INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Zu Anbeginn hat Gott erschaffen den Himmel und die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Die Erde aber war wüst und wirr, und auf der Urflut lag Finsternis. Gottes Geist aber schwebte über den Gewässern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Da sprach Gott: \"Licht werde!\" Und Licht ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah: Das Licht war gut. So schied Gott zwischen Licht und Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Und Gott bestimmte für das Licht den Tag. Und für die Finsternis bestimmte er die Nacht. So ward Abend und ward Morgen. Ein Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: \"Mitten in den Wassern sei eine Feste! Sie scheide zwischen Wasser und Wasser!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'So machte Gott die Feste und schied zwischen dem Wasser unter der Feste und dem Wasser über der Feste. Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Der Feste sprach Gott den Himmel zu. So ward Abend und ward Morgen. Ein zweiter Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: \"An einem Orte sammle sich das Wasser unterm Himmel, und das Trockene erscheine!\" Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Für das Trockensein bestimmte Gott die Erde, und für die Sammlung der Wasser bestimmte er die Meere. Und Gott sah: Gut war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: \"Sprießen lasse die Erde Grünes! Samentragendes Kraut und Fruchtbäume, nach ihrer Art Früchte tragend, darin ihr Same für die Erde!\" Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Die Erde brachte Grünes, Kraut mit Samen je nach seiner Art und Bäume mit Früchten, darin ihr Same je nach ihrer Art. Und Gott sah: Gut war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'So ward Abend und ward Morgen. Ein dritter Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: \"Leuchten seien an der Himmelsfeste, zwischen Tag und Nacht zu scheiden! Dann dienen sie zu Zeichen und Gezeiten, zu Tagen und Jahren');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und zu Leuchten an der Himmelsfeste, die Erde zu bescheinen.\" Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'So machte Gott die zwei großen Leuchten, die größere Leuchte zum Walten über den Tag und die kleinere Leuchte zum Walten über die Nacht, und die Sterne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott ließ sie an der Himmelsfeste auf die Erde scheinen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'über den Tag und die Nacht walten und zwischen dem Licht und der Finsternis scheiden. Und Gott sah: Gut war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'So ward Abend und ward Morgen. Ein vierter Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: \"Das Wasser wimmle von lebendem Gewimmel, und auf Erden an der Himmelsfeste fliege Geflügel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'So schuf Gott die großen Meerestiere und alle anderen lebenden Wimmelwesen, wovon die Wasser wimmeln, nach ihren Arten und der beschwingten Vögel jegliche Art. Und Gott sah: Gut war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Da segnete Gott sie und sprach: \"Seid fruchtbar! Mehret euch! Füllet der Meere Gewässer! Auf Erden mehre sich das Geflügel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'So ward Abend und ward Morgen. Ein fünfter Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach:\"Die Erde zeuge Lebewesen je nach ihrer Art! Vieh, Gewürm und das Wild der Erde!\" Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'So machte Gott das Wild der Erde nach seiner Art, das Vieh nach seiner Art und alles Gewürm des Bodens nach seiner Art. Und Gott sah: Gut war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach. \"Lasset uns Menschen machen als unser Bild nach unserem Gleichnis! Herrschen sollen sie über des Meeres Fische, über des Himmels Vögel, über das Vieh auf der ganzen Erde überall und über alle Wimmelwesen, die auf Erden wimmeln!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen als sein Bild. Als Gottes Bild schuf er ihn. Er schuf sie als Mann und als Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie. Und Gott sprach zu ihnen: \"Seid fruchtbar! Mehret euch! Füllet die Erde! Macht sie euch untertan! Herrschet über des Meeres Fische, über des Himmels Vögel und über alle Lebewesen, die auf Erden wimmeln!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: \"Euch überlasse ich alles samentragende Kraut auf der ganzen Erde und alle Bäume mit samentragender Baumfrucht, daß sie euch zur Nahrung diene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Und alles andere grüne Kraut diene zur Nahrung allem Wilde, allen Vögeln des Himmels und allem Gewürm auf Erden, in dem Lebensgeist ist.\" Und so ward es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah alles, was er gemacht hatte. Und sehr gut war es. So ward Abend und ward Morgen. Ein sechster Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'So wurden vollendet der Himmel und die Erde und all ihre Vielfalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Da feierte Gott am siebten Tage von seiner Arbeit, die er getan. Und er ruhte am siebten Tage ganz von seiner Arbeit, die er getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'So segnete Gott den siebten Tag und weihte ihn. Denn an ihm hatte er völlig von seiner Arbeit geruht, die Gott zu tun geplant hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dies ist die Entstehung des Himmels und der Erde, als sie erschaffen worden sind. Damals, als der Herr Gott Erde und Himmel gemacht hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'war kein Feldgesträuch im Lande, und kein Feldgewächs sproßte; denn der Herr Gott hatte dem Lande noch keinen Regen gegeben. Auch waren keine Menschen da, die den Erdboden bebaut hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Und eine Wasserflut stieg von der Erde auf und tränkte des Erdbodens ganze Fläche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Da bildete der Herr Gott den Menschen aus Staub vom Boden und blies ihm Lebensodem in die Nase. So ward der Mensch zu einem Lebewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Nun hatte der Herr Gott im Osten einen Garten in Eden gepflanzt; dort ließ er nun den Menschen sein, den er gebildet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Allerlei Bäume, lieblich zur Schau und köstlich als Speise, hatte der Herr Gott aus dem Erdboden sprießen lassen, in des Gartens Mitte aber den Baum des Lebens und den Baum der Erkenntnis von Gut und Bös.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und ein Fluß kam von Eden her, den Garten zu bewässern; er aber war von da ab geteilt und zu vier Häuptern geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Pischon heißt der erste, der das ganze Sandland umfließt, wo das Gold ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Fein ist das Gold dieses Landes; dort gibt es auch Harztränen (Bdellium) und Onyxstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Und der zweite Strom heißt Gichon, der das ganze Land Kusch umfließt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Der dritte Strom heißt Tigris, der östlich von Assur vorüberfließt. Der vierte Strom ist der Euphrat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Der Herr Gott nahm also den Menschen und setzte ihn in Edens Garten, daß er ihn bebaue und pflege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und der Herr Gott gebot dem Menschen und sprach: \"Von allen Bäumen im Garten darfst du nach Belieben essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Nur von dem Baume, der Gutes und Böses keimen lehrt, darfst du nicht essen. Denn sobald du von ihm issest, bist du des Todes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und der Herr Gott sprach: \"Nicht gut ist es, daß der Mensch allein sei; ich will ihm eine Gehilfin schaffen, die ihm gleichgeartet ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Nun formte der Herr Gott aus dem Erdboden alle Tiere des Feldes und alle Vögel des Himmels. Diese brachte er zum Menschen, um zu sehen, wozu er sie bestimmte, und genau das wozu er ein Lebewesen bestimmte, sollte seine Bestimmung sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Und so gab der Mensch allem Vieh und des Himmels Vögeln und allem Wilde eine Bestimmung; aber für einen Menschen hatte keines als Beistand gepaßt, ihm gleichgeartet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da ließ der Herr Gott einen Tiefschlaf auf den Menschen sinken, und als dieser eingeschlafen, nahm er eine seiner Rippen und füllte ihre Lücke mit Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Dann baute der Herr Gott die Rippe, die er vom Menschen genommen, zu einem Weibe aus und brachte sie zum Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sprach der Mensch: \"Diesmal ist es Bein von meinem Bein und Fleisch von meinem Fleisch. Deshalb heißt sie Weib, weil sie vom Manne genommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum läßt ein Mann Vater und Mutter und hängt sich an sein Weib, und sie werden Ein Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Die beiden aber, der Mensch und sein Weib, waren nackt; aber sie schämten sich nicht voreinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Die Schlange aber ist schlauer gewesen, als des Feldes Tiere alle, die der Herr Gott gemacht hat. Und so sprach sie zu dem Weibe: \"Daß doch Gott gesprochen haben soll: Ihr dürft von keinem Baum des Gartens essen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da sprach das Weib zur Schlange: \"Wir dürfen von der Frucht der Bäume im Garten essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Nur von der Frucht des Baumes mitten im Garten sprach Gott: \'Davon dürft ihr nicht essen, ja nicht einmal daran rühren, sonst müßt ihr sterben.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Die Schlange sprach zum Weibe: \"Ihr werdet gewiß nicht sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Nein! Gott weiß: Sobald ihr davon esset, gehen euch die Augen auf, und ihr seid wie Gott, erkennend Gutes und Böses.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Da sah das Weib: Der Baum war köstlich zum Speisen und Wollust den Augen, und berückend war der Baum, um zur Erkenntnis zu gelangen. So nahm sie von seiner Frucht und aß. Dann gab sie ihrem Manne bei ihr. Auch er aß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da gingen beiden die Augen auf, und sie erkannten, daß sie nackt waren. Und sie flochten Feigenlaub und machten sich Schürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Da hörten sie das Geräusch des Herrn Gottes, der sich im Garten beim Tageswinde erging. Und der Mensch verbarg sich mit seinem Weibe vor dem Herrn Gott unter den Bäumen des Gartens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Der Herr Gott aber rief den Menschen und fragte ihn: \"Wo bist du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Er sprach: \"Ich habe dein Geräusch im Garten gehört; da erschrak ich, weil ich nackt bin, und so verbarg ich mich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Er sprach: \"Wer hat dir verraten, daß du nackt bist? Hast du von dem Baume gegessen, von dem zu essen ich dir verboten habe?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Da sprach der Mensch: \"Das Weib, das du mir beigesellt, hat mir vom Baume gegeben; da aß ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sprach der Herr Gott zu dem Weibe: \"Was hast du getan?\" Und das Weib sprach: \"Die, Schlange hat mich verführt; da aß ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sprach der Herr Gott zu der Schlange: \"Weil solches du getan, bist du verflucht, mehr als alles Vieh und alles Wild. Auf deinem Bauche sollst du kriechen und Staub dein Lebtag fressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und Feindschaft will ich setzen zwischen dich und das Weib und zwischen deinen, Stamm und ihren Stamm; zermalmen wird er dir den Kopf, willst du ihn in die Ferse stechen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Zum Weibe aber sprach er: \"Vermehren will ich deine Mühsal bei deiner Schwangerschaft. In Mühen sollst du Kinder gebären, und doch geht dein Verlangen hin nach deinem Manne, obschon er waltet über dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zu Adam sprach er: \"Weil du auf deines Weibes Stimme hast gehört und von dem Baum gegessen, von dem ich dir geboten: \'Du darfst davon nicht essen\', so ruht der Fluch um deinetwillen auf dem Acker. In Mühsal sollst du dich dein Leben lang von ihm ernähren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dir soll er Dorn und Distel tragen, und doch mußt du das Kraut des Feldes essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiße deines Angesichts wirst du dein Brot verzehren, bis du zur Erde wiederkehrst, wie du von ihr genommen bist. Denn Staub bist du und kehrst zum Staube wieder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Da gab der Mensch seinem Weibe den Namen \"Eva\"; weil sie aller Lebenden Mutter werden sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und der Herr Gott machte Adam und seinem Weib Fellröcke und hüllte sie darein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Dann sprach der Herr Gott: \"Ja, der Mensch ist jetzt wie unsereiner im Erkennen von Gutem und Bösem. Daß er nicht seine Hand ausstrecke und gar vom Lebensbaume esse und ewig lebe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'So trieb ihn der Herr Gott aus Edens Garten, damit er den Erdboden bebaue, aus dem er genommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'So verstieß er den Menschen und lagerte östlich von Edens Garten Cherube und die zuckende Schwertflamme, um den Weg zum Lebensbaum zu bewachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Der Mensch aber hatte sein Weib Eva erkannt. Da empfing sie und gebar Kain. Da sprach sie: \"Ich habe mit des Herrn Beistand einem Manne das Leben gegeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und zum zweitenmal gebar sie seinen Bruder Abel. Und Abel ward ein Schafhirte; Kain aber war Ackersmann geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Nach einiger Zeit geschah es, daß Kain von den Ackerfrüchten dem Herrn ein Opfer brachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Auch Abel brachte ein Opfer von den Erstlingswürfen seiner Schafe dar, und zwar von den wohlgenährtesten. Und der Herr achtete auf Abel und sein Opfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Aber auf Kain und sein Opfer achtete er nicht. Da ward Kain sehr ergrimmt, und sein Antlitz sank ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Da sprach der Herr zu Kain: \"Warum bist du ergrimmt? Weswegen sinkt dein Antlitz ein?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Nicht wahr? Bist frohen Sinnes du, dann kannst du es erheben. Wenn aber nicht, dann ruhst du an der Sünde Pforte; da lauert sie auf dich, du aber solltest sie bezwingen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Kain aber sprach mit seinem Bruder Abel, und da sie auf dem Felde waren, vergriff sich Kain an seinem Bruder Abel und schlug ihn tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sprach der Herr zu Kain: \"Wo ist dein Bruder Abel?\" Er sprach:\"Ich weiß es nicht. Bin ich denn meines Bruders Hüter?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Da sprach er: \"Was hast du getan? Deines Bruders Blut schreit von der Erde auf zu mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Nun sei verflucht! Fern von dem Boden, der den Mund geöffnet, um deines Bruders Blut aus deiner Hand zu trinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Bebauest du den Boden, so gebe er dir fortan keine Ernte! Durchziehe irr und wirr die Erde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Da sprach Kain zum Herrn: \"Allzugroß für das Vergeben ist meine Schuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'So vertreibst du mich heute vom Ackerboden. Und vor deinem Angesichte muß ich mich verbergen. Irr und wirr muß ich die Erde durchwandern. Und wer mich trifft, kann mich erschlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Da sprach der Herr zu ihm: \"Nein! Wer den Kain erschlägt, verfalle der Rache siebenfachmal.\" Und der Herr machte Kain ein Zeichen, auf daß ihn keiner, der ihn träfe, erschlüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'So zog Kain vom Herrn hinweg und siedelte im Lande Nod, östlich von Eden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain erkannte sein Weib, und sie empfing und gebar Henoch. Dann baute er eine Stadt und hieß die Stadt nach seines Sohnes Namen Henoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Dem Henoch ward Irad geboren, und Irad zeugte Mechujael und Mechujael Metusael und Metusael Lamech.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Und Lamech nahm sich zwei Weiber: die eine hieß Ada, die andere Silla.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada gebar den Jabal; dieser ward der Stammvater der Zeltbewohner und Viehzüchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Sein Bruder hieß Jubal; dieser ward der Stammvater aller Zither- und Flötenspieler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Auch Silla gebar und zwar den Tubalkain, der allerlei ehernes und eisernes Werk schmiedete. Und Tubalkains Schwester war Naama.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lamech sprach zu seinen Weibern: \"Ada und Silla, höret meine Rede! Lamechs Weiber, vernehmet meinen Spruch! Für meine Wunde kann ich Männer jetzt erschlagen, für meine Beulen ihre Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Wird Kain schon siebenfach gerächt, dann Lamech siebenundsiebzigfach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam aber erkannte wiederum sein Weib, und sie gebar einen Sohn. Den nannte sie Set. \"Denn\", sprach sie, \"Gott hat mir an Abels Stelle andere Nachkommen geschenkt, weil jenen Kain erschlagen hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Aber auch dem Set ward ein Sohn geboren, und er hieß ihn Enos. Damals begann man, des Herrn Namen anzurufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Das ist die Urkunde der Geschlechterfolge Adams: Damals, als Gott den Adam schuf, machte er ihn in Gottes Ähnlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Männlich und weiblich schuf er sie. Dann segnete er sie und hieß sie \"Mensch\", damals, als sie geschaffen worden waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Und Adam war 130 Jahre alt; da zeugte er in seiner Ähnlichkeit nach seinem Bild einen Sohn und hieß ihn Set.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Der Tage Adams waren es nach Sets Zeugung 800 Jahre und er zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Und aller Tage Adams waren 930 Jahre. Da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set war 105 Jahre alt; da zeugte er Enos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Und Set lebte nach des Enos Zeugung 807 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Und aller Tage Sets waren 912 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos war 90 Jahre alt; da zeugte er Kenan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Und Enos lebte nach Kenans Zeugung 815 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Und aller Tage des Enos waren 905 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Und Kenan war 70 Jahre alt; da zeugte er Mahalalel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Und Kenan lebte nach Mahalalels Zeugung 840 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Und aller Tage Kenans waren 910 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Und Mahalalel war 65 Jahre alt; da zeugte er Jered.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Und Mahalalel lebte nach Jereds Zeugung 830 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Und aller Tage Mahalalels waren 895 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Und Jered war 162 Jahre alt; da zeugte er Henoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Und Jered lebte nach Henochs Zeugung 800 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Und aller Tage Jereds waren 962 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Und Henoch war 65 Jahre alt; da zeugte er Metuselach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Nach Metuselachs Zeugung wandelte Henoch mit Gott 300 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Und aller Tage Henochs waren 365 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und Henoch wandelte mit Gott, und plötzlich war er nicht mehr da, weil ihn Gott weggenommen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Und Metuselach war 187 Jahre alt; da zeugte er Lamech.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Und Metuselach lebte nach Lamechs Zeugung 782 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Und aller Tage Metuselachs waren 969 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Und Lamech war 182 Jahre alt; da zeugte er einen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Und er hieß seinen Sohn Noe und sprach: \"Dieser soll uns Trost bringen, nach unserer Arbeit und unserer Hände Mühen, aus eben diesem Boden, den der Herr verflucht hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Und Lamech lebte nach Noes Zeugung 595 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Und aller Tage Lamechs waren 777 Jahre; da starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Und Noe war 500 Jahre alt; da zeugte Noe Sem, Cham und Japhet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Als die Menschen angefangen hatten, sich auf dem Erdboden zu mehren, waren ihnen Töchter geboren worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Da sahen die Göttersöhne, daß die Menschentöchter schön waren, und sie nahmen sich zu Weibern, soviel sie wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sprach der Herr: \"Mein Geist verbleibe nimmer länger bei den Menschen! Er ist ja nur mehr Fleisch! Nur noch auf 120 Jahre sollen seine Tage sich belaufen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'In jenen Zeiten waren die Riesen auf Erden gewesen, zumal damals, als die Göttersöhne mit den Menschentöchtern verkehrten und diese ihnen Kinder gebaren. Jenes sind die Recken der Urzeit, die Männer von Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Da sah der Herr, daß die Bosheit der Menschen auf Erden groß ward und alles Dichten und Trachten ihres Herzen allezeit böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Da reute es den Herrn, daß er die Menschen auf Erden gemacht, und er ward tief bekümmert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Darauf sprach der Herr: \"Vertilgen von der Erde werde ich die Menschen, die ich erschaffen habe, vom Menschen bis zum Vieh, bis zum Gewürm und zu des Himmels Vögeln; denn ich bereue, sie gemacht zu haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noe aber hatte Huld in des Herrn Augen gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist Noes Geschlechterfolge: Noe war ein gerechter, unsträflicher Mann unter seinen Zeitgenossen gewesen. Noe wandelte mit Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noe zeugte drei Söhne: Sem, Cham und Japhet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Die Erde aber war vor Gottes Angesicht verderbt, und die Erde füllte sich mit Frevel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Und Gott sah, wie die Erde verderbt war; denn jedes Fleischwesen hatte seinen Wandel auf Erden verderbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sprach Gott zu Noe. \"Das Ende jedes Fleischwesens ist von mir verhängt; die Erde ist ja voller Frevel, die sie tun. Und so verderbe ich sie samt der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mach eine Arche dir aus Fichtenholz! Und zu Behausungen sollst du die Arche einbauen! Und dann verpiche sie mit Harz von außen und von innen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Also sollst du sie machen: 300 Ellen sei der Arche Länge und 50 Ellen ihre Breite und 30 Ellen ihre Höhe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Und an der Arche sollst du eine Luke machen und bis auf eine Elle sie ganz oben anbringen, alsdann der Arche Tor in eine ihrer Längsseiten einsetzen und sie in untere und mittlere und obere Stockwerke einteilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ich lasse jetzt die Wasserflut auf Erden kommen, um alles Fleisch, das unterm Himmel, zu vertilgen, darinnen Lebensodem ist. So möge alles, was auf Erden, sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mit dir nun treffe ich mein Abkommen, und so gehst du samt deinen Söhnen, deinem Weibe und deinen Schwiegertöchtern in die Arche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Von allem Lebenden, von jedem Fleischeswesen, sollst du je ein Paar mit in die Arche bringen, um sie bei dir am Leben zu erhalten! Nur je ein Männchen und ein Weibchen soll es sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'So von den Vögeln je nach ihrer Art, vom Vieh nach seiner Art, von allem, was auf Erden kriecht, nach seiner Art. Davon soll immer je ein Pärchen zu dir kommen, daß sie am Leben bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Du selbst beschaffe dir von jeglicher eßbaren Speise, und speichere solches bei dir auf! Zur Nahrung dient es alsdann dir und ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noe tat so. Ganz so, wie ihm Gott befohlen hatte, tat er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Dann sprach der Herr zu Noe: \"Zieh du mit deinem ganzen Hause in die Arche! Denn dich habe ich gerecht vor mir in diesem Geschlecht erfunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Von allen reinen Tieren nimm dir je sieben, jeweils ein Männchen und ein Weibchen! Doch von den Tieren, die nicht rein, jeweils nur zwei, ein Männchen und ein Weibchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Auch von des Himmels Vögeln jeweils sieben, ein männliches und weibliches, um auf der ganzen Erde einen Stamm am Leben zu erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Von jetzt ab über sieben Tage lasse ich auf die Erde regnen durch vierzig Tage und durch vierzig Nächte, und ich vertilge alsdann alles Lebende, das ich gemacht, vom Erdboden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noe tat ganz so, wie ihn der Herr geheißen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noe aber war 600 Jahre alt geworden, als die Wasserflut über die Erde kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'So ging Noe mit seinen Söhnen, seinem Weibe und seinen Schwiegertöchtern in die Arche vor den Wassern der Flut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von den reinen und unreinen Tieren, von den Vögeln und von allem, was auf Erden kriecht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'waren paarweise zu Noe in die Arche gegangen je ein Männliches und ein Weibliches, wie Gott dem Noe geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Nach sieben Tagen geschah es, da waren die Wasser der Flut schon über die Erde gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im 600. Lebensjahre des Noe, am 17. Tage des 2. Monats, an diesem Tage brachen alle Sprudel des großen Meeres auf, und die Himmelsluken öffneten sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Und Regen strömte auf die Erde 40 Tage und 40 Nächte lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An eben diesem Tage waren Noe und Noes Söhne Sem, Cham und Japhet, sowie sein Weib und seine drei Schwiegertöchter mit ihnen in die Arche gegangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'sie und alle Tiere nach ihrer Art und alles Vieh nach seiner Art und alles Gewürm, das auf Erden kriecht, nach seiner Art und alle Vögel nach ihrer Art, was irgendwie Flügel hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Sie gingen zu Noe in die Arche, je ein Paar von allem Fleisch mit Lebensodem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Die Einziehenden waren nun, je ein Männliches und Weibliches von jedem Fleische, eingezogen, so wie ihm Gott befohlen. Da schloß der Herr hinter ihm zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Vierzig Tage kam die Flut über die Erde. Und das Wasser wuchs und hob die Arche, daß sie über der Erde schwebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und das Wasser stieg und wuchs gewaltig an auf Erden, und die Arche fuhr auf dem Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Das Wasser stieg nun in gewaltiger Höhe über die Erde, und alle hohen Berge irgendwo unter dem Himmel wurden bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen darüber hinaus war das Wasser gestiegen; so wurden die Berge bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da starb ein jeglich Fleisch, das sich auf Erden regte, an Vögeln, Vieh und Getier und an allem Gewürm, das auf Erden kroch, sowie alle Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alles, was des Lebensgeistes Odem in seiner Nase hatte, soweit es sich auf dem Trockenen befand, war tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'So vertilgte er alle Wesen auf dem Erdboden, vom Menschen bis zum Vieh und Gewürm und bis zu des Himmels Vögeln. Sie wurden von der Erde vertilgt; nur Noe und was bei ihm in der Arche war, blieb übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und das Wasser wuchs auf Erden 150 Tage lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da gedachte Gott des Noe und all des Getieres und all des Viehs bei ihm in der Arche. Und Gott ließ einen Wind über die Erde wehen, und das Wasser sank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Dann schlossen sich des Meeres Sprudel und die Himmelsluken, und dem Regen vom Himmel ward gewehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Und das Wasser ging allmählich zurück auf Erden, und nach Ablauf der 150 Tage minderte sich das Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Und die Arche ließ sich am 17. Tage des 7. Monats auf dem Araratgebirge nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Das Wasser aber hatte immer mehr abgenommen, bis zum 10. Monat. Am 1. Tag des 10. Monats waren die Spitzen der Berge sichtbar geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Nach Ablauf von 40 Tagen öffnete Noe das Fenster der Arche, das er gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Und er schickte den Raben aus. Dieser flog hin und her, bis das Wasser auf Erden vertrocknet war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Dann ließ Noe die Taube von sich fortfliegen, zu sehen, ob sich das Wasser verlaufen hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Die Taube aber fand keine Stätte für ihren Fuß. So kam sie zu ihm wieder in die Arche; denn auf der ganzen Erde war noch Wasser. Und er streckte seine Hand aus und nahm sie und brachte sie zu sich in die Arche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Da wartete er noch sieben weitere Tage. Dann sandte er zum zweitenmal die Taube aus der Arche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Da kam die Taube zu ihm zur Abendzeit mit einem frischen Ölblatt im Schnabel. Da erkannte Noe, daß sich das Wasser von der Erde verlaufen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Und er wartete noch weitere sieben Tage; dann ließ er die Taube wieder ausfliegen. Diesmal aber kehrte sie nicht mehr zu ihm zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Im 601. Jahre, am ersten Tage des ersten Monats, waren die Wasser auf Erden vertrocknet. Da hob Noe das Dach der Arche und schaute aus, und siehe da, der Erdboden war wasserfrei geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Am 27. Tage des zweiten Monats war die Erde ganz abgetrocknet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Und Gott sprach zu Noe:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '\"Geh aus der Arche, du selbst, dein Weib, deine Söhne und deine Schwiegertöchter bei dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Und alles Getier, das bei dir ist, von jedem Fleisch, an Vögeln, Vieh und jeglichem Gewürm, das auf Erden kriecht, führe du mit dir hinaus! Dann wimmle es auf Erden und sei fruchtbar auf Erden und mehre sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Da ging Noe hinaus, seine Söhne, sein Weib und seine Schwiegertöchter bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alles Getier, alles Gewürm, alle Vögel, alles, was sich auf Erden regt nach seinen Sippen, ging aus der Arche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Und Noe baute dem Herrn einen Altar und nahm von allen reinen Tieren und reinen Vögeln einige und brachte auf dem Altar Brandopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Da roch der Herr den süßen Duft. Und der Herr sprach bei sich: \"Nicht will ich fortan mehr dem Boden fluchen des Menschen wegen. Der Menschen Herzenstrachten ist böse ja von Jugend auf. Hinfort will ich kein Lebewesen mehr so schlagen, wie ich\'s getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Fortan soll nimmer feiern, solange auch die Erde steht, die Saat mitsamt der Ernte und Frost und Hitze, der Sommer und der Winter und Tag und Nacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Und Gott segnete Noe und seine Söhne und sprach zu ihnen: \"Seid fruchtbar, mehret euch und füllt die Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Und Furcht vor euch und Schrecken komme über alle Landtiere und alle Himmelsvögel und über alles, was sich auf dem Boden regt, und über alle Meeresfische; in eure Hand sind sie gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich regt und lebt, sei euch zur Speise! So wie das grüne Kraut, so gebe ich euch alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur Fleisch mit seinem Lebensblut sollt ihr nicht essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Und vollends euer eigen Blut will ich zurückverlangen; von jedem Tiere will ich\'s fordern; auch von des Menschen Hand, von seines Bruders Hand will ich das Menschenleben fordern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergießt, des Blut soll durch die Menschen auch vergossen werden! Als Gottesbild hat er die Menschen ja gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ihr, seid nun fruchtbar, mehret euch! Verbreitet euch auf Erden! Herrscht über sie!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Und Gott sprach zu Noe und seinen Söhnen bei ihm also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '\"Ich schließe meinen Bund mit euch und euren Nachkommen und mit allen Lebewesen bei euch, was an Vögeln, Vieh und allen anderen Tieren auf Erden bei euch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'mit all denen, die aus der Arche kamen, und allem Getier der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ja, meinen Bund errichte ich mit euch; kein Fleischeswesen werde durch der Flut Gewässer mehr vertilgt, und niemals wieder komme eine Flut, die Erde zu verheeren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: \"Dies sei des Bundes Zeichen, den ich aufrichte zwischen mir und euch und allen Lebewesen, die bei euch, für ewige Zeiten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Ich stelle meinen Bogen in die Wolken. Er sei das Bundeszeichen zwischen mir und dieser Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Und wölke ich Gewölke ob der Erde, und im Gewölk erscheint der Bogen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'alsdarin gedenke ich des Bundes, der zwischen mir und euch und allen anderen Fleischeswesen, die da leben, gilt auf Erden. Nie wird das Wasser wieder eine Flut, die allem Fleische das Verderben brächte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Und steht der Bogen im Gewölke, dann schaue ich ihn an und denke an den ewigen Bund, der zwischen Gott und allen Fleischeswesen, die da leben, gilt auf Erden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noe: \"Dies ist des Bundes Zeichen, den ich errichtet habe zwischen mir und jedem Fleisch auf Erden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Noes Söhne, die aus der Arche gingen, waren Sem, Cham und Japhet; Cham aber war Kanaans Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Diese drei waren Noes Söhne, und ihnen entsprang die ganze Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noe aber begann mit dem Landbau und pflanzte einen Weinberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Da trank er von dem Wein, ward betrunken und lag entblößt in seinem Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Da schaute Cham, der Vater Kanaans, die Blöße seines Vaters und sagte es seinen beiden Brüdern draußen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Sem und Japhet aber nahmen das Obergewand, legten es auf ihre Schultern, gingen rückwärts hinein und bedeckten ihres Vaters Blöße; ihr Gesicht aber war abgewandt, und so hatten sie ihres Vaters Blöße nicht gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als Noe von seinem Wein erwachte, erfuhr er, was ihm sein jüngster Sohn getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Da sprach er: \"Verflucht sei Kanaan! Der niedrigste der Sklaven sei er seinen Brüdern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und er sprach: \"Des Herrn Gesegneter, mein Gott, sei Sem! Doch Kanaan sei ihm Sklave!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Für Japhet schaffe Gott gar weiten Raum! In Zelten aber wohne Sem! Und Kanaan sei ihm Sklave!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Und Noe lebte nach der Flut 350 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Und die ganze Lebensdauer Noes betrug 950 Jahre; dann starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Und dies ist die Geschlechterfolge der Söhne Noes: Noes Söhnen Sem, Cham und Japhet wurden nach der Flut Söhne geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Japhets Söhne waren Gomer, Magog, Madai, Javan, Tubal, Mesek und Tiras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Gomers Söhne waren Askenaz, Riphat und Togarma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Javans Söhne waren Elisa, Tarsis, Kittim und Dodanim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen hatten sich der Heiden Inseln abgezweigt nach ihren Ländern, ihren verschiedenen Sprachen, Stämmen und Völkerschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Chams Söhne waren Kusch, Misraim, Put und Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Des Kusch Söhne waren Saba, Chavila, Sabta, Regma und Sabteka, und Regmas Söhne waren Scheba und Dedan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Und Kusch hatte Nimrod gezeugt; dieser war zuerst ein Kriegsheld auf Erden gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Er war ein gewaltiger Jäger vor dem Herrn; daher pflegt man zu sagen: \"Gleich Nimrod ist er ein gewaltiger Jäger vor dem Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Seine Herrschaft erstreckte sich anfangs auf Babel, Erech, Akkad und Kalne im Lande Sinear.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog er nach Assur; da baute er Ninive - dazu Rechobot-Ir und Kelach');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'sowie Resen zwischen Ninive und Kelach -, das ist die große Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Und Misraim zeugte die Luditer, Anamiter, Lehabiter und Naphtuchiter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'sowie die Patrusiter und Kasluchiter und die, von denen die Philister stammten, die Kaphtoriter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan zeugte Sidon, seinen Erstgeborenen, und Chet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'sowie die Jebusiter, Amoriter und Girgasiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Chiviter, Arkiter, Siniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvaditer, Semariter und Chamatiter; hernach breiteten sich die Kanaaniterstämme aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Das Kanaanitergebiet erstreckte sich von Sidon bis nach Gerar, Gaza, Sodoma, Gomorrha, Adma. Seboim und Lesa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dies sind Chams Söhne nach ihren Stämmen, Sprachen, Ländern und Völkerschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Auch Sem, dem Stammvater aller Söhne Ebers und ältesten Bruder Japhets, wurden Kinder geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Sems Söhne waren Elam, Assur, Arpaksad, Lud und Aram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Arams Söhne waren Uz, Chul, Geter und Masch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Und Arpaksad zeugte Selach und Selach den Eber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Dem Eber wurden zwei Söhne geboren; der eine hieß Peleg, weil sich zu seiner Zeit die Erde gespalten hatte; sein Bruder hieß Joktan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Joktan zeugte Almodad, Seleph, Chasarmavet, Jerach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uzal, Dikla,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Scheba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Chavila und Jobab: dies alles sind Joktans Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Ihre Wohnsitze reichten von Mesa bis Sephar beim Ostgebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dies sind die Söhne Sems nach ihren Stämmen, Sprachen, Ländern und Völkerschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Dies sind die Stämme der Noesöhne nach ihren Sippen und Völkerschaften; von ihnen haben sich nach der Flut die Völker auf Erden abgesondert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Die ganze Erde aber hatte eine Sprache und einerlei Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Als sie von Osten herzogen, fanden sie im Lande Sinear eine Ebene und ließen sich darin nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen zueinander: \"Auf! Laßt uns Luftziegel streichen und Backsteine brennen!\" Und der Ziegel diente ihnen als Baustein; das Erdpech aber hatte ihnen als Mörtel gedient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Sie sprachen: \"Auf! Bauen wir uns eine Stadt und einen Turm mit einer Spitze bis zum Himmel, und machen wir uns eine Wohnstatt, daß wir uns nicht über die ganze Erde zerstreuen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Der Herr aber stieg herab, die Stadt und den Turm zu beschauen, den die Menschenkinder gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Da sprach der Herr: \"Fürwahr! Ein Volk sind sie und haben alle dieselbe Sprache, und dies ist nur der Anfang ihres Tuns, und fortan wäre ihnen nichts verwehrt, was immer sie nur planen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Auf nun! Wir wollen jetzt hinab und ihre Sprache mischen, daß keiner je des anderen Sprache mehr verstehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'So zerstreute sie der Herr von dort über die ganze Erde, und sie mußten es lassen, die Stadt auszubauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Darum nennt man sie Babel; denn dort hat der Herr die Sprache der ganzen Erde gemischt, und von dort hat der Herr sie über die ganze Erde zerstreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies ist die Geschlechterfolge Sems: Als Sem 100 Jahre alt war, zeugte er Arpaksad, zwei Jahre nach der Flut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Und Sem lebte nach Arpaksads Zeugung 500 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Und Arpaksad war 35 Jahre alt; da zeugte er Selach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Und Arpaksad lebte nach Selachs Zeugung 403 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Und Selach war 30 Jahre alt; da zeugte er Eber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Und Selach lebte nach Ebers Zeugung 403 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Und Eber war 34 Jahre alt, da zeugte er Peleg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Und Eber lebte nach Pelegs Zeugung 430 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Und Peleg war 30 Jahre alt; da zeugte er Rëu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Und Peleg lebte nach Rëus Zeugung 209 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Und Rëu war 32 Jahre alt; da zeugte er Serug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Und Rëu lebte nach Serugs Zeugung 207 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Und Serug war 30 Jahre alt; da zeugte er Nachor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Und Serug lebte nach Nachors Zeugung 200 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Und Nachor war 29 Jahre alt; da zeugte er Terach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Und Nachor lebte nach Terachs Zeugung 119 Jahre und zeugte noch Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Und Terach war 70 Jahre alt; da zeugte er Abram, Nachor und Haran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Dies ist die Geschlechterfolge Terachs: Terach zeugte Abram, Nachor und Haran, und Haran zeugte Lot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Es starb aber Haran zu Lebzeiten seines Vaters Terach, in seinem Geburtslande zu Ur Kasdim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram und Nachor nahmen sich dann Weiber; Abrams Weib hieß Sarai und Nachors Weib Milka, die Tochter Harans, des Vaters von Milka und Iska.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai aber war unfruchtbar; sie hatte nie ein Kind geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Und Terach nahm seinen Sohn Abram und seinen Enkel Lot, den Sohn Harans, und seine Schwiegertochter Sarai, das Weib seines Sohnes Abram, und sie zogen mit ihm aus Ur Kasdim, ins Land Kanaan zu wandern. So kamen sie bis Charan; hier aber ließen sie sich nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Die Tage Terachs beliefen sich auf 205 Jahre; dann starb Terach zu Charan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Und der Herr sprach zu Abram: \"Aus deinem Lande, deiner Sippe zieh fort, aus deinem Vaterhause, ins Land, das ich dir zeigen werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'ich mache dich zu einem großen Volke und segne dich und mache deinen Namen hochberühmt, daß du zum Segen werdest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Denn segnen will ich, die dich segnen, und die verfluchen, die dich lästern. Der Erde Stämme alle sollen sich mit dir dann segnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Und Abram zog fort, wie ihm der Herr gesagt, und mit ihm zog Lot; Abram aber war 75 Jahre alt, als er von Charan fortzog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Und Abram nahm sein Weib Sarai und seinen Brudersohn Lot und all ihre Habe, die sie erworben, sowie die Seelen, die sie in Charan bekommen hatten, und sie zogen fort, ins Land Kanaan zu wandern, und sie kamen auch in das Land Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Und Abram durchzog das Land bis zu Sichems Wohnsitz, bis zum Maulbeerbaum; damals aber waren die Kanaaniter im Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien der Herr dem Abram und sprach: \"Ich gebe deinem Stamme dieses Land.\" Da baute er dort einen Altar dem Herrn, der ihm erschienen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Von dort zog er auf das Gebirge östlich von Betel und schlug sein Zelt auf, Betel im Westen und Ai im Osten. Dort baute er dem Herrn einen Altar und rief des Herrn Namen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Dann zog Abram weiter und weiter, dem Südland zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Nun kam die Hungersnot ins Land, und Abram zog nach Ägypten, hier zu verbleiben; denn schwer lag die Hungersnot auf dem Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Als er nahe bei Ägypten war, sprach er zu seinem Weib Sarai: \"Ich weiß wohl, daß du ein schönes Weib bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Sehen dich nun die Ägypter, dann denken sie: Dies ist sein Weib, und alsdann töten sie mich; dich aber werden sie am Leben lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sag doch, du seiest meine Schwester, daß es mir um deinetwillen gut gehe. Dann bleibe ich deinetwegen ungefährdet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als Abram nach Ägypten kam, sahen die Ägypter, daß das Weib überaus schön war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Auch des Pharao Fürsten sahen sie und rühmten sie vor Pharao. So ward das Weib in Pharaos Haus geholt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Dem Abram aber war er ihretwegen hold geworden; und so bekam er Schafe, Rinder, Esel, Sklaven, Mägde, Eselinnen und Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Der Herr aber schlug mit schweren Plagen Pharao und sein Haus wegen Sarai, des Weibes Abrams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da ließ Pharao den Abram rufen und sprach: \"Was hast du mir da angetan? Warum hast du mir verhehlt, daß sie dein Weib ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum hast du gesagt: \'Sie ist nur meine Schwester\'? Und so nahm ich sie mir zum Weib. Nun aber sieh, hier ist dein Weib! Nimm sie und geh fort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und Pharao entbot seinetwegen Leute, daß sie ihn, sein Weib und all seine Habe fortschafften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Abram zog nun von Ägypten aufwärts, er, sein Weib und all seine Habe, auch Lot mit ihm, ins Südland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram war sehr reich an Vieh, Silber und Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er zog nach öfterem Lagern aus dem Südland bis nach Betel, bis an die Stätte, wo vordem sein Zelt gestanden, zwischen Betel und Ai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'zu der Stätte des Altars, den er früher dort gebaut hatte. Dort rief Abram des Herrn Namen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Auch Lot, der mit Abram zog, besaß Schafe, Rinder und Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Aber das Land ließ sie nicht beisammen hausen; denn ihre Habe war groß geworden, und so konnten sie nicht beieinander bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und Streit ward zwischen den Hirten der Herde Abrams und denen der Herde Lots; die Kanaaniter und die Periziter hausten aber damals im Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: \"Nimmer sei Zwietracht zwischen mir und dir, zwischen meinen Hirten und deinen! Wir sind ja Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Steht nicht das ganze Land dir offen? Trenne dich lieber von mir! Willst du zur Linken, gehe ich zur Rechten; willst du zur Rechten, gehe ich zur Linken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da hob Lot seine Augen auf und sah, daß die ganze Au des Jordan völlig bewässert war, bevor der Herr Sodom und Gomorrha zerstörte - gleich dem Garten des Herrn und wie das Ägypterland - bis Soar hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Und Lot wählte sich die ganze Au des Jordan. So brach Lot nach Osten auf, und sie schieden voneinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram hatte sich im Lande Kanaan angesiedelt. Lot aber in den Städten der Au, und so zeltete er bis nach Sodom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Sodoms Männer aber waren böse und gewaltige Sünder wider den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Der Herr aber sprach zu Abram, als Lot von ihm geschieden: \"Erhebe deine Augen! Schau von dem Orte, wo du bist, nach Norden, Süden, Osten und Westen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'All das Land, das du erblickst, gebe ich dir und deinem Stamm für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Dann mache ich deinen Stamm den Staubkörnchen der Erde gleich. Vermöchte jemand der Erde Staubkörnchen zu zählen, dann könnte auch dein Stamm gezählt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Auf! Umwandle dieses Land nach Länge und Breite! Denn dir will ich es geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Und Abram stimmte zu, kam und ließ sich bei Mamres Terebinthen zu Hebron nieder und baute hier dem Herrn einen Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Und es geschah in den Tagen Amraphels, des Königs von Sinear, Adoks, des Königs von Ellasar, Kedorlaomers, des Königs von Elam, und Tidals, des Königs von Gojim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Diese hatten Krieg beschlossen wider Bera, Sodoms König, Birsa, den König von Gomorrha, Sinab, den König von Adma, Semeber, den König von Seboim, und den König von Bela, das ist Soar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle diese zogen vereint in das Tal Siddim, das ist das Salzmeer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre waren sie Kedorlaomer dienstbar gewesen; im dreizehnten aber fielen sie ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Im vierzehnten Jahre nun zogen Kedorlaomer und die Könige bei ihm heran; da schlugen sie die Rephaiter zu Astarot Karnaim, die Zuziter zu Ham und die Emiter in der Ebene von Kirjataim');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Choriter auf den Bergen von Seïr bis nach EI Paran, das östlich von der Wüste liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Dann machten sie kehrt und kamen nach En Mispat, das ist Kades, und schlugen das ganze Gefilde der Amalekiter, sowie die Amoriter, die in Chasason Tamar hausten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da zogen der König von Sodom und der König von Gomorrha aus, sowie der König von Adma, der König von Seboim und der von Bela, das ist Soar, und rüsteten zum Kampfe gegen jene im Siddimtale,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'gegen Kedorlaomer, den König von Elam, Tidal, den König von Gojim, Amraphel, den König von Sinear, und Arjok, den König von Ellasar, vier Könige gegen fünf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Das Siddimtal aber ist voller Erdpechgruben. Als nun die Könige von Sodom und Gomorrha fliehen mußten, warfen sie sich hinein; die übrigen aber flohen ins Gebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Da nahmen jene alle Habe Sodoms und Gomorrhas und all ihren Mundvorrat und zogen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Auch Lot, Abrams Brudersohn, und seine Habe nahmen sie mit und zogen ab; er wohnte nämlich zu Sodom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Nun kam ein Flüchtling und brachte Kunde dem Hebräer Abram; er wohnte bei den Terebinthen Mamres, des Amoriters, des Bruders von Eskol und Aner, und diese waren mit Abram im Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als Abram hörte, sein Bruder sei gefangen, entbot er seine Verbündeten und seine 318 Hausgeborenen und jagte bis Dan nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Er überfiel sie des Nachts, er und seine Diener, schlug und verfolgte sie bis Choba, links von Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'So brachte er alle Habe zurück. Auch seinen Bruder Lot und seine Habe brachte er zurück, ebenso die Weiber und das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Da zog ihm der König von Sodom entgegen, als er vom Sieg über Kedorlaomer und die Könige bei ihm zurückkehrte, im Tale Save, das ist das Königstal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Der König von Salem aber, Melchisedech, hatte Brot und Wein mitgebracht; er war ja ein Priester des höchsten Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: \"Vom höchsten Gott, dem Schöpfer Himmels und der Erden, sei gesegnet Abram!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Gepriesen sei der höchste Gott, der deine Feinde dir in die Hand gegeben!\" Und Abram gab ihm den Zehnten von allem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Und der König von Sodom sprach zu Abram: \"Gib mir die Leute! Die Habe behalte für dich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Da sprach Abram zum König von Sodom: \"Zum Herrn, dem höchsten Gott, dem Schöpfer Himmels und der Erde, erhebe ich meine Hand:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Keinen Faden, keinen Schuhriemen, gar nichts von dem, was dir eigen, nehme ich an. Du sollst nicht sagen: \'Ich habe Abram reich gemacht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Nichts will ich. Nur was die Jungmannschaft verzehrt, und den Anteil für die Männer, die mit mir gezogen, Aner, Eskol und Mamre! Sie mögen ihren Anteil nehmen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Hernach erging das Wort des Herrn an Abram in einem Gesichte also: \"Abram, fürchte dich nicht! Ich bin dir doch ein Schild; dein Lohn ist überreich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Da sprach Abram: \"Herr, ach Herr, was kannst du mir geben, da ich doch kinderlos wandle? Ist doch der Sohn meines Haussklaven Eliezer der Erbesohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach: \"Mir hast du ja keinen Nachkommen geschenkt; so wird mich mein Haussklave eben beerben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Aber da erging das Wort des Herrn an ihn also: \"Dieser wird dich nicht beerben; dein eigener Leibessprosse wird dich einst beerben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er führte ihn ins Freie und sprach: \"Blick auf zum Himmel und zähle die Sterne! Kannst du sie zählen?\" Dann sprach er zu ihm: \"Also wird auch dein Stamm sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Und er glaubte dem Herrn, und dies erachtete er ihm als Verdienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und er sprach zu ihm: \"Ich bin der Herr, der dich aus Ur Kasdim geführt, um dir dies Land zu geben, damit du es besitzest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Da sprach er: \"Herr, ach Herr! Woran erkenne ich, daß ich\'s besitzen soll?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Und er sprach zu ihm:\"Hol mir jetzt eine dreijährige Kuh und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube sowie eine junge Taube!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Da holte er ihm diese alle. Dann zerlegte er sie mitten durch und legte jede Hälfte der anderen gegenüber; die Vögel aber hatte er nicht zerteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Da stießen die Raubvögel auf die Tierleichen nieder; Abram aber scheuchte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Wie nun die Sonne im Untergehen war, befiel Abram ein Tiefschlaf, und eine schwere, dunkle Ahnung überkam ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da sprach er zu Abram. \"Du sollst jetzt wissen: Dein Stamm wird Fremdling sein in einem Lande, das dir nicht eigen. Dann front er ihm, und dies bedrückt ihn an vierhundert Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Jedoch das Volk, dem sie dort fronen, das will ich richten. Dann ziehen sie mit reicher Habe aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Du aber gehst zu deinen Vätern ein im Frieden, zu deiner Grabesstatt in schönem Alter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Im vierten Gliede kehren sie hierher; noch ist nicht voll der Amoriter Maß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Dann ging die Sonne unter, und dichte Finsternis kam; da erschien ein rauchender Ofen und eine Feuerflamme, und zwischen jenen Stücken fuhr es durch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An jenem Tag schloß der Herr mit Abram einen Bund mit den Worten: \"Ich gebe deinem Stamme dieses Land vom Fluß Ägyptens bis zum großen Strom, dem Euphratstrom,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'das Gebiet der Keniter, Keniziter, Kadmoniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Chittiter, Periziter, Rephaiter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'und Amoriter, Kanaaniter, Girgasiter sowie Jebusiter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai aber, Abrams Weib, hatte ihm kein Kind geboren; sie hatte aber eine ägyptische Magd, die Hagar hieß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Nun sprach Sarai zu Abram: \"Der Herr hat mir Kinder versagt. Heirate meine Magd! Vielleicht komme ich durch sie zu Kindern. Und Abram folgte den Worten Sarais.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'So nahm Sarai, Abrams Weib, ihre Magd, die Ägypterin Hagar, nach Ablauf von zehn Jahren, die Abram im Lande Kanaan gewohnt, und gab sie ihrem Manne Abram, ihm selbst, zum Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er heiratete Hagar, und sie empfing. Als sie aber sah, daß sie guter Hoffnung war, sank ihre Herrin in ihren Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sprach Sarai zu Abram: \"Meine Kränkung über dich! Ich selbst habe dir meine Magd abgetreten; nun sie aber sah, daß sie in Hoffnung sei, sank ich in ihren Augen. Zwischen mir und dir richte der Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Da sprach Abram zu Sarai: \"In deiner Hand ist deine Magd. Tue mit ihr, wie es dir gefällt!\" Da drückte Sarai sie so, daß sie ihr entfloh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Der Engel des Herrn aber traf sie an einem gewissen Wasserquell in der Wüste, am Quell auf dem Wege nach Schur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Und er sprach: \"Hagar, Sarais Magd, wo kommst du her? Wo gehst du hin?\" Sie sprach: \"Vor meiner Herrin Sarai bin ich flüchtig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Da sprach der Engel des Herrn zu ihr: \"Kehr heim zu deiner Herrin und unterwirf dich ihren Händen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Dann sprach der Engel des Herrn zu ihr: \"Ich mache deinen Stamm gar zahlreich; vor Menge kann man ihn nicht zählen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Und der Engel des Herrn sprach zu ihr: \"Du bist gesegnet und wirst einen Sohn gebären. Den heißest du Ismael: denn der Herr hat dein Elend gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ein Wildeselmensch wird er werden; seine Hand gegen alle und aller Hand gegen ihn! Allen seinen Brüdern steht er dreist gegenüber.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Da nannte sie den Herrn, der mit ihr redete, \"du bist der Gott des Trostes\"; denn sie sprach: \"Habe ich nicht schließlich Trost erfahren?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Daher nannte man den Brunnen: Lachaj Roi (Des Lebenden Trostbrunnen): er liegt zwischen Kades und Berad.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Sohn, den ihm Hagar geboren, Ismael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Und Abram war 86 Jahre alt, als Hagar dem Abram den Ismael gebar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Abram war 99 Jahre alt; da erschien der Herr dem Abram und sprach zu ihm: \"Ich bin ein mächtiger Gott. Vor mir nur wandle! Alsdann fehlt dir nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ich schließe zwischen mir und dir den Bund und will dich mächtig mehren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da fiel Abram auf sein Antlitz, und Gott redete mit ihm also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '\"Das ist mein Bund mit dir: Stammvater einer Völkermenge wirst du jetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Drum sollst du fortan nimmer Abram heißen. Nein, Abraham ist jetzt dein Name; zu einer Völkermenge Vater mache ich dich ja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Ich lasse dich gar zahlreich werden und mache dich zu Völkern, und Könige entsprießen dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und zwischen mir und dir errichte ich den Bund und zwischen mir und deinem Stamm nach dir, ja, einen ewigen Bund für alle die Geschlechter, daß ich dir Schutzgott sei und deinem Stamm nach dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Ich gebe dir und deinem Stamm nach dir den Boden deiner Pilgerfahrten, das ganze Land von Kanaan, zu ewigem Besitze; ein Schutzgott will ich ihnen sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham: \"Du aber halte meinen Bund, du und dein Stamm nach dir, in allen den Geschlechtern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das ist mein Bund, den ihr einhalten sollt, der zwischen mir und euch und deinem Stamm nach dir besteht: Bei euch soll alles Männliche beschnitten werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Und zwar sollt ihr an eurer Vorhaut Fleisch beschnitten sein! Dies ist das Bundeszeichen zwischen mir und euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Bei euch soll mit acht Tagen alles Männliche beschnitten werden, Geschlecht für Geschlecht, auch selbst der Haussklave und der von irgendeinem Fremden Angekaufte, der nimmer deines Stammes ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Beschnitten werde dein Haussklave und der von dir mit Geld Erkaufte! So sei mein Bund an eurem Fleisch zum ewigen Bunde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Doch wer gesund und dennoch unbeschnitten ist, wer nicht an seiner Vorhaut Fleisch beschnitten, ein solches Wesen wird aus seinem Volke ausgestrichen. Zerrissen hat es meinen Bund.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach zu Abraham: \"Du sollst dein Weib Sarai nicht länger Sarai nennen! Nein! Sara soll ihr Name sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ich segne sie und schenke dir durch sie noch einen Sohn. Ich segne sie; dann wird sie eine Völkermutter, und Völkerkönige entsprießen ihr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da fiel Abraham auf sein Antlitz, lachte und sprach bei sich: \"Sollte einem Hundertjährigen noch ein Kind geboren werden, oder sollte Sara, die neunzigjährige, noch gebären können?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: \"Möchte nur Ismael auf dein Geheiß am Leben bleiben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sprach Gott: \"Trotzdem wird Sara, dies dein Weib, dir einen Sohn gebären; den sollst du Isaak heißen! Mit ihm errichte ich dann meinen Bund zum ewigen Bund für seinen Stamm nach ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Auch Ismaels wegen will ich dich erhören; ich segne ihn und lasse Frucht ihn tragen und mehre ihn gar mächtiglich. Zwölf Fürsten wird er zeugen, und also mache ich auch ihn zu einem großen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Doch meinen Bund will ich mit Isaak schließen, den dir um diese Zeit im künftigen Jahre Sara schenkt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und er beendete seine Unterredung mit ihm. Und Gott fuhr vor Abraham auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Da nahm Abraham seinen Sohn Ismael und alle seine Haussklaven, sowie alle mit Geld von ihm Erkauften, jedes Männliche unter den Leuten in Abrahams Haus, und beschnitt das Fleisch ihrer Vorhaut an eben diesem Tage, gleich nachdem Gott mit ihm gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham aber war 99 Jahre alt, als er am Fleische seiner Vorhaut beschnitten ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Und 13 Jahre alt war sein Sohn Ismael, als er am Fleische seiner Vorhaut beschnitten ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Am gleichen Tage war Abraham beschnitten worden wie sein Sohn Ismael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Und alle seine Hausgenossen, sowohl die Haussklaven als auch die mit Geld von Fremden Gekauften, waren mit ihm beschnitten worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Und der Herr erschien ihm bei den Terebinthen Mamres, als er sich an den Zelteingang zur Vormittagszeit setzte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Wie er nun seine Augen erhob und aufblickte, standen drei Männer vor ihm. Kaum sah er sie, lief er schon vom Zelteingang auf sie zu und neigte sich zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Dann sprach er: \"Herr, finde ich in deinen Augen Gnade, dann ziehe nicht an deinem Sklaven vorüber!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soll etwas Wasser bringen! Dann wascht ihr euch die Füße und legt euch unter diesen Baum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Ich hole inzwischen einen Bissen Brot, daß ihr euch stärket. Dann mögt ihr weiterziehen! Denn darum seid ihr bei eurem Sklaven vorbeigekommen.\" Sie sprachen: \"Tu so, wie du gesagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Da eilte Abraham ins Zelt zu Sara und sprach: \"Schnell drei Maß Mehl, Feinmehl! Knete und backe Kuchen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Dann lief Abraham zu den Rindern, holte ein Kalb, zart und kräftig, und gab es dem Diener, der es eilends bereitete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Dann holte er Butter und Milch sowie das Kalb, das er hatte bereiten lassen, und setzte es ihnen vor; er selbst wartete ihnen unter dem Baume auf, während sie aßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sprachen sie zu ihm: \"Wo ist denn Sara, dein Weib?\" Er sprach: \"Hier im Zelt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sprach er: \"Ich kehre zu dir nach Ablauf von neun Monaten zurück; da hat dein Weib Sara einen Sohn.\" Sara aber horchte am Zelteingang hinter ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham aber und Sara waren alt und hochbetagt, und Sara erging es nicht mehr nach Weiberart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'So lachte Sara in sich hinein, indem sie dachte: \"Welk geworden, sollte ich noch der Liebe pflegen? Mein Herr ist gleichfalls alt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Darauf sprach der Herr zu Abraham: \"Warum lacht Sara und denkt dabei: \'Soll ich wahrhaftig ein Kind bekommen, nachdem ich alt geworden?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ist für den Herrn etwas unmöglich? Um diese Zeit kehre ich zu dir nach Ablauf von neun Monaten zurück; dann hat Sara einen Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Da leugnete Sara und sprach: \"Ich habe nicht gelacht\"; denn sie hatte Angst bekommen; er aber sprach: \"Nein! Du hast gelacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Herauf brachen die Männer von da auf und bogen gegen Sodom ab; Abraham aber ging mit ihnen, sie zu begleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Und der Herr sprach: \"Soll ich vor Abraham verhehlen, was ich zu tun im Sinne habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Doch Abraham soll zu einem Volke werden, groß und stark! Dann sollen sich in ihm die Erdenvölker alle segnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Nein! Auserkoren hab ich ihn, auf daß er seinen Söhnen und dem Haus nach ihm gebiete, sie sollen doch den Weg des Herrn einhalten Gerechtigkeit und Recht ausübend, auf daß der Herr das über Abraham brächte, was er ihm einst verheißen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und der Herr sprach: \"Der Klageruf schwillt wider Sodom und Gomorrha an, und ihre Sünde wuchtet schwer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Ich will hinab und sehen, ob sie getan, so wie ihr Ruf, der vor mich kam, vermeldet. Alsdann Vernichtung! Wenn aber nicht - ich will es wissen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Da wandten sich die Männer von dort weg und gingen Sodom zu. Abraham aber blieb vor dem Herrn stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat vor und sprach: \"Willst du Schuldlose mit Schuldigen hinraffen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht gibt\'s in der Stadt noch fünfzig Schuldlose. Willst du diese hinraffen und nicht vielmehr den Ort begnadigen, den fünfzig Schuldlosen darin zulieb?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Nicht würdig wäre es deiner, solches zu tun, Schuldige und Unschuldige zusammen zu töten, daß es eins wäre, schuldlos oder schuldig. Das wäre deiner unwürdig. Sollte der ganzen Erde Richter nicht Gerechtigkeit üben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Da sprach der Herr: \"Fänd ich nur fünfzig Schuldlose zu Sodom in der Stadt, dann wollte ich ihretwegen den ganzen Ort begnadigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Da hob Abraham an und sprach: \"Ich habe mich nun unterfangen, mit meinem Herrn zu reden, wennschon ich Staub und Asche bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht fehlen an den fünfzig Schuldlosen nur fünf. Willst du die ganze Stadt um dieser fünfe willen zugrunde richten?\" Er sprach: \"Nein, falls ich dort fünfundvierzig fände.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Da redete er abermals mit ihm und sprach: \"Vielleicht finden sich nur vierzig darin.\" Er sprach: \"Dann tue ich es nicht um der vierzig willen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Er sprach: \"Ach zürne nicht, mein Herr, daß ich noch einmal rede! Vielleicht finden sich nur dreißig darin.\" Er sprach: \"Dann tue ich es nicht, wenn ich nur dreißig darin fände.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Er sprach - \"Ich habe mich nun schon unterfangen, mit meinem Herrn zu reden. Vielleicht finden sich nur zwanzig darin.\" Er sprach: \"Ich richte sie nicht zugrunde um der zwanzig Willen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Er sprach: \"Ach zürne nicht, mein Herr, wenn ich dies eine Mal noch rede! Vielleicht finden sich nur zehn darin.\" Er sprach: \"Ich richte sie dann nicht zugrunde wegen dieser zehn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Dann ging der Herr fort, sogleich, nachdem er das Gespräch mit Abraham beendet hatte. Abraham aber kehrte an seinen Ort zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Und die beiden Engel kamen des Abends nach Sodom; Lot aber wohnte in Sodoms Vorstadt. Als Lot sie erblickte, trat er an sie heran und neigte sich bis zum Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Dann sprach er: \"Meine Herren! Kehrt doch in eures Knechtes Haus zur Nachtrast ein und wascht euch die Füße! Dann möget ihr frühmorgens eures Weges ziehen!\" Sie aber sprachen: \"Nein! Wir wollen auf der Straße mächtigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Er aber drang inständig in sie, und so kehrten sie bei ihm ein und betraten sein Haus. Da bereitete er ihnen eine Mahlzeit, buk ungesäuerte Kuchen, und sie aßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Noch hatten sie sich nicht schlafen gelegt, als schon die Männer der Stadt, die Leute von Sodom, das Haus umringten, jung und alt, das ganze Volk bis auf den letzten Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Und sie riefen nach Lot und sprachen zu ihm: \"Wo sind die Männer, die heute abend zu dir gekommen sind? Bring sie uns heraus, damit wir sie erkennen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da ging Lot zu ihnen vor die Tür hinaus; die Tür aber verschloß er hinter sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Und er sprach: \"Meine Brüder, tut doch nichts so Unnatürliches!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Da habe ich zwei Töchter, die noch keinen Mann erkannt haben, sie will ich zu euch bringen. Tut an ihnen, was euch beliebt. Doch diesen Männern dürft ihr nichts tun; denn darum sind sie in meines Daches Schatten getreten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Da schrien sie: \"Pack dich weg!\" und sagten: \"Kam einer als Gast und Richter zugleich? Jetzt tun wir dir noch übler als jenen.\" Und sie drangen hart auf den Mann, auf Lot, ein und gingen daran, die Tür zu erbrechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Da griffen die Männer hinaus, zogen Lot zu sich ins Haus, nachdem sie die Tür abgeschlossen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Die Leute am Hauseingang aber hatten sie mit Blindheit geschlagen, klein und groß, und so konnten sie die Tür nicht finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Die Männer aber sprachen zu Lot: \"Hast du noch jemanden hier? Etwa einen Schwiegersohn, deine Söhne und deine Töchter? All die Deinen in der Stadt führe von diesem Ort weg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir vertilgen diese Stätte, weil der Klageschrei wider sie vor dem Herrn mächtig geworden. Darum sandte uns der Herr, sie zu verderben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot hinaus und redete mit seinen Schwiegersöhnen, die seine Töchter geheiratet, und sprach: \"Auf! Fort aus diesem Ort! Der Herr will diese Stadt vertilgen!\" Aber er schien seinen Schwiegersöhnen zu scherzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Nach Anbruch der Morgenröte aber drängten die Engel Lot und sprachen: \"Auf! Nimm dein Weib und diese deine beiden Töchter hier, daß du nicht weggerafft wirst ob der Missetat der Stadt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Als er zögerte, griffen die Männer ihn, sein Weib und seine beiden Töchter an der Hand, weil der Herr ihn schonen wollte; sie führten ihn fort und ließen ihn erst draußen vor der Stadt los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Während sie sie hinausführten, sprach einer: \"Flüchte dich um deines Lebens willen! Schau dich nicht um! Bleib nirgends in der Niederung stehen! Flieh ins Gebirge, daß du nicht weggerafft wirst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot aber sprach zu ihnen: \"Nicht so, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Dein Knecht hat nun einmal Gnade bei dir gefunden; groß Erbarmen hast du mir erwiesen, mir das Leben zu retten; aber ich kann nicht ins Gebirge fliehen. Dann aber könnte mich das Verderben ereilen, daß ich stürbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, diese Stadt ist nahe genug, hineinzuflüchten, und nur ein kleines Stück ist\'s noch. Dahin könnte ich mich flüchten. Es ist ja nur noch ein kleines Stück; dann könnte ich am Leben bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Er sprach zu ihm: \"Wohlan, ich nehme auch darin Rücksicht auf dich und will diese Stadt, von der du sprichst, nicht zerstören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Flieh eilends dorthin! Denn ich kann nichts tun, bis du dorthin kommst.\" Deshalb nannte man die Stadt Soar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Eben war die Sonne aufgegangen; da kam Lot nach Soar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Der Herr aber ließ auf Sodom und Gomorrha Schwefel und Feuer regnen, vom Herrn her, vom Himmel herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Und er vernichtete diese Städte, die ganze Niederung und alle Insassen der Städte und das Gewächs des Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Sein Weib aber schaute hinter sich und ward zu einer Salzsäule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham begab sich nun in der Frühe an die Stätte, wo er vor dem Herrn gestanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Und er schaute auf Sodom und Gomorrha hinab und auf das ganze Land der Niederung; da sah er, wie ein Qualm vom Lande aufstieg, wie eines Schmelzofens Qualm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'So war es, als Gott die Städte der Niederung zerstörte; dabei gedachte Gott Abrahams und schickte Lot aus dem Bereich der Zerstörung weg, als er die Städte, in denen Lot gewohnt, zerstörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot zog dann von Soar hinauf und wohnte im Gebirge mit seinen beiden Töchtern; denn er fürchtete sich, in Soar zu bleiben. So wohnte er in einer Höhle mit seinen beiden Töchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sprach die Ältere zu der jüngeren: \"Unser Vater ist alt, und auf Erden gibt es niemand mehr, der Umgang mit uns haben könnte nach aller Welt Brauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Komm, wir wollen unserem Vater Wein zu trinken geben und uns zu ihm legen, daß wir durch unseren Vater unseren Stamm erhalten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Da gaben sie ihrem Vater in jener Nacht Wein zu trinken; dann ging die Ältere hinein und schlief bei ihrem Vater; er aber merkte nicht, wie sie sich legte, noch wie sie aufstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Am Tage darauf sprach die Ältere zur Jüngeren: \"Siehe, ich habe heute nacht bei meinem Vater geschlafen; wir wollen ihm auch diese Nacht Wein zu trinken geben. Dann geh hinein und schlaf bei ihm, daß wir durch unseren Vater unseren Stamm erhalten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Und sie gaben ihrem Vater auch an diesem Abend Wein zu trinken; dann ging die Jüngere hin und schlief bei ihm; er aber merkte nicht, wie sie sich legte, noch wie sie aufstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Also kamen die beiden Töchter Lots durch ihren Vater in Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die Ältere gebar einen Sohn und nannte ihn Moab; das ist der Stammvater der heutigen Moabiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Auch die jüngere gebar einen Sohn und sie nannte ihn Ben Ammi; das ist der Stammvater der heutigen Ammoniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Und Abraham zog von dort ins Gebiet des Südlands und wohnte zwischen Kades und Schur. Als er einst zu Gerar weilte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'sprach Abraham von seinem Weibe Sara: \"Sie ist meine Schwester.\" Da sandte der König von Gerar, Abimelech, hin und ließ Sara holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Gott aber kam im nächtlichen Traume zu Abimelech und sprach zu ihm: \"Des Weibes wegen, das du geholt, mußt du sterben, ist sie doch eine Ehefrau.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber war ihr noch nicht genaht; so sprach er: \"Herr, bringst du auch schuldlose Leute um?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Er hat doch selbst zu mir gesagt: \'Sie ist meine Schwester\' und auch sie hat gesagt: \'Er ist mein Bruder.\' In meines Herzens Einfalt und mit reinen Händen habe ich das getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Da sprach Gott zu ihm im Traume: \"Auch ich weiß, daß du in deines Herzens Einfalt so gehandelt, und so bewahrte ich selbst dich davor, gegen mich zu sündigen; darum habe ich dir nicht zugelassen, sie zu berühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Gib aber jetzt dem Manne sein Weib heraus! Weil er ein Prophet ist, soll er für dich beten, daß du am Leben bleibst. Gibst du sie aber nicht heraus, so wisse, daß du sterben mußt, du samt all den Deinen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Da rief frühmorgens Abimelech alle seine Diener zusammen und erzählte ihnen all das, und die Männer erschraken sehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Dann ließ Abimelech Abraham rufen und sprach zu ihm: \"Was hast du uns angetan? Womit habe ich gegen dich gefehlt, daß du so schwere Schuld über mich und über mein Gebiet gebracht hast? Was nimmermehr geschehen durfte, hast du mir angetan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Dann sprach Abimelech zu Abraham: \"Was ist dir eingefallen, daß du dies getan hast?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Da sprach Abraham: \"Ich habe eben gedacht: \'Gar keine Furcht vor Gott herrscht an diesem Ort; sie bringen mich meines Weibes wegen um.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Auch ist sie wirklich meine Schwester, meines Vaters Tochter, nur nicht meiner Mutter Tochter, und so ist sie mein Weib geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Als mich die Himmlischen aus meines Vaters Hause auf die Irrfahrt schickten, sprach ich zu ihr. \'Tu mir dies zuliebe! Wohin wir kommen, sag von mir: Es ist mein Bruder.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Schafe und Rinder, Sklaven und Mägde und gab sie Abraham; auch gab er ihm sein Weib Sara heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: \"Mein Land steht dir offen. Laß dich nieder, wo es dir beliebt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Zu Sara aber sprach er: \"Ich schenke deinem Bruder tausend Silberstücke. Dies sei dir Ersatz für alles, was dir, deinen Knechten und Mägden widerfahren ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Abraham aber betete zu Gott, und Gott heilte Abimelech, sein Weib und seine Mägde, daß sie Geburten hatten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'denn der Herr hatte jeden Schoß in Abimelechs Hause wegen Sara, des Weibes Abrahams, verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Der Herr aber hatte Sara heimgesucht, wie er verheißen. Und der Herr tat an Sara, wie er vorausgesagt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sara war guter Hoffnung und gebar einen Sohn dem Abraham in seinem Greisenalter um die Zeit, die Gott vorausgesagt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham nannte seinen neugeborenen Sohn, den ihm die Sara gebar, Isaak.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Und Abraham beschnitt seinen Sohn Isaak, als er acht Tage alt war, wie ihm Gott befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham aber war hundert Jahre alt, als ihm sein Sohn Isaak geboren ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Da sprach Sara: \"Zum Scherze hat mich Gott gemacht. Wer davon hört, scherzt über mich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: \"Wer hätte Abraham zugeflüstert: \'Sara stillt Kinder noch?\' Nun habe ich ihm doch noch einen Sohn in seinem Greisenalter geboren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind wuchs und wurde entwöhnt, und Abraham bereitete ein großes Mahl an dem Tag, an dem Isaak entwöhnt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Sara aber sah den Sohn der Ägypterin Hagar, den sie Abraham geboren, wie er seinen Spott trieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Da sprach sie zu Abraham: \"Jage diese Magd und ihren Sohn fort! Denn dieser Magd Sohn soll nicht mit Isaak, meinem Sohn, erben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dies Wort aber betrübte Abraham heftig wegen seines Sohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Doch Gott sprach zu Abraham: \"Nicht um den Knaben sei\'s dir leid und nicht um deine Magd! In allem, was dir Sara sagt, höre auf ihre Stimme! Nur wer von Isaak stammt, trägt deines Stammes Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Doch mache ich zu einem Volke auch den Sohn der Magd; auch er ist ja dein Sproß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Da nahm Abraham am anderen Morgen früh Brot und einen Schlauch mit Wasser und gab es Hagar; das Kind legte er auf ihre Schultern und schickte sie fort. Da zog sie hin und verirrte sich in der Wüste Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Als das Wasser im Schlauch zu Ende ging, ließ sie das Kind unter einem der Sträucher liegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ging fort und saß für sich, einen Bogenschuß weit; denn sie sprach: \"Ich kann nicht ansehen, wie das Kind stirbt.\" So saß sie abseits, erhob ihre Stimme und weinte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Gott aber hörte ihr Gebet um den Knaben, und Gottes Engel rief Hagar vom Himmel her und sprach zu ihr: \"Was ist dir, Hagar? Fürchte dich nicht! Gott hat ja dein Gebet um den Knaben gehört, wo immer er ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Auf! Nimm den Knaben! Fasse durch ihn wieder Mut! Ich will ihn ja zu einem großen Volke machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott tat ihr die Augen auf, und sie erblickte einen Wasserquell. Da ging sie hin und füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben. Er wuchs heran und wohnte in der Wüste und war ein Meister mit dem Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Er wohnte in der Wüste Paran, und seine Mutter besorgte ihm ein Weib aus dem Ägypterlande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'In jener Zeit redeten Abimelech und sein Heerführer Pikol mit Abraham: \"Gott ist mit dir in allem, was du tust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Nun schwöre mir hier bei Gott, daß du weder mich noch meinen Schoß und Sproß schädigest, sondern Güte, wie ich an dir geübt, auch an mir üben willst, desgleichen an dem Lande, in dem du zu Gast weilst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sprach Abraham: \"Ich schwöre es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Abraham aber stellte Abimelech zur Rede wegen des Wasserbrunnens, den Abimelechs Knechte weggenommen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelech aber sprach: \"Ich weiß nicht, wer dies getan; du hast mir nichts gesagt, noch habe ich bis heute davon gehört.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und sie schlossen einen Vertrag miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Abraham aber stellte die sieben Lämmer der Herde besonders.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Da sprach Abimelech zu Abraham: \"Was sollen diese sieben Lämmer, die du besonders stellst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Er sprach: \"Die sieben Lämmer mußt du von mir nehmen, damit sie mir als Zeugnis dienen, daß ich diesen Brunnen gegraben habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Diese Stätte heißt daher Beerseba; denn dort haben sie einander zugeschworen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'So schlossen sie einen Vertrag zu Beerseba. Alsdann brachen Abimelech und sein Heerführer Pikol auf und kehrten in das Philisterland zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Er aber pflanzte eine Tamariske zu Beerseba und rief dort den Namen des Herrn an, eines ewigen Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und Abraham weilte lange zu Gast im Philisterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nach diesen Begebnissen war es; da versuchte Gott den Abraham. Er sprach zu ihm: \"Abraham!\" Er sprach: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Da sprach er: \"Nimm deinen einzigen Sohn, den du so liebst, den Isaak, und zieh ins Morialand und bring ihn zum Brandopfer dort dar, auf einem jener Berge, den ich dir bezeichnen werde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da sattelte Abraham frühmorgens seinen Esel, nahm seine beiden Diener samt seinem Sohne Isaak mit, spaltete Holzscheite zum Brandopfer, brach auf und zog nach der Stätte, von der ihm Gott gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage erhob Abraham seine Augen; da sah er von weitem die Stätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sprach Abraham zu seinen Dienern: \"Bleibt mit dem Esel hier! Ich aber und der Knabe wollen dorthin gehen, anzubeten. Wir kommen dann wieder zu euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Und Abraham nahm das Opferholz und legte es seinem Sohne Isaak auf; er aber nahm Feuer und Messer mit. So zogen sie beide zusammen dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sprach Isaak zu seinem Vater Abraham; er sprach: \"Mein Vater!\" Er sprach: \"Mein Sohn, hier bin ich.\" Er sprach: \"Da ist Feuer und Holz. Aber wo ist das Schaf zum Opfer?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Da sprach Abraham: \"Gott ersieht sich schon das Schaf zum Opfer, mein Sohn.\" So zogen sie beide zusammen dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Und sie kamen zu dem Ort, von dem ihm Gott gesprochen. Dort baute Abraham einen Altar und schichtete das Holz. Dann band er seinen Sohn Isaak und legte ihn auf den Altar auf das Holz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Dann streckte Abraham seine Hand aus und griff nach dem Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel des Herrn vom Himmel her und sprach: \"Abraham! Abraham!\" Er sprach: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Er sprach: \"Leg deine Hand nicht an den Knaben! Tu ihm nichts! Jetzt weiß ich: Du bist gottesfürchtig; du verweigerst mir ja selbst deinen einzigen Sohn nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Und Abraham erhob seine Augen und sah hin; da hatte sich hinter ihm ein Widder mit den Hörnern im Dickicht verfangen. Abraham ging hin, nahm den Widder und brachte ihn an seines Sohnes Statt zum Opfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham nannte diesen Ort: \"Der Herr sorgt\", so wie man noch sagt: \"Auf dem Berg des Herrn ist man versorgt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und des Herrn Engel rief Abraham ein zweitesmal vom Himmel her');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'und sprach: \"Ich leiste bei mir selber einen Schwur\" - ein Spruch des Herrn -: \"Weil du dies getan und deinen einzigen Sohn mir nicht verweigert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'so gebe ich dir meinen Segen und mache deinen Stamm so zahlreich wie des Himmels Sterne und wie den Sand am Meeresufer. Dein Stamm soll seiner Feinde Tor erobern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Der Erde Völker alle sollen sich mit deinem Stamme segnen zum Lohn dafür, daß du auf meine Stimme hast gehört.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Und Abraham kehrte zu seinen Dienern zurück; sie brachen auf und zogen miteinander nach Beerseba. Und Abraham blieb in Beerseba wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nach diesen Begebnissen geschah es, daß man Abraham meldete: \"Auch Milka hat deinem Bruder Nachor Söhne geboren:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz, seinen Erstgeborenen, und seinen Bruder Buz und Kemuel, den Vater Arams,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Kesed, Chazo, Pildas, Jidlaph sowie Betuel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuel aber hatte Rebekka gezeugt. Diese acht hatte Milka dem Nachor, Abrahams Bruder, geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Er hatte auch ein Nebenweib namens Rëuma; sie gebar Tebach, Gacham, Tachas und Maaka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Die Lebensjahre Saras betrugen 127 Jahre; das sind die Lebensjahre Saras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Und Sara starb zu Kirjat Arba, das ist Hebron, im Lande Kanaan. Und Abraham kam, Sara zu beklagen und zu beweinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Dann erhob sich Abraham von dem Leichnam weg und sprach zu den Söhnen Chets also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '\"Als Gast und Beisaß bin ich bei euch. Gebt mir bei euch doch ein Erbgrab, daß ich meine Tote aus dem Hause bringe und begrabe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Und die Söhne Chets antworteten Abraham also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '\"Nein! Hör uns an, Herr! Ein Gottesfürst bist du in unserer Mitte. Begrabe deine Tote im besten unserer Gräber. Keiner von uns wird dir sein Grab verweigern, deine Tote darin zu bestatten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da erhob sich Abraham, neigte sich vor den Landeskindern, den Söhnen Chets');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'und redete also mit ihnen: \"Ist es euch genehm, daß ich meine Tote aus dem Hause bringe und begrabe, so hört mich an! Legt Fürsprache für mich ein bei Ephron, Sochars Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir die Höhle der Makpela lasse, die ihm gehört und am Rande seines Feldes liegt! Um vollen Preis lasse er sie mir in eurer Mitte zum Erbbegräbnis!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Ephron aber hatte einen Sitz unter den Söhnen Chets. So antwortete der Chittiter Ephron dem Abraham laut vor den Söhnen Chets, vor allen, die Zutritt zum Tore seiner Stadt hatten, also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '\"Nicht so, Herr! Hör mich an: Dieses Feld schenke ich dir; ich schenke dir auch die Höhle, die darauf ist. Vor meiner Volksgenossen Augen schenke ich sie dir. Begrabe deine Tote!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da neigte sich Abraham vor den Landeskindern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und sprach zu Ephron laut vor den Landeskindern also: \"Ach, möchtest du mir Gehör schenken! Ich zahle den Preis des Feldes. Nimm ihn von mir an, daß ich dort meine Tote begraben kann!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Da antwortete Ephron dem Abraham also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '\"Nicht doch, mein Herr! Hör mich an! Ein Feld! Vierhundert Silberringe, was hat dies unter uns zu sagen? Begrabe nur deine Tote!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Und Abraham hörte auf Ephron. So wog Abraham dem Ephron den Preis dar, von dem er im Beisein der Söhne Chets gesprochen: vierhundert Silberringe Kaufsilber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'So ward Ephrons Feld, das in der Makpela gegenüber Mamre lag, das Feld samt der Höhle darin und allen Bäumen auf dem Feld und in seinem ganzen Umkreise');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'rechtskräftig Abrahams Eigentum im Beisein der Söhne Chets, all derer, die Zutritt zum Tore seiner Stadt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Danach begrub Abraham sein Weib Sara in der Höhle des Feldes der Makpela gegenüber Mamre, das ist Hebron, im Lande Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'So ward das Feld mit der Höhle darin rechtskräftig des Abraham Erbbegräbnis unter Zustimmung der Söhne Chets.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham aber war alt und hochbetagt geworden, und der Herr hatte Abraham in allem gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Da sprach Abraham zu seinem Knecht, seinem Hausältesten, der über all seinem Eigentume waltete: \"Lege deine Hand unter meine Lende!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Ich lasse dich schwören beim Herrn, dem Gott des Himmels und der Erde, daß du meinem Sohn kein Weib freiest von den Töchtern der Kanaaniter, in deren Mitte ich wohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Nein! Du ziehst in mein Land und zu meiner Verwandtschaft und freist für Isaak, meinen Sohn, ein Weib.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Da sprach der Knecht zu ihm: \"Wenn mir aber das Weib in dies Land nicht folgen will? Soll ich dann deinen Sohn in jenes Land, aus dem du gezogen, wieder zurückbringen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Da sprach Abraham zu ihm: \"Hüte dich, meinen Sohn dorthin zurückzubringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Der Herr, des Himmels Gott, der mich aus meinem Vaterhaus und meinem Heimatland geholt und der zu mir geredet und mir feierlich geschworen: \'Ich gebe deinem Stamme dies Land\', derselbe sendet seinen Engel vor dir her, daß du ein Weib dorther für meinen Sohn freiest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Und sollte dir das Weib nicht folgen, dann bist du dieses Eides ledig. Doch keinesfalls darfst du meinen Sohn dorthin verbringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Knecht seine Hand unter die Lende seines Herrn Abraham und schwur ihm auf dies Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Dann nahm der Knecht zehn Kamele von seines Herrn Kamelen und schickte sich zur Abreise an, im Besitz der Vollmacht über das ganze Vermögen seines Herrn. So brach er auf und zog nach Aram Naharaim, zu der Stadt Nachors.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Da ließ er die Kamele draußen vor der Stadt am Brunnen lagern, zur Abendzeit, um die Zeit, wann die Weiber zum Wasserholen herauskommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Er sprach: \"Herr, du Gott Abrahams, meines Herrn! Laß es mir heute glücken und zeige dich gnädig gegen Abraham, meinen Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Hier stehe ich am Wasserquell; der Stadtleute Töchter kommen jetzt zum Wasserschöpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Das Mädchen nun sei es, dem ich sage: \'Neige deinen Krug, auf daß ich trinke!\' und das antwortet: \'Trink! Und auch deine Kamele will ich tränken.\' Sie hast du für deinen Knecht Isaak bestimmt, und an ihr erkenne ich, daß du Huld an meinem Herrn geübt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Noch hatte er nicht ausgeredet, da kam Rebekka heraus, die dem Betuel, dem Sohne Milkas, des Weibes Nachors, Abrahams Bruders, geboren war, mit ihrem Krug auf der Schulter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Das Mädchen war überaus schön, eine Jungfrau, die noch keinen Mann erkannt hatte. Sie stieg zum Quell hinab, füllte ihren Krug und stieg heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da lief ihr der Knecht entgegen und sprach: \"Laß mich aus deinem Krug ein wenig Wasser schlürfen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Sie sprach:\"Trink, mein Herr!\", und geschwind ließ sie den Krug auf die Hand nieder und gab ihm zu trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Als sie ihn hatte genug trinken lassen, sprach sie: \"Ich will auch deinen Kamelen schöpfen, bis sie sich satt getrunken haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und eilends goß sie ihren Krug in die Tränkrinne, lief wieder zum Brunnen, Wasser zu schöpfen, und schöpfte so für alle seine Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Der Mann aber sah ihr zu, gespannt zu erfahren, ob der Herr ihm seine Reise habe glücken lassen oder nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Wie sich nun die Kamele sattgetrunken hatten, nahm der Mann einen goldenen Stirnring, einen halben Ring schwer, und legte zwei Armspangen an die Arme, zehn Ringe Goldes schwer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Und er sprach: \"Wessen Tochter bist du? Sag mir\'s doch! Ist wohl Platz in deines Vaters Haus für uns zum Übemachten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie sprach zu ihm: \"Ich bin die Tochter des Betuel, den Milka dem Nachor einst geboren hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Dann sprach sie zu ihm: \"Stroh und Futter haben wir in Menge sowie Platz zum Übernachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da neigte sich der Mann, warf sich vor dem Herrn nieder und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, '\"Gepriesen sei der Herr, meines Herrn Abraham Gott, der seine Huld und Treue meinem Herrn nicht vorenthalten! Ich bin da auf dem rechten Wege; mich hat der Herr zum Haus der Brüder meines Herrn geführt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Das Mädchen aber lief und berichtete im Hause ihrer Mutter dies Begebnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebekka aber hatte einen Bruder namens Laban; Laban lief nun zu dem Mann an den Quell hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Kaum hatte er aber den Stirnring und die Spangen an den Armen seiner Schwester gesehen und seiner Schwester Rebekka Bericht vernommen: \"So hat der Mann zu mir gesprochen\", kam er schon zu dem Manne, dieser aber stand noch bei den Kamelen an dem Quell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Er sprach: \"Komm, du Gesegneter des Herrn! Warum stehst du da draußen? Habe ich doch das Haus aufgeräumt und Platz für die Kamele gemacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'So brachte der Mann die Kamele ins Haus und schirrte sie ab; dann brachte jener Stroh und Futter für die Kamele und Wasser zum Füßewaschen für ihn und die Männer bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Dann setzte man ihm zu essen vor; er aber sprach: \"Ich esse nicht eher, als bis ich meine Sache vorgebracht.\" Sie sagten: \"So rede!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Er sprach: \"Ich bin Abrahams Knecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Reich gesegnet hat der Herr meinen Herrn, daß er zu großem Wohlstande gelangte. Er hat ihm Schafe und Rinder, Silber und Gold geschenkt, Sklaven, Mägde, Kamele und Esel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Nun gebar auch Sara, meines Herrn Weib, meinem Herrn einen Sohn noch nach ihrem Altern. Ihm übergab er seinen ganzen Besitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Nun ließ mich mein Herr also schwören: \'Du darfst für meinen Sohn kein Weib freien von den Töchtern der Kanaaniter, in deren Land ich wohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Nein! Du ziehst zu meines Vaters Haus und zu meiner Sippe und freist meinem Sohne ein Weib.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Da sprach ich zu meinem Herrn: \'Wenn aber das Weib mir nicht folgen will?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sagte er zu mir: \'Der Herr, vor dessen Antlitz ich gewandelt, wird seinen Engel mit dir senden; dann läßt er deine Reise wohl gelingen, und du freist meinem Sohne ein Weib aus meiner Sippe, und zwar aus meines Vaters Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Nur dann sollst du meines Eides ledig sein. Kommst du zu meiner Sippe und geben sie dir nichts, dann bist du meines Eides ledig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Nun kam ich heute zum Quell; da sprach ich: Herr, Gott Abrahams, meines Herrn! Läßt du mir meine Reise, die ich unternommen, wohl gelingen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Hier stehe ich am Wasserquell. Nun sei es das junge Mädchen, das zum Schöpfen kommt und das ich anrede: \'Laß mich ein wenig Wasser aus deinem Kruge trinken!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und das mir sagt: \'Trink du selber! Und auch den Kamelen will ich schöpfen!\' Sie ist das Weib, das der Herr dem Sohne meines Herrn bestimmt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Kaum hatte ich so bei mir geschlossen, da kam Rebekka heraus, den Krug auf der Schulter, stieg zum Quell hinab und schöpfte. Ich sprach zu ihr: \'Gib mir zu trinken!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Da ließ sie eilends ihren Krug herab und sprach: \'Da! Trink! Und auch deine Kamele will ich tränken.\' Da trank ich, und da tränkte sie auch die Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Nun fragte ich sie und sprach: \'Wessen Tochter bist du?\' Sie sprach: \'Die Tochter des Nachorsohnes Betuel, den jenem Milka einst geboren.\' Da legte ich den Ring ihr an die Stirn und die Spangen an die Arme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Alsdann verneigte ich mich, warf mich vor dem Herrn nieder und pries den Herrn, meines Herrn Abraham Gott, der mich auf rechten Weg geführt, die Tochter eines Bruders meines Herrn für seinen Sohn zu freien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Wollt ihr nun Liebe und Treue meinem Herrn erweisen, so sagt es mir! Wo nicht, so sagt\'s mir auch, daß ich mich zur Rechten oder Linken wende!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antworteten Laban und Betuel und sprachen: \"Das kommt vom Herrn; wir können weder gut noch übel dich bescheiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Rebekka steht dir zur Verfügung. Nimm sie und geh, daß sie dem Sohne deines Herrn zum Weibe werde, wie der Herr gesagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Als Abrahams Knecht ihre Worte hörte, warf er sich vor dem Herrn auf die Erde nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Dann zog der Knecht silberne und goldene Geräte und Gewänder hervor und schenkte sie Rebekka; ihrem Bruder und ihrer Mutter gab er Kleinodien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Sie aßen nun und tranken, er und die Männer bei ihm und blieben über Nacht. Am anderen Morgen, als sie aufstanden, sprach er: \"Entlaßt mich zu meinem Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Da sprachen ihr Bruder und ihre Mutter: \"Laß noch das Mädchen einige Tage oder doch wenigstens zehn bei uns! Dann mag sie ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Da sprach er zu ihnen: \"Haltet mich nicht auf! Der Herr hat meine Reise glücken lassen. Entlasset mich, daß ich zu meinem Herrn ziehe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Sie sprachen: \"Wir wollen das Mädchen rufen und sie selbst befragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Da riefen sie Rebekka und sprachen zu ihr: \"Willst du mit diesem Manne ziehen?\" Sie sagte: \"Ja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Da ließen sie ihre Schwester Rebekka mit ihrer Amme ziehen, ebenso den Knecht Abrahams mit seinen Leuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekka und sprachen zu ihr: \"Unsere Schwester, werde du zu ungezählten Tausenden! Mögen deine Nachkommen das Tor ihrer Hasser besetzen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Dann brach Rebekka mit ihren Mägden auf; sie ritten auf den Kamelen und folgten dem Manne. So nahm der Knecht Rebekka und zog von dannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber war vom Brunnen Lachaj Roi hergekommen. Er wohnte nunmehr im Südland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Nun ging Isaak zum Betrachten bei Abendanbruch aufs Feld hinaus. Wie er aber die Augen erhob, kamen Kamele daher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Auch Rebekka erhob ihre Augen und erblickte Isaak. Da beugte sie sich vom Kamele herab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und sprach zu dem Knechte: \"Wer ist der Mann da drüben, der uns auf dem Felde entgegenkommt?\" Der Knecht sprach: \"Das ist mein Herr.\" Da nahm sie den Schleier und verhüllte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Der Knecht aber erzählte dem Isaak alles, was er ausgerichtet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Da führte Isaak sie in seiner Mutter Sara Zelt. Er freite Rebekka, und sie ward sein Weib, und er gewann sie lieb. So tröstete sich Isaak über seiner Mutter Verlust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham aber nahm nochmals ein Weib, namens Ketura.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Und sie gebar ihm Zimran, Joksan, Medan, Midian, Isbak und Suach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksan aber hatte Seba und Dedan gezeugt, und Dedans Söhne wurden zu Asuritern, Letusitern und Lëumitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Und Midians Söhne sind Epha, Epher, Chanok, Abida und Eldaa; all dies sind Söhne der Ketura.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Dann übergab Abraham all sein Eigentum dem Isaak.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Den Nebenweibersöhnen aber, die Abraham besaß, hatte Abraham Geschenke gegeben; er ließ sie zugunsten seines Sohnes Isaak, noch bei seinen Lebzeiten, ostwärts ins Ostland ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Dies ist der Lebensjahre Abrahams Dauer, die er durchlebte, 175 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und Abraham verschied und starb in schönem Alter, alt und lebenssatt, und ward zu seinen Stammesgenossen versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Ihn begruben seine Söhne Isaak und Ismael in der Höhle der Makpela, auf des Chittiters Ephrons, des Socharsohnes, Feld, Mamre gegenüber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'auf dem Feld, das Abraham von Chets Söhnen gekauft. Dort waren Abraham und sein Weib Sara begraben worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Nach Abrahams Tode segnete Gott seinen Sohn Isaak; Isaak aber wohnte bei dem Brunnen Lachaj Roi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist die Geschlechterfolge des Abrahamsohnes Ismael den die Ägypterin Hagar, Saras Magd, dem Abraham geboren hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Dies sind die Namen der Söhne Ismaels nach ihren Namen und ihrem Stammbaum: Ismaels Erstgeborener Nebajot, Kedar, Adbeel, Mibsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Massa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Chadad, Tema, Jetur, Naphis und Kedma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dies sind die Söhne Ismaels und dies ihre Namen nach ihren Gehöften und Zeltlagern, zwölf Fürsten nach ihren Stammverbänden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies war Ismaels Lebensdauer: 137 Jahre; da verschied er. Er starb und ward zu seinen Stammesgenossen versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Sie lagerten von Chavila bis Schur, östlich von Ägypten und bis gen Assur hin. Er fiel zu Lebzeiten all seiner Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dies ist die Geschlechterfolge des Abrahamsohnes Isaak: Abraham hat Isaak gezeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaak aber war 40 Jahre alt, als er sich Rebekka, des Aramäers Betuel Tochter, aus Paddan Aram, die Schwester des Aramäers Laban, zum Weibe nahm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak aber flehte zum Herrn für sein Weib, weil es unfruchtbar war. Und der Herr ließ sich von ihm erbitten, und so ward sein Weib Rebekka guter Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Aber die Kinder rannten einander in ihrem Leibe an. Da sprach sie: \"Steht\'s so, warum trifft es gerade mich?\" Und sie ging den Herrn befragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Da sprach der Herr zu ihr: \"Zwei Völker sind in deinem Leibe, und zwei Stämme scheiden sich aus deinem Schoße. Ein Stamm beherrscht den anderen; lang wird der jüngere dienstbar sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Als ihre Zeit kam zum Gebären, da waren Zwillinge in ihrem Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der erste, rötlich, kam wie ein haariger Mantel hervor, und man nannte ihn Esau.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Danach kam sein Bruder hervor, und er hielt mit seiner Hand die Ferse Esaus. So nannte man ihn Jakob. Isaak aber war 60 Jahre alt, als sie geboren wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Die Knaben wuchsen nun heran. Esau ward ein tüchtiger Jäger, ein Mann der Steppe; Jakob aber war ein schlichter Mann, der bei den Zelten blieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaak aber liebte Esau; denn er sprach gern von der Jagd. Rebekka aber liebte Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Einst kochte Jakob ein Gericht; da kam Esau ganz erschöpft aus der Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Und Esau sprach zu Jakob: \"Laß mich doch eilends von dieser roten Zukost genießen! Denn ich bin erschöpft.\" Deshalb nannte man ihn Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Da sprach Jakob: \"Verkaufe mir zuvor dein Erstgeburtsrecht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau sprach: \"Ich muß sonst sterben. Was nützt mir da die Erstgeburt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob sprach: \"Schwöre mir zuvor!\" Da schwur er ihm und verkaufte sein Erstgeburtsrecht an Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jakob aber gab Esau Brot und das Linsengericht. Da aß er und trank, stand auf und ging von hinnen. So verscherzte Esau das Erstgeburtsrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Nun kam eine Hungersnot ins Land, eine andere als jene frühere zu Abrahams Zeiten. So zog Isaak zum Philisterkönig Abimelech nach Gerar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da erschien ihm der Herr und sprach: \"Zieh nicht nach Ägypten hinab! Bleib in dem Land, das ich dir anweise!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bleib in diesem Lande zu Gast! Und ich will mit dir sein und dich segnen; denn dir und deinem Stamm gebe ich all diese Lande; dann erfülle ich den Schwur, den ich deinem Vater Abraham geschworen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Dann mehre ich deinen Stamm wie des Himmels Sterne und gebe deinem Stamm all diese Lande. In deinem Stamm sollen sich der Erde Völker alle segnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'zum Lohn dafür, daß Abraham auf meine Stimme gehört hat; er befolgte mein Gebot, meine Satzungen, Gesetze und Vorschriften.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'So blieb Isaak zu Gerar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Als aber die Leute des Ortes nach seinem Weibe fragten, sprach er: \"Sie ist nur meine Schwester\"; denn er fürchtete sich zu sagen: \"Sie ist mein Weib\"; sonst könnten mich die Leute des Ortes umbringen; denn Rebekka ist schön.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er längere Zeit dort gewesen war, geschah es, daß der Philisterkönig Abimelech zum Fenster hinausschaute. Da sah er Isaak mit seinem Weib Rebekka kosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da rief Abimelech den Isaak herbei und sprach: \"Also dein Weib ist sie! Wie hast du sagen können: \'Sie ist meine Schwester!\'?\" Da sprach Isaak zu ihm: \"Ich habe gedacht, ich müßte ihretwegen sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech sprach: \"Was hast du uns da getan? Wie leicht hätte einer aus dem Volke deinem Weibe beiwohnen können. Dann hättest du Schuld über uns gebracht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Da gebot Abimelech allem Volke: \"Wer diesen Mann und sein Weib berührt, soll des Todes sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isaak aber säte in jenem Lande. Und er erntete in jenem Jahre hundert Speicher voll. So segnete der Herr ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Und so ward der Mann reich und immer reicher, bis er schwer reich geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Er besaß Schaf- und Rinderherden und viel Arbeitsvieh. Da beneideten ihn die Philister.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Und die Philister verschütteten alle Brunnen, die seines Vaters Knechte bei seines Vaters Abraham Lebzeiten gegraben, und füllten sie mit Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Und Abimelech sprach zu Isaak: \"Zieh fort von uns! Du bist ja mächtiger geworden, als uns lieb.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Und Isaak zog von da weg und lagerte sich im Tale von Gerar und wohnte da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Da grub Isaak die Wasserbrunnen wieder auf, die man in seines Vaters Abrahams Tagen gegraben und die nach Abrahams Tod die Philister verschüttet hatten, und benannte sie wieder mit den Namen, die ihnen sein Vater gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Auch gruben Isaaks Knechte im Tale nach und fanden dort einen Brunnen fließenden Wassers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Die Hirten von Gerar aber stritten mit Isaaks Knechten und sprachen: \"Unser ist das Wasser.\" Da nannte man den Brunnen Esek, weil sie dort gestritten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Dann bohrten sie einen anderen Brunnen; aber auch um diesen stritten sie, und man nannte ihn Sitna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Er zog von dort weiter und grub einen anderen Brunnen. Um diesen stritten sie nicht mehr. Und er nannte ihn Rechobot und sprach: \"Nun hat der Herr uns freien Raum geschaffen, und wir können im Lande sorglos sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Von dort zog er nach Beerseba hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und der Herr erschien ihm in selbiger Nacht und sprach: \"Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht! Ich bin mit dir. Ich segne dich und mehre deinen Stamm um meines Dieners Abraham Willen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Und er erbaute dort einen Altar und rief den Namen des Herrn an. Er schlug auch hier sein Zelt auf. Und Isaaks Knechte gruben dort einen Brunnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Da kam Abimelech zu ihm aus Gerar, mit seinem Vertrauten Achuzat und seinem Heerführer Pikol.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Da sprach Isaak zu ihnen: \"Warum kommt ihr zu mir? Ihr hasset mich doch und jagtet mich von euch fort?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie sprachen: \"Wir haben gesehen, daß der Herr mit dir ist. Da sagten wir: Zwischen uns und dir sei ein Eid! Wir wollen einen Bund mit dir schließen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns kein Übel tust, wie wir dich nicht angetastet, sondern dir bloß Gutes getan; wir entließen dich doch in Frieden. Du bist ja der Gesegnete des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da gab er ihnen ein Mahl, und sie aßen und tranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Frühmorgens schwuren sie einander zu. Dann verabschiedete sie Isaak, und sie gingen von ihm in Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Am selben Tage aber kamen Isaaks Knechte und machten ihm Meldung über den Brunnen, den sie gegraben; sie sagten zu ihm: \"Wir haben Wasser gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Da nannte er ihn Siba; daher heißt die Stadt bis auf diesen Tag Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Als Esau 40 Jahre alt ward, heiratete er des Chittiters Beeri Tochter Judith, ebenso des Chittiters Elon Tochter Basemat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Sie waren ein schwerer Kummer für Isaak und Rebekka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Als Isaak nun alt geworden und seine Augen erblindet waren, rief er seinen älteren Sohn Esau und sprach zu ihm: \"Mein Sohn!\" Der sprach zu ihm: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Da sprach er: \"Ich bin jetzt alt geworden und kann täglich sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Nimm nun dein Jagdgerät, dein Wehrgehänge und deinen Bogen! Gehe aufs Feld und jage mir ein Wild!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Dann bereite mir Leckerbissen, wie ich sie liebe, und bringe sie zum Essen, auf daß dich meine Seele segne, bevor ich sterbe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka aber hatte gelauscht, wie Isaak mit seinem Sohne Esau sprach. Esau ging nun aufs Feld, Wild zum Vorsetzen zu jagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Da sprach Rebekka zu ihrem Sohne Jakob also: \"Ich habe eben gehört, wie mit deinem Bruder Esau dein Vater redete und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\'Hol mir ein Wild und bereite mir Leckerbissen zum Essen! Dann segne ich dich mit des Herrn Zustimmung vor meinem Tode.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Nun, mein Sohn, folg meinem Rat, was ich dich heiße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Geh zum Kleinvieh! Hol mir von dort zwei schöne Ziegenböckchen, daß ich sie für deinen Vater zu Leckerbissen bereite, wie er\'s liebt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Dann bringst du sie deinem Vater zum Essen, auf daß er dich segne vor seinem Tode.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Da sprach Jakob zu seiner Mutter Rebekka: \"Aber mein Bruder Esau ist sehr stark behaart, indes ich glatt bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht betastet mich mein Vater; dann stehe ich vor ihm als Possenreißer da und bringe über mich nur Fluch, nicht Segen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sprach seine Mutter zu ihm: \"Auf mich falle die Verfluchung, die dir gilt, mein Sohn! Folge meinem Rat! Geh hin und hol es mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er, holte und brachte es seiner Mutter, und seine Mutter bereitete Leckerbissen, wie sein Vater sie liebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Dann holte Rebekka ihres ältesten Sohnes Esau Kleider, die sie im Hause drinnen hatte, und zog sie ihrem jüngeren Sohne Jakob an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Die Ziegenböckchenfelle aber hatte sie um seine Arme und seinen glatten Hals gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Dann gab sie die Leckerbissen samt dem Brot, wie sie\'s bereitet hatte, ihrem Sohne Jakob in die Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'So kam er zu seinem Vater und sprach: \"Mein Vater!\" Er antwortete: \"Hier bin ich. Wer bist du, mein Sohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Da sprach Jakob zu seinem Vater: \"Ich bin dein Erstgeborener, Esau. Ich habe getan, wie du mir gesagt. Auf! Iß von meinem Wildbret, auf daß mich deine Seele segne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Da sprach Isaak zu seinem Sohn: \"Wie hast du\'s, mein Sohn, so schnell gefunden?\" Er sprach: \"Der Herr, dein Gott, hat es mir in den Weg laufen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: \"Tritt näher, mein Sohn, daß ich dich betaste! Bist du wirklich mein Sohn Esau? Bist du\'s nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Da trat Jakob näher zu seinem Vater Isaak. Er betastete ihn und sprach: \"Die Stimme ist zwar Jakobs Stimme; die Arme aber sind Esaus Arme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er erkannte ihn nicht; denn seine Arme waren wie die seines Bruders Esau behaart. So gab er ihm den Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Er sprach: \"Du bist also Esau, mein Sohn?\" Er sprach: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: \"So bring\'s mir her, daß ich von meines Sohnes Wildbret esse, damit dich meine Seele segne!\" Da brachte er es ihm, und er aß; dann brachte er ihm Wein, und er trank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Nun sprach sein Vater Isaak zu ihm: \"Tritt näher und küsse mich, mein Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Da trat er näher und küßte ihn. Da roch er den Duft seiner Kleider, segnete ihn und sprach: \"Wahrhaftig, meines Sohnes Duft ist wie der Duft des Feldes, das der Herr gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Dir gebe Gott vom Himmelstau und von der Erde besten Früchten, des Kornes und des Weins die Fülle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Dir sollen Völker dienen und Stämme sich vor dir verneigen! Sei Herrscher aber deine Brüder! Die Söhne deiner Mutter sollen sich vor dir verneigen! Wer dich verflucht, der sei verflucht! Und wer dich segnet, sei gesegnet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Wie aber Isaak den Segen über Jakob beendet und Jakob kaum seinen Vater Isaak verlassen, kam sein Bruder Esau von seiner Jagd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Er bereitete gleichfalls Leckerbissen und brachte sie seinem Vater. Er sprach zu seinem Vater: \"Mein Vater richte sich auf und esse von seines Sohnes Wildbret auf daß deine Seele mich segne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Da sprach sein Vater Isaak zu ihm: \"Wer bist du?\" Er sprach: \"Ich bin dein Sohn, dein Erstgeborener, Esau.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da erschrak Isaak über alle Maßen und sprach: \"Wer in aller Welt ist der gewesen, der ein erjagtes Wild mir brachte, daß ich gehörig aß, bevor du kamst? Ihn segnete ich, und gesegnet wird er bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Wie Esau die Worte seines Vaters vernahm, schrie er überlaut und bitterlich und sprach zu seinem Vater: \"Mein Vater, segne auch mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Er sprach: \"Dein Bruder ist mit List gekommen, und so nahm er dir deinen Segen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: \"Heißt man ihn nicht Jakob? Schon zum zweitenmal betrog er mich. Mein Erstgeburtsrecht hat er genommen; jetzt nimmt er mir auch den Segen.\" Dann sprach er: \"Hast du mir keinen Segen aufbewahrt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Darauf erwiderte Isaak und sprach zu Esau: \"Ich habe ihn zum Herrn über dich gesetzt. All seine Brüder habe ich ihm zu Knechten gegeben und ihn mit Korn und Most belehnt. Was in aller Welt kann ich dir tun, mein Sohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Da sprach Esau zu seinem Vater: \"Hast du nur den einen Segen, mein Vater? Mein Vater, segne doch auch mich!\" und Esau fing laut zu weinen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Darauf hub sein Vater Isaak an und sprach zu ihm: \"Fern von der Erde edlen Frucht wird dein Wohnsitz sein, und fern vom Tau des Himmels droben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Von deinem Schwerte wirst du leben und deinem Bruder dienstbar sein, nur wenn du heimatlos umherschweifest, dann hältst du deinem Nacken fern sein Joch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'So ward Esau dem Jakob feind wegen des Segens, den ihm sein Vater gegeben. Und Esau dachte bei sich: \"Kommen die Trauertage um meinen Vater, dann töte ich meinen Bruder Jakob.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Der Rebekka verriet sich aber das Vorhaben ihres älteren Sohnes Esau. So sandte sie hin, ließ ihren jüngeren Sohn Jakob rufen und sprach zu ihm: \"Siehe, dein Bruder Esau sinnt auf Rache gegen dich und will dich töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'So folge meinem Rat, mein Sohn! Brich auf und mach, daß du geschwind zu meinem Bruder Laban nach Charan kommst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Dann bleibe eine Zeit bei ihm, bis sich deines Bruders Groll legt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Läßt dann deines Bruders Zorn von dir ab und vergißt er, was du ihm getan, dann sende ich und lasse dich von dort holen. Warum soll ich euch beide an einem Tag verlieren?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Und Rebekka sprach zu Isaak: \"Ich bin des Lebens überdrüssig der Töchter Chets wegen. 47 Holt sich auch Jakob ein Weib von den Töchtern Chets, wie diese da aus des Landes Töchtern, wozu lebte ich noch?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da rief Isaak den Jakob, segnete ihn, beschied ihn und sprach zu ihm: \"Du darfst kein Weib aus Kanaans Töchtern freien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mach dich auf und zieh nach Paddan Aram, zum Haus der Betuel, des Vaters deiner Mutter, und freie dir dort ein Weib, eine der Töchter Labans, deines Mutterbruders!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Gott, der Allmächtige, segne dich, mache dich fruchtbar und mehre dich, daß du zu einer Menge Völker werdest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Er verleihe dir Abrahams Segen, dir und deinem Stamme nach dir, daß du deiner Pilgerschaft Land zu eigen bekommst, das Gott dem Abraham verliehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'So entließ Isaak den Jakob, und er zog nach Paddan Aram zu Betuels Sohn Laban, dem Aramäer, dem Bruder der Rebekka, der Mutter Jakobs und Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Esau aber hatte bemerkt, daß Isaak den Jakob gesegnet und ihn nach Paddan Aram gesandt, sich dort ein Weib zu holen, und daß er ihn segnete und so beschied: \'Du darfst kein Weib aus Kanaans Töchtern nehmen\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob auf seinen Vater und seine Mutter hörte und nach Paddan Aram ging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Da merkte Esau, daß Kanaans Töchter seinem Vater Isaak mißfielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'So ging Esau zu Ismael und nahm Machalat, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajots, zu seinen Weibern hin sich zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jakob aber zog von Beerseba aus und wanderte nach Charan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Und er kam an eine gewisse Stätte und übernachtete hier, weil die Sonne unterging. Er nahm einen von den Steinen der Stätte und machte ein Lager für sein Haupt und legte sich an dieser Stätte schlafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Da träumte ihm: Auf der Erde stand eine Treppe, deren Spitze bis zum Himmel reichte, und darauf stiegen die Engel Gottes auf und ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Da stand auch der Herr vor ihn, und sprach: \"Ich bin der Herr, der Schutzgott deines Vaters Abraham und Isaaks; das Land, auf dem du ruhst, das gebe ich dir und deinem Stamme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Dann wird dein Stamm dem Staub der Erde gleich; nach Westen, Osten, Norden, Süden breitest du dich aus. Dann segnen sich in dir der Erde Geschlechter alle, sowie in deinem Stamme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Fürwahr, ich bin mit dir und hüte dich allüberall, wohin du gehst. Dann bringe ich dich auch zu diesem Boden wieder. Denn ich verlasse nimmer dich, bis ich vollbracht, was ich dir jetzt verheißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da erwachte Jakob aus seinem Schlafe und sprach: \"Wahrlich, der Herr ist an dieser Stätte, und ich wußte es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und er erschauerte und sprach: \"Wie schauervoll ist diese Stätte! Hier ist nichts anderes als Gottes Haus, und jenes ist die Himmelspforte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Frühmorgens nahm Jakob den Stein, den er zum Kopfpolster gemacht, stellte ihn als Malstein auf und goß Öl oben darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Und er nannte jenen Ort Betel; vorher aber hieß die Stadt Luz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob machte ein Gelübde und sprach: \"Ist Gott mit mir und behütet er mich auf dem Wege, den ich gehen muß, und gibt er mir Brot zur Nahrung und Kleider zur Bedeckung');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und kehre ich heil zu meines Vaters Haus heim, dann ist der Herr mir zum Schutzgott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich als Malstein aufgestellt, wird ein Gotteshaus, und alles, was Du mir geben wirst, will ich Dir getreulich verzehnten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Da machte sich Jakob auf den Weg und wanderte ins Land der Söhne des Ostens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Er schaute aus; da war im Feld ein Brunnen, und drei Schafherden lagerten daran; denn aus diesem Brunnen pflegte man die Herden zu tränken. Der Stein aber über dem Brunnenloch war groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Waren nun alle Herden dort beisammen, dann wälzte man den Stein vom Brunnenloch und tränkte die Schafe. Dann brachte man den Stein für das Brunnenloch wieder an seine Stelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Da sprach Jakob zu ihnen: \"Brüder! Wo seid ihr her?\" Sie sagten: \"Aus Charan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Er sprach zu ihnen: \"Kennt ihr Laban, Nachors Sohn?\" Sie sprachen: \"Jawohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Er sprach zu ihnen: \"Geht\'s ihm auch gut?\" Sie sprachen: \"Ja! Und da kommt gerade seine Tochter Rachel mit den Schafen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Er sprach: \"Noch ist\'s hoch am Tag und noch zu früh, das Vieh einzutreiben. Tränket die Schafe und weidet weiter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie sprachen: \"Wir können es nicht, bis alle Herden beisammen sind; dann wälzt man den Stein vom Brunnenloch, und wir tränken die Schafe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Noch redete er mit ihnen, da kam Rachel mit den Schafen ihres Vaters; denn sie war Hirtin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Wie nun Jakob Rachel, die Tochter seines Mutterbruders Laban, erblickt hatte und die Schafe seines Mutterbruders Laban, da trat Jakob herzu und wälzte den Stein vom Brunnenloch und tränkte seines Mutterbruders Laban Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Dann küßte Jakob die Rachel und hob laut zu weinen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Und Jakob erzählte der Rachel, er sei ein Bruder ihres Vaters und zwar ein Sohn Rebekkas. Da lief sie und erzählte es ihrem Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Wie Laban solche Kunde von seinem Schwestersohne Jakob vernahm, lief er ihm entgegen, umarmte und küßte ihn und führte ihn in sein Haus; jener aber erzählte Laban die ganze Geschichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Und Laban sprach zu ihm: \"So bist du also von meinem Bein und Fleisch.\" Als er einen Monat lang bei ihm war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'sprach Laban zu Jakob: \"Wolltest du, weil du mein Bruder bist, mir umsonst dienen? Sag mir: Was soll dein Lohn sein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Nun hatte Laban zwei Töchter; die ältere hieß Lea, die jüngere Rachel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea hatte glanzlose Augen, Rachel aber war schön von Gestalt und Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob gewann Rachel lieb. Er sprach: \"Ich diene dir sieben Jahre um Rachel, deine jüngere Tochter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban sprach: \"Besser, ich gebe sie dir als einem fremden Mann. Bleib bei mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'So diente Jakob um Rachel sieben Jahre, und sie dünkten ihm wie wenige Tage, weil er sie liebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Dann sprach Jakob zu Laban: \"Gib mir mein Weib! Denn meine Zeit ist um, daß ich sie heirate.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Männer des Ortes ein und bereitete ein Gastmahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Als es Abend ward, nahm er seine Tochter Lea und führte sie ihm zu, und er wohnte ihr bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab seine Magd Zilpa seiner Tochter Lea zur Magd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Am Morgen aber war es die Lea. Da sprach er zu Laban: \"Was hast du mir da getan? Habe ich nicht um Rachel bei dir gedient? Warum hast du mich betrogen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban sprach:\"An unserem Ort ist\'s nicht der Brauch, die jüngere vor der Älteren wegzugehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Führe mit der einen die Woche zu Ende, dann werden wir dir auch die andere geben um den Dienst von weiteren sieben Jahren bei mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Und Jakob tat so und führte mit der einen die Woche zu Ende. Dann gab Laban ihm seine Tochter Rachel zum Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab seiner Tochter seine Magd Bilha zur Magd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'So wohnte er auch Rachel bei. Er liebte aber Rachel mehr als Lea, und so diente er bei ihm andere sieben Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Wie nun der Herr sah, daß Lea nicht geliebt wurde, öffnete er ihren Mutterschoß; Rachel aber blieb unfruchtbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'So empfing Lea, gebar einen Sohn und nannte ihn Ruben; denn sie sprach: \"Gesehen hat ja der Herr mein Elend. Nun wird mein Mann mich liebgewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: \"Gehört hat ja der Herr, daß ich ungeliebt bin. Darum gab er mir auch diesen.\" Und sie nannte ihn Simeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: \"Nun endlich wird sich mein Mann mit mir verbinden; drei Söhne habe ich ihm geboren.\" Darum nannte man ihn Levi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: \"Endlich kann ich den Herrn lobpreisen.\" Darum nannte sie ihn Juda. Danach hörte sie mit Gebären auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Als Rachel sah, daß sie dem Jakob kein Kind gebar, ward Rachel auf ihre Schwester neidisch. Sie sprach zu Jakob: \"Schaff mir Kinder! Wenn nicht, dann sterbe ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Da ging Jakob die Geduld gegenüber Rachel aus, und er sprach: \"Bin ich an Gottes Statt, der dir die Leibesfrucht versagt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Sie sprach: \"Hier ist meine Magd Bilha. Wohne ihr bei, daß sie für meinen Schoß gebäre und auch ich durch sie zu Kindern komme!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'So gab sie ihm ihre Magd Bilha zum Weib, und Jakob wohnte ihr bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha ward guter Hoffnung und gebar Jakob einen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sprach Rachel: \"Mir hat Gott Recht verschafft; auch hat er auf meine Stimme gehört und mir einen Sohn geschenkt.\" Deshalb nannte sie ihn Dan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Wieder ward Bilha, Rachels Magd, guter Hoffnung und gebar einen zweiten Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rachel: \"Gotteskämpfe habe ich gekämpft mit meiner Schwester und habe gesiegt.\" Und sie nannte ihn Naphtali.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Als Lea sah, daß sie aufhörte zu gebären, nahm sie ihre Magd Zilpa und gab sie Jakob zum Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Und Leas Magd Zilpa gebar Jakob einen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: \"Glück auf!\" Und sie nannte ihn Gad.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Und Leas Magd Zilpa gebar Jakob einen zweiten Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: \"Heil mir! Mich preisen Töchter glücklich.\" Und sie nannte ihn Asser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben ging in den Tagen der Weizenernte aus und fand auf dem Felde Liebesäpfel und brachte sie seiner Mutter Lea. Da sprach Rachel zu Lea: \"Gib mir doch von deines Sohnes Liebesäpfeln!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sie sprach zu ihr: \"lst\'s nicht genug, daß du meinen Mann wegnimmst, mußt du nun auch noch die Liebesäpfel meines Sohnes wegnehmen?\" Da sprach Rachel: \"So schlafe er diese Nacht bei dir für die Liebesäpfel deines Sohnes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Als Jakob des Abends vom Felde kam, ging Lea ihm entgegen und sprach zu ihm: \"Bei mir mußt du einkehren; denn ich habe dich mir für meines Sohnes Liebesäpfel ausbedungen.\" Und er schlief bei ihr in jener Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott erhörte Lea, und sie empfing und gebar Jakob einen fünften Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sprach Lea: \"Gott hat mir meinen Lohn für das gegeben, was ich meiner Verwandten für meinen Mann gegeben habe.\" Und sie nannte ihn Issakar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Wieder ward Lea guter Hoffnung und gebar Jakob einen sechsten Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Und Lea sprach: \"Gott hat mir eine schöne Spende gespendet; diesmal bleibt mein Mann bei mir; denn sechs Söhne habe ich ihm geboren.\" Und sie nannte ihn Zabulon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Danach gebar sie eine Tochter und nannte sie Dina.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Da erinnerte sich Gott der Rachel. Und Gott erhörte sie und öffnete ihr den Mutterschoß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Und sie ward guter Hoffnung und gebar einen Sohn. Da sprach sie: \"Weggenommen hat Gott meine Schmach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und sie nannte ihn Joseph, indem sie sagte: \"Noch einen Sohn schenkte mir der Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Als Rachel den Joseph geboren hatte, sprach Jakob zu Laban: \"Entlaß mich, daß ich in meine Heimat ziehe, in mein Land!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Weiber und meine Kinder, um die ich dir gedient! Dann gehe ich. Du kennst selbst meine Dienste, mit denen ich dir gedient.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Da sprach Laban zu ihm: \"Mit Vergunst! Ich hab\'s erraten: Deinetwegen hat der Herr mich gesegnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Und er sprach: \"Nenne deine Lohnforderung an mich, damit ich sie erfülle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Er sprach zu ihm: \"Du weißt selbst, wie ich dir gedient habe und was aus deinem Viehstand bei mir geworden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Denn wenig ist es gewesen, was du vor mir hattest. Dann aber mehrte es sich in Fülle. So hat dich der Herr nach meiner Ankunft gesegnet. Nun aber, wann soll ich für meinen Hausstand sorgen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Er sprach: \"Was soll ich dir geben?\" Da sprach Jakob: \"Gar nichts sollst du mir geben. Gewährst du mir folgendes, dann will ich aufs neue deine Schafe sorgsam weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich gehe heute alle deine Schafe durch. Entferne daraus jegliches gesprenkelte und gescheckte Stück! Dann ist jedes Schwarze bei den Lämmern und alles Scheckige und Gesprenkelte bei den Ziegen mein Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Dann zeugt meine Ehrlichkeit in Zukunft für mich vor dir, kommst du, mich zu belohnen. Was nicht gesprenkelt und nicht scheckig bei den Ziegen und was nicht schwarz bei Lämmern ist, gelte bei mir als gestohlen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Und Laban sprach: \"Es sei, wie du gesagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'So sonderte er am selben Tage die gestreiften und scheckigen Böcke ab, alle gesprenkelten und scheckigen Ziegen, alles, woran Weiß war, und alles Schwarze bei den Lämmern und übergab es seinen Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Dann ließ er einen Zwischenraum von drei Tagereisen zwischen sich und Jakob; Jakob aber weidete Labans übriges Vieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Da holte Jakob frische Stäbe von Pappeln, Mandelbäumen und Platanen und schälte daran weiße Streifen heraus, das Weiße an den Stäben bloßlegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Dann stellte er die geschälten Stäbe in die Tränkrinnen, in die Wasserrinnen, wohin die Tiere zur Tränke kamen, gerade vor die Tiere hin. Sie waren aber in Brunst, als sie zur Tränke kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'So begatteten sich die Tiere vor den Stäben. Dann warfen die Tiere gestreifte, gesprenkelte und scheckige Junge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Die Lämmer aber sonderte Jakob ab. So machte er die besten Tiere in Labans Herden zu gestreiften und ganz schwarzen Stücken und legte sich besondere Herden an, die er nicht zu Labans Herden tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Sooft fortan die Brunstzeit der kräftigen Tiere kam, legte Jakob die Stäbe den Tieren vor Augen in die Rinnen, auf daß sie sich vor den Stäben begatteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Waren aber die Tiere schwächlich, dann legte er sie nicht hin. So fielen die schwächlichen dem Laban zu, die kräftigen Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'So ward der Mann ohne Maßen reich und kam zu viel Vieh, zu Mägden und Knechten, Kamelen und Eseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Er vernahm aber die Reden der Labansöhne, die sagten: \"Jakob bringt die ganze Habe unseres Vaters an sich; von dem, was unseres Vaters war, hat er all diesen Reichtum geschaffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jakob sah auch an Labans Angesicht, daß er nicht mehr so wie früher gegen ihn war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Da sprach der Herr zu Jakob: \"Kehr in deiner Väter Land zurück, zu deiner Verwandtschaft! Ich will mit dir sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob und rief Rachel und Lea aufs Feld zu seiner Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Er sprach zu ihnen: \"Ich sehe an eures Vaters Angesicht, daß er zu mir nicht mehr so ist wie früher, und doch ist meines Vaters Gott mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ihr wißt aber, daß ich mit all meiner Kraft eurem Vater gedient habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Doch euer Vater hat mich betrogen und mir den Lohn zehnmal geändert. Aber Gott hat ihm nicht verstattet, mich zu schädigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Sprach er: \'Die Gesprenkelten seien dein Lohn!\', dann warfen alle Tiere Gesprenkelte. Und sprach er: \'Die Gestreiften seien dein Lohn!\', dann warfen alle Tiere Gestreifte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'So entzog Gott das Vieh eurem Vater und gab es mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Es war in der Brunstzeit der Tiere, da erhob ich meine Augen und sah im Traum, wie die Böcke die Schafe bespringen, gestreift, gesprenkelt und gescheckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und Gottes Engel sprach zu mir im Traum: \'Jakob!\' Ich sprach: \'Hier bin ich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Er sprach: \'Hebe deine Augen und sieh: Alle Böcke, die die Schafe bespringen, sind gestreift, gesprenkelt und gescheckt. Ich sehe ja alles, was Laban dir tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Herr, der Gott von Betel, wo du ein Steinmal gesalbt und mir ein Gelübde gemacht. Nun auf! Zieh aus diesem Land und kehr in dein Heimatland zurück!\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da antworteten Rachel und Lea und sprachen zu ihm: \"Haben wir noch Teil und Erbe im Hause unseres Vaters?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Gelten wir ihm nicht als Fremde? Er hat uns ja verhandelt. Soll er auch unseren Erlös verzehren dürfen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Ja, all der Reichtum, den Gott unserem Vater entzogen, gehört uns und unseren Kindern. Tu also ganz, wie Gott zu dir gesagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Da erhob sich Jakob, hob seine Kinder und Weiber auf die Kamele');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'und führte all sein Vieh weg und all seine Habe, die er erworben, das Vieh seines Besitzes, das er zu Paddan Aram erworben, um zu seinem Vater Isaak ins Land Kanaan zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Während Laban ging, seine Schafe zu scheren, stahl Rachel ihres Vaters Teraphim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakob aber überlistete Laban, den Aramäer; durch nichts hatte er ihn ahnen lassen, daß er fliehen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'So floh er mit all seiner Habe. Er brach auf und setzte über den Strom und nahm die Richtung auf das Gebirge Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Am dritten Tage bekam Laban die Kunde, Jakob sei entflohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da nahm er seine Brüder mit, verfolgte ihn sieben Tagereisen und holte ihn auf dem Gebirge Gilead ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Da kam Gott zu Laban, dem Aramäer, nachts im Traum und sprach zu ihm: \"Hüte dich, mit Jakob herausfordernd zum Bösen zu reden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Als Laban Jakob erreichte, hatte Jakob auf dem Berge sein Zelt aufgeschlagen; Laban aber schlug es mit seinen Brüdern auf dem Gebirge Gilead auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Und Laban sprach zu Jakob: \"Was hast du getan, daß du mich überlistet und meine Töchter wie Kriegsgefangene fortgeführt hast?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich geflohen und hast mich bestohlen? Warum hast du\'s mir nicht kundgetan? Dann hätte ich dir mit Jauchzen und Singen, mit Pauken und Zithern das Geleite gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Warum hast du mich nicht zum Abschied meine Enkel und meine Töchter küssen lassen? Nun, du hast recht töricht gehandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Ich habe die Macht, euch übel zu tun. Aber deines Vaters Gott hat gestern Nacht zu mir gesprochen: \'Hüte dich, mit Jakob herausfordernd zum Bösen zu reden!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Nun bist du eben fortgezogen, weil du dich nach deinem Vaterhause gesehnt hast. Warum hast du aber meine Götter gestohlen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da antwortete Jakob und sprach zu Laban: \"Wohl! Ich habe Angst gehabt, weil ich gedacht habe, du könntest deine Töchter mir entreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bei wem du aber deine Götter findest, der soll nicht länger leben. Erkennst du im Beisein unserer Brüder etwas als dein eigen, dann nimm es an dich!\" Jakob aber wußte nicht, daß Rachel sie gestohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'So kam Laban in Jakobs und in Leas Zelt sowie in das Zelt der beiden Mägde, fand aber nichts; dann ging er aus Leas Zelt und kam in das der Rachel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rachel aber hatte die Teraphim genommen und legte sie in die Kamelsänfte und setzte sich auf sie. Laban durchstöberte das ganze Zelt, fand aber nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Da sprach sie zu ihrem Vater: \"Sei nicht böse, mein Herr, daß ich vor dir nicht aufstehe! Mir ergeht es nach Weiberart.\" So suchte er, fand aber die Teraphim nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Da ward Jakob zornig und schalt Laban. Und Jakob hob an und sprach zu Laban: \"Was ist mein Verbrechen? Was mein Vergehen, daß du hinter mir herhetzest');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'und mir all mein Gerät durchstöberst? Was hast du von all deinem Hausrat gefunden? Leg\'s her vor meine und vor deine Brüder, daß sie zwischen uns entscheiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Zwanzig Jahre bin ich so bei dir gewesen. Deine Mutterschafe und -ziegen haben nie einen Fehlwurf, und nie habe ich deiner Herde Widder verzehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Zerrissenes habe ich nie vor dich bringen dürfen; ich mußte es ersetzen; von mir fordertest du es. So bin ich betrogen worden bei Tag und bei Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'So ist es mir ergangen: Bei Tage hat mich die Hitze gefressen und der Frost bei Nacht. Meine Augen floh der Schlaf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Volle zwanzig Jahre habe ich so in deinem Hause dir gedient, vierzehn Jahre um deine beiden Töchter und sechs um deine Schafe, und zehnmal ändertest du meinen Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Hätte ich nicht meines Vaters Gott gehabt, den Gott Abrahams und Isaaks Schrecken, leer hättest du mich ziehen lassen. Mein Abplagen und meiner Hände Mühen hat aber Gott gesehen und gestern nacht hat er entschieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Da erwiderte Laban und sprach zu Jakob: \"Mein sind die Töchter, mein die Kinder, mein das Vieh, und alles, was du siehst, gehört mir, also meinen Töchtern. Was könnte ich heute diesen tun oder ihren Kindern, die sie geboren haben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Nun komm! Wir wollen einen Bund miteinander schließen. Der Herr sei Zeuge zwischen mir und dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Und Jakob nahm einen Stein und richtete ihn als Steinmal auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Jakob aber sprach zu seinen Brüdern: \"Sammelt Steine!\" Da nahmen sie Steine und machten einen Wall. Und sie aßen dort auf dem Wall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Laban nannte ihn Jegar Sahaduta, und Jakob nannte ihn Galed.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Da sprach Laban: \"Dieser Wall ist heute Zeuge zwischen mir und dir.\" Deshalb nannte er ihn Galed.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Auch Mispa, weil er sagte: \"Der Herr wache zwischen mir und dir, wenn wir einander ferne sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ob du meine Töchter schlecht behandelst oder ob du noch andere Weiber zu meinen Töchtern nimmst, ist auch kein Mensch bei uns, bedenke: Zwischen mir und dir ist ein Gott Zeuge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Ferner sprach Laban zu Jakob: \"Hier dieser Wall und dieses Steinmal, das ich errichte zwischen mir und dir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Dieser Wall sei Zeuge und Zeuge dieses Steinmal! Ich darf diesen Wall zu dir nicht überschreiten, noch darfst du diesen Wall und dieses Steinmal zu mir überschreiten in böser Absicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Zwischen uns richte der Gott Abrahams und Nachors Gott, der Gott ihrer Väter!\" Da schwur Jakob beim Schrecken seines Vaters Isaak.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Dann schlachtete Jakob ein Schlachtopfer auf dem Berg und lud seine Brüder ein, das Mahl zu halten. Da hielten sie das Mahl und nächtigten auf dem Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Frühmorgens aber küßte Laban seine Enkel und seine Töchter und segnete sie. Dann brach Laban auf und kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Auch Jakob zog seines Wegs; da stießen Gottes Engel auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Jakob sprach, als er sie sah: \"Dies ist Gottes Heerlager\", und er nannte diesen Ort Machanaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Jakob sandte nun Boten voraus an seinen Bruder Esau ins Land Seïr, in Edoms Gefilde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Er trug ihnen folgendes auf: \"So sollt ihr sprechen: \'Meinem Herrn Esau läßt dein Sklave Jakob also melden: Bei Laban war ich zu Gast und verzögerte mich bis jetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Ich kam aber zu Rindern und Eseln, zu Schafen, Sklaven und Mägden. Und so wollte ich es meinem Herrn melden lassen, um Huld bei dir zu finden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Die Boten kehrten zu Jakob zurück und meldeten: \"Zu deinem Bruder Esau sind wir gekommen, aber schon zieht er dir entgegen mit vierhundert Mann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Da geriet Jakob in große Furcht und Bangigkeit. Dann teilte er die Leute bei sich sowie die Schafe, Rinder und Kamele in zwei Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Er dachte nämlich: Kommt Esau über das eine Lager und schlägt es, dann kann das andere Lager entrinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Und Jakob sprach: \"Gott meines Vaters Abraham! Gott meines Vaters Isaak! Herr, der du zu mir sprachst: \'Kehr in dein Land zurück, zu der Verwandtschaft! Ich will dir wohltun\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'nicht wert bin ich all der Liebe und Treue, die du deinem Diener erwiesen. Denn nur mit meinem Stock habe ich diesen Jordan überschritten, und jetzt besitze ich zwei Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Ach, rette mich aus meines Bruders Esau Hand! Ich fürchte mich vor ihm. Daß er nicht komme und mich schlage, die Mutter samt den Kindern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Du aber hast gesprochen: \'Ich will dir reichlich wohltun; dann mache ich wie Sand am Meere deinen Stamm, vor Menge nicht zu zählen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Er blieb nun dort in jener Nacht; dann nahm er aus dem, was ihm zur Hand war, ein Geschenk für seinen Bruder Esau,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, '200 Ziegen, 20 Böcke, 200 Mutterschafe und 20 Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, '30 säugende Kamele mit ihren Füllen, 40 junge Kühe, 10 junge Stiere, 20 Eselinnen und 10 Eselsfüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Er übergab diese seinen Knechten, jede Herde besonders, und sprach zu seinen Knechten: \"Ziehet mir voraus und laßt jedesmal einen Zwischenraum zwischen den Herden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Und er wies den vordersten an: \"Wenn mein Bruder Esau auf dich stößt und dich fragt: \'Wessen bist du? Wohin Willst du? Wessen sind diese da vor dir?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'so sprich: \'Deines Sklaven Jakob Geschenke sind sie, abgeschickt für Esau, meinen Herrn. Er selber folgt uns auf dem Fuße nach.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ebenso wies er den zweiten, den dritten und alle übrigen an, die die Herden trieben, und sprach: \"Genauso sollt ihr zu Esau sprechen, wenn ihr ihn treffet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Ihr sollt sagen: \'Auch dein Sklave Jakob folgt uns auf dem Fuß!\'\" Er dachte nämlich: Ablenken will ich seine Aufmerksamkeit durch das Geschenk, das mir vorausgeht; erst dann trete ich ihm vor die Augen. Vielleicht nimmt er mich gnädig auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'So ging ihm das Geschenk voraus; er selber nächtigte in jener Nacht zu Machanaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'In derselben Nacht stand er auf, nahm seine beiden Weiber, seine beiden Mägde und seine elf Kinder und führte sie über die Jabbokfurt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Er nahm sie und führte sie über den Fluß und brachte alles, was er hatte, hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Jakob blieb allein zurück; da rang mit ihm ein Mann bis zum Anbruch der Morgenröte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und als er sah, daß er ihn nicht überwände, rührte er an seine Hüftpfanne, und Jakobs Hüftpfanne ward verrenkt, als er mit ihm rang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Dann sprach er: \"Laß mich los! Die Morgenröte bricht an.\" Er sprach: \"Ich lasse dich nicht los, bevor du mich segnest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Er sprach zu ihm: \"Wie heißest du?\" Er sprach: \"Jakob.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Da sprach er: \"Fortan sollst du nicht Jakob heißen, sondern Israel. Du hast mit Gott gekämpft, und so trägst du den Sieg davon auch über Menschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Da bat Jakob und sprach: \"Tu auch deinen Namen kund!\" Er sprach: \"Warum doch fragst du mich nach meinem Namen?\" Und er segnete ihn dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jakob nannte den Ort Penuël: \"Ich habe Gott geschaut von Angesicht zu Angesicht und kam mit dem Leben davon.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Die Sonne strahlte ihm auf, als er an Penuël vorüberzog; er aber hinkte an seiner Hüfte. Darum sollen Israels Söhne bis auf diesen Tag keine Sehne des Schenkels essen, der auf der Hüftpfanne läuft, weil er Jakobs Hüftpfanne, die Sehne des Schenkels, berührt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jakob aber erhob seine Augen und schaute; da kam Esau mit 400 Mann. Da verteilte er die Kinder auf Lea, Rachel und die beiden Mägde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Und zwar stellte er die Mägde und ihre Kinder voran, dahinter Lea mit ihren Kindern und ganz hinten Rachel und Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Er selbst ging ihnen voraus und neigte sich siebenmal zur Erde, bis er zu seinem Bruder kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Da lief ihm Esau entgegen, umarmte ihn, fiel ihm um den Hals und küßte ihn. Und sie weinten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Dann erhob er seine Augen, sah die Weiber mit den Kindern und sprach: \"Was sind diese da bei dir?\" Er sprach: \"Das sind die Kinder, die Gott deinem Sklaven geschenkt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Da traten die Mägde mit ihren Kindern herzu und verneigten sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Auch Lea und ihre Kinder traten herzu und verneigten sich. Danach traten Joseph und Rachel herzu und verneigten sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Er sprach: \"Was soll dir dies ganze Lager, auf das ich gestoßen bin?\" Er sprach: \"Auf daß ich Gnade finde bei meinem Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Da sprach Esau: \"Ich habe übergenug, mein Bruder. Behalte, was dir gehört!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob sprach: \"Nicht doch! Habe ich in deinen Augen Gnade gefunden, dann mußt du meine Gabe von mir annehmen. Denn ich habe dein Antlitz gesehen, so, wie ich Gottes Antlitz sah, und du nahmst mich zu Gnaden an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch mein Grußgeschenk, das dir dargebracht ward! Denn Gott hat mich begnadet, und ich habe vollauf.\" So drang er in ihn, bis er es nahm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Dann sprach er: \"Laßt uns aufbrechen und weiterziehen! Ich halte gleichen Schritt mit dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Er aber sprach zu ihm: \"Mein Herr sieht selber, daß die Kinder zart sind, und säugende Schafe und Kinder stehen in meiner Obhut. Wollte ich sie einen Tag über Gebühr anstrengen, dann stürbe die ganze Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'So ziehe mein Herr doch vor seinem Sklaven her! Ich ziehe gemächlich weiter, im Schritte des Viehstands vor mir und im Schritte der Kinder, bis ich zu meinem Herrn nach Seïr komme!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Da sprach Esau: \"So will ich wenigstens bei dir einen Teil meiner Leute lassen.\" Er aber sprach: \"Wozu? Möchte ich nur Huld bei meinem Herrn finden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'So kehrte Esau an jenem Tag nach Seïr zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob aber zog nach Sukkot weiter und baute sich ein Haus, seinem Vieh aber machte er Laubhütten. Daher nennt man den Ort Sukkot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Und Jakob kam in friedlicher Gesinnung nach der Stadt Sichem im Lande Kanaan auf seiner Fahrt aus Paddan Aram und lagerte östlich von der Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Er kaufte das Stück Feld, wo er sein Zelt gespannt, von den Söhnen Chamors, des Herrn von Sichem, um 100 Beutel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Und er stellte dort einen Altar auf und pries bei ihm den Gott Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Einst ging Dina, Leas Tochter, die sie Jakob geboren, aus, sich unter des Landes Töchtern sehen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Da erblickte sie Sichem, der Sohn des chiwitischen Landesfürsten Chamor, entführte sie, wohnte ihr bei und tat ihr Gewalt an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Er aber hängte sich mit ganzer Seele an Jakobs Tochter Dina und gewann das Mädchen lieb. So redete er dem Mädchen zu Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Sichem sprach zu seinem Vater Chamor also: \"Freie dies Kind mir zum Weibe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob aber hatte vernommen, man habe seine Tochter Dina geschändet. Seine Söhne aber waren mit seinem Vieh auf dem Felde gewesen. So hatte Jakob bis zu ihrer Rückkehr geschwiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Da ging Sichems Vater Chamor zu Jakob, mit ihm Rücksprache zu nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Die Söhne Jakobs aber waren sofort vom Felde heimgekommen, als sie davon gehört hatten. Die Männer waren erbittert und in heftigem Zorn; denn eine Schandtat hatte er an Israel begangen, daß er Jakobs Tochter beschlief. Solches durfte nicht geschehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Chamor aber redete mit ihnen also: \"Mein Sohn Sichem hat sein Herz an eure Tochter gehängt. Gebt sie ihm doch zum Weibe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Verschwägert euch mit uns! Eure Töchter gebt ihr uns und nehmt euch unsere Töchter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Dann bleibt ihr bei uns wohnen. Das Land steht euch offen. Bleibt da und zieht umher und siedelt darin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Sichem sprach zu ihrem Vater und ihren Brüdern: \"Möchte ich Gnade in euren Augen finden! Was ihr auch von mir fordert, ich gebe es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Fordert noch soviel Kaufgeld und Geschenke von mir, ich will\'s geben, wie ihr\'s von mir fordert. Nur gebt das Mädchen mir zum Weibe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da antworteten Jakobs Söhne Sichem und seinem Vater Chamor arglistig; das Wort aber führten die, deren Vollschwester Dina er geschändet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Sie sprachen zu ihm: \"Wir können dies nicht tun, unsere Schwester einem unbeschnittenen Mann geben. Denn dies gilt uns als schmachvoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Doch unter der Bedingung willfahren wir euch, wenn ihr werdet wie wir, insofern alles Männliche bei euch beschnitten wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Dann geben wir euch unsere Töchter und nehmen uns eure Töchter und wohnen bei euch und werden so ein Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wollt ihr aber wegen der Beschneidung nicht auf uns hören, dann nehmen wir unsere Tochter und gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Und der Vorschlag gefiel Chamor, ebenso Chamors Sohne Sichem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Der Jüngling aber zauderte nicht, dies zu veranlassen; denn er hatte Gefallen an Jakobs Tochter. Auch war er im ganzen Hause seines Vaters der Angesehenste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'So kamen Chamor und sein Sohn Sichem zum Tor ihrer Stadt und redeten also zu den Männern ihrer Stadt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '\"Friedlich gesinnt sind uns diese Männer. Sie sollen im Lande wohnen und darin verkehren, hat doch das Land nach allen Seiten Raum für sie. Wir wollen ihre Töchter uns zu Weibern nehmen und ihnen unsere Töchter geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Doch einzig unter der Bedingung wollen diese Männer bei uns wohnen bleiben und ein Volk werden, wenn sich alles Männliche bei uns beschneidet, wie sie beschnitten sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Werden ihre Herden aller Art und all ihr Vieh uns nicht von Nutzen sein? So wollen wir ihnen willfahren, daß sie bei uns wohnen bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Da hörten auf Chamor und seinen Sohn Sichem alle, die zum Tore seiner Stadt hinausziehen konnten, und alle Männer, die zum Tore seiner Stadt hinausziehen konnten, ließen sich beschneiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Aber am dritten Tage, als sie wundkrank waren, griffen die beiden Jakobssöhne, Simeon und Levi, Dinas Brüder, jeder nach seinem Schwert, überfielen dreist die Stadt und erschlugen jede Mannesperson.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Auch Chamor und seinen Sohn Sichem schlugen sie mit des Schwertes Schärfe, dann holten sie Dina aus Sichems Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Dann zogen auch die anderen Jakobssöhne aus, kamen über die Erschlagenen und plünderten die Stadt, weil sie ihre Schwester geschändet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Sie nahmen ihre Schafe, Rinder, Esel, was in der Stadt und draußen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'All ihre Habe und all ihre Kinder und ihre Weiber erbeuteten sie; und plünderten alles, was in den Häusern war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sprach Jakob zu Simeon und Levi: \"Ihr habt mich verstört. Ihr macht mich bei des Landes Bewohnern, den Kanaanitern und den Perizitern, verhaßt, und doch habe ich nur wenige ohnmächtige Wichte. Rotten sie sich gegen mich zusammen, dann schlagen sie mich, und ich werde mit meinem Haus vernichtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sie sprachen: \"Durfte man denn unsere Schwester wie eine Dirne behandeln?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Gott sprach zu Jakob: \"Auf! Hin nach Betel, bleib dort und baue dort einen Altar dem Gott, der dir erschienen ist, als du vor deinem Bruder Esau bist geflohen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sprach Jakob zu seiner Familie und allen anderen bei ihm: \"Werft die fremden Götter bei euch weg! Reinigt euch und bessert eure Kleider aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Wir wollen uns aufmachen und nach Betel ziehen! Dort will ich einen Altar bauen dem Gott, der mich an meinem Nottag erhört und mit mir auf dem Weg gewesen, den ich gegangen bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da gaben sie Jakob alle fremden Götter aus ihrem Besitz, samt ihren Ohrringen, und Jakob vergrub sie unter der Terebinthe bei Sichem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Dann brachen sie auf. Aber ein Gottesschrecken fiel auf die Städte ringsum; da verfolgten sie nicht die Jakobssöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'So kam Jakob nach Luz im Land Kanaan, das ist Betel, er und all die Leute bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Er baute dort einen Altar und rief bei dem Orte den Gott von Betel an; denn hier hatten sich ihm die göttlichen Mächte geoffenbart, als er vor seinem Bruder floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Da starb Rebekkas Amme Debora. Sie ward unterhalb Betels unter der Eiche begraben; man nannte sie Klageeiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien nochmals Jakob nach seiner Rückkehr aus Paddan Aram und segnete ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: \"Du heißest Jakob; fortan sollst du nicht Jakob heißen, nein, Israel soll nun dein Name sein!\" Daher nannte man ihn Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: \"Gott bin ich, der Allmächtige. Sei fruchtbar, mehre dich! Ein Volk, ja Völkerscharen sollen dir entstammen und Könige aus deinen Lenden sprossen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Das Land, das ich gegeben Abraham und Isaak, gebe ich dir. Auch deinem Stamm nach dir verleihe ich das Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Und Gott fuhr von ihm an der Stätte auf, wo er mit ihm geredet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Da errichtete Jakob ein Mal an dem Ort, wo er mit ihm geredet, ein Steinmal, und goß darauf ein Trankopfer und schüttete Öl darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob nannte die Stätte, wo Gott mit ihm geredet, Betel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Sie zogen von Betel weiter. Es war aber noch ziemlich weit nach Ephrat; da mußte Rachel gebären, und sie bekam eine schwere Geburt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Als ihr die Geburt so schwer ward, sprach die Geburtshelferin zu ihr: \"Sei getrost! Du hast auch diesmal einen Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Als ihr aber der Lebenshauch entfloh, denn sie mußte sterben, nannte sie ihn Ben Oni; sein Vater aber hieß ihn Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'So starb Rachel. Sie ward am Weg nach Ephrat, das ist Bethlehem, begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jakob stellte auf ihrem Grab ein Steinmal auf. Das ist das Steinmal am Rachelgrab bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Israel zog weiter und spannte sein Zelt jenseits vom Herdenturm auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Während Israel in dieser Gegend wohnte, ging Ruben hin und beschlief seines Vaters Nebenweib Bilha, und Israel vernahm es. Die Jakobssöhne waren aber ihrer zwölf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Leasöhne waren Jakobs Erstgeborener Ruben, Simeon, Levi, Juda, Issakar und Zabulon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Die Rachelsöhne waren Joseph und Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Die Söhne Bilhas, der Magd der Rachel, waren Dan und Naphtali.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Und die Söhne Zilpas, der Magd der Lea, waren Gad und Asser; dies sind die Jakobssöhne, die ihm zu Paddan Aram geboren sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jakob kam nun zu seinem Vater Isaak nach Mamre bei Kirjat Arba, das ist Hebron, wo Abraham und Isaak als Gäste geweilt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Und Isaaks Lebensdauer betrug 180 Jahre,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'da verschied Isaak. Er starb und ward zu seinen Stammesgenossen versammelt, alt und lebenssatt. Ihn begruben seine Söhne Esau und Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Das ist die Geschlechterfolge Esaus, das ist Edoms:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau nahm seine Weiber aus den Töchtern Kanaans: Ada, die Tochter des Chittiters Elon, und Oholibama, die Tochter Anas, der Tochter des Choriters Sibon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basemat, die Tochter Ismaels und Schwester Nebajots.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada gebar dem Esau den Eliphaz; Basemat aber hatte den Reguel geboren');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'und Oholibama den Jëus, Jalam und Korach. Dies sind die Esausöhne, die im Lande Kanaan geboren sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Esau nahm seine Weiber, Söhne und Töchter, überhaupt alle Seelen seines Hauses und seine Herde, all sein Vieh und seine ganze Habe, die er sich im Lande Kanaan erworben hatte, und zog in ein anderes Land, fort von seinem Bruder Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihr Besitz war zu groß geworden zum Beisammenbleiben, und das Land, in dem sie als Gäste weilten, hatte wegen ihrer Herden für sie nicht ausgereicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'So ließ sich Esau auf dem Gebirge Seïr nieder: Esau ist Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Das ist die Geschlechterfolge Esaus, des Vaters von Edom, auf dem Gebirge Seïr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphaz, der Sohn der Ada, des Weibes Esaus, und Reguel, der Sohn der Basemat, des Weibes Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Die Söhne des Eliphaz waren Teman, Omar, Sepho, Gatam und Kenaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna aber war ein Nebenweib des Esausohnes Eliphaz, und sie gebar dem Eliphaz den Amalek. Dies sind die Söhne der Ada, des Weibes Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Und dies sind die Söhne Reguels. Nachat, Zerach, Samma und Mizza. Dies waren die Söhne der Basemat, des Weibes Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und dies waren die Söhne der Oholibama, der Tochter Anas, der Tochter Sibons und des Weibes Esaus: Sie gebar dem Esau den Jëus, den Jalam und den Korach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies sind die Häuptlinge der Söhne Esaus. Die Söhne des Erstgeborenen Esaus, Eliphaz, waren der Häuptling Teman, der Häuptling Omar, der Häuptling Sepho und der Häuptling Kenaz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Häuptling Korach, der Häuptling Gatam und der Häuptling Amalek. Dies sind die Häuptlinge des Eliphaz im Lande Edom; dies sind die Söhne der Ada.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und dies sind die Söhne des Esausohnes Reguel: der Häuptling Nachat, der Häuptling Zerach, der Häuptling Samma und der Häuptling Mizza; dies sind die Häuptlinge Reguels im Lande Edom; dies sind die Söhne Basemats, des Weibes Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Und dies sind die Söhne der Oholibama, des Weibes Esaus: der Häuptling Jëus, der Häuptling Jalam und der Häuptling Korach; dies sind die Häuptlinge der Oholibama, der Tochter Anas und des Weibes Esaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Dies sind die Söhne Esaus und dies ihre Häuptlinge: das ist Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dies sind die Söhne des Choriters Seïr, die Einwohner des Landes: Lotan, Sobal, Sibon und Ana,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Eser und Disan; dies sind die Häuptlinge der Choriter, der Söhne Seïrs im Lande Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Die Söhne Lotans waren Chori und Hemam, und Lotans Schwester war Timna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Und dies sind die Söhne Sobals: Alwan, Manachat, Ebal, Sepho und Onam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Und dies sind die Söhne Sibons: Ajja und Ana; das ist der Ana, der die Ungeheuer in der Wüste angetroffen hat, als er seinem Vater Sibon die Esel weidete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Und dies sind die Söhne Anas: Dison, und Oholibama war die Tochter des Ana.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Und dies sind die Söhne des Disan, Chemdan, Esban, Jitran und Keran..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dies sind die Söhne des Eser: Bilhan, Zaawan und Akan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dies sind die Söhne Disans: Uz und Aram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Häuptlinge der Choriter: der Häuptling Lotan, der Häuptling Sobal, der Häuptling Sibon und der Häuptling Ana,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Häuptling Dison, der Häuptling Eser, der Häuptling Disan; dies sind die Häuptlinge der Choriter nach ihren Geschlechtern im Lande Seïr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Dies sind die Könige, die im Lande Edom geherrscht haben, bevor ein König über Israels Söhne herrschte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'König über Edom war Bela, Beors Sohn, und seine Stadt hieß Dinhaba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Als Bela starb, ward an seiner Statt König Jobab, Zerachs Sohn, aus Bosra.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Als Jobab starb, ward an seiner Statt König Chusam aus dem Land der Temaniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Als Chusam starb, ward an seiner Statt König Bedads Sohn Hadad, der die Midianiter auf Moabs Gefilden schlug, und seine Stadt hieß Awit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Als Hadad starb, ward an seiner Statt Samla aus Masreka König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Als Samla starb, ward an seiner Statt Saul aus Nechobot am Strome König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Als Saul starb, ward an seiner Statt Baalchanan aus Akbor König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Als Baalchanan aus Akbor starb, ward an seiner Statt Hadad König, und seine Stadt hieß Pau und sein Weib Mehetabel, die Tochter Matreds, der Tochter von Mezahab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Dies sind die Namen der Häuptlinge Esaus nach ihren Geschlechtern, ihren Ortschaften und Namen: der Häuptling Timna, der Häuptling Alwa, der Häuptling Jetet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Häuptling Oholibama, der Häuptling Ela, der Häuptling Pinon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Häuptling Kenaz, der Häuptling Teman, der Häuptling Mibsar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Häuptling Magdiel und der Häuptling Iram. Dies sind die Häuptlinge Edoms nach ihren Wohnsitzen in ihrem besetzten Gebiet. Das ist Esau, der Vater Edoms.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber wohnte in dem Land, in dem sein Vater zu Gast geweilt, im Land Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dies ist Jakobs Geschlechterfolge: Als Joseph siebzehn Jahre alt geworden, pflegte er seine Brüder bei den Schafherden zu besuchen. Er hielt sich aber als junger Mann zu den Söhnen Bilhas und Zilpas, der Weiber seines Vaters. Und so konnte Joseph ihrem Vater schlimme Geschichten über sie vermelden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel aber liebte Joseph mehr als alle seine anderen Söhne; denn er war ihm in seinem Alter geboren, und so hatte er ihm einen langen Leibrock machen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Wie nun seine Brüder sahen, daß ihn sein Vater mehr als alle seine Brüder liebte, da haßten sie ihn, und so konnten sie nicht unter sich freundlich über ihn reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Einst hatte nun Joseph einen Traum und erzählte ihn seinen Brüdern; da haßten sie ihn noch mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Er sprach zu ihnen: \"Hört doch, was ich geträumt habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Wir banden Garben auf dem Felde. Da hat sich meine Garbe aufgerichtet und ist stehengeblieben. Aber eure Garben stellten sich herum und neigten sich vor meiner Garbe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Brüder zu ihm \"Du wärst wohl gern König über uns; du wärst wohl gern unser Herrscher?\" Und sie haßten ihn noch ärger wegen seines Traumes und seiner Erzählung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Er träumte aber wieder und erzählte es seinen Brüdern. Er sprach: \"Noch einen Traum habe ich gehabt: Die Sonne, der Mond und elf Sterne neigten sich vor mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Als er dies seinem Vater und seinen Brüdern erzählte, schalt ihn sein Vater und sprach zu ihm: \"Was ist das für ein Traum, den du gehabt? Sollen wir, ich, deine Mutter und deine Brüder kommen und uns vor dir zur Erde neigen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Seither waren ihm seine Brüder mißgesinnt. Sein Vater aber merkte sich die Sache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Nun gingen seine Brüder, ihres Vaters Schafe bei Sichem zu weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Da sprach Israel zu Joseph: \"Weiden deine Brüder nicht zu Sichem? Komm! Ich will dich zu ihnen senden.\" Er sprach zu ihm: \"Ich bin bereit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Da sprach er zu ihm: \"Geh! Schau nach dem Befinden deiner Brüder und der Herde und bringe mir Bescheid!\" So schickte er ihn aus dem Tal von Hebron, und er kam nach Sichem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Da sah ihn ein Mann auf dem Feld umherirren, und der Mann fragte ihn: \"Wen suchst du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er sprach: \"Ich suche meine Brüder. Sag mir doch, wo sie weiden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Da sprach der Mann: \"Sie sind von hier weggezogen. Ich habe sie nämlich sprechen gehört: \'Wir wollen nach Dotain gehen.\'\" Da ging Joseph seinen Brüdern nach und traf sie in Dotain.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Sie sahen ihn aber schon von ferne, und bevor er zu ihnen kam, heckten sie gegen ihn einen Mordplan aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Sie sprachen zueinander: \"Seht, dort drüben kommt der Träumer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Nun auf! Erschlagen wir ihn und werfen wir ihn in eine der Gruben; dann sagen wir: \'Ein wildes Tier hat ihn gefressen.\' Dann sehen wir, was aus seinen Träumen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Als Ruben dies hörte, suchte er ihn aus ihrer Hand zu retten. Er sprach: \"Wir wollen ihn nicht totschlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Dann sprach Ruben zu ihnen: \"Vergießt kein Blut! Werft ihn in die Grube da in der Steppe! Aber legt nicht Hand an ihn!\" So wollte er ihn aus ihrer Hand retten und ihn seinem Vater heimbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Wie nun Joseph zu seinen Brüdern kam, rissen sie Joseph seinen Leibrock ab, den langen Leibrock, den er anhatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Und sie packten ihn und warfen ihn in die Grube; die Grube aber war leer und wasserlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Dann setzten sie sich zum Mahle nieder. Wie sie nun aufblickten, sahen sie, wie eine Karawane von Ismaelitern aus Gilead herankam, ihre Kamele beladen mit Tragakanth, Mastix und Ladanharz, auf dem Weg nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brüdern: \"Was haben wir davon, wenn wir unseren Bruder umbrächten und dann sein Blut zudeckten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt! Wir wollen ihn den Ismaelitern verkaufen! Aber unsere Hand komme nicht an ihn! Er ist doch unser Bruder, unser eigen Fleisch.\" Da willigten seine Brüder ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Als aber midianitische Handelsleute vorüberzogen, zogen sie Joseph aus der Grube. Und sie verkauften Joseph an die Ismaeliter um zwanzig Silberlinge. Diese aber brachten Joseph nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als nun Ruben wieder zu der Grube kam, war Joseph nicht mehr in der Grube. Da zerriß er seine Kleider,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'kehrte zu seinen Brüdern zurück und sprach: \"Der Knabe ist nicht mehr da. Wie kann ich da heimgehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Da nahmen sie Josephs Leibrock, schlachteten einen Ziegenbock und tauchten den Rock in das Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Dann machten sie den langen Leibrock noch schmutzig, brachten ihn ihrem Vater und sprachen: \"Dies haben wir gefunden. Sieh zu, ob\'s deines Sohnes Rock ist oder nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Er betrachtete ihn und sprach: \"Meines Sohnes Rock ist\'s. Ein wildes Tier hat ihn gefressen. Ach, Joseph ist zerrissen worden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Kleider, legte ein härenes Gewand um seine Hüften und trauerte um seinen Sohn viele Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Da machten sich all seine Söhne und Töchter daran, ihn zu trösten; er aber wollte sich nicht trösten lassen. Er sprach: \"Nein! Trauernd fahre ich zu meinem Sohne in die Unterwelt.\" Und sein Vater weinte um ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'So hatten ihn die Midianiter nach Ägypten verkaufen lassen an Potiphar, den Kämmerer des Pharao und den Anführer der Leibwache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'In jener Zeit verließ Juda seine Brüder und schloß sich einem Mann von Adullam, namens Chira, an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Dort sah nun Juda die Tochter eines Kanaaniters namens Sua; er freite und heiratete sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Und sie empfing und gebar einen Sohn; er nannte ihn Ger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Wieder ward sie guter Hoffnung und gebar einen Sohn; sie nannte ihn Onan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Dann gebar sie noch einen Sohn; sie nannte ihn Sela; zu Kezib war es gewesen, wo sie ihn gebar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Dann freite Juda für seinen Erstgeborenen Ger ein Weib namens Tamar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Ger aber, Judas Erstgeborener, machte sich dem Herrn mißfällig, und so ließ ihn der Herr sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sprach Juda zu Onan: \"Komm zu dem Weibe deines Bruders! Leiste ihr die Schwagerpflicht und erwecke deinem Bruder Nachkommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Onan aber wußte, daß ihm die Nachkommenschaft nicht gehören würde; als er nun zu seines Bruders Weibe kam, vereitelte er die Zeugung, um nicht seinem Bruder Nachkommen zu schenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Dem Herrn aber mißfiel, was er getan, und er ließ auch ihn sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sprach Juda zu seiner Schwiegertochter Tamar: \"Bleib als Witwe in deines Vaters Haus, bis mein Sohn Sela erwachsen ist!\" Denn er dachte, auch dieser könnte wie seine Brüder sterben. Tamar ging nun und blieb in ihres Vaters Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Längere Zeit verstrich; da starb Suas Tochter, Judas Weib. Als Juda ausgetrauert hatte, ging er hinauf zu seiner Schafschur mit seinem Freunde, dem Adullamiter Chira, nach Timna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Da ward Tamar gemeldet: \"Dein Schwiegervater kommt nach Timna zur Schafschur.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Da legte sie ihre Witwenkleider ab, bedeckte sich mit dem Schleier, vermummte sich und setzte sich an den Zugang nach Enaim, am Wege nach Timna. Sie hatte nämlich bemerkt, daß Sela erwachsen war, und dennoch war sie ihm nicht zum Weibe gegeben worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Juda aber sah sie und hielt sie für eine Dirne; denn sie hatte ihr Gesicht verhüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und er bog zu ihr an den Weg ab und sprach: \"Laß mich, bitte, zu dir kommen!\" Denn er merkte nicht, daß es seine Schwiegertochter war. Sie sprach: \"Was gibst du mir dafür, wenn du zu mir kommen darfst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er sprach: \"Ich sende dir ein Ziegenböckchen von der Herde.\" Sie sprach: \"Wenn du mir ein Pfand gibst, bis du\'s schickst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Er sprach: \"Was für ein Pfand soll ich dir geben?\" Sie sprach: \"Dein Siegel, deine Schnur und den Stab in deiner Hand!\" Er gab es ihr; dann kam er zu ihr, und sie empfing von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Dann erhob sie sich, legte ihren Schleier ab und zog ihre Witwenkleider wieder an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda sandte nun das Ziegenböckchen durch seinen Freund, den Adullamiter, um dafür das Pfand von dem Weibe zurückzuerhalten. Aber er fand sie nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Da fragte er die Leute ihres Ortes: \"Wo ist die Weihdirne, die hier bei Enaim am Wege gewesen ist?\" Sie sprachen: \"Hier ist doch keine Dirne gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Da kehrte er zu Juda zurück und sprach: \"Ich fand sie nicht, und auch die Leute im Orte sagten: \"Hier war keine Dirne.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Da sprach Juda: \"So mag sie\'s behalten! Daß wir nur nicht zum Gespött werden! Ich aber habe dies Böckchen geschickt, und du hast sie nur nicht gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Nach ungefähr drei Monaten ward Juda berichtet: \"Deine Schwiegertochter Tamar hat nicht nur gebuhlt, sondern ist durch die Buhlerei auch in Hoffnung gekommen.\" Da sprach Juda: \"Führt sie hinaus! Sie werde verbrannt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Schon wurde sie hinausgeführt, da schickte sie zu ihrem Schwiegervater und ließ sagen: \"Von jenem Mann, dem dies gehört, bin ich guter Hoffnung.\" Sie ließ ihm auch sagen: \"Sieh doch genau zu! Wem gehört dies, das Siegel, die Schnüre und der Stab?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Und Juda betrachtete sie und sprach: \"Sie hat recht gegen mich. Warum habe ich sie nicht meinem Sohne Sela gegeben?\" Er aber hatte fortan keinen Umgang mehr mit ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Zur Zeit ihres Gebärens aber waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Als sie gebar, streckte der eine eine Hand vor. Da nahm die Hebamme einen roten Faden und band ihn um seine Hand, wobei sie sprach: \"Dieser ist zuerst herausgetreten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Als er aber seine Hand zurückzog, kam sein Bruder zum Vorschein. Da sprach sie: \"Wie du dir einen Vorläufer bestellt hast!\" Und man nannte ihn Peres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Hernach kam sein Bruder zum Vorschein, an dessen Hand der rote Faden war. Und man nannte ihn Zerach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'So war Joseph nach Ägypten gebracht worden. Da kaufte ihn Potiphar, Pharaos Kämmerer und Oberster der Leibwächter, ein ägyptischer Mann, von den Ismaelitern, die ihn dorthin gebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Der Herr aber war mit Joseph, und so ward er ein Mann, dem alles gelang. Da er im Hause seines ägyptischen Herrn blieb,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'sah sein Herr, daß der Herr mit ihm sei und daß der Herr ihm alles, was er vornahm, gelingen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'So fand Joseph in seinen Augen Gnade und durfte ihn bedienen. Dann setzte er ihn als Verwalter über sein Haus und vertraute ihm sein ganzes Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und seitdem er ihn über sein Haus bestellt und all sein Eigentum ihm anvertraut hatte, segnete der Herr das Haus des Ägypters um Josephs willen. Und des Herrn Segen ruhte auf seinem Eigentum in Haus und Feld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'So überließ er all sein Eigentum Joseph und kümmerte sich bei ihm um nichts als um die Speise, die er genoß. Joseph aber ward schön von Gestalt und Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Nach diesen Begebnissen geschah es, daß seines Herrn Weib die Augen zu Joseph erhob und sprach: \"Leg dich zu mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu seines Herrn Weib: \"Sieh! Mein Herr kümmert sich bei mir um nichts im Hause; all sein Eigentum hat er mir übergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Niemand ist in diesem Hause größer als ich. Gar nichts hat er mir vorenthalten als dich, weil du sein Weib bist. Wie sollte ich nun dieses schwere Unrecht tun, daß ich mich wider Gott versündigte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Sie redete aber Tag für Tag auf Joseph ein. Er aber war ihr nicht zu Willen, sich zu ihr zu legen und mit ihr beisammen zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Da geschah es an einem solchen Tage, daß er ins Haus kam, seine Arbeit zu tun; vom Hausgesinde aber war keines dort im Gemach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Da packte sie ihn am Gewand und sprach: \"Leg dich zu mir!\" Er aber ließ sein Gewand in ihrer Hand und floh hinaus ins Freie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Als sie sah, daß er sein Gewand in ihrer Hand gelassen und ins Freie geflohen war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'rief sie ihr Hausgesinde herbei und sprach zu ihm: \"Seht! Da hat man uns einen hebräischen Mann gebracht, daß er seinen Mutwillen mit uns treibe. Er kam zu mir herein und wollte sich zu mir legen; da schrie ich laut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Wie er aber hörte, daß ich lautes Geschrei erhob, ließ er sein Kleid bei mir, floh und lief ins Freie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie legte sein Gewand neben sich, bis sein Herr heimkäme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Da berichtete sie ihm das gleiche und sprach: \"Kommt da der hebräische Sklave, den du uns hergebracht, zu mir herein und will seinen Mutwillen mit mir treiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Wie ich aber laut schrie, ließ er sein Kleid bei mir und floh ins Freie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als der Herr seines Weibes Erzählung vernahm, die sie ihm vorgetragen: \"Also hat dein Sklave mir getan\", da ward er sehr zornig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Und Josephs Herr ließ ihn ergreifen und ins Gefängnis werfen, dahin, wo die Königsgefangenen saßen. Und so lag er dort im Kerker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber der Herr war mit Joseph und wandte ihm Huld zu. Er verschaffte ihm die Gunst des Oberkerkermeisters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Und der Oberkerkermeister vertraute Joseph alle Gefangenen im Kerker an, und alles, was man dort zu tun hatte, besorgte er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der Oberkerkermeister aber kümmerte sich um gar nichts, was durch jenen geschah, weil der Herr mit ihm war und der Herr alles, was er vornahm, gelingen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Nach jenen Begebnissen geschah es, daß sich des ägyptischen Königs Mundschenk und Bäcker gegen ihren Herrn, den König von Ägypten, vergingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Und Pharao ergrimmte über seine beiden Hofleute, über den Obermundschenk und den Oberbäcker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Er ließ sie in Gewahrsam legen, ins Haus des Anführers der Leibwache, in den Kerker, an die Stätte, wo Joseph gefangen saß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Anführer der Leibwächter gab ihnen Joseph bei, sie zu bedienen. So blieben sie längere Zeit im Gewahrsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Da träumten beide in der gleichen Nacht, und zwar jeder einen besonderen Traum, des ägyptischen Königs Mundschenk und Bäcker, die im Kerker saßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Am Morgen kam Joseph zu ihnen und sah sie an. Da waren sie verstimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Da fragte er des Pharaos Höflinge, die mit ihm im Gewahrsam in seines Herrn Haus waren: \"Warum macht ihr heute solch böse Gesichter?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie sprachen zu ihm: \"Wir haben einen Traum gehabt, und niemand ist da, der ihn deute.\" Da sprach Joseph zu ihnen: \"Sind Deutungen nicht Gottes Sache? Erzählt mir doch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzählte der Obermundschenk dem Joseph seinen Traum und sprach zu ihm: \"In meinem Traume stand vor mir ein Weinstock.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Und am Weinstock sind drei Ranken. Er schlägt aus; dann kommt er zum Blühen, und schon tragen seine Kämme reife Trauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ich aber habe Pharaos Becher in der Hand, nehme die Trauben, presse sie in Pharaos Becher aus und gebe den Becher dem Pharao in die Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Da sprach Joseph zu ihm: \"Dies ist seine Deutung: Drei Ranken sind drei Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Drei Tage noch, dann nimmt dich Pharao persönlich vor und stellt dich wieder auf deinen Posten, und du reichst Pharao wieder den Becher, ganz wie früher, als du sein Mundschenk gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Denkst du also an mich, wenn es dir wieder gut geht, dann habe die Güte, mich beim Pharao zu empfehlen und mir so aus diesem Hause zu helfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn aus der Hebräer Land bin ich entführt worden, und auch hier habe ich nichts verbrochen, daß sie mich in den Kerker werfen mußten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Als der Oberbäcker bemerkte, daß er zum Guten ausgelegt, sprach er zu Joseph: \"In meinem Traume waren auf meinem Kopf drei geflochtene Körbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Im obersten der Körbe waren allerlei Eßwaren für den Pharao, Backwerk; jedoch die Vögel fraßen es aus dem Korb auf meinem Kopfe weg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Da erwiderte Joseph und sprach: \"Dies ist die Deutung: Drei Körbe sind drei Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Drei Tage noch, dann nimmt dich der Pharao persönlich in deiner Sache vor; dann hängt er dich an das Holz, und dann fressen die Vögel dein Fleisch von dir ab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Am dritten Tage war es, dem Geburtstag Pharaos; da bereitete er ein Mahl für alle seine Diener. Dabei nahm er den Obermundschenk und den Oberbäcker im Beisein seiner Diener persönlich vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Da setzte er den Obermundschenk wieder zu seinem Mundschenk ein, und er durfte Pharao den Becher wieder reichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Den Oberbäcker aber ließ er hängen, wie ihnen Joseph vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Der Obermundschenk aber gedachte nicht mehr Josephs. Er vergaß ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Nach Verlauf zweier Jahre träumte Pharao, er stehe am Nil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Da stiegen aus dem Nil sieben Kühe, prächtig von Aussehen und fett an Fleisch, und weideten im Riedgras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Ihnen nach stiegen sieben andere Kühe aus dem Nil, häßlich von Aussehen und mager an Fleisch, und traten neben jene Kühe am Nilufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Dann fraßen die häßlichen und mageren Kühe die sieben stattlichen und fetten Kühe. Da erwachte Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Er schlief wieder ein, da träumte er zum zweitenmal. Sieben Ähren wuchsen an einem Halm, dick und schön.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ihnen nach sproßten sieben Ähren, dürr und vom Ostwind versengt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die dürren Ähren verschlangen die sieben dicken und vollen Ähren. Da erwachte Pharao; ein Traum war es gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Am Morgen aber war sein Gemüt noch unruhig; da sandte er hin und ließ alle Schriftkundigen und Weisen Ägyptens rufen. Und Pharao erzählte ihnen seine Träume; aber niemand vermochte sie dem Pharao zu deuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da nahm der Obermundschenk das Wort und sprach zu Pharao: \"Heute muß ich meiner Nachlässigkeit gedenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Der Pharao hatte einst auf seine Diener gezürnt, und so legte er mich in Gewahrsam in das Haus des Anführers der Leibwächter, mich und den Oberbäcker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Da träumten wir beide in einer Nacht, und zwar hatte jeder einen besonderen Traum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Nun war bei uns dort ein hebräischer Jüngling, ein Sklave des Obersten der Leibwächter, und dem erzählten wir es, und jener deutete uns unsere Träume. Jedem deutete er, seinem Traum gemäß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und wie er es uns gedeutet, so traf es ein. Mich hat man wieder auf meinen Posten gestellt, und ihn hat man gehenkt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte Pharao und ließ Joseph rufen. Eilends entließen sie ihn aus dem Kerker. Er ließ sich scheren und wechselte seine Kleider. Dann kam er zu Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Und Pharao sprach nun zu Joseph: \"Ich habe einen Traum gehabt, und niemand kann ihn deuten. Nun habe ich von dir gehört, man sage, du brauchtest einen Traum nur zu hören, und du könntest ihn deuten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Da erwiderte Joseph dem Pharao also: \"Ich nicht; Gott nur kann offenbaren, was Pharao frommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Da erzählte Pharao dem Joseph: \"In meinem Traume stand ich an des Niles Ufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Da stiegen sieben Kühe aus dem Nil, fett an Fleisch und stattlich anzusehen, und weideten im Riedgras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Ihnen nach stiegen sieben andere Kühe, elend und häßlich an Gestalt und mager an Fleisch. In ganz Ägypten habe ich nie etwas so Häßliches gesehen wie sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Da fraßen die mageren und häßlichen Kühe die ersten sieben fetten Kühe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Sie kamen so in ihren Magen; aber man hatte gar nicht gemerkt, daß sie in ihren Magen gekommen waren; denn ihr Aussehen blieb häßlich, wie zuvor. Da erwachte ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Und wieder sah ich in meinem Traum: Da wuchsen sieben Ähren voll und schön an einem Halm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Ihnen nach sproßten sieben andere Ähren, taub, dürr und vom Ostwind versengt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Und diese dürren Ähren verschlangen die sieben schönen Ähren. Ich sagte es den Schriftgelehrten; aber keiner konnte mir Bescheid geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da sprach Joseph zu Pharao: \"Pharaos Traum ist unzweideutig. Gott tut dem Pharao kund, was er zu tun gedenkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schönen Kühe sind sieben Jahre. Die sieben schönen Ähren sind auch sieben Jahre. Nur ein Traum ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Und diese sieben mageren und häßlichen Kühe, die nach ihnen kamen, sind sieben Jahre, und die sieben leeren, vom Ostwind versengten Ähren bedeuten sieben Hungerjahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das ist dasselbe, was ich Pharao schon sagte: \'Was Gott zu tun gedenkt, hat er Pharao schauen lassen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Sieh, sieben Jahre kommen, da herrscht großer Überfluß im ganzen Land Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Nach ihnen kommen sieben Hungerjahre. Da weiß man nichts mehr von irgendwelchem Überfluß im Land Ägypten. Dann zehrt der Hunger im Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Dann merkt man nichts mehr vom Überfluß im Land wegen dieser Hungersnot hernach; denn sie wird überschwer sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Und daß der Traum des Pharao zweimal in verschiedener Form erschien, heißt: Die Sache ist fest bei Gott beschlossen, und Gott setzt eilends sie ins Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nun ersehe sich Pharao einen klugen, weisen Mann und setze ihn über das Ägypterland!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Möge Pharao unverzüglich über das Land Aufseher setzen und dann den fünften Teil aus dem Land Ägypten in den sieben Jahren des Überflusses als Abgabe erheben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Dann soll man jeglich Korn dieser kommenden guten Jahre aufspeichern und Getreide zu Pharaos Verfügung in den Städten zur Nahrung anhäufen und verwahren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Dann ist das Korn dem Land ein Rückhalt für die sieben Hungerjahre, die über das Ägypterland kommen, damit das Land durch die Hungersnot nicht zugrunde gehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Diese Rede gefiel nun Pharao und all seinen Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und Pharao sprach zu seinen Dienern: \"Könnten wir jemanden wie diesen finden, einen Mann, in dem Gottes Geist ist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Und Pharao sprach zu Joseph: \"Weil ein Gott dir all dies geoffenbart, ist keiner so klug und weise wie du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst meinem Hause vorstehen! Mein ganzes Volk soll deine Rede achten! Nur um den Thron will ich größer sein als du.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dann sprach Pharao zu Joseph: \"Siehe! Ich setze dich über ganz Ägypterland.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Dann zog Pharao seinen Siegelring von seiner Hand und streifte ihn an Josephs Hand, kleidete ihn mit Linnengewändern und legte ihm die goldene Kette um den Hals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Dann ließ er ihn auf seinem Wagen zweiten Ranges fahren und vor ihm ausrufen: Abrek! und daß man ihn einsetze als König über ganz Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und Pharao sprach zu Joseph: \"Ich bin Pharao. Aber ohne dich hebe niemand Hand noch Fuß in ganz Ägypterland!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und Pharao hieß Joseph Saphnat Paneach. Und er gab ihm zum Weibe Asenat, die Tochter Potipheras, des Priesters von On. So ward Joseph im Ägypterland bekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joseph war dreißig Jahre alt, als er in des ägyptischen Königs Pharao Dienste trat. Nachdem Joseph von Pharao weggegangen war, durchzog er ganz Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Das Land war nun in den sieben Jahren des Überflusses überaus fruchtbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'So speicherte er jegliches Korn der sieben Jahre im Ägypterland auf und legte Korn in die Städte. In jede Stadt legte er das Korn des Feldes, das sie umgab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'So häufte Joseph Getreide wie Sand am Meere überaus viel auf, bis man das Messen lassen mußte; denn es war unmeßbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Zwei Söhne aber waren Joseph geboren worden, bevor das Hungerjahr kam. Asenat, die Tochter Potipheras, des Priesters von On, hatte sie ihm geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und Joseph nannte den Erstgeborenen Manasse; denn \"Gott hat mich vergessen lassen all mein Unglück und mein ganzes Haus\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den zweiten nannte er Ephraim; denn \"Gott hat mich zur Macht im Lande meines Elends kommen lassen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Zu Ende gingen nun die sieben Jahre des Überflusses im Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Und die sieben Jahre des Hungers hoben an, wie Joseph gesagt hatte. Hunger war in allen Ländern; aber in ganz Ägypten gab es Brot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Als aber auch ganz Ägypterland hungerte, schrie das Volk zu Pharao um Brot; da sprach Pharao zu jedem Ägypter: \"Geht zu Joseph! Was er euch sagen wird, tut!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Nun kam der Hunger über die ganze Erde. Da öffnete Joseph alle Speicher und verkaufte den Ägyptern Getreide. Aber auch in Ägypten ward der Hunger immer stärker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Alle Welt kam nun nach Ägypten, Getreide bei Joseph zu kaufen, denn stark war der Hunger auf der ganzen Erde geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Auch Jakob erfuhr, daß es in Ägypten Brotgetreide gebe; da sprach Jakob zu seinen Söhnen: \"Warum zögert ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Und er sprach: \"Ich habe gehört, daß in Ägypten ein Kornmarkt ist. Ziehet dorthin und holt uns von dort Getreide, daß wir am Leben bleiben und nicht sterben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Da zogen zehn der Brüder Josephs hinab, in Ägypten Getreide zu kaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Den Benjamin aber, Josephs Vollbruder, hatte Jakob nicht mit seinen Brüdern ziehen lassen; denn er dachte, ihn könnte ein Unfall treffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'So kamen Israels Söhne zum Markt inmitten der Herbeiströmenden; denn im Lande Kanaan war der Hunger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Joseph aber war der Gebieter des Landes; er war es, der jedem Volk der Erde Getreide verkaufte. So kamen auch Josephs Brüder und neigten sich vor ihm zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Da sah Joseph seine Brüder und erkannte sie; aber er stellte sich fremd gegen sie, ließ sie hart an und fragte sie: \"Woher kommt ihr?\" Sie sagten: \"Aus dem Lande Kanaan zum Getreidekauf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Joseph erkannte seine Brüder; sie aber hatten ihn nicht erkannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Da gedachte Joseph der Träume, die er ihretwegen gehabt. Er sprach zu ihnen: \"Spione seid ihr. Ihr seid gekommen, die Blöße des Landes zu erspähen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie sprachen zu ihm: \"Nein, Herr! Mundvorrat zu kaufen, sind deine Sklaven gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir alle sind eines Mannes Söhne. Wir sind ehrlich. Niemals waren deine Knechte Spione.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Er sprach zu ihnen: \"Nichts da! Die Blöße des Landes zu erspähen, seid ihr gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie sprachen: \"Deiner Sklaven sind es zwölf, lauter Brüder, Söhne eines gewissen Mannes im Lande Kanaan. Der jüngste aber ist jetzt noch bei unserem Vater, und einer ist nicht mehr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Da sprach Joseph zu ihnen: \"Dabei bleibt es, was ich zu euch gesagt: Spione seid ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran sollt ihr geprüft werden. Beim Leben Pharaos! Ihr dürft nicht eher von hier fort, bis euer jüngster Bruder herkommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Schicket von euch einen, daß er euren Bruder hole! Ihr aber bleibt gefangen. So werden eure Aussagen geprüft, ob Wahrheit bei euch ist oder nicht. Beim Leben Pharaos! Ihr seid Spione.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und er ließ sie drei Tage in Gewahrsam legen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tage sprach Joseph zu ihnen: \"Tut dies, dann bleibt ihr am Leben! Denn ich bin gottesfürchtig:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Seid ihr ehrliche Leute, so bleibe von euch einer im Hause, darin ihr in Gewahrsam wart! Ihr anderen aber geht und bringt Korn für den Hunger eurer Familien heim!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Euren jüngsten Bruder aber müßt ihr mir bringen, daß sich eure Worte bewahrheiten und ihr nicht sterben müßt! Tut also!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Da sprachen sie zueinander: \"Leider haben wir dies an unserem Bruder verschuldet. Wir haben seine Angst gesehen, wie er uns anflehte, und wir haben nicht darauf geachtet. Deshalb ist diese Not über uns gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Da antwortete ihnen Ruben und sprach: \"Habe ich euch nicht gesagt: \'Versündigt euch nicht an dem Kinde!\' Ihr aber habt nicht gehört. Nun wird sein Blut gefordert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie aber wußten nicht, daß Joseph zuhörte; denn der Dolmetscher war zwischen ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Und er wandte sich von ihnen und weinte. Dann wandte er sich ihnen zu und redete mit ihnen. Hierauf ließ er Simeon aus ihrer Mitte greifen und vor ihren Augen fesseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Joseph befahl aber, ihre Geräte mit Korn zu füllen und jedem sein Geld wieder in seinen Sack zu legen und ihnen Zehrung auf den Weg zu geben. Man tat so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Sie luden nun ihr Korn auf ihre Esel und zogen von dannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Da öffnete der eine seinen Sack, um seinen Esel in der Herberge zu füttern, und erblickte sein Geld. Obenan lag es in seinem Sack.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Da sprach er zu seinen Brüdern: \"Mein Geld ist wieder da. Hier liegt es in meinem Sack.\" Da entsank ihnen der Mut, und bebend sahen sie einander an und sprachen: \"Was hat uns Gott da getan?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Und sie kamen zu ihrem Vater Jakob ins Land Kanaan und berichteten ihm alles, was ihnen begegnet war, und sprachen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '\"Hart hat uns der Mann, der Herr des Landes, angelassen; er stellte uns hin wie Auskundschafter seines Landes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Wir sagten ihm: \"Wir sind ehrliche Leute; nie waren wir Spione.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Zwölf Brüder sind wir, lauter Söhne unseres Vaters. Einer ist nicht mehr. Der jüngste aber ist jetzt noch bei unserem Vater im Lande Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Aber der Mann, der Herr des Landes, sprach zu uns: \'Daran werde ich erkennen, ob ihr ehrliche Leute seid: Laßt einen von euch Brüdern hier bei mir! Den Bedarf für den Hunger eurer Familien nehmt mit und zieht ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Doch bringt mir euren jüngsten Bruder, daß ich erkenne, daß ihr keine Spione seid, sondern ehrliche Leute! Ich werde euch dann euren Bruder zurückgeben, und ihr dürft im Lande umherziehen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Wie sie nun ihre Säcke leerten, war eines jeden Geldbeutel in seinem Sack. Sie erblickten samt ihrem Vater ihre Geldbeutel und erschraken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Da sprach ihr Vater Jakob zu ihnen: \"Ihr beraubt mich der Kinder! Joseph ist nicht mehr, Simeon nicht mehr. Nun wollt ihr Benjamin fortnehmen. Über mich kommt alles.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da sprach Ruben zu seinem Vater: \"Töte meine beiden Söhne, wenn ich ihn nicht zurückbringe! Vertraue ihn mir an! Ich bringe ihn dir wieder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er sprach: \"Niemals darf mein Sohn mit euch reisen. Denn sein Bruder ist tot; er allein ist übrig. Träfe ihn ein Leid auf dem Weg, den ihr ziehen müßt, so senktet ihr mein graues Haupt mit Kummer in die Unterwelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Der Hunger aber lag schwer auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Als sie nun das aus Ägypten gebrachte Korn aufgezehrt hatten, sprach ihr Vater zu ihnen: \"Geht noch einmal, ein wenig Korn für uns zu kaufen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Da sprach Juda zu ihm: \"Nachdrücklich hat uns der Mann eingeschärft: \'Ihr dürft mir nicht mehr vor die Augen kommen, euer Bruder sei denn bei euch.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Willst du also unseren Bruder mitgeben, dann ziehen wir hinab und kaufen Korn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Gibst du ihn aber uns nicht mit, dann ziehen wir nicht hinab. Der Mann hat ja zu uns gesagt: \'Ihr dürft mir nicht vor die Augen kommen, euer Bruder sei denn bei euch.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Da sprach Israel: \"Warum habt ihr es mir zu Leid getan, dem Manne zu verraten, daß ihr noch einen Bruder habt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Da sprachen sie: \"Der Mann erkundigte sich genau nach uns und unserer Familie. Er sprach: \'Ist euer Vater noch am Leben? Habt ihr noch einen Bruder?\' Da gaben wir ihm Bescheid, wie es sich verhält. Konnten wir denn wissen, daß er sagen würde: \'Bringt euren Bruder her?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Da sprach Juda zu seinem Vater Israel: \"Gib mir den Knaben mit! Dann brechen wir auf und gehen und bleiben am Leben und müssen nicht sterben, wir so gut wie du und unsere Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich bürge für ihn. Fordere ihn von nur! Bringe ich ihn dir nicht und stelle ihn dir nicht vor Augen, so will ich lebenslang vor dir schuldig sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Hätten wir nicht allzulange gezaudert, wir wären schon zweimal zurück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da sprach ihr Vater Israel zu ihnen: \"Muß es sein, so tut dies: Nehmt vom feinsten Landeserzeugnis in euer Gepäck und bringt es als Geschenk dem Manne hinab, etwas Balsam, etwas Honig, Spezereien, Ladanum, Pistazien und Mandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Nehmt noch einmal soviel Geld mit euch! Auch das Geld oben in euren Säcken müßt ihr wieder mitnehmen. Vielleicht war es ein Versehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Auch euren Bruder nehmt mit! Auf! Zieht wieder zu dem Manne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Gott, der Allmächtige, schenke euch Erbarmen bei dem Manne, daß er euren anderen Bruder euch freigebe, desgleichen Benjamin! Ich aber! Nun, dann bin ich eben kinderlos.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'So nahmen die Männer jenes Geschenk; auch den doppelten Geldbetrag nahmen sie mit, dazu Benjamin, brachen auf, zogen nach Ägypten und traten vor Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Und Joseph sah bei ihnen den Benjamin. Da sprach er zu seinem Hausverwalter: \"Führe die Männer ins Haus, und man schlachte ein Stück Vieh und richte es her! Die Männer sollen mittags bei mir speisen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Und der Mann tat, wie Joseph gesagt. Und der Mann führte die Männer in Josephs Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Aber die Männer fürchteten sich, weil sie in Josephs Haus geführt wurden, und sprachen: \"Des Geldes wegen, das beim vorigen Male wieder in unsere Säcke geriet, werden wir hereingebracht. Man will einen Vorwand gegen uns haben, uns überwältigen und uns als Sklaven behalten, samt unseren Eseln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'So traten sie zu dem Manne, der Josephs Haus verwaltete, und redeten ihn an der Hauspforte an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Sie sprachen: \"Bitte, mein Herr! Wir sind schon einmal hierher gereist, Korn zu kaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Als wir danach in die Herberge kamen und unsere Säcke öffneten, da lag eines jeden Geld oben in seinem Sack, unser Geld nach seinem Vollgewicht. Nun bringen wir es eigenhändig zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Wir bringen auch anderes Geld, um Korn zu kaufen. Wir wissen nicht, wer unser Geld in unsere Säcke gelegt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Er sprach: \"Beruhigt euch! Fürchtet euch nicht! Euer und eures Vaters Gott hat euch heimlich einen Schatz in eure Säcke gelegt. Euer Geld ist mir zugekommen.\" Dann gab er ihnen Simeon heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Darauf führte der Mann die Männer in Josephs Haus und brachte Wasser, daß sie sich die Füße wuschen, und ihren Eseln gab er Futter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sie aber legten das Geschenk zurecht, bis Joseph mittags käme; denn sie hatten gehört, daß sie dort das Mahl einnehmen sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Joseph trat nun ein; da überreichten sie ihm das Geschenk, das sie bei sich hatten, und neigten sich vor ihm bis zur Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Er fragte nach ihrem Befinden und sprach: \"Wie geht es eurem alten Vater, von dem ihr gesprochen? Lebt er noch?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie sprachen: \"Gut geht es deinem Diener, unserem Vater: Er lebt noch.\" Dabei bückten und verneigten sie sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Wie er aber seine Augen erhob, erblickte er seinen Vollbruder Benjamin. Da sprach er: \"Ist das euer jüngster Bruder, von dem ihr zu mir gesprochen?\" Dann sprach er: \"Gott gebe dir Huld, mein Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Joseph aber brach schnell ab; denn sein Herz brannte nach seinem Bruder, und er ward zu Tränen gerührt. So ging er in das innere Gemach und weinte dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Dann wusch er sein Antlitz, trat hervor, hielt an sich und sprach: \"Tragt das Mahl auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Da trug man ihm und jenen besonders auf, ebenso den Ägyptern, die mit ihm speisten. Denn die Ägypter dürfen nicht mit den Hebräern zusammen speisen; das ist für die Ägypter ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sie saßen aber nach seiner Weisung, vom Ältesten bis zum Jüngsten genau nach dem Alter geordnet. Staunend sahen sich die Männer an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Er aber ließ von sich zu ihnen Gerichte hinüberbringen; Benjamins Gericht war dabei fünfmal größer als ihrer aller Gerichte. Dann tranken sie und wurden bei ihm guter Dinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Hierauf gebot er seinem Hausverwalter: \"Fülle die Säcke der Männer mit Korn, soviel sie tragen können, und leg eines jeden Geld oben in seinen Sack!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Und meinen silbernen Becher leg oben in den Sack des jüngsten samt dem Geld für sein Getreide!\" Er tat so, wie Joseph gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Als der Morgen anbrach, entließ man die Männer mit ihren Eseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Eben waren sie zur Stadt hinausgegangen, noch nicht weit, da sprach Joseph zu seinem Hausverwalter: \"Auf! Jag den Männern nach! Holst du sie ein, dann sprich zu ihnen: \'Warum vergeltet ihr Gutes mit Bösem?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist es nicht der Becher, aus dem mein Herr trinkt und weissagt? Ihr habt übel daran getan, daß ihr so gehandelt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Er holte sie ein und redete also zu ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Sie sprachen zu ihm: \"Warum spricht mein Herr solcherlei? Ferne sei es deinen Sklaven, so etwas zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Haben wir doch das Geld, das wir in unseren Säcken oben fanden, dir aus dem Lande Kanaan zurückgebracht. Wie sollten wir aus deines Herren Haus Silber oder Gold stehlen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei wem von deinen Sklaven er sich findet, der soll sterben! Wir anderen wollen meinem Herrn leibeigen sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Da sprach er: \"So sollte es eigentlich sein, wie ihr sagt. Doch soll nur der, bei dem er sich findet, mir leibeigen sein; ihr anderen aber geht frei aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Da ließ jeder eilends seinen Sack zur Erde und öffnete seinen Sack.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Er aber fing zu suchen an. Beim Ältesten hatte er angefangen und endete beim jüngsten. Da fand sich der Becher in Benjamins Sack.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Darauf zerrissen sie ihre Kleider, beluden jeder seinen Esel und kehrten in die Stadt zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'So kam Juda mit seinen Brüdern in Josephs Haus; dieser aber war noch dort, und sie fielen vor ihm zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph aber sprach zu ihnen: \"Was ist das für eine Tat, die ihr getan? Habt ihr nicht gewußt, daß ein Mann wie ich richtig ahnen kann?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Da sprach Juda: \"Was sollen wir meinem Herrn sagen? Was reden? Wie uns rechtfertigen? Gott hat die Schuld deiner Sklaven gefunden. Wir sind jetzt Sklaven unseres Herrn, wir so gut wie der, bei dem sich der Becher gefunden hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Er sprach: \"Ferne sei es nur, das zu tun! Der Mann, bei dem sich der Becher gefunden hat, soll allein mir leibeigen sein. Ihr anderen aber zieht in Frieden zu eurem Vater!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda zu ihm und sprach: \"Bitte, mein Herr! Möchte dein Sklave ein Wort an meinen Herrn richten dürfen, ohne daß dein Zorn gegen deinen Sklaven entbrenne! Du bist ja wie Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr hat seine Sklaven gefragt: \'Habt ihr noch einen Vater oder einen Bruder?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da sagten wir zu meinem Herrn: \'Wir haben noch einen alten Vater. Ein kleiner, spätgeborener Sohn ist auch da. Sein Bruder aber ist tot, und so ist er allein von seiner Mutter übrig und ist seines Vaters Liebling.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Du sprachst zu deinen Sklaven: \'Bringt ihn zu mir herab, damit ich ihn mit eigenen Augen sehe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Da sprachen wir zu meinem Herrn: \'Der Knabe kann seinen Vater nicht verlassen; denn verließe er seinen Vater, so stürbe dieser.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Du aber sprachest zu deinen Sklaven: \'Kommt euer jüngster Bruder nicht mit euch herab, dann dürft ihr nimmermehr mein Antlitz schauen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Als wir zu deinem Sklaven, unserem Vater, hinaufgezogen, berichteten wir ihm meines Herrn Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Da sprach unser Vater: \'Kauft uns nochmals etwas Korn.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Da sagten wir: \'Wir können nicht hinabziehen; nur wenn unser jüngster Bruder mit uns geht, ziehen wir hinab. Wir dürfen ja dem Manne nicht mehr unter die Augen kommen, ist unser jüngster Bruder nicht bei uns.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da sprach zu uns dein Sklave, mein Vater: \'Ihr wißt: Mein Weib hat mir zwei Söhne geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Der eine ist von mir gegangen. Ich sagte mir: Sicherlich ist er zerrissen worden. Bis heute habe ich ihn nicht mehr gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Nehmt ihr mir auch diesen weg und träfe ihn ein Leid, dann senktet ihr mein graues Haar im Leid zur Unterwelt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Und nun, komme ich zu deinem Sklaven, meinem Vater, und ist der Knabe nicht bei uns, an dem seine Seele hängt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'dann stürbe er, sobald er sieht, der Knabe ist nicht mehr da, und deine Sklaven senkten deines Sklaven, unseres Vaters, graues Haar in Jammer zur Unterwelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Weil sich dein Sklave für den Knaben meinem Vater so verbürgt hat: \'Wenn ich ihn dir nicht bringe, dann will ich lebenslang vor meinem Vater schuldig sein\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'so möchte dein Sklave an des Knaben Statt bleiben, als meines Herren Leibeigener! Der Knabe aber ziehe mit seinen Brüdern hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Wie könnte ich zu meinem Vater ziehen ohne den Knaben bei mir? Nie könnte ich das Leid ansehen, das meinen Vater überkäme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da konnte Joseph nicht länger an sich halten, trotz allen Umstehenden. Er rief: \"Schafft jedermann von mir hinaus!\" Und so war niemand bei ihm, als sich Joseph seinen Brüdern zu erkennen gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Er brach in lautes Weinen aus, daß es einige Ägypter hörten; auch Pharaos Haus vernahm davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Dann sprach Joseph zu seinen Brüdern: \"Ich bin Joseph. Lebt mein Vater noch?\" Da konnten ihm seine Brüder keine Antwort geben; so bestürzt standen sie vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sprach Joseph zu seinen Brüdern: \"Tretet zu mir her!\" Und sie traten näher. Er sprach: \"Ich bin euer Bruder Joseph, den ihr nach Ägypten verkauft habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Nun aber grämt euch nicht! Nicht dünke es euch peinlich, daß ihr mich hierher verkauft habt! Denn zur Erhaltung eures Lebens hat mich Gott euch vorausgesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Zwei Jahre schon ist der Hunger im Lande, noch aber kommen fünf Jahre, wo nicht Pflügen noch Ernten ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'So hat mich Gott euch vorausgesandt, euch eine Zuflucht auf Erden zu schaffen, euch am Leben zu erhalten in wunderbarer Rettung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Somit habt nicht ihr mich hierhergesandt, sondern Gott. Er machte mich für Pharao zu einem Vater, zum Herrn für sein ganzes Haus und zum Gebieter über ganz Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Zieht eilends zu meinem Vater hinauf! Dann sageet ihm: \'So spricht dein Sohn Joseph: Gott hat mich zum Herrn über ganz Ägypten gesetzt. Komm herab zu mir und säume nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Dann läßt du dich im Lande Gosen nieder und bleibst in meiner Nähe, du, deine Söhne, deine Enkel, deine Schafe, deine Rinder und alles, was dein ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Und ich versorge dich dort; denn noch fünf Jahre währt der Hunger, daß du nicht verkümmerst mit deinem Haus und allem, was dein ist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ihr seht es mit eigenen Augen, auch mein Bruder Benjamin, daß ich es bin, der zu euch spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Dann meldet meinem Vater all meine Ehre in Ägypten und alles, was ihr geschaut! Dann bringt ihr eilends meinen Vater hierher.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und er fiel seinem Bruder Benjamin um den Hals und weinte; auch Benjamin weinte an seinem Hals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Dann küßte er all seine Brüder und weinte an ihnen. Nun erst konnten seine Brüder mit ihm sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und die Kunde drang in Pharaos Haus, indem man sprach: \"Josephs Brüder sind gekommen.\" Und Pharao mit seinen Dienern war darüber erfreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Pharao sprach zu Joseph: \"Sag deinen Brüdern: \'Tut also! Beladet eure Lasttiere und zieht ins Land Kanaan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Holt euren Vater sowie eure Familie und kommt zu mir! Ich gebe euch, was das Ägypterland Gutes bietet, und von des Landes Wohlstand sollt ihr genießen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'So bist du ermächtigt: \'Tut also! Nehmt aus Ägypterland euch Wagen für eure Kinder und Weiber mit! Dann laßt ihr euren Vater aufsteigen und kommt her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Laßt\'s euch nicht leid sein um euren Hausrat! Denn was das ganze Land Ägypten Gutes bietet, soll euer Sein.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Die Söhne Israels taten so. Und Joseph gab ihnen Wagen nach Pharaos Geheiß. Auch gab er ihnen Zehrung auf die Reise mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Allen aber, Mann für Mann, hatte er ein Ehrenkleid geschenkt; dem Benjamin aber hatte er 300 Silberlinge und fünf Ehrenkleider gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Ebenso sandte er seinem Vater zehn Esel, beladen mit Ägyptens bestem Gut, sowie zehn Eselinnen, beladen mit Korn, Brot und Reisekost für seinen Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Dann entließ er seine Brüder, und sie zogen fort. Er sagte noch zu ihnen: \"Säumt euch nicht auf dem Wege!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'So zogen sie aus Ägypten hinauf und kamen ins Land Kanaan zu ihrem Vater Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Und sie berichteten ihm: \"Joseph lebt noch. Ja, er waltet über ganz Ägypterland.\" Da erstarrte sein Herz; denn er glaubte ihnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Sie aber berichteten ihm alle Worte Josephs, die er an sie gerichtet. Er sah die Wagen, die Joseph gesandt, ihn hinzubringen. Da lebte der Geist ihres Vaters Jakob auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Und Israel sprach: \"Genug! Mein Sohn Joseph lebt noch. Ich gehe hin und will ihn sehen, bevor ich sterbe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'So brach Israel mit all seiner Habe auf und kam nach Beerseba. Da brachte er dem Gott seines Vaters Isaak Opfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Und Gott sprach zu Israel in einem Nachtgesichte. Er sprach: \"Jakob! Jakob!\" Er sprach: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Er sprach: \"Ich bin Gott, der Schutzgott deines Vaters. Fürchte dich nicht; nach Ägypten zu ziehen! Denn dort mache ich dich zu einem großen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich selber ziehe mit dir nach Ägypten und ich selber führe dich wieder herauf. Und Joseph wird dir die Hand auf die Augen legen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da brach Jakob von Beerseba auf, und Israels Söhne hoben ihren Vater Jakob, ihre Kinder und Weiber auf die Wagen, die Pharao gesandt hatte, ihn zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und sie nahmen ihre Herden mit und ihre Fahrnis, die sie im Lande Kanaan erworben hatten. So kam Jakob mit seiner ganzen Nachkommenschaft nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Bei ihm waren seine Söhne und Enkel, ferner seine Töchter und Enkelinnen, brachte er doch seine ganze Nachkommenschaft mit sich nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dies sind die Namen der Söhne Israels, die nach Ägypten kamen, Jakobs und seiner Söhne: Jakobs Erstgeborener Ruben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Rubens Söhne sind Chanok, Pallu, Chesron und Karmi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeons Söhne sind Jemuel, Jamin, Ohad, Jakin und Sochar sowie der Kanaaniterin Sohn, Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Levis Söhne sind Gerson, Kehat und Merari,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Judas Söhne sind Ger, Onan, Sela, Peres und Zerach; Ger und Onan aber starben schon im Lande Kanaan, und des Peres Söhne sind Chesron und Chamul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Issakars Söhne sind Tola, Pua, Job und Simron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Zabulons Söhne sind Sered, Elon und Jachleel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Dies sind die Söhne der Lea, die sie Jakob zu Paddan Aram gebar, sowie seine Tochter Dina; alles zusammen 33 Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gads Söhne sind Siphjon, Chaggi, Suni, Esbon, Eri, Arodi und Areli.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Assers Söhne sind Jimna, Jisma, Jiswi, Beria sowie ihre Schwester Serach; Berias Söhne sind Cheber und Malkiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Dies sind die Söhne Zilpas, die Laban seiner Tochter Lea mitgegeben; sie hatte diese dem Jakob geboren, sechzehn Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne Rachels, des Weibes Jakobs, sind Joseph und Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Dem Joseph aber wurden im Land Ägypten Kinder geboren, die ihm Asenat, die Tochter Potipheras, des Priesters von On, gebar: Manasse und Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Benjamins Söhne sind Bela, Beker, Asbel, Gera, Naaman, Echi, Nos, Muppim, Chuppim und Ard.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Dies sind Rachels Söhne, die dem Jakob geboren worden, zusammen vierzehn Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Dans Sohn ist Chusim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naphtalis Söhne sind Jachseel, Guni, Jeser und Sillem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Dies sind die Söhne Bilhas, die Laban seiner Tochter Rachel mitgegeben; sie hatte diese dem Jakob geboren, zusammen sieben Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Aller Seelen, die mit Jakob nach Ägypten kamen, seine leiblichen Nachkommen, ohne die Weiber der Jakobssöhne, waren es sechsundsechzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und der Söhne Josephs, die ihm in Ägypten geboren wurden, waren es zwei. Aller Seelen des Jakobshauses, die nach Ägypten kamen, waren es siebzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Nun sandte er Juda zu Joseph voraus, daß er vor ihm Gosen benachrichtige. Und sie kamen ins Land Gosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Da ließ Joseph seinen Wagen einspannen und fuhr hinauf nach Gosen, seinem Vater Israel entgegen. Als er vor ihm erschien, fiel er ihm um den Hals und weinte noch lange an seinem Hals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Dann sprach Israel zu Joseph: \"Jetzt sterbe ich gern, nachdem ich dein Antlitz gesehen und weiß, daß du lebst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph aber sprach zu seinen Brüdern und zu den anderen Hausgenossen seines Vaters: \"Ich will vorauf, es Pharao melden und ihm sagen: \'Meine Brüder sowie meines Vaters Hausgenossen, die im Lande Kanaan waren, sind zu mir gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Schafhirten aber sind diese Männer; denn Viehzüchter waren sie von je. Sie haben ihre Schafe, Rinder und alle ihre Habe mitgebracht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch nun Pharao rufen läßt und spricht: \'Was ist euer Gewerbe?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'dann sagt: \'Von Jugend auf bis heute sind deine Sklaven Viehzüchter gewesen, wir wie auch unsere Väter\', damit ihr im Lande Gosen bleiben dürft; denn jeder Schafhirte ist den Ägyptern ein Greuel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'So kam Joseph, meldete es Pharao und sprach: \"Mein Vater und meine Brüder mit ihren Schafen und Rindern und all ihrer Habe sind aus dem Lande Kanaan gekommen und sind jetzt im Lande Gosen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Er hatte aber fünf der tüchtigsten seiner Brüder mitgenommen. Diese stellte er dem Pharao vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Da sprach Pharao zu seinen Brüdern: \"Was ist euer Gewerbe?\" Sie sprachen zu Pharao: \"Schafhirten sind deine Sklaven, wir wie unsere Väter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Dann sprachen sie zu Pharao: \"Wir sind gekommen, im Land zu Gaste zu sein, weil es keine Weide mehr für deiner Sklaven Schafe gibt. Schwer ist ja der Hunger im Lande Kanaan. Nun möchten deine Sklaven in dem Lande Gosen weilen dürfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sprach Pharao zu Joseph: \"Dein Vater und deine Brüder sind zu dir gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Offen steht dir das Ägypterland. Siedle deinen Vater und deine Brüder im besten Teil des Landes an! Sie mögen in dem Lande Gosen wohnen, und findest du, daß unter ihnen tüchtige Leute sind, dann kannst du sie zu Aufsehern über meine Herden machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Da führte Joseph seinen Vater Jakob hinein und stellte ihn Pharao vor. Jakob aber begrüßte Pharao mit einem Segenswunsch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Da sprach Pharao zu Jakob: \"Wie viele Lebensjahre zählst du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Da sprach Jakob zu Pharao: \"Die Dauer meiner Wanderschaft beträgt 130 Jahre. Wenig und böse sind meine Lebensjahre gewesen. Sie reichen nicht an die Lebensjahre meiner Väter in den Tagen ihrer Pilgerschaft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Dann segnete Jakob den Pharao. Und so verließ er den Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Und Joseph siedelte seinen Vater und seine Brüder an und gab ihnen im Lande Ägypten Besitz, im besten Teile des Landes, im Lande Ramses, wie Pharao befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater, seine Brüder und die ganze Familie seines Vaters mit Brot, vornehmlich die Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Nun gab es auf der ganzen Erde kein Brot mehr; denn der Hunger war sehr stark. Auch das Land Ägypten war ebenso vom Hunger erschöpft wie das Land Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Joseph aber hatte alles Geld im Land Ägypten und im Lande Kanaan an sich gebracht für das Getreide, das sie kaufen mußten. Und Joseph hatte das Geld in Pharaos Haus gebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'So war das Geld im Lande Ägypten und im Lande Kanaan verschwunden. Da kam ganz Ägypten zu Joseph und sprach: \"Gib uns Brot! Warum sollen wir vor deinen Augen sterben, nur weil das Geld zu Ende ging?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Da sprach Joseph: \"Gebt eure Herden her! Dann gebe ich euch um eure Herden etwas, wenn das Geld zu Ende ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'So brachten sie ihre Herden zu Joseph, und Joseph gab ihnen Brot um die Rosse, die Schaf- und Rinderherden und die Esel. So versorgte er sie mit Brot um den Preis all ihrer Herden in jenem Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'So verging jenes Jahr. Da kamen sie im zweiten Jahre wieder zu ihm und sprachen zu ihm: \"Wir können es meinem Herrn nicht verhehlen: Wenn das Geld zu Ende ist und der Besitz an Vieh an meinen Herrn übergeht, dann ist nichts mehr vor meinem Herrn übrig als unser Leib und unser Ackerland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollen wir vor deinen Augen hinsterben, wir und unser Ackerland? Kaufe uns und unser Ackerland um Brot! Wir wollen mit unserem Ackerland dem Pharao fronen. Aber gib Saatkorn her, daß wir leben und nicht sterben und daß das Ackerland nicht veröde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'So kaufte Joseph den ganzen Ackerboden Ägyptens für Pharao; denn die Ägypter verkauften jeder sein Feld. So hatte sie der Hunger gedrückt. Und das Land kam in Pharaos Besitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Das Volk aber ließ er in Städte übersiedeln von einem Ende Ägyptens bis zum anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur das Ackerland der Priester kaufte er nicht. Denn die Priester hatten vom Pharao ein festes Einkommen. So lebten sie von ihrem Einkommen, das ihnen Pharao gewährte. Deshalb verkauften sie ihr Ackerland nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Da sprach Joseph zu den Leuten: \"Nun habe ich euch samt eurem Ackerland für Pharao gekauft. Hier habt ihr Saatkorn. Dann könnt ihr das Ackerland besäen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Aber bei der Ernte müßt ihr ein Fünftel dem Pharao abliefern. Die anderen vier Fünftel sollen euch gehören zur Aussaat fürs Feld und zu eurem Unterhalt und dem eurer Familien und zur Nahrung der Kinder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Sie sprachen: \"Du rettest uns das Leben. Möchten wir Gnade finden in meines Herrn Augen! Dann wollen wir Pharaos Sklaven sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'So machte es Joseph zum Gesetz bis auf diesen Tag für Ägyptens Ackerland, daß dem Pharao ein Fünftel gehöre. Nur das Ackerland der Priester allein war Pharao nicht zugefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Israel aber blieb im Lande Ägypten, im Lande Gosen. Sie setzten sich darin fest, waren fruchtbar und mehrten sich stark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte im Lande Ägypten 17 Jahre. Der Tage Jakobs, seiner Lebensjahre wurden 147 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Als die Tage Israels dem Tod zugingen, rief er seinen Sohn Joseph und sprach zu ihm: \"Gelte ich dir etwas, dann lege deine Hand unter meine Lende! Dann erweist du mir treue Liebe. Begrabe mich nicht in Ägypten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Bei meinen Vätern möchte ich liegen! Möchtest du mich fort aus Ägypten bringen und mich in ihrem Grabe bestattend Er sprach: \"Ich tue, wie du sagst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Er sprach: \"Schwöre mir!\" Da schwur er ihm. Israel aber neigte sich zu Häupten des Bettes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Nach diesen Begebnissen ward Joseph gemeldet: \"Dein Vater ist erkrankt.\" Da nahm er seine beiden Söhne mit, Manasse und Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Man meldete es Jakob und sprach. \"Da kommt dein Sohn Joseph zu dir.\" Da nahm Israel seine Kräfte zusammen und setzte sich aufrecht im Bett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: \"Gott, der Allmächtige, ist mir zu Luz im Lande Kanaan erschienen, hat mich gesegnet und zu mir gesprochen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, '\'Ich lasse fruchtbar dich und zahlreich werden und mache dich zu einer Völkermenge und gebe dieses Land deinem Stamme nach dir zum ewigen Besitz.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Nun sollen mir deine beiden Söhne gehören, die dir im Ägypterland geboren worden, bevor ich zu dir nach Ägypten kam! Ephraim und Manasse seien mein wie Ruben und Simeon!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Aber die Kinder, die du nach ihnen gezeugt, seien dein! Auf ihrer Brüder Namen seien sie zu ihrem Erbteil berufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Als ich aus Paddan kam, starb mir deine Mutter Rachel im Lande Kanaan unterwegs, nur noch eine Strecke Wegs bis Ephrat. Dort begrub ich sie am Wege nach Ephrat, das ist Bethlehem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Als Israel die Söhne Josephs sah, sprach er: \"Wer sind die?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Da sprach Joseph zu seinem Vater: \"Dies sind meine Söhne, die Gott mir hier geschenkt hat.\" Er sprach: \"Bring sie zu mir her, daß ich sie segne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Israels Augen nämlich waren stumpf geworden vor Alter, daß er nicht mehr sehen konnte. Da führte er sie zu ihm, und er küßte sie und herzte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Und Israel sprach zu Joseph: \"Ich hätte nimmermehr geglaubt, dich wiederzusehen. Nun hat mich Gott selbst deinen Stamm noch sehen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Da nahm sie Joseph von seinen Knien und verneigte sich bis auf den Boden vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Dann nahm Joseph die beiden, Ephraim an seine Rechte, links von Israel, und Manasse an seine Linke, rechts von Israel, und führte sie zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Da streckte Israel seine Rechte aus und legte sie auf Ephraims Haupt, obschon er der Jüngere war, und seine Linke auf das Haupt Manasses, seine Hände kreuzend, obschon Manasse der Erstgeborene war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Dann segnete er Joseph und sprach: \"Der Gott, vor dem einst meine Väter Abraham und Isaak sind gewandelt, der Gott, der ist mein Hirte, seit ich bin gewesen, bis auf diesen Tag,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der von jedem Übel mich erlöst, er segne diese Knaben! In ihnen lebe fort mein Name und meiner Väter Abraham und Isaak Name fort und fort! Sie sollen sich auf Erden mehren und wachsen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Als aber Joseph sah, daß sein Vater seine Rechte auf Ephraims Haupt legte, mißfiel ihm dies, und er griff nach seines Vaters Hand, um sie von Ephraims Haupt auf das Haupt Manasses zu legen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Und Joseph sprach zu seinem Vater: \"Nicht so! Mein Vater! Ist dieser doch der Erstgeborene. Lege deine Hand auf sein Haupt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Sein Vater aber weigerte sich und sprach: \"Ich weiß, mein Sohn; ich weiß. Auch er wird ein Volk; auch er wird mächtig. Jedoch sein jüngerer Bruder wird mächtiger als er. Sein Stamm wird zur Völkerfülle werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'So segnete er sie an jenem Tage und sprach: \"Mit dir soll Israel segnen, also sprechend: \'Gott mache dich wie Ephraim und wie Manasse!\'\" So setzte er Ephraim vor Manasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Dann sprach Israel zu Joseph: \"Siehe! Ich sterbe. Doch Gott ist mit euch, und so führt er euch heim in eurer Väter Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ich aber gebe dir vor deinen Brüdern Sichem, jenes einzige Stück, das ich den Amoritern einst mit meinem Schwert und Bogen abgenommen habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Jakob berief nun seine Söhne und sprach: \"Versammelt euch, damit ich euch verkünde, was euch begegnet in der Folgezeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Schart euch zusammen! Ihr Jakobssöhne, hört! Auf euren Vater Israel hört jetzt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, '\"Ruben! Mein Erstling du, du meine Kraft, du Erstling meiner Stärke! Aufrechter Pflock! Du starker Pflock!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Des Wassers Überschwang sei nimmer dir zu eigen! Denn du erstiegest deines Vaters Bett, entweihtest mit Gewalt mein Lager.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, '\"Simeon und Levi! Das Brüderpaar. Des Unrechts Waffen waren ihre Schwerter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Nicht möchte meine Seele ihrem Plane beitreten! Nicht möchte mein Gemüt mit ihrem Anschlag sich befreunden! In ihrem Zorne mordeten sie Männer, verstümmelten in ihrer Laune Stiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht ihr Zorn, der stark, ihr Grimm, so hart! Und so verteile ich in Jakob sie, zerstreue sie in Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, '\"Dich, Juda, sollen deine Brüder preisen! Am Nacken deiner Feinde deine Hand! Die Söhne deines Vaters neigen sich vor dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Ein junger Leu ist Juda. Mein Sohn, vom Raube stiegest du empor. Er kauert, lagert wie der Leu, wie eine Löwin. Wer mag ihn reizen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nicht weicht das Zepter je von Juda und nie der Herrscherstab von ihm, bis sein Ersehnter kommt, auf den die Völker hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Sein Eselsfüllen bindet er an einen Weinstock und an die Edelrebe seiner Eselin Junges. Er wäscht in Wein sein Kleid, im Traubenblute sein Gewand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Von Wein die Augen fröhlich, die Zähne weiß von Milch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, '\"Und Zabulon wohnt an dem Meeresstrand und fährt auf Schiffen, und seine Flanke reicht an Sidon.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, '\"Issakar ist ein starker Esel, der zwischen Höhen lagert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Er fand, daß Ruhe etwas Schönes und daß das Land gar prächtig. So beugte er zum Tragen seinen Nacken und ward ein Fronknecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, '\"Und Dan schafft seinem Volke Recht, wie einer nur von Israels Stämmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Am Weg ist eine Schlange Dan und eine Hornviper am Pfad; sie beißt das Roß in seine Hinterfüße, und rückwärts stürzt sein Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Auf Deine Hilfe hoff ich, Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, '\"Den Gad umdrängt die Raubschar; doch schon drängt er dem Nachtrab nach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, '\"Von Asser stammt gar fette Speise; er liefert königliche Leckerbissen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, '\"Und Naphtali ist eine heilige Hirschkuh, die schöne Lämmer wirft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, '\"Ein Stier ist Joseph, ein Stier an einer Quelle. Jungmänner ziehen gegen diesen Stier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Und ihn bedrängen Pfeilschützen, die ihn beschießen und ihm zusetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Doch wird ihr Bogen unbiegsam, und ihrer Hände Arme zittern vor dem Jakobsfürsten und vor des Israelsohnes Hirten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Dir helfe deines Vaters Gott, und der Allmächtige segne dich mit Himmelssegen oben, mit Segnungen der Tiefe drunten, mit Segnungen an Brust und Schoß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segenswünsche deines Vaters, sie übertreffen jene meiner Eltern, den Wunsch der alten Hirten. Gelangen mögen sie auf Josephs Haupt, ja auf den Scheitel des Geweihten unter seinen Brüdern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, '\"Ein räuberischer Wolf ist Benjamin; am Morgen frißt er Raub und abends teilt er Beute.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'All diese sind die zwölf Stämme Israels, und dies war es, was ihr Vater zu ihnen gesprochen hat. Er segnete sie; jeden segnete er mit seinem besonderen Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er beschied sie und sprach zu ihnen: \"Ich gehe nun zu meinem Volke ein. Begrabet mich bei meinen Vätern in der Höhle auf dem Feld des Chittiters Ephron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in jener Höhle auf dem Feld der Makpela, Mamre gegenüber im Lande Kanaan, auf jenem Feld, das Abraham von dem Chittiter Ephron zum Erbbegräbnis gekauft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dort hat man Abraham begraben und sein Weib Sara. Dort hat man Isaak begraben und sein Weib Rebekka; dort habe auch ich Lea begraben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'auf jenem Felde und in der Höhle, die von den Söhnen Chets stammt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Als Jakob die Aufträge an seine Söhne beendet hatte, zog er seine Füße auf dem Bett ein, verschied und ward zu seinen Vätern versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da warf sich Joseph auf seinen Vater, weinte über ihm und küßt ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Dann befahl Joseph seinen Dienern, den Ärzten, seinen Vater einzubalsamieren. Da balsamierten die Ärzte Israel ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Darüber vergingen vierzig Tage; denn soviel Tage vergehen mit Einbalsamieren. Man beweinte ihn in Ägypten siebzig Tage lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Als aber die Tage seiner Beweinung vorüber waren, sprach Joseph zu Pharaos Haus also: \"Habe ich in euren Augen Gnade gefunden, dann legt für mich ein Wort bei Pharao ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat mich schwören lassen; er sprach: \'Siehe! Wenn ich tot bin, sollst du mich in meinem Grabe beisetzen, das ich mir im Lande Kanaan gegraben, dort sollst du mich begraben.\' Nun möchte ich hinaufziehen und meinen Vater dort bestatten und wiederkehren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Da sprach Pharao: \"So zieh hinauf! Bestatte deinen Vater, wie er dich hat schwören lassen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'So zog Joseph zur Bestattung seines Vaters hinauf; mit ihm zogen alle Diener Pharaos, die Ältesten seines Hauses und die Ältesten des Landes Ägypten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'sowie das ganze Haus Josephs, seine Brüder und das Haus seines Vaters. Nur ihre Kinder, ihre Schafe und Rinder hatten sie im Lande Gosen gelassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Mit ihm zogen Wagen und Reiter hinauf, ein ganz gewaltiger Zug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'So kamen sie nach Goren Haatad jenseits des Jordan und hielten dort sehr große und feierliche Totenklage Und er hielt für seinen Vater eine siebentägige Totenfeier ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Die Bewohner des Landes aber, die Kanaaniter, sahen die Totenfeier zu Goren Haatad und sprachen: \"Da findet eine große Totenfeier der Ägypter statt.\" Deshalb nannte man seinen Namen Abel Misraim; es liegt jenseits des Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Und seine Söhne taten ihm, wie er ihnen geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Seine Söhne führten ihn in das Land Kanaan und bestatteten ihn in der Höhle des Feldes der Makpela, des Feldes, das Abraham zum Erbbegräbnis von dem Chittiter Ephron gegenüber Mamre erworben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Dann kehrte Joseph nach Ägypten zurück, er und seine Brüder sowie alle, die mit ihm zur Bestattung seines Vaters hinaufgezogen waren, nachdem er seinen Vater bestattet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Als Josephs Brüder sahen, daß ihr Vater gestorben war sprachen sie: \"Wenn Joseph uns befeindete und uns all das Böse, das wir ihm angetan, vergälte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Da sandten sie zu Joseph und ließen sagen: \"Dein Vater hat vor seinem Tode folgendes verordnet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\'Sprecht so zu Joseph: Vergib doch die Missetat deiner Brüder und ihre Sünde, daß sie dir Böses getan!\' Und nun verzeihe doch die Sünde der Verehrer des Gottes deines Vaters!\" Da weinte Joseph, als sie so zu ihm sprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Nun gingen auch seine Brüder hin, fielen vor ihm nieder und sprachen: \"Hier sind wir, deine Leibeigenen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Da sprach Joseph zu ihnen: \"Fürchtet euch nicht! Bin ich an Gottes Statt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr freilich habt Böses wider mich ersonnen; Gott aber hat es zum Guten gelenkt, um bis auf heute vorzusorgen, ein großes Volk am Leben zu erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Nun fürchtet euch nicht. Ich sorge für euch und eure Kinder.\" So tröstete er sie und sprach ihnen Mut zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Joseph blieb in Ägypten, er und seines Vaters Haus. Und Joseph lebte 110 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Joseph sah von Ephraim Urenkel; auch die Söhne Makirs, des Manassesohnes, waren auf Josephs Knien geboren worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Joseph sprach zu seinen Brüdern: \"Ich sterbe; Gott aber sorgt für euch; dann führt er euch aus diesem Lande in das Land, das er Abraham, Isaak und Jakob zugeschworen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Und Joseph ließ die Söhne Israels schwören und sprach: \"Gott nimmt sich eurer an. Dann müßt ihr mein Gebein von hier hinaufbringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'So starb Joseph, 110 Jahre alt. Man balsamierte ihn ein und legte ihn in Ägypten in den Schrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Und dies sind die Namen der Söhne Israels, die nach Ägypten gekommen sind. Mit Jakob sind sie gekommen, jeder mit seiner Familie:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon,Levi, Juda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issakar, Zabulon, Benjamin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naphtali, Gad und Asser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Aller Seelen der aus Jakob Entsprungenen waren es siebzig; Joseph aber war schon in Ägypten gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Da starben Joseph und alle seine Brüder, jenes ganze Geschlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Die Israeliten aber waren fruchtbar geworden; sie wurden überreich, wuchsen und erstarkten mehr und mehr, und das Land ward ihrer voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da trat in Ägypten ein neuer König auf, der von Joseph nichts wußte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Er sprach zu seinem Volk: \"Das Volk der Söhne Israels wird uns zu viel und zu stark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan! Überlisten wir es, daß es nicht weiter wachse! Sonst könnte es sich, falls ein Krieg wider uns ausbreche, zu unseren Gegnern schlagen und gegen uns kämpfen und dann aus dem Lande ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'so setzten sie Fronvögte darüber, um mit Fronarbeiten es zu drücken. Und so baute es Pitom und Ramses zu Vorratsstädten für Pharao aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber je mehr sie es drückten, desto mehr nahm es zu und breitete sich aus. Da graute jenen vor den Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Und so machten die Ägypter die Israeliten gewaltsam zu Sklaven');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und verbitterten ihnen das Leben mit harter Fron in Lehm und Ziegeln und allerlei Fron auf dem Felde. All ihr Frondienst, den man ihnen aufgelegt hatte, geschah mit Plackerei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Dann sprach der König von Ägypten zu den Hebammen der Hebräerinnen; die eine hieß Siphra, die andere Pua.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Er sagte: \"Entbindet ihr die Hebräerinnen, dann beseht ihr die Teile. Ist es ein Knabe, dann tötet ihr ihn. Ist es ein Mädchen, mag es leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Die Hebammen aber fürchteten Gott, und so taten sie nicht, was ihnen der König von Ägypten befohlen, sondern ließen die Knaben am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da schrie der König von Ägypten die Hebammen an und sprach zu ihnen: \"Warum habt ihr dies getan? Ihr ließet die Knaben am Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Da sprachen die Hebammen zu Pharao: \"Die Hebräerinnen sind nicht wie die ägyptischen Weiber; sie sind wie Tiere. Bevor die Hebamme zu ihnen kommt, haben sie geboren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Und Gott ließ es den Hebammen gut ergehen. Das Volk aber wuchs und wurde sehr stark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Weil aber die Hebammen Gott gefürchtet hatten, verlieh er ihnen Vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Pharao aber befahl seinem ganzen Volke: \"Ihr sollt alle Knaben, die geboren werden, in den Nil werfen. Die Mädchen aber sollt ihr am Leben lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Da ging ein Mann aus Levis Haus hin und heiratete eine Tochter Levis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib ward guter Hoffnung und gebar einen Sohn. Als sie sah, daß er kräftig ward, verbarg sie ihn drei Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Länger aber konnte sie ihn nicht verborgen halten. So nahm sie für ihn ein Papyruskästchen, dichtete es mit Asphalt und Pech, legte den Knaben darein und setzte es in das Schilf am Nilufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Seine Schwester aber stellte sich von ferne auf, zu sehen, was mit ihm geschähe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da stieg Pharaos Tochter herab, im Nil zu baden, währenddessen sich ihre Dienerinnen am Nilufer ergingen. Da sah sie das Kästchen mitten im Schilfe. Und sie schickte ihre Magd und ließ es holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Sie öffnete es und sah es, das Kind. Ein weinender Knabe war es. Und er dauerte sie. Sie sprach: \"Dies ist einer von den Knaben der Hebräer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da sprach seine Schwester zu der Tochter Pharaos: \"Soll ich gehen? Dann hole ich dir ein stillendes Weib von den Hebräerinnen, daß sie dir den Knaben stille?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Und Pharaos Tochter sprach zu ihr: \"Geh!\" Da ging das Mädchen und holte des Knaben Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Und Pharaos Tochter sprach zu ihr: \"Nimm diesen Knaben und stille ihn mir! Ich gebe dir einen Lohn dafür.\" Da nahm das Weib den Knaben und stillte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Der Knabe wuchs heran; da brachte sie ihn der Tochter Pharaos, und er galt ihr als Sohn. Sie nannte ihn Moses; sie sagte nämlich: \"Ich habe ihn aus dem Wasser gezogen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'In jener Zeit, als Moses erwachsen war, ging er zu seinen Brüdern hinaus und sah sich ihre Fronarbeiten an. Da sah er, wie ein ägyptischer Mann einen hebräischen Mann, einen seiner Brüder, niederschlug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Er wandte sich nun hierhin und dorthin, und als er sah, daß kein Mensch da war, erschlug er den Ägypter. Dann verscharrte er ihn im Sand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Am andern Tage ging er wieder aus. Da rauften sich zwei Hebräer. Er sprach zu dem Schuldigen: \"Warum schlägst du deinen Genossen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Da sprach er: \"Wer hat dich zum Obmann und Richter über uns gesetzt? Denkst du daran, mich totzuschlagen, wie du den Ägypter totgeschlagen hast?\" Da erschrak Moses und dachte: \"So ist die Sache ruchbar geworden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Auch Pharao erfuhr davon und trachtete, Moses umzubringen. Da floh Moses vor Pharao, kam in das Land Midian und setzte sich an den Brunnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Der Priester Midians aber hatte sieben Töchter. Diese kamen und wollten Wasser schöpfen und die Tränkrinnen füllen, um ihres Vaters Schafe zu tränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Da kamen die Hirten und vertrieben sie. Moses aber stand auf, half ihnen und tränkte ihre Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Als sie zu ihrem Vater Raguel kamen, sprach er: \"Warum kommt ihr heute so bald?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie sprachen: \"Ein ägyptischer Mann hat uns gegen die Hirten geholfen. Er hat fleißig für uns geschöpft. Dann tränkte er die Schafe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sprach er zu seinen Töchtern: \"Wo ist er? Warum habt ihr den Mann dort gelassen? Ladet ihn zum Mahle ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Moses willigte ein, bei dem Manne zu bleiben. Und er gab seine Tochter Sippora dem Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Sie gebar einen Sohn, und er hieß ihn Gersom; denn er sprach: \"Gast bin ich geworden in fremdem Lande.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Nach vielen Tagen starb der König von Ägypten. Die Israeliten aber seufzten unter der Fron und schrien auf. Und ihr Hilferuf stieg zu Gott von der Fron empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott hörte ihr Gestöhn. Gott aber gedachte seines Bundes mit Abraham, Isaak und Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah die Söhne Israels. Und Gott nahm sich ihrer an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moses aber hütete die Schafe seines Schwiegervaters Jetro, des Priesters von Midian. Da trieb er einmal die Schafe nach der Wüste und kam zu dem Gottesberg, an den Horeb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Da erschien ihm der Engel des Herrn mitten im Feuer aus dem Dornbusch heraus. Er sah hin: Der Dombusch brannte in Feuer; aber der Dornbusch ward nicht verzehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Da sprach Moses: \"Ich will doch hingehen, diese großartige Erscheinung zu betrachten, warum der Dornbusch nicht verbrennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Als der Herr sah, daß er herüberkam, um aufzuschauen, da rief ihn Gott aus dem Dornbusche an und sprach: \"Moses! Moses!\" Er sprach: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Er sprach: \"Komm nicht näher! Streif deine Schuhe von den Füßen! Denn der Ort, auf dem du stehst, ist heiliger Boden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Und er sprach: \"Ich bin der Schutzgott deiner Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.\" Da verbarg Moses sein Antlitz; denn er scheute sich, auf Gott zu blicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Der Herr aber sprach: \"Die Quälung meines Volkes in Ägypten habe ich wohl bemerkt und sein Schreien über seine Fronvögte gehört. Ich kenne seine Leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'So fuhr ich denn herab, es aus Ägyptens Hand zu lösen und es aus diesem Lande hinaufzuführen in ein Land, trefflich und weit, in ein Land, das von Milch und Honig fließt, zu dem Sitze der Kanaaniter und Chittiter, der Amoriter, Periziter, Chiwiter und Jebusiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nun ist das Geschrei der Söhne Israels zu mir gedrungen, und ich habe die Quälerei gesehen, mit der die Ägypter sie quälen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'So geh! Ich sende dich zu Pharao. Und führe mein Volk, die Söhne Israels, aus Ägypten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Moses aber sprach zu Gott: \"Wer bin ich, daß ich zu Pharao gehe und die Söhne Israels aus Ägypten führe?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Er sprach: \"Ich selber werde ja mit dir sein. Dies sei für dich das Zeichen, daß ich dich sende. Führst du das Volk aus Ägypten, dann feiert ihr auf diesem Berge ein Fest zu Gottes Ehren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Da sprach Moses zu Gott: \"Ich komme also zu den Söhnen Israels und sage ihnen: \'Der Schutzgott eurer Väter schickt mich zu euch.\' Wenn sie mich fragen: \'Was ist es um seinen Namen?\' was soll ich ihnen sagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Da sprach Gott zu Moses: \"Ich bin der \'Ich bin\'.\" Und er sprach: \"So sollst du zu den Söhnen Israels sprechen: \'Der \"Ich bin\" hat mich zu euch gesandt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und weiter sprach Gott zu Moses: \"So sollst du zu den Söhnen Israels sprechen: \'Der Herr, der Schutzgott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, schickt mich zu euch.\' Für ewig ist dies mein Name und dies für alle Geschlechter meine Bezeichnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Geh! Versammle die Ältesten in Israel und sprich zu ihnen: Der Herr, der Schutzgott eurer Väter, ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, mit der Zusage: Ich achte genau auf euch und auf das, was euch in Ägypten geschieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Und ich sage nun: Ich führe euch aus Ägyptens Elend weg in das Land der Kanaaniter, Chittiter, Amoriter, Periziter, Chiwiter und Jebusiter, in ein Land, von Milch und Honig fließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und hören sie auf dich und kommst du mit den Ältesten Israels zum König von Ägypten, dann sagt ihr zu ihm: \'Der Herr, der Schutzgott der Hebräer, ist uns begegnet. Nun möchten wir drei Tagereisen in die Wüste ziehen und dort dem Herrn, unserem Gott, opfern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ich aber weiß, daß nur unter starkem Druck Ägyptens König euch ziehen läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'So recke ich denn meine Hand aus und schlage Ägypten mit all meinen Wundem, die ich darin wirken werde. Daraufhin läßt er euch ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und ich verschaffe diesem Volke bei den Ägyptern Wohlwollen, daß ihr nicht leer abzieht, wenn ihr geht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Die Weiber sollen sich von ihren Nachbarinnen und von ihren Hausgenossinnen Gold- und Silberschmuck ausbitten und Gewände! Dann legt sie euren Söhnen und Töchtern an und gewinnt so die Ägypter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moses erwiderte und sprach: \"Wenn sie mir aber nicht glauben und nicht auf mich hören, sondern sprechen: \'Der Herr ist dir nicht erschienen\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da sprach der Herr zu ihm: \"Was hast du da in deiner Hand?\" Er sprach: \"Einen Stab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da sprach er: \"Wirf ihn zur Erde!\" Er warf ihn zur Erde. Da ward er eine Schlange, so daß Moses vor ihr floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Da sprach der Herr zu Moses: \"Streck deine Hand aus! Greif sie am Schwanze!\" Er reckte seine Hand aus und packte sie. Da ward sie in seiner Hand zum Stabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '\"Dies sei, damit sie glauben, daß der Herr, der Schutzgott ihrer Väter, dir erschienen ist, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Der Herr sprach weiter zu ihm: \"Bringe deine Hand in deinen Busen!\" Da brachte er seine Hand in den Busen, und als er sie hervorzog, war seine Hand aussätzig wie Schnee.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Er sprach: \"Tu deine Hand wieder in deinen Busen!\" Da tat er seine Hand wieder in seinen Busen und zog sie wieder aus seinem Busen. Da war sie wieder gleich dem anderen Fleische geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '\"Wollen sie dir nicht glauben und nicht auf des ersten Zeichens Sprache hören, dann glauben sie der Sprache dieses letzten Zeichens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Und glauben sie nicht diesen beiden Zeichen und hören sie nicht auf dich, dann nimmst du von dem Nilwasser und gießest es auf das Trockene. Dann wird das Wasser, das du dem Nil entnimmst, auf dem Trockenen zu Blut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Moses sprach zum Herrn: \"Herr! Mit Verlaub! Ich bin kein Mann der Rede. Nicht gestern, nicht ehegestern und auch heute nicht, seit du mit deinem Diener sprichst. Ich bin unbeholfen mit Mund und Zunge.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Da sprach der Herr zu ihm: \"Wer kann dem Menschen einen Mund geben? Wer kann ihn stumm oder taub machen? Wer sehend oder blind? Bin es nicht ich, der Herr?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Und nun geh! Ich will schon mit deinem Munde sein; dann lehre ich dich, was du reden sollst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Er aber sprach: \"Herr! Mit Verlaub! Bestelle es lieber durch jemand anderen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da ward der Herr über Moses zornig und sprach: \"Ist nicht dein Bruder Aaron, der Levite, da? Ich weiß, daß er gut reden kann. Zudem geht er dir gerade entgegen. Und so er dich sieht, freut er sich herzlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Dann sprich mit ihm und lege ihm die Worte in den Mund! Ich aber will mit deinem und seinem Munde sein, und so lehre ich euch, was ihr tun sollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Er selber redet nun für dich zum Volk. So dient er dir zum Mund, und du bist ihm zu einem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und diesen Stab sollst du in die Hand nehmen, um mit ihm die Zeichen zu tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Moses ging und kehrte wieder zu seinem Schwiegervater Jetro und sprach zu ihm: \"Ich möchte gehen und wieder zu meinen Brüdern in Ägypten kehren und sehen, ob sie noch leben.\" Jetro sprach zu Moses: \"Geh in Frieden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Der Herr aber hatte zu Moses in Midian gesprochen: \"Geh! Kehr wieder nach Ägypten! Denn alle Männer sind gestorben, die dir nach dem Leben trachteten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'So nahm Moses sein Weib und seine Söhne, setzte sie auf den Esel und kehrte wieder nach Ägypten. Auch den Gottesstab nahm Moses mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Da sprach der Herr zu Moses: \"Da du wieder nach Ägypten kehrst, sieh zu, daß du all diese Wunder, die ich in deine Macht gelegt, vor Pharao tust! Ich aber verhärte sein Herz, daß er das Volk nicht entläßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Dann sprich zu Pharao: \'So spricht der Herr: Mein erstgeborener Sohn ist Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Ich sage dir: Entlaß meinen Sohn, daß er mich verehre! Doch weigerst du dich, ihn zu entlassen, dann erschlage ich deinen erstgeborenen Sohn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Unterwegs aber in der Herberge stieß der Herr auf ihn und wollte ihn töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Sippora einen Kiesel, beschnitt die Vorhaut ihres Sohnes, rührte damit an seine Füße und sprach: \"Du bist mir ein Blutmahner.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da ließ er von ihm ab. Damals hatte sie gesagt \"Blutmahner\" wegen der Beschneidung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und der Herr sprach zu Aaron: \"Geh Moses entgegen in die Wüste!\" So ging er und traf ihn am Gottesberge und küßte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Dann erzählte Moses dem Aaron alle seine Aufträge, die ihm der Herr gegeben, und alle Zeichen, die er ihm anbefohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Da gingen Moses und Aaron und versammelten alle Ältesten der Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron verkündete alle Aufträge, die der Herr dem Moses gegeben. Und der tat die Zeichen vor den Augen des Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Da glaubte das Volk. Und als es hörte, daß der Herr sich der Söhne Israels angenommen und ihr Elend gesehen habe, verneigten sie sich und warfen sich nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Hernach kamen Moses und Aaron und sprachen zu Pharao: \"So spricht der Herr, der Gott Israels: \'Entlaß mein Volk, daß sie mir ein Fest in der Wüste feiern!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Da sprach Pharao: \"Wer ist der Herr, daß ich ihm gehorchen und Israel entlassen soll? Den Herrn kenne ich nicht, und Israel entlasse ich nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Sie sprachen.- \"Der Gott der Hebräer ist uns begegnet. Wir möchten nur drei Tagereisen in die Wüste gehen und dem Herrn, unserem Gott, opfern, daß er uns nicht mit Pest oder Schwert überfalle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Da sprach der König von Ägypten zu ihnen: \"Warum wollt ihr, Moses und Aaron, das Volk an seiner Arbeit hindern? Kümmert euch doch um eure Sachen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Und Pharao sprach: \"Fürwahr, allzuviel Leute sind schon im Land. Da lasset ihr diese von ihren Arbeiten ausruhen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Und Pharao befahl am gleichen Tage des Volkes Fronvögten und seinen Aufsehern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '\"Liefert kein Stroh mehr dem Volk zum Ziegelmachen wie bisher! Selber sollen sie gehen und Stroh auflesen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Aber den Satz der Ziegel, die sie bisher hergestellt, belaßt für sie! Macht keinen Abzug daran! Faul sind sie, drum schreien sie: \'Laßt uns gehen, unserem Gott zu opfern!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Wuchtig laste die Arbeit auf diesen Leuten, und sie sollen daran zu tun haben, daß sie nicht auf Lügenreden achten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da kamen des Volkes Fronvögte und seine Aufseher heraus und sagten zum Volke: \"So spricht der Pharao: Ich liefere euch kein Stroh mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Geht selber! Holt euch Stroh, wo ihr es findet! Von eurem Frondienst aber wird nichts gekürzt\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da zerstreute sich das Volk über ganz Ägypterland, Stoppeln für die Ziegel zu sammeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Aber die Fronvögte drängten und sprachen: \"Die volle Arbeit müßt ihr täglich liefern wie damals, als es Stroh gab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Da wurden die israelitischen Aufseher gezüchtigt. Ihnen hatten Pharaos Fronvögte die Schuld gegeben, indem sie sprachen: \"Warum habt ihr nicht euer Maß an Ziegeln wie bisher, so auch heute fertig gebracht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'So kamen die israelitischen Aufseher, schrien zu Pharao und sprachen: \"Warum tust du so mit deinen Sklaven?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Stroh wird deinen Sklaven nicht mehr geliefert; doch \'Ziegel\', sagt man uns, \'liefert ab!\' Nun werden deine Sklaven schwer gezüchtigt, indes an dir die Schuld liegt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Er sprach: \"Faul seid ihr, faul. Deshalb sagt ihr: \'Wir wollen gehen, dem Herrn zu opfern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Jetzt marsch! Fort an die Arbeit! Stroh wird euch nicht geliefert; doch den Satz an Ziegeln habt ihr zu liefern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Da sahen die Aufseher der Israeliten sie traurig an und sprachen: \"Ihr dürft das Tagwerk an Ziegeln nicht kürzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Als sie von Pharao weggingen, trafen sie auf Moses und Aaron, die sie erwarteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Sie sprachen zu ihnen: \"Der Herr blicke auf euch und richte, daß ihr uns bei Pharao und seinen Dienern in übelsten Geruch gebracht, ja ihnen das Schwert in die Hand gedrückt habt, uns zu morden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da wandte sich Moses an den Herrn und sprach: \"Herr! Warum tust du diesem Volk so übel? Wozu hast du mich hergesandt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Seit ich zu Pharao gekommen bin, in deinem Namen zu reden, hat er diesem Volke übel getan, und du hast dein Volk nicht davor geschützt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Da sprach der Herr zu Moses: \"Jetzt wirst du sehen, was ich an Pharao tun werde. Gezwungen läßt er sie ausziehen und gezwungen jagt er sie aus seinem Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Und Gott redete mit Moses und sprach zu ihm: \"Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ich erschien Abraham, Isaak und Jakob als allmächtiger Gott; aber mit meinem Namen \"Herr\" habe ich mich ihnen nicht bekannt gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Wie ich meinen Bund mit ihnen errichtet habe, das Land Kanaan ihnen zu geben, das Land, in dem sie zu Gast geweilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'so habe ich auch das Gestöhn der Söhne Israels gehört, die die Ägypter knechten. Und ich gedachte meines Bundes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Daher sprich zu den Söhnen Israels: \'Ich bin der Herr. Ich befreie euch nun vom Frondienst der Ägypter und reiße euch aus ihrer Sklaverei. Ich erlöse euch mit hochgerecktem Arme und gewaltigen Gerichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Ich nehme euch mir zum Volk und bin euch ein Schutzgott. Da erfahret ihr, daß nur ich der Herr bin, euer Gott, der euch befreit vom Frondienst der Ägypter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Ich bringe euch dann in das Land, das ich Abraham, Isaak und Jakob durch feierlichen Schwur verheißen. Ich gebe es euch zum Erbbesitz, ich der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Und Moses berichtete dies den Israeliten. Aber sie hörten nicht auf Moses in ihrer gedrückten Stimmung und wegen der schweren Arbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da sprach der Herr zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '\"Geh! Sprich mit Pharao, dem König von Ägypten, er soll die Söhne Israels aus seinem Land entlassen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Da redete Moses vor dem Herrn also: \"Haben die Israeliten nicht auf mich gehört, wie sollte Pharao auf mich hören? Ich bin ja nicht gewandt im Reden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Da redete der Herr mit Moses und Aaron und entbot sie zu den Israeliten und zu Pharao, dem König von Ägypten, um die Israeliten aus Ägypterland zu führen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind ihre Familienhäupter: Die Söhne Rubens, des Erstgeborenen Israels, waren Chanok, Pallu, Chesron und Karmi. Dies sind die Geschlechter Rubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeons Söhne waren Jemuel, Jamin, Ohad, Jakin, Sochar und Saul, der Kanaaniterin Sohn. Dies sind die Sippen Simeons.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Dies sind die Namen der Söhne Levis nach ihrem Stammbaum: Gerson, Kehat und Merari. Levi ward 137 Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersons Söhne waren Libni und Simi mit ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehats Söhne waren Amram, Ishar, Chebron und Uzziel. Kehat ward 133 Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Meraris Söhne waren Machli und Musi. Dies sind die Sippen der Leviten nach ihrem Stammbaum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram heiratete seine Tante Jokebed. Sie gebar ihm Aaron und Moses; Amram ward 137 Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Ishars Söhne waren Korach, Nepheg und Zikri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Uzziels Söhne waren Misael, Elsaphan und Sitri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Und Aaron heiratete Aminadabs Tochter Eliseba, des Nachson Schwester. Sie gebar ihm Nadab und Abihu, Eleazar und Itamar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korachs Söhne waren Assir, Elkana und Abiasaph. Dies sind die Sippen der Korachiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Aarons Sohn Eleazar hatte eine der Töchter Putiels geheiratet. Sie gebar ihm Pinechas. Dies sind die Familienhäupter der Leviten nach ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'So war es mit Aaron und Moses, zu denen der Herr gesprochen: \"Führt die Söhne Israels in ihren Scharen aus Ägypterland!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Sie sind es, die mit dem König von Ägypten, Pharao, redeten, um die Israeliten aus Ägypten zu führen. So war es mit Moses und Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'So war es an dem Tage, da der Herr mit Moses im Lande Ägypten gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Der Herr sprach zu Moses also: \"Ich bin der Herr. Vermelde Pharao, dem König von Ägypten, alles, was ich dir sage!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Da sprach Moses vor dem Herrn: \"Siehe! Ich bin im Reden ungewandt. Wie soll da Pharao auf mich hören?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Da sprach der Herr zu Moses: \"Siehe, ich mache dich für Pharao zu einem Gott, und dein Bruder Aaron ist dein Prophet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Alles, was ich dir auftrage, sollst du sagen. Doch zu Pharao sage dein Bruder Aaron, er solle die Söhne Israels aus seinem Lande entlassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ich aber will Pharaos Herz verhärten und im Ägypterland meine Zeichen und meine Wunder mehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'So hört Pharao nicht auf euch, bis ich meine Hand auf Ägypten lege und aus Ägypterland meine Scharen, mein Volk, die Söhne Israels, führe, unter großen Machterweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Dann erfahren die Ägypter, daß ich der Herr bin, wenn ich meine Hand gen Ägypten strecke und aus seiner Mitte die Söhne Israels führe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Moses und Aaron taten so. Wie es der Herr sie hieß, so taten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moses aber war 80 Jahre alt und Aaron 83, als sie mit Pharao verhandelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Und der Herr sprach zu Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '\"Spricht Pharao zu euch: \'Gebt euren Erweis\', dann sprich zu Aaron: \'Nimm deinen Stab und wirf ihn vor Pharao, daß er zur Natter werde!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da kamen Moses und Aaron zu Pharao und taten, wie der Herr befohlen. Aaron warf seinen Stab vor Pharao und seine Diener; da ward er zur Natter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Aber auch Pharao berief die Weisen und Zauberer, und Ägyptens Zauberkünstler taten so mit ihren Künsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Sie warfen jeder seinen Stab hin, und diese wurden zu Nattern. Doch Aarons Stab verschlang ihre Stäbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Aber Pharaos Herz blieb verhärtet; hatte er doch nicht auf sie gehört, wie der Herr vorausgesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Und der Herr sprach zu Moses: \"Des Pharao Herz ist verstockt. Er weigert sich, das Volk zu entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Geh morgen früh zu Pharao! Da geht er an das Wasser. Dann tritt ihm am Nilufer entgegen. Den Stab, der sich zur Schlange wandelt, nimm mit dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Dann sprich zu ihm: \'Der Herr, der Schutzgott der Hebräer, sendet mich zu dir mit der Weisung: \"Entlaß mein Volk, daß sie in der Wüste mir zu Ehren ein Fest feiern!\" Aber bis jetzt hast du nicht hören wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Nun spricht der Herr: \"Daran sollst du erkennen, daß ich der Herr bin: Siehe, ich schlage mit dem Stab in meiner Hand auf das Wasser im Nil, dann wandelt dieses sich in Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Die Fische im Nil sterben, und der Nil wird stinkend; dann ekelt es die Ägypter, Wasser aus dem Nil zu trinken.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Und der Herr sprach zu Moses: \"Sprich zu Aaron: \'Nimm deinen Stab und strecke deine Hand über die Gewässer in Ägypten, über ihre Flüsse, Kanäle, Teiche und alle ihre Wasserstellen, daß sie zu Blut werden!\' Dann ist Blut im ganzen Land Ägypten, im Holzgefäß wie im Steinzeug.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Da taten Moses und Aaron so, wie der Herr befohlen. Er hob den Stab und schlug das Wasser im Nil vor Pharaos und seiner Diener Augen. Da ward alles Wasser im Nil zu Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Die Fische im Nil starben; der Nil ward stinkend; da konnten die Ägypter kein Wasser aus dem Nil trinken. Blut war im ganzen Lande Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Aber auch Ägyptens Zauberkünstler taten ebenso mit ihren Zaubereien. So blieb Pharaos Herz verstockt; hatte er doch nicht auf sie gehört, wie es der Herr vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Und Pharao wandte sich und trat in sein Haus, hatte er sich doch auch dies nicht zu Herzen genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Alle Ägypter gruben nun rings um den Nil nach Trinkwasser, weil sie vom Nilwasser nicht trinken konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'So vergingen volle sieben Tage, nachdem der Herr den Nil geschlagen hatte. Da sprach der Herr zu Moses: \"Geh zu Pharao hinein! Dann sagst du ihm: \'So spricht der Herr: \"Entlasse mein Volk, daß sie mich verehren! Willst du es aber nicht entlassen, dann plage ich dein ganzes Gebiet mit Fröschen. Von Fröschen wimmelt dann der Nil. Sie steigen heraus und kommen in dein Haus, in dein Schlafgemach, auf dein Bett und in deiner Diener und in deines Volkes Häuser, in deine Backöfen und Teigmulden. Selbst an dir, wie an deinem Volke und an allen deinen Dienern, werden die Frösche hinaufsteigen.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und der Herr sprach zu Moses: \"Sprich jetzt zu Aaron: \'Streck deine Hand mit deinem Stab über die Flüsse, Kanäle und Teiche und laß die Frösche über Ägypterland aufsteigen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Da streckte Aaron seine Hand über Ägyptens Gewässer. Da kamen die Frösche und bedeckten das Land Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Aber auch die Zauberkünstler taten ebenso mit ihren Zaubereien. Auch sie ließen Frösche über das Land Ägypten kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Pharao aber rief Moses und Aaron herbei und sprach: \"Leget Fürbitte beim Herrn ein, daß er die Frösche mir und meinem Volke nehme! Dann entlasse ich das Volk, daß es dem Herrn opfere.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Da sprach Moses zu Pharao: \"Sag mir: Auf wann soll ich für dich, deine Diener und dein Volk beten, daß die Frösche von dir und deinen Häusern weichen und nur im Nile bleiben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Da sprach er: \"Auf morgen.\" Er sprach: \"Nach deinem Worte geschehe, daß du erkennst: Keiner ist wie der Herr, unser Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Dann weichen Frösche von dir und deinen Häusern, von deinen Dienern und von deinem Volke und sollen nur noch im Nil bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'So gingen Moses und Aaron von Pharao. Und Moses rief zum Herrn wegen des Versprechens, das er der Frösche halber dem Pharao gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Und der Herr tat nach Mosis Wort. Die Frösche starben weg aus den Häusern, den Gehöften und Feldern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Man schüttete sie zu Haufen und das Land roch übel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Als Pharao aber sah, daß Erleichterung geworden, verstockte er sein Herz, hatte er doch nicht mehr auf sie gehört, wie es der Herr vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Da sprach der Herr zu Moses: \"Sprich zu Aaron: \'Streck deinen Stab aus! Schlag auf dem Boden den Staub! Dann wird er in ganz Ägypterland zu Mücken.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und sie taten so. Aaron streckte seine Hand mit dem Stab aus und schlug den Staub auf dem Boden. Da kamen Stechmücken an Mensch und Vieh. Aller Staub auf dem Boden war zu Stechmücken im Lande Ägypten geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Da taten die Zauberkünstler ebenso mit ihren Zaubereien, die Stechmücken wegzubringen; aber dies konnten sie nicht. Die Stechmücken gingen an Mensch und Vieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Da sprachen die Zauberkünstler zu Pharao: \"Dies ist Gottes Finger.\" Doch Pharaos Herz blieb verhärtet, hatte er doch nicht auf sie gehört, wie es der Herr vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Und der Herr sprach zu Moses: \"Morgen in der Frühe tritt vor Pharao, wenn er ans Wasser geht, und sprich zu ihm: \'So spricht der Herr: \"Entlasse mein Volk, daß es mich verehre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Entlässest du aber mein Volk nicht, dann lasse ich über dich, deine Diener, dein Volk und deine Häuser Fliegen kommen. Die Häuser der Ägypter werden voll von Fliegen, sowie das Ackerfeld, darauf sie sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Aber ausnehmen will ich an jenem Tage das Land Gosen, wo mein Volk weilt, daß dort keine Fliegen seien, damit du erkennest, daß ich Herr inmitten dieses Landes bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Diesen Unterschied mache ich zwischen meinem Volke und deinem Volke. Morgen geschieht dies Zeichen.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und der Herr tat so. Hundsfliegen, eine schwere Menge, kamen in das Haus Pharaos und in das seiner Diener und über ganz Ägypterland; so ward durch die Hundsfliegen das Land verderbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Da rief Pharao nach Moses und Aaron und sprach: \"Geht! Opfert eurem Gott im Lande!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Da sprach Moses: \"Nicht richtig wäre es, so zu tun. Was den Ägyptern ein Greuel ist, opfern wir dem Herrn, unserem Gott. Brächten wir zum Opfer, was den Ägyptern greulich dünkt, würden sie uns nicht steinigen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Wir möchten in die Wüste drei Tagesreisen ziehen und dem Herrn, unserem Gott, opfern, wie der Herr uns geboten hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Da sprach Pharao: \"Nun, ich lasse euch ziehen, dann könnt ihr dem Herrn, eurem Gott, in der Wüste opfern. Nur nicht zu weit entfernet euch! Legt für mich Fürsprache ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Da sprach Moses: \"Sowie ich von dir weggehe, lege ich Fürsprache beim Herrn ein. Morgen weichen von Pharao, seinen Dienern und seinem Volke die Fliegen. Nur möge Pharao nicht weiter trügen, daß er das Volk nicht zum Opfer für den Herrn entläßt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Da ging Moses von Pharao weg und legte Fürbitte beim Herrn ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Und der Herr tat nach Mosis Wort. Die Fliegen wichen von Pharao, seinen Dienern und seinem Volke; nicht eine blieb zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Aber Pharao verstockte sein Herz auch diesmal. Er ließ das Volk nicht ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Da sprach der Herr zu Moses: \"Geh zu Pharao hinein! Dann sprich zu ihm: \'So spricht der Herr, der Schutzgott der Hebräer: Entlaß mein Volk, daß sie mich verehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Verweigerst du aber die Freilassung und hältst sie weiter fest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'dann kommt die Hand des Herrn zum Verderben an dein Vieh auf dem Felde, an Pferde, Esel, Kamele, Rinder und Schafe, eine schrecklich schwere Seuche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Aber einen Unterschied macht der Herr zwischen Israels Vieh und dem Ägyptens: Keinem Israeliten stirbt ein Stück.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Und der Herr bestimmte eine Zeit, indem er sprach: \"Morgen schon tut dies der Herr an dem Lande.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und der Herr tat dies am folgenden Tage. Alles Vieh der Ägypter fiel; aber vom Vieh der Israeliten fiel nicht eines.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Da ließ Pharao nachsehen. Und von Israels Vieh war auch nicht eines gefallen. Doch Pharaos Herz verstockte sich, und er entließ das Volk nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Da sprach der Herr zu Moses und Aaron: \"Füllt eure Hände jetzt mit Ofenruß! Und Moses streue ihn himmelwärts vor Pharaos Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Dann wird er zu feinem Staube über ganz Ägypten und wird an Mensch und Tier in ganz Ägypten zu Beulen, und diese brechen schwärend auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Da nahmen sie Ofenruß, traten vor Pharao, und Moses streute ihn himmelwärts. Da wurden schwärende Beulen, die aufbrachen, an Mensch und Vieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Die Zauberkünstler aber konnten nicht vor Moses stehen wegen der Beulen; denn an den Zauberkünstlern, wie an allen Ägyptern, waren die Beulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Der Herr aber verhärtete Pharaos Herz, hatte er doch nicht auf sie gehört, wie es der Herr dem Moses vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Da sprach der Herr zu Moses: \"In aller Frühe tritt morgen vor den Pharao und sprich zu ihm: So spricht der Herr, der Schutzgott der Hebräer: \'Entlasse mein Volk, daß sie mich verehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn diesmal schicke ich alle meine Plagen auch zu dir wie zu deinen Dienern und deinem Volke, daß du erkennest: Keiner ist auf der ganzen Erde wie ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Schon jetzt könnte ich meine Hand ausstrecken und dich samt deinem Volke mit Seuchen schlagen, daß du von der Erde schwändest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Ich lasse dich doch gerade deshalb leben, damit ich dir meine Macht zeige, damit man auf der ganzen Erde meinen Ruhm künde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Hältst du aber weiterhin mein Volk zurück und willst es nicht entlassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'dann lasse ich morgen um diese Zeit einen überschweren Hagel niedergehen, desgleichen nicht in Ägypten war seit seiner Gründungszeit bis jetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Nun schick hin und birg dein Vieh und alles, was du auf dem Felde hast! All die Menschen und Tiere, die auf dem Felde betroffen werden und nicht unter Dach kommen, sterben, geht der Hagel auf sie nieder.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer nun von Pharaos Höflingen das Wort des Herrn achtete, der flüchtete seine Sklaven und sein Vieh unter Dach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Wer aber des Herrn Wort mißachtete, der ließ seine Sklaven und sein Vieh auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da sprach der Herr zu Moses: \"Streck deine Hand gen Himmel, daß Hagel in ganz Ägypterland falle auf Mensch und Vieh und alles Feldgewächs im Lande Ägypten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Und Moses streckte seinen Stab gen Himmel. Da ließ der Herr Donner und Hagel kommen, und Feuer ging nieder. So ließ der Herr Hagel auf das Land Ägypten fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Ein Hagel war es, und mitten im Hagel ein Flugfeuer, übermächtig. Seinesgleichen war nie über ganz Ägypterland gekommen, seitdem es ein Volk geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel schlug im ganzen Land Ägypten alles auf dem Felde, Mensch und Vieh. Auch alles Feldgewächs schlug der Hagel und zerschmetterte alle Bäume des Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur in dem Lande Gosen, wo die Israeliten waren, fiel kein Hagel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da sandte Pharao, berief Moses und Aaron und sprach zu ihnen: \"Diesmal habe ich gefehlt. Der Herr ist im Recht; ich aber und mein Volk sind im Unrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Legt bei dem Herrn Fürsprache ein! Übergenug des Gottesdonners und des Hagels! Ich lasse euch frei. Ihr sollt nicht länger verweilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Da sprach Moses zu ihm: \"Sobald ich aus der Stadt gehe, breite ich zum Herrn meine Hände. Das Donnern wird aufhören, und der Hagel nicht mehr sein, daß du erkennest: Dem Herrn gehört die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Doch du und deine Diener fürchten noch nicht den Herrn, Gott, wie ich wohl weiß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Der Flachs und die Gerste waren zerschlagen worden; denn die Gerste stand in Ähren, und der Flachs in Blüte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Weizen aber und Spelt waren nicht zerschlagen worden, weil sie spät sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Moses ging nun von Pharao zur Stadt hinaus und breitete seine Hände zum Herrn. Da hörte Donnern und Hageln auf; auch der Regen goß nicht mehr auf die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Als aber Pharao sah, daß Regen, Hagel und Donner aufgehört, verharrte er in seiner Sünde und verstockte sein Herz, samt seinen Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Und Pharaos Herz verhärtete sich, und so ließ er die Israeliten nicht ziehen, wie es der Herr durch Moses vorhergesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Da sprach der Herr zu Moses: \"Geh hinein zu Pharao! Habe ich doch sein und seiner Diener Herz verstockt, daß ich diese Zeichen bei ihm tue,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und daß du Kind und Kindeskindern erzählen kannst, wie ich mich an Ägypten ausgewirkt und welche Zeichen ich an ihnen getan habe. So könnt ihr erkennen, daß ich der Herr bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Da kamen Moses und Aaron zu Pharao und sprachen zu ihm: \"So spricht der Herr, der Schutzgott der Hebräer: \'Wie lange willst du dich nicht vor mir beugen? Entlasse mein Volk, daß es mir diene!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Weigerst du dich aber, mein Volk zu entlassen, dann bringe ich morgen Heuschrecken in dein Gebiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Dann decken sie des Landes Oberfläche, daß man den Boden nicht mehr sieht. Sie fressen dann den Rest, der vom Hagel übrig ist, und sie fressen alle Bäume ab, die euch im Felde sprießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Voll werden davon deine Häuser, all deiner Diener Häuser und die ganz Ägyptens, wie es deine Väter nicht geschaut noch deine Großväter, seit ihrem Erdenwallen bis zu diesem Tag.\'\" Und er wandte sich und ging weg von Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sprachen Pharaos Diener zu ihm: \"Wie lange soll dieser uns eine Gefahr sein? Entlasse die Männer, daß sie dem Herrn, ihrem Gott, dienen! Siehst du nicht, daß Ägypten verdirbt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Da wurden Moses und Aaron zu Pharao zurückgeholt, und er sprach zu ihnen: \"Geht! Dienet dem Herrn, eurem Gott! Doch wer geht mit?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Da sprach Moses: \"Mit unseren Jünglingen und unseren Greisen wollen wir ziehen, mit unseren Söhnen und Töchtern; mit unseren Schafen und Rindern wollen wir ziehen. Wir haben ja ein Fest des Herrn zu feiern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Da sprach er zu ihnen: \"Möge der Herr so bei euch sein, wie ich euch mit euren Kindern fortlasse! Seht, daß ihr Böses im Sinne habt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Daraus wird nichts. Ihr Männer geht und verehrt den Herrn! Das war euer Begehr.\" Und man jagte sie von Pharao fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da sprach der Herr zu Moses: \"Recke deine Hand über das Ägypterland, der Heuschrecken wegen! Sie sollen über das Land Ägypten kommen und im Lande alles Gewächs abfressen, das der Hagel hat stehen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Da streckte Moses seinen Stab über das Ägypterland. Und der Herr führte einen Ostwind über das Land jenen ganzen Tag und die ganze Nacht. Morgen ward es; da hatte der Ostwind die Heuschrecken hergetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'So kamen die Heuschrecken über ganz Ägypterland und fielen im ganzen Bereich Ägyptens übermächtig ein. Nie gab es vorher soviel Heuschrecken, noch wird es später soviel geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Sie deckten des ganzen Landes Oberfläche, daß der Boden nicht mehr zu sehen war. Sie fraßen alles Gewächs im Lande und alle Baumfrüchte, die der Hagel hatte stehen lassen. Nichts Grünes blieb mehr an den Bäumen und Feldgewächsen im Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Eilends ließ Pharao Moses und Aaron rufen und sprach: \"Ich bin im Unrecht wider den Herrn, euren Gott, und wider euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Verzeiht mir doch noch diesmal mein Verschulden und legt bei dem Herrn, eurem Gott, Fürsprache ein, daß er nur diesen Tod von mir wende!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Da ging er von Pharao weg und flehte zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Da ließ der Herr einen sehr starken Westwind wehen. Dieser nahm die Heuschrecken und warf sie ins Schilfmeer. Nicht eine Heuschrecke blieb in Ägyptens ganzem Bereiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber der Herr verstockte Pharaos Herz, und so entließ er die Israeliten nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Und der Herr sprach zu Moses: \"Recke deine Hand gen Himmel! Finsternis komme über Ägypterland, und die Finsternis sei stark!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Da reckte Moses seine Hand gen Himmel, und eine dichte Finsternis ward in ganz Ägypterland, drei Tage lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Keiner sah den anderen und keiner erhob sich von seinem Platz, drei Tage lang. Die Israeliten alle aber hatten Licht in ihren Siedlungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da rief Pharao nach Moses und sprach: \"Geht! Verehrt den Herrn! Eure Schafe und Rinder aber bleiben hier. Doch eure Kinder gehen mit euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Da sprach Moses: \"Auch du selbst solltest uns Schlacht- und Brandopfer liefern, daß wir sie für den Herrn, unseren Gott, zurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Aber auch unser Vieh muß mit uns gehen. Nicht eine Klaue bleibe zurück! Davon müssen wir nehmen können, wenn wir dem Herrn, unserem Gott, zu Ehren ein Fest feiern wollen. Wir wissen ja nicht, wie wir den Herrn verehren sollen, bis wir dorthin kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber der Herr verhärtete Pharaos Herz, und so wollte er sie nicht entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und Pharao sprach zu ihm: \"Geh weg von mir! Hüte dich, noch einmal mein Antlitz zu schauen! Sobald du mein Antlitz siehst, mußt du sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Moses sprach: \"Recht hast du geredet. Ich werde nicht wieder dein Antlitz schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Und der Herr sprach zu Moses: \"Noch eine Plage bringe ich über Pharao und Ägypten. Hernach läßt er euch von hier abziehen, und wenn er lediglich die Entlassung zugibt, dann jagt er euch gewaltsam fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Schärfe dem Volke ein, sie sollen, Männer wie Weiber, von den Bekannten silbernen und goldenen Schmuck erbitten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Und der Herr stimmte die Ägypter dem Volke günstig. Dazu galt der Mann Moses sehr viel in Ägypten, bei Pharaos Dienern wie beim Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Da sprach Moses: \"So spricht der Herr: \'Um Mitternacht fahre ich mitten durch Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Dann stirbt im Lande Ägypten jeder Erstgeborene, von Pharaos Erstgeborenem an, der einst auf seinem Throne sitzen sollte, bis zu dem Erstgeborenen der Sklavin hinter der Handmühle, und alle Erstlingswürfe des Viehes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Dann ist ein groß Gejammer im ganzen Lande Ägypten, desgleichen noch nie gewesen, noch je sein wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Aber gegen keinen der Israeliten streckt ein Hund die Zunge heraus, weder gegen Mensch noch Vieh, daß ihr erkennet, wie der Herr zwischen Israel und Ägypten scheidet.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann beugen sich alle diese deine Diener zu mir, werfen sich vor mir nieder und sprechen: \'Zieh weg, du samt dem ganzen Volke bei dir!\' Hernach ziehe ich weg.\" Und er ging von Pharao in loderndem Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Da sprach der Herr zu Moses: \"Der Pharao hört nicht auf euch, damit sich meine Wunder mehren im Ägypterlande.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'So hatten Moses und Aaron alle diese Wunder vor Pharao getan. Aber der Herr verhärtete Pharaos Sinn, daß er die Israeliten nicht aus seinem Lande entließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Und der Herr sprach zu Moses und Aaron im Lande Ägypten also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '\"Dieser Monat sei für euch der Anfangsmonat! Der Jahresmonde erster sei er für euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Sprecht so zu der Gesamtgemeinde Israels! Am zehnten dieses Monats nehme sich jedermann ein Lamm nach den Sippen, ein Lamm für jedes Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Sind aber in einem Hause zuwenig für ein Lamm, dann nehme er es mit dem Nachbarn, der jenem gleich an Kopfsteuer ist! Jeder nach seinem Verzehr, sollt ihr zum Lamm beisteuern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ein fehlerfreies, männliches, noch nicht jähriges Lämmchen müßt ihr haben; aus den Schafen oder Ziegen sollt ihr es nehmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Dann verwahrt es bis zum vierzehnten des Monats! Dann schlachte es Israels Vollgemeinde abends!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und vom Blute sollen sie nehmen und an beide Pfosten und den Türsturz tun, zum Schutze der Häuser, wo sie es essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Noch in derselben Nacht sollen sie das Fleisch essen, am Feuer gebraten, dazu ungesäuertes Brot. Mit Bitterkräutern sollen sie es essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Eßt nichts davon roh noch gargekocht, sondern gebraten, Kopf mit Beinen und Rumpf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Laßt davon nichts bis zum Morgen übrig! Was bis zum Morgen übrigbleibt, sollt ihr verbrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'So sollt ihr es essen: Eure Hüften gegürtet, eure Schuhe an den Füßen, euren Stab in der Hand! Dann esset es in Hast: Ein Passah ist es dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Denn ich durchziehe in jener Nacht das Ägypterland und schlage alle Erstgeburt im Land Ägypten, Mensch und Vieh. Ich, der Herr, vollziehe das Gericht an Ägyptens Göttern allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Das Blut sei euch zum Zeichen an den Häusern, wo ihr weilt! Sehe ich das Blut, dann übergehe ich euch. Kein verderblicher Streich trifft euch, wenn ich das Land Ägypten schlage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Zum Gedächtnis diene euch dieser Tag. Feiert ihn als ein Fest des Herrn in allen euren Geschlechtern! Als ewige Satzung sollt ihr ihn feiern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Ihr sollt sieben Tage ungesäuertes Brot essen! Genau am ersten Tage sollt ihr aus euren Häusern Sauerteig entfernen - denn wer Gesäuertes ißt, ein solches Wesen werde aus Israel gestrichen! -, vom ersten bis zum siebten Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Am ersten Tage sei heilige Versammlung! Am siebten haltet gleichfalls heilige Versammlung! Dabei darf keine Arbeit verrichtet werden. Nur was jeglich Wesen zu essen haben muß, das allein werde von euch bereitet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Achtet diese Vorschrift! Denn an eben diesem Tage führe ich eure Scharen aus Ägypterland. Haltet diesen Tag in eueren Geschlechtern als ewige Einrichtung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Am vierzehnten des ersten Monds am Abend esset ungesäuertes Brot bis zu dem Abend des einundzwanzigsten des Monats!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Kein Sauerteig finde sich sieben Tage lang in euren Häusern: Wer Gesäuertes ißt, werde aus Israels Gemeinschaft gestrichen! Sei\'s Fremdling, sei\'s Einheimischer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nicht einen Bissen gesäuertes Brot sollt ihr essen! In all euren Siedlungen eßt nur ungesäuertes Brot!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Dann berief Moses alle Ältesten Israels und sprach zu ihnen: \"Zieht aus und holt für eure Sippen Schafe und schlachtet das Passah!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Dann nehmt ein Ysopbüschel, taucht es in das Blut im Becken und streicht von dem Blute im Becken an den Türsturz und an die beiden Türpfosten! Euer keiner soll bis zum Morgen aus der Tür seines Hauses gehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Zieht dann der Herr hindurch, das Ägypterland zu schlagen, und sieht er an dem Türsturz und an den beiden Türpfosten das Blut und übergeht der Herr die Tür, dann läßt er den Verderber nicht eure Häuser zum Schlagen betreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Achtet doch dies Wort! Als Satzung für euch und eure Kinder gelte es auf ewige Zeiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und kommt ihr in das Land, das der Herr euch gibt, wie er verheißen, dann haltet diesen Brauch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und fragen eure Söhne euch: \'Was ist dieser Brauch!\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'dann saget: \'Das ist das Passahopfer für den Herrn, der Israels Häuser im Ägypterland übergangen, als er Ägypten schlug; unsere Häuser aber hat er ausgenommen.\'\" Da neigte sich das Volk und warf sich nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Dann gingen die Israeliten hin und taten so. Wie der Herr Moses und Aaron geboten, so taten sie auch hernach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Da geschah es zur Mitternacht, daß der Herr alle Erstgeburt im Ägypterlande schlug, von Pharaos Erstgeborenem an, der auf seinem Throne sitzen sollte, bis zum Erstgeborenen der Sklavin, die im Kerker lag, und alle Erstlingswürfe des Viehs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Noch in der Nacht stand Pharao auf mit all seinen Dienern und ganz Ägypten, und ein großes Jammern war in Ägypten; denn kein Haus gab es, in dem nicht ein Toter lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Da berief er Moses und Aaron noch in der Nacht und sprach: \"Auf! Fort aus meinem Volke, ihr und die Söhne Israels! Geht! Verehrt den Herrn nach euren Worten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Nehmt auch eure Schafe und Rinder mit, wie ihr gesagt, und zieht fort! Doch segnet mich zuvor!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Auch die Ägypter drängten darauf, das Volk schleunigst aus dem Land zu bringen; denn sie sagten: \"Wir sind sonst alle des Todes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Da nahm das Volk seinen Brotteig, bevor er noch durchsäuert war, und seine Backschüsseln, in seine Mäntel gewickelt, auf die Schulter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Die Israeliten aber hatten nach Mosis Worten getan, und so erbaten sie sich von den Ägyptern Silber- und Goldschmuck und Kleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Der Herr aber hatte die Ägypter dem Volke günstig gestimmt. Und er ließ sie bitten, und sie gewannen sich die Ägypter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Die Israeliten brachen von Ramses auf, nach Sukkot zu, ungefähr 600.000 Fußgänger, ohne Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Auch viel Mischvolk zog mit ihnen, dazu Schafe und Rinder, eine mächtig große Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Sie buken ungesäuerte Brotkuchen aus dem Teige, den sie aus Ägypten mitnahmen; denn er war nicht gesäuert. Sie wurden ja von den Ägyptern verjagt. So konnten sie sich nicht aufhalten und keine Zehrung bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Der Israeliten Bleiben in Ägypten betrug 430 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Nach Ablauf der 430 Jahre geschah es, daß genau am selben Tage alle Scharen des Herrn aus Ägypten zogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Eine durchwachte Nacht war das für den Herrn, als er sie aus dem Land Ägypten führte. Dies ist die Nacht, da alle Israeliten zu Ehren des Herrn in jedem Geschlecht Nachtwachen halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und der Herr sprach zu Moses und Aaron: \"Das ist die Passahordnung: Kein Sohn der Fremde darf mitessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Aber jeder um Geld gekaufte Sklave darf mitessen, wenn du ihn beschnitten hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Beisaß und Mietling dürfen nicht mitessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Im Hause allein soll es gegessen werden. Aus dem Hause darfst du nichts vom Fleisch auf die Straße bringen. Auch kein Bein dürft ihr daran abbrechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israels soll es so halten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Ist ein Gast bei dir und will dem Herrn Passah feiern, so muß alles Männliche bei ihm beschnitten sein. Dann erhält er das Vorrecht, es zu feiern. Er sei dann wie ein Sproß des Landes! Kein Unbeschnittener aber darf davon essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein gleich Gesetz gilt für den Eingeborenen wie für den Gast, der bei euch weilt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Da taten alle Israeliten so. Wie der Herr dem Moses und Aaron befohlen, so taten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'An eben jenem Tage führte der Herr die Israeliten aus dem Ägypterland, nach ihren Scharen geordnet, heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Da sprach der Herr zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '\"Weihe mir alles Erstgeborene! Was bei den Israeliten den Mutterschoß durchbricht, ist mein, Mensch und Vieh.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Und Moses sprach zum Volke: \"Feiert zum Gedächtnis diesen Tag, da ihr aus Ägypten, aus dem Sklavenhause, gezogen seid! Mit starker Hand hat euch der Herr von dannen geführt. Also werde nichts Gesäuertes gegessen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute ziehet aus, am Neumond des Abib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Bringt dich der Herr in das Land der Kanaaniter, Chittiter, Amoriter, Chiwiter und Jebusiter, er, der einst deinen Vätern zugeschworen, ein Land, von Milch und Honig fließend, dir zu geben, dann übe diesen Brauch an diesem Neumond!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage sollst du ungesäuertes Brot essen! Am siebten Tage aber sei ein Fest des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Ungesäuertes Brot werde die sieben Tage gegessen! Nichts Gesäuertes sei bei dir zu sehen! Kein Sauerteig sei bei dir in deinem ganzen Ortsgebiete zu sehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Aber deinem Sohne vermelde an diesem Tage also: \'Um dessentwillen, was der Herr mir getan beim Auszug aus Ägypten, geschieht dies.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es sei dir zum Zeichen an der Hand und zum Merkmal zwischen den Augen, damit in deinem Munde sei die Lehre über den Herrn, daß dich der Herr mit starker Hand aus Ägypten geführt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Und achte diese Satzung zu ihrer Zeit, Jahr für Jahr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Bringt dich der Herr ins Kanaaniterland, wie er dir zugeschworen und deinen Vätern, und gibt er es dir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'dann tritt dem Herrn alles ab, was den Mutterschoß durchbricht! Jeder Erstlingswurf des Viehes, das du hast, falls er männlich ist, gehört dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Doch jeden Erstlingswurf des Esels sollst du mit einem Schafe auslösen und willst du nicht, dann zerbrich ihm das Genick! Bei deinen Kindern aber mußt du jede männliche Erstgeburt auslösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und fragt dich dein Sohn einmal: \'Was ist das?\' dann sprich zu ihm: \'Mit starker Hand hat uns der Herr aus Ägypten geführt, aus dem Frönerhause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Als Pharao sich weigerte, uns freizulassen, tötete der Herr im Lande Ägypten jede Erstgeburt, vom Erstgeborenen des Menschen bis zum Erstlingswurf des Viehs. Darum opfere ich dem Herrn jeden männlichen Erstlingswurf und löse jeden Erstgeborenen meiner Söhne aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und dir sei es zum Zeichen an der Hand und zur Marke zwischen den Augen, daß uns der Herr mit starker Hand aus Ägypten geführt hat!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Als Pharao das Volk entließ, führte es Gott nicht den Weg nach dem Philisterland, der doch der nächste war. Denn Gott sprach: \"Daß es nicht das Volk gereue, wenn es Kämpfe sähe, und dann nach Ägypten wieder wollte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'So ließ Gott das Volk auf dem Wege zur Wüste am Schilfmeer einschwenken. Die Israeliten aber zogen geordnet aus dem Ägypterland fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Moses nahm Josephs Gebeine mit sich. Denn dieser hatte die Israeliten eidlich beschworen: \"Bedenkt euch einstens Gott, dann nehmt meine Gebeine mit euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Und sie zogen von Sukkot ab und lagerten sich in Etam am Rand der Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Der Herr aber zog vor ihnen einher, des Tags in einer Wolkensäule, sie den Weg zu leiten, und des Nachts in einer Feuersäule, ihnen zu leuchten, so daß sie Tag und Nacht wandern konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nicht wich vor dem Volke die Wolkensäule bei Tag und die Feuersäule nicht bei Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '\"Befiehl den Söhnen Israels, daß sie umkehren und sich vor Pihachirot lagern, zwischen Migdol und dem Meere vor Baalsephon. Ihm gegenüber sollt ihr am Meere lagern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Dann sagt Pharao von den Israeliten: \'Verirrt haben sie sich im Land. Die Wüste hält sie umschlossen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Und ich verhärte Pharaos Herz, daß er sie verfolge. So räche ich mich an Pharao und all seiner Heeresmacht. Die Ägypter sollen dann wissen, daß ich der Herr bin.\" Und sie taten so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Da ward es Ägyptens König klar, daß das Volk entwichen sei. Und Pharaos wie seiner Diener Herz ward anders gegen das Volk, und sie sprachen: \"Was haben wir da gemacht, daß wir Israel aus unserem Dienst entlassen haben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und er schirrte seinen Wagen und nahm sein Volk mit sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Sechshundert erlesene Wagen nahm er mit und was sonst an Wagen in Ägypten war, auf ihnen allen Streiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Und der Herr verhärtete Pharaos, des Ägypterkönigs, Herz, und so verfolgte er die Israeliten. Die Israeliten aber waren in dichter Schar ausgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'So setzten ihnen die Ägypter nach und erreichten sie in dem Lager am Meer, mit allen Rossen der Wagen Pharaos, mit seinen Reitern und dem übrigen Heere, bei Pihachirot vor Baalsephon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Wie nun Pharao nähergekommen war, erhoben die Israeliten die Augen. Da waren ihnen die Ägypter nachgezogen, und so erschraken sie heftig. Da schrien die Israeliten zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Und sie sprachen zu Moses: \"Fehlte es an Gräbern in Ägypten, daß du uns zum Sterben in der Wüste mitgenommen hast? Was hast du uns da getan, uns aus Ägypten zu führen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Ist es nicht das gewesen, was wir zu dir in Ägypten gesagt: \'Laß uns in Ruhe! Wir wollen den Ägyptern dienen.\' Ja, besser wäre es für uns, den Ägyptern zu dienen, als in der Wüste zu sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Da sprach Moses zum Volke: \"Fürchtet euch nicht! Haltet stand! Dann erlebt ihr des Herrn Hilfe, die er euch heute schaffen wird. Denn so, wie ihr heute die Ägypter seht, seht ihr sie in alle Ewigkeit nicht wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Der Herr wird für euch streiten, und ihr dürft ruhig zusehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Und der Herr sprach zu Moses: \"Was schreist du zu mir? Heiße die Söhne Israels aufbrechen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber heb deinen Stab empor, streck die Hand übers Meer und spalte es! Mitten durchs Meer sollen die Israeliten auf dem Trockenen ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ich aber verhärte der Ägypter Sinn. Sie sollen ihnen nachziehen. Ich räche mich so an Pharao und seiner ganzen Kriegermacht, an seinen Wagen und Reitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Die Ägypter sollen dann erkennen, daß ich der Herr bin, wenn ich mich räche an Pharao und seinen Wagen und Reitern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Gottes Engel aber, der vor Israels Heer einherzog, erhob sich und trat hinter sie. Auch die Wolkensäule vor ihnen zog weg und stand hinter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'So kam sie zwischen das ägyptische und das israelitische Lager. Da war nun die Wolke und die Finsternis da, und sie vermehrte die Nacht, so daß keines dem anderen während der ganzen Nacht zu nahe kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Dann streckte Moses seine Hand über das Meer. Und der Herr trieb das Meer zurück durch einen starken Ostwind während der ganzen Nacht und machte das Meer zum Sandgrund. Und das Wasser ward geteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Die Israeliten gingen nun mitten durch das Meer im Trockenen. Und die Wasser standen als Mauer zu ihrer Rechten und Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Aber die Ägypter setzten nach und gingen hinter ihnen mit allen Rossen Pharaos, seinen Wagen und Reitern, mitten in das Meer hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'In der Morgenwache geschah es; da neigte sich der Herr in der Feuer- und Wolkensäule über den Zug der Ägypter und verwirrte den ägyptischen Zug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Er hemmte ihre Wagenräder und ließ sie nur mit Beschwer vorwärts kommen. Da sprach Ägypten: \"Fliehen will ich vor Israel.\" Denn der Herr stritt für sie gegen Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Da sprach der Herr zu Moses: \"Streck deine Hand über das Meer! Zurückfluten sollen die Wasser über die Ägypter, ihre Wagen und Reiter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Da streckte Moses seine Hand über das Meer. Und das Meer flutete um die Morgenwende zu seinem Boden zurück, indes die Ägypter ihm entgegenflohen. So trieb der Herr die Ägypter mitten in das Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Zurückfluteten da die Wasser und bedeckten die Wagen und Reiter in Pharaos ganzem Heere, das ihnen nachgezogen war ins Meer. Nicht einer von ihnen blieb übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Die Israeliten aber waren auf dem Trockenen mitten durch das Meer gezogen, und die Wasser standen als Mauer zu ihrer Rechten und Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'So befreite der Herr an jenem Tage Israel aus der Hand Ägyptens, und Israel sah die Ägypter tot am Ufer des Meeres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Da sah Israel die Großtat, die der Herr an Ägypten getan. Und das Volk fürchtete den Herrn und vertraute dem Herrn und seinem Diener Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Damals sang Moses mit den Israeliten dieses Lied dem Herrn. Sie sprachen also: \"Dem Herrn will ich lobsingen. Er hat gesiegt, ins Meer gestürzt das Roß und seinen Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Dem Herrn mein Lobgesang! Zur Rettung ward er mir. So ist mein Gott; ihn preise ich. Ich rühme meines Vaters Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Der Herr ein Kriegsheld, sein Name Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen Pharaos und seine Mannen hat er ins Meer geworfen. Ins Schilfmeer tauchten die besten seiner Streiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Abgründe deckten sie; sie fuhren in die Strudel wie ein Stein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Herr, Deine Rechte, an Kraft so herrlich, Herr, Deine Rechte zerschmettert Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Mit Deines Zornes Fülle zerschlägst Du Deine Gegner; ausschickst Du Deinen Grimm, er frißt sie wie das Stroh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Durch Deines Zornes Hauch schwoll an das Wasser. Wallgleich die Fluten standen, und Abgründe gerannen in Meeres Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Es sprach der Feind: \'Ich jage nach und hole ein und teile Raub. An ihnen meine Gier sich letze! Mein Schwert zück ich. Sie tilge meine Hand!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du bliesest nur mit Deinem Hauche; schon bedeckte sie das Meer. Sie wirbelten wie Blei in die gewaltigen Gewässer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer gleicht Dir bei den Göttern, Herr? Wer gleicht Dir, Du Erhabener im Heiligtum, Furchtbarer, Schrecklicher, Du Wunderwirker?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du streckst die Rechte aus, und sie verschluckt die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du lenkst mit Deiner Huld das Volk, das Du erlöst. Du leitest es in Deiner Kraft zu Deiner heiligen Wohnstatt hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Die Völker hören\'s, zittern, und Angst packt die Bewohner Philistäas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Zusammenschrecken Edoms Fürsten, und Moabs Edelinge faßt Erbeben, und Kanaans Insassen alle zagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Entsetzen, Schrecken stürzt auf sie; ob Deines Armes Größe erstarren sie zu Stein, bis daß hindurchzieht, Herr, Dein Volk, bis daß hindurchzieht dies Dein Volk, das Du erkauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Herbei bringst Du sie selbst und pflanzest sie an jener Stätte ein, die Du zu Deinem Sitze, Herr, bereitet, im Heiligtum, mein Herr, das Deine Hände selbst erstellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Der Herr ist König immerdar und ewig.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Pharaos Rosse waren ja samt seinen Wagen und Reitern ins Meer geraten, und der Herr brachte über sie des Meeres Gewässer zurück. Die Israeliten aber waren im Trockenen mitten durchs Meer gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Da nahm die Prophetin Mirjam, Aarons Schwester, die Pauke zur Hand, und alle Frauen folgten ihr mit Pauken und Reigentänzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Da sang ihnen Mirjam zu: \"Lobsingt dem Herrn! Er ist so hoch und hehr, der Rosse und Reiter gestürzt ins Meer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Moses ließ nun Israel vom Schilfmeer aufbrechen. Sie zogen in die Wüste Sur hinein. Drei Tage gingen sie durch die Wüste; sie fanden aber kein Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'So kamen sie nach Mara; aber sie konnten in Mara kein Wasser trinken, weil es bitter war; daher hieß es Mara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da murrte das Volk gegen Moses und sprach: \"Was sollen wir trinken?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Er aber rief zum Herrn. Und der Herr wies ihn auf einen Baum. Davon warf er ins Wasser, und das Wasser ward süß. Dort gab er ihm Gesetz und Recht, und dort prüfte er es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Er sprach: \"Hörst du gehorsam auf die Stimme des Herrn, deines Gottes, und tust, was recht ist vor ihm, dann horchst du auf seine Weisungen und hältst all seine Satzungen, dann lege ich dir keines der Leiden auf, die ich Ägypten auferlegt. Ich, der Herr, bin dein Arzt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Und sie kamen nach Elim. Dort waren zwölf Quellen und siebzig Palmen. Und sie lagerten dort am Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Von Elim brachen sie auf und kamen, die ganze Gemeinschaft Israels, in die Wüste Sin zwischen Elim und Sinai am fünfzehnten Tage des zweiten Monats nach ihrem Auszuge aus Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Da murrten sie, die ganze israelitische Gemeinschaft, gegen Moses und Aaron wegen der Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Und die Israeliten sprachen zu ihm: \"Wären wir doch im Ägypterland durch des Herrn Hand gestorben! Da saßen wir beim Fleischtopf und aßen uns satt an Brot. Ihr habt uns in diese Wüste geführt, diese ganze Gemeinde durch Hunger zu töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach der Herr zu Moses: \"Ich lasse euch nun Brot vom Himmel regnen. Das Volk gehe hinaus! Doch lese es jeden Tag nur den Tagesbedarf! Damit prüfe ich es, ob es meiner Weisung folgt oder nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Messen sie dann am sechsten Tage, was sie einbringen, so wird es das Doppelte sein von dem, was sie tagtäglich lesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Da sprachen Moses und Aaron zu allen Israeliten: \"Am Abend erkennt ihr, daß der Herr euch aus Ägypterland geführt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Und am Morgen schaut ihr des Herrn Majestät, hat er doch euer Gemurr gegen den Herrn vernommen. Was sind wir, daß ihr gegen uns murrt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Und Moses sprach: \"Der Herr gibt euch am Abend Fleisch zu essen und zur Genüge Brot am Morgen, hat doch der Herr euer Gemurr wider ihn vernommen. Was sind wir? Nicht gegen uns geht euer Gemurr, sondern gegen den Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Und Moses sprach zu Aaron: \"Sag der ganzen Gemeinschaft der Söhne Israels: \'Tritt vor den Herrn! Er hat euer Gemurr vernommen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Als Aaron dies der ganzen Gemeinschaft der Israeliten verkündigte und sie sich der Wüste zuwandten, da erschien des Herrn Majestät in der Wolke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '\"Der Israeliten Gemurr habe ich vernommen. Sag ihnen dies: Ihr werdet Fleisch am Abend essen und morgen früh euch am Brote sättigen. Da möget ihr erkennen, daß ich der Herr, euer Gott, bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und Abend war\'s, da zog ein Wachtelschwarm heran und bedeckte das Lager. Und am Morgen lag eine Tauschicht rings um das Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Dann stieg die Tauschicht auf, und auf der Wüstenfläche lag etwas Dünnes, Schuppiges, fein wie der Reif auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Die Israeliten sahen es und sprachen zueinander: \"Was ist das?\", denn sie wußten nicht, was es war. Da sprach Moses zu ihnen: \"Dies ist das Brot, das euch der Herr zu essen gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Das ist es, was der Herr mir geboten: \'Leset davon auf, jeder nach Bedarf. Je ein Maß auf den Kopf nach eurer Seelenzahl hole jeglicher für die in seinem Zelt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Israeliten taten so. Sie lasen auf, der eine viel, der andere wenig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Da maßen sie mit dem Maß. Wer viel geholt, hatte nicht mehr, wer wenig geholt, nicht weniger gehabt. Jeder hatte für seinen Bedarf gelesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Und Moses sprach zu ihnen: \"Niemand hebe davon bis zum Morgen auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie hörten nicht auf Moses; sondern einige Männer hoben davon bis zum Morgen auf. Da ward es voller Würmer und roch übel. Moses aber ward auf sie zornig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'So lasen sie es Morgen für Morgen auf, jeder nach seinem Bedarf. Wenn aber die Sonne heiß brannte, schmolz es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Aber am sechsten Tage lasen sie doppelte Speise, zwei Maß für einen. Da kamen alle Fürsten der Gemeinschaft und meldeten es Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Er sprach zu ihnen: \"Dies ist es, was der Herr gemeint: Der heilige Ruhetag des Herrn ist morgen. Was ihr backen wollt, backet jetzt! Kochet jetzt, was ihr kochen wollt! Was übrigbleibt, verwahrt bis zum Morgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie legten es bis zum anderen Morgen zurück, wie Moses befohlen. Nichts roch übel, und kein Wurm war darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Und Moses sprach: \"Eßt es heute! Denn heute ist ein Ruhetag des Herrn. Ihr findet nichts auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage könnt ihr es sammeln. Aber am siebten Tage ist Sabbat; an dem gibt es nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Doch am siebten Tage gingen vom Volke etliche zum Lesen hinaus; sie fanden aber nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sprach der Herr zu Moses: \"Wie lange wollt ihr meine Vorschriften und Gebote nicht halten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Seht! Der Herr hat euch den Sabbat gegeben. Darum gibt er euch am sechsten Tag Speise für zwei Tage. So bleibe jeder daheim! Am siebten Tage aber gehe niemand von seinem Platz!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'So ruhte am siebten Tage das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Das Haus Israel aber nannte es Manna. Es war wie Koriandersamen, weißlich, und sein Geschmack wie Honigkuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Moses sprach: \"Das ist es, was der Herr geboten: \'Füllt ein Maß davon zum Verwahr für eure Geschlechter, damit sie sehen das Brot, mit dem ich in der Wüste euch gespeist, als ich euch aus Ägypterland geführt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Und Moses sprach zu Aaron: \"Nimm einen Krug und tu ein ganzes Maß Manna hinein und lege ihn nieder vor dem Herrn zum Verwahr für eure Geschlechter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Und wie der Herr dem Moses befohlen, so legte ihn Aaron vor der Gesetzeslade nieder zum Verwahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Die Israeliten aber aßen das Manna vierzig Jahre, bis sie in bewohntes Land kamen. Das Manna aßen sie, bis sie an die Grenze des Landes kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ein Maß aber ist das Zehntteil eines Scheffels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Sie nun, die ganze Gemeinschaft der Israeliten, zogen von der Wüste Sin weiter, in Tagesmärschen nach des Herrn Befehl. Sie lagerten zu Raphidim. Da war aber kein Trinkwasser für das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Das Volk aber haderte mit Moses und sprach: \"Gebt uns Wasser zum Trinken!\" Und Moses sprach zu ihnen: \"Weshalb zankt ihr mit mir? Was prüft ihr den Herrn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Das Volk aber dürstete dort nach Wasser. Und so murrte das Volk gegen Moses und sprach: \"Wozu hast du uns aus Ägypten geführt? Mich, meine Kinder und mein Vieh durch Durst zu töten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da rief Moses zum Herrn und sprach: \"Was fange ich mit diesem Volk noch an? Nur wenig, und sie steinigen mich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Der Herr sprach zu Moses: \"Übergehe das Volk und nimm dir von den Ältesten in Israel nur ein paar mit! Auch deinen Stab, mit dem du den Nil geschlagen, nimm mit und geh!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Siehe! Ich stehe dort vor dir auf dem Felsen am Horeb. Schlägst du an den Felsen, so fließt Wasser heraus, und das Volk kann trinken.\" Und Moses tat so vor den Augen der Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Und er nannte die Stätte Massa und Meriba, weil die Israeliten gezankt und den Herrn versucht hatten mit den Worten: \"Ist der Herr unter uns oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Da kam Amalek und wollte mit Israel zu Raphidim kämpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Moses sprach zu Josue: \"Wähle uns Männer! Alsdann ziehe aus und kämpfe mit Amalek! Ich aber stelle mich morgen auf des Hügels Spitze, den Gottesstab in der Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josue tat, wie ihm Moses gesagt, bei dem Kampfe mit Amalek. Moses aber, Aaron und Hur waren auf den Gipfel des Hügels gestiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Wie nun Moses seinen Arm erhob, siegte Israel, und wie er seinen Arm sinken ließ, siegte Amalek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Aber Mosis Arme wurden steif. So nahmen sie einen Stein und legten ihm diesen unter, und er setzte sich darauf. Aaron aber und Hur stützten seine Arme, der eine hier, der andere dort. So blieben seine Arme fest bis zum Sonnenuntergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'So überwand Josue Amalek und sein Volk mit des Schwertes Schärfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Da sprach der Herr zu Moses: \"Schreibe dies zum Gedächtnis ins Buch und schärfe es Josue ein: \'Wegwischen will ich Amaleks Gedenken unterm Himmel!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Moses erbaute einen Altar und nannte ihn \"Mein Banner ist der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Er');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Midians Priester Jetro aber, Mosis Schwiegervater, hörte alles, was Gott an Moses und seinem Volk Israel gewirkt, daß der Herr Israel aus Ägypten geführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Da nahm Jetro, Mosis Schwiegervater, die Sippora, Mosis Weib, das er heimgeschickt hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'und ihre beiden Söhne. Der eine hieß Gersom, weil er gesagt: \"Ich ward in fremdem Lande Fremdling.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Der andere hieß: Eliezer. Denn: \"Meines Vaters Gott war meine Hilfe, und er befreite mich vor Pharaos Schwert\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'So kam Mosis Schwiegervater Jetro mit seinen Söhnen und seinem Weibe zu Moses in die Wüste; er aber lagerte am Gottesberge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Da ließ er Moses sagen: \"Ich, Jetro, dein Schwiegervater, komme zu dir mit deinem Weibe und ihren beiden Söhnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging Moses seinem Schwiegervater entgegen, neigte sich und küßte ihn. Dann fragten sie einander nach dem Befinden. Hierauf gingen sie in das Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Da erzählte Moses seinem Schwiegervater alles, was der Herr an Pharao und Ägypten getan um Israels willen, alles Ungemach, das sie unterwegs getroffen, und wie sie der Herr gerettet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Und Jetro freute sich all des Guten, das der Herr an Israel getan, als er es aus Ägyptens Gewalt erlöst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jetro sprach: \"Gepriesen sei der Herr, der euch befreit aus Ägyptens und Pharaos Hand und der das Volk aus Ägyptens Hand befreit hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun sehe ich, daß der Herr größer ist als alle Götter; denn merkwürdig ist es, wie man sie verspottet hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Dann weihte Mosis Schwiegervater Jetro Gott Brand- und Schlachtopfer. Und Aaron kam mit allen Ältesten Israels, mit Mosis Schwiegervater ein Mahl vor Gott zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Am anderen Morgen setzte sich Moses, das Volk zu richten, und das Volk stand vor Moses vom Morgen bis zum Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Als Mosis Schwiegervater sah, wieviel er dem Volke tat, sprach er: \"Was ist das, wie du es mit dem Volke machst? Warum sitzest du allein, und alles Volk steht vom Morgen bis zum Abend vor dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Da sprach Moses zu seinem Schwiegervater: \"Das Volk kommt zu mir, Gott zu fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Haben sie eine Rechtssache, so kommt sie vor mich, und ich richte zwischen ihnen und künde Gottes Rechtssprüche und seine Weisungen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sprach Mosis Schwiegervater zu ihm: \"Nicht gut ist\'s, wie du es treibst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du reibst dich auf und das Volk bei dir. Es ist zu schwer für dich. Du kannst es allein nicht machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Hör auf mich! Ich rate dir, und Gott sei mit dir! Vertritt du das Volk gegenüber Gott! Und bring du die Sachen vor Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Erkläre ihnen die Gesetze und Weisungen! Zeig ihnen den Weg, den sie gehen, und das Werk, das sie tun sollen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Aber du selbst sollst dir aus dem ganzen Volke Männer ersehen, tüchtig, gottesfürchtig, Männer, vertrauenswürdig, vorteilhassend! Setze sie über sie als Führer von Tausendschaften, Hundertschaften, Fünfzigschaften und Zehnschaften!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Sie sollen jederzeit das Volk richten! Alle wichtigen Sachen sollen sie vor dich bringen! Die geringeren aber sollen sie alle selber entscheiden! Entlaste dich und laß sie mit dir tragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Tust du so, dann kannst du bestehen bei dem, was Gott dir befiehlt. Und dies ganze Volk geht befriedigt heim.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Und Moses hörte auf seines Schwiegervaters Rat und tat ganz so, wie er gesagt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Moses wählte aus ganz Israel tüchtige Männer aus und stellte sie an die Spitze des Volkes, als Führer von Tausendschaften, Hundertschaften, Fünfzigschaften und Zehnschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Sie sprachen dem Volke jederzeit Recht. Die schwierigen Sachen aber brachten sie vor Moses; die geringfügigen entschieden sie alle selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Dann ließ Moses seinen Schwiegervater heimziehen, und er ging heim in sein Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Am dritten Neumond nach dem Auszug der Israeliten aus Ägypten, genau auf den Tag, waren sie in die Wüste Sinai gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sie brachen nämlich von Raphidim auf und kamen so in die Wüste Sinai. Und sie lagerten sich in der Wüste. Und Israel lagerte dort gegenüber dem Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Moses aber stieg zu Gott hinauf. Da rief ihm der Herr vom Berge zu: \"Sprich also zu dem Jakobshaus und kündige den Söhnen Israels:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '\'Ihr selber habt gesehen, was ich an Ägypten getan und wie ich euch auf Adlerflügeln trug und euch zu mir herbrachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Nun sollt ihr auf meine Stimme hören: Haltet ihr meinen Bund, dann seid ihr mir aus allen Völkern ein Sondergut. Denn mein ist die ganze Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Ihr aber sollt mir sein ein Königreich von Priestern, ein heilig Volk.\' Das sind die Worte, die du den Israeliten sagen sollst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Da kam Moses, berief des Volkes Ältesten und trug ihnen alle diese Worte vor, die der Herr ihm aufgetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Und das ganze Volk erwiderte einhellig und sprach: \"Alles, was der Herr befiehlt, wollen wir tun.\" Und Moses überbrachte die Worte des Volkes dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Da sprach der Herr zu Moses: \"Ich komme zu dir in dichter Wolke, damit das Volk höre, wenn ich mit dir rede, und daß sie für immer auch dir vertrauen.\" Moses aber berichtete die Worte des Volkes dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Und der Herr sprach zu Moses: \"Geh zum Volk! Bereite es vor, heute und morgen! Sie sollen saubere Kleider tragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Für übermorgen seien sie bereit! Denn übermorgen fährt der Herr vor des ganzen Volkes Augen nieder auf den Sinaiberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Das Volk aber schranke du ringsum ein und sprich: \'Hütet euch, auf den Berg zu steigen oder nur an seinen Fuß zu rühren! Wer den Berg berührt, erleidet Todesstrafe.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nicht soll eine Hand an ihn rühren! Gesteinigt oder durchstochen werde, ob Vieh oder Mensch! Nicht dürfen sie am Leben bleiben. Erst wenn das Lärmhorn tönt, dürfen sie den Berg hinaufsteigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Da stieg Moses von dem Berge zum Volke hinab und bereitete das Volk vor. Sie legten saubere Gewänder an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Dann sprach er zum Volke: \"Für übermorgen haltet euch bereit! Berührt kein Weib!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Als es am dritten Tage Morgen ward, brachen Donner los und Blitze. Eine schwere Wolke hing auf dem Berge, und mächtiger Hörnerschall ertönte. Da bebte alles Volk im Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Dann führte Moses das Volk Gott entgegen aus dem Lager, und am Fuße des Berges stellte es sich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Der ganze Berg Sinai aber rauchte, weil der Herr auf ihn im Feuer niedergefahren war. Und sein Rauch stieg auf, wie des Schmelzofens Rauch. Und der ganze Berg erbebte heftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Der Hörnerschall aber ward immer stärker. Und Moses redete; die Gottheit aber antwortete ihm nur in einem Schall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Der Herr fuhr also auf den Berg Sinai, auf den Gipfel des Berges, nieder. Da berief der Herr den Moses auf den Gipfel des Berges, und Moses stieg hinan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Und der Herr sprach zu Moses: \"Steig hinab! Schärfe dem Volke ein, daß sie nicht vorwärtsdringen, den Herrn zu schauen! Sonst würden viele aus ihnen fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Die Priester selbst, die sonst dem Herrn nahen dürfen, müssen stehenbleiben, daß der Herr nicht gegen sie losfahre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Da sprach Moses zum Herrn: \"Das Volk kann nicht den Sinaiberg besteigen; du hast ja selbst uns eingeschärft: \'Umschranke den Berg! Umhege ihn!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Da sprach der Herr zu ihm: \"Geh hinab und komm mit Aaron wieder! Aber die Priester und das Volk dürfen nicht stürmisch zum Herrn heraufsteigen, daß er nicht gegen sie losfahre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Da stieg Moses zum Volke hinab und sprach mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Und Gott redete all diese Worte; er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '\"Ich bin der Herr, dein Gott, der dich aus dem Ägypterland, aus dem Frönerhaus geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keinen anderen Gott gleich mir haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst kein Bild dir machen, noch eine Abform dessen, was im Himmel droben ist oder auf Erden unten oder in dem unterirdischen Gewässer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du sollst dich nicht vor solchen niederwerfen und nimmer sie verehren! Ein eifersüchtiger Gott bin ich, der Herr, dein Gott, der da die Schuld der Väter heimsucht an den Kindern, Enkeln und Urenkeln derer, die mich hassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'doch Huld erweist den Tausenden von denen, die mich lieben und die meine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst nicht des Herrn, deines Gottes, Namen eitel nennen! Der Herr läßt den nicht ungestraft, der seinen Namen eitel nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke, den Sabbattag zu heiligen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und all dein Werk verrichten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Ein Ruhetag, dem Herren, deinem Gott, zu Ehren, ist jedoch der siebte Tag. An ihm verrichte kein Geschäft, nicht du und nicht dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, und nicht dein Vieh und nicht dein Gast in deinen Toren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat der Herr den Himmel und die Erde, das Meer und alles, was darin, gemacht. Am siebten Tage aber ruhte er. Deswegen hat der Herr den Ruhetag gesegnet, und also heiligte er ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Ehre deinen Vater und deine Mutter, damit du lange lebest auf dem Erdboden, den dir der Herr, dein Gott, verleiht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht morden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst nicht gegen deinen Nächsten falsches Zeugnis ablegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst nicht deines Nächsten Haus begehren! Du sollst nicht deines Nächsten Weib begehren, noch seinen Knecht, noch seine Magd, und nicht sein Rind, noch seinen Esel, nichts, was deines Nächsten ist!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Und alles Volk ward inne der Donnerschläge, der Blitze, des Hörnerschalls und des rauchenden Berges. Und das Volk sah es, lief zurück und stand fern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Dann sprachen sie zu Moses: \"Rede du mit uns! Dann wollen wir zuhören. Aber nicht rede Gott mit uns! Sonst sterben wir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Da sprach Moses zum Volke: \"Habt keine Furcht! Die Gottheit ist gekommen, euch zu prüfen und damit die Furcht vor ihr in euch bleibe, auf daß ihr nicht sündiget.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'So stand das Volk fern. Moses aber trat zu dem Wolkendunkel, in dem Gott war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Da sprach der Herr zu Moses: \"So sollst du sprechen zu den Israeliten: \'Ihr selber habt gesehen, daß ich mit euch vom Himmel aus geredet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ihr sollt mich nicht als einen Gott aus Silber oder Gold machen. Das dürft ihr euch nicht machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Du sollst aus Erde mir einen Altar anfertigen und darauf deine Brand- und Mahlopfer und deine Schafe und Rinder opfern. Wo immer meinen Namen ich ausspreche, da komme ich zu dir, und alsdann segne ich dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Machst du mir aber aus Steinen einen Altar, dann sollst du ihn nicht mit behauenen Steinen bauen! Denn du entweihest sie, schwingst du dein Eisen über sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Und nicht auf Stufen sollst du zu meinem Altar emporsteigen, damit nicht deine Blöße vor ihm offenbar werde!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '\"Dies sind die Rechtssatzungen, die du ihnen vorlegen sollst:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Kaufst du dir einen hebräischen Knecht, so diene er dir sechs Jahre! Im siebten aber gehe er frei und ledig aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Kam er mit seinem Bündel, so gehe er mit seinem Bündel; hatte er ein Weib, so gehe sein Weib mit ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Gab ihm sein Herr ein Weib und gebar sie ihm Söhne oder Töchter, so bleibe das Weib mit seinen Kindern bei seinem Herrn. Er selber aber gehe mit seinem Bündel weg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Erklärt aber der Knecht: \'Ich liebe meinen Herrn, mein Weib und meine Kinder\' und mag nicht frei weggehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'dann bringe ihn sein Herr vor die Gottheit und stelle ihn an die Tür oder den Türpfosten! Und dann steche ihm sein Herr mit seinem Pfriemen durch das Ohr: Und nun sei er für immer sein Knecht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Verkauft jemand seine Tochter als Magd, dann darf sie nicht wie Knechte fortgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Mißfällt sie ihrem Herrn, der sie sich bestimmt hatte, dann lasse er sie loskaufen! Sie fremdem Volk zu verkaufen, hat er keine Macht, wenn er sie gehen läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Bestimmt er sie aber seinem Sohne, dann tue er ihr nach der freien Mädchen Recht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nimmt er sich noch eine andere, dann schmälere er ihr nicht Fleisch, Kost, Gewand und Umarmung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Tut er ihr von diesen dreien keines, dann gehe sie ohne Entgelt, umsonst weg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen anderen totschlägt, soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er aber nicht aufgelauert, sondern Gott hat es seiner Hand widerfahren lassen, dann bestimme ich dir eine Stätte, wohin er fliehen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Wenn aber jemand wider den Genossen brütet, ihn mit List zu töten, dann hole ihn von meinem Altar weg, daß er getötet werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater oder seine Mutter schlägt, soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Menschen raubt, er habe ihn verkauft oder er finde sich noch in seiner Hand, soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Wer seinem Vater oder seiner Mutter flucht, soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Wenn Männer streiten und einer schlägt den anderen so mit einem Steine oder mit der Faust, daß er zwar nicht stirbt, aber aufs Lager fällt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'so bleibe der Schläger frei, wenn er wieder aufsteht und im Freien an seiner Krücke umhergeht! Nur sein Feiernmüssen ersetze er und lasse ihn ausheilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Wenn jemand seinen Knecht oder seine Magd mit dem Stocke schlägt, und es stirbt eines unter seiner Hand, so werde es gesühnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Übersteht es aber noch einen oder zwei Tage, dann werde es nicht gesühnt; denn um sein eigen Geld geht es!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn sich Männer raufen und stoßen ein schwangeres Weib, so daß es eine Fehlgeburt gibt, aber kein weiterer Schaden entsteht, so werde der Schuldige mit soviel bestraft, wie ihm der Gatte des Weibes auflegt! Er gebe es als Buße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Entsteht jedoch ein Schaden, dann wende an: Leben um Leben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Beule um Beule!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Schlägt jemand seinem Knecht oder seiner Magd ins Auge und zerstört es, so lasse er ihn für sein Auge frei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Schlägt er seinem Knecht oder seiner Magd einen Zahn aus, so lasse er ihn für seinen Zahn frei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Und stößt ein Rind einen Mann oder ein Weib tot, so werde das Rind gesteinigt! Sein Fleisch werde nicht gegessen. Des Rindes Besitzer aber sei straffrei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'War aber das Rind lange zuvor stößig und war sein Besitzer schon verwarnt, er aber hütete es nicht und nun tötet es einen Mann oder ein Weib, so werde das Rind gesteinigt, und auch sein Besitzer soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wird ihm aber ein Sühnegeld auferlegt, so zahle er für sein Leben soviel Lösung, wie man ihm auflegt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Gleichviel, ob es einen Sohn oder eine Tochter stößt, werde ihm dann nach diesem Recht getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stößt aber das Rind einen Knecht oder eine Magd, dann zahle er ihrem Herrn dreißig Silberlinge! Das Rind aber werde gesteinigt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Läßt jemand einen Brunnen offen oder gräbt er einen Brunnen und überdeckt ihn nicht und fällt ein Rind oder Esel hinein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'dann zahle der Brunnenbesitzer! Den Geldwert erstatte er seinem Besitzer; das Tote aber sei sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Rind des anderen Rind totstößt, dann sollen sie das lebende Rind verkaufen und seinen Erlös teilen, und auch das tote sollen sie teilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ist es aber bekannt gewesen, daß dieses Rind schon lange stößig war und sein Eigentümer behütete es nicht, so ersetze er das Rind durch ein anderes! Das tote aber sei sein! Wenn jemand ein Rind oder ein Schaf stiehlt und dann es schlachtet oder es verkauft, dann gebe er für das Rind fünf und für das Schaf vier andere!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wird ein Dieb beim Einbruch ertappt und dann totgeschlagen, so entsteht seinetwegen keine Blutschuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Hat dabei aber schon die Sonne geschienen, dann ist seinethalben Blutschuld. Ersatz muß der Dieb leisten. Hat er nichts, dann werde er für seinen Diebstahl verkauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Wird bei ihm das Gestohlene, Rind, Esel oder Schaf noch lebend gefunden, dann leiste er nur doppelte Buße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Läßt jemand ein Feld oder einen Weinberg abweiden und läßt er das Vieh laufen, daß es ein anderes Feld abweidet, dann gebe er zum Ersatz das Beste von seinem Feld und Weinberg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Wenn Feuer auskommt und Gestrüpp ergreift und ein Getreidehaufen wird dabei verbrannt oder das Korn auf dem Halm oder das Feld, dann ersetze, wer den Brand entzündet hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn jemand seinem Genossen Geld gibt oder Geräte zum Aufheben und dies ist aus dem Hause des Mannes gestohlen worden, dann ersetze der Dieb doppelt, falls er entdeckt wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Wird aber der Dieb nicht entdeckt, dann trete der Hausherr vor die Gottheit, wenn er sich nicht an des anderen Habe vergriffen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Bei Unterschlagung eines Rindes, eines Esels, eines Schafes, eines Mantels, bei allem, was abhanden gekommen und wovon man sagt: \'Das ist es\', komme vor die Gottheit der beiden Sache! Wen Gott schuldig spricht, der ersetze dem anderen doppelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn jemand einem anderen Esel oder Rinder oder Schafe oder sonst ein Tier zu hüten gibt und es stirbt oder wird verstümmelt oder verschleppt und keiner sieht es,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'dann entscheidet zwischen beiden der Schwur beim Herrn, er habe nicht seine Hand an des anderen Habe gelegt. Das nehme der Besitzer an, und jener hat nichts zu ersetzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Ward es aber in seinem Beisein gestohlen, dann ersetze er dem Eigentümer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Und wenn es zerrissen ward und er kann des zerrissenen Tieres Fell vorlegen, dann ersetze er nichts!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wenn aber jemand eins vom anderen entlehnt und es wird verstümmelt oder stirbt, dann ersetze er, wenn sein Besitzer nicht zugegen war!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'War aber der Besitzer da, dann ersetze er nichts! War es gemietet, bekommt er dafür den Mietpreis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Betört jemand eine noch nicht verlobte Jungfrau und wohnt er ihr bei, dann mache er sie durch Morgengabe zum Weib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Weigert sich aber ihr Vater, sie ihm zu geben, so zahle er nach der Brautgabe der Jungfrauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Du sollst nicht eine Verführerin aufziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Wer einem Tier beiwohnt, sterbe des Todes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wer den Göttern opfert, sei im Banne! Einzig und allein dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Einen Fremdling sollst du nicht drücken noch quälen! Auch ihr seid Fremdlinge im Land Ägypten gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Ihr sollt nie Witwen und Waisen bedrücken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Drückst du sie, dann schreit sie zu mir, und ich höre ihr Schreien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Aufflammt mein Zorn, und mit dem Schwerte töt ich euch, und eure Weiber werden Witwen, und Waisen eure Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Leihst du Geld meinem Volk, dem Armen bei dir, sei ihm nie wie ein Wucherer! Zins sollt ihr ihm nicht auferlegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Pfändest du des Genossen Mantel, gib ihn zurück bis zum Sonnenuntergang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Denn er ist seine einzige Hülle, für seine Haut sein Kleid. Worin soll er sich schlafen legen? Schreit er zu mir, dann höre ich darauf. Denn ich bin mitleidsvoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Du sollst Gott nicht lästern. Du sollst keinem Fürsten deines Volkes fluchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Hinterziehen sollst du nicht deine Fülle noch dein Tröpflein! Gib mir deiner Söhne Erstgeborenen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'So sollst du auch mit deinem Rinde und deinem Schafe tun! Bei seiner Mutter bleibe es sieben Tage! Am achten magst du es mir bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Heilige Männer sollt ihr mir sein! Zerrissenes Wildfleisch sollt ihr nicht essen! Den Hunden sollt ihr es vorwerfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst kein Luggerücht annehmen! Reiche nicht die Hand dem Schuldigen, daß du unrecht Zeugnis gäbest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst nicht einer Mehrheit zum Schlechten folgen! Du sollst nicht über einen Streitfall so abstimmen, daß du dich der Mehrheit beugest und das Recht biegest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Den Reichen sollst du nicht in seinem Rechtsstreit beschönigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Triffst du deines Feindes Rind oder Esel verlaufen an, dann sollst du sie ihm zuführen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Und siehst du deines Widersachers Esel unter seiner Last erliegen und bist du fertig mit seinem Absatteln, dann sollst du mit ihm noch rasten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst nicht deines Armen Recht in seinem Rechtsstreit beugen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Fern sollst du dich von lügenhafter Aussage halten! Wer ohne Schuld und im Recht ist, den bringe nicht ums Leben! Ich lasse den Schuldigen nicht ungestraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Du sollst kein Geschenk annehmen! Denn das Geschenk blendet Sehende und verdreht der Gerechten Sache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Du sollst keinen Fremdling bedrücken! Ihr wißt ja selbst, wie es Fremdlingen zumute ist; ihr seid ja selbst Fremdlinge im Ägypterland gewesen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sechs Jahre sollst du dein Land besäen und seine Ernte heimsen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Im siebten aber laß es brach liegen und gib es dann frei, daß deines Volkes Arme essen können! Und was sie übriglassen, soll das Tier des Feldes aufzehren! So sollst du auch mit deinem Weinberge und deinem Ölgarten tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du deine Werke wirken! Am siebten aber sollst du feiern, damit dein Rind und dein Esel ruhe und aufatme das Kind deiner Magd und der Fremdling!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'In allem, was ich euch befehle, sollt ihr euch in acht nehmen! Der falschen Götter Namen sollt ihr nicht anrufen! Er soll aus deinem Munde nicht gehört werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal im Jahr sollst du mir Feste feiern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest der ungesäuerten Brote sollst du halten! Sieben Tage sollst du nur ungesäuertes Brot essen, wie ich dir geboten, zur Zeit des Neumonds im Abib. An ihm bist du aus Ägypten fortgezogen. Mein Antlitz aber soll man nicht gabenleer schauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Und das Fest der Ernte, der Erstlinge deines Ertrages, dessen, womit den Acker du besätest, und am Jahresschluß das Fest der Lese, wenn du vom Felde deinen Ertrag erntest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahre lasse sich alles Männliche bei dir vor dem Herrn, dem Herrn, sehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst nicht meines Opfers Blut mit Gesäuertem zusammen opfern! Nicht soll von meinen Festopfern das Fett bis zum Morgen noch da sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Von deines Ackers Erstlingen den ersten Abhub sollst du zum Hause des Herrn, deines Gottes, bringen! Du sollst kein Böckchen im Fett seiner Mutter braten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Nun sende ich einen Engel vor dir her, dich auf dem Wege zu hüten und dich zur Stätte zu bringen, die ich bestimmt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Nimm dich vor ihm in acht und hör auf seine Stimme! Sei gegen ihn nicht widerspenstig! Er kann euren Frevel nicht ertragen, weil mein Name in ihm ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Hörst du aber gehorsam auf seine Stimme und tust du alles, was ich sage, dann befeinde ich deine Feinde und dränge deine Dränger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Geht mein Engel vor dir her und bringt er dich dann zu den Amoritern und Chittitern, Perizitern, Kanaanitern, Chiwitern und den Jebusitem, die ich ausrotte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'dann sollst du nicht ihre Götter anbeten und ihnen nicht dienen! Auch sollst du keine Abbilder von ihnen machen! Du sollst sie vielmehr niederreißen und zerschmettern ihre Denksteine!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Dient ihr aber dem Herrn, eurem Gott, dann segnet er dein Brot und dein Wasser, und Krankheit halte ich dir ferne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Keine Fehlgebärende und Unfruchtbare wird in deinem Lande sein. Deiner Tage Zahl erfülle ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Und mein Grauen sende ich vor dir her, und dann erschrecke ich alle Völker, zu denen du gelangst, und mache, daß vor dir alle deine Feinde fliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Vor dir her sende ich Hornissen, und sie vertreiben vor dir Chiwiter, Kanaaniter und Chittiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Aber nicht in einem Jahre will ich sie vor dir vertreiben, sonst würde das Land zur Wüste, und die wilden Tiere nähmen zu deinem Schaden überhand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Nach und nach vertreibe ich sie vor dir, bis du zahlreich wirst und dann das Land besetzen kannst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und ich stecke dir die Gebiete vom Schilfmeer bis zum Philistermeer und von der Wüste bis zum Strome ab. Denn ich gebe in eure Hand des Landes Einwohner, daß du sie vor dir vertreibest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du darfst keinen Bund mit ihnen und ihren Göttern schließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Sie dürfen nicht in deinem Lande bleiben, daß sie dich nicht zur Sünde gegen mich verleiten. Denn dientest du ihren Göttern, so würde dir dies zum Falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Zu Moses aber hatte er gesprochen: \"Steig zum Herrn empor, du, Aaron, Nadab und Abihu und siebzig von den Ältesten Israels und betet aus der Ferne an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Moses allein trete zum Herrn! Die anderen dürfen nicht näher treten. Auch das Volk darf nicht mit ihm hinaufsteigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Und Moses kam und kündete dem Volke alle Worte des Herrn und alle Rechtssatzungen. Da antwortete das Volk einstimmig und sprach: \"All die Worte, die der Herr gesprochen, wollen wir befolgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Und Moses schrieb alle Worte des Herrn nieder. Am anderen Morgen früh aber baute er einen Altar unten am Berge und zwölf Denksteine für die zwölf Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Dann sandte er die Jungmänner der Israeliten hin, und sie brachten Brandopfer und schlachteten Stiere zu Dankopfern für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Moses aber nahm den einen Teil des Blutes und goß es in die Becken; den anderen Teil des Blutes sprengte er an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Dann nahm er das Bundesbuch und las es dem Volke laut vor. Sie sprachen: \"Alles, was der Herr geredet, wollen wir tun und darauf hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Da nahm Moses das Blut, sprengte es auf das Volk und sprach: \"Dies ist das Blut des Bundes, den der Herr mit euch schließt auf alle diese Worte hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Dann stiegen Moses empor und Aaron, Nadab, Abihu mit siebzig der Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Da sahen sie Israels Gott, zu seinen Füßen etwas wie ein Werk aus Saphirplatten und wie der Himmel selbst so rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Aber an die Edlen der Israeliten hatte er nicht seine Hand gelegt. So schauten sie die Gottheit, konnten aber wie sonst essen und trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Da sprach der Herr zu Moses: \"Steig auf den Berg zu mir und bleibe hier! Ich will dir Steintafeln mit dem Gesetze und dem Gebote geben, das ich zu ihrer Weisung geschrieben habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Da stand Moses auf und sein Diener Josue. Und Moses stieg zu dem Berge der Gottheit empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Zu den Ältesten aber hatte er gesagt: \"Wartet hier auf uns, bis wir zu euch zurückkehren! Bei euch sind ja Aaron und Hur. Wer einen Rechtsstreit hat, wende sich an sie!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Und Moses stieg auf den Berg. Da verhüllte die Wolke den Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und des Herren Majestät ließ sich herab auf den Berg Sinai. Und die Wolke hüllte ihn sechs Tage ein. Am siebten Tage aber rief er Moses mitten aus der Wolke an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Die Erscheinung der Majestät des Herrn aber war wie ein fressendes Feuer auf dem Bergesgipfel vor den Augen der Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Und Moses kam mitten in die Wolke und stieg auf den Berg. Und dann weilte Moses auf dem Berge vierzig Tage und vierzig Nächte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Der Herr aber sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '\"Sprich zu den Söhnen Israels, sie sollen für mich beisteuern! Von jedem, den sein Herz dazu treibt, sollt ihr Beisteuer für mich erheben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Dies sei die Beisteuer, die ihr von ihnen erheben sollt: Gold, Silber, Kupfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Purpur, blau und rot, Karmesin, Linnen, Ziegenhaar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'gegerbte Widderfelle, Seekuhhäute, Akazienholz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öl für den Leuchter, Spezereien zum Salböl und zum Räucherwerk, dem köstlich duftenden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onyxsteine und andere Edelsteine zum Besatz des Schulterkleides und der Tasche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Ein Heiligtum sollen sie mir machen, daß ich in ihrer Mitte wohne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Genau nach dem, was ich dir zeige, nach dem Muster der Wohnung und dem Muster all ihrer Geräte, so sollt ihr es machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Sie sollen demnach von Akazienholz eine Lade machen, zweieinhalb Ellen lang, anderthalb hoch und breit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Überziehe sie mit reinem Gold! Überziehe sie ganz von innen und von außen! Und mach einen goldenen Kranz ringsum an ihr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Vier goldene Ringe gieße für sie. An den vier Füßen bringe sie an, zwei Ringe auf der einen Seite, zwei auf der anderen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Mache Stangen von Akazien und überziehe sie mit Gold!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Paß diese Stangen in die Ringe an der Seite der Lade, die Lade daran zu tragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Die Stangen seien in den Ringen der Lade also, daß sie nicht herausschlüpfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'In diese Lade leg das Zeugnis, das ich dir geben werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Mach aus reinem Gold eine Deckplatte zweieinhalb Ellen lang, anderthalb Ellen breit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Mach zwei Cherube, aus Gold getrieben, an beiden Enden der Deckplatte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Festige den einen Cherub an dem einen Ende, den anderen am anderen Ende! Auf der Deckplatte sollst du die Cherube an ihren beiden Enden aufstellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Nach oben sollen die Cherube die Flügel breiten, mit ihren Flügeln die Deckplatte schirmend, das Antlitz einander zugekehrt! Nach der Deckplatte hin seien der Cherube Gesichter gerichtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Lege die Deckplatte oben auf die Lade! In die Lade sollst du das Zeugnis legen, das ich dir geben werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ich bezeuge mich dir dort und rede mit dir von dieser Deckplatte zwischen den beiden Cheruben auf der Zeugnislade, sooft ich dir Befehle an die Israeliten gebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Mach dann aus Akazienholz einen Tisch zwei Ellen lang, eine -Elle breit und anderthalb hoch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Überziehe ihn mit reinem Gold! Mach ihm einen goldenen Kranz ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Mach ihm eine Leiste, handbreit, ringsum und einen goldenen Kranz an seiner Leiste ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Mach ihm vier goldene Ringe und bringe die Ringe an die vier Ecken bei seinen Füßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Dicht an der Leiste seien diese Ringe als Stangenhalter, um den Tisch zu tragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Die Stangen mache aus Akazienholz und überziehe sie mit Gold! An ihnen werde der Tisch getragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Mach für ihn Schüsseln, Schalen, Kannen und Becher zum Darbringen des Trankopfers! Aus reinem Gold stelle sie her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und auf dem Tisch lege Schaubrote beständig vor mich hin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Dann mach aus reinem Gold einen Leuchter! Der Leuchter und sein Fußgestell samt seinem Schaft seien ganz gediegene Arbeit! Blumenkelche, Knospen und Blüten daraus seien an ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sechs Röhren gehen von seinen Seiten aus, drei Röhren auf der einen Seite des Leuchters und drei auf der anderen Seite des Leuchters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Drei Blumenkelche, mandelförmig, seien an jeder Röhre, mit Knospen und mit Blüten, auf der einen und der anderen Seite; so an den sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Am Leuchter selbst seien vier Blumenkelche, mandelförmig, mit Knospen und mit Blüten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Und zwar sei eine Knospe unter jedem der drei Röhrenpaare an ihm, an den sechs Röhren, die von dem Leuchter ausgehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Aus einem Stück sollen ihre Knospen und ihre Röhren mit ihm sein, aus feinem Gold getrieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Mach sieben Lampen für ihn! Man setze ihm diese Lampen so auf, daß er die ihm zugekehrte Seite beleuchte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Aus reinem Gold seien seine Lichtscheren und Pfannen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Einen Barren feinen Goldes sollst du an ihn samt allen jenen Stücken verwenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'So schau! So baue genau nach dem Muster, das auf dem Berge dir gezeigt worden ist!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '\"Die Wohnung aber sollst du aus zehn Teppichen von gezwirntem Linnen, Purpur, blau und rot, und Karmesin fertigen! Mit Cheruben nach Kunstwirkers Art sollst du sie machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Jeder Teppich sei achtundzwanzig Ellen lang, vier Ellen breit! Ein Maß für alle Teppiche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Je fünf der Teppiche seien zusammengeheftet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Mach von blauem Purpur Schleifen am Saume des letzten Teppichs der einen Fläche, desgleichen am Saume des letzten Teppichs der anderen Fläche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'An dem einen Teppich sollst du fünfzig Schleifen machen und fünfzig Schleifen an dem Rande des Teppichs der anderen Fläche, daß sich die Schleifen gegenüberstehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Mach fünfzig goldene Haken und hefte die Teppiche damit zusammen, daß die Wohnung ein Ganzes werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Mach Teppiche aus Ziegenhaar zu einem Zelt über der Wohnung! Dazu sollst du elf der Teppiche verwenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Jeder Teppich sei dreißig Ellen lang, vier Ellen breit! Ein Maß für alle elf Teppiche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Hefte fünf der Teppiche für sich zusammen, ebenso die anderen sechs! Den sechsten Teppich aber an des Zeltes Vorderseite nimm doppelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Mach fünfzig Schleifen an dem einen Saume des letzten Teppichs der einen Fläche, desgleichen fünfzig an dem Rande des Teppichs der zweiten Fläche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Mach fünfzig Kupferhaken! Ziehe die Haken durch die Schleifen und füge so das Zelt zusammen, daß es ein Ganzes werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Von dem überschüssigen Überhange an den Zeltteppichen sollst du die eine Hälfte über die Rückseite der Wohnung hängen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Auf beiden Seiten hänge je eine, Elle am Überschuß in der Länge der Zeltteppiche über die Seiten der Wohnung und hülle sie auf beiden Seiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Mach für das Zelt eine Überdecke aus gegerbten Widderfellen und aus Seekuhhäuten eine weitere Überdecke darüber!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Die Bretter zur Wohnung mache aus Akazienholz, standfest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Zehn Ellen lang sei jedes Brett, anderthalb Ellen breit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Zwei Zapfen habe jedes Brett zur gegenseitigem Versprießung! So sollst du es mit allen Brettern für die Wohnung machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'An Brettern für die Wohnung stelle zwanzig Bretter für die Südseite her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Vierzig Fußgestelle aus Silber sollst du unter die Zwanzig Bretter machen! Zwei Füße unter jedes Brett für seine beiden Zapfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Desgleichen für die andere Seite der Wohnung gegen Norden zwanzig Bretter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Und vierzig Silberfüße, zwei Füße unter jedes Brett!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Und für die Westseite der Wohnung mach sechs Bretter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Zwei Bretter mach für die Winkel an der Wohnung auf der Rückseite!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Sie seien unten doppelkantig und am Kopfende kreisrund! So sei es für beide! Sie sollen die beiden Winkel bilden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Acht Bretter seien es somit und dazu ihre Silberfußgestelle, somit sechzehn Fußgestelle, je zwei als Fußgestell für jedes Brett!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Dann mach fünf Riegel aus Akazienholz für die Bretter auf der einen Seite der Wohnung');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'sowie fünf Riegel für die Bretter auf der anderen Seite und fünf für die Bretter an der westlichen Hinterseite der Wohnung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Der mittlere Riegel laufe in der Bretter Mitte von einem Ende zum anderen durch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Die Bretter sollst du mit Gold überziehen und aus Gold die Ringe zur Aufnahme für die Riegel machen. Dann überziehe die Riegel mit Gold!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'So erstelle die Wohnung nach ihrer Ordnung, wie sie dir auf dem Berge gezeigt worden ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Mach einen Vorhang aus blauem und aus rotem Purpur, aus Karmesin und aus gezwirntem Linnen! In Kunstwirkarbeit mache man ihn mit Cheruben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Hänge ihn an vier Säulen aus Akazienholz, mit Gold überzogen, mit goldenen Stiften und vier Silberfüßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Den Vorhang hänge an die Haken! Hinter diesen Vorhang bringe die Lade des Zeugnisses! So scheide euch der Vorhang das Heilige und das Allerheiligste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und auf die Lade des Zeugnisses setze im Allerheiligsten die Deckplatte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Den Tisch stelle außerhalb des Vorhanges, den Leuchter dem Tisch gegenüber, auf der Wohnung Südseite! Den Tisch sollst du auf die Nordseite stellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Mach einen Vorhang für des Zeltes Öffnung aus blauem und aus rotem Purpur, Karmesin und aus gezwirntem Linnen in Buntwirkarbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und für den Vorhang mach fünf Säulen aus Akazienholz! Überziehe sie mit Gold und gieße für sie fünf Kupferfußgestelle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Mach aus Akazienholz den Altar, fünf Ellen lang, fünf Ellen breit! Viereckig sei der Altar und drei Ellen hoch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'An den vier Ecken bringe seine Hörner so an, daß die Hörner von ihm ausgehen! Überziehe ihn mit Kupfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Mach seine Töpfe für die Fettasche und seine Schaufeln, Becken, Gabeln, Pfannen, alle seine Sachen sollst du aus Kupfer herstellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Mache für ihn ein Gitter, Netzwerk aus Kupfer! Bringe an dem Netz vier Kupferringe an, an den vier Ecken des Altares!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Befestige dies unten so am Altargesims, daß das Netz noch bis zur Mitte des Altares reiche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Mach für den Altar Stangen aus Akazienholz und überziehe sie mit Kupfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Man bringe seine Stangen in die Ringe, damit sie in den Ringen bleiben zu beiden Seiten des Altares, wenn man ihn trägt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Aus Brettern sollst du ihn machen, daß er hohl sei! Wie man dir auf dem Berge zu schauen gegeben, so sollen sie es machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Der Wohnung Vorhof mach so: Vorhofumhänge für die Südseite aus gezwirntem Linnen, für diese eine Seite hundert Ellen lang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Dazu zwanzig Säulen nebst ihren zwanzig Kupferfüßen! Der Säulen Nägel seien, wie ihre Ringe, silbern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Desgleichen für die Langseite des Nordens Umhänge von hundert Ellen Länge, dazu die zwanzig Säulen mit ihren zwanzig Kupferfüßen! Der Säulen Nägel seien, wie ihre Ringe, silbern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Des Vorhofes westliche Breitseite habe Umhänge von fünfzig Ellen, dazu zehn Säulen nebst ihren zehn Füßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Des Vorhofes östliche Breitseite habe fünfzig Ellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Fünfzehn Ellen Umhänge sollen auf die eine Seite kommen, dazu drei Säulen nebst drei Füßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Desgleichen auf die andere Seite fünfzehn Ellen Umhänge, dazu drei Säulen mit drei Füßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Des Vorhofes Tor habe einen Vorhang, zwanzig Ellen breit, von blauem und von rotem Purpur, Karmesin, gezwirntem Linnen, bunt gewirkt, dazu vier Säulen nebst vier Füßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Des Vorhofes Säulen alle seien mit Silberringen ringsumher versehen! Auch ihre Nägel seien silbern, ihre Füße aber kupfern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Des Vorhofes Länge sei hundert Ellen, die Breite fünfzig, die Höhe fünf, aus gezwirntem Linnen! Die Füße aber seien kupfern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Aus Kupfer seien alle die Geräte in der Wohnung nebst ihrem ganzen Zubehör, desgleichen alle ihre Pflöcke und des Vorhofes Pflöcke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Du aber sollst den Israeliten befehlen, dir lauteres Öl aus zerstoßenen Oliven für den Leuchter zu holen, um die ewige Lampe anzuzünden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im Festgezelt außerhalb des Vorhangs, vor dem Zeugnis, richte ihn Aaron mit seinen Söhnen zu, daß er vom Abend bis zum Morgen vor dem Herrn sei! Als ewige Verpflichtung sei dies den Israeliten für alle Geschlechter auferlegt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '\"Berufe deinen Bruder Aaron und nächst ihm seine Söhne aus all den Söhnen Israels zu dir, daß er mir Priester sei! Aaron, Nadab, Abihu, Eleazar und Itamar, die Söhne Aarons!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Mach deinem Bruder Aaron Kleider für das Heiligtum, für den Anstand und die Würde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Du sollst dich mit allen Leuten weisen Sinnes besprechen, wen ich mit weisem Geiste erfülle, auf daß sie Aarons Kleider machen, um ihn zu weihen, daß er mir Priesterdienste tue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Dies sind die Kleider, die sie machen sollen: Die Tasche, das Schulterkleid, das Oberkleid und den Leibrock aus gewürfeltem Stoff, den Kopfbund und den Gürtel. So sollen sie deinem Bruder Aaron mit seinen Söhnen heilige Kleider machen, daß er mir Priesterdienste tue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Und dazu nehmen sollen sie Gold, blauen und roten Purpur, Karmesin und Linnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Das Schulterkleid sollen sie aus Gold machen, aus blauem und rotem Purpur, Karmesin und Linnen in kunstgewirkter Arbeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Zwei Schulterstücke, unter sich verbunden, soll es haben! Auf seinen beiden Enden werde es geknüpft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Das Band zum Umbinden sei von gleicher Arbeit. Ein Stück mit ihm, aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Nimm zwei Onyxsteine und grabe darein der Söhne Israels Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Sechs ihrer Namen auf den einen Stein, die übrigens sechs Namen auf den zweiten Stein, nach ihrer Geburtsfolge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'In Steinschneideart, in Siegelstich sollst du in die beiden Steine der Söhne Israels Namen graben und sie in goldenes Geflecht fassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Setze die beiden Steine auf die Schulterstücke des Schulterkleides als Steine des Gedenkens an die Söhne Israels! Im Dienst des Herrn trage Aaron ihre Namen auf den Schultern zum Gedächtnis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Sodann mach Goldgeflechte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und aus reinem Gold zwei Kettchen! Du sollst sie in gedrehten Schnüren herstellen! Befestige an den Goldgeflechten die Schnurkettchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Dann mach in Kunstwirkarbeit eine Lostasche! Wie das Schulterkleid sollst du sie machen! Aus Gold, aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen sollst du sie machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig sei sie, doppelt gelegt, je eine Spanne lang und breit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Besetze sie mit Edelsteinbesatz in vier Steinreihen! Karneol, Topas und Smaragd sei die erste Reihe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Die zweite Reihe Rubin, Saphir und Jaspis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Die dritte Reihe Hyazinth, Achat und Amethyst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Die vierte Reihe Chrysolith, Onyx und Beryll. In ihrer Einfassung seien sie goldumflochten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Die Steine sollen für der Söhne Israels Namen da sein, zwölf nach ihren Namen. In jeden sei der Name eines der zwölf Stämme eingegraben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Mach an die Tasche rein goldene Schnurkettchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Bringe an der Tasche auch zwei goldene Ringe an! Befestige die beiden Ringe an den Enden der Tasche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Befestige die beiden goldenen Schnüre in den beiden Ringen an den Enden der Tasche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Der beiden Schnüre beide Enden sollst du an die zwei Geflechte befestigen und diese an die Schulterstücke vorn am Schulterkleid!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Mach zwei goldene Ringe und setze sie an die beiden Enden der Tasche, an ihren Rand, nach innen dem Schulterkleid zu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Mach noch zwei goldene Ringe und befestige sie an den beiden Schulterstücken des Schulterkleides, unten an der Vorderseite, bei der Knüpfung, doch oberhalb der Schulterkleidbinde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Man soll die Tasche samt den Ringen an die Ringe des Schulterkleides mit blauen Purpurschnüren ketten, daß sie über der Schulterkleidbinde sei und sich die Tasche nicht vom Schulterkleide trenne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Aaron trage in der Tasche auf der Brust der Söhne Israels Namen, wenn er ins Heiligtum geht, zur ständigen Erinnerung des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Und in die Tasche lege die Urim und Tummim, daß sie auf Aarons Brust seien, wenn er vor den Herrn tritt! Also trage Aaron für die Söhne Israels die Tasche vor dem Herrn beständig auf der Brust!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Das Obergewand zum Schulterkleid mache aus blauem Purpur!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'In seiner Mitte sei seine Kopföffnung! Und diese Öffnung habe einen Saum ringsum in Webart! Wie eine Panzeröffnung soll es eine solche haben, daß es nicht zerreiße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Mach an dem Saum Granatäpfel von blauem und rotem Purpur und Karmesin, rings an seinem Saum, und goldene Glöckchen mitten darin ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Goldene Glöckchen sollen mit Granatäpfeln am Saum des Oberkleides ringsum abwechseln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Beim Dienste trage es Aaron, und sein Geräusch werde gehört, wenn er vor den Herrn ins Heiligtum geht und wenn er herausgeht, daß er nicht sterbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Dann mach aus reinem Gold ein Blatt und grabe darauf in Siegelstich: \'Heiligtum des Herrn\'!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Befestige dies mit blauer Purpurschnur am Kopfbunde! Vorn am Kopfbunde sei es!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Es sei auf Aarons Stirn! So ersetze Aaron die Fehler an heiligen Gaben, die Israels Söhne darbringen, bei all ihren heiligen Opfergaben! Auf seiner Stirn sei es beständig, daß ihnen Wohlgefallen vor dem Herrn werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Den Leibrock webe aus Linnen, würfelförmig ausgemustert! Einen Kopfbund mach aus Linnen! Und einen Gürtel in buntgewirkter Arbeit sollst du machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Für Aarons Söhne sollst du Leibröcke herstellen; mach auch Gürtel, und hohe Mützen sollst du ihnen für den Anstand und die Würde machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Kleide darein deinen Bruder Aaron und seine Söhne bei ihm! Dann salbe sie, fülle ihre Hand und weihe sie, daß sie mir Priesterdienste tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Fertige ihnen Linnenbeinkleider zur Verhüllung der Blöße! Von den Hüften bis zu den Schenkeln sollen sie reichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Aaron und seine Söhne sollen sie tragen, wenn sie zum Festgezelt eingehen oder an den Altar treten, um Dienst im Heiligtum zu tun! Sonst würden sie Schuld auf sich laden und sterben. Dies gelte ihm und seinem Stamm als ewige Verpflichtung!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '\"Dies ist der Hergang, den du beachten sollst, wenn du sie zum Priesterdienst für mich weihst: Nimm einen jungen Stier und zwei fehlerlose Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ungesäuertes Brot, ungesäuerte, ölbestrichene Kuchen und ungesäuerte, ölbestrichene Fladen! Aus Weizenmehl sollst du sie machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Leg sie in einen Korb und bringe sie in dem Korbe her! Dazu den Farren und die beiden Widder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Dann führe Aaron mit den Söhnen an des Bundeszeltes Eingang und bade sie in Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Dann nimm die Gewänder! Bekleide Aaron mit dem Leibrock und mit dem Oberkleid zum Schulterkleid, mit dem Schulterkleid selbst und mit der Tasche und binde ihm des Schulterkleides Binde um!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Setze ihm den Kopfbund auf sein Haupt! Befestige am Kopfbunde das heilige Diadem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Dann nimm das Salböl, gieße es auf sein Haupt und salbe ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Alsdann sollst du seine Söhne kommen lassen; bekleide sie dann mit Leibröcken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Umgürte sie mit einem Gürtel, Aaron wie seine Söhne! Setz ihnen Mützen auf! So stehe ihnen kraft ewiger Ordnung das Priesteramt zu! Nun fülle Aarons und seiner Söhne Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Dann bringe den Farren zu dem Festgezelt her, und Aaron und seine Söhne sollen ihre Hände auf des Farren Kopf legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Dann schlachte vor dem Herrn den Farren an dem Eingang zum Festgezelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Nimm von dem Farrenblut und tu es mit deinem Finger an die Altarhörner! Das andere Blut sollst du ganz auf den Altarsockel gießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Nimm alles Fett der Eingeweidedecke, den Leberlappen und die beiden Nieren samt dem Fett daran und laß es auf dem Altar verrauchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Das Fleisch des Farren, sein Fell und seinen Mist sollst du außer Lagers verbrennen! Ein Sündopfer ist dies.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Dann sollst du den einen Widder nehmen; Aaron aber und seine Söhne sollen ihre Hände auf des Widders Kopf legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Dann schlachte den Widder, nimm sein Blut und sprenge es rings um den Altar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Dann sollst du den Widder zerstückeln; hierauf wasche seine Eingeweide und Beine und lege sie zu seinen Rumpfstücken und seinem Kopf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Dann laß den ganzen Widder auf dem Altar verrauchen! Brandopfer ist es für den Herrn, ein süßer Duft. Ein Mahl ist es für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Dann nimm den zweiten Widder, und Aaron und seine Söhne sollen ihre Hände auf des Widders Kopf legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Dann schlachte den Widder, nimm von seinem Blut und bring es an das rechte Ohrläppchen Aarons und seiner Söhne und an den rechten Daumen und die rechte große Zehe! Das andere Blut sprenge rings um den Altar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Dann nimm von dem Blut am Altar und von dem Salböl! Besprenge damit Aaron und seine Gewänder, sodann die Aaronssöhne und ihre Gewänder, daß er und seine Gewandung sowie seine Söhne und ihre Gewandung geweiht werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Dann nimm des Widders Fett, den Fettschwanz und das Fett der Eingeweidedecke, den Leberlappen und die beiden Nieren, das Fett davon und die rechte Keule, weil es ein Weihewidder ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'und einen Brotlaib, einen ölgebackenen Kuchen und einen Fladen aus dem Korb der ungesäuerten Brote vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Und leg das Ganze dem Aaron und den Söhnen auf die Hände und bringe es vor dem Herrn als Abgabe dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Dann nimm es aus ihrer Hand und laß es auf dem Brandopferaltar aufdampfen zu süßem Duft vor dem Herrn! Ein Mahl für den Herrn ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Dann nimm die Brust vom Weihewidder, der für Aaron gilt, und bringe sie vor dem Herrn als Abgabe dar! Dann sei sie dein Teil!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Weihe die Brust der Abgabe und die Weihegabekeule, von denen die eine sonst geopfert, die andere abgeliefert wird, vom Weiheopferwidder, zum Unterschied von dem, was sonst Aaron und seine Söhne bekommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Dies falle sonst Aaron und seinen Söhnen zu, kraft einer für die Israeliten ewig geltenden Verpflichtung; denn dies ist eine Abgabe. Eine Abgabe der Söhne Israels sei es von ihren Mahlopfern, ihre Abgabe für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aarons heilige Gewänder sollen seinen Söhnen nach ihm zufallen, um sie darin zu salben und ihre Hand darin zu füllen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Wer von seinen Söhnen an seiner Statt Priester ist, der soll sie sieben Tage anziehen, wenn er ins Festgezelt zum Dienst im Heiligtum kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Den Weiheopferwidder aber sollst du nehmen, und dann koche sein Fleisch an heiliger Stätte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Das Widderfleisch verzehre Aaron mit seinen Söhnen samt dem Brot im Korb am Eingang zum Festgezelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Dies sollen die verzehren, um deretwillen dieses Sühneopfer vollzogen wird, um ihre Hand zu füllen und sie zu weihen. Ein Unbefugter esse nicht davon, weil es heilige Dinge sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Und bleibt vom Fleisch des Weiheopfers und vom Brot bis zum Morgen etwas übrig, verbrenne, was übrigbleibt! Man darf es nicht essen, weil es ein heilig Ding ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tu so mit Aaron und seinen Söhnen, ganz so, wie ich dir gebiete! Fülle ihnen sieben Tage die Hand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Und einen Sündopferstier sollst du bereiten für jeden Tag zum Sühnevollzug! Entsündige den Altar durch dein Sühnewerk und salbe ihn, um ihn zu weihen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage lang sollst du die Sühnehandlungen am Altar vollziehen; so weihe ihn ein! Dann wird der Altar hochheilig. Wer den Altar berührt, wird selber heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Das ist es, was du auf dem Altar herrichten sollst: Zwei einjährige Lämmer Tag für Tag als Regel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Am Morgen sollst du das eine Lamm bereiten, das zweite gegen Abend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Zum einen Lamm komme ein Zehntel Feinmehl, gemengt mit einem Viertelkrug Öl aus zerstoßenen Oliven, dazu ein Trankopfer aus einem Viertel Wein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Das andere Lamm sollst du gegen Abend bereiten! Dabei sollst du, wie beim morgendlichen Speise- und Trankopfer tun, zu süßem Duft! Ein Mahl für den Herrn ist es,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'das stetige Brandopfer für eure Geschlechter, am Eingang zum Festgezelt vor dem Herrn, wo ich mich euch offenbare, dort mit dir redend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Ich will mich daselbst den Söhnen Israels offenbaren. Durch meine Herrlichkeit wird es geweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'So weihe ich das Festgezelt und den Altar. Auch Aaron weihe ich und seine Söhne, daß sie mir Priesterdienste tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ich wohne mitten unter Israels Söhnen und diene ihnen als Schutzgott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Und sie erfahren dann, daß ich der Herr, ihr Gott bin, der sie aus dem Ägypterland geführt, um unter ihnen zu verweilen, ich, der Herr, ihr Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '\"Mach einen Rauchaltar! Mach ihn aus Akazienholz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Viereckig sei er, eine Elle lang und eine breit, zwei hoch! Seine Hörner sollen von ihm ausgehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Überziehe ihn mit reinem Gold, seine Platte, seine Wände ringsum und seine Hörner und mach ihm einen goldenen Kranz ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Zwei goldene Ringe sollst du unterhalb des Kranzes an den beiden Seiten machen! An seinen Seiten sollst du sie machen, daß sie Gehäuse der Stangen seien, ihn daran zu tragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen mach aus Akazienholz und überzieh sie mit Gold!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Stelle ihn vor den Vorhang vor der Lade des Zeugnisses und vor den Deckel über dem Zeugnis, wo ich mich dir offenbaren werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Aaron räuchere darauf wohlriechendes Räucherwerk! Er soll es alle Morgen räuchern, wenn er die Lampen richtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Und wenn Aaron abends die Lampen aufsteckt, dann soll er räuchern! In euren Geschlechtern sei vor dem Herrn ein stetig Rauchopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr sollt auf ihm kein fremdes Räucherwerk darbringen, nicht Brand-, nicht Speiseopfer! Ihr sollt darauf kein Trankopfer ausgießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Einmal im Jahr verrichte Aaron an seinen Hörnern die Sühnehandlung! Einmal im Jahr soll er daran durch das Versöhnungssündenopferblut die Sühne in euren Geschlechtern vornehen! Dem Herrn ist er hochheilig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und der Herr redete mit Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '\"Erhebst du der Söhne Israels Zahl bei ihrer Musterung, dann sollen sie dem Herrn ein Lösegeld für ihr Leben geben, Mann für Mann, wenn man sie mustert! Dann befällt sie keine Plage, wenn man sie mustert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Wer der Musterung unterliegt, der soll die Hälfte des heiligen Ringes zahlen! Zwanzig Korn sind ein gemeiner Ring; dieser gilt nur als halber Ring bei einer Abgabe für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Wer der Musterung unterliegt, von zwanzig Jahren und darüber, soll für den Herrn die Abgabe geben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche gebe nicht mehr, der Arme nicht weniger als einen halben Ring, wenn sie die Abgabe für den Herrn entrichten, um euer Leben zu lösen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Nimm von den Söhnen Israels das Sühnegeld und gib es für den Dienst am Festgezelt! So wirke es den Söhnen Israels beim Herrn ein Gedenken und ihres Lebens Lösung!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '\"Mach dir ein Kupferbecken mit kupfernem Gestell zum Waschen und stelle es zwischen Festgezelt und Altar und gieße Wasser darein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Daraus sollen sich Aaron und die Söhne Hände und Füße waschen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie zum Festgezelt kommen, sollen sie sich waschen, daß sie nicht sterben, oder wenn sie beim Dienst zum Altare treten, ein Mahl für den Herrn aufdampfen zu lassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'dann sollen sie Hände und Füße waschen, daß sie nicht sterben! Dies sei ihnen ewige Pflicht, ihm sowie seinem Stamm für ihre Geschlechter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '\"Nimm dir Balsamessenz und reine Myrrhe fünfhundert, und Zimt halb soviel, zweihundertfünfzig, Gewürzrohr, zweihundertfünfzig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und Kassia, fünfhundert nach dem heiligen Ring, und einen Krug voll Olivenöl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Und mache es zu heiligem Salböl, zu würziger Salbe, zu eines Salbenmischers Werk! Ein heilig Salböl soll es werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Salbe damit das Festgezelt und die Lade des Zeugnisses,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'den Tisch und alle seine Geräte, den Leuchter und sein Zubehör, den Rauchaltar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'den Brandopferaltar und alle seine Geräte, das Becken und sein Gestell!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'So weihe sie, daß sie hochheilig seien! Wer sie berührt, wird gleichfalls heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Auch Aaron und seine Söhne sollst du salben; so weihe sie, daß sie mir Priester seien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Sprich zu den Söhnen Israels: \'Ein heilig Salböl sei mir dies für eure Geschlechter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf keines Menschen Leib darf es gegossen werden! Ihr dürft in seiner Mischung für euch nichts Gleiches machen. Ein heilig Ding ist es. Ein heilig Ding bleibe es euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer solches mischt und davon an einen Unbefugten bringt, werde aus seinem Volke gestrichen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Der Herr sprach zu Moses: \"Nimm Spezereien, Tropfharz, Räucherklaue, wohlriechendes Harz und reinen Weihrauch, alles zu gleichen Teilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Mach daraus ein Räucherwerk, eine würzige Mischung, eines Salbenmischers Werk, scharf, rein, ein heilig Ding!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Verreibe davon staubfein und bringe davon vor das Zeugnis ins Festgezelt, wo ich mich dir offenbaren werde! Hochheilig sei es euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Das Räucherwerk, das du machst, dürft ihr für euch nicht mehr nachmachen. Ein heilig Ding für den Herrn sei es dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer gleiches macht, daran zu riechen, werde aus seinem Volke gestrichen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '\"Sieh! Ich berufe Besalel, des Uri Sohn, den Enkel Hurs, vom Stamme Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Ich erfülle ihn mit Gottesgeist, mit Weisheit, Einsicht und Wissen um jeglich Werk,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'um Pläne zu ersinnen und sie in Gold, Silber und Kupfer auszuführen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'im Schnitt von Steinen zu Füllungen und im Schnitt von Hölzern, in vielgestaltiger Ausführung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Oholiab, den Sohn Achisamaks, vom Danstamme gebe ich ihm bei und verleihe Weisheit allen anderen Künstlern, daß sie alles machen, was ich dir befehle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Das Festgezelt und die Lade des Zeugnisses, die Deckplatte darüber und die anderen Geräte im Zelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'den Tisch und seine Geräte, den reinen Leuchter mit all seinen Geräten, den Rauchaltar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Altar für Brandopfer und alle seine Geräte, das Becken mit seinem Gestell,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'die feineren Schutzdecken und die Gewänder für das Heiligtum, für Aaron, den Priester, und die Gewänder seiner Söhne für den priesterlichen Dienst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'das Salböl und das würzige Rauchwerk für das Heiligtum. Ganz wie ich es dir befehle, sollen sie es machen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '\"Sag dies den Söhnen Israels: \'Beobachtet doch meine Ruhetage! Ein Zeichen zwischen mir und euch ist ein solcher in euren Geschlechtern, auf daß man wisse, daß ich, der Herr, euch heilige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Haltet auch den Sabbat! Er sei euch ein heilig Ding! Wer ihn entweiht, sterbe des Todes! Wer an ihm Arbeit tut, solch Wesen werde getilgt aus seinem Volke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage werde Arbeit getan! Am siebten Tage aber ist der rechte Ruhetag, ein heilig Ding dem Herrn! Wer am Sabbat Arbeit tut, sei des Todes!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'So sollen die Söhne Israels den Sabbat halten! Zum ewigen Bunde sollen sie den Sabbat in ihren Geschlechtern machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Er sei ein Zeichen zwischen mir und den Söhnen Israels für immer! Denn in sechs Tagen hat der Herr den Himmel und die Erde gemacht. Am siebten Tage aber hat er aufatmend geruht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Und er übergab Moses, nachdem er mit ihm auf dem Berg Sinai zu Ende geredet, die beiden Tafeln des Zeugnisses, steinerne Tafeln, vom Finger Gottes beschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Als das Volk sah, daß Moses säumte, vom Berg herabzusteigen, rottete sich das Volk wider Aaron und sprach zu ihm: \"Auf! Mach uns Götter, die vor uns herziehen! Denn also ist es mit Moses, dem Manne, der uns aus Ägypterland geführt: Wir wissen nicht, was aus ihm geworden ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Da sprach Aaron zu ihnen: \"Dann reißt die goldenen Ringe ab, die in den Ohren eurer Weiber, Söhne und Töchter hängen, und bringt sie mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da riß sich alles Volk seine goldenen Ohrringe ab und brachte sie zu Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Er nahm sie aus ihrer Hand und formte sie in einer Gußform. So machte er ein Gußkalb daraus. Da sprachen sie: \"Dies sind, Israel, deine Götter, die dich aus Ägypterland herausgeführt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Als aber Aaron dies wahrnahm, baute er vor ihm einen Altar. Dann rief Aaron und sprach: \"Morgen ist ein Fest des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Da opferten sie frühmorgens Brandopfer und brachten Mahlopfer. Dann setzte sich das ganze Volk, zu essen und zu trinken. Hierauf erhob es sich zu scherzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sprach der Herr zu Moses: \"Geh hinab! Verkehrtes tut dein Volk, das du aus Ägypterland geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Rasch sind sie vom Pfade gewichen, den ich ihnen geboten. Sie haben sich ein Gußkalb gemacht. Dies beten sie an, opfern ihm und sprechen: \'Dies sind, Israel, deine Götter, die dich aus Ägypterland geführt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und der Herr sprach zu Moses: \"Ich sehe, woran ich mit diesem Volke bin. Ein widerspenstiges Volk ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Nun laß mich, daß mein Zorn wider sie entbrenne und ich sie vernichte! Dich aber mache ich zu einem großen Volke.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Da begütigte Moses den Herrn, seinen Gott. \"Warum willst du, Herr, so heftig deinem Volke zürnen, das du aus Ägypterland mit großer Kraft und starkem Arm geführt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Ägypter sagen dürfen: Zur Unheilsstunde hat er sie herausgeführt, sie in den Bergen umzubringen und von der Erde zu tilgen? Laß von deiner Zornesglut! Laß dich gereuen des Unheils über dein Volk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke deiner Knechte Abraham und Isaak und Israel, was du ihnen bei dir geschworen hast! Du versprachest: \'Mehren will ich euren Stamm wie des Himmels Sterne, und dies ganze Land, von dem ich gesprochen, gebe ich eurem Stamm, daß es ihm auf ewig eigen sei.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Da ließ sich der Herr des Unheils gereuen, das er seinem Volke zu tun gedroht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'So wandte sich Moses und stieg vom Berg, die zwei Tafeln des Zeugnisses in der Hand. Die Tafeln waren auf beiden Seiten beschrieben. Vorne und hinten waren sie beschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Die Tafeln aber waren Gotteswerk, und die Schrift Gottesschrift, gegraben auf die Tafeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Da hörte Josue den Lärm des zügellosen Volkes und sprach zu Moses: \"Kriegslärm ist im Lager.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Er aber sprach. \"Das ist kein Siegesjubel und kein Fluchgeschrei. Gemeines Schreien höre ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Als er dem Lager näherkam, sah er das Kalb und Tänze. Da loderte Mosis Zorn empor, und er warf die Tafeln weg und zerschlug sie unten am Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Dann nahm er das Kalb, das sie gemacht, verbrannte es im Feuer und zerstieß es zu Staub. Dann streute er ihn auf das Wasser und gab ihn den Israeliten zu schlucken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Dann sprach Moses zu Aaron: \"Was hat dir dieses Volk getan, daß du solch schwere Schuld darüber gebracht hast?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Da sprach Aaron: \"Nicht zürne mein Herr! Du selber weißt, wie zügellos das Volk sein kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie sprachen zu mir: \'Mach du uns Götter, die vor uns herziehen! Denn also ist es mit Moses, dem Manne, der uns aus Ägypterland geführt: Wir wissen nicht, was aus ihm geworden ist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Ich sprach zu ihnen: \'Wer hat Gold?\' Da rissen sie es ab und gaben es mir. Ich warf es ins Feuer. Da kam dies Kalb heraus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Moses aber sah, daß das Volk ausgelassen war. Denn Aaron hatte es laufen lassen, hatte sich doch ihr Widerspruchsgeist hervorgedrängt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Da trat Moses ins Lagertor und rief: \"Wer für den Herrn ist, her zu mir!\" Da sammelten sich bei ihm alle Levisöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Er sprach zu ihnen: \"So spricht der Herr, Israels Gott: \'Es lege jeder sein Schwert an seine Hüfte! Geht im Lager von einem Tor zum anderen und tötet, jeder selbst den eigenen Bruder, Freund und Anverwandten!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Und die Levisöhne taten nach Mosis Wort. Vom Volke fielen an jenem Tage um 3.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Und Moses sprach: \"Tut für den Herrn das Höchste, was ihr tun könnt! Denn auch bei Sohn und Bruder ist es euch möglich, ihnen heute Segen zu vermitteln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Am anderen Morgen sprach Moses zu dem Volke: \"Schwer habt ihr euch versündigt. Nun steige ich zum Herrn empor. Vielleicht kann ich euch Verzeihung für eure Sünde erwirken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'So kehrte Moses zum Herrn und sprach.- \"Sieh, dieses Volk hat schwer gesündigt. Goldene Götter machte es sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Wenn du ihnen diese Sünde verzeihen wolltest! Wo nicht, so streiche mich lieber aus deinem Buche, in das du schreibst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Da sprach der Herr zu Moses: \"Wer sich gegen mich versündigt, nur den streiche ich aus meinem Buche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Nun aber gehe hin und führe das Volk, wohin ich dir gesagt! Fürwahr, mein Engel zieht vor dir her. Am Tage meiner Ahndung aber ahnde ich an ihnen ihre Sünde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Und der Herr schlug das Volk dafür, daß sie das Kalb hatten machen lassen, das Aaron gefertigt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Und der Herr sprach zu Moses: \"Geh, zieh hinauf von hier, du und das Volk, das du aus Ägypterland geführt, in das Land, das ich Abraham, Isaak und Jakob zugeschworen mit den Worten: \'Deinem Stamme gebe ich es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ich sende aber einen Engel vor dir her und vertreibe die Kanaaniter und die Amoriter, Chittiter, Periziter, Chiwiter und Jebusiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Denn in das Land, von Milch und Honig fließend, ziehe ich nicht in deiner Mitte hinauf; weil du ein widerspenstiges Volk bist. Ich müßte dich sonst unterwegs vernichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Als das Volk diese schlimme Botschaft vernahm, trauerte es, und niemand legte seinen Schmuck an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Und der Herr sprach zu Moses: \"Sprich zu den Söhnen Israels: \'Ihr seid ein widerspenstiges Volk. Zöge ich nur einen Augenblick in deiner Mitte mit, so müßte ich dich vertilgen. Lege keinen Schmuck mehr an, sonst wüßte ich, was ich dir täte!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da ließen die Israeliten vom Berge Horeb an ihren Schmuck weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moses aber nahm das Zelt; dann schlug er es dort außerhalb des Lagers auf, entfernt vom Lager. Er nannte es Festgezelt. Wer den Herrn suchte, ging zum Festgezelt außerhalb des Lagers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Sooft Moses zum Zelte hinausging, erhob sich alles Volk. Jeder stellte sich unter seine Zelttür, und so schauten sie Moses nach, bis er zum Zelte gekommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Sooft Moses zum Zelte kam, senkte sich die Wolkensäule herab und stand an der Zelttür und redete mit Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Sah nun das ganze Volk die Wolkensäule am Zelteingang stehen, dann begann es, jeder an seinem Zelteingang, sich niederzuwerfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Der Herr aber redete mit Moses von Angesicht zu Angesicht, wie jemand mit seinem Freunde spricht. Kehrte er ins Lager zurück, so wich sein Diener Josue, Nuns Sohn, als Lediger, nicht aus dem Zelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Moses sprach zum Herrn: \"Du sagst zu mir: \'Führe dieses Volk hinauf!\' Aber du tust mir nicht kund, wen du mit mir senden willst. Und doch sagst du: \'Ich kenne dich mit Namen. In meinen Augen hast du Gnade gefunden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Nun, habe ich in deinen Augen Gnade gefunden, dann laß mich deine Art erkennen, daß ich dich recht verstehe und mich deiner Gnade würdig zeige! Bedenke! Dein Volk ist dies Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Er sprach: \"Ginge mein Angesicht mit, beruhigte ich dich damit?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Da sprach er zu ihm: \"Zieht nicht dein Angesicht mit, dann führe uns nicht von hier hinauf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Woran denn würde sonst erkannt, daß ich mit deinem Volk in deinen Augen Gnade gefunden, wenn nicht daran, daß Du mit uns ziehst? Dadurch sind wir ja, ich und dein Volk, vor allen Erdenvölkern ausgezeichnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da sprach der Herr zu Moses: \"Auch dies, was du erbittest, will ich tun. Du hast ja Gnade in meinen Augen gefunden. Ich kenne dich mit Namen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Er sprach: \"Laß mich deine Herrlichkeit schauen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Da sprach er: \"Ich führe an dir vorüber all meine Herrlichkeit und nenne vor dir des Herrn Namen: Wem ich gnädig bin, dem bin ich gnädig, wem barmherzig, dem barmherzig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Dann sprach er: \"Mein Angesicht kannst du nicht schauen. Kein Mensch schaut mich und lebt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und der Herr sprach: \"Hier bei mir ist Platz. Stell dich auf diesen Felsen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Fährt meine Herrlichkeit vorüber, dann stelle ich dich in die Felsenritze und lege meine Hand auf dich, bis ich vorüber bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Ziehe ich dann meine Hand weg, dann schaust du meine Rückseite. Aber mein Angesicht bleibt unsichtbar.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Und der Herr sprach zu Moses: \"Behaue dir zwei Steintafeln, wie die ersten! Ich schreibe dann auf die Tafeln die Worte, die auf den ersten Tafeln standen, die du zerbrochen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Sei bereit für morgen und steige in der Frühe auf den Sinaiberg und tritt vor mich auf den Bergesgipfel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Aber niemand steige mit dir hinauf! Am ganzen Berge lasse sich niemand blicken! Auch Schafe und Rinder dürfen nicht nach diesem Berg zu weiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'So hieb er zwei Steintafeln wie die ersten zurecht. Und früh morgens stand Moses auf und bestieg den Berg Sinai, wie ihm der Herr befohlen, und nahm die zwei Steintafeln in seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da fuhr der Herr im Gewölke herab und stellte sich dort neben ihn; dann nannte er den Namen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Der Herr zog nämlich an ihm vorüber und rief: \"Herr, Herr! Ein Gott, barmherzig und gnädig, langmütig, reich an steter Güte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Tausenden wahrt er die Treue und verzeiht Schuld und Fehl und Missetat. Aber straffrei läßt er nicht, sondern ahndet der Väter Schuld an Kindern und an Enkeln, am dritten und am vierten Gliede.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Dann neigte sich Moses eilends zu Boden und warf sich nieder und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '\"Habe ich, Herr, in deinen Augen Gnade gefunden, dann ziehe der Herr mit uns! Wohl ist es ein widerspenstiges Volk. Doch verzeihe unsere Schuld und Sünde! Mach uns zu den ewig Deinen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Und er sprach: \"So schließe ich denn einen Bund: Vor all deinem Volke will ich Wunder tun, wie sie nirgends auf Erden und bei keinem Volke gewirkt worden sind. Schauen soll das ganze Volk, in dessen Mitte du weilst, wie schauervoll das Herrenwerk ist, das ich an dir tun will!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Merk dir, was ich dir heute gebiete! Sieh! Ich vertreibe vor dir die Amoriter, Kanaaniter, Chittiter, Periziter, Chiwiter und Jebusiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich vor einem Bunde mit den Insassen des Landes, in das du kommst, daß er nicht zum Falle in deiner Mitte werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Ihre Altäre sollt ihr zerstören, ihre Steinmale zerbrechen, ihre heiligen Pfähle fällen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Du sollst dich nicht vor einem anderen Gott niederwerfen! Der Herr heißt eifersüchtig. Ein eifersüchtiger Gott ist er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Daß du keinen Bund mit des Landes Insassen schließest Wenn sie ihren Göttern nachhuren und ihren Göttern opfern und man dich einlade, iß nichts von ihren Opfern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Nimm von ihren Töchtern kein Weib für deine Söhne. Ihre Töchter huren ja ihren Göttern nach, und so würden sie deine Söhne zur Götterhurerei verleiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du sollst dir kein Göttergußbild machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesäuerten Brote halte! Sieben Tage sollst du ungesäuertes Brot essen, wie ich es dir geboten, zur Zeit des Neumonds im Abib');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Du bist ja aus Ägypten gezogen an dem Neumond des Abib. 19 Ein jeder Erstlingswurf ist mein, und zwar ist all dein Zuchtvieh hier gemeint: der erste Wurf von Rindern und von Schafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Den ersten Wurf vom Esel sollst du mit einem Schafe auslösen! Lösest du ihn nicht aus, dann brich ihm das Genick! All deine erstgeborenen Söhne sollst du auslösen! Nicht schaue man gabenleer mein Angesicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage magst du arbeiten: am siebten aber sollst du ruhen! Selbst zur Zeit des Pflügens und Erntens sollst du ruhen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Du sollst dir ein Wochenfest zur Zeit der Erstlinge der Weizenernte halten und dein Herbstfest an der Jahreswende!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahr erscheine vor dem Herrn, dem Herrn, dem Gotte Israels, alles, was bei dir ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Ich tilge viele Völker vor dir und weite dein Gebiet. Und so wird niemand dein Land begehren, solange du hinaufziehst, vor dem Herrn, deinem Gott, dreimal im Jahre zu erscheinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst meines Opfers Blut nicht mit Gesäuertem zusammen schlachten! Über Nacht soll nichts vom Passahfestopfer bis zum Morgen noch da sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Von deines Ackers Erstlingen den ersten Abhub sollst du zum Hause des Herrn, deines Gottes, bringen! Du sollst kein Böckchen in seiner Mutter Fett braten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und der Herr sprach zu Moses: \"Schreib diese Worte dir auf! Denn laut dieser Worte schließe ich mit dir und mit Israel einen Bund.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er weilte dort beim Herrn vierzig Tage und vierzig Nächte. Er aß kein Brot und trank kein Wasser. Auf die Tafeln aber schrieb er die Worte des Bundes, die zehn Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Als Moses vom Berge Sinai niederstieg - die beiden Zeugnistafeln in Mosis Hand -, als er vom Berge niederstieg, wußte Moses nicht, daß seine Gesichtshaut von der Unterredung mit ihm strahlte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Aaron und alle anderen Israeliten schauten Moses, wie seine Gesichtshaut strahlte. Da fürchteten sie sich, ihm nahe zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Da rief ihnen Moses zu, und Aaron und alle Fürsten in der Gemeinschaft wandten sich ihm zu. Dann redete Moses mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Hernach traten alle Israeliten herzu, und er gebot ihnen alles, was der Herr mit ihm auf dem Berge gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Als Moses seine Unterredung mit ihnen beendigt hatte, legte er auf sein Antlitz einen Schleier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Sooft Moses vor den Herrn kam, mit ihm zu reden, entfernte er den Schleier, bis er wieder heraustrat. Trat er heraus und meldete den Israeliten, wozu er entboten ward,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'dann sahen die Israeliten an Mosis Antlitz, daß Mosis Gesichtshaut strahlte. Dann aber legte Moses den Schleier wieder über sein Antlitz, bis er hineinkam, mit ihm zu reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moses versammelte nun die ganze israelitische Gemeinschaft und sprach zu ihnen: \"Dies sind die Worte, die der Herr zu tun befiehlt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, '\'Gearbeitet darf nur sechs Tage werden! Der siebte Tag soll euch ein heilig Ding, ein rechter Ruhetag des Herrn sein! Wer an ihm irgendeine Arbeit tut, soll getötet werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ihr dürft in keiner eurer Siedlungen am Sabbattage Feuer machen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Und Moses sprach zu der ganzen israelitischen Gemeinschaft also: \"Dies ist es, was der Herr befiehlt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Liefert von euch aus eine Gabe für den Herrn! Wen dazu sein Herz treibt, der bringe für den Herrn eine Gabe an Gold, Silber, Kupfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'an blauem und rotem Purpur, Karmesin und Linnen, Ziegenhaar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'gegerbten Widderfellen, Seekuhhäuten und Akazienholz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Öl für den Leuchter und Spezereien zum Salböl und zum würzigen Räucherwerk');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'und Onyx- sowie andere Edelsteine zum Besatze des Schulterkleides und der Tasche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Dann sollen alle, die kundigen Sinnes bei euch, kommen und alles machen, was der Herr befiehlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'die Wohnung und das Zelt mit seiner Hülle und seinen Haken, Brettern, Riegeln, Säulen, Füßen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade, ihre Stangen, ihre Deckplatte, den verhüllenden Vorhang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Stangen und all seinen Geräten, das Schaubrot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter zur Beleuchtung, alle seine Geräte, seine Lampen und das Leuchteröl,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Rauchaltar und seine Stangen, das Salböl und das würzige Räucherwerk, den Vorhang für der Wohnung Tür,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar, das Kupfergitterwerk daran und seine Stangen, seine Geräte, den Kessel und sein Gestell,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'des Vorhofs Umhänge mit seinen Säulen und Fußgestellen, des Vorhoftores Vorhang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'der Wohnung Pflöcke, die des Vorhofes, ihre Stricke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die Schongewänder zum Dienste im Heiligtum, des Heiligtums Gewänder für den Priester Aaron und seiner Söhne Kleider für den Priesterdienst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Da gingen sie, die ganze israelitische Gemeinschaft von Moses weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Dann kam jeder, den sein Sinn bewegt, und jeder, den sein Herz angetrieben; sie brachten eine Gabe dem Herrn für die Arbeit am Festgezelt, für all seinen Dienst darin und für die heiligen Gewänder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Die Männer kamen neben den Weibern; alle, die ihr Herz antrieb, brachten Spangen, Ohr- und Fingerringe und Geschmeide, lauter goldene Sachen, jeder, der an Gold eine Weihegabe dem Herrn geweiht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Jeder, bei dem sich blauer und roter Purpur, Karmesin, Linnen, Ziegenhaar, gegerbte Widderfelle und Seekuhhäute vorgefunden, brachte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Jeder, der eine Gabe an Silber und Kupfer geben wollte, brachte diese Gabe für den Herrn, ebenso wer Akazienholz für allerlei Verwertung hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Jedes kunstfertige Weib, das auf gewöhnliche Art spann, brachte das Gespinst, blauen und roten Purpur, Karmesin und Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Alle die Weiber, die ihr Sinn in Weisheit bewegt hatte, verspannen Ziegenhaar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Fürsten brachten Onyx- und andere Edelsteine zum Besatz des Schulterkleides und der Tasche,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'dazu die Spezereien und das Öl für den Leuchter, zum Salböl und zum wohlduftenden Räucherwerk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Jeder Mann und jedes Weib brachte, was sie ihr Herz zu bringen trieb, für alle Arbeit, deren Anfertigung der Herr durch Moses geboten hatte. Die Söhne Israels brachten es freiwillig dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Moses aber sprach zu den Israeliten: \"Seht! Mit Namen hat der Herr den Besalel berufen, des Uri Sohn, den Enkel Hurs, vom Stamme Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Mit Gottesgeist erfüllte er ihn, mit Kunstsinn, Einsicht und Wissen um ein jeglich Werk,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'und um Pläne zu ersinnen, um in Gold, Silber oder Kupfer sie auszuführen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'in Steinschnitt zu Füllungen und im Holzschneiden, um sie vielgestaltig auszuführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Auch die Gabe, Anregungen zu geben, hat er in sein Herz gelegt. Ihn selber und Oholiab, den Sohn Achisamaks, vom Stamme Dan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'sie beide hat er mit weisem Sinne erfüllt, jegliche Arbeit zu machen, die des Schmiedes und des Kunstwebers, des Buntwirkers in blauem und rotem Purpur, in Karmesin und Linnen und die des Webers. So machten sie jegliche Arbeit und ersannen Kunstwerke.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '\"So mache es Besalel, Oholiab und jeder Kunstverständige, dem der Herr Weisheit und Einsicht verliehen, alle Arbeit zur Fertigung des Heiligtumes zu verstehen, Weisheit und Einsicht für alles, was der Herr befohlen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Hierauf berief Moses den Besalel und Oholiab und jeden kunstverständigen Mann, dem der Herr Weisheit verliehen, jeden, den sein Sinn bewegt hatte, an die Ausführung des Werkes zu gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Sie empfingen unter Mosis Aufsicht alle Gaben, die die Israeliten für die Arbeit der Fertigstellung des Heiligtums gebracht, um sie zu verarbeiten. Aber noch brachten sie ihm jeden Morgen freiwillige Gaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da gingen alle Weisen, die alle Arbeit am Heiligtume machten, Mann für Mann von ihrer Arbeit weg, die sie machten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sprachen zu Moses: \"Das Volk bringt viel mehr, als zur Fertigung der vom Herrn gebotenen Arbeiten nötig ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da gab Moses Befehl, und man ließ im Lager den Ruf ergehen: \"Nicht Mann noch Weib mehr mache etwas zu einer Gabe für das Heiligtum!\" So ward dem Volke weiteres Bringen verwehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Stoff genug war da, um alle Arbeit auszuführen, ja übergenug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'So machten all die Kunstverständigen unter den am Werk Beschäftigten die Wohnung aus zehn Teppichen von gezwirntem Linnen, blauem und rotem Purpur und Karmesin. Mit Cheruben, nach Kunstwirkers Art, hatte man sie gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Jeder Teppich war achtundzwanzig Ellen lang und vier breit. Alle Teppiche hatten einerlei Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Fünf Teppiche heftete man zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Man machte blaue Purpurschleifen am Saume des äußersten Teppichs der einen Naht, ebenso am Saum des äußersten Teppichs der anderen Naht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen hatte man an dem einen Teppich gemacht und fünfzig am Rand des Teppichs der anderen Naht, so daß die Schleifen einander gegenüberstanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Dann machte man fünfzig goldene Haken und heftete die Teppiche mittels der Haken zusammen. So ward die Wohnung ein Ganzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Dann machte man Teppiche aus Ziegenhaar zu einem Zelt über der Wohnung. Elf Teppiche nahm man dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'jeder Teppich war dreißig Ellen lang und vier breit. Alle elf Teppiche hatten einerlei Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Dann heftete man fünf Teppiche für sich zu einem Ganzen, ebenso die sechs Teppiche für sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Dann machte man fünfzig Schleifen am Saum des äußersten Teppichs der einen Naht und fünfzig an dem der anderen Naht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Dann machte man fünfzig Kupferhaken, um das Zelt zu einem Ganzen zusammenzuheften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Dann machte man eine Zeltdecke aus gegerbten Widderfellen und oben darüber eine Decke aus Seekuhhäuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Dann machte man gerade Bretter zur Wohnung aus Akazienholz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Jedes Brett zehn Ellen lang und anderthalb breit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'an den einzelnen Brettern zwei Zapfen unter sich verbunden. So machte man alle Bretter der Wohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Und zwar machte man an Brettern für die Wohnung zwanzig Bretter für die Südseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Unter die zwanzig Bretter machte man vierzig silberne Füße, je zwei Füße unter jedem Brett für seine zwei Zapfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Ebenso für die andere Seite der Wohnung gegen Norden zwanzig Bretter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'mit ihren vierzig silbernen Füßen, je zwei Füße unter jedem Brett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Für die Westseite machte man sechs Bretter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'und zwei Bretter für die Winkel der Wohnung auf der Rückseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Sie waren unten doppelkantig und am Kopfende kreisrund. So machte man es mit beiden in den beiden Winkeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Somit waren es acht Bretter mit sechzehn silbernen Füßen; je zwei Füße unter jedem Brett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Dann machte man fünf Akazienholzriegel für die Bretter der einen Wohnseite,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'fünf Riegel für die Bretter der anderen Wohnseite und fünf Riegel für die Bretter der westlich gelegenen Wohnseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Den mittelsten Riegel ließ man in der Brettermitte von einem Ende zum anderen durchlaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Die Bretter überzog man mit Gold. Aus Gold fertigte man auch die Ringe zur Aufnahme der Riegel; die Riegel überzog man gleichfalls mit Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Dann stellte man den Vorhang her aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen, mit Cheruben in Kunstwirkerarbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Man machte für ihn vier Akaziensäulen und überzog sie mit Gold. Auch ihre Stifte waren aus Gold, und man goß für sie vier silberne Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Dann machte man einen Vorhang für die Zeltöffnung aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen in Buntwirkerarbeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'nebst seinen fünf Säulen und ihren Stiften. Ihre Köpfe und ihre Ringe überzog man mit Gold; ihre fünf Füße aber waren kupfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Und Besalel machte die Lade aus Akazienholz, zwei und eine halbe Elle lang, anderthalb breit und hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Er überzog sie in- und auswendig mit reinem Gold und machte ihr einen goldenen Kranz ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Dann goß er für sie vier goldene Ringe für die vier Füße, zwei Ringe auf der einen Seite und zwei auf der anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Dann fertigte er Akazienstangen und überzog sie mit Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Diese Stangen zog er durch die Ringe an den beiden Seiten der Lade, um die Lade zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Dann machte er aus reinem Gold eine Deckplatte, zweieinhalb Ellen lang und anderthalb breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Auch machte er zwei goldene Cherube. Er machte sie in getriebener Arbeit für die beiden Enden der Deckplatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Den einen Cherub an dem einen Ende, den anderen am anderen Ende. An beiden Enden der Deckplatte brachte er die Cherube an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Die Cherube breiteten nach oben ihre Flügel, mit ihren Flügeln die Deckplatte deckend, die Gesichter sich zugekehrt. Die Cherubsgesichter aber schauten nach der Deckplatte hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Dann machte er aus Akazienholz einen Tisch, zwei Ellen lang, eine breit und anderthalb hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Er überzog ihn mit reinem Gold und machte ihm einen goldenen Kranz ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Dann machte er ihm eine handbreit große Leiste ringsum, und daran machte er wieder einen goldenen Kranz ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Er goß für ihn vier goldene Ringe und befestigte diese Ringe an den vier Ecken seiner vier Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Dicht an der Leiste waren die Ringe zur Aufnahme der Stangen, um den Tisch zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Die Stangen machte er aus Akazienholz und überzog sie mit Gold, um den Tisch zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Er machte die Geräte für den Tisch, seine Schüsseln, Schalen, Becher und Kannen zur Trankopferspende, aus reinem Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Aus reinem Gold machte er auch den Leuchter; in getriebener Arbeit machte er den Leuchter, sein Fußgestell und seinen Schaft; seine Kelche, Knospen und Blüten gingen aus ihm hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Von seinen Seiten gingen sechs Röhren aus, je drei auf jeder Leuchterseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'An jeder Röhre waren drei Mandelblütenkelche, je eine Knospe samt der Blüte. So an allen sechs von dem Leuchter ausgehenden Röhren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Am Leuchter selbst waren vier Mandelblütenkelche, mit Knospen und Blüten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'jedesmal eine Knospe unter jedem der drei Röhrenpaare, der sechs von ihm ausgehenden Röhren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knospen und Röhren waren aus einem Stück mit ihm, alles getriebene Arbeit aus einem Stück, von reinem Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Dann machte er seine sieben Lampen nebst seinen Lichtscheren und Pfannen von reinem Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Barren Feingold machte er ihn und seine Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Dann machte er aus Akazienholz den Räucheraltar, eine Elle lang, eine breit, viereckig und zwei Ellen hoch. Seine Hörner gingen aus ihm hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Er überzog mit reinem Gold ihn, seine Platte und seine Wände ringsum sowie seine Hörner und machte ihm einen goldenen Kranz ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Unterhalb des Kranzes machte er seinen beiden Ecken beiderseitig je zwei goldene Ringe zur Aufnahme der Stangen, um ihn daran zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Die Stangen machte er aus Akazienholz und überzog sie mit Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Dann machte er das heilige Salböl sowie das reine, wohlriechende Räucherwerk nach Salbenmischer Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Dann machte er den Brandopferaltar aus Akazienholz, fünf Ellen lang, fünf breit, viereckig und drei Ellen hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Er machte an seinen vier Ecken seine Hörner so, daß seine Hörner an ihm ausliefen. Er überzog sie mit Kupfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Dann machte er alle Altargeräte, Töpfe, Schaufeln, Becken, Gabeln und Pfannen. Aus Kupfer machte er alle seine Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Für den Altar machte er ein Gitterwerk, ein kupfernes Netzwerk, unterhalb seines Gesimses bis zu seiner halben Höhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Er goß vier Ringe für die vier Ecken des Kupfergitterwerkes zur Aufnahme der Stangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Die Stangen machte er aus Akazienholz und überzog sie mit Kupfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Die Stangen zog er durch die Ringe an den Seiten des Altares, um ihn daran zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Er machte ihn aus Brettern, so daß er hohl war. Das Becken machte er aus Kupfer, ebenso sein Gestell aus Kupfer von den Spiegeln der Mädchen, die den Eingang zum Festgezelt schmückten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Dann machte er den Vorhof. Die Vorhofumhänge aus gezwirntem Linnen für die Südseite waren hundert Ellen lang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'dazu zwanzig Säulen mit ihren zwanzig Kupferfüßen. Die Säulenstifte und ihre Ringe waren silbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Für die Nordseite hundert Ellen, dazu zwanzig Säulen mit ihren zwanzig Kupferfüßen. Die Säulenstifte und ihre Ringe waren silbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Für die Westseite Umhänge von fünfzig Ellen, dazu zehn Säulen mit ihren zehn Füßen. Die Säulenstifte und ihre Ringe waren silbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Für die Ostseite fünfzig Ellen-,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Umhänge von fünfzehn Ellen für die eine Seite, dazu drei Säulen mit ihren drei Füßen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'für die andere Seite, zu beiden Seiten des Vorhoftores, Umhänge von fünfzehn Ellen, dazu drei Säulen mit ihren drei Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Vorhofumhänge ringsum waren von gezwirntem Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Die Säulenfüße kupfern, die Säulenstifte und ihre Ringe silbern, ebenso der Überzug ihrer Köpfe silbern. Alle Vorhofsäulen waren mit Silberringen versehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Des Vorhoftores Vorhang war Buntwirkerarbeit aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen, zwanzig Ellen lang und fünf Ellen hoch in der Breite, entsprechend den Vorhofsumhängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Seine vier Säulen mit ihren vier Füßen waren kupfern, ihre Stifte silbern und der Überzug ihrer Köpfe und ihrer Ringe silbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle Pflöcke an der Wohnung und am Vorhof ringsum waren kupfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Dies sind die Verordnungen für die Wohnung, die Zeugniswohnung, wie sie auf Mosis Befehl als Dienst der Leviten unter dem Priester Itamar, dem Aaronssohn, verordnet wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Besalel, Uris Sohn und Hurs Enkel vom Stamm Juda, machte alles, was der Herr dem Moses geboten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Oholiab, Achisamaks Sohn, vom Stamm Dan als Schmied, Kunstwirker und Buntwirker in rotem und blauem Purpur, Karmesin und Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, das bei der Arbeit, bei aller Arbeit am Heiligtum, verwendet ward, das Gold der Spende, betrug 29 Barren und 730 Ringe nach der Währung des heiligen Ringes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'das Silber aus der Musterung der Gemeinde hundert Barren und 1.775 Ringe nach der Währung des heiligen Ringes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'je die Hälfte von jedem Kopf, ein Halbring nach der Währung des heiligen Ringes, von allen, die der Musterung von zwanzig Jahren und darüber unterlagen, 603.550 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Die hundert Barren Silber wurden zum Gießen der Fußgestelle des Heiligtums und der Vorhanggestelle verwendet, hundert Barren zu hundert Füßen, zu jedem Fuß ein Barren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aus den 1.775 Ringen machte man Säulenstifte, überzog ihre Köpfe und versah sie mit Ringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Das Kupfer der Weihegabe betrug 70 Barren 2.400 Ringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus machte man die Füße der Tür des Bundeszeltes, den kupfernen Altar, das kupferne Gitterwerk an ihm, alle Altargeräte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'die Füße im Vorhof ringsum, die Füße des Vorhoftores alle Pflöcke der Wohnung und alle Pflöcke des Vorhofes ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Aus blauem und rotem Purpur und Karmesin machten sie die Überwürfe als Schutzdecken für das Heiligtum; ebenso die Heiligtumsgewänder für Aaron, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Das Schulterkleid machte man aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Man schlug Goldplatten breit; dann zerschnitt man sie in Fäden, um sie in blauen und roten Purpur, Karmesin und Linnen mittels Kunstwirkerarbeit einzuarbeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Man brachte daran Schulterstücke, unter sich verbunden, an; an beiden Enden ward es verknüpft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Das Band zum Umbinden an ihm war ein Stück mit ihm von gleicher Arbeit aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen, wie der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Dann richtete man Onyxsteine her, um sie mit goldenem Netzwerk einzufassen und mittels Siegelstich darin die Namen der Söhne Israels einzugraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Man setzte sie auf die Schulterstücke des Schulterkleides als Steine des Gedenkens an die Söhne Israels, wie der Herr es dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Die Tasche aber machte man in Kunstwirkerarbeit nach Art des Schulterkleides aus Gold, blauem und rotem Purpur, Karmesin und gezwirntem Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Viereckig, gedoppelt hatte man die Tasche gemacht, je eine Spanne lang und breit, gedoppelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Man besetzte sie mit vier Reihen Edelsteinen: Karneol, Topas und Smaragd war die erste Reihe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Die zweite Reihe war Rubin, Saphir und Jaspis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Die dritte Hyazinth, Achat und Amethyst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Die vierte Chrysolith, Onyx und Beryll; in ihrer Einfassung waren sie goldumflochten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Die Steine waren nach den Namen der Söhne Israels zwölf, mittels Siegelstich jeder für einen Namen der zwölf Stämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'An die Tasche machte man reingoldene Schnurkettchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Dann machte man zwei goldene Geflechte und zwei goldene Ringe. Die Ringe befestigte man an den beiden Enden der Tasche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Die zwei goldenen Schnüre befestigte man an den beiden Ringen am Ende der Tasche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Die zwei Enden der beiden Schnüre befestigte man an die zwei Geflechte und diese an die Schulterstücke des Schulterkleides.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Dann machte man zwei goldene Ringe und setzte sie an die zwei Enden der Tasche am Rand nach innen, dem Schulterkleid zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Man machte noch zwei goldene Ringe und befestigte sie an den beiden Schulterstücken des Schulterkleides unten an der Vorderseite bei der Knüpfung, doch oberhalb der Schulterkleidbinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Dann kettete man die Tasche mit ihren Ringen an die Ringe des Schulterkleides mit blauen Purpurschnüren, daß sie über der Schulterkleidsbinde blieb und sich die Tasche nicht vom Schulterkleide trennte, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Das Oberkleid des Schulterkleides machte man in Webarbeit, ganz aus blauem Purpur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Des Obergewandes Öffnung in seiner Mitte glich der eines Panzers, mit einem Saume um seine Öffnung, daß es nicht zerreiße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'An den Saum des Obergewandes machte man Granatäpfel aus blauem und rotem Purpur, Karmesin und gezwirntem Linnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Aus reinem Gold machte man Glöckchen und setzte die Glöckchen zwischen die Granatäpfel hinein, rings um den Saum des Obergewandes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'daß immer ein Glöckchen mit einem Granatapfel abwechselte, rings um den Saum des Obergewandes, wie es der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Die Leibröcke machte man aus Linnen in Webarbeit für Aaron und seine Söhne,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'den Kopfbund aus Linnen, ebenso die Mützen, die Beinkleider aus gezwirntem Linnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'den Gürtel aus gezwirntem Linnen, blauem und rotem Purpur und Karmesin in Buntwirkerarbeit, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Das Blatt des heiligen Diadems machte man aus reinem Gold und schrieb darauf in Siegelstecherschrift: \"Heiligtum des Herrn\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Man befestigte es mit einer blauen Purpurschnur oben am Kopfbund, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'So wurde alle Arbeit für die Wohnung des Festgezeltes vollendet. Die Israeliten taten ganz, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'So brachten sie zu Moses die Wohnung, das Zelt und all seine Geräte, seine Haken, Bretter, Riegel, Säulen und Füße,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'die Oberdecke aus gegerbten Widderfellen sowie die Überdecke aus Seekuhhäuten und den verhüllenden Vorhang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Zeugnislade, ihre Stangen, die Deckplatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch mit all seinen Geräten, die Schaubrote,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den Leuchter aus reinem Gold mit seinen Lampen, den Lampen in einer Reihe, und all seinen Geräten, sowie das Öl für den Leuchter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'den goldenen Altar, das Salböl, das wohlriechende Räucherwerk und den Vorhang für die Zelttür,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den kupfernen Altar mit dem kupfernem Gitterwerk daran, seine Stangen mit all seinen Geräten, das Becken und sein Gestell,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhänge des Vorhofs, seine Säulen und Füße, den Vorhang für das Vorhoftor, seine Stricke und Pflöcke, sowie alle Geräte zum Dienste in der Wohnung des Bundeszeltes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die Überwürfe als Schutzdecken für das Heiligtum, die Heiligtumsgewänder für den Priester Aaron und die Gewänder seiner Söhne zum Priesterdienste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Wie alles der Herr dem Moses geboten, so hatten die Israeliten die gesamte Arbeit getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Da besah Moses die ganze Arbeit, und sie hatten sie so getan. So wie es der Herr befohlen, hatten sie es gemacht. Da segnete sie Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '\"Am ersten Tage des ersten Monds sollst du des Festgezeltes Wohnung aufschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Dann stelle die Zeugnislade darein und verhülle die Lade mit dem Vorhang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Bring den Tisch hinein! Leg die Schichten (der Schaubrote) auf! Dann bringe den Leuchter hinein und setze seine Lampen auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Den goldenen Rauchaltar stelle vor die Zeugnislade und hänge den Türvorhang der Wohnung auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Und vor die Tür der Festgezeltwohnung stelle den Brandopferaltar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Das Becken stelle zwischen Bundeszelt und Altar auf und gieße Wasser darein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Lege ringsum den Vorhof an und hänge den Vorhang zum Vorhoftore auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Nimm Salböl! Salbe die Wohnung und alles, was darin, und weihe sie und alle ihre Geräte, daß sie ein Heiligtum werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Salbe auch den Brandopferaltar und alle seine Geräte und weihe den Altar, so daß dieser Altar hochheilig werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Salbe auch das Becken mit seinem Fußgestell und weihe es!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Führe Aaron mit seinen Söhnen zu des Festgezeltes Tür und wasche sie mit Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Bekleide Aaron mit den Kleidern für das Heiligtum! Salbe ihn und weihe ihn, daß er mir Priesterdienste tue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Auch seine Söhne sollst du herbeiführen! Bekleide sie mit Leibröcken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Und salbe sie, wie du ihren Vater gesalbt, daß sie uns Priesterdienste tun! Die Salbung zum ewigen Priestertum gelte für sie über ihre Geschlechter hin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Moses tat so. Wie ihm der Herr geboten, tat er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Am ersten Tag des ersten Monats im zweiten Jahre ist die Wohnung aufgeschlagen worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Und Moses erstellte die Wohnung. Er setzte ihre Fußgestelle hin, setzte ihre Bretter darauf, fügte ihre Riegel ein und stellte ihre Säulen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Er spannte das Zelt über die Wohnung und legte über das Zelt die Überdecke, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Er nahm auch das Zeugnis, legte es in die Lade, steckte an die Lade die Stangen und setzte oben auf die Lade die Deckplatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Die Lade aber brachte er in die Wohnung, hängte den verhüllenden Vorhang auf und verhüllte so die Zeugnislade, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Den Tisch stellte er in das Festgezelt auf der Wohnung Nordseite außerhalb des Vorhangs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Er legte darauf die Schichten der Brote vor dem Herrn zurecht, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Den Leuchter stellte er ins Bundeszelt gegenüber dem Tisch auf die Südseite der Wohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Er setzte die Lampen vor den Herrn, wie der Herr dem Moses gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Den goldenen Altar stellte er ins Festgezelt vor den Vorhang');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'und zündete darauf wohlriechendes Räucherwerk an, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Dann hängte er den Türvorhang der Wohnung auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Den Brandopferaltar aber stellte er an den Eingang des Festgezeltes; man opferte darauf das Brand- und Speiseopfer, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Das Becken aber stellte er zwischen dem Festgezelt und dem Altare auf und goß Waschwasser hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Daraus wuschen sich Moses, Aaron und seine Söhne Hände und Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Sooft Sie zum Festgezelt kamen und sich dem Altare nahten, wuschen sie sich, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Den Vorhof aber legte er rings um die Wohnung und den Altar an und hängte den Vorhang des Vorhoftores auf. So vollendete Moses sein Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Da verhüllte eine Wolke das Festgezelt, hatte doch die Herrlichkeit des Herrn die Wohnung erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Moses konnte nicht ins Festgezelt eingehen; denn die Wolke hatte sich darauf gelagert und die Herrlichkeit des Herrn die Wohnung erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Wenn sich die Wolke von der Wohnung hob, zogen die Israeliten fort, auf all ihren Zügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Hob sich aber die Wolke nicht, so zogen sie nicht fort, bis sie sich hob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn eine Wolke lag tagsüber auf der Wohnung. Des Nachts aber war Feuer darüber vor den Augen des ganzen Hauses Israel auf allen ihren Zügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Und der Herr rief Moses und redete mit ihm vom Festgezelt aus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '\"Sprich zu den Söhnen Israels und sage ihnen: \'Will jemand von euch ein Opfer dem Herrn darbringen, so könnt ihr eure Tieropfer nur vom Rind und Schaf darbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ist sein Opfer ein Rinderbrandopfer, dann soll er ein männliches, fehlerloses Tier zum Opfer bringen! Er soll es an des Festgezeltes Pforte bringen, daß ihm Wohlgefallen vor dem Herrn werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Er lege auf den Kopf des Brandopfers seine Hand. So wird es ihm angerechnet und wird ihm Sühne schaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Dann schlachte er vor dem Herrn das junge Rind! Und die Priester, Aarons Söhne, sollen das Blut hintragen und mit dem Blute ringsum den Altar besprengen, der vor der Pforte des Festgezeltes ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Dann häute er das Brandopfer und zerstückle es!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Die Priester, Aarons Söhne, sollen Feuer auf dem Altar machen und auf das Feuer Holzscheite schichten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Dann sollen Aarons Söhne, die Priester, auf den Holzscheiten des Altarfeuers die Stücke und den Kopf samt dem Fett auflegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Seine Eingeweide aber und Beine soll er mit Wasser waschen; dann lasse der Priester alles auf dem Altar aufdampfen als Brandopfer, als Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Stammt sein Opfer für das Brandopfer vom Kleinvieh, von Lämmern oder Ziegen, dann soll er ein männliches, fehlerloses Tier zum Opfer bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Er schlachte es auf der Nordseite des Altares vor dem Herrn! Die Priester aber, Aarons Söhne, sollen mit seinem Blut ringsum den Altar besprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Dann zerlege er es in seine Teile! Mit seinem Kopf und Fett lege sie der Priester auf die Scheite des Altarfeuers!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Die Eingeweide und die Beine soll er im Wasser waschen! Dann bringe der Priester alles dar und lasse es auf dem Altar aufdampfen! Ein Brandopfer ist es, ein Mahl süßen Duftes für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ist ein Vogelbrandopfer seine Opfergabe für den Herrn, dann bringe er von Turtel- oder jungen Tauben sein Opfer dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Der Priester bringe es zum Altar und drücke ihm den Kopf ab und lasse es auf dem Altar aufdampfen! An des Altares Wand werde sein Blut ausgepreßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Er trenne dem Vogel den Kropf samt seinem Unrat ab und werfe ihn neben den Altar ostwärts auf den Aschenhaufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Dann zerknicke er ihn an seinen Flügeln, ohne ihn zu teilen! Dann lasse ihn der Priester auf dem Altar aufdampfen auf Holzscheiten über dem Feuer! Ein Brandopfer ist es, ein Mahl süßen Duftes für den Herrn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '\"\'Bringt jemand ein Speiseopfer dem Herrn dar, dann sei aus Feinmehl sein Opfer! Er gieße Öl darauf und gebe Weihrauch daran!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Dann bringe er es den Priestern, Aarons Söhnen! Und deren einer hebe eine Handvoll davon ab, von seinem Feinmehl, seinem Öl mit all seinem Weihrauch! Dann lasse der Priester auf dem Altar sein Brandteil aufdampfen, ein Mahl süßen Duftes für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Was vom Speiseopfer übrigbleibt, gehöre Aaron sowie seinen Söhnen als Hochheiliges von den Mählern des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Willst du als Speiseopfer Backwerk bringen, dann seien es Feinmehlkuchen, ungesäuert und mit Öl bereitet, und Fladen, ungesäuert und mit Öl bestrichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ist dein Opfer ein Speiseopfer in der Pfanne, dann sei es aus ungesäuertem, mit Öl bereitetem Feinmehl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Zerbrich es in Einzelbissen. Gieße Öl darüber! Ein Speiseopfer ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ist dein Opfer ein Topfspeiseopfer, so werde es mit Öl aus feinem Mehl bereitet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Dies Speiseopfer, daraus bereitet, bring dem Herrn dar! Man gebe es dem Priester, und er bringe es zum Altar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Vom Speiseopfer nehme der Priester seinen Brandteil und lasse ihn auf dem Altar aufdampfen als ein Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Was vom Speiseopfer übrigbleibt, gehöre Aaron und seinen Söhnen als Hochheiliges von den Mählern für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Wollt ihr dem Herrn ein Speiseopfer bringen, so darf es nicht aus Gesäuertem gemacht werden. Ihr dürft ja keinen Sauerteig und keinen Honig als Mahl für den Herrn aufdampfen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Als des ersten Abhubs Gabe sollt ihr sie dem Herrn darbringen! Aber auf den Altar dürfen sie nicht kommen zu süßem Duft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle deine Speiseopfer sollst du salzen! Nicht sollst du deines Gottesbundes Salz bei deinem Speiseopfer fehlen lassen! Zu all deinen Opfern sollst du Salz bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Bringst du dem Herrn ein Speiseopfer von den Erstlingsfrüchten, dann sollst du Ähren bringen, am Feuer geröstet, frische Graupen als Frühfruchtspeiseopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Tu Öl daran und lege Weihrauch darauf! Ein Speiseopfer ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Der Priester lasse von den Graupen und dem Öl mit seinem ganzen Weihrauch den Brandteil aufdampfen! Ein Mahl ist es für den Herrn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '\"\'Ist seine Opfergabe ein Dankopfer und will er von Rindern sie darbringen, so sei es ein fehlerloses männlich oder weiblich Tier, das man dem Herrn darbringt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Er lege auf den Kopf seiner Opfergabe die Hand und schlachte sie vor der Pforte des Festgezeltes! Die Priester, Aarons Söhne, sollen mit dem Blut den Altar ringsum besprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Dann bringe er von dem Dankopfer dem Herrn ein Mahl, das Fett der Eingeweidedecke sowie alles Eingeweidefett,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'die beiden Nieren und das Fett daran und das an den Lenden und an den Leberlappen! Bei den Nieren soll er es abtrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Die Aaronssöhne sollen es auf dem Brandopferaltar aufdampfen lassen, auf den Holzscheiten im Feuer, als ein Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Kommt aber ein Opfer als Dankopfer für den Herrn vom Kleinvieh her, dann sei es ein fehlerloses männlich oder weiblich Tier, das man darbringt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Will man ein Lamm als Opfer bringen, so bringe man es vor den Herrn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'und lege auf den Kopf seines Opfers die Hand und schlachte es vor dem Festgezelt! Die Aaronssöhne sollen mit dem Blut den Altar ringsum besprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Dann bringe man von dem Dankopfer dem Herrn ein Mahl: das Beste, den ganzen Fettschwanz, - dicht am Schwanzbein trenne man ihn ab! - sowie das Fett der Eingeweidedecke und alles andere Eingeweidefett,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'die beiden Nieren und das Fett daran und das an den Lenden und den Leberlappen! Bei den Nieren trenne man es ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Der Priester lasse es auf dem Altar aufdampfen als Mahl für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ist aber eine Ziege seine Opfergabe, so bringe er sie vor den Herrn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'und lege die Hand auf ihren Kopf und schlachte sie vor dem Festgezelt! Die Aaronssöhne sollen mit dem Blute den Altar ringsum besprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Dann bringe er von seinem Opfer als Mahl für den Herrn das Fett der Eingeweidedecke und alles andere Fingeweidefett,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'die beiden Nieren und das Fett daran und das an den Lenden und an den Leberlappen! Bei den Nieren soll man es abtrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Der Priester lasse es auf dem Altar aufdampfen als Mahl zum süßen Duft! Dem Herrn gehört jedwedes Fett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Für eure Geschlechter in all euren Siedlungen gilt allzeit dies Gebot: Fett und Blut dürft ihr nicht genießen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '\"Sage dies zu den Söhnen Israels, wenn sich jemand unvorsätzlich gegen irgendein Gebot des Herrn verginge in Dingen, die man nicht tun darf, und handelte doch gegen eines von ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Sündigt der gesalbte Priester, wodurch Schuld auch auf das Volk kommt, dann bringe er für seine Sünde, die er getan, einen fehlerlosen jungen Stier dem Herrn zur Entsündigung dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Den Stier bringe er an die Pforte des Festgezeltes vor den Herrn und lege auf den Stierkopf die Hand und schlachte den Stier vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Dann nehme der gesalbte Priester vom Farrenblut und bringe es ins Festgezelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Der Priester tauche seinen Finger in das Blut und sprenge von dem Blut vor den Herrn siebenmal gegen des Heiligtumes Vorhang hin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Und der Priester streiche von dem Blut an die Hörner des Altares für würziges Rauchwerk vor dem Herrn im Festgezelt! Alles andere Farrenblut soll er an den Sockel des Brandopferaltares vor der Tür des Festgezeltes gießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Er soll alles Fett vom Sündopferfarren abheben, das Fett der Eingeweidedecke und das Fett der Eingeweide,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'die beiden Nieren und das Fett daran und das an den Lenden und den Leberlappen! Bei den Nieren soll er es abtrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Wie es abgehoben wird vom Dankopferrinde, so lasse es der Priester auf dem Brandopferaltar aufdampfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Die Haut des Farren, all sein Fleisch samt Kopf und Beinen, Eingeweiden und Mist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'den ganzen Farren schaffe man vor das Lager an einen reinen Ort auf den Aschenhaufen! Dann verbrenne man ihn auf Holzscheiten im Feuer! Auf dem Aschenhaufen werde er verbrannt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Irrt aber die ganze Versammlung Israels und ist es der Gemeinschaft nicht bewußt, daß sie etwas getan, was man nach des Herrn Geboten nicht tun darf, und werden sie so schuldig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'und wird die Sünde erkannt, durch die sie gesündigt, dann bringe die Gemeinschaft einen jungen Stier als Sündopfer dar! Sie bringe ihn vor das Festgezelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Die Ältesten der Gemeinschaft sollen auf den Farrenkopf die Hände vor dem Herrn legen! Dann schlachte man den Farren vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Dann bringe der gesalbte Priester vom Farrenblut ins Festgezelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Der Priester benetze seinen Finger mit dem Blut und sprenge es an den Vorhang vor dem Herrn siebenmal!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Er soll von dem Blute etwas an die Hörner des Altares vor dem Herrn im Festgezelt tun, und alles andere Blut soll er an des Brandopferaltares Sockel vor dem Festgezelt gießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Auch soll er all sein Fett abheben; dann lasse er es auf dem Altare aufdampfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Er tue mit dem Farren, wie er mit dem Sündenopferstier getan hat! So soll er auch mit ihm tun! So entsühne sie der Priester und suche ihnen Vergebung zu erwirken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Den Farren schaffe man vors Lager und verbrenne ihn, wie man den vorigen Farren verbrannt hat! Das ist der Gemeinschaft Sündopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Sündigt ein Fürst und tut unvorsätzlich etwas, was man nach des Herrn, seines Gottes, Geboten nicht tun darf, und wird er schuldig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'und wird ihm seine Sünde, durch die er gesündigt, bewußt, dann bringe er einen fehlerlosen Ziegenbock als ein Opfer dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Er lege auf des Bockes Kopf die Hand und schlachte ihn am Ort, wo man vor dem Herrn das Brandopfer sonst schlachtet! Ein Sündopfer ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Der Priester nehme vom Sündopferblut etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an des Brandopferaltares Sockel soll er sein übriges Blut gießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'All sein Fett soll er auf dem Altar aufdampfen lassen wie das Fett des Dankopfers! So entsühne ihn der Priester von seiner Sünde und suche ihm Verzeihung zu erwirken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Sündigt unvorsätzlich eine einzelne Seele vom Volk des Landes, indem sie etwas tut, was man nach den Geboten des Herrn nicht tun darf, und wird sie schuldig');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'und wird ihr ihre Sünde, die sie getan, bewußt, dann bringe sie eine fehlerlose Ziege dar als Opfer für ihre Sünde, die sie getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Sie lege auf den Kopf des Sündopfers ihre Hand und schlachte an dem Ort des Brandopfers das Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Der Priester nehme von seinem Blute etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an den Sockel des Altares soll er sein Blut ausgießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'All sein Fett soll er wegnehmen, wie man es vom Dankopfer wegnimmt! Der Priester lasse es auf dem Altar aufdampfen zum süßen Duft für den Herrn! So entsühne ihn der Priester und suche ihm Verzeihung zu erlangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Bringt er ein Lamm als Opfergabe für seine Sünde dar, so bringe er ein weibliches, fehlerloses Tier!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Er lege auf des Sündopfers Kopf die Hand und schlachte das Sündopfer an dem Ort, wo man das Brandopfer zu schlachten pflegt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Der Priester nehme von des Sündopfers Blut etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an den Sockel des Altares soll er sein übriges Blut gießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'All sein Fett soll er wegnehmen, wie das Fett des Lammes beim Dankopfer weggenommen wird! Der Priester lasse es aufdampfen auf dem Altar, der sonst für des Herren Mahl bestimmt ist! So entsühne ihn der Priester wegen der vollbrachten Sünde und suche ihm Verzeihung zu erwirken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '\"Sündigt jemand, der ein Fluchwort hört, und könnte er Zeuge sein als Augenzeuge oder als einer, der Beweise liefern kann, macht aber keine Anzeige, so lädt er Schuld auf sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Oder jemand berührt Unreines oder das Aas eines unreinen Wildes oder eines unreinen Haustieres oder das Aas eines unreinen Gewürms, ist sich aber dessen nicht bewußt, so ist er dennoch unrein und schuldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Oder rührt jemand an die Unreinheit eines Menschen, irgendwelche Unreinheit, wodurch man unrein wird, ist sich aber dessen nicht bewußt, so wird er schuldig, wenn er dessen bewußt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Oder jemand schwört recht unbesonnen, er wolle Schlechtes oder Gutes tun, was eben ein Mensch beim Schwören unbesonnen sprechen kann, ist sich aber dessen nicht bewußt, dann wird er an einem davon schuldig, wenn er sich dessen bewußt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Fühlt sich jemand dieser Dinge schuldig, so erkenne er, daß er darin gefehlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'und bringe dem Herrn als Buße für die vollbrachte Sünde zum Sündopfer ein Weibchen vom Kleinvieh, ein Schäfchen oder eine Ziege! So entsühne ihn der Priester von seiner Sünde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Reicht sein Vermögen nicht für ein Schaf hin, dann bringe er zur Buße für seine Sünde dem Herrn ein Paar Turtel- oder junge Tauben, die eine als Sündopfer, die andere als Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Er bringe sie zum Priester! Und dieser bringe an erster Stelle die zum Sündopfer bestimmte dar! Er knicke ihren Kopf dicht vor dem Genick ein, ohne ihn abzutrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Dann sprenge er von dem Blute des Sündopfers etwas an die Altarwand! Der Rest des Blutes aber werde am Altarsockel ausgepreßt! Ein Sündopfer ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Die zweite soll er nach Gebühr fürs Brandopfer herrichten! So entsühne ihn der Priester von seiner Sünde, die er getan, und suche ihm Verzeihung zu erwirken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Reicht sein Vermögen nicht für ein paar Turtel- oder junge Tauben hin, dann bringe er für seine Sünde nur ein Zehntel Scheffel Feinmehl als seine Sündopfergabe dar! Er soll aber kein Öl darauftun noch Weihrauch darüberstreuen! Ein Sündopfer ist es ja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Er bringe es zum Priester! Der Priester nehme davon eine Handvoll als sein Brandteil und lasse es aufgehen auf dem Altar für des Herrn Mähler! Es ist ein Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'So entsühne ihn der Priester wegen seiner Sünde, die er bei einem dieser Anlässe getan, und suche ihm Verzeihung zu erwirken! Dem Priester falle es zu wie das Speiseopfer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '\"Wenn jemand pflichtvergessen handelt und sündigt, so bringe er als seine Buße dem Herrn vom Kleinvieh einen fehlerlosen Widder zur Buße im Wert von zwei Silberringen nach dem Ring des Heiligtums!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Was er am Heiligen gesündigt, muß er zahlen, und er soll ein Fünftel des Betrages darauflegen; dann gebe er es dem Priester! So soll ihn der Priester durch den Schuldopferwidder entsühnen, und er suche ihm Verzeihung zu erlangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Wenn jemand sündigt und tut, was man nach den Geboten des Herrn nicht tun darf, ist sich aber dessen nicht bewußt, dann ist er dennoch schuldig und muß seine Verschuldung tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Er bringe zur Buße vom Kleinvieh einen fehlerlosen Widder nach deiner Schätzung zum Priester! So entsühne ihn der Priester wegen des Versehens, das er unwissentlich tat, und suche ihm Verzeihung zu erwirken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es ist ein Schuldopfer. Er hat sich an dem Herrn verschuldet.\" Und der Herr sprach zu Moses also. \"Jemand sündigt und handelt pflichtvergessen am Herrn, wenn er seinem Volksgenossen Anvertrautes oder ein Darlehen oder einen Diebstahl ableugnet oder seinem Nächsten vorenthält oder das Verlorene findet und verhehlt, und er beschwört eine Lüge, eines von all dem, wodurch ein Mensch sündigen kann. Sündigt er so und ist schuldig, so erstatte er das von ihm Geraubte oder das von ihm Vorenthaltene oder das Anvertraute oder das Verlorene, das er gefunden, oder all das, worüber er falsch geschworen hat! Er erstatte den Betrag; dazu lege er ein Fünftel darauf! Er soll es dem Eigentümer am Tage seines Schuldopfers geben! Als seine Buße soll er dem Herrn einen fehlerlosen Widder bringen, vom Kleinvieh nach deiner Schätzung, für den Priester als Buße! So entsühne ihn der Priester vor dem Herrn und suche ihm Verzeihung zu erwirken für alles, wodurch er sich verschuldet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '\"Gebiete Aaron und seinen Söhnen also: \'Dies ist die Lehre über das Brandopfer, das ist das, was hinaufkommt in seinen Brand die ganze Nacht bis zum Morgen, und das Feuer des Altars werde darauf in Brand erhalten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Der Priester kleide sich in sein Linnenkleid und lege ein Linnenbeinkleid an sein Fleisch und nehme vom Altar die Asche weg, worin das Feuer das Brandopfer verzehrt hat, und lege sie neben den Altar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Dann ziehe er seine Kleider aus und lege andere Kleider an und trage an einen reinen Ort die Asche vor das Lager!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Auf dem Altar brenne unterdessen das Feuer! Es darf nicht verlöschen. Alle Morgen entzünde der Priester darauf Holzscheite und schichte das Brandopfer darauf und lasse darauf die Fettstücke der Dankopfer aufdampfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Auf dem Altar soll stets Feuer brennen und nie verlöschen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Und dies ist die Lehre über das Speiseopfer: Die Aaronssöhne sollen es vor den Herrn an die Vorderseite des Altars bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Dann nehme einer eine Handvoll von dem Feinmehl und von dem Öl des Speiseopfers und allen Weihrauch auf dem Speiseopfer und lasse es auf dem Altar zu süßem Duft als Brandteil für den Herrn verdampfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Sein Übriges soll Aaron samt den Söhnen essen! An heiliger Stätte werde es ungesäuert gegessen. Im Vorhofe des Festgezeltes sollen sie es essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Mit Sauerteig darf es nicht gebacken werden. Als ihren Anteil an meinen Mählern habe ich es bestimmt. Hochheilig ist es, wie das Sünd- und Schuldopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Wer von den Aaronskindern männlich ist, darf es essen. Ewige Gebühr für eure Geschlechter ist es von des Herren Mählern. Wer daran rührt, wird heilig.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '\"Dies sei Aarons und seiner Söhne Opfer, das sie dem Herrn an seinem Salbungsfesttag bringen sollen: ein Zehntel Scheffel feines Mehl als ständiges Speiseopfer, die eine Hälfte davon am Morgen, die andere am Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Auf einer Pfanne werde es mit Öl bereitet! Du sollst es eingerührt darbringen. Als halbgebackenes Bissenspeiseopfer sollst du es dem Herrn zu süßem Dufte darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Auch der Priester, der an seiner Statt aus seinen Söhnen gesalbt wird, soll es bereiten! Als ewige Gebühr lasse man es für den Herrn als Ganzopfer aufdampfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Ganzopfer seien alle Priesterspeiseopfer! Sie dürfen nicht gegessen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '\"Sprich zu Aaron und zu seinen Söhnen: \'Dies ist die Lehre über das Sündopfer: An dem Orte, wo das Brandopfer geschlachtet wird, werde vor dem Herrn das Sündopfer geschlachtet! Es ist hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der es als Sündopfer darbringt, soll es essen! An heiliger Stätte werde es gegessen, im Vorhof des Festgezeltes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Wer sein Fleisch berührt, wird heilig, und spritzt etwas von seinem Blut an ein Kleid, so sollst du das Bespritzte an heiligem Ort waschen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Ein irdenes Gefäß, in dem es gekocht wird, werde zerbrochen, und wird es in einem kupfernen Gefäß gekocht, so werde dies gescheuert und mit Wasser ausgespült!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Wer bei den Priestern männlich ist, darf davon essen. Hochheilig ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Aber nicht gegessen werde irgendein Sündopfer, von dem ein Teil des Blutes in das Festgezelt gebracht wird, um in dem Heiligtum die Sühne zu vollziehen! Im Feuer werde es verbrannt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '\"Und dies ist die Lehre über das Schuldopfer: Es ist hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Am Orte, wo man das Brandopfer schlachtet, soll man auch das Schuldopfer schlachten! Sein Blut soll man an den Altar ringsum sprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Man soll von ihm all sein Fett darbringen, den Fettschwanz und das Fett der Eingeweidedecke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'die beiden Nieren und das Fett daran und das der Lenden und den Leberlappen! Von den Nieren soll man es abtrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Der Priester lasse es auf dem Altare aufdampfen als Mahl für den Herrn! Es ist ein Schuldopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Wer bei den Priestern männlich ist, darf es essen. An heiliger Stätte soll man es verzehren! Es ist hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie das Sündopfer, so das Schuldopfer! Ein Gesetz gilt für beide: Dem Priester, der damit die Sühne vollzieht, soll es zufallen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Dem Priester, der eines anderen Brandopfer darbringt, gehöre die Haut des Brandopfers, das er darbringt! Dem Priester soll sie gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Und jedes Speiseopfer, das im Ofen gebacken wird, und alles, was im Topf und in der Pfanne bereitet wird, soll dem Priester gehören, der es darbringt! Ihm soll es gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Und jedes Speiseopfer, mit Öl bereitet und trocken, soll allen Aaronssöhnen gehören, einem wie dem anderen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies ist die Lehre über die Dankopfer, die man dem Herrn darbringt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Bringt er sie als Dankopfer dar, dann bringe er zu dem Dankopfer noch ungesäuerte, mit Öl bereitete Kuchen und ungesäuerte, mit Öl bestrichene Fladen und feines Mehl zu Kuchen, mit Öl vermengt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Zu Kuchen von gesäuertem Brote soll er sein Opfer bei seinem Lobdankopfer darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Zu jeder Art von Opfer bringe er davon je einen dar als Weihegabe für den Herrn! Dem Priester, der das Blut des Dankopfers aussprengt, soll es gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Das Fleisch des Lobdankopfers soll am Tag seiner Darbringung gegessen werden! Man soll nichts davon bis zum Morgen hinlegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Ist seiner Opfergabe Opfer ein Gelübde oder eine freie Leistung, dann werde es am Tag der Opferung verzehrt! Den Rest davon mag man am Tag darauf essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was vom Opferfleisch noch am dritten Tag übrig ist, werde verbrannt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Wird von dem Fleisch des Dankopfers am dritten Tage gegessen, so gereicht dies dem Darbringer nicht zum Segen; ihm wird es nicht zugerechnet. Es gilt als verdorben, und wer davon genießt, muß seine Schuld tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Das Fleisch, das irgend etwas Unreinem zu nahe kam, werde nicht gegessen! Es ist zu verbrennen. Das Fleisch sonst darf jeder Reine essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Wer Fleisch von einem Dankopfer des Herrn genießt und ist mit Unreinheit behaftet, der werde aus seinem Volke gestrichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Wer etwas Unreines berührt, sei es Unreines an einem Menschen oder an einem unreinen Tier oder ein unreines Gewürm, und ißt vom Fleisch des Dankopfers des Herrn, dieser werde aus seinem Volke gestrichen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '\"Sprich also zu den Söhnen Israels: \'Ihr sollt kein Fett von Rindern, Schafen und Ziegen essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Das Fett gefallener und zerrissener Tiere kann zu allerlei verwendet werden; aber essen dürft ihr es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Jeder, der Tierfett ißt, wie man es dem Herrn als Mahl bringt, wer davon ißt, dieser werde aus seinem Volke gestrichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ihr sollt keinerlei Blut in irgendeiner eurer Siedlungen genießen, nicht von Vögeln und nicht von Vieh!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Wer irgendwie Blut genießt, soll aus seinem Volke gestrichen werden!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und der Herr redete zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '\"Sprich also zu den Söhnen Israels: \'Wer dem Herrn sein Dankopfer bringt, soll von seinem Dankopfer dem Herrn seine Opfergabe bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Seine eigenen Hände sollen des Herrn Mahl darbringen! Er bringe das Fett samt der Brust! Die Brust, um sie als Gabe vor den Herrn zu bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Der Priester lasse das Fett auf dem Altar aufdampfen! Die Brust gehöre Aaron und den Söhnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Die rechte Keule sollt ihr von euren Dankopfern dem Priester als Weihegabe geben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Wer von den Aaronssöhnen Blut und Fett der Dankopfer darbringt, dem soll die rechte Keule als Anteil gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Ich selber habe ja von den Söhnen Israels bei ihren Dankopfern die Brust der Abgabe genommen und die Keule der Weihegabe und sie dem Priester Aaron und seinen Söhnen gegeben als ewige Gebühr von seiten der Israeliten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dies ist der Rechtsteil des Aaron und seiner Söhne an den Mählern des Herrn, seitdem er sie herangezogen hatte, dem Herrn Priesterdienste zu leisten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'hatte doch der Herr am Tage, da man sie salbte, geboten, man solle ihnen dies geben von seiten der Israeliten als ewige Gebühr für ihre Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dies ist die Lehre über das Brandopfer, das Speiseopfer, das Sünd- und Schuldopfer, das Einsetzungsopfer und das Dankopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'die der Herr dem Moses auf dem Berg Sinai geboten, als er den Israeliten befahl, ihre Opfer dem Herrn in der Wüste Sinai darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '\"Nimm Aaron und seine Söhne, die Gewänder und das Salböl, den Sündopferfarren und die beiden Widder sowie den Korb mit Ungesäuertem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Versammle die ganze Gemeinschaft vor der Pforte des Festgezeltes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Da tat Moses, wie ihm der Herr befohlen. Die Gemeinschaft versammelte sich vor der Tür des Festgezeltes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Da sprach Moses zur Gemeinschaft: \"Dies ist es, was der Herr zu tun geboten hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Dann ließ Moses Aaron und seine Söhne herantreten und ließ sie ein Wasserbad nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Er legte ihm den Leibrock an, umgürtete ihn mit dem Gürtel, bekleidete ihn mit dem Obergewand, legte ihm das Schulterkleid an, band ihm die Schulterkleidbinde um und befestigte sie fest daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Dann befestigte er die Tasche daran und legte in die Tasche die Urim und Tummim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Aufs Haupt setzte er ihm den Kopfbund und befestigte vorn am Kopfbund das goldene Blatt, das heilige Diadem, wie es der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Dann nahm Moses das Salböl, salbte die Wohnung und alles darin und weihte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Davon sprengte er siebenmal auf den Altar, salbte den Altar, alle seine Geräte sowie das Becken und sein Gestell, um sie zu weihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Dann goß er vom Salböle auf Aarons Haupt und salbte ihn, um ihn zu weihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'hierauf ließ Moses die Söhne Aarons herantreten, bekleidete sie mit Leibröcken, umgürtete sie mit einem Gürtel und setzte ihnen Mützen auf, wie es der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Er holte dann den Sündopferfarren. Und Aaron mit seinen Söhnen legten die Hände auf den Kopf des Sündopferfarrens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Moses aber schlachtete ihn, nahm das Blut und tat es mit dem Finger ringsum an die Altarhörner und entsündigte den Altar; das übrige Blut aber hatte er an den Altarsockel gegossen. So weihte er den Altar durch Vollzug der Sühnehandlungen daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Dann nahm man alles Eingeweidefett, den Leberlappen und die beiden Nieren mit ihrem Fett. Und Moses ließ es auf dem Altar aufdampfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Den Farren, seine Haut, sein Fleisch und seinen Mist hatte man außerhalb des Lagers verbrannt, wie es der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Dann ließ er den Brandopferwidder bringen, und Aaron mit seinen Söhnen legten die Hände auf den Widderkopf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Moses schlachtete ihn und sprengte das Blut rings um den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Den Widder aber hatte er in seine Rumpfstücke zerlegt. Den Kopf, die Rumpfstücke und den Schmer ließ nun Moses aufdampfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Die Eingeweide aber und die Beine hatte er mit Wasser gewaschen. Dann ließ Moses den ganzen Widder auf dem Altar aufdampfen. Ein Brandopfer von süßem Duft war es, ein Mahl für den Herrn, wie es der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Dann ließ er den anderen Widder bringen, den Einsetzungswidder, und Aaron mit seinen Söhnen legten die Hände auf den Widderkopf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Moses schlachtete ihn, nahm von seinem Blute und tat es an Aarons rechtes Ohrläppchen, an seinen rechten Daumen und seine rechte große Zehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Dann ließ Moses die Aaronssöhne herantreten und tat vom Blute an ihr rechtes Ohrläppchen, ihren rechten Daumen und ihre rechte große Zehe. Das übrige Blut sprengte Moses ringsum an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Er nahm das Fett, den Fettschwanz und alles Eingeweidefett, die Leberlappen, die beiden Nieren mit ihrem Fett und die rechte Keule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Aus dem Korbe mit Ungesäuertem, der vor dem Herrn stand, hatte er einen ungesäuerten Kuchen genommen, einen mit Öl bereiteten Brotkuchen und einen Fladen; dann legte er sie zu den Fettstücken und zu der rechten Keule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Dann gab er alles Aaron und seinen Söhnen in die Hände und weihte es so als Abgabe vor dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Hierauf nahm es Moses ihnen aus den Händen und ließ es auf dem Brandopferaltar aufdampfen. Ein Einsetzungsopfer von süßem Duft, ein Mahl für den Herrn war es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Dann nahm Moses die Brust und brachte sie vor dem Herrn als Abgabe dar. Sie fiel vom Einsetzungswidder Moses als Anteil zu, wie es der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Und Moses nahm vom Salböl und vom Blute auf dem Altar und sprengte es auf Aaron, seine Gewänder, ebenso auf seine Söhne und seiner Söhne Gewänder. So weihte er Aaron und seine Gewänder, ebenso seine Söhne und seiner Söhne Gewänder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Dann sprach Moses zu Aaron und seinen Söhnen: \"Kocht vor des Festgezeltes Pforte das Fleisch! Dort sollt ihr es essen samt dem Brot im Korbe des Weiheopfers, wie mir geboten ward: \'Aaron soll es mit seinen Söhnen essen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was an Fleisch und Brot übrigbleibt, müßt ihr verbrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Nicht weichen sollt ihr sieben Tage von des Festgezeltes Pforte bis zu dem Tage, da eure Weihezeit vorüber ist! Sieben Tage lang soll er euch weihen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Wie man heute getan, so hat der Herr auch weiterhin zu tun geboten, wenn es gilt, euch zu entsühnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Sieben Tage sollt ihr an des Festgezeltes Pforte Tag und Nacht bleiben! Befolgt des Herrn Geheiß, sonst müßt ihr sterben. Denn so ist mir geboten worden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Aaron und seine Söhne taten alles, was der Herr durch Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Am achten Tage berief Moses Aaron und seine Söhne sowie Israels Älteste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Er sprach zu Aaron: \"Nimm dir ein junges Kalb zum Sündopfer und einen Widder zum Brandopfer, beide fehlerlos, und bringe sie vor dem Herrn dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Und zu den Söhnen Israels sollst du folgendes sprechen: \'Holt einen Ziegenbock für das Sündopfer! Ein Kalb und ein Schaf, beide noch nicht jährig und fehlerlos, für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'und ein Rind mit einem Widder für das Dankopf er, zur Schlachtung vor dem Herrn, und ein mit Öl bereitetes Speiseopfer! Denn heute erscheint euch der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Sie holten nun, was Moses verlangt hatte, zum Festgezelt, und die ganze Gemeinschaft kam und trat vor den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Da sprach Moses: \"Was euch der Herr befiehlt, sollt ihr tun, daß euch des Herrn Herrlichkeit erscheine!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Und Moses sprach zu Aaron: \"Tritt an den Altar! Besorge dein Sünd- und Brandopfer und schaffe für dich und für das Volk Sühne! Dann besorge des Volkes Opfergabe und schaffe ihnen Sühne, wie der Herr befohlen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Und Aaron trat an den Altar und schlachtete das Sündopferkalb für sich selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Und Aarons Söhne reichten ihm das Blut. Er tauchte seinen Finger ins Blut und tat es an die Altarhörner. Das übrige Blut aber hatte er an den Altarsockel gegossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Das Fett, die Nieren, die Leberlappen vom Sündopfer hatte er auf dem Altar aufdampfen lassen, wie der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Das Fleisch aber und die Haut hatte er außerhalb des Lagers verbrennen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Dann schlachtete er das Brandopfer. Die Aaronssöhne reichten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Das Brandopfer reichten sie ihm in Stücken samt dem Kopfe. Er ließ es auf dem Altar aufdampfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Die Eingeweide und die Beine wusch er mit Wasser und ließ sie zu dem Brandopfer hin auf dem Altar aufdampfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Dann brachte er das Opfer des Volkes dar. Er nahm den Sündopferbock, der für das Volk war, schlachtete ihn und brachte ihn als Sündopfer dar wie den ersten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Dann brachte er das Brandopfer dar und machte es nach Vorschrift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Hierauf brachte er das Speiseopfer dar. Er nahm davon eine Handvoll und ließ es auf dem Altar aufdampfen, außer dem Morgenbrandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Dann schlachtete er das Rind und den Widder als Dankopfer für das Volk. Die Aaronssöhne reichten ihm das Blut, und er sprengte es ringsum an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Des Rindes Fettstücke und die des Widders, den Fettschwanz, die Decke, die Nieren und den Leberlappen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'die Fettstücke legten sie auf die Bruststücke. Dann ließ er die Fettstücke auf dem Altar aufdampfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Die Bruststücke aber und die rechte Keule brachte Aaron als Abgabe vor dem Herrn dar, wie es Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Dann streckte Aaron die Hand über das Volk und segnete es. Nach Vollzug des Sünd-, des Brand- und des Dankopfers stieg er herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Moses und Aaron traten nun ins Festgezelt. Dann gingen sie hinaus und segneten das Volk. Da erschien des Herrn Majestät dem ganzen Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Feuer aber ging vom Herrn aus und verzehrte auf dem Altar das Brandopfer und die Fettstücke. Alles Volk sah es. Sie jubelten und fielen dabei auf ihr Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Die Aaronssöhne Nadab und Abihu aber nahmen ein jeder seine Kohlenpfanne, taten Feuer hinein, legten Weihrauch darauf und brachten vor den Herrn ein ungehöriges Feuer, das er ihnen nicht geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da ging Feuer von dem Herrn aus und verzehrte sie. So starben sie vor dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sprach Moses zu Aaron: \"Dies ist es, was der Herr sagen will: \'An denen, die mir nahestehen, zeige ich mich als heilig und als herrlich vor dem ganzen Volke.\'\" Aaron aber schwieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Da rief Moses nach Misael und Elsaphan, den Söhnen Uziels, des Oheims von Aaron, und sprach zu ihnen: \"Kommt her und tragt eure Brüder fort vom Heiligtum hinaus vor das Lager!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Da kamen sie her und trugen sie in ihren Leibröcken vor das Lager, wie Moses gesagt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Und Moses sprach zu Aaron, Eleazar und Itamar, seinen Söhnen: \"Löst nicht euer Haupthaar! Zerreißt nicht eure Kleider, daß ihr nicht sterbet! Er würde über die ganze Gemeinschaft ergrimmen, wenn eure Brüder, das ganze Haus Israels, den Brand beweinten, den der Herr gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Weicht nicht von der Pforte des Festgezeltes, daß ihr nicht sterbet! Das Salböl des Herrn ist an euch.\" Sie aber taten nach dem Wort des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Da sprach der Herr zu Aaron:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '\"Trink weder Wein noch Bier, weder du noch deine Söhne, wenn ihr das Festgezelt betretet, daß ihr nicht sterbet! Für eure Geschlechter sei es ewig geltende Vorschrift!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Unterscheidet zwischen Heiligem und Nichtheiligem, Unreinem und Reinem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Unterweiset die Israeliten in all den Gesetzen, die ihnen der Herr durch Moses verkündet hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Moses sprach zu Aaron, Eleazar und Itamar, seinen übriggebliebenen Söhnen: \"Nehmt das Speiseopfer, das von des Herrn Mählern übrig ist, und esset es ungesäuert neben dem Altar! Es ist hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Eßt es an heiliger Stätte! Es ist die Gebühr, die dir mit deinen Söhnen von des Herrn Mählern zufällt. So ist es mir geboten worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Der Abgabe Brust sowie der Weihegabe Keule sollt ihr an reinem Orte essen, du, deine Söhne und deine Töchter! Sie sollen dir und deinen Söhnen von den Dankopfern der Israeliten als Gebühr zufallen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Der Weihegabe Keule und die Brust der Abgabe soll man zu den Mählern der Fettstücke bringen, um sie vor dem Herrn darzubringen! Sie sollen dir und deinen Söhnen, wie der Herr befohlen, als ewige Gebühr zufallen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Moses aber hatte besorgt nach dem Sündopferbock gefragt. Da war er schon verbrannt. Daraufhin zürnte er auf Eleazar und Itamar, Aarons Söhne, und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '\"Warum habt ihr das Sündopfer nicht an heiliger Stätte gegessen? Hochheilig ist es ja. Er hat es euch gegeben, um die Schuld der Gemeinschaft wegzunehmen und für sie vor dem Herrn Sühne zu erwirken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Ist doch sein Blut nicht in das Innere des Heiligtums hineingebracht worden! Darum mußtet ihr es im Heiligtum ganz verzehren, wie es mir geboten ward.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Da sprach Aaron zu Moses: \"Sie haben heute ihr Sünd- und Brandopfer vor dem Herrn dargebracht, und doch traf mich solches. Hätte ich heute ein Sündopfer verzehrt, gefiele dies dem Herrn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Dies hörte Moses, und es war recht vor seinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Der Herr redete mit Moses und Aaron und sagte zu ihnen folgendes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '\"Sprecht zu den Söhnen Israels: \'Dies sind die Tiere, die ihr essen dürft von allem Vieh auf Erden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Was gespaltene Klauen hat, ganz durchgespaltene, und was wiederkäut, das dürft ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Dagegen dürft ihr von den Wiederkäuern nicht die genießen, die gespaltene Klauen haben: das Kamel; denn es hat, wenn auch Wiederkäuer, doch keine ganz gespaltenen Klauen. Unrein sei es euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Auch nicht den Klippdachs; denn er hat, obschon Wiederkäuer, keine ganz gespaltenen Klauen. Unrein sei er euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Auch nicht den Hasen; denn er hat, obschon Wiederkäuer, keine ganz gespaltenen Klauen. Unrein sei er euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Auch nicht das Schwein! Es hat zwar ganz gespaltene Klauen, ist aber kein Wiederkäuer. Unrein sei es euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Ihr dürft ihr Fleisch nicht essen und ihr Aas nicht berühren. Sie seien euch unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Von allem, was im Wasser ist, dürft ihr dies verzehren: Was im Gewässer, in den Meeren und in Bächen Flossen und Schuppen hat, dürft ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Was aber im Meer und in den Bächen weder Flossen noch Schuppen hat von allem, was im Wasser wimmelt, von allen Lebewesen, die im Wasser sind, sei euch ein Greuel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Sie seien euch ein Greuel! Von ihrem Fleische dürft ihr nichts genießen. Ihr Aas müßt ihr verabscheuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Greuel sei euch, was im Wasser keine Flossen und keine Schuppen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Und von den Vögeln sollt ihr folgende verabscheuen! Sie dürfen, als Greuel, nicht gegessen werden: Adler, Bartgeier und Geier,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Weihe und Falken, je in ihrer Art,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'alle Raben, je in ihrer Art;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Strauß, Schwalbe, Möve, Habicht, je in ihrer Art,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Käuzchen und Sturzpelikan, Uhu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Eule und Pelikan, Erdgeier,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Storch, Regenpfeifer, je in ihrer Art, Wiedehopf, Fledermaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Und alles geflügelte Gewimmel, das auf Vieren geht, sei euch ein Greuel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Von allem geflügelten Gewimmel, das auf Vieren geht, dürft ihr nur die verzehren, die über ihren Füßen ein Schenkelpaar haben, um damit auf der Erde zu hüpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von diesen dürft ihr folgende verzehren: Die Heuschrecke in ihrer Art, die Freßheuschrecke in ihrer Art, das Heupferd in seiner Art, die Springheuschrecke in ihrer Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Die anderen kleinen Flügeltiere, die vier Füße haben, seien euch ein Greuel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Durch folgendes könnt ihr euch unrein machen: Wer ihr Aas berührt, bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Wer eines ihrer Äser trägt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Jedes Tier, das Klauen hat, die zwar gespalten, aber nicht ganz durchgespalten sind, und das nicht wiederkäut, gelte euch als unrein! Wer es berührt, wird unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Alles, was auf Tatzen geht, sei euch von allen Vierfüßlern unrein! Wer ihr Aas berührt, bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Wer ihr Aas anfaßt, wasche seine Kleider! Er bleibt bis zum Abend unrein. Sie seien euch unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Die für euch unrein sind, sind folgende von dem Gewimmel, das auf Erden wimmelt: das Wiesel, die Maus und die Eidechsen in ihrer Art,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'die Spitzmaus, das Chamäleon, der Gecko, die Eidechse und der Salamander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese seien euch von allem Gewimmel unrein! Wer sie in ihrem Tod berührt, sei bis zum Abend unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Alles das, worauf von ihnen eines im Tode fällt, wird unrein. Alles Holzgerät oder Gewand oder Fell oder Tuch, all die Gefäße, die zum Gebrauch dienen. Ins Wasser werde es verbracht! Es bleibt bis zum Abend unrein. Dann ist es wieder rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Fällt davon eines in ein irdenes Gefäß, so wird alles, was darin ist, unrein. Ihr müßt es zerschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Alle Speise, an die zum Genießen Wasser kommt, wird unrein, und alles trinkbare Getränk wird in jedem Gefäß unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Alles, worauf eines ihrer Äser fällt, wird unrein. Backofen und Kochherd müssen abgebrochen werden, wenn sie unrein sind. Auch sie seien euch unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Nur Quellen, Brunnen und Wasserbecken bleiben rein. Nur wer ihr Aas berührt, wird unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Fällt eines ihrer Äser auf irgendeinen Samen einer Aussaat, die man säen will, so bleibt er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Bringt man aber Wasser an den Samen und eines ihrer Äser fällt darauf, so sei er euch unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Fällt ein Stück von dem Vieh, das euch zum Essen dient, dann wird bis zum Abend unrein, wer sein Aas berührt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Und wer von seinem Aase ißt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein. Wer sein Aas anfaßt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'All das Gewimmel, das auf Erden wimmelt, ist als Greuel nicht genießbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Was auf dem Bauche kriecht und was auf Vieren geht, bis zu allem Vierfüßigen, von allem Gewimmel, das auf Erden wimmelt, eßt sie nicht! Sie sind ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ihr sollt euch nicht selbst durch irgendein Kriechtier abscheulich machen! Verunreinigt euch nicht durch sie, daß ihr dadurch unrein würdet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich, der Herr, bin euer Gott. Nun, so zeigt euch als heilig und seid heilig! Denn ich bin heilig. Ihr sollt euch nicht selbst durch irgendein Gewimmel verunreinigen, das auf Erden wimmelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Ich bin der Herr, der euch aus Ägypterland geführt, um euch Gott zu sein. So werdet heilig! Denn ich bin heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dies ist die Lehre über das Vieh, das Geflügel und alle Lebewesen, die im Wasser tummeln und alle Wesen, die auf Erden wimmeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'damit man scheide zwischen Unreinem und Reinem und zwischen eßbaren Lebewesen und ungenießbaren Lebewesen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '\"Sprich zu den Söhnen Israels: \'Schenkt ein Weib einem Knaben im Wochenbett das Leben, so ist sie sieben Tage unrein, so wie sie in den Tagen ihrer monatlichen Unreinheit unrein ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Am achten Tage werde seines Gliedes Fleisch beschnitten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Dreiunddreißig Tage soll sie im Reinigungsblute bleiben! Sie darf nichts Heiliges berühren und darf nicht in das Heiligtum kommen, bis daß die Tage ihrer Reinigung vorüber sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Schenkt sie aber einem Mädchen das Leben, so sei sie zwei Wochen unrein wie bei ihrer monatlichen Unreinheit, und sechsundsechzig Tage soll sie im Reinigungsblute bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Sind die Tage ihrer Reinigung vorüber bei einem Sohn oder einer Tochter, so soll sie ein noch nicht einjähriges Lamm zum Brandopfer bringen und eine junge Taube oder eine Turteltaube zum Sündopfer an des Festgezeltes Pforte zu dem Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Er bringe sie vor dem Herrn dar und schaffe ihr Sühne! So werde sie rein von ihrem Blutflusse! Dies ist die Lehre über Kindbetterinnen, sei es bei Knaben oder Mädchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Reicht aber ihr Vermögen nicht für ein Schaf hin, so nehme sie zwei Turteltauben oder sonst zwei junge Tauben, die eine für das Brandopfer, die andere für das Sündopfer, und so verschaffe ihr der Priester Sühne, daß sie rein werde!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Der Herr sprach zu Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '\"Zeigt sich auf jemandes Haut ein Mal oder ein Grind oder ein Fleck und bildet sich auf seiner Haut ein Aussatzschaden, dann bringe man ihn vor den Priester Aaron oder einen seiner Priestersöhne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Sieht nun der Priester den Schaden an der Haut und ist das Haar in dem Schaden weiß geworden und ist der Schein des Schadens tiefer als die Haut seines Fleisches, so ist es Aussatzschaden. Sieht dies der Priester, dann erkläre er ihn für unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ist ein weißer Fleck an der Haut seines Fleisches und ist sein Schein nicht tiefer als die Haut und ist das Haar daran nicht weiß geworden, dann sondere der Priester sieben Tage den Schaden ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Beschaut ihn der Priester am siebten Tage und blieb der Schaden bei seiner Farbe, griff der Schaden auf der Haut nicht weiter um sich, dann sondere der Priester weitere sieben Tage den Schaden ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Beschaut ihn der Priester abermals am siebten Tage und wurde der Schaden blässer und griff der Schaden auf der Haut nicht weiter um sich, dann erkläre ihn der Priester für rein! Ein Grind ist es. Er wasche seine Kleider! Dann ist er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Greift aber auf der Haut der Grind immer weiter um sich, nachdem er vom Priester zu seiner Reinsprechung beschaut war, und zeigt er sich abermals dem Priester');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'und sieht der Priester, daß auf der Haut der Grind um sich griff, dann erkläre der Priester ihn für unrein! Aussatz ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ist an einem Menschen ein Aussatzschaden, so bringe man diesen Fall vor den Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Sieht der Priester, daß ein weißes Mal an der Haut ist, und das Haar daran ist weiß geworden und in dem Mal wuchert wildes Fleisch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'dann ist an der Haut seines Fleisches ein unheilbarer Aussatz. Der Priester erkläre ihn für unrein! Er soll ihn aber nicht absondern! Er ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Blüht aber der Aussatz auf der Haut und bedeckt der Aussatz vom Kopf bis zu den Füßen die ganze Schadenhaut im ganzen Schaubereich des Priesters');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'und sieht der Priester, daß der Aussatz seinen ganzen Leib bedeckt, dann erkläre er den Schaden für rein! Ganz weiß geworden, ist er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Wenn sich aber wildes Fleisch an ihm zeigt, dann wird er unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und sieht der Priester das wilde Fleisch, dann erkläre er ihn für unrein! Das wilde Fleisch ist unrein. Aussatz ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Verschwindet freilich das wilde Fleisch und er wird weiß und kam er zum Priester');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'und besah ihn der Priester und wurde der Schaden weiß, dann erkläre der Priester den Schaden für rein! Er ist rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Ist an der Haut ein Geschwür und heilt es wieder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'und entsteht an Stelle des Geschwüres ein weißes Mal oder ein weißrötliches, ein Fleck, so zeige er sich dem Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Und sieht der Priester, daß die Gestalt des Fleckes tiefer als die Haut ist, und ist daran sein Haar weiß geworden, dann erkläre ihn der Priester für unrein! Aussatzschaden ist es, im Geschwür ausgebrochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Beschaut es der Priester und kein Haar ist daran weiß geworden, auch ist es nicht tiefer als die Haut, nur blasser, dann sondere ihn der Priester sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Greift es dann weiter auf der Haut um sich, dann erkläre ihn der Priester für unrein! Ein Schaden ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Bleibt aber der Fleck an der gleichen Stelle und breitet er sich nicht aus, so ist es die Narbe des Geschwürs. Dann erkläre ihn der Priester für rein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Oder ist eine Brandwunde an der Haut und ist das Fleisch an der Brandwunde ein weißroter oder weißer Fleck');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester beschaut ihn, und das Haar ist an dem Fleck weiß geworden und seine Gestalt ist tiefer als die Haut, so ist der Aussatz in der Brandwunde ausgebrochen. Der Priester erkläre ihn für unrein! Es ist der Aussatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Beschaut ihn der Priester und ist kein weißes Haar am Fleck und ist er nicht tiefer als die Haut, nur blässer, dann sondere ihn der Priester sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Beschaut ihn der Priester am siebten Tag, dann erkläre ihn der Priester für unrein, falls es auf seiner Haut weiter um sich griff! Dann ist es Aussatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Blieb aber der Fleck auf der gleichen Stelle und griff er nicht auf der Haut um sich und ward er nur blässer, so ist es das Mal der Brandwunde. Für rein erkläre ihn der Priester! Nur Brandwundnarbe ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Ist bei einem Manne oder Weib ein Schaden am Kopf oder Bart');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester beschaut den Schaden und ist er tiefer als die Haut und goldgelbes dünnes Haar daran, dann erkläre ihn der Priester für unrein! Krätze ist es, Aussatz des Kopfes oder Bartes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Besichtigt der Priester den Krätzeschaden und ist er nicht tiefer als die Haut, fehlen aber schwarze Haare, dann sondere der Priester den Krätzeschaden sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Besichtigt der Priester am siebten Tag den Schaden und griff die Krätze nicht um sich und war darin kein goldgelbes Haar und ist die Krätze nicht tiefer als die Haut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'So lasse er sich scheren, aber nicht die Krätze! Dann sondere der Priester die Krätze nochmals sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Besichtigt am siebten Tag der Priester die Krätze und griff die Krätze nicht auf der Haut um sich und ist ihre Gestalt nicht tiefer als die Haut, so erkläre ihn der Priester für rein. Er wasche seine Kleider! Dann ist er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Greift aber die Krätze auf der Haut um sich nach seiner Reinerklärung');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und besichtigt ihn der Priester und hat die Krätze weiter auf der Haut um sich gegriffen, so braucht der Priester nicht nach dem goldgelben Haar zu suchen. Er ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Bleibt sich aber die Krätze im Aussehen gleich und wächst schwarzes Haar daran, so ist die Krätze geheilt. Er ist rein. Für rein erkläre ihn der Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Sind bei einem Manne oder Weibe Flecken auf der Haut, mattweiße Flecken');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und bemerkt ein Priester, daß auf der Haut ihres Fleisches verblaßte, weiße Flecken sind, so sind es Flechten, die auf der Haut ausbrachen. Ein solcher ist rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wird jemandes Haupt kahl und ist es ein Hinterglatzkopf, so ist er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Wird aber vorn sein Kopf kahl, so ist es ein Vorderglatzkopf. Er ist rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Zeigt sich aber an der hinteren oder vorderen Glatze ein weißlichroter Schaden, so ist es der Aussatz, der an seiner hinteren oder vorderen Glatze ausbricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Besichtigt ihn der Priester und ist ein weißlichrotes Schadenmal an seiner hinteren oder vorderen Glatze, das aussieht wie der Aussatz auf der Haut des Fleisches,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist er ein aussätziger Mann. Er ist unrein. Der Priester soll ihn für unrein erklären! An seinem Kopfe ist sein Schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Der Aussätzige, der den Schaden an sich hat, soll sein Gewand zerreißen und soll das Haupthaar fliegen lassen, den Bart verhüllen und rufen \"Unrein! Unrein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Er bleibe die ganze Zeit, da er den Schaden hat, unrein! Er soll abgesondert wohnen! Sein Bleiben sei außerhalb des Lagers!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Ist an einem Tuche ein Aussatzschaden, an Woll- oder Leintuch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'oder an Leinen- oder Wollgewebe oder Einschlag, oder auch an Leder oder an Lederware,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und ist der Schaden grünlich oder rötlich am Tuch oder am Leder oder am Gewebe oder am Einschlag oder an der Lederware, so ist es Aussatzschaden. Er werde vom Priester beschaut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Besichtigt der Priester den Schaden, so sondere er den Schaden sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Am siebten Tage beschaue er den Schaden! Hat auf dem Tuche, dem Gewebe, dem Einschlag, dem Leder oder an der Lederware der Schaden um sich gegriffen, dann ist der Schaden ein fressender Aussatz. Er ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Man verbrenne das Tuch oder das Gewebe oder den Einschlag in Wolle oder Leinen oder jede Ledertasche, woran der Schaden ist! Denn fressender Aussatz ist es. Im Feuer soll es verbrannt werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Besichtigt es der Priester, und der Schaden griff nicht um sich auf dem Tuch oder Gewebe oder Einschlag oder auf irgendwelchen Ledersache,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'dann gebiete der Priester, daß man wasche, an denen der Schaden ist, und sondere es nochmals sieben Tage ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Beschaut es dann der Priester, nachdem der Schaden gewaschen wurde, und hat sich die Farbe des Schadens nicht verändert und hat der Schaden nicht um sich gegriffen, so ist es unrein. Im Feuer sollst du es verbrennen, sei es eine Einfressung an seiner hinteren oder vorderen Seite!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Besieht es aber der Priester, und ist der Schaden verblaßt, nachdem man ihn gewaschen hat, so schneide man ihn aus dem Tuche oder Leder oder Aufzug oder Einschlag!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Erscheint er nochmals am Tuch oder Gewebe oder Einschlag oder an irgendeiner Ledersache, so ist es ein frisch ausbrechender. Du sollst im Feuer das verbrennen, woran der Schaden ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Das Tuch, das Gewebe, der Einschlag oder die Lederwaren aller Art, die du wuschest und von denen der Schaden gewichen, müssen wiederum gewaschen werden. Dann erst sind sie rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Dies ist die Lehre über den Aussatzschaden an wollenem oder linnenem Tuch oder an Gewebe oder Einschlag oder irgendeiner Ledersache, inwiefern sie für rein oder unrein zu erklären sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '\"Dies ist das Gesetz über den für aussätzig Erklärten am Tage seiner Reinigung: Man bringe seinen Fall vor den Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Dann gehe der Priester vor das Lager! Beschaut es der Priester und ist der Aussatzschaden am Aussätzigen geheilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'dann gebiete der Priester, daß man für den zu Reinigenden zwei lebende, reine Vögel und Zedernholz und Karmesinwolle und Ysop hole!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Dann gebiete der Priester, daß man den einen Vogel in ein Tongefäß über frischem Wasser schlachte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Den anderen lebendigen Vogel soll er nehmen und das Zedernholz, die Karmesinwolle und den Ysop und tauche sie und den lebendigen Vogel ins Blut des über frischem Wasser abgeschlachteten Vogels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Dann besprenge er den vom Aussatz zu Reinigenden siebenmal und reinige ihn so! Den lebenden Vogel aber lasse er aufs freie Feld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Dann wasche der sich zu Reinigende seine Kleider und schere sein ganzes Haar und bade sich, so wird er rein. Danach darf er ins Lager kommen, bleibe aber noch sieben Tage vor seinem Zelte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Am siebten Tage soll er all sein Haar scheren, seinen Kopf und seinen Bart und seine Augenbrauen! All sein Haar soll er scheren! Dann wasche er seine Kleider und bade seinen Leib! So wird er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Am achten Tage soll er zwei fehlerlose Lämmer nehmen und ein noch nicht einjähriges, fehlerloses, weibliches Lamm sowie drei Zehntel feines Mehl, mit Öl bereitet, für das Speiseopfer und eine Kanne Öl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Der Priester, der reinigt, stelle den Mann, der sich reinigen läßt, und diese Sachen vor den Herrn an des Festgezeltes Tür!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Dann nehme der Priester das eine Lamm und bringe es als Schuldopfer mit der Kanne Öl dar und weihe beides vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Und er schlachte an dem Orte, wo das Sünd- und Brandopfer geschlachtet wird, das Lamm an heiliger Stätte! Dem Priester gehöre das Schuldopfer wie das Sündopfer! Es ist hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Dann nehme der Priester vom Blut des Schuldopfers! Der Priester streiche es dem zu Reinigenden an das rechte Ohrläppchen, an den Daumen seiner rechten Hand und an die große Zehe seines rechten Fußes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Dann nehme der Priester aus der Kanne etwas Öl und gieße es in die priesterliche Linke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Dann tauche der Priester seinen rechten Finger in das Öl in seiner Linken und sprenge vor dem Herrn vom Öl mit seinem Finger siebenmal!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Vom Öl, das auf seiner Hand noch übrigbleibt, soll der Priester dem zu Reinigenden etwas an das rechte Ohrläppchen und an den Daumen seiner rechten Hand streichen und an die große Zehe seines rechten Fußes oben auf das Blut des Schuldopfers!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Was dann noch übrig ist von dem Öle auf der Hand des Priesters, soll er auf das Haupt des zu Reinigenden tun! So schaffe ihm der Priester vor dem Herrn Sühne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Dann richte der Priester das Sündopfer her und schaffe so Sühne dem zu Reinigenden wegen seiner Unreinheit! Danach soll er das Brandopfer schlachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Dann bringe der Priester auf dem Altar das Brand- und das Speiseopfer dar! Schafft ihm so der Priester Sühne, dann wird er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ist er aber arm und unvermöglich, dann nehme er ein Lamm als Schuldopfer zur Darbringung und Sühneschaffung sowie ein Zehntel feines Mehl, mit Öl bereitet, mit einer Kanne Öl für das Speiseopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Sowie zwei Turtel- oder ein Paar junge Tauben, wie er es eben vermag! Die eine sei Sündopfer, die andere Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Er bringe sie am achten Tage nach seiner Reinigung zum Priester an des Festgezeltes Tür vor den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Der Priester nehme mit der Kanne Öl das Lamm des Schuldopfers! Dann bringe der Priester sie vor dem Herrn als Abgabe dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Dann schlachte man das Lamm des Schuldopfers! Der Priester nehme vom Blut des Schuldopfers und streiche es dem zu Reinigenden an das rechte Ohrläppchen und an den Daumen seiner rechten Hand und an die große Zehe seines rechten Fußes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Von dem Öle soll der Priester etwas in die priesterliche Linke gießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Dann sprenge der Priester mit seinem rechten Finger etwas von dem Öl in seiner Linken vor den Herrn siebenmal!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Dann tue der Priester etwas von dem Öl in seiner Hand an des zu Reinigenden rechtes Ohrläppchen und an den Daumen seiner Rechten und an die große Zehe seines rechten Fußes, wo sich das Blut des Schuldopfers befindet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Was vom Öl auf des Priesters Hand noch übrig ist, soll er an des zu Reinigenden Kopf tun! So schaffe er ihm vor dem Herrn Sühne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Dann richte er von den Turteltauben oder jungen Tauben, die er sich leisten kann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'die eine als Sündopfer her, die andere als Brandopfer samt dem Speiseopfer! So schaffe der Priester dem zu Reinigenden Sühne vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das ist die Weisung für den, der den Aussatzschaden hat und der bei seiner Reinigung unvermöglich ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und der Herr redete mit Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '\"Kommt ihr in das Kanaaniterland, das ich euch zu eigen gebe, und schlage ich mit dem Aussatzschaden ein Haus in eurem eigenen Lande,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so komme der Hausbesitzer und melde es dem Priester mit den Worten: \'Wie ein Schaden dünkt es mir am Hause!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Da gebiete der Priester, das Haus zu räumen, bevor der Priester kommt, den Schaden zu besichtigen, damit nicht alles im Haus unrein werde! Dann soll der Priester kommen, das Haus zu besichtigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Besichtigt er den Schaden und ist an den Hauswänden der Schaden in Gestalt von grünen oder roten Grübchen, die tiefer als die Wand zu liegen scheinen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'dann gehe der Priester aus dem Haus an die Haustür und verschließe auf sieben Tage das Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Kommt der Priester am siebten Tag wieder und sieht er, daß der Schaden an den Hauswänden weiter um sich griff,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'dann gebiete der Priester, daß man die Steine, an denen der Schaden ist, ausbreche und draußen vor der Stadt an einen unreinen Ort werfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Dann lasse er das Haus ringsum inwendig abkratzen, und draußen vor der Stadt schütte man den abgekratzten Lehm an einen unreinen Ort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Dann nehme man andere Steine und bringe sie an den Platz jener Steine! Dann soll man anderen Lehm nehmen und das Haus tünchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Kehrt der Schaden am Haus wieder, nachdem jene Steine weggenommen und das abgekratzte Haus getüncht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'dann komme der Priester, und sieht er, daß im Haus der Schaden weiter um sich griff, so ist ein fressender Aussatz am Haus. Es ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Man schleife das Haus mit seinen Steinen und Balken und den gesamten Lehm des Hauses und bringe es hinaus vor die Stadt an einen unreinen Ort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Wer das verschlossene Haus betreten hat, gelte bis zum Abend für unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Wer im Haus geschlafen hat, der soll seine Kleider waschen! Wer im Haus gegessen hat, der soll seine Kleider waschen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Kommt der Priester und besichtigt es und hat der Schaden im Haus nicht um sich gegriffen nach dem Tünchen des Hauses, dann erkläre der Priester das Haus für rein! Der Schaden ist geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Zwei Vögel nehme er zur Entsündigung des Hauses und Zedernholz und Karmesinwolle mit Ysop!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Dann schlachte er den einen Vogel in ein Tongefäß über frischem Wasser');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'und nehme das Zedernholz, den Ysop, die Karmesinwolle und den lebenden Vogel, tauche sie in das Blut des geschlachteten Vogels und in das frische Wasser und besprenge siebenmal das Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'So entsündigt er das Haus mit Vogelblut und frischem Wasser, mit dem lebenden Vogel, dem Zedernholz, dem Ysop und der Karmesinwolle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Dann lasse er den lebenden Vogel vor die Stadt ins freie Feld entkommen! So schaffe er dem Hause Sühne! Dann ist es rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Das ist die Weisung für die verschiedenen Arten des Aussatzschadens und der Krätze,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'des Aussatzes an Tüchern und Häusern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'der Hautmale, des Schorfes und der Flecken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'um danach zwischen Rein oder Unrein zu entscheiden. Dies ist das Gesetz über den Aussatz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und der Herr sprach zu Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '\"Redet mit den Söhnen Israels und sprecht zu ihnen: Wer einen Fluß an seinem Fleische hat, dessen Ausfluß ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Dies ist eine Unreinheit durch seinen Fluß: Mag sein Fleisch seinen Fluß ausscheiden oder mag sein Fleisch so verstopft sein, daß nichts fließt, bei ihm ist es Unreinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Das ganze Lager, auf dem der Flüssige liegt, ist unrein, ebenso alles Gerät, auf dem er sitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Wer sein Lager anrührt, soll seine Kleider waschen, dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Wer sich auf das Gerät setzt, auf dem der Flüssige saß, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Wer das Fleisch des Flüssigen berührt, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Speit der Flüssige auf den Reinen, so wasche dieser seine Kleider und bade sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Alles Reitzeug, auf dem der Flüssige reitet, ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Wer etwas, was unter ihm war, anrührt, bleibt bis zum Abend unrein. Wer es fortträgt, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Wen der Flüssige mit ungewaschenen Händen berührt, der wasche seine Kleider und bade sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Ein Tongefäß, das der Flüssige berührt, werde zerbrochen und alles Holzgerät mit Wasser abgespült!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Wird der Flüssige rein von seinem Fluß, dann zähle er von seinem Reinwerden sieben Tage! Dann wasche er seine Kleider und bade sein Fleisch in frischem Wasser! Dann ist er rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Am achten Tage soll er zwei Turtel- oder junge Tauben nehmen; dann komme er an des Festgezeltes Pforte vor den Herrn und gebe sie dem Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Der Priester richte sie her, die eine als Sündopfer, die andere als Brandopfer! So schaffe ihm der Priester wegen seines Flusses Sühne vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Entgeht einem Mann der Same, so bade er seinen ganzen Leib! Er bleibt bis zum Abend unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und jedes Tuch und jedes Lederzeug, an die Samen kommt, werde gewaschen! Bis zum Abend bleibt es unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und schläft jemand bei einem Weibe, daß Samenfluß erfolgt, so müssen sie sich baden und sind bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Wird ein Weib durch seines Leibes Blutfluß flüssig, so haftet sieben Tage an ihr die Unreinheit. Wer sie berührt, wird bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Alles, worauf sie während ihrer Unreinheit liegt, und alles, worauf sie sitzt, wird unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Wer ihr Lager anrührt, der soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Wer irgendein Gerät berührt, auf dem sie saß, der soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Wer auf dem Lager oder dem Gerät, auf dem sie saß, etwas berührt, wird bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Wenn einer bei ihr liegt, kommt er in ihre Unreinheit und bleibt sieben Tage unrein. Das ganze Lager, auf dem er liegt, wird unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Fließt eines Weibes Blutfluß viele Tage außer der Zeit ihrer gewöhnlichen Unreinheit, oder wenn sie über ihre Unreinheit hinaus noch flüssig bleibt, so gelten alle Tage des Flusses ihrer Unreinheit als Tage ihrer Unreinheit. Sie ist unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Das ganze Lager, auf dem sie alle Tage ihres Flusses sitzt, gelte ihr wie das Lager ihrer gewöhnlichen Unreinheit, und alles Gerät, auf dem sie sitzt, wird unrein, wie bei ihrer gewöhnlichen Unreinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Und unrein wird jeder, der diese Dinge berührt. Er wasche seine Kleider und bade sich! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Ist sie aber von ihrem Flusse rein geworden, so zähle sie noch sieben Tage! Dann ist sie rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Am achten Tage soll sie zwei Turtel- oder junge Tauben nehmen; dann bringe sie diese zum Priester an des Festgezeltes Pforte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Der Priester richte die eine als Sündopfer her, die andere als Brandopfer! Und so verschaffe der Priester ihr vor dem Herrn Sühne, des Flusses wegen, der sie unrein machte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ihr sollt die Söhne Israels ob ihrer Unreinheit verwarnen, auf daß sie nicht durch ihre Unreinheit sterben, indem sie meine Wohnung in ihrer Mitte unrein machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Das ist das Gesetz über den Flüssigen und den, dem der Same entgeht, wodurch er unrein wird,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und über die, die an ihrer Unreinigkeit leidet, und über den, der seinen Fluß hat, über Männer wie über Weiber, und über den, der bei einer Unreinen liegt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und der Herr redete zu Moses nach dem Tode der beiden Aaronssöhne, als sie dem Herrn zu nahe traten und sterben mußten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Der Herr sprach zu Moses: \"Sag deinem Bruder Aaron, er dürfe nicht zu jeder Zeit ins Heiligtum und hinter den Vorhang vor der Lade Deckplatte kommen, sonst müsse er sterben! Denn in der Wolke erscheine ich über der Deckplatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Nur so soll Aaron ins Heiligtum kommen, daß er einen jungen Stier als Sündopfer darbringt und einen Widder als Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Er soll einen heiligen Linnenleibrock anziehen! Über seinem Fleisch sollen linnene Beinkleider sein! Er soll sich mit einem Linnengürtel gürten und einen Linnenkopfbund umbinden! Dies sind heilige Gewänder. Darum wasche er sein Fleisch! Dann ziehe er sie an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Und von der israelitischen Gemeinschaft soll er zwei Ziegenböcke zum Sündopfer nehmen und einen Widder zum Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Alsdann hole Aaron seinen Sündopferfarren und schaffe so sich und seinem Hause Sühne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Dann nehme er die beiden Böcke und stelle sie an des Festgezeltes Tür vor den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Und Aaron lege die Lose auf die beiden Böcke! Ein Los gelte für den Herrn, ein Los für Azazel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Dann nehme Aaron jenen Bock, auf den das Los gefallen \'Für den Herrn\', und bereite ihn als Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Den Bock, auf den das Los gefallen \'Für Azazel\', soll er lebend vor den Herrn stellen, um an ihm die Sühne zu vollziehen und ihn dem Azazel in die Wüste zuzuschicken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Aaron bringe seinen Sündopferfarren her und schaffe sich und seinem Hause Sühne! Er schlachte seinen Sündopferfarren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Dann nehme er die Pfanne voller Feuerkohlen vom Altare vor dem Herrn weg und zwei Hände feines, würziges Räucherwerk und bringe es hinter jenen Vorhang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Dann tue er das Räucherwerk aufs Feuer vor dem Herrn und hülle mit der Räucherwerkwolke die Deckplatte auf dem Zeugnis ein, daß er nicht sterbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Dann nehme er vom Farrenblut und sprenge es mit seinem Finger an die Vorderseite der Deckplatte! Vor die Deckplatte soll er siebenmal von dem Blute mit seinem Finger sprengen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Dann schlachte er des Volkes Sündopferbock und bringe sein Blut hinter jenen Vorhang und tue mit seinem Blute so wie mit dem Farrenblut und sprenge es auf die Deckplatte und vor sie hin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'So entsündige er das Heiligtum, wegen der Unreinheiten der Söhne Israels und wegen ihrer Frevel bei all ihren Sünden. So soll er mit dem Festgezelte dessen tun, der bei ihnen wohnt inmitten ihrer Unreinheit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Im Festgezelt darf aber niemand sein, wenn er kommt, im Heiligtum die Sühnebräuche zu tun, bis zu seinem Austritt. So schaffe er sich und seinem Hause und der Gesamtgemeinde Israels Sühne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Dann gehe er hinaus zum Altar, der vor dem Herrn ist, und entsündige ihn! Er nehme vom Farrenblut und vom Bocksblut und bringe dieses an die Altarhörner ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Er sprenge auf ihn vom Blute mit seinem Finger siebenmal! So reinige und heilige er ihn von den Unreinheiten der Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Und hat er die Entsündigung des Heiligtums, des Festgezeltes und des Altares vollendet, dann bringe er den lebenden Bock herbei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Und Aaron lege seine beiden Hände auf den Kopf des lebenden Bockes und bekenne über ihm die Schuld all der Söhne Israels und alle ihre Frevel bei all ihren Sünden und lege sie auf den Kopf des Bockes und lasse ihn durch einen blöden Menschen in die Wüste führen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'So trage der Bock auf sich all ihre Schuld in eine abgelegene Gegend fort! In die Wüste treibe er den Bock hinaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Aaron aber komme wieder zum Festgezelt! Hernach ziehe er die Linnenkleider aus, die er sich angelegt, als er das Heiligtum betreten, und lege sie dort nieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Dann wasche er an heiligem Ort sein Fleisch mit Wasser, ziehe seine Kleider an, gehe hinaus und richte sein und des Volkes Brandopfer her! So schaffe er sich und dem Volke Sühne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Des Sündopfers Fett soll er auf dem Altar aufdampfen lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Wer aber den Bock zu Azazel hinausschafft, soll seine Kleider waschen; dann bade er sein Fleisch in Wasser! Dann darf er ins Lager kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Sündopferfarren und den Sündopferbock, deren Blut man hineinbrachte, um im Heiligtum die Sühnebräuche zu tun, soll man vor das Lager bringen, und hier verbrenne man ihre Haut, ihr Fleisch und ihren Mist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Wer sie verbrennt, soll seine Kleider waschen; dann bade er sein Fleisch in Wasser! Alsdann darf er ins Lager kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'So sei es euch zu ewiger Satzung: Am zehnten Tag des siebten Monats sollt ihr euch kasteien und keine Arbeit tun, weder der Eingeborene noch der Fremdling, der bei euch weilt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage schafft man euch zu eurer Reinigung Sühne. Von all euren Sünden sollt ihr euch vor dem Herrn reinigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein Tag völliger Ruhe sei es für euch, und kasteit euch kraft ewiger Satzung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Und die Entsündigung vollziehe der Priester, der gesalbt und eingekleidet ward, um Priesterdienst an seines Vaters Statt zu tun! Er lege die linnenen Gewänder an, die Kleider für das Allerheiligste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Und er entsündige das Allerheiligste, das Festgezelt und den Altar! So soll er den Priestern und der ganzen Volksgemeinde Sühne schaffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Dies sei euch ewige Satzung, daß man den Söhnen Israels von allen ihren Sünden einmal im Jahre Sühne schaffe!\" Und er tat, wie der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '\"Rede mit Aaron, seinen Söhnen und mit allen Söhnen Israels und sprich zu ihnen: \'Dies ist es, was der Herr gebietet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Jeder vom Hause Israel, der ein Rind, ein Lamm oder eine Ziege im Lager schlachtet oder außerhalb des Lagers schlachtet');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'und sie nicht an des Festgezeltes Pforte bringt, um vor des Herrn Wohnung sie dem Herrn als Opfergabe darzubringen, dem werde es als Blutschuld angerechnet, hat er doch Blut vergossen! Dieser Mann werde aus seinem Volke gestrichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'auf daß die Israeliten ihre Schlachtopfer, die sie auf freiem Feld schlachteten, zum Priester an des Festgezeltes Pforte dem Herrn bringen und sie als Dankopfer dem Herrn schlachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Der Priester besprenge mit dem Blut den Altar an des Festgezeltes Pforte und lasse das Fett aufdampfen zu süßem Duft für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Sie sollen aber ihre Schlachtopfer nicht mehr den Bocksgestalten opfern, denen sie nachhuren! Dies sei ihnen ewige Satzung in ihren Geschlechtern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und du sollst ihnen sagen: \'Wer vom Hause Israel und von den Fremden, die in seiner Mitte weilen, Brand- oder Schlachtopfer darbringt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und es nicht vor des Festgezeltes Pforte bringt, es für den Herrn zu bereiten, ein solcher werde aus seinem Volke gestrichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und gegen jeden vom Hause Israel und von den Fremdlingen bei ihnen, der irgend Blut genießt, will ich mein Antlitz richten und ihn aus seinem Volke streichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Des Fleisches Leben ist im Blute. Für den Altar habe ich es euch gegeben, um euch selbst Sühne zu schaffen. Denn Blut schafft Sühne durch das Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum sage ich zu den Söhnen Israels: Von euch darf niemand Blut genießen, auch nicht der Fremde unter euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und jeder Israelit und jeder ihrer Fremdlinge, der sich ein Wild erlegt oder eßbares Geflügel, lasse sein Blut auslaufen und bedecke es mit Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn jedes Fleisches Leben ist sein Blut kraft seines Lebensodems. Darum sage ich zu den Söhnen Israels: Von keinem Fleische dürft ihr das Blut genießen. Denn jedes Fleisches Leben ist sein Blut. Jeder werde ausgestrichen, der es genießt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und jegliche Person, die Gefallenes oder Zerrissenes ißt, Eingeborener oder Fremdling, wasche ihre Kleider und bade sich in Wasser! Er bleibt bis zum Abend unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wäscht er nicht und badet er nicht seinen Leib, dann zieht er sich Schuld zu.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '\"Rede mit den Söhnen Israels und sprich zu ihnen: \'Ich, der Herr, bin euer Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr sollt nicht nach dem Treiben des Ägypterlandes tun, in dem ihr gesessen, und nicht nach dem Treiben des Landes Kanaan, in das ich euch bringe! Ihr sollt nicht nach ihren Satzungen wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Meine Satzungen sollt ihr befolgen und meine Vorschriften halten, danach zu wandeln! Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Wahret meine Vorschriften und Satzungen! Wer sie tut, wird durch sie leben. Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Niemand soll sich seinen nächsten Blutsverwandten nahen, die Blöße zu enthüllen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Die Blöße deines Vaters und deiner Mutter darfst du nicht enthüllen. Deine Mutter ist es. Du darfst nicht ihre Blöße enthüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Die Blöße deines Vaterweibes darfst du nicht enthüllen. Deines Vaters Blöße ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Die Blöße deiner Schwester, deines Vaters Tochter oder deiner Mutter Tochter, daheim geboren oder auswärts, darfst du nicht enthüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Die Blöße deiner Sohnestochter oder deiner Tochtertochter darfst du nicht enthüllen. Sie sind deine Blöße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Die Blöße der Tochter eines Weibes deines Vaters, als deinem Vater geboren, darfst du nicht enthüllen. Sie ist deine Schwester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Die Blöße der Schwester deines Vaters darfst du nicht enthüllen. Sie ist deines Vaters Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Die Blöße der Schwester deiner Mutter darfst du nicht enthüllen. Sie ist deiner Mutter Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Die Blöße deines Vaterbruders darfst du nicht enthüllen, noch nahe dich seinem Weib! Sie ist deine Tante.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Die Blöße deiner Schwiegertochter darfst du nicht enthüllen. Sie ist deines Sohnes Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Die Blöße deines Brudersweibes darfst du nicht enthüllen. Sie ist deines Bruders Blöße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Die Blöße eines Weibes und seiner Tochter darfst du nicht enthüllen. Die Tochter ihres Sohnes und die Tochter ihrer Tochter darfst du nicht nehmen, ihre Blöße zu enthüllen. Sie sind nächste Blutsverwandte. Unzucht ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du darfst nicht ein Weib zu seiner Schwester hinzunehmen als Nebenweib, um neben ihm zu seinen Lebzeiten ihre Blöße zu enthüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du darfst dich nicht einem Weib zur Zeit der Unreinheit nahen, ihre Scham zu enthüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Mit dem Weibe eines anderen aus deinem Volke darfst du keinen Beischlaf haben, auf daß du dich dadurch nicht unrein machst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Von deinen Nachkommen darfst du keinen hergeben zur Weihe an den Moloch. Du darfst nicht Gottes Namen entweihen. Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Einem Manne darfst du nicht beiliegen wie einem Weibe. Ein Greuel ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du darfst dich nicht fleischlich mit einem Tiere vermischen, dich dadurch unrein zu machen. Nicht darf sich ein Weib vor ein Tier hinstellen, sich zu paaren. Schwere Schandtat ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Versündigt euch nicht durch derartiges! Denn durch all das haben sich die Heiden versündigt, die ich vor euch vertreibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Das Land ward unrein, und ich suchte seine Missetaten an ihm heim. Und das Land spie seine Einwohner darum aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'So haltet meine Vorschriften und Satzungen! Ihr dürft nichts von all diesen Greueln tun, weder Eingeborene noch Fremde, die bei euch weilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Denn alle diese Greuel haben im Lande die Leute getan, die vor euch waren, und das Land ward dadurch unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Daß nicht das Land euch ausspeie, wenn ihr es verunreinigt, wie es das Volk ausgespieen hat, das vor euch war!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Wer einen dieser Greuel tut, ausgestrichen müssen aus dem Volke Leute werden, die solches tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'So folgt meiner Anordnung, daß ihr keine dieser Greuelsitten, die vor euch getan worden sind, übet und euch dadurch unrein machet! Ich, der Herr, bin ja euer Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und der Herr redete mit Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '\"Rede mit der ganzen Gemeinschaft der Söhne Israels und sprich zu ihr: \'Seid heilig! Denn heilig bin ich, der Herr, euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ihr sollt jeder seine Mutter und seinen Vater fürchten und meine Ruhetage beobachten. Ich, der Herr, bin euer Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Wendet euch nicht den Götzen zu! Ihr sollt euch keine gegossenen Götter machen! Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und schlachtet ihr dem Herrn ein Dankopfer, so sollt ihr es zu eurer Begnadigung opfern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Am Tage, da ihr es darbringt, und am Tage darauf muß es gegessen werden. Was bis zum dritten Tage übrigbleibt, soll verbrannt werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Würde es am dritten Tage gegessen, so wäre es Verdorbenes, das nicht zu Gnaden geachtet wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Wer es genießt, lädt Schuld auf sich. Denn er entheiligt das dem Herrn Geweihte. Aus seinem Volke werde diese Seele gestrichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn ihr euer Land aberntet, dann darfst du dein Feld nicht bis zum letzten Rande abernten. Du sollst nicht nach deiner Ernte Nachlese halten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Auch deinen Weinberg sollst du nicht nachlesen! Du sollst in deinem Weinberge nicht die zerstreuten Beeren auflesen! Du sollst sie dem Armen und dem Fremdling überlassen! Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen! Ihr sollt nicht hehlen! Ihr sollt einander nicht betrügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt nicht bei meinem Namen falsch schwören, daß du den Namen deines Gottes entweihest! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst nicht deinen Nächsten drücken! Du sollst nicht rauben! Nicht soll bei dir des Lohnarbeiters Lohn bis zum Morgen nächtigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst nicht einem Tauben fluchen! Du sollst nicht vor den Blinden einen Anstoß legen! Fürchte dich vor deinem Gott! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt keine Verdrehung beim Rechtsprechen machen! Du sollst nicht den Niederen abweisen! Du sollst nicht auf einen Großen Rücksicht nehmen! Du sollst deinen Nächsten recht richten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst nicht als Ohrenbläser beim Volk umhergehen! Du sollst nicht dem Blute deines Nächsten nachstellen! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst nicht deinen Bruder in deinem Herzen hassen! Mit Freimut sollst du den Angehörigen deines Volkes zurechtweisen und nicht seinetwegen Schuld auf dich laden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst nicht rachgierig sein und nicht deines Volkes Söhnen grollen! Liebe deinen Nächsten wie einen deinesgleichen! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Ihr sollt meine Satzungen beobachten! Du sollst nicht zweiartig dein Vieh paaren! Du sollst nicht zweiartig dein Feld besäen! Nicht soll an dich ein Kleid, zweiartig gewebt, kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wohnt ein Mann einem Weibe bei und sie ist als Sklavin mit einem anderen Manne verbunden, ist aber noch nicht losgekauft oder noch nicht freigelassen, so soll man eine Unterscheidung machen! Sie soll nicht den Tod erleiden, weil sie keine Freigelassene war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Er aber bringe dem Herrn als Buße an des Festgezeltes Pforte zum Schuldopfer einen Widder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Der Priester schaffe ihm vor dem Herrn durch den Schuldopferwidder Sühne wegen seiner Sünde, die er getan, und suche ihm Verzeihung zu erwirken von seiner Sünde, die er tat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Kommt ihr in das Land, dann pflanzt allerlei Fruchtbäume, aber scheuet das, was daran zu scheuen ist, ihre Frucht! Drei Jahre sollt ihr sie scheuen! Sie darf nicht gegessen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahre sei all ihre Frucht heilig, dem Herrn geweiht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Im fünften Jahr dürft ihr ihre Früchte genießen, daß ihre Ernte euer Gut mehre. Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr sollt nichts mit Blut essen! Ihr sollt nicht wahrsagen! Ihr sollt nicht zaubern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt nicht eures Haupthaares Ecken runden! Du sollst nicht deines Bartes Ecken verderben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ihr sollt euch nicht wegen einer Leiche an eurem Leibe ritzen. Ihr sollt keine Schriftzeichen euch einätzen! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Entweihe deine Tochter nicht, daß du sie zur Unzucht führst, auf daß nicht das Land unzüchtig werde und sich das Land mit grober Unzucht fülle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Ihr sollt meine Ruhetage halten! Ihr sollt vor meinem Heiligtum Ehrfurcht haben! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Wendet euch nicht an die Totengeister! Befragt nicht die Wahrsagegeister, daß ihr dadurch unrein würdet! Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem grauen Haupte sollst du aufstehen! Ehre die Person des Greises! Fürchte dich vor deinem Gott! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Weilt in eurem Lande bei euch ein Fremder, dann dürft ihr ihn nicht drücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Der Fremdling soll euch sein wie ein Eingeborener aus euch! Liebe ihn wie deinesgleichen! Ihr seid Fremdlinge im Lande Ägypten gewesen. Ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt keine Verdrehung beim Rechtsprechen, beim Längenmaß, Gewicht und Gefäß machen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Richtige Waage, richtige Gewichtsteine, richtiger Scheffel und richtige Kanne sollen bei euch sein! Ich, der Herr, bin euer Gott, der euch aus Ägypterland geführt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'So beachtet alle Vorschriften und Satzungen und erfüllet sie, bin ich doch der Herr!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '\"Sprich zu den Söhnen Israels: Wer aus den Söhnen Israels und aus den Fremdlingen in Israel von seinen Kindern eines dem Moloch gibt, soll den Tod erleiden! Das Volk des Landes soll ihn steinigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Ich selber richte mein Antlitz wider diesen Mann und streiche ihn aus seinem Volke, weil er von seinen Kindern eines dem Moloch gibt und so mein Heiligtum unrein macht und meinen heiligen Namen entweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wollte vor einem solchen Manne das Volk des Landes seine Augen schließen, wenn er von seinen Kindern eines dem Moloch gibt, und wollten sie ihn nicht töten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'dann richte ich mein Antlitz gegen einen solchen Mann und seine Sippe. Ich streiche ihn aus seinem Volke, ihn samt allen, die ihm in Unzucht mit dem Moloch nachfolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Und gegen die Person, die sich an Toten- und an Wahrsagegeister wendet, ihnen nachzuhuren, richte ich mein Angesicht und streiche sie aus ihrem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Zeigt euch als heilig, daß ihr heilig werdet! Ich bin der Herr, euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Beachtet und befolget meine Satzungen! Ich bin der, der euch heiligt, ich, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Wer Vater und Mutter grob beleidigt, soll den Tod erleiden! Weil er Vater und Mutter grob beleidigt, bleibt seine Blutschuld auf ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Buhlt ein Mann mit eines anderen Mannes Weib, buhlt ein Mann mit seines Nächsten Weib, so leide der Ehebrecher und die Ehebrecherin den Tod!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Liegt jemand bei dem Weibe seines Vaters, hat er des Vaters Blöße enthüllt, so sollen beide den Tod leiden, und ihre Blutschuld bleibt bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Liegt jemand bei der eigenen Schwiegertochter, so sollen beide den Tod leiden. Sie haben eine schwere Schandtat ausgeübt, und ihre Blutschuld bleibt bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Liegt jemand bei einem Manne, wie man bei einem Weibe liegt, so haben beide eine Greueltat getan. Den Tod sollen sie leiden, und ihre Blutschuld bleibt bei ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Nimmt jemand ein Weib und ihre Mutter dazu, so ist dies grobe Unzucht. Man soll ihn und sie verbrennen, auf daß nicht Unzucht unter euch im Schwange seil');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Wer sich mit einem Tiere vermischt, soll den Tod leiden! Auch das Tier sollt ihr umbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Naht sich ein Weib einem Tiere, sich mit ihm zu paaren, so töte Weib und Tier! Den Tod sollen sie leiden, und ihre Blutschuld bleibt bei ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Nimmt jemand seines Vaters Tochter oder seiner Mutter Tochter, seine Schwester, und schaut er ihre Blöße und sie schaut seine Blöße, so ist dies Verruchtheit. Sie sollen angesichts ihres Volkes ausgestrichen werden, hat er doch die Blöße seiner Schwester enthüllt; er lädt Schuld auf sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Liegt jemand bei einem Weibe in ihrem Unwohlsein und enthüllt er ihre Blöße und deckt er ihren Quell auf und enthüllt sie den Quell ihrer Blutungen, so sollen beide aus ihrem Volke gestrichen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Enthülle nicht die Blöße deiner Mutterschwester noch der Vaterschwester! Wer seine eigenen Verwandten entblößt, ihre Schuld sollen sie büßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Liegt jemand bei der Tante, so hat er seines Oheims Blöße enthüllt. Sie laden ihre Schuld auf sich. Kinderlos werden sie sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Nimmt jemand seines Bruders Weib, so ist es Blutschande. Er hat seines Bruders Blöße enthüllt. Kinderlos werden sie bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Haltet alle meine Vorschriften und Satzungen! Tut sie, daß euch das Land nicht ausspeie, in das ich euch bringe, darin zu siedeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ihr sollt nicht nach den Satzungen der Heiden wandeln, die ich vor euch vertreibe! Denn all das haben sie getan, daß es mich vor ihnen ekelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Ich sprach zu euch: Ihr sollt ihr Land zu eigen haben. Ich gebe es euch zum Besitz, ein Land, von Milch und Honig fließend. Ich, der Herr, bin euer Gott, der euch von den anderen Völkern gesondert hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So scheidet zwischen reinem und unreinem Vieh, reinem und unreinem Geflügel! Ihr sollt euch selbst nicht abscheulich machen durch das Vieh, das Geflügel oder durch das, was auf dem Boden kriecht und was ich für euch als unrein ausgesondert habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Seid mir heilig! Denn ich, der Herr, bin heilig. Ich sondere euch von den Völkern, daß ihr mein seiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Ist in einem Mann oder Weib ein Toten- oder Wahrsagegeist, so sollen sie den Tod leiden! Man soll sie steinigen! Ihre Blutschuld bleibt bei ihnen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und der Herr sprach zu Moses: \"Sprich zu den Priestern, zu den Söhnen Aarons, sage ihnen: \'An keiner Leiche aus seiner Verwandtschaft darf er sich unrein machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Nur an den nächsten Blutsverwandten, an seiner Mutter, seinem Vater, seinem Sohn, seiner Tochter, seinem Bruder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'und an seiner jungfräulichen Schwester, die ihm nahesteht und die noch keines Mannes ist, darf er sich unrein machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Er darf sich nicht als Gatte an seinen anderen Verwandten unrein machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen auf ihrem Kopf keine Glatze machen, nicht ihres Bartes Rand scheren und in ihr Fleisch keine Einschnitte machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Heilig seien sie ihrem Gott und sie sollen ihres Gottes Namen nicht entweihen! Sie bringen ja die Mähler für den Herrn, die Speise ihres Gottes, dar. Deswegen seien sie heilig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Sie dürfen keine Dirne noch eine Vergewaltigte heiraten, noch ein von seinem Manne verstoßenes Weib. Denn heilig ist er seinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Heilig halte ihn! Er bringt deines Gottes Speise dar. Heilig sei er dir! Denn heilig bin ich, der Herr, der euch heiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Entweiht sich eine Priestertochter durch Hurerei, so entweiht sie ihren Vater. Im Feuer werde sie verbrannt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Der Hohepriester unter seinen Brüdern, auf dessen Haupt das Salböl ausgegossen und der eingekleidet ward durch Anlegen der Gewänder, lasse nie sein Haupthaar offen fliegen! Nicht soll er seine Kleider zerreißen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Er soll zu keiner Leiche gehen! Selbst nicht des Vaters oder der Mutter wegen darf er sich unrein machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Er soll nicht aus dem Heiligtum gehen und nicht seines Gottes Heiligtum entweihen! Die Weihe durch seines Gottes Ölsalbung ruht auf ihm. Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Er soll eine Jungfrau heiraten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Er soll keine Witwe nehmen, noch Verstoßene, noch Vergewaltigte, noch Dirne, sondern eine Jungfrau aus der Verwandtschaft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'daß er nicht durch seine Verwandten seinen Stamm entweihe! Denn ich, der Herr, bin es, der ihn heiligt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '\"Sprich so zu Aaron: \'Hat einer aus deinem Stamme ein Gebrest, dann darf er nicht herantreten, Speise seinem Gott darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Denn niemand darf herantreten, der ein Gebrest hat, kein Blinder oder Lahmer oder Entstellter oder Überlanger,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'oder wer einen Beinbruch hat oder einen Armbruch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'oder ein Buckliger oder ein Zwerg oder ein Fleckäugiger oder ein Krätziger oder ein Grindiger oder einer mit zerriebenen Hoden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Kein Mann, der ein Gebrest hat, vom Stamm des Priesters Aaron darf herantreten, die Mähler für den Herrn darzubringen. Hat er ein Gebrest, dann darf er nicht herantreten, die Speise seines Gottes darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Die Speise seines Gottes, von den hochheiligen und selbstverständlich von den heiligen Gaben, darf er essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Nur soll er nicht zum Vorhang kommen und sich nicht dem Altare nähern, weil er ein Gebrest hat! Sonst entweiht er meine Heiligtümer. Denn ich, der Herr, bin es, der sie heiligt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Moses redete so zu Aaron und seinen Söhnen und zu allen Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und der Herr redete zu Moses also.-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '\"Sag dem Aaron und seinen Söhnen, sie sollen wegen der heiligen Gaben der Israeliten enthaltsam sein, auf daß sie meinen heiligen Namen nicht entweihen, wenn sie mir, dem Herrn, Gaben weihen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sprich zu ihnen: \'Für eure Geschlechter! Wer von all euren Nachkommen je den heiligen Gaben naht, die dem Herrn die Israeliten weihen, solange an ihm Unreinheit ist, diese Person werde vor meinem Angesichte weggestrichen! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Wer von dem Aaronsstamm aussätzig oder flüssig ist, soll nichts von den heiligen Gaben essen, bis er wieder rein ist! Wer einen, der durch eine Leiche unrein ward, berührt, oder wem der Same entgeht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'wer ein Gewürm berührt, wodurch man unrein wird, oder einen Menschen, an dem man unrein wird durch irgendeine Unreinheit an ihm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'diese Person, die das berührt, sei bis zum Abend unrein! Sie soll nichts von heiligen Gaben essen, bevor sie ihren Leib gebadet hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Sobald die Sonne untergeht, ist er rein. Hernach mag er von heiligen Gaben essen. Denn das ist sein Brot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Gefallenes und Zerrissenes darf er nicht essen, daß er nicht dadurch unrein werde. Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Sie sollen meine Vorschrift befolgen, daß sie nicht deswegen Sünde auf sich laden; sie würden sterben, wenn sie es entweihen. Ich bin es, der Herr, der sie heiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein Unbefugter darf Heiliges genießen. Der Beisaß des Priesters und der Lohndiener dürfen nichts Heiliges essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Erwirbt ein Priester für Geld einen Sklaven, so darf er mitessen, ebenso ein Hausgeborener. Sie dürfen von seiner Speise essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Aber eine Priestertochter, die einen Nichtpriester geheiratet hat, darf von der Weihegabe der heiligen Gaben nichts genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Dagegen eine Priestertochter, die Witwe ist oder verstoßen und kinderlos und wieder in ihr Vaterhaus zurückkehrt, wie in der ledigen Zeit, darf von der Speise ihres Vaters essen. Ein Unzugehöriger darf aber nicht davon essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Wenn jemand aus Versehen Geheiligtes ißt, so lege er ein Fünftel des Betrages darauf und gebe es dem Priester samt der heiligen Gabe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Sie sollen nicht entweihen der Israeliten heilige Gaben, die sie dem Herrn als Weihegabe darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Sonst würden sie ihnen Schuldverfehlungen aufladen, wenn sie ihre heiligen Gaben essen. Denn ich, der Herr, bin es, der sie heiligt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '\"Sprich zu Aaron, seinen Söhnen und zu allen Israeliten und sage zu ihnen: \'Bringt vom Hause Israels oder von den Fremdlingen in Israel jemand sein Opfer dar, sei es versprochen oder freiwillig, das er dem Herrn als Brandopfer darbringen will,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'so sei es zu eurer Begnadigung ein fehlerloses männliches Tier von Rindern, Lämmern oder Ziegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Was einen Makel an sich hat, dürft ihr nicht darbringen. Es würde euch nicht zur Begnadigung sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Will jemand dem Herrn ein Dankopfer darbringen, als besonderes Opfer für Gelobtes oder als freiwillige Gabe von Rindern oder Schafen, so sei es für die Begnadigung fehlerlos! Keinen Makel darf es an sich haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Was blind ist oder gebrochen oder verstümmelt oder geschwürig oder krätzig oder grindig, das dürft ihr dem Herrn nicht darbringen und nicht als Mahl für den Herrn auf den Altar legen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Ein Rind oder ein Schaf, überdeckt oder verkrüppelt, darfst du als freie Gabe herrichten. Aber als Gelübdeopfer wird es nicht angerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Zerquetschtes oder Zerstoßenes oder Abgerissenes oder Verschnittenes dürft ihr dem Herrn nicht darbringen. Ihr dürft in eurem Lande solches nicht machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Auch von Ausländern dürft ihr nichts von alledem als Speise eures Gottes darbringen. Ihr Verderb ist an ihnen. Gebrest ist daran. Solches wird euch nicht angerechnet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und der Herr redete zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '\"Wenn ein Rind, ein Lamm oder ein Zicklein geworfen wird, soll es sieben Tage unter seiner Mutter sein! Vom achten Tage ab und weiterhin kann es als Opfer, als Mahl für den Herrn, angesehen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Ihr dürft weder Rind noch Schaf an einem Tag mit seinem Jungen schlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Wollt ihr dem Herrn ein Lobesopfer opfern, so sollt ihr es zu eurer Begnadigung opfern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Am selben Tage noch werde es gegessen! Ihr dürft davon nichts bis zum Morgen übriglassen! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Beachtet meine Vorschriften! Tut sie! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Ihr sollt nicht meinen heiligen Namen entweihen! Ich will geheiligt sein bei den Söhnen Israels. Ich, der Herr, bin es, der euch heiligt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der euch aus dem Ägypterland geführt, um euch Gott zu sein. Ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '\"Rede mit den Söhnen Israels und sprich zu ihnen: \'Des Herrn Feste, die ihr als heilige Vorlesungstage feiern sollt, dies sind meine Feste:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage soll Arbeit getan werden. Der siebte aber ist ein Tag unbedingter Ruhe, ein heiliger Vorlesungstag. Da dürft ihr keine Arbeit tun. Ein Ruhetag des Herrn ist er in allen euren Siedlungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind des Herrn Feste, die heiligen Vorlesungstage, die ihr zu ihrer Zeit begehen sollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Am vierzehnten des ersten Monats gegen Abend ist Passah für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Am fünfzehnten desselben Monats ist das Fest der ungesäuerten Brote für den Herrn. Ihr sollt sieben Tage ungesäuertes Brot genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage habt ihr heilige Vorlesung abzuhalten. Ihr dürft keinerlei Dienstarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Sieben Tage bringet dem Herrn ein Mahl dar! Am siebten Tage ist heilige Vorlesung. Ihr dürft keinerlei Dienstarbeit tun.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und der Herr redete zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '\"Rede mit den Söhnen Israels und sprich zu ihnen: \'Kommt ihr in das Land, das ich euch gebe, und haltet ihr darin die Ernte, so bringt eurer Ernte erste Abhubsgarbe dem Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Er bringe die Garbe vor den Herrn, euch zur Begnadigung! Am Morgen nach dem Sabbat soll sie der Priester darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Bereitet an dem Tage, da ihr die Garbe bringt, für den Herrn ein fehlerloses, noch nicht einjähriges Lamm zum Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Dazu als Speiseopfer zwei Zehntel feines Mehl, mit Öl bereitet, als ein Mahl süßen Duftes für den Herrn, dazu einen vierter Krug Wein als Trankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Brot, geröstete, zerstoßene Körner, dürft ihr bis zu eben dem Tage nicht essen, bis ihr für euren Gott die Opfergabe dargebracht. Dies ist ewige Satzung für eure Geschlechter in all euren Siedlungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Dann zählt für euch von dem Tage nach dem Sabbat, vom Tage, wo ihr die Garbe dargebracht, sieben volle Wochen ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Bis zum Tage nach dem siebten Sabbat sollt ihr fünfzig Tage abzählen! Dann bringt dem Herrn ein neues Speiseopfer dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Siedlungen sollt ihr zwei Weihebrote aus zwei Zehntel feinem Mehl bringen, mit Sauerteig gebacken, als Erstlingsopfer für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und zu dem Brote bringt noch sieben fehlerlose Lämmer, noch nicht ein Jahr alt, einen jungen Stier und zwei Widder! Sie sollen ein Brandopfer dem Herrn sein, nebst ihren Speis- und Trankopfern, als ein Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Dann bereitet einen Ziegenbock zum Sündopfer sowie zwei Lämmer, nicht ein Jahr alt, zum Dankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Der Priester bringe sie mit den Erstlingsbroten vor dem Herrn samt den beiden Lämmern dar! Zu des Priesters Nutzen seien sie dem Herrn geweiht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'An eben diesem Tage haltet eine Vorlesung ab! Heilige Vorlesung sei es euch! Ihr dürft keinerlei Dienstarbeit verrichten. Dies ist ewige Satzung in allen euren Siedlungen für eure Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Und wenn ihr euer Land aberntet, so sollst du dein Feld nicht bis zum Rande abernten und nach deiner Ernte keine Nachlese halten! Dem Armen und dem Fremdling sollst du es lassen! Ich, der Herr, bin euer Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '\"Sprich also zu den Söhnen Israels: \'Der erste im siebten Monate soll euch ein Ruhetag sein, ein freudiges Gedächtnis, eine heilige Vorlesung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ihr dürft keinerlei Dienstarbeit tun. Dagegen bringt dem Herrn ein Mahl dar!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '\"Genau der zehnte Tag desselben siebten Monats ist der Sühnetag. Da sollt ihr eine heilige Vorlesung abhalten und euch kasteien und dem Herrn ein Mahl darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Aber keinerlei Arbeit dürft ihr an eben diesem Tage tun. Ein Sühnetag ist es, um euch Sühne zu schaffen vor dem Herrn, eurem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn alle die Personen, die sich nicht an eben diesem Tage kasteien, sind aus den Reihen ihres Volkes zu streichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Und alle die Personen, die an eben diesem Tag irgendeine Arbeit tun, raffe ich aus ihrem Volke weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ihr dürft keinerlei Arbeit tun. Dies ist ewige Satzung in allen euren Siedlungen für eure Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Er sei für euch ein strenger Ruhetag! Kasteiet euch! Am neunten Tage des Monats abends, vom Abend bis zum Abend, sollt ihr Sabbatruhe halten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '\"Sprich also zu den Söhnen Israels: Am fünfzehnten desselben siebten Monats feiere man dem Herrn sieben Tage lang das Laubhüttenfest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage ist heilige Vorlesung. Ihr dürft keinerlei Dienstarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Ihr sollt sieben Tage dem Herrn ein Mahl bringen! Am achten Tage haltet heilige Vorlesung ab und bringt dann dem Herrn ein Mahl! Tag der Festversammlung ist es. Ihr dürft keinerlei Dienstarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Dies sind des Herrn Feste, an denen ihr heiligen Vorlesungen obliegen sollt, dabei dem Herrn ein Mahl darbringend, Brand-, Speise-, Schlacht- und Trankopfer je nach Erfordernis des Tages,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'abgesehen von den Sabbaten des Herrn und euren Gaben, allen euren gelobten Opfern und euren freien Spenden, die ihr dem Herrn geben werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Genau am fünfzehnten des siebten Monats, wenn ihr des Landes Ernte einheimset, sollt ihr das Fest des Herrn sieben Tage feiern! Ein Ruhetag ist der erste Tag, ebenso der achte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Am ersten Tage holt euch Zweige vom Myrtenbaum, Palmfächer und Zweige von Laubbäumen und Bachweiden! Und freut euch vor dem Herrn, eurem Gotte, sieben Tage!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'So feiert es im Jahre sieben Tage als Fest des Herrn, ewiges Gesetz für eure Geschlechter! Im siebten Monat sollt ihr es feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sieben Tage sollt ihr in den Lauben wohnen! Jeder Eingeborene in Israel soll in den Lauben wohnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'damit eure Geschlechter wissen, daß ich die Söhne Israels in Lauben habe siedeln lassen, als ich sie aus Ägypterland geführt! Ich, der Herr, bin euer Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Moses verkündete die Feste den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und der Herr redete mit Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '\"Befiehl den Söhnen Israels, sie sollen dir lauteres Öl aus zerstoßenen Oliven für den Leuchter liefern, um ein stetes Licht zu haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Draußen vor des Zeugnisses Vorhang im Festgezelt mache es Aaron zurecht für die Zeit vom Abend bis zum Morgen vor dem Herrn! Eine ewige Satzung für eure Geschlechter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem reingoldenen Leuchter soll er die Lichter zurechtmachen, ständig vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Nimm feines Mehl und backe daraus zwölf Kuchen! Zwei Zehntel soll auf einen Kuchen kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Lege sie in zwei Reihen, je sechs für einen Teil, vor dem Herrn auf einen Tisch von reinem Gold!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Und jedem Teile gib reinen Weihrauch bei, damit er dem Brot als Brandteile diene, ein Mahl für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Er soll es jedesmal am Sabbat stets vor dem Herrn aufschichten, von den Söhnen Israels aus eine ewige Verpflichtung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Es gehöre Aaron und seinen Söhnen! Sie sollen es an heiliger Stätte verzehren! Denn ihm gehört es als Hochheiliges von des Herrn Mählern, ein ewiges Anrecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Da war eines israelitischen Weibes Sohn mit ausgezogen, dessen Vater ein Ägypter war, unter den Israeliten. Nun rauften im Lager der Sohn der Israelitin und ein israelitischer Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Da schmähte des israelitischen Weibes Sohn den Namen und lästerte. Da brachten sie ihn zu Moses. Seine Mutter aber vom Stamme Dan hieß Selomit, Dibris Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Sie führten ihn in den Gewahrsam, bis aus des Herrn Mund ihnen Weisung käme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '\"Führe den Lästerer vor das Lager! Alle, die es hörten, sollen die Hände auf sein Haupt legen! Dann soll ihn die gesamte Gemeinde steinigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Und zu den Söhnen Israels sprich also: \'Wer seinen Gott lästert, lädt Schuld auf sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Wer aber des Herrn Namen schmäht, leide den Tod! Ihn soll die Gesamtgemeinde steinigen. Sei es Fremdling oder Eingeborener! Weil er den Namen geschmäht, muß er sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Wer ein Menschenwesen erschlägt, soll den Tod erleiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Wer ein Tierwesen erschlägt, soll es ersetzen! Wesen um Wesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Wenn jemand seinem Nächsten einen Leibesschaden zufügt, dem werde getan, wie er getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch! Aug\' um Aug\'! Zahn um Zahn! Der gleiche Leibesschaden, den er einem anderen zufügt, werde ihm zugefügt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Wer ein Stück Vieh erschlägt, soll es ersetzen! Wer einen Menschen erschlägt, soll getötet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Einerlei Recht sei euch, dem Fremdling wie dem Einheimischen! Ich, der Herr, bin euer Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Und Moses berichtete so den Israeliten. Da führten sie den Lästerer vor das Lager und steinigten ihn. Die Israeliten taten also, wie der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Der Herr aber hatte zu Moses auf dem Berge Sinai also gesprochen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '\"Rede mit den Söhnen Israels und sprich zu ihnen: \'Wenn ihr in das Land kommt, das ich euch gebe, so halte das Land für den Herrn eine Ruhezeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre sollst du dein Feld besäen! Sechs Jahre sollst du deinen Weinberg beschneiden, dann heimse seine Ernte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Im siebten Jahre aber soll das Land volle Ruhe haben, als Ruhezeit für den Herrn! Du darfst dein Feld nicht besäen, noch deine Weinberge beschneiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Den Nachwuchs deiner Ernte sollst du nicht beschneiden! Die Trauben deines unbeschnittenen Weinstocks sollst du nicht lesen. Ein Ruhejahr soll es für das Land sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Während eurer Bodenruhe diene zur Nahrung dir, deinem Knechte, deiner Magd, deinem Lohnarbeiter, deinem Beisaß unter deinem Schutze,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'deinem Vieh und dem Wilde in deinem Lande all sein Ertrag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Zähle dir sieben Jahrwochen ab, siebenmal sieben Jahre! So seien dir die Tage der sieben Jahrwochen neunundvierzig Jahre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Dann laß im siebten Mond das Lärmhorn erschallen, am zehnten Tage des Monats! Am Sühnetage sollt ihr in eurem Lande das Horn ertönen lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Heiligt das fünfzigste Jahr und ruft Freiheit im Land für alle seine Insassen aus! Jubeljahr sei es euch! Da kehrt ein jeder zu seinem Besitz und jeder zu seiner Sippe zurück!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Jubeljahr sei euch das fünfzigste Jahr! Nicht säen dürft ihr noch den Nachwuchs einernten und nicht von unbeschnittenen Traubenstöcken lesen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Ein Jubeljahr soll euch heilig sein! Vom Felde weg sollt ihr seinen Ertrag verzehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In diesem Jubeljahr kommt ihr jeder wieder zu seinem Besitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Verkauft ihr etwas einem Angehörigen eures Volkes oder kauft ihr es von einem solchen, so plage keiner den anderen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Nach der Zahl der Jahre nach dem Jubeljahr sollst du den Angehörigen deines Volkes abkaufen! Nach der Zahl der Erntejahre soll er dir verkaufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Für eine größere Zahl von Jahren sollst du einen höheren Kaufpreis zahlen und einen kleineren für eine kleinere Zahl von Jahren! Wenn er dir eine Anzahl Ernten verkauft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'dann sollt ihr nicht einander plagen, einer den anderen Angehörigen seines Volkes! Fürchte dich vor deinem Gott! Denn ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Tut meine Vorschriften! Meine Satzungen sollt ihr wahren! Erfüllt sie! Dann wohnet ihr im Lande sicher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Und dann gibt das Land seine Frucht. Satt könnt ihr euch essen und sicher darin siedeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und sprächet ihr: \"Was sollen wir im siebten Jahre essen? Wir dürfen ja nicht säen und keinen Vorrat sammeln\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'so entbiete ich im sechsten Jahre meinen Segen für euch, daß es für drei Jahre Ertrag gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Sät ihr im achten Jahr, so könnt ihr noch Altes vom Ertrag genießen. Bis zum neunten Jahre, bis seine Ernte kommt, könnt ihr Altes essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Nicht soll das Land endgültig verkauft werden! Denn mein ist das Land. Ihr seid nur Gäste und Beisassen bei mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Ihr sollt überall in eurem eigenen Lande Wiedereinlösung für das Land gestatten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Verarmt dein Bruder und verkauft von seinem Besitz, so gehe sein nächster Verwandter zu ihm als Löser und löse den Verkauf seines Bruders aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Hat jemand keinen Löser, aber ist er zur Wiedereinlösung vermöglich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so bringe er die Jahre seit dem Verkauf in Anrechnung! Was darüber ist, erstatte er seinem Käufer, damit er wieder zu seinem Besitz komme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Ist er aber zur Rückerstattung unvermögend, dann bleibe sein Verkauf im Besitz des Käufers bis zum Jubeljahr! Im Jubeljahr aber falle es heim, daß er wieder zu seinem Besitz kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Verkauft jemand in einer ummauerten Stadt ein Wohnhaus, so währe sein Einlösungsrecht bis zum Tage des Jahres seines Verkaufes! Sein Einlösungsrecht soll auf den Tag währen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wird es aber bis zum Ablauf eines vollen Jahres nicht eingelöst, dann verfalle das Haus in der Stadt mit Mauern endgültig seinem Käufer und seinen Nachkommen! Im Jubeljahr fällt es nicht heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Die Häuser in Dörfern ohne Ringmauern sind zum Ackerfelde zu rechnen. Für sie gibt es ein Einlösungsrecht; sie fallen im Jubeljahre heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Bei den Levitenhäusern, bei ihren eigenen Häusern in den Städten, gibt es stets ein Einlösungsrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Wer von den Leviten nicht einlösen kann, dessen verkauftes Haus falle in der eigenen Stadt im Jubeljahr zurück. Denn der Levitenstädte Häuser sind ihr Eigentum inmitten der Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Aber ihrer Städte Weideland darf nicht verkauft werden. Für alle Zeit gehört es ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Verarmt dein Bruder, zittert seine Hand neben dir, dann halte ihn fest! Als Gast und Beisasse, so lebe er bei dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nimm keinen Wucherzins von ihm! Fürchte deinen Gott! Dein Bruder lebe neben dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du sollst ihm dein Geld nicht gegen Zins geben und nicht um Zinsen deine Speise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ich, der Herr, bin euer Gott, der aus Ägypterland euch geführt, euch das Land von Kanaan zu geben und euch Gott zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Verarmt dein Bruder neben dir und verkauft er sich dir, so sollst du ihn keine Sklavendienste tun lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Er soll bei dir wie ein Lohnarbeiter sein, ein Beisasse! Er soll bei dir bis zum Jubeljahr dienen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Dann verlasse er samt seinen Söhnen dich und kehre zu seiner Sippe! Zum Besitz seiner Väter kehre er wieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Sie sind ja meine Knechte, die ich aus Ägypterland geführt. Sie dürfen nicht wie Sklaven verkauft werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du sollst nicht mit Härte über ihn herrschen! Fürchte dich vor deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Dein Sklave und deine Sklavin, die dein sind: von den Heidenvölkern rings um euch rnöget ihr Sklaven und Sklavinnen erwerben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Auch von den Kindern der Beisassen neben euch möget ihr kaufen sowie aus ihrer Sippe bei euch. Die sie in eurem Land gezeugt, sie mögen euer Besitz werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Vererbet sie nach euch auf eure Söhne als ihren Besitz! Ihr möget sie dauernd zu Sklaven haben. Aber über eure israelitischen Brüder dürft ihr gegenseitig nicht mit Härte walten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Kommt bei dir ein Fremder oder Beisaß zu Besitz, dein Bruder aber wird neben ihm arm und verkauft sich einem Beisassen bei dir oder einem Abkömmling aus des Fremdlings Sippe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so gibt es nach seinem Verkauf für ihn Auslösung. Einer seiner Brüder soll ihn lösen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'oder sein Oheim oder seines Oheims Sohn, oder einer seiner nächsten Blutsverwandten seiner Sippe, oder reicht sein Vermögen zu, so löse er sich aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Er rechne mit seinem Käufer die Zeit vom Jahre seines Verkaufs bis zum Jubeljahr! Der Preis seines Verkaufs sei nach der Jahre Zahl! Wie ein Lohnarbeiter soll er eine bestimmte Zeit bei ihm sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Sind es noch viele der Jahre, dann soll er dementsprechend seine Lösungssumme von seinem Kaufgeld erstatten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Fehlen aber nur wenige Jahre bis zum Jubeljahr, so berechne er sie ihm! Nach seinen Jahren soll er seine Lösungssumme erstatten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Gleich dem, der Jahr für Jahr um Lohn arbeitet, soll er neben ihm sein! Er soll aber nicht mit Härte über ihn walten vor deinen Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Wird er nicht auf diese Weise ausgelöst, dann gehe er im Jubeljahr samt seinen Söhnen frei aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn die Söhne Israels sind mir Knechte. Meine Knechte sind sie, die ich aus dem Ägypterland herausgeführt. Ich, der Herr, bin euer Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '\"Ihr sollt keine Götzen machen! Ihr sollt euch kein Schnitzbild errichte und kein Steinmal! Ihr sollt keinen Klagestein in eurem Lande setzen, um euch darauf hinzuwerfen! Denn ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Meine Ruhetage sollt ihr beobachten! Vor meinem Heiligtume sollt ihr Ehrfurcht haben! Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Wandelt ihr nach meinen Satzungen und haltet ihr meine Vorschriften und tut ihr nach ihnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'alsdann gebe ich eure Regen zu ihrer Zeit. Das Land gibt seine Ernte und des Feldes Baum seine Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Dann reicht euch die Dreschzeit bis zur Weinlese und die Weinlese bis zur Saatzeit. Ihr eßt bis zum Sattsein euer Brot und sitzt in Sicherheit in eurem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Dem Land gebe ich Frieden. Ihr legt euch nieder, und niemand schreckt euch. Böses Getier schaffe ich aus dem Lande. Kein Schwert zieht mehr durch euer Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Verfolgt ihr eure Feinde, dann verfallen sie vor euch dem Schwerte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Eurer fünf verfolgen hundert und eurer hundert zehntausend. So verfallen eure Feinde vor euch dem Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Ich wende mich euch zu und mehre euch und mache euch zahlreich. Meinen Bund errichte ich mit euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Essen könnt ihr Altes, Gelagertes. Das Alte aber müßt ihr erst hinausschaffen vor dem Neuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ich nehme meinen Wohnsitz bei euch, und meine Seele wird euch nicht verabscheuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ich wandle unter euch und bin euch Gott. Ihr aber sollt mir zum Volke sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich, der Herr, bin euer Gott, der aus Ägypterland euch geführt, damit ihr nicht länger ihnen Sklaven wäret. Ich zerbrach die Stangen eures Joches und ließ euch aufrecht gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Hört ihr aber nicht auf mich und tut ihr nicht nach allen den Geboten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'verwerft ihr meine Vorschriften und verabscheut eure Seele meine Satzungen, daß alle meine Gebote ungetan bleiben, daß ihr meinen Bund brechet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'dann tu ich Ähnliches an euch. Ich verhänge über euch plötzlich Schwindsucht und Brand, die die Augen vernichten und die Seele verkümmern. Umsonst sät ihr euren Samen. Eure Feinde verzehren ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Ich kehre mein Antlitz wider euch. Von euren Feinden werdet ihr geschlagen, und eure Hasser unterjochen euch. Ihr flieht, wo keiner euch verfolgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Gehorcht ihr mir auf dies hin nicht, dann züchtige ich euch noch siebenmal härter für eure Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Ich breche euren frechen Übermut und lasse euren Himmel wie Eisen werden, euer Ackerfeld wie Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Umsonst verzehrt sich eure Kraft. Ertraglos bleibt euer Ackerfeld. Des Feldes Bäume geben keine Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und geht ihr dann mit mir noch unschicklich um, und wollt ihr mir nicht gehorchen, dann schlage ich euch nach euren Sünden siebenfach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Ich sende gegen euch des Feldes Wild, damit es euch entvölkere und euer Vieh würge und euch mindere, damit eure Straßen veröden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Und nehmt ihr dann noch keine Zucht von mir an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'dann gehe auch ich mit euch unschicklich um und schlage euch siebenfach um eurer Sünde willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Ich bringe über euch ein Schwert, das den Bundesbruch rächt. Bergt ihr euch in euren Städten, dann sende ich unter euch die Pest. In Feindeshände werdet ihr gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Zerbreche ich euch des Brotes Stütze, dann können euer Brot zehn Weiber in einem einzigen Ofen backen. Sie werden euch das Brot zuwägen. Dann esset ihr und werdet nicht satt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Und hört ihr trotzdem nicht auf mich, und geht ihr mit mir unschicklich um,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'dann gehe auch ich in meinem Grimm mit euch unschicklich um und züchtige euch meinerseits um eurer Sünden willen siebenfach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Dann eßt ihr eurer Söhne Fleisch, und eurer Töchter Fleisch werdet ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Und ich verwüste eure Höhen, zerstöre eure Rauchaltäre und werfe auf eure Götzen eure Leichen. So ekelt sich meine Seele vor euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Ich mache zu Trümmern eure Städte und lasse eure Heiligtümer unbewohnt und nicht mehr rieche ich euren süßen Duft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ich verwüste das Land, und eure Feinde entsetzen sich darob, wenn sie in ihm siedeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber zerstreue ich unter die Heiden und ich zücke hinter euch ein Schwert. Zur Wüste soll euer Land werden, zu Trümmern eure Städte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Dann zahlt das Land seine Sabbate mit all der Zeit der Verödung, indessen ihr im Lande eurer Feinde seid. Dann feiert das Land und zahlt so seine Sabbate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Ruhe hat es die ganze Zeit der Verödung, die Ruhe, die es nicht gehabt, als ihr bei euren Ruhezeiten darin noch wohntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Die von euch übrigbleiben, mache ich verzagt in ihrer Feinde Länder. Verwehten Blattes Rauschen schlägt sie in die Flucht. Sie fliehen wie auf Schwertes Flucht und stürzen, obwohl sie niemand verfolgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Sie fallen wie vor einem Schwerte, der eine über den anderen, obschon von niemandem verfolgt. Ihr haltet vor euren Feinden nicht stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Und bei den Heiden schwindet ihr, und eurer Feinde Land frißt euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Die von euch übrigbleiben, siechen ob ihrer Sündenschuld in eurer Feinde Ländern hin. Sie siechen obendrein ob ihrer Väter Sünden hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Bekennen sie dann ihre Schuld und die der Väter, in ihrem Trug, mit dem sie mich betrogen, auch daß sie mit mir unschicklich umgegangen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'und daß auch ich mit ihnen unschicklich gehandelt und sie in ihrer Feinde Land verbracht, wenn sich dann ihr unbeschnitten Herze beugt und wenn sie dann ihre Sündenschuld aufzählen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'dann gedenke ich meines Jakobbundes und meines Isaakbundes und meines Abrahambundes und des Landes gedenke ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Das Land muß aber von ihnen verlassen werden und seine Sabbate abzahlen, indes es wüste liegt und jene fort sind. Sie selber müssen ihre Sündenschuld aufzählen, weil sie meine Satzungen verworfen und meine Vorschriften mißachtet haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Trotzdem verwerfe ich sie nicht, wenn sie im Lande ihrer Feinde sind, und ich verabscheue sie nicht, so daß ich sie ganz vertilgt und meinen Bund mit ihnen aufgelöst hätte. Ich, der Herr, bin ihr Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ich gedenke zu ihrem Besten des Bundes mit den Ahnen, die ich aus Ägypterland vor der Heiden Augen weggeführt, um ihnen Gott zu sein, ich, der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dies sind die Gebote, Satzungen und Lehren, die der Herr zwischen sich und den Söhnen Israels auf dem Berge Sinai durch Moses aufgestellt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '\"Sprich zu den Söhnen Israels und sage ihnen: \'Wenn jemand Personen nach dem Schätzungswert dem Herrn gelobt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'dann sei Schätzungswert des Männlichen von zwanzig bis zu sechzig Jahren nach heiligem Gewicht fünfzig Silberringe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ist es ein Weibliches, sei der Wert dreißig Ringe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Ist es von fünf bis zu zwanzig Jahren, so sei der Wert des Männlichen zwanzig Ringe, der des Weiblichen zehn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ist es von einem Monat bis zu fünf Jahren, so sei der Wert des Männlichen fünf Silberringe, der des Weiblichen drei Silberringe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ist es von sechzig Jahren und darüber, so sei der Wert des Männlichen fünfzehn Ringe und der des Weibes zehn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ist es aber zu arm für den Schätzungswert, dann bringe man es vor den Priester, und der Priester werte es! Nach dem, was der Gelobende zahlen kann, soll ihn der Priester werten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Und ist es Vieh, von dem man dem Herrn ein Opfer bringen will, dann soll alles, was einer davon gibt, dem Herrn geheiligt sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Er soll es nicht auswechseln und nicht Gutes für Schlechtes vertauschen oder Schlechtes für Gutes, und tauscht er doch das eine Vieh mit dem anderen, so sei das eine geheiligt; aber auch das andere soll es sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ist es aber irgendein unreines Tier, das man dem Herrn nicht als Opfer darbringen darf, so stelle er das Vieh dem Priester vor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Der Priester werte es zwischen gut und schlecht! Wie es der Priester wertet, so soll es bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Löst er es aber ein, so lege er ein Fünftel auf den Schätzungswert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Weiht jemand dem Herrn sein Haus als heilige Gabe, so werte es der Priester zwischen gut und schlecht! Wie es der Priester schätzt, dabei soll es bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Will jemand, der sein Haus geweiht hat, es einlösen, so lege er ein Fünftel des Wertes darauf, und es sei wieder sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Weiht jemand etwas von seinem Besitz dem Herrn, so sei der Wert nach seiner Aussaat! Ein Malter Gerstenaussaat zu fünfzig Silberringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Weiht er vom Jubeljahre ab sein Feld, so soll es nach dem Richtwerte zu stehen kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Weiht er aber nach dem Jubeljahr sein Feld, so berechne der Priester den Silberpreis mit Rücksicht nach den Jahren, die bis zum Jubeljahre fehlen! Dies werde vom Richtwert abgezogen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will aber der, der das Feld geweiht, es einlösen, dann lege er ein Fünftel des Wertes darauf, und es sei wieder sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Löst er aber das Feld nicht ein und hat man das Feld an einen anderen verkauft, so kann es nicht mehr eingelöst werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Vielmehr ist dies Feld, wird es im Jubeljahre frei, etwas, was dem Herrn geweiht ist, wie ein dem Bann verfallenes Feld. Dem Priester soll sein Besitz zufallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Weiht er jedoch dem Herrn ein Feld, das er sich selbst gekauft und das nicht zu seinem Erbbesitz gehört,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so berechne ihm der Priester den Betrag des Richtwertes bis zum Jubeljahr! Er gebe den Wert an demselben Tag als heilige Gabe für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Jubeljahre kommt das Feld an den zurück, von dem er es gekauft und dem es als Erbbesitz gehört hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Nach heiligem Gewicht geschehe jede Schätzung! Zwanzig Korn seien ein Ring!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Erstgeburten aber, die beim Vieh als erstgeworfen des Herrn sind, darf niemand opfern, weder Rind noch Schaf. Dem Herrn gehören sie ohnehin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Bei unreinem Vieh löse man es nach dem Schätzungswert und lege ein Fünftel des Betrags darauf! Wird es nicht eingelöst, so werde es nach dem Wert verkauft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Keinerlei Banngut, das ein Mann dem Herrn bannt, nichts, was ihm gehört, Mensch oder Vieh oder Erbgrundstück, darf verkauft oder eingelöst werden. Alles Banngut ist dem Herrn hochheilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Was von Menschen gebannt wird, darf nicht losgekauft werden. Es soll getötet werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Aller Zehnte vom Boden, der Saatfrucht und der Baumfrüchte sind des Herrn. Sie sind dem Herrn geheiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Löst aber jemand einen Teil von seinem Zehnten ein, so soll er ein Fünftel des Betrages darauflegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Bei allem Zehnten von Rind und Schaf, von allem, was unterm Hirtenstabe durchgeht, soll das zehnte Stück dem Herrn geheiligt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soll nicht zwischen gut und schlecht untersuchen! Man soll es nicht vertauschen! Tauschte man es doch, dann sei das eine dem Heiligtum verfallen, ebenso soll es mit dem anderen sein! Es darf nicht eingelöst werden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dies sind die Gebote, die der Herr dem Moses für die Israeliten auf dem Berge Sinai gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und der Herr redete mit Moses in der Wüste Sinai im Festgezelt am ersten Tage des zweiten Monats im zweiten Jahre nach ihrem Auszug aus dem Land Ägypten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '\"Erhebt die Gesamtzahl der israelitischen Gesamtgemeinde nach ihren Sippen und Familien, in Namenszählung, alles Männliche aber nach der Kopfzahl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Von zwanzig Jahren an und darüber sollt ihr in Israel alle Kampffähigen nach ihren Scharen mustern, du und Aaron!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Euch zugesellt soll für jeden Stamm je einer sein, und zwar sei es das Familienoberhaupt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Dies sind die Namen der Männer, die euch beistehen sollen: für Ruben: Elisur, Sedeurs Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'für Simeon: Selumiel, Surisaddais Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'für Juda: Amminadabs Sohn Nachson;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'für Issakar: Suars Sohn Netanel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'für Zabulon: Chelons Sohn Eliab;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'für die Josephssöhne: von Ephraim Elisama, Ammihuds Sohn, von Manasse Pedahsurs Sohn Gamliel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'für Benjamin: Gidonis Sohn Abidan;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'für Dan: Ammisaddais Sohn Achiezer;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'für Asser: Okrans Sohn Pagiel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'für Gad: Reuels Sohn Eljasaph;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'für Naphtali: Enans Sohn Achira.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Dies waren die Berufenen der Gemeinde, die Fürsten ihrer väterlichen Stämme, die Häupter der Sippen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'So nahm Moses mit Aaron diese namentlich bezeichneten Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Die Gesamtgemeinde aber versammelten sie am ersten des zweiten Monats. Da trugen sie sich nach der Geburt in ihren Sippen familienweise ein, in Namenszählung, Kopf für Kopf, von zwanzig Jahren und darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Wie der Herr dem Moses befohlen, so musterte er sie in der Wüste Sinai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Die Söhne Rubens, des Erstgeborenen Israels, entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung, Kopf für Kopf, alles Männliche, von zwanzig Jahren und darüber, alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'ihre aus dem Stamme Ruben Ausgemusterten, 46.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Von den Söhnen Simeons entsprachen in ihren Geschlechtern, Sippen und Familien die Gemusterten unter schriftlicher Namensaufnahme, Kopf für Kopf, alles Männliche, von zwanzig Jahren und darüber, alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'ihre aus dem Stamme Simeon Ausgemusterten, 59.300.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Von den Söhnen Gads entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber, alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'ihre aus dem Stamme Gad Ausgemusterten, 45.650.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Von den Söhnen Judas entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'ihre aus dem Stamme Juda Ausgemusterten, 74.600.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Von den Söhnen Issakars entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'ihre aus dem Stamme Issakar Ausgemusterten, 54.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Von den Söhnen Zabulons entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'ihre aus dem Stamme Zabulon Ausgemusterten, 57.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Von den Josephssöhnen, von den Söhnen Ephraims entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'ihre aus dem Stamme Ephraim Ausgemusterten, 40.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Von den Söhnen Manasses entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'ihre aus dem Stamme Manasse Ausgemusterten, 32.200.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Von den Söhnen Benjamins entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'ihre aus dem Stamme Benjamin Ausgemusterten, 35.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Von den Söhnen Dans entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'ihre aus dem Stamme Dan Ausgemusterten, 62.700.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Von den Söhnen Assers entsprachen in ihren Geschlechtern, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'ihre aus dem Stamme Asser Ausgemusterten, 41.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Von den Söhnen Naphtalis entsprachen in ihren Geschlechtem, Sippen und Familien in Namenszählung von zwanzig Jahren und darüber alle Wehrpflichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'ihre aus dem Stamme Naphtali Ausgemusterten, 53.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Dies sind die Ausgemusterten, die Moses und Aaron gemustert haben, sowie die Fürsten Israels, zwölf Mann, je einer für seine Familie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Alle, familienweise von zwanzig Jahren und darüber gemusterten Israeliten wurden sämtlich in Israel wehrpflichtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Aller Gemusterten waren es 603.550.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Die Leviten aber waren nach ihrem väterlichen Stamme nicht mit ihnen gemustert worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Der Herr hatte nämlich zu Moses gesagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '\"Du darfst den Levitenstamm in keiner Weise mustern. Ihre Gesamtzahl sollst du bei Israels Söhnen nicht aufnehmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Dagegen beauftrage du die Leviten über die Wohnung des Zeugnisses, über alle ihre Geräte und alles, was dazu gehört! Sie sollen die Wohnung und alle ihre Geräte tragen! Pflegen sollen sie diese! Darum sollen sie rings um die Wohnung lagern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Setzt sich die Wohnung in Bewegung, dann sollen die Leviten sie auseinandernehmen, und lagert sich die Wohnung, dann sollen die Leviten sie erstellen! Ein Fremder, der hinzutritt, soll des Todes sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Die anderen Israeliten sollen lagern, jeder in seinem Lager und jeder bei seiner Fahne, nach ihren Scharen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Die Leviten aber sollen um die Wohnung des Zeugnisses lagern, daß kein Zorn über die israelitische Gemeinschaft komme! Darum sollen die Leviten die Wache an der Wohnung des Zeugnisses übernehmen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Die Israeliten taten so. Genau so wie der Herr dem Moses geboten, also taten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und der Herr sprach zu Moses und Aaron:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '\"Jeder soll sich bei seiner Fahne lagern, bei den Abzeichen seiner Familie! So sollen die Israeliten lagern! Dem Festgezelt gegenüber ringsum sollen sie lagern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Nach vorne, nach Osten zu, sollen lagern die Fahne des Lagers Juda nach seinen Scharen und der Fürst der Judasöhne Nachson, Amminadabs Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'und seine Schar mit ihren Ausgemusterten, 74.600!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Neben ihm lagere der Stamm Issakar und der Fürst der Issakarsöhne Netanel, Suars Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'und seine Schar mit seinen Ausgemusterten, 54.400!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Ferner der Stamm Zabulon und der Fürst der Zabulonsöhne Eliab, Chelons Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'und seine Schar mit seinen Ausgemusterten, 57.400!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle in Judas Lager Ausgemusterten zählen 186.400 nach ihren Scharen. Sie haben zuerst zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Die Fahne des Lagers Rubens sei nach Süden zu, nach ihren Scharen, und Fürst der Rubensöhne sei Elisur, Sedeurs Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'und seine Schar mit seinen Ausgemusterten, 46.500!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Daneben lagere der Stamm Simeon und der Fürst der Simeonsöhne Selumiel, Surisaddais Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'und seine Schar mit ihren Ausgemusterten, 59.300!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Dann der Stamm Gad und der Fürst der Gadsöhne Eljasaph, Reuels Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'und seine Schar mit ihren Ausgemusterten, 45.650!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle in Rubens Lager Ausgemusterten zählen 151.450 nach ihren Scharen. Sie haben an zweiter Stelle zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Das aufgeschlagene Festgezelt und das Levitenlager seien in der Mitte der anderen Lager! Wie sie lagern, so sollen sie ziehen, jeder von seinem Platze bei ihren Fahnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Die Fahne des Lagers Ephraims nach seinen Scharen sei gegen Westen, und Fürst der Ephraimsöhne sei Elisama, Ammihuds Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'und seine Schar mit ihren Ausgemusterten, 40.500!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Daneben der Stamm Manasse, und Fürst der Manassesöhne sei Gamliel, Pedahsurs Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'und seine Schar mit ihren Ausgemusterten, 32.2001');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Dann der Stamm Benjamin und Fürst der Benjaminsöhne Abidan, Gidonis Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'und seine Schar mit ihren Ausgemusterten, 35.400!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle im Lager Ephraims Ausgemusterten, 108.100 nach ihren Scharen, sollen an dritter Stelle ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Die Fahne des Lagers Dans sei gegen Norden, nach ihren Scharen, und Fürst der Söhne Dans sei Achiezer, Ammisaddais Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'und seine Schar mit ihren Ausgemusterten, 62.700!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Daneben lagere den Stamm Asser, und Fürst der Assersöhne sei Pagiel, Okrans Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'und seine Schar und ihre Ausgemusterten, 41.500!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Dann der Stamm Naphtali, und Fürst der Naphtalisöhne sei Achira, Enans Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'und seine Schar mit ihren Ausgemusterten, 53.400!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle im Lager Dans Ausgemusterten, 157.600, sollen zuletzt nach ihren Fahnen ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Dies sind die Ausgemusterten der Israeliten nach ihren Familien; sämtliche Ausgemusterten der Lager nach ihren Scharen, 603.550.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Die Leviten aber waren unter den Israeliten nicht mitgemustert worden, wie der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Die Israeliten taten alles, wie der Herr dem Moses befohlen. So lagerten sie nach ihren Fahnen. Und also zogen sie aus, jeder nach seiner Sippe und bei seiner Familie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dies sind die Geschehnisse Aarons und Mosis zur Zeit, da der Herr mit Moses auf dem Berge Sinai geredet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Dies sind die Namen der Aaronsöhne: der Erstgeborene Nadab, Abihu, Eleazar und Itamar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Dies sind die Namen der Söhne Aarons, der gesalbten Priester, die man zum Priesterdienste eingesetzt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab und Abihu aber waren vor dem Herrn gestorben, weil sie vor dem Herrn ungehöriges Feuer darbrachten in der Wüste Sinai. Sie hatten keine Söhne gehabt, und so verwalteten Eleazar und Itamar bei ihres Vaters Lebzeiten das Priesteramt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '\"Bringe den Levistamm her und stelle ihn dem Priester Aaron vor, daß er ihm Dienste leiste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Sie sollen seiner und der Gesamtgemeinde vor dem Festgezelt warten im Dienst an der Wohnung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Des Festgezeltes sämtlicher Geräte sollen sie warten und sonst der Söhne Israels im Dienste an der Wohnung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Die Leviten übergib Aaron und seinen Söhnen! Beigegeben sind sie ihm aus den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron mit seinen Söhnen sollst du bestellen, daß sie an dem Festgezelt ihres Priesteramtes warten! Der Unbefugte, der herantritt, soll des Todes sterben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '\"Ich selber nehme die Leviten aus der Israeliten Mitte anstatt aller erstgeborenen Israeliten, die zuerst den Mutterschoß durchbrechen. So seien die Leviten mein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn mein ist alle Erstgeburt. An dem Tage, da ich alle Erstgeburt im Land Ägypten geschlagen, habe ich mir alle Erstgeburt in Israel geweiht. Vom Menschen bis zum Vieh. Sie gehören mir, dem Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und der Herr sprach zu Moses in der Steppe Sinai:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '\"Mustere die Levisöhne nach ihren Sippen und Familien! Alles Männliche von einem Monat aufwärts sollst du mustern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Da musterte sie Moses, nach des Herrn Befehl, wie ihm geboten ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Dies sind Levis Söhne nach ihren Namen: Gerson, Kehat und Merari.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Dies sind die Namen der Söhne Gersons nach ihren Sippen: Libni und Simi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Die Söhne Kehats nach ihren Sippen sind Amram, Jishar, Chetron und Uzziel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Die Söhne Meraris nach ihren Sippen sind Machli und Musi. Dies sind die Sippen der Leviten nach ihren Familien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Von Gerson stammt das Geschlecht der Libniter und das der Simiter. Dies sind die Sippen der Gersoniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Die Zahl ihrer Ausgemusterten, aller Männlichen von einem Monat und darüber, betrug 7.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Sippen der Gersoniter sollen hinter der Wohnung gen Westen lagern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Das Familienhaupt der Gersoniter war Laels Sohn Eljasaph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Die Wartung der Gersonsöhne sei im Festgezelt die Wohnung und das Zelt seine Hülle, der Vorhang vor der Tür des Festgezeltes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'die Vorhofumhänge, der Vorhang vor der Vorhoftür um Wohnung und Altar und seine Stricke mit seinem ganzen Zubehör!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Von Kehat stammt das Geschlecht der Amramiter, der Ishariter, der Chetroniter und der Uzzieliter. Dies sind die Geschlechter der Kehatiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Nach der Zählung alles Männlichen, von einem Monat an gerechnet, sind es 8.300, die des Heiligtums warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Sippen der Kehatsöhne sollen neben der Wohnung gen Süden lagern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Familienhaupt der Kehatitersippen ist Uzziels Sohn Elisaphan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ihre Sorge sei die Lade, der Tisch, der Leuchter, die Altäre, die heiligen Geräte, mit denen man amtet, und der Vorhang, mit all ihrem Zubehör!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Das Oberhaupt der Levihäupter ist Eleazar, der Sohn des Priesters Aaron, Aufseher derer, die des Heiligtums warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Von Merari stammt das Geschlecht der Machliter und Musiter. Das sind die Sippen Meraris.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Ihrer Ausgemusterten, in der Zählung alles Männlichen von einem Monat aufwärts, sind es 6.200.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Familienhaupt der Sippen Meraris ist Suriel, Abichails Sohn; sie lagerten neben der Wohnung gegen Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Die Merarisöhne haben die Aufgabe, die Bretter der Wohnung zu besorgen, ihre Riegel, Säulen, Füße und alle ihre Geräte, kurz ihr gesamtes Zubehör,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'ferner die Vorhofsäulen ringsum und ihre Füße, Pflöcke und Stricke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Vor der Wohnung nach vorne, vor dem Festgezelt gen Osten, lagerten Moses, Aaron und seine Söhne, die den Dienst am Heiligtum besorgten, den Dienst für die Israeliten. Der Unbefugte, der sich naht, soll des Todes sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Aller Ausgemusterten der Leviten, die Moses und Aaron nach des Herrn Befehl nach ihren Sippen gemustert hatten, alles Männliche von einem Monat aufwärts, sind es 22.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und der Herr sprach zu Moses: \"Mustere alle männliche Erstgeburt der Söhne Israels von einem Monat aufwärts! Erhebe die Zahl ihrer Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Für mich, den Herrn, nimm die Leviten anstatt aller israelitischen Erstgeburt und der Leviten Vieh anstatt aller Erstlingswürfe unter dem Vieh der Israeliten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Da musterte Moses nach des Herrn Befehl alle Erstgeburt unter den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Und die Zahl der Namen aller männlichen Erstgeburt von einem Monat aufwärts, nach ihren Ausgemusterten, war 22.273.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '\"Nimm die Leviten anstatt aller erstgeborenen Israeliten und der Leviten Vieh anstatt ihres Viehes! Die Leviten sollen mir, dem Herrn, gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Und für die Auslösung der 273 israelitischen Erstgeborenen, die über die Leviten überschüssig sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'erhebe für jeden Kopf fünf Ringe! Erhebe sie nach heiligem Gewicht! Den Ring zu zwanzig Korn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Und gib das Geld dem Aaron und seinen Söhnen zur Ablösung ihrer Überschüssigen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Und Moses erhob das Ablösungsgeld von denen, die überschüssig waren über die durch die Leviten Abgelösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Er erhob das Geld von den israelitischen Erstgeborenen, 1.365 (Ring) heiliges Gewicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Moses übergab das Ablösungsgeld dem Aaron und seinen Söhnen nach des Herrn Wort, wie es der Herr dem Moses befolgen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und der Herr sprach zu Moses und Aaron:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '\"Erhebt der Kehatsöhne Kopfzahl aus den anderen Levisöhnen, nach ihren Sippen und Familien');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreißig Jahren aufwärts bis zu fünfzig Jahren, alles, was zum Dienste kommt, an dem Festgezelt Arbeit zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies ist der Dienst der Kehatsöhne an dem Festgezelt, in hochheiligen Dingen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Beim Abzug des Lagers sollen Aaron und seine Söhne kommen und den hüllenden Vorhang abnehmen und die Zeugnislade mit ihm verhüllen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Darüber sollen sie eine weiche Lederdecke legen und oben darauf ein blaues Purpurtuch breiten und ihre Tragstangen einstecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Über den Schaubrottisch sollen sie ein blaues Purpurtuch breiten und darauf die Schüsseln, Schalen, Becher und Trankopferkannen stellen! Das stets aufgelegte Brot sei auch darauf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Darüber sollen sie Karmesintuch breiten, dies mit einer weichen Überdecke einpacken und die Tragstangen hineinstecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Dann sollen sie ein blaues Purpurtuch nehmen und damit den Leuchter, seine Lampen, seine Lichtscheren und Pfannen und all die Ölgefäße bedecken, mit denen man daran amtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Dann sollen sie ihn und alle seine Geräte in eine Hülle aus weichem Leder tun und ihn auf eine Tragbahre legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Ein blaues Purpurtuch sollen sie über den goldenen Altar breiten, ihn in eine weiche Lederdecke packen und seine Tragstangen hineinstecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Dann sollen sie alle dienstlichen Geräte nehmen, mit denen man im Heiligtum amtet, in ein blaues Purpurtuch wickeln, sie in eine weiche Lederdecke packen und auf die Tragbahre legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Dann sollen sie den Altar von seiner Asche reinigen und über ihn ein rotes Purpurtuch breiten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'und alle die Geräte darauflegen, mit denen man darauf amtet, die Pfannen, Gabeln, Schaufeln, Becken, kurz alle die Altargeräte! Sie sollen eine weiche Lederdecke darüber breiten und seine Tragstangen hineinstecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Sind Aaron und seine Söhne mit dem Einpacken des Heiligen und des ganzen Zubehörs des Heiligen fertig beim Aufbruch des Lagers, dann sollen die Kehatsöhne kommen, sie zu tragen! Sie dürfen aber das Heilige nicht berühren, sonst müßten sie sterben. Das ist das Trägeramt der Kehatsöhne am Festgezelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Zum Aufsichtsamt des Aaronsohnes und Priesters Eleazar gehört das Leuchteröl, das würzige Räucherwerk, das regelmäßige Speiseopfer und das Salböl, die Aufsicht über die ganze Wohnung und alles, was darin an Heiligem ist, und sein Zubehör.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und der Herr redete zu Moses und Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '\"Laßt nicht der Kehatitersippen Stamm aus den Leviten ausgerottet werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Tut dies für sie, daß sie leben und nicht sterben, wenn sie an das Hochheilige treten! Dann komme Aaron mit den Söhnen und stelle jene, Mann für Mann, an das, was sie zu leisten und zu tragen haben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'daß sie nicht hineinkommen und sehen, wie man das Heiligtum zerlegt, und sterben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '\"Du sollst auch der Gersonsöhne Kopfzahl aufnehmen, familienweise nach ihren Sippen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Von dreißig Jahren aufwärts bis zu fünfzig mustere sie, alle, die antreten, am Festgezelt Dienst zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Dies ist der Dienst der Gersonitersippen an Leistung und Tragen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Sie sollen die Teppiche der Wohnung tragen, des Festgezeltes Decke und die weiche Lederdecke obendrauf, den Vorhang der Festgezelttür,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'die Vorhofumhänge, den Vorhang vor der Toröffnung des Vorhofes rings um die Wohnung und den Altar, die Stricke und alle ihre anderen Dienstgeräte! Was daran zu tun ist, sollen sie dienstwillig tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Auf Aarons und seiner Söhne Geheiß erfolge der Gersonitersöhne Dienstleistung nach all ihrem Tragen und ihrer sonstigen Leistung! Ihr sollt ihnen all ihr Tragen zuordnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Dies ist der Dienst der Gersonitersöhnesippen am Festgezelt. Ihre Aufsicht stehe unter Itamar, dem Aaronsohn und Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Die Söhne Meraris sollst du nach ihren Sippen und Familien mustern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Von dreißig Jahren aufwärts bis zu fünfzig sollst du sie mustern, alle, die antreten, am Festgezelt Dienst zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Was ihre Pflicht zu tragen ist bei ihrem ganzen Dienst am Festgezelt, sind die Bretter der Wohnung, ihre Riegel, Säulen, Füße,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'die Vorhofsäulen ringsherum und ihre Füße, Pflöcke, Stricke samt allem Zubehör und allem, was es dabei zu besorgen gibt. Mit Namen sollt ihr die Geräte ihres pflichtigen Trägers angeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Dies ist der Dienst der Sippen der Merarisöhne bei ihrer Dienstleistung am Festgezelt unter Aufsicht Itamars, des Aaronssohnes und Priesters.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Moses und die Fürsten der Gemeinde musterten die Kehatitersöhne nach ihren Sippen und Familien');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren aufwärts bis zu fünfzig, alle, die antraten, am Festgezelt Dienst zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Ihrer Ausgemusterten waren es nach ihren Geschlechtern 2.750.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die aus den Kehatitersippen Ausgemusterten, alle, die am Festgezelt Dienste taten und die Moses und Aaron, auf des Herrn Befehl an Moses, gemustert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Die Ausgemusterten der Gersonsöhne nach ihren Sippen und Familien,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren aufwärts bis zu fünfzig, alle, die antraten, am Festgezelt Dienst zu tun,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'ihrer Ausgemusterten waren nach Sippen und Familien 2.630.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Dies sind die Ausgemusterten der Sippen der Gersonsöhne, alle, die am Festzelt Dienste taten und die Moses und Aaron nach des Herrn Befehl gemustert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Die Ausgemusterten der Sippen der Merarisöhne nach Sippen und Familien');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren aufwärts bis zu fünfzig, alle, die antraten, am Festzelt Dienst zu tun,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'ihrer Ausgemusterten waren nach Sippen 3.200.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die Ausgemusterten der Sippen der Merarisöhne, die Moses und Aaron nach des Herrn Befehl an Moses gemustert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'All die Ausgemusterten, die Moses, Aaron und die Fürsten Israels bei den Leviten musterten, nach ihren Sippen und Familien,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren aufwärts bis zu fünfzig, alle, die antraten, Dienst zu tun und das Trägeramt am Festzelt auszuüben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'ihrer Ausgemusterten waren 8.580.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach des Herrn Befehl stellte man sie unter Mosis Aufsicht, Mann für Mann bei ihrem Dienst und Trägeramt an, und die man anstellte, waren die, die der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und der Herr redete also mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '\"Befiehl den Söhnen Israels, sie sollen aus dem Lager jeden Aussatzverdächtigen entfernen, jeden Flüssigen und jeden an einer Leiche Verunreinigten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Männer und Weiber sollt ihr fortschaffen und vor das Lager sollt ihr sie schaffen, damit sie nicht ihr Lager unrein machen, weil ich unter ihnen wohne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Israeliten taten so. Sie schafften sie vor das Lager. Wie der Herr zu Moses gesprochen, so hatten die Israeliten getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '\"Sprich zu den Israeliten: \'Tut jemand, Mann oder Weib, irgendeine Menschensünde, in Untreue gegen den Herrn, und fühlt sich dieser schuldig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'dann soll er seine Sünde, die er getan, bekennen! Er gebe den veruntreuten Betrag zurück und darauf soll er ein Fünftel legen und er gebe es dem, gegen den er sich verschuldet hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Fehlt aber dem Mann ein Verwandter, dem man die Buße entrichten könnte, so fällt die schuldige Buße dem Herrn zum Besten der Priester zu, abgesehen vom Sühnewidder, mit dem man ihm Sühne schafft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Jede Weihegabe von all den heiligen Gaben, dem Priester von den Israeliten dargebracht, soll ihm gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Die ihm zustehenden Opfer sollen ihm gehören! Was jemand dem Priester gibt, soll ihm gehören!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '\"Sprich zu den Söhnen Israels und sage ihnen: \'Ist eines Mannes Weib ausschweifend und übt Trug an ihm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'und ein anderer wohnt ihr bei, und dies bleibt ihrem Manne verborgen, weil sie unentdeckt bleibt, so verunreinigt sie sich. Ein Zeuge aber fehlt gegen sie, und sie ward nicht ertappt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Nun kommt ein Geist der Eifersucht aber ihn, und er eifert auf sein Weib, die sich verunreinigt hat, oder ein Geist der Eifersucht kommt über ihn, und er eifert auf sein Weib, obschon sie sich nicht verunreinigt hat;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'dann führe der Mann sein Weib zum Priester und bringe ihr Opfer für sie mit, ein Zehntel Scheffel Gerstenmehl! Er soll aber kein Öl darüber gießen noch Weihrauch darauf tun! Es ist ein Eifersuchtsspeiseopfer, ein Offenbarungsspeiseopfer zum Offenbaren der Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Der Priester führe sie nun herbei und stelle sie vor den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Dann hole der Priester heiliges Wasser in einem Tongefäß! Auch etwas Staub vom Boden der Wohnung soll der Priester nehmen; dann tue er ihn in das Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Der Priester stelle dann das Weib vor den Herrn, bringe des Weibes Haupthaar in Unordnung und lege in ihre Hände das Offenbarungsspeiseopfer, das Eifersuchtsspeiseopfer! Aber in des Priesters Hand soll das fluchbringende Bitterwasser bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Dann beschwöre sie der Priester! Er spreche zum Weibe: Hat dir kein Mann beigewohnt und hast du dich nicht vergangen und verunreinigt, bist du vielmehr unter deinem Manne gewesen, dann schade dir nicht das fluchbringende Bitterwasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Wenn du dich aber hast vergangen, obwohl deinem Manne unterstehend, und bist du unrein geworden dadurch, daß ein Mann dir beigewohnt, von deinem Manne abgesehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'so beschwöre der Priester das Weib mit dem Fluchschwure! Und der Priester spreche so zu dem Weibe: Dich soll der Herr inmitten deines Volkes zum Fluche und zur Verwünschung machen! Der Herr gebe dir Fehlgeburten bei willigem Leibe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Dies fluchbringende Wasser komme in dein Eingeweide, den Leib willig zu machen, aber Fehlgeburten zu bewirken! Das Weib spreche: Amen! Amen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Dann schreibe der Priester die Verwünschungen auf eine Tafel, wische sie in das Bitterwasser');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'und lasse das Weib das fluchbringende Wasser trinken! So komme das fluchbringende Wasser in sie zu bitterem Wehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Dann nehme der Priester dem Weibe das Eifersuchtsspeiseopfer aus der Hand, weihe das Speiseopfer vor dem Herrn und bringe es zum Altar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Der Priester nehme vom Speiseopfer eine Handvoll als sein Teil und lasse es auf dem Altar verrauchen! Dann soll er das Weib das Wasser trinken lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und so er sie das Wasser trinken läßt, kommt, ist sie unrein und ihrem Marine untreu gewesen, das fluchbringende Wasser in sie zu bitterem Wehe. Ihr Leib wird zwar empfänglich sein; doch wird sie Fehlgeburten haben. So wird das Weib zum Fluche bei seinem Volke werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ist aber das Weib nicht unrein, sondern rein, so bleibt es unversehrt und bringt ein lebend Kind zu Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dies ist das Gesetz über die Eifersuchtsfälle: Vergeht sich ein Weib, ihrem Mann unterstehend, und wird es unrein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'oder kommt über einen Mann ein Geist der Eifersucht und eifert er auf sein Weib, so stelle er das Weib vor den Herrn, und der Priester tue an ihm genau nach diesem Gesetz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Der Mann bleibt dann von Verschuldung frei. Ein solches Weib aber lädt Schuld auf sich.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '\"Rede mit den Söhnen Israels und sage ihnen: \'Will jemand, Mann oder Weib, ein Nasiräergelübde ablegen, um sich dem Herrn zu weihen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'so soll er sich des Weines und des Bieres enthalten! Auch soll er keinen Essig von Wein oder Bier trinken! Er soll keinen Traubensaft trinken und keine Trauben essen, weder frisch noch getrocknet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Alle Tage seiner Weihe soll er nichts trinken, was vom Weinstock gemacht wird! Von den Kernen bis zur Hülse soll er nichts essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Die ganze Zeit seiner Weihe soll kein Schermesser über sein Haupt kommen, bis die Zeit erfüllt ist, für die er sich dem Herrn geweiht! Er ist dem Herrn heilig. Er lasse sein Haupthaar wachsen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Die ganze Zeit, die er sich dem Herrn geweiht, darf er zu keiner Leiche kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Er darf sich nicht unrein machen, weder an Vater noch Mutter noch Bruder noch Schwester, wenn sie sterben. Denn die Weihe an seinen Gott ist auf seinem Haupte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Alle Tage seiner Weihe ist er dem Herrn geweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Wenn aber neben ihm ganz plötzlich jemand stirbt und er macht seines Diadems Haupt unrein, dann schere er sein Haupt an dem Tage, an dem er wieder rein wird! Am siebten Tage soll er es scheren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Am achten Tage soll er zwei Turtel- oder junge Tauben zum Priester bringen an des Festgezeltes Pforte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Der Priester bereite die eine als Sündopfer, die andere als Brandopfer und schaffe ihm dafür Sühne, daß er sich an der Leiche verschuldet hat! Dann heilige er wieder sein Haupt am selben Tage,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'weihe sich weiter für die Tage seiner Weihe dem Herrn und bringe ein noch nicht jähriges Lamm als Schuldopfer dar! Die früheren Tage aber fallen weg, weil er sein Diadem entweiht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Dies ist das Gesetz über den Nasiräer: Wenn die Tage seiner Weihe erfüllt sind, soll man ihn an des Festgezeltes Pforte bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Er bringe dazu als seine Opfergabe dem Herrn ein noch nicht jähriges, fehlerloses Lamm zum Brandopfer, ein noch nicht jähriges, weibliches, fehlerloses Lamm zum Sündopfer, einen fehlerlosen Widder zum Dankopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'einen Korb ungesäuerter Kuchen von Feinmehl, mit Öl bereitet, ungesäuerte, mit Öl bestrichene Fladen sowie Speise- und Trankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Der Priester bringe es vor den Herrn und bereite sein Sünd- und Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Den Widder soll er als Dankopfer für den Herrn bereiten samt dem Korb mit dem Ungesäuerten! Auch sein Speise- und Trankopfer bereite der Priester!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Dann schere der Nasiräer vor des Festgezeltes Pforte sein geweihtes Haupt, nehme seines geweihten Hauptes Haar und werfe es in das Feuer, unter dem Dankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Dann nehme der Priester vom Widder den gekochten Bug und aus dem Korb einen ungesäuerten Kuchen sowie einen ungesäuerten Fladen und gebe es dem Nasiräer in die Hände, nachdem er sein Geweihtes abgeschoren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Dann weihe sie der Priester als Abgabe vor dem Herrn - eine zufallende heilige Gabe ist es für Priester - samt der Weihebrust und der Gabenkeule! Danach darf der Nasiräer Wein trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz über den Nasiräer, der ein Gelübde macht, sein Opfer für den Herrn seiner Weihe wegen, außer dem, was er noch leisten kann. Gemäß seinem gemachten Gelübde soll er also tun, nach dem Gesetz seiner Weihe!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und der Herr sprach zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '\"Sprich so zu Aaron und den Söhnen: \'So sollt ihr die Israeliten segnen und so zu ihnen sprechen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Dich segne der Herr und behüte dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Sein Antlitz lasse leuchten über dich der Herr und sei dir gnädig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Zuwende dir der Herr Sein Angesicht und schaffe dir so Frieden!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'So sollen sie meinen Namen auf die Israeliten legen! Dann werde ich sie segnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Nachdem Moses die Wohnung erstellt hatte, salbte er sie und weihte sie, ebenso alle ihre Geräte sowie den Altar und seine Geräte. Er salbte sie und weihte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Da brachten Israels Fürsten, ihre Familienhäupter, das sind die Stammesfürsten, Vorstände der Gemusterten, Opfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Sie brachten vor den Herrn als ihre Opfergaben sechs Dachwagen und zwölf Rinder, je einen Wagen von zwei Fürsten und je ein Rind von jedem. Sie brachten sie vor die Wohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Da sprach der Herr zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '\"Nimm sie von ihnen an! Sie sollen dem Dienst am Festgezelt dienen! Übergib sie den Leviten, jedem für seinen Dienst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da nahm Moses die Wagen und die Rinder und gab sie den Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei der Wagen und vier Rinder gab er den Söhnen Gersons für ihren Dienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Vier der Wagen und acht Rinder gab er den Söhnen Meraris für ihren Dienst unter Leitung des Priesters Itamar, des Aaronssohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Den Söhnen Kehats gab er nichts. Denn ihnen lag die Besorgung des Heiligtums ob, das sie auf der Schulter tragen mußten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Die Fürsten brachten ferner die Einweihungsgabe für den Altar an dem Tage, an dem er gesalbt ward. Die Fürsten brachten ihre Opfergabe vor den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Und der Herr sprach zu Moses: \"Je ein Fürst soll je an einem Tag seine Opfergabe zur Altarweihe bringen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Der am ersten Tage seine Gabe brachte, war Amminadabs Sohn Nachson vom Stamm Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'ein junger Stier, ein Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ein Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nicht jährige Lämmer. Das war die Opfergabe Nachsons, des Amminadabsohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage hatte Suars Sohn Netanel geopfert, der Fürst von Issakar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Er hatte als seine Opfergabe eine Silberschüssel gebracht, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Netanels, des Suarsohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage der Fürst der Zabulonsöhne Eliab, Chelons Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Gabe Eliabs, des Chelonsohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage der Fürst der Rubensöhne, Elisur, Sedeurs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
