INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Elisurs, des Sedeursohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage der Fürst der Simeonsöhne, Selumiel, der Sohn Surisaddais.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Selumiels, des Sohnes des Surisaddai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Am sechsten Tage der Fürst der Gadsöhne, Eljasaph, Deuels Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Eljasaphs, des Sohnes Deuels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Am siebenten Tage der Fürst der Ephraimsöhne, Elisama, Ammihuds Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Elisamas, des Sohnes Ammihuds.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Am achten Tage der Fürst der Manassesöhne Gamliel, Pedahsurs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Gabe Gamliels, des Sohnes Pedahsurs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage der Fürst der Benjaminsöhne, Abidan, Gideonis Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Abidans, des Gideonisohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Am zehnten Tage der Fürst der Dansöhne, Achiezer, der Sohn Ammisaddais.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Achiezers, des Sohnes des Ammisaddai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Am elften Tage der Fürst der Assersöhne, Pagiel, Okrans Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Pagiels, des Okransohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Am zwölften Tage der Fürst der Naphtalisöhne, Achira, Enans Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Seine Opfergabe war eine Silberschüssel, 130 Ringe schwer, ein Silberbecken, 70 Ringe schwer, nach heiligem Gewicht, beide mit Feinmehl gefüllt, das mit Öl zum Speiseopfer angemacht war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'eine Schale, 10 Goldringe schwer, mit Räucherwerk gefüllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'einen jungen Stier, einen Widder, ein noch nicht jähriges Lamm für das Brandopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'einen Ziegenbock für das Sündopfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke und fünf noch nichtjährige Lämmer. Das war die Opfergabe Achiras, des Enansohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Dies war von seiten der Fürsten der Israeliten die Altarweihegabe an dem Tage seiner Salbung, zwölf Silberschüsseln, zwölf Silberbecken und zwölf Goldschalen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'jede Schüssel 130 Silberringe, jedes Becken 70 Ringe schwer; das gesamte Silber der Gefäße betrug 2.400 Ringe nach heiligem Gewicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Zwölf Goldschalen, mit Räucherwerk gefüllt, jede Schale 10 Ringe schwer nach heiligem Gewicht; das gesamte Gold der Schalen betrug 120 Ringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Rinder zum Brandopfer waren es zusammen zwölf Farren, zwölf Widder, zwölf noch nicht jährige Lämmer nebst ihrem Speiseopfer und zwölf Ziegenböcke zum Sündopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Rinder zum Dankopfer waren es zusammen 24 Farren, 60 Widder, 60 Böcke und 60 noch nicht jährige Lämmer. Das war die Altarweihegabe nach seiner Salbung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Als Moses zum Festgezelt kam, mit ihm zu reden, hörte er die Stimme zu sich reden von der Deckplatte aus, die auf der Zeugnislade war, vom Orte zwischen den beiden Cheruben. So redete er zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '\"Sprich zu Aaron und melde ihm: \'Wenn du die Lampen anzündest, so sollen zum Leuchterschaft hin die sieben Lampen leuchten!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Und Aaron tat so. Er setzte seine Lampen gegen den Leuchterschaft hin, wie der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Die Arbeit am Leuchter war aus Gold getrieben. Der Schaft und seine Blüten waren getriebene Arbeit. Wie es dem vom Herrn dem Moses gezeigten Bild entsprach, so hatte er den Leuchter gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '\"Nimm die Leviten aus den Söhnen Israels und reinige sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Bei ihrer Reinigung sollst du also tun: Besprenge sie mit Entsündigungswasser! Sie sollen über ihren ganzen Leib ein Schermesser führen und ihre Kleider reinigen und sich so reinigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Dann sollen sie einen jungen Stier nehmen und ein Speiseopfer, Feinmehl mit Öl angemacht! Und zum Sündopfer sollst du einen zweiten jungen Stier nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Dann führe die Leviten vor das Festgezelt und versammle die israelitische Gesamtgemeinde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Dann führe die Leviten vor den Herrn! Die Israeliten sollen dann auf die Leviten ihre Hände legen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Und Aaron weihe die Leviten vor dem Herrn als heilige Gabe der Söhne Israels! So seien sie fähig, den Dienst des Herrn zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Die Leviten sollen ihre Hände auf den Farrenkopf legen! Den einen bereite zum Sündopfer, den anderen für den Herrn zum Brandopfer, um den Leviten Sühne zu schaffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Dann stelle die Leviten vor Aaron und seine Söhne und verpflichte sie für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'So sondere aus der Israeliten Mitte die Leviten aus! Die Leviten sollen mir gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Hernach mögen die Leviten zum Dienst am Festgezelt kommen! Du hast sie ja gereinigt und verpflichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Sie sind aus der Israeliten Mitte mir als Diener gegeben. An Stelle alles dessen, was jeden Mutterschoß durchbricht, aller Erstgeburt, nehme ich sie mir aus den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Denn mir gehört alle Erstgeburt der Söhne Israels, Mensch und Vieh. An dem Tage, da ich im Lande Ägypten alle Erstgeburt geschlagen, habe ich sie mir geheiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'An Stelle aller Erstgeburt der Israeliten nahm ich die Leviten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Als Diener gab ich die Leviten aus der Israeliten Mitte dem Aaron und seinen Söhnen, um am Festgezelt der Israeliten Dienst zu tun und so die Israeliten zu entsühnen, daß die Israeliten keine Plage befalle, wenn sich die Israeliten dem Heiligtum nahen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Moses, Aaron und die israelitische Gesamtgemeinde taten so mit den Leviten. Genauso, wie der Herr dem Moses für die Leviten geboten hatte, taten die Israeliten mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Die Leviten ließen sich entsündigen und reinigten ihre Kleider. Dann weihte sie Aaron vor dem Herrn. So schaffte ihnen Aaron zu ihrer Reinigung Sühne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Hernach kamen die Leviten, ihren Dienst am Festgezelt zu tun vor Aaron und seinen Söhnen. Wie der Herr dem Moses für die Leviten geboten, so haben sie mit ihnen getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Und der Herr redete mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '\"Das ist es, was für den Leviten gilt: Von fünfundzwanzig Jahren aufwärts soll er eintreten, Dienste bei des Festgezeltes Besorgung zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Von fünfzig Jahren ab soll er der Dienstpflicht ledig sein und nicht mehr dienen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Er sei zwar seinen Brüdern im Festgezelt bei der Wartung des Amtes behilflich! Aber Dienste soll er nicht mehr tun! Also sollst du mit den Leviten bei ihren Ämtern tun!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Und der Herr redete mit Moses in der Wüste Sinai, im zweiten Jahre nach ihrem Auszuge aus Ägypterland, am ersten Neumond also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '\"So sollen die Israeliten zu seiner Zeit das Passah feiern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Am vierzehnten des Monats gegen Abend sollt ihr es zu seiner Zeit feiern! Nach all seinen Satzungen und Ordnungen sollt ihr es feiern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Moses sagte nun den Israeliten, sie sollten das Passah feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Da feierten sie das Passah am vierzehnten Tag des ersten Monats gegen Abend in der Wüste Sinai. Genauso, wie der Herr dem Moses geboten hatte, taten die Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Da waren aber Männer, die durch eine menschliche Leiche unrein geworden waren. So konnten sie am selben Tag das Passah nicht feiern. Sie kamen nun vor Moses und Aaron an jenem Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Und die Männer sprachen zu ihnen: \"Wir sind durch eine menschliche Leiche unrein geworden. Warum sollen wir verkürzt werden, wenn wir die Opfergabe für den Herrn inmitten Israels nicht zu seiner Zeit darbringen dürfen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Moses sprach zu ihnen: \"Wartet, bis ich höre, was der Herr für euch verordnet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '\"Sag den Söhnen Israels: \'Wird jemand bei euch oder euren Nachkommen durch eine Leiche unrein oder ist er auf fernem Wege, so feiere er dennoch dem Herrn Passah!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Am vierzehnten des zweiten Monats gegen Abend sollen sie es feiern! Zu ungesäuertem Brote und bitteren Kräutern sollen sie es essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Sie dürfen bis zum Morgen nichts übriglassen! Sie dürfen auch kein Gebein an ihm brechen. Nach aller Passahsatzung sollen sie es feiern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Der Mann, der rein und nicht auf Reisen ist und die Passahfeier versäumt, ein solcher werde aus den Reihen des Volkes gestrichen! Denn er bringt nicht die Opfergabe für den Herrn zu seiner Zeit dar. Ein solcher Mann lädt Schuld auf sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Weilt bei euch ein Fremdling und feiert er dem Herrn Passah, so soll er es nach der Passahordnung und Passahsatzung feiern. Nur eine Satzung soll bei euch für Fremde wie für Landeseingeborene gelten!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'An dem Tage aber, da man die Wohnung erstellte, hüllte die Wolke die Wohnung des Zeugniszeltes ein. Am Abend aber war es über der Wohnung wie ein Feuerschein bis zum Morgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'So war es stets. Die Wolke hüllte sie bei Tage ein und ein Feuerschein bei Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Sooft die Wolke vom Zelt aufstieg, zogen danach die Israeliten fort. Und an dem Ort, an dem sich die Wolke niederließ, dort lagerten die Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Nach des Herrn Geheiß zogen die Israeliten fort und nach des Herrn Befehl lagerten sie. Alle Tage, da die Wolke auf der Wohnung ruhte, lagerten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Verblieb auch die Wolke viele Tage auf der Wohnung, so fügten sich die Israeliten doch der Fügung des Herrn und zogen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Manchmal aber blieb die Wolke wenige Tage über der Wohnung; doch nach des Herrn Geheiß lagerten sie und nach des Herrn Geheiß zogen sie weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Manchmal blieb die Wolke nur vom Abend bis zum Morgen. Stieg die Wolke am Morgen auf, dann zogen sie weiter. Oder nur einen Tag und eine Nacht; stieg dann die Wolke auf, dann zogen sie weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Oder nur ein paar Tage oder einen Monat oder noch längere Zeit; wenn die Wolke über der Wohnung länger verzog, dann lagerten die Israeliten und zogen nicht weiter. Stieg sie aber auf, dann zogen sie weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Nach des Herrn Geheiß lagerten sie und nach des Herrn Geheiß zogen sie. So hatten sie sich der Fügung des Herrn gefügt, nach dem Geheiß des Herrn an Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '\"Mach dir zwei silberne Trompeten! In getriebener Arbeit sollst du sie machen! Sie sollen dir zur Einberufung der Gemeinschaft dienen und zum Abbruch der Lager!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Bläst man sie, dann sammle sich die Gesamtgemeinde bei dir an des Festgezeltes Pforte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Bläst man nur eine, dann sollen sich bei dir die Fürsten, die israelitischen Stammeshäupter, sammeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Blast ihr Lärm, dann sollen die Lager, die gen Osten lagern, ausziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Blast ihr zum zweitenmal Lärm, dann sollen die Lager, die gen Süden lagern, ausziehen! Sie sollen Lärm blasen, wenn sie aufbrechen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Wenn man aber die Gemeinschaft sammelt, sollt ihr blasen, aber nicht schmettern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'In die Trompeten sollen nur die Priester, Aarons Söhne, stoßen! Sie seien euch zum ewigen Gebrauch für eure Geschlechter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Wenn ihr Krieg bekommt in eurem Lande mit dem Feind, der euch drängt, und wenn ihr in die Trompeten schmettert, dann wird euer vor dem Herrn, eurem Gott, gedacht, und ihr werdet von euren Feinden befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'An eurem Siegestag, an euren Festtagen und Neumonden stoßt zu euren Brandopfern in die Hörner sowie zu euren Dankopfern, daß sie von eurem Gott euch angerechnet werden! Ich, der Herr, bin euer Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Im zweiten Jahre, am zwanzigsten des zweiten Monats, stieg die Wolke von der Zeugniswohnung auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Da zogen die Israeliten zugweise aus der Wüste Sinai fort. Die Wolke aber ließ sich in der Wüste Paran nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'So zogen sie erstmals auf das Geheiß des Herrn an Moses weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Zuerst zog das Lagerbanner der Judasöhne aus, Schar für Schar, an der Spitze seiner Schar Nachson, Amminadabs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'An der Spitze der Stammesschar der Issakarsöhne war Netanel, Suars Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'An der Spitze der Stammesschar der Zabulonsöhne war Eliab, Chelons Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Dann ward die Wohnung abgebrochen. Da zogen die Söhne Gersons und Meraris, die Träger der Wohnung, ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Dann brach das Lagerbanner Rubens auf, Schar für Schar. An der Spitze seiner Schar war Elisur, Sedeurs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'An der Spitze der Stammesschar der Simeonsöhne war Selumiel, Surisaddais Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'An der Spitze der Stammesschar der Dansöhne war Eljasaph, Deuels Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Dann zogen die Kehatiter, die Träger des Heiligtumes, ab. Sie erstellten die Wohnung bis zu ihrer Ankunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Dann brach das Lagerbanner der Ephraimsöhne auf, Schar für Schar. An der Spitze seiner Schar Elisama, Ammihuds Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'An der Spitze der Stammesschar der Manassesöhne war Gamliel, Pedahsurs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'An der Spitze der Stammesschar der Benjaminsöhne war Abidan, Gideonis Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Dann brach das Lagerbanner der Dansöhne auf. Dies war die Nachhut für alle Lager, Schar für Schar. An der Spitze der Schar war Achiezer, Ammisaddais Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'An der Spitze der Stammesschar der Assersöhne war Pagiel, Okrans Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'An der Spitze der Stammesschar der Naphtalisöhne war Achira, Enans Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Dies sind die Auszüge der Israeliten, Schar für Schar. So zogen sie dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Da sprach Moses zu Reuels Sohn Chobab, dem Midianiter, Mosis Schwiegervater: \"Wir ziehen nach dem Ort, von dem der Herr gesagt: \'Ich geb ihn euch.\' Zieh mit uns! Wir wollen dir Gutes tun. Der Herr hat ja Israel alles Gute verheißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Er sprach zu ihm: \"Ich gehe nicht mit. Ich gehe wieder in mein Land und zu meiner Verwandtschaft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Da sprach er: \"Verlaß uns doch nicht! Du weißt am besten, wo wir in der Wüste uns lagern können. Sei uns Auge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Gehst du mit uns, dann tun wir dir Gutes mit all dem, was der Herr uns geben wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'So zogen sie von dem Berge des Herrn drei Tagereisen weiter, und die Bundeslade des Herrn zog vor ihnen her, einen Ruheort für sie zu erkunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Die Wolke des Herrn aber stand über ihnen bei Tage, als sie aus dem Lager zogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Als die Lade auszog, sprach Moses: \"Auf! Herr! Zerstieben sollen Deine Feinde und Deine Hasser vor Dir fliehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Und als sie ruhte, sprach er: \"Heimkehre, Herr, der unermeßlich Israel liebt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Als aber das Volk Wehklagenden glich, war es übel in des Herrn Ohren. Der Herr hörte es nämlich. Da entbrannte sein Zorn. Und des Herrn Feuer flammte in sie und fraß am wichtigsten Teile des Lagers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Da schrie das Volk zu Moses. Und Moses betete zum Herrn. Da versank das Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Den Ort aber nannte er Tabera, weil des Herrn Feuer in sie geflammt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Aber das Gesindel unter ihnen hatte ein heftiges Gelüste bekommen. Da weinten auch die anderen Israeliten wieder und sprachen: \"Wer gibt uns Fleisch zu essen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Vergebens gedenken wir der Fische, die wir in Ägypten aßen, der Gurken und Melonen, des Lauchs, der Zwiebeln und des Knoblauchs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Jetzt aber ist unsere Seele kraftlos. Nichts ist da, und wir sehen nichts als das Manna.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Das Manna aber war wie Koriandersame und sah aus wie Edelharz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Das Volk lief umher und las es auf, zerrieb es in der Handmühle oder zerstieß es im Mörser. Dann kochten sie es im Topf und machten Fladen daraus. Es schmeckte wie Ölkuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Fiel der Tau nachts auf das Lager, dann fiel das Manna darauf herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Moses hörte nun das Volk sippenweise weinen, jeden vor seiner Zelttür. Da entbrannte fürchterlich des Herrn Zorn. Dies aber mißfiel Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Und Moses sprach zum Herrn: \"Warum tust Du übel an Deinem Knechte? Warum erregte ich Dein Mißfallen, daß Du des ganzen Volkes Last auf mich legst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Bin ich etwa mit all diesem Volke schwanger gegangen? Habe ich es geboren, daß Du mir sagen könntest: \'Trag es an deinem Busen, wie die Wärterin den Säugling in das Land, das du seinen Vätern einst zugeschworen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Woher nehme ich Fleisch, um es all dem Volk zu geben? Sie weinen mich ja an und sagen: \'Gib uns Fleisch zu essen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ich kann allein die Last dieses ganzen Volkes nicht tragen. Sie ist zu schwer für mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Willst Du mir solches antun, dann töte mich lieber, wenn ich noch Gnade in Deinen Augen finde, daß ich nicht mein Elend ansehen muß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Da sprach der Herr zu Moses: \"Rufe mir siebzig Männer aus den Ältesten Israels, die du als Volksälteste und Beamte kennst! Nimm sie mit dir zum Festgezelt! Hier sollen sie neben dich treten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Dann steige ich hinab und rede dort zu dir und nehme von dem Geist auf dir etwas weg und lege es auf sie. So können sie mit dir an des Volkes Last tragen, und du mußt sie nicht allein tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Zum Volke aber sollst du sprechen: \'Bereitet euch für morgen! Ihr bekommt Fleisch zu essen. Ihr habt vor des Herrn Ohren geweint: Wer gibt uns Fleisch zu essen? Wir hatten es in Ägypten besser gehabt.\' So gibt euch der Herr Fleisch und ihr sollt es essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nicht einen Tag bekommt ihr es zu essen, nicht zwei, nicht fünf, nicht zehn, nicht zwanzig Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Nein! Einen vollen Monat lang, bis es euch zur Nase herausfährt und euch zum Ekel wird. Weil ihr den Herrn in eurer Mitte so mißachtet und weinend vor ihm gerufen habt: \'Wozu doch sind wir aus Ägypten weggezogen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Da sprach Moses: \"Das Volk in dessen Mitte ich weile, zählt sechshunderttausend rüstige Leute, und Du sagst: \'Ich gebe ihnen Fleisch, daß sie einen vollen Monat essen können.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Kann man so viele Schafe und Rinder für sie schlachten, daß es für sie reicht, oder soll man im Meer alle Fische für sie fangen, daß es ihnen reicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Da sprach der Herr zu Moses: \"Ist des Herrn Hand verkürzt? Du wirst bald sehen, ob mein Wort bei dir eintrifft oder nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Da ging Moses hinaus und berichtete des Herrn Worte dem Volk. Dann holte er siebzig Männer aus den Ältesten des Volkes und stellte sie rings um das Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Da fuhr der Herr nieder im Gewölk und redete mit ihm. Dann nahm er von dem Geiste auf ihm etwas weg und legte es auf die siebzig Ältesten. Und wie der Geist über ihnen ruhte, weissagten sie, ohne etwas hinzuzufügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Zwei Männer aber waren im Lager geblieben. Der eine hieß Eldad, der andere Medad. Auch auf sie ließ sich der Geist nieder. Sie waren nämlich unter den Aufgeschriebenen, waren aber nicht zum Zelt gegangen. So weissagten sie im Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Da lief der Diener hin und meldete es Moses und sprach: \"Eldad und Medad weissagen im Lager.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Josue, Nuns Sohn und Mosis Diener von Jugend auf, hob an und sprach: \"Herr! Moses! Wehr es ihnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Da sprach Moses zu ihm: \"Ereiferst du dich für mich? Bestände doch des Herrn ganzes Volk aus Propheten, daß seinen Geist der Herr auf sie legte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Darauf zog sich Moses ins Lager zurück, er und die Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Da kam vom Herrn her ein Wind. Und er trieb Wachteln vom Meere herüber und ließ sie auf das Lager fallen, eine Tagereise nach jeder Richtung rings um das Lager, bis zu zwei Ellen hoch über dem Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Da machte sich das Volk daran, jenen ganzen Tag, die ganze Nacht und den ganzen folgenden Tag die Wachteln zu sammeln. Wer nur wenig sammelte, kam auf zehn Malter. Sie aber breiteten sich um das Lager aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Das Fleisch aber war noch zwischen ihren Zähnen unverkaut, als schon des Herrn Zorn in das Volk brannte. Und der Herr schlug in das Volk mit einem sehr großen Schlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Daher hieß man jenen Ort \"Gräber des Gelüstes\", weil man dort das Volk der Lüsternen begraben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Von den \"Gräbern des Gelüstes\" zog das Volk nach Chaserot. In Chaserot aber blieben sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mirjam und Aaron aber sprachen über Moses wegen des kuschitischen Weibes, das er genommen, daß er überhaupt ein kuschitisches Weib geheiratet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Sie sprachen: \"Hat denn der Herr bloß mit Moses geredet? Hat er nicht auch mit uns geredet?\" Der Herr aber hörte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Der Mann Moses aber war überaus tugendhaft, mehr als alle anderen Menschen auf Erden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Da sprach der Herr plötzlich zu Moses, zu Aaron und zu Mirjam: \"Geht alle drei hinaus zum Festgezelt!\" Und die drei gingen hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Da fuhr der Herr in einer Wolkensäule nieder und trat unter die Zelttür mit dem Rufe: \"Aaron! Mirjam!\" Und sie kamen beide heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Da sprach er: \"Hört meine Worte! Ist euer einer ein Prophet des Herrn, dann offenbare ich mich durch das Gesicht und rede zu ihm im Traume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Nicht so bei meinem Diener Moses! Er ist mit meinem ganzen Hauswesen vertraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Von Mund zu Munde rede ich mit ihm. Des Herrn unverschleiertes Bild und des Herrn Gestalt schaut er. Warum habt ihr euch nicht gescheut, über meinen Diener Moses zu sprechen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'So entbrannte der Zorn des Herrn gegen sie, und er ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Wie aber die Wolke vom Zelte wich, war Mirjam aussätzig wie Schnee, und als Aaron Mirjam betrachtete, war sie wirklich aussätzig geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Da sprach Aaron zu Moses: \"Ach, mein Herr! Laß uns nicht dafür büßen, daß wir so töricht gewesen und gesündigt haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Sei sie doch nicht wie eine Tote! Wir entstammen demselben Mutterleibe, und so würde schon unseres Fleisches Hälfte verzehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Und Moses schrie zum Herrn mit den Worten: \"Ach Gott! Heile sie doch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Und der Herr sprach zu Moses: \"Hätte ihr Vater ihr ins Gesicht gespieen, müßte sie sich nicht sieben Tage schämen? So bleibe sie sieben Tage aus dem Lager ausgesperrt! Danach werde sie zurückgeholt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Und Mirjam ward sieben Tage aus dem Lager ausgesperrt; das Volk aber zog nicht weiter, bis Mirjam zurückgeholt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Danach zog das Volk von Chaserot hinweg und lagerte in der Wüste Paran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Und der Herr redete mit Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '\"Entsende Männer, daß sie das Land von Kanaan auskundschaften, das ich den Söhnen Israels geben will! Je einen aus dem Stamm seiner Väter sollt ihr senden, jeder unter ihnen ein Fürst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'So entsandte sie Moses aus der Wüste Paran nach des Herrn Befehl, lauter Männer, die Häupter der Israeliten waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Dies sind ihre Namen: vom Stamme Ruben: Sammua, Zakkurs Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'vom Stamme Simeon: Saphat, Choris Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'vom Stamme Juda: Kaleb, Jephunnes Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Vom Stamme Issakar: Igal, Josephs Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'vom Stamme Ephraim: Hosea, Nuns Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'vom Stamme Benjamin: Palti, Raphus Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'vom Stamme Zabulon: Gaddiel, Sodis Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'vom Stamme Joseph: vom Stamme Manasse Gaddi, Susis Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'vom Stamme Dan: Ammiel, Gemallis Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'vom Stamme Asser: Setur, Michaels Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'vom Stamme Naphtali: Nachbi, Wophsis Sohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'vom Stamme Gad: Geuel, Makis Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Dies sind die Namen der Männer, die Moses zur Auskundschaftung des Landes, ausgesandt hat. Moses aber nannte Hosea, Nuns Sohn, Josue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'So sandte sie Moses aus, das Land Kanaan auszukundschaften. Er sprach zu ihnen: \"Zieht in das Südland hier hinauf! Ersteigt das Gebirge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Beschauet das Land wie es ist und seht zu, und ob das Volk darin stark oder schwach, wenig oder zahlreich ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'und wie die Gegend, in der es wohnt, ob schön oder häßlich, und wie die Städte sind, die es bewohnt, ob sie in Dörfern oder festen Städten wohnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'und wie der Boden ist, ob mager oder fett, ob Bäume daraufstehen oder nicht! So gebt euch Mühe und nehmt aus dem Lande ein paar Früchte mit!\" Es war nämlich gerade die Zeit der ersten Weintrauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Da zogen sie hinauf und durchforschten das Land von der Wüste Sin bis Rechob, Chamat zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Dann zogen sie in das Südland bis Chebron hinauf. Dort waren Achiman, Sesai und Talmai, die Enaksprößlinge. An Chebron aber war sieben Jahre, vor Tanis in Ägypten, gebaut worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Sie kamen nun in das Traubental und schnitten dort eine Rebe mit einer einzigen Traube ab und trugen sie zu zweien an einer Stange, auch Granatäpfel und Feigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Jenen Ort nannte man das Traubental wegen der Traube, die dort die Israeliten geschnitten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Nach vierzig Tagen kehrten sie von der Auskundschaftung des Landes zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Sie zogen heim und kamen zu Moses, Aaron und der israelitischen Gesamtgemeinde in die Wüste Paran nach Kades. Sie brachten ihnen und der ganzen Gemeinschaft Bescheid und zeigten ihnen des Landes Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Und sie erzählten ihnen und sprachen: \"Wir sind in das Land gekommen, in das du uns gesandt hast. Wahr ist es: Es fließt von Milch und Honig, und dies sind seine Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Nur, daß das Volk im Lande trotzig und die Städte fest und sehr groß sind. Auch haben wir dort die Enaksprößlinge erblickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Im Südland wohnt Amalek, auf dem Gebirge die Chittiter, Jebusiter und Amoriter, am Meer und am Jordan die Kanaaniter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Da drängte sich Kaleb durch das Volk zu Moses und sprach: \"Wir wollen dennoch hinaufziehen und es erobern. Wir können es gut bewältigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Aber die Männer, die mit ihm hinaufgezogen, sprachen: \"Wir können gegen dieses Volk nicht ziehen. Es ist für uns viel zu stark.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Und sie berichteten den Israeliten Schlimmes über das Land, das sie ausgekundschaftet hatten, und sprachen: \"Das Land, das wir zur Erkundung durchzogen haben, überfüttert seine Einwohner. Alle Leute, die wir darin gesehen, sind ungewöhnlich groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Wir haben dort die Riesen geschaut, die Enaksöhne unter den Riesen. Wir kamen uns vor wie Heuschrecken. Auch ihnen sind wir so vorgekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Da erhob die ganze Gemeinde ihre Stimme und ließ sie erschallen. Und das Volk weinte in jener Nacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'und alle Israeliten murrten wider Moses und Aaron, und die ganze Gemeinde sprach zu ihnen: \"Wären wir doch im Ägypterlande oder in der Wüste hier gestorben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Warum bringt uns der Herr in dieses Land? Damit wir durch das Schwert fallen? Zur Beute werden unsere Weiber und unsere Kinder. Wäre es für uns nicht besser, nach Ägypten zurückzukehren?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Und sie sprachen zueinander: \"Laßt uns den Kopf daran setzen und kehren wir nach Ägypten zurück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Da fielen Moses und Aaron auf ihr Antlitz vor der ganzen versammelten israelitischen Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Josue aber, Nuns Sohn, und Jephunnes Sohn, Kaleb, die zu den Kundschaftern des Landes gehörten, hatten ihre Kleider zerrissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Sie sprachen zur ganzen israelitischen Gemeinde also: \"Das Land, das wir durchzogen, es auszuspähen, ist ein treffliches Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Ist uns der Herr geneigt, dann bringt er uns in dieses Land und gibt es uns, ein Land von Milch und Honig fließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Empört euch doch nicht gegen den Herrn! Das Volk des Landes aber fürchtet nicht! Wir werden sie aufzehren. Von ihnen ist ihr Schutz gewichen; mit uns aber ist der Herr. Habt keine Furcht vor ihnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Aber die ganze Gemeinde besprach sich schon, sie zu steinigen. Da erschien des Herrn Herrlichkeit am Festgezelt allen Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Und der Herr sprach zu Moses: \"Wie lange höhnt mich dieses Volk? Wie lange schenkt es mir keinen Glauben, trotz aller Zeichen, die ich unter ihm getan?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Ich schlage es mit der Pest und vertilge es. Dich aber mache ich zu einem Volke, größer und zahlreicher als jenes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Da sprach Moses zum Herrn: \"So? Daß Ägypten davon hört! Hast Du doch dieses Volk in Deiner Kraft aus seiner Mitte heraufgeführt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Daß dieses Landes Bewohner davon reden! Sie, die gehört, daß Du, der Herr, inmitten dieses Volkes weilst, daß Du Auge in Auge erscheinst und daß Deine Wolke über ihnen schwebt und daß Du in einer Wolkensäule vor ihnen herschreitest bei Tag und des Nachts in einer Feuersäule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Tötest Du nun dies Volk wie einen Mann, so werden die Heiden die Kunde von Dir vernehmen und sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '\'Weil der Herr nicht mehr imstande ist, dies Volk in jenes Land zu bringen, das er ihnen zugeschworen, darum metzelt er sie in der Wüste hin.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Nun zeige sich groß, Herr, Deine Langmut, wie Du verheißen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '\'Zum Zorne ist der Herr langsam, aber reich an Huld und verzeiht Missetat und Sünde; doch läßt er nicht ganz ungestraft. Er ahndet Väterschuld noch an den Kindern, am dritten und am vierten Gliede.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Vergib doch dieses Volkes Missetat nach der Größe Deiner Gnade! So, wie Du diesem Volke von Ägypten bis auf heute hast vergeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Da sprach der Herr: \"Ich verzeihe nach deinem Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'So wahr ich aber lebe! Die ganze Erde wird voll vom Ruhme des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Denn die Männer alle, die meinen Ruhm und meine Zeichen, die ich in Ägypten und in der Wüste gewirkt, geschaut und dennoch mich zehnmal versucht und nicht auf meine Stimme gehört haben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'werden nimmermehr das Land sehen, das ich euren Vätern zugeschworen. Nicht einer von all denen, die mich verhöhnt, soll es je schauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Doch meinen Diener Kaleb, mit dem ein anderer Geist gewesen und der mir Ehrfurcht zollte, bringe ich in das Land, in das er gekommen. Er soll es auf seine Nachkommen vererben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'In der Niederung und auf dem Gebirge aber bleiben die Amalekiter und die Kanaaniter. Morgen wendet euch und zieht in die Wüste, dem Schilfmeer zu!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Und der Herr redete zu Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '\"Wie lange soll dies der bösen Gemeinde eigen sein, daß sie gegen mich murrt? Der Israeliten Gemurr gegen mich habe ich vernommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sage ihnen: \'So wahr ich lebe\', ein Spruch des Herrn, \'wie ihr es laut vor mir ausgesprochen, so tue ich euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Eure Leichname sollen in dieser Wüste niedersinken, alle eure Gemusterten, die ganze Zahl von zwanzig Jahren aufwärts, wie ihr mir gegenüber gemurrt habt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Nie kommt ihr in das Land, das ich euch zum Wohnsitz eidlich angewiesen. Nur Kaleb, Jephunnes Sohn, und Josue, der Sohn des Nun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Doch eure kleinen Kinder, von denen ihr gesagt, sie werden zur Beute, die bringe ich hinein. Sie werden das Land kennenlernen, das ihr verschmäht habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Aber eure Leichen bleiben hier in dieser Wüste liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Und eure Söhne werden in der Wüste vierzig Jahre lang weiden müssen und so für euer Murren büßen, bis eure Leiber in der Wüste aufgerieben sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'nach der Zahl jener vierzig Tage, da ihr das Land ausgespäht habt. Je einen Tag für ein Jahr sollt ihr eure Sünden vierzig Jahre lang büßen, daß ihr erfahret meine Entfremdung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ich sage es, der Herr: Ich tue wahrlich so mit dieser ganzen bösen Gemeinde, die sich gegen mich zusammengerottet. In dieser Wüste sollen sie hinschwinden! Hier sollen sie sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Und die Männer, die Moses zur Erkundung des Landes entsandt hatte und die nach der Rückkehr die ganze Gemeinde zum Murren wider ihn aufhetzten, da sie Schlimmes gegen das Land vorbrachten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'diese Männer, die Schlimmes gegen das Land vorgebracht, werden vor dem Herrn am Schlage sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Josue, Nuns Sohn, aber und Jephunnes Sohn Kaleb, sollen von diesen Männern, die zur Erkundung des Landes ausgezogen, am Leben bleiben!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Als Moses alle diese Worte sämtlichen Israeliten verkündete, ward das Volk sehr traurig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Und sie zogen am anderen Morgen in der Frühe auf den Kamm des Gebirges und sprachen: \"Nun ziehen wir doch hinauf in das Gebiet, von dem der Herr geredet. Wir haben ja gesündigt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Da sprach Moses: \"Warum wollt ihr des Herrn Befehl jetzt übertreten? Das kann nicht gelingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Zieht nicht hinauf! Der Herr ist nicht in eurer Mitte. Ihr werdet sonst vor eure Feinde hingestoßen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Dort stehen ja die Amalekiter und die Kanaaniter euch gegenüber. Ihr fallt durch das Schwert. Denn ihr habt euch vom Herrn abgewandt. Darum ist der Herr nicht mit euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Doch sie vermaßen sich, zum Kamme des Gebirges zu ziehen. Aber die Bundeslade des Herrn und Moses waren nicht aus dem Lager gewichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Da stiegen die Amalekiter herab und die Kanaaniter, die auf jenem Gebirge saßen, schlugen sie und zersprengten sie bis Chorma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Und der Herr redete also mit Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '\"Sprich zu den Söhnen Israels und sag zu ihnen: Kommt ihr in eurer Siedlungen Land, das ich euch gebe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'und wollt ihr ein Mahl für den Herrn bereiten, Brand- oder Schlachtopfer, um ein Gelübde zu erfüllen oder als freie Gabe oder bei euren Festen, um von den Rindern oder Schafen dem Herrn einen süßen Duft zu bereiten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'dann bringe der, der dem Herrn seine Opfergabe bringt, als Speiseopfer ein Zehntel feines Mehl dar, mit einem Viertel Krug Öl zubereitet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Einen Viertelkrug Wein sollst du zum Trankopfer bei Brand- und Schlachtopfer für je ein Lamm herrichten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Für einen Widder richte als Speiseopfer her zwei Zehntel feines Mehl, mit einem Drittel Krug Öl zubereitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'an Wein zum Trankopfer einen Drittelkrug! So kannst du dem Herrn einen süßen Duft darbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Willst du einen jungen Stier als Brand- oder als Schlachtopfer herrichten, um ein Gelübde zu erfüllen oder als ein Dankopfer für den Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'dann bringe man zu dem jungen Rind als Speiseopfer drei Zehntel Feinmehl dar und mache es mit einem halben Krug Öl an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'An Wein sollst du zum Trankopfer einen halben Krug bringen, als ein Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Bei jedem Rinde oder Widder oder jedem Lamme von Schafen oder Ziegen tue man also!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Entsprechend der Zahl, die ihr herrichtet, sollt ihr bei jedem einzelnen also tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jeder Eingeborene soll diese so bereiten, will er dem Herrn ein Mahl süßen Duftes darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Weilt ein Fremdling bei euch, oder wer bei euch sei in euren Geschlechtern, und will er dem Herrn ein Mahl süßen Duftes bereiten, so soll er so tun, wie ihr tut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Für euch wie für den Fremdling gelte eine Gemeindesatzung! Auch euren Nachkommen gelte diese ewige Satzung. Wie ihr, so soll auch der Fremdling vor dem Herrn sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Ein Gesetz und eine Ordnung sollen für euch und für den Fremdling, der bei euch weilt, gelten!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Und der Herr sprach also zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '\"Sprich zu den Söhnen Israels und sag zu ihnen: Kommt ihr in dieses Land, in das ich euch bringe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'und eßt ihr von dem Korne des Landes, dann sollt ihr eine Weihegabe dem Herrn darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Von eures Teiges erstem Abhub sollt ihr einen Kuchen als Gabe abgeben. Wie eine Tennengabe sollt ihr sie darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Von eures Teiges erstem Abhub sollt ihr dem Herrn eine Abgabe machen von Geschlecht zu Geschlecht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Vergeht ihr euch ohne Vorsatz und erfüllt ihr eines der Gebote nicht, die der Herr dem Moses gegeben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'irgend etwas von dem, was durch Moses der Herr euch geboten, von dem Tage an, da der Herr Gebote gegeben, und weiterhin, für die Geschlechter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'so sei es: Ist das Versehen von seiten der Gemeinde erfolgt, dann bereite die Gesamtgemeinde einen jungen Stier zum Brandopfer, zu süßem Dufte für den Herrn, und nach Gebühr sein Speise- und Trankopfer und einen Ziegenbock zum Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'So schaffe der Priester der ganzen israelitischen Gemeinde Sühne! Dann wird ihnen vergeben werden. Ein Versehen ist es, und sie sollen ihre Opfergabe als Mahl für den Herrn darbringen und wegen des Versehens vor dem Herrn ihr Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'So werde der ganzen israelitischen Gemeinde vergeben sowie dem Fremdling in ihrer Mitte; denn er gehört zu dem Volk im Falle einer Irrung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Sündigt aber eine einzelne Person unvorsätzlich, so bringe sie eine noch nicht jährige Ziege als Sündopfer dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Und der Priester schaffe Sühne der Person, die sich durch ein Versehen unvorsätzlich vor dem Herrn vergeht, durch Vollzug der Sühnegebräuche! So werde ihr vergeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Für den Eingeborenen Israeliten und den Fremdling in eurer Mitte gilt ein Gesetz für euch, wenn jemand unvorsätzlich handelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Die Person aber, die vorsätzlich sündigt, eingeboren oder fremd, lästert den Herrn. Diese Person soll aus ihrem Volke gestrichen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Denn sie hat das Wort des Herrn verspottet und sein Gebot zerrissen. Diese Person werde unerbittlich gestrichen! Ihre Schuld komme auf sie!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Als die Israeliten in der Wüste waren, ertappten sie einen Mann, der am Sabbattage Holz las.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Da brachten ihn die Leute, die ihn beim Holzlesen ertappt, zu Moses und Aaron und zu der ganzen Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Und sie legten ihn in Gewahrsam, weil noch nicht entschieden war, was ihm zu tun sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Da sprach der Herr zu Moses: \"Der Mann soll den Tod erleiden! Die Gesamtgemeinde steinige ihn außerhalb des Lagers!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Da führte ihn die ganze Gemeinde vor das Lager, und sie steinigten ihn zu Tode, wie der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '\"Sprich zu den Söhnen Israels! Sag zu ihnen: Sie sollen sich Quasten an ihre Kleiderzipfel machen, sie und ihre Nachkommen, und sollen eine blaue Purpurschnur an jeder Zipfelquaste anbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'So sollt ihr also Quasten haben! Seht ihr sie an, dann denkt an all die Gebote des Herrn und tut sie! Ihr sollt nicht eurem Herzen und eurem Auge nachgeben, daß ihr durch sie die Treue brechet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Dadurch bleibt eingedenk all meiner Gebote und tut sie und seid heilig eurem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Nur ich, der Herr, bin euer Gott, der aus Ägypterland euch geführt, um euch zum Gott zu sein. Nur ich, der Herr, bin euer Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Da erfrechte sich Korach, Ishars Sohn, der Enkel des Levisohnes Kehat, mit den Rubeniten Datan und Abiram, Eliabs Söhnen, und mit On, Pelets Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Und sie traten vor Moses hin, ebenso 250 Männer von den anderen Israeliten, Gemeindevorsteher, Ratsherren und Vornehme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'So scharten sie sich gegen Moses und Aaron zusammen und sprachen zu ihnen: \"Genug mit euch! Denn die Gesamtgemeinde, alle miteinander, sind heilig, und in ihrer Mitte ist der Herr. Warum erhebt ihr euch über des Herrn Gemeinde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Als Moses es hörte, fiel er auf sein Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Dann sprach er zu Korach und seiner ganzen Rotte: \"Der Herr tut morgen kund, wer sein ist und wer geweiht und wer mit ihm verkehren darf, wer ihm genehm, daß er ihn mit sich verkehren läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tut dies: Nehmet euch Räucherpfannen, Korach und seine ganze Rotte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'tut Feuer darein und legt darauf morgen vor dem Herrn Räucherwerk! Zu wem sich der Herr bekennt, der ist geweiht. Ihr Levisöhne, dies genüge euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Und Moses sprach zu Korach: \"Hört dies, ihr Levisöhne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ist es euch zu wenig, daß euch Israels Gott aus der israelitischen Gemeinde ausgesondert hat, daß ihr mit ihm verkehren dürft, um an des Herrn Wohnung Dienst zu tun und vor der Gemeinde mit ihrem Dienst zu stehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Dich ließ er mit sich verkehren und mit dir alle deine Brüder, Levis Söhne, und nun verlangt ihr auch Priesterrechte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Darum rottest du dich mit deiner Rotte gegen den Herrn zusammen. Was ist denn Aaron, daß ihr über ihn murret?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Dann sandte Moses und ließ Datan und Abiram, Eliabs Söhne, rufen. Sie aber sprachen: \"Wir kommen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ist es zu wenig, daß du uns aus einem Land, von Milch und Honig fließend, heraufgeführt, um uns in der Wüste umzubringen, daß du auch noch selbstherrlich über uns herrschen Willst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Nicht wahr? Du hast uns in ein Land, von Milch und Honig fließend, gebracht, und Feld und Weinberg gabst du uns zu Erbe. Darfst du die Augen dieser Leute blenden? Wir kommen nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Da wurde Moses sehr zornig und sprach zum Herrn: \"Kehre Dich nicht an ihr Gerede! Nicht einen Esel habe ich ihnen jemals weggenommen. Nicht einem unter ihnen ein Leid getan!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Und zu Korach sprach Moses: \"Du und deine ganze Rotte sind morgen vor dem Herrn; du, sie und Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Nehme jeder seine Räucherpfanne mit, tue Räucherwerk darauf und bringe vor den Herrn jeder seine Räucherpfanne, 250 Räucherpfannen, auch du und Aaron, jeder seine Räucherpfanne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Da nahmen sie jeder seine Räucherpfanne, taten Feuer darein, legten Räucherwerk darauf und stellten sich an die Pforte des Festgezeltes, ebenso Moses und Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Und Korach versammelte die ganze Gemeinde wider sie an der Pforte des Festgezeltes. Da erschien der ganzen Gemeinde die Herrlichkeit des Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Und der Herr redete mit Moses und Aaron also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '\"Sondert euch von der Gemeinde hier ab, daß ich sie im Nu vertilge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Da fielen sie auf ihr Antlitz und sprachen: \"Gott, Du Gott des Lebensodems alles Fleisches! Ein Mann sündigt, und Du willst gegen die Gemeinde ohne Ausnahme wüten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Da sprach der Herr zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '\"Sprich so zu der Gemeinde: \'Verzieht euch rings von der Wohnstätte Korachs, Datans und Abirams.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Da stand Moses auf und ging zu Datan und Abiram; ihm folgten die Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Und er sprach zur Gemeinde: \"Weicht von den Zelten dieser schlimmen Männer! Berührt nichts, was ihrer ist, damit ihr nicht, um all ihrer Sünden willen, mit hinweggerafft werdet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'So verzogen sie sich rings von der Wohnstätte Korachs, Datans und Abirams. Datan und Abiram aber waren herausgetreten und hatten sich vor ihre Zelttüren gestellt, samt ihren Weibern, großen und kleinen Kindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Da sprach Moses: \"Daran sollt ihr erkennen, daß der Herr mich gesandt, alle diese Taten zu tun, und daß ich solche nicht von mir aus tue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Wenn diese sterben, wie alle Menschen sterben, und ihnen nur das widerfährt, was allen Menschen begegnet, dann hat der Herr mich nicht gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Aber tut der Herr ein Werk, und öffnet die Erde ihren Schlund und verschlingt sie mit allem, was ihrer ist, und fahren sie lebend in die Unterwelt, dann erkennet, daß diese Männer den Herrn gelästert haben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Wie er nun all diese Reden beendet hatte, spaltete sich der Erdboden unter ihnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'und die Erde öffnete ihren Schlund und verschlang sie und ihre Behausungen sowie alle Leute, die Korach gehörten, und alle Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Und sie fuhren mit all ihrer Habe lebend zur Unterwelt, und die Erde schloß sich über ihnen, und sie verschwanden aus der Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Ganz Israel aber, das sie rings umstand, war eilends geflohen; denn sie sagten: \"Die Erde könnte auch uns verschlingen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Ein Feuer war nämlich vom Herrn ausgegangen und fraß die 250 Männer, die das Räucherwerk gebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '\"Sprich zum Aaronsohn, dem Priester Eleazar, er soll die Räucherpfannen von der Brandstatt nehmen und das Feuer von da zerstreuen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Weil die Frevler diese Räucherpfannen mit dem Verlust ihres Lebens geheiligt, so mache man aus ihnen Bleche und überziehe damit den Altar! Sie hatten sie ja vor den Herrn gebracht, und so heiligten sie sie. Sie seien den Söhnen Israels ein Wahrzeichen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Da nahm der Priester Eleazar die kupfernen Räucherpfannen, die die Verbrannten hergebracht hatten, und man schlug sie breit zu einem Altarüberzug,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'ein Merkzeichen für die Israeliten, daß kein Unbefugter, der nicht zu Aarons Nachkommen gehört, das Recht hat, vor dem Herrn Räucherwerk darzubringen. Sonst geht es ihm wie Korach und seiner Rotte, wie ihm der Herr durch Moses angedroht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Da murrte die ganze israelitische Gemeinde am anderen Morgen wider Moses und Aaron und sagte: \"Ihr habt das Volk des Herrn bestürzt gemacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Als sich nun die Gemeinde gegen Moses und Aaron zusammenrottete, wandten sich diese nach dem Festgezelt. Und schon hatte es die Wolke bedeckt. Da erschien die Herrlichkeit des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Moses und Aaron betraten das Festgezelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '\"Hebt euch weg aus der Gemeinde hier, daß ich sie im Nu vertilge!\" Da fielen sie auf ihr Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Und Moses sprach zu Aaron: \"Nimm die Räucherpfanne, tu vom Altar Feuer darein, lege Räucherwerk darauf und trag es schleunigst in die Gemeinde und schaff ihnen Sühne! Denn schon geht vom Herrn der Grimm ans. Die Pest hat begonnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Da nahm es Aaron, wie Moses gesagt, und lief mitten unter die Gemeinde. Schon aber hatte die Pest unter dem Volke begonnen. Da räucherte er und schaffte dem Volk Sühne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Also stellte er sich zwischen die Toten und die Lebenden, und der Pest ward Einhalt getan. Aber der Pestleichen waren es 14.700, außer den um Korachs willen Umgekommenen. Aaron kehrte nun zu Moses an die Pforte des Festgezeltes zurück; der Pest war nämlich Einhalt getan worden. Und der Herr sprach zu Moses: \"Rede mit den Söhnen Israels und nimm von ihnen je einen Stab von allen ihren Fürsten nach Familien, zwölf Stäbe! Und schreibe eines jeden Namen auf seinen Stab! Den Namen Aaron aber schreibe auf den Levistab! Denn ein besonderer Stab gehört dem Haupte der Familie. Dann leg sie im Festgezelt vor dem Zeugnis nieder, wo ich mich euch zu offenbaren pflege! Dann sproßt der Stab des Mannes, den ich auserwähle. So schlage ich von mir aus der Israeliten Murren wider euch nieder.\" Da redete Moses mit den Israeliten. Und alle ihre Fürsten, Stamm für Stamm, übergaben ihm für ihre Familien zwölf Stäbe, jeder Fürst einen Stab. Unter ihren Stäben war auch der Stab Aarons. Da legte Moses die Stäbe vor dem Herrn im Zeugniszelt nieder. Als aber am anderen Morgen Moses zum Zeugniszelt kam, hatte der Stab Aarons vom Hause Levi ausgeschlagen; er trieb Sprossen und Blüten und wies reife Mandeln auf. Da brachte Moses alle Stäbe vom Herrn weg zu allen Israeliten. Da sprach der Herr zu Moses: \"Leg Aarons Stab vor dem Zeugnis nieder zur Verwahrung, den Widerspenstigen ein Zeichen, daß er von mir aus ihr Murren beende! Sonst müssen sie sterben.\" Moses tat so. Wie ihm der Herr befohlen, so hat er getan. Da sprachen die Israeliten zu Moses: \"Wehe! Wir vergehen; wir schwinden; wir schwinden alle hin. Jeder, der herantritt, stirbt, wenn er des Herrn Wohnung nahekommt. Sollen wir ganz und gar umkommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Da sprach der Herr zu Aaron: \"Du, deine Söhne und die Familie bei dir, ihr sollt die Verfehlung am Heiligtum auf euch nehmen! Du und deine Söhne sollt die Verfehlung an euren Priesterpflichten auf euch nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Doch laß auch den Levistamm, deinen väterlichen Stamm, deine Brüder, mit dir herantreten! Sie sollen sich dir anschließen und dich bedienen! Du aber und deine Söhne mit dir sollen vor dem Zeugniszelt Dienste tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Sie sollen deines Dienstes warten und des Dienstes am ganzen Zelte! Nur nicht den heiligen Geräten und nicht dem Altar dürfen sie nahekommen; sonst müßten sie, wie auch ihr, sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Sie sollen sich dir anschließen und an dem Festgezelt Dienste tun, den ganzen Dienst am Zelte! Kein Unbefugter darf euch nahekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Wartet des Dienstes am Heiligtum und am Altar! Dann kommt hinfort kein Zorn mehr über die Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ich habe also eure Brüder, die Leviten, aus den Söhnen Israels genommen; denn als Geschenk von euch sind sie dem Herrn gegeben, um den Dienst am Festgezelt zu verrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Du aber und deine Söhne sollt eures Priesteramtes warten für alle Sachen des Altars und darin hinter dem Vorhang! So dienet! Ich mache euer Priesteramt zu einem Amt, gar einträglich. Aber der Unbefugte, der herantritt, soll den Tod leiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Und der Herr sprach zu Aaron: \"Ich gebe dir also das Amt, dem meine Abgaben zufließen. Von allen heiligen Gaben der Söhne Israels überweise ich sie dir zum Einziehen, ebenso deinen Söhnen als ewige Gebühr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Von den hochheiligen Gaben soll dir, nach Abzug meines Mahles, ihr ganzes Opfer eigen sein bei all ihrem Speiseopfer, Sünd- und Schuldopfer, die sie mir erstatten! Dir und deinen Söhnen gehört es als Hochheiliges.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Du sollst sie als Hochheiliges verzehren. Nur alles Männliche darf sie verzehren. Dir ist es geweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Dies ist dein als Abgabe ihrer Gaben. Ich überweise dir, deinen Söhnen und deinen Töchtern bei dir alle Weihegaben der Israeliten als ewige Gebühr. Wer in deinem Hause rein ist, darf es essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alles Frische von Öl, Most und Korn, den ersten Abhub von dem, was sie dem Herrn geben, überweise ich dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Die Erstlinge von allem, was in ihrem Lande ist, und die sie dem Herrn darbringen, sollen dir gehören. Wer in deinem Hause rein ist, darf es essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Und alles Banngut in Israel soll dir gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Und was von allem Fleisch den Mutterschoß durchbricht, und was man dem Herrn zu bringen pflegt, Mensch oder Vieh, soll dir gehören! Die Menschenerstgeburt mußt du jedoch abgelten lassen, auch den ersten Wurf der unreinen Tiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Und seine Abgeltungen sind: Vom Monatskind an mußt du abgelten lassen nach dem Werte; fünf Ringe heiliges Gewicht sind zwanzig Korn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Aber den ersten Wurf des Rindes oder Schafes oder einer Ziege darfst du nicht abgelten lassen. Sie sind geweiht. Mit ihrem Blute sollst du den Altar besprengen und ihr Fett verrauchen lassen als ein Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ihr Fleisch gehöre dir! Wie die Abgabebrust und wie die rechte Keule soll es dir gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle Weihegaben heiliger Gaben, die die Israeliten dem Herrn weihen, verleihe ich dir, deinen Söhnen und deinen Töchtern bei dir als ewige Gebühr. Dies ist ein ewiger Salzbund vor dem Herrn für dich und deine Nachkommen bei dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Und der Herr sprach zu Aaron: \"Du sollst in ihrem Lande nichts zu eigen haben und keinen Anteil unter ihnen! Ich bin dein Anteil und dein Eigentum bei den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Den Söhnen Levis übergebe ich jeden Zehnten in Israel als Eigentum, als Entschädigung für ihren Dienst, den sie tun, den Dienst am Festgezelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Nicht dürfen die Israeliten fortan an das Festgezelt herantreten, um nicht todeswürdige Schuld auf sich zu laden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Vielmehr tue der Levite den Dienst am Festgezelt! Diese haben ihre Verschuldung selbst zu tragen kraft ewiger Satzung für eure Geschlechter. Bei den Israeliten dürfen sie kein Eigentum haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Ich überweise der Israeliten Zehnten, den sie dem Herrn als Weihegabe geben, zum Eigentum den Leviten. Darum habe ich von ihnen gesagt, sie sollen kein Eigentum bei den Söhnen Israels haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '\"Zu den Leviten sprich und sag zu ihnen: \'Nehmt ihr von den Israeliten den Zehnten, den ich von jenen euch als Eigentum gebe, so gebt davon eine Weihegabe dem Herrn, den Zehnten von dem Zehnten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Dann wird euch eure Weihegabe so angerechnet, wie sonst die des Kornes von der Tenne und die der Abfüllung aus der Kelter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'So sollt auch ihr die Weihegabe für den Herrn von all euren Zehnten weihen, die ihr von den Söhnen Israels einnehmt! Ihr sollt davon die Gabe für den Herrn dem Priester Aaron übergeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Von allen euch zufallenden Abgaben sollt ihr die ganze Weihegabe an den Herrn abliefern, von allem Fett, das ihm geweiht!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Und sprich zu ihnen: \'Gebt ihr das Fett davon ab, so wird es den Leviten angerechnet, wie der Ertrag der Tenne und der Kelter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Ihr dürft es an jedem Ort verzehren, ihr und euer Haus. Euer Lohn ist es ja für euren Dienst am Festgezelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Ihr ladet seinetwegen keine Schuld auf euch, wenn ihr das Beste davon abhebt. Ihr entweiht nicht der Israeliten heilige Gaben und müßt nicht sterben.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '\"Dies ist die Gesetzesbestimmung, von welcher der Herr folgendes verordnet: \'Sag den Söhnen Israels, sie sollen dir eine rote Kuh bringen, an der kein Makel ist und auf die noch kein Joch gekommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Gebt sie dem Priester Eleazar! Man führe sie vor das Lager und schlachte sie vor ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Und der Priester Eleazar nehme von ihrem Blut mit seinem Finger und sprenge an des Festgezeltes Vorderseite siebenmal von ihrem Blut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Dann verbrenne man die Kuh vor seinen Augen! Ihre Haut, ihr Fleisch und ihr Blut soll man verbrennen mitsamt dem Mist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Dann nehme der Priester Zedernholz, Ysop und Karmesinwolle und werfe es in den Kuhbrand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Dann wasche der Priester seine Kleider und bade seinen Leib in Wasser! Dann darf er wieder in das Lager kommen. Doch bleibt der Priester unrein bis zum Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Auch wer sie verbrennt, soll seine Kleider im Wasser waschen! Er bade auch seinen Leib in Wasser! Auch ist er unrein bis zum Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Ein reiner Mann sammle die Kuhasche und lege sie draußen vor dem Lager an einen reinen Ort hin, um sie für die israelitische Gemeinde zum Reinigungswasser aufzuheben! Ein Sündopfer ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Der Sammler der Kuhasche wasche gleichfalls seine Kleider! Er ist unrein bis zum Abend. Den Israeliten und dem Fremdling bei ihnen gelte es als ewige Satzung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Wer einen Toten, eine Menschenleiche, berührt, wird für sieben Tage unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Er soll sich damit am dritten und am siebten Tage entsündigen, dann wird er wieder rein. Entsündigt er sich aber nicht am dritten und am siebten Tage, dann bleibt er unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Wer einen Toten, eines toten Menschen Leiche, berührt und sich nicht entsündigt, verunreinigt die Wohnstätte des Herrn. Gestrichen aus Israel werde diese Person. Weil man kein Reinigungswasser auf sie gesprengt hat, bleibt sie unrein. Ihre Unreinheit bleibt weiter an ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Auch dies Gesetz gilt: Stirbt jemand in einem Zelte, so wird, wer das Zelt betritt und wer im Zelte ist, für sieben Tage unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Und jedes offene Gefäß, dem kein Deckel aufgebunden ist, wird unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Wer im Freien einen Ermordeten oder sonst Verstorbenen oder ein Gerippe oder ein Grab berührt, wird sieben Tage unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Für den Unreinen nehme man Asche vom verbrannten Sündopfer und gieße darüber frisches Wasser in ein Gefäß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Dann nehme ein reiner Mann Ysop und tauche ihn ins Wasser und besprenge das Zelt samt allen Geräten und Personen darin sowie den, der das Gerippe oder den Ermordeten oder sonst Gestorbenen oder eine Grabstätte berührt hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Am dritten und am siebten Tage besprenge der Reine den Unreinen und entsündige ihn am siebten Tage! Dann wasche er seine Kleider und bade sich in Wasser! So wird er am Abend rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Wird aber jemand unrein und entsündigt sich nicht, so ist eine solche Person aus der Volksgemeinde zu streichen. Denn sie verunreinigt das Heiligtum des Herrn. Sie ward nicht mit Reinigungswasser besprengt. Darum ist sie unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Dies gelte ihnen als ewige Satzung! Wer Reinigungswasser sprengt, muß seine Kleider waschen. Und unrein bis zum Abend wird, wer Reinigungswasser anrührt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Was der Unreine berührt, ist unrein. Wer ihn berührt, ist auch unrein bis zum Abend.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Und die Söhne Israels, die ganze Gemeinde, kamen am ersten Neumond in die Wüste Sin. Und das Volk blieb in Kades. Hier starb Mirjam und ward hier begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Die Gemeinde aber hatte kein Wasser. Da rotteten sie sich wider Moses und Aaron zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Und das Volk haderte mit Moses und schrie: \"Ach, wären wir auch umgekommen, als unsere Brüder vor dem Herrn umkamen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Warum habt ihr des Herrn Gemeinde in diese Wüste geführt, hier mit unserem Vieh zu sterben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Warum habt ihr aus Ägypten uns geführt, uns an diesen schlimmen Ort zu bringen, an einen Ort, wo es nicht Korn, noch Feige, noch Weinstock, noch Granatapfel, noch Trinkwasser gibt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Da kamen Moses und Aaron von der Gemeinde zu der Pforte des Festgezeltes und fielen auf ihr Antlitz. Da erschien ihnen die Herrlichkeit des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '\"Hol den Stab, versammle die Gemeinde, du und dein Bruder Aaron, und redet vor ihren Augen mit dem Felsen, daß er sein Wasser hergebe! Laß für sie Wasser aus dem Felsen sprudeln und tränke die Gemeinde und ihr Vieh!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Da holte Moses den Stab vom Herrn, wie ihm der Herr befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Dann versammelten Moses und Aaron die Gemeinde vor dem Felsen. Er sprach zu ihnen: \"Hört, ihr Widerspenstigen! Vermögen wir aus diesem Felsen Wasser für euch zu locken?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Dann hob Moses seine Hand und schlug zweimal an den Felsen mit seinem Stabe. Da kam viel Wasser heraus, und die Gemeinde trank samt ihrem Vieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Der Herr aber sprach zu Moses und Aaron: \"Weil ihr mir nicht geglaubt und mich vor den Israeliten nicht gerechtfertigt habt, darum dürft ihr diese Gemeinde nicht in das Land führen, das ich ihnen gegeben habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Das ist das Zweifelwasser, wo die Israeliten am Herrn zweifelten und er sich ihnen gegenüber rechtfertigte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Und Moses sandte Boten von Kades zum König von Edom. \"So spricht dein Bruder Israel: \'Du kennst all das Ungemach, das uns betroffen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'wie unsere Väter nach Ägypten zogen und wir lange in Ägypten saßen, wie die Ägypter uns und unsere Väter hart bedrückten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'wie wir zum Herrn schrien und er unser Flehen erhörte und einen Engel sandte und uns aus Ägypten führte. Jetzt sind wir in Kades, einer Stadt an deines Reiches Grenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Laß uns doch durch dein Land ziehen! Wir wollen nicht durch Feld und Weinberg ziehen. Wir wollen kein Wasser aus den Brunnen trinken. Wir ziehen auf dem Königsweg und biegen weder rechts noch links ab, bis daß wir dein Gebiet durchzogen haben.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Da ließ ihm Edom sagen: \"Du darfst bei mir nicht durchziehen; sonst trete ich dir mit dem Schwert entgegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Da ließ ihm Israel sagen: \"Auf der Straße wollen wir hinziehen. Trinken wir deine Wasser, ich und meine Herden, dann bezahle ich es; ich will nichts weiter, als einfach durchziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Da ließ er sagen: \"Du darfst es nicht.\" Und Edom zog ihm mit zahlreichem Kriegsvolk und bewaffneter Hand entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'So verweigerte Edom den Durchzug Israels durch sein Gebiet. Und Israel bog von ihm seitwärts ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Dann brachen sie von Kades auf, und so kamen die Israeliten, die ganze Gemeinde, zum Berge Hor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Da sprach der Herr zu Moses und Aaron am Berge Hor, an der Grenze des Landes Edom:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '\"Aaron soll zu seinen Stammesgenossen aufgenommen werden! Er darf das Land, das ich den Israeliten gebe, nicht betreten, weil ihr am Zweifelwasser widerstrebt habt dem, was ich befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Nimm Aaron und Eleazar, seinen Sohn, und fahre sie auf den Berg Hor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Dann nimm dem Aaron seine Kleider ab und bekleide damit seinen Sohn Eleazar! Dann wird Aaron weggenommen und dort sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Und Moses tat, wie ihm der Herr befohlen. Sie stiegen auf den Berg Hor vor den Augen der ganzen Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Dann nahm Moses Aaron seine Gewänder ab und bekleidete damit seinen Sohn Eleazar. Dann starb Aaron dort auf der Spitze des Berges. Hernach stiegen Moses und Eleazar den Berg hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Da sah die ganze Gemeinde, daß Aaron verschieden war, und das ganze Haus Israel beweinte Aaron dreißig Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Da hörte der Kanaaniter, König von Arad, der im Südland saß, daß Israel auf dem Weg der Kundschafter komme. Da griff er Israel an und nahm von ihm einige gefangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Da machte Israel dem Herrn ein Gelübde und sprach: \"Gibst Du dies Volk in meine Hand, dann banne ich ihre Städte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Und der Herr erhörte Israel und gab den Kanaaniter preis. Und es bannte sie und ihre Städte. Die Stätte nannte man Chorma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Sie zogen nun vom Berge Hor den Weg zum Schilfmeer, das Land Edom zu umgehen. Aber das Volk ward der Wanderung überdrüssig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Und das Volk redete wider Gott und Moses: \"Warum habt ihr uns aus Ägypten hergeführt, daß wir in der Wüste sterben? Kein Brot gibt es und kein Wasser. Wir sind der ärmlichen Kost überdrüssig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Da sandte der Herr gegen das Volk die Schlangen, Brandnattern. Sie bissen die Leute, und viel Volk starb aus Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Da kam das Volk zu Moses und sprach: \"Wir haben gesündigt, daß wir gegen den Herrn und dich geredet haben. Bete zum Herrn, daß er die Schlangen von uns nehme!\" Da betete Moses für das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Und der Herr sprach zu Moses: \"Mach dir eine Brandnatter und hänge sie an eine Stange! Jeder Gebissene schaue sie an und bleibe am Leben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Da machte Moses eine eherne Schlange und hängte sie an die Stange. Bissen dann die Schlangen jemand, so blickte er auf die eherne Schlange und blieb am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Die Israeliten zogen nun weiter und lagerten in Obot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Von Obot zogen sie weiter und lagerten in Ijje Haabarim in der Wüste, die östlich an Moab stößt, gegen Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Von dort zogen sie weiter und lagerten sich im Bachtal Zared.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Von da zogen sie weiter und lagerten jenseits des Arnon, der in der Wüste ist und aus dem Amoritergebiet kommt. Denn der Arnon ist die Grenze Moabs zwischen Moabitern und Amoritern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Daher heißt es im Buche der Kriege des Herrn: \"Waheb in Supha und die Bachtäler des Arnon');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'und der Bachtäler Abhang, der sich bis zur Gegend von Ar erstreckt und sich an Moabs Grenze lehnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Von dort nach Beer, das ist der Brunnen, von dem der Herr zu Moses gesagt: \"Hol das Volk her, damit ich ihm Wasser gebe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Damals sang Israel dies Lied und fiel mit dem Kehrvers \"Aufspringe, Quell!\" ein:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, '\"Du Brunnen, von Fürsten gegraben, gebohrt von des Volkes Edlen mit Zeptern, ihren Stäben.\" Aus der Wüste ging es nach Mattana,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'von Mattana nach Nachaliel, von Nachaliel nach Bamot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'von Bamot nach dem Tale in Moabs Gefilde beim Gipfel des Pisga, der auf das Ödland herabschaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Da sandte Israel Boten zu dem Amoriterkönige Sichon und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '\"Ich möchte dein Land durchziehen. Wir wollen weder auf Felder noch in Weinberge abbiegen. Wir wollen kein Wasser aus den Brunnen trinken. Wir ziehen auf dem Königswege hin, bis wir dein Gebiet durchzogen haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Aber Sichon verweigerte Israel den Durchzug durch sein Gebiet; Sichon zog vielmehr sein ganzes Volk zusammen und rückte gegen Israel in die Wüste vor. So kam er nach Jahas und griff Israel an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Israel aber schlug ihn mit dem Schwerte und eroberte sein Land vom Arnon bis zum Jabbok und bis zu den Ammonitern hin. Denn Jazer war die Grenze der Ammoniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Israel nahm alle diese Städte ein. Und Israel besetzte alle Amoriterstädte, Chesbon und alle seine Tochterstädte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Chesbon aber war die Stadt des Amoriterkönigs Sichon. Dieser hatte mit dem früheren Moabiterkönig Krieg geführt; da nahm er ihm sein ganzes Land bis zum Arnon ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Daher sagten die Spruchdichter: \"Kommt nach Chesbon! Gebaut und wohlbefestigt werde Sichons Stadt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, '\"Ein Feuer ging von Chesbon aus, aus Sichons Stadt die Lohe. Sie fraß bis Moab hin und glomm bis auf des Arnon Höhen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, '\"Weh, Moab, dir! Du bist verloren, Volk des Kamos. Er läßt gefangennehmen seine Söhne, und seine Töchter werden Kriegsgefangene des Amoriterkönigs Sichon.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, '\"Gerade sie beschossen wir. Zugrund ging Chesbon bis nach Dibon, und wir verwüsteten bis Nophach hin, bei Medeba.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'So besetzte Israel das Amoriterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Dann ließ Moses Jazer auskundschaften. Sie nahmen seine Tochterstädte, und man vertrieb die Amoriter darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Dann wandten sie sich und zogen gen Basan hinauf. Da rückte Basans König Og mit seinem ganzen Volke ihnen bis Edreï entgegen zum Kampfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Der Herr aber sprach zu Moses: \"Hab keine Furcht vor ihm! Ich gebe ihn und all sein Volk und Land in deine Hand. Tu mit ihm so, wie du mit dem Amoriterkönig Sichon getan, der zu Chesbon saß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Da schlugen sie ihn, seine Söhne und all sein Volk, daß kein Entronnener ihm blieb. Und sie besetzten sein Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Dann zogen die Israeliten weiter und lagerten in den Steppen Moabs jenseits des Jordans von Jericho.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Balak, Sippors Sohn, aber sah alles, was Israel den Amoritern getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Da geriet Moab in große Furcht vor dem Volke, weil es so zahlreich war. Und Moab graute es vor den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Da sprach Moab zu den Ältesten Midians: \"Jetzt wird die Gemeinde alles um uns abfressen, wie der Stier das Grün des Feldes abfrißt.\" Zu jener Zeit war Balak, Sippors Sohn, König über Moab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Da sandte er Boten an Beors Sohn Bileam nach Petor, das am Strome liegt, ihn in das Land seines Volkes zu rufen. Er ließ ihm sagen: \"Da ist ein Volk aus Ägypten gezogen. Es deckt des Landes Fläche. Mir gegenüber sitzt es da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Nun geh her! Verfluche mir dieses Volk! Denn es ist mächtiger als ich. Vielleicht kann ich es; wir schlagen es, und ich vertreibe es aus dem Lande. Ich weiß ja. Gesegnet ist, wen du segnest, und verflucht, wen du verfluchst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Da gingen die Ältesten Moabs und die Ältesten Midians hin, Meister der Wahrsagekunst. Sie kamen zu Bileam und kündeten ihm Balaks Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Da sprach er zu ihnen. \"Nächtiget hier die Nacht! Dann gebe ich euch Bescheid, wie der Herr zu mir reden wird.\" So blieben Moabs Häuptlinge bei Bileam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Gott aber kam zu Bileam und sprach: \"Was sind dir diese Männer?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Da sprach Bileam zu Gott: \"Der Moabkönig Balak, Sippors Sohn, schickt zu mir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '\'Das Volk, das aus Ägypten gezogen, deckt des Landes Fläche. Nun geh her! Verwünsche es mir! Vielleicht kann ich es bekämpfen und vertreiben.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Da sprach Gott zu Bileam: \"Du sollst nicht mit ihnen gehen! Du sollst das Volk nicht verfluchen! Denn für den Segen ist es bestimmt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Da machte sich Bileam am anderen Morgen auf und sprach zu Balaks Häuptlingen: \"Geht in euer Land! Der Herr verweigert mir die Erlaubnis, mit euch zu gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Da machten sich Moabs Häuptlinge auf, kamen zu Balak und sprachen: \"Bileam weigert sich, mit uns zu ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Da sandte Balak nochmals Häuptlinge, zahlreichere und angesehenere als jene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Sie kamen zu Bileam und sprachen zu ihm: \"So spricht Balak, Sippors Sohn: \'Laß dich nicht abhalten, zu mir zu ziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Denn ich belohne dich auf das reichlichste und tue alles, was du mir sagst. So geh her und verwünsche mir dies Volk!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Da hob Bileam an und sprach zu Balaks Dienern: \"Gäbe Balak mir seines Hauses Fülle an Gold und Silber, so könnte ich doch nicht dem Befehle des Herrn, meines Gottes, zuwiderhandeln, weder im Kleinen noch im Großen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Nun bleibt auch heute Nacht noch hier, daß ich erfahre, was der Herr mir weiter sagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Und Gott kam in der Nacht zu Bileam und sprach zu ihm: \"Sind diese Männer gekommen, dich zu rufen, so mache dich auf und geh mit ihnen! Doch tu nur, was ich dich heiße!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Da machte sich Bileam am anderen Morgen auf, sattelte seinen Esel und zog mit Moabs Häuptlingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Aber Gottes Zorn entbrannte, daß er ging, und der Engel des Herrn trat ihm hemmend in den Weg. Er aber ritt auf seiner Eselin, und seine beiden Diener waren bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Da sah die Eselin den Engel des Herrn auf dem Wege stehen, sein Schwert gezückt in seiner Hand. Und die Eselin bog vom Wege und ging in das Feld. Bileam aber schlug die Eselin, um sie wieder auf den Weg zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Da trat der Engel des Herrn in den Hohlweg der Weinberge, wo auf beiden Seiten Mauern waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Die Eselin sah nun den Engel des Herrn und sie drückte sich an die Wand und drückte auch Bileams Fuß an die Wand. Da schlug er sie abermals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Da ging der Engel des Herrn nochmals voraus und stellte sich an eine engere Stelle, wo kein Weg war, nach rechts oder links auszuweichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Als die Eselin den Engel des Herrn sah, legte sie sich unter Bileam hin. Da entbrannte Bileams Zorn, und er schlug die Eselin mit dem Stock.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Der Herr aber öffnete den Mund der Eselin. Und sie sprach zu Bileam: \"Was habe ich dir getan, daß du mich schon dreimal geschlagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Da sprach Bileam zur Eselin: \"Zum Narren hast du mich ja gehabt. Hätte ich doch ein Schwert zur Hand! Denn dann würde ich dich töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Da sprach die Eselin zu Bileam: \"Bin ich denn nicht deine Eselin, auf der du von jeher bis heute geritten bist? Bin ich je gewohnt gewesen, dir solches zu tun?\" Er sprach: \"Nein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Da öffnete der Herr dem Bileam die Augen. Und er sah den Engel des Herrn auf dem Wege stehen, sein Schwert gezückt in seiner Hand. Da verneigte er sich und warf sich auf seine Stirne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Der Engel des Herrn aber sprach zu ihm: \"Warum hast du deine Eselin schon dreimal geschlagen? Ich bin es, der ich hemmend ausgezogen bin. Denn diese Reise gefällt mir nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Die Eselin aber sah mich und wich vor mir nun schon dreimal aus. Wäre sie nicht vor mir ausgewichen, dann hätte ich dich umgebracht und sie am Leben gelassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Da sprach Bileam zum Engel des Herrn: \"Ich habe gefehlt. Ich habe ja nicht gewußt, daß du mir den Weg vertrittst. Nun aber, wenn dir die Sache mißfällt, dann kehre ich um.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Da sprach der Engel des Herrn zu Bileam \"Geh mit den Männern! Nur sage nichts als das, was ich dir sage!\" Da zog Bileam mit Balaks Häuptlingen weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Als Balak hörte, daß Bileam komme, ging er ihm entgegen bis Ar Moab, das an der Arnongrenze liegt, an der äußersten Grenzmark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Da sprach Balak zu Bileam: \"Habe ich dich nicht geziemend rufen lassen? Warum bist du nicht zu mir gekommen? Vermag ich wahrhaftig nicht, dich zu belohnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Da sprach Bileam zu Balak: \"Ich bin ja zu dir gekommen. Vermag ich aber wirklich etwas zu reden? Nur das Wort, das Gott mir in den Mund legt, rede ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Da ging Bileam mit Balak, und sie kamen nach Kirjat Chusot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Da opferte Balak Rinder und Schafe und schickte davon an Bileam und die Häuptlinge bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Am anderen Morgen nahm Balak den Bileam und führte ihn zu den Baalshöhen. Von dort sah er des Volkes Umrisse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Da sprach Bileam zu Balak: \"Baue mir der Altäre sieben und bereite mir hier sieben junge Stiere und sieben Widder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Und Balak tat, wie Bileam verlangt hatte. So brachten Balak und Bileam Stiere und Widder auf den Altären dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Da sprach Bileam zu Balak: \"Bleibe du bei deinem Brandopfer! Ich aber will hingehen. Vielleicht tritt mir der Herr entgegen. Was er mich schauen läßt, melde ich dir.\" So ging er in die Einsamkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Da begegnete Gott dem Bileam. Und Bileam sprach zu ihm: \"Ich habe der Altäre sieben hergerichtet und Stiere und Widder auf den Altären dargebracht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Da legte der Herr dem Bileam ein Wort in den Mund und sprach: \"Zu Balak kehr um und sprich also!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Da kehrte er zu ihm zurück; er aber stand noch bei seinem Brandopfer, er und alle Häuptlinge Moabs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Da hob er seinen Spruch an und sprach: \"Aus Aram holt mich Balak, der König Moabs, aus des Ostlands Bergen: \'Hierher! Verfluch mir Jakob! Hierher! Beschreie Israel!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Wie soll ich fluchen dem, dem Gott nicht flucht? Wie den beschreien, den nicht der Herr beschreit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Ich seh\' es von den Felsenspitzen; ich schau es von den Hügeln. fürwahr, ein Volk, das abgesondert wohnt und unter Heiden sich nicht mischt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Wer zählt denn Jakobs Staub? Wer mißt denn Israels feinen Staub? Möcht\' ich das Sterben der Gerechten sterben! Und möcht\' mein Ende wie das ihre sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Da sprach Balak zu Bileam: \"Was hast du mir getan? Meine Feinde zu verwünschen hole ich dich, und nun segnest du sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Da antwortete er und sprach: \"Muß ich nicht genau aussprechen, was mir der Herr in den Mund legt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Da sprach Balak zu ihm: \"Geh mit mir an einen anderen Ort, von wo du es noch sehen kannst! Nur Umrisse brauchst du zu sehen. Ganz brauchst du es nicht zu sehen. So verwünsche es mir von dort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'So nahm er ihn nach dem Späherfelde zur Höhe des Pisga, baute dort sieben Altäre und opferte Stiere und Widder auf den Altären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Da sprach Bileam zu Balak: \"Bleib hier bei deinem Brandopfer! Ich aber gehe dorthin zu der Begegnung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Da begegnete der Herr dem Bileam, legte ihm ein Wort in den Mund und sprach- \"Kehre zu Balak zurück und rede so!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Da kam er zu ihm. Er aber stand noch bei seinem Brandopfer, und die Häuptlinge Moabs bei ihm. Und Balak sprach zu ihm: \"Was hat der Herr geredet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Da hob er seinen Spruch an, also sprechend: \"Auf, Balak! Höre Du, Sohn des Sippor, hör mir zu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Nicht ist Gott wie ein Mann, daß er Sein Wort nicht hielte, nicht wie ein Menschenkind, daß er bereute. Soll er nur reden und nichts tun, verheißen und dann nichts erfüllen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Fürwahr, von Segen habe ich vernommen, er hat gesegnet. Ich kann\'s nicht wenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'In Jakob sieht man nichts Verkehrtes; in Israel schaut man kein Ungemach. Der Herr, sein Gott, mit ihm; bei ihm ist Kriegsjubel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gott hat es aus Ägypten weggeführt. Wie Wisents Hörner ist er ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Denn gegen Jakob hilft nicht Zauberkunst und nicht Beschwörung gegen Israel. Schon wird es Israel und Jakob angekündigt, was Gott im Werke hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Dies Volk! Wie eine Löwin steht es auf, erhebt sich einem Löwen gleich, und legt sich nicht, eh\' es den Raub verzehrt und von Erschlagenen Blut getrunken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Da sprach Balak zu Bileam: \"Verwünschest du es nicht, dann brauchst du es auch nicht zu segnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Da antwortete Bileam und sprach zu Balak: \"Habe ich dir nicht gesagt: \'Ich tue, was der Herr mir sagt\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Da sprach Balak zu Bileam: \"So geh! Ich nehme dich an einen anderen Ort. Vielleicht ist es Gott genehm, daß du es von dort aus mir verfluchst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Und Balak nahm Bileam auf den Gipfel des Peor, der auf das Ödland herabschaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Da sprach Bileam zu Balak: \"Bau mir hier der Altäre sieben und richte mir hier sieben junge Stiere und sieben Widder her!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Da tat Balak, wie Bileam gesagt, und opferte auf den Altären Stiere und Widder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Bileam aber sah, daß es dem Herrn gefiel, Israel zu segnen. So ging er nicht, wie die vorigen Male, auf Bannsprüche aus, sondern wandte sein Antlitz zur Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Und Bileam erhob seine Augen. Da sah er Israel nach Stämmen gelagert. Und ein Gottesgeist kam über ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Er hob seinen Spruch an und sprach: \"Der Spruch des Beorsohnes Bileam, der Spruch des Mannes mit erschloßnen Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'des Mannes Spruch, der Gottesworte hört und des Allmächtigen Gesichte schaut, der niederfällt und doch die Augen öffnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, '\'Wie schön sind deine Zelte, Jakob, und Israel, deine Wohnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Wie Bachgründe, geweitet, wie Gärten an dem Strome, wie Eichen, von dem Herrn gepflanzt, wie Zedern am Gewässer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Sein Wasser quillt gesund hervor; an vielen Wassern seine Saat. Sein Reich ist größer noch als das des Adad, und seine Herrschaft ausgedehnter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gott hat es aus Ägypten weggeführt. Es ist Ihm wie des Wisents Hörner. Es frißt die Heiden, seine Feinde, und ihr Gebein zermalmt es und ihre Gliedmaßen zerbricht es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Es kauert, lagert wie ein Löwe, wie eine Löwin. Wer wagt, sie aufzustören? Gesegnet, wer dich segnet! Verflucht, wer dich verflucht!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Da entbrannte Balaks Zorn wider Bileam, und er schlug die Hände zusammen. Dann sprach Balak zu Bileam: \"Meine Feinde zu verwünschen, habe ich dich berufen. Und nun segnest du sie dreimal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Jetzt geh eilends heim! Ich dachte, dich reichlich zu lohnen. Doch der Herr hat dich um den Lohn gebracht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Da sprach Bileam zu Balak: \"Habe ich nicht schon deinen Boten, die du mir gesandt, gesagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '\'Gäbe Balak mir auch seines Hauses Fülle an Gold und Silber, ich könnte nicht dem Befehle des Herrn zuwiderhandeln, um von mir aus Gutes oder Schlimmes zu tun. Nur was der Herr sagt, werde ich künden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Nun gehe ich heim zu meinem Volk. Geh her! Ich will dir verraten, was dies Volk deinem Volk in der Zukunft tun wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Und er hob seinen Spruch an und sprach: \"Der Spruch des Beorsohnes Bileam, der Spruch des Mannes mit erschloßnen Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'des Mannes Spruch, der Gottesworte hört und der des Höchsten Denken kennt, der des Allmächtigen Gesichte schaut, der niederfällt und doch die Augen öffnet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, '\'Ich sehe ihn, jedoch nicht jetzt. Ich schaue ihn, jedoch nicht nahe. Aufgeht ein Stern aus Jakob; aufsteigt aus Israel ein Schweifstern, und er zerschmettert Moabs Hänge; zu Boden wirft er alle Söhne Sets.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Und Edom wird verwüstet, und das ihm feindliche Seïr zerstört, und Israel gewinnt an Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Aus Jakob geht er aus und er vernichtet selbst den Rest der Stadt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Dann sah er Amalek; da hob er seinen Spruch an, also sprechend: \"Der Völker Abneigung ist Amalek; sein Untergang ist gründlich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Dann sah er die Keniter; da hob er seinen Spruch an, also sprechend: \"Urständig ist dein Sitz, dein Nest in Felsen eingebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Und doch wird Kain ein Weideplatz. Wie lange noch, bis weggeführt dich Assur?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Dann hob er seinen Spruch an, also sprechend: \"Weh! Wer will leben bleiben, wenn Gott dies auferlegt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, '\"Von Kittim kommen Schiffe her; sie beugen Assur und beugen Eber. Auch dies geht unter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Dann machte sich Bileam auf und kehrte heim. Auch Balak zog seines Wegs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Israel aber saß zu Sittim. Da befleckte sich das Volk durch Unzucht mit den Töchtern Moabs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Diese luden das Volk zu ihren Götteropfern ein. Da aß das Volk und warf sich vor ihren Göttern nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Und Israel paarte sich zu Ehren des Baal Peor. Da ward der Herr über Israel zornig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Und der Herr sprach zu Moses: \"Nimm dieses Volkes Rädelsführer und setze sie dem Herrn, im Angesicht der Sonne, aus, daß die Zornesglut des Herrn von Israel lasse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Da sprach Moses zu den Stämmen Israels: \"Töte jeder seine Leute, die sich zu Ehren Baal-Peors gepaart!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Da kam eben ein israelitischer Mann und führte seinen Stammesgenossen eine gewisse Midianiterin zu, unter den Augen des Moses und der ganzen israelitischen Gemeinde, die an ihren Zelttüren ohne Unterlaß weinten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Dies sah Eleazars Sohn Pinechas, der Enkel des Priesters Aaron. Da trat er aus der Gemeinde hervor und nahm einen Speer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Dann ging er dem israelitischen Manne in das innere Gemach nach und durchstach beiden, dem israelitischen Mann und dem Weibe, den Unterleib. Da ward dem Blutbad unter den Israeliten Einhalt getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Die Zahl der im Blutbad Gefallenen betrug 24.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Da sprach der Herr zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '\"Pinechas, der Sohn des Eleazar, des Priesters Aaron Enkel, hat von den Israeliten meinen Grimm gewendet, mit meinem Eifer unter ihnen eifernd. Und so habe ich die Israeliten nicht in meinem Eifer aufgerieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Darum künde! Ich nehme ihn nachträglich in meinen Bund auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Ihm und seinem Stamme nach ihm soll Priesterrecht für alle Zeit gesichert sein, dafür, daß er für seinen Gott geeifert und den Israeliten Sühne verschafft hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Der getötete israelitische Mann aber, der mit der Midianiterin erschlagen worden war, hieß Zimri, der Sohn Salus, des Fürsten einer Familie der Simeoniten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Und das getötete midianitische Weib hieß Kozbi, die Tochter Surs, des Sippenhäuptlings einer midianitischen Familie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '\"Befehdet die Midianiter! Schlagt sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Denn sie befehden euch durch ihre Ränke, mit denen sie euch durch Peor umgarnt haben, und durch ihre Schwester Kozbi, diese midianitische Fürstentochter, die am Tage des Blutbades getötet ward, das wegen Peor angerichtet wurde.\" - Es war nach dem Blutbad.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Da sprach der Herr zu Moses und Eleazar, dem Sohn des Priesters Aaron:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '\"Nehmt die Gesamtzahl der ganzen israelitischen Gemeinde auf, von zwanzig Jahren aufwärts, nach Familien, alle Heerespflichtigen in Israel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Da ließen Moses und der Priester Eleazar sie in den Steppen Moabs, am Jordan bei Jericho, zur Musterung kommen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Von zwanzig Jahren aufwärts, wie der Herr dem Moses befohlen. Die Israeliten, die aus dem Lande Ägypten ausgezogen waren:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Israels Erstgeborener Ruben: Rubens Söhne: Chanok mit der Sippe der Chanokiter, Pallu mit der der Palluiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Chesron mit der der Chesroniter, Karmi mit der der Karmiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Das sind die Sippen der Rubeniter; die Zahl ihrer Ausgemusterten betrug 43.730.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Pallus Söhne: Eliab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Eliabs Söhne waren Nemuel, Datan und Abiram. Datan und Abiram waren die von der Rotte Berufenen, die wider Moses und Aaron unter der Rotte Korachs gehadert, als sie im Hader mit dem Herrn lagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'worauf die Erde ihren Schlund auftat und sie mit Korach verschlang, während die Rotte umkam, indem das Feuer die 250 Mann verzehrte, so daß sie zu einem Zeichen wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Die Söhne Korachs aber kamen nicht um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeons Söhne nach ihren Sippen: Nemuel mit der Sippe der Nemueliter, Jamin mit der der Jaminiter, Jakin mit der der Jakiniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Zerach mit der der Zerachiter, Saul mit der der Sauliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dies sind die Sippen der Simeoniter 22.200.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gads Söhne nach ihren Sippen: Sephon mit der der Sephoniter, Chaggi mit der der Chaggiter, Suni mit der der Suniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Ozni mit der der Ozniter, Eri mit der der Eriter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod mit der der Aroditer, Areli mit der der Areliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Das sind die Sippen der Gadsöhne nach ihren Gemusterten, 40.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Judas Söhne waren Er und Onan. Er und Onan aber waren im Lande Kanaan gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Judas Söhne nach ihren Sippen waren dies: Sela mit der der Selaniter, Peres mit der der Persiter. Zerach mit der der Zarchiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Des Peres Söhne waren diese: Chesron mit der Sippe der Chesroniter, Chamul mit der der Chamuliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dies sind Judas Sippen nach ihren Gemusterten, 76.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Issakars Söhne nach ihren Sippen waren: Tola mit der der Tolaiter, Puwwa mit der der Puniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub mit der der Jasubiter, Simron mit der der Simroniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Dies sind Issakars Sippen nach ihren Gemusterten, 64.300.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Zabulons Söhne nach ihren Sippen: Sered mit der der Serditer, Elon mit der der Eloniter, Jachleel mit der der Jachleeliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dies sind die Sippen der Zabuloniter nach ihrem Gemusterten, 60.500.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Josephs Söhne nach ihren Sippen: Manasse und Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manasses Söhne: Makir mit der Sippe der Makiriter. Makir zeugte Gilead. Von Gilead die Sippe der Gileaditer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Dies sind die Söhne Gileads: Jezer mit der Sippe der Jezriter, Chelek mit der der Chelkiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel mit der der Asrieliter, Sekem mit der der Sikmiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semida mit der der Semidaiter, Chepher mit der der Chephriter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Selophchad, Chephers Sohn, hatte keine Söhne, nur Töchter. Selophchads Töchter hießen Machla, Noa, Chogla, Milka und Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Dies sind die Sippen Manasses, und ihrer Gemusterten waren es 52.700.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Dies sind Ephraims Söhne nach ihren Sippen: Sutelach mit der der Sutalchiter, Beker mit der der Bakriter, Tachan mit der der Tachaniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Dies sind Sutelachs Söhne: Eran mit der Sippe der Eraniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dies sind die Sippen der Söhne Ephraims nach ihren Gemusterten, 32.500. Dies sind die Josephsöhne nach ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjamins Söhne nach ihren Sippen: Bela mit der der Baliter, Asbel mit der der Asbeliter, Achiram mit der der Achiramiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sephupham mit der der Suphamiter, Chupham mit der der Chuphainiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Belas Söhne waren Ard und Naaman, Ard mit der Sippe der Arditer, Naaman mit der der Naamaniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dies sind Benjamins Söhne nach ihren Sippen, und ihrer Gemusterten waren es 45.600.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Dies sind Dans Söhne nach ihren Sippen: Sucham mit der der Suchamiter. Das sind Dans Sippen mit ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Alle Sippen der Suchamiter nach ihren Gemusterten waren es 64.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Assers Söhne nach ihren Sippen: Jimna mit der des Jimna, Jiswi mit der der Iswiter, Beria mit der der Beriiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Von den Söhnen Berias: Cheber mit der Sippe der Chebriter, Malkiel mit der der Malkieliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Assers Tochter hieß Serach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dies sind die Sippen der Söhne Assers nach ihren Gemusterten, 53.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naphtalis Söhne nach ihren Sippen: Jachseel mit der der Jachseeliter, Guni mit der der Guniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jeser mit der der Isriter, Sillem mit der Sillemiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Das sind die Sippen Naphtalis nach ihren Sippen, und ihrer Gemusterten waren es 45.400.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Dies sind die Gemusterten der Söhne Israels: 601.730.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '\"Diesen soll das Land als eigen zugeteilt werden nach Namenzahl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Du sollst dem, der viel zählt, viel Besitz geben und dem, der wenig zählt, wenig! Nach den Ausgemusterten werde sein Besitz jedem gegeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Doch soll das Land durchs Los verteilt werden! Sie sollen es nach den Namen ihrer väterlichen Stämme erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Sein Besitz soll nach dem Los verteilt werden zwischen dem, der viel, und dem, der wenig zählt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Dies sind die aus Levi Ausgemusterten nach ihren Sippen: Gerson mit der der Gersoniter, Kehat mit der der Kehatiter, Merari mit der der Merariter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dies sind die Sippen Levis: die der Libniter, die der Chebroniter, die der Machliter, die der Musiter, die der Korchiter. Kehat zeugte Amram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Amrams Weib hieß Jokebed, Levis Tochter, die Levi in Ägypten geboren ward. Sie gebar dem Amram Aaron und Moses sowie ihre Schwester Mirjam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aaron wurden Nadab, Abihu, Eleazar und Itamar geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadab aber und Abiram mußten sterben, als sie vor dem Herrn unbefugt Feuer darbrachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Ihre Ausgemusterten beliefen sich auf 23.000, alles Männliche von einem Monat aufwärts. Denn sie waren nicht mit den anderen Israeliten gemustert worden, weil ihnen kein Besitz inmitten der Israeliten geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Das sind die von Moses und dem Priester Eleazar Gemusterten. Sie hatten die Israeliten in den Steppen Moabs am Jordan bei Jericho gemustert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Unter diesen war keiner mehr von den durch Moses und den Priester Aaron Gemusterten. Diese hatten die Israeliten in der Wüste Sinai gemustert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Denn der Herr hatte zu ihnen gesagt, sie müßten in der Wüste sterben. So war keiner von ihnen mehr übrig, außer Jephunnes Sohn Kaleb und Josue, Nuns Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Herzu traten die Töchter Selophchads, des Sohnes Chephers, des Enkels Gileads, des Sohnes Makirs, des Enkels Manasses, von den Sippen Manasses, des Josephsohnes. Seine Töchter hießen Machla, Noa, Chogla, Milka und Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Sie traten vor Moses und vor den Priester Eleazar, vor die Fürsten und die Gesamtgemeinde vor der Pforte des Festgezeltes mit den Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '\"Unser Vater ist in der Wüste gestorben. Doch er ist nicht bei der Rotte gewesen, die sich gegen den Herrn zusammenrottete, bei der Rotte Korachs. Er ist um seiner eigenen Sünde willen gestorben. Er hatte aber keine Söhne gehabt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Warum soll unseres Vaters Namen aus seiner Sippe getilgt werden, bloß, weil er keinen Sohn hat? Gib uns Besitztum unter unseres Vaters Brüdern\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Und Moses brachte ihre Rechtssache vor den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Da sprach der Herr zu Moses also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '\"Selophchads Töchter haben recht geredet. Gib ihnen unter ihres Vaters Brüdern einen Besitz und überweise ihnen ihres Vaters Besitz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Und zu den Söhnen Israels sprich so: \'Stirbt ein Mann und hat keinen Sohn, dann überweist seiner Tochter seinen Besitz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Hat er aber keine Tochter, so gebt seinen Besitz seinen Brüdern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Hat er aber keine Brüder, so gebt seinen Besitz den Brüdern seines Vaters!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Hat aber sein Vater keine Brüder, so gebt sein Besitztum seinem Blutsverwandten in seiner Sippe, daß er es erbe! Das sei den Israeliten Rechtssatzung, wie der Herr dem Moses geboten hat.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Und der Herr sprach zu Moses: \"Steig auf die Uferberge hier! Beschaue das Land, das ich den Söhnen Israels gebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Hast du es gesehen, dann wirst du zu deinen Stammesgenossen aufgenommen, wie dein Bruder Aaron aufgenommen worden ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'weil ihr meinem Worte in der Wüste Sin widersprochen habt, als die Gemeinde haderte und ihr mich vor ihren Augen durch das Wasser hättet rechtfertigen sollen. Das ist das Haderwasser bei Kades in der Wüste Sin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Und Moses sprach zum Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '\"Der Herr, der Gott der Geister in allem Fleisch, bestelle über die Gemeinde einen Mann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'der vor ihnen ausziehe und vor ihnen heimkomme und sie aus- und heimführe, daß des Herrn Gemeinde nicht sei wie Schafe ohne Hirten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Da sprach der Herr zu Moses: \"Wähle dir Josue, den Sohn des Nun! Das ist ein Mann, in dem Geist ist. Leg deine Hand auf ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Stelle ihn dem Priester Eleazar und der Gemeinde vor und bestelle ihn vor ihren Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Leg von deiner Würde auf ihn, damit die ganze israelitische Gemeinde gehorche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Vor den Priester Eleazar trete er, daß dieser vor dem Herrn die Entscheidung der Lose für ihn befrage! Auf sein Geheiß sollen sie ausziehen und auf sein Geheiß heimkommen, er und alle Söhne Israels, die Gesamtgemeinde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Da tat Moses, wie ihm der Herr befohlen hatte. Er wählte Josue und stellte ihn dem Priester Eleazar und der ganzen Gemeinde vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Dann legte er ihm seine Hände auf und setzte ihn ein, wie es der Herr durch Moses angeordnet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '\"Befiehl den Söhnen Israels und sprich zu ihnen: \'Ihr sollt mir pünktlich meine Opfergabe bringen, meine Speise, als Mahl süßen Duftes zu seiner Zeit!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Und sprich zu ihnen: \'Das ist das Mahl, das ihr dem Herrn darbringen sollt: Zwei fehlerlose, noch nichtjährige Lämmer Tag für Tag als stetig Brandopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Das eine Lamm sollst du am Morgen bereiten, das andere zwischen den Abendstunden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Dazu ein Zehntel Scheffel feines Mehl, mit einem vierter Krug Öl zerstoßener Oliven angemacht, zum Speiseopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Das stetige Brandopfer, das am Berge Sinai eingesetzt ward, zum süßen Duft als Mahl für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Ein vierter Krug sei sein Trankopfer für jedes Lamm! Spende dem Herrn das Bieropfer im Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Das zweite Lamm sollst du zwischen den Abendstunden bereiten! Du sollst es mit dem gleichen Speiseopfer, wie am Morgen, bereiten, und mit seinem Trankopfer als Mahl süßen Duftes für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Am Sabbattage zwei fehlerlose, noch nicht jährige Lämmer sowie zwei Zehntel feines Mehl, mit Öl bereitet, zum Speiseopfer und zu seinem Trankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Das ist das stetige Sabbatbrandopfer neben dem stetigen Brandopfer und seinem Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Je am ersten Tage eurer Monde sollt ihr als Brandopfer dem Herrn zwei junge Stiere bringen, einen Widder, sieben fehlerlose, noch nicht jährige Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'dazu drei Zehntel feines Mehl, mit Öl bereitet, für das Speiseopfer auf jeden Stier, zwei Zehntel feines Mehl, mit Öl bereitet, für das Speiseopfer auf jeden Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'ein Zehntel feines Mehl, mit Öl bereitet, für das Speiseopfer auf jedes Lamm, als Brandopfer von süßem Duft, als Mahl für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Bei ihren Trankopfern soll ein halber Krug auf jeden Farren kommen, ein dritter Krug auf jeden Widder, ein Viertel Wein auf jedes Lamm! Das ist das Opfer, das an jedem Neumond des ganzen Jahres darzubringen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Als Sündopfer diene dem Herrn ein Ziegenbock! Man soll ihn und sein Trankopfer zum stetigen Brandopfer bereiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Am vierzehnten des ersten Monds ist Passah für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Am fünfzehnten desselben Monds ist Festfeier. Sieben Tage soll nur ungesäuertes Brot gegessen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Am ersten Tag ist Vorlesung im Heiligtum. Da dürft ihr keine Werktagsarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Als Opfermahl für den Herrn bringt zwei junge Stiere, einen Widder, sieben noch nicht jährige Lämmer! Sie sollen bei euch fehlerlos sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Dann sollt ihr als ihr Speiseopfer feines Mehl herrichten, mit Öl bereitet, drei Zehntel zum Stier, zwei Zehntel zum Widder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Zu dem der sieben Lämmer nur ein Zehntel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Und einen Bock zum Sündopfer, um euch Sühne zu schaffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'So sollt ihr diese bereiten, ganz abgesehen vom Morgenbrandopfer, das ein stetiges Brandopfer ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Die gleichen sollt ihr Tag für Tag sieben Tage lang bereiten, als Mahl für den Herrn von süßem Duft! Man soll sie neben dem stetigen Brandopfer und dem dazu gehörenden Trankopfer noch bereiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Am siebten Tage sollt ihr Vorlesung am Heiligtum abhalten! Da dürft ihr keine Werktagsarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Am Tage der Erstlinge bringt dem Herrn ein neues Speiseopfer dar! An eurem Wochenfeste haltet Vorlesung im Heiligtum ab! Da dürft ihr keine Werktagsarbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'An Brandopfern zu süßem Duft für den Herrn bringt zwei junge Stiere, einen Widder, sieben noch nicht jährige Lämmer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Und als ihr Speiseopfer feines Mehl, mit Öl bereitet, drei Zehntel zum Stier, zwei Zehntel zum Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'ein Zehntel für jedes dieser sieben Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'und einen Ziegenbock, um Sühne euch zu schaffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Abgesehen vom stetigen Brandopfer und seinem Speiseopfer sollt ihr diese bereiten! Sie sollen bei euch fehlerlos sein, ebenso ihre Trankopfer!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '\"\'Am ersten Tage des siebten Mondes sollt ihr Vorlesung am Heiligtum halten! Da dürft ihr keine Werktagsarbeit tun. Er sei euch ein Tag des Jubels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Als Brandopfer zu süßem Duft für den Herrn bereitet einen jungen Farren, einen Widder, sieben fehlerlose, noch nicht jährige Lämmer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Dazu als Speiseopfer feines Mehl, mit Öl bereitet, drei Zehntel für den Stier, zwei Zehntel für den Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'ein Zehntel für jedes der sieben Lämmer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Und einen Ziegenbock als Sündopfer, um euch Sühne zu schaffen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'abgesehen vom Neumondbrandopfer und seinem Speiseopfer sowie vom stetigen Brandopfer und seinem Speiseopfer und ihren Trankopfern, wie es sich gebührt, zu süßem Duft als Mahl für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Am zehnten Tage desselben Mondes sollt ihr am Heiligtum Vorlesung hatten und euch kasteien! Keinerlei Arbeit dürft ihr tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Als Brandopfer dem Herrn zu süßem Duft bringt einen jungen Farren, einen Widder, sieben noch nicht jährige Lämmer dar! Sie sollen bei euch fehlerlos sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Und als ihr Speiseopfer feines Mehl, mit Öl bereitet, drei Zehntel für den Stier, zwei Zehntel für den Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'ein Zehntel für jedes der sieben Lämmer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Und einen Bock als Sündopfer noch zum Sündopfer für Entsündigung und zum stetigen Brandopfer und zu seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Am fünfzehnten des siebten Monats sollt ihr Vorlesung am Heiligtum halten! Da dürft ihr keine Werktagsarbeit tun! Feiert ein Fest dem Herrn sieben Tage lang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Als Opfermahl süßen Duftes für den Herrn bringt dreizehn junge Stiere dar, zwei Widder und vierzehn noch nichtjährige, fehlerlose Lämmer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Und als ihr Speiseopfer feines Mehl, mit Öl bereitet, je drei Zehntel zu jedem der dreizehn Farren, je zwei Zehntel für die beiden Widder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'ein Zehntel für jedes der vierzehn Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'und einen Ziegenbock als Sündopfer außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Am zweiten Tage zwölf junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Am dritten Tage elf junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Am vierten Tage zehn junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Am fünften Tage neun junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Am sechsten Tage acht junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Am siebten Tage sieben junge Stiere, zwei Widder und vierzehn noch nicht jährige, fehlerlose Lämmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'dazu ihre Speise- und ihre Trankopfer zu diesen Farren, Widdern, Lämmern nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'und einen Ziegenbock als Sündopfer noch außer dem stetigen Brandopfer und seinem Speise- und Trankopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Am achten Tage haltet Festversammlung ab! Da dürft ihr keine Werktagsarbeit tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'An Brandopfern als ein Mahl süßen Duftes für den Herrn bringt einen Farren, einen Widder, sieben fehlerlose noch nicht jährige Lämmer dar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'sodann ihr Speise- und ihr Trankopfer zum Farren, zum Widder und zu den Lämmern, nach ihrer Zahl, wie es sich gebührt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'und einen Bock als Sündopfer außer dem regelmäßigen Brandopfer, sowie sein Speise- und Trankopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'An euren Festen sollt ihr sie für den Herrn bereiten, abgesehen von den Brand- und Speiseopfern, die ihr gelobet oder freiwillig darbringt, sowie den Trank- und Dankopfern!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Und Moses redete zu den Israeliten so, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Und Moses redete mit den Stammeshäuptern der Israeliten also: \"Das ist es, was der Herr befiehlt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, '\'Macht einer ein Gelübde dem Herrn oder schwört er einen Eid, wodurch er seiner Seele eine Bindung aufbindet, so darf er sein Wort nicht brechen! So, wie er es ausgesprochen, soll er handeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Macht aber ein Weib dem Herrn ein Gelöbnis und bindet sich in ihres Vaters Haus im Ledigstand eine Bindung auf');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'und ihr Vater hört vom Gelöbnis und der Bindung, die sie ihrer Seele aufgebunden, und schweigt ihr Vater dazu, dann gelten all die Gelübde, und jede Bindung, die sie auf ihre Seele gebunden, gilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Wenn aber ihr Vater am Tage, an dem er es hört, ihr wehrt, dann gelten all die Gelübde und Bindungen nicht, die sie auf ihre Seele gebunden. Der Herr vergibt ihr, weil ihr Vater ihr gewehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Sollte sie aber eines Mannes werden, solange die Gelübde oder sonst ein unbedacht gesprochen Wort, das sie auf ihre Seele gebunden, auf ihr lasten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'und ihr Mann hört davon und schweigt, nachdem er es gehört, dann gelten die Gelübde, ebenso die Bindung, die sie ihrer Seele aufgebunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Doch wehrt ihr Mann es ihr, wenn er davon hört, so zerreißt er ihr Gelübde, das ihr obliegt, sowie das unbedacht gesprochene Wort, das sie auf ihre Seele gebunden. Der Herr verzeiht es ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Das Gelübde einer Witwe und einer Verstoßenen, überhaupt alles, was sie auf ihre Seele gebunden, gilt für sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Macht sie aber im Hause ihres Mannes ein Gelübde oder bindet sie durch Eid eine Bindung auf ihre Seele');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'und hört ihr Mann davon, doch schweigt er dazu, ohne ihr zu wehren, dann sind alle ihre Gelübde gültig, ebenso gilt jede Bindung, die sie auf ihre Seele gebunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Zerreißt ihr Mann sie aber an dem Tage, an dem er davon hört, so gilt nichts von dem, was sie ausgesprochen, sei es Gelöbnis oder Bindung. Ihr Mann hat sie zerrissen. Der Herr wird ihr verzeihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Jedes Gelübde und allen Bindungsschwur zur Beugung der Seele bestätigt ihr Mann und ihr Mann zerreißt es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Schweigt aber ihr Mann dazu von Tag zu Tag, so bestätigt er alle Gelübde oder all ihre Bindungen, die ihr obliegen. Er bestätigt sie; denn er hat dazu geschwiegen an dem Tage, an dem er es gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Zerreißt er sie dann noch, nachdem er davon gehört, so lädt er ihre Schuld auf sich.\'\" Das sind die Gesetze, die der Herr dem Moses gab für das Verhältnis zwischen Mann und Weib, zwischen dem Vater und seiner ledigen Tochter im Vaterhaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '\"Nimm Rache an den Midianitern für Israels Söhne! Danach wirst du zu deinen Stammesgenossen aufgenommen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Und Moses sprach zu dem Volke: \"Wählt unter euch die tüchtigsten der Männer zu einem Kriegszug! Sie sollen über Midian kommen, um an Midian die Unbill am Herrn zu rächen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Je tausend von allen Stämmen Israels sendet zum Heer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Da wurden aus den Geschlechtern Israels je tausend von jedem Stamm aufgerufen, 12.000, die Auslese des Heeres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Moses sandte sie nun, je tausend von jedem Stamm, zum Zuge aus und Eleazars Sohn Pinechas als Feldpriester. Er hatte die heiligen Geräte, die Lärmtrompeten, bei sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'So zogen sie gen Midian zu Feld, wie der Herr dem Moses befohlen, und schlugen alles Männliche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Auch schlugen sie Midians Könige zu den anderen von ihnen Geschlagenen, Ewi, Rekem, Sur, Chur und Reba, die fünf Könige Midians. Auch Beors Sohn Bileam hatten sie mit dem Schwert geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Dann führten die Israeliten die Weiber und Kinder Midians gefangen fort, und all ihre Lasttiere und all ihr Herdenvieh erbeuteten sie, ihre ganze Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Und alle ihre Gehöfte in ihren Siedlungen und alle ihre Zeltlager steckten sie in Brand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Dann nahmen sie allen Raub und alle Beute an Mensch und Vieh');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'und brachten sie zu Moses und dem Priester Eleazar und zur israelitischen Gemeinde, die Gefangenen, die Beute und den Raub zum Lager in Moabs Steppen am Jordan bei Jericho.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Da gingen Moses und der Priester Eleazar mit allen Edlen der Gemeinde ihnen entgegen vor das Lager hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Moses aber ward über die Heerführer zornig, über die Hauptleute der Tausend und der Hundert, die vom Kriegszug kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Und Moses sprach zu ihnen: \"Habt ihr alles Weibliche am Leben gelassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Gerade sie haben den Söhnen Israels, nach Bileams Wort, dazu gedient, um Peors willen dem Herrn die Treue zu brechen, daß ein Gemetzel in des Herrn Gemeinde ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Nun tötet alles Männliche unter den Kindern! Und jedes Eheweib tötet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Dagegen laßt für euch am Leben alle noch unverehelichten Mädchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ihr selbst bleibt sieben Tage außerhalb des Lagers, jeder, der eine Person tötet, und jeder, der Erschlagene berührt hat. Ihr müßt am dritten und siebten Tage euch entsündigen samt euren Mannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Ebenso müßt ihr jedes Gewand und jedes Lederzeug und jedes Ziegenhaarwerk und alles Holzgerät entsündigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Und der Priester Eleazar sprach zu den Kriegsleuten, die in den Kampf gezogen waren: \"Dies ist die Weisung des Gesetzes, das der Herr dem Moses geboten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Gold und Silber, Kupfer, Eisen, Zinn und Blei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'alles, was in das Feuer kommen kann, sollt ihr durchs Feuer gehen lassen! Dann ist es rein. Jedoch muß es mit Reinigungswasser entsündigt werden. Was aber nicht ins Feuer kommen kann, laßt durchs Wasser gehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Wascht eure Kleider am siebten Tage! Dann seid ihr rein. Hernach dürft ihr ins Lager kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '\"Die Hauptbeute an Menschen und Vieh nimm auf, du und der Priester Eleazar und die Familienhäupter der Gemeinde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'und gib von der Beute eine Hälfte denen, die gekämpft und ins Feld gezogen sind, die andere der Gesamtgemeinde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Dann erhebe eine Abgabe für den Herrn von den Kriegern, die ins Feld gezogen, ein Stück von je fünfhundert, von Menschen, Rindern, Eseln, Schafen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Von ihrer Hälfte sollt ihr sie nehmen! Gib sie als Abgabe für den Herrn dem Priester Eleazar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Und von der Hälfte der Söhne Israels sollst du immer eins von fünfzig dir herausgreifen aus Menschen, Rindern, Eseln, Schafen und allem anderen Vieh! Gib sie den Leviten, die des Dienstes an der Wohnstätte des Herrn warten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Moses und der Priester Eleazar taten, wie der Herr dem Moses befahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Da belief sich der Gewinn, nach Abzug der Beute, die das Kriegsvolk für sich erbeutete, auf 675.000 Schafe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, '72.000 Rinder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'und 61.000 Esel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Von Menschenwesen betrug die Zahl der weiblichen ledigen Personen insgesamt 32.000 Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Der halbe Anteil, der den ins Feld Gezogenen zufiel, betrug 337.500 Schafe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'die Abgabe von den Schafen für den Herrn 675,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'ferner 36.000 Rinder, die Abgabe davon für den Herrn 72,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'ferner 30.500 Esel, die Abgabe hiervon für den Herrn 61,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'und 16.000 menschliche Personen, die Abgabe davon für den Herrn 32 Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Und Moses überwies die Abgabe der Weihegabe des Herrn dem Priester Eleazar, wie der Herr dem Moses befahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Aus der für die Israeliten bestimmten Hälfte, die Moses von der der Kriegsleute aussonderte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '- die der Gemeinde bestimmte Hälfte betrug 337.500 Schafe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, '36.000 Rinder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, '30.500 Esel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'und 16.000 Menschen -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'aus der den Israeliten bestimmten Hälfte also griff Moses immer eins von fünfzig heraus, aus Menschen und Tieren, und übergab sie den Leviten, die des Dienstes an des Herrn Wohnung warteten, wie der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Da traten zu Moses die Anführer der Tausendschaften des Heeres, die Hauptleute der Tausendschaften und die der Hundertschaften');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'und sprachen zu Moses: \"Deine Diener haben die Gesamtzahl aller Leute für den Kriegszug aufgenommen, der unter unserer Führung geschehen ist, und nicht ein Mann wird von uns vermißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'So bringen wir als Opfergabe für den Herrn, was jeder gefunden hat an goldenen Geräten, Armketten und Spangen, Fingerringen, Ohrringen und Geschmeide, um uns vor dem Herrn zu entsühnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Da nahmen Moses und der Priester Eleazar von ihnen das Gold, lauter Gefäße kunstvoller Arbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Alles Gold der Weihegabe, die sie dem Herrn darbrachten, belief sich auf 16.750 Korn Ringe von den Hauptleuten der Tausendschaften und den der Hundertschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Die gemeinen Krieger aber hatten jeder für sich die Beute behalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'So nahmen Moses und der Priester Eleazar das Gold von den Hauptleuten der Tausendschaften und der Hundertschaften und brachten es ins Festgezelt, zum Andenken für die Israeliten vor dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubens und Gads Söhne aber hatten einen großen, überreichen Herdenstand. Sie sahen nun das Land Jazer und das Land Gilead. Die Gegend aber war eine Herdengegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'So kamen Gads und Rubens Söhne und sprachen zu Moses und dem Priester Eleazar, sowie zu den Edlen der Gemeinde:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '\"Atarot, Dibon, Jazer, Nimra, Chesbon, Elale, Sebam, Nebo, Beon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'das Land, das der Herr vor der israelitischen Gemeinde niedergeworfen, ist ein Herdenland, und deine Knechte haben Herden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Und sie sprachen: \"Finden wir in deinen Augen Gnade, so werde dieses Land zum Besitz deinen Knechten verliehen! Siedle uns nicht über dem Jordan an!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Da sprach Moses zu Gads und Rubens Söhnen: \"Sollen eure Brüder in die Schlacht ziehen, und ihr wollt hier bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Warum hindert ihr das Herz der Söhne Israels, hinüberzuziehen in das Land, das ihnen der Herr gegeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'So haben eure Väter getan, als ich sie von Kades Barnea zur Besichtigung des Landes gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Sie kamen bis zum Traubental hinauf und besahen das Land. Dann hinderten sie das Herz der Söhne Israels, ins Land zu kommen, das ihnen der Herr gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Da geriet der Herr an jenem Tage in Zorn und tat den Schwur:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '\'Die Männer, die aus Ägypten gezogen, von zwanzig Jahren aufwärts, sollen nie die Gegend sehen, die ich dem Abraham, Isaak und Jakob zugeschworen habe! Denn sie sind mir nicht voll ergeben gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Nur der Keniziter Kaleb, Jephunnes Sohn, und Josue, der Sohn des Nun, sind mir voll ergeben gewesen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Da ward der Herr zornig über Israel und ließ sie in der Wüste vierzig Jahre umherirren, bis daß ausgestorben war dies Geschlecht, das Böses in des Herrn Augen getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Ihr steht nun an eurer Väter Stelle, eine Brut sündiger Menschen, nur um des Herrn Zornesglut über Israel noch zu steigern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Und wendet ihr euch von ihm ab, so beläßt er es noch länger in der Wüste. So stürzt ihr dies ganze Volk ins Verderben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Da drangen sie auf ihn ein und sprachen: \"Hier wollen wir für unseren Herdenstand Schafhürden bauen und für unsere kleinen Kinder Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Wir selbst aber wollen als Vortrupp den Israeliten voranziehen, bis daß wir sie an ihren Ort gebracht. Doch unsere kleinen Kinder sollen vor des Landes Insassen in festen Städten sitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'In unsere Häuser kehren wir nicht zurück, bis von den Israeliten jeder zu seinem Besitz gelangt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Denn wir wollen nicht mit ihnen zusammen über dem Jordan und weiterhin Besitz bekommen, wenn uns unser Besitz östlich über dem Jordan zufällt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Da sprach Moses zu ihnen: \"Wollt ihr das tun, wollt ihr vor dem Herrn sturmbereit zum Kampf voranschreiten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'und überschreitet ihr vor dem Herrn, jeder von euch sturmbereit, den Jordan, bis daß er seine Feinde vor sich vertilgt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'und wird dieses Land vor dem Herrn niedergeworfen, und kehrt ihr danach heim, dann seid ihr dem Herrn und Israel gegenüber unsträflich, und dieses Land falle euch vom Herrn aus als Besitztum zu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Doch tut ihr nicht so, dann sündigt ihr an dem Herrn. Wisset dann, daß eure Sünden euch finden werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Baut euch also Städte für eure kleinen Kinder und Hürden für eure Schafe! Doch tut, was ihr ausgesprochen habt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Da sprachen Gads und Rubens Söhne zu Moses: \"Deine Knechte werden so tun, wie unser Herr befiehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Unsere kleinen Kinder, unsere Weiber, unser Herdenstand und all unser Vieh bleibe hier in Gileads Städten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Doch deine Knechte ziehen hinüber, jeder sturmbereit, vor dem Herrn in den Krieg, wie es der Herr gesagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Da gab Moses dem Priester Eleazar und Nuns Sohn, Josue, sowie den väterlichen Stammhäuptern der Israeliten ihretwegen Anweisung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Und Moses sprach zu ihnen: \"Überschreiten mit euch vor dem Herrn die Söhne Gads und Rubens den Jordan, jeder sturmbereit, und wird das Land erobert und es stellt euch frei, dann gebt ihnen zu eigen das Land Gilead!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ziehen sie aber nicht mit euch sturmbereit hinüber, so müssen sie bei euch im Lande Kanaan siedeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Da antworteten Gads und Rubens Söhne: \"Wir tun so, wie der Herr von deinen Knechten verlangt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Wir ziehen vor dem Herrn sturmbereit ins Land Kanaan hinüber und so kommen wir in unseren Besitz jenseits des Jordans.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'So gab Moses ihnen, den Söhnen Gads und Rubens, und dem halben Stamme Manasses, des Josephsohnes, das Reich des Amoriterkönigs Sichon und das des Basankönigs Og, das Land mit seinen Städten nach Gemarkungen, die Städte des Landes ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'So bauten Gads Söhne Dibon, Atarot und Aroer wieder auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'ebenso Aterot Sophan, Jazer, Jogbeha,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bet Nimra und Bet Haran, feste Städte und Schafhürden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubens Söhne aber bauten Chesbon, Elale, Kirjataim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo und Baal Meon mit verändertem Namen wieder auf und Sibma, und sie gaben ihren Namen den Städten, die sie aufbauten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Die Söhne Makirs, des Manassesohnes, zogen nach Gilead, eroberten es und vertrieben den Amoriter, der darin war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Und Moses verlieh Gilead dem Makir, Manasses Sohn, und er wohnte darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Manasses Sohn Jair zog aus, eroberte ihre Zeltdörfer und nannte sie Zeltdörfer Jairs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobach zog aus, eroberte Kenat mit seinen Tochterorten und benannte es nach seinem Namen Nobach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Dies sind der Israeliten Züge, auf denen sie aus Ägypterland nach ihren Scharen unter Mosis und Aarons Führung gezogen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Moses schrieb ihre Ausfahrten zu ihren Zügen nieder auf des Herrn Befehl. Dies sind ihre Züge zu ihren Ausfahrten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Sie zogen von Ramses weg am fünfzehnten Tage des ersten Monats. Am Tage nach dem Passah zogen die Israeliten aus, in dichter Schar vor ganz Ägyptens Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'während die Ägypter verkündeten, daß der Herr bei ihnen jede Erstgeburt erschlagen und daß der Herr an ihren Göttern Strafgerichte vollzogen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Die Israeliten zogen nun von Ramses fort und lagerten in Sukkot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Von Sukkot zogen sie fort und lagerten in Etam am Rande der Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Von Etam zogen sie fort und wandten sich nach Pihachirot vor Baalsephon und lagerten vor Migdol.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Sie zogen von Pihachirot fort und schritten mitten durch das Meer in die Wüste. Sie wanderten drei Tagereisen und lagerten in Mara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Sie zogen von Mara fort und kamen nach Elim. In Elim waren zwölf Quellen und siebzig Palmbäume, und sie lagerten dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Sie zogen von Elim fort und lagerten am Schilfmeer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Sie zogen vom Schilfmeer fort und lagerten in der Wüste Sin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Von der Wüste Sin zogen sie fort und lagerten in Dophka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Sie zogen von Dophka fort und lagerten in Alus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Von Alus zogen sie fort und lagerten in Raphidim. Da war kein Wasser für das Volk zum Trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Von Raphidim zogen sie fort und lagerten in der Wüste Sinai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Von der Wüste Sinai zogen sie fort und lagerten bei den Gelüstegräbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Von den Gelüstegräbern zogen sie nach Chaserot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'von Chaserot nach Ritma,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'von Ritma nach Rimmon Peres,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'von Rimmon Peres nach Libna,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'von Libna nach Rissa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'von Rissa nach Kehela,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'von Kehela zum Berge Sepher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'vom Berge Sepher nach Charada,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'von Charada nach Makhelot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'von Makhelot nach Tachat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'von Tachat nach Tarach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'von Tarach nach Mitka,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'von Mitka nach Chasmon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'von Chasmon nach Moserot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'von Moserot nach Bene Jaakan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'von Bene Jaakan nach Chor Hagidgad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'von Chor Hagidgad nach Jotba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'von Jotba nach Abron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'von Abron nach Esiongeber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'von Esiongeber in die Wüste Sin, das ist Kades,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'von Kades zum Berge Hor an der Grenze des Landes Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Und der Priester Aaron stieg auf den Berg Hor nach des Herrn Befehl und starb hier, im vierzigsten Jahre nach dem Auszug der Israeliten aus Ägypterland, am ersten des fünften Monats.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aaron aber war 123 Jahre alt, als er auf dem Berge Hor starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Da hörte der Kanaaniter, Arads König, der im Süden des Landes Kanaan saß, vom Anmarsch der Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Sie zogen dann vom Berge Hor fort und lagerten in Salmon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Von Salmon ging es nach Punon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Von Punon nach Obot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Von Obot nach Ijje Haabarim im Gebiete Moabs,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'von Ijjim nach Dibon Gad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'von Dibon Gad nach Almon Diblataim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'von Almon Diblataim zum Ufergebirge von Nebo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Vom Ufergebirge zogen sie fort und lagerten in den Steppen Moabs am Jordan bei Jericho,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'und zwar lagerten sie am Jordan von Bet Hajesimot bis Abel Hasittim in Moabs Steppen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Und der Herr sprach zu Moses in Moabs Steppen am Jordan bei Jericho:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '\"Rede mit den Söhnen Israels und sprich zu ihnen: \'Zieht ihr über den Jordan ins Land Kanaan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'dann müßt ihr alle Insassen des Landes vor euch vertilgen und alle ihre Bilder vernichten. Auch alle ihre Gußbilder sollt ihr vernichten und alle ihre Höhen verwüsten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Vom Lande ergreift Besitz und siedelt darin! Denn euch gebe ich das Land zum Besitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Verteilt das Land nach euren Stämmen durch das Los! Dem, der viel zählt, sollt ihr seinen Besitz vermehren und dem, der wenig zählt, einen kleineren geben! Was jemandem durchs Los zufällt, soll ihm gehören! Nach euren väterlichen Stämmen sollt ihr es verteilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Vertreibt ihr aber nicht vor euch des Landes Insassen, dann werde, was ihr davon übriglaßt, euch zu Dornen in den Augen und zu Stacheln in den Seiten! Sie sollen euch bedrängen in eurem Lande, in dem ihr siedelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Dann tue ich mit euch, was ich jenen zugedacht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '\"Befiehl den Söhnen Israels und sprich zu ihnen: Kommt ihr in das Land Kanaan, dann ist dies das Land, das euch als Eigentum zufällt, das Land Kanaan nach seinen Grenzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Der Südsaum sei euch von der Wüste Sin an Edom entlang, und zwar sei euch Südgrenze das Ende des Salzmeeres im Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Dann wende sich euch die Grenze südlich von der Skorpionensteige und gehe weiter nach Sin hinüber, bis sie südlich von Kades Barnea endet! Dann laufe sie nach Chasar Addar aus und gehe weiter nach Asmon!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Die Grenze wende sich von Asmon zum Bach Ägyptens, bis sie am Meer endet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Westgrenze sei euch das große Meer und seine Küste! Das soll eure Westgrenze sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Nordgrenze soll euch dies sein: Vom großen Meere sollt ihr sie euch bis zum Berge Hor ziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Vom Berge Hor sollt ihr sie euch bis Chamat ziehen! Endpunkt der Grenze sei Sedad!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Dann laufe die Grenze nach Siphron und weiter bis Chasar Enan als ihrem Endpunkt! Dies soll eure Nordgrenze sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Als Ostgrenze setzet euch fest die Strecke von Chasar Enan bis Sepham!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Die Grenze senke sich von Sepham nach Rebel, östlich von Ain! Dann senke sich die Grenze und stoße auf den Bergrücken östlich vom See Genesareth!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Dann senke sich die Grenze an den Jordan, bis sie am Salzmeer endet! Das sollen ringsum des Landes Grenzen sein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Und Moses gebot den Israeliten: \"Das ist das Land, das ihr euch durch das Los zueignen sollt und das der Herr den neuneinhalb Stämmen zu geben befohlen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Denn die Familien des Stammes der Rubensöhne und die Familie des Stammes der Gadsöhne und der halbe Stamm Manasse hatten ihren Besitz schon erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Die zweieinhalb Stämme hatten ihren Besitz jenseits des Jordan, auf der Ostseite des Jordan bei Jericho erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '\"Dies sind die Namen der Männer, die euch das Land zuteilen sollen: der Priester Eleazar und Josue, des Nun Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Zieht von jedem Stamme je einen Fürsten bei der Landesverteilung hinzu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Dies sind die Namen der Männer: vom Stamme Juda Kaleb, Jephunnes Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'vom Stamme der Simeonsöhne Semuel, Ammihuds Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'vom Stamme Benjamin Elidad, Kislons Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'vom Stamme der Dansöhne als Fürst Bukki, Joglis Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'von den Josephsöhnen, vom Stamme der Manassesöhne, als Fürst Channiel, Ephods Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'vom Stamme der Ephraimsöhne als Fürst Kemuel, Siphtans Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'vom Stamme der Zabulonsöhne als Fürst Elisaphan, Parnaks Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'vom Stamme der Issakarsöhne als Fürst Paltiel, Azzans Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'vom Stamme der Assersöhne als Fürst Achihud, Selomis Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'von Stamme der Naphtalisöhne, als Fürst Pedahel, Ammihuds Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Das sind die, denen der Herr befohlen, den Israeliten im Lande Kanaan ihren Besitz auszuteilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Und der Herr redete mit Moses in Moabs Steppen am Jordan bei Jericho:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '\"Befiehl den Söhnen Israels, daß sie von ihrem Besitze den Leviten Städte zum Siedeln geben! Auch die Weidetrift rings um die Städte sollt ihr den Leviten geben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Die Städte seien ihnen zum Besiedeln, die Weidetriften aber seien für ihr Vieh, ihre Habe und all ihren Lebensbedarf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Der Städte Weidetriften, die ihr den Leviten geben sollt, seien ringsum tausend Ellen weit von der Stadtmauer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Meßt außerhalb der Stadt zweitausend Ellen auf der Ostseite ab, desgleichen südlich, westlich, nördlich, so daß die Stadt in die Mitte kommt! Das soll ihnen Weidetrift bei den Städten sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Und den Städten, die ihr den Leviten geben sollt, sechs Freistädten, die ihr abtretet, daß der Totschläger dahin fliehe, sollt ihr noch zweiundvierzig andere hinzufügen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'All der Städte, die ihr den Leviten gebt, sind es achtundvierzig samt den Weidetriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Die Zahl der Städte, die ihr vom Besitz der Söhne Israels abtretet, sollt ihr bei den Größeren größer bemessen und bei den kleineren kleiner! Jeder soll entsprechend dem Besitz einige seiner Städte den Leviten geben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Und der Herr sprach zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '\"Sag den Söhnen Israels und sprich zu ihnen: \'Wenn ihr, den Jordan überschreitend, in das Land Kanaan kommt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'dann wählt Städte, die euch so gelegen sind, daß sie euch Freistädte seien! Dorthin fliehe jeder Totschläger und jeder, der einen Menschen unvorsätzlich erschlagen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Die Städte seien euch Zuflucht vor Bluträchern, daß nicht der Totschläger den Tod leide, bis er vor der Gemeinde zum Gericht gestanden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Der Städte, die ihr dazu hergebt, seien es sechs! Sie sollen euch Freistädte sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Drei der Städte sollt ihr über dem Jordan abtreten und drei Städte im Lande Kanaan! Freistädte seien es!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Den Söhnen Israels sowie dem Gast und dem Beisassen bei euch sollen die sechs Städte eine Zuflucht sein, daß jeder dorthin fliehe, der unvorsätzlich einen Menschen erschlagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Hat er ihn aber mit einem eisernen Gerät geschlagen, daß er starb, dann ist er ein Mörder. Der Mörder leide den Tod!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Und hat er ihn mit einem handlichen Steine getroffen, wodurch jemand sterben kann, und er starb, dann ist er ein Mörder. Der Mörder leide den Tod!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Und hat er ihn mit einem handlichen Holzgerät getroffen, wodurch jemand sterben kann, und er starb, dann ist er ein Mörder. Der Mörder leide den Tod!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Der Bluträcher soll selber den Mörder töten! Wo er auf ihn trifft, soll er ihn töten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Und hat dieser jemandem aus Haß einen Stoß gegeben, oder hat er nach ihm hinterlistig geworfen, daß er starb,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'oder hat er ihn aus Feindschaft mit der Hand niedergeschlagen, daß er starb, dann leide der, der ihn geschlagen, den Tod! Er ist ein Mörder. Der Bluträcher soll den Mörder töten, wo er ihn trifft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Hat er von ungefähr jemanden gestoßen, ohne Feindschaft, oder hat er irgendein Gerät auf ihn geworfen, ohne daß er zielte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'oder hat er irgendeinen Stein, wodurch einer sterben kann, unversehens auf ihn fallen lassen, daß er starb, ist ihm aber kein Feind gewesen und hat ihm nichts Böses tun wollen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'dann richte die Gemeinde zwischen dem Totschläger und dem Bluträcher nach diesen Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Den Totschläger beschütze die Gemeinde vor der Hand des Bluträchers! Die Gemeinde bringe ihn in seine Zufluchtsstadt, in die er fliehen will! Er bleibe dort bis zum Tode des Hohenpriesters, den man mit heiligem Öl gesalbt hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Verläßt aber der Totschläger die Gemarkung seiner Zufluchtsstadt, in die er sich gerichtet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'und trifft ihn der Bluträcher außerhalb der Gemarkung seiner Zufluchtsstadt und tötet der Bluträcher den Totschläger, dann ist kein Mord an ihm verübt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Er soll ja bis zum Tode des Hohenpriesters in der Zufluchtsstadt verbleiben! Doch nach des Hohenpriesters Tod darf der Totschläger zu seines Besitzes Boden zurückkehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Dies sei euch Rechtssatzung für eure Geschlechter in allen euren Siedlungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Wenn jemand einen Menschen umbringt, so soll man den Mörder nach dem Mund von Zeugen hinrichten! Ein einziger Zeuge aber soll nicht aussagen gegen jemand, daß er sterbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Ihr sollt kein Lösegeld für das Leben eines Mörders annehmen, der des Todes schuldig ist! Er muß den Tod leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Ihr sollt auch keine Gegengabe dafür nehmen, daß einer in seine Zufluchtsstadt flieht und dann heimkehrt, bevor der Priester gestorben ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Ihr dürft das Land, in dem ihr wohnt, nicht entweihen. Denn Blut entweiht das Land. Sühne wird dem Land für das darin vergossene Blut nur durch das Blut dessen, der es vergossen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Ihr sollt also nicht das Land unrein machen, in dem ihr siedelt, weil auch ich darin wohne! Denn ich, der Herr, wohne mitten unter Israels Söhnen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Da kamen die Familienhäupter der Sippe der Söhne Gileads, des Sohnes Makirs, des Enkels Manasses, von den Sippen der Josephsöhne und brachten vor Moses und die Fürsten, die israelitischen Familienhäupter, ein Anliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Sie sprachen: \"Der Herr hat meinem Herrn befohlen, das Land durchs Los zum Besitze den Söhnen Israels zu geben; und meinem Herrn ward vom Herrn befohlen, das Erbe unseres Bruders Selophchad seinen Töchtern zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Heiraten diese einen der Söhne aus den anderen israelitischen Stämmen, dann wird ihr Besitz dem ihrer Väter entzogen und zu dem Besitze des Stammes geschlagen, dessen Angehörigen sie heiraten. So wird der Besitz, der durch das Los uns zugefallen, geschmälert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Selbst wenn das Jubeljahr für Israels Söhne kommt, dann bleibt ihr Besitz bei dem Stamme, dessen Angehörigen sie heiraten. So wird der Besitz dem unseres väterlichen Stammes entzogen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Da gebot Moses den Israeliten nach des Herrn Befehl folgendes: \"Der Josephsöhne Stamm hat recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Das ist es, was der Herr für Selophchads Töchter verordnet: \'Sie mögen sich verheiraten, mit wem sie wollen. Nur müssen sie einen ihres Vaterstammes heiraten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'daß nicht ein Besitz der Söhne Israels von einem Stamme zum andern übergehe. An des Vaterstammes Besitz sollen alle Israeliten festhalten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Und jede Tochter, die in einem israelitischen Stamme zum Besitz gelangt, hat einen ihres Vaterstammes zu heiraten, damit bei den Israeliten jeder den väterlichen Besitz behauptet');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'und nicht ein Besitz von einem Stamme zum andern übergehe. Jeder der israelitischen Stämme soll an seinem Erbbesitze festhalten!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Wie der Herr dem Moses befohlen, so taten Selophchads Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Machla, Tirsa, Chogla, Milka und Noa, Selophchads Töchter, heirateten die Söhne ihrer Oheime.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Sie heirateten Angehörige aus den Sippen der Söhne Manasses, des Josephsohnes. Und so verblieb ihr Besitz bei dem Stamme ihrer väterlichen Sippe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Dies sind die Gebote und Satzungen, die der Herr durch Moses den Israeliten in Moabs Steppen am Jordan bei Jericho geboten hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Dies sind die Worte, die Moses zu ganz Israel gesprochen jenseits des Jordans in der Wüstensteppe gegenüber Suph zwischen Paran, Tophel, Laban, Chaserot und Dizahab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Elf Tage vom Horeb ab währte der Zug zum Gebirge Seïr bis nach Kades Barnea.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Im vierzigsten Jahre, am ersten Tage des elften Monats, kündete Moses den Israeliten alles, was ihm der Herr für sie entboten hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'nach seinem Siege über den Amoriterkönig Sichon, der in Chesbon und Edreï saß, und über den König von Basan, Og, der in Astarot saß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Jenseits des Jordans im Lande Moab begann Moses diese Lehre zu erläutern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '\"Der Herr, unser Gott, hat am Horeb also zu uns geredet: \'Genug sei eures Weilens an diesem Berge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Geht weiter und zieht geradewegs auf das Gebirge der Amoriter und zu allen ihren Nachbarn in der Steppe, auf dem Gebirge, in der Niederung, im Südland und an der Meeresküste, ins Land der Kanaaniter und zum Libanon bis zum großen Strome, dem Euphratstrom!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Seht! Ich gebe euch das Land. Zieht hinein und nehmt das Land, das der Herr euren Vätern Abraham, Isaak und Jakob und ihrem Stamme zugeschworen hat!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Zu jener Zeit sprach ich zu euch: \'Ich kann für euch nicht allein sorgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Der Herr, euer Gott, hat euch gemehrt, und ihr seid heute wie des Himmels Sterne an Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Möge der Herr, der Schutzgott eurer Väter, euch tausendfach hinzutun und euch segnen, wie er euch verheißen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Wie soll ich allein tragen eure Last, eure Bürde und euren Hader?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Wählt euch aus euren Stämmen weise, kluge und erfahrene Männer, damit ich sie zu euren Häuptern mache!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Da antwortetet ihr mir und sprachet: \'Gut ist, was du zu tun gedenkst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Da nahm ich eure Stammeshäupter, weise und erfahrene Männer, und machte sie zu euren Vorgesetzten als Oberste über Tausend, Hundert, Fünfzig und Zehn und als Beamte für eure Stämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Ich gebot zu gleicher Zeit euren Richtern: Verhört eure Brüder und richtet gerecht zwischen einem Manne und seinem Bruder und bei einem Fremdling!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Seid unparteiisch im Gericht und hört den Kleinen wie den Großen an! Scheut euch vor niemand! Denn das Gericht ist Gottes. Nur die Sache, die für euch zu schwierig ist, bringt vor mich, und ich will sie anhören!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Und so belehrte ich euch damals über alles, was ihr tun solltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Dann zogen wir vom Horeb weg und gingen nach des Herrn, unseres Gottes, Befehl auf den Weg zum Amoritergebirge durch jene ganz große, schaurige Steppe, die ihr geschaut habt. Und so kamen wir nach Kades Barnea.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Da sprach ich zu euch: \'Ihr seid zum Amoritergebirge gekommen, das uns der Herr, unser Gott, geben will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Siehe! Der Herr, dein Gott, gibt dir das Land. Steig hinan! Besetze es, wie der Herr, deiner Väter Gott, dir zugesagt! Seid furchtlos und unverzagt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Da tratet ihr alle vor mich und spracht: \'Wir wollen Männer vor uns hersenden, damit sie uns das Land erkunden und uns bescheiden über den Weg, auf dem wir hinaufziehen sollen, und über die Städte, in die wir kommen werden!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Der Vorschlag gefiel mir, und so wählte ich aus euch zwölf Männer, je einen für jeden Stamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Sie gingen weiter und zogen ins Gebirge und kamen bis ins Traubental und spähten es aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Sie nahmen von des Landes Früchten und brachten sie uns herüber. Sie gaben uns Bescheid und sprachen: \'Das Land ist schön, das uns der Herr, unser Gott, gibt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Aber ihr wolltet nicht hinaufziehen und widerstrebtet dem Geheiß des Herrn, eures Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Ihr murrtet in euren Zelten und spracht: \'Aus Haß gegen uns hat der Herr uns aus Ägypten herausgeführt, um uns in die Hand der Amoriter zu geben, daß sie uns vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Wohin wollen wir ziehen? Unsere Brüder schmolzen unser Herz; sie sprachen: \"Leute, größer und stärker als wir, und Städte, groß und himmelhoch umwehrt, selbst Enakiter sahen wir dort.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Ich sprach zu euch: \'Entsetzt euch nicht und fürchtet euch nicht vor ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Der Herr, euer Gott, zieht euch voran. Er streitet selbst für euch, wie er mit euch in Ägypten vor euren Augen getan');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'und wie in der Steppe, die du verkostet, wo dich der Herr, dein Gott, getragen, wie ein Mann sein Kindlein trägt, auf dem ganzen Wege, den ihr gegangen, bis zu eurer Ankunft hier.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Aber trotzdem trautet ihr nicht dem Herrn, eurem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Und doch zog er euch auf dem Wege voran, euch ein Lager zu erkunden, des Nachts im Feuer, daß ihr auf dem Wege sehen konntet, den ihr zoget, und tagsüber in der Wolke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Und der Herr hörte eure lauten Reden. Da ward er zornig und schwur:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '\'Nicht einer dieser Männer aus diesem schlimmen Geschlechte soll das schöne Land erblicken, das ich euren Vätern zugeschworen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Nur Kaleb, der Sohn des Jephunne, soll es sehen. Ihm und seinen Kindern gebe ich das Land, das er betreten hat, weil er dem Herrn voll ergeben war.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Auch auf mich zürnte euretwegen der Herr, daß er sprach: Auch du sollst nicht dorthin kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Nur Josue, Nuns Sohn, dein ständiger Diener, wird dorthin kommen. Sprich ihm Mut zu! Denn er wird es Israel zu eigen geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Doch eure Kleinen, von denen ihr gesagt: \"Zur Beute werden sie\", ja eure Kinder, die heute noch nicht Gut und Böse kennen, kommen hinein. Ich gebe es ihnen, und sie nehmen es zu eigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ihr aber macht kehrt und zieht in die Steppe, dem Schilfmeere zu!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Da antwortetet ihr und spracht zu mir: \'Wir haben an dem Herrn gesündigt. Wir ziehen hinauf und kämpfen, wie uns der Herr, unser Gott, gebot.\' Ihr umgürtetet jeder seine Waffen und erkühntet euch, ins Gebirge zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Da sprach der Herr zu mir: \'Sag ihnen: \"Zieht nicht hinauf und kämpft nicht! Ich bin nicht bei euch. Sonst werdet ihr von euren Feinden geschlagen\"\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Ich redete euch zu; aber ihr hörtet nicht, sondern widerstrebtet des Herrn Befehl und zoget dreist ins Gebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Da rückten die Amoriter auf jenem Gebirge euch entgegen, verfolgten euch wie Bienen und zersprengten euch von Seïr bis Chorma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Da kehrtet ihr wieder heim und weintet vor dem Herrn. Aber der Herr achtete nicht auf euer Klagen und hörte nicht auf euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'So saßet ihr zu Kades lange Zeit, ebenso lange, wie ihr dort gesessen habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '\"Wir machten kehrt, zogen nach der Steppe auf das Schilfmeer zu, wie der Herr zu mir gesagt, und kreisten lange Zeit um das Gebirge Seïr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Da sprach der Herr zu mir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '\'Genug eures Kreisens um dieses Gebirge! Wendet euch nach Norden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Dem Volke befiehl also: \"Ihr wollt durch das Gebiet der Söhne Esaus ziehen, eurer Brüder, die in Seïr wohnen. Sie werden euch fürchten. Aber nehmt euch in acht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Befehdet sie nicht! Ich gebe euch keinen Fußbreit von ihrem Land; denn ich habe Esau das Gebirge Seïr zum Besitz verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Ihr sollt ihnen für Geld Speise abkaufen, die ihr eßt, und Wasser von ihnen erhandeln, das ihr trinkt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Der Herr, dein Gott, hat dich ja gesegnet in all deinem Händewerk. Er sorgt für deinen Marsch durch diese große Steppe. Vierzig Jahre ist der Herr, dein Gott, mit dir. Dir hat nichts gefehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Wir zogen vorüber an unseren Brüdern, den Söhnen Esaus zu Seïr, auf der Arabastraße, vorüber an Elat und Esiongeber. Wir wandten uns und zogen auf Moabs Steppe zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Da sprach der Herr zu mir: \'Befehde nicht die Moabiter! Stürze dich in keinen Kampf mit ihnen! Ich gebe dir ja von ihrem Lande nichts zu eigen; denn ich habe Ar den Söhnen Lots zum Besitz verliehen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Vordem wohnten die Emiter darin, ein Volk, so groß, zahlreich und hochgewachsen wie die Enakiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Auch sie gelten als Rephaiter, wie die Enakiter. Die Moabiter nennen sie Emiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'In Seïr saßen vordem die Choriter. Die Esausöhne aber besiegten und vertilgten sie und siedelten an ihrer Stelle, wie Israel mit dem Land getan, das ihm der Herr zu eigen gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '\'Nun auf! Setzt über den Zaredbach!\' Da überschritten wir den Bach Zared.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Wir sind achtunddreißig Jahre unterwegs gewesen, von Kades Barnea bis zur Überschreitung des Zaredbaches. Bis dahin war das ganze Geschlecht der Kriegsmänner aus dem Lager weggestorben, wie es ihnen der Herr geschworen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Die Hand des Herrn war aber gegen sie gewesen, um sie voll aus dem Lager zu vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Als alle Kriegsmänner aus dem Volke weggestorben waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'sprach der Herr zu mir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '\'Du ziehst heute durch die Grenzmark Moabs und an Ar vorüber');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'und näherst dich den Ammonitem. Befehde und befeinde sie nicht! Ich gebe dir ja vom Ammoniterlande nichts zu eigen; denn ich habe es den Söhnen Lots zu eigen gegeben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Es gilt auch als Rephaiterland. Vordem wohnten darin Rephaiter, von den Ammonitern Samsummiter genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Leute waren es, so groß, zahlreich und hochgewachsen wie die Enakiter. Der Herr aber vertilgte sie vor ihnen. Und so nahmen sie ihr Land und siedelten an ihrer Stelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'So hatte er auch für die Esausöhne zu Seïr getan. Vor ihnen vertilgte er die Choriter. So nahmen sie ihr Land und wohnten an ihrer Stelle bis auf den heutigen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Auch die Awwiter, die in Gehöften bis nach Gaza wohnten, waren vernichtet worden durch die Kaphtoriter, die aus Kaphtor auswanderten, und diese siedelten an ihrer Stelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '\'Auf! Zieht hin und setzt über den Arnonbach! Siehe! Ich gebe in deine Hand den Amoriter Sichon, Chesbons König, mit seinem Lande. Fang an mit dem Erobern! Greif sie an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Von jetzt an breite ich Furcht und Schrecken vor dir auf die Völker unter dem ganzen Himmel. Sobald sie von dir hören, sollen sie vor dir zittern und beben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Da sandte ich von der Steppe Kedemot Boten an Chesbons König Sichon mit friedlichen Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '\'Ich möchte dein Land durchziehen, will aber nur auf der Straße bleiben und weder rechts noch links abbiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Speise sollst du mir um Geld verkaufen, damit ich esse, und Wasser um Geld mir geben, damit ich trinke! Ich will nur durchziehen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Dies haben mir die Esausöhne zu Seïr und die Moabiter zu Ar gestattet, bis ich über den Jordan in das Land ziehe, das der Herr, unser Gott, uns geben will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Doch Chesbons König, Sichon, wollte uns nicht durchziehen lassen; denn der Herr, dein Gott, hatte seinen Sinn verhärtet und sein Herz verstockt, um ihn in deine Hand zu geben, wie es jetzt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Da sprach der Herr zu mir: \'Siehe! Ich mache den Anfang damit, daß ich dir Sichon und sein Land preisgebe. Fang an, sein Land zu besetzen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Und Sichon zog uns mit seinem gesamten Volke zum Streite nach Jahas entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Da gab ihn der Herr, unser Gott, uns preis. Wir schlugen ihn samt seinen Söhnen und seinem ganzen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Damals nahmen wir auch alle seine Städte und bannten jede Stadt, selbst schwächliche Männer, Weiber und Kinder. Niemanden haben wir entrinnen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Nur das Vieh und das Plündergut der von uns eroberten Städte haben wir für uns erbeutet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Von Aroër am Ufer des Arnonflusses und von der Stadt im Tale bis nach Gilead ist keine Feste uns zu steil gewesen. Alles hat der Herr, unser Gott, uns preisgegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Nur dem Ammoniterlande bist du nicht genaht, allem, was seitwärts vom Jabbokflusse liegt, samt den Städten im Gebirge, wie der Herr, unser Gott, befohlen hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '\"Wir gingen weiter und zogen nach Basan. Da zog uns Basans König Og mit seinem gesamten Volk entgegen zur Schlacht bei Edreï.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Der Herr sprach zu mir: \'Fürchte ihn nicht! Ich gebe ihn nebst seinem ganzen Volk und Land in deine Hand. Tu mit ihm, wie du getan mit dem Amoriterkönig Sichon zu Chesbon!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'So gab der Herr, unser Gott, in unsere Hand auch den Basanskönig Og mit all seiner Mannschaft. Wir schlugen ihn, daß kein Flüchtling übrigblieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Damals eroberten wir alle seine Städte. Da war keine Feste, die wir ihnen nicht genommen hätten: sechzig Städte, alles, was zum Bezirk Argob und zu Ogs Königreich in Basan gehörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'All dies waren Städte mit hohen Mauern, Toren und Riegeln umwehrt, außerdem zahlreiche offene Landstädte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Wir bannten sie, wie Chesbons König Sichon, jede Stadt, selbst schwächliche Männer, Weiber und Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Alles Vieh aber und das Plündergut aus den Städten haben wir für uns genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'So nahmen wir damals von den beiden Amoriterkönigen das Land jenseits des Jordans, vom Arnonflusse bis zum Hermongebirge -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'die Sidonier heißen den Hermon Sirjon, die Amoriter Senir -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'alle Städte der Ebene, ganz Gilead und ganz Basan bis Salcha und Edreï, die zum Reich Ogs gehörenden Städte in Basan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Denn der Basanskönig Og war der letzte Rest der Rephaiter gewesen. Sein Bett aus Basalt ist noch in der Ammoniterstadt Rabba zu sehen. Nach gewöhnlicher Elle war es neun Ellen lang und vier breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Dieses Land haben wir damals uns zu eigen gemacht. Von Aroër am Ufer des Arnonflusses habe ich es nebst dem halben Gebirge Gilead und seinen Städten den Rubeniten und Gaditen verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Dem Halbstamm Manasse aber habe ich den Rest von Gilead und ganz Basan, Ogs Königreich, verliehen. Der ganze Argobbezirk samt ganz Basan heißt Rephaiterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, Manasses Sohn, hatte den ganzen Argobbezirk bis zum Gebiet der Gesuriter und Maakatiter erobert, und man nannte Basan nach seinem Namen \"Jairs Dörfer\" bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Dem Makir habe ich Gilead verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Den Rubeniten und den Gaditen habe ich von Gilead bis zum Arnonfluß, den Fluß selbst und das Uferland bis an den Jabbokfluß, die Grenze der Ammoniter, verliehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'ferner die Steppe mit dem Jordan und seinem Uferland vom See Genesareth bis zum Meer der Steppe, dem Salzmeer, am Fuß der Abhänge des Pisga.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Damals gebot ich euch: \'Der Herr, euer Gott, gibt euch dieses Land zu eigen. Aber sturmgerüstet zieht, all ihr wehrhaften Männer, euren israelitischen Brüdern voran!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Nur eure Weiber und Kinder und euer Vieh - weiß ich doch, daß ihr viel Vieh habt - sollen in euren Städten bleiben, die ich euch gab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'bis der Herr euren Brüdern Ruhe schafft wie euch und auch sie das Land einnehmen, das ihnen der Herr, euer Gott, jenseits des Jordans gibt. Dann kehre jeder heim in seinen Besitz, den ich euch verliehen habe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Und ich habe damals Josue geboten: \'Du hast mit eigenen Augen alles gesehen, was der Herr, euer Gott, an diesen beiden Königen getan hat. Also tut der Herr mit allen Königreichen, wohin du ziehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Fürchtet sie nicht! Denn der Herr, euer Gott, streitet selbst für euch.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Ich flehte damals zum Herrn und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '\'Herr! Herr! Du hast Deinem Knechte bereits gezeigt Deine Größe und Deine starke Hand. Wo ist im Himmel und auf Erden ein Gott, der solche Werke tut und Heldentaten, wie Du?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Laß mich doch hinüberziehen, damit ich schaue das schöne Land jenseits des Jordans und das schöne Gebirge und den Libanon!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Aber der Herr zürnte mir euretwegen, und so hat er mich nicht erhört. Der Herr sprach zu mir: \'Genug! Rede nichts weiter zu mir in dieser Sache!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Steig auf des Pisga Gipfel! Hebe deine Augen gen Westen, Norden, Süden und Osten und schaue mit deinen Augen! Denn den Jordan hier wirst du nicht überschreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Bestelle Josue! Ermutige und stärke ihn! Denn er zieht vor diesem Volke voran. Und er verteilt ihnen das Land, das du schaust.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'So blieben wir im Tale, Bet Peor gegenüber.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '\"Nun höre, Israel, auf die Gesetze und Gebräuche, die ich euch befolgen lehre, auf daß ihr lebet und kommet und das Land besetzet, das der Herr, euer Gott, euch gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ihr sollt nichts zu den Geboten, die ich euch gebe, hinzutun und nichts davon streichen! Befolgt nur des Herrn, eures Gottes, Gebote, die ich euch gebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Mit eigenen Augen habt ihr gesehen, was der Herr wegen des Baal Peor getan. Denn jeden, der dem Baal Peor nachlief, hat der Herr, dein Gott, aus deiner Mitte getilgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Ihr aber, die ihr am Herrn, eurem Gotte hinget, seid alle heute noch am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Seht, Ich gewöhne euch an Gesetze und Gebräuche, wie mir der Herr, mein Gott, geboten, daß ihr danach tut in dem Lande, das einzunehmen ihr kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Haltet und tut sie! Denn das ist eure Weisheit und Klugheit in den Augen der Völker. Hören sie von all diesen Satzungen, so werden sie sprechen: \'Jedenfalls ist dieses große Volk eine weise, kluge Nation.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Ja, wo ist ein so großes Volk, dem Gott so nahe ist wie der Herr, unser Gott, sooft wir rufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Wo wäre ein so großes Volk, das solch gerechte Gesetze und Gebräuche hätte, wie diese ganze Lehre, die ich euch heute vorlege?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Nur hüte dich und nimm dich in acht, daß du nicht vergessest, was du mit eigenen Augen gesehen, und daß es dir zeitlebens nicht aus dem Herzen weiche! Tu sie vielmehr deinen Kindern und Enkeln kund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Auch den Tag, den du am Horeb vor dem Herrn, deinem Gott, gestanden, als mir der Herr befahl: \'Versammle mir das Volk! Ich lasse sie meine Worte hören, daß sie mich fürchten lernen alle Tage, die sie auf Erden leben, und daß sie auch ihre Kinder lehren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Da tratet ihr her und standet am Fuße des Berges. Der Berg aber brannte im Feuer bis ins Innere des Himmels hinein und bis in Finsternis, Gewölk und Wolkendunkel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Der Herr aber redete zu euch aus dem Feuer. Den Schall der Worte hörtet ihr, aber nur den Schall. Keine Gestalt sahet ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'So kündete er euch seinen Bund, den er euch zu halten geboten, die Zehn Worte. Er schrieb sie auf zwei Steintafeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mir aber hat der Herr damals geboten, euch Gesetze und Gebräuche zu lehren, damit ihr sie tut in dem Lande, in dessen Besitz ihr kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'So nehmt euch in acht, gilt es doch euer Leben! Denn ihr habt damals keinerlei Gestalt gesehen, als der Herr am Horeb aus dem Feuer zu euch redete,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'damit ihr nicht entartet und euch ein Bild macht, das Abbild irgendeiner Götzengestalt, die Form eines Mannes oder Weibes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'die Form irgendeines Tieres auf Erden oder eines beschwingten Vogels, der am Himmel fliegt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'die Form irgendeines Kriechtieres auf Erden, die Form irgendeines Fisches, der im Wasser unter der Erde ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Damit du nicht deine Augen gen Himmel hebest und Sonne, Mond und Sterne betrachtest, das ganze Himmelsheer, und dich nicht verleiten lässest, dich davor hinzuwerfen und ihnen zu dienen! Sie hat der Herr, dein Gott, für alle Völker unter dem ganzen Himmel geschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Euch aber hat der Herr ergriffen; dann führte er euch aus dem ägyptischen Eisenschmelzofen, damit ihr ein Volk würdet, ihm eigen, wie es heute ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Mir aber hat der Herr um euretwillen gezürnt, und so schwur er, ich dürfe nicht den Jordan überschreiten und nicht das schöne Land betreten, das der Herr, dein Gott, dir zu eigen gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Ich sterbe vielmehr in diesem Land und ziehe nicht über den Jordan. Ihr aber zieht hinüber und nehmt dies schöne Land zu eigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Hütet euch, daß ihr nicht den Bund vergesset, den der Herr, euer Gott, mit euch geschlossen! Macht euch kein Bild, kein Abbild von irgend etwas, wie es dir der Herr, dein Gott, geboten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Denn der Herr, dein Gott, ist ein verzehrendes Feuer, ein eifernder Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Wenn ihr Kinder und Enkel bekommt und wenn ihr im Land eingelebt seid, und wenn ihr entartet und Bilder macht, Abbilder von irgend etwas, und tut das, was böse ist in den Augen des Herrn, deines Gottes, um ihn zu erzürnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'so nehme ich jetzt schon Himmel und Erde zu Zeugen wider euch, daß ihr schleunigst aus dem Lande schwindet, das einzunehmen, ihr den Jordan überschreitet. Ihr bleibt dann nicht lange darin, sondern ihr werdet völlig vertilgt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Und der Herr zerstreut euch unter die Völker, und nur ein winzig Häuflein bleibt von euch unter den Nationen übrig, in die euch der Herr treiben wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Dort dient ihr Göttern, Werken von Menschenhänden, Holz und Stein, die nicht sehen, noch hören, noch essen, noch riechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Von dort ab suchst du den Herrn, deinen Gott. Und du findest ihn, wenn du ihn suchst von ganzem Herzen und ganzer Seele,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'in deiner Not, wenn dich all dies trifft in späterer Zeit. Dann kehrst du zum Herrn, deinem Gott, zurück und hörst wieder auf seine Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Denn der Herr, dein Gott, ist ein barmherziger Gott. Er läßt dich nicht los und läßt dich nicht verderben. Er vergißt nicht den Bund mit deinen Vätern, den er ihnen beschworen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Ja, frage doch die alten Zeiten, die vor dir gewesen, seit der Zeit, da Gott auf Erden Menschen geschaffen, und von einem Ende des Himmels bis zum anderen, ob je so Großes geschehen oder ob je dergleichen vernommen worden ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'ob ein Volk vernehmlich Gott aus dem Feuer reden gehört hat, wie du es gehört, und es blieb leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Oder ob je ein Gott versucht hat, zu kommen und sich ein Volk aus einem anderen herauszuholen mit Proben, Zeichen und Wundern, mit Krieg, mit starker Hand und gerecktem Arm und großen Schauern, wie der Herr, euer Gott, vor deinen Augen in Ägypten mit euch getan?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'So bist du überzeugt worden: Der Herr ist Gott, sonst keiner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Vom Himmel her hat er dich seine Stimme hören lassen, zu deiner Zucht. Und auf Erden hat er dich sein großes Feuer sehen lassen. Und aus dem Feuer hast du seine Worte vernommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Weil er deine Väter geliebt hat, erwählte er ihre Nachkommen und führte dich selbst mit seiner großen Kraft aus Ägypten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'wollte er doch Völker vor dir vertreiben, größer und stärker als du, und dich in ihr Land bringen und es dir zu eigen geben, wie es jetzt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'So erkenne heute! Nimm es dir zu Herzen! Der Herr ist Gott im Himmel droben und auf Erden unten, sonst keiner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Halte seine Gesetze und Gebräuche, die ich dir heute gebe, daß es dir wohlergehe und deinen Kindern nach dir und du lange lebest auf dem Boden, den dir der Herr, dein Gott, gibt, zu allen Zeiten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Damals schied Moses drei Städte aus in dem Land jenseits des Jordans gegen Osten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'damit ein Totschläger dahin fliehen könnte, der seinen Nächsten ohne Absicht getötet hatte und nicht aus altem Hasse. Er soll in eine dieser Städte fliehen und leben bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Beser in der Steppe auf der Hochebene für die Rubeniten, Ramot in Gilead für die Gaditen und Golan in Basan für die Manassiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Dies ist die Lehre, die Moses den Israeliten vorlegte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Dies sind die Gebote, Gesetze und Gebräuche, die Moses den Israeliten verkündet hat nach ihrer Fahrt aus Ägypten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'jenseits des Jordans im Tale gegenüber von Bet Peor, im Lande des Amoriterkönigs Sichon, der zu Chesbon saß, und den Moses mit den Israeliten bei ihrem Auszug aus Ägypten besiegt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'und dessen Land sie, wie das Land des Basanskönigs Og, erobert haben, die Länder der beiden Amoriterkönige, jenseits des Jordans gegen Osten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'von Aroër am Ufer des Arnonflusses bis zum Berge Sirjon, das ist der Hermon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'samt der ganzen Steppe auf der Ostseite des Jordans bis zum Steppenmeer am Fuße der Abhänge des Pisga.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Moses berief ganz Israel und sprach zu ihnen: \"Höre, Israel, die Gesetze und Gebräuche, die ich heute vor euren Ohren vortrage! Macht euch damit vertraut und habt acht, sie zu tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Der Herr, unser Gott, hat mit uns am Horeb einen Bund geschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nicht mit unseren Vätern hat der Herr diesen Bund geschlossen, sondern mit uns selber, mit diesen hier, die heute mit uns leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Der Herr hat mit euch auf dem Berge von Angesicht zu Angesicht aus dem Feuer geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ich selber stand damals zwischen dem Herrn und euch, des Herrn Wort euch zu künden; denn ihr habt euch vor dem Feuer gefürchtet und seid nicht auf den Berg gestiegen. Er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '\'Ich der Herr, bin dein Gott, der dich aus dem Ägypterland geführt, aus dem Sklavenhause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du sollst mir zum Trotze keine anderen Götter haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du sollst dir kein Bild machen irgendwelcher Gestalt, die am Himmel droben und unten auf Erden oder unter der Erde im Wasser ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du sollst dich nicht vor solchen niederwerfen, du sollst ihnen nicht dienen! Denn ich, der Herr, dein Gott, bin ein eifernder Gott, der die Schuld der Väter an den Kindern ahndet, an den Enkeln und Urenkeln derer, die mich hassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'aber Huld erweist dem tausendsten Gliede derer, die mich lieben und meine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du sollst nicht des Herrn, deines Gottes, Namen eitel nennen! Der Herr läßt den nicht ungestraft, der seinen Namen eitel nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Wahre den Sabbattag, daß du ihn heilig haltest, wie der Herr, dein Gott, dir befohlen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sechs Tage sollst du arbeiten, und so tu all dein Werk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Der siebte Tag aber ist ein Sabbat zu des Herrn, deines Gottes, Ehren. Du sollst kein Werk tun, weder du noch dein Sohn, noch deine Tochter und nicht dein Knecht noch deine Magd und nicht dein Rind noch dein Esel noch eines deiner Lasttiere und nicht der Fremdling, der in deinen Toren weilt! Dein Knecht und deine Magd sollen ruhen wie du!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Denk daran, daß du selbst Knecht warst im Ägypterlande, und daß der Herr, dein Gott, dich mit starker Hand und gerecktem Arm von dort weggeführt! Deshalb befiehlt der Herr, dein Gott, den Sabbat zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Ehre deinen Vater und deine Mutter, wie dir der Herr, dein Gott, geboten, damit du lange lebest und es dir wohlergehe auf dem Boden, den dir der Herr, dein Gott, gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du sollst nicht morden! Du sollst nicht ehebrechen! Du sollst nicht stehlen! Du sollst nicht als falscher Zeuge gegen deinen Nächsten aussagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Begehre nicht deines Nächsten Weib! Hab keine Gelüste nach deines Nächsten Haus und Feld, Knecht oder Magd, nicht nach seinem Rind oder Esel und nicht nach irgend etwas, was deines Nächsten ist!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Diese Worte hat der Herr mit lauter Stimme zu eurer Gesamtgemeinde geredet auf dem Berge aus dem Feuer, dem Gewölk und Dunkel heraus, nichts weiter. Dann schrieb er sie auf zwei Steintafeln und gab sie mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Als ihr aus dem Dunkel die Stimme hörtet und der Berg im Feuer brannte, tratet ihr zu mir her, alle eure Stammeshäupter und Ältesten, und spracht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, '\'Der Herr, unser Gott, zeigt uns seine Herrlichkeit und Größe. Wir hören aus dem Feuer seine Stimme. So erfahren wir heute, daß Gott mit einem Menschen redet und dieser bleibt leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Aber warum sollen wir sterben? Dies große Feuer frißt uns noch. Wenn wir noch länger des Herrn, unseres Gottes, Stimme anhören, so sterben wir noch am Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Wo ist ein sterblich Wesen, das die Stimme des lebendigen Gottes aus dem Feuer hat reden hören wie wir, und blieb leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Tritt du hin und höre alles, was der Herr, unser Gott, sprechen will! Sage uns dann alles, was der Herr, unser Gott, dir sagt! Wir hören es und tun danach.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Und der Herr hörte eure lauten Reden bei eurer Unterredung mit mir. Da sprach der Herr, unser Gott, zu mir: \'Ich habe dieses Volkes laute Reden gehört, die sie mit dir geführt haben. Sie haben recht mit allem, was sie sagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Daß doch ihr Herz so bliebe, mich allzeit zu fürchten und alle meine Gebote zu halten, auf daß es ihnen und ihren Kindern immer wohlergehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Geh! Sag ihnen: Kehrt zu euren Zelten wieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Du aber bleib hier bei mir, daß ich dir alle Gebote, Gesetze und Gebräuche künde, die du sie lehren sollst, daß sie danach tun in dem Land, das ich ihnen zu eigen gebe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Seid also bedacht zu tun, wie euch der Herr, euer Gott, befahl! Weicht nicht rechts und nicht links ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Genau den Weg geht, den der Herr, euer Gott, euch vorschreibt, auf daß ihr lebet, glücklich werdet und lange lebet in dem Land, das ihr erobert!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '\"Das ist das Gesetz mit den Satzungen und Rechten, die der Herr, euer Gott, euch zu lehren geboten, auf daß ihr sie tut in dem Lande, in das ihr zieht, es zu besetzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'auf daß du den Herrn, deinen Gott, fürchtest und alle seine Satzungen und Gebote haltest, die ich dir befehle, du, dein Sohn und dein Enkel, all deine Lebenstage, und daß du lange lebest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Höre, Israel, und wahre sie, um danach zu tun, auf daß es dir wohlergehe und ihr gar zahlreich werdet, wie der Herr, der Gott deiner Väter, dir ein Land verhieß, das von Milch und Honig fließt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Höre, Israel! Der Herr ist unser Gott, der Herr allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Du sollst den Herrn, deinen Gott, lieben mit ganzem Herzen, mit ganzer Seele und mit ganzer Kraft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Diese Worte, die ich dir heute vorlege, seien in deinem Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Schärfe sie deinen Kindern zur Lebensregel ein und sprich davon, wenn du in deinem Hause weilst und auf dem Wege bist, wenn du dich legst und wenn du dich erhebst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Binde sie als Denkzeichen auf deine Hand und trage sie als Marken zwischen deinen Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Schreibe sie auf deines Hauses Pfosten und an deine Tore!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Bringt dich der Herr, dein Gott, in das Land, das er deinen Vätern Abraham, Isaak und Jakob zugeschworen, und gibt er dir große und schöne Städte, die du nicht gebaut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'und Häuser, voll jeglichen Gutes, das du nicht angehäuft, gehauene Brunnen, die du nicht ausgehauen, Wein und Ölgärten, die du nicht gepflanzt, und du issest dich satt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'dann hüte dich, des Herrn, deines Gottes, zu vergessen, der dich aus dem Ägypterlande führte, aus dem Sklavenhaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Den Herrn, deinen Gott, sollst du fürchten! Ihm sollst du dienen und schwören bei seinem Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ihr dürft keinem anderen Gott nachgehen von den Göttern der Völker, die rings um euch sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Denn der Herr, dein Gott, ist ein eifernder Gott in deiner Mitte. Daß nicht der Herr, dein Gott, über dich zornig werde und dich tilge vom Erdboden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ihr sollt den Herrn, euren Gott, nicht mehr versuchen, wie ihr ihn zu Massa versucht habt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Haltet des Herrn, eures Gottes, Gebote, Gesetze und Gebräuche, die er dir geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Tu, was recht und gut ist in den Augen des Herrn, auf daß es dir wohlergehe und du kommest und das treffliche, vom Herrn deinen Vätern zugeschworene Land besetzest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'wenn alle deine Feinde vor dir verjagt werden, wie der Herr verheißen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Wenn dich dein Sohn künftig fragt: \'Was ist es um diese Gebote, Gesetze und Gebräuche, die der Herr, unser Gott, euch geboten?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'so sprich zu deinem Sohne: \'Wir sind des Pharao Sklaven in Ägypten gewesen. Aber der Herr führte uns mit starker Hand aus Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Der Herr tat vor unseren Augen große und schlimme Zeichen und Wunder an Ägypten, an Pharao und seinem ganzen Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Uns aber hat er von dort weggeführt, uns hierher zu bringen und uns das Land zu geben, das er unseren Vätern zugeschworen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Der Herr befahl uns, all diese Gebräuche zu tun, und den Herrn, unseren Gott, zu fürchten, uns zum Heil für alle Zeiten und zur Erhaltung unseres Lebens, wie es jetzt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Wir haben ein Verdienst beim Herrn, unserem Gott, wenn wir darüber wachen, dies ganze Gesetz zu tun, wie er uns hieß.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '\"Bringt dich der Herr, dein Gott, in das Land, in das du zu seiner Besetzung kommst, und treibt er viele Völker vor dir aus: die Chittiter, Girgasiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter, sieben Völker, zahlreicher und mächtiger als du,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'gibt der Herr, dein Gott, sie dir preis und schlägst du sie, dann sollst du sie bannen! Du sollst keinen Bund mit ihnen schließen! Du sollst keine Gnade an ihnen üben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Du sollst dich nicht mit ihnen verschwägern! Du sollst deine Tochter keinem ihrer Söhne zum Weibe geben! Du sollst keine ihrer Töchter für deinen Sohn zum Weibe nehmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Denn sie könnte deinen Sohn mir abspenstig machen, und er könnte anderen Göttern dienen. Dann aber zürnte der Herr über euch und tilgte dich schnell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Tut so mit ihnen: Ihre Altäre sollt ihr zerstören, zertrümmern ihre Steinmale, ihre heiligen Bäume fällen und ihre Gottesbilder verbrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Denn ein heilig Volk bist du dem Herrn, deinem Gott. Dich hat der Herr, dein Gott, zum eigenen Volke erkoren aus allen Völkern auf dem Erdboden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nicht weil ihr zahlreicher seid als die anderen Völker, hat euch der Herr begehrt, so daß er euch erkor; denn ihr seid das kleinste aller Völker,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'sondern weil der Herr euch liebt und den Schwur hält, den er euren Vätern geleistet hat. So hat euch der Herr mit starker Hand hinweggeführt und so befreite er dich aus dem Sklavenhaus, aus der Hand des Ägypterkönigs Pharao.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'So wisse, daß der Herr, dein Gott, der Gott ist, der unvergängliche Gott. Er bewahrt den Bund und die Huld bis ins tausendste Geschlecht denen, die ihn lieben und seine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Aber seinen Hassern vergilt er öffentlich durch Vernichtung. Er gibt seinem Hasser keinen Aufschub, sondern vergilt ihm öffentlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Darum befolge das Gesetz, die Gebote und Gebräuche, die ich dir heute zu tun gebiete!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Zum Lohne dafür, daß ihr diesen Vorschriften gehorchet, sie beobachtet und befolget, wahrt dir der Herr, dein Gott, den Bund und die Huld, die er deinen Vätern zugeschworen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Er liebt dich, segnet dich und mehrt dich. Er segnet deine Leibesfrucht und deine Feldfrucht, dein Korn, deinen Wein und dein Öl, den Wurf deiner Rinder und die Zucht deiner Schafe in dem Land, das er deinen Vätern zugeschworen, dir zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Gesegnet bist du dann vor allen Völkern. Bei dir ist nichts Unfruchtbares weder beim Manne noch beim Weibe noch beim Vieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Der Herr hält dir jede Krankheit fern und legt dir keine der bösen ägyptischen Seuchen auf, die du kennst. Er belegt damit alle deine Hasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Vertilge die Völker alle, die der Herr, dein Gott, dir preisgibt! Du sollst nicht auf sie schauen! Du sollst nicht ihren Göttern dienen! Denn das wäre dir ein Fallstrick.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Denkst du aber: \'Diese Völker sind größer als ich, wie könnte ich sie besiegen?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'so sollst du dich nicht vor ihnen fürchten! Du sollst bedenken, was der Herr, dein Gott, dem Pharao und ganz Ägypten getan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'die großen Proben, die du mit eigenen Augen gesehen, die Zeichen und Wunder, die starke Hand und den gereckten Arm, womit dich der Herr, dein Gott, befreit hat! Also wird der Herr, dein Gott, mit all den Völkern tun, vor denen du dich fürchtest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Ja, selbst Hornissen sendet der Herr, dein Gott, wider sie, bis vernichtet sind die Übriggebliebenen, die sich vor dir versteckten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Du sollst dich nicht vor ihnen entsetzen! Denn der Herr, dein Gott, ist in deiner Mitte, ein Gott, groß und furchtbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Der Herr, dein Gott, vertreibt diese Völker nur allmählich vor dir. Du darfst sie aber nicht zu rasch vertilgen, sonst wüchse über dich das Wild des Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Der Herr, dein Gott, gibt sie dir preis und setzt sie in gewaltigen Schrecken, bis sie vernichtet sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Er gibt auch ihre Könige in deine Hand, und du tilgst ihren Namen unterm Himmel. Niemand hält vor dir stand, bis du sie vertilgt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Ihre Götterbilder sollt ihr verbrennen. Nach dem Silber und Gold daran soll dich nicht gelüsten; nimm es dir nicht! Sonst wirst du dadurch umgarnt. Denn das ist dem Herrn, deinem Gott, ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Du sollst keinen Greuel in dein Haus bringen, daß du nicht gleich ihm gebannt würdest! Du sollst es verabscheuen und Grauen davor haben! Denn es ist gebannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '\"Ihr sollt das ganze Gesetz, das ich dir heute gebiete, mit Bedacht erfüllen, auf daß ihr leben bleibet, euch mehret und das Land besetzet, das der Herr euren Vätern zugeschworen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Gedenke des ganzen Weges, den dich der Herr, dein Gott, seit vierzig Jahren in der Steppe geführt hat, dich zu demütigen und zu prüfen, um zu erfahren, was in deinem Herzen ist, ob du seine Gebote halten wirst oder nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Er beugte dich und ließ dich hungern; aber dann speiste er dich mit Manna, das dir und deinen Vätern unbekannt gewesen, um dich zu lehren, daß der Mensch nicht vom Brot allein lebe, sondern daß der Mensch von allem lebt, was durch des Herrn Mund entsteht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Dein Kleid ist nicht an dir zerfallen, und dein Fuß nicht geschwollen, diese vierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'So erkenne in deinem Herzen, daß dich der Herr, dein Gott, so erzieht, wie jemand seinen Sohn erzieht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Halte die Gebote des Herrn, deines Gottes, auf seinen Wegen wandelnd und ihn fürchtend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Denn der Herr, dein Gott, bringt dich in ein treffliches Land, in ein Land mit Wasserbächen, Quellen und Seen, die im Tal und auf dem Berg entspringen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'in ein Land mit Weizen und Gerste, Weinreben, Feigen und Granaten, in ein Land mit Oliven und Honig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'in ein Land, wo du nicht kümmerlich Brot essen mußt, sondern keinen Mangel hast, in ein Land, dessen Steine Eisen sind und aus dessen Bergen du Erz gräbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Du wirst essen und satt werden. Preise dann den Herrn, deinen Gott, für das treffliche Land, das er dir gegeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Hüte dich, daß du nicht des Herrn, deines Gottes, vergäßest und seine Gesetze, Gebote und Gebräuche nicht mehr hieltest, die ich dir heute gebiete!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Issest du dich satt und baust schöne Wohnhäuser,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'mehren sich deine Rinder und Schafe, wird dir Silber und Gold in Menge zu eigen, mehrt sich all das Deine,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'dann werde nicht dein Herz hochmütig! Vergiß nicht des Herrn, deines Gottes, der dich aus Ägypterlande geführt, aus dem Sklavenhause,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'der dich geleitet durch die große schreckliche Wüste, wo Schlangen, Nattern und Skorpione sind und Dürre, wo kein Wasser ist; der dir Wasser quellen ließ aus Kieselfelsen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'der dich in der Wüste mit Manna speiste, das deine Väter nicht gekannt, der dich beugte und prüfte, damit er dir Gutes tun könnte in deiner Zukunft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Denke nicht: \'Meine Kraft und die Stärke meiner Hand hat mir diesen Reichtum verschafft!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Bedenke, daß der Herr, dein Gott, dir Kraft gibt, Reichtum zu schaffen, damit er seinen Bund bekräftige, den er deinen Vätern zugeschworen, wie es heute ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Vergissest du aber des Herrn, deines Gottes, folgst du anderen Göttern, dienst ihnen und wirfst dich vor ihnen hin, so erkläre ich euch zum voraus aufs feierlichste, daß ihr umkommen werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Wie die Völker, die der Herr vor euch vertilgt, so werdet ihr umkommen, zur Strafe dafür, daß ihr nicht auf die Stimme des Herrn, eures Gottes, hört.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '\"Höre, Israel! Du ziehst jetzt über den Jordan, Herr zu werden über Völker, größer und stärker als du, über Städte, groß und himmelhoch umwehrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'über ein Volk, groß und hochgewachsen, die Enakiter, die du selbst kennst und von denen du selbst sagen hörtest: \'Wer hält den Enakitern stand?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So wisse zum voraus: Der Herr, dein Gott, zieht dir voran als ein verzehrendes Feuer. Er vertilgt sie und wirft sie vor dich hin. Du wirst sie leicht vertreiben und vernichten, wie dir der Herr verhieß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Denke nicht, wenn sie der Herr, dein Gott, vor dir verjagt: \'Um meines Verdienstes willen hat mich der Herr in den Besitz dieses Landes gebracht!\' Der Herr vertreibt vor dir diese Völker doch nur um ihres Frevels willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nicht wegen des Verdienstes und deines lauteren Herzens kommst du in den Besitz dieses Landes, sondern der Herr, dein Gott, vertreibt vor dir diese Völker wegen ihrer Frevelhaftigkeit und zur Erfüllung des Schwures, den der Herr deinen Vätern, Abraham, Isaak und Jakob, geleistet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Bleib dir bewußt, daß dir der Herr, dein Gott, dieses schöne Land nicht wegen deines Verdienstes zu eigen gibt! Denn du bist ein halsstarrig Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Denk daran! Vergiß nicht, wie du den Herrn, deinen Gott, in der Wüste erzürnt hast! Vom Tag an, an dem du aus Ägypterland gezogen, bis zu eurer Ankunft an diesem Ort seid ihr widerspenstig gegen den Herrn gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Besonders am Horeb habt ihr den Herrn erzürnt, und der Herr ergrimmte über euch und wollte euch vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Ich stieg auf den Berg, die Steintafeln zu empfangen, die Tafeln des Bundes, den der Herr mit euch geschlossen, und ich blieb vierzig Tage und Nächte auf dem Berg. Brot habe ich nicht gegessen und Wasser nicht getrunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Der Herr gab mir die beiden Steintafeln, vom Finger Gottes beschrieben. Darauf waren genau die Worte, die der Herr am Versammlungstag auf dem Berg aus dem Feuer zu euch redete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Nach vierzig Tagen und Nächten hat mir der Herr die beiden Steintafeln gegeben, die Tafeln des Bundes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Da sprach der Herr zu mir: \'Auf! Rasch von hier hinab! Schlimm handelt dein Volk, das du aus Ägypten führtest. Sie sind schnell vom Weg gewichen, den ich ihnen gebot. Sie haben sich ein Gußbild gemacht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Und der Herr sprach zu mir: \'Ich habe dies Volk beobachtet; es ist ein hartnäckig Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laß mich in Ruhe, daß ich sie vertilge und ihren Namen unter dem Himmel lösche! Dich will ich zum Ahnherrn eines Volkes machen, stärker und größer als dieses.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Ich wandte mich und stieg vom Berge, und der Berg brannte noch im Feuer. Die beiden Gesetzestafeln hielt ich in meinen Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Da sah ich hin. Wahrhaftig! Ihr hattet euch an dem Herrn, eurem Gott, versündigt. Ihr hattet euch ein gegossenes Kalb gemacht. So seid ihr schnell von dem Wege gewichen, den der Herr euch vorgeschrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Da faßte ich die beiden Tafeln, warf sie weg und zerschlug sie vor euren Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Dann warf ich mich nieder vor dem Herrn, wie das erstemal, vierzig Tage und Nächte. Ich habe kein Brot gegessen und kein Wasser getrunken wegen all eurer Sünde, die ihr getan, indem ihr etwas dem Herrn Mißfälliges tatet, daß es ihn kränken mußte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Denn mir ist bange geworden vor dem Zorn und Grimm, womit der Herr über euch gezürnt, so daß er daran war, euch zu vertilgen. Und der Herr erhörte mich auch diesmal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Auch über Aaron hatte der Herr so sehr gezürnt, daß er ihn vertilgen wollte. Ich flehte damals auch für Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Euer Sündenwerk aber, das ihr gemacht, das Kalb, habe ich genommen; dann verbrannte ich es, zerstieß und zerrieb es zu feinem Staub, und diesen Staub warf ich in den Bach, der vom Berg herabfließt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Auch zu Tabera, Massa und an den Gelüstegräbern habt ihr den Herrn erzürnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Auch als euch der Herr von Kades Barnea aussandte und sprach: \'Zieht hinauf und erobert das Land, das ich euch gebe!\', waret ihr widerspenstig gegen des Herrn, eures Gottes, Befehl; ihr habt ihm nicht getraut und nicht auf seine Stimme gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Widerspenstig seid ihr gegen den Herrn gewesen, seitdem ich euch kenne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Ich lag vor dem Herrn die vierzig Tage und Nächte, als ich bestürzt war, weil der Herr euch vernichten wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Ich betete zum Herrn: \'Herr! Herr! Vertilge nicht dein ureigen Volk, das du erlöst durch deine große Macht und mit starkem Arm aus Ägypten geführt hast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Gedenke deiner Knechte Abraham, Isaak und Jakob! Kehre dich nicht an des Volkes Halsstarrigkeit, an seine Bosheit und Sünde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Damit man nicht in dem Land, aus dem du uns geführt, sage: \"Aus Unvermögen des Herrn, sie in das zugesagte Land zu bringen, und aus Abneigung gegen sie führte er sie hinweg, sie in der Wüste sterben zu lassen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Und doch sind sie dein ureigen Volk, das du mit deiner großen Kraft und deinem gereckten Arm hast herausgeführt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, '\"Damals sprach der Herr zu mir: \'Haue dir zwei Steintafeln aus wie die ersten, und steige zu mir auf den Berg! Auch mach dir einen Schrein von Holz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Ich will auf die Tafeln die Worte schreiben, die auf den ersten Tafeln gestanden, die du zerbrochen hast. Lege sie in die Lade!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Da machte ich eine Lade aus Akazienholz und hieb zwei Steintafeln aus, wie die ersten. Dann stieg ich auf den Berg, die beiden Tafeln in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Da schrieb er in der gleichen Schrift wie zuvor auf die Tafeln die Zehn Worte, die er am Versammlungstag auf dem Berg aus dem Feuer zu euch geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Dann gab sie mir der Herr. Ich wandte mich und stieg vom Berg herab und legte die Tafeln in die Lade, die ich gemacht hatte. Sie blieben darin, wie mir der Herr befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Die Israeliten waren nun von den Brunnen der Söhne Jaakan nach Mosera gezogen; dort starb Aaron und ward dort begraben. An seiner Statt ward sein Sohn Eleazar Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Von da zogen sie nach Gudgoda, von Gudgoda nach Jotba, einer Gegend mit Wasserbächen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Damals schied der Herr den Stamm Levi aus, die Bundeslade des Herrn zu tragen, vor dem Herrn zu stehen, ihm zu amten und mit seinem Namen zu segnen, bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Darum ward Levi kein Besitzteil unter seinen Brüdern. Der Herr ist sein Erbgut, wie der Herr, dein Gott, ihm verheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ich aber bin wie zuvor vierzig Tage und Nächte auf dem Berge geblieben. Und der Herr erhörte mich auch diesmal. Der Herr hatte dich nicht vernichten wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Und der Herr sprach zu mir: \'Auf! Geh vor dem Volke her, daß sie das Land einnehmen, das ich ihren Vätern zugeschworen habe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nun, Israel! Weshalb fordert der Herr, dein Gott, von dir, daß du den Herrn, deinen Gott, fürchtest und immerdar auf seinen Wegen wandelst, daß du ihn liebst und dem Herrn, deinem Gott, von ganzem Herzen und aus ganzer Seele dienst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'daß du des Herrn Gesetze und Gebote befolgst, die ich dir heute gebe? Doch nur zu deinem Besten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Des Herrn, deines Gottes, sind die Himmel und die Himmel der Himmel und die Erde und alles, was darauf ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Aber nur zu deinen Vätern allein hat sich der Herr in Liebe geneigt und euch, ihre Nachkommen, aus allen Völkern erkoren, wie es jetzt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'So beschneidet die Vorhaut eures Herzens und seid nicht ferner halsstarrig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Denn der Herr, euer Gott, ist der Götter Gott und der Herr der Herren, der große, mächtige und furchtbare Gott, der kein Ansehen kennt und keine Bestechung nimmt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'der Recht den Waisen und Witwen schafft und den Fremdling liebt und ihm Brot und Gewandung spendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Liebet also den Fremdling! Denn ihr seid Fremdlinge im Ägypterland gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Den Herrn, deinen Gott, sollst du fürchten! Ihm sollst du dienen! An ihm sollst du hängen und mit seinem Namen schwören');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Er ist dein Ruhm. Er ist dein Gott, der an dir jenes Große und Furchtbare getan, das du mit eigenen Augen gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'In der Zahl von siebzig Seelen sind deine Väter nach Ägypten gezogen, und jetzt hat dich der Herr, dein Gott, an Menge gleich gemacht den Sternen des Himmels.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '\"So liebe den Herrn, deinen Gott, und warte seines Amtes, seiner Gesetze, Gebote und Gebräuche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Beachtet, daß dies jetzt nicht euren Kindern gilt! Sie haben die Zucht des Herrn, eures Gottes, nicht erlebt und nicht erfahren seine Größe, seine starke Hand und seinen ausgereckten Arm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'seine Zeichen und Taten, die er in Ägypten an Ägyptens König Pharao und seinem ganzen Land getan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'und was er getan an Ägyptens Heer, seinen Rossen und Wagen. Über sie hat der Herr des Schilfmeeres Wasser fluten lassen, als sie euch nachjagten; so vertilgte sie der Herr bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Und was er an euch in der Wüste getan bis zu eurer Ankunft an diesem Ort,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'und was er getan an Datan und Abiram, den Söhnen des Rubensohnes Eliab, wie die Erde ihren Schlund aufgetan und sie dann verschlang inmitten von ganz Israel samt ihren Behausungen und Zelten und ihrem ganzen Gefolge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Ihr dagegen sahet mit eigenen Augen all die Großtaten, die der Herr getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'So achtet aller Gebote, die ich euch heute gebiete, damit ihr stark seid und das Land betretet und es einnehmt, das zu besetzen ihr hinüberschreitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'und damit ihr lange lebet in dem Lande, das der Herr euren Vätern und ihrem Stamme zugeschworen, in dem Lande, das von Milch und Honig fließt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Denn das Land, in das du ziehst, es zu besetzen, gleicht nicht dem Lande Ägypten, aus dem du gezogen, das du mit deiner Saat besätest und das du, wie einen Gemüsegarten, mit deinem Fuß bewässert hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Das Land, in das ihr hinüberzieht, es zu besetzen, ist ein Land mit Bergen und Tälern; vom Regen des Himmels trinkt es Wasser,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'ein Land, für das der Herr, dein Gott, sorgt. Beständig ruhen des Herrn, deines Gottes, Augen auf ihm, vom Anfang bis zum Schluß des Jahres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Gehorchet ihr treulich meinen Geboten, die ich euch heute gebiete, den Herrn, euren Gott, zu lieben und ihm von ganzem Herzen und aus ganzer Seele zu dienen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'dann gebe ich eurem Lande zur rechten Zeit Regen, Frühregen und Spätregen, daß du dein Korn, deinen Wein und dein Öl einheimsest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Ich gebe auf deiner Flur Gras für dein Vieh, daß du essest und satt werdest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Hütet euch, daß euer Herz nicht betört werde und ihr abfallet, anderen Göttern dienet und euch davor hinwerfet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Sonst entbrennt des Herrn Zorn gegen euch, und er sperrt den Himmel. Kein Regen fällt, und die Scholle gibt ihre Ernte nicht mehr. Dann schwindet ihr rasch aus dem schönen Lande, das der Herr euch gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Nehmt euch diese meine Worte zu Herzen und zu Gemüt! Bindet sie als Denkzeichen an eure Hand! Tragt sie als Marken zwischen euren Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Lehrt sie eure Kinder, indem ihr davon redet, wenn du in deinem Hause weilst oder auf Reisen gehst, wenn du dich legst und wenn du aufstehst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Schreibe sie auf die Pfosten deines Hauses und an deine Tore,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'auf daß sich eure und eurer Kinder Tage mehren in dem vom Herrn euren Vätern zugeschworenen Land, wie die Tage des Himmels über der Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Achtet ernstlich darauf, all diese Gebote, die ich gebiete zu tun, den Herrn, euren Gott, zu lieben, auf seinen Wegen zu wandeln und ihm anzuhängen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Dann rottet der Herr all diese Völker vor euch aus, und ihr besiegt Völker, die größer und stärker als ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Jeder Ort, den eure Fußsohle betritt, wird euer sein. Von der Wüste bis zum Libanon, vom Strome, dem Euphratstrom, bis ans Westmeer, das wird euer Gebiet sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Niemand besteht vor euch. Furcht und Schrecken legt vor euch der Herr, euer Gott, über das ganze Land, das ihr nach seiner Verheißung betretet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Seht! Ich lege euch heute Segen und Fluch vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Den Segen, falls ihr gehorchet des Herrn, eures Gottes, Geboten, die ich euch heute gebiete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Den Fluch, wenn ihr nicht gehorcht den Geboten des Herrn, eures Gottes, wenn ihr abweicht von dem Weg, den ich euch heute gebiete, und anderen Göttern nachlauft, die ihr nicht kanntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Bringt dich der Herr, dein Gott, in das Land, in das du ziehst, es zu besetzen, so erteile den Segen auf dem Berge Garizim und den Fluch auf dem Berge Ebal!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Liegen sie nicht jenseits des Jordans, westlich der Straße des Sonnenuntergangs, im Land der Kanaaniter, in der Steppe gegenüber Gilgal bei den Maulbeerbäumen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Denn ihr überschreitet den Jordan, um vorzudringen und das Land zu besetzen, das euch der Herr, euer Gott, gibt. Habt ihr es besetzt und besiedelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'dann achtet, all die Gesetze und Gebräuche zu halten, die ich euch heute vorlege!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '\"Dies sind die Gebote und Gebräuche. Achtet darauf, sie zu tun in dem Lande, das dir der Herr, deiner Väter Gott, zu eigen gibt, solange ihr im Lande lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vernichten sollt ihr all die Stätten, wo die von euch besiegten Völker ihren Göttern gedient, auf den hohen Bergen und den Hügeln und unter jedem immergrünen Baume!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Stürzt ihre Altäre! Zertrümmert ihre Steinmale! Verbrennen sollt ihr ihre heiligen Bäume! Fällen sollt ihr ihre Götterbilder! Tilgen sollt ihr ihren Namen von jenen Stätten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Nicht also sollt ihr dem Herrn, eurem Gott, tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Besuchen sollt ihr die Stätte, die der Herr, euer Gott, aus irgendeinem eurer Stämme aussucht, seinen Namen dort einzusetzen: Kommt dorthin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Dorthin bringt eure Brand- und Schlachtopfer, eure Zehnten und die Weihegabe eures Feldes, eure Gelübde, eure freiwilligen Gaben und die Erstlingswürfe eurer Rinder und Schafe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Dort esset vor dem Herrn, eurem Gott, und tut euch gütlich samt euren Familien an allem Erwerb eurer Hände, mit dem dich der Herr, dein Gott, gesegnet hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ihr sollt nicht so tun, wie wir jetzt hier tun! Jeder nämlich tut nach seinem Gutdünken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Denn ihr seid noch nicht zur Ruhe gelangt und nicht zu dem Besitz, den dir der Herr, dein Gott, gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Habt ihr aber den Jordan überschritten und wohnt in dem Lande, das euch der Herr, euer Gott, zu eigen gibt, und schafft er euch vor all euren Feinden ringsum Ruhe, und wohnt ihr sicher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'dann sollt ihr an den Ort, den der Herr, euer Gott, erwählt, seinen Namen dort wohnen zu lassen, alles bringen, was ich euch gebiete; eure Brand- und Schlachtopfer, eure Zehnten, die Weihegaben eures Feldes und alle eure erlesenen Gelübdeopfer, die ihr dem Herrn gelobet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Seid fröhlich vor dem Herrn, eurem Gott, ihr, eure Söhne, Töchter, Knechte und Mägde samt dem Leviten, der in euren Ortschaften wohnt, weil er kein Erbteil hat wie ihr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Hüte dich, deine Brandopfer an beliebigem Ort darzubringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Nur an dem Ort, den der Herr in irgendeinem deiner Stämme wählt, dort darfst du deine Brandopfer darbringen und dort all das tun, was ich dich heiße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Aber nach Herzenslust darfst du in all deinen Ortschaften schlachten. Iß Fleisch nach des Herrn, deines Gottes, Segen, den er dir gibt! Der Unreine wie der Reine können es essen, wie den Hirsch und das Reh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Nur das Blut darfst du nicht genießen. Du sollst es auf die Erde gießen wie Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nicht darfst du in deinen Toren den Zehnten deines Korns, Weins und Öls verzehren, noch deiner Rinder oder Schafe erste Würfe, noch eines deiner versprochenen Gelübde, noch deine freiwilligen Gaben, noch die Weihegabe deines Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Nur vor dem Herrn, deinem Gott, kannst du es verzehren an dem Ort, den der Herr, dein Gott, erwählt, du, dein Sohn, deine Tochter, dein Knecht und deine Magd samt dem Leviten, der in deinen Toren ist. Sei fröhlich mit allem Erwerb deiner Hand vor dem Herrn, deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Hüte dich, daß du den Leviten nicht verlässest, alle deine Tage in deinem Lande!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Erweitert der Herr, dein Gott, dein Gebiet, wie er dir verheilen, und du sprichst: \'Ich möchte Fleisch essen\', weil dich nach Fleischgenuß gelüstet, so magst du Fleisch nach Herzenslust essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ist dir der Ort zu entlegen, den der Herr, dein Gott, erwählt, seinen Namen dort einzusetzen, so schlachte, wie ich dir geboten, von deinen Rindern und Schafen, die dir der Herr gibt, und iß in deinen Toren nach Herzenslust!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Nur sollst du es essen, wie Hirsch und Reh gegessen werden! Der Unreine mag so gut wie der Reine davon essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Nur sei stark, daß du nicht das Blut genießest! Denn das Blut ist die Seele, und du darfst nicht mit dem Fleisch die Seele verzehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Du sollst es nicht genießen, sondern es auf die Erde gießen wie Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Du sollst es nicht genießen, auf daß es dir und deinen Kindern wohlergehe, wenn du tust, was recht ist in des Herrn Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Nur deine heiligen Gaben und deine Gelübde darfst du nehmen; dann komm zu dem Ort, den der Herr erwählen wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Bereite auf dem Altar des Herrn, deines Gottes, deine Brandopfer, das Fleisch und das Blut! Das Blut deiner Schlachtopfer aber werde an den Altar des Herrn, deines Gottes, gegossen! Das Fleisch magst du essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Beobachte aufmerksam all diese Gebote, die ich dir gebiete, auf daß es dir und deinen Kindern ewig wohlergehe, wenn du tust, was gut und recht ist in des Herrn, deines Gottes, Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Vertilgt der Herr, dein Gott, vor dir die Völker, die zu besiegen du dorthin ziehst, und hast du sie besiegt und dich in ihrem Lande angesiedelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'so hüte dich und laß dich nicht von ihnen umgarnen, nachdem sie von dir vertilgt sind! Kümmere dich nicht um ihre Götter und frage nicht: \'Wie dienen diese Völker ihren Göttern? Also will auch ich tun.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Du sollst nicht so tun mit dem Herrn, deinem Gott! Denn alles, was dem Herrn ein Greuel ist und was er haßt, tun sie ihren Göttern, verbrennen sie doch ihren Göttern sogar ihre Söhne und Töchter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '\"Alles, was ich gebiete, sollt ihr achten, es zu tun! Du sollst nichts hinzufügen und nichts davon abstreichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Tritt bei dir ein Prophet auf oder einer, der Träume hat, und bietet dir ein Zeichen oder Wunder an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'und das Zeichen oder Wunder trifft ein, das er dir vorausgesagt, und er spricht: \'Wir wollen anderen Göttern folgen, die du nicht kennst, und ihnen dienen\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'so sollst du nicht auf die Worte jenes Propheten oder Träumers hören! Denn der Herr, euer Gott, versucht euch, um zu erkennen, ob ihr den Herrn, euren Gott, liebt von ganzem Herzen und aus ganzer Seele!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Dem Herrn, eurem Gott, sollt ihr folgen! Ihn sollt ihr fürchten! Seine Gebote sollt ihr halten! Auf seine Stimme sollt ihr hören! Ihm sollt ihr dienen und ihm anhangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jener Prophet oder Träumer soll des Todes sein! Denn geraten hat er zum Abfall vom Herrn, eurem Gott, der euch aus Ägypterland geführt und dich aus dem Sklavenhaus befreit. Er wollte dich vom Weg lenken, auf dem der Herr, dein Gott, dir zu wandeln geboten. So tilge den Bösen aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Will dein Bruder, deiner Mutter Sohn, dich heimlich bereden oder dein Sohn oder deine Tochter oder dein liebes Weib oder dein Freund, der dir ist wie dein Leben, mit den Worten: \'Laßt uns gehen und anderen Göttern dienen!\', die dir und deinen Vätern unbekannt sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'von den Göttern der Völker rings um euch her, den dir nahen oder fernen, von einem Ende der Erde bis zum anderen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'so sollst du ihm nicht willfahren noch ihm Gehör geben! Du sollst keinen Blick des Mitleids für ihn haben, noch seiner schonen, noch seine Schuld verheimlichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Nein! Du sollst ihn umbringen! Deine Hand soll zuerst gegen ihn sein, ihn zu töten, danach die Hand des ganzen Volkes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Steinige ihn zu Tode! Denn er hat dich absprengen wollen vom Herrn, deinem Gott, der dich aus Ägypterland geführt, aus dem Sklavenhaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Ganz Israel soll es hören und sich fürchten, daß niemand mehr solch Schlimmes tue in deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Hörst du in einer deiner Städte, die dir der Herr, dein Gott, zur Siedlung gibt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Nichtswürdige Leute sind in deiner Mitte aufgekommen und haben die Insassen ihrer Stadt verführt mit den Worten: \'Laßt uns gehen und anderen Göttern dienen!\', die ihr nicht kennt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'dann untersuche, forsche und frage genau! Und ist es wahr, ist die Sache richtig, ist in deiner Mitte solcher Greuel verübt worden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'dann sollst du die Insassen jener Stadt mit des Schwertes Schärfe töten! Banne sie und alles darin und ihr Vieh mit des Schwertes Schärfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'All ihren Plunder sollst du auf ihren Markt tragen! Verbrenne die Stadt samt all ihrem Plunder gänzlich, wegen des Herrn, deines Gottes! Sie bleibe ewig ein Schutthügel und soll nimmer aufgebaut werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Nichts von dem Banngut soll an deiner Hand kleben, auf daß der Herr von seinem grimmen Zorn lasse, dir Erbarmen spende und dich erbarmend mehre, wie er deinen Vätern zugeschworen, falls du auf des Herrn, deines Gottes, Stimme hörst, alle seine Gebote, die ich dir heute gebiete, hältst und tust, was recht ist in den Augen des Herrn, deines Gottes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '\"Kinder seid ihr dem Herrn, eurem Gott. Ihr sollt euch wegen eines Toten keine Einschnitte machen und euch keine Glatze scheren zwischen den Augen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Denn du bist dem Herrn, deinem Gott, ein heiliges Volk. Dich erkor der Herr aus allen Völkern auf Erden zu seinem Eigenvolke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du sollst nichts Abscheuliches genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dies sind die Tiere, die ihr essen dürft: Rind, Schaf, Ziege,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Hirsch, Gazelle, Damhirsch, Steinbock, Antilope, Büffel und Rehbock.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Alle Vierfüßler, die gespaltene Klauen haben, und zwar beide Klauen ganz durchgespalten, und die zugleich unter den Vierfüßlern wiederkäuen, dürft ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Dagegen dürft ihr von den Wiederkäuern mit ganz durchgespaltenen Klauen folgende nicht essen: das Kamel, den Hasen und den Klippdachs; denn sie sind zwar Wiederkäuer, haben aber keine durchgespaltenen Klauen. Sie seien euch unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Ferner das Schwein. Es hat zwar gespaltene Klauen und sogar ganz durchgespaltene Klauen, ist aber kein Wiederkäuer. Unrein sei es euch! Ihr dürft ihr Fleisch nicht essen und ihr Aas nicht berühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Von allen im Wasser lebenden Tieren dürft ihr folgende essen: Ihr dürft essen alles, was Flossen und Schuppen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Dagegen dürft ihr keines von denen essen, die weder Flossen noch Schuppen besitzen. Unrein seien sie euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reinen Vögel dürft ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Ihr dürft aber nicht von folgenden essen: von dem Adler, dem Bartgeier, dem Geier,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'von der Weihe und dem Geschlechte der Falken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'dem ganzen Rabengeschlechte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'von dem Strauß, der Schwalbe, der Möve und dem Habichtgeschlechte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'von dem Käuzchen, dem Uhu, der Eule,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'von dem Pelikan, dem Erdgeier, dem Sturzpelikan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'von dem Storch, dem Regenpfeifergeschlechte, dem Wiedehopf, der Fledermaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Auch alles geflügelte Gewimmel sei euch unrein! Es darf nicht gegessen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Alles reine Geflügel dürft ihr essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'ihr dürft aber keinerlei Aas genießen. Dem Fremden in deiner Siedlung magst du es zu essen geben oder an einen Ausländer verkaufen. Denn du bist ein dem Herrn, deinem Gott, geheiligtes Volk. Du sollst nicht ein Böckchen in seiner Mutter Milch kochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Verzehnten sollst du Jahr für Jahr gewissenhaft deinen ganzen Ernteertrag, den das Feld hervorbringt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Verzehre vor dem Herrn, deinem Gott, an der Stätte, die er auserwählt, um seinen Namen dort einwohnen zu lassen, den Zehnten deines Getreides, Weins und Öls und die Erstlingswürfe deiner Rinder und Schafe, auf daß du lernst, allzeit den Herrn, deinen Gott, zu fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Ist dir aber der Weg zu weit, daß du es nicht tragen kannst, weil die vom Herrn, deinem Gott, zur Einsetzung seines Namens erwählte Stätte zu weit von dir entfernt ist, und hat dich der Herr, dein Gott, gesegnet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'dann mach es zu Geld und nimm das Geld mit! Zieh nach der vom Herrn, deinem Gott, erwählten Stätte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Kaufe für das Geld das, was du begehrst, Rinder und Schafe, Wein und Bier, alles, wozu dich dein Herz auffordert! Und genieße dort vor dem Herrn, deinem Gott, und sei fröhlich mit deinem Hause!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Den Leviten in deiner Siedlung solltest du nicht verlassen! Denn er hat bei dir kein Erbteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Jedes dritte Jahr sollst du den gesamten Zehnten aus deinem Ertrag ausscheiden! Dann leg ihn in deiner Siedlung nieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Dann kommen die Leviten, die weder Teil noch Erbe bei dir haben, die Fremdlinge, Waisen und Witwen in deine Siedlung und essen sich satt. Und dann segnet dich der Herr, dein Gott, in all deiner Händearbeit, die du tust.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '\"In jedem siebten Jahre sollst du Erlaß üben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Mit dem Erlaß ist es so: Kein Gläubiger darf ein Darlehen eintreiben, das er seinem Nächsten geliehen hat. Er soll es nicht eintreiben bei seinem Nächsten und Bruder, wenn man einen Erlaß von seiten des Herrn ausruft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Beim Ausländer magst du es eintreiben. Aber was du bei deinem Bruder hast, sollst du nicht eintreiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Wohl sollte bei dir kein Armer sein, da der Herr dich reichlich segnet in dem Lande, das dir der Herr, dein Gott, zu eignem Besitze gibt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'falls du nur der Stimme des Herrn, deines Gottes, gehorchest und darauf achtest, all diese Gebote zu tun, die ich dir heute gebiete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Denn der Herr, dein Gott, segnet dich, wie er dir verheißen, daß du vielen Völkern leihen kannst, selbst aber nichts entlehnen mußt, und daß du über viele Völker herrschest, über dich aber keines herrscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Ist aber ein Armer bei dir, so sollst du nicht hartherzig sein gegen deinen Bruder in irgendeinem deiner Tore in deinem Lande, das der Herr, dein Gott, dir gibt! Verschließen sollst du nicht deine Hand vor deinem armen Bruder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Öffnen sollst du ihm deine Hand und ihm genug leihen für seinen Mangel, was ihm gebricht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Hüte dich, daß in deinem Herzen nicht der nichtsnutzige Gedanke entstehe: \'Das siebte Jahr, das Erlaßjahr, naht\', und daß dein Auge mißgünstig sei auf deinen armen Bruder und du ihm nichts gebest! Denn sonst schreit er über dich zum Herrn, und dann ruht Sünde auf dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Geben sollst du ihm und nicht verdrießlich sein, wenn du ihm gibst! Denn um dessentwillen segnet dich der Herr, dein Gott, bei all deinem Tun und allem deinem Unternehmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Weil es nie in deinem Lande an Armen fehlt, darum gebiete ich dir also: Öffnen sollst du deine Hand deinem Bruder, dem Dürftigen und Armen in deinem Lande!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Verkauft sich dir einer deiner Brüder, Hebräer oder Hebräerin, diene er dir sechs Jahre! Im siebten Jahre sollst du ihn freilassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Und läßt du ihn frei, dann darfst du ihn nicht leer ziehen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Geben sollst du ihm gehörig von deinem Obst, deiner Tenne und deiner Kelter, womit dich der Herr, dein Gott, gesegnet hat! Davon sollst du ihm geben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Gedenke, daß du Sklave gewesen im Ägypterlande und daß dich der Herr, dein Gott, befreit hat! Darum gebiete ich dir heute solches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Sagt er aber zu dir: \'Ich gehe nicht von dir\', da er dich und dein Haus liebt, weil ihm bei dir wohl ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'dann nimm den Pfriemen und durchbohre ihm sein Ohr an der Tür! So wird er für immer dein Knecht! So sollst du auch mit deiner Magd tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Nicht schwer soll es dir fallen, wenn du ihn freiläßt! Denn er hat dir sechs Jahre ohne Taglöhners Lohn gedient. Dann segnet dich der Herr, dein Gott, in allem, was du tust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Jeden männlichen Erstlingswurf unter deinen Rindern und Schafen sollst du dem Herrn, deinem Gott, weihen! Du sollst nicht mit dem Erstlingswurf deiner Rinder arbeiten und nicht den deiner Schafe scheren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'An der vom Herrn erwählten Stätte sollst du sie Jahr für Jahr mit deinem Hause essen vor dem Herrn, deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Sind sie aber bemakelt, sind sie lahm oder blind oder haben sie sonst einen schlimmen Makel, so darfst du sie nicht dem Herrn, deinem Gott, opfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'In deinen Toren darfst du solche essen, ob du unrein oder rein bist, wie Reh und Hirsch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Nur ihr Blut darfst du nicht genießen. Du sollst es auf die Erde wie Wasser gießen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '\"Achte auf den Ährenmonat, daß du dem Herrn, deinem Gott, Passah haltest! Denn im Ährenneumond hat dich der Herr, dein Gott, bei Nacht aus Ägypten geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Schlachte als Passahopfer für den Herrn, deinen Gott, Schafe und Rinder an der Stätte, die der Herr erwählt, um seinen Namen dort wohnen zu lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du sollst nichts Gesäuertes dazu essen! Du sollst sieben Tage darum ungesäuerte Brote, gemeine Kost essen! Denn in Hast bist du aus dem Ägypterland gezogen. Daß du des Tages deines Auszuges aus Ägypterland all dein Leben gedenkest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Sieben Tage darf in deinem ganzen Bereich kein Sauerteig bei dir gesehen werden. Von dem am Abend des ersten Tages geopferten Fleisch darf nichts über die Nacht bis zum Morgen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du darfst nicht das Passah in einer deiner Ortschaften feiern, die dir der Herr, dein Gott, gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Nur an der vom Herrn, deinem Gott, zur Wohnung seines Namens erwählten Stätte sollst du das Passah schlachten, am Abend bei Sonnenuntergang, um die Zeit deines Auszuges aus Ägypten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Koch und iß es an der vom Herrn, deinem Gott, erwählten Stätte! Am anderen Morgen reise ab und gehe zu deinen Zelten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sechs Tage noch sollst du ungesäuerte Brote essen! Am siebten sei Festversammlung zu Ehren des Herrn, deines Gottes! Da darfst du keine Arbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Abzählen sollst du dir sieben Wochen! Vom Anlegen der Sichel an die Halme sollst du anfangen, sieben Wochen zu zählen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Dann halte dem Herrn, deinem Gott, das Wochenfest mit den freiwilligen Gaben, die deine Hand spendet, je nachdem dich der Herr, dein Gott, segnete');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Sei fröhlich vor dem Herrn, deinem Gott, du, dein Sohn, deine Tochter, dein Knecht, deine Magd, der Levite in deiner Siedlung, der Fremdling, die Waise und die Witwe bei dir an der vom Herrn, deinem Gott, zur Wohnung seines Namens erwählten Stätte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Gedenke, daß du in Ägypten Sklave gewesen bist! Halte sorgsam diese Gebote!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Das Laubhüttenfest sollst du sieben Tage feiern, wenn du den Ertrag deiner Tenne und Kelter einheimst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Sei an diesem Feste fröhlich, du, dein Sohn, deine Tochter, dein Knecht, deine Magd, der Levite, der Fremdling, die Waise und die Witwe in deinen Toren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sieben Tage sollst du feiern ein Fest dem Herrn, deinem Gott, an der vom Herrn erwählten Stätte! Denn der Herr, dein Gott, segnet dich in all deinem Ertrag und bei allem Tun deiner Hände. Darum sei nur froh!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Dreimal im Jahr erscheine all dein Mannsvolk vor dem Herrn, deinem Gott, an der von ihm erwählten Stätte: am Fest der ungesäuerten Brote, am Wochenfest und am Laubhüttenfest! Man darf aber nicht leer vor dem Herrn erscheinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Jeder spende, was er geben kann, je nach dem Segen, den der Herr, dein Gott, dir gegeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Richter und Beamte sollst du dir einsetzen in all deinen Toren, die dir der Herr, dein Gott, gibt! Sie sollen das Volk gerecht richten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Beugen darfst du nicht das Recht, noch parteiisch sein! Du darfst keine Geschenke annehmen. Denn das Geschenk blendet der Weisen Augen und verdreht die Worte der Gerechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Nur das Recht sollst du im Auge haben, auf daß du lebest und das Land besitzest, das der Herr, dein Gott, dir gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du sollst dir nicht als heiligen Pfahl irgendwelchen Baum einpflanzen neben des Herrn, deines Gottes, Altar, den du dir machen wirst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Errichten sollst du dir kein Steinmal, was der Herr, dein Gott, haßt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '\"Du darfst dem Herrn, deinem Gott, weder ein Rind noch ein Schaf opfern, an dem ein Makel, etwas Schlimmes ist! Denn das ist dem Herrn, deinem Gott, ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Findet sich bei dir in einem deiner Tore, die der Herr, dein Gott, dir gibt, ein Mann oder ein Weib, die tun, was dem Herrn, deinem Gott, mißfällt, und die seinen Bund übertreten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'die hingehen, anderen Göttern dienen und sich vor ihnen hinwerfen und vor der Sonne oder dem Mond oder dem ganzen Himmelsheer, was ich verbiete,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'und wird es dir angezeigt und hörst du davon, dann untersuche es gründlich, und ist es wahr, ist die Sache richtig, ist dieses in Israel verübt worden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'dann führe jenen Mann oder jenes Weib, die so Schlimmes getan, zu deinen Toren hinaus, den Mann oder das Weib, und steinige sie zu Tode!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Auf die Aussage zweier oder dreier Zeugen soll den Tod erleiden, der sterben muß, nicht aber auf die Aussage nur eines Zeugen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Die Zeugen sollen zuerst Hand an ihn legen, um ihn zu töten, danach das ganze Volk! So tilge das Schlimme aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Fällt dir ein Urteil schwer bei einem Mord, einer Streitsache oder einem Schaden, überhaupt bei Streitsachen in deinen Toren, so mach dich auf und reise an die vom Herrn, deinem Gott, erwählte Stätte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Geh zu den levitischen Priestern und zu dem Richter, der zu jener Zeit da ist! Befrage sie, daß sie dir den Urteilsspruch kundgeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Tu nach dem Spruch, den sie dir geben an der vom Herrn erwählten Stätte! Tu genauso, wie sie dich unterweisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tu gemäß der Weisung, die sie dir geben und nach dem Rechtsspruch, den sie dir sagen! Weiche nicht von dem, den sie dir künden, nicht nach rechts und nicht nach links!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Wäre einer so vermessen, daß er auf den Priester nicht hörte, der dort im Dienst des Herrn, deines Gottes, steht, oder nicht auf den Richter hörte, der soll sterben! So tilge das Böse aus Israel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'auf daß es alles Volk höre und sich fürchte und fortan niemand vermessen handle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kommst du in das Land, das dir der Herr, dein Gott, gibt, und besetzest es und siedelst darin und sprichst du: \'Ich setze einen König über mich wie all die Völker rings um mich\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'so sollst du zum König über dich nur den setzen, den der Herr, dein Gott, erwählt! Aus deiner Bruder Mitte sollst du über dich einen König setzen! Einen Fremden, der nicht dein Bruder ist, darfst du nicht über dich setzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Nur soll er sich nicht viele Rosse halten und nicht das Volk nach Ägypten zurückführen, um sich viele Rosse anzuschaffen! Der Herr hat euch gesagt: \'Ihr sollt nie wieder auf diesem Weg zurückkehren!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Auch soll er sich nicht viele Weiber halten, damit sein Herz nicht abweiche! Auch Silber und Gold soll er sich nicht in Masse anhäufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Sobald er auf dem Königsthrone sitzt, mache er eine Abschrift dieser Lehre mit Erlaubnis der levitischen Priester in ein Buch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Er habe es bei sich und lese sein Leben lang darin, auf daß er lerne, den Herrn, seinen Gott zu fürchten und alle Worte dieser Lehre und dieser Gesetze zu achten und zu tun,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'auf daß sich sein Herz nicht über seine Brüder erhebe und nicht von diesem Gebote weiche, weder nach rechts noch nach links, damit er und seine Söhne lange in Israel regieren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '\"Den levitischen Priestern, dem ganzen Levitenstamm, soll kein Erbteil sein, wie dem anderen Israel! Sie sollen die Mähler des Herrn und das ihm Zugeeignete essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Aber Erbteil soll ihm nicht werden inmitten seiner Brüder! Der Herr ist sein Erbteil, wie er ihm verheißen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Dies sind die Gebühren der Priester vom Volke, von denen, die Opfer bringen. Sei es Rind oder Schaf, so gebe man dem Priester den Bug, die Kinnbacken und den Magen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Den ersten Abhub deines Kornes, Weines und Öles sowie den ersten Abhub deiner Schafschur sollst du ihm geben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Denn ihn hat der Herr, dein Gott, aus all deinen Stämmen erwählt, damit er und seine Söhne allzeit dastehen, im Namen des Herrn zu amten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Kommt ein Levite aus einem deiner Tore aus ganz Israel, wo er weilt, im Drange seines Herzens an die vom Herrn erwählte Stätte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'und amtet er im Namen des Herrn, seines Gottes, so gut wie alle seine Brüder, die Leviten, die dort vor dem Herrn stehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'dann soll er den gleichen Teil genießen wie sie, ungeachtet der Gaben seiner Bekannten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kommst du in das Land, das dir der Herr, dein Gott, gibt, so darfst du nicht lernen, die Greuel jener Völker nachzuahmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Bei dir darf sich niemand finden, der seinen Sohn oder seine Tochter durchs Feuer gehen läßt, niemand, der Wahrsagerei oder geheime Künste oder Zauberei treibt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'kein Geisterbanner, niemand, der einen Toten- oder Wahrsagergeist befragt, kein Totenbeschwörer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Denn wer solches tut, ist dem Herrn ein Greuel, und der Herr, dein Gott, wird sie vor dir ob dieser Greuel vertreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Sei ungeteilt bei dem Herrn, deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Denn diese Völker, die du besiegst, hören auf Zeichendeuter und Wahrsager. Dir aber gestattet der Herr, dein Gott, das nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Einen Propheten wie mich läßt der Herr, dein Gott, aus deiner Mitte, aus deinen Brüdern, erstehen. Auf diesen sollt ihr hören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Du hastja vom Herrn, deinem Gott, am Versammlungstag am Horeb verlangt: \'Nicht weiter will ich des Herrn, meines Gottes, Stimme hören und dies große Feuer nicht mehr sehen, daß ich nicht sterbe.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Damals sprach zu mir der Herr: \'Gut ist, was sie reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Ich lasse aus ihrer Brüder Mitte einen Propheten wie dich erstehen und lege ihm meine Worte in den Mund. Er kündet ihnen alles, was ich ihm befehle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Hört aber jemand nicht auf meine Worte, die er in meinem Namen kündet, den ziehe ich zur Rechenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Doch der Prophet, der sich vermißt, in meinem Namen etwas zu künden, was ich ihm nicht zu künden aufgetragen, und der im Namen anderer Götter redet, ein solcher Prophet sei des Todes!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Und denkst du: \'Wie sollen wir wissen, welches Wort der Herr nicht geredet hat?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'So wisse: Wenn ein Prophet in des Herrn Namen redet, und das Wort erfüllt sich nicht und trifft nicht ein, das ist ein Wort, das der Herr nicht gesprochen hat. Vermessentlich hat es der Prophet gesprochen. Davor sollst du nicht bangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '\"Rottet der Herr, dein Gott, die Völker aus, deren Land dir der Herr, dein Gott, gibt, besiegst du sie und siedelst du in ihren Städten und Häusern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'dann sollst du dir drei Städte aussondern in deinem Land, das dir der Herr, dein Gott, zu eigen gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Du sollst dir den Weg herrichten; dann teile in drei Kreise das Gebiet deines Landes, das dir der Herr, dein Gott, zu eigen gibt, daß dorthin jeder Totschläger fliehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'So sei es mit dem Totschläger, der dorthin flieht und leben bleibt: Wer seinen Nächsten unabsichtlich tötet, und er hat ihn früher nicht gehaßt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'geht er etwa mit seinem Nächsten in den Wald, Holz zu fällen, und seine Hand holt mit der Axt aus, den Baum zu fällen, und das Eisen fährt vom Stiele und trifft seinen Nächsten tödlich, der soll in eine dieser Städte fliehen und leben bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Damit nicht der Bluträcher erhitzten Gemütes dem Totschläger nachsetzen ihn einhole, weil der Weg zu weit ist, und ihn totschlage! Und doch ist er nicht des Todes schuldig, weil er ihn früher nicht gehaßt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Deshalb gebiete ich dir: Aussondern sollst du dir drei Städte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Erweitert der Herr, dein Gott, dein Gebiet, wie er deinen Vätern zugeschworen, und gibt er dir das ganze Land, das er deinen Vätern verheißen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'dann füge dir zu diesen dreien noch drei Städte, sofern du dies ganze Gesetz beachtest und tust, was ich dir heute gebiete, den Herrn, deinen Gott, allzeit zu lieben und in seinen Wegen zu wandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Daß in deinem Lande, das dir der Herr, dein Gott, zu eigen gibt, kein unschuldig Blut vergossen werde, und daß keine Blutschuld auf dir laste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Haßt aber jemand seinen Nächsten, lauert er ihm auf, überfällt ihn und schlägt ihn, daß er stirbt, und flieht er in eine dieser Städte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'dann sollen die Ältesten seiner Stadt ihn von dort abholen und dem Bluträcher ausliefern, damit er sterbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Dein Auge soll kein Mitleid mit ihm kennen: Schaffe des Unschuldigen Blut aus Israel, damit es dir wohlergehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Verrücken sollst du nicht deines Nächsten Grenzen, die die Vorfahren gezogen, auf deinem Besitze, den du bekommst in dem Lande, das dir der Herr, dein Gott, zu eigen gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ein Zeuge allein darf nicht gegen jemanden auftreten bei einem Verbrechen oder einem Vergehen oder bei einer Verfehlung, die er tut! Erst auf die Aussage zweier oder dreier Zeugen wird eine Sache bestätigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Tritt ein frevelhafter Kläger gegen jemanden auf, ihn fälschlich anzuklagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'dann sollen die beiden streitenden Männer hintreten vor den Herrn, die Priester und die Richter, die in jenen Tagen da sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Die Richter sollen genau nachforschen! Ist der Kläger ein lügnerischer Kläger, der Lügen gegen seinen Bruder aussagt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'dann tut ihm, was er seinem Bruder zu tun gedacht! So tilge das Böse aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Dann hören es die übrigen, fürchten sich und tun fortan nicht mehr so Schlimmes in deiner Mitte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Dein Auge soll kein Erbarmen kennen! Person um Person! Aug\' um Aug\'! Zahn um Zahn! Hand um Hand! Fuß um Fuß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '\"Ziehst du gegen deinen Feind zu Felde und siehst du Rosse und Wagen und Fußvolk, zahlreicher als du, dann sollst du dich nicht vor ihnen fürchten! Denn der Herr, dein Gott, ist mit dir, der dich aus dem Ägypterland geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Zieht ihr in den Kampf, dann trete der Priester vor, rede zum Volk');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'und spreche zu ihnen: \'Höre, Israel! Ihr beginnt jetzt den Kampf mit euren Feinden. Nicht werde euer Herz weich! Fürchtet euch nicht! Erschrecket nicht vor ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Der Herr, euer Gott, zieht mit euch, streitet gegen eure Feinde für euch und gibt euch den Sieg.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Die Ordner aber sollen zum Volke sprechen: \'Wer hat ein neues Haus gebaut und noch nicht eingeweiht? Er trete ab und gehe heim, damit er nicht in der Schlacht falle und ein anderer es einweihe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Wer hat einen Weinberg gepflanzt und ihn nicht genossen? Er trete ab und gehe heim, damit er nicht in der Schlacht falle und ein anderer ihn genieße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Wer hat sich ein Weib verlobt und noch nicht heimgeführt? Er trete ab und gehe heim, damit er nicht in der Schlacht falle und ein anderer sie heimführe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Dann sollen die Ordner weiter zu dem Volke sprechen: \'Wer ist furchtsam und weichen Herzens? Er trete ab und gehe heim, damit er nicht seiner Brüder Herz verzagt mache wie das seine!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Sind die Ordner mit ihrer Ansprache an das Volk fertig, dann soll man Truppenführer an die Spitze des Volkes stellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Gehst du an die Belagerung einer Stadt, dann biete ihr den Frieden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Und antwortet sie dir friedfertig und öffnet sie dir, dann soll dir alles Volk darin fronpflichtig und dienstbar werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ergibt sie sich aber nicht, sondern kämpft sie mit dir, dann belagere sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Gibt sie der Herr, dein Gott, in deine Hand, dann töte alles an Männern darin mit der Schärfe des Schwertes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Die Weiber aber, die Kinder, das Vieh und was sonst in der Stadt, all ihr Beutegut, darfst du plündern. So genieße deiner Feinde Beute, die dir der Herr, dein Gott, gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Also sollst du mit all den Städten tun, die weit weg von dir sind und nicht zu den Städten dieser Völker gehören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Doch in den Städten dieser Völker, die dir der Herr, dein Gott, zu eigen gibt, sollst du keinen Hauch leben lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Du sollst sie bannen! Die Chittiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter, wie dir der Herr, dein Gott, befiehlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'damit sie euch nicht lehren, nach all ihren Greueln zu tun, die sie zu Ehren ihrer Götter tun! Ihr würdet gegen den Herrn, euren Gott, sündigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Belagerst du eine Stadt lange Zeit und brennst du sie und willst du sie erobern, dann darfst du nicht ihre Bäume vernichten, indem du die Axt daran legst. Du darfst vielmehr davon essen. Sie selbst aber darfst du nicht fällen! Sind die Bäume des Feldes Menschen, daß sie von dir belagert werden mußten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Nur Bäume, von denen du weißt, daß sie keine eßbaren Früchte tragen, darfst du roden und fällen, um Belagerungswerke zu bauen gegen die Stadt, die mit dir streitet, bis sie fällt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '\"Wird in dem Lande, das dir der Herr, dein Gott, zu eigen gibt, jemand erschlagen auf dem Felde liegend gefunden, und man weiß nicht, wer ihn erschlagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'dann sollen deine Ältesten, und zwar deine Richter, hinausgehen und bis zu den Städten messen, die rings um den Erschlagenen sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Aus der Stadt, die dem Erschlagenen zunächst liegt, sollen die Ältesten dieser Stadt eine junge Kuh nehmen, mit der noch nicht gearbeitet worden ist und die noch an keinem Joch gezogen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Dann sollen die Ältesten dieser Stadt die junge Kuh in einen steinigen Bachgrund führen, wo nicht geackert und gesät wird! Und sie sollen dort in dem steinigen Bachgrunde der jungen Kuh das Genick brechen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Darauf sollen die Priester, die Levitensöhne, herantreten; denn sie hat der Herr, dein Gott, erwählt, ihm zu amten und mit des Herrn Namen zu segnen, und nach ihrem Ausspruche soll über jeden Streit und Schaden entschieden werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Aus jener Stadt, die dem Erschlagenen am nächsten ist, sollen alle Ältesten über der jungen Kuh, der in dem steinigen Bachgrunde das Genick gebrochen worden, ihre Hände waschen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'und sollen laut sprechen: \'Nicht haben unsere Hände dieses Blut vergossen, und unsere Augen haben es nicht gesehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Vergib, Herr, Deinem Volke Israel, das Du erlöst, und lege nicht Deinem Volke Israel unschuldig Blut auf!\' So wird die Blutschuld ihnen gesühnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'So sollst du selbst unschuldig vergossenes Blut tilgen aus deiner Mitte! Denn du sollst tun, was recht ist in den Augen des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Ziehst du gegen deinen Feind zu Feld, und gibt der Herr, dein Gott, ihn in deine Hand, und machst du von ihm Gefangene');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'und erblickst du unter den Gefangenen ein Weib, schön von Gestalt, und wirst du von Liebe zu ihr ergriffen und möchtest du sie dir zum Weibe nehmen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'dann bringe sie in dein Haus, daß sie ihr Haupt enthülle, ihre Nägel schneide,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'ihre Gefangenentracht ablege, in deinem Haus bleibe und Vater und Mutter einen Monat betrauere! Dann darfst du zu ihr eingehen und sie ehelichen, daß sie dein Weib sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Gefällt sie dir aber nicht mehr, dann gib sie ganz frei! Keinesfalls darfst du sie um Geld verkaufen. Du darfst gegen sie nicht roh sein, weil du sie geschwächt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Hat ein Mann zwei Frauen, die eine bevorzugt, die andere zurückgesetzt, und gebären ihm beide Söhne, die bevorzugte und die zurückgesetzte, und stammt der erstgeborene Sohn von der zurückgesetzten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'und setzt der Mann seine Söhne zu Erben ein über alles, was sein ist, dann darf er nicht dem Sohne der Bevorzugten vor dem Sohne der Zurückgesetzten, dem Erstgeborenen, die Rechte des Erstgeborenen geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Er muß den Erstgeborenen, den Sohn der Zurückgesetzten, anerkennen und ihm von allem, was sich bei ihm findet, zwei Drittel geben. Denn dieser ist der Erstling seiner Kraft. Ihm gehört das Erstgeburtsrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Hat jemand einen mißratenen und widerspenstigen Sohn, der nicht die Stimme des Vaters und der Mutter hört, wenn sie ihn zurechtweisen, und der ihnen nicht gehorcht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'so sollen ihn Vater und Mutter ergreifen und vor die Ältesten seiner Stadt führen, zum Tor seines Ortes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Sie sollen zu den Ältesten seiner Stadt sagen: \'Dieser unser Sohn ist mißraten und widerspenstig, er hört nicht auf unsere Stimme; er ist ein Schlemmer und Säufer!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Dann sollen ihn alle Männer seiner Stadt zu Tode steinigen! So tilge das Böse aus deiner Mitte! Ganz Israel soll es hören und sich fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Liegt auf jemand eine Schuld, ein todeswürdiges Verbrechen, und wird er hingerichtet und hängst du ihn an einen Baum,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'so darf sein Leichnam nicht über Nacht an dem Baume bleiben; du mußt ihn begraben noch am gleichen Tage. Denn ein Gehängter ist ein Gottesfluch. Du darfst dein Land nicht verunreinigen, das dir der Herr, dein Gott, zu eigen gibt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '\"Nicht sollst du mit ansehen, wie deines Bruders Rind oder Schaf irreläuft! Stiehl dich nicht davor beiseite! Du sollst sie deinem Bruder zurücktreiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Wohnt dein Bruder nicht nahe bei dir oder ist er dir nicht bekannt, so nimm es in dein Haus und behalt\'s bei dir, bis es dein Bruder sucht! Dann gib es ihm zurück!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Ebenso sollst du mit seinem Esel tun, mit seinem Gewande und mit allem, was deinem Bruder abhanden gekommen und was du gefunden hast! Nicht darfst du dich davor beiseitestehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Siehst du deines Bruders Esel oder Rind auf dem Wege zusammenbrechen, so darfst du dich ihm nicht versagen. Du mußt sie ihm aufrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ein Weib soll keine Männertracht tragen! Ein Mann keine Weiberkleider anziehen! Wer solches tut, ist dem Herrn, deinem Gott, ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Triffst du auf der Wanderung auf einem Baume oder am Boden ein Vogelnest mit Jungen oder Eiern, und sitzt die Mutter auf den Jungen oder Eiern, dann darfst du nicht die Mutter mitsamt den Jungen nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Die Mutter sollst du fliegen lassen, die Jungen aber kannst du dir nehmen, auf daß es dir wohlergehe und du lange lebest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Baust du ein neues Haus, so mach deinem Dach ein Geländer, daß du nicht Blutschuld auf dein Haus ladest, wenn jemand herabfiele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'In einen Weinberg sollst du nicht zweierlei pflanzen! Sonst wird der volle Ertrag, die Anlage, die du machst, und der Weinbergsertrag, etwas Geweihtes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Pflügen sollst du nicht mit Rind und Esel zusammen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du sollst kein Zeug anlegen, Gewebe aus Wolle und Flachs!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Quasten sollst du dir an die Zipfel deines Mantels machen, in den du dich hüllst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Führt jemand ein Weib heim und wohnt ihr bei, und spürt er Widerwillen gegen sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'tut ihr Unbill durch Worte an und bringt sie in üblen Ruf und sagt: \'Ich habe dieses Weib heimgeführt; dann nahte ich mich ihr. Ich habe sie aber nicht als Jungfrau erfunden\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'da sollen des Mädchens Eltern die Zeichen der Jungfrauschaft des Mädchens nehmen und vor die Ältesten der Stadt zum Tor bringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Der Vater des Mädchens sage zu den Ältesten: \'Ich habe meine Tochter diesem Manne zum Weibe gegeben, und da er Widerwillen gegen sie spürt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'tut er ihr Unbill durch Worte an und sagt: \"Ich habe deine Tochter nicht als Jungfrau erfunden\", hier aber sind die Jungfernzeichen meiner Tochter!\' Dann sollen sie das Bettuch vor den Ältesten der Stadt ausbreiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Daraufhin sollen die Ältesten jener Stadt den Mann nehmen und ihn züchtigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Auch sollen sie ihn um hundert Silberlinge büßen und sie dem Vater des Mädchens geben! Denn er hat eine Jungfrau Israels in bösen Ruf gebracht. Sie soll sein Weib bleiben! Er kann sich im ganzen Leben nicht von ihr scheiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ist aber solche Nachrede wahr und kann die Jungfrauschaft des Mädchens nicht erwiesen werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'dann führe man das Mädchen vor ihres Vaterhauses Tür, und die Leute aus ihrer Stadt sollen sie zu Tode steinigen! Denn sie hat eine Schandtat in Israel getan. Sie hat Unzucht getrieben in ihres Vaters Haus. So tilge das Böse aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Wird ein Mann bei einer verheirateten Frau liegend betroffen, so sollen beide sterben, der Mann, der dem Weibe beiwohnt, und das Weib! So tilge das Böse aus Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Trifft ein Mann eine verlobte Jungfrau innerhalb der Stadt und wohnt ihr bei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'so führt beide zum Tor jener Stadt und steinigt sie zu Tod, das Mädchen, weil es in der Stadt nicht geschrieen, und den Mann, weil er seines Nächsten Weib geschwächt hat! So tilge das Böse aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Trifft aber der Mann die verlobte Jungfrau auf freiem Felde, und der Mann packt sie und wohnt ihr bei, so soll der Mann allein sterben, der ihr beigewohnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Dem Mädchen sollst du nichts tun! Am Mädchen haftet kein todeswürdiges Vergehen. Es ist so, wie wenn jemand seinen Nächsten überfällt und totschlägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Denn da er sie auf freiem Felde getroffen, kann die verlobte Jungfrau geschrieen haben; aber niemand ist ihr zu Hilfe gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Trifft jemand eine unverlobte Jungfrau, ergreift sie, wohnt ihr bei, und er wird ausfindig gemacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'So gebe der Mann, der ihr beigewohnt, dem Vater des Mädchens fünfzig Silberlinge! Sie aber soll sein Weib sein, weil er sie geschwächt hat! Sein ganzes Leben lang kann er sie nicht entlassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, '\"Niemand darf seines Vaters Weib heiraten, noch seines Vaters Laken aufheben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'In des Herrn Gemeinde darf nicht eintreten, wer durch Zerquetschung verstümmelt ist oder durch Abschneiden der Röhre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'In des Herrn Gemeinde darf kein Bastard eintreten. Auch nicht das zehnte Glied von einem solchen darf in des Herrn Gemeinde eintreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Kein Ammoniter noch Moabiter darf in des Herrn Gemeinde eintreten. Auch das zehnte Glied von ihnen darf nicht in des Herrn Gemeinde eintreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Denn, als ihr aus Ägypten gezogen, sind sie euch nicht mit Brot und Wasser entgegengekommen. Auch hat man gegen dich den Beorsohn Bileam aus Petor in Mesopotamien verdingt, dich zu verfluchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Aber der Herr, dein Gott, hat nicht auf Bileam hören wollen. Dir verwandelte der Herr, dein Gott, den Fluch in Segen. Denn der Herr, dein Gott, liebt dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Niemals sollst du ihr Wohl und ihr Glück fördern, solange du lebst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Die Edomiter sollst du nicht verabscheuen! Denn sie sind deine Brüder. Auch die Ägypter sollst du nicht verabscheuen! Denn Gast bist du in ihrem Lande gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Kinder, die ihnen geboren werden, dürfen im dritten Gliede in des Herrn Gemeinde eintreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Ziehst du gegen deine Feinde, so hüte dich vor allem Ungehörigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Ist einer unter dir, der unrein wäre durch nächtlichen Zufall, so gehe er vor das Lager! Er darf nicht in das Lager hereinkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Erst wenn er sich gegen Abend gewaschen hat, darf er um Sonnenuntergang in das Lager kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Dir soll ein Platz außerhalb des Lagers sein! Dort tritt aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'In deinem Gürtel sollst du einen Spaten tragen! Grabe damit ein Loch, wenn du draußen niederkauern mußt, und bedecke wieder deinen Kot!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Denn der Herr, dein Gott, schreitet mitten durch dein Lager, dich zu schützen und dir deine Feinde preiszugeben. Darum sei dein Lager heilig, auf daß er nichts Widerliches an dir bemerke und sich nicht von dir wende!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Einen Sklaven, der vor seinem Herrn sich zu dir rettet, sollst du seinem Herrn nicht ausliefern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Er soll bei dir bleiben, in deiner Mitte, an dem Orte, den er wählt in einem deiner Tore, wo es ihm gefällt! Du sollst ihn nicht plagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Bei Israels Mädchen darf es keine Geweihte geben und bei den israelitischen Knaben keinen Geweihten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du sollst nicht eines Gelübdes wegen Hurenlohn oder Hundegeld in das Haus des Herrn, deines Gottes, bringen! Denn beides ist dem Herrn, deinem Gott, ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Du sollst von deinen Brüdern keinen Zins nehmen, weder Zins für Geld noch für Speise noch Zins für irgend etwas Leihbares!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Vom Ausländer darfst du Zins nehmen, aber von deinen Brüdern nicht fordern, auf daß dich der Herr, dein Gott, in all deiner Hände Werk segne in dem Lande, in das du kommst, es zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Machst du dem Herrn, deinem Gott, ein Gelübde, so sollst du nicht zögern, es zu erfüllen! Denn sonst fordert es der Herr von dir, und du wärest einer Sünde schuldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Meidest du das Geloben, so bist du keiner Sünde schuldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Was aber über deine Lippen kommt, sollst du halten! Tu also, wie du dem Herrn, deinem Gott, freiwillig gelobt und was du mündlich versprochen hast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kommst du in deines Nächsten Weinberg, so iß dich satt an Trauben nach Herzenslust! Aber du darfst nichts in dein Gefäß tun! Kommst du in die Halmfrucht deines Nächsten, so pflücke Ähren mit der Hand! Aber du darfst nicht die Sichel über deines Nächsten Halmfrucht schwingen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '\"Ein Mann nimmt ein Weib und heiratet sie. Sie findet aber nicht Gunst in seinen Augen, weil er an ihr etwas Abstoßendes entdeckt. So schreibt er ihr einen Scheidebrief, händigt ihn ihr aus und entläßt sie aus seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Sie aber geht nach dem Weggang aus seinem Hause hin und wird eines anderen Mannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Dieser zweite Mann aber schreibt ihr auch einen Scheidebrief, weil er ihr abgeneigt ist, händigt ihn ihr aus und entläßt sie aus seinem Hause, oder der zweite Mann stirbt, der sie zum Weib nimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Nun kann sie ihr erster Mann, der sie entlassen, nicht wieder zum Weibe nehmen, nachdem sie unrein geworden ist. Denn ein Greuel ist das vor dem Herrn. Du aber sollst das Land nicht beflecken, das dir der Herr, dein Gott, zu eigen gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Nimmt jemand ein neues Weib, so braucht er nicht mit dem Heere auszuziehen. Er gehört nicht dazu. Er soll ein Jahr für sein Haus frei sein, damit er sein Weib erfreue, das er genommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Man soll nicht die Handmühle, und zwar den oberen Mühlstein, pfänden; denn damit pfändet man das Leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Wird einer dabei ertappt, wie er einen seiner Brüder, einen Israeliten, stiehlt, ihn versklavt und verkauft, so soll ein solcher Dieb sterben! Tilge das Böse aus deiner Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Nimm dich in acht bei der Plage des Aussatzes, daß du genau all die Weisungen achtest und sie befolgst, die euch die levitischen Priester lehren! Wie ich ihnen befohlen, so sollt ihr sorgfältig verfahren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Bedenke, was der Herr, dein Gott, unterwegs an Mirjam tat, auf eurem Zuge aus Ägypten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Borgst du deinem Nächsten, dann darfst du nicht sein Haus betreten, um von ihm ein Pfand zu erheben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Draußen sollst du stehenbleiben! Der Mann, dem du geborgt, soll dir das Pfand herausbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Ist es ein armer Mann, dann lege dich nicht schlafen mit seinem Pfande!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Du sollst ihm das Pfand bei Sonnenuntergang zurückgeben, damit er sich in seinem Mantel schlafen lege und dich segne! Dann hast du ein Verdienst vor dem Herrn, deinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Einen armen und bedürftigen Taglöhner sollst du nicht drücken, sei er von deinen Brüdern oder von den Fremdlingen in deinem Land und in deinen Toren bei dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Du sollst ihm seinen Lohn noch am selben Tage geben, bevor die Sonne darüber untergeht! Denn er ist arm und verlangt sehnlich danach. Sonst ruft er den Herrn gegen dich an, und Sünde ist an dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Väter sollen nicht wegen der Kinder getötet werden und Kinder nicht wegen der Väter! Jeder sterbe nur für seine Schuld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Das Recht eines Fremdlings und einer Waise sollst du nicht beugen! Du sollst nicht das Kleid einer Witwe pfänden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Bedenke, daß du in Ägypten Sklave gewesen und daß dich der Herr, dein Gott, daraus befreit hat! Darum gebiete ich dir, so zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Hältst du auf dem Felde deine Ernte und vergißt du eine Garbe auf dem Felde, dann sollst du nicht zurückkehren, sie zu holen! Sie soll den Fremdlingen, Waisen und Witwen gehören, auf daß dich der Herr, dein Gott, bei allem Tun deiner Hände segne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Schüttelst du deine Ölbäume, dann sollst du nicht die Zweige hinterher abklopfen! Den Fremdlingen, Waisen und Witwen sollen sie eigen sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Hältst du Lese in deinem Weinberg, dann sollst du nicht hinterher Nachlese halten! Den Fremdlingen, Waisen und Witwen soll es eigen sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Bedenke, daß du in Ägypten Sklave gewesen! Darum gebiete ich dir, also zu tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '\"Ist Streit zwischen Männern, und treten sie vor Gericht, dann richte man sie! Den Unschuldigen spreche man frei und verurteile den Schuldigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Verdient der Schuldige Schläge, dann lasse ihn der Richter hinlegen und ihm vor ihm Schläge geben seines Frevels wegen zur Genüge an Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Vierzig Hiebe lasse er ihm geben, aber nicht mehr, damit dein Bruder nicht vor deinen Augen zerfleischt würde, versetzte man ihm noch mehr Hiebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du sollst einem Rinde beim Dreschen keinen Maulkorb anlegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Leben Brüder beisammen und stirbt einer von ihnen, ohne daß er einen Sohn gehabt, so soll die Frau des Verstorbenen nicht nach auswärts eines fremden Mannes werden! Ihr Schwager soll zu ihr eingehen! Er nehme sie sich zum Weibe und leiste ihr die Schwagerpflicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Der Erstgeborene, den sie gebiert, komme auf den Namen seines verstorbenen Bruders, daß nicht sein Name in Israel erlösche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Hat aber der Mann keine Lust, seine Schwägerin zu heiraten so gehe seine Schwägerin an das Tor zu den Ältesten und spreche: \'Mein Schwager weigert sich, seines Bruders Namen in Israel zu erhalten! Er will mir die Schwagerpflicht nicht leisten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Da sollen ihn die Ältesten seiner Stadt vorladen und ihm zureden! Bleibt er aber dabei und sagt: \'Ich habe keine Lust, sie zu nehmen\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'so trete seine Schwägerin in Gegenwart der Ältesten zu ihm, ziehe ihm den Schuh vom Fuße, speie ihm ins Angesicht, hebe an und sage: \'Also ergehe es jedermann, der seines Bruders Haus nicht aufbauen will!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Und sein Name heiße in Israel: \'Elender Barfüßer\'!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Raufen zwei Brüder miteinander, und eilt das Weib des einen herbei, ihren Mann zu befreien aus der Hand dessen, der ihn schlägt, und packt sie ihn mit der Hand an den Schamteilen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'dann haue ihr schonungslos die Hand ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'In deiner Tasche sollst du nicht zweierlei Gewichtssteine tragen, einen größeren und einen kleineren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'In deinem Hause sollst du nicht zweierlei Scheffel haben, einen größeren und einen kleineren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Nur volles und richtiges Gewicht sollst du haben, vollen und richtigen Scheffel, auf daß du lange lebst in dem Land, das dir der Herr, dein Gott, gibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Denn ein Greuel für den Herrn, deinen Gott, ist jeder, der solches tut und solche Unredlichkeit verübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Bedenke, was dir die Amalekiter unterwegs getan, auf deinem Zuge aus Ägypten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'wie sie dich unterwegs überfallen und all deine ermatteten Nachzügler von dir abschnitten, als du erschöpft und müde geworden, und wie sie Gott nicht gefürchtet haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Darum sollst du in dem Lande, das dir der Herr, dein Gott, zu eigen gibt, des Amalekiters Namen unter dem Himmel auslöschen, wenn dir der Herr, dein Gott, vor all deinen Feinden ringsum Ruhe schafft! Du sollst es nicht vergessen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '\"Kommst du in das Land, das dir der Herr, dein Gott, zu eigen gibt, nimmst du es in Besitz und siedelst du darin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'dann nimm einen Teil des ersten Abhubs all der Feldfrüchte, die du aus deinem Lande einbringst, das dir der Herr, dein Gott, gibt, lege sie in einen Korb und gehe zu der Stätte, die der Herr, dein Gott, erwählt, um seinen Namen dort wohnen zu lassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Tritt zu dem Priester hin, der zu jener Zeit Dienste tut, und sprich zu ihm: \'Hiermit zeige ich heute dem Herrn, deinem Gott, an, daß ich in das Land gekommen bin, das uns zu geben der Herr unseren Vätern zugeschworen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Dann nehme der Priester den Korb aus deiner Hand und stelle ihn vor den Altar des Herrn, deines Gottes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Dann heb an und sprich also vor dem Herrn, deinem Gott: \'Ein Aramäer, stammgetrennt, ist mein Ahn gewesen. Er zog mit einem geringen Häuflein nach Ägypten, war dort zu Gast und ward daselbst zu großem, starkem und zahlreichem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Die Ägypter aber Behandelten uns und bedrückten uns und legten uns harte Arbeit auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Da schrieen wir zum Herrn, dem Gott unserer Väter. Und der Herr erhörte unser Rufen und sah auf unser Elend, unsere Mühsal und Qual.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Dann führte der Herr uns aus Ägypten mit starker Hand und ausgerecktem Arme, mit furchtbarer Macht und unter Zeichen und Wundern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Er brachte uns an diese Stätte und gab uns dieses Land, ein Land, von Milch und Honig fließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Und hier bringe ich den ersten Abhub der Früchte aus dem Lande, das Du mir gegeben, Herr!\' Damit laß sie beim Herrn deinem Gott, wirf dich nieder vor dem Herrn, deinem Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'und freue dich an all dem Segen, den dir und deinem Haus der Herr, dein Gott, geschenkt, du selbst, der Levite und der Fremdling bei dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Lieferst du vollständig im dritten Jahre, dem Zehntjahre, den ganzen Zehnten deiner Erträgnisse ab, dann gib ihn den Leviten, Fremdlingen, Waisen und Witwen, damit sie ihn in deinen Toren verzehren und sich sättigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Dann erkläre vor dem Herrn, deinem Gott: \'Ich habe das Heilige aus dem Haus geschafft und es den Leviten, Fremdlingen, Waisen und Witwen gegeben, genau nach Deinem Gebote, das Du mir geboten. Ich habe keines Deiner Gebote übertreten und keines vergessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ich habe nichts davon im Tempel genossen und nichts davon beseitigt in unfrommer Weise und habe nichts davon einem Toten gegeben. Ich gehorche der Stimme des Herrn, meines Gottes, und tue alles, was Du mir befahlst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Neige Dich von Deiner heiligen Wohnung, vom Himmel, und segne Dein Volk Israel und die Scholle, die Du uns gegeben, wie Du unseren Vätern zugeschworen, ein Land, von Milch und Honig fließend!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Heute befiehlt dir der Herr, dein Gott, diese Gebote und Gebräuche zu tun. So befolge sie sorgfältig von ganzem Herzen und aus ganzer Seele!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Du erklärst heute von dem Herrn, er soll dein Gott sein und du wollest in seinen Wegen wandeln, seine Gesetze, Gebote und Gebräuche halten und seiner Stimme gehorchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Und der Herr erklärt heute von dir, du sollest ihm ein Sondervolk sein, wie er dir verheißen, wenn du all seine Gebote befolgst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Er wolle dich hoch über alle Völker setzen, die er geschaffen, zu Preis, Ruhm und Ehre, und du sollst dem Herrn, deinem Gott, ein heiliges Volk sein, wie er zugesagt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Da geboten Moses und die Ältesten Israels dem Volk: \"Merkt genau auf das Gebot, das ich euch heute gebiete!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Zieht ihr über den Jordan in das Land, das dir der Herr, dein Gott, gibt, so errichte dir große Steine, tünche sie mit Kalk');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'und schreibe darauf alle Worte dieser Lehre, sobald du hinüberziehst, damit du in das Land kommest, das dir der Herr, dein Gott, gibt, in ein Land von Milch und Honig fließend, wie der Herr, der Gott deiner Väter, dir verheißen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Sobald ihr den Jordan überschritten habt, sollst du diese Steine errichten, nach meinem heutigen Befehl, auf dem Berge Ebal, und tünche sie mit Kalk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Auch baue dort einen Altar dem Herrn, deinem Gott, einen Altar aus Steinen! Aber kein Eisen sollst du darüber schwingen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Aus unbehauenen Steinen sollst du den Altar des Herrn, deines Gottes, bauen! Und bring darauf dem Herrn, deinem Gott, Brandopfer dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Schlachte auch Mahlopfer und iß dort und sei fröhlich vor dem Herrn, deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Auf die Steine schreibe deutlich und klar alle Worte dieser Lehre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Da sprachen Moses und die levitischen Priester zu Gesamtisrael also: \"Merk auf und höre, Israel! Heute wirst du das Volk des Herrn, deines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'So höre auf des Herrn, deines Gottes, Stimme und halte seine Gebote und Gebräuche, die ich dir heute gebiete!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Am selben Tage gebot Moses dem Volke:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '\"Habt ihr den Jordan überschritten, so sollen sich die einen auf dem Berge Garizim aufstellen, daß man das Volk segne: Simeon, Levi, Juda, Issakar, Joseph und Benjamin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Die anderen sollen sich auf dem Berge Ebal gegen den Fluch aufstellen: Ruben, Gad, Asser, Zabulon, Dan und Naphtali!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Und die Leviten sollen anheben und sprechen zu allen Männern Israels mit hocherhobener Stimme:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '\'Verflucht, wer ein Schnitz- oder Gußbild macht, ein Werk von Künstlerhand, ein Greuel für den Herrn, und es insgeheim aufstellt!\' Das ganze Volk antworte und spreche: So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '\'Verflucht, wer Vater oder Mutter verunehrt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '\'Verflucht, wer seines Nächsten Grenze rückt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '\'Verflucht, wer einen Blinden auf dem Wege irreführt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '\'Verflucht, wer das Recht des Fremdlings, der Waise und der Witwe beugt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '\'Verflucht, wer seines Vaters Weibe beiwohnt! Denn er deckt seines Vaters Laken auf.\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '\'Verflucht, wer irgendeinem Tier beiwohnt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '\'Verflucht, wer seiner Schwester, Vater- oder Muttertochter beiwohnt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '\'Verflucht, wer seiner Schwiegermutter beiwohnt!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '\'Verflucht, wer seinen Nächsten heimlich erschlägt!\' Das ganze Volk spreche:So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '\'Verflucht sei, wer sich bestechen läßt, um unschuldig Blut zu vergießen!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '\'Verflucht, wer nicht die Worte dieser Lehre aufrechthält und sie tut!\' Das ganze Volk spreche: \'So sei es!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '\"Hörst du auf die Stimme des Herrn, deines Gottes, und hältst du sorgsam alle seine Gebote, die ich dir heute gebiete, dann stellt dich der Herr, dein Gott, hoch über alle Völker der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Alle diese Segnungen kommen dir zu und treffen dich, hörst du auf des Herrn, deines Gottes, Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Gesegnet wirst du sein in der Stadt und gesegnet auf dem Feld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Gesegnet die Frucht deines Leibes, die Frucht deines Feldes und die Zucht deines Viehs, der Wurf deiner Rinder und die Tracht deiner Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Gesegnet dein Korb und deine Backschüssel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Gesegnet bist du bei deinem Eingang und deinem Ausgang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Der Herr streckt deine Feinde nieder, die gegen dich aufstehen. Auf einem Weg ziehen sie gegen dich; auf sieben fliehen sie vor dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Der Herr entbietet bei dir den Segen in all deine Speicher und bei allem Unterfangen deiner Hand. Er segnet dich in dem Lande, das dir der Herr, dein Gott, gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Der Herr bereitet dich zu einem heiligen Volke für sich, wie er dir zugeschworen, falls du des Herrn, deines Gottes, Gebote hältst und in seinen Wegen wandelst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Dann sehen alle Völker der Erde, daß du des Herrn Namen trägst, und sie fürchten sich vor dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Dann gibt dir der Herr im Überflusse die Frucht deines Leibes, deines Viehs und deines Bodens auf der Scholle, die dir zu geben der Herr deinen Vätern zugeschworen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Der Herr öffnet für dich sein reiches Schatzhaus, den Himmel, um deinem Lande Regen zur rechten Zeit zu spenden und alles Tun deiner Hand zu segnen. Dann kannst du vielen Völkern leihen, mußt aber selbst nichts entlehnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'So macht dich der Herr zum Haupte und nicht zum Schweife. Du steigst immer höher und kommst nicht nach unten, falls du des Herrn, deines Gottes, Gebote befolgst, die ich dir heute gebe, und sie sorgsam hältst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Weiche weder nach rechts noch nach links in all dem, was ich dir heute gebiete! Folge nicht, dienend, anderen Göttern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Hörst du nicht auf die Stimme des Herrn, deines Gottes, und befolgst du nicht all seine Gebote und Gebräuche, die ich dir heute vorlege, dann kommen alle diese Flüche über dich und treffen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Verflucht wirst du sein in der Stadt und auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Verflucht dein Korb und deine Backschüssel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Verflucht die Frucht deines Leibes und deines Bodens, der Wurf deiner Rinder und die Tracht deiner Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Verflucht bist du bei deinem Eingang und deinem Ausgang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Der Herr sendet gegen dich den Fluch, Zerrüttung und Verwünschung bei allen deinen Geschäften, die du tust, bis du vertilgt bist und bald untergehst wegen der Schlechtigkeit deiner Werke, weil du mich verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Der Herr heftet die Pest an dich, bis sie dich aus dem Land vertilgt, in das du ziehst, es zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Der Herr schlägt dich mit Auszehrung, Fieber, Entzündung und Hitze, mit Dürre, Getreidebrand und Meltau. Sie jagen dich, bis du untergehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Der Himmel über deinem Haupte wird von Erz und der Boden unter dir zu Eisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Der Herr wandelt den Regen deines Landes in Staub und Sand. Vom Himmel fällt er auf dich, bis du vertilgt bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Der Herr wirft dich vor deine Feinde hin. Auf einem Wege ziehst du gegen ihn; auf sieben fliehst du vor ihnen. Du wirst allen Königreichen der Erde zum Entsetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Dein Leichnam wird ein Fraß allen Vögeln des Himmels und dem Getier der Erde, und niemand verscheucht sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Der Herr schlägt dich mit Ägyptens Geschwür, mit Beulen, Krätze und Grind, unheilbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Der Herr schlägt dich mit Irrsinn, Blindheit und Geistesverwirrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Du tappst am hellen Mittag wie der Blinde im Dunkeln und hast kein Glück auf deinen Wegen. Du bist allzeit nur gedrückt und vergewaltigt, und niemand hilft dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Du verlobst dir ein Weib, und ein anderer beschläft sie. Du baust ein Haus und wohnst nicht darin. Du pflanzest einen Weinberg und genießest nicht seine Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Dein Rind wird vor deinen Augen geschlachtet. Du aber kannst nicht davon essen. Dein Esel wird vor deinem Angesicht geraubt und kehrt nicht mehr zu dir. Deine Schafe werden deinen Feinden gegeben, und niemand hilft dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Deine Söhne und Töchter werden einem fremden Volke verkauft. Deine Augen sehen es und schmachten nach ihnen allzeit. Aber du bist machtlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Deiner Scholle Frucht und all deine Mühen verzehrt ein Volk, dir unbekannt. Du bist allzeit nur unterdrückt und zertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Du wirst irrsinnig von dem, was deine Augen sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Der Herr schlägt dich mit bösem Geschwür an Knien und Schenkeln, daß du nicht geheilt werden kannst, von der Sohle bis zum Scheitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Der Herr führt dich und deinen König, den du über dich setzest, zu einem Volke, das dir und deinen Vätern unbekannt. Dort mußt du anderen Göttern dienen, Holz und Stein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Du wirst zum Entsetzen, Spott und Hohn bei all den Völkern, zu denen dich der Herr führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Vielen Samen bringst du auf das Feld und erntest wenig. Denn die Heuschrecken fressen es ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Du pflanzest Weinberge und bebauest sie. Doch trinkst du nicht Wein und lagerst nichts ein. Denn der Wurm frißt ihn ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Überall in deinem Gebiete hast du Ölbäume. Aber du salbst dich nicht mit Öl. Denn deine Oliven fallen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Du zeugst Söhne und Töchter. Aber sie bleiben nicht bei dir. Denn sie wandern in Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'All deine Bäume und deines Bodens Frucht verdirbt das Ungeziefer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Der Fremdling unter dir steigt immer höher über dich. Du aber sinkst immer tiefer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Er leiht dir. Du aber leihst ihm nichts. Er wird das Haupt, du der Schweif.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Alle diese Flüche kommen über dich, jagen dich und treffen dich, bis du vertilgt bist, weil du der Stimme des Herrn, deines Gottes, nicht gehorchst und seine Gebote und Gesetze, die er dir auferlegt, nicht beachtest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Sie haften als Zeichen und Wunder an dir und deinem Stamme für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Dafür, daß du dem Herrn, deinem Gott, nicht gedient hast in Freude und in Herzensfröhlichkeit trotz des Überflusses an allem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'sollst du deinen Feinden dienen, die der Herr gegen dich sendet, in Hunger, Durst, Blöße und Mangel an allem. Er legt dir ein Eisenjoch auf den Hals, bis er dich vertilgt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Der Herr holt gegen dich von ferne, vom Ende der Erde, ein Volk, das wie ein Adler schwebt, ein Volk, dessen Sprache du nicht verstehst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'ein Volk wilden Blickes, rücksichtslos gegen Greise, erbarmungslos gegen Knaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Es verzehrt die Frucht deines Viehs und deines Bodens, bis du vernichtet bist. Nichts läßt es dir übrig von Korn, Wein und Öl, vom Wurf deiner Rinder und der Tracht deiner Schafe, bis es dich vertilgt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Es belagert dich in all deinen Toren, bis deine hohen und festen Mauern fallen, auf die du vertraust, überall in deinem Lande. Und es belagert dich in all deinen Toren, überall in deinem Lande, das dir der Herr, dein Gott, gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'In der Angst und Not, in die dich dein Feind bringt, verzehrst du deine Leibesfrucht, das Fleisch deiner Söhne und Töchter, die dir der Herr, dein Gott, schenkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Der Weichlichste und Verzärtelste bei dir ist mißgünstig gegen seinen Bruder, sein liebes Weib und die Kinder, die er übrigbehielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Keinem von ihnen gibt er von seiner Kinder Fleisch, das er verzehrt, weil ihm nichts übrigbleibt in Angst und Not, in die dich dein Feind in all deinen Toren bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Die Weichlichste und Üppigste bei dir, die vor Verzärtelung und Weichlichkeit nie versucht hat, ihren Fuß auf die Erde zu setzen, ist mißgünstig gegen den lieben Mann, ihren Sohn und ihre Tochter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'bei ihrer Nachgeburt, die ihren Schoß verläßt, und bei den Kindern, die sie zur Welt bringt. Denn beim Mangel an allem ißt sie diese insgeheim in Angst und Not, in die dich dein Feind in all deinen Toren bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Achtest du nicht darauf, alle Worte dieser Lehre, die in diesem Buche geschrieben sind, zu tun, fürchtest du nicht \'den Herrn, deinen Gott\', diesen glorreichen und furchtbaren Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'dann verhängt der Herr über dich und deine Nachkommen außerordentliche Plagen, gewaltige und andauernde Plagen und böse anhaltende Krankheiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Er bringt über dich Ägyptens ganzes Siechtum, vor dem dir graut. Dir haftet es an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Auch jede Krankheit und Plage, von denen in diesem Buch der Lehre nichts geschrieben steht, bringt der Herr aber dich, bis du vernichtet bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Nur wenig Männer werden von euch übrigbleiben, statt daß an der Menge ihr gleich wäret den Sternen des Himmels, weil du der Stimme des Herrn, deines Gottes, nicht gehorchst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Und wie sich der Herr über euch freut, euch wohlzutun und euch zu mehren, so freut sich der Herr darüber euch, euch zu vernichten und zu tilgen. Ihr werdet herausgerissen aus dem Lande, in das du ziehst, es zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Der Herr zerstreut dich unter alle Völker von einem Ende der Erde bis zum anderen. Dort wirst du anderen Göttern dienen müssen, dir und deinen Vätern unbekannt, Holz und Stein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Du rastest nicht bei jenen Völkern. Keine Ruhestatt ist deiner Fußsohle gegönnt, Vielmehr gibt dir der Herr ein bebend Herz, verschmachtende Augen und verzagtes Gemüt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Dein Leben ist dir in der Schwebe. Du zitterst bei Tag und Nacht und traust deinem Leben nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Am Morgen denkst du: \'Wär\'s doch Abend!\'; am Abend denkst du: \'Wär\'s doch Morgen!\', in Herzensangst vor dem, was deine Augen schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Der Herr bringt dich wieder nach Ägypten, auf dem Wege, von dem ich zu dir gesprochen: Du sollst ihn nie wieder sehen. Dort werdet ihr feilgeboten deinen Feinden als Sklaven und Sklavinnen. Aber niemand mag euch kaufen.\" Das sind die Worte des Bundes, den der Herr dem Moses aufgetragen hat, mit den Israeliten im Lande Moab zu schließen, abgesehen von dem Bunde, den er mit ihnen am Horeb geschlossen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Und Moses berief ganz Israel und sprach zu ihnen: \"Ihr habt alles gesehen, was der Herr vor euren Augen im Ägypterland getan an Pharao und all seinen Dienern und seinem ganzen Lande,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'die großen Machterweise, die deine Augen sahen, jene großen Zeichen und Wunder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Aber bis auf den heutigen Tag hat euch der Herr noch nicht den Sinn zum Begreifen gegeben, noch nicht Augen zum Sehen, noch nicht Ohren zum Hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Ich führte euch vierzig Jahre in der Wüste. Eure Kleider haben sich an euch nicht abgetragen, und dein Schuh ist nicht an deinem Fuße zermürbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Ihr habt kein Brot gegessen und weder Wein noch Bier getrunken, auf daß ihr erkennet, daß ich, der Herr, euer Gott, bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'So kamt ihr an diese Stätte. Da zogen wider uns der König von Chesbon, Sichon, und Og, der König von Basan. Wir aber besiegten sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'nahmen ihr Land und gaben es den Rubeniten, den Gaditen und dem Halbstamm Manasse zu eigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'So habt denn acht auf die Worte dieses Bundes und tut sie, auf daß ihr Glück habt in allem, was ihr tut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Ihr steht heute alle vor dem Herrn, eurem Gott, eure Häupter, eure Richter, eure Ältesten und Amtleute, alle Männer Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'eure Kinder, Weiber und dein Fremdling, der in deinem Lager weilt, von deinen Holzhauern bis zu deinen Wasserschöpfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Du sollst eintreten in den Bund mit dem Herrn, deinem Gott, und in seinen Vertrag, den der Herr, dein Gott, heute mit dir eingeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Er möchte dich heute zu seinem Volke bestellen und dein Gott werden, wie er dir verheißen und wie er deinen Vätern Abraham, Isaak und Jakob zugeschworen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Aber nicht mit euch allein schließe ich diesen Bund und diesen Vertrag,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'sondern auch mit dem, der heute hier bei uns ist und vor dem Herrn steht, sowie mit dem, der heute nicht mit uns hier ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Ihr selber wißt, wie wir im Ägypterland geweilt und wie wir mitten durch die Völker gezogen, die ihr durchzogen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Ihr schautet ihre Scheusale und ihre Götzen von Holz und Stein, Silber und Gold bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Möchte es doch nicht bei euch einen Mann geben oder ein Weib oder eine Sippe oder einen Stamm, dessen Herz sich heute wendet vom Herrn, unserem Gott, und hingeht und den Göttern jener Völker dient! Möchte sich unter euch keine Wurzel finden, die Schierling und Wermut treibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Daß nicht jemand beim Anhören dieser Fluchworte in seinem Herzen fröhlich denke: \'Mir geht es gut; ich kann in meines Herzens Härte wandeln\', um Hinterlist und Wollust zu vereinen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Einem solchen verziehe der Herr nicht, sondern des Herrn Zorn und Eifer loderte gegen einen solchen Menschen auf. Der ganze in diesem Buch aufgezeichnete Fluch lastete auf ihm, und der Herr löschte seinen Namen unter dem Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Der Herr schiede einen solchen zum Verderben aus allen Stämmen Israels, nach allen Bundesflüchen, die in diesem Buch der Lehre aufgezeichnet sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Das spätere Geschlecht, eure Kinder, die nach euch aufwachsen, und der Ausländer, der aus fernem Lande kommt, würden fragen, wenn sie in jenem Lande die Plagen und Krankheiten sehen, mit denen der Herr es erschöpft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Sein ganzer Boden wird Schwefel, Salz und Brandstatt sein. Er kann nicht mehr besät werden und läßt nichts sprossen, und kein Gewächs geht darin auf. Eine Verwüstung wird es, wie die auf Sodoma und Gomorrha, Adma und Seboim, die der Herr in seinem Zorn und Grimm umgekehrt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Und alle Völker werden fragen: \'Warum hat der Herr also mit diesem Lande getan? Wofür diese gewaltige Zornesglut?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Dann antwortet man: \'Weil sie den Bund verlassen haben, den der Herr, der Gott ihrer Väter, mit ihnen geschlossen, als er sie aus Ägypterland führte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'weil sie hingingen, anderen Göttern dienten und sich vor ihnen hinwarfen, vor Göttern, die ihnen unbekannt waren und die er ihnen nicht zugeteilt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Darum entbrannte des Herrn Zorn über das Land, daß er darüber den ganzen Fluch brachte, der in diesem Buche geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Der Herr riß sie in Zorn und Grimm und großer Wut aus ihrem Boden und schleuderte sie in ein anderes Land, wie es heute ist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Das Verborgene ist des Herrn, unseres Gottes. Das Enthüllte aber gehört uns und unseren Kindern immerdar, damit wir alle Worte dieser Lehre tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '\"Kommen über dich alle diese Worte, der Segen und der Fluch, die ich dir vorgelegt, und nimmst du es zu Herzen unter all den Völkern, wohin dich der Herr, dein Gott, verstößt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'und bekehrst du dich samt deinen Kindern von ganzem Herzen und aus ganzer Seele zum Herrn, deinem Gott, und gehorchst du seiner Stimme in allem, was ich dir heute gebiete,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'dann wendet der Herr, dein Gott, dein Geschick, erbarmt sich deiner und sammelt dich aus allen Völkern, unter die dich der Herr, dein Gott, verstreut hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Mögen deine Versprengten am Ende des Himmels sein, so sammelte dich der Herr, dein Gott, auch dort und holte dich von dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Und der Herr, dein Gott, brächte dich in das Land, das deine Väter besessen, und du wirst es besitzen. Er beglückte und mehrte dich reichlicher als deine Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Der Herr, dein Gott, beschneidet dann dir und deinen Nachkommen das Herz, daß du den Herrn, deinen Gott, von ganzem Herzen und aus ganzer Seele liebest, um deines Lebens willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Und der Herr, dein Gott, legt all diese Flüche auf deine Feinde und Hasser, die dich gejagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Du aber gehorchst wieder der Stimme des Herrn, deines Gottes, und befolgst alle seine Gebote, die ich dir heute gebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Und der Herr, dein Gott, gibt dir Überfluß bei jedem Tun deiner Hand, bei der Frucht deines Leibes und bei dem Wurf deines Viehs und bei der Ernte deines Bodens. Denn dann hat der Herr wieder Freude an dir, wie er sich an deinen Vätern gefreut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'wenn, du der Stimme des Herren, deines Gottes, gehorsam, seine Gebote und Satzungen beachtest, die in diesem Buch der Lehre aufgezeichnet sind, und dich von ganzem Herzen und aus ganzer Seele zum Herrn, deinem Gott, bekehrst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Denn dieses Gebot, das ich dir heute gebe, übersteigt nicht deine Kraft und ist nicht unerreichbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Nicht ist es im Himmel, daß du sprächest: \'Wer steigt für uns in den Himmel und holt es uns herab und kündet es uns, daß wir danach tun?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Auch ist es nicht jenseits des Meeres, daß du sprächest: \'Wer fährt uns über das Meer und holt es uns und kündet es uns, daß wir danach tun?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Nein! Sehr nahe ist dir das Wort in deinem Munde und in deinem Herzen, es zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Siehe! Ich lege dir heute vor: das Leben und das Glück, den Tod und das Böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Wenn ich dir heute befehle, den Herrn, deinen Gott, zu lieben, auf seinen Wegen zu wandeln und seine Gebote, Gesetze und Gebräuche zu beachten, dann bleibst du leben und mehrst dich. Und der Herr, dein Gott, segnet dich in dem Lande, in das du ziehst, es zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Wird aber dein Herz abtrünnig, bist du ungehorsam und läßt du dich verführen, dich vor anderen Göttern hinzuwerfen und ihnen zu dienen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'dann verkünde ich euch heute: Ihr geht zugrunde. Ihr lebt nicht lange auf dem Boden, zu dessen Besetzung du über den Jordan ziehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Ich nehme heute Himmel und Erde zu Zeugen gegen euch, daß ich dir Leben und Tod, Segen und Fluch vorlegte. So wähle das Leben, auf daß du lebest, du und deine Nachkommen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'wenn du den Herrn, deinen Gott, liebst, seiner Stimme gehorchst und ihm anhängst! Denn das ist dein Leben und dein langes Siedeln auf dem Boden, den ihnen zu geben der Herr deinen Vätern Abraham, Isaak und Jakob zugeschworen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Da ging Moses daran, diese Worte zu ganz Israel zu sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Er sprach zu ihnen: \"Ich bin heute hundertzwanzig Jahre alt. Ich kann nicht mehr ausrücken und heimziehen. Auch hat mir der Herr gesagt: \'Du wirst nicht den Jordan überschreiten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Der Herr, dein Gott, zieht vor dir hinüber. Er vertilgt diese Völker vor dir, daß du sie besiegest. Josue zieht vor dir hinüber, wie der Herr gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Der Herr tut an ihnen, wie er an den Amoriterkönigen Sichon und Og und ihrem Land getan, und die er vertilgt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Der Herr gibt sie euch preis, tut an ihnen genau nach dem Befehle, den ich euch gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Seid mutig und stark! Fürchtet euch nicht! Bangt nicht vor ihnen! Denn der Herr, dein Gott, ist es, der mit dir zieht. Er läßt und verläßt dich nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Dann berief Moses Josue und sprach zu ihm vor ganz Israel: \"Sei mutig und stark! Denn du bringst dieses Volk in das Land, das ihnen zu geben der Herr ihren Vätern zugeschworen hat. Verteilen sollst du es unter sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Der Herr selbst zieht vor dir her. Er ist mit dir. Er läßt dich nicht und verläßt dich nicht. Du sollst furchtlos und unverzagt sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Dann schrieb Moses diese Lehre auf und gab sie den Priestern, den Levisöhnen, die die Bundeslade des Herrn trugen, und allen Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Und Moses gebot ihnen also: \"Nach sieben Jahren, um die Zeit des Erlaßjahres, am Laubhüttenfest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'wenn ganz Israel kommt, vor dem Herrn, deinem Gott, zu erscheinen, an der von ihm erwählten Stätte, dann lies diese Lehre ganz Israel laut vor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Berufe das Volk, die Männer, Weiber, Kinder und deine Fremdlinge in deinen Toren zu einer Versammlung, auf daß sie hören und lernen, den Herren, euren Gott, zu fürchten, und alle Worte dieser Lehre beachten und tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Ihre Kinder, die es noch nicht kennen, sollen hören und lernen, den Herrn, euren Gott, zu fürchten alle Zeit, die ihr auf dem Boden lebt, zu dessen Besetzung ihr über den Jordan zieht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Und der Herr sprach zu Moses: \"Deine Tage nahen dem Ende. Rufe Josue! Tretet dann ins Festgezelt, daß ich ihn einsetze!\" Da gingen Moses und Josue hin und betraten das Festgezelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Darauf erschien der Herr im Zelt in einer Wolkensäule. Die Wolkensäule aber stand an der Pforte des Zeltes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Da sprach der Herr zu Moses: \"Du wirst dich bald zu deinen Ahnen legen. Dann steht dieses Volk auf und buhlt in seiner Mitte mit den fremden Göttern des Landes, in das du bald ziehst. Es verläßt mich und bricht den Bund, den ich mit ihm geschlossen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Dann entbrennt mein Zorn über sie. Ich lasse sie im Stich und berge mein Antlitz vor ihnen. Dann wird es zum Fraße. Und viele Nöte und Übel treffen es. Dann spricht es zu jener Zeit: \'Treffen mich nicht diese Übel, weil mein Gott nicht mehr in meiner Mitte ist?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ich aber berge zu jener Zeit mein Antlitz wegen all des Bösen, das es tut, weil es sich anderen Göttern zuwendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'So schreibt euch dieses Lied auf! Lehre es die Israeliten! Lege es ihnen in den Mund, daß mir dieses Lied zum Zeugen gegen die Söhne Israels diene!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Ich bringe das Volk allerdings in das Land, das ich seinen Vätern zugeschworen und das von Milch und Honig fließt. Es ißt, wird satt und fett, wendet sich aber anderen Göttern zu und dient ihnen. Mich aber schmähen sie und brechen den Bund mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Wenn es dann viele Nöte und Übel treffen, dann sei dieses Lied vor ihm ein Zeuge, es bleibt im Munde seiner Nachkommen unvergessen. Dafür, daß ich im voraus gewußt habe, wohin bei ihm die Neigung geht, bevor ich es in das Land gebracht, das ich zugeschworen habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Und Moses schrieb an jenem Tage dieses Lied nieder und ließ es die Israeliten einüben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Dann gebot er Josue, Nuns Sohn: \"Sei mutig und sei stark! Du führst die Israeliten in das Land, das ich ihnen zugeschworen habe. Ich werde mit dir sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Und Moses schrieb die Worte dieser Lehre im ganzen Umfang in ein Buch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Dann gebot Moses den Leviten, den Trägern der Bundeslade des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '\"Nehmt dieses Buch der Lehre und legt es neben die Bundeslade des Herrn, eures Gottes! Dort sei es als Zeuge gegen dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Denn ich kenne deine Widerspenstigkeit und Halsstarrigkeit. Jetzt, wo ich noch unter euch lebe, seid ihr widerspenstig gegen den Herrn. Wie erst nach meinem Tode!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Beruft mir alle Ältesten eurer Stämme und eure Amtleute zu einer Versammlung, daß ich ihnen diese Worte laut verkünde und Himmel und Erde gegen sie zum Zeugen nehme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Denn ich weiß: Nach meinem Tode artet ihr aus und weicht von dem Wege, den ich euch gewiesen. So trifft euch in der Folgezeit das Unglück, wenn ihr tut, was dem Herrn mißfällt, und wenn ihr ihn durch euer Tun erzürnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Und Moses sprach vor der ganzen Gemeinde Israels die Worte dieses Liedes bis zum Schlusse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '\"Ihr Himmel, lauscht! Denn ich will reden. Die Erde höre meines Mundes Aussprüche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Dem Regen gleich ergieße meine Botschaft sich! Wie Tau, so träufle meine Rede, wie Regengüsse auf das junge Grün, wie Regentropfen auf das Gras!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Denn ich verkündige des Herren Ruhm: Gebt unserem Gott die Ehre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Ein Fels ist er; sein Tun ist vollkommen. Denn recht sind alle seine Wege. Er ist ein Gott der Treue, sonder Trug, gerecht und redlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Doch Schweres tut ihm seiner Unkinder Verderbnis, des ganz verkehrten und verdorbenen Geschlechtes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Dürft ihr dem Herrn dies antun, törichtes, unweises Volk? Ist er denn nicht dein Vater, der dich schuf? Er, der dir Dasein und Bestand verlieh?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Gedenke doch der Vorzeit Tage! Betrachte der vergangenen Geschlechter Zeit! Befrage deinen Vater, daß er dir es künde, die Greise unter dir, daß sie dir\'s sagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Als einst der Höchste Völker siedelte, wie er die Menschenkinder sonderte, bestimmte er der Stämme Grenzen genau der Zahl der Söhne Israels gemäß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Ist doch des Herren Teil sein Volk, Jakob sein zugemessen Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Er fand\'s im Wüstenland, am Ort des Grauens und der öden Einsamkeit. Er warb darum und nahm\'s in seine Hut, beschützte es wie seinen Augapfel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Dem Adler gleich, der seine Brut sich auflädt und seine Jungen schwebend trägt, so spannte er die Flügel aus, nahm\'s auf und trug\'s auf seinen Schwingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Der Herr war einzig und allein sein Führer. Ein fremder Gott war nicht mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Er hob es auf des Landes Höhen. Es aß die Früchte des Gefildes. Er ließ es Honig aus dem Felsen saugen und Öl aus hartem Felsgestein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Dickmilch von Kühen, Milch von Ziegen, dazu das Fett von Lämmern und von Widdern, Basansstiere mitsamt dem Nierenfett verzehrtest du, und Traubenblut, ein feuriges Getränke, trankest du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Und Jeschurun ward fett, schlug aus. Du wurdest fett und dick und feist. Und es verstieß den Gott, der es gemacht, verachtete den Felsen seines Heiles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Durch Fremde machten sie ihn eifersüchtig und kränkten ihn durch Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Sie opferten den Dämonen, Ungöttern, den Göttern, die sie nie gekannt, den Neulingen, die jüngst erst aufgekommen, vor denen euren Vätern nicht gegraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Den Fels, der dich erzeugt, verließest du, vergaßest Gott, der dich geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Der Herr erschaute es und zürnte, gekränkt durch seine Söhne, seine Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Er sprach: Vor ihnen berge ich mein Angesicht, will sehen, was ihr Ende wird. Denn ein verlogenes Geschlecht sind sie, sind Kinder ohne Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Sie haben mich durch Ungötter geärgert, durch ihre nichtigen Götzen mich gekränkt. Nun will ich selbst sie durch ein Unvolk ärgern, sie selbst durch eine gottlose Nation erbittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Ein Feuer loht in meiner Nase und lodert bis zu Höllentiefen, versengt das Land und sein Gewächs, es brennt die Grundfesten der Berge an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Erschöpfen will ich dran die Übel und alle meine Pfeile wider sie verbrauchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Von Hungersnot entkräftet, ausgesaugt von Pest und schlimmen Seuchen, sind sie es, auf die ich hetze noch den Zahn der wilden Tiere, mitsamt dem Gifte der im Staube Schleichenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Von außen rafft das Schwert sie hin und drin der Schrecken, den Jüngling und die Jungfrau, den Säugling und den alten Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ich hätte gern gesagt: Ich werde sie zerschlagen und ihr Gedächtnis bei den Menschen tilgen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'befürchtete ich nicht der Feinde Schadenfreude, daß ihre Dränger es verkannten und so sprächen: \'Siegreich ist unsere Hand gewesen, und nicht der Herr hat alles das gewirkt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Ein ratverloren Volk sind sie, und keine Einsicht ist bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Wenn sie nur weise wären, daß sie dies begriffen, so würden sie ihr Ende wohl bedenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Wie könnte einer Tausend jagen und zwei Zehntausende vertreiben, wenn jene nicht ihr Fels verkauft, der Herr sie preisgegeben hätte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Denn nicht wie unser Felsen ist der ihrige, und unsere Feinde selbst sind Schiedsrichter darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Vom Weinstock Sodomas stammt ihr Gewächs und von Gomorrhas Fluren. Gifttrauben ihre Trauben mit gallenbitteren Beeren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Ihr Wein ist Drachengeifer und grauses Natterngift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ist solches nicht bei mir verwahrt, in meinen Schatzkammern versiegelt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mein ist die Rache und Vergeltung, zur Zeit, da wankt ihr Fuß. Nah schon ist ihres Sturzes Tag, und ihre Zukunft eilt herbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Der Herr bestraft sein Volk, doch rächt er sich für seine Diener; er sieht, wie schon die Schuld ist abgezahlt, und doch die Hilfe zögert, auf sich warten läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Er fragt: \'Wo sind nun ihre Götter? Und wo der Fels, bei dem sie Zuflucht suchten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Sie, deren Opferfett sie ehedem verzehrten und deren Opferwein sie tranken, sie mögen aufstehn und euch helfen! Sie mögen euch zum Schirme sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Seht nun, daß ich es bin! Ich bin\'s und kein Gott neben mir. Ich töte und belebe, verwunde wiederum und heile. Und niemand reißt\'s aus meiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Wenn ich zum Himmel meine Hand erhebe und spreche ich: So wahr ich ewig lebe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'und schärfe ich mein blitzend Schwert und lange nach dem Pfeile, dann nehme ich an meinen Drängern Rache, vergelte meinen Hassern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Ich tränke meine Pfeile mit dem Blute, mein Schwert frißt Fleisch. Besudelt ist die Lanze von dem Blute, das aus der Feindeführer Herzen quillt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Sein Volk preist hoch, ihr Völker, daß seiner Knechte Blut er rächt, daß er an seinen Gegnern Rache nimmt, sein Land und Volk entsündigt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Und Moses begann, alle Worte dieses Liedes vor dem Volke vorzutragen, er und Hosea, Nuns Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Als Moses ganz Israel all diese Worte vorgetragen hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'sprach er zu ihnen: \"Richtet euer Herz auf all die Worte, die ich euch heute feierlich einschärfe, daß ihr sie euren Kindern anbefehlet, auf daß sie alle Worte dieser Lehre beachten und tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Denn es ist euch kein leeres Wort, sondern gilt euer Leben. Durch dieses Wort lebt ihr lange in dem Lande, zu dessen Besetzung ihr über den Jordan zieht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Am selben Tage sprach der Herr zu Moses:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '\"Steig auf das Abarimgebirge hier, auf den Berg Nebo im Moablande östlich von Jericho! Besieh das Land Kanaan, das ich den Israeliten zu eigen gebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Dann stirb auf dem Berge, den du bestiegen! Und komm so zu deinen Stammesgenossen, wie dein Bruder Aaron auf dem Berge Hor gestorben und zu seinen Stammesgenossen gekommen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Ihr habt an mir übel getan inmitten der Söhne Israels beim Haderwasser von Kades in der Wüste Sin, weil ihr mich nicht gerechtfertigt habt bei den Söhnen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Nur von gegenüber darfst du das Land schauen, aber nicht in das Land kommen, das ich den Söhnen Israels gebe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Dies ist der Segen, mit dem Moses, der Mann Gottes, die Söhne Israels vor seinem Tode gesegnet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Er sprach: \"Vom Sinai kam her der Herr, erstrahlte ihnen von Seïr. Er glänzte auf von Pharans Bergen und kam von Kades\' Randgebieten, des Haderwassers Randgebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ja, Freund des Volkes! Bei dir sind alle seine heiligen Geheimnisse; sie sind dir anvertraut; man lernt von deinen Weisungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Die Lehre hat uns Moses übergeben zum Erbe der Gemeinde Jakobs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Ein König wurde er in Jeschurun, als sich des Volkes Häupter sammelten, in eins die Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Es lebe Ruhen, sterbe nimmer aus! Doch seine Wichte seien gezählt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Dies sprach er über Juda: \"Auf Judas Stimme höre, Herr! Zu seinem Volke bringe ihn! Kampfscharen hat er eine Menge, und Du bist Hilfe wider seine Dränger.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Über Levi sprach er: \"Der Dir geweihte Mann hat Deine heiligen Lose, er, den Du einst zu Massa prüftest, auszanktest an dem Haderwasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Er aber sprach von Vater und von Mutter: \'Ich kenne diese nicht\', der seine Brüder nicht mehr ansah und seine Kinder nicht mehr kannte. Sie hielten sich an Dein Gebot und wahrten Deinen Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Sie lehrten Jakob Deine Rechte und Deine Lehre Israel. Sie legen Rauchwerk vor Dein Angesicht, auf Deinen Altar Ganzopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Herr! Segne seinen Wohlstand! Laß seiner Hände Tun Dir wohlgefallen! Zerschmettere die Lenden seiner Gegner, daß seine Hasser nimmer sich erheben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Über Benjamin sprach er: \"In Ruhe wohnt durch ihn des Herren Liebling; er schützt ihn allezeit, wohnt er doch zwischen seinen Schultern! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Über Joseph sprach er: \"Sein Land sei von dem Herrn gesegnet! das Köstlichste vom Himmel droben und drunten von der Wasserflut sei ihm zuteil!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Das Köstlichste, was je die Sonne lockt und was die Monde sprossen lassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'das Beste, was die Ahnen hatten, das Köstlichste der alten Hirten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'das Köstlichste des Bodens, seiner Fülle: die Gnade dessen, der im Dornbusch wohnt, es komme auf das Haupt des Joseph, auf des Geweihten Scheitel unter seinen Brüdern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Sein Erstgeborner, stiergleich, habe Hoheit, und Wildstierhörner seien seine Hörner! Mit ihnen stoße er die Völker nieder bis zu der Erde Enden allzumal! Das sind des Ephraim Zehntausende und des Manasse Tausende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Über Zabulon sprach er: \"Erfreue dich an deinen Fahrten, Zabulon, und deinen Zelten, Issakar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Mit Völkern in dem Bergland stoßen sie zusammen; sie opfern Siegesopfer dort. Sie schleppen fort der Meere Schätze und fremder Küsten Abgaben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Über Gad sprach er: \"Gepriesen ist der herdenreiche Gad. Er lagert wie ein Löwe, zerschmettert Speer und Schild und Helm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Und er ersah sich einen Edelsitz; denn er zerteilte eines Feindesfürsten Land. Des Volkes Häupter feuerte er an und tat mit Israel, was recht dem Herrn und billig war.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Und über Dan sprach er: \"Dan ist ein Löwenjunges, das sich aus Basan gut versorgt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Und über Naphtali sprach er: \"Zufrieden satt ist Naphtali, des Herren Segens voll, wenn er See und Südland sich zu eigen nimmt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Und über Asser sprach er: \"Der Söhne meistgesegneter sei Asser! Er sei der Liebling seiner Brüder! Er bade seinen Fuß in Öl! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Dein Schutz ist Erz und Eisen, und deine Waffen sind dein Stolz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Wie Jeschuruns Gott, gibt es keinen. Er fuhr am Himmel hin in seiner Hoheit in den Wolken, als deine Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Bis jetzt war Gott voll Liebe, gütig gegen seine Treuen. Er hat den Feind vor dir verjagt und hat gesagt: Vertilge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Er läßt im Sichern wohnen Israel, unnahbar Jakobs Quell in einem Land voll Korn und Wein; sein Himmel träufelt Tau.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Heil dir, du Israel! Wer ist wie du? Ein Volk, so siegreich durch den Herrn! Er ist der Schild, der dich beschützt, und er das Schwert, das Siege dir erkämpft. Vor dir sich beugen deine Feinde, du schreitest über ihre Höhen hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Moses stieg aus Moabs Steppen auf den Berg Nebo, auf die Spitze des Pisga, Jericho gegenüber. Da zeigte ihm der Herr das ganze Land, Gilead bis Dan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'ganz Naphtali und das Gebiet Ephraims und Manasses sowie das ganze Gebiet Judas bis zum Westmeer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'das Südland und die Au, die Ebene der Palmenstadt Jericho bis nach Soar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Und der Herr sprach zu ihm: \"Das ist das Land, das ich dem Abraham, Isaak und Jakob zugeschworen mit den Worten: \'Ich gebe es deinen Nachkommen.\' Ich lasse es dich nur schauen; aber hinüber darfst du nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Also starb des Herrn Diener Moses, dort im Lande Moab nach des Herrn Befehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Er begrub ihn im Tale im Lande Moab, Bet Peor gegenüber. Aber niemand kennt sein Grab bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Moses war hundertzwanzig Jahre alt, als er starb. Sein Auge war nicht getrübt, und seine Frische nicht geschwunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Die Söhne Israels beweinten Moses in Moabs Steppen dreißig Tage. Erst dann war die Zeit des Weinens und Klagens um Moses voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Josue ward nun vom Geist der Weisheit erfüllt; denn Moses hatte ihm seine Hände aufgelegt. Die Israeliten gehorchten ihm und taten, wie der Herr dem Moses geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Seitdem ist in Israel kein Prophet mehr erstanden wie Moses, mit dem der Herr von Angesicht zu Angesicht verkehrt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'mit all den Zeichen und Wundem, die zu tun der Herr ihn nach Ägypterland sandte, zu Pharao und all seinen Dienern und seinem ganzen Lande,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'und mit all der starken Macht und mit all dem großen Furchtbaren, das Moses vor den Augen von ganz Israel gewirkt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Und nach dem Tode Mosis, des Dieners des Herrn, sprach der Herr zu Josue, Nuns Sohn und Mosis Diener, also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '\"Mein Diener Moses ist tot. Auf! Ziehe hier über den Jordan, du und dieses ganze Volk, in das Land, das ich den Söhnen Israels gebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Wie ich Moses versprochen, gebe ich euch jeden Platz, den euer Fuß betritt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Hier von der Wüste und dem Libanon bis zum großen Strom, dem Euphratstrom, bis zum ganzen Chittiterland und bis zum großen Meer im Westen erstreckt sich euer Reich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Vor dir hält niemand stand, solange du lebst. Wie ich mit Moses gewesen bin, bin ich mit dir. Ich lasse dich nicht und verlasse dich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sei stark und fest! Denn du sollst dieses Volk in das Land führen, das ihnen zu geben ich ihren Vätern zugeschworen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Nur sei stark und fest entschlossen, darauf zu achten, ganz nach der Lehre zu tun, die dir mein Diener Moses geboten! Weiche nicht davon ab, weder nach rechts noch nach links, daß du Glück habest in allem, woran du gehst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Dies Buch der Lehre soll nie von deinem Munde weichen! Sinne darüber Tag und Nacht, daß du mit Vorbedacht ganz nach dem, was darin geschrieben, handelst! Dann führst du deinen Weg durch und hast Glück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Habe ich dir nicht geboten: Sei mutig und entschlossen? Zage nicht und zittere nicht! Mit dir ist der Herr, dein Gott, überall, wo du gehst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Da gebot Josue den Amtleuten des Volkes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '\"Schreitet durch das Lager und gebietet dem Volke: \'Besorgt euch Zehrung! Denn nach drei Tagen zieht ihr hier über den Jordan, und besetzt das Land, das der Herr, euer Gott, euch zu eigen gibt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Zu den Rubeniten aber, zu den Gaditen und dem Halbstamme Manasse sprach Josue:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '\"Gedenket dessen, was euch der Diener des Herrn, Moses, geboten mit den Worten: \'Der Herr, euer Gott, hat euch an euer Ziel gebracht und euch dies Land gegeben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Eure Weiber, eure kleinen Kinder und euer Vieh mögen in dem Lande bleiben, das Moses diesseits des Jordan euch gegeben hat. Ihr aber, alle Wehrtüchtigen, sollt geordnet euren Brüdern voranschreiten! So helft ihnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'bis der Herr eure Brüder an ihr Ziel bringt wie euch und auch sie das Land besetzen, das der Herr, euer Gott, ihnen geben will! Dann kehrt in euer eigenes Land zurück und besetzt es, das euch der Diener des Herrn, Moses, diesseits des Jordan im Osten gegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Da antworteten sie Josue: \"Alles, was du uns heißest, wollen wir tun, und wohin du uns schickst, gehen wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Wie wir auf Moses gehört, so wollen wir auch auf dich hören. Nur möge der Herr, dein Gott, mit dir sein, wie er mit Moses gewesen\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Wer deiner Weisung widerspricht und nicht auf deine Worte hört, was du ihm irgendwie gebietest, der sei des Todes! Sei nur mutig und entschlossen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Und Josue, Nuns Sohn, sandte von Sittim heimlich zwei Männer aus als Kundschafter und sprach: \"Geht! Beseht die Gegend, besonders Jericho!\" Sie gingen und kamen zum Hause einer Wirtin namens Rachab. Hier kehrten sie ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Da ward dem König von Jericho gemeldet: \"Heute nacht sind Männer von den Söhnen Israels hierher gekommen, das Land auszuspähen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Da sandte Jerichos König zu Rachab und ließ sagen: \"Gib die Männer heraus, die zu dir gekommen und dein Haus betreten haben! Sie sind nur gekommen, die ganze Gegend auszuspähen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Das Weib aber nahm die beiden Männer und verbarg sie. Dann sprach sie: \"Gewiß! Die Männer sind zu mir gekommen. Aber ich habe nicht gewußt, woher sie waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Um die Zeit des Torschlusses, beim Dunkelwerden, sind die Männer fortgegangen. Ich weiß nicht, wohin die Männer gegangen sind. Jagt ihnen schnell nach! Dann könnt ihr sie einholen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sie hatte sie aber aufs Dach geführt und unter Flachsstengeln versteckt, die sie auf dem Dache ausgebreitet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Die Männer aber jagten ihnen nach, dem Jordan zu, an die Furten. Das Tor schloß man zu, sobald ihre Verfolger draußen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Sie hatten sich aber noch nicht hingelegt, da kam sie zu ihnen auf das Dach');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'und sprach zu den Männern: Ich weiß: Der Herr gibt euch das Land. Der Schrecken vor euch hat uns befallen, und alle Insassen des Landes zagen vor euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Denn wir haben gehört, wie der Herr das Wasser des Schilfmeeres vor euch ausgetrocknet hat bei eurem Auszug aus Ägypten und was ihr den beiden Amoriterkönigen jenseits des Jordan getan, Sichon und Og, wie ihr sie gebannt habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Wir hörten dies; da verzagte unser Herz, und in niemandem hat sich ein Mut wider euch geregt. Denn der Herr, euer Gott, ist droben im Himmel und auf Erden unten Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Und nun schwört mir beim Herrn, daß ihr auch dem Hause meines Vaters Gutes tun wollt, wie ich euch Gutes getan! Gebt mir ein Zeichen der Gewähr dafür,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'daß ihr meinen Vater, meine Mutter, meine Brüder und Schwestern und all die Ihrigen leben lasset und unser Leben vom Tode rettet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Da sprachen die Männer zu ihr: \"Wir bürgen mit unserem eigenen Leben für das eurige, wenn ihr diese unsere Verabredung nicht verratet. Gibt uns der Herr das Land, dann wollen wir dir in Treue Gutes tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Sie ließ sie darauf an einem Seil durchs Fenster hinab. Denn ihr Haus war in die Stadtmauer eingebaut, und so wohnte sie an der Stadtmauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Sie sprach zu ihnen: \"Geht ins Gebirge, daß die Verfolger euch nicht treffen! Verbergt euch dort drei Tage, bis die Verfolger heimgekehrt sind! Dann geht eures Weges!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Da sprachen die Männer zu ihr: \"Wir wollen frei von deinem Eidfluche bleiben, den du uns hast aussprechen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Kommen wir in das Land, so sollst du die rote Tuchfahne hier an das Fenster knüpfen, durch das du uns heruntergelassen, und Vater, Mutter, Brüder und dein ganzes Vaterhaus zu dir ins Haus nehmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Wer dann vor die Tür deines Hauses auf die Straße geht, dessen Blut fällt auf sein Haupt. Wir aber sind schuldfrei. Legt aber jemand Hand an irgendeinen, der bei dir im Hause ist, dann fällt sein Blut auf unser Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Verrätst du aber unsere Verabredung, so sind wir deines Eidfluches frei, den du uns hast aussprechen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Sie sprach: \"So sei es, wie ihr sagt!\" Sie entließ sie, und sie gingen weg. Sie aber band die rote Fahne an das Fenster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Sie gingen nun weg und kamen ins Gebirge. Dort blieben sie drei Tage, bis die Verfolger zurück waren. Die Verfolger aber hatten den Weg überall abgesucht, aber sie nicht gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Dann stiegen die beiden Männer wieder vom Gebirge herab, setzten über und kamen zu Josue, Nuns Sohn. Und sie erzählten ihm alles, was ihnen begegnet war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Sie sprachen zu Josue: \"Wahrhaftig! Der Herr gibt uns das ganze Land die Hand; denn alle Insassen des Landes haben Angst vor uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Und Josue stand frühmorgens auf; da zogen sie von Sittim ab. Sie kamen dann an den Jordan, er und alle Israeliten, und sie nächtigten dort, bevor sie übersetzten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Nach drei Tagen gingen die Amtsleute durch das Lager');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'und befahlen dem Volke: \"Seht ihr die Bundeslade des Herrn, eures Gottes, von den levitischen Priestern getragen, dann sollt ihr von eurem Standorte abziehen! Und folgt ihr nach -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'nur sei zwischen euch und ihr ein Raum von etwa zweitausend Ellen! Kommt aber nicht näher -an sie -, damit ihr den Weg wisset, den ihr gehen sollt! Denn ihr seid ihn bisher noch nie gegangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Da sprach Josue zu dem Volke: \"Haltet euch rein! Denn morgen wirkt der Herr euch Wunder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Zu den Priestern aber sprach Josue: \"Nehmt die Bundeslade und schreitet dem Volke voran!\" Da nahmen sie die Bundeslade und zogen dem Volke voran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Da sprach der Herr zu Josue: \"Heute beginne ich, dich in den Augen von ganz Israel zu verherrlichen, damit sie daran erkennen, daß ich mit dir bin, wie ich mit Moses gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Du sollst nun den Priestern, den Trägern der Bundeslade, befehlen: \'Kommt ihr zum Rande des Jordanwassers, dann sollt ihr am Jordan stehenbleiben!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Und Josue sprach zu den Israeliten: \"Tretet her und höret das Vorhaben des Herrn, eures Gottes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Und Josue sprach: \"Daran sollt ihr erkennen, daß in eurer Mitte ein lebendiger Gott ist und daß er vor euch vertreibt die Kanaaniter, Chittiter, Chiwiter, Periziter, Girgasiter, Amoriter und Jebusiter:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Die Bundeslade des Herrn der ganzen Erde zieht vor euch durch den Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Wählt euch inzwischen zwölf Männer aus Israels Stämmen, je einen Mann aus einem Stamm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Sobald die Füße der Priester, der Träger der Lade des Herrn, des Herrn der ganzen Erde, in das Jordanwasser tauchen, wird das Wasser des Jordan verschwinden; das Wasser aber, das von oben fließt, wird dastehen wie ein Wall.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Das Volk zog nun aus seinen Zelten, den Jordan zu überschreiten. Vor dem Volke die Priester, die Träger der Bundeslade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Wie die Träger der Lade an den Jordan kamen und die Füße der Priester, der Träger der Lade, kaum ins Wasser tauchten - der Jordan aber war voll in all seinen Nebenflüssen während der ganzen Erntezeit -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'da stand das Wasser, das von oben floß, hatte es sich doch wie ein Wall erhoben, in großer Weite bei der Stadt Adam seitwärts von Saretan. Das Wasser aber, das zu dem Steppenmeere, dem Salzmeere floß, verschwand völlig. So zog das Volk hinüber auf Jericho zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Die Priester, die Träger der Bundeslade des Herrn, standen im Trockenen genau in der Mitte des Jordan, während ganz Israel im Trockenen hinüberzog, bis das ganze Volk den Jordan vollends überschritten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Sobald das ganze Volk den Jordan vollends überschritten hatte, sprach der Herr zu Josue:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '\"Wählt euch aus dem Volke zwölf Männer, je einen Mann aus einem Stamme,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'und weiset sie also an: \'Nehmt euch zwölf Steine von hier, gerade aus des Jordans Mitte, von diesem Platz, auf dem der Priester Füße stehen, schafft sie mit euch hinüber und legt sie an den Ort, wo ihr heute nächtigen wollt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Da berief Josue die zwölf Männer, die er aus den Israeliten bestellt hatte, je einen Mann aus einem Stamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Und Josue sprach zu ihnen: \"Geht vor die Lade des Herrn, eures Gottes, mitten in den Jordan und ladet euch jeder einen Stein auf seine Schulter nach der Zahl der Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Dies sei ein Merkzeichen unter euch! Fragen später eure Kinder: \'Was bedeuten euch diese Steine?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'dann sagt ihnen: \'Sie bedeuten, daß das Jordanwasser vor der Bundeslade des Herrn verschwunden ist, als sie in den Jordan kam. Das Wasser des Jordan ist verschwunden, und diese Steine dienen den Israeliten zum ewigen Gedenken.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Die Israeliten taten so, wie Josue befahl. Sie nahmen zwölf Steine mitten aus dem Jordan, wie der Herr zu Josue gesagt, nach der Zahl der israelitischen Stämme, schafften sie mit sich in das Nachtlager hinüber und legten sie dort nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Zwölf andere Steine hatte Josue mitten im Jordan niederlegen lassen an der Stelle, wo die Füße der Priester stehen sollten, der Träger der Bundeslade. Sie blieben dort bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Die Priester aber, die Träger der Lade, standen mitten im Jordan, bis alles ausgeführt war, was der Herr den Josue geheißen hatte, dem Volke zu sagen, gemäß dem Befehle Mosis an Josue. Das Volk aber zog rasch hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Erst als das ganze Volk vollends hinüber war, zog auch die Lade des Herrn hinüber, und die Priester stellten sich an die Spitze des Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Die Rubeniten, die Gaditen und der Halbstamm Manasse zogen geordnet vor den Israeliten hinüber, wie ihnen Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'An 40.000 kriegsbereite Männer zogen vor dem Herrn nach Jerichos Steppe in den Kampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'An jenem Tage hatte der Herr den Josue verherrlicht in ganz Israels Augen, und sie fürchteten ihn sein Leben lang, wie sie Moses gefürchtet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Der Herr aber sprach zu Josue:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '\"Befiehl den Priestern, den Trägern der Lade des Zeugnisses, sie sollen aus dem Jordan steigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Da befahl Josue den Priestern: \"Steigt aus dem Jordan!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'So stiegen die Priester, die Träger der Bundeslade des Herrn, aus dem Jordanbett. Kaum aber berührten der Priester Fußsohlen das Trockene, so nahm das Wasser des Jordan wieder den natürlichen Lauf und trat wie vorher über all seine Ufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Das Volk aber stieg am zehnten Tage des ersten Monats aus dem Jordan und lagerte im Gilgal an Jerichos Ostgrenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Jene zwölf Steine aber, die sie aus dem Jordan genommen, stellte Josue im Gilgal auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Er sprach zu den Israeliten: \"Fragen später eure Kinder ihre Väter: \'Was bedeuten diese Steine?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'so Iehret eure Kinder: \'Israel ist hier trockenen Fußes über den Jordan gezogen\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'weil der Herr, euer Gott, das Jordanwasser vor euch hatte vertrocknen lassen, bis ihr hinüber waret, wie der Herr, euer Gott, mit dem Schilfmeer getan, das er vor uns vertrocknen ließ, bis wir hinüber waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'damit alle Völker der Erde einsehen, daß des Herrn Hand stark ist, und daß sie so den Herrn, euren Gott, allzeit fürchten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Sobald die Amoriterkönige alle jenseits des Jordan im Westen und alle Kanaaniter am Meere hörten, wie der Herr das Wasser des Jordan vor den Israeliten hatte vertrocknen lassen, bis sie hinüber waren, verzagte ihr Herz, und sie hatten keinen Mut mehr gegen die Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'In jener Zeit gebot der Herr dem Josue: \"Mach dir Steinmesser! Beschneide zum zweitenmal die Söhne Israels!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Da machte sich Josue Steinmesser und beschnitt die Israeliten wieder an der Spitze der Glieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Dies war der Grund, weshalb Josue beschnitten hatte: Das ganze Volk, das aus Ägypten zog, die Männer, alle Kriegsleute, waren unterwegs in der Wüste gestorben nach ihrem Auszuge aus Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Denn das ganze Volk, das aus Ägypten auszog, war beschnitten gewesen. Dagegen hatte man niemand von dem Volke beschnitten, das nach dem Auszug aus Ägypten unterwegs in der Wüste geboren ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Denn vierzig Jahre zogen die Israeliten in der Wüste umher, bis das ganze Geschlecht weggestorben war, die Kriegsleute, die aus Ägypten gezogen, aber des Herrn Weisung nicht gehorcht hatten und denen der Herr geschworen, daß er sie das Land nicht sehen lasse, das uns zu geben der Herr ihren Vätern zugeschworen, ein Land von Milch und Honig fließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Ihre Söhne aber hatte er an ihrer Statt aufkommen lassen, und sie hatte Josue beschnitten. Denn sie waren unbeschnitten gewesen, weil man sie unterwegs nicht beschnitten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Als alles Volk zu Ende beschnitten war, blieben sie an ihrer Stelle im Lager bis zu ihrer Genesung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Und der Herr sprach zu Josue: \"Heute habe ich Ägyptens Schande von euch gewälzt.\" Daher heißt der Ort Gilgal bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Die Israeliten lagerten im Gilgal, und sie hielten am vierzehnten Tage des Monats am Abend in Jerichos Steppe das Passah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Sie aßen am nächsten Tage nach dem Passah von den Früchten des Bodens, ungesäuerte Brote und geröstetes Korn noch am selben Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Am nächsten Tage aber blieb das Manna aus, als sie von den Früchten des Bodens aßen. Für die Israeliten gab es kein Manna mehr. So aßen sie in jenem Jahr von dem Ertrag des Landes Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Als aber Josue bei Jericho war, schaute er auf. Da sah er sich gegenüber einem Mann mit gezücktem Schwert in der Hand. Josue ging auf ihn zu und sprach zu ihm: \"Bist du für uns oder für unsere Feinde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Er sprach: \"Nein! Ich bin der Führer der Kriegsschar des Herrn. Eigens bin ich gekommen.\" Da fiel Josue auf sein Antlitz zur Erde, huldigte und fragte ihn. \"Was hat mein Herr seinem Sklaven zu sagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Da sprach der Anführer der Kriegsschar des Herrn zu Josue: \"Zieh deine Schuhe aus! Denn heilig ist der Ort, worauf du stehst.\" Und Josue tat so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho aber war eine Sperrfestung. Nun wurde es von den Israeliten eingeschlossen. Und niemand konnte aus noch ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Da sprach der Herr zu Josue: \"Jetzt gebe ich Jericho in deine Hand nebst seinem König und den Kriegern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Zieht um die Stadt, ihr Streiter all! Zieht einmal um die Stadt! So sollst du sechs Tage tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Und sieben Priester sollen sieben Lärmhörner vor der Lade tragen! Am siebten Tage sollt ihr siebenmal um die Stadt ziehen, und die Priester sollen in die Hörner stoßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Wenn das Lärmhorn anhaltend ertönt und wenn ihr den Hörnerschall hört, dann soll das ganze Volk ein gewaltiges Geschrei erheben! Dann stürzt die Stadtmauer in sich zusammen, und das Volk kann einziehen, jeder, wo er steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Josue, Nuns Sohn, berief nun die Priester und sprach zu ihnen: \"Tragt die Bundeslade! Sieben Priester sollen sieben Lärmhörner vor des Herrn Lade tragen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Und sie sprachen zum Volke: \"Zieht rings um die Stadt! Die Vorhut soll vor des Herrn Lade herziehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Es geschah, wie Josue zum Volke gesagt hatte. Die sieben Priester, die die sieben Lärmhörner vor dem Herrn trugen, zogen einher und stießen in die Hörner, und die Bundeslade des Herrn kam hinter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Die Vorhut aber ging vor den in die Hörner stoßenden Priestern, und die Nachhut ging hinter der Lade, fort und fort in die Hörner stoßend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Dem Volke aber gebot Josue: \"Ihr sollt nicht lärmen und eure Stimme nicht hören lassen! Kein Laut soll aus eurem Mund kommen, bis ich euch sage: \'Schreit!\' Dann erhebt das Kriegsgeschrei!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'So ließ er die Lade des Herrn einmal rings um die Stadt gehen. Dann gingen sie ins Lager und nächtigten im Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Josue aber stand früh am Morgen auf; da nahmen die Priester die Lade des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Die sieben Priester, die Träger der sieben Lärmhörner vor des Herrn Lade, zogen hin und stießen fort und fort in die Hörner. Die Vorhut ging vor ihnen her, und die Nachhut folgte der Lade des Herrn, fort und fort in die Hörner stoßend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Sie zogen auch am zweiten Tage einmal um die Stadt und kehrten dann ins Lager zurück. So taten sie sechs Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Am siebten Tage aber erhoben sie sich bei Anbruch der Morgenröte und zogen nach dieser Ordnung siebenmal um die Stadt. Nur an diesem Tage umzogen sie siebenmal die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Beim siebtenmal stießen die Priester in die Hörner, und Josue rief dem Volke zu: \"Macht ein Geschrei! Denn der Herr gibt die Stadt in eure Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Die Stadt aber und alles, was darin ist, sei dem Herrn gebannt! Nur die Wirtin Rachab soll am Leben bleiben nebst allen, die bei ihr im Hause sind! Denn sie hat die Boten versteckt, die wir gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Hütet euch aber vor dem Banngut, daß ihr es nicht verschiebt und von dem Banngut nehmt! Ihr brächtet damit das Lager Israels in den Bann und stürztet es ins Unglück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Alles Silber und Gold, alles eherne und eiserne Gerät sei dem Herrn geweiht! In den Schatz des Herrn soll es kommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Da erhob das Volk ein Geschrei, und sie stießen in die Hörner. Als das Volk nämlich den Hörnerschall vernahm, erhob das Volk ein gewaltiges Geschrei. Da stürzte die Mauer in sich zusammen. Und das Volk zog in die Stadt, wo jeder gerade stand. So nahmen sie die Stadt ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Und sie bannten alles in der Stadt, Mann und Weib, jung und alt, Rinder, Schafe und Esel mit des Schwertes Schärfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Den beiden Männern aber, die die Gegend erforscht hatten, hatte Josue gesagt: \"Geht in das Haus jener Wirtin und holt das Weib mit all den Seinigen von da heraus, wie ihr ihr geschworen habt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Da gingen die jungen Männer, die Kundschafter, hin und führten Rachab, ihren Vater, ihre Mutter, ihre Brüder und all die Ihrigen heraus. Ihre ganze Sippe führten sie heraus; dann brachten sie diese außerhalb des Lagers Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Die Stadt aber und alles, was darin, steckten sie in Brand. Nur das Silber und Gold, die ehernen und eisernen Geräte gaben sie in den Schatz des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Die Wirtin Rachab aber, ihr Vaterhaus und all die Ihrigen hatte Josue leben lassen. Und so blieb sie unter den Israeliten bis auf diesen Tag, weil sie die Boten versteckt hatte, die Josue gesandt, Jericho auszuspähen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Zu jener Zeit aber sprach Josue den Fluch aus: \"Verflucht sei vor dem Herrn der Mann, der es wagt, diese Stadt Jericho wiederaufzubauen! Auf seinen Erstgeborenen soll er sie gründen und auf seinen Jüngsten ihre Pforten setzen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Und der Herr war mit Josue, und sein Ruf ging durch das ganze Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Die Israeliten aber vergriffen sich am Banngut. Achan nämlich, Karmis Sohn und Zabdis Enkel und Urenkel Zerachs, vom Stamme Juda, nahm vom Banngut. Da entbrannte des Herrn Zorn über die Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Nun sandte Josue Männer von Jericho nach Ai bei Bet Awen östlich von Betel. Er befahl ihnen: \"Geht hinauf und erkundet die Gegend!\" Und die Männer gingen hinauf und erkundeten Ai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Dann kehrten sie zu Josue zurück und berichteten ihm: \"Nicht das ganze Volk braucht hinaufzuziehen. Zwei- oder dreitausend Mann mögen hinziehen, Ai zu erobern. Bemühe nicht das ganze Volk dorthin! Denn ihrer sind wenige.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Da zogen vom Volke an dreitausend Mann dorthin. Aber sie flohen vor Ais Leuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Die Leute von Ai erschlugen an sechsunddreißig Mann, verfolgten sie vor dem Tore bis zu den Steinbrüchen und schlugen sie am Abhang. Da zerfloß das Herz des Volkes und ward zu Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Josue aber zerriß seine Kleider und warf sich auf sein Antlitz zu Boden vor des Herrn Lade bis zum Abend, er und Israels Älteste, und sie streuten Staub auf ihr Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Und Josue sprach: \"Ach Herr, Herr! Warum hast Du dies Volk aber den Jordan geführt, wenn Du uns den Amoritem zur Vernichtung preisgeben willst? Wären wir lieber jenseits des Jordan geblieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Bitte, Herr! Was soll ich sagen, nachdem Israel seinen Feinden den Rücken gezeigt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Hören dies die Kanaaniter und alle anderen Insassen des Landes, so kreisen sie uns ein und tilgen unseren Namen aus der Welt. Was willst Du für Deinen großen Namen tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Da sprach der Herr zu Josue: \"Steh auf! Wozu liegst du auf deinem Angesicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Gesündigt hat Israel, ja, meinen Bund übertreten, den ich ihnen auferlegt habe. Ja, genommen haben sie vom Banngut, ja, gestohlen, ja, verhehlt, ja, unter ihre Geräte getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'So können die Söhne Israels vor ihren Feinden nicht mehr standhalten. Den Rücken werden sie den Feinden zeigen, sind sie doch dem Banne verfallen. Ich werde künftig nicht mit euch sein, wenn ihr nicht den Bann aus eurer Mitte tilget.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Auf! Bereite das Volk zur Reinigung! Verkünde: \'Sorgt dafür, daß ihr morgen rein seid! Denn also spricht der Herr, Gott Israels: Etwas Gebanntes ist bei dir, Israel! Du kannst vor deinen Feinden nicht mehr standhalten, bis ihr das Banngut aus eurer Mitte tilgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Tretet morgen stammweise an! Der Stamm, den der Herr herausgreift, soll sippenweise antreten, und die Sippe, die der Herr herausgreift, familienweise! Von der Familie, die der Herr herausgreift, sollen die Männer einzeln antreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Wer aber mit dem Gebannten getroffen wird, den soll man mit all seiner Habe verbrennen! Er hat ja den Bund des Herrn übertreten und Schändliches in Israel getan.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Und Josue ließ am anderen Morgen früh Israel stammweise herantreten. Da wurde der Stamm Juda herausgegriffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Darauf ließ er Judas Sippen antreten. Da wurde die Sippe der Zerachiter getroffen. Dann ließ er die Sippe der Zerachiter Mann für Mann antreten. Da ward Zabdi getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Hierauf ließ er seine Familie Mann für Mann antreten. Da ward Achan, Karmis Sohn, Enkel Zabdis und Urenkel Zerachs, aus dem Stamme Juda getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Da sprach Josue zu Achan: \"Mein Sohn! Gib dem Herrn, dem Gott Israels, Ehre und gib ihm Lob! Sage mir, was du getan! Verhehle mir nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Da erwiderte Achan dem Josue und sprach: \"Wahrhaftig! Ich habe gegen den Herrn, den Gott Israels, gesündigt. Das und das habe ich getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Ich sah unter der Beute einen schönen Mantel aus Sinear, zweihundert Ring Silber und eine Goldzunge, fünfzig Ringe schwer. Mich gelüstete danach, und ich nahm sie. Sie liegen in meinem Zelt im Boden vergraben, das Silber darunter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Da sandte Josue Boten, und sie liefen in das Zelt. Wirklich war es in seinem Zelt vergraben, das Silber darunter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Sie nahmen die Sachen aus dem Zelt, brachten sie zu Josue und allen Israeliten und legten sie vor dem Herrn hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Da nahm Josue Achan, Zerachs Sohn, das Geld, den Mantel und die Goldzunge, seine Söhne, seine Töchter, seine Rinder, Esel und Schafe, sein Zelt und all das Seine, und ganz Israel zog mit ihm, und sie brachten sie in das Tal Achor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Dort sprach Josue: \"Warum hast du uns ins Unglück gebracht? Dafür bringe dich der Herr jetzt ins Unglück.\" Da steinigte ihn ganz Israel. Und sie verbrannten ihn und bewarfen ihn mit Steinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Dann errichteten sie über ihm einen großen Steinhaufen, der noch heute da ist. Und der Herr ließ von seinem heftigen Zorne. Daher heißt jene Stätte Achortal bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Da sprach der Herr zu Josue: \"Sei ohne Furcht und zage nicht! Nimm alles Kriegsvolk mit dir! Auf! Zieh gegen Ai hinauf! Siehe! Ich gebe Ais König, sein Volk, seine Stadt und sein Land in deine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Tu mit Ai und seinem König, wie du mit Jericho und seinem König getan! Doch dürft ihr seine Beute und sein Vieh euch aneignen. Lege der Stadt einen Hinterhalt auf ihrer Westseite!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Da erhob sich Josue mit allem Kriegsvolk, gegen Ai zu ziehen. Und Josue wählte nun dreißigtausend Mann aus, tapfere Leute, sandte sie des Nachts ab');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'und befahl ihnen: \"Seht, daß ihr euch gegen die Stadt in einen Hinterhalt legt, westlich der Stadt! Nicht zu weit von der Stadt! Seid alle bereit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ich und alles Volk bei mir rücken gegen die Stadt. Kommen sie heraus, uns entgegen, wie zuvor, so fliehen wir vor ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Ziehen sie uns nach, dann locken wir sie von der Stadt fort, weil sie denken: \'Sie fliehen vor uns, wie zuvor.\' Während wir vor ihnen fliehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'sollt ihr euch aus dem Hinterhalte erheben! Dann besetzt die Stadt! Der Herr, euer Gott, gibt sie in eure Hand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Habt ihr die Stadt genommen, dann sollt ihr Feuer an die Stadt legen! So sollt ihr nach des Herrn Wort tun! Seht! Das befehle ich euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Und Josue schickte sie ab, und sie legten sich in den Hinterhalt zwischen Betel und Ai, westlich von Ai. Josue aber nächtigte damals unter dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Am anderen Morgen früh musterte Josue das Volk. Dann zog er mit den Ältesten Israels vor dem Volke nach Ai hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Und alles Kriegsvolk bei ihm zog hinauf. So kamen sie nahe bis vor die Stadt und lagerten nördlich von Ai, das Tal zwischen ihnen und Ai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Dann nahm er an fünftausend Mann und legte sie in den Hinterhalt zwischen Betel und Ai, westlich der Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Und sie stellten das Volk, das ganze Heer, in eine Höhle nördlich der Stadt und seine Nachhut westlich davon. In jener Nacht nächtigte Josue mitten in dem Talgrund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Als dies der König von Ai sah, eilten die Leute der Stadt in der Frühe wider Israel zum Kampfe, er und sein ganzes Volk zeitig gegen die Steppe zu. Er aber wußte nicht, daß ihm westlich der Stadt ein Hinterhalt drohte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josue und ganz Israel ließen sich nun von ihnen schlagen und flohen der Wüste zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Da ward alles Volk in der Stadt aufgeboten, sie zu verfolgen. Und sie verfolgten Josue und ließen sich von der Stadt fortlocken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Zu Ai und Betel war kein Mann mehr übriggeblieben, der nicht hinter Israel hergezogen wäre. Die Stadt aber ließen sie offen und verfolgten Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Da sprach der Herr zu Josue: \"Recke den Speer in deiner Hand gegen Ai! Ich gebe es in deine Hand.\" Da reckte Josue den Speer in seiner Hand gegen die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Der Hinterhalt aber hatte sich eilends von seinem Platz erhoben, sobald er die Hand ausstreckte; dann drang er in die Stadt ein, besetzte sie und zündete eilends die Stadt an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Die Leute von Ai aber wandten sich um. Da sahen sie, wie der Rauch der Stadt zum Himmel stieg. Da hatten sie keinen Raum mehr, hierhin oder dorthin zu fliehen. Denn das zur Wüste geflohene Israel hatte sich gegen den Verfolger gewandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Als aber Josue und ganz Israel sahen, daß der Hinterhalt die Stadt erobert hatte und daß der Rauch der Stadt aufstieg, machten sie kehrt und schlugen Ais Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Die anderen aber waren ihnen von der Stadt entgegengezogen. So bekam Israel sie in die Mitte, die einen vor sich, die anderen hinter sich. Und sie schlugen sie, daß von ihnen kein Entronnener und kein Flüchtling mehr übrigblieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Den König von Ai aber ergriffen sie lebendig; dann führten sie ihn vor Josue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Und Israel erschlug alle Insassen Ais im Felde, in der Steppe, wohin sie sie verfolgt hatten. So fielen alle vollzählig durch des Schwertes Schärfe. Dann wandte sich ganz Israel gegen Ai und schlug es mit des Schwertes Schärfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Aller, die an jenem Tage fielen, Männer und Weiber, waren es zwölftausend, sämtlich Leute von Ai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josue aber hatte seine Hand, ausgereckt mit dem Speere, nicht eingezogen, bis er alle Bewohner Ais gebannt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Nur das Vieh und die Beute dieser Stadt nahm Israel für sich, nach dem Worte des Herrn, der so dem Josue geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Und Josue verbrannte Ai und machte es zum ewigen Schutthügel, zur Öde bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Den König von Ai aber hängte er bis zum Abend an den Pfahl. Erst nach Sonnenuntergang ließ Josue seinen Leichnam vom Pfahl nehmen. Dann warf man ihn vor den Eingang des Stadttores und errichtete darüber einen großen Steinhaufen, bis auf den heutigen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Damals baute Josue dem Herrn, Israels Gott, auf dem Berg Ebal einen Altar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'wie Moses, des Herrn Diener, den Israeliten befohlen und wie es im Buche der Lehre Mosis geschrieben steht, einen Altar aus unbehauenen Steinen, über die man mit keinem Eisen gefahren. Sie brachten darauf dem Herrn Brandopfer dar und schlachteten Mahlopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Auf die Steine schrieb er dort eine Abschrift der Lehre Mosis, der sie den Söhnen Israels vorgeschrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Ganz Israel mit seinen Ältesten, Amtsleuten und Richtern stand zu beiden Seiten der Lade, den levitischen Priestern gegenüber, den Trägern der Bundeslade des Herrn, Fremde und Einheimische, die eine Hälfte gegen den Berg Garizim, die andere gegen den Berg Ebal hin, wie des Herrn Diener, Moses, zur Segnung des Volkes befohlen hatte. Dies war das Erste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Hernach las er alle Worte der Lehre vor, den Segen und den Fluch, ganz wie im Buche der Lehre geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Kein Wort von all dem, was Moses geboten, gab es, das Josue nicht der ganzen Gemeinde Israel vorgelesen hätte, auch den Weibern, Kindern und den mit ihnen zugezogenen Fremden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Als davon alle Könige jenseits des Jordan hörten, auf dem Gebirge und in der Niederung, an der ganzen Küste des großen Meeres gegen den Libanon, die Chittiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'vereinigten sie sich, um einmütig gegen Josue und Israel zu kämpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Auch Gibeons Einwohner hörten, was Josue an Jericho und Ai getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Da handelten auch sie, aber listig. Sie gingen und versahen sich mit Reisekost, nahmen aber alte Säcke auf ihre Esel und alte, zermürbte und geflickte Weinschläuche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Sie zogen auch alte geflickte Schuhe an und alte Kleider, und ihr Brot für die Reise war hart und zerkrümelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'So gingen sie zu Josue in das Lager im Gilgal und sprachen zu ihm und den Männern Israels: \"Wir kommen aus fernem Lande. Schließt mit uns ein Bündnis!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Da sprachen die israelitischen Männer zu dem Anführer: \"Vielleicht wohnst du in unserer Nähe? Wie könnten wir mit dir ein Bündnis schließen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Da sprachen sie zu Josue: \"Wir sind deine Sklaven.\" Da fragte sie Josue: \"Wer seid ihr und woher kommt ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Sie sprachen zu ihm: \"Deine Sklaven kommen aus fernstem Lande, auf den Ruhm des Herrn, deines Gottes, hin. Denn wir haben gerüchtweise gehört von ihm und von allem, was er in Ägypten getan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'und alles, was er an den beiden Amoriterkönigen jenseits des Jordan getan, an Chesbons König Sichon und an Og, dem Basankönig zu Astarot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Da sagten unsere Ältesten und unseres Landes Insassen alle zu uns: Nehmt Zehrung auf den Weg mit! Geht ihnen entgegen und sprecht zu ihnen: \'Wir sind eure Sklaven!\' Und nun schließt mit uns ein Bündnis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'So ist es mit unserem Brote. Noch warm haben wir es zu Hause für die Reise mitgenommen, als wir zu euch ziehen wollten. Nun ist es hart und zerkrümelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Die Weinschläuche da sind neu gewesen, als wir sie gefüllt haben. Nun sind sie geborsten. Unsere Kleider und Schuhe da sind durch die weite Reise abgenutzt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Da beurteilten die Männer sie nach ihrer Zehrung; aber den Mund des Herrn hatten sie nicht befragt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'So machte Josue mit ihnen Freundschaft und schloß mit ihnen ein Bündnis, sie leben zu lassen. Und die Fürsten der Gemeinde schwuren ihnen dies zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Drei Tage nach Abschluß des Bündnisses aber hörte man, sie seien aus der Nähe, und zwar ganz nahe bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Da brachen die Israeliten auf und kamen am dritten Tage zu ihren Städten. Ihre Städte waren Gibeon, Kephira, Beerot und Kirjat-Jearim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Die Israeliten aber schlugen sie nicht, weil ihnen die Fürsten der Gemeinde beim Herrn, Israels Gott, dies zugeschworen hatten. Da murrte die Gemeinde wider die Fürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Da sagten alle Fürsten zur Gesamtgemeinde: \"Wir haben ihnen beim Herrn, Israels Gott, geschworen: somit dürfen wir sie nicht antasten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Das aber wollen wir an ihnen tun: Wir wollen ihnen das Leben schenken, damit nicht ein Zorn über uns komme wegen des Eides, den wir ihnen geschworen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Und so sprachen die Fürsten von ihnen: \"Sie sollen am Leben bleiben; jedoch für die ganze Gemeinde Holzhauer und Wasserträger werden, wie ihnen die Fürsten vorgeschlagen hatten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Und Josue berief sie und sprach zu ihnen: \"Warum habt ihr uns betrogen mit den Worten: \'Wir wohnen sehr weit von euch\', und ihr wohnt doch in unserer Nähe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Nun seid ihr verflucht. Nicht soll es bei euch an Sklaven, Holzhauern und Wasserträgem für meines Gottes Haus mangeln!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Da antworteten sie Josue und sprachen: \"Deinen Sklaven ist berichtet worden, was der Herr, dein Gott, seinem Diener Moses geboten, ihr sollet alle Insassen des Landes vor euch vertilgen, wenn er euch das ganze Land gebe. Da fürchteten wir von euch um unser Leben und taten so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Nun sind wir in deiner Hand. Tu mit uns, wie es dir gut und recht dünkt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Da tat er mit ihnen so und schützte sie vor den Israeliten, und so haben sie sie nicht umgebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Damals machte sie Josue zu Holzhauern und Wasserträgern für die Gemeinde und für den Altar des Herrn, für die Stätte, die er erwählen würde, bis zu diesem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Der König von Jerusalem nun, Adonisedek, hörte, daß Josue Ai erobert und es gebannt habe. Wie er Jericho und seinem König getan, so habe er auch Ai und seinem König getan, und Gibeons Einwohner hätten mit Israel Frieden geschlossen und gehörten zu ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Da fürchteten sie sich sehr. Denn Gibeon war eine große Stadt wie irgendeine Reichsstadt. Sie war größer als Ai, und alle ihre Männer waren tapfere Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Da sandte Jerusalems König Adonisedek zu Hebrons König, Hoham, zu dem von Jarmut, Piram, zu dem von Lachis, Japhia, und zu Eglons König, Debir, und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '\"Zieht zu mir herauf und helft mir! Wir wollen Gibeon schlagen dafür, daß es mit Josue und den Israeliten Frieden geschlossen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Da taten sich die fünf Amoriterkönige zusammen und zogen heran, der König von Jerusalem, der von Hebron, der von Jarmut, der von Lachis und der von Eglon, mit ihren ganzen Heeren. Und sie lagerten gegen Gibeon und bestürmten es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Da sandten die Gibeoniter zu Josue ins Lager nach dem Gilgal und ließen sagen: \"Zieh deine Hand nicht von deinen Sklaven! Komm schnell zu uns und hilf uns! Denn alle Amoriterkönige auf dem Gebirge scharen sich wider uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Da zog Josue mit dem ganzen Kriegsvolk, lauter tapferen Männern, vom Gilgal aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Und der Herr sprach zu Josue: \"Hab keine Furcht vor ihnen! Ich gebe sie in deine Hand. Nicht einer von ihnen hält dir stand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Und Josue überfiel sie plötzlich. Denn er war die ganze Nacht vom Gilgal heraufgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Und der Herr verwirrte sie vor Israel, und dieses schlug sie bei Gibeon schwer, verfolgte sie gegen die Steige von Bet Choron und schlug sie bis Azeka und Makeda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Als sie, vor Israel fliehend, auf dem Abhang von Bet Choron waren, warf der Herr auf sie große Steine vom Himmel bis nach Azeka, daß sie starben. Und durch Hagelsteine starben mehr, als die Israeliten mit dem Schwert umgebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Damals sprach Josue zum Herrn an dem Tage, da der Herr die Amoriter den Israeliten preisgab. Er sprach in der Israeliten Gegenwart: \"Sonne, steh still zu Gibeon; du Mond, im Tale Ajalon!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Und still stand der Lauf des Mondes und der Sonne, bis über seine Feinde ein Volk den Sieg gewonnen. Steht es nicht so geschrieben im Buche des Richtigen? Die Sonne stand still mitten am Himmel und eilte nicht unterzugehen, den ganzen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Wie dieser Tag ist keiner zuvor noch nachher gewesen, daß der Herr der Stimme eines Menschen gefolgt hätte. Denn der Herr hatte für Israel gestritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Dann kehrte Josue mit ganz Israel ins Lager zurück nach dem Gilgal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Jene fünf Könige aber flohen und versteckten sich in der Höhle bei Makeda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Da ward Josue gemeldet: \"Die fünf Könige hat man in der Höhle bei Makeda versteckt gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Da befahl Josue: \"Wälzt große Steine vor den Eingang der Höhle und stellt Männer als Wache dabei auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ihr anderen aber bleibt nicht stehen! Verfolgt eure Feinde! Vernichtet ihre Nachhut! Laßt sie nicht in ihre Städte kommen! Denn der Herr, euer Gott, gibt sie in eure Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'So schlugen Josue und die Israeliten sie sehr schwer bis zur Vernichtung. Einige von ihnen aber waren entkommen, und sie gelangten in die festen Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Das ganze Volk kehrte nun zu Josue ins Lager nach Makeda unangefochten zurück. Niemand wagte es, gegen Israel auch nur leise etwas zu sagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Da befahl Josue: \"Öffnet den Höhleneingang und bringt mir aus der Höhle jene fünf Könige!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Sie taten so und brachten ihm jene fünf Könige aus der Höhle, den König von Jerusalem, den von Hebron, den von Jarmut, den von Lachis und den von Eglon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Als man jene Könige zu Josue brachte, rief Josue alle Männer Israels herbei und sprach zu den Obersten der Kriegsleute, die mit ihm gezogen: \"Kommt heran und setzt diesen Königen den Fuß auf den Nacken.\" Da kamen sie heran und setzten ihnen den Fuß auf den Nacken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Und Josue sprach zu ihnen: \"Seid ohne Furcht und unverzagt! Seid fest und mutig! So tut der Herr mit all euren Feinden, gegen die ihr streitet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Hierauf schlug sie Josue und tötete sie. Dann hängte er sie an fünf Pfähle. Und sie hingen an den Pfählen bis zum Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Gegen Sonnenuntergang befahl Josue, sie von den Pfählen zu nehmen. Man warf sie in die Höhle, in der sie sich versteckt hatten. Dann legte man große Steine vor der Höhle Eingang, bis zu diesem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Und Makeda eroberte Josue am gleichen Tage; er schlug es samt seinem König mit des Schwertes Schärfe. Er hatte sie gebannt und alle anderen Menschen darin. Er hatte keinen einzigen übriggelassen. Und mit Makedas König tat er so, wie er mit Jerichos König getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Und Josue zog mit ganz Israel von Makeda nach Libna und stritt wider Libna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Der Herr gab auch dieses samt dem König in Israels Hand, und Israel schlug es mit des Schwertes Schärfe, sowie alle anderen Leute darin. Keinen einzigen hat es übriggelassen. Und mit seinem Könige tat es so, wie es mit Jerichos König getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Und Josue zog mit ganz Israel von Libna nach Lachis, lagerte davor und stritt dawider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Und der Herr gab Lachis in Israels Hand. Es nahm es am zweiten Tage ein und schlug es mit des Schwertes Schärfe, sowie alle anderen Menschen darin, ganz so, wie es bei Libna getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Damals zog Gezers König, Horam, heran, Lachis zu helfen. Aber Josue schlug ihn und sein Volk so, daß von ihm niemand übrigblieb, der hätte entrinnen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Und Josue zog mit ganz Israel von Lachis nach Eglon. Sie lagerten davor und stritten dawider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Sie nahmen es am selben Tag und schlugen es mit des Schwertes Schärfe, und alle Leute darin bannten sie an jenem Tage, ganz so, wie sie bei Lachis getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Und Josue zog mit ganz Israel von Eglon nach Hebron hinauf, und sie stritten dawider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Sie nahmen es und schlugen es mit des Schwertes Schärfe, auch den König und alle seine Städte und alle Leute darin. Keinen einzigen haben sie entkommen lassen, ganz so, wie sie bei Eglon getan. Die Stadt und alle Leute darin bannten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Dann wandte sich Josue mit ganz Israel gegen Debir und griff es an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Er nahm es samt seinem König und alle seine Städte. Sie schlugen sie mit des Schwertes Schärfe und bannten alle Leute darin. Keinen einzigen hatte er entkommen lassen. Wie er mit Hebron getan und wie mit Libna und seinem König, so tat er mit Debir und seinem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'So bezwang Josue das ganze Land, das Bergland, das Südland, die Niederung und das Hügelland mit all ihren Königen. Keinen hatte er entkommen lassen. Alles Lebende hatte er gebannt, wie der Herr, Israels Gott, befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Und Josue bezwang sie von Kades Barnea bis Gaza und das ganze Land Gosen bis Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Alle jene Könige und ihr Land nahm Josue auf einmal. Denn der Herr, Israels Gott, hatte für Israel gestritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Hierauf kehrten Josue und ganz Israel ins Lager nach dem Gilgal zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Als aber Jabin, der König von Chasor, davon hörte, sandte er zu Madons König, Johab, zum König von Simron und zum König von Achsaph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'sowie zu den Königen im Norden, im Bergland, in der Steppe südlich von Kinerot, in der Niederung und auf dem Höhenzug von Dor am Meere,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'zu den Kanaanitern im Osten und Westen, den Amoritern, Chittitern, Perizitern und Jebusitern auf dem Gebirge und zu den Chiwitern am Fuße des Hermon im Lande der Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Sie zogen mit all ihren Heeren aus, ein starkes Volk, zahlreich wie der Sand am Meeresstrande, und mit sehr viel Rossen und Wagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Und alle Könige kamen einhellig zusammen und lagerten insgesamt beim Wasser von Merom, wider Israel zu streiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Aber der Herr sprach zu Josue: \"Furchte dich nicht vor ihnen! Morgen um diese Zeit lege ich sie alle erschlagen vor Israel hin. Ihre Rosse sollst du lähmen und ihre Streitwagen verbrennen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Da kam Josue mit dem ganzen Kriegsvolk unvermutet über sie beim Wasser von Merom, und sie überfielen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Und der Herr gab sie in Israels Hand. Sie schlugen sie und verfolgten sie bis Groß-Sidon und bis Misrephot Maim sowie bis in die Talebene von Mispa im Osten. Und sie schlugen sie. Keinen einzigen von ihnen hat er entkommen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Josue tat an ihnen, wie ihm der Herr gesagt. Ihre Rosse lähmte er und verbrannte ihre Streitwagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Dann kehrte Josue um und eroberte Chasor. Seinen König aber hatte er mit dem Schwerte geschlagen. Chasor war vordem die Vormacht aller jener Königreiche gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Und sie schlugen darin alle Leute mit des Schwertes Schärfe und bannten sie. Kein Hauch war mehr übriggeblieben. Chasor selbst hatte er verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'All jene Königsstädte mit all ihren Königen nahm Josue und schlug sie mit des Schwertes Schärfe, hatte er sie doch gebannt, wie es des Herrn Diener, Moses, befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Aber von all den Städten, die auf ihrem Hügel saßen, verbrannte Israel keine; allein Chasor hatte Josue verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Die Israeliten aber nahmen die ganze Beute aus jenen Städten und das Vieh für sich. Nur die Menschen alle hatten sie mit des Schwertes Schärfe bis zur Vernichtung geschlagen. Keinen Hauch hatten sie übriggelassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Wie der Herr seinem Diener Moses befohlen, so hatte dieser dem Josue geboten, und so hatte Josue getan. Nichts unterließ er von allem, was der Herr dem Moses geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'So eroberte Josue dieses ganze Land, das Bergland, das ganze Südland, das ganze Land Gosen, die Niederung und die Steppe sowie das Bergland von Israel und seine Niederung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'vom kahlen Gebirge an, das gegen Seïr ansteigt, bis Baal Gad in der Libanonebene am Fuß des Hermon. Alle ihre Könige hatte er gefangen; dann schlug er sie und tötete sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Lange Zeit führte Josue mit all jenen Königen Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Keine Stadt ergab sich den Israeliten friedlich, außer die zu Gibeon wohnenden Chiwiter. Sonst hatten sie alles durch Kampf genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Denn vom Herrn war es gefügt worden, ihr Herz zu verstocken zum Kampfe gegen Israel, daß man sie bannte, damit ihnen keine Schonung zuteil würde, sondern Ausrottung, wie der Herr dem Moses befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Damals kam Josue und vertilgte die Enakiter auf dem Gebirge, zu Hebron, Debir und Anab, auf dem ganzen Gebirge Juda und Israel. Sie und ihre Städte hatte Josue gebannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'So blieben keine Enakiter mehr im Lande der Israeliten. Nur in Gaza, Gat und Asdod blieb ihrer ein Rest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Josue nahm das ganze Land, wie es der Herr dem Moses geboten. Und Josue gab es Israel zu eigen nach ihrer Stammeseinteilung. Und das Land ruhte vom Kriege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Dies sind des Landes Könige, die die Israeliten geschlagen und deren Land sie eingenommen haben: Jenseits des Jordan im Osten vom Arnonflusse bis zum Hermongebirge und die ganze Steppe im Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Der Amoriterkönig Sichon, der zu Chesbon wohnte und der das Land beherrschte von Aroër am Ufer des Arnonflusses an und die Mitte des Tales sowie die eine Hälfte Gileads bis zum Jabbokfluß, die Grenze der Ammoniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'sowie die Steppe bis zum See Genesareth im Osten und bis zum Meer der Steppe, dem Salzmeer, im Osten gegen Bet Hajesimot und südlich am Fuße der Zusammenflüsse des Pisga');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'und das Uferland. Ferner der König von Basan, Og, der zu den Rephaiterresten gehörte und zu Astarot und Edreï wohnte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'und herrschte über das Hermongebirge, Salka und ganz Basan bis zur Grenze der Gesuriter und Maakatiter sowie über Gileads andere Hälfte bis zu dem Gebiete Sichons, des Königs von Chesbon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Des Herrn Diener, Moses, und die Israeliten hatten sie besiegt, und Moses, des Herrn Diener, hatte es den Rubeniten, Gaditen und dem Halbstamm Manasse zu eigen gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Dies sind des Landes Könige, die Josue und die Israeliten jenseits des Jordan besiegt haben, westlich von Baal Gad im Libanontale bis zum glatten, gegen Seïr ansteigenden Gebirge, und das Josue den Stämmen Israels nach ihren Abteilungen zu eigen gab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'auf dem Gebirge, in der Niederung, in der Steppe, an den Zusammenflüssen, in der Wüste und im Südland, das Land der Chittiter, Amoriter, Kanaaniter, Periziter, Chiwiter und Jebusiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Ein König von Jericho, einer von Ai neben Betel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'einer von Jerusalem, einer von Hebron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'einer von Jarmut, einer von Lachis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'einer von Eglon, einer von Gezer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'einer von Debir, einer von Geder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'einer von Chorma, einer von Arad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'einer von Libna, einer von Adullam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'einer von Makeda, einer von Betel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'einer von Tappuach, einer von Chepher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'einer von Aphek, einer von Saron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'einer von Madon, einer von Chasor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'einer von Simron Meron, einer von Achsaph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'einer von Taanak, einer von Megiddo,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'einer von Kedes, einer von Jokneam am Karmel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'einer von Dor bei Naphat Dor, einer von den Heiden im Gilgal,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'einer von Tirsa; zusammen 31 Könige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Als Josue alt und hochbetagt war, sprach der Herr zu ihm: \"Du bist jetzt alt und hochbetagt. Noch aber bleibt ein großer Teil des Landes zu erobern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Dies ist das Gebiet, das noch fehlt: alle Philisterbezirke und das ganze Gesur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Von dem Sichor östlich von Ägypten bis zur Nordgrenze Ekrons, das zum Gebiet der Kanaaniter gerechnet wird: die fünf Fürsten der Philister, der von Gaza, der von Asdod, der von Askalon, der von Gat und der von Ekron, dazu die Awiter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'im Süden, das ganze Kanaaniterland und die sidonische Höhle bis Aphek und bis an die Amoritergrenze');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'und das giblitische Land, sodann der ganze Libanon im Osten, von Baal Gad am Fuße des Hermongebirges bis ganz Chamat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Alle Gebirgsbewohner vom Libanon bis Misrephot Maim, sämtliche Sidonier. Ich selbst vertreibe sie vor den Israeliten. Verlose es an Israel zum Erbbesitz, wie ich dir befohlen habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Verteile nun dies Land als Erbbesitz an die neun Stämme und an den Halbstamm Manasse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Mit ihm haben die Rubeniten und Gaditen ihren Erbbesitz erhalten, den ihnen Moses jenseits des Jordan angewiesen, wie ihn des Herrn Diener, Moses, ihnen angewiesen hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'von Aroër am Ufer des Arnonflusses und von der Stadt mitten im Tale, dazu die ganze Ebene von Medeba bis Dibon');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'sowie alle Städte des Amoriterkönigs Sichon zu Chesbon bis zur Ammonitergrenze,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'ferner Gilead und das Gebiet der Gesuriter und Maakatiter sowie das Hermongebirge und ganz Basan bis Salka,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'das ganze Königreich Ogs zu Basan, der zu Astarot und Edreï herrschte. Dieser war von den Rephaiterresten noch da. Diese besiegte Moses und vertrieb sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Nicht vertrieben haben die Israeliten die Gesuriter und Maakatiter, und so blieben Gesur und Maakat unter Israel bis auf diesen Tag wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Nur dem Levitenstamm hat er kein Erbe gegeben, weil des Herrn, des Gottes Israels, Mähler sein Erbe sind, wie er ihm verheißen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Und Moses gab den Sippen des Rubenitenstammes Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Sie bekamen das Gebiet von Aroër am Ufer des Arnonflusses und die Stadt mitten im Tal, dazu die ganze Ebene bei Medeba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Chesbon und alle seine Städte in der Ebene, Dibon, Bamot Baal, Bet Baal Meoti,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahsa, Kedemot, Mephaat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjataim, Sibma, Seret Hasachar auf dem Berge der Talebene,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bet Peor, die Zusammenflüsse des Pisga, Bet Hajesimot');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'und alle anderen Städte in der Ebene sowie das ganze Königreich des Amoriterkönigs Sichon, der zu Chesbon herrschte und das Moses besiegthat samt den Midianiterfürsten Ewi, Rekem, Sur, Chur und Reba, den im Lande ansässigen Vasallen Sidions.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Auch den Wahrsager Bileam, Beors Sohn, haben die Israeliten mit dem Schwert getötet wie die anderen, die sie erschlagen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Das Gebiet der Rubeniten ward der Jordan und das Uferland. Das ist der Erbbesitz der einzelnen Rubenitensippen, die Städte und ihre Dörfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Moses begabte auch den Stamm Gad, die einzelnen Sippen der Gaditen, und zwar erhielten sie folgendes Gebiet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Jazer, alle Städte Gileads und die Hälfte des Ammoniterlandes bis Aroër östlich von Rabba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'und zwar von Chesbon bis Ramat Hamispe und Betonim sowie von Machanaim bis zum Gebiet von Debir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'ferner in der Talebene Bet Haram, Bet Nimra, Sukkot und Saphon, den Rest des Königreiches Sichons, des Königs von Chesbon, mit dem Jordan und dem Uferland bis zum Ende des Genesarethsees, jenseits, östlich des Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Das ist der Erbbesitz der einzelnen Gaditensippen, die Städte und ihre Dörfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Moses gab auch dem Halbstamm Manasse Land. Die einzelnen Sippen des Halbstammes Manasse erhielten folgendes Gebiet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Ihr Gebiet umfaßte von Machanaim ganz Basan, das ganze Königreich des Basankönigs Og, und sämtliche Zeltdörfer Jairs in Basan, sechzig Städte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'dazu halb Gilead, sowie Astarot und Edreï, die Städte des Königreichs Og in Basan. Dies bekamen die Söhne Makirs, des Manassesohnes, und zwar die einzelnen Sippen der einen Hälfte der Makirsöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Das ist es, was Moses in Moabs Steppen, jenseits, östlich des Jordan bei Jericho, zu eigen gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Dem Levitenstamm hat Moses kein Erbe gegeben; der Herr, Israels Gott, ist ihr Erbe, wie er ihnen verheißen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Dies ist es, was die Israeliten im Lande Kanaan zu eigen bekommen und was ihnen der Priester EIeazar, Josue, Nuns Sohn, und die Stammeshäupter der israelitischen Stämme');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'durch das Los als ihren Erbbesitz verteilt haben, wie der Herr dem Moses für die neuneinhalb Stämme befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Denn den zweieinhalb Stämmen hatte Moses jenseits des Jordan ihren Erbbesitz gegeben, den Leviten aber keinen unter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Denn die Josephsöhne waren zwei Stämme, Manasse und Ephraim. Aber den Leviten hat man im Lande kein Teil gegeben, außer Städte zum Wohnen und ihre Weidetriften für allerhand Herden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Wie der Herr dem Moses befohlen, so haben die Israeliten getan und das Land verteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Da traten die Judäer im Gilgal zu Josue, und der Keniziter Kaleb, Jephunnes Sohn, sprach zu ihm: \"Du kennst das Wort, das der Herr zu Moses, dem Mann Gottes, meiner- und deinetwegen zu Kades Barnea gesprochen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Ich war vierzig Jahre alt, als des Herrn Diener, Moses, mich von Kades Barnea aussandte, das Land zu erforschen. Ich brachte ihm Bescheid, wie es mir ums Herz war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Meine Brüder aber, die mit mir hinaufgezogen, haben das Herz des Volkes verzagt gemacht. Ich aber bin hinter den Herrn, meinen Gott, getreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'An jenem Tage versprach Moses feierlich: \'Wahrlich, dir selbst und deinen Nachkommen sei das Land, das dein Fuß betritt, für immer Erbbesitz; denn du bist hinter den Herrn, meinen Gott, getreten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Nun hat mich der Herr, wie er gesagt, volle fünfundvierzig Jahre leben lassen seit der Zeit, da der Herr dies zu Moses gesagt und da Israel in der Wüste umhergezogen. So bin ich jetzt fünfundachtzig Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Noch immer bin ich so rüstig wie damals, als mich Moses ausgesandt hat. Meine Kraft von heute gleicht meiner Kraft von damals im Kampfe, bei Auszug und Heimkehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'So gib mir jetzt dieses Bergland, von dem der Herr an jenem Tage gesprochen! Denn du hast selbst damals gehört, daß es dort Enakiter mit großen, festen Städten gibt. Vielleicht ist der Herr mit mir, daß ich sie vertreiben kann, wie der Herr versprochen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Da segnete ihn Josue und gab Hebron dem Jephunnesohne Kaleb zum Erbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Deshalb hatte der Keniziter Kaleb, Jephunnes Sohn, Hebron zum Erbe bekommen bis auf diesen Tag, weil er hinter den Herrn, den Gott Israels, getreten war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Hebron hieß vormals die Stadt des Arba; dieser war der bedeutendste Mann bei den Enakitern. Und das Land ruhte vom Kriege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Die Sippen des Judastammes erhielten ihr Los nach der Grenze Edoms hin, südwärts nach der Wüste Sin zu, im äußersten Süden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Ihre Südgrenze beginnt mit dem Ende des Salzmeeres, von der nach Süden gerichteten Zunge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'und geht südlich von der Skorpionensteige hinüber nach Sin und läuft südlich von Kades Barnea aufwärts nach Chesron hinüber. Dann geht sie aufwärts nach Adar und wendet sich nach Karka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Dann geht sie nach Asmon hinüber und geht bis zum Bache Ägyptens, bis die Grenze am Meer endigt. Das sei eure Südgrenze!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Die Ostgrenze ist das Salzmeer bis zur Jordanmündung. Die Nordgrenze beginnt mit der Meereszunge und der Jordanmündung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Dann läuft die Grenze aufwärts nach Bet Chogla und hinüber bis nördlich von Bet Haaraba. Dann läuft die Grenze aufwärts zum Steine Bohans, des Rubensohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Dann zieht sich die Grenze aufwärts nach Debir vom Achortale her und wendet sich nördlich nach dem Gilgal, gegenüber der Steige von Adummim südlich vom Bache. Sodann läuft die Grenze hinüber nach dem Wasser der Sonnenquelle und weiter bis zur Rogelquelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Sodann läuft die Grenze aufwärts ins Tal Ben Hinnom südlich vom Bergrücken der Jebusiter, das ist Jerusalems. Dann läuft die Grenze aufwärts auf den Gipfel des Berges westlich vor dem Hinnomtal und am nördlichen Ende der Rephaimebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Vom Gipfel des Berges biegt die Grenze zur Quelle des Nephtoawassers um und geht zu den Städten des Ephrongebirges. Dann biegt die Grenze nach Baala, das ist Kirjat Jearim, um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Voll Baala wendet sich die Grenze westwärts zum Berge Seïr, läuft hinüber nördlich vom Rücken des Waldberges, das ist Kesalon, zieht sich nach Bet Semes hinab und nach Timna hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Dann geht die Grenze nördlich weiter bis zum Bergrücken von Ekron. Dann biegt die Grenze nach Sikron um, geht hinüber nach dem Berg von Baala und läuft weiter bis Jabneel. So endet die Grenze am Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Die Westgrenze ist das große Meer mit dem Küstenland. Das ist das Gebiet der Judäer ringsum nach ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Dem Jephunnesohn Kaleb aber gab er unter den Judäern ein Teil nach dem Befehle des Herrn an Josue, nämlich die Stadt Arbas, des Enakvaters, das ist Hebron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Und Kaleb vertrieb von da die drei Enaksöhne Sesai, Achiman und Talmai, die Sprößlinge Enaks.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Von dort zog er gegen Debirs Einwohner. Debir hieß früher Kirjat Sepher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Und Kaleb versprach: \"Wer Kirjat Sepher bezwingt und erobert, dem gebe ich meine Tochter Aksa zum Weibe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Und Otniel, der Sohn des Kenaz, des Bruders Kalebs, eroberte es. Da gab er ihm seine Tochter Aksa zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Als sie hinzog, überlistete sie ihren Vater, da sie von ihm ein Feld wollte. Sie neigte sich nämlich vom Esel, so daß Kaleb sie fragte: \"Was ist dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Sie aber sprach: \"Gib mir doch eine Abschiedsgabe! Du vergibst mich ja nach dem Südlande. So gib mir Wasser!\" Da gab er ihr oberirdische und unterirdische Wasserstellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Das ist der Erbbesitz des Stammes der Judäer nach ihren Sippen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Die Städte für den Judäerstamm, alles mitgerechnet, waren gegen Edoms Grenze hin im Südland: Kabseel, Eder, Jagur,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Adada,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Chasor und Jitnan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Chasor Chadatta und Kerijot Chesron, das ist Chazor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Molada,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Chasar Gadda, Chesmon, Bet Pelet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Chasar Sual, Beer Seba und seine Tochterstädte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala Ijim, Esem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Chorma,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmanna, Sansanna,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Silchim, En-Rimmon, zusammen neunundzwanzig Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In der Niederung: Estaol, Sora, Asna,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoach, En Gannim, Tapuach und Enam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adullam, Soko, Azeka,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Aditaim, Gedera und seine Gehöfte; vierzehn Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Chadasa, Migdal Gad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilan, Hamispe, Jokteel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakis, Boskat, Eglon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lachmas, Kitlis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Bet Dagon, Naama und Makeda, sechzehn Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Aasan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiphtach, Asna, Nesib,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Akzib und Maresa, neun Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron mit seinen Ortschaften und Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Von Ekron bis zum Meer alles, was neben Asdod und seinen Dörfern lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod mit seinen Ortschaften und Dörfern, Gaza mit seinen Ortschaften und Dörfern bis zum Bache Ägyptens. Das große Meer bildete die Grenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Auf dem Gebirge: Sanir, Jattir, Soko,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjat Sanna, das ist Debir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Anim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Cholon, Gilo, elf Städte und ihre Dörfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Bet Tappuach, Aphekal,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Chumta, Kirjat Arba, das ist Hebron, und Sior, neun Städte und ihre Gehöfte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Ziph, Juta,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezreel, Jokneam und Zanoach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Hakain, Gibea und Timma, zehn Städte mit ihren Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Chalchul, Bet Sur und Gedor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Bet Anot und Eltekon, sechs Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat Baal, das ist Kirjat Jearim, und Rabba, zwei Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In der Steppe: Bet Haaraba, Middin, Sekaka,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan und die Salzstadt sowie Engeddi, sechs Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Die Jebusiter, Jerusalems Bewohner, hatten die Judäer nicht vertreiben können. Und so blieben die Jebusiter mit den Judäern in Jerusalem bis auf diesen Tag beisammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Das Los der Söhne Josephs ging vom Jordan bei Jericho an Jerichos Gewässern im Osten, gegen die Steppe zu, die von Jericho zum Gebirge Betels hinaufzieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Dann lief die Grenze von Betel, dem alten Luz, nach dem Arkitergebiete nach Atarot hinüber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'senkte sich westlich nach dem Japhletitergebiet bis zum Gebiet des unteren Bet Choron und bis Gezer. Sie endigte am Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Auch Josephs Söhne, Manasse und Ephraim, erhielten Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Das Gebiet der Ephraimiten nach ihren Sippen war folgendes: Im Osten war ihres Erbbesitzes Grenze Aterot Adar bis zum oberen Bet Choron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Dann lief die Grenze bis zum Meer, im Norden nach Mikmetat. Dann wandte sich die Grenze östlich nach Taanat Silo und zog östlich von Janoach vorüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Von Janoach lief sie nach Atarot und Naarat hinab, stieß an Jericho und endete am Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Von Tappuach lief die Grenze westwärts bis zum Kanabach und endete am Meer. Das ist der Erbbesitz des Ephraimitenstammes nach seinen Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Dazu die ephraimitischen Städte, die abgesondert inmitten des Erbbesitzes der Manassiten lagen, sämtliche Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Sie hatten aber die Kanaaniter zu Gezer nicht vertrieben. So blieben die Kanaaniter inmitten Ephraims bis auf diesen Tag und wurden zu dienstbaren Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Auch der Stamm Manasse bekam sein Los; denn er war Josephs Erstgeborener. Dem Erstgeborenen Manasses, Makir, dem Vater Gileads, fielen Gilead und Basan zu; denn er war ein Kriegsmann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Auch die übrigen Nachkommen Manasses erhielten nach ihren Sippen ihr Teil: die Söhne Abiezers, Cheleks, Asriels, Sekems, Chephers und Semidas. Das sind die männlichen Nachkommen Manasses, des Josephsohns, nach ihren Sippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Selophchad, Chephers Sohn und Gileads Enkel, Urenkel des Sohnes Makirs, des Manassesohnes, hatte keine Söhne, sondern nur Töchter. Seine Töchter hießen Machla, Noa, Chogla, Milka und Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Sie traten nun vor den Priester Eleazar und vor Josue, Nuns Sohn, und vor die Fürsten mit den Worten: \"Der Herr hat Moses geheißen, uns unter unseren Brüdern einen Erbbesitz zu geben.\" Da gab er ihnen nach des Herrn Befehl einen Erbbesitz unter ihres Vaters Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'So fielen auf Manasse zehn Teile, abgesehen vom Lande Gilead und Basan, jenseits des Jordan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'weil Manasses Töchter unter seinen Söhnen Erbbesitz erhalten hatten. Das Land Gilead aber fiel den anderen Manassesöhnen zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Manasses Grenze ging von Asser nach Mikmetat östlich von Sichem. Dann lief die Grenze nach rechts zu den Insassen von En Tappuach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Die Landschaft Tappuach gehörte Manasse, Tappuach aber an Manasses Grenze den Ephraimiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Dann lief die Grenze zum Kanabach hinab. Südlich vom Bache gehörte diese Stadt den Ephraimiten inmitten der Manassestädte. Sodann ging die Grenze Manasses nördlich vom Bach und endete am Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Was südwärts lag, gehörte zu Ephraim, was nordwärts, zu Manasse, und das Meer war die Grenze. Im Norden grenzten sie an Asser, im Osten an Issakar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'In Issakar und Asser gehörten zu Manasse Bet Sean mit seinen Dörfern, Ibleam mit den seinigen, die Bewohner Dors mit seinen Dörfern, ebenso die von En Dor mit seinen Dörfern und die von Megiddo mit den seinigen, die drei Höhenzüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Die Manassiten konnten aber die genannten Städte nicht erobern. So bequemten sich die Kanaaniter dazu, in dieser Gegend zu bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Als aber die Israeliten erstarkten, machten sie die Kanaaniter fronpflichtig. Aber ganz vertrieben hatten sie sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Da sprachen die Josephsöhne zu Josue: \"Warum hast du mir nur ein Los und ein Teil zum Erbbesitz gegeben? Und doch habe ich viele Leute, weil mich darin der Herr gesegnet hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Josue sprach zu ihnen: \"Hast du viele Leute, so steige ins Waldgebirge und rode dir dort etwas im Periziter- und Rephaiterlande! Das Gebirge Ephraim ist in eurer Nähe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Da sprachen die Josephsöhne: \"Das Gebirge reicht für uns nicht. Alle Kanaaniter aber, die in der Ebene wohnen, haben eiserne Wagen, so die zu Betsean und die in seinen Dörfern und die in der Jezreelebene wohnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Da sprach Josue zum Josephshause, zu Ephraim und Manasse: \"Du hast viel Leute und große Macht. So bleibt es für dich nicht bei einem Lose.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Ein Bergland wird dir aber von Wert sein, weil es Wald ist. Wenn du ihn rodest, fallen dir seine Einkünfte zu. Du mußt aber auch den Kanaaniter vertreiben, obschon er eiserne Wagen hat und stark ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Die ganze israelitische Gemeinde versammelte sich nun zu Silo. Und dort stellten sie das Festgezelt auf. Das Land aber lag unterworfen vor ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Unter den Israeliten waren aber noch sieben Stämme übrig, die noch keinen Erbbesitz erhalten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Da sprach Josue zu den Israeliten: \"Wie lange zögert ihr noch, hinzugehen und das Land zu besetzen, das euch der Herr, eurer Väter Gott, gegeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Bringet drei Männer aus jedem Stamm, so sende ich sie aus, und sie sollen sich aufmachen, das Land durchziehen und es aufschreiben nach der Größe ihres Besitzes! Dann sollen sie zu mir kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Hierauf sollen sie es in sieben Teile teilen! Juda behält sein Gebiet im Süden, das Josephshaus im Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Ihr aber zeichnet das Land in sieben Teilen auf und berichtet mir hierher! Dann werfe ich hier vor dem Herrn, unserem Gott, das Los für euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Denn die Leviten haben kein Teil bei euch; vielmehr ist des Herrn Priestertum ihr Erbe. Gad aber und Ruben sowie der Halbstamm Manasse haben jenseits, östlich des Jordan ihren Erbbesitz erhalten, den ihnen des Herrn Diener, Moses, angewiesen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Da machten sich die Männer auf und gingen. Die Ausziehenden hieß Josue das Land aufzeichnen, indem er sprach: \"Geht hin! Durchzieht das Land! Zeichnet es auf! Dann kommt wieder zu mir! Ich werfe dann hier vor dem Herrn zu Silo für euch das Los!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Da gingen die Männer, durchzogen das Land und zeichneten es Stadt für Stadt in sieben Teilen in ein Buch. Dann kamen sie zu Josue in das Lager nach Silo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Da warf Josue zu Silo vor dem Herrn für sie das Los. So verteilte Josue dort den Israeliten das Land nach ihren Abteilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Da kam das Los des Stammes der Benjaminsöhne für seine Sippen heraus. Das Gebiet ihres Loses lag zwischen den Judäern und den Josephsöhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Ihre Grenze ging nördlich vom Jordan aus. Dann zog sich die Grenze aufwärts zu dem Bergrücken nördlich von Jericho und weiter hinauf auf das Gebirge nach Westen zu und lief nach der Steppe von Bet Awen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Von da ging die Grenze nach Luz hinüber, auf die Südseite des Bergrückens von Luz, das ist Betel. Dann stieg die Grenze nach Aterot Addar hinab, dann auf den Berg südlich vom unteren Bet Choron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Dann bog die Grenze um und wandte sich auf ihrer Westseite nach Süden, von dem Berg aus, der südlich von Bet Choron liegt, und endete bei Kirjat Baal, das ist die judäische Stadt Kirjat Jearim. Das ist die Westseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Die Südgrenze lief von der Stadtgrenze Kirjat Jearims aus. Dann ging die Grenze westwärts bis zur Quelle des Nephtoachwassers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Dann lief die Grenze hinab bis ans Ende des Berges, östlich vom Ben-Hinnomstal und nördlich der Rephaimebene. Dann lief sie ins Hinnomstal hinab südlich vom Bergrücken der Jebusiter und weiter hinab zur Rogelquelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Dann bog sie nach Norden und lief auf die Quelle von Semes zu. Dann lief sie zu den Gelilot, gegenüber der Steige von Adummim, und zog sich zum Felsen des Rubensohnes Bohan hinab');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'und hinüber zu dem Bergrücken, nördlich der Steppe gegenüber. Dann lief sie in die Steppe hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Dann ging die Grenze hinüber bis nördlich vom Bergrücken von Bet Chogla. Die Grenze endete an der Nordspitze des Salzmeeres, am Südende des Jordan. Das ist die Südgrenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Auf der Ostseite war der Jordan ihre Grenze. Das sind die Grenzen rings um den Erbbesitz der Benjaminitensippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Die Städte der Sippen des Benjaminitenstammes waren: Jericho, Bet Chogla, Kesistal,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bet Haaraba, Semaraim, Betel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Awim, Happara, Ophra,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kephar Haammoni, Haophni und Geba, zwölf Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Harama, Beerot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Hammispe, Hakkephira, Hammosa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Irpeel, Tarala,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Sela, Haeleph und die Jebusiterstadt, das ist Jerusalem, Gibeat und Kirjat Arim,, vierzehn Städte mit ihren Dörfern. Das ist der Erbbesitz der Benjaminitensippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Das zweite Los kam für Simeon heraus, für die Sippen des Stammes der Simeoniten. Ihr Erbbesitz lag mitten im judäischen Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Sie bekamen als Erbbesitz: Beerseba, Sema, Molada,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Chasar Sual, Bala, Esem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Chorma,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Bet Hammarkabot, Chasar Susa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bet Lebaot und Saruchen, dreizehn Städte mit ihren Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Eter und Asan, vier Städte mit ihren Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'dazu all die Dörfer rings um diese Städte bis Baalat Ber, dem Rama des Südlandes. Das ist der Erbbesitz der Sippen des Stammes der Simeoniten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Aus dem judäischen Anteil stammte der Erbbesitz der Simeoniten. Denn das Teil der Judäer war für diese zu groß. So bekamen die Simeoniten ihr Land mitten in deren Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Das dritte Los kam für die Zabuloniten heraus für ihre Sippen. Ihres Erbbesitzes Bereich erstreckte sich bis Sarid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Nach Westen ging ihre Grenze aufwärts nach Marela, berührte Dabbeset und stieß an den Bach östlich von Jokneam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Nach Osten, nach Sonnenaufgang, wandte sie sich von Sarid nach dem Gebiet von Kislot Tabor, lief nach Haddaberat und stieg nach Japhia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Von da ging sie nach Osten gegen Sonnenaufgang hinüber nach Gat Chepher, Et Kasin, lief nach Rimmon und bog nach Hannea um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Dann wandte sich die Grenze herum auf der Nordseite von Chanaton und endete im Tal von Iphtach El.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattat, Naphalal, Simron, Idala und Bethlehem, zwölf Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Das ist der Erbbesitz der Zabulonitensippen: diese Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Für Issakar kam das vierte Los heraus, für die Issakaritensippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Ihr Gebiet erstreckte sich über Jezreel, Hakkesullot, Sunem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Chapharaini, Sion, Anacharat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Harrabbit, Kisjon, Ebes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Reemer, En Gannim, En Chadda und Bet Passes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Die Grenze berührte Tabor, Sachasima und Bet Semes. Ihre Grenze endete am Jordan; sechzehn Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Das ist der Erbbesitz der Sippen des Issakaritenstammes, die Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Das fünfte Los kam für die Sippen des Asseritenstammes heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Ihr Gebiet erstreckte sich über Chelkat, Chali, Beten, Aksaph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Allammelek, Amad und Misal. Es stieß an den Karmel am Meer und an den Sichor von Libna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Dann wandte es sich gen Sonnenaufgang nach Bet Dagon, berührte Zabulon und das Tal Iphtach El im Norden, Bet Haemek und Negiel und ging nordwärts nach Kabul,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebron, Rechob, Chammon und Kana bis zum großen Sidon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Dann wandte sich die Grenze zurück nach Harannt und bis zur festen Stadt Tyrus. Dann wandte sich die Grenze nach Chos und endete am Meer, Machaleb, Akzib,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Akko, Aphek und Rechebot, zweiundzwanzig Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Das ist der Erbbesitz der Sippen des Asseritenstammes: diese Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Für die Naphtaliten kam das sechste Los heraus, für die Naphtalitensippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ihre Grenze lief von Cheleph, von der Eiche bei Saanannim, Adami, Hannekeb und Jabneel bis Lakkum und endete am Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Dann wandte sich die Grenze westwärts nach Aznot Tabor, lief von da nach Chukkok, stieß im Süden an Zabulon, nach Westen an Asser, nach Osten in Juda an den Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Feste Städte waren Hassidim, Ser, Chammat, Rakkat, Kinneret,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adma, Harama, Chasor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edreï, En Chasor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Ireon, Migdal El, Chorem, Bet Anat und Bet Semes, neunzehn Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Das ist der Erbbesitz der Sippen des Naphtalitenstammes: die Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Für die Sippen des Danitenstammes kam das siebente Los heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Der Bereich ihres Erbbesitzes erstreckte sich über Sora, Estaol, Ir Semes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabin, Ajjalon, Itla,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnat, Ekron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibbeton, Baalat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene Berak, Gat Rimmon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me Hajjarkon und Harakkon samt der Küste bei Joppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Das Gebiet der Daniten aber ging ihnen verloren. So zogen die Daniten hinauf und kämpften gegen Lesem, eroberten es und schlugen es mit des Schwertes Schärfe. Sie besetzten es, siedelten darin und nannten es Lesem Dan nach ihres Ahnherrn Dan Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Das ist der Erbbesitz der Sippen des Danitenstammes: diese Städte mit ihren Dörfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'So beendeten sie die Verteilung des Landes nach seiner Ausdehnung. Die Israeliten aber gaben in ihrer Mitte dem Sohne Nuns, Josue, einen Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Nach des Herrn Geheiß hatten sie ihm die Stadt gegeben, die er erbeten hatte. Timnat Zerach auf dem Gebirge Ephraim. Er befestigte die Stadt und siedelte darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Dies sind die Erbteile, die der Priester Eleazar und Nuns Sohn, Josue, mit den Stammhäuptern der israelitischen Männer zu Silo verlost haben vor dem Herrn an des Festgezeltes Pforte. So beendigten sie des Landes Verteilung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Und der Herr redete also mit Josue:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '\"Sprich zu den Söhnen Israels: Bestimmt euch die Zufluchtsstädte, von denen ich durch Moses zu euch gesagt habe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'daß ein Totschläger, der unvorsätzlich, unversehens einen Menschen totschlug, dorthin fliehe! Sie seien euch Zuflucht vor dem Bluträcher!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Er (der Totschläger) fliehe in eine dieser Städte, trete an des Stadttores Eingang und berichte seine Sache den Ältesten der Stadt! Dann sollen sie ihn zu sich in die Stadt nehmen und ihm einen Platz anweisen, und er bleibe bei ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Verfolgt ihn der Bluträcher, so dürfen sie ihm den Totschläger nicht ausliefern, weil er seinen Nächsten unwissentlich getötet und ihn nicht von früher her gehaßt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Er bleibe in dieser Stadt, bis er vor der Gemeinde zum Gerichte gestanden, bis zum Tode des jeweiligen Hohenpriesters! Dann soll der Totschläger heimkehren; er gehe in seine Stadt und sein Haus, in die Stadt, aus der er geflohen ist.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Da bestimmten sie Kedes in Galiläa auf dem Gebirge Naphtali, auf dem Gebirge Ephraim Sichern und Kirjat Arba, das ist Hebron auf dem Gebirge Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Jenseits des Jordan bei Jericho im Osten bestellten sie Beser in der Steppe, auf der Hochebene vom Stamme Ruben, Ramot in Gilead vom Stamme Gad und Golan in Basan vom Stamme Manasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Dies waren die Freistädte für alle Israeliten und die Fremdlinge unter ihnen, daß dorthin alle fliehen sollten, die einen Menschen unvorsätzlich töteten, damit sie nicht durch einen Bluträcher stürben, bevor sie vor der Gemeinde gestanden hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Nun traten die Familienoberhäupter der Leviten zu dem Priester Eleazar und zu Josue, Nuns Sohn, sowie zu den Stammhäuptern der israelitischen Stämme');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'und sprachen zu ihnen in Silo im Lande Kanaan: \"Der Herr hat durch Moses befohlen, uns Städte zu Siedlungen und ihre Weiden für unser Vieh zu geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Da gaben die Israeliten auf des Herrn Befehl von ihrem Erbbesitz den Leviten folgende Städte mit ihren Weiden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Das Los fiel auf die Kehatitensippen, und so erhielten bei den Leviten die Söhne des Priesters Aaron vom Judastamme, vom Simeonitenstamme und vom Stamme Benjamin durch das Los dreizehn Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Die anderen Kehatiten aber erhielten von den Sippen des Ephraimstammes, dem Stamme Dan und von dem Halbstamme Manasse durch das Los zehn Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Die Gersoniten erhielten von den Sippen des Issakarstammes, vom Asserstamme, vom Stamme Naphtali und vom Halbstamme Manasse in Basan durch Los dreizehn Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Die Sippen der Merariten erhielten vom Stamme Ruben, vom Stamme Gad und vom Zabulonstamme zwölf Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Und die Israeliten übergaben den Leviten diese Städte samt ihren Weiden durch das Los, wie der Herr durch Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Vom Stamme der Judasöhne und der Simeoniten trat man diese Städte ab, die man jetzt mit Namen nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Von den Sippen der Kehatiter unter Levis Söhnen bekamen die Aaronsöhne, weil auf sie zuerst das Los fiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'die Stadt Arbas, des Vaters Enaks, das ist Hebron, auf dem Gebirge Juda samt ihren Weiden ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Die Markung der Stadt mit ihren Dörfern aber hatte man Kaleb, Jephunnes Sohn, zu seinem Erbbesitze gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Den Söhnen des Priesters Aaron hatte man Hebron gegeben, die Zufluchtsstadt der Totschläger, samt ihren Weiden, ebenso Libna,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jattir, Estemona,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Cholon, Debir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ajin, Juta, Bet Semes je mit ihren Weiden, neun Städte von seiten jener beiden Stämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Und vom Stamme Benjamin Gibeon samt seinen Weiden, ebenso Geba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot und Almon, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Somit bekamen die Söhne des Priesters Aaron insgesamt dreizehn Städte mit ihren Weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Den Sippen der übrigen levitischen Kehatsöhne wurden ihre Losstädte vom Stamm Ephraim abgetreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Man gab ihnen Sichem als Zufluchtsstadt der Totschläger, mit ihren Weiden auf dem Gebirge Ephraim, ebenso Gezer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsaim und Bet Choron je mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Vom Stamme Dan Elteke, Gibbeton,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjalon und Gat Rimmon je mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Vom Halbstamme Manasse Taanak und Gat Rimmon mit je ihren Weiden, zwei Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Somit bekamen die Sippen der übrigen Kehatsöhne insgesamt zehn Städte Mit ihren Weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Die Gersoniten unter den Levitensippen bekamen vom Halbstamme Manasse Golan als Zufluchtsstadt der Totschläger, in Basan und Astarot, je mit ihren Weiden, zwei Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Vom Issakarstamme Kisjon, Daberat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut und En Gannim je mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Vom Asserstamme Misal, Abdon');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Chelkat und Rechob je mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Vom Naphtalistamme Kedes als Zufluchtsstadt der Totschläger in Galiläa, Chammot Dor und Kartan je mit ihren Weiden, drei Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Somit bekamen die Gersonitensippen insgesamt dreizehn Städte mit ihren Weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Die übrigen levitischen Meraritensippen bekamen vom Zabulonstamme Jokneam, Karta,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna und Nahalal mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Vom Rubenstamme Beser, Jahsa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot und Mephaat je mit ihren Weiden, vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Vom Stamme Gad Ramot als Zufluchtsstadt der Totschläger in Gilead, Machanaim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Chesbon und Jazer je mit ihren Weiden, insgesamt vier Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'So bekamen die von den Levitensippen übrigen Meraritensippen als ihr Los zwölf Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Es waren also achtundvierzig Städte samt ihren Weiden inmitten des israelitischen Erbbesitzes Levitenstädte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Diese Städte bestanden jedesmal aus einer Stadt und ihrer Weide ringsum. So war es bei all diesen Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'So gab der Herr Israel das ganze Land, das zu geben ihren Vätern er zugeschworen. Sie besetzten es und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Und der Herr gab ihnen ringsum Ruhe, wie er ihren Vätern geschworen hatte. Von all ihren Feinden hatte keiner gegen sie standgehalten. Der Herr hatte all ihre Feinde in ihre Hand gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Von all den Verheißungen, die der Herr dem Haus Israel gegeben, war keine ausgeblieben. Alle waren in Erfüllung gegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Damals berief Josue die Rubeniten, die Gaditen und den Halbstamm Manasse');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'und sprach zu ihnen: \"Ihr habt alles befolgt, was euch des Herrn Diener, Moses, befohlen hat. Ihr gehorchtet meiner Stimme in allem, was ich euch geheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Ihr habt eure Brüder diese lange Zeit hindurch nicht verlassen. Bis auf diesen Tag beobachtet ihr treulich die gebieterische Verpflichtung des Herrn, eures Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Nun hat der Herr, euer Gott, euren Brüdern Ruhe verliehen, wie er ihnen verheißen hat. Kehrt nun heim, dahin, wo euer Erbbesitz liegt, den euch des Herrn Diener, Moses, jenseits des Jordan gegeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Nur seid bemüht, das Gebot und die Weisung zu tun, die euch des Herrn Diener, Moses, gegeben. Ihr sollt den Herrn, euren Gott, lieben, immer auf seinen Wegen wandeln, seine Gebote befolgen, ihm anhangen und ihm von ganzem Herzen und aus ganzer Seele dienen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Und Josue segnete und entließ sie. So kehrten sie heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Der einen Hälfte des Manassestammes aber hatte Moses Besitz in Basan gegeben, der anderen Hälfte aber Josue bei ihren Brüdern westlich des Jordan. Auch sie hatte Josue mit Segenswünschen zu ihren Zelten entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Er sprach zu ihnen: \"Kehrt mit viel Schätzen zu euren Zelten zurück, mit sehr viel Herden, mit Silber und Gold, Kupfer und Eisen und Gewändern in großer Menge! Teilet die Beute eurer Feinde mit euren Brüdern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'So kehrten die Rubeniten heim, die Gaditen und der Halbstamm Manasse, und zogen von den Israeliten weg aus Silo im Lande Kanaan. Sie wollten in das Gileadland ziehen, in ihr Erbbesitzland, wo sie nach dem Befehl des Herrn an Moses angesiedelt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'So kamen sie am Jordan zu den Steinkreisen, die im Lande Kanaan waren. Da bauten dort die Rubeniten, Gaditen und der Halbstamm Manasse am Jordan einen weithin sichtbaren Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Da hörten die Israeliten die Kunde, die Rubeniten, Gaditen und der Halbstamm Manasse hätten den Altar gebaut gegenüber dem Lande Kanaan an den Steinkreisen des Jordan jenseits der Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Als die Israeliten dies hörten, versammelte sich die israelitische Gesamtgemeinde zu Silo, jene zu bekriegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Und die Israeliten sandten an die Rubeniten, Gaditen und den Halbstamm Manasse in das Land Gilead den Sohn des Priesters Eleazar, Pinechas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'nebst zehn Fürsten, je einen aus jedem Stamme Israels. Jeder war ein Oberhaupt israelitischer Stammesfamilien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'So kamen sie zu den Rubeniten, Gaditen und dem Halbstamm Manasse ins Land Gilead und sprachen zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '\"So spricht die ganze Gemeinde des Herrn: \'Was bedeutet diese Untreue, die ihr am Gott Israels tut, euch heute vom Herrn abzuwenden, euch heute einen Altar zu bauen und so euch gegen den Herrn zu empören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ist uns der Peorfrevel zu gering? Davon haben wir uns bis heute noch nicht gereinigt, und deshalb kam über die Gemeinde des Herrn die Plage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Und ihr wendet euch heute vom Herrn ab? So ist es: Heute empört ihr euch gegen den Herrn, und Morgen entlädt sich sein Zorn über die ganze Gemeinde Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Ist aber euer Erbbesitzland unrein, dann zieht in das Erbbesitzland des Herrn hinüber, wo des Herrn Wohnung aufgeschlagen ist, und laßt euch bei uns nieder! Doch empört euch nicht gegen den Herrn! Aber auch uns verwickelt nicht in eure Empörung, wenn ihr außer dem Altar des Herrn, unseres Gottes, noch einen anderen bauet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Ist nicht über die ganze Gemeinde ein Zorn gekommen, als sich Akan, Zerachs Sohn, am Banngut vergriffen hatte, und doch war er nur ein einzelner? Hat er nicht seiner Sünde wegen sterben müssen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Da sprachen die Rubeniten, Gaditen und der Halbstamm Manasse zu den Stammeshäuptern Israels:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '\"Beim Gott der Götter, dem Herrn! Der Götter Gott, der Herr, weiß es, und Israel selbst wisse es! Geschah es in Untreue und Empörung, dann hilf uns heute nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Bauten wir einen Altar, um vom Herrn abzufallen und um darauf Brand- und Speiseopfer zu opfern und um darauf Mahlopfer zu machen, dann soll es der Herr selbst ahnden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Ob wir dies nicht aus Sorge vor etwas getan? Wir dachten nämlich, eure Söhne könnten später zu unseren Söhnen sprechen: \'Was geht euch der Herr, Israels Gott, an?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Hat doch der Herr den Jordan zur Grenze zwischen uns und euch gesetzt, ihr Rubeniten und Gaditen. Ihr habt am Herrn kein Teil.\' So könnten eure Söhne die unsrigen so weit bringen, daß sie nicht mehr den Herrn fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Darum sagten wir: \'Wir wollen uns durch den Bau des Altares vorsehen. Nicht für Brand- und Schlachtopfer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sondern zum Zeugen sei er uns und euch und unseren Nachkommen, daß wir vor ihm den Dienst des Herrn tun wollen durch unsere Brand-, Schlacht- und Dankopfer, und daß künftig nicht eure Söhne zu den unsrigen sprechen: \"Ihr habt kein Teil am Herrn.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Wir sagten: \'Sollten sie künftig so zu uns oder unseren Nachkommen sprechen, dann sagen wir: \"Schaut die Bauart des Herrnaltares, den unsere Väter gebaut! Gemacht nicht für Brandopfer noch für Schlachtopfer, sondern nur zum Zeugen für uns und euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Ferne sei es uns, gegen den Herrn uns zu empören und heute vom Herrn abzufallen und für Brand-, Speise- und Schlachtopfer vor seiner Wohnung noch einen anderen Altar zu bauen, außer des Herrn, unseres Gottes, Altar.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Als der Priester Pinechas und die Fürsten der Gemeinde, die Häupter der israelitischen Stämme bei ihm, die Worte hörten, die die Rubeniten, Gaditen und Manassiten redeten, gefiel es ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Und Pinechas, der Sohn des Priesters Eleazar, sprach zu den Rubeniten, Gaditen und Manassiten: \"Heute erfahren wir, daß der Herr in unserer Mitte weilt, weil ihr keine Untreue gegen den Herrn getan. Damit habt ihr die Israeliten vor der Hand des Herrn bewahrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Dann kehrten Pinechas, der Sohn des Priesters Eleazar, und die Fürsten aus dem Lande Gilead von den Rubeniten und Gaditen ins Land Kanaan zu den Israeliten zurück und brachten ihnen Bescheid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Und die Sache gefiel den Israeliten. Da priesen die Israeliten Gott und dachten nicht mehr daran, sie zu bekriegen und das Land, in dem die Rubeniten und Gaditen saßen, zu verwüsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Die Rubeniten und Gaditen aber rühmten von dem Altar: \"Er ist unter uns Zeuge, daß der Herr Gott ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Geraume Zeit, nachdem der Herr Israel vor all seinen Feinden ringsum Ruhe verschafft und Josue alt und hochbetagt geworden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'berief Josue ganz Israel, seine Ältesten, Häupter, Richter und Amtleute und sprach zu ihnen: \"Ich bin alt und hochbetagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Ihr habt alles selbst geschaut, was der Herr, euer Gott, all diesen Völkern euretwegen getan. Denn der Herr, euer Gott, hat selbst für euch gestritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Seht, ich überweise euch diese übriggebliebenen Heidenvölker durchs Los zum Eigentum für eure Stämme, vom Jordan an bis zum großen Meer im Westen, wie all die Heiden, die ich schon ausgerottet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Der Herr, euer Gott, selbst verjagt sie vor euch und vertreibt sie vor euch, daß ihr ihr Land besetzet, wie euch der Herr, euer Gott, verheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So tut euer Möglichstes, zu beachten und zu tun alles, was im Buch der Lehre Mosis geschrieben steht, ohne davon nach rechts oder links zu weichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Geratet nicht unter diese Heidenvölker, die bei euch übrig sind! Die Namen ihrer Götter sollt ihr nicht in den Mund nehmen und nicht bei ihnen schwören! Ihr sollt ihnen nicht dienen und euch nicht davor niederwerfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Dem Herrn, eurem Gott, sollt ihr anhangen, wie ihr es bis heute getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Deshalb vertrieb der Herr vor euch große und starke Heidenvölker, und niemand hielt bis heute vor euch stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Ein Mann von euch jagt tausend vor sich her. Denn der Herr, euer Gott, streitet selbst für euch nach seiner Verheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'So gebt sorgfältig acht - gilt\'s doch euer Leben! -, daß ihr den Herrn, euren Gott, liebet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Denn tut ihr anders und haltet ihr es mit dem Reste dieser Heidenvölker, die bei euch übrig sind, und verschwägert und vermischt ihr euch gegenseitig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'dann wisset, daß der Herr, euer Gott, diese Heidenvölker nicht mehr vor euch vertreiben wird! Sie werden euch dann zur Schlinge und zum Fallstrick, zu Geißeln in euren Seiten und zu Stacheln für eure Augen, bis ihr verdrängt seid aus diesem schönen Lande, das euch der Herr, euer Gott, gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Ich gehe dieser Tage den Weg alles Irdischen. Dann seid von ganzem Herzen und aus ganzer Seele euch bewußt, daß von all den Verheißungen, die der Herr euch gegeben, keine seinerseits ausgeblieben ist! Alle sind für euch in Erfüllung gegangen. Keine davon ist ausgeblieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Aber wie sich alle Verheißungen erfüllt haben, die der Herr, euer Gott, euch gegeben, so wird der Herr auch alle Drohungen an euch erfüllen, bis er euch aus diesem schönen Land verdrängt hat, das euch der Herr, euer Gott, gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Übertretet ihr den Bund, den der Herr, euer Gott, euch geboten, und geht ihr hin, falschen Göttern zu dienen und euch vor ihnen hinzuwerfen, so wird des Herrn Zorn gegen euch entbrennen, und ihr werdet rasch aus dem schönen Land verdrängt, das er euch gegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Josue versammelte nun alle Stämme Israels nach Sichem. Er berief dazu die Ältesten Israels sowie ihre Oberhäupter, Richter und Amtleute, und sie stellten sich vor Gott auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Da sprach Josue zum ganzen Volke: \"So spricht der Herr, Israels Gott: \'In grauer Vorzeit haben eure Ahnen in dem Lande jenseits des Stromes gewohnt, der Vater Abrahams und Nachors, Terach, und sie dienten anderen Göttern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Da wählte ich mir euren Ahnherrn Abraham aus dem Gebiete jenseits des Stromes und führte ihn im ganzen Lande Kanaan umher, vermehrte seinen Stamm und gab ihm Isaak.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Und Isaak schenkte ich Jakob und Esau, und Esau gab ich das Gebirge von Seïr zu eigen. Doch Jakob zog mit seinen Söhnen nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Da sandte ich Moses und Aaron. Und ich schlug Ägypten durch das, was ich darin getan. Dann habe ich euch weggeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Ich führte eure Väter aus Ägypten. Und so kamet ihr an das Meer. Die Ägypter aber verfolgten eure Väter mit Wagen und mit Reitern bis an das Schilfmeer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Da riefen sie zum Herrn. Er aber setzte zwischen euch und die Ägypter tiefe Finsternis und brachte über sie das Meer, daß es sie bedeckte. Und eure Augen sahen, was ich Ägypten getan. Dann weiltet ihr in der Wüste lange Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Hierauf brachte ich euch in das Land der Amoriter, jenseits des Jordan, und diese kämpften gegen euch. Ich aber gab sie in eure Hand. So nahmt ihr ihr Land weg, und ich tilgte sie vor euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Dann trat Balak auf, des Sippors Sohn und Moabs König, und stritt mit Israel. Er sandte hin und ließ Bileam, des Beor Sohn, rufen, euch zu verfluchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Ich aber wollte nicht auf Bileam hören. So gab er euch den Segen, und ich befreite euch aus seiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Dann überschrittet ihr den Jordan und kamt nach Jericho. Da kämpften mit euch die Bürger Jerichos, die Amoriter, Periziter, Kanaaniter, Chittiter und Girgasiter, Chiwiter und Jebusiter. Und ich gab sie in eure Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Ich sandte vor euch die Hornissen her. Sie vertrieben sie vor euch, zwei Könige der Amoriter, nicht durch dein Schwert und nicht durch deinen Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Ich gab euch ein Land, um das du dich nicht bemüht, und Städte, die ihr nicht gebaut, und ihr siedeltet darin. Weinberge und Olivengärten, die ihr nicht gepflanzt, genießet ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'So fürchtet den Herrn und dient ihm aufrichtig und treu! Schafft die Götter ab, denen eure Vorfahren jenseits des Stromes und in Ägypten gedient! Dient dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Mißfällt es euch aber, dem Herrn zu dienen, so wählt für euch heute, wem ihr dienen wollt, ob den Göttern, denen eure Ahnen jenseits des Stromes gedient, oder den Göttern der Amoriter, in deren Land ihr wohnt! Ich und mein Haus wollen dem Herrn dienen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Da antwortete das Volk und sprach: \"Ferne sei es uns, den Herrn zu verlassen und anderen Göttern zu dienen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Denn der Herr ist unser Gott. Er hat uns und unsere Väter aus Ägypten, wo wir Sklaven waren, hergeführt und vor unseren Augen diese großen Wunder getan und uns überall behütet auf dem Weg, den wir gegangen, und unter all den Völkern, durch die wir mitten durchgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'So vertrieb der Herr vor uns alle Völker, auch die Amoriter, des Landes Insassen. Auch wir wollen dem Herrn dienen. Denn er ist unser Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Josue sprach zum Volke: \"Ihr könnt dem Herrn nicht dienen. Denn er ist ein heiliger Gott. Er ist ein eifersüchtiger Gott. Er vergibt euch nicht euren Frevel und eure Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Verlasset ihr den Herrn und dienet ihr ausländischen Göttern, so wird er anders werden. Er tut euch dann Übles und reibt euch auf, nachdem er euch wohlgetan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Und das Volk sprach zu Josue: \"Nein! Wir wollen doch dem Herrn dienen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Da sprach Josue zum Volk: \"Ihr seid Zeugen wider euch selbst, daß ihr euch für den Dienst des Herrn entschieden habt.\" Sie sprachen: \"Jawohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '\"So schafft nun die ausländischen Götter bei euch weg und neigt euer Herz dem Herrn, dem Gott Israels, zu!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Und das Volk sprach zu Josue: \"Dem Herrn, unserem Gott, wollen wir dienen und auf seine Stimme hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Da schloß Josue an jenem Tage einen Bund mit dem Volke und gab ihm zu Sichem Satzung und Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Und Josue schrieb dies in das Buch der Lehre Gottes. Dann nahm er einen großen Stein und stellte ihn dort unter die Eiche im Heiligtum des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Josue aber sprach zum ganzen Volke: \"Wohlan, dieser Stein sei Zeuge wider uns! Denn er hat all die Worte angehört, die der Herr mit uns gesprochen hat. Darum sei er Zeuge gegen euch, daß ihr euren Gott nicht verleugnet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Dann entließ Josue das Volk, jeden in sein Besitztum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Hernach starb Josue, Nuns Sohn, des Herrn Diener, hundertzehn Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Sie begruben ihn im Bereiche seines Erbes zu Timnat Serach auf dem Gebirge Ephraim, nördlich vom Berg Gaas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Und Israel diente dem Herrn alle Tage Josues und der Ältesten, die noch lange nach Josue lebten und die noch jedes Werk kannten, das der Herr für Israel getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Josephs Gebeine aber, die die Israeliten aus Ägypten heraufgebracht hatten, hatten sie zu Sichem begraben, auf dem Feldstück, das Jakob von den Söhnen Chamors, des Vaters Sichems, um hundert Beutel gekauft hatte und das die Söhne Josephs als Erbe besaßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Auch Aarons Sohn Eleazar starb. Und sie begruben ihn auf seines Sohnes Pinechas Hügel, der ihm auf dem Gebirge Ephraim verliehen worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Und nach Josues Tode fragten die Söhne Israels den Herrn: \"Wer von uns soll zuerst in den Kampf wider die Kanaaniter ziehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Da sprach der Herr: \"Juda soll hinziehen! Ich gebe das Land in seine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Da sprach Juda zu seinem Bruder Simeon: \"Zieh mit mir in mein Losteil! Wir wollen wider die Kanaaniter streiten. Dann ziehe auch ich mit dir in dein Losteil.\" Und Simeon zog mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juda zog nun hin, und der Herr gab die Kanaaniter und die Periziter in seine Hand. Sie schlugen diese bei Bezek, 10.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'In Bezek stießen sie auf den Zepterträger, kämpften mit ihm und schlugen die Kanaaniter und Periziter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Der Zepterträger jedoch floh. Sie aber jagten ihm nach, griffen ihn und hieben ihm die Daumen und die großen Zehen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Da sprach der Zepterträger: \"Siebzig Könige mit abgehauenen Daumen und Zehen haben unter meinem Tische aufgelesen. Wie ich getan, so hat mir Gott vergolten.\" Dann brachten sie ihn nach Jerusalem, und er erlitt dort den Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Judas Söhne kämpften nämlich gegen Jerusalem, eroberten es und schlugen es mit des Schwertes Schärfe und steckten die Stadt in Brand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Danach zogen Judas Söhne zum Kampfe gegen die Kanaaniter hinab, die das Gebirge, das Südland und die Niederung bewohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Und Juda zog gegen die Kanaaniter in Hebron. Hebron aber hieß vormals Kirjat Arba. Sie schlugen Sesai, Achiman und Talmai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Von dort zogen sie gegen Debirs Einwohner. Debir hieß vormals Kirjat Sepher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Und Kaleb sprach: \"Wer Kirjat Sepher bezwingt und einnimmt, dem gebe ich meine Tochter Aksa zum Weibe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Da nahm es des Kenaz Sohn Otniel, Kalebs jüngerer Bruder. Da gab er ihm seine Tochter Aksa zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Als sie hinzog, überlistete sie ihren Vater, da sie von ihm ein Feld wollte. Sie neigte sich nämlich vom Esel, so daß Kaleb sie fragte: \"Was ist dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Sie aber sprach zu ihm: \"Gib mir doch eine Abschiedsgabe! Du vergibst mich ja nach dem Südland. So gib mir Wasser!\" Da gab ihr Kaleb oberirdische und unterirdische Wasserstellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Die Söhne des Keniters, des Schwiegervaters Mosis, waren aus der Palmenstadt zu den Söhnen Judas nach der Wüste Juda im Rücken Arads hinauf gezogen. Diese aber zogen ab und verpflanzten das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Auch Juda zog mit seinem Bruder Simeon weiter. Sie schlugen die Kanaaniter zu Sephat und bannten es. Daher nannte man die Stadt Chorma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Dann eroberte Juda Gaza, Askalon und Ekron je mit ihrem Gebiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Und der Herr war mit Juda, und es besetzte das Gebirge; die Talbewohner nämlich konnte es nicht vertreiben, weil sie eiserne Wagen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Sie gaben nun Hebron dem Kaleb, wie es Moses befohlen. Und er vertrieb daraus die Enaksöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Auch die Benjaminiten konnten die Jebusiter, Jerusalems Insassen, nicht vertreiben. So blieben die Jebusiter bei den Söhnen Benjamins bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Auch die vom Hause Josephs zogen gegen Betel, und der Herr war mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Die vom Hause Josephs ließen nun Betel ausspähen. Die Stadt aber hieß vordem Luz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Die Kundschafter sahen nun einen Mann aus der Stadt kommen und sagten zu ihm: \"Zeig uns den Zugang zur Stadt! Wir erweisen dir dafür Gutes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Da zeigte er ihnen den Zugang zur Stadt. Und sie schlugen die Stadt mit des Schwertes Schärfe. Den Mann aber ließen sie mit seiner ganzen Familie ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Da ging der Mann in das Chittiterland, baute eine Stadt und nannte sie Luz. So heißt sie bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Auch Manasse vertrieb nicht die Bewohner von Bet Sean, Taanak, Ibleam, Megiddo und ihren Dörfern. Den Kanaanitern nämlich gelang es, in diesem Lande zu bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Als aber Israel erstarkte, machte es die Kanaaniter zinsbar, vertrieb sie aber nicht ganz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Auch Ephraim vertrieb nicht die kanaanitischen Insassen von Gezer. So blieben die Kanaaniter mitten unter ihm zu Gezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Auch Zabulon vertrieb nicht die Insassen von Kitron noch die von Nahalol. So blieben die Kanaaniter mitten unter ihm, wurden aber zinsbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser vertrieb nicht die Insassen von Akko und die von Sidon, Achlab, Akzib, Helba, Aphik und Rechob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'So wohnten Assers Söhne mitten unter Kanaanitern, die im Lande blieben, weil man sie nicht vertrieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naphtali vertrieb nicht die Insassen von Bet Semes noch die von Bet Anat. So wohnte es mitten unter den Kanaanitern, die im Lande blieben. Doch wurden die Einwohner von Bet Semes und Bet Anat ihnen zinsbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Die Amoriter aber drängten Dans Söhne auf das Gebirge; denn sie ließen sie nicht in die Ebene ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'So gelang es den Amoritern, in Har Cheres, Ajjalon und Saalbin zu bleiben. Als aber die Macht des Josephhauses erstarkte, wurden sie zinsbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Das Amoritergebiet aber erstreckte sich von der Skorpionensteige, von dem Felsengebirge, weiter hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Des Herrn Bote aber zog von Gilgal nach Bokim und sprach: \"Ich führte euch aus Ägypten und brachte euch in dies Land, das ich euren Vätern zugeschworen. Ich sprach: \'Ich breche nie mein Bündnis mit euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Aber auch ihr dürft mit den Bewohnern dieses Landes kein Bündnis schließen. Zerstören sollt ihr ihre Altäre!\' Ihr habt aber nicht auf meine Stimme gehört. Wie habt ihr solches tun können?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'So sage auch ich: \"Ich will sie nicht vor euch vertreiben. Sie seien euch zur Schlinge, und ihre Götter seien euch zur Falle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Des Herrn Bote sprach nun diese Worte zu allen Söhnen Israels. Da erhob das Volk seine Stimme und weinte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Und so nannte man einen Ort Bokim. Und sie opferten dort dem Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Josue entließ nun das Volk. Da gingen die Israeliten, jeder nach seinem Erbbesitz, das Land zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Und das Volk diente dem Herrn alle Tage Josues und all der Ältesten, die Josue überlebt und die noch geschaut hatten jede Großtat des Herrn, die er für Israel getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Da starb Josue, Nuns Sohn, des Herrn Diener, hundertzehn Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Man begrub ihn im Bereiche seines Erbes zu Timnat Cheres auf dem Gebirge Ephraim, nördlich vom Berge Gaas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Auch dies ganze Geschlecht ward zu seinen Vätern versammelt. Danach kam ein anderes Geschlecht, das den Herrn nicht kannte, noch das Werk, das er für Israel getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Und die Israeliten taten, was dem Herrn mißfiel, und dienten den Baalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Sie verließen den Herrn, ihrer Väter Gott, der sie aus Ägypten geführt, und liefen anderen Göttern nach, solchen aus den Göttern der Völker rings um sie. Sie beteten sie an und kränkten den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Sie verließen also den Herrn und dienten den Baalen und den Astarten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Da entbrannte des Herrn Zorn wider Israel. Er gab sie in die Hand der Plünderer, die sie ausraubten. So verkaufte er sie in die Hand ihrer Feinde ringsum, und sie konnten nicht ihren Feinden widerstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Wohin sie zogen, war des Herrn Hand gegen sie zum Unheil, wie der Herr gesagt, und wie der Herr ihnen zugeschworen. Aber ihre Not ward zu groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'So ließ der Herr Richter erstehen, und diese retteten sie aus ihrer Plünderer Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Aber auch ihren Richtern gehorchten sie nicht, sondern buhlten hinter anderen Göttern her und beteten sie an. So wichen sie schnell von dem Wege ab, den ihre Väter gegangen, als sie des Herrn Geboten gehorchten. Sie aber taten nicht so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Ließ ihnen der Herr Richter erstehen, so war der Herr mit dem Richter und bewahrte sie vor ihrer Feinde Hand alle Tage des Richters. Denn der Herr änderte seinen Sinn ob ihrer Klage über ihre Bedränger und Bedrücker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Starb aber der Richter, so trieben sie es wieder schlimmer als ihre Väter. Sie liefen anderen Göttern nach, dienten ihnen und beteten sie an. Sie ließen nicht von ihren Missetaten und ihrem verkehrten Wandel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Dann entbrannte des Herrn Zorn gegen Israel, und er sprach: \"Weil dieses Volk mein Bündnis übertritt, das ich ihren Vätern befohlen, und nicht auf meine Stimme hört,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'so vertreibe ich vor ihnen nicht einen Mann mehr aus jenen Heidenvölkern, die Josue bei seinem Tode hinterlassen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'um Israel durch sie zu prüfen, ob sie des Herrn Wandel achteten und danach wandelten, wie ihre Väter darauf geachtet, oder nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'So ließ der Herr jene Heidenvölker, ohne sie rasch zu vertilgen; er hatte sie nicht in Josues Hand gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Dies sind die Heidenvölker, die der Herr dagelassen hat, um durch sie Israel zu erproben in all dem, was sie noch nicht gekannt, in den Kämpfen mit Kanaan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '- nur damit die Geschlechter der Israeliten das Kriegshandwerk zu erlernen verstünden, einzig das, was sie vormals nicht gekannt haben -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'die fünf Philisterfürsten, alle Kanaaniter, Sidonier und die Chiwiter, die auf dem Libanongebirge vom Berge Baal Hermon bis gegen Hamat saßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Sie waren da, um Israel an ihnen zu prüfen und zu erfahren, ob sie des Herrn Gebot gehorchten, das er ihren Vätern durch Moses gegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'So saßen die Israeliten mitten unter den Kanaanitern, Chittitern, Amoritern, Perizitern, Chiwitern und Jebusitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Sie nahmen sich ihre Töchter zu Weibern, und ihre Töchter gaben sie ihren Söhnen und dienten ihren Göttern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Die Israeliten nun taten, was dem Herrn mißfiel, vergaßen des Herrn und dienten den Baalen und den Ascheren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Da entbrannte des Herrn Zorn gegen Israel, und er verkaufte sie in die Hand des Kuschan Rischataim, des Königs von Mesopotamien. Und so dienten die Israeliten dem Kuschan Rischataim acht Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Da schrien die Israeliten zum Herrn, und der Herr ließ den Israeliten einen Retter erstehen, der sie befreite, Otniel, des Kenaz Sohn, Kalebs jüngeren Bruder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Der Geist des Herrn kam auf ihn, und so richtete er Israel. Er zog zu Felde, und der Herr gab Arams König, Kuschan Rischataim, in seine Hand. Seine Hand lag schwer auf Kuschan Rischataim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'So rastete das Land vierzig Jahre. Da starb des Kenaz Sohn Otniel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Die Israeliten aber taten aufs neue, was dem Herrn mißfiel. Da gab der Herr dem Moabkönig Eglon Macht über Israel, weil sie getan, was dem Herrn mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Und er verband sich mit den Ammonitern und mit Amalek. So zog er hin, schlug Israel, und sie besetzten die Palmenstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Die Israeliten dienten dem König Moabs, Eglon, achtzehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Da schrien die Israeliten zum Herrn, und der Herr ließ ihnen einen Retter erstehen, Ehud, den Sohn Geras, den Benjaminiten, einen Linkshänder. Durch ihn sandten die Israeliten an Moabs König, Eglon, eine Spende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Da machte sich Ehud ein Schwert, zweischneidig und eine Spanne lang. Er gürtete es unter seinem Gewand an seine rechte Seite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'So brachte er die Spende dem Eglon, Moabs König. Eglon aber war sehr beleibt. Er war eben von den Götzenbildern im Gilgal heimgekehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Als er die Spende überreicht hatte, entließ er die Leute, die Träger der Spende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Er sprach: \"König! Ein geheimes Wort habe ich an dich.\" Da sprach dieser: \"Still!\" Darauf gingen alle fort, die ihn umstanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Ehud war nun an ihn herangetreten. Er aber saß in seinem kühlen Söller allein da. Ehud sprach nun: \"Ich habe an dich ein Gotteswort.\" Da stand er vom Throne auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Ehud aber streckte seine Linke aus, nahm das Schwert von seiner rechten Hüfte und stach es ihm in den Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Und er stieß nach der Klinge das Heft hinein, und das Fett umschloß die Klinge; denn er hatte das Schwert nicht aus seinem Leibe gezogen; dann verließ er den Flur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Hierauf ging Ehud durch den Mittelbau, verschloß die Türen des Obergemachs hinter sich und riegelte ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Eben war er fortgegangen, da kamen seine (Eglons) Diener und fanden die Tür des Söllers verriegelt. Sie sprachen: \"Er begießt wohl in der kühlen Kammer seine Füße.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'So warteten sie endlos. Aber niemand öffnete die Tür des Söllers. Da holten sie den Schlüssel und schlossen auf. Ihr Herr lag tot am Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud aber war während ihres Wartens entkommen und hatte die Götzenbilder umgestürzt, dann entkam er in den Busch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Wie er nun heimkam, stieß er auf dem Gebirge Ephraim in das Horn. Da stiegen mit ihm die Israeliten vorn Gebirge herab, er an ihrer Spitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Er sprach zu ihnen: \"Folgt mir schnell! Denn der Herr gibt eure Feinde, Moab, in eure Hand.\" Da stiegen sie hinab, ihm nach, besetzten die Jordanfurten gegen Moab und ließen niemand hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Sie schlugen damals Moab, etwa zehntausend Mann, Lauter starke und streitbare Leute; und niemand entrann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Damals ward Moab unter Israels Hand gebeugt, und das Land hatte achtzig Jahre Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Nach ihm trat Anats Sohn, Samgar, auf. Er schlug die Philister, sechshundert Mann, mit einem Ochsenstecken. Auch er befreite Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Und wieder taten die Israeliten, was dem Herrn mißfiel. Ehud aber war gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'So verkaufte sie der Herr in die Hand des Königs von Kanaan, Jabin, der zu Chasor regierte. Sein Feldherr war Sisera, der zu Charoset Haggojim saß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Da schrien die Israeliten zum Herrn. Denn er hatte neunhundert eiserne Wagen und bedrückte die Israeliten zwanzig Jahre gewaltig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'In jener Zeit richtete Lapidots Weib, die Prophetin Debora, Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Sie saß unter der Bienenpalme zwischen Rama und Betel auf dem Gebirge Ephraim, und die Israeliten zogen zum Gericht zu ihr hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Sie sandte nun hin und berief Abinoams Sohn, Barak, aus Kedes Naphtali. Sie sprach zu ihm: \"Befiehlt nicht der Herr, Israels Gott? Auf! Zieh auf den Taborberg! Nimm mit dir zehntausend Mann aus Naphtalis und Zabulons Söhnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Dann locke ich zu dir an den Kisonbach Sisera, Jabins Heerführer, samt seinen Wagen und seinem Heereshaufen und gebe sie in deine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak aber sprach zu ihr: \"Gehst du mit mir, dann gehe ich. Wenn nicht, dann gehe ich auch nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Sie sprach: \"Ich ziehe mit dir. Doch wird der Ruhm nicht dein werden auf dem Weg, den du gehst. Denn der Herr verkauft dann in eines Weibes Hand den Sisera.\" Darauf erhob sich Debora und zog mit Barak nach Kedes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Barak entbot nun Zabulon und Naphtali nach Kedes. Zehntausend Mann folgten ihm auf dem Fuße hinauf. Auch Debora zog mit ihm hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Der Keniter Cheber aber hatte sich getrennt von Kain, einem der Söhne Chobabs, des Schwiegervaters Mosis, und zeltete an der Eiche zu Saanim bei Kedes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Nun meldete man Sisera, Barak, Abinoams Sohn, sei auf den Berg Tabor gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Da entbot Sisera alle seine Wagen, neunhundert eiserne Wagen und das gesamte Kriegsvolk bei sich aus Charoset Haggojim an den Kisonbach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Da sprach Debora zu Barak: \"Auf! Das ist der Tag, in dem der Herr den Sisera in deine Hand gibt. Zieht der Herr nicht vor dir her?\" Da stieg Barak vom Taborberge herab, und zehntausend Mann hinter ihm her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Da verwirrte der Herr den Sisera, alle Wagen und das ganze Heer durch des Schwertes Schärfe vor Barak. Und Sisera stieg vom Wagen und floh zu Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak aber jagte den Wagen und das Heer bis Charoset Haggojim, und Siseras ganzes Heer fiel durch des Schwertes Schärfe. Auch nicht einer blieb übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera aber floh zu Fuß zum Zelte Jaëls, der Frau des Keniters Cheber. Denn zwischen Chasors König, Jabin, und dem Haus des Keniters Cheber war Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Da trat Jaël heraus, dem Sisera entgegen und sprach zu ihm: \"Kehr ein, Herr! Kehre bei mir ein! Fürchte dich nicht!\" Da kehrte er im Zelt bei ihr ein, und sie bedeckte ihn mit einer Decke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Er sprach zu ihr: \"Gib mir ein wenig Wasser! Mich dürstet.\" Da öffnete sie den Milchschlauch und ließ ihn trinken. Dann bedeckte sie ihn wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Er aber sprach zu ihr: \"Stell dich an des Zeltes Eingang! Kommt jemand und fragt dich und spricht: \'Ist jemand hier?\' so sag: \'Nein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Jaël, Chebers Weib, aber ergriff einen Zeltpflock, nahm den Hammer in die Hand und trat leise zu ihm; dann schlug sie ihm den Pflock durch die Schläfe, daß er in die Erde drang. Jener war nämlich eingeschlafen. Da zuckte er und starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Da kommt Barak, der Sisera nachjagt. Jaël tritt heraus, ihm entgegen, und spricht zu ihm: \"Komm! Ich zeige dir den Mann, den du suchst.\" Er trat bei ihr ein. Da lag Sisera tot da, mit dem Zeltpflock in der Schläfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'So demütigte Gott an jenem Tage Kanaans König, Jabin, vor den Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Und die Hand der Israeliten wuchtete immer schwerer auf Jabin, Kanaans König, bis sie Kanaans König, Jabin, vernichtet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Da sang Debora mit Abinoams Sohn, Barak, an jenem Tage also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '\"Stimmt an in Israel, ihr Führer! Fall ein, du Volk, beim Loblied auf den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Ihr Könige, hört! Horcht auf, ihr Herren! Ich bin des Herrn; ich will lobsingen; ich weih dem Herrn, dem Gotte Israels, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Herr! Als Du ausgezogen von Seïr, als Du von Edoms Fluren hergekommen, da zitterte die Erde, und die Himmel troffen; von Wasser troffen Wolken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Vorm Herrn, dem Herrn, die Berge bebten, vorm Herrn, vor Israels Gott, am Sinai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Gefeiert haben Straßen zur Zeit des Anatsohnes Samgar, in Jaëls Tagen. Denn die, die sonstens auf den Straßen zogen, betraten jetzt nur Seitenpfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'In Israel gemangelt haben Schwerter, ja gemangelt, bis daß du aufgestanden bist, Debora, bis daß du dich in Israel erhoben hast als Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Dies wählte neue Führer, die sich damals einten. Schild aber sah man nicht, noch Speer bei vierzigtausend Mann in Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Die Hochgemuten bei den Führern Israels, die sich dem Volke hingegeben, sie hatten hoch den Herrn gepriesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Die ihr auf weißen Eselinnen rittet, die auf den Wagen fuhren, die auf dem Weg marschierten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'sie stießen Rufe aus, anstimmend den Gebetsgesang: Des Herren Siegestaten priesen sie, die Siegestaten seines Schwertes in Israel! Dann zogen sie herab mit Planken, das Volk des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, '\'Auf! Auf, Debora! Auf! Auf! Stimm an das Lied!\' \'Auf, Barak! Gefangene mach dir, du Sohn des Abinoam!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Voll Kraft stieg da herab die kleine Schar. Das Volk des Herrn griff an voll Wut, ganz eng vereint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Ephraims Stamm zog aus in Kühnheit, und hinter ihm mit seinen Leuten Benjamin. Auszog Makir; herab die Edlen stiegen. Hinzogen die aus Zabulon Gemusterten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Und bei Debora blieben Issakars Anführer, und unter Barak stellt sich Issakar und wird zu Tal gesandt mit seinen Truppen. In Rubens Sippen waren Große bitteren Gemütes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, '\'Was bleibst du unschlüssig da sitzen? Um der Gemeinen Hohn zu hören?\' In Rubens Sippen waren Große zornigen Gemütes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, '\'Warum bleibt Gilead über dem Jordan? Warum weilt bei den Schiffen Dan? Bleibt Asser an dem Meeresufer sitzen, an seinen Buchten wohnen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sein Leben hat das Volk von Zabulon bis in den Tod mißachtet, und Naphtali ward wild bis auf das äußerste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Da kamen Könige und kämpften; da kämpften kampfesfroh die Könige von Kanaan zu Taanak an den Gewässern von Megiddo; doch sie errangen nicht den Silberpreis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vom Himmel kämpften, von ihren Bahnen kämpften selbst mit Sisera die Sterne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Fort raffte sie der Kisonbach, der Kisonbach die Überraschten; des Frostes Kälte lähmte seine Starken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Geschlagen hatten die zu Fuß die Reiterei, verjagt die Führer der Rossewagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '\'Verfluchet, die bei Seite sind gestanden!\' spricht des Herren Bote \'verfluchet, die zu ihnen hielten! Gekommen sind sie nimmer zu den Vorkämpfern des Herrn, zu des Herren Vorkämpfern mit Kriegern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Gesegnet sei die Jaël vor den Weibern des Cheber, des Keniters Weib! Sie sei im Zelt gesegnet vor den Weibern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Um Wasser bittet er. Sie spendet Milch; in einer Ehrenschale reicht sie Sahne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Doch ihre Linke streckt sich nach dem Pflock, und ihre Rechte nach dem Schmiedehammer. Sie hämmerte auf Sisera, durchschlug sein Haupt, zerschmetterte durchbohrend seine Schläfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Zu ihren Füßen sank er hin, fiel nieder und blieb liegen. Zu ihren Füßen sank er nochmals hin und stürzte nieder; wo er zusammenbrach, da blieb er liegen, hingestreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Durchs Fenster lehnte sich die Mutter Siseras und rief durchs Gitter: \'Warum enttäuscht sein Wagen mit der Heimkehr? Warum verziehn sich der Gespanne Tritte?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Die Klügste ihrer Fürstinnen gab ihr zur Antwort; sie war es auch, die ihr erwiderte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '\'Sie fanden sicher Beute und verteilten sie, ein doppelt Maß für jeden Krieger; Beute mancher Art hat Sisera, Beute, mannigfaltig, prächtig; mannigfaltig, zierlich, herrlich ist die Beute.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, '\'So müssen alle, die dem Herren feind, zugrunde gehen! Doch die ihn lieben, sie gleichen einem Sonnenaufgange in seiner Pracht.\'\" - Und das Land hatte vierzig Jahre Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Die Israeliten aber taten wieder, was dem Herrn mißfiel. Da gab sie der Herr für sieben Jahre in die Hand Midians.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Und Midians Hand wuchtete auf Israel. Da benützten Midians wegen die Israeliten die Schluchten, Höhlen und Festen im Gebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Wenn Israel gesät hatte, dann zogen die Midianiter, wie sonst Amalek und des Ostens Söhne, herauf und zogen dawider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Sie lagerten wider sie und grasten des Landes junge Saat ab, bis Gaza hin. Sie ließen in Israel kein Futter übrig für Schafe, Rinder und Esel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Denn sie kamen mit ihrem Vieh und brachten ihre Zelte mit. Sie kamen wie die Heuschrecken an Menge. Ihrer und ihrer Kamele war keine Zahl. So kamen sie in das Land, es abzugrasen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Da verkümmerte Israel gewaltig durch Midian. So schrien die Israeliten zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'So kam es, daß die Israeliten wegen Midian zum Herrn schrien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Und der Herr sandte zu den Israeliten einen Propheten. Er sprach zu ihnen: \"So spricht der Herr, Israels Gott: \'Ich habe euch aus Ägypten hergebracht und euch aus dem Sklavenhause geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Ich befreite euch aus Ägyptens Hand und aus der Hand eurer Dränger. Ich vertrieb sie vor euch und gab euch ihr Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Ich sprach zu euch: \"Ich bin der Herr, euer Gott. Ihr sollt nicht die Götter der Amoriter fürchten, in deren Land ihr siedelt!\" Ihr aber habt nicht auf meine Stimme gehört.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Da kam des Herrn Engel und setzte sich unter die Terebinthe zu Ophra, das dem Abiezriter Joas gehörte. Sein Sohn Gideon drosch eben in der Kelter Weizen, um ihn vor Midian zu bergen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Da erschien ihm des Herrn Engel und sprach zu ihm: \"Du tapferer Held! Der Herr ist mit dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Da sprach Gideon zu ihm: \"Mit Vergunst, mein Herr! Ist der Herr mit uns, warum trifft uns all dies? Wo bleiben all seine Wundertaten, von denen unsere Väter uns also erzählt: Hat uns nicht der Herr aus Ägypten heraufgeführt? Aber jetzt verstößt uns der Herr und gibt uns in Midians Faust.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Da wandte sich der Herr ihm zu und sprach: \"Geh in dieser deiner Kraft! Rette Israel aus Midians Hand! Sende ich dich nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Er sprach zu ihm: \"Mit Vergunst, mein Herr! Womit soll ich Israel retten? Ist doch meine Sippe die schwächste in Manasse, und bin doch ich der geringste in meines Vaters Haus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Da sprach der Herr zu ihm: \"Bin ich mit dir, dann schlägst du Midian wie einen Mann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Er sprach zu ihm: \"Habe ich in Deinen Augen Gnade gefunden, so gib mir ein Zeichen, daß Du mit mir redest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Weiche nicht von hier, bis ich zu Dir komme, meine Gabe hole und Dir vorsetzen Er sprach: \"Ich bleibe, bis du wiederkommst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Da ging Gideon weg und bereitete ein Ziegenböckchen und einen ungesäuerten Kuchen von einem Maß Mehl. Das Fleisch aber hatte er in den Korb gelegt und die Brühe in den Topf getan. So brachte er es ihm unter die Terebinthe und setzte es vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Da sprach zu ihm der Engel Gottes: \"Nimm das Fleisch und die ungesäuerten Brote! Und lege sie drüben auf den Felsen! Die Brühe aber gieße weg!\" Und er tat so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Da streckte der Engel des Herrn die Spitze des Stabes in seiner Hand aus und berührte das Fleisch samt den ungesäuerten Broten. Da schlug Feuer aus dem Felsen und verzehrte das Fleisch samt den ungesäuerten Broten. Des Herrn Engel aber entschwand aus seinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Da merkte Gideon, daß es der Engel des Herrn war. Und Gideon sprach: \"Wehe, Herr, Herr! Leider habe ich des Herrn Engel von Angesicht zu Angesicht gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Da sprach der Herr zu ihm: \"Friede sei mit dir! Fürchte dich nicht! Du wirst nicht sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Da baute Gideon dort einen Altar dem Herrn und nannte ihn: \"Des Herren Heil.\" Bis auf diesen Tag steht er noch im abiezritischen Ophra.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'In jener Nacht sprach der Herr zu ihm: \"Nimm deines Vaters Leitbullen, den zweigehörnten Stier von sieben Jahren, und zertrümmere den Baalsaltar deines Vaters! Die Aschera (hl. Pfahl) daneben aber sollst du fällen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Dann baue einen Altar dem Herrn, deinem Gott, auf dieses Felsens Höhe mit einem Feuerherd und nimm den zweigehörnten Stier und bringe ihn als Brandopfer dar mit dem Holz des heiligen Pfahles, das du zerschlagen sollst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Da nahm Gideon aus seinen Sklaven zehn Männer und tat, wie ihm der Herr geboten. Weil er sich aber vor seines Vaters Haus und den Leuten der Stadt fürchtete, es bei Tag zu tun, so tat er es bei Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Als nun die Leute der Stadt am anderen Morgen aufstanden, war der Baalsaltar niedergerissen und der heilige Pfahl daneben umgehauen, und der zweigehörnte Stier geopfert auf dem neuerbauten Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Die Leute fragten einander: \"Wer hat dies getan?\" Als sie so fragten und forschten, hieß es: \"Des Joas Sohn Gideon hat dies getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Da sprachen die Leute der Stadt zu Joas: \"Gib deinen Sohn heraus, daß er sterbe. Denn er hat den Baalsaltar eingerissen und den heiligen Pfahl daneben umgehauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Da sprach Joas zu all den Umstehenden: \"Wollt ihr für den Baal streiten? Wollt ihr ihm helfen? Wer für ihn streitet, soll bis zum Morgen getötet werden! Ist er ein Gott, so streite er für sich selbst, weil man seinen Altar eingerissen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'So nannte man ihn an jenem Tag Jerubbaal, weil man sagte: \'Der Baal streite mit ihm, weil er seinen Altar eingerissen hat!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Nun hatte sich ganz Midian, wie sonst Amalek und des Ostens Söhne, verbündet, war herübergekommen und lagerte in der Jezreelebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Da fuhr der Geist des Herrn in Gideon. Und er stieß in das Horn. So ward Abiezer zur Heeresfolge aufgerufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Danach sandte er Boten zu ganz Manasse. Auch dies ward zur Heeresfolge aufgerufen. Dann sandte er Boten nach Asser, Zabulon und Naphtali. Auch diese zogen ihnen entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Da sprach Gideon zu Gott: \"Willst Du wirklich durch meine Hand die Israeliten retten, wie Du gesagt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'dann lege ich ein Schafvließ auf die Tenne. Ist der Tau allein auf dem Vließ und sonst überall der Boden trocken, dann weiß ich, daß Du durch meine Hand Israel rettest, wie Du gesagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Und so geschah es. Als er am anderen Morgen das Vließ auswand, preßte er aus dem Vließ Tau, eine Schale voll Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Da sprach Gideon zu Gott: \"Ach! Möge nicht Dein Zorn über mich entflammen, wenn ich nur diesmal noch rede! Ich möchte es nur noch diesmal mit dem Vließ versuchen. Das Vließ allein bleibe trocken; aber sonst sei überall Tau auf dem Boden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Und Gott tat so in jener Nacht. Das Vließ allein blieb trocken; sonst aber lag überall auf dem Boden Tau.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Jerubbaal, das ist Gideon, machte sich nun früh auf mit allem Volke bei ihm, und sie lagerten bei der Quelle Charod, Midians Lager aber war nördlich davon, von dem Hügel des Maulbeerbaumes bis in die Ebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Da sprach der Herr zu Gideon: \"Zuviel ist des Volkes bei dir, als daß ich Midian in deine Hand gäbe. Sonst könnte sich Israel wider mich brüsten und sagen: \'Ich habe mir selbst geholfen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'So ruf denn laut zum Volke: \'Wer bangt und bebt, kehre um und schleiche vom Gileadgebirge fort!\' Da kehrten vom Volke zweiundzwanzigtausend um; nur zehntausend blieben zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Da sprach der Herr zu Gideon: \"Noch ist es des Volkes zuviel. Führe sie zum Wasser, daß ich sie dir dort sichte! Von wem ich dir sage: \'Er begleite dich!\', der soll dich begleiten! Von wem ich aber zu dir sage: \'Er begleite dich nicht!\', der darf nicht mitziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Da führte er das Volk ans Wasser, und der Herr sprach zu Gideon: \"Wer mit der Zunge Wasser schlürft, wie die Hunde schlürfen, den stelle besonders! Ebenso jeden, der zum Trinken niederkniet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Da war die Zahl derer, die das Wasser mit dem Munde aus der Hand schlürften, dreihundert. Der ganze Rest des Volkes aber war zum Wassertrinken hingekniet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Da sprach der Herr zu Gideon: \"Mit den dreihundert Mann, die Wasser schlürften, rette ich euch und gebe Midian in deine Hand. All das andere Volk soll heimgehen, jeglicher an seinen Ort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Da bekamen sie des Volkes Vorrat in ihre Hand und seine Hörner. Dann entließ er alle Israeliten, jeden in seine Heimat; nur die dreihundert Mann hatte er behalten. Midians Lager aber war unter ihm in der Ebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'In jener Nacht sprach der Herr zu ihm: \"Auf! Steige hinab ins Lager! Ich gebe es in deine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Hast du aber Angst hinabzusteigen, so steige mit deinem Diener Pura zum Lager hinab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Belausche, was sie darin sprechen! Dann werden deine Hände stark, und du wirst das Lager angreifen.\" Da stieg er mit seinem Diener Pura hinab bis ganz nahe an die Gewappneten im Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midian aber, wie sonst Amalek und alle Söhne des Ostens, lag in der Ebene wie Heuschrecken an Masse, und ihre Kamele waren zahllos wie die Sandmenge am Meeresufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Und Gideon kam. Da erzählte eben ein Mann dem anderen einen Traum und sprach: \"Ich habe geträumt: Ein Stück Gerstenbrot rollte in Midians Lager, kam bis zum Zelt, traf es, daß es fiel, und drehte es nach oben, als das Zelt umfiel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Da antwortete der andere und sprach: \"Das ist nichts anderes, als des Joassohnes Gideon Schwert. Gott gibt einem Israeliten Midian mit dem ganzen Lager in seine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Als aber Gideon die Erzählung und die Auslegung des Traumes hörte, warf er sich anbetend nieder; dann kehrte er in Israels Lager zurück und sprach: \"Auf! Der Herr gibt Midians Lager in eure Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Darauf teilte er die dreihundert Mann in drei Heerhaufen und gab allen Hörner und leere Krüge in die Hand. In den Krügen aber waren Fackeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Dann sprach er zu ihnen: \"Seht auf mich und tut ebenso! Komme ich bis zum Rande des Lagers, dann tut das gleiche, was ich tue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Stoße ich in das Horn und alle bei mir, dann stoßt auch ihr in die Hörner um das Lager und ruft: \'Für den Herrn und Gideon!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'So kam Gideon mit den hundert Mann, die bei ihm waren, bis zum Lagerrand bei Beginn der mittleren Nachtwache. Eben hatten sie die Wachen ausgestellt. Da stießen sie in die Hörner und zerschlugen die Krüge in ihrer Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'So stießen die drei Heerhaufen in die Hörner, zerbrachen die Krüge, nahmen die Fackeln in die linke und die Hörner zum Blasen in die rechte Hand und riefen durchdringend: \"Für den Herrn und Gideon!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Dabei blieb jeder auf seinem Platze rings um das Lager. Im Lager aber rannte alles hin und her. Sie lärmten und flohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Jene aber stießen in die dreihundert Hörner, und der Herr wandte des einen Schwert gegen den anderen. Was im Lager war, floh bis nach Bet Sitta gegen Zereda hin, bis an das Ufer von Abel Mechola bei Tabbat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Da ward Israels Mannschaft aus Naphtali, Asser und ganz Manasse aufgeboten, und sie verfolgten Midian.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Auch sandte Gideon Boten auf das ganze Gebirge Ephraim und ließ sagen: \"Zieht hinab Midian entgegen und besetzt ihre Wasserstellen bis Bet Bara und bis an den Jordan!\" Da ward Ephraims gesamte Mannschaft aufgeboten, und sie besetzten die Wasserstellen bis Bet Bara und an den Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Und sie fingen zwei Midianiterfürsten, Oreb und Zeeb. Den Oreb erschlugen sie am Rabenfelsen und den Zeeb bei der Wolfskelter. Dann jagten sie weiter Midian nach. Orebs und Zeebs Köpfe aber brachten sie zu Gideon über den Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Da sprach Ephraims Mannschaft zu ihm: \"Was hast du uns angetan, daß du uns nicht riefst, als du in den Kampf wider Midian gezogen bist?\", Und sie machten ihm heftige Vorwürfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Er sprach zu ihnen: \"Was habe ich im Vergleich zu euch getan? Ist nicht Ephraims Nachlese besser als Abiezers Lese?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'In eure Hand hat Gott die Midianiterfürsten Oreb und Zeeb gegeben. Was habe ich im Vergleich mit euch tun können?\" Da legte sich ihr Zorn gegen ihn, als er so sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Dann zog Gideon an den Jordan. Er und die dreihundert Mann bei ihm zogen hinüber. Sie waren zwar matt, setzten aber die Verfolgung fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Da sprach er zu Sukkots Männern: \"Gebt den Leuten, die ich befehlige, Brotkuchen! Denn sie sind matt. Ich aber jage den Midianiterkönigen Zebach und Salmunna nach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Da sagten Sukkots Oberste: \"Hast du schon Zebach und Salmunna in deiner Hand, daß wir deiner Heerschar Brot geben sollten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Da sprach Gideon: \"Nun gut! Gibt der Herr Zebach und Salmunna in meine Hand, dann zerdresche ich euch mit Wüstendornen und Disteln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Von da zog er nach Penuel hinauf und sprach zu diesem ebenso. Aber Penuels Männer erwiderten ihm, wie die Männer Sukkots erwidert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Da sprach er zu Penuels Männern: \"Komme ich heil zurück, dann schleife ich diesen Turm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebach und Salmunna aber waren in Karkor mit ihrem Heer, etwa fünfzehntausend Mann. Das war alles, was vom ganzen Heer der Söhne des Ostens übriggeblieben war. Der Gefallenen waren es 120.000 Mann Schwertgerüstete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideon zog nun den Weg gegen die Zeltleute östlich von Nobach und Jogbeha und überfiel das Lager; das Lager aber lag sorglos da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Zebach und Salmunna flohen. Er aber jagte ihnen nach, fing die beiden Midianskönige Zebach und Salmunna und vernichtete das ganze Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Hierauf kehrte Gideon, des Joas Sohn, an der Sonnensteige vom Kriegszug um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Da griff er einen jungen Mann aus Sukkots Männern und fragte ihn aus. Und er schrieb ihm Sukkots Oberste und Älteste auf, siebenundsiebzig Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'So kam er zu den Männern von Sukkot und sprach: \"Hier sind Zebach und Salmunna, deretwegen ihr mich gehöhnt habt mit den Worten: \'Hast du schon Zebach und Salmunna in deiner Hand, daß wir deinen hungrigen Männern Brot geben sollten?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Dann nahm er die Ältesten der Stadt sowie Wüstendornen und Stacheln und verurteilte Sukkots Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Ebenso schleifte er Penuels Turm und metzelte die Männer der Stadt nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Dann sprach er zu Zebach und Salmunna: \"Wie sind die Männer gewesen, die ihr am Tabor erschlagen habt?\" Sie sprachen:\"Ganz so wie du. Jeder nach Aussehen ein Königssohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Er sprach: \"Das sind meine Brüder gewesen, meiner Mutter Söhne. So wahr der Herr lebt! Hättet ihr sie leben lassen, ich brächte euch nicht um.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Dann rief er seinen Erstgeborenen Jeter: \"Auf! Schlag sie nieder!\" Aber der Knabe zog sein Schwert nicht, weil er sich scheute. Denn er war noch zu jung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Da sprachen Zebach und Salmunna: \"Auf! Stoß du uns nieder! Denn wie der Mann, so seine Kraft!\" Da stand Gideon auf und erschlug Zebach und Salmunna. Er nahm auch die kleinen Monde an den Hälsen ihrer Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Da sprach Israels Mannschaft zu Gideon: \"Walte über uns, du, dein Sohn und dein Enkel! Denn du hast uns aus Midians Hand befreit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Da sprach Gideon zu ihnen: \"Weder will ich über euch walten, noch mein Sohn. Der Herr walte über euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Dann sprach Gideon zu ihnen: \"Ich will mir von euch etwas anderes erbitten: Gebt mir jeder aus seiner Beute einen Ring!\" Jene hatten nämlich goldene Ringe, weil sie Ismaeliter waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Da sagten sie: \"Gern geben wir dir sie.\" Und sie breiteten einen Mantel aus, und jeder warf seinen Beutering darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Das Gewicht der Goldringe, die er erbeten hatte, betrug 1.700 Ring Gold, außer den Monden, Ohrgehängen und Purpurkleidern, die die Midianskönige getragen, und den Halsbändern ihrer Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideon machte daraus ein Ephod und stellte es in seiner Stadt Ophra auf. Und ganz Israel hurte ihm dort nach. So ward es Gideon und seinem Hause zum Fallstricke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Also ward Midian von den Israeliten gedemütigt, daß es nicht wieder das Haupt erhob. Und das Land hatte in Gideons Tagen vierzig Jahre Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Und Jerubbaal, des Joas Sohn, zog ab und blieb fortan zu Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideon aber besaß siebzig Vollsöhne. Denn er hatte viele Weiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Sein Nebenweib zu Sichem aber hatte ihm auch einen Sohn geboren, und er legte ihm den Namen Abimelek bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon, des Joas Sohn, starb in hohem Alter und ward in seines Vaters Joas Grab begraben, im Ophra der Abiezriten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Als aber Gideon tot war, hurten die Israeliten wieder mit den Baalen. Sie nahmen sich den Bundesbaal zum Schutzgott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Und die Israeliten gedachten nicht mehr des Herrn, ihres Gottes, der sie aus der Hand all ihrer Feinde ringsum befreit hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Auch erwiesen sie keine Liebe der Familie Jerubbaals, vormals Gideon genannt, trotz dem Guten, das er Israel getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Jerubbaals Sohn Abimelek nämlich ging nach Sichem zu den Brüdern seiner Mutter. Er sprach zu ihnen und zu der ganzen Sippe des Vaterhauses seiner Mutter also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '\"Befragt alle Sichemsbürger eindringlich: \'Was frommt euch mehr? Daß siebzig Männer über euch walten, all die Jerubbaalssöhne, oder nur ein Mann?\' Bedenkt auch, daß ich euer Fleisch und Bein bin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Da redeten die Brüder seiner Mutter seinetwegen eindringlich mit allen Bürgern von Sichem alle diese Worte. Da neigte sich ihr Sinn Abimelek zu; denn sie sagten: \"Er ist unser Bruder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Und sie gaben ihm siebzig Silberstücke aus dem Haus des Bundesbaal. Damit dingte Abimelek arme und gewissenlose Männer, die ihm folgten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Dann ging er in seines Vaters Haus zu Ophra und erschlug seine Brüder, Jerubbaals Söhne, siebzig Mann, auf einem Steine. Nur Jerubbaals jüngster Sohn Jotam blieb übrig; denn er hatte sich versteckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Nun versammelten sich alle Bürger Sichems und das ganze Haus der Burg. Sie gingen hin und machten Abimelek zum König bei der Bildsäule, die in Sichem aufgestellt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Als man dies Jotam erzählte, ging er hin und stellte sich auf eine Höhe des Berges Garizim. Dann erhob er seine Stimme, rief und sprach zu ihnen: \"Hört mich an, ihr Bürger von Sichem, auf daß euch Gott anhöre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Die Bäume sind darangegangen, zu salben einen König über sich. Sie sprachen zu dem Ölbaum: \'Sei du ein König über uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Der Ölbaum sprach zu ihnen: \'Habe ich mein Fett verloren, mit dem man Götter ehrt und Menschen, daß ich für die anderen Bäume zittern sollte?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'So sprachen denn zum Feigenbaum die Bäume: \'Wohlan! Sei du ein König über uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Da sprach der Feigenbaum zu ihnen: \'Habe ich denn meine Süßigkeit verloren und meine edle Frucht, daß ich für die anderen Bäume zittern sollte?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Die Bäume sprachen zu dem Weinstock: \'Wohlan! Sei du ein König aber uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Der Weinstock sprach zu ihnen: \'Habe ich denn meinen Wein verloren, der fröhlich Götter macht und Menschen, daß ich für die anderen Bäume zittern sollte?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Da sprachen zu dem Stechdorn all die Bäume: \'Wohlan! Sei du ein König über uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Da sprach der Stechdorn zu den Bäumen: \'Wollt ihr im Ernst mich über euch zum König machen, dann kommt und berget euch in meinem Schatten! Wo nicht, dann gehe Feuer von dem Stechdorn aus, und dies verzehre auf dem Libanon die Zedern!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Nun denn! Habt ihr ehrlich und redlich gehandelt, als ihr Abimelek zum König machtet? Habt ihr an Jerubbaal und seinem Hause schön gehandelt und ihm vergolten, was seine Hände für euch getan?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Ihr, für die mein Vater kämpfend sein Leben gewagt und die er aus Midians Hand gerettet hat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Und ihr habt euch gegen meines Vaters Haus erhoben, seine Söhne, siebzig Mann, auf einem Stein ermordet und seiner Sklavin Sohn Abimelek zum König gemacht, ihr Bürger von Sichem, weil er euer Bruder sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Habt ihr also ehrlich und redlich an Jerubbaal und seinem Haus gehandelt, dann freut euch Abimeleks, und auch er freue sich eurer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Wenn aber nicht, dann soll von Abimelek Feuer ausgehen und die Bürger Sichems verzehren und das Haus der Bastei! Und von den Bürgern Sichems und von dem Basteihause soll Feuer ausgehen und Abimelek verzehren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Hierauf entwich Jotam, floh und ging nach Beer. Dort saß er in Sicherheit vor seinem Bruder Abimelek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Abimelek herrschte nun über Israel drei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Da sandte Gott einen bösen Geist zwischen Abimelek und die Bürger Sichems, und die Bürger Sichems fielen treulos von Abimelek ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Dadurch sollte der Frevel an Jerubbaals siebzig Söhnen und ihr Blut über ihren Bruder Abimelek kommen, der sie ermordet hatte, ebenso auf Sichems Bürger, die ihm geholfen hatten, seine Brüder zu ermorden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Die Bürger Sichems stellten jetzt auf der Berge Höhen Wegelagerer auf, und diese plünderten jeden, der an ihnen vorüberzog. Dies ward Abimelek gemeldet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Da kam Gaal, Ebeds Sohn, mit seinen Brüdern und ließ sich in Sichem nieder. Auf ihn verließen sich nun Sichems Bürger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Sie gingen auf das Feld hinaus, hielten in ihren Weinbergen Lese und kelterten. Dann feierten sie ein Dankfest, gingen in ihres Gottes Haus, aßen und tranken und lästerten Abimelek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Und Gaal, Ebeds Sohn, sprach: \"Wer ist Abimelek und was ist Sichem, daß wir ihm dienen sollen? Sollten nicht Jerubbaals Sohn und sein Statthalter Zebul den Männern Chamors, des Vaters von Sichem, dienen? Warum sollten wir ihm dienen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Gäbe nur einer dieses Volk in meine Hand, dann wollte ich Abimelek absetzen! Man würde zu Abimelek sagen: \'Dein Dienst hat lange genug gedauert. Nun geh fort!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Der Befehlshaber der Stadt, Zebul, aber hörte von den Reden Gaals, des Ebedsohnes, und ergrimmte darüber:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Er sandte heimlich Boten an Abimelek und ließ sagen: \"Gaal, Ebeds Sohn, ist mit seinen Brüdern nach Sichem gekommen. Nun wiegeln sie die Stadt wider dich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Mach dich also bei Nacht auf, du und das Kriegsvolk bei dir, und lege dich im Feld in einen Hinterhalt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Am Morgen, wenn die Sonne aufgeht, brich auf und überfalle die Stadt! Rückt er dann mit dem Kriegsvolk bei ihm gegen dich, dann tu mit ihm, wie du es vermagst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Da machte sich Abimelek mit dem ganzen Kriegsvolk bei ihm des Nachts auf, und sie legten sich in vier Scharen gegen Sichem in den Hinterhalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Nun kam Gaal, Ebeds Sohn, heraus und stellte sich an den Eingang des Stadttores. Da brach Abimelek mit dem Kriegsvolk bei ihm aus dem Hinterhalt auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Gaal sah das Kriegsvolk. Da sprach er zu Zebul: \"Kriegsvolk kommt von der Berge Höhen.\" Zebul sprach zu ihm: \"Du siehst der Berge Schatten für Männer an.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal hob noch einmal an und sprach: \"Fürwahr! Kriegsvolk steigt von des Landes Mitte. Eine Schar kommt von der Zauberereiche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Da sprach Zebul zu ihm: \"Wo ist jetzt dein Maul, daß du sprachst: \'Wer ist Abimelek daß wir ihm dienen sollen?\' Ist das nicht das Kriegsvolk, das du verachtet hast? Rück doch jetzt aus und streit mit ihm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Da zog Gaal an der Spitze der Bürger von Sichem aus und stritt wider Abimelek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Abimelek aber verfolgte ihn, und er floh vor ihm, und viele Erschlagene fielen bis vor das Stadttor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Dann kehrte Abimelek nach Aruma zurück. Zebul aber vertrieb den Gaal mit seinen Brüdern, daß für sie in Sichem keines Bleibens war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Am anderen Morgen ging das Volk ins Freie. Dies meldete man Abimelek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Da nahm er das Kriegsvolk, teilte es in drei Scharen und legte sich im Freien in den Hinterhalt. Sobald er das Volk aus der Stadt kommen sah, rückte er gegen es und schlug es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelek war nämlich mit den Scharen bei ihm losgebrochen: Dann stellten sie sich vor das Stadttor; die beiden anderen Scharen aber hatten alle im Freien draußen überfallen, und so schlugen sie sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimelek aber berannte die Stadt jenen ganzen Tag. Schließlich eroberte er die Stadt. Nachdem er das Volk darin erschlagen, zerstörte er die Stadt und streute Salz darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Dies hörten alle Bürger des Sichemturmes. Da gingen sie in den Söller im Hause des Bundesgottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Das wurde Abimelek gemeldet: \'Alle Bürger des Sichemturmes sind beisammen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Da stieg Abimelek auf den Salmonberg mit dem ganzen Volke bei ihm. Hier nahm Abimelek die Axt in die Hand, hieb einen Busch ab, hob ihn auf und legte ihn auf die Schulter. Dann sprach er zu dem Volke bei ihm. \"Was ihr mich tun sehet, macht mir schleunigst nach!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Da hieb das ganze Volk, Mann für Mann, Büsche ab. Dann folgten sie Abimelek, warfen sie um den Söller und steckten über ihnen den Söller in Brand. So starben alle Insassen des Sichemturmes, an tausend Männer und Weiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Abimelek zog nun nach Tebes. Er belagerte Tebes und eroberte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Inmitten der Stadt aber war ein starker Turm. Dorthin flohen alle Männer und Weiber sowie alle Edlen der Stadt. Sie riegelten hinter sich zu und stiegen auf das Dach des Turmes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abimelek kam nun bis an den Turm und berannte ihn. Er trat an die Turmtür, sie in Brand zu stecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Da warf ein Weib einen oberen Mühlstein dem Abimelek auf den Kopf und zerschmetterte ihm den Schädel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Da rief er eilends den Burschen, der seine Waffen trug, und sprach zu ihm: \"Ziehe dein Schwert und töte mich, daß sie nicht von mir sagen: \'Ein Weib hat ihn umgebracht!\'\" So durchbohrte ihn sein Bursche, und er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Als Israels Mannschaft sah, daß Abimelek tot war, ging ein jeder heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'So vergalt Gott Abimeleks Freveltat, die er an seinem Vater verübt hatte, als er seine siebzig Brüder erschlug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Ebenso vergalt Gott alle Schlechtigkeit der Männer von Sichem auf ihr Haupt. So traf sie der Fluch des Jerubbaalsohnes Jotam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Nach Abimelek kam zu Israels Rettung Tola, Puas Sohn und Dodus Enkel, aus Issakar. Er saß zu Samir auf dem Gebirge Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Er richtete Israel 2');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Jahre. Dann starb er und ward in Samir begraben. 3 Nach ihm kam der Gileadite Jair und richtete Israel 22 Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Er hatte dreißig Söhne, die auf dreißig Eselsfüllen ritten und dreißig Städte besaßen. Diese nennt man Jairs Zeltdörfer bis auf diesen Tag. Sie sind im Lande Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jair starb und ward in Kanon begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Und wieder taten die Israeliten, was dem Herrn mißfiel, und sie dienten den Baalen und Astarten und den Göttern Syriens, Sidons, Moabs und den Göttern der Ammoniter und der Philister. So verließen sie den Herrn und dienten ihm nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Da entbrannte des Herrn Zorn wider Israel, und er verkaufte sie in die Hand der Philister und der Ammoniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Und diese quälten und plagten die Israeliten zehn Jahre lang, alle Israeliten jenseits des Jordans im Amoriterlande, in Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Dann zogen die Ammoniter über den Jordan, um auch mit Juda, Benjamin und dem Hause Ephraim zu streiten. Und Israel kam in große Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Da schrien die Israeliten zum Herrn und sprachen: \"Wir haben wider Dich gesündigt; denn wir haben in der Tat unseren Gott verlassen und den Baalen gedient.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Da sprach der Herr zu den Israeliten: \"Haben nicht Leute der Ägypter und Amoriter, der Ammoniter und Philister,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Sidonier, Amalek und Maon euch bedrängt? Da schriet ihr zu mir, und ich befreite euch aus ihrer Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Da verließet ihr mich und dientet anderen Göttern. Darum helfe ich euch nicht länger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Geht und ruft zu den Göttern, die ihr erwählt habt! Sie mögen euch in euren Nöten helfen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Da sprachen die Israeliten zum Herrn: \"Wir haben gesündigt. Tu mit uns, wie es Dir gefällt! Nur rette uns jetzt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Und sie schafften des Auslands Götter aus ihrer Mitte und dienten dem Herrn. Da ward er über Israels Elend ungeduldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Die Ammoniter aber wurden wieder aufgeboten und lagerten in Gilead. Da kamen auch die Israeliten zusammen und lagerten in der Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Da sprach das Volk in Gileads Städten zueinander: \"Wer ist der Mann, der mit den Ammonitern zu streiten beginnt? Er soll das Haupt aller Insassen Gileads werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Der Gileaditer Jephte nun war ein tapferer Held, aber Sohn eines Kebsweibes. Als Gilead den Jephte erzeugt hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'gebar Gileads Frau ihm gleichfalls Söhne. Herangewachsen, vertrieben die Söhne dieser Frau den Jephte. Sie sprachen zu ihm: \"Du darfst in unseres Vaters Haus nicht miterben; denn du bist der Sohn eines anderen Weibes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Da entwich Jephte vor seinen Brüdern und weilte im Lande Tob. Da scharten sich um Jephte arme Männer und zogen mit ihm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Nach einiger Zeit stritten die Ammoniter mit Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Als nun die Ammoniter mit Israel stritten, gingen die Ältesten Gileads hin, Jephte aus dem Lande Tob zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Sie sprachen zu Jephte: \"Komm! Sei unser Anführer! Dann wollen wir gegen die Ammoniter streiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Da sprach Jephte zu Gileads Ältesten: \"Habt ihr mich nicht gehaßt, so daß ihr mich aus meines Vaters Haus vertriebet? Warum kommt ihr jetzt zu mir, wo ihr in Not seid?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Da sprachen Gileads Älteste zu Jephte: \"Trotz alledem! Wir sind jetzt anderer Gesinnung gegen dich. Gehst du mit uns und streitest gegen die Ammoniter, dann sollst du uns Haupt sein, allen Insassen Gileads!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Da sprach Jephte zu Gileads Ältesten: \"Wenn ihr mich zurückholt, gegen die Ammoniter zu streiten, und der Herr gibt sie mir preis, werde ich dann euer Haupt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Die Ältesten Gileads sprachen zu Jephte: \"Der Herr hört, was zwischen uns vorgeht; wir tun, wie du verlangst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Da zog Jephte mit Gileads Ältesten, und das Volk machte ihn zum Haupt und Führer über sich. Jephte aber wiederholte all seine Forderungen vor dem Herrn auf der Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Dann sandte Jephte an den Ammoniterkönig Boten mit der Anfrage: \"Was hast du mit mir, daß du zu mir kommst, in meinem Lande zu streiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Da sprach der Ammoniterkönig zu Jephtes Boten: \"Israel hat mein Land weggenommen vom Arnon bis zum Jabbok und Jordan, als es aus Ägypten zog. Gib es gutwillig zurück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Da sandte Jephte nochmals Boten an den Ammoniterkönig');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'und ließ ihm sagen: \"So spricht Jephte: \'Israel hat das Land Moab und das Ammoniterland nicht weggenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Als Israel aus Ägypten kam und in der Wüste zum Schilfmeer zog und nach Kades kam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'sandte Israel Boten an den Edomiterkönig mit der Bitte: \" Ich möchte durch dein Land ziehen.\" Aber Edoms König gab ihm kein Gehör. Auch an Moabs König hatte es gesandt; aber auch er wollte nicht. So saß Israel in Kades.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Dann zog es durch die Wüste, umging das Land Edom und das Moabland und lagerte jenseits des Arnon. So haben sie kein Moabitergebiet betreten. Denn der Arnon ist Moabs Grenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Dann sandte Israel Boten an den Amoriterkönig Sichon, den König zu Chesbon. Israel sprach zu ihm: \"Wir möchten durch dein Land an unsere Stätte ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Aber Sichon hatte Israels Durchzug durch sein Gebiet nicht getraut. Und so sammelte Sichon sein ganzes Volk. Und sie lagerten zu Jahsa. Dann stritt er mit Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Aber der Herr, Israels Gott, gab Sichon mit seinem ganzen Volk in Israels Hand, und sie schlugen sie. So bekam Israel das ganze Land der Amoriter, die in diesem Lande saßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Sie besetzten das ganze Amoritergebiet vom Arnon bis zum Jabbok und von der Wüste bis zum Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Nun denn! Der Herr, Israels Gott, hat die Amoriter wegen seines Volkes Israel enteignet, und da willst du in ihren Besitz treten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Nicht wahr! Wen dein Gott Kasmos enteignet, den verdrängst du. Wen also der Herr, unser Gott, unseretwegen enteignet, den verdrängen wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Nun, bist du viel stärker als Sippors Sohn, Balak, Moabs König? Hat er mit Israel gestritten oder mit ihm gekämpft?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Israel saß doch in Chesbon und seinen Tochterorten, in Aroër und den seinigen und in all den Städten am Arnon dreihundert Jahre. Warum habt ihr sie nicht in dieser Zeit entrissen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Ich habe dir nichts zuleid getan. Du aber tust Unrecht, wenn du mich beschimpfst. Der Herr richte heute als Richter zwischen den Israeliten und den Ammonitern!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Der Ammoniterkönig aber hörte nicht auf Jephtes Worte, die er ihm entboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Da kam der Geist des Herrn über Jephte. Er zog nach Gilead und Manasse. Dann zog er nach Gileads Mispa; von Gileads Mispa aber zog er wider die Ammoniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Und Jephte tat dem Herrn ein Gelübde und sprach: \"Gibst Du mir die Ammoniter in meine Hand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'dann sei das, was mir aus meines Hauses Tür entgegenkommt, des Herrn, falls ich heil von den Ammonitem kehre! Ich will es als Brandopfer darbringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'So zog Jephte, wider die Ammoniter zu streiten. Und der Herr gab sie in seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Er schlug sie ganz gewaltig, von Aroër bis gegen Minnit, zwanzig Städte, und bis Abel, zwanzig Städte. So wurden die Ammoniter vor den Israeliten gebeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Jephte kehrte nach der Mispa zurück. Da kam ihm seine Tochter entgegen mit Pauken und im Reigentanz. Sie war gerade der Liebling. Für ihn gab es weder Sohn noch Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Als er sie sah, zerriß er seine Kleider und sprach. \"Ach meine Tochter! Du beugst mich nieder. Du selbst bist unter meinen Unglücksbringern. Denn ich habe meinen Mund vor dem Herrn aufgetan. Ich kann nicht zurück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Da sprach sie zu ihm: \"Mein Vater! Hast du vor dem Herrn deinen Mund aufgetan, so tu an mir, wie es aus deinem Munde kam, nachdem der Herr dir Rache verschafft an deinen Feinden, den Ammonitern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Und sie sprach zu ihrem Vater: \"Dies sei mir gewährt! Laß mir noch zwei Monate, daß ich hingehe und in den Bergen weile und mein Jungfrauenalter beweine, ich und meine Gespielinnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Er sprach: \"Geh hin!\" Und er entließ sie für zwei Monate. Da ging sie mit ihren Gespielinnen und beweinte auf den Bergen ihr Jungfrauenalter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Nach Verlauf zweier Monate kehrte sie zu ihrem Vater heim. Und er vollzog an ihr sein Gelübde, das er gelobt. Sie hatte noch keinen Mann erkannt. In Israel ward es Sitte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'daß alljährlich Israels Töchter hingingen, des Gileaditers Jephte Tochter jedes Jahr vier Tage zu beklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Da ward Ephraims Mannschaft aufgeboten. Und sie zog gen Saphon. Und sie sprachen zu Jephte: \"Warum bist du in den Kampf wider die Ammoniter gezogen und hast uns nicht gerufen, mit dir zu ziehen? Wir wollen dein Haus über dir anzünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Da sprach Jephte zu ihnen: \"Ich und mein Volk haben einen schweren Kampf mit den Ammonitern gehabt. Ich rief euch; aber ihr habt mich nicht aus ihrer Hand befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Als ich sah, daß du mir nicht halfest, da wagte ich mein Leben und zog aus gegen die Ammoniter. Und der Herr gab sie in meine Hand. Was zieht ihr heute wider mich, mit mir zu streiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Dann bot Jephte alle Männer Gileads auf und stritt mit Ephraim. Da schlugen Gileads Männer Ephraim. Denn dieses pflegte zu sagen: \"Ihr seid Flüchtlinge aus Ephraim.\" Gilead liegt ja zwischen Ephraim und Manasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Und Gilead besetzte die Jordanfurten nach Ephraim. Sagten nun die Flüchtlinge von Ephraim: \"Ich möchte hinüber\", so fragten ihn die Männer Gileads: \"Bist du ein Ephratiter?\" Sagte er: \"Nein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Dann sagten sie zu ihm- \"Sag doch Schibbolet! Sagte er Sibbolet, weil er nicht richtig sprechen konnte, dann griffen sie ihn und metzelten ihn an den Jordanfurten. So fielen damals aus Ephraim 42.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Und Jephte richtete Israel sechs Jahre. Dann starb Jephte, der Gileaditer, und ward in einer der Städte Gileads begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Nach ihm richtete Ibsan aus Bethlehem Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Er hatte dreißig Söhne. Dreißig Töchter gab er auswärts und dreißig Töchter führte er seinen Söhnen von auswärts zu. Er richtete Israel sieben Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Ibsan starb und ward zu Bethlehem begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Nach ihm richtete der Zabulonite Elon Israel. Er richtete Israel zehn Jahre lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Dann starb der Zabulonite Elon und ward zu Ajjalon im Lande Zabulon begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Nach ihm richtete der Piratonite Abdon, Hillels Sohn, Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Er hatte vierzig Söhne und dreißig Enkel, die auf siebzig Eselsfüllen ritten. Er richtete Israel acht Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Dann starb der Piratonite Abdon, Hillels Sohn, und ward zu Piraton im Land Ephraim auf dem Arnalekitergebirge begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Und wieder taten die Israeliten, was dem Herrn mißfiel. Und der Herr gab sie in der Philister Hand vierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Da war ein Mann aus Sora, vom Geschlechte der Daniten, namens Manoach. Sein Weib aber war unfruchtbar und hatte nicht geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Da erschien des Herrn Engel dem Weib und sprach zu ihr: \"Du bist unfruchtbar und hast nicht geboren. Aber du sollst in Hoffnung kommen und einen Sohn gebären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Dann nimm dich in acht! Trink weder Wein noch Bier und iß nichts Unreines!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Denn du kommst in Hoffnung und gebierst einen Sohn. Auf sein Haupt darf aber kein Schermesser kommen! Denn ein Gottgeweihter soll der Knabe schon im Mutterleibe sein. Er wird anfangen, Israel aus der Philister Hand zu befreien.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Da ging das Weib und erzählte ihrem Mann also: \"Ein Gottesmann ist zu mir gekommen. Er war wie ein Engel Gottes, überaus ehrwürdig anzusehen. Ich habe ihn aber nicht gefragt, woher er sei. Auch er hat mir seinen Namen nicht genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Er sagte aber zu mir: \'Du kommst in Hoffnung und gebierst einen Sohn. Trink jetzt weder Wein noch Bier und iß nichts Unreines! Denn ein Gottgeweihter wird der Knabe sein vom Mutterleibe bis zu seinem Todestage.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Da betete Manoach zum Herrn und sprach: \"Mit Vergunst, Herr! Der Gottesmann, den Du gesandt, möge nochmals zu uns kommen und uns belehren, was wir mit dem Knaben tun sollen, der geboren wird!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Und Gott hörte auf Manoachs Stimme. Und so kam der Gottesengel nochmals zu dem Weibe. Sie weilte eben auf dem Felde. Ihr Mann Manoach war aber nicht bei ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Eilends lief das Weib hin und meldete es ihrem Manne und sprach zu ihm: \"Eben ist mir der Mann erschienen, der damals zu mir gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Da stand Manoach auf, folgte seinem Weibe, kam zu dem Mann und sprach zu ihm: \"Bist du der Mann, der mit dem Weibe gesprochen?\" Er sagte: \"Ja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Da sprach Manoach: \"Wenn deine Worte eintreffen, wie soll des Knaben Weise sein und wie sein Tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Da sprach des Herrn Engel zu Manoach: \"Vor all dem, was ich dem Weibe genannt, soll sie sich hüten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Sie genieße gar nichts, was vom Weinstock kommt! Sie trinke weder Wein noch Bier, noch esse sie etwas Unreines! Alles, was ich ihr geboten, soll sie beobachten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Da sprach Manoach zu des Herrn Engel: \"Wir möchten dich aufhalten und dir ein Ziegenböckchen vorsetzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Da sprach des Herrn Engel zu Manoach: \"Wolltest du mich auch aufhalten ich koste doch nicht von deiner Speise. Willst du aber ein Brandopfer bereiten, dann bringe es dem Herrn dar!\" Manoach nämlich wußte nicht, daß es des Herrn Engel war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'So fragte Manoach den Engel des Herrn: \"Wie heißst du? Denn trifft dein Wort ein, möchten wir es dir lohnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Da sprach des Herrn Engel zu ihm: \"Wozu fragst du nach meinem Namen? Ist es doch ein Wunder des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Da nahm Manoach das Ziegenböckchen und das Speiseopfer und brachte es auf dem Felsen dem Herrn dar. Er aber tat Wunderbares. Manoach und sein Weib schauten zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Als die Flamme vom Altar zum Himmel stieg, fuhr des Herrn Engel in der Flamme auf. Manoach und sein Weib sahen es. Da fielen sie zur Erde auf ihr Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Des Herrn Engel aber erschien Manoach und seinem Weibe nicht wieder. Da erkannte Manoach, daß es der Engel des Herrn war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Und Manoach sprach zu seinem Weibe: \"Wir müssen sterben; denn wir haben einen Gott gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Da sprach sein Weib zu ihm: \"Hätte uns der Herr töten wollen, so hätte er nicht Brand- und Speiseopfer von uns angenommen und uns nicht jetzt solches schauen und hören lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Und das Weib gebar einen Sohn. Sie hieß ihn Simson. Der Knabe wuchs heran, und der Herr segnete ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Und der Geist des Herrn begann, ihn anzutreiben in Dans Lager zwischen Sora und Estaol.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Simson aber ging nach Timnat hinab und sah zu Timnat ein philistäisches Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Da ging er hinauf und erzählte es Vater und Mutter. Er sprach: \"Ich habe zu Timnat ein philistäisches Weib gesehen. Freit mir sie jetzt zum Weibe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Da sprachen zu ihm Vater und Mutter: \"Gibt es unter den Töchtern deiner Brüder und in meinem ganzen Volke kein Weib, daß du bei den unbeschnittenen Philistern ein Weib freien willst?\" Simson aber sprach zu seinem Vater: \"Freie mir sie! Denn diese gefällt mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Sein Vater und seine Mutter aber wußten nicht, daß es vom Herrn kam, daß er einen Anlaß gegen die Philister suchte. Zu jener Zeit herrschten nämlich die Philister über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'So ging Simson mit Vater und Mutter nach Timnat hinunter. Sie kamen zu den Weinbergen Timnats. Und da brüllte ihm ein junger Löwe entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Da kam der Geist des Herrn über ihn, und er schlitzte ihn auf, wie man ein Böckchen aufschlitzt. Er hatte dabei nichts in der Hand. Seinem Vater und seiner Mutter aber sagte er nicht, was er getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Dann ging er hinab und warb um das Weib, und sie gefiel Simson.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Nach einiger Zeit kam er wieder, sie heimzuholen. Da bog er ab, das Aas des Löwen zu schauen. Da war in dem Körper des Löwen,ein Bienenschwarm und Honig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Er nahm diesen in seine Hände und aß im Gehen. Und als er zu Vater und Mutter kam, gab er ihnen davon, und sie aßen. Er verriet ihnen aber nicht, daß er den Honig aus dem Körper des Löwen geholt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Dann ging er selber wegen des Weibes hinab. Und Simson veranstaltete dort ein Gelage. Denn so machten es die jungen Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Als sie ihn sahen, wählten sie dreißig Genossen aus, und diese blieben bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Zu diesen sprach Simson: \"Ich will euch ein Rätsel aufgeben. Löst ihr es mir in den sieben Tagen des Gelages, und findet ihr es, dann gebe ich euch dreißig Unterkleider und dreißig Festgewänder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Könnt ihr es mir aber nicht lösen, dann gebt ihr mir dreißig Unterkleider und dreißig Festgewänder.\" Sie sprachen zu ihm: \"Gib dein Rätsel auf, daß wir es vernehmen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Er sprach zu ihnen: \"Fraß ist vom Fresser gekommen, Süßes vom Herben.\" Sie aber konnten während dreier Tage das Rätsel nicht lösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Am vierten Tage sprachen sie zu Simsons Weib: \"Berede deinen Mann, daß er uns des Rätsels Lösung gibt! Sonst verbrennen wir dich und das Haus deines Vaters. Habt ihr uns nur eingeladen, um uns arm zu machen? Oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Da weinte Simsons Weib ihm vor und sprach: \"Nicht anders ist\'s: Du bist mir abgeneigt. Du liebst mich nicht. Hast du nicht meinen Landsleuten ein Rätsel aufgegeben? Und mir sagst du es nicht.\" Er sprach zu ihr: \"Weder Vater noch Mutter habe ich es verraten und dir sollt ich es verraten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Da weinte sie ihm die sieben Tage vor, die das Gelage dauerte. Am siebten Tage aber verriet er es ihr, weil sie ihn gequält hatte. Und sie verriet das Rätsel ihren Landsleuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Am siebten Tage sagten die Leute der Stadt zu ihm, bevor er ins Brautgemach ging: \"Was ist süßer als Honig, und was ist herber als ein Löwe?\" Er sprach zu ihnen: \"Hättet ihr nicht mit meinem Kalbe gepflügt, so hättet ihr mein Rätsel nicht gelöst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Dann überkam ihn der Geist des Herrn. Er stieg nach Askalon hinab und erschlug von ihnen dreißig Mann. Diesen nahm er die Gewandung und gab die Festgewänder den Rätsellösern. Doch ward er darüber zornig und ging zu seines Vaters Haus hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Simsons Weib aber ward seinem Gesellen zuteil, der sein Nebenbuhler gewesen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Nach einiger Zeit, in den Tagen der Weizenernte, besuchte Simson sein Weib mit einem Ziegenböckchen. Er sprach: \"Ich will zu meinem Weibe in die Kammer gehen.\" Aber ihr Vater ließ ihn nicht eintreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Ihr Vater sagte nämlich: \"Ich habe gedacht, du seiest ihr abgeneigt, und so gab ich sie deinem Nebenbuhler. Aber ist nicht ihre jüngere Schwester für dich passender als jene? Sie sei dein an ihrer Statt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Da sprach Simson zu ihnen: \"Diesmal bin ich schuldfrei an den Philistern, wenn ich ihnen Schlimmes antue.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Und Simson ging, fing dreihundert Füchse, nahm Fackeln, band Schweif an Schweif und tat je eine Fackel zwischen zwei Schweife in die Mitte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Dann steckte er die Fackeln in Brand und ließ sie los in die Saaten der Philister. So verbrannte er Garben, Halme,Weinberge und Olivenbäume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Die Philister fragten: \"Wer hat dies getan?\" Man sagte: \"Des Timniters Eidam Simson. Er hat ihm ja sein Weib genommen; dann gab er es seinem Nebenbuhler. Da zogen die Philister hinauf und verbrannten sie und ihren Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Da sprach Simson zu ihnen: \"Wenn ihr so tut, dann räche ich mich ein für allemal an euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Und er schlug sie ganz gewaltig auf Hügeln und in Tälern. Dann stieg er hinab und weilte in der Felsenkluft von Etam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Da zogen die Philister herauf, lagerten wider Juda und ließen sich in dem Engpasse nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Da fragte Judas Mannschaft: \"Warum zieht ihr gegen uns herauf?\" Da sagten sie: \"Wir ziehen herauf, Simson zu fesseln und ihm zu tun, wie er uns getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Da zogen dreitausend Mann aus Juda nach der Felsenkluft von Etam hinab und sprachen zu Simson: \"Weißt du nicht, daß die Philister über uns herrschen? Warum tust du uns dies an?\" Er sprach zu ihnen: \"Wie sie mir getan, so habe ich ihnen getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Und sie sprachen zu ihm: \"Wir sind herabgekommen, dich zu fesseln und dich den Philistern auszuliefern.\" Simson sprach zu ihnen: \"Schwört mir, daß ihr mich nicht erschlagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Sie sprachen zu ihm: \"Nein! Wir wollen dich nur fesseln und dich in ihre Hand geben. Aber töten wollen wir dich nicht.\" So fesselten sie ihn mit zwei neuen Stricken und führten ihn aus der Felsenschlucht herauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'So kam er in den Engpaß, und die Philister jauchzten ihm entgegen. Da kam der Geist des Herrn über ihn. Und die Stricke an seinen Armen wurden wie Fäden, vom Feuer versengt, und die Fesseln glitten ihm von den Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Er fand auch in dem Eselspaß einen Pfahl, streckte seine Hand aus, griff ihn und schlug damit 1.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Und Simson sprach: \"Im Eselspaß habe ich sie gründlich geschunden. Im Eselspaß habe ich 1.000 Mann erschlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Als er ausgeredet, warf er ihn in den Paß. Man nannte jenen Ort Ramat Lechi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Da ward er sehr durstig. Und er rief zum Herrn und sprach: \"Du hast durch Deines Dieners Hand diesen großen Sieg geschaffen. Nun werde ich vor Durst sterben und falle dann in der Unbeschnittenen Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Da ließ Gott die Höhle in der Eselsschlucht überquellen, und Wasser floß heraus. Er trank, und sein Geist lebte auf. Daher nannte man sie \"Des Rufers Quelle in der Schlucht\" bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Und er richtete Israel zur Zeit der Philister zwanzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Simson ging nun nach Gaza. Da sah er dort eine Dirne und ging zu ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Bei den Leuten von Gaza hieß es nun: \"Simson ist hierhergekommen.\" Da stellten sie sich ringsum auf und lauerten ihm ganz heimlich am Stadttor auf. Sie blieben aber die ganze Nacht ruhig, weil sie sagten: \"Erst wenn der Morgen tagt, erschlagen wir ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Simson aber schlief bis Mitternacht. Um Mitternacht aber stand er auf, packte die Stadttorflügel samt den beiden Pfosten, hob sie samt dem Riegel aus, legte sie auf seine Schultern und trug sie auf den Gipfel des Berges gegenüber Hebron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Später liebte er ein Weib am Bache Sorek. Sie hieß Delila.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Da kamen die Philisterfürsten zu ihr herauf und redeten ihr zu: \"Berede ihn und sieh zu, wodurch seine Kraft so groß ist und womit wir ihm beikommen können, daß wir ihn fesseln und bezwingen! Dann geben wir, Mann für Mann, dir elfhundert Silberringe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Da sprach Delila zu Simson: \"Sag mir doch, wodurch deine Kraft so groß ist und womit du gefesselt werden mußt, daß man dich bezwinge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson sprach zu ihr: \"Bände man mich mit sieben frischen, feuchten Saiten, dann würde ich schwach und würde wie ein anderer Mensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Da brachten die Philisterfürsten sieben frische, feuchte Saiten, und sie band ihn damit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Bei ihr im Gemache aber saß der Aufpasser. Da sprach sie zu ihm: \"Simson! Die Philister sind über dir.\" Da zerriß er die Saiten, wie ein Wergfaden zerreißt, wenn er Feuer spürt. So blieb seine Kraft unerkundet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Da sprach Delila zu Simson: \"Du hast mich genarrt und mir Lügen vorgeredet. Sag mir jetzt, womit du gefesselt werden mußt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Er sagte ihr: \"Bände man mich mit neun neuen Stricken, mit denen noch keine Arbeit getan worden, dann würde ich schwach und wie ein anderer Mensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Da nahm Delila neue Stricke und fesselte ihn damit. Dann sprach sie zu ihm: \"Die Philister sind über dir, Simson.\" Der Aufpasser aber saß im inneren Gemach. Da riß er sie von seinen Armen wie einen Faden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Da sprach Delila zu Simson: \"Bisher hast du mich genarrt und mir Lügen vorgeredet. Sag mir doch, womit du gefesselt werden mußt!\" Da sagte er ihr: \"Wenn du die sieben Locken meines Hauptes mit der Decke verflöchtest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Da klopfte sie an den Pflock und sprach zu ihm: \"Simson! Die Philister sind über dir.\" Da erwachte er aus seinem Schlaf und riß den Pflock, das Geflecht und die Decke aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Da sagte sie zu ihm: \"Wie kannst du behaupten, du liebest mich? Dein Herz ist nicht bei mir. Dreimal hast du mich genarrt und mir nicht gesagt, wodurch deine Kraft so groß ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'So setzte sie ihm mit ihren Reden unaufhörlich zu und quälte ihn. Da ward seine Seele zum Sterben ungeduldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Und so entdeckte er ihr sein ganzes Herz und sprach zu ihr: \"Auf mein Haupt ist noch nie ein Schermesser gekommen. Denn ich bin vom Mutterleibe an ein Gottgeweihter. Würde ich geschoren, so wiche meine Kraft von mir. Ich würde schwach und wäre wie jeder andere Mensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Da sah Delila, daß er ihr sein ganzes Herz verraten hatte. Sie sandte hin und ließ die Philisterfürsten rufen und ihnen sagen: \"Kommt diesmal! Er hat mir sein ganzes Herz verraten.\" Da kamen die Philisterfürsten zu ihr und brachten das Geld mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Nun ließ sie ihn auf ihrem Schoße einschlafen. Dann rief sie nach einem Schermesser und schnitt ihm die sieben Locken seines Hauptes ab. Da ward es mit ihm immer schwächer, und seine Kraft wich von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Sie sprach: \"Simson! Die Philister sind über dir.\" Da wachte er aus seinem Schlafe und dachte: \"Ich will hinaus wie sonst und mich aufraffen.\" Er wußte aber nicht, daß der Herr von ihm gewichen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Da griffen ihn die Philister und stachen ihm die Augen aus. Dann führten sie ihn nach Gaza hinab und schlugen ihn in eherne Fesseln. Da mußte er die Mühle im Gefängnis drehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Sein Haupthaar aber begann wieder zu wachsen, so wie es abgeschoren war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Nun kamen die Philisterfürsten zusammen, ihrem Gott Dagon ein großes Opferfest zu bereiten und sich zu freuen; denn sie sagten: \"Unser Gott hat unseren Feind Simson in unsere Hand gegeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Auch das Volk hörte von ihm, und sie priesen ihren Gott; denn sie sagten: \"Unser Gott hat unseren Feind in unsere Hand gegeben, den Verwüster unseres Landes, ihn, der so viele von uns erschlagen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Als sie nun guter Dinge wurden, sprachen sie: \"Ruft Simson herbei, daß er uns belustige!\" Da rief man Simson aus dem Gefängnis, und er mußte sie belustigen. Sie stellten ihn zwischen die Säulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Da sprach er zu dem Knaben, der ihn an der Hand hielt: \"Laß mich die Säulen betasten, auf denen das Haus ruht! Ich möchte daran lehnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Das Haus aber war voller Männer und Weiber. Auch alle Philisterfürsten waren hier zugegen, und auf dem Dache waren an 3.000 Männer und Weiber, die Simsons Spiele zusahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Da rief Simson zum Herrn und sprach: \"Herr, ach Herr! Gedenke meiner und stärke mich nur diesmal, o Gott! Ich will für meine beiden Augen einmalige Rache an den Philistern nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Dann umschlang Simson die beiden Mittelsäulen, auf denen das Haus ruhte, und drückte darauf, auf die eine mit dem rechten, auf die andere mit dem linken Arm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Dann sprach Simson: \"Nun sterbe ich mit den Philistern.\" Und er neigte sich mit Macht, und das Haus fiel auf die Fürsten und alles Volk darin. So wurden es der Toten, die er getötet hatte, bei seinem Tode mehr als derer, die er bei Lebzeiten getötet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Dann kamen seine Brüder und sein ganzes Vaterhaus herab, holten ihn hinauf und begruben ihn zwischen Sora und Estaol in seines Vaters Manoach Grab. Er hatte Israel zwanzig Jahre gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Auf dem Gebirge Ephraim war ein Mann namens Micha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Dieser sprach zu seiner Mutter: \"Die elfhundert Silberringe, die dir entwendet worden sind und derentwegen du geflucht und es laut vor mir gesagt hast, dies Geld ist bei mir. Ich habe es entwendet.\" Da sprach seine Mutter \"Mein Sohn! Sei vom Herrn gesegnet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Da gab er die elfhundert Silberringe seiner Mutter zurück. Seine Mutter aber sprach: \"Ich weihe dieses Geld dem Herrn aus meiner Hand für meinen Sohn, um daraus ein Bildnis mit Umhang zu machen. Als solches gebe ich es dir wieder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Da brachte er das Geld seiner Mutter. Seine Mutter aber nahm zweihundert Silberringe und gab sie einem Goldschmied. Dieser machte daraus ein Bildnis mit Umhang. Dies kam in Michas Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Und dieser Mann, Micha, machte sich ein Gotteshaus, fertigte Ephod und Teraphim und weihte einen seiner Söhne, und der ward ihm Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Zu jener Zeit war kein König in Israel. Jeder tat, was ihm gut dünkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Nun war ein junger Mann aus Bethlehem in Juda aus Judas Sippe. Er war Levite und dort zu Gast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Nun ging der Mann aus der Stadt Bethlehem in Juda, irgendwo zu Gaste zu sein. So kam er auf das Gebirge Ephraim zu Michas Haus und sprach hier vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Micha fragte ihn: \"Woher kommst du?\" Er antwortete ihm: \"Ich bin ein Levite aus Bethlehem in Juda. Ich bin auf der Reise, mich irgendwo niederzulassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Da sprach Micha zu ihm: \"Bleib bei mir und sei mir Vater und Priester! Ich gebe dir jährlich zehn Silberringe und Kleidung und deinen Lebensunterhalt.\" Und der Levite ging darauf ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'So entschloß sich also der Levite, bei dem Manne zu bleiben. Und der junge Mann war bei ihm wie einer seiner Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Und Micha weihte den Leviten. Und der junge Mann ward sein Priester und blieb in Michas Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Da sprach Micha: jetzt weiß ich, daß der Herr mir wohltun wird, weil ich den Leviten zum Priester habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Zu jener Zeit gab es keinen König in Israel. Damals suchte sich der Danitenstamm einen Erbbesitz zur Siedlung. Denn ihm war bis dahin inmitten der Stämme Israels kein Erbbesitz zugefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'So schickten die Daniten fünf Männer aus ihrer Sippe, aus ihren Beamten, die tüchtigsten Männer aus Sora und Estaol aus, das Land zu erkunden und auszuforschen. Sie sprachen zu ihnen: \"Zieht hin! Erforscht das Land!\" So kamen sie auf das Gebirge Ephraim zu Michas Haus und übernachteten hier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Sie waren eben bei Michas Haus. Da hatten sie die Mundart des jungen Leviten erkannt. Und sie kehrten hier ein und fragten ihn: \"Wer hat dich hierher gebracht? Was tust du da? Was hast du hier?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Er sprach zu ihnen: \"So und so hat es Micha mit mir gemacht. Er dingte mich, und ich ward sein Priester.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Da sprachen sie zu ihm: \"Befrag doch Gott, damit wir wissen, ob unser Weg gelingt, auf dem wir sind!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Da sprach der Priester zu ihnen: \"Geht getrost! Dem Herrn ist euer Weg genehm, auf dem ihr seid.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'So zogen die fünf Männer fort und kamen nach Lais. Sie fanden das Volk darin ruhig wohnen, nach Art der Sidonier, sorglos und ruhig. Keiner, der im Lande Macht besaß, tat etwas Schimpfliches. Auch waren sie fern von den Sidoniern und hatten mit niemandem eine Verabredung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'So kamen sie wieder zu ihren Brüdern nach Sora und Estaol, und ihre Brüder fragten sie: \"Was sagt ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Sie sprachen: \"Auf! Laßt uns gegen jene ziehen! Wir haben das Land beschaut, und es ist ganz passend. Seid ihr noch unschlüssig? Zögert nicht, hinzuziehen und das Land zu besetzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kommt ihr hin, so kommt ihr zu einem sorglosen Volk, und das Land ist weitläufig, und der Herr gibt es in eure Hand: ein Ort, wo an nichts, was es auf Erden gibt, Mangel ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'So zogen von dort aus der Danitensippe sechshundert waffengerüstete Männer aus Sora und Estaol.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Sie stiegen hinan und lagerten sich zu Kirjat Jearim in Juda. Daher nennt man jenen Ort \"Dans Lager\" bis auf diesen Tag. Er liegt hinter Kirjat Jearim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Von dort zogen sie nach dem Gebirge Ephraim. So kamen sie zu Michas Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Da hoben die fünf Männer an, die ausgezogen waren, das Land von Lais zu erkunden, und sprachen zu ihren Brüdern: \"Wißt ihr, daß in diesen Häusern Ephod und Teraphim sind und ein Bildnis mit Umhang? Seht jetzt zu, was ihr tut!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Sie bogen dorthin ab und kamen in das Haus des jungen Leviten, zu Michas Haus, und fragten ihn nach dem Befinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Die sechshundert Mann von den Daniten aber standen kriegsgerüstet am offenen Tor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Die fünf Männer nun, die das Land zu erkunden ausgezogen und hierher gekommen waren, gingen hinauf und holten das Bildnis, den Ephod, die Teraphim und den Umhang. Der Priester aber stand am offenen Tor, ebenso die sechshundert bewaffneten Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Jene gingen also in Michas Haus und holten das Bildnis, den Ephod, die Teraphim und den Umhang. Da sprach der Priester zu ihnen: \"Was macht ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Sie sprachen zu ihm: \"Schweig still! Leg die Hand auf den Mund! Geh mit uns und werde uns Vater und Priester! Willst du lieber Priester für das Haus eines Mannes sein oder Priester für einen Stamm und eine Sippe in Israel?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Dies gefiel dem Priester. Er nahm den Ephod, die Teraphim und das Bildnis und trat in die Mitte der Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Sie wandten sich nun und zogen ab. Die Kinder aber, das Vieh und die Sklaven stellten sie voran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Kaum hatten sie sich von Michas Haus entfernt, als die Männer in den Häusern um Michas Haus aufgeboten wurden. Und sie holten die Daniten ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Dann riefen sie die Söhne Dans an. Diese wandten sich und sprachen zu Micha: \"Was ist dir, daß du das Aufgebot gemacht hast?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Er sprach: \"Ihr nehmt meinen Gott weg, den ich gemacht, samt dem Priester und geht davon. Was bleibt mir noch? Wie könnt ihr fragen: \'Was ist dir?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Da sprachen Dans Söhne zu ihm: \"Laß uns nichts weiter hören! Sonst könnten Männer erbitterten Gemüts euch anfallen. Und dann kannst du dich und dein Haus zusammensuchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'So zogen die Daniten ihres Wegs. Micha aber sah, daß sie ihm zu stark waren und kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Sie nahmen also mit, was Micha hatte machen lassen, samt dem Priester, den er besaß. So zogen sie bis Lais, gegen ein ruhig und sorglos lebendes Volk, schlugen sie mit des Schwertes Schärfe und verbrannten die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Niemand aber half; denn sie lag zu weit von Sidon und hatte mit niemandem Verabredung. Sie lag in der Ebene von Bet Rechob. Sie bauten die Stadt wieder auf und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Und sie nannten die Stadt \"Dan\" nach dem Namen ihres Ahnen Dan, der Israel geboren ward. Früher hieß die Stadt Lais.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Die Daniten stellten nun das Bildnis auf, und Jonatan, der Sohn Gersoms und Enkel Manasses, er und seine Söhne wurden Priester für den Stamm der Daniten bis zur Wegführung aus dem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Sie hatten das Bildnis, das Micha gemacht hatte, die ganze Zeit aufgestellt, solange das Gotteshaus in Silo war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'In jener Zeit, als es keinen König in Israel gab, war ein levitischer Mann auf der Rückseite des Gebirges Ephraim zu Gast. Er nahm sich ein Mädchen aus Bethlehem in Juda zum Nebenweib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Sein Nebenweib aber betrog ihn und ging von ihm in ihres Vaters Haus nach Bethlehem in Juda. Dort lebte sie vier Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Da machte sich ihr Mann auf und ging ihr nach, ihr zuzureden und sie zurückzugewinnen. Er aber hatte seinen Burschen und ein paar Esel bei sich. Sie führte ihn nun in ihres Vaters Haus. Da sah ihn des Mädchens Vater und freute sich über seine Ankunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Und sein Schwiegervater, des Mädchens Vater, gab ihm die Hand, und er blieb drei Tage bei ihm. Sie aßen und tranken und blieben über Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Am vierten Tage standen sie früh auf, und er erhob sich zu gehen. Da sprach des Mädchens Vater zu seinem Schwiegersohn: \"Stärke dein Herz mit einem Bissen Brot! Hernach mögt ihr reisen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Sie setzten sich, aßen beide zusammen und tranken. Dann sprach des Mädchens Vater zu dem Mann: \"Entschließe dich und bleibe über Nacht und sei guter Dinge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Der Mann aber stand auf, um zu gehen. Aber sein Schwiegervater drang in ihn, und er blieb nochmals über Nacht da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Am fünften Tage stand er früh auf, um zu gehen. Da sprach des Mädchens Vater: \"Stärke doch dein Herz und verweilet bis zur Neige des Tages!\" So aßen sie miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Dann stand der Mann auf, um zu gehen, er, sein Nebenweib und sein Diener. Da sprach sein Schwiegervater, des Mädchens Vater, zu ihm: \"Der Tag neigt sich zum Abendwerden. Bleibt doch über Nacht! Der Tag geht zur Neige, bleibe hier über Nacht und sei guter Dinge! Morgen früh zieht eures Wegs, daß du zu deinem Zelte kommst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Aber der Mann wollte nicht mehr übernachten. Er stand auf, zog fort und kam bis vor Jebus, das ist Jerusalem. Er hatte ein Paar gesattelter Esel bei sich und sein Nebenweib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Sie waren eben bei Jebus, als es spät am Tage wurde! Da sprach der Bursche zu seinem Herrn: \"Komm! Laßt uns in dieser Jebusiterstadt einkehren und hier übernachten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Aber sein Herr sprach zu ihm: \"Wir wollen nicht in einer fremden Stadt einkehren, in der kein Israelite ist. Wir ziehen weiter bis Gibea.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Dann sprach er zu seinem Burschen: \"Komm! Wir wollen nach einer der Ortschaften gehen! Wir übernachten in Gibea oder in Rama.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'So zogen sie des Weges weiter. Da ging die Sonne unter bei Gibea in Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Hier bogen sie nun vom Wege ab, um in Gibea zu übernachten. Als er ankam, setzte er sich auf den Marktplatz der Stadt. Aber niemand nahm sie ins Haus zum Übernachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Da kam ein alter Mann abends von seiner Feldarbeit. Der Mann war vom Gebirge Ephraim und selber Fremdling zu Gibea. Die Leute des Ortes aber waren Benjaminiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Er hob nun seine Augen und sah den Wandersmann auf dem Marktplatz der Stadt. Da fragte der alte Mann: \"Wohin gehst du? Woher kommst du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Er sprach zu ihm: \"Wir ziehen von Bethlehem in Juda nach der Rückseite des Gebirges Ephraim. Ich bin von dort. Ich reiste nach Bethlehem in Juda. Ich bin nun unterwegs nach dem eigenen Hause. Aber niemand nimmt mich in sein Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Wir haben Stroh und Futter für unsere Esel. Auch Brot und Wein für mich und deine Magd und für den Burschen sind bei deinem Sklaven. Es fehlt an nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Da sprach der alte Mann: \"Friede sei mit dir! Mir obliege all dein Mangel allein! Nur auf der Straße darfst du nicht übemachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Dann führte er ihn in sein Haus und fütterte die Esel. Sie aber wuschen sich die Füße, aßen und tranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Sie taten eben ihrem Herzen gütlich. Da umringten die Männer der Stadt, Teufelsbuben, das Haus, klopften an die Tür und sprachen zu dem alten Mann, dem Herrn des Hauses: \"Gib den Mann heraus, der in dein Haus gekommen, daß wir ihn erkennen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Da ging der Mann, der Hausherr, zu ihnen hinaus und sprach zu ihnen: \"Nicht doch! Meine Brüder! Tut doch nichts Böses! Nachdem dieser Mann in mein Haus gekommen, dürft ihr keine solche Schandtat tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Da ist meine jungfräuliche Tochter und ihre Dienerin. Ich will sie herausgeben. Ihnen tut Gewalt an! Mit ihnen tut nach eurer Laune! Aber diesem Manne dürft ihr keine solche Schandtat antun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Aber die Männer wollten nicht auf ihn hören. Da ergriff der Mann sein Nebenweib und brachte sie ihnen auf die Straße. Und sie erkannten sie und trieben Mutwillen mit ihr die ganze Nacht bis zum Morgen. Sie ließen sie erst los beim Anbruch der Morgenröte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Bei der Morgenwende aber kam das Weib und fiel nieder vor der Haustür des Mannes, bei dem ihr Herr war, und lag so bis zum lichten Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Ihr Herr aber stand am Morgen auf, öffnete die Haustür und trat hinaus, um seines Weges zu ziehen. Da lag das Weib, sein Nebenweib, vor der Haustür, die Hände auf der Schwelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Er sprach sie an: \"Steh auf! Wir wollen fort.\" Aber keine Antwort! Da lud er sie auf den Esel. Und der Mann machte sich auf und zog nach seiner Heimat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Als er heimkam, nahm er das Messer, faßte sein Nebenweib, zerstückelte es völlig in zwölf Stücke und sandte sie umher im ganzen Bereiche Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Da rief jeder, der es sah: \"Solches ist nicht geschehen und nicht gesehen worden seit der Zeit, da Israels Söhne aus Ägypterland gezogen, bis auf diesen Tag. Denkt darüber nach! Ratet und sprechetl\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Da zogen alle Söhne Israels aus, und die Gemeinde sammelte sich wie ein Mann von Dan bis Beerseba, dazu das Land Gilead, vor dem Herrn auf der Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Und die Vorkämpfer des ganzen Volkes, alle Stämme Israels, stellten sich ein in der Gemeinde des Gottesvolkes, 400.000 Mann zu Fuß, Schwertträger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Die Benjaminiten aber hörten, die Söhne Israels seien nach der Mispa gezogen. Die Söhne Israels hatten nämlich sagen lassen: \"Sagt an! Wie ist diese schlimme Tat geschehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Da antwortete der levitische Mann, der Mann des gemordeten Weibes, und sprach: \"Ich bin mit meinem Nebenweibe nach Gibea in Benjamin gekommen zu übernachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Da erhoben sich Gibeas Bürger gegen mich und umringten meinetwegen nachts das Haus. Mich umzubringen, sind sie bedacht gewesen, und mein Nebenweib haben sie so vergewaltigt, daß es starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Da nahm ich mein Nebenweib, zerstückelte es und sandte es im ganzen Bereiche des israelitischen Eigenbesitzes umher. Denn sie haben in Israel Niedertracht und Schandtat begangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Wohlan! Ihr Söhne Israels insgesamt! Schafft hier Bescheid und Rat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Da erhob sich das ganze Volk wie ein Mann und sprach: \"Keiner gehe in sein Zelt! Keiner nach Hause!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Nun denn! Das ist es, was wir mit Gibea tun wollen: \'Nach dem Lose über sie her!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Wir nehmen zehn Mann von hundert aus allen Stämmen Israels, hundert von tausend und tausend von zehntausend. Sie sollen Zehrung für das Kriegsvolk schaffen, auf daß das Volk gegen Gibea in Benjamin ziehe, nach der Schandtat, die es in Israel verübte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Da brachte alle Mannschaft Israels wie ein Mann Zehrung in die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Dann sandten die Stämme Israels Männer zum ganzen Benjaminstamm mit der Botschaft: \"Welch eine Untat ist bei euch geschehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Gebt die Männer heraus, die Teufelsbuben, in Gibea, daß wir sie töten und das Schlimme aus Israel tilgen!\" Aber die Benjaminiten wollten nicht auf die Stimme ihrer israelitischen Brüder hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Und die Benjaminiten aus den anderen Städten versammelten sich in Gibea, gegen die Israeliten in den Kampf zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Und die Benjaminiten aus den Städten wurden an jenem Tag gemustert, 26.000 Schwertbewaffnete, außer Gibeas Einwohnern. Dann wurden 700 Auserlesene gemustert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Von all diesem Volk waren 700 Auserlesene linkshändig. Jeder von ihnen schleuderte mit Steinen haarscharf, ohne zu fehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Auch Israels Mannschaft ward gemustert. Ohne Benjamin waren es 400.000 Schwertbewaffnete, lauter Kriegsleute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Sie erhoben sich nun und zogen nach Betel hinauf und befragten Gott. Die Israeliten fragten: \"Wer von uns zieht zuerst zum Kampfe wider die Benjaminiten hinauf?\" Der Herr sprach: \"Juda zuerst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Am Morgen erhoben sich die Israeliten und lagerten gegen Gibea.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Da zog Israels Mannschaft zum Kampfe gegen Benjamin bei Gibea. Israels Mannschaft aber bot ihnen den Kampf an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Da rückten die Benjaminiten aus Gibea und streckten an jenem Tage von Israel 22.000 Mann nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Da ermannte sich das Kriegsvolk, Israels Mannschaft, und bot ihnen nochmals den Kampf an, am selben Platze, wo sie ihn am ersten Tage angeboten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Dann gingen die Israeliten hinauf und weinten vor dem Herrn bis zum Abend. Dann befragten sie den Herrn und sprachen: \"Soll ich noch einmal zum Kampf gegen meinen Bruder Benjamin ausrücken?\" Der Herr sprach: \"Zieht gegen sie!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Am zweiten Tage nun zogen die Israeliten gegen die Benjaminiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Und am zweiten Tage zog ihnen Benjamin aus Gibea entgegen und streckte von den Israeliten abermals 18.000 Mann nieder, lauter Schwertbewaffnete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Da gingen alle Israeliten, und zwar das gesamte Kriegsvolk, hinauf. Sie kamen nach Betel und weinten und saßen dort vor dem Herrn und fasteten an jenem Tage bis Abend. Dann brachten sie Brand- und Mahlopfer vor dem Herrn dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Darauf befragten die Israeliten den Herrn. Denn dort war zu jener Zeit die Bundeslade Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Zu jener Zeit diente ihm Pinechas, Eleazars Sohn und Aarons Enkel. Sie sprachen: \"Soll ich noch einmal zum Kampf gegen meinen Bruder Benjamin ziehen oder soll ich es lassen?\" Der Herr sprach: \"Zieht aus! Denn morgen gebe ich ihn in deine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Nun legte Israel einen Hinterhalt rings um Gibea.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Dann zogen die Israeliten gegen die Benjaminiten am dritten Tage und stellten sich wider Gibea wie die vorigen Male auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Da rückten die Benjaminiten dem Kriegsvolk entgegen. Sie ließen sich aber von der Stadt weglocken und begannen, wie die vorigen Male, einige vom Kriegsvolk zu erschlagen auf den Straßen, deren eine nach Betel und die andere nach Gibea führt, auf freiem Felde, gegen dreißig Mann von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Da dachten die Benjaminiten: \"Sie werden von uns geschlagen wie das erstemal.\" Die Israeliten aber hatten gesagt: \"Laßt uns fliehen, daß wir sie von der Stadt nach den Straßen locken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Da erhob sich Israels ganze Mannschaft aus ihrem Ort und stellte sich bei Baal Tamar auf. Dann brach Israel aus seinem Standort im Hinterhalt hervor, aus einer Waldlichtung bei Geba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'So kamen, Gibea gegenüber, 10.000 aus ganz Israel erlesene Männer heran. Und der Kampf ward heftig. Sie wußten aber nicht, daß das Verderben ihnen nahte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'So schlug der Herr durch Israel Benjamin. Und die Israeliten schlugen an jenem Tag von Benjamin 25.100 Mann, lauter Schwertbewaffnete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Die Benjaminiten sahen nun, daß sie geschlagen waren. Israels Mannschaft aber gab Benjamin Raum, weil sie sich auf den Hinterhalt verließen, den sie bei Gibea gelegt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Nun brach plötzlich der Hinterhalt vor und schwärmte gegen Gibea aus. Und der Hinterhalt rückte vor und schlug die ganze Stadt mit des Schwertes Schärfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Die Mannschaft Israels aber hatte mit dem Hinterhalt, der einfallen sollte, eine Abmachung getroffen, er solle eine starke Rauchsäule aus der Stadt aufsteigen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Nun wandte Israels Mannschaft sich im Kampf, und Benjamin begann, schon etliche der Mannschaft Israels, etwa dreißig Mann, zu erschlagen; denn sie dachten: Sie erliegen uns wie in der ersten Schlacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Da begann der Brand, und aus der Stadt stieg eine Rauchsäule auf. Als Benjamin zurückschaute, war die ganze Stadt himmelhoch in Flammen aufgegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Israels Mannschaft aber hatte kehrt gemacht; so ward Benjamins Mannschaft verwirrt. Denn sie sahen, daß sie das Verderben ereilt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'So wandten sie sich vor Israels Mannschaft auf den Weg zur Wüste. Der Kampf hatte sich an sie geheftet, und die aus der Vorhut setzten ihnen zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Inzwischen hatten sie Benjamin umzingelt, verfolgt und mühelos niedergekämpft bis östlich Gibea gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Dabei fielen von Benjamin 18.000 Mann, lauter tapfere Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Sie wandten sich zur Flucht nach der Wüste gegen den Rimmonfelsen hin. Jene aber hielten auf den Straßen unter ihnen eine Nachlese von fünftausend Mann und verfolgten sie bis zur Vernichtung und schlugen von ihnen noch zweitausend Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'So waren aus Benjamin an jenem Tag insgesamt 25.000 Schwertbewaffnete gefallen, lauter tapfere Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Sie wandten sich nun und flohen nach der Wüste gegen den Rimmonfelsen hin, sechshundert Mann. Und sie blieben beim Rimmonfelsen vier Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Israels Mannschaft aber kehrte zu den anderen Benjaminiten zurück und schlug sie mit des Schwertes Schärfe, außerhalb der Städte, von den Männern bis zum Vieh, alles, was sich vorfand. Auch alle vorgefundenen Städte steckten sie in Brand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Israels Mannschaft aber hatte auf der Mispa geschworen: \"Keiner von uns darf seine Tochter Benjamin zum Weibe geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Und das Volk kam nach Betel und saß dort bis zum Abend vor Gott. Und sie erhoben ihre Stimme, weinten laut und sprachen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, '\"Warum, Herr, Gott Israels, ist dies in Israel geschehen, daß heute aus Israel ein Stamm vermißt wird?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Das Volk aber baute am anderen Morgen früh dort einen Altar und brachte Brand- und Dankopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Dann fragten die Israeliten: \"Wer von allen Stämmen Israels ist es, der nicht mit der Gemeinde zum Herrn heraufgezogen ist?\" Denn der große Schwur war gegen den ausgesprochen worden, der nicht zum Herrn nach der Mispa käme: \"Er soll des Todes sterben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Da tat es den Israeliten leid um ihren Bruder Benjamin, und sie sprachen: \"Heute ist ein Stamm aus Israel ausgerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Wie können wir den Übriggebliebenen zu Weibern verhelfen? Wir haben ja beim Herrn geschworen, daß wir keine unserer Töchter an sie verheiraten wollen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Da sprachen sie: \"Welcher von Israels Stämmen ist nicht zum Herrn nach der Mispa gezogen?\" Da fand sich, daß aus Jabes in Gilead niemand ins Lager zur Versammlung gekommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Da ward das Volk gemustert, und wirklich war aus Jabes in Gilead niemand da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Da sandte die Gemeinde 12.000 der tapfersten Männer dahin und befahl ihnen: \"Geht hin und schlagt die Einwohner von Jabes in Gilead mit des Schwertes Schärfe, Weiber und Kinder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Und so sollt ihr es machen: Bannt alle Mannsbilder und alle Weiber, die männliches Beilager erkannt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Da fanden sich unter den Einwohnern von Jabes in Gilead 400 jungfräuliche Mädchen, die noch keinen Mann in männlichem Beilager erkannt hatten. Diese brachten sie ins Lager zu Silo im Lande Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Dann sandte die ganze Gemeinde hin und verhandelte mit den Benjaminiten beim Rimmonsfelsen. Und sie entboten ihnen Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Da kehrten die Benjaminiten in jener Zeit zurück, und man gab ihnen Weiber, die man von den Weibern zu Jabes in Gilead am Leben gelassen hatte. Aber sie reichten ihnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Da tat es dem Volk um Benjamin leid, daß der Herr einen Riß in die Stämme gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'So sprachen die Ältesten der Gemeinde: \"Wie können wir den Übriggebliebenen zu Weibern verhelfen? Sind doch aus Benjamin die Weiber ausgerottet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Sie sprachen: \"Eine Möglichkeit der Rettung gäbe es für Benjamin! Kein Stamm aus Israel darf doch getilgt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Wir aber können ihnen keine Weiber aus unseren Töchtern geben; denn die Israeliten haben geschworen: \'Verflucht sei, wer Benjamin ein Weib gibt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Dann sprachen sie: \"Das Fest des Herrn ist jedes Jahr zu Silo, nördlich von Betel, östlich der Straße von Betel nach Sichem und südlich von Lebona.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Sie rieten nun den Benjaminiten: \"Geht und lauert in den Weinbergen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Seht ihr, daß Silos Töchter herauskommen, Reigen zu tanzen, dann brecht aus den Weinbergen hervor und raubt euch jeder aus Silos Töchtern ein Weib! Dann geht heim ins Land Benjamin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Kommen dann ihre Väter oder Brüder, bei uns zu klagen, dann sagen wir ihnen: \'Seht es ihnen nach! Haben wir nicht im Krieg jeden seines Weibes beraubt? Hättet ihr sie ihnen gegeben, dann wäret ihr jetzt schuldig.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Die Benjaminiten taten so und holten sich aus den Tänzerinnen die nötige Zahl Weiber, die sie raubten. Dann kehrten sie in ihren Erbbesitz heim, bauten die Städte wieder auf und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Von dort gingen die Israeliten zu jener Zeit auseinander, jeder zu seinem Stamm und seiner Sippe. So zogen sie von dort ab, jeder in seinen Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Zu jener Zeit gab es in Israel keinen König, und jeder tat, was ihm gut dünkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Als einst die Richter noch regierten, kam eine Hungersnot ins Land. Da machte sich ein Mann aus Bethlehem in Juda auf, in das Gefilde von Moab auszuwandern, er und sein Weib und seine beiden Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Der Name des Mannes war Elimelek, der seines Weibes Noëmi. Machlon und Kiljon hießen seine beiden Söhne, aus Bethlehem in Juda, Ephratiter. Und sie gelangten ins Gefilde Moabs und ließen sich dort nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Da starb Elimelek, der Gatte Noëmis. Sie aber blieb mit ihren beiden Söhnen dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Und diese nahmen moabitische Weiber. Orpa hieß die eine, die andere Ruth. Sie weilten ungefähr zehn Jahre dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Da starben auch die beiden, Machlon und Kiljon. So blieb das Weib allein von ihren beiden Söhnen und ihrem Manne übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Darauf erhob sie sich mit ihren Schwiegertöchtern, um aus dem Moablande heimzukehren. Im Lande Moab nämlich hatte sie vernommen, der Herr habe heimgesucht sein Volk und abermals ihm Brot gespendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'So zog sie von dem Ort, wo sie gewesen, und das Geleit gaben ihr die beiden Schwiegertöchter. So zogen sie des Wegs, um wieder in das Judaland zurückzukehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Und Noëmi sprach da zu ihren beiden Schwiegertöchtern: \"Geht! Kehrt um, eine jede zu ihrer Mutter Haus! Der Herr erweise euch nur Liebe, so, wie ihr an den Toten und an mir getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Der Herr verleihe euch, daß ihr jetzt eine Heimat wieder findet, im Hause ihres Mannes eine jede!\" Dann gab sie ihnen Küsse. Doch sie begannen laut zu weinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Sie sprachen: \"Nein! Wir wollen auch mit dir zu deinem Volke gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Darauf sprach Noëmi: \"Nein, meine Töchter, kehrt um! Was wollt ihr mit mir gehen? Könnte ich noch Söhne wohl in meinem Schoße hegen, die eure Männer werden könnten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Nein, meine Töchter, kehrt um! Ich bin zu alt für einen Mann. Selbst wenn ich dächte: Ich habe immerhin noch Aussicht und würde diese Nacht noch eines Mannes werden und sogar Söhne gebären,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'ja, wolltet ihr auf diese warten, bis sie erwachsen wären? Ja, wolltet ihr an sie gebunden sein und nicht bis dahin heiraten? Nein, meine Töchter! Ich bin viel schlimmer dran als ihr, ist ja die Hand des Herrn gegen mich gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Da weinten sie aufs neue laut. Darauf gab Orpa ihrer Schwiegermutter einen Abschiedskuß. Ruth aber hängte sich an sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Sie aber sprach: \"Siehe, deine Schwägerin ist zurückgekehrt zu ihrem Volk und ihrem Gott. Dem Beispiel deiner Schwägerin folge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruth sprach: \"Dringe nicht in mich, dich zu verlassen, von dir fortzugehen! Wohin du gehst, dahin gehe auch ich; und wo du bleibst, da bleibe auch ich. Dein Volk mein Volk. Dein Gott mein Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Und wo du stirbst, will auch ich sterben. Da will auch ich begraben sein. Tue mir der Herr an, was er nur will! Der Tod allein scheide zwischen mir und dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Als sie nun sah, daß jene fest entschlossen war, mit ihr zu gehen, da sprach sie ihr nicht weiter zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'So gingen diese zwei des Wegs, bis sie nach Bethlehem gelangten. Als sie nun Bethlehem betraten, geriet die ganze Stadt ihretwegen in Aufruhr. Sie fragten: \"Ist dies Noëmi?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Sie sprach zu ihnen: \"Nennt mich nicht Noëmi! Nein, nennt mich Mara! Denn der Allmächtige hat über mich viel Bitteres verhängt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Voll bin ich ausgezogen, und leer bringt mich der Herr zurück. Was wollt ihr Noëmi mich heißen? Gezeugt hat gegen mich der Herr. Es hat der Allerhöchste Leid mir zugefügt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'So kehrte Noëmi nach Hause in der Begleitung Ruths, der Moabitin, ihrer Schwiegertochter, die aus dem Lande Moab kam. Und sie betraten Bethlehem gerade zu Beginn der Gerstenernte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Nun aber hatte Noëmi noch einen Verwandten ihres Mannes, der gar sehr vermöglich war, aus dem Geschlecht Elimeleks, mit Namen Boaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Nun sprach die Moabitin Ruth zu Noëmi: \"Ich will aufs Feld hinaus und Ähren lesen hinter dem, in dessen Augen ich wohl Gnade finde.\" Sie sprach zu ihr: \"Geh, meine Tochter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Da ging sie hin und sammelte dort auf dem Felde hinter Schnittern her. Da traf es sich zufällig, daß jenes Feld Eigentum des Boaz war, der aus Elimeleks Geschlecht stammte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Und da kam eben Boaz her, aus Bethlehem, und redete die Schnitter an: \"Es sei der Herr mit euch!\" Da sprachen sie zu ihm. \"Es segne dich der Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Da fragte Boaz seinen Diener, der über seinen Schnittern stand: \"Wem gehört dies Mädchen da?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Da sprach der Diener, der über seinen Schnittern stand, und sagte: \"Es ist ein Moabitermädchen, das aus dem Moabiterland mit Noëmi zurückgekehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Sie fragte: \'Darf ich wohl lesen und bei den Garben hinter diesen Schnittern sammeln?\' Dann kam sie her und ist jetzt auf den Beinen seit dem frühen Morgen schon und hat inzwischen nur ein Weilchen Ruhe sich gegönnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Und Boaz sprach zu Ruth: \"Hör, meine Tochter, höre wohl: Geh nicht auf eines anderen Feld zum Ährenlesen! Geh nicht von hier hinweg! Nein! Halte dich an meine Mädchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Behalte nur im Auge das Feld, das sie abernten, und folge ihnen! Hab ich ja doch den Knechten den Befehl gegeben, sich keine Freiheiten mit dir je zu erlauben. Und hast du Durst, so geh hin zu den Gefäßen und trinke auch von dem, was meine Knechte schöpfen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Da warf sie sich auf ihr Gesicht und neigte sich zu Boden und sprach zu ihm: \"Warum erweisest du mir Gnade, mich anzublicken, da ich doch eine Fremde bin?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Darauf gab Boaz ihr zur Antwort: \"Man hatte mir erzählt, was du an deiner Schwiegermutter tatest nach deines Mannes Tod, daß du den Vater und die Mutter, dein Heimatland verließest und daß du dann zu einem Volke zogst, das du niemals vorher gekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Der Herr vergelte dir dein Tun! Es wird dir voller Lohn zuteil vom Herrn, Israels Gott, von ihm, in dessen Fittichen Zuflucht zu suchen du gekommen bist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Sie sprach: \"Ich danke, Herr. Denn du hast mich getröstet und deiner Magd gar freundlich zugesprochen, obwohl ich selbst nicht einer deiner Mägde gleiche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Und Boaz sprach zur Essenszeit zu ihr: \"Komm her und iß hier von dem Brot und tauche deinen Bissen in den Essig!\" Da setzte sie sich zu den Schnittern. Dann gab er ihr geröstet Korn in Fülle, so daß sie satt sich essen konnte und selbst noch übrigließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Als sie zum Sammeln wieder sich erhob, sprach Boaz zu den Knechten: \"Sie mag auch zwischen Garben lesen. Ihr dürft ihr nichts zuleide tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Zieht aus den ungebundenen Garben für sie noch einiges heraus und laßt es liegen, daß sie es auflesen kann! Ihr dürft sie niemals anfahren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'So las sie auf dem Felde bis zum Abend. Dann klopfte sie, was sie gesammelt hatte, aus. Da war es ein Scheffel Gerste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Sie hob es auf, betrat die Stadt und zeigte ihrer Schwiegermutter, was sie gesammelt hatte. Sie zog hervor und schenkte ihr, was sie nach ihrer Sättigung noch erübrigte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Und ihre Schwiegermutter sprach zu ihr: \"Wie hast du heute gesammelt? Wo hast du heute geweilt? Gesegnet sei, der dich beachtet hat!\" Da sagte sie ihrer Schwiegermutter, bei wem sie war, und sprach: \"Der Mann, bei dem ich heute geweilt, heißt Boaz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Darauf sprach Noëmi zu ihrer Schwiegertochter: \"Er sei vom Herrn gesegnet, der sein Erbarmen nicht versagt den Lebenden und nicht den Toten!\" Darauf sprach Noëmi zu ihr: \"Der Mann steht uns auch nahe. Er ist mit uns gewissermaßen noch verwandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Da sprach die Moabitin Ruth zu ihrer Schwiegermutter: \"Ich muß noch beifügen, daß er zu mir gesprochen: \'An meine Knechte halte dich, bis diese mit der ganzen Ernte fertig sind, die mir gehört!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Da sagte Noëmi zu ihrer Schwiegertochter Ruth: \"Meine Tochter! Gut ist es, wenn du mit seinen Mädchen hinausgehst. Dann kann dir niemand etwas Schlimmes tun auf eines anderen Feld.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'So hielt sie sich beim Lesen zu des Boaz Mädchen, bis daß die Gerstenernte und die Weizenernte fertig waren. Alsdann blieb sie bei ihrer Schwiegermutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Darauf sprach ihre Schwiegermutter Noëmi zu ihr: \"Meine Tochter! Ich will dir eine Heimat schaffen, die dir gefällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Nun, ist denn Boaz nicht mit uns verwandt, bei dessen Mädchen du gewesen? Er worfelt heute nacht die Gerstentenne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'So wasche dich und salbe dich! Leg deine Kleider an und geh hinab zur Tenne! Doch gib dich nicht dem Manne zu erkennen, bis er mit Essen und mit Trinken fertig ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Wenn er sich niederlegt, dann merke dir den Ort, wo er sich niederlegt! Geh hin! Deck dann den Platz zu seinen Füßen auf und lege dich dort nieder! Er wird dir sagen, was du tun sollst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Da sagte sie zu ihr: \"Was immer du mir sagst, das will ich tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Sie ging zur Tenne und tat, wie ihre Schwiegermutter sie geheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Und Boaz aß und trank und wurde guter Dinge. Dann ging er hin, sich hinter den Getreidehaufen hinzulegen. Sie aber ging ganz leise herzu und deckte nun den Platz zu seinen Füßen auf und legte sich hier nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Und da geschah es um Mitternacht. Der Mann fuhr voller Schrecken auf, und als er tastete, da lag das Weib an seinem Fußende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Er sprach: \"Wer bist denn du?\" Da sagte sie: \"Ruth, deine Magd! Heirate deine Magd! Du bist verwandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Er sprach: \"Gesegnet seist du, meine Tochter, von dem Herrn! Du hast später deine Liebe schöner noch gezeigt als je zuvor. Du liefst nicht jungen Männern nach, ob arm, ob reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Nun, -eine Tochter, sei getrost! Ich werde ganz nach deinen Worten an dir tun. Denn jede Sippe meines Volkes weiß: Du bist ein wackeres Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Nun ist es so: Ich bin verwandt. Doch gibt es einen, der noch näher ist verwandt als ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Bleib diese Nacht nur hier! Freit er dich morgen, gut! So mag er freien. Doch hat er keine Lust dazu, so will, so wahr der Herr lebt, ich dich freien. Jetzt schlafe bis zum Morgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'So lag sie bis zum Morgen früh an seinem Fußende. Alsdann erhob sie sich, bevor noch irgendwer den anderen erkennen konnte. Sie sprach: \"Nicht ruchbar werde es, daß auf die Tenne hier ein Weib gekommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Da sagte er: \"So nimm den Überwurf, den du da trägst, und halte ihn her!\" Sie hielt ihn hin. Da maß er sechs Maß Gerste ab und lud es ihr auf. So kam sie in die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Sie kam zu ihrer Schwiegermutter, und diese fragte: \"Wie steht\'s mit dir, du meine Tochter?\" Und sie erzählte ihr, was ihr der Mann erwiesen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Sie sagte: \"Die sechs Maß Gerste schenkte er mir. Er sprach: \'Du darfst nicht leer zu deiner Schwiegermutter kommen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Da sagte sie: \"Verhalt dich ruhig, meine Tochter, bis du weißt, wie diese Sache endet! Der Mann wird ja nicht ruhen, bis er die Sache heute noch zu Ende bringt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Inzwischen war zum Tore Boaz aufgestiegen und hatte sich dort hingesetzt. Da ging gerade der Verwandte dort vorüber, von dem Boaz gesprochen. Er sprach. \"Komm her und setze dich hier nieder, du, so und so!\" Er kam herbei und setzte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Dann nahm er von den Ältesten der Stadt zehn Männer und sprach: \"Setzt euch nieder hier!\" Da setzten sie sich hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Dann sprach er zum Verwandten: \"Das Grundstück, das einst unserem Bruder Elimelek gehörte, setzt Noëmi jetzt dem Verkaufe aus, die wieder aus dem Moabland zurückgekehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Nun dachte ich: Ich will es dir zu Ohren bringen. So kauf\'s in Gegenwart der Männer hier, der Ältesten in meinem Volk! Willst du es lösen, dann löse es ein! Wenn nicht, so melde es mir, daß ich es weiß! Denn außer dir ist niemand da, der es einlösen könnte. Ich aber komme nach dir.\" Er sprach: \"Ich will es einlösen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Da sagte Boaz: \"Damit, daß du von Noëmi das Grundstück jetzt erwirbst, erwirbst du auch die Moabitin Ruth, das Weib des Toten, um so des Toten Namen auf seinem Eigentum wiederum erstehen zu lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Darauf sprach der Verwandte: \"Dann kann ich es nicht für mich einlösen. Ich würde meinen Erbbestand schädigen. Was ich zu lösen hätte, lös du ein! Ich kann es nicht einlösen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Nun war in Israel vor Zeiten folgendes Brauch bei einer Lösung, einem Tausch, um irgend etwas fest zu machen: Es zog da einer seinen Schuh ab und reichte ihn dem anderen. Das war in Israel die Form für die Bestätigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'So sprach zu Boaz der Verwandte: \"Kauf es für dich!\" und zog den Schuh ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Darauf sprach Boaz zu den Ältesten und zu dem ganzen Volk: \"Ihr seid jetzt Zeugen, daß ich das ganze Eigentum Elimeleks von Noëmi kaufe, sowie das ganze Eigentum von Kiljon und von Machlon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Dazu erkaufe ich die Moabitin Ruth, die Gattin Machlons, mir zum Weibe, um so des Toten Namen auf seinem Erbbesitze wiederum erstehen zu lassen, damit des Toten Namen aus seiner Brüder Kreise und aus dem Tore seines Orts nicht ausgerottet werde. Ihr seid jetzt meine Zeugen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Darauf rief alles Volk im Tore und die Ältesten: \"Wir sind des Zeugen: Möge nur der Herr das Weib, das in dein Haus einzieht, wie Rachel und wie Lea machen, die beide einst das Haus von Israel begründet! Üb Macht in Ephrat aus; verbreite Ruhm zu Bethlehem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Dein Haus, das werde wie das Haus des Peres, den Tamar Juda einst geboren, durch jenen Stamm, den dir der Herr aus diesem Mädchen schenke!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Und Boaz nahm die Ruth. Sie ward sein Weib. Und als er zu ihr ging, gewährte Segen ihr der Herr. Sie schenkte einem Sohn das Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Da sprachen die Frauen zu Noëmi: \"Gepriesen sei der Herr, der einen Löser heut dir nicht versagt! Sein Name werde in Israel genannt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Er möge dich am Leben auch erhalten und so Versorger deines Alters werden! Denn deine Schwiegertochter, die dich liebt, hat ihn geboren, sie, die dir mehr wert ist als sieben Söhne.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Darauf nahm Noëmi das Kind und legte es auf ihren Schoß und ward ihm eine Wärterin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Da gaben ihm die Nachbarinnen einen Namen: \"Ein Sohn ist Noëmi geboren.\" Sie nannten seinen Namen also Obed. Das ist der Vater Isais; der ist der Vater Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Das ist des Peres Stammbaum: Peres zeugte Hezron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Und Hezron zeugte Ram, und Ram zeugte den Aminadab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadab zeugte Nachson, und Nachson zeugte Salmon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Und Salmon zeugte Boaz, und Boaz zeugte Obed.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Und Obed zeugte Isai, und Isai zeugte David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Und zu Ramataim war ein Mann, ein Sufite vom Gebirge Ephraim namens Elkana, Jerochams Sohn und Elihus Enkel, Tochurs Urenkel und Ururenkel Suphs, ein Ephratiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Er hatte zwei Frauen. Die eine hieß Anna, die andere Peninna. Peninna aber hatte Kinder, Anna nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Dieser Mann nun zog alljährlich aus seiner Stadt hinauf, zu Silo anzubeten und dem Herrn der Heerscharen zu opfern. Priester des Herrn aber waren dort die beiden Söhne Elis, Chophni und Pinechas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Eines Tages nun opferte Elkana. Dabei gab er seinem Weibe Peninna und all ihren Söhnen und Töchtern mehrere Stücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Anna aber gab er verdrossen nur ein Stück; denn er liebte Anna, aber der Herr hatte ihren Schoß verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Dazu kränkte ihre Nebenbuhlerin sie, um sie zu reizen, weil der Herr ihren Schoß verschlossen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Und so geschah es Jahr für Jahr. Sooft sie zum Hause des Herrn zog, kränkte jene sie so, daß sie weinte und nicht aß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Einst sprach ihr Mann Elkana zu ihr: \"Anna, warum weinst du? Warum issest du nicht? Warum bist du so verstimmt? Bin ich dir nicht inniger zugetan, als wenn du schon zehn Kinder hättest?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Da stand Anna auf, nachdem man das Gekochte gegessen und hernach getrunken hatte: Der Priester Eli aber saß auf dem Stuhle an den Pfosten des Herrntempels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Sie war aber betrübten Gemüts. So betete sie zum Herrn und weinte in einem fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Dabei machte sie ein Gelübde und sprach: \"Herr der Heerscharen! Wenn du das Elend deiner Magd ansiehst und meiner gedenkst und deiner Magd nicht vergissest, sondern deiner Magd einen Mannessprossen verleihst, dann schenke ich ihn für sein ganzes Leben dem Herrn. Und auf sein Haupt soll nie ein Schermesser kommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'So betete sie lange vor dem Herrn; Eli aber ward aufmerksam auf ihren Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Anna aber redete innerlich. Nur ihre Lippen bewegten sich. Da nun ihre Stimme nicht gehört ward, hielt Eli sie für betrunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Und Eli sprach zu ihr: \"Wie lange willst du trunken sein? Werde deinen Weinrausch los!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Da erwiderte Anna und sprach: \"Nein, mein Herr! Ich bin ein tief bekümmertes Weib, und doch habe ich weder Wein noch Bier getrunken. Ich schüttete nur mein Herz vor dem Herrn aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Halte deine Magd nicht für eine Nichtswürdige! Denn nur aus der Fülle meines Kummers und meiner Kränkung habe ich so lange geredet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Da antwortete Eli und sprach: \"Zieh hin in Frieden! Israels Gott gebe dir, was du von ihm erbeten hast!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Sie sprach: \"Möge deine Magd Huld in deinen Augen finden!\" Dann ging das Weib seines Wegs und aß. Und sie war nicht mehr wie vordem');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Am anderen Morgen früh beteten sie vor dem Herrn. Dann kehrten sie nach der Rama heim. Da erkannte Elkana sein Weib, und der Herr gedachte ihrer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Das Jahr ging vorüber. Anna hatte inzwischen empfangen und einen Sohn geboren. Sie nannte ihn Samuel, das heißt \"Vom Herrn habe ich ihn erbeten\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Der Mann Elkana aber zog mit seinem ganzen Hause hinauf, dem Herrn das jährliche Opfer und sein Gelübde darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Anna aber zog nicht mit hinauf, sie hatte nämlich zu ihrem Manne gesagt: \"Erst wenn der Knabe entwöhnt ist, bringe ich ihn hin, daß er vor dem Herrn erscheine und dort für immer bleibe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Da sprach ihr Mann Elkana zu ihr: \"Tu, was dir gut dünkt! Bleib da, bis du ihn entwöhnt hast! Möge der Herr sein Wort bestätigen!\" So blieb das Weib daheim und stillte ihren Sohn, bis sie ihn entwöhnt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Dann brachte sie ihn nach seiner Entwöhnung mit sich hinauf, dazu ein dreijähriges Rind, einen Scheffel Mehl und einen Schlauch Wein. So brachte sie ihn in das Haus des Herrn nach Silo. Der Knabe aber war halbwüchsig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Dann schlachteten sie das Rind und brachten den Knaben zu Eli.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Sie sprach: \"Mit Vergunst, mein Herr! Bei deinem Leben, Herr! Ich bin das Weib, das hier bei dir gestanden, zum Herrn zu beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Um diesen Knaben habe ich gebetet. Und der Herr gewährte mir meine Bitte, das, was ich von ihm erbeten habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'So leihe auch ich dem Herrn all seine Lebenstage. Er ist der vom Herrn Erbetene.\" Dann beteten sie dort den Herrn an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Anna betete und sprach: Aufjauchzt mein Herz im Herrn; groß wurde meine Stärke durch den Herrn. Kühn spricht mein Mund mit meinen Feinden; ich freue mich ob Deiner Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'So heilig wie der Herr ist keiner; denn außer Dir ist keiner sonst. Kein Fels gleicht unserem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Nicht sprechet soviel Übermütiges! Vermessenheit entschwinde eurem Munde! Es ist der Herr ein Gott des Wissens! Und böse Taten sind nie recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Der Starken Bogen ward geknickt; doch Strauchelnde behalten ihre Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Um Brot verdingen müssen sich, die vordem satt, und Hungrige erquicken sich. Die Unfruchtbare hat der Kinder sieben; die Kinderreiche welkt dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Der Herr kann töten und beleben, zum Grabe führen und davor bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Der Herr macht arm und reich, erniedrigt und erhöht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Er richtet auf vom Staub den Bettler, erhebt den Armen aus dem Kot und heißt sie setzen neben Fürsten, weist ihnen einen Ehrensitz für immer an. Des Herren sind der Erde Säulen; den Erdkreis stellte er darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Die Schritte seiner Frommen hütet er; in Finsternis vergehn die Frevler; denn nicht durch eigne Kraft wird jemand Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Zerschmettert werden so des Herren Widersacher, und er vernichtet Himmelsstürmer. Der Erde Enden richtet selbst der Herr, gibt Stärke seinem König, erhöht seines Gesalbten Macht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Dann ging Elkana nach der Rama heim. Der Knabe aber diente dem Herrn unter des Priesters Eli Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Die Söhne Elis aber waren Teufelsbuben. Sie kümmerten sich nicht um den Herrn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'und um der Priester Gerechtsame gegenüber dem Volke. Sooft nämlich jemand ein Opfer schlachtete, kam des Priesters Bursche, während das Fleisch kochte, mit einer dreizackigen Gabel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'und stach damit in den Kessel oder Topf oder Tiegel oder in die Pfanne. Alles, was die Gabel heraufbrachte, nahm der Priester für sich. So taten sie mit ganz Israel, das dorthin nach Silo kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Sogar bevor man das Fett verbrannte, kam des Priesters Bursche und sagte zu dem opfernden Mann: \"Gib Fleisch zum Braten für den Priester! Er will von dir kein gekochtes Fleisch haben, sondern rohes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Sagte dann der Mann zu ihm: \"Man muß auf der Stelle das Fett verbrennen. Danach nimm dir, was du gerne magst!\", so sprach er zu ihm: \"Nein! Gib sofort! Wenn nicht, dann nehme ich es mit Gewalt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'So ward die Schuld der jungen Männer vor dem Herrn sehr groß. Denn sie, die Menschen, hatten das Opfer des Herrn verächtlich behandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel aber diente vor dem Herrn, als Knabe schon mit dem Leibschurz umgürtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Dazu pflegte ihm seine Mutter einen kleinen Mantel zu machen. Einen solchen brachte sie ihm jedes Jahr, wenn sie mit ihrem Manne hinaufzog, das jährliche Opfer darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Dann segnete Eli den Elkana und sein Weib und sprach: \"Der Herr gebe dir von diesem Weibe Nachwuchs statt des Erflehten, den sie vom Herrn erfleht!\" Dann zogen sie heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Weil der Herr Anna bedacht hatte, ward sie guter Hoffnung und gebar noch drei Söhne und zwei Töchter. Der junge Samuel aber wuchs auf beim Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli aber war sehr alt geworden. Er hörte alles, was seine Söhne an ganz Israel taten, und daß sie bei den Weibern lagen, die den Eingang des Festgezeltes verhängten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Er sprach zu ihnen: \"Warum treibt ihr solche Dinge, daß ich vom ganzen Volke diese schlechten Dinge über euch hören muß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nein, meine Söhne, nicht schön ist das Gerücht, das ich über die Verführer des Herrnvolkes hören muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Sündigt ein Mann gegen den anderen, dann ist dessen Anwalt Gott. Sündigt aber ein Mann gegen den Herrn, wer könnte ihn verteidigen?\" Aber sie hörten nicht auf ihres Vaters Worte. Denn dem Herrn gefiel es, sie sterben zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Der Knabe Samuel aber wuchs immer mehr und nahm zu an Gunst beim Herrn und bei den Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Da kam ein Gottesmann zu Eli und sprach zu ihm: \"So spricht der Herr: \'Ich habe mich dem Hause deines Vaters einst geoffenbart, als es in Ägypten noch Pharaos Haus gehörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Und ich erwählte es aus allen Stämmen Israels für mich zu Priestern, daß sie auf meinen Altar steigen und Räucherwerk anzünden und das Ephod vor mich hinlegen. Und deinem Vaterhause übertrug ich alle Mahlopfer der Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Warum mißachtet ihr mein Opfer und meine Gabe, die ich zum Unterhalt angewiesen? Weswegen achtest du deine Söhne höher als mich, daß ihr euch mästet von dem ersten Abhub aller Gaben Israels, die meines Volkes sind?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Deshalb ein Spruch des Herrn, des Gottes Israels: \'Ich habe freilich ausgesprochen: \"Dein Haus und deines Vaters Haus, sie sollen immer vor mir wandeln!\" Nun aber\' - Spruch des Herrn -, \'sei es fern von mir! Denn die mich ehren, ehre ich. Die mich mißachten, leiden Schmach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Es kommt die Zeit, da kürze ich dir einen Arm und deines Vaterhauses Arm, daß nimmermehr ein Greis in deinem Hause sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Dann blickst du, selber arm, auf jeden, dem es gut in Israel ergeht. Nie sei in deinem Hause mehr ein Greis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Nicht jeden aber tilge ich von meinem Altar, daß deine Augen schmachten und deine Seele vergehe. Doch sterbe deines Hauses ganze Brut hin wie gemeine Leute!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Und dies sei dir das Zeichen, das deine beiden Söhne Chophni und Pinechas trifft: An einem Tage sterben beide!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Doch ich bestelle mir einen zuverlässigen Priester, der tut nach meinem Sinn und Herzen. Ich baue ihm ein dauernd Haus. Und alle Tage wandelt er vor meinem Hochgesalbten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Wer übrigbleibt von deinem Hause, der kommt und wirft sich nieder, um Geld und Brotlaibe zu betteln, wobei er sagt: \"Geselle mich doch einer deiner Priesterschaften bei, damit ich einen Bissen Brot bekomme.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Der Knabe Samuel nun diente vor Eli dem Herrn. Zu jener Zeit aber war das Herrnwort selten. Auch Gesichte waren nicht verbreitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Eines Tages nun ruhte Eli an seinem Platze. Seine Augen aber begannen sich zu trüben, und er konnte nicht mehr gut sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Aber die Gotteslampe erlosch nicht, ruhte doch Samuel in des Herrn Heiligtum, wo die Gotteslade stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Da rief der Herr: \"Samuel!\" Er sprach: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Dann lief er zu Eli und sprach: \"Hier bin ich. Du hast mich ja gerufen.\" Er sprach: \"Ich habe dich nicht gerufen. Leg dich nieder!\" Da ging er und legte sich nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Da rief der Herr noch einmal: \"Samuel!\" Und Samuel stand auf, ging zu Eli und sprach: \"Hier bin ich. Du hast mich doch gerufen.\" Er sprach:\"Ich habe nicht gerufen, mein Sohn; leg dich nieder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel aber hatte den Herrn noch nicht erfahren, und noch ward ihm kein Herrnwort geoffenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Da rief der Herr den Samuel noch zum drittenmal. Und er stand auf, ging zu Eli und sprach: \"Hier bin ich. Du hast mich doch gerufen.\" Da merkte Eli, daß der Herr den Knaben rief.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Und Eli sprach zu Samuel: \"Geh, leg dich nieder! Ruft es dich nochmals, dann sprich: \'Rede, Herr! Dein Diener hört.\'\" Da ging Samuel und legte sich an seinem Platze nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Da kam der Herr, trat hin und rief wie die vorigen Male: \"Samuel! Samuel!\" Da sprach Samuel: \"Rede! Dein Diener hört.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Da sprach der Herr zu Samuel: \"Ich tue etwas in Israel, daß jedem, der es hört, davon die Ohren gellen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'An jenem Tage erfülle ich an Eli alles, was ich seinem Haus angedroht, von Anfang bis zu Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ich tue ihm kund, daß ich sein Haus strafen will für immer wegen der Sünde, weil er gewußt hat, daß seine Söhne \"sich\" lästern; er aber hat ihnen nicht gewehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'So habe ich dem Haus Elis geschworen: \'Die Schuld des Elihauses soll niemals durch Schlachtopfer und andere Opfergaben gesühnt werden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel aber blieb bis zum Morgen liegen. Dann öffnete er die Pforten im Hause des Herrn. Doch scheute sich Samuel, Eli das Gesicht zu künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Da rief Eli den Samuel und sprach: \"Samuel, mein Sohn!\" Da sagte er: \"Hier bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Er sprach: \"Was war es, das er zu dir geredet hat? Verhehle mir nichts! Gott tue dir dies und das, verhehlst du mir etwas von all dem, was er zu dir gesprochen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Da erzählte ihm Samuel alle Worte und verhehlte ihm nichts. Da sprach jener: \"Es ist der Herr. Er tue, was ihm gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel wuchs nun heran, und der Herr war mit ihm. Und er hatte kein einziges seiner Worte zur Erde fallen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Ganz Israel erkannte, von Dan bis Beerseba, daß Samuel sich als Prophet des Herrn bewährte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Und der Herr erschien auch weiterhin zu Silo. Denn der Herr offenbarte sich Samuel durch das Herrnwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Und so galt Samuels Wort für ganz Israel. Israel aber zog gegen die Philister in den Kampf. Sie lagerten am Eisstein; die Philister aber lagerten sich bei Aphek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Die Philister nun boten Israel den Kampf an. Da begann der Kampf, und Israel ward von den Philistern geschlagen. Auf dem Kampfplatz auf dem Felde wurden an 4.000 Mann erschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'So kam die Mannschaft wieder in das Lager; da sagten die Ältesten Israels: \"Warum hat uns heute der Herr vor den Philistern geschlagen? Wir wollen die Bundeslade des Herrn aus Silo zu uns holen. So soll er in unsere Mitte kommen und uns aus unserer Feinde Hand erretten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Da sandte das Volk nach Silo. Und man holte von dort die Bundeslade des Herrn der Heerscharen, der auf den Cheruben thront. Dabei waren auch die beiden Elisöhne Chophni und Pinechas mit der Bundeslade Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Als die Bundeslade des Herrn ins Lager kam, erhob ganz Israel lauten Jubel, daß der Boden dröhnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Die Philister aber hörten das schallende Jubelgeschrei und fragten: \"Was bedeutet dieser laute Jubel im Lager der Hebräer?\" Da erfuhren sie, daß die Lade des Herrn ins Lager gekommen sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Da fürchteten sich die Philister und sprachen: \"Ein Gott ist zu ihnen ins Lager gekommen.\" Und sie sprachen: \"Wehe uns! So ist es noch nie gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Wehe uns! Wer rettet uns aus der Hand dieser mächtigen Götter? Das sind die gleichen Götter, die Ägypten mit allerlei Plagen verheerend geschlagen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Haltet euch tapfer und seid Männer, ihr Philister, daß ihr nicht den Hebräern dienet, wie sie euch gedient haben! Seid denn Männer und kämpfet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Da kämpften die Philister. Israel aber unterlag und floh, jeder in sein Zelt. Und so ward die Niederlage sehr groß. Von Israel fielen 30.000 Mann, lauter Fußvolk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Auch die Gotteslade ward erbeutet, und die beiden Elisöhne Chophni und Pinechas waren gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Da lief ein Mann von Benjamin vom Walplatz und kam am selben Tage nach Silo, die Kleider zerrissen und Staub auf dem Kopfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Als er ankam, saß Eli auf dem Stuhle nahe am Wege und spähte. Denn sein Herz bangte um die Lade Gottes. Als der Mann aber kam und der Stadt die Kunde brachte, schrie die ganze Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Eli hörte das laute Geschrei und fragte: \"Was bedeutet dies Geschrei der Menge?\" Da kam der Mann herangeeilt und brachte Eli die Kunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Achtundneunzig Jahre alt war Eli, und seine Augen waren starr, und er konnte nicht mehr sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Der Mann sprach zu Eli: \"Ich bin der, der vom Walplatz kommt. Ich bin heute von dem Walplatz geflohen.\" Da fragte er: \"Wie ist es gegangen, mein Sohn?\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Da antwortete der Bote und sprach: \"Israel ist vor den Philistern geflohen. Dazu hat das Volk eine große Niederlage erlitten. Auch deine beiden Söhne Chophni und Pinechas sind gefallen, und die Gotteslade ist genommen worden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Als er aber die Gotteslade nannte, fiel jener rücklings vom Stuhle durch die Tür, brach das Genick und starb. Denn der Mann war alt und schwer. Er hatte Israel vierzig Jahre gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Seine Schwiegertochter, des Pinechas Weib, war hochschwanger. Sie hörte nun die Kunde vom Verlust der Gotteslade und vom Tod ihres Schwiegervaters und ihres Mannes. Da sank sie hin und gebar. Denn die Wehen hatten sie überrascht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Als sie zum Sterben kam, sprachen die umstellenden Weiber: \"Fürchte dich nicht! Du hast einen Sohn geboren.\" Sie aber gab keine Antwort und achtete nicht darauf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'sondern nannte den Knaben Ikabod. Sie sagte: \"Dahin ist Israels Ehrenpreis\", wegen des Verlustes der Gotteslade, ihres Schwiegervaters und ihres Mannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'So sprach sie also: \"Dahin ist Israels Ehrenpreis; denn die Gotteslade ist genommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Die Philister hatten also die Gotteslade erbeutet. Sie brachten sie von dem Eisstein nach Asdod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Dann nahmen die Philister die Gotteslade und brachten sie in das Haus des Dagon. Sie stellten sie hier neben Dagon auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Als aber am anderen Morgen einige Asdoditer kamen, lag Dagon mit seinem Gesicht auf dem Boden vor der Lade des Herrn. Da nahmen sie Dagon und stellten ihn wieder an seinen Platz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Als sie aber am anderen Morgen früh kamen, war Dagon wieder auf sein Gesicht zur Erde gefallen vor der Lade des Herrn. Dagons Kopf und beide Hände lagen abgebrochen auf der Schwelle. Dagon selbst lag neben ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Daher dürfen weder die Dagonspriester noch irgendein Besucher des Dagonshauses auf die Schwelle Dagons in Asdod treten bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Die Hand des Herrn aber lag schwer auf den Asdoditern. Er erschreckte sie und schlug sie mit Pestbeulen, Asdod und sein Gebiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Als die Männer von Asdod sahen, daß es so war, sagten sie: \"Die Lade des Gottes Israels darf nicht bei uns bleiben. Denn seine Hand lastet schwer auf uns und unserem Gotte Dagon.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'So sandten sie hin und ließen alle Philisterfürsten zu sich kommen und sprachen: \"Was sollen wir mit der Lade des Gottes Israels tun?\" Da sprachen sie: \"Man soll die Lade des Gottes Israels nach Gat schaffen!\" So schafften sie die Lade des Gottes Israels dorthin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Nachdem man sie hingeschafft hatte, lag die Hand des Herrn auf der Stadt zu ihrer größten Bestürzung. Er schlug nämlich die Männer der Stadt, klein und groß, daß Beulen an ihnen ausbrachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Da sandten sie die Gotteslade nach Ekron. Als aber die Gotteslade nach Ekron kam, schrieen die von Ekron: \"Man bringt die Lade des Gottes Israels zu mir, um mich und mein Volk zu töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Dann sandten sie hin und ließen alle Philisterfürsten kommen und sprachen: \"Schickt die Lade des Gottes Israels fort, daß sie an ihren Ort kehre und nicht mich und mein Volk töte.\" Denn Todesfurcht war in der ganzen Stadt. Gar schwer lag die Hand Gottes darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Und die Leute, die nicht starben, wurden mit Beulen geschlagen. Und das Jammergeschrei der Stadt stieg zum Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'So blieb die Lade des Herrn im Gefilde der Philister sieben Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Dann beriefen die Philister die Priester und Wahrsager und fragten: \"Was machen wir mit des Herrn Lade? Tut uns kund, wie wir sie an ihren Ort schaffen sollen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Sie sprachen: \"Schickt ihr die Lade des Gottes Israels fort, dann schickt sie nicht leer fort! Ihr sollt ihm vielmehr eine Buße zahlen! Dann werdet ihr geheilt, und es wird euch klar, warum seine Hand nicht von euch wich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Sie fragten: \"Welche Buße sollen wir ihm zahlen?\" Sie sprachen. \"Nach der Zahl der philistäischen Fürsten fünf goldene Beulen und fünf goldene Mäuse. Denn einerlei Plage hat euch alle und eure Fürsten getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Macht Abbilder eurer Beulen und eurer Mäuse, die das Land verheert haben! Gebt dem Gott Israels die Ehre! Vielleicht nimmt er seine Hand weg von euch, von eurem Gott und eurem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Wozu wollt ihr euer Herz verhärten, wie Ägypten und der Pharao ihr Herz verhärtet haben? Nicht wahr, als er ihnen übel mitgespielt hatte, ließ man sie fortziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Nun macht einen neuen Wagen und holt zwei Milchkühe, auf die noch kein Joch gekommen! Dann spannt die Kühe an den Wagen; aber ihre Kälber laßt fern von ihnen im Stalle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Dann nehmt die Lade des Herrn und stellt sie auf den Wagen! Die Goldsachen, die ihr ihm als Buße gebet, sollt ihr in einem Sack zur Seite legen! Dann laßt sie des Wegs ziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Seht dann zu: Zieht sie den Weg nach Betsemes hinauf, dann hat er uns dies große Übel angetan. Wenn nicht, dann wissen wir, daß nicht seine Hand uns getroffen hat. Dann ist dies für uns ein Zufall gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Und die Männer taten so. Sie nahmen zwei Milchkühe und spannten sie an den Wagen. Ihre Kälber aber hatten sie im Stalle behalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Dann stellten sie die Lade des Herrn auf den Wagen, ebenso den Sack und die goldenen Mäuse und die Bilder ihrer Geschwülste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Die Kühe aber liefen geraden Wegs auf der Straße nach Betsernes. Sie brüllten unaufhörlich, aber bogen nicht nach rechts noch links ab. Die Philisterfürsten aber folgten ihnen bis in das Gebiet von Betsemes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Eben hielt Betsemes im Talgrund die Weizenernte. Als sie ihre Augen erhoben, erblickten sie die Lade. Da freuten sie sich bei ihrem Anblick.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Der Wagen aber kam zum Felde Josues aus Betsemes und stand hier still. Hier lag ein großer Stein. Da spalteten sie das Holz des Wagens; die Kühe nämlich opferten sie als Brandopfer dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Die Leviten aber hatten die Lade des Herrn und den Sack neben ihr mit den Goldsachen abgeladen; dann stellten sie sie auf den großen Stein. Und die Männer von Betsemes hatten Brandopfer herbeigeschafft, und so schlachteten sie dem Herrn an jenem Tage Schlachtopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Als dies die fünf Philisterfürsten gesehen, kehrten sie am selben Tage nach Ekron zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Dies aber waren die goldenen Beulen, die die Philister dem Herrn als Buße bezahlten: eine für Asdod, eine für Gaza, eine für Askalon, eine für Gat und eine für Ekron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Auch die Goldmäuse richteten sich nach der Zahl aller Philisterstädte der fünf Fürstentümer. Sie galten für die befestigten Städte und die Bauerndörfer. Noch ist der große Stein da, worauf sie die Lade des Herrn gestellt, bis auf diesen Tag im Felde Josues von Betsemes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Er schlug aber bei den Mannen von Betsemes, weil sie in die Lade des Herrn hineingeschaut hatten, 70 Mann; im Volke schlug er 50.000 Mann. Dann trauerte das Volk, daß der Herr vom Volke so viele geschlagen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Da sprachen die Männer von Betsemes: \"Wer kann den Herrn, diesen heiligen Gott, bedienen? Und zu wem soll er von uns hingehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Da sandten sie Boten zu den Einwohnern von Kirjat Jearim und ließen sagen: \"Die Philister haben die Lade des Herrn zurückgebracht. Kommt herab und holt sie euch herauf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Da kamen die Männer von Kirjat Jearim, holten die Lade des Herrn hinauf und brachten sie ins Haus Abinadabs auf dem Hügel. Seinen Sohn Eleazar aber bestimmten sie dazu, die Lade des Herrn zu hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Von dem Tage an, da die Lade in Kirjat Jearim blieb, verging eine lange Zeit. Zwanzig Jahre wurden es, und das ganze Haus Israel klagte vor dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Da sprach Samuel zu dem ganzen Volke Israel also: \"Wollt ihr von ganzem Herzen zum Herrn zurückkehren, dann schafft die Götter der Fremde aus eurer Mitte, ebenso die Astarten! Richtet euer Herz auf den Herrn und dient ihm allein! Und er entreißt euch der Philister Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Da entfernten Israels Söhne die Baale und Astarten und dienten allein dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Da sprach Samuel: \"Versammelt ganz Israel nach der Mispa! Dann bete ich für euch zum Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Da versammelten sie sich auf der Mispa, schöpften Wasser, gossen es vor den Herrn, fasteten an jenem Tag und sprachen dort: \"Wir haben gegen den Herrn gesündigt.\" Und Samuel richtete Israel auf der Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Die Philister aber hörten, daß sich Israels Söhne auf der Mispa versammelt hatten. Da zogen die Philisterfürsten gegen Israel. Als dies die Söhne Israels hörten, fürchteten sie sich vor den Philistern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Und die Söhne Israels sprachen zu Samuel: \"Höre nicht auf, für uns zum Herrn, unserem Gott, zu flehen, daß er uns aus der Philister Hand helfe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Da nahm Samuel ein Milchlamm und brachte es dem Herrn als ganzes Brandopfer dar. Und Samuel flehte zum Herrn für Israel, und der Herr erhörte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Und Samuel brachte eben das Brandopfer dar. Da griffen die Philister Israel an. Der Herr aber donnerte mit gewaltigem Schalle an jenem Tage gegen die Philister und verwirrte sie, und sie wurden von Israel geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Da rückten die Männer Israels von der Mispa aus, verfolgten die Philister und schlugen sie bis unterhalb Betkar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Da nahm Samuel einen Stein, stellte ihn zwischen der Mispa und der Spitze auf und nannte ihn \"Stein der Hilfe\". Er sprach: \"Bis hierher hat der Herr geholfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'So wurden die Philister gebeugt. Und sie kamen fernerhin nicht mehr in Israels Gebiet. Die Hand des Herrn lag auf den Philistern, solange Samuel lebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Die Städte aber, die die Philister Israel abgenommen hatten, kamen wieder an Israel, von Ekron bis Gat. Auch ihr Gebiet entriß Israel der Hand der Philister. Ebenso ward Friede zwischen Israel und dem Amoriter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Und Samuel richtete alle Tage seines Lebens Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Jahr für Jahr nämlich war er umhergewandert und hatte die Runde gemacht über Betel, das Gilgal und die Mispa. An all diesen Orten hatte er Israel gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Seine Heimstatt aber war auf der Rama; denn dort war sein Haus, und dort richtete er Israel. Er baute auch dort dem Herrn einen Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Als Samuel alt geworden, bestellte er seine Söhne zu Richtern für Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Sein Erstgeborener hieß Joel, sein Zweiter Abia. Sie richteten zu Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Aber seine Söhne waren nicht auf seinen Wegen gewandelt; sie gingen vielmehr auf Gewinn aus. Sie ließen sich bestechen und beugten das Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Da traten die Ältesten Israels zusammen und kamen zu Samuel auf die Rama.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Sie sprachen zu ihm: \"Du bist alt geworden. Deine Söhne aber wandeln nicht auf deinen Wegen. Deshalb setze über uns einen König, daß er uns richte, wie es bei allen anderen Völkern ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Samuel aber mißfiel es, daß sie gesprochen hatten: \"Gib uns einen König, daß er uns richte!\" Und Samuel beklagte sich beim Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Da sprach der Herr zu Samuel: \"Hör auf des Volkes Stimme in allem, was sie zu dir sagen! Nicht dich verwerfen sie, sondern mich, damit ich nicht mehr über sie König sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Gerade so, wie sie getan von dem Tage an, da ich sie aus Ägypten geführt, bis auf diesen Tag, da sie mich verließen und anderen Göttern dienten, so tun sie auch dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'So hör auf ihre Stimme! Doch sollst du sie ernstlich verwarnen! Tu ihnen auch die Rechte des Königs kund, der über sie herrschen soll!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Und Samuel verkündete alle Worte des Herrn dem Volk, das von ihm einen König verlangte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Er sprach: \"Dies sind die Rechte des Königs, der über euch herrschen wird: Eure Söhne nimmt er und stellt sie an seine Wagen und Rosse, daß sie vor seinem Wagen laufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Er setzt sich Oberste über Tausende und Oberste über fünfzig. Sie müssen sein Ackerland pflügen, seine Ernte einbringen und seine Kriegs- und Wagengeräte machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Eure Töchter nimmt er zum Salbenbereiten, Kochen und Backen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Von euren Feldern, Weinbergen und Ölgärten nimmt er die besten und gibt sie seinen Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Von euren Saatländern und Weinbergen erhebt er den Zehnten und gibt ihn seinen Hofleuten und Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Und eure Knechte und Mägde, eure fetten Rinder und eure Esel nimmt er und verwendet sie für seine Wirtschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Von euren Schafen erhebt er den Zehnten. Ihr selbst aber werdet seine Knechte sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Da schreit ihr an jenem Tage wegen eures Königs, den ihr euch erwählt habt. Aber der Herr erhört euch nicht an jenem Tage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Das Volk aber weigerte sich, auf Samuels Stimme zu hören. Sie sprachen zu ihm: \"Nur ein König soll über uns sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Wir wollen auch so sein wie alle Völker. Unser König richte uns und ziehe vor uns her und führe unsere Kriege!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Samuel hörte aber alles, was das Volk redete, und trug es dem Herrn vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Da sprach der Herr zu Samuel: \"Hör auf ihre Stimme und gib ihnen einen König!\" Da sprach Samuel zu den Männern Israels: \"Geht, ein jeglicher in seine Stadt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Da war ein Mann aus Benjamin namens Kis, Abiels Sohn, Serors Enkel und Urenkel Bekorats, des Sohnes Aphiachs, ein Benjaminite und vermögender Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Er hatte einen Sohn, namens Saul, jung und wohlgestaltet. Keiner der Söhne Israels war so wohlgestaltet wie er. Von seinen Schultern an ragte er über das ganze Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Nun verliefen sich dem Kis, Sauls Vater, Eselinnen. Da sprach Kis zu seinem Sohne Saul: \"Nimm dir einen von den Knechten; mach dich auf, geh, such die Eselinnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Da durchstreifte er das Gebirge Ephraim und durchstreifte die Landschaft Salisa; aber sie fanden nichts. Dann durchstreiften sie die Landschaft Saalim, wieder war nichts zu finden. Dann durchstreifte er das Gebiet Benjamins. Aber auch da fanden sie nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Schon waren sie in die Landschaft Suph gekommen. Da sprach Saul zu seinem Diener bei ihm: \"Komm, wir kehren um! Sonst könnte mein Vater die Eselinnen aufgeben und sich um uns sorgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Da sprach jener zu ihm: \"In dieser Stadt ist ein Gottesmann. Und der Mann ist angesehen. Alles, was er sagt, trifft alsbald ein. Laßt uns hingehen! Vielleicht bescheidet er uns über unseren Weg, den wir einzuschlagen haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Da sprach Saul zu seinem Diener: \"Wenn wir gehen, was bringen wir dann dem Mann? Das Brot in unseren Taschen ist ausgegangen, und ein Schmuckstück kann man dem Gottesmann nicht geben. Was haben wir sonst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Da erwiderte der Diener nochmals dem Saul und sprach: \"Bei mir findet sich ein Viertelsilberling. Den gebe ich dem Gottesmann, daß er uns über unseren Weg bescheide.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Vor alters sagte man in Israel, wenn man Gott befragen ging, also: \"Kommt, lasset uns zum Seher gehen!\" Denn die jetzt Propheten genannt werden, hießen vor Zeiten Seher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Da sprach Saul zu seinem Diener: \"Du hast recht. Auf! Laßt uns gehen!\" So gingen sie zur Stadt, wo der Gottesmann war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Sie gingen nun die Steige zur Stadt hinan. Da trafen sie Mädchen, die zum Wasserschöpfen herauskamen. Da sprachen sie zu ihnen: \"Ist der Seher daheim?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Da antworteten sie ihnen und sprachen: \"Ja, er ist für dich zu haben. Beeile dich jetzt! Denn heute ist er in die Stadt gekommen, weil heute das Volk ein Opfer auf der Höhe hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kommt ihr in die Stadt, dann trefft ihr ihn noch an, bevor er auf die Höhe zum Mahle geht. Denn das Volk speist nicht, bis er kommt. Erst segnet er das Opfermahl, dann essen die Geladenen. Geht also hinauf! Denn dort könnt ihr ihn noch treffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'So gingen sie zur Stadt hinauf. Als sie aber mitten in die Stadt kamen, begegnete ihnen eben Samuel, um zur Höhe hinaufzusteigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Der Herr aber hatte Samuels Ohr einen Tag vor Sauls Ankunft geöffnet; er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '\"Morgen um diese Zeit sende ich dir aus dem Lande Benjamin einen Mann. Den salbe zum Fürsten meines Volkes Israel! Er wird mein Volk aus der Philister Hand erretten. Denn ich habe nach meinem Volke gesehen; ist doch sein Hilferuf zu mir gedrungen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kaum hatte Samuel den Saul erblickt, hatte ihn schon der Herr beschieden: \"Dies ist der Mann, von dem ich dir gesagt: \'Er wird mein Volk regieren.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Da trat Saul zu Samuel mitten im Tor und sprach: \"Sag mir doch: Wo ist das Haus des Sehers?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Da erwiderte Samuel dem Saul und sprach: \"Ich bin der Seher. Gehet vor mir auf die Höhe und esset heute mit mir! Morgen lasse ich dich ziehen und bescheide dich über alles, was du auf dem Herzen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Um die Eselinnen, die dir heute vor drei Tagen verloren gingen, sorge dich nicht! Sie haben sich gefunden. Wem aber kommt zu, was Gesamtisrael wünscht? Nicht dir und deinem ganzen Vaterhause?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Da antwortete Saul und sprach: \"Bin ich nicht ein Benjaminite aus einem der kleinsten Stämme Israels? Und meine Sippe ist die geringste von allen Sippen des Benjaminstammes. Warum redest du so zu mir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel aber nahm Saul und seinen Diener, führte sie in die Halle und gab ihnen einen Platz an der Spitze der Geladenen. Deren waren es an dreißig Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Und Samuel sagte zum Koch: \"Gib das Stück her, das ich dir gegeben und wovon ich dir gesagt: \'Leg es beiseite!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Da nahm der Koch die Keule und legte sie Saul vor. Jener sprach: \"Das ist der Rest. Leg dir vor und iß! Denn zu seiner Zeit ward er aufgespart, schon als ich sagte: \'Ich habe die Leute eingeladen.\'\" So aß Saul mit Samuel an jenem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Dann stiegen sie von der Höhe in die Stadt hinab, und er redete mit Saul noch auf dem Dache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Sie standen früh auf. Als die Morgenröte anbrach, rief Samuel zu Saul auf das Dach hinauf: \"Steh auf, daß ich dich begleite!\" Und Saul stand auf, und sie beide, er und Samuel, gingen hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Sie schritten eben dem Ende der Stadt zu. Da sprach Samuel zu Saul: \"Heiß den Diener uns weit vorausgehen!\" Da ging dieser voraus. \"Du aber bleib stehen, daß ich dir ein Gotteswort kundtue!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Darauf nahm Samuel die Ölflasche, goß sie auf sein Haupt und küßte ihn. Dann sprach er: \"Damit salbt dich der Herr zum Fürsten über sein Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Gehst du heute von mir weg, so triffst du zwei Männer bei Rachels Grab an der Grenze Benjamins im Glutschatten. Sie sagen zu dir: \'Die Eselinnen, die du suchen gegangen, haben sich gefunden. Dein Vater hat die Sache mit den Eselinnen aufgegeben; dafür ist er um euch besorgt und sagt: Was soll ich für meinen Sohn tun?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Gehst du von da weiter und kommst du zur Taboreiche, so stoßen dort drei Männer zu dir. Sie gehen zu der Gottheit nach Betel hinauf. Der eine führt drei Böcklein mit sich, der andere hat drei Brotlaibe und der dritte einen Schlauch Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Sie grüßen dich und geben dir zwei Brote. Nimm sie von ihnen an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Hernach kommst du zu dem Gotteshügel, wo die Philisterposten sind, und wenn du dorthin in die Stadt kommst, dann triffst du einen Trupp Propheten, die von der Höhe kommen; ihnen voraus Harfen, Pauken, Flöten und Zithern; sie selbst aber sind verzückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Dann kommt über dich der Geist des Herrn, und du wirst mit ihnen verzückt und wandelst dich in einen anderen Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Wenn diese Zeichen bei dir eintreffen, dann tu dein Möglichstes! Denn Gott ist mit dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Geh vor mir nach dem Gilgal hinab! Ich komme zu dir hinab, Brandopfer darzubringen und Mahlopfer zu schlachten. Warte aber sieben Tage, bis ich zu dir komme und dir kundtue, was du tun sollst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Als er den Rücken wandte, um von Samuel wegzugehen, da wandelte ihm Gott sein Inneres. Und an jenem Tage trafen alle diese Zeichen ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Als sie dorthin nach dem Hügel kamen, eilte ihm ein Trupp Propheten entgegen. Auch der Geist Gottes kam über ihn, und er ward mitten unter ihnen verzückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Und alle, die ihn von früher her kannten und sahen, wie er mit den Propheten verzückt war, diese Leute sagten zueinander: \"Was ist mit dem Sohn des Kis geschehen? Ist auch Saul unter den Propheten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Da erwiderte ein Mann von dort und sprach: \"Aber wer ist denn ihr Vater?\" Daher entstand das Sprichwort: \"Auch Saul unter den Propheten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Als er aufhörte, verzückt zu sein, kam er auf die Höhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Da fragte Sauls Oheim ihn und seinen Diener: \"Wohin seid ihr gegangen?\" Er sprach: \"Die Eselinnen zu suchen, und als wir sahen, daß sie nicht da waren, gingen wir zu Samuel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Da sagte Sauls Oheim: \"Sag mir doch, was Samuel zu euch gesprochen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Da sprach Saul zu seinem Oheim: \"Er hat uns mitgeteilt, daß die Eselinnen gefunden seien.\" Aber die Sache mit dem Königtum, wovon Samuel gesprochen, sagte er ihm nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Da entbot Samuel das Volk zum Herrn auf die Mispa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Er sprach zu den Söhnen Israels: \"So spricht der Herr, Gott Israels: \'Ich habe aus Ägypten Israel herausgeführt und aus der Hand Ägyptens und all der Königreiche euch gerettet, die euch bedrängt haben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Ihr aber verwerft jetzt euren Gott, der euch Retter war, in all euren Leiden und Nöten half. Ihr sagt: \'Nein! Einen König sollst du über uns setzen!\' Nun denn! So stellt euch vor dem Herrn auf, nach euren Stämmen und Tausendschaften!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Hierauf ließ Samuel alle Stämme Israels antreten. Da traf es den Stamm Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Hierauf ließ er den Stamm Benjamin sippenweise antreten. Da traf es die Sippe der Matriter. Dann traf es Saul, des Kis Sohn. Da suchten sie ihn. Er aber war nicht zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Da fragten sie nochmals den Herrn: \"Ist der Mann überhaupt hierher gekommen?\" Da sprach der Herr: \"Ja! Er hält sich beim Gepäck versteckt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Da liefen sie hin und holten ihn von dort. Als er mitten unters Volk trat, überragte er alles Volk von seiner Schulter an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Da sprach Samuel zum ganzen Volk: \"Seht ihr nicht? Der, den sich der Herr erkoren, hat nicht seinesgleichen im ganzen Volk.\" Und das ganze Volk jubelte und rief:\"Es lebe der König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Hernach trug Samuel dem Volk die Rechte des Königtums vor. Dann schrieb er sie in das Buch und legte dies vor dem Herrn nieder. Dann entließ Samuel das ganze Volk, jeden in seine Heimat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Auch Saul war in seine Heimat nach Gibea gegangen, und mit ihm ging die Schar, deren Herz Gott gerührt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Bösewichter aber hatten gesagt: \"Was kann uns dieser helfen?\" Und sie verachteten ihn und sie hatten ihm kein Geschenk gebracht. Er aber stellte sich wie taub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Nun zog der Ammoniter Nachas herauf und belagerte Jabes in Gilead. Da sprachen alle Männer von Jabes zu Nachas: \"Schließ mit uns einen Vergleich! Dann unterwerfen wir uns dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Da sprach der Ammoniter Nachas zu ihnen: \"Ich schließe mit euch einen Vergleich, daß ich euch allen das rechte Auge aussteche und damit ganz Israel einen Schimpf antue.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Da sprachen die Ältesten von Jabes zu ihm: \"Laß uns sieben Tage Zeit! Wir wollen Boten durch das ganze Gebiet Israels senden. Hilft uns niemand, dann ergeben wir uns dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'So kamen die Boten auch nach dem Gibea Sauls und meldeten dem Volk die Lage. Da brach das ganze Volk in lautes Weinen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Eben kam Saul hinter den Rindern vom Felde heim. Da fragte Saul: \"Was ist dem Volk, daß es weint?\" Nun berichteten sie ihm die Lage der Männer von Jabes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Da kam Gottes Geist über Saul, als er diese Dinge vernahm, und sein Zorn erglühte heftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Dann nahm er ein paar Rinder, zerstückelte sie und sandte sie in Gesamtisrael durch die Boten umher mit dem Aufrufe: \"Wer nicht mit auszieht hinter Saul und Samuel her, dessen Nachwuchs soll es ebenso ergehen!\" Da befiel das Volk ein Herrnschrecken, und sie zogen aus wie ein Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Er musterte sie nun zu Bezek. Da waren es 300.000 Israeliten und 30.000 Judäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Da sagten sie zu den Boten, die gekommen waren: \"So sollt ihr zu den Männern von Jabes in Gilead sagen: \'Morgen wird euch Hilfe, wenn die Sonne brennt.\'\" Da gingen die Boten heim und meldeten es den Männern von Jabes. Da wurden diese froh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Und die Männer von Jabes sprachen: \"Morgen übergeben wir uns euch. Dann tut mit uns, wie euch gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Am anderen Morgen nun teilte Saul das Volk in drei Haufen. Und sie drangen in das Lager um die Morgenwache und schlugen Ammon, bis der Tag heiß ward. Was übrigblieb, zerstreute sich; nicht zwei davon blieben beisammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Da sprach das Volk zu Samuel: \"Wer sind die, die gesagt haben: \'Saul soll nicht König über uns werden?\' Schafft die Männer her, daß wir sie totschlagen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Da sprach Saul: \"An diesem Tage soll niemand den Tod erleiden! Denn heute hat der Herr Israel zum Siege verholfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Da sprach Samuel zum Volke. \"Kommt! Laßt uns nach dem Gilgal ziehen und dort dem Königtum die Weihe geben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'So zog das ganze Volk nach dem Gilgal. Und sie machten dort Saul vor dem Herrn im Gilgal zum König. Dann schlachteten sie dort Mahlopfer vor dem Herrn. Und Saul und alle anderen Männer Israels waren dort überaus froh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Und Samuel sprach zu ganz Israel: \"Ich habe eurer Stimme in allem gefolgt, was ihr mir gesagt. Ich setzte über euch einen König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Nun führt der König euch an. Ich selbst aber bin alt und grau. Doch meine Söhne sind noch bei euch. Und ich selbst habe euch von meiner Jugend an bis auf diesen Tag angeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Hier bin ich. Verklagt mich beim Herrn und seinem Gesalbten! Wessen Ochsen habe ich weggenommen? Wessen Esel fortgeführt? Wen habe ich gedrückt? Wem habe ich Gewalt getan? Von wem habe ich Sühnegeld empfangen, so daß ich mein Auge ihm gegenüber zudrückte? Ich will es euch erstatten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Sie sprachen: \"Du hast uns nicht bedrückt noch Gewalt angetan und nicht das Geringste aus jemandes Hand genommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Da sprach er zu ihnen: \"Der Herr sei mein Zeuge euch gegenüber, und sein Gesalbter sei heute Zeuge, daß ihr in meiner Hand nicht das Geringste gefunden habt!\" Da sprachen sie: \"Jawohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Da sprach Samuel zum Volk: \"Der Herr hat Moses und Aaron eingesetzt und eure Väter aus Ägypterland heraufgeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Nun kommt her, daß ich vor dem Herrn mit euch rechte über alle Wohltaten des Herrn, die er an euch und euren Vätern getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Als Jakob nach Ägypten gekommen war, da schrien eure Väter zum Herrn. Und der Herr sandte Moses und Aaron. Und diese führten eure Väter aus Ägypten und gaben ihnen an dieser Stätte Siedlungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Aber sie vergaßen den Herrn, ihren Gott. Da verkaufte er sie in die Hand Siseras, des Feldherrn von Chasor, dann in die der Philister und in die des Moabkönigs, und sie bekriegten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Da schrien sie zum Herrn und sprachen: \'Wir haben gesündigt, daß wir den Herrn verlassen haben und dann den Baalen und Astarten dienten. Nun aber rette uns aus unserer Feinde Hand! Dann wollen wir Dir dienen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Da erweckte der Herr Jerubbaal, und zwar den Richter, Jephte und Samuel und rettete euch aus eurer Feinde Hand ringsum, so daß ihr sicher wohntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Als ihr aber sahet, daß der Ammoniterkönig Nachas gegen euch heranrückte, spracht ihr zu mir: \'Nein! Ein König herrsche über uns!\' Und doch ist der Herr, euer Gott, euer König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nun denn! Da ist der König, den ihr erwählt und den ihr gefordert habt. Seht! Der Herr hat euch einen König gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Wenn ihr den Herrn fürchtet, dann dienet ihm und hört seine Stimme. Dem Mund des Herrn dürft ihr nicht widersprechen. Ihr selbst und der König, der über euch herrscht, seid dem Herrn, eurem Gott, folgsam!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Hört ihr aber nicht auf des Herrn Stimme und widersprecht ihr dem Munde des Herrn, dann ist des Herrn Hand wider euch wie gegen eure Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Kommt jetzt her und seht das große Werk, das der Herr vor euch tut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Ist nicht jetzt die Weizenernte? Ich rufe nun zum Herrn, daß er Gewitter und Regen sende. Dann erkennt ihr und seht, daß eure Bosheit groß ist, die ihr vor dem Herrn getan, indem ihr für euch einen König gefordert habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Dann rief Samuel zum Herrn, und der Herr sandte an jenem Tag Gewitter und Regen. So kam das Volk in große Angst vor dem Herrn und Samuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Und das ganze Volk sprach zu Samuel: \"Bete zum Herrn, deinem Gott, für deine Knechte, daß wir nicht sterben! Denn wir haben zu all unseren Sünden das Unrecht hinzugefügt, für uns einen König zu fordern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Da sprach Samuel zum Volke: \"Seid ohne Furcht! Ihr habt zwar all dies Böse getan. Aber laßt wenigstens nicht vom Herrn, sondern dient dem Herrn aus eurem ganzen Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ihr dürft keinesfalls zu den Götzen abfallen, die nichts nützen und nicht retten, weil sie Nichtse sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Denn der Herr verstößt um seines großen Namens willen nicht sein Volk, hat es doch dem Herrn gefallen, euch zum Volk für sich zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Aber dessen ungeachtet sei es fern von mir, daß ich mich am Herrn versündigte und abließe, für euch zu beten! Vielmehr weise ich euch den guten und geraden Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Nur fürchtet den Herrn und dient ihm getreulich aus ganzem Herzen! Denn seht: Was hat er Großes an euch getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Wenn ihr aber böse handelt, dann werdet ihr samt eurem König weggerafft werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul war fünfzig Jahre alt, als er König ward, und zwei Jahre hatte er über Israel geherrscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Saul warb nun');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, '000 aus Israel an. Bei Saul aber blieben 2.000 zu Mikmas und auf dem Gebirge Betels, 1.000 aber waren bei Jonatan zu Gibea Benjamins. Den Rest hatte er entlassen, jeden in sein Zeit. 3 Da schlug Jonatan den Philistervogt in Geba. Die Philister aber erfuhren es. Nun hatte Saul im ganzen Land in das Horn stoßen und verkünden lassen: \"Hören sollen es die auf der anderen Seite!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'So vernahm ganz Israel die Kunde: \"Saul hat den Philistervogt geschlagen, und Israel ist bei den Philistern anrüchig geworden.\" Da ward das Volk aufgeboten und folgte Saul nach dem Gilgal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Die Philister aber hatten sich zum Kampf gegen Israel versammelt, 30.000 Wagen und');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, '000 Reiter sowie Fußvolk, an Menge gleich dem Sand am Meeresufer. So zogen sie herauf und lagerten zu Mikmas, östlich von Bet Awen. 6 Israels Männer aber merkten, daß sie in Not kämen; denn das Volk war bestürzt. So verbarg sich das Volk in Höhlen, Erdlöchern, Felsspalten, Grüften und Gruben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Und zuletzt zogen sie über die Jordanfurten in das Land Gad und Gilead. Saul aber blieb immer noch im Gilgal, obwohl das ganze Volk sich heftig nach ihm sehnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Er wartete sieben Tage bis zu der Frist, die Samuel bestimmt hatte. Aber Samuel kam nicht nach dem Gilgal. Da verlief sich das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'So sprach denn Saul: \"Bringt mir das Brandopfer und die Mahlopfer!\" Dann vollzog er das Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Eben war er mit dem Darbringen des Brandopfers fertig, da kam Samuel. Saul ging ihm nun entgegen, ihn zu begrüßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Da sprach Samuel: \"Was hast du getan?\" Saul sprach: \"Ich habe gesehen, wie das Volk mir davongelaufen ist, und du bist nicht zur bestimmten Frist eingetroffen, obschon die Philister in Mikmas versammelt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Da sprach ich: \'Nun werden die Philister gegen mich ins Gilgal ziehen, bevor ich den Herrn begütigt habe.\' Und so überwand ich mich und brachte das Brandopfer dar.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Da sprach Samuel zu Saul: \"Du hast töricht gehandelt. Hättest du des Herrn, deines Gottes, Befehl, den er dir gegeben, befolgt, dann hätte der Herr dein Königtum über Israel für immer bestätigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'So aber wird dein Königtum keinen Bestand haben. Der Herr hat sich schon einen Mann nach seinem Herzen ausgesucht, und ihn bestellte er zum Fürsten über sein Volk. Denn du hast nicht befolgt, was dir der Herr befohlen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Dann erhob sich Samuel und ging aus dem Gilgal nach Gibea Benjamins hinauf. Da musterte Saul das Volk, das sich bei ihm fand, an 600 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul und sein Sohn Jonatan sowie das Volk, das sich bei ihm fand, weilten in Gibea Benjamin. Die Philister aber lagerten in Mikmas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Da zog eine Plündererschar aus dem Philisterlager in drei Haufen. Der eine Haufe wandte sich nach dem Wege von Ophra ins Gebiet von Saul,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'der andere nach dem von Betchoron und der dritte nach dem Wege über den Hügel, der über das Hyänental auf die Steppe schaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Im ganzen Lande Israel aber fand sich kein Schmied. Denn die Philister hatten gesagt: \"Die Hebräer machen sich sonst Schwerter oder Lanzen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'So mußte ganz Israel zu den Philistern hinabgehen, wenn jemand seine Pflugschar, seinen Karst, seine Axt und seinen Ochsenstachel schmieden lassen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Harte Steine dienten als Schneiden an den Pflugscharen, Karsten, Dreizacken, Äxten und zum Wetzen der Sicheln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'So hatte sich am Kampftage weder Schwert noch Lanze beim gesamten Kriegsvolk vorgefunden, das bei Saul und Jonatan war. Nur bei Saul und seinem Sohn Jonatan fanden sich solche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Da rückte ein Philisterposten gegen den Paß von Mikmas vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Eines Tages nun sprach Sauls Sohn Jonatan zu dem Diener, der ihm die Waffen trug: \"Auf! Laß uns hinübergehen, gerade zu dem Philisterposten, der dort auf der anderen Seite steht!\" Seinem Vater aber hatte er nichts davon gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul saß nämlich gerade am Ende von Gibea unter dem Granatbaume bei Migron, und das Volk bei ihm war an 600 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Und Achia, der Sohn Achitubs, des Bruders Ikabods, der Enkel des Pinechas, des Sohnes Elis, des Priesters des Herrn zu Silo, trug das Ephod. Das Volk aber wußte nicht, daß Jonatan fortgegangen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Zwischen den Pässen, die Jonatan gegen den Philisterposten hin zu überschreiten suchte, war nun hüben und drüben eine Reihe Felszacken. Die eine hieß Boses, die andere Sene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Die eine Zackenreihe steht säulengleich auf der Nordseite, Mikmas gegenüber, die andere auf der Südseite gegenüber Geba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Da sprach Jonatan zu dem Diener, der seine Waffen trug: \"Auf! Wir wollen hinübergehen zu dem Posten dieser Unbeschnittenen. Vielleicht tut der Herr etwas für uns. Denn für den Herrn ist es kein Hindernis, durch viel oder wenig zu helfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Da sprach zu ihm sein Waffenträger: \"Tu, was du in deinem Herzen hast! Reck dich! Sieh, ich bin dir zur Seite nach deinem Wunsch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Da sprach Jonatan: \"Nun gehen wir zu den Männern hinüber und zeigen uns ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Sprechen sie so zu uns: \'Haltet, bis wir zu euch kommen!\', dann bleiben wir auf unserem Platze stehen und steigen nicht zu ihnen hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Sagen sie aber: \'Kommt zu uns herauf!\', dann steigen wir hinauf. Dann nämlich gibt sie der Herr in unsere Hand. Dies sei uns das Zeichen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Beide zeigten sich also dem Philisterposten. Da sprachen die Philister: \"Hier kommen Hebräer aus den Löchern, in die sie sich verkrochen haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Und die Leute des Postens riefen zu Jonatan und seinem Waffenträger und sprachen: \"Kommt zu uns herauf! Wir zeigen euch etwas.\" Da sprach Jonatan zu seinem Waffenträger: \"Steig mir nach! Der Herr gibt sie in Israels Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Jonatan klomm nun auf Händen und Füßen hinauf, hinter ihm sein Waffenträger. Da fielen sie vor Jonatan, und sein Waffenträger tötete sie hinter ihm her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'So traf der erste Schlag, den Jonatan und sein Waffenträger getan, ungefähr zwanzig Mann, auf einer Strecke ungefähr einen halben Morgen lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Da entstand ein Schrecken im Lager und auf dem Feld und beim ganzen Volk. Auch der Posten und die Plündererschar waren erschrocken. Und die Gegend bebte, und so ward ein Gottesschrecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Sauls Späher zu Gibea Benjamins sahen nun, daß die Menge hin und her wogte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Da sprach Saul zu dem Volke bei ihm: \"Haltet doch Musterung und seht nach, wer von uns fortgegangen ist!\" Da hielten sie Musterung. Und Jonatan und sein Waffenträger fehlten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Da sprach Saul zu Achia: \"Bring die Gottestasche her!\" Denn damals hatten die Israeliten noch die Gottestasche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Solange aber Saul mit dem Priester redete, ward das Getöse in dem Philisterlager immer stärker. Da sprach Saul zum Priester: \"Laß es sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Und Saul und das ganze Volk bei ihm wurden mutig, und sie kamen auf den Kampfplatz. Da ward eines jeden Schwert gegen den anderen gerichtet. Eine schreckliche Verwirrung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Hebräer aber waren seit langem bei den Philistern und mit ihnen ins Feld gezogen. Auch diese fielen ab, um sich Israel bei Saul und Jonatan anzuschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Und als alle anderen israelitischen Männer, die sich auf dem Gebirge Ephraim versteckt hielten, hörten, die Philister seien geflohen, setzten auch sie ihnen nach, sie zu bekämpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'So half der Herr an jenem Tage Israel. Der Kampf aber hatte sich über Bet Awen ausgedehnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'An jenem Tage aber kasteite sich Israels Mannschaft, hatte doch Saul das Volk schwören lassen: \"Verflucht sei der Mann, der Speise vor dem Abend ißt, bevor ich an meinen Feinden Rache genommen!\" Und so hatte das ganze Volk keine Speise gekostet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Die ganze Schar aber war auf die Bergeshöhe gelangt. Auf der Hochebene aber gab es Honig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Als das Volk auf die Höhe kam, floß dort der Honig; aber niemand führte die Hand zum Munde, weil sich das Volk vor dem Schwur fürchtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonatan aber hatte nicht gehört, wie sein Vater das Volk beschworen hatte. So streckte er die Spitze des Stabes in seiner Hand aus, tauchte sie in eine Honigwabe und führte seine Hand zum Munde. Da wurden seine Augen wieder hell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Nun erhob ein Mann aus dem Volke seine Stimme und sprach: \"Dein Vater hat das Volk schwören lassen: \'Verflucht sei der Mann, der heute etwas genießt!\'\" Das Volk aber war matt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Da sprach Jonatan: \"Mein Vater stürzt das Land ins Unglück. Seht doch, wie meine Augen leuchten, weil ich dies bißchen Honig genossen habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Um wieviel mehr - hätte das Volk heute von seiner Feindesbeute, die es gemacht, tüchtig gegessen! Wäre dann nicht die Niederlage der Philister noch größer geworden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'So schlugen sie an jenem Tage die Philister von Mikmas bis Ajjalon. Das Volk aber war sehr abgemattet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Da machte sich das Volk über die Beute her, nahm Schafe, Rinder und Kälber und wollte sie am Boden schlachten. Dabei wollte das Volk sogar das Blut genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Da meldete man es Saul: \"Das Volk versündigt sich gegen den Herrn, es will sogar das Blut genießen.\" Da sprach er: \"Ihr tut Unrecht. Wälzt mir sogleich einen großen Stein her!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Dann sprach Saul: \"Zerstreut euch unter das Volk und sagt ihnen: \'Bringe jeder sein Rind und sein Schaf zu mir! Dann schlachtet es hier und esset und versündigt euch nicht gegen den Herrn, daß ihr das Blut mitgenießet!\'\" Da brachte das ganze Volk eigenhändig jeder sein Jungtier, noch in der gleichen Nacht, und sie schlachteten es dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Und Saul baute für den Herrn einen Altar. Das war der erste Altar, den er dem Herrn baute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Dann sprach Saul: \"Laßt uns den Philistern nächtens nachsetzen und sie zusammenhauen bis zum Morgenlicht und keinen von ihnen übriglassen!\" Da sprachen sie: \"Tu, wie dir gut dünkt!\" Da sprach der Priester: \"Laßt uns zuerst zu Gott beten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Da befragte Saul Gott: \"Soll ich den Philistern nachsetzen? Gibst du sie in Israels Hand?\" Aber er gab ihm jenes Tages keine Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Da sprach Saul: \"Tretet her, all ihr Vorkämpfer des Volkes! Forschet und seht nach, durch wen heute diese Schuld geworden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Denn so wahr der Herr lebt, der Israel half! Läge es selbst an meinem Sohne Jonatan, so müßte er sterben!\" Aber niemand vom Volk gab ihm Bescheid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Da sprach er zu ganz Israel. \"Tretet auf die eine Seite, und ich mit meinem Sohn Jonatan auf die andere!\" Da sprach das Volk zu Saul: \"Tu, was dir gutdünkt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Da sprach Saul zum Herrn: \"Gott Israels! Gib den richtigen Bescheid!\" Da wurden Jonatan und Saul getroffen. Das Volk aber ging frei aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Da sprach Saul: \"Loset zwischen mir und meinem Sohne Jonatan!\" Da ward Jonatan getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Da sprach Saul zu Jonatan: \"Sag mir, was du getan hast!\" Jonatan gestand ihm und sprach: \"Ich habe mit der Spitze des Stabes in meiner Hand ein wenig Honig gekostet. Ich bin bereit zu sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Da sprach Saul: \"So möge mir Gott antun dies und das! Ja, Jonatan, du mußt sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Da sprach das Volk zu Saul: \"Sterben soll Jonatan, der diesen großen Sieg in Israel errungen hat? Das sei ferne! So wahr der Herr lebt! Nicht ein Haar darf von seinem Haupte zu Boden fallen. Denn nächst Gott hat er diesen Tag geschaffen.\" So befreite das Volk Jonatan vom Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Saul gab nun die Verfolgung der Philister auf. Die Philister aber waren in ihre Heimat gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'So errang Saul das Königtum über Israel. Er kämpfte ringsum gegen alle seine Feinde, gegen Moab, die Ammoniter, Edom, den König von Soba und gegen die Philister. Und wohin er sich wandte, brachte er Verheerung-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Er bewies Tapferkeit, und so schlug er auch Amalek und rettete Israel aus seines Plünderers Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Sauls Söhne aber waren Jonatan, Iswi und Malkisua. Seine Töchter hießen die ältere Merab und die jüngere Mikal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Sauls Weib hieß Achinoam und war des Achimaas Tochter. Sein Heerführer hieß Abner; er war der Sohn des Ner, und dieser Sauls Oheim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Sauls Vater Kis und Abners Vater Ner waren Abiels Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Solange Saul lebte, tobte der Krieg gegen die Philister. Sah Saul einen tapferen kriegstüchtigen Mann, so zog er ihn an sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel sprach zu Saul: \"Mich hat der Herr gesandt, dich zum König über sein Volk Israel zu salben. Nun höre auf die Stimme der Worte des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'So spricht der Herr der Heerscharen: \'Ich ahnde, was Amalek an Israel getan, dem es feindlich den Weg vertreten hat, als es aus Ägypten zog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Nun geh und schlage Amalek! Bannt es und alles, was ihm eigen ist! Du sollst es nicht schonen! Töte Männer samt Weibern, Kinder samt Säuglingen, Rinder, Schafe, Esel und Kamele!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Da bot Saul das Volk auf und musterte es zu Telaim, 200.000 Mann Fußvolk und 10.000 Judäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Dann zog Saul gegen die Amalekiterstadt und stieg in das Bachtal hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Und Saul sprach zu den Kenitern: \"Auf! Zieht euch zurück und geht aus Amaleks Mitte weg, daß ich euch nicht mit ihm wegraffe! Ihr habt Liebe allen Israeliten auf ihrem Herweg aus Ägypten erwiesen.\" Da zog sich der Keniter aus Amaleks Mitte zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul schlug nun Amalek von Chawila bis gegen Sur, östlich von Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Er fing auch Amalek lebendig. Das ganze übrige Volk aber bannte er zwar mit des Schwertes Schärfe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'doch schonten Saul und das Volk den Agag sowie das Beste der Schafe und Rinder, die vom zweiten Wurfe, und die Lämmer, überhaupt alles Wertvolle. Sie mochten sie eben nicht bannen. Nur, was gering und wertlos war, bannten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Da erging des Herrn Wort an Samuel also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '\"Mich reut, daß ich Saul zum König gemacht habe. Denn er hat sich von mir abgewandt und meine Worte nicht vollzogen.\" Dies verdroß Samuel, und er schrie zum Herrn die ganze Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Frühmorgens nun ging Samuel Saul entgegen. Da wurde Samuel gemeldet: \"Saul ist in den Garten gegangen und hat dort einen Posten aufgestellt.\" Da wandte er sich, zog weiter und stieg ins Gilgal hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Als Samuel schließlich zu Saul kam, sprach Saul zu ihm: \"Sei gesegnet von dem Herrn! Ich habe das Wort des Herrn vollstreckt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Da sprach Samuel: \"Aber was bedeutet dieses Schafeblöken in meinen Ohren? Und das Rindergebrüll, das ich höre?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Da sprach Saul: \"Das haben sie von den Amalekitern heimgebracht, weil das Volk die besten Schafe und Rinder geschont hat, um sie dem Herrn, deinem Gott, zu opfern. Das übrige haben wir gebannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Da sprach Samuel zu Saul: \"Halt ein, daß ich dir künde, was der Herr zu mir in dieser Nacht gesprochen!\" Da sagte er zu ihm: \"Sprich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Da sprach Samuel: \"Mochtest du auch klein sein in deinen Augen, du wurdest doch das Haupt der Stimme Israels. Und der Herr salbte dich zum König über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Nun sandte dich der Herr und sprach: \'Auf! Banne die Schuldigen, Amalek, und kämpfe gegen sie, bis sie vernichtet sind!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Warum hast du nicht auf des Herrn Stimme gehört? Du stürztest dich vielmehr auf die Beute und tatest, was dem Herrn mißfiel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Da sprach Saul zu Samuel: \"Ich habe ja der Stimme des Herrn gehorcht; zog ich doch auf dem Wege, den mich der Herr gesandt hat. Ich brachte den Amalekiterkönig Agag mit und bannte Amalek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Das Volk aber nahm aus der Beute Schafe und Rinder, den ersten Abhub des Banngutes, um es dem Herrn, deinem Gott, im Gilgal zu opfern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Da sprach Samuel: \"Hat der Herr an Brand- und Schlachtopfern gleiches Gefallen wie am Gehorsam gegen des Herrn Befehl? Gehorsam ist besser als Opfer, Hören besser als Widderfett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Ja, Widerstreben ist ebenso Sünde wie Wahrsagerei, Eigenmächtigkeit soviel wie Missetat und Götzendienst. Weil du des Herrn Wort verworfen, verwirft er dich auch als König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Da sprach Saul zu Samuel: \"Ich habe gesündigt; ich habe ja des Herrn Befehl übertreten und deine Worte. Ich fürchtete eben das Volk und hörte auf seine Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Aber jetzt vergib doch meine Sünde und kehre mit mir um, daß ich den Herrn anbete!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Da sprach Samuel zu Saul: \"Ich kehre nicht mit dir um. Weil du des Herrn Wort verworfen, so verwirft auch dich der Herr, daß du nimmer König seiest über Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Dann wandte sich Samuel zum Gehen. Da packte jener den Zipfel seines Mantels, und dieser riß ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Da sprach Samuel zu ihm: \"Heute reißt der Herr das Königtum Israels von dir weg und gibt es deinem Freunde, der besser ist als du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Gott ist immerdar gerade. Er lügt nicht und bereut nicht; denn er ist kein Mensch, daß er bereuen müßte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Da sprach er: \"Ich habe gesündigt. Aber gib mir wenigstens jetzt die Ehre vor den Ältesten meines Volkes und vor Israel und kehre mit mir um, daß ich den Herrn, deinen Gott, anbete!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Da begleitete Samuel den Saul. Dann betete Saul den Herrn an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Samuel aber sprach: \"Bringt mir den Amalekiterkönig Agag!\" Da ging Agag freudig auf ihn zu. Und Agag sprach: \"So ist also des Todes Bitterkeit gewichen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Da sprach Samuel: \"Wie dein Schwert Weiber kinderlos gemacht, so werde unter den Weibern auch deine Mutter kinderlos!\" Und Samuel hieb Agag in Stücke vor dem Herrn im Gilgal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Dann ging Samuel auf die Rama. Saul aber ging in sein Haus nach Gibea Sauls hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel aber sah Saul nicht mehr bis zu seinem Todestag. Doch trauerte Samuel um Saul. Aber den Herrn hatte es gereut, daß er Saul zum König über Israel gesetzt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Da sprach der Herr zu Samuel: \"Wie lange willst du um Saul trauern? Ich habe ihn verworfen, daß er nicht mehr König über Israel sei. Fülle dein Horn mit Öl und geh! Ich sende dich zu dem Bethlehemiten Isai. Denn unter seinen Söhnen habe ich mir einen zum König ersehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Da sprach Samuel: \"Wie kann ich gehen? Hört es Saul, dann bringt er mich um.\" Da sprach der Herr: \"Nimm eine junge Kuh zur Hand und sprich: \'Dem Herrn zu opfern, komme ich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Lade zum Opfer Isai ein! Dann lasse ich dich wissen, was du ihm tun sollst. Salbe mir den, den ich dir nenne!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Und Samuel tat, wie ihm der Herr gesagt, und kam nach Bethlehem. Da eilten ihm die Ältesten der Stadt entgegen und sprachen: \"Bringt dein Kommen Heil?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Er sprach: \"Heil! Ich komme, dem Herrn zu opfern. Heiligt euch und kommt mit mir zum Opfer!\" Dann hieß er auch Isai und seine Söhne sich heiligen und lud sie zum Opfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Als sie kamen, sah er Eliab und sprach: \"Wie der Herr, so sein Gesalbter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Da sprach der Herr zu Samuel: \"Sieh nicht auf sein Aussehen und seinen hohen Wuchs! Denn ich verschmähe ihn, sieht doch kein Mensch auf den Grund. Der Mensch schaut auf das Äußere, der Herr aber schaut auf das Herz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Da rief Isai den Abinadab und führte ihn Samuel vor. Er aber sprach: \"Auch diesen hat der Herr nicht erkoren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Dann führte Isai den Samma vor. Er aber sprach: \"Auch diesen hat der Herr nicht erkoren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'So führte Isai seine sieben Söhne vor Samuel. Aber Samuel sprach zu Isai: \"Der Herr hat diese nicht erkoren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Dann fragte Samuel den Isai: \"Sind das die Jünglinge alle? Er sprach: \"Noch ist der Jüngste übrig. Dieser hütet eben die Schafe.\" Da sprach Samuel zu Isai: \"Schick hin und laß ihn holen! Denn wir setzen uns nicht zu Tisch, bis er herkommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Da schickte er hin und ließ ihn kommen. Er aber war blond; zugleich hatte er schöne Augen und war wohlgebildet. Da sprach der Herr: \"Auf! Salbe ihn! Dieser ist es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Da nahm Samuel das Ölhorn und salbte ihn inmitten seiner Brüder. Da kam des Herrn Geist auf David von dem Tag an und weiterhin. Samuel aber brach auf und ging auf die Rama.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Des Herrn Geist aber wich von Saul. Ihn verstörte ein böser Geist vom Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Da sprachen Sauls Diener zu ihm: \"Dich verstört ein böser Gottesgeist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Unser Herr spreche nur! Deine Diener sind dir zu Willen. Sie suchen einen Mann, der die Zither zu spielen versteht. Sooft ein böser Gottesgeist über dich kommt, spiele er, daß dir besser werde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Da sprach Saul zu seinen Dienern: \"Erkundet für mich einen Mann, der gut zu spielen weiß, und bringt ihn mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Da hob einer der Diener an und sprach: \"Ich habe einen Sohn des Bethlehemiten Isai gesehen. Er ist des Saitenspiels kundig und ein tüchtiger Krieger, kampferprobt, dazu des Wortes mächtig und ein Mann von Wuchs. Dazu ist der Herr mit ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Da sandte Saul Boten an Isai und ließ sagen: \"Schick mir deinen Sohn David, der bei den Schafen weilt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Da nahm Isai einen Scheffel Brot, einen Schlauch Wein und ein Ziegenböckchen und sandte es durch seinen Sohn David an Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'So kam David zu Saul und trat in seinen Dienst. Er gewann ihn sehr lieb, und so ward er sein Waffenträger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Da schickte Saul zu Isai und ließ sagen: \"Laß David in meine Dienste treten! Denn er gefällt mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Sooft nun der Gottesgeist über Saul kam, nahm David die Zither und spielte mit seiner Hand. Da ward es Saul leichter und besser, wich doch der böse Geist von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Da versammelten die Philister ihr Heer zum Kampfe. Sie sammelten sich bei Soko in Juda und lagerten zwischen Soko und Azeka zu Ephes Dammim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Auch Saul und die Mannschaft Israels hatten sich gesammelt, und sie lagerten im Terebinthentale. Sie rüsteten sich zum Angriff auf die Philister.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Die Philister aber standen an dem Gebirge auf der einen Seite, und Israel auf der anderen; das Tal aber lag dazwischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Da trat ein jüngerer Mann aus den Reihen der Philister. Er hieß Goliat und war aus Gat, sechs Ellen und eine Spanne hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Er hatte einen Helm aus Erz auf dem Haupte und trug einen Schuppenpanzer. Der Panzer wog 5.000 Ring Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'An den Beinen trug er eherne Schienen und zwischen den Schultern einen ehernen Nackenschirm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Sein Speerschaft war wie ein Weberbaum, und seine Lanzenspitze war 600 Ring Eisen schwer. Und vor ihm schritt ein Schildträger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Er stellte sich nun hin, rief Israels Reihen zu und sprach zu ihnen: \"Warum zieht ihr kampfgerüstet aus? Bin ich nicht der Philister, und ihr seid Sauls Knechte? Wählt aus euch einen Mann, daß er zu mir herabkomme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Kann er mit mir kämpfen und schlägt er mich, dann wollen wir euch untertan sein. Komme aber ich ihm bei und schlage ihn, dann müßt ihr uns untertan sein und uns dienen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Weiter sprach der Philister: \"Ich höhne heute Israels Reihen. Stellt mir einen Mann, daß wir miteinander kämpfen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Saul aber und ganz Israel hörten diese Worte des Philisters. Da erschraken sie und fürchteten sich recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David aber war der Sohn jenes Ephratiters aus Bethlehem in Juda namens Isai. Er hatte acht Söhne. Der Mann aber war in Sauls Tagen schon betagt unter den Männern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'So zogen die drei ältesten Söhne Isais, die Saul gefolgt waren, in den Kampf. Und seine drei Söhne, die in den Krieg zogen, hießen Eliab, der Erstgeborene, Abinadab, sein zweiter, und Samma, der dritte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David aber war der jüngste. Die drei ältesten also waren Saul gefolgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David ging nun öfters von Saul heim, seines Vaters Schafe in Bethlehem zu hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Der Philister aber trat früh und spät hervor und stellte sich hin, vierzig Tage lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Da sprach Isai zu seinem Sohne David: \"Nimm doch für deine Brüder ein Maß von diesem gerösteten Korn und diese zehn Brote und bringe sie schnell deinen Brüdern ins Lager!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Und diese zehn Milchkäse mögest du dem Obersten der Tausend bringen. Und deine Brüder sollst du begrüßen und ihren Sold mitbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul und sie und alle andere Mannschaft Israels liegen im Terebinthentale gegen die Philister zu Felde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Da übergab David frühmorgens die Schafe einem Hüter, nahm die Sachen und ging, wie ihn Isai geheißen hatte. Als er zu dem Wagenkreis kam, rückte das Heer eben zum Kampfe aus und erhob den Schlachtruf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'So standen Israel und die Philister kampfbereit, Reihe gegen Reihe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Da übergab David das Gepäck dem Troßwächter und lief zur Schlacht hin. Als er hinkam, begrüßte er seine Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Während er eben mit ihnen redete, kam der junge Mann, der Philister Goliat - so hieß er - aus Gat, aus der Reihe der Philister hervor und führte solche Worte. Und David hörte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Als aber Israels Mannschaft den Mann sah, flohen sie alle vor ihm und fürchteten sich recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Da sprach ein Mann aus Israel: \"Habt ihr diesen Mann hervortreten sehen? Nur um Israel zu höhnen, tritt er auf. Wer ihn schlüge, den beschenkte der König reichlich und gäbe ihm seine Tochter und machte seines Vaters Haus in Israel steuerfrei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Da sprach David zu den Mannen, die bei ihm standen: \"Was soll dem Manne werden, der diesen Philister schlägt und Schmach von Israel nimmt? Wer ist dieser unbeschnittene Philister, daß er die Kampfscharen des lebendigen Gottes höhnt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Da sagte ihm das Volk das gleiche: \"So wird dem Manne, der ihn schlägt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Da hörte ihn sein ältester Bruder Eliab mit den Mannen sprechen. Und Eliab geriet in heftigen Zorn über David und sprach: \"Wozu bist du herabgekommen? Wem hast du die paar Schafe da in der Steppe überlassen? Ich kenne deinen Übermut und deines Herzens Bosheit. Nur um den Kampf zu schauen, bist du herabgekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Da sprach David: \"Was habe ich jetzt getan? War es nicht bloß eine Frage?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Und wandte sich von ihm einem anderen zu und fragte das gleiche. Und das Volk beschied ihn wie das erstemal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Sie vernahmen aber auch die Worte, die David sprach, und meldeten sie Saul. Da ließ er ihn holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Und David sprach zu Saul: \"Niemand verliere seinetwegen den Mut! Dein Sklave geht und kämpft mit diesem Philister.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Da sprach Saul zu David: \"Du kannst nicht gegen diesen Philister ziehen und mit ihm kämpfen. Du bist ein Knabe. Er aber ist ein Kriegsmann von Jugend auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Da sprach David zu Saul: \"Dein Sklave hütet seinem Vater die Schafe. Ist da der Leu zugleich mit dem Bären gekommen und hat ein Schaf aus der Herde fortgetragen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'so bin ich ihm nachgelaufen, habe ihn geschlagen und es ihm aus dem Rachen gerissen. Stellte er sich gegen mich, dann habe ich ihn an der Mähne gepackt und ihn totgeschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Den Löwen und den Bären hat dein Sklave erschlagen, und diesem unbeschnittenen Philister geht es wie einem von jenen, weil er die Kampfscharen des lebendigen Gottes höhnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Dann sprach David: \"Der Herr, der mich aus Löwen- und Bärenpranken gerettet, kann mich auch aus dieses Philisters Hand retten.\" Da sprach Saul zu David: \"Geh hin! Der Herr ist mit dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Und Saul legte David seinen Waffenrock an, setzte ihm einen ehernen Helm aufs Haupt und legte ihm einen Panzer an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Dann gürtete David sein Schwert über seinen Waffenrock und mühte sich zu gehen; denn er war es nicht gewohnt. Da sprach David zu Saul: \"Ich kann nicht darin gehen; ich bin es nicht gewohnt.\" Und David legte die Rüstung ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Dann nahm er seinen Stock in die Hand, suchte sich fünf glatte Steine aus dem Bach, tat sie in seine Hirtentasche, die er anhatte, und zwar in die Tasche, und nahm seine Schleuder zur Hand. So trat er gegen den Philister vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Der Philister aber kam immer näher auf David zu, vor ihm der Mann, der den Schild trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Da schaute der Philister auf und sah David. Und er nahm ihn nicht ernst, denn er war noch ein Knabe, bräunlich, dazu von schmuckem Aussehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Dann sprach der Philister zu David: \"Bin ich ein Hund, daß du zu mir mit Stecken kommst?\" Dann fluchte der Philister dem David bei seinen Göttern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Und der Philister sprach zu David: \"Komm her zu mir, daß ich dein Fleisch den Vögeln des Himmels gebe und den Tieren des Feldes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Da sprach David zum Philister: \"Du kommst zu mir mit Schwert und Spieß und Wehr. Ich aber komme zu dir im Namen des Herrn der Heerscharen, des Gottes der Kampfscharen Israels, die du verhöhnst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Heute liefert dich der Herr in meine Hand, daß ich dich schlage und dir den Kopf abhaue. Die Leichen des Philisterheeres aber gebe ich heute den Vögeln des Himmels und dem Wild der Erde. Und so erkenne die ganze Welt, daß in Israel ein Gott ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Auch diese ganze Schar erfahre es, daß der Herr hilft, aber nicht durch Schwert und Speer! Denn der Kampf ist des Herrn, und er gibt euch in unsere Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Darauf erhob sich der Philister und ging gegen David zum Nahkampfe vor; da lief David schnell der Philisterschlachtreihe entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Dann fuhr David mit der Hand in die Tasche, nahm daraus einen Stein, schleuderte ihn und traf den Philister an die Stirn. Und der Stein drang in seine Stirn, und er fiel auf sein Antlitz zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'So überwand David mit Schleuder und Stein den Philister und tötete ihn, ohne daß David ein Schwert zur Hand hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'David lief nun hin, trat neben den Philister, nahm sein Schwert, zog es aus der Scheide und tötete ihn. Dann hieb er ihm den Kopf ab. Als die Philister sahen, daß ihr Held tot war, flohen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Jetzt erhoben sich die Männer Israels und Judas, stimmten den Kriegsruf an und verfolgten die Philister bis gegen Gat und vor die Tore Ekrons. Erschlagene der Philister fielen noch auf dem Wege nach Saaraim und bis nach Gat und Ekron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Dann kehrten Israels Söhne von der Verfolgung der Philister zurück und plünderten ihr Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David aber nahm des Philisters Kopf und brachte ihn nach Jerusalem. Und seine Waffen legte er in dem Zelte nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Als Saul den David dem Philister entgegenschreiten sah, fragte er den Heeresobersten Abner: \"Wessen Sohn ist der Jüngling, Abner?\" Da sprach Abner: \"So wahr du lebst, König, ich weiß es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Und der König sprach: \"Frag du selbst, wessen Sohn der junge Mann ist!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Als David von der Besiegung des Philisters zurückkehrte, nahm ihn Abner und führte ihn vor Saul; er aber hatte noch des Philisters Kopf in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Da sprach Saul zu ihm: \"Wessen Sohn bist du, Knabe?\" David sprach: \"Deines Sklaven, des Bethlehemiten Isai, Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kaum hatte er sein Gespräch mit Saul beendigt, da band sich Jonatans Seele an die Davids. Und Jonatan liebte ihn wie sich selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Saul aber nahm ihn an jenem Tag zu sich und ließ ihn nicht mehr in sein Vaterhaus zurückkehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Jonatan schloß nun mit David einen Bund, weil er ihn liebte wie sich selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Dabei zog Jonatan den Mantel aus, den er trug, und gab ihn David, dazu seinen Waffenrock, sein Schwert, seinen Bogen und seinen Gürtel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'David zog nun überall hin, wohin ihn Saul sandte, und hatte dabei Glück. So setzte ihn Saul über die Kriegsleute. Und er ward beliebt beim ganzen Volke und selbst bei Sauls Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Als sie nun bei Davids Rückkehr nach des Philisters Besiegung heimkamen, gingen die Weiber aus allen Städten Israels dem König Saul entgegen, singend und tanzend, mit Pauken, unter Jubel und mit Zimbeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Und die spielenden Weiber hoben an und sprachen: \"Saul hat seine Tausend erschlagen, David aber Zehntausend.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Da wurde Saul sehr zornig. Denn dies Wort mißfiel ihm. Er sprach: \"David geben sie Zehntausend und mir geben sie die Tausend. Nun fehlt ihm nur noch das Königtum.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Und so blickte Saul argwöhnisch auf David von jenem Tag an und weiterhin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Am anderen Morgen kam ein böser Gottesgeist über Saul, und er raste im Innern des Hauses. David spielte nun die Zither wie jeden Tag; Saul aber hielt den Speer in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Da schwang Saul den Speer und dachte: \"Ich will David an die Wand spießen.\" David aber wich zweimal vor ihm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saul fürchtete sich nun vor David. Denn der Herr war mit ihm; von Saul aber war er gewichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Saul aber entfernte ihn von sich und machte ihn zum Obersten von Tausend. So zog er an der Spitze des Volkes aus und ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'David aber hatte Glück auf allen seinen Wegen. Denn der Herr war mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Als Saul sah, daß er großes Glück hatte, graute es ihm vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Ganz Israel und Juda aber liebten David; denn er rückte vor ihnen aus und ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Nun sprach Saul zu David: \"Ich gebe dir meine älteste Tochter Merab zum Weibe. Nur sei mir ein Held und führe des Herrn Kämpfe!\" Saul aber dachte: Ich selbst mag nicht Hand an ihn legen. Dies mögen die Philister tun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David aber sprach zu Saul: \"Wer bin ich und wer ist meine Sippe, meines Vaters Geschlecht in Israel, daß ich des Königs Schwiegersohn würde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Zu jener Zeit aber, da Sauls Tochter Merab dem David gegeben werden sollte, ward sie dem Mecholatiten Adriel zum Weibe gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Sauls Tochter Mikal aber liebte David. Man sagte es Saul, und die Sache war ihm recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Saul dachte nämlich: \"Ich gebe sie ihm, daß sie ihm zum Fallstrick werde und der Philister Hand über ihn komme.\" So sprach Saul zu David: \"Du kannst noch heute schnell mein Schwiegersohn werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Und Saul befahl seinen Dienern: \"Redet mit David im stillen also: \'Der König hat an dir Gefallen, und seine Diener lieben dich! So verschwägere dich mit dem König!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Solches redeten Sauls Diener David vor. Da sprach David. \"Dünkt es euch gering, des Königs Schwiegersohn zu werden? Ich bin doch ein armer und geringer Mann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Da meldeten Sauls Diener ihm: \"So und so hat David gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Da sprach Saul: \"So sollt ihr zu David sagen: \'Der König wünscht keinen anderen Brautpreis als hundert Philisterglieder, um sich an des Königs Feinden zu rächen.\'\" Saul aber rechnete damit, durch der Philister Hand David zu stürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Seine Diener meldeten nun David diese Worte, und David gefiel die Sache, des Königs Schwiegersohn zu werden. Noch war die Zeit nicht vorüber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'da zog David mit seinen Männern aus und schlug unter den Philistern 200 Mann. Und David brachte ihre Glieder und zählte sie dem Könige vor, um des Königs Schwiegersohn zu werden. Da gab ihm Saul seine Tochter Mikal zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Saul aber sah und erkannte, daß der Herr mit David war und daß Sauls Tochter Mikal ihn liebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Da fürchtete sich Saul noch mehr vor David. So ward Saul für alle Zeit der Feind Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Die Philisterfürsten zogen nun aus. Sobald sie aber auszogen, hatte David mehr Glück als alle anderen Diener Sauls, und sein Name ward hochgeehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul sprach nun zu seinem Sohne Jonatan und all seinen Dienern davon, man solle David töten. Sauls Sohn Jonatan aber liebte David innig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'So erzählte Jonatan dem David: \"Mein Vater Saul sucht dich zu töten. Nimm dich daher morgen früh in acht! Geh in ein Versteck und verbirg dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ich gehe dann hinaus und stelle mich neben meinen Vater auf dem Felde, wo du bist, und rede mit meinem Vater über dich. Erfahre ich etwas, dann sage ich es dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Da redete Jonatan über David vor seinem Vater Saul Gutes und sprach zu ihm: \"Der König vergehe sich nicht an seinem Knechte David! Denn er hat sich nicht an dir versündigt, sondern seine Taten sind recht gut für dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Er setzte sein Leben aufs Spiel und schlug den Philister. Der Herr schaffte so für ganz Israel einen großen Sieg. Du hast es gesehen und dann freutest du dich. Warum willst du dich an unschuldigem Blut vergehen und David grundlos töten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Da schenkte Saul dem Jonatan Gehör. Und Saul schwur: \"So wahr der Herr lebt! Er soll nicht getötet werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Da rief Jonatan den David. Und Jonatan erzählte ihm all diese Worte. Dann führte Jonatan David zu Saul, und er blieb bei ihm wie zuvor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Als nun wieder Krieg ausbrach, zog David aus und stritt gegen die Philister. Er schlug sie schwer, und sie flohen vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Über Saul aber kam ein böser Geist des Herrn. Er saß zu Hause, seinen Speer in der Hand. David aber spielte Zither.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Da suchte Saul den David mit dem Speer an die Wand zu spießen. Er aber wich vor Saul aus, und so stieß er den Speer in die Wand. David aber floh und entkam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'In jener Nacht aber schickte Saul Boten in Davids Haus, um auf ihn aufzupassen und ihn am anderen Morgen zu töten. Aber den David warnte sein Weib Mikal; sie sprach: \"Rettest du nicht diese Nacht dein Leben, dann bist du morgen des Todes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Und Mikal ließ David durchs Fenster hinab. Er ging weg, floh und entkam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Mikal aber nahm den Teraphim, tat ihn ins Bett, legte einen Ziegenpelz zu seinen Häupten und bedeckte ihn mit der Decke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Saul schickte nun Boten, David festzunehmen. Da sprach sie: \"Er ist krank.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Da sandte Saul die Boten zurück, nach David zu sehen, und sprach: \"Schleppt mir ihn samt dem Bette her, daß ich ihn töte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Die Boten kamen. Da lag im Bette der Teraphim, zu seinen Häupten der Ziegenpelz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Da sprach Saul zu Mikal: \"Warum hast du mich so betrogen, daß du meinen Feind entrinnen ließest und er heil entkam?\" Da sprach Mikal zu Saul: \"Er sagte zu mir: \'Laß mich, oder ich schlage dich tot.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David aber war geflohen, und so entkam er. Da kam er zu Samuel auf die Höhe und erzählte ihm alles, was Saul ihm getan. Da gingen er und Samuel und wohnten in einem Heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Da ward Saul gemeldet: \"David ist in dem Heim auf der Höhe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Da sandte Saul Boten, David zu holen. Sie sahen den Trupp der Propheten in Verzückung, und Samuel stand dabei als Vorsteher. Da kam über Sauls Boten ein Gottesgeist, und auch sie wurden verzückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Man meldete dies Saul. Da sandte er andere Boten. Aber auch sie wurden verzückt. Saul sandte zum drittenmal Boten. Da wurden auch sie verzückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Da ging er selbst nach der Höhe und kam zum großen Brunnen bei Seku. Da fragte er. \"Wo sind Samuel und David?\" Man sagte: \"Sie sind in dem Heim auf der Höhe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Da ging er von dort zu dem Heim auf der Höhe. Und auch ihn überkam der Gottesgeist. Er ging verzückt, bis er zu dem Heim auf der Höhe kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Da streifte auch er seine Kleider ab und war vor Samuel verzückt. So lag er nackt da, jenen ganzen Tag und die ganze Nacht. Daher pflegt man zu sagen: \"Ist auch Saul unter den Propheten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David aber floh aus dem Heim auf der Höhe. Er kam und sprach vor Jonatan: \"Was habe ich verbrochen? Was ist meine Schuld und meine Sünde gegen deinen Vater, daß er mir nach dem Leben trachtet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Er sprach zu ihm: \"Das sei ferne! Du mußt nicht sterben. Mein Vater tut nichts Wichtiges oder Unwichtiges, ohne es mir vorher zu sagen. Warum sollte mein Vater mir dies vorenthalten? Es ist nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Aber David beteuerte wiederum und sprach: \"Dein Vater weiß gut, daß ich mit dir gut stehe. Er denkt: Das soll Jonatan nicht erfahren, daß er sich nicht gräme. Aber so wahr der Herr lebt und du lebst! Nur ein Schritt ist zwischen mir und dem Tod.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Da sprach Jonatan zu David: \"Was wünscht deine Seele, daß ich es dir tue?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Da sprach David zu Jonatan: \"Morgen ist Neumond. Da sollte ich mit dem König beim Mahle sitzen. Aber entlaß mich, daß ich mich auf dem Feld bis zum dritten Abend verberge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Vermißt mich dein Vater, dann sprich: \'David hat sich von mir Urlaub erbeten, um nach seiner Stadt Bethlehem zu eilen; denn das Jahresopfer ist dort für die ganze Sippe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Spricht er also: \'Gut!\', so ist Friede deinem Sklaven. Gerät er aber in Zorn, so wisse, daß das Unheil von ihm beschlossen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Darin zeige deinem Sklaven Liebe! Du hast ja deinen Sklaven mit dir in einen Herrnbund treten lassen. Ist aber bei mir eine Schuld, dann töte du selbst mich! Aber warum wolltest du mich zu deinem Vater bringen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Da sprach Jonatan: \"Das sei ferne von dir! Würde ich wirklich erfahren, daß von meinem Vater beschlossen ist, Unheil über dich zu bringen, sollte ich es dir nicht melden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Da sprach David zu Jonatan: \"Wer meldet es mir oder was dein Vater dir sonst Schroffes antwortet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Da sprach Jonatan zu David: \"Auf! Laßt uns aufs Feld gehen!\" Da gingen beide aufs Feld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Da sprach Jonatan zu David: \"Beim Herrn, Israels Gott! Ich forsche meinen Vater aus, übermorgen um diese Zeit, ob es gut um David steht. Wo nicht, dann sende ich zu dir und offenbare es dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Der Herr tue Jonatan das und das! Wenn meinem Vater das Unheil gegen dich gefiele, so offenbarte ich es dir doch und ließe dich ziehen, und du zögest im Frieden. Der Herr sei mit dir, wie er mit meinem Vater gewesen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Und solange ich noch am Leben bin, mögest du an mir des Herrn Liebe üben, daß ich nicht sterbe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Aber du wirst niemals meinem Hause deine Liebe entziehen, auch dann nicht, wenn der Herr die Feinde Davids ausrottet, Mann für Mann vom Erdboden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'So schloß Jonatan mit dem Hause Davids einen Bund, hatte doch der Herr ihn von der Schar der Feinde Davids ausgenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Da schwur Jonatan noch einmal David bei seiner Liebe zu ihm. Denn wie sein eigen Leben liebte er ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Dann sprach Jonatan zu ihm: \"Morgen ist Neumond. Da wirst du vermißt; denn man wird die Blicke auf deinen Sitz richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Gehst du nun übermorgen zur Stadt hinab, dann komm am Werktag zu dem Ort, wo du dich verborgen hast, und setze dich neben jenen Stein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Ich schieße dann drei Pfeile nach einer Richtung hin, als schösse ich nach einem Ziele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Dann schicke ich den Knaben: \'Auf! Such die Pfeile!\' Sage ich nun zum Knaben: \'Die Pfeile liegen herwärts von dir\', dann nimm es auf und komm! Denn dann ist Friede mit dir und nichts anderes, so wahr der Herr lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Sage ich aber zum Jüngling: \'Die Pfeile liegen vorwärts von dir\', so geh! Dann schickt dich der Herr fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Für das Wort, das wir, ich und du, gesprochen haben, sei der Herr zwischen mir und dir in Ewigkeit Zeuge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David verbarg sich nun im Felde. Der Neumond kam. Da setzte sich der König zum Mahle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Und der König saß wie immer auf seinem Sitz, auf dem Wandsitz. Jonatan aber saß vornan, und Abner saß an Sauls Seite. Davids Platz aber fiel auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul sagte nichts an jenem Tage, sondern dachte: \"Ein Vorkommnis ist es. Er ist nicht rein, weil er noch nicht gereinigt ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Am zweiten Tage nach dem Neumond fiel Davids Platz wieder auf. Da fragte Saul seinen Sohn Jonatan: \"Warum ist Isais Sohn weder gestern noch heute zum Mahle gekommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Darauf erwiderte Jonatan dem Saul: \"David hat sich von mir Urlaub nach Bethlehem erbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Er sagte: \'Entlaß mich! Denn wir haben in der Stadt ein Familienopfer. Und da hat mein Bruder mich entboten. Und nun, finde ich in deinen Augen Gnade, so möchte ich entschuldigt sein und meine Brüder besuchen.\' Deshalb ist er nicht an des Königs Tafel gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Da ergrimmte Saul über Jonatan und sprach zu ihm: \"Du Sohn versuchten Abfalls! Weiß ich nicht, daß du ein Freund des Isaisohns bist, zu deiner und deiner Mutter Schmach und Schande!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Denn solange der Isaisohn auf Erden lebt, hast weder du noch hat dein Königtum Bestand. Nun schicke hin und hol ihn mir! Er ist ein Kind des Todes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonatan aber antwortete seinem Vater Saul und sprach zu ihm: \"Warum soll er getötet werden? Was hat er verbrochen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Da schwang Saul die Lanze gegen ihn, um ihn zu ermorden. Da erkannte Jonatan, daß es von seinem Vater beschlossen war, David zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Und Jonatan stand in glühendem Zorn von der Tafel auf. Er hatte aber am zweiten Neumondstage nichts gegessen. Denn er war betrübt um David und weil ihn sein Vater beschimpft hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Am Morgen ging Jonatan aufs Feld hinaus, gemäß der Verabredung mit David; ein kleiner Knabe war bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Da sagte er zu seinem Knaben: \"Lauf und such die Pfeile, die ich abschieße!\" Der Knabe lief; er selbst aber schoß die Pfeile über ihn hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Als der Knabe an die Stelle der Pfeile kam, die Jonatan abgeschossen hatte, rief Jonatan dem Knaben nach und sprach: \"Liegen nicht die Pfeile vorwärts von dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Dann rief Jonatan dem Knaben nach: \"Rasch! Spute dich! Halt dich nicht auf!\" Da hob der Knabe die Pfeile und brachte sie seinem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Der Knabe aber wußte von nichts. Nur Jonatan und David wußten darum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Und Jonatan gab seine Waffen dem Knaben, der bei ihm war, und sprach zu ihm: \"Auf! Bring sie in die Stadt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Als aber der Knabe fortgegangen war, erhob sich David im Hintergrund, fiel auf sein Antlitz zur Erde und verneigte sich dreimal. Dann küßten sie einander und weinten lange zusammen, David aber noch länger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Dann sprach Jonatan zu David: \"Geh im Frieden! Wir haben uns ja beide in des Herrn Namen zugeschworen: \'Der Herr ist zwischen mir und dir, meinem und deinem Stamm für alle Zeit.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Da stand er auf und ging. Jonatan aber kehrte in die Stadt zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David kam nun nach Nob zu dem Priester Achimelek. Und Achimelek eilte David entgegen und sprach zu ihm: \"Warum kommst du allein? Weshalb ist niemand bei dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Da sprach David zum Priester Achimelek: \"Der König hat mir einen Auftrag gegeben, sprach er doch zu mir: \'Niemand erfahre etwas von der Sache, deretwegen ich dich sende und die ich dir auftrage.\' Die Diener aber habe ich an den und den Ort beschieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Nun aber! Was hast du zur Hand? Gib mir fünf Brote oder was sonst da ist!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Der Priester antwortete dem David und sprach: \"Es ist kein gewöhnliches Brot zur Hand. Nur geweihtes Brot ist da. Haben sich die Diener der Weiber enthalten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Da antwortete David dem Priester und sprach zu ihm: \"Ja! Weiber sind uns in letzter Zeit versagt gewesen, als ich fortging. So blieben die Geschlechtsteile der Diener rein, obgleich es ein gewöhnliches Unternehmen war. Wieviel mehr ist man heute am Geschlechtsteil rein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Da gab ihm der Priester Geweihtes. Denn dort war kein anderes Brot da als Schaubrote, die man vor dem Herrn weggenommen hatte, um frisches Brot aufzulegen, wenn man jenes wegnahm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Nun war dort an jenem Tage ein Mann von Sauls Dienern vor dem Herrn eingeschlossen, namens Doëg, der Edomiter, und Oberster der Hirten Sauls.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'David sprach nun zu Achimelek: \"Ist bei dir nicht eine Lanze oder ein Schwert zu haben? Denn ich habe weder mein Schwert noch meine sonstigen Waffen mitgenommen, weil des Königs Sache drängte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Da sprach der Priester: \"Das Schwert des Philisters Goliat, den du im Terebinthental erschlugst, ist in ein großes Tuch eingehüllt hinter dem Ephod. Willst du es nehmen, so nimm es! Ein anderes sonst ist nicht hier.\" Da sprach David: \"Keines wie dies! Gib es mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'David brach nun auf und floh an jenem Tage vor Saul. So kam er zum König Akis von Gat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Da sprachen Akis Diener zu ihm: \"Ist das nicht David, des Landes König? Sangen sie nicht ihm zu Ehren im Reigen: \'Saul hat seine Tausend erschlagen, David aber seine Zehntausend?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'David aber nahm sich diese Worte zu Herzen und fürchtete sich recht vor dem König Akis von Gat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Und so entstellte er sein Gebaren vor ihnen und tat bei ihnen wie toll. Er schimpfte auf die Torflügel und ließ seinen Speichel in den Bart fließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Da sprach Akis zu seinen Dienern: \"Ihr seht ja: ein toller Mensch! Weshalb bringt ihr ihn zu mir? Fehlt es mir an Tollen, daß ihr diesen bringt, sich bei mir auszutollen? Soll dieser in mein Haus kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David ging nun von dort weg und rettete sich in die Höhle Adullam. Dies hörten seine Brüder und sein ganzes Vaterhaus und sie zogen zu ihm dorthin hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Um ihn scharten sich auch allerlei Bedrängte und alle, die einen Gläubiger hatten, und alle Unzufriedenen. So ward er ihr Anführer, und bei ihm waren an 400 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Von da ging David nach der Mispa in Moab; da sprach er zu Moabs König: \"Dürften nicht mein Vater und meine Mutter bei euch bleiben, bis ich weiß, was Gott mit mir vorhat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Also ließ er sie beim König von Moab. Und sie wohnten bei ihm, solange David auf der Bergfeste war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Da sprach der Prophet Gat zu David: \"Du darfst nicht auf der Bergfeste bleiben. Auf! Kehr zurück ins Land Juda!\" Da machte sich David auf den Weg und kam in den Wald von Cheret.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Da hörte Saul, daß David und die Leute bei ihm entdeckt seien. Saul aber saß eben auf der Gibea unter der Tamariske auf der Höhe, den Speer in der Hand, und alle seine Diener standen um ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Da sprach Saul zu seinen Dienern, die ihn umstanden: \"Hört doch, ihr Söhne Benjamins! Schenkt irgendeinem von euch der Isaisohn Felder und Weinberge und macht er irgendeinen von euch zum Hauptmann über Tausend und Hundert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'daß ihr euch alle gegen mich verschworen habt und keiner mir angezeigt hat, daß sich mein Sohn mit dem Sohne Isais verbündete, und daß sich keiner von euch meinetwegen härmte und mir anzeigte, daß mein Sohn meinen Sklaven gegen mich zum Lauern aufgehetzt hat, wie es jetzt ist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Da hob der Edomiter Doëg an - er stand nämlich bei Sauls Dienern -: \"Ich habe gesehen, wie der Isaisohn nach Nob zu Achitubs Sohn Achimelek gekommen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Und dieser fragte für ihn den Herrn; auch Zehrung hat er ihm gegeben. Ebenso hat er ihm das Schwert des Philisters Goliat gegeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Da entbot der König den Priester Achimelek, Achitubs Sohn, und sein ganzes Vaterhaus, die Priester zu Nob. Und sie kamen alle zum König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Da sprach Saul: \"Hör einmal, Sohn Achitubs!\" Er sprach: \"Ja, Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Da sprach Saul zu ihm: \"Warum habt ihr euch gegen mich verschworen, du und Isais Sohn? Du gabst ihm Brot und Schwert und befragtest für ihn Gott. So konnte er gegen mich als Lauerer auftreten, wie es jetzt der Fall ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Da erwiderte Achimelek dem König und sprach: \"Aber wer ist unter all deinen Dienern so treu wie David? Dazu des Königs Schwiegersohn und auserwählt für deine Leibwache und geehrt in deinem Hause!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Habe ich erst heute angefangen, für ihn Gott zu befragen? Das sei ferne von mir! Lege der König seinem Sklaven und dessen ganzem väterlichen Hause nichts zur Last! Denn dein Sklave hat von all dem nichts gewußt, weder Unwichtiges noch Wichtiges.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Da sprach der König: \"Du mußt sterben, Achimelek, du und dein ganzes väterliches Haus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Und der König sprach zu den Läufern, die ihn umstanden: \"Tretet her und tötet die Priester des Herrn! Denn auch sie halten es mit David. Sie haben gewußt, daß er auf der Flucht war, und haben mir nichts angezeigt.\" Aber die Diener des Königs weigerten sich, Hand anzulegen und des Herrn Priester niederzustoßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Da sprach der König zu Doëg: \"Tritt du her und stoße die Priester nieder!\" Da trat der Edomiter Doëg hinzu. Und dieser stieß die Priester nieder. Er tötete an jenem Tage 85 Männer, die das linnene Ephod trugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Auch die Priesterstadt Nob schlug er mit des Schwertes Schärfe, Männer und Weiber, Knaben und Säuglinge, ebenso Rinder, Esel und Schafe mit des Schwertes Schärfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Nur ein Sohn des Achitubsohnes Achimelek, namens Ebjatar, entkam. Er floh zu David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Und Ebjatar meldete David. \"Saul hat die Priester des Herrn ermordet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Da sprach David zu Ebjatar: \"Ich habe es damals geahnt, weil der Edomiter Doëg dort war, daß er es Saul verriete. Ich räche jede Seele in deines Vaters Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Bleib bei mir! Hab keine Furcht! Denn der sucht wahrlich mein Leben, der das deine sucht. Denn du bist mir ein Ehrenpfand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Da meldete man David: \"Die Philister berennen Kegila und plündern die Tennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Da fragte David den Herrn: \"Soll ich gehen und diese Philister schlagen?\" Da sprach der Herr zu David: \"Auf! Schlage die Philister und befreie Kegila!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Aber Davids Mannen sprachen zu ihm: \"Wir sind hier in Juda schon voller Furcht. Wie erst, wenn wir nach Kegila gegen die Philisterscharen ziehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Da fragte David den Herrn noch einmal, und der Herr beschied und sprach: \"Auf! Zieh nach Kegila hinab! Denn ich gebe die Philister in deine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Da zog David mit seinen Leuten nach Kegila, griff die Philister an, trieb ihr Vieh weg und schlug sie gewaltig. So half David den Einwohnern Kegilas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Als Ebjatar, Achimeleks Sohn, zu David nach Kegila floh, kam auch das Ephod mit ihm hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Da ward Saul gemeldet: \"David ist nach Kegila gekommen.\" Da sprach Saul: \"Gott liefert ihn mir in die Hand. Jetzt ist er eingeschlossen, da er in eine Stadt mit Tor und Riegel kam.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Und Saul entbot das ganze Volk zum Kampfe nach Kegila hinab, um David und seine Leute zu belagern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'David aber erfuhr, daß Saul gegen ihn Unheil schmiede. Da sprach er zum Priester Ebjatar: \"Bring das Ephod her!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Dann sprach David: \"Herr, Gott Israels! Dein Knecht hört, daß Saul nach Kegila zu kommen strebt und meinetwegen die Stadt vernichten will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Werden mich Kegilas Bürger ihm ausliefern? Kommt Saul herab, wie Dein Knecht gehört hat? Herr, Gott Israels, melde es Deinem Knecht!\" Da sprach der Herr: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Da sprach David: \"Werden Kegilas Bürger mich und meine Leute an Saul ausliefern?\" Da sprach der Herr: \"Ja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Da brachen David und seine Leute auf, etwa 600 Mann, und verließen Kegila. Dann streiften sie da und dort herum. Da ward Saul gemeldet: \"David ist aus Kegila entkommen.\" Daraufhin gab er den Zug auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David aber weilte in der Wüste, auf Bergeshöhen. Dann saß er im Gebirge in der Wüste Ziph. Saul aber suchte ihn zwar die ganze Zeit; aber Gott gab ihn nicht in seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David aber hatte Angst, weil Saul ausgezogen war, ihm nach dem Leben zu trachten. Damals war David in der Wüste Ziph im Gehölz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Da stand Sauls Sohn Jonatan auf und ging zu David ins Gehölz. Er ergriff seine Hand voller Herzlichkeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'und sprach zu ihm: \"Fürchte dich nicht! Denn meines Vaters Saul Hand findet dich nicht. Du wirst König über Israel, und ich werde der Zweite nach dir. Auch mein Vater Saul weiß dies.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Da schlossen beide vor dem Herrn einen Bund. David blieb im Gehölz; Jonatan aber ging heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Da gingen Ziphiter zu Saul nach der Gibea hinauf und sagten: \"Hält sich nicht David bei uns verborgen auf den Berghöhen im Gehölz, auf dem sonnigen Hügel südlich der Einöde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Nun, König, komm herab, sobald es dir beliebt! An uns ist es, ihn in des Königs Hand zu bringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Da sprach Saul: \"Gesegnet seid ihr vor dem Herrn! Denn ihr habt Mitgefühl mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Wohlan! Paßt noch genauer auf und erkundet den Ort, wo sein Fuß weilt! Wer hat ihn dort gesehen? Man hat mir nämlich gesagt, er übe große Vorsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Erkundet also, was an Schlupfwinkeln da ist, wo er sich verstecken kann! Kommt aber zu mir bestimmt zurück! Dann gehe ich mit euch. Ist er noch im Lande, dann suche ich bei allen Sippen Judas.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Da brachen sie auf und gingen Saul voran nach Ziph. David aber und seine Leute waren in der Wüste Maon, in der Steppe südlich der Einöde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'So zog Saul mit seinen Leuten auf die Suche. Dies aber ward David gemeldet. Da zog er hinab zum Felsen und blieb in der Wüste Maon. Dies hörte Saul und verfolgte David in der Wüste Maon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul zog nun auf der einen Seite des Gebirges, David mit seinen Leuten auf der anderen. David aber floh in Hast. Saul aber und seine Leute umkreisten David mit den Seinigen, um sie zu greifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Da kam aber ein Bote zu Saul und sagte: \"Komm rasch! Die Philister sind ins Land eingebrochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Da stand Saul von Davids Verfolgung ab und zog gegen die Philister. Daher nennt man jenen Ort \"Fels des Rückzuges\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'David aber zog von dort hinauf und saß auf Engedis Berghöhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Als Saul von den Philistern zurückkehrte, meldete man ihm: \"David ist in der Wüste von Engedi.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Da nahm Saul 3.000 auserlesene Mannen aus ganz Israel und zog hin, um David und seine Leute vorn auf dem Steinbockfelsen zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'So kam er zu den Schafhürden am Wege. Hier aber war eine Höhle. Da ging Saul hinein, seine Füße zu begießen. David aber und seine Leute kauerten im Rückteile der Höhle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Da sprachen Davids Mannen zu ihm: \"Das ist der Tag, wovon der Herr zu dir gesprochen: \'Ich gebe deinen Feind in deine Hand, daß du mit ihm tust, wie es dir gut dünkt.\'\" Da stand David auf und schnitt heimlich ein Ende von Sauls Mantel ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Nachher aber schlug David das Herz darüber, daß er dem Saul das Ende abgeschnitten habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Und er sprach zu seinen Mannen: \"Fern sei es von mir des Herrn wegen, daß ich so etwas meinem Herrn, dem Gesalbten des Herrn, tue und meine Hand an ihn lege! Denn er ist der Gesalbte des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Und David wies seine Leute mit Worten zurecht und erlaubte ihnen nicht, sich an Saul zu vergreifen. Saul aber verließ die Höhle und zog seines Weges.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Da stand David hernach auf, ging aus der Höhle und rief Saul nach: \"Mein Herr und König!\" Da sah sich Saul um, und David neigte sich mit dem Antlitz zur Erde und huldigte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Dann sprach David zu Saul: \"Warum hörst du auf das Gerede der Leute, die sagen: \'David sinnt auf dein Verderben?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Heute sehen deine Augen, daß dich der Herr mir heute in der Höhle in die Hand gegeben hat. Man hat gesagt, ich solle dich töten. Aber mir tat es leid um dich, und ich sprach: \'Ich strecke meine Hand nicht aus wider meinen Herrn. Denn er ist des Herrn Gesalbter.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Mein Vater! Sieh! Ja, sieh hier das Ende deines Mantels in meiner Hand! Daß ich nur deines Mantels Ende abgeschnitten und dich nicht getötet habe, daran erkenne deutlich, daß ich nicht Bosheit und Verrat im Schilde führe und daß ich mich nicht an dir vergangen habe! Du aber machst Jagd auf mein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Der Herr richte zwischen mir und dir! Der Herr räche mich an dir! Aber meine Hand wird nicht gegen dich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Wie das alte Sprichwort sagt: \'Von Frevlern kommt Frevel\'; aber meine Hand wird nicht wider dich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Hinter wem zieht Israels König her? Wen verfolgst du? Einen toten Hund! Einen winzigen Floh!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'So sei denn der Herr Richter! Er entscheide zwischen mir und dir! Er schaue darein und führe meine Sache! Er schaffe mir Recht vor dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Als David diese Worte an Saul geendet hatte, sprach Saul: \"Ist das deine Stimme, mein Sohn David?\" Und Saul hob laut zu weinen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Er sprach zu David: \"Du bist gerechter als ich. Denn du tust mir Gutes, und ich dir Böses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Du hast heute gezeigt, was du mir Gutes getan, da mich der Herr in deine Hand gegeben und du mich nicht getötet hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Trifft sonst jemand seinen Feind, läßt er ihn heilen Weges ziehen? Der Herr möge dir also Gutes vergelten für das, was du heute mir getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nun weiß ich, daß du König wirst und daß in deiner Hand Israels Königtum Bestand hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'So schwöre mir denn beim Herrn, daß du nicht meine Nachkommen nach mir ausrottest und nicht meinen Namen aus meinem Vaterhaus tilgest!\" Und David schwur es Saul zu. Dann zog Saul heim. David aber und seine Leute waren inzwischen auf die Bergeshöhe gestiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Da starb Samuel. Ganz Israel versammelte sich und trauerte um ihn. Dann begruben sie ihn in seinem Hause auf der Rama. David aber machte sich auf und zog in die anstoßende Wüste hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'In Maon aber war ein Mann; dieser hatte seine Zucht am Karmel. Der Mann aber war sehr reich. Er besaß 3.000 Schafe und 1.000 Ziegen. Eben war er zur Schur seiner Schafe in Karmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Der Mann hieß Nabal, und sein Weib Abigail. Das Weib war feingebildet und schön, der Mann aber roh und bösartig; denn er war selbst wie seine Gesinnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'David hörte nun in der Wüste, daß Nabal seine Schafe schor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Da sandte David zehn Diener ab. Und David sprach zu den Dienern: \"Zieht zum Karmel hinauf, geht zu Nabal, begrüßt ihn in meinem Namen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'und sagt ihm zum Gruße also: \'Dir und deinem Hause sei Heil, ebenso allem, was dir ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Ich habe gehört, daß du Schafschur hältst. Nun sind deine Hirten mit uns zusammen gewesen. Wir haben sie nicht gekränkt, und nichts ist von ihnen vermißt worden, solange sie in Karmel waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Frage deine Diener! Sie bestätigen es dir. So mögen die Knechte Gnade finden in deinen Augen! Wir kommen ja zu einem Festtag. Gib also deinen Knechten und deinem Sohne David, was du vermagst!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Davids Knechte kamen und redeten mit Nabal also in Davids Namen und warteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Da erwiderte Nabal den Knechten Davids und sprach: \"Wer ist David und wer Isais Sohn? Heute gibt es genug Knechte, die ihren Herren davonlaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Soll ich da mein Brot, mein Wasser und mein Schlachtvieh, das ich für meine Scherer schlachte, Leuten geben, von denen ich nicht weiß, woher sie sind?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Da traten Davids Diener den Rückweg an und kehrten um. Sie kamen heim und meldeten ihm jene Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Da sprach David zu seinen Männern: \"Jeder gürte sein Schwert um!\" Da gürtete jeder sein Schwert um. Auch David gürtete sein Schwert um. Dann zogen sie hinter David hinauf, an vierhundert Mann. Zweihundert aber waren beim Gepäck geblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Aber schon hatte der Abigail, dem Weibe Nabals, ein Knecht von jenen Knechten gemeldet: \"David hat aus der Wüste hergesandt, unseren Herrn zu begrüßen. Er aber fuhr sie an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Und doch waren die Männer gegen uns sehr gut. Wir sind nie gekränkt worden und haben nie etwas vermißt, solange wir bei ihnen umhergezogen sind, wenn wir auf dem Felde waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Sie waren eine Mauer um uns bei Nacht so gut wie bei Tag, solange wir bei ihnen die Schafe hüteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Besinne dich nun und sieh, was du tun willst! Denn fertig ist das Unheil über unseren Herrn und sein ganzes Haus. Er selbst ist ein bösartiger Mann, zu dem man nichts sagen darf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Da nahm Abigail eilends zweihundert Brote, zwei Schläuche Wein, fünf zubereitete Schafe und fünf Maß geröstetes Getreide, hundert Dörrtrauben und zweihundert Feigenkuchen und lud alles auf Esel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Dann sagte sie zu ihren Knechten: \"Zieht mir voraus! Ich folge euch sogleich.\" Ihrem Manne Nabal aber hatte sie nichts gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'So ritt sie auf einem Esel abwärts, vom Berge verdeckt. Da kam David mit seinen Leuten herunter und auf sie zu. So traf sie diese.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David aber hatte gesagt: \"Rein umsonst habe ich ihm seine ganze Habe in der Wüste gehütet, daß von all seiner Habe nie etwas vermißt worden ist. Und da vergilt er mir Gutes mit Bösem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Dies und das tue Gott den Feinden Davids, wenn ich von all den Seinen bis zum Morgengrauen auch nur einen Wandpisser übriglasse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Als Abigail David erblickte, stieg sie schnell vom Esel, warf sich bei Davids Anblick auf ihr Antlitz, beugte sich zu Boden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'warf sich ihm zu Füßen und sprach: \"Auf mir, mein Herr, liegt die Schuld. Möchte deine Magd vor dir reden dürfen! Hör die Worte deiner Magd an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Möchte sich doch nicht mein Herr um diesen bösartigen Menschen kümmern, um Nabal! Denn wie er heißt, so ist er. Tor heißt er, und Torheit ist an ihm. Ich aber, deine Magd, habe meines Herrn Leute, die du gesandt hast, nicht gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Nun denn, mein Herr! So wahr der Herr lebt und so wahr du lebst, den der Herr vor Blutschuld zurückhält und vor Selbsthilfe! Nun denn! Deinen Feinden soll es gehen wie Nabal, denen, die für meinen Herrn Unheil suchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Nun denn! Dies Geschenk, das deine Sklavin meinem Herrn bringt, gebe man den Dienern, die meinem Herrn auf seinen Zügen folgen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Vergib deiner Magd die Ungeschicklichkeit! Denn der Herr wird meinem Herrn ein dauerndes Haus schaffen. Weil mein Herr die Kämpfe des Herrn kämpft, so darf sich kein Unrecht in deinem Leben an dir finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Leute standen auf, dich zu verfolgen und dir nach dem Leben zu streben. Aber meines Herrn Leben ist unantastbar in der Schatzkammer des Lebens beim Herrn, deinem Gott. Das Leben deiner Feinde aber legt er in die Schleuderpfanne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Tut dann der Herr an meinem Herrn, wie er Gutes dir verheißen, und bestellt er dich zum Fürsten über Israel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'dann wird dir dies nicht zum Anstoß werden und meinem Herrn nicht zur Gewissensnot, daß du grundlos Blut vergossen und daß mein Herr sich selbst geholfen hätte. Tut aber der Herr meinem Herrn Gutes, dann gedenke auch deiner Magd!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Da sprach David zu Abigail: \"Gepriesen sei der Herr, Gott Israels, der dich mir heute entgegenschickt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Gepriesen sei deine Klugheit und gepriesen seist du selbst, die mich heute zurückgehalten, in Blutschuld zu kommen und mir selbst zu helfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Aber so wahr der Herr, Israels Gott, lebt, der mich abgehalten, dir ein Leid zu tun! Wärest du mir nicht schnell entgegengekommen, dann bliebe dem Nabal bis zum Morgengrauen auch nicht ein Wandpisser übrig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David nahm nun aus ihrer Hand, was sie ihm gebracht hatte. Dann sprach er zu ihr: \"Zieh im Frieden heim! Ich schenke dir Gehör und nehme auf dich Rücksicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Abigail kam nun zu Nabal. Er hatte eben zu Hause ein Mahl wie ein Königsmahl. Und Nabals Herz war guter Dinge, und so ward er schwer betrunken. Da sagte sie ihm nicht das geringste bis zum Morgengrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Am Morgen aber, als der Wein aus Nabal wich, erzählte ihm sein Weib diese Begebnisse. Da stockte sein Herz in seiner Brust und ward wie Stein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Zehn Tage währte es. Da schlug der Herr den Nabal, und er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Als David hörte, daß Nabal tot sei, rief er aus: \"Gepriesen sei der Herr, der meine Beschimpfung an Nabal gestraft und seinen Knecht vom Unrecht zurückgehalten hat! Der Herr hat Nabals Unrecht auf ihn selbst zurückfallen lassen.\" Darauf sandte David hin und warb um Abigail, daß sie sein Weib würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'So kamen Davids Diener zu Abigail nach Karmel und warben um sie mit den Worten: \"David sendet uns zu dir; er will dich zum Weibe nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Da stand sie auf, beugte sich mit dem Antlitz zur Erde und sprach: \"Deine Magd will deine Sklavin sein und den Dienern meines Herrn die Füße waschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Dann stand Abigail schnell auf und bestieg den Esel; ihre fünf Dienerinnen aber folgten ihr. So ging sie hinter den Boten Davids her und ward sein Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Aus Jezreel aber holte David die Achinoam. So wurden beide zumal seine Frauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul aber hatte seine Tochter Mikal, Davids Weib, dem Palti gegeben, dem Sohne des Lais aus Gallim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Da kamen die Ziphiter zu Saul nach der Gibea und sagten: \"Hält sich David nicht auf dem sonnigen Hügel am Eingang zur Einöde versteckt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'So machte sich Saul auf, ging nach der Wüste Ziph hinab mit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, '000 Mann, auserlesenen Israeliten, um David in der Wüste Ziph zu suchen. 3 Saul nun lagerte sich auf dem sonnigen Hügel am Eingang zur Einöde. David aber saß in der Wüste. Da überkam ihn eine Ahnung, daß Saul ihm in die Wüste nachzöge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Und so sandte David Kundschafter aus und da erfuhr er bestimmt, daß Saul gekommen sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Da machte sich David auf und kam an den Ort, wo Saul lagerte. Und David sah den Platz, wo sich Saul mit seinem Feldhauptmann Abner, Ners Sohn, niedergelegt hatte. Saul schlief nämlich in einem Wallkreis, und das Volk lagerte rings um ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Da hob David an und sprach zu dem Chittiter Achimelek und zu Abisai, Serujas Sohn und Joabs Bruder: \"Wer steigt mit mir zu Saul in das Lager hinab?\" Da sprach Abisai: \"Ich gehe mit dir hinab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'So kam David mit Abisai zu dem Kriegsvolk in der Nacht. Saul aber lag schlafend in dem Wallkreis und sein Speer stak im Boden zu seinen Häupten. Und Abner lag mit dem Volke rings um ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Da sprach Abisai zu David: \"Gott gibt dir heute deinen Feind in deine Hand. Nun spieße ich ihn mit seiner Lanze durch einen Stoß an den Boden; ich brauche keinen zweiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Da sprach David zu Abisai: \"Bring ihn nicht um! Wer hätte je den Gesalbten des Herrn angetastet und wäre straflos geblieben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Dann sprach David: \"So wahr der Herr lebt! Entweder schlägt ihn der Herr, oder sein Tag kommt, da er sterben muß, oder er zieht in den Kampf und wird weggerafft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Bewahre mich der Herr davor, daß ich meine Hand an den Gesalbten des Herrn lege! Nimm jetzt den Speer zu seinen Häupten und den Wasserkrug! Laßt uns dann gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'So ließ David die Lanze und den Wasserkrug von Sauls Häupten nehmen. Dann gingen sie ihres Wegs. Niemand sah es und niemand merkte es und niemand erwachte. Sie schliefen alle; denn ein Tiefschlaf des Herrn war auf sie gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Dann ging David auf die andere Seite und stellte sich auf die Spitze des Berges von ferne. Der Raum aber zwischen ihnen war groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Da rief David dem Volke und Abner, Ners Sohn, also zu: \"Gibst du nicht Antwort, Abner?\" Da erwiderte Abner und fragte. \"Wer bist du? Rufst du des Königs wegen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Da sprach David zu Abner: \"Bist du nicht ein Mann? Wer gleicht dir in Israel? Warum aber behütest du nicht den König, deinen Herrn? Jemand vom Volke ist ja gekommen, den König, deinen Herrn, umzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nicht recht ist, was du getan. So wahr der Herr lebt! Den Tod verdient ihr, die ihr euren Herrn, des Herrn Gesalbten, nicht behütet habt. Schau doch nach des Königs Speer und Wasserkrug zu seinen Häupten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Da erkannte Saul die Stimme Davids und sprach: \"Ist dies deine Stimme, mein Sohn David?\" Da sprach David: \"Ja, mein Herr und König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Dann sprach er: \"Warum verfolgt der Herr seinen Sklaven? Was tue ich: Was ist bei mir Böses?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Möchte doch jetzt mein Herr und König den Worten seines Sklaven Gehör schenken! Hat dich der Herr gegen mich aufgereizt, dann erfreue er sich des Opfers! Wenn aber Menschenkinder, dann seien sie vor dem Herrn verflucht, weil sie mich heute vertreiben, daß ich nicht einmal als Geringster in des Herrn Erbteil leben kann! Sie sprechen: \'Auf! Diene anderen Göttern!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Nun denn! Möge mein Blut nicht in des Herrn Augen unbedeutend sein! Denn Israels König macht Jagd auf einen winzigen Floh, wie man im Gebirge das Rebhuhn jagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Da sprach Saul: \"Ich habe gefehlt. Kehre zurück, mein Sohn David! Ich tue dir nie wieder ein Leid an, dafür, daß dir mein Leben heute so kostbar gewesen ist. Gewiß! Ich habe töricht gehandelt, daß ich mich so stark verging.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Da antwortete David und sprach: \"Hier ist des Königs Speer. Einer deiner Diener möge herüberkommen und ihn holen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Der Herr aber vergilt jedem seine Redlichkeit und Treue. So hat dich der Herr heute in meine Hand gegeben. Ich aber habe nicht des Herrn Gesalbten anfassen wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'So wertvoll heute mir dein Leben gewesen, so kostbar möge auch mein Leben dem Herrn sein! Er möge mich aus aller Not erretten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Da sprach Saul zu David: \"Sei gesegnet, mein Sohn David! Du führst es aus und führst es zu Ende.\" Hierauf ging David seines Weges, und Saul kehrte an seinen Ort zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Da sprach David bei sich: \"Ich werde doch eines Tags durch Sauls Hand umkommen. Für mich ist nichts besser, als nach dem Philisterland zu fliehen. Dann läßt Saul ab, mich ferner im ganzen Gebiete Israels zu suchen. Dadurch bin ich seiner Hand entrückt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Da machte sich David auf und ging mit den 600 Mann bei ihm zu Akis über, dem König von Gat und Maoks Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'David blieb nun bei Akis in Gat, er und seine Leute, jeder mit seiner Familie. David mit seinen zwei Frauen, der Jezreelitin Achinoam und der Karmelitin Abigail, Nabals Witwe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Da ward Saul gemeldet, David sei nach Gat geflohen. Und so verfolgte er ihn nicht weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'David sprach nun zu Akis: \"Finde ich Gnade in deinen Augen, dann möge man mir zur Siedlung einen Platz in einer der Landstädte anweisen! Wozu soll dein Knecht in der Königstadt bei dir wohnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Da wies ihm Akis an jenem Tage Siklag an. Daher gehört Siklag den Königen von Juda bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Die Zeit aber, die David im Philistergefilde saß, betrug ein Jahr und vier Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Da zog David mit seinen Leuten hinauf, und sie überfielen die Gesuriter, Pereziter und Amalekiter. Denn das waren Siedlungen im Landstrich von Telam bis gegen Sur und Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Sooft David eine Gegend überfiel, ließ er niemand leben, weder Männer noch Weiber. Er nahm auch Schafe, Rinder, Esel, Kamele und Gewänder; dann brachte er sie zu Akis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Fragte Akis: \"Wo seid ihr heute eingebrochen?\", dann sagte David: \"Im Südlande Judas oder im Südlande der Jerachmeeliter oder in dem der Keniter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Aber weder Mann noch Weib ließ David leben, um sie nach Gat zu bringen; er dachte: \"Sie sollen uns nicht verraten!\" So tat David. Und so war sein Verfahren die ganze Zeit, seit er im Gefilde der Philister saß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Akis aber traute David; er sprach: \"Er bringt sich bei seinem Volke Israel in Verruf und bleibt so für immer mein Diener.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'In jener Zeit sammelten die Philister ihr Heer zu einem Feldzug, um mit Israel zu streiten. Da sprach Akis zu David: \"Du weißt, daß du mit mir im Heere ausrücken mußt, du und deine Leute.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Da sprach David zu Akis: \"Gut! Du wirst sehen, was dein Knecht leistet.\" Da sprach Akis zu David: \"Gut! Ich ernenne dich zu meinem Leibwächter für alle Zeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel aber war gestorben; da betrauerte ihn ganz Israel und bestattete ihn auf der Rama in seiner Stadt. Saul aber hatte die Totenbeschwörer und Wahrsager aus dem Lande gejagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Nun sammelten sich die Philister, kamen und lagerten bei Sunem. Da bot Saul ganz Israel auf, und sie lagerten auf dem Gilboa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Als aber Saul das Philisterlager erblickte, geriet er in Angst, und sein Herz bebte gewaltig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Da befragte Saul den Herrn. Aber der Herr gab ihm keine Antwort, weder durch Träume noch durch die Urim noch durch die Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Da sprach Saul zu seinen Dienern: \"Sucht mir ein Weib, das einen Totengeist hat! Ich will zu ihr gehen und sie befragen.\" Da sprachen seine Diener zu ihm: \"Ein Weib, das einen Totengeist hat, ist zu En Dor.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Da vermummte sich Saul, zog andere Kleider an und ging hin, zwei Männer bei sich. So kamen sie des Nachts zu dem Weibe. Er sprach: \"Wahrsage mir mit dem Totengeist und laß mir einen erscheinen, den ich dir nennen werde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Da sprach das Weib zu ihm: \"Du weißt selbst, was Saul getan, daß er die Totenbeschwörer und Wahrsager im Lande ausgerottet hat. Warum legst du meinem Leben eine Schlinge, mich zu töten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Da schwur ihr Saul beim Herrn: \"So wahr der Herr lebt! Dich trifft kein Schaden in dieser Sache.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Da sprach das Weib: \"Wen soll ich dir erscheinen lassen?\" Er sprach: \"Laß mir Samuel erscheinen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Da sah das Weib Samuel. Und sie schrie laut auf. Dann sprach das Weib zu Saul: \"Warum betrügst du mich? Du selbst bist Saul.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Da sprach zu ihr der König: \"Sei ohne Furcht! Was siehst du?\" Da sprach das Weib zu Saul: \"Ich sehe etwas Überirdisches aus dem Boden steigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Da fragte er: \"Wie sieht es aus?\" Sie sprach: \"Ein alter Mann steigt herauf, in eine Kutte gehüllt.\" Da erkannte Saul, daß es Samuel war. Er neigte sich mit dem Antlitz zu Boden und verbeugte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Da sprach Samuel zu Saul: \"Warum störst du mich, daß du mich erscheinen lässest?\" Da sprach Saul: \"Mir ist sehr bange. Die Philister kämpfen gegen mich. Nun ist Gott von mir gewichen und antwortet mir nicht mehr, weder durch die Propheten noch durch Träume. So ließ ich dich rufen, daß du mir kündest, was ich tun soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Da sprach Samuel: \"Was fragst du mich, wenn der Herr von dir gewichen und dein Feind geworden ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Der Herr tut dir, wie er durch mich verkündet hat: Der Herr reißt dir das Königtum aus der Hand und gibt es deinem Nebenbuhler David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Weil du auf des Herrn Stimme nicht gehört und seinen grimmen Zorn an Amalek nicht vollstreckt hast, deshalb tut dir der Herr dies heute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Der Herr gibt auch Israel samt dir in der Philister Hand. Morgen bist du mit deinen Söhnen bei mir. Auch Israels Heer gibt der Herr in die Hand der Philister.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Alsbald fiel Saul seiner ganzen Länge nach zu Boden, so heftig erschrak er über Samuels Worte. Auch hatte er keine Kraft mehr; denn er hatte den ganzen Tag und die ganze Nacht nichts gegessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Da trat das Weib zu Saul hin und sah, daß er ganz entsetzt war. Da sprach sie zu ihm: \"Deine Sklavin hat deiner Stimme gehorcht. Ich wagte mein Leben und hörte auf deine Worte, die du zu mir gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Nun höre auch du auf deiner Sklavin Stimme! Ich will dir einen Bissen Brot vorsetzen. Diesen iß, daß Kraft in dir sei, deines Weges zu ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Er aber weigerte sich und sprach: \"Ich esse nichts.\" Da drangen seine Diener in ihn, ebenso das Weib, und so hörte er auf ihre Stimme. Er stand vom Boden auf und setzte sich auf das Polster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Nun hatte das Weib ein Mastkalb im Hause. Sie schlachtete es rasch, nahm Mehl, knetete es und buk daraus Brotkuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Dann setzte sie es Saul und seinen Dienern vor, und sie aßen. Hernach standen sie auf und gingen in der gleichen Nacht noch fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Die Philister nun sammelten ihren ganzen Heerbann nach Aphek. Israel aber lagerte an der Quelle bei Jezreel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Als nun die Philisterführer vorüberzogen, mit Schützen und anderen Scharen, und auch David mit seinen Leuten zuletzt an Akis vorüberzog,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'sprachen die Philisterfürsten: \"Was sollen da die Hebräer?\" Da sprach Akis zu den Philisterfürsten: \"Ist das nicht David, der Diener Sauls, des Königs von Israel? Er ist seit Jahr und Tag bei mir, und ich habe an ihm nicht das geringste seit seinem Übertritt bis heute gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Aber die Philisterfürsten waren ihm abgeneigt. Und so sprachen die Philisterfürsten zu ihm: \"Schick diesen Mann zurück! Er soll an seinen Ort zurückkehren, den du ihm angewiesen! Er soll nicht mit uns in die Schlacht ziehen, daß er nicht an uns zum Verräter im Kampfe werde! Womit könnte er seines Herrn Gunst gewinnen? Nicht mit den Köpfen dieser Leute?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ist das nicht David, dem zu Ehren man im Reigen sang: \'Saul schlug seine Tausend. David aber seine Zehntausend?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Da rief Akis den David und sprach zu ihm: \"So wahr der Herr lebt! Du bist ehrlich, und mir wäre es erwünscht, wenn du im Heerbann mit mir aus- und einzögest; denn ich habe an dir nichts Unrechtes gefunden, seitdem du zu mir kamst, bis auf diesen Tag. Aber den Fürsten gefällst du nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'So kehr um und geh in Frieden! Tu nichts, was den Philisterfürsten mißfällt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Da sprach David zu Akis: \"Was habe ich getan? Was hast du an deinem Knecht gefunden, seitdem ich in deinen Dienst getreten bin, bis heute, daß ich nicht in den Kampf gegen die Feinde meines Herrn, des Königs, ziehen darf?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Da antwortete Akis dem David: \"Ich fühle es, daß du mir so lieb bist wie ein Gottesbote. Nur die Philisterfürsten sagen: \'Er darf nicht mit uns in den Kampf ziehen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'So mach dich morgen früh auf, samt deines Herrn Knechten, die mit dir gekommen sind! Macht euch also morgen früh auf und zieht ab, sobald es Tag wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Da machte sich David mit seinen Leuten auf, am Morgen abzuziehen und ins Philisterland zurückzukehren. Die Philister aber zogen nach Jezreel hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'David nun kam mit seinen Leuten nach Siklag am dritten Tag. Da waren schon die Amalekiter in das Südland und in Siklag eingefallen. Sie verheerten Siklag und brannten es nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Sie nahmen auch die Weiber darin, jung und alt, gefangen. Getötet aber hatten sie niemand. So führten sie sie weg und zogen ihres Weges.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'David aber kam mit seinen Leuten zur Stadt. Da war sie niedergebrannt, und ihre Weiber, Söhne und Töchter waren verschleppt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Da weinten David und die Leute bei ihm laut auf, bis sie keine Kraft mehr zum Weinen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Auch Davids beide Weiber waren verschleppt worden, die Jezreelitin Achinoam und die Karmelitin Abigail, Nabals Witwe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'David ward nun sehr bange; denn das Kriegsvolk hatte davon gesprochen, ihn zu steinigen. So erbittert war das ganze Volk wegen seiner Söhne und Töchter. Aber David ermannte sich im Herrn, seinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Und David sprach zu dem Priester Ebjatar, Achimeleks Sohn: \"Bringe mir doch das Ephod!\" Da brachte Ebjatar das Ephod zu David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Dann fragte David den Herrn: \"Soll ich diese Horde verfolgen? Hole ich sie ein\"? Da sprach er zu ihm: \"Ja! Du holst sie ein und befreist jene.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Da zog David mit den sechshundert Mann, die bei ihm waren, fort, und sie kamen in das Tal des Besor. Da blieben die Nachzügler stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'So setzte David mit vierhundert Mann nach. Zweihundert Mann aber blieben zurück, die zu müde waren, das Tal des Besor zu überschreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Da fanden sie einen Ägypter auf dem Felde und brachten ihn zu David. Sie gaben ihm Brot zu essen, und er aß. Dann gaben sie ihm Wasser zu trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Hierauf gaben sie ihm ein Stück Feigenkuchen und ein paar Dörrtrauben. Und er aß. Da kam er wieder zu sich. Denn er hatte drei Tage und drei Nächte weder Brot gegessen noch Wasser getrunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Da sprach David zu ihm: \"Wem gehörst du? Woher bist du?\" Er sagte: \"Ich bin ein ägyptischer Jungmann, Sklave eines Amalekitermannes. Mich gab mein Herr auf; denn ich bin vor drei Tagen krank geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Wir sind in das Südland der Karobenbäume eingefallen, in das Gebiet von Juda und in das kalebitische Südland und haben Siklag verbrannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Da sprach David zu ihm: \"Willst du mich zu dieser Horde führen?\" Er sagte: \"Schwöre mit bei Gott, daß du mich nicht tötest und mich nicht meinem Herrn auslieferst! Dann führe ich dich zu dieser Horde hinab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Und er führte ihn hinab. Sie aber waren über die ganze Gegend verstreut. Sie aßen, tranken und feierten ob all der reichen Beute, die sie aus dem Philisterland und aus dem Judaland gebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Da schlug sie David vom Nachmittag bis zum Abend, sie verwundend. Keiner entkam außer vierhundert Packknechten, die sich auf die Kamele schwangen und entkamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'So befreite David alles, was die Amalekiter geraubt hatten. Auch seine beiden Weiber befreite David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nichts vom Kleinsten bis zum Größten ward von ihm vermißt, weder Söhne noch Töchter, weder die Beute noch irgend etwas, was sie ihnen geraubt hatten. Alles brachte David zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'David nahm auch alle Schafe und Rinder. Und sie führten dies Vieh vorauf und sagten: \"Dies ist Davids Beute.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'David kam nun zu den zweihundert Mann, die zu müde gewesen waren, um David zu folgen, und die er im Tale des Besor zurückgelassen hatte. Sie gingen David und den Leuten bei ihm entgegen. Da trat David an die Leute heran und begrüßte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Aber allerlei böse und mißgünstige Männer unter den Leuten, die mit David gezogen waren, hoben an und sprachen: \"Weil sie nicht mit uns ausgezogen sind, so geben wir ihnen nichts von der Beute, die wir zurückgewonnen haben, sondern nur jedem sein Weib und seine Kinder. Diese mögen sie nehmen und gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Da sprach David: \"Meine Brüder! So dürft ihr nicht tun für das, was der Herr uns gegeben! Er beschützte uns und gab uns die Horde, die uns überfallen, in die Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Wer möchte auf euch hierin hören? Wie der Anteil derer, die in den Kampf gezogen, sei auch der Anteil jener, die beim Gepäck geblieben! Gleich sollen sie teilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'So blieb es von jenem Tage an. Man machte dies nämlich zur Satzung und zum Brauch in Israel bis auf den heutigen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'David kam nun nach Siklag. Da sandte er einen Teil der Beute an Judas Älteste, seine Freunde, mit den Worten: \"Hier ist ein Geschenk für euch aus der Beute der Feinde des Herrn\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'an die in Betel, in Ramot im Südland, in Jattir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Aroër, Siphmot, Estemoa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Karmel, an die in den Gemeinden der Jerachmeliter, an die in den Gemeinden der Keniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'an die in Chorma, Bor, Asan, Atak,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'an die in Hebron und an all die Orte, wo David mit seinen Leuten umhergestreift war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Die Philister aber stritten unterdes mit Israel. Da flohen die Mannen Israels vor den Philistern. Und auf dem Gebirge des Gilboa lagen Erschlagene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Die Philister aber holten Saul und seine Söhne ein. Dabei schlugen die Philister die Söhne Sauls, Jonatan, Abinadab und Malkisua.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'So ward der Kampf für Saul immer schwerer. Da trafen ihn die Bogenschützen von ungefähr. Und er ward durch die Bogenschützen schwer verwundet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Da sprach Saul zu seinem Waffenträger: \"Zücke dein Schwert und erstich mich, daß nicht diese Unbeschnittenen kommen, mich erstechen und mit mir ihr Spiel treiben!\" Aber sein Waffenträger wollte nicht; denn er scheute sich zu sehr. Da nahm Saul das Schwert und stürzte sich darein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Als aber sein Waffenträger sah, daß Saul tot war, stürzte auch er sich in sein Schwert und starb neben ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'So starben Saul und seine drei Söhne und sein Waffenträger, samt allen seinen Mannen zugleich an jenem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Als die Israeliten diesseits des Tales und des Jordan sahen, daß Israels Mannen geflohen und daß Saul und seine Söhne tot waren, verließen sie die Städte und flohen. Da kamen die Philister und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Am anderen Morgen kamen die Philister, um die Erschlagenen zu plündern. Da fanden sie Saul und seine drei Söhne auf dem Gebirge des Gilboa liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Sie schnitten ihm das Haupt ab, zogen ihm die Rüstung aus und sandten im Philisterlande umher, in ihren Götzentempeln und bei dem Volke den Sieg zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Seine aber Waffen legten sie im Hause der Astarten nieder; seinen Leichnam aber hatten sie an die Mauer von Betsan genagelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Die Bewohner von Jabes in Gilead aber hörten gleich darauf, was die Philister an Saul getan hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Da machten sich alle wehrhaften Mannen auf. Sie zogen die ganze Nacht hindurch und nahmen Sauls Leichnam und die Leichname seiner Söhne von der Mauer zu Betsan. So kamen sie wieder nach Jabes und verbrannten sie dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Dann nahmen sie ihre Gebeine, begruben sie unter der Tamariske zu Jabes und fasteten sieben Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Und erst nach Sauls Tod war David vom Sieg über die Amalekiter heimgekehrt; er weilte nun zwei Tage in Siklag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Da kam am dritten Tag ein Mann aus dem Lager, von Saul her, seine Kleider zerrissen und Staub auf dem Kopfe. Als er zu David kam, neigte er sich bis zur Erde und verbeugte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Da sprach David zu ihm: \"Woher kommst du?\" Er sprach: \"Ich bin aus Israels Lager entronnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Da sprach David zu ihm: \"Wie ging es? Berichte mir!\" Er sprach: \"Das Kriegsvolk ist aus der Schlacht geflohen, und viele aus dem Volke sind gefallen, so daß sie starben und tot sind. Auch Saul und sein Sohn Jonatan sind tot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Da sprach David zu dem jungen Manne, der ihm die Botschaft brachte: \"Wie weißt du, daß Saul und sein Sohn Jonatan tot sind?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Da sprach der junge Mann, der ihm die Botschaft brachte: \"Ich bin zufällig auf das Gebirge des Gilboa gekommen. Da hatte sich Saul auf seinen Speer gelehnt. Die Wagen aber und die Reiterei waren schon dicht hinter ihm her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Da wandte er sich um und sah mich. Er rief mich an, und ich sprach: \'Da bin ich!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Dann sprach er zu mir: \'Wer bist du?\' Ich sprach zu ihm: \'Ich bin ein Amalekiter.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Da sprach er zu mir: \'Tritt herzu und gib mir den Todesstoß! Mich befällt Ohnmacht; denn ich lebe noch.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Da trat ich zu ihm und gab ihm den Todesstoß. Denn ich wußte, daß er seinen Sturz nicht überleben würde. Ich nahm das Diadem auf seinem Haupte und die Spange an seinem Arm und bringe sie hier meinem Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Da packte David seine Gewänder und zerriß sie, ebenso alle Männer bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Und sie trauerten, weinten und fasteten bis zum Abend um Saul und seinen Sohn Jonatan und um das Volk des Herrn und um das Haus Israel, daß sie durch das Schwert gefallen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Dann sprach David zu dem jungen Mann, der ihm die Meldung brachte: \"Woher bist du?\" Er sprach: \"Ich bin der Sohn eines zugewanderten Amalekiters.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Da sprach David zu ihm: \"Wie? Du hast dich nicht gescheut, Hand anzulegen, um den Gesalbten des Herrn umzubringen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Dann rief David einen seiner Knechte und sprach: \"Her! Stoß ihn nieder!\" Da schlug er ihn nieder, so daß er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Und David sprach zu ihm: \"Dein Blut über dein Haupt! Dein eigener Mund klagt dich an; du sagtest: \'ich habe den Gesalbten des Herrn getötet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Dann dichtete David dieses Klagelied auf Saul und seinen Sohn Jonatan:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Er sprach: \"Man lehre es die Söhne Judas auf der Zither!\" Aufgezeichnet ist es im \"Buche des Richtigen\":');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '\"Der Adel liegt, o Israel, erschlagen dort auf deinen Höhen. Wie sind gestürzt die Helden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Verkündet\'s nicht zu Gat! Bringt nicht die Botschaft in die Gassen Askalons, daß der Philister Töchter sich nicht freuen, nicht jubeln dieser Unbeschnittenen Töchter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ihr Berge Gilboas! Nicht Tau, nicht Regen falle mehr auf euch und nicht auf die Gefilde Dotains! Dort ward des Helden Schild zuschanden, der Schild des zwiefach ölgesalbten Saul!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Vor der unreinen Sippe, vor Kriegsvolk ist nie der Bogen Jonatans zurückgewichen. Nie kehrte leer zurück das Schwert des Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul und Jonatan, die Lieben und die Holden, im Leben und im Tode sind sie nicht getrennt, einst schneller als die Adler und stärker als die Löwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Ihr Töchter Israels! Weint über Saul, der euch in Purpur lieblich kleidete, Der Goldschmuck eurer Kleidung gab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Wie sind die Helden hingestürzt im Kampfgedränge! Auf deinen Höhen wurde Jonatan erschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Mein Bruder Jonatan! So leid ist mir um dich. Du warst mir gar so hold. Noch wundersamer war mir');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Wie sind die Helden hingestürzt! Des Krieges Waffen schwanden hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Als David hernach den Herrn befragte: \"Darf ich in eine der Städte Judas ziehen?\" sprach der Herr zu ihm: \"Ja!\" Da fragte David: \"Wohin soll ich ziehen?\" Er sprach: \"Nach Hebron.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'David zog nun dorthin, ebenso seine beiden Frauen, die Jezreelitin Achinoam und die Karmelitin Abigail, Nabals Witwe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Auch seine Mannen, die bei ihm waren, brachte David hin, jeden mit seiner Familie. Und so saßen sie in Hebrons Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Da kamen die Männer Judas und salbten dort David zum König über das Haus Juda. Da meldete man David: \"Die Männer von Jabes in Gilead haben Saul begraben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Da sandte David Boten zu den Männern von Jabes in Gilead und ließ ihnen sagen: \"Seid vom Herrn gesegnet, die ihr diese Liebe eurem Herrn Saul erwiesen und ihn begraben habt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Nun möge auch der Herr euch Liebe und Treue erweisen, und auch ich will euch Gutes tun, wie ihr getan habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Nun seid mutig! Und seid tapfere Leute! Weil euer Herr Saul starb, so salbten mich die vom Hause Juda zum König über sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner, Ners Sohn und Sauls Feldherr, hatte nun Sauls Sohn Isboset mitgenommen; dann brachte er ihn nach Machanaim hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Und er machte ihn zum König über Gilead und über Basan sowie über Jezreel, Ephraim, Benjamin und das sonstige Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Vierzig Jahre alt war Sauls Sohn Isboset, als er König über Israel ward, und zwei Jahre hat er regiert. Nur das Haus Juda hielt zu David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Die Zeit, die David in Hebron König über das Haus Juda war, betrug sieben Jahre und sechs Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Von Machanaim nun zog Abner, Ners Sohn, mit den Knechten des Saulsohnes Isboset nach Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Auch Serujas Sohn Joab zog mit den Knechten Davids aus. Sie trafen sich nun an dem Teiche von Gibeon. Die einen saßen diesseits, die anderen jenseits des Teiches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Da sprach Abner zu Joab: \"Mögen doch die Knechte aufstehen und im Kampfspiel vor uns streiten!\" Joab sprach: \"Ja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Da machten sie sich auf und rückten abgezählt aus zwölf von Benjamin und von den Mannen des Saulsohnes Isboset und zwölf von Davids Knechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Da packten sie einander am Kopf und stießen einander das Schwert in die Seite. So fielen sie allzumal. Man hieß jenen Ort: \"Feld der Felsmuscheln\". Er liegt bei Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Da ward der Kampf an jenem Tage immer ernster. Abner und die Leute Israels aber wurden von Davids Knechten geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Nun waren dort die drei Serujasöhne, Joab, Abisai und Asahel. Asahel war leichtfüßiger als eine der Gazellen auf der Flur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Und Asahel verfolgte den Abner. Er bog weder nach rechts noch nach links ab hinter Abner her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Da wandte sich Abner und sprach: \"Bist du es, Asahel?\" Er sprach: \"Jawohl, ich bin es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Da sprach Abner zu ihm: \"Bieg nach rechts oder nach links ab! Greif dir einen der Knechte und nimm dir seine Rüstung!\" Aber Asahel wollte nicht von ihm lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Da sprach Abner nochmals zu Asahel: \"Geh hinter mir weg! Wozu soll ich dich zu Boden schlagen? Wie könnte ich dann deinem Bruder Joab unter die Augen kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Er aber weigerte sich, abzulassen. Da stieß ihm Abner die Lanzenspitze in den Leib, daß der Speer rückwärts herauskam. Er fiel dort hin und starb auf der Stelle. Wer an die Stelle gelangte, wo Asahel gefallen und gestorben war, machte Halt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joab und Abisai verfolgten noch Abner. Als die Sonne unterging, waren sie bis zum Eckhügel bei der Quelle gekommen, an der Straße zur Wüste von Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Da sammelten sich die Benjaminiten hinter Abner. Sie bildeten eine Schar und stellten sich auf den Gipfel eines Hügels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Da rief Abner dem Joab zu und sprach: \"Soll denn ewig das Schwert fressen? Weißt du nicht, daß schließlich Bitteres kommt? Wie lange willst du dem Volke nicht sagen, es soll von seinen Brüdern lassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Da sprach Joab: \"Beim Leben Gottes! Hättest du nur geredet, dann hätte das Volk schon am Morgen von seinen Brüdern abgelassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Dann stieß Joab in das Horn. Und alles machte halt, und sie verfolgten Israel nicht mehr und kämpften nicht weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner und seine Leute aber waren jene ganze Nacht hindurch nach der Steppe gezogen. Dann setzten sie über den Jordan, durchzogen die ganze Schlucht und kamen nach Machanaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab aber hatte von Abner abgelassen; er sammelte nun das ganze Volk. Da fehlten von Davids Knechten neunzehn Mann und Asahel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Die Knechte Davids aber hatten eine Anzahl von den Benjaminiten und von den 300 Manneu Abners erschlagen: 60 Mann nämlich waren gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Sie hoben nun Asahel auf und begruben ihn in seines Vaters Grab zu Bethlehem. Dann marschierten Joab und seine Leute die ganze Nacht. Bei Tagesanbruch kamen sie in Hebron an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Lange währte der Krieg zwischen Sauls Haus und dem Hause Davids. David aber wurde immer stärker, Sauls Haus immer schwächer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Zu Hebron wurden David Söhne geboren. Sein Erstgeborener war Amnon, der Jezreelitin Achinoam Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Sein nächster war Kilab, der Sohn der Karmelitin Abigail, der Witwe des Nabal. Der dritte war Absalom, der Sohn Maakas, der Tochter Talmais, des Königs von Gesur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Der vierte war Adonia, Chaggits Sohn. Der fünfte war Sephatia, Abitals Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Der sechste war Jitream, der Sohn von Davids Weib Egla. Diese wurden David zu Hebron geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Solange der Krieg zwischen Sauls Haus und dem Davidshause währte, hielt Abner fest zum Hause Sauls.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saul aber hatte ein Nebenweib gehabt, Ajas Tochter namens Nispa. Da sprach Isboset zu Abner: \"Warum hast du meines Vaters Nebenweib geheiratet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Da zürnte Abner ob der Worte des Isboset und sprach: \"Bin ich ein Hundskopf, der es mit Juda hält? Heute noch erweise ich Gunst dem Hause deines Vaters Saul, seinen Brüdern und Freunden. Ich habe dich nicht in Davids Hand fallen lassen. Und du wirfst mir heute dieses Weib vor?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'So tue Gott dem Abner, und so mache er es ihm! Was der Herr dem David zugeschworen, das tue ich für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Ich entreiße das Königtum dem Hause des Saul und errichte Davids Thron über Israel und Juda von Dan bis Beerseba.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Da konnte er Abner kein Wort mehr erwidern, aus Furcht vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Abner schickte aber auf der Stelle Boten an David mit der Botschaft: \"Wes ist das Land?\" Damit sagte er: \"Verbünde dich mit mir! Dann ist meine Hand mit dir, und ich führe dir ganz Israel zu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Jener sprach: \"Gut! Ich verbünde mich mit dir. Nur das eine fordere ich von dir: Du siehst nicht mein Antlitz, außer du bringst Sauls Tochter Mikal mit, wenn du herkommst, mein Antlitz zu sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'David sandte auch Boten an Sauls Sohn Isboset und ließ sagen: \"Gib mir mein Weib Mikal heraus, die ich mir um hundert Philisterglieder gefreit habe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboset schickte nun hin und ließ sie von ihrem Manne Paltiel, dem Sohn des Lais, holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Ihr Mann aber ging mit ihr und folgte ihr beständig weinend bis Bachurim. Da sprach Abner zu ihm: \"Auf! Kehre um!\" Da kehrte er um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abners Wort aber erging an die Ältesten Israels: \"Früher schon habt ihr David zum König über euch begehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Nun führt es aus! Denn der Herr hat von David gesprochen: \'Durch David, meinen Knecht, rette ich mein Volk Israel aus der Philister Hand und aus der Hand all seiner anderen Feinde.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Ebenso sprach Abner zu Benjamin. Dann ging Abner, um es auch David in Hebron zu melden, was Israel und das ganze Benjaminhaus wünschten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'So kam Abner zu David nach Hebron mit zwanzig Mann. Da gab David dem Abner und den Mannen bei ihm ein Gastmahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abner sprach nun zu David: \"Ich will mich aufmachen und hingehen zu meinem Herrn, dem König, und ganz Israel entbieten, daß sie sich mit dir verbünden. Dann kannst du König sein, wie du nur wünschest.\" Da entließ David den Abner. Und er ging in Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Da kamen Davids Leute mit Joab von einem Streifzug und brachten reiche Beute mit. Abner aber war nicht mehr bei David in Hebron. Denn er hatte ihn entlassen, und er war in Frieden gegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Joab und die ganze Schar bei ihm war nun heimgekommen. Da meldete man Joab: \"Ners Sohn Abner ist zum König gekommen; er aber ließ ihn ziehen, und so ging er in Frieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Da kam Joab zum König und sprach: \"Was hast du getan? Abner ist ja zu dir gekommen. Warum hast du ihn fortziehen lassen, daß er gehen konnte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Du kennst doch Abner, Ners Sohn. Er ist nur gekommen, dich zu hintergehen, dein Tun und Lassen zu erkunden und alles, was du tust, auszuspähen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Und Joab ging von David weg und sandte Boten hinter Abner her. Sie holten ihn vom Brunnen der Herberge zurück. David aber hatte nichts davon gewußt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'So kam Abner wieder nach Hebron. Da nahm ihn Joab inmitten des Tores beiseite, mit ihm ungestört zu reden. Er stach ihn aber dort in den Leib. So starb er für das Blut seines Bruders Asahel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'David hörte es nachher und sprach: \"Ich und mein Königtum sind vor dem Herrn allzeit unschuldig am Blute Abners, des Nersohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Es falle auf Joabs Haupt und auf sein ganzes Vaterhaus! Niemals fehle es im Hause Joabs an Flüssigen und Aussätzigen, an Spindelführenden, Schwertverfallenen und an Bettlern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Joab und sein Bruder Abisai aber hatten Abner ermordet, weil er ihren Bruder Asahel zu Gibeon im Kampf getötet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'David aber sprach zu Joab und allem Volke bei ihm: \"Zerreißt eure Kleider, umgürtet euch mit Bußgewändern und klagt vor Abner her!\" Und der König David ging hinter der Bahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Sie begruben Abner zu Hebron, und der König weinte laut an Abners Grab. Und alles Volk weinte mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Der König aber dichtete auf Abner einen Sang und sprach: \"Sollt\' Abner enden, so wie Aberwitzige enden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Die Arme dein, sie waren nicht zu fesseln und deine Füße nicht zu ketten. Du bist gefallen so, wie man vor Meuchelmördern fällt.\" - Da weinte alles Volk noch mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Dann kam das ganze Volk, David zum Essen zu nötigen, solange es noch Tag war. Aber David schwur: \"Gott tue mir dies und das, wenn ich vor Sonnenuntergang Brot oder sonst etwas koste!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Dies hatte das ganze Volk wahrgenommen, und es gefiel ihm, wie alles, was der König getan, dem Volke gefiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Das ganze Volk aber und ganz Israel sahen an jenem Tage klar, daß es nicht vom König ausgegangen war, Abner, den Nersohn, zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Auch sprach der König zu seinen Dienern: \"Wißt ihr nicht, daß heute ein Fürst und Großer in Israel gefallen ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ich aber bin heute nur ein schwacher und unnützer König. Aber diese Männer, die Serujasöhne, sind für mich zu stark. Vergelte der Herr dem, der den Frevel tat, nach seiner Missetat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Als Sauls Sohn hörte, daß Abner zu Hebron gestorben sei, ward er mutlos; ganz Israel aber war bestürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Nun hatte Sauls Sohn zwei Häuptlinge. Der eine hieß Baana, der andere Rekab, Söhne des Beerotiters Rimmon, aus den Söhnen Benjamins. Denn auch Beerot wird zu Benjamin gerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Aber die Beerotiter flohen nach Gittim und waren dort zu Gast bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Sauls Sohn Jonatan nun hatte einen Sohn, der an beiden Füßen lahm war. Er war fünf Jahre alt gewesen, als die Nachricht von Saul und Jonatan aus Jezreel kam. Da packte ihn seine Amme und floh. In der Hast ihrer Flucht aber fiel er hin und ward gelähmt. Er hieß Mephiboset.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Die Söhne des Beerotiters Rimmon nun, Rekab und Baana, zogen aus und betraten während der Mittagshitze Isbosets Haus. Er hielt eben seinen Mittagsschlaf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'So waren sie mitten ins Haus gekommen, als wollten sie Weizen kaufen. Da stachen sie ihn in den Bauch. Dann waren Rekab und sein Bruder Baana entflohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Sie waren also in das Haus gekommen. Er aber schlief auf dem Bett in seinem Schlafzimmer. Da schlugen sie ihn und töteten ihn. Dann hieben sie ihm das Haupt ab. Sie nahmen nun seinen Kopf und gingen die ganze Nacht die Steppe entlang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Dann brachten sie Isbosets Haupt nach Hebron zu David und sprachen zum König: \"Da ist das Haupt des Isboset, des Sohnes deines Feindes Saul, der dir nach dem Leben getrachtet. So gab der Herr meinem Herrn heute Rache an Saul und seinen Nachkommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Da antwortete David Rekab und seinem Bruder Baana, den Söhnen des Beerotiters Rimmon, und sprach: \"So wahr der Herr lebt, der mein Leben aus aller Not befreit hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Daß ich den, der mir gemeldet \'Saul ist tot\' und der sich für einen Glücksboten gehalten, festnahm und in Siklag niederhieb, das ist mein Botenlohn gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Wenn nun ruchlose Menschen einen rechtschaffenen Mann in seinem Haus auf seinem Lager ermordet haben, muß ich da nicht sein Blut von euch fordern und euch vom Erdboden tilgen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Und David gebot den Knechten, und sie schlugen sie nieder, hieben ihnen Hände und Füße ab und hängten sie am Teich zu Hebron auf. Das Haupt des Isboset aber nahmen sie mit; dann begruben sie ihn in Abners Grab zu Hebron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Da kamen alle Stämme Israels zu David nach Hebron und sprachen: \"Wir sind auch dein Fleisch und dein Bein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Schon längst, als noch Saul König über uns war, bist du es gewesen, der Israel aus- und zurückgeführt hat. Auch sprach der Herr zu dir: \'Du sollst mein Volk Israel weiden und Fürst über Israel sein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Also kamen alle Ältesten Israels zum König nach Hebron. Und der König schloß mit ihnen einen Bund zu Hebron vor dem Herrn. Dann salbten sie David zum König über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Dreißig Jahre alt war David, als er König wurde, und vierzig Jahre hat er regiert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'In Hebron hat er über Juda sieben Jahre und sechs Monate regiert. In Jerusalem hat er dreiunddreißig Jahre regiert über ganz Israel und Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Der König zog nun mit seinen Mannen nach Jerusalem wider den Jebusiter, der in der Gegend saß. Da sagte man zu David: \"Du kommst nur hinein, wenn die Dunklen und die Blonden deine Sklaven sind.\" Das sollte heißen: \'David kommt nicht hinein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Aber David erstürmte die Burg Sion, das ist die Davidsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Da sprach David an jenem Tage: \"An den Hof kommt jeder, der die Blonden und die Dunklen schlägt, selbst ein Jebusiter.\" Sie waren David in der Seele zuwider. Deshalb sagte man: \"Kein Dunkler und kein Blonder darf das Haus betreten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Dann setzte sich David in die Burg und nannte sie Davidsstadt. Und David baute ringsum von der Bastei nach innen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'So ward David allmählich immer mächtiger, war doch der Herr, der Gott der Heerscharen, mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Und so sandte Chiram, König von Tyrus, Boten an David mit Zedernholz und Zimmerleuten und Steinmetzen. Und sie bauten David ein Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'So erkannte David, daß ihn der Herr als König über Israel bestätigt und daß er wegen seines Volkes Israel sein Königtum hochgebracht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'David aber nahm noch mehr Nebenweiber und Weiber von Jerusalem, nachdem er von Hebron gekommen war. Auch wurden David noch Söhne und Töchter geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Dies sind die Namen der ihm zu Jerusalem Geborenen: Sammua, Sobab, Natan und Salomo,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Ibchar, Elisua, Nepheg, Japhia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada und Eliphelet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Die Philister aber hörten, daß man David zum König über ganz Israel gesalbt habe. Da zogen alle Philister hinauf, David zu suchen. David aber hörte es und zog nach der Bergfeste hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Die Philister kamen nun und ließen sich in der Rephaimebene nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Da befragte David den Herrn: \"Soll ich gegen die Philister ziehen? Gibst Du sie in meine Hand?\" Da sprach der Herr zu David: \"Ja! Ich gebe sicher die Philister in deine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Da zog David nach Baal Perasim. Und dort schlug sie David. Er sprach: \"Der Herr hat mir meine Feinde durchbrochen, wie Wasser durchbricht.\" Deshalb nennt man jenen Ort Baal Perasim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Sie ließen aber ihre Götzenbilder dort im Stich, und David mit seinen Leuten nahm sie mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Abermals zogen die Philister herauf und ließen sich in der Rephaimebene nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Da befragte David den Herrn. Er sprach: \"Du sollst nicht hinaufziehen! Wende dich gegen ihren Rücken und komme über sie von den Geröllhalden her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Hörst du Geräusch von Schritten auf den oberen Rändern der Geröllhalden, dann brich los! Denn dann zieht der Herr vor dir her, im Philisterlager dreinzuschlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Und David tat, wie ihm der Herr befohlen, und schlug die Philister von Geba bis Gezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'David versammelte nochmals alle Erlesenen in Israel, 30.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Dann brach David auf und zog mit dem ganzen Volke bei ihm von Baalat Juda aus, von dort die Gotteslade heraufzuholen, wo der Name des Herrn der Heeresscharen, der auf Cheruben thront, angerufen worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Sie luden nun die Gotteslade auf einen neuen Wagen und brachten sie aus Abinadabs Haus, das zu Gibea stand. Den neuen Wagen aber lenkten Uzza und Achjo, Abinadabs Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'So brachten sie ihn aus Abinadabs Haus zu Gibea samt der Gotteslade fort. Achjo aber schritt vor der Lade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Und David und das ganze Haus Israel tanzten vor dem Herrn unter dem Klange von Zithern, Harfen, Pauken, Schellen und Zimbeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Als sie aber an ein bebautes Feldstück kamen, griff Uzza nach der Gotteslade und hielt sich daran fest, weil ihn die Rinder ins Wanken gebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Da entbrannte des Herrn Zorn über Uzza. Und Gott schlug ihn dort wegen des Vergehens. So starb er dort neben der Gotteslade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Da ward David mißgestimmt, daß der Herr den Uzza geschlagen hatte. Und er nannte jenen Ort \"Schlag des Uzza\", wie er jetzt noch heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'David aber fürchtete sich vor dem Herrn an jenem Tage und sprach: \"Wie soll da die Lade des Herrn zu mir kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Und David wollte die Lade des Herrn nicht mehr zu sich in die Davidsstadt bringen. So ließ sie David beiseite führen, in das Haus des Gatiters Obededom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'So blieb die Lade des Herrn im Hause des Gatiters Obededom drei Monate. Aber der Herr segnete Obededom und sein ganzes Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Da ward dem König David gemeldet: \"Der Herr segnete Obededoms Haus und all seinen Besitz um der Gotteslade willen.\" Da ging David hin und holte unter Jubel die Gotteslade nach der Davidsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Sooft nun die Träger der Lade des Herrn sechs Schritte gemacht hatten, opferte er ein Rind und ein Mastkalb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Und David tanzte mit aller Kraft vor dem Herrn. David aber war mit einem leinenen Ephod umgürtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'So führten David und das ganze Haus Israel die Lade des Herrn unter Jauchzen und mit lautem Posaunenschall hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Als aber die Lade des Herrn in die Davidsstadt einzog, hatte sich Sauls Tochter Mikal durch das Fenster gebeugt. Da sah sie den König David vor dem Herrn springen und tanzen. Und sie verachtete ihn in ihrem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Sie aber brachten die Lade des Herrn und stellten sie an ihren Platz in dem Zelt, das David für sie aufgeschlagen hatte. Dann brachte David vor dem Herrn Brand- und Mahlopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Als David fertig war, Brand- und Mahlopfer darzubringen, begrüßte er das Volk im Namen des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Und er verteilte an alles Volk, für die ganze Menge Israels, Männer und Weiber, je einen Brotkuchen, einen Laib und einen Traubenkuchen. Dann ging ein jeder aus dem Volk in sein Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'David kehrte nun heim, sein Haus zu begrüßen. Da trat Sauls Tochter Mikal dem David entgegen und sprach: \"Wie ehrenvoll hat sich heute Israels König betragen, der sich heute vor den Augen der Mägde seiner Diener entblößt hat, wie sich die Verrückten entblößen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Da sprach David zu Mikal: \"Dies geschah zu Ehren des Herrn, der mich vor deinem Vater und seinem ganzen Haus vorgezogen hat, um mich zum Fürsten über das Volk des Herrn, über Israel, zu bestellen. So habe ich vor dem Herrn gespielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Und ich erniedrige mich noch mehr als hier und will in deinen Augen klein sein. Bei den Mägden, von denen du gesprochen, bei ihnen möchte ich mir Ehre holen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Und Sauls Tochter Mikal bekam kein Kind bis zu ihrem Todestag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'David wohnte nun in seinem Hause, und der Herr hatte ihm Ruhe ringsum vor all seinen Feinden verschafft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Da sprach der König zum Propheten Natan: \"Sieh doch! Ich wohne in einem Zedernhause. Die Gotteslade aber weilt in einem bloßen Zelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Da sprach Natan zum König: \"Tu alles, was du im Sinne hast! Denn der Herr ist mit dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Aber noch in der gleichen Nacht erging das Wort des Herrn an Natan:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '\"Gehe hin und sage meinem Knechte David: \'So spricht der Herr: Du willst ein Haus mir bauen zu meinem Sitze?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Ich habe nie in einem Haus gewohnt seit jener Zeit, da ich die Söhne Israels aus Ägypterland geführt, bis hin zu diesem Tag. Ich zog in einem Wohnzelt umher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Habe ich, solange ich bei all den Söhnen Israels umhergezogen, jemals ein Wort zu einem Führer Israels gesagt, den ich beauftragt, Israel, mein Volk, zu weiden: \"Warum baut ihr mir nicht ein Zedernhaus?\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'So sage nunmehr zu meinem Knechte David: \'So spricht der Herr der Heerscharen: Ich habe von der Weide, aus der Herde dich hinweggeholt, auf daß du meines Volkes Israel Gebieter seiest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Ich war mit dir allüberall, wohin du gingst, und tilgte vor dir alle deine Feinde. Ich habe einen großen Namen dir geschaffen, gleich dem der Großen auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Ich habe eine Stätte meinem Volke Israel bestimmt und es dann eingepflanzt, daß es, an seiner Stätte wohnend, nimmer zittere und Ruchlose es nimmer drücken, so wie früher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Seit jenen Zeiten, da ich Richter meinem Volke Israel bestellt, habe ich dir Ruhe verschafft vor allen deinen Feinden. Der Herr hat dir verkündet, daß dir der Herr ein Haus erbauen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Sind deine Tage voll geworden, und liegst du dann bei deinen Vätern, alsdann bestimme ich auch deinen Leibessprossen zu deinem Nachfolger und ich bestätige sein Königtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Er baut ein Haus dann meinem Namen, und ich bestätige seinen Königsthron für alle Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ich will ihm Vater sein; er wird mir Sohn. Verfehlt er sich, dann strafe ich ihn mit einer Rute, wie für ganz einfache Menschen, mit Schlägen wie für ganz gewöhnliche Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Und nie weicht meine Huld von dir, wie ich sie Saul entzogen, den ich vor dir beseitigt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Dein Haus mit deinem Königtum wird ewiglich vor mir bestehen. Dein Thron steht fest für alle Zeit.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Genau nach all diesen Worten und diesem ganzen Gesichte hatte Natan zu David gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Da kam König David, setzte sich vor den Herrn und sprach: \"Wer bin ich, Herr, ach Herr? Was ist mein Haus, daß Du mich bis hierher geführt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Dies war Dir noch zuwenig, Herr, ach Herr. Du gabst dem Hause Deines Sklaven Verheißungen auf weit hinaus. Und dies ist eine Lehre für die Menschen, Herr, Du Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Was sollte David weiter zu Dir sagen? Du selbst kennst Deinen Knecht, Herr, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Für Deinen Sklaven, Deinen Hund, hast Du dies Große all getan, um Deinem Sklaven es zu zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Deswegen bist Du groß, Herr, Gott. Denn Dir ist keiner gleich. Kein Gott ist außer Dir, nach alledem, was wir vernommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Wo ist ein Volk, gleich Deinem Israel, ein einzig Volk auf Erden, das sich zum Volke zu erkaufen, ein Gott gegangen wäre, sich einen Namen zu verschaffen, euch Großes zu erweisen und Wunderbares Deinem Land, vor Deinem Volke, das Du Dir aus Ägypten hast erlöst? Wo ist ein Volk und dessen Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Doch Du hast Israel, Dein Volk, für immer Dir zum Volk bestellt und Du bist ihnen, Herr, zum Gott geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Nun aber, Herr und Gott, laß jetzt das Wort für alle Zeiten gültig sein, das Du gesprochen über Deinen Sklaven und sein Haus, und handle so, wie Du gesagt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Dann ist Dein Name groß für alle Zeiten und lautet: \'Herr der Heeresscharen, Gott Israels\'. Und Deines Sklaven David Haus steht vor Dir fest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Denn Du, der Heeresscharen Herr, Gott Israels, hast Deinem Sklaven selbst geoffenbart: \'Ich will ein Haus dir bauen.\' Drum faßt Dein Sklave sich ein Herz, um dies Gebet Dir vorzutragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nun denn, Herr, Herr! Du selbst bist Gott, und Deine Worte, Herr, sind Wahrheit. Du gabst dies herrliche Versprechen Deinem Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Nun laß es Dir gefallen und segne Deines Sklaven Haus, daß es für alle Zeit vor Dir bestehe! Herr, Herr! Du hast es selbst gesagt. So möge auch durch Deinen Segen auf ewig Deines Sklaven Haus gesegnet sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Danach schlug David die Philister und demütigte sie. David nahm auch die Talsperre den Philistern aus der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Dann schlug er Moab und vermaß es mit der Meßschnur, nachdem er sie zu Boden geworfen hatte. Je zwei Schnüre maß er zur Verwüstung ab und je eine Schnur zur Aufpflanzung. So ward Moab David untertan und steuerpflichtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Dann schlug David den König von Soba, Hadadezer, Rechobs Sohn, als er auszog, seine Hand nach dem Strom zu strecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'David nahm ihm 1.700 Wagenkämpfer und 20.000 Mann Fußvolk ab. Alle Rosse lähmte David. Nur 100 Pferdewagen ließ er davon übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Da kamen die damaszenischen Aramäer dem König von Soba, Hadadezer, zu Hilfe. Aber David schlug von den Aramäern 22.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Dann setzte David im damaszenischen Aram Vögte ein. So wurden die Aramäer David untertan und steuerpflichtig. Der Herr half David überall, wohin er zog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'David nahm nun die goldenen Schilde der Knechte Hadadezers und brachte sie nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Aus Tebach und aus Berotai, den Städten des Hadadezers, nahm König David sehr viel Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Da hörte Toi, der König von Chamat, David habe die ganze Streitmacht Hadadezers geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'So sandte nun Toi seinen Sohn Hadoram zum König David, ihn zu begrüßen und zu beglückwünschen wegen seines siegreichen Kampfes mit Hadadezer. Denn Hadadezer war Tois Kriegsgegner. Er brachte silberne, goldene und eherne Gefäße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Auch sie weihte König David dem Herrn, samt dem Silber und Gold, das er von all den Völkern geweiht, die er unterjocht hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'von den Edomitern, Moabitern, Ammonitern, Philistern und Amalekitern und von der Beute des Hadadezer, des Königs von Soba und Sohnes des Rechob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'So machte sich David einen Namen nach seiner Rückkehr vom Siege aber die 18.000 Mann Aramäer im Salztale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'In Edom bestellte er Vögte, hatte er doch mit ganz Edom ein Abkommen getroffen. So ward ganz Edom David untertan. Der Herr half nämlich David überall, wohin er zog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'So regierte David über ganz Israel. Und David übte Recht und Gerechtigkeit an seinem ganzen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Über das Heer war Serujas Sohn Joab gesetzt, und Achiluds Sohn Josaphat war Kanzler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Achitubs Sohn Sadok und Achimelek, Ebjatars Sohn, waren Priester, Seraja Schreiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Jojadas Sohn, war Anführer der Bogenschützen und der Schildträger. Davids Söhne aber waren Landleute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Da fragte David: \"Ist noch jemand von Sauls Haus übrig? Ich möchte ihm um Jonatans willen Liebes tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Nun war im Hause Sauls ein Diener, namens Siba. Ihn rief man zu David, und der König fragte ihn: \"Bist du Siba?\" Er sprach: \"Ja, dein Sklave.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Da fragte ihn der König: \"Ist niemand mehr von Sauls Haus da, daß ich an ihm Gottes Liebe erweise?\" Da sprach Siba zum König: \"Noch ist ein Sohn Jonatans da, aber mit lahmen Beinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Da sprach zu ihm der König: \"Wo ist er?\" Da sprach Siba zum König: \"Er ist im Hause Makirs, des Sohnes Ammiels, zu Lodebar.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Da sandte König David hin und ließ ihn aus dem Hause des Ammielsohnes Makir aus Lodebar holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'So kam Mephiboset, der Sohn des Saulssohns Jonatan zu David. Er warf sich auf sein Antlitz und huldigte. Da sprach David: \"Mephiboset!\" Er sprach: \"Hier ist dein Sklave.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Da sprach David zu ihm: \"Fürchte nichts. Ich will dir Liebes tun wegen deines Vaters Jonatan. Ich gebe dir das ganze Grundstück deines Ahnherrn Saul zurück, und du selbst magst jederzeit an meinem Tische speisen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Da verneigte er sich und sprach: \"Was ist dein Sklave, daß du dich einem toten Hund zuwendest, wie ich einer bin?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Da rief der König nach Siba, Sauls Diener, und sprach zu ihm: \"Alles, was Saul und seinem ganzen Haus gehört hat, gebe ich dem Sohne deines Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Bestelle ihm das Land, du, deine Söhne und deine Sklaven, und heimse es ihm ein, damit das Haus deines Herrn Speise zur Zehrung habe! Deines Herrn Sohn Mephiboset soll jederzeit an meinem Tische speisen!\" Siba selbst aber besaß fünfzehn Söhne und zwanzig Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Da sprach Siba zum König: \"Ganz so, wie mein Herr, der König, seinem Sklaven befiehlt, wird dein Sklave tun, obschon Mephiboset an meinem Tisch speisen könnte, wie einer der Königssöhne.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mephiboset aber hatte einen kleinen Sohn, namens Mika. Alle Insassen in Sibas Haus dienten Mephiboset.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Mephiboset nun wohnte zu Jerusalem; denn er speiste ständig an des Königs Tafel, obwohl er an beiden Beinen gelähmt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Danach starb der Ammoniterkönig, und sein Sohn Chanun ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Da sprach David: \"Ich will dem Chanun, des Nachas Sohn, Liebes tun, wie sein Vater mir Liebes hat getan.\" So schickte David hin, ihn durch seine Diener wegen seines Vaters zu trösten. So kamen Davids Diener ins Ammoniterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Da sprachen die Ammoniterfürsten zu ihrem Herrn Chanun: \"Ehrt David nach deiner Ansicht deinen Vater, daß er dir Tröster schickt? Sendet nicht David seine Diener zu dir, die Stadt auszuspähen, auszuforschen und zu erkunden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Da ergriff Chanun Davids Diener, schor ihnen den Bart halb ab und schnitt ihnen die Kleider halb bis ans Gesäß weg. So schickte er sie fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Als man dies David meldete, sandte er ihnen entgegen. Denn die Männer waren schwer beschimpft. Der König ließ ihnen sagen: \"Bleibt in Jericho, bis euch der Bart gewachsen ist! Dann kommt heim!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Die Ammoniter aber merkten, daß sie sich bei David verhaßt gemacht hatten. Da schickten die Ammoniter hin und dingten bei Aram in Bet Rechob und bei Aram in Soba 20.000 Fußtruppen und vom König von Maaka 1.000 Mann und 12.000 Mann von Tob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Als dies David hörte, sandte er Joab und das ganze Heer, die Krieger, aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Da rückten die Ammoniter aus und stellten sich zum Kampfe vor das Stadttor. Die Aramäer von Soba und Rechob aber und die Mannschaften von Tob und Maaka standen für sich im Gelände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Als Joab sah, daß ihm ein Angriff von vorn und von hinten drohe, wählte er Leute aus allen Erlesenen Israels und stellte sich den Aramäern entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Den Rest des Volkes aber hatte er seinem Bruder Abisai unterstellt. Auch er stellte sich den Ammonitern entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Er sprach: \"Werden aber die Ammoniter mir zu stark, dann komm du mir zu Hilfe! Werden aber die Aramäer dir zu stark, dann komme ich dir zu helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sei tapfer! Seien wir mutig für unser Volk und Diener unseres Gottes. Der Herr aber tue, was ihm gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'So rückten Joab und das Volk bei ihm zum Kampfe gegen die Aramäer vor. Da flohen sie vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Als die Ammoniter sahen, daß die Aramäer flohen, flohen auch sie vor Abisai und zogen sich zurück. Da ließ Joab von den Ammonitern ab und kam nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Als die Aramäer sahen, daß sie von Israel geschlagen waren, sammelten sie sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Und Hadadezer sandte hin und ließ die Aramäer jenseits des Stromes ausrücken. Und sie kamen nach Chelam. Hadadezers Feldherr Sobak aber war an ihrer Spitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Dies ward David gemeldet. Da bot er ganz Israel auf, überschritt den Jordan und kam nach Chelam. Da stellten sich die Aramäer David entgegen und kämpften mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Aber die Aramäer mußten vor Israel fliehen. Und David schlug von den Aramäern 700 Wagenkämpfer und 40.000 Mann Fußvolk. Auch ihren Feldherrn Sobak schlug er, daß er dort starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Als alle Könige, Hadadezers Untergebene, sahen, daß sie von Israel geschlagen waren, schlossen sie mit Israel Frieden und waren ihm untertan. Die Aramäer aber hüteten sich, den Ammonitern weiter zu helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Um die Jahreswende, wenn die Könige ins Feld ziehen, sandte David den Joab und seine Diener mit ihm und ganz Israel hin. Sie verheerten das Land der Ammoniter und belagerten Rabba. David aber blieb in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'An einem Abend erhob sich David von seinem Lager und erging sich auf dem Dache des Königshauses. Da sah er vom Dache aus ein badendes Weib. Das Weib aber war sehr schön.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'David sandte nun hin und erkundigte sich nach dem Weibe. Da sagte man: \"Ist das nicht Eliams Tochter Batseba, das Weib des Chittiters Urias?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Da sandte David Boten und ließ sie holen. Sie kam zu ihm und er schlief bei ihr. Sie hatte sich nämlich von ihrer Unreinigkeit befreit. Dann kehrte sie heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'So ward das Weib schwanger. Sie sandte nun hin und meldete David: \"Ich bin schwanger.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Da sandte David zu Joab: \"Sende mir den Chittiter Urias!\" Da sandte Joab den Urias zu David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Urias kam dann zu ihm und David fragte nach Joabs und des Volkes Befinden und nach dem Kriegsglücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Dann sprach David zu Urias: \"Geh in dein Haus hinunter und wasche dir die Füße!\" Und Urias ging aus des Königs Haus. Da folgte ihm ein königlicher Wächter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Urias aber schlief im Tore des Königshauses bei all den Dienern seines Herrn. Er ging nicht in sein Haus hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Da meldete man David: \"Urias ist nicht in sein Haus hinabgegangen.\" Da sprach David zu Urias: \"Kommst du nicht von der Reise? Warum gehst du nicht in dein Haus hinab?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Da sprach Urias zu David: \"Die Lade und Israel und Juda weilen in Hütten. Mein Herr Joab und meines Herrn Diener lagern auf freiem Felde. Da sollte ich in mein Haus gehen, essen und trinken und bei meinem Weibe liegen? Bei deinem Leben und deiner Seele! So etwas tue ich nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Da sprach David zu Urias: \"Bleib auch heute noch hier! Morgen entlasse ich dich.\" So blieb Urias jenen Tag zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Am anderen Tage lud ihn David ein. Er aß und trank vor ihm. Schließlich machte er ihn trunken. Am Abend ging er hinaus, auf seinem Lager bei seines Herrn Diener zu schlafen. Aber in sein Haus ging er nicht hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Nun schrieb David am anderen Morgen einen Brief an Joab und sandte ihn durch Urias ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Er schrieb in dem Briefe: \"Stellt Urias vorn ins heftigste Kampfgewühl! Dann zieht euch von ihm zurück, daß er erschlagen werde und falle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Während Joab die Stadt belagerte, stellte er Urias an den Ort, wo, wie er wußte, tapfere Leute stünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Die Leute der Stadt machten nun einen Ausfall und kämpften mit Joab. Da fielen einige vom Volk, von Davids Dienern. Auch der Chittiter Urias fand den Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Da sandte Joab hin und berichtete David den ganzen Verlauf des Kampfes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Er befahl dem Boten: \"Berichtest du dem König den ganzen Hergang des Kampfes bis zum Ende');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'und braust der König auf und fragt dich: \'Warum seid ihr zum Treffen so nahe an die Stadt gerückt? Wußtet ihr nicht, daß sie von der Mauer herabschießen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Wer hat Jerubosets Sohn Abimelek erschlagen? Hat nicht ein Weib auf ihn einen Mühlstein von der Mauer geworfen, daß er zu Tebes starb? Warum seid ihr so nahe an die Mauer gerückt?\', dann sprich: \'Auch dein Diener Urias, der Chittiter, ist gefallen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Der Bote ging, kam und meldete David alles, was ihm Joab aufgetragen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Der Bote sprach zu David: \"Die Leute sind uns überlegen gewesen; sie drangen gegen uns ins freie Feld. Wir aber drängten sie bis an das Stadttor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Da schossen die Schützen auf deine Diener von der Mauer, daß von des Königs Dienern etliche den Tod fanden. Auch dein Knecht, der Chittiter Urias, fand den Tod.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Da sprach David zum Boten: \"Sprich so zu Joab: \'Kränke dich nicht darüber! Denn das Schwert frißt bald so, bald so. Führe wacker deinen Kampf gegen die Stadt und zerstöre sie!\' So ermutige ihn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Des Urias Weib aber vernahm, daß ihr Mann Urias gefallen sei. Da betrauerte sie ihren Gemahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Als aber die Trauer vorüber war, sandte David und ließ sie in sein Haus holen. So ward sie sein Weib und gebar ihm einen Sohn. Aber dem Herrn mißfiel, was David getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'So sandte der Herr den Natan zu David. Er kam zu ihm und sagte ihm: \"Zwei Männer waren in einer gewissen Stadt, der eine reich, der andere arm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Der Reiche besaß Schafe und Rinder in großer Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Der Arme aber hatte nichts als ein einziges Lämmchen, das er gekauft hatte. Er zog es auf, und es wuchs bei ihm auf mit seinen Kindern zusammen. Von seinem Bissen aß es, aus seinem Becher trank es und schlief an seinem Busen. Es galt ihm wie ein Kind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Da kam Besuch zu dem reichen Manne. Ihm aber war es leid, eines seiner Schafe und Rinder zu nehmen, um es dem Gast, der zu ihm gekommen, zuzubereiten. So nahm er das Lamm des armen Mannes und bereitete es dem Manne, der zu ihm gekommen war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Da ward David über den Mann sehr zornig und sprach zu Natan: \"So wahr der Herr lebt! Der Mann, der dies getan, ist ein Kind des Todes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Und das Lamm muß er vierfach erstatten, dafür, daß er dies getan und kein Erbarmen geübt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Da sprach Natan zu David: \"Du selbst bist der Mann. So spricht der Herr, Israels Gott: \'Ich habe dich zum König über Israel gesalbt. Ich habe dich aus der Hand des Saul gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Ich gab dir deines Herrn Haus, die Weiber deines Herrn an deinen Busen. Ich gab dir Israels und Judas Haus. Und wäre das zu wenig, so wollte ich dir noch dies und das geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Warum hast du des Herren Wort mißachtet und das getan, was ihm mißfällt? Du hast Urias, den Chittiter, mit dem Schwert erschlagen und hast dir seine Frau zum Weib genommen. Du hast ihn durch der Ammoniter Schwert ermordet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nun weiche nie das Schwert aus deinem eigenen Hause, zur Strafe dafür, daß du mich mißachtet, daß du das Weib Urias ́, des Chittiters, dir zum Weibe nahmst!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'So spricht der Herr: \'Ich lasse einen Nebenbuhler dir aus deinem Haus erstehen. Ich nehme weg vor deinen Augen deine Weiber und gebe diese deinem Nebenbuhler, daß er im Angesichte dieser Sonne deinen Weibern beiwohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Du hast es heimlich zwar getan. Ich aber tue dies im Angesicht des ganzen Israel und vor der Sonne.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Da sprach David zu Natan: \"Ich habe gegen den Herrn gesündigt.\" Da sprach Natan zu David: \"So sieht der Herr dir auch deine Sünde nach. Du wirst nicht sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Weil du aber auf die Feinde des Herrn dabei keine Rücksicht genommen, soll auch der Sohn, der dir geboren ward, sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Und Natan ging nach Hause. Der Herr aber schlug das Kind, das des Urias Witwe dem David geboren hatte. Es ward todkrank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Da suchte David um des Knaben willen Gott auf. Und David fastete streng, hielt Nachtwache und lag über Nacht auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Da traten die Ältesten seines Hauses zu ihm, ihn vom Boden aufzuheben. Er aber wollte nicht und genoß keine Speise mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Am siebten Tage starb der Knabe. Da fürchteten sich Davids Diener, ihm zu sagen, der Knabe sei tot. Denn sie sagten: \"Solange der Knabe lebte, haben wir ihm zugeredet; aber er gab uns kein Gehör. Wie können wir ihm sagen: \'Der Knabe ist tot!\' Er könnte Unheil anrichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'David aber sah seine Diener miteinander flüstern. Da erkannte David, daß der Knabe tot war. Und David sprach zu seinen Dienern: \"Ist der Knabe gestorben?\" Sie sagten: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Da stand David vom Boden auf, wusch sich und salbte sich und wechselte sein Gewand. Dann ging er in das Haus des Herrn und warf sich nieder. Hierauf ging er in sein eigen Haus und verlangte etwas. Da setzten sie ihm Speise vor, und er aß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Da sprachen seine Diener zu ihm: \"Was für ein Gebaren ist dies, das du zeigst? Als der Knabe noch lebte, hast du gefastet, dazu weintest du. Und nun, da der Knabe tot ist, stehst du auf und genießest Speise?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Da sprach er: \"Solange der Knabe lebte, habe ich gefastet und dazu geweint, weil ich gedacht habe: \'Wer weiß? Der Herr kann sich meiner erbarmen, daß der Knabe leben bleibt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nun ist er aber tot. Wozu sollte ich fasten? Kann ich ihn wieder zurückbringen? Ich gehe zu ihm. Aber er kommt nicht wieder zu mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Und David tröstete sein Weib Batseba. Er ging zu ihr und wohnte ihr bei. Da gebar sie einen Sohn und sie nannte ihn Salomo. Und der Herr hatte ihn lieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Und durch den Propheten Natan ließ er ihn Jedidia nennen wegen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab aber bestürmte das ammonitische Rabba und eroberte die Königsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Da sandte Joab Boten zu David und ließ melden: \"Ich habe Rabba bestürmt und die Zufluchtsstadt erobert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Nun sammle den Rest des Volkes! Bestürme die Stadt und erobere sie vollends, damit nicht ich die Stadt erobere und mein Name darüber genannt würde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Da sammelte David alles Volk und zog nach Rabba, bestürmte und eroberte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Dann nahm er die Krone Milkoms von dessen Kopf. Sie wog ein Talent Gold, dabei war ein Edelstein, und er kam auf Davids Haupt. Die Beute der Stadt führte er in großer Menge heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Das Volk darin aber hatte er herausgeführt; dann legte er Feuerbrände an und hieb und stach mit Eisen darein; sie selber aber hatte er der Königsfron überwiesen. So tat er mit allen Ammoniterstädten. Dann kehrten David und das ganze Volk nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Hernach geschah folgendes: Absalom, Davids Sohn, hatte eine schöne Schwester namens Tamar. In sie verliebte sich der Davidssohn Amnon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Und Amnon quälte sich ganz krank wegen seiner Schwester Tamar. Denn sie war eine züchtige Jungfrau. Und so erschien es dem Amnon unmöglich, mit ihr etwas zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Nun hatte Amnon einen Freund namens Jonadab, Sohn des Sima, eines Bruders Davids, Jonadab aber war ein sehr kluger Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Er sprach zu ihm: \"Warum bist du, Königssohn, Morgen für Morgen so elend? Willst du es mir nicht sagen?\" Da sprach Amnon zu ihm: \"Ich liebe Tamar, meines Bruders Absalom Schwester.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Da sprach Jonadab zu ihm: \"Lege dich zu Bett und stell dich krank! Und kommt dein Vater, dich zu besuchen, dann sage ihm: \'Käme doch meine Schwester Tamar und brächte mir etwas zu essen! Wenn sie vor meinen Augen das Essen bereitete, daß ich es sehe, dann wollte ich gerne von ihrer Hand essen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'So legte sich Amnon nieder und stellte sich krank. Und der König kam, ihn zu besuchen. Da sprach Amnon zum König: \"Käme doch meine Schwester Tamar und machte vor meinen Augen ein paar Kuchen, daß ich von ihrer Hand essen könnte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Da sandte David nach Haus zu Tamar und ließ sagen: \"Geh doch in deines Bruders Amnon Haus und bereite ihm das Essen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Da ging Tamar in ihres Bruders Amnon Haus. Er aber lag zu Bette. Sie nahm den Teig, knetete ihn und bereitete vor seinen Augen die Kuchen und buk sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Dann nahm sie die Pfanne und stürzte sie vor ihn. Er aber weigerte sich zu essen. Dann sprach Amnon: \"Entfernt alle von hier!\" Da ging alles von ihm hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Dann sprach Amnon zu Tamar: \"Bring das Essen in das innere Gemach! Dann will ich von deiner Hand essen.\" Da nahm Tamar die Kuchen, die sie gemacht hatte, und brachte sie ihrem Bruder Amnon ins innere Gemach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Sie bot ihm zu essen. Da faßte er sie und sprach zu ihr: \"Komm, leg dich zu mir, meine Schwester!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Da sprach sie zu ihm: \"Nicht doch, mein Bruder, entehre mich nicht! Denn so etwas tut man nicht in Israel. Tu nicht solche Freveltat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Wohin sollte ich meine Schande tragen? Du selbst gältest in Israel als einer der größten Missetäter. Sprich doch lieber mit dem König! Er versagt mich dir nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Er aber wollte ihr kein Gehör schenken, sondern überwältigte und vergewaltigte sie. Und so wohnte er ihr bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Dann aber faßte Amnon eine überaus tiefe Abneigung gegen sie. Ja, die Abneigung, die er gegen sie faßte, war größer als die Liebe, die er zu ihr gehabt hatte. Und so sprach Amnon zu ihr: \"Auf! Fort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Sie sprach zu ihm: \"Nein! Dieses große Unrecht, wenn du mich fortjagtest, wäre noch größer als das andere, das du mir angetan!\" Er aber wollte nicht auf sie hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Er rief seinen Burschen und Diener und sprach: \"Schaff mir die da fort auf die Straße. Verriegle die Tür hinter ihr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Sie aber trug einen buntgewirkten Leibrock. Denn solche Obergewänder hatten von alters her die Königstöchter, solange sie Jungfrauen waren. Sein Diener führte sie nun auf die Straße und verriegelte hinter ihr die Tür.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Da streute sich Tamar Asche auf das Haupt, zerriß den buntgewirkten Leibrock, den sie trug, schlug die Hände über dem Kopf zusammen und ging unter beständigem Wehgeschrei davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Da sprach ihr Bruder Absalom zu ihr: \"War dein Bruder Amnon bei dir? Nun, meine Schwester, schweig still! Dein Bruder ist es. Nimm dir diese Sache nicht zu Herzen!\" So blieb Tamar, und zwar unvermählt, im Hause ihres Bruders Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Der König aber erfuhr den ganzen Vorgang. Da ward er sehr zornig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalom aber redete kein Wort mit Amnon, weder im Bösen noch im Guten. Aber Absalom haßte den Amnon, weil er seine Schwester Tamar entehrt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Nach zwei Jahren hielt Absalom Schafschur in Baal Chasor bei Ephraim. Dazu lud Absalom alle Königssöhne ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalom kam nämlich zum König und sprach: \"Dein Sklave hält heute Schafschur. Möchten doch der König und seine Diener mit deinem Sklaven gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Da sprach der König zu Absalom: \"Nicht doch, mein Sohn! Wir wollen nicht alle hingehen, daß wir dir nicht beschwerlich fallen.\" Da drängte er ihn. Er aber wollte nicht gehen, sondern segnete ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Da sprach Absalom: \"Wenn nicht, dann gehe wenigstens mein Bruder Amnon mit uns!\" Da fragte ihn der König: \"Wozu soll er mit dir gehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Absalom aber drang in ihn. Und so sandte er Amnon und alle anderen Königssöhne mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom aber befahl seinen Dienern: \"Wenn Amnon vom Wein guter Laune sein wird, und ich spreche zu euch: \'Haut Amnon nieder!\' Dann tötet ihn! Fürchtet nichts! Gebe nicht ich euch den Befehl? Seid also mutig und zeigt euch als wackere Mannen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Absaloms Diener taten an Amnon, wie Absalom geboten hatte. Da sprangen alle anderen Königssöhne auf, jeder schwang sich auf sein Maultier und floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Noch waren sie unterwegs. Da war schon das Gerücht zu David gedrungen, Absalom habe alle Königssöhne erschlagen; nicht einer von ihnen sei mehr übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Da stand der König auf, zerriß seine Gewänder und warf sich zur Erde, und alle seine Diener standen mit zerrissenen Kleidern da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Da hob Jonadab an, der Sohn des Davidsbruders Sima, und sprach: \"Mein Herr sage nicht, man habe all die jungen Königssöhne umgebracht! Amnon allein ist tot. Denn so wie Absalom ist, war es geplant seit dem Tage, da jener seine Schwester Tamar entehrt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'So setze sich mein Herr und König nicht den Gedanken in den Kopf, alle Königskinder seien tot! Amnon allein ist tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalom aber floh.\" Der wachhabende Diener hielt eben Ausschau. Da sah er eine Menge Leute auf der Straße hinter ihm von der Bergseite kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Da sprach Jonadab zum König: \"Die Königssöhne kommen. Wie dein Sklave sagte, so war es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Er hatte eben ausgeredet. Da waren die Königssöhne angekommen; sie erhoben ihre Stimme und weinten. Auch der König und all seine Diener hatten überlaut geweint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom aber war geflohen; er ging zu Talmai, dem König von Gesur und Ammichuds Sohn. Jener aber trauerte um seinen Sohn die ganze Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom aber war entflohen; er ging nach Gesur. Dort blieb er drei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'David aber dachte schon daran, Absalom entgegenzukommen. Denn er hatte sich darüber getröstet, daß Amnon tot war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joab, Serujas Sohn, merkte nun, daß sich des Königs Herz Absalom zuneigte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Da schickte Joab nach Tekoa und ließ von dort ein kluges Weib holen. Er sprach zu ihr: \"Stell dich trauernd und zieh Trauerkleider an! Salbe dich nicht mit Öl, sondern sei wie ein Weib, das geraume Zeit um einen Toten trauert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Geh zum König und sprich zu ihm dies!\" Nun legte ihr Joab die Worte in den Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Das Weib von Tekoa kam zum König, warf sich auf ihr Antlitz, huldigte und sprach: \"Hilf, König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Da sprach der König zu ihr: \"Was ist dir?\" Sie sprach: \"Leider bin ich eine Witwe, starb doch mein Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Deine Sklavin hatte zwei Söhne. Aber sie stritten miteinander auf dem Felde, und niemand schlichtete zwischen ihnen. So schlug der eine den anderen und tötete ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Nun erhebt sich die ganze Sippe gegen deine Sklavin und ruft: \'Gib den Brudermörder heraus, daß wir ihn töten für das Leben seines Bruders, den er erschlagen hat. Wir wollen so zugleich den Erben beseitigen.\' So wollen sie meine letzte Kohle löschen und meinem Manne nicht Namen noch Nachkommen auf Erden lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Da sprach der König zum Weibe: \"Geh heim! Ich werde deinetwegen verfügen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Da sprach das Weib von Tekoa zum König: \"Mich, Herr und König, träfe das Unrecht, und meine Familie. Der König und sein Thron aber bleiben unangetastet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Da sprach der König: \"Wenn jemand so zu dir spricht, dann melde mir ihn! Er soll dich nicht mehr antasten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Sie sprach: \"Möchte doch der König an den Herrn, seinen Gott, denken - sonst könnte der Bluträcher zuviel verderben -, daß sie nicht meinen Sohn umbringen!\" Da sprach er: \"So wahr der Herr lebt! Nicht ein Haar deines Sohnes soll zu Boden fallen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Da sprach das Weib: \"Dürfte doch deine Sklavin an meinen Herrn und König ein Wort richten!\" Er sprach: \"Sprich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Da sprach das Weib: \"Warum sinnst du Ähnliches gegen Gottes Volk? Aus dieser Rede des Königs geht hervor, daß es an Sünde grenzt, wenn der König seinen Verbannten nicht zurückruft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Sterben wir, so werden wir wie Wasser, das, auf den Boden geschüttet, nicht mehr gesammelt werden kann. Aber Gott nimmt nicht das Leben weg, sondern faßt Pläne, damit ein Verbannter nicht zu unserem Schaden verbannt bleibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Daß ich jetzt gekommen bin, dies dem König, meinem Herrn, zu sagen, das kommt davon, daß mir das Volk Angst gemacht hat. Deine Sklavin aber sagte: \'Ich will doch mit dem König reden. Vielleicht tut der König, was seine Magd sagt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Weil der König die Bitte gewährt, seine Magd aus der Hand des Mannes zu retten, der mich und meinen Sohn zugleich aus Gottes Erbe zu tilgen sucht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'So dachte deine Sklavin: \'Möchte doch das Wort meines Herrn und Königs zur Beruhigung dienen!\' Denn wie ein Gottesengel ist mein Herr und König, wenn er Gutes und Böses anhört. Der Herr, dein Gott, sei mit dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Da hob der König an und sprach zu dem Weibe: \"Verhehle mir nichts von dem, was ich dich frage!\" Da sprach das Weib: \"Es spreche doch mein Herr und König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Da sprach der König:\"Hat Joab dir bei alldem geholfen?\" Da hob das Weib an und sprach: \"So wahr du lebst, mein Herr und König! Unmöglich ist es, rechts oder links vorbeizukommen an irgend etwas, was mein Herr und König spricht. Ja, dein Diener Joab selbst hat mir den Auftrag gegeben. Er hat deiner Sklavin alle jene Worte in den Mund gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Um der Sache ein anderes Gesicht zu geben, hat dein Diener Joab dies getan. Aber mein Herr ist weise wie ein Gottesengel; er weiß alles, was im Lande vorgeht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Da sprach der König zu Joab: \"Das hast du getan. So geh und hole den Jüngling Absalom!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Da warf sich Joab auf sein Antlitz zur Erde, huldigte und segnete den König. Dann sprach Joab: \"Heute erfährt dein Sklave, daß ich Huld gefunden in deinen Augen, mein Herr und König, weil der König das Wort seines Sklaven erfüllt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Dann stand Joab auf, ging nach Gesur und brachte Absalom nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Der König aber sprach: \"Er gehe in sein Haus! Mein Antlitz darf er nicht sehen!\" So ging Absalom in sein Haus. Aber des Königs Antlitz sah er nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'So schön aber wie Absalom war in ganz Israel kein Mann, so daß man ihn sehr rühmte. Von der Fußsohle bis zum Scheitel war kein Makel an ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Und wenn er sein Haupt schor, und er schor es von Zeit zu Zeit - weil es ihm beschwerlich ward, schor er es -, so wog das ganze Haar seines Hauptes zweihundert Ringe nach königlichem Gewicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Absalom aber wurden drei Söhne und eine Tochter, namens Tamar, geboren. Diese ward ein schönes Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Da saß Absalom zu Jerusalem zwei Jahre. Des Königs Antlitz aber hatte er nicht gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Da sandte Absalom zu Joab, ihn zum König zu schicken; er aber wollte nicht kommen. So schickte er noch ein zweitesmal. Aber er wollte nicht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Da sprach er zu seinen Dienern: \"Seht! Joab hat ein Feld neben meinem Grundstück und hat Gerste darauf. Geht und steckt es in Brand!\" Und Absaloms Diener steckten das Feld in Brand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Da machte sich Joab auf, ging zu Absalom ins Haus und sprach zu ihm: \"Weshalb haben deine Diener mein Feld in Brand gesteckt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Da sprach Absalom zu Joab: \"Ich habe zu dir gesandt und sagen lassen: \'Komm her!\' Ich möchte dich zum König senden und sagen lassen: \'Wozu bin ich von Gesur heimgekommen? Mir wäre wohler, wäre ich noch dort.\' Nun aber möchte ich des Königs Antlitz sehen. Liegt eine Schuld auf mir, so töte er mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'So kam Joab zum König und meldete es ihm. Und er ließ Absalom rufen. So kam er zum König. Da warf er sich auf sein Antlitz zur Erde vor dem König nieder, und der König küßte Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Hernach schaffte sich Absalom Wagen und Pferde an, dazu fünfzig Mann, die vor ihm herliefen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Absalom aber pflegte sich frühmorgens neben den Torweg zu stellen. Und alle Leute, die eine Streitsache vor den König zur Entscheidung bringen wollten, rief Absalom an und fragte: \"Aus welcher Stadt bist du?\" Und sagte er: \"Dein Knecht ist von dem und dem Stamme Israels\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'dann sagte Absalom zu ihm: \"Deine Sache ist gut und recht. Aber beim König hört dich niemand an.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Dann sprach Absalom: \"Wer bestellte mich zum Richter im Lande? Zu mir dürfte jeder kommen, der einen Streit und Rechtshandel hat. Ich würde ihn nach Recht entscheiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Und trat jemand heran, ihm zu huldigen, so streckte er seine Hand aus, hielt ihn fest und küßte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Also tat Absalom jedem Israeliten, der den König um Entscheidung anging. So bestrickte Absalom das Herz der Männer Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Nach einem halben Jahre sprach Absalom zum König: \"Ich möchte verreisen und in Hebron mein Gelübde einlösen, das ich dem Herrn gelobt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Denn dein Sklave hat ein Gelübde gemacht, als ich zu Gesur in Aram weilte: \'Führt mich der Herr wirklich nach Jerusalem zurück, dann will ich dem Herrn zu Ehren ein Fest feiern.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Da sprach zu ihm der König: \"Ziehe hin in Frieden!\" Da machte er sich auf und ging nach Hebron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Absalom aber sandte geheime Boten an alle Stämme Israels und ließ sagen: \"Hört ihr Hörnerschall, dann sagt: \'Absalom ist in Hebron König geworden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Mit Absalom waren aus Jerusalem 200 Männer gezogen; sie waren eingeladen und zogen arglos mit. Sie wußten nämlich nicht das geringste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absalom rief auch den Giloniter Achitophel, Davids Ratgeber, aus seiner Stadt Gilo, als er die Opfer darbrachte. So gewann die Verschwörung Kraft, und das Volk ging hin und ward immer zahlreicher bei Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Da kam der Bote zu David mit der Meldung: \"Das Herz der Männer Israels hat sich Absalom zugewandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Da sprach David zu all seinen Dienern, die bei ihm zu Jerusalem waren: \"Auf zur Flucht! Denn für uns gibt es keine Rettung vor Absalom. Schleunigst fort! Sonst kommt er rasch uns nach und bringt über uns das Schlimmste und schlägt die Stadt mit des Schwertes Schärfe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Da sprachen des Königs Diener zum König: \"Wie der Herr und König wünscht! Wir sind deine Sklaven.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'So zog der König aus und sein ganzes Haus mit ihm. Der König aber ließ zehn Frauen zurück, das Haus zu hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'So zog der König fort und alles Kriegsvolk mit ihm. Beim letzten Haus machten sie halt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Und alle seine Diener zogen an ihm vorüber. Ebenso zogen vor dem König alle Bogenschützen und Schildträger vorüber und alle Gatiter, 600 Mann, die ihm aus Gat gefolgt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Da sprach der König zum Gatiter Ittai: \"Weshalb gehst auch du mit uns? Kehr um und bleib beim König! Du bist ja ein Ausländer und selbst aus deiner Heimat verbannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Gestern kamst du, und heute schon soll ich dich mit uns auf die Irrfahrt nehmen? Ich gehe doch, wohin ich eben gehe. Kehr um und führe deine Brüder mit dir zurück in Liebe und Treue!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Da hob Ittai an und sprach zum König: \"So wahr der Herr lebt, und so wahr mein Herr und König lebt! An dem Orte, wo mein Herr und König sein wird, ob zum Tode, ob zum Leben, dort ist auch dein Sklave.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Da sprach David zu Ittai: \"Auf! Zieh vorüber!\" Da zog der Gatiter Ittai mit all seinen Leuten und dem ganzen Troß bei ihm vorüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Die ganze Umgebung aber weinte laut auf, als alles Kriegsvolk vorüberzog. Der König zog nun in das Kidrontal, und alles Kriegsvolk zog auf den Weg zur Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Bei ihm waren auch Sadok und alle Leviten, die des Gottesbundes Lade trugen. Sie stellten die Gotteslade hin, und Ebjatar blieb stehen, bis alles Volk aus der Stadt vorübergezogen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Da sprach der König zu Sadok: \"Bringe die Gotteslade wieder in die Stadt! Finde ich in des Herrn Augen Gnade, dann führt er mich zurück und läßt mich seine Wohnstatt schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Spräche er aber so: \'Ich habe an dir kein Gefallen\', nun, dann bin ich bereit. Er tue mir, wie ihm gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Dann sprach der König zum Priester Sadok: \"Du sollst der Beobachter sein! Kehre ruhig in die Stadt zurück! Dein Sohn Achimaas und Jonatan, Ebjatars Sohn, eure beiden Söhne seien bei euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Seht! Ich warte an den Furten zur Steppe, bis ein Wort von euch kommt, mir Nachricht zu geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Da brachten Sadok und Ebjatar die Gotteslade wieder nach Jerusalem, und sie blieben dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David aber stieg den Ölberg hinan, im Gehen weinend und das Haupt verhüllt, und er ging barfuß. Auch von allem Kriegsvolk bei ihm verhüllte jeder das Haupt und stieg weinend hinan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Da meldete man David: \"Achitophel ist unter den Verschwörern bei Absalom.\" Da sprach David: \"Herr, betöre Achitophels Rat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'David kam nun auf die Spitze, wo er zu Gott betete. Da trat ihm der Arkiter Chusai entgegen, mit zerrissenem Rock und Staub auf dem Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Da sprach David zu ihm: \"Gehst du mit mir weiter, dann bist du mir zur Last.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Gehst du aber in die Stadt zurück und sagst du zu Absalom: \'Dein Sklave will ich sein, König. Ehedem war ich deines Vaters Sklave. Nun aber bin ich dein Sklave\', dann kannst du mir Achitophels Rat zunichte machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Sind nicht dort bei dir die Priester Sadok und Ebjatar? Was du aus des Königs Hause hörst, melde den Priestern Sadok und Ebjatar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Bei ihnen sind ihre beiden Söhne, Achimaas, Sadoks Sohn und Ebjatars Sohn Jonatan. Schickt durch sie an mich alles, was ihr hört!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'So kam Davids Freund Chusai in die Stadt, als Absalom einzog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'David hatte den Gipfel nur wenig überschritten. Da kam Mephibosets Diener Siba ihm entgegen mit einem Paar gesattelter Esel. Sie trugen zweihundert Brote, hundert Dörrtrauben, hundert Obstkuchen und einen Schlauch Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Da sprach der König zu Siba: \"Was willst du damit?\" Siba sprach: \"Die Esel sind für das Königshaus zum Reiten, das Brot und das Obst für die Diener zum Essen und der Wein zum Trinken für die in der Wüste Erschöpften.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Da sprach der König: \"Wo bleibt aber deines Herrn Sohn?\" Siba sprach zum König: \"Er bleibt in Jerusalem. Denn er hat gesagt: \'Heute gibt mir Israels Haus das Königtum meines Vaters zurück.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Da sprach der König zu Siba: \"Dein ist, was Mephiboset gehört.\" Siba sprach: \"Ich werfe mich nieder. Möchte ich weiter Gnade finden in deinen Augen, mein Herr, König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Der König David war nun bis Bachurim gekommen. Da trat ein Mann von der Sippe des Saulhauses hervor, Simei, Geras Sohn. Er kam fluchend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Und warf mit Steinen nach David, nach allen Dienern des Königs David, obwohl alles Kriegsvolk und alle Krieger zu seiner Rechten und Linken waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Und also schrie Simei fluchend: \"Fort! Fort, Blutmensch, Ruchloser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Der Herr bringt über dich all das Blut des Hauses Sauls, für den du König geworden bist. Der Herr gab das Königtum deinem Sohne Absalom. Nun bist du in deinem Unglück. Denn du bist ein Blutmensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Da sprach Abisai, Serujas Sohn, zum König: \"Warum soll dieser tote Hund meinem Herrn und König fluchen? Ich will hinüber und ihm den Kopf abschlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Da sprach der König: \"Was habe ich mit euch, ihr Serujasöhne, zu schaffen? Flucht er, so geschieht es, weil der Herr zu ihm gesprochen: \'Fluche David!\' Wer darf da sagen: \'Warum tust du so?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Dann sprach David zu Abisai und all seinen Dienern: \"Mein eigener, leiblicher Sohn stellt mir nach dem Leben. Um wieviel leichter dieser Benjaminite? Laßt ihn! Mag er fluchen. Denn der Herr heißt es ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Vielleicht sieht der Herr mein Elend. Dann gibt mir der Herr wieder Glück an Stelle der Verfluchung von heute.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'So zog David mit seinen Leuten des Wegs. Simei aber ging an der Bergseite neben ihm und fluchte im Gehen, warf Steine nach ihm und wirbelte Staub auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Der König und das ganze Volk bei ihm kamen zur Furt. Und dort erholte er sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom aber und das ganze Kriegsvolk, Israels Mannen, waren nach Jerusalem gekommen. Auch Achitophel war bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Da kam der Arkiter Chusai, Davids Freund, zu Absalom. Und Chusai sprach zu Absalom: \"Es lebe der König! Es lebe der König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Da sprach Absalom zu Chusai: \"Ist das deine Liebe zu deinem Freunde? Warum bist du nicht mit deinem Freunde gegangen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Da sprach Chusai zu Absalom: \"Nein! Nur für den bin ich und bei dem bleibe ich, den der Herr erwählt und dies Volk und alle Mannen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Zweitens: Wem sollte ich dienen? Nicht seinem Sohne? Wie ich deinem Vater gedient, so diene ich auch dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Da sprach Absalom zu Achitophel: \"Gebt mir euren Rat, was wir tun sollen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Da sprach Achitophel zu Absalom: \"Geh zu deines Vaters Nebenweibern, die er dagelassen, das Haus zu bewachen! Dann hört ganz Israel, daß du dich bei deinem Vater in Verruf gebracht hast, und alle deine Anhänger werden ermutigt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'So schlug man für Absalom auf dem Dache das Zelt auf. Und Absalom ging zu seines Vaters Nebenweibern vor ganz Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Achitophels Rat aber, den er gab, galt damals, wie wenn jemand Gottes Wort befragt hätte. So galt jeder Rat Achitophels, wie bei David, so bei Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Da sprach Achitophel zu Absalom. \"Ich möchte 1');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, '000 Mann ausheben, mich aufmachen und noch in der Nacht David nachsetzen. 2 Ich möchte ihn überfallen, solange er matt und mutlos ist. So würde ich ihn erschrecken, und alles Volk bei ihm würde fliehen. So könnte ich den König allein schlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Dann brächte ich alles Volk zu dir zurück; und wenn all die Männer, nach denen du Verlangen trägst, zurückkehren, dann ist das ganze Volk befriedigt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Und die Rede gefiel Absalom und allen Ältesten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Da sprach Absalom: \"Ruf mir auch den Arkiter Chusai, daß wir hören, was auch er zu sagen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'So kam Chusai zu Absalom. Da sprach Absalom zu ihm: \"Solches hat Achitophel gesprochen. Sollen wir sein Wort ausführen? Wenn nicht, so rede du!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Da sprach Chusai zu Absalom: \"Diesmal ist der Rat, den Achitophel gibt, nicht gut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Und Chusai sagte: \"Du kennst deinen Vater und seine Leute, daß sie Helden sind und grimmen Mutes, wie eine der Jungen beraubte Bärin auf dem Feld. Dazu ist dein Vater ein Kriegsmann, der mit dem Kriegsvolk keine Nachtruhe hält.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Gewiß ist er jetzt in irgendeiner Schlucht oder an irgendeiner Stelle versteckt. Fallen nun anfangs einige von euch, und hört man es, dann sagt man: \'Eine Niederlage ist unter dem Volk entstanden, das Absalom anhängt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Dann zagt selbst der Tapfere, der sonst ein Löwenherz ist. Denn ganz Israel weiß, daß dein Vater ein Held ist und seine Begleiter tapfere Mannen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'So rate ich dir: Erst sammle sich ganz Israel von Dan bis Beerseba um dich, wie der Sand am Meer an Menge! Dann zieh du selber in den Kampf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Stoßen wir dann auf ihn an einem Platze, wo er sich treffen läßt, dann stürzen wir uns auf ihn, wie der Tau auf den Boden fällt. Von ihm und allen Männern bei ihm bleibt auch nicht einer übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Zöge er sich in eine Stadt zurück, so schleppte ganz Israel zu jener Stadt Stricke, und wir schleiften sie ins Tal, bis auch nicht ein Steinchen mehr sich dort fände.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Da sprachen Absalom und alle Männer Israels: \"Des Arkiters Chusai Rat ist besser als der des Achitophel.\" Der Herr aber hatte es angeordnet, daß Achitophels guter Rat zunichte würde, damit der Herr über Absalom das Unheil bringen konnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Chusai aber sprach zu den Priestern Sadok und Ebjatar: \"So und so hat Achitophel dem Absalom geraten und den Ältesten Israels. Das und das aber habe ich geraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Nun schickt eilends hin und meldet David: \'Übernachte nicht bei den Furten zur Steppe! Mögest du übersetzen, damit nicht dem König und dem ganzen Volk bei ihm Verderben werde!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonatan aber und Achimaas hielten sich am Walkerbrunnen auf. Eine Magd aber war hingegangen und hatte es ihnen gemeldet. Da gingen sie und meldeten es dem König David; denn sie durften sich nicht in der Stadt sehen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Ein Knabe aber sah sie und meldete es Absalom. Die beiden aber liefen eilig weiter und kamen in Bachurim zum Hause eines Mannes; der hatte in seinem Hof einen Brunnen. Da stiegen sie hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Das Weib aber nahm eine Decke, breitete sie über den Brunnen und streute Schrotkorn darüber, daß man nichts merkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Da kamen Absaloms Diener zu dem Weib ins Haus und fragten: \"Wo sind Achimaas und Jonatan?\" Da sprach das Weib zu ihnen: \"Sie sind zum Wasserbächlein gegangen.\" Da suchten sie, fanden aber nichts. So kehrten sie nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Nach ihrem Weggang stiegen sie aus dem Brunnen und gingen weiter. Dann berichteten sie dem König David. Sie sprachen zu David: \"Auf! Setzt eilends über das Gewässer! Denn so und so hat Achitophel gegen euch geraten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Da machte sich David auf und alles Volk bei ihm, und sie überschritten den Jordan. Bis der Morgen tagte, fehlte nicht ein einziger, der nicht den Jordan überschritten hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Als Achitophel sah, daß sein Rat nicht befolgt wurde, sattelte er den Esel, machte sich auf und ging nach Hause in seine Stadt. Er bestellte sein Haus und erhängte sich. So starb er und ward in seinem väterlichen Grabe bestattet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David aber war nach Machanaim gekommen. Da überschritt Absalom den Jordan, er und alle Mannen Israels mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Absalom aber hatte Amasa an Joabs Stelle über das Heer gesetzt. Amasa war der Sohn eines Israeliten namens Itra, der des Nachas Tochter Abigal, Serujas Schwester und Joabs Mutter, geheiratet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Israel aber und Absalom lagerten im Lande Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Als David nach Machanaim kam, brachten Sobi, des Nachas Sohn, aus dem ammonitischen Rabbat, Ammiels Sohn Makir aus Lodebar und der Gileadite Barzillai aus Rogelim');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Bündel, Schalen, Töpfergeschirr, Weizen, Gerste, Mehl, geröstetes Korn, Bohnen, Linsen und Röstkorn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Honig, Sahne, Schafe und Kuhkäse. Sie reichten es David und dem Volke bei ihm zum Essen. Denn sie hatten gesagt: \"Das Volk ist in der Steppe hungrig, matt und durstig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David musterte nun das Volk bei ihm und stellte an seine Spitze Anführer über Tausend und über Hundert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Dann stellte David das eine Drittel des Volkes unter Joabs Befehl, ein Drittel unter den Befehl des Serujasohnes Abisai, des Bruders Joabs, und ein Drittel unter den Gatiter Ittai. Und David sprach zum Volke: \"Auch ich rücke mit euch aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Da sprach das Volk: \"Du darfst nicht ausrücken. Denn, fliehen wir, so grämt man sich nicht um uns. Fiele von uns auch die Hälfte, so grämte man sich nicht um uns. Du aber bist soviel wie von uns zehn Tausendschaften. Auch ist es besser, wenn du uns von der Stadt Hilfe bringen kannst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Da sprach der König zu ihnen: \"Ich tue, was euch gut dünkt.\" Dann stellte sich der König neben das Tor, und das ganze Volk rückte aus, nach Hunderten und Tausenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Da gebot der König Joab, Abisai und Ittai: \"Seid mir milde mit Absalom, dem jungen Manne!\" Alles Volk hörte, was der König allen Heerführern Absaloms halber gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'So zog das Volk gegen Israel ins Feld, und die Schlacht war im Walde von Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Da ward dort das Volk Israel von Davids Dienern geschlagen, und dort kam es zu einer schweren Niederlage von 20.000 Mann an jenem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Der Kampf aber dehnte sich dort über die ganze Gegend, und der Wald fraß mehr Volk, als das Schwert an jenem Tage gefressen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Absalom aber ward von Davids Dienern angetroffen. Absalom ritt nämlich ein Maultier, und das Maultier kam unter das Geäst einer großen Eiche. Da blieb sein Kopf an der Eiche hängen. Und so schwebte er zwischen Himmel und Erde. Das Maultier aber ging unter ihm durch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Das sah ein Mann und meldete es Joab und sprach: \"Ich habe Absalom an einer Eiche hängen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Da sprach Joab zu dem Mann, der ihm dies meldete: \"Du hast es gesehen? Warum hast du ihn dort nicht niedergeschlagen? An mir wäre es dann, dir zehn Silberlinge und einen Gurt zu geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Da sprach der Mann zu Joab: \"Und wenn ich ein volles Tausend Silberlinge auf der Hand hätte, so werde ich doch nicht den Königssohn antasten. Denn der König befahl dir, Abisai und Ittai, vor unseren Ohren also: \'Habt mir acht auf den jungen Mann Absalom!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Oder sollte ich mit Gefahr meines Lebens Ungehorsam üben - dem König bleibt ja nichts verborgen -, du selbst trätest beiseite.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Da sprach Joab: \"Mitnichten! Ich würde dich verteidigen.\" Da nahm er einen Dreizack in die Hand und stieß ihn Absalom ins Herz. Noch lebte er inmitten der Eiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Da traten zehn Diener herzu, Joabs Waffenträger, und schlugen Absalom vollends tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Dann stieß Joab in das Horn, und das Volk ließ von der Verfolgung Israels. Denn Joab schonte das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Dann nahmen sie Absalom, warfen ihn im Wald in eine große Grube und türmten einen mächtigen Steinwall über ihn. Ganz Israel aber war geflohen, jeder in sein Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom aber hatte schon bei Lebzeiten ein Steinmal geholt und es im Königstal aufgestellt. Denn er hatte gesagt: \"Ich habe keinen Sohn, um meinen Namen im Andenken zu erhalten.\" So nannte er das Steinmal nach seinem Namen. Daher heißt es \"Absaloms Denkmal\" bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Sadoks Sohn Achimaas aber sprach: \"Ich könnte hinlaufen und dem König Botschaft bringen, daß der Herr ihm gegen seine Feinde geholfen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Da sprach Joab zu ihm: \"Du bist heute nicht der Mann für solche Botschaft. Ein andermal bring Botschaft! Aber am heutigen Tag darfst du keine bringen, da doch des Königs Sohn tot ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Dann sprach Joab zu dem Kuschiten: \"Geh und melde dem König, was du gesehen!\" Da verneigte sich der Kuschite vor Joab und lief weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Da redete Sadoks Sohn Achimaas nochmals Joab an: \"Mag kommen, was will, ich möchte doch gern dem Kuschiten nachlaufen.\" Da sprach Joab: \"Warum willst du, mein Sohn, laufen? Für dich gibt\'s keinen Botenlohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Er sprach: \"Mag kommen, was will, ich laufe hin.\" Da sagte er zu ihm: \"Lauf!\" Da lief Achimaas den Weg durch die Aue und überholte den Kuschiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David aber saß eben im Doppeltor. Und der Wächter stieg auf das Tordach an der Mauer. Als er seine Augen erhob, sah er einen Mann allein daherlaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Da rief der Wächter und meldete es dem König. Da sprach der König: \"Ist er allein, dann bringt er gute Botschaft.\" Jener aber lief und kam immer näher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Da sah der Wächter einen zweiten Mann laufen. Dies rief der Wächter dem Torwart zu und sprach: \"Noch ein Mann läuft daher.\" Der König sprach: \"Auch er bringt gute Botschaft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Da sprach der Wächter: \"Soviel ich sehe, gleicht des ersten Gangart der des Sadoksohnes Achimaas.\" Da sprach der König: \"Das ist ein wackerer Mann. Er kommt mit froher Botschaft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Da rief Achimaas und sprach zum König: \"Heil!\" Dann warf er sich vor dem König mit dem Angesicht zu Boden und sprach: \"Gepriesen sei der Herr, dein Gott, der die Männer preisgegeben, die ihre Hand gegen meinen Herrn, den König, erhoben haben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Der König fragte:\"Ist heil der junge Mann Absalom?\" Achimaas sagte: \"Ich habe wildes Getümmel gesehen, als des Königs Diener Joab schon deinen Sklaven absandte, aber ich weiß nicht, was es gegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Da sprach der König: \"Tritt beiseite und stell dich hierher!\" Er trat beiseite und stand da,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'als der Kuschite kam. Und der Kuschite sprach: \"Mein Herr, der König, lasse sich gute Kunde melden! Denn der Herr hat dir heute geholfen gegen alle, die sich gegen dich empört haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Da fragte der König den Kuschiten: \"Ist heil der junge Mann Absalom?\" Da sprach der Kuschite: \"Mögen dem jungen Manne im Unglück gleich werden die Feinde meines Herrn, des Königs, und alle, die sich gegen dich erhoben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Da erbebte der König, ging in des Tores Obergemach und weinte. Im Gehen rief er: \"Mein Sohn Absalom! Mein Sohn! Mein Sohn Absalom! Wäre ich an deiner Statt gestorben! Absalom, mein Sohn! Mein Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Da ward es Joab gemeldet: \"Der König weint und trauert um Absalom.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Da ward der Sieg an jenem Tage zur Trauer für das ganze Volk, weil das Volk an jenem Tage hörte: \"Der König grämt sich um seinen Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Und das Volk stahl sich an jenem Tage in die Stadt, wie sich das Volk hereinstiehlt, wenn es durch Flucht aus der Schlacht mit Schimpf bedeckt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Der König aber hatte sich das Gesicht verhüllt. Und der König schrie laut auf: \"Mein Sohn Absalom! Absalom, mein Sohn! Mein Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Da ging Joab zum König und sprach: \"Du benimmst dich heute schändlich vor deinen Dienern, die heute dir, deinen Söhnen und Töchtern, deinen Weibern und Nebenweibern das Leben gerettet haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Du liebst deine Hasser und hassest deine Freunde. Denn du zeigst heute, daß Fürsten und Diener dir nichts sind. Heute bin ich überzeugt: Wäre Absalom am Leben und wir wären heute alle tot, dir wäre es ganz recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Nun aber auf! Tritt hinaus und sprich freundlich zu deinen Dienern! Denn ich schwöre beim Herrn: Gehst du nicht hinaus, dann bleibt kein Mann diese Nacht bei dir. Und das wäre für dich ein Unglück, schlimmer als alles, was über dich von deiner Jugend bis jetzt gekommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Da erhob sich der König und setzte sich an das Tor. Dem Kriegsvolke aber war gemeldet worden: \"Der König sitzt im Tor.\" Da kam alles Volk vor den König, Israel aber floh, jeder in seine Zelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Das ganze Volk aber lag in Hader. In allen Städten Israels hieß es: \"Der König hat uns aus der Philister Hand gerettet. Nun aber ist er aus dem Lande vor Absalom geflohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Absalom aber, den wir uns gesalbt, ist im Kampfe gefallen. Nun denn! Was zögert ihr, den König zurückzuführen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Da sandte der König David zu den Priestern Sadok und Ebjatar und ließ sagen: \"Sagt den Ältesten Judas: \'Warum wollt ihr hintan sein, den König in sein Haus zurückzuführen?\'\" Das Gerede von ganz Israel war nämlich schon zum König in sein Haus gedrungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, '\"\'Ihr seid meine Brüder, ihr mein Fleisch und Bein. Warum wollt ihr hintan sein, den König zurückzuführen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Und zu Amasa sollt ihr sagen: \'Bist du nicht mein Fleisch und Bein? So und so tue mir Gott, wenn du nicht bei mir fein alle Zeiten Oberfeldherr wirst an Joabs Stelle!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Da wandte sich der Sinn der judäischen Mannschaft insgesamt, daß sie einmütig zum König sandten: \"Kehre mit all deinen Dienern zurück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Der König kehrte nun zurück und kam an den Jordan. Juda aber kam nach dem Gilgal, dem König entgegen, um den König über den Jordan zu fahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Da eilte der Benjaminite Simei, Geras Sohn, aus Bachurim herbei und zog mit Judas Mannschaft hinab, dem König David entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Bei ihm waren tausend Mann aus Benjamin. Auch Siba, der Diener des Hauses Saul, hatte mit seinen fünfzehn Söhnen und zwanzig Sklaven den Jordan im Angesichte des Königs durchwatet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Und das Fährboot fuhr hinüber, um das Königshaus überzuführen und zu tun, was ihm gefiele. Da warf sich Geras Sohn Simei vor dem König nieder, als er über den Jordan gefahren war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Und er sprach zum König: \"Möge mein Herr mir keine Schuld mehr anrechnen und nicht dessen gedenken, was dein Sklave an jenem Tage verbrochen hat, da mein Herr, der König, aus Jerusalem gezogen, daß es sich der König zu Herzen nähme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Dein Knecht weiß, daß ich mich vergangen habe. Aber ich komme heute als erster vom ganzen Josephshause meinem Herrn, dem König, entgegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Da hub Serujas Sohn Abasai an und sprach: \"Sollte dafür Simei nicht den Tod leiden? Er hat dem Gesalbten des Herrn geflucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Da sprach David: \"Was habe ich mit euch, ihr Serujasöhne, zu tun, daß ihr mir heute zum Versucher werdet? Sollte heute jemand in Israel getötet werden? Weiß ich denn nicht, daß ich jetzt erst König über Israel bin?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Und der König sprach zu Simei: \"Du sollst nicht sterben!\" Und der König schwur es ihm zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Auch Sauls Enkel Mephiboset ging dem König entgegen. Er hatte aber sein Haupthaar nicht gepflegt noch seinen Bart geordnet und seine Kleider nicht gewaschen seit dem Tage, da der König fortgegangen, bis zu dem Tage, da er im Frieden nach Jerusalem zog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Als er dem König, Jerusalem zu, begegnete, fragte ihn der König: \"Warum bist du nicht mit mir gegangen, Mephiboset?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Er sprach: \"Mein Herr und König! Mich hat mein Diener betrogen. Denn dein Sklave hatte gesagt: \'Ich will mir den Esel satteln, daß ich auf ihm reite und mit dem König ziehe.\' Dein Sklave ist ja lahm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Er aber verleumdete deinen Sklaven bei meinem Herrn, dem König. Aber mein Herr, der König, gleicht einem Engel Gottes. Tu, was dir beliebt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Mein ganzes Vaterhaus ist ja bei meinem Herrn, dem König, dem Tode verfallen, du aber setztest deinen Sklaven unter deine Tischgäste. Was für ein Recht hätte ich noch, mich beim König zu beklagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Da sprach der König zu ihm: \"Warum machst du soviel Worte? Ich sage: Du und Siba sollt das Landgut teilen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Da sprach Mephiboset zum König: \"Er behalte sogar das Ganze, wenn mein Herr, der König, heil in sein Haus einzieht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Auch der Gileadite Barzillai war von weither gekommen; auch er setzte mit dem König über den Jordan, ihn über den Jordan zu begleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Barzillai aber war sehr alt, ein Achtzigjähriger. Er hatte den König bei seinem Aufenthalt zu Machanaim versorgt. Denn er war ein sehr vermöglicher Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Da sprach der König zu Barzillai: \"Geh du mit mir hinüber, und ich sorge für dich bei mir zu Jerusalem!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Da sprach Barzillai zum König: \"Wieviel sind die Tage meiner Lebensjahre, daß ich mit dem König nach Jerusalem zöge?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Achtzig Jahre bin ich jetzt alt. Kann ich da noch Gutes und Schlechtes unterscheiden? Schmeckt deinem Sklaven, was ich esse und trinke? Höre ich noch die Stimme der Sänger und Sängerinnen? Wozu fiele dein Sklave meinem Herrn, dem König, noch zur Last?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Kaum kann dein Sklave den König über den Jordan begleiten. Aber warum vergilt mir der König also?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Dein Sklave möchte lieber umkehren, daß ich in meiner Stadt bei meines Vaters und meiner Mutter Grab stürbe! Aber dein Sklave Kimham möchte mit meinem Herrn, dem König, hinüberziehen! Tu ihm, was dir gut dünkt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Da sprach der König: \"So ziehe Kimham mit mir hinüber! Ich tue ihm, was dir gefällt; aber auch alles, was du von mir wünschst, werde ich dir tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Nun setzte alles Volk über den Jordan. Auch der König setzte über. Da küßte der König den Barzillai und segnete ihn. Und er kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Dann zog der König nach dem Gilgal; auch Kimham zog mit ihm. So führte der ganze judäische Heerbann den König hinüber, ebenso die Hälfte des Volkes Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Dann kam der ganze israelitische Heerbann zum König. Und sie sprachen zum König: \"Warum haben dich unsere Brüder entführt, Judas Heerbann? Sie brachten den König samt seinem Hause und alle Mannen Davids bei ihm über den Jordan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Da erwiderten alle Mannen Judas der Mannschaft Israels: \"Der König ist mit uns verwandt. Warum bist du deshalb zornig? Haben wir auf des Königs Kosten gespeist? Hat man uns aufgetragen?\" Da hob Israels Mannschaft an und sprach zu der Mannschaft Judas: \"Ich habe am König zehn Teile, und auch an David bin ich dir voraus. Weshalb achtest du mich gering? Und stand es nicht mir zuerst zu, meinen König zurückzuführen?\" Aber die Rede der Mannschaft Judas war durchschlagender als die der Mannschaft Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Dort aber war zufällig ein nichtswürdiger Mann namens Seba, Bikris Sohn, ein Benjaminite. Er stieß in das Horn und rief: \"Wir haben an David keinen Teil und keinen Anteil an dem Isaisohne. Israel, ein jeglicher zu seinen Zelten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Da fiel Israels gesamte Mannschaft von David zum Bikrisohne Seba ab. Judas Mannschaft aber scharte sich um ihren König vom Jordan bis Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'So kam David in sein Haus zu Jerusalem. Da nahm der König die zehn Nebenweiber, die er zur Bewachung des Hauses dagelassen hatte und brachte sie in ein besonderes Haus und versorgte sie. Er aber kam nicht mehr zu ihnen. So lebten sie bis zu ihrem Todestage abgeschlossen als lebenslängliche Witwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Dann sprach der König zu Amasa: \"Entbiete mir Judas Mannschaft in drei Tagen! Du selbst stelle dich hier ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Da ging Amasa, Juda aufzubieten. Er verzog sich aber über die Frist, die er ihm gesetzt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Da sprach David zu Abisai: \"Nun wird Seba für uns noch schlimmer als Absalom. Nimm jetzt deines Herrn Diener und setze ihm nach, daß er nicht feste Städte gewinne und unsere Quellen wegnehme!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'So zogen hinter ihm Joabs Leute einher, ebenso die Bogenschützen und die Schildträger und alle anderen Krieger. Sie zogen aus Jerusalem, den Bikrisohn Seba zu verfolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Sie waren eben bei dem großen Stein in Gibeon. Da ging Amasa ihnen voraus. Joab aber war mit einem langen Gewande angetan, und darin war ein Schwert, das mit der Scheide an seine Hüfte geknüpft war. Er zog es heraus, verbarg es aber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Da fragte Joab Amasa: \"Geht es dir gut, mein Bruder?\" Dabei faßte Joab mit der Rechten Amasa am Bart, ihn zu küssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa aber beachtete nicht das Schwert in Joabs Hand. Und so stieß er ihn damit in den Leib. Da ließ er seine Eingeweide auf den Boden fallen. Jener aber brauchte ihm keinen zweiten Stoß zu geben. Er starb. Joab aber und sein Bruder Abisai setzten Bikris Sohne Seba weiter nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Einer von Joabs Knechten aber war zu ihm getreten und sprach: \"Wer es mit Joab und David hält, folge Joab!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa aber wälzte sich im Blute mitten auf der Straße. Als die Mannschaft sah, wie alles Volk stehenblieb, schob sie Amasa von der Straße auf das Feld und warf auch einen Mantel über ihn; denn sie sah, daß jeder, der an ihm vorüberkam, stehenblieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Als sie ihn von der Straße weggeschafft hatten, folgte jedermann Joab, um Seba, den Bikrisohn, zu verfolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Und er durchzog alle Stämme Israels bis Abel Beth Maaka. Und alle Banden sammelten sich und folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'So kamen sie, belagerten ihn zu Abel Beth Maaka und schütteten gegen die Stadt einen Wall auf, der auf den Festungsgraben kam. Und das ganze Volk bei Joab unterwühlte die Mauer, um sie zu stürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Da rief ein weises Weib aus der Stadt: \"Hört! Hört! Sagt doch Joab: \'Komm hierher! Ich möchte dich sprechen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Und er näherte sich ihr. Da fragte das Weib: \"Bist du Joab?\" Er sagte: \"Ja!\" Da sprach sie zu ihm: \"Höre deiner Sklavin Worte!\" Er sprach: \"Ich höre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Sie sprach dann also: \"Man pflegte in alter Zeit zusagen: \'Man frage über Abel nach\', dann sagt man also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, '\'Ich bin die Friedfertigste und Getreueste in Israel.\' Du aber suchst eine Mutterstadt in Israel zu vernichten. Weshalb vernichtest du des Herrn Eigentum?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Da hub Joab an und sprach: \"Ferne, ferne sei dies von mir! Ich will nichts verderben und nichts vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Nicht so ist es, sondern ein Mann vorn Gebirge Ephraim, namens Seba, Bikris Sohn, hat seine Hand gegen den König David erhoben. Ihn allein liefert aus, dann ziehe ich von der Stadt ab.\" Da sprach das Weib zu Joab: \"Sein Kopf soll dir über die Mauer zugeworfen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Das Weib kam nun mit seiner Klugheit zum ganzen Volk. Da hieben sie Bikris Sohn Seba den Kopf ab und warfen ihn Joab zu. Da stieß er in das Horn, und sie lösten sich auf und zogen von der Stadt weg, jeder zu seinen Zelten, Joab aber zog heim zum König nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab blieb nun Befehlshaber über das ganze Heer Israels, Benaja, Jojadas Sohn, aber über die Bogenschützen und Schildträger');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'und Adoram über den Frondienst. Josaphat, Achiluds Sohn, war Kanzler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja war Schreiber, Sadok und Ebjatar waren Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Auch der Jairite Ira war bei David Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'In Davids Tagen war drei Jahre lang, Jahr für Jahr, eine Hungersnot. Da suchte David das Antlitz des Herrn. Der Herr aber sprach: \"Auf Saul und seinem Haus ruht eine Blutschuld, weil er die Gibeoniten getötet hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Da berief der König die Gibeoniten und sprach zu ihnen. (Die Gibeoniten aber gehörten nicht zu den Söhnen Israels, sondern zu dem Reste der Amoriter. Doch die Söhne Israels hatten sich ihnen eidlich verpflichtet. Saul aber suchte in seinem Eifer für die Söhne Israels und Juda sie auszurotten.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Da sprach David zu den Gibeoniten: \"Was soll ich für euch tun? Womit Sühne schaffen? Segnet doch des Herrn Eigentum!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Da sprachen die Gibeoniten zu ihm: \"Wir wollen kein Silber und Gold von Saul und seinem Hause. Auch im übrigen Israel gibt es keinen Mann, dessen Tod wir fordern.\" Da sprach er: \"Was ihr sagt, tue ich für euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Da sprachen sie zum König: \"Der Mann, der uns aufgerieben und auf unsere Vernichtung gesonnen, daß wir im ganzen Bereich Israels nicht mehr bestünden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'aus seinen Söhnen soll man uns sieben Männer geben, daß wir sie dem Herrn aussetzen zu Gibea Sauls, des vom Herrn Erwählten!\" Da sprach der König: \"Ich gebe Sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Der König aber verschonte Mephiboset, den Sohn des Saulssohnes Jonatan, wegen des Herrnschwures, der zwischen David und Sauls Sohn Jonatan bestand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'So nahm der König der Rispa, Ajas Tochter, beide Söhne, die sie Saul geboren hatte, Armoni und Mephiboset, sowie der Merab, Sauls Tochter, fünf Söhne, die sie dem Mecholatiter Adriel, Barzillais Sohn, geboren hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Diese gab er den Gibeoniten. Und sie setzten sie auf dem Berge vor dem Herrn aus. So kamen die Sieben zusammen um. Und zwar starben sie in den Tagen der Gerstenernte, in den ersten Tagen, zu Beginn der Gerstenernte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Da nahm Ajas Tochter Rispa das Trauergewand und breitete es sich auf den Felsen, vom Beginn der Gerstenernte, bis Wasser vom Himmel auf sie floß. So hatte sie es verhütet, daß des Himmels Vögel bei Tag und des Feldes Tiere bei Nacht über sie herfielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Da ward David gemeldet, was Rispa, Ajas Tochter und Sauls Nebenweib, getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Da ging David hin und holte die Gebeine Sauls und die seines Sohnes Jonatan von den Bürgern in Jabes Gilead. Sie hatten sie vom Marktplatz in Betsean entführt, wo sie die Philister aufgehängt hatten an jenem Tage, als sie Saul am Gilboa schlugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'So brachte er Sauls und seines Sohnes Jonatan Gebeine von dort weg. Dann sammelte man die Gebeine der Ausgesetzten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'und begrub sie mit Sauls und seines Sohnes Jonatan Gebeinen im Lande Benjamin zu Sela im Grabe seines Vaters Kis. So tat man alles, was der König befohlen hatte, und Gott ward danach dem Lande hold gestimmt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Da war wieder Krieg zwischen den Philistern und Israel. David zog mit seinen Dienern hinab, und sie kämpften mit den Philistern. David aber ward müde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Da nahm ihn Benob gefangen. Dieser gehörte zu den Kindern des Akis, und sein Speer wog 300 Sekel Erz; er hatte erst jüngst den Gurt angelegt. Und schon dachte er daran, David zu erschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Da kam ihm Serujas Sohn Abisai zu Hilfe. Und er schlug den Philister tot. Damals beschworen Davids Leute ihn: \"Du darfst nicht mehr mit uns in den Kampf ziehen, daß du nicht Israels Leuchte verlöschest!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Hernach war wieder Krieg zu Gob mit den Philistern. Damals schlug der Chusatiter Sibkai den Saph von den Kindern des Akis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Nochmals war ein Kampf mit den Philistern zu Gob. Da schlug Jairs Sohn Elchanan, ein Weber aus Bethlehem, den Gatiter Goliat, dessen Speerschaft einem Weberbaume glich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Nochmals war ein Kampf bei Gat. Da war ein Kriegsmann, der je sechs Finger an den Händen und je sechs Zehen an den Füßen hatte, zusammen vierundzwanzig, und der ebenfalls von Akis stammte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Er höhnte Israel. Da schlug ihn Jonatan, der Sohn Simis, des Bruders Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Diese Vier stammten von Akis zu Gat ab, und sie fielen durch Davids und seiner Diener Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'David dichtete für den Herrn die Worte dieses Liedes, zu der Zeit, da ihn der Herr aus der Hand aller seiner Feinde und besonders aus der des Saul befreite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Er sprach: \"Ein Fels ist mir der Herr und eine Rettungsburg,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'mein Gott mein Hort, wo ich mich berge, mein Schild, mein sieghaft Horn und meine Feste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '\'Gepriesen sei der Herr!\' das einzig rufe ich und bin von meinen Feinden schon erlöst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Schon hatten Todesfluten mich umgeben; mich schreckten des Verderbens Ströme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Der Hölle Stricke hatten mich umschlungen; des Todes Schlingen überraschten mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Da rief ich in der Not zum Herrn und schrie zu meinem Gott um Hilfe. Er hört in seinem Tempel meine Stimme, und mein Geschrei dringt ihm zu Ohren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Die Erde schütterte und bebte; des Himmels Festen zitterten und wankten. Er war ergrimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Aufquoll aus seiner Nase Rauch; aus seinem Munde sprühte Feuer, und eine Glut ward von ihm ausgesprüht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Den Himmel neigte er und fuhr herab, tief Dunkel unter seinen Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Er fuhr auf einem Cherub, flog einher, auf Windesflügeln schwebend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Zur Hülle nahm er Dunkel rings um sich und Wasserflut und dicht Gewölk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'An seiner Nähe Glanz entzündeten sich Feuerströme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Der Herr im Himmel donnerte; der Höchste ließ die Stimme dröhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Und Pfeile schoß er ab nach allen Seiten und warf die Blitze hin in regelloser Wahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Des Meeres Betten zeigten sich; der Erde Gründe wurden bloßgelegt vor dem Gedroh des Herrn, vor seinem Zornesschnauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Herab griff er und faßte mich und zog mich aus gewaltigen Gewässern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'entriß mich meinen argen Feinden und meinen überlegnen Hassern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'die mich an meinem Unglückstage überfielen. So wurde mir der Herr zur Stütze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Er führte mich hinaus ins Freie, befreite mich, weil er an mir Gefallen fand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Der Herr vergalt mir so nach meiner Rechtlichkeit und lohnte mir nach meiner Hände Reinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Denn immer halte ich des Herren Wege und frevle nimmer gegen meinen Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'denn alle seine Rechte habe ich vor Augen und lasse seine Satzungen nicht aus dem Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Ich habe ihm mich ungeteilt ergeben und mich vor meiner Lieblingssünde wohl gehütet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Darum vergalt der Herr mir auch nach meiner Rechtlichkeit, nach meiner ihm bekannten Reinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Du bist dem Holden hold, dem Treugesinnten treugesinnt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'verfährst mit Reinen rein, doch böse mit dem Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Dem armen Volke stehst Du bei; doch auf den Stolzen senkst Du Deine Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Du bist mein Licht, Du Herr, Du Herr, mein Gott, der meine Finsternis erhellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Mit Dir erstürme ich die Wälle; und Mauern überspringe ich mit meinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Truglos ist Gottes Weg; geläutert ist das Wort des Herrn, ein Schild für alle, die zu ihm sich flüchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Denn wer ist Gott, wenn nicht der Herr? Wer sonst ein Hort als unser Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Das ist der Gott, der meine feste Zuflucht ist, der unbehindert seines Weges eilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'der gleich den Rehen meine Füße macht und mich auf meine Höhen stellt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'der meine Hände kämpfen lehrt und meine Arme eherne Bogen spannen läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Du reichst mir Deinen Siegesschild, und Deine Rechte stützet mich, und Deine Stärkung macht mich kräftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Und meinen Schritten gibst Du weiten Raum, und meine Knöchel wanken nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Ich setze meinen Feinden nach und greife sie und kehre nicht zurück, bis daß ich sie vernichtet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Ich schlage sie, daß sie sich nimmermehr erheben, und daß sie unter meinen Füßen liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Du gürtest mich mit Kraft zum Kampfe, und meine Gegner beugst Du unter mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Und meiner Feinde Rücken zeigst Du mir, daß ich vertilge meine Hasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Sie rufen - niemand hilft - zum Herrn; er hört sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Und ich zermalme sie wie Staub vorm Winde; zerstampfe sie gleich Gassenkot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du rettest mich vor Tausenden von Kriegervölkern; zum Haupt von Heiden machst Du mich; mir unbekannte Leute dienen mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Des Auslands Söhne schmeicheln mir; aufs Hörensagen leisten sie mir schon Gehorsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'und andere Fremdlinge verschwinden und sitzen zitternd in Verstecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Lebendig ist der Herr und hochgepriesen als mein Hort, und als mein hilfereicher Gott steht hoch er da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Gott, der Du mir verhilfst zur Rache und Völker mir zu Füßen legst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'der Du vor meinen Feinden mich errettest, Du machst mich fürder meinen Gegnern unerreichbar und rettest mich vor Wüterichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'dafür lobpreise ich Dich bei den Heiden, Herr, und singe also Deinem Namen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, '\'Heilvoller Turm für seinen König, der David, den er salbte, Huld erweist und seinem Stamme ewiglich.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dies sind Davids letzte Worte, ein Ausspruch des Isaisohnes David und ein Ausspruch des Mannes, der als Gesalbter des Jakobsgottes und als Sänger der Lieder Israels dastand:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Es spricht der Geist des Herrn durch mich; auf meiner Zunge ist sein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Gesprochen hat der Gott von Israel. Gesprochen hat zu mir der Fels von Israel: \'Wer über Menschen herrscht gerecht, von Gottesfurcht erfüllt, als Herrscher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'der gleicht dem Licht am Morgen, am wolkenlosen Morgen, wenn hell die Sonne strahlt, die Gräser aus dem Boden sprossen läßt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Steht also nicht mein Haus zu Gott? - Hat er doch einen ewig gültigen Bund mit mir geschlossen, der festgestellt in allem und gesichert ist. - Denn all mein Streben und mein Wünschen, läßt er\'s denn nicht gelingen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Die Frevler aber sind wie lose Dornen alle zumal nicht in die Hand zu nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Wer auf sie trifft, der schlägt mit Eisen, schlägt mit dem Lanzenschaft darein, sie werden ohne Widerstand verbrannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Das sind die Namen der Helden, die David hatte: des Chakmoni Sohn Josabam, das Haupt der Drei. Er stritt mit seinem Speere gegen 800 Unreine auf einmal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Nach ihm kommt der Achochiter Eleazar, Dodis Sohn; er war unter den drei Kriegern bei David; am Blutsteinfelsen ging er gegen die Philister los. Diese hatten sich dort zum Kampfe gesammelt. Da zog sich Israels Mannschaft zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Er aber hielt stand und hieb auf die Philister ein, bis seine Hand ermattete und seine Hand am Schwerte kleben blieb. Und der Herr schaffte an jenem Tage einen großen Sieg; das Volk zog ihm nun nach, aber nur um zu plündern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Nach ihm kommt der Harariter Samma, des Age Sohn. Einst sammelten sich die Philister in Lechi. Dort war ein Feld voller Garben. Da aber das Volk vor den Philistern floh,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Stellte er sich mitten in das Feld, rettete es und schlug die Philister, und der Herr schaffte einen großen Sieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Drei von den dreißig Hauptleuten stiegen hinab und kamen zu dem Felsen, zu David in die Höhle von Adullam. Die Philisterschar aber lagerte in der Rephaimebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David war damals in der Feste, der Philisterposten aber in Bethlehem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Da spürte David ein Gelüste und sprach: \"Wer holt mir Trinkwasser aus dem Brunnen in Bethlehem am Tor?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Da schlugen sich die drei Krieger durch das Philisterlager, schöpften aus dem Brunnen in Bethlehem am Tor und brachten es David. Aber er wollte nicht mehr trinken, sondern spendete es dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Er sprach: \"Ferne sei es mir, Herr, daß ich solches tue! Ist es doch Blut der Männer, die unter Lebensgefahr hingingen.\" Und er wollte es nicht trinken. So hatten die drei Helden getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Der Serujasohn Abisai, Joabs Bruder, war das Haupt der Dreißig. Er schwang seinen Speer gegen 300 Unreine und war bei den Dreien angesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Er wurde also von den Dreien ausgezeichnet, und so ward er bei ihnen Hauptmann. Aber an die Drei reichte er nicht heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Des Jojada Sohn Benaja war der Sohn eines richtigen, tatenreichen Mannes aus Kabseel. Er selber hatte Moabs beide Kämpen erschlagen. Auch er war hinabgestiegen und hatte den Löwen mitten im Brunnen erschlagen, als Schnee fiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Auch hatte er einen Ägypter erschlagen, einen riesigen Mann. Der Ägypter hatte einen Speer in der Hand. Er aber ging mit einem Stock auf ihn los, entriß dem Ägypter die Lanze und tötete ihn mit seinem eigenen Speer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Dies hatte Benaja, Jojadas Sohn, getan. Auch er hatte einen Namen bei den drei Helden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Unter den Dreißig hatte er sich ausgezeichnet. Aber an die Drei reichte er nicht heran. David stellte ihn bei seiner Leibwache an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Unter den Dreißig waren Joabs Bruder Asahel, ferner Dodos Sohn Elchanan aus Bethlehem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'der Charoditer Samma, der Charoditer Elika,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'der Paltiter Cheles, der Tekoiter Ira, des Ikkes Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'der Anatotiter Abiezer, der Chusatiter Mebunnai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'der Achochiter Salmon, der Netophatiter Maharai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'der Netophatiter Cheleb, Baanas Sohn Ittai aus Gibea in Benjamin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'der Piratotiter Benaja, Hiddai aus Nachale Gaas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'der Arbatiter Abialbon, der Barchumiter Azmawet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'der Saalboniter Eljachba, die Söhne Jasens, Jonatan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'der Harariter Samma, der Arariter Achiam, Sarars Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'der Maakatiter Eliphelet, Achasbais Sohn, der Giloniter Eliam, Achitophels Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'der Karmeliter Chesro, der Arbiter Paarai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal, Natans Sohn aus Soba, der Gaditer Bani,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'der Ammoniter Selek, der Beerotiter Nakarai sowie des Serujasohnes Joab Waffenträger,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'der Itriter Ira, der Itriter Gareb');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'und Urias, der Chittiter. Zusammen siebenunddreißig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Nochmals zürnte der Herr über Israel. Und so reizte er David gegen Israel durch den Befehl: \"Auf! Zähle Israel und Juda!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Da sprach der König zu Joabs Heerführern, die bei ihm waren: \"Durchwandert alle Stämme Israels von Dan bis Beerseba und zählt das Volk, daß ich die Zahl des Volkes erfahre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Da sprach Joab zum König: \"Mag der Herr, dein Gott, das Volk, wie es ist, hundertfach vermehren, und mag mein Herr, der König, dies selbst erleben! Aber warum verlangt dies mein Herr, der König?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Aber des Königs Befehl zwang Joab und die Heerführer. So gingen Joab und die Heerführer vom König weg, das Volk Israel zu zählen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Sie überschritten den Jordan und machten sich an die Arbeit in Aroër, rechts von der Stadt, im Bachtale, gegen Gad und Jazer hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'So kamen sie nach dem Gilead und in das Land unter dem Hermon. Dann kamen sie nach Dan und in Galiläas Umkreis nach Sidon zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Dann kamen sie zur Festung von Tyrus sowie zu allen Chiwiter- und Kanaaniterstädten. Dann zogen sie nach Judas Südland, nach Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'So durchstreiften sie das ganze Land und kamen nach neun Monaten und zwanzig Tagen nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Da gab Joab die Zahl aus der Volkszählung dem Könige an: \"Israel zählte 800.000 an waffenfähigen, schwertgerüsteten Mannen und Juda nach seiner Mannschaft 500.000.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'David aber schlug das Gewissen nach der Volkszählung. Und so sprach David zum Herrn: \"Ich habe schwer gesündigt durch das, was ich getan. Nun aber, Herr, vergib die Schuld Deines Sklaven. Denn ich habe töricht gehandelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Als David am Morgen aufstand, war das Wort des Herrn an den Propheten Gad, Davids Seher, also ergangen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '\"Auf! Sprich zu David: \'So spricht der Herr: Ich lege dir dreierlei vor: Eins wähle dir davon, daß ich es dir antue!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Da ging Gad zu David und verkündete es ihm. Er sprach zu ihm: \"Entweder für dich drei Jahre Hungersnot in deinem Land oder drei Monate Flucht vor deinem Feind, wenn er dich verfolgt, oder drei Tage Pest in deinem Land? Nun besinne dich und sieh zu, was ich dem bescheiden soll, der mich sendet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Da sprach David zu Gad: \"Mir ist sehr bange. Laßt uns lieber in des Herrn Hand fallen! Denn sein Erbarmen ist groß. Aber in Menschenhand möchte ich nicht fallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'So schickte der Herr eine Pest über Israel vom Morgen bis zum Vormittag. Und vom Volke starben 70.000 Mann von Dan bis Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Und der Engel des Herrn streckte seine Hand gegen Jerusalem aus, es zu vernichten. Da reute den Herrn das Unheil, und er gebot dem Engel, der unter dem Volke würgte: \"Genug! Zieh deine Hand jetzt ab!\" Des Herrn Engel war eben bei der Tenne des Jebusiters Arauna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Da sprach David zum Herrn, als er sah, wie der Engel das Volk schlug, und sagte: \"Ich habe gefehlt und gesündigt. Was aber haben die Schafe getan? Deine Hand sei doch gegen mich und mein Haus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Da kam Gad zu David an jenem Tage und sprach zu ihm: \"Geh hinauf und errichte dem Herrn einen Altar auf der Tenne des Jebusiters Arauna!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Da ging David auf Gads Geheiß hinauf, wie ihm der Herr befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Arauna schaute eben aus. Da sah er den König mit seinen Dienern auf sich zukommen. So trat Arauna hinaus und neigte sein Antlitz vor dem König bis zum Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Dann sprach Arauna: \"Warum kommt mein Herr, der König, zu seinem Sklaven?\" Da sprach David: \"Um dir die Tenne abzukaufen und dem Herrn einen Altar zu bauen, daß die Seuche vom Volke abgewehrt werde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Da sprach Arauna: \"Mein Herr, der König, wolle nehmen und opfern, was ihm beliebt! Hier sind die Rinder zum Brandopfer und die Dreschwagen und das Rindergeschirr zum Holz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Dies alles, o König, schenkt Arauna dem König.\" Ferner sprach Arauna zum König: \"Der Herr, dein Gott, sei dir geneigt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Da sprach der König zu Arauna: \"Nein! Ich will es von dir um Entgelt erwerben! Ich kann dem Herrn, meinem Gott, nicht Brandopfer ohne Entgelt darbringen.\" So kaufte David die Tenne und die Rinder für fünfzig Silberlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Und David baute dort dem Herrn einen Altar und brachte Brand- und Mahlopfer dar. Und der Herr ward dem Lande hold gestimmt. So ward die Seuche von Israel abgewehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Und König David war alt und hochbetagt. Da hüllte man ihn in warme Kleider. Er konnte aber nicht warm werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Da sprachen seine Diener zu ihm: \"Man suche für meinen Herrn, den König, ein jungfräuliches Mädchen, daß sie dem König aufwarte und ihm Pflegerin sei! Liegt sie an deinem Busen, dann wird es meinem Herrn, dem König, warm werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Da suchte man ein schönes Mädchen im ganzen Gebiete Israels. Und man fand die Sunamitin Abisag und brachte sie zum König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Das Mädchen war sehr schön. So ward sie des Königs Pflegerin und bediente ihn. Der König aber erkannte sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Da meinte Chaggits Sohn Adonias voller Überhebung: \"Ich bin es, der König wird.\" Er schaffte sich Wagen und Pferde an und fünfzig Mann, die vor ihm herliefen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Sein Vater aber war ihm nie in seinem Leben zu nahe getreten, so daß er ihm gesagt hätte: \"Warum tust du das oder das?\" Auch er war sehr schön und von Geburt der nächste nach Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Er aber unterhandelte mit Joab, Serujas Sohn, und mit dem Priester Ebjatar. Und sie traten zu Adonias über.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Aber der Priester Sadok, Jojadas Sohn Benaja, der Prophet Natan, Simi und Reï sowie Davids Krieger hielten nicht zu Adonias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Nun schlachtete Adonias Schafe, Rinder und Mastkälber bei dem Schlangenstein neben der Walkerquelle. Dazu lud er alle seine Brüder, die Königssöhne, ein, ebenso alle Mannen Judas, des Königs Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Aber den Propheten Natan und Benaja, die Krieger und seinen Bruder Salomo hatte er nicht eingeladen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Da sprach Natan zu Salomos Mutter Batseba: \"Hörst du nicht, daß Adonias, Chaggits Sohn, König wird? Und unser Herr David weiß nichts davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Nun komm! Ich will dir raten, wie du dein und deines Sohnes Salomo Leben rettest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Geh zum König David hinein und sprich zu ihm: \'Hast du nicht selbst, mein Herr und König, deiner Magd geschworen: \"Gewiß! Dein Sohn Salomo wird nach mir König. Er wird auf meinem Throne sitzen\"? Warum wird Adonias König?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Solange du dort noch mit dem König sprichst, komme ich nach dir hinein und bestätige deine Worte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Da ging Batseba zum König in das innere Gemach. Der König aber war sehr alt, und die Sunamitin Abisag bediente den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Batseba verneigte sich nun und warf sich vor dem König nieder. Da fragte der König: \"Was willst du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Sie sprach zu ihm: \"Mein Herr! Du hast beim Herrn, deinem Gott, deiner Magd geschworen: \'Dein Sohn Salomo wird nach mir König. Er wird auf meinem Throne sitzen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Nun aber wird Adonias König, und du, mein Herr und König, weißt nichts davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Er schlachtete Rinder, Mastkälber und Schafe in Menge und lud alle Königssöhne samt dem Priester Ebjatar und dem Feldhauptmann Joab ein, dagegen nicht deinen Knecht Salomo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Auf dich, mein Herr und König, sind die Augen von ganz Israel gerichtet, daß du ihnen kundtust, wer auf dem Throne meines Herrn und Königs nach ihm sitzen soll!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Legte sich aber mein Herr und König zu seinen Vätern, dann stünden ich und mein Sohn Salomo als Verbrecher da.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Sie sprach noch mit dem König; da kam der Prophet Natan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Man meldete dem König: \"Der Prophet Natan ist da.\" So kam er vor den König und warf sich vor ihm auf sein Antlitz zur Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Und Natan sprach: \"Mein Herr und König! Hast du bestimmt: \'Adonias soll nach mir König sein und er soll auf meinem Throne sitzen\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Denn er ist heute hinabgegangen und hat Ochsen, Mastkälber und Schafe in Menge geschlachtet. Dazu lud er alle Königssöhne ein, sowie die Heeresobersten und den Priester Ebjatar. Nun essen und trinken sie vor ihm und rufen: \'Es lebe der König Adonias!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mich aber, deinen Knecht, den Priester Sadok, Jojadas Sohn Benaja und deinen Knecht Salomo hat er nicht geladen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ist das von meinem Herrn und König ausgegangen, und hast du deine Diener nicht wissen lassen, wer auf dem Thron meines Herrn und Königs nach ihm sitzen soll?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Da hob der König David an und sprach: \"Ruft mir Batseba!\" Da kam sie vor den König und trat vor den König hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Da schwur der König und sprach: \"So wahr der Herr lebt, der mich aus aller Not befreit hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Wie ich dir beim Herrn, Israels Gott, geschworen: \'Dein Sohn Salomo wird nach mir König; er soll auf meinem Thron an meiner Statt sitzen\', so will ich heute tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Da neigte sich Batseba mit dem Antlitz bis zur Erde, fiel vor dem König nieder und sprach: \"Lang lebe mein Herr, der König David!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Da sprach der König David: \"Ruft mir den Priester Sadok, den Propheten Natan und Benaja, Jojadas Sohn!\" Da kamen sie vor den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Da sprach der König zu ihnen: \"Nehmt die Diener eures Herrn mit euch und laßt meinen Sohn Salomo mein eigenes Maultier besteigen! Dann führt ihn zum Gichon hinab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Dort salbe ihn der Priester Sadok und der Prophet Natan zum König über Israel! Dann stoßt in das Horn und ruft: \'Es lebe König Salomo!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Dann zieht hinter ihm herauf! Er komme dann herein und setze sich auf meinen Thron! Er sei König an meiner Statt! Denn ihn bestelle ich, daß er Fürst über Israel und Juda sei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Da antwortete Jojadas Sohn Benaja dem König und sprach: \"So sei es! So spreche der Herr, der Gott meines Herrn und Königs!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Wie der Herr mit meinem Herrn und König gewesen, so sei er mit Salomo und erhöhe seinen Thron noch über den Thron meines Herrn und Königs David!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Da gingen der Priester Sadok, der Prophet Natan und Jojadas Sohn Benaja samt den Bogenschützen und den Schildträgern hinab und ließen Salomo das Maultier des Königs David besteigen. Dann führten sie ihn zum Gichon hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Der Priester Sadok aber nahm das Ölhorn aus dem Zelte und salbte Salomo. Dann stießen sie in das Horn, und das ganze Volk rief: \"Es lebe der König Salomo!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Dann zog das ganze Volk hinter ihm her. Dabei bliesen die Leute auf Flöten und jauchzten in großer Freude, und die Erde zitterte vor ihrem Geschrei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Das hörten Adonias und alle Geladenen bei ihm. Doch wollten sie das Mahl zu Ende führen. Auch Joab hörte den Hörnerschall und fragte: \"Warum ist der Lärm in der Stadt so laut?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Noch sprach er, da kam des Priesters Ebjatar Sohn Jonatan. Da sprach Adonias: \"Komm her! Du bist ein wackerer Mann und bringst uns gute Botschaft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Da hob Jonatan an und sprach zu Adonias: \"Leider hat unser Herr, der König David, den Salomo zum König gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Und der König gab ihm den Priester Sadok, den Propheten Natan, den Jojadasohn Benaja und die Bogenschützen und die Schildträger mit. Sie ließen ihn des Königs Maultier besteigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Dann salbten ihn der Priester Sadok und der Prophet Natan zum König am Gichon und zogen von dort mit Jauchzen hinauf, daß die Stadt von Lärm erfüllt war. Das ist der Lärm, den ihr gehört habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Schon hat sich Salomo auf den Reichsthron gesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Und schon sind des Königs Diener hineingegangen, unseren Herrn, den König David zu segnen. Sie sprachen: \'Dein Gott mache Salomos Name noch herrlicher als den deinen und erhöhe seinen Thron über deinen Thron!\' Und der König verneigte sich auf seinem Lager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Weiter sprach der König also: \'Gepriesen sei der Herr, Israels Gott, der es heute gefügt, daß sich einer auf meinen Thron gesetzt und meine Augen es noch sehen dürfen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Da erschraken alle, die Adonias eingeladen hatte. Sie brachen auf und gingen jeder seines Wegs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonias aber ward voll Furcht vor Salomo, eilte hin und erfaßte die Hörner des Altars.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Da meldete man Salomo: \"Adonias fürchtet den König Salomo. Er hat die Altarhörner gefaßt und spricht: \'Der König Salomo schwöre mir zuvor, daß er seinen Knecht nicht mit dem Schwerte töten lasse!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Da sprach Salomo: \"Zeigt er sich als zuverlässig, dann soll keines seiner Haare auf die Erde fallen! Wird aber Böses an ihm erfunden, dann stirbt er.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Und der König Salomo sandte hin, und sie führten ihn vom Altar herab. Er kam und warf sich vor dem König Salomo nieder. Da sprach Salomo zu ihm: \"Geh heim!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Die Zeit kam nun heran, daß David sterben sollte. Da gab er seinem Sohne Salomo folgende Weisungen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '\"Ich gehe den Weg der ganzen Welt. Sei getrost und sei ein Mann!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Beobachte die Satzungen des Herrn, deines Gottes! Wandle auf seinen Wegen und halte seine Gebote, Gesetze, Vorschriften und Gebräuche, wie es in der Lehre Mosis geschrieben steht, auf daß du Glück habest bei allem, was du tust und wohin du dich wendest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Auf daß der Herr sein Wort erfülle, das er über mich also gesprochen: \'Wenn deine Söhne auf ihren Wandel achten, um treulich vor mir zu wandeln, aus ganzem Herzen und aus ganzer Seele, so fehlt es dir niemals an einem Mann auf Israels Thron!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Weiter weißt du selbst, was mir Serujas Sohn Joab angetan, was er getan hat den beiden Heeresobersten Israels, Ners Sohn Abner und Amasa, Jeters Sohn. Er ermordete sie. Er vergoß Kriegsblut im Frieden. Er brachte Kriegsblut an den Gurt um seine Hüfte und an seinen Schuh an seinem Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tu nach deinem weisen Ermessen! Du darfst aber den Graukopf nicht im Frieden in die Unterwelt hinabsteigen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Aber den Söhnen des Gileaditers Barzillai sollst du Huld erweisen! Sie seien unter deinen Tischgenossen! Denn sie sind zu mir gekommen, als ich vor deinem Bruder Absalom floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Nun ist bei dir noch Simei, der Sohn des Gera und Enkel Hajeminis, aus Bachurim. Er hat mir in schlimmster Weise geflucht, als ich nach Machanaim ging. Später aber ist er mir am Jordan entgegengekommen. Da schwur ich beim Herrn: \'Ich werde dich nicht mit dem Schwerte töten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Nun laß ihn nicht ungestraft! Du bist ein weiser Mann und weißt, was du ihm tun mußt, daß du sein graues Haar mit Blut in die Unterwelt binabsendest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Dann legte sich David zu seinen Vätern und ward in der Davidsstadt begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Die Zeit, die David über Israel geherrscht hatte, betrug vierzig Jahre. Zu Hebron hatte er sieben Jahre regiert und zu Jerusalem dreiunddreißig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Salomo saß nun auf dem Throne seines Vaters David, und seine Herrschaft ward immer fester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Da kam Chaggits Sohn Adonias zu Salomos Mutter Batseba. Sie fragte: \"Kommst du im Frieden?\" Er sprach: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Dann sprach er: \"Ich habe mit dir etwas zu reden!\" Sie sprach: \"Rede!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Er sprach: \"Du weißt selbst, daß das Königtum mein gewesen und ganz Israel erwartet hat, ich würde König; wie es dann anders kam und das Königtum meinem Bruder zufiel. Denn vorn Herrn ist es ihm bestimmt gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nun habe ich eine einzige Bitte an dich. Weise mich nicht ab!\" Sie sprach zu ihm: \"Rede!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Er sprach: \"Sprich mit dem König Salomo! Dich wird er ja nicht abweisen. Er soll mir die Sunamitin Abisag zum Weibe geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Da sprach Batseba: \"Gut! Ich will deinetwegen mit dem König sprechen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Und Batseba kam zum König Salomo, mit ihm wegen des Adonias zu reden. Da stand der König auf, ging ihr entgegen, neigte sich vor ihr und setzte sich auf seinen Thron. Hierauf ließ er für die Königinmutter einen Thronsessel hinstellen und sie setze sich zu seiner Rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Dann sprach sie: \"Ich habe eine kleine Bitte an dich. Weise mich nicht ab!\" Der König sprach zu ihr: \"Bitte nur, meine Mutter! Ich werde dich doch nicht abweisen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Da sprach sie: \"Man gebe die Sunamitin Abisag deinem Bruder Adonias zum Weibe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Da erwiderte der König Salomo und sprach zu seiner Mutter: \"Ei, warum bittest du für Adonias bloß um die Sunamitin Abisag? Bitte doch lieber gleich um das Königtum für ihn! Er ist ja mein älterer Bruder, und auf seiner Seite stehen der Priester Ebjatar und Joab, der Serujasohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Dann schwur der König Salomo also dem Herrn: \"Gott tue mir das und das, wenn Adonias aus sich selbst dies Wort gesprochen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Nun, so wahr der Herr lebt, der mich erwählt hat und der mich auf meines Vaters David Thron erhob und mir gemäß seiner Verheißung ein Haus gegründet hat! Noch heute sei Adonias des Todes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Und der König Salomo beauftragte Jojadas Sohn Benaja, und dieser stieß ihn nieder, und er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Dem Priester Ebjatar aber befahl der König: \"Geh nach Anatot auf dein Landgut! Du verdienst zwar den Tod. Aber ich will dich jetzt nicht töten, weil du die Lade des Herrn, des Herrn, vor meinem Vater getragen und alles, was mein Vater erlitten, miterduldet hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'So verstieß Salomo den Ebjatar, daß er nicht länger ein Priester des Herrn war, um des Herrn Wort zu erfüllen, das er über Elis Haus zu Silo geredet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Das Gerücht war auch zu Joab gedrungen. Weil sich aber Joab an Adonias angeschlossen hatte, wenn auch nicht an Absalom, so floh Joab zum Zelte des Herrn und ergriff die Altarhörner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Man meldete dem König Salomo: \"Joab ist zum Zelte des Herrn geflohen. Er steht neben dem Altar.\" Da sandte Salomo Jojadas Sohn Benaja mit dem Befehl hin: \"Auf! Stoß ihn nieder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja kam nun zum Zelte des Herrn und sprach zu ihm- \"So spricht der König: \'Komm heraus!\'\" Er aber sprach: \"Nein! Ich will hier sterben.\" Benaja brachte nun dem König Bescheid und sprach: \"So hat Joab geredet und so geantwortet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Der König sprach zu ihm: \"Tu, wie er gesprochen! Stoß ihn nieder! Aber begrabe ihn, daß du das Blut, das Joab ohne Ursache vergossen, von mir und meines Vaters Haus wendest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Der Herr lasse sein Blut auf sein Haupt zurückfallen! Denn zwei Männer, die treuer und tapferer als er gewesen, hat er niedergestoßen und sie mit dem Schwerte getötet, ohne daß mein Vater es gewußt hat. Israels Feldhauptmann Abner, Ners Sohn, und Judas Feldhauptmann Amasa, Jeters Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'So komme ihr Blut auf Joabs Haupt und auf das seiner Nachkommenschaft für immer! Immerdar aber sei David, seiner Nachkommenschaft, seinem Hause und Throne Heil vom Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'So ging Jojadas Sohn Benaja hinauf, stieß ihn nieder und tötete ihn. Da ward er in seinem Hause in der Steppe begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Und der König setzte Jojadas Sohn Benaja an seiner Statt über das Heer und den Priester Sadok an Ebjatars Stelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Dann sandte der König hin und ließ Simei rufen. Er sprach zu ihm: \"Bau dir ein Haus zu Jerusalem und bleibe hier wohnen! Gehe von hier nirgendwo anders hin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Gehst du aber hinaus und überschreitest du den Kidronbach, dann, merke dir das, bist du dem Tode verfallen. Dein Blut fällt auf dein Haupt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei sprach zum König: \"Gut so! Wie mein Herr und König gesagt, wird dein Sklave tun.\" Also blieb Simei längere Zeit zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Aber nach drei Jahren entliefen dem Simei zwei Sklaven zum König von Gat, Akis, Maakas Sohn. Man meldete dem Simei: \"Deine Sklaven sind in Gat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Da machte sich Simei auf, sattelte seinen Esel und ging nach Gat zu Akis, seine Sklaven zu suchen. So ging Simei hin und holte aus Gat seine Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Da meldete man Salomo: \"Simei ist aus Jerusalem nach Gat gegangen und ist wieder zurückgekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Da sandte der König hin, ließ Simei rufen und sprach zu ihm: \"Habe ich nicht beim Herrn geschworen und dir beteuert: Sobald du weggehst und irgendwohin gehst, merk dir, bist du dem Tode verfallen, und du hast zu mir gesagt: \'Gut so! Ich will gehorchen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Warum achtest du nicht den Schwur des Herrn und das Gebot, das ich dir gegeben habe?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Dann sprach der König zu Simei: \"Du kennst das Böse, um das dein Herz gewußt und das du meinem Vater David angetan. Der Herr bringt deine Bosheit auf dein Haupt zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Der König Salomo aber möge gesegnet sein und Davids Thron immerdar vor dem Herrn feststehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Und der König beauftragte Jojadas Sohn Benaja. Dieser ging hin und stieß ihn nieder, daß er starb. So war das Königtum in Salomos Hand gesichert worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Salomo verschwägerte sich nun mit Pharao, Ägyptens König. Er nahm Pharaos Tochter zum Weib und brachte sie in die Davidsstadt, bis er mit dem Bau seines Hauses und des Hauses des Herrn sowie der Mauer rings um Jerusalem fertig war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Nur opferte das Volk noch auf den Höhen; denn bis zu jener Zeit war dem Namen des Herrn noch kein Haus gebaut worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomo aber liebte den Herrn und wandelte in seines Vaters David Satzungen. Nur opferte und räucherte er auf den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Der König ging nun nach Gibeon, dort zu opfern. Denn dies war die größte Höhe. Tausend Brandopfer konnte Salomo auf diesem Altare darbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Zu Gibeon aber erschien der Herr dem Salomo nachts im Traum. Und Gott sprach: \"Bitte, was ich dir geben soll!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Da sprach Salomo: \"Du hast Deinem Knechte David, meinem Vater, große Huld erwiesen. Er ist vor Dir in frommer, echter Treue gegen Dich gewandelt. Du hast ihm diese große Huld bewahrt und hast ihm einen Sohn geschenkt, der jetzt auf seinem Throne sitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nun Herr, mein Gott! Du hast zum König Deinen Knecht gemacht an meines Vaters David Statt. Ich aber bin ein junger Mensch und weiß nicht aus noch ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Dein Knecht steht mitten in Deinem Volk, das Du erwählt, ein Volk, so zahlreich, daß es nicht gezählt und nicht berechnet werden kann vor Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Gib Deinem Knechte ein gehorsam Herz, Dein Volk zu richten und zwischen Gut und Bös ́ zu unterscheiden! Wer könnte sonst Dein zahlreich Volk regieren?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Dies gefiel dem Herrn, daß Salomo solches erbeten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Und Gott sprach zu ihm: \"Weil du darum gefleht und dir nicht langes Leben hast erbeten, nicht Reichtum und nicht deiner Feinde Tod, nein, nur für dich gebeten hast, recht klug zu werden, um auf Recht zu hören,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'so tue ich nach deinem Worte. Ich gebe dir ein weises und verständiges Herz, wie niemand vor dir es besessen hat, noch je besitzen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Ich gebe dir auch, was du nicht verlangt hast: den Reichtum und die Pracht, daß dir keiner gleicht unter den Königen für deines Lebens Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Und wandelst du auf meinen Wegen und wahrst du meine Satzungen und Vorschriften, so wie dein Vater David einst gewandelt, dannschenke ich dir langes Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Salomo erwachte. Es war ein Traum gewesen. Dann ging er nach Jerusalem, trat vor des Herrn Bundeslade, opferte und brachte Mahlopfer dar. Dann bereitete er ein Mahl für alle seine Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Damals kamen zwei Dirnen zum König und traten vor ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Das eine Weib sprach: \"Bitte, mein Herr! Ich und dieses Weib wohnen im gleichen Hause. Da gebar ich in ihrer Gegenwart im Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Am dritten Tag nach meiner Niederkunft gebar auch dieses Weib. Wir waren allein. Kein Fremdes war bei uns im Hause. Nur wir zwei waren im Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Da starb der Sohn dieses Weibes in der Nacht; sie hatte sich auf ihn gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Nun stand sie mitten in der Nacht auf und nahm meinen Sohn von meiner Seite, während deine Magd schlief, und legte ihn an ihren Busen. Ihren toten Sohn aber hatte sie an meinen Busen gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Ich stand nun am Morgen auf, meinen Sohn zu stillen. Da war er tot. Als ich ihn aber am Morgen betrachtete, war es nicht mein Sohn, den ich geboren hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Das andere Weib sprach: \"Nein! Mein Sohn ist der lebende, und dein Sohn ist der tote.\" Jene sagte: \"Nein! Dein Sohn ist der tote, und mein Sohn ist der lebende.\" Also stritten sie vor dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Der König sprach: \"Diese sagt: \'Der lebende ist mein Sohn, und dein Sohn ist der tote\', und jene sagt: \'Nein! Dein Sohn ist der tote, und mein Sohn der lebende.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Dann sprach der König: \"Holt mir ein Schwert!\" Da brachte man das Schwert vor den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Da sprach der König: \"Zerschneidet das lebende Kind in zwei Teile und gebt die eine Hälfte dieser, die andere jener!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Da sprach das Weib, dessen Sohn der lebende war, zum König - denn ihre Liebe für ihren Sohn regte sich mächtig. Sie sprach: \"Bitte, mein Herr! Gebt ihr das lebende Kind; aber tötet es nicht!\" Jene aber sprach: \"Weder mein noch dein sei es! Zerhaut es!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Da entschied der König und sprach: \"Gebt ihr das lebende Kind! Ihr dürft es nicht töten! Sie ist seine Mutter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Und ganz Israel hörte von dem Urteil, das der König fällte. Und sie fürchteten sich vor dem König. Denn sie sahen, daß Gottes Weisheit in ihm war, um Gerechtigkeit zu üben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Der König Salomo war also König über Gesamtisrael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Dies sind seine Obersten: Azarja, Sohn des Priesters Sadok.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Schreiber waren Elichoreph und Achia, Sisas Söhne. Achiluds Sohn Josaphat war Kanzler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Jojadas Sohn Benaja befehligte das Heer. Sadok und Ebjatar waren Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarja, Natans Sohn, war über die Vögte gesetzt. Natans Sohn Zabud war des Königs eigener Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Achisar war über das Haus gesetzt und Abdas Sohn Adoniram über die Fron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomo hatte zwölf Vögte für ganz Israel. Diese versorgten den König und sein Haus. Je einen Monat im Jahre lag jedem ob, ihn zu versorgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Dies sind ihre Namen: Churs Sohn auf dem Gebirge Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekers Sohn in Makas, Saalbim, Betsemes und Elon Bet Chanan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Cheseds Sohn in Arubbot; ihm unterstanden Soko und das ganze Chepherland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadabs Sohn im ganzen Hügelland von Dor. Er hatte Salomos Tochter Taphat zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, Achiluds Sohn in Taanak, Megiddo und ganz Betsean, das neben Sartan unterhalb Jezreels liegt, von Betsean bis Abel Mechola und bis jenseits von Jokneam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Gebers Sohn in Ramat Gilead unterstanden die Dörfer Jairs, des Manassesohnes, in Gilead, ebenso der Landstrich Argob in Basan, sechzig große Städte mit Mauern und ehernen Riegeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Joddas Sohn Achinadab in Machanaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas in Naphtali. Auch er nahm eine Tochter Salomos, Basemat, zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Chusas Sohn Baana in Asser und in Alot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Paruchs Sohn Josaphat in Issakar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Elas Sohn Simi in Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Uris Sohn Geber im Lande Gilead, dem Land des Amoriterkönigs Sichon und des Basankönigs Og. Dazu war er Vogt über das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda und Israel waren zahlreich wie der Meeressand an Menge. Sie aßen, tranken und waren guter Dinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Salomo herrschte über alle Königreiche vom Strom bis zum Philisterland und bis zu Ägyptens Grenze. Sie brachten Abgaben und dienten Salomo alle Tage seines Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomos Speisebedarf für einen Tag betrug: dreißig Maß Feinmehl und sechzig Maß anderes Mehl,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'zehn fette Rinder, zwanzig Weiderinder und hundert Schafe, ohne die Hirsche, Gazellen, Damhirsche, Wasservögel und Wildtauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Er waltete über alles Land jenseits des Stroms von Tipsach bis Gaza und über alle Könige jenseits des Stroms. So hatte er auf allen Seiten ringsum Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Juda und Jerusalem wohnten ruhig, jeder saß unter seinem Weinstock und Feigenbaum von Dan bis Beerseba, solange Salomo lebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Und Salomo besaß 40.000 Stuten als Rosse für seine Wagen nebst 12.000 Reitpferden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Jene Vögte versorgten den König Salomo und alle, die zum Tisch des Königs Salomo Zutritt hatten, jeder einen Monat lang. Sie ließen es an nichts fehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Auch Gerste und Stroh für die Rosse und Rennpferde brachten sie an den Ort, wo er gerade war, jeder nach seiner Ordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Und Gott gab Salomo Weisheit und Einsicht überreichlich sowie Geistesreichtum gleich dem Sand am Meeresufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Salomos Weisheit ward größer als die Weisheit aller Söhne des Ostens und als die Ägyptens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Er war weiser als alle Menschen, als der Ezrachite Etan und Machols Söhne Heman, Kalkol und Darda. Bei allen Heiden ringsum war er berühmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Er verfaßte 3.000 Sprüche, und seiner Lieder waren es 1.005.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Er redete über die Bäume von der Zeder auf dem Libanon bis zum Ysop, der an der Mauer herauswächst. Er redete auch über das Wild, die Vögel, das Gewürm und die Fische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Aus allen Völkern kamen Leute, Salomos Weisheit zu hören, von allen Erdenkönigen, die von seiner Weisheit hörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Chiram, der König von Tyrus, sandte seine Diener zu Salomo, weil er gehört, daß man ihn zum König an seines Vaters Statt gesalbt hatte. Chiram war ja immer ein vertrauter Freund Davids gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Und Salomo sandte zu Chiram und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, '\"Du weißt, daß mein Vater David nicht vermocht hat, für den Namen des Herrn, seines Gottes, ein Haus zu bauen wegen der Kriege, mit denen man ihn umringt hat, bis der Herr sie unter seine Fußsohle legte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Nun hat mir der Herr ringsum Ruhe verschafft. Kein Widersacher und kein böser Anstoß ist mehr da. So gedenke ich, dem Namen des Herrn, meines Gottes, ein Haus zu bauen, wie der Herr zu meinem Vater David gesprochen: \'Dein Sohn, den ich an deiner Statt auf deinen Thron setze, baue meinem Namen ein Haus!\' Darum lasse mir jetzt Zedern auf dem Libanon schlagen! Meine Diener mögen bei deinen Dienern sein! Ich gebe den Lohn deiner Diener dir so, wie du sagst. Denn du weißt selbst, daß bei uns niemand ist, der Holz zu schlagen weiß wie die Sidonier.\" Als Chiram Salomos Botschaft hörte, freute er sich sehr und sprach: \"Gepriesen sei der Herr, der dem David einen weisen Sohn über das zahlreiche Volk verliehen hat!\" Und Chiram schickte an Salomo und ließ sagen: \"Ich habe gehört, was du mir entboten hast. Ich will all deinen Wunsch an Zedern und Zypressenstämmen erfüllen. Meine Knechte sollen sie vom Libanon zum Meer bringen! Ich mache daraus im Meer Flöße bis zu dem Ort, den du mir angibst. Dort nehme ich sie auseinander. Und du kannst sie wegbringen. Du aber mögest meinen Wunsch erfüllen und für mein Haus Speise liefern!\" So lieferte Chiram dem Salomo Zedern- und Zypressenstämme ganz nach Wunsch. Dafür gab Salomo dem Chiram 20.000 Maß Weizen als Speise für sein Haus, dazu 20.000 Maß Öl aus zerstoßenen Oliven. Soviel gab Salomo dem Chiram Jahr für Jahr. Und der Herr hatte Salomo Weisheit verliehen, wie er ihm verheißen hatte. Zwischen Chiram und Salomo war Frieden, und sie schlossen ein Bündnis miteinander. Und der König Salomo hob von ganz Israel Fronarbeiter aus. Der Fronarbeiter waren es 30.000 Mann. Er sandte sie auf den Libanon, jeden Monat abwechselnd 10.000 Mann. Einen Monat waren sie auf dem Libanon und zwei Monate zu Hause. Über die Fron war Adoniram gesetzt. Im Gebirge hatte Salomo 70.000 Lastträger und 80.000 Steinhauer, außer den 3.300 Obersten der salomonischen Vögte, die über das Werk gesetzt waren. Diese beaufsichtigten das Volk, das am Werke arbeitete. Der König gebot, und sie brachen große, schwere Steine, um den Grund des Hauses mit Quadersteinen zu legen. So behauten die Bauleute Salomos und Chirams sowie die Gibliter die Stämme und Steine und richteten sie zum Bau des Hauses her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Im 480. Jahre nach dem Auszug der Israeliten aus dem Lande Ägypten, im vierten Jahre, am Neumondstag des Ziw, das ist des zweiten Monats der Regierung Salomos über Israel, baute er das Haus für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Das Haus, das der König Salomo für den Herrn baute, war sechzig Ellen lang, zwanzig breit und dreißig hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Die Halle vor dem Heiligtum des Hauses war zwanzig Ellen lang vor des Hauses Breitseite und vor dem Hause zehn Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Er machte für das Haus vergitterte und verschließbare Fenster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'An der Wand des Hauses baute er ringsum einen Anbau, an den Wänden des Hauses rings um das Heiligtum und den Hinterraum. So stellte er Seitenbauten ringsherum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Der unterste Anbau war fünf Ellen breit, der mittlere sechs und der dritte sieben. Er hatte am Hause ringsum Absätze machen lassen, so daß kein Eingreifen in die Hauswände nötig war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Als man das Haus baute, wurden ganze, beim Brechen fertiggestellte Steine verarbeitet. Weder Hammer noch Meißel, keinerlei eisernes Werkzeug, war im Haus bei seiner Erbauung zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Die Türe zum mittleren Stockwerke lag auf des Hauses Südseite. Auf Wendeltreppen stieg man zum Mittleren und von da zum dritten empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'So baute er das Haus und vollendete es. Er deckte das Haus mit Balken und Bohlen aus Zedernholz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Er baute am ganzen Hause den Anbau fünf Ellen hoch und verband ihn durch Zedernbalken mit dem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Da erging das Wort des Herrn an Salomo also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '\"Du baust dies Haus. Nun, wandelst du in meinen Satzungen und tust du meine Vorschriften und wahrst du all meine Gebote, darin zu wandeln, alsdann erfülle ich an dir mein Wort, das ich zu deinem Vater David sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, '\'Ich werde bei den Israeliten wohnen und niemals Israel, mein Volk, verlassen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'So baute Salomo das Haus und vollendete es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Im Innern fertigte er die Hauswände aus Zedernbrettern. Von des Hauses Fußboden bis zu den Deckenbalken belegte er es im Innern mit Holz. Des Hauses Fußboden belegte er mit Zypressenbrettern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Die zwanzig Ellen auf der hinteren Hausseite fertigte er aus Zedernbrettern vom Fußboden bis zu den Balken. So baute er es im Innern zum Hinterraum, dem Allerheiligsten, aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Vierzig Ellen maß das Haus, das heißt das Heiligtum vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Inwendig am Haus war Zedernholz, Koloquintenschnitzwerk und Blumengehänge. Alles war von Zedern. Kein Stein war zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Innen im Hause errichtete er den Hinterraum, daß man hier des Herrn Bundeslade aufstelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Und vor dem Hinterraum, der je zwanzig Ellen lang, breit und hoch war, errichtete er einen Altar aus Zedernholz und überzog ihn mit Feingold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Und Salomo bedeckte das Haus innen mit Feingold, sperrte den Hinterraum mit Goldkettchen ab und vergoldete ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Das ganze Haus vergoldete er, das ganze Haus vollständig, ebenso den ganzen Altar im Hinterraum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Im Hinterraum machte er zwei Cherube von Olivenholz, je zehn Ellen hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Fünf Ellen maß des einen Cherubs Flügel und fünf der des zweiten, somit zehn Ellen von einem Flügelende bis zum andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Zehn Ellen maß auch der andere Cherub. Beide Cherube hatten einerlei Maß und Gestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Die Höhe des einen Cherub war zehn Ellen. Ebenso maß der zweite Cherub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Die Cherube stellte er in das Innerste des Hauses und ließ die Flügel der Cherube sich so ausbreiten, daß der Flügel des einen die eine Wand berührte, der des andere die andere; ihre anderen Flügel stießen inmitten des Hauses aneinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Er vergoldete die Cherube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Alle Wände des Hauses ringsum versah er mit Schnitzwerk von Cheruben, Palmen und Blumengehängen innen und außen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Auch des Hauses Fußboden vergoldete er innen und außen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Für die Hinterraumtür machte er Türflügel aus Olivenholz. Die Einfassung bestand aus fünfseitigen Pfosten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Auf den zwei Türflügeln aus Olivenholz brachte er Schnitzwerk von Cheruben, Palmen und Blumengehängen an und vergoldete sie. Die Cherube und Palmen ließ er in das Gold ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Ebenso machte er für den Eingang zum Heiligtum Olivenholzpfosten von viereckiger Gestalt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'sowie zwei Türflügel aus Zypressenholz. Der eine Flügel bestand aus zwei Drehtüren; ebenso der andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Er schnitzte Cherube, Palmen und Blumengehänge ein und vergoldete sie passend für die Schnitzereien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Den inneren Vorhof baute er aus drei Quadersteinlagen und einer Lage Zedernbalken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Im vierten Jahre ward der Grund zum Hause des Herrn gelegt, im Monat Ziw.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Im elften Jahre im Monat Bul, das ist im achten Monat, vollendete er das Haus in all seinen Stücken und all seinem Zubehör. Er baute sieben Jahre daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'An seinem eigenen Hause baute Salomo dreizehn Jahre. Auch sein Haus vollendete er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Das Libanonwaldhaus baute er hundert Ellen lang, fünfzig breit und siebzig hoch, auf vier Zedernsäulengängen, mit Zedernbalken auf den Säulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Die Decke war auch aus Zedernholz oberhalb der Bogen, die auf den fünfundvierzig Säulen, je fünfzehn in einer Reihe, lagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Die Balken hatten drei Lagen, und so war dreimal ein Fenster dem anderen gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Alle Türen und Pfosten waren viereckig aus Holzrahmen. Ebenso stand dreimal eine Tür der anderen gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Die Säulenhalle machte er fünfzig Ellen lang und dreißig breit, davor eine Halle mit Säulen und Dach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Die Thronhalle und Gerichtshalle, die er machte und in der er Recht sprach, war mit Zedern vom Fußboden bis zum Gebälke gedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Sein Haus, in dem er wohnte, im anderen Hof, einwärts von der Halle, war in gleicher Weise gebaut. Auch für Pharaos Tochter, die Salomo geheiratet hatte, machte er ein Haus gleich dieser Halle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Alles dies war aus kostbaren Steinen von Quadergröße, nach innen und außen mit der Säge geschnitten, und zwar vom Fundament bis zu den Kragsteinen. So war es von draußen bis zum großen Vorhof.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Fundamentiert war es mit schweren, großen Steinen von zehn und Steinen von acht Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Darüber lagen schwere Steine in Quadergröße und Zedernholz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Der große Vorhof bestand ringsum aus drei Quaderlagen und einer Lage Zedernbalken, ebenso wie der innere Vorhof im Hause des Herrn und des Hauses Säulenhalle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Und der König Salomo sandte hin und ließ Chiram von Tyrus holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Er war der Sohn einer Witwe aus dem Stamme Naphtali. Sein Vater war ein Erzschmied aus Tyrus. Er war voll Weisheit, Einsicht und Geschick zur Ausführung von allerlei Erzarbeiten. So kam er zu König Salomo und machte alle seine Arbeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'So bildete er die zwei Säulen aus Erz. Die Höhe der einen Säule war achtzehn Ellen. Ein Faden von zwölf Ellen umspannte die andere Säule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Er machte zwei Knäufe, um sie oben auf die Säulen zu setzen. Sie waren aus Erz gegossen. Die Höhe des einen Knaufes betrug fünf Ellen und fünf die des anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Netze, netzartige Arbeit, Kettchen, kettenartige Arbeit, für die Knäufe oben auf den Säulen, sieben für den ersten Knauf und sieben für den zweiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Er machte Granatäpfel, zwei Reihen rings um das eine Netz, um damit die Knäufe oben an den Säulen zu bedecken. So machte er es auch für den zweiten Knauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Die Knäufe oben an den Säulen waren lilienförmig, vier Ellen an Umfang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'An den Knäufen oben an den zwei Säulen, oben und entlang der Ausbauchung jenseits des Netzwerkes, liefen zweihundert Granatäpfel in Reihen ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Die Säulen stellte er im Vorhofe des Heiligtums auf, zur Rechten eine, die er Jakin hieß, und zur Linken eine, die er Boaz nannte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Oben auf den Säulen war ein lilienartiges Gebilde. So ward das Säulenwerk vollendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Dann machte er das gegossene Meer, zehn Ellen von einem Rand bis zum anderen, ringsum rund, fünf Ellen hoch. Eine Schnur von dreißig Ellen umspannte es ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Unterhalb seines Randes von zehn Ellen umgaben es Koloquinten. Sie liefen rings um das Meer, zwei Koloquintenreihen, bei seinem Guß mitgegossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Es stand auf zwölf Rindern. Drei gekehrt nach Norden, drei nach Westen, drei nach Süden und drei nach Osten. Auf ihnen stand das Meer. Ihre Rückseiten waren alle nach innen gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Seine Dicke betrug eine Handbreite, und sein Rand war wie ein Becherrand, lilienförmig gestaltet. Es faßte 2.000 Bat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Er machte zehn Gestühle aus Erz. Jedes Gestühl war vier Ellen lang, vier breit und drei hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Die Gestühle waren so gearbeitet: Sie hatten Leisten, und zwar Leisten zwischen den Sprossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Auf den Leisten der Sprossen waren Löwen, Rinder und Cherube, ebenso auf den Sprossen. Ober- und unterhalb der Löwen und Rinder waren herablaufende Gewinde gearbeitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Jedes Gestühl hatte vier eherne Räder und Achsen, an seinen vier Füßen Schulterstücke. Unterhalb des Beckens waren die Schulterstücke von über Mannesgröße angenietet, angegossen die Gewinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Sein Mundstück war innerhalb des Knaufs eine Elle hoch darüber. Sein Mundstück war rund, anderthalb Ellen groß. Auch an seinem Mundstück befanden sich Reliefs, und seine Leisten bildeten ein Viereck, waren also nicht rund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Die vier Räder waren unterhalb der Leisten. Die Halter der Räder waren am Gestühl. Die Höhe eines jeden Rades betrug anderthalb Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Die Räder waren wie Wagenräder gearbeitet. Ihre Halter, Felgen, Speichen und Naben, alles war gegossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Vier Schulterstücke waren an den vier Ecken eines jeden Gestühls. Aus dem Gestühl kamen seine Schulterstücke hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Oben auf dem Gestühl war ein Aufsatz, eine halbe Elle hoch, rund ringsherum, und oben auf dem Gestühl kamen seine Halter und Leisten aus ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Er gravierte auf die Felder, Halter und Leisten Cherube, Löwen und Palmen nach eines jeden Raum, ebenso ringsum Blumengewinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Also machte er die Gestühle. Sie waren alle aus einem Guß, einerlei Maß und Gestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Dann machte er zehn eherne Becken. Jedes Becken faßte vierzig Maß. Jedes Becken hatte vier Ellen. Ein Becken war auf jedem der zehn Gestühle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Er stellte von den Gestühlen fünf auf der Südseite und fünf auf der Nordseite des Hauses auf. Das Meer stellte er auf die Südseite des Hauses nach Osten, dem Süden gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Chiram machte die Töpfe, Schaufeln und Schalen. Und so vollendete Chiram alle Arbeiten, die er dem König Salomo für das Haus des Herrn fertigen mußte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'zwei Säulen und zwei Kugeln der Knäufe oben auf den Säulen, die zwei Netze zur Bedeckung der zwei Knaufkugeln oben auf den Säulen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'die vierhundert Granatäpfel für die zwei Netze, zwei Reihen Granatäpfel für jedes Netz zur Bedeckung der zwei Knaufkugeln oben auf den Säulen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'die zehn Gestühle, die zehn Becken auf den Gestühlen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'das eine Meer, die zwölf Rinder unter dem Meer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'die Töpfe, Schaufeln und Schalen. Alle diese Geräte, die Chiram dem König Salomo für das Haus des Herrn gemacht hatte, waren aus poliertem Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'In der Jordanau, zwischen Sukkot und Sartan, ließ der König sie in Tonformen gießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Und Salomo stellte alle Geräte auf. Wegen der überaus großen Zahl war das Gewicht des Erzes nicht festgestellt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'So machte Salomo alle Geräte, die im Haus des Herrn waren: den goldenen Altar, den goldenen Schaubrottisch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'die Leuchter, fünf rechts und fünf links vor dem Hinterraum, aus Feingold, die goldenen Blütenlampen und Lichtscheren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'die Becken, Messer, Schalen, Schüsseln und Pfannen aus Feingold. Auch die Angeln an der Flügeltür zum innersten Teil des Hauses, zum Allerheiligsten, und an der Flügeltüre des Hauses zum Heiligtum waren aus Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'So ward das ganze Werk fertig, das König Salomo machen ließ. Salomo brachte auch seines Vaters David Weihegeschenke in das Haus des Herrn. Das Silber, das Gold und die Geräte legte er in die Schatzkammern im Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Damals berief Salomo die Ältesten Israels und alle Stammeshäupter, die Fürsten der israelitischen Geschlechter, zum König Salomo nach Jerusalem, um des Herrn Bundeslade von der Davidsstadt, das ist Sion, hinaufzuführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'So sammelte sich beim König Salomo die ganze Mannschaft Israels im Monat Etanim, das ist im siebten Monat, am Feste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Da kamen alle Ältesten Israels, und die Priester trugen die Lade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Dann brachten sie die Lade des Herrn zum Festgezelt, ebenso alle heiligen Geräte im Zelt. So brachten sie die Priester und Leviten hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Der König Salomo aber und Israels Gesamtgemeinde, die sich bei ihm eingefunden, standen mit ihm vor der Lade und opferten Schafe und Rinder, daß man sie nicht zählen noch berechnen konnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Dann brachten die Priester des Herrn Bundeslade an ihren Ort im Hinterraum des Hauses, in das Allerheiligste, unter die Flügel der Cherube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Denn die Cherube breiteten die Flügel über den Ort der Lade. So bedeckten die Cherube die Lade und ihre Stangen von oben her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Die Stangen waren so lang, daß die Stangenspitzen zwar vom Heiligtum gegen den Hinterraum hin gesehen werden konnten, aber von draußen nicht sichtbar waren. Sie blieben dort bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'In der Lade war nichts als die zwei steinernen Tafeln, die Moses am Horeb hineingelegt hatte, die Tafeln des Bundes, den der Herr mit den Israeliten geschlossen, als sie aus Ägypterland zogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Als aber die Priester das Heiligtum verließen, erfüllte die Wolke das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Und die Priester konnten wegen der Wolke nicht zur Dienstleistung hintreten, weil die Herrlichkeit des Herrn das Haus erfüllt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Damals hat Salomo gesprochen: \"Im Wetterdunkel hat der Herr gesprochen, er wolle Wohnung nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Nun habe ich ein Haus für Dich zur Wohnung hergestellt, zu Deinem Wohnsitz einen Ort für ewige Zeiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Dann wandte sich der König um und segnete die ganze Gemeinde Israels. Die Gesamtgemeinde Israels stand unterdessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Er sprach: \"Gepriesen sei der Herr, Gott Israels, der schon durch seinen Mund mit David, meinem Vater, gesprochen hat und auch durch ihn erfüllt, was er geredet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '\'Seitdem ich Israel, mein Volk, einst aus Ägypten herausgeführt, habe ich aus keinem Stamme Israels eine Stadt erkoren, ein Haus darin zu bauen, daß dort mein Name sei. Doch ich erwählte David, auf daß er meinem Volke Israel vorstehe.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Mein Vater David hatte zwar im Sinn, dem Herrn, dem Gotte Israels, für seinen Namen eine Stätte zu erbauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Doch sprach der Herr zu meinem Vater David: \'Daß du im Sinne hast, ein Haus zu bauen für meinen Namen, an diesem Plane hast du wohlgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Doch du sollst nicht dies Haus errichten. Dein Sohn, dein Leibessprosse, baue mir ein Haus für meinen Namen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Der Herr bestätigte sein Wort, das er gesprochen. Ich trat an meines Vaters David Statt und setzte mich auf Israels Thron, wie es der Herr gesagt. Ich baute dieses Haus dem Herrn, dem Gott Israels, für seinen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Ich machte einen Ort dort für die Lade, darin des Herren Bund sich findet, den er mit unseren Vätern abgeschlossen, als er sie aus Ägypterland geführt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Dann trat Salomo vor den Altar angesichts der Gesamtgemeinde Israels, breitete seine Hände zum Himmel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'und sprach: \'Herr, Gott Israels! Kein Gott gleicht Dir, nicht in dem Himmel droben, nicht auf der Erde unten, der Du den gnadenvollen Bund bewahrest Deinen Dienern, die mit dem ganzen Herzen vor Dir wandeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'der Du auch Deinem Knechte, meinem Vater, gehalten hast, was Du ihm einst versprochen. Du sprachest es mit Deinem Munde; mit Deiner Hand ließt Du\'s erfüllt, wie\'s heute ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nun, Herr, Gott Israels! Erfülle Deinem Knechte David, meinem Vater, was Du ihm einst versprochen: \'Nie fehle dir vor mir ein Mann, der sitzet auf dem Throne Israels, falls deine Söhne nur auf ihren Weg so achten, daß sie vor mir ihn wandeln, so, wie auch du vor mir gewandelt bist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nun, Herr, Gott Israels! Dein Wort bewahrheite sich jetzt, das Du zu Deinem Knechte, meinem Vater David hast gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Soll denn in Wahrheit Gott auf Erden wohnen? Dich fassen nicht der Himmel, noch der Himmel Himmel, geschweige dieses Haus, das ich erbaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Doch wende Dich dem Flehgebete Deines Knechtes zu, Du Herr, mein Gott, daß Du das Rufen und das Beten hörest, das heute Dein Knecht vor Dir vollzieht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Laß Deine Augen über diesem Hause offenstehen bei Tag und Nacht, hier über diesem Ort, von dem Du ausgesagt: \'Mein Name wird hier sein\', um das Gebet zu hören, das hier Dein Knecht verrichtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Hör auf das Flehen Deines Knechtes und Deines Volkes Israel, die hier an diesem Orte beten! Vernimm es an der Stätte, wo Du thronst, im Himmel! Erhör es dann! Verzeih!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Wenn jemand gegen seinen Nächsten fehlt, und man verlangt von ihm den Eid, er soll\'s beschwören, und kommt er zu dem Eid in dieses Haus vor Deinen Altar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'so greife Du, im Himmel hörend, ein! Schaff Deinen Dienern Recht, daß Du den Schuldigen bestrafst und auf sein Haupt sein Tun läßt fallen und freisprichst den, der ohne Schuld, und ihm nach seiner Unschuld lohnest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Wird von dem Feinde Israel, Dein Volk, geschlagen, dieweil es sich an Dir verfehlt, und sie bekehren sich zu Dir und preisen Deinen Namen und flehn zu Dir, in diesem Hause betend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'hör Du im Himmel! Vergib die Sünde Deines Volkes Israel! Laß seßhaft sie verbleiben auf der Scholle, die ihren Vätern Du verliehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Und ist der Himmel fest verschlossen und fällt kein Regen mehr, weil gegen Dich sie sich verfehlt, und beten sie alsdann an dieser Stätte in dem Bekenntnis Deines Namens und kehren sie von ihrer Sünde, dieweil Du sie gebeugt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'dann hör es, Du im Himmel! Vergib die Sünde Deiner Knechte und Deines Volkes Israel Vergehen! Den guten Weg, auf dem sie wandeln sollen, weise ihnen! Send Regen Deinem Lande, das Du zum Erbteil Deinem Volk verliehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Und wäre Hungersnot im Lande und wären Pest, Getreidebrand, Vergilbung, Heuschrecken und sonstig Ungeziefer da, bedrängte es sein Feind in seiner Tore Pforten und käme irgendwelche Plage, irgendwelche Krankheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'bei jeder Klage, jeder Bitte, sei\'s von irgendeinem Menschen, sei es von Deinem ganzen Volke Israel, wer je ein Leid in seinem Herzen trägt und hin nach diesem Hause seine Hände breitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'den hör im Himmel Du! Vergib an jener Stätte, wo Du thronest! Gib jeglichem nach seinem ganzen Wandel, sowie sein Herz Du kennst! Denn Du allein kennst aller Menschenkinder Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Dann fürchten sie Dich alle Zeit, solang sie auf der Scholle leben, die unsern Vätern Du verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Doch auch der fremde Mann, der nicht zu Deinem Volke Israel gehört, wenn er aus fremdem Lande kommt um Deines Namens willen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '- sie hören ja von Deinem großen Namen, von Deiner starken Hand und Deinem ausgestreckten Arm - wenn dieser hergepilgert und bei diesem Hause betet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'hör Du im Himmel, Deiner Wohnstatt, und tu all das, worum der Fremdling zu Dir ruft, daß alle Erdenvölker Deinen Namen kennenlernen, daß sie Dich also fürchten, gleich Deinem Volke Israel, und daß sie inne werden, daß über diesem Haus, das ich erbaut, Dein Name ausgerufen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Und zieht Dein Volk zum Streite wider Deine Feinde des Wegs, den Du sie sendest, und beten sie zum Herrn, hin nach der Stadt, die Du erwählt, und nach dem Haus, das ich errichtet Deinem Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'hör Du im Himmel ihr Gebet und Flehen! Schaff ihnen Sieg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Und wenn sie sich an Dir verfehlt - kein Mensch ist, der nicht sündigte - und wenn Du ihnen zürntest und sie dem Feinde überliefertest und ihre Zwingherrn sie in Feindesland verschleppten, nah oder fern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'und gehen sie im Land, wo sie gefangen sind, in sich, bekehren sich und flehn zu Dir in ihrer Zwingherrn Land und sprechen: \'Gesündigt haben wir und schlecht gehandelt und gefrevelt\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'und sie bekehren sich zu Dir von ganzem Herzen, ganzer Seele im Lande ihrer Feinde, die sie weggeschleppt, und beten sie zu Dir nach ihrem Lande hin, das ihren Vätern Du verliehen, hin zu der Stadt, die Du erwählt, hin zu dem Haus, das ich errichtet Deinem Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'hör Du im Himmel, Deines Thronens Ort, ihr Flehen und Gebet! Schaff ihnen Recht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Verzeih dann Deinem Volk, was es an Dir gefehlt, und alle ihre Missetaten, womit sie gegen Dich sich je vergangen! Laß ihnen Huld von ihren Zwingherrn widerfahren, daß diese ihrer sich erbarmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Sie sind Dein Volk, Dein Eigentum, das Du einst aus Ägypten weggeführt, dort mitten aus dem Schmelzofen des Eisens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Laß Deine Augen offenstehen für das Flehen Deines Dieners und für das Flehen Deines Volkes Israel! Daß Du in allem sie erhörst, worum sie Dich anrufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Du hast zum Eigentum sie ausgesondert aus allen Erdenvölkern, wie Du durch Moses, Deinen Knecht, verheißen, als Du einst unsre Väter aus Ägypten führtest, Herr, mein Herr!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Als Salomo all dieses Flehen und Beten zum Herrn beendigt hatte, stand er von dem Platze vor des Herrn Altar auf, wo er auf den Knien gelegen und seine Hände zum Himmel gebreitet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Dann trat er vor und segnete mit lauter Stimme die Gemeinde Israels und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '\"Gepriesen sei der Herr, der Ruhe seinem Volke Israel geschenkt, ganz so, wie er\'s verheißen hat! Von all den herrlichen Verheißungen, die er durch seinen Diener Moses einst gegeben, ist auch nicht eine einzige ausgeblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Mit uns sei unser Herr und Gott, wie er mit unsern Vätern einst gewesen! Ach, er verlaß uns nicht, verstoß uns nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Er lenke unsre Herzen zu sich hin, daß wir auf allen seinen Wegen wandeln und seine Vorschriften, Gesetze und Verordnungen beachten, die er einst unsern Vätern anbefohlen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'So mögen diese meine Worte, die ich vorm Herrn im Flehgebete ausgesprochen, ganz nahe sein dem Herren, unserm Gott, bei Tag und Nacht, auf daß er seinem Knecht und seinem Volke Israel nach eines jeden Tags Bedürfnis Recht verschaffe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'So kommen alle Erdenvölker zu der Einsicht, daß nur der Herr ist Gott und keiner sonst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Und euer Herz sei ganz beim Herren, unserm Gott, daß ihr nach seinen Rechten wandelt und das, was er gebietet, haltet, so wie heute!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Dann opferten der König und ganz Israel mit ihm vor dem Herrn Schlachtopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Als Dankopfer, das er dem Herrn opferte, brachte Salomo 22.000 Rinder und 12.000 Schafe dar. So weihten sie das Haus des Herrn ein, der König und alle Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'An jenem Tag hatte der König den mittleren Teil des Vorhofes vor dem Hause des Herrn eingeweiht. Denn er hatte dort das Brand- und das Speiseopfer bereitet sowie die Fettstücke des Mahlopfers. Der eherne Altar, der vor dem Herrn stand, war nämlich zu klein, um das Brand- und das Speiseopfer sowie die Fettstücke des Mahlopfers zu fassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'So feierte Salomo in jener Zeit das Fest, mit ihm ganz Israel, eine große Gemeinde von da, wo es nach Hamat geht, bis zu Ägyptens Bach, vor dem Herrn, unserem Gott, sieben Tage lang und nochmals sieben Tage, vierzehn Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Am achten Tage aber hatte er das Volk entlassen. Sie segneten den König und gingen in ihre Heimat, fröhlich und guten Mutes wegen all des Guten, das der Herr seinem Diener David und seinem Volke Israel getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Als Salomo mit dem Bau des Hauses des Herrn und des königlichen Hauses und mit jedem Plane, den Salomo auszuführen wünschte, fertig war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'erschien der Herr dem Salomo zum zweitenmal, wie er ihm zu Gibeon erschienen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Und der Herr sprach zu ihm: \"Dein Flehgebet, das du vor mich gebracht, das habe ich gehört. Ich heilige dieses Haus, das du mir erbaut hast, um meinen Namen hier für immer sein zu lassen. Hier weilen meine Augen und mein Herz für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Und wandelst du vor mir so, wie dein Vater David einst gewandelt, in Herzenseinfalt und in Redlichkeit, und tust du, wie ich dir geboten, befolgst du meine Vorschriften und Satzungen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'dann stelle ich für immer über Israel deines Königtums Thron so, wie ich deinem Vater David einst verheißen: \'Dir soll es auf Israels Thron nie an einem Manne fehlen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Doch fallt ihr und eure Söhne von mir ab, befolgt ihr nicht meine Vorschriften und Satzungen, die ich euch vorlege, und geht ihr hin und dienet anderen Göttern, sie anbetend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'dann tilge ich Israel vom Boden, den ich ihnen einst gegeben, verwerfe dann das Haus, das meinem Namen geweiht, von meinem Angesicht. Zum Sprichwort und zum Hohn wird Israel bei allen Völkern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Dies Haus wird umgestürzt. Wer daran vorüberzieht, entsetzt sich darob und zischt darüber. Und fragt man: \'Warum tat diesem Land und diesem Hause so der Herr?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'dann wird man sagen: \'Weil sie ihren Gott und Herrn verlassen, der ihre Väter aus Ägypten weggeführt, und sich an andere Götter halten, sie anbeten und ihnen dienen, drum hat der Herr all dieses Unheil über sie gebracht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Volle zwanzig Jahre hatte Salomo an den beiden Häusern gebaut, an dem Hause des Herrn und an dem königlichen Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Chiram, der König von Tyrus, hatte Salomo mit Zedern- und Zypressenbalken und Gold unterstützt, soviel er wünschte. Damals gab der König Salomo dem Chiram zwanzig Städte in dem Landstrich Galiläa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Und Chiram kam von Tyrus, die Städte zu besichtigen, die ihm Salomo gegeben hatte. Aber sie gefielen ihm nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Und er sprach: \"Was sollen diese Städte, die du mir gegeben hast, mein Bruder?\" So nannte man sie \"Land Kabul\" bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Chiram aber sandte dem König hundertzwanzig Talente Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Und so verhielt es sich mit der Fron, die der König Salomo erhob, um das Haus des Herrn zu bauen, sein Haus, die Bastei und die Mauern Jerusalems, sowie Chasor, Megiddo und Gezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Der Pharao, Ägyptens König, war nämlich heraufgezogen, hatte Gezer erobert und eingeäschert, die kanaanitischen Bewohner der Stadt niedergemetzelt und diese dem Weibe Salomos, seiner Tochter, als Mitgift gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomo baute nun Gezer wieder auf, ebenso das untere Betchoron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalat, Tamar in der bewohnten Steppe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'ferner alle Vorratsstädte Salomos, die Wagenstädte, die Rossestädte und was Salomo sonst noch geplant, zu Jerusalem und auf dem Libanon, überhaupt im ganzen Bereiche seiner Herrschaft zu bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Alles Volk, das übrig war von den Amoritem, Chittitern, Perizzitern, Chiwitern und Jebusitern, die nicht zu den Israeliten gehörten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'ihre Kinder, die nach ihnen im Land waren und die die Israeliten nicht auszurotten vermochten, hob Salomo zum Frondienste aus bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Von den Israeliten aber machte Salomo niemand zum Sklaven. Sie waren seine Krieger, Diener, Obersten und Wagenkämpfer und die Befehlshaber über seine Wagen und Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Es waren 550 Oberste über den Vögten, die über Salomos Werk gesetzt waren und die das Volk beaufsichtigten, das am Werk arbeitete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Kaum war Pharaos Tochter aus der Davidsstadt in ihr Haus gezogen, das er ihr gebaut hatte, so baute er die Bastei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Salomo opferte dreimal im Jahre Brand- und Mahlopfer auf dem Altar, den er dem Herrn gebaut hatte. Auch brachte er Räucherwerk auf ihm dar, der vor dem Herrn stand. Auch besserte er das Haus aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Auch Schiffe ließ der König Salomo anfertigen in Esiongeber bei Elot am Ufer des Schilfmeeres im Lande Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Und Chiram schickte zu Schiff seine Diener, meerkundige Schiffsleute, zusammen mit Salomos Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Sie kamen nach Ophir und holten von dort 420 Talente Gold und brachten es dem König Salomo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Die Königin von Saba nun hörte den Ruhm Salomos, des Geweihten des Herrn. So kam sie, ihn mit Rätseln zu prüfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Und sie kam mit sehr großem Gefolge nach Jerusalem. Kamele trugen Spezereien und Gold in sehr großer Menge, dazu Edelsteine. So kam sie zu Salomo. Da besprach sie mit ihm alles, was sie auf dem Herzen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Und Salomo gab ihr auf alle ihre Fragen Antwort. Nichts war dem König verborgen, was er ihr nicht beantwortet hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Die Königin von Saba sah nun all die Weisheit Salomos, das Haus, das er gebaut hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'die Speisen seines Tisches, das Sitzen seiner Diener, das Aufwarten seiner Bedienten, ihre Gewandung und seine Mundschenken und seinen Aufzug, in dem er zum Haus des Herrn hinaufzuziehen pflegte. Da war sie außer sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Sie sprach zum König: \"Wahrheit ist es, was ich in meinem Lande von deinen Sachen und deiner Weisheit vernommen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Ich habe der Kunde nicht geglaubt, bis ich gekommen bin und es dann mit eigenen Augen sah. Mir ist nicht die Hälfte gesagt worden. Du hast viel mehr Weisheit und Güte, als das Gerücht besagt, das ich vernahm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Glücklich deine Mannen! Glücklich diese deine Diener, die allzeit vor dir stehen und deine Weisheit hören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Gepriesen sei der Herr, dein Gott, der an dir Wohlgefallen gefunden, um dich auf Israels Thron zu setzen! Weil der Herr allzeit Israel liebt, hat er dich zum König eingesetzt, um Recht und Gerechtigkeit zu üben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Und sie gab dem König 120 Talente Gold und sehr viel Spezereien und Edelsteine. Niemals wieder waren Spezereien in solcher Menge hergekommen, wie die Königin von Saba dem König Salomo gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Auch Chirams Schiff, das Gold aus Ophir holte, brachte aus Ophir Aloëholz und Edelsteine in großer Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Und der König machte aus dem Aloëholz Fußsteige für das Haus des Herrn und das königliche Haus sowie Zithern und Harfen für die Sänger. Solches Aloëholz war nicht mehr gekommen und nicht mehr gesehen worden bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Der König Salomo aber erfüllte der Königin von Saba alle ihre Wünsche über das hinaus, was er ihr schenkte, wie es nur König Salomo konnte. Dann kehrte sie um und zog mit ihren Dienern in ihr Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Das Gewicht des Goldes, das für Salomo in einem Jahr einlief, betrug 666 Goldtalente,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'ohne die Abgaben der Großkaufleute und den Handelsertrag der Kaufleute und ohne das, was alle abgabepflichtigen Könige und die Statthalter des Landes lieferten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Der König Salomo machte 200 Schilde von geschlagenem Gold. Für jeden Schild belief es sich auf 600 Ring Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Bei 300 Schildchen aus geschlagenem Gold belief es sich für ein Schildchen auf drei Minen Gold. Der König tat sie in das Libanonwaldhaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Ferner machte der König einen großen Elfenbeinthron und überzog ihn mit Gold und Feingold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Sechs Stufen hatte der Thron. Das Oberteil hinten am Thron war gerundet. Armlehnen waren am Sitzplatz zu beiden Seiten, und neben den Lehnen standen zwei Löwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Zwölf Löwen standen dort auf sechs Stufen zu beiden Seiten. Solches war für kein anderes Königreich gemacht worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Alle Trinkgefäße des Königs Salomo waren von Gold. Von feinem Gold waren alle Geräte des Libanonwaldhauses. Silber galt zu Salomos Zeiten für nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Denn der König Salomo hatte auf dem Meere ein Tarsisschiff bei Chirams Flotte. Alle drei Jahre kam ein Tarsisschiff, beladen mit Gold und Silber, Elfenbein, Affen und Pfauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'So übertraf der König Salomo alle Könige der Erde an Reichtum und Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Alle Welt suchte Salomo zu sehen und seine Weisheit zu hören, die ihm Gott ins Herz gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'So brachten sie ein jeder seine Gabe, silberne und goldene Geräte, Gewänder, Waffen, Spezereien, Rosse und Maultiere, Jahr für Jahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomo beschaffte sich auch zahlreiche Wagen und Rosse. Er hatte 1.400 Wagen und 12.000 Reiter. Diese legte er in die Wagenstädte und in die Umgebung des Königs nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Der König machte das Silber zu Jerusalem den Steinen gleich und die Zedern den Maulbeerbäumen in der Niederung; so viele gab es davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Die Ausfuhr der Rosse, die Salomo besaß, kam aus Ägypten. Auch aus Kue holten sie die königlichen Händler gegen Bezahlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Ein Wagen kam bei der Einfuhr aus Ägypten auf sechshundert Silberlinge und ein Roß auf hundertundfünfzig. Ebenso kamen sie durch ihre Vermittlung zu allen chittitischen und aramäischen Königen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Der König Salomo aber liebte vielerlei fremdländische Weiber, neben der Pharaotochter Moabitinnen, Ammonitinnen, Edomitinnen, Sidonierinnen, Chittiterinnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'aus den Heidenvölkern, von denen der Herr den Israeliten gebot: \"Ihr sollt nicht zu ihnen kommen, noch dürfen sie zu euch kommen! Sonst werden sie euer Herz zu ihren Göttern verführen!\" An solchen hing Salomo mit Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Er hatte 700 eigentliche Frauen und 300 Nebenweiber. Und seine Weiber verführten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Als Salomo zu altern begann, verführten seine Weiber sein Herz zu anderen Göttern hin. Und sein Herz war nicht mehr ganz mit dem Herrn, seinem Gott, wie seines Vaters David Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'So folgte Salomo der sidonischen Göttin Astoret und dem ammonitischen Scheusal Milkom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Und Salomo tat, was dem Herrn mißfiel, und folgte nicht bis zuletzt dem Herrn wie sein Vater David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Damals baute Salomo eine Höhe für Kamos, Moabs Scheusal, auf dem Berge östlich von Jerusalem, und für das ammonitische Scheusal Moloch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'So tat er für alle fremdländischen Weiber, die ihren Göttern räucherten und opferten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Da zürnte der Herr über Salomo, weil sich sein Herz abgewandt hatte vom Herrn, dem Gott Israels, der ihm zweimal erschienen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Und er hatte ihm dies verboten, anderen Göttern nachzugehen. Aber er hatte nicht gehalten, was der Herr ihm geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Darum sprach der Herr über Salomo: \"Weil du dies im Sinn gehabt und meinen Bund und meine Vorschriften nicht eingehalten, die ich dir aufgetragen, darum entreiße ich dir nun das Königtum und gebe es deinem Knechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Jedoch bei deinen Lebzeiten tue ich es nicht, um deines Vaters David willen. Doch deinem Sohn entreiße ich es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Doch nicht das ganze Reich entreiße ich ihm. Ich lasse deinem Sohne einen Stamm um meines Dieners David willen und wegen Jerusalems, das ich erwählt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Und der Herr stellte dem Salomo einen Widersacher auf im Edomiter Hadad aus königlichem Geschlecht zu Edom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Damals als David Edom bestrafte und der Feldhauptmann Joab hinaufzog, die Erschlagenen zu begraben, und alle waffenfähigen Männer in Edom niederhieb');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '- denn Joab blieb sechs Monate dort mit ganz Israel, bis er alle waffenfähigen Männer in Edom ausgerottet hatte -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'da floh Hadad zusammen mit einigen Edomitern von seines Vaters Dienern nach Ägypten. Hadad aber war noch ein kleiner Knabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Sie brachen aus Midian auf und kamen nach Paran. Aus Paran nahmen sie Leute mit sich und kamen nach Ägypten zu Pharao, Ägyptens König. Und er gab ihnen ein Haus und wies ihnen einen Unterhalt an. Auch Land gab er ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Und Hadad fand viel Gunst bei Pharao. So gab er ihm die Schwester seines Weibes, die Schwester der Herrin Tachpenes, zum Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Die Schwester der Tachpenes gebar ihm seinen Sohn Genubat. Und Tachpenes gab ihm die erste Erziehung im Haus des Pharao. So blieb Genubat in Pharaos Haus inmitten der Söhne Pharaos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Hadad hörte nun in Ägypten, David habe sich zu seinen Vätern gelegt und der Feldhauptmann Joab sei tot, da sprach Hadad zu Pharao: \"Entlasse mich, daß ich in mein Land ziehe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Da sprach Pharao zu ihm: \"Was fehlt dir denn bei mir, daß du in dein Land zu ziehen suchst?\" Er sagte: \"Nichts. Aber entlasse mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Dann erweckte ihm Gott einen Widersacher in Eljadas Sohn Rezon, der von Hadadezer, seinem Herrn, dem König von Soba, entflohen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Er sammelte Leute um sich und ward Oberster einer Streifschar, als David jene tötete. Sie zogen nach Damaskus und siedelten hier. Dann herrschten sie in Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'So ward er Widersacher für Israel die ganze Zeit Salomos, wie das Unheil des Hadad. Er war Israel abgeneigt, solange er König über Aram war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboam, Nebats Sohn, ein Ephratite von Hassereda, dessen Mutter, eine Witwe, Serua hieß, war ein Diener Salomos. Er aber empörte sich gegen den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Dies ist der Grund, weshalb er die Hand gegen den König erhob. Salomo baute die Bastei und schloß die Lücke in seines Vaters David Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Der Mann Jeroboam aber war sehr tüchtig. Auch Salomo sah, daß der junge Mann ein tätiger Arbeiter war. Da machte er ihn zum Aufseher über allen Frondienst des Hauses Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'In jener Zeit ging Jeroboam aus Jerusalem. Da traf ihn unterwegs der Prophet Achia, der Silonite. Er aber war in einen neuen Mantel gehüllt, und die beiden waren allein auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Da faßte Achia den neuen Mantel, den jener anhatte, und zerriß ihn in zwölf Stücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Dann sprach er zu Jeroboam: \"Nimm dir zehn Stücke! Denn also spricht der Herr, Gott Israels: \'Siehe! Ich entreiße Salomo die Herrschaft und gebe dir zehn Stämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Nur ein Stamm wird ihm wegen meines Dieners David bleiben und um Jerusalems willen, der Stadt, die ich aus allen Stämmen Israels erwählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Sie haben mich verlassen und Sidons Göttin, die Astoret, angebetet, den Moabitergötzen Kamos sowie den Ammonitergötzen Milkom und sind auf meinen Wegen nicht gewandelt, zu tun, was recht in meinen Augen, das heißt meine Vorschriften und Satzungen, gleich seinem Vater David;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'ich nehme ihm aber nicht die ganze Herrschaft weg; ich lasse ihn als Fürsten noch, solange er lebt, um meines Dieners David willen, den ich erwählt und der auch meine Vorschriften und Satzungen beachtet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Doch seinem Sohne nehme ich das Reich und gebe dir es, die zehn Stämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Nur einen Stamm noch lasse ich, seinem Sohne, daß meinem Diener David vor mir allezeit eine Leuchte bleibe in Jerusalem, der Stadt, die mir auserwählt, um meinen Namen darein zu setzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Dich wähle ich. So herrsche ganz nach deinem Wunsche! Sei König über Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Gehorchst du in allem, was ich dir gebiete, und wandelst du auf meinen Wegen und tust, was recht in meinen Augen, und wahrst du meine Satzungen und Vorschriften, so wie mein Diener David einst getan, dann bin ich auch mit dir und baue dir ein Haus, so fest, wie ich es David auferbaut. Ich will dir Israel geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Dem Stamme Davids lege ich dazu Entbehrung auf, doch nicht für immer.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomo suchte nun Jeroboam zu töten. Jeroboam aber machte sich auf und floh nach Ägypten zu Ägyptens König Sisak. Und er blieb in Ägypten bis zu Salomos Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Ist nicht der Rest der Geschichte Salomos, alles, was er getan, und seine Weisheit, im Buche der Geschichte Salomos aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Die Zeit, die Salomo in Jerusalem über ganz Israel regierte, betrug vierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Salomo legte sich dann zu seinen Vätern und ward in der Stadt seines Vaters David begraben. Und sein Sohn Rechabeam ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rechabeam ging nun nach Sichem. Denn ganz Israel war nach Sichem gegangen, ihn zum König zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Davon hörte Nebats Sohn Jeroboam. Er war noch in Ägypten, wohin er vor dem König Salomo geflohen war. Jeroboam saß also in Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Nun sandte man hin und ließ ihn rufen. So kam Jeroboam und die ganze Gemeinde Israels. Sie sprachen zu Rechabeam also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '\"Dein Vater hat uns ein hartes Joch auferlegt. Erleichtere uns deines Vaters harten Dienst und sein schweres Joch, das er uns auferlegt, und wir wollen dir dienen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Er aber sprach zu ihnen: \"Geht und kommt in drei Tagen wieder zu mir!\" Und das Volk ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Da beriet sich König Rechabeam mit den Ältesten, die vor seinem Vater Salomo zu seinen Lebzeiten gestanden, und sprach: \"Wie ratet ihr, dies Volk zu bescheiden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Sie sprachen zu ihm: \"Bist du heute diesem Volke dienstwillig, fügst dich ihnen und gibst ihnen freundlichen Bescheid, so werden sie dir allzeit Diener sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Er aber kehrte sich nicht an den Rat der Alten, die ihn beraten hatten, sondern beriet sich mit den Jungen, die mit ihm aufgewachsen waren und vor ihm standen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Er sprach zu ihnen: \"Wie ratet ihr, dies Volk zu bescheiden, das zu mir gesprochen: \'Mach leichter das Joch, das uns dein Vater aufgelegt hat!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Da sprachen zu ihm die Jungen, die mit ihm aufgewachsen waren: \"Also sprich zu diesem Volke, das zu dir gesprochen: \'Dein Vater hat uns ein schweres Joch auferlegt; mach du nun unser Joch leichter!\' So sprich zu ihnen: \'Mein kleiner Finger ist stärker als meines Vaters Lenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Nun denn! Mein Vater hat euch ein schweres Joch auferlegt. Ich aber will euer Joch noch härter machen. Mein Vater hat euch mit Peitschen gezüchtigt. So will ich euch mit Skorpionen züchtigen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Am dritten Tage kam nun das ganze Volk zu Rechabeam, wie der König gesagt hatte: \"Kommt am dritten Tage wieder zu mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Da fuhr der König das Volk hart an; denn er hielt sich nicht an den Rat der Alten, die ihn beraten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Er sprach nach der Jungen Rat zu ihnen: \"Mein Vater hat euch ein schweres Joch auferlegt. Ich aber mache euer Joch noch schwerer. Mein Vater züchtigte euch mit Peitschen. Ich aber züchtige euch mit Skorpionen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Also gab der König dem Volk keine Gehör. Denn so war es vom Herrn verhängt worden, damit er sein Wort bestätigte, das der Herr durch den Siloniten Achia zu Nebats Sohn Jeroboam gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'So sah ganz Israel, daß der König ihnen kein Gehör schenkte. Da gab das Volk dem König diesen Bescheid. \"Was haben wir gemein mit David? Wir nehmen keinen Anteil mehr am Isaisohne. Zu deinen Zelten, Israel! Nun schau nach deinem Hause, David!\" So ging Israel zu seinen Zelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'So blieb Rechabeam nur noch König über die Israeliten, die in Judas Städten wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Da sandte der König Rechabeam den Fronmeister Adoniram hin. Aber ganz Israel steinigte ihn zu Tode. Der König Rechabeam selbst hatte noch rasch auf seinen Wagen springen und nach Jerusalem fliehen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'So fiel Israel vom Davidshause ab bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Als aber ganz Israel hörte, daß Jeroboam zurückgekehrt sei, sandten sie hin und ließen ihn zur Versammlung rufen. Da machten sie ihn zum König über ganz Israel. Niemand hielt mehr zu Davids Haus als allein der Stamm Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Rechabeam kam nun nach Jerusalem. Da sammelte er das ganze Haus Juda und den Stamm Benjamin. 180.000 erlesene Krieger, zum Kampfe gegen das Haus Israel, um das Königtum für Salomos Sohn Rechabeam zurückzugewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Da erging Gottes Wort an den Gottesmann Semaja:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '\"Sprich zu dem Sohne Salomos Rechabeam, dem König von Juda, und zu dem ganzen Hause Juda und zu Benjamin und zu dem übrigen Volke so:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '\'So spricht der Herr: Zieht nicht hinauf und kämpft nicht gegen eure israelitischen Brüder! Kehrt alle heim! Durch mich ist es so gefügt.\'\" Sie hörten auf das Wort des Herrn und kehrten heim nach des Herrn Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jeroboam baute nun Sichem auf dem Gebirge Ephraim aus und wohnte darin. Dann zog er von dort fort und baute Penuel aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jeroboam aber dachte bei sich: \"Jetzt kann die Herrschaft wieder an Davids Haus zurückfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Zieht dieses Volk hinauf, Schlachtopfer im Haus des Herrn zu Jerusalem darzubringen, dann fällt das Herz dieses Volkes wieder ihrem Herrn zu, Rechabeam, dem König von Juda. Dann bringen sie mich um und kehren wieder zum König von Juda Rechabeam zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Da beriet sich der König. Dann machte er zwei goldene Kälber und sprach zu jenen: \"Lange genug seid ihr nach Jerusalem hinaufgezogen. Hier, Israel, ist dein Gott, der dich aus Ägypterland geführt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Das eine stellte er zu Betel auf. Das andere tat er nach Dan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Dies ward Anlaß zur Sünde. Das Volk zog vor das eine bis nach Dan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Auch machte er ein Höhenhaus und bestellte aus des Volkes Vornehmen Priester, die nicht zu den Levisöhnen gehörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Auch stiftete Jeroboam am fünfzehnten Tage des achten Monats ein Fest wie das in Juda. Er selbst stieg zum Altar hinauf. Ebenso stiftete er ein solches zu Betel, um den Kälbern zu opfern, die er gemacht hatte. Zu Betel stellte er auch die Priester für die Höhen an, die er gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Er stieg nun zu dem Altar hinauf, den er in Betel gemacht hatte, am fünfzehnten Tage des achten Monats, in dem Monat, den er sich selbst allein erdacht hatte. Und er stiftete für die Israeliten ein Fest. Eben stieg er zum Altar, um zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Da kam ein Gottesmann aus Juda auf des Herrn Geheiß nach Betel. Jeroboam stand gerade am Altar, um zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Jener rief gegen den Altar auf des Herrn Geheiß und sprach: \"Altar! Altar! So spricht der Herr: \'Ein Sohn wird einst dem Davidshaus geboren. Josias ist sein Name. Er wird auf dir die Höhenpriester schlachten, die auf dir räuchern, und Menschenknochen wird man dann auf dir verbrennen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Auch gab er an jenem Tage ein Wahrzeichen an. Er sagte: \"Dies ist das Wahrzeichen, das der Herr gibt: Der Altar wird zerbersten und die Fettasche darauf verschüttet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Der König aber hörte des Gottesmannes Wort, das dieser gegen den Altar zu Betel ausgesprochen. Da streckte Jeroboam seine Hand vom Altar herab und sprach: \"Ergreifet ihn!\" Da verdorrte seine Hand, die er gegen ihn ausgestreckt hatte. Er konnte sie nicht mehr an sich ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Und der Altar barst, und die Fettasche ward vom Altare herab verschüttet, nach dem Wahrzeichen, das der Gottesmann auf des Herrn Geheiß angegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Da hob der König an und sprach zum Gottesmann: \"Begütige doch den Herrn, deinen Gott, und bete für mich, daß ich wieder meine Hand an mich ziehen kann!\" Da begütigte der Gottesmann den Herrn, und des Königs Hand kam wieder zu ihm zurück. Sie ward wie zuvor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Da sprach der König zu dem Gottesmann: \"Komm zu mir ins Haus und labe dich! Ich will dir ein Geschenk geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Da sprach der Gottesmann zum König: \"Gäbest du mir auch die Hälfte deines Hauses, so käme ich nicht mit dir. Ich esse weder Brot, noch trinke ich Wasser an diesem Orte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Denn so hat man mir durch des Herrn Worte befohlen: \'Iß kein Brot und trinke kein Wasser und gehe den Weg nicht wieder, den du gegangen bist!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'So ging er auch einen anderen Weg und kehrte nicht auf dem Weg zurück, auf dem er nach Betel gekommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Nun wohnte zu Betel ein alter Prophet. Seine Söhne kamen und erzählten ihm alles, was damals der Gottesmann zu Betel getan, und die Worte, die er zum König gesprochen. Als sie das ihrem Vater erzählten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'fragte sie ihr Vater: \"Welchen Weg ist er von dannen gezogen?\" Da wiesen ihm seine Söhne den Weg, den der Gottesmann aus Juda gezogen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Er sprach zu seinen Söhnen: \"Sattelt mir den Esel!\" Sie sattelten ihm den Esel, und er bestieg ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'So ritt er dem Gottesmanne nach und fand ihn unter einer Terebinthe sitzen. Dieser sprach zu ihm: \"Bist du der Gottesmann aus Juda?\" Er sprach: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Da sprach er zu ihm: \"Geh mit mir heim und iß Brot!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Er sprach: \"Ich kann nicht mit dir umkehren und dich begleiten. Ich esse an diesem Ort kein Brot und trinke bei dir kein Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Denn ein Wort ist an mich ergangen auf des Herrn Geheiß hin: \'Du darfst kein Brot essen und dort kein Wasser trinken. Du darfst nicht auf dem Wege, den du gegangen, zurückgehen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Da sprach er zu ihm: \"Auch ich bin ein Prophet wie du. Ein Engel hat eben zu mir auf des Herrn Geheiß hin gesprochen: \'Bring ihn wieder mit dir heim, daß er Brot esse und Wasser trinke!\'\" So belog er ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Da kehrte er mit ihm um und aß in seinem Hause Brot und trank Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Sie saßen eben bei Tische. Da erging das Wort des Herrn an den Propheten, der ihn zurückgeholt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Und er rief dem Gottesmanne aus Juda also zu: \"So spricht der Herr: \'Verletzt hast du des Herrn Befehl, nicht das Gebot befolgt, das dir der Herr, dein Gott, gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Du kehrtest um und aßest Brot und trankest Wasser an dem Ort, von dem er dir gesagt: \"Iß weder Brot noch trinke Wasser!\" So kommt dein Leichnam nicht in deiner Väter Grab.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Nachdem er Brot gegessen und hernach getrunken hatte, sattelte er ihm den Esel, dem Propheten, den er zurückgeholt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'So zog er fort. Da traf ihn unterwegs ein Löwe und tötete ihn. Sein Leichnam lag ausgestreckt auf dem Weg. Und der Esel stand daneben. Auch der Löwe blieb neben dem Leichnam stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Da kamen Leute vorüber und sahen den Leichnam auf dem Wege liegen und den Löwen bei dem Leichnam stehen. Da kamen sie und erzählten es in der Stadt, wo der alte Prophet wohnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Dies hörte der Prophet, der ihn zurückgeholt hatte. Da sprach er: \"Das ist der Gottesmann, der des Herrn Befehl verletzt hat. So gab der Herr ihn dem Löwen preis, der ihn zermalmte und tötete gemäß des Herrn Wort, das er zu ihm geredet hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Dann sprach er zu seinen Söhnen: \"Sattelt mir den Esel!\" Sie sattelten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Da zog er fort und fand den Leichnam auf dem Wege liegen und neben dem Leichnam den Esel und den Löwen stehen. Der Löwe hatte den Leichnam nicht gefressen und den Esel nicht zermalmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Da hob der Prophet den Leichnam des Gottesmannes auf, legte ihn auf den Esel und brachte ihn zurück. So kam der alte Prophet wieder zurück, die Klage zu halten und ihn zu begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Er legte seinen Leichnam in sein eigenes Grab. Und sie hielten um ihn die Klage: \"Ach, mein Bruder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Nachdem er ihn begraben hatte, sprach er zu seinen Söhnen: \"Wenn ich sterbe, begrabt mich in dem Grabe, in dem der Gottesmann begraben ist! Neben seine Gebeine legt meine Gebeine!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Denn das Wort trifft ein, das er auf des Herrn Geheiß ausgesprochen gegen den Altar zu Betel und alle Höhenhäuser in Samarias Städten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Trotzdem hatte Jeroboam nicht von seinem schlimmen Wandel gelassen; er bestellte vielmehr wieder von des Volkes Vornehmen Höhenpriester. Jeden, der es wünschte, setzte er als Höhenpriester ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Er ward dadurch zur Sünde für Jeroboams Haus und Anlaß zur Vernichtung und Vertilgung vom Erdboden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Zu jener Zeit ward Jeroboams Sohn Abia krank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Da sprach Jeroboam zu seiner Gemahlin: \"Mach dich auf! Verkleide dich aber, daß man nicht merke, daß du Jeroboams Gemahlin bist, und geh nach Silo! Dort ist der Prophet Achia, er, der geweissagt hat, daß ich König über dieses Volk würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Nimm zehn Brote, Schafskäse und einen Krug Honig mit dir und geh zu ihm! Er wird dir kundtun, wie es dem Knaben gehen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Jeroboams Gemahlin tat so. Sie brach auf, ging nach Silo und kam in Achias Haus. Achia aber konnte nicht mehr sehen; denn seine Augen waren infolge seines Alters starr geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Aber der Herr hatte zu Achia gesprochen: \"Soeben kommt das Weib Jeroboams, dich wegen ihres Sohnes zu fragen, weil er krank ist. Sprich so und so zu ihr! Wenn sie kommt, ist sie verkleidet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Als sie zur Türe hereinging, hörte Achia das Geräusch ihrer Tritte. Er sprach: \"Komm nur herein, Jeroboams Weib! Wozu verstellst du dich? Ich bin mit Hartem an dich beauftragt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Auf! Sage dem Jeroboam: \'So spricht der Herr, Israels Gott: Ich habe dich aus dem Volke erhoben und dich zum Fürsten meines Volkes Israel gemacht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Entrissen habe ich dem Davidshaus die Herrschaft und diese dir gegeben. Du aber bist nicht wie mein Diener David, der das, was ich geboten, auch befolgt und der aus ganzem Herzen mir nachgewandelt ist, zu tun, was recht in meinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Du tatest Böses, mehr als alle deine Vorgänger; du gingst hin und machtest andere Götter dir, Gußbilder, mir zur Kränkung. Mich aber warfst du hinter deinen Rücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Drum bringe ich Unheil über Jeroboams Haus und tilge von Jeroboam die Wandpisser, Unmündige und Mündige in Israel. Ich fege so Jeroboams Haus, wie man den Kot wegfegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Wer von Jeroboam stirbt in der Stadt, den fressen Hunde, und wer im Freien stirbt, den fressen des Himmels Vögel.\' So hat der Herr gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Du aber steh auf und geh heim! Wenn deine Füße dann die Stadt betreten, stirbt der Knabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Ganz Israel wird ihn betrauern und ihn begraben. Denn er allein kommt von Jeroboam in ein Grab, weil nur an ihm sich etwas findet, was dem Herrn, Israels Gott, an Jeroboams Haus gefällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Aber dann erweckt der Herr sich über Israel einen König, der Jeroboams Haus ausrottet, das heutige und das spätere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Der Herr schlägt Israel, daß es wie ein Rohr im Wasser schwankt, und reißt Israel aus diesem schönen Lande, das er ihren Vätern einst gegeben, und dann zerstreut er sie jenseits des Stromes, weil sie ihre heiligen Bäume fertigen und so des Herrn Eifersucht wecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Preis gibt er Israel um der Sünden Jeroboams willen, die er getan, zu denen er Israel verführt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Jeroboams Weib aber stand auf und kam nach Tirsa. Als sie die Hausschwelle betrat, war der Knabe schon tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Man begrub ihn, und ganz Israel betrauerte ihn nach des Herrn Wort, das er durch seinen Diener, den Propheten Abia, gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Der Rest der Geschichte Jeroboams, wie er Krieg geführt und regiert hat, ist ja aufgezeichnet im Buch der Geschichte der Könige Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Die Zeit, die Jeroboam regierte, betrug zweiundzwanzig Jahre. Er legte sich zu seinen Vätern, und sein Sohn Nadab ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Salomos Sohn Rechabeam aber regierte in Juda. Rechabeam war einundvierzig Jahre alt, als er König wurde, und regierte siebzehn Jahre in Jerusalem, der Stadt, die der Herr aus allen Stämmen Israels erwählt, seinen Namen dort einzusetzen. Seine Mutter war die Ammoniterin Naama.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Juda aber tat, was dem Herrn mißfiel, und sie erregten seine Eifersucht mehr als durch alles, was ihre Väter getan, durch ihre Sünden, die sie taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Sie bauten sich gleichfalls Höhen, Steinmale und heilige Bäume auf jedem hohen Hügel und unter jedem grünen Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Selbst Tempeldirnen waren im Lande. So taten sie alle Greuel der Heiden, die der Herr vor den Israeliten vertrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Im fünften Jahre des Königs Rechabeam zog Ägyptens König Sisak gegen Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Er nahm die Schätze aus dem Hause des Herrn und die Schätze des königlichen Hauses. Alles nahm er mit. Auch die goldenen Schilde, die Salomo gemacht, nahm er mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'An ihrer Statt machte der König Rechabeam eherne Schilde und gab sie in die Obhut der Obersten der Läufer, die an der Pforte des königlichen Hauses Wache hielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Sooft der König in das Haus des Herrn ging, trugen sie die Läufer und brachten sie hernach in das Gemach der Läufer zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Ist der Rest der Geschichte Rechabeams und alles dessen, was er getan, nicht im Buche der Geschichte der Könige Judas aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Zwischen Rechabeam und Jeroboam aber war allezeit Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Rechabeam legte sich nun zu seinen Vätern und ward bei seinen Vätern in der Davidsstadt begraben. Seine Mutter hieß Naama und war eine Ammoniterin. Und sein Sohn Abia ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Im achtzehnten Jahre des Königs Jeroboam, des Nabatsohnes, ward Abia König in Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Er regierte zu Jerusalem drei Jahre, und seine Mutter hieß Maaka, des Abisalom Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Er wandelte in allen Sünden seines Vaters, die er vor ihm getan hatte, und sein Herz war nicht ganz beim Herrn, seinem Gott, wie seines Vaters David Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Denn nur um Davids willen hatte ihm der Herr, sein Gott, eine Leuchte zu Jerusalem gelassen, daß er seinen Sohn nach ihm erstehen und Jerusalem bestehen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Denn David hatte getan, was recht war in den Augen des Herrn, und war in nichts abgewichen von dem, was er ihm geboten, sein ganzes Leben lang, außer in der Sache des Chittiters Urias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Zwischen Rechabeam und Jeroboam aber war zeitlebens Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Ist der Rest der Geschichte Abias und alles dessen, was er getan, nicht im Buche der Geschichte der Könige Judas aufgeschrieben? Auch zwischen Abia und Jeroboam war Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Als sich Abia zu seinen Vätern legte, begrub man ihn in der Davidsstadt, und sein Sohn Asa ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Im zwanzigsten Jahre des israelitischen Königs Jeroboam ward Asa König in Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Er regierte in Jerusalem einundvierzig Jahre. Seine Mutter hieß Maaka, des Abisalom Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asa tat, wie sein Ahne David, was recht war in des Herrn Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'So trieb er die Tempeldirnen aus dem Land und beseitigte all die Schandgestalten, die seine Väter gemacht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Auch seine Mutter Maaka setzte er als Herrin ab, weil sie ein Schandbild der Aschera gemacht hatte. Asa hieb ihr Schandbild um und verbrannte es im Kidrontal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Die Höhen aber waren nicht beseitigt worden. Doch blieb Asas Herz ganz beim Herrn sein Leben lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Er brachte seines Vaters Weihegaben und seine eigenen Gaben in das Haus des Herrn, Silber, Gold und Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Zwischen Asa und Baësa, Israels König, aber war immer Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Israels König Baësa nun zog gegen Juda und baute Rama aus, um dem Judakönig Asa Aus- und Einzug zu versperren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Da nahm Asa alles Silber und Gold in den Schatzkammern des Hauses und die Schätze im königlichen Haus und händigte sie seinen Dienern ein. Dann sandte sie der König Asa zu dem König von Aram, Benhadad, dem Sohn des Tabrimmon und Chesjons Enkel, der zu Damaskus saß, und ließ ihm sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '\"Zwischen mir und dir sei ein Bund, wie zwischen meinem und deinem Vater! Hier sende ich dir ein Geschenk an Silber und Gold. Wohlan! Brich deinen Bund mit Israels König Baësa! Dann zieht er von mir ab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Benhadad nun hörte auf König Asa und sandte seine Heeresobersten gegen die Städte Israels. Er verheerte ljjon, Dan, Abel Bet Maaka und ganz Kinerot samt dem ganzen Land Naphtali.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Als dies Baësa vernahm, ließ er den Ausbau von Rama und blieb in Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Nun hatte der König Asa ganz Juda aufgeboten; keiner war davon befreit, und sie schafften die Steine und Balken fort, mit denen Baësa Rama ausgebaut hatte. König Asa baute damit Geba in Benjamin und Mispa aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Ist der Rest der Geschichte Asas und all seine Heldentaten und alles, was er sonst getan, sowie die Städte, die er ausgebaut, nicht im Buche der Geschichte der Könige Judas aufgezeichnet? Im Alter aber litt er an kranken Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Als sich Asa zu seinen Vätern legte, ward er bei seinen Vätern in der Davidsstadt begraben. Sein Sohn Josaphat ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Jeroboams Sohn Nadab war in Israel König geworden im zweiten Jahre des Judakönigs Asa. Er regierte über Israel zwei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Und er tat, was dem Herrn mißfiel, Und wandelte auf seines Vaters Weg und in seiner Sünde, zu der er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Achias Sohn Baësa vom Hause Issakar aber verschwor sich gegen ihn. Und Baësa erschlug ihn zu Gibbeton, das den Philistern gehörte, als Nadab mit ganz Israel Gibbeton belagerte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'So tötete ihn Baësa im dritten Jahre des Judakönigs Asa und ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Sobald er König geworden war, schlug er Jeroboams ganzes Haus. Er ließ von Jeroboam nichts übrig, was Odem hatte, bis er es vertilgt hatte, nach des Herrn Wort, das er durch seinen Diener Achia, den Siloniter, gesprochen hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Und zwar wegen Jeroboams Sünden, die er getan und zu denen er Israel verleitet durch das Ärgernis, durch das er dem Herrn, Israels Gott, eine Kränkung bereitet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Ist der Rest der Geschichte Nadabs und alles dessen, was er getan, nicht im Buch der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Zwischen Asa und dem König Israels, Baësa, aber war immer Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Im dritten Jahre des Judakönigs Asa ward des Achia Sohn Baësa König über Israels ganzen Rest zu Tirsa für vierundzwanzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Er tat, was dem Herrn mißfiel, und wandelte auf Jeroboams Weg und in seiner Sünde, zu der er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Das Wort des Herrn erging nun an Chananis Sohn Jehu gegen Baësa also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '\"Ich habe dich aus dem Staub erhoben, dich zum Fürsten meines Volkes Israel gemacht. Du aber gingest auf Jeroboams Pfad, und du verführtest Israel, mein Volk, zur Sünde, so daß sie mich durch ihre Frevel kränkten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'So fege ich denn Baësa mit seinem Hause weg. Und ich verfahre so mit deinem Haus, wie mit des Nebatsohnes Jeroboam Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Wer da von Baësa stirbt in der Stadt, den fressen die Hunde, und wer im Freien stirbt, den fressen da des Himmels Vögel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Ist der Rest der Geschichte Baësas, was er getan, und seine tapferen Taten nicht im Buch der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Als sich Baësa zu seinen Vätern legte, ward er in Tirsa begraben. An seiner Statt ward sein Sohn Ela König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Beigefügt sei, daß durch den Propheten Jehu, Chananis Sohn, das Wort des Herrn an Baësas und sein Haus ergangen ist, einmal wegen all des Bösen, das er in des Herrn Augen getan, um ihn durch seiner Hände Machwerk zu kränken, so daß er dem Hause Jeroboams gleich ward, sodann, weil er jenen erschlagen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Im sechsundzwanzigsten Jahre des Judakönigs Asa ward Baësas Sohn Ela König über Israel zu Tirsa für zwei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Gegen ihn verschwor sich sein Diener Zimri, Oberster der einen Hälfte der Streitwagen. Er selbst berauschte sich beim Zechen zu Tirsa im Hause des Arsa, der dem Hause zu Tirsa vorstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimri kam und schlug ihn tot im siebenundzwanzigsten Jahre des Judakönigs Asa. Er ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Als der König auf dem Throne saß, schlug er Baësas ganzes Haus. Er ließ davon nichts übrig, was an die Wand pißt, samt seinen Verwandten und Freunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'So vertilgte Zimri Baësas ganzes Haus nach des Herrn Wort, das er aber Baësa durch den Propheten Jehu gesprochen hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'wegen all der Sünden Baësas und seines Sohnes Ela Frevel, die sie selbst getan, und zu denen sie Israel verführt hatten, um den Herrn, Israels Gott, durch ihre Nichtigkeiten zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Ist der Rest der Geschichte Elas und alles, was er getan, nicht im Buch der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Im siebenundzwanzigsten Jahre des Judakönigs Asa ward Zimri für sieben Tage zu Tirsa König. Das Kriegsvolk aber lagerte vor Gibbeton, das den Philistern gehörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Da hörte das Volk im Lager die Kunde, Zimri habe sich verschworen und sogar den König erschlagen. Da machte ganz Israel den Omri, Israels Feldhauptmann, an jenem Tage im Lager zum König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Dann zogen Omri und ganz Israel mit ihm von Gibbeton ab, und sie belagerten Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Als Zimri sah, daß die Stadt genommen sei, kam er in des königlichen Hauses Hochburg und steckte das königliche Haus über sich in Brand. So starb er');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'wegen seiner Sünden, die er begangen, indem er tat, was dem Herrn mißfällig war. Er wandelte dabei auf Jeroboams Weg und in seiner Sünde, die er getan, um Israel zur Sünde zu verführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Ist nicht der Rest der Geschichte Zimris und seine Verschwörung im Buch der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Damals spaltete sich das Volk Israel in zwei Teile. Die eine Hälfte des Volkes hielt sich an Ginats Sohn Tibni, ihn zum König zu machen, die andere Hälfte an Omri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Das Volk aber, das sich an Omri hielt, überwand das Volk, das sich an den Ginatsohn Tibni hielt. So starb Tibni, und Omri ward König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Im einunddreißigsten Jahre des Judakönigs Asa ward Omri König in Israel für zwölf Jahre. Er regierte sechs Jahre in Tirsa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Dann kaufte er den Berg von Samaria von Semer um zwei Talente Silbers, bebaute den Berg und benannte die Stadt, die er gebaut, nach dem Namen des früheren Besitzers des Berges Semer Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Auch Omri tat, was dem Herrn mißfiel, und trieb es ärger als alle seine Vorgänger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Er ging ganz auf des Nebatsohnes Jeroboam Weg und in seinen Sünden, zu denen er Israel verführt hatte, um den Herrn, Israels Gott, durch ihre Nichtigkeiten zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Ist nicht der Rest der Taten, die Omri tat, und seine Tapferkeit, die er bewiesen, im Buche der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Als sich Omri zu seinen Vätern legte, ward er zu Samaria begraben. Sein Sohn Achab ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Omris Sohn Achab ward über Israel König im achtunddreißigsten Jahre des Judakönigs Asa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Omris Sohn Achab regierte über Israel zu Samaria zweiundzwanzig Jahre. Achab, Omris Sohn, aber tat, was dem Herrn mißfiel, mehr als alle seine Vorgänger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Das war noch das Geringste, daß er in des Nebatsohnes Jeroboam Sünden wandelte. Er nahm auch des Sidonierkönigs Etbaal Tochter Izebel zum Weib, diente dem Baal und betete ihn an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Auch errichtete er dem Baal einen Altar in des Baals Haus, das er zu Samaria erbaut hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Sodann stellte Achab die Aschera auf. Noch anderes tat Achab und kränkte den Herrn, Israels Gott, mehr als alle Könige Israels, die vor ihm waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'zu seiner Zeit baute Chiel von Betel Jericho auf. Mit seinem Erstgeborenen Abiram legte er seinen Grund und mit seinem jüngsten Segub setzte er seine Tore ein, nach des Herrn Wort, das er durch Nuns Sohn Josue gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Der Tisbiter Elias von den Beisassen Gileads aber sprach zu Achab: \"So wahr der Herr, Israels Gott, lebt, vor dem ich stehe! In diesen nächsten Jahren fällt weder Tau noch Regen, außer es geschähe auf mein Wort.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Dann erging an ihn des Herrn Wort also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '\"Geh von dannen und wende dich gen Osten! Verbirg dich an dem Bache Kerit, östlich vom Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Aus dem Bache sollst du trinken, und Raben heiße ich, dich dort zu ernähren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Er ging und tat nach des Herrn Wort. Er ließ sich am Bache Kerit nieder, östlich vom Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Und die Raben brachten ihm Brot und Fleisch, morgens und abends, und aus dem Bache trank er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Nach einiger Zeit versiegte aber der Bach; denn im Lande war kein Regen gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Da erging an ihn des Herrn Wort also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '\"Auf! Geh nach Sarepta bei Sidon und bleibe dort! Ich habe dort einer Witwe geboten, dich zu pflegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'So brach er auf und ging nach Sarepta. Als er zum Stadttor kam, war dort gerade eine Witwe, die Holz auflas. Er rief ihr zu und sprach: \"Hol mir in einem Gefäß ein wenig Wasser, daß ich trinke!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Sie ging, es zu holen. Da rief er ihr nach und sprach: \"Bring mir doch einen Bissen Brot mit!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Sie sprach: \"So wahr der Herr, dein Gott, lebt! Ich habe nichts Gebackenes, nur noch eine Handvoll Mehl im Topf und im Krug ein wenig Öl. Eben lese ich ein paar Holzstücke auf. Dann gehe ich heim und bereite es für mich und meinen Sohn. Haben wir es verzehrt, dann wollen wir sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elias sprach zu ihr: \"Sei unbesorgt! Geh heim und tu, wie du gesagt! Doch mache mir davon zuerst einen kleinen Kuchen und bring ihn mir her! Für dich und deinen Sohn mach hernach einen solchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Denn so spricht der Herr, Israels Gott: \'Das Mehl im Topfe geht nicht aus, der Ölkrug wird nicht leer, bis zu dem Tage, da der Herr zur Erde Regen sendet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Sie ging und tat, was Elias gesagt. Und sie aßen davon, sie, er und ihr Haus, eine Zeitlang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Das Mehl im Topfe aber ging nicht aus, und der Krug mit Öl ward nicht leer, nach des Herrn Wort, das er durch Elias geredet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Nach diesen Begebnissen erkrankte der Sohn des Weibes, der Hauswirtin, und seine Krankheit steigerte sich, bis daß kein Odem mehr in ihm blieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Da sprach sie zu Elias: \"Was habe ich mit dir zu schaffen, Gottesmann? Du bist zu mir gekommen, meine Schuld zu rügen und meinen Sohn zu töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Er sprach zu ihr: \"Gib mir deinen Sohn!\" Und er nahm ihn aus ihrem Schoß, trug ihn in das Obergemach, wo er wohnte, und legte ihn auf sein Bett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Dann rief er zum Herrn und sprach: \"Herr, mein Gott! Tust Du sogar der Witwe, bei der ich zu Gast bin, so übel, daß Du ihren Sohn sterben lässest?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Dann streckte er sich dreimal über den Knaben, rief den Herrn an und sprach: \"Herr, mein Gott! Möge dieses Knaben Seele in sein Inneres zurückkehren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Und der Herr hörte auf das Rufen des Elias. Und die Seele des Knaben kehrte in sein Inneres zurück, und er ward wieder lebendig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Da nahm Elias den Knaben, brachte ihn vom Obergemach ins Haus hinab und gab ihn seiner Mutter. Und Elias sprach: \"Siehe da! Dein Sohn lebt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Da sprach das Weib zu Elias: \"Jetzt weiß ich, daß du ein Gottesmann bist und daß des Herrn Wort in deinem Munde Wahrheit ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Lange Zeit verging. Da erging des Herrn Wort an Elias im dritten Jahre also: \"Auf! Zeige dich dem Achab! Ich will Regen auf die Erde senden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Da ging Elias, sich Achab zu zeigen. Die Hungersnot aber war stark in Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Und so rief Achab seinen Hausvorstand Obadja. Obadja aber fürchtete den Herrn sehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Damals, als Izebel die Propheten des Herrn ausrottete, holte Obadja hundert Propheten und versteckte sie, je fünfzig in einer Höhle, und versorgte sie mit Brot und Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Achab sprach also zu Obadja: \"Geh im Lande zu allen Wasserquellen und allen Bächen! Vielleicht finden wir Gras und erhalten damit Roß und Maultiere am Leben und müssen nichts vom Vieh eingehen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'So teilten sie sich in das Land, es zu durchziehen. Achab aber zog auf dem einen Weg allein und Obadja auf dem anderen allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Als Obadja unterwegs war, kam ihm Elias entgegen. Er erkannte ihn, fiel auf sein Antlitz und sprach: \"Bist du es, mein Herr Elias?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Dieser sprach zu ihm: \"Ich bin es. Auf! Sag deinem Herrn: \'Elias ist da!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Er sprach: \"Was habe ich verschuldet, daß du deinen Sklaven in die Hand des Achab geben willst, daß er mich töte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'So wahr der Herr, dein Gott, lebt! Es gibt kein Volk und kein Reich, wohin mich mein Herr nicht geschickt, dich zu suchen. Und sprächen sie: \'Er ist nicht hier\', dann ließe ich das Reich und das Volk schwören, daß sie dich nicht finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Und da sprichst du jetzt: \'Auf! Sag deinem Herrn: Elias ist da!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Ginge ich von dir weg, so entführte dich des Herrn Geist, ich weiß nicht, wohin, und käme ich, es Achab zu melden, und fände er dich nicht, so erschlüge er mich. Und doch fürchtet dein Sklave den Herrn von Jugend auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ist meinem Herrn nicht berichtet worden, was ich getan, als Izebel des Herrn Propheten tötete, daß ich von den Propheten des Herrn hundert Mann, je fünfzig in einer Höhle, versteckte und sie mit Brot und Wasser versorgte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Und da sprichst du jetzt: \'Geh und sage deinem Herrn: Elias ist da!\' Er bringt mich um.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elias sprach: \"So wahr der Herr der Heerscharen lebt, vor dem ich stehe! Noch heute zeige ich mich ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Da ging Obadja Achab entgegen und sagte es ihm. Und Achab ging Elias entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Als nun Achab den Elias erblickte, sprach Achab zu ihm: \"Bist du da, du Unglücksbringer Israels?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Er sprach: \"Nicht ich habe Israel ins Unglück gebracht, sondern du und das Haus deines Vaters. Ihr verließet des Herrn Gebote, und du folgtest den Baalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Nun aber sende hin und versammle zu mir ganz Israel auf dem Berge Karmel und auch die 450 Baalspropheten samt den 400 Ascherapropheten, die an Izebels Tisch essen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Da sandte Achab zu allen Israeliten und lud die Propheten auf den Berg Karmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Da trat Elias zum ganzen Volk und sprach: \"Wie lange hinket ihr nach beiden Seiten? Ist der Herr Gott, so folgt ihm. Ist es aber Baal, so folgt diesem!\" Das Volk aber erwiderte ihm nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Da sprach Elias zum Volk: \"Ich bin allein übrig als Prophet des Herrn. Der Baalspropheten dagegen sind es 450 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'So gebe man uns zwei Farren! Sie mögen sich einen Farren wählen, zerstückeln und auf das Holz legen, ohne Feuer anzumachen! Ich richte den anderen Farren her und lege ihn auf das Holz, zünde aber auch kein Feuer an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Dann ruft ihr eures Gottes Namen an, und ich rufe den Namen des Herrn an. Der Gott, der mit Feuer antwortet, ist der Gott.\" Da antwortete das ganze Volk und sprach: \"Der Vorschlag ist gut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Darauf sprach Elias zu den Baalspropheten: \"Wählt euch den einen Farren und richtet ihn zuerst zu! Denn ihr seid die Mehrzahl. Und ruft eures Gottes Namen an! Aber Feuer legt nicht daran!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Da nahmen sie den Farren, den man ihnen gab, und richteten ihn her. Dann riefen sie den Namen des Baal an, vom Morgen bis zum Mittag: \"Baal, erhöre uns!\" Aber da gab es keinen Laut und keine Antwort. Und sie hinkten um den Altar, den man gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Am Mittag verspottete sie Elias und sprach: \"Ruft recht laut! Obgleich er Gott ist, so ist er wohl in Gedanken oder ist beiseite gegangen oder auf Reisen! Vielleicht schläft er gar und wird dann aufwachen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Da riefen sie noch lauter und machten sich nach ihrem Brauch Einschnitte mit Schwertern und Spießen, bis an ihnen Blut herabrann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Als der Mittag vorüber war, rasteten sie bis zur Zeit der Darbringung des Speiseopfers. Aber kein Laut, keine Antwort! Nichts war zu merken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Da sprach Elias zum ganzen Volke: \"Tretet zu mir her!\" Da trat alles Volk zu ihm. Da besserte er den eingerissenen Altar des Herrn aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elias nahm nämlich zwölf Steine nach der Zahl der Stämme der Söhne Jakobs, an den des Herrn Wort ergangen: \"Israel sei dein Name!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Aus den Steinen baute er einen Altar im Namen des Herrn und machte einen Graben, der an zwei Maß Korn faßte, rings um den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Dann schichtete er das Holz, zerstückte den Farren und legte ihn auf das Holz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Dann sprach er: \"Füllt vier Eimer mit Wasser und gießt es auf das Brandopfer und das Holz!\" Dann sprach er: \"Tut es noch einmal!\" Sie taten es noch einmal. Dann sprach er: \"Tut es zum drittenmal!\" Und sie taten es zum drittenmal. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Und das Wasser floß rings um den Altar, und auch den Graben füllte das Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Um die Zeit der Darbringung des Speiseopfers trat nun der Prophet Elias hin und sprach: \"Herr, Du Gott Abrahams, Isaaks und Israels! Heute werde kund, daß Du Gott bist in Israel und ich Dein Knecht und daß ich all dies auf Dein Geheiß getan habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Erhöre mich, Herr, erhöre mich, daß dies Volk erkenne, daß Du, Herr, der wahre Gott bist! Bekehre ihre Herzen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Da:fiel des Herrn Feuer herab, verzehrte das Brandopfer, das Holz, die Steine und das Erdreich und leckte das Wasser im Graben auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Das ganze Volk sah es. Da fielen sie auf ihr Antlitz und riefen: \"Der Herr ist der wahre Gott. Der Herr ist der wahre Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Da sprach Elias zu ihnen. \"Ergreift die Baalspropheten! Keiner von ihnen entkomme!\" Sie ergriffen sie. Elias führte sie an den Kisonbach und schlachtete sie dort ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Dann sprach Elias zu Achab: \"Geh hinauf! Iß und trink! Schon läßt sich das Rauschen des Regens hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Da ging Achab hinauf, zu essen und zu trinken. Elias aber stieg auf den Gipfel des Karmel, bückte sich zur Erde und legte sein Antlitz zwischen seine Knie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Dann sprach er zu seinem Diener: \"Geh doch hinauf und schaue westwärts!\" Er ging hinauf, blickte aus und sprach: \"Nichts ist da.\" Er sprach: \"Gehe noch siebenmal hin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Beim siebtenmal sprach er: \"Eine Wolke, klein wie eine Manneshand, steigt aus dem Meer.\" Da sprach er: \"Geh hinauf und sage zu Achab: \'Spann an und fahr hinab! Daß dich nicht der Regen aufhalte!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Inzwischen ward der Himmel schwarz von Gewitterwolken, und ein starker Regen fiel. Achab fuhr nun ab und kam nach Jezreel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Über Elias aber kam des Herrn Hand. Er gürtete seine Lenden und lief vor Achab bis Jezreel her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Achab aber erzählte Izebel alles, was Elias getan, und daß er alle Propheten mit dem Schwert getötet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Da sandte Izebel an Elias einen Boten und ließ ihm sagen: \"Die Götter sollen das tun und das beifügen, wenn ich nicht morgen um diese Zeit dein Leben dem Ihrigen gleich mache!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Da bekam er Angst. Er brach auf und ging, sein Leben zu retten. So kam er nach Beerseba in Juda. Hier ließ er seinen Diener zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Er aber ging in die Wüste, eine Tagereise weit hinein. Er kam und setzte sich unter einen Ginsterbusch. Da wünschte er zu sterben. Er sprach. \"Es ist genug. Nimm, Herr, jetzt mein Leben! Denn ich bin nicht mehr wert als meine Väter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Dann legte er sich hin und schlief unter einem Ginsterstrauch. Und siehe, da berührte ihn ein Engel und sprach zu ihm: \"Steh auf und iß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Er schaute. Da war zu seinen Häupten ein gerösteter Kuchen und ein Krug mit Wasser. Er aß und trank und legte sich wieder hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Da kam des Herrn Engel zum zweitenmal, berührte ihn und sprach: \"Steh auf und iß! Sonst ist der Weg für dich zu weit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Da stand er auf, aß und trank und ging in der Kraft dieser Speise vierzig Tage und vierzig Nächte bis zum Gottesberg Horeb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Dort trat er in eine Höhle und blieb hier über Nacht. Da erging das Wort des Herrn an ihn, und er sprach zu ihm: \"Was willst du hier, Elias?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Er sprach: \"Ich habe für den Herrn, den Gott der Heerscharen, geeifert. Denn die Söhne Israels haben Deinen Bund verlassen, Deine Altäre niedergerissen und Deine Propheten mit dem Schwerte getötet. Nur ich alleine bin übrig. Nun trachten sie auch mir nach dem Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Er sprach: \"Geh hinaus und tritt auf den Berg vor den Herrn!\" Da zog der Herr vorüber. Vor dem Herrn zog ein großer, heftiger Sturmwind einher, Berge rüttelnd und Felsen schütternd. Aber der Herr war nicht im Sturme. Nach dem Sturme kam ein Erdbeben. Aber der Herr war nicht im Erdbeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Nach dem Erdbeben kam Feuer. Aber der Herr war nicht im Feuer. Nach dem Feuer kam eine leise, feine Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Als Elias dies hörte, hüllte er sein Antlitz in seinen Mantel, ging hinaus und trat an den Eingang der Höhle. Da redete ihn eine Stimme an und sprach: \"Was willst du hier, Elias?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Er sprach: \"Ich habe für den Herrn, den Gott der Heerscharen, geeifert. Denn die Israeliten haben Deinen Bund verlassen, Deine Altäre niedergerissen und Deine Propheten mit dem Schwerte getötet. Ich allein bin übrig. Aber sie trachten auch mir nach dem Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Da sprach der Herr zu ihm: \"Auf! Kehr um auf deinem Weg nach der Wüste von Damaskus! Geh hinein und salbe Chazael zum König über Aram!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Auch Jehu, Nimsis Sohn, sollst du zum König über Israel salben! Dann sollst du Elisäus, Saphats Sohn, von Abel Mechola, zum Propheten an deiner Statt salben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Wer dem Schwerte Chazaels entrinnt, den tötet Jehu, und wer Jehus Schwert entrinnt, den tötet Elisäus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Doch lasse ich in Israel 7.000 übrig, alle Knie, die sich nicht vor Baal gebeugt, und jeden Mund, der ihn nicht geküßt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'So ging er von dannen und traf Saphats Sohn Elisäus, der pflügte. Zwölf Paare waren bei ihm. Er selber war beim zwölften. Da ging Elias zu ihm hinüber und warf auf ihn seinen Mantel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Da ließ er die Rinder, eilte Elias nach und sprach: \"Laß mich Vater und Mutter küssen! Dann folge ich dir.\" Er sprach: \"Geh und komm wieder! Was habe ich mit dir zu tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'So ging er von ihm, nahm das Rinderpaar und schlachtete es. Mit dem Geschirr der Rinder kochte er das Fleisch und gab es den Leuten zum Essen. Dann brach er auf, folgte Elias und ward sein Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Benhadad, Arams König, aber zog sein ganzes Heer zusammen. Zweiunddreißig Könige waren bei ihm samt Rossen und Wagen. So zog er heran, schloß Samaria ein und berannte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Er sandte zu Achab, Israels König, Boten in die Stadt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'und ließ ihm sagen: \"So spricht Benhadad: \'Dein Silber und Gold ist mein. Doch deine Weiber und deine tüchtigen Söhne sollen dir verbleiben.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Da antwortete ihm Israels König: \"Nach deinem Worte, mein Herr und König! Dein bin ich und alles, was mein ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Die Boten aber kamen wieder und sprachen: \"So spricht Benhadad: \'Ich habe dir entboten: Dein Silber und Gold, aber auch deine Weiber und deine Söhne sollst du mir geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Wenn ich morgen um diese Zeit meine Diener zu dir sende, durchsuchen sie dein Haus und deiner Diener Häuser. Dann nehmen sie alles, was dir teuer ist, und tragen es fort.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Da berief Israels König alle Ältesten des Landes und sprach: \"Erkennet und sehet, daß dieser Böses vorhat! Denn er schickt jetzt zu mir wegen meiner Weiber und meiner Söhne. Wäre es bloß Silber und Gold, dann versagte ich es ihm nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Da sprachen alle Ältesten und das ganze Volk zu ihm: \"Hör nicht darauf und willige nicht ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Da sprach er zu Benhadads Boten: \"Sagt meinem Herrn, dem König: \'Alles, was du zuerst deinem Knecht entboten hast, will ich tun. Aber dies kann ich nicht tun.\'\" Die Boten gingen nun und brachten ihm den Bescheid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Da sandte Benhadad zu ihm und ließ sagen: \"Die Götter mögen mir dies und das tun, wenn der Schutt Samarias allen meinen Leuten bei mir die hohlen Hände füllen könnte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Da erwiderte Israels König und sprach: \"Meldet! Wer sich erst wappnet, rühme sich nicht schon gleich dem, der die Rüstung wieder ablegt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Er hörte diese Antwort, als er eben mit den Königen in den Zelten zechte. Da sprach er zu seinen Dienern: \"Greift an!\" Da griffen sie die Stadt an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Da trat ein Prophet zu Israels König Achab und sprach: \"So spricht der Herr: \'Siehst du diesen ganzen großen Haufen? Ich gebe ihn heute in deine Hand, damit du erkennest, daß ich der Herr bin.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Da sprach Achab: \"Durch wen?\" Er sprach: \"So spricht der Herr: \'Durch die Jungmannschaft der Landvögte.\'\" Er sprach: \"Wer soll den Kampf eröffnen?\" Er sagte: \"Du.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'So musterte er die Jungmannschaft der Landvögte. Es waren 232. Hernach musterte er das ganze Volk, alle Israeliten, 7.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Sie rückten nun am Mittag aus. Benhadad zechte eben in den Lauben bis zur Trunkenheit, er und die zweiunddreißig Könige, die ihm beistanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'So rückte die Jungmannschaft der Landvögte zuerst aus. Da sandte man zu Benhadad und ließ ihm melden: \"Aus Samaria rückt Mannschaft aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Er sprach: \"Ziehen sie in Frieden aus, dann fangt sie lebendig! Ziehen sie aber zum Kampf aus, dann fangt sie auch lebendig!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Jene aber zogen aus der Stadt, der Landvögte Jungmannschaft und das Heer, das ihnen nachzog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Da schlugen sie, jeder seinen Mann. Die Aramäer flohen, und Israel verfolgte sie. Arams König Benhadad aber entrann auf einem Reitpferd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Dann zog Israels König aus und schlug die Rosse und die Wagen. So schlug er die Aramäer gewaltig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Da trat der Prophet zum König von Israel und sprach zu ihm: \"Wohlan! Verstärke dich und siehe wohl zu, was du tun willst! Denn im nächsten Jahr zieht Arams König wieder gegen dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Nun sprachen die Diener des Königs von Aram zu ihm: \"Ihre Götter sind Berggötter. Deshalb haben sie uns besiegt. Kämpften wir aber in der Ebene mit ihnen, dann besiegten wir sie sicherlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tu dies also: Entsetze die Könige, jeden seiner Stellung, und ersetze sie durch Statthalter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Dann sollst du dir selbst ein Heer zusammenbringen wie das Heer, das dir abhanden gekommen, und Rosse und Wagen wie jene früheren Dann wollen wir sie in der Ebene bekämpfen. Wir werden sie sicherlich besiegen.\" Und er hörte auf ihren Rat und tat so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Im nächsten Jahre musterte Benhadad die Aramäer. Dann zog er nach Aphek zum Kampf mit Israel hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Auch die Israeliten wurden gemustert und mit Mundvorrat versorgt. Dann zogen sie jenen entgegen. Die Israeliten aber lagerten ihnen gegenüber wie ein paar erschöpfte Ziegen. Die Aramäer aber füllten das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Da trat der Gottesmann herzu und sprach zum König von Israel und sagte: \"So spricht der Herr: \'Weil die von Aram ausgesagt, ein Berggott sei der Herr, doch nicht ein Gott der Täler, so gebe ich in deine Hand den ganzen großen Haufen hier, auf daß ihr seht: Ich bin der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'So lagerten die einen den anderen sieben Tage gegenüber. Am siebten Tage aber begann die Schlacht, und die Israeliten schlugen von den Aramäern 100.000 Mann Fußvolk an einem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Die übrigen aber flohen nach Aphek in die Stadt. Da fiel die Mauer, als die übriggebliebenen 27.000 Mann darin waren. Auch Benhadad war geflohen; so kam er in die Stadt und verbarg sich in einem Schlupfwinkel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Da sprachen seine Diener zu ihm: \"Wir haben gehört, daß die Könige des Hauses Israel milde Könige seien. Wir wollen härene Gewänder um unsere Hüften legen und Stricke an unsere Häupter und so zum König von Israel hinausgehen. Vielleicht läßt er dich leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'So legten sie um ihre Hüften härene Gewänder und an ihre Häupter Stricke, gingen zum König von Israel und sprachen: \"Dein Sklave Benhadad läßt sagen: \'Laß mich leben!\'\" Da sprach er: \"Lebt er noch? Er ist mein Bruder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Die Leute aber faßten dies als gutes Vorzeichen auf. Sie griffen es von ihm schleunigst auf und sprachen. \"Dein Bruder ist Benhadad?\" Er sprach: \"Geht hin und holt ihn!\" Da ging Benhadad zu ihm hinaus. Und er ließ ihn auf seinen Wagen steigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Da sprach er zu ihm: \"Die Städte, die mein Vater deinem Vater weggenommen, will ich zurückgeben. Du darfst dir auch in Damaskus Bazare anlegen, wie mein Vater es in Samaria getan. Willst du mich auf Grund eines solchen Vertrages freilassen?\" Da schloß er einen Vertrag mit ihm und ließ ihn frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Da sprach einer von den Prophetensöhnen zu seinem Gefährten auf des Herrn Geheiß: \"Schlage mich!\" Jener aber weigerte sich, ihn zu schlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Da sprach dieser zu ihm: \"Weil du dem Befehle des Herrn nicht gehorchst, töte dich ein Löwe, wenn du von mir weggehst.\" Und als er von ihm ging, traf ihn ein Löwe und schlug ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Dann traf er einen anderen Mann und sprach: \"Schlage mich!\" Und dieser schlug ihn wund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Nun ging der Prophet hin und stellte sich dem König in den Weg. Dabei machte er sich unkenntlich durch eine Binde über den Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Als nun der König vorüberkam, schrie er den König an und sprach: \"Dein Sklave war mit in die Schlacht gezogen. Da trat ein Mann heraus, brachte mir einen Mann und sprach: \'Bewache diesen Mann! Wenn er vermißt wird, dann haftet dein Leben für das seinige, oder du mußt ein Talent Silber bezahlen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Nun hatte dein Sklave bald da, bald dort zu tun. Da war jener nicht mehr da.\" Da sprach der König von Israel zu ihm: \"Da hast du dein Urteil selbst gefällt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Nun riß jener eilends die Binde von seinen Augen, und der König erkannte, daß er einer der Propheten war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Da sprach jener zu ihm: \"So spricht der Herr: \'Weil du den mir verfallenen Mann freigelassen, so sei dein Leben für sein Leben, dein Volk für sein Volk!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Mißmutig und verstört ging der König von Israel in sein Haus. So kam er nach Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Nach diesen Begebnissen geschah folgendes: Der Jezreeliter Nabot besaß zu Jezreel einen Weinberg neben dem Palaste Achabs, des Königs von Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Achab sprach zu Nabot. \"Gib mir deinen Weinberg, daß er ein Gemüsegarten werde! Er liegt so nahe bei meinem Haus. Ich gebe dir dafür einen besseren Weinberg. Ist es dir aber lieber, so gebe ich dir Geld in seinem Wert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nabot aber sprach zu Achab: \"Bewahre mich der Herr davor, daß ich dir meiner Väter Erbe weggäbe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Da kam Achab in sein Haus, mißmutig und verstört ob der Antwort des Jezreeliters Nabot, der sprach: \"Ich gebe dir nicht meiner Väter Erbe.\" Er legte sich zu Bett, wandte sein Gesicht ab und aß nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Da kam seine Gemahlin Izebel zu ihm und fragte ihn: \"Warum bist du mißmutig und issest nichts?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Er sprach zu ihr: \"Rede ich da mit dem Jezreeliter Nabot und sage ihm: \'Gib mir für Geld deinen Weinberg oder, ist es dir lieber, dann gebe ich dir einen anderen Weinberg dafür\', da sagte er: \'Ich gebe dir meinen Weinberg nicht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Da sprach seine Gemahlin Izebel zu ihm: \"Nun mußt du das Königtum in Israel wirklich ausüben. Steh auf! Iß Brot und sei guter Dinge! Ich schaffe dir den Weinberg des Jezreeliters Nabot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Dann schrieb sie in Achabs Namen einen Brief und siegelte ihn mit seinem Siegel. Sie sandte den Brief an die Ältesten und Vornehmen, die mit Nabot zusammen in seiner Stadt wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'In dem Brief schrieb sie: \"Ruft ein Fasten aus und setzt Nabot obenan unter den Leuten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Setzt ihm aber zwei Bösewichter gegenüber! Sie sollen ihn anklagen und sprechen: \'Du hast Gott und den König \"gepriesen\" (gelästert)!\' Dann führt ihn hinaus und steinigt ihn zu Tod!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Die Männer seiner Stadt, die Ältesten und Vornehmen, die in seiner Stadt wohnten, taten, wie Izebel ihnen entboten, und wie geschrieben stand in dem Brief, den sie an sie geschickt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Sie riefen ein Fasten aus und setzten Nabot obenan unter den Leuten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Dann kamen die zwei Männer, Teufelsbuben, und setzten sich ihm gegenüber. Und die Teufelsmänner verklagten Nabot angesichts des Volkes und sprachen: \"Nabot hat Gott und den König `gepriesen ́\" So führten sie ihn vor die Stadt und steinigten ihn zu Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Dann ließen sie der Izebel entbieten: \"Nabot ist gesteinigt worden; er ist tot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Sobald Izebel hörte, daß Nabot zu Tod gesteinigt sei, sprach Izebel zu Achab: \"Auf! Nimm des Jezreeliters Weinberg, den er für Geld nicht geben wollte. Denn Nabot lebt nicht mehr. Er ist tot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Sobald Achab hörte, daß Nabot tot sei, stand Achab auf, hinabzugehen zum Weinberg des Jezreeliters Nabot und ihn in Besitz zu nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Da erging des Herrn Wort an den Elias, den Tisbiter:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '\"Auf! Geh hinab, Achab entgegen, dem König Israels zu Samaria!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Und sage zu ihm: \'So spricht der Herr: \'Hast du gemordet, um zu erben?\' Dann sprich zu ihm: So spricht der Herr: \'Dafür, daß Nabots Blut die Hunde aufgeleckt, sollen die Hunde auch dein Blut auflecken!\'\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Da sprach Achab zu Elias: \"Hast du mich gefunden, mein Feind?\" Er sprach: \"Jawohl! Du hast niederträchtig das getan, was dem Herrn mißfällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'So bringe ich Unheil über dich und fege dich hinweg. Ich rotte aus von Achab, was die Wand bepißt, Unmündige und Mündige in Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Ich tue so mit deinem Haus, wie mit dem Haus des Nebatsohnes Jeroboam, wie mit dem Haus des Baësa, des Achiasohnes, des Zornes wegen, den du hast erregt und weil du Israel zur Sünde hast verführt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Auch über Izebel verkündete der Herr: \"Die Hunde fressen auf der Flur von Jezreel Izebel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Wer da von Achab in der Stadt verstirbt, den fressen Hunde, und wer im Freien stirbt, den fressen des Himmels Vögel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Sicherlich gab es niemand mehr, der so niederträchtig das getan hat, was je dem Herrn mißfallen, wie Achab, den sein Weib Izebel dazu verführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Er handelte ganz abscheulich, als er den Scheußlichkeiten nachging, wie einst die Amoriter sie getan, die der Herr vor den Israeliten vertrieben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Als Achab jene Worte hörte, zerriß er seine Kleider, legte ein härenes Gewand um seinen Leib und fastete. Er schlief auch im Bußgewand und ging barfuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Da erging des Herrn Wort an Elias, den Tisbiter:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '\"Hast du gesehen, wie Achab sich vor mir verdemütigt? Dieweil er sich vor mir verdemütigt, so bringe ich das Unheil nicht zu seinen Lebzeiten. Erst unter seinem Sohne füge ich das Unheil seinem Hause zu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Drei Jahre saßen sie ruhig. Da war zwischen Aram und Israel kein Krieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Im dritten Jahre aber zog Judas König Josaphat zum König von Israel hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Da sprach der König von Israel zu seinen Dienern: \"Wißt ihr, daß Ramot in Gilead uns gehört? Wir aber sitzen müßig da, anstatt es dem König von Aram zu nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Dann sprach er zu Josaphat: \"Ziehst du mit mir in den Kampf um Ramot in Gilead?\" Da sprach Josaphat zum König von Israel: \"Ich wie du, mein Volk wie dein Volk, meine Rosse wie deine Rosse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Dann sprach Josaphat zum König von Israel: \"Frage doch erst nach dem Wort des Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Da versammelte Israels König die Propheten, Ungefähr vierhundert Mann, und sprach zu ihnen: \"Soll ich gegen Ramot in Gilead zu Felde ziehen oder es lassen?\" Sie sprachen: \"Ziehe hin! Der Herr gibt es in des Königs Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Da sprach Josaphat: \"Ist hier sonst kein Prophet des Herrn, daß wir ihn befragen könnten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Da sprach der König von Israel zu Josaphat: \"Noch ist einer da, durch den wir den Herrn befragen können. Aber ich hasse ihn. Denn er weissagt über mich nichts Gutes, sondern nur Schlechtes, Mika, Imlas Sohn.\" Da sprach Josaphat: \"Der König rede nicht so!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Da rief der König Israels einen Kämmerling und sprach: \"Hole rasch Imlas Sohn Mika!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Nun saßen der König von Israel und Judas König, Josaphat, jeder auf seinem Thron, in Untergewändern, am Eingang des Tores von Samaria, und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Und Sidkia, Kenaanas Sohn, machte sich eiserne Hörner und sprach: \"So spricht der Herr: \'Mit solchen stößt du die Aramäer bis zur Vernichtung.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Auch alle anderen Propheten weissagten so und sprachen: \"Ziehe nach Ramot in Gilead und sei glücklich! Der Herr gibt es in des Königs Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Der Bote aber, der gegangen war, Mika zu rufen, sprach zu ihm: \"Die Propheten verheißen einstimmig dem König Gutes. Möchte dein Wort einem der Ihrigen gleichen! Sprich nur Gutes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Da sprach Mika: \"So wahr der Herr lebt! Ich rede nur, was der Herr mir sagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'So kam er zum König. Und der König sprach zu ihm: \"Mika! Sollen wir gen Ramot in Gilead zu Felde ziehen oder sollen wir es lassen?\" Er sprach zu ihm: \"Zieh hin und sei glücklich! Der Herr gibt es in des Königs Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Da sprach der König zu ihm: \"Wie oft muß ich dich beschwören, du sollest mir in des Herrn Namen nichts als Wahrheit künden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Da sprach er: \"Ich sehe ganz Israel auf den Bergen zerstreut wie Schafe ohne Hirten. Und also spricht der Herr: \'Sie haben keinen Herrn mehr. Doch kehren sie, ein jeder unversehrt, nach Hause.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Da sprach Israels König zu Josaphat: \"Habe ich dir nicht gesagt: \'Er weissagt über mich nie Gutes, sondern nur Schlimmes?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Da sprach er: \"So hör darum das Wort des Herrn! Ich habe den Herrn auf seinem Throne sitzen sehen, und bei ihm stand das ganze Himmelsheer zur Rechten und zur Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Da sprach der Herr: \'Wer möchte Achab so betören, daß er zu Felde ziehe und in Gilead zu Ramot falle?\' Der eine sagte dies, der andere das.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Da trat der Geist hervor und stellte sich vor den Herrn und sprach: \'Ich möchte ihn betören.\' Da fragte ihn der Herr: \'Womit?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Er sprach: \'Ich gehe aus und werde Lügengeist im Munde aller seiner Seher.\' Er sprach: \'Du wirst betören und es auch vermögen. Gehe hin und tue so!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'So hat der Herr nun einen Lügengeist dem Munde aller dieser deiner Seher eingegeben. Der Herr plant Unheil über dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Da trat Sidkia, Kenaanas Sohn, herzu, schlug Mika auf die Wange und sprach: \"Wie, ist des Herrn Geist von mir gewichen, um mit dir zu reden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Da sprach Mika: \"Das siehst du an jenem Tage, wo du kommst, einen Winkel aufzusuchen, um dich zu verstecken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Da sprach der König von Israel: \"Nimm den Mika und übergib ihn dem Obersten der Stadt, Amon, und dem Königssohn Joas!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Sag, so spricht der König: \'Werft diesen in den Kerker und nährt ihn kärglich mit Brot und Wasser, bis ich heil heimkomme!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Da sprach Mika: \"Kehrst du wirklich heil heim, dann hat der Herr nicht durch mich geredet.\" Und er sprach: \"Hört dies, all ihr Leute!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'So zogen der König Israels und Judas König Josaphat gen Ramot in Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Und der König von Israel sprach zu Josaphat: \"Es gilt, sich verkleidet in den Kampf zu stürzen. Du aber behalte deine Gewänder an!\" So verkleidete sich Israels König und zog in den Kampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Der König von Aram aber befahl den Obersten seiner Streitwagen zwei- oder dreimal: \"Kämpft mit niemand anderem, gering oder vornehm, als allein mit dem König von Israel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Als nun die Obersten der Streitwagen den Josaphat sahen, sprachen sie: \"Das kann nur der König von Israel sein.\" Und sie lenkten auf ihn zu, ihn anzugreifen. Da schrie Josaphat auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Als nun die Obersten der Streitwagen sahen, daß es nicht der König von Israel war, ließen sie von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Nun spannte ein Mann von ungefähr den Bogen, da traf er den König von Israel zwischen Ringelgurt und Panzer. Da sprach er zu seinem Wagenlenker: \"Wende um und fahre mich aus dem Getümmel! Denn ich bin verwundet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Aber der Kampf entbrannte an jenem Tage immer stärker, und so blieb der König im Wagen, gestützt, den Aramäern gegenüber. Abends starb er. Das Blut aber ergoß sich aus der Wunde ins Wageninnere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Da erscholl im Lager bei Sonnenuntergang der Ruf: \"Jeder in seine Stadt und in sein Land!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'So starb der König. Er kam nach Samaria, und zu Samaria begrub man den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Als man den Wagen an Samarias Teich abspülte, leckten die Hunde sein Blut und reinigten die Riemen nach dem Worte des Herrn, das er gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Ist nicht der Rest der Geschichte Achabs und alles, was er getan, sowie das Elfenbeinhaus und alle Städte, die er gebaut, im Buch der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'So legte sich Achab zu seinen Vätern, und sein Sohn Achazja ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'König in Juda ward Asas Sohn Josaphat im vierten Jahre Achabs, des Königs von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Josaphat war fünfunddreißig Jahre alt, als er König wurde, und regierte zu Jerusalem fünfundzwanzig Jahre. Seine Mutter hieß Azuba und war des Silchi Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Er wandelte ganz auf seines Vaters Asa Weg und wich nicht von ihm ab. Er tat, was dem Herrn gefiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Nur die Höhen waren nicht beseitigt worden. Noch opferte und räucherte das Volk auf den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Josaphat aber hielt mit dem König von Israel Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Ist nicht der Rest der Geschichte Josaphats und seiner tapferen Taten, die er getan, und wie er Krieg geführt, im Buche der Geschichte der Könige Judas aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Auch tilgte er aus dem Lande den Rest der Tempeldirnen, die aus der Zeit seines Vaters Asa noch übrig waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'In Edom aber war kein König als Herrscher eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josaphat baute auch zu Esiongeber Tarsisschiffe, die nach Ophir zum Goldholen fahren sollten. Aber man kam nicht hin; denn die Schiffe scheiterten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Damals sprach Achabs Sohn Achazja zu Josaphat: \"Meine Knechte könnten mit deinen Knechten auf den Schiffen fahren.\" Aber Josaphat wollte nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Als sich Josaphat zu seinen Vätern legte, ward er bei seinen Vätern in seines Ahnen David Stadt begraben. An seiner Statt ward sein Sohn Joram König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Achabs Sohn Achazja ward König über Israel zu Samaria im siebzehnten Jahr des Judakönigs Josaphat. Er regierte über Israel zwei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Er tat, was dem Herrn mißfiel, und wandelte auf dem Wege seines Vaters und seiner Mutter sowie auf dem Wege des Nebatsohnes Jeroboam, der Israel zur Sünde verführt hatte. Er diente dem Baal und betete ihn an. So kränkte er den Herrn, Israels Gott, ganz wie sein Vater getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Und nach Achabs Tod fiel Moab von Israel ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Achazja aber fiel gegen das Gitter in seinem Obergemach zu Samaria und ward verletzt. Da sandte er Boten und sprach zu ihnen: \"Geht und befragt den Gott von Ekron, Beelzebub, ob ich von der Wunde da genesen würde!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Da sprach des Herrn Engel zu Elias, dem Tisbiter: \"Auf! Geh hinauf, den Boten des Königs von Samaria entgegen und sprich zu ihnen: \'Gibt es in Israel keinen Gott, daß ihr hingeht, den Gott von Ekron, Beelzebub, zu befragen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Darum spricht der Herr: \"Vom Bett, auf das du dich gelegt, kommst du nicht mehr herunter, sondern du stirbst.\"\'\" Dann ging Elias weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Die Boten kehrten zum König zurück. Er sprach zu ihnen. \"Warum kommt ihr wieder?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Sie sprachen zu ihm: \"Ein Mann ist heraufgekommen, uns entgegen; er sprach zu uns: \'Geht! Kehrt zum König, der euch sendet, zurück und sagt ihm: \"So spricht der Herr: Gibt es in Israel keinen Gott, daß du zu Beelzebub, dem Gott von Ekron, sendest, ihn zu befragen? Darum kommst du von dem Bett, auf das du dich gelegt, nicht mehr herunter, sondern du stirbst.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Er sprach zu ihnen: \"Wie sah der Mann aus, der euch entgegengekommen ist und solches zu euch gesprochen hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Sie sagten zu ihm: \"Es war ein haariger Mann mit einem Ledergurt um die Hüften.\" Er sprach: \"Das ist Elias, der Tisbiter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Da schickte er nach ihm hinauf. Er aber saß oben auf dem Berggipfel. Jener redete ihn an: \"Gottesmann! Der König befiehlt: \'Komm herab!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Da antwortete Elias und sprach zu dem Hauptmann der Fünfzig: \"Bin ich ein Gottesmann, dann falle Feuer vom Himmel und fresse dich samt deinen Fünfzig!\" Da fiel Feuer vom Himmel und fraß ihn samt seinen Fünfzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Da schickte er wieder einen anderen Hauptmann über Fünfzig nach ihm mit seinen Fünfzig. Er hob an und sprach zu ihm: \"Gottesmann! So befiehlt der König: \'Komm eilends herab!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Da erwiderte Elias und sprach zu ihnen: \"Bin ich ein Gottesmann, dann falle Feuer vom Himmel und fresse dich samt deinen Fünfzig!\" Da fiel Feuer vom Himmel und fraß ihn samt seinen Fünfzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Da schickte er nochmals einen dritten Hauptmann und seine Fünfzig. Er ging hinauf. Als aber dieser dritte Hauptmann über Fünfzig kam, beugte er seine Knie vor Elias und redete ihn flehend an: \"Gottesmann! Laß mein Leben und das dieser fünfzig Knechte dir teuer sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Feuer ist ja vom Himmel gefallen und hat die beiden ersten Hauptleute über die Fünfzig samt ihren Fünfzig aufgezehrt. Nun laß mein Leben dir teuer sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Da sprach des Herrn Engel zu Elias: \"Geh mit ihm hinab! Fürchte dich nicht vor ihm!\" So stand er auf und ging mit ihm zum König hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Er sprach zu ihm: \"So spricht der Herr: \'Du hast Boten gesandt, Ekrons Gott, Beelzebub, zu befragen. Ist kein Gott in Israel, ihn um sein Wort anzugehen? Deshalb kommst du von dem Bett nicht mehr herab, auf das du dich gelegt, sondern du stirbst.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Also starb er nach des Herrn Wort, das er an Elias gerichtet hatte. Joram ward an seiner Statt König im zweiten Jahre des Judakönigs Joram, des Josaphatsohnes. Er hatte nämlich keinen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Ist nicht der Rest dessen, was Achazja getan, im Buche der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Als aber der Herr den Elias im Sturm himmelwärts fahren lassen wollte, ging Elias mit Elisäus aus dem Gilgal weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Und Elias sprach zu Elisäus: \"Bleib hier! Denn der Herr schickt mich bis Betel.\" Da sprach Elisäus: \"So wahr der Herr lebt und du lebst! Ich lasse dich nicht.\" So gingen sie nach Betel hinab. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Da kamen die Prophetensöhne in Betel zu Elisäus heraus und sprachen zu ihm: \"Weißt du, daß heute der Herr deinen Meister über dein Haupt hinweg entrückt?\" Er sprach: \"Auch ich weiß es. Seid still!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Da sprach Elias zu ihm: \"Elisäus, bleib hier! Denn der Herr schickt mich nach Jericho.\" Da sprach er: \"So wahr der Herr lebt und du lebst! Ich lasse dich nicht.\" So kamen sie nach Jericho.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Da traten die Prophetensöhne in Jericho an Elisäus heran und sprachen zu ihm: \"Weißt du, daß heute der Herr deinen Meister dir über deinem Haupt entrückt?\" Er sprach. \"Auch ich weiß es. Seid still!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Da sprach Elias zu ihm: \"Bleib hier! Denn der Herr schickt mich an den Jordan.\" Da sprach er: \"So wahr der Herr lebt und du lebst! Ich lasse dich nicht.\" So gingen die beiden weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Fünfzig Mann aber von den Prophetensöhnen waren mitgegangen. Sie stellten sich abseits von ferne auf. Die beiden aber traten an den Jordan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Da nahm Elias seinen Mantel, rollte ihn zusammen und schlug damit auf das Wasser. Da teilte es sich nach beiden Seiten, und die beiden kamen trocken hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Als sie hinübergegangen waren, sprach Elias zu Elisäus: \"Bitte doch um irgend etwas, was ich dir tun soll, bevor ich von dir entrückt werde!\" Da sprach Elisäus: \"Möchten doch zwei Drittel deines Geistes mir werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Da sprach er: \"Du bittest um Schweres. Siehst du mich, wie ich von dir entrückt werde, dann wird es dir zuteil. Wenn nicht, dann geschieht es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Wie sie so im Gehen redeten, erschien ein Feuerwagen mit Feuerrossen. Sie trennten beide. Und Elias fuhr im Sturme himmelwärts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Als dies Elisäus sah, rief er: \"Mein Vater, mein Vater! Israels Wagen und Lenker!\" Dann sah er ihn nicht mehr. Da faßte er seine Kleider und zerriß sie in zwei Stücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Dann hob er den Mantel des Elias auf, der diesem entfallen war, kehrte um und trat an das Jordanufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Er nahm nun des Elias Mantel, der diesem entfallen war, schlug damit auf das Wasser und sprach. \"Wo ist der Herr, des Elias Gott?\" Als er aber aufs Wasser schlug, teilte es sich nach beiden Seiten, und Elisäus schritt hindurch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Die Prophetensöhne nun sahen ihn in Jericho herüber. Da sprachen sie: \"Des Elias Geist ruht auf Elisäus.\" Und sie kamen ihm entgegen und neigten sich vor ihm bis zum Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Dann sprachen sie zu ihm: \"Bei deinen Sklaven sind fünfzig rüstige Männer. Laß sie gehen und deinen Meister suchen, ob ihn etwa ein Sturm des Herrn entführt und ihn auf einen der Berge oder in eines der Täler geworfen hat!\" Er sprach: \"Sendet sie nicht aus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Sie aber drangen bis zum äußersten in ihn. Da sprach er: \"So sendet eben hin!\" Da sandten sie fünfzig Mann aus. Sie suchten ihn drei Tage, fanden ihn aber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Dann kehrten sie zu ihm zurück, da er noch in Jericho war. Er sprach zu ihnen: \"Habe ich euch nicht gesagt, ihr sollet nicht gehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Die Männer der Stadt aber sprachen zu Elisäus: \"Die Lage der Stadt ist trefflich, wie unser Herr selbst sieht. Aber das Wasser ist schlecht, und die Gegend verursacht Fehlgeburten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Da sprach er: \"Bringt mir eine neue Schale und tut Salz hinein!\" Sie brachten sie ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Da ging er an den Quellort des Wassers hinaus, warf Salz hinein und sprach: \"So spricht der Herr: \'Ich mache dies Wasser gesund. Fortan soll nicht Tod noch Fehlgeburt sein.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'So ward das Wasser gesund bis auf diesen Tag, nach des Elisäus Wort, das er gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Von da ging er nach Betel hinauf. Als er den Weg hinaufging, kamen kleine Knaben aus der Stadt. Sie verspotteten ihn und riefen ihm nach: \"Kahlkopf, komm herauf! Kahlkopf, komm herauf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Da wandte er sich um, sah sie an und fluchte ihnen in des Herrn Namen. Da kamen zwei Bärinnen aus dem Wald und zerrissen von ihnen zweiundvierzig Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Von dort ging er auf den Berg Karmel und von hier kehrte er nach Samaria zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram aber, Achabs Sohn, ward zu Samaria König über Israel im achtzehnten Jahre des Judakönigs Josaphat. Er regierte zwölf Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Er tat, was dem Herrn mißfiel, doch nicht so, wie sein Vater und seine Mutter. Er beseitigte den Baaldenkstein, den sein Vater gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Nur an des Nebatsohns Jeroboam Sünden, der Israel zur Sünde verführt hat, hielt er fest und ließ nicht davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mesa aber, Moabs König, war Schafzüchter und hatte als Steuer dem König von Israel hunderttausend Lämmer und hunderttausend Wollwidder zu liefern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Als Achab starb, fiel Moabs König von Israels König ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'König Joram aber zog zu jener Zeit von Samaria aus und musterte ganz Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Dann ging er hin und sandte an Judas König Josaphat die Botschaft: \"Der König von Moab ist von mir abgefallen. Ziehst du mit mir gegen Moab in den Krieg?\" Er sprach: Ja! Ich wie du, mein Volk wie dein Volk, meine Rosse wie deine Rosse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Dann fragte er: \"Welchen Weg sollen wir ziehen?\" Er sprach: \"Den Steppenweg nach Edom.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'So zog Israels König mit dem Judakönig und dem König von Edom dahin. Als sie aber sieben Tage auf dem Umgehungsmarsche waren, hatte weder das Heer noch das Vieh, das ihnen folgte, Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Da sprach der König Israels: \"Wehe! Der Herr hat diese drei Könige hergerufen, um sie in Moabs Hand zu geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Da sprach Josaphat: \"Ist hier kein Prophet des Herrn, daß wir durch ihn den Herrn befragen?\" Da meinte einer der Diener des Königs von Israel: \"Hier ist Saphats Sohn Elisäus, der Wasser über des Elias Hände gegossen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Da sprach er: \"Bei ihm ist das Wort des Herrn.\" So gingen Israels König und Josaphat und der König von Edom zu ihm hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Elisäus fragte nun den König von Israel: \"Was habe ich mit dir zu tun? Geh zu den Propheten deines Vaters und deiner Mutter!\" Da sprach zu ihm der König von Israel: \"Daß doch nicht der Herr diese drei Könige hergerufen hat, um sie in Moabs Hand zu geben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Da sprach Elisäus: \"So wahr der Herr der Heerscharen, dem ich diene, lebt! Achtete ich nicht auf Judas König Josaphat, so würdigte ich dich keines Blickes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Jetzt aber holt mir einen Saitenspieler!\" Als der Saitenspieler spielte, kam die Hand des Herrn auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Und er sprach: \"So spricht der Herr: \'Macht in diesem Tale Grube an Grube!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Denn so spricht der Herr: \'Ihr seht weder Wind noch Regen, und dennoch füllt sich dieses Tal mit Wasser, daß ihr samt euren Scharen und eurem Vieh zu trinken habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Das ist aber dem Herrn noch zu wenig. Er gibt auch Moab in eure Hand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'daß ihr alle festen Städte zerstöret, alle auserlesenen Städte, alle Fruchtbäume fället, alle Wasserquellen verstopfet und alle guten Äcker durch Steine verderbet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Am anderen Morgen, zur Zeit der Darbringung des Speiseopfers, kam Wasser vom Weg nach Edom, und die Gegend füllte sich mit Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Als aber Moab hörte, daß die Könige heranzögen, sie anzugreifen, ward alles aufgeboten, vom halbwüchsigen Burschen an und darüber. Und sie stellten sich an der Grenze auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Frühmorgens nun strahlte die Sonne über dem Wasser auf. Da erschien den Moabitern drüben das Wasser rot wie Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Sie sprachen: \"Das Blut bedeutet, daß die Könige vernichtet sind. Sie rieben einander auf. Nun auf, Moab, zur Beute!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'So kamen sie zu Israels Lager. Da rückte Israel aus und schlug Moab, daß es vor ihm floh. Dadurch wurden sie angereizt, Moab niederzuschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Die Städte rissen sie nieder und auf alle guten Äcker warfen sie Mann für Mann einen Stein und füllten sie damit an. Alle Wasserquellen verstopften sie und fällten alle Fruchtbäume, bis nur die Steine an der Mauer von Kir Charset übrigblieben. Und dies umzingelten die Schleuderer und beschossen es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Als Moabs König sah, daß der Angriff gegen ihn zu stark sei, nahm er siebenhundert schwertbewaffnete Mannen mit sich, um beim König von Edom durchzubrechen. Aber sie vermochten es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Da nahm er seinen erstgeborenen Sohn, der nach ihm König werden sollte, und opferte ihn auf der Mauer als Brandopfer. Nun kam ein großer Zorn über Israel. Sie ließen von ihm und kehrten heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Eines von den Weibern der Prophetensöhne aber schrie Elisäus also an: \"Dein Sklave, mein Mann, ist gestorben. Du selbst weißt, daß dein Sklave den Herrn gefürchtet hat. Nun kommt der Gläubiger und will sich meine beiden Knaben zu Sklaven nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Da fragte sie Elisäus: \"Was soll ich für dich tun? Sag mir: Was hast du im Haus?\" Sie sprach: \"Deine Sklavin hat nichts im Haus als einen Krug Öl.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Da sprach er: \"Auf! Borge dir Gefäße draußen, von all deinen Nachbarn leere Gefäße, aber nicht zuwenig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Dann gehe hinein! Schließ die Tür hinter dir und deinen Söhnen und gieß in alle diese Gefäße ein! Ist eines voll, dann stelle es beiseite!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Sie ging von ihm weg. Dann schloß sie die Tür hinter sich und ihren Söhnen. Sie reichten ihr zu, und sie goß ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Als die Gefäße voll waren, sprach sie zu ihrem Sohn: \"Reiche mir noch ein Gefäß!\" Da sprach er zu ihr: \"Es ist kein Gefäß mehr da.\" Da hörte das Öl zu fließen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Sie kam und meldete es dem Gottesmann. Er sprach: \"Auf! Verkaufe das Öl und bezahle deinen Gläubiger! Vom übrigen magst du mit deinen Söhnen leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Eines Tages nun ging Elisäus durch Sunem. Dort war eine reiche Frau. Sie nötigte ihn zu speisen. Sooft er dann vorüberkam, kehrte er dort zum Speisen ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Da sprach sie zu ihrem Manne: \"Ich merke, daß es ein heiliger Gottesmann ist, der stets bei uns vorüberkommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Wir wollen ein kleines, ummauertes Obergemach bauen und ihm dort Bett, Tisch, Stuhl und Leuchter hineinstellen, damit er hier einkehre, wenn er zu uns kommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Eines Tages kam er dorthin. Er kehrte im Obergemach ein und legte sich darin nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Dann sprach er zu seinem Diener Gechazi: \"Ruf diese Sunamitin!\" Da rief er sie, und sie trat vor ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Dann sprach er zu ihm: \"Sag ihr doch: \'Du machst dir unseretwegen all diese Mühe! Was kann ich für dich tun? Brauchst du Fürsprache beim König oder beim Feldhauptmann?\'\" Da sprach sie: \"Ich gehöre zum gewöhnlichen Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Da sprach er: \"Aber was ist für sie zu tun?\" Da sprach Gechazi: \"Leider hat sie keinen Sohn, und ihr Mann ist alt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Da sprach er: \"Ruf sie!\" Da rief er sie, und sie trat in die Tür.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Er sprach: \"Zu dieser Frist zur entsprechenden Zeit wirst du einen Sohn herzen.\" Da sprach sie: \"Ach nein, mein Herr! Gottesmann! Enttäusche nicht deine Sklavin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Aber das Weib ward gesegnet und gebar einen Sohn in jener Frist zur entsprechenden Zeit, die ihr Elisäus angegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Der Knabe wuchs heran. Eines Tages ging er zu seinem Vater bei den Schnittern hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Da sagte er zu seiner Vater: \"Mein Kopf! Mein Kopf!\" Da sprach jener zum Diener: \"Trag ihn zu seiner Mutter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Da hob er ihn auf und brachte ihn seiner Mutter. Er saß auf ihrem Schoß bis zum Mittag. Dann starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Sie ging hinauf und legte ihn auf das Bett des Gottesmannes, schloß hinter ihm zu und ging hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Dann rief sie ihren Mann und sprach: \"Schick mir doch einen der Diener mit einer Eselin! Ich will schnell zum Gottesmann und wieder zurück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Er sprach: \"Weshalb willst du zu ihm? Heute ist doch weder Neumond noch Sabbat.\" Sie sagte: \"Es hat nichts auf sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'So ließ sie die Eselin satteln und sprach zu ihrem Diener: \"Treib immerfort an! Halt mich nicht im Reiten auf, bis ich es dir sage!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'So zog sie hin und kam zum Gottesmann auf den Berg Karmel. Als der Gottesmann sie von ferne sah, sprach er zu seinem Diener Gechazi. \"Da ist ja die Sunamitin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Lauf ihr sogleich entgegen und frage sie: \'Geht es dir gut? Geht es deinem Manne gut? Geht es deinem Knaben gut?\'\" Sie sagte: \"Alles wohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Als sie aber zu dem Gottesmann auf den Berg kam, umfaßte sie seine Füße. Da trat Gechazi hinzu, sie wegzureißen. Da sprach der Gottesmann: \"Laß sie! Ihr Gemüt ist bekümmert. Der Herr hat es mir verborgen und es mir nicht kundgetan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Sie fragte: \"Habe ich meinen Herrn um einen Sohn gebeten? Habe ich nicht gesagt: \'Mach mir keine falschen Hoffnungen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Da sprach er zu Gechazi: \"Gürte deine Lenden! Nimm meinen Stab in deine Hand und gehe! Begegnest du jemand, dann grüß ihn nicht, und grüßt dich jemand, dank ihm nicht! Dann lege meinen Stab auf des Knaben Angesicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Da sprach die Mutter des Knaben: \"So wahr der Herr lebt und du lebst! Ich lasse dich nicht.\" Da machte er sich auf und folgte ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gechazi aber ging voraus und legte den Stab auf des Knaben Antlitz. Aber kein Laut kam, und nichts war zu bemerken. Da kehrte er um, ging ihm entgegen und meldete ihm: \"Der Knabe ist nicht erwacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Elisäus kam nun in das Haus; da lag der Knabe tot auf seinem Bett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Er ging hinein, schloß die Tür hinter ihnen beiden und betete zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Dann erhob er sich und legte sich auf das Kind, Mund auf Mund, Augen auf Augen und Hände auf Hände und streckte sich wieder über ihn. Da ward der Körper des Kindes warm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Dann ging er im Hause hin und her, stieg hinauf und streckte sich über ihn. Da nieste der Knabe siebenmal. Danach schlug der Knabe die Augen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Da rief er Gechazi und sprach: \"Rufe die Sunamitin herbei!\" Er rief sie, und sie kam zu ihm. Da sprach er: \"Nimm deinen Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Da trat sie heran, fiel ihm zu Füßen und neigte sich bis zum Boden. Hierauf nahm sie ihren Sohn und ging hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisäus aber kehrte nach dem Gilgal zurück. Da ward im Lande eine Hungersnot. Die Prophetensöhne aber saßen vor ihm. Da sprach er zu seinem Diener: \"Setze den größten Topf bei und koche für die Prophetensöhne Gemüse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Da ging einer aufs Feld, Kräuter zu pflücken. Er fand einen Feldweinstock und pflückte Gurken, seinen Mantel voll. Er kam und schnitt sie in den Kochtopf. Er kannte sie aber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Dann schütteten sie es für die Männer zum Essen aus. Aber sobald sie von dem Gekochten aßen, schrien sie und riefen: \"Im Topf ist der Tod, Gottesmann.\" Sie konnten es nicht essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Er sprach:\"Holt Mehl!\" Dann warf er es in den Topf und sprach: \"Schütte es den Leuten zum Essen hin!\" Da war nichts Schlimmes mehr im Topf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Nun kam ein Mann von Baal Salisa und brachte dem Gottesmann zwanzig Gerstenbrote als Erstlingsbrot und neues Getreide in der Tasche. Er sagte: \"Gib es den Leuten zu essen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Da fragte sein Diener: \"Wie kann ich dies hundert Mann vorlegen?\" Er sprach: \"Gib es den Leuten zu essen! Denn also spricht der Herr: \'Sie essen und lassen davon übrig.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Da legte er es ihnen vor. Und sie aßen und ließen nach des Herrn Wort davon übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Des Aramkönigs Feldherr Naaman aber war groß vor seinem Herrn und hochangeschen. Denn der Herr hatte durch ihn Aram den Sieg verschafft. Der Mann war ein Kriegsheld, aber aussätzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Nun zogen die Aramäer auf einen Streifzug und raubten dabei aus dem Lande Israel ein junges Mädchen. Sie wurde bei Naamans Weib Dienerin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Sie sprach zu ihrer Herrin: \"Ach, stünde mein Herr vor dem Propheten zu Samaria! Er heilte ihn von seinem Aussatz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Da ging dieser und meldete seinem Herrn: \"So und so hat das israelitische Mädchen gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Der König von Aram sprach: \"Ziehe nur hin. Ich gebe einen Brief mit an den König von Israel.\" Da zog er hin und nahm zehn Talente Silber, sechstausend Goldstücke und zehn Festkleider mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Dann übergab er dem König von Israel den Brief, in dem stand: \"Wenn dieser Brief zu dir kommt, sende ich dir meinen Diener Naaman. Befreie ihn vom Aussatz!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Als aber der König von Israel den Brief gelesen hatte, zerriß er seine Gewänder und sprach: \"Bin ich denn ein Gott, der töten und beleben kann, daß er zu mir schickt, einen Mann von seinem Aussatz zu befreien? Seht, daß er nur Streit mit mir sucht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Als aber der Gottesmann Elisäus hörte, der König von Israel habe seine Gewänder zerrissen, sandte er zum König und ließ ihm sagen: \"Warum zerreißest du deine Kleider? Er komme nur zu mir, und er wird erfahren, daß es in Israel einen Propheten gibt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Naaman kam nun mit seinen Rossen und Wagen und hielt vor der Haustür des Elisäus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elisäus sandte einen Boten zu ihm und ließ sagen: \"Geh und bade siebenmal im Jordan! Und dein Leib sei wiederhergestellt! Geh und werde rein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Da ging Naaman unwillig davon und sprach: \"Ich habe gedacht, er käme zu mir, träte hin und riefe den Namen des Herrn, seines Gottes, an und bewegte seine Hand gegen den Ort und entfernte den Aussatz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Sind nicht Abana und Parpar, die Flüsse von Damaskus, besser als alle Gewässer Israels? Kann ich nicht darin baden und rein werden?\" Also wandte er sich und ging zornig davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Da traten seine Diener heran, sprachen zu ihm und sagten: \"Mein Vater! Hätte der Prophet etwas Schwieriges von dir verlangt, würdest du es nicht tun? Wieviel mehr, da er dir sagt: \'Bade, und du wirst rein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Da stieg er hinab und tauchte siebenmal im Jordan unter, nach des Gottesmannes Wort. Da ward sein Leib wieder wie der eines kleinen Knaben. Und er ward rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Da kam er zu dem Gottesmann zurück mit seinem ganzen Gefolge. Er kam, trat vor ihn und sprach: \"Nun weiß ich, daß auf der ganzen Erde kein Gott ist, außer in Israel. So nimm von deinem Sklaven ein Geschenk!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Er sprach: \"So wahr der Herr, dem ich diene, lebt! Ich nehme nichts.\" Da drang er in ihn, es zu nehmen. Aber er weigerte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Da sprach Naaman \"Dann möge deinem Sklaven eine Last Erde gegeben werden, die Last eines Maultiergespanns! Denn dein Sklave bringt fortan ein Brand- und Schlachtopfer nicht anderen Göttern dar als einzig dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Aber dies verzeihe der Herr deinem Sklaven! Wenn mein Herr in das Haus des Rimmon geht, dort anzubeten, und sich auf meinen Arm stützt, werfe auch ich mich im Haus des Rimmon nieder. Werfe ich mich dann so im Hause Rimmons nieder, dann verzeihe dies der Herr deinem Sklaven!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Da sprach er: \"Ziehe hin in Frieden!\" Und er zog von ihm eine Strecke Wegs fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Da dachte Gechazi, der Diener des Gottesmannes Elisäus: \"Mein Herr hat diesen Aramäer Naaman geschont und von ihm nichts genommen, was er hergebracht hat. So wahr der Herr lebt! Ich laufe ihm nach und nehme ihm etwas ab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Also lief Gechazi dem Naaman nach. Naaman aber sah, daß er ihm nachlief. Er beugte sich vom Wagen herab ihm entgegen und sprach: \"Steht es gut?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Er sprach: \"Ja! Aber mein Herr sendet mich und läßt sagen: \'Soeben sind zu mir zwei junge Leute von den Prophetensöhnen aus dem Gebirge Ephraim gekommen. Gib doch für sie ein Talent Silber und zwei Feierkleider!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Da sprach Naaman: \"Tu den Gefallen und nimm zwei Talente!\" Und er drang in ihn, verpackte zwei Talente Silber in zwei Beutel nebst zwei Feierkleidern und gab sie seinen beiden Dienern. Diese trugen sie vor ihm her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Als er zum Hügel kam, nahm er sie ihnen ab und verwahrte sie im Hause. Dann entließ er die Leute, und sie gingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Er selbst aber kam und trat vor seinen Herrn. Da fragte ihn Elisäus: \"Woher, Gechazi?\" Er sagte: \"Dein Sklave ist nirgends hingegangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Da sprach er zu ihm: \"Es ist nicht wahr. Mein Herz ist mitgegangen. Als sich ein Mann im Wagen nach dir umgewandt hat, ist das nicht der Augenblick gewesen, da du das Geld genommen hast, um dir dafür Kleider, Ölgärten, Weinberge, Schafe und Rinder, Sklaven und Sklavinnen zu kaufen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Nun hafte Naamans Aussatz an dir und deinen Nachkommen immerdar! Und er ging von ihm weg, schneeweiß von Aussatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Die Prophetensöhne aber sprachen zu Elisäus: \"Der Ort, an dem wir bei dir wohnen, ist uns zu eng.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Wir wollen an den Jordan gehen. Dort hole jeder einen Balken! Und wir schaffen uns eine Stätte zum Wohnen.\" Er sprach: \"Geht hin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Einer aber sprach: \"Sei so gut und gehe mit deinen Dienern!\" Er sprach: \"Gut! Ich gehe mit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'So ging er mit ihnen. Da kamen sie an den Jordan und fällten Bäume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Als einer an einem Balken hieb, fiel ihm das Eisen ins Wasser. Er schrie und rief: \"Ach, mein Herr! Und dazu ist es entlehnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Da fragte der Gottesmann: \"Wohin ist es gefallen?\" Da wies er ihm die Stelle. Nun schnitzte er ein Holz und warf es dorthin. Da schwamm das Eisen herbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Er sprach: \"Hol\'s dir herauf!\" Da streckte er seine Hand aus und holte es. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Der König von Aram fing mit Israel Krieg an. Da beriet er sich mit seinen Dienern und sprach: \"An dem und dem Ort sei mein Lager!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Da sandte der Gottesmann zum König von Israel und ließ sagen: \"Hüte dich, an diesem Ort vorüberzuziehen! Denn dort liegen die Aramäer im Hinterhalt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Da sandte der König von Israel an den Ort, den ihm der Gottesmann genannt hatte. So warnte er ihn. Und er beobachtete dort, nicht bloß ein- oder zweimal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Darüber ward der König von Aram aufgeregt. Er rief seine Diener und sagte zu ihnen: \"Könnt ihr mir nicht sagen, wer von uns es mit dem König von Israel hält!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Da sprach einer seiner Diener: \"Nicht doch! Mein Herr, König! Der Prophet Elisäus in Israel teilt dem König von Israel die Worte mit, die du in deinem Schlafgemach sprichst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Da sprach er: \"Geht und seht, wo er ist, daß ich schicke und ihn holen lasse!\" Da ward ihm gemeldet: \"Er ist in Dotan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Da sandte er dorthin Rosse, Wagen und eine starke Kriegerschar. Sie kamen bei Nacht und umzingelten die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Der Diener des Gottesmannes aber stand in der Frühe auf und trat hinaus. Da lag eine Kriegerschar rings um die Stadt mit Rossen und Wagen. Sein Diener sprach zu ihm: \"Wehe, mein Herr! Was sollen wir tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Er sprach: \"Fürchte nichts! Denn mehr sind der Unsrigen als der Ihrigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Und Elisäus betete und sprach: \"Herr, öffne ihm die Augen, daß er sehe!\" Da öffnete der Herr dem Diener die Augen, und er sah den Berg voll von feurigen Rossen und Wagen rings um Elisäus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Als sie nun gegen ihn anrückten, betete Elisäus zum Herrn und sprach: \"Schlage dieses Kriegsvolk mit Blindheit!\" Da schlug er sie mit Blindheit nach des Elisäus Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Dann sprach Elisäus zu ihnen: \"Dies ist nicht der Weg und dies ist nicht die Stadt. Folgt mir! Ich führe euch zu dem Mann, den ihr suchet.\" Da führte er sie nach Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Als sie nach Samaria gekommen waren, sprach Elisäus: \"Herr, öffne diesen die Augen, daß sie sehen!\" Da öffnete ihnen der Herr die Augen, und sie sahen sich mitten in Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Da sprach der König von Israel zu Elisäus, als er sie sah: \"Soll ich dreinschlagen lassen, mein Vater?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Da sprach er: \"Nein! Willst du solche, die du nicht mit deinem Schwert und Bogen gefangennimmst, niederschlagen? Setz ihnen Brot und Wasser vor, daß sie essen und trinken! Dann mögen sie zu ihrem Herrn ziehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Da ließ er für sie ein großes Mahl herrichten, und sie aßen und tranken. Dann entließ er sie, und sie zogen zu ihrem Herrn. Seitdem kamen keine aramäischen Streitscharen mehr ins Land Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Hernach zog Arams König Benhadad sein ganzes Heer zusammen. Er zog heran und belagerte Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Da ward eine große Hungersnot in Samaria, als jene es belagerten, bis ein Eselskopf achtzig Silberlinge galt und ein Viertelmaß Vogelmilch fünf Silberlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Als nun der König von Israel die Mauern untersuchte, schrie ein Weib ihn an und sprach: \"Hilf doch, mein Herr, König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Er sprach: \"Hilft dir der Herr nicht? Woher sollte ich dir helfen können? Von der Tenne oder von der Kelter?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Dann sprach der König zu ihr: \"Was hast du?\" Da sprach sie: \"Das Weib da sprach zu mir: \'Gib deinen Sohn her, daß wir ihn heute verzehren! Morgen wollen wir meinen Sohn verzehren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'So kochten wir meinen Sohn und verzehrten ihn. Da sprach ich zu ihr am anderen Tage: \'Gib deinen Sohn her, daß wir ihn essen!\' Da versteckte sie ihren Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Als aber der König die Worte des Weibes vernahm, zerriß er seine Kleider. Er untersuchte eben die Mauer. Da sah das Volk, daß er darunter ein Bußgewand auf seinem Leib hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Er sprach: \"Gott tue mir das und das, wenn des Saphatsohnes Elisäus Haupt noch heute auf ihm bleibt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elisäus aber saß in seinem Hause, und die Ältesten saßen bei ihm. Jener aber sandte einen Mann vor sich her. Bevor aber der Bote zu ihm kam, sprach er zu den Ältesten: \"Wißt ihr, daß dieser Mördersohn herschickt, mir den Kopf abzuschlagen? Seht zu! Sobald der Bote kommt, schließt die Tür und stemmt euch mit der Tür gegen ihn! Ist nicht der Schall der Tritte seines Herrn hinter ihm zu hören?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Noch redete er mit ihnen, da kam der König zu ihm herab. Er sprach: \"Das ist das Schlimmste vom Herrn. Was warte ich noch länger auf den Herrn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Elisäus aber sprach: \"Hört des Herrn Wort! So spricht der Herr: \'Um diese Zeit morgen gilt ein Maß Feinmehl einen Ring und zwei Maß Gerste gleichfalls einen Ring am Tor in Samaria.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Da entgegnete der Krieger, auf dessen Arm sich der König stützte, dem Gottesmann und sprach: \"Selbst wenn der Herr Luken am Himmel machte, könnte solches sein?\" Er sprach: \"Du darfst es sehen, aber darfst nicht mitessen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Nun waren vier Männer als Aussätzige vor dem Tore. Sie sprachen zueinander: \"Wozu bleiben wir hier, bis wir sterben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Sagten wir: Wir wollen in die Stadt kommen, so stürben wir dort; denn Hungersnot ist in der Stadt. Bleiben wir aber hier, so sterben wir auch hier. So kommt jetzt! Wir laufen ins Aramäerlager über. Lassen sie uns leben, so leben wir. Töten sie uns aber, so sterben wir eben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'So standen sie in der Abenddämmerung auf, um ins Aramäerlager zu gehen. Und sie kamen bis ans Ende des Aramäerlagers. Aber kein Mensch war hier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Der Herr hatte nämlich im Aramäerlager ein Getöse hören lassen, das Getöse von Wagen und Rossen, das Getöse eines großen Heeres, so daß sie zueinander sprachen: \"Der König von Israel hat gegen uns die Könige der Chittiter und Ägypter zu einem Überfall auf uns gedungen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'So brachen sie auf und flohen in der Abenddämmerung. Sie ließen ihre Zelte, Rosse und Esel, das Lager, wie es war, im Stich, und flohen um ihr Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Da kamen diese Aussätzigen bis an des Lagers Ende. Sie gingen in ein Zelt und aßen und tranken. Dann nahmen sie daraus Silber, Gold und Kleider und gingen, es zu vergraben. Sie kamen wieder und gingen in ein anderes Zelt. Auch hier trugen sie fort und gingen und vergruben es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Dann sprachen sie zueinander: \"Wir tun nicht recht. Dieser Tag ist ein Tag froher Botschaft. Wenn wir schweigen und bis zum lichten Morgen warten, dann trifft uns Strafe. So kommt denn! Wir wollen gehen und es im Königshause melden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'So kamen sie und riefen den Stadttorwächter und verkündeten ihnen: \"Wir sind ins Aramäerlager gekommen. Da war aber niemand, auch kein menschliches Geräusch. Die Rosse und Esel gesattelt und die Zelte, wie sie waren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Da brachen die Wächter in Rufe aus und meldeten es im Hause des Königs drinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Da stand der König noch in der Nacht auf und sprach zu seinen Dienern: \"Ich will euch sagen, was die Aramäer gegen uns vorhaben. Sie wissen, daß wir Hunger leiden. Darum verließen sie das Lager, um sich im Freien zu verstecken. Denn sie denken: \'Wenn sie aus der Stadt kommen, dann greifen wir sie lebendig und dringen in die Stadt ein.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Da erwiderte einer seiner Diener und sprach: \"Man nehme doch fünf der übriggebliebenen Rosse! Ihnen geht es dann eben wie Israels Volksmenge, die noch da ist, und wie Israels ganzer Masse, die schon dahin ist. Wir wollen sie aussenden und sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Da holten sie zwei Berittene. Und der König von Israel sandte sie dem Aramäerheere nach und sagte: \"Geht und schaut nach!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Sie folgten ihnen bis an den Jordan. Da war der ganze Weg voll von Gewändern und Waffen, die die Aramäer auf ihrer eiligen Flucht weggeworfen hatten. Die Boten kehrten um und meldeten es dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Da ging das Volk hinaus und plünderte das Aramäerlager. Und ein Maß Feinmehl galt einen Ring und zwei Maß Gerste auch einen Ring nach des Herrn Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Der König aber hatte über das Tor den Krieger bestellt, auf dessen Arm er sich zu stützen pflegte. Da zertrat ihn das Volk im Tor, und er starb, wie es der Gottesmann gesagt hatte, als der König zu ihm hinabkam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Als nämlich der Gottesmann zum König sagte: \"Zwei Maß Gerste werden einen Ring gelten und ein Maß Feinmehl gleichfalls einen Ring morgen um diese Zeit in Samarias Tor\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'gab der Krieger dem Gottesmann zur Antwort und sprach: \"Selbst wenn der Herr am Himmel Luken machte, könnte solches sein?\" Da sagte er: \"Du darfst es sehen, aber darfst nicht mitessen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Und ihm geschah also. Das Volk zertrat ihn im Tor, und er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisäus aber sprach zu dem Weib, dessen Sohn er lebendig gemacht hatte: \"Auf! Zieh mit deinem Hause fort und weile, wo du weilen magst! Denn der Herr ruft eine Hungersnot herbei, und sie kommt für sieben Jahre ins Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Da machte sich das Weib auf und tat nach des Gottesmannes Wort. Sie zog mit ihrem Hause von dannen und weilte sieben Jahre im Philisterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Nach sieben Jahren kehrte das Weib aus dem Philisterland zurück. Da ging sie, den König wegen ihres Hauses und Feldes anzurufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Der König sprach gerade zu Gechazi, dem Diener des Gottesmannes: \"Erzähle mir all die Großtaten, die Elisäus getan hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Gerade erzählte er dem König, wie er den Toten lebendig gemacht hatte, da kam das Weib, dessen Sohn er lebendig gemacht hatte, um den König wegen ihres Hauses und Feldes anzurufen. Da sprach Gechazi: \"Mein Herr, König! Dies ist das Weib und dies sein Sohn, den Elisäus lebendig gemacht hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Da befragte der König das Weib, und sie erzählte es ihm. Da gab ihr der König einen Kämmerer mit und befahl: \"Verschaffe ihr all das Ihrige und den ganzen Feldertrag von dem Tage an, da sie das Land verlassen hat, bis heute!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elisäus kam nun nach Damaskus; Arams König Benhadad aber war gerade krank. Ihm wurde gemeldet: \"Der Gottesmann ist hierher gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Da sprach der König zu Chazael: \"Nimm ein Geschenk mit! Geh dem Gottesmann entgegen und befrage durch ihn den Herrn, ob ich von meiner Krankheit genese!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Chazael ging ihm entgegen. Und er nahm ein Geschenk mit, allerlei Köstliches aus Damaskus, vierzig Kamellasten. So kam er, trat vor ihn und sprach: \"Dein Sohn, Arams König Benhadad, schickt mich zu dir und fragt: \'Werde ich von dieser Krankheit genesen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Da sprach Elisäus zu ihm: \"Geh und sage ihm: \'Du wirst genesen!\' Der Herr aber hat mich sehen lassen, daß er sterben werde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Er aber verzog keine Miene und lehnte lange Zeit auf seinem Stab. Da weinte der Gottesmann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Chazael fragte: \"Warum weinst du, mein Herr?\" Er sprach: \"Weil ich weiß, was du Israels Söhnen Böses tun wirst. Du wirst ihre festen Städte in Brand stecken, ihre Jungmannschaft mit dem Schwerte töten, ihre Kindlein zerschmettern und ihre werdenden Mütter aufschlitzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Da sprach Chazael: \"Was ist denn dein Sklave, der Hund, daß er dies Gewaltige tun sollte?\" Da sprach Elisäus: \"Der Herr hat dich mir als König von Aram gezeigt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Er ging nun von Elisäus weg und kam zu seinem Herrn. Dieser fragte ihn: \"Was hat dir Elisäus gesagt?\" Er hat mir gesagt: \"Du wirst genesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Am anderen Morgen aber nahm er einen Schleier, tauchte ihn in Wasser und breitete ihn über sein Gesicht, und er starb. So ward Chazael König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Im fünften Jahre des Achabsohnes Joram, des Königs von Israel - Josaphat, Judas König, war gestorben -, ward des Judakönigs Josaphat Sohn, Joram, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Er war zweiunddreißig Jahre alt, als er König wurde, und regierte acht Jahre in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Er wandelte auf dem Weg der Könige Israels, wie die vom Achabshaus getan. Denn er hatte eine Tochter Achabs zum Weibe. So tat er, was dem Herrn mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Aber der Herr wollte Juda um seines Dieners David willen nicht vernichten, wie er ihm verheißen hatte, daß er ihm und seinen Söhnen allzeit eine Leuchte lasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'In seinen Tagen war Edom von Judas Botmäßigkeit abgefallen; es gab sich einen König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Da zog Joram nach Sair Mit all seinen Wagen. Er erhob sich des Nachts und schlug die Edomiter, die ihn umzingelt hatten, samt den Wagenobersten, und das Volk floh zu seinen Zelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Aber Edom fiel doch von Juda ab, bis auf diesen Tag. Damals fiel zu gleicher Zeit auch Libna ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Ist nicht der Rest der Geschichte Jorams und alles, was er sonst getan, im Geschichtsbuch der Könige von Juda aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Als sich Joram zu seinen Vätern legte, ward er bei seinen Ahnen in der Davidsstadt begraben, und sein Sohn Achazja ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Im zwölften Jahr des Achabsohnes und Israelkönigs Joram ward des Judakönigs Joram Sohn, Achazja, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazja war zweiundzwanzig Jahre alt, als er König wurde, und regierte ein Jahr in Jerusalem. Seine Mutter hieß Atalja. Sie war eine Enkelin des israelitischen Königs Omri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Er wandelte auf des Achabhauses Weg und tat, was dem Herrn mißfiel, wie das Haus Achabs; denn er war mit dem Hause Achabs verschwägert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Er zog nun mit dem Achabsohne Joram gegen Arams König Chazael bei Ramot im Gilead zu Felde. Aber die Aramäer verwundeten Joram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Da kehrte der König Joram heim, um sich in Jezreel von den Wunden zu heilen, die ihm die Aramäer in Rama geschlagen hatten, als er mit Arams König Chazael kämpfte. Nun ging der Judakönig Achazja, Jorams Sohn, hinab, den Achabsohn Joram in Jezreel zu besuchen, weil er krank war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Da rief der Prophet Elisäus einen der Prophetensöhne und sprach: \"Gürte deine Lenden! Nimm diese Ölflasche mit dir und geh nach Ramot im Gilead!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Und kommst du dort an, dann merk auf! Dort ist Jehu, Josaphats Sohn und Nimsis Enkel. Trittst du ein, dann laß ihn aus seiner Brüder Mitte aufstehen und führ ihn in das innerste Gemach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Dann nimm die Ölflasche, gieße daraus auf sein Haupt und sage: \'So spricht der Herr: \"Ich salbe dich zum König über Israel!\"\' Dann öffne die Tür und fliehe unverweilt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Da ging der Jüngling - der Jüngling war ein Prophet - nach Ramot im Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Als er hinkam, saßen die Hauptleute des Heeres da. Er sagte: \"Hauptmann! Ich habe dir etwas zu sagen.\" Jehu fragte: \"Wem von uns allen?\" Er sprach: \"Hauptmann! Dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Da stand er auf und ging ins Haus hinein. Da goß er ihm das Öl aufs Haupt und sagte zu ihm: \"So spricht der Herr, Israels Gott: \'Ich salbe dich zum König über des Herrn Volk, über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Schlage nieder das Haus Achabs, deines Herrn, damit ich räche meiner Diener, der Propheten, Blut sowie das Blut aller anderen Diener des Herrn an Izebel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'und an dem ganzen Achabhause! Zugrunde geht das ganze Achabhaus. Von Achab tilge ich die Wandpisser, wie Mündige in Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Ich mache so das Achabhaus gleich dem des Nebatsohns Jeroboam und gleich dem Haus des Achiasohnes Baësa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Izebel aber fressen Hunde auf der Flur von Jezreel, und niemand ist, der sie bestattet.\'\" Darauf öffnete er die Tür und floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Als Jehu nun zu den Dienern seines Herrn hinaustrat, fragte man ihn: \"Steht es gut? Weshalb ist dieser Verrückte zu dir gekommen?\" Er sprach zu ihnen: \"Ihr kennt ja den Mann und sein Geschwätz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Sie sprachen. \"Ausflüchte! Sag es uns!\" Da sagte er: \"So und so hat er zu mir gesprochen: \'So spricht der Herr: \"Ich salbe dich zum König über Israel.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Da nahmen sie eilends jeder sein Gewand und legten es unter ihn auf die Treppenziegel. Dann stießen sie in das Horn und riefen: \"Jehu ist König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Also verschwor sich Jehu, Josaphats Sohn und Nimsis Enkel, gegen Joram. Joram aber lag auf der Wacht zu Ramot im Gilead mit ganz Israel gegen Arams König Chazael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Der König Joram aber kehrte heim, um sich in Jezreel heilen zu lassen von den Wunden, die ihm die Aramäer schlugen, als er mit Arams König Chazael kämpfte. Jehu sprach: \"Ist es euch genehm, dann gehe niemand heimlich aus der Stadt in der Absicht, hinzugehen und es in Jezreel zu melden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Hierauf bestieg Jehu einen Wagen und fuhr nach Jezreel. Denn dort lag Joram, und der Judakönig Achazja war herabgezogen, Joram zu besuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Auf dem Turme zu Jezreel aber stand der Wächter und sah Jehus, Schar herankommen. Er sprach: \"Ich sehe eine Schar.\" Da sprach Joram: \"Hole einen Reiter und schicke ihn jenen entgegen, daß er frage: \'In friedlicher Absicht?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Da ritt der Reiter ihm entgegen und sprach: \"So fragt der König: \'In friedlicher Absicht?\'\" Jehu sprach: \"Was geht dich der Frieden an? Schwenke hinter mich ein!\" Der Wächter meldete es und sprach: \"Der Bote ist bei ihnen angelangt, kehrt aber nicht um.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Da sandte er einen zweiten Reiter. Er kam zu ihm und sprach: \"So fragt der König: \'Friedlich?\'\" Jehu sprach: \"Was geht dich der Frieden an? Schwenke hinter mich ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Der Wächter meldete: \"Auch er ist bei ihnen angelangt, kehrt aber nicht um. Und das Fahren gleicht dem Fahren des Nimsisohnes Jehu; denn er fährt unsinnig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Da sprach Joram: \"Spanne ein!\" Man spannte seinen Wagen ein, und der König von Israel, Joram, fuhr mit dem Judakönig Achazja hinaus, jeder auf seinem Wagen. So fuhren sie Jehu entgegen und trafen ihn auf des Jezreeliters Nabot Grundstück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Als Joram den Jehu erblickte, fragte er: \"In friedlicher Absicht, Jehu?\" Er sprach: \"Was, friedliche Absicht bei deiner Mutter Izebel Hurerei und ihren zahllosen Ränken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Da lenkte Joram um und floh. Er rief Achazja zu \"Verrat! Achazja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Da spannte Jehu den Bogen bis aufs äußerste und traf Joram zwischen die Arme. Der Pfeil fuhr ihm durchs Herz, und er sank in seinem Wagen nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Dann sprach er zu seinem Krieger Bidekar: \"Nimm ihn und wirf ihn auf des Jezreeliters Nabot Grundstück! Denk daran, wie ich und du hinter seinem Vater Achab Seite an Seite ritten, als der Herr über ihn diesen Ausspruch tat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '\'Ich habe gestern Nabots und seiner Söhne Blut gesehen - ein Spruch des Herrn - und ich vergelte es dir auf diesem Grundstück.\' Ein Spruch des Herrn. So nimm ihn und wirf ihn auf das Grundstück nach des Herrn Wort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Dies hatte der Judakönig Achazja mit angesehen; da floh er gegen das Gartenhaus. Jehu jagte ihm nach und rief: \"Schlagt auch diesen auf dem Wagen!\" Es war auf der Steige von Gur bei Ibleam. Doch er entkam nach Megiddo; dort aber starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Dann fuhren ihn seine Diener nach Jerusalem und begruben ihn in seiner Grabstätte bei seinen Ahnen in der Davidsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Im elften Jahr des Achabsohnes Joram war Achazja über Juda König geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Nun kam Jehu nach Jezreel. Als Izebel davon hörte, schminkte sie die Augenlider, schmückte ihr Haupt und schaute zum Fenster hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Als Jehu durch das Tor kam, sprach sie: \"Geht es Zimri, dem Mörder seines Herrn, gut?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Da blickte er zum Fenster hinauf und rief: \"Wer hält es mit mir? Wer?\" Da blickten zu ihm zwei oder drei Kämmerlinge herunter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Er rief: \"Stürzt sie herab!\" Und sie stürzten diese hinab. Von ihrem Blut aber spritzte an die Mauer und an die Rosse, und sie zerstampften sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Er aber ging hinein und aß und trank. Dann sprach er: \"Seht nach dieser Verfluchten und begrabt sie! Sie ist doch eine Königstochter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Da gingen sie hin, sie zu begraben, fanden aber von ihr nichts mehr als den Schädel, die Füße und Arme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Sie kamen zurück und meldeten es ihm. Er sprach: \"Das ist des Herrn Wort, das er durch seinen Diener, den Tisbiter Elias, gesprochen hat: \'Das Fleisch Izebels fressen Hunde auf der Flur von Jezreel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Izebels Leichnam wird wie Ackerdünger auf der Flur von Jezreel, daß man nicht sagen kann: \"Das ist Izebel.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Achab hatte siebzig Söhne in Samaria. Nun schrieb Jehu einen Brief und sandte ihn nach Samaria an Jezreels Fürsten, an die Ältesten und die Vormünder der Achabsöhne, in dem es hieß:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '\"Gelangt dieser Brief an euch - bei euch sind eures Herrn Söhne und auf eurer Seite die Wagen, Rosse, Festungen und das Zeughaus -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'dann wählt den besten und tüchtigsten aus den Söhnen eures Herrn, setzt ihn auf seines Vaters Thron und kämpft für das Haus eures Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Jene aber fürchteten sich gewaltig und sprachen: \"Zwei Könige haben nicht vor ihm standgehalten. Wie könnten wir bestehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'So schickten die Vorsteher des Hauses und der Stadtoberste sowie die Ältesten und Vormünder zu Jehu und ließen sagen: \"Wir sind deine Sklaven, und alles, was du uns befiehlst, wollen wir tun. Wir machen niemanden zum König. Tu, was dir gut dünkt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Er schrieb zum zweitenmal einen Brief des Inhalts: \"Haltet ihr zu mir und hört ihr auf meine Stimme, dann nehmt die Häupter der Männer, der Söhne eures Herrn, und kommt zu mir morgen um diese Zeit nach Jezreel!\" Des Königs Söhne, siebzig Mann, aber waren in der Stadt bei den Vornehmen, die sie aufzogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Als der Brief an sie kam, ergriffen sie des Königs Söhne und schlachteten sie ab, siebzig Mann. Dann legten sie ihre Köpfe in Körbe und schickten sie nach Jezreel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Da kam der Bote und meldete ihm: \"Man bringt die Köpfe der Königssöhne.\" Er sprach: \"Legt sie in zwei Haufen vor den Toreingang bis zum Morgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Am anderen Morgen ging er hinaus, trat hin und sprach zum ganzen Volk: \"Ihr seid ohne Schuld. Ich habe mich gegen meinen Herrn verschworen und ihn umgebracht. Wer aber hat all diese erschlagen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Erkennet nun, daß nichts zu Boden fällt von des Herrn Wort, das der Herr gegen Achabs Haus gesprochen hat! Der Herr hat getan, was er durch seinen Diener Elias gesprochen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Hierauf erschlug Jehu alle, die von Achabs Haus zu Jezreel übrig waren, ebenso alle seine Verwandten, Vertrauten und Priester. Keinen einzigen von ihm ließ er übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Dann erhob er sich und zog nach Samaria. Er war gerade bei dem Schurhaus der Hirten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Da traf Jehu des Judakönigs Achazja Brüder und fragte: \"Wer seid ihr?\" Sie sprachen: \"Wir sind die Brüder des Achazja und kommen herab, die Königssöhne und die Söhne der Königinmutter zu begrüßen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Da rief er: \"Greift sie lebendig!\" Sie ergriffen sie lebendig und schlachteten sie in der Grube des Schurhauses ab, zweiundvierzig Mann. Keinen von ihnen ließ er übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Von da zog er weiter und traf Rekabs Sohn Jonadab, der ihm entgegenkam. Er grüßte ihn und fragte ihn: \"Ist dein Herz zu mir so aufrichtig wie meines zu deinem?\" Jonadab sprach: \"Jawohl! Gib mir deine Hand!\" Da gab er ihm die Hand und hob ihn zu sich auf seinen Wagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Und er sprach: \"Geh mit mir und schaue deine Lust an meinem Eifern für den Herrn!\" So fuhren sie auf seinem Wagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'So kam er nach Samaria und erschlug alle, die von Achab zu Samaria übrig waren, bis er sie vertilgt hatte, nach des Herrn Wort, das er zu Elias gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Dann versammelte Jehu das ganze Volk und sprach zu ihm: \"Achab hat dem Baal zuwenig gedient. Jehu wird ihm eifriger dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'So ruft jetzt alle Baalspropheten, alle seine Diener und alle seine Priester zu mir! Keiner fehle! Denn ich habe ein großes Opferfest für den Baal vor. Wer fehlt, bleibt nicht am Leben.\" Jehu aber handelte hinterlistig, um die Baalsdiener umzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jehu sprach: \"Verkündet eine Festversammlung für den Baal!\" Und sie riefen diese aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Dann sandte Jehu in ganz Israel umher. Und alle Baalsdiener kamen. Nicht einer blieb zurück, der nicht gekommen wäre. Also kamen sie in das Haus des Baal, und das Baalshaus ward voll von einer Ecke bis zur anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Da sprach er zum Vorstand der Kleiderkammer: \"Gib für alle Baalsdiener Gewänder heraus!\" Da gab er für sie die Gewänder heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Dann kam Jehu mit dem Rekabsohn Jonadab in das Baalshaus. Er sprach zu den Baalsdienern: \"Forscht nach und seht, ob nicht bei euch einer von den Dienern des Herrn ist! Nur Baalsdiener allein seien da!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'So kamen sie, Schlacht- und Brandopfer herzurichten. Jehu aber stellte draußen achtzig Mann auf. Er sprach: \"Wer einen der Männer, die ich euch in die Hände liefere, entkommen läßt, der haftet dafür mit seinem Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Als man mit der Zurichtung des Brandopfers fertig war, sprach Jehu zu den Läufern und den Kriegern: \"Kommt und schlagt sie! Keiner darf heraus!\" Da schlugen sie sie mit dem Schwerte. Die Läufer aber und die Krieger schafften sie heraus. Dann gingen sie wieder in das Baalshaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Hier schafften sie die Denksäulen des Baalshauses heraus und verbrannten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Dann zertrümmerten sie das Mal des Baal und das Baalshaus und machten daraus Kloaken bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'So tilgte Jehu aus Israel den Baal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Aber von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte, ließ Jehu nicht, von den goldenen Kälbern in Dan und Betel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Der Herr aber sprach zu Jehu: \"Weil du richtig ausgeführt hast, was recht in meinen Augen, und weil du ganz nach meinem Sinn am Achabhaus getan, so sollen deine Nachkommen bis in das vierte Glied auf Israels Thron sitzen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Aber Jehu hatte nicht acht, im Gesetze des Herrn, des Gottes Israels, von ganzem Herzen zu wandeln. Er ließ nicht von Jeroboams Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Zu jener Zeit begann der Herr Israel zu verringern. Chazael nämlich schlug sie im ganzen Grenzgebiet Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'vom Jordan östlich das ganze Land Gilead, die Gaditen, Rubeniten und Manassiten von Aroër am Arnonfluß, Gilead und Basan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Ist nicht der Rest der Geschichte Jehus und alles, was er sonst getan, sowie seine ganze Tapferkeit im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Als sich Jehu zu seinen Vätern legte, begrub man ihn zu Samaria, und sein Sohn Joachaz ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Die Zeit, die Jehu über Israel zu Samaria regierte, betrug achtundzwanzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Als Atalja, Achazjas Mutter, erfuhr, daß ihr Sohn tot sei, erhob sie sich und vertilgte den ganzen Königsstamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Aber Joseba, des Königs Joram Tochter und Vollschwester Achazjas, nahm den Joas, des Achazja Sohn, und brachte ihn verstohlenerweise mitten aus den Königssöhnen, die getötet werden sollten, mit seiner Amme in die Bettkammer. So verbargen sie ihn vor Atalja, und er ward nicht getötet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Er blieb bei ihr im Hause des Herrn sechs Jahre versteckt. Atalja aber herrschte über das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Im siebten Jahre aber sandte Jojada hin und holte die Obersten der karischen Hundertschaften und der Läufer. Und er brachte sie zu sich in das Haus des Herrn. Dann verbündete er sich mit ihnen und ließ sie im Hause des Herrn schwören. Hierauf zeigte er ihnen den Königssohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Er gebot ihnen: \"Dies habt ihr zu tun: Das Drittel, das am Sabbat abzieht, hat die Wache im Königshaus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'das andere Drittel am Tor des Ausgangs und das letzte Drittel am Tor hinter den Läufern. Die Wache am Haus aber haltet abwechselnd!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Zwei Teile von euch, alle, die am Sabbat zum Dienste kommen, sollen Wache halten am Hause des Herrn beim König!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Schart euch um den König, jeder mit seinen Waffen in der Hand! Wer in die Reihen dringt, werde getötet! Bleibt beim König, wenn er aus- und einzieht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Die Obersten der Hundertschaften taten nun ganz, wie es der Priester Jojada befohlen hatte. Jeder nahm seine Leute mit, die am Sabbat Abziehenden und die am Sabbat Aufziehenden, und sie kamen zum Priester Jojada.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Und der Priester gab den Obersten der Hundertschaften die Lanzen und Schilde des Königs David im Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'So standen die Läufer, jeder mit seinen Waffen in der Hand, von des Hauses Südseite bis zur Nordseite, um Altar und Haus, rings um den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Da führte er den Königssohn heraus und legte ihm das Diadem und die Spange an. So machten sie ihn zum König, salbten ihn, klatschten in die Hände und riefen: \"Es lebe der König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Atalja aber hörte den Lärm der Tanzenden im Volke. So kam sie in das Haus des Herrn zum Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Da sah sie, wie der König nach dem Brauch auf der Säule stand und die Fürsten mit den Hörnern beim König, und wie alles Volk des Landes fröhlich war und in die Hörner stieß. Da zerriß Atalja ihre Gewänder und schrie: \"Verschwörung! Verschwörung!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Da gebot der Priester Jojada den Obersten der Hundertschaften, den Befehlshabern des Heeres, und sprach zu ihnen: \"Führt sie durch die Reihen hinaus! Wer ihr folgt, den tötet mit dem Schwert!\" Denn der Priester hatte gesagt: \"Sie werde nicht im Haus des Herrn getötet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Da legten sie Hand an sie, und sie kam durch den Rossegang ins Königshaus. Dort wurde sie getötet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Da schloß Jojada den Bund zwischen dem Herrn, dem König und dem Volk, daß sie ein Volk des Herrn sein wollten, sowie zwischen dem König und dem Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Dann kam alles einheimische Volk in das Baalshaus und riß es ein. Seine Altäre und Bilder zerbrachen sie vollständig, und den Priester Mattan töteten sie vor den Altären. Dann stellte der Priester eine Wache vor das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Darauf nahm er die Obersten der Hundertschaften, die Karer, die Läufer und das ganze einheimische Volk. Und sie führten den König aus dem Hause des Herrn hinab und kamen durch das Läufertor ins Königshaus. Da setzte er sich auf den Königsthron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Alles Volk des Landes war fröhlich; die Stadt aber war ruhig geblieben, obschon sie Atalja mit dem Schwert im Königshaus getötet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Joas war sieben Jahre alt, als er König wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Im siebten Jahre Jehus ward Joas König, und vierzig Jahre regierte er zu Jerusalem. Seine Mutter hieß Sibja und war aus Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Joas tat, was dem Herrn gefiel, solange ihn der Priester Jojada unterwies.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Nur die Höhen wurden nicht abgeschafft. Das Volk opferte und räucherte noch immer auf den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Joas sprach nun zu den Priestern: \"Der Weihegaben ganzes Geld, das ins Haus des Herrn als schätzbares Silber gebracht wird, das Geld der Musterungspflichtigen, alles, was jemand freiwillig ins Haus des Herrn bringt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'das sollen die Priester für sich nehmen, jeder von seinen Bekannten! Sie sollen dafür den Schaden am Hause ausbessern, alles, woran sich ein Schaden findet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Im dreiundzwanzigsten Jahre des Königs Joas aber hatten die Priester noch immer nicht den Schaden am Hause ausgebessert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Da berief der König Joas den Priester Jojada samt den anderen Priestern und fragte sie: \"Warum bessert ihr nicht am Hause den Schaden aus? Nehmt kein Geld mehr von euren Bekannten an! Ihr sollt es vielmehr zur Ausbesserung am Hause verwenden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Die Priester willigten ein, kein Geld mehr vom Volke anzunehmen, ohne zugleich am Hause den Schaden auszubessern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Dann nahm der Priester Jojada eine Lade, bohrte ein Loch in den Deckel und stellte sie rechts neben den Altar. Kam nun jemand in das Haus des Herrn, so taten die priesterlichen Schwellenhüter alles Geld hinein, das in das Haus des Herrn gebracht ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Wenn sie nun sahen, daß in der Lade viel Geld war, kam des Königs Schreiber mit dem Hohenpriester herauf. Sie packten das Geld zusammen und zählten, was sich im Hause des Herrn fand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Dann übergaben sie das abgewogene Geld den Werkführern, die am Hause des Herrn die Aufsicht führten. Diese verausgabten es an die Zimmerleute und Bauleute, die am Hause des Herrn arbeiteten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'an die Holzfäller und Steinbrecher, und zum Ankauf von Holz und Bruchsteinen, um am Hause des Herrn den Schaden auszubessern, kurz, zu allem, was die Ausbesserung des Hauses kostete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Doch wurden für des Herrn Haus keine silbernen Becken, Messer, Sprengschalen und Trompeten gemacht noch irgendein anderes goldenes oder silbernes Gerät von dem Gelde, das in das Haus des Herrn gebracht wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Man gab es nur den Arbeitern, daß sie das Haus des Herrn davon ausbesserten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Mit den Männern aber, denen man das Geld aushändigte, daß sie es den Arbeitern gäben, rechnete man nicht ab. Sie walteten eben auf Treu und Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Nicht in das Haus des Herrn ward das Geld von Schuld- und Sündopfern gebracht; es gehörte den Priestern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Damals zog Arams König Chazael heran, stritt wider Gar und nahm es ein. Dann machte Chazael Miene, Jerusalem anzugreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Da nahm Judas König Joas alle Weihegaben, die Josaphat, Joram und Achazja, seine Väter, Judas Könige, gestiftet hatten, samt den eigenen Weihegaben, sowie alles Geld, das sich in den Schatzkammern im Haus des Herrn und im Königshaus fand, und sandte es Arams König Chazael. Da zog er von Jerusalem ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Ist nicht der Rest der Geschichte des Joas und alles, was er sonst getan, im Geschichtsbuche der Könige Judas aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Seine Diener erhoben sich, machten eine Verschwörung und erschlugen Joas im Basteihaus, das zur Steige abfällt. Jozakar, Simats Sohn, und Somers Sohn Jozabad, seine Diener, schlugen ihn tot. Dann begrub man ihn bei seinen Vätern in der Davidsstadt. Und sein Sohn Amasja ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Im dreiundzwanzigsten Jahre des Judakönigs Joas, des Achazjasohnes, ward Joachaz, Jehus Sohn, König über Israel zu Samaria für siebzehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Er tat, was dem Herrn mißfiel, und folgte des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte. Er ließ nicht davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Da entbrannte des Herrn Zorn über Israel, und er gab sie in die Hand des Aramkönigs Chazael und in die des Chazaelsohnes Hadad für lange Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Aber Joachaz begütigte den Herrn. Und der Herr erhörte ihn. Denn er hatte Israels Bedrückung gesehen, wie es der König von Aram drückte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Da gab der Herr Israel einen Retter. Und sie entzogen sich Arams Gewalt. So wohnten Israels Söhne wie vorlängst in ihren Zelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Nur ließen sie nicht von den Sünden des Hauses Jeroboams, zu denen er Israel verführt hatte. Darin wandelten sie, und auch die Aschera blieb in Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Denn er ließ dem Joachaz nicht mehr Kriegsvolk als fünfzig Reiter, zehn Wagen und 10.000 Mann Fußtruppen. Arams König nämlich hatte sie vernichtet und dem Staube beim Dreschen gleichgemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Ist nicht der Rest der Geschichte des Joachaz und alles, was er sonst getan, sowie seine Tapferkeit im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Als sich Joachaz zu seinen Vätern legte, begrub man ihn zu Samaria, und sein Sohn Joas ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Im siebenunddreißigsten Jahre des Judakönigs Joas ward Joachaz Sohn Joas König über Israel in Samaria für sechzehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Er tat, was dem Herrn mißfiel. Er ließ in seinem Wandel nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Ist nicht der Rest der Geschichte des Joas und alles, was er sonst getan, sowie seine Tapferkeit, wie er mit Judas König, Amasja, Krieg führte, im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Als sich Joas zu seinen Vätern legte, bestieg Jeroboam seinen Thron. Joas ward bei den Königen Israels zu Samaria begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Elisäus aber verfiel in eine Krankheit, an der er sterben sollte. Da kam Israels König, Joas, zu ihm hinab, weinte über ihn und sprach: \"Mein Vater! Mein Vater! Israels Wagen und Reiter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Da sprach Elisäus zu ihm: \"Hol Bogen und Pfeile!\" Da holte er ihm Bogen und Pfeile.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Da sprach er zum König von Israel: \"Spanne den Bogen mit deiner Hand!\" Er spannte ihn, und Elisäus legte seine Hände auf die Hände des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Dann sprach er: \"Öffne das Fenster nach Osten!\" Er öffnete es. Da sprach Elisäus: \"Schieße!\" Da schoß er. Er sprach: \"Ein Pfeil des Sieges vom Herrn! Ein Siegespfeil gegen Aram! Du wirst Aram wie zu Aphek vernichtend schlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Dann sprach er: \"Nimm die Pfeile!\" Er nahm sie. Dann sprach er zu Israels König: \"Schlage auf den Boden!\" Da schlug er dreimal. Darauf hielt er inne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Da zürnte der Gottesmann über ihn und sprach: \"Bei fünf- oder sechsmaligem Schlagen hättest du Aram vernichtend geschlagen. Nun schlägst du den Aram nur dreimal.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elisäus starb, und man begrub ihn. Nun fielen moabitische Streifscharen in einem Jahre in das Land ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Eben wollte man einen Mann begraben, als man die Streifschar erblickte. Da warfen sie den Mann in des Elisäus Grab und gingen davon. Sobald aber der Mann die Gebeine des Elisäus berührte, ward er lebendig und stellte sich auf seine Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Arams König Chazael bedrängte Israel alle Tage des Joachaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Der Herr aber war ihnen gnädig und erbarmte sich ihrer. Er wandte sich ihnen zu, wegen seines Bundes mit Abraham, Isaak und Jakob. Er wollte nicht ihr Verderben und verwarf sie noch nicht von seinem Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Chazael, Arams König, starb, und sein Sohn Benhadad ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Da entriß des Joachaz Sohn Joas dem Benhadad, Chazaels Sohn, wieder die Städte, die jener seinem Vater Joachaz im Krieg entrissen hatte. Dreimal schlug ihn Joas und gewann Israels Städte wieder zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Im zweiten Jahre des Joachazsohnes Joas, des Königs von Israel, ward des Judakönigs Joas Sohn, Amasja, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Er war fünfundzwanzig Jahre alt, als er König wurde, und fünfundzwanzig Jahre regierte er in Jerusalem. Seine Mutter hieß Joaddan und war aus Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Er tat, was dem Herrn gefiel, aber nicht so wie sein Ahn David. Er tat ganz so, wie sein Vater Joas getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Nur die Höhen waren nicht beseitigt. Das Volk opferte und räucherte noch immer auf den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Als die Herrschaft fest in seiner Hand war, ließ er seine Diener töten, die den König, seinen Vater, erschlagen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Aber die Söhne der Mörder tötete er nicht, wie im Buche der Lehre Mosis geschrieben steht und was der Herr geboten: \"Väter sollen nicht wegen der Kinder getötet werden, noch Söhne wegen der Väter; sondern jeder werde nur wegen seines eigenen Verbrechens getötet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Er schlug die 10.000 Edomiter im Salztal und nahm Sela im Sturm ein. Er nannte es Jokteel bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Damals sandte Amasja Boten an Joas, des Joachaz Sohn und Jehus Enkel, den König von Israel, und ließ sagen: \"Komm! Wir wollen uns ins Angesicht sehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Da ließ Israels König Joas dem Judakönig Amasja dies entbieten: \"Die Distel auf dem Libanon hat zur Libanonzeder gesandt und sagen lassen: \'Gib deine Tochter meinem Sohn zum Weibe!\' Aber das Wild auf dem Libanon lief darüber und zertrat die Distel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Weil du Edom geschlagen, überhebt sich gewaltig dein Sinn. Schone deine Ehre und bleib zu Haus! Warum forderst du das Unglück heraus, daß du fällst, du und Juda mit dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Aber Amasja hörte nicht darauf. So rückte Israels König Joas heran, und sie maßen sich, er und Amasja, Judas König, zu Betsemes in Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Da ward Juda von Israel geschlagen, und sie flohen, jeder in sein Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Den Judakönig Amasja aber, Sohn des Joas und Achazjas Enkel, nahm Israels König Joas zu Betsemes gefangen und brachte ihn nach Jerusalem. Er legte auch in Jerusalems Mauer Breschen vom Ephraimtor bis zum Ecktor, 400 Ellen lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Dann nahm er alles Gold und Silber, alle Geräte im Hause des Herrn und in des Königshauses Schatzkammern und die Geiseln; hierauf kehrte er nach Samaria zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Ist nicht der Rest der Geschichte des Joas und was er sonst getan, sowie seine Tapferkeit, und wie er mit Amasja, Judas König, kämpfte, im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Als sich Joas zu seinen Vätern legte, ward er in Samaria bei den Königen Israels begraben, und sein Sohn Jeroboam ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Judas König Amasja, des Joas Sohn, lebte nach dem Tode des Königs von Israel, Joas, des Joachazsohnes, noch fünfzehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Ist nicht der Rest der Geschichte Amasjas im Geschichtsbuche der Könige von Juda aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Sie verschworen sich aber zu Jerusalem gegen ihn, und er floh nach Lakis. Da schickten sie ihm nach Lakis Leute nach und töteten ihn dort');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Dann überführten sie ihn auf Rossen, und er ward in Jerusalem bei seinen Vätern in der Davidsstadt begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Da nahm das ganze Volk Juda den Azarja, der sechzehn Jahre alt war, und machte ihn zum König an seines Vaters Amasja Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Er baute Elat auf und brachte es wieder an Juda, nachdem sich der König zu seinen Vätern gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Im fünfzehnten Jahre des Judakönigs Amasja, des Joassohnes, ward Jeroboam, des Israelkönigs Joas Sohn, König in Samaria für einundvierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Er tat, was dem Herrn mißfiel. Er ließ nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Er brachte das Gebiet Israels von der Gegend um Hamat bis zum Meer der Wüste zurück, nach dem Worte des Herrn, des Gottes Israels, das er durch seinen Diener, den Propheten Jonas, Amittais Sohn, aus Gat Chepher gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Denn der Herr sah, daß Israels Not gar bitter war, völlig eingeschlossen und verlassen war es, und niemand half Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Der Herr aber dachte nicht daran, Israels Namen unter dem Himmel zu tilgen. Und so half er ihnen durch den Joassohn Jeroboam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Ist nicht der Rest der Geschichte Jeroboams und alles, was er sonst getan, sowie seine Tapferkeit, wie er Krieg geführt und Damaskus nebst Hamat durch Israel für Juda zurückgebracht hat, im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Als sich Jeroboam zu seinen Vätern legte, ward er zu Samaria bei Israels Königen begraben, und sein Sohn Sakarja ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Im siebenundzwanzigsten Jahre des Israelkönigs Jeroboam ward des Judakönigs Amasja Sohn, Azarja, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Er war sechzehn Jahre alt, als er König wurde, und regierte zweiundfünfzig Jahre in Jerusalem. Seine Mutter hieß Jekolja und war aus Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Er tat, was dem Herrn gefiel, ganz wie sein Vater Amasja getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Nur die Höhen waren nicht beseitigt. Noch immer opferte und räucherte das Volk auf den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Der Herr aber schlug den König, und er ward bis zu seinem Todestage aussätzig. Er wohnte in einem besonderen Hause. Des Königs Sohn Jotam stand dem Hause vor und richtete das Volk des Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Ist nicht der Rest der Geschichte Azarjas und alles, was er sonst getan, im Geschichtsbuche der Könige Judas aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Als sich Azarja zu seinen Vätern legte, begrub man ihn in der Davidsstadt bei seinen Ahnen. Und sein Sohn Jotam ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Im achtunddreißigsten Jahre des Judakönigs Azarja ward Jeroboams Sohn Zakarja König über Israel zu Samaria für sechs Monate.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Er tat, was dem Herrn mißfiel, wie seine Väter getan hatten. Er ließ nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Gegen ihn verschwor sich des Jabes Sohn Sallum, schlug ihn zu Ibleam und tötete ihn. Er ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Ist nicht der Rest der Geschichte Zakarjas im Geschichtsbuche der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Dies ist des Herrn Wort, das er zu Jehu gesprochen hat: \"Söhne bis ins vierte Glied sollen von dir auf Israels Thron sitzen!\" Und so geschah es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, des Jabes Sohn, ward König im neununddreißigsten Jahre des Judakönigs Uzzia und regierte einen Monat zu Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Da zog Menachem, des Gadis Sohn, von Tirsa heran, kam nach Samaria, schlug Sallum, des Jabes Sohn, zu Samaria und tötete ihn. So ward er an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Der Rest der Geschichte Sallums und seine Verschwörung, die er anzettelte, sind ja im Buche der Geschichte der Könige Israels aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Damals verwüstete Menachem Tiphsach und alles, was darin war, und seine Umgebung von Tirsa an. Denn man hatte nicht die Tore geöffnet. Er schlug alle nieder. Ihre Schwangeren aber ließ er aufschlitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Im neununddreißigsten Jahre des Judakönigs Azarja ward Menachem, des Gadis Sohn, über Israel König zu Samaria für zehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Er tat, was dem Herrn mißfiel. Auch er ließ nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel all seine Tage verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Da kam der Assyrerkönig Phul in das Land. Und Menachem gab dem Phul tausend Talente Silber, daß seine Hand mit ihm sei, um die Herrschaft in seiner Hand zu festigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Und Menachem legte das Silber auf Israel um, auf alle vermöglichen Leute, um es dem Assyrerkönig zu geben, fünfzig Ringe auf jeden. Da zog der Assyrerkönig ab. Er blieb nicht länger dort im Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Ist nicht der Rest der Geschichte Menachems und alles, was er sonst getan, im Buche der Geschichte der Könige Israels aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menachem legte sich zu seinen Vätern, und sein Sohn Pekachja ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Im fünfzigsten Jahre des Judakönigs Azarja ward Pekachja, Menachems Sohn, König über Israel zu Samaria für zwei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Er tat, was dem Herrn mißfiel. Er ließ nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Da verschwor sich gegen ihn Pekach, Remaljas Sohn, sein Adjutant, und schlug ihn zu Samaria in der Burg des Königshauses, samt fünfzig Männern von den Söhnen der Gileaditer aus Argob und Areopolis. So tötete er ihn und ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Ist nicht der Rest der Geschichte Pekachjas und alles, was er sonst getan, im Buche der Geschichte der Könige Israels aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Im zweiundfünfzigsten Jahre des Judakönigs Azarja ward Pekach, Remaljas Sohn, König über Israel zu Samaria für zwanzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Er tat, was dem Herrn mißfiel. Er ließ nicht von des Nebatsohnes Jeroboam Sünden, zu denen er Israel verführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'In den Tagen Pekachs, des Königs von Israel, kam der Assyrerkönig Tiglatpileser und nahm Ijjon, Abel Bet Maaka, Janoach, Kedes, Chasor, Gilead, Galiläa und das ganze Land Naphtali und führte sie gefangen nach Assyrien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Hosea, Elas Sohn, aber verschwor sich gegen Pekach, Remaljas Sohn, schlug ihn und tötete ihn. So ward er König an seiner Statt im zwanzigsten Jahre des Uzziasohnes Jotam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Ist nicht der Rest der Geschichte Pekachs und alles, was er sonst getan, im Buche der Geschichte der Könige Israels aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Im zweiten Jahre Pekachs, des Remaljasohnes und Königs von Israel, ward Jotam, des Judakönigs Uzzia Sohn, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Er war fünfundzwanzig Jahre alt, als er König wurde, und sechzehn Jahre regierte er zu Jerusalem. Seine Mutter hieß Jerusa und war die Tochter Sadoks.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Er tat, was dem Herrn wohlgefiel, ganz wie sein Vater Uzzia getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Nur die Höhen waren nicht abgeschafft. Noch immer opferte und räucherte das Volk auf den Höhen. Er baute das obere Tor am Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Ist nicht der Rest der Geschichte Jotams und alles, was er sonst getan, im Buche der Geschichte der Könige von Juda aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'In jenen Tagen begann der Herr, gegen Juda Arams König Resin und Pekach, Remaljas Sohn, loszulassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Als sich Jotam zu seinen Vätern legte, ward er bei seinen Vätern in der Stadt seines Vaters David begraben. Und sein Sohn Achaz ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Im siebzehnten Jahre des Remaljasohnes Pekach ward des Judakönigs Jotam Sohn, Achaz, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achaz war zwanzig Jahre alt, als er König wurde, und sechzehn Jahre regierte er zu Jerusalem. Er tat aber nicht, was dem Herrn, seinem Gott, gefiel, wie sein Ahn David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Er wandelte auf dem Wege der Könige Israels. Er führte sogar seinen Sohn durchs Feuer, nach Art der Greuel der Heiden, die der Herr vor Israels Söhnen vertrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Er opferte und räucherte auf den Höhen, auf den Hügeln und unter jedem grünen Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Damals zogen Arams König Resin und Israels König Pekach, Remaljas Sohn, nach Jerusalem zum Angriff, und sie bedrängten Achaz. Aber sie hatten nicht stürmen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'In jener Zeit brachte Arams König, Resin, Elat an Aram zurück; er warf nämlich die Judäer aus Elat. Dann kamen die Edomiter nach Elat und siedelten dort bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Da sandte Achaz Boten an den Assyrerkönig Tiglatpileser und ließ sagen: \"Dein Sklave und dein Sohn bin ich. Zieh herauf und rette mich aus der Faust des Königs von Aram und der des Königs von Israel, die mich angreifen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Und Achaz nahm das Silber und das Gold, das sich im Hause des Herrn und in des Königshauses Schatzkammern fand, und sandte es dem Assyrerkönig als Geschenk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Und der Assyrerkönig willfahrte ihm. So zog der Assyrerkönig nach Damaskus, eroberte es und führte es gefangen nach Kir. Den Resin aber tötete er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Da ging der König Achaz dem Assyrerkönig Tiglatpileser nach Damaskus entgegen. Dabei sah er den Altar, der in Damaskus war. Und der König Achaz sandte an den Priester Uria Maße und Abbild des Altars entsprechend seiner ganzen Anlage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Und der Priester Uria baute den Altar. Genauso, wie König Achaz es aus Damaskus übersandt hatte, tat der Priester Uria, bevor der König Achaz von Damaskus kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Der König kam nun von Damaskus. Da besah der König den Altar. Dann trat der König an den Altar heran und bestieg ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Er ließ sein Brand- und sein Speiseopfer in Rauch aufgehen, goß sein Trankopfer aus und sprengte das Blut seines Mahlopfers an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Den ehernen Altar aber, der vor dem Herrn stand, rückte er von der Vorderseite des Tempels weg, von der Stelle zwischen dem Altar und dem Hause des Herrn, und stellte ihn an die Nordseite des Altares.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Und der König Achaz befahl dem Priester Uria: \"Auf dem großen Altar laß in Rauch aufgehen das Morgenbrandopfer, das Abendspeiseopfer und das Königsbrandopfer samt seinem Speiseopfer, sowie das Brandopfer des gesamten Volkes im Lande samt seinem Speise- und Trankopfer und sprenge alles Brandopfer- und Schlachtopferblut an ihn! Der eherne Altar bleibe mir zur Schau!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Und der Priester Uria tat, wie ihm der König Achaz befohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Der König Achaz zerschlug die Rahmen an den Gestühlen und nahm von ihnen die Becken. Auch das Meer nahm er von den ehernen Rindern, auf denen es stand, und setzte es auf ein Steinpflaster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Die Sitzempore, die man im Haus gebaut hatte, und den äußeren Eingang für den König verlegte er im Hause des Herrn wegen des Assyrerkönigs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Ist nicht der Rest der Geschichte des Achaz und alles, was er sonst getan, im Buche der Geschichte der Könige Judas aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Als Achaz sich zu seinen Vätern legte, ward er bei seinen Vätern in der Davidsstadt begraben, und sein Sohn Ezechias ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Im zwölften Jahre des Judakönigs Achaz ward Hosea, Elas Sohn, zu Samaria König aber Israel für neun Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Er tat, was dem Herrn mißfiel, aber nicht wie Israels Könige, die vor ihm gewesen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Gegen ihn zog der Assyrerkönig Salmanassar heran. Und Hosea ward ihm untertan und lieferte ihm Abgaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Da fand der Assyrerkönig an Hosea Verrat, weil er Boten an Ägyptens König So gesandt und nicht mehr die jährlichen Abgaben an den Assyrerkönig geleistet hatte. Darum verhaftete ihn der Assyrerkönig und legte ihn gefesselt ins Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Und der Assyrerkönig besetzte das ganze Land. Er zog auch gegen Samaria und belagerte es drei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Im neunten Jahre Hoseas aber eroberte der Assyrerkönig Samaria; er führte Israel nach Assyrien und gab ihm Wohnsitze in Chalach und am Chabor, dem Flusse Gozans, und in Mediens Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Die Söhne Israels hatten am Herrn, ihrem Gott, gesündigt, der sie aus Ägypterland, aus des ägyptischen Königs Pharao Hand, weggeführt hatte. Sie verehrten andere Götter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'und wandelten in den Satzungen der Heiden, die der Herr vor Israels Söhnen vertrieben hatte. Und erst Israels Könige! Was hatten sie getan?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Die Söhne Israels führten unwahre Reden über den Herrn, ihren Gott, und bauten sich Höhen in all ihren Städten, vom Wachtturm bis zur befestigten Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Auch setzten sie sich Steinmale und Ascheren auf jedem hohen Hügel und unter jedem grünen Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Dort räucherten sie auf allen Höhen wie die Heiden, die der Herr vor ihnen weggeführt, und taten böse Dinge, um den Herrn zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Sie dienten den Götzen, von denen der Herr zu ihnen gesagt: \"Tut dies nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Der Herr verwarnte Israel und Juda durch seine Propheten, durch jeden Seher mit den Worten: \"Kehrt um von euren bösen Wegen und haltet meine Satzungen und Vorschriften genau der Lehre nach, die ich euren Vätern geboten, nach dem, was ich durch meine Diener, die Propheten, euch entboten habe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Sie aber hatten nicht gehorcht, sondern waren halsstarrig wie ihre Väter, die dem Herrn, ihrem Gott, nicht vertraut hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Sie mißachteten seine Gesetze und seinen Bund, den er mit ihren Vätern geschlossen, ebenso seine Warnungen, durch die er sie gewarnt hatte. Sie gingen dem Nichtigen nach und verfielen der Nichtigkeit wie die Heiden, die rings um sie waren, obgleich der Herr ihnen verboten hatte, zu tun wie jene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Sie verließen alle Gebote des Herrn, ihres Gottes, und machten sich Gußbilder, zwei Kälber. Auch machten sie Ascheren, beteten das ganze Himmelsheer an und dienten dem Baal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Sie führten ihre Söhne und Töchter durch das Feuer, trieben Wahrsagerei und Zeichendeuterei und gaben sich dazu her, zu tun, was dem Herrn mißfiel, um ihn zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Da zürnte der Herr heftig über Israel und schaffte es von seinem Angesichte weg. Nichts blieb übrig als allein der Stamm Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Aber auch Juda hielt nicht die Gebote des Herrn, seines Gottes, sondern wandelte in Israels Satzungen, die es selber gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'So verwarf der Herr Israels ganzen Stamm und demütigte ihn. Er gab ihn in die Hand von Plünderern, bis er sie schließlich ganz von seinem Angesicht verstieß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Denn Israel hatte sich vom Davidshause losgerissen und Nebats Sohn Jeroboam zum König gemacht. Jeroboam aber drängte Israel vom Herrn hinweg und verleitete es zu schwerer Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'So wandelten Israels Söhne ganz in Jeroboams Sünden, die er getan. Sie ließen nicht davon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'bis der Herr schließlich Israel von seinem Antlitz verstieß, wie er durch all seine Diener, die Propheten, gedroht hatte. So wanderte Israel von seiner Heimat in die assyrische Gefangenschaft bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Der Assyrerkönig brachte nun Leute aus Babel, Kuta, Awwa, Hamat und Sepharvaim und siedelte sie in Samarias Städten statt der Söhne Israels an. So nahmen sie Samaria in Besitz und wohnten in seinen Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'In der ersten Zeit, da sie dort wohnten, fürchteten sie den Herrn nicht. Da sandte der Herr Löwen gegen sie, und diese würgten unter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Da meldete man dem Assyrerkönig: \"Die Völker, die du weggeführt und in Samarias Städten angesiedelt hast, kennen nicht das Recht des Landesgottes. Darum sandte er die Löwen unter sie, und diese würgten sie, weil sie nicht des Landesgottes Recht kennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Da befahl der Assyrerkönig: \"Führt dorthin einen der Priester zurück, die ihr von dort weggeführt habt! Er gehe und wohne dort und belehre sie über das Recht des Landesgottes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'So kam einer der aus Samaria weggeführten Priester und wohnte in Betel. Und er lehrte sie, wie sie den Herrn zu fürchten hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Sie machten sich aber, Volk für Volk, jedes seinen eigenen Gott und stellten ihn in das Haus der Höhen, die die Samariter gemacht hatten, jedes Volk in seinen Städten, wo es wohnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'So machten sich die Leute von Babel Sukkot Benot, die Leute von Kuta den Nergal, die Leute von Hamat eine Aschima');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'und die Arriter den Nibchaz und den Tartak. Die Sepharviter verbrannten ihre Kinder im Feuer zu Ehren des Adarmelek und des Anammelek, der Götter von Sepharvaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Sie fürchteten aber auch den Herrn und bestellten sich aus ihren Vornehmen Leute zu Höhenpriestern, und diese waren für sie im Höhenhaus tätig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Den Herrn fürchteten sie zwar; aber ihren Göttern dienten sie auch nach der Art der Heiden, von denen man sie weggeführt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Bis auf diesen Tag tun sie nach den alten Gebräuchen. Sie fürchten zwar den Herrn, tun aber auch nach ihren Geboten und Rechten, wie nach der Lehre und dem Gebot, das der Herr den Söhnen Jakobs gegeben hat, dem er den Namen Israel beilegte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'und mit denen der Herr einen Bund geschlossen und ihnen geboten hatte: \"Fürchtet nicht andere Götter! Betet sie nicht an! Dient ihnen nicht! Opfert ihnen nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Sondern nur den Herrn, der euch aus Ägypterland mit großer Kraft und ausgestrecktem Arm herausgeführt hat, fürchtet und ihn betet an und ihm opfert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Und die Satzungen und Rechte, die Lehre und das Gebot, das er euch aufgeschrieben, sollt ihr beobachten und allzeit befolgen! Aber andere Götter fürchtet nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Den Bund, den ich mit euch geschlossen, sollt ihr nicht vergessen und keine anderen Götter fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Nur den Herrn, euren Gott, sollt ihr fürchten! Dann rettet er euch aus all eurer Feinde Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Aber sie gehorchten nicht, sondern taten nach ihrer alten Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'So fürchteten diese Heidenvölker zwar den Herrn; aber sie dienten auch ihren Schnitzbildern. Und selbst ihre Söhne und Enkel tun, wie ihre Väter bis auf diesen Tag getan haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Im dritten Jahre Hoseas, des Elasohnes, des Königs von Israel, ward des Judakönigs Achaz Sohn, Ezechias, König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Er war fünfundzwanzig Jahre alt, als er König ward, und neunundzwanzig Jahre regierte er zu Jerusalem. Seine Mutter hieß Abi und war des Zakarja Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Er tat, was dem Herrn gefiel, ganz wie sein Ahn David getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Er schaffte die Höhen ab, zertrümmerte die Denksteine, hieb die Aschera um und zerschlug die eherne Schlange, die Moses gemacht hatte. Denn bis zu jener Zeit hatten die Söhne Israels ihr geräuchert. Man nannte sie Nechustan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Er vertraute auf den Herrn, Israels Gott. Und nach ihm war unter allen Königen Judas keiner mehr wie er, auch nicht unter denen vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Er hing dem Herrn an, wich nicht von ihm und hielt seine Gebote, die der Herr dem Moses befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Und der Herr war mit ihm. Bei allem, was er tat, hatte er Glück. Auch ward er dem Assyrerkönig abtrünnig und diente ihm nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Er schlug auch die Philister bis nach Gaza hin, und zwar bis zu dessen Grenze, vom Wachtturm bis zur befestigten Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Im vierten Jahre des Königs Ezechias, das ist im siebten Jahre Hoseas, des Elasohnes und Königs von Israel, zog der Assyrerkönig Salmanassar gegen Samaria und belagerte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Nach drei Jahren eroberte man es. Im sechsten Jahre des Ezechias, das ist im neunten Jahre Hoseas, des Königs von Israel, wurde Samaria erobert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Der Assyrerkönig führte Israel gefangen nach Assyrien und siedelte sie in Chalach an, am Chabor, auf den Bergen Gozans und in Mediens Bergen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Denn sie hatten auf die Stimme des Herrn, ihres Gottes, nicht gehört, sondern seinen Bund übertreten, alles, was Moses, des Herrn Diener, geboten hatte; sie hatten nicht darauf gehört noch danach getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Und im vierzehnten Jahre des Königs Ezechias zog der Assyrerkönig Sanherib gegen alle festen Städte Judas heran und nahm sie ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Da sandte Judas König Ezechias zum Assyrerkönig nach Lakis und ließ sagen: \"Ich habe mich verfehlt. Laß von mir ab! Was du auferlegst, will ich tragen.\" Da legte der Assyrerkönig dem Judakönig Ezechias 300 Talente Silber und 30 Talente Gold auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Ezechias gab alles Silber her, das sich im Hause des Herrn und in den Schatzkammern des Königshauses vorfand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Zu jener Zeit ließ Ezechias von den Türen des Tempels des Herrn und von den Türpfosten, die Judas König Ezechias hatte überziehen lassen, das Gold wegnehmen und gab es dem Assyrerkönig. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Der Assyrerkönig sandte den Tartan, den Rabsaris und den Rabsake von Lakis aus zum König Ezechias mit starker Heeresmacht nach Jerusalem. Sie zogen hinauf und kamen nach Jerusalem. Als sie hinaufzogen und ankamen, stellten sie sich an der Wasserleitung des oberen Teiches auf, an der Straße zum Walkerfeld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Sie riefen nach dem König. Da kam Eljakim, Chilkias Sohn, des Hauses Vorstand, mit dem Schreiber Sebna und dem Kanzler Joach, Asaphs Sohn, zu ihnen heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Rabsake sprach zu ihnen: \"Sagt doch dem Ezechias: So spricht der Großkönig, der König von Assyrien: \'Was ist es mit dieser Zuversicht, die du hegst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Meinst du, bloßes Reden sei schon Einsicht und Kraft zum Krieg? Auf wen verläßt du dich jetzt, daß du von mir abfällst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Du verläßt dich auf diesen abgebrochenen Rohrstab Ägypten, der jedem, der sich darauf stützt, in die Hand fährt und sie durchbohrt. So ist Pharao, Ägyptens König, für alle, die auf ihn vertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Wenn ihr mir aber sagt: \"Wir verlassen uns auf den Herrn, unseren Gott\" - ja, ist nicht er es, dessen Höhen und Altäre Ezechias abgeschafft hat, als er Juda und Jerusalem befahl: \"Vor diesem Altare sollt ihr zu Jerusalem anbeten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nun wette mit meinem Herrn, dem König von Assyrien: Ich gebe dir zweitausend Rosse, kannst du ihnen auch Reiter für dich beschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Wenn du schon einen der geringsten Knechte meines Herrn abweisen mußt, wie kannst du dich auf Ägypten wegen Wagen und Rossen verlassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Bin ich denn ohne den Herrn gegen diesen Ort heraufgezogen, ihn zu verheeren? Der Herr hat zu mir gesprochen: \"Zieh gegen dies Land und verheere es!\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Da sprachen Eljakim, Sebna und Joach zu Rabsake: \"Sprich mit deinen Knechten Aramäisch! Denn wir verstehen es. Aber sprich nicht mit uns judäisch vor den Ohren der Leute auf der Mauer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Da sprach Rabsake: \"Hat mich der Herr nur zu deinem Herrn gesandt und zu dir, solches zu künden, und nicht auch zu den Männern, die auf der Mauer sitzen und die ihren Kot und Harn mit euch essen und trinken müssen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Und Rabsake trat vor und rief mit lauter Stimme auf judäisch: \"Hört die Worte des Großkönigs, des Königs von Assyrien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'So spricht der König: \'Ezechias täusche euch nicht! Er kann euch nicht retten aus meiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Laßt euch nicht von Ezechias auf den Herrn vertrösten mit den Worten: \"Der Herr rettet uns. Diese Stadt wird nicht in des Assyrerkönigs Hand gegeben!\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Hört nicht auf Ezechias! Denn also spricht der König Assyriens: \'Schließt Frieden mit mir und kommt zu mir heraus! Dann dürft ihr jeder von seinem Weinstock und Feigenbaum essen und jeder aus seinem Brunnen Wasser trinken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'bis ich komme und euch hole in ein Land wie euer Land, in ein Land voll Korn und Wein, ein Land voll Getreide und Weinbergen, voll Ölbäumen und Honig, daß ihr lebet und nicht sterbet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Hört nicht auf Ezechias, wenn er euch beredet: \"Der Herr wird uns retten!\" Ja, haben der Heiden Götter ihr Land aus der Hand des Assyrerkönigs gerettet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Wo sind die Götter von Hamat und Arpad? Wo die Götter von Sepharvaim, Hena und Jova? Haben sie Samaria aus meiner Hand errettet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Wer ist unter all den Göttern dieser Länder, der sein Land aus meiner Hand errettet hätte, daß der Herr Jerusalem aus meiner Hand retten sollte?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Da schwieg das Volk und gab ihm keine Antwort. Denn so war des Königs Befehl: \"Antwortet ihm nichts!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Eljakim aber, Chilkias Sohn und Hausvorstand, der Schreiber Sebna und der Kanzler Joach, Asaphs Sohn, kamen vor Ezechias, die Kleider zerrissen, und berichteten ihm des Rabsake Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Als der König Ezechias es hörte, zerriß er seine Gewänder, hüllte sich in ein Bußgewand und ging in das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Dann sandte er Eljakim, den Hausvorstand, den Schreiber Sebna und die Ältesten der Priester, in Bußgewänder gehüllt, zu dem Propheten Isaias, des Amos Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Sie sprachen zu ihm: \"So spricht Ezechias: \'Ein Tag der Not und schmählicher Züchtigung ist dieser Tag. Denn Kinder kommen an den Durchbruch; da fehlt die Kraft, sie zu gebären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Vielleicht hört der Herr, dein Gott, auf alle die Reden des Rabsake, den sein Herr, der Assyrerkönig, gesandt, den lebendigen Gott zu lästern, und zeigt durch Worte, daß der Herr, dein Gott, es gehört hat. So leg Fürsprache für den noch vorhandenen Überrest ein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Des Ezechias Diener kamen also zu Isaias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Da sprach Isaias zu ihnen: \"Sprecht so zu eurem Herrn! So spricht der Herr: \'Hab keine Angst der Reden wegen, die du angehört hast, mit denen die Knechte des Assyrerkönigs mich gelästert haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Ich gebe ihm einen Geist ein, so daß er eine Kunde hört; dann geht er in sein Land zurück. Ich fälle ihn durch das Schwert in seinem Land.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Darauf kehrte Rabsake zurück und traf den Assyrerkönig bei der Belagerung von Libna. Er hatte nämlich gehört, er sei von Lakis aufgebrochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Und jener hörte von Tirhaka, dem König von Äthiopien: \"Er zieht aus, mit dir zu kämpfen.\" Da sandte er abermals Boten an Ezechias und ließ ihm sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '\"So sprecht zum Judakönig Ezechias: \'Daß dich dein Gott nicht täusche, auf den du vertraust, und so denkst: Jerusalem wird nicht in des Assyrerkönigs Hand gegeben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Du hast selbst gehört, wie die Assyrerkönige allen Ländern getan und sie gebannt haben. Und du willst gerettet werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Wurden die Heiden, die meine Väter vernichtet haben, von ihren Göttern gerettet? Gozan, Charan, Reseph und die Söhne Edens zu Telassar?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Wo ist der König von Hamat, der König von Arpad, der König der Stadt Sepharvaim, der von Hena und von Eva?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Ezechias nahm den Brief aus der Hand des Boten und las ihn. Dann ging er in das Haus des Herrn. Hier breitete ihn Ezechias vor dem Herrn aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Dann betete Ezechias also zum Herrn: \"Herr der Heerscharen, Gott Israels, der Du thronst über Cheruben! Nur Du allein bist Gott für alle Erdenreiche. Du hast den Himmel und die Erde gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Neige, Herr, Dein Ohr und höre! Herr! Öffne Deine Augen! Schau darein. Merk auf die Worte Sanheribs, die er verlauten ließ, um den lebendigen Gott zu lästern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Wahr ist es, Herr: Die Könige von Assur haben alle Länder stark verheert');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'und ihre Götter in das Feuer geworfen. Denn das waren keine Götter, nur Werk von Menschenhänden, Holz und Stein. So konnte man sie leicht vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Nun aber Herr, Du unser Gott! Errette uns aus seiner Hand, damit alle Reiche der Erde sehen, daß Du allein der Herr bist!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Da sandte Isaias, des Amos Sohn, zu Ezechias und ließ sagen: \"So spricht der Herr, Israels Gott: \'Was du gebetet wegen Sanherib, des Königs von Assyrien, das habe ich gehört.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Dies ist das Wort, das über ihn der Herr ausspricht: \'Es spottet deiner und verachtet dich die Jungfrau, Sions Tochter. Es schüttelt hinter dir das Haupt die Tochter von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Wen lästerst du? Wen schmähst du? Und gegen wen erhebst du deine Stimme? Du schlugst deine stolzen Augen auf, dem Heiligen Israels zum Trotz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Durch deine Knechte sprachest du vermessen von dem Herrn: \"Mit meiner starken Reiterei dringe ich hinauf bis zu der Berge höchsten Höhen, selbst auf den höchsten Libanon, und fälle seine höchsten Zedern und seine schönsten Fichten. Ich dringe bis zu seinem höchsten Gipfel, in seine reichsten Waldungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Firngewässer trinke ich zur Kühlung, mit meinem Fuße trete ich die Gletscherströme alle aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Hast du denn nicht gehört, daß ich seit langem dies geplant, von alten Zeiten her bestimmt? Jetzt ließ ich Ähnliches geschehen, und so warst du imstande, feste Städte in Trümmerhaufen zu verwandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Und die in ihnen wohnten, für die Verteidigung zu schwach, erzitterten und bebten und wurden wie das Gras des Feldes, wie zartes Grün, wie Hälmchen auf den Dächern und wie vermengtes, unreifes Korn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Bekannt ist mir dein Aufstehen und dein Niedersitzen. Dein Gehen und dein Kommen kenne ich gut, und auch dein Toben gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Dein Toben und dein Ungestüm kam mir zu Ohren. So lege ich denn meinen Ring in deine Nase und meinen Zaum in deine Lippen und führe dich auf gleichem Wege heim, auf dem du hergekommen bist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Dies diene dir als Zeichen! In diesem Jahre iß, was von selber wächst! Im zweiten Jahre, was aus den Wurzeln wächst! Im dritten Jahre aber sät und erntet wieder und pflanzet Weinberge! Genießet ihre Früchte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Der gerettete Rest des Hauses Juda treibt in die Tiefe Wurzeln und trägt oben Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Denn aufblüht in Jerusalem ein Rest und ein gerettet Häuflein auf dem Sionsberg. Der Eifer des Herrn der Heerscharen tut dies.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Darum spricht der Herr über den Assyrerkönig so: \'Er kommt nicht in diese Stadt und schießt keinen Pfeil hinein, hält ihr keinen Schild entgegen und wirft keinen Wall um sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Auf dem Wege, den er kam, kehrt er um. Er kommt nicht in diese Stadt.\' Ein Spruch des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, '\'Ich schirme diese Stadt und helfe ihr um meiner selbst und meines Dieners David willen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'In der gleichen Nacht ging des Herrn Engel aus und schlug im Assyrerlager 185.000 Mann. Am anderen Morgen waren sie alle Leichen, Tote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Der Assyrerkönig Sanherib brach auf und zog ab. Er kehrte heim und blieb in Ninive.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Als er im Hause seines Gottes Nisroch betete, schlugen ihn seine Söhne Adarmelech und Sareser mit dem Schwert. Sie flohen ins Land Ararat, und sein Sohn Asarhaddon ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'In jener Zeit war Ezechias todkrank gewesen. Da besuchte ihn der Prophet Isaias, des Amos Sohn, und sprach zu ihm: \"So spricht der Herr: \'Bestelle dein Haus! Denn sterben mußt du und wirst nicht genesen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Da wandte sich Ezechias mit seinem Antlitz zur Wand und betete zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Er sprach: \"Ach Herr! Gedenke doch, daß ich vor Dir treu und mit ungeteiltem Herzen wandelte und daß ich tat, was Dir gefiel!\" Dann brach Ezechias in lautes Weinen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Aber noch war Isaias nicht aus dem mittleren Vorhof, da erging das Wort des Herrn an ihn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '\"Kehre um und künde Ezechias, dem Fürsten meines Volkes: \'So spricht der Herr, des David, deines Ahnen, Gott: Ich habe dein Gebet gehört und deine Tränen angesehen. So will ich dich denn heilen. Am dritten Tage kannst du schon ins Haus des Herrn gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Ich füge deinen Lebenstagen fünfzehn Jahre noch hinzu und rette dich aus des Assyrerkönigs Hand, dich und die Stadt. Ich schirme diese Stadt um meinetwillen und wegen meines Dieners David.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Isaias sprach: \"Holt ein Feigenpflaster!\" Sie holten es und legten es auf das Geschwür. Da genas er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ezechias aber sagte zu Isaias: \"Was ist das Zeichen, daß mich der Herr heilen wird und daß ich am dritten Tage in das Haus des Herrn gehen kann?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Isaias sprach: \"Dies sei dir das Zeichen vom Herrn, daß der Herr tut, was er verspricht: \'Soll der Schatten zehn Stufen vorrücken oder zehn Stufen zurückgehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezechias sprach: \"Dem Schatten ist es ein Leichtes, zehn Stufen abwärts zu gehen. Nein! Der Schatten soll um zehn Stufen zurückkehren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Da rief der Prophet Isaias zum Herrn, und er ließ den Schatten um zehn Stufen zurückgehen an den Stufen des Achaz, die er schon hinabgerückt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Zu jener Zeit sandte Merodach Baladan, Baladans Sohn, der König von Babel, ein Schreiben mit Geschenken an Ezechias. Denn er hatte gehört, daß Ezechias erkrankt sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezechias freute sich darüber und zeigte ihnen sein ganzes Schatzhaus, das Silber und Gold, die Spezereien, das Feinöl und sein ganzes Zeughaus, überhaupt alles, was sich in seinen Schatzkammern fand. Nichts war in seinem Haus und in seiner Reichsverwaltung, was ihnen Ezechias nicht gezeigt hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Da kam der Prophet Isaias zum König Ezechias und sprach zu ihm: \"Was haben die Männer gesagt? Woher kommen sie zu dir?\" Ezechias sagte: \"Aus fernem Lande kommen sie zu mir, aus Babel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Er fragte: \"Was haben sie in deinem Hause gesehen?\" Ezechias sprach: \"Alles haben sie in meinem Hause gesehen. Nichts ist, was ich ihnen in meinen Schatzkammern nicht gezeigt hätte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Da sprach Isaias zu Ezechias: \"Vernimm das Wort des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Tage kommen, wo alles, was in deinem Hause ist, was deine Väter bis auf diesen Tag aufgespeichert, nach Babel gebracht wird. Nichts bleibt zurück.\' So spricht der Herr:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, '\'Auch von deinen Söhnen, die dir entsprossen und die du zeugst, nimmt man einige, daß sie im Palaste des Babelkönigs Kämmerlinge werden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Da sprach Ezechias zu Isaias: \"Heilsam ist das Herrnwort, das du kündest.\" Dann sprach er: \"Sollte es nicht so sein, wenn Friede und Treue herrschen werden, solange ich lebe?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ist nicht der Rest der Geschichte des Ezechias und alle seine Tapferkeit, und wie er den Teich und die Wasserleitung hergestellt und das Wasser in die Stadt geleitet hat, im Buche der Geschichte der Könige von Juda aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Als sich Ezechias zu seinen Vätern legte, wurde sein Sohn Manasse an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse war zwölf Jahre alt, als er König wurde, und er regierte fünfundfünfzig Jahre zu Jerusalem. Seine Mutter hieß Chephsiba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Er tat, was dem Herrn mißfiel, ähnlich den Greueln der Heiden, die der Herr vor den Israeliten vertrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Er baute wieder die Höhen auf, die sein Vater Ezechias zerstört hatte, errichtete dem Baal Altäre und machte eine Aschera, wie Israels König Achab getan. Auch betete er das ganze Himmelsheer an und diente ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Auch hatte er Altäre im Hause des Herrn gebaut, von dem der Herr gesagt: \"Jerusalem mache ich zum Sitze meines Namens.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Er baute aber auch dem ganzen Himmelsheere Altäre in beiden Vorhöfen im Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Ferner führte er seinen Sohn durch\'s Feuer, trieb Zauberei und Wahrsagerei und befaßte sich mit Totenbeschwörern und Zeichendeutern. So tat er vieles, was dem Herrn mißfiel, um ihn zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Er stellte der Aschera Bild, das er gemacht, in das Haus, von dem der Herr zu David und seinem Sohne Salomo gesprochen: \"Dies Haus und dies Jerusalem, das ich aus allen Stämmen Israels erwählt, das mache ich zum Sitze meines Namens ewiglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Ich lasse niemals Israels Füße flüchtig gehen vom Boden, den ich ihren Vätern einst gegeben, wenn sie bedacht sind, so zu tun, wie ich es ihnen anbefohlen, ganz nach dem Gesetze, das ihnen einst mein Diener Moses gegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Doch sie gehorchten nicht. Manasse verführte sie dazu, Schlimmes zu tun, Schlimmeres als die Heiden, die der Herr vor den Israeliten vertilgt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Da sprach der Herr durch seine Diener, die Propheten, also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '\"Manasse, Judas König, der tut diese Greuel. Er tut noch Schlimmeres, als all das war, was die Amoriter einst getan, die vor ihm dagewesen, verführte er doch Juda, daß es sündigte mit seinen Götzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Darum spricht der Herr, Gott Israels: \'Ich bringe Unheil über Juda und Jerusalem, daß allen, die es hören, beide Ohren gellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Ich bringe an Jerusalem Samarias Meßschnur und des Achabhauses Waage und wische dann Jerusalem so aus, gleichwie man eine Schüssel wischt und sie dann umstürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Und so verstoße ich dann den Rest meines Eigentums und gebe sie in ihrer Feinde Hand, daß sie zum Raube und zur Beute allen ihren Feinden werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Sie tun, was mir mißfällt. Sie reizten mich zum Zorn von dem Tage an, da ihre Väter aus Ägypten zogen, bis auf diesen Tag.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Dazu vergoß Manasse sehr viel unschuldiges Blut, bis er damit Jerusalem von einer Ecke bis zur anderen erfüllte, außer seiner Missetat, daß er Juda verführte, zu tun, was dem Herrn mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Ist nicht der Rest der Geschichte des Manasse und alles, was er sonst getan, und sein Frevel, den er tat, im Buche der Geschichte der Könige Judas aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Als sich Manasse zu seinen Vätern legte, wurde er im Garten seines Hauses, in Uzzas Garten, begraben. Sein Sohn Amon ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amon war zweiundzwanzig Jahre alt, als er König wurde, und zwei Jahre regierte er zu Jerusalem. Seine Mutter hieß Mesullemet und war des Charus Tochter aus Jotba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Er tat, was dem Herrn mißfiel, wie sein Vater Manasse getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Er wandelte ganz auf dem Weg, den sein Vater gewandelt, und diente den Götzen, denen sein Vater gedient hatte, und betete sie an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Er verließ den Herrn, den Gott seiner Väter, und wandelte nicht auf des Herrn Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Da verschworen sich des Amon Diener gegen ihn und töteten den König in seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Der eingesessene Volksteil aber erschlug alle, die sich gegen den Amon verschworen hatten. Dann machte der eingesessene Volksteil seinen Sohn Josias an seiner Statt zum König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Ist nicht der Rest der Geschichte Amons, und was er sonst getan, im Buche der Geschichte der Könige Judas aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Man begrub ihn in seinem Begräbnis in Uzzas Garten, und sein Sohn Josias ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias war achtzehn Jahre alt, als er König wurde, und regierte einunddreißig Jahre zu Jerusalem. Seine Mutter hieß Jedida und war des Adaja Tochter aus Boskat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Er tat, was dem Herrn gefiel, und wandelte ganz auf seines Ahnen David Weg. Er wich nicht nach rechts noch nach links.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Im achtzehnten Jahre des Königs Josias sandte der König den Schreiber Saphan, Asaljas Sohn und Mesullams Enkel, in das Haus des Herrn und sagte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '\"Geh zu dem Hohenpriester Chilkia hinauf und laß ihn das Geld ganz entnehmen, das in das Haus des Herrn gebracht worden ist und das die Schwellenhüter vom Volk eingesammelt haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Er gebe es den Werkführern, die am Hause des Herrn angestellt sind! Diese sollen es an die Arbeiter verausgaben, die an des Herrn Haus den Schaden am Haus ausbessern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'an die Zimmerleute, Bauleute und Holzfäller und zum Ankauf von Holz und Bruchsteinen für die Ausbesserung des Hauses!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Das Geld, das man ihnen gibt, soll mit ihnen nicht verrechnet werden! Denn sie walten nach Treu und Glauben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Da sprach der Hohepriester Chilkia zu dem Schreiber Saphan: \"Ich habe das Buch der Lehre im Hause des Herrn gefunden.\" Und Chilkia gab das Buch dem Saphan, und er las es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Dann kam der Schreiber Saphan zum König und berichtete dem König: \"Deine Diener haben das Geld herausgenommen, das sich im Hause fand; sie gaben es den am Hause des Herrn angestellten Werkführern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Dann meldete der Schreiber Saphan dem König: \"Der Priester Chilkia hat mir ein Buch gegeben.\" Und Saphan las es dem König vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Als der König die Worte des Buches der Lehre vernahm, zerriß er seine Gewänder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Dann befahl der König dem Priester Chilkia, dem Achikam, Saphans Sohn, dem Akbor, Mikas Sohn, dem Schreiber Saphan und dem königlichen Diener Asaja:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '\"Geht und befragt den Herrn für mich, für das Volk und für den Rest Israels in Juda wegen des aufgefundenen Buches! Denn groß ist des Herrn Grimm, der gegen uns entbrannt ist, weil unsere Väter den Worten dieses Buches nicht gehorcht haben, um alles zu tun, was uns vorgeschrieben ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Da ging der Priester Chilkia mit Achikam, Akbor, Saphan und Asaja zu der Prophetin Hulda, dem Weibe des Sallum, des Sohnes Tikwas und Enkels des Charcha, des Kleiderbewahrers. Sie wohnte in Jerusalem im zweiten Bezirk. Da redeten sie mit ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Und sie sprach zu ihnen: \"So spricht der Herr, Israels Gott: \'Sagt jenem Mann, der euch zu mir gesandt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'So spricht der Herr: Ich bringe Unheil über diesen Ort und seine Bewohner, den ganzen Inhalt jenes Buches, das der Judakönig las.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Weil sie mich verließen und anderen Göttern räucherten, um mich mit allem Machwerk ihrer Hände zu kränken, soll mein Grimm erglühen gegen diesen Ort und nicht erlöschen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Zum Judakönig, der euch gesandt, den Herrn zu fragen, sollt ihr also sprechen: \'So spricht der Herr, Israels Gott: Dies sind die Worte, die du vernommen hast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Weil dein Herz weich geworden und du dich vor dem Herrn verdemütigt, als du vernahmst, was ich gegen diesen Ort und seine Einwohner geplant, daß sie zum Fluch und zum Entsetzen werden sollen, und weil du dein Gewand zerrissen und vor mir geweint, so schenke ich Gehör.\' Ein Spruch des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, '\'Darum will ich dich zu deinen Vätern versammeln. Du sollst im Frieden eingehen in dein Grab, und deine Augen sollen nicht mit ansehen all das Unheil, das ich über diesen Ort bringen werde!\'\" Sie berichteten es dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Da sandte der König hin, und man versammelte bei ihm alle Ältesten Judas und Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Dann ging der König zum Hause des Herrn hinauf, mit ihm alle Männer Judas und alle Einwohner Jerusalems, ebenso die Priester und Propheten sowie das ganze Volk, groß und klein. Nun las er vor ihren Ohren alle Worte des Bundesbuches vor, das im Hause des Herrn gefunden worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Dann trat der König an die Säule und schloß vor dem Herrn den Bund, dem Herrn nachzufolgen und seine Gebote, Gebräuche und Satzungen von ganzem Herzen und aus ganzer Seele zu beobachten und so dieses Bundes Worte, die in diesem Buch standen, zu erfüllen. Alles Volk trat in den Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Der König gebot nun dem Hohenpriester Chilkia, dem zweiten Priester und den Schwellenhütern, aus dem Tempel des Herrn alle Geräte hinauszuschaffen, die für den Baal, die Aschera und das ganze Himmelsheer gemacht waren. Dann verbrannte er sie außerhalb Jerusalems in den Fluren am Kidron. Ihren Staub aber brachte er nach Betel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Auch entfernte er die Götzenpriester, die die Könige Judas eingesetzt hatten und die auf den Höhen in Judas Städten und in Jerusalems Umgebung räucherten, ebenso die, die dem Baal, der Sonne, dem Mond und den Tierkreisbildern räucherten, sowie dem ganzen Himmelsheer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Er schaffte die Aschera aus dem Hause des Herrn vor Jerusalem hinaus ins Kidrontal. Er verbrannte sie im Kidrontale, zermalmte sie zu Staub und warf ihren Staub hier auf die Gräber der gemeinen Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Er vernichtete die Geschenke der Tempeldirnen im Hause des Herrn, wo die Weiber Geschenke für die Aschera webten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Dann ließ er aus Judas Städten alle Priester kommen und verunreinigte die Höhen, auf denen die Priester räucherten, von Geba bis Beerseba. Auch riß er die Höhen der Bocksgestalten nieder am Eingang zum Tor des Stadthauptmanns Josue, links am Stadttor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Die Höhenpriester aber hatten keinen Teil mehr an dem Altar des Herrn zu Jerusalem, sondern mußten inmitten ihrer Brüder gewöhnliches Brot essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Er verunreinigte auch das Tophet im Hinnomstal, daß keiner mehr seinen Sohn und seine Tochter für den Moloch durchs Feuer führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Dann beseitigte er die Rosse, die Judas Könige der Sonne aufgestellt hatten, am Eingang ins Haus des Herrn, und zwar bei der Zelle des Kämmerers Netanmelek in den Festungstürmen. Die Wagen der Sonne aber verbrannte er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Die Altäre auf dem Dache am Söller des Achaz, die Judas Könige gemacht hatten, ebenso die Altäre, die Manasse in den beiden Vorhöfen im Hause des Herrn gemacht hatte, brach der König ab und zertrümmerte sie dort. Ihren Schutt warf er in das Kidrontal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Auch die Höhen östlich von Jerusalem und südlich vom Ölberg, die Israels König Salomo dem sidonischen Scheusal Astarte, dem moabitischen Scheusal Kamos und dem ammonitischen Greuel Milkom gebaut, verunreinigte der König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Auch zerbrach er die Steinmale, fällte die Ascheren und füllte ihre Stelle mit Menschengebeinen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Auch den Altar zu Betel, die Höhe, die Nebats Sohn Jeroboam, der Israel zur Sünde verführt, gemacht hatte, auch diesen Altar samt der Höhe brach er ab. Dann verbrannte er die Höhe, zermalmte sie zu Staub und verbrannte die Aschera.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Als sich Josias umsah, erblickte er die Gräber, die dort auf dem Berge waren. Da ließ er die Gebeine aus den Gräbern holen, verbrannte sie auf dem Altar und verunreinigte ihn nach des Herrn Wort, das der Gottesmann kundgetan hatte, der diese Dinge verkündete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Er fragte: \"Was für ein Grabmal sehe ich da?\" Da sagten die Leute der Stadt zu ihm: \"Das ist das Grab des Gottesmannes, der von Juda gekommen ist und dann diese Dinge, die du tust, über den Altar in Betel verkündete.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Er sprach: \"Laßt ihn! Niemand beunruhige seine Gebeine!\" So retteten seine Gebeine die Gebeine des Propheten, der aus Samaria stammte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Auch beseitigte Josias alle Höhenhäuser, die in Samarias Städten waren und die Israels Könige zur Kränkung gemacht hatten. Er tat mit ihnen ganz so, wie er in Betel getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Er opferte alle Höhenpriester dort auf den Altären und verbrannte darauf Menschengebeine. Dann kehrte er nach Jerusalem heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Der König befahl nun allem Volke: \"Haltet dem Herrn, eurem Gott, ein Passah, wie es in diesem Bundesbuche geschrieben steht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Denn ein solches Passah war nicht mehr gehalten worden seit den Tagen der Richter, die Israel gerichtet hatten, noch in irgendeiner Zeit der Könige Israels und Judas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Erst im achtzehnten Jahre des Königs Josias ward dem Herrn zu Jerusalem das Passah gehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Auch vertilgte Josias die Totenbeschwörer, Zeichendeuter, Teraphim, Götzen, überhaupt alle Scheusale, die im Lande Juda und in Jerusalem zu sehen waren, um die Worte der Lehre auszuführen, die geschrieben waren in dem Buche, das der Priester Chilkia im Hause des Herrn gefunden hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Wie er war vor ihm kein König gewesen, der sich zum Herrn bekehrt hätte, von ganzem Herzen, aus ganzer Seele und aus aller Macht, genau nach Mosis Lehre. Auch nach ihm erstand nicht seinesgleichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Und dennoch ließ der Herr nicht von seinem heftigen Zorn, der über Juda erglüht war, ob all der Kränkungen, mit denen ihn Manasse gekränkt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Der Herr sprach: \"Auch Juda schaffe ich weg von meinem Angesicht, so wie ich Israel hinweggeschafft, und ich verwerfe diese Stadt, die ich erwählt, Jerusalem mitsamt dem Haus, von dem ich sprach: \'Mein Name soll dort sein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Ist nicht der Rest der Geschichte des Josias und alles, was er sonst getan, im Buche der Geschichte der Judakönige aufgeschrieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Zu seiner Zeit zog Ägyptens König, Pharao Necho, wegen des Assyrerkönigs zum Euphratstrom. Der König Josias zog ihm nun entgegen. Sobald er ihn aber erblickte, tötete er ihn zu Megiddo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Da fuhren ihn seine Diener tot aus Megiddo, brachten ihn nach Jerusalem und begruben ihn in seiner Grabstätte. Da nahm das eingesessene Volk des Josias Sohn Joachaz. Und sie salbten ihn und machten ihn an seines Vaters Statt zum König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joachaz war dreiundzwanzig Jahre alt, als er König wurde, und drei Monate regierte er zu Jerusalem. Seine Mutter hieß Chamutal und war des Jeremias Tochter aus Libna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Er tat, was dem Herrn mißfiel, ganz wie seine Väter getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Da entsetzte ihn Pharao Necho der Regierung über Jerusalem zu Ribla in der Landschaft Hamat und legte dem Land eine Geldbuße von hundert Talenten Silber und zehn Talenten Gold auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Und Pharao Necho machte des Josias Sohn Eljakim an seines Vaters Josias Statt zum König und änderte seinen Namen in Jojakim. Den Joachaz aber nahm er fest. So kam er nach Ägypten und starb hier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Das Gold und Silber aber gab Jojakim dem Pharao. Er aber schätzte das Land ein, um das Geld nach des Pharaos Befehl abliefern zu können. Er hatte beim eingesessenen Volk von jedem je nach der Schätzung das Silber und Gold eingetrieben, um es dem Pharao Necho abzuliefern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojakim war fünfundzwanzig Jahre alt, als er König wurde, und elf Jahre regierte er zu Jerusalem. Seine Mutter hieß Zebudda und war des Pedaja Tochter aus Ruma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Er tat, was dem Herrn mißfiel, ganz wie seine Väter getan hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Zu seinen Tagen zog Nebukadrezar, Babels König, heran, und Jojakim ward ihm drei Jahre untertan. Dann fiel er wieder von ihm ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Da sandte der Herr gegen ihn die Streifscharen der Chaldäer, Aramäer, Moabiter und Ammoniter. Er sandte sie, Juda zu verheeren nach dem Wort des Herrn, das er durch seine Diener, die Propheten, gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Dies geschah auf Anordnung des Herrn in Juda, um es wegzuschaffen von seinem Antlitz wegen Manasses Sünden, nach all dem, was er getan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'zumal wegen des Blutes der Unschuldigen, das er vergoß, wobei er Jerusalem mit unschuldigem Blut anfüllte. Das aber wollte der Herr nicht vergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Ist nicht der Rest der Geschichte Jojakims und alles, was er sonst getan, im Buche der Geschichte der Judakönige aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Als sich Jojakim zu seinen Vätern legte, ward sein Sohn Jojachin an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Ägyptens König aber zog fortan nicht mehr aus seinem Lande. Denn Babels König hatte vom Bache Ägyptens bis zum Euphratstrom alles erobert, was dem König von Ägypten gehörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jojachin war achtzehn Jahre alt, als er König wurde, und drei Monate regierte er zu Jerusalem. Seine Mutter hieß Nechusta und war des Elnatan Tochter aus Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Er tat, was dem Herrn mißfiel, ganz wie sein Vater getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Zu jener Zeit zogen die Diener des Babelkönigs Nebukadrezar gegen Jerusalem, und die Stadt wurde eingeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Babels König Nebukadrezar griff die Stadt an, und seine Diener belagerten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Da ging Judas König Jojachin zum Babelkönig hinaus, er und seine Mutter, seine Diener, Obersten und Kämmerer. Da nahm ihn der König von Babel fest, im achten Jahre seiner Regierung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Und er führte von dort alle Schätze des Herrn weg, ebenso die Schätze des Königshauses. Er zerbrach auch alle goldenen Gefäße, die Israels König Salomo im Tempel des Herrn gemacht hatte, wie der Herr gedroht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Ganz Jerusalem, alle Obersten und wehrfähigen Männer, 10.000, führte er gefangen weg, dazu alle Schmiede und Schlosser. Nichts blieb zurück als nur die geringen Leute des eingesessenen Volksteils.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Er führte Jojachin nach Babel. Auch die Königinmutter sowie des Königs Weiber, seine Kämmerer und die Vornehmen des Landes führte er als Gefangene von Jerusalem nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Dazu alle wehrfähigen Männer, 7.000, und die Schmiede und Schlosser, 1.000, lauter kriegstüchtige Leute, brachte der Babelkönig als Gefangene nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Der König von Babel machte Mattanja, seinen (des Jojachin) Oheim, an seiner Statt zum König und änderte seinen Namen in Sedekias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sedekias war einundzwanzig Jahre alt, als er König ward, und regierte elf Jahre zu Jerusalem. Seine Mutter hieß Chamutal und war des Jeremias Tochter aus Libna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Er tat, was dem Herrn mißfiel, ganz wie Jojakim getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Denn nur wegen des Zornes des Herrn war solches mit Jerusalem und Juda geschehen, bis er sie von seinem Antlitz verbannte. Sedekias aber wurde vom Babelkönig abtrünnig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Im neunten Jahre seiner Regierung am zehnten Tage des zehnten Monats zog Babels König Nebukadrezar mit seiner ganzen Heeresmacht gegen Jerusalem und belagerte es. Und sie bauten dagegen ringsum einen Wall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'So wurde die Stadt bis zum elften Jahre des Königs Sedekias belagert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Am neunten Tage des Monats nahm in der Stadt die Hungersnot überhand, und der eingesessene Volksteil hatte nichts mehr zu essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Da wurde die Stadt erstürmt. Alle Kriegsleute waren in der Nacht auf dem Weg durch das Tor zwischen den beiden Mauern am Königsgarten. Die Chaldäer aber standen noch rings um die Stadt. So zogen jene gegen die Steppe hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Da jagten die Chaldäertruppen dem König nach. Und sie erreichten ihn in Jerichos Steppen. Sein ganzes Heer aber hatte ihn verlassen und wurde zerstreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Sie ergriffen nun den König und führten ihn nach Ribla zum Babelkönig. Dieser sprach ihm das Urteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Da schlachteten sie des Sedekias Söhne vor seinen Augen ab. Den Sedekias selbst aber ließ er blenden und in Ketten legen. So brachte man ihn nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Am siebten Tage des fünften Monats, das ist im neunzehnten Regierungsjahre des Babelkönigs Nebukadrezar, kam Nebuzaradan, der Oberste der Leibwächter und Diener des Königs, nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Er verbrannte das Haus des Herrn, das Haus des Königs und alle anderen Häuser Jerusalems. Jedes bedeutendere Haus verbrannte er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Die Chaldäertruppen insgesamt, die beim Obersten der Leibwächter waren, rissen die Mauern um Jerusalem ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Den Rest des Volkes, die in der Stadt Zurückgebliebenen und die Überläufer, die zum Babelkönig übergelaufen waren, und den Rest des Pöbels führte Nebuzaradan, der Oberste der Leibwächter, fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Von den geringen Leuten des Landes ließ der Oberste der Leibwächter etliche für Weinberge und für Äcker zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Die ehernen Säulen am Hause des Herrn, die Gestühle und das eherne Meer im Hause des Herrn zerbrachen die Chaldäer und führten das Erz davon nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Auch die Töpfe, Schaufeln, Messer, Schalen und alle ehernen Gefäße, mit denen man Dienst getan, nahmen sie mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Auch die Pfannen und Sprengschalen, die einen golden, die anderen silbern, nahm der Oberste der Leibwächter mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Von den zwei Säulen, von dem einen Meer und den Gestühlen, die Salomo für das Haus des Herrn gemacht, von all diesen Geräten war das Erz nicht zu wägen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Achtzehn Ellen war die eine Säule hoch. Oben auf ihr ein eherner Knauf. Die Höhe des Knaufes war drei Ellen. Rings um den Knauf war ein Gittergeflecht mit Granatäpfeln, alles aus Erz. Solche hatte auch die zweite Säule am Gittergeflecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Der Oberste der Leibwächter nun nahm den Oberpriester Seraja fest, den zweiten Priester Sephanja und die drei Schwellenhüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Aus der Stadt nahm er einen Kämmerer, den Befehlshaber über die Kriegsleute, fünf Männer von denen, die des Königs Antlitz sehen durften und sich in der Stadt befanden, des Feldhauptmanns Schreiber, der die einheimische Bevölkerung aufbot, und von der einheimischen Bevölkerung sechzig Mann, die sich in der Stadt fanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Und Nebuzaradan, der Oberste der Leibwächter, nahm sie und führte sie nach Ribla zum Babelkönig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Der König von Babel ließ sie zu Ribla in der Landschaft Hamat hinrichten. So wanderte Juda von seinem Boden in die Verbannung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Über das Volk, das im Lande zurückblieb und das Nebukadrezar, Babels König, zurückließ, setzte er den Gedalja, den Sohn Achikams und Enkel Saphans.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Als alle Heeresobersten samt den Leuten hörten, daß der König von Babel den Gedalja eingesetzt habe, kamen sie nach der Mispa zu Gedalja. Auch Ismael, Netanjas Sohn, ferner Kareachs Sohn Jochana, Tanchumets Sohn Seraja, der Netophatiter und des Maakatiters Sohn Jaazanja samt ihren Leuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Da schwur Gedalja ihnen und ihren Leuten und sprach zu ihnen: \"Fürchtet euch nicht vor den chaldäischen Dienern! Bleibt im Lande und seid dem Babelkönig untertan! Dann geht es euch gut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Aber im siebten Monate kam Ismael, der Sohn Netanjas und Enkel Elisamas aus königlichem Geschlecht, mit zehn Männern. Sie schlugen Gedalja, daß er starb, ebenso die Juden und Chaldäer, die bei ihm zu Mispa waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Da brach alles Volk, klein und groß, auf, samt den Heeresobersten, und sie kamen nach Ägypten. Denn sie fürchteten sich vor den Chaldäern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Im siebenunddreißigsten Jahre der Wegführung des Judakönigs Jojachin, am siebenundzwanzigsten Tage des zwölften Monats, entließ der König von Babel, Evilmerodach, in dem Jahre, da er König ward, die Person des Judakönigs Jojachin aus dem Kerker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Er redete gütig mit ihm und setzte seinen Stuhl über die Stühle der anderen Könige, die bei ihm zu Babel waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Er wechselte seine Gefängniskleider und speiste beständig vor ihm alle Tage seines Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Sein ständiger Bedarf wurde ihm vom König gegeben, jeden Tag, was er benötigte, alle Tage seines Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jered.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Chanok, Metuselach, Lemek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noë, Sem, Cham, Japhet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Japhets Söhne sind Gomer, Magog, Madai, Javan, Tubal, Mosek und Tiras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Gomers Söhne sind Askenaz, Riphat und Togarma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Javans Söhne sind Elisa, Tarsis, Kittim und Rodanim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Chams Söhne sind Kusch und Misraim, Put und Kanaan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Des Kusch Söhne sind Seba, Chavila, Sabta, Regma und Sabteka, Regmas Söhne sind Seba und Dedan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Und Kusch zeugte Nimrod. Dieser fing an, auf Erden ein Held zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Und Misraim zeugte die Luditer, die Anamiter, die Lehabiter, die Naphtuchiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'die Patrusiter und die Kasluchiter sowie die Kaphtoriter, von denen die Philister auszogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Und Kanaan zeugte Sidon als seinen Erstgeborenen und Chet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'sodann die Jebusiter, Amoriter, Girgasiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Chiviter, Arkiter, Siniter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvaditer, Semariter und Chamatiter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sems Söhne sind Elam, Assur, Arphaksad, Lud, Aram, Us, Chul, Geter und Mesek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Und Arphaksad zeugte den Selach und Selach den Eber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Zwei Söhne wurden Eber geboren. Des einen Name war Peleg. Denn in seinen Tagen ward die Erde zerteilt. Sein Bruder hieß Joktan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Und Joktan zeugte Almodad, Seleph, Chazarmavet, Jerach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uzal, Dikla,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Seba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Chavila und Jobab. All diese sind Joktans Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphaksad, Selach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Rëu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nachor, Terach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, das ist Abraham.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Abrahams Söhne waren Isaak und Ismael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Dies sind ihre Geschlechtsfolgen: Ismaëls Erstgeborener ist Nebajot. Dann folgen Kedar, Adbeel, Mibsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Massa, Chadad, Tema,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphis und Kedma. Dies sind die Söhne Ismaëls.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Keturas, des Nebenweibes Abrahams, Söhne sind Zimran, Joksan, Medan, Midian, Isbak und Suach; diese hat sie geboren. Joksans Söhne sind Seba und Dedan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Midians Söhne sind Epha, Epher und Chanok, Abida und Eldaa. Alle diese sind Söhne der Ketura.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Und Abraham zeugte den Isaak. Isaaks Söhne sind Esau und Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Esaus Söhne sind Eliphaz, Rëuel, Jeus, Jalam und Korach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Des Eliphaz Söhne sind Teman, Omar, Sephi, Gatam, Kenaz, Timna und Amalek.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Rëuels Söhne sind Nachat, Zerach, Samma und Mizza.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Und Seïrs Söhne sind Lotan, Sobal, Sibon, Ana, Dison, Eser und Disan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotans Söhne sind Chori und Homam. Timna ist Lotans Schwester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sobals Söhne sind Aljan, Manachat, Ebal, Sephi und Onam. Sibons Söhne sind Ajja und Ana.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anas Söhne sind: Dison. Und Disons Söhne sind Chamram, Esban, Itran und Keran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Esers Söhne sind Bilhan, Zaavan und Jakan. Disans Söhne sind Us und Aran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Dies sind die Könige, die im Lande Edom herrschten, bevor ein König der Israeliten war:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Bela, Beors Sohn, und seine Stadt hieß Dinhaba. Als Bela starb, ward des Serach Sohn, Jobab, aus Bosra an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Als Jobab starb, ward Chusam aus dem Lande der Temaniter an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Als Chusam starb, ward an seiner Statt König Bedads Sohn, Hadad, der Midian auf Moabs Gefilde schlug. Seine Stadt hieß Avit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Als Hadad starb, ward Samla aus Masreha an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Als Samla starb, ward Saul aus Rechobot am Strom an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Als Saul starb, ward Akbors Sohn, Baalchanan, an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Als Baalchanan starb, ward Hadad an seiner Statt König. Seine Stadt hieß Pai, und sein Weib, Matreds Tochter und Mezahabs Enkelin, hieß Mehetabel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Als Hadad starb, gab es nur noch Häuptlinge in Edom: die Häuptlinge Timna, Alja, Jetet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Oholibama, Ela, Pinon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Kenaz, Teman, Mibsar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Magdiel und Iram. Dies sind Edoms Häuptlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Dies sind Israels Söhne: Ruben, Simeon, Levi und Juda, Issakar und Zabulon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph und Benjamin, Naphtali, Gad und Asser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Judas Söhne sind: Er, Onan und Sela, drei, die ihm von Suas Tochter, der Kanaaniterin, geboren sind. Judas Erstgeborener machte sich dem Herrn mißfällig, und dieser ließ ihn sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Seine Schwiegertochter Tamar aber gebar ihm Peres und Zerach. Aller Söhne Judas sind es fünf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Des Peres Söhne sind Chesron und Chamul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Des Zerach Söhne sind Zimri, Etan, Heman, Kalkol und Dara, zusammen fünf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Des Karmi Söhne sind: Akar, der Israel ins Unglück stürzte, da er sich am Geweihten pflichtvergessen vergriff.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Etans Söhne sind: Azarja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Chesrons Söhne, die ihm geboren worden, sind Jerachmeel, Ram und Kelubai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram zeugte Aminadab und Aminadab den Nachson, den Judäerfürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nachson zeugte Salma und Salma den Boaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boaz zeugte Obed und Obed den Isai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Und Isai zeugte als seinen Erstgeborenen Eliab, als zweiten Abinadab, als dritten Sima,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'als vierten Natanael, als fünften Raddai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'als sechsten Osem und als siebten David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Ihre Schwestern sind Seruja und Abigail. Der Seruja Söhne sind Absai, Joab und Asael, drei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail gebar Amasa. Des Amasa Vater ist der Ismaeliter Jeter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Chesrons Sohn Kaleb hat Azuba geheiratet. Dies sind ihre Söhne: Jeser, Sobab und Ardon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Als Azuba starb, nahm sich Kaleb die Ephrat. Sie gebar ihm den Chur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Chur aber zeugte Uri und Uri den Besalel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Hernach ist Chesron zur Tochter Makirs, des Vaters von Gilead, gegangen und hat sie geheiratet, als er sechzig Jahre alt war, und sie gebar ihm den Segub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub aber zeugte Jair. Dieser besaß dreiundzwanzig Städte im Lande Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Aber die Gesuriter und die Aramäer nahmen ihnen Jairs Zeltdörfer weg, Kenat mit seinen Tochterstädten, sechzig Städte. Alle diese waren die Söhne des Gileadvaters Makir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Nach Chesrons Tod ging Kaleb nach Ephrat. Chesrons Weib aber war Abia, und sie gebar ihm Aschur, Tekoas Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jerachmeels, des Erstgeborenen des Chesron, Söhne waren der Erstgeborene Ram, dann Buna, Oren, Osem und Achia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerachmeel hatte noch ein anderes Weib mit Namen Atara. Sie war Onams Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Rams, des Erstgeborenen von Jerachmeel, Söhne sind Maan, Jamin und Eker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Onams Söhne sind Sammai und Jada. Sammais Söhne sind Nadab und Abisur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Abisurs Weib hieß Abichail. Sie gebar ihm Achban und Molid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadabs Söhne sind Seled und Appaim. Seled starb kinderlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Appaims Söhne sind Isi, Isis Söhne sind: Sesan, Sesans Söhne sind Achlai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Jadas, Sammais Bruders, Söhne sind Jeter und Jonatan. Jeter aber starb kinderlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Jonatans Söhne sind Pelet und Zaza. Dies sind Jerachmeels Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesan hatte keine Söhne gehabt, sondern nur Töchter. Dagegen besaß Sesan einen ägyptischen Sklaven namens Jarcha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Seinem Sklaven Jarcha aber gab Sesan seine Tochter zum Weibe, und sie gebar ihm den Attai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai zeugte Natan und Natan den Zabad.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad zeugte Ephlal und Ephlal den Obed.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed zeugte Jehu und Jehu den Azarja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarja hat Cheles gezeugt und Cheles den Elasa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa zeugte Sismai und Sismai den Sallum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum zeugte Jekamja und Jekamja den Elisama.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Kalebs, Jerachmeels Bruders, Söhne sind sein Erstgeborener Mesa, das ist Ziphs Vater, und die Söhne Maresas, des Vaters von Chebron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Chebrons Söhne sind Korach, Tappuach, Rekem und Sema.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sema zeugte Jorkams Vater Racham, und Rekem zeugte Sammai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Sammais Sohn ist Maon, und Maon ist der Vater von Bet Sur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Kalebs Nebenweib Epha gebar Charan, Mosa und Gazez. Charan zeugte Gazez.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Jahdais Söhne sind Regem, Jotam, Gesan, Pelet, Epha und Saaph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Kalebs Nebenweib Maaka gebar Seber und Tirchana.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Sie gebar auch Saaph, den Vater von Madmanna, Seva, den Vater von Makbenna, und den Vater von Giba. Kalebs Tochter war Aksa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Dies sind Kalebs Söhne: Churs, des Erstgeborenen des Ephrat, Söhne sind Sobal, der Vater von Kirjat Jearim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, der Vater von Bethlehem, und Chareph, der Vater von Bet Gader.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Sobal, Kirjat Jearims Vater, hatte zu Söhnen Haroeh, die Hälfte der Menuchot');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'und die Sippen Kirjat Jearims, die Itriter, Putiter, Sumatiter und Misraiter. Von diesen stammen die Saratiter und die Estauliter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salmas Söhne sind Bethlehem und die Netophatiter, Aterot, Bet Joab und die Hälfte der Manachtiter und der Sariter');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'und die Sippen der Sopherim, die in Jabes wohnen, die Tiratiter, Simatiter und Sukatiter. Dies sind die Kiniter, die von Chamot, Bet Rekabs Vater, stammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Dies sind Davids Söhne, die ihm zu Hebron geboren sind: der Erstgeborene Amnon von der Achinoam aus Jezreel; ein zweiter Daniel, von der Abigail aus Karmel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'der dritte Absalom, von des Königs von Gesur, Talmai, Tochter Maaka, der vierte Adonia, Chaggits Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'der fünfte Sephatja von der Abital, der sechste Itram von seinem Weib Egla.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Sechs sind ihm zu Hebron geboren. Er regierte hier sieben Jahre sechs Monate, und in Jerusalem regierte er dreiunddreißig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Folgende sind ihm zu Jerusalem geboren: Sima, Sobab, Natan und Salomo, vier von Ammiels Tochter Batsua,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'ferner Ibchar, Elisua, Eliphelet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogach, Nepheg, Japhia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada und Eliphelet, neun,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'alle Davids Söhne außer den Söhnen seiner Nebenweiber. Ihre Schwester ist Tamar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomos Sohn ist Rechabeam, dessen Sohn Abia, dessen Sohn Asa, dessen Sohn Josaphat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'dessen Sohn Joram, dessen Sohn Achazja, dessen Sohn Joas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'dessen Sohn Amasja, dessen Sohn Azarja, dessen Sohn Jotam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'dessen Sohn Achaz, dessen Sohn Ezechias, dessen Sohn Manasse,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'dessen Sohn Amon, dessen Sohn Josias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Des Josias Söhne sind der Erstgeborene Jochanan, der zweite Jojakim, der dritte Sedekia, der vierte Sallum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Jojakims Söhne sind sein Sohn Jechonja und sein Sohn Sedekia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Die Söhne Jechonjas, des Gefangenen, sind sein Sohn Sealtiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedaja, Senassar, Jekamja, Hosanna und Nedabja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedajas Söhne sind Zerubbabel und Simei - Zerubbabels Sohn ist Mesullam - sowie Chananja. Ihre Schwester ist Selomit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Ferner Chasubal, Ohel, Berekja, Chasadja, Jusab, Chesed, fünf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Chananjas Söhne sind Pelatja und Jesaja und Rephaias, Arnons, Obadjas und Sekanjas Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Sekanjas Söhne sind: Semaja und Semajas Söhne sind Chattus, Igal, Bariach, Nearja und Saphat, sechs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearjas Söhne sind Eljoënai, Chizkia und Azrikam, drei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoënais Söhne sind Hodaiva, Eljasib, Pelaja, Akkub, Jochanan, Dejala und Anani, sieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Judas Söhne sind Peres, Chesron, Karmi, Chur und Sobal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Sobals Sohn Reaja zeugte Jachat und Jachat den Achumai und den Lahad. Dies sind die Geschlechter der Soratiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Diese haben Etam zum Vater: Jezreel, Sima und Idbas. Ihre Schwester heißt Haslelponi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Ferner Penuel, Gedors Vater, und Husas Vater Ezer. Dies sind die Söhne Churs, des Erstgeborenen Ephrats, des Vaters von Bethlehem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Tekoas Vater Aschur hatte zwei Weiber, Chela und Naara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara gebar ihm Achuzam, Chepher, Temni und die Achastariter. Dies sind Naaras Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Der Chela Söhne sind Seret, Ischar und Etnan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Kos zeugte Anub und Sobeba sowie die Sippen des Acharchel, des Harumsohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabes aber war vornehmer als seine Brüder. Seine Mutter hatte ihn Jabes genannt; sie sprach: \"Ich habe ihn ja mit Schmerzen geboren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Und Jabes rief zu Israels Gott: \"Daß Du mich segnest und mein Gebiet vergrößerst und daß Deine Hand mit mir sei und Du Unheil ablenkest, auf daß ich keinen Verdruß habe!\" Und Gott erfüllte das, worum er bat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Suchas Bruder Kelub zeugte Mechir. Das ist der Vater von Eston.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eston zeugte Bet Rapha, Paseach und Techinna, den Vater der Stadt Nachas. Dies sind die Männer von Reka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Des Kenat Söhne sind Otniel und Seraja. Otniels Söhne sind: Chatat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotai zeugte Ophra, und Seraja den Joabs den Vater des Tales der Zimmerer. Denn sie waren Zimmerleute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Des Jephunnesohnes Kaleb Söhne sind Ir, Ela und Naam, und der Sohn des Ela ist Kenaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Des Jehallel Söhne sind Ziph, Zipha, Tirja und Asarel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Ezras Sohn ist Jeter; Mered aber heiratete Jalon. Und sie gebar Mirjam, Sammai und Isbach, des Estemoa Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Sein jüdisches Weib aber hat Jered, den Vater Gedors, geboren, ferner Cheber, Sokos Vater, und Jekutiel, den Vater von Zanoach. Dies sind die Söhne der wirklichen Pharaotochter, die Mered geheiratet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Die Söhne der Schwester Rachams und der Frau des Hodia sind der Garmiter, Kegilas Vater, und der Maakatiter Estemoa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Simons Söhne sind Ammon, Rinna, Ben Chanan und Tilon. Iseis Söhne sind: Zochet und des Zochet Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Des Judasohnes Sela Söhne sind Er, der Vater von Leka, und Lada, der Vater von Maresa, sowie die Sippen des Hauses der Baumwollarbeiter zu Bet Asbe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'ferner Jokim und die Männer von Kozeba, sowie Joas und Saraph, die Moab erobert haben, und Jasubi Lechem. Die Geschichten aber sind alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Dies sind die Töpfer und Bewohner von Netaim und Gedera. Sie haben dort beim König in seinem Dienste gewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeons Söhne sind Nemuel und Jamin, Jarib, Zerach und Saul,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'dessen Sohn war Sallum, dessen Sohn Mibsam und dessen Sohn Misma.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Mismas Söhne sind: sein Sohn Chammuel, dessen Sohn Zakkur und dessen Sohn Simei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei aber besaß sechzehn Söhne und sechs Töchter. Seine Brüder aber hatten nicht viele Söhne. Und ihre ganze Sippe mehrte sich nicht so, daß sie den Judäern gleichgekommen wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Sie wohnten in Beerseba, Molada, Chasar Sual,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'in Bilha, Esem, Tolad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'in Betuel, Chorma, Siklag,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'in Bet Markabot, Chasar Susim, in Bet Biri und Saarim. Dies waren ihre Städte, bis David König ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Ihre Dörfer waren Etam, Ajin, Rimmon, Token und Asan, fünf Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Dazu all ihre Dörfer rings um diese Städte bis nach Baal hin. Dies waren ihre Wohnsitze. Sie hatten auch ihre eigene Sippenliste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Ferner: Mesobab, Jamlek und des Amasja Sohn Josab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jehu, des Josibja Sohn und Enkel des Asielsohnes Seraja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'und Eljoënai, Jaakoba, Jesochaja, Asaja, Adiel, Jesimiel, Benaja');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'und Ziza, Siphis Sohn, Allons Enkel und Urenkel des Jedaja, des Sohnes des Simri und Enkels des Semaja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Diese mit Namen Aufgeführten sind in ihren Sippen Fürsten, und das Haus ihrer Väter ist weit verbreitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Sie zogen vom Zugange nach Gedor, bis östlich vom Tal, um für ihre Herden Weiden zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Sie fanden auch eine fette und gute Weide. Das Land war geräumig, ruhig und friedlich; denn die früheren Bewohner gehörten zu Cham.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Diese namentlich Aufgeführten kamen in den Tagen des Judakönigs Ezechias und schlugen Chams Gezelte und die der Mëuniter, die dort waren, und rotteten sie aus bis auf den heutigen Tag. Dann wohnten sie dort an ihrer Stelle. Denn dort war für ihre Herden Weide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Ein Teil davon aber, von Simeons Söhnen, zog auf das Gebirge Sëir, fünfhundert Mann. An ihrer Spitze Pelatja, Nearja, Rephaja und Uziel, Iseis Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Sie schlugen Amaleks letzten Rest und wohnten dort bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Die Söhne Rubens, des Erstgeborenen Israels: - er war ja der Erstgeborene. Als er aber seines Vaters Lager entweihte, ist sein Erstgeburtsrecht den Söhnen des Israelsohnes Joseph verliehen worden. Aber die Erstgeburt ist nicht in die Sippenliste eingetragen worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Denn Juda ist unter seinen Brüdern mächtig geworden und ein Fürst, größer als jener. Das Erstgeburtsrecht gehört aber Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Rubens, des Erstgeborenen Israels, Söhne sind Chanok, Pallu, Chesron und Karmi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Joels Söhne sind sein Sohn Semaja, dessen Sohn Gog, dessen Sohn Simei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'dessen Sohn Mika, dessen Sohn Reaja, dessen Sohn Baal,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'dessen Sohn Beera, den Tilgat Pilneser, Assyriens König, in Gefangenschaft geführt hat. Er ist ein Fürst der Rubeniten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Seine Brüder, nach seinen Sippen, nach der Abstammung verzeichnet, sind das Haupt Jeiel, ferner Zakarja');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'und Bela, des Azaz Sohn, Enkel des Sema und Urenkel Joels. Er wohnte zu Aroër und bis nach Nebo und Baal Meon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Nach Osten hat er bis zum Rand der Wüste vom Euphratstrome an gewohnt. Denn ihre Herden im Lande Gilead sind zahlreich gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'In Sauls Tagen stritten sie mit den Hagritern. Diese fielen in ihre Hand, und sie wohnten in deren Zelten auf Gileads ganzer Ostseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gads Söhne haben im Lande Basan bis Saleka, ihnen gegenüber, gewohnt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'das Haupt Joel, Saphan, der zweite, und Janai und Saphat in Basan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Ihre Brüder sind nach ihren Familien Mikael, Mesullam, Seba, Josai, Jakan, Zi und Eber, sieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Dies sind die Söhne Abichails, des Churisohns und Enkels des Jaroach, des Sohns Gileads und Enkels des Mikael, des Jesisaisohns und Enkels des Jachda, des Buzsohns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Achi, Abdiels Sohn und Gunis Enkel, war ein Haupt ihrer Familien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Sie wohnten in Gilead, Basan und dessen Tochterstädten, sowie auf allen Weidetriften Sarons bis an ihre Ausgänge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Sie alle sind in des Judakönigs Jotam und des Israelskönigs Jeroboam Tagen aufgezeichnet worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Die Söhne Rubens und Gads sowie der Halbstamm Manasse, tapfere Männer, die Schild und Schwert trugen, den Bogen spannten und kampfgeübt waren, 440 und zwar leichtbewaffnete, kriegstüchtige Söldner,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'führten mit den Hagritern Krieg, ebenso mit Jetur, Naphis und Nodab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Ihnen ward gegen sie geholfen, und so wurden die Hagriter in ihre Hand gegeben, ebenso alle, die bei ihnen waren. Denn sie hatten im Kampfe zu Gott geschrieen, und er hatte sich von ihnen erbitten lassen, weil sie auf ihn vertraut hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Sie führten deren Herden weg: 50.000 Kamele, 250.000 Schafe, 2.000 Esel und 100.000 Menschenseelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Denn viele waren durchbohrt gefallen, weil der Krieg von Gott kam. Dann wohnten sie an ihrer Stelle bis zu der Verbannung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Auch die Söhne des Halbstammes Manasse haben im Lande Basan gewohnt bis Baal Hermon, Senir und bis zum Hermongebirge. Sie waren zahlreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Dies sind ihre Familienhäupter: Epher, Isei, Eliel, Azriel, Irmeja, Hodavja und Jachdiel, tapfere Krieger, berühmte Männer, Häupter in ihren Familien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Sie waren aber gegen den Gott ihrer Väter treulos und buhlten mit den Göttern der Landesvölker, die Gott vor ihnen vertilgt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'So reizte Israels Gott die Wut des Assyrerkönigs Pul, ebenso die Wut des Assyrerkönigs Tilgat Pilneser und ließ sie die Rubeniten, Gaditen und den Halbstamm Manasse wegführen und sie nach Chelach und zum Chabor bringen, nach Hara und zum Flusse Gozan bis auf diesen Tag. Levis Söhne sind Gersom, Kehat und Merari. Kehats Söhne sind Amram, Ischar, Chebron und Uzziel. Amrams Kinder sind Aaron, Moses und Mirjam. Aarons Söhne sind Nadab, Abihu, Eleazar und Itamar. Eleazar zeugte Pinechas und Pinechas den Abisu. Abisu zeugte Bukki und Bukki den Uzzi. Uzzi zeugte Zerachja und Zerachja den Merajot. Merajot zeugte Amarja und Amarja den Achitub. Achitub zeugte Sadok und Sadok den Achimaas. Achimaas zeugte Azarja und Azarja den Jochanan, Jochanan zeugte Azarja - das ist der, der im Hause, das Salomo in Jerusalem gebaut, Priesterdienste getan hat. Azarja aber zeugte Amarja und Amarja den Achitub. Achitub zeugte Sadok und Sadok den Sallum. Sallum zeugte Chilkia und Chilkia den Azarja. Azarja zeugte Seraja und Seraja den Josadak. Josadak aber ist fortgezogen, als der Herr Juda und Jerusalem durch Nebukadrezar wegführen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levis Söhne sind Gersom, Kehat und Merari.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Dies sind die Namen der Söhne Gersoms: Libni und Simi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Kehats Söhne sind Amram, Ishar, Chebron und Uzziel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Meraris Söhne sind Machli und Musi. Dies sind die Sippen der Leviten nach ihren Familien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Von Gersom stammt sein Sohn Libni, dessen Sohn Jachat, dessen Sohn Zimma,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'dessen Sohn Joach, dessen Sohn Iddo, dessen Sohn Zerach und dessen Sohn Jeatrai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Kehats Söhne sind sein Sohn Amminadab, dessen Sohn Korach, dessen Sohn Assir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'dessen Sohn Elkana, dessen Sohn Abjasaph, dessen Sohn Assir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'dessen Sohn Tachat, dessen Sohn Uriel, dessen Sohn Uzzia und dessen Sohn Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Elkanas Söhne sind Amasai und Achimot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'dessen Sohn Elkana. Elkanas Söhne sind sein Sohn Sophai, dessen Sohn Nachat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'dessen Sohn Eliab, dessen Sohn Jerocham, dessen Sohn Elkana und dessen Sohn Samuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Samuels Söhne sind der Erstgeborene Joel und der zweite Abia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Meraris Söhne sind Machli, dessen Sohn Libni, dessen Sohn Simei, dessen Sohn Uzza,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'dessen Sohn Simea, dessen Sohn Chaggia und dessen Sohn Asaja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Diese sind es, die David für den Gesang in des Herrn Haus bestellt hat, nachdem die Lade einen Ruheort gefunden hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Sie hatten den Dienst im Gesang vor der Wohnung des Bundeszeltes, bis Salomo das Haus des Herrn zu Jerusalem baute. Und sie taten ihren Dienst nach ihrer Vorschrift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Diese amteten samt ihren Söhnen: von den Söhnen der Kehatiter der Sänger Heman, Joels Sohn und Enkel Samuels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'des Sohnes Elkanas und Enkels Jerochams, des Sohnes Eliabs und Enkels Tochis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'des Sohnes Suphs und Enkels Elkanas des Sohnes Machats und Enkels Amasais,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'des Sohnes Elkanas und Enkels Joels, des Sohnes Azajas und Enkels Sephanjas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'des Sohnes Tachats und Enkels Assirs, des Sohnes Ebjasaphs und Enkels Korachs,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'des Sohnes Ishars und Enkels Kehats, des Sohnes Levis und Enkels Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Sein Bruder ist Asaph, sein erster Gehilfe. Asaph, Berekjas Sohn und Enkel Simeas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'des Sohnes Mikaels und Enkels Baasejas, des Sohnes Malkias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'des Sohnes Etnis und Enkels Zerachs, des Sohnes Adajas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'des Sohnes Etans und Enkels Zimmas, des Sohnes Simis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'des Sohnes Jochats und Enkels Gersoms, des Levisohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Meraris Söhne, ihre Brüder, waren ihre zweiten Gehilfen. Etan, Kisis Sohn und Enkel Abdis, des Sohnes Malluks,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'des Sohnes Chasabjas und Enkels Amasjas, des Sohnes Chilkias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'des Sohnes Amsis und Enkels Banis, des Sohnes Semers,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'des Sohnes Machlis und Enkels Musis, des Sohnes Meraris und Enkels Levis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ihre Brüder, die Leviten, waren für den ganzen Dienst an der Wohnung des Gotteshauses bestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Aaron aber und seine Söhne räucherten an dem Brandopferaltar und an dem Räucheraltar, ebenso bei allen Diensten am Allerheiligsten und bei der Entsühnung Israels, genau nach der Vorschrift, die der Diener Gottes, Moses, gegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Dies sind Aarons Söhne: sein Sohn Eleazar, dessen Sohn Pinechas, dessen Sohn Abisu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'dessen Sohn Bukki, dessen Sohn Uzzi, dessen Sohn Zerachja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'dessen Sohn Merajot, dessen Sohn Amarja, dessen Sohn Achitub,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'dessen Sohn Sadok und dessen Sohn Achimaas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Dies sind ihre Wohnsitze nach ihren Zeltlagern in ihrem Gebiet: Den Aaronssöhnen, der Kehatitersippe - denn auf sie fiel das Los -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'gab man im Lande Juda Hebron und seine Weidetriften ringsumher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Das Feld der Stadt aber und ihre Gehöfte hatte man Jephunnes Sohn Kaleb gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Den Aaronssöhnen aber hatte man die Zufluchtsstädte Hebron und Libna samt ihren Weidetriften übergeben, ferner Jattir und Estemoa mit den Ihrigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Cholon mit seinen Weidetriften, Debir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Asan und Betsemes je mit seinen Weidetriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Vom Stamme Benjamin: Geba mit seinen Weidetriften und Anatot mit den seinigen. Die Gesamtzahl ihrer Städte ist dreizehn samt ihren Familien,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Die übrigen Kehatsstädte erhielten von den Sippen des Stammes Ephraim, vom Stamme Dan und vom Halbstamme Manasse zehn Städte durch das Los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Gersoms Söhne erhielten nach ihren Sippen vom Stamme Issakar, vom Stamme Asser, vom Stamme Naphtali und vom Manassestamme in Basan dreizehn Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Meraris Söhne erhielten nach ihren Sippen vom Stamme Ruben, vom Stamme Gad und vom Stamme Zabulon zwölf Städte durch das Los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'So gaben die Israeliten den Leviten die Städte samt den Weidetriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Man gab durchs Los vom Stamme der Judasöhne, von dem der Simeonsöhne und dem der Söhne Benjamins jene Städte, die namentlich genannt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bei den Sippen der Kehatssöhne rühren die Städte ihres Loses vom Stamm Ephraim her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Man gab ihnen die Zufluchtsstädte Sichem mit seinen Weidetriften auf dem Gebirge Ephraim, Gezer mit den seinigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jokmeam, Bet Choron,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ajjalon und Gat Rimmon je mit ihren Weidetriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Und vom Halbstamm Manasse Aner mit seinen Weidetriften und Bileam mit den seinigen, und zwar den Sippen der übrigen Kehatssöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Gersoms Söhne erhielten von der Sippe des Halbstammes Manasse in Basan Golan mit seinen Weidetriften und Astarot mit den Ihrigen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'und vom Stamme Issakar Kedes mit seinen Weidetriften, Dobrat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ramot und Anem je mit ihren Weidetriften');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'und vom Stamme Asser Masal mit seinen Weidetriften, Abdon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Chukok und Rechob je mit den Ihrigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'und vom Stamme Naphtali in Galiläa Kedes mit seinen Weidetriften und Chammon und Kirjatim je mit den seinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Die übrigen Merarisöhne erhielten vom Stamme Zabulon Rimmon und Tabor je mit ihren Weidetriften,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'und jenseits des Jordans östlich vom Jordan, vom Stamme Ruben in der Steppe Beser mit seinen Weidetriften Ichsa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemot und Mephaat je mit den Ihrigen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'und vom Stamme Gad in Gilead Ramot, Machanaim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Chesbon und Jazer je mit ihren Weidetriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Zu den Söhnen Issakars gehören Tola und Pua, Jasub und Simron, vier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Tolas Söhne sind Uzzi, Rephaja, Jeriel, Jachmai, Ibsam und Samuel, lauter Häupter in Tolas Familien, kriegstüchtige Männer nach ihren Sippen. Ihre Zahl war zu Davids Zeit 22.600.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Uzzis Söhne sind: Izrachja. Und IzrachjasSöhne sind Mikael, Obadja, Joel, Issia, fünf Häupter insgesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Zu ihnen gehörten nach ihren Sippen, Familien und Kriegerscharen 36.000 Leute. Denn sie hatten viele Weiber und Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Und ihre Brüder, sämtliche Issakarsippen, waren kriegstüchtige Männer. Ihre Sippeliste umfaßte im ganzen 87.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjamins Söhne waren Bela, Beker und Jediael, drei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Belas Söhne sind Esbon, Uzzi, Uzziel, Jerimot und Iri, fünf, lauter Familienoberhäupter, kriegstüchtige Männer. Ihre Sippenliste umfaßte 22.034 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bekers Söhne sind Zemira, Joas, Eliezer, Eljoënai, Omri, Jerimot, Abia, Anatot und Alemet. Diese alle sind Söhne Bekers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Ihre Sippenliste nach ihren Sippen, ihren Familienhäuptern und kriegstüchtigen Männern belief sich auf 20.200.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaels Söhne sind: Bilhan. Und Bilhans Söhne sind Jëus, Benjamin, Ehud, Kenaana, Zetan, Tarsis und Achisachar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Dies alle sind Jediaels Söhne, Familienhäupter, kriegstüchtige Leute, 17.200 zum Kampf Gerüstete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Suppim und Chuppim sind Irs Söhne, Chusim sind Söhne des Acher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naphtalis Söhne sind Jachaziel, Guni, Jezer und Sallum, Bilhas Nachkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manasses Söhne sind: Asriel, den sein aramäisches Nebenweib gebar. Sie hat auch Gileads Vater, Makir, geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Makir aber hatte für Chuppim und Suppim ein Weib genommen. Seine Schwester hieß Maaka. Der zweite aber hieß Selophchad. Selophchad aber hatte nur Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Makirs Weib aber gebar einen Sohn und nannte ihn Peres. Sein Bruder aber hieß Seres und dessen Söhne Ulam und Rekeni.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Ulams Söhne sind: Bedan. - Dies sind die Söhne Gileads, des Sohnes Makirs, des Manassesohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Seine Schwester, die Königin, gebar Ishod, Abiezer und Machla.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Semidas Söhne sind Achjan, Sekem, Likchi und Aniam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Ephraims Söhne sind Sutelach; dessen Sohn war Bered, dessen Sohn Tachat, dessen Sohn Elada, dessen Sohn Tachat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'dessen Sohn Zabad, dessen Sohn Sutelach sowie Ezer und Elad. - Die Männer von Gad aber haben sie, die im Lande geboren waren, getötet, weil sie zum Raub ihres Viehes hinabgezogen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Da trauerte ihr Vater Ephraim viele Tage. Es kamen auch seine Brüder, ihn zu trösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Dann wohnte er seinem Weibe bei. Sie empfing und gebar einen Sohn. Er nannte ihn Beria, weil es geschehen war, als Unglück in seinem Hause war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Seine Tochter aber war Seera. Sie baute das untere und obere Bet Horon, ebenso Uzzen Seera.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Sein Sohn war Rephach, ebenso Reseph; dessen Sohn war Telach, dessen Sohn Tachan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'dessen Sohn Ladan, dessen Sohn Ammihud, dessen Sohn Elisama,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'dessen Sohn Nun und dessen Sohn Josue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ihr Besitz und ihre Wohnsitze sind Betel und dessen Tochterorte, nach Osten Naaran und nach Westen Gezer und Sichem je mit ihren Tochterorten bis gegen Gaza mit den zugehörigen Ortschaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Im Besitze der Manassesöhne sind Betsean mit seinen Tochterorten, Taanak, Megiddo und Dor mit je ihren Tochterorten. Darin wohnten die Söhne Josephs, des Sohnes Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Assers Kinder sind Imna, Isva, Isvi und Beria mit ihrer Schwester Serach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berias Söhne sind Cheber und Malkiel, das ist der Vater von Bir Zait.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Cheber zeugte Iphlat, Somer und Chotam samt ihrer Schwester Sua.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Japhlets Söhne sind Pasak, Bimehal und Asvat. Dies sind die Söhne Japhlets.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Semers Söhne sind Achi, Rohga, Chubba und Aram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Seines Bruders Helem Söhne sind Sophach, Imna, Seles und Amal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sophachs Söhne sind Suach, Charnepher, Sual, Beri, Imra,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hod, Samma, Silsa, Itran und Beera.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jeters Söhne sind Jephunne, Pispa und Ara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ullas Söhne sind Arach, Channiel und Risja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Alle diese sind Assers Söhne, auserlesene kriegstüchtige Männer, Häupter der Fürsten. Man verzeichnete sie in den Listen für den Kriegsdienst, und ihre Zahl war 26.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin zeugte als seinen Erstgeborenen Bela, als zweiten Asbel, als dritten Achrach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'als vierten Nocha und als fünften Rapha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Bela hatte zu Söhnen Addar, Gera, Abihud,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisu, Naaman, Achoch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephuphan und Churam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Dies sind Achuds Söhne. Diese sind die Familienhäupter der Einwohner Gebas. Man führte sie gefangen nach Manachat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naaman, Achia und Gera hat er fortgeführt, nachdem jener Uzza und Achichud gezeugt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Sacharaim zeugte in Moabs Gefilde, nachdem er seine Weiber Chusim und Baara entlassen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Er zeugte mit seinem Weibe Chodes den Jobab, Sibja, Mesa, Malkam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jëus, Sokja und Mirma. Dies sind seine Söhne, Familienhäupter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Mit Chusim hatte er Abitub und Elpaal gezeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaals Söhne sind Eber, Misam und Semer. Dieser baute Ono, ebenso Lod mit seinen Tochterorten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Beria und Sema sind die Familienhäupter der Einwohner Ajjalons. Sie haben die Bewohner von Gat vertrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Berias Söhne sind Achjo, Sasak, Jeremot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadja, Arad, Ader,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mikael, Ispa und Jocha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Elpaals Söhne sind Zebadja, Mesullam, Chizki, Cheber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismere, Izlia und Jobab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Simeis Söhne sind Jakim, Zikri, Zabdi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Silletai, Eliel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja und Simrat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Sasaks Söhne sind Ispan, Eber, Eliel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zikri, Chanan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Chananja, Elam, Antotia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'lphdaja und Penuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Jerochams Söhne sind Samserai, Secharja, Atalja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresja, Elia und Zikri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Dies sind in ihren Sippen die Familienhäupter. Als Häupter haben sie zu Jerusalem gewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Zu Gibeon wohnten der Vater Gibeons und sein Weib namens Maaka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Sein erstgeborener Sohn ist Abdon, dann Sur, Kis, Baal, Nadab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Achjo und Zeker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklot hat Sima gezeugt. Auch sie wohnten in Jerusalem bei ihren Brüdern, diesen gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner zeugte Kis und Kis den Saul und Saul den Jonatan, Malkisua, Abinadab und Esbaal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonatans Sohn ist Meribbaal, und Meribbaal zeugte Mika.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Mikas Söhne sind Piton, Melek, Tare und Achaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Achaz zeugte Joadda und Joadda den Alemet, Azmavet und Zimri und Zimri den Mosa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Mosa zeugte den Bina. Dessen Sohn ist Rapha, dessen Sohn Elasa und dessen Sohn Asel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Asel hatte sechs Söhne. Dies sind ihre Namen: Azrikam, sein Erstgeborener, Ismael und Searja, Obadja und Chanan. Alle diese waren Söhne Asels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Seines Bruders Esek Söhne sind sein Erstgeborener Ulam, der zweite Jëus und der dritte Eliphelet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Ulams Söhne waren kriegstüchtige Männer, die den Bogen spannen konnten. Sie hatten auch zahlreiche Söhne und Enkel, 150. Alle diese gehören zu den Söhnen Benjamins.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Alle Israeliten sind in den Sippenlisten eingetragen worden. Und sie sind im Buch der Könige Israels aufgezeichnet. Die Judäer sind wegen ihrer Frevel nach Babel fortgeführt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Die früheren Einwohner aber, die wieder auf ihrem Eigentum in ihren Städten lebten, waren Israeliten, die Priester, die Leviten und die Tempeldiener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'In Jerusalem haben von den Söhnen Judas Benjamins, Ephraims und Manasses gewohnt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utai, Ammihuds Sohn und Enkel Omris, des Sohnes Imris und Enkels Banis, von des Judasohnes Peres Nachkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Von den Siloniten der Erstgeborene Asaja samt seinen Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Von Zerachs Söhnen Jeuel samt ihren Brüdern, 690.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Von Benjamins Söhnen Sallu, des Mesullam Sohn und Enkel Hodavjas, des Sohnes Hassenas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'ferner Jerochams Sohn Ibneja und Ela, Uzzis Sohn und Enkel Mikris, und Mesullam, Sephatjas Sohn und Enkel Reuels, des Ibniasohnes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'samt ihren Brüdern nach ihren Geschlechtern, 956. Alle diese Männer sind in ihren Familien Familienhäupter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Von den Priestern sind es Jedaja, Jojarib, Jakin');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'und Azarja, der Sohn des Chilkia und Enkel Mesullams, des Sohnes Sadoks und Enkels des Merajot, des Achitubsohnes, des Fürsten am Gotteshaus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'und Adaja, Jerochams Sohn und Enkel des Paschur, des Malkiasohnes, und Masai, Adiels Sohn und Enkel des Jachzera, des Sohnes Mesullams und Enkels Mesillemits, des Immersohnes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'und ihre Brüder, Häupter in ihren Familien, 1.760, Vorgesetzte der Schar, die den Dienst im Gotteshaus tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Von den Leviten sind es Semaja, des Chassub Sohn und Enkel Azrikams, des Sohnes Chasabjas, von den Merarisöhnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'und Bakbakkar, Cheres, Galal, Makamja, des Mika Sohn und Enkel des Asaphsohnes Zikri,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadja, des Semaja Sohn und Enkel des Jedutunsohnes Galal, und Berekja, des Asa Sohn und Enkel des Elkana, der in den Netophatiterdörfern wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Ferner die Torhüter Sallum, Akkub, Talmon und Achiman, sowie ihre Brüder. Sallum ist der Oberste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Bis heute sind am Königstore gegen Osten die Torhüter in den Lagern der Levisöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sallum, Kores Sohn und Enkel des Korachsohnes Ebjasaph, und seine Brüder aus seiner Familie, die Korachiter, liegen dem Dienste ob; sie hüten im Zelt die Schwellen. Schon ihre Väter sind im Lager des Herrn die Hüter des Eingangs gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Vor Zeiten ist Fürst über sie Eleazars Sohn Pinechas gewesen. Der Herr sei mit ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zakarja, Meselemjas Sohn, ist am Bundeszelte Torhüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Sie alle, die zu Torhütern an den Schwellen auserlesen sind, zählen 212. Sie sind in ihren Dörfern aufgezeichnet. David und der Seher Samuel haben sie in ihre Amtspflicht eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Sie, wie auch ihre Söhne, stehen an den Toren im Hause des Herrn, im Zelthaus, auf Wache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Nach den vier Winden stehen die Torhüter gegen Osten, Westen, Norden, Süden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Ihre Brüder in ihren Dörfern haben jeweils für sieben Tage zu kommen, sie zu unterstützen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Denn die vier Obersten der Torhüter stehen in steter Dienstpflicht. Dies sind die Leviten. Sie beaufsichtigen auch die Zellen und Vorratskammern im Gotteshaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Sie bleiben in der Umgebung des Gotteshauses über Nacht. Denn ihnen liegt die Wache ob, und sie haben jeden Morgen aufzuschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Und ein Teil von ihnen beaufsichtigt die Dienstgeräte. Denn sie bringen diese abgezählt hinein und hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Ein anderer Teil von ihnen ist über die Güter bestellt, und zwar über die heiligsten Güter, über das Feinmehl, den Wein, das Öl, den Weihrauch und die Spezereien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Einige der Priestersöhne haben aus den Spezereien Salben zu mischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Einer der Leviten, Mattitja, des Korachiten Sallum Erstgeborener, ist mit dem Pfannenbackwerk betraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Etliche der Kehatitersöhne, ihrer Brüder, sind für die reihenweise gelegten Brote bestellt, die sie Sabbat um Sabbat bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Das sind die Sänger, levitische Familienhäupter, die nur in den Zellen dienstfrei sind. Denn sie haben sonst Tag und Nacht Dienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Dies sind levitische Familienhäupter, auch nach ihren Sippen Häupter. Diese wohnten zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Zu Gibeon wohnte Jeiel, Gibeons Vater. Sein Weib heißt Maaka.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Sein erstgeborener Sohn ist Abdon, ferner Sur, Kis, Baal, Ner, Nadab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Achjo, Zakarja und Miklot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklot hat Simam gezeugt. Auch sie wohnten zu Jerusalem bei ihren Brüdern, diesen gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner hat Kis gezeugt, Kis den Saul, Saul den Jonatan, Malkisua, Abinadab und Esbaal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Jonatans Sohn ist Meribbaal, und Meribbaal hat Mika gezeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Mikas Söhne sind Piton, Melek und Tachre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Achaz hat Jara gezeugt und Jara den Alemet, Azmawet und Zimri. Zimri hat Mosa gezeugt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'und Mosa den Bina. Sein Sohn ist Rephaja, dessen Sohn Elasa und dessen Sohn Asel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Asel hat sechs Söhne. Dies sind ihre Namen: Azrikam, Bokru, Ismael, Searja, Obadja und Chanan. Dies sind Asels Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Die Philister aber kämpften mit Israel. Da floh Israels Mannschaft vor den Philistern, und Erschlagene lagen auf dem Gebirge Gilboa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Und die Philister hefteten sich an Saul und seine Söhne. Und so erschlugen die Philister Sauls Söhne, Jonatan, Abinadab und Malkisua.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'So wurde der Kampf für Saul immer schwerer. Da trafen ihn die Bogenschützen in den Leib. So wurde er durch die Bogenschützen verwundet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Da sprach Saul zu seinem Waffenträger: \"Zücke dein Schwert und erstich mich damit, daß nicht diese Unbeschnittenen kommen und mit mir ihr Spiel treiben!\" Aber sein Waffenträger wollte nicht. Denn er scheute sich zu sehr. Da zog Saul selbst das Schwert und stürzte sich hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Wie aber sein Waffenträger sah, daß Saul tot war, stürzte auch er sich in das Schwert und starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'So starben Saul und seine drei Söhne und sein ganzes Haus; so starben sie miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Als aber Israels gesamte Mannschaft, die im Tale wohnte, sah, daß jene geflohen und daß Saul und seine Söhne tot waren, verließ sie ihre Städte und floh. Da kamen die Philister und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Am anderen Morgen kamen die Philister, um die Erschlagenen zu plündern. Da fanden sie Saul und seine Söhne auf dem Gebirge Gilboa liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Sie zogen ihn aus, nahmen sein Haupt und seine Waffen und sandten sie im Philisterlande umher, ihren Götzen und dem Volke die Siegesbotschaft zu künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Seine Waffen legten sie in dem Hause ihres Gottes nieder. Seinen Schädel aber nagelten sie im Hause Dagons an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Als ganz Jabes in Gilead das alles hörte, was die Philister an Saul getan hatten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'machten sich alle wehrfesten Männer auf und holten Sauls Leichnam und die Leichen seiner Söhne und brachten sie nach Jabes. Sie begruben ihre Gebeine unter der Terebinthe zu Jabes und fasteten sieben Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'So starb Saul wegen seines Abfalls vom Herrn, wegen des Herrnwortes, das er nicht befolgt und auch, weil er einen Totengeist befragt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'und nicht beim Herrn angefragt hatte. So ließ er ihn sterben und wandte das Königtum dem Isaisohne David zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Nun sammelte sich ganz Israel bei David zu Hebron und sprach: \"Wir sind dein Fleisch und Bein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Noch als Saul König war, bist du es gewesen, der Israel ins Feld und heimgeführt hat. Auch sprach der Herr, dein Gott, zu dir: \'Du sollst mein Volk Israel weiden und Fürst über mein Volk Israel sein!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Also kamen alle Ältesten Israels zum König nach Hebron. Und David schloß mit ihnen zu Hebron vor dem Herrn einen Bund. Dann salbten sie David zum König über Israel nach dem Worte des Herrn durch Samuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Nun zog David mit ganz Israel gegen Jerusalem, das ist Jebus. Dort waren die Jebusiter einheimisch im Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Da sprachen die Einwohner von Jebus zu David: \"Du kommst nicht hier herein.\" David aber erstürmte die Burg Sions, das ist die Davidsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Da sprach David: \"Jeder, der zuerst einen Jebusiter erschlägt, sei Hauptmann und Befehlshaber!\" Da stieg Joab, der Sohn der Zeruja, zuerst hinauf. So ward er Hauptmann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Hierauf ließ sich David in der Burg nieder. Darum nannte man sie Davidsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Er baute die Stadt ringsum, von der Bastei bis zu der Ringmauer. Und Joab stellte die übrige Stadt her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'David aber ward immer größer, und der Herr der Heerscharen war mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Dies sind der Helden Davids Häupter, die fest zu ihm hielten, als er König ward, um ihn nach des Herrn Wort zum König auch über Gesamtisrael zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Dies ist die Zahl der Davidshelden: Chaknonis Sohn Josebeam, das Haupt der Dreißig. Er ist es, der seinen Speer über dreihundert Erschlagene auf einmal schwang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Nach ihm kommt der Achotiter Eleazar, Dodos Sohn. Er gehörte zu den drei Helden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Er war mit David am Blutsteinfelsen gewesen, als sich die Philister dort zur Schlacht sammelten. Nun war dort ein Feld voll Gerste. Als aber das Volk vor den Philistern floh,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'stellten sie sich mitten auf das Feldstück, behaupteten es und schlugen die Philister, und der Herr verhalf ihnen zu einem großen Sieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Drei von den dreißig Hauptleuten stiegen nach dem Felsennest zu David, in die Höhle von Adullam hinab. Das Philisterheer aber lagerte in der Rephaimebene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Damals war David in der Feste, die Philisterbesatzung aber in Bethlehem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Nun spürte David ein Gelüste und fragte: \"Wer holt mir Trinkwasser aus dem Brunnen in Bethlehem am Tore?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Da schlugen sich die Drei durch das Philisterlager, schöpften Wasser aus dem Brunnen in Bethlehem am Tore und brachten es David. David aber wollte es nicht mehr trinken, sondern spendete es für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Er sprach: \"Bewahre mich mein Gott davor, daß ich so etwas tue! Sollte ich dieser Männer Blut samt ihrem Leben trinken? Denn mit Lebensgefahr haben sie es hergebracht.\" Und so wollte er es nicht trinken. Solches taten die drei Helden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Joabs Bruder Abisai war das Haupt der Dreißig. Er war es, der seinen Speer gegen dreihundert Unreine schwang. Bei den Dreien war er angesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Er wurde schnell von den Dreien ausgezeichnet, und so ward er bei ihnen Hauptmann. Aber an die Drei reichte er nicht heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Jojadas Sohn, war der Sohn eines tüchtigen, tatenreichen Mannes aus Kabseel, ein tapferer Held. Er selber hatte Moabs beide Kämpen erschlagen. Auch war er hinabgestiegen und hatte den Löwen mitten im Brunnen erschlagen, als Schnee fiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Er ist es auch, der den Ägypter, einen riesigen Mann von fünf Ellen, erschlagen hat. Der Ägypter hatte einen Speer gleich einem Weberbaume in der Hand. Er aber ging mit dem Stocke auf ihn los, entriß dem Ägypter die Lanze und tötete ihn mit dem eigenen Speere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Solches hatte Benaja, Jojadas Sohn, getan. Und er war bei den Dreien angesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Er hatte sich unter den Dreißig ausgezeichnet. Aber an die Drei reichte er nicht heran. David setzte ihn über seine Leibwache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Die tapferen Helden sind Joabs Bruder Asael, der Bethlehemite Elchanan, Dodos Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'der Haroditer Sammot, der Pelomiter Cheles,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'der Tekoiter Ira, des Ikkes Sohn, der Anatotiter Abiezer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'der Chusatiter Sibkai, der Achotiter Ilai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'der Netophatiter Mocharai, der Netophatiter Cheled, Baanas Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ribais Sohn Itai aus Gibea Benjamins, der Paratoniter Benaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Churai aus Nachale Gaas, der Asbatiter Abiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'der Bacharumiter Azmavet, der Saalboniter Eljachba,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'der Gizoniter Hasem, der Harariter Jonatan, des Sage Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'der Harariter Achiam, Sakars Sohn, Eliphal, Urs Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'der Mekeratiter Chepher, der Peloniter Achia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'der Karmeliter Chesro, Naarai, Ezbais Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, Natans Bruder, Mibchar, Chagris Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'der Ammoniter Selek, der Berotiter Nachrai, des Serujasohnes Joab Waffenträger,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'der Istriter Ira, der Istriter Gareb,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'der Chittiter Uria, Zobad, Achlais Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'der Rubenite Adina, Zizas Sohn, ein Häuptling der Rubeniter und Anführer der Dreißig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Chanan, Maakas Sohn, der Mitniter Josaphat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'der Astarotiter Uzzia, Sama und Jeiel, die Söhne des Aroëriters Chotam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, Simris Sohn, und sein Bruder Jocha, der Tisiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'der Machanatiter Eliel, Jeribai und Josavja, Elnaams Söhne, der Moabiter Itma,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed und der Mesobaiter Jaasiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Dies sind die, die zu David nach Siklag kamen, als er von dem Kissohne Saul verjagt war. Auch sie gehörten zu den Helden, als Helfer im Kampfe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'bogenbewaffnet, geschickt, mit der Rechten und Linken Steine und Pfeile mit dem Bogen zu schleudern. Von den Benjaminiten, Sauls Brüdern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'der Hauptmann Achiezer und Joas, des Gibeatiters Semaa Söhne, ferner Jeziel und Pelet, Azmavets Söhne, Beraka und der Anatotiter Jehu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'der Gibeoniter Ismaja, ein Held unter den Dreißig und der Dreißig Anführer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Jeremia, Jachaziel, Jochanan, der Gederatiter Jozabad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Eluzai, Jerimot, Bealja, Semarja, der Chariphiter, Sephatja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Elkana, Issia, Azarel, Joezer und Josbam, die Korachiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'und Joela und Zebadja, Jerochams Söhne aus Gedor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Auch von den Gaditen gingen tapfere Männer zu David auf die Feste in der Wüste, kampfgerüstete Krieger, die Schild und Lanze führten, wie Löwen anzusehen und schnellfüßig wie Gazellen auf den Bergen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Ezer, der Hauptmann Obadia, der zweite, Eliab, der dritte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Mismatina, der vierte, Jerema, der fünfte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Attai, der sechste, Eliel, der siebte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Isanan, der achte, Elzabad, der neunte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Jeremia, der zehnte, Makbannai, der elfte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Diese sind aus Gads Söhnen die Heerführer. Der geringste nahm es mit hundert und der größte mit tausend auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Diese waren es, die den Jordan im ersten Monat überschritten, als er durch alle seine Nebenzuflüsse voll war. Und sie durchzogen alle Täler in Ost und West.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Etliche kamen selbst von Benjamin und Juda zur Feste Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Da ging David zu ihnen hinaus und sprach sie an: \"Kommt ihr zu mir in Frieden, mir beizustehen, dann vereinige ich mich von Herzen mit euch. Kommt ihr aber, mich an meine Feinde zu verraten, obschon kein Unrecht an meinen Händen klebt, so sehe unserer Väter Gott darein und räche es!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Da hatte ein Geist den Obersten der Drei eingehüllt, Amasai. Er sprach: \"Dir, David, und deinem Volke, Isaisohn, sei Heil! Dir sei Heil und deinen Helfern! Denn dein Gott hilft dir.\" Da nahm sie David auf und machte sie zu Hauptleuten der Kriegerschar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Auch von Manasse gingen etliche zu David über, als er mit den Philistern gegen Saul in den Kampf zog. Aber diesen half er nicht. Denn die Philisterfürsten hatten ihn absichtlich fortgeschickt; sie sagten: \"Er kann mit unseren Köpfen zu seinem Herrn Saul übergehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Als er nach Siklag zog, gingen von Manasse zu ihm über: Adnach, Jozabad, Jediael, Mikael, Jozabad, Elihu und Silletai, die Häupter der Tausend Manasses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Diese halfen David bei der Kampfstellung. Denn sie waren alle tapfere Männer. Sie wurden auch Anführer im Heere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Denn Tag für Tag kamen Leute zu David, ihm zu helfen, bis das Heer groß geworden war wie ein Gottesheer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Dies ist die Zahl des Heerbannes, der zu David nach Hebron kam, um ihm Sauls Königtum nach des Herrn Befehl zu übertragen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Judas Söhne, die Schild und Lanze trugen, 6.800 zum Kriegszug Gerüstete,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'von den Simeonsöhnen 7.100 tapfere Kriegsleute,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Von den Levisöhnen 4.600');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'samt dem Aaronsfürsten Jojada, bei dem 3.700 waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'und samt Sadok, einem tapferen Jüngling, dessen Familie zweiundzwanzig Anführer stellte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Von den Söhnen Benjamins, Sauls Brüdern, 3.000. Bis dahin hatte die Mehrzahl von ihnen den Wachdienst für Sauls Haus gestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Von den Söhnen Ephraims 20.800 tapfere, in ihren Familien hochangesehene Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Vom Halbstamme Manasse 18.000, die namentlich bezeichnet waren, hinzugeben und David zum König zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Von den Söhnen Issakars, die Einsicht in die Zeitläufte hatten, so daß sie wußten, was Israel tun sollte, 200 Hauptleute, samt allen ihren Brüdern unter ihrem Befehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Von Zabulon 50.000 Kriegstüchtige, mit allerlei kriegerischen Waffen ausgestattet; bereit, sich einzuordnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Von Naphtali 1.000 Anführer; sie hatten 37.000 Mann mit Schild und Speer bei sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Von den Daniten 28.600 Kampfgerüstete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Von Asser 40.000 Kriegstüchtige, bereit, Krieg zu führen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'und von jenseits des Jordans, von den Rubeniten, den Gaditen und dem Halbstamme Manasse 120.000 mit allerlei Kriegswaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Alle diese Kriegsleute, in Reihen geordnet, kamen einmütig nach Hebron, David zum König über ganz Israel zu machen. Auch das ganze übrige Israel war ungeteilten Herzens dabei, David zum König zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Sie blieben dort bei David drei Tage, aßen und tranken. Denn ihre Brüder hatten für sie zugerichtet. Auch die ihnen nahe wohnten, bis nach Issakar, Zabulon und Naphtali hin, brachten Brot auf Eseln, Kamelen Maultieren und Rindern, Mehlspeisen, Feigen und Rosinenkuchen, Wein, Öl, Rinder und Schafe in Menge; denn Jubel herrschte in Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David beriet sich nun mit den Anführern der Tausendschaften und Hundertschaften von jedem Stamme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Und David sprach zur Gesamtgemeinde Israels: \"Ist es euch recht und wird es vom Herrn, unserem Gott, gebilligt, dann senden wir zu unseren Brüdern, die übrig sind in allen Landen Israels, und zu den Priestern und den Leviten in den Städten ihrer Weidebezirke, sie sollen sich bei uns versammeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Wir wollen unseres Gottes Lade zu uns holen. Denn in Sauls Tagen fragten wir nicht nach ihr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Da sagte die ganze Gemeinde, man solle so tun. Denn die Sache gefiel dem ganzen Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'So berief David ganz Israel von Ägyptens Schichor bis Hamat, um die Gotteslade aus Kirjat Jearim zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Und David zog mit ganz Israel zur Burg, nach Kirjat Jearim, in Juda, von dort die Lade Gottes zu holen, des Herrn, der auf Cheruben thront, und wo man seinen Namen angerufen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Sie fuhren nun die Gotteslade, vom Hause Abinadabs an, auf einem neuen Wagen. Uzza und Achjo führten den Wagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'David aber tanzte mit ganz Israel vor Gott unter dem Klange von Zithern, Harfen und Pauken, Zimbeln und Trompeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Wie sie aber an ein gepflegtes Feldstück kamen, streckte Uzza seine Hand aus, die Lade zu fassen, weil die Rinder sie ins Wanken gebracht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Da entbrannte des Herrn Zorn wider Uzza, und er schlug ihn, weil er seine Hand gegen die Lade ausgestreckt hatte. Und er starb dort vor Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Da ward David mißgestimmt, daß der Herr Uzza geschlagen hatte. Und er nannte jenen Ort \"Schlag des Uzza\" bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'David aber fürchtete sich vor Gott an jenem Tage und sprach: \"Wie kann ich die Gotteslade zu mir bringen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'So ließ David die Lade nicht zu sich in die Davidsstadt bringen, sondern beiseite in das Haus des Gatiters Obededom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'So blieb die Gotteslade drei Monate im Hause Obededoms, drei Monate in seinem Hause. Aber der Herr segnete Obededoms Haus und all seine Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Chiram, der König von Tyrus, sandte nun an David Boten mit Zedernholz, dazu Steinmetzen und Zimmerleute, ihm ein Haus zu bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Da erkannte David, daß ihn der Herr als König über Israel bestätigt hatte. Denn hochgeehrt ward sein Königtum wegen seines Volkes Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'David aber nahm noch weitere Frauen zu Jerusalem. Und David zeugte noch weitere Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Dies sind die Namen der Kinder, die ihm zu Jerusalem geboren worden sind: Sammua, Sobab, Natan und Salomo,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Ibchar, Elisua, Elpelet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogach, Nepheg, Japhia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeljada und Eliphelet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Die Philister aber hörten, David sei zum König über ganz Israel gesalbt worden. Da zogen alle Philister hinauf, David zu suchen. David aber hörte es. Da zog er ihnen entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Die Philister kamen nun und ließen sich in der Rephaimebene nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Da befragte David Gott: \"Soll ich gegen die Philister ziehen? Gibst Du sie in meine Hand?\" Da sprach der Herr zu ihm: \"Zieh hin! Ich gebe sie in deine Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Da zogen sie nach Baal Perasim hinauf. Und dort schlug sie David. Und David sprach: \"Gott ist durch mich gegen meine Feinde durchgebrochen, wie Wasser durchbricht.\" Deshalb nannte man jenen Ort Baal Perasim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Sie ließen dort ihre Götter im Stich, und David hieß sie verbrennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Die Philister kamen wieder und ließen sich in der Ebene nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Da befragte David wiederum Gott, und Gott sprach zu ihm: \"Du sollst nicht hinter ihnen hinaufziehen! Wende dich von ihnen ab und komme vom Rücken her über sie, von den Geröllhalden her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Sobald du das Geräusch von Schritten auf den Rändern der Geröllhalden hörst, dann brich los! Denn dann zieht dir Gott voran, das Philisterheer zu schlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'David tat so, wie ihn Gott geheißen. Und sie schlugen das Philisterheer von Gibeon bis gegen Gezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Und Davids Ruhm verbreitete sich in allen Landen, hatte doch der Herr Angst vor ihm auf alle Völker gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Und David machte sich in der Davidsstadt Häuser; dann bereitete er eine Stätte für die Gotteslade und schlug für sie ein Zelt auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Damals bestimmte David, daß niemand außer den Leviten die Gotteslade trage. Denn diese hatte der Herr erwählt, die Gotteslade zu tragen und ihm stets zu dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'So berief David ganz Israel nach Jerusalem, des Herrn Lade an ihren Platz zu bringen, den er ihr bereitet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Und David versammelte die Aaronssöhne und die Leviten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'von den Söhnen Kehats den Obersten Uriel und seine 120 Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'von den Merarisöhnen den Obersten Asaja und seine 220 Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'von den Gersomsöhnen den Obersten Joel und seine 130 Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'von den Elisaphansöhnen den Obersten Semaja und seine 200 Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'von den Chebronsöhnen den Obersten Eliel und seine 80 Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'von den Uzzielsöhnen den Obersten Amminadab und seine 112 Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Dann berief David die Priester Sadok und Ebjatar sowie die Leviten Uriel, Asaja, Joel, Semaja, Eliel und Amminadab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Er sprach zu ihnen: \"Ihr seid die Familienhäupter der Leviten. Heiligt euch und eure Brüder und bringt die Lade des Herrn, des Gottes Israels, an den Ort, den ich für sie bereitet habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Weil ihr das erstemal nicht zugegen gewesen seid, so hat der Herr, unser Gott, unter uns dreingeschlagen. Denn wir kümmerten uns nicht um ihn nach Gebühr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Da heiligten sich die Priester und die Leviten, um die Lade des Herrn, des Gottes Israels, hinaufzuführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Und die Levisöhne trugen die Gotteslade mit den Tragstangen auf ihren Schultern, wie Moses nach des Herrn Wort befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Hierauf befahl David den Obersten der Leviten, ihre Brüder, die Sänger, zu bestellen mit Musikinstrumenten, Harfen, Zithern und Zimbeln; sie sollten lauten Jubelschall ertönen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Da bestellten die Leviten Joels Sohn Heman und von seinen Brüdern Berekjas Sohn Asaph und von den Merarisöhnen, ihren Brüdern, den Etan, Kusajas Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'und mit ihnen ihre Brüder, die zweiten Ranges waren, Zakarja, Jaaziel, Semiramot, Jechiel, Unni, Eliab, Benaja, Maaseja, Mattitja, Eliphelehu, Miknejahu, Obededom und Jeiel, die Torhüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Und die Sänger Heman, Asaph und Etan hatten mit ehernen Zimbeln laut zu spielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zakarja aber, Aziel, Semiramot, Jechiel, Unni, Eliab, Maaseja und Benaja hatten mit Harfen die Führung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'und Mattitja, Eliphelehu, Miknejahu, Obededom, Jeiel und Azazja hatten mit Zithern Lieder zu singen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja aber war der Oberste der Leviten im Tonangeben. Er sang auch beim Tonangeben. Denn er war kunstfertig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berikja und Elkana waren die Hüter der Lade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Die Priester Sebanjahu, Josaphat, Netanel, Amasai, Zakarja, Benjahu und Eliezer bliesen vor der Gotteslade Trompeten. Hüter der Lade waren Obededom und Jechia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'David aber und die Ältesten Israels und die Obersten der Tausendschaften zogen hin, aus dem Hause Obededoms die Bundeslade des Herrn voller Freude hinaufzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Und Gott stand den Leviten bei, den Trägern der Bundeslade des Herrn. Sie opferten sieben Farren und sieben Widder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David war mit einem Byssusmantel bekleidet, ebenso alle Leviten, die die Lade trugen, desgleichen die Sänger und Kenanja, der Oberste der Sänger im Tonangeben. David trug noch ein linnenes Ephod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'So brachte ganz Israel die Bundeslade des Herrn hinauf unter Jubel und lautem Posaunenschall, mit Trompeten und Zimbeln. Sie ließen Harfen und Zithern ertönen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'So kam des Herrn Bundeslade in die Davidsstadt. Sauls Tochter Mikal aber beugte sich durch das Fenster. Da sah sie den König hüpfen und tanzen. Und sie verachtete ihn in ihrem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Sie aber brachten die Gotteslade hinein und stellten sie mitten in das Zelt, das David dafür ausgespannt hatte. Dann brachten sie vor Gott Brand- und Dankopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Als nun David mit der Darbringung der Brand und Dankopfer fertig war, segnete er das Volk im Namen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Dann verteilte er an alle Israeliten, Männer wie Weiber, je einen Brotkuchen, einen Laib und einen Traubenkuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Vor die Lade des Herrn aber bestellte er einige Leviten als Diener, daß sie den Herrn, Israels Gott, priesen, ihm dankten und ihn rühmten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph, das Oberhaupt, und Zakarja, den zweiten im Range nach ihm, sodann Jeiel, Semiramot, Jechiel, Mattitja, Eliab, Benajahu, Obededom und Jeiel mit Harfen und Zithern. Asaph aber sollte die Zimbeln ertönen lassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'ebenso die Priester Benajahu und Zachaziel beständig die Trompeten vor der Bundeslade Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Damals übertrug David zuerst Asaph und seinen Brüdern den Lobpreis des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '\"Dem Herrn sagt Dank! Verherrlicht seinen Namen! Kund machet seine Taten den Nationen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Lobsinget ihm! Lobt ihn! Erzählt von allen seinen Wundern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'In seinem heiligen Namen rühmet euch. Wer da den Herrn sucht, freue sich von Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Verlanget nach dem Herrn und seiner Herrlichkeit! Sein Antlitz suchet immerfort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Gedenkt der Wunder all, die er gewirkt, der Zeichen, seiner Richtersprüche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Du, seines Knechtes Israel Geschlecht, ihr Söhne Jakobs, seine Auserwählten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Der Herr ist unser Gott, und auf der ganzen Erde gelten seine Urteile.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'In Ewigkeit gedenkt er seines Bundes und seines Wortes, das er ausgesprochen, bis in das tausendste Geschlecht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'des Bundes, den er einst mit Abraham geschlossen, und seines Eides, den er Isaak zugeschworen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'den er für Jakob als ein Recht bestätigt, für Israel als ewigen Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Er sprach: \'Dir gebe ich der Kanaaniter Land als euer erblich Eigentum.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Noch klein war damals ihre Zahl; sie waren wenige und fremd darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Sie wanderten von einem Heidenvolk zum anderen, von einem Reich zu einer anderen Nation.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Er hat niemand gestattet, sie zu drücken; er warnte ihretwegen Könige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '\'Vergreift euch nicht an den von mir Gesalbten! Nicht füget meinen Sehern Schaden zu!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Dem Herrn lobsinge alle Welt! Sein Heil tut kund von Meer zu Meer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Verkündet bei den Heiden seinen Ruhm, bei allen Völkern seine Wunder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'ist doch der Herr so groß und hoch zu preisen, vor allen Göttern ehrfurchtswert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Der Völker Götter alle sind ja Götzen; des Himmels Schöpfer ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Vor ihn mit Glanz und Herrlichkeit! Mit Macht und Pracht zu seinem Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'So bringt dem Herrn, ihr Völkerscharen, herbei bringt Pracht und Macht dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'So bringt dem Herrn zu seines Namens Ehre Gaben! Betretet mit Geschenken seine Vorhöfe! Hinwerft euch vor dem Herrn mit Schmuck fürs Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Vor ihm erzittere alle Welt! Dann steht die Erde ohne Wanken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Der Himmel freue sich, die Erde jauchze; zurufen sollen sie den Heiden: \'Der Herr ist König!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Es brause auf das Meer und seine Fülle; die Flur und alles, was darin, frohlocke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Des Waldes Bäume sollen jubeln vor dem Herrn! Er kommt, die Erde jetzt zu richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'So dankt dem Herrn! Denn er ist gütig. Ja, ewig währet seine Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Und sprecht: \'Hilf uns, Du unseres Heiles Gott, und sammle und befreie von den Heiden uns, auf daß wir Deinem heiligen Namen danken und Deines Lobpreises uns rühmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Gepriesen sei der Herr, Gott Israels, von Ewigkeit zu Ewigkeit!\'\" - Und alles Volk sprach: \"Amen\" und einen Lobspruch auf den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Dann übergab er dort vor der Bundeslade des Herrn dem Asaph mit seinen Brüdern für immer den Dienst, vor der Lade zu dienen, Tag für Tag nach Vorschrift,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'ferner Obededom mit seinen achtundsechzig Brüdern und Jedituns Sohn, Obededom und Chosa als Torhüter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'ferner dem Priester Sadok und seinen Brüdern, den Priestern vor des Herrn Wohnung auf der Höhe von Gibeon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'dem Herrn auf dem Brandopferaltar regelmäßig jeden Morgen und Abend Brandopfer darzubringen, eben alles, was in der Lehre des Herrn, die er Israel gebot, geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Bei ihnen waren Heman und Jedutun und die übrigen Auserlesenen, die mit Namen genannt sind, um den Herrn zu preisen, daß seine Gnade ewig währe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Bei ihnen waren auch Trompeten und Zimbeln für die Musiker und die Spielgeräte für die Gotteslieder. Jedutuns Söhne waren für die Pforte da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Darauf ging das ganze Volk heim, jeder in ein Haus. David aber wandte sich, sein Haus zu segnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'David wohnte nun in seinem Hause. Da sprach David zum Propheten Natan: \"Ich wohne in einem Zedernhause, des Herrn Bundeslade aber unter Zelttüchern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Da sprach Natan zu David: \"Tu alles, was du im Sinne hast! Denn Gott ist mit dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Aber noch in derselben Nacht erging Gottes Wort an Natan also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '\"Geh und sage meinem Knechte David: So spricht der Herr: Nicht du sollst mir das Haus zum Wohnen bauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Ich habe nie in einem Haus gewohnt seit jener Zeit, wo ich einst Israel heraufgeführt, bis hin zu diesem Tag. Ich zog von einem Wohngezelt zum anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'So lange bin ich in ganz Israel herumgezogen. Habe ich ein Wort zu einem Richter Israels gesagt, die ich bestellt, mein Volk zu weiden: \'Warum baut ihr mir nicht ein Zedernhaus?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'So sage nunmehr meinem Knechte David: So spricht der Herr der Heeresscharen: Ich habe dich von der Weide aus der Herde hinweggeholt, auf daß du meines Volkes Israel Gebieter seiest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Ich war mit dir allüberall, wohin du gingst, und tilgte vor dir alle deine Feinde. Ich habe einen Namen dir geschaffen, gleich dem der Großen auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Ich habe eine Stätte meinem Volke Israel bestimmt und es dann eingepflanzt, daß es, an seiner Stätte wohnend, nicht mehr zittere, und Ruchlose es nimmer drücken so wie früher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Seit jenen Zeiten, da ich Richter meinem Volke Israel bestellt, demütigte ich alle deine Feinde. Nun künde ich dir an: \"Der Herr baut dir ein Haus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Sind deine Tage voll geworden, daß du zu deinen Vätern gehst, alsdann bestimme ich aus deinen Söhnen deinen Nachfolger und festige sein Königtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Mir baut er dann ein Haus, und ich befestige für alle Zeiten deinen Thron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ich will ihm Vater sein, er wird mir Sohn. Und ich entziehe nie ihm meine Huld, wie ich sie dem entzog, der vor dir war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Und ich bestelle ihn für mein Haus und für mein Reich auf alle Zeit. Sein Thron hat immerdar Bestand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Genau nach diesen Worten und nach diesem Gesicht redete Natan zu David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Da ging der König David, setzte sich vor den Herrn und sprach: \"Wer bin ich, Herr, Gott? Was ist mein Haus, daß Du mich bis hierher geführt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Dies war Dir noch zuwenig, Gott. Du gabst dem Hause Deines Sklaven Verheißungen auf weit hinaus. Du siehst auf mich, Herr, Gott, als wäre ich gar eine hehre menschliche Gestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Was soll denn David Dir noch weiter sagen von Deines Knechtes Ruhm? Du kennst ja selber Deinen Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Für Deinen Sklaven, Herr, für Deinen Hund, hast Du das Große all getan und alle diese Herrlichkeiten angekündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herr! Dir ist keiner gleich. Kein Gott ist außer Dir nach alledem, was wir vernommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Wo ist ein Volk wie Dein Volk Israel, ein einzig Volk auf Erden, das sich zum Volke zu erkaufen ein Gott gegangen wäre, Dir einen Namen, groß und furchtbar, zu erwerben; daß Heiden Du vertriebst vor Deinem Volke, das Du aus dem Ägypterland erlöst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Doch Du hast Israel, Dein Volk, für immer Dir zum Volk bestellt, und Du bist ihnen, Herr, zum Gott geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nun aber, Herr! Verwirkliche das Wort für immer, das über Deinen Sklaven und sein Haus Du hast gesprochen! Und tu jetzt, wie Du es gesagt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Dann ist Dein Name wohlbewährt und groß für immer, und er lautet: \'Der Herr der Heerscharen, Gott Israels, der Schutzgott Israels.\' Und Deines Sklaven David Haus steht fest vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Denn Du, mein Gott, hast Deinem Sklaven selbst geoffenbart, ein Haus ihm zu erbauen. Drum faßt Dein Sklave sich ein Herz, um dies Gebet Dir vorzutragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nun, Herr, Du selbst bist Gott. Du gabst dies herrliche Versprechen Deinem Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Nun laß es Dir gefallen und segne Deines Sklaven Haus, daß es für alle Zeit vor Dir bestehe! Denn was Du segnest, Herr, das ist für alle Zeit gesegnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Danach schlug David die Philister und demütigte sie. Er nahm Gat mit seinen Tochterorten den Philistern weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Dann schlug er Moab, und die Moabiter wurden David untertan und brachten Gaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Hierauf schlug David den König von Soba, Hadarezer, gegen Hamat zu, als er daranging, seine Macht am Euphratstrome aufzurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'David nahm ihm 1.000 Wagen, 7.000 Reiter und 20.000 Mann Fußvolk weg. Alle Rosse lähmte David. Nur 100 Rossewagen ließ er übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Da kamen die damaszenischen Aramäer dem König von Soba, Hadarezer, zu Hilfe. Aber David schlug die Aramäer, 22.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Dann setzte David im damaszenischen Aram Vögte ein. So wurden die Aramäer David untertan und steuerpflichtig. Der Herr half David überall, wohin er zog.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'David nahm auch die goldenen Schilde, die Hadarezers Knechte trugen, und brachte sie nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Aus Tibchat und Kun, Hadarezers Städten, holte David sehr viel Erz. Daraus machte Salomo das eherne Meer, die Säulen und die ehernen Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Da hörte Hamats König Tou, David habe die ganze Streitmacht Hadarezers, des Königs von Soba, geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'So sandte er nun seinen Sohn Hadoram zu König David, ihn zu begrüßen und zu beglückwünschen wegen seines siegreichen Kampfes mit Hadarezer. Denn Hadarezer war Tous Kriegsgegner. Er sandte auch allerlei goldene, silberne und eherne Gegenstände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Auch sie weihte König David dem Herrn samt dem Silber und Gold, das er von den Heiden weggeführt hatte, von Edom, Moab, den Söhnen Ammons, den Philistern und den Amalekitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Serujas Sohn, Absai, aber hatte Edom, 18.000 Mann, im Salztal geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Er setzte in Edom Vögte ein, und ganz Edom ward David untertan. Und der Herr half David überall, wohin er kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'So regierte David ganz Israel und übte Recht und Gerechtigkeit an seinem ganzen Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, Serujas Sohn, war über das Heer gesetzt. Achiluds Sohn Josaphat war Kanzler,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadok, Achitubs Sohn, und Ebjatars Sohn Abimelek waren Priester und Savsa Schreiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benjahu, Jojadas Sohn, befehligte die Bogenschützen und die Schildträger. Davids Söhne aber waren die Ersten um den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Danach starb der Ammoniterkönig Nachas, und sein Sohn ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Da sprach David: \"Ich will dem Chanun, des Nachas Sohn, Liebes tun, weil sein Vater mir Liebes getan hat.\" So sandte David Boten, ihn wegen seines Vaters zu trösten. So kamen Davids Diener ins Ammoniterland zu Chanun, ihn zu trösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Da sprachen die Ammoniterfürsten zu Chanun: \"Ehrt David nach deiner Ansicht deinen Vater, daß er dir Tröster schickt? Kommen seine Diener nicht zum Ausforschen, Erkunden und Ausspähen des Landes zu dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Da ergriff Chanun die Diener Davids, schor sie und schnitt ihnen die Gewänder halb bis ans Gesäß ab. So schickte er sie fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Sie gingen. Nun berichtete man David über die Männer. Da sandte er ihnen entgegen. Denn die Männer waren schwer beschimpft. Der König ließ sagen: \"Bleibt in Jericho, bis euch der Bart gewachsen ist! Dann kommt heim!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Die Ammoniter aber merkten, daß sie sich bei David verhaßt gemacht hatten. Da schickten Chanun und die Ammoniter tausend Silbertalente, sich bei den Aramäern in Mesopotamien und den Aramäern von Maaka und Soba Wagen und Reiter zu dingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Sie dingten sich 32.000 Wagen sowie den König von Maaka mit seinem Volk. Dann zogen sie heran und lagerten vor Medeba. Auch die Ammoniter sammelten sich aus ihren Städten und zogen zum Kampf aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Als David dies hörte, schickte er Joab mit dem ganzen Heer der Krieger aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Da rückten die Ammoniter aus und stellten sich am Eingang der Stadt zum Kampfe auf. Die Könige aber, die gekommen waren, standen für sich im Gelände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Als Joab sah, daß ihm ein Angriff von vorn und von hinten drohe, wählte er Leute aus allen Erlesenen Israels und stellte sich den Aramäern entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Den Rest des Volkes aber unterstellte er seinem Bruder Absai. Und sie stellten sich den Ammonitern gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Er sprach: \"Werden die Aramäer mir zu stark, dann komm du mir zu Hilfe! Sind aber die Ammoniter dir zu stark, dann helfe ich dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sei tapfer! Seien wir mutig für unser Volk und die Diener unseres Gottes! Der Herr aber tue, was ihm gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'So rückte Joab mit dem Volke bei ihm zum Kampfe gegen die Aramäer vor. Da flohen sie vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Als die Ammoniter sahen, daß die Aramäer flohen, flohen auch sie vor seinem Bruder Absai und zogen sich zurück. Hierauf zog Joab nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Als die Aramäer sahen, daß sie von Israel geschlagen waren, sandten sie Boten und ließen die Aramäer jenseits des Stromes ausrücken. Und Hadarezers Feldherr Sophak stand an ihrer Spitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Dies ward David gemeldet. Da bot er ganz Israel auf, überschritt den Jordan, zog gegen sie und stellte sich ihnen zum Kampf. David stellte sich also gegen die Aramäer zum Kampfe auf, und sie stritten mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Aber die Aramäer mußten vor Israel fliehen, und David schlug von den Aramäern 7.000 Wagenkämpfer und 40.000 Mann Fußvolk. Auch den Feldherrn Sophak tötete er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Als Hadarezers Diener sahen, daß sie von Israel geschlagen waren, schlossen sie Frieden mit David und waren ihm untertan. Und die Aramäer hatten keine Lust mehr, den Ammonitern weiter zu helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Zur Zeit der Jahreswende, zur Zeit, wenn die Könige ins Feld ziehen, führte Joab das Heer ins Feld und verheerte das Ammoniterland. Dann zog er hin und belagerte Rabba. David aber blieb in Jerusalem. Dann erstürmte Joab Rabba und zerstörte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'David aber nahm dem Milkom seine Krone vom Kopf und fand, daß sie ein Talent Gold wog. Kostbare Edelsteine waren daran, und sie paßte auf Davids Haupt. Die Beute der Stadt führte er in großer Menge weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Das Volk aber, das darin war, führte er heraus. Dann legte er Feuerbrände an und hieb und stach mit Eisen darein. So tat David mit all den anderen Ammoniterstädten. Dann kehrte David mit dem ganzen Volk nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Hernach kam es nochmals mit den Philistern in Gezer zum Kampf. Damals erlegte der Chusatite Sibkai den Sippai, eines der Riesenkinder. So wurden sie gedemütigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Nochmals war ein Kampf mit den Philistern. Da schlug Jairs Sohn Elchanan den Gatiter Lachmi, Goliats Bruder, dessen Speerschaft einem Weberbaume glich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Nochmals war ein Kampf bei Gat. Da war ein riesenlanger Mensch, der je sechs Finger und Zehen hatte, also vierundzwanzig, und der gleichfalls von den Riesen stammte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Als er Israel höhnte, schlug ihn Jonatan, der Sohn Simeas, des Bruders Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Diese stammten von den Riesen zu Gat und fielen durch Davids und seiner Diener Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satan aber trat gegen Israel auf und reizte David zur Zählung Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'So gebot David Joab und den Volksobersten: \"Auf! Zählt Israel von Beerseba bis Dan, und bringt mir Bescheid, daß ich weiß, wieviel ihrer sind!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Da sprach Joab: \"Mag der Herr sein Volk, wie es ist, noch hundertfach vermehren! Sind sie nicht alle dem König, meinem Herrn, untertan? Warum verlangt dies mein Herr? Warum soll es Israel zur Schuld werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Aber des Königs Befehl zwang Joab. Da zog Joab aus, durchwanderte ganz Israel und kam wieder nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Und Joab gab David die Zahl aus der Volkszählung an: Ganz Israel zählte 1.100.000 und Juda 470.000 schwertgerüstete Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Er hatte aber Levi und Benjamin nicht mitgemustert. Denn des Königs Befehl war Joab ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Gott aber mißfiel diese Sache, und so schlug er Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Da sprach David zu Gott: \"Ich habe schwer gesündigt durch das, was ich getan. Nun aber vergib Deinem Knechte die Schuld! Denn ich habe töricht gehandelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Da sprach der Herr zu Gad, dem Seher Davids, also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '\"Auf! Sprich zu David: \'So spricht der Herr: Ich lege dreierlei dir vor. Eins wähle dir davon, daß ich\'s dir antue!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Da ging Gad zu David und sprach zu ihm: \"So spricht der Herr: \'Wähledir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Entweder Hungersnot drei Jahre lang oder drei Monate Flucht vor deinen Widersachern, wobei dich deiner Feinde Schwert ereilt, oder drei Tage lang das Schwert des Herrn und Pest im Lande, daß der Engel des Herrn das Gesamtgebiet von Israel wüst macht.\' Nun sieh zu, was ich dem bescheiden soll, der mich gesandt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Da sprach David zu Gad: \"Mir ist sehr bange. Doch möchte ich lieber in die Hand des Herrn fallen. Denn sein Erbarmen ist sehr groß. Aber in Menschenhand möchte ich nicht fallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'So schickte der Herr eine Pest über Israel, und aus Israel fielen 70.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Gott sandte auch einen Engel nach Jerusalem, es zu verheeren. Als er es verheerte, sah der Herr darein und ließ sich das Unheil gereuen. Er sprach zum Engel, der die große Verheerung anrichtete: \"Zieh deine Hand jetzt ab!\" Eben stand des Herrn Engel bei der Tenne des Jebusiters Ornan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Als nun David seine Augen erhob, sah er den Engel des Herrn zwischen Erde und Himmel stehen, in der Hand ein gezücktes Schwert, gegen Jerusalem ausgestreckt. Da fielen David und die Ältesten, mit härenen Gewändern bedeckt, auf ihr Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Und David sprach zu Gott: \"Habe nicht ich befohlen, das Volk zu zählen? Ich bin es also, der gesündigt und übel gehandelt hat. Was aber haben diese Schafe getan? Herr, mein Gott! Deine Hand sei gegen mich und mein Haus, nicht aber gegen Dein Volk zum Schlagen bereit!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Der Engel des Herrn aber hatte Gad angewiesen, David zu melden, David möge hinaufgehen und einen Altar für den Herrn auf der Tenne des Jebusiters Ornan errichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Da ging David hinauf nach Gads Wort, das er im Namen des Herrn ausgesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Ornan sah wiederholt den Engel. Seine vier Söhne bei ihm aber versteckten sich. Ornan drosch gerade Weizen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'So kam David zu Ornan. Ornan aber blickte auf und sah David. Da ging er aus der Tenne und verneigte sich vor David bis zum Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Da sprach David zu Ornan: \"Gib mir den Tennenplatz, daß ich darauf für den Herrn einen Altar baue! Gib ihn mir für den vollen Betrag! Damit werde die Seuche vom Volk abgewehrt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Da sprach Ornan zu David: \"Nimm ihn dir! Mein Herr, der König, tue, was ihm gefällt! Ich gebe dir die Rinder zu den Brandopfern, die Dreschschlitten zum Holz und den Weizen zum Speiseopfer. All dies gebe ich dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Da sprach der König David zu Ornan: \"Nein! Ich will ihn um den vollen Betrag käuflich erwerben. Denn ich nehme für den Herrn nicht das weg, was dir gehört, um ein Brandopfer umsonst darzubringen.\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'So gab David dem Ornan für den Platz die Summe von 600 Goldringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Dann baute David dort einen Altar für den Herrn und brachte Brand- und Dankopfer dar. Und als er den Herrn anrief, antwortete ihm dieser auf dem Brandopferaltar mit Feuer vom Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Und der Herr befahl dem Engel, sein Schwert wieder in die Scheide zu stecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Damals, als David wahrnahm, daß ihm der Herr auf der Tenne des Jebusiters Ornan Antwort gab, opferte er dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Des Herrn Wohnung aber, die Moses in der Wüste gefertigt hatte, und der Brandopferaltar waren damals auf der Höhe von Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'David aber konnte nicht vor ihm erscheinen, Gott zu befragen. Denn er war vor dem Schwerte des Engels des Herrn erschrocken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Und David sprach: \"Dies hier sei das Haus Gottes, des Herrn, und dies der Altar für die Brandopfer Israels.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Dann befahl David, die Fremdlinge im Lande Israel zu sammeln. Hierauf bestellte er Steinmetzen, um Quadersteine zum Bau des Gotteshauses zu behauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Ferner beschaffte David eine Menge Eisen für die Nägel zu den Torflügeln und für die Klammern und eine solche Menge Erz, daß man es nicht wägen konnte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'auch unzählige Zedernbalken. Denn die Sidonier und Tyrier brachten David Zedernbalken in Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'David sagte nämlich: \"Mein Sohn Salomo ist noch jung und zart. Das Haus aber, das für den Herrn zu bauen ist, muß überaus groß werden, daß es als Ruhm und Zier für alle Länder dastehe. So will ich es denn vorbereiten.\" Und so beschaffte David vor seinem Tode Vorrat in Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Dann rief er seinen Sohn Salomo und gebot ihm, ein Haus dem Herrn, dem Gott Israels, zu bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'David sprach zu seinem Sohne Salomo: \"Ich habe im Sinne gehabt, ein Haus für den Namen des Herrn, meines Gottes, zu bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Da erging aber das Wort des Herrn an mich: \'Du hast in Menge Blut vergossen und große Kriege unternommen. So darfst du meinem Namen kein Haus erbauen, weil du viel Blut auf Erden vergossen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Doch siehe! Ein Sohn wird dir geboren. Er wird ein Mann der Ruhe sein. Und ich verschaffe ihm Ruhe vor all seinen Feinden ringsumher. Er heißt ja Salomo. Und Ruhe und Frieden gebe ich in seinen Tagen Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Er baut ein Haus für meinen Namen. Er ist mir Sohn und ich ihm Vater. Ich gründe seinen königlichen Thron für alle Zeiten über Israel.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nun, mein Sohn! Der Herr sei mit dir, daß es dir gelinge und du das Haus des Herrn, deines Gottes, bauest, wie er dir verheißen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Nur gebe dir der Herr Verstand und Klugheit und bestelle dich über Israel, daß du des Herrn, deines Gottes, Lehre beachtest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Dann hast du Glück, wenn du die Satzungen und Rechte einhältst, die der Herr dem Moses für Israel geboten. Sei stark und mutig! Sei nicht furchtsam und nicht ängstlich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Bei meiner Armut habe ich für das Haus des Herrn 100.000 Talente Gold beschafft und eine Million Silber, dazu so viel Erz und Eisen, daß es nicht zu wägen ist; in solcher Masse ist es da. Auch Balken und Steine habe ich beschafft, und du wirst noch mehr dazutun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Auch Werkleute, Steinhauer, Maurer und Zimmerleute sind bei dir in Menge und allerlei Kunstverständige für jegliche Arbeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'in Gold, Silber, Erz und Eisen ohne Zahl. Auf! Geh ans Werk! Der Herr sei mit dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Dann befahl David allen Fürsten Israels, seinem Sohne Salomo beizustehen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '\"Ist denn nicht der Herr, euer Gott, mit euch gewesen und hat euch ringsum Ruhe verschafft? Er hat ja in meine Hand des Landes Bewohner gegeben, und das Land hat sich dem Herrn und seinem Volke unterwerfen müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'So richtet euer Herz und euren Sinn darauf, den Herrn, euren Gott, zu suchen! Auf! Baut Gottes, des Herrn, Heiligtum,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Als David alt und lebenssatt geworden war, bestellte er seinen Sohn Salomo zum König über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Er versammelte alle Fürsten Israels, ebenso die Priester und die Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Und die Leviten wurden von dreißig Jahren an und darüber gezählt. Ihre Kopfzahl war 38.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '\"Von diesen sollen 24.000 der Arbeit am Hause des Herrn vorstehen und 6.000 Amtleute und Richter sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, '4.000 seien Torhüter, und 4.000 sollen den Herrn mit den Spielgeräten preisen, die ich zum Lobpreis mache!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'David teilte sie in Abteilungen nach den Levisöhnen Gerson, Kehat und Merari.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Zu den Gersoniten gehörten Ladan und Simei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ladans Söhne sind das Oberhaupt Jechiel, Zetam und Joel, drei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Simeis Söhne sind Selomit, Chaziel und Haran, drei. Diese sind die Familienhäupter Ladans.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Simeis Söhne waren auch Jachat, Zina, Jëus und Beria. Dies sind die Söhne Simeis, vier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jachat war das Oberhaupt und Zina der zweite. Jëus aber und Beria hatten nur wenig Kinder, so daß sie bloß eine Familie, eine Amtsklasse bildeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehats Söhne sind Amram, Ishar, Chebron und Uzziel, vier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amrams Söhne sind Aaron und Moses. Aaron aber wurde ausgesondert, um für immer hochheilig geweiht zu sein, er und seine Söhne, damit sie beständig vor dem Herrn räucherten, ihm dienten und mit seinem Namen segneten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Moses aber war der Mann Gottes. Seine Söhne wurden zum Levitenstamm gerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mosis Söhne sind Gersom und Eliezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Gersoms Söhne sind: das Oberhaupt Sebuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Eliezers Söhne sind: das Oberhaupt Rechabja; andere Söhne hatte Eliezer nicht. Dagegen waren Rechabjas Söhne überaus zahlreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Ishars Söhne sind: das Oberhaupt Selomit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Chebrons Söhne sind: das Oberhaupt Jeriahu, Amarja, der zweite, Jachaziel, der dritte, und Jekamam, der vierte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Uzziels Söhne sind das Oberhaupt Mika und Isia, der zweite,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Meraris Söhne sind Machli und Musi. Machlis Söhne sind Eleazar und Kis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar starb, ohne Söhne zu hinterlassen. Er hatte nur Töchter. Diese heirateten die Söhne des Kis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Musis Söhne sind Machli, Eder und Jeremot, drei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Dies sind Levis Söhne nach ihren Familien, die Familienhäupter nach ihrer Musterung, nach der Zahl der Namen, Kopf für Kopf, die beim Dienste am Hause des Herrn beschäftigt waren, von zwanzig Jahren und darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Denn David sprach: \"Der Herr, Israels Gott, hat seinem Volke Ruhe verliehen und wohnt in Jerusalem für alle Zeiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'So brauchten auch die Leviten die Wohnung nicht mehr zu tragen und keines der zu ihrem Dienst erforderlichen Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Denn nach Davids letzten Befehlen wurde die Zahl der Levisöhne von den Zwanzigjährigen an berechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Ihre Amtspflicht bestand in der Unterstützung der Aaronssöhne beim Dienst im Hause des Herrn, als Aufseher über die Vorhöfe und Zellen und über die Reinigung alles Heiligen sowie in den Dienstverrichtungen am Gotteshause,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'ferner in der Besorgung der reihenweise aufgelegten Brote, des Feinmehls zum Speiseopfer und der ungesäuerten Fladen, der Pfanne und des Eingerührten, eines jeden Hohl- und Längenmaßes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'ferner darin, daß sie jeden Morgen hintraten, dem Herrn zu danken und ihn zu preisen, ebenso am Abend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'und bei jeder Darbringung von Brandopfern für den Herrn an den Sabbaten, Neumonden und Festen, soviel ihrer nach Vorschrift beständig vor dem Herrn darzubringen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'So sollten sie die Geschäfte am Bundeszelt tun und die Geschäfte am Heiligtum, ferner die Geschäfte bei ihren Brüdern, den Aaronssöhnen, während des Dienstes am Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Auch die Aaronssöhne hatten ihre Abteilungen. Die Aaronssöhne waren Nadab, Abihu, Eleazar und Itamar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nadab und Abihu aber starben vor ihrem Vater, ohne Söhne zu hinterlassen. So wurden Eleazar und Itamar Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'David teilte sie mit Sadok von Eleazars Söhnen und mit Achimelek von den Söhnen Itamars je nach ihrem Amt in ihren Dienst ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Nun waren Eleazars Söhne in den Sippenhäuptern zahlreicher als Itamars Söhne. Sie teilten sich so, daß auf Eleazars Söhne sechzehn und auf die Itamars acht Familienhäupter kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Sie teilten sie durch das Los, die einen wie die anderen. Denn es gab Fürsten des Heiligtums und Fürsten Gottes sowohl bei Eleazars als bei Itamars Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Und Netanels Sohn, Semaja, der Schreiber aus der Levitenzahl, schrieb sie vor dem König, den Fürsten und dem Priester Sadok auf. Je eine Familie wurde dabei von Itamar und je zwei von Eleazar ausgelost.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Das erste Los fiel auf Jojarib, das zweite auf Jedaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'das dritte auf Charim, das vierte auf Seorim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'das fünfte auf Malkia, das sechste auf Mijjamin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'das siebte auf Hakkos, das achte auf Abia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'das neunte auf Jesua, das zehnte auf Sekanjahu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'das elfte auf Eljasib, das zwölfte auf Jakin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'das dreizehnte auf Chuppa, das vierzehnte auf Jeseb,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'das fünfzehnte auf Bilga, das sechzehnte auf Immer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'das siebzehnte auf Chezir, das achtzehnte auf Happisses,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'das neunzehnte auf Petachja, das zwanzigste auf Jechezkel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'das einundzwanzigste auf Jakin, das zweiundzwanzigste auf Gamul,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'das dreiundzwanzigste auf Delaja und das vierundzwanzigste auf Maazja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Das war ihre Amtsordnung für ihren Dienst, der darin bestand, daß sie des Herrn Haus nach der ihnen von ihrem Vater Aaron gegebenen Vorschrift betraten, wie es ihm der Herr, Israels Gott, geboten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Was die übrigen Levisöhne betrifft, so stammte von Amrams Söhnen Subael her, von Subaels Söhnen Iechdejahu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'von Rechabjahu, und zwar den Rechabjahusöhnen, das Oberhaupt Issia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'von den Ishariten Selomot, von Selomots Söhnen Jachat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Jerias Söhne sind Amarja, der zweite, Jachaziel, der dritte, und Jekaman, der vierte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Uzziels Söhne sind: Mika, von Mikas Söhnen Samir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Mikas Bruder ist Issia; von den Söhnen Issias Zakarja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Meraris Söhne sind Machli und Musi, die Söhne seines Sohnes Jaazia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Meraris Söhne von seinem Sohn Jaaziahu sind Soham, Zakkur und Ibri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Von Machli stammte Eleazar. Dieser hatte keine Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Von Kis: die Söhne des Kis: Jerachmeel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Des Musi Söhne sind Machli, Eder und Jerimot. Dies sind die Levitensöhne nach ihren Familien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Auch sie warfen Lose, wie ihre Brüder, die Söhne Aarons, vor König David, vor Sadok und Achimelek sowie vor den Familienhäuptern der Priester und Leviten, die Familienhäupter ebenso wie ihre jüngeren Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Ferner bestellte David Dienstobere für die Dienstleistung der Söhne Asaphs, Hemans und Jedutuns, die mit Zithern, Harfen und Zimbeln vorspielen sollten. Es erfolgte aber eine Zählung der mit diesem Dienste Beschäftigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Von Asaphs Söhnen standen Zakkur, Joseph, Netanja und Asarela, Asaphs Söhne, unter Asaph, der nach des Königs Geheiß vorspielte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Von Jedutun standen Jedutuns Söhne Gedalja, Suri, Jesaja, Chasabja und Mattitja, sechs, mit Zithern unter ihrem Vater Jedutun, der beim Danksagen und beim Lobpreise des Herrn vorspielte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Von Heman waren es Hemans Söhne Bukkiahu, Mattanjahu, Uzziel, Sebuel, Jerimot, Chananja, Chanani, Eliata, Giddalti, Romamtiezer, Josbekasa, Malloti, Hotir und Machaziot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Dies alles sind Söhne Hemans, des königlichen Sehers in göttlichen Dingen und Zeichendeuters. Gott schenkte Heman vierzehn Söhne und drei Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Diese alle standen unter ihrem Vater beim Gesang im Hause des Herrn, mit Zimbeln, Harfen und Zithern beim Dienst im Gotteshause unter dem König, Asaph, Jedutun und Heman.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ihre Zahl nebst der ihrer Brüder, die in den Liedern des Herrn wohlerfahren waren, insgesamt Meister, betrug 288.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Sie warfen Lose für den Dienst, für den der jüngeren und für den der Älteren, für Meister und Schüler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Das erste Los Asaphs fiel auf Joseph, das zweite auf Gedalja; er, seine Brüder und Söhne waren zusammen zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'das dritte auf Zakkur; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'das vierte auf Isri; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'das fünfte auf Netanjahu; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'das sechste auf Bukkiahu; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'das siebte auf Jesarela; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'das achte auf Jesajahu; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'das neunte auf Mattanjahu; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'das zehnte auf Simei; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'das elfte auf Azarel; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'das zwölfte auf Chasabja; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'das dreizehnte auf Subael; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'das vierzehnte auf Mattijahu; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'das fünfzehnte auf Jeremot; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'das sechzehnte auf Chananjabu; seine Söhne und Bruder: Zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'das siebzehnte auf Josbekasa; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'das achtzehnte auf Chanani; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'das neunzehnte auf Malloti; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'das zwanzigste auf Eliata; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'das einundzwanzigste auf Hotir; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'das zweiundzwanzigste auf Giddalti; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'das dreiundzwanzigste auf Machaziot; seine Söhne und Brüder: zwölf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'das vierundzwanzigste auf Romamtiezer; seine Söhne und Brüder: zwölf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Bei den Torhüterabteilungen war von den Korachiten Meselemjahu, Kores Sohn von den Asaphsöhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Und Meselemjahus Söhne sind Zakarja, der Erstgeborene, Iediael, der zweite, Zabadjahu, der dritte, Jatmiel, der vierte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam, der fünfte, Jochanan, der sechste, Eljoënai, der siebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Auch Obededom hatte Söhne: Semaja, den Erstgeborenen, Jozabad, den zweiten, Joach, den dritten, Sakar, den vierten, Netanel, den fünften,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel, den sechsten, Issakar, den siebten, und Pëulletai, den achten. Denn ihn hatte Gott gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Auch seinem Sohne Semaja waren Söhne geboren worden, die in ihrer Familie Führer waren. Denn sie waren tapfere Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Semajas Söhne waren Otnai und Rephael, Obed, Elzabad, Elihu und Semakjahu, seine Brüder, tüchtige Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Diese alle stammen von Obededoms Söhnen ab, sie, ihre Söhne und Brüder, tüchtige Leute, zum Dienste wohlbefähigt, zweiundsechzig von Obededom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Auch Meselemja hatte achtzehn Söhne und Brüder, tüchtige Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Chosas Söhne, die zu Meraris Söhnen gehörten, waren: das Oberhaupt Simri. Denn kein Erstgeborener war mehr dagewesen, und so machte ihn sein Vater zum Oberhaupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Chilkiahu war der zweite, Tebaljahu der dritte und Zakarjahu der vierte. Chosas Söhne und Brüder waren insgesamt dreizehn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Diesen Abteilungen der Torhüter, und zwar den Sippenhäuptern, fielen ebenso wie ihren Brüdern die amtlichen Dienstleistungen am Hause des Herrn zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Man warf das Los für die einzelnen Tore nach Familien, für die Jüngeren wie für die Älteren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Da fiel das Los nach Osten auf Selemjahu. Auch für seinen Sohn Zakarjahu, einen klugen Ratgeber, warf man das Los, und das Los fiel für ihn nach Norden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'für Obededom nach Süden und für seine Söhne auf das Vorratshaus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'für Suppim und für Chosa nach Westen samt dem Ausgangstor an der aufsteigenden Straße, ein Wachtposten neben dem anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Nach Osten zu waren es sechs Leviten, nach Norden zu täglich vier, nach Süden täglich vier, am Vorratshause je zwei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'am Festungsturme nach Westen vier für die Straße und zwei für den Festungsturm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Dies sind die Abteilungen der Torhüter von den Söhnen des Korachiten und von den Merarisöhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Ihre Brüder aber, die Leviten, beaufsichtigten die Vorräte des Gotteshauses und die heiligen Gaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ladans Söhne, die Söhne des Gersoniten Ladan, die Familienhäupter Ladans, des Gersoniters, die Jechieliter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'die Söhne der Jechieliter, Zetam und sein Bruder Joel, beaufsichtigten die Vorräte im Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Bei den Amramiten, Ishariten, Chebroniten und Ozzieliten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'war Sebuel, Gersoms Sohn und Mosis Enkel, Oberaufseher über die Vorräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Bei seinen Brüdern von Eliezer her war sein Sohn Rechabjahu, dessen Sohn Jesajahu, dessen Sohn Joram, dessen Sohn Zikri und dessen Sohn Selomit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Dieser Selomit und seine Brüder beaufsichtigten alle Vorräte an heiligen Gaben, die König David und die Familienhäupter der Anführer von Tausend- und Hundertschaften sowie die Heerführer geweiht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Sie hatten sie aus den Kriegen und aus der Beute geweiht, um des Herrn Haus sicherzustellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Auch alles, was der Seher Samuel, Saul, des Kis Sohn, Abner, Ners Sohn, und Serujas Sohn Joab geweiht hatten, alles Geweihte stand unter Selomits und seiner Brüder Aufsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Von den Ishariten waren Kenanjahu und seine Söhne für die Geschäfte draußen in Israel als Amtsleute und Richter bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Von den Chebroniten standen Chasabjahu und seine Brüder, 1.700 tüchtige Leute, der Verwaltung Israels westlich vom Jordan vor in allen Sachen des Herrn und im Dienste des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Zu den Chebroniten gehörte Jeria, das Oberhaupt der Chebroniter nach ihren Sippen und Familien. Im vierzigsten Regierungsjahre Davids waren sie aufgesucht worden, und unter ihnen waren zu Jazer in Gilead tüchtige Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Seine Brüder, tüchtige Leute, 2.700 Familienhäupter, setzte König David über die Rubeniten, Gaditen und den Halbstamm Manasse in allen Sachen Gottes und des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Israels Söhne nach ihrer Zahl, die Familienhäupter und die Anführer der Tausend- und Hundertschaften, ebenso ihre Amtleute dienten dem König in allen Sachen der Abteilungen, die Monat für Monat, alle Monate des Jahres, antraten und abzogen, jede Abteilung 24.000 Mann stark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Über der ersten Abteilung im ersten Monat stand Zabdiels Sohn Josobeam. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Er stammte von des Peres Söhnen und war das Oberhaupt aller Heerführer im ersten Monat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Über der Abteilung des zweiten Monats stand der Achochiter Dodai, über seiner Abteilung und über der des Fürsten. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Der Obere des dritten Heeres für den dritten Monat war Benajahu, des Priesters Jojada Sohn als Oberhaupt. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Dieser Benajahu war der Held unter den Dreißig und stand den Dreißig vor. Seine Abteilung war die seines Sohnes Ammizadab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Der vierte für den vierten Monat war Joabs Bruder Asahel. Sein Sohn Zabadja war sein Nachfolger. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Der fünfte für den fünften Monat war der Oberste Samhut, der Izrachiter. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Der sechste für den sechsten Monat war der Tekoiter Ira, des Ikkes Sohn. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Der siebte für den siebenten Monat war der Peloniter Cheles von den Söhnen Ephraims. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Der achte für den achten Monat war der Chusatiter Sibbeka aus den Zarechitern. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Der neunte für den neunten Monat war der Anatotiter Eliezer aus den Benjaminiten. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Der zehnte für den zehnten Monat war der Netophatiter Maharai aus den Zarechitern. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Der elfte für den elften Monat war der Piratoniter Benaja von den Söhnen Ephraims. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Der zwölfte für den zwölften Monat war der Netophatiter Cheldai aus Otniel. Bei seiner Abteilung waren 24.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Über den Stämmen Israels standen Fürsten: von den Rubeniten Zikris Sohn Eliezer, von den Simeoniten Maakas Sohn Sephatjahu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'von Levi Kemels Sohn Chasabja, von Aaron Sadok,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'von Juda Elihu, einer der Brüder Davids, von Issakar Mikaels Sohn Omri,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'von Zabulon Obadjahus Sohn Ismajahu, von Naphtali Azriels Sohn Jerimot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'von den Ephraimiten Azazjahus Sohn Hosea, vom Halbstamme Manasse Joel, Pedajahus Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'vom Halbstamme Manasse in Gilead Zakarjahus Sohn Iddo, von Benjamin Abners Sohn Jaasiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'von Dan Jerochams Sohn Azarel. - Dies sind die Fürsten der Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Die Zahl derer von zwanzig Jahren und darunter hatte David nicht aufgenommen. Denn der Herr hatte gesagt, er mache Israel so zahlreich wie des Himmels Sterne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Serujas Sohn Joab hatte mit der Zählung begonnen; aber er hatte sie nicht zu Ende gebracht. Denn deshalb entstand ein Zorn wider Israel. Die Zählung aber war nicht vollständig in das Buch der Chronik des Königs David aufgenonunen worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Über den Vorräten des Königs stand Azmavet, Adiels Sohn, und über den Vorräten auf dem Feld, in den Städten, Dörfern und Türmen stand Jonatan, Uzziahus Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Über den Feldarbeitern beim Ackerbau stand Ezri, Kelubs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Über den Weinbergen stand Simei von Nama. Und über dem, was in den Weinbergen an Weinvorräten war, stand Zabdi von Siphmi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Über den Ölbäumen und Maulbeerfeigen in der Niederung stand Baal Chanan von Gader. Über den Ölvorräten Joas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Über den Rindern, die in Saron weideten, stand Sitri von Saron. Über den Rindern in den Tälern stand Saphat, Adlais Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Über den Kamelen Obil, der Ismaelite, über den Eselinnen Jechdejahu Meronot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Über den Schafen Jaziz, der Hagriter. Diese alle waren Oberbeamte über des Königs David Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonatan, Davids Oheim, ein kluger und schriftkundiger Mann, war Rat. Jechiel, Hakmonis Sohn, war bei den Söhnen des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel war Rat beim König, und Chusai, der Arkiter, war der Freund des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Nach Achitophel aber waren es Jojada, Benajahus Sohn, und Ebjatar. Und Feldhauptmann des Königs war Joab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Es versammelte David alle Oberen Israels, die Oberen der Stämme und die der Abteilungen, die dem König dienten, die Oberen der Tausend- und Hundertschaften, die Oberaufseher über das gesamte Eigentum und die Herden des Königs und seiner Söhne samt den Kämmerlingen, den Helden und allen kriegstüchtigen Männern nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Und König David stand da und sprach: \"Auf mich hört, meine Brüder und mein Volk, hört mich! Im Sinne habe ich gehabt, ein Haus der Ruhe zu erbauen für des Herrn Bundeslade und für den Schemel der Füße unseres Gottes. Ich hatte schon das Bauen vorbereitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Gott aber hat zu mir gesprochen: \'Du sollst kein Haus für meinen Namen bauen. Du bist ein Kriegsmann und hast Blut vergossen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Und dennoch wählte mich der Herr, Gott Israels, aus meinem ganzen Vaterhause, auf daß ich König über Israel für immer sei. Denn Juda hatte er zum Fürsten auserwählt und in dem Judahause meine Sippe, und unter meines Vaters Söhnen hat es ihm beliebt, mich über das gesamte Israel zum Könige zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Von allen meinen Söhnen - der Herr hat mir viele Söhne geschenkt - erwählte er meinen Sohn Salomo, auf daß er sitze auf des Herrn königlichem Throne über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Er sprach zu mir: \'Mein Haus und meine Vorhöfe erbaue mir dein Sohn Salomo! Denn ihn erwählte ich mir zum Sohne, und ihm bin ich Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Und ich bestätige sein Königtum für alle Zeit, wenn er nur standhaft ist, um meine Satzungen und Rechte zu erfüllen, so wie es heute ist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nun denn! Vor den Augen des gesamten Israel, vor des Herrn Gemeinde und auch vor unseres Gottes Ohren sei gesagt: Beachtet doch und suchet alle Satzungen des Herrn, eures Gottes, daß ihr dies treffliche Land behaltet und es auf eure Söhne nach euch ewiglich vererbet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Du, Salomo, mein Sohn, hochschätze deines Vaters Gott und diene ihm mit ungeteiltem Herzen und mit williger Seele! Der Herr erforscht ja alle Herzen und kennt alles Dichten und Trachten. Suchst du ihn auf, dann läßt er sich von dir auch finden. Verläßt du ihn, verwirft er dich für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Sieh zu! Dich hat der Herr erwählt, ein Haus zum Heiligtum zu bauen. Geh frisch ans Werk!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Hierauf übergab David seinem Sohn Salomo den Plan der Vorhalle und den seiner Räume, seiner Schatzkammern, Obergemächer, inneren Kammern und des Raumes für die Deckplatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'sowie den Plan für alles andere, was er noch im Sinne gehabt, für die Vorhöfe im Hause des Herrn und alle Zellen ringsum, für die Vorratskammern des Gotteshauses und die Schatzkammern für die Weihegaben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'für die Abteilungen der Priester und Leviten, für alle dienstlichen Verrichtungen im Hause des Herrn und für alle Geräte für den Dienst im Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'An Gold soviel, wie für die Geräte zu den einzelnen Dienstleistungen nötig war, ebensoviel zu allen silbernen Geräten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'ferner den Bedarf für die goldenen Leuchter und ihre goldenen Lampen, nach dem Gewichte eines jeden Leuchters mit seiner Lampe, ferner den für die silbernen Leuchter, nach dem Gewichte eines jeden Leuchters mit seiner Lampe, gemäß der Verwendung der verschiedenen Leuchter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'ferner den Goldbedarf für die Schaubrottische, für jeden einzelnen Tisch, sodann das Silber für die einzelnen Tische,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'ferner für die Gabeln, Becken und Kannen von gediegenem Golde und für die goldenen Becher, soviel jeder Becher wiegen sollte, ebenso für die silbernen Becher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'für den Räucheraltar geläutertes Gold nach Bedarf, ebenso für das Muster des Wagens, für die goldenen Cherube, die sich ausbreiten und die Bundeslade des Herrn überdecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Über all das hatte er ihn durch eine vom Herrn veranlaßte Schrift belehrt, über alle Arbeiten nach dem Plane.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Dann sprach David zu seinem Sohne Salomo: \"Geh mutig und tapfer ans Werk! Sei nicht furchtsam und nicht bang! Denn der Herr, mein Gott, ist mit dir. Er läßt nicht von dir und verläßt dich nicht, bis alle Arbeiten für den Dienst am Hause des Herrn fertig sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Schon sind die Abteilungen der Priester und der Leviten für den ganzen Dienst am Gotteshause bereit, und für jedes Geschäft hast du allerlei kunstfertige, zu jedem Dienst bereite Leute. Ebenso stehen dir die Obersten und das ganze Volk stets zu Diensten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Und König David sprach zu der ganzen Gemeinde: \"Meinen Sohn Salomo allein hat Gott erwählt. Er ist aber noch jung und zart, und das Werk ist gewaltig. Denn nicht für einen Menschen ist die Burg bestimmt, sondern für Gott den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Und so habe ich mit all meiner Kraft für meines Gottes Haus Gold zu dem goldenen Gerät beschafft, Silber zum silbernen, Erz zum ehernen, Eisen zum eisernen und Holz zum hölzernen, ferner Onyxsteine und glänzende und bunte Steine zu Füllungen, sowie sonstige kostbare Steine und in Menge Alabasterstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Weiter gebe ich in meinem Eifer für meines Gottes Haus das, was ich an erspartem Gold und Silber besitze, zum Hause meines Gottes, mehr als ich bereits für das heilige Haus beschafft habe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, '3.000 Goldtalente Ophirgold und 7.000 Talente geläutertes Silber, um die Wände des Hauses zu überziehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'alles Nötige an Gold und Silber und für jede Arbeit durch Künstlerhand. Wer ist nun bereit, heute für den Herrn mit vollen Händen zu geben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Da spendeten die Obersten der Familien, die Obersten der Stämme Israels, die Obersten der Tausend- und Hundertschaften und die Obersten im königlichen Dienste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Sie gaben zum Bau des Gotteshauses 5.000 Goldtalente oder 10.000 Dariken, 10.000 Talente Silber, 18.000 Talente Erz und 100.000 Talente Eisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Wer Steine besaß, gab sie in den Schatz des Hauses des Herrn unter die Obhut des Gersoniters Jechiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Das Volk aber freute sich über ihre Freigebigkeit; denn mit ungeteiltem Herzen waren sie gegen den Herrn freigebig gewesen. Auch König David hatte sich recht darüber gefreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Da pries David den Herrn angesichts der ganzen Gemeinde. Und David sprach: \"Gepriesen seist Du, Herr, Gott unseres Vaters Israel, von Ewigkeit zu Ewigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dein ist die Größe, Macht und Herrlichkeit und Ruhm und Hoheit, Herr; denn Dein ist alles, so im Himmel wie auf Erden, Herr, die Herrschaft und der Vorrang über alle Hochgeborenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Der Reichtum und die Ehre kommen nur von Dir, und Du bist Herrscher über alles. In Deiner Hand steht Kraft und Macht. Bei Dir steht es, jemanden groß und stark zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nun, unser Gott! Dir danken wir und preisen Deinen Namen voller Glanz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Denn wer bin ich? Was ist mein Volk, daß wir soviel freiwillig spenden können? Von Dir stammt alles. Aus Deiner Hand bloß geben wir es Dir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'sind wir doch Fremdlinge vor Dir und Beisassen wie alle unsere Väter. Ein Schatten nur sind unsere Tage auf der Erde, hoffnungslos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herr, unser Gott! All diese Fülle, die wir jetzt beschafft, um Dir ein Haus für Deinen heiligen Namen zu erbauen, aus Deiner Hand stammt sie, und Dein ist alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Ich weiß, mein Gott, daß Du die Herzen prüfest, daß Du an Redlichkeit Gefallen hast; drum habe ich in Redlichkeit des Herzens alles dies gespendet. Und auch Dein Volk, das hier zugegen, ich sehe es mit Freuden Dir die Gaben bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herr! Unserer Väter Abraham, Isaak und Jakob Gott! Bewahre ewig diese guten Triebe im Herzen Deines Volkes und lenke hin sein Herz zu Dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Gib meinem Sohne Salomo ein ungeteiltes Herz, zu wahren Deine Vorschriften, Gebräuche und Verordnungen und alles dies zu tun und auch die Burg, die ich jetzt vorbereite, zu erbauen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Dann sprach David zu der ganzen Gemeinde: \"Preist den Herrn, euren Gott!\" Da pries die ganze Gemeinde den Herrn, ihrer Väter Gott. Sie neigten sich und warfen sich vor dem Herrn nieder und vor dem Könige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Sie schlachteten für den Herrn Opfer und brachten dem Herrn Brandopfer am anderen Morgen dar: tausend Farren, tausend Widder, tausend Lämmer nebst ihren Trankopfern, dazu in Menge Schlachtopfer für ganz Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Dann aßen sie und tranken vor dem Herrn an jenem Tage mit großer Freude. Dann machten sie Davids Sohn Salomo zum zweitenmal zum König und salbten ihn dem Herrn zum Fürsten und Sadok zum Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'So saß Salomo auf dem Throne des Herrn als König an seines Vaters David Statt, und er hatte Glück. Ganz Israel gehorchte ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Auch alle Obersten und Helden sowie alle Söhne des Königs David unterwarfen sich dem König Salomo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Und der Herr machte Salomo überaus groß in den Augen von ganz Israel und legte auf ihn königlichen Glanz, wie ihn vor ihm kein König von Israel besessen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'David, Isais Sohn, hatte über ganz Israel geherrscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Die Zeit, die er über Israel herrschte, betrug vierzig Jahre. Zu Hebron regierte er sieben Jahre und zu Jerusalem dreiunddreißig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Er starb in schönem Alter, satt an Lebenstagen, Reichtum und Ruhm. Und sein Sohn Salomo ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Des Königs David Geschichte aber, die frühere und die spätere, ist aufgezeichnet in der Geschichte des Sehers Samuel, in der Geschichte des Propheten Natan und in der Geschichte des Sehers Gad,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'samt seiner ganzen Regierung, seinen Heldentaten und den Zeitläuften, die über ihn dahingegangen sind und über Israel und über all die anderen Reiche der Länder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomo, Davids Sohn, aber befestigte sein Königtum. Der Herr, sein Gott, war mit ihm und machte ihn überaus groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Und Salomo sprach zu ganz Israel, zu den Anführern der Tausend- und Hundertschaften, den Richtern und allen Fürsten in ganz Israel, den Familienhäuptern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Und so zogen Salomo und die ganze Gemeinde mit ihm nach der Höhe von Gibeon. Denn dort war Gottes Festgezelt, das Moses, des Herrn Diener, in der Wüste gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Die Gotteslade aber hatte David aus Kirjat Jearim heraufgebracht, weil David für sie sorgen wollte. Denn er schlug für sie ein Zelt in Jerusalem auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Auch der eherne Altar, den Besalel, Uris Sohn und Enkel Churs, gemacht, war vor des Herrn Wohnung. Und Salomo und die Gemeinde suchten ihn auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Dann stieg Salomo dort vor dem Herrn zum ehernen Altar beim Festgezelt hinauf und brachte ihm tausend Brandopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'In jener Nacht aber erschien Gott dem Salomo und sprach zu ihm: \"Erbitte das, was ich dir geben soll!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Da sprach Salomo zu Gott: \"Große Huld hast Du meinem Vater David erwiesen und mich an seiner Statt zum König gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Jetzt nun bewähre sich, Herr, Gott, Dein Wort an meinem Vater David! Denn Du hast mich zum König eines Volks gemacht, so zahlreich wie der Erde Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'So gib mir Weisheit auch und Einsicht, vor diesem Volke aus- und einzuziehen Denn wer vermöchte dies Dein großes Volk zu richten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Da sprach Gott zu Salomo: \"Weil du solches im Sinne hast und nicht um Reichtum, Schätze und Ruhm gefleht, noch um das Leben deiner Hasser, auch nicht um langes Leben, vielmehr dir Weisheit und Erkenntnis erfleht hast, um so mein Volk zu richten, über das ich zum König dich gemacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'so sei dir diese Weisheit und Erkenntnis auch geschenkt! Doch auch Reichtum, Schätze, Ruhm verleihe ich dir, dergleichen nie die Könige vor dir besessen, noch nach dir haben werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Salomo kam nun von der Höhe zu Gibeon nach Jerusalem vor das Bundeszelt und herrschte über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Und Salomo brachte Wagen und Reiter zusammen, und zwar besaß er 14.000 Wagen und 12.000 Reiter. Er legte sie in die Wagenstädte und in des Königs Umgebung nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Und der König machte zu Jerusalem Silber und Gold den Steinen gleich, und die Zedern machte er gleich den Maulbeerbäumen in der Niederung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Und die Ausfuhr der Rosse für Salomo erfolgte aus Ägypten und aus Kue. Die Händler des Königs holten sie aus Kue gegen Bezahlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Aus Ägypten holten sie einen Wagen um sechshundert Silberlinge und ein Roß um hundertfünfzig. Ebenso führten sie an alle chittitischen und aramäischen Könige durch ihre Vermittlung aus. Und Salomo befahl, dem Namen des Herrn ein Haus zu bauen und für sich einen Königspalast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Und Salomo zählte 70.000 Lastträger ab und 80.000 Steinhauer im Gebirge und 3.600 Aufseher darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Dann sandte Salomo an den König von Tyrus, Churam, und ließ sagen: \"Wie du meinem Vater David getan, als du ihm Zedern sandtest, um sich ein Wohnhaus zu bauen,...');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'nun baue ich dem Namen des Herrn, meines Gottes, ein Haus, es ihm zu weihen, vor ihm duftendes Räucherwerk zu verbrennen, ständig Brote darzubringen und jeden Morgen und Abend an den Sabbaten, Neumonden und Festen des Herrn, unseres Gottes, Brandopfer darzubringen. Solches obliegt Israel für ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Das Haus, das ich bauen will, wird groß. Denn unser Gott ist größer als alle Götter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Wer aber vermöchte ihm ein Haus zu bauen? Denn der Himmel und die Himmel der Himmel fassen ihn nicht. Wer aber bin ich, daß ich ihm ein Haus baute? Wenn auch nur, um vor ihm zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Sende mir nun einen Mann, der in Gold, Silber, Erz, Eisen, Purpurrot, Karmin und Purpurblau zu arbeiten versteht und der es versteht, Bildwerke einzuschneiden im Verein mit Künstlern, die bei mir in Juda und Jerusalem sind und die mein Vater David bestellt hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Sende mir auch Zedern, Zypressen und Sandelholz vom Libanon! Denn ich weiß, daß deine Leute es verstehen, auf dem Libanon Holz zu fällen. Meine Knechte werden mit deinen Leuten sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Holz aber muß mir viel beschafft werden. Denn das Haus, das ich baue, soll groß und wunderbar werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Den Holzhauern, die die Bäume fällen, gebe ich als Zehrung für deine Knechte 20.000 Scheffel Weizen, 20.000 Scheffel Gerste, 20.000 Maß Wein und 20.000 Maß Öl.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Churam aber, der König von Tyrus, antwortete in einem Brief und sandte an Salomo die Botschaft: \"Der Herr hat aus Liebe zu seinem Volk dich zum König über es gemacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Churam sprach weiter: \"Gepriesen sei der Herr, Israels Gott, der Himmel und Erde gemacht! Er hat König David einen Sohn geschenkt, weise, klug und umsichtig, um für den Herrn ein Haus zu bauen und für sich einen Königspalast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Nun sende ich einen weisen, kunstverständigen Mann, den einheimischen Churam Abi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Er ist der Sohn eines danitischen Weibes und eines tyrischen Vaters. Er versteht zu arbeiten in Gold, Silber, Erz, Eisen Holz, Purpurrot und Purpurblau, Byssus und Karmin, allerlei einzustechen und allerlei Sinnreiches zu ersinnen, das ihm vorgelegt wird, im Verein mit deinen Künstlern und den Künstlern meines Herrn, deines Vaters David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Nun schicke mein Herr den Weizen und die Gerste, das Öl und den Wein seinen Knechten, wie mein Herr gesagt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Wir aber fällen auf dem Libanon Bäume, soviel du bedarfst, und bringen sie dir als Flöße auf dem Meer nach Joppe. Du läßt sie dann nach Jerusalem hinaufschaffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Da zählte Salomo alle fremden Männer im Lande Israels nach der Zählung, die sein Vater David gemacht hatte. Es waren 153.600.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Von diesen machte er 70.000 zu Lastträgem und 80.000 zu Steinhauern im Gebirge sowie 3.600 zu Aufsehern, um die Leute zum Frondienst anzuhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Salomo begann nun das Haus des Herrn zu Jerusalem zu bauen auf dem Berge Moria, der von seinem Vater David ersehen war und wo David Vorbereitungen getroffen hatte, nämlich auf der Tenne des Jebusiters Ornan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Er begann mit dem Bau am zweiten Tage des zweiten Monats im vierten Jahre seiner Regierung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Dies hat Salomo für den Bau des Gotteshauses angeordnet: Die Länge betrug sechzig Ellen nach früherem Maße und die Breite zwanzig Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Die Vorhalle vor der Breitseite des Hauses hatte zwanzig Ellen; ihre Höhe war hundertzwanzig Ellen. Inwendig überzog er sie mit reinem Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Das große Haus bedeckte er mit Zypressenbrettern und gutem Gold, und er brachte darauf Palmen und Ketten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Auch bekleidete er das Haus zum Schmuck mit kostbarem Gestein. Das Gold war Ophirgold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'So überzog er das Haus, die Balken, die Schwellen, seine Wände und seine Türen mit Gold und ließ Cherube auf die Wände einschneiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Dann machte er den Raum des Allerheiligsten. Seine Länge an des Hauses Breitseite war zwanzig Ellen und seine Breite zwanzig Ellen. Er überzog es mit gutem Gold, an sechshundert Talenten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Das Gewicht der Nägel betrug fünfzig Ring Gold. Auch die Obergemächer überzog er mit Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Im Raume des Allerheiligsten machte er zwei Cherube, Bildhauerarbeit, und überzog sie mit Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Die Cherubsflügel waren zwanzig Ellen lang. Des einen Flügel, fünf Ellen lang, berührte die Wand des Hauses, und der andere Flügel, fünf Ellen lang, berührte den Flügel des anderen Cherubs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Ebenso berührte der eine Flügel des anderen Cherubs, fünf Ellen lang, die Hauswand, und der andere Flügel, fünf Ellen lang, stieß an den Flügel des ersten Cherubs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Die Flügel dieser Cherube breiteten sich zwanzig Ellen aus. Sie selbst standen auf den Füßen, und ihr Antlitz war auf das Haus gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Den Vorhang machte er aus blauem und rotem Purpur, aus karminfarbigem Zeug und aus Byssus und brachte Cherube darauf an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Vor dem Hause machte er zwei Säulen, fünfunddreißig Ellen lang. Der Knauf an jeder oben maß fünf Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Dann machte er Ketten nach Halskettenform und brachte sie oben an den Säulen an; ferner machte er hundert Granatäpfel und hängte sie an die Ketten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Die Säulen stellte er vor dem Tempel auf, die eine rechts, die andere links. Die zur Rechten nannte er Jakin, die zur Linken Boaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Er machte auch einen ehernen Altar, zwanzig Ellen lang, zwanzig breit und zehn hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Dann machte er das Meer, gegossen von einem Rande bis zum anderen zehn Ellen weit ringsum, rund und fünf Ellen hoch. Eine Schnur von dreißig Ellen umspannte es ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Blumengewinde umgaben es nach unten ringsum, je zehn auf eine Elle. Sie umschlossen das Meer ringsum, zwei Reihen von Gewinden, in einem Guß mit ihm gegossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Es stand auf zwölf Rindern. Drei wendeten sich gen Norden, drei gen Westen, drei gen Süden und drei gen Osten. Das Meer ruhte oben auf ihnen. All ihre Rückseiten waren nach innen gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Es war eine Handbreit dick, und sein Rand war wie ein Becherrand lilienförmig. Es faßte dreitausend Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Ferner machte er zehn Becken. Fünf stellte er rechts auf und fünf links zum Abwaschen des zum Brandopfer Gehörigen, das man darin abspülte. Das Meer aber diente den Priestern zur eigenen Abwaschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Ferner machte er vorschriftsmäßig die zehn goldenen Leuchter und stellte sie in den Tempel, fünf rechts und fünf links.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Er machte auch zehn Tische und stellte sie im Tempel auf, fünf rechts und fünf links. Ebenso machte er hundert goldene Schalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Dann machte er den Priestervorhof, den großen Hof und die Tore zum Hof. Ihre Tore überzog er mit Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Das Meer stellte er, nach Osten zu, auf der Südseite auf, dem Süden gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Churam machte auch die Töpfe, Schaufeln und Schalen. So vollendete Churam die Arbeit, die er dem König Salomo im Gotteshause gefertigt hatte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Zwei Säulen und die zwei Kugelknäufe oben auf den Säulen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'die vierhundert Granatäpfel für die zwei Gitter zur Bedeckung der zwei Kugelknäufe oben auf den Säulen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'die zehn Gestühle mit den zehn Decken auf den Gestühlen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'das eine Meer und die zwölf Rinder darunter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Aus poliertem Erz machte Churam Abi dem König Salomo für das Haus des Herrn Töpfe, Schaufeln, Gabeln und all ihre Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Der König goß sie in Erdformen in der Jordansau zwischen Sukkot und Sereda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Salomo machte all diese Geräte in sehr großer Zahl; das Erzgewicht war nicht festgestellt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomo machte alle Geräte im Gotteshause, den goldenen Altar, die Schaubrottische,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'die Leuchter mit ihren Lampen zum vorschriftsmäßigen Anzünden vor dem Hinterraume aus feinem Gold,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'ebenso die Hülsen, Lampen und die goldenen Lichtscheren, die goldenen Zangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'die Messer, Schalen, Schüsseln und Pfannen aus feinem Gold, der Haustür innere Torflügel, die zum Allerheiligsten führten, und des Hauses Torflügel, die zum Tempel führten, aus Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'So ward das ganze Werk fertig, das Salomo am Hause des Herrn tat. Und Salomo brachte seines Vaters David Weihegaben hinein. Er legte das Silber und Gold und alle anderen Wertsachen in die Schatzkammern des Gotteshauses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Damals versammelte Salomo die Ältesten Israels und alle Stammhäupter, die Fürsten der Stammhäuser Israels, nach Jerusalem, um des Herrn Bundeslade von der Davidsstadt, das ist von dem Sion, hinaufzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Am Feste, das ist im siebten Monat, versammelten sich beim König alle Männer Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'So kamen alle Ältesten Israels. Da hoben die Leviten die Lade auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Sie brachten die Lade samt dem Festzelt hinauf, ebenso alle heiligen Geräte im Zelt. Diese brachten die priesterlichen Leviten hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Der König Salomo aber und die ganze Gemeinde Israels, die sich bei ihm versammelte, standen vor der Lade und opferten Schafe und Rinder ohne Zahl und Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'So brachten die Priester die Bundeslade des Herrn an ihren Ort, in des Hauses Hinterraum, in das Allerheiligste, unter die Cherubsflügel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Die Cherube aber breiteten die Flügel über den Ort der Lade aus. So bedeckten die Cherube die Lade und ihre Stangen von oben her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Die Stangen waren so lang, daß die Stangenspitzen von der Lade her vor dem Hinterraum gesehen wurden. Draußen konnten sie nicht gesehen werden. Und so blieb sie dort bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'In der Lade war nichts als die zwei Tafeln, die Moses am Horeb hineingelegt hatte, wo der Herr einen Bund abgeschlossen mit den Kindern Israels bei ihrem Auszug aus Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Nun verließen die Priester das Heiligtum. Denn alle Priester, die zugegen waren, hatten sich geheiligt, ohne Rücksicht auf die Abteilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Die levitischen Sänger alle aber, Asaph, Heman, Jedutun mit ihren Brüdern und Söhnen, standen, in Linnen gekleidet, mit Zimbeln, Harfen und Zithern östlich vom Altar und bei ihnen hundertzwanzig Priester, die Trompeten bliesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Die Trompeter aber und die Sänger hoben zugleich einstimmig an, den Herrn zu preisen und ihm zu danken. Und als der Gesang erscholl mit Trompeten, Zimbeln und den anderen Musikgeräten und mit dem Lobpreise des Herrn: \"Er ist gütig; denn ewiglich währt seine Huld\", ward das Haus von einer Wolke erfüllt, aber nur das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Die Priester aber konnten wegen der Wolke nicht hinzutreten, Dienst zu tun. Denn des Herrn Herrlichkeit hatte das Gotteshaus erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Damals sprach Salomo: \"Im Wetterdunkel hat der Herr gesprochen, er wolle Wohnung nehmen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Nun habe ich ein Haus zur Wohnung Dir erbaut, für ewige Zeiten einen Ort zu Deinem Wohnsitz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Dann wandte der König sein Antlitz und segnete die ganze Gemeinde Israels. Israels Gesamtgemeinde stand unterdessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Er sprach: \"Gepriesen sei der Herr, Gott Israels, der schon durch seinen Mund mit David, meinem Vater, gesprochen und durch ihn auch erfüllt hat, was er geredet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '\'Seitdem ich aus Ägypterland mein Volk herausgeführt, habe ich aus keinem Stamme Israels eine Stadt erkoren, ein Haus darin zu bauen, daß dort mein Name sei. Auch habe ich nie einen Mann erwählt, daß er ein Fürst sei meinem Volke Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Nun wählte ich Jerusalem, daß dort mein Name sei. Und ich erwählte David, auf daß er meinem Volke Israel vorstände.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Mein Vater David hatte zwar im Sinne, dem Herrn, dem Gotte Israels, ein Haus zu bauen für seinen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Doch sprach der Herr zu meinem Vater David: \'Daß du im Sinne hast, ein Haus für meinen Namen zu erbauen, an diesem Plane hast du wohlgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Doch du sollst nicht dies Haus erbauen. Dein Sohn, dein Leibessprosse, baue mir ein Haus für meinen Namen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Der Herr bestätigte sein Wort, das er gesprochen. Ich trat an meines Vaters David Statt und setzte mich auf Israels Thron, wie es der Herr gesagt. Ich baute dieses Haus dem Herrn, dem Gotte Israels, für seinen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Aufgestellt habe ich dort die Lade, in der des Herrn Bund sich befindet, den er mit Israel geschlossen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Dann trat er vor den Altar des Herrn angesichts der ganzen israelitischen Gemeinde und breitete seine Hände aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomo hatte nämlich ein ehernes Gestell machen lassen und es mitten in den Hof gestellt, fünf Ellen lang, fünf breit und drei hoch. Auf dieses Gestell stellte er sich und ließ sich angesichts der ganzen israelitischen Gemeinde auf die Knie nieder. Dann breitete er seine Hände gen Himmel aus');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'und sprach: \"Herr, Israels Gott! Kein Gott gleicht Dir im Himmel und auf Erden, der Du den gnadenvollen Bund bewahrst mit Deinen Dienern, die mit dem ganzen Herzen vor Dir wandeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'der Du auch Deinem Knecht gehalten, meinem Vater David, was Du ihm einst verheißen hast. Mit Deinem Mund hast Du\'s versprochen, mit Deiner Hand hast Du\'s erfüllt, wie\'s heute ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nun, Herr, Gott Israels! Erfülle Deinem Knechte David, meinem Vater, was Du ihm einst versprochen hast: \'Nie fehle dir vor mir ein Mann, der auf dem Throne Israels regiert, falls deine Söhne nur auf ihren Weg so achten, daß sie nach meiner Lehre wandeln, so, wie auch du vor mir gewandelt bist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nun Herr, Gott Israels! Dein Wort bewahrheite sich jetzt, das Du zu Deinem Knechte David, meinem Vater, hast gesprochen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Soll denn in Wahrheit Gott auf Erden wohnen? Dich fassen nicht der Himmel, noch der Himmel Himmel, geschweige dieses Haus, das ich erbaut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Doch wende Dich dem Flehgebete Deines Knechtes zu, Du Herr, mein Gott, daß Du das Rufen und das Beten hörest, das heut vor Dir Dein Knecht vollzieht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Laß Deine Augen über diesem Hause offenstehen, bei Tag und Nacht hier über diesem Orte, von dem Du sprachst, Du wollest Deinen Namen allhier wohnen lassen, um das Gebet zu hören, das jetzt Dein Knecht an diesem Ort verrichtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Auf Deines Knechtes Flehen hör und Deines Volkes Israel, die hier an diesem Orte beten! Vernimm es an der Stätte, wo Du thronest, in dem Himmel! Erhör es und vergib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Wenn jemand gegen seinen Nächsten fehlt und man verlangt von ihm den Eid, er soll\'s beschwören, und kommt er zu dem Eid in dieses Haus vor Deinen Altar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'greif Du, im Himmel hörend, ein, schaff Deinen Dienern Recht, daß Du den Schuldigen bestrafst und auf sein Haupt sein Tun läßt fallen, daß den Unschuldigen Du freisprichst und ihm nach seiner Unschuld lohnest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Wird vor dem Feinde Israel, Dein Volk, geschlagen, weil es an Dir sich hat verfehlt, und sie bekehren sich und preisen Deinen Namen und flehn vor Dir, in diesem Hause betend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'dann höre sie vom Himmel her! Vergib die Sünde Deines Volkes Israel, und laß sie seßhaft auf der Scholle bleiben, die ihnen, wie auch ihren Vätern, Du verliehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Und ist der Himmel fest verschlossen, und fällt kein Regen mehr, weil sie sich gegen Dich verfehlt, und beten sie alsdann an dieser Stätte in dem Bekenntnis Deines Namens und kehren sie sich ab von ihrer Sünde, weil Du sie gebeugt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'dann höre Du im Himmel! Vergib die Sünde Deiner Knechte und das Vergehen Deines Volkes Israel! Den guten Weg, auf dem sie wandeln sollen, weise ihnen! Und sende Regen Deinem Lande, das Du zum Erbteil Deinem Volk verliehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Und wäre Hungersnot im Land, und wären Pest, Getreidebrand, Vergilbung, Heuschrecken und sonstig Ungeziefer da, bedrängte es sein Feind in seinen Pforten, und käme irgendwelche Plage, irgendwelche Krankheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'bei jeder Klage, jeder Bitte, sei es von irgendeinem Menschen, sei es von Deinem ganzen Volke Israel, wer je sein Leid und seinen Schmerz verspürt und hin nach diesem Hause seine Hände breitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'den höre Du im Himmel! Vergib an jener Stätte, wo Du thronest! Gib jeglichem nach seinem ganzen Wandel, so, wie sein Herz Du kennst! Denn Du allein kennst aller Menschenkinder Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Dann fürchten sie Dich alle Zeit und wandeln auch auf Deinen Wegen, solang sie auf der Scholle leben, die unseren Vätern Du verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Doch auch der Fremdling, der zu Deinem Volke Israel nicht gehört, wenn er aus fremdem Lande kommt, um Deines großen Namens, Deiner starken Hand und Deines ausgestreckten Armes willen, wenn er herpilgert und bei diesem Hause betet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'dann höre Du im Himmel, dem Orte, wo Du wohnst, und tu all das, worum der Fremdling zu Dir ruft, daß alle Erdenvölker Deinen Namen kennenlernen, daß sie Dich fürchten, so wie Israel, Dein Volk, und daß sie inne werden, daß über diesem Haus, das ich erbaut, Dein Name ausgerufen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Und zieht Dein Volk zum Streite wider seine Feinde, des Wegs, den Du sie sendest, und beten sie zu Dir nach dieser Stadt hin, die Du Dir erwählt, und nach dem Hause hin, das ich errichtet Deinem Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'dann höre Du im Himmel ihr Gebet und Flehen! Schaff ihnen Sieg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Und wenn sie sich an Dir verfehlten - kein Mensch ist, der nicht sündigte - und wenn Du ihnen zürntest, sie dem Feinde überliefertest und ihre Zwingherrn sie in ferne oder nahe Lande führten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'und gehen sie im Land, wo sie gefangen sind, in sich, und sie bekehren sich und flehn zu Dir im Lande der Gefangenschaft und sprechen: \'Gesündigt haben wir und schlecht gehandelt und gefrevelt\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'und sie bekehren sich zu Dir von ganzem Herzen, ganzer Seele im Lande ihrer Zwingherrn, die sie weggeschleppt, und beten sie zu Dir nach ihrem Lande hin, das ihren Vätern Du verliehen, hin zu der Stadt, die Du erwählt, hin zu dem Haus, das ich errichtet Deinem Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'dann höre Du im Himmel, dem Orte Deines Thrones, ihr Flehen und Gebet! Verschaffe ihnen Recht! Verzeihe Deinem Volk, was es an Dir gefehlt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nun denn, mein Gott! Laß Deine Augen offenstehen und Deine Ohren aufmerken auf das Gebet an dieser Stätte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Und nun, Herr, Gott, erhebe Dich zu Deiner Ruhestätte hin, Du und Deine mächtige Lade! Mit Heil bekleidet seien Deine Priester, Herr und Gott, und Deine Frommen mögen sich des Glücks erfreuen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herr, Gott! Weis nimmer ab den Mann, den Du gesalbt! Sei eingedenk der frommen Taten Deines Dieners David!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Als Salomo ausgebetet hatte, fuhr vom Himmel Feuer herab und verzehrte das Brand- und die Schlachtopfer. Und die Herrlichkeit des Herrn erfüllte das Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Die Priester aber konnten das Haus des Herrn nicht betreten. Denn des Herrn Herrlichkeit erfüllte das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Alle Israeliten aber sahen das Feuer herabfahren und die Herrlichkeit des Herrn im Hause. Da beugten sie sich mit dem Angesicht zur Erde auf das Steinpflaster, beteten an und priesen den Herrn, daß er so gütig sei, weil seine Huld immer währt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Der König und das ganze Volk opferten vor dem Herrn Schlachtopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Der König Salomo brachte 22.000 Rinderschlachtopfer und 120.000 Schafe dar. So weihten der König und das ganze Volk das Gotteshaus ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Die Priester aber standen auf ihren Posten, ebenso die Leviten mit des Herrn Musikgeräten, die der König David gemacht hatte, um dem Herrn dafür zu danken, daß seine Huld immer währt. So trugen sie Davids Lobpreis vor, und die Priester bliesen die Trompeten, während ganz Israel dabeistand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Und Salomo weihte den mittleren Teil des Vorhofes vor dem Hause des Herrn. Denn er bereitete hier Brandopfer und die Fettstücke der Mahlopfer, weil der eherne Altar, den Salomo gemacht, die Brand- und Speiseopfer und die Fettstücke nicht hatte fassen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'So beging Salomo zu jener Zeit das Fest sieben Tage lang, und ganz Israel mit ihm, eine sehr große Gemeinde, von der Gegend um Hamat bis zum Bach Ägyptens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Am achten Tage feierten sie das Schlußfest. Denn die Altarweihe hatten sie sieben Tage gefeiert. Das Fest aber währte sieben Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Am dreiundzwanzigsten Tage des siebten Monats aber entließ er das Volk zu seinen Zelten, fröhlich und guten Mutes über das Gute, das der Herr David und Salomo und seinem Volke Israel erwiesen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Also vollendete Salomo das Haus des Herrn und das Königshaus. Alles, was Salomo im Sinn hatte, im Hause des Herrn und in seinem Hause zu tun, war ihm gelungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Da erschien der Herr dem Salomo des Nachts und sprach zu ihm: \"Ich habe dein Gebet erhört und diesen Ort zur Opferstätte mir erwählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Verschließe ich den Himmel, daß kein Regen fällt, und schicke ich die Heuschrecken, die Gegend abzufressen, und sende ich zu meinem Volk die Pest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'doch wenn mein Volk, das meinen Namen trägt, sich demütigt, und suchen betend sie mein Angesicht, von ihren schlimmen Pfaden lassend, alsdann erhöre ich vom Himmel her, verzeihe ihre Sünde und schaffe Heilung ihrem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Nun sollen meine Augen offenstehen und meine Ohren aufmerken auf das Gebet an dieser Stätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Denn jetzt erwähle ich dies Haus und weihe es, auf daß mein Name hier für immer sei und meine Augen und mein Herz für immer weilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Und wandelst du vor mir so, wie dein Vater David einst gewandelt, und tust, ganz wie ich dir geboten, und achtest meine Vorschriften und Satzungen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'alsdann bestätige ich den Thron deines Königtums, wie ich mit deinem Vater David einen Bund geschlossen: \'Nie fehle dir ein Mann, der Israel beherrscht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Doch fallt ihr ab und verlasset meine Vorschriften und Satzungen, die ich euch vorgelegt, und dienet anderen Göttern und werft euch vor sie hin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'dann reiße ich sie weg von meiner Scholle, die ich ihnen einst verliehen, und weg von meinem Angesicht verwerfe ich das Haus, das meinem Namen ich geweiht, und mache es zum Hohn und Spott für alle Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Und über dieses Haus, das so erhaben war, entsetzt sich jeder, der daran vorübergeht, und fragt er dann: \'Weswegen hat der Herr diesem Land und diesem Hause so getan?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'dann sagen sie: \'Weil sie den Herrn, ihrer Väter Gott, verlassen, der einst sie aus Ägypterland geführt, und sich alsdann an andere Götter hielten und sie anbeteten und ihnen dienten, deswegen hat der Herr all dieses Unheil aber sie gebracht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'In zwanzig Jahren hatte Salomo das Haus des Herrn und sein Haus erbaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Danach baute Salomo die Städte aus, die Churam dem Salomo gegeben, und siedelte Israeliten darin an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Dann zog Salomo nach Hamat bei Soba und eroberte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Er baute auch Tadmor in der Wüste und alle Vorratsstädte aus, die er in Hamat angelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Er baute auch Ober- und Nieder-Bet Choron aus, Festungen mit Mauern, Toren und Riegeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'ferner Baalat und alle Vorratsstädte, die Salomo besaß, alle Wagenstädte, die Städte für die Reiter und alles, was Salomo zu bauen wünschte in Jerusalem, auf dem Libanon und in seinem ganzen Herrschaftsbereich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Aus allem Volk, das von den Chittitern, Amoritern, Perizitern, Chiwitern und Jebusitern übrig war und das nicht aus Israel war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'von seinen Söhnen, die nach ihm im Lande geblieben waren und die die Israeliten nicht ausgerottet hatten, hob Salomo zum Frondienst aus bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Aber von den Israeliten machte Salomo keinen zum Knecht für seine Arbeit. Sie wurden Kriegsleute, Befehlshaber seiner Wagenkämpfer und Befehlshaber seiner Wagen und Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Dies waren die Oberen der Vögte des Königs Salomo, 210, die die Leute beaufsichtigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Salomo aber brachte Pharaos Tochter aus der Davidsstadt in das Haus, das er für sie gebaut hatte. Denn er sprach: \"Kein Weib wohne mir im Hause Davids, des Königs von Israel! Denn der Ort ist heilig, weil dahin die Lade des Herrn gekommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Damals brachte Salomo dem Herrn Brandopfer dar, auf dem Altar des Herrn, den er vor der Vorhalle erbaut hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Das Tägliche brachte er dar nach des Moses Gebot an den Sabbaten, Neumonden und Festen und dreimal im Jahre, an dem Feste der ungesäuerten Brote, am Wochenfeste und am Hüttenfeste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Nach seines Vaters David Anordnung bestellte er die Priesterabteilungen zu ihrem Dienste und die Leviten zu ihren Amtsverrichtungen, daß sie lobsangen und bei den Priestern den täglichen Dienst taten, ferner die Torhüter nach ihren Abteilungen für jedes Tor. Denn so war es Befehl des Gottesmannes David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Man war in keinem Stücke abgewichen von des Königs Befehl betreffs der Priester und Leviten und der Schatzkammern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'So ward Salomos ganzes Werk fertig, von dem Tage an, an dem das Haus des Herrn gegründet wurde, bis zur gänzlichen Vollendung des Hauses des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Damals war Salomo nach Esiongeber und Elot am Meeresufer im Lande Edom gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Churam aber sandte ihm durch seine Knechte Schiffe mit meereskundigen Knechten. Und sie kamen mit Salomos Knechten nach Ophir. Von da holten sie 450 Talente Gold und brachten es dem König Salomo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Auch die Königin von Saba hatte den Ruhm über Salomo vernommen. So kam sie nach Jerusalem, Salomo mit Rätseln zu prüfen, mit sehr großem Gefolge und mit Kamelen, beladen mit Spezereien und Gold in Menge und Edelsteinen. So kam sie zu Salomo. Da besprach sie mit ihm alles, was sie auf dem Herzen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Und Salomo gab ihr Antwort auf alle ihre Fragen. Nichts war Salomo verborgen, das er ihr nicht beantwortet hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Als die Königin von Saba die Weisheit Salomos sah, den Palast, den er erbaut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'die Speisen seines Tisches, die Sitze seiner Diener, das Aufwarten seiner Bedienten, ihre Gewandung, seine Mundschenken und ihre Gewandung und sein Brandopfer, das er im Hause des Herrn darbrachte, da war sie außer sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Sie sprach zum König: \"Wahrheit ist es, was ich in meinem Lande von deinen Sachen und deiner Weisheit vernommen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Ich habe ihren Worten nicht geglaubt, bis ich selbst gekommen bin und es dann mit eigenen Augen gesehen habe. Dabei ist mir nicht die Hälfte der Fülle deiner Weisheit gemeldet worden. Du übertriffst den Ruhm, den ich vernommen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Glücklich deine Mannen! Glücklich diese deine Diener, die allzeit vor dir stehen und deine Weisheit hören!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Gepriesen der Herr, dein Gott, der an dir Wohlgefallen gefunden, um dich auf seinen Thron als König für den Herrn, deinen Gott, zu setzen! Weil dein Gott Israel liebt und es ewig bestehen lassen will, darum hat er dich über sie zum König gesetzt, um Recht und Gerechtigkeit zu üben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Sie gab dem König 120 Talente Gold, Spezereien in sehr großer Menge und Edelsteine. Nie hatte es solche Spezereien gegeben wie die, die Sabas Königin dem König Salomo geschenkt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Auch Churam und Salomos Knechte, die Gold aus Ophir holten, brachten Aloeholz und Edelsteine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Und der König machte aus dem Aloeholz Treppen zum Hause des Herrn und zum Königshause und Zithern und Harfen für die Sänger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Der König Salomo aber erfüllte der Königin von Saba all ihre Wünsche, noch über das hinaus, worum sie den König gebeten hatte. Sie kehrte nun heim und zog in ihr Land mit ihren Dienern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Das Gewicht des Goldes, das für Salomo in einem Jahr einging, betrug 666 Goldtalente,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'außer dem, was die Kaufleute und Händler brachten. Auch alle abgabepflichtigen Könige und die Statthalter des Landes lieferten Salomo Gold und Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Der König Salomo machte 200 Schilde aus geschlagenem Golde; auf jeden Schild verwendete er 600 Ring geschlagenes Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Dazu 300 Schildchen aus geschlagenem Golde. Auf jedes Schildchen verwendete er 300 Ring geschlagenes Gold. Und der König tat sie in das Libanonwaldhaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Ferner machte der König einen großen Elfenbeinthron und überzog ihn mit reinem Golde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Sechs Stufen hatte der Thron und eine Thronsessellehne. Sie waren mit Gold gefaßt, ebenso die Armlehnen auf beiden Seiten des Sitzplatzes. Und zwei Löwen standen neben den Lehnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Zwölf Löwen standen dort auf den sechs Stufen zu beiden Seiten. Solches ward für kein anderes Königreich gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Alle Trinkgefäße des Königs Salomo waren aus Gold und alle Geräte des Libanonwaldhauses von feinem Gold. Silber galt in Salomos Tagen für nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Denn der König besaß Schiffe, die mit Churams Knechten nach Tarsis fuhren. Alle drei Jahre einmal kamen die Tarsisschiffe und brachten Gold und Silber, Elfenbein, Affen und Pfaue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'So übertraf der König Salomo alle Könige der Erde an Reichtum und Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Und alle Könige der Erde suchten Salomos Anblick, um seine Weisheit zu hören, die ihm Gott ins Herz gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Sie brachten jeder seine Gabe, silberne und goldene Geräte, Gewänder, Waffen und Spezereien, Rosse und Maultiere, Jahr für Jahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Und Salomo besaß 4.000 Gespanne, Rosse und Wagen und 12.000 Reiter. Er legte sie in die Wagenstädte und in die Umgebung des Königs nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Und er war Herrscher über alle Könige vom Strome bis zum Philisterland und bis zur Grenze Ägyptens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Und der König machte das Silber zu Jerusalem den Steinen gleich und die Zedern gleich den Maulbeerbäumen in der Niederung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Man führte Rosse für Salomo aus Ägypten und aus allen Ländern ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Ist nicht Salomos übrige Geschichte, die frühere und die spätere, aufgeschrieben in der Geschichte des Propheten Natan, in der Weissagung des Siloniten Achia und in der Offenbarung des Sehers Jedo an Nebats Sohn Jeroboam?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomo herrschte zu Jerusalem über ganz Israel vierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Alsdann legte sich Salomo zu seinen Vätern, und man begrub ihn in seines Vaters David Stadt. Und sein Sohn Rechabeam ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rechabeam ging nun nach Sichem. Denn ganz Israel ging nach Sichem, ihn zum König zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Davon hörte Nebats Sohn Jeroboam. Er war noch in Ägypten, wohin er vor dem König Salomo geflohen war. Da kehrte Jeroboam aus Ägypten zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Nun sandte man hin und ließ ihn rufen. So kamen Jeroboam und ganz Israel. Sie sprachen zu Rechabeam:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '\"Dein Vater hat uns ein hartes Joch auferlegt. Erleichtere uns deines Vaters harten Dienst und das schwere Joch, das er uns auferlegt, und wir wollen dir dienen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Er sprach zu ihnen: \"Kommt in drei Tagen wieder zu mir!\" Und das Volk ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Da beriet sich König Rechabeam mit den Ältesten, die vor seinem Vater Salomo bei seinen Lebzeiten gestanden, und sprach: \"Wie ratet ihr, dieses Volk zu bescheiden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Sie sprachen zu ihm so: \"Bist du zu diesem Volke gütig, fügst dich ihnen und gibst ihnen freundlichen Bescheid, dann werden sie dir allzeit Diener sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Er aber kehrte sich nicht an den Rat der Alten, die ihn beraten hatten, sondern beriet sich mit den Jungen, die mit ihm aufgewachsen waren und vor ihm standen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Er sprach zu ihnen: \"Wie ratet ihr, dieses Volk zu bescheiden, das zu mir gesprochen: \'Erleichtere das Joch, das uns dein Vater auferlegt hat!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Da sprachen zu ihm die Jungen, die mit ihm aufgewachsen waren: \"Also sprich zu diesem Volke, das zu dir gesprochen: \'Dein Vater hat uns ein schweres Joch auferlegt. Erleichtere du unser Joch!\' So sprich zu ihnen: Mein kleiner Finger ist stärker als meines Vaters Lenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Nun denn! Mein Vater hat euch ein schweres Joch auferlegt. Ich aber will euer Joch noch härter machen. Mein Vater hat euch mit Peitschen gezüchtigt, ich aber will es mit Skorpionen tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Am dritten Tage kamen nun Jeroboam und alles Volk zu Rechabeam, wie der König gesagt hatte: \"Kommt am dritten Tage wieder zu mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Da fuhr der König sie hart an. Denn der König Rechabeam hielt sich nicht an den Rat der Alten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Er sprach nach der Jungen Rat zu ihnen: \"Mein Vater hat euch ein schweres Joch auferlegt. Ich aber mache euer Joch noch schwerer. Mein Vater züchtigte euch mit Peitschen, ich aber will es mit Skorpionen tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Also schenkte der König dem Volke kein Gehör. Denn so war es von Gott bestimmt, damit der Herr sein Wort bestätigte, das er durch den Siloniten Abia zu Nebats Sohn Jeroboam gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Als nun ganz Israel sah, daß der König ihnen kein Gehör schenkte, gab das Volk dem König diesen Bescheid: \"Was haben wir gemein mit David? Wir nehmen keinen Anteil mehr am Isaisohne. Ein jeglicher gehe zu seinen Zelten, Israel! Nun schau nach deinem Hause, David!\" So ging ganz Israel zu seinen Zelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'So blieb Rechabeam nur noch König über die Israeliten, die in Judas Städten wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Da sandte der König Rechabeam den Fronmeister Hadoram hin. Aber die Israeliten steinigten ihn zu Tode. Der König Rechabeam selbst konnte noch rasch auf seinen Wagen springen und nach Jerusalem fliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'So fiel Israel vom Davidshause ab bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Rechabeam kam nun nach Jerusalem. Da sammelte er das Haus Juda und Benjamin, 180.000 erlesene Krieger, zum Kampfe gegen Israel, um das Königtum dem Rechabeam zurückzugewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Da erging Gottes Wort an den Gottesmann Semaja:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '\"Sprich zu dem Sohne Salomos, dem Judakönig Rechabeam, und zu dem ganzen Israel in Juda und in Benjamin:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '\'So spricht der Herr: Zieht nicht hinauf und kämpfet nicht mit euren Brüdern! Ein jeder kehre heim! Durch mich ist es so gefügt.\'\" Sie hörten auf das Wort des Herrn und ließen den Zug gegen Jeroboam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'So blieb Rechabeam in Jerusalem und baute Städte in Juda zu Festungen um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'So baute er Bethlehem, Etam, Tekoa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Betsur, Soko, Adullam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Maresa, Ziph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lakis, Azeka,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Sora, Ajjalon und Hebron, die in Juda und Benjamin lagen, zu festen Städten um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Er verstärkte die Festungen, legte Befehlshaber hinein sowie Vorräte an Speise, Öl und Wein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'und in jede Stadt Schilde und Speere. So machte er sie überaus stark. Und so blieben ihm Juda und Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Die Priester aber und die Leviten in ganz Israel stellten sich bei ihm ein aus all ihren Bezirken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Denn die Leviten verließen ihre Weidetriften und ihren Besitz und gingen nach Juda und Jerusalem; denn Jeroboam mit seinen Söhnen hatte sie aus dem Priesterdienst des Herrn verstoßen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'und sich eigene Priester bestellt für die Höhen, für die Bocksgestalten und für die Kälber, die er gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Ihnen waren aus allen Stämmen Israels solche gefolgt, die ihren Sinn darauf richteten, den Herrn, Israels Gott, aufzusuchen. Sie waren nach Jerusalem gekommen, dem Herrn, dem Gott ihrer Väter, zu opfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'So stärkten sie das Königreich Juda und unterstützten Salomos Sohn Rechabeam drei Jahre lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Rechabeam nahm sich nun zum Weibe Machalat, die Tochter des Davidsohnes Jerimot und der Abichail, die Enkelin des Isaisohnes Eliab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Sie gebar ihm Söhne: Jëus, Semarja und Zaham.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Nach ihr heiratete er Absaloms Enkelin Maaka, und sie gebar ihm Abia, Attai, Ziza und Selomit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rechabeam aber liebte Absaloms Tochter Maaka mehr als alle seine anderen Frauen und Nebenweiber. Er hatte achtzehn Frauen und sechzig Nebenweiber genommen. Er zeugte achtundzwanzig Söhne und sechzig Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Und Rehabeam bestellte Maakas Sohn Abia zum Haupte und Fürsten unter seinen Brüdern, um ihn zum König zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Und er handelte klug und verteilte all seine Söhne in alle Gegenden Judas und Benjamins und in alle festen Städte. Er gab ihnen reichliche Zehrung und gewährte eine Menge Weiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Als aber Rechabeams Königtum fest war und er zu Macht kam, verließ er des Herrn Gesetz, und ganz Israel mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'So zog denn im fünften Regierungsjahr Rechabeams Sisak, der König von Ägypten, gegen Jerusalem, weil sie dem Herrn untreu geworden waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'mit 1.200 Wagen und 60.000 Reitern. Zahllos war das Volk, das mit ihm aus Ägypten zog: Libyer, Troglodyten und Äthiopier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Und er eroberte Judas Festungen und kam bis Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Da kam der Prophet Semaja zu Rechabeam und Judas Fürsten, die sich vor Sisak nach Jerusalem geflüchtet hatten, und sprach zu ihnen: \"So spricht der Herr: \'Mich habt ihr verlassen. So überlasse ich auch euch der Hand des Sisak.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Da demütigten sich Judas Fürsten mit dem König und sprachen: \"Der Herr ist gerecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Als der Herr sah, daß sie sich verdemütigt hatten, erging des Herrn Wort an Semaja: \"Sie haben sich gedemütigt. So will auch ich sie nicht vernichten. Ich gönne ihnen nun ein wenig Heil: Mein Grimm ergießt sich nimmermehr durch Sisak auf Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Doch sollen sie ihm dienstbar werden, daß sie kennenlernen meinen Dienst und den der Königreiche anderer Länder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'So rückte Ägyptens König Sisak gegen Jerusalem und nahm die Schätze im Hause des Herrn und die Schätze des Königshauses. Alles nahm er mit. Er nahm auch die goldenen Schilde, die Salomo gemacht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'König Rechabeam machte an ihrer Statt eherne Schilde und gab sie in die Obhut der Obersten der Läufer, die den Eingang des Königshauses bewachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Sooft der König ins Haus des Herrn ging, kamen die Läufer und trugen sie. Dann brachten sie sie ins Gemach der Läufer zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Weil er sich verdemütigte, ließ der Zorn des Herrn von ihm und vertilgte ihn nicht. Auch an Juda war manches Gute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'König Rechabeam befestigte sich wieder in Jerusalem und regierte weiter. Denn Rechabeam war einundvierzig Jahre alt, als er König wurde, und regierte siebzehn Jahre zu Jerusalem, in der Stadt, die der Herr aus allen Stämmen Israels wählte, seinen Namen hier einzusetzen. Seine Mutter hieß Naama und war eine Ammoniterin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Er tat das Böse. Denn er richtete sein Herz nicht darauf, den Herrn zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Ist nicht Rechabeams Geschichte, die frühere und spätere, in der Geschichte des Propheten Semaja und des Sehers Iddo aufgezeichnet? Die Kämpfe Rechabeams und Jeroboams währten die ganze Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Als sich Rechabeam zu seinen Vätern legte, ward er in der Davidsstadt begraben, und sein Sohn Abia ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Im achtzehnten Jahre des Königs Jeroboam ward Abia König über Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Drei Jahre regierte er zu Jerusalem. Seine Mutter hieß Mikajahu und war Uriels Tochter aus Gibea. Auch zwischen Abia und Jeroboam kam es zum Kriege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abia begann den Kampf mit einem Heer tapferer Krieger, mit 400.000 erlesenen Leuten. Jeroboam aber stellte sich in Schlachtordnung gegen ihn mit 800.000 erlesenen, tapferen Kriegern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Da stellte sich Abia oben auf den Berg Semaraim im Gebirge Ephraim und sprach: \"Hört mich, Jeroboam und ihr, ganz Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Müßt ihr nicht wissen, daß einst der Herr, Gott Israels, dem David das Königtum von Israel für alle Zeit verliehen hat, ihm und seinen Söhnen, als einen Salzbund?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Nun trat des Nebat Sohn Jeroboam auf, der Knecht des Davidsohnes Salomo, um sich gegen seinen Herrn zu empören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Um ihn scharten sich nichtsnutzige und schlimme Leute, und sie empörten sich gegen Salomos Sohn Rechabeam. Rechabeam war noch jung und schwachmütig und konnte ihnen nicht standhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'jetzt aber denkt ihr standzuhalten vor des Herren Königtum, das in der Hand der Söhne Davids liegt? Ihr seid ein großer Haufen zwar; bei euch sind auch die goldenen Kälber, die euch Jeroboam zu Göttern gemacht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Habt ihr denn nicht des Herren Priester ausgetrieben, die Aaronssöhne und Leviten, und euch selber Priester gemacht, so wie die Völker in den Ländern? Wer da mit einem jungen Stier und sieben Widdern kam, sich weihen zu lassen, der ist schon ein Priester der Ungötter geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Der Herr ist aber unser Gott; verlassen haben wir ihn nicht. Als Priester dienen so dem Herrn die Aaronssöhne, und die Leviten sind im Amte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Sie lassen für den Herren jeden Morgen und jeden Abend Brandopfer verrauchen und duftiges Räucherwerk. Sie legen das Brot dem reinen Tische reihenweise auf und zünden auch den goldenen Leuchter mit seinen Lampen jeden Abend an. Denn wir beobachten den Dienst des Herrn, unseres Gottes. Doch ihr habt ihn verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Mit uns ist, an der Spitze, Gott und seine Priester und die Lärmtrompeten, um gegen euch zum Angriff zu blasen. Ihr Söhne Israels! Kämpft doch nicht gegen den Herrn, eurer Väter Gott! Ihr habt kein Glück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Jeroboam aber ließ den Hinterhalt eine Wendung machen, um ihnen in den Rücken zu fallen. So standen sie Juda gegenüber. In seinem Rücken aber war der Hinterhalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Nun wandte Juda sich um. Da hatte es den Kampf vorn und hinten. Da schrien sie zum Herrn, und die Priester stießen in die Hörner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Und die Mannen Judas erhoben ein Kriegsgeschrei. Sowie Judas Mannen aber schrien, schlug Gott Jeroboam und ganz Israel vor Abia und Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Und die Israeliten flohen vor Juda. Und Gott gab sie in seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Und Abia und seine Leute schlugen sie gewaltig. Von Israel fielen 500.000 erlesene Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'So wurden die Israeliten damals gedemütigt. Und Judas Söhne gewannen die Oberhand; denn sie hatten sich auf den Herrn, ihrer Väter Gott, gestützt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abia aber verfolgte Jeroboam und gewann ihm etliche Städte ab, Betel, Jesana und Ephron je mit ihren Tochterorten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jeroboam aber war nicht mehr zu Kraft gekommen in Abias Tagen. Ihn schlug der Herr, und er starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abia aber wurde mächtig, und er nahm sich vierzig Weiber und zeugte zweiundzwanzig Söhne und sechzehn Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Abias übrige Geschichte, sein Wandel und seine Reden, sind in der Auslegung des Propheten Iddo aufgezeichnet. Abia legte sich zu seinen Vätern, und man begrub ihn in der Davidsstadt, und sein Sohn Asa ward König an seiner Statt. In seinen Tagen hatte das Land zwanzig Jahre Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Asa tat, was gut und recht war in des Herrn, seines Gottes, Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Er entfernte die ausländischen Altäre und die Höhen, zertrümmerte die Malsteine und fällte die Ascheren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Er gebot Juda, den Herrn, ihrer Väter Gott, zu suchen und die Lehre und das Gebot zu üben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Er entfernte aus allen Städten Judas die Höhen und die Rauchaltäre. Durch ihn hatte das Reich Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Er baute auch feste Städte in Juda. Denn das Land hatte Ruhe. Niemand führte mit ihm in jenen Jahren Krieg, da der Herr ihm Ruhe verschafft hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Er sprach nun zu Juda: \"Wir wollen diese Städte aufbauen und mit Mauern, Türmen, Toren und Riegeln umgeben. Noch sind wir die Herren des Landes. Denn wir haben den Herrn, unseren Gott, gesucht. Wir haben ihn gesucht, und da schaffte er uns ringsum Ruhe.\" So bauten sie und hatten Gelingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Asa aber hatte ein Heer, das Schild und Speer trug, aus Juda 300.000 Mann und aus Benjamin 280.000 Mann, die Tartschen trugen und den Bogen spannten, lauter tapfere Krieger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Da zog gegen ihn der Kuschite Zerach mit einem Heere von 1.000.000 Mann und dreihundert Wagen. Er kam bis Maresa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Da zog Asa ihm entgegen. Und sie ordneten die Schlacht im Tale nördlich bei Maresa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Da rief Asa zum Herrn, seinem Gott, und sprach: \"Herr! Nur Du kannst helfen im Streite zwischen einem Mächtigen und einem Schwachen. Hilf uns, Herr, unser Gott! Wir stützen uns auf Dich. In Deinem Namen ziehen wir gegen diesen Haufen. Herr! Du bist unser Gott. Laß keinen Sterblichen vor Dir aufkommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Da schlug der Herr die Kuschiten vor Asa und Juda. Und die Kuschiten flohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Asa aber und das Volk bei ihm verfolgten sie bis Gerar. Und von den Kuschiten fielen so viele, daß ihrer keiner mehr am Leben blieb. Denn sie waren vor dem Herrn und vor seinem Heere zerschmettert worden. Jene trugen sehr große Beute davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Und sie schlugen alle Städte rings um Gerar. Denn des Herrn Schrecken war über sie gekommen. So plünderten sie alle Städte. Denn viel Beute war darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Auch die Zelte mit den Herden hatten sie geschlagen, und so führten sie Schafe in Menge und Kamele fort. Dann kehrten sie nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Da kam über Azarja, Odeds Sohn, Gottes Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Er ging zu Asa hinaus und sprach zu ihm: \"Hört mich, du, Asa, und ihr, Leute von ganz Juda und von Benjamin! Der Herr ist dann mit euch, wenn ihr auch mit ihm seid. Sucht ihr ihn auf, läßt er sich von euch finden. Verlaßt ihr ihn, verläßt er euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Viele Tage schon war Israel ohne wahren Gott und ohne die belehrenden Priester und ohne Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Da kehrte es sich in seiner Not zum Herrn, dem Gotte Israels. Sie suchten ihn; er ließ sich finden. Denn große Unruhe war bei allen Bewohnern dieser Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'In jenen Zeiten war kein Frieden für die Aus- und Eingehenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Ein Volk war gegen das andere verhetzt und eine Stadt gegen die andere. Denn Gott hat sie durch allerlei Trübsal verwirrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ihr aber! Seid mutig! Laßt eure Hände nimmer sinken! Für euer Tun gibt\'s einen Lohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Als Asa diese Worte hörte und die Weissagung des Propheten Azarja, bekam er Mut, und so entfernte er die Scheusale aus dem ganzen Lande Juda und Benjamin und aus den Städten, die er auf dem Gebirge Ephraim erobert hatte. Er erneuerte auch des Herrn Altar, der vor der Vorhalle des Herrn stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Dann versammelte er ganz Juda und Benjamin und die Fremdlinge bei ihnen aus Ephraim, Manasse und Simeon. Denn sie waren ihm aus Israel in Menge zugefallen, als sie sahen, daß der Herr, sein Gott, mit ihm war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Sie sammelten sich nun zu Jerusalem im dritten Monat des fünfzehnten Jahres der Regierung des Asa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Und sie opferten dem Herrn an jenem Tage von der Beute, die sie heimgebracht, 700 Rinder und 7.000 Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Dann verpflichteten sie sich, den Herrn, ihrer Väter Gott, aus ihrem ganzen Herzen und ihrer ganzen Seele zu suchen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'und wer den Herrn, Israels Gott, nicht suche, solle getötet werden, klein oder groß, Mann oder Weib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'So schwuren sie dem Herrn mit lautem Jubelrufe und unter Hörner- und Posaunenschall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Und ganz Juda freute sich über den Schwur. Denn sie hatten ihn mit ganzem Herzen geschworen und ihn mit ihrem ganzen Willen gesucht. Und er ließ sich von ihnen finden. So schaffte ihnen der Herr ringsum Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Sogar Maaka, die Mutter des Königs Asa, entsetzte er der Würde einer Herrin, weil sie der Aschera ein Schandbild gemacht hatte. Asa fällte ihr Schandbild, zermalmte und verbrannte es im Kidrontale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Die Höhen aber waren aus Israel nicht verschwunden. Nur Asas Herz war all seine Tage ungeteilt geblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Er brachte seines Vaters heilige Gaben und die seinigen in das Gotteshaus, Silber, Gold und andere Wertsachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Krieg aber war nicht mehr bis zu Asas fünfunddreißigstem Regierungsjahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Im sechsunddreißigsten Jahre Asas zog Israels König Baësa gegen Juda heran. Er baute Rama aus, um niemanden zu Judas König Asa aus- und eingehen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Da nahm Asa Silber und Gold aus den Schatzkammern im Hause des Herrn und im Königshause und sandte es an Arams König Benhadad, der zu Damaskus wohnte, und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '\"Ein Bund sei zwischen mir und dir, wie zwischen deinem Vater und meinem Vater! Hier sende ich dir Silber und Gold. Wohlan, brich deinen Bund mit Israels König Baësa, daß er von mir abziehe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Und Benhadad hörte auf den König Asa und sandte seine Heeresobersten gegen Israels Städte. Sie verheerten Ijjon, Dan und Abelmaim und alle Vorratshäuser in Naphtalis Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Als dies Baësa vernahm, ließ er vom Ausbau Ramas und stellte seine Arbeit ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Da zog der König Asa ganz Juda heran, und sie trugen die Steine und die Balken von Rama fort, das Baësa ausgebaut hatte. Er baute damit Geba und Mispa aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'In jener Zeit war der Seher Chanani zum Judakönige Asa gekommen, und so sprach er zu ihm: \"Weil du dich auf Arams König gestützt hast und nicht auf den Herrn, deinen Gott, deswegen ist das Heer des Israelkönigs deiner Hand entronnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Sind denn die Äthiopier und Libyer nicht zahlreicher gewesen an Wagen und an Reitern? Doch weil du auf den Herrn dich gestützt, hat er sie auch in deine Hand gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Die Augen des Herrn durchspähen ja die ganze Erde, um den zu festigen, dessen Herz ungeteilt für ihn ist. Du hast töricht hierin gehandelt. Von jetzt ab gibt\'s für dich nur Kämpfe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Da zürnte Asa dem Seher und legte ihn ins Stockhaus. Denn er war ihm böse. Asa tötete auch damals etliche aus dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Asas Geschichte, die frühere und die spätere, ist im Buche der Könige von Juda und Israel aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Im neununddreißigsten Regierungsjahr erkrankte Asa an den Füßen, und seine Erkrankung war überaus heftig. Aber auch in dieser Krankheit suchte er nicht den Herrn auf, sondern die Ärzte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Und Asa legte sich zu seinen Vätern, und zwar starb er in seinem einundvierzigsten Regierungsjahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Man begrub ihn in seiner Grabstätte, die er sich in der Davidsstadt angelegt hatte. Man legte ihn auf ein Lager, das man mit Spezereien und sonstigen kunstvoll bereiteten Gewürzen angefüllt hatte. Dann zündete man ihm einen überaus großen Brand an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Sein Sohn Josaphat ward an seiner Statt König. Er aber ward Israel überlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Er legte nämlich in alle festen Städte Judas Mannschaften. Er legte auch Besatzungen in das Land von Juda und in Ephraims Städte, die sein Vater Asa erobert hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Und der Herr war mit Josaphat. Denn er wandelte auf seines Vaters früheren Pfaden. Er suchte die Baale nicht auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sondern den Gott seines Vaters. So wandelte er nach seinen Geboten und nicht nach Israels Tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Daher ließ der Herr unter seiner Hand das Königtum erstarken, und ganz Juda gab Josaphat Geschenke. So hatte er Reichtum und Ehre in Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Und sein Herz ward mutig auf des Herrn Wegen. Er beseitigte auch noch die Höhen und die Ascheren aus Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Im dritten Regierungsjahr sandte er seine Obersten Benchail, Obadja, Zakarja, Netanel und Mikajahu aus, in Judas Städten zu lehren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'mit ihnen die Leviten Semajahu, Netanjahu, Zebadjahu, Asael, Semiramot, Jonatan, Adonijahu und Tobijahu und die Leviten Tob und Adonia und mit diesen die Priester Elisama und Joram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Sie lehrten in Juda. Dabei hatten sie das Buch der Lehre des Herrn bei sich. Sie zogen in allen Städten Judas umher und lehrten unter dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Des Herrn Schrecken aber fiel auf alle Reiche der Länder rings um Juda. Und so stritten sie nicht mit Josaphat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Auch von den Philistern brachten etliche Josaphat Geschenke und eine Last Silber. Auch die Araber brachten ihm an Schafen 7.700 Widder und 7.700 Böcke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'So ward Josaphat immer mächtiger. Er baute in Juda Burgen und Vorratsstädte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'In den Städten Judas besaß er gewaltige Vorräte und in Jerusalem tapfere Kriegsleute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Dies war ihre Amtsordnung nach ihren Familien: Zu Juda gehörten als Oberste von Tausendschaften Adna, der Oberste. Bei ihm waren 300.000 tapfere Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Neben ihm war Jochanan Oberster mit 280.000.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Neben ihm Amasja, Zikris Sohn, der sich freiwillig dem Herrn geweiht hatte, mit 200.000 tapferen Leuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Zu Benjamin gehörte der tapfere Krieger Eljada mit 200.000 Leuten, mit Bogen und Schild gerüstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Neben ihm war Jozabad mit 180.000 Kriegsgerüsteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Diese waren es, die dem König dienten, außer denen, die der König in die festen Städte in ganz Juda gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Und Josaphat besaß Reichtum und Ruhm in Fülle. Und er verschwägerte sich mit Achab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Nach einigen Jahren zog er zu Achab nach Samaria hinab. Da schlachtete Achab für ihn und seine Leute bei ihm Schafe und Rinder in Menge. Dann überredete er ihn, nach Ramot in Gilead zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Achab, Israels König, sprach zum Judakönig Josaphat: \"Ziehst du mit mir gegen Ramot in Gilead?\" Er sprach zu ihm: \"Ich wie du, mein Volk wie dein Volk! Ich ziehe mit dir in den Krieg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Und Josaphat sprach zum König Israels: \"Frag doch jetzt nach dem Worte des Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Da versammelte Israels König die Propheten, 400 Mann, und fragte sie: \"Sollen wir gegen Ramot in Gilead zu Felde ziehen, oder soll ich es lassen?\" Sie sprachen: \"Zieh hin! Gott gibt es in des Königs Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Da sprach Josaphat: \"Ist hier kein Prophet des Herrn mehr, daß wir ihn befragen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Da sprach der König Israels zu Josaphat: \"Noch einer ist da, den Herrn durch ihn zu befragen. Aber ich hasse ihn. Denn er weissagt über mich nichts Gutes, sondern allzeit nur Schlimmes. Das ist Imlas Sohn Mikajehu.\" Da sprach Josaphat: \"Der König sage nicht so!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Da rief der König Israels einen Kämmerer und befahl: \"Hol rasch Mikajehu, Imlas Sohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Der König Israels aber und Josaphat, Judas König, saßen, jeder auf seinem Throne, in Gewändern da, und zwar saßen sie am Eingang des Tores von Samaria in Untergewändern da, und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Da machte sich Sidkijahu, Kenaanas Sohn, eiserne Hörner und sprach: \"So spricht der Herr: \'Mit solchen wirst du die Aramäer stoßen und vernichten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Ebenso weissagten alle anderen Propheten und sprachen: \"Zieh nach Ramot in Gilead und habe Glück! Der Herr gibt es in des Königs Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Der Bote aber, der hingegangen war, Mikajehu zu rufen, sprach zu ihm: \"Die Propheten verheißen dem König einstimmig Gutes. Möchte auch dein Wort einem der Ihrigen gleichen! Sprich nur Gutes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Da sprach Mikajehu: \"So wahr der Herr lebt! Ich rede nur, was mein Gott sagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'So kam er zum König. Und der König sprach zu ihm: \"Mika! sollen wir gen Ramot in Gilead zu Felde ziehen, oder soll ich es lassen?\" Er sprach: \"Zieht hin und habt Glück! Sie werden in eure Hand gegeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Da sprach der König zu ihm: \"Wie oft muß ich dich beschwören, du sollst mir in des Herrn Namen nur Wahrheit verkünden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Da sprach er: \"Ich sehe ganz Israel auf den Bergen zerstreut, wie Schafe ohne Hirten, und der Herr spricht: \'Sie haben keinen Herrn mehr. Sie kehren aber jeder unversehrt nach Hause.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Da sprach der König Israels zu Josaphat: \"Habe ich dir nicht gesagt: \'Er weissagt über mich nie Gutes, sondern nur Schlimmes?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Da sprach er: \"Hört darum das Wort des Herrn. Gesehen habe ich den Herrn auf seinem Throne sitzen, und bei ihm stand das ganze Himmelsheer zur Rechten und zur Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Da sprach der Herr: \'Wer möchte Achab, Israels König, so betören, daß er zu Felde zöge und in Gilead zu Ramot fiele?\' Der eine sagte dies, der andere jenes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Da tritt der Geist hervor und stellt sich vor den Herrn und spricht: \'Ich möchte ihn betören.\' Da fragte ihn der Herr: \'Womit?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Er sprach: \'Ich gehe aus und werde dann zum Lügengeist im Munde aller seiner Seher.\' Er sprach: \'Du wirst betören und es auch vollbringen. Auf! Handle so!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'So hat der Herr nun einen Lügengeist dem Munde all deiner Seher eingegeben. Unheil plant über dich der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Da trat Sidkia, Kenaanas Sohn, herzu, schlug Mikajehu auf die Wange und sprach: \"Auf welchem Wege ist der Geist des Herrn von mir gewichen, um mit dir zu reden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Da sprach Mikajehu: \"Das siehst du an jenem Tage, an dem du kommst, Winkel aufsuchend, um dich zu verstecken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Da sprach der König von Israel: \"Nehmt Mikajehu und bringt ihn zum Stadthauptmann Amon und zum Königssohne Joas');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'und meldet: \'So spricht der König: Werft diesen in den Kerker und nährt ihn kärglich mit Brot und Wasser, bis ich heil heimkomme!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Da sprach Mikajehu: \"Kehrst du wirklich heil heim, dann hat der Herr nicht durch mich gesprochen.\" Und er sprach: \"Hört es, all ihr Leute!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'So zog der König Israels mit Judas König Josaphat gen Ramot in Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Und der König von Israel sprach zu Josaphat davon, verkleidet in den Kampf zu ziehen. \"Du aber behalte deine Kleider an!\" So verkleidete sich der König Israels, und sie zogen in den Kampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Nun befahl der König von Aram den Obersten seiner Streitwagen: \"Kämpft mit niemand anderem, gering oder vornehm als allein mit dem König von Israel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Wie nun die Obersten der Streitwagen den Josaphat erblickten, dachten sie: \"Das ist der König von Israel. Und sie umringten ihn, um ihn anzugreifen.\" Da schrie Josaphat, und der Herr half ihm. Gott lockte sie von ihm weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Wie die Führer der Streitwagen nun merkten, daß es nicht der König von Israel war, ließen sie von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Nun spannte ein Mann von ungefähr den Bogen und traf den König zwischen Ringelgurt und Panzer. Er sprach zum Wagenlenker: \"Kehr um und fahre mich aus dem Getümmel! Denn ich bin verwundet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Aber der Kampf entbrannte an jenem Tage immer stärker, und so blieb der König von Israel, im Wagen gestützt, Aram gegenüber bis zum Abend. Zur Zeit des Sonnenunterganges aber starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Josaphat, Judas König, aber kam heil nach Jerusalem heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Da trat zu ihm der Seher Jehu, Chananis Sohn, und sprach zum König Josaphat: \"Hast du dem Frevler helfen und die lieben müssen, die den Herrn hassen? Darum lastet von dem Herrn ein Zorn auf dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Doch etwas Gutes ist an dir erfunden worden. Du hast ja die Ascheren aus dem Land getilgt und hast dein Herz darauf gerichtet, Gott zu suchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Josaphat aber blieb in Jerusalem. Dann zog er wieder unter das Volk von Beerseba bis zum Gebirge Ephraim und bekehrte sie zum Herrn, ihrer Väter Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Auch bestellte er Richter im Lande in allen festen Städten Judas, Stadt für Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Er sprach zu den Richtern: \"Seht zu, was ihr tut! Denn ihr richtet nicht für Menschen, sondern für den Herrn, und er hilft euch beim Rechtsprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'So sei die Furcht vor dem Herrn auf euch! Seid vorsichtig und genau! Denn bei dem Herrn, unserem Gott, gilt kein Unrecht und kein Ansehen der Person und keine Bestechung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Auch in Jerusalem bestellte Josaphat etliche von den Leviten und Priestern und Stammhäuptern Israels für das Gericht des Herrn und für zweifelhafte Fälle. Sie hatten zu Jerusalem ihren Sitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Er befahl ihnen: \"Also sollt ihr tun in der Furcht des Herrn, in Treue und mit ungeteiltem Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Bei jedem Rechtshandel, der vor euch kommt von euren Brüdern, die in ihren Städten wohnen, zwischen Blutsverwandten, zwischen der Lehre und den Geboten, den Satzungen und den Rechten, sollt ihr sie belehren, daß sie nicht beim Herrn in Schuld kommen! Sonst kommt ein Zorn über euch und eure Brüder. So sollt ihr tun, daß ihr nicht in Schuld kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Der Oberpriester Amarjahu sei euer Vorstand in jeder Angelegenheit des Herrn, ebenso Zebadjahu, Ismaels Sohn, der Fürst des Hauses Juda, in jeder Angelegenheit des Königs! Als Beamte seien euch die Leviten zur Verfügung! Geht also mutig ans Werk! Der Herr sei mit dem Guten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Hernach rückten die Moabiter und die Ammoniter und einige der Mëuniter gegen Josaphat zum Kampfe aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Man kam und meldete Josaphat: \"Ein gewaltiger Haufe zieht von jenseits des Meeres, von Edom, gegen dich heran. Sie sind schon in Chason Tamar, das ist Engedi.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Da fürchtete sich Josaphat und schickte sich an, den Herrn zu suchen. Und er ließ in ganz Juda ein Fasten ausrufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Da sammelte sich Juda, um den Herrn zu suchen. Auch aus allen Städten Judas waren sie gekommen, den Herrn zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Josaphat aber trat in die Gemeinde Judas und Jerusalems im Hause des Herrn vor den neuen Vorhof');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'und sprach: \"Herr, unserer Väter Gott! Bist Du nicht in dem Himmel Gott und herrschest über alle Heidenreiche? In Deiner Hand ist Kraft und Macht, und niemand kann Dir widerstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hast nicht Du, unser Gott, des Landes Insassen vertrieben vor Deinem Volke Israel und dies dem Stamme Deines Freundes Abraham für alle Zeit verliehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Sie siedelten darin und bauten Dir darin ein Heiligtum für Deinen Namen. Sie sprachen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '\'Wenn uns ein Unheil trifft, Schwert, Strafgericht, Pest, Hungersnot, dann treten wir vor dieses Haus, vor Dich. Ist ja in diesem Haus Dein Name! Wir rufen dann zu Dir in unserer Not, daß Du uns hörest und errettest.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Nun sind die Söhne Ammons, Moabs und die von dem Gebirge Sëir da, das zu betreten Du einst Israel verboten, als dieses aus Ägypten kam, sind sie doch ihnen ausgewichen und haben sie nicht ausgetilgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Sie wollen jetzt an uns Vergeltung üben und uns aus dem Besitz vertreiben, den Du zum Erbe uns verliehen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Willst Du sie denn nicht richten, unser Gott? Vor dein gewaltig großen Haufen, der gegen uns heranzieht, sind wir ja machtlos. Wir wissen nimmer, wie wir handeln sollen. Auf Dich allein sehn deshalb unsere Augen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Ganz Juda stand dabei vor dem Herrn, auch seine Kinder, Weiber und Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Da kam über Jachaziel, des Zakarja Sohn und Enkel des Benaja, des Sohnes des Jeiel und Enkels des Mattanja, einen Leviten aus den Asaphsöhnen, der Geist des Herrn inmitten der Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Er sprach: \"Merkt auf, ganz Juda und ihr Bewohner Jerusalems und du, König Josaphat! So spricht der Herr zu euch: \'Vor dem gewaltig großen Haufen fürchtet euch doch nicht! Erschrecket nicht davor! Der Kampf obliegt nicht euch, vielmehr nur Gott.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Zieht morgen gegen sie! Sie rücken auf der Steige von Sis an. Ihr findet sie darum am Ende des Bachtals, östlich von der Wüste Jeruel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Nicht ihr habt hier zu streiten. Paßt auf, steht still! Dann seht ihr die Hilfe des Herrn für euch, für Juda und Jerusalem! Habt keine Furcht! Erschrecket nicht! Zieht morgen gegen sie! Der Herr ist ja mit euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Da neigte Josaphat das Antlitz bis zur Erde, und ganz Juda mit Jerusalems Einwohnern war vor dem Herrn niedergefallen, den Herrn anzubeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Dann erhoben sich die Leviten von den Kehatiter- und Korachsöhnen, um den Herrn, Israels Gott, mit überlauter Stimme zu preisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Am anderen Morgen in der Frühe aber zogen sie nach der Steppe von Tekoa. Bei ihrem Auszug trat Josaphat auf; dann sprach er: \"Hört mich an, Juda und ihr Bewohner Jerusalems! Vertraut auf den Herrn, euren Gott, und ihr habt Bestand! Vertraut auf seine Propheten, und ihr habt Glück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Dann beriet er sich mit dem Volke und bestellte für den Herrn Sänger, die im heiligen Schmucke jubelten. Sie sollten vor den Kampfgerüsteten herziehen und sprechen: \"Dankt dem Herrn; denn ewig währet seine Huld!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Sobald sie aber mit dem Jubelruf und dem Lobpreis begannen, legte der Herr einen Hinterhalt wider die Ammoniter, Moabiter und die vom Gebirge Sëir, die gegen Juda ausgezogen waren. So wurden sie geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Auch die Ammoniter und Moabiter standen gegen die Bewohner des Gebirges Sëir auf, sie zu bannen und zu tilgen. Als sie aber mit den Bewohnern Seïrs fertig waren, griffen sie sich gegenseitig an und vernichteten sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Als nun Juda auf die Höhe kam, nach der Wüste zu, sah es sich nach dem Haufen um. Da lagen lauter Leichen am Boden. Niemand war entronnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Da kam Josaphat mit seinen Leuten, Beute zu machen. Und sie fanden Vieh in Menge, Fahrnis, Kleider und kostbare Geräte. Und sie nahmen sich mehr, als sie tragen konnten. Drei Tage plünderten sie, so groß war die Beute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Am vierten Tage aber versammelten sie sich im Lobpreistale. Denn dort pries man den Herrn. Deshalb nennt man jenen Ort bis auf diesen Tag Lobpreistal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Dann kehrten alle Männer Judas und Jerusalems mit Josaphat an der Spitze um und zogen voller Freude nach Jerusalem; denn der Herr hatte sie über ihre Feinde mit Freude erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'So kamen sie nach Jerusalem mit Harfen, Zithern und Trompeten zum Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Ein Gottesschrecken aber fiel auf alle Reiche der Länder, als sie hörten, daß der Herr mit Israels Feinden gestritten habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Und Josaphats Reich hatte Ruhe. Denn sein Gott schaffte ihm ringsumher Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Josaphat regierte also über Juda. Er war fünfunddreißig Jahre alt, als er König wurde, und regierte fünfundzwanzig Jahre in Jerusalem. Seine Mutter hieß Azuba und war des Silchi Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Er wandelte auf seines Vaters Asa Weg und wich nicht von ihm. Er tat, was dem Herrn gefiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Nur die Höhen waren nicht beseitigt. Und das Volk richtete nicht sein Herz auf den Gott seiner Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Der Rest der Geschichte Josaphats, der früheren und späteren, ist verzeichnet in Jehus, des Chananisohnes, Geschichte, die man in das Buch der Könige Israels eingefügt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Hernach verbündete sich Judas König Josaphat mit Achazja, dem König Israels. Dieser aber lebte und wirkte lasterhaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Er verband sich nun mit ihm, um Schiffe für die Fahrt nach Tarsis zu bauen. Und so machten sie in Esiongeber Schiffe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Da weissagte Dodawahus Sohn Eliezer aus Maresa wider Josaphat und sprach: \"Weil du dich mit Achazja verbündest, wird der Herr dein Werk zertrümmern.\" Und die Schiffe scheiterten und vermochten nicht nach Tarsis zu fahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Josaphat aber legte sich zu seinen Vätern und ward in der Davidsstadt bei seinen Vätern begraben. Sein Sohn Joram ward an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Dieser hatte zu Brüdern die Josaphatsöhne Azarja, Jechiel, Zakarjahu, Mikael und Sephatjahu. Sie alle waren Söhne Josaphats, des Königs von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ihr Vater aber gab ihnen große Geschenke, Silber und Gold, Kleinodien nebst befestigten Städten in Juda. Aber die Königswürde verlieh er Joram. Denn dieser war der Erstgeborene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Joram trat nun die Herrschaft über seines Vaters Reich an. Als er sich stark fühlte, tötete er alle seine Brüder mit dem Schwerte, auch etliche der Fürsten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram war zweiunddreißig Jahre alt, als er König wurde, und regierte acht Jahre in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Er wandelte auf dem Wege der Könige Israels, wie es Achabs Haus getan hatte. Denn er hatte eine Tochter Achabs zum Weib und tat, was dem Herrn mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Aber der Herr wollte nicht das Davidshaus vernichten wegen des Bundes, den er mit David geschlossen, wie er verheißen hatte, ihm und seinen Söhnen allezeit eine Leuchte zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'In seinen Tagen fiel Edom von Juda ab und setzte sich einen eigenen König ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Da zog Joram mit seinen Obersten und mit sämtlichen Wagen hinüber. Dann stand er bei Nacht auf und schlug Edom, das ihn umzingeln wollte, samt den Führern der Streitwagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Dennoch fiel Edom von Juda ab bis auf diesen Tag. Zu jener Zeit fiel auch Libna von ihm ab, weil er den Herrn, seiner Väter Gott, verlassen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Auch machte er Höhen in den Städten Judas und verführte Jerusalems Einwohner zur Untreue und verleitete Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Da kam an ihn ein Schreiben vom Propheten Elias, des Inhalts: \"So spricht der Herr, der Gott deines Vaters David: \'Du wandelst nimmer auf den Wegen deines Vaters Josaphat und nimmer auf des Judakönigs Asa Wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Du gingst den Weg der Könige von Israel, und du verführtest die Bewohner Judas und Jerusalems zur Untreue, so wie das Achabhaus zur Untreue verführte; du hast auch deine Brüder, deine Angehörigen, erschlagen, die besser als du gewesen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'So wird der Herr dein Volk gewaltig schlagen, und deine Söhne, deine Weiber, deine ganze Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Du selbst verfällst in schweres Siechtum, in Krankheit deiner Eingeweide, daß dir über Jahr und Tag die Eingeweide durch die Krankheit heraustreten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Und der Herr erregte gegen Joram die Wut der Philister und Araber, die neben den Äthiopiern wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Sie zogen gegen Juda, brachen ein und führten die ganze Habe im Königshaus weg, dazu seine Söhne und Weiber. So war ihm kein Sohn mehr übriggeblieben als der jüngste seiner Söhne, Joachaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Nach all dem strafte ihn der Herr an seinen Eingeweiden mit unheilbarer Krankheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Nach langer Zeit, gegen Ende des Hochsommers, nach zwei Jahren, traten ihm die Eingeweide infolge seiner Krankheit heraus. Er starb unter bösen Schmerzen. Sein Volk aber veranstaltete ihm keinen Brand, wie den Brand bei seinen Vätern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Er war zweiunddreißig Jahre alt, als er König wurde, und regierte zu Jerusalem acht Jahre. Er ging dahin, von niemand bedauert. Man begrub ihn in der Davidsstadt, aber nicht in den Königsgräbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Jerusalems Einwohner machten nun seinen jüngsten Sohn Achazjahu an seiner Statt zum König. Denn alle älteren hatte die Horde getötet, die mit den Arabern im Zug gekommen waren. So ward Jorams Sohn Achazjahu König von Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazjahu war zweiundzwanzig Jahre alt, als er König wurde, und regierte ein Jahr zu Jerusalem. Seine Mutter hieß Ataljahu und war Omris Enkelin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Darum wandelte er auf den Wegen des Achabhauses. Denn seine Mutter war seine Ratgeberin zum Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'So tat er, was dem Herrn mißfiel, wie die von Achabs Haus. Denn diese wurden nach seines Vaters Tod seine Berater, zu seinem Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Auch darin ihrem Rate folgend, zog er mit Achabs Sohne Joram, dem König Israels, gegen Chazael, den König von Aram, bei Ramot in Gilead in den Kampf. Dabei schlugen die Aramäer den Joram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Er aber kehrte heim, sich in Jezreel von den Wunden heilen zu lassen, die man ihm zu Rama geschlagen, als er mit Arams König Chazael kämpfte. Judas König aber, Achazjahu, Jorams Sohn, ging hinab, Joram, Achabs Sohn, in Jezreel zu besuchen, weil er krank war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Von Gott aber war es zum Untergange Achazjahus bestimmt, daß er zu Joram kam. Als er nämlich kam, ging er zu Jehu, Nimsis Sohn, hinaus. Diesen aber hatte der Herr gesalbt, um Achabs Haus zu vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Als Jehu am Hause Achabs das Strafgericht vollzog, stieß er auf die Fürsten Judas und Achazjahus Brüdersöhne, die Achazjahu bedienten. Und er tötete sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Dann suchte er Achazjahu. Und man ergriff ihn, da er sich in Samaria versteckt hielt. Sie brachten ihn zu Jehu. Er aber ließ ihn töten. Dann begruben sie ihn. Denn sie hatten gesagt: \"Er ist ein Sohn Josaphats, der den Herrn von ganzem Herzen gesucht hat.\" Nun war vom Hause Achazjahus niemand mehr da, der zu regieren vermocht hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Als aber Ataljahu, die Mutter des Achazjahu, erfuhr, daß ihr Sohn tot sei, erhob sie sich und vertilgte das ganze königliche Geblüt des Hauses Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Aber des Königs Tochter Josabat nahm des Achazjahu Sohn Joas verstohlenerweise mitten aus den Königssöhnen, die getötet werden sollten, und steckte ihn mit seiner Amme in die Bettkammer. So verbarg ihn des Königs Joram Tochter Josabat, das Weib des Priesters Jojada, vor Ataljahu, daß sie ihn nicht umbrachte. Sie war des Achazjahu Schwester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Und er blieb im Gotteshause sechs Jahre versteckt. Ataljahu herrschte unterdessen über das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Im siebten Jahre aber ermannte sich Jojada und verbündete sich mit den Obersten der Hundertschaften Azarjahu, Jerochams Sohn, Ismael, Jochanans Sohn, Azarjahu, Obeds Sohn, Maasejahu, Adajas Sohn, und Elisaphat, Zikris Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Diese zogen in Juda umher und sammelten die Leviten aus allen Städten Judas und die Stammhäupter Israels. Dann kamen sie nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Da schloß die ganze Gemeinde im Gotteshause einen Bund wegen des Königs. Er sprach zu ihnen: \"Hier ist der Königssohn. Er soll König sein, wie der Herr den Söhnen Davids verheißen hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Ihr habt folgendes zu tun: Das Drittel, das von euch am Sabbat abzieht, Priester und Leviten, sei Torhüter an den Schwellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Das andere Drittel sei beim Königshause und das weitere Drittel am Tor des Ausgangs! Das ganze Volk aber sei in den Vorhöfen im Hause des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Niemand komme in das Haus des Herrn, als die Priester und die diensttuenden Leviten! Diese dürfen hineingehen; denn sie sind geweiht. Das ganze Volk aber halte die Vorschriften des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Die Leviten sollen nun den König umgeben, jeder mit der Waffe in der Hand! Wer aber das Haus betritt, werde getötet! Jene sollen bei dem König bleiben, wenn er aus- und eingeht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Und die Leviten und ganz Juda taten so, wie der Priester Jojada befohlen. Sie nahmen jeder seine Leute, sowohl die, die am Sabbat abzogen, als auch die am Sabbat aufzogen. Denn der Priester Jojada hatte die Abteilungen nicht entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Der Priester Jojada gab nun den Obersten der Hundertschaften die Speere, Schilde und Tartschen des Königs David, die im Gotteshause lagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Dann stellte er das ganze Volk auf, jeden mit seiner Schleuder in der Hand, von der Südseite des Hauses bis zur Nordseite, bis zum Altar und wieder bis zum Hause rings um den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Dann führten sie den Königssohn vor, legten ihm das Diadem und die Spange an und machten ihn zum König. Und Jojada und seine Söhne salbten ihn und riefen: \"Es lebe der König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Ataljahu aber hörte das Geschrei des Volkes, das tanzend dem König entgegenjubelte. So kam sie zum Volk in das Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Da sah sie, wie der König an seiner Säule am Eingang stand, und beim König waren die Sänger und die Trompeter, und wie alles Volk des Landes fröhlich war und in die Trompeten stieß und wie die Sänger mit den Musikgeräten das Zeichen zum Jubilieren gaben. Da zerriß Ataljahu ihre Kleider und rief: \"Verschwörung, Verschwörung!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Da gebot der Priester Jojada den Obersten der Hundertschaften, den Heeresbefehlshabern und sprach zu ihnen: \"Führt sie durch die Reihen hinaus! Wer ihr folgt, werde mit dem Schwert getötet!\" Denn der Priester hatte gesagt: \"Tötet sie nicht im Hause des Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Da legten sie Hand an sie. Und so kam sie zum Eingang des Roßtores am Königshause. Dort töteten sie sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Hierauf schloß Jojada einen Bund zwischen dem Herrn, dem ganzen Volk und dem König, daß sie ein Volk des Herrn sein wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Dann kam das Volk zum Hause des Baal, riß es ein und zerstörte alle seine Altäre und Bilder. Den Baalspriester Mattan aber töteten sie vor den Altären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Hierauf legte Jojada die Ämter für des Herrn Haus in die Hand der levitischen Priester, die David für das Haus des Herrn abgeteilt hatte, um dem Herrn Brandopfer darzubringen nach der Aufzeichnung in der Lehre des Moses, unter Jubelruf und Gesängen nach Davids Anordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Auch stellte er die Torhüter an die Tore im Hause des Herrn, daß nicht hineinkomme, wer irgendwie unrein sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Dann nahm er die Obersten der Hundertschaften, die Vornehmen und die Beamten im Volke sowie das ganze Volk des Landes und führte den König aus dem Hause des Herrn hinab. Sie kamen durch das obere Tor in das Königshaus und setzten den König auf den königlichen Thron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Alles Volk des Landes war fröhlich; die Stadt aber war ruhig geblieben, obschon sie Ataljahu mit dem Schwert getötet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas war sieben Jahre alt, als er König wurde, und regierte in Jerusalem vierzig Jahre. Seine Mutter hieß Siba und war aus Beerseba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joas tat, was dem Herrn gefiel, solange der Priester Jojada lebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Und Jojada verheiratete ihn mit zwei Weibern, und er zeugte Söhne und Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Danach beschloß Joas, das Haus des Herrn zu erneuern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Er versammelte die Priester und Leviten und sprach zu ihnen: \"Geht in die Städte Judas hinaus und sammelt von ganz Israel Geld, um Jahr für Jahr das Haus eures Gottes auszubessern! Beeilt euch dabei!\" Aber die Leviten beeilten sich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Da berief der König das Oberhaupt Jojada und sprach zu ihm: \"Warum hältst du nicht die Leviten an, daß sie aus Juda und Jerusalem die Steuer einbringen, die Moses, der Diener des Herrn, und die Gemeinde Israel für das Zeugniszelt auferlegt hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Denn Atalja, die ruchlos an den Kindern gehandelt, hatte das Gotteshaus verfallen lassen und sogar alle heiligen Gaben für das Haus des Herrn auf die Baale verwendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Hierauf machte man auf des Königs Befehl eine Lade und stellte sie vor das Tor im Hause des Herrn hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Dann rief man in Juda und Jerusalem aus, man solle dem Herrn die Steuer bringen, die der Diener Gottes, Moses, in der Wüste Israel auferlegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Da freuten sich alle Obersten und das ganze Volk. Sie brachten sie und warfen sie in die Lade, bis sie voll war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Die Lade brachte man jedesmal durch die Leviten vor das Amt des Königs, wenn man sah, daß viel Geld darin war. Dann kamen des Königs Schreiber und der Beamte des obersten Priesters und leerten die Lade. Dann trugen sie sie wieder an ihren Ort. So taten sie Tag für Tag und sammelten Geld in Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Der König und Jojada gaben es den Geschäftsführern bei der Arbeit am Hause des Herrn. Diese dingten Steinhauer und Zimmerleute, um das Haus des Herrn zu erneuern, dazu Eisen- und Kupferschmiede, um des Herrn Haus auszubessern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Die Geschäftsführer sorgten, daß durch sie die Ausbesserung vorwärtsging. So stellten sie das Gotteshaus in seiner Ausdehnung her und setzten es in guten Stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Als sie fertig waren, brachten sie dem König und Jojada das übrige Geld. Daraus machte man Geräte für das Haus des Herrn, Geräte für den Dienst und für die Opferung und Schalen, goldene und silberne Geräte. Solange Jojada lebte, brachte man beständig im Haus des Herrn Brandopfer dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Jojada aber ward alt und lebenssatt, dann starb er. Bei seinem Tode war er hundertdreißig Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Man begrub ihn in der Davidsstadt bei den Königen. Denn er hatte Gutes getan an Israel und gegen Gott und an seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Nach Jojadas Tod aber kamen die Fürsten Judas und warfen sich vor dem König nieder. Und der König hörte auf sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Und so verließen sie das Haus des Herrn, des Gottes ihrer Väter, und dienten den Ascheren und den Bildern. Da kam ein Zorn über Juda und Jerusalem wegen dieser ihrer Versündigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'So schickte er ihnen Propheten, sie zum Herrn zurückzuführen. Und sie verwarnten sie. Aber jene hörten nicht darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Ein Gottesgeist aber hatte den Zakarja eingehüllt, den Sohn des Priesters Jojada. Er trat vor das Volk und sprach zu ihm: \"Also spricht Gott: \'Warum habt ihr des Herrn Gebote übertreten und bringt euch so um euer Glück? Weil ihr den Herrn verlassen, verläßt er euch.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Da scharten sie sich gegen ihn und steinigten ihn auf des Königs Befehl im Vorhof des Hauses des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'König Joas aber hatte nicht mehr der Liebe gedacht, die sein Vater Jojada ihm erwiesen, sondern tötete dessen Sohn. Dieser aber hatte sterbend gesprochen: \"Der Herr sehe es und ahnde es!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Um die Jahreswende zog nun gegen ihn das Heer der Aramäer. Sie kamen nach Juda und Jerusalem und tilgten alle Fürsten des Volkes aus dem Volke und sandten ihre ganze Beute an den König von Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Das Aramäerheer kam zwar mit weniger Mannschaft. Aber der Herr gab in ihre Hand eine überaus große Schar, weil sie den Herrn, ihrer Väter Gott, verlassen hatten. So vollzogen sie an Joas das Strafgericht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Sie zogen nun von ihm ab. Aber sie ließen ihn schwerkrank zurück. Da verschworen sich seine Diener gegen ihn wegen der Blutschuld an dem Sohne des Priesters Jojada und ermordeten ihn auf seinem Lager. So starb er, und man begrub ihn in der Davidsstadt, aber nicht in den Königsgräbern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Die sich gegen ihn verschworen hatten, waren Zabad, der Sohn der Ammoniterin Simat, und Jozabad, der Sohn der Moabiterin Simrit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Seine Söhne und die Schwere des Angriffs gegen ihn, sowie die Bauarbeit am Gotteshause sind in der Auslegung des Buches der Könige aufgezeichnet. An seiner Statt ward sein Sohn Amasjahu König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasjahu wurde mit fünfundzwanzig Jahren König und regierte neunundzwanzig Jahre in Jerusalem. Seine Mutter hieß Joaddan und war von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Er tat, was dem Herrn gefiel, aber nicht mit ganzem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Sobald er aber die Herrschaft fest in der Hand hatte, tötete er seine Diener, die seinen Vater, den König, erschlagen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Doch ihre Söhne tötete er nicht, sondern tat, wie geschrieben steht in der Lehre, in dem Buche Mosis, was der Herr geboten: \"Nicht sollen Väter wegen der Söhne sterben und nicht Söhne wegen der Väter. Jeder soll nur für eigene Schuld sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Darauf versammelte Amasjahu Juda und stellte es familienweise auf, die Obersten über die Tausend- und die Hundertschaften von ganz Juda und Benjamin. Dann musterte er sie von zwanzig Jahren und darüber. Er fand ihrer 300.000 erlesene Krieger, die Speer und Schild führten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Dazu dingte er aus Israel 100.000 tapfere Krieger um hundert Talente Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Aber ein Gottesmann kam zu ihm und sprach: \"König! Israels Heer ziehe nicht mit dir! Denn der Herr ist nicht mit Israel, mit keinem der Söhne Ephraims.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Gehst du daran, dich für den Kampf zu verstärken, so bringt dich Gott vor dem Feinde zu Falle. Denn Gott hat die Macht zu helfen und zu stürzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Da sprach Amasjahu zum Gottesmann: \"Was soll dann mit den hundert Talenten geschehen, die ich der israelitischen Schar gegeben habe?\" Da sprach der Gottesmann: \"Dem Herrn steht es zu, dir weit mehr zu geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Da sonderte Amasjahu die Schar aus, die zu ihm aus Ephraim gekommen war, daß sie wieder heimzogen. Sie zürnten aber heftig auf Juda und zogen heim in hellem Grimm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amasjahu aber hatte Mut gefaßt, und so führte er sein Volk aus, zog in das Salztal und schlug die Söhne Seïrs, 10.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Andere 10.000 aber nahmen die Söhne Judas lebendig gefangen. Sie führten sie auf die Spitze des Felsens und stürzten sie vom Felsengipfel, daß sie alle zerschellten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Die Leute der Schar aber, die Amasjahu zurückgeschickt hatte, daß sie nicht mit ihm in den Kampf zögen, überfielen die Städte Judas, von Samaria bis Bet Choron, erschlugen darin 3.000 Mann und machten reiche Beute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Als Amasjahu von dem Sieg aber die Edomiter zurückkehrte, brachte er die Götter der Söhne Seïrs mit und stellte sie sich als Götter auf. Er pflegte vor ihnen zu beten und ihnen zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Da entbrannte der Zorn des Herrn gegen Amasjahu, und er sandte einen Propheten zu ihm. Dieser sprach zu ihm: \"Warum hast du eines Volkes Götter aufgesucht, die ihr Volk nicht aus deiner Hand gerettet haben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Als er so mit ihm redete, sprach jener zu ihm: \"Haben wir dich zum Ratgeber des Königs bestellt? Hör damit auf! Wozu sollte man dich schlagen müssen?\" Da aber hörte der Prophet auf. Dann aber sprach er: \"Nun weiß ich, daß Gott beschlossen hat, dich zu verderben, weil du dies getan und nicht auf meinen Rat gehört hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Judas König Amasjahu ging nun mit sich zu Rate. Dann sandte er an Israels König Joas, des Joachaz Sohn und Enkel des Jehu, und ließ ihm sagen: \"Wir wollen uns gegenseitig messen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Da ließ Israels König Joas dem Judakönig Amasjahu folgendes entbieten: \"Die Distel auf dem Libanon hat zu der Libanonzeder gesandt und sagen lassen: \'Gib deine Tochter meinem Sohn zum Weibe!\' Aber das Wild auf dem Libanon lief über die Distel und zertrat sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du denkst, du habest Edom geschlagen, so überhebt sich dein Sinn, Größeres zu tun. Bleib jetzt daheim! Wozu forderst du das Unglück heraus, daß du fällst, du und Juda mit dir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Aber Amasjahu hatte nicht darauf hören wollen. Denn solches war von Gott verhängt, um sie in andere Hand zu geben, weil sie die Götter Edoms aufgesucht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Da zog Israels König Joas heran, und sie maßen sich, er und Judas König Amasjahu bei Betsemes in Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Da ward Juda von Israel geschlagen, und sie flohen, jeder in sein Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Den Judakönig Amasjahu, des Joas Sohn und Enkel des Joachaz, nahm Israels König Joas zu Betsemes gefangen, und brachte ihn nach Jerusalem. Dann schlug er eine Bresche in Jerusalems Mauer vom Ephraimtor bis zum Ecktor, vierhundert Ellen lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Mit allem Gold und Silber und allen anderen Wertsachen, die sich im Gotteshause bei Obededom fanden, und mit den Schätzen des königlichen Hauses und den Geiseln kehrte er nach Samaria zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amasjahu, des Joas Sohn und König von Juda, lebte nach dem Tode des Königs von Israel, Joas, des Joachazsohnes, noch fünfzehn Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Ist nicht der Rest der Geschichte Amasjas, die frühere und spätere, im Buche der Könige von Juda und Israel aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Von der Zeit an, wo Amasjahu vom Herrn abgefallen war, verschworen sie sich gegen ihn zu Jerusalem. Er floh nach Lakis. Da sandten sie hinter ihm her nach Lakis und töteten ihn dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Dann luden sie ihn auf Rosse und begruben ihn bei seinen Vätern in der Stadt Davids.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Darauf nahm das ganze Volk Juda den Uzziahu, der erst sechzehn Jahre alt war, und machte ihn zum König an seines Vaters Amasjahu Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Er baute Elot aus und brachte es wieder an Juda, nachdem sich der König zu seinen Vätern gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uzziahu war sechzehn Jahre alt, als er König ward, und regierte zu Jerusalem zweiundfünfzig Jahre. Seine Mutter hieß Jekolja und war aus Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Er tat, was dem Herrn gefiel, ganz wie sein Vater Amasjahu getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Er war dabei, Gott zu suchen, solange Zakarjahu lebte, der ihn in der Gottesfurcht unterwies. Solange er den Herrn suchte, gab ihm Gott Gelingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Er zog aus und stritt mit den Philistern. Er stürzte die Mauern von Gat, Jabne und Asdod. Jabne aber gehörte zu den Städten bei Asdod und bei den Philistern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Und Gott half ihm gegen die Philister und die Araber, die zu Gurbaal wohnten, sowie gegen die Mëuniter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Auch die Ammoniter zahlten Uzziahu Tribut. Sein Ruhm erstreckte sich bis nach Ägypten. Denn er war überaus mächtig geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Uzziahu baute in Jerusalem Türme auf dem Ecktor, dem Taltor und dem Winkel und befestigte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Auch in der Steppe baute er Türme und grub zahlreiche Brunnen. Denn er hatte in der Niederung und Ebene große Herden und Ackerleute und Winzer auf den Bergen und im Fruchtland, weil er den Landbau liebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzziahu hatte auch ein Heer, das Kriegsdienste tat und das in Scharen zu Felde zog. Ihre Musterung durch den Schreiber Jeiel und den Amtmann Maasejahu unter Aufsicht Chananjahus, eines Fürsten des Königs, geschah durch Zählung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Die Gesamtzahl der Stammhäupter der tapferen Helden war 2.600.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Unter ihrem Befehl stand eine Heeresmacht von 307.500, die voller Kraft Kriegsdienste taten, um dem König gegen die Feinde zu helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzzia beschaffte für das ganze Heer Schilde, Speere, Helme, Panzer, Bogen und Schleudersteine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Er machte in Jerusalem künstliche Werke, von Künstlern erdacht, daß sie auf die Türme und Zinnen kämen, um mit Pfeilen und großen Steinen zu schießen. Und sein Ruhm drang in die Ferne. Denn ihm ward wunderbar geholfen, bis er mächtig geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Als er aber mächtig geworden, überhob sich sein Herz zu verderblichem Tun. Er wurde dem Herrn, seinem Gott, untreu. So kam er in den Tempel des Herrn, auf dem Räucheraltar zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Da folgte ihm der Priester Azarja nebst achtzig wackeren Priestern des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Sie traten dem König Uzzia entgegen mit den Worten: \"Uzzia! Dir kommt es nicht zu, dem Herrn zu räuchern, sondern nur den Priestern, Aarons Söhnen, die für das Räuchern geweiht sind. Geh aus dem Heiligtum! Denn du versündigst dich und machst dir vor dem Herrn, Gott, keine Ehre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Uzziahu aber ward zornig. Er hielt dabei ein Rauchfaß zum Räuchern in der Hand. Wie er aber auf die Priester zürnte, brach schon der Aussatz an seiner Stirn hervor, angesichts der Priester im Hause des Herrn neben dem Räucheraltar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Da wandten sich ihm das priesterliche Oberhaupt Azarjahu und alle anderen Priester zu. Er aber war wirklich an der Stirn aussätzig. Da trieben sie ihn schnell von dannen. Auch er selbst stürzte hinaus, da ihn der Herr geschlagen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Der König Uzzia blieb bis zu seinem Todestage aussätzig. Er wohnte als Aussätziger im Hause der Absonderung. Denn er war vom Hause des Herrn ausgeschlossen. Sein Sohn Jotam stand dem Königshause vor und sprach dem Volk des Landes Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Den Rest der Geschichte Uzzias, die frühere und die spätere, beschrieb der Prophet Isaias, des Amos Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Uzzia legte sich zu seinen Vätern. Man begrub ihn bei seinen Vätern auf dem Feld bei der Gruft der Könige. Denn man hatte gesagt: \"Er war aussätzig.\" Sein Sohn Jotam ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotam war fünfundzwanzig Jahre alt, als er König wurde, und regierte sechzehn Jahre in Jerusalem. Seine Mutter hieß Jerusa und war die Tochter des Sadok.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Er tat, was dem Herrn gefiel, ganz wie sein Vater Uzziahu getan. Nur kam er nicht in den Tempel des Herrn. Das Volk aber tat noch immer Böses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Er baute auch das obere Tor am Hause des Herrn; auch an der Ophelmauer baute er viel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Dazu baute er Städte auf dem Gebirge Juda. Und in den Forsten baute er Burgen und Türme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Auch kämpfte er mit dem König der Ammoniter und besiegte sie. In jenem Jahre gaben ihm die Ammoniter hundert Talente Silber, zehntausend Maß Weizen und zehntausend Maß Gerste. Dies lieferten ihm die Ammoniter im zweiten und dritten Jahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'So ward Jotam stark; denn er machte sein Leben zu einem Wandel vor dem Herrn, seinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Der Rest der Geschichte Jotams, all seine Kriege und Handlungen sind im Buche der Könige Israels und Judas aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Er war fünfundzwanzig Jahre alt, als er König wurde, und regierte sechzehn Jahre in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Jotam legte sich zu seinen Vätern. Man begrub ihn in der Davidsstadt. Und sein Sohn Achaz ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz war sechsundzwanzig Jahre alt, als er König wurde, und regierte sechzehn Jahre in Jerusalem. Er tat aber nicht, was dem Herrn gefiel, wie sein Ahn David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Er wandelte auf den Wegen der Könige Israels. Dazu machte er Gußbilder für die Baale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Auch räucherte er im Tale Benhinnom und führte seine Söhne durchs Feuer, gemäß den Greueln der Heiden, die der Herr vor den Israeliten vertrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Er opferte und räucherte auf den Höhen und Hügeln und unter jedem grünen Baume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Da gab ihn der Herr, sein Gott, in die Hand des Königs der Aramäer. Sie schlugen ihn, machten von ihm viele Gefangene und brachten sie nach Damaskus. Auch ward er in die Hand des Königs von Israel gegeben. Dieser schlug ihn gewaltig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekach, Remaljahus Sohn, tötete in Juda an einem Tage 120.000 tapfere Männer; denn sie hatten den Herrn, ihrer Väter Gott, verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Der ephraimitische Held Zikri aber tötete den Königssohn Maasejahu, den Hausvorsteher Azrikam und Elkana, den zweiten nach dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Und die Israeliten führten von ihren Brüdern 200.000 ab, darunter Weiber, Söhne und Töchter; auch machten sie bei ihnen große Beute. Die Beute brachten sie nach Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Dort aber war ein Prophet des Herrn, namens Oded. Er ging dem Heer entgegen, das nach Samaria zurückkam, und sprach zu ihnen: \"Durch des Herrn, des Gottes eurer Väter, Zorn über Juda hat er sie in eure Hand gegeben, so daß ihr unter ihnen getötet habt mit einer Wut, die bis zum Himmel reicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nun denkt ihr daran, die Söhne Judas und Jerusalems für euch zu Sklaven und zu Sklavinnen zu machen. Seid denn nur ihr schuldlos vor dem Herrn, eurem Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Gebt mir nun Gehör und schickt die Gefangenen heim, die ihr von euren Brüdern weggeführt habt! Sonst käme des Herrn grimmer Zorn auf euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Auch einige von den Häuptern der Söhne Ephraims, Azarjahu, des Jochanan Sohn, Berekjahu, Mesillemots Sohn, Chizkiahu, Sallums Sohn, und Amasa, Chadlais Sohn, traten den vom Feldzug Heimkehrenden entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Sie sprachen zu ihnen: \"Bringt die Gefangenen nicht hierher! Sonst fügt ihr zu unserer Verschuldung gegen den Herrn eine neue hinzu zu unseren Sünden und Schulden. Groß würde die Schuld für uns und die Zornesglut über Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Da gab die Vorhut in Gegenwart der Obersten und der ganzen Gemeinde die Gefangenen samt der Beute frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Und die Männer, die mit Namen genannt sind, standen auf und nahmen sich der Gefangenen an. Sie kleideten auch aus der Beute alle Nackten unter ihnen, gaben ihnen Kleider und Schuhe und zu essen und zu trinken, salbten sie und führten alle Müden auf Eseln und brachten sie nach der Palmenstadt Jericho zu ihren Brüdern. Dann kehrten sie nach Samaria zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'In jener Zeit schickte der König Achaz zu dem König Assyriens, daß er ihm helfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Denn wieder kamen die Edomiter, schlugen Juda und machten Gefangene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Auch die Philister fielen in die Städte der Niederung und in das Südland von Juda ein und eroberten Betsemes, Ajjalon, Gederot, sowie Soko, Timna und Gimzo je mit ihren Tochterorten und siedelten darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Denn der Herr demütigte Juda wegen Achaz, des Königs von Israel, weil er Juda zügellos gemacht hatte und gegen den Herrn treulos geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Da kam der Assyrerkönig Tiglat-Pilneser zu ihm. Aber er bedrängte ihn, hatte er ihm doch nicht geholfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Achaz hatte zwar das Haus des Herrn, das Königshaus und die Häuser der Fürsten geleert und er gab es dem Assyrerkönig. Aber Hilfe ward ihm nicht zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Aber zu der Zeit, wo man ihn bedrängte, ward er dem Herrn noch mehr untreu. So war König Achaz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Er opferte den damaszenischen Göttern, die ihn besiegt hatten. Er sprach: \"Die Götter der Aramäerkönige halfen ihnen. Auch ich will ihnen opfern, und sie werden mir helfen.\" Aber sie waren ihm und ganz Israel nur zum Falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Achaz raffte nun die Geräte des Gotteshauses zusammen, zerschlug des Gotteshauses Geräte, schloß die Türen des Gotteshauses und machte sich an jeder Ecke Jerusalems Altäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Auch in jeder Stadt Judas machte er Höhen, um anderen Göttern zu räuchern. So kränkte er den Herrn, den Gott seiner Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Der Rest der Geschichte, all seine Handlungen, die früheren und späteren, sind im Buche der Könige Judas und Israels aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Achaz legte sich zu seinen Vätern. Man begrub ihn in der Stadt zu Jerusalem. Denn man brachte ihn nicht in die Gräber der Könige Israels. Sein Sohn Ezechias ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezechias ward mit fünfundzwanzig Jahren König und regierte in Jerusalem neunundzwanzig Jahre. Seine Mutter hieß Abia und war die Tochter des Zakarja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Er tat, was dem Herrn gefiel, ganz wie sein Ahnherr David getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Er öffnete im ersten Regierungsjahr, gleich im ersten Monat, die Tore am Hause des Herrn; dann machte er sie fest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Er ließ die Priester und Leviten kommen und versammelte sie auf dem freien Platz im Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Er sprach zu ihnen: \"Hört mich an, ihr Leviten! Heiligt euch jetzt! Heiligt auch das Haus des Herrn, des Gottes eurer Väter, und schafft den Unrat aus dem Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Denn unsere Väter sind treulos geworden und haben getan, was dem Herrn mißfiel, und so verließen sie ihn. Sie wandten ihr Antlitz von des Herrn Wohnung und zeigen ihr den Rücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Auch haben sie die Tore der Vorhalle geschlossen; dann löschten sie die Lampen; Räucherwerk haben sie nicht mehr angezündet und im Heiligtum dem Gott Israels kein Brandopfer mehr dargebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'So kam des Herrn Zorn über Juda und Jerusalem. Er machte sie zu einem Schreckbild und Gegenstand des Entsetzens und Gezisches, wie ihr mit eigenen Augen sehet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Nun! Unsere Väter sind durch das Schwert gefallen, und unsere Söhne, Töchter und Weiber sind deshalb gefangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Jetzt habe ich im Sinn, mit dem Herrn, Israels Gott, einen Bund zu schließen, auf daß sein grimmer Zorn von uns lasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Zeigt euch jetzt nicht lässig, meine Söhne! Denn euch hat der Herr erwählt, um vor ihm zu stehen, ihm zu dienen und zu räuchern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Da erhoben sich die Leviten Machat, Amasais Sohn, und Joel, Azarjahus Sohn, von den Kehatitersöhnen, von den Merarisöhnen Kis, Abdis Sohn, und Azarjahu, Jehallelels Sohn, von den Gersuniten Joach, Zimmas Sohn, und Eden, Joachs Sohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'von den Söhnen Elisaphans Simri und Jeiel, von den Asaphsöhnen Zakarjahu und Mattanjahu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'von den Hemansöhnen Jechiel und Simi und von den Söhnen Jedutuns Semaja und Uzziel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Sie versammelten ihre Brüder und heiligten sich. Dann kamen sie, nach des Königs Befehl, auf das Wort des Herrn, das Haus des Herrn zu reinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Die Priester gingen in das Innere im Haus des Herrn, es zu reinigen. Sie schafften alles Unreine, das sie in des Herrn Tempel gefunden, in den Vorhof am Hause des Herrn. Die Leviten nahmen es in Empfang und schafften es an den Kidronbach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Sie begannen am ersten Tage des ersten Monats mit der Weihe, und am achten Tage des Monats waren sie bis zu des Herrn Vorhalle gelangt. In weiteren acht Tagen weihten sie das Haus des Herrn, und am sechzehnten Tage des ersten Monats waren sie fertig geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Dann kamen sie zu König Ezechias hinein und sprachen: \"Wir haben das ganze Haus des Herrn gereinigt, auch den Brandopferaltar und all seine Geräte, sowie den Schaubrottisch und all seine Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Alle Geräte, die der König Achaz während seiner Regierung in seiner Untreue beiseite geworfen, haben wir wieder aufgestellt und sie eingeweiht. Sie stehen jetzt vor dem Altar des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Da versammelte der König Ezechias in aller Frühe die Fürsten der Stadt und ging hinauf zum Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Sie brachten sieben Farren, sieben Widder und sieben Lämmer, dazu sieben Ziegenböcke zum Sündopfer für das Königtum, für das Heiligtum und für Juda. Er befahl den priesterlichen Aaronssöhnen, sie auf des Herrn Altar zu opfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Da schlachteten sie die Rinder. Die Priester fingen das Blut auf und sprengten es an den Altar. Sodann schlachteten sie die Widder und sprengten das Blut an den Altar. Hierauf schlachteten sie die Lämmer und sprengten das Blut an den Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Dann brachten sie die Sündopferböcke vor den König und die Gemeinde, und sie legten ihnen ihre Hände auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Die Priester schlachteten sie und brachten ihr Blut zur Entsündigung an den Altar, um für ganz Israel Sühne zu schaffen. Denn für ganz Israel hatte der König das Brand- und das Sündopfer bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Hierauf stellte er die Leviten am Hause des Herrn auf mit Zimbeln, Harfen und Zithern, nach dem Befehle Davids, des königlichen Sehers Gad und des Propheten Natan. Denn von dem Herrn war das Gebot durch seine Propheten ergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'So standen die Leviten mit Davids Musikgeräten da und die Priester mit Trompeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ezechias gebot nun, das Brandopfer auf den Altar zu bringen. Als das Opfern anfing, begannen der Gesang auf den Herrn und die Trompeten, und zwar unter Begleitung der Musikgeräte Davids, des Königs von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Die ganze Gemeinde aber warf sich nieder. Der Gesang erklang, und die Trompeten schmetterten. Das alles, bis das Brandopfer fertig war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Als man mit dem Opfern fertig war, knieten der König und alle bei ihm und beteten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Dann ließ der König Ezechias samt den Obersten die Leviten dem Herrn lobsingen mit den Gesängen Davids und des Sehers Asaph. Da sangen sie mit Freude den Lobpreis, neigten sich und beteten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Dann hob Ezechias an und sprach: \"Opfert nunmehr reichlich dem Herrn! Kommt herbei und bringt zum Hause des Herrn Schlacht- und Dankopfer!\" Da brachte die Gemeinde Schlacht- und Dankopfer und jeder Edelgesinnte Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Die Zahl der Brandopfer, die die Gemeinde darbrachte, betrug siebzig Rinder, hundert Widder und zweihundert Lämmer, diese alle als Brandopfer für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Die heiligen Gaben betrugen sechshundert Rinder und dreitausend Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Nur waren der Priester zuwenig, und sie konnten nicht allen Brandopfern die Haut abziehen. Da halfen ihnen ihre Brüder, die Leviten, bis die Arbeit fertig war und bis sich die Priester heiligen konnten. Denn die Leviten waren redlich bestrebt, sich mehr zu heiligen als die Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Aber es waren auch der Brandopfer sehr viele samt den Fettstücken der Mahlopfer und den Trankopfern für die Brandopfer. So war der Dienst am Hause des Herrn geordnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Ezechias aber und das ganze Volk freuten sich über das, was Gott dem Volke bereitet hatte; denn die Sache war unerwartet geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Hierauf sandte Ezechias an ganz Israel und Juda. Auch schrieb er Briefe an Ephraim und Manasse, sie möchten zum Hause des Herrn nach Jerusalem kommen, das Passah dem Herrn, Israels Gott, zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Und der König beschloß mit seinen Fürsten und der ganzen Gemeinde in Jerusalem, das Passah im zweiten Monat zu feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Denn sie hatten es nicht rechtzeitig halten können, weil sich die Priester nicht genügend geheiligt hatten. Auch das Volk war noch nicht in Jerusalem versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Da gefiel es dem König und der ganzen Gemeinde, festzusetzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'daß in ganz Israel von Beerseba bis Dan verkündet werde, man solle kommen, dem Herrn, Israels Gott, zu Jerusalem Passah zu halten. Denn sie hatten es nicht gebührend nach Vorschrift gehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Da durchzogen die Läufer mit den Briefen von der Hand des Königs und seiner Fürsten ganz Israel und Juda und kündeten auf des Königs Befehl: \"Ihr Israeliten! Bekehrt euch zu dem Herrn, dem Gott Abrahams, Isaaks und Israels, auf daß er sich zu den Entronnenen wende, die euch aus der Hand der Assyrerkönige geblieben sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Seid nicht wie eure Väter und Brüder, die dem Herrn, dem Gott ihrer Väter, untreu geworden waren, so daß er sie zum Entsetzen machte, wie ihr seht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Seid jetzt nicht halsstarrig wie eure Väter! Reicht dem Herrn die Hand und kommt in sein Heiligtum, das er für immer geweiht hat. Dient dem Herrn, eurem Gott, daß sich sein grimmer Zorn von euch wende!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Denn, kehrt ihr zum Herrn, so finden eure Brüder und Söhne Erbarmen bei ihren Kerkermeistern und dürfen wieder in ihr Land kehren. Denn gnädig und barmherzig ist der Herr, euer Gott. Er verbirgt nicht vor euch sein Antlitz, wenn ihr zu ihm umkehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Die Läufer zogen nun von Stadt zu Stadt durch das Land Ephraim und Manasse und bis nach Zabulon. Aber man verlachte und verspottete sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Nur ein paar Männer von Asser, Manasse und Zabulon hatten sich gedemütigt, und so kamen sie nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Aber über Juda kam Gottes Hand. Er gab ihnen einen Sinn, das Gebot des Königs und der Fürsten nach des Herrn Wort zu befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'So versammelte sich zu Jerusalem zahlreiches Volk, das Fest der ungesäuerten Brote im zweiten Monat zu feiern, eine überaus große Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Sie machten sich auf und beseitigten die Altäre zu Jerusalem. Auch alle Räucheraltäre beseitigten sie, dann warfen sie sie in den Kidronbach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Dann schlachteten sie das Passah am vierzehnten Tage des zweiten Monats. Die Priester aber und die Leviten schämten sich. Und so heiligten sie sich und brachten Brandopfer zum Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Dann standen sie auf ihrer Stelle nach ihrer Vorschrift, nach der Lehre des Gottesmannes Moses. Und die Priester sprengten das Blut aus der Hand der Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Denn viele in der Gemeinde hatten sich nicht geheiligt. So besorgten die Leviten das Schlachten der Passahlämmer für jeden Unreinen, um sie dem Herrn zu weihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Denn die große Menge des Volkes, viele aus Ephraim, Manasse, Issakar und Zabulon, hatten sich nicht gereinigt und das Passah nicht nach Vorschrift verzehrt. Ezechias aber hatte also für sie gebetet: \"Verzeihen möge jeglichem der Herr, der Gütige,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'wenn er den Sinn darauf gerichtet, Gott, den Herrn, und seiner Väter Gott, zu suchen, auch ohne Reinheit für das Heiligtum!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Und der Herr erhörte Ezechias und verschonte das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'So feierten die Israeliten zu Jerusalem das Fest der ungesäuerten Brote sieben Tage mit großer Freude. Tag für Tag priesen die Leviten und Priester den Herrn mit aller Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ezechias aber sprach zum Herzen aller Leviten, die sich dem Herrn gegenüber gut benahmen. Und sie hielten das Fest sieben Tage durch. Sie schlachteten Mahlopfer und priesen den Herrn, ihrer Väter Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Und die ganze Gemeinde beschloß, noch weitere sieben Tage zu feiern. Und so feierten sie sieben Tage ein Freudenfest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Denn Ezechias, Judas König, spendete der Gemeinde tausend Farren und siebentausend Schafe als Gabe; auch die Fürsten spendeten der Gemeinde tausend Farren und zehntausend Schafe. Und die Priester heiligten sich in Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'So freute sich die ganze Gemeinde Judas, die Priester und Leviten, ebenso die ganze Gemeinde derer, die aus dem Land Israel gekommen waren, sowie die Fremdlinge, die aus dem Land Israel kamen und die in Juda wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Große Freude war in Jerusalem. Denn seit den Tagen Salomos, des Davidsohnes und Königs von Israel, war derartiges nicht mehr in Jerusalem gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Die levitischen Priester standen auf und segneten das Volk. Und ihre Stimme ward erhört. Ihr Gebet kam zu seinem heiligen Wohnsitz, zum Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Als dies alles beendet war, zog ganz Israel, das sich eingefunden, nach den Städten Judas, zertrümmerte die Steinmale, fällte die Ascheren und zerstörte die Höhen und Altäre in ganz Juda und Benjamin, Ephraim und Manasse, bis sie vernichtet waren. Dann kehrten alle Israeliten heim, jeder in seinen Erbsitz, in ihre Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezechias aber bestellte die Abteilungen der Priester und Leviten, für Brand- und Mahlopfer, um Dienste zu tun, zu danken und zu loben in den Toren als Dienst für den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Des Königs Beitrag aus seinem Besitz diente für Brandopfer, für Morgen- und Abendbrandopfer und für Brandopfer an den Sabbaten, Neumonden und Festen nach der Vorschrift in der Lehre des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Er gebot auch dem Volke, den Bewohnern Jerusalems, ihren Teil den Priestern und Leviten zu geben, damit sie festhielten an der Lehre des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Als dies bekannt wurde, brachten die Israeliten den ersten Abhub von Getreide, Most, Öl, Honig und allem Feldertrag. Sie brachten den Zehnten von allem in Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Die Söhne Israels wie die Judas, die in anderen Städten Judas wohnten, brachten den Zehnten von Rindern und Schafen sowie den Zehnten der Weihegaben, die dem Herrn, ihrem Gott, geweiht wurden. Sie gaben es haufenweise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'im dritten Monat begannen sie die Haufen zu legen, und erst im siebten Monat waren sie damit fertig geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Da kam Ezechias mit den Fürsten und besah die Haufen. Da priesen sie den Herrn und sein Volk Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Ezechias befragte nun die Priester und Leviten über die Haufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Da sprach zu ihm der Priester Azarja, das Oberhaupt des Hauses Sadok. Er sagte: \"Seit man anfing, die Gabe in das Haus des Herrn zu bringen, haben wir gegessen und sind satt geworden, und viel ist noch übriggeblieben. Denn der Herr hat sein Volk gesegnet, und so ist diese Masse übrig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Da ließ Ezechias im Hause des Herrn Zellen herrichten. Als man sie hergerichtet hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'brachte man die Gabe getreulich hinein, den Zehnten und die Weihegaben. Der Levite Konanjahu führte darüber die Aufsicht, und sein Bruder Simei war der zweite im Range.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jechiel, Azazjahu, Nachat, Asael, Jerimot, Jozabad, Eliel, Ismakjahu, Machat und Benajahu waren Gehilfen des Konanjahu und seines Bruders Simei laut Anordnung des Königs Ezechias und Azarjahus, des Fürsten im Gotteshause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kore, Imnas Sohn, der Levite und Torhüter gen Osten, beaufsichtigte die freiwilligen Gottesgaben, um die Gabe für den Herrn und die hochheiligen Gaben abliefern zu können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Unter seiner Aufsicht standen Eden, Minjamin, Jesua, Semajahu, Amarjahu und Sekanjahu. Sie sollten in den Priesterstädten gewissenhaft ihren Brüdern ihren Teil geben, abteilungsweise, den Alten und den Jungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Außerdem trug man in das Geschlechtsregister die Mannspersonen ein, von den dreijährigen und darüber, alle, die zum Hause des Herrn kamen zu ihrem täglichen Dienste, je nach ihren Ämtern und Abteilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Auch die Priester trug man in das Geschlechtsregister ein nach ihren Stammhäusern, ebenso die Leviten, von den Zwanzigjährigen an und darüber, nach ihren Ämtern und Abteilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Man verzeichnete sie dabei mit all ihren kleinen Kindern, Weibern, Söhnen und Töchtern in jeder Gemeinde. Denn diese wurden durch das lebenslängliche Amt jener geheiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Die Aaronssöhne, die Priester, hatten auf den Feldern der Weidetriften ihrer Städte für jede Stadt Leute, die mit Namen genannt waren. Sie mußten jedem Männlichen unter den Priestern seinen Teil geben, ebenso jedem eingetragenen Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'So tat Ezechias in ganz Juda. Er tat das Gute, Rechte und Wahre vor dem Herrn, seinem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Bei allem Tun, das er für den Dienst am Gotteshaus, für die Lehre und das Gebot, seinen Gott zu suchen, unternahm, verfuhr er mit ganzem Herzen und hatte Glück dabei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Nach diesen Begebnissen und solcher Treue kam der Assyrerkönig Sanherib. Er kam nach Juda und belagerte die festen Städte. Er gedachte, sie für sich zu erobern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Als Ezechias sah, daß Sanherib gekommen war und Jerusalem erobern wollte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'beschloß er, mit seinen Obersten und Kriegern die Quellwasser außerhalb der Stadt zu verstopfen. Und sie stimmten ihm bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Da sammelte sich viel Volk und verstopfte alle Quellen und den Bach, der die Gegend durchfließt. Sie sagten: \"Wozu sollen die Assyrerkönige kommen und soviel Wasser finden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Dann rüstete er sich. Er baute die ganze geborstene Mauer auf, errichtete darauf Türme und draußen die andere Mauer. Dann befestigte er die Bastei in der Davidsstadt und machte Schleudern und Schilde in Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Dann setzte er Kriegsoberste über das Volk. Und er versammelte sie zu sich auf den Platz am Stadttore. Er redete ihnen freundlich zu und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '\"Seid mutig und stark! Seid getrost! Erschreckt nicht vor dem Assyrerkönig und nicht vor dem ganzen Haufen, den er mit sich führt! Denn mit uns ist ein Größerer als mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Mit ihm ist ein fleischerner Arm. Mit uns aber der Herr, unser Gott, um uns zu helfen und unsere Kriege zu führen.\" Da verließ sich das Volk auf die Worte des Judakönigs Ezechias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Später hatte der Assyrerkönig Sanherib seine Knechte nach Jerusalem gesandt. Er selbst aber stand vor Lakis mit seiner ganzen Macht. So sandte er zu dem Judakönig Ezechias und zu ganz Juda in Jerusalem und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '\"So spricht Sanherib, Assyriens König: \'Worauf vertraut ihr, daß ihr euch in Jerusalem belagern lasset?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Verführt euch nicht Ezechias und läßt euch vor Hunger und Durst sterben, wenn er spricht: \"Der Herr, unser Gott, rettet uns aus des Assyrerkönigs Hand?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Hat nicht dieser Ezechias seine Höhen und Altäre beseitigt und zu Juda und Jerusalem gesprochen: \"Ihr sollt vor einem Altar anbeten und nur auf ihm räuchern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Wißt ihr nicht, was ich und meine Väter allen Völkern der Erde getan haben? Haben der Heiden Götter in den Ländern ihr Land aus meiner Hand retten können?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Wer von all den Göttern dieser Heiden, die meine Väter vertilgten, hat sein Volk aus meiner Hand gerettet? Da sollte euer Gott euch aus meiner Hand retten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'So betöre euch jetzt nicht Ezechias und verführe euch nicht auf solche Art! Glaubt ihm nicht! Denn kein Gott irgendeines Volkes oder Reiches konnte sein Volk aus meiner und meiner Väter Hand retten. Auch will euer Gott euch aus meiner Hand gar nicht retten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Solches und noch mehr redeten seine Knechte wider Gott, den Herrn, und gegen seinen Diener Ezechias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Auch einen Brief schrieb er, um den Herrn, Israels Gott zu lästern und wider ihn zu reden: \"Sowenig in den Ländern die Heidengötter ihr Volk aus meiner Hand retteten, ebensowenig kann des Ezechias Gott sein Volk aus meiner Hand retten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Sie riefen auch mit lauter Stimme auf jüdisch zum Volke Jerusalems auf der Mauer, um es in Furcht und Schrecken zu setzen und um so die Stadt zu erobern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Sie redeten von dem Gott Jerusalems wie von der Erdenvölker Göttern, dem Werk von Menschenhänden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Nun beteten der König Ezechias und der Prophet Isaias, des Amos Sohn, dieserhalb und schrien zum Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Da sandte der Herr einen Engel und tilgte alle Krieger, Heerführer und Obersten im Lager des Assyrerkönigs. Schmachbedeckt kehrte er in sein Land. Als er in das Haus seines Gottes ging, fällten ihn einige leibliche Abkömmlinge dort durch das Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'So rettete der Herr den Ezechias und Jerusalems Einwohner aus der Hand des Assyrerkönigs Sanherib und aus der Hand aller anderen und gab ihnen ringsum Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Viele brachten dem Herrn Gaben nach Jerusalem und dem Judakönig Ezechias Kleinodien, und er wurde danach in aller Heiden Augen hochangesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Zu jener Zeit wurde Ezechias todkrank. Da betete er zum Herrn. Und er sprach mit ihm und gab ihm ein Wunderzeichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Aber Ezechias vergalt nicht die Wohltat, die ihm widerfahren war. Denn er ward hochmütig. Darum kam grimmer Zorn über ihn und über Juda und Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Dann erst demütigte sich Ezechias in seinem Hochmut, er und Jerusalems Bewohner. So war des Herrn grimmer Zorn nicht über sie in Ezechias Tagen gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ezechias besaß aber sehr großen Reichtum und Prunk. Er legte sich Schatzkammern an für Silber, Gold, Edelsteine, Spezereien, Schilde und allerlei kostbare Geräte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'und Speicher für den Ertrag an Korn, Wein und Öl, Ställe für allerlei Vieh und Scharen tüchtiger Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Er beschaffte sich Ställe, dazu großen Besitz an Schafen und Rindern. Denn Gott gab ihm überaus viel Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Derselbe Ezechias war es auch, der den oberen Ausfluß der Gewässer des Gichon verstopfte und sie westwärts in die Davidsstadt hinableitete. Ezechias hatte bei all seinem Tun Glück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Nur bei den Gesandten der Babelfürsten, die sie zu ihm geschickt hatten, nach dem Wunder, das im Lande geschehen, zu fragen, verließ ihn Gott, um ihn zu prüfen und sein ganzes Herz zu erkunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Der Rest der Geschichte des Ezechias und seine tapferen Taten sind in dem Gesicht des Propheten Isaias, des Amossohnes, im Buch der Könige von Juda und Israel aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ezechias legte sich zu seinen Vätern, und man begrub ihn am Aufstieg zu den Gräbern der Davidsöhne. Ganz Juda und Jerusalems Einwohner erwiesen ihm bei seinem Tode Ehre. Sein Sohn Manasse ward König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse war zwölf Jahre alt, als er König wurde, und regierte fünfundzwanzig Jahre zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Er tat, was dem Herrn mißfiel, nach den Greueln der Heiden, die der Herr vor den Israeliten vertrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Er baute die Höhen wieder, die sein Vater Ezechias zertrümmert hatte, errichtete Altäre für die Baale und machte Ascheren. Auch betete er das ganze Himmelsheer an und diente ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Ferner baute er Altäre in des Herrn Haus, von denen der Herr gesagt hatte: \"Mein Name wird allzeit in Jerusalem sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Dann baute er Altäre für das ganze Himmelsheer in beiden Vorhöfen im Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Derselbe führte seine Söhne im Hinnomssohntale durchs Feuer, trieb Zauberei, Wahrsagerei und sonstige geheime Künste und bestellte Totenbeschwörer und Zeichendeuter. So tat er vieles, was dem Herrn mißfiel, um ihn zu kränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Das Schnitzbild, das er machte, stellte er im Gotteshause auf, von dem Gott zu David und seinem Sohn Salomo gesprochen: \"In dieses Haus und in Jerusalem, das ich aus allen Stämmen Israels erwählt, will ich für ewig meinen Namen setzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Und ich versetze nicht mehr Israels Fuß vom Boden, auf den ich eure Väter hingestellt, vorausgesetzt, daß sie sich auch bemühen, all das, was ich ihnen geboten, zu tun, gemäß der ganzen Lehre Mosis und seinen Satzungen und Rechten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Doch Manasse verführte Juda und Jerusalems Einwohner, daß sie Böses taten, mehr als die Heiden, die der Herr vor den Israeliten vertilgt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Und der Herr redete zu Manasse und seinem Volk. Aber sie achteten nicht darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Da brachte der Herr über sie die Heerführer des Assyrerkönigs. Diese fingen Manasse mit Haken, legten ihn in Ketten und führten ihn nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Als er in Not gekommen war, suchte er den Herrn, seinen Gott, zu begütigen, und so demütigte er sich tief vor dem Gott seiner Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Er betete zu ihm. Da ließ er sich erbitten. Und er erhörte sein Flehen und brachte ihn wieder nach Jerusalem zurück in sein Reich. Da erkannte Manasse, daß der Herr Gott sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Danach baute er eine äußere Mauer an der Davidsstadt westlich vom Gichon im Tale und bis da, wo man ins Fischtor geht, und rings um den Ophel. Er machte sie sehr hoch. Auch legte er Heeresoberste in alle festen Städte Judas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Dann beseitigte er die fremden Götter und das Standbild aus dem Hause des Herrn, ebenso alle Altäre, die er auf dem Berge des Hauses des Herrn und in Jerusalem erbaut hatte. Er warf sie zur Stadt hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Den Altar des Herrn aber richtete er wieder auf und opferte auf ihm Mahl- und Lobopfer. Er befahl Juda, dem Herrn, Israels Gott, zu dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Doch das Volk opferte noch auf den Höhen, wiewohl nur dem Herrn, ihrem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Der Rest der Geschichte Manasses und sein Gebet zu seinem Gott, wie die Worte der Seher, die zu ihm im Namen des Herrn, des Gottes Israels, gesprochen, stehen in der Geschichte der Könige Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sein Gebet und seine Erhörung, all seine Sünde und Untreue, und die Orte, wo er Höhen gebaut und die Ascheren mit Schnitzbildern aufgestellt, bevor er sich demütigte, sind aufgezeichnet in der Geschichte seiner Seher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Und Manasse legte sich zu seinen Vätern. Man begrub ihn in seinem Hause, und sein Sohn Amon wurde König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon war zweiundzwanzig Jahre alt, als er König wurde, und regierte in Jerusalem zwei Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Er tat, was dem Herrn mißfiel, wie sein Vater Manasse getan. Amon opferte allen Schnitzbildern, die sein Vater gemacht, und diente ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Aber er demütigte sich nicht vor dem Herrn, wie sich sein Vater Manasse verdemütigt hatte, sondern dieser Amon machte die Schuld noch größer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Da verschworen sich seine Diener gegen ihn und töteten ihn in seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Doch das Landvolk erschlug alle, die sich gegen den König Amon verschworen hatten. Dann machte das Landvolk seinen Sohn Josias zum König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias war acht Jahre alt, als er König wurde, und regierte einunddreißig Jahre in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Er tat, was dem Herrn gefiel. Er wandelte auf seines Ahnen David Pfaden und wich nicht davon, weder rechts noch links.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Im achten Regierungsjahr, als er noch jung war, fing er an, den Gott seines Ahnen David zu suchen, und im zwölften Jahr begann er, Juda und Jerusalem von den Höhen, den Ascheren, den Schnitz- und Gußbildern zu reinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Vor ihm riß man die Altäre der Baale ein. Er selber fällte die Rauchaltäre oben darauf, zerstörte und vernichtete die Ascheren, sowie die Schnitz- und Gußbilder, dann streute er auf die Gräber die, denen man geopfert hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Auch die Gebeine der Propheten verbrannte er auf ihren Altären. So säuberte er Juda und Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'In den Städten Manasses, Ephraims, Simeons und Naphtalis, in ihren Trümmern ringsum,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'riß er auch die Altäre um, zerschlug und zermalmte die Ascheren und die Schnitzbilder und stürzte alle Rauchaltäre im ganzen Lande Israel um. Darauf kehrte er nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Im achtzehnten Regierungsjahr, während der Reinigung von Land und Haus, sandte Saphan, Asaljahus Sohn, den Stadthauptmann Maasejahu und den Kanzler Joach, des Joachaz Sohn, das Haus des Herrn, seines Gottes, auszubessern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Sie kamen zu dem Hohenpriester Chilkijahu und übergaben das Geld, das ins Gotteshaus gebracht worden war. Die levitischen Schwellenhüter von Manasse und Ephraim sowie vom ganzen übrigen Israel hatten es aus ganz Juda und Benjamin und von Jerusalems Einwohnern eingesammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Sie gaben es den Werkmeistern, die zur Aufsicht am Haus des Herrn bestellt waren, und diese gaben es für die Arbeiter aus, die am Hause des Herrn arbeiteten, um das Haus auszubessern und zu festigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Sie gaben es auch für die Zimmerleute und Bauleute aus, um Bausteine zu kaufen und Holz für die Verklammerung und Gebälke für die Gebäude, die Judas Könige hatten verfallen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Die Leute arbeiteten gewissenhaft an dem Werk. Zur Aufsicht über sie waren bestellt die Leviten Jochat und Obadjahu von den Merarisöhnen, sowie Zakarjahu und Mesullam von den Kehatssöhnen, um Anweisung zu geben. Leviten, von denen jeder der Musikgeräte kundig war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'standen den Lastträgern vor. Überhaupt gab es Aufseher für alle irgendwie Beschäftigten. Etliche der Leviten waren Schreiber, Amtleute und Torhüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Als sie das Geld herausnahmen, das in das Haus des Herrn gebracht worden war, fand der Priester Chilkijahu das Buch der Lehre des Herrn an Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Da hob Chilkijahu an und sprach zum Schreiber Saphan: \"Ich habe im Hause des Herrn das Buch der Lehre gefunden.\" Chilkijahu gab das Buch dem Saphan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Und Saphan brachte das Buch zum König und erstattete dem König weiteren Bericht. Er sprach: \"Alles, was deinen Knechten aufgetragen ward, haben sie getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Sie schütteten das Geld aus, das sich im Hause des Herrn vorgefunden, und gaben es den Aufsehern und Arbeitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Dann berichtete der Schreiber Saphan dem König: \"Der Priester Chilkijahu hat mir ein Buch gegeben. Und Saphan las daraus dem König vor.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Wie der König die Worte der Lehre vernahm, zerriß er seine Kleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Dann gebot der König dem Chilkijahu und dem Achikam, Saphans Sohn, dem Abdon, Mikas Sohn, dem Schreiber Saphan und dem königlichen Leibdiener Asaja:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '\"Geht! Befragt den Herrn für mich und für die in Israel und Juda Übriggebliebenen wegen des Inhalts des Buches, das gefunden worden ist! Denn groß ist des Herrn Grimm, der sich über uns ergießt, weil unsere Väter das Wort des Herrn nicht befolgten und nichts davon taten, was in diesem Buch geschrieben steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Da ging Chilkijahu mit des Königs Leuten zu der Prophetin Chulda, dem Weibe Sallums, des Sohnes Tokhats und Enkels Chasras, des Kleiderhüters. Sie aber wohnte in Jerusalem im neuen Stadtviertel. Sie redeten solches mit ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Da sagte sie zu ihnen: \"So spricht der Herr, Israels Gott: \'Sagt nur dem Mann, der euch zu mir gesandt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'So spricht der Herr: Fürwahr, ich bringe Unglück über diesen Ort und seine Bewohner, all diese Flüche, die geschrieben sind im Buch, das man dem Könige von Juda vorgelesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Dafür, daß sie mich schnöd verlassen haben, so daß sie anderen Göttern räucherten und mich mit allem Machwerk ihrer Hände kränkten, ergießt sich mein Grimm über diesen Ort und soll nicht mehr erlöschen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Zum Judakönig, der euch hergesandt, den Herrn zu befragen, sollt ihr so sprechen: \'Der Herr, Gott Israels, hat diese Worte ausgesprochen, die du gehört hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Doch weil dein Herz so weich und weil du dich vor Gott demütigtest, als du seine Worte gegen diesen Ort und seine Bewohner vernahmst, ja, weil du dich vor mir demütigtest und dein Gewand zerrissest und vor mir weintest, so schenke ich Gehör.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, '\'Fürwahr, ich sammle dich zu deinen Vätern; im Frieden wirst du in dein Grab gebracht. Und deine Augen müssen nicht ansehen all das Unheil, das ich verhänge über diesen Ort und seine Bewohner.\'\" Also berichteten sie dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Hierauf sandte der König hin und versammelte alle Ältesten Judas und Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Dann ging der König zum Hause des Herrn hinauf, ebenso alle Männer Judas und Jerusalems Einwohner, die Priester und die Leviten, sowie das ganze Volk, vom Ältesten bis zum Jüngsten, und er las ihnen alle Worte des Bundesbuches vor, das im Haus des Herrn gefunden worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Dann trat der König an seinen Standort und schloß vor dem Herrn den Bund, dem Herrn nachzufolgen und seine Gebote, Gebräuche und Satzungen von ganzem Herzen und aus ganzer Seele zu halten und die Bundesworte zu befolgen, die in diesem Buch geschrieben stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Und er bestärkte darin alle, die sich in Jerusalem und Benjamin vorfanden. Und so taten die Bewohner Jerusalems nach dem Bunde Gottes, des Gottes ihrer Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Und Josias beseitigte alle Greuel aus allen Gebieten der Israeliten und verpflichtete alle in Israel zum Dienste des Herrn, ihres Gottes. Solange er lebte, fielen sie nicht von dem Herrn, ihrer Väter Gott, ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Josias hielt nun in Jerusalem dem Herrn ein Passah. Am vierzehnten Tage des ersten Monats schlachtete man das Passah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Er stellte die Priester auf ihre Posten und machte ihnen Mut zum Dienste am Hause des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Er sprach zu den Leviten, die ganz Israel belehren sollten und die dem Herrn geweiht waren: \"Belasset die heilige Lade im Hause, das Israels König Salomo, Davids Sohn, erbaut hat! Ihr habt nichts mehr auf der Schulter zu tragen. Dient nunmehr dem Herrn, eurem Gott, und seinem Volk Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Haltet euch bereit nach euren Familien, nach euren Abteilungen, nach der Schrift Davids, des Königs von Israel, und nach dem Erlaß seines Sohnes Salomo!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Stellt euch im Heiligtum auf, nach den Gruppen der Familien eurer Brüder, der Leute aus dem Volke, und die Abteilung der Familie der Leviten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Schlachtet das Passah, zerlegt es und bereitet es für eure Brüder! Tut nach dem Wort des Herrn an Moses!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Josias lieferte den Leviten aus dem Volke Schafe, Lämmer und junge Ziegen, alles zu Passahopfern für alle Anwesenden; 30.000 an Zahl und 3.000 Rinder, diese aus des Königs Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Seine Obersten aber lieferten in Menge für das Volk, die Priester und Leviten ab. Die Fürsten des Gotteshauses Chilkia, Zakarjahu und Jechiel gaben für die Priester 2.600 Lämmer und 3.000 Rinder zu Passahopfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konanjahu und seine Brüder Semajahu und Netanel sowie die Levitenobersten Chasabjahu, Jeiel und Jozabad gaben für die Leviten 5.000 Lämmer und 500 Rinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'So war der Dienst geordnet. Die Priester traten auf ihren Standort und die Leviten in ihre Abteilungen nach des Königs Befehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Sie schlachteten das Passah, und die Priester sprengten das Blut, während die Leviten die Haut abzogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Sie schieden das Brandopfer aus. Dann gaben sie nach Gruppen den Stammeshäuptern der Leute aus dem Volk, damit sie dem Herrn darbrächten, wie geschrieben ist im Buche Mosis. Ebenso taten sie mit den Rindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Dann brieten sie das Passah nach Vorschrift am Feuer. Die heiligen Gaben aber kochten sie in Kesseln, Töpfen und Schüsseln und brachten diese schnell allen Leuten aus dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Danach richteten sie für sich und die Priester zu. Denn die Aaronssöhne, die Priester, hatten mit der Darbringung des Brandopfers und der Fettstücke bis in die Nacht hinein zu tun gehabt. So richteten die Leviten für sich und die priesterlichen Aaronssöhne zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Die Sänger, Asaphs Söhne, waren nach der Anordnung Davids, Asaphs, Hemans und des königlichen Sehers Jedutun auf ihren Posten. Ebenso die Torhüter an den einzelnen Toren. Sie brauchten ihren Dienst nicht zu verlassen, weil ihre Brüder, die Leviten, für sie zurichteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'So ward an jenem Tag der ganze Dienst des Herrn geordnet. Man feierte das Passah und opferte nach des Königs Josias Befehl auf dem Altar des Herrn Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Also feierten die anwesenden Israeliten zu jener Zeit Passah, dazu das Fest der ungesäuerten Brote, sieben Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'So war das Passah in Israel nicht mehr gefeiert worden seit den Tagen des Propheten Samuel. Keiner der Könige Israels hatte ein Passah gefeiert wie dies, das Josias begangen, die Priester und die Leviten und ganz Juda und Israel, soweit es da war, und Jerusalems Bewohner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Dieses Passah war im achtzehnten Regierungsjahre des Josias gefeiert worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Nach all diesen Begebenheiten, als Josias das Haus wiederhergestellt hatte, zog Ägyptens König Necho heran, bei Karkemis am Euphrat zu kämpfen. Josias aber zog ihm entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Da sandte jener Boten an ihn und ließ sagen: \"Was habe ich mit dir, König von Juda? Nicht dir gilt es heute, sondern meinem feindlichen Hausgesinde. Gott heißt mich eilen. Laß ab von Gott, der mit mir ist, daß er dich nicht vernichte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Josias aber wandte sich nicht von ihm ab, sondern erklärte, mit ihm streiten zu wollen. Er hörte nicht auf Gottes Worte aus Nechos Munde, sondern ging vielmehr hin, in der Ebene von Megiddo zu kämpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Die Schützen schossen auf König Josias. Da sprach der König zu seinen Dienern: \"Bringt mich weg! Denn ich bin schwer verwundet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Da hoben ihn seine Diener vom Wagen und trugen ihn in seiner Sänfte weg. So brachten sie ihn nach Jerusalem. Da starb er und wurde in den Gräbern seiner Väter bestattet. Ganz Juda und Jerusalem trauerte um Josias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremias dichtete ein Klagelied auf Josias, und alle Sänger und Sängerinnen besangen in ihren Klageliedern Josias bis auf diesen Tag. Man machte es zu einer Sitte für Israel. Sie sind in den Klageliedern verzeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Der Rest der Geschichte des Josias und seine Frömmigkeit, die in der Lehre des Herrn vorgeschrieben ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'seine frühere und spätere Geschichte, sind im Buche der Könige von Israel und Juda aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Die eingesessene Bevölkerung nahm nun Josias Sohn Joachaz und machte ihn zu Jerusalem zum König an seiner Statt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joachaz war dreiundzwanzig Jahre alt, als er König wurde, und regierte drei Monate in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Der König von Ägypten setzte ihn zu Jerusalem ab und legte dem Land eine Buße von hundert Talenten Silber und einem Talent Gold auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Dann machte Ägyptens König seinen Bruder Eljakim zum König über Juda und Jerusalem und änderte seinen Namen in Jojakim. Seinen Bruder Joachaz aber verhaftete Necho; dann führte er ihn nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jojakim war fünfundzwanzig Jahre alt, als er König wurde, und regierte elf Jahre in Jerusalem. Er tat, was dem Herrn, seinem Gott, mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Gegen ihn zog der König von Babel, Nebukadrezar, heran; dann legte er ihn in Ketten, um ihn nach Babel zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Auch einen Teil der Geräte im Haus des Herrn brachte Nebukadrezar nach Babel und tat sie zu Babel in seinen Palast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Der Rest der Geschichte Jojakims und der Greuel, die er verübte, und sein Mißgeschick sind im Buche der Könige von Israel und Juda aufgeschrieben. An seiner Statt ward sein Sohn Jojachin König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jojachin war acht Jahre alt, als er König wurde, und er regierte drei Monate und zehn Tage zu Jerusalem. Er tat, was dem Herrn mißfiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Nach Ablauf des Jahres sandte der König Nebukadrezar; dann brachte er ihn nach Babel samt den kostbaren Geräten aus dem Hause des Herrn. Er machte seines Vaters Bruder Sedekia zum König über Juda und Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sedekia war einundzwanzig Jahre alt, als er König wurde, und regierte in Jerusalem elf Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Er tat, was dem Herrn, seinem Gott, mißfiel. Er demütigte sich nicht vor dem Propheten Jeremias und seinem Worte aus des Herrn Munde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Auch gegen den König Nebukadrezar empörte er sich, der ihn bei Gott hatte schwören lassen. Er war halsstarrig und verstockt und kehrte sich nicht zum Herrn, Israels Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Auch alle Obersten der Priester samt dem Volk begingen viel Untreue, entsprechend all den heidnischen Greueln. Sie verunreinigten das Haus des Herrn, das er in Jerusalem hatte weihen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Der Herr, ihrer Väter Gott, sandte zwar durch seine Boten unermüdlich Mahnungen an sie. Denn sein Volk und sein Wohnsitz taten ihm leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Aber sie verhöhnten Gottes Boten, verachteten ihre Worte und verlachten seine Propheten, bis des Herrn Grimm gegen sein Volk so hoch stieg, daß keine Rettung möglich war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'So führte er gegen sie den Chaldäerkönig, und er schlug ihre Jungmannschaft mit dem Schwerte im Hause ihres Heiligtums. Er verschonte weder Jüngling noch Jungfrau, weder Greis noch Hochbetagten. Alles gab er in seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Alle Geräte des Gotteshauses, groß und klein, samt den Schätzen im Haus des Herrn und denen des Königs und seiner Obersten, alles brachte er nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Dann verbrannten sie das Gotteshaus und rissen Jerusalems Mauern ein; auch alle seine Paläste äscherten sie ein, und alle ihre kostbaren Geräte gingen zugrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Und was dem Schwerte entrann, führte er nach Babel in die Gefangenschaft. Sie wurden ihm und seinen Söhnen untertan, bis das Perserreich zur Herrschaft kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'So wurde erfüllt des Herrn Wort durch des Jeremias Mund: \"Bis seine Sabbate das Land gezählt, genießt es Ruhe in den Tagen der Verwüstung insgesamt, um siebzig Jahre zu erfüllen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Im ersten Jahre des Perserkönigs Cyrus, von da ab gerechnet, wo sich des Herrn Wort durch des Jeremias Mund erfüllte, erweckte der Herr den Geist des Perserkönigs Cyrus, und er ließ in seinem ganzen Reiche folgendes ausrufen und schriftlich bekanntmachen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '\"So spricht Cyrus, der König von Persien: Alle Reiche der Erde hat mir der Herr, der Gott des Himmels, gegeben. Er selbst hat mir geboten, ihm ein Haus zu bauen zu Jerusalem, das in Juda liegt. Wer unter euch zu seinem Volk gehört, mit diesem sei sein Gott! Er ziehe hinauf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Im ersten Jahre des Perserkönigs Cyrus, von da an gerechnet, als sich das Wort des Herrn aus des Jeremias Mund erfüllte, hatte der Herr den Geist des Perserkönigs Cyrus erweckt, so daß er in seinem ganzen Reiche folgendes ausrufen und schriftlich bekanntmachen ließ:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '\"So spricht der Perserkönig Cyrus: Alle Reiche der Erde hat Mir der Herr, der Gott des Himmels, gegeben. Er hat mir auch aufgetragen, ihm ein Haus zu bauen zu Jerusalem, das im Judalande liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Wer unter euch zu seinem Volk gehört, mit diesem sei sein Gott! Er ziehe nach Jerusalem im Judaland hinauf und baue das Haus des Herrn, des Gottes Israels, das ist der Gottheit zu Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Wer übrig ist, dem sollen an allen Orten, wo er weilt, seine Ortsgenossen mit Silber, Gold und sonstiger Habe helfen, auch mit Reittieren samt freiwilligen Gaben für das Haus der Gottheit zu Jerusalem!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Da erhoben sich die Familienhäupter von Juda und Benjamin sowie die Priester und die Leviten, alle, deren Geist die Gottheit erweckt hatte, hinaufzuziehen und des Herrn Haus in Jerusalem aufzubauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Alle ihre Mitbewohner aber unterstützten sie mit Silber, Gold und sonstiger Habe sowie mit Reittieren und köstlichen Lebensmitteln in Menge, abgesehen von dem, was jeder freiwillig spendete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Der König Cyrus aber gab die Geräte aus dem Hause des Herrn heraus, die Nebukadrezar aus Jerusalem weggeschleppt und in seines Gottes Haus verbracht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Und der Perserkönig gab sie in die Hand des Schatzmeisters Mitredat. Und dieser zählte sie Sesbassar zu, dem Landpfleger von Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Dies war ihre Zahl: dreißig goldene Becken, tausend silberne Becken, neunundzwanzig Räucherpfannen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'dreißig goldene Becher, vierhundertzehn silberne Doppelbecher, tausend andere Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Im ganzen fünftausendvierhundert goldene und silberne Geräte. All das brachte Sesbassar hinauf, als er aus Babel die Gefangenen nach Jerusalem hinaufführte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Dies sind die Angehörigen des Bezirks, die aus der Exulantenschar heraufgezogen und die Babels König Nebukadrezar nach Babel geführt hatte. Sie kehrten heim nach Jerusalem und Juda, jeder in seine Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Sie, die mit Zerubbabel, Jesua, Nechemja, Seraja, Reelaja, Mordekai, Bilsan, Mispar, Bigwai, Rechum und Baana gekommen waren. Das ist die Zahl der Männer des Volkes Israel:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'die Söhne des Paros 2.172,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'die Söhne des Saphatja 372,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'die Söhne des Arach 775,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'die Söhne des Tachat Moab, nämlich die Söhne des Jesua Joab, 2.812,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'die Söhne des Elam 1.245,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'die Söhne des Zattu 945,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'die Söhne des Zakkai 760,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'die Söhne des Bani 642,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'die Söhne des Bebai 623,');
