INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'die Söhne des Adonikam 666,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'die Söhne des Bigwai 2.056,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'die Söhne des Adin 459,');
