INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'die Söhne des Besai 323,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'die Söhne des Jora 112,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'die Söhne des Chasum 223,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'die Söhne des Gibbar 95,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'die Söhne von Bethlehem 23,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'die Männer von Netopha 56,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'die Männer von Anatot 128,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'die Söhne des Azmawet 42,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'die Söhne Kirjat Arim, Kephira undBeerot 743,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'die Söhne der Rama und von Geba 621,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'die Männer von Mikmas 122,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'die Männer von Betel und dem Ai 223,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'die Söhne des Nebo 52,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'die Söhne des Maglis 156,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'die Söhne des Neu-Elam 1.254,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'die Söhne des Charim 320,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'die Söhne des Lod, Chadid und Ano 725,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'die Söhne von Jericho 345,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'die Söhne Senaas 3.630.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Die Priester: die Söhne Jedajas vom Hause Jesua 973,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'die Söhne des Immer 1052,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'die Söhne des Paschur 1247,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'die Söhne des Charim 1017.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Die Leviten: die Söhne des Jesua und des Kadmiel vom Hause Hodawja 74.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Die Sänger: die Söhne Asaphs, 128.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Die Torhüter: die Söhne Sallums, die Söhne Talmons, die Söhne Akkubs, die Söhne Chatitas, die Söhne Sobais, insgesamt 1.391.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Die Tempelsklaven: die Söhne des Sicha, die Söhne des Chasupha, die des Tabbaot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'die Söhne des Keros, die des Siaha, die des Padon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'die Söhne des Lebana, die des Chaguba, die des Akkub,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'die Söhne des Chagab, die des Samlai, die des Chanan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'die Söhne des Giddel, die des Gachar, die des Reaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'die Söhne des Resin, die des Nekoda, die des Gazzam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'die Söhne des Uzza, die des Paseach, die des Besai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'die Söhne des Asna, die der Mëuniter, die der Nephusiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'die Söhne des Bakbuk, die des Chakupha, die des Charchur,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'die Söhne des Baslut, die des Mechida, die des Charsa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'die Söhne des Barkos, die des Sisera, die des Tamach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'die Söhne des Nesiach die des Chatipha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Die Söhne der Sklaven Salomos: die Söhne des Sotai, die der Schreiberin, die des Peruda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'die Söhne des Jaala, die des Darkon, die des Giddel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'die Söhne des Sephatja, die des Chattil, die Söhne der Pokeret der Gazellen, die des Ami,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'all die Tempelsklaven und Söhne der Sklaven Salomos 393.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Und dies sind die, die aus Tel Melach und Tel Charsa, Cherub, Addan und Immer hergezogen waren, aber nicht dartun konnten, ob ihr Haus und ihre Abstammung echt israelitisch seien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Die Söhne des Delaja, die des Tobia und die des Nekoda 652.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Und von den Priestersöhnen die Söhne des Chabaja und die des Hakkos, die Söhne Barzillais, der sich eine der Töchter des Gileaditers Barzillai zum Weibe genommen hatte und dann nach ihrem Namen benannt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Diese suchten die Schrift ihres Geschlechtsnachweises. Sie fand sich aber nicht vor, und so wurden sie vom Priestertum ausgeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Der Tirsata sprach zu ihnen, sie dürften vom Hochheiligen nicht essen, bis ein Priester für Urim und Tummim erstünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Die ganze Gemeinde belief sich auf 42.360,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'ohne ihre Sklaven und Sklavinnen, an Zahl 7.337. Auch hatten sie 200 Sänger und Sängerinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Die Zahl der Pferde betrug 736, die ihrer Maultiere 245,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'ihrer Kamele 435, ihrer Esel 6.720.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Von den Familienhäuptern hatten manche, als sie zum Hause des Herrn in Jerusalem kamen, Spenden für das Gotteshaus gegeben, um es auf seiner Stelle zu errichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Sie hatten für den Bauschatz je nach ihrer Habe an Gold 61.000 Drachmen gegeben, an Silber 5.000 Minen und 100 Priesterkleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Die Priester, die Leviten und manche vom Volk, die Sänger, Torhüter und Tempelsklaven siedelten sich darin in ihren Städten an, ebenso das ganze übrige Israel in seinen Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'So kam der siebte Mond heran. Die Söhne Israels waren schon in den Städten. Da versammelte sich das Volk wie ein Mann zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Jesua, der Sohn des Josadak, und seine Brüder, die Priester, und Zerubbabel, der Sohn Sealtiels, und seine Brüder erhoben sich und bauten den Altar des Gottes Israels auf, um Brandopfer darauf darzubringen, wie in der Lehre Mosis, des Gottesmannes, geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'So erstellten sie den Altar auf seinen Grundlagen. Denn die Völker der Länder hatten ihn bis auf den Grund zerstört. Sie opferten auf ihm dem Herrn Brandopfer, Morgen- und Abendopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Sie feierten auch das Laubhüttenfest nach Vorschrift und brachten Brandopfer Tag für Tag, an Zahl nach Vorschrift, wie es sich für jeden Tag gebührte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'und dann das regelmäßige Brandopfer und die der Neumonde und die aller heiligen Festzeiten des Herrn und die eines jeden, der dem Herrn freiwillig Gaben brachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Vom ersten Tage des siebten Monats an begannen sie dem Herrn Opfer zu bringen obwohl des Herrn Tempel noch nicht aufgebaut war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Sie gaben den Steinmetzen und den Zimmerleuten Geld, den Sidoniern und Tyriern aber Speise und Trank und Öl, damit sie Zedernstämme vom Libanon zur See nach Joppe brächten, gemäß der Vollmacht des Perserkönigs Cyrus an sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Im zweiten Jahre nach ihrer Ankunft beim Gotteshaus zu Jerusalem, im zweiten Monat, begannen Sealtiels Sohn, Zerubbabel, und Jesua, der Sohn des Josadek, sowie die anderen Brüder, die Priester und die Leviten und alle, die aus der Gefangenschaft nach Jerusalem gekommen waren. Sie stellten die Leviten an, von zwanzig Jahren und darüber, um den Bau des Herrnhauses zu überwachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Und Jesua und seine Söhne sowie seine Brüder und Kadmiel mit seinen Söhnen und Judas Söhne traten wie ein Mann auf, die Arbeiter am Gotteshaus zu überwachen. Ferner die Söhne Chenadads und ihre Söhne sowie ihre Brüder, die Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Die Bauleute richteten nun den Tempel für den Herrn auf. Dann stellten sich die Priester in Amtstracht mit Trompeten hin. Die Leviten und die Asaphsöhne priesen mit Zimbeln den Herrn in der Weise Davids, des Königs von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'In ihrem Lobgesang machten sie den Vers zum Kehrvers: \"Lobpreist den Herrn! Denn er ist gut. Ewig währet seine Huld für Israel!\" Beim Lob des Herrn jubelte das ganze Volk überlaut, weil das Haus des Herrn errichtet war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Vielen aber von den Priestern und den Leviten und von den Familienhäuptern, von den Alten, die noch das frühere Haus gesehen hatten, erschien das Haus da fremd. Und sie weinten laut. Viele aber erhoben lauten Freudenjubel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'So konnte das Volk vor dem lauten Freudenjubel nicht das Weinen der Leute heraushören. Denn das Volk jauchzte laut, und weithin ward der Lärm gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Judas Feinde aber und die Benjamins hörten, daß die Söhne der Gefangenschaft dem Herrn, dem Gotte Israels, einen Tempel bauten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Da traten sie zu Zerubbabel und zu den Familienhäuptern und sagten ihnen: \"Wir wollen mit euch bauen; denn wir suchen euren Gott wie ihr. Wir opfern ihm seit den Tagen des Assyrerkönigs Assarhadon, der uns hierher gebracht hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Da sprachen Zerubbabel und Jesua und die übrigen Familienhäupter Israels zu ihnen: \"Nein! Ihr und wir können kein Haus für unseren Gott bauen. Wir allein bauen es für den Herrn, Israels Gott, wie uns der König Cyrus, der Perserkönig, befohlen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Da machten die Völker der Länder das Volk Juda mutlos und schreckten es vom Bauen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Sie dingten wider sie Ratgeber, um ihren Plan zu vereiteln, die ganze Zeit des Perserkönigs Cyrus hindurch bis zur Herrschaft des Perserkönigs Darius.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Unter der Regierung des Ahasveros, zu Anfang seiner Herrschaft, schrieben sie eine Klage gegen die Bewohner Judas und Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Und in der Zeit des Artachsast schrieben Bislam, Mitredat, Tabel und die anderen seiner Amtsgenossen an Artachsast, den Perserkönig. Das Klageschreiben war nach Schrift und Sprache aramäisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rechum, der Ratsherr, und der Schreiber Simsai schrieben einen Brief wider Jerusalem an den König Artachsast, folgenden Inhalts:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, '\"Rechum, der Ratsherr, und der Schreiber Simsai und ihre übrigen Amtsgenossen, die Gerichtsvollzieher und die Eparchen aus Tripolis, Babel, Susa, das ist aus Elam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'und solche der anderen Nationen, die Osnappar, der Große und Erlauchte, weggeführt und in den Städten Samarias und in dem übrigen Syrien angesiedelt hat usw.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Dies ist eine Abschrift des Briefes, den sie dem König Artachsast sandten: \"Deine Sklaven, die Leute von Syrien usw.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Dem König sei mitgeteilt, daß die Juden, die aus deiner Nähe zu uns gezogen, nach Jerusalem gelangt sind. Sie bauen die aufrührerische und böse Stadt auf, stellen ihre Mauer her und bessern die Wehren aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Deshalb sei dem König mitgeteilt: Falls jene Stadt aufgebaut und die Mauern hergestellt werden, entrichten sie keine Steuer, keine Abgabe und keinen Zoll mehr. So wird das Einkommen der Könige geschädigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Weil wir das Salz des Palastes essen und weil uns des Königs Verunglimpfungen anzusehen nicht ansteht, darum schicken wir her und melden es dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Man forsche im Buche der Denkwürdigkeiten deiner Väter! Du findest und erfährst im Buche der Denkwürdigkeiten, daß jene Stadt eine aufrührerische Stadt gewesen ist und daß sie Könige und Provinzen geschädigt und daß man in ihr Empörung seit alter Zeit gestiftet hat. Eben darum ist jene Stadt zerstört worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Wir melden dem König: Falls jene Stadt aufgebaut und ihre Mauern hergestellt werden, hast du keinen Teil mehr an Syrien.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Dann sandte der König Bescheid an Rechum, den Ratsherrn, an Simsai, den Schreiber, und an die anderen Amtsgenossen, die in Samaria und sonst in Syrien wohnten: \"Gruß usw.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Das Schreiben, das ihr uns gesandt habt, ist in Übersetzung vor mir verlesen worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Von mir ist der Befehl ergangen, und man hat nachgeforscht und gefunden, daß sich jene Stadt seit alter Zeit gegen Könige erhob und daß Aufruhr und Empörung darin gestiftet wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Mächtige Könige herrschten über Jerusalem und schalteten in ganz Syrien. Ihnen wurde Steuer, Abgabe und Zoll entrichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Darum gebt Befehl, daß jenen Männern gewehrt werde! Jene Stadt soll nicht mehr aufgebaut werden, bis von mir Befehl hierzu erteilt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Nehmt euch aber in acht, hierin keinen Fehler zu tun, damit nicht ein Schaden zum Nachteil der Könige erwachse!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Sobald nun die Abschrift des Schreibens vom König Artachsast vor dem Ratsherrn Rechum, dem Schreiber Simsai und ihren Amtsgenossen verlesen worden war, zogen sie eilends nach Jerusalem gegen die Judäer und hinderten sie mit Zwang und Gewalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Damals war die Arbeit am Gotteshaus zu Jerusalem gehindert. Und sie unterblieb bis zum zweiten Regierungsjahr des Perserkönigs Darius.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Damals weissagten die Seher Aggäus und Zacharias, Iddos Sohn, über die Judäer in Jerusalem und Juda im Namen des Gottes Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Darauf erhoben sich Zerubbabel, der Sohn Sealtiels, und Jesua, der Sohn des Josadak, und begannen, das Gotteshaus in Jerusalem zu bauen. Und die Propheten Gottes waren mit ihnen und unterstützten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Zu jener Zeit kam Syriens Landpfleger Tattenai zu ihnen und Setar Bozenai und ihre Amtsgenossen und sprachen also zu ihnen: \"Wer hat euch erlaubt, dies Haus zu bauen und diese Mauer herzustellen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Auch fragten sie sie: \"Wie heißen jene Männer, die dieses Gebäude bauen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Aber ihres Gottes Augen ruhten auf den Ältesten der Judäer. Und so hinderten jene sie nicht, bis von Darius die Erlaubnis einlief und man hernach das Schreiben hierüber zustellte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Abschrift des Briefes, den Tattenai, Syriens Landpfleger, und Setar Bozenai und seine Amtsgenossen, die Statthalter in Syrien, an den König Darius geschickt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Sie sandten den Bericht an ihn, und so stand darin geschrieben: \"Dem König Darius allen Frieden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Dem König sei kundgetan, daß wir in der Provinz Juda zum Hause des Großgottes gekommen sind. Dieses wird aus Quadersteinen gebaut, und die Wände werden mit Holz getäfelt. Die Arbeit wird eifrig betrieben und gedeiht unter ihren Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Da haben wirjene Ältesten gefragt und so zu ihnen gesprochen: \'Wer hat euch Erlaubnis gegeben, dies Haus zu bauen und diese Mauern herzustellen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Auch nach ihren Namen haben wir sie gefragt, um sie dir mitzuteilen. Wir schrieben die Namen der Männer an ihrer Spitze auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Sie haben uns folgenden Bescheid gegeben: \'Wir sind Diener des Gottes Himmels und der Erden. Wir bauen dies Haus, das vor vielen Jahren gebaut worden ist. Ein großer König Israels hat es erbaut und vollendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Weil aber unsere Väter den Himmelsgott erzürnt haben, hat er sie in die Hand des Chaldäers Nebukadrezar, des Königs von Babel gegeben. Er hat dies Haus zerstört und das Volk nach Babel in die Gefangenschaft geführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Aber im ersten Jahre des Cyrus, des Königs von Babel, hat der König Cyrus den Befehl gegeben, dieses Haus aufzubauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Auch die goldenen und silbernen Geräte des Gotteshauses, die Nebukadrezar aus dem Tempel zu Jerusalem weggenonunen und in den Tempel zu Babel verbracht, hat der König Cyrus aus dem Tempel zu Babel geholt, und sie sind dem Sesbassar gegeben worden, der so heißt und den er zum Landpfleger eingesetzt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Er hat zu ihm gesagt: \"Da hast du die Geräte. Nimm sie, zieh hin und lege sie im Tempel zu Jerusalem nieder! Das Gotteshaus soll an seiner Stätte aufgebaut werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Darauf ist jener Sesbassar gekommen und hat dem Gotteshaus zu Jerusalem Wehren gefertigt. Seitdem wird bis jetzt daran gebaut; es ist aber noch nicht fertig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Falls es dem König beliebt, möge im königlichen Schatzhaus dort zu Babel nachgeforscht werden, ob es so sei, daß vom König Cyrus Befehl ergangen ist, dies Gotteshaus zu bauen! Den Bescheid des Königs in dieser Sache lasse er uns zukommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Also gab König Darius Befehl. Und man forschte im Urkundenhaus nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Da fand sich zu Ekbatana im Schlosse, das in der Provinz Medien liegt, eine Schriftrolle, und als Denkwürdigkeit stand darin:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '\"Im ersten Jahre des Königs Cyrus hat der König Cyrus Befehl gegeben: Das Gotteshaus zu Jerusalem werde aufgebaut als Stätte, wo man Schlachtopfer schlachtet und wo man ihm seine Feueropfer darbringt! Seine Höhe sei sechzig Ellen und seine Breite sechzig Ellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Drei Schichten von Quadersteinen seien da, ebenso eine Schicht von Holz! Die Kosten sollen aus dem königlichen Hause bestritten werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Auch erstatte man die goldenen und silbernen Geräte des Gotteshauses, die Nebukadrezar aus dem Tempel zu Jerusalem weggenommen und nach Babel gebracht hat! Sie seien dem Tempel zu Jerusalem eigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Demnach bleibt fern von dort ihr, Tattenai, Landpfleger von Syrien, Setar Bozenai und seine Amtsgenossen, Statthalter von Syrien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Laßt die Arbeit an diesem Gotteshause gehen! Der Statthalter der Judäer und die Ältesten der Juden sollen jenes Gotteshaus an seiner Stätte aufbauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Und von mir ergeht der Befehl über das, was ihr jenen Ältesten der Judäer tun sollt, um jenes Gotteshaus aufzubauen. Aus den königlichen Einkünften des Tributs von Syrien werde jenen Männern genau ausbezahlt, um sie nicht zu stören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Und was sonst nötig ist, wie junge Stiere, Widder und Lämmer zu Brandopfern für den Himmelsgott, Weizen, Salz, Wein und Öl, werde ihnen nach Angabe der Priester zu Jerusalem Tag für Tag ungeschmälert geliefert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Sie sollen dem Himmelsgott Wohlgerüche darbringen und für das Leben des Königs und seiner Söhne beten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Ferner ergeht von mir Befehl: Wer diesen Beschluß ändert, aus dessen Haus werde ein Balken gerissen und er selbst gepfählt daran geschlagen! Sein Haus aber werde deshalb zum Misthaufen gemacht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Der Gott aber, der seinen Namen dort thronen läßt, stürze jeden König und jedes Volk, die es wagen sollten, das Gotteshaus zu Jerusalem zum zweitenmal zu zerstören! Ich, Darius, habe den Befehl gegeben. Er werde genau befolgt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Da taten Syriens Landpfleger Tattenai, Setar Bozenai und ihre Amtsgenossen genauso, wie es König Darius angeordnet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'So bauten die Ältesten der Judäer glücklich weiter nach der Weissagung des Aggäus und des Iddosohnes Zacharias, der Propheten. So hatten sie gebaut und waren fertig geworden auf Geheiß des Gottes Israels und auf Befehl des Cyrus und des Darius sowie des Perserkönigs Artachsast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'So vollendeten sie das Haus bis zum dritten Tag des Monats Adar, also im sechsten Regierungsjahr des Königs Darius.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Dann feierten die Söhne Israels, die Priester und die Leviten und die anderen Söhne der Gefangenschaft die Einweihung dieses Gotteshauses mit Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Und sie brachten bei der Einweihung des Gotteshauses hundert Stiere dar, zweihundert Widder, vierhundert Lämmer und zwölf Ziegenböcke als Sündopfer für ganz Israel, entsprechend der Zahl der Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Sie bestellten auch die Priester nach ihren Abteilen und die Leviten nach ihren Klassen zum Gottesdienst in Jerusalem nach der Vorschrift des Buches Mosis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Dann feierten die Söhne der Gefangenschaft das Passah am vierten Tage des ersten Monats.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Denn die Priester und Leviten hatten sie wie ein Mann gereinigt. Sie alle waren rein. Dann schlachteten sie das Passah für alle Söhne der Gefangenschaft und für ihre Brüder, die Priester und die Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Und die Söhne Israels, die aus der Gefangenschaft zurückgekehrt waren, verzehrten es; aber auch alle, die sich zu ihnen hin von der Unreinheit der Heiden im Land abgesondert hatten, um den Herrn, Israels Gott, zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Sie feierten das Fest der ungesäuerten Brote in Freuden sieben Tage. Denn der Herr hatte sie erfreut und ihnen des Assyrerkönigs Herz zugewandt, daß er sie unterstützte bei der Arbeit am Gotteshaus des Gottes Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Hernach zog unter der Regierung des Perserkönigs Artachsast der Sohn Serajas herauf, Esdras (Ezra), der Enkel des Azarja und Urenkel Chilkias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'des Sohnes Sallums und Enkels Sadoks und Urenkels des Achitub,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'des Sohnes des Amarja und Enkels des Ajarja und Urenkels des Merajot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'des Sohnes des Zerachja und Enkels Uzzis und Urenkels des Bukki,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'des Sohnes Abisuas, des Enkels Pinechas und Urenkel Eleazars, des Sohnes des Hohenpriesters Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Eben dieser Esdras zog von Babylon herauf. Er war Schriftgelehrter, bewandert in Mosis Lehre, die der Herr, Gott Israels, gegeben hatte. Ihm gab der König, was er sich wünschte, unter dem Schutze des Herrn, seines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'So zog eine Anzahl von Söhnen Israels, Priester, Leviten, Sänger, Torhüter und Tempelsklaven mit ihm nach Jerusalem im siebten Jahre des Königs Artachsast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Er kam nach Jerusalem im fünften Monat, das ist im siebten Jahre des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Am ersten Tag des ersten Monats, das ist im Nisan, verfügte er den Auszug aus Babylon. Und am ersten Tag des fünften Monats kam er nach Jerusalem unter dem sicheren Schutze seines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Denn Esdras hatte sein Herz darauf gerichtet, des Herrn Lehre zu erforschen und zu befolgen und Satzung und Recht in Israel zu lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Dies ist die Abschrift des Schreibens, das der König Artachsast dem Priester und Schreiber Esdras gegeben hat, dem Ausleger der Gebote und Vorschriften des Herrn für Israel:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '\"Artachsast, der König der Könige, an den Priester Esdras, den Ausleger des Gesetzes des Himmelsgottes usw.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Von mir ergeht Befehl: Jeder in meinem Reich von dem Volke Israel und seinen Priestern und Leviten, der sich getrieben fühlt, nach Jerusalem zu ziehen, ziehe mit dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Du wirst vom König und seinen sieben Ratgebern gesandt, Juda und Jerusalem zu erkunden, nach deines Gottes Gesetz, dessen du kundig bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Überbringe das Silber und Gold, das der König und seine Räte für Israels Gott gespendet, dessen Wohnung in Jerusalem ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Ebenso alles Silber und Gold, das du in der ganzen Provinz Babel bekommst als freiwillige Gaben des Volkes und der Priester, die sie für das Haus ihres Gottes zu Jerusalem spenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Demgemäß kaufe gewissenhaft für das Geld Stiere, Widder und Lämmer und die dazugehörigen Speise- und Trankopfer und opfere sie auf dem Altar des Hauses eures Gottes zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Und was dir und deinen Brüdern beliebt, mit dem Rest des Silbers und des Goldes zu tun, das tut nach eures Gottes Willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Liefere auch die Geräte ab, die man für den Gottesdienst im Hause deines Gottes hergegeben, vor Gott in Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Den übrigen Bedarf deines Gotteshauses, den du zu decken hast, bestreite aus dem königlichen Schatzhaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Von mir, König Artachsast, wird Befehl an alle Schatzmeister in Syrien erteilt: Alles, was der Priester Esdras, der Ausleger des Gesetzes des Himmelsgottes, von euch verlangt, werde genau geleistet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'an Silber bis zu hundert Talenten, an Weizen bis zu hundert Malter, an Wein bis zu hundert Maß, an Öl bis zu hundert Maß und an Salz unbeschränkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Alles, was nach dem Befehl des Himmelsgottes ist, werde genau für das Haus des Himmelsgottes geleistet, auf daß kein Zorn über das Reich des Königs und seiner Söhne komme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Ferner sei euch kundgetan: Nicht erlaubt ist es, irgendeinem der Priester, Leviten, Sänger, Torhüter, Tempelsklaven und Knechte dieses Gotteshauses Steuer, Abgabe oder Zoll aufzulegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Du aber, Esdras, setze nach deiner Gottesgelehrtheit, die du hast, Richter und Gerichtsvollzieher ein, die alles Volk in Syrien richten sollen, und solche, die deines Gottes Gesetze kennen! Wer sie nicht kennt, den sollt ihr belehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Jeden aber, der deines Gottes Gesetze und das Gesetz des Königs nicht befolgt, den treffe strenge gerichtliche Strafe, entweder Tod oder Verbannung oder Geldstrafe oder Haft!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Gepriesen sei der Herr, der Gott unserer Väter, der dies dem König ins Herz gegeben, um das Haus des Herrn in Jerusalem zu verherrlichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'und der mir die Huld des Königs, seiner Räte und all der mächtigen Beamten zugewandt hat! So faßte ich Mut unter dem Schutze des Herrn, meines Gottes, und sammelte aus Israel eine Anzahl Familienhäupter, mit mir zu ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Dies sind die Häupter ihrer Familien und ihrer Anverwandten, die mit mir unter der Regierung Artachsasts, des Königs, aus Babylon heraufzogen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'von den Söhnen des Pinechas: Gerson, von den Söhnen Itamars: Daniel, von den Söhnen Davids: Chattus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'von den Söhnen des Paros: Zekarja und zu ihm gehörend 150 männliche Personen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'von den Söhnen Pachatmoabs: Eljehoenai, Zerachjas Sohn, und mit ihm 200 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Von den Söhnen Sekanjas: der Sohn Jachaziels und mit ihm 300 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Und von den Söhnen Adins: Ebed, Jonatans Sohn, und mit ihm 50 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Und von den Söhnen Elams: Jesaja, Ataljas Sohn, und mit ihm 70 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Und von den Söhnen Sepathas: Zebadja, Mikaels Sohn, und mit ihm 80 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Und von den Söhnen Joabs: Obadja, Jechiels Sohn, und mit ihm 218 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Und von den Söhnen Sebmits: der Sohn Josiphjas und mit ihm 160 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Und von den Söhnen Bebais: Zekarja, Bebais Sohn, und mit ihm 28 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Und von den Söhnen Azgars: Jochanan, Hakkatans Sohn, und mit ihm 160 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Und von den Söhnen Adonikams: Eliphelet, Jeiel und Semaja und mit ihnen 60 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Und von den Söhnen Bigwais: Utai und Zabbud und mit ihnen 70 männliche Personen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Ich versammelte sie an dem Flusse, der nach Ahawa kommt. Dort lagerten wir an drei Tage. Ich musterte das Volk samt den Priestern. Da fand ich keinen von den Söhnen Levis dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'So schickte ich Eliezer, Ariel, Semaja, Elnatan, Jarib, Elnatan, Natan, Zekarja und Mesullam als Häupter weg, und Jojarib und Elnatan als Lehrer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Und ich entbot sie an Iddo, das Oberhaupt im Orte Kasiphja, und legte in ihren Mund den Auftrag, den sie Iddo und seinen Brüdern im Ort Kasiphja bestellen sollten, nämlich, sie sollten uns Diener für unser Gotteshaus zuführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Und sie brachten uns unter dem gütigen Schutz unseres Gottes einen verständigen Mann von den Söhnen Machlis, eines Sohnes Levis, eines Sohnes Israels, namens Serebja, mit Söhnen und Brüdern, 18 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Auch Chasabja und mit ihm Jesaja von den Söhnen Meraris, seine Brüder und ihre Söhne, 20,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'von den Tempelsklaven, die David und die Fürsten zum Dienste der Leviten gegeben hatten, 220 Tempelsklaven. Sie alle sind mit Namen verzeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Dann rief ich dort am Flusse Ahawa ein Fasten aus, daß wir uns vor unserem Gott demütigten und ihn um gute Reise anflehten, für uns, unsere Kinder und all unsere Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Denn ich schämte mich, vom Könige Mannschaft und Reiter zu erbitten, um uns vor den Feinden auf der Reise zu schützen. Denn wir hatten zum König gesagt: \"Unseres Gottes Hand ruht auf allen, die ihm zum Besten suchen. Sein mächtiger Zorn dagegen auf allen, die ihn verlassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'So fasteten wir und erflehten solches von unserem Gott, und er ließ sich von uns erweichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Dann sonderte ich von den Obersten der Priester zwölf Leute aus, Serebja und Chasabja, mit ihnen zehn von ihren Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Und ich wog ihnen dar das Silber und Gold und die Geräte, die Spende für unser Gotteshaus, die der König, seine Räte und Beamten gestiftet und ganz Israel, das sich vorgefunden hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Ich wog ihnen in die Hand an Silber 650 Talente und 100 silberne Gefäße zu 2 Talenten, an Gold 100 Talente,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'sodann 20 goldene Becher zu 1000 Dariken und verschiedene Geräte aus feinem Glanzerz, wertvoll wie Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Dann sprach ich zu ihnen: \"Ihr seid dem Herrn geweiht, und die Geräte sind geweiht. Das Silber und das Gold sind eine Spende für eurer Väter Gott, den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Darum hütet es sorgfältig, bis ihr es vor den Obersten der Priester, der Leviten und der Familienoberhäupter Israels zu Jerusalem darwäget in den Zellen im Hause des Herrn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Die Priester und die Leviten übernahmen nun das abgewogene Silber und das Gold und die Geräte, um sie nach Jerusalem in unser Gotteshaus zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Wir brachen nun vom Flusse von Ahawa auf am zwölften Tage des ersten Monats, um nach Jerusalem zu ziehen. Und unseres Gottes Hand war über uns. Er schützte uns vor Feinden und vor Wegelagerern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'So kamen wir nach Jerusalem und weilten dort drei Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Am vierten Tage aber wurden das Silber und das Gold und die Geräte in unserem Gotteshause dargewogen in die Hand des Uriassohnes Meremot, des Priesters. Bei ihm war Eleazar, des Pinechas Sohn, bei ihnen auch Jozabad, Jesuas Sohn, und Binnuis Sohn Noadja, die Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Alles stimmte nach Zahl und Gewicht, und das ganze Gewicht ward zugleich aufgeschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Die aus der Gefangenschaft Heimgekehrten, die Söhne der Gefangenschaft, opferten dem Gott Israels 12 Stiere für das ganze Israel, dann 96 Widder, 77 Lämmer, 12 Böcke zum Sündopfer, alles für den Herrn als Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Dann übergaben sie des Königs Befehle den Satrapen des Königs und den syrischen Statthaltern. Und sie unterstützten das Volk und das Gotteshaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Als dies beendet war, traten die Obersten zu mir und sagten: \"Das Volk in Israel, die Priester und die Leviten, halten sich nicht abgesondert von den Völkern der Länder, ungeachtet ihrer Greuel, von den Kanaanitern und Chittitern, Perizzitern, Jebusitern, Ammonitern, Moabitern, Ägyptern und Amoritern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Sie haben von ihnen Töchter für sich und für ihre Söhne zu Weibern genommen, so daß sich der heilige Stamm mit den Völkern der Länder vermischte. Die Fürsten und Vorsteher sind bei diesem Frevel die ersten gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Als ich das hörte, zerriß ich mein Gewand und meinen Mantel. Dann raufte ich mir das Haar aus Kopf und Bart und saß betäubt da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Zu mir hielten aber alle, welche die Worte des Gottes Israels fürchteten wegen des Frevels der Gefangenschaft. So saß ich betäubt bis zum Abendopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Zur Abendopferzeit stand ich von meiner Verdemütigung auf. In meinem zerrissenen Gewande und Mantel beugte ich die Knie, breitete zum Herrn, meinem Gott, die Hände aus');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'und sprach: \"Mein Gott, ich schäme mich und scheue mich, zu Dir, mein Gott, das Antlitz zu erheben. Denn unsere Sünden sind uns über unser Haupt gewachsen, und ihre Schuld ist himmelhoch geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Seit unserer Väter Tagen bis auf diesen Tag sind wir in großer Schuld, und wegen unserer Sünden sind wir preisgegeben, wir, unsere Könige und Priester, den Königen der Länder, durch Schwert und Gefangenschaft, durch Raub und offene Verhöhnung, so wie es heute ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Nun ist auf kurzen Augenblick Erbarmung gekommen von dem Herrn, unserem Gott. Er ließ uns einen Rest übrig und gab an seiner heiligen Wohnstatt uns einen Zeltpflock. Aufleuchten ließ uns unser Gott die Augen und schenkte uns ein wenig Lebenskraft in unserer Knechtschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Wir sind zwar Knechte, doch hat in unserer Knechtschaft unser Gott uns nicht verlassen. Er wandte uns die Huld der Perserkönige zu und gab uns so viel Lebenskraft, daß wir unser Gotteshaus aufrichten und seine Trümmer wiederherstellen konnten. Er gab uns eine Schutzmauer in Juda und Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Was aber sollen wir nach all diesem sagen, unser Gott? Wir haben Deine Vorschriften ganz außer acht gelassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Du hast sie uns durch Deine Knechte, die Propheten, so gegeben: \'Das Land, in das ihr kommt, um es zu erobern, ist ein bedecktes Land durch Unreinheit der Ländervölker, durch ihre Greueltaten, womit sie es von einem Ende bis zum anderen angefüllt in ihrer Unreinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Gebt eure Töchter niemals ihren Söhnen, und ihre Töchter nehmt niemals für eure Söhne! Nie sucht ihr Glück und ihren Vorteil! Dann bleibt ihr stark, und ihr genießt des Landes Güter, auf eure Söhne sie vererbend.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Ach, können wir nach alledem, was uns durch unsere bösen Werke, unsere große Schuld getroffen - Du, unser Gott, hast unsere Sünden tief verworfen, und doch hast Du uns diesen Rest gelassen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'ja, dürfen wir aufs neue Deine Anordnungen brechen und uns mit diesen Greuelvölkern gar verschwägern? Wirst Du nicht über uns bis zur Vernichtung zürnen, so daß kein Bleiben wäre, keine Rettung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Du bist gar edelmütig, Herr, Gott Israels. Wir sind ein Rest Geretteter noch heute. Wir sind vor Dir in unserer Schuld. So aber kann man nicht vor Dir bestehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'So betete Esdras, bekannte, weinte und flehte vor dem Gotteshause. Da scharte sich eine große Menge aus Israel um ihn, Männer, Weiber und Kinder; denn das Volk weinte bitterlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Da hob Sekanja, Jechiels Sohn, von Elams Söhnen, an und sprach zu Esdras: \"Wir sind untreu geworden unserem Gott, daß wir fremde Weiber von des Landes Völkern heimgeführt. Aber noch ist dabei Hoffnung für Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Wir wollen jetzt einen Bund schließen mit unserem Gott, daß wir alle unsere Frauen und was aus ihnen geboren worden, nach des Herrn Rat entlassen. Wir wollen unseres Gottes Gebot gewissenhaft beachten. Nach der Lehre soll es geschehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Steh auf! Denn deine Sache ist es. Wir sind mit dir. Ermanne dich und handle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Da stand Esdras auf und ließ die Oberen der Priester, die Leviten und ganz Israel schwören, daß sie so tun wollten. Und sie schwuren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Esdras stand nun vor dem Gotteshause auf und ging in die Zelle Jochanans, des Eljasibsohnes. Er ging hinein, aß aber kein Brot und trank kein Wasser, trauernd ob des Frevels der Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Dann ließen sie einen Ruf ergehen in Juda und Jerusalem an alle Söhne der Gefangenschaft, sie sollten sich in Jerusalem versammeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Wer nicht am dritten Tage nach dem Beschluß der Oberen und Ältesten komme, dessen ganze Habe solle gebannt werden, und er selbst solle aus der Gemeinde der Gefangenschaft ausgeschlossen sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Da versammelten sich zu Jerusalem alle Männer aus Juda und aus Benjamin am dritten Tage, das ist am zwanzigsten des neunten Monats. Und das ganze Volk saß auf dem Platze des Gotteshauses, zitternd wegen der Sache und der Regengüsse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Da stand der Priester Esdras auf und sprach zu ihnen: \"Ihr habt dadurch gefrevelt, daß ihr heidnische Weiber heimgeführt, um Israels Schuld zu mehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Nun legt ein Bekenntnis vor dem Herrn, dem Gott eurer Väter, ab, und tut seinen Willen! Trennt euch von den Ländervölkern und von den fremden Weibern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Die ganze Gemeinde rief mit lauter Stimme: \"Wie du zu uns gesagt, ist zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Das Volk aber ist zahlreich. Auch ist Regenzeit. Man kann nicht im Freien weilen. Auch ist es keine Sache für einen oder zwei Tage. Denn wir haben mannigfach in dieser Sache gefrevelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Unsere Obersten mögen für die ganze Gemeinde tagen! Dann können alle, die in unseren Städten fremde Weiber heimgeführt, zur bestimmten Zeit kommen und mit ihnen die Ältesten und Priester jeder Stadt, um unseres Gottes Zornesglut von uns in dieser Sache abzuwenden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Nur Jonatan, Azales Sohn, und Jachzela, Tikwas Sohn, traten dagegen auf, und Mesullam und der Levite Sabai standen ihnen bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Aber die Söhne der Gefangenschaft handelten recht. So sonderte sich der Priester Esdras Männer, Familienhäupter, nach den einzelnen Familien aus, alle namentlich aufgezeichnet. Und sie hielten die erste Sitzung an dem ersten Tage des zehnten Monats, um die Sache zu untersuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Und sie wurden mit all den Männern fertig, die fremde Weiber heimgeführt, bis zum ersten Tage des ersten Monats.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Da fanden sich auch unter Priestersöhnen solche, die fremde Weiber heimgeführt hatten, von den Söhnen Jesuas, des Sohnes Josadaks, und seiner Brüder Maaseja und Eliezer, Jarib und Gedalja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Sie gaben aber ihre Hand darauf, ihre Weiber zu entlassen. Ihr Schuldopfer war ein Widder für ihre Schuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Und von den Söhnen Immers: Chanani und Zebadja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Und von den Söhnen Charims: Maaseja, Elia, Semaja, Jechiel und Uzzia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Und von den Söhnen Paschurs: Eljoënai, Maaseja, Ismael, Netanel, Jozabad und Elasa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Und von den Leviten Josabad, Simi und Kolaja, das ist Kelita, Petachja, Jehuda und Eliezer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Und von den Sängern Eljasib und von den Torhütern Sallum, Telem und Uri.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Und von Israel, von den Söhnen des Paros Ramja, Izzia, Malkia, Mijjamin, Eleazar, Malkia und Benaja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Und von den Söhnen Elams Mattanja, Zekarja, Zechiel, Abdi, Jeremot und Elia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Und von den Söhnen Zattus Eljoënai, Eljasib, Mattanja, Jeremot, Zabad und Aziza.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Und von den Söhnen Bebais Jehochanan, Chananja, Zabbai, Atlai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Und von den Söhnen Banis Messullam, Malluk, Adaja, Jasub, Seal und Ramot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Und von den Söhnen Pachatmoabs Adna und Kelal, Benaja, Maaseja, Mattanja, Besalel, Binnui und Menasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Und von den Söhnen Charims Eliezer, Isija, Malkija, Semaja, Simon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk, Semarja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Von den Söhnen Chasums Mattenai, Mattatta, Zabad, Eliphelet, Jemai, Menasse, Simi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Von den Söhnen Banis Maadai, Aram und Uël,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Keluhi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Wanja, Meremot, Eljasib,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanja, Mattenai und Jaasaw.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Und von den Söhnen Binnuis Simi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemja, Natan, Adaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadebai, Sasai, Sarai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Selemja, Semaria,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja, Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Von den Söhnen Nebos Jejel, Mattija, Zabad, Zebina, Jaddai, Joel und Benaja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Alle diese hatten fremde Weiber genommen. Es fanden sich unter ihnen auch Weiber, die Kinder geboren hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Der Bericht des Chakaljasohnes Nehemias. Es war im Monat Kislev im Jahre zwanzig, daß ich zu Susan in der Burg weilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Da kam einer meiner Brüder, Chanani, mit Männern aus Judäa. Ich fragte sie nach den Judäern, den Entronnenen, die vor der Gefangenschaft bewahrt worden waren, und nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Sie gaben mir Bescheid: \"Die Zurückgebliebenen, die dort vor der Gefangenschaft in den Landstädten verschont geblieben sind, befinden sich in großer Not und Schmach. Die Mauer von Jerusalem liegt in Trümmern, und seine Tore sind verbrannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Als ich diese Worte hörte, setzte ich mich hin, weinte und trauerte eine Zeitlang. Ich fastete und betete vor dem Himmelsgott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Dann sprach ich: \"Herr, Gott des Himmels! Du großer, fürchterlicher Gott! Du hältst den gnadenvollen Bund all denen, die Dich lieben und Dein Geheiß befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Leih doch Dein Ohr! Laß Deine Augen offen sein, auf daß Du Deines Knechts Gebet erhörst, das ich jetzt Tag und Nacht vor Dir verrichte für Deine Knechte, für die Söhne Israels. Ich beichte die Verschuldungen der Söhne Israels, die wir so gegen Dich gesündigt haben, ich selbst und meines Vaters Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Wir haben Dich beleidigt und nicht gewahrt Gebote und Gesetze, Rechte, die Du dem Moses, Deinem Diener, aufgetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Gedenke doch des Wortes, das Du dem Moses, Deinem Knecht, befohlen: \'Begeht ihr Untreue, zerstreu ich euch unter die Nationen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Bekehrt ihr euch jedoch zu mir und haltet und befolgt, was ich geboten, dann bringe ich zusammen eure Vertriebenen, und wenn sie selbst am Himmelsende wären, und führe sie zur Stätte hin, die ich zum Wohnsitz meines Namens auserkoren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Denn sie sind Deine Knechte und Dein Volk, das Du befreit mit Deiner großen Kraft und Deinem starken Arm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ach, Herr! Laß doch Dein Ohr vernehmen das Flehen Deines Dieners und das Flehen Deiner Diener, die begehren, Deinen Namen zu verehren! Laß Deinem Diener heute es gelingen! Und schenke ihm vor diesem Manne Gnade!\" - Ich aber war der Mundschenk beim König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Im Nisanmonat, in des Königs Artachsast zwanzigstem Jahr, stand Wein vor ihm. Ich nahm den Wein und gab ihn dem König. Er war mir nicht ungewogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Da sprach zu mir der König: \"Warum bist du betrübt? Du bist doch nicht krank? Wenn nicht, dann hast du Herzenskummer.\" Da erschrak ich heftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Ich sprach zum König: \"Lang lebe der König! Wie sollte ich nicht betrübt sein, da die Stadt, meiner Väter Grabstätte, zerstört ist und ihre Tore verbrannt sind?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Da sprach zu mir der König: \"Worum bittest du?\" Da betete ich zum Himmelsgott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Ich sprach dann zum König: \"Gefällt es dem König und ist dein Sklave dir genehm, dann mögest du mich nach Juda zur Stadt der Gräber meiner Väter senden, damit ich sie aufbaue!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Da sprach zu mir der König, und die Gemahlin saß an seiner Seite: \"Wie lange währt deine Reise? Wann kehrst du zurück?\" Und es gefiel dem König, mich zu entsenden, und ich gab ihm eine Frist an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Dann sprach ich zum König: \"Gefällt es dem König, so gebe man mir Briefe an Syriens Statthalter mit, daß sie mich begleiten lassen, bis ich nach Juda komme,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'und einen Brief an Asaph, den Verwalter der königlichen Waldungen, daß er mir Holz gebe, um an der Burg, die zum Hause gehört, die Tore mit Balken zu versehen; desgleichen für die Stadtmauer und für das Haus, in das ich ziehen werde!\" Und der König bewilligte mir dies, dank dem gütigen Schutze meines Gottes über mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'So kam ich zu den Statthaltern von Syrien und gab ihnen des Königs Briefe. Der König aber sandte mit mir Heeresoberste und Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Dies hörten Sanballat von Choronaim und der ammonitische Ansiedler Tobia. Da verdroß es sie stark, daß jemand gekommen sei, das Wohl der Söhne Israels zu fördern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'So kam ich nach Jerusalem und blieb hier drei Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Dann stand ich nachts mit ein paar Leuten auf. Ich hatte aber keinem Menschen gesagt, was mein Gott für Jerusalem zu tun mir ins Herz gegeben. Auch waren bei mir keine Reittiere, außer dem Tiere, auf dem ich selbst ritt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'So zog ich durch das Taltor nachts zur Drachenquelle und dann zum Misttor. Ich besichtigte die Mauern Jerusalems, wie sie in Trümmern lagen und ihre Tore verbrannt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Dann zog ich zum Quellentor hinüber und zum Königsteich. Aber das Tier fand dort keinen Platz, um mit mir durchzukommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Da stieg ich im Tale nachts bergan und besichtigte die Mauer. So kam ich dann wieder an das Taltor und kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Die Vorsteher aber wußten nicht, wohin ich gegangen war und was ich vorhatte. Den Judäern, den Priestern, den Adligen und den Vorstehern und den anderen Werkführern hatte ich bis jetzt nichts gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Nun sprach ich zu ihnen: \"Ihr seht die Not, in der wir sind. Jerusalem ist zerstört, und seine Tore sind verbrannt. Auf! Laßt uns die Mauern Jerusalems bauen, daß wir nicht länger zum Gespötte seien!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Dann erzählte ich ihnen, wie gütig der Schutz meines Gottes über mir war, und auch des Königs Worte, die er an mich gerichtet. Da sagten sie: \"Wir wollen darangehen und bauen.\" So ermunterten sie sich zum guten Werke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Dies hörten Sanballat aus Choronaim, der ammonitische Ansiedler Tobia und der Araber Gesem, spotteten unser und äußerten verächtlich: \"Was ist das, was ihr tun wollt? Wollt ihr vom König abfallen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Da gab ich ihnen Bescheid und sprach zu ihnen: \"Der Himmelsgott wird uns Gelingen geben. Wir, seine Knechte, wollen uns ans Bauen machen. Ihr aber habt kein Teil und kein Recht und kein Gedächtnis zu Jerusalem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Da standen der Hohepriester Eljasib und die Priester, seine Brüder, auf und bauten das Schaftor, zugleich hatten sie es befestigt; dann setzten sie seine Tore ein, ebenso den Turm Hammea; auch ihn hatten sie umwallt, ebenso den Turm Chananels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Daneben hatten die von Jericho gebaut und neben ihnen Zakkur, Imris Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Das Fischtor bauten Senaas Söhne, zugleich hatten sie es mit Gebälk überdacht; dann setzten sie seine Tore ein und seine Klammern mit den Querriegeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Daneben besserte Urias Sohn Meremot aus, der Enkel des Hakkos, daneben Mesullam, Berekjas Sohn und Enkel Mesezabels, daneben Sadok, Baanas Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Daneben besserten die Tekoiter aus; ihre Vornehmen aber trugen nichts zu ihrer Herren Leistung bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Am Altstadttor besserten Paseachs Sohn Jojada aus und Mesullam, Besodjas Sohn. Zugleich hatten sie es mit Gebälk überdacht; dann setzten sie seine Tore ein und seine Klammern mit den Querriegeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Daneben besserten der Gibeoniter Melatja aus und Jadon, der Meronititer, und die von Gibeon und von der Mispa am Stuhle des Statthalters von Syrien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Daneben besserte Uzziel, ein Glied der Goldschmiedezunft, aus, daneben Chananja von den Salbenmischern. Sie befestigten Jerusalem bis an die breite Mauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Daneben besserte des Chur Sohn Rephaja aus, der Oberste der einen Hälfte des Bezirks Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Daneben besserte Charunaphs Sohn Jedaja aus, und zwar vor seinem eigenen Hause, daneben Chattus, Chasabnejas Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Und eine zweite Strecke besserte Malkia, Charims Sohn, aus, und Chasub, Pachatmoabs Sohn, beim Ofenturm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Daneben besserte des Loches Sohn Sallum aus, der Oberste der anderen Hälfte des Bezirks Jerusalem, er und die Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Das Taltor besserte Chanun mit den Leuten von Zanoach aus, Sie bauten es auf, dann setzten sie seine Tore ein und seine Klammern mit den Querriegeln und weitere tausend Ellen an der Mauer bis zum Misttor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Das Misttor besserte der Rebakssohn Malkia aus, der Oberste im Bezirk von Beth Hakkerem. Er baute es auf und setzte seine Tore ein und seine Klammern mit den Querriegeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Das Quelltor besserte des Kol Choze Sohn Sallum aus, der Oberste im Bezirk der Mispa. Er baute es auf, überdachte es und setzte seine Tore ein und seine Klammern und Querriegel, sowie die Mauer an dem Teich für die Schaffelle beim Königsgarten bis zu den Stufen, die von der Davidsstadt herabführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Danach besserte aus des Azbuk Sohn Nechemja, der Oberste der Hälfte des Bezirkes von Beth Sur, bis gegenüber von den Davidsgräbern und bis zu dem künstlichen Teich und dann bis zur Kaserne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Danach besserten auch die Leviten aus: Rechum, des Bani Sohn. Daneben besserte Chasabja aus, der Oberste des halben Amts von Keïla, für dieses sein Amt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Daneben besserten ihre Brüder aus, Bawwai, der Sohn des Chenadad, der Oberste des anderen Amts von Keïla.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Daneben besserte Ezer, der Sohn Jesaes, der Oberste der Mispa, eine zweite Strecke aus, dem Aufstieg des Zeughauses am Winkel gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Danach besserte des Zabbai Sohn Baruk eine zweite Strecke aus, vom Winkel bis zum Tor des Hauses Eljasibs, des Hohenpriesters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Danach besserte des Uria Sohn Meremot, der Enkel des Hakkos, eine zweite Strecke aus, vom Tor des Hauses Eljasibs bis ans Ende des Hauses Eljasibs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Danach besserten die Priester, die Männer aus dem Gau, aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Danach besserte des Maaseja Sohn Azarja aus, der Enkel des Ananja, neben seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Danach besserte Binnui, Chenadads Sohn, eine zweite Strecke aus, von des Azarjas Haus bis zum Winkel und bis zur Ecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palel, des Uzai Sohn, gegenüber dem Winkel sowie dem Turm, der vom oberen Königshaus, am Gefängnishof hervorspringt, danach des Paros Sohn Pedaja');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'und die Tempelsklaven, die im Ophel wohnten, bis vor dem Wassertor im Osten und vor dem vorspringenden Turm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Danach besserten die Tekoiter eine zweite Strecke aus, dem großen vorspringenden Turm gegenüber bis an die Ophelmauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Oberhalb des Roßtores besserten die Priester aus, jeder vor seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Danach besserte vor seinem Hause Immers Sohn Sadok aus, danach Sekanjas Sohn Semaja, des Osttores Hüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Danach besserten Selemjas Sohn Chananja und Salaphs des Sechsten Sohn Chanun eine zweite Strecke aus. Danach besserte Berekjas Sohn Mesullam vor seiner eigenen Zelle aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Danach besserte Malkia von den Goldschmieden bis zum Hause der Tempelsklaven und der Krämer aus, dem Wachttor gegenüber und bis zur oberen Zelle der Ecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Und zwischen dieser oberen Zelle an der Ecke und dem Schaftor besserten die Goldschmiede und die Krämer aus. Sobald Sanballat erfuhr, daß wir die Mauer bauten, kam er in Zorn und großen Ärger. Er spottete der Judäer. Er sprach von seinen Brüdern und der Streitmacht von Samaria: \"Was machen die armseligen Judäer? Läßt man sie gewähren? Opfern sie jetzt? Machen sie es fertig? Lassen sie die Steine aus dem Schutthaufen wachsen? Sie sind doch verbrannt.\" Neben ihm stand Tobia aus Ammon und sprach: \"Mögen sie bauen! Springt ein Fuchs hinauf, reißt er ihre Steinmauer ein.\" Höre, unser Gott, wie wir verspottet werden! Bringe ihren Hohn auf ihr eigen Haupt zurück und gib sie im Lande der Gefangenschaft der Schmach preis! Decke nimmer ihre Frevel zu! Nicht ausgelöscht werde ihre Sünde vor Dir! Sie haben die Bauenden gekränkt. Wir aber bauten an der Mauer. Und die ganze Mauer wurde bis zur halben Höhe geschlossen, und das Volk hatte Lust zur Arbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Als Sanballat, Tobia und die Araber, die Ammoniter und die Asdoditer hörten, daß die Ausbesserung der Mauern Jerusalems voranging und daß sich die Breschen zu schließen begännen, wurden sie recht zornig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Sie verschworen sich, alle auf einmal zu kommen, Jerusalem zu stürmen und in ihm Verwirrung zu stiften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Wir beteten zu unserem Gott und stellten Wachen Tag und Nacht gegen sie auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Die Judäer aber sprachen: \"Die Kraft des Lastträgers wankt: Des Schuttes ist zuviel. Wir sind nicht mehr imstande, an der Mauer zu bauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Unsere Gegner aber sagten: \"Sie sollen nichts sehen und nichts merken, bis wir in ihre Mitte dringen und sie töten; so machen wir dem Bau ein Ende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Aber die Judäer, die in ihrer Nähe wohnten, kamen und sprachen uns zehnmal von all den Orten, wohin \"ihr zu uns gehen sollt\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Da ließ ich Schleuderer aufstellen in der Gegend hinter der von Truppen entblößten Stadtmauer. Nach Familien ließ ich das Volk antreten mit seinen Schwertern, Lanzen und Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Ich sah auch nach. Dann erhob ich mich und sprach zu den Adligen, den Vorstehern und zum übrigen Volk: \"Habt vor ihnen keine Angst! Denkt an den großen, furchtbaren Herrn und kämpft für eure Brüder, Söhne, Töchter, Weiber und Häuser!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Unsere Feinde aber hörten, es sei uns verraten worden. So störte Gott ihren Plan. Und wir kehrten alle zur Mauer zurück, jeder an seine Arbeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Seit jener Zeit war nur die eine Hälfte meiner Knappen bei der Arbeit tätig. Die andere Hälfte hielt die Lanzen, Schilder, Bogen und Panzer, die Oberen aber standen hinter dem ganzen Hause Juda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'das an der Mauer baute. Die Lastträger aber schafften so, daß sie mit einer Hand bei der Arbeit tätig waren, die andere Hand aber die Schleuder hielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Und von den Bauenden band sich jeder sein Schwert um die Hüften und baute so. Neben mir stand der Hornbläser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Ich sprach nun zu den Adligen, den Vorstehern und zu dem übrigen Volk: \"Die Arbeit ist groß und umfangreich. Wir aber sind auf der Mauer verstreut, einer vom anderen entfernt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Woher ihr den Schall des Hornes hört, dort schart euch bei uns zusammen! Unser Gott kämpft für uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'So schafften wir am Werke. Die eine Hälfte hielt die Lanzen vom frühen Morgen bis zum Erscheinen der Sterne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Zur selben Zeit sprach ich zum Volke: \"Jeder bleibe mit seinem Knappen die Nacht in Jerusalem, bei Nacht als Wache, bei Tage am Werk!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Weder ich noch meine Brüder noch meine Knappen noch die Wachtposten in meinem Gefolge legten die Kleider ab. Jeder hatte seinen Regenmantel an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Damals erhob sich große Klage beim Volk und bei seinen Weibern, gegen ihre Brüder, die Judäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Die einen sagten: \"Wir wurden unserer Söhne und unserer Töchter für verlustig erklärt; dann erst bekamen wir Korn, aßen und blieben leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Und andere sagten: \"Wir verpfändeten unsere Felder, Weinberge und Häuser; dann bekamen wir Korn für den Hunger.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Und wieder andere sagten: \"Wir haben uns Geld für des Königs Steuer auf unsere Felder und Weinberge geliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Nun aber ist unser Leib wie der Leib unserer Brüder, und unsere Söhne sind wie ihre Söhne. Und doch müssen wir unsere Söhne und Töchter zum Sklavendienst pressen. Manche unserer Töchter wurden vergewaltigt, und wir können nichts dagegen tun. Unsere Felder und Weinberge gehören anderen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Da geriet ich in großen Zorn, als ich ihre Klage hörte und diese Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Und mein Herz zwang mich, daß ich mit den Adligen und Vorstehern rechtete und zu ihnen sprach: \"Ihr treibt ja Wucher miteinander.\" Und so hielt ich ihnen eine große Rede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Ich sprach zu ihnen: \"Wir haben unsere jüdischen Brüder losgekauft, die an die Heiden verkauft waren, soviel an uns war. Nun verkauft ihr selbst eure Brüder, und sie werden an uns verkauft?\" Sie aber schwiegen still und fanden keine Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Ich sprach: \"Nichtsnutzig ist, was ihr tut. Solltet ihr nicht in der Furcht vor unserem Gott wandeln, schon aus Scham vor den Heiden, unseren Feinden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Ich, meine Brüder und meine Knappen haben ihnen Getreide und Geld geliehen. Lassen wir doch die Schuldforderung verfallen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Gebt ihnen sogleich ihre Felder, Weinberge, Ölbaumgärten und Häuser zurück, sowie die Zinsen vom Geld, Korn, Most und Öl, die ihr von ihnen fordert!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Da sprachen sie: \"Wir geben es zurück und verlangen nichts mehr. Wir wollen tun, wie du gesagt.\" Da berief ich die Priester und ließ sie schwören, also zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Ich schüttelte dazu meines Kleides Falten und sprach: \"So schüttle Gott all die Männer, die das Versprechen nicht halten, aus Haus und aus Besitz! So leer und ausgeschüttelt werde jeder!\" Und die ganze Gemeinde sprach: \"So sei es!\" Und sie pries den Herrn. Und das Volk tat nach diesem Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Von dem Tage an, da er mir den Auftrag gab, Statthalter im Judaland zu sein, vom zwanzigsten bis zum zweiunddreißigsten Jahre des Königs Artachsast, zwölf Jahre, haben weder ich noch meine Brüder die Kost des Landpflegers gegessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Die früheren Landpfleger, meine Vorgänger, hatten das Volk bedrückt. Sie nahmen von ihnen Brot und Wein, außerdem vierzig Ringe. Auch ihre Knappen hatten das Volk vergewaltigt. Ich aber habe nicht so getan aus Gottesfurcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Dann habe ich bei diesem Mauerbau mitgeholfen, obwohl wir kein Feld gekauft hatten. Alle meine Knappen waren dort beim Bau versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Judäer und Edle, an hundertfünfzig Mann, und die zu uns kamen von den Heiden rings um uns, waren an meinem Tisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Was täglich zubereitet wurde, waren ein Stier und sechs auserlesene Schafe. Auch Geflügel war mir zubereitet worden. Und alle zehn Tage Wein in Fülle. Trotzdem habe ich die Kost des Landpflegers nicht beansprucht, weil die Fronarbeit schwer auf diesem Volk gelastet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Mein Gott, gedenke meiner und rechne mir zum Besten alles, was ich für dieses Volk getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Sanballat aber, Tobia, dem Araber Gesem und unseren anderen Feinden kam es zu Ohren, daß ich die Mauer aufgebaut und daß keine Bresche darin zurückgeblieben sei. Nur Tore hatte ich bis dahin noch nicht eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Da schickten Sanballat und Gesem zu mir und ließen sagen: \"Auf! Wir wollen im Tal Ono in Kephirim zusammenkommen.\" Sie aber planten, mir Böses zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Ich sandte zu ihnen Boten und ließ melden: \"Ich arbeite an einem großen Werk. Darum kann ich nicht hinunterkommen. Warum soll das Werk feiern, wenn ich es ließe und zu euch käme?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'So schickten sie zu mir in dieser Weise viermal. Und ich gab ihnen stets die gleiche Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Da schickte Sanballat, auf diese Weise zum fünftenmal, seinen Diener zu mir mit einem offenen Brief in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Darin stand geschrieben: \"Man hört bei den Heiden reden - auch Gasmu sagt es -, du und die Judäer planten Aufruhr. Deshalb bautest du die Mauer auf. Du selbst wolltest, nach diesen Gerüchten, bei ihnen König werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Sogar Propheten habest du angestellt, um zu Jerusalem von dir zu künden: \'In Juda König!\' Nun wird dem König solches zu Ohren kommen. Darum auf! Wir wollen zusammen darüber beraten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Ich aber schickte zu ihm und ließ ihm sagen: \"Nichts von all dem, was du sagst, ist geschehen. Aus deinem Herzen erdichtest du es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Denn sie alle wollten uns bange machen. Sie dachten: \"Ihre Hände werden schlaff bei dem Werke, so daß es nicht ausgeführt wird.\" Nun hieß es Mut fassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Ich aber ging in das Haus Semajas, des Delajasohnes und Enkels des Mehetabel. Es war gut verschließbar. Da sprach er: \"Treffen wir uns im Gotteshaus, im Innern des Tempels, und schließen wir die Tempeltore zu! Denn sie kommen, dich zu ermorden. Sie kommen bei Nacht, dich zu ermorden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Ich sprach: \"Ein Mann wie ich sollte fliehen? Wer meinesgleichen dächte in den Tempel gehen und leben bleiben? Ich gehe nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Und ich erkannte, daß nicht Gott ihn gesandt hatte, sondern er verkündete mir die Weissagung, weil Tobia und Sanballat ihn gedungen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Er war gedungen worden, daß ich Angst bekäme und also täte und mich versündigte. Dieses hätte ihnen als üble Nachrede gedient, mich zu verlästern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Gedenke, mein Gott, dem Tobia und dem Sanballat nach diesen ihren Taten! Auch Noadja, der Prophetin, und den anderen Propheten, die mir Angst machen wollen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Die Mauer aber ward am fünfundzwanzigsten Elul im Laufe von zweiundfünfzig Tagen fertig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Als unsere Feinde dies hörten, fürchteten sich alle Heiden unserer Nachbarschaft und wurden kleinlaut. Sie erkannten, daß von unserem Gott dies Werk geschehen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Noch in jenen Tagen kamen Briefe vieler Adliger Judas an Tobia, und solche von Tobia kamen an sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Denn in Judäa waren viele seiner geschworenen Freunde, weil er der Schwiegersohn des Arachsohnes Sekanja war. Und Jonatan, sein Sohn, hatte die Tochter des Berekjahsohnes Mesullam heimgeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Selbst seine guten Absichten besprachen sie vor mir, und meine Worte hinterbrachten sie ihm. Tobia sandte dazu Briefe, mir Angst zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Als die Mauer erbaut war, setzte ich die Tore ein. Dann wurden die Torhüter, die Leviten, für ihr Amt ernannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Meinen Bruder Chanani, auch Chananja genannt, bestellte ich zum Burgherrn über Jerusalem. Er galt bei vielen als ein zuverlässiger und gottesfürchtiger Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Ich sprach zu ihnen: \"Man öffne nicht die Tore Jerusalems, bis die Sonne scheint, und bis sie aufgestanden sind, halte man die Tore verschlossen Haltet fest daran! Für die Bewohner Jerusalems stelle man Wachen auf, je einen auf seinen Posten und je einen vor dem Hause.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Nun war die Stadt ausgedehnt und groß. Aber nur wenige Leute waren darin. Noch waren keine Häuser gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Da gab mein Gott mir ins Herz, die Adligen und Vorsteher und das Volk zu versammeln und sie nach ihrer Abkunft aufzuzeichnen. Dabei fand ich das Geschlechterverzeichnis derer, die zuerst heraufgezogen waren. Ich fand geschrieben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Dies sind die Söhne der Landschaft, die aus der Gefangenschaft der Exulanten hergezogen sind, die einstens Babels König Nebukadrezar weggeführt hat, und die nach Jerusalem und Juda zurückkehrten, jeder in seine Stadt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'die mit Zerubbabel, Jesua, Nechemja, Azarja, Reamja, Nachamani, Mordekai, Bilsan, Misperet, Bigwai, Nechum und Baana gekommen sind, die Zahl der Männer des Volkes Israel:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'die Söhne des Paros 2.172,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'die Söhne Sephatjas 372,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'die Söhne des Arach 652,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'die Söhne des Pachatmoab (Moabs Statthalter), nämlich die Söhne des Jesua und Joab 2.818,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'die Söhne des Elam 1.254,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'die Söhne des Zattu 845,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'die Söhne des Zakkai 760,');
