INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'die Söhne des Azgad 2.322,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'die Söhne des Adonikam 667,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'die Söhne des Bigwai 2.067,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'die Söhne des Adin 655,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'die Söhne des Ater von Chizkija 98,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'die Söhne des Chasum 328,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'die Söhne des Besai 324,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'die Söhne des Chariph 112,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'die Söhne Gibeons 95,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'die Männer von Bethlehem und Netopha 188,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'die Männer von Anatot 128,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'die Männer von Bet-Azmawet 42,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'die Männer von Kirjatjearim, Kephira und Beerot 743,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'die Männer der Rama und von Geba 621,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'die Männer von Mikmas 122,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'die Männer von Betel und dem Ai 123,');
