INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'die Söhne Neu Elams 1.254,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'die Söhne Charims 320,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'die Söhne Jerichos 345,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'die Söhne des Lod, Chadid und Ono 721,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'die Söhne Senaas 3930,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'die Priester: die Söhne Jedajas vom Hause Jesua 973,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'die Söhne des Immer 1.052,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'die Söhne des Paschur 1.247,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'die Söhne des Charim 1.017,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'die Leviten: die Söhne des Jesua, nämlich Kadmiel, die Söhne Hodewas 74,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'die Sänger: die Söhne Asaphs 148,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'die Torhüter: die Söhne Sallums, die Söhne Aters, die Söhne Talmons, die Söhne Akkubs, die Söhne Chatitas, die Söhne Sobais 138,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'die Tempelsklaven: die Söhne des Sicha, die Söhne des Chasupha, die des Tabbaot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'die Söhne des Keros, die des Sia, die des Paddon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'die Söhne des Lebana, die des Chazaba, die des Salmai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'die Söhne des Chanan, die des Giddel, die des Gachar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'die Söhne des Reaja, die des Resin, die des Nekoda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'die Söhne des Gazzam, die des Uzza, die des Peseach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'die Söhne des Besai, die der Mëuniter, die der Nephisiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'die Söhne des Bakbuk, die des Chakupha, die des Charchur,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'die Söhne des Baslit, die des Mechida, die des Charsa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'die Söhne des Barkos, die des Sisera, die des Temach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'die Söhne des Nesiach, die des Chatipha,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'die Söhne der Sklaven Salomos: die Söhne des Sotai, die Sopherets (der Schreiberin), die des Perida,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'die Söhne des Jaala, die des Darkon, die des Giddel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'die Söhne des Sephatja, die des Chattil, die Söhne der Pokeret der Gazellen, die des Amon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'alle Tempelsklaven und Söhne der Sklaven Salomos 392.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Dies sind die, die aus Tel Melach, Tel Charsa, Cherub, Addon und Immer hergezogen sind, aber nicht haben dartun können, ob ihr Haus und ihre Abstammung israelitisch seien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'die Söhne des Delaja, die des Tobia und die des Nekoda 642,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'und von den Priestern die Söhne des Chabaja, die des Hakkos und die Söhne Barzillais, der eine von den Töchtern des Gileaditers Barzillai sich zum Weibe genommen hatte und dann nach ihrem Namen benannt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Diese hatten ihre Geschlechtsurkunde gesucht. Sie fand sich aber nicht vor, und so wurden sie vom Priestertum ausgeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Da sprach der Tirsata zu ihnen, sie dürften vom Hochheiligen so lange nicht essen, bis daß ein Priester für Urim und Tummim erstünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Die ganze Gemeinde, alles in allem, belief sich auf 42.360,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'nicht eingerechnet ihre Sklaven und die Sklavinnen, an Zahl 7.387; auch hatten sie 200 Sänger und Sängerinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Und ihrer Pferde waren es 736, ihrer Maultiere 245,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'ihrer Kamele 435, ihrer Esel 6.720.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Und einige von den Familienhäuptern spendeten in den Werkschatz; der Tirsata spendete für den Schatz an Gold 1.000 Drachmen, 50 Sprengschalen, 530 Priesterkleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Einige von den Familienhäuptern spendeten in den Werkschatz an Gold 20.000 Drachmen und an Silber 2.200 Minen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Und was das übrige Volk gab, betrug an Gold 20.000 Drachmen und an Silber 2.000 Minen und was das übrige Volk gab, betrug an Gold 20.000 Drachmen, an Silber 2.000 und 67 Priesterkleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Die Priester aber und die Leviten, die Torhüter, die Sänger und die Leute aus dem Volke sowie die Tempelsklaven und ganz Israel wohnten in ihren Städten. Da kam der siebte Monat heran. Die Söhne Israels waren schon in ihren Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Da versammelte sich wie ein Mann das ganze Volk auf dem Platz vor dem Wassertor. Sie baten den Schreiber Ezra, das Buch der Lehre Mosis herzubringen, die der Herr Israel gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Der Priester Ezra (das ist Esdras) brachte die Lehre vor die Gemeinde, die Männer und Weiber, vor alle, die zuzuhören verstanden, am ersten Tage des siebten Monats.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Er las daraus auf dem Platz vor dem Wassertor von Tagesanbruch bis zum Mittag den Männern, Weibern und allen, die es verstanden, vor. Und das Volk lauschte gespannt dem Buch der Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Der Schreiber Ezra aber trat auf einen hölzernen Turm, den man zum Reden gemacht hatte. Mattia, Sema, Ananja und Uria, Chilkia und Maaseja stellten sich neben ihn zu seiner Rechten, zu seiner linken Seite aber Pedaja, Misael, Malkia, Chasum, Chasladdana, Zekarja und Mesullam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ezra öffnete nun das Buch vor den Augen des ganzen Volkes; denn er stand höher als das ganze Volk. Als er es öffnete, ward es im ganzen Volke still.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Da pries Ezra den Herrn, den großen Gott, und alles Volk sprach unter Händefalten: \"Amen.\" Dann warfen sie sich nieder und beugten vor dem Herrn das Angesicht zur Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Jesua und Bani und Serebja, Jamin, Akkub, Sabtai, sowie Hodia, Maaseja, Kelita, Azaria, Jozabad, Chanan, Pelaja und die Leviten erläuterten dem Volke die Lehre. Das Volk aber stand da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Sie lasen aus dem Buche, aus der Lehre Gottes, in Übersetzung vor und gaben den Sinn an. So verstanden sie das Vorgelesene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Da sprachen Nehemias, das ist der Tirsata, sowie der Priester und Schreiber Ezra und die Leviten, die das Volk belehrten, zum ganzen Volke: \"Dieser Tag ist dem Herrn, eurem Gott, heilig. Trauert nicht und weinet nicht!\" Denn das ganze Volk weinte, als es die Worte der Lehre hörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Er sprach zu ihnen: \"Auf! Esset fette Speisen! Trinkt süße Getränke! Und schickt denen Gaben, die nichts vorrätig haben! Denn heilig ist der Tag unserem Herrn. Seid nicht traurig! Die Freude am Herrn sei eure Zuversicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Auch die Leviten beruhigten das ganze Volk mit den Worten: \"Seid still! Denn der Tag ist heilig. Seid nicht traurig!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Da ging das ganze Volk daran, zu essen und zu trinken und Gaben zu verschicken und ein großes Freudenfest zu halten. Denn sie verstanden die Worte, die man sie gelehrt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Am zweiten Tage versammelten sich die Stammeshäupter aus dem ganzen Volke, die Priester und die Leviten, bei dem Schreiber Ezra, um weiter den Worten der Lehre zu lauschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Da fanden sie in der Lehre geschrieben, daß der Herr durch Moses geboten habe, im siebten Monat sollten die Söhne Israels über die Festzeit in Laubhütten wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Sie sollten auch in ihren Städten und in Jerusalem verkünden lassen: \"Zieht ins Gebirge und holt Zweige von edlen und wilden Ölbäumen, von Myrten und Palmen und anderen dichtbelaubten Bäumen, um vorschriftsmäßig Hütten zu machen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Da zog das Volk hinaus, holte es und machte sich Hütten, jeder auf seinem Dach oder im eigenen Hof, und in des Gotteshauses Höfen und auf dem Platz des Wassertores und auf dem Platz des Ephraimtores.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'So machte die ganze Gemeinde, alle die aus der Gefangenschaft Zurückgekehrten, Hütten. Sie wohnten auch in den Hütten. Solche hatten seit der Zeit Josuas, des Sohnes Nuns, die Söhne Israels nicht mehr gemacht bis auf diesen Tag. Größte Freude herrschte darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Man las aus dem Buche der Lehre Gottes Tag für Tag vor, vom ersten bis zum letzten Tag. So feierten sie das Fest sieben Tage. Am achten Tage aber war nach der Sitte geschlossene Versammlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Am vierundzwanzigsten in diesem Monat versammelten sich die Söhne Israels, fastend und in Bußgewändern, mit Erde auf dem Haupte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Dann ward der Stamm Israels von allen Fremden abgesondert. Sie traten hin und bekannten ihre Sünden und die Schuld ihrer Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Dann erhoben sie sich und lasen aus dem Buche der Lehre des Herrn, ihres Gottes, den vierten Teil des Tages vor. Und ein weiteres Viertel bekannten sie ihre Sünden und warfen sich nieder vor dem Herrn, ihrem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Dann traten Jesua und Banai und Kadmiel, Sebanja, Bunni und Serebja, Bani, Kenani auf die Levitenbühne und flehten laut zum Herrn, ihrem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Dann sprachen die Leviten Jesua und Kadmiel und Bani, Chasabneja, Serebja, Hodia, Sebanja und Petachja: \"Auf! Lobpreist den Herrn, euren Gott, von Ewigkeit zu Ewigkeit! Man preise Deinen wundervollen Namen, erhaben über allen Preis und Ruhm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Darauf sprach Ezra: \"Du, Herr, bist einzig. Du bist es, der den Himmel schuf, der Himmel Himmel, all sein Heer, die Erde, alles, was darauf, die Meere, alles, was darin. Du bist\'s, der alles lebend hält, vor dem des Himmels Heer sich beugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du, Herr, Du bist der Gott, der Abram hat erkoren, und ihn aus der Chaldäer Ur geführt und ihm den Namen Abraham gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Du hast sein Herz getreu vor Dir erfunden und diesen Bund mit ihm geschlossen, das Land der Kanaaniter und Chittiter, der Ammoniter, Perizziter und Jebusiter, Girgasiter seinen Nachkommen zu geben. Du hieltest dies Dein Wort; Du bist gerecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Du sahst das Elend unserer Väter in Ägypten, und an dem Schilfmeer hast Du ihren Hilfeschrei vernommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Da tatest Zeichen Du und Wunder an Pharao und allen seinen Dienern und an dem ganzen Volke seines Landes. Du hast gewußt, daß diese gegen jene freventlich gehandelt. Du schufst Dir damit einen Namen bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Gespalten hast Du auch das Meer vor ihnen, daß sie durchs Meer im Trockenen zogen. Doch ihre Feinde hast Du in die Wasserstrudel hingeschleudert wie einen Stein in wilde Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Durch eine Wolkensäule hast Du sie bei Tag geleitet, durch eine Feuersäule in der Nacht, den Weg, auf dem sie zogen, ihnen zu beleuchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Dann bist Du auf den Sinaiberg herabgestiegen und hast mit ihnen von dem Himmel her gesprochen; Du gabest ihnen richtige Gesetze, wahre Lehren und gute Satzungen und Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Auch Deinen heiligen Sabbat hast Du ihnen angekündet, hast ihnen die Gebote und Satzungen und Lehren durch Moses, Deinen Diener, aufgetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Gespendet hast Du ihnen Brot vom Himmel für den Hunger und Wasser ihnen für den Durst aus Felsen sprudeln lassen. Dann hießest Du sie jenes Land besetzen, das feierlich Du ihnen zugesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Gefrevelt aber haben unsere Väter; halsstarrig waren sie, sie haben nicht auf Dein Gebot gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Sie haben sich geweigert, zu gehorchen, und hatten Deiner Wunder nimmermehr gedacht, die Du für sie gewirkt. Sie steiften also ihren Nacken. Sie setzten es sich in den Kopf, zu ihrem Frondienst heimzukehren nach Ägypten. Doch der Vergebung Gott bist Du, gar gnädig und barmherzig, langmütig, reich an Huld. Du hast sie nicht verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Dann hatten sie sich ein gegossen Kalb verfertigt und gesagt: \'Dies ist dein Gott, der aus Ägypten dich geführt.\' Sie lästerten erschrecklich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Du aber hast sie in der Wüste nicht verlassen in Deinem Reichtum an Erbarmen. Nicht wich bei Tag die Wolkensäule je von ihnen, sie auf dem Weg zu führen, und nicht die Feuersäule nachts, zu leuchten auf dem Wege, den sie zogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Nein! Deinen guten Wind hast Du bestellt, sie zu belehren. Und ihrem Munde hast Du Manna nicht versagt, hast ihnen Wasser für den Durst gespendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Und vierzig Jahre hast Du in der Wüste sie versorgt; nie haben Mangel sie gelitten; zerfallen sind nicht ihre Kleider und ihre Füße nicht geschwollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Dann gabst Du ihnen Königreiche, Völker, und Du verteiltest sie als Lehen. Und sie eroberten das Land des Sichon und das des Königs von Hesbon und das des Basankönigs Og.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Gemehrt hast Du des Himmels Sternen ähnlich ihre Kinder; Du brachtest sie in dieses Land, dahin zu geh\'n Du ihren Vätern anbefohlen, es zu besetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Und ihre Söhne kamen und eroberten das Land. Du warfst des Landes Insassen vor ihnen nieder, die Kanaaniter. Du gabst sie hin in ihre Hand, die Könige mitsamt der Länder Völkern, mit ihnen nach Belieben zu verfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Sie nahmen feste Städte ein und Fruchtgefilde, gewannen Häuser voll des Guten all und ausgehauene Zisternen, Weinberge und Ölbaumgärten, Obstbäume in Menge. Sie aßen, und sie wurden satt und fett und schwelgten in der reichen Fülle Deiner Güter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Doch widerspenstig wurden sie. Sie fielen von Dir ab, verwarfen Deine Lehre, und Deine Seher haben sie erschlagen, die sie verwarnt, um sie zu Dir zurückzuführen. Und sie verübten fürchterliche Lästerungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Da gabst Du sie in ihrer Dränger Hand, und sie bedrückten sie. Da schrieen sie zu Dir in ihrer Not, und Du erhörtest sie vom Himmel her. Du gabst nach Deiner großen Milde ihnen Retter, die sie aus ihrer Dränger Hand befreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Doch als sie Ruhe hatten, verübten sie, was Dir mißfiel; da überließest Du sie ihrer Feinde Hand, und sie beherrschten sie. Nun schrien sie wiederum zu Dir, und Du erhörtest sie vom Himmel her, befreitest sie nach Deiner großen Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Du warntest sie, um sie zu Deiner Lehre wieder hinzuführen. Auf Deine Vorschrift hatten sie in ihrem Frevelsinne nicht gehört. Sie hatten gegen Deine Rechte sich verfehlt, durch die ein Mensch am Leben bleibt, erfüllt er sie. Sie aber zeigten sich gar störrisch. Hartnäckig waren sie geworden, ungehorsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Du aber wartetest mit ihnen viele Jahre, verwarntest sie durch Deinen Geist, durch Deine Seher. Sie aber hatten nicht darauf gehört; da gabst Du sie in die Gewalt der Ländervölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Jedoch in Deiner großen Huld hast Du sie nicht vertilgt und nicht im Stich gelassen, weil Du ein Gott bist, gnädig und barmherzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nun, unser Gott, Du großer und gewaltiger, furchtbarer Gott, der Bund und Huld bewahrt, nicht gelte Dir als wenig all das Ungemach, das uns getroffen, unsere Könige und Oberen und Priester und Propheten und Dein ganzes Volk seit der Assyrerkönige Zeiten bis auf diesen Tag!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du bist gerecht bei allem, was uns traf. Du hast im Recht gehandelt. Doch unser Tun entsprang gar böser Absicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Und unsre Könige, Oberen und Priester, unsre Väter, sie haben Deine Lehre nicht befolgt, und nicht geachtet Deiner Weisung und Ermahnung, durch die Du sie vermahnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Trotz ihres eignen Königtums und trotz der reichen Güterfülle, die Du ihnen hast geschenkt, und trotz dem weiten, fetten Boden, den Du ihnen hast verliehen, haben sie doch Dir nicht gedient und nicht von ihrem schlimmen Treiben abgelassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Deshalb sind heute wir geknebelt, und in dem Land, das unsern Vätern Du geschenkt, damit sie seine Frucht, sein Gut genießen, darin sind wir jetzt Knechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Jetzt mehrt sich sein Ertrag den Königen, die Du ob unseren Sünden über uns gesetzt. Sie schalten nach Belieben über uns und unser Vieh, und wir sind selbst in großer Not.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Trotz alledem sind wir bereit, einen festen Bund zu schließen und ihn zu unterzeichnen. Auf der Urkunde sollen unsere Oberen, Leviten und Priester stehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Auf der Urkunde stand: Nehemias, der Tirsata, Chakaljas Sohn, und Sidkja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Seraja, Azarja, Jirmeja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Paschur, Amarja, Malkia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Chattus. Sebanja, Malluk,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Charim, Meremot, Obadja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Ginneton, Baruk,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mesullam, Abia, Mijjamin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maazja, Bilgai, Semaja. Dies sind die Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Ferner die Leviten: Jesua, Azanjas Sohn, Binnui von Chenadas Söhnen, Kadmiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'und ihre Brüder Sebanja, Hodia, Kelita, Pelaja und Chanan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Mika, Rechob, Chasabja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Zakkur, Serebja, Sebanja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hodia, Bani, Beninu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Die Häupter des Volkes: Paros, Pachatmoab, Elam, Zattu, Bani,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Bunni, Azgad, Bebai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonia, Bigwai, Adin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Chizkia, Azzur,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hodia, Chasum, Besai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Chariph, Anatot, Nebai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpias, Mesullam, Chezir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mesezabel, Sadok, Jaddua,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatja, Chanan, Ananja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hosea, Chananja, Chasub,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Halloches, Pilcha, Sobek,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rechum, Chasabna, Maaseja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'und Achia, Chanan, Anan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Malluk, Charim, Baana.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Die anderen aus dem Volke aber, die Priester, Leviten, Torhüter, Sänger, Tempelsklaven sowie alle, die sich von den Völkern der Länder abgesondert und der Lehre Gottes beigetreten, ihre Frauen, Söhne und Töchter, jeder Kundige und Wissende,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'schließen sich ihren Brüdern, ihren Adligen, an und treten in Eid und Schwur, nach Gottes Lehre zu wandeln, die durch Moses, den Diener Gottes, gegeben worden ist, und alle Gebote des Herrn, unseres Gottes, zu halten und zu befolgen, ebenso seine Rechte und Gesetze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Wir geben weder unsere Töchter den Völkern des Landes, noch freien wir ihre Töchter unseren Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Wir nehmen nichts von den Völkern der Länder, die am Sabbat Waren und allerhand Getreide zum Verkauf bringen, am Sabbat und an einem anderen heiligen Tage. Wir verzichten auf den Ertrag des siebten Jahres und auf jedes Darlehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Wir legen uns als Gesetz auf, jährlich einen Drittelring zum Dienst in unserem Gotteshaus für uns zu geben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Zum Schaubrot, dem täglichen Speiseopfer und dem täglichen Brandopfer, zu den Sabbat- und Neumondopfern, den Festopfern, den Heiligungs- und Sündopfern, um Israel zu Entsündigen, und zu jedem Werke an unserem Gotteshause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Wir haben Lose geworfen, die Priester, Leviten und das Volk, für die Holzspende, um sie in unser Gotteshaus zu bringen, nach Familien zu bestimmter Zeit, Jahr für Jahr. Auf dem Altar des Herrn, unseres Gottes, soll man damit Feuer anzünden, wie es in der Lehre geschrieben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Auch die Erstlinge unseres Ackers und die Erstlinge aller Baumfrucht bringe man Jahr für Jahr ins Haus des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Wir wollen unsere erstgeborenen Söhne und unser Vieh abliefern, wie geschrieben ist in der Lehre, und unser Rindvieh und Kleinvieh an unser Gotteshaus, an die Priester, die in unserem Gotteshause Dienste tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Und den ersten Abhub unseres Brotteigs und unserer Spenden und der Früchte aller Baumarten, des Mostes und des Öles wollen wir an die Priester in die Gemächer unseres Gotteshauses abliefern und den Zehnten unseres Ackers an die Leviten. Die Leviten sollen den Zehnten auch in all den Städten einsammeln, wo wir unter Fremdherrschaft leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Der Priester, der Aaronssohn, begleite die Leviten beim Einsammeln des Zehnten für die Leviten! Die Leviten aber sollen den zehnten Teil des Zehnten in unser Gotteshaus in die Gemächer der Schatzkammer bringen! Denn in die Gemächer sollen die Söhne Israels und die Söhne Levis die Abgaben an Korn, Most und Öl bringen! Dort liegen auch die Sachen des Heiligtums und der diensttuenden Priester, der Torhüter und der Sänger. Wir wollen unser Gotteshaus nicht vernachlässigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'In Jerusalem wohnten die Fürsten des Volkes. Das andere Volk aber warf die Lose, daß je einer von zehn hereinkommen und in Jerusalem, der heiligen Stadt, wohnen solle. Neun Zehntel blieben in den anderen Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Und das Volk segnete alle Männer, die freiwillig beschlossen, in Jerusalem zu wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Dies sind die Häupter der Provinz, die in Jerusalem Wohnung genommen. In den Städten Judas aber war jeder in seinem Besitztum und in seiner Stadt geblieben: Israels Priester, Leviten und Tempelsklaven und die Söhne der Sklaven Salomos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'In Jerusalem hatten Söhne Judas und Söhne Benjamins Wohnung genommen. Von den Söhnen Judas Ataja, der Sohn Uzzias, der Enkel des Zekarja, des Sohnes Amarja, des Sohnes des Sephatja, des Sohnes des Mahalalel, von den Söhnen des Peres,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'und Maaseja, der Sohn Baruks, der Enkel des Kol Chozeh, des Sohnes des Chazaja, des Sohnes des Adaja, des Sohnes des Jojarib, des Sohnes des Zekada, des Sohnes des Siloniten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Alle Peressöhne, die zu Jerusalem wohnten, waren 468 Grundbesitzer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Dies sind die Söhne Benjamins: Sallu, der Sohn Mesullams, der Enkel des Joed, des Sohnes des Pedaja, des Sohnes des Kolaja, des Sohnes des Maaseja, des Sohnes des Isiel, des Sohnes des Jesaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'und nach ihm Gabbai und Salai 928.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Und Joel, Zikris Sohn, war ihr Aufseher, und Juda, Senuas Sohn, war der zweite Aufseher über die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Von den Priestern: Jojaribs Sohn Jedaja, Jakin');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'und Seraja, der Sohn Chilkia, Mesullams Enkel und Urenkel Sadoks, des Sohnes der Merajot und Enkels des Achitub, der Fürst des Gotteshauses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Und ihre Brüder, die den Dienst im Haus besorgten, 822, ferner Adaja, der Sohn des Jerocham, der Enkel des Pelaja und Urenkel des Amri, des Sohnes des Zekarja und Enkel des Paschur, des Sohnes des Malkia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Und seine Brüder, die Familienhäupter, 242, ferner Amassai, der Sohn des Azarel, Enkel des Achzi und Urenkel des Mesillemot, des Sohnes des Immer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'ferner ihre Brüder, Grundbesitzer, 128, und Aufseher über sie war Zabdiel, der Sohn Haggedolims.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Von den Leviten: Semaja, der Sohn Chasubs, der Enkel des Azrikam und Urenkel des Chasabja, des Sohnes des Bunni.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Und Sabtai und Jozabad standen dem äußeren Dienst am Gotteshause vor; sie gehörten zu den Häuptern der Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Und Mattanja, der Sohn des Mika, der Enkel des Zabdi und Urenkel des Asaph, der Hauptführer, der beim Gebet den Gesang anstimmte, und Bakbukja, der zweite unter seinen Brüdern, und Abda, der Sohn des Sammua, der Enkel des Galal und Urenkel des Jeditum,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'sämtliche Leviten in der heiligen Stadt waren es 284.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Die Torhüter waren Akkub, Talmon und ihre Brüder, die Wächter bei den Toren, 172.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Und das übrige Israel, die Priester, die Leviten, waren in allen Städten Judas, jeder auf seinem Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Und die Tempelsklaven wohnten auf dem Ophel. Sicha und Gispa standen den Tempelsklaven vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Der Aufseher der Leviten zu Jerusalem war Uzzi, der Sohn des Bani, der Enkel des Chasabja und Urenkel des Mattanja, des Sohnes des Mika, von den Asaphsöhnen, den Sängern, beim Dienst im Gotteshause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Denn ein königlicher Befehl lag für sie vor und eine Verpflichtung für die Sänger auf jeden Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petachja, Mesezabels Sohn, von den Söhnen des Zerach, des Sohnes Judas, stand dem König zur Seite in allen Angelegenheiten des Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'In den Ortschaften auf ihren Feldmarkungen wohnten von den Söhnen Judas solche in Kirjatarba und seinen Dörfern, in Dibon und seinen Dörfern, in Jekabzeel und seinen Gehöften,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'in Jesua, Molada, Betpelet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'in Chasarsual und Beerseba und seinen Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'in Siklag und Mekona und seinen Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'in Enrimmon, Sora und Jarmut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'in Zanoach, Adullam und ihren Gehöften, in Lakis und seinen Feldmarken, in Azeka und seinen Dörfern. Sie siedelten also von Beerseba bis zum Hinnomstale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Die Söhne Benjamins waren von Geba an zu Mikmas und Ajja, sowie in Betel und seinen Dörfern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'in Anatot, Nob, Ananja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'in Chasor, Rama, Gittaim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'in Chadid, Seboim, Niblat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'in Lod, Ono, und in Gehacharasim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Von den Leviten waren Abteilungen in Juda und in Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Dies sind die Priester und die Leviten, die mit Zerubbabel, dem Sohn Sealtiels und Jesua hergezogen sind: Seraja, Irmeja, Ezra,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluk, Chattus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekanja, Rechum, Meremot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoi, Abia,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijjamin, Maadja, Bilga,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Chilkia, Jedaja. Dies sind die Häupter der Priester und ihrer Brüder in Jesuas Tagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Und die Leviten sind: Jesua, Binnui, Kadmiel, Serebja, Jehuda, Mattanja. Dieser und seine Brüder leiteten den Dankgesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Und Bakbukja und Unni, ihre Brüder, standen ihnen gegenüber in ihren Abteilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua zeugte Jojakim und Jojakim den Eljasib, Eljasib den Jojada.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada zeugte Jonatan und Jonatan den Jaddua.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'In Jojakims Tagen waren Priester die Familienhäupter: für Seraja Merarja, für Irmeja Chananja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'für Ezra Mesullam, für Amarja Jehochanan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'für Malkia Jonatan, für Sebanja Joseph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'für Charim Adna, für Merajot Chalkai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'für Iddo Zekarja, für Ginneton Mesullam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'für Abia Zikri, für Mijjamin..., für Moadja Piltai,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'für Bilga Sammua, für Semaja Jehonatan');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'und für Jojarib Mattenai, für Jedaja Uzzi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'für Sallai Kallai, für Amok Eber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'für Chilkia Chasabja, für Jedaja Netanel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Von den Leviten sind in den Tagen Eljasibs, Jojadas, Jochanans und Jadduas die Familienhäupter verzeichnet worden, ebenso die Priester unter der Regierung des Persers Darius.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Die Söhne Levis, die Familienhäupter, sind im Buche der Geschichte bis auf die Zeit Jochanans, des Sohnes Eljasibs, verzeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Die Häupter der Leviten sind Chasabja, Serebja und Jesua, Kadmiels Sohn, und ihre Brüder, die ihnen gegenüberstanden, um die Lob- und Danklieder zu singen nach der Vorschrift Davids, des Gottesmannes, Abteilung neben Abteilung:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattanja und Bakbukja, Obadja, Mesullam, Talmon, Akkub, Wächter, Torhüter, die bei den Speichern der Tore Wache halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Diese waren da zur Zeit Jojakims, des Sohnes des Jesua, des Sohnes des Josadak, und zur Zeit Nehemias, des Statthalters, und Ezras, des Priesters und Schreibers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Bei der Einweihung der Mauer Jerusalems suchte man in allen ihren Orten die Leviten, um sie nach Jerusalem zu holen. Sie sollten freudig mit Dankliedern, Gesängen, Zimbeln, Harfen und Liedern das Weihe- und Dankfest feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Und die Söhne der Tempelsänger kamen zusammen, die einen aus dem Gau, der Umgebung von Jerusalem, die anderen aus den Gehöften der Netophatiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'aus Bet Haggilgal und aus den Feldmarken von Geba und Azmawet. Denn die Sänger hatten sich Gehöfte rings um Jerusalem gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Dann reinigten sich die Priester und Leviten. Sie reinigten auch das Volk, die Tore und die Mauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Ich ließ nun die Obersten Judas die Mauer besteigen. Zwei große Chöre stellte ich auf. Der eine zog auf der Mauer rechts hin bis zum Misttor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Ihnen folgte Hosaja, dabei die eine Hälfte der Oberen Judas,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'sowie Azarja, Ezra, Mesullam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Jehuda, Benjamin, Semaja, Irmeja,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'und von den Priestern mit Trompeten Zekarja, der Sohn Jonatans, der Enkel Semajas, des Sohnes Mattanjas, des Sohnes Mikajas, des Sohnes Zakkurs, des Sohnes Asaphs,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'und seine Brüder Semaja, Azarel, Milalei, Gilalei, Maai, Netanel, Jehuda, Chanani mit den Saitenspielen des Gottesmannes David. Der Schreiber Ezra ging vor ihnen her');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'zum Quelltor hin. Sie stiegen dann geradeaus die Stufen zur Davidsstadt hinauf, auf jenem Anstieg an der Mauer oberhalb des Davidshauses bis zum Wassertor im Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Der andere Chor zog nach links. Ich selbst folgte ihm mit der Hälfte des Volkes auf der Mauer oberhalb des Ofenturmes bis zur breiten Mauer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'dann oberhalb des Tores Ephraim und über das Jesanator, das Fischtor, den Chananelsturm und den Meaturm bis zum Schaftor. Sie stellten sich bei dem Gefängnistor auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Dann stellten sich beide Chöre am Gotteshause auf. Ich selbst und mit mir die Hälfte der Vorsteher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'sodann die Priester Eljakim, Maaseja, Minjamin, Mikaja, Eljoënai, Zekarja und Chananja mit Trompeten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'und Maaseja und Semaja, Eleazar, Uzzi, Jehonatan, Malkia, Elam und Ezer. Dann ließen sich die Sänger unter Izrachjas Leitung hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'An jenem Tage schlachteten sie große Schlachtopfer und freuten sich, weil ihnen Gott eine große Freude bereitet hatte. Auch die Frauen und Kinder freuten sich. Der Jubel aus Jerusalem ward weithin gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'An jenem Tage wurden Männer zur Aufsicht über die Gemächer der Vorräte angestellt; sie sollten die Abgaben, den ersten Abhub und Zehnten von den Feldern der Städte, die gesetzlichen Gaben für Priester und Leviten sammeln. Denn Juda hatte Freude an den Priestern und Leviten, wenn sie Dienste taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Sie besorgten ihren Gottesdienst und den Dienst der Reinigung, ebenso die Sänger und die Torhüter nach dem Geheiß Davids und seines Sohnes Salomo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Denn schon in Davids und Asaphs Zeit im Altertum gab es Sängerhäupter für den Lobgesang und Dank gegen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ganz Israel gab in den Tagen des Zerubbabel und denen des Nehemias Geschenke an die Sänger und Torhüter Tag für Tag. Sie gaben auch solche den Leviten, und die Leviten gaben solche den Aaronssöhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'An jenem Tage wurde dem Volke aus dem Buche Mosis laut vorgelesen. Man fand da geschrieben, daß nie Ammoniter oder Moabiter in die Gemeinde Gottes kommen dürfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Sie hatten den Söhnen Israels nicht Brot noch Wasser angeboten, sondern den Bileam gedungen, sie zu verfluchen. Aber unser Gott wandelte den Fluch in Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Als sie die Lehre hörten, schieden sie alle Mischlinge aus Israel aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Vordem war der Priester Eljasib, der über unseres Gotteshauses Zellen gesetzt war, mit dem Tobia verwandt geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Er richtete ihm eine große Zelle ein, in der man sonst das Speiseopfer, den Weihrauch und die anderen Sachen tat, sowie den Zehnten von Korn, Most und Öl, Pflichtteil für die Leviten, Sänger und Torhüter und die Gaben für die Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Ich bin während alldem nicht in Jerusalem gewesen. Denn im zweiunddreißigsten Jahre des Babelkönigs Artachsast war ich zum König gekommen. Nach einiger Zeit hatte ich mir aber vom König Urlaub genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Dann kam ich wieder nach Jerusalem. Dann merkte ich den Frevel, den Eljasib Tobia zulieb verübt hatte, daß er ihm eine Zelle in den Höfen des Gotteshauses eingeräumt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Dies empörte mich aufs tiefste. Und so warf ich alle Sachen aus dem Hause des Tobia, aus jener Zelle, auf die Straße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Dann hieß ich die Zellen reinigen und brachte dorthin die Sachen aus dem Gotteshause, das Speiseopfer und den Weihrauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Auch erfuhr ich, daß die Gaben an die Leviten nicht abgeliefert worden waren und daß von den Leviten und den Sängern, die den Dienst besorgen sollten, jeder auf sein Landgut gelaufen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Da schalt ich die Vorsteher und sprach: \"Warum ist das Gotteshaus vernachlässigt?\" Dann holte ich sie zusammen und stellte sie auf ihre Posten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Nun brachte ganz Juda den Zehnten von Korn, Most und Öl in die Speicher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Dann setzte ich über die Speicher den Priester Selemja, den Schreiber Sadok und von den Leviten Pedaja und als ihren Helfer Chanan, Zakkurs Sohn, den Enkel des Mattanja. Denn sie galten als zuverlässig. Ihre Pflicht war es, für ihre Brüder zu teilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Gedenke mir dies, mein Gott, und lösche nicht meine guten Werke aus, die ich dem Hause meines Gottes und seinen Abteilungen getan habe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'In jenen Tagen hatte ich in Judäa Leute gesehen, die am Sabbat Kelter traten und Korn einfuhren, die Esel beluden und Wein, Trauben, Feigen und allerlei Ware am Sabbattage nach Jerusalem einführten. Ich warnte um des Tages willen, an dem sie die Lebensmittel feilboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Die Fremden, die darin wohnten, führten Fische und sonstige Ware ein und verkauften sie am Sabbattag den Söhnen Judas zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Da schalt ich Judas Edle und sprach zu ihnen: \"Welcher Frevel ist das, den ihr tut, daß ihr den Sabbattag entweiht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Haben nicht also eure Väter getan? Da brachte unser Gott über uns und diese Stadt all dies Unheil. Wollt ihr über Israel noch mehr Zorn bringen, daß ihr den Sabbattag entweiht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Sobald nun vor dem Sabbat die Tore Jerusalems dunkelten, hieß ich die Tore schließen. Auch befahl ich, daß man sie vor Sabbatschluß nicht öffne. Ich stellte auch einige von meinen Knappen an die Tore, daß keine Ware am Sabbattag hereinkäme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'So übernachteten die Händler und die Verkäufer von allerhand Waren draußen vor Jerusalem, so ein-, zweimal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Ich verwarnte sie und sprach zu ihnen: \"Warum übernachtet ihr vor der Mauer? Tut ihr dies nochmals, dann lege ich Hand an euch.\" Von dieser Zeit an kamen sie nicht mehr am Sabbat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Dann sagte ich den Leviten, sie sollten sich reinigen, hingehen und die Tore hüten, um den Sabbattag zu heiligen. Auch dies gedenke mir, mein Gott! Erbarm Dich meiner nach Deiner großen Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'An jenen Tagen sah ich nach den Judäern, die asdoditische, ammonitische und moabitische Weiber heimgeführt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Die Hälfte ihrer Kinder redete asdoditisch; aber jüdisch konnten sie nicht reden, sondern nur in der Sprache irgendeines Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Da schalt ich sie und fluchte ihnen. Einige von ihnen schlug ich und zerzauste sie. Bei Gott beschwor ich sie: \"Gebt nicht eure Töchter ihren Söhnen und nicht von ihren Töchtern euren Söhnen und nehmt euch selbst nicht solche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hat nicht um solcher willen Salomo, Israels König, gesündigt? Obwohl unter den vielen Völkern kein König gewesen wie er und er seines Gottes Liebling gewesen ist, so daß ihn Gott zum König über ganz Israel machte, so haben ihn doch die fremden Weiber zur Sünde verführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Ist es recht von euch, daß ihr all diesen großen Frevel tut und gegen unseren Gott untreu werdet durch Heimführung fremder Weiber?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Von den Söhnen Jojadas, des Sohnes des Hohenpriesters Eljasib, war einer Schwiegersohn des Sanballat aus Choronaim. Ich jagte ihn von mir fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Gedenke es ihnen, mein Gott, wie sie das Priestertum befleckt haben, den Bund des Priestertums und der Leviten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Von allem Fremden reinigte ich sie; dann bestellte ich die Posten der Priester und der Leviten, jeden für sein Amt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Auch für die Holzspenden zu bestimmten Zeiten und für die Erstlingsfrüchte. Gedenke mir dies, mein Gott, rechne es mir zum Besten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'In der Zeit des Ahasveros - das ist jener Ahasveros, der einst von Indien bis nach Äthiopien über 127 Länder herrschte - trug dies sich zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'In jenen Tagen also, da sich König Ahasveros sicher fühlte auf dem Thron seines Königtums zu Susan in der Burg,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'im dritten Jahre seines Herrschertums, gab er ein Gastmahl allen seinen Dienern und Beamten, wobei vor ihm zur Schau auslagen die Schätze Persiens und Mediens, der Vornehmen und der Beamten der Provinzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Er ließ sehen den Reichtum seiner königlichen Herrlichkeit sowie die Kostbarkeiten seiner wundervollen Größe viele Tage, 180 Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Als diese Tage nun zu Ende waren, bereitete der König allem Volk zu Susan in der Burg, vom Größten bis zum Kleinsten, ein Gastmahl sieben Tage lang im Vorhofe des königlichen Schloßgartens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Ganz weißes Baumwollzeug und Purpurtuch war da, mit Linnen und mit Purpurschnüren an Silberringen und an Marmorsäulen festgemacht. Polster von Gold und Silber erhoben sich auf Steinpflaster von Alabaster, von weißem Marmor und Perlmutterstein und von geflecktem Marmor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Getränke aber reichte man in goldenen Gefäßen, wobei ein jegliches Gefäß verschieden war, und königlicher Wein war viel vorhanden, entsprechend der Freigebigkeit des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Das Trinken aber richtete sich ganz nach dem Befehl, daß niemand wehren sollte. Denn also hatte es der König für alle Großen seines Hauses zur Regel aufgestellt, daß jeder nach Belieben handeln solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Ein Mahl gab auch die Königin Vasthi für die Frauen im Haus der Königinnen, die König Ahasveros hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Am siebten Tage ward vom Wein des Königs Sinn gar fröhlich, und da befahl er Mehuman, Bizzeta, Charbona, Bigeta, Abageta, Zetar und Karkas, den sieben Kämmerlingen, die vor dem König Ahasveros Dienste taten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'sie sollten jetzt die Königin Vasthi im königlichen Diadem vor den König bringen, um den Nationen und Beamten ihre Schönheit öffentlich zu zeigen. Sie war von schönem Aussehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Die Königin Vasthi aber sträubte sich, auf den durch die Eunuchen übermittelten Befehl des Königs zu erscheinen. Da ward der König zornig. Sein Ingrimm loderte in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Der König sagte zu den Weisen, die auf die Zeiten sich verstehen - denn also pflegte man des Königs Wort all den Gesetzes- und Rechtkundigen vorzulegen -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'die Zutritt zu ihm hatten, das waren Karchena, Schetar, Admata, Tarsis, Meres, Marsena, Memukan, der Perser und der Meder sieben Fürsten, die ganz allein des Königs Antlitz sehen durften und die den Vorsitz in dem Reiche führten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '\"Was ist nach dem Gesetz mit Königin Vasthi zu tun, daß sie den durch Eunuchen übermittelten Befehl des Königs Ahasveros nicht befolgt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Da sagte vor dem Könige und den Beamten Memukan: \"Nicht an dem Könige allein versündigt sich die Königin Vasthi. Nein! Auch an allen Fürsten, allen Völkern, die in allen Landen des Königs Ahasveros wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'So endet ja der Fall der Königin für alle Frauen, daß ihnen ihre Ehemänner verächtlich dünken, indem sie sagen: \'Der König Ahasveros hat befohlen, die Königin Vasthi vor sich zu bringen, und sie kam nicht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Von diesem Tag an sagen dann der Perser und der Meder Fürstinnen, die von dem Fall der Königin gehört, zu all den königlichen Fürsten so. Dann gibt\'s Mißachtung und Verdruß genug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Ist\'s nun dem König recht, so möge jetzt ein königlicher Erlaß von ihm ausgehen und unter den Gesetzen aufgezeichnet werden, die bei den Persern und bei den Medern sind, daß er nicht aufgehoben werden kann, nie wieder dürfe Vasthi vor den König Ahasveros kommen. Der König gebe ihre königliche Stellung einer anderen, die besser ist als sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Wird so des Königs Anordnung gehört, die er in seinem ganzen Reich erlassen soll, weil sie so wichtig ist, dann geben alle Frauen ihren Ehemännern abermals die Ehre, vom Größten bis zum Kleinsten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Und gut gefiel der Rat dem König und den Fürsten. Und also tat der König nach dem Rate Memukans.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Er sandte Schreiber aus in alle königlichen Lande, in jegliche Provinz, entsprechend ihrer Schrift zu jedem Volke je nach seiner Sprache: \"Ein jeder Mann soll Herr in seinem Hause sein und nach der Sprache seines Volks befehlen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Doch später legte sich der Zorn des Königs Ahasveros. Und er gedachte Vasthis und was sie getan und was dann über sie beschlossen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Da machten nun des Königs Höflinge und Leibdiener den Vorschlag: \"Man suche für den König jugendlich anmutige Jungfrauen\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'und dann bestellte der König in allen Landen seines Reichs Beamte, damit sie jede jugendlich anmutige Jungfrau in die Burg nach Susan in das Frauenhaus verbrächten, zur Obhut Hegais, eines königlichen Kämmerlings, des Aufsehers der Frauen! Man gebe ihnen nur die rechten Schönheitsmittel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Und jenes Mädchen, das dem König gefällt, soll Königin an Vasthis Stelle werden.\" Dem König gefiel der Vorschlag gut. Und also tat er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Da war ein Mann, ein Jude, in der Burg zu Susan mit Namen Mordekai, der Sohn des Jair und Enkel Simeis, des Sohnes des Kis, vom Stamme Benjamin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'der aus Jerusalem einstmals weggeführt, zugleich mit den Gefangenen, die mit dem Judakönig Jechonja waren weggeführt worden, die Nebukadrezar, der Babelkönig, wegführte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Er war der Pflegevater Hadossas, das ist der Esther, seines Oheims Tochter, da sie weder Vater noch Mutter mehr hatte. Das Mädchen aber war von herrlicher Gestalt und schönem Aussehen. Und als der Vater und die Mutter starben, nahm Mordekai sie selbst als Tochter an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Nun wurden der Erlaß des Königs und sein Befehl bekanntgegeben. Da brachte man zur Burg nach Susan viele Mädchen zur Obhut Hegais dort zusammen. So ward auch Esther in dem Haus des Königs der Obhut Hegais, des Aufsehers der Frauen, unterstellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Und ihm gefiel das Mädchen gut, so daß sie Gnade vor ihm fand. Eifrig war er darauf bedacht, die rechten Schönheitsmittel ihr zu liefern, sowie die rechte Kost und ihr die sieben auserwähltesten der Dienerinnen aus dem königlichen Haus zu geben. Er zeichnete sie und ihre Dienerinnen in dem Frauenhause aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Doch Esther hatte weder ihr Volk noch ihre Herkunft angegeben; denn Mordekai hatte es ihr streng verboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Und Tag für Tag ging Mordekai vor dem Hof des Frauenhauses auf und ab, zu forschen, ob es Esther wohl ergehe und was mit ihr geschehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kam dann die Reihe an ein jedes Mädchen, einzeln sich zu dem König Ahasveros zu begeben, nachdem man so mit ihr gemäß den Vorschriften, die für die Frauen gelten, zwölf Monde lang verfahren hatte - denn soviel Zeit verging schon über ihrer Schönheitspflege, sechs Monde mit Myrrhenöl, sechs Monde mit Balsamen und anderen Schönheitsmitteln für die Frauen -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'so kam auf solche Art zum König das Mädchen. Was sie verlangte, wurde ihr gegeben, um sie vom Frauenhause bis zum königlichen Hause zu begleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Am Abend ging sie hinein; am Morgen kehrte sie zum Frauenhaus zurück, und zwar ins zweite in die Obhut des Sasgaz, des königlichen Kämmerlings, des Aufsehers der Weiber; sie durfte nimmermehr zum König kommen. Nur wenn der König sollte je an ihr Gefallen finden, dann würde sie mit ihrem Namen aufgerufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'So kam die Reihe auch an Esther, die Tochter Abichails, des Oheims Mordekais, der sie als Tochter angenonunen, zum König zu gehen. Und sie verlangte gar nichts weiter, als was der königliche Kämmerling Hegai, der Aufseher der Frauen, gab. Jedoch erwarb sich Esther Gunst bei allen, die sie sahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Und so ward Esther zu dem König Ahasveros in das königliche Schloß geholt am zehnten Neumond, das ist im Monat Tebet, im siebten Jahre seiner Herrschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Und da gewann der König Esther lieb, mehr als alle anderen Jungfrauen. Und sie erwarb sich Gunst und Huld vor ihm, mehr als die anderen Jungfrauen all. Er setzte ihr ein königliches Diadem aufs Haupt und machte sie an Vasthis Statt zur Königin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Der König gab ein großes Mahl für alle seine Fürsten und für seine Diener, das Gastmahl Esthers. Und den Provinzen gab er Steuernachlaß. Und er gewährte eine Spende, königlich freigebig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Als man die Jungfrauen verschiedener Abstammung zusammenholte - beim Tor des Königs aber wohnte Mordekai -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'gab Esther ihre Herkunft und ihr Volk nicht an, wie Mordekai es ihr befohlen. So folgte Esther dem Befehl des Mordekai wie damals, als sie noch in Pflege bei ihm war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'In jenen Tagen, als Mordekai beim Tor des Königs wohnte, erzürnten sich einst Bigetan und Teres, die beiden königlichen Kämmerlinge, die zudem Schwellenhüter waren, und trachteten danach, an König Ahasveros Hand zu legen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Die Sache aber wurde Mordekai bekannt. Und er erzählte es der Königin Esther, und Esther sagte es im Namen Mordekais dem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Als man der Sache heimlich nachspürte, da wurden sie ertappt und beide an das Holz gehängt. Und dies ward im Buch der Chronik für den König aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Hernach verlieh der König Ahasveros dem Haman, Hammedatas Sohn, dem Agagiter, eine hohe Stellung und zeichnete ihn aus und setzte seinen Stuhl dem aller Fürsten bei ihm vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Und alle königlichen Diener in dem königlichen Tore beugten ihre Knie und warfen sich vor Haman nieder. So hatte es der König für ihn angeordnet. Doch Mordekai wollte seine Knie nicht beugen und sich nicht niederwerfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Die königlichen Diener in dem königlichen Tore fragten Mordekai: \"Weswegen übertrittst du das Gebot des Königs?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Als sie\'s nun täglich zu ihm sagten, er aber niemals auf sie hörte, da zeigten sie\'s dem Haman an, damit sie sähen, ob Mordekais Ausrede gelte. Er hatte nämlich mitgeteilt, er sei ein Jude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Als Haman sah, daß Mordekai seine Knie nicht vor ihm beugte und sich nicht niederwarf, ward Haman voller Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Doch deuchte es ihm gar verächtlich, an Mordekai allein die Hand zu legen. Man hatte ihm das Volkstum Mordekais auch mitgeteilt. So trachtete Haman danach, die Juden all im ganzen Reich des Ahasveros, die Volksgenossen Mordekais, zu vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Am ersten Neumond, das ist im Monat Nisan, im zwölften Jahr des Königs Ahasveros, warf man das Pur, das ist das Los, vor Haman, von einem Tag zum anderen, von einem Monat zum anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Da sagte Haman zum König Ahasveros: \"Es gibt ein ganz besonderes Volk, das bei den Völkern da in allen Ländern deines Reiches zerstreut und abgesondert lebt. Verschieden auch sind seine Vorschriften von denen jedes anderen Volkes. Sie folgen nicht den Satzungen des Königs, daß es dem König gar nichts nützt, sie so gewähren zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ist es dem König recht, so möge schriftlich angeordnet werden, sie zu vernichten. Dann kann ich zehntausend Talente Silber den Schatzbeamten darwägen, damit sie\'s in die Schatzkammern des Königs überführen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Da zog der König seinen Siegelring von seiner Hand und übergab ihn Haman, Hammedatas Sohn, dem Agagiter, dem Feind der Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Der König sprach dabei zu Haman: \"Das Silber sei dir überlassen sowie das Volk, daß du ihm tust nach Belieben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Des Königs Schreiber wurden in dem ersten Monat am dreizehnten berufen und so, wie\'s Haman angeordnet, erging ein schriftlicher Befehl, sowohl an die Satrapen wie an die Statthalter, die über den einzelnen Provinzen standen, an die Beamten all der Völker, der Schriftart einer jeden einzelnen Provinz entsprechend, sowie der Sprache jeder einzelnen Nation. Und der Befehl war in des Königs Ahasveros Namen abgefaßt und mit dem königlichen Siegelring versiegelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Die Schreiben wurden abgesandt durch Eilboten in alle königlichen Länder mit dem Befehl, die Juden alle zu vertilgen, zu töten und sie zu vernichten, die jungen wie die Alten und Kinder mit den Weibern an einem Tag, am dreizehnten des zwölften Monds, das ist im Monat Adar, und ihre Habe als Beute zu verteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Des Schreibens Inhalt ging dahin, es solle ein Gesetz in jeder einzelnen Provinz erlassen werden und allen Völkern kundgetan, daß sie auf diesen Tag gerüstet wären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Eilends zogen Eilboten auf königlich Geheiß hinaus, sobald das Gesetz zu Susan in der Burg erlassen war. Der König aber setzte sich zu einem Trinkgelage mit Haman nieder. Inzwischen aber kam die Stadt Susan in Aufregung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Und Mordekai erfuhr all die Begebnisse. Und Mordekai zerriß die Kleider und nahm ein rauhes Kleid und Asche und ging so mitten in die Stadt hinaus, laut und bitterlich wehklagend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'So kam er bis vors königliche Tor. Denn in das königliche Tor darf man mit einem rauhen Kleid nicht treten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'In jeder einzelnen Provinz, wohin nur der Erlaß und das Gesetz des Königs kamen, war große Trauer bei den Juden und Fasten, Weinen, Wehklagen. Die meisten breiteten ein rauhes Kleid und Asche unter sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Da kamen Esthers Dienerinnen und teilten es ihr mit. Da ward die Königin von tiefem, großem Schmerz erfüllt. Sie sandte Kleider, daß man sie Mordekai anlege und er das rauhe Kleid abstreife. Doch nahm er sie nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Danach rief Esther von den königlichen Kämmerlingen Hatak, der ihr zu Diensten stand, und hieß ihn wegen Mordekai erkunden, was dies bedeute, weswegen es geschehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Darauf besuchte Hatak Mordekai beim städtischen Markte oben, der vor dem Königstore lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Und Mordekai berichtete ihm alle die Begebnisse, auch die genaue Anordnung wegen des Silbers, das Haman für die königlichen Kammern darzuwägen schon versprach, als Preis für die Vernichtung aller Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Er tat ihm auch den Inhalt jener Vorschrift kund, die wegen ihres Untergangs in Susan war erlassen, daß er sie Esther zeige und ihr künde und sie zum Könige zu gehen heiße, ihn um Erbarmen anzuflehen und für ihr Volk Fürbitte bei ihm einzulegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Und Hatak kam und meldete die Worte Mordekais der Esther.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Und Esther redete mit Hatak und sandte ihn zu Mordekai:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '\"Die königlichen Diener alle wissen, wie auch die Leute in den königlichen Landen, daß jedermann, Mann oder Weib, der zu dem König ungerufen in den inneren Vorhof geht, dem Gesetz verfällt, das seine Tötung fordert, den ausgenommen, gegen den der König das goldene Zepter ausstreckt; der bleibt am Leben. Ich aber bin seit dreißig Tagen nicht mehr zum Könige berufen worden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Man sagte Mordekai die Worte Esthers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Und Mordekai ließ Esther wieder sagen: \"Glaube nicht, du kommst davon mit deinem Leben, du ganz allein von allen Juden, in dem königlichen Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Nein, schwiegst du still zu dieser Zeit, so käme Befreiung und Errettung für die Juden wohl von anderer Seite. Du aber kommst samt deinem Hause um. Wer weiß, ob du nicht grad für solche Zeit zum Königtum gelangtest?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Darauf ließ Esther Mordekai vermelden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '\"Geh hin, versammle alle Juden, die sich zu Susan finden, und fastet dann für mich und eßt und trinkt drei Tage lang nichts bei Nacht und nichts bei Tag! Ich will mit meinen Dienerinnen gleichfalls fasten. Und dann geh ́ ich zum König, obwohl es dem Gesetz zuwider ist. Doch sollte ich umkommen, so komm ich eben um.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Und Mordekai ging fort und tat, wie Esther ihn geheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Am dritten Tage war\'s, da kleidete sich Esther königlich und stellte sich in den inneren Vorhof im königlichen Haus, dem königlichen Hause gegenüber. Der König aber saß auf seinem Königsthron im königlichen Haus, dem Haupttor gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Wie nun der König im Vorhofe die Königin Esther stehen sah, da fand sie Huld in seinen Augen, und alsbald streckte der König gegen Esther hin das goldene Zepter, das sich in seiner Hand befand. Und Esther trat heran und rührte an des Zepters Spitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Da sprach zu ihr der König: \"Was hast du, Königin Esther? Was ist dein Begehr? Ja, bis zum halben Königreich soll dir bewilligt sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Und Esther sprach: \"Ist es dem König recht, so komme der König heute mit Haman zu dem Mahl, das ich ihm richte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Da sprach der König: \"Holt Haman schnell herbei, damit wir Esthers Wunsch erfüllen!\" Der König ging mit Haman zu dem Mahl, das Esther hergerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Und bei dem Weingelage fragte sie der König: \"Was ist jetzt deine Bitte? Sie sei dir schon gewährt! Was ist dein Begehr? Ja, bis zum halben Reich soll dir bewilligt sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Und Esther gab zur Antwort: \"Mein Bitten und Begehren ist -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'fand ich in des Königs Augen Gnade, gefällt es so dem König, meine Bitte zu gewähren und mein Begehren zu bewilligen -, so komme der König wiederum mit Haman zu dem Mahl, das ich für sie bereite! Ich tue morgen nach des Königs Wunsch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Und Haman ging an jenem Tage froh und guten Muts von dannen. Im Königstor erblickte aber Haman Mordekai, wie dieser weder sich erhob noch überhaupt sich vor ihm rührte. Da wurde Haman über Mordekai voll Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Doch Haman hielt noch an sich. Als er jedoch nach Hause kam, beriet er seine Freunde samt Zeres, seinem Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Und Haman sprach zu ihnen von seinem großen Reichtum und der Menge seiner Söhne, von all dem, wie der König ihn so hoch geehrt und über Fürsten und des Königs Diener ihn erhoben habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Und Haman sprach: \"Ja, Esther selbst, die Königin, hat mit dem König zu dem Mahl, das sie bereitet, gar niemand anders kommen lassen als nur mich. Und auch für morgen wurde ich von ihr mitsamt dem König eingeladen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Doch all dies nützt mir nichts, solang ich noch den Juden Mordekai im Königstore sitzen sehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Darauf erwiderten ihm seine Gattin Zeres und alle seine Freunde: \"Man richte einen Galgen her, an fünfzig Eilen hoch, und morgen früh sprich mit dem König, daß man daran den Mordekai aufhänge! Alsdann geh mit dem König fröhlich zu dem Mahl!\" Und dies gefiel dem Haman wohl. So ließ er einen Galgen machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Den König floh in jener Nacht der Schlaf. Da ließ er sich das Buch mit den geschichtlichen Denkwürdigkeiten bringen. Man las sie nun dem König vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Da fand sich aufgezeichnet, wie Mordekai berichtet habe von Bigetan und Teres, zwei königlichen Kämmerlingen, die bei den Schwellenhütern waren, daß sie den König Ahasveros töten wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Da sprach der König: \"Was ist an Ehren und an Würden deshalb Mordekai erwiesen worden?\" Des Königs Diener, die ihm Dienste taten, sprachen: \"Nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Da fragte der König: \"Wer ist im Vorhof?\" Und da betrat den äußeren Vorhof in dem königlichen Hause Haman, um mit dem Könige zu reden, man soll Mordekai an einen Galgen hängen, den er für diesen hergerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Des Königs Diener gaben ihm zur Antwort: \"Sieh, Haman steht im Vorhof!\" Da sprach der König: \"Er trete ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Alsdann trat Haman ein. Der König sprach zu ihm: \"Was soll dem Mann geschehen, den da der König ehren will?\" Und Haman dachte: \"Wen wird der König ehren wollen, wenn nicht mich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Und Haman sprach zum König: \"Will schon der König jemand ehren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'dann bringe man ein königliches Kleid herbei, mit dem der König sich bekleidet, sowie ein Roß, das einst der König ritt zur Zeit, da man die Königskrone auf sein Haupt gesetzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'und übergebe das Gewand sowie das Roß dann einem von den königlichen Fürsten, von den Edlen, daß man den Mann bekleide, den da der König ehren möchte, und diesen auf dem Rosse auf dem Stadtplatz reiten lasse, und daß man vor ihm ausrufe: \'Also geschieht dem Manne, den der König ehren möchte.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Darauf erwiderte der König Haman: \"Hol eilends das Gewand sowie das Roß, gerade so, wie du gesagt, und tue so mit Mordekai, dem Juden, der bei dem Königstore wohnt! Doch unterlasse nichts von alledem, was du gesagt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Da holte Haman das Gewand sowie das Roß, bekleidete den Mordekai und ließ ihn auf dem Stadtplatz reiten und rief vor ihm: \"Also geschieht dem Manne, den der König ehren möchte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Dann kehrte Mordekai zum Königstor zurück. Doch Haman lief gar schnell nach Haus, ganz traurig, mit verhülltem Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Und Zeres, seinem Weib, und allen Freunden sagte Haman, was ihm begegnet war. Da sprachen seine Weisen samt Zeres, seinem Weib, zu ihm: \"Ist von dem Judenstamme Mordekai, vor dem zu fallen du begonnen hast, alsdann vermagst du gegen ihn nichts weiter. Du fällst vor ihm ganz sicher.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Solange Sie noch mit ihm sprachen, erschienen schon des Königs Kämmerlinge und führten Haman eilends zu dem Mahl, das Esther hergerichtet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Der König trat mit Haman ein, um bei der Königin Esther zu zechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Der König fragte auch am zweiten Tag beim Weingelage Esther: \"Was ist jetzt deine Bitte, Königin Esther? Sie soll dir schon bewilligt sein! Was ist dein Begehr? Ja, bis zum halben Reich soll dir bewilligt sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Da gab die Königin Esther diese Antwort: \"Fand Gnade ich in deinen Augen, König, und ist\'s dem König recht, so sei auf meine Bitte hin mein Leben mir geschenkt, sowie auf mein Begehr mein Volk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Sind wir ja doch verkauft, ich und mein Volk, zu gänzlicher Vernichtung, zu Tötung und zu Tilgung. Ja, würden wir als Sklaven und als Sklavinnen verkauft, ich hätte geschwiegen, wiegt doch der Feind des Königs Schaden nimmer auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Da sprach der König Ahasveros eilends zu der Königin Esther: \"Wer ist doch der, und wo ist der, dem\'s in den Sinn kam, so zu tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Darauf sprach Esther: \"Mein Geliebter, der Mann, der Feind und Widersacher, ist Haman da.\" Da wurde Haman arg bestürzt vor dem König und der Königin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Da stand der König stark erregt vom Weingelage auf; er wollte in den Garten des Palastes gehen. Doch Haman blieb zurück; er wollte für sein Leben bei der Königin Esther flehen. Er merkte nämlich, daß von dem König Unheil über ihn beschlossen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Der König kehrte aus dem Garten des Palasts zurück ins Haus des Weingelages. Da warf sich Haman eben auf das Polster, worauf die Esther lag. Da rief der König: \"Soll etwa gar der Königin Gewalt geschehen, solang ich noch im Hause bin?\" Kaum war das Wort dem königlichen Mund entflohen, als man schon Hamans Angesicht verhüllte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Da sprach Harbona, einer von den Kämmerlingen, vor dem König: \"Es steht ja übrigens in Hamans Hause, fünfzig Ellen hoch, der Galgen, den Haman für den Mordekai hat machen lassen, der doch zum Heile für den König einst geredet.\" Da sprach der König: \"Hängt ihn daran!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'So hängte man den Haman an den Galgen, den er für Mordekai hatte herrichten lassen. Dann legte sich des Königs Aufregung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'An jenem Tage gab der König Ahasveros der Königin Esther das Haus des Haman, dieses Judenfeindes, zum Geschenk, und Mordekai erhielt zum König Zutritt. Denn Esther hatte mitgeteilt, wie dieser zu ihr stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Der König nahm dann seinen Siegelring, den er dem Haman hatte nehmen lassen, und gab ihn Mordekai. Und Esther setzte über Hamans Haus den Mordekai.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Und Esther sprach vorm König abermals, fiel ihm zu Füßen, weinend und ihn um Gnade bittend, er möge das Unheil wenden, das von dem Agagiter Haman angerichtet, und seinen Anschlag, den er gegen alle Juden geschmiedet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Der König aber streckte gegen Esther abermals das goldene Zepter aus. Darauf erhob sich Esther und trat mit diesen Worten vor den König:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, '\"Ist es dem König recht und fand ich vor ihm Gnade, erscheint es auch dem König angemessen und habe ich sein Wohlgefallen, so möge ein schriftlicher Befehl ergehen, auf daß die Schreiben jetzt zurückgenommen werden - der Anschlag Hamans, Hammedatas Sohns, des Agagiters -, die dieser schreiben ließ, um so die Juden zu vernichten, die in allen Landschaften des Königs sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Wie könnte ich es nur ertragen, das Unheil, das mein Volk betreffen soll, mitanzusehen? Wie könnte ich es nur ertragen, dem Untergange meines Stammes beizuwohnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Da sprach der König Ahasveros zur Königin Esther und zum Juden Mordekai: \"Ich habe Hamans Haus der Esther zum Geschenk gemacht. Ihn selber hat man an den Galgen gehängt dafür, daß er die Hände gegen diese Juden ausgestreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ihr mögt den Juden, wie\'s euch gut erscheint, im königlichen Namen tun und dies mit meinem königlichen Ring besiegeln. Ein Schreiben, in des Königs Namen abgefaßt und mit dem königlichen Ring besiegelt, kann nicht zurückgenommen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'So wurden nun die königlichen Schreiber zu jener Zeit im dritten Mond, das ist im Monat Siwan, am dreiundzwanzigsten, berufen. Dann ward geschrieben, wie es Mordekai betreffs der Juden anwies, und zwar an die Satrapen und an die Statthalter und Fürsten der 127 Länder von Indien bis Äthiopien, gemäß der Schriftart einer jeglichen Provinz, sowie der Sprache eines jeden Volkes, und so auch an die Juden, entsprechend ihrer Schrift und Sprache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Er ließ es in des Königs Ahasveros Namen schreiben und siegelte es mit königlichem Ring. Dann sandte er die Schreiben durch berittene Eilboten, die auf Rennpferden aus Gestüten ritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Danach gestattete der König allen Juden irgendeiner Stadt, sich zu versammeln und ihr Leben zu verteidigen. Wenn die bewaffneten Volkshaufen einer Nation und einer Gegend sie angriffen, so durften sie sie all mit Kindern und mit Weibern vernichten, töten, tilgen und ihre Habe als Beute nehmen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'an einem Tag in allen Landen, die König Ahasveros eigen waren, am dreizehnten des zwölften Monds, das ist im Monat Adar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Der Inhalt dieses Schreibens war, in jeder einzelnen Provinz soll ein Gesetz erlassen werden; die Juden sollen sich an jenem Tage rüsten, an ihren Feinden sich zu rächen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Eilboten, auf den schnellsten Pferden reitend, zogen schleunigst aus, eilends nach dem Befehl des Königs, sobald zu Susan in der Burg ein solch Gesetz erlassen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Und Mordekai verließ den König im königlichen Kleide, purpurblau und weiß, mit großem goldenen Diadem und einem Mantel, der von Linnen und von Purpur war. Die Stadt von Susan jubelte und freute sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Den Juden ward jetzt Glück und Fröhlichkeit zuteil, Jubel und Ehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'In jeglicher Provinz und Stadt, wo immer nur des Königs Wort und sein Gesetz hinkamen, da herrschte Fröhlichkeit und Jubel bei den Juden und Gasterei und Fröhlichkeit, und viele von des Landes Völkern gaben sich für Juden aus. Der Schrecken vor den Juden war auf sie gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Im zwölften Mond, das ist im Monat Adar, am dreizehnten, am Tage da des Königs Wort und sein Gesetz vollzogen werden sollten, am selben Tag, an dem die Judenfeinde hofften, sie zu überwältigen, und der sich nun gewandelt hatte und jetzt zu einem solchen ward, an dem die Juden selber ihre Hasser überwinden sollten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'da scharten sich die Juden in den Städten in sämtlichen Provinzen, die den König Ahasveros gehörten, um Hand an die zu legen, die ihnen Unheil zuzufügen trachteten. Und niemand hielt vor ihnen stand. Die Furcht vor ihnen fiel auf alle Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Und alle Fürsten der Provinzen, Satrapen, Statthalter, des Königs Angestellte halfen nun den Juden, dieweil die Furcht vor Mordekai auf sie gefallen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Denn groß stand Mordekai im Haus des Königs da. Durch alle Lande lief von ihm die Kunde. Denn Mordekai, der Herr, ward immer größer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Die Juden schlugen alle ihre Feinde fürchterlich mit Schwert und Mord und Tod. Mit ihren Hassern taten sie nach Gutdünken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'So töteten die Juden und vertilgten in der Burg von Susan fünfhundert Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Parsandata und Dalephon und Aspata,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Porata und Adalja, Aridata,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmasta, Arisai und Aridai und Jezata,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'zehn Söhne Hamans, des Sohnes des Hammedata, des Judenfeindes, brachten sie ums Leben. Doch nach Beute streckten sie die Hand nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'An jenem Tage kam die Zahl der in der Susanburg Erschlagenen vor den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Da sprach der König zu der Königin Esther: \"Zu Susan in der Burg erschlugen und vernichteten die Juden an fünfhundert Mann sowie zehn Söhne Hamans. Was taten sie da in den anderen königlichen Landen! Doch was ist deine Bitte, damit sie dir bewilligt werde? Und was ist weiter dein Begehr, daß es erfüllet werde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Und Esther sprach: \"Gefällt\'s dem König, so möge morgen noch den Juden in Susan gestattet sein, zu tun wie heute, und die zehn Söhne Hamans hänge man auch an den Galgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Darauf befahl der König, dies zu tun. Und so ward ein Befehl in Susan ausgegeben. Da hängte man zehn Söhne Hamans auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Dann scharten sich in Susan auch die Juden am vierzehnten des Monats Adar und töteten dreihundert Mann zu Susan. Doch nach Beute streckten sie die Hand nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Die anderen Juden in des Königs Landen hatten sich versammelt und waren für ihr Leben eingetreten. Sie schafften Ruhe sich vor ihren Feinden und töteten bei ihren Hassern 75.000. Doch nach Beute streckten sie die Hand nicht aus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'am dreizehnten des Monats Adar. Sie ruhten am vierzehnten aus und machten ihn zu einem Tag der Gasterei und Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Die Juden, die zu Susan waren, versammelten sich am dreizehnten und vierzehnten Tag und ruhten erst am fünfzehnten. Sie machten diesen Tag zu einem Tag der Gasterei und Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'So machen denn die Land-Juden, die in den Ortschaften des offenen Landes wohnen, den vierzehnten des Monats Adar zu einem Tag der Freude und der Gasterei, zu einem Festtag mit gegenseitiger Zusendung von Eßportionen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Und Mordekai schrieb diese Dinge auf und sandte Schreiben allen Juden, die in des Königs Ahasveros Landen waren, den nahen und den fernen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'um es ihnen zur ständigen Pflicht zu machen, daß sie den vierzehnten des Monats Adar, sowie den fünfzehnten alljährlich feiern sollten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'entsprechend jenen Tagen, da einst den Juden Ruhe vor den Feinden ward, sowie dem Monat, der sich für ihn aus Kummer in Fröhlichkeit, aus Trauer in einen Festtag gewandelt hatte. Sie hielten ihn als Tag der Gasterei und Freude und Zusendung von Eßportionen aneinander und von Geschenken an die Armen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Die Juden machten sich zum Brauch, was sie zu tun begonnen und was einst Mordekai an sie geschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Denn Haman, Hammedatas Sohn, der Agagiter, der Widersacher aller Juden, hat einst die Ausrottung der Judenschaft geplant und hat das Pur, das ist das Los, werfen lassen, sie zu vernichten und zu vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Doch als es vor den König kam, gab er den schriftlichen Befehl. So fiel denn auf sein eigen Haupt zurück sein schlimmer Plan, den er der Judenschaft zu Leide ausgeheckt. Man hängte ihn und seine Söhne an den Galgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Deshalb hieß man die Tage Purim nach dem Worte Pur, nach der Erzählung dieses Buches, was ihnen einst in Aussicht stand, und wie es ihnen drauf erging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Drum machten es zu fester Pflicht und festem Brauch die Juden für sich und ihre Nachkommen sowie für alle, die sich ihnen anschließen. Unwiderruflich soll es sein: Sie haben diese beiden Tage nach Anordnung und Zeitbestimmung jedes Jahr zu feiern! Sie haben diese Tage als Gedächtnistage zu feiern, daß sie in allen Zeitaltern, Geschlechtern und in Provinzen und in Städten feierlich begangen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Nie sollen die Purimstage aus der Juden Mitte schwinden und ihr Gedächtnis nie bei ihren Nachkommen aufhören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Die Tochter Abichails und Mordekais, des Juden, die Königin Esther, verfaßte auch ein Schreiben, um die vollkommene Echtheit dieser zweiten Purimschrift vollauf zu bestätigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Man sandte Schreiben allen Juden in den 127 Ländern im Reich des Ahasveros mit Grüßen und Gesetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Sie sollten diese Purimstage als gesetzlich anerkennen zu ihren Zeiten, so wie sie Mordekai, der Jude, und die Königin Esther einst gesetzlich gemacht, und wie sie für sich selbst und ihre Nachkommen die Fasten und die Weheklage zum Gesetz gemacht hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Und der Befehl der Esther machte diese Purimvorschriften gesetzlich. Er ward in einem Buche aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Der König Ahasveros aber ließ vom Land und von des Meeres Inseln die Steuern wieder eintreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Sind alle die Erweise seiner Macht und Stärke und die genaueste Beschreibung jener hohen Würde Mordekais, zu der der König ihn erhob, nicht in dem Buche der Geschichte der Könige von Medien und Persien aufgezeichnet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Denn Mordekai, der Jude, besaß den zweiten Rang nach König Ahasveros, und für die Juden war er gar bedeutungsvoll, beliebt bei seiner Brüder Masse, weil er seines Volkes Heil erstrebte und für sein ganzes Geschlecht zum Besten sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Einst lebte in dem Lande Us ein Mann mit Namen Job, und dieser Mann war fromm und recht gottesfürchtig und dem Bösen feind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Ihm waren sieben Söhne und drei Töchter geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Und er besaß an Zuchtvieh 7.000 Schafe, 3.000 Kamele, 500 Joch Rinder und 500 Eselinnen, dazu ein groß Gesinde, und so war dieser Mann der vornehmste von allen Söhnen des Ostens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Die Söhne aber pflegten ein Gelage abzuhalten, und zwar in eines jeden Haus an seinem Tage. Sie luden dazu die drei Schwestern ein, mit ihnen dort zu essen und zu trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Und hatten sie die Tage des Gelages die Runde machen lassen, dann sandte Job und ließ sie reinigen, erhob er sich doch früh am Morgen und brachte Opfer dar für jeden einzelnen von ihnen. Denn also dachte Job: \"Vielleicht daß meine Kinder sich versündigt und so in ihrem Herzen Gott \'gesegnet\' haben.\" So tat denn Job ein jedesmal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Doch da geschah ́s an jenem Tage: Die Gottessöhne kamen und stellten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'vor dem Herrn sich auf. Mit ihnen auch der Satan. Da sprach der Herr zum Satan. \"Woher kommst du?\" Der Satan gab dem Herrn zur Antwort: \"Ich komme her von einem Streifzug auf der Erde, von einer Wanderung auf ihr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Da sprach der Herr zum Satan: \"Hast du gemerkt, daß Job, mein Knecht, nicht seinesgleichen auf der Erde hat, ein Mann, so fromm und recht, so gottesfürchtig und dem Bösen feind?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Darauf erwiderte dem Herrn der Satan: \"Ist Job umsonst so gottesfürchtig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hast du nicht ihn, sein Haus und all sein Gut umhegt? Und seiner Hände Arbeit hast du so gesegnet, daß sein Besitz im Land sich mehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Doch fahre einmal einen Schlag und triff sein Hab und Gut, ob er nicht ins Gesicht dich \'segnet\'!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Da sprach der Herr zum Satan: \"So sei in deiner Hand jetzt alles, was er hat! Nur rühr ihn selbst nicht an!\" Da ging der Satan von dem Herrn hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'An einem Tag geschah\'s: Die Söhne und die Töchter Jobs schmausten im Haus des ältesten Bruders und tranken Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Da kam zu Job ein Bote. Er sprach: \"Die Rinder pflügten auf dem Felde; die Eselinnen weideten daneben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Da fielen die Sabäer ein und raubten sie und schlugen mit dem Schwert die Knechte. Nur ich allein entkam mit knapper Not, dir\'s zu vermelden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Und noch sprach dieser. Da kam ein anderer schon und sprach: \"Ein Gottesfeuer fiel vom Himmel, fuhr zündend in die Herden zu den Knechten und fraß sie auf. Nur ich allein entkam mit knapper Not, dir\'s zu vermelden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Und noch sprach dieser. Da kam ein anderer schon und sprach: \"Chaldäer fielen ein, drei Haufen, und trieben die Kamele weg und schlugen mit dem Schwert die Knechte. Nur ich allein entkam mit knapper Not, dir\'s zu vermelden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Und noch sprach dieser. Da kam ein anderer schon und sprach: \"Beim Schmause waren deine Söhne und deine Töchter und tranken Wein im Haus des ältesten der Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Da kommt ein mächtiger Sturmwind aus der Wüste, erfaßt das Haus an den vier Ecken. Und dies fällt auf die Knechte; sie kommen um. Nur ich allein entkam mit knapper Not, dir\'s zu vermelden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Darauf erhob sich Job, zerriß sein Kleid, zerraufte sich sein Haupt und warf sich auf die Erde zum Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Hierauf sprach er: \"Ich habe nackt den Mutterschoß verlassen; ich fahre nackt dorthin zurück. Der Herr hat es gegeben. Der Herr hat es genommen. Gepriesen sei des Herrn Name!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Bei alldem hatte Job sich nicht versündigt, noch Haß geäußert gegen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Doch da geschah\'s an einem Tage: Die Gottessöhne kamen und stellten vor dem Herrn sich auf; da kam der Satan auch mit ihnen und stellte vor dem Herrn sich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Da sprach der Herr zum Satan: \"Woher kommst du?\" Der Satan gab dem Herrn zur Antwort: \"Ich komme her von einem Streifzug auf der Erde, von einer Wanderung auf ihr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Da sprach der Herr zum Satan: \"Hast du bemerkt, daß Job, mein Knecht, nicht seinesgleichen auf der Erde hat, ein Mann, so fromm und recht, so gottesfürchtig und dem Bösen feind, und noch hält er an seiner Frömmigkeit so fest. Du hast mich grundlos aufgereizt, ihn so zu quälen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Da sprach zum Herrn der Satan: \"Ja Leib für Leib! Selbst alles, was ein Mann besitzt, das gibt er für sich selber hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Doch führe einmal einen Schlag und rühr an sein Gebein und Fleisch, ob er nicht ins Gesicht hinein Dich \'segnet\'!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Da sprach der Herr zum Satan: \"Nun wohl, er sei in deiner Hand! Nur schone mir sein Leben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Da ging vom Herrn der Satan weg und schlug den Job mit einem schrecklichen Geschwür vom Kopfe bis zum Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Er nahm sich eine Scherbe, um sich damit zu schaben, und saß dabei im Aschenhaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Da sprach sein Weib zu ihm: \"Noch hältst du fest an deiner Frömmigkeit? Nun \'segne\' Gott und stirb!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Er aber sprach zu ihr: \"Wie unvernünftige Weiber reden, so redest du. Ja, sollen wir allein das Gute von Gott annehmen, dagegen nicht das Schlimmste?\" Bei alldem hatte Job mit seinen Lippen nicht gesündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Drei Freunde Jobs vernahmen von all dem Unglück, das auf ihn gekommen; da machten sie sich auf, ein jeglicher von seinem Wohnort, von Teman Eliphaz, Bildad von Schuach, von Naama Sophar, und sie bestellten sich zusammen, um zu gehen, ihm ihr Beileid zu bezeugen und ihn zu trösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Doch wie sie ihre Augen von ferne erhoben, erkannten sie ihn nicht. Sie fingen laut zu weinen an, zerrissen jeglicher sein Kleid und streuten Staub sich himmelwärts aufs Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Sie saßen auf der Erde so bei ihm wohl sieben Tage, sieben Nächte, und keiner sprach ein Wort zu ihm; sie sahen. Das Leid war furchtbar groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Danach tat Job den Mund auf und fluchte seinem Schicksal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Und Job hob an und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '\"0 wäre doch der Tag, da ich geboren, nie erschienen und jene Nacht entschwunden, da man den Knaben aufgenommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Weh jenem Tage! Besser wäre er in Dunkelheit verblieben! Hätte doch der Höchste droben sich nie um ihn gekümmert und nie die Sonne ihm geleuchtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Die schwarze Urnacht hätte ihn vernichten und Wolkendunkel auf ihm ruhen sollen! Hätte man ihn doch der Verdüsterung überlassen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, '\"Wenn nur ein Raub der Finsternis die Nacht geworden wäre! Und hätte niemals zu den Jahrestagen sie gezählt und niemals in der Monde Schar gegolten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Wenn jene Nacht nur unfruchtbar geblieben wäre, und wäre nie ein Jubellaut in ihr ertönt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Und die den Tag verfluchen, ach, hätten die doch sie verflucht und jene, die bereit, den Leviatan selbst zu reizen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Verlöschen hätten sollen ihre Morgensterne, sie hätte auf das Licht vergeblich warten müssen! Des Frührots Wimpern hätte sie nicht schauen dürfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Denn hätte sie einst meines Lebens Tor verschlossen, dann hätte sie auch meinen Augen Leid erspart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Warum bin ich denn nicht im Mutterschoß gestorben, weswegen, kaum geboren, nicht verschieden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Warum denn nahm ein Schoß mich auf und Brüste, daß ich trinken mußte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Dann läge ich zu dieser Zeit und hätte Ruhe. Ich schliefe - wie wär mir so wohl! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'bei Königen und Weltregenten, die Trümmerstätten wiederum sich aufgebaut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'bei jenen goldberühmten Fürsten, die ihre Schatzhäuser mit Silber füllten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Dann wäre ich nicht mehr; ich gliche einer Fehlgeburt und jenen Kleinen, die das Licht nie schauten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Dort, wo die Sorgen den Geplagten schwinden, wo die durch Obermacht Geknechteten ausruhen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'wo die Gefangenen sorglos gehen und keines Treibers Ruf mehr hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Vornehm und Nieder ist dort gleich; frei von dem Herrn ist dort der Sklave.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Warum nur schenkt man Elenden das Tageslicht und Herzbetrübten Leben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'die ausschaun nach dem Tode, der nicht kommt, nach ihm sich sehnen mehr als nach Schätzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'die ob der Grabestür sich freuen, die jauchzen, wenn\'s zur Grube geht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, '- dem Manne, dessen Schicksal unbeachtet bleibt, vor dem sich Gott verborgen hält?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'An Brotes Stelle tritt bei mir das Seufzen; als Wasser strömt mir Klage zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Und bange ich vor einem Ding, dann trifft es sicher mich, und was mich ängstigt, kommt zu mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ich darf nicht ruhen und nicht rasten, kaum aufatmen, und schon kommt neue Pein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Da gab ihm Eliphaz aus Teman also Antwort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '\"Hat man vor dich zur Prüfung je ein Ding gebracht, worüber du den Mut verloren hättest? Wer konnte je den Worten Einhalt tun?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Fürwahr, so viele hast du selbst belehrt, so manchen schwachen Arm gestählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Den Strauchelnden hielt aufrecht deine Rede; die müden Kniee stärktest du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Jetzt kommt\'s an dich, da wirst du mutlos; wo dich\'s erfaßt, verzweifelst du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'War deine Gottesfurcht nicht dein Vertrauen, und dein unsträflich Leben deine Hoffnung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Bedenke nur: Wer kommt je schuldlos um? Wo gehen Redliche zugrunde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Die Unrecht pflügen, Böses säen, die ernten\'s auch. So weiß ich es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Durch Gottes Odem gehen sie zugrunde; durch seinen Zornhauch sterben sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Der Löwen Stimmen selber, das Gebrüll der Leuen, der jungen Löwen Zähne werden ausgetilgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Der Löwe geht zugrunde aus Beutemangel; der Löwin Junge müssen sich zerstreuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Zu mir drang ein verstohlen Wort; mein Ohr vernahm davon nur ein Geflüster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Im Wundertraum, bei Nachtgesichten, wenn Tiefschlaf auf die Menschen fällt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'da fuhr in mich ein Schrecken und ein Zittern, und Angst ließ mein Gebein erbeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Und über meinen Rücken lief es kalt; ein Schauder schüttelt\' meinen Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Das Unbekannte stand vor mir; vor meinem Auge schwebte her ein Schatten. - Ein Säuseln hörte ich und eine Stimme:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '\'Ist gegen Gott ein Mensch gerecht; vor seinem Schöpfer einer rein?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Er traut dies seinen Dienern selbst nicht zu, und seinen Engeln flößt er Schrecken ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Nun vollends gar der Lehmhausmensch, der Sterbliche, aus Staub gebaut, noch leichter als die Motten zu zerdrücken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Vom Morgen bis zum Abend werden sie vernichtet; unwiderruflich gehen sie zugrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Ja, wird denn nicht ihr Vorzug ihnen weggenommen? Durch Unvernunft nur sterben sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '\"Ach, fordere immer vor Gericht! Wer leistet deiner Ladung Folge? Mit Heiligen entzweit, an wen willst du dich wenden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Den Toren wird der Ärger töten, den Dummen wird der Zorn das Leben kosten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Ich selbst sah einen Toren festgewurzelt stehen; da schaut ich seines Hauses raschen Untergang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'und seine Kinder standen hilflos da. Sie mußten, ohne Anwalt, im Gerichtstor sich zertreten lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Was er geerntet, ißt ein Hungriger, und dieser bringt davon dem Darbenden. Nach ihren Krügen lechzen Durstige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Denn Unheil wächst nicht aus dem Staube; nicht sprießt das Unglück aus dem Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Dem Unglück wächst ein Mensch entgegen, so wie empor der Flamme Funken fliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'An deiner Stelle kehrte ich mich doch zu Gott; ich stellte meine Sache Gott anheim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'ihm, der so herrlich, unerforschlich waltet und Wunder wirket ohne Zahl,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'der selbst der Erde Regen spendet und Wasser auf die Fluren schickt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'der Niedrige erhöht, Gebeugte führt zum Heil,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'der hintertreibt den Plan der Listigen, daß ihre Hände immer Förderliches schaffen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'der Kluge übertrifft an List, so daß der Schlauen Plan sich überstürzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'daß sie bei Tag auf Dunkel stoßen, am Mittag tappen wie bei Nacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'der rettet den Verlassenen vor ihrem Rachen, den Armen vor der starken Faust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Drum geht dem Schwachen Hoffnung auf; die Bosheit muß ihr Maul verschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Wohl dem, der Gottes Zucht erfährt! Verschmäh daher des Höchsten Mahnung nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Denn er verwundet und verbindet; von seiner Hand kommt Schlag und Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'In sechs der Nöte schont er deiner; in sieben dich kein Unheil trifft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Er rettet dich vom Tod in Hungersnot, im Krieg vor der Gefahr des Schwertes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Und greifen Feuerzungen um sich, so bist du wohl geborgen, hast nichts zu fürchten, wenngleich Verheerung kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Des Dämons und der Seuche kannst du lachen; die wilden Tiere brauchst du nicht zu fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Denn mit des Landes Schrecknissen stehst du im Bunde; die wilden Tiere sind dir zugetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Und du erfährst, daß wohlbehalten bleibt dein Zelt, und musterst du dein Haus, vermißt du nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Die Zahl der Kinder siehst du wachsen; wie Gras im Feld ist dein Gesproß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Du gehst zum Grab im hohen Alter ein, wie Garben, eingeführt zur rechten Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'So ist\'s. So haben wir\'s ergründet. So haben wir\'s gehört. Zu Herzen nimm es dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Da gab ihm Job zur Antwort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '\"Wenn doch mein Gram, mein Leid gewogen würde auf einer Waage, ganz genau,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'so wär es schwerer als des Meeres Sand. Deshalb sind meine Worte unbedacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Des Höchsten Pfeile kenne ich zu gut, mein Geist saugt doch ihr Gift in sich hinein. Die Gottesschrecken überfallen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Auf grüner Au, schreit da der Esel, und brüllt der Stier bei seinem Futter?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Kann man denn Fades ohne Salz genießen; besitzt das Eiweiß Wohlgeschmack?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'So widert es mich an, auch jenes anzurühren, dergleichen gilt mir wie ein Trauerbrot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Ach, daß mein Flehen Gnade fände, daß Gott erfüllte meinen Wunsch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Gefiel es Gott, mich zu zermalmen; zerschnitt er rasch in Großmut meinen Lebensfaden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Dies wäre noch ein Trost für mich; ich tanzte noch im schonungslosen Schmerze, weil ich mit Worten an den Heiligen nicht zurückgehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Was ist denn meine Kraft, daß ich noch hoffen, mein Zweck, daß ich mich noch gedulden soll?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ist meine Körperkraft aus Stein? Ist denn mein Fleisch aus Erz?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Verdiene ich denn keinen Beistand mehr? Ist jede Hilfe mir zu nehmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Dem Leidenden gebührt von seinem Freunde Liebe, und muß er selbst die Gottesfurcht beiseite lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Die Brüder aber sind mir untreu wie die Bäche. - Sie zeigen nutzlos sich wie Wasserläufe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'die durch die Kälte trauern und die der Schnee verbirgt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'die ebenso, wenn sie durchglüht, verschwinden, wenn\'s heiß, getilgt von ihrem Orte sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'und deren Wegeläufe ganz verkehrt. Sie steigen dann als Dunst hinauf und sind nicht mehr zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Die Karawanen Temas schauen danach aus; die Reisezüge Sabas rechnen drauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Doch ihr Vertrauen täuschet sie; sie kommen hin und sind dann schwer betrogen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Zu gar nichts nutze seid ihr freilich. Ihr seht das Unglück und verzaget.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Ja, habe ich euch gesagt: \'Von Eurem gebt mir! Aus eurem mühevoll erworbenen Gute zahlt für mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Befreit mich aus der Hand des Drängers! Vom harten Gläubiger erlöset mich!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Belehrt mich eines Besseren, dann schweige ich. Zeigt mir doch meinen Irrtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Wozu verhöhnt ihr offne Worte, und was beweist denn ein Beweis von euch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Ja, haltet ihr schon bloße Worte für Beweis, die Worte eines Armen aber nur für Wind?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Laßt ihr auf Waisen etwas kommen, und sprecht ihr gegen euren Freund?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Nun aber wollet mit Verlaub mir zuhören! Ich täusche eure Aufmerksamkeit mitnichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Hierher kehrt euch! Kein Unrecht laßt geschehen! Hierher kehrt euch! Im Rechte bin ich noch hierin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Ist denn auf meiner Zunge einzig Unrecht? Verstehe ich denn nicht, was Sünde ist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '\"Ist nicht im Dienst der Mensch auf Erden? Ist nicht sein Los ein Frönerleben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Dem Sklaven gleich, der nur nach Schatten lechzt, dem Fröner, der um seinen Lohn sich sorgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'So hoffte ich auf Ruhemonde; da wurden Kummernächte mir zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Und lege ich mich nieder, frage ich: \'Wann darf ich mich erheben?\' Und zieht der Abend sich dahin, dann bin ich satt von Unrast bis zur Nachtzeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mein Körper kleidet sich in Fäulnis, in erdige Kruste, und meine Haut vernarbt und wird dann wieder flüssig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Weit schneller fliegen meine Tage hin als Weberschiffchen. Sie schwinden ohne Hoffnung hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Bedenke, daß ein Hauch mein Leben! Nie schaut mein Auge wieder Gutes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Wer später nach mir schaut, des Auge sieht mich nimmer. Mich suchen deine Augen; ich bin nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Die Wolke schwindet und zergeht, Und wer zum Totenreiche steigt, der kommt nicht mehr herauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nie kehrt er wieder in sein Haus, und seine Heimat sieht ihn niemals mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'So will ich meinen Mund nicht hemmen, nein, aussprechen, was mir das Herz beklemmt. Ich rede so in meiner Seele Bitternis:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, '\'Bin ich ein Meer, bin ich ein Ungeheuer, daß Du Schlaflosigkeit mir auferlegst?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Ich denke, daß mein Bett mich tröstete und daß mit mir mein Lager trüge auch mein Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Da scheuchst Du mich durch wirre Träume auf; durch Angstgestalten schreckst Du mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Erwürgung, Sterben hätte meine Seele lieber als diese meine Schmerzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Ich habe es jetzt aufgegeben, immerfort zu eben. Laß ab von mir! Denn meine Tage sind ein Hauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Was ist der Mensch für Dich denn Großes, daß Du Dich so mit ihm befassest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'ihn untersuchst an jedem Morgen, in jedem Augenblick ihn prüfest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Wie lange ist\'s, daß Du den Blick nicht von mir wendest, mir keine Ruhe lässest, bis ich nur meinen Speichel schluckte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Und habe ich gesündigt, was tu ich Dir damit, Du Menschenwächter? Was machst Du mich für Dich zur Scheibe? Weswegen diene ich zum Ziele Dir?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Kannst Du mir nicht verzeihen, hingehen lassen meine Schuld? Dann läge ich gar bald im Staube, und suchtest Du mich auf, ich wäre nimmermehr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Darauf erwidert Bildad von Schuach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '\"Wie lange willst du solches reden und wüten mit der Worte Sturm?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Ist Gott etwa ein Rechtsverdreher? Und beugt gerechte Sache der Allmächtige?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Wenn deine Kinder gegen ihn gesündigt und er sie um der Sünde willen in den Tod geschickt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'so solltest du an Gott dich wenden und zum Allmächtigen um Gnade flehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Dann würde er dir Schutz gewähren, falls du nur rein und lauter bist, und stellte auch die Wohnung wieder her, die dir gebührt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Dann würde auch dein früheres Los gering erscheinen, die Zukunft aber herrlich für dich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Befrage dich bei den vergangenen Zeiten; gib auf der Väter Weisheit acht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Wir sind von gestern, unerfahren; denn wie ein Schatten sind auf Erden unsere Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Doch jene, können sie dich nicht belehren? Sie geben tiefgeschöpftes Wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Wird etwa Schilfkraut ohne Sumpf sehr hoch? Wird Gras, wo Wasser fehlt, recht groß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Noch ist\'s im Trieb, nicht reif zum Schnitt, und schon ist\'s dürr, grünt alles andere noch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'So geht\'s mit allen Gottvergessenen. So wird des Frevlers Stolz vernichtet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'er, dessen Zuversicht nur Sommerfäden und dessen Hoffnung Spinngewebe sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Er stützt sich auf sein Haus; doch hält\'s nicht stand. Er hält sich fest daran; doch bleibt\'s nicht stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Wenn er auch in der Sonne grünt und seine Ranken weit in seinen Garten gehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Verflechten seine Wurzeln sich zuhauf, wie ein Gemäuer anzusehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'wenn er von seinem Ort ihn tilgt, verleugnet dieser ihn: \'Ich habe niemals dich gesehen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Das ist da seines Schicksals \'Wonne\', und andere steigen aus dem Staub empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Den Frommen kann Gott nicht verachten; der Übeltäter Hand hält er nicht fest. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Dein Mund wird noch des Lachens voll und voll von Jubel deine Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Und deine Hasser kleiden sich in Schande, und nicht mehr ist der Bösen Zelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Darauf gab Job zur Antwort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '\"Wahrhaft, ich weiß, daß es so ist. Wie könnte gegen Gott ein Mensch obsiegen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Hat einer Lust, mit ihm zu streiten, gibt er auf tausend nicht ein Wort zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Ist einer noch so klug und stark, wer trotzte ihm und bliebe heil?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Der Berge so versetzt, daß man nicht merkt, daß er im Zorn sie umgestürzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'der zittern macht der Erde Bau, daß ihre Säulen wanken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'der nicht mehr scheinen heißt die Sonne, und Sterne unter Siegel legt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'der ganz allein den Himmel spannte, auf Wolken schreitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'den Bären und Orion schuf, den Siebenstern, des Südens Kreuz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'der groß und unerforschlich waltet und Wunder wirket ohne Zahl:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Er macht sich an mich her, bevor ich\'s sehe, dringt auf mich ein, eh ich\'s bemerke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Und packt er zu, wer hält ihn ab? Wer sagt zu ihm: \'Was tust du da?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Wenn seinem Zorne Gott nicht wehrt, dann winden sich zu seinen Füßen selbst des Ungestüms Gehilfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Wie kann dann ich ihm Rede stehen, ihm gegenüber meine Worte wählen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'ich, der ich nicht Bescheid darf geben, mag ich im Recht auch sein, nein, meinen Richter noch anwinseln muß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Wenn ich ihn riefe, gäbe er mir Antwort? Ich glaub\' es nicht, daß er auf meine Stimme hörte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'er, der mich für ein Härchen packt, mir grundlos viele Wunden schlägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Er läßt mich nicht zu Atem kommen, weil er mit Bitterkeit mich sättigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Wenn\'s auf die Kraft ankommt, dann ist er stark, und gilt es zu beweisen, wer zeugt für mich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Bin ich im Recht, dann zeiht mich doch sein Mund des Unrechts, bin ich unschuldig, stellt er mich doch als schuldig hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Und wüßte ich nicht selber, daß ich schuldlos bin, wegwürfe ich mein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Nun ist es so; drum sage ich es offen. Er bringt den Frommen gleich dem Frevler um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Die Geißel tötet blindlings; er lacht ob der Unschuldigen Verzweiflung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Die Welt ist somit ausgeliefert in eines Ungerechten Hand, der seinen Strafgerichten das Gesicht verhüllt. Ist\'s dem nicht so, wie ist es dann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Und meine Zeit läuft schneller als ein Läufer; sie flieht und sieht das Glück nicht mehr,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'so flüchtig wie die Binsenschiffe, rasch wie der beutegierige Aar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Nie kann ich sagen: \'Ich will mein Leid vergessen, mein Trauern lassen, heiter sein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Mir graut vor allen meinen Schmerzen; ich weiß: Du sprichst mich nimmer los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Ich soll nun einmal schuldig sein. Wozu mich zwecklos mühen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Und wüsche ich mich weiß wie Schnee und reinigte mit Lauge mir die Hände,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'dann tauchtest Du mich um so tiefer in den Kot, daß meine Kleider selbst vor mir sich ekelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Er ist kein Mensch wie ich, dem ich erwiderte: \'Gehn wir zusammen vor Gericht!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Wenn einen Schiedsmann zwischen uns es gäbe, der beide unter seine Aufsicht stellte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'der seinen Stock von mir fernhielte; daß mich die Angst vor jenem nicht betäubte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'dann wollt\' ich furchtlos frei aussprechen, daß er - ich weiß es - gegen mich nicht ehrlich ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '\"Ich bin, des Lebens überdrüssig; ich lasse meiner Klage freien Lauf. In meiner Seele Bitterkeit will ich jetzt reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Ich spreche nun zu Gott: \'Verurteile mich nicht! Gib an, warum Du mich bekämpfst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Was nützt es Dir, wenn Du verdammst und Deiner Hände Werk verwirfst? Wenn aber zu der Frevler Plan Dein Antlitz leuchtet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Besitzest Du denn Fleischesaugen? Siehst Du so kurz, wie Menschen sehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Sind Deine Tage wie der Menschen Tage und Deine Jahre wie die Zeit der Sterblichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'daß Du bei mir nach Fehlern fahndest und mich auf Sünde untersuchst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'obschon Du weißt, daß ich nicht schuldig bin und mich aus Deinen Händen niemand retten kann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Mich formten kunstvoll Deine Hände; gleichwohl vernichtest Du mich ganz und gar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Bedenke, daß Du mich aus Lehm geschaffen! Und wiederum schickst Du mich in den Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Wie Milch hast Du mich hingegossen und mich zur festen Form gemacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'hast mich mit Haut und Fleisch bekleidet, mit Knochen und mit Sehnen mich durchwebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Ein Leben voller Gnade hast Du mir gegeben, und Deine Fürsorge hat meinen Geist bewacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Doch im geheimen ist Dein Planen dies; ich weiß es jetzt, was Du gedacht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Wenn je ich fehlte, wolltest Du mir grollen, mir meine Sünde nie verzeihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Wenn ich in Sünden fiele, wehe mir! Wenn ich rechtschaffen bliebe, ich dürfte dennoch nicht mein Haupt erheben, mit Schmach gesättigt, an Elend und am Leide satt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Ja, machst Du Jagd auf mich gleichwie auf einen Löwen, und zeigst Du dadurch Dich stets unvergleichlich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'daß Du den Angriff auf mich stets erneuerst und Deinen Unmut an mir kühlst, in immer neuen Angriffen auf mich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Warum hast Du mich aus dem Schoß geführt? Ach, wäre ich gestorben, ehe mich ein Auge sah!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Als wäre niemals ich gewesen, so hätte ich schon werden mögen, vom Mutterleib sogleich zu Grab getragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Sind meine Lebenstage nicht so kurz? Laß ab von mir, daß ich ein wenig heiter werde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'bevor ich, ohne Rückkehr, geh ins Land der düstern Todesschatten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'ins Land, wo tiefste Finsternis das Dunkel bildet, ganz ohne Unterschied, und wo es, wenn es heller scheint, noch immer dunkelt!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Da fiel Sophar von Naama ein und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '\"Soll dem Wortreichen keine Antwort werden? Soll wohl der Zungenheld obsiegen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Dummköpfe bringt zum Schweigen dein Geschwätz; da magst du Unsinn reden; da widerlegt dich keiner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du sprachst: \'Es ist doch lauter meine Rede. In Deinen Augen bin ich rein!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Wie aber, wenn Gott reden wollte, den Mund auftäte gegen dich');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'und dir in Weisheit zeigte, daß die geheimen Schändlichkeiten doppelt soviel ausmachen? So wisse: Von deinen Sünden sieht dir Gott noch manche nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Ergründest du die Tiefen Gottes, und kennst du das vollkommene Bild des Allerhöchsten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Was kannst du Höheres planen als den Himmel? Was kennst du Tieferes als die Hölle,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'und Breiteres als der Erde Breite und Weiteres als das weite Meer?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Wenn er verhaftet und versiegelt und hält Gericht, wer wehrt ihm da?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Er kennt die Menschen, die so gern sich selber täuschen; er sieht die Bosheit; doch er übersieht sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Und des Verstandes wird der Mann bei Hof beraubt, und der Gemeine wird durch schimpflichen Verkauf gepeinigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Wenn aber du dein Herz in Ordnung bringst, und hebst zu ihm die Hände flehend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'entfernst den Frevel, der an deinen Händen klebt, vergönnst der Sünde keinen Raum bei dir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'dann kannst du makellos dein Antlitz heben, dann stehst du felsenfest und unverzagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Alsdann vergissest du das Leid, du denkst daran wie an vergangene Zeiten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'und heller als der Mittag strahlt das Leben, und Dunkelheit ist wie der helle Morgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'voll Hoffnung schaut dein Blick hinaus; du schaust umher und legst dich sorglos nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Du lagerst dich, und niemand schreckt, und viele mühen sich um deine Gunst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Jedoch der Frevler Augen schmachten hin; fort schwindet ihnen Zuflucht, und ihre Hoffnung ist Verhauchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Darauf gab Job zur Antwort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '\"Wahrhaftig, ihr seid Leute; ausstirbt mit euch die Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Ich habe aber auch Verstand wie euer einer, ich falle gegen euch nicht ab. Wem wären solche Dinge fremd? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Dem Nächsten diene ich zum Schimpf, dem, der zu Gott ruft und den er erhört, dem vollkommenen Gerechten, zum Gespött.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Ich gleiche einer Nessel, gar verachtenswert, nach Ansicht Glücklicher für Fußtritte ausersehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Den Räubern aber sind die Zelte sicher, und Sicherheit genießen, die Gott reizen für das, was Gott in ihreHände hat gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Befrage nur die Tiere! Sie können es dir sagen; die Vögel auch beweisen dir\'s.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Schau dir die Erde an! Sie lehrt es dich; die Fische in dem Meer bezeugen dir\'s:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Wer nur in aller Welt weiß nicht, daß Gottes Hand dies hat geschaffen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'daß jedes Wesen ist in seiner Hand, der Odem aller Sterblichen? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Ist nicht das Ohr zum Worteprüfen so geschaffen, gerade wie der Gaumen, daß er Speise koste? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Ist Weisheit bei den Alten, Verstand bei langem Leben bloß zu finden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'dann muß bei ihm recht große Weisheit, Verstand und kluger Rat zu finden sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Was er zerstört, das baut man nimmer auf, und nimmt er jemanden gefangen, der wird nicht wieder frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Wenn er den Wassern wehrt, dann bleiben sie an Ort und Stelle; wenn er sie ledig läßt, aufwühlen sie die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Von ihm kommt Stärke und Erfolg; sein ist der Irrende, sein der Verführer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Er, der da Räte barfuß ziehen läßt und Richtern den Verstand wegnimmt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'der Königen die Diademe löst und ihnen Stricke um die Hüften legt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'der Priester barfuß ziehen läßt und der Beamte stürzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'der stocken macht geübte Redner und Greisen den Verstand wegnimmt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'der Schande ausgießt über Vornehme und Höflingen die Schärpen lockert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'der Tiefes aus dem Dunkel zieht und an das Licht das Finstere bringt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'der Heiden in die Irre führt und sie vernichtet und Heidenvölker niederstreckt und liegen läßt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'der zagen macht die Landeshäupter und sie in auswegloser Wirrnis irreführt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'daß sie in finsterem Dunkel tappen und der sie wie Betrunkene taumeln macht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, '\"So ist\'s. So hat\'s mein Auge auch gesehen, mein Ohr vernommen und gemerkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Soviel ihr wisset, weiß ich auch; ich falle gegen euch nicht ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Nun will ich mit dem Allerhöchsten reden; mit Gott zu rechten ich begehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Ihr freilich, ihr seid Lügenmeister, unnütze Ärzte insgesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Wenn ihr nur endlich schweigen wolltet und das für euch zur Weisheit würde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Auf meine Widerrede hört! Aufmerket auf den Vorwurf meiner Lippen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Wollt ihr für Gott Verkehrtes reden und ihm zuliebe Lügen sprechen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Wollt ihr für ihn Partei ergreifen, gar Anwalt sein für Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Wenn er euch richtet, geht\'s dann gut? Wollt ihr ihn narren, wie man Menschen narrt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Er gibt euch scharfen Tadel, wenn hinterrücks Partei ihr nehmet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Wird euch nicht seine Hoheit betäuben; befällt euch nicht sein Schrecken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Zerstäubt sind euere Beweise, und euere Bekräftigungen sind gar tönern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Vor mir nur schweigt! Denn ich muß reden. Es komme über mich, was wolle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Warum soll ich mein Fleisch in meine Zähne nehmen? Ich lege auf die flache Hand mein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Ja, mag er mich auch töten; ich zittere nicht davor; auf jeden Fall will ich vor ihm verteidigen meinen Wandel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Da muß er selber mir zum Sieg verhelfen; vor ihn kommt ja kein Ruchloser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Aufmerksam hört auf meine Rede! Ich will\'s euch selbst beweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Ich lege meinen Rechtsfall vor. Ich weiß gewiß, ich werd\'s gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kann einer etwas gegen mich beweisen, ich würde schweigend willig sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Nur zweierlei tu mir nicht an! Sonst muß ich mich vor Deinem Antlitz bergen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Stell Deine Macht vor mir beiseite! Und Deine Furchtbarkeit erschrecke nimmer mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Dann klage Du, und ich will mich verteidigen. Dann rede ich; Du aber widerlege mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Wie groß ist meine Schuld und mein Vergehen? Mein ganzes Unrecht laß mich wissen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Warum birgst Du Dein Angesicht, erachtest mich für Deinen Feind?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Ein welkes Blatt, das schreckst Du auf. Dem dürren Strohhalm jagst Du nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Du rechnest mir Vergangenes auf und weisest mir die Jugendsünden nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Du legst mir meine Füße in den Block, verwahrst mir alle Schritte; um meine Fußgelenke ziehst Du einen Ring. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Er aber gleicht dem Wurmfraß, der in Stücke fällt, und einem Kleid, an dem die Motte zehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '\"Der Mensch, der Weibgeborene, kurzlebig ist er, voller Hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Wie eine Blume blüht er und verwelkt, und wie ein Schatten fliegt er schnell vorbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Ja, gegen einen solchen öffnest Du Dein Auge und ziehst mich ins Gericht vor Dich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Wie könnte von dem Unreinen ein Reiner kommen? Nicht einer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Sind seine Tage ihm bestimmt, alsdann ist seiner Monde Zahl nur Dir bekannt. Du setzest ihm ein Ziel, unüberschreitbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Blick weg von ihm! Laß ab, bis er die Tagesarbeit abgeliefert, dem Fröner gleicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Ein Baum kann guten Trostes sein. Wird er gefällt, so sproßt er wieder; sein Wurzelsprößling bleibt nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Wird seine Wurzel in der Erde alt und stirbt sein Stamm im Boden ab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'vom Wasserdunste sproßt er neu und treibt gleich einem jungen Reise Zweige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Doch stirbt der Mann, so liegt er kraftlos da, und scheidet hin ein Mensch, wo ist er dann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'In Menge mögen aus dem Meere Wasser fließen und Ströme ausgetrocknet werden und versiegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'der Mensch bleibt dennoch liegen und steht nicht wieder auf. Sie wachen nimmer auf, bis daß die Himmel schwinden. Sie werden aus dem Schlafe nicht erweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ach, daß Du mich doch in der Unterwelt verbärgest, verstecktest mich, bis sich Dein Zorn gestillt! Ach, daß Du mir doch eine Zeit bestimmtest und danach mein gedächtest! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Wenn jemand stirbt, wird er nochmals lebendig? - Ich harrte gerne meine Dienstzeit aus, bis meine Ablösung erschiene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Du riefest, und ich gäbe Antwort Dir, wenn Du nach Deiner Hände Werk verlangtest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Dann zähltest Du wohl meine Schritte, auf meine Sünden nimmer achtend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Dann würde fest versiegelt mein Vergehn in einem Beutel; mein Schuldregister klebtest Du dann zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Ein Berg stürzt ein, zerfällt; von seiner Stelle wird ein Fels gerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Alsdann zerreibt das Wasser diese Felsentrümmer, und starke Regegüsse lösen sie zu Erdenstaub. So ganz läßt Du des Menschen Hoffen auch zunichte werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Du packst ihn an, daß er auf ewig geht, entstellst sein Antlitz, schickst ihn fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Die Kinder kommen auf; er weiß es nicht. Sie werden arm; ihn kümmert\'s nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Am eigenen Leid hat er genug; sein Schatten trauert für sich hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Darauf erwidert Eliphaz von Teman also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '\"Kann denn ein Weiser so unsinnige Beweise bringen und sich in solcher Hohlheit blähen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Kann er Beweis mit Reden führen, die nichts taugen, mit Sprüchen, die nichts nütze sind?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Du machst die Gottesfurcht zunichte, zerstörst die Andacht vor der Gottheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'wenn deine Schuld dich lehrt, also zu reden, und du Verschmitzter Redeweise wählst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Dein eigener Mund verdammt dich und nicht ich; die eigenen Lippen strafen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Warst du als Erstlingsmensch geboren und kamst du vor den Hügeln auf die Welt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'und hörtest du im Rate Gottes zu und holtest Weisheit dir allein?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Was weißt du, und wir wüßten\'s nicht, verstehst, was unbekannt uns wäre?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Sind unter uns doch graue Häupter, mehr als betagt genug, um Vater dir zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Ist dir die Gotteströstung zu gering, das Wort, das sanft an dich ergeht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Warum reißt dich ein Unmut fort? Was blicken deine Augen finster,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'daß deinen Geist du Gott zurückzugeben trachtest? Nur mit dem Munde freilich hast du das gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Was ist der Mensch, daß rein er wäre, gerecht der Weibgeborene?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Selbst seinen Heiligen traut er nicht; der Himmel ist nicht rein in seinen Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'geschweige der Abscheuliche, Verdorbene, der Mensch, der Sünde wie das Wasser trinkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Ich will dich lehren; hör mir zu. Was ich geschaut, will ich dir sagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'was Weise einst verkündet, was ihre Väter ihnen nicht verhehlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'die noch allein im Lande saßen, zu denen noch kein Fremder kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Des Bösen Leben ist voll Angst; nur wenig Jahre sind für den Gewaltmenschen bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Der Schrecken hallt in seinem Ohr; wiewohl in Sicherheit, wird er vom Räuber überfallen schon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Er gibt den Glauben auf, dem Dunkel zu entrinnen; er ist bestimmt für blutigen Tod');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'und wird ein Fraß der Geier. Er weiß, ihm ist ein finsterer Tag von ihm bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Ihn schreckt die Not; ihn überfällt die Drangsalszeit gleich einem kampfbereiten Hahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Weil gegen Gott die Hand er ausgestreckt und dem Allmächtigen er Trotz geboten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'so stürmt er gegen ihn, mit seines rauhen Schildes Wölbung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Er deckt mit dem Visier sein Angesicht, legt einen Panzerschurz um seine Lenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Nur in verfemten Städten noch kann jener siedeln, in unbewohnbaren Gebäuden, die schon dem Abbruch sind verfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Er wird nicht wieder reich, noch hat Bestand je seine Habe; er schlägt im Boden nimmer Wurzel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Der Finsternis entgeht er nicht, es dörrt die Hitze seine Zweige, und seine Blüten fallen durch den Sturmwind ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Zu denen, die auf Nichtiges vertrauen, irrt er hin; sein Entgelt ist das Nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Noch vor der Zeit verwelken sie, und seine Zweige grünen nimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Er wirft gleich einem Weinstock seine Früchte ab, wirft wie der Ölbaum seine Blüte hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Des Frevlers Rotte ist ja unfruchtbar, und Feuer frißt des Unrechts Zelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Sie brüten Unheil, hecken Ungemach, und ihres Leibes Frucht ist Trug.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Darauf erwidert Job und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '\"Desgleichen hörte ich schon viel; ihr alle seid mir leidige Tröster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Sind zweckvoll windige Worte? Oder, was zwingt dich, daß du Rede stehst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Wie ihr, so könnte ich auch reden, wärt ihr an meiner Stelle. Ich übertrumpfte euch durch Worte, und schüttelte bloß mit dem Kopfe über euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Mit meinem Munde tröstete ich euch, doch Mitleid hielte meine Lippen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Wenn aber ich jetzt rede, so wird mein Schmerz doch nicht gelindert. Und unterlaß ich es, was nur verliere ich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'So hat man also mich besiegt. Du hast mir das verwirrt, was für mich zeugt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'hast wehrlos mich gemacht. - Zum Kläger ward er mir und trat mir gegenüber; er sagte mir ins Angesicht, ich löge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Er rümpft die Nase und befeindet mich und knirscht mit seinen Zähnen wider mich, und als mein Feind rollt er die Augen gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Sie sperren gegen mich den Mund weit auf und schlagen mich gar schmählich auf die Wangen; dabei ergänzen sie sich gegenseitig wider mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Dem Bösewicht gibt Gott mich preis; durch Frevler Hände macht er meine Wunde aufbrechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Ich lebte ruhig. Da kam im Sturm er gegen mich, ergriff mich an dem Nacken, warf mich hin und machte mich für sich zur Zielscheibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Die Pfeile schwirren um mich her. Er spaltet meine Nieren schonungslos und schüttet meine Galle auf den Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Er bricht mir Bresche ein um Bresche und rennt gleich einem Kriegsheld wider mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Da habe ich das Trauerkleid mir angenäht und in den Staub mein Horn gebohrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Vom Weinen rot ist mein Gesicht, und meine Augen sind umflort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Und doch war schuldlos meine Hand, aufrichtig immer mein Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Du, Erde, decke nicht mein Blut, und meinem Klageruf sei keine Schranke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Im Himmel gibt\'s für mich noch Zeugen und Eideshelfer in den Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Fürsprecher sind mir meine Sitten. Mein Auge weint zu Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'daß er dem Manne Recht verschaffe gegen Gott, so, wie man\'s bei den Menschen macht und seinesgleichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Denn wenig Jahre noch, dann walle ich auf einem Pfade ohne Wiederkehr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, '\"Dahin ist meine Lebenskraft, und meine Tage, die verflossen, sind für mich ebensoviel Gräber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Wahrhaftig! Tadler sind bei mir; mein Auge muß auf ihrem Hader weilen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Setz ein! Jedoch Du hast schon meinen Einsatz. Wer gäbe sonst mir Handschlag?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Ihr Herz verschlossest Du der Einsicht; drum darfst Du sie nicht triumphieren lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Es hieße, Freunden einen Anteil zuerkennen, die eigenen Kinder aber darben lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Zum Sprichwort macht er mich für alle Welt; wie einer, dem man ins Gesicht speit, bin ich jetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Die Augen sind vor Kummer blind; wie Schatten schwindet hin mein Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Die \'Frommen\' staunen drüber, \'Unschuldige\' jubeln über den Verruchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Recht fest an ihrem Wege halten die \'Gerechten\', aufs neue schöpfen Kräfte diese \'Biederen\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Wenn ihr auch allesamt herbeikommt, ich finde keinen Weisen unter euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Hinschwinden meine Tage; dahin sind meine Pläne, die Herzenswünsche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Nacht macht man mir für Tag, das Licht noch dunkler als die Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Muß ich schon in der Unterwelt auf eine Wohnung rechnen, erhalte ich mein Ruhbett in der Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Und muß ich \'Vater!\' zur Verwesung sagen und zum Gewürme \'Mutter!\', \'Schwester!\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'wo bleibt da meine Hoffnung? Wer kann noch Glück für mich erspähen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Sie steigen in die Unterwelt, wenn wir gemeinsam in dem Staube ruhen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Darauf erwiderte Bildad von Schuach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '\"Wie lange steht\'s noch an, bis daß ihr Schluß mit diesen Worten macht, bis ihr belehrt und wir erwidern können?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Warum sind wir wie Vieh geachtet, nach eurer Ansicht wie vernagelt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Der du in deiner Wut dich selbst zerfleischst, soll deinetwegen gar die Welt sich selber überlassen sein? Und soll der Fels von seiner Stelle rücken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Jedoch des Frevlers Licht verlischt; nicht brennt mehr seines Herdes Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Das Licht verfinstert sich in seinem Zelt, und seine Leuchte über ihm erlischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Im besten Alter lahmt sein Schritt; sein eigener Rat bringt ihn zu Fall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Sein Fuß wird in dem Netz verstrickt, und im Gestrüpp verfängt er sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Die Ferse hält der Fallstrick fest, und Schlingen klammern sich an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Versteckt am Boden ist das Seil; die Falle liegt am Weg für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Die Schrecken lagern sich um ihn und machen, daß er Angst bekommt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Die Kinder sollen Hunger leiden, und Unheil sei bereit für seine Gattin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Die Glieder seines Leibs verzehre, des Todes Erstgeborener verzehre seine Glieder! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Aus seinem Zelte, seinem Glücke wird er fortgerissen; man führt ihn zu dem Schreckenskönig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Man wohnt in seinem Zelte ohne ihn; auf seine Wohnung streut man Schwefel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Von unten dorren seine Wurzeln, und oben welken seine Zweige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Und von der Erde schwindet sein Gedächtnis; kein Name bleibt ihm bei den Leuten draußen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Man stößt ihn aus dem Licht in Nacht und treibt ihn aus der Welt hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Nicht Schoß noch Sproß hat er im Volk; nicht einer bleibt in seiner Wohnung übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ob seines Schicksals starrt der Westen, und die im Osten faßt ein Grauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Dies ist des Frevlers Los, und dahin kommt\'s mit dem, der nichts von Gott mehr wissen will.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Darauf erwidert Job und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '\"Wie lange peinigt ihr mich noch, zermartert mich mit euren Worten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Wohl dutzendmal versuchtet ihr, mir eine Niederlage zu bereiten. Ihr schämt euch nicht, zum Angriff gegen mich zu schreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Ist\'s wahr, daß wirklich ich geirrt und daß im Irrtum ich verharre?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Wollt ihr gar groß tun gegen mich, so müßt ihr meine Schande mir beweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'So seht doch ein, daß Gott mir Hindernisse legt! Er hat mich in sein Netz verstrickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Ich schreie: \'Ha, Gewalttat\'; niemand hört\'s. Ich rufe, und mein Recht bleibt aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Er hat mir meinen Weg verbaut, und meinen Pfad in Finsternis gehüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Der Ehre hat er mich beraubt, die Krone mir vom Haupt gerissen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'zerschmettert mich, daß ich zerfahren und reißt, wie einen Baum, so mir das Hoffen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Sein Zorn ist wider mich entbrannt; er achtet mich als seinen Feind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'All seine Scharen rücken an, erbauen einen Damm gerade auf mich zu und lagern rings sich um mein Zelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Mich lassen meine Brüder; Vertraute gehen von mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Nachbarn und Freunde bleiben aus, und meines Hauses Schützlinge vergessen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Die Mägde achten mich für einen Fremden; ein Unbekannter bin ich ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Der Knecht hört nicht, wenn ich ihn rufe; ich muß ihn buchstäblich aufsuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Und für mein Weib ist meine Zuneigung ein Ekel und meine Zärtlichkeiten meinen eigenen Kindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Sogar die Buben, sie verachten mich; sie spotten meiner, wenn ich mich erhebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Die Mindesten aus meinem Kreis verabscheun mich; es wenden, die ich gerngehabt, sich gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'An meiner Haut, an meinem Fleisch klebt mein Gebein; mit meinen Narben bin ich einzig da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Erbarmet euch! Erbarmet euch, ihr meine Freunde! Denn Gottes Hand hat mich getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Warum verfolgt ihr mich wie Gott? Habt ihr an mir noch nicht genug?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ach, möchten meine Worte aufgezeichnet und in ein Buch geschrieben werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'auf Blei mit Eisenstift, auf ewig in den Fels gehauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Ich weiß bestimmt, für mich lebt ein Verteidiger, und schließlich tritt er doch auf Erden auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Dann ändert sich mein Körper hier; ich schaue Gott in meinem Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Den ich für mich ersehne, den sehe ich allein und niemand sonst; mag auch das Herz mir in der Brust hinschwinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Ihr sprechet ja: \'Womit nur wollen gegen ihn wir vorgehen, da doch der Hauptgrund jetzt bei ihm gefunden ist?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Nur hütet euch vor der Verleumdung! Verleumdung ist ja Gift und Sünde, daß ihr erfahrt, was richten heißt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Da antwortete Sophar von Naama und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '\"Mich bringen die Gedanken wieder auf den gleichen Punkt; mein Eifer wählt in mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Ich höre schmähliche Belehrung; mir antwortet ein Geist, für den ich kein Verständnis habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Du weißt das nicht, daß schon von altersher, seit Menschen auf der Erde sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'der Frevler Jubel gar nicht lange währt, die Freude des Verruchten höchstens einen Augenblick?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Erhebt er sich bis in den Himmel und streckt sein Haupt bis in die Wolken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'mit seinem Unterschlupf verschwindet er für alle Zeit. Die eben ihn gesehen, fragen, wo er sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Traumgleich zerfließt er, ohne Spuren, verschwindet wie ein Nachtgesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Das Auge, das ihn sah, wird ihn nicht wieder schauen, und seine Heimat sieht ihn nimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Ersatz den Armen seine Kinder leisten; die eignen Hände liefern seine Kinder ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Er stand in voller Lebenskraft; nun muß sie mit ihm in den Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Wenn ihm das Böse noch so süß im Munde schmeckt, und birgt er\'s unter seiner Zunge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'und spart er\'s auf und läßt\'s nicht los, behält es recht in seinem Gaumen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'dann ändert seine Speise sich in seinem Innern, wird Otterngift in seinem Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Er speit das Gut, das er verschlang; aus seinem Leibe treibt es Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Er saugt der Nattern Gift; der Viper Zunge tötet ihn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Er labt sich nicht an Strömen, an Bächen voll von Honig und von Milch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Er führt zwar sein Erworbenes zum Munde, verschluckt es aber nicht; so, wie\'s ihm sein Gewinn erlaubt, genießt er\'s nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Weil er der Armen Hütten eingerissen, so darf er nichts auf dem geraubten Baugrund bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Er kannte nie für seinen Bauch Zufriedenheit; in seiner Lust bekam er nie genug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Wen zu verzehren er sich vorgenommen, der ist ihm nicht entgangen; drum ist sein Wohlstand nicht von Dauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'In vollem Glück befällt ihn Angst; was Elende an Leid bedrückt, kommt über ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Wenn er sich anschickt, seinen Leib zu füllen, entsendet gegen ihn er seines Zornes Glut, und macht er sich ans Essen, beschießt er ihn von oben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Vom eisernen Geschoß wird er durchbohrt; ihn trifft der eherne Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Hinein dringt es und kommt heraus aus seinem Rücken. Ein Strahl von Galle fährt heraus; ein Schrecken lagert sich auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Den Seinigen, die er geborgen glaubt, ist alles Unheil aufgespart. Sie frißt ein Feuer, das von selber brennt. Wer noch in seinem Zelte übrig ist, dem geht es schlimm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Die Himmel offenbaren seine Schuld; die Erde selbst erhebt sich wider ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Hinschwinden seines Hauses Einkünfte und Ausgaben an seinem Zornestag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Das ist des Frevlers Los vor Gott, des Widerspenstigen Geschick vom Höchsten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Darauf erwidert Job und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '\"Mögt ihr auf meine Rede nochmals hören, und wär\'s zu eurem Zeitvertreib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Ertragt mich! Laßt mich, reden! Dann scheltet nur, wenn ich geredet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Erhebe ich denn gegen einen Menschen Klage? Oder - warum soll ich nicht ungeduldig werden dürfen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Zu mir kehrt euch, erstarret! Die Hand legt auf den Mund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Ich werde ganz erschüttert, denke ich daran; an Leib und Seele zittere ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Wie kommt\'s, daß Frevler leben dürfen und alternd noch an Kräften wachsen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Bei ihnen bleibt ihr Stamm, und er gedeiht, solang sie leben, und stets vor Augen bleiben ihnen ihre Sprößlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Und sicher vor Gefahr sind ihre Häuser; die Gottesrute trifft sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Sein Stier bespringt und läßt es nicht entgleiten, und seine Kuh kalbt leicht und tut nicht eine Fehlgeburt.-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Gleich einer Herde lassen sie die Kinderschar hinaus, und munter hüpfen ihre Jungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Sie spielen froh zu Pauken und zu Zithern und freuen sich beim Flötenschalle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Ihr Leben geht im Glück zu Ende; sie steigen zu der Unterwelt in Frieden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'und sagen doch zu Gott: \'Du bleib uns fern!\' \'Wir wollen nichts von Deinen Wegen wissen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, '\'Was soll es, daß wir dem Allmächtigen dienen? Was nützt es uns, ihn bittend anzugehen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Nun, läge nicht ihr Glück in ihrer Hand, dann wäre mir das Planen dieser Frevler unbegreiflich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Wie oft erlischt der Frevler Leuchte und überfällt sie ihr Verderben? Wie oft teilt er in seinem Zorne Schmerzen aus? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Sie sollen werden wie das Stroh vorm Winde, wie Spreu, vom Sturm entführt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '\'Gott hat sein Unheil eben dessen Kindern aufgespart.\' Er zahle ihm es heim, daß er es selber fühle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Er selber sollte seinen Becher kosten und von dem Grimm des Höchsten trinken müssen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Was braucht ihn denn zu kümmern, wie\'s seinem Haus nach seinem Tode geht, wenn seiner Monde Zahl zu Ende ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Kann man denn Gott das Wissen lehren, da er doch von der Höhe aus verfügt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Der eine stirbt in vollem Glücke, ganz ruhig, wohlgemut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Von Fett sind seine Lenden voll; sein Körper wird mit Mark getränkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Der andre stirbt verzweiflungsvoll, hat niemals von dem Glück gekostet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Zusammen liegen sie im Staube; Gewürm deckt beide zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Ich kenne eure Meinung wohl; ihr ziehet an den Haaren Gründe gegen mich herbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Ihr sagt: \'In welcher Lage ist das Haus des edlen Mannes?\' \'In welcher ist das Wohngezelt der Frevler?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Befragt ihr nicht die Leute, die auf den Lauf der Welten achten? Und ihre Zeugnisse könnt ihr nicht ablehnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Der Frevler bleibt vom Unheilstag verschont, vom Tag, wo Steuern eingetrieben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Wer hält ihm seinen Wandel vor, und wer vergilt ihm, was er tat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Er wird zu Grab getragen, und auf dem Grabespolster ruht er ungestört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Des Grabes Schollen sind ihm süß. So lockt er alle Welt sich nach, und vor ihm schreiten Zahllose einher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Wie leer ist euer Trost! Und eure Antworten sind unaufrichtig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Darauf erwidert Eliphaz von Teman mit den Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '\"Hat Gott von einem Manne Nutzen? Nein, nur zum eigenen Nutzen ist man fromm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Hat der Allmächtige etwas von deiner Tugend, Gewinn von deiner Lauterkeit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Zeiht er dich etwa deiner Frömmigkeit und zieht dich deshalb vor Gericht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Kann nicht dein Frevel mannigfaltig sein und deine Sünden ohne Maß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Gewiß hast du den Bruder ohne Grund gepfändet und Nackten ihre Kleider ausgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Dem Müden hast du keinen Trunk gespendet und Hungrigen das Brot versagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, '\'Dem Mann der Faust gehört das Land, und nur der Stolze darf drin wohnen\', so dachtest du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'So hast du Witwen hilflos ziehen lassen; die Waisen hat dein Arm bedrückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Deshalb sind Schlingen rings um dich und ängstigt jählings dich der Schrecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ist\'s nicht so, daß du gar nichts siehst, wenn Finsternis und Wasserwolken dich bedecken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Nun, ist nicht Gott so hoch in Himmelshöhen? Schau nur empor, wie hoch der Sterne Haupt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Da denkst du wohl: Wie kann denn Gott etwas bemerken? Kann er denn hinterm Wolkendunkel etwas unterscheiden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Umschleiern ihn doch Wolken, daß er nichts sehen kann, und auch der Himmelskreis ist in Bewegung.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Willst du denn von der Vorzeit Pfaden den betreten, den jene alten Sünder gingen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Sie, die gepackt zur Unzeit wurden, und deren Sein die Wasserflut verschlang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'die einst zu Gott gesprochen: \'Bleib uns fern!\' - Was tat doch ihnen der Allmächtige?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Er, der mit Segen ihre Häuser füllte. Der Plan mit diesen Frevlern ist mir unbegreiflich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Die Frommen sehen es noch heut und freuen sich; der Schuldlose verspottet sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '\'Ist unser Widersacher nicht vernichtet? Und seinen Rest verzehrte noch das Feuer.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Vertrau allein auf ihn, so hast du Frieden! Durch jene wird dir reichlicher Gewinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Laß dich von seinem Mund belehren! Zu Herzen nimm dir seine Worte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Wenn du gebessert zum Allmächtigen dich kehrst, entfernst aus deinem Zelte unrecht Gut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Golderz für Staub erachtend und für der Bäche Kiesel Ophirgold,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'daß dir so der Allmächtige zum Goldberg wird, zu einem Silberhaufen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'dann kannst du vorm Allmächtigen dich dem verwöhnten Kinde gleich gebärden und kannst dein Angesicht zu Gott erheben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Du bittest ihn, er hört auf dich; was du gelobt, kannst du erfüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Was du dir vornimmst, wird dir glücken, und hell vor dir liegt deine Straße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Wenn du in Demut Hochmut eingestanden, dann hilft er auch dem Demutsvollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'So rettet er den Nichtschuldlosen; doch wird er nur gerettet durch deiner Hände Reinigung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Darauf erwidert Job und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '\"Auch heut ist meine Klage bitter; ich lege allen Nachdruck auf mein Seufzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ach, daß ich ihn zu finden wüßte, vor seinen Stuhl gelangen könnte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'und dürfte meine Sache ihm vorlegen und mit Beweisen meinen Mund anfüllen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'und dürfte seine Antwort hören, vernehmen, was er mir zu sagen weiß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Ob er mit starken Gründen mit mir rechten wollte, ob er in Staunen mich versetzen könnte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Da stünde dann ein braver Mann vor ihm; ich wäre dann für immer meiner Richter ledig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Doch wenn ich ostwärts geh, so läßt er sich nicht finden, und westwärts, so gewahr ich ihn auch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Und wäre er im Norden, ich sähe ihn doch nicht, und böge er nach Süden ab, ich schaute ihn doch nirgends.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Mein Weg, auf dem ich stehe, ist ihm wohlbekannt, und prüft er mich, dann würde er wie Gold mich finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Mein Fuß ging stets in seinen Gleisen; ich wankte nicht von seinem Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Von seiner Lippe Lehre wich ich nicht; und seines Mundes Worte hob ich ohnegleichen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Er ist nun wahrhaft einzigartig. Wer kann ihm wehren? Was er beschließt, das führt er aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Er will mein Maß erfüllen, und solcherlei hat er noch viel bei sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Drum bin ich über ihn erschrocken; mir graut vor ihm, wenn ich dran denke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Gebrochen hat das Herz mir Gott; mit Schrecken hat mich der Allmächtige erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Denn ob des Dunkels fühle ich mich schon vernichtet, dieweil in Düsterkeit gehüllt ich bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '\"Warum sind vom Allmächtigen die Zeiten nimmer eingehalten? Denn seine Tage haben seine Gläubigen niemals erlebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Man rückt die Grenzen, raubt die Herden und treibt sie offen auf die Weide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Der Waisen Esel treibt man fort und nimmt der Witwe Rind zum Pfande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Die Armen stößt man von dem Wege; die Elenden im Lande müssen sich zumal verstecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Gleich wilden Eseln müssen sie durch jener Schuld die Zehrung in der Steppe suchen und Brot daselbst für ihre Kinder holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Auf dem Felde eines Bösewichtes müssen sie als Schnitter schaffen, im Weinberg eines Frevlers Lese halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Bei Nacht liegen sie nackt, der Kleidung bar, und bar der Hülle in der Kälte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Vom Regenguß auf Bergen triefen sie und schmiegen obdachlos sich an den Fels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Man raubt die Waise von der Mutter Brust und pfändet des Bedrückten Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Die gehen nackt einher, der Kleider bar, und schleppen hungernd Garben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Sie keltern zwischen Gruben Öl und müssen dürsten, wenn sie Keltern treten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Sie stöhnen unter Sklavenangst; um Hilfe schreien diese Opfer; doch Gott zeigt keine Gunst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Und jene sind\'s doch, die das Licht verachten und seine Pfade nimmer kennen noch seine Wege je betreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Beim Morgengrauen steht der Mörder auf; er tötet Friedliche und Arme, und in der Nacht schleicht hin der Dieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Des Ehebrechers Auge lauert auf die Dämmerung; kein Auge, denkt er, wird mich sehen, und legt sich eine Hülle vors Gesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Er dringt im Finstern in die Häuser ein. - Bei Tage fürchten sie sich sehr und wollen von dem Licht nichts wissen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'denn ihnen allen ist ein Graus der Morgen, der Augenblick ein Höllenschrecken, wo man sie kennen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Er schwebet leichthin über den Gewässern. \'Verflucht wird ihr Besitz auf Erden.\' Er gibt nicht auf den Weg der Sünder acht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Die Dürre und die Hitze nehmen Schneegewässer fort, die Unterwelt die, so gesündigt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Mitleid vergißt ihn. Gewürm labt sich an ihm, und man gedenkt nicht seiner mehr. Zerschmettert wie ein Baum so wird der Frevler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Er gibt der Unfruchtbaren, Kinderlosen Hab und Gut; den Witwen aber tut er nimmer Gutes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Lang leben läßt er Mächtige durch seine Macht. Da gibt es einen, deran den Lebenden nicht glaubt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'und doch gibt er ihm Sicherheit, auf die er sich verlassen kann. Doch seine Augen wachen über solcher Wege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Hoch stehn sie da. Nur eine kleine Zeit, sie sind nicht mehr. Sie sinken hin, wie alle anderen sterbend. Gleichwie die besten Ähren, also sind sie voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Wenn\'s nicht so ist, wer straft mich Lügen und macht mein Wort zunichte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Darauf erwidert Bildad aus Schuach und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '\"Herrscht er vielleicht in Schrecken? Er, der da Ordnung hält in seinen Höhen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Sind denn nicht zahllos seine Scharen? Und über wen erhebt sich nicht sein Licht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Wie kann nur gegen Gott ein Mensch im Rechte sein und rein erscheinen der vom Weib Geborene?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Des Mondes Schimmer selbst erklärt er nicht für hell; die Sterne sind nicht rein in seinen Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'geschweige denn der Mensch, die Made, der Menschensohn, der Wurm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Darauf erwidert Job und spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '\"Wie trefflich hilfst du doch dem Schwachen und stärkst den Arm den Kraftlosen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Welch feinen Rat gibst du der Unweisheit und offenbarst dem Zweifler soviel Kluges!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Wen hast du denn belehren wollen? Und wessen Geist geht von dir aus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Die Schatten in der Unterwelt geraten außer sich, die Wasser und die sie bewohnen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Die Unterwelt liegt nackt vor ihm und hüllenlos das Totenreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Er spannt den Bären aus im Leeren und läßt die Erde schweben überm Nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Gewässer bindet er in seine Wolken; nicht reißt darunter das Gewölk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Er überzieht des Vollmonds Scheibe, darüber breitend sein Gewölk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Und eine Grenze zieht er über den Gewässern, dort wo sich treffen Licht und Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Des Himmels feste Säulen schwanken; vor seinem Drohen wanken sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Durch seine Kraft weckt er den Ozean; sein Ungestüm bricht er durch seine Klugheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Durch seinen Geist besteht des Himmels Schöne, und seine Hand erschuf die flücht\'ge Schlange.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Das sind nur seines Waltens Säume und nur ein Weniges, was wir so von ihm hören. Wer kann da erst die Donnersprache seiner Allgewalt verstehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Darauf fuhr Job im Vortrag seiner Rede fort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '\"Bei Gott, der mir mein Recht genommen, bei dem Allmächtigen, der mich verzweifeln läßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Solange noch ein Atem in mir bleibt und Gotteshauch in meiner Nase,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'solange kommt nichts Falsches her von meinen Lippen, und meine Zunge dichtet keinen Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Von mir sei\'s fern, euch Recht zu geben, bis zum Tode fern, auf meine Unschuld zu verzichten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Ich halte fest an meiner Rechtlichkeit und lasse sie nicht fahren. Ob keinem meiner Tage tadelt mich mein Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Mein Feind der soll als Schuldiger erscheinen, mein Widersacher als der Ungerechte! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Welche Hoffnung hat der Frevler, wird er hinweggerafft, wenn seine Seele Gott verlangt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Wird Gott denn sein Geschrei erhören, wenn Not ihn überfällt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Kann er vor dem Allmächtigen sich wie ein verwöhntes Kind benehmen, daß er zu jeder Zeit Gott rufen dürfte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Ich will euch über Gottes Hand belehren, euch nicht verhehlend, was beim Allmächtigen beschlossen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Ihr alle habt es selbst gesehen. Was wollt ihr euch so eitlem Wahn ergeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Das ist der bösen Menschen Los bei Gott, dies der Tyrannen Erbe, das sie von dem Allmächtigen erhalten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Hat er viele Kinder, ist\'s für das Schwert, und seine Sprößlinge bekommen nimmer Brot genug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Wer von den Seinen übrigbleibt, wird durch die Pest begraben, und seine Witwen halten nicht die Totenklage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Wenn Silber er wie Sand aufhäuft und Kleider sich zurücklegt gleich wie Lehm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'er legt sie freilich sich zurück; doch der Gerechte kleidet sich damit; das Silber nimmt der Fromme fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Sein Haus baut er dem leeren Vogelneste gleich, wie eine Hütte, die ein Hüter macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Er legt als reicher Mann sich hin und hat noch nicht die Füße eingezogen; er blinzelt mit den Augen noch, da ist er schon nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Gleich Wassern überraschen ihn die Schreckgestalten; des Nachts nimmt ihn der Sturmwind fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Der Ostwind hebt ihn auf; er fährt dahin, und jener wirbelt ihn von seiner Stätte fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Er schießt auf ihn erbarmungslos; von seiner Hand wird er durchbohrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Und seine Wohnstatt klatscht in ihre Hände über ihn und zischt ihn aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '\"Für Silber gibt es eine Fundstätte und einen Ort fürs Gold, das man hier sieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Man holt auch Eisen aus der Erde, Gestein, das man zu Erz umschmilzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Am Ende denkt man an die Finsternis; mit aller Tüchtigkeit durchforscht man das Gestein im Dunkeln und im Finstern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Man läßt sich einen Schacht von fremdem Volke brechen, das so herabgekommen, daß sie nimmer Männer sind, zu tief gesunken, um noch Menschen gleichzustehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'das hingezogen ist nach einem Lande, aus dem zwar Brotkorn sprießt, wo\'s unten aber wird durch Feuer umgewühlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'nach einem Orte, dessen Steine Saphir sind und der daneben Goldstaub liefert');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'und dessen Zugang Adler selbst nicht kennen und den des Geiers Augen nicht erspähen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'den nie die Raubtiere betreten und den der Löwe nie beschreitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Man legt die Hand dort an das Felsgestein und wühlt von Grund die Berge um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Man schneidet Wasseradern in den Felsen an, und Kostbarkeiten aller Art erblickt das Auge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Der Ströme Quellen unterbindet man und bringt Verborgenes ans Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Wo aber findet man die Weisheit? Wo ist der Fundort der Erkenntnis?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Kein Mensch kennt ihren Preis; sie findet nimmer sich im Lande der Lebendigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Der Ozean erklärt: \'Ich hab sie nicht\'; das Meer sagt: \'Ich besitz sie nimmer\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Mit gutem Golde kann man sie nicht kaufen; nicht wird ihr Preis mit Silber dargewogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Sie läßt sich nicht mit Ophirgold aufwiegen; auch nicht mit Onyx und mit Saphirstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Nicht kommen Gold und Glas ihr gleich; noch tauscht man sie für goldene Geräte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'geschweige um Korallen und Kristall. Ein Sack voll Weisheit übertrifft den voller Perlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Nicht kommen Äthiopiens Topase ihr gleich; mit reinstem Gold wird sie nicht aufgewogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Woher nun also kommt die Weisheit? Wo ist der Fundort der Erkenntnis?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Verhüllt ist sie vorm Blicke aller Lebenden; des Himmels Vögeln selbst ist sie verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Es sprechen Tod und Totenreich: \'Wir haben nur von ihr gehört.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Den Weg zu ihr kennt Gott allein; um ihren Wohnort weiß nur er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Bis zu der Erde Grenzen schaut er hin; er sieht, was irgend unterm Himmel ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Als er des Windes Wucht abwog, sein Maß dem Wasser fest bestimmte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'als er des Regens Zeit bestellte und einen Pfad dem Donnerrollen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'da sah er sie und warb sie an, nachdem er sie vor sich gestellt und sie durchmustert hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Er sprach zum Menschen: \'Die Furcht des Herrn ist Weisheit, und Böses meiden heißt: Verständigsein!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Darauf fuhr Job im Vortrag seiner Rede fort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '\"Ach, daß ich wäre wie in früheren Monden, wie in den Tagen, da mich Gott beschützte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'als seine Leuchte über meinem Haupte schwebte und ich bei ihrem Scheine mich ins Dunkel wagte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'So, wie ich war, in meiner höchsten Blüte Tagen, da Gott mein Zelt beschirmte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'als der Allmächtige noch mit mir war, als meine Dienerschaft mich noch umgab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'als meine Gäste sich in Dickmilch badeten, als Bäche Öls bei mir den Boten zur Verfügung standen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Wenn ich zur Stadt hinauf zum Tore ging und auf dem Markte meinen Sitz einnahm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'alsdann verkrochen sich die Knaben, sahn sie mich, und Greise standen auf und blieben stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Die Ratsherrn hielten ein mit Reden und legten auf den Mund die Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Der Edlen Stimme, sie verbarg sich; das Wort blieb ihnen in der Kehle stecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Wer von mir hörte, pries mich selig; wer mich erblickte, lobte mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Ich half dem Armen, der um Hilfe schrie, dem Waisenkinde, dem hilflosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Und armer Menschen Segen kam auf mich; das Herz der Witwe ließ ich jubeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Gerechtigkeit war mein Gewand, das gut mir stand, und meine Rechtlichkeit war Mantel mir und Diadem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Ich war des Blinden Augenlicht und Fuß dem Lahmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Den Armen wollte ich ein Vater sein; selbst Fremder Sache führte ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Des Bösewichts Gebiß zermalmte ich und riß den Raub ihm aus den Zähnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'So dachte ich, in meinem Neste stürbe ich; ich lebte soviel Jahre wie der Phönix.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Zum Wasser reichte meine Wurzel tief hinab; in meinen Zweigen nächtigte der Tau,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'und neu stets würde meine Herrlichkeit an mir; in meiner Hand verjüngte sich der Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Mir hörten sie nur zu und warteten und lauschten schweigend meinem Rat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Wenn ich geredet, sprachen sie nicht mehr; nur meine Rede troff auf sie herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Sie warteten auf mich wie auf den Regen; sie lechzten nach mir wie auf Lenzesregen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Und lächelte ich ihnen zu, so konnten sie\'s nicht glauben, und sie verschmähten nicht mein heitres Antlitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Ich wählte ihren Weg, den sie einschlagen sollten, wie bei der Kriegerschar der König. Ich saß gemächlich obenan wie einer, der den Trauernden Trost spendet.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '\"Und jetzt verlachen solche mich, die jünger sind als ich, ja solche, deren Väter ich nicht beigesellen möchte meinen Herdenhunden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Was sollte mir selbst ihrer Hände Kraft, denn Rüstigkeit geht ihnen doch verloren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Durch Mangel und durch harten Hunger sollen sie sich Nahrung aus der Wüste holen, dem Lande des Orkans und Sturmes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Sie sollten Melde pflücken am Gesträuche, und ihre Nahrung seien Ginsterwurzeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Von Wasserstellen sollten sie vertrieben werden! Man schreie über sie wie Diebe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'daß sie in schauerlichen Schluchten, in Erdlöchern und Felsenhöhlen siedeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'und daß sie im Gebüsche gröhlen und unter Nesseln sich zusammenkauern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Sie, eine Brut so schlecht und ehrlos, sie sollten tief im Staube liegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Und jetzt bin ich ihr Spottgesang; ich diene ihnen zum Gerede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Ja, sie verabscheun mich und rücken fern von mir und scheun sich nicht, mir ins Gesicht zu speien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Er löste mir das Diadem und warf mich auf den Boden, daß sie den Zügel vor mir schießen lassen konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Zur Prüfung stehn die Gegner auf; sie lähmen mir die Füße und werfen gegen mich die Wege für ihr Unheil auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Sie reißen meine Pfade auf, verhelfen mir zum Falle, und niemand hindert sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Sie kommen wie ein breiter Dammbruch her; sie wälzen sich mit Ungestüm heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Da kommen Schrecken über mich; dem Wind gleich jagt mein Glück davon; fort zieht mein Heil wie eine Wolke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Mein Leben ist in mir zerflossen, und jammervolle Tage halten mich gefesselt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Des Nachts bohrt\'s mir in dem Gebein; auf meinen bloßgelegten Knochen kann ich nimmer liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Mit Allgewalt packt er mich an und schnürt mich in des Unterkleides Schlitze ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Er wirft mich in den Schmutz; dem Staub, der Asche bin ich gleich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Ich schreie auf zu Dir. Doch Du hörst nicht auf mich. Ich halte ein; da gibst Du auf mich acht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Du zeigst Dich grausam gegen mich und geißelst mich mit Deiner starken Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du schickst den Wind, mich zu entführen; der Sturm fährt mit mir auf und ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Ich weiß ja wohl: Du willst zum Tod mich treiben, in das Versammlungshaus für alles Lebende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Auf Wunsch jedoch greift er nicht zu, schreit man in seinem Unglück drob um Hilfe. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Beweinte ich nicht den Unseligen; war nicht mein Herz des Armen wegen sehr betrübt? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Weil ich auf Glück gehofft, doch Unheil kam; auf Licht geharrt, doch Dunkel kam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'so ist im Aufruhr ohne Unterlaß mein Inneres. Des Leidens Tage überfielen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Tieftraurig wandle ich einher, wo keine Sonne scheint. Ich trete dem Vereine bei, wo ich nur heulen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Der Schakale Vereinsbruder bin ich und ein Gesell dem Vogel Strauß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Zu schwarz ward meine Haut, daß sie mir bliebe, und mein Gebein ist mir von Glut verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'So diente meine Harfe mir zum Trauerliede, zu bitterem Schluchzen die Schalmei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '\"Ich schloß mit meinen Augen einen Bund. Wie sollte ich auf Jungfraun achten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Was ist mein Teil von Gott da droben, mein Lohn von dem Allmächtigen im Himmel?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Wahrhaftig, Unheil, wie\'s dem Bösewicht gebührt, und Ungemach, das nur für Übeltäter paßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Besieht er denn nicht meine Wege, da er doch alle meine Schritte zählt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, '\"Wenn ich der Falschheit nachgegangen wäre, verweilte auf dem Weg des Truges gern mein Fuß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Mit rechter Waage möge Gott mich wägen, und ohne Schuld wird er mich finden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Wenn meine Schritte je vom rechten Wege bogen, und wenn mein Herz den Augen folgte, und klebte je ein Makel meinen Händen an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'dann zehre nur ein anderer von meiner Saat; entwurzelt werde meine Pflanzung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Wenn\'s mich zum fremden Weibe zog, und stellte ich dem Eheweib des Freundes nach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'dann mahle auch mein Weib für andere, und andere mögen über sie sich beugen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Denn dieses wäre eine Schandtat, ein Verbrechen, vom Richter zu bestrafen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'ein Feuer, das bis zu dem Abgrund fräße und meine Habe all entwurzeln müßte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Mißachtete ich meines Sklaven Recht und meiner Magd, wenn sie mit mir im Streite waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'was wollte ich da machen, wenn Gott jetzt Rache nähme, und untersuchte er, was ihm erwidern?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hat er ihn nicht geformt, im gleichen Schoß wie mich und sie geschaffen in dem gleichen Mutterleibe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Versagte ich den Schwachen einen Wunsch und ließ der Witwe Augen schmachten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'verzehrt\' für mich allein ich meinen Bissen, und durfte nicht die Waise mitessen; -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'seit meiner Jugend blickte sie zu mir gleich einem Vater auf, vom Mutterschoß an leitete ich sie, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'und sah ich einen nackten Bettler und einen Armen hüllenlos,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'wenn seine Hüften keinen Dank mir wußten und er sich nicht von meiner Lämmer Schur erwärmte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'und schwang ich gegen eine Waise meine Faust, weil ich in dem Gerichtstor Beistand für mich sah,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'dann falle mir die Achsel aus der Schulter, und aus dem Rohr werd\' mir der Arm gerissen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Denn fürchterliches Unheil ist meines Gottes Schrecken; vor seiner Hoheit kann ich nicht bestehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Und machte ich zu meinem Götzen Gold und hieß ich Mammon meinen Helfer');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'und sonnte mich an meinen Schätzen, daß ich\'s so weit gebracht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'und wenn ich das Gestirn erblickte, wann\'s sichtbar ward, den lieben Mond, wie er des Weges zog,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'und ließ\' mein Herz sich insgeheim betören und legte meine Hand zum Kusse sich an meinen Mund:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'auch das wär\' ein Vergehn, vom Richter zu bestrafen, weil ich Gott in der Höh\' verleugnet hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Nie freute mich des Feindes Not, und nie frohlockt\' ich, wenn ihn Unheil traf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Nie gab ich meinen Mund der Sünde hin, um seine Seele zum Verfluchen mir zu fordern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'In meinem Zelte sagten die Geringsten: \'Ach, möchte er mit seiner Rache unersättlich sein!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Kein Fremdling durfte je im Freien nächtigen, und jedem Wandersmann stand meine Türe offen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Nie habe ich, wie Adam, meine Missetat verheimlicht, im Busen meine Schuld geborgen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'weil es mir vor dem Auflauf graute und mich der Sippe Schimpf erschreckte, so daß ich stille mich verhalten und nicht aus meiner Tür gegangen wäre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Wer aber hört mich an? Hier meine Unterschrift! Drauf soll mir der Allmächtige erwidern, aufs Schreiben, das als Kläger ich verfaßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Ich trüge einen solchen auf der Schulter und wollt\' ihn mir als Diadem aufsetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Bei jedem meiner Schritte huldigte ich ihm wie einem Fürsten: gleich einem Fürsten träte ich ihm da entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Wenn über mich mein Acker schrie und alle seine Furchen weinten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'und ich verzehrte seine Ernte, ohne zu bezahlen, und ließe die, die ihn bebauten, stöhnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'dann sollen Disteln statt des Weizens und statt der Gerste Unkraut sprossen!\" - Hier enden Jobs Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Da hörten die drei Männer auf, dem Job noch weiter zu erwidern, obwohl er selbst sich für gerecht erachtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Auf dieses hin geriet in Zorn Elihu, der Sohn des Barachel aus Buz, von Rams Geschlechte. Er wurde über Job sehr aufgebracht, weil er sich gegenüber Gott für ganz gerecht erachtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Auch über die drei Freunde ward er zornig, weil sie die rechte Antwort nicht gefunden und Job ins Unrecht setzten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu aber hatte nur bei Job gewartet, solange jene redeten, weil sie betagter als er waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Elihu merkte nun, daß diese drei nichts weiter zu erwidern wußten, und so entbrannte mächtig stark sein Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Nun hob Elihu an, der Sohn des Barachel aus Buz, und sprach: \"Ich bin noch jung an Jahren; aber ihr seid Greise; ich war daher zu schüchtern und scheute mich, bei euch mein Wissen anzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Ich dachte: Mag das Alter reden, der Jahre Fülle Weisheit lehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Allein der Geist im Menschen ist\'s, der Odem des Allmächtigen, der sie verständig macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Nicht die Betagten sind die Weisesten; noch wissen Greise immer, was das Rechte ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Drum sage ich: Hört doch auf mich! Ich möchte kundtun, was ich selber weiß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Als ich auf eure Rede wartete, da überlegt ich mir eure Beweise. Bis euch die rechten Worte kämen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'solange habe über euch ich nachgedacht. Doch keiner von euch überzeugte Job und widerlegte seine Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Sagt nicht: \'Wir fanden Weisheit. Nur Gott vermag ihn zu besiegen, nicht ein Mensch!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Nach meiner Ansicht trug er keine treffenden Beweise vor; ich will ihm nicht erwidern mit Worten gleich den eurigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Sie sind besiegt, antworten nimmer; sie schoben von sich die Beweise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'So fange ich denn an, weil sie nicht reden, dieweil sie dastehn ohne jegliche Erwiderung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Ich möchte gleichfalls meine Lehre künden und kundtun, was ich selber weiß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Denn ich bin voll von Worten; mich drängt der Geist in meinem Innern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Mein Inn\'res ist wie festverschlossener Wein, der in den neuen Schläuchen Luft sich macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Ich rede, um mir Luft zu machen, tu meine Lippen auf und spreche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Für keinen Menschen nehme ich Partei und nenne niemandem zulieb die Dinge anders,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'weil ich es nicht verstehe, die Dinge anders zu benennen. Sonst würde kaum mein Schöpfer mich ertragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '\"Nun aber höre, Job, auf meine Rede! All meinen Worten leih\' dein Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Ich öffne nunmehr meinen Mund; nach Kräften redet meine Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Geradem Sinn entstammen meine Worte; was meine Lippen wissen, sprechen sie auch lauter aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Erschaffen hat mich Gottes Geist, und mich belebt der Odem des Allmächtigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Kannst du\'s, so widerlege mich! Ja, rüste dich zum Kampfe gegen mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Fürwahr, ich bin nach deiner Art, mit Gott verglichen; aus gleichem Ton wie du bin ich geschnitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Nein, Furcht vor mir, die braucht dich nicht zu schrecken, und meine Wucht soll dich nicht niederdrücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Allein vor meinen Ohren sagtest du; den Wortlaut hörte ich genau:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '\'Rein bin ich, ohne Missetat, und lauter bin ich, ohne Fehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Wahrhaftig, er erfindet gegen mich nur Vorwände, erachtet mich für seinen Feind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'und meine Füße legt er in den Block und gibt auf alle meine Wege acht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Sieh, darin hast du unrecht und darin widerspreche ich dir auch; denn Gott ist größer als der Mensch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Warum hast du mit ihm gehadert, weil er auf alle deine Worte keine Antwort gibt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Denn Gott spricht auf die eine und die andere Weise; man faßt es nur nicht auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Im Traume und im Nachtgesichte, wenn Tiefschlaf auf die Menschen fällt im Schlummer auf der Lagerstätte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'dann öffnet er der Menschen Ohr und gibt so ihnen Zeichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'um von der Tat den Menschen abzubringen und vor dem Übermut den Mann zu schützen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'auf daß er seine Seele vor der Finsternis bewahre, sein Leben vor dem Gang zur Unterwelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Hernach wird er gezüchtiget durch Schmerz auf seinem Lager; in seinen Gliedern wütet immerfort ein Krampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Sein Lebenstrieb macht ihm das Brot zum Ekel und seine Seele seine Lieblingsspeise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sein Fleisch vergeht; man kann es nimmer sehen. Sein dürr Gebein wird unscheinbar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'so daß dem Grab sich seine Seele nähert, den Würgern schon sein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Wenn dann ein Fürsprechbote zu ihm tritt, so einer aus dem Freundeskreise, um einem das, was recht, zu melden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'und, seiner sich erbarmend, spricht: \'Erlöse ihn! Laß ihn doch nicht zur Grube fahren! Ich habe Dank empfangen\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'dann strotzt sein Leib von Jugendfrische wieder und wird wie einst in seiner Jugendzeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Er fleht zu Gott, und der erweist ihm Gnade und läßt sein Angesicht ihn unter Jauchzen schauen und gibt zurück dem Armen sein Verdienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Er singt den Leuten vor und spricht: \'Ich hatte schwer gesündigt, das Recht verkehrt; doch ward\'s mir nicht vergolten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Erlöst hat er jetzt meine Seele, auf daß sie nicht zur Grube fahre. Mein Leben freut sich noch am Tageslicht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Sieh, Gott tut dieses alles zwei-, dreimal mit einem Manne,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'um seine Seele so der Grube zu entreißen, daß er des Lichtes der Lebendigen sich freue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Merk auf, Job! Hör mir zu! So schweige! Laß mich reden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Hast du dann Gründe noch, so widerlege mich! Dann sprich! Ich gebe gern dir recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Wo nicht, so hör mir zu und schweige, damit ich dich jetzt Weisheit lehre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Und wieder hob Elihu an und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '\"Ihr Weisen, höret meine Worte, und ihr Verständigen, leiht mir das Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Das Ohr prüft ja die Worte, gleichwie der Gaumen Essen kostet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Das Rechte laßt uns wählen und unter uns erkunden: Was ist richtig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Gesagt hat Job: \'Ich bin schuldlos, und Gott hat mir mein Recht entzogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Ich werde um mein Recht betrogen, und meine Qual ist ganz entsetzlich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Wo ist ein solcher Mann wie Job, der Lästerung wie Wasser trinkt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'und der Gemeinschaft hat mit Übeltätern, mit Frevlern Umgang?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Er spricht: \'Der Mann hat nichts davon, wenn er mit Gott in Freundschaft lebt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Drum hört mir zu, ihr klugen Leute! Fern sei\'s, daß Frevel Gott begeht und Unrecht der Allmächtige!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Nein, nur des Menschen Tun vergilt er ihm, und nach des Mannes Wandel läßt er\'s ihm ergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Wahrhaftig, Gott handelt nicht ungerecht, und der Allmächtige beugt nicht das Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Wem nur auf Erden hat er aufgetragen, wem aufgebürdet irgendeinen Teil der Welt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Wenn er auf sich nur achtete und seinen Geist und Odem an sich zöge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'verginge alles Fleisch zumal; zu Staube würde dann der Mensch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Hast du Verstand, dann höre dies, leih meiner Worte Laut dein Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Kann denn in Milde, wer das Recht haßt, herrschen? Willst du ihn denn beschuldigen, er sei zu sehr gerecht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Ihn, der zu einem König sprechen kann: \'Verworfener!\', \'Du Frevler!\' zu dem Vornehmen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'der nicht Partei für Fürsten nimmt und nicht bevorzugt Reiche vor den Armen. Sie alle sind ja seiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'In einem Augenblicke sterben sie, und mitten in der Nacht wird aufgestört ein Volk und muß davon; Tyrannen setzt man ohne alles Zutun ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Auf eines jeden Weg hinblicken seine Augen, und er sieht eines jeden Schritte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Nicht Finsternis, nicht Dunkel ist, wo sich die Übeltäter bergen könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Denn er bestimmt, daß vor Gericht man nicht vor einem Menschen, vielmehr vor Gott erscheinen muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Er kann die Mächtigen zerschmettern ohne lange Untersuchung; an ihre Stelle setzt er andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Weil er sie unterscheiden kann von ihren Sklaven, drum stürzt er selbst sie mitten in der Nacht, daß sie vernichtet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Er geißelt sie wie Missetäter vor aller Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'weil sie von ihm gewichen, auf keinen seiner Wege Rücksicht nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Sie lassen das Geschrei des Armen zu ihm kommen, daß er der Elenden Geschrei vernehmen muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Und ruht er einmal aus, wer möchte dies verdammen? Wenn er das Antlitz birgt, wer sieht ihn dann? Er ordnet an bei einem andern Volke und bei andern Leuten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'daß nicht ein frevelhafter Mensch darüber herrsche, daß der Zerstreuung nicht ein Volk verfalle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'So sollte man zu Gott wohl sagen: \'Ich trage es und will nicht irre werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Belehre Du mich über das, was ich nicht sehe! Und tat ich Böses, will ich\'s nimmer tun!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Soll etwa er nach deinem Sinn vergelten, weil da das \'Wähle du, nicht ich\' so hassest, und du weißt selbst nicht das geringste?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Mir werden kluge Leute sagen und weise Männer, die mich hören:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '\'Ganz, ohne Einsicht redet Job, und seinen Worten fehlt die Überlegung.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Als Muster wird sich Job für alle Zeit bewähren bei Schlechten wegen seiner Art zu folgern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Zu seiner schlechten Aufführung fügt er noch einen Frevel; auf uns hier schlägt er ein und redet Freches wider Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Und wieder hob Elihu an und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '\"Ja, hältst du das für Recht und meinst du das mit \'meinem Rechthaben vor Gott\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Du sagst: \'Was nützt es Dir? Was nützt es mir, wenn ich nicht sündige?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ich will dir drauf die Antwort geben und deinen Freunden hier bei dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Schau auf zum Himmel; sieh! Blick zu den hohen Wolken über dir empor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Du hast gesündigt. Was tust du ihm damit? Sind deiner Sünden noch so viel, was machst du ihm damit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Und bist du fromm, was schenkst du ihm? Was nur empfängt er da aus deiner Hand?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Doch deinesgleichen geht dein Frevel an, die Menschenkinder deine Frömmigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Man schreit wohl über der Bedrückung Menge, führt Klage ob der Großen Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Doch niemand fragt: \'Wo bleibt da Gott, mein Schöpfer, der in der Nachtzeit spricht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'der vor des Feldes Tieren uns belehrt, uns vor des Himmels Vögeln Weisheit schenkt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Dann schreit man ob des Übermuts der Bösen; doch er schenkt kein Gehör.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Zu nichts führt es, so sagst du, nimmer höre Gott, und der Allmächtige seh\' dies Treiben nicht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'zumal du sagst, du könnest ihn nicht sehen; der Streitfall liege ihm zwar vor, du aber müßtest immer auf ihn warten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'und weil er sich nicht zeige, so strafe er im Zorne; er wolle nichts von Urteil wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Da redet Job denn doch gar unvernünftig; er macht viel Redens ohne Einsicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu fuhr nun weiter fort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '\"Ein wenig warte noch, daß ich dich unterweise! Denn noch spricht manches auch für Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Ich muß nur meinen Vortrag weiter ausdehnen; doch werde ich mein Tun rechtfertigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Denn nimmer sollen meine Worte dich enttäuschen, die ich an dich, Rechthaber, richte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Sieh, Gott ist fest und widerspricht sich nicht; er ist durchaus von festem Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Er schenkt dem Frevler nicht das Leben; dem Armen aber gibt er Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Von Frommen zieht er nicht die Augen ab; sogar mit Königen läßt er auf dem Thron sie sitzen, in Pracht und Herrlichkeit, und werden sie dann stolz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'so legt man sie in Ketten, und sie werden so gefesselt in des Elends Stricken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Dann hält er ihnen vor ihr Treiben, ihre Sünden, daß sie stolz geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Und so tut er ihr Ohr der Warnung auf und heißt sie umkehren von Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Gehorchen sie in Unterwürfigkeit, dann fließen ihre Tage in Glückseligkeit, in Wonne ihre Jahre hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Doch wenn sie nicht gehorchen, rennen sie ins Dunkle und sie sterben in Verblendung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Ruchlose Leute aber wecken Zorn und rufen nicht um Hilfe, wenn er sie fesselt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Hin stirbt so in der Jugendfrische ihre Seele, ihr Leben in der Vollkraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'In seinem Elend rettet er den Armen, dieweil er in der Not ihr Ohr eröffnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Er lockt auch dich aus der Bedrängnis Rachen. An ihre Stelle träte Freiheit, unbeengt, und deines Tisches Schüssel würde voll von Fett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Bist du von frevelhaftem Urteil aber voll, dann trifft auch dich gerechtes Urteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Denn Zorn verführe dich nicht zu dem Übermaße, der Streit um Lösung soll dich nicht verleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Wird\'s dein Geschrei in Ordnung bringen? Unnötig sind ja all die Kraftanstrengungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Nicht wünsche dir die Nacht herbei! An ihre Stelle treten Unruhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Nimm dich in acht und kehre nimmer dich dem Frevel zu! Du hast dazu mehr Lust als zu dem Leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Sieh, Gott ist groß in seiner Macht. Wer ist ein Lehrer gleich wie er?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Wer stellt ihn über seinen Weg zur Rede? Wer sagt nur: \'Du hast schlecht gehandelt\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Bedenk, daß du sein Tun des Irrtums zeihst, das andere in Lobliedern besingen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Und alle Menschen haben ihre Lust daran; die Sterblichen betrachten es seit fernsten Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Sieh, Gott ist alt, weit über unsere Begriffe, und unerforschlich seiner Jahre Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Er zählt die Wassertropfen ab, daß sie in seinen Nebel hin als Regen sickern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'den Wolken rieseln lassen, auf viele Menschen niederträufelnd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Wer vollends hätte Einsicht in der Wolken Weite, in das Gedröhne seines Wohngezeltes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'wenn er darin sein Rollen weithin tönen läßt und dann des Meeres Quellen niederrinnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Denn damit gibt er Völkern Nahrung, stellt Speise her in großer Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Er birgt den Blitzstrahl in den Händen, befiehlt ihm, wo er einzuschlagen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Er zeigt ihm seinen Freund; den Frevler aber läßt er ihn durchbohren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, '\"Darob erzittert mir das Herz und hebt sich weg von seiner Stelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Auf seine Stimme hört voll Furcht, das Wort, das seinen Mund verläßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Er sendet\'s unterm ganzen Himmel hin, dazu sein Licht bis zu der Erde Säumen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Und hintendrein brüllt eine Stimme; mit einer Stimme, allgewaltig, donnert es, und nichts hält sie zurück, wenn sein Befehl sich hören läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gott donnert wunderbar mit seiner Stimme, er, der so Großes tut, so Unbegreifliches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Dem Schnee gebietet er: \'Fall auf die Erde!\', so zu dem Regenguß, so zu gewaltigen Wolkenbrüchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Dann mahnt er allgemein, es solle jeder Mensch sein Werk beachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Da geht das Wild selbst ins Versteck und ruht auf seiner Lagerstatt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Dann kommt der Sturm aus seiner Kammer, und von den rauhen Winden kommt die Kälte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Vor Gottes Odem aber schmilzt das Eis; die Wassermasse kommt in Fluß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Der Nordwind scheucht alsdann die Wolken, und das Gewölk zerstreut sein Sausen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Er dreht sich um sich selbst, von ihm geführt, er tut, was immer er ihn heißt auf dieser ird\'schen Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Er sendet ihn zur Strafe und zum Fluch, doch auch zum Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Vernimm dies, Job! Merk auf, beachte Gottes Wunder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Begreifst denn du, wie Gott bei alldem waltet und seinen Strahl in seiner Wolke zucken läßt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Begreifst du, wenn die Wolken alles überziehen, du Wunder der Allwissenheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'wie dir die Kleider durch die Hitze lästig werden, wenn durch den Süd die Erde stille liegt? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Kannst du, gleich ihm, die lichten Höhen wölben, die also fest wie ein gegossener Spiegel sind? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Zeig mir doch an, was wir da sagen wollten! Wir finden uns gar nicht zurecht vor Düsterkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Wird sie verscheucht auf mein Geheiß? Kann jemand ihr befehlen, zu verschwinden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Nichts Lichtes sieht man mehr, ist\'s doch so dunkel durch die Wolken. Da streicht ein Wind daher und reinigt sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Von Norden her erscheint es golden, und Gott, dem Furchtbaren, gebührt der Ruhm davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Nie werden wir begreifen den Allmächtigen. Er ist so groß an Macht und Rechtlichkeit, und nicht verschleppt er die gerechte Sache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Drum fürchten ihn die schlichten Leute. Doch die sich weise dünken, die begreifen all das nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Darauf antwortete der Herr dem Job nach dem Gewitter also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '\"Wer ist denn dieser, der mit einsichtslosen Worten so dunkel findet meine Pläne?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Auf, gürte deine Lenden wie ein Mann! Ich will dich fragen; du belehre mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Wo warst du denn, als ich die Erde gründete? Vermelde es, wenn Einsicht dir bekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Wer nur bestimmte ihre Maße? Du weißt es ja. Wer hat die Meßschnur über sie gespannt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Worauf sind ihre Pfeiler eingesenkt? Wer hat für sie den Schlußstein eingesetzt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Wo warst du, als die Morgensterne jubelten, als alle Gottessöhne jauchzten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Wer schloß das Meer mit Toren ein, als dies hervorbrach wie aus einem Mutterschoß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'als ich Gewölk zu seinem Kleide machte und dichte Finsternis zu seinen Windeln?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Ich gab ihm mein Gesetz, versah mit Riegeln seine Tore');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'und sprach: \'Bis hierher und nicht weiter! Hier soll sich brechen deiner Wogen Überschwang!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hast du in deinem Leben je dem Morgenrot geboten, dem Frührot seine Stätte angewiesen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'der Erde Säume zu umfassen, damit die Frevler von ihr schwänden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Sie wandelt sich gleich Siegelton; sie färbt sich gleichwie ein Gewand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Den Frevlern wird ihr Licht entzogen; zerschmettert wird der schon erhobene Arm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Gelangtest du bis zu des Meeres Strudeln? Bist du gewandelt auf der Tiefe Grund?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Und öffneten sich dir des Todes Tore, und schautest du des tiefen Dunkels Hüter?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hast du der Erde Breiten überschaut? Vermelde, wenn du dies alles weißt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Wo ist der Weg zur Wohnstätte des Lichtes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'wo ist der Ort der Finsternis, auf daß du jenes zum Gebiete dieser führen und ihrer Wohnung Wege zeigen kannst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Du weißt es ja; denn damals wurdest du geboren, und deiner Tage Zahl ist groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Bist du gekommen zu des Schnees Kammern? Hast du erblickt des Hagels Speicher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'den für die Drangsalzeit ich aufgespart, für Kampf- und Fehdetage?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Wo ist der Weg dahin, wo sich der Sturm zerteilt, von wo der Ostwind auf die Erde sich verbreitet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Wer hat Kanäle für den Regen hergestellt und einen Weg dem Wetterstrahl,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'um Regen menschenleerem Land zu geben, der Wüste, in der keine Leute wohnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'um öde Wildnis zu ersättigen, damit sie Pflanzen sprossen lasse?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Hat denn der Regen einen Vater? Wer hat die Tautropfen erzeugt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Aus wessen Schoße kommt das Eis? Wer hat des Himmels Reif geboren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Gleich dem Kristall verdichtet sich das Wasser; der Wasserfluten Fläche hält dann fest zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Verknüpfest du die Bande der Plejaden, oder lösest du die Fesseln des Orion?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Führst du den Tierkreis aus zu seiner Zeit, und leitest den Bären du samt seinen Jungen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Erkennst du die Gesetze der Himmelshöhn? Bestimmst du ihre Herrschaft für die Erde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Erhebst du zu der Wolke deine Stimme? Bedeckt dich dann ein Wasserschwall?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Entsendest du die Blitze, daß sie gehen und zu dir sagen: \'Hier sind wir\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Wer legte in die Wolken Weisheit? Oder wer verlieh der Wolkenmasse Klugheit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Wer treibt die Wolken weise fort? Wer legt des Himmels Krüge um,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'auf daß zu Gußwerk fließt der Staub zusammen und fest die Schollen aneinanderkleben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Erjagst du für die Löwin Beute? Und stillest du die Gier der jungen Leuen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'wenn in den Lagerstätten sie sich ducken, im Dickicht auf der Lauer liegen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Wer gibt dem Raben seine Atzung, wenn seine Jungen schrein zu Gott und ohne Nahrung flattern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, '\"Vielleicht kennst du der Gemsen Werfen? Acht gibst du auf der Hirschkuh Kreißen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Die Monde zählst du, die sie trächtig gehen? Die Zeit weißt du, da sie gebären?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Sie krümmen sich und trennen selber ihre Schnüre und machen ihren Nachwuchs frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Und ihre Jungen werden stark; im Freien wachsen sie; sie laufen fort und kehren nimmermehr zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Wer hat den wilden Esel freigelassen? Wer ließ den Wildfang in die Freiheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'dem ich die Wüste zur Behausung gab, die Salzsteppe zur Wohnung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Er spottet des Getöses in der Stadt; der Treiber Lärmen hört er nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Was auf den Bergen er erspäht, ist seine Weide, und allem Grünen spürt er nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Wird dir der Wildochs willig dienen? Und nächtigt er an deiner Krippe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Kannst du den Wildochsen an einen Zugstrick binden? Wird er, dir folgend, in den Tälern Gründe eggen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Verläßt du dich auf ihn, weil seine Kraft so groß, und überlässest du ihm deine Ernte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Wirst du ihm zutrauen, daß er auch dresche und deine Saaternte heimbringen helfe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Des Straußes Flügel schlägt gar übermütig. Wennschon ein Storch nach Schwingen und nach Federn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'so überläßt er doch der Erde seine Eier und läßt sie auf dem Boden wärmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Und er vergißt, daß sie ein Fuß zertreten, das Wild der Steppe sie zerdrücken könnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Und er behandelt seine Jungen hart, als ob sie nicht die seinen wären, ganz sorglos, ob umsonst nicht seine Mühe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Denn Gott hat Klugheit ihm versagt und keinen Anteil an Verstand gegeben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'sonst würde er an hochgelegenen Orten brüten und so des Rosses und des Reiters spotten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Verleihst du wohl dem Rosse Heldenkraft, bekleidest seinen Hals mit einer Mähne,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'bewirkst du, daß es wie ein Rauchfang dampfe? Erschreckend ist sein mächtig Wiehern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Voll Freude springt es in das Tal; voll Kraft stürzt es den Harnischen entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Des Schreckens lacht\'s, hat keine Angst und macht nicht kehrt vorm Schwerte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Der Köcher klirrt auf ihm, der Speer, der blitzende, die Lanze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Mit Toben und mit Ungestüm scharrt\'s auf dem Boden, hält nimmer fest, tönt die Trompete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Bei dem Trompetenklang ruft\'s: \'Hui!\' Von ferne wittert es den Streit, der Fahrer Donnerruf, das Schlachtgeschrei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Nach deinem Gutdünken zieht wohl der Habicht fort und breitet nach dem Süden seine Flügel aus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Auf dein Geheiß fliegt wohl so hoch der Adler und nistet in der Höhe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Er wohnt und horstet auf dem Felsen, auf Felsenzacken, auf der hohen Wacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Von dort erspäht er sich den Fraß; in weite Fernen blicken seine Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Und seine Brut stürzt sich auf Blut; wo Leichen sind, da ist auch er.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Der Herr erwiderte dem Job und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '\"Ist nun der Streit mit dem Allmächtigen zu Ende? Wer Gott anklagt, antworte drauf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Und Job erwiderte dem Herrn und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '\"Ich bin doch zu gering, daß ich Dir Antwort gebe; ich lege meine Hand auf meinen Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Einmal hab ich geredet; ich widerspreche nimmer. Ein zweitesmal tu ich\'s nicht wieder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Der Herr erwiderte dem Job nach diesem Wettersturm und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '\"Auf, gürte deine Lenden wie ein Mann! Ich will dich fragen; du belehre mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Willst du mein Recht vielleicht zunichte machen und mich verdammen, daß du Recht behältst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Hast du denn einen Arm wie Gott? Kannst du gleich diesem donnern lassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Mit Hoheit schmücke dich und mit Erhabenheit. Umkleide dich mit Glanz und Herrlichkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Laß deines Zornes Gluten sich ergießen! Und wirf mit deinen Blicken jeden Stolzen nieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Mit einem Blick demütige jeden Stolzen! An ihrem Orte wirf die Frevler nieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Verbirg im Staube sie zumal. Und steck ihr Angesicht an den verborgenen Ort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Dann will auch ich dich loben, wenn du dir selber hilfst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Das Nilpferd sieh dir an, das ich geschaffen, im Vergleich zu dir! Gleich einem Rinde frißt es Gras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Betrachte aber doch die Kraft in seinen Lenden und seine Stärke in den Muskeln seines Leibes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Gleich einer Zeder streckt es seinen Schweif hinaus. Die Sehnen seiner Schenkel, dicht verschlungen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'und seine Knochen sind wie eherne Röhren, und seine Beine sind wie Eisenstäbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Es ist dies Gottes Meisterwerk; sein Schöpfer gab ihm eine Sichel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Die Berge liefern ihm das Futter; es spottet aller wilden Tiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Und unter Lotosbüschen lagert\'s dort in dem Versteck von Rohr und Schilf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Und Lotosbüschel überdachen es als Schattenspender; des Baches Weiden halten es umfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Wenn sich ein Strom ergießt, wird ihm nicht bange. Es bleibt getrost, ergösse sich ein Jordan ihm ins Maul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Kann man\'s mit seinen Augen bannen? Will man mit Stricken wohl die Nase ihm durchbohren? Kannst du das Krokodil mit einer Angel ziehen und seine Zunge mit dem Stricke niederdrücken? Kannst du ihm durch die Nase eine Binsenschnur durchziehen? Durchbohren mit dem Haken seine Backe? Wird\'s dir viel Flehens machen; wird\'s dir wohl gute Worte geben? Mit dir Verträge schließen, daß du\'s zum Knecht für immer nehmest? Kannst du mit ihm wohl spielen wie mit einem Vöglein? Und bindest du\'s für deine Mädchen an, die seinetwegen Freundinnen einladen und unter Mägdlein es verlosen? Kannst du mit Stacheln seine Haut ihm spicken und seinen Kopf mit schwirrenden Harpunen? Leg\' deine Hand einmal daran! Bedenke, welch ein Kampf! Du tust\'s nie wieder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '\"Ja, seine Hoffnung wird getäuscht; bei seinem bloßen Anblick stürzt er hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Kein Mensch ist so verwegen, daß er\'s reizt. \'Wer stellt sich vor mich hin?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Wer griff mich an, und ich ließ diesen unversehrt entkommen? Mein wär ein solcher unterm ganzen Himmel.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Von seinen Gliedern kann ich nimmer schweigen und nicht von seiner Kraft, vom Ebenmaße seines Baues.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Wer kann sein äußeres Kleid beschreiben, und wer sein doppeltes Gebiß abzeichnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Wer läßt in seines Rachens Doppeltüre sehen? Um seine Zähne lagert Schrecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Sein Rücken ist aus Rinnen voller Schilde, in engem Anschluß fest verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Eins reiht sich an das andere; dazwischen gibt es keine Fuge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Ein jedes hängt am anderen fest. Sie schließen unzertrennlich sich zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Sein Niesen läßt das Licht aufleuchten, und seine Augen sind der Morgenröte Wimpern gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Aus seinem Rachen fahren Fackeln, sprühen Feuerfunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Aus seinen Nüstern fährt ein Dampf gleichwie aus einem siedend heißen Topf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Sein Odem zündet Kohlen an; aus seinem Rachen fahren Flammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'In seinem Nacken wohnt die Kraft; ein Sack hängt vorn an ihm herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Die Wampen seines Fleisches haften fest, ihm angegossen, unbeweglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Sein Herz fest wie ein Stein, fest wie ein unterer Mühlstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Wenn\'s auffährt, zagen Stärkste, sie taumeln ob der Wasserwirbel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Wenn man\'s mit einem Schwerte trifft, hält dies nicht stand, nicht Lanze, Wurfgeschoß noch Panzer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Das Eisen achtet es für Stroh, für morsches Holz das Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Nicht können\'s Pfeile je durchbohren, und Schleudersteine sind ihm wie Strohhalme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Auch Keulen gelten ihm wie Halme, und übers Lanzenschwirren spottet es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Und unten sind an ihm ganz spitze Scherben. Wie eine Dreschwalze, so fährt es auf dem Schlamm dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Wie einen Topf, so läßt\'s die Tiefe brodeln; es macht das Wasser wie in einem Salbenkessel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Ein Pfad aufleuchtet hinter ihm; man hält die Flut für Silberhaar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Auf Erden ist nicht seinesgleichen; geschaffen ist\'s, sich nicht zu fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Auf alles Mächtige schaut es voll Stolz, ist\'s doch ein König über alle stolzen Tiere.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Und Job erwiderte dem Herrn und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '\"Ich weiß es, daß Du alles kannst, daß kein Gedanke Dir verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '\"Wer ist nur der, der Pläne dunkel findet, unverständlich?\" Deshalb, das sehe ich jetzt ein, im Unverstande habe ich gesprochen von Dingen, viel zu wunderbar für mich, und die ich nicht begriffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '\"So höre! Laß mich reden! Ich will Dich fragen, Du unterweise mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Vom Hörensagen hatte ich von Dir gehört; nun aber hat mein Auge Dich gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Drum widerrufe und bereue ich, auf Staub und Asche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Nachdem der Herr mit Job also gesprochen, verkündete der Herr dem Eliphaz von Teman: \"Mein Zorn ist wider dich entbrannt und deine beiden Freunde hier. Ihr habt nicht recht von mir geredet, so wie mein Diener Job.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'So nehmet sieben Farren euch und sieben Widder! Und geht zu meinem Diener Job und bringt für euch Brandopfer dar! Mein Diener Job soll für euch beten! Mich hält die Rücksicht auf ihn ab, in übereilter Art an euch zu handeln. Ihr habt nicht recht von mir geredet, so wie mein Diener Job.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Da gingen Eliphaz von Teman, Bildad von Schuach und von Naama Sophar hin und taten, wie sie der Herr geheißen. Der Herr erhob alsdann Jobs Angesicht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'er hatte doch Jobs Los gewendet, weil er für andere gebetet hatte. Und doppelt soviel gab der Herr dem Job, als früher er besessen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Da kamen alle seine Brüder zu ihm und die Schwestern und alle seine alten Freunde und speisten dann mit ihm in seinem Hause, bezeugten ihm ihr Mitleid und sprachen ihm Trost zu ob all des Unglücks, das über ihn der Herr gebracht, und jeder schenkte ihm nun einen Beutel und einen goldenen Ring.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Der Herr gab Job jetzt noch mehr Glück, als er zuvor besessen; er brachte es auf 14.000 Schafe, 6.000 Kamele, 1.000 Joch Rinder und 1.000 Eselinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Und er bekam auch zweimal sieben Söhne, sowie drei Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Die erste nannte er \"das Täubchen\", die zweite \"Wohlgeruch\", die dritte \"Schminkhörnchen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Im ganzen Lande fand man keine solch\' schönen Frauen wie die Töchter Jobs. Ihr Vater gab auch ihnen Erbteil mit den Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Nach diesen Zeiten lebte Job noch hundertvierzig Jahre, sah Kinder noch und Kindeskinder, im ganzen vier Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Und Job starb alt und lebenssatt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Heil sei dem Mann, der nach der Frevler Rat nicht wandelt, nicht auf dem Weg der Sünder bleibt, nicht in der Spötter Runde weilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'den nur des Herren Lehre freut, der seine Lehre Tag und Nacht betrachtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Er grünet wie der Baum, verpflanzt an Wasserbäche, der Früchte trägt zur rechten Zeit, und dessen Laub nicht welkt. Und was er tut, gerät ihm gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nicht so die Frevler! Sie sind wie Spreu, die jeder Wind verweht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Drum halten Frevler nicht in dem Gerichte stand; die Sünder sind nicht bei der Frommen Sammlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Der Frommen Weg: des Herren Sorge; der Frevler Weg: der Untergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Was toben denn die Heiden und schmieden eitle Pläne Nationen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Der Erde Könige verbünden sich, und Fürsten pflegen Rat, dem Herrn und dem, den er gesalbt, zum Trotz:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Auf! Laßt uns ihre Fesseln sprengen, ihr Joch abschütteln!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Der in dem Himmel thront, lacht ihrer; der Herr verspottet sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Doch schließlich redet er in seinem Zorn mit ihnen; mit seinem Grimme schreckt er sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Ich selber habe meinen König eingesetzt zu Sion über meinen heiligen Berg.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Des Herrn Entschließung will ich künden; er sprach zu mir: \"Du bist mein Sohn; ich habe heute dich gezeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'So fordere von mir! Ich gebe Heidenvölker zum Besitze dir, der Erde Grenzen dir zum Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Zerschelle sie mit einem Eisenstocke, zerschmettere sie gleich irdenem Gefäß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Nun, Könige! Bedenkt es wohl! Erdenrichter, laßt euch warnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'In Ehrfurcht dient dem Herrn, und werft euch zitternd nieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Und huldigt ohne Falsch, daß er nicht zürne und ihr auf irrem Weg verderbet! Ein kleines nur, und schon entbrannt sein Zorn. Heil allen, die bei ihm sich bergen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein Lied Davids auf der Flucht vor seinem Sohne Absalom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Wie sind\'s, Herr, meiner Dränger viel! So viel, die aufstehn gegen mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Wie mancher sagt von mir: \"Für ihn gibt\'s keine Hilfe mehr bei Gott!\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Du aber, Herr, Du bist um mich ein Schild; Du bist mein Siegesruhm, und Du erhebst mein Haupt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ich rufe laut zum Herrn; von seinem heiligen Berg erhört er mich. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ich leg mich nieder, schlafe ein, und ich erwache wieder; der Herr verleiht mir Kraft. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Ich fürchte mich deswegen nicht vor vielen Tausenden, die um mich her sich lagern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Auf, Herr! Mein Gott! Hilf mir! Oh, schlügest Du doch allen meinen Feinden ins Gesicht, zerschmettertest Gottlosen ihre Zähne! - Des Herren ist der Sieg, Dich hoch zu preisen Deines Volkes Pflicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Auf den Siegesspender, mit Saitenspiel, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Erhöre mich, Gott meines Heils, dieweil ich rufe! Verschaffe Luft mir in der Not! Sei gnädig Herr! Erhöre mein Gebet! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Wie lang, ihr Männer, wird geschändet meine Ehre und liebet ihr den Tand und jaget nach dem Truge? (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Bedenkt, daß seine Frommen so der Herr auszeichnet: \"Mich hört der Herr, sobald ich zu ihm rufe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Wenn ihr euch keine Ruhe gönnet, dann sündiget doch nicht! Zerbrecht ihr euch den Kopf auf eurem Lager, dann schweiget wenigstens! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Bringt lieber richtige Opfer dar! Vertraut dem Herrn! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Die Masse sagt: \"Wer läßt uns Gutes nur genießen?\" Uns aber laß das Licht, Herr, Deines Angesichtes leuchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Mehr Freude legst Du mir ins Herz, als wenn sich Korn und Wein vermehrt. Ich kann mich sorglos niederlegen und mich dem Schlummer überlassen; denn Du läßt mich ganz ungestört und sicher ruhen, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Auf den Siegesspender, für den Chor, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Hör meine Worte, Herr! Merk auf mein Seufzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Auf meinen Angstschrei horche, mein König und mein Gott! Ich bete ja zu Dir. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'In aller Frühe, Herr, erhöre meinen Ruf! Dein harre ich in aller Frühe und spähe aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Du bist ja nicht ein Gott, dem Übermut gefällt; nicht hat das Böse Reiz für Dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Vor Deine Augen dürfen Dir nicht Spötter kommen; Du hassest alle Übeltäter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Und Du vertilgst die Lügenredner. - Dem Herrn ein Abscheu sind des Blutes und des Truges Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Durch Deine große Güte läßt Du mich Dein Haus betreten; zu Deinem heiligen Palast gewandt, sink ich in Ehrfurcht betend vor Dir nieder. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Führ mich zu der Gerechtigkeit, die Dir gefällt! Um meiner Feinde willen, Herr, ebne mir Deinen Weg! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'In keinem Mund von Wahrheit eine Spur! In ihrem Herzensgrund ist Unheil und ihre Kehle eine offene Grube! Mit ihrer Zunge heucheln sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Gott! Strafe sie! Durch ihre eigenen Pläne laß sie niedersinken! Zu Fall bring sie durch ihrer Frevel Menge! Sie trotzen Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Dann freu\'n sich alle, die zu Dir sich flüchten, frohlocken ewiglich, daß Du sie schirmst. Dann jubeln über Dich, die Deinen Namen lieben. Du selbst, Herr, segnest ja den Frommen, und wie mit einem Schild umgibst Du ihn mit Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Auf den Siegesspender, mit Saitenspiel, ein Gesang, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Herr! Straf mich nicht in Deinem Zorn! In Deinem Grimme züchtige mich nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Herr! Sei mir gnädig! Ich vergehe, Herr! Verschone mich! Erschüttert ist mein Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Die Seele ist mir ganz verwirrt. Und Du, Herr, ach wie lange noch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Noch einmal rette mir du Leben, Herr! Hilf mir um Deiner Gnade willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Im Tode denkt man Deiner nicht. Wer lobte Dich im Schattenreich? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Von meinem Seufzen bin ich müde; ich bade jede Nacht mein Bett und netze meine Ruhestatt mit Tränen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Vor Kummer schlaflos ist mein Auge beim Blick auf alle meine Widersacher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Weicht, Übeltäter all\', von mir! Mein lautes Weinen hört der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Mein Flehen hört der Herr; der Herr nimmt meine Bitte an. Beschämt, bestürzt sei\'n alle meine Feinde! Zurück! In einem Augenblicke seien sie zuschanden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Von David, ein Geheimspruch, den er dem Herrn gesungen wegen des ungestümen Benjaminiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Ich suche Schutz bei Dir, Du Herr, mein Gott. Komm mir zu Hilfe wider alle, die mir nachstellen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Nicht soll man mich zerfleischen, wie\'s die Löwen tun, nicht rettungslos zerreißen! Du befreie mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Du, Herr, mein Gott, wenn solches ich getan, wenn Frevel klebt an meiner Hand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'wenn ich vergolten Böses meinen friedlichen Gefährten, wenn ich mich meines Gegners voller Hinterlist entledigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'dann eile mir der Feind auch nach und greife mich! Zu Boden trete er mein Leben, daß in den Staub mein Wesen sinke! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Auf, Herr, in Deinem Zorne! Erheb Dich grimmig gegen meine Feinde! Mein Gott, wach auf! Bestelle das Gericht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Die Völkerschar umringe Dich! Hoch über ihr nimm Deinen Sitz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Herr, schaff mir Recht, der Du die Völker richtest! Nach meiner Rechtlichkeit und Lauterkeit geschehe mir, o Herr! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Der Frevler Tücke sei zu Ende! Richt den Gerechten auf! Du bist\'s, der Herz und Nieren prüft, doch ein gerechter Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bei Gott steht meine Ehre; Er hilft den frommen Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gott führt des Frommen Sache wider den, der allzeit übermütig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Fürwahr, der schärft sein Schwert schon wieder und spannt den Bogen, zielt mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Doch nur für sich bereitet er die mörderischen Waffen und macht die Pfeile scharf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Also empfängt er Unheil selbst, ist unheilschwanger und gebiert Enttäuschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Er gräbt an einem Grab und höhlt es aus und gleitet selber in die Gruft, die er gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Sein Frevel trifft sein eigen Haupt; sein Unrecht stürzt auf seinen Scheitel nieder. Den Herrn will ich lobpreisen, daß er so gerecht, und von dem Ruhm des Herrn, des Höchsten, singen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Auf den Siegesspender, ein Kelterlied, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Herr, unser Herr! Wie glorreich ist Dein Name auf der ganzen Erde! Wie herrlich ist Dein Ruhm am Himmel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Aus Kindes- und aus Säuglingsmund hast Du Dir Ruhm geschaffen, zum Trutz den Widersachern Dein, und machst so Feind und Groller stumm. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Betrachte ich den Himmel, Deiner Finger Werk, den Mond, die Sterne, die Du all erschaffen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Was ist der Mensch, daß seiner Du gedenkst? Das Menschenkind, daß sein Du achtest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Nur wenig hast Du ihn der Gottheit nachgesetzt, mit Glanz und Herrlichkeit gekrönt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'ernennest ihn zum Herrn der Werke Deiner Hände und unterwirfst ihm alles:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'die Schafe und die Rinder all, des Feldes Wild,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'des Himmels Vögel und des Meeres Fische, was sonst noch durch die Meeresstraßen zieht. Herr, unser Herr! Wie glorreich ist Dein Name auf der ganzen Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Auf den Siegesspender, beim Tode eines Kindes, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Ich preise Dich von ganzem Herzen, Herr. Ich will erzählen alle Deine Wundertaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ich will mich jubelnd Deiner freuen, besingen Deinen Namen, Höchster,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Wenn meine Feinde rückwärts weichen, durch Sturz vor Dir vernichtet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Verschaff mir Recht, Gerechtigkeit als Richter der Gerechtigkeit auf hohem Throne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Schilt aus die Heiden; Frevler tilge! Lösch ihren Namen ewig aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Dahin die Feinde! Für alle Zeit vergessen ihre Städte und vernichtet! Und selbst ihr Angedenken sei verschwunden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'In Ewigkeit verbleibt der Herr; schon läßt er zum Gerichte seinen Thron aufstellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Gerecht wird er den Weltkreis richten und nach Gebühr den Völkern Urteil sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'So wird der Herr zum Horte den Bedrückten; ein Hort zur Zeit der Trübsal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Darum vertrauen die Bekenner Deines Namens Dir; denn Du verläßt die nicht, Herr, die Dich suchen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Lobsingt dem Herrn, der auf dem Sion thront! Tut kund den Völkern seine Schreckenstaten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Der Bluttat rächt, gedenkt auch ihrer noch, den Klageschrei der Dulder überhört er nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Herr! Sei mir gnädig! - Sieh, was ich von meinen Hassern leide! Du kannst mir aus des Todes Pforten helfen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'auf daß ich an der Sions-Tochter Toren all Deinen Lobpreis künde und jubelnd mich an Deinem Heil erfreue! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Die Heiden sollen in die Grube stürzen, die sie selbst gegraben; im Netz, das heimlich sie gelegt, die Füße sich verfangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Kund tue sich der Herr, vollziehe das Gericht! In seiner eigenen Hände Werk verstricke sich der Bösewicht! Higajon. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Zur Hölle sollen Frevler fahren, die Heiden all, die Gottvergessenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Der Arme bleibt nicht ewiglich vergessen. Nicht ist der Elenden Erwartung immerfort vergeblich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Auf, Herr! Laß Menschen nicht obsiegen! Die Heiden laß vor Dir gerichtet werden! Gib ihnen eine Lehre, Herr, auf daß die Heiden spüren, daß sie doch nur Menschen sind! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Warum stehst Du so ferne, Herr, entziehst Dich in der Zeit der Not? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Gequält wird durch des Frevlers Übermut der Arme; er fängt ihn durch die Ränke, die er sich ersonnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Gejubelt hat nach Herzenslust der Frevler, Gewissenlosigkeit gepriesen und dazu den Herrn geschmäht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Der Frevler spricht in höchstem Stolz: \"Man ahndet nichts; dafür gibt\'s keinen Gott.\" Bestehen bleiben alle seine Pläne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Sein Weg ist stets erfolgreich, und ferne sind ihm Deine Strafgerichte; all seine Gegner höhnt er aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Er denkt bei sich: \"Ich wanke nimmer in der Zukunft Zeit, in der kein Übel ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Voll Meineid, Trug und Arglist ist sein Mund, und was er spricht, ist Unheil und Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Er liegt auf Lauer hinter Zäunen, um im Verstecke Wehrlose zu morden; nach Unglücklichen spähen seine Augen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Er lauert im Versteck, dem Löwen gleich im Dickicht; er lauert, einen Armen zu erhaschen. Er zieht sein Netz zusanunen, hascht den Armen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Der krümmt und windet sich; doch schließlich fällt der Unglückselige in seine Klauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, '\"Gott denkt nicht dran\", spricht er bei sich. \"Er hat sein Angesicht verhüllt und sieht es nicht in Ewigkeit.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Auf, Herr! Den Arm erhebe, Gott! Vergiß doch nicht der Elenden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Was höhnt der Frevler Gott und denkt bei sich: \"Du ahndest nichts\"? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du hast\'s gesehn, Du schaust ja hin auf Leid und Jammer. In Deine Hände sich ergebend, auf Dich verläßt sich, wer in Not. Verwaisten bist Du ja ein Helfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zerbrich des Frevlers Arm; zerschmettere ihn! Wenn er nach seinem Frevel greift, dann fasse er ihn nimmermehr! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Der Herr sei König immer und auf ewig! Aus seinem Lande mögen fort die Heiden schwinden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Den Wunsch der Elenden erhöre, Herr, und ihres Herzens Sorgen neige hin Dein Ohr,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'und schaff den Waisen und Bedrängten Recht, daß sie nie mehr ein Mensch im Lande schrecke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Auf den Siegesspender, von David. - Ich berge mich beim Herrn. Was sagt ihr da zu mir: \"Entfliehe wie ein Vöglein in die Berge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Die Frevler spannen schon den Bogen und legen auf die Sehne ihren Pfeil, um unsichtbar auf Menschen ohne Schuld ihn abzuschießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Vernichtet werden ja die Wohnstätten. Was kann der Fromme da noch tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'In seinem heiligen Palaste ist der Herr, sein Thron im Himmel. Jedoch sein Auge schaut herab; sein Blick durchforscht die Menschenkinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Gefallen hat der Herr am Frommen; den Frevler und den Mann, der Unrecht liebt, haßt seine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Hernieder auf die Frevler lasse er des Feuers Glut und Schwefel regnen, und ihres Bechers Gabe sei der Hauch der Glut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Gerecht ist ja der Herr; er liebt Gerechtigkeit; sein Antlitz schauen nur die Redlichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Auf den Siegesspender, ein Gesang, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Zu Hilfe, Herr! Die Frommen sind dahin; die treuen Seelen sind verschwunden aus der Menschen Mitte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Mit seinem Nächsten redet jeder falsch und doppelsinnig reden sie in heuchlerischer Sprache. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Der Herr vertilge all die glatten Lippen und jede Zunge, die vermessen spricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '\"Durch unsere Zunge sind wir stark! Wenn unser Mund uns Beistand ist, wer meistert uns?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '\"Ob Elender Bedrückung, ob der Jammerklage Armer ich mich erhebe\", spricht der Herr, \"Heil bring ich dem, der es begehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Lautere Worte sind des Herren Worte, ein Silber, gut geläutert, von der Erde siebenfach gereinigt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Du, Herr: mögst Du sie halten und ewig uns vor dem Gelichter schützen! Die Frevler sollen betteln gehen, der Menschenkinder niedrigste erhöhet werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Auf den Siegesspender, ein Lied von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Wie lange willst Du mich vergessen, Herr, wie lange noch Dein Antlitz mir verhüllen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Wie lange soll ich meinen Geist mit Sinnen, mein Herz mit Sorgen täglich quälen? Wie lange noch mein Feind obsiegen über mich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Schau her, erhöre mich, Du Herr, mein Gott! Erleuchte meine Augen, daß ich des Todes nicht entschlafe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'daß nicht mein Feind sich rühme: \"Den hab ich bezwungen\", nicht meine Gegner jubeln, daß ich wanke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Ich baue fest auf Deine Huld. Mein Herz frohlocke über Deine Hilfe! - Ich will dem Herrn lobsingen, wenn er mir Gutes unverdient getan. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Auf den Siegesspender, von David. - In seinem Herzen spricht der Tor: \"Kein Gott ist da.\" Verkehrt, verrucht sind sie in ihrem Treiben, und keiner ist, der Gutes täte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Vom Himmel her hat sich der Herr geneigt, hernieder auf die Menschenkinder sieht er, ob jemand der Vernunft gehorcht und Gott aufsucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Doch alle sind im Frevelwahn verderbt, und keiner ist, der Gutes täte, nicht einer. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Erfuhren\'s nicht die Übeltäter alle, die meines Volkes Speisen neulich aufgezehrt, und die den Herrn gelassen außer acht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Ein Schrecken hatte auf der Stelle sie gepackt; denn Gott war beim Geschlecht der Frommen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Ihr werdet Ehrfurcht haben vor der Elenden Gemeinde; denn ihre Zuflucht ist der Herr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Von Sion komme Heil für Israel! Ach, wendete der Herr doch seinem Volke das Geschick! Dann würde Jakob fröhlich sein und Israel frohlocken. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Ein Lied, von David. - Wer darf in Deinem Zelte wohnen, Herr? Wer darf auf Deinem heiligen Berge weilen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Nur wer unsträflich wandelt, tut, was recht ist, von Herzen Wahrheit redet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'mit seiner Zunge nicht verleumdet, nichts Böses seinem Nächsten tut, nicht Schmach ob der Verwandten auf sich nimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'In dessen Blick ein hoffnungslos Verlorener verachtet ist, der Achtung hat vor denen, die den Herrn fürchten, zu seinem Schaden schwört und doch nicht ändert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'wer nicht sein Geld auf Zinsen leiht und gegen Unschuld nicht Bestechung nimmt, wer ohne Schwanken also handelt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ein Weihegesang, von David. - Beacht mich, Herr, wie ich bei Dir mich berge! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Ich spreche zu dem Herrn: \"Du Herr! Du bist mein Glück; nichts geht mir über Dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Die Heiligtümer, die im Land, die wundervollen, sind meine ganze Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Die mehren ihre Schmerzen, die einem anderen zueilen. Ich nehme nimmer teil an ihren Blutspenden und bringe nicht auf meine Lippen ihre Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Der Herr ist ja mein Anteil und mein Becher. - Du wirfst mein Los. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Die Lose sind für mich aufs Lieblichste gefallen; der Erbanteil gefällt mir über alle Maßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Den Herren preise ich, der mich berät, und auch die Nächte, da mich mein Gewissen mahnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ich stelle stets vor mich den Herrn; ich wanke nicht, wenn er zu meiner Rechten steht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Drob freue sich mein Herz und juble mein Gemüt! Und sicher ruht mein Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Du läßt nicht meine Seele in der Unterwelt, und Deinen Frommen läßt Du nicht Verwesung spüren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du tust mir kund des Lebens Pfad zur Fülle jener Freuden, die bei Dir nur sind, zu ewigen Wonnen, die in Deiner Rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ein Gebet, von David. - Gerechte Sache höre, Herr! Mein Flehen merk! Vernimm mein Beten mit den Lippen sonder Trug!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Nur Recht ergeht von Deinem Angesicht; untrüglich schauen Deine Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Wenn Du das Herz mir prüftest, in der Nacht es überraschtest und gründlich mich durchforschtest, fändst Du nicht, daß ich gedacht, was meinen Mund nicht überschreiten durfte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Und bei den Löhnen für die Leute gab ich acht nach Deines Mundes Worten auf den Lebensunterhalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Und meine Schritte hielten fest an Deinen Gleisen nicht wankten meine Tritte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'So rufe ich zu Dir, daß Du mich, Gott, erhörest! Neige Dein Ohr zu mir! Auf meine Rede höre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Erzeige Deine Wundergüte, Retter derer, die vor ihren Widersachern bei Deiner Rechten Zuflucht suchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Dem Augensterne gleich behüte mich! Verbirg mich in dem Schatten Deiner Flügel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'vor Frevlern, die mich überfallen, vor meinen Feinden, die mich voller Gier bedrängen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Fühllos verschließen sie ihr Herz; im Übermute spricht ihr Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Sie stürzen sich auf mich, umringen mich; zu Boden senken sie die Augen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Er gleicht dem Löwen, der auf Beute lauert, dem Jungleu im Verstecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Auf, Herr! Tritt ihm entgegen! Wirf ihn nieder! Errette mich vor Bösewichten durch Dein Schwert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'vor Leuten, Herr, durch Deine Hand, vor Leuten, deren Teil im Leben nur die Welt, ja, durch Dein Schwert vor solchen, die ein Schlemmerleben führen, und die samt ihren Kindern voll gesättigt sind, und die, was übrigbleibt, den Enkeln hinterlassen können!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ich aber schaue durch Gerechtigkeit Dein Angesicht und labe mich an Deinem Anblick voll Begier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Auf den Siegesspender, von des Herrn Knecht, von David, der dem Herrn zu Ehren dieses Lied gedichtet, als ihn der Herr aus der Gewalt aller seiner Feinde und besonders Sauls errettet hatte. Er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, '\"Ich liebe, Herr, Dich herzlich, meine Stärke.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Der Herr ist mir ein Fels und eine Rettungsburg; mein Gott, mein Hort, wo ich mich berge, mein Schild, mein sieghaft Horn und meine Feste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, '\"Gepriesen sei der Herr!\" darf ich nur rufen und bin von meinen Feinden schon erlöst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Schon hatten Todesfluten mich umgeben; mich schreckten des Verderbens Ströme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Der Hölle Stricke hatten mich umschlungen; des Todes Schlingen überraschten mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Da rief ich in der Not zum Herrn und schrie zu meinem Gott um Hilfe. Er hört in seinem Tempel meine Stimme, und mein Geschrei dringt ihm zu Ohren. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Die Erde ward erschüttert und sie bebte; der Berge Festen zitterten; sie wankten. Denn er war ergrimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Aufquoll\' aus seiner Nase Rauch; aus seinem Munde sprühte Feuer, und eine Glut ward von ihm ausgesprüht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Den Himmel neigte er und fuhr hernieder, ein tiefes Dunkel unter seinen Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Er fuhr auf einem Cherub, flog einher, auf Windesflügeln schwebend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Zur Hülle nahm er Dunkel rings um sich und Wasserflut und dicht Gewölke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Am Glanze seiner Nähe haben seine Wolken entzündet Hagel, Feuerströme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Der Herr im Himmel donnerte; der Höchste ließ die Stimme dröhnen; da gab es Hagelschauer, Feuergluten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Und seine Pfeile schoß er ab nach allen Seiten und warf die Blitze hin in regelloser Wahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Und Wasserströme zeigten sich; der Erde Gründe wurden bloßgelegt vor Deinem Drohen, Herr, vor Deinem Zornesschnauben. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Mich aber griff er aus der Höhe, faßte mich, und zog mich aus den mächtigen Gewässern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'entriß mich meinen argen Feinden und meinen überlegenen Hassern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'die mich an meinem Unglückstage überfielen. So wurde mir der Herr zur Stütze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Er führte mich ins Freie hin, befreite mich, weil er an mir Gefallen fand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'vergalt mir so nach meiner Rechtlichkeit und lohnte mir nach meiner Hände Reinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Denn immer habe ich des Herren Wege eingehalten und nimmer gegen meinen Gott gefrevelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'behielt ich doch vor Augen alle seine Rechte, und seine Satzungen ließ ich nie aus dem Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Ich hatte mich ganz ungeteilt ergeben und suchte mich vor meiner Lieblingssünde zu bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Darum vergalt der Herr mir auch nach meiner Rechtlichkeit, nach der ihm wohlbekannten Reinheit meiner Hände. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Du bist dem Frommen hold, dem Treugesinnten treu gesinnt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'verfährst mit Reinem rein, doch böse mit dem Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Dem armen Volke stehst Du bei, die stolzen Blicke schlägst Du nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Du lässest ja mein Lichtlein leuchten, Du Herr, mein Gott, der meine Finsternis erhellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Mit Dir anrenne ich die Wälle; mit meinem Gotte überspringe ich die Mauern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Truglos ist Gottes Weg; geläutert ist das Wort des Herrn, ein Schild für alle, die zu ihm sich flüchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Denn wer ist Gott, wenn nicht der Herr? Wer sonst ein Hort als unser Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Der Gott, der mich mit Stärke gürtet und meinen Weg gefahrlos macht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'der meine Füße macht wie die der Rehe, mich sicher stellt auf meinen Höhen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'der meine Hände kämpfen lehrt und meine Arme eherne Bogen spannen läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Du reichst mir Deinen Siegesschild, und Deine Rechte stützt mich, und Deine Stärkung macht mich kräftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Und meinen Schritten gibst Du weiten Raum, und meine Knöchel wanken nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Ich setze meinen Feinden nach und greife sie und kehre nicht zurück, bis daß ich sie vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Ich schlage sie, daß sie sich nimmermehr erheben; sie liegen unter meinen Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Du gürtest mich mit Kraft zum Kampfe, und meine Gegner beugst Du unter mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Und meiner Feinde Rücken zeigst Du mir, daß ich vertilge meine Hasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Sie rufen - niemand hilft - zum Herrn, er hört sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Und ich zermalme sie wie Staub vorm Winde, zerstampfe sie gleich Gassenkot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du rettest mich vor Tausenden von Kriegervölkern; zum Haupt von Heiden machst Du mich, mir unbekannte Leute dienen mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Des Auslands Söhne schmeicheln mir; aufs Hörensagen leisten sie mir schon Gehorsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'und andere Fremdlinge verschwinden und sitzen zitternd in Verstecken. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Lebendig ist der Herr und hochgepriesen als mein Hort, steht hoch da als mein hilfereicher Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Gott, der Du mir verhilfst zur Rache und Völker mir zu Füßen legst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'der Du vor meinen Feinden mich errettest, Du machst mich meinen Gegnern fürder unerreichbar und rettest mich vor Wüterichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Dafür lobpreise ich Dich bei den Heiden, Herr, und singe also Deinem Namen: Heilvoller Turm für seinen König, der David, den er salbte, Huld erweist, und seinem Stamme ewiglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Die Himmel rühmen Gottes Ehre: das Sterngewölbe kündet seiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Die Botschaft raunt ein Tag dem andern zu, und eine Nacht tut sie der andern kund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Nicht Reden sind\'s, nicht Worte, die nicht vernehmlich klängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Ihr Schall durchtönt die ganze Erde, und ihre Laute dringen bis zum Rand der Welt. Ein Zelt ist auf ein Jahr dort für den Sonnenball,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'der, einem Bräutigam gleich, aus seiner Kammer tritt und freudig, wie ein Krieger, seine Bahn durchläuft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'der von dem Rand des Himmels seinen Ausgang hat, an seinen Grenzen seinen Umschwung nimmt, vor dessen Strahlen nichts verborgen bleibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Des Herrn Gesetz ist makellos und eine Seelenspeise. Des Herrn Verordnung ist bewährt und macht die Toren weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Des Herrn Befehle sind gerecht, Gemüt und Herz erfreuend. Des Herrn Gebot ist tadellos und spendet Licht den Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Die Furcht des Herrn ist unfehlbar, auf ewig unvergänglich. Die Satzungen des Herrn sind wahr, gerecht befunden allzumal,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'kostbarer noch als Gold, als feinstes Gold in Menge; und süßer noch als Honigseim und Waben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Vorsichtig geht Dein Knecht mit ihnen um, verwendet vielen Fleiß auf ihr Befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Doch wer ist jeden Irrtums sich bewußt? Von unbewußten Schwächen sprich mich los!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Beschütze Deinen Knecht auch vor mutwilligen Verfehlungen! Sie mögen mich nicht überwältigen! Dann bin ich ohne Tadel und bleibe völlig frei von Missetat. Gefallen laß Dir meines Mundes Worte und meines Herzens Sinnen, mein Hort und mein Erlöser, Du mein Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Der Herr erhöre dich noch an dem Tag der Not! Des Gottes Jakobs Name schütze dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Er sende aus dem Heiligtum dir Hilfe und stütze dich von Sion her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Er nehme an all deine Opfergaben und freue sich an deinen Brandopfern! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Er gebe dir, was nur dein Herz begehrt; und lasse alle deine Pläne wohl gelingen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Dann jauchzen wir ob deines Sieges und jubeln laut in unseres Gottes Namen. Der Herr erfülle dir die Wünsche all! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'jetzt weiß ich es: Der Herr hilft dem, den er gesalbt, erhört ihn von dem heiligen Himmel her mit hilfereichen Taten seiner Rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Sind jene noch so stolz auf Wagen und auf Rosse, wir sind es auf den Namen unsres Herrn und Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Sie krümmen sich und stürzen hin; wir aber stehen wieder auf. Herr, hilf dem König und höre uns, sooft wir rufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Ein König freut sich über Deine Macht, und wie frohlockt er über Deine Hilfe, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Erfüllt hast Du ihm seinen Herzenswunsch, ihm nicht versagt, was seine Lippen sich erfleht. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Entgegen kamst Du ihm mit reichem Segen und setztest eine goldene Krone ihm aufs Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Um Leben hat er Dich gebeten; Du hast\'s ihm geschenkt, ein langes Leben, unvergänglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Sein Ruhm wird groß durch Deine Hilfe; Du hüllest ihn in Glanz und Majestät.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Du machst zum Segen ihn für immerdar und labst ihn mit den Wonnen Deines Angesichtes. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Ja, auf den Herrn vertraut der König und zweifelt nimmer an des Höchsten Huld. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Gewachsen allen Deinen Feinden zeigt sich Deine Hand, gewachsen Deine Rechte allen denen, die Dich hassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Zur rechten Zeit, o Herr, machst Du Dein Angesicht zur Feueresse, die sie mit ihrer Glut vernichtet, und Feuer frißt sie auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Du tilgst vom Boden ihre Frucht und aus den Menschenkindern ihren Stamm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Weil sie mit Bösem Dir gedroht und Pläne sich ersonnen, wie sie es nimmer durften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Denn grausam wirfst Du diese hin und zielst mit Deinem Bogen auf ihr Angesicht. Erhebe, Herr, Dich wiederum in Deiner Kraft! Wir möchten Deinen Sieg mit Sang und Spielen feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Auf den Siegesspender bei der Morgenröte, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mein Gott, mein Gott, was hast Du mich verlassen, und stehst so ferne meinen Angst- und Klagerufen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mein Gott, am Tag erhebe ich den Ruf, und Du erhörst mich nicht, und also in der Nacht; Stillschweigen ist mir nicht vergönnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Und doch bist Du der Heilige Israels, Du schrecklich Thronender.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Auf Dich vertrauten unsere Väter; sie hofften, und Du halfest ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Sie schrieen auf zu Dir und fanden Rettung, und ihr Vertrauen auf Dich ward nicht getäuscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Ich aber bin ein Wurm, kein Mann, der Leute Spott, verachtet von dem Pöbel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Mich höhnt, wer mich nur sieht, verzieht den Mund und schüttelt mit dem Kopf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '\"Er freut sich an dem Herrn, der rette ihn! Der helfe ihm! Er ist sein Liebling.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Du halfst mir aus der Mutter Schoß; Du bargst mich an der Mutter Brust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Auf Dich bin ich vom Mutterschoß her angewiesen; vom Mutterleibe an bist Du mein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Bleib mir nicht fern! Die Not ist nah, und niemand hilft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Der Farren viele stehen um mich her, und mich umringen Basanstiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Sie sperren gegen mich die Rachen auf, wie Löwen, die vor Mordlust brüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Wie Wasser bin ich hingegossen; all meine Glieder haben sich gelöst. Mein Herz ist mir wie Wachs geworden, in meinem Busen hingeschmolzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Vertrocknet ist wie Lehm mein Schlund; am Gaumen haftet mir die Zunge, und wie mit Todesfarbe überzieht es mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Denn Hunde haben mich umringt, der Frevler Rotte mich umgeben; sie machen Löcher mir an Händen und an Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ich spüre Pein in allen meinen Gliedern; sie schauen zu und weiden sich an mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Sie teilen meine Kleider unter sich und werfen über mein Gewand das Los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Herr, sei nicht fern! Zu Hilfe, meine Stärke; schnell!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Errette vom Verderben meine Seele, aus der Gewalt der Hunde jetzt mein Leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Entreiße mich der Löwen Rachen! Rett aus den Hörnern der Wildochsen mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Dann kündige ich meinen Brüdern Deinen Ruhm und preise Dich in der Gemeinde also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, '\"Die ihr den Herrn fürchtet, preiset ihn! Von Jakobs Stamm ihr alle, ehret ihn! Von Israels Geschlecht ihr alle, fürchtet ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Denn er verachtet und verschmäht es nicht, den Armen zu erhören, verhüllt sein Antlitz nicht vor ihm, und wenn er zu ihm ruft, erhört er ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Dann trag ich meine Dankesschuld in großer Volksgemeinde ab; ich bringe dann gelobte Opfer dar vor denen, die ihn fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Dann sollen satt die Armen werden, den Herrn rühmen, die ihn suchen: \"Auflebe euer Herz für immer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Dann kehren sich zum Herrn die Erdenenden alle, und alle Heidenstämme beten vor Dir dann an, bedenkend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'daß nur dem Herrn das Königtum gebührt, und daß er auch den Heiden Herrscher ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Nur ihn allein beten auf Erden alle an. Ihm beugt sich, wer zur Grube fährt und dessen Seele nicht mehr lebenskräftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Die Nachwelt derer, die ihm dienen, sie rühmt den Herrn dem kommenden Geschlecht und kündet einem nachgeborenen Volke seine Liebe und was er ihm getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Ein Lied, von David. - Mein Hirte ist der Herr; mir mangelt nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Er lagert mich auf grünen Auen; er leitet mich zu stillen Wassern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'lenkt mein Begehr und leitet mich auf rechten Pfaden zu seines Namens Wohnstatt hin. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Und walle ich im Tal des Todesschattens, ich fürchte keinerlei Gefahr; denn Du begleitest mich. Ein Trost sind mir Dein Stab und Deine Rute, die mir zur Leitung dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du richtest mir ein Mahl vor meinen Neidern zu. Du salbst mein Haupt mit Öl und schenkst mir vollen Becher ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'In meinem Leben folgt mir Glück und Huld, und immer weile ich im Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Von David, ein Lied. - Die Erde ist des Herrn und was sie füllt; sein ist die Welt und alles, was da wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Auf Meere hat er sie gegründet, auf Ströme sie gestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Wer darf den Berg des Herrn besteigen? Wer seinen heiligen Ort betreten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Wer reine Hände hat und lautern Herzens ist, wer nie nach Falschheit giert, dem Wahn nicht huldigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'wer Segen von dem Herrn empfängt und Wohlergehn von seines Heiles Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Also gesinnt ist das Geschlecht, das sein begehrt, und das dein Antlitz, Jakob, sucht. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Hebt eure Häupter hoch, ihr Tore. Ihr alten Pforten recket euch! Einzieht der Völkermenge König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Wer ist der Völkermenge König? Der Herr ist es, der Starke und Gewaltige, der Herr, der Kriegsheld. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Hebt eure Häupter hoch, ihr Tore. Erhebet sie, ihr alten Pforten! Einzieht der Völkermenge König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Wer ist der Völkermenge König? Der Herr der Heeresscharen. Er ist der Völkermenge König. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Von David. - Nach Dir verlangt mich, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mein Gott, auf Dich nur hoffe ich. Laß nimmer mich zuschanden werden! Laß meine Feinde über mich nicht jubeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Nicht einer, der auf Dich vertraut, wird je zuschanden. Doch leer gehn aus die Abgefallenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Belehre, Herr, mich über Deine Wege! Gewöhne mich an Deine Pfade!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'In Deiner Treue leite mich! Gewöhne mich daran! Denn Du bist meines Heiles Gott; stets hoffe ich auf Dich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Gedenke Deiner Liebe, Herr, und Güte! Sie sind von Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Gedenk nicht meiner Jugendsünden, meiner Missetaten nicht! Gedenk mir dessen nur, was Deiner Gnade würdig ist, um Deiner Güte willen, Herr! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Der Herr ist gütig und wahrhaftig; drum zeigt er Irrenden die rechte Bahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Bedrückte leitet er, wie\'s richtig ist, gewöhnt an seinen Weg die Dulder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Des Herrn Wege all\' sind Lieb\' und Treue für die, die seinen Bund und seine Lehren halten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Um Deines Namens willen, Herr, vergib mir meine Schuld, so groß ist sie! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Ist irgendwo ein Mann in Furcht des Herrn, so zeigt er ihm den Weg, den jener wählen soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Ihm ist das Glück auch hold; sein Stamm ererbt das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Des Herrn Geheimnis eignet denen, die ihn fürchten; in seinen Bund weiht er sie ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mein Auge schaut stets auf den Herrn; denn meine Füße kann er vor dem Netz bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Schau her auf mich! Sei gnädig mir! Verlassen bin ich, elend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Erweitere mein beklemmtes Herz! Aus meinen Nöten rette mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Schau meine Pein, mein Elend an! Vergib mir alle meine Sünden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Betrachte meine Feinde, welche Menge, den Haß, wie furchtbar sie mich hassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Mein Leben schirme, rette mich, damit ich nicht zuschanden werde! Ich harre Dein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Mir bleibe Unschuld! Mir bleibe Redlichkeit! Ich harre Dein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Erlöse Israel aus allen seinen Nöten, Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Von David. - Urteile, Herr, ob ich in Unschuld nicht gewandelt und sonder Wanken auf den Herrn vertraut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prüf mich, erprob mich, Herr! Rein ist mein Herz und mein Gewissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Denn Deine Güte schwebte mir vor Augen, und Dir getreu bin ich gewandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Bei schlechten Männern bin ich nie gesessen; hab nie mit Lichtscheuen Umgang gepflogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Ich haßte die Zusammenkunft der Bösen, und bei den Frevlern saß ich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'In Unschuld wasche ich die Hände und schreite gern um Deinen Altar, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Ich lausche Deines Lobes Stimme und künde alle Deine Wunder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Ich liebe, Herr, den Aufenthalt in Deinem Hause, das Weilen an der Stätte Deiner Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Raff meine Seele nicht mit Sündern hin, mein Leben nicht mit Mordgesellen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'in deren Händen Schandtat käuflich ist, und deren Rechte voll ist von Bestechung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ich aber wandle hin in meiner Unschuld. Erlöse mich! Und sei mir gnädig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Betritt mein Fuß dann ebnen Weg, lobpreise ich Dich, Herr, mit Chören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Von David. - Der Herr mein Licht, mein Heil! Wen soll ich fürchten? Der Herr mein Lebenshort! Wen muß ich scheuen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Wenn Übeltäter sich mir nahen, nach meinem Fleische gierig, sie, meine Gegner, meine Feinde, so straucheln sie und stürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Und lagert sich ein Heer um mich mein Herz bleibt unerschrocken. Erhebt sich gegen mich ein Kampf, auch dann bin ich getrost. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Um eines bitte ich den Herrn, Nur dies erflehe ich für mich: Im Haus des Herrn zu weilen die Tage alle, die ich lebe, des Herrn Lieblichkeit zu kosten und sie in seinem Tempel zu betrachten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Er birgt in seiner Hütte mich am unglücksvollen Tage und schirmt mich in dem Schutze seines Zeltes und sichert mich auf hohen Felsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Und hebt sich dann mein Haupt empor hoch über meine Feinde ringsumher, dann opf\'re ich in seinem Zelt mit lautem Jubelschalle und weihe Sang und Spiel dem Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'So hör doch, Herr! Ich rufe laut.- Sei gnädig mir! Erhöre mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Dein, spricht mein Herz, ist ja das Wort: \"Ihr sollt mein Antlitz suchen!\" So suche ich Dein Antlitz, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Verbirg Dein Antlitz nicht vor mir! Weis nicht im Zorne Deinen Diener ab! Sei Beistand mir! Verstoß mich nimmer! Verlaß mich nicht, mein hilfereicher Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Es heißt: \"Verläßt mich selbst der Vater und die Mutter, nimmt mich der Herr zu sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'So zeige Deinen Weg mir, Herr, und leite mich auf ebner Bahn um meiner Feinde willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Nicht gib mich meiner Feinde Willkür preis! Denn gegen mich stehn falsche Zeugen auf und solche, die Gewalttat schnauben. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Als ob ich nimmer die Gewißheit hätte, daß ich des Herrn Güte noch erfahre im Lande der Lebendigen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Hoff auf den Herrn! Sei nur getrost und guten Muts und hoffe auf den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Von David. - Ich rufe, Herr, zu Dir. Sei doch nicht taub vor mir, mein Hort! Wenn Du vor mir verstummst, dann gleiche ich ins Grab Gesunkenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Mein lautes Flehen hör, wenn ich, zu Dir um Hilfe rufend, zu Deinem Allerheiligsten die Hände breite!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Nicht lange laß mich sein bei Frevlern und nicht bei Übeltätern! Sie reden freundlich mit dem Nächsten; doch sinnen sie im Herzen Böses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Vergilt Du ihnen ihrer Tat gemäß, nach ihrer bösen Art! Nach ihrer Hände Werk belohne sie! Behandle sie, wie sie\'s verdienen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Sie achten nimmer auf des Herren Taten und nicht auf seiner Hände Werk; sie reißen sie herab und bauen sie nicht auf, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Gepriesen sei der Herr, wenn er mein lautes Flehen hört!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Der Herr ist mir ein Schutz und Schild; auf ihn vertraut mein Herz. Mir wird geholfen; mein Herz frohlockt. Ich danke ihm mit meinem Liede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Der Herr ist seines Volkes Schutzgott, ein Zufluchtsort, wo sein Gesalbter Hilfe findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Zuhilfe Deinem Volk! Den ewig Deinen spende Segen! Und weide sie und sorge ewiglich für sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Ein Lied, von David. - Ihr Gottessöhne! Bringet für den Herrn herbei, bringt Kostbarkeiten, Schätze für den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Bringt für den Herrn die Schätze, seines Namens würdig! Werft vor den Herrn euch hin mit Schmuck fürs Heiligtuni! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Des Herrn Stimme dröhnet über den Gewässern. Der Gott der Herrlichkeit ließ donnern; der Herr war über mächtigen Gewässern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Des Herrn Stimme schallt in Kraft; des Herrn Stimme schallt mit Majestät.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Des Herrn Stimme splittert Zedern. Der Herr zerschmettert Zedern Libanons.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Er ließ den Libanon gleich einem Kalbe hüpfen, den Sirjon wie ein Büffeljunges.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Des Herrn Stimme spaltet Feuerflammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Des Herrn Stimme macht die Wüste beben. Einst ließ der Herr die Wüste Kades zittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Des Herrn Stimme macht, daß Rehe werfen, und daß entblößt die Wälder werden. Mit ihrer ganzen Kraft bestellt er Schätze in sein Heiligtum. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Und überm Sintflutregen hatte einst der Herr gethront. Der Herr war König schon in alten Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Der Herr verleihe Schätze seinem Volk! Mit Frieden segne doch der Herr sein Volk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein Lied. Ein Gesang zur Tempelweihe. Von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Erheben will ich Dich, wenn Du mich aus der Tiefe zögest, Herr, und wenn Du meine Feinde über mich nicht jubeln ließest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Ich rufe, Herr, mein Gott, zu Dir, Du mögest Heil mir schenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Der Unterwelt entziehe mich! Mein Leben rette, Herr, aus denen, die zur Grube fahren. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Lobsingt dem Herrn, ihr seine Frommen! Lobpreiset seinen heiligen Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Sein Zorn währt einen Augenblick, ein Leben seine Huld. Und kehrt am Abend Weinen ein, am Morgen ist schon Jubel da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ich sage ganz getrost und zweifle nie daran:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, '\"Du, Herr, in Deiner Huld, Du stehst mir da als fester Berg; verhüllest Du jedoch Dein Angesicht, dann packt mich Grauen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Ich rufe, Herr, zu Dir; zu meinem Herren flehe ich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Was nützt Dir mein Verstummen, wenn ich hinab zur Grube stiege? Kann Dich ein Stäubchen preisen und Deine Treue künden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Herr! Höre! Sei mir gnädig! Sei mir ein Helfer, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Verwandle Du in Reigen meine Trauer! Befrei mich von dem Bußgewand! Umgürte mich mit Freude! Dann singt ein lebend Wesen Dir und wird nie still. Dann preise ich Dich, Herr, mein Gott, auf immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Geborgen hab ich mich bei Dir, o Herr. Nun laß mich nicht zuschanden werden! In Deiner Güte rette mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Neig mir Dein Ohr! Und hilf nur eilends! Sei Felsenburg und Feste mir zu meiner Rettung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Mein Fels und meine Burg bist Du. Leit mich, führ mich um Deines Namens willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Bewahre mich vor diesem Netz, das sie mir heimlich legen! Du bist ja meine Schutzwehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'In Deine Hände, Herr, befehl ich meinen Geist; Du rettest mich, Du treuer Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Ich hasse die, die sich an eitle Götzen halten; denn ich vertraue auf den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Ich möchte jubeln, jauchzen über Deine Huld, wenn Du mein Elend schautest und merktest meiner Seele Ängste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Der Feindeshand gib mich nicht preis! Stell mich auf freien Fuß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Herr! Sei mir gnädig! Sieh, mir ist so bange. Vor Kummer krankt mein Auge, mein Leib und meine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Denn unter Jammer welkt mein Leben hin und meine Jahre unter Seufzen. Durch meine Schuld ist mir die Kraft gelähmt und die Gesundheit mir zerstört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Ich bin all meiner Gegner Spott geworden. Und erst bei meiner Nachbarschaft! Ein Schrecken meinen besten Freunden! Mich flieht, wer draußen mich erblickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Vergessen bin ich völlig, wie ein Toter; wie ein verloren Ding bin ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ich höre das Gerede vieler: \"Seht, nur Schrecken um ihn her\", weil alle sich verschwören wider mich und mich zu morden planen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Ich aber hoffe, Herr, auf Dich; \"Du bist mein Gott\", so spreche ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'In Deinen Händen liegt mein Schicksal. Errette mich aus meiner Feinde und Verfolger Hand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Laß über Deinen Knecht Dein Antlitz leuchten! Errette mich durch Deine Gnade!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Herr, laß mich nicht zuschanden werden, da ich zu Dir rufe! Zuschanden mögen Frevler werden und in die Hölle stumm versinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Daß sie verstummen, diese Lügenmäuler, die dem Gerechten Grauenvolles künden, höhnisch und stolz! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Wie reich ist doch Dein Gut, das denen Du bewahrest, die Dich fürchten, das denen Du bereitet, die auf Dich hoffen, und das für andere Menschen unerreichbar ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du birgst im Schutze Deiner Flügel sie vor Menschenhändeln und wahrst in einem Zelte sie vor Zungenhader.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Gepriesen sei der Herr, wenn er mir seine Wundergüte noch einmal in der Not beweist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ich denke zwar in meiner Angst: \"Aus Deinen Augen bin ich ganz verstoßen\"; allein Du hörst mein lautes Flehen, erhebe ich zu Dir den Hilferuf. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'So liebt den Herrn, ihr seine Frommen alle! Die treuen Seelen schützt der Herr. Doch dem, der Hochmut übt, vergilt er ganz genau nach Maß. So seid getrost und unerschrocken alle, die auf den Herrn vertrauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Von David; ein Lehrgedicht. - Dem Menschen Heil, dem seine Missetat vergeben ist und dessen Sünde zugedeckt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Dem Menschen Heil, dem seine Schuld der Herr nicht länger anrechnet, in dessen Geist sich keine Täuschung findet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Solange ich\'s verschwieg, verfiel mein Leib durch tägliches Gestöhn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Denn Deine Hand lag schwer auf mir bei Tag und Nacht. Gewandelt hat sich meine Lebenskraft gleichsam in dürre Sommerfrucht. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Doch als ich Dir die Schuld bekannte und meine Sünde länger nicht verhehlte, und als ich sprach: \"Dem Herrn gesteh ich meine Missetaten\", da nahmst Du meine Sündenschuld hinweg. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Drum sollte jeder Fromme zu Dir flehen, sobald er etwas findet. Anstürmen mögen starke Wasserfluten, sie kommen nicht zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du bist mir Schutz, bewahrst mich vor dem Feinde, stellst Dich zur Seite mir mit Rettungsrufen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '\"Ich will dich unterweisen, will den Weg dir zeigen, auf dem du gehen sollst; ich möchte, Liebling, dich beraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Sei nicht dem unverständigen Roß und Maultier gleich! Ihr Ungestüm muß man mit Zaum und Zügel hemmen. Zieh nimmer dich zurück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Den Frevler treffen viele Plagen. Wer aber auf den Herrn vertraut, dem ist er überall mit seiner Huld zur Seite. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Ihr Frommen! Freuet euch am Herrn, frohlockt! Ihr frommen Seelen alle, jauchzet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Ihr Frommen, jauchzt dem Herrn! Den Redlichen ziemt Lobgesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Mit Zitherklängen dankt dem Herrn! Ihm spielt auf Harfen mit zehn Saiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Ihm singt ein nie gehörtes Lied! Und schlaget kräftig in die Saiten, daß es schallt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Wahrhaftig ist das Wort des Herrn, und Treue ist sein ganzes Tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Er liebt Gerechtigkeit und Recht; des Herrn Güte ist die Erde voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Die Himmel sind geworden durch das Wort des Herrn, durch seines Mundes Hauch ihr ganzes Heer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Er sammelt wie in einen Schlauch ein Meer von Wasser und legt in Speicher Ozeane.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'So fürchte alle Welt sich vor dem Herrn! Vor ihm erschauere jeder Erdbewohner!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Denn so er spricht, geschieht\'s, gebietet er\'s, so bleibt es aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Zunichte macht der Herr der Heiden Plan; der Völker Absichten vereitelt er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Der Plan des Herrn ist unveränderlich, und seines Herzens Pläne gelten für und für.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Heil sei dem Heidenvolke, dessen Gott der Herr, der Nation, die er zur ewig Seinen sich erkoren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Vom Himmel schaut der Herr herab und blickt auf alle Menschenkinder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Von seiner Wohnstatt schaut er nieder auf alle Erdbewohner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ihm, der geschaffen ihre Herzen allzumal, dem ist bekannt ihr ganzes Tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Kein König siegt durch Heeresmacht; den Riesen rettet nicht die Fülle seiner Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Betrogen, wer vom Roß den Sieg erwartet; nicht Rettung bringt es ihm trotz großer Stärke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Auf denen, so ihn fürchten, ruht des Herrn Auge, auf denen, die von seiner Güte hoffen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'daß er vor Pest ihr Leben rette und sie in Hungersnot erhalte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Dem Herrn gilt unserer Seele Harren; uns ist er Schutz und Schild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'So froh wird unser Herz durch ihn; denn wir vertrauen seinem heiligen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Herr! Deine Gnade walte über uns, so wie wir sie von Dir erhoffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Von David, als er seinen Verstand vor Abimelech verstellte und dieser ihn verjagte, worauf er sich entfernte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Lobpreisen will ich jederzeit den Herrn. Sein Lob sei stets in meinem Munde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Es rühme meine Seele sich im Herrn! Die Armen sollen\'s hören und sich freuen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Verherrlichet den Herrn mit mir! Laßt uns gemeinsam seinen Namen preisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Den Herrn such ich auf; er hört auf mich, befreit mich aus den Ängsten all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Mich schauet an und strahlt vor Freude! Nie röte mehr sich euer Angesicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Hier ist ein armer Mensch, der einst gerufen. Der Herr vernahm\'s und half ihm aus den Nöten all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Des Herrn Engel lagert sich um jene, die ihn fürchten, er rettet sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'So kostet und erfahrt, wie gut der Herr! Wie wohl dem Mann, der ihm vertraut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Vorm Herrn habt Furcht, ihr, seine Heiligen! Denn die ihn fürchten, leiden keinen Mangel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Die Gottesleugner hungern darbend; doch denen, die den Herrn aufsuchen, mangelt nicht, was ihnen frommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Her, Kinder, hört mir zu! Ich lehre euch die Furcht des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Wer ist der Mann, der Lust zum Leben hat, der zum Genuß des Glückes leben möchte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Behüte vor dem Bösen deine Zunge, vor trügerischer Rede deine Lippen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Vom Bösen laß und tu das Gute! den Frieden such! Ihm jage nach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Des Herrn Augen achten auf die Frommen und seine Ohren auf ihr Flehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Des Herrn Antlitz wendet sich den Übeltätern zu und tilgt ihr Angedenken von der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Die Frommen schreien, und schon hört\'s der Herr und rettet sie aus aller Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Der Herr ist nahe den zerknirschten Herzen; zerschlagenen Gemütern hilft er auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'In viel Gefahren ist der Fromme; aus ihnen allen rettet ihn der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Er hütet jedes seiner Glieder; versehrt wird auch nicht eins davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Den Frevler rafft ein Unfall weg; des Frommen Hasser müssen es bereuen. Der Herr erlöst die Seele seiner Diener; wer auf ihn baut, bereut es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Von David. - Bekämpfe, Herr, die mich bekämpfen! Befehde Du, die mich befehden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Nimm Schild und Wehr! Steh auf zu meiner Hilfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Schwing Beil und Lanze gegen die, so mich verfolgen, und sprich zu mir: \"Ich bin dein Heil!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Daß meine Todfeinde voll Scham erröten, mit Scham zurückgetrieben werden, die auf mein Unheil sinnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Wie Spreu vorm Winde seien sie! Des Herrn Engel scheuche sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ihr Weg sei finster, schlüpfrig, und sie verfolge drauf des Herrn Engel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Sie legen ohne Grund mir insgeheim ihr Unglücksnetz; sie graben für mich grundlos eine Grube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, '\"Ihn überfalle ahnungslos ein Taumel! Das Netz, das heimlich man für ihn gelegt, verstricke ihn! Im Taumel falle er hinein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Dann jauchzt mein Herz des Herrn wegen und freut sich seiner Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Dann spricht ein jeder Zoll an mir: \"Wer rettet so wie Du den Schwachen vor dem Starken, Herr, den Elenden und Armen vor dem Räuber?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Auftreten falsche Zeugen und zeihn mich dessen, was mir nicht bewußt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Vergelten Arges mir für Gutes; sie warten auf mein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Und ich? In ihrer Krankheit trage ich ein Bußgewand, mit Fasten mich abhärmend, und bete mit gesenktem Haupte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Als wär\'s mein Freund, mein Bruder, so geh ich einher; als trauerte ich um die Mutter, so bin ich gebeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Und diese freuen sich bei meinem Sturze, rotten sich zusammen. Sie rotten sich zusammen wider mich gar hinterlistig, daß ich\'s nicht merke; unaufhörlich lästern sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Des Hohnes, Spottes und der argen Tücke voll, so fletschen sie die Zähne gegen mich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Wie lange, Herr, siehst Du noch zu? Entreiß mein Leben ihren Schrecknissen, mein einziges den jungen Leuen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Dann preis ich Dich vor großer Menge und singe Dir vor vielem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Nicht sollen über mich sich freuen, die unverdient mir feindlich sind, nicht mit den Augen zwinkern, die mich ganz unverschuldet hassen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Sie reden nicht zum Guten von den Kleinen in dem Land; des Truges Worte sinnen sie sich aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Sie sperren gegen mich den Mund weit auf und rufen: \"Ha, ha, ha! So sehen wir es gerne.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Du siehst es, Herr. Schweig nicht dazu! Herr, sei nicht fern von mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Erwache! Wach zu meinem Rechte auf, mein Gott und Herr, für meine Sache!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Verschaffe, Herr, mein Gott, mir Recht nach Deiner Rechtlichkeit! Nicht lustig machen dürfen sie sich über mich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'nicht denken: \"Ha! So war\'s erwünscht\", nicht sagen: \"Wir vernichten ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Sich schämen und erröten müssen alle, die sich an meinem Unglück freuen, in Schande und in Scham sich hüllen, die großtun gegen mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Frohlocken, jauchzen sollen aber die, die Heil mir wünschen, und immerdar soll sprechen: \"Hochgepriesen sei der Herr!\" wer Deinem Knecht gewogen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Auch meine Zunge kündet alsdann Deine Güte und Deinen Ruhm den ganzen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Auf den Siegesspender, von des Herrn Knecht, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Mein Herz weiß einen Ausspruch über Schlechtigkeit von Frevlern: \"Für Nichts gilt Gottesfurcht in seinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Denn er gefällt sich selbst, dieweil ihm hassenswerte Missetat gelingt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Sein Mund spricht Lug und Trug; auf Tugend und Vernunft verzichtet er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Auf Bosheit sinnt er noch auf seinem Lager, verweilt auf üblem Weg und scheut sich nicht vor Übeltat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Herr, Deine Güte reicht bis in den Himmel, bis in die Wolken Deine Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Den höchsten Bergen gleich ist Deine Milde und die Gerechtigkeit bei Dir ist gleich der tiefsten Tiefe. Du hilfst selbst den vertierten Menschen, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Wie köstlich, Gott, ist Deine Gnade! In Deiner Flügel Schatten dürfen sich die Menschen bergen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sie dürfen sich erlaben an der reichen Fülle Deines Hauses; und aus dem Borne Deiner Wonnen tränkst Du sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'bei Dir ist ja des Lebens Urquell, in Deinem Licht erblicken wir das Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Laß Deine Liebe immer strömen über die, so Dich bekennen, und über die geraden Herzen Deine Milde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Nicht komme an mich her des Übermutes Fuß! Und nicht vertreibe mich des Frevlers Hand! Schon fallen sie, die Übeltäter; sie stürzen, kommen nimmer auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Von David. - Ereifere dich nicht der Bösewichte wegen! Beneide nicht die Übeltäter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Sie welken schnell wie Gras, verdorren wie das grüne Kraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Vertrau dem Herrn! Tu Gutes! Verbleib im Land, dich redlich nährend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Wie ein verwöhntes Kind komm zu dem Herrn! Er gibt dir, was dein Herz sich wünscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befiehl du deinen Weg dein Herrn! Auf ihn vertrau! Er wird\'s schon machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Er bringt ans Licht, daß du gerecht, und an den Tag, daß du im Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Und schweig zum Herrn und harre sein! Ereifere über den dich nicht, der sich Erfolg erzwingt, nicht über einen Mann, der Schwindel treibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Gib auf den Ärger! So ereifere dich nicht, daß selbst du Böses tätest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Denn ausgerottet werden Übeltäter; die auf den Herrn vertrauen, bleiben im Besitz des Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Noch kurze Zeit! Dann ist der Bösewicht dahin! Du schaust nach seiner Stätte. Er ist nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Die Dulder bleiben im Besitz des Landes an reichem Glücke sich erlabend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Dem Frommen plant zuleid der Frevler Arges und fletscht die Zähne wider ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Der Herr lacht seiner; schon sieht er seinen Tag sich nahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Die Frevler zücken zwar ihr Schwert und spannen ihren Bogen, um Elende und Arme zu erlegen und hinzuwürgen, die geraden Wandels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Allein ihr Schwert dringt in ihr eigen Herz, und ihre Bogen splittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Das Wenige bekommt dem Frommen besser, als Frevlern großer Reichtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Zerbrochen werden ja der Frevler Arme; die Frommen aber stützt der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Der Herr sorgt für die Tage lauterer Menschen, und ihr Besitztum dauert immerfort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Sie werden nicht in böser Zeit zuschanden; sie werden satt in Hungertagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Denn nur die Frevler gehn zugrunde, des Herrn Feinde gleich der Auen Pracht; sie schwinden hin wie Rauch; sie schwinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Der Frevler borgt, kann\'s aber nicht zurückerstatten; freigebig, milde kann der Fromme sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Denn die von ihm Gesegneten verbleiben im Besitz des Landes; doch die von ihm Verfluchten werden ausgerottet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Sind eines Mannes Schritte recht im Hinblick auf den Herrn, dann kümmert dieser sich um seinen Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Und wankt er auch, so stürzt er nicht; ihn stützt der Herr mit seiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Ich war ein Jüngling, ward ein Greis; doch ganz verlassen habe ich den Frommen nie gesehen, noch sein Geschlecht um Nahrung betteln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Stets milde, leiht es allezeit; zum Segen sät es aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Dem Laster gram, der Tugend hold, so bleibst du immerdar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Der Herr liebt ja das Recht; von seinen Frommen läßt er nicht. Sie sind für alle Zeit geschützt; der Frevler Brut wird ausgerottet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Den Frommen wird das Land zu eigen, sie bleiben ewiglich darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Des Frommen Mund spricht Weises; nur Rechtes redet seine Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Im Herzen trägt er seines Gottes Lehre, und seine Schritte schwanken nie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Der Frevler lauert auf dem Frommen, begierig, ihn zu morden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Doch überläßt der Herr ihn nimmer seiner Hand, läßt vor Gericht ihn nicht verdammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Dem Herrn vertrau! Halt dich an seinen Weg! Dann gibt er dir das Land zu eigen; der Frevler Untergang erlebst du noch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Ich habe einen Frevler voller Trotz gesehen, so kahl gemacht wie Gras im Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Man schaute um; er war nicht mehr. Ich suchte ihn; er war nicht mehr zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Merk auf die Lauteren! Schau auf die Redlichen, wie\'s jedem gut am Ende geht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Die Missetäter aber werden all vertilgt; der Frevler Zukunft wird vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Der Frommen Heil dagegen kommt vom Herrn; er ist ihr Schutz zur Zeit der Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Der Herr steht ihnen bei und rettet sie; er schirmt und schützt sie vor dem Bösen; denn sie vertraun auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein Lied; von David, zum Erlernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Bestraf mich nicht in Deinem Zorne, Herr! In Deinem Grimme züchtige mich nicht noch mehr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Denn Deine Pfeile sind gar tief in mich gedrungen, und Deine Hand liegt schwer auf mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'An meinem Fleische ist nichts heil ob Deinem Zorn, nichts unversehrt an meinem Leib ob meiner Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Denn meine Sünden übersteigen mir das Haupt, sind mir zu schwer, wie eine ungeheure Last.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Und eiternd faulen meine Wunden um meiner Torheit willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Ich winde mich und krümme mich so heftig und allzeit gehe ich betrübt einher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'In meinem Innern wühlt der Brand; an meinem Leib ist nichts Gesundes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Ich bin gelähmt, zermalmt und stöhne; mir klopft das Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Vor Dir liegt jeder meiner Wünsche offen, Herr; mein Seufzen ist Dir nicht verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mir pocht das Herz und steht mir still, und meine Kraft, mein Augenlicht versagen mir den Dienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Die Freunde und Gefährten treten zurück vor meiner Plage; fern stehen die Verwandten mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Die auf mein Leben lauern, legen Schlingen, und die mein Unglück suchen, drohen mit Verderben und schmieden täglich Ränke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Und ich? Ich bin wie taub und höre nichts, bin wie ein Stummer, der den Mund nicht öffnet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'bin wie ein Mensch, der nichts versteht und keinen Widerspruch im Munde führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Denn ich vertraue, Herr, auf Dich; Du Herr, mein Gott, wirst Rede stehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Weil ich mir sag, sie dürfen meiner nimmer spotten, und glitte aus mein Fuß, nicht über mich frohlocken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Schon bin ich ja dem Falle nah, stets meiner Schwäche mir bewußt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Denn ich bekenne meine Schuld und gräme mich um meine Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Doch zahlreich sind, die unverschuldet mich befeinden, und viele, die mich grundlos hassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'und die mit Bösem Gutes mir vergelten, mich lästern, daß ich nach dem Guten strebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Verlaß mich nicht, o Herr! Mein Gott, entfern Dich nicht von mir! Zu meinem Schutze schnell herbei! Zu Hilfe, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Auf den Siegesspender, für Zurückgezogene ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Ich denke: Ich hab acht auf meinen Wandel, daß ich nicht sündige mit meiner Zunge. Ich will mit einem Zaume meinen Mund verwahren vor frevler Rede, die sich mir aufdrängt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Ich habe still geschwiegen, nichts von Besserung gesagt. Verbissen wird mein Schmerz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Geglüht hat mir das Herz im Busen, und hab ich dran gedacht, so lobte eine Flamme auf. Ich lasse meine Zunge reden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, '\"Herr! Künde mir mein Ziel, wie ist\'s mit meiner Tage Maß! Ich wüßte gern, woran es bei mir fehlt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Du machst ja spannenlang nur meine Tage, und meine Lebensdauer ist wie nichts vor Dir. Nur für das Nichts ist jeder Mensch geschaffen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Mit Schattenbildern geht der Mensch umher. Sie machen Lärm um eitlen Tand. Man scharrt zusammen und weiß nicht, wer es bekommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Doch ich, was hoffe ich nur, Herr? Mein Hoffen geht auf Dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Erlöse mich von allen meinen Sünden! Setz mich dem Spott der Toren nimmer aus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Ich schweige, tu den Mund nicht auf; denn Du hast es getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Nimm Deine Plage fort von mir! Vom Schlage Deiner Hand vergehe ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Wenn Du zur Buße für die Sünden mit Strafen jemand züchtigest, beschädigst Du sein Teuerstes, als wär\'s ein leeres Vogelnest. Ach, jeder Mensch ist nur ein Hauch. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Erhöre mein Gebet, Herr, meinen Hilferuf! Auf meine Tränen merke! Nimmer schweige! Ein Gast bin ich bei Dir, ein Beisaß so, wie meine Väter all. Sei freundlich doch zu mir, daß ich noch einmal lächle, bevor ich scheide und hier nimmer weile!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Auf den Siegesspender, von David, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Ich hoffe gläubig auf den Herrn; er schenkt mir auch Gehör und hört mein Rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Er wird mich aus der Mördergrube ziehen, aus Kot und Schlamm, und stellen meinen Fuß auf Felsengrund und meine Schritte sichern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Er legt ein neues Lied mir in den Mund ein Lob auf unsern Gott. Das sollen viele hören und sich fürchten und zu dem Herrn Vertrauen fassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, '\"Dem Manne Heil, der sein Vertrauen auf den Herrn gesetzt, sich nicht den Frechen beigesellt, die abgefallen sind zum Truge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Du tust zahlreiche Wunder, Herr, mein Gott, und Deine Pläne, die Du mit uns hast, - Dir ist nichts gleich - wollt ich sie künden, davon redend, zu viele wären es, sie zu erklären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Du wünschest keine Schlacht- noch Speiseopfer; feinhörig machst Du mich. Du heischest keine Brand- noch Sündenopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Drum spreche ich: \"Bereit bin ich zu dem, was mir die Buchrolle verzeichnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Mein Gott! Wie gerne tu ich Deinen Willen und trage Dein Gesetz im Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Verkünden möchte ich das Heil vor zahlreicher Gemeinde; ich täte meinen Lippen keinen Einhalt. Du weißt es, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Im Herzen will ich Deine Liebe nicht begraben, von Deiner Treue, Deinem Heile will ich reden und Deine Huld und Treue nicht verhehlen vor der großen Volksgemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'So wehre, Herr, auch Du nicht Deiner Güte gegen mich! Mich schütze Deine Huld und Treue immerdar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Denn Leiden ohne Zahl umringen mich; mich treffen meiner Sünden Strafen. Ich kann sie nimmer überblicken; mehr als die Haare meines Hauptes sind es ihrer. So steht mir stille der Verstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Herr! Schnell herbei zu meiner Rettung! Zu Hilfe eilends, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Beschämt und schamrot sollen werden alle, die ernstlich mir nach meinem Leben trachten, mit Schmach die Flucht ergreifen, die mir übelwollen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Erstarren sollen auf der Stelle, die mir entgegenrufen: \"Ha!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Doch jubeln sollen über Dich vor Freude alle, die Dich suchen, und allzeit rufen: \"Groß der Herr!\", die Deinen Sieg sich wünschen! Bin ich auch selber arm und elend, der Herr sorgt doch für mich. Du bist mir Rettung und mein Schutz. Mein Gott! Nicht säume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Heil dem, der an den Kranken denkt! Am eignen Unglückstag errettet ihn der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Der Herr behütet ihn und fristet ihm das Leben; auf Erden wird er glücklich sein. Gib seiner Feinde Wut ihn nimmer preis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Auf eigenem Krankenbette stärke ihn der Herr. Verwandle seinen ganzen Leib in völlige Gesundheit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Ich spreche: Herr, o sei mir gnädig! Gib Heilung mir, so sehr ich gegen Dich gesündigt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Nur Böses wünschen meine Feinde mir: Wann stirbt er denn? Wann geht sein Name unter?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Besucht mich einer, spricht er trügerisch; im Herzen sammelt er sich Lügen, und tritt er auf die Straße, dann verbreitet er\'s.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'All meine Hasser raunen wider mich und rechnen auf das Schlimmste, mir zum Schaden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '\"Fest ist ein Höllenwerk ihm angeschmiedet. Wer einmal sich gelegt, kommt nicht mehr auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Sogar mein Busenfreund, auf den ich mich verlassen habe, mein Tischgenosse übertreibt die Folgen mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Du aber, Herr, hilf mir erbarmend auf, daß ich dem Frieden sie gewinne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Ich merke dran, daß Du mich liebst, wenn über mich der Feind nicht jauchzt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'und wenn ich wiederum gesunde, da Du mich stärkst und vor Dein Angesicht mich allzeit treten läßt. Gepriesen sei der Herr, Gott Israels, von Ewigkeit zu Ewigkeit! Amen! Amen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Auf den Siegesspender, ein Lehrgedicht, von den Korachiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Gleich einem Hirsch, nach Wasserbächen schmachtend, so schmachtet meine Seele, Gott, nach Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Nach Gott lechzt meine Seele, dem lebendigen Gott. Wann darf ich kommen, daß ich das Antlitz Gottes schaue?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Bei Tag und Nacht sind Tränen meine Speise, weil man mich täglich fragt: \"Wo ist dein Gott?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Mein Sinnen und mein Wünschen wäre dies: Ich möchte hin zum Zelt, zum Hause Gottes wallen, mit lautem Jubeldanke, eine Festschar leiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Was härmst du dich, mein Herz? Warum ist dir so bang in mir? Auf Gott vertrau! Ich preise ihn gewißlich noch, ihn, meines Angesichtes Hilfe, meinen Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Mein Herz härmt sich in mir; ich denke deshalb Dein im Jordanlande, beim Hermon und beim kleinen Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Hier gibt ein Abgrund an den andern weiter Deiner Wasserfälle Hall. So sind gestürzt all Deine Wogen und Deine Wellen über mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Der Herr entzieht tagsüber seine Huld; bei Nacht ist er so hart mit mir. Im Bittgebet zu meines Lebens Gott');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'will ich zu Gott so sprechen. \"Mein Hort, warum vergißt Du mich?\" Warum muß ich in Trauer wandeln, vom Feind bedrängt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Mich haben meine Widersacher drob verhöhnt, daß meine Glieder brannten. Sie haben allzeit mich gefragt: \"Wo ist dein Gott?\" Was härmst du dich, mein Herz? Warum ist dir so bang in mir? Auf Gott vertrau! Ich preise ihn gewißlich noch, ihn, meines Angesichtes Hilfe, meinen Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Schaff Recht mir, Gott! Und führe meine Sache. gen solch ein lieblos Heidenvolk! Von falschen, bösen Leuten rette mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Mein Schutzgott bist ja Du. Warum verstößt Du mich? Warum muß ich in Trauer wandeln, vom Feind gedrängt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Send aus Dein Licht und Deine Wahrheit, daß sie zu Deinem heiligen Berg mich leiten, zu Deinen Wohnungen mich führen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Ich möchte zum Altare Gottes kommen, zum Gotte meiner höchsten Wonne. Dann brächte ich Dir mit der Zither Lobpreis dar, du Gott, mein Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Was härmst du dich, mein Herz? Warum ist dir so bang in mir? Auf Gott vertrau! Ihn preise ich gewißlich noch, ihn, meine Hilfe, meinen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Auf den Siegesspender, von den Korachiten, ein Lehrgedicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Wir wissen\'s, Gott, vom Hörensagen; uns haben unsere Ahnen es erzählt: das Werk, das Du in ihren Tagen, in alten Zeiten, ausgeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Mit Deinem Arme hast Du Heidenvölker ausgetrieben; dann pflanztest andere Du ein und riebest Nationen auf, und andere hast Du ausgebreitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Nicht ihrem Schwerte haben sie das Land verdankt; ihr Arm hat ihnen nicht den Sieg gebracht. Nein, Deine Rechte und Dein Arm und Deines Angesichtes Leuchten; Du bist ihnen hold gewesen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Du bist mein König, und mein Gott, der Jakob Sieg entbietet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Mit Dir nur stoßen wir die Gegner nieder, zertreten unsere Feinde nur in Deinem Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Nicht meinem Bogen traue ich; den Sieg verschafft mir nicht mein Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Nur Du befreist uns von den Gegnern und machst zuschanden unsere Hasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Nur Gottes wollen wir uns allzeit rühmen und Deinen Namen preisen immerdar. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Nun hast Du uns verworfen, gar zuschanden uns gemacht: Du ziehst nicht mehr mit unsere Scharen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Du läßt uns vor dem Gegner fliehen, und unsere Hasser holen Beute sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Du gibst uns hin wie Schlachtschafe, zerstreust uns unter Heiden, und die Nationen schütteln über uns den Kopf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Verkaufst Dein Volk um nichts, Gewinn aus ihrem Kaufpreis ziehst Du nimmer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Du machst uns unsern Nachbarn zum Gespött, zum Hohn und Schimpfe allen um uns her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Zum Sprichwort für die Heiden machst Du uns, die Nationen alle schütteln über uns den Kopf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Mein Schimpf steht täglich mir vor Augen, und Scham bedeckt mein Angesicht');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'bei dem Geschrei des Spötters und des Lästerers, vor Feinden und vor Rachegierigen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'All das hat uns getroffen, obschon wir Deiner nicht vergessen, an Deinem Bunde nicht gefrevelt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Doch unser Herz schreckt nicht zurück; nicht schwanken unsere Schritte ab von Deinem Pfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Obschon Du uns in Schrecken bringst an einer Stätte der Schakale, mit Todesschatten uns umhüllst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Vergessen wir den Namen unseres Gottes? Und strecken wir nach einem fremden Gott die Hände aus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Erforschte dies nicht Gott? Er kennt des Herzens Heimlichkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Nein! Deinetwegen mordet man uns täglich und achtet uns wie Schlachtschafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Erwache doch! Was schläfst Du, Herr? Wach auf! Verwirf uns nicht für immer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Warum verhüllst Du denn Dein Angesicht und denkst nicht mehr an unsere Pein und Not?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Gebeugt zum Staub ist unser Körper, zu Boden unser Leib gedrückt. Auf jetzt zu unserer Hilfe! Erlöse uns um Deiner Gnade willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Auf den Siegesspender, für den öffentlichen Gottesdienst, von den Korachiten, ein Lehrgedicht, ein Lied der Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mein Herz bewegt ein feines Ding; in meinem Liede singe ich von einem König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Dem schnellsten Schreibegriffel sei meine Zunge dabei ähnlich! \"Du bist so schön wie sonst kein Menschenkind, und Anmut ist auf deine Lippen ausgegossen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'weil Gott dich segnet für und für. Umgürte, Held, mit deinem Schwert die Hüfte, mit deiner Zierde, deinem Schmuck!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Und rüste dich mit deiner Zier! Besteig ein treues Tier mit Siegesmut und laß dir deine Rechte Wunder weisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Geschärft sind deine Pfeile, daß Völker dir zu Füßen fallen, wenn sie ins Herz der Königsfeinde dringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Dein Thron ist ewiglich und immerdar ein Gottesthron, gerechtes Szepter ist das Szepter deines Reiches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du liebst das Recht; das Unrecht hassest du; drum salbt dich Gott, dein Gott, mit wonniglichem Öle mehr als deine Mitgenossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Mit Myrrhe, Aloë und Kassia erquicken deine Kleider dich aus elfenbeinernen, minäischen Behältern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Mit Gaben dir zu Ehren kommen Königstöchter; mit Ophirgold tritt Dir zur Rechten die Gemahlin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Merk, Tochter, auf, schau her und neig dein Ohr! Vergiß dein Volk und deines Vaters Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Und will der König sich an deiner Schönheit laben, ist er ja doch dein Ehgemahl, zeig dich ihm wohlgewogen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Du Armutstochter! Mit den Gaben kommen und huldigen vor dir des Volkes Reichste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Die ganze Pracht der Königstochter ist inwendig; in Gold gewirkt ist ihr Gewand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Auf bunten Teppichen wird sie zum König hingeführt; jungfräuliche Gespielinnen sind ihr Gefolge; sie werden zu ihr hingeleitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Mit Freudenjubel führt man sie herbei; sie ziehen in das königliche Schloß. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'An deiner Väter Stelle treten deine Söhne; du machst sie überall im Land zu Fürsten. Ein ewig Denkmal will ich deinem Ruhme stiften, drum sollen dich die Völker ewig preisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Auf den Siegesspender, von den Korachiten, mit verborgenem Sinne ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gott ist uns Schutz und Zuversicht, in Nöten eine Hilfe, leicht zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Drum fürchteten wir uns auch nicht, selbst wenn die Erde wankte, versänken Berge gar ins Meer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'daß seine Wasser tosend schäumten, daß selbst vor seinem Wüten Berge bebten. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Ein Strom ist da. Die Gottesstadt erfreuen seine Arme, die heiligste der Wohnungen des Höchsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'In ihr ist Gott; sie kann nicht wanken. Gott steht ihr bei noch vor der Morgenwende. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Die Heidenvölker tobten. Reiche wankten. Darein gedonnert hat er, daß die Erde bebte. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Der Herr der Heeresscharen ist mit uns; und eine Burg ist Jakobs Gott für uns. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Herbei und schaut des Herrn Taten, der überaus Erstaunliches im Land getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Die Kämpfe läßt er ruhn bis an des Landes Grenze. zerbricht die Bogen und zerschlägt die Speere, verbrennt die Schilde. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '\"Laßt ab! Bedenket: Ich bin Gott! Ich will erhaben bei den Heiden sein, wie ich erhaben bin im eignen Lande.\" Der Herr der Heeresscharen ist mit uns; und eine Burg ist Jakobs Gott für uns. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Auf den Siegesspender, von den Korachiten, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Ihr Stämme all, klatscht in die Hände! Mit Jubelschall singt eurem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Als Höchster wird der Herr gefürchtet, als großer König auf der ganzen Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Er unterjocht uns Völker und Nationen legt er uns zu Füßen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'bestimmt, daß unser Erbteil uns verbleibe. der Ruhm für Jakob, den er liebt. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Im Jubelsang fährt Gott empor und mit Trompetenschall der Herr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Lobsinget unserm König! Singt! Lobsinget unserm König! Singt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Denn Gott wird König auf der ganzen Erde. Nun singet herrlich! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Als König zeigt sich Gott den Heiden; Gott thront auf seinem heiligen Throne. Der Völker Fürsten schwinden hin, du Volk des Gottes Abrahams! Denn Gott gehört die Macht auf Erden. Erhaben steht er obenan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein Gesang, ein Lied, von den Korachiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Der Herr ist groß und hochzupreisen ob unserer Gottesstadt, ob seines heiligen Berges,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'der herrlich sich erhebt, der ganzen Erde Wonne, der Berg von Sion, der im Norden der Stadt des großen Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'In ihren Burgen hat sich Gott als Schutzwehr kundgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Versammelt haben sich die Könige, sind allzumal herangezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Sie sind erstarrt, kaum daß sie es gesehen, und sind bestürzt entflohen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Von Schrecken dort erfaßt, von Angst, gleich der in Kindesnöten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'wie wenn der Ostwind Tarsisschiffe stranden läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Was vormals wir gehört, das haben wir geschaut jetzt an der Stadt des Herrn der Heeresscharen, unserer Gottesstadt. Gott läßt sie ewiglich bestehen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Wir haben Deine Gnade, Gott, empfangen hier in Deinem Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Gleich Deinem Himmel, Gott, erstreckt sich Deine Herrlichkeit bis an der Erde Ende. Voll von Gerechtigkeit ist Deine Rechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Der Sionsberg ist voller Freude, und Judas Töchter jubeln über Deine Strafgerichte. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Umgeht, umwandert Sion! Und zählet seine Türme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Betrachtet seinen Wall! Durchmustert seine Burgen, daß ihr\'s dem künftigen Geschlecht verkünden könnt, daß Gott es ist, in alle Ewigkeiten unser Gott, der selbst uns leitet für und für!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Auf den Siegesspender, von den Korachiten, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Ihr Völker alle, hört! Ihr Weltbewohner all, merkt auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Gemeine Leute, Herrensöhne, ihr all zusammen, reich und arm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Mein Mund trägt Weisheit vor, und meines Herzens Dichtung ist voll Einsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Ich lausche einem Spruch, mein Lied mit Zitherspiel beginnend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Warum soll ich in Unglückstagen zagen, wo meiner Gegner Bosheit mich umgibt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'die auf ihr Gut vertrauen, sich ihres großen Reichtums rühmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Nicht einer kann sich selbst loskaufen, nicht einer Gott für sich ein Lösegeld erlegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'zu teuer ist der Loskauf ihrer selbst und so für alle Zeit unmöglich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'daß er für immer lebe und nicht die Grube sehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Da sieht man Weise sterben, wie Tor und Narr vergehn und andern ihr Vermögen hinterlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Für immer ist ihr Grab ihr Haus, für alle Zukunft ihre Wohnstätte, sie, deren Namen Weltruf hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Der Mensch bleibt nicht im Ansehen, er gleicht den Tieren, die man würgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Das ist ihr Lauf; das ist\'s, was ihrer wartet, und was nach ihrem Ende wird, das können selber sie erzählen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Sie sind den Schafen gleich, die für die Unterwelt der Tod schon weidet; der führt sie unparteiisch bald hinab, zur Unterwelt, zu ihrer Wohnung, wo ihr Gespenst verschwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Doch Gott behütet meine Seele vor der Unterwelt; er nimmt mich mit. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Sei unbesorgt! Wenn einer sich bereichert, wenn seines Hauses Überfluß sich mehrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'beim Sterben nimmt er doch nicht alles mit; sein Reichtum folgt ihm nicht hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Er schätzte sich dann mit dem bloßen Leben glücklich, und priese glücklich dich, daß dir\'s noch gut ergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Doch muß er zum Geschlechte seiner Väter gehen, die nimmermehr das Licht erblicken. Der Mensch bleibt nicht im Ansehen, er gleicht den Tieren, die man würgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Lied, von Asaph. - Gott, Gott der Herr, soll reden; rufe er die Erde vom Aufgang bis zum Niedergang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Von Sion her, der Schönheit Krone, erstrahle Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'So komme wieder unser Gott und schweige nicht! Verzehrend Feuer schreite vor ihm her; gewaltig stürme es um ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Dem Himmel droben rufe er und dann der Erde mit den Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Versammelt mir jetzt meine Frommen, die einen Bund mit mir geschlossen!\", daß sie sein Volk der Opfer wegen richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Der Himmel lege Zeugnis dafür ab: \"Er ist im Recht; er ist ein Gott des Rechtes.\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Mein Volk, gib acht und laß mich reden, Israel! Dich ermahn ich ernstlich: \"Gott, dein Gott, bin ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Ich tadle dich nicht deiner Opfer wegen, und deine Brandopfer steht immer mir vor Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Doch brauche ich kein Rind aus deinem Hause, aus deinen Hürden keine Böcke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Denn mein ist alles Wild im Walde, auf Tausenden von Bergen das Getier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ich kenne alle Vögel im Gebirge; mir steht zu Diensten das, was sich im Felde regt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Und sollte je ich hungern, dir sagt\' ich es nicht; mein ist die Welt und was sie füllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Will ich denn Fleisch von Stieren essen? Und trinke ich der Böcke Blut?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Bring Dank dem Herrn zum Opfer dar und löse so dem Höchsten dein Gelübde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Und ruf am Tag der Not mich an. Dann werde ich dich retten. Aber danken sollst du mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Zum Frevler aber spreche Gott: \"Was schwatzest du von meinen Satzungen und führst im Munde meinen Bund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Du hassest doch die Zucht, und meine Worte schlägst du in den Wind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Kaum siehst du einen Dieb, so läufst du schon mit ihm. Mit Ehebrechern gehst du um');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'und lässest deinen Mund in Bosheit sich ergehen, und deine Zunge paarest du mit Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Da setzst du dich und redest gegen deinen Bruder, verleumdest deiner Mutter Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Das tust du, und ich sollte schweigen? Du dächtest dann, ich sei wie du. Zur Rede stelle ich dich jetzt und zeige deutlich dir den Unterschied-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Dies merkt, ihr Gottvergessenen! Sonst raffe ich euch rettungslos dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Wer Dank darbringt, der gibt mir Ehre. Wer gutes Beispiel gibt, den laß\' ich göttlich Heil erblicken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Auf den Siegesspender, ein Lied, von David,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'als der Prophet Nathan zu ihm kam, nachdem er zu Bathseba gegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Erbarm Dich meiner, Gott, nach Deiner Huld! Nach Deiner großen Güte tilge meine Missetaten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Wasch meine Schuld mir gründlich ab, und reinige von meiner Sünde mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Denn ich erkenne meine Missetaten, und meine Sünde schwebet stets vor mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'An Dir allein hab ich gesündigt, was bös in Deinen Augen ist, getan, daß Du gerecht dastehst bei Deinem Richterspruche und tadellos mit Deinem Richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Geboren bin ich in der Sünde; in Schuld hat meine Mutter mich empfangen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Du liebst die Wahrheit in unverhüllterweise und unterrichtest mich in Weisheit auf verborgne Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Wasch mich mit Ysop rein von Sünden! Wasch mich, auf daß ich weißer sei als Schnee!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Vernehmen laß mich Freud\' und Wonne! Laß die von Dir zerschlagenen Gebeine jubeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Verbirg Dein Angesicht vor meinen Sünden, und tilge alle meine Missetaten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Erschaff mir, Gott, ein reines Herz, und in mir einen rechten Geist erzeuge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Verstoß mich nimmermehr von Deinem Angesicht, und Deinen heiligen Geist entziehe mir nicht wieder! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Gib wieder mir die Wonne Deines Heils! Erquicke mich mit frohgemutem Geist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Die Irrenden belehre ich dann über Deine Wege, und Sünder kehren sich zu Dir. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Gott, ohne Blutopfer, errette mich, Du meines Heiles Gott. Alsdann wird meine Zunge jubelnd Deine Liebe preisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Herr, öffne Du mir meine Lippen! Dann wird mein Mund Dein Lob verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Denn Du verlangst nicht Blutopfer, noch andre Gaben. Nicht willst Du Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Mein Opfer, Gott, ist ein zerbrochener Geist, ein ganz gebrochen und zerknirschtes Herz, o Gott, verschmähst Du nie. - In Deiner Gnade fördere Sion! Erbau die Mauern von Jerusalem! Dann findest Du an echten Opfern Freude sowie an Brand- und ganzen Opfern. Auf Deinen Altar kommen dann Gebete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Auf den Siegesspender, ein Lehrgedicht von David,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'als der Edomiter Doeg kam und dem Saul meldete und sprach: \"David ist in Achimeleks Haus gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Was rühmst du dich der Bosheit, du Gewaltmensch, als wär sie eine Gottesgnade immerdar?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Du schätzest Frevel hoch, und deine Zunge gleicht einem scharfen Messer, das mit Trug arbeitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du liebst das Böse mehr als Gutes und redest lieber Unwahrheit als Wahrheit. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du liebst die glatten Reden all und falsche Zungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Auch dich wirft Gott für immer nieder; er packt dich, reißt dich aus dem Zelt, entwurzelt dich aus der Lebendigen Land. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Das sehen die Gerechten voller Furcht, und sie verlachen ihn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '\"Da seht den Mann! Er hält nicht Gott für seine Stütze, vertraut auf seines Reichtums Fülle und pocht auf seine Bosheit.\" Dem grünen Ölbaum in dem Gotteshause gleich, hab ich mich stets auf Gottes Huld verlassen. Ich danke Dir auf ewig, wenn Du\'s tust. Vor Deinen Frommen künd ich, daß so gut Dein Name ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Auf den Siegesspender, schon vorhanden, ein Lehrgedicht, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'In seinem Herzen spricht der Tor: \"Kein Gott ist da.\" Verkehrt, verrucht sind sie in ihrem Frevel, und keiner ist, der Gutes täte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Vom Himmel hat sich Gott geneigt hernieder auf die Menschenkinder, zu schaun, ob jemand der Vernunft gehorcht und Gott aufsucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Sie alle sind verderbt, wie Schlacken, und keiner ist, der Gutes täte, auch nicht einer. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Erfuhren\'s nicht die Übeltäter, die meines Volkes Speisen neulich aufgezehrt und Gott gelassen außer acht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ein Schrecken hatte auf der Stelle sie gepackt. War\'s nicht ein Schrecken, als die Gebeine des Verderbers schimpflich Gott zerstreute? Gott hat sie ja verworfen. Von Sion komme wieder Heil für Israel! Ach wendete doch Gott das Schicksal seines Volkes! Dann wäre Jakob fröhlich und frohlockte Israel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Auf den Siegesspender, bei Saitenspiel, ein Lehrgedicht, von David,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'als die Ziphiter zu Saul kamen und sagten \"HäIt bei uns sich David nicht verborgen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Hilf mir, o Gott, durch Deinen Namen! Verschaff mir Recht durch Deine Stärke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Gott! Höre mein Gebet! Vernimm die Worte meines Mundes\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Erheben Fremdlinge sich gegen mich und trachten Mächtige mir nach dem Leben und stellen Gott sich nicht vor Augen, (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'so ist mir Gott ein Helfer. Der Herr bleibt der Beschirmer meines Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Auf meine Feinde falle Ungemach zurück! Vertilge sie nach Deiner Treue! Ein reichlich Opfer bringe ich Dir dar und rühme Deinen Namen, Herr, daß er so gütig ist. Er rettet mich aus aller Not; mein Auge weidet sich an meinen Feinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Auf den Siegesspender, bei Saitenspiel, ein Lehrgedicht, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Gott! Höre mein Gebet! Verbirg Dich nicht vor meinem Flehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Merk doch auf mich, erhöre mich! Ich bin verwirrt und zage kläglich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'dieweil der Feind so tobt, der Frevler drängt, und Unheil wälzen sie auf mich und sind mir heftig gram. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mir bebt das Herz in meiner Brust; mich überfallen Todesängste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Und Furcht und Zittern überkommen mich; ein Schauder überschauert mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Ach, hätte ich doch Taubenschwingen, wünschte ich, ich flöge fort und suchte Rast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'In weite Ferne hin, zur Wüste in die Herberge! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Geschwinder eilte ich zu meiner Zufluchtsstatt als Sturm und Wirbelwind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Herr! Spalte, teile ihre Zunge! Ich sehe Streit und Frevel in der Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Sie wandeln Tag und Nacht um ihre Mauern, und Not und Jammer herrscht darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Verderben herrscht in ihr; von ihrem Markte weicht nicht Lug noch Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Nicht schmäht mich jetzt mein Feind; denn das ertrüge ich. Mein Hasser höhnt mich nicht, sonst bärge ich mich sicherlich vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Nein! Du, ein Mensch von meinem Rang, mein Freund, mein Busenfreund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Die wir vertraulich miteinander lebten, zum Gotteshaus im Zuge wallten! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Sie überliste jetzt der Tod, daß sie lebendig in die Hölle fahren! In ihrem Innern nistet Bosheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ich ruf\' zu Gott, der Herr mög\' mich erretten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Ich klage abends, morgens, mittags, seufzend. Er möge meinen Ruf erhören.-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, '\"Erlöse mich zum Heil aus diesem Kampfe gegen mich! Sie stehn im Kampf mit mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gott höre es und beuge sie und stoße sie zurück, (Sela.) die nicht Versöhnung kennen und Gott nicht fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Vergriffen hat er sich sogar an meinen Opfern, an seinem Bund gefrevelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Sein Mund war glatt, der Butter gleich, doch stand nach Kampf sein Sinn. Geschmeidiger als Öl, so waren seine Worte, und doch gezwickte Dolche:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, '\"Befiehl dich doch dem Herrn! Er hat dich lieb und sorgt für dich und läßt nicht den Gerechten wanken.\" Der Todesgrube übergib sie, Gott! Blutmenschen und Betrüger sollen nicht zur Hälfte ihrer Lebenstage kommen! Auf Dich vertraue ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Auf den Siegesspender, für den unschuldigen Zugewanderten in der Ferne, von David, ein Weihegesang, als ihn die Philister zu Gath festhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Gott! Sei mir gnädig! Denn Menschen schnauben wider mich, und täglich ängstigt mich mein Feind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Ja, meine Feinde schnauben immerfort; denn viele streiten gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Jedoch der Tag ist weit entfernt, da ich mich fürchte; denn auf Dich vertraue ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Ich rühme mich der Gotteszusage; furchtlos vertraue ich auf Gott. Was können Sterbliche mir tun?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Und fechten sie auch täglich meine Worte an, sind alle ihre Pläne, mir zum Schaden, böse,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'sie müssen doch sich fürchten und verkriechen und so auf meine Schritte lauschen, wie sie\'s von mir erwartet haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Verstoße sie des Frevels wegen! Die Scharen stürze hin im Grimme, Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Vermerkst Du schon mein Schwanken, dann lege meine Tränen auch in Deinen Schlauch, voll angerechnet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Dann weichen meine Feinde. Am Tage, da ich rufe, weiß ich, daß ich einen Gott besitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Ich rühme mich der Gotteszusage; ich rühme mich der Zusage des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Furchtlos vertraue ich auf Gott. Was kann ein Mensch mir antun? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ich schulde Dir Gelübde, Gott; ich zahle sie Dir heim mit Dankbarkeit. Denn meine Seele wahrst Du vor dem Tod, nicht wahr? vorm Sturze meine Füße. So kann ich länger noch vor Gott im Licht des Lebens wallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Auf den Siegesspender, ein Kunstgesang, von David, ein Weihegesang, als er vor Saul in die Höhle floh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Gott! Sei mir gnädig! Sei mir gnädig! Denn meine Seele flieht zu Dir. Ich fliehe in den Schatten Deiner Flügel, bis die Gefahr vorübergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Zu Gott, dem Höchsten, rufe ich, zu Gott, der mir nur Gutes tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Er sendet Hilfe mir vom Himmel, verhöhnt mich auch mein Gegner, (Sela.) Gott sendet dennoch seine Huld und Treue. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Ich weile unter Löwen, bei Menschenfressern, bei Leuten, deren Zähne Spieß und Pfeile und deren Zungen scharfe Dolche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Erhebe Dich, o Gott, soweit der Himmel, und Deinen Ruhm, soweit die Erde reicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Sie stellen meinem Schritt ein Netz; doch ich umgehe es. Sie graben eine Grube mir und fallen selbst hinein. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Aus Herzensgrunde, Gott, aus Herzensgrunde sing ich und juble:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, '\"Erwache, du mein Stolz! Wach, Harfe, auf und Zither! Ich singe wach das Morgenrot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Ich preise, Herr, Dich bei den Völkern, und ich besinge Dich bei den Nationen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'daß Deine Huld bis an den Himmel reicht, bis zu den Wolken Deine Treue. Erhebe Dich, o Gott, soweit der Himmel, und Deinen Ruhm, soweit die Erde reicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Auf den Siegesspender, ein Kunstgesang, von David, ein Weihelied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Ihr wollet also wirklich Wahrheit reden, den Menschen richtigen Bescheid erteilen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Nein! Nur auf Unrecht sinnet ihr im Herzen und laßt im Lande eurer Hände Frevel freien Lauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Verkehrt vom Mutterleibe an sind Gottlose; vom Mutterschoß her irren schon die Lügner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Der Schlangenwut gleicht ihre Wut; sie gleicht der tauben Otter, die ihr Ohr verschließt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'und nicht auf der Beschwörer Stimme hört, nicht auf den klugen Zaubermeister. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Schlag ihnen, Gott, die Zähne aus dem Munde! Zerschmettre das Gebiß der jungen Löwen, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Vergehen sollen sie, wie Wasser sich verlaufen! Ihr Gift soll man zertreten; also sollen sie verschwinden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Wie Leibesfrucht, nicht ausgetragen, fault, so mögen sie vergehn wie eine Fehlgeburt, die Sonne nicht mehr schauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Bevor sie es noch merken, verwehe sie ein Sturmwind gleich dem Dorngestrüpp!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Der Fromme freut sich bei dem Anblick der Vergeltung und kann im Blut des Frevlers seine Füße baden. Die Leute sagen dann: \"Gerecht sein, das ist lohnend; noch ist ein Gott auf Erden Richter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Auf den Siegesspender, ein Kunstgesang, von David, ein Weihelied, als Saul hinsandte und sein Haus bewachen ließ, um ihn zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Errette mich, mein Gott, von meinen Feinden! Befreie mich von meinen Widersachern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Erlöse mich von Übeltätern! Vor Mordgesellen schütze mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Denn auf mein Leben lauem Wüteriche; ganz ohne Schuld von meiner Seite greifen sie mich an, ganz ohne mein Vergehen, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Sie stürmen grundlos an und zielen. Wach auf! Blick her, mein Führer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Herr, Gott der Heerscharen, Gott Israels! Wach auf! Such all die Heiden heim und schone keinen falschen Übeltäter! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Sie sollen jeden Abend wiederkommen, heulend, und Hunden gleich die Stadt umstreifen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Sieh, wie sie mit dem Munde geifern, wie sie mit ihren Lippen schwätzen: \"Wer sollte es vernehmen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Doch Du, Herr, lachst sie aus; Du spottest aller dieser Heiden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Du meine Stärke: Dich allein erwarte ich; denn Gott ist meine Burg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Mein Gott kommt mir mit seiner Huld zuvor; Gott läßt mich Lust an meinen Feinden sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Laß sie nicht sterben, daß mein Volk es nicht vergesse! Laß sie in Deinen Mauern betteln gehn! Dann stoß sie aus dem Tore, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Denn ihrer Lippen Wort ist Zungensünde. So mögen ihrem Übermute sie verfallen ob der verfluchten Lüge, die sie reden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Vollbring\'s im Grimm! Vollbring\'s, daß sie zunichte werden! Erfahren sollen sie\'s, daß Herrscher sei in Jakob Gott bis an der Erde Grenzen! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Sie sollen jeden Abend wiederkommen, heulend, und Hunden gleich die Stadt umstreifen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Ums Essen betteln gehn und heulen sollen sie, wenn sie nicht satt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ich aber singe Deiner Macht und preise Deine Huld in aller Frühe, daß Du mir eine Burg und Zuflucht bist am Tage meiner Not. \"O meine Stärke!\" will ich von Dir singen. Du, Gott, bist meine Burg, mein gnadenvoller Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Auf den Siegesspender, für den öffentlichen Gottesdienst, ein Weihelied, von David, zum Lehren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'als er mit den Syrern von Mesopotamien und den Syrern von Soba kämpfte, und als Joab zurückkehrte und die Edomiter im Salztal schlug, 12.000 Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gott! Du verwirfst uns; ach, Du schlägst uns; Du läßt in Deinem Zorn zurück uns weichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Das Land erschütterst Du und schlägst ihm Wunden. Heil ihm die Wunden! Sieh, es wankt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Du bist so hart mit Deinem Volke, tränkst uns mit Taumelwein');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'und machst, daß, die Dich fürchten, im Kampfe irre fliehen müssen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Daß Deine Lieblinge gerettet werden, dazu verhilf mit Deiner Rechten! Höre uns!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gott hat in seinem Heiligtum gesprochen: \"Ich soll im Siegesjubel Sichem jetzt verteilen, das Sukkot-Tal vermessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Mein würde Gilead, Manasse mein, und meine Hauptwehr Ephraim und Juda mein Regentenstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Ich zwänge Moab, mir das Waschbecken, und Edom, mir die Schuhe herzurichten, und über Philistäa triumphierte ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Wer bringt mich aber jetzt zur festen Stadt? Wer führt mich jetzt nach Edom hin? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Bist Du\'s nicht, Gott, der uns verstößt, der nicht mit unsern Scharen auszieht, Gott? Verschaffe Rettung uns aus dieser Not! Denn Menschenhilfe trügt. Mit Gott verrichten wir dann Heldentaten; nur er kann unsere Feinde niederwerfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Auf den Siegesspender, mit Saitenspiel, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, '\"Hör, Gott, mein Rufen! Vernimm mein Flehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Ich rufe von des Landes Grenze zu Dir in meiner Herzensnot: Auf einen Felsen führe mich, der sonst für mich zu hoch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Denn Du bist meine Zuversicht, ein fester Turm vorm Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'In Deinem Zelte laß mich ewig weilen, mich bergen in dem Schatten Deiner Flügel! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Wenn du auf mein Gelübde hörest, Gott, und denen ihr Begehr erfüllst, die Deinen Namen fürchten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'dann füg des Königs Tagen viele andere zu! Dann seien seine Jahre lang, wie nur in der Geschlechterreihe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Er throne ewiglich vor Gottes Angesicht! Und Lieb und Treue mögen ihn beschützen! Dann will ich Deinem Namen immerdar lobsingen und mein Gelübde Tag für Tag einlösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Auf den Siegesspender, für Zurückgezogene. Ein Lied von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'In Gott allein ist Stille, meine Seele; von ihm kommt meine Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Mein Hort und Heil ist er allein und meine Burg. Ich zweifle nicht daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Wie lange schreiet einen Mann ihr an und wollet ihn ums Leben bringen, ihr alle, die ihr einer schiefen Wand und einem morschen Zaune gleicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Sie raten ihm gar eitel, wollen ihn verführen. Mit ihrem Lügenmunde segnen sie und hegen Fluch im Herzen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Mein Herz, sei still in Gott! Von ihm allein kommt, was ich hoffe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Mein Hort und Heil ist er allein und meine Burg. Ich zweifle nicht daran. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Auf Gott beruht mein Heil und Ruhm. Er ist mein starker Hort. Bei Gott ist meine Zuversicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Vertraut, ihr Leute, ihm zu jeder Zeit der Trübsal! Und schüttet vor ihm aus das Herz! Nur Gott ist unsere Zuversicht. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Die Menschenkinder sind ein Nichts, die Männer Täuschung; sie schnellen auf der Waage wie ein Nichts empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Vertrauet nicht auf unrecht Gut! Auf Raub setzt nicht die eitle Hoffnung! Und sprosse Reichtum auch daraus, nicht achtet drauf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Ein Wort hat Gott gesprochen, und Zwiefaches entnehme ich daraus: \"Die Macht ist Gottes Eigentum\" und \"Eigen ist Dir Gnade, Herr, und jeglichem lohnst Du nach seinem Werke.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein Lied, von David, als er in der Wüste Juda war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Dich such ich, Gott, mein Gott; nach Dir lechzt meine Seele; nach Dir sehnt sich mein Fleisch. Wie in dem dürren, trocknen, wasserlosen Lande,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'so schau ich aus nach Dir, um Deine Pracht zu sehen und Deine Majestät im Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Denn köstlicher ist Deine Huld als Leben. Dich preisen meine Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'So preise ich Dich lebenslang; in Deinem Namen will ich regen meine Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Gleichwie von Fett und Öl wird meine Seele satt; mit Jubellippen singt mein Mund,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'wenn ich auf meinem Lager Dein gedenke, in mitternächtiger Stunde sinne über Dich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Du möchtest Schutz mir sein, daß ich im Schatten Deiner Flügel jauchze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'An Dir hängt meine Seele; ich klammere mich an Deine Rechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Die meine Seele gerne in der Wüste wüßten, sie mögen in der Erde Tiefe fahren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Die sie dem Untergange überliefern wollen, die mögen der Schakale Beute werden! Der König aber freue sich in Gott, und wer ihm Treue schwört, der jauchze! Der Lügner Mund wird zugestopft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Auf den Siegesspender, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Erhör, mein Rufen, Gott! Ich klage. Mein Leben wahre vor des Feindes Schrecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Verbirg mich vor der Bösen Rotte, vor dem Gelärm der Missetäter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'die ihre Zungen gleich dem Dolche schärfen, ein giftig Wort zum Pfeile machen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'um aus Verstecken auf die Wehrlosen zu schießen, sie unvermutet zu erschießen, ohne Scheu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Sie machen für sich Schlimmes aus; sie rühmen sich des Schlingenlegens. \"Wer wird sie sehen?\" sagen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Sie sinnen auf Verbrechen. \"Wir denken sie nach allen Seiten aus\", so denken sie bei sich im tiefsten Herzensgrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Mit Pfeilen treff\' sie Gott! Ganz unvermutet sollen ihnen Wunden werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Sie sollen ihnen ihre Zunge lähmen! Ein jeder schaudere, der dies an ihnen sieht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Dann fürchten sich die andern Menschen alle und künden es als Gottes Tat und rechnen als sein Werk es an. Der Fromme freue sich alsdann des Herrn und baue fest auf ihn, und alle frommen Herzen triumphieren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Auf den Siegesspender, ein Lied, von David, ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Als Lobgesang gebührt Dir Schweigen, Gott; in Sion will man Dir Gelübde lösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Erhörer des Gebets! Wenn alles Fleisches Missetat auch vor Dich käme,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'an Zahl noch mehr als unsere eigenen Vergehen, Du bist es, der sie tilgen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Heil dem, den Du erwählest und berufst, daß er in Deinen Höfen weile! Wir möchten uns am Segen Deines Hauses, an Deines Tempels Weihe laben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Du mögest uns auf wirklich wunderbare Art erhören, Du unseres Heiles Gott, Du Hoffnung aller fernsten Erd- und Meeresgrenzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'der Du die Berge unermüdlich fruchtbar machst, mit Kraft gegürtet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'der Du der Meere Brausen stillst, das laute Toben ihrer Wogen, das Ungestüm der Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Die an den Enden wohnen, vor Deinen Zeichen werden sie sich fürchten, wenn Du das Morgen- und das Abendland aufjubeln machst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Wenn Du die Erde heimsuchst, mögst Du sie bewässern und segnen reich mit einem Gottesbach voll Wasser und so ihr Korn bereiten, wenn Du sie so bestellst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Befeuchte ihre Furchen, ebne ihre Schollen, und Regengüsse mögen sie erweichen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du aber segne ihr Gewächs! Mögst Du das Jahr mit Deinem Segen krönen, daß Deine Pfade triefen von dem Überfluß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Auf daß der Steppe Auen triefen, die Hügel sich mit Jubel gürten, die Fluren sich in Früchte kleiden und Täler sich in Korn einholen und jauchzend um die Wette singen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Auf den Siegesspender, ein Gesang; ein Lied. - Jauchzt Gott zu, alle Lande!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Besinget seines Namens Herrlichkeit! Besinget herrlich seinen Lobpreis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'So sprecht von Gott: \"Wie wundervoll sind Deine Werke! Selbst Deine Feinde schlagen sich auf Deine Seite ob Deiner großen Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Der ganze Erdkreis betet vor Dir an und singet Dir, singt Deinem Namen.\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Herbei! Schaut Gottes Werke! Wie hehr sein Walten an den Menschenkindern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'In trocken Land verwandelt er das Meer; zu Fuß durchschreiten sie den Strom. So wollen wir uns seiner freuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Der ewig herrscht mit seiner Allgewalt, er richtet seine Blicke auf die Heiden; sie können sie nicht von sich abwenden trotz ihrem Sträuben. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Ihr Völker, preiset unsern Gott und lasset laut sein Lob erschallen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'der unser Leben immerfort erhält und unsern Fuß nicht gleiten läßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Du hast uns freilich, Gott, geprüft, geläutert uns wie Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Du hast in Banden uns gebracht und Fesseln unsern Hüften angelegt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'und Menschen hast Du über uns zu Herren eingesetzt; in Feuer und in Wasser kamen wir; doch Du befreitest uns daraus zum Heile. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'So walle ich mit Brandopfern zu Deinem Hause, und mein Gelübde löse ich Dir ein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'wozu sich meine Lippen aufgetan, und was mein Mund in meiner Not versprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Brandopfer fetter Tiere bringe ich Dir dar samt Opferduft von Widdern; ich richte Rinder her und Böcke. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Herbei, ihr Gottesfürchtigen alle! Hört! Ich will euch erzählen, was er mir getan:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Mit meinem Munde habe ich zu ihm gerufen und Großes ihm mit meiner Zunge vorgetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Wenn ich mich eines Frevels schuldig je gewußt, dann hätte mich der Herr nicht angehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Nun aber hat es Gott gehört und auf mein laut Gebet geachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Gelobt sei Gott, der meine Bitte nicht versagt und seine Huld mir nicht entzogen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Auf den Siegesspender, mit Zithern, ein Lied, ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gott sei uns gnädig, segne uns! Er lasse uns sein Antlitz leuchten. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Wenn man auf Erden Deine Weise kennenlernt, bei all den Heiden Deine hilfereiche Art,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'dann preisen Dich die Völker, Gott, dann preisen Dich die Völker all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Dann freuen sich und jubeln die Nationen, daß Du gerecht die Völker richtest, auf Erden die Nationen leitest. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Dann preisen Dich die Völker, Gott; dann preisen Dich die Völker all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Die Erde spendet ihre Ernte! Uns segnet Gott ja, unser Gott! Uns segne fürder Gott, daß sich die Erdenenden alle vor ihm fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Auf den Siegesspender, von David, ein Lied, ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Erhebt sich Gott, dann stieben seine Feinde fort, und seine Hasser fliehn vor ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Wie Rauch verschwindet, wenn es stürmt, wie vor dem Feuer Wachs zerschmilzt, also vergehn vor Gottes Angesicht die Frevler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Die Frommen aber freuen sich, vor Gottes Angesicht frohlockend, in Freude, voller Fröhlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Lobsinget Gott! Singt seinem Namen! Die Bahn macht frei für den, der durch die Wüsten fährt! \"Herr\" ist sein Name,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, '\"der Waisen Vater und der Witwen Anwalt, Gott\". Vor ihm in seiner heiligen Wohnung freuet euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Gott bringt Einsame in die Heimat wieder, wenn er die Eingekerkerten in Freiheit setzt. Nur Widerspenstige verbleiben in dem dürren Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Gott, als Du auszogst an der Spitze Deines Volkes und durch die Wüste schrittest, (Sela)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'erzitterte die Erde. Der Himmel selbst zerfloß vor Gott dort an dem Sinai vor Gott, dem Gott von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Du mögest wieder Regen reichlich niederströmen lassen, Gott, um so Dein mattes Erbland zu erquicken, das am verschmachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Und Deine Leute, die drin wohnen, mögst Du zur rechten Zeit durch Deine Güte, Gott, versorgen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Der Herr ließ wieder donnern, beschloß der Völkerscharen Heer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Die Könige der Völker floh\'n in wilder Flucht, daß Schwächlinge selbst Beute teilten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Hinsanken sie auf Düngerstätten, in Kot versteckt, mit Schmach bedeckt, und ihre Reiterscharen in Morast vergraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Als der Allmächtige die Könige zerstreute, da fielen sie in Schauern auf dem Salmon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'auf diesem hohen Berge, diesem Basansberge. Ein kuppenreicher Berg ist dieser Basansberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Warum, ihr kuppenreichen Berge, seid ihr neidisch? Den einen Berg hat Gott zu seinem Sitze sich gewünscht; ja, ihn bewohnt der Herr auf ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Der Reiter Gottes sind\'s Zehntausende, gar viele Tausende. Bei ihnen ist der Herr, wie einst auf Sinai, so jetzt im Heiligtum. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du zogst zur Höhe, nahmst Gefangene gefangen, empfingest Menschen als Geschenk, die sich gesträubt, an Gott, den Herrn, zu glauben. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gepriesen sei der Herr, der täglich für uns sorgt, Gott unsere Hilfe! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Des Heiles Gott ist Gott für uns. Der Herr, der Herr, hat manchen Ausweg aus dem Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Ja, seiner Feinde Haupt hat Gott zerschmettert, den Haarbuschhelm des Mannes, der in seinen Sünden wandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Verkündet hat der Herr: \"Die Ausgeschämten hole ich. Ich hole her die aufgeblasenen Schurken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'daß blutig kann dein Fuß zertreten, die dich lästerten, in einem Augenblicke die verhaßten Hunde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Da sah man Deinen Zug, o Gott, den meines Gottes, meines Königs, in dem Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Vorn an der Spitze zogen Sänger, hinten Saitenspieler her und in der Mitte paukenschlagende Jungfrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Israel lobte seinen Gott in Chören und mit Musik den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Den Takt gab Benjamin, der jüngste. Die Fürsten Judas, Zabulons und Naphtalis, sie klatschten in die Hände. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Entbiete wiederum, Gott, Deine Macht, von Deinem Tempel aus, die Macht, mit der Du bisher, Gott, für uns gewirkt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'daß Könige Dir Gaben für Jerusalem darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Bedroh die Lanzenschar, das Rossevolk, das unter Völkern meist verpflanzte, das zu den Silbergängen sich hinunterläßt! Zerstreu die Völker, die an Kriegen Freude haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Gesandte sollen aus Ägypten kommen; zu Gott soll seine Hände Äthiopien ausstrecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Dann singt, ihr Erdenreiche, Gottes Lob! Lobsingt dem Herrn, (Sela)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'der durch der Himmel Himmel, den uralten, fährt, der seine Stimme wieder tönen läßt, gar eine mächtige Stimme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Die Ehre gebet Gott, ihm, dessen Hoheit wartet über Israel, und in den Wolken zeigt sich furchtbar seine Macht. Von alters ist Gott hocherhaben. Wer gleicht dem Gotte Israels, der Macht verleiht und Kraft dem Volk, das würdig ist des Gottessegens?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Auf den Siegesspender, für den öffentlichen Gottesdienst, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Gott! Rette mich! Bis an die Kehle geht mir das Gewässer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Ich sinke ohne Halt in tiefen Schlamm hineingeraten in die Wassertiefen; mich überströmen Strudel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Vom Rufen bin ich müde, heiser ist mir meine Kehle, und meine Augen nehmen ab vom Schaun nach meinem Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Die ohne Grund mich hassen, mehr als meines Hauptes Haare sind sie. Zuviel für meine Kräfte sind, die mich für nichts befehden. Erstatten soll ich, was ich nie geraubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Du wußtest, Gott, von meiner Torheit, und meine Schuld entging Dir nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Laß meinetwegen nicht zuschanden werden, die auf Dich harren, Herr, Du Herr der Heeresscharen! Nicht meinetwegen laß in Schmach geraten, die nach Dir suchen, Du Gott Israels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Denn Deinetwegen habe ich erduldet Schmach, hat Scham mein Angesicht bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Selbst meinen Brüdern bin ich fremd geworden, ein Fremdling meiner Mutter Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Denn mich verzehrt der Eifer für Dein Haus; der Geifer Deiner Schmäher fällt auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Wenn ich durch Fasten mich kasteie, so wird es mir zum Schimpf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Und mache ich zu meinem Kleid das Bußgewand, dann bin ich ihnen zum Gespött.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Die an den Toren sitzen, reden über mich, in Liedern voller Spott tun es die Zecher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ich aber bete, Herr, zu Dir um eine Gnadenzeit. In Deiner reichen Huld erhöre mich, o Gott, durch Deine treue Hilfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Befrei mich aus dem Schlamm, daß ich nicht sinke! Daß ich befreit von meinen Hassern werde, aus der Wassertiefe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Die Flut laß nicht mich überströmen und nicht die Tiefe mich verschlingen! Der Brunnen schließe seinen Schlund nicht über mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Erhör mich, Herr, nach Deiner Huld, der köstlichen! Und wende Dich mir zu nach Deiner reichen Liebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Verhüll Dein Angesicht vor Deinem Knechte nicht! Mir ist so bang. Erhör mich eilends!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Herbei zu meiner Seele! Sie erlöse! Um meiner Feinde willen rette mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du kennst ja meine Schmach und Schande und meinen Schimpf bei allen meinen Drängern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Die Schmach bricht mir das Herz, ich bin verzweifelt. Auf Mitleid hoffe ich, jedoch umsonst, auf Tröster, doch ich finde keinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Sie mischen Galle mir ins Essen und geben Essig mir für meinen Durst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Daß ihre Tafel ihnen eine Falle werde, für sie zur Schlinge ihr Gelage!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Daß ihre Augen finster werden und nichts sehen mehr! Laß ihre Hüften wanken immerdar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Gieß Deinen Grimm doch über sie, und Deine Zornglut packe sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Verödet sei ihr Lager und ihre Zelte unbewohnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Denn sie verfolgen, den Du schlägst, und fügen zu dem Schmerze Deiner Wunden neuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Schuld füg zu ihrer Schuld hinzu, daß sie nicht schuldlos vor Dir werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Sie seien aus dem Buch der Lebenden getilgt, nicht aufgezeichnet mit den Frommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Mich, der ich arm und leidend bin, beglücke Deine Hilfe, Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'In Liedern preise ich den Namen Gottes und ehre ihn gar hoch durch Lobgesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Denn dies gefällt dem Herrn viel mehr als Rinder, mehr als gehörnte und behufte Stiere:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Schaut her, ihr frommen Dulder! Und werdet froh, ihr Gottessucher! Und euer Herz leb wieder auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Der Herr erhört die Armen, verschmäht die Seinen nicht in Banden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Der Himmel und die Erde preise ihn, das Meer und alles, was darin sich regt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Denn Gott hilft Sion wieder auf; läßt Judas Städte wiederum ersteh\'n als Wohnstatt und als Erbe. Und seiner Diener Stamm nimmt\'s in Besitz: Die seinen Namen lieben, wohnen drin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Auf den Siegesspender, von David, zum Erlernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Gott, eile, mich zu retten, Herr, mir zu helfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Beschämt und schamrot sollen werden die Feinde meines Lebens! Mit Schmach bedeckt die Flucht ergreifen all, die mir übel wollen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Und auf der Seele sollen ihre Schande tragen, die höhnisch rufen \"Ha! Ha!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Doch jubeln sollen über Dich, vor Freude alle, die Dich suchen! Und allzeit sollen rufen: \"Gott ist groß\", die Deinen Sieg sich wünschen! Doch ich bin arm und elend. Gott, eiligst her zu mir! Du bist mein Schutz und Retter. Herr, säume nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Auf Dich, Herr, hoffe ich. Laß nimmer mich zuschanden werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Errette mich nach Deiner Liebe! Du befreie mich! Und neig zu mir Dein Ohr! Errette mich!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sei mir doch eine Felsenburg, in die ich jederzeit zu meinem Heile kommen darf. Mein Fels und meine Burg bist Du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mein Gott! Befrei mich aus der Hand des Frevlers und aus der Faust des Ungerechten und Bedrückers!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Du meine Hoffnung, Herr, Du meine Zuversicht von Jugend an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Vom Mutterschoß an hab ich mich auf Dich verlassen, vom Mutterleibe her bist Du mir Stütze. Auf Dir hat immer meine Zuversicht beruht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Als Wunder galt ich vielen; solch großer Schutz bist Du für mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Mein Mund ist Deines Ruhmes voll, alltäglich Deines Preises.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Verwirf mich nun im Alter nicht! Verlaß mich nicht beim Schwinden meiner Kräfte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Denn meine Feinde reden über mich; die auf mein Leben lauem, halten Rat zumal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Sie sagen: \"Gott hat ihn verlassen. Verfolgt ihn! Greift ihn! Nirgends ist ein Retter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Gott, sei nicht ferne mir! Mein Gott, zur Hilfe eile mir herbei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'In Scham vergehen mögen meiner Seele Feinde! Mit Schimpf und Schmach bedeckt sein, die mein Unglück suchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ich aber harre immerdar und mehre Deinen Ruhm nach allen Seiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mein Mund soll Deine Liebe künden und den ganzen Tag Dein Heil. Wenn ich geschickt im Schildern wäre');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'und ich erreichte, Herr, das höchste Alter, ich wollte Deine Liebe, Herr, nur schildern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Du lehrtest mich\'s in meiner Jugend, Gott, und bis zur Stunde künd\' ich Deine Wunder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Nun, so verlaß mich auch im Alter nicht, Gott, nicht im Greisenalter, daß ich der Nachwelt Deine Kraft, der ganzen Zukunft Deine Macht verkünde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'In Deiner Liebe, Gott, so hoch, in der Du Großes tust, wer gleicht Dir, Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Der Du viel Not und Leid mich fühlen ließest, Du lässest wiederum mich aufleben und führst mich aus der Erde Schlünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du machst mir meine Buße groß und tröstest mich dann wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Ich preise alsdann Deine Treue mit Harfenspiel, mein Gott. Ich spiele auf der Zither Dir, Du Heiliger Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Wenn ich Dir singe, jubeln meine Lippen und meine Seele, die Du rettest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Auch meine Zunge spricht von Deiner Liebe immerfort; denn tief beschämt zuschanden werden, die mein Verderben suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Von Salomo. - Gott, gib dem König Deine Ordnungen, dem Königssohn Dein Recht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'daß er Dein Volk gemäß dem Rechte richte und Deine Armen nach Gerechtigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Die Berge laß dem Volke Frieden bringen, Gerechtigkeit die Hügel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Er schaffe Recht den Elenden im Volk und helfe armer Leute Kindern! Doch den Bedrücker möge er zermalmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Er lebe auch, solange Mond und Sonne währen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Er komme wie der Regen auf die abgemähte Flur, wie Regengüsse auf das Land!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'In seinen Tagen blühe auf der Fromme, und Friedensfülle sei, bis nimmer ist der Mond!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Von Meer zu Meere herrsche er, vom Strom bis an der Erde Enden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Seemächte sollen sich vor ihm erniedrigen und seine Feinde Staub auflecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Die Könige von Tarsis und die der Inseln sollen Gaben bringen, Tribut die Könige von Saba und von Seba');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'und alle Könige ihm huldigen! Ihm sollen alle Heidenvölker dienstbar sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Den Armen rettet er, wenn er um Hilfe ruft, den Leidenden, der keinen Beistand hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Er schont den Armen und Geringen und rettet der Bedrückten Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Von Schaden und Gewalt erlöst er ihre Seele; denn teuer achtet er ihr Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Man rufe alsdann \"Lebe hoch!\" Er gibt dafür von Sabas Golde, damit für ihn bete, ihn beständig segne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Er sei ein Fruchtgefilde auf der Erde! Auf Bergesgipfeln, gleich dem Libanon, da woge auch noch seine Frucht! Sie sprosse aus der Stadt wie Pflanzen aus der Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sein Name währe ewiglich! Solange eine Sonne ist, so währe auch sein Name! Daß alle Heiden ihn beim Segnen nennen und glücklich preisen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Gepriesen sei der Herr und Gott, der Schutzgott Israels, der einzig Wunder tut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Gepriesen sei der Name seines Herrschertums in Ewigkeit! Die ganze Erde sei erfüllt von seiner Herrlichkeit! Amen! Amen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Zu Ende sind die Gebete Davids, des Isaisohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein Lied, von Asaph. - Gewiß! Das höchste Gut für Israel ist Gott, für die, die reinen Herzens sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ich wäre fast mit meinem Fuß gestrauchelt; fast hätte einen Fehltritt ich getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Denn ich beneidete die Übermütigen und gaffte bei der Frevler Wohlergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Denn ihre Sklaven brauchen keine Fesseln, und kerngesund ist ihr Gesinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Sie teilen nicht der Menschen Leid und werden nicht wie andere geplagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Drum ist ihr Halsgeschmeide Übermut; Gewalttat heißt das Kleid, das sie umhüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Ihr Auge quillt aus Fett hervor; ausschweifend sind des Herzens Süchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Sie reden boshaft, voller Hohn, und drohen mit Gewalt von oben her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Mit ihrem Munde tasten sie den Himmel an, und ihre Zunge herrscht durchs ganze Land-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, '\"Fürwahr! Dahin hat er sein Volk gebracht, daß sie nicht Wasser zur Genüge fanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Sie sprechen: \"Ach, wie weiß denn Gott? Gibt\'s denn ein Wissen bei dem Höchsten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Ja, diese sind so frevelhaft und glücklich in der Welt, vermehren sie ihr Hab und Gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'So hielt ich denn vergeblich rein mein Herz und wusch in Unschuld meine Hände?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Den ganzen Tag bin ich geplagt, und meine Züchtigung ist jeden Morgen da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Nähm ich mir aber vor, also zu sprechen: \"So geht es dem Geschlechte Deiner Kinder\", so wär\'s von mir vermessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Wenn ich\'s nachsinnend will verstehen, da wird\'s in meinen Augen erst ein Jammer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'bis ich in Gottes heilige Pläne dringe. Da erst begreife ich ihr Ziel:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Du stellst sie auf gar schlüpferigen Boden, daß Du sie ins Verderben stürzest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie plötzlich gehen sie zugrunde! Wie schrecklich werden sie dahingerafft, vertilgt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie beim Erwachen einen Traum der Wachende verachtet, so tust Du\'s, Herr, mit ihrem Schatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Wenn voll von Bitternis das Herz mir wäre, und schnitte durch die Nieren mir der Schmerz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'dann wäre ich ein Tier, ganz unverständig, ein unvernünftig Tier vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Doch immer bleibe ich Dir treu, wenn Du mich bei der Rechten fassest');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'und leitest mich nach Deinem Rat und nimmst zuletzt mich noch zu Besserm mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wen habe ich im Himmel? Und wenn ich Dich besitze, brauche ich auf dieser Welt nichts mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Vergeht mein Fleisch, mein Herz, so bleibt doch meines Herzens Hort, mein Anteil Gott in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Wer sich von Dir entfernt, kommt um. Jedweden tilgst Du, der Dir Treue kündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Für mich ist\'s Seligkeit, mich Gott zu nahen. Ich setze meine Hoffnung auf den Herrn, den Herrn, daß ich verkünden kann, was immer Du verheißen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Ein Lehrgedicht, von Asaph. - Warum, ach Gott, verwirfst Du immerfort und lodert über Deiner Herde Deines Zornes Rauch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Bedenke: Die Gemeinde, die Du einst gegründet, die Du Dir ausgelöst zum Stamme ewigen Besitzes, der Sionsberg, auf dem Du Wohnung nahmst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'den Deine Schritte ausgezeichnet, sind zusammen eine Trümmerstatt! Gar alles hat der Feind im Heiligtum geschändet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'In Deiner Sammlungsstätte wüten Deine Feinde; sie stellen ihre Flaggen dort als Zeichen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'So ist\'s, wie wenn man hohen Schwunges auf Waldgehölz die Äxte hebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Und nun sein Schnitzwerk allzumal zerschlagen sie mit Beil und Hammer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Sie werfen Feuer in Dein Heiligtum, entweihen in den Staub die Wohnung Deines Namens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'In ihrem Herzen sprechen sie: \"Wir wollen alle sie zu Heiden machen.\" Im Land verbrennen sie die Gotteshäuser all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Wir sehen unsere Zeichen nimmer; und Propheten gibt es keine mehr, und niemand weiß bei uns: Wie lange?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Wie lange darf der Feind noch höhnen, der Gegner Deinen Namen immerfort verlästern, Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Warum entziehst Du Deine rechte Hand dem Kampfe? Vollbringe doch, was Dir obliegt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Von altersher ist Gott mein König, der auf der Erde hilfereiche Werke tut. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'In Deiner Macht zerteilst Du ja das Meer, zerbrichst die Drachenköpfe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'zerschlägst des Leviatans Häupter und gibst ihn hin der Wüstentiere Schar zum Fraße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du lässest Bach und Quelle sprudeln und starke Ströme Du versiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Dein ist der Tag; Dein ist die Nacht. Genau bemißt Du Mond und Sonne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du stellst der Erde Grenzen alle fest; Du schaffst den Sommer und den Winter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Gedenke dessen, daß der Feind, Herr, höhnt, daß Deinen Namen lästert ein törichtes Volk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nicht gib dem Habicht Deiner Taube Leben preis! Vergiß nicht gänzlich Deiner Dulder Menge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Blick auf den Bund! Das Land ist voller Lug und Trug, die Wohnungen sind voll Gewalttat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Nicht ziehe der Bedrängte voller Scham dahin, der Arme nicht, der Elende, der Deinen Namen preist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Auf, Gott! Führ Deine Sache! Der Schmach gedenke, die von Toren allezeit Dir widerfährt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Vergiß den Aufruhr Deiner Feinde nicht, das Toben Deiner Gegner nicht, das immer lauter wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Auf den Siegesspender, ein Kunstgesang; ein Lied, von Asaph, ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Wir danken, Gott; wir danken Dir. Die Deinem Namen nahestehen, künden Deine Wundertaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '\"Wenn ich mir auch schon Zeit vergönne, ich richte dennoch nach dem Rechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Wenn auch die Erde bebt und was drauf wohnt, ich stelle ihre Pfeiler wieder fest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ich spreche zu den Rasenden: \'Rast nicht!\' und zu den Frevlern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, '\'Pocht nicht auf eure Stärke!\' - Pocht nicht so stark auf eure Stärke, und redet nicht aus frecher Kehle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Denn nicht von Ost und nicht von West, nicht von der Wüste her kommt Widerstand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'wenn Gott sich zum Gericht erhebt und hier erniedrigt, dort erhöht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Der Herr hat einen Becher in der Hand, voll stark gewürzten Weines. Er schenkt ihn aus; der Erde Frevler alle müssen trinken und die Hefe selbst noch schlürfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ich aber juble immerdar und preise Jakobs Gott. Der Frevler Macht zerbreche ich vollständig, auf daß der Frommen Macht sich hebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Auf den Siegesspender, mit Zithern, ein Lied, von Asaph, ein Gesang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Berühmt ist Juda Gottes wegen, und wegen Israels ist groß sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Zu Salem sein Gezelt, in Sion seine Thronstadt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Des Bogens Blitze ließ er hier zusammenbrechen, Schild, Schwert und andere Kriegerwaffen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Du bist so herrlich und so schrecklich auf zweigbedeckten Bergen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Zur Beute fielen Mutige, als ob sie schliefen, und all die tapferen Krieger fanden keine Kräfte mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Vor Deinem Drohen, Jakobs Gott, da werden die zu Wagen und zu Roß betäubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du bist so furchtbar, Du. Zürnst Du, wer kann vor Dir bestehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Vom Himmel lässest Du Vergeltung künden; die Erde staunt und schweigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'wenn Du Dich zum Gericht erhebst, o Gott, zu helfen allen Duldern in dem Lande. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Dich preist der Menschen Menge; der Massen Rest hüllt sich in Bußgewänder. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Gelobet nur und löst es ein, dem Herren, eurem Gott! Wer immer um ihn ist, soll Gaben ihm, dem Furchtbaren, darbringen. Er bricht der Fürsten Übermut, und fürchterlich ist er den Königen der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Auf den Siegesspender, für Zurückgezogene, von Asaph, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Zu Gott erheb ich meiner Klage Stimme, zu Gott nur meine Stimme: \"Du, mein Gott! Horch auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'In meiner Notzeit suche ich den Herrn; mein Ringen währt ohn\' Ende in der Nacht, und meine Seele läßt sich nimmer trösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Wenn Gottes ich gedenke, muß ich seufzen. Und überlege ich, verzagt mein Geist. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Die Augenlider bannst Du mir; verstört bin ich und ohne Sprache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ich überdenke alte Tage, die Jahre der Vergangenheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Bedenke ich des Nachts mein Leiden, erwäge ich\'s in meinem Sinn, dann forscht mein Geist:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, '\"Verstößt der Herr denn ewiglich? Ist er denn niemals wieder gnädig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Hat seine Huld für immer aufgehört? Hat die Verheißung ganz und gar ein Ende?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hat Gott das Gnädigsein verlernt? Hält er erzürnt sein Mitleid auf?\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Da sag ich mir: \"Das ist mein Kummer, daß sich geändert hat des Höchsten Rechte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Ich bin der Werke eingedenk des Herrn, betrachte jetzt Dein Wunderwalten in der Vorzeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'und überlege all Dein Tun und sinne Deinen Taten nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Dein Weg ist heilig, Gott. Wer ist ein Gott, so groß wie Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du bist der Gott, der Wunder tut. So offenbare an den Völkern Deine Macht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Erlös mit Macht Dein Volk, des Jakob und des Joseph Söhne. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Die Wasser seh\'n Dich, Gott. Die Wasser sehen Dich und beben; selbst Meerestiefen zittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Ausströmen Wolken Wasser, und das Gewölke donnert, es fliegen Deine Pfeile hin und her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Zu Deinem Donner, rollend, krachend, leuchten Deine Blitze. Der Erdkreis zittert und die Erde bebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Dein Weg geht durch das Meer, Dein Pfad durch große Wasser, doch unkenntlich ist Deine Spur. Du führst Dein Volk gleich einer Herde an Mosis und an Aarons Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Ein Lehrgedicht, von Asaph. - Mein Volk! Hab acht auf meine Lehre! Zu meines Mundes Reden neiget euer Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Ich öffne meinen Mund zu einem Spruch. Ich künd Gesänge aus der Vorzeit Tagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'die wir vernommen und jetzt wissen, die unsre Väter uns erzählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Wir, ihre Kinder, wollen über sie nicht schweigen. Wir wollen künftigem Geschlecht des Herren Ruhmestaten künden und seine Macht und Wunder, die er tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Zum Brauch hat er\'s in Jakob eingesetzt, zur heiligen Pflicht in Israel gemacht. Denn unsern Vätern hat er anbefohlen, sie ihren Kindern kundzutun,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'auf daß ein späteres Geschlecht sie kenne, die Enkel, die geboren würden, sie ihren Kindern wiederum verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Sie sollten Gott vertrauen und nicht vergessen Gottes Taten und seine Vorschriften befolgen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'und nicht, wie ihre Väter, werden ein widerspenstig, trotziges Geschlecht, solch ein Geschlecht von wankendem Gemüt und ungetreuem Herzen gegen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Ganz unvernünftige Söhne, voller Trug, das Leben werfen sie hinweg und wenden sich am Trübsalstage ab;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'sie halten Gottes Bündnis nicht und wollen nicht nach seiner Lehre wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Und sie vergessen seine Werke gänzlich und seine Wunder, die er ihnen zeigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Vor ihren Vätern tat er Unvergleichliches, im Land Ägypten, im Gefild von Tanis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Er spaltete das Meer und führte sie hindurch und ließ das Wasser dammgleich stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Er leitete bei Tag sie mit der Wolke, die ganze Nacht mit Feuerschein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'und ließ die Felsen in der Wüste sprudeln und tränkte sie in Fülle wie mit Fluten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Aus Steinen ließ er Bäche quellen, wie Ströme Wasser sprudeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Allein sie sündigten noch weiter gegen ihn und widersetzten sich dem Höchsten in der Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Und sie versuchten Gott in ihrem Herzen, für ihre Gelüste Speise heischend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Sie sprachen gegen Gott und fragten: \"Vermag es Gott, selbst in der Wüste einen Tisch zu decken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Den Felsen schlug er zwar; das Wasser floß, die Bäche strömten. Vermag er aber Brot zu geben und seinem Volke Fleisch zu spenden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Der Herr vernahm\'s und wurde zornig; ein Feuer loderte in Jakob auf; ein Zorn erhob sich gegen Israel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'weil sie an Gott nicht glaubten und nicht auf seine Hilfe bauten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Doch er gebot den Wolken oben und tat des Himmels Pforten auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'hernieder ließ er Manna auf sie regnen, um sie zu speisen, schenkte ihnen Himmelsbrot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Das Brot der Engel konnte jeder essen; er sandte ihnen Kost in Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Er ließ den Morgenwind am Himmel wehen; den Südwind führte er durch seine Macht herbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Dann ließ er Fleisch wie Staub auf sie herniederregnen, wie Meeressand Geflügel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Er ließ es in ihr Lager fallen, um seine Wohnstatt ringsumher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Sie aßen, wurden übersatt; was sie gewünscht, verlieh er ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Noch war nicht ihre Lust gestillt, noch war die Kost in ihrem Munde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'als Gottes Zorn sich gegen sie erhob, die Feisten unter ihnen würgte, die junge Mannschaft Israels zu Boden streckte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Bei all dem sündigten sie weiter und glaubten nicht an seine Wunderkräfte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Da ließ er ihre Tage zwecklos schwinden und ihre Jahre in Enttäuschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Zwar fragten sie nach ihm, wenn er sie würgte, verlangten wiederum nach Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'wohl eingedenk, daß Gott ihr Hort, der höchste Gott ihr Retter sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Allein sie täuschten ihn mit ihrem Munde, belogen ihn mit ihrer Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Ihr Herz war unaufrichtig gegen ihn; mit seinem Bunde meinten sie\'s nicht ehrlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Doch er, erbarmungsvoll, vergab die Schuld, vertilgte nicht; oft hielt er seinen Zorn zurück und ließ nicht seinen Grimm austoben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'wohl eingedenk, daß sie nur Fleisch, ein Windhauch, der verschwindet ohne Wiederkehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Wie oft erzürnten sie ihn in der Wüste und reizten ihn im Steppenland,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'versuchten immer wieder Gott, erbitterten die Heiligen Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'gedachten nimmer seiner Macht, des Tages, da er vor dem Feinde sie gerettet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'wie er vor den Ägyptern seine Zeichen tat, an dem Gefild von Tanis seine Wunder:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'In Blut verwandelte er ihre Ströme; untrinkbar ward ihr fließend Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Er sandte Ungeziefer unter sie, das sie verzehrte, und Frösche ihnen zum Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Der Raupe gab er ihre Früchte preis und ihre Arbeit der Heuschrecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Er schlug mit Hagel ihren Weinstock und ihren Maulbeerbaum durch Reif.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Er gab ihr Vieh dem Hagel preis, den Blitzen ihre Herden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Er ließ die Hitze seines Zornes auf sie los, nur Grimm und Wut und Angst, von Unglücksboten eine Schar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'So ließ er seinem Zorne freien Lauf, verschonte ihre Seele mit dem Tode nicht. Er gab der Pest ihr Leben preis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'und in Ägypten schlug er alle Erstgeburt, die Jugendblüte in den Zelten Chams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Er führte, Schäflein gleich, sein Volk heraus und lenkte sie wie in der Steppe eine Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Er leitete sie sicher, daß sie nichts zu fürchten hatten; das Meer bedeckte ihre Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Er brachte sie zu seinem heiligen Gebiete, zu jenem Berg, den seine Rechte sich erworben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'vertrieb vor ihnen weg die Heiden, verloste sie als erblichen Besitz und ließ die Stämme Israels in ihren Zelten wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Und doch versuchten sie und reizten Gott, den Höchsten, und hielten nimmer seine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Wie ihre Väter wichen sie und fielen ab; sie wurden wie ein schlaffer Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Sie reizten ihn zum Zorn durch ihre Höhen, zur Eifersucht durch ihre Götzenbilder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Gott hörte dies und wurde zornig, und Israel verwarf er völlig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'verließ zu Silo seinen Sitz, das Zelt, in dein er unter Menschen wohnte;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'gab seine Ehre in Gefangenschaft und seine Zier in Feindeshand');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'und gab sein Volk dem Schwerte preis, entrüstet über dies sein Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Die jungen Männer fraß das Feuer, und seine Jungfraun durften keine Totenklage halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Hinfielen seine Priester durch das Schwert, und seine Witwen weinten nicht dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Doch wie vom Schlaf erwachte da der Herr, gleichwie ein Held vom Weine jauchzend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Im Rücken schlug er seine Feinde, belegte sie mit ewigem Schimpf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Doch er verschmähte Josephs Zelt; den Stamm von Ephraim erkor er nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Vielmehr erkor er Judas Stamm, den Sionsberg, der ihm so lieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Er baute Himmelshöhen gleich sein Heiligtum und gleich der Erde, die er ewig gründete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Und er erkor sich David, seinen Knecht, entriß ihn seiner Herde Hürden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Vom Milchvieh nahm er ihn hinweg, sein Volk zu weiden in Jakob, in Israel die ewig Seinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Mit frommem Sinne weidete er sie und führte sie mit kluger Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Ein Lied, von Asaph. - Gott! Heiden dringen in Dein Eigentum, entweihen Deinen heiligen Tempel. Jerusalem verwandeln sie in Trümmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Sie geben Deiner Knechte Leichen hin zum Fraß den Vögeln unterm Himmel und Deiner Frommen Fleisch den wilden Tieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Ihr Blut vergießen sie wie Wasser her um Jerusalem; man läßt sie unbegraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Zum Hohne sind wir unsern Nachbarn, zum Spott und Schimpf für unsere Umgebung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Wie lange zürnst Du, Herr, ohn Unterlaß und brennt dem Feuer gleich Dein Eifer?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Gieß Deinen Grimm auf diese Heiden aus, die Dich nicht kennen, und auf die Reiche, die nicht rufen Deinen Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Denn sie verschlingen Jakob und machen wüste seine Wohnungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Der Ahnen Sündenschulden rechne uns nicht an! Schnell komme Dein Erbarmen uns entgegen! Denn wir sind ganz erschöpft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Gott unseres Heils, komm uns zu Hilfe, um Deines Namens Ehre! Befreie uns! Vergib uns unsere Sünden Deines Namens wegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Was sollten doch die Heiden sagen: \"Wo bleibt denn ihr Gott?\" Er zeige sich vor unsern Augen an den Heiden! Das sei die Rache jetzt für Deiner Knechte ausgegossen Blut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Das Stöhnen der Gefangenen laß zu Dir dringen! Durch Deinen starken Arm befrei des Todes Kinder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Gib unsern Nachbarn siebenfach die Schmach zurück, mit der sie, Herr, Dich lästern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Dann wollen wir, Dein Volk, die Schäflein Deiner Weide, Dir ewig dankbar sein und künden für und für Dein Lob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Auf den Siegesspender, für den öffentlichen Gottesdienst, ein Vortrag, von Asaph, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Horch auf, Du Hirte Israels, der Du die Herde Josephs leitest und thronest über Cherubim! Erscheine!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Vor Ephraim, Manasse, Benjamin entfalte Deine Macht! Komm uns zu Hilfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Bereit uns Heimkehr, Gott, Dein Angesicht laß leuchten, damit Heil uns werde! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Herr, Gott der Heeresscharen! Wie lange zürnst Du trotz dem Flehen Deines Volkes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du speisest sie mit Tränenbrot und schenkst nur kärglich Maß in Tränen ihnen ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Du gibst uns preis der Spottsucht unserer Nachbarn, und unsere Feinde spotten unter sich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Herr, Gott der Heeresscharen! Führ uns heim und laß Dein Antlitz leuchten, auf daß Heil uns werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Du hobst Dir aus Ägypten einen Weinstock aus, vertriebest Heiden, pflanztest ihn an ihre Stätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Du gabst ihm Raum, so daß er Wurzeln schlug und sich im Lande dehnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Sein Schatten deckte Berge und sein Gezweig die Zedern Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Er dehnte seine Ranken bis ans Meer und seine Schößlinge bis zu dem Strom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Warum reißt Du jetzt seine Zäune ein, daß ihn zerpflückt, was da vorüberzieht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Des Waldes Eber wühlt ihn durch; abweidet ihn das Wildschwein. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Halt ein, Du Gott der Heeresscharen! Blick nieder aus dem Himmel, sieh! Nach Deinem Weinstock schau!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Will sagen: nach dem Sprößlinge, den Deine Rechte eingepflanzt, und nach dem Sohn, den Du Dir aufgezogen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Er ist vom Feuer ganz verbrannt, zerwühlt; vom Dräuen Deines Angesichts kam das Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Auf diesem Manne ruhe Deine Hand und Deine Rechte auf dem Menschensohn, den Du Dir aufgezogen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Wir lassen nimmermehr von Dir. Erhalte uns am Leben! Und wir lobpreisen Deinen Namen. Herr, Gott der Heeresscharen! Bereit uns Heimkehr und laß Dein Antlitz leuchten, auf daß Heil uns werde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Auf den Siegesspender, beim Kelternfest, von Asaph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Zujubelt unserer Stärke: Gott! Jauchzt Jakobs Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Erschallen lasset Pauken und Gesang, klangvolle Zithern samt den Harfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Am Neumond schmettert in das Horn, am Vollmond zu der Feier unsres Festes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Denn Satzung ist\'s für Israel, für Jakobs Zelte ein Gesetz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'In Joseph macht er\'s zum Gebrauch. Bei seinem Feldzug nach Ägypten hört ich Worte, wie ich sie nie erfahren:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '\"Von seiner Schulter habe ich die Last genommen; des Lastkorbs ledig wurden seine Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Du riefst in Not, und ich befreite dich und hörte in der Donnerhülle dich und prüfte dich am Haderwasser.\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '\"Mein Volk! Horch auf! Ich mahne dich. Gehorchst du mir, mein Israel, in folgendem:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Kein fremder Gott sei je bei dir! Du darfst nicht einen Auslandsgott anbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ich bin dein Gott, der Herr, der aus Ägypterlande dich geführt, dann öffne deinen Mund, daß ich ihn fülle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Doch hört mein Volk auf meine Stimme nicht, und ist mir Israel nicht willig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'dann laß ich sie in ihrem Starrsinn nach ihrer Willkür wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Ach, möchte mir mein Volk gehorchen und Israel in meinen Wegen wandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Wie wollte bald ich ihre Feinde beugen und meine Hand an ihre Gegner wieder legen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Des Herren Hasser müßten sich auf seine Seite schlagen, und ihr Verhängnis währte ewig! Er würde es mit feinstem Weizen speisen. \"Mit Honig aus dem Felsen würde ich dich sättigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein Lied, von Asaph. - Zum Gottesrat begibt sich Gott, Gericht bei Göttern abzuhalten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '\"Wie lange wollt ihr noch das Recht verdrehen, für Schuldige Partei ergreifen? (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Den Armen und den Waisen schaffet Recht! Verteidigt den Geringen und den Dürftigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Errettet Niedrige und Arme! Befreit sie aus der Frevler Hand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Sie achten\'s nicht, verständnislos; im Finstern wandeln sie umher; des Landes Stützen wanken all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Ich habe zwar gesprochen: \"Ihr seid Götter, ihr des Höchsten Söhne all.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Jedoch wie andere Menschen sollt ihr sterben, wie andere Fürsten niedersinken!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Auf, Gott! Der Erde halte ihr Gericht! Du bist der Erbherr aller Heidenvölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein Gesang, ein Lied, von Asaph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Gott, sei nicht still! Schweig nicht! Bleib nicht so ruhig, Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Denn siehe, Deine Feinde sind geschäftig; das Haupt erheben Deine Hasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Sie halten, Deinem Volk zuwider, listig Rat, beraten gegen Deine Schutzbefohlenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Sie sprechen: \"Auf, wir wollen sie als Volk vernichten. Nie werde mehr des Namen Israels gedacht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Einmütig halten Rat und schließen gegen Dich ein Bündnis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Edoms und Ismaels Gezelte, Moabs und die der Agarener,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal, Ammon und Amalek, Philisterland und Tyrier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Auch Assur schließt sich ihnen an; sie leihen ihren Arm den Söhnen Lots. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Behandle sie wie Midian, wie Sisara, wie Jabin an dem Kisonsbach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Zu Endor wurden sie vertilgt; sie wurden Dünger für das Ackerfeld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Tu ihren Edlen wie Oreb und Zeeb, wie Zeba und Salmunna, allen ihren Fürsten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Sie sprechen: \"Lasset Gottes Auen uns erobern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Mein Gott! Mach sie dem Wirbellaube gleich, den Stoppeln vor dem Winde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Wie Feuer, das den Wald verzehrt, wie Flammen, Berge sengend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'jag ihnen nach mit Deinem Wetter! Und schreckt sie mit Deinem Sturme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Füll an ihr Angesicht mit Schmach, auf daß sie Deinen Namen fürchten, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Sie sollen schämen sich, für immerdar verwirrt, mit Schanden untergehen! Dann merken sie, daß Du mit Deinem Namen heißest');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Auf den Siegesspender, zum Kelternfest, von den Korachiten, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Wie lieblich ist doch Deine Wohnung, Herr der Heeresscharen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Mein Geist verlangt und schmachtet hin nach den Vorhöfen des Herrn; mit Leib und Seele rufe ich nach dem lebendigen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Gesichert hat der Vogel eine Stätte sich, ein Nest die Schwalbe, wenn diese ihre Jungen birgt bei Deinem Altar, Du Herr der Heeresscharen, mein König und mein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Wie selig, die in Deinem Hause weilen, die immerfort Dich preisen dürfen! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Wie selig, der in Dir die Stärke findet, wenn eine Pilgerfahrt er plant,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'der, durch das Tränental hinpilgernd, es macht zu einem Quellort, zu Teichen, wie sie sonst der frühe Regen füllt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'der, alle Kraft zusammennehmend, wallt, bis er vor Gott in Sion kann erscheinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Herr, der Heerscharen Gott! Erhöre mein Gebet! Vernimm es, Jakobs Gott! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Schau her, o Gott, Du unser Schild! Blick auf den Mann, den Du gesalbt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Weit besser ist ein Tag in Deinen Höfen als tausend andere. In meines Gottes Hause stehe ich viel lieber an der Schwelle, als daß ich in des Frevels Zelten weilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Denn Schar und Schild ist Gott der Herr, und Ruhm und Ehre gibt der Herr. Er geizt bei denen, die in Unschuld wandeln, nimmer mit seinem Segen. Herr der Heerscharen, wie selig ist, wer Dir vertraut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Auf den Siegesspender, von den Korachiten, ein Lied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Du hast Dein Land begnadet, Herr, und Jakobs Schicksal umgewandelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'vergeben Deines Volkes Schuld, bedeckt all ihr Vergehen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Du zogst all Deinen Grimm zurück und dämpftest Deine Zornesglut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Du, unser hilfereicher Gott, geh weiterhin mit uns! Und tilge vollends Deinen Unmut wider uns!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Willst Du denn ewig auf uns zürnen, auf alle Zeiten Deinen Zorn ausdehnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Willst Du uns nicht aufs neu beleben, auf daß Dein Volk sich Deiner freue?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Erzeig uns Deine Gnade, Herr! Gewähre uns Dein Heil! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ich möchte hören, was der Herr verheißt: Er spricht von Frieden für sein Volk und seine Frommen, für die, die umkehren, von Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Schon naht sein Heil sich denen, die ihn fürchten, auf daß die Herrlichkeit in unserm Lande wieder wohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Dann finden sich die Liebe und die Treue; Gerechtigkeit und Frieden küssen sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Die Treue reckt auf Erden sich, und die Gerechtigkeit neigt sich vom Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Der Herr beschert alsdann den Segen, und unser Land gibt seine volle Ernte wieder. Gerechtigkeit geht vor ihm her, und auf dem Wege seiner Schritte ist Geradheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Ein Gebet, von David. - Dein Ohr, Herr, neige! Höre mich! Denn ich bin elend und geplagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Beachte mich, wie treu ich bin! Zu Hilfe Deinem Knecht, der auf Dich hofft, mein Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Herr! Sei mir gnädig! Denn täglich rufe ich zu Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Erfülle Deines Dieners Wunsch! Denn meinen Wunsch, Herr, richte ich auf Dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Du bist so gütig, Herr, versöhnlich und gegen jeden, der Dich anruft, liebevoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Herr, merk auf mein Gebet! Und hör mein lautes Flehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'In meiner Notzeit rufe ich zu Dir, daß Du mich hörest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Der Götter keiner gleicht Dir, Herr, nichts Deinen Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Die Heiden alle, die Du schufest, kommen und werfen sich vor Dir, Herr, nieder, und geben Deinem Namen Ehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Denn Du bist groß und Wunder wirkend, Du, Gott allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Herr! Weis mich Deinen Weg, daß in der Treue gegen Dich ich wandle! Mit Deines Namens Furcht vereine sich mein Herz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Ich will Dir danken, Herr, mein Gott, von ganzem Herzen und Deinen Namen ewig ehren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'errettest Du, großherzig gegen mich, mein Leben aus der tiefsten Hölle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Gott! Gegen mich stehn Übermütige auf; mir trachtet nach dem Leben eine Räuberrotte; sie stellt Dich nicht vor ihre Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Du aber, Herr, bist ein barmherziger und gnädiger Gott, langmütig, huldreich, treu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wend voll Erbarmen Dich mir zu! Und leihe Deinem Diener Deinen Schutz, und hilf dem Sohne Deiner Magd!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tu mir zum Heil ein Zeichen: daß meine Hasser mit Beschämung sehen, wie Du mein Helfer bist, mein Tröster, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Von den Korachiten, ein Lied, ein Gesang. - Was er auf heiligen Bergen hat gegründet');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'das liebt der Herr; die Sionstore mehr als alle andern Wohnungen Jakobs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Von dir ist Herrliches zu künden, du Gottesstadt. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Erwähne ich auch Rahab und auch Babel wegen ihrer Weisen, Philisterland und Tyrus und Äthiopien: \"Es ist dort der geboren\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'so wird von Sion ausgesagt: \"Darin ist Mann um Mann geboren.\" Das sichert ihm den höchsten Rang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Der Herr ist\'s, der bestätigt, zeichnet er die Völker auf: \"Es ist der dort geboren.\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'So singt und tanzt, wer immer in dir wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein Gesang, ein Lied, von den Korachiten, auf den Siegesspender, eine Zugabe, bei Bußübungen, ein Lehrgedicht, von Heman, dem Ezrachiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Du meines Heiles Gott, o Herr! Ich rufe Tag und Nacht zu Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Es komme mein Gebet vor Dich! Und neige meinem Fleh\'n Dein Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Denn meine Seele ist von Leiden voll gesättigt; der Unterwelt naht sich mein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Zu denen, die zur Grube fahren, zählt man mich; ich gleiche einem Manne ohne Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Wie Tote bin ich, bloß von allem, wie die Verblichenen, die im Grabe liegen, und deren Du nicht mehr gedenkst, und die Dir fernestehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du stößt mich in die tiefste Grube, in Finsternis, in große Tiefen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Dein Grimm liegt schwer auf mir; und Deine Fluten führst Du her. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Und Du entfremdest mir die Freunde; zum Ekel machst Du mich für sie. Ich liege eingekerkert und darf nimmer ausgehn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Matt ist mein Auge mir vom Leiden. Ich rufe täglich, Herr, Dich an und breite meine Hände nach Dir aus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, '\"Wirst Du an Taten Wunder tun? Und stehen Schatten auf, Dir Dank zu sagen? (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Rühmt man im Grabe Deine Liebe und Deine Treue in der Unterwelt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Wird in der Finsternis Dein unvergleichlich Wesen kundgetan und Deine Liebe in dem Lande der Vergessenheit?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'So schreie ich, o Herr, zu Dir; vor Dich dringt in der Frühe mein Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Warum verschmähst Du meine Seele, Herr, verbirgst vor mir Dein Angesicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'So elend bin ich, von der Jugendzeit an sterbend, und wortlos Deine Schrecken tragend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Mich überfallen Deine Zornesgluten, und Deine Schrecknisse vernichten mich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'umfluten täglich mich wie Wasser, umschließen mich zumal. Du nimmst mir meine Freunde und Gefährten weg, und meine Liebsten sind entschwunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Ein Lehrgedicht, von Ethan, dem Ezrachiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Ich singe von des Herrn ewiger Liebe. Mit meinem Mund verkündige ich Deine Treue für künftige Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Denn ich erklär: Die Liebe ist auf ewigen Grund gebaut; dem Himmel gleich befestigest Du Deine Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '\"Mit meinem Auserwählten schloß ich einen Bund; Ich schwor dem David, meinem Knecht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Auf ewig laß ich deinen Stamm bestehen, begründe deinen Thron für alle Zeiten.\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Dein unvergleichlich Wesen preist der Himmel, Herr, und Deine Treue mit der heiligen Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Wer in den Wolken gleicht dem Herrn? Wer von den Gottessöhnen ist dem Herrn ähnlich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'dem Gott, so schrecklich in der Heiligen Rat und furchtbar über alle um ihn her?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Herr, Gott der Heerscharen! Wer ist, wie Du, so mächtig, Herr? Wie Deine Treue doch für die, die Dich umgeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du bist des stolzen Meeres Herrscher; nur Du beruhigst seiner Wogen Brandung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Nur Du schlägst Rahab, daß es kampfunfähig wird, zerstreust mit Deinem starken Arme Deine Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Dein ist der Himmel, Dein die Erde; die Welt und was sie füllt, hast Du gegründet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Den Norden und den Süden schufest Du; der Tabor und der Hermon hoben sich in Deinem Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Dir ist ein Arm voll Kraft zu eigen, und stark ist Deine Hand und Deine Rechte hoch erhoben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Gerechtigkeit und Recht sind Deines Thrones Pfeiler, und Huld und Treue gehen vor Dir her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Dem Volke Heil, das jauchzend im Lichte Deines Angesichtes wandelt, Herr,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'das über Deinen Namen stets frohlockt und das durch Deine Liebe groß dasteht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Die Krone seiner Macht bist Du; durch Deine Huld wächst unsere Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Fürwahr, dem Herrn ist unser Schild zu eigen, dem Heiligen Israels unser König. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Einst sprachst Du im Gesicht zu Deinem Frommen. Du sprachst: \"Ich habe aufgeholfen einem Helden und einen Jüngling aus dem Volk erhoben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Ich habe David, meinen Knecht, ergriffen, mit meinem heiligen Öle ihn gesalbt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'daß meine Hand beständig mit ihm sei, und daß mein Arm ihn stärke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Kein Gegner wird ihn überfallen, kein Frevler ihn bedrängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Vor ihm zerschmettere ich seine Feinde, und seine Hasser schlage ich zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Begleiten soll\'n ihn meine Huld und Treue, mein Name seine Macht erhöhen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Ich setze seine Hand aufs Meer und auf die Ströme seine Rechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Er soll mich anrufen: \'Mein Vater Du, mein Gott und meines Heiles Hort bist Du.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Ich mache ihn zum Erstgeborenen, zum Höchsten von den Erdenkönigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Ich will ihm ewig meine Huld bewahren und unverbrüchlich meinen Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ich mache ewig seinen Stamm und seinen Thron des Himmels Tagen gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Verlassen aber seine Söhne mein Gesetz und wandeln nicht nach meinen Ordnungen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'entweihn sie meine Satzungen und halten nimmer meine Vorschriften,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'dann strafe ich mit Ruten ihr Vergehen, mit Streichen ihre Missetat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Doch ich entziehe ihm nicht meine Gnade, und meine Treue laß ich ihm nicht fehlen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'verletze nimmer meinen Bund und ändre nicht den Ausspruch meiner Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Ich schwöre ein für allemal bei meiner Heiligkeit: - Wie sollte ich auch David täuschen? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Sein Stamm soll ewig dauern, sein Thron, der Sonne gleich nach meinem Willen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'und wie der Mond für alle Zeiten währen, beständig so, wie dieser in den Wolken!\" (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Und doch verwirfst Du und verschmähst im Zorne den, den Du gesalbt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'vernichtest Deines Knechtes Bund; wirfst seine Krone in den Staub,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'durchbrichst all seine Mauern, zertrümmerst seine Festen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Wer da vorübergeht, der plündert ihn; für seine Nachbarn ist er nur ein Hohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du hebst empor die Rechte seiner Dränger, erfreuest alle seine Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Du läßt abprallen seines Schwertes Schneide und ihn im Kampfe nicht bestehn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'vernichtest seine Heiligkeit und stürzest seinen Thron zu Boden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'verkürzest seine Jugendzeit, und deckest ihn mit Schande zu. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Wie lange, Herr, verbirgst Du Dich so ganz? Wie lange brennt Dein Grimm wie Feuer?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Bedenk doch, was ich für ein Wesen bin! Zu welchem Nichts schufst Du die Menschenkinder alle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Wo ist der Mann, der leben bliebe und den Tod nicht schaute, der vor des Grabes Macht sein Leben wahrte? (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Wo sind, Herr, Deiner Gnade frühere Beweise, die Du dem David schwurst bei Deiner Treue?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Bedenk den Hohn auf Deine Knechte, Herr, den ich von all den vielen Völkern her in meinem Busen trage,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'den Hohn, mit dem Dich Deine Feinde, Herr, verhöhnen, mit dem sie des von Dir Gesalbten Stamm beschimpfen! Gepriesen sei der Herr in Ewigkeit! Amen! Amen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Ein Gebet, von Moses, dem Gottesmann. - Ein Obdach bist Du, Herr,für uns durch alle Menschenalter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Bevor die Berge noch geboren wurden, bevor die Erde und die Welt gezeugt, bist Du von Ewigkeit zu Ewigkeiten, Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Die Menschen wandelst Du in Staub und sprichst: \"Ihr andern Menschenkinder: werdet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Denn tausend Jahre sind in Deinen Augen gleich einem jüngst vergangenen Tag, gleich einer Wache in der Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du lässest sie im Schlaf entstehen; sie sind wie Gras, das morgens sprießt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'das morgens blüht und sprießt, am Abend welkt und dorrt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Vor Deinem Zorn vergehen wir; zunichte werden wir vor Deinem Grimme,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'wenn Du Dir unsere Vergehn vor Augen stellst, vor Deines Angesichtes Leuchte unsere schlimmsten Fehler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Denn alle unsere Tage schwinden unter Deinem Grimme, und wir verbringen unsere Jahre einem Seufzer gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Auf siebzig kommen unsres Lebens Jahre, bei großer Kraft auf achtzig. Ihr Stolz ist Mühsal nur und Elend. Sie eilen schnell dahin, und wir entschwinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Wer weiß Bescheid mit Deines Zornes Stärke und wer mit Deinem Grimm, der Furcht vor Dir entsprechend?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Dieweil wir also unsere Tage zählen, zeig doch das Richtige, auf daß wir zur Vernunft gelangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Laß ab, o Herr! Wie lange noch? Werd andern Sinnes über Deine Knechte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Erquick uns bald mit Deiner Huld, damit wir jubelnd lebenslang uns freuen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Erfreu mit so viel Tagen uns, wie wir getrauert, mit so viel Jahren, wie in Unheil wir gelebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Dein Wirken zeige sich an Deinen Knechten und Deine Herrlichkeit an ihren Kindern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Des Herrn, unseres Gottes Gnade walte über uns, und fördere unsrer Hände Werk bei uns, ja, fördere unserer Hände Werk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Der du dich in des Höchsten Schutz begibst, in des Allmächtigen Schatten weilst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'vom Herrn sprich so: \"Mein Schirm und meine Burg, mein Gott, auf den ich baue!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Aus Jägers Schlinge löst er dich und vor dem Anschlag voller Tücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Mit seinen Schwingen deckt er dich; geborgen bist du unter seinen Fittichen. Ein Schirm und Schild ist seine Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Kein nächtlich Grauen darf dich schrecken, kein Pfeil, der an dem Tage fliegt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'und keine Seuche, die im Finstern schleicht, und keine Pest, die an dem hellen Mittag wütet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ob Tausend dir zur Seite fallen, Zehntausende zu deiner Rechten, dich wird es nicht treffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Du siehst es nur mit deinen Augen, wenn du der Übeltäter Strafgericht erlebst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'So sprich: \"Der Herr ist meine Zuversicht\". Zu deinem Freunde nimmst du dir den Höchsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Dir kann kein Unheil widerfahren und keine Plage deinem Zelte nahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Denn deinetwegen gibt er seinen Engeln das Gebot, auf allen deinen Wegen dich zu hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Auf Händen sollen sie dich tragen, daß nicht dein Fuß an Steine stoße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Auf Löwen und auf Nattern reitest du; du fährst auf jungen Löwen und mit Schlangen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Ich rette ihn, dieweil er an mir hängt, und schirme ihn, dieweil er meinen Namen kennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Wenn er mich ruft, so höre ich auf ihn und stehe ihm zur Seite in der Not. Ich rette ihn und bringe ihn zu Ehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ich labe ihn mit langem Leben und lasse schauen ihn mein Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein Lied, ein Gesang, für den Sabbattag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Gar köstlich ist\'s, dem Herrn zu danken und Deinem Namen, Höchster, Lob zu singen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'des Morgens Deine Huld zu künden und in den Nächten Deine Treue');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'zum Psalter mit zehn Saiten und zur Harfe, zum Saitenspiele auf der Zither.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Du, Herr, erfreust mich durch Dein Tun; ich juble über Deiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Wie groß sind Deine Werke, Herr, und Deine Pläne tief!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Der Törichte bemerkt es nimmer; der Tor beachtet\'s nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Wenn Frevler blühn, so ist\'s wie mit dem Gras. Die Übeltäter sprossen alle nur, damit sie ewig untergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Du aber bist der Höchste, Herr, in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Denn Deine Feinde kommen um, Herr, Deine Feinde; die Übeltäter werden allesamt zerstreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Dem wilden Stiere gleich wächst meine Kraft; gleichwie von Öl, so ist mein Alter frisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Mein Auge sieht mit Lust auf meine Gegner; mit Freuden hört mein Ohr von meiner Widersacher Niederlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Der Fromme sproßt wie eine Palme, und wächst wie eine Zeder auf dem Libanon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'ins Haus des Herrn verpflanzt und in den Höfen unseres Gottes grünend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'sie tragen noch im Alter Früchte, beständig grün und markig bleibend, zur Kunde, daß der Herr gerecht, daß er mein Hort ist ohne Tadel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Der Herr ist König, angetan mit Hoheit. Mit Macht bekleidet sei der Herr, gegürtet! Dann steht die Welt da ohne Wanken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Dein Thron steht wieder da wie einst. Du bist dann wie vor alters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Erheben Ströme, Herr, erheben Ströme ihr Gebraus, erheben Ströme ihr Getöse,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'viel stärker noch als vieler Wasser Tosen ist die Meeresbrandung; doch mächtiger der Herr in Himmelshöhen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'So bleibt, was Du verordnest, gültig. Wir wollen in Dein heilig Haus noch lange wallen, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Herr! Als der Rache Gott, als Gott der Rache zeige Dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Erhebe Dich als Erdenrichter! Vergilt den Stolzen nach Verdienst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Wie lange sollen Frevler, Herr, wie lange sollen Frevler noch frohlocken');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'und geifernd so Vermessenes reden und alle Übeltäter so sich brüsten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Sie treten, Herr, Dein Volk. Die ewig Deinen quälen sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'erwürgen Fremdlinge und Witwen und morden Waisen, sprechend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, '\"Der Herr sieht\'s nicht; nicht merkt es Jakobs Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Ihr Albernen im Volke werdet klug! Ihr Törichten! Wann wollt ihr das begreifen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Nicht hören sollte, der das Ohr erschafft? Nicht sehen, der das Auge hat gebildet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Nicht strafen sollte, der die Heidenvölker züchtigt? Er, der den Menschen Einsicht schenkt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Die menschlichen Gedanken kennt der Herr, wie sie so eitel sind. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Dem Manne Heil, den Du erziehst, o Herr, aus Deiner Lehre ihn belehrst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'ihn ob des Bösen Glück beruhigend, bis daß gegraben ist die Grube für den Frevler:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, '\"Der Herr verstößt sein Volk nicht ganz, verläßt die ewig Seinen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Noch immer sitzt er zu Gericht; ihm fallen alle frommen Herzen zu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Wer steht mir gegen Bösewichter bei? Wer tritt für mich den Übles Tuenden entgegen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Wenn nicht der Herr mein Beistand wäre, dann läge meine Seele bald im Reich der Stille.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Obschon ich wähnte, daß mein Fuß gewankt, so hält mich dennoch Deine Gnade aufrecht, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Und streiten sich in meinem Innern die Gedanken, so labt an Deinen Tröstungen sich meine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Hat schon des Unrechts Stuhl der aufgestellt, der Unheil dem Gesetz bereitet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Sie klagen fromme Seelen an; unschuldig Blut verdammen sie. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Doch eine Burg sei mir der Herr, mein Gott, mein Zufluchtsfels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Er lohne ihnen auch ihr Unrecht; er tilge sie in ihrer Bosheit! Der Herr vertilge sie, er, unser Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Wohlan! Laßt uns dem Herrn zujauchzen, zujubeln unserm hilfereichen Hort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Laßt Uns mit Lobpreis vor sein Antlitz treten, mit Liedern ihm entgegenjauchzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Der Herr ein großer Gott, Großkönig über alle Götter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'In seiner Hand der Erde Tiefen, sein sind der Berge Gipfel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Sein ist das Meer: Er hat\'s gemacht; das trockene Land: Er hat mit seinen Händen es gestaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Herbei, anbetend laßt uns niederfallen und niederknieen vor dem Herrn und unserm Schöpfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Er ist alleinig unser Gott, und wir sein Weidevolk und seine liebste Herde, wenn ihr auf seine Stimme heute horcht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '\"Verhärtet euer Herz nicht, wie zu Meriba, wie in der Wüste am Versuchungstag,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'wo eure Väter mich versucht und mich geprüft, obschon sie meine Tat gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Ich grollte vierzig Jahre dem Geschlechte; ich sprach: Es ist ein Volk mit einem irren Geist; sie achten nicht auf meine Wege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Ich schwur daher in meinem Zorn: Nie gehen sie zu meiner Ruhstätte ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Dem Herrn zu Ehren singt ein neues Lied! Dem Herrn lobsinge alle Welt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Lobsingt dem Herrn; lobpreiset seinen Namen! Von Meer zu Meer tut kund sein Heil!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Verkündet bei den Heiden seinen Ruhm, bei allen Völkern seine Wunder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'ist doch der Herr so groß und lobesam, vor allen Göttern ehrfurchtswert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Der Völker Götter sind ja alle Götzen; des Himmels Schöpfer ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Vor ihn mit Glanz und Herrlichkeit! Mit Macht und Pracht zu seinem Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'So bringt dem Herrn, ihr Völkerscharen, herbei bringt Pracht und Macht dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'So bringt dem Herrn zu seines Namens Ehre Gaben! Betretet mit Geschenken seine Vorhöfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Werft vor den Herrn euch hin mit Schmuck fürs Heiligtum! Vor ihm erzittere die ganze Welt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Den Heiden rufet zu: \"Der Herr ist König. Darum steht die Welt und wanket nimmer. Er richtet Völker in Gerechtigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Der Himmel freue sich! Die Erde jauchze, das Meer und was darin, erbrause!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Die Flur frohlocke auch mit allem, was darauf! Die Waldesbäume alle jubeln vor dem Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, '\"Er kommt, er kommt, der Erde Richter. Er richtet nach Gerechtigkeit die Welt und die Nationen unparteiisch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Der Herr ist König. Erde freue dich! Und fröhlich sei\'n die Inseln, soviel ihrer sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Gewölk und Dunkel um ihn her; und seines Thrones Stütze ist Gerechtigkeit und Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Auflodere vor ihm ein Feuer und senge ringsum seine Feinde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Die Welt erhellen sollen seine Blitze; die Erde schaue es und zittere!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Die Berge schmelzen vor dem Herrn wie Wachs, vor ihm, dem Herrn der ganzen Erde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Die Himmel sollen künden seinen Sieg; die Völker alle schauen seinen Ruhm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Zuschanden sollen werden alle Bildanbeter, die stolz auf Götzen sind; hinsinken sollen in den Staub vor ihm die Götter alle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Mit Freuden hör es Sion, und Judas Töchter sollen jubeln ob Deiner Strafgerichte, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Für alle Welt bist Du der Höchste, Herr, hoch erhaben über alle Götter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Die ihr den Herren liebet, haßt das Böse! Er schirmt die Seelen seiner Frommen und reißt sie aus der Bösen Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Den Frommen wird ein Licht bereitet und Freude denen, die geraden Herzens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Ihr Frommen, freut euch an dem Herrn! Preist seinen heiligen Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein Lied. - Ein neues Lied singt jetzt dem Herrn, dem Wundertäter, dem seine Rechte hilft, sein heiliger Arm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Der Herr hat seinen Sieg verkündet, und vor der Heiden Augen offenbarte er sein Heil,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'der Huld und Treue eingedenk zum Heil des Hauses Israels. Der Erde Enden alle sahen unseres Gottes Sieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Entgegenjauchze alle Welt dem Herrn! Frohlocket! jubelt! Singt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Lobsingt dem Herrn mit Zitherklang, mit Zitherklang und mit Gesang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Mit Hörnern und Posaunenschall, mit Jubel vor dem König, vor dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Das Meer und was es füllt, erbrause, die Welt und die drauf wohnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Die Ströme sollen Beifall klatschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'die Berge allzumal frohlocken vor dem Herrn, wenn er die Welt zu richten kommt! - Er richtet nach Gerechtigkeit die Welt, nach Billigkeit die Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Der Herr ist König. Beben mögen da die Völker! Der Erdball zittere, wenn er sich auf die Cherubine niederläßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Groß ist der Herr in Sion, erhaben über alle Völker!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Sie sollen Deinen Namen preisen, ihn, den großen, schrecklichen! - Er ist so heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Und ist so mächtig. - Der Du das Recht liebst, König, stell die rechte Ordnung her und schaffe Billigkeit und Recht in Jakob!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Den Herrn verherrlicht, unsern Gott! Vor seiner Füße Schemel betet an! Er ist so heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Ein Moses und ein Aaron unter seinen Priestern; ein Samuel ruft seinen Namen an. Sie riefen zu dem Herrn, und er erhörte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Er spricht zu ihnen wieder in der Wolkensäule, wenn sie befolgen seine Mahnungen und das von ihm gegebene Gesetz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herr, unser Gott! Erhöre sie! Sei Du für sie ein Gott, fürsorgend, rächend ihre Unbilden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Den Herrn verherrlicht, unsere Gott! Werft euch vor seinem heiligen Berge nieder! Denn unser Gott, der Herr, ist heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Lied, zur Danksagung. - Entgegenjauchze alle Welt dem Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Verehrt den Herrn mit Fröhlichkeit! Mit Jubel tretet vor sein Angesicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Bekennt: Der Herr ist Gott! Erschaffen hat er uns, wir sind sein Eigen, sein Volk, die Schäflein seiner Weide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Zu seinen Toren ziehet dankend ein, mit Lobgesang in seine Höfe! Ihm dankt! Lobpreiset seinen Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Denn gütig ist der Herr. Auf immer währet seine Huld und seine Treue für und für.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Von David, ein Lied. - Von Liebe und von Recht will ich jetzt singen, will, Herr, Dir singen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Auf einen frommen Wandel achte ich. Wann wirst Du zu mir kommen? In Herzensunschuld wandle ich in meinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Mein Auge richt ich nicht auf schlimme Dinge. Der Abtrünnigen Treiben hasse ich; mir liegt es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ein falsches Sinnen liegt mir fern; vom Bösen weiß ich nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Wer heimlich andere verdächtigt, den bringe ich zum Schweigen. den Mann, begabt, doch übermütig, vertrage ich in keiner Weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Die Treuesten im Land ersehe ich für mich; nur solche dürfen um mich bleiben. Wer auf dem Pfad der Tugend wandelt, der soll mein Diener sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Wer aber Trug verübt, der bleibt in meinem Hause nimmer; wer Lügen spricht, verweilt nicht lang vor meinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Verstummen mache ich allmorgendlich des Landes Frevler insgesamt; denn ich verbanne aus der Stadt des Herrn die Übeltäter alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Gebet für einen Elenden, wenn er verzagt vor dem Herrn seine Klage ausschüttet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Herr! Höre mein Gebet, und laß mein Rufen zu Dir kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Verbirg Dein Antlitz nicht vor mir! Neig her zu mir Dein Ohr an meinem Trübsalstage! Erhöre schnell mich, wenn ich rufe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Denn meine Tage schwinden hin wie Rauch; dem Feuer gleich ist mein Gebein verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mein Herz ist dürr, versengt wie Gras; mein täglich Brot vergesse ich zu essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Vor meinem lauten Seufzen klebt mein Gebein im Leib zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Dem Pelikan der Wüste gleiche ich, und Eulen in Ruinen bin ich gleich geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Beim Wachen bin ich wie ein Vöglein, das einsam auf dem Dache weilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Mich höhnen täglich meine Feinde, und die mich reizen, nehmen mich zum Fluchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Denn Asche esse ich wie Brot und mische meinen Trank mit Tränen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'vor Deinem Zorne, Deinem Grimm, wenn Du mich aufhebst und zu Boden wirfst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Dem langen Schatten gleichen meine Tage; wie Gras verdorre ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Doch Du, Herr, thronest ewiglich; Dein Name dauert für und für.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Du solltest Dich erheben, Dich Sions wieder zu erbarmen. Ihm Gnade zu erweisen, ist es Zeit; denn die bestimmte Frist ist da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'So gerne haben Deine Knechte seine Steine und hängen selbst an seinem Schutt in Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Die Heiden fürchten dann des Herrn Namen und alle Könige der Erde Deine Herrlichkeit. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Erbaut dem Herrn von neuem Sion und zeigt er sich in seinem Herrschertum,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'und achtet auf der Nackten Flehen, verschmäht er nimmer ihr Gebet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'dann schreibe man dies für die Nachwelt auf, damit ein neugeschaffen Volk den Herrn lobpreise!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Von seiner heiligen Höhe schaue er herab; der Herr vom Himmel auf die Erde blicke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'um der Gefangenen Gestöhn zu hören, des Todes Kinder zu befreien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Dann künden sie des Herren Ruhm in Sion und zu Jerusalem sein Lob,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'wenn sich die Völker allzumal versammeln und Königreiche, um dem Herrn zu dienen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Ermattet bin ich auf dem Weg; verkürzt sind meine Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Drum flehe ich: \"Mein Gott! Nimm mich nicht weg in meiner Tage Hälfte! Du, dessen Jahre Ewigkeiten währen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Die Erde, die Du einst gegründet, der Himmel, Deiner Hände Werk,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'sie schwinden hin, Du aber bleibst. Sie all veralten wie ein Kleid; Du wechselst sie wie ein Gewand. Und wechseln sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'so bleibst Du doch derselbe, und Deine Jahre enden nicht. So mögen auch die Kinder Deiner Knechte bleiben, ihr Stamm, solang Du selber bist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Von David. - Den Herrn lobpreise, meine Seele, mein ganzes Herz den heiligen Namen sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Lobpreis den Herrn, du, meine Seele! Vergiß nicht, was er Gutes dir getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Er ist\'s, der alle deine Schuld vergibt, der alle deine Leiden heilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'der vor dem Grab dein Leben rettet, mit Huld und Liebe dich umgibt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'mit Segen dein Verlangen stillt und dich dem Phönix gleich verjüngt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Gerechtigkeit übt stets der Herr, schafft allen Unterdrückten Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Er zeigt, wie einst dem Moses seine Wege, den Kindern Israels all seine Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Barmherzig ist der Herr und gnädig, langmütig und von großer Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Er zürnt nicht immerfort; noch trägt er ewig nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Er tut uns nicht nach unsren Sünden, vergüt uns nicht nach unsren Missetaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'So hoch der Himmel über dieser Erde, so überragend seine Liebe über denen, die ihn fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'So fern der Morgen von dem Abend ist, entfernt er unsere Schuld von uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'So innig, wie ein Vater seine Kinder liebt, so liebt der Herr die, so ihn fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Er kennt ja unsere Art, ist eingedenk, daß wir aus Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Der Sterbliche! Wie Gras sind seine Tage, er blüht wie eine Blume auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Wenn sie ein Lüftchen anhaucht, ist sie weg, und ihre Stätte kennt sie nimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Die Huld des Herrn jedoch ruht für und für auf denen, die ihn fürchten, und seine Liebe auf den Kindeskindern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'die seinen Bund bewahren und seine Vorschriften erfüllen wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Der Herr hat seinen Thron im Himmel aufgestellt; doch seine Herrschaft waltet über alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Lobpreist den Herrn, ihr, seine Engel, ihr starken Helden, die ihr seinen Willen tut und seinem Donnerrufe folgt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Lobpreist den Herrn, all seine Heere! Ihr Diener, die Vollstrecker seines Willens!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Lobpreist den Herrn, all seine Werke an allen Orten seiner Herrschaft! Lobpreis den Herrn, du, meine Seele!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Lobpreis den Herrn, du, meine Seele! Du, Herr, mein Gott, gar groß bist Du, mit Pracht und Herrscherwürde angetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Du hüllst Dich in das Licht wie in ein Kleid und spannst den Himmel aus wie ein Gezelt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Auf Wasser baut er seinen Söller; zu seinem Wagen macht er Wolken und fährt auf Windesflügeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Zu seinen Boten macht er Stürme, zu seinen Dienern Feuerflammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Die Erde gründet er auf ihre Pfeiler, daß sie in alle Ewigkeit nicht wanke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Du deckst den Ozean darüber wie ein Tuch, daß selbst auf Bergen Wasser stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'jedoch vor Deinem Schelten fliehen sie; vor Deiner Donnerstimme eilen sie davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Die einen bleiben auf den Bergen; die andern fließen in die Täler zu dem Ort, von Dir bestimmt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Du setzest Grenzen, die sie nimmer überschreiten, und niemals decken sie die Erde wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Du bist\'s, der Quellen in die Täler sendet; sie rieseln zwischen Bergen hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Sie tränken alles Wild des Feldes; da löschen Zebras ihren Durst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Des Himmels Vögel sitzen drüber und lassen sich aus dem Gebüsche hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Die Berge tränkest Du durch Deine Wunderwerke; an Deines Wirkens Frucht ersättigt sich die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Du lässest Gras den Tieren sprossen und Futter für des Menschen Arbeitstiere, um aus der Erde Brot zu ziehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'auch Wein, der froh der Menschen Herzen macht, und Öl, das glänzen macht das Angesicht, und Brot, des Menschen Lebensmark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Des Herren Bäume werden satt getränkt, die Zedern Libanons, die er gepflanzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'darin die Vögel ihre Nester bauen, Zypressen, die dem Storch zum Nisten dienen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'die hohen Berge, die den Gemsen, die Felsen, die der Dachse Zuflucht sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Du schufst den Mond zum Zeiteinteilen und lehrtest ihren Lauf die Sonne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Wenn Finsternis herab Du senkst und es wird Nacht, dann regt sich alles Waldgetier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Die jungen Löwen brüllen nach dem Fraß, von Gott die Nahrung heischend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Geht dann die Sonne auf, so schleichen sie zurück und strecken sich auf ihre Lager nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Dann geht der Mensch an seine Arbeit, geht an sein Werkeln bis zum Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Wie mannigfaltig, Herr, sind Deine Werke, so weise sind von Dir sie all geordnet! Wie ist die Erde voll von Deinen Schöpfungstaten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Da ist das Meer, so groß und weit, zahlloses Seegetier darin, Geschöpfe klein und groß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'sie ziehen hin und her wie Schiffe samt dem Leviatan, den Du erschaffen, um mit ihm zu spielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Sie alle harren Deiner, daß Du zur rechten Zeit sie speisest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Und gibst Du ihnen etwas, lesen sie es auf, und wenn Du öffnest Deine Hand, so werden sie des Guten voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Doch wendest Du Dein Antlitz ab, dann faßt sie Grauen, und ziehst Du ihren Lebenshauch zurück, dann sterben sie und werden, was sie waren, Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du sendest Deinen Odem, andere entstehen, und so erneuerst Du der Erde Angesicht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Des Herrn Ruhm bestehe ewiglich! An seinen Werken freue sich der Herr,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'der auf die Erde blickt, daß sie erzittert, und Berge anrührt, daß sie rauchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Ich sing dem Herrn. Solang ich lebe, singe ich dem Herrn und preise meinen Gott, solang ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Mein Loblied möge ihm gefallen! Ich freue mich des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Ach, daß die Sünder von der Erde schwänden, daß keine Frevler mehr vorhanden wären! Lobpreis\' den Herrn, du meine Seele! Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Dem Herrn sagt Dank! Verherrlicht seinen Namen! Macht seine Taten den Nationen kund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Lobsingt von ihm! Lobt ihn! Erzählt von seinen Wundern all!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'In seinem heiligen Namen rühmet euch! Von Herzen freue sich, wer nach dem Herrn sucht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Verlanget nach dem Herrn und seiner Herrlichkeit! Stets sucht sein Angesicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Gedenkt der Wunder, die er tat, der Zeichen, seiner Richtersprüche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Geschlecht du, seines Knechtes Abraham, ihr Söhne Jakobs, seines Auserwählten! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Der Herr ist unser Gott, und auf der ganzen Erde gelten seine Urteilssprüche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'In Ewigkeit gedenkt er seines Bundes und seines Wortes, das er sprach, ins tausendste Geschlecht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'des Bunds, den er mit Abraham geschlossen für Israel als einen ewigen Bund,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'den er für Jakob als ein Recht bestätigt, und seines Eides, den er Isaak zugeschworen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, '\"Dir\", sprach er, \"geb\' ich Kanaan, als euer zugemessen Erbe.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Noch klein war damals ihre Zahl, noch winzig klein und fremd darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Sie wanderten von einem Heidenvolk zum andern, von einem Reich zu einer andern Nation.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Er gab nicht zu, daß jemand sie bedrückte; er warnte ihretwegen Könige:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '\"Vergreift euch nicht an den von mir Gesalbten! Fügt keinen Schaden meinen Sehern zu!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Er rief alsdann ins Land den Hunger, jedwede Brotesstütze brechend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Er sandte einen Mann vor ihnen her; zum Sklaven ward Joseph verkauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'in Fesseln zwang man seine Füße; in Eisen ward sein Hals gelegt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'bis in Erfüllung ging, was er verheißen, und ihn der Spruch des Herrn bewährte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Da ließ der König ihn entfesseln; der Völkerherrscher ließ ihn frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Er machte ihn zum Herrn in seinem Hause und zum Verwalter über all sein Gut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'daß er nach seinem Sinne seine Fürsten lenkte und seine Ältesten belehrte. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Alsdann kam nach Ägypten Israel, und Jakob ward ein Gast im Lande Chams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Er machte fruchtbar dort sein Volk, für seine Feinde allzu zahlreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Nun wandte er ihr Herz zum Hasse wider Gottes Volk, zur Arglist gegen seine Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Er sandte Moses, seinen Diener, und Aaron, den er sich erkoren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Sie zeigten ihnen seine Wunder und taten Zeichen in dem Lande Chams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Er sandte Finsternis, und dunkel ward\'s; doch achteten sie nicht auf seinen Wink.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Er wandelte in Blut ihr Wasser, und ihre Fische ließ er sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Er ließ ihr Land von Fröschen wimmeln bis in die Kammern ihrer Könige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Er sprach; da kam ein Fliegenschwarm und Mücken in ihr ganz Gebiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Für Regen gab er ihnen Hagel und Feuerflammen auf ihr Land,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'schlug ihren Weinstock, ihren Feigenbaum darnieder. zersplitterte die Bäume all in ihren Grenzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Er sprach; da kamen Heuschrecken und Ungeziefer ohne Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Sie fraßen alles Gras in ihrem Land und fraßen ihre Feldfrucht ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'In ihrem Lande schlug er alle Erstgeburt, die Erstlinge all ihrer Kraft. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Er führte sie mit Gold und Silber aus dem Lande, und unter seinen Stämmen war kein Müder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Ägypten ward ob ihres Wegzugs froh; denn Angst vor ihnen hatte sie befallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Er breitete zum Schirme eine Wolke aus und Feuer, um bei Nacht zu leuchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Auf ihre Bitte ließ er Wachteln kommen und schenkte ihnen Himmelsspeise zur Genüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Er öffnete den Fels, daß Wasser flossen, in dürrem Lande Ströme rieselten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Denn er gedachte seines heiligen Wortes und seines Dieners Abraham.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'So führte er sein Volk mit Jubel fort, mit Jauchzen seine Auserwählten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Der Heiden Länder gab er ihnen, ließ sie die Frucht des Völkerfleißes erben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'auf daß sie seine Rechte hielten, und seine Lehren treu bewahrten. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Alleluja! Dem Herrn sagt Dank! Denn er ist gut! Auf ewig währet seine Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Wer redet würdig von des Herren großen Taten, verkündet all sein Lob?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Heil denen, die das Richtige befolgen und es zu jeder Zeit recht machen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Gedenke meiner, Herr, begnadigst Du Dein Volk und kommt Dein Heil, so denk auch meiner,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'daß Deiner Auserwählten Glück ich noch erlebe und mich der Freude Deines Volkes freue und mit den ewig Deinen jubiliere!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Gesündigt haben wir mit unsren Vätern, unrecht und frevelhaft gehandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Schon unsere Väter merkten nicht auf Deine Wunder in Ägypten und dachten nicht an Deine Gnadenfülle. - Sie haderten am Meer, des Schilfmeers wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Um seines Namens willen half er ihnen, um seine Stärke kundzutun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Er schalt das Schilfmeer; es versiegte. Er führte sie durch Fluten wie durch eine Trift,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'entriß sie aus der Hasser Hand, befreite sie aus Feindes Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Das Wasser deckte ihre Dränger; nicht einer blieb von ihnen übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Da glaubten sie an seine Worte und stimmten einen Lobgesang ihm an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Doch schnell vergaßen sie dann seine Taten und harrten seines Rates nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Sie wurden in der Wüste lüstern, versuchten Gott im wasserlosen Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Da gab er ihnen ihr Begehr: Erbrechen sandte er in ihren Hals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Im Lager aber wurden sie auf Moses eifersüchtig und auf den Heiligen des Herrn, auf Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Die Erde tat sich auf, verschlang den Dathan, begrub die Rotte Abirams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'In ihrer Rotte flammte Feuer auf, und eine Flamme fraß die Frevler. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Am Horeb machten sie ein Kalb und beteten ein Gußbild an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'vertauschten ihres Gottes Herrlichkeit mit der Gestalt des Stiers, der Gras verzehrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'vergaßen Gott, der sie gerettet, der Großes in Ägypten hat getan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Erstaunliches im Lande Chams, Erschreckliches am Roten Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Er dachte dran, sie zu vertilgen; da trat vor ihm sein Auserwählter, Moses, in die Bresche, um seinen Grimm vom Unheil abzuwenden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Doch sie verschmähten das ersehnte Land und glaubten seinem Worte nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'In ihren Zelten murrten sie, gehorchten nicht des Herren Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Da schwur er ihnen hoch und teuer, sie in der Wüste zu vertilgen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'den Heiden preiszugeben ihren Stamm und diesen in die Länder zu versprengen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Sie paarten sich zu Ehren Baal Peors und aßen Totenopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Sie reizten ihn durch ihre Taten; da brach die Pest bei ihnen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Und Pinechas stand auf und schlichtete; da ward die Pest gehemmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Ihm ward es zum Verdienst gerechnet und seinen Enkeln immerfort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Und sie erzürnten ihn am Haderwasser, und ihretwegen mußte Moses leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Denn sie verbitterten ihm das Gemüt so daß er unbedacht mit seinen Worten war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Sie tilgten auch die Völker nicht, wie\'s ihnen doch der Herr gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Sie mischten sich mit Heiden und lernten ihre Sitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Sie dienten ihren Götzen, und diese brachten sie zu Fall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'So opferten sie ihre Söhne und ihre Töchter den Dämonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Unschuldig Blut vergossen sie, das Blut der eigenen Söhne und der Töchter, die sie den Götzen Kanaans zum Opfer brachten. So ward das Land durch Mord entweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Sie selbst bedeckten sich durch ihre Taten; durch ihre Werke wurden sie so untreu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Da zürnte seinem Volk der Herr aufs heftigste, zum Abscheu wurde ihm sein Erbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Er gab sie in der Heiden Hand, und ihre Hasser herrschten über sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Und ihre Feinde drückten sie; sie mußten ihrer Macht sich beugen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Zu vielen Malen hat er sie befreit; sie aber blieben voller Trotz bei ihrem Plan, verkamen so durch ihre Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Er sah auf ihre Not, sooft er ihre Klage hörte, dachte er');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'an seinen Bund mit ihnen, ward andern Sinns in seiner großen Huld');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'und ließ sie Mitleid finden bei allen ihren Siegern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Zu Hilfe uns, Herr, unser Gott! - Bring uns zusammen aus den Heidenvölkern, auf daß wir Deinem heiligen Namen danken, uns rühmen Deines Ruhmes! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Gepriesen sei der Herr, Gott Israels, von Ewigkeit zu Ewigkeit, und alles Volk soll sprechen: \"Amen! Alleluja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, '\"Dem Herrn sagt Dank! Denn er ist gut. Auf ewig währet seine Huld.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'So singen die vom Herrn Erlösten, die er aus Feindes Hand befreit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'und aus den Ländern sammelt von Morgen, Abend, Mitternacht und Süden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Sie irren in der Steppenwüste und finden keine Bahn zur Wohnstatt hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Sie leiden Durst und Hunger, und ihre Seele sinkt darob in Ohnmacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Sie schreien zu dem Herrn in ihrer Not; Er rettet sie aus ihren Ängsten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'und leitet sie auf rechtem Wege, die Wohnstatt zu erreichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Sie sollen dankbar sein dem Herrn für seine Gnade, für seine Wunder an den Menschenkindern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'daß er ihr Lechzen stillt und ihren Hunger mit dem Nötigen befriedigt! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'In Finsternis und Todesschatten sitzen sie, gebannt in Elend und in Eisen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'denn Gottes Worten widerspenstig, verschmähen sie des Höchsten Rat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Durch Mühsal beugt er ihren Sinn; sie werden machtlos; niemand hilft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Sie schrein zum Herrn in ihrer Not; er rettet sie aus ihren Ängsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Aus Finsternis und Todesschatten führt er sie, und ihre Fesseln sprengt er auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Sie sollen dankbar sein dem Herrn für seine Gnade, für seine Wunder an den Menschenkindern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'daß er zertrümmert eherne Pforten und Eisenriegel bricht! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Die Kranken leiden schwer ob ihres Sündenwandels und wegen ihrer Missetaten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'daß sie vor jeder Speise ekelt und sie des Todes Pforten schon berühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Sie schreien zu dem Herrn in ihrer Not; er rettet sie aus ihren Ängsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Er schickt sein Wort, macht sie gesund und rettet sie vor ihren Grüften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Sie sollen dankbar sein dem Herrn für seine Gnade, für seine Wunder an den Menschenkindern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'ihm Dankesopfer bringen, jubelnd seine Taten künden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Die auf der See in Schiffen fahren und ihr Geschäft auf großen Wassern treiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'erblicken hier des Herren Werke und seine Wunder mit der tiefen Flut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Ein Sturm erhebt sich auf sein Wort, und seine Wellen türmen sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Sie steigen bis zum Himmel, fahren in die Tiefen. Ihr Leben ist gefährdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Sie tanzen, schwanken wie Betrunkene. Dahin ist ihre ganze Kunst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Sie schrein zum Herrn in ihrer Not; er rettet sie aus ihren Ängsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Er macht den Sturm zum Säuselwind; da legen sich des Meeres Wellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Sie jubeln, daß sie stille liegen und er sie an ihr Endziel führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Sie sollen dankbar sein dem Herrn für seine Gnade, für seine Wunder an den Menschenkindern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'und ihn vor allem Volk erheben und ihn im Kreis der Alten loben! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Er macht zur Wüste Ströme, zu dürrem Lande Quellenorte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'ein fruchtbar Land zum salzigen Grund, der Bosheit der Bewohner wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Er macht zum Wasserteich die Wüste und dürres Land zum Quellenort;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'die Hungrigen läßt er hier wohnen; Sie bauen eine Wohnstatt dort,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'besäen Felder, pflanzen Weinberge, die lohnend Früchte tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Er segnet sie, daß sie sich riesig mehren, und läßt ihr Vieh sich nicht vermindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Vermindern sie sich, werden sie gebeugt von Druck und Elend und von Jammer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'dann gießt auf Fürsten er Verachtung aus und führt sie in die unwegsame Öde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Doch aus dem Elend hebt er Arme auf und macht Geschlechter Herden gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Das sehen Redliche und freuen sich, und jeder Frevelmund verstummt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Wer weise ist, beachtet dies, und Anerkennung finden so des Herren Gnadentaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein Gesang, ein Lied, von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Aus Herzensgrund, o Gott, will ich jetzt singen und frohlocken');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Erwache, du mein Stolz! Erwache, Harfe du und Zither! Ich singe wach das Morgenrot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Ich preise, Herr, Dich bei den Völkern, und ich besinge Dich bei den Nationen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'daß Deine Huld bis an den Himmel reicht, bis zu den Wolken Deine Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Erheb Dich, Gott, soweit der Himmel, und Deinen Ruhm, soweit die Erde reicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Daß Deine Lieblinge gerettet werden, mit Deiner Rechten hilf dazu! Erhöre uns! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gott hat in seinem Heiligtum gesprochen: \"Ich soll im Siegesjubel Sichem jetzt verteilen, das Sukkot-Tal vermessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Mein würde Gilead, Manasse mein, und meine Hauptwehr Ephraim und Juda wär mein Herrscherstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Ich zwänge Moab auch, das Waschbecken, und Edom, mir die Schuhe herzurichten, und über Philistäa triumphierte ich.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Wer bringt mich aber jetzt zur festen Stadt? Wer führt mich jetzt nach Edom hin? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Bist Du\'s nicht, Gott, der uns verstößt, der nicht mit unsren Scharen auszieht, Gott?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Verschaffe Rettung uns aus dieser Not! Denn Menschenhilfe trügt. Mit Gott verrichten wir dann Heldentaten; er nur kann unsere Feinde niedertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Auf den Siegesspender, von David, ein Lied. - Mein Gott, den ich lobpreise, sei nicht taub!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Sie öffnen gegen mich den frechen, falschen Mund; mit Lügenzungen reden sie zu nur');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'und überhäufen mich mit Hassesworten und feinden ohne Grund mich an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Für meine Liebe klagen sie mich an; ich muß mich gar verteidigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Für Gutes haben sie für mich nur böse Wünsche, für meine Liebe Haß: -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, '\"Man möge einen Frevler gegen ihn bestellen, daß er als Kläger gegen ihn auftrete!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Er gehe schuldig im Gericht hervor; fehlschlage ihm sein Rechten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Nur wenig seien seine Tage; ein anderer nehme sein Erspartes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Und seine Kinder sollen Waisen werden und seine Gattin Witwe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Unstet umherziehen und betteln sollen seine Kinder, aus ihren leeren Wohnungen verstoßen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Ein Wucherer belege seine ganze Habe mit Beschlag, und Fremde sollen sein Erworbnes plündern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Nicht einer bleibe ihm gewogen! Nicht einer schenke Mitleid seinen Waisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Sein Stamm verfalle der Vernichtung; im zweiten Glied erlösche schon sein Name!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Beim Herrn werd seiner Väter Schuld gedacht, und seiner Mutter Sünde werde nimmer ausgelöscht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Sie seien stets dem Herrn vor Augen, daß er vertilge ihr Gedächtnis von der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Denn er gedachte nimmer, Liebe zu erweisen, verfolgte elende und arme Leute und gab den Todesstoß zerbrochenen Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Weil ihm der Fluch so lieb und ihm sich leicht einstellte, dieweil das Segnen er nicht mochte, weil\'s ihm ferne lag,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'dieweil den Fluch er wie sein eigen Kleid anlegte, wie Wasser in sein Inneres nahm und er wie Öl in seine Glieder drang,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'so sei er ihm wie ein Gewand, das er als Hülle um sich legt, gleich einem Gürtel, den er ständig trägt!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Vom Herrn geschehe also meinen Anklägern, die wider mich gar Schlimmes reden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Du aber, Herr, mein Gott, befasse Dich mit mir um Deines Namens willen! Errette mich nach Deiner milden Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Denn ich bin bettelarm und leidend; mein Herz bricht mir im Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Gleich einem Schatten, der sich neigt, vergehe ich, bin hohl gleich einem Rauchfang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Vor Fasten wanken mir die Knie; mein Leib zehrt ab, wird mager.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Ich bin ihr Spott; sie sehen mich und schütteln ihren Kopf. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Komm mir zu Hilfe, Herr, mein Gott! Errette mich nach Deiner Huld,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'damit sie innewerden, Deine Hand sei es, daß Du, Herr, solches tust!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Sie mögen fluchen! Doch Du segne! So werden meine Widersacher voller Scham, Dein Diener aber voller Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'In Schande müssen meine Ankläger sich kleiden, in ihre Scham sich hüllen wie in einen Mantel! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Dann danke ich dem Herrn mit lautem Munde und preise ihn inmitten Vieler,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'daß er dem Armen steht zur Rechten, zur Hilfe gegen die, die ihn verklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Von David, ein Lied. - Ein Spruch des Herrn an meinen Herrn: \"Zu meiner Rechten setze dich! Ich mache deine Feinde zum Schemel deiner Füße.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Dein machtvoll Zepter laß der Herr weit über Sions Grenzen reichen! Steig du hinab in deiner Feinde Mittel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Dir huldige dein Volk an deinem Krönungsfest in heiliger Festesfreude! Und deiner jungen Männer Schar laß hoch dich leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Geschworen hat der Herr und es gereut ihn nicht: \"Du sollst auf ewig Priester sein, nach meinem Worte ein Melchisedech!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der Herr zu deiner Rechten zerschmettert Könige an seinem Zornestage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Er gehe mit den frevelschwangern Heiden ins Gericht, zerschmettre Fürsten auf dem breiten Plane.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Er trinke auf dem Zuge Wasser aus dem Bach und setze so dem Werk die Krone auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Alleluja! Aus ganzem Herzen danke ich dem Herrn im Kreis der Frommen und in der Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Des Herren Werke sind gewaltig, wie ausgesucht für alle ihre Zwecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Sein Wirken ist nur Pracht und Glanz, und ewig währet seine Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Er sorgt für seiner Wunder Fortbestand; / erbarmungsvoll und gnädig ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Er spendet Nahrung denen, die ihn fürchten, auf immer seines Bundes eingedenk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Er zeigte seinem Volke seiner Taten höchstes Maß, wie er das Eigentum der Heiden ihnen zum Besitze gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Von Recht und Treue zeugt ja seiner Hände Werk; was er verfügt, ist alles wohlgemeint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Für alle Zeiten sind sie festgesetzt und ausgeführt mit Treue und Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Er sandte seinem Volk Erlösung und schloß auf ewig seinen Bund. \"Furchtbarer\", \"Heiliger\" ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Der Weisheit Anfang ist die Furcht des Herrn. Wer also tut, der führt sich gut. Sein Ruhm besteht für ewige Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Alleluja! Wie selig, wer den Herren fürchtet und freudig tut, was er gebeut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sein Stamm ist mächtig auf der Erde; gesegnet ist der Redlichen Geschlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'In seinem Haus ist Pracht und Fülle, und seine Milde währet immerdar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Er strahlt den Frommen auf, ein Licht im Dunkel, barmherzig, mild und liebevoll ist er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Wohl geht\'s dem Mann, der schenkt und leiht, der hierfür seinen Haushalt nach Gebühr einrichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Er wankt auf ewig nicht; in ewigem Gedächtnis bleibt er als Gerechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Vor Unheilsboten bebt er nicht; sein Herz ist unverzagt, dem Herrn vertrauend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Sein Herz ist fest und ohne Furcht; er schaut sogar an seinen Feinden seine Lust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Freigebig ist er, schenkt den Armen, und alle Zeit währt seine Milde; durch sein Vermögen ragt er hoch empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Der Frevler sieht\'s und ärgert sich, und zähneknirschend schwindet er dahin; der Bösen Reiz vergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Alleluja! Des Herren Knechte, preist, lobpreist des Herren Namen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Des Herren Name sei gepriesen von nun an bis in Ewigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Vom Sonnenaufgang bis zum Niedergang sei hochgelobt des Herrn Name!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Der Herr sei über alle Heiden hoch erhaben! Bis in den Himmel reiche seine Ehrung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Wer gleicht dem Herrn, unserm Gott, der in der Höhe thront,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'der tief herniederblickt, im Himmel dort, hier auf die Erde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Aus Staub zieht er den Niedrigen empor und hebt den Dürftigen aus dem Kot');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'und setzt ihn neben Fürsten, zu seines Volkes Fürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Er läßt die Frau, die nie gebar, im Hause bleiben, als Kindermutter hochwillkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Als Israel Ägypten und Jakobs Haus das fremde Volk verließ,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'da ward Juda sein Heiligtum und Israel sein Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Dies sah das Meer und floh; der Jordan ging zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Die Berge hüpften gleich den Widdern, die Hügel wie die Lämmer. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Was ist dir, Meer? Du fliehst. Was, Jordan, dir? Du gehst zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Euch Bergen, daß ihr gleich den Widdern, euch Hügeln, daß ihr gleich den Lämmern hüpfet; -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Erbebe, Erde, vor dem Herrn, vor Jakobs Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'der Fels in See und Kies in Quellgrund wandelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nicht uns, nicht uns, nein, Deinem Namen gib die Ehre, Herr, und Deiner Huld und Deiner Treue!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Was sollten schon die Heiden sagen: \"Wo ist ihr Gott?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Im Himmel ist er, unser Gott, der alles, was er will, vollbringt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Doch ihre Götzen sind von Gold und Silber, ein Werk von Menschenhänden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Sie haben einen Mund und reden nicht; Sie haben Augen, doch sie sehen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Nicht hören sie mit ihren Ohren; nicht riechen sie mit ihrer Nase.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Nicht tasten sie mit ihren Händen; nicht gehen sie mit ihren Füßen; sie bringen keinen Laut aus ihrer Kehle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Wie sie, so werden ihre Schöpfer und alle, die auf sie vertrauen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Hat aber Israel fest auf den Herrn gebaut, dann ist er ihm ein Schutz und Schild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Baut Aarons Haus fest auf den Herrn, dann ist er ihnen Schutz und Schild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Und bauen, die den Herren fürchten, auf den Herrn, dann ist er ihnen Schutz und Schild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'So segne unsern Fortbestand der Herr! Er segne das Haus Israel! Er segne Aarons Haus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Er segne, die den Herren fürchten, die Kleinen mit den Großen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Der Herr vermehre euch, euch selbst und eure Kinder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'So seid gesegnet von dem Herrn, dem Schöpfer Himmels und der Erde! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Der Himmel ist ein Himmel für den Herrn; die Erde nur gibt er den Menschenkindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Die Toten loben nicht den Herrn, nicht die ins stille Reich Gesunkenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Dagegen wollen wir den Herrn lobpreisen von nun an bis in Ewigkeit. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Weil auf mein Rufen hört der Herr, hab ich die Stunden meiner Andacht lieb;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'er neigt sein Ohr zu mir, sooft ich rufe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Umfangen mich des Todes Bande, und überkommt mich Höllenangst, und komme ich in Not und Jammer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'dann rufe ich des Herren Namen an; \"Ach, rette, Herr, mein Leben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Der Herr ist gnädig und ist mild; erbarmungsvoll ist unser Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Einfältige beschützt der Herr; bin ich unwürdig schon, so hilft er dennoch mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Zu deiner Ruhestätte, meine Seele, wende dich! Der Herr tut dir ja Gutes unverdient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Du wahrst mein Leben vor dem Tode, mein Auge vor den Tränen und meine Füße vor dem Straucheln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'So kann ich wandeln vor dem Herrn im Lande der Lebendigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Ich kann\'s bestätigen, was ich jetzt sage: Ich war so tief gebeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Ich sprach in meiner Angst: \"Die Menschenkinder trügen all.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Wie kann ich jetzt dem Herrn vergelten all das, was er an mir getan?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Des Heiles Kelch ergreife ich; des Herren Ruhm verkünde ich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Was ich dem Herrn gelobt, das löse ich jetzt ein vor seinem ganzen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Bedeutungsvoll ist in des Herren Augen, wenn\'s um das Sterben seiner Frommen geht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ach, Herr, ich bin Dein Knecht; ich bin Dein Knecht, von Deiner Magd geboren. Wenn Du jetzt meine Bande lösest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'dann bringe ich Dir Dankesopfer dar und künde so des Herren Ruhm. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Was ich dem Herrn gelobt, das löse ich jetzt ein vor seinem ganzen Volke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'im Haus des Herrn in seinen Höfen, Jerusalem, in deiner Mitte. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Ihr Heiden allesamt, lobpreist den Herrn! Ihr Völker alle, preiset ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Für uns ist seine Huld ja viel zu groß; des Herren Treue währet ewig. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Dem Herrn sagt Dank! Denn er ist gut. In Ewigkeit währt sein Erbarmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'So spreche Israel: \"In Ewigkeit währt seine Huld!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'So spreche Aarons Haus: \"In Ewigkeit währt seine Huld!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'So mögen, die den Herren fürchten, sprechen: \"In Ewigkeit währt seine Huld!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Aus tiefer Not ruf ich zum Herrn, und mich erhört der Herr aus weiter Ferne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Ist schon der Herr für mich, dann fürcht ich nichts. Was könnten mir die Menschen tun?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Und ist der Herr mein Beistand, dann schau ich meine Lust an meinen Hassern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Viel besser ist es, auf den Herrn zu bauen, als Menschen zu vertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Viel besser ist es, auf den Herrn zu bauen, als Fürsten zu vertrauen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Umringen mich die Heiden all, ich wehre sie doch in des Herren Namen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Umringen sie mich auch, wie sie nur können, ich wehre sie doch in des Herren Namen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Umschwärmen sie mich auch wie ausgestoßene Bienen und wie das Feuer Dorngestrüpp einhüllt, ich wehre sie doch in des Herren Namen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Und stößt man mich zum Sturz, dann steht der Herr mir bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Mein Siegen ist des Herren Lob, verhilft er mir zur Rettung. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Dann tönen Jubellaut und Siegesruf bei den Gezelten der Gerechten: Gar Großes tut des Herren Rechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Ganz überlegen ist des Herren Rechte; gar Großes tut des Herren Rechte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ich sterbe nicht; ich bleibe noch am Leben, verkündige des Herren Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Und züchtigt mich der Herr auch hart, er gibt mich nicht dem Tode preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'So öffnet mir die Siegespforten! Ich ziehe ein, dem Herrn zu danken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dies ist des Herren Pforte; die Frommen ziehen durch sie ein. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, '\"Ich danke Dir, daß Du mich hast erhört und mir zur Rettung bist geworden.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, verworfen von den Bauleuten, ist jetzt der Eckstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Dies ist vom Herrn geschehn, ganz wunderbar in unsern Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, vom Herrn gewährt. Geweiht sei er dem Jubel und der Freude! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, '\"Wohlan, Herr, spende Heil! Wohlan, Herr, spende Glück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gesegnet in des Herren Namen sei, wer eintritt! Wir segnen euch vom Haus des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, '\"Der Herr ist Gott; er leuchte uns!\" Beginnt den Reigen mit den Zweigen bis zu den Hörnern des Altars! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, '\"Du bist mein Gott; ich danke Dir. Mein Gott, ich preise Dich.\" In Ewigkeit währt seine Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Dem Herrn sagt Dank! Denn er ist gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Glückselig, die unsträflich leben und in des Herrn Gesetzen wandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Glückselig sind, die seine Bräuche achten und ihn von ganzem Herzen suchen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'die nie ein Unrecht tun und die auf seinen Wegen wandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du selbst gibst Deine Vorschriften, daß man genau sie halte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Ach, wäre fest mein Wandel in der Befolgung Deiner Ordnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Dann werde ich niemals zuschanden, beacht ich alle Deine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Ich danke Dir von Herzensgrunde, wenn ich erlerne Deine so gerechten Weisungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Genau beachten will ich Deine Vorschriften. Verlaß mich nicht dabei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Wodurch erhält ein Jüngling seinen Wandel rein? Wenn er sich hält an Deine Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Von ganzem Herzen suche ich Dich auf. Entfremde mich nicht Deinen Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'In meinem Herzen berge ich Dein Wort, auf daß ich wider Dich nicht sündige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Gepriesen seist Du, Herr! Gewöhne mich an Deine Ordnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Auswendig sag ich auf all Deine mündlichen Gebote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Ich freue mich des Weges hin zu Deinen Zeugnissen weit mehr als über irgendwelche Schätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Was Du befiehlst, dem sinn ich nach und schaue hin auf Deine Pfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Mit Deinen Ordnungen befasse ich mich gern, vergesse nicht Dein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Gewähre Deinem Knechte, daß ich leben bleibe! Dann halte ich Dein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Entschleiere mir das Auge, daß ich schaue, was wunderbar an Deiner Lehre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ein Fremdling bin ich in dem Lande. Verbirg mir nimmer Deine Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'In Sehnsucht meine Seele sich verzehrt nach Deinen Weisungen zu jeder Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Du schiltst die Frechen. Verfluchst, die Deine Satzungen mißachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Wend Spott und Hohn von mir; denn Deine Zeugnisse, ich achte sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Ob Fürsten auch sich wider mich beraten, Dein Knecht beherzigt dennoch Deine Ordnungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Ja, Wonne sind mir Deine Zeugnisse, Wegweiser sind mir Deine Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Am Staube klebe ich. Erhalte mich nach Deinem Wort am Leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Ich lege meine Wege dar, und Du erhörst mich. Gewöhne mich an Deine Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Gib Einsicht mir ins Wesen Deiner Vorschriften! Dann will ich Deine Wunder überdenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Vor Leid weint meine Seele. Richt mich nach Deinem Worte auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Halt fern von mir den Pfad der Untreue! Zu eigen gib mir Deine Lehre gnädiglich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Den Weg der Treue wähle ich, befolge Deine Weisungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Ich hänge fest an Deinen Zeugnissen. Herr, laß mich nicht zuschanden werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Ich laufe auf dem Wege Deiner Ordnungen; Du machst mir weit das Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Zeig mir den Weg zu Deinen Vorschriften, o Herr! Ich will ihn mit Bedacht einhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Gib Einsicht mir, daß ich befolge Deine Lehre und sie mit ganzem Herzen hüte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Laß Deiner Satzung Pfad mich wallen! Denn Freude habe ich daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Zu Deinen Bräuchen lenke hin mein Herz und nicht zur Eigenliebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Lenk meine Augen ab vom Schielen nach dem Eitlen! Auf Deinen Wegen laß mich Leben finden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Bewähr an Deinem Knecht Dein Wort, das zu der Ehrfurcht vor Dir leiten soll!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Nimm meine Schmach hinweg, daß ich gezweifelt, ob Deine Weisungen auch heilsam seien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Nach Deinen Vorschriften verlangt es mich. In Deiner Liebe laß mich leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Herr! Deine Gnade komme über mich, Dein Heil nach Deinem Worte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'daß ich entgegne meinem Schmäher! Denn Deinem Wort vertraue ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Versag nicht meinem Mund das rechte Wort! Auf Deine Weisung harr ich sehnsuchtsvoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Stets will ich Deiner Lehre folgen, für immer und auf ewig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'nach ihr, der überreichen, wandeln. Nach Deinen Vorschriften verlangt es mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Vor Königen selbst rede ich von Deinen Zeugnissen ohn alle Scheu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Ich habe meine Lust an Deinen Satzungen; ich liebe sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Ich rege meine Hände eifervoll für Deine so geliebten Satzungen und sinne über Deine Ordnungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Gedenke Deinem Diener jenes Wort, auf das Du mich fest hoffen lässest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Dies ist mein Trost in meinem Leid, daß Lebensmut Dein Wort mir gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'So sehr Vermessene meiner spotten, ich weiche nicht von Deiner Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'An Deine Weisungen, die alten, denke ich und fühle mich getröstet, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Der Frevler wegen packt mich Zornesglut, die Deine Lehre schnöd verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Zu Lobesliedern sind mir Deine Ordnungen geworden im Haus, wo ich als Fremdling weile.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Ich denke, Herr, an Deinen Namen in der Nacht, an Deine Lehre selbst in mitternächtiger Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Zum Grundsatz ward mir dies, weil ich um Deine Vorschriften mich kümmere:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, '\"Mein Alles ist der Herr\", das deut ich so: Ich muß die Worte Dein beachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Von ganzem Herzen werbe ich um Deine Huld. Sei gnädig mir nach Deinem Wort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Ich überlege meine Wege und lenke meine Füß hin zu Deinen Zeugnissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Ich eile, säume nicht, zu halten Deine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Der Frevler Stricke wollen mich umfangen; doch ich vergesse nimmer Deine Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Um Mitternacht erhebe ich mich schon und danke Dir für Deine Weisungen, die so gerecht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'im Wetteifer mit allen, die Dich fürchten, die Deine Vorschriften befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Voll Deiner Gnade ist die Erde, Herr. Gewöhne mich an Deine Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Du tust an Deinem Knechte Gutes, nach Deinem Worte, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'So lehre mich heilsame Sitte und Erkenntnis! Denn Deinen Satzungen vertraue ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Bevor ich leiden mußte, irrte ich; nun aber halte ich Dein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du bist so gut und handelst gut. Gewöhne mich an Deine Satzungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Mir dichten Freche Falsches an; ich aber halte Deine Vorschriften aus ganzem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Ihr Herz ist stumpf wie Fett; doch ich ergötze mich an Deiner Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Mir war es heilsam, daß ich litt, damit ich mich an Deine Ordnungen gewöhnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Dein mündliches Gesetz gilt mir weit mehr als tausend Stücke Gold und Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Von Deiner Hand bin ich geschaffen und gebildet. Verleih mir Einsicht, daß ich mich an Deine Satzungen gewöhne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Mit Freuden sehen, die Dich fürchten, daß ich mich auf Dein Wort verlasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Ich weiß es, Herr: Gerecht sind Deine Weisungen; in bester Absicht hast Du mich gezüchtigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Zum Troste sei mir Deine Huld, wie Deinem Knechte Du verheißen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Laß Dein Erbarmen mich erquicken! Denn Deine Lehre ist mir Lust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Schmach über diese Frechen, weil grundlos sie zu Unrecht mich bezichtigen! Ich sinne über Deine Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Sie mögen sich durch mich in solche wandeln, die fürchten Dich und schätzen lernen Deine Zeugnisse!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Unfehlbar sei mein Herz in Deinen Ordnungen, damit ich nicht erröten muß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Nach Deinem Heile schmachtet meine Seele, ich harre Deines Wortes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Nach Deinem Worte schmachten meine Augen: \"Wann bringt\'s mir Trost?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Bin ich auch wie ein Schlauch im Rauche, vergesse ich doch niemals Deine Ordnungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wieviel sind noch der Tage Deines Knechtes? Wann richtest Du, die mich verfolgen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Mir graben Freche Gruben in dem, was Deiner Lehre nicht entspricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Was Du befiehlst, ist lautre Wahrheit; grundlos verfolgt man mich. Komm mir zu Hilfe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Beinah vertilgten sie mich von der Erde; doch laß ich nicht von Deinen Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Nach Deiner Huld erhalte mich am Leben, daß Deines Mundes Lehre ich befolge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Dein Wort ist für die Ewigkeiten, Herr; dem Himmel gleich, so steht es fest gegründet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Durch alle Zeiten währet Deine Treue, wie Du die Erde für die Dauer hast gegründet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Für Deine Winke steht sie heut bereit; denn alles ist Dir untertan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Wenn Deine Lehre mir nicht Wonne wäre, vergangen wäre ich in meinem Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nie will ich Deine Vorschriften vergessen; denn Du verleihst mir dadurch Lebenskraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Dein bin ich. Steh mir bei! Denn ich durchforsche Deine Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Mir lauern Frevler auf, mich umzubringen; doch ich vertiefe mich in Deine Zeugnisse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Bei allem anderen, was enden soll, ersehe ich ein Ende; doch Dein Gebot ist übergroß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Wie lieb ich Deine Lehre! Sie ist mein täglich Sinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Mich macht weit klüger Deine Satzung, als meine Feinde sind; denn ich besitze sie für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Verständiger noch werde ich als alle meine Lehrer; denn Deine Zeugnisse sind all mein Sinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'An Einsicht übertreff ich Greise; denn ich beachte Deine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Ich wehre meinem Fuße jeden bösen Weg, auf daß ich Deines Wortes pflege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Ich weiche nicht von deinen Weisungen; denn Du belehrest mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Wie süß sind meinem Gaumen Deine Worte, weit süßer meinem Mund als Honigseim!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Verständig werde ich durch Deine Vorschriften; drum hasse ich auch jeden falschen Pfad.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Dein Wort ist meines Fußes Leuchte, ein Licht auf meinem Pfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Ich hab\'s mir eidlich vorgenommen, was Du gerecht befohlen, auch zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ich bin gar tief gebeugt. Nach Deinem Worte, Herr, belebe mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Laß, Herr, Dir meines Mundes Übungen gefallen! Gewöhne mich an Deine Weisungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Mein Leben ist beständig in Gefahr; doch ich vergesse Deine Lehre nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Mir legen Frevler Schlingen; ich irre nimmer ab von Deinen Vorschriften. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Ein ewig Erbgut sind mir Deine Zeugnisse; ja, Herzenswonne sind sie mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Ich neige hin mein Herz, zu tun, was Du befiehlst, für immer auf das eifrigste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Ich hasse Zweifler; doch Deine Lehre liebe ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Mein Schirm und Schild bist Du; ich harre Deines Wortes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Hinweg von mir, ihr Übeltäter! Ich will ja meines Gottes Satzungen befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Nach Deinem Worte stärke mich, auf daß ich lebe! Beschäme mich in meiner Hoffnung nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Halt Du mich fest, daß ich gerettet werde! Ich schaue stets nach Deinen Ordnungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Die sich vergehn an Deinen Ordnungen, die wirfst Du weg; denn Trug ist all ihr Sinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Die Frevler all auf Erden achtest Du wie Schlacken; drum liebe ich auch Deine Zeugnisse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Aus Furcht vor Dir erschaudert mir die Haut; Ich fürchte mich vor Deinen Strafgerichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Das Rechte tu ich und das Gute. Gib meinen Drängern mich nicht preis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Vertritt zu seinem Besten Deinen Knecht, daß nicht die Stolzen mir Gewalt antun!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Nach Deiner Hilfe schmachten meine Augen, nach Deiner Heilsverheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Verfahr mit Deinem Knecht nach Deiner Huld! Gewöhne mich an Deine Ordnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Dein Knecht bin ich. Belehre mich, auf daß ich Deine Bräuche wohl verstehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, '\'s ist Zeit, sich für den Herrn zu regen; sie wollen Dein Gesetz abschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Drum liebe ich auch Deine Satzungen viel mehr als Gold, als selbst das feinste Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Drum habe ich all Deine Vorschriften mir auserwählt; ich hasse jeden falschen Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Geheimnisvoll sind Deine Zeugnisse drum achtet ihrer meine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Dein Wort erschließen spendet Licht; es macht die Einfalt klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Begierig öffne ich den Mund; denn mich verlangt nach Deinen Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wend Dich zu mir und sei mir gnädig, wie\'s Rechtens ist für die, die Deinen Namen lieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'In Deinem Wort mach meine Schritte fest! Laß nicht das Böse herrschen über mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Von Menschendruck befreie mich, damit ich Deine Vorschriften befolge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Laß Deinem Knecht Dein Antlitz leuchten! Gewöhne mich an Deine Ordnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Aus meinen Augen strömen Wasserbäche für die, die Deine Lehre nicht befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Gerecht bist Du, o Herr, und Deine Weisungen sind recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Ganz recht sind Deine Bräuche, die Du bestimmst, und lauter Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mein Eifer zehrt mich auf, daß meine Gegner Deine Worte so vergessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Dein Wort ist rein geläutert; Dein Knecht hat\'s lieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Gering, verachtet bin ich zwar; doch ich vergesse nimmer Deine Vorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Dein Recht bleibt ewig Recht; Wahrheit ist Deine Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Mich treffen Not und Angst; doch Wonne sind mir Deine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Allzeit sind Deine Bräuche richtig. Gib Einsicht mir, daß ich am Leben bleibe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Von ganzem Herzen rufe ich: \"Herr, höre mich! Ich möchte Deine Ordnungen befolgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, '\"Hilf mir!\" so rufe ich zu Dir. \"Ich möchte Deine Zeugnisse beachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Zur Zeit der Dämmerung erheb ich mich und flehe; ich harre Deines Wortes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Bevor der Morgen graut, sind meine Augen wach, Dein Wort zu überdenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Nach Deiner Huld erhöre mein Gebet! Wie\'s Deine Art ist, laß mich leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Die nach dem Laster jagen, kommen diesem immer näher und Deiner Lehre immer ferner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Jedoch auch Du bist nahe, Herr; all Deine Satzungen sind Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Von Urzeit her, so weiß ich es von Deinen Zeugnissen, Du hast sie eingesetzt für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Sieh her auf meine Not und rette mich! Ich habe Deine Lehre nicht vergessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Zu meiner Rettung führe meine Sache! Nach Deinem Worte laß mich leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Den Frevlern ferne ist das Heil, weil sie nach Deinen Ordnungen nichts fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Gar groß ist Dein Erbarmen, Herr. Laß mich, wie\'s Deine Art ist, leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Obschon mich viele drängen und verfolgen, so weiche ich doch nicht von Deinen Zeugnissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Erblick ich Treulose, streit ich mit ihnen, dieweil Dein Wort sie nicht beachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Wie gerne hab ich Deine Vorschriften! Erhalte mich nach Deiner Huld am Leben, Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Beständigkeit ist Deines Wortes Eigenart; für immer gelten Deine so gerechten Weisungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Von Fürsten werd ich ohne Grund verfolgt; doch nur vor Deinem Worte bebt mein Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Ich freue mich ob Deines Wortes, wie der, so reiche Beute findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Mit großem Abscheu hasse ich die Falschheit; nur Deine Lehre liebe ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Ich preise Dich des Tages siebenmal für Deine so gerechten Weisungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Die Deine Lehre lieben, ernten reichen Frieden; für sie gibt\'s keinen Anstoß mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Ich harre Deines Heiles, Herr, und Deine Satzungen befolge ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Auf Deine Zeugnisse hat meine Seele acht und liebt sie über alle Maßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Ich achte Deine Vorschriften und Bräuche; all meine Wege liegen ja vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Laß vor Dich kommen, Herr, mein Flehen! Nach Deinem Worte gib mir Einsicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Mein Flehen komme vor Dein Angesicht! Errette mich nach Deinem Wort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Ein Loblied ström von meinen Lippen, gewöhnst Du mich an Deine Ordnungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Dein Wort besinge meine Zunge! Denn alle Deine Satzungen sind Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Zum Beistand reiche mir die Hand! Denn Deine Vorschriften hab ich erwählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Nach Deinem Heil verlangt\'s mich, Herr, und Wonne ist mir Deine Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'So möge leben meine Seele und Dich preisen, und dazu mögen mir verhelfen Deine Weisungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Wie ein verloren Schäflein irre ich umher. Such Deinen Knecht! Denn ich vergesse niemals Deine Satzungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein Stufenlied. - In meiner Drangsal rufe ich zum Herrn. Er hört auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herr! Rette mich von Lügenlippen, von trügerischer Zunge!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Wie liefert Dir die trügerische Zunge fort und fort');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'geschärfte Pfeile eines Helden samt Ginsterkohlen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Weh mir, daß ich bei Mesech gaste, bei Kedars Zelten weile!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Zu lange schon weilt meine Seele bei Friedensfeinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich bin so friedsam. Doch, wenn ich\'s auch noch so sehr beteure, sie wollen Kampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ein Stufenlied. - Erhöb ich zu den Bergen meine Augen, von ihrer keinem käm mir Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Vom Herrn kommt meine Hilfe von dem Schöpfer Himmels und der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nie läßt er deine Füße gleiten; dein Hüter schlummert nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'O nein! Nicht schläft, nicht schlummert der Hüter Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Dein Hüter ist der Herr. Dein Schirm zu deiner Rechten ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Dir schadet nicht bei Tag die Sonne und nicht der Mond bei Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Vor allem Leid behütet dich der Herr, behütet deine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Der Herr behütet so dein Kommen wie auch dein Gehn, so jetzt wie alle Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ein Stufenlied, von David. - Mich freut es, sagen sie zu mir: \"Laßt uns zum Haus des Herren wallen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Bald sollen unsere Füße stehen, Jerusalem, in deinen Toren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem ist wieder aufgebaut als eine Stadt. Damit verbunden ist');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'die heilige Pflicht für Israel, daß dorthin ziehn die Stämme, ja, des Herren Stämme, und dort des Herren Namen preisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Dort stehen ja die Richterstühle, des Davidshauses Throne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Begrüßet so Jerusalem: \"Mög\'s deinen Freunden wohl ergehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'In deinen Mauern herrsche Frieden und Sicherheit in deinen Burgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Um meiner Freunde, meiner Brüder willen, wünsch ich dir Heil und Segen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Des Hauses unseres Herrn und Gottes wegen wünsch ich dir Wohlergehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ein Stufenlied. - Zu Dir erheb ich meine Augen, der Du im Himmel thronst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Sieh! Wie der Sklaven Blick auf ihrer Herren Hand gerichtet, und wie auf ihrer Herrin Hand der Sklavin Auge ruht, so blicken unsere Augen hin auf unsere Gott und Herrn, bis daß er unser sich erbarmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Herr! Sei uns gnädig, gnädig! Denn der Verachtung sind wir übersatt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Des Spottes der Behäbigen ist unsere Seele übersatt, der Schmach der Übermütigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Ein Stufenlied, von David. - \"Wär\' nicht der Herr, der mit uns ist\", - so spreche Israel -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, '\"wär nicht der Herr, der mit uns ist, wenn gegen uns die Leute sich erheben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'dann würden sie uns ungestraft vernichten, so sehr entflammt ihr Grimm sich gegen uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Begraben würde uns die Wasserflut; bis an die Kehle ginge uns ein Strom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Dann ginge bis zum Hals uns flutendes Gewässer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Gepriesen sei der Herr, der nicht zum Raub uns ihren Zähnen preisgibt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Wie Vögel aus des Fängers Netz, entkommt auch unser Leben. Das Netz zerreißt, und wir sind frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Fest ruhet unsere Hilfe in des Herren Namen, des Schöpfers Himmels und der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ein Stufenlied. - Die auf den Herrn vertraun, sind wie der Sionsberg, der niemals wankt und ewig steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Wie Berge um Jerusalem, so ist der Herr auch um sein Volk von nun an immerfort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'O nein! Des Frevels Zepter ruht nicht mehr auf dem Besitz der Frommen, dieweil die Frommen nimmermehr nach Frevel ihre Hände strecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Tu Gutes, Herr, den Guten, und denen, die geraden Herzens sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Doch die in ihrem Sinne schwanken, die läßt der Herr mit denen gehen, die Frevelhaftes tun. Heil über Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein Stufenlied. - Wenn die Gefangenen der Herr zurück nach Sion führt, dann wird es uns, als träumten wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Voll Lachen ist dann unser Mund und voll Frohlocken unsre Zunge. Dann sagt man bei den Heiden: \"Gar Großes wirkt der Herr an diesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Ja, Großes wirkt der Herr an uns; wir sind so fröhlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Laß unsere Heimkehr, Herr, geschehen, den Flüssen in dem Südland gleich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Mit Tränen wird gesät; geerntet wird mit Jubel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Wer Samen trägt im Sack, geht hin und weint; der Garbenträger kommt und jauchzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ein Stufenlied, von Salomo. - Wenn nicht der Herr das Haus mitbaut, so mühen sich die Bauleute vergebens. Wenn nicht der Herr die Stadt mithütet, so wacht umsonst der Wächter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Vergeblich steht ihr mit der Morgenröte auf und legt euch spät am Abend nieder, der Fronarbeiter Brot verzehrend! Zur Schlafenszeit gibt er das Rechte seinem Liebling.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Seht! Söhne sind des Herren Gabe und Leibesfrucht Belohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Wie Pfeile in des Kriegers Hand sind diese jugendlichen Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Dem Manne Heil, der ihrer gar viel im Köcher hat! Sie werden nicht zuschanden, wenn sie mit Feinden an dem Tore streiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Ein Stufenlied. - Heil jedem, der den Herren fürchtet und der auf seinen Pfaden wandelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Wenn du von deiner Hände Arbeit lebst, wohl dir! Es geht dir gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Gleich einem Weinstock, früchtereich, dein Weib im Innern deines Hauses und deine Söhne Ölbaumsprossen um deinen Tisch herum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Seht! Also wird der Mann gesegnet, der fürchtet Gott, den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'So segne dich der Herr von Sion aus! Erlabe dich am Glück Jerusalems dein Leben lang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Und schau die Kinder deiner Kinder! Heil über Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Ein Stufenlied. - Sie haben mich schon oft von Jugend an bedrängt.\" So spreche Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, '\"Schon oft von Jugend an bedrängt, jedoch nicht überwältigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Mit meinem Rücken pflügten sie und dehnten ihre Ackerfelder in die Weite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Der Herr jedoch, gerecht, zerhaut der Frevler Stränge.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'In Schande sollen weichen all die Hasser Sions.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Sie seien wie das Gras auf Dächern, das vor dem Blühen schon verdorrt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Der Schnitter füllt nicht seine Hand damit, nicht seinen Schoß der Garbenbinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Und keiner der Vorübergehenden ruft: \"Des Herren Segen über euch! Wir grüßen euch im Namen des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Ein Stufenlied. - Aus tiefem Grund, Herr, rufe ich zu Dir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herr, höre meine Stimme! Aufmerken mögen Deine Ohren auf mein lautes Flehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Wenn Du der Sünden achten wolltest, Ach Herr, wer könnte, Herr, bestehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'jedoch Vergebung ist bei Dir, daß man Dich fürchte. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Des Herren harr ich. Meine Seele harrt; ich hoffe auf sein Wort,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'ja, meine Seele harret auf den Herrn mehr, als den Morgen die Wächter sich ersehnen, die den Tag erwarten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israel harre auf den Herrn! Beim Herrn ist Gnade, bei ihm ist der Erlösung Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Nur er kann Israel erlösen von allen seinen Sündenstrafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Ein Stufenlied, von David. - Mein Herz, Herr, ist nicht stolz; nicht blicken meine Augen übermütig. Ich gehe nicht mit großen Dingen um, mit solchen, die mir unerreichbar sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Ruhe gebiete ich dem Herzen und mach\'s dem Kinde gleich an seiner Mutter Brust, dem Säugling gleicht mein Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'So harre Israel des Herrn von nun an bis in Ewigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Ein Stufenlied. - Sei, Herr, zugunsten Davids eingedenk all dessen, was er gesprochen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'wie er dem Herrn geschworen, dem Starken Jakobs hat gelobt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '\"Ich gehe nimmer in mein Wohngezelt, besteige nicht mein Ruhebett,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Versage meinen Augen Schlaf und Schlummer meinen Augenwimpern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'bis daß ich eine Stätte finde für den Herrn, für Jakobs Starken eine Wohnung.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Nun hörten wir davon zu Ephrat und fanden sie im Waldgefilde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, '\"Zu seiner Wohnung laßt uns gehen, vor seiner Füße Schemel niederfallen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Auf, Herr, zu Deiner Ruhestätte, Du und die Lade Deiner Herrscherwürde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Mit Heil laß Deine Priester sich bekleiden, und Deine Frommen mögen jubeln! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Um David, Deines Dieners willen, weis nicht zurück, den Du gesalbt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Der Herr schwur David Dauer zu. Er geht davon nicht ab. \"Auf deinen Thron erheb ich einen von deiner Leibesfrucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Bewahren deine Söhne meinen Bund und meine Zeugnisse, wie ich sie lehre, dann dürfen ihre Söhne allezeit auf deinem Throne sitzen!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Der Herr hat Sion sich erkoren, zum Wohnsitz sich ersehen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '\"Das sei in Ewigkeit mein Ruhesitz, ich throne hier; denn hier gefällt es mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Ich segne seine Jugend und gebe seinen Armen Brot in Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Mit Heil bekleid ich seine Priester, und frohe Lust sei seiner Frommen Teil!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Ich lasse Davids Macht ersprossen, dem richt ich eine Leuchte her, den ich gesalbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'In Schande hüll ich seine Feinde, dieweil auf ihm ein Diadem erglänzt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein Stufenlied, von David. - Wie lieblich ist\'s, wie schön, - schaut nur! - wenn Brüder beieinander bleiben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Wie köstlich Salböl von dem Haupt herabließt auf den Bart und wie der Aaronsbart auf des Gewandes Borte niederwallt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'und wie der Tau des Hermon auf dürre Bergesteile niederströmt, so spendet Segen dort der Herr, ein Leben bis in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein Stufenlied. - Des Herren Diener all - schaut nur! - ergehen sich im Lob des Herrn. Zur Nachtzeit noch verweilen sie im Haus des Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Erhebt auch eure Hand zum Heiligtum und preist den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Dann segnet dich der Herr, von Sion aus, der Herr, der Schöpfer Himmels und der Erden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Alleluja! Lobpreist des Herren Namen! Lobpreist ihn ihr, des Herren Diener,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'die ihr im Haus des Herren weilet, in unseres Gotteshauses Höfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Singt Alleluja! Denn der Herr ist gut. Singt seinem Namen! Er ist liebreich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'hat doch der Herr sich Jakob auserkoren, zu seinem Eigentum sich Israel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Ich weiß, der Herr ist so gewaltig, daß unser Herr die Götter alle überragt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Der Herr tut, was er will, im Himmel und auf Erden, im Meer und in den Tiefen all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Der Du heraufführst Wolken von der Erde Ende und Blitze für den Regen bildest, der Du den Wind aus seinen Kammern lässest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'der Du die Erstgeburt Ägyptens schlugest, vom Menschen bis zum Vieh,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'und in Ägypten wunderbare Zeichen an Pharao und allen seinen Knechten tatest');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'und große Völker niederschlugst und starke Könige vertilgtest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'den Amoriterkönig Sichon, den Basankönig Og und alle Reiche Kanaans');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'und deren Land zum ewigen Besitze machtest, zum ewigen Besitze Deines Volkes Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Dein Name ist auf ewig \"Herr\", für alle Zeiten wirst Du \"Herr\" genannt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Der Herr schafft seinem Volke Recht, erbarmt sich seiner Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Der Heiden Götzen sind von Gold und Silber, der Menschenhände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Sie haben einen Mund und reden nicht und Augen, doch sie sehen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Nicht hören sie mit ihren Ohren; kein Odem ist in ihrem Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Wie sie, so sollen werden, die sie machen, und so, wer sich auf sie verläßt! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Lobpreis den Herrn, Haus Israel! Du Aaronshaus, Lobpreis den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Du Levis Haus, Lobpreis den Herrn! Die ihr den Herrn fürchtet, preist den Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Gepriesen sei der Herr von Sion aus, der thronet zu Jerusalem! Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Dem Herrn sagt Dank! Denn er ist gut. Ja, ewig währet seine Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Dem Gott der Götter danket; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Dem Herrn der Herren danket; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Ihm, der allein nur große Wunder tut; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Ihm, der mit Einsicht schuf den Himmel; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Ihm, der die Erde ausgebreitet auf den Wassern; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Ihm, der die großen Lichter schuf; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Die Sonne als die Königin des Tages; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Als Nachtbeherrscher Mond und Sterne; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Der die Ägypter schlug an ihren Erstgeborenen; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Der Israel aus ihrer Mitte führte; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Mit starker Hand und ausgestrecktem Arme; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Ihm, der das Schilfmeer schnitt in Teile; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Der Israel durch seine Mitte führte; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Der Pharao und seine Macht ins Schilfmeer stürzte; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Der seines Volkes Führer durch die Wüste war; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Der große Könige erschlug; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Der starken Königen das Leben nahm; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Den Amoriterkönig Sichon; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Und Og, den Basankönig; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Und der ihr Land zum ewigen Besitze machte; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Zum ewigen Besitz für seinen Diener Israel; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Der unsere Erniedrigung uns hoch anschrieb; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Der uns von unseren Bedrängern rettete; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Der allem Fleische Speise gibt; denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Dem Himmelsgott sagt Dank! Denn ewig währet seine Huld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'An Babels Strömen sitzen wir, jedoch wir weinen, denken wir an Sion.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Wir hängen in den Weidenbüschen die Harfen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Denn unsere Zwingherrn fordern Lieder dort von uns und heitre Klänge unsere Peiniger: \"Ein Lied von Sion singet uns!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Wie könnten wir ein Lied dem Herrn zu Ehren in fremdem Lande singen? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Vergeß ich dein, Jerusalem, verdorr mir meine Rechte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Die Zunge klebe mir am Gaumen, wenn ich nicht dein gedächte, wenn ich in größter Freude selbst das Los Jerusalems mir nicht zu Herzen nähme! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Gedenke, Herr, den Edomssöhnen den Tag Jerusalems, an dem sie riefen: \"Zerstört, zerstört es gründlich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Du Tochter Babels, du Verwüsterin! Heil dem, der dir vergilt, was du an uns verübt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Heil dem, der deine Kindlein packt und an den Felsen schlägt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Von David. - Dich preise ich von ganzem Herzen; begeistert singe ich Dir zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'In Deinem heiligen Tempel werfe ich mich nieder und preise Deinen Namen hoch für Deine Huld und Treue. Denn über allen Deinen Ruhm hinaus hast Du Dein Wort verherrlicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Sooft ich zu Dir rufe, hörst Du mich, und so entlockst Du mir die kühnsten Wünsche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Dich preisen alle Erdenkönige, wenn Deines Mundes Worte sie vernehmen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Sie singen von des Herren Wegen; der Ruhm des Herrn ist groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Denn hoch erhaben ist der Herr und blickt doch auf das Niedrige, und ist er noch so hoch, so nimmt er doch aus weiter Ferne wahr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Und wandle ich auch mitten in der Not, erhältst Du dennoch mich am Leben; zu meiner Feinde Zorn streckst Deine Hand Du aus und hilfst mir so mit Deiner Rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Der Herr vollführt\'s für mich. Herr! Ewig währet Deine Huld. Laß nicht von Deiner Hände Werk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Auf den Siegesspender; von David, ein Lied. - Herr, Du erforschest und erkennest mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Du weißt es, ob ich sitze oder stehe, durchschaust, was ich für ferne Zukunft plane.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Du spürest meinen Pfad, mein Lager aus; Dir sind vertraut all meine Wege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Dafür fehlt meiner Sprache selbst ein Wort. Doch Herr! Du weißt dies alles selber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Von hinten und von vorne hältst Du mich umschlossen und hast mich ganz in Deiner Hand. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'O wunderbares, mir zu hohes Wissen! Ich kann es nimmer fassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Wohin soll ich vor Deinem Geiste gehen, wohin vor Deinem Antlitz fliehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Wenn ich zum Himmel stiege, bist Du da; wenn ich zur Hölle führe, bist Du hier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Erwähle ich des Morgens Säume, und ging ich an das fernste Meer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'auch dort ergriffe Deine Hand mich und Deine Rechte faßte mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Und spräche ich: \"Die Finsternis verhüllt mich sicher; das Licht wird um mich her zur Nacht\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'so wäre Dir die Finsternis selbst nicht zu finster. Dir leuchtet Nacht wie Tag und Finsternis wie Licht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Du schufest meine Nieren und formtest mich im Mutterschoße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Ich danke Dir, daß ich so wunderbar bin ausgezeichnet. Ganz wunderbar sind Deine Werke, und meine Seele fühlt es gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mein ganzes Sein ist Dir nicht unbekannt, obgleich ich im Verborgenen geschaffen ward, gewirkt in Erdentiefen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Gesehen haben Deine Augen meine umgeformten Glieder. Sie wurden alle in Dein Buch geschrieben, die Tage auch, wo sie sich formten, bevor noch eines davon war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Wie wertvoll sind mir, Gott, doch Deine Pläne! Wie unschätzbar die wichtigsten von ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Ich zählte eher noch des Meeres Sand als sie. Und wollte ich ihr Ende gar bestimmen, dann müßte meine Dauer Deiner gleichen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Daß Du die Frevler niederstrecken wolltest, Gott! Ja, fort von mir, ihr Blutmenschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'die Dir in Tücke widerstreben und hinterlistig Deine Städte zu gewinnen trachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Soll ich nicht hassen, die Dich hassen, Herr, vor Deinen Gegnern keinen Abscheu haben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Ich hasse sie mit unbegrenztem Hasse; sie gelten mir als Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Gott! Du erforsche mich! Mein Herz durchschau! Mit scharfem Blick prüf meinen Sinn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Sieh zu, ob ich der Kränkung Pfad betreten! Zurück zum alten Weg mit mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Auf den Siegverleiher, ein Lied von David.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Befrei mich, Herr, von bösen Menschen! Behüt mich vor den ungerechten Leuten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'die in dem Herzen Böses sinnen, alltäglich Händel stiften,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'die wie die Schlangen züngeln, und deren Rede Otterngift enthält! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Behüt mich, Herr, vor Frevlerhänden! Bewahre mich vor ungerechten Menschen, die mir ein Bein zu stellen suchen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Mir legen Übermütige Schlingen, und Stricke legen sie als Netz den Pfad entlang; sie stellen Fallen für mich auf. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ich aber sag zum Herrn: \"Mein Gott bist Du. Vernimm mein lautes Flehen, Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Herr, Du mein Herr, Du meine mächtige Hilfe! Mein Haupt beschirme an dem Tag, da Waffen klirren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Erfüll nicht, Herr, der Frevler Wünsche! Laß ihren Anschlag, zu obsiegen, nicht gelingen! (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Auf meiner Gegner Haupt herniederfalle das Unheil, das sie selbst gerufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Hernieder falle Kohlenglut auf sie! Man lasse sie in Gruben stürzen, woraus sie nicht mehr sich erheben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Nicht halte sich im Lande der Verleumder auf! Den Mann des Frevels soll das Böse jähem Sturz entgegenjagen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Ich weiß: Der Herr führt der Bedrückten Sache, den Rechtshandel der Armen. Die Frommen können Deinem Namen danken; vor Deinem Antlitz dürfen Redliche verweilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Ein Lied, von David. - Ich rufe, Herr, zu Dir. Erhöre mich! Vernimm doch meine Stimme, wenn ich zu Dir rufe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Laß mein Gebet wie Weihrauch vor Dich kommen und meine Andacht gleich dem Abendopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Setz meinem Mund, Herr, eine Wache! Verwahre meiner Lippen Tor! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Laß nicht mein Herz, dem Bösen hold, mit Übeltätern Frevel üben, daß ich von ihren Leckerbissen koste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Der Fromme schlage mich! Nur Wohltat ist es. Er züchtige mich! Denn dies ist mir Öl aufs Haupt. Mein Haupt sträubt nimmer sich dagegen. Anhaltend ist bei ihren Nöten mein Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Und fallen sie in ihrer Richter harte Hand, alsdann bekommen sie von mir zu hören, daß jene es nur gut gemeint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Wie man die Erde furchend gräbt; wird unser Leib dem Schlund der Unterwelt entrissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Herr! Meine Augen blicken hin auf Dich; ich suche Schutz bei Dir. Laß mich nicht ohne Schutz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Behüt mich vor der Schlinge, die sie legen, und vor der Übeltäter Stricken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'In ihren Netzen mögen sich die Frevler fangen gerade dann, wenn ich vorübergehe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Ein Lehrgedicht, von David, als er in der Höhle war; ein Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Ich rufe laut zum Herrn; ich flehe laut zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Ich schütte meine Klage vor ihm aus und tu ihm meine Drangsal kund;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Wenn sich mein Geist in Ängsten windet. - Du kennst ja meinen Pfad; auf diesem Wege, den ich gehen soll, erstellen sie mir eine Schlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Nach rechts hin blicke, schaue! Kein Mensch will mich erkennen. Jedwede Zuflucht ist mir abgeschnitten, und niemand kümmert sich um mich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ich schreie, Herr, zu Dir; ich sage: \"Du meine Zuversicht, mein Alles in dem Lande der Lebendigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Auf meine Klage merk! Denn ich bin sehr bedrückt. Entgehen laß mich den Verfolgern! Denn allzu mächtig sind sie mir. Befrei aus diesem Kerker meine Seele, auf daß ich Deinen Namen preise, wenn sich die Frommen meinetwegen schmücken, weil Du mir Gutes tust!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Ein Lied, von David. - Herr, höre mein Gebet! Vernimm mein Flehen! In Deiner Treue, Deiner Liebe, höre mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Geh nicht in das Gericht mit Deinem Diener! Vor Dir ist kein Lebendiger im Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Denn es verfolgen Feinde meine Seele und ziehen in den Staub mein Leben und werfen mich in finstere Tiefen, gleich denen, die schon längst verschieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Mein Geist in mir ist ganz verzagt; mein Herz erstarrt in meinem Busen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'An die vergangenen Zeiten denke ich und sinne über all Dein Handeln nach, erwägend Deiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Ich breite meine Hände nach Dir aus; wie dürres Land lechzt meine Seele Dir entgegen. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Erhör mich schnell, Herr! Fast vergehen will mein Geist. Verhüll Dein Antlitz nicht vor mir! Sonst bin ich den ins Grab Gesunkenen gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Tu bald mir Deine Gnade kund! Denn Du allein bist mein Vertrauen. Bezeichne mir den Weg, darauf ich wandeln soll! Zu Dir erheb ich meine Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Errette mich von meinen Feinden, Herr! Ich berge mich bei Dir. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Gewöhne mich, daß Deinen Willen ich vollbringe! Du bist mein Gott; Dein Geist ist gut. Er führe mich auf ebener Bahn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Herr! Schenke mir das Leben Deines Namens wegen! In Deiner Liebe rette meine Seele aus der Not!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'In Deiner Treue tilge meine Feinde! Vernichte alle Widersacher meiner Seele! Ich bin Dein Knecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Von David. - Gepriesen sei der Herr, mein Hort, der meine Hände streiten lehrt und meine Finger kämpfen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'der meine Wehr ist, meine Burg und meine Feste, mein Befreier, der mein Schild und meine Zuversicht, er, der mir Völker unterwirft! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Was ist der Mensch, daß Du Dich um ihn kümmerst, Herr, und was das Menschenkind, daß Du es also achtest');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Der Mensch gleicht einem Hauch, die Tage sein dem Schatten dessen, was vorüberfliegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Hernieder neige, Herr, den Himmel! Steig herab! Und rühre an die Berge, daß sie rauchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Wirf Blitze! Streue sie! Schieß Deine Pfeile ab und schrecke sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Von oben reiche Deine Hand! Befreie, errette mich aus großen Fluten, aus der Gewalt der Fremden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Sie reden falsch mit ihrem Munde, und schwören Meineid mit der Rechten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ich singe Dir dann, Gott, ein neues Lied und spiele Dir auf Harfen mit zehn Saiten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, '\"Der Königen verleiht den Sieg, der David, seinen Knecht, dem bösen Schwert entreißt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'der rettet und befreit mich aus der Hand der Fremden, die falsch mit ihrem Munde reden, mit ihrer Rechten Meineid schwören.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Dann sind wie Pfeiler an den Türmen unsere Söhne in ihrer Jugendkraft, und unsere Töchter gleichen Säulen, dem Bildschmuck an Palästen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Dann werden unsere Scheunen übervoll, für jede Frucht ein Speicher; zu Tausenden dann unsere Schafe, auf unsren Fluren zu Zehntausenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Und unsere Rinder trächtig; da gibt\'s Einfall nicht noch Ausfall, kein Jammer mehr auf unsren Gassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Dem Volke Heil, dem\'s also geht! Dem Volke Heil, des Gott der Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein Loblied, von David. - Erheben will ich Dich, mein Gott, Du König, und Deinen Namen immerdar und ewig preisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Ich will Dich jeden Tag lobpreisen und immer und auf ewig Deinen Namen rühmen: -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, '\"Groß ist der Herr und hoch zu preisen und unerforschlich seine Größe\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'daß ein Geschlecht dem andere Deine Werke rühme und Deine großen Taten künde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Vom wundervollen Glanze Deiner Herrschergröße, von Deinen Wundertaten will ich singen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Daß man von Deiner Schreckenstaten Größe rede, will ich von Deinen Großtaten erzählen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Lob Deiner großen Güte ströme aus, und Jubel preise Deine Liebe! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Der Herr ist gnädig und barmherzig, geduldig und von großer Güte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Der Herr ist gütig gegen alle, voll Liebe zu seinen Geschöpfen all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Dich sollen alle Deine Werke loben, Herr, und Deine Frommen Dich lobpreisen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Von Deines Reiches Glanze sollen sie erzähle und Deine Macht verkünden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'und so die andern Deine großen Taten lehren und Deines Reiches Pracht und Herrlichkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ja ein Reich für alle Zeiten, und Deine Herrschaft reicht bis zu den äußersten Geschlechtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Der Herr stützt alle Wankenden und richtet alle, die gebeugt sind, auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Die Augen aller schauen hin auf Dich; Du speisest sie zur rechten Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du öffnest Deine Hand und sättigst alles, was da lebt, mit Lust. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'In allen seinen Wegen ist der Herr so gütig, in allen seinen Werken liebevoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Der Herr ist allen nahe, die ihn rufen, ja allen, die mit Recht ihn rufen dürfen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'erfüllt die Wünsche derer, die ihn fürchten, vernimmt ihr Schreien und errettet sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Der Herr behütet alle, die ihn lieben, und rottet alle Frevler aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'So singt mein Mund das Lob des Herrn, daß alles Fleisch lobpreise seinen heiligen Namen für immer und auf ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Alleluja! Lobpreis den Herrn, du meine Seele!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Solang ich lebe, preise ich den Herrn und singe meinem Gott, solang ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Verlaßt euch nicht auf einen Fürsten, auf einen Menschen, der sich nimmer helfen kann!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Wenn ihm der Odem ausgeht, kehrt er wiederum zur Erde. Aus ist\'s an jenem Tag mit seinen Plänen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Wohl dem, des Helfer Jakobs Gott, und dessen Hoffnung ruht auf seinem Herrn und Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'der Himmel, Erde, Meer und alles, was darin, erschaffen! Er, der zu aller Zeit Gerechte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'verschafft den Unterdrückten Recht, gibt Brot den Hungernden. - Der Herr löst der Gefang\'nen Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Der Herr gibt Blinden Licht; der Herr hebt die Gebeugten auf; die Frommen liebt der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Der Herr beschützt die Fremdlinge, erhält die Waisen und die Witwen; die Frevler aber läßt er irregehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Der Herr wird ewig König sein, dein Gott durch alle Zeiten, Sion. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Lobpreist den Herrn! Weil er so gut, ist unser Gott des Lobes wert; weil er so liebevoll, des Ruhmes würdig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Der Herr erbaut Jerusalem; er sammelt die Zerstreuten Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Er heilet die gebrochenen Herzen und lindert ihre Schmerzen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Der Sterne Zahl hat er bestimmt und ruft sie all mit Namen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Ja, unser Herr ist groß, gewaltig, und seine Weisheit unbeschreiblich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Der Herr hebt die Gebeugten auf; die Frevler aber beugt er in den Staub. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'So dankt dem Herrn in Wechselchören! So singet auf der Zither unserm Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'ihm, der den Himmel deckt mit Wolken und so der Erde Regen schafft, der Gras auf Bergen sprossen läßt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'und der dem Wilde Futter gibt, den jungen Raben das, wonach sie rufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Er hat nicht Lust an Rosses Stärke; nicht achtet er des Mannes Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Dem Herrn gefallen, die vor ihm sich fürchten, und wer auf seine Gnade harrt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Lobpreis den Herrn, Jerusalem! Lobsinge, Sion, deinem Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Er festigt deiner Tore Riegel und segnet darin deine Söhne,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'und wieder gibt er deinen Grenzen Frieden und sättigt dich mit feinstem Weizen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Zur Erde sendet er sein Wort, und schnell läuft sein Befehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Wie Wolle gibt er Schnee und streut den Reif wie Asche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Er wirft sein Eis wie Brocken hin; vor seiner Kälte bleibt das Wasser stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Dann sendet er sein Wort; er macht sie schmelzen. Er gibt mir leis Befehl, und sie zergehn in Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Er, der sein Wort läßt Jakob hören, Gesetz und Rechte Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'So hat er keinem Heidenvolk getan, seine Gebote lehrte er sie nicht. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Alleluja! Lobpreist den Herrn im Himmel! Lobpreist ihn in den Höhen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lobpreist ihn, alle seine Engel! Lobpreist ihn, alle seine Scharen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lobpreiset ihn, du Sonne und du Mond! Lobpreist ihn, all ihr hellen Sterne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Du höchster Himmel, preise ihn und ihr Gewässer überm Himmel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Des Herren Namen sollen sie lobpreisen! Denn er gebot; da waren sie geschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Er läßt sie stehn für alle Zeiten und macht es zum Gesetz, das nimmer kraftlos wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lobpreist den Herrn, die ihr auf Erden weilet, ihr Meerestiere, all ihr Meeresfluten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Du Feuer, Hagel, Schnee und Sturmgewölk, du Sturmwind, seines Winks gewärtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Ihr Bergeshöhen, all ihr Hügel, ihr Fruchtbäume, ihr Zedern all!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Du Wild und all ihr zahmen Tiere, Gewürm und ihr beschwingten Vögel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Ihr Erdenkönige, ihr Völker all, ihr Fürsten alle und ihr Erdenrichter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Ihr Jünglinge, ihr Jungfrauen, ihr Greise und ihr Jungen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Lobpreisen sollen sie des Herren Namen! Denn hoch erhaben ist allein sein Name, und seine Herrscherwürde ist erhaben über Erd und Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Und seinem Volk verleiht er große Macht. Lobpreisen dürfen ihn all seine Frommen, die Kinder Israels, das Volk, das ihm so nahe steht. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Alleluja! Ein neues Lied singt jetzt dem Herrn, sein Lob mit seiner Frommen Chor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Froh wäre Israel an seinem Schöpfer. Ob ihres Königs seien Sions Söhne fröhlich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Mit Reigen sollen seinen Namen sie lobpreisen, mit Pauken und mit Zithern ihm lobsingen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Denn Wohlgefallen hat der Herr an seinem Volke. Er krönt mit Sieg die Dulder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Die Frommen jauchzen dann ob all der Herrlichkeit und tun sich nicht genug in Jubel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'In ihrem Mund sei Gottes Lob, ein scharfes Schwert in ihrer Hand,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'um Rache zu vollziehen an den Heiden und an den Völkern Ahndungen zu üben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'mit Ketten ihre Könige zu binden, mit Eisenfesseln ihre Edlen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'um zu vollziehen das Gericht, wie\'s vorgeschrieben! Für alle seine Frommen ist dies ehrenvoll. Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Alleluja! Lobpreist den Herrn in seinem Heiligtum! Lobpreiset ihn in seiner starken Feste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lobt ihn ob seiner großen Taten! Lobt ihn gemäß der Größe seiner Majestät!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lobpreist ihn mit Posaunenklang! Lobt ihn mit Zithern und mit Harfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lobt ihn mit Pauken und mit Reigen! Lobt ihn mit Saitenspiel und Flöten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lobt ihn mit leisen Zimbeltönen! Lobt ihn mit lauten Zimbeltönen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Ein jener Atemzug lobpreis den Herrn! Alleluja!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Die Sprüche Salomos, des Davidssohnes und Herrschers über Israel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'sind dazu da, daß man Charakter und Weisheit würdige und kluge Worte wohl verstehe');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'und Zucht und Anstand lerne, was recht und rechtlich, ehrlich sei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'daß Bildung Unerfahrene empfangen und daß die Jugend Lebenskunst erlerne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Vernimmt ein Weiser sie, so kann er seine Rede fesselnder gestalten; ein kluger Mann kann sich die richtige Belehrung sichern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Er kann das Gleichnis und den Sinnspruch faßlicher gestalten, wie auch der Weisen Worte, ihre dunklen Reden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Die Furcht des Herrn ist Anfang der Erkenntnis, Weisheit, Bildung. Nur Toren sind\'s, die sie verachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Der väterlichen Zucht, mein Sohn, gehorche! Der Mutter Mahnung achte nicht gering!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Sie zieren wie ein Kranz dein Haupt und deinen Hals wie Kettenschmuck.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mein Sohn, wenn dich Verbrecher locken, folg ihnen nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Wenn sie dir sagen: \"Halt\'s mit uns! Wir haben einen Anschlag gegen einen Menschen vor; wir wollen ungefährdet im Versteck Arglosen auflauern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Wir wollen selbst am Leben bleiben und sie verschlingen gleich der Unterwelt, mit Haut und Haar als solche, die zur Grube fahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Und wir gewinnen alles mögliche kostbare Gut und füllen unsere Häuser mit dem Raub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Du darfst auch mit uns teilen; wir alle haben einen Beutel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mein Sohn, geh nicht auf einem Weg mit ihnen! Halt deinen Fuß von ihren Pfaden fern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Denn ihre Füße laufen dem Verderben zu und eilen blutigem Tod entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Vergeblich wird man Netze spannen vor den Blicken der beschwingten Vögel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'sie aber lauern auf ihr eigen Blut und stellen sich selbst nach dem Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'So ist das Schicksal eines jeden, der auf unrechten Gewinn ausgeht. Er bringt ihn um sein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Auf Straßen ruft die Weisheit; auf Plätzen ruft sie laut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Hoch oben auf den Mauern predigt sie, an Stadttoren; vor aller Welt nimmt sie das Wort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '\"Wie lange liebt ihr Toren noch Betörung, gefällt den Dünkelhaften Spott und hassen Toren Einsicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Ihr kommt auf meine Mahnrede zurück. Fürwahr, ich sag euch unumwunden, was ich auf dem Herzen habe. Ich tue meine Warnungen euch kund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Ich rief; ihr aber wolltet nicht; ich winkte euch, und niemand gab drauf acht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Ihr schluget meinen Ratschlag in den Wind und mochtet meine Rüge nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'So lache ich bei eurem Unglück nur und spotte, wenn euch Angst befällt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'wenn wie ein Ungewitter euer Schrecken kommt, einherfährt gleich dem Sturmwind euer Unglück und Not und Drangsal euch befällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Dann rufen sie mich an; ich gebe keine Antwort. Sie suchen, aber finden mich nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Erkenntnis haben sie gehaßt und nach der Furcht des Herren nicht gefragt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'sie wollten nichts von meinem Rate wissen, und meine Rüge haben sie verschmäht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'So mögen sie denn ihres Handels Frucht genießen, sich sättigen mit dem, was sie sich selbst bereitet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Ihr Fehlgehn bringt sie, diese Dummen, um; Sorglosigkeit vernichtet diese Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Wer aber mir gehorcht, der kann in Ruhe wohnen und unbesorgt vor Unheilsschrecken sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mein Sohn! Nimmst du jetzt meine Worte an und bewahrst du bei dir, was ich geboten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'und lauscht dein Ohr auf Weisheit und neigt dein Herz sich zur Vernunft');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'und rufst nach Einsicht du und schreist du nach Verstand');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'und suchst du sie wie Silber und spürst ihr nach gleich wie verborgnen Schätzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'alsdann begreifst auch du die Furcht des Herrn, gewinnst Erkenntnis Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'daß Weisheit nur der Herr verleiht, aus seinem Mund Erkenntnis und Vernunft herrühren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'und daß er guten Rat für Rechtliche aufspart, ein Schild ist denen, die unsträflich wandeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'die von des Rechtes Bahnen nicht abweichen, jedoch die Wege seiner Frommen gehen, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'alsdann wirst du Gerechtigkeit und Recht verstehen, Geradheit, jede Bahn des Guten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'denn Weisheit kommt dir in das Herz und die Erkenntnis weilt in deiner Seele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Dann ist die Umsicht dir ein Schutz; Vernunft ist deine Hüterin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Sie rettet dich vor schlimmen Schurken, vor Lügenrednern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'die von des Lichtes Pfaden lassen und auf dem Weg des Finstern wandeln, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'die freudig Böses tun und ob dem Untergang des Nächsten jubeln, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'vor Leuten, deren Pfade krumm und deren Bahnen ganz verkehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Sie rettet dich vor andern Weibern, vor einer Fremden voller Schmeichelreden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'die den Vertrauten ihrer Jugend läßt und den vor ihrem Gott geschlossenen Bund vergißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Dem Tode nahe steht ihr Haus, und zu den Schatten führen ihre Bahnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Wer zu ihr eingeht, kehrt nicht wieder; betritt niemals des Lebens Pfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Dann kannst du auf dem Weg der Guten wandeln und an der Frommen Pfad dich halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Denn nur wer recht tut, darf im Lande wohnen; nur wer untadelig, drin übrigbleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Die Schlechten aber werden aus dem Land vertilgt und die Betrüger aus ihm ausgerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mein Sohn, vergiß nicht meine Weisung! Dein Herz beachte mein Gebot!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Denn viele Tage, lange Lebensjahre verheißen sie in Fülle dir und Wohlfahrt. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Sie mögen dich in treuer Liebe nicht verlassen! Bind um den Hals sie, schreibe sie auf deines Herzens Tafeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Durch feine Lebensart gewinnst du Gunst in Gottes und der Menschen Augen. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Auf Gott vertrau von ganzem Herzen! Stütz dich auf eigene Einsicht nie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Auf allen deinen Wegen denk an ihn! Dann ebnet er dir deine Pfade. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Halt dich nicht selbst für weise! Fürchte den Herrn! Halt ferne dich vom Bösen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Erquickung sei dies deinem Leibe und Labsal deinen Gliedern! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Ehre den Herrn mit deiner Habe, mit deiner ganzen Ernte erstem Abhub!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Dann werden reichlich deine Scheunen voll; vom Moste strömen deine Kufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Die Zucht des Herrn verachte nicht, mein Sohn, und seufze niemals über seine Strafe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Denn wen der Herr liebhat, den züchtigt er, so wie ein Vater seinen Sohn, an dem er Wohlgefallen hat. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Heil sei dem Mann, der Weisheit findet, dem Mann, der Einsicht sich erwirbt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Denn was sie einbringt, übertrifft, was man am Silber haben kann, und was sie abwirft, übertrifft, was man um Gold erwirbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Sie ist weit köstlicher als Perlen, und gar nichts kommt ihr gleich, was du dir wünschen könntest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'In ihrer rechten Hand liegt langes Leben, in ihrer linken Reichtum und Besitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'All ihre Wege sind der Wohlfahrt Wege; all ihre Pfade sind nur Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ein Lebensbaum für den, der sie ergreift, und wer sie festhält, ist beglückt. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Durch Weisheit gründete der Herr die Erde; durch Einsicht machte er den Himmel fest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Durch seine Kunst ergießen sich die Ozeane und senden Wolken Tau herab. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mein Sohn! Laß sie nicht aus den Augen! Bewahre Umsicht, klugen Rat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'So werden sie für dich zum Leben, für deinen Hals zu anmutsvollem Schmuck.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Dann gehst du sicher deines Weges; dein Fuß stößt nirgends an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Wenn du dich niederlegst, dann brauchst du keine Furcht zu haben, und wenn du schläfst, ist süß dein Schlummer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Vor plötzlichem Erschrecken brauchst du dich nicht zu ängstigen, nicht vor dem Unheil für den Frevler, daß es käme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Der Herr ist deine Zuversicht: Er hütet vor Verstrickung deinen Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Versag nicht dem die Wohltaten, der sie verdient, wenn es in deiner Macht steht, sie zu spenden! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Sag nicht zu deinem Nächsten: \"Geh fort! Komm später! Ich geb dir morgen etwas\", wenn du es heute kannst. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ersinn nicht Böses gegen deinen Nächsten, vor allem nicht, solang er arglos bei dir wohnt! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Mit keinem Menschen streite ohne Grund, wenn er dir nichts zuleid getan! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Beneide nicht die Herrenmenschen, wähl keinen ihrer Wege!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Der Arge ist dem Herrn ein Greuel; ein Freund ist er den aufrichtigen Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Der Fluch des Herrn ruht auf des Frevlers Haus; der Frommen Wohnstatt segnet er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Der Mühe, die sich Spötter machen, spottet er; den frommen Duldern gibt er reichlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Den Weisen kommt die Ehre zu; die Toren kommen an den Pranger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Die väterliche Mahnung, Söhne, hört! Merkt auf, damit ihr Einsicht kennenlernt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Denn gute Lehre geb ich euch. Laßt meine Unterweisung nimmer außer acht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Als Kind schon war ich meinem Vater teuer, ein Liebling meiner Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Er unterwies mich, sprach zu mir: \"Halt fest dein Herz an meinen Worten! Behalt, was ich dich heiße! Und du wirst glücklich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Einsicht und Weisheit zu erwerben, nicht vergiß! Weich nicht von meines Mundes Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Laß sie nicht außer acht! Und sie behütet dich. Gewinne sie recht lieb! Sie schützt dich wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Der Weisheit bester Teil: Erkaufe Weisheit! Mit aller deiner Habe kauf dir Einsicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Halt dich an sie! Und sie erhöht dich, bringt zu Ehren dich, wenn du sie herzest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Sie windet um dein Haupt der Anmut Kranz, beschert dir eine wunderschöne Krone.\" /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Mein Sohn! Horch auf! Nimm meine Worte an! Dann werden\'s deiner Lebensjahre viele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Ich lehre dich der Weisheit Weg und lasse dich auf graden Pfaden schreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Wenn du einherschreitest, ist nicht dein Schritt beengt; bist du im Lauf, dann stößest du nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Halt fest an dieser Richtschnur! Laß sie nimmer los: Sie ist dein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Nicht wandle auf der Frevler Pfad! Beschreite nicht der Bösen Weg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Vermeide ihn! Begeh ihn nicht! Lenk von ihm weg! Und geh daran vorbei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Sie können gar nicht einschlafen, falls sie zuvor nicht Böses schon getan; geraubt ist ihnen jeder Schlaf, falls sie nicht Ärgernis gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Sie nähren sich vom Brot der Gottlosigkeit und trinken der Gewalttat Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Der Frommen Pfad gleicht lichtem Morgenglanz, der immer heller wird, bis daß es Tag geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Der Frevlerweg ist wie das Dunkel: Sie merken nicht,was sie zu Falle bringt. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mein Sohn, auf meine Worte merk, und meinen Reden neig dein Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Laß sie nicht aus den Augen! Bewahre sie im Innersten des Herzens!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Denn Leben sind sie ja für die, die sie zu schätzen wissen, für ihren ganzen Körper Arzenei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Bewahr vor jeglicher Verstocktheit dir das Herz! Denn davon hängt das Leben ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Dein Mund soll niemals trügen, und deine Lippen seien keine Lügenlippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Dann kannst du deinem Gegenüber ruhig ins Auge sehn, ganz offen deinem Nächsten in das Auge blicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Geh stets geradeaus! Auf deines Fußes Bahn hab acht! Sei deines Ziels gewiß! All deine Wege seien fest bestimmt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Bieg nicht zur rechten noch zur linken Seite ab! Halt fern vom Bösen deinen Fuß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mein Sohn! Merk wohl auf meine Weisheit und neige meiner Einsicht hin dein Ohr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Alsdann behältst du Einsicht, und deine Lippen wahren Klugheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Von Honigseim triefen die Lippen eines fremden Weibes; sein Gaumen ist noch glätter selbst als Öl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Am Ende aber ist sie bitter wie der Wermut und scharf wie ein zweischneidig Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Zum Tode gehn die Füße, die sie besuchen, zur Unterwelt die Schritte, die zu ihr lenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Geht sie den Weg des Lebens? Irrpfade nur sind ihre Bahnen; sie weiß es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Nun, meine Söhne, hört auf mich! Von meines Mundes Reden weichet nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Halt ferne deinen Weg von ihr! Komm nicht der Türe ihres Hauses nahe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Sonst mußt du deine Kraft mit einer Fremden, mit einer Unbarmherzigen dein Lager teilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Und Fremde werden satt durch deine Arbeit, und deiner Mühen Preis wird einem andern Haus zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Und schließlich mußt du stöhnen, wenn Leib und Fleisch dir schwinden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'und mußt bekennen: \"Ach, daß ich Zucht gehaßt und daß mein Herz die Warnung hat verschmäht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'daß ich der Stimme meiner Lehrer nicht gehorcht und nicht mein Ohr geliehen meinen Lehrmeistern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Fast wäre ich geworden \"alles Böse in der Gemeinde und Versammlung\". /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Aus deiner Grube Wasser trink; nur was aus deinem Brunnen quillt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Nicht sollen deine Ströme sich nach außen gießen, nicht auf die freien Plätze deine Wasserbäche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Sie sollen dir allein gehören und nicht den Fremden neben dir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Gesegnet sei dein Born! Erfreu dich an dem Weibe deiner Jugend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'an dieser Hindin gar so lieb, an der Gazelle, also fein! Allzeit kann ihre Liebe dich berauschen; du kannst dich ihrem Lieben immerdar ergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Warum nur wolltest du, mein Sohn, dich einer anderen ergeben, umarmen einer Fremden Busen? /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Klar liegen vor des Herren Auge eines jeden Wege; auf alle seine Pfade hat er acht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Den Frevler nimmt gefangen seine Schuld; gebunden wird er mit den Stricken seiner Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Er stirbt aus Mangel an Botmäßigkeit und durch die große Torheit, der er sich ergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mein Sohn! Hast du für deinen Nächsten dich verbürgt, hast Handschlag du für einen anderen gegeben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'bist du verstrickt durch deines Mundes Reden, durch deines Mundes Worte selbst gefangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'dann, Sohn, sieh zu, daß du dich rettest, da du doch in die Hand des Nächsten eingeschlagen: Geh ohne Säumen hin! Bestürme deinen Nächsten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Gönn deinen Augen keinen Schlaf, nicht deinen Augenwimpern Schlummer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Errette dich gleich der Gazelle aus der Schlinge, gleich einem Vogel aus des Fängers Hand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Zur Ameise, du Fauler, geh, schau ihre Art und werde klug');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'durch sie die keinen Fürsten hat, nicht Amtmann, nicht Gebieter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'sie, die im Sommer schon ihr Brot bereitet und in der Ernte ihre Speise sammelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Wie lange, Fauler, willst du liegen? Wann willst du dich vom Schlaf erheben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, '\"Ach noch ein wenig Schlaf, ein wenig Schlummer, ein wenig noch die Hände ineinander legen, um zu ruhen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Schon kommt die Armut über dich, gleich der des Strolches, und Mangel gleich dem eines Bettlers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ein Teufelsmann ist der Halunke, der in der Falschheit seines Mundes wandelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'der mit dem Auge blinzelt, mit dem Fuße deutet, mit seinen Fingern Zeichen gibt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'und der Verkehrtes sinnt im Herzen und allzeit Streitereien anfängt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Das Unheil, das er stiftet, kommt ganz plötzlich; in einem Augenblicke schlägt er unheilbare Wunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Sechs Dinge sind dem Herrn verhaßt; ein Greuel sind ihm sieben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'hochmütige Augen, falsche Zunge, Hände, die unschuldig Blut vergießen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'ein Herz, das arge Tücke sinnt, und Füße, die behend zum Schlechten eilen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'wer Lügen haucht als falscher Zeuge; wer Händel zwischen Brüdern stiftet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mein Sohn, beachte das Gebot des Vaters! Verwirf nicht deiner Mutter Mahnung');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'und bind sie dir aufs Herz für alle Zeit! Leg sie um deinen Hals als Schmuck!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Bei deinem Gehen möge sie dich leiten, bei deinem Niederlegen dich bewachen, und dich ansprechen, wachst du auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Denn das Gebot ist eine Leuchte, ein Licht die Weisung; ein Weg zum Leben ist die Mahnung und die Warnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Denn sie bewahren dich vorm schlimmen Weib und vor der Fremden glatter Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nach ihrer Schönheit giere nicht in deinem Herzen! Sie fange nicht mit ihren Blicken dich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Für eine Dirne geht ein Brotlaib drauf; doch eine Ehefrau macht Jagd auf teures Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Kann jemand Feuer in den Schoß einscharren, und seine Kleider würden nicht dabei versengt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Auf glühende Kohlen sollte jemand treten, und seine Füße würden nicht verbrannt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Also ergeht es dem, der zu des Nächsten Weibe geht; wer sie berührt, der bleibt nicht ungestraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Verachtet man nicht einen Dieb, auch wenn er stiehlt, bloß um die Gier zu stillen, dieweil ihn hungert?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Wird er ertappt, dann muß er siebenfach ersetzen, muß seines Hauses Hab und Gut hingeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Wer Ehebruch mit einem Weibe treibt, ist unsinnig; nur wer sich selber ins Verderben stürzen will, tut so etwas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Nur Schläge, Schande findet er, und seine Schmach ist unauslöschlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Des Ehemannes Grimm wird leidenschaftlich aufgeregt; er schont ihn nicht am Tag der Rache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Mit irgendeinem Reuegeld beruhigt er sich nicht; er gibt sich nicht zufrieden, auch wenn du noch soviel Geschenke gibst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mein Sohn, behalte meine Reden! Bei dir verwahr, was ich dich heiße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Bewahr dir meine Vorschriften, so wirst du leben, und meine Weisung wie den Augapfel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Bind sie an deine Finger! Auf deines Herzens Tafel schreibe sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Zur Weisheit sprich: \"Du bist mir Schwester\", nenn Einsicht deine Freundin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'auf daß sie dich vor einem andere Weib bewahre, vor einer Fremden, die einschmeichelnd redet! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Durchs Fenster meines Hauses, durchs Gitter schaute ich hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Da sah ich einen Jüngling bei den noch Unerfahrenen, bemerkte bei den jungen Leuten einen Unvorsichtigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'der auf der Gasse nahe einer Ecke ging und in der Richtung meines Hauses schritt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'in Dämmerung, am Abende des Tags, in stiller Nachtzeit, in der Dunkelheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Da tritt auf einmal ihm das Weib entgegen im Dirnenanzug mit geschnürter Brust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Unruhig trieb sie sich herum; zu Hause hatten ihre Füße keine Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Ein Schritt jetzt auf die Straße und auf den Markt ein Schritt; sie lauerte an jeder Ecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Jetzt hascht sie ihn, küßt ihn; mit frecher Miene redet sie ihn an:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '\"Schlachtopfer darzubringen, lag mir ob; ich habe heute mein Gelübde nun entrichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Deswegen bin ich ausgegangen, um dich zu suchen. Ich habe dich gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Mit Decken habe ich bedeckt mein Lager, mit buntem Linnen aus Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Mit Myrrhen habe ich besprengt mein Lager, mit Aloë und Zimtgewürz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'So komm! Wir wollen bis zum Morgen an der Liebe uns berauschen, in Liebe uns genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Der Mann ist nicht daheim; er zog auf Reisen in die Ferne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Er nahm den Beutel samt dem Gelde mit sich; am Vollmondstag erst kehrt er wieder heim.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'So bringt sie ihn herum durch ihr verführerisches Reden und reißt ihn fort durch ihre glatten Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Er folgt ihr nach, der Harmlose, gleich einem Stier, den man zur Schlachtbank führt, gleich einem Hund zum Stricke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'gleich einem Hirsch dahin, wo ihm ein Pfeil die Leber spaltet, gleich einem Vogel, der zur Schlinge eilt, und merkt es nicht, daß es sein Leben gilt. /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Nun, Söhne, horcht auf mich! Auf meines Mundes Reden merket!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Laß nicht dein Herz zu ihren Wegen biegen! Verirr dich nicht auf ihre Steige!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Denn viel sind der Erschlagenen, die sie gefällt, und viele sind\'s, die sie gemordet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Die Wege, die zu ihrem Hause führen, sind Wege zu der Unterwelt. Sie führen zu des Todes Kammern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Die Weisheit! Ruft sie nicht? Und Einsicht läßt sich hören');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'am Weg ganz oben auf den Höhen; an Scheidewegen tritt sie auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Beim Eingang in die Stadt, an ihren Toren, am Eingang zu den Pforten ruft sie aus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '\"Zu euch, ihr Männer, rede ich; ich spreche zu den Menschenkindern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Ihr Einfältigen, lernet Klugheit! Ihr Toren, kommet zur Vernunft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Hört zu! Denn ich will Rechtes reden, und meiner Rede Inhalt ist, was richtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Denn Redlichkeit nur spricht mein Gaumen; für meine Lippen ist Unehrlichkeit ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Rechtschaffen ist, was immer spricht mein Mund, nichts Hinterlistiges, nichts Falsches ist darin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'das Richtige für alle, die da fragen, und recht für die, die suchen nach Erkenntnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Nimm meine Mahnung lieber an als Silber, Erkenntnis lieber als erlesenes Gold. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Denn besser noch als Perlen ist die Weisheit; und Kostbarkeiten kommen ihr nicht gleich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, '\"Ich, Weisheit, hab zur Nachbarin die Klugheit; ich kann zu klugem Wissen kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Die Furcht des Herrn verträgt sich nicht mit Bösem. Ich hasse Hochmut, Hoffart, schlimmen Wandel sowie verkehrtes Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Mein ist der Rat, die Tüchtigkeit; Einsicht ist mein und mein die Stärke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Durch mich regieren Könige, und Fürsten herrschen, wie es rechtens ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Durch mich befehlen Herrschende und all die hohen Erdenrichter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Wer mich liebt, den liebe ich; mich finden, die mich suchen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Reichtum und Ehre sind bei mir, ein stattlich Gut und Wohlergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Weit besser noch als Gold, als feines Gold, ist meine Frucht, und mein Ertrag ist kostbarer als auserlesen Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Ich wandle auf dem Pfade der Gerechtigkeit und mitten auf des Rechtes Wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Ich gebe denen, die mich lieben, immerdar Besitz und fülle ihre Schatzkammern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Mich schuf der Herr als Anfang seiner Laufbahn, als erstes seiner Werke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'in der Urzeit. Von Ewigkeit her bin ich eingesetzt, im Anfang seit dem Weltbeginne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Die Ozeane waren nicht, da ward ich schon geboren, als es noch keine reichen Wasserquellen gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Bevor die Berge eingesenkt, da war ich vor den Hügeln schon geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Er hatte Land und Flur noch nicht gemacht, noch nicht das Element des Staubes in der Welt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'da war ich schon dabei, als er den Himmel hergestellt, als er die Wölbung überm Ozean festsetzte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'als er die Wolken droben mächtig machte, und als des Ozeanes Fluten mächtig wurden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'als er dem Meere seine Schranke setzte, daß die Gewässer sein Geheiß nicht überschritten, als er der Erde Gründe legte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Zur Seite war ich ihm als Schülerin und diente zur Ergötzung Tag für Tag und spielte vor ihm jede Zeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'und spielte auf dem Erdkreis, den ich liebte, und zur Ergötzung diente ich den Menschenkindern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, '\"Nun, meine Söhne, hört auf mich! Heil denen, die meine Wege wählen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Auf Mahnung hört, auf daß ihr weise werdet! Schlagt sie nicht in den Wind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Heil sei den Menschen, die mich hören und Tag für Tag an meinen Türen wachen und meiner Tore Pfosten hüten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Denn wer mich findet, findet Leben, und von dem Herrn empfängt er alles Nötige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Wer aber mich verfehlt, der frevelt gegen seine eigene Seele; ja alle, die mich hassen, lieben nur den Tod.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Die Weisheit hatte sich ein Haus gebaut und sieben Säulensitze machen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Sie schlachtete ihr Vieh und mischte ihren Wein und deckte ihre Tische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Sie sandte ihre Mägde aus, um auf erhöhten Plätzen in der Stadt zu rufen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '\"Wer immer töricht ist, der pflege hier der Einkehr!\" Wem\'s an Verstand gebricht, zu dem sag ich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '\"Kommt her, genießt von meiner Speise und trinkt den Wein, den ich gemischt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Laßt von der Torheit, daß ihr lebet, und schlagt den Weg der Einsicht ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Wer einen Spötter schilt, der holt sich selber Schande, wer einen Frevler tadelt, eigene Schmach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'So tadle nicht den Spötter, daß er dich nicht hasse! Doch tadle einen Weisen, dieser wird dich lieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Belehre einen Weisen! Und er wird noch weiser. Den Frommen lehr! Er mehrt sein Wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Der Weisheit Anfang ist die Furcht des Herrn; den Heiligen erkennen, das heißt Einsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '\"Durch mich ja werden deiner Tage viele; die Lebensjahre werden dir sich mehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Bist du jetzt weise, bist du weise dir zum Besten; bist du ein Spötter, hast du es allein zu tragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Das Weib der Torheit schwatzt nur dummes Zeug; unwissend ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Sie sitzt an ihres Hauses Pforte, auf einem Sessel, fern dem Herzen ihrer Stadt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'um denen zuzurufen, die des Weges ziehen und auf den Pfaden fürbaß schreiten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '\"Wer immer töricht ist, der pflege hier der Einkehr!\" Wem\'s an Verstand gebricht, zu dem möcht ich jetzt sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '\"Gestohlen Wasser, das ist fein; verboten Brot - ein süßes Brot!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Und er weiß nicht, daß dort die Schatten hausen, daß ihre Gäste in der Hölle Abgrund kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Die Sprüche Salomos sind folgende: Ein weiser Sohn macht seinem Vater Freude; ein törichter ist seiner Mutter Gram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Unnütz sind Schätze, frevelhaft erworben; nur Tugend kann vorm Tode schützen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Der Herr läßt nicht der Frommen Hunger ungestillt; der Frevler Gier stößt er zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Die faule Hand schafft Armut; die Hand der Fleißigen schafft Reichtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Wer schon im Sommer sammelt, der ist klug, verächtlich, wer die Erntezeit verschläft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Aufs Haupt der Frommen strömen Segnungen; der Frevler Mund bringt Unheil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Des Frommen Name dient zum Segnen; des Frevlers Name schwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Wer weisen Herzens ist, nimmt die Gebote an; nur wer ein Narrenmaul besitzt, verwirft sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Wer in der Unschuld lebt, tritt sicher auf; wer auf verkehrten Wegen wandelt, dem geht\'s schlimm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Wer mit dem Auge blinzelt, bereitet Kränkung, und wer ein Narrenmaul besitzt, hetzt auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Des Frommen Mund - ein Lebensborn; des Frevlers Mund nur Unrecht birgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Der Haß legt Zwistigkeiten bloß; doch alle Sünden deckt die Liebe zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Gefunden wird durch eines Weisen Lippen Weisheit, doch auch ein Stock für eines Unverständigen Rücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Die Weisen bergen ihre Wissenschaft; des Toren Mund ist nahendes Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Des Reichen Habe ist ihm eine feste Stadt; den Dürftigen ist ihre Armut ihre schwache Seite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Des Frommen Lohn dient für das Leben, des Frevlers Einkommen für die Verdammnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Dem Leben geht entgegen, wer auf Mahnung hört; wer aber Rüge nicht beachtet, wandelt irre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Wer Haß mit lügenhaften Lippen will bedecken, ist gerade so ein Tor wie jener, der üble Nachrede verbreitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Bei vielem Reden geht\'s nicht ohne Fehler ab; wer aber seine Lippen zügelt, der tut klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Ein auserlesenes Silber ist des Frommen Zunge; des Gottlosen Verstand ist wenig wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Gerechte Lippen haben viele Güter; die Toren aber sterben durch den Unverstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Reich macht des Herren Segen, und nicht bereichert eigene Mühe so wie er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Die Schandtat dünkt dem Toren nur ein Scherz, dem klugen Mann jedoch ein Übermut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Wovor dem Frevler graut, gerade das trifft ihn, und so erfüllet er der Frommen Wunsch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'So wie ein Sturm vorüberbraust und nicht mehr ist, so auch der Frevler; der Fromme aber steht auf ewig festem Grund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Was Essig für die Zähne, was Rauch ist für die Augen, das ist der Faule seinem Auftraggeber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Die Furcht des Herrn vermehrt die Lebenstage; der Frevler Jahre aber werden oft verkürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Der Frommen Harren wird in Freude enden; der Frevler Hoffnung wird zunichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Schutzwehr für Redliche, das ist des Herren Walten, für Übeltäter aber Grund zur Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Ein Frommer wird in Ewigkeit nicht wanken; die Frevler aber werden nicht im Lande bleiben dürfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Des Frommen Mund nimmt zu an Weisheit; dem Untergang verfällt die falsche Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Des Frommen Lippen kennen Gütigkeit, der Mund der Frevler aber Hinterlist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Ein Greuel für den Herrn ist falsche Waage; ein richtiges Gewicht gefällt ihm wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kommt auf der Übermut, kommt auch Verachtung; mit den Bescheidenen kommt Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Der Gerechten Unschuld spendet ihnen Ruhe; der Frevler Falschheit tötet sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Am Zornestag nutzt kein Besitz; vom Tod errettet Almosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Die Frömmigkeit der Frommen ebnet ihm den Weg; der Frevler stürzt durch seine Schlechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Der Redlichen Gerechtigkeit errettet sie; die Frevler werden durch die Schlechtigkeit gefangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Jedwede Hoffnung endet mit des Frevlers Tod, und die Erwartung aus den Sünden wird zunichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Wer Recht erhalten, ist von Not erlöst; an seine Stelle kommt der Gegner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Der Frevler sucht durch Reden seinen Gegner zu vernichten; doch die im Rechte, werden durch die Einsicht auch gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Es jauchzt die Stadt ob ihrer Frommen Glück, und Jubel gibt es bei der Frevler Untergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Der Staat blüht durch den Segen Redlicher; durch Frevler Mund geht er zugrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Der Tor spricht voll Verachtung wider seinen Gegner; der Kluge aber schweigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Geheimnisse verrät der Neuigkeitenkrämer; der Zuverlässige behält für sich die Sache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Wenn\'s an der Führung fehlt, dann kommt ein Volk zu Falle; gut aber steht\'s, wo viele sind der Ratgeber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Sehr schlimm kann\'s dem ergehen, der sich für einen anderen verbürgt; doch sicher bleibt, wer nicht den Handschlag liebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Wie ein verführerisches Weib an Schmuck sich klammert, so klammern sich an Reichtum die Gewalttätigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Wer Gutes tut, der tut sich selber Gutes; wer harten Herzens ist, der schneidet sich ins eigene Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Der Frevel bringt nur nichtigen Lohn; der Tugend Lohn ist wahrer Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Festhalten an der Tugend führt zum Leben; das frevelhafte Tun bringt sichern Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Ein Greuel sind dem Herrn all, die verkehrten Herzens sind; sein Wohlgefallen haben, die unsträflich wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Untrüglich ist\'s: Nicht straflos bleibt der Böse; doch frei geht das Geschlecht der Frommen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Ein goldener Ring im Rüssel eines Schweines ist ein Weib, das schön, doch ohne Scham.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Der Frommen Wunsch geht nur aufs Nötige; der Frevler Sehnen ist das Übermaß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Der eine teilt sehr reichlich aus und wird noch reicher; ein andrer spart am Nötigen und wird noch ärmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Ein dankbares Gemüt wird überhäuft mit Gutem; wer Wohltaten erweist, empfängt auch solche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Wer Korn zurückhält, diesem flucht das Volk; wer aber Korn verkauft, auf dessen Haupt kommt Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Wer Gutes anstrebt, zielt auf Wohlwollen; wer aber Böses sucht, auf den kommt\'s auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Wer nur auf Reichtum sich verläßt, verwelkt; die Frommen aber grünen so wie grünes Laub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Wer seine eigene Familie darben läßt, wird Wind erwerben; der Tor wird Sklave dessen, der klüger ist als er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Ein Lebensbaum ist des Gerechten Frucht; wer Seelen an sich zieht, ist weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Wenn schon den Frommen trifft auf Erden die Vergeltung, um wieviel mehr den Frevler und den Sünder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Wer Mahnung liebt, liebt auch Erkenntnis; wer aber Rüge haßt, ist töricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Der gute Mann erhält vom Herrn, was er für\'s Leben braucht, der Bauernfänger nur erschwindelt es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Kein Mensch kommt zum Bestand durch Frevel; der Frommen Wurzel aber wanket nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ein wackeres Weib ist seinem Gatten eine Krone; ein schändliches ist ihm wie Wurmfraß in den Knochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Gedanken frommer Leute zielen auf das Recht, der Frevler Pläne auf Betrug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Der Frevler Worte stellen selbst dem Blute nach; der Frommen Mund errettet es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Wenn Frevler stürzen, daß sie nicht mehr sind, dann hat der Frommen Haus Bestand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Gelobt wird nach der Klugheit Maß ein Mann; doch der verschrobenen Verstandes, wird verachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Weit besser, wer geringen Stands, doch einen Sklaven halten kann, als wer sich vornehm dünkt und brotlos ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Der Fromme sorgt sich für sein Vieh, für alles, was ihm not tut; das Herz des Bösen aber ist erbarmungslos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Wer seinen Acker baut, hat Brot in Fülle; wer nichtigen Dingen nachgeht, ist ein Tor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Der Bösen Höhen ist des Frevlers Wunsch; die Frommen aber gründen tief./');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Durch Widerspruch fängt sich der Frevler; der Not entkommt der Fromme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Der Edelmann labt sich an schönen Reden; entlohnt wird der Gewöhnliche für seiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Dem Toren scheint sein Weg der richtige; der Weise aber hört auf Rat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Ein Tor läßt seinen Zorn den ganzen Tag durch merken: doch den Verdruß verbirgt der Kluge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Wer Wahrheit meldet, spricht, was sich bewährt: ein falscher Zeuge macht Enttäuschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Gar manche führen Reden gleich den Stichen eines Schwerts; doch Heilung bringt des Weisen Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Wahrheitsgemäße Rede hat für immer Geltung; nur einen Augenblick behauptet sich die falsche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Enttäuschung kommt ins Herz der Unheilplanenden, doch Freude denen, die das Wohlergehen fördern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Dem Frommen fällt nie Böses ein; die Frevler aber sind voll Bosheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Ein Greuel für den Herrn sind falsche Lippen; doch die wahrhaftig handeln, sind ihm angenehm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ein kluger Mann verbirgt sein Wissen; das Herz der Toren sprudelt Törichtes hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Die Hand der Fleißigen wird herrschen; die lässige wird fronen müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Ein Kummer in des Menschen Herzen drückt es nieder; ein freundlich Wort verwandelt es in Fröhlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Der Fromme sucht und findet seine Nahrung; der Weg der Frevler führt sie irre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Die Faulheit bringt nicht ihre Nahrung auf, der Fleißige jedoch ein groß Vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Zum Leben kommt man auf der Tugend Pfad; der Weg des Truges führt zum Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Der Weise achtet auf die väterliche Mahnung; der Spötter hört auf keinerlei Verweis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Der Gute nährt sich von der Hilfe anderer, die Gier der Bösewichter von Gewalttat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Wer seinen Mund behütet, wahrt sein Leben; wer seine Lippen aufreißt, dem droht Untergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Der Faule will und will doch nicht; der Arbeitsame aber wird gar reich gelabt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Die Lüge haßt der Fromme; die Sünde bringt nur Schimpf und Schande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Des Weges Sicherheit bewacht die Tugend; das Laster aber läßt zum Fall den Fehltritt führen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Der eine stellt sich reich und hat doch nichts; der andere stellt sich arm und hat ein groß Vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Schon mancher mußte durch viel Geld sein Leben retten; wer arm ist, hört nie eine Drohung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Das Licht der Frommen leuchtet; der Frevler Leuchte muß erlöschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Im Übermut allein kommt es zu Tätlichkeiten; doch Weisheit findet sich bei Klugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Vermögen schwindet, das durch nichts erworben wird; doch wer durch Arbeit es erwirbt, vergrößert es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Ein lang dahingezogenes Hoffen macht das Herz erkranken; ein Lebensbaum ist der erfüllte Wunsch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Wer vor Befehlen keine Scheu besitzt, der schädigt sich; wer aber Ehrfurcht vor Geboten hat, wird nicht behelligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Des Weisen Lehre ist ein Lebensborn, wo\'s gilt, den Fallstricken des Todes zu entgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Ein fein Benehmen bringt in Gunst; der Sünder Wandel führt zum Abgrund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Ein kluger Mann tut alles recht geschickt; der Tor entwickelt Torheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Der frevelhafte Bote stürzt sich selbst ins Unglück; ein treuer Bote tut sich selber wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Armut und Schande werden dem zuteil, der Zucht verwirft; wer auf die Rüge achtet, wird geehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Verbotener Genuß ist süß; dem Toren ist\'s darum ein Greuel, vom Bösen abzulassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Gehst du mit Weisen um, wirst du weise! Wer\'s mit den Toren hält, dem geht es schlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Unglück verfolgt die Sünder; den Frommen gibt man zur Belohnung Gutes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Ein Guter hinterläßt sein Erbe Kindeskindern; des Sünders Habe ist dem Frommen vorbehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Das Prozessieren frißt der Armen mühevoll bestellte Äcker, und mancher stirbt, bevor das Urteil kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Wer seine Rute schont, der liebt nicht seinen Sohn; doch wer ihn liebt, der sucht ihn heim mit Züchtigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Der Fromme ißt, bis daß er satt; der Frevler Bauch hat nie genug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Ein Haus baut sich Frau Weisheit; die Torheit reißt\'s mit ihrer Hand zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Wer in Geradheit wandelt, der hat Furcht vorm Herrn; wer krumme Wege geht, verachtet ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Im Torenmund liegt eine Angelrute; den Weisen dienen ihre Lippen zur Bewahrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Wenn keine Rinder da, so bleibt die Krippe sauber; doch durch der Stiere Kraft wird reichlicher Ertrag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Nicht trügt der Wahrheit Zeuge; doch Lügen spricht der falsche Zeuge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Nach Weisheit sucht der Spötter, doch vergeblich; Erkenntnis ist für Kluge etwas Leichtes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Geh aus dem Weg dem Toren! Dann mußt du nicht Bekanntschaft mit dem Anwalt machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Des Klugen Vorsicht ist es, auf den Weg zu achten; der Toren Leichtsinn bringt Enttäuschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Die Schuld vermittelt zwischen Schurken, und zwischen Redlichen der gute Wille.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Das Herz kennt seinen Seelenschmerz am besten; und auch in seine Freude kann ein Fremder sich nicht mischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Das Haus der Frevler wird vertilgt; der Redlichen Gezelt erblüht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Gar mancher Weg dünkt einem Mann gerade; doch schließlich sind es Todeswege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Sogar beim Lachen kann das Herz sich grämen; der Freude Ende ist oft Gram.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Der Eingebildete wird satt von seinen Wegen, der Tüchtige von seinen Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Der Törichte traut jedem Ding; ein kluger Mann geht einer Sache auf den Grund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Der Weise fürchtet sich und meidet die Gefahr; der Tor geht eine Wette mit ihr ein und fühlt sich sicher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Der Ungeduldige macht Törichtes; ein ränkevoller Mensch wird nur gehaßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Die Toren haben Torheit im Besitz; der Klugen Diadem ist Einsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Vor Gutem müssen sich die Schlechten beugen, und Frevler sitzen an des Frommen Türen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Selbst seinem Freunde ist der Arme widerwärtig; doch derer, die den Reichen lieben, sind es viele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Wer seinen Nächsten nicht beachtet, der versündigt sich; wohl dem, der sich der Elenden erbarmt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Die Böses planen, täuschen sich auch gegenseitig; doch Lieb und Treue herrscht bei denen, die da Gutes planen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Durch Arbeit nur schafft man Gewinn, doch bloßes Reden führt zu nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Der Klugen Diadem ist ihre Klugheit; der Toren Diadem ist Torheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Ein Lebensretter ist der Wahrheit Zeuge; wer Lügen spricht, bewirkt Enttäuschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'An Gottesfurcht besitzt man eine starke Burg; so kann man Schutz den eigenen Kindern bieten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Die Furcht des Herrn - ein Lebensborn, daß man des Todes Stricke meide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Des Königs Ruhm besteht in seines Volkes Massen; vom Leutemangel kommt des Fürsten Sturz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Wer langmütig, ist reich an Einsicht; wer ungeduldig, steigert seine Torheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Des Leibes Leben ist gelassener Sinn; wie Wurmfraß im Gebein ist Leidenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Wer den Geringen drückt, der lästert dessen Schöpfer; doch wer des Armen sich erbarmt, der gibt ihm Ehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Der Frevler wird durch seine Schlechtigkeit gestürzt; der Fromme hat bei seinem Tod noch Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'In eines Klugen Herzen ruht die Weisheit stille; sie wird verurteilt bei den Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Die Tugend führt ein Volk zur Höhe; Krebsschaden der Nationen ist das Laster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Die Huld des Königs sollte einem tüchtigen Diener werden; sein Grimm den Unbrauchbaren treffen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Gelinde Rede stillt den Grimm; verletzend Wort erregt den Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Des Weisen Zunge kleidet guten Sinn in schöne Form; der Mund des Toren spricht die nackte Torheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'An jedem Orte sieht des Herren Aug die Bösen und die Guten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Der Zunge Milde ist ein Lebensbaum; doch wenn darauf Verkehrtheit liegt, wirkt sie verstörend auf den Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Der Tor verschmäht die väterliche Zucht; wer auf die Rüge achtet, handelt klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Im Haus des Frommen findet Vorrat sich in Fülle; doch in des Frevlers Ernte liegt Zerrüttung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Der Weisen Lippen zeugen Wissen, doch nicht das Herz der Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Der Frevler Opfer ist ein Greuel für den Herrn; doch das Gebet der Redlichen gefällt ihm wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Der Weg der Frevler ist ein Greuel für den Herrn; das Streben nach der Tugend hat er gern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Dem, der vom Pfade weicht, ist Rüge nicht willkommen; wer aber Mahnung haßt, muß sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Ganz offen liegen Unterwelt und Abgrund vor dem Herrn; um wieviel mehr der Menschen Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Der Spötter liebt nicht, daß man ihn vermahne; er geht nicht zu den Weisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ein fröhlich Herz macht auch das Antlitz freundlich; bedrückt ist das Gemüt bei Herzenskummer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Erkenntnis sucht des Klugen Herz; auf Torheit geht der Toren Miene aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Wohl sind des Armen Tage alle böse; doch ist er heiteren Gemüts, hat er beständig Festgelage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Viel besser, wenig zu besitzen in der Furcht des Herrn, als reiche Schätze und dabei ein bös Gewissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Viel besser ein Gericht Gemüse und dabei auch Liebe, als ein fettes Rind und Haß dabei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Ein hitziger Mann erregt den Zank; wer aber sanft ist, stillt den Hader.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Der Weg des Furchtsamen gleicht einer Dornenhecke; der Pfad des Aufrechten ist wohl gebahnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Ein weiser Sohn versorgt den Vater reichlich; ein dummer Mensch vernachlässigt die Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Die Torheit bringt dem Unverständigen Gefahr; doch ebenen Weg geht der Vernünftige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Die Pläne schlagen fehl, wo die Beratung fehlt; sind aber der Berater viel, so kommen sie zustande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Ein jeder hört sich selber gern. Ein Wort zur rechten Zeit, wie selten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Hier oben gibt es für den Klugen einen Lebensweg, damit er fern sich hält dem Abgrund drunten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Wegreißt der Herr der Stolzen Haus; der Witwe Eigentum läßt er bestehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Ein Greuel für den Herrn sind boshafte Gedanken; doch rein sind Worte, freundlich ausgesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Es läßt der Geizhals die Familien darben; wer auf Vermögen nicht versessen ist, ernährt sie wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Die Antwort überlegt des Frommen Herz; des Frevler Mund spricht unumwunden Bosheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Den Gottlosen ist fern der Herr; doch das Gebet der Frommen achtet er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Ein freundlich Anblicken erfreut das Herz, und frohe Kunde labt den Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ein Ohr, das auf die Mahnung hört, die Leben spendet, weilt gerne mitten unter Weisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Wer Zucht verachtet, wirft sein Leben weg; doch wer auf Rüge hört, erkauft sich Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Die Furcht des Herrn ist Grundlage der Weisheit, der Ehre geht voran die Demut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Dem Menschen mag das Denken eignen; vom Herrn kommt die Beredsamkeit der Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Erklärt für lauter alle seine Wege auch der Mensch, der Herr ist\'s, der die Geister wägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Dem Herrn enthülle deine Werke! Rechtschaffen sind dann deine Pläne auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Für einen, den er strafen will, erschafft der Herr Beliebiges, selbst einen Frevler für den Tag der Strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Ein Greuel für den Herrn ist jeder Übermütige. Untrüglich ist\'s: er bleib nicht ungestraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Durch treue Liebe wird die Sündenstrafe abgewandt; und in der Furcht des Herrn vermeidet man das Böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Findet der Herr Gefallen an den Wegen eines Mannes, dann müssen seine Feinde selbst mit ihm in Frieden leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Viel besser wenig in Gerechtigkeit als großes Einkommen mit Unrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Des Menschen Herz erdenkt sich seinen Weg; doch seine Schritte lenkt der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Des Königs Ausspruch ist Orakelspruch, und so vergreift sich nicht sein Mund beim Urteilsprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Die Waage, wie das rechte Wägen, kommt vom Herrn; sein Werk sind die Gewichte all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Ein frevelhaftes Handeln sollte Königen ein Greuel sein; denn durch Gerechtigkeit nur wird der Thron befestigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Wahrhaftige Lippen sollten einem König wohl gefallen; er sollte lieben, die die Wahrheit reden! /');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Des Königs Grimm: ein Todesbote! Ein weiser Mann versteht\'s, ihn zu besänftigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Des Königs freundlich froher Blick schafft Leben; der Frühlingsregenwolke gleicht sein Wohlgefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Viel besser Weisheit zu erwerben als feines Gold! Erwerb von Einsicht ist dem Silber vorzuziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Der Frommen Bahn besteht im Böses-Meiden; sein Leben wahrt, wer acht auf seinen Wandel hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Hochmut kommt vor dem Fall und Stolz vor Untergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Viel besser ist\'s, betrübt zu sein mit Duldern, als Beute mit den Übermütigen zu teilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Wer acht gibt auf das Wort, der findet Glück, und wer dem Herrn vertraut: Heil ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Ein Denker zieht nur den Gelehrten an; doch wohlberedte Lippen machen groß den Hörerkreis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Ein Lebensborn ist Unterweisung derer, die dafür empfänglich; doch Torheit ist\'s, die Toren zu belehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Des Weisen Herz macht seinen Mund gar klug und mehrt auf seinen Lippen die Belehrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Huldvolle Reden sind wie Honigseim; sie sind der Seele eine Süßigkeit und Labsal für den Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'So mancher Weg dünkt einem Mann gerade; doch schließlich sind es Todeswege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Des Arbeiters Verlangen schafft für ihn; sein Mund drängt ihn dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Der Teufelsmann vergräbt die Absicht; auf seinen Lippen aber lodert Feuersglut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Ein ränkesüchtiger Mann macht Streitigkeiten; ein Ohrenbläser bringt vertraute Freunde auseinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Gewalttat übt schon, wer den Nächsten nur verführt und ihn auf keinen guten Weg geleitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Wer seine Augen zukneift, tut\'s um Lügen zu ersinnen; wer seine Lippen aufeinander preßt, ist fertig mit dem bösen Plan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Ein herrlich Diadem ist graues Haar; nur auf dem Weg der Tugend wird\'s gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Weit tapfrer sind die Langmutsvollen als des Krieges Helden, und tapfrer die des eigenen Gemütes Herr als die Eroberer von Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'In des Gewandes Falten wirft man zwar das Los; doch von dem Herrn kommt sein Entscheid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Viel besser ist ein trockner Bissen, dabei Frieden, als voll ein Haus von Fleisch und dabei Zank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Ein guter Knecht wird einem unbrauchbaren Sohne vorgezogen, und unter Brüdern kann er Eigentum verteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Der Tiegel dient fürs Silber, für das Gold der Ofen; die Herzen aber prüft der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Der Bösewicht horcht auf heillose Rede; der Lügner lauscht auf der Verderbers Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Wer einen Armen auslacht, lästert dessen Schöpfer; wer sich beim Unglück freut, der bleibt nicht straflos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Der Alten Diadem sind Kindeskinder; der Kinder Ruhm sind ihre Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Nicht kommt dem Toren edle Rede zu, noch weniger dem Edlen Lügensprache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Ein Zauberstein ist das Geschenk nach des Empfängers Ansicht; er schaut, wozu er es verwenden könnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Wem an der Freundschaft liegt, der sucht die Fehler zu verhüllen; doch wer den Fehler wiederholt, entfremdet sich den Freund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Verweis schreckt einen Klugen mehr als einen Toren hundert Schläge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Nur Widersetzlichkeit erstrebt der Schlechte; doch wird ein bitterer Bote gegen ihn gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Begegnet einem eine Bärin, ihrer Jungen jüngst beraubt, noch lieber als ein Törichter in seinem Wahn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Wer Gutes heimbezahlt mit Bösem, von dessen Haus geht nicht das Unglück fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Wie den Wassern Bahnen öffnen, so der Anfang eines Streites. Bevor der Streit beginnt, laß ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Wer freispricht den, der Unrecht hat, und den verdammt, der Recht besitzt, ein, Greuel für den Herrn sind diese beiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Was hilft der Kaufpreis in des Toren Hand? Er könnte Weisheit sich erwerben; doch fehlt ihm der Verstand dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Zu jeder andern Zeit liebt der Gefährte dich; doch für die Zeit der Not ist nur der Bruder da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Ein unverständiger Mensch ist der, der Handschlag gibt und seinem Nächsten gegenüber sich verbürgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Ein blaues Auge hat der gern, der Händel liebt; wer freche Reden führt, sucht Schläge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Nicht findet Glück, wer ein verkehrtes Herz besitzt; wer sich mit seiner Zunge windet, der gerät ins Unglück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Wer einen Toren zeugt, dem bringt es Grämen; der Vater eines Narren freut sich nimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ein fröhlich Herz macht wohlgenährt; den Leib abmagern läßt ein kummervoll Gemüt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Geschenk wird aus dem Busen eines Frevlers angenommen, gilt es, des Rechtes Pfad zu beugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Dem Klugen steht vor Augen Weisheit; des Toren Augen wandern bis ans Erdenende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Ein dummer Sohn ist Ärger für den Vater, ein bitterer Kummer auch für die, die ihn geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Mit Geld den Frommen zu bestrafen, ist schon unrecht. Um wieviel mehr ist\'s unrecht, Vornehme zu schlagen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Wer mit den Worten an sich hält, ist einsichtsvoll; wer kühlen Sinns, ein kluger Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Ein Tor kann durch sein Schweigen für einen Weisen gelten, für einen klugen Mann, verschließt er seine Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Den Eigenwillen sucht, wer sich absondert; bei jeglicher Gelegenheit beginnt er Streit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Der Tor hat kein Gefallen an Belehrung; er möchte nur die eigene Meinung künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Wo Frevel auftritt, dort tritt auch Verachtung auf, und Schmähung ist mit Hohn vereint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Aus eines Mannes Munde tiefe Worte sind Gewässer, ein Strom, der aus dem Born der Weisheit sprudelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Daß man Partei für einen Frevler nimmt, daß man das Recht des Frommen beugt, nützt nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Des Toren Lippen schaffen Streit; nach Schlägen ruft sein Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Des Toren Mund führt seinen Sturz herbei, und seine Lippen sind ein Strick für seinen Hals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Des Ohrenbläsers Worte sind wie Hammerschläge; sie dringen tief ins Herz hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Wer lässig bei der Arbeit ist und wer den eigenen Besitz zerstört, sind Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Ein fester Turm des Herren Name; der Fromme läuft zu ihm und ist gesichert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Des Reichen Habe ist ihm eine feste Stadt, wie eine hohe Mauer um ihn her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Stolz geht dem Sturz voran, der Ehre Demut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Gibt jemand Antwort schon, bevor er recht verstanden, so rechnet man es ihm als Torheit und als Schande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Ein männliches Gemüt kann seine Leiden meistern. Ein düsteres Gemüt, wer mag\'s erträglich finden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Des Klugen Herz erwirbt sich Einsicht; Einsicht sucht auch des Weisen Ohr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Geschenke schaffen ihrem Geber Raum und öffnen ihm den Zutritt zu den Großen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'In einem Streite hat der erste Recht; da kommt der andere und untersucht\'s aufs neue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Den Streitigkeiten macht das Los ein Ende; es trennt die Streitenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Ein Bruder kann an einer Festung sich vergehen, sind Streitigkeiten doch, was eine Bresche für die Burg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Mit seines Mundes Frucht ersättigt jeder seinen Magen, von seiner Lippen Ernte kann er satt sich essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'In dem Bereich der Zunge liegen Tod und Leben, und wer sie gern gebraucht, genießt auch ihre Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Wer je das Weib erforscht, hat einen guten Fund getan, und er erfreut sich der besonderen Huld des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Der Arme redet weinerlich; der Reiche aber spricht mit Nachdruck.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Gefährten gibt\'s, die gegenseitig sich zugrunde richten; und Freunde gibt\'s, anhänglicher als Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Ein Armer, der in Einfalt wandelt, ist viel besser als einer mit gezierter Rede, dazu dumm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Ausruhen ohne Grund ist auch nicht gut; doch wer sich überstürzt, tritt sicher fehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Zerstört des Menschen eigene Torheit seinen Weg, so zürnt sein Herz dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Der Reichtum schafft stets neue Freunde; wer aber arm, von dem trennt sich sein Freund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ein falscher Zeuge bleibt nicht ungestraft, und nicht entkommt, wer Lügen spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Es buhlen viele um des Mannes Gunst, der geben kann; doch keinen Freund besitzt, wer selbst bedürftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Den Armen mag von seinen Brüdern keiner; selbst seine Freunde bleiben fern von ihm. Wer Worten nachjagt, dem gereichen sie zu nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Wer sich Verstand erwirbt, der liebt sein Leben, und wer Vernunft bewahrt, der findet Glück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Ein falscher Zeuge bleibt nicht ungestraft; wer Lügen vorbringt, geht zugrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Wohlleben frommt dem Toren nicht, noch weniger dem Sklaven der Genuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Langmut zeuget vom Verstande eines Menschen; das Übersehen der Verfehlung ist sein Ruhm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Des Königs üble Laune ist wie Knurren eines jungen Löwen; doch seine Huld, was Tau für Pflanzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ein Unglück für den Vater ist ein dummer Sohn; ein zänkisch Weib ist wie der Regen, der eindringt in ein Haus und draus vertreibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Von seinen Vätern erbt man Haus und Gut; vom Herrn jedoch kommt ein verständig Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'In tiefen Schlaf versenkt die Faulheit; ein Lässiger wird Hunger leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Wer Achtung vor Befehlen hat, bewahrt sein Leben; wer seine Pflicht vernachlässigt, wird mit dem Tod bestraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Wer sich erbarmt des Armen, leiht dem Herrn, und seine Guttat lohnt er ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Straf deinen Sohn! Dann gibt\'s noch Hoffnung. Bekümmre dich nicht um sein Weinen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, '\"Wer gar zu weit im Zorne geht, der muß es büßen.\" Im Gegenteil! Errette ihn und rett ihn immer wieder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Hör auf den Rat! Nimm an die Mahnung, auf daß du in der Zukunft weise seist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Der Pläne in des Mannes Herzen mögen viele sein; der Plan des Herrn allein geht in Erfüllung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Beim Menschen ist begehrenswert Wohltätigkeit; doch besser ist ein Mensch, der nichts besitzt, als der, der lügenhaft verspricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Zum Leben dient die Furcht des Herrn; der Hochmut murrt, daß nicht das Böse wird bestraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Wenn seine Hand der Faule in die Schüssel steckt, so mag er sie zum Mund nicht bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Wenn du den Spötter schlägst, so kann der Dumme dadurch weise werden. Vermahnst du einen Klugen, kann er dadurch weise werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Wer seinen Vater elend macht und seiner Mutter Herz durchbohrt, der ist ein Sohn, der schimpflich und erbärmlich handelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Mein Sohn, laß ab, auf Mahnungen zu hören, die nur geschehn, um gute Lehren in den Wind zu schlagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Des nichtswürdigen Zeugen spottet die Gerechtigkeit; der Trug verwickelt frevelhaften Mund in Widerspruch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Bereit sind Schläge für die Spötter und Hiebe für des Toren Rücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Ein Spötter ist der Wein, ein Lärmer Bier; wer davon taumelt, ist nicht klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Wie eines jungen Löwen Knurren ist des Königs Unwillen; wenn er in Zorn gerät, verwirkt man schon sein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Für einen Mann ist\'s eine Ehre, einem Streite fernzubleiben, und nur ein Tor tut sich hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Im Herbste pflügt der Faule nicht; wenn er dann in der Ernte nachfragt, ist nichts da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Wie Wasser in der Tiefe, ruht der Plan im Herzen eines Mannes; ein kluger Mann weiß es zu schöpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Gar mancher muß den Mann herbeirufen, dem Gutes er getan. Denn einen Dankbaren, wer kann ihn finden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Wenn jemand in Gerechtigkeit und Unschuld lebt, den ahmen seine Kinder nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ein König auf dem Richterstuhle der Gerechtigkeit soll mit den Augen jeden Übeltäter aufspüren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Wer könnte sagen: \"Gereinigt habe ich mein Herz, von meiner Lieblingssünde frei gemacht!\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Zweifach Gewicht und zweifach Maß, sie beide sind dem Herrn ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Ein Knabe schon gibt sich in seinen Taten zu erkennen, ob krumm, ob grade wird sein Tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Das hörend Ohr, das sehend Auge, sie beide hat der Herr gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Lieb nicht den Schlaf, damit du nicht verarmst! Mach schon die Augen auf, solang du Brot in Fülle hast!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '\"Wie schlecht, wie schlecht!\" sagt da ein Käufer; doch ist es sein geworden, rühmt er sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Hat man auch Gold und Perlen eine Menge, ein gläsernes Gefäß ist eines Anwalts Rede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Wer einem andern bürgt, dem kann sein eigen Kleid genommen werden; gepfändet wird er Fremder wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Süß schmeckt dem Mann das Brot der Lüge; doch hintendrein füllt sich sein Mund mit Kieselstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Die Pläne prüfe durch Beratung! Mit Klugheit führe Krieg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Geheimnisse verrät, wer stets auf Wanderschaft. Drum gib mit Plaudermäulern dich nicht ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Wer auf den Vater und die Mutter wenig gibt, des Licht verlöscht im Dunkeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Besitz, zu Anbeginn in Hast erworben, bleibt doch am Ende ohne Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Sprich nicht. \"Ich muß den bittern Kelch zur Neige trinken.\" Nein, hoffe auf den Herrn! Er kann dir helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Ein Greuel für den Herrn ist zweierlei Gewicht; nichts nützt die falsche Waage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Des Mannes Schritte sind vom Herrn bestimmt; wie kann ein Mensch sich selber seinen Weg bestimmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Gefährlich ist\'s für Menschen, Heiliges vorschnell zu versprechen und nachher das Gelobte wiederum zu überlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Ein weiser König späht die Frevler aus, vergilt an ihnen Unordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Des Menschen Geist ist vor dem Herren licht, und er durchforscht sein Innerstes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Der König hütet immerwährend Huld; durch Liebe stützt er seinen Thron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Der Ruhm der Jünglinge ist ihre Stärke; der Greise Schmuck ist graues Haar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Wenn eine Wunde schwärt, Umschläge bringen Linderung, so Schläge auch dem Herzensgrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Den Wasserbächen gleich ist in der Hand des Herrn des Königs Herz; Er lenkt\'s, wohin er will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Dem Mann scheint jeder seiner Wege recht zu sein; jedoch der Herr ist\'s, der die Herzen wägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Gerechtigkeit und Recht ausüben liebt der Herr viel mehr denn Schlachtopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Ein großer Ehrgeiz und Verstand entflammen Frevler zum Vergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Allein des Arbeitsamen Pläne führen zum Gewinn; der Hastige bringt\'s nur zum Verlust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Wer sich durch Lügenzunge Schätze sammelt, strebt nach verwehtem Hauch, ja, nach dem Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Für Frevler hat das Unrecht einen Reiz; sie weigern sich zu tun, was recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Mag eines Mannes Tun verwickelt sein und schief verlaufen, doch ist er redlich, handelt er doch recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Viel lieber in dem Winkel eines Daches ruhen, als ein gemeinsam Haus mit einem Weib, das zänkisch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Des Frevlers Seele hat am Bösen ihre Lust, und nicht verhaßt ist ihm die böse Tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Wenn man den Spötter büßen läßt, dann kann der Dumme dadurch weise werden. Behandelt man den Weisen rücksichtsvoll, kann jener dadurch auch zur Einsicht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Wenn auf des Frevlers Haus der Fromme Rücksicht nimmt, verleitet er den Frevler wiederum zum Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Wer vor des Armen Hilferuf sein Ohr verstopft, der findet kein Gehör dann, wenn er selber ruft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Im stillen eine Gabe kann den Zorn besänftigen, ein heimliches Geschenk den größten Grimm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Dem Frommen ist es eine Freude, wenn ihm nach Recht geschieht; den Bösewichtern ist\'s ein Schrecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ein Mensch, der von der Klugheit Wege irrt, wird Ruhe erst im Schattenreiche finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Wer Lustbarkeiten liebt, der fühlt sich stets im Mangel; wer Wein und Öl zu gerne hat, wird nimmer reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Das Sühnegeld des Frommen ist der Frevler; an Stelle der Rechtschaffenen tritt der Verbrecher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Viel besser, einsam in der Wüste leben, als in Gesellschaft eines zank- und händelsüchtigen Weibes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'An Öl und köstlichem Getränk ist in des Weisen Haus ein Vorrat; ein Tor läßt sie verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Wer nach Gerechtigkeit und Güte strebt, der findet Leben, Rechtlichkeit und Ehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Der Helden Stadt erstieg ein Weiser; das Bollwerk stürzte ein, dem sie sich anvertraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Wer seinen Mund und seine Zunge hütet, der schützt sein Leben vor Gefahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Ein Spötter heißt, wer übermütig und vermessen ist und wer im Übermaß des Stolzes handelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Den Faulen tötet sein Gelüste; denn seine Hände weigern sich zu schaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Den ganzen Tag begehrt nur, wer begehrlich; der Fromme spendet ohne Unterlaß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Des Frevlers Opfer ist ein Greuel und vollends, bringt er es in schnöder Absicht dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Ein falscher Zeuge geht zugrunde; dagegen redet sieghaft ein glaubwürdiger Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Der Frevler macht ein frech Gesicht; der Biedere verbessert seinen Wandel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Nicht Weisheit gibt\'s, nicht Einsicht, Rat nicht vor dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Das Roß ist abgerichtet für den Tag der Schlacht; jedoch der Sieg kommt von dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Ein guter Name: wünschenswerter ist er als der Reichtum, ein fein Benehmen mehr als Gold und Silber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Zwar Reich und Arm sind Gegensätze; doch alle beide hat der Herr geschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Der Kluge sieht das Unglück und verbirgt sich; die Toren gehen weiter, kommen aber so zu Schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Der Demut Lohn, der Lohn der Furcht des Herrn ist Reichtum, Ruhm und Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Dornen und auch Schlingen sind auf eines Falschen Weg. Fern bleibe ihnen, wer sein Leben wahren will!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Erziehe einen Knaben nur nach dem für ihn bestimmten Weg! Dann geht er auch im Alter nimmer davon ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Der Reiche ist der Herr des Armen; wer borgt, ein Sklave dessen, der ihm leiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Wer Unrecht sät, wird Unheil ernten, und seines Zornes Rute reibt ihn auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Gelobt wird der Leichtlebige; er gibt von seinem eigenen Brot dem Armen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Treib nur den Spötter weg! Dann schwindet auch der Zank. Ein Ende nehmen Streit und Schimpf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Wer Herzensreinheit liebt und anmutsvolle Rede, bekommt zum Freund den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Des Herren Augen wachen über die Erkenntnis; er bringt des Frevlers Wort zu Falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Der Faule spricht: \"Ein Löwe könnte draußen sein; ich könnte mitten in den Straßen eines Mordes Opfer werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Ein frevelhafter Mund ist eine tiefe Grube; wer von dem Zorn des Herrn getroffen, fällt hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Die Torheit wurzelt in des Knaben Herzen tief; die Zuchtrute treibt sie ihm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Man übervorteilt einen Armen, um sein eigen Gut zu mehren; doch schenkt man einem Reichen, tut man es zu dessen Schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Neig her dein Ohr! Hör auf des Weisen Worte! Richt auf meine Lehre deinen Sinn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Gar schön bewahrst du sie in deinem Herzen, wenn sie verwahrt dir auf den Lippen liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Auf daß sich dein Vertrauen auf den Herren stütze, belehre ich dich heute selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Die Dreißig, hab ich nicht aufgezeichnet sie für dich zu wohlbedachten Überlegungen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Ich lehre dich in Wahrheit nur wahrhaftige Worte und gebe dir auf deine Fragen zuverlässige Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Beraube den Schwächsten nicht, weil man ihm leicht beikommen kann! Zermalme nicht den Armen, weil er wehrlos ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Denn ihre Sache führt der Herr; die sie betrügen, die betrügt auch er ums Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Gesell dich nicht den Zornigen zu! Mit einem Hitzkopf hab nicht Umgang!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Sonst lernst du seinen Wandel und bringst sein Leben in Gefahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Sei nicht bei denen, die da Handschlag geben, bei denen, die für Schulden bürgen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Wenn du nichts hast, um zu bezahlen, wird dir dafür das Bett genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Verrücke nicht uralte Satzungen, die deine Väter einst gemacht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Siehst du, wie gar geschickt ein Mann bei seiner Arbeit ist, dann kann er nur bei Königen bestehen, nicht bei Sparsamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Wenn du beim Mahl bei einem Fürsten sitzest, gib acht auf das, was man dir vorsetzt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Nur wenig leg dir in den Teller, falls du die Gier beherrschen willst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Nach Leckerbissen hege kein Gelüste! Es kann dies eine Speise der Enttäuschung sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Bemüh dich nicht um Reichtum! Steh ab davon aus Klugheit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Denn, schaust du nach ihm aus, ist er nicht da; er schafft sich Adlerflügel an und fliegt gen Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Mit einem Menschen voller Mißgunst speise nicht! Nach seinen Leckerbissen hege kein Gelüste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Denn wie ein Ekel beim Genuß ist es mit diesem: \"Iß doch und trink!\" sagt er zu dir; er aber meint\'s mit dir nicht ehrlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Den Bissen, den du issest, sollst du wieder ausspeien, verderben dir die guten Sachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Red nicht vor eines Toren Ohren! Denn er verachtet deiner Rede klugen Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Verrück die Grenze nicht der Kinder! Mach keinen Eingriff in der Waisen Äcker!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Denn der sie schützt, ist stark, führt ihre Sache wider dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Was über Zucht ich sage, merk dir wohl! Auf einsichtsvolle Rede höre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Entzieh nicht deinem Knaben seine Züchtigung! Wenn du ihn mit der Rute schlägst, so stirbt er nicht daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du schlägst ihn mit der Rute zwar; doch rettest du sein Leben vor der Hölle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mein Sohn! Wird weise je dein Herz, dann bin auch ich in meinem Herzen fröhlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Mein Innerstes frohlockt, wenn deine Lippen reden das, was recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Es eifere nicht dein Herz den Sündern nach, es streb vielmehr nach Gottesfurcht zu allen Zeiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Dann hast du eine Zukunft, und nicht zuschanden wird dir deine Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Mein Sohn! Horch auf! Und werde weise! Laß nur geraden Weg dein Herz beschreiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Sei nicht bei Weinsäufern und nicht bei liederlichen Menschen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Der Säufer und der liederliche Mensch verarmen; die Dirne kleidet dich in Lumpen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Auf deinen Vater hör, der dich gezeugt! Mißachte nimmer deine Mutter, weil sie alt geworden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Die Wahrheit kauf! Versäum nicht ihren Einkauf, nicht den von Weisheit, Zucht und Einsicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Gar laut frohlockt der Vater eines Frommen; wer einen Weisen zeugt, der freut sich über ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'So freue sich dein Vater über dich! Frohlocken möge die, die dich geboren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Mein Sohn, gib mir dein Herz! Laß deinen Augen meine Wege wohlgefallen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Denn eine tiefe Grube ist das andere Weib; ein enger Brunnen ist die Fremde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'ja, wie ein Räuber liegt sie auf der Lauer, verübt an Menschen viel Betrug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Wer hat nur Ach? Und wer hat Wehe? Wer hat nur Streitereien? Und wer Klagen? Wer Wunden ganz umsonst? Wer hat ein blaues Auge?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Die spät beim Weine sitzen, die zu des Mischtranks Probe kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Schau nach dem Wein nicht gierig, wie er rötlich schimmert, wie er im Becher funkelnd leicht hinuntergleitet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Zum Schlusse gleicht er einer Schlange, die dich sticht, und einem Basilisken, der sein Gift verspritzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Und deine Augen blicken schief; dein Herz denkt ganz verkehrte Sachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Und du gleichst einem Mann, der mitten in dem Meere liegt, ja einem Mann, der oben auf dem Mastbaum sitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '\"Ja, hätt\' man mich geschlagen, hätt\' es mir nicht weh getan. Und wenn man mich geprügelt, hätt\' ich\'s nicht gemerkt. Sobald ich wieder nüchtern bin, will ich aufs neue mich ihm wiederum ergeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Verlange nicht nach Boshaften! Trag kein Gelüst, mit ihnen zu verkehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Denn nur Gewalttat sinnt ihr Herz, und Unheil reden ihre Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Durch Weisheit wird allein ein Haus erbaut, und durch verständig Wesen wird es fest gegründet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Durch Einsicht füllen sich die Kammern mit seltener und wohlverdienter Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Ein weiser Mann ist mächtig, ein Kluger voller Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Mit Kunst fuhrst glücklich du den Krieg; der Sieg ist da, wo viele Ratgeber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Dem Toren ist die Weisheit unerreichbar; er fragt nicht auf dem Markt danach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Wer Schlechtigkeit zu tun sich vornimmt, den heißt man einen abgefeimten Schurken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Das Dichten und das Trachten eines Toren ist das Laster, und das des Spötters sind Abscheulichkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Wenn du dich schlaff an schlimmen Tagen zeigst, wird deine Kraft sich mindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Die man zum Tode führt, die suche zu befreien; verlaß nicht, die man führt zur Hinrichtung hinaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Denn, wenn du sagst: \"Wir haben\'s nicht gekonnt\", durchschaut\'s nicht der, der alle Herzen wägt, und wird\'s nicht inne, der auf deine Seele achtet? Wird nicht dem Mann nach seinem Tun vergolten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Mein Sohn iß Honig! Er ist gut. Und Honigseim! Süß ist er deinem Gaumen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'So schätze auch die Weisheit ein für deine Seele! Wenn du sie findest, gibt es eine Zukunft, und deine Hoffnung wird nicht mehr zuschanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Belaure, Frevler, nicht des Frommen Ruhestätte! Dir soll es nicht gelingen, seine Lagerstätte zu zerstören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Denn fällt auch siebenmal der Fromme, steht er doch immer wieder auf; die Frevler aber sinken in das Unglück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Nicht juble über deines Feindes Fall, und über seinen Sturz frohlocke nicht dein Herz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Sonst sieht mit Mißbehagen es der Herr und wendet seinen Zorn von jenem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Erhitze dich nicht über Bösewichte! Ereifere dich nicht über Frevler!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Denn keine Zukunft hat der Böse; des Bösewichtes Leuchte wird erlöschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mein Sohn! Fürchte den Herrn und fürcht den König! Mit Aufrührern verkehre nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Denn plötzlich kommt ihr Unheil, und dem Mißgeschicke, das von beiden kommt, wer weiß ihm zu begegnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Auch das sind Aussprüche von Weisen: Bei Gericht Parteilichkeit: ein übel Ding.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Wer zu dem Schuldigen spricht: \"Du bist im Recht\", ja, den verwünschen Völker und verfluchen Nationen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Doch denen, die gebührend strafen, ergeht es wohl, und über sie kommt Glück und Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Die Lippen schließt, wer immer rechte Antwort gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Besorge draußen dein Geschäft! Bestell den Acker dir! Setz dein Gebäude gut instand!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Sei gegen deinen Nächsten niemals Zeuge ohne Grund! Täusch mit den Lippen nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Sprich nicht: \"So wie er mir getan, so will auch ich ihm tun; ich will dem Mann nach seinem Tun vergelten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Den Acker eines faulen Mannes habe ich betrachtet, den Weinberg eines unverständigen Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Da war er ganz in Wicken aufgegangen; das Unkraut deckte seine Fläche, und seine Steinmauer war eingerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Ich habe hingeschaut und es beherzigt; ich habe hingeblickt und eine Warnung mir daraus genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '\"Ach noch ein wenig Schlaf, ein wenig Schlummer, ein wenig noch die Hände ineinander legen, um zu ruhen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Schon kommt die Armut über dich gleich der des Strolches, und Mangel gleich dem eines Bettlers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Auch dies sind Sprüche Salomos, die aufgezeichnet von den Männern Hizkias, des Herrschers über Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Für Gott ist\'s eine Ehre, geheimnisvolle Worte auszusprechen; dagegen ist es eine Ehre für die Könige, Befehle unzweideutig auszugeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Gleichwie des Himmels Höhe und der Erde Tiefe, so unerforschlich ist auch eines Königs Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Entfernt man Schlacken aus dem Silber, dann gelingt dem Goldschmied ein Gefäß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Entferne Frevler aus des Königs Dienst, dann hat sein Thron Bestand durch die Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Vor einem König prunke nicht! Tritt nimmer auf den Platz der Großen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Weit besser, daß man zu dir sagt: \"Rück doch herauf, hierher!\", als daß man dich hinunterrücken läßt vor einem Vornehmern, wie du es selber schon gesehen haben magst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Voreilig fange keinen Streit an! Kannst du noch später etwas machen, wenn dich dein Freund beschämt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Hast du mit deinem Freunde Streit, verrate niemals ein Geheimnis einem andern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'daß er dich nicht verlästre, falls er\'s hört! Nicht kehrt ja deine üble Nachrede zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Goldenen Äpfeln in Silberschalen gleicht ein Wort, zur rechten Zeit gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Ein goldener Ring, ein Schmuck aus feinem Gold, das ist ein weiser Mahner für den aufmerksamen Hörer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Wie kühles Eis bei Erntehitze, so kann ein Bote, seinen Auftraggebern treu, das Leben seinem Herrn erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Wie Wolken, Wind und doch kein Regen, so ist ein Mann, der mit Geschenken prahlt und sie nicht gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Durch Milde wird ein Fürst begütigt; die sanfte Rede kann selbst Starres brechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Hast Honig du gefunden, iß soviel, wie du vertragen kannst! Sonst mußt du ihn erbrechen, hast du daran dich übersättigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Laß deinen Fuß im Hause deines Nächsten selten sein, daß er nicht deiner überdrüssig werde und dich gleichgültig behandle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Was Keule und was Schwert und was ein scharfer Pfeil, das ist der Mensch, der gegen seinen Nächsten auftritt als ein falscher Zeuge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Ein böser Zahn, ein kranker Fuß: das ist ein falscher Freund, auf den man sich verläßt am Tag der Not!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Wie einer, der an kaltem Tag den Rock auszieht, wie Essig auf das Natron wirkt, ist einer, der mit Singenden bei traurigem Gemüte singt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Wenn\'s deinen Hasser hungert, speise ihn mit Brot! Und wenn\'s ihn dürstet, tränke ihn mit Wasser!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Denn damit scharrst du glühende Kohlen auf sein Haupt; der Herr vergilt es dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Der Nordwind hemmt den Regen, verdrießliches Gesicht die Zunge der Verleumdung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Viel lieber in dem Winkel eines Daches ruhen, als ein gemeinsames Haus mit einem Weib, das zänkisch ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Was für die durstige Seele frisches Wasser, ist gute Nachricht aus der Ferne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Getrübter Born, verderbte Quelle, das ist ein Frommer, der vor einem Frevler weicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Nicht gut ist, zuviel Honig zu verzehren; in Menge davon zu erbrechen, eine Buße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Was eine offne, mauerlose Stadt, das ist ein Mann, dem Selbstbeherrschung fehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Wie Schnee im Sommer, Regen in der Ernte, so ungehörig ist die Ehre für den Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Ein Sperling, der fortflattert, eine Schwalbe, die fortfliegt, so ist unverdienter Fluch; er trifft nicht ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Dem Roß gebührt die Peitsche, ein Zaum dem Esel, dem Rücken eines Toren eine Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Antworte nicht dem Toren seiner Torheit nach, damit du selbst dich ihm nicht gleichstellst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Daß seine Rede Torheit sei, sag einem Toren, daß er sich nicht weise dünke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Ein Trinker, der die Füße heftig anstößt, ist einer, der durch einen Toren eine Botschaft sich bestellen läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Laßt einen Trunk durch einen Lahmen schöpfen, das ist der Weisheitsspruch im Mund des Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Wie einer, der bei einer Steinigung den Stein umwickelt, so handelt, wer dem Toren Ehre gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ein Dornzweig in des Trunknen Hand, das ist ein Weisheitsspruch im Mund des Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Viel Weh erleidet jedermann, der einen Toren dingt, wie einer, der in Dienst nimmt einen Wanderer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Gleich einem Hunde, der zu seinem Auswurf kehrt, so ist ein Tor, der seine Torheit wiederholt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Erblickst du einen Mann, der selbst sich weise dünkt, da gibt\'s für einen Narren eher Hoffnung als für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Der Faule spricht: \"Es ist ein Löwe auf dem Wege, ein Löwe innerhalb der Straßen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Wie sich die Tür dreht in der Angel, genauso auch im Bett der Faule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Wenn seine Hand der Faule in die Schüssel steckt, dann wird\'s ihm sauer, sie zum Mund zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Ein Fauler dünkt sich weiser noch als sieben, die die Gottessprüche künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Gleich dem, der einen Hund beim Springen an den Ohren packen will, ist einer, der in fremden Streit sich mischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Wie einer, der aus Zeitvertreib Brandpfeile und Geschosse und Verderben schleudert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'so ist ein Mann, der seinen Nächsten hintergeht und dann noch sagt. \"Ich scherze bloß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Ist Holz nicht mehr vorhanden, geht das Feuer aus, und ist kein Ohrenbläser da, legt sich der Zank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Zur Glut sind Kohlen da und Holz zum Feuer, und so zum Streitentfachen ein Streitsüchtiger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Des Ohrenbläsers Worte dienen nur dem Zeitvertreib; doch dringen sie gar tief ins Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Dem Gefäß mit unecht Silber überzogen, bei Herzeleid ihm gleichen hitzige Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Mit seinen Lippen kann der Hasser sich verstellen; in seinem Innern aber hegt er Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Und wenn er seine Liebe laut beteuert, glaub ihm nicht! Denn sieben Greuel sind in seinem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Und mag der Haß durch Heuchelei verborgen werden, es tritt doch seine Bosheit öffentlich zutage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Wer eine Grube gräbt, kann selber in sie fallen; wer einen Stein wegwälzt, auf den kann er zurück auch rollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Es haßt die lügnerische Zunge ihre Tadler; ein glatter Mund schafft sich Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Freu dich nicht auf den Morgen! Denn du weißt nicht, was ein Tag gebären mag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Ein anderer Mund, nicht deiner rühme dich, ein fremder, doch nicht deine eigenen Lippen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Der Stein ist schwer; gewichtig ist der Sand; doch der Verdruß, von einem Toren dir bereitet, ist schwerer als die beiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Die Wut mag grimmig sein; der Zorn mag überschäumen; doch wer kann vor der Eifersucht bestehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Viel besser Rüge, die enthüllt, als Liebe, die verschleiert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Aufrichtig sind gemeint des Freundes Schläge; des Feindes Küsse sind geheuchelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Dem satten Gaumen ekelt\'s vor dem Honigseim; dem Hungrigen ist alles Bittere süß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Ein Vogel, der dem Nest entflieht: so ist ein Mann, der seinen Heimatort verläßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Salböl und Räucherwerk erheitern das Gemüt; des Freundes Süßigkeit geht über die des Duftgehölzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Den alten Freund des Hauses übergehe nicht! Klopf nicht an deines Bruders Haus am Tage deiner Not! Viel besser ist ein Nachbar in der Nähe als ein Bruder in der Ferne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Mein Sohn! Sei weise und erfreu mein Herz! Damit ich rechte Antwort einem geben kann, der mich beschimpfen will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Der Kluge sah das Unheil und versteckte sich; die Toren gingen weiter und erlitten Schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Wer einem andern bürgt, dem nimm sein Kleid! Pfänd ihn um Fremder willen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Wer seinen Nächsten allzu laut und gar zu früh lobpreist, dem kann\'s als Fluchen angerechnet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Ein triefend Dach zur Zeit des Regenwetters ist ein zänkisch Weib; sie gleichen sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Der Nordwind ist ein rauher Wind; und er wird doch der \"Glückverheißende\" genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Wie Eisen sich dem Eisen eint, so eint ein Mann sich seinem Freund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Des Feigenbaumes Frucht genießt, wer diesen pflegt, und wer den seines Herren wartet, findet seinen Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Gleichwie beim Wasser sich die Form der Form anpaßt, so auch des Menschen Herz dem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Der Abgrund und die Unterwelt sind unersättlich; so sind der Menschen Augen gleichfalls nicht zu sättigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Nach Silber wird der Tiegel eingeschätzt; der Ofen nach dem Gold, ein Mann nach dem, was er bewundert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Zerstießest du den Toren selbst im Mörser, selbst mitten in der Grütze mit der Keule, nicht würde seine Torheit von ihm weichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Hab acht auf deine besten Schafe, sei wachsam auf die Herden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Denn bares Geld reicht nicht für immer; nicht währt der Zins für alle Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Sprießt Gras empor, erscheint das frische Grün, und werden auf den Bergen Kräuter eingeheimst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'dann hast du Lämmer für die Kleidung und Böcke zum Erwerb von Feldern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'und Ziegenmilch genug für deine und für deines Hauses Nahrung und Lebensmittel für die Mägde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Der Frevler flieht, obschon ihm niemand auf den Fersen. Doch wie ein junger Löwe, der sich sicher fühlt, so ist der Fromme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Die Sünde eines Landes schafft ihm viele Herrscher; durch einen Klugen, der das Richtige versteht, wird lange Dauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ein Mann, der reich, jedoch Geringe unterdrückt, ist wie ein Regen, der nur wegschwemmt, aber kein Getreide schafft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Die das Gesetz mißachten, rühmen einen Frevler; doch die Gesetzestreuen eifern gegen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Die schlimmen Leute denken nicht an das Gericht; doch die den Herren suchen, achten drauf in jeder Weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Viel besser ist ein Armer, der in seiner Unschuld lebt, als wer verkehrte Wege geht und dabei reich ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Wer das Gesetz beachtet, ist ein kluger Sohn. Wer\'s mit den Liederlichen hält, macht seinem Vater Schande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Wer sein Vermögen mehrt durch Zins und Wucher, der sammelt es für den, der sich der Elenden erbarmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Wer da sein Ohr wegwendet, weil er das Gesetz nicht hören will, selbst sein Gebet ist Gott ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Wer Leute, die den rechten Weg beschritten, auf schlimmen Irrweg führt, der fällt in seine Grube; die Frommen erben Gutes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Ein reicher Mann hält sich für weise; doch ihn durchschaut ein kluger Bettelmann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Erlangen Fromme hohe Stellung, dann zeigt sich vielfach Luxus; gelangen Ungerechte an die Macht, durchsucht man wiederum die Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Wer seine Missetaten zu verbergen sucht, der hat kein Glück damit; wer sie bekennt und läßt, der wird Erbarmen finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Heil sei dem Menschen, der stets auf der Hut! Doch wer sein Herz verhärtet, fällt in Unglück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Ein Leu, der brüllt, ein Bär mit aufgesperrtem Rachen: so ist ein schlimmer Herrscher über ein geringes Volk!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Ein Fürst zeigt sich beschränkt, begeht er viel Erpressungen; wer ungerechtes Gut nicht mag, der hat ein langes Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ein Mensch mit Blutschuld auf der Seele eilt zur Grube. Halt ihn nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Wer in der Unschuld wandelt, wird gerettet; wer auf verkehrten Wegen wandelt, fällt auf einmal hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Wer seinen Acker baut, hat Brot in Fülle; doch wer nichtigen Dingen nachjagt, hat in Fülle Armut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Ein Mann mit Zähigkeit wird reich gesegnet; wer aber eilt, sich zu bereichern, bleibt nie ohne Schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Parteilichkeit ein übel Ding! Schon wegen eines Bissens Brot kann sich ein Mensch versündigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Wer Mißgunst hegt, der will in Eile sich bereichern und weiß nicht, daß auch über ihn der Mangel kommen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Wer einen Menschen tadelt, der kann hinterher mehr Dank empfangen als der glatte Schmeichler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Wer seine Eltern ausraubt mit den Worten: \"Dies ist doch keine Sünde\", der ist ein Spießgesell von Mordbuben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Habgier weckt Unzufriedenheit; wer auf den Herrn vertraut, wird reich gelabt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Wer seinem eigenen Verstand vertraut, der ist ein Tor; wer aber der Erfahrung folgt, der kommt davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Wer Armen gibt, der leidet keinen Mangel; wer aber seinen Blick verhüllt, wird viel verflucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Gelangen Ungerechte je zur Macht, verbirgt sich jedermann; verschwinden sie, gelangen Fromme an die Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Ein Mann, halsstarrig Rügen gegenüber, verfällt dem Untergange unheilbar und plötzlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Gelangen Fromme an die Macht, alsdann frohlockt das Volk; wenn Frevler herrschen, seufzt das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Ein Mann, der Weisheit liebt, der sorgt auch für den Vater; doch wer\'s mit Dirnen hält, vergeudet sein Vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Ein König voll Gerechtigkeit befestigt auch das Land; ein Mann, auf Abgaben erpicht, vernichtet es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Wer einen andern auf das Glatteis führt, bereitet auch Gefahr den eigenen Schritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'In eines bösen Mannes. Frevel liegt ein Fallstrick; der Fromme jauchzt und freut sich dran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Der Fromme achtet auf die Rechte der Geringen; der Frevler aber kümmert sich nicht um Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Boshafte Leute bringen eine ganze Stadt in Aufruhr; den Zorn beschwichtigen die Weisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Mit einem Toren rechtete ein weiser Mann. Es zürnte jener, dieser lachte; so gab es keine Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Gewissenlose Menschen hassen den Einfältigen; Gerechte suchen ihn am Leben zu erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Ein Tor läßt seinen ganzen Zorn heraus; ein Weiser bändigt ihn im Hinblick auf die Zukunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Ein Herrscher, der auf Lügenworte hört, hat frevelhafte Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Zwar Reich und Arm sind Gegensätze; doch beiden gibt der Herr das Lebenslicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Der Thron des Königs, der getreulich Recht den Armen schafft, besteht für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Weisheit verleihen Stock und Rüge; ein Knabe, selbst sich überlassen, macht der Mutter Schande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Wenn Frevler in die Höhe kommen, nimmt der Frevel überhand; bei ihrem Sturze kommen an die Macht die Frommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Straf deinen Sohn, und er bereitet ein behaglich Leben dir, reicht deiner Seele Leckerbissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Wenn Mangel ist an Offenbarungen, dann wird das Volk verwildern; doch hält es das Gesetz, Heil ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Mit Worten läßt ein Knecht sich nicht belehren; denn wenn er sie versteht, dann kümmert er sich nicht darum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Erblickst du einen Mann, der mit den Worten viel zu hastig ist: mehr Hoffnung ist für einen Narren als für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Wenn einer seinen Knecht von Jugend auf verzärtelt, dann spielt dieser zuletzt den Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Ein Mann voll Zorn weckt Zank; ein Hitzkopf macht gar viele Fehler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Des Menschen Hochmut führt ihn zur Erniedrigung; doch Ehre wird der demutsvolle Mann erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Wer mit dem Diebe teilt, der haßt sein eigen Leben; er hört den Fluch; doch zeigt er es nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Die Angst bringt einen Menschen in Gefahr; wer auf den Herrn vertraut, der wird geschützt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Es suchen viele eines Herrschers Angesicht; doch von dem Herrn kommt eines Mannes Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Ein Greuel für den Frommen ist, wer Unrecht tut. Ein Greuel für den Frevler, wer gerade wandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Die Worte Agurs, Sohnes des Jake, aus Massa: Es spricht ein Mann mit Namen Loitiel: \"Ich kann Gott nicht begreifen, und dabei bleibt es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Zu töricht bin ich, einen Mann recht zu verstehen, und mir fehlt der Verstand, um einen Menschen zu begreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Und wäre ich noch weiser, wie könnte einen Heiligen ich gar begreifen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Ist jemand bis zum Himmel aufgestiegen oder auch von dort herabgekommen? Hat jemand Wind in seine Fäuste eingesammelt oder Wasser in ein Tuch gebunden? Wer hat der Erde Enden hingestellt? Wie heißt doch er? Wie heißt sein Sohn, wenn du es weißt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Geläutert ist doch jedes Gotteswort; ein Schild ist er für die, die auf ihn bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Füg seinen Worten nichts hinzu, auf daß er dich nicht tadeln muß, weil du dich nicht bewährst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Ich bitte zweierlei von dir. Versag mir\'s nicht, bevor mein Leben ich verwirke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Falschheit und Lügenwort laß ferne von mir sein; Armut und Reichtum gib mir nicht! - Laß mich mein zugemessen Teil an Speise nehmen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Ich möchte sonst verleugnen, würde ich zu satt, und sagen: \"Wer ist denn der Herr?\", und wäre ich ein Bettler, könnt ich stehlen und belasten meines Gottes Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Verleumde nicht den Knecht bei seinem Herrn! Sonst flucht er dir, und du bist selber schuld daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Ja, das Geschlecht, das seinem Vater flucht und nimmer seine Mutter segnet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'ja, das Geschlecht, das rein sich dünkt und doch von seinem Unrat nicht gereinigt ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'ja, das Geschlecht, das übermütig schaut, und dessen Blicke hochgetragen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'ja, das Geschlecht, des Zähne Schwerter sind und des Gebiß besteht aus Messern, um von der Erde Elende hinwegzufressen und Arme aus der Menschen Mitte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'das gleicht dem Vampyr, der die Weiber schwer zerfleischt: \"Gib her! Gib her!\" Drei sind\'s, die niemals satt werden, und vier, die sprechen nie: \"Genug!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Die Unterwelt, verschlossener Mutterschoß, die Erde, die des Wassers niemals satt, das Feuer, das nie spricht: \"Genug!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Ein Auge, das des Vaters spottet, die greise Mutter selbst verächtlich findet, das müssen Raben aus den Höhlen hacken und junge Adler fressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Drei sind\'s, die mir zu wunderbar erscheinen, und vier sind\'s, die ich nicht begreife:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'des Adlers Weg am Himmel, der Schlange Weg auf einem Felsen, des Schiffes Weg inmitten eines Meeres, des Mannes Weg bei einem jungen Weibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'So ist der Weg der Ehebrecherin; sie ißt und wischt den Mund sich ab und spricht: \"Ich habe doch nichts Unrechtes getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Ein Land kann unter drei erbeben und unter vieren es nicht aushalten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'bei einem Sklaven, wenn er König wird, bei einem Narren, wenn er Brot in Fülle hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'bei einer Ungeliebten, wenn in Gunst sie kommt, bei einer Magd, wenn sie an ihrer Herrin Stelle tritt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Vier sind die Kleinsten auf der Erde, und doch sind sie so weise:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'die Ameisen, ein Volk, das keine Macht besitzt, und doch bereiten sie im Sommer ihre Nahrung vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Die Klippdachse, ein Volk, dem Stärke nicht zu eigen ist, und dennoch legen sie in Felsen ihre Wohnung an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Heuschrecken haben keinen König, und dennoch zieht der ganze Schwarm geordnet aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Die Echse kannst du mit den Händen greifen, und doch weilt sie in königlichen Schlössern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Drei sind\'s, die stattlich schreiten, und vier, die würdevoll einhergehen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'der Löwe, Held der Tiere, der nie vor jemand umkehrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'der schmächtige Star, der Ziegenbock, der König, der sein Kriegervolk befehligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Benahmst du dich im Übermute töricht, oder hast du so etwas geplant, die Hand auf deinen Mund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Schlägt man die Milch, so gibt es Butter; drückt man die Nase, gibt es Blut, und drückt man auf die Zornesader, gibt es Streit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Die Worte an den König Lemuel, ein Spruch, den seine Mutter lehrte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, '\"Was soll ich dir, mein Sohn, was Lemuel, mein Erstgeborener, dir sagen? Nicht doch, du meines Leibes Sohn, nicht doch du Sohn, den durch Gelübde ich erworben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nicht gib den Weibern deine Kraft, noch deine Liebe Königs Freundinnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Nicht ziemt den Königen, o Lemuel, nicht ziemt den Königen der Weingenuß, so wenig, wie den Fürsten der des Bieres,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'daß er nicht zeche und des Rechts vergäße und der Bedrückten Sache ändere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dem Elenden gebt Bier und dem betrübten Herzen Wein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Er soll nur trinken und des Jammers so vergessen und seines Leids nicht mehr gedenken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Tu deinen Mund für Stumme auf und für die Sache derer, die Vertretung nötig haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Tu deinen Mund auf als gerechter Herrscher, als Anwalt des Bedrängten und des Armen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Ah, wem ein wackres Weib zuteil geworden, dem geht sie über Perlenwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Bei ihrem Mann genießt sie Zutrauen, und an Gewinn fehlt es ihm nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Charitin ist sie ihm; sie tut ihm nie ein Leid ihr ganzes Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Die Arbeit nur ist ihre Lust; sie sieht sich um nach Wolle und nach Flachs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Einem Kauffahrerschiff gleicht sie, von ferne schafft sie sich die Nahrung her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Früh bricht sie in der Nacht den Schlaf, bereitet Speise ihrem Hausgesinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Gern hätte sie ein Feld; sie kauft es vom Ersparten sich und eines Weinbergs Pflanzung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Hat ihre Lenden fest gegürtet, und rüstig reget sie die Arme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Jetzt sieht sie, wie voran geht alles, und ihre Lampe bleibt des Nachts nicht ausgelöscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Kommt sie alsdann zum Stoff für\'s Spinnen, so fassen ihre Hände fest die Spindel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Lädt Arme ein; dem Elenden gibt sie die Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Mit Winterschnee nimmt für ihr Hausgesinde sie es auf; in doppelte Gewandung hüllet sie die Ihren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Näht Teppiche für sich aus Linnen und aus dem Purpur Kleider.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Obenan steht in den Schulen ihr Gemahl, wenn mit den Ältesten des Landes er zusaminensitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Phöniziens Händlern gibt sie Gürtel; ein feines Unterkleid hat sie gefertigt und verkauft es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Reich, prächtig ist ihr Kleid, und so lacht sie des künftigen Tages.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Sie spricht, und lautere Wahrheit ist\'s, und was sie redet, ist nur liebevolle Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Tatkräftig überwacht sie ihres Hauses Ordnung, und Brot der Faulheit läßt sie nicht genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Und wo sich ihre Kinder zeigen, preist man sie und rühmt sie, wo ihr Gatte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '\"Viel Frauen haben wacker sich gezeigt; du aber übertriffst sie alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Wie schwinden Anmut hin und Schönheit! Ein Weib, das Furcht hat vor dem Herrn, das soll man rühmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Zollt ihr, was ihr gebührt! Selbst in den Toren künden ihre Werke ihren Ruhm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Die Worte des Davidsohnes Kohelet, des Königs von Jerusalem, lauten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, '\"Eitel, Eitelkeit\", so spricht Kohelet, \"Eitel, Eitelkeit, \'s ist alles eitel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Was hat der Mensch von seiner Mühe all, mit der er unter dieser Sonne regsam ist;,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Geschlechter gehn, Geschlechter kommen; doch ewig bleibt die Erde stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Aufgeht die Sonne, untergeht die Sonne, sie keucht nach ihrem Ort und geht doch wieder auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Der Wind weht nach dem Süden und kreist zum Norden; er geht im Kreis, und nur zu seinem Kreislauf kehrt der Wind zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Die Ströme ziehen all zum Meere; doch wird das Meer nicht voll. Zur Stätte, wo der Ströme Quelle, kehren sie zu neuem Laufe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Die Worte all versagen; kein Mensch kann es erklären; kein Auge völlig übersehen, kein Ohr erschöpfend es vernehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Was einst gewesen, das ist jetzt, und was geschehen, das geschieht. Nichts Neues gibt es unter dieser Sonne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Ist etwas da, wovon man sagen kann: \"Sieh, dies ist neu!\"? Es war schon längst zu einer Zeit, die vor uns liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Von den Verflossenen weiß man nichts; doch auch der Künftigen gedenken die nicht mehr, die später kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ich, Kohelet, war zu Jerusalem ein König über Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Ich war bedacht, zu forschen, zu ergründen an der Weisheit Hand, was unterm Himmel sich vollzieht. Ein leidig Ding, was Gott den Menschenkindern zugeteilt zu ihrer Plage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Ich sah, was unter dieser Sonne je geschehen. Sieh, alles war nur eitel und Geistesspiel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'nur Krummes, das man nie gerade macht, nur Mangelhaftes, das man nicht berechnen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Ich sagte mir: \"Fürwahr, ich wurde groß und wuchs an Weisheit über alle, die vor mir zu Jerusalem geherrscht. Viel Weisheit und viel Wissen sah mein Geist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Doch als ich meinen Sinn darauf gelenkt, herauszubringen, was es um die Weisheit und um Wissen sei, um Torheit und um Tollheit, da kam ich zu der Einsicht: Auch das ist selbst ein Hirngespinst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Denn wo viel Weisheit, ist viel Ärger. Wer Wissen mehrt, der mehrt auch Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Ich sprach in meinem Herzen: \"Wohlan, versuch es mit Vergnügen! Und laß dir\'s wohlergehen!\" Doch sieh, auch dies war eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Vom Lachen mußt ich sagen: \"Unsinn!\" und vom Vergnügen: \"Ach, was soll\'s?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Ich nahm mir vor, dem Weingenuß mich hinzugeben. Mein Geist, der bisher nach der Weisheit sich gerichtet, der sollte Torheit kennenlernen, bis daß ich sähe, was für die Menschenkinder sich empfehle, in ihrem kurzen Lebenslauf zu tun, solang sie unter diesem Himmel weilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'So schuf ich mir denn große Dinge; ich baute Häuser, pflanzte Weinberge zu meiner Lust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Ich legte Gärten mir und Parke an, bepflanzte sie mit Bäumen jeder Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Ich schuf mir Teiche, um aus ihnen junge Parkanlagen zu bewässern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Ich kaufte Sklaven mir und Mägde und hatte Schützlinge; besaß auch Schaf- und Rinderherden, viel mehr als alle, die vor mir zu Jerusalem gelebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Ich sammelte mir Gold und Silber und Schätze, königliche, fürstliche; verschaffte Sänger mir und Sängerinnen, dazu der Menschenkinder Lust, Knaben und Mädchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'So ward ich groß und reich, weit mehr als alle, die vor mir zu Jerusalem gelebt. Dabei blieb mir doch meine Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Was meine Augen sich nur wünschten, verweigerte ich ihnen nicht, und meinem Herzschlag schlug ich keine Freude ab; es sollte ja mein Herz aus aller meiner Mühe Freude schöpfen. Dies sollt mein Anteil sein aus aller meiner Mühe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Ich überprüfte alle meine Werke, die meine Hände je geschaffen, dazu die Müh\', die ich zum Schaffen aufgewandt. Sieh, alles war nur eitel Geistesspiel; kein bleibender Gewinn ist unter dieser Sonne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Alsdann ging ich daran, die Weisheit mit der Tollheit und der Torheit zu vergleichen. Was ist der Mensch, daß er nachspüren könnte dem Zwecke dessen, was man früher tat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Da sah ich, daß die Weisheit vor der Torheit den gleichen Vorzug hat wie Licht vor Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Der Weise hat im Kopfe Augen; der Tor muß wandeln in der Finsternis, und doch bemerkte ich: Ein Los trifft alle beide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Da dachte ich bei mir: Wenn mich das gleiche Schicksal wie den Toren trifft, wozu ward ich so überflüssig weise? Da dachte ich bei mir. Auch dies ist eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Für immer denkt man grad so wenig an den Weisen wie den Toren, weil ja in künftigen Tagen alles längst vergessen ist. Wie aber stirbt der Weise gleich dem Toren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Da ward das Leben mir verhaßt; denn als ein Übel dünkt mir das Geschehen, das unter dieser Sonne sich vollzieht. Ja, alles ist nur eitel Geistesspiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Ich haßte alle meine Mühe, die ich mir unter dieser Sonne gab. Ich muß ja alles einem Menschen hinterlassen, der nach mir kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Wer weiß, ob dieser klug ist oder dumm? Und dennoch schaltet er mit allem, was ich so mühsam und so weise unter dieser Sonne mir erworben habe. Auch das ist eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Und so verzweifelte ich schließlich über alle Mühe, mit der ich unter dieser Sonne mich gemüht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Da müht ein Mensch sich ab mit Weisheit, Einsicht, Tüchtigkeit, und gibt\'s dann einem Menschen, der sich nicht drum müht, als Erbteil. Ja, das ist eitel und sehr übel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Was hat der Mensch von aller seiner Mühe, von seines Geistes Sinnen, mit dem er unter dieser Sonne sich bemüht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'All seine Tage sind nur kummervoll; ihr Inhalt ist Verdruß; sein Herz hat selbst bei Nacht nicht Ruhe. Auch das ist eitel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Kein größeres Glück gibt\'s für den Menschen, als daß er ißt und trinkt und sich an seiner Mühe freut. Doch sah ich auch, daß dies nur von der Gottheit kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Wer kann denn essen und wer fasten, wenn sie nicht will?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Wer gut in ihren Augen, dem verleiht sie Weisheit, Wissen, Freude. Doch dem Mißfälligen teilt sie die Mühe zu, zu sammeln und zu häufen, um es dem zu geben, der der Gottheit wohlgefällt. Das erst ist eitle Geistesplage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Für alles gibt es eine Zeit, und jedes Vorhaben hat seine Stunde unterm Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Für das Geborenwerden gibt es eine Zeit und eine Zeit fürs Sterben, fürs Pflanzen eine Zeit und eine Zeit, Gepflanztes auszureuten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Fürs Töten gibt es eine Zeit und eine Zeit fürs Heilen, fürs Niederreißen eine Zeit und eine Zeit fürs Aufbauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Fürs Weinen gibt es eine Zeit und eine Zeit fürs Lachen, fürs Klagen eine Zeit und eine Zeit fürs Tanzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Fürs Steinewerfen gibt es eine Zeit und eine Zeit fürs Steinesammeln, und fürs Liebkosen eine Zeit und eine Zeit für das Sich-Meiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Fürs Suchen gibt es eine Zeit und eine Zeit, verloren es zu geben, fürs Aufbewahren eine Zeit und eine Zeit, sich nicht darum zu kümmern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Fürs Reißen gibt es eine Zeit und eine Zeit fürs Nähen, fürs Schweigen eine Zeit und eine Zeit fürs Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Fürs Lieben gibt es eine Zeit und eine Zeit fürs Hassen, für Kriege eine Zeit und eine Zeit für Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Was nützt es dem, der etwas tut, daß er sich müht? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Ich habe nun das Ding erkannt, das Gott den Menschenkindern gab, sich damit zu befassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Das All hat er zu seiner Zeit so schön gemacht; dazu die Welt in seine Mitte hingestellt; doch nie begreift der Mensch vom Anfang bis zum Schluß das Werk, das Gott einstmals gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'So komme ich zu der Erkenntnis: Nichts Besseres gibt es unter Menschen, als sich zu freun und gütlich sich zu tun im Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Wo immer nur ein Mensch ißt oder trinkt und sich an aller seiner Mühe freut, ist\'s eine Gottesgabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Ich weiß, daß alles, was die Gottheit je verhängt, für immer Geltung hat. Man kann dazu nichts tun und auch davon nichts nehmen. Die Gottheit hat das so gemacht, daß man sich vor ihr fürchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Was ist, war längst, was sein wird, ist bereits gewesen. Die Gottheit sucht verwehte Spuren auf. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Und weiter sah ich unter dieser Sonne: An der Gerichtsstatt herrscht die Ungerechtigkeit, am Ort der Frömmigkeit der Frevel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Da denke ich bei mir: Den Frommen wie den Frevler wird dereinst die Gottheit richten; denn sie hat eine Zeit für jedes Ding und Werk gesetzt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Nach andrer Leute Weise hatte ich gedacht, Gott habe sie erwählt. Da sah ich nun, daß sie nur Tiere sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Denn Menschenlos und Los der Tiere: Ein und dasselbe Los besitzen beide. Wie diese sterben, sterben jene; sie haben alle einen und denselben Geist. Der Mensch hat keinen Vorzug vor dem Tier. Es ist ja alles eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Sie alle beide gehn an e i n e n Ort; sie alle beide sind aus Staub, und alle beide werden wieder Staub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Wer weiß vom Geist der Menschenkinder, ob er nach oben steigt, und von der Tiere Geist, ob er nach unten niedersinkt zur Erde? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'So sah ich denn: Nichts Besseres gibt\'s, als daß der Mensch ob seiner Werke fröhlich sei; denn dies ist sein bestimmtes Teil. Wer gibt ihm je Gelegenheit, an dem, was nachher sein wird, sich zu laben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Und wiederum sah ich all die Bedrückungen, die\'s unter dieser Sonne gibt. Da sind die Tränen der Bedrückten, und niemand tröstet sie. Gewalttat geht von ihren Drängern aus, und niemand gibt es, der sie rächt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Drum preis ich glücklicher die Toten, die schon gestorben, als die Lebendigen, die noch am Leben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'und glücklicher als beide den, der noch nicht ist. Er sieht das böse Treiben nicht, das unter dieser Sonne sich vollzieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Auch sah ich das: jedwede Mühe und alle Tüchtigkeit des Schaffens ist gegenseitige Eifersucht; auch das ist eitel und ein Geistesspiel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Der Tor legt seine Hände ineinander; dann muß er aber von dem eignen Fleische essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Und doch viel besser eine Handvoll, dabei Ruhe, als beide Hände voll und dabei Müh\' und Geistesplage. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Und wieder sah ich unter dieser Sonne Eitles:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Da ist ein einzelner kein zweiter neben ihm, kein Sohn, kein Bruder, und doch kein Ende aller seiner Mühe, und seine Augen schauen nicht genug des Reichtums: \"Für wen nur mühe ich mich ab, versag\' mir jeglichen Genuß?\" Auch das ist eitel und ein böses Ding. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Zu zweit ist besser als allein; dann hat man von den Mühen guten Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Wenn einer fällt, dann kann ihm sein Geselle helfen. Doch weh dem einzelnen! Wenn dieser stürzt, kann ihm kein zweiter auf die Beine helfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Und weiter: Schläft man zu zweit, gibt man sich gegenseitig warm; wie aber will ein einzelner erwärmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Und wenn man einzeln unterliegt, dann hält man stand zu zweit. Dreifacher Faden reißt nicht schnell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Viel besser ist ein Jüngling, arm, doch klug, als so ein alter, dummer König, der nicht verstand, auf Warnungen zu achten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Denn jener kam aus dem Gefängnis auf den Thron, wenngleich er unter dessen Herrschaft ohne Ansprüche geboren ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Ich habe all die Lebenden gesehen, die unter dieser Sonne einst mit jenem Jüngling gingen, der als der zweite auf ihn folgte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Kein Ende all des Volks, all derer, denen er vorangezogen; doch später freuten sie sich seiner nimmermehr. Ja dies ist wirklich eitel und ein Geisteskummer. Behüte deinen Fuß, wenn du der Gottheit Haus besuchst, und wenn in seiner Nähe du vernimmst, daß Toren Opfer bringen! Denn diese wissen nicht, daß Ungehöriges sie tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Mit deinem Munde sei nicht vorschnell! Nicht eilig sei dein Herz, ein Wort zu äußern vor der Gottheit! Denn in dem Himmel ist die Gottheit, und du auf Erden. Deshalb mach wenig Worte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Bei Vielgeschäftigkeit kommt es zu Träumerei, zu Torenrede bei viel Worten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Wem du der Gottheit ein Gelübde machst, dann säume nicht, es zu erfüllen! Denn kein Gefallen hat sie an den Säumigen. Was du gelobt, erfülle!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Weit besser ist es, daß du nichts gelobst, als daß du ein Gelübde machst und es nicht hältst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Verfehl dich nicht mit deinem Munde, sag nimmer vor dem Boten: \"Nur Übereilung ist\'s gewesen\"! Sonst zürnt die Gottheit über dein Gerede und pfändet deiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Denn wo viel Träume sind, gibt\'s auch viel eitle Worte. Die Gottheit fürchte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Siehst du die Armen unterdrückt, das Recht und die Gerechtigkeit dem Land entzogen, dann staune nicht darüber! Ein Höherer beobachtet die Hohen, noch Höhere alle beide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'In jeder Hinsicht ist von Vorteil ein Stück Land: im Vorteil der Besitzer eines wohl bestellten Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Wer Geld liebt, hat niemals genug. Wer\'s haufenweise liebt, dem geht davon genug nie ein. Ja, das ist eitel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Das Gut mehrt sich; dann mehren sich, die es verzehren. Was hat davon dann sein Besitzer mehr als bloßes Anschaun? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Der Arbeiter hat einen süßen Schlaf, ob wenig oder viel er ißt. Den Reichen läßt der Überfluß nicht schlafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Ein arges Übel gibt\'s; ich sah es unter dieser Sonne: ein Reichtum, der von seinem Herrn zu seinem Schaden aufgespart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Und dieser Reichtum geht durch Mißgeschick verloren, und hat er einen Sohn, so bleibt nichts mehr in seiner Hand. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Wie er aus seiner Mutter Schoße kam, so nackt muß er auch gehen, so, wie er kam, und nichts von dem, was er erworben, nimmt er mit, wenn er dahingeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Auch dies ist arges Übel: Genauso, wie er kam, so muß er gehen. Was hat er dann davon, daß er sich für den Wind hat abgemüht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Genießt man doch sein Leben lang nur spärlich bei viel Ärger, Kummer und Verdruß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Fürwahr, was ich erfahren, ist: Vortrefflich ist\'s, zu essen und zu trinken, sowie durch alles, was man unter dieser Sonne tut, Genuß sich zu verschaffen in seinen knappen Lebenstagen, die ihm die Gottheit schenkt. Dies ist sein Alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Ist doch für jeden Menschen, dem die Gottheit Reichtum gibt und Schätze, und dem sie Fälligkeit verleiht, davon zu essen und sich sein Teil zu nehmen und sich an seiner Mühe zu erfreuen, dies eben eine Gottesgabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Dann macht er sich nicht viel Gedanken über seine Lebenstage, dieweil die Gottheit sich in seiner Herzensfreude offenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Ein Übel gibt\'s; ich sah es unter dieser Sonne. Das lastet auf den Menschen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Da ist ein Mann, dem gibt die Gottheit Reichtum, Schätze, Luxus. Nichts fehlt ihm mehr, was sich sein Herz nur wünscht; doch gibt die Gottheit ihm nicht Macht, es zu genießen. Ein fremder Mann genießt davon. Ja, dies ist eitel und ein böses Leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Wenn jemand hundert Kinder hätte und viele Jahre lebte, je länger dieser lebte und würde Gutes nicht genießen und würde ihm kein Grab zuteil, so sage ich: \"Die Fehlgeburt ist besser dran als er.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Denn kommt sie auch in Nichtigkeit und geht sie hin in Dunkel, und Dunkelheit deckt ihren Namen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'und erblickt sie auch die Sonne nicht und weiß von nichts, viel wohler ist ihr doch als jenem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'selbst wenn er tausend Jahre zweimal lebte, jedoch das Gute nicht genösse! Begibt sich denn nicht alles hin an einen Ort?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Doch könnte auch von aller Müh der Mensch mit seinem Mund genießen, so würde seine Seele nicht davon erfüllt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Was ist der Vorzug eines Weisen vor dem Toren? Was hat der Arme nur davon, daß er versteht, im Gegensatz zu andern Lebenden zu wandeln?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Beschaulichkeit ist besser als der Zweifel; doch ist auch jenes eitel und ein Geistesspiel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Was ist, war längst schon namentlich bestimmt, bekannt, was mit dem Menschen wird. Mit dem darf er nicht rechten, der stärker ist als er,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'obwohl es viel der Worte sind, die immer wiederholen: \"Das ist eitel\"; und: \"Welchen Nutzen hat der Mensch davon?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Wer weiß, was für den Menschen gut im Leben bei seinen knappen, nichtigen Lebenstagen, die er dem Schatten gleich verbringt? Wer kündet doch dem Menschen, was unter dieser Sonne späterhin geschieht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Weit besser fein Gerücht als Feingeruch, der Todestag als die Geburtsstunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Viel besser ist\'s, ins Trauerhaus zu gehen als in ein Haus der Gasterei. Dort zeigt sich ja das Ende jedes Menschen, und wer noch lebt, kann sich\'s zu Herzen nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Viel besser Ernst als Scherz! Das Herz kann wohlgemut bei ernster Miene sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Der Weisen Herz weilt in dem Trauerhause, der Toren Herz im Haus der Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Viel besser ist\'s, des Weisen Tadel zu vernehmen als auf der Toren Loblied hinzuhören;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'denn wie der Dornen Knistern unterm Kessel, ist eines Toren Beifall. Ja, der ist eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Der Geldeinzug kann einen weisen Mann betören; dem Herzen schadet die Bestechung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Viel besser ist der Ausgang einer Sache als ihr Anfang; viel besser Langmut als der Übermut. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Laß dich nicht schnell zum Unmut reizen; denn Unmut wohnt nur in der Brust von Toren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Sprich nicht: \"Wie kommt es nur, daß jene früheren Tage besser waren als die jetzigen?\" Denn nicht aus Weisheit fragst du so. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Die Weisheit ist so gut wie Eigentum. Für alle ist sie Vorteil, die die Sonne schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Die Weisheit ist ein Schutz, ein Schutz das Geld. Des Wissens Vorzug aber ist, daß Weisheit ihrem Herrn das Leben wahrt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Durchlebe nur der Gottheit Schickung! Denn wer kann grade machen, was sie krümmt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Am guten Tag sei guter Dinge! Am Unglückstag schau hin, - die Gottheit macht ja diesen ebenso wie jenen, - auf diesen Sachverhalt, wonach der Mensch nicht die geringste Spur davon noch später findet! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Das alles schaute ich in meinen eitlen Lebenstagen: Da geht zugrunde ein Gerechter trotz seiner Rechtlichkeit. Da lebt ein Frevler lang mit seiner Bosheit. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Sei nicht zu sehr gerecht! Nicht überklug erzeig dich, daß du nicht in Trübsinn fallest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Sei nicht zu zügellos, und sei kein Tor, damit du nicht zur Unzeit sterbest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Gut, wenn du dich zu einem hältst und von dem anderen nicht läßt. Wer wirklich gottesfürchtig ist, der übertrifft sie alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Die Klugheit gibt dem Klugen viel mehr Stärke, als in der Stadt zehn Machthaber besitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Kein Mensch ist so gerecht auf Erden, daß er immer richtig handelte und niemals fehlte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Acht nicht auf jegliches Gerede, damit du nicht vernimmst, wie dich dein Knecht beschimpft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Dein Herz weiß selber ja, daß du auch andere geschmäht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'All dies durchforschte ich nach Weisheit. Ich sprach, ich möchte weise werden; doch blieb\'s mir fern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Was ist, das ist so fern und tief. So tief! Wer kann\'s erfassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Und immer wieder richte ich den Sinn darauf, es zu erkennen und auszuforschen und zu suchen Weisheit und ein richtiges Ergebnis und zu sehn der Torheit Fehler und der Tollheit Unvernunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Da fand ich bittrer als den Tod das Weib; ein Fangnetz ist\'s, sein Herz ein Garn und seine Arme Fesseln. - Nur wer der Gottheit wohlgefällt, schützt sich vor ihr; doch der Verworfne wird durch es verstrickt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Sieh da, dies fand ich, spricht Kohelet, indem ich eins zum andern fügte, um ein Ergebnis zu erlangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'das immer wieder ich gesucht und niemals habe finden können. Schon manchen Menschen traf ich lehrend an, doch unter allen diesen fand ich nie ein Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Nur dies, sich, habe ich gefunden: Dies, daß die Gottheit einst die Menschen voller Einfalt schuf; doch diese werfen viele Fragen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Wer gleicht dem Weisen? Wer kennt der Dinge Deutung? - Die Klugheit macht des Menschen Antlitz hell und wandelt seines Angesichtes Trotz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Ich sag: Beachte das Geheiß des Königs, des Gotteseides wegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Nicht vorschnell falle von ihm ab! Tritt keiner bösen Sache bei! Denn was er will, das tut er auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Dem Königswort ist Macht. Wer sagt zu ihm: \"Was tust du da?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Wer das Gebot befolgt, erfährt nichts Schlimmes. Die rechte Zeit erfährt ein weises Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Für jeglich Ding gibt es die rechte Zeit. - Gar schwer liegt auf dem Menschen dieses Übel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'daß er nicht weiß, was wird. Wer zeigt ihm an, wie\'s werden wird?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Kein Mensch ist Herr des Lebensodems, daß er den Lebenshauch behalten könnte. Kein Machtgebot gilt für den Sterbetag, im Todeskampf hilft keine Kriegerschar. - Doch hilft auch nicht der Frevel seinem Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Dies habe ich genau gesehn, weil ich den Sinn auf alles Tun gerichtet, das unter dieser Sonne wird vollbracht zu einer Zeit, wo Menschen über andere zum Unheil herrschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Ich sah, wie Frevler sich hervordrängten und kamen, wie aber die, die recht gehandelt, fort von heiliger Stätte mußten und in der Stadt vergessen wurden. Auch das ist eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Weil böser Tat das Urteil nicht sogleich gesprochen wird, schwillt Mut den Menschenkindern, Böses zu verüben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'weil hundertmal der Sünder Böses tut und trotzdem lange lebt. Doch weiß ich auch: Den Gottesfürchtigen allein geht\'s gut, weil sie vor Ihm sich fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Dem Frevler aber geht\'s nicht gut, ob er auch, einem Schatten gleich, die Lebensfrist verlängert, weil er sich vor Gott nicht fürchtet. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Auf Erden gibt\'s noch etwas Eitles. Gerechte gibt\'s und diesen geht\'s, wie\'s Frevlern gehen sollte, und Frevler gibt\'s, und diesen geht\'s, wie\'s Frommen gehen sollte. Ich sprach: \"Auch dies ist eitel.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Da pries ich laut die Freude, weil\'s für den Menschen gar nichts Besseres unter dieser Sonne gibt, als daß er esse, trinke und sich freue, und er verbinde dies mit seiner Arbeit während seiner Lebenszeit, die ihm die Gottheit unter dieser Sonne schenkt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Als ich mein Herz darauf gerichtet, die Weisheit zu erkennen Und zu betrachten all das Treiben, das auf Erden vor sich geht, wie man dabei den Schlaf nicht sieht, am Tage nicht und nicht bei Nacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'da sah ich ein: Der Gottheit Walten ganz und gar kann nie ein Mensch ergründen, das Walten nämlich, das unter dieser Sonne vor sich geht. Wie sehr der Mensch sich müht, es aufzusuchen, er kann es nicht ergründen. Selbst wenn der Weise meint, es zu erkennen, er kann es nicht ergründen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'All dies hab ich bedacht, all dies studiert genau. Die Frommen und die Weisen und ihre Werke sind in Gottes Hand. Ob liebens- oder hassenswert, das weiß deshalb kein Mensch. All das geht über ihr Begreifen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Denn ein Geschick kommt allen zu, den Frommen wie den Frevlern, den Guten, Reinen wie den Unreinen, dem Opfernden wie dem, der gar nicht opfert, dem Guten wie dem Sünder, dem Schwörenden wie dem, der vor dem Eid sich scheut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Das ist das Schlimmste doch von allem, was unter dieser Sonne sich vollzieht, daß allen ein Geschick beschieden, ist doch das Herz der Menschenkinder voller Leid, und Sorge ist in ihrem Herzen lebenslang, und nachher geht es zu den Toten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Wo einer zu Lebendigen sich zählen kann, da ist noch Hoffnung. Denn selbst ein Hund ist besser dran, wenn er lebendig, als ein toter Löwe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Das eine wissen doch, die leben, daß einmal sie auch sterben müssen; die Toten aber wissen gar nichts mehr. Sie werden auch nicht mehr mit Lohn bedacht: denn ihr Gedächtnis ist vergessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Ihr Lieben und ihr Hassen, ihr Neiden ist schon längst dahin. Sie haben keinen Teil in Ewigkeit an irgendeinem Werk, das unter dieser Sonne sich vollzieht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Auf! Iß dein Brot mit Freude, trink heitern Sinnes deinen Wein, wenn schon die Gottheit Wohlgefallen hat an deinen Werken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Stets seien deine Kleider weiß! Und deinem Haupte mangle nicht das Öl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Genieß das Leben mit dem Weibe, das du liebgewonnen, all deine eitlen Lebenstage, die er dir unter dieser Sonne gibt! Denn dies ist ja dein Teil am Leben in allen deinen eitlen Lebenstagen, sowie an deiner Mühe, die unter dieser Sonne du dir machst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Was du dir leisten kannst mit deiner Kraft, vollbringe! Denn weder Schaffen, noch Berechnen, nicht Wissen und nicht Weisheit gibt es in der Unterwelt, wohin du gehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Und wieder sah ich unter dieser Sonne: Den Lauf gewinnen nicht die Schnellen und nicht den Krieg die Helden und nicht die Weisen Brot und nicht die Klugen Reichtum und nicht die Künstler Dank. Auf Zeit und Glück kommt es bei ihnen allen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Der Mensch kennt nimmer seine Zeit; wie Fische sich im Unglücksnetze fangen, wie Vögel in der Schlinge festgehalten werden, so werden auch die Menschenkinder all verstrickt zur Unglückszeit, die plötzlich sie befällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Auch dies sah ich als Weisheit unter dieser Sonne, und als bedeutungsvoll erschien es mir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Da gab es eine kleine Stadt und wenig Männer drin. Ein großer König zog vor sie und schloß sie ein und baute große Türme wider sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Nun traf er einen armen, aber klugen Mann darin, und dieser rettete die Stadt durch seine Klugheit. Kein Mensch gedachte aber später mehr des armen Mannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Da sagte ich: \"Die Klugheit ist weit besser als die Stärke; doch eines Armen Klugheit wird verkannt, und seine Worte werden nicht gehört.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Der Weisen Worte, ruhig ausgesprochen, finden mehr Beachtung als des Narrenkönigs Brüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Viel besser Klugheit als des Krieges Waffen! Ein einziger, der Fehler macht, kann vieles Gute selbst verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Vertilgt man giftige Fliegen, läßt man duftend Öl vergießen. So kann ein wenig Torheit auch begehrter sein als Weisheit und als Würde. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Der Weise hat zur Rechten den Verstand, der Tor zur Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Selbst auf der Reise, die ein Tölpel unternimmt, zeigt sein Verstand sich als beschränkt und sagt es jedem, er sei ein Narr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Wenn gegen dich des Herrschers Unmut sich erhebt, verlaß nicht deine Stellung! Gelassenheit kann große Frevel unterdrücken. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Doch kaum ein Übel ist - ich sah es unter dieser Sonne - so groß wie das Versehen eines Herrschers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Die Torheit wird zu hohen Stellungen erhoben, und Edle müssen in der Niedrigkeit verweilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Zu Pferde sah ich Sklaven, und Fürsten gingen Sklaven gleich zu Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Wer eine Grube gräbt, fällt leicht hinein. Wer eine Mauer einreißt, den sticht leicht die Schlange.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Wer Steine bricht, verletzt sich leicht daran. Wer Holz zerspaltet, bringt dabei gar leicht sich in Gefahr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Hat man das Eisen stumpf gemacht und schleift man nicht die Schneide, dann muß man seine Kräfte mehr anstrengen. Ein Vorteil ist\'s, die Klugheit richtig anzuwenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Wenn eine Schlange sticht, bevor es zur Beschwörung kommt, dann nützt es nichts, ist man ein Meister im Beschwören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Die Worte aus des Weisen Mund sind anmutsvoll; in Widerspruch verwickeln sich des Toren Lippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Der Anfang seiner Worte ist schon Torheit; das letzte Wort aus seinem Munde schlimmste Tollheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Der Narr macht nämlich viele Worte: \"Der Mensch weiß nicht, was kommen wird. Was späterhin geschieht, wer kündet\'s ihm?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Die Arbeit mit den Toren macht ihn müde, ihn, der es nicht versteht, in Heiterkeit zu wandeln. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Weh dir, du Land, des König ist ein Unfreier und dessen Fürsten schon am Morgen schmausen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Heil dir, du Land, des König ist ein freier Mann und dessen Fürsten tafeln stets zur rechten Zeit, als Helden, aber nicht als Zecher!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Da, wo man faulenzt, senkt sich das Gebälk, und wo die Hände lässig, trieft das Haus. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'In Ausgelassenheit verwandeln sie die Speisen und den Wein, der sonst die Lebenden erquickt, und alles offenbart das Geld. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Auch nicht in deinem Zimmer fluch dem König je! In deinem Schlafgemach beschimpfe keinen Reichen! Des Himmels Vögel könnten ja den Laut entführen und die Gefiederten das Wort verbreiten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Dein Brotkorn sende übers Wasser, damit du es nach vielen Tagen wieder findest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Zerleg\' es sieben- oder achtmal! Du weißt ja nicht, was für ein Unglück übers Land noch kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Wenn Wolken sich mit Regen füllen, so gießen sie ihn auf die Erde. Doch fällt ein Baum im Süden oder Norden, dort an dem Ort, wohin der Baum auch fällt, da bleibt er liegen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Wer auf den Wind achtgibt, der kommt niemals zum Säen. Wer nach den Wolken schaut, der erntet nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Wie du nicht weißt, auf welche Weise Lebensgeist im Leib der Mutter in den Körper kommt, so kennst du auch der Gottheit Walten nicht, das alles macht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Am Morgen säe deinen Samen! Laß ruhen deine Hand nicht bis zum Abend! Du weißt nicht, was gedeiht, ob dies, ob das, ob beiderlei gleich gut gerät.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Das Licht ist süß. Den Augen tut es wohl, das Sonnenlicht zu schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Doch wenn der Mensch auch viele Jahre lebt und sich an ihnen insgesamt ergötzt, so soll er wohl bedenken, daß viele Tage sind in Finsternis! Auch das Vergangene ist eitel. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Freu dich an deiner Jugend, Jüngling! Dein Herz erlabe sich in deinen Jünglingstagen! Wohin dein Herz dich lockt und dich dein Auge ladet, geh nur froh! Doch wisse wohl, daß dich nach alledem die Gottheit ins Gericht wird ziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Verscheuche Gram vom Herzen! Und Leiden halt vom Leibe dir! Denn Jugendzeit und schwarzes Haar sind eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Gedenke deines Schöpfers in den Tagen deiner Jugend, bevor die bösen Tage kommen und Jahre nahen, von denen du erklärst: \"Ach, sie gefallen mir nicht\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'bevor die Sonne mit dem Lichte sich verfinstert und mit dem Mond die Sterne, bevor die Wolken nach dem Regen wiederkehren;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'zu einer Zeit, da schon des Hauses Wächter zittern und sich die starken Männer krümmen und die Müllerinnen feiern, weil ihrer wenige geworden sind, und da die durch die Fenster Blickenden sich trüben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'und da die Türen nach dem Markte zu sich schließen, und wenn der Mühle Lärm geringer wird, wenn man beim Schrei des Vogels sich erhebt, wenn jegliche Musik gedämpft ertönt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'auch fürchtet man sich vor den Höhen; Ohnmachten gibt es auf dem Weg; der Mandelbaum erblüht, und mühevoll schleppt sich die Heuschrecke; die Klapper platzt; zu seinem ewigen Haus geht ja der Mensch, und auf der Straße gehn die Trauernden umher;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'bevor der Silberstrick zerreißt, bevor die goldne Kugel ganz zerschellt, bevor der Krug am Brunnen wird zerbrochen, bevor das Rad zertrümmert fällt in die Zisterne. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Zur Erde kehrt der Staub, so wie er war. Es kehrt der Geist zur Gottheit, die ihn gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, '\"Eitel Eitelkeit!\" spricht der Kohelet, \"Alles ist nur eitel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Noch bleibt zu sagen: Kohelet war ein Weiser, der lange Zeit das Volk Erkenntnis lehrte und prüfend und nachdenkend viele Sprüche hat verfaßt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Kohelet suchte anziehende Worte aufzufinden. Die Verbesserungen aber enthalten das Richtige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Der Weisen Worte gleichen Ochsenstacheln; doch Nägel, eingetrieben mit dem Hammer, sind die Zusätze. Sie stammen von einem Hirten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Jedoch vor dem, was darüber hinausgeht, hüte dich, mein Sohn! Bücherschreiben ist nicht reif; so ist das Lesen eine körperliche Anstrengung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Als Schlußwort des Ganzen ist zu vernehmen: \"Die Gottheit fürchte! Halte ihre Vorschriften!\" Um alle Menschen ist\'s ja so bestellt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, '\"Mit allem Tun geht ins Gericht die Gottheit, mit allem, auch mit dem Verborgenen, mag\'s gut sein oder böse.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Das Hohe Lied von Salomo. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, '\"An seines Mundes Küssen lasse er mich trinken!\" - \"Ja lieblicher als Wein ist deine Liebe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, '\"An Wohlgeruch sind deine Öle einzig gut; dein Name selber aber ist das feinste Öl. Drum haben dich die Jungfrauen so lieb.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, '\"Lock mich an dich! Wir wollen eilends kommen.\" \"Der König führe mich in seine Kammern!\" \"Da wollen jubelnd wir uns deiner freuen, dein Kosen höher preisen als den Wein.\" \"Sie lieben dich mit vollem Recht.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '\"Ich bin wohl schwarz und dennoch schön, ihr Töchter von Jerusalem, wie Kedars Zelte, wie Salmas Zeltdecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Nicht darauf schaut, wie schwarz ich bin, weil mich die Sonne so verbrannt! Die Söhne meiner Mutter zürnten mir und machten mich zur Hüterin von andern Weinbergen. So konnte ich denn meinen eigenen Weinberg nicht behüten.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '\"Sag mir, du, den ich liebgewonnen! Wo weidest du, wo lagerst du zur Mittagszeit, daß ich nicht als Verdächtige erscheinen muß bei deiner Freunde Herden?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '\"Weißt du es nicht, du schönste aller Frauen? Geh den Herden nach, und weide deine Zicklein bei den Hütten ihrer Hirten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Dich muß ich jetzt vergleichen mit den Stuten vor dem Wagen Pharaos, du, meine Freundin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Gehänge stünden deinen Wangen lieblich und deinem Halse Schnüre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, '\"Drum wollen wir dir goldene Gehänge machen zu silbernen Zieraten hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '\"Bis dorthin, wo der König ruht auf seinem Polster, da würde meine Narde ihren Duft noch senden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Ich habe nur ein Myrrhensträußchen, Lieber, das hier an meinem Busen ruht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Ich habe eine Zyperntraube, Lieber, in den Weinbergen von Engaddi.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '\"Fürwahr, du bist so schön, du, meine Freundin! Fürwahr, du bist so schön mit deinen Augen, Tauben gleich.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '\"Fürwahr, du bist so schön, Geliebter, so holdselig! So sei das Grüne unser Lager,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'und unsres Hauses Balken seien Zedern, Zypressen unsre Laubengänge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '\"Ich bin nur wie ein Veilchen auf der Saronsflur, wie eine Lilie der Täler.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '\"Was eine Lilie im Vergleich zur Distel, ist meine Freundin bei den Mädchen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '\"Und was ein Apfelbaum ist bei des Waldes Bäumen, das ist mein Liebster bei den Knaben. Mit Lust will ich in seinem Schatten sitzen, und seine Frucht wird meinem Gaumen süß sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Er bringt mich jetzt zum Weinhaus hin und richtet über mir der Liebe Flagge auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Mit Traubenkuchen stärket mich! Erquicket mich mit Äpfeln! Denn ich bin krank vor Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Wenn seine Linke unter meinem Haupte wäre und seine Rechte herzte mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, '\"Ihr Töchter von Jerusalem, ach, ich beschwöre euch bei den Gazellen oder bei den Hindinnen der Flur: Nicht wecket auf! Nicht stört die Liebe, bis es selber ihr gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '\"Horch! Mein Geliebter war soeben angekommen, hinspringend über Berge, über Hügel hüpfend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Schon glich da einem Reh mein Liebster oder einem jungen Hirsch. Er stellt sich hinter unsere Mauer und späht durchs Fenster, blickt durchs Gitter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Dann hob mein Liebster an und sprach zu mir: \'Auf, meine Freundin! Du, meine Schöne, komm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Vorüber ist die Winterzeit; der Regen ist vorbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Die Blumen zeigen sich auf Erden, und der Gesänge Zeit ist da. Der Turteltaube Ruf, der läßt in unserm Land sich hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Schon reifen an dem Feigenbaum die Früchte; Duft haucht die Rebenblüte aus. Auf, meine Freundin! Du, meine Schöne, komm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Du meine Taube in den Felsenspalten, in dem Versteck der Klüfte! Laß deinen Anblick mich genießen! Laß deine Stimme mich vernehmen! Denn deine Stimme ist so süß, dein Anblick lieblich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Die Füchse fanget uns, die kleinen Füchse, die die Weinberge verderben! Denn jetzt schon tragen reife Beeren unsere Weinberge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Ja, mein soll mein Geliebter werden wie ich sein. Bei Lilien soll er weiden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'bis daß der Tag schon luftig wird und bis die Schatten fliehen! Dann streife, du Geliebter, abermals, dem Reh vergleichbar oder einem jungen Hirsch, umher auf klüftereichen Bergen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, '\"Ich sehnte mich auf meinem Lager eines Nachts nach dem, den meine Seele liebt. Ich sehnte mich nach ihm und fand ihn nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'So will ich aufstehen, die Stadt durchstreifen, auf Märkten und auf Straßen suchen ihn, den meine Seele liebt. Ich suchte ihn und fand ihn nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Da trafen mich die Wächter, die in der Stadt umgehen: \'Habt ihr ihn wohl gesehen, den meine Seele liebt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'An ihnen kaum vorüber, fand ich den, den meine Seele liebt. Ich halte ihn nun fest und will von ihm nicht lassen, bis daß ich ihn in meiner Mutter Haus gebracht, hin zu der Kammer jener Frau, die mich geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, '\'Ihr Töchter von Jerusalem!\' so rufe ich. \'Ach, ich beschwöre euch bei den Gazellen oder bei den Hindinnen der Fluren: Weckt nicht auf! Stört nicht die Liebe, bis es selber ihr gefällt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Was ist\'s, was dort heraufkommt aus der Wüste, Rauchessäulen gleich, im Duft von Myrrhen und von Weihrauch, von Spezereien aller Art?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, '\"Fürwahr, das ist die Sänfte Salomos, um sie herum der Helden sechzig, genommen aus den Helden Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Sie alle kriegstüchtig, im Kampf erprobt, jedweder mit dem Schwert an seiner Hüfte, um der Gefahr zur Nachtzeit willen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, '\"Der König Salomo, der ließ sich einen Tragstuhl fertigen aus Holz vom Libanon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Aus Silber ließ er seine Säulen machen, aus Gold die Lehne, seinen Sitz aus Purpurzeug. Sein Innres ist bedeckt mit Bildern aus dem Liebesleben der Töchter von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Wohlan, ihr Sionstöchter! So weidet euch am Anblicke des Königs Salomo, am Kranz, den seine Mutter ihm gewunden an seinem Hochzeitstag, am Tage seiner Herzensfreude!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, '\"Du bist so schön, du, meine Freundin, so schön, und deine Augen sind wie Täubchen, und hinter deinem Schleier gleicht dein Haar wohl einer Ziegenherde, die sich herab am Gileadberge lagert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Und deine Zähne gleichen einer Herde, die sich zur Schur bereithält, die aus der Schwemme steigt, die allesamt Zwillinge trägt, und deren keines ohne Junges ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Und deine Lippen gleichen einem Scharlachfaden, und lieblich ist dein Mund, und deine Schläfe schimmert hinterm Schleier vor gleichwie die Scheibe des Granatapfels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Dein Hals gleicht Davids Turm, mit Zinnen wohlbewehrt, und tausend Schilde hängen dran, sie alle Heldenschilde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Dein Busen gleicht zwei Rehkälbchen, Gazellenzwillingen, die in den Lilien weiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, '\"So lange, bis der Tag ganz luftig wird und bis die Schatten fliehen, will ich zu diesem Myrrhenberg hingehen, zu diesem Weihrauchhügel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, '\"An dir ist alles schön, du, meine Freundin, und kein Makel ist an dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Du brächtest mich vom Libanon, du meine Braut, ja von dem Libanon zurück. Du führtest mich zurück vom Gipfel des Amana, vom Gipfel des Sanir und Hermon, von Löwenwohnungen sogar, von Pantherbergen her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hast mich des Verstands beraubt, du, meine Schwester, meine Braut. Du hast mich des Verstands beraubt, allein durch einen einzigen Blick, durch eine einzige Wendung deines Halses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Wie süß ist deine Liebe, meine Schwester, meine Braut! Um wieviel köstlicher denn Wein ist deine Liebe und deiner Öle Duft als alle Wohlgerüche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Es träufeln deine Lippen, Braut, von Honigseim, und deine Zunge, sie birgt Milch und Honig; dem Duft des Libanon gleicht deiner Kleider Duft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ein Garten, der verschlossen, ist meine Schwester Braut, ein Born, verschlossen; ein Quell, versiegelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Dein Schoß ist ein Granatenhain mit Früchten, wunderköstlich, mit Zyperntrauben, Narden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Ja, Narde, Safran, Kalmus, Zimt mit allerlei Weihrauchgehölz und Myrrhen, Aloë, mit allerlei Balsamessenzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Ein Brunnen mit lebendigem Wasser und Bäche, die vom Libanon herniederrieseln, sind meine Gartenquelle.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '\"Erwache, Nord! Komm, Süd! Durchwehe meinen Garten, daß sein Balsamduft hinströme! - In seinen Garten komme mein Geliebter, genieße seine Früchte, die so köstlich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '\"So komme ich in meinen Garten, du, meine Schwester Braut. Ich pflücke meine Myrrhe samt dem Balsam. Ich esse meine Wabe samt dem Honig. Ich trinke meinen Wein mitsamt der Milch. Ihr Freunde, jetzt sollt ihr zu essen haben und viel zu trinken, ihr Vertrauten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, '\"Ich schlief; jedoch mein Herz war wach. Da horch! Mein Liebster klopft!\"\"Du, meine Schwester, meine Freundin, öffne mir! Du meine Taube, meine Reine! Mein Haupt ist voller Tau und meine Locken voller Tropfen dieser Nacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '\"Ich habe mein Gewand schon abgelegt. Wie sollte ich es wieder anziehn? Auch meine Füße schon gewaschen, wie soll ich nochmals sie beschmutzen?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Da zog mein Liebster seine Hand zurück vom Eingang; nun wallte auf in mir mein Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Ich stand jetzt auf, um meinen Liebsten einzulassen. Da wurden meine Hände feucht von Myrrhe, die auf des Riegels Griffe lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Ich mache meinem Liebsten auf; doch mein Geliebter war entwichen und blieb verschwunden. Mein Leben hätte ich gegeben um ein Wort von ihm; ich suchte ihn und fand ihn nicht. Ich rief ihn an; er gab mir keine Antwort mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Da fanden mich die Wächter, die in der Stadt umgehen. Sie schlugen mich und machten Wunden mir; es rissen mir den Schleier weg die Wächter unserer Stadtmauern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, '\"Ihr Töchter von Jerusalem! Ach, ich beschwöre euch, wenn je ihr meinen Liebsten finden solltet, daß ihr ihm alsdann sagt, ich sei vor Liebe krank.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '\"Was ist dein Liebster als Geliebter, du schönste aller Frauen? Was ist dein Liebster als Geliebter, daß du uns so beschwörst?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '\"Mein Liebster, er ist blendend weiß und rot, aus Tausenden hervorragend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sein Haupt von Gold und seiner Locken eine große Menge, schwarz wie Rabenfedern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Und seine Augen gleichen Tauben an den Wasserbächen, milchweiß gewaschen, dasitzend in Behaglichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Und seine Wangen sind wie Balsambeete und Schreine voll von Wohlgerüchen, und seine Lippen sind wie rote Lilien, von feiner Myrrhe überfließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Und seine Arme sind wie goldne Walzen, mit Tarsissteinen eingefaßt, sein Leib ein Werk aus Elfenbein, bedeckt mit Saphirstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Und seine Beine gleichen Marmorsäulen, gestützt auf Feingoldfüße. Sein Anblick ist wie der des Libanon, großartig wie die Zedern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Sein Gaumen ist ganz Süßigkeit, und er ganz Lieblichkeit. So ist mein Liebster, so mein Freund, ihr Töchter von Jerusalem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '\"Wohin pflegt dein Geliebter sonst zu gehen, schönste aller Frauen? Wohin pflegt dein Geliebter sich zu wenden, daß wir ihn mit dir suchen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '\"Mein Liebster pflegt zu gehn in seinen Garten, zu den Balsambeeten, sich recht an meinem Garten zu erlaben und Lilien zu pflücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Ach, ich gehöre meinem Liebsten. Mein Liebster, er ist mein, der in den Lilien weiden soll.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '\"Du bist so schön, du, meine Freundin, gerade so wie Tirsa, so lieblich wie Jerusalem und dennoch schrecklich wie die Löwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Wend deine Augen ab von mir! Sie setzen mich in Flammen. Dein Haar gleicht einer Ziegenherde, die an dem Gilead herab sich lagert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'und deine Zähne sind wie eine Herde Mutterschafe, die aus der Schwemme steigt, die allesamt Zwillinge tragen, und deren keines ohne Junges ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Und deine Wange hinter deinem Schleier gleicht der Scheibe des Granatapfels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sind\'s auch der Königinnen sechzig und achtzig Nebenfrauen und Jungfraun ohne Zahl,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'so ist nur eine meine Taube, meine Reine, die Lieblingstochter ihrer Mutter, die kindlich der, die sie gebar, ergeben ist. Die Mädchen sehen sie und preisen sie. Die Königinnen und die Nebenfrauen müssen, sie bewundernd, sprechen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '\'Wer ist\'s, die da herabblickt wie die Morgenröte, schön wie der Mond, rein wie die Sonne, und dennoch schrecklich wie die Löwen?\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '\"Zum Nußgarten wollt\' ich hinab, mich an der Palmen frischen Trieben zu erfreun, zu sehen, ob der Weinstock sproßt, ob die Granaten blühen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Da haben gänzlich unvermutet Wagen eines fürstlichen Gefolges in Verwirrung mich gebracht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '\"Sulamith! Du! Halt, Halt! Daß wir dich anschaun können, halt! Halt!\" \"Wozu begaffet ihr die Sulamith wie eine öffentliche Tänzerin?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, '\"Wie schön doch wären deine Füße in Sandalen, du Prinzessin! Es gleicht die Wölbung deiner Hüften einem Schmuck, dem Werk von Künstlerhänden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Dein Schoß ist ein gerundet Becken, dem Mischwein nimmer fehlen darf, dein Leib ein Weizenhaufen, von Lilien umsäumt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Dein Busen gleicht zwei Rehkälbchen, Gazellenzwillingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Dein Hals ist wie ein Elefantenturm, und deine Augen wie die Teiche dort zu Hesbon an dem Tor der Völkerreichen, und deine Nase gleicht dem Turme auf dem Libanon, der nach Damaskus schaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Dem Karmel gleicht dein Haupt auf dir, und deines Hauptes Haar sind Purpurlocken, in Gitterwerk gebunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Wie schön mußt du dann sein, wie lieblich, wenn vollends Liebe sich mit diesen Wonnen eint!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Dein Wuchs ist so, daß er der Palme gleicht; den Trauben gleicht dein Busen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Drum nehme ich mir vor, die Palme zu ersteigen und ihre Früchtezweige zu ergreifen. Dein Busen gleicht den Trauben an dem Weinstock und deiner Nase Duft den Äpfeln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'dem besten Wein dein Gaumen, der glatt in meinen Becher fließen soll, einschläfernd über meine Lippen gleiten!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, '\"Ich aber bin zu eigen meinem Liebsten, und ihm mich hinzugeben, ist mir Pflicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Nun komm, Geliebter! Wir wollen auf das Feld hinaus und unter Zyperntrauben uns verweilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Wir gehen zu den Weinbergen in aller Früh und sehen, ob der Weinstock sproßt und ob sich seine Beeren bilden, ob die Granaten blühen. Dort möchte ich dir meine Liebe schenken. Dort spenden Liebesäpfel ihren Duft. Dort sind vor unserer Türe Früchte, köstlich, mannigfaltig. Ganz frische, samt den alten habe ich dir dort, Geliebter, aufbewahrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, '\"Ach, daß du mir doch Bruder wärst, den meiner Mutter Brust gesäugt Bin ich mit dir im Freien, möchte ich dich küssen. Ich würde darum nicht verachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Jetzt führe ich dich hin, geleite dich zu meiner Mutter Haus, die mich erzogen. Ich gebe dir gewürzten Wein zu trinken, Granatenmost.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Alsdann sei seine Linke unter meinem Haupt, und seine Rechte herze mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Ihr Töchter von Jerusalem! Ach, ich beschwör euch: Weckt nicht auf! Stört nicht die Liebe, bis ihr\'s selbst gefällt!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, '\"Wer ist\'s, der dort heraufkommt aus der Wüste, gestützt auf ihren Liebsten?\" - \"Ich hab dich einen Apfelbaum genannt. Daran hat deine Mutter dich gebunden, daran gebunden, die das Dasein dir geschenkt.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, '\"So drücke mich gleich einem Siegel auf dein Herz, auf deinen Arm gleich einem Siegel!\" \"Stark wie der Tod, so ist die Liebe, fest wie die Unterwelt die Liebesleidenschaft und ihre Flammengluten, Feuergluten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Viel Wasser können nicht die Liebe löschen, und Ströme sie nicht überfluten. Wenn einer alle Habe seines Hauses für die Liebe gäbe, man würde ihn doch bloß verachten.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '\"Wir haben eine kleine Schwester, noch ohne Busen. Was machen wir mit unsrer Schwester an dem Tage, da man um sie freit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Wenn sie dann einer Mauer gleicht, errichten wir ein silbern Pfahlwerk um sie her. Ist sie dagegen eine Tür, dann wollen wir durch Zedernbohlen sie verwahren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '\"Nun bin ich eine Mauer, und Türmen gleicht mein Busen. In seinen Augen freilich bin ich einer gleich, die schon vollzogen hat die Übergabe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '\"Zu Baal Hamon war Salomo ein Weinberg eigen. Er hat den Weinberg Hütern übergeben, von denen jeder seine Frucht abliefern mußte im Wert von tausend Silberlingen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, '\"Mit meinem Weinberg, der mein eigen, ist\'s nach meiner Ansicht ebenso: Die tausend, Salomo, gehören dir; zweihundert dann den Hütern seiner Früchte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, '\"Die du in Gärten wohnst, auf deine Stimme lauschen die Gefährten. Laß mich sie hören!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '\"Mein Liebster, flieh, dem Reh gleich oder jungen Hirschen, auf die Balsamberge!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Ein Gesicht des Amossohnes Isaias, der über Juda und Jerusalem Gesichte geschaut in den Tagen des Ozias, Jotam, Achaz und Ezechias, der Könige von Juda. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Lausch auf, o Himmel! Erde, horche auf! So spricht der Herr: \"Ich ziehe Kinder groß und bringe sie empor; doch schlimm betragen sie sich gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Ein Ochse kennt seinen Besitzer, ein Esel weiß die Krippe seines Herrn. Nur Israel kennt nichts; nur mein Volk will nichts kennenlernen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ein Wehe über eine sündhafte Nation, ein Volk, so reich an Schuld! Unartige Brut! Verderbte Kinder! Den Herrn verlassen sie; den Heiligen Israels mißachten sie, verachten ihn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Worauf wollt ihr denn noch geschlagen werden? Wo denn noch weiter schwären? Das Haupt ist völlig krank, das Herz ganz elend. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Kein heiler Fleck ist von der Sohle bis zum Kopfe, nur Beulen, Striemen, frische Wunden, nicht ausgedrückt und nicht verbunden und nicht mit Öl gekühlt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Verwüstet wurde euer Land, und ausgebrannt sind eure Städte. Von eurem Fruchtgefilde nährten sich vor euren Augen Fremde. Verödet war\'s wie der Barbaren Felder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'So stand die Sionstochter ganz verlassen wie im Weinberg eine Hütte. Der Wächterhütte gleich im Gurkenfeld, so ganz einsam die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ja, hätte uns der Heeresscharen Herr nicht einen Rest gelassen, so wären wir beinah wie Sodoma geworden und glichen jetzt Gomorrha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Ihr Sodomsfürsten, hört das Wort des Herrn! Horch auf die Mahnung unseres Gottes, du Gomorrhavolk! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, '\"Was soll mir\", spricht der Herr, \"die Menge eurer Schlachtopfer? Satt habe ich die Widderopfer und satt das Fett der Mastkälber. Ich mag nicht Farrenblut, nicht Blut der Lämmer und der Böcke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Wenn ihr mein Angesicht zu schauen kommt, ja, wer verlangt von euch, ihr sollet meine Vorhöfe zertrampeln?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Bringt mir kein eitles Speiseopfer dar! Ein Greuelwerk ist es für mich. Am Neumond und am Sabbat Festversammlung! Ein Fest mit Frevel ist mir unerträglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Ich hasse eure Neumondsfeste, eure Feiertage; sie sind mir eine Last, mir unausstehlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Wenn ihr die Hände ausbreitet, vor euch verhüll ich mir die Augen, und betet ihr auch noch so viel, ich höre nicht. Voll Blut sind eure Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Wascht euch und macht euch rein! Hinweg aus meinen Augen mit eurer Werke Schlechtigkeit! Hört auf mit Freveltat. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lernt Guttat! Suchet Recht! Die Schwachen stärkt! Verschafft den Waisen Recht! Für Witwen streitet!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, '\"Herbei! Wir wollen uns vergleichen!\" So spricht der Herr: \"Sind eure Sünden scharlachrot, sie werden weiß wie Schnee, und sind sie purpurrot, sie werden sein wie weiße Wolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Vergönnt ihr mir ein williges Gehör, dann esset ihr des Landes Gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Doch wollt ihr nicht und trotzet ihr, dann werdet ihr vom Schwert verzehrt. Der Mund des Herrn hat es gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Wie konnte nur zur Dirne werden die getreue Stadt, so voll des Rechts, darinnen die Gerechtigkeit zu Hause war, jetzt aber Mörder. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ward zur Schlacke; dein Trunk verwässert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Abtrünnige sind deine Fürsten, Diebsgesellen, verliebt ist alles in Bestechung und auf der Jagd nach Entgelt. Den Waisen schaffen sie nicht Recht; der Witwen Klagen dringen nicht vor sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Deshalb, so lautet jetzt ein Spruch des Herrn der Heeresscharen, des Starken Israels: - \"Ein Wehe, wenn ich meine Gegner rüge und mich an meinen Feinden räche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Mit dir befasse ich mich gründlich und schmelze deine Schlacken wie mit Lauge aus, entferne alle deine Bleiklumpen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Dann gebe ich dir wieder Richter wie zu Anbeginn, Berater wie am Anfang. Dann nennt man dich \'Gerechte Stadt\', \'Getreue Bürgerschaft\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Allein durch Rechtlichkeit ist Sion noch zu retten, die sich darin bekehren, durch Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Vernichtung aber trifft die Abgefallenen, die Sünder allzumal! Ausrottung jene, die den Herrn verlassen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Zuschanden werden sie der Terebinthen wegen, die euch bezaubern, erröten ob der Haine, nach denen ihr so giert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'wenn ihr entlaubten Terebinthen gleicht und einem Garten ohne Wasser. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Der Starke wird zu Werg, sein Werk zum Funken, und beide brennen miteinander, niemand löscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Der Dinge Zustand, den Isaias, des Amos Sohn, in Juda und Jerusalem geschaut:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'In ferner Zukunft wird der Berg, auf dem das Haus des Herrn gebaut ist, an der Spitze aller Berge stehen; er übertrifft die andern Hügel, und alle Heidenvölker strömen freudig zu ihm hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Und große Völker kommen, also sprechend: \"Auf! Wallen wir zum Berg des Herrn, zum Haus des Jakobsgottes! Belehre er uns über seine Wege! Auf seinen Pfaden laßt uns wandeln.\" Weit über Sion geht die Lehre dann hinaus, und aus Jerusalem das Wort des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Und bei den Heiden hält das Jakobshaus Gericht und spricht bei großen Völkern Recht. Zu Pflügen schmieden sie die Schwerter, zu Winzermessern ihre Lanzen. Kein Heidenvolk zückt gegen andere das Schwert; das Kriegshandwerk hat keine Schüler mehr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'O Jakobshaus! Auf! Wandeln wir im Licht des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Du hast, fürwahr, dein Volk, du Jakobshaus, darniedersinken lassen. Denn voll sind sie von Geistersehern und von Gauklern, wie die Philister, und ihr Ergötzen haben sie an fremden Kindern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Sein Land ist angefüllt von Silber und von Gold, kein Ende seiner Schätze. Sein Land von Rossen voll, kein Ende seiner Wagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Sein Land ist voller Götzen. Man betet an das Machwerk seiner Hände, das ihre Finger selbst gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Die Menschen beugen sich; es beugen sich die Leute tief davor. - Verzeih es ihnen nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Sie sollen auf die Felsen klettern und sich im Staub verkriechen vor dem Schrecken des Herrn, vor seiner hoheitsvollen Herrscherwürde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Dann sinkt der Menschen stolzer Blick; der Leute Hochmut wird erniedrigt. Erhaben ist allein der Herr an jenem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Der Herr der Heeresscharen hat einen Tag bestimmt für jeden Stolzen, Hohen, für jeden Hocherhabenen und Wohlbestellten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Für alle Zedern Libanons, die hohen und die stolzen, für alle Basanseichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'für alle hohen Berge, für alle Hügel, die hochragenden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'für jeden hohen Turm, für jede feste Mauer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'für alle Tarsisschiffe und alle andern Schiffe in der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Da wird der Menschen Stolz gebeugt; der Leute Hochmut wird erniedrigt. Erhaben ist allein der Herr an jenem Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Fort müssen alle Götzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'In Felsenhöhlen kriechen sie und in der Erde Löcher vor des Herren Schrecken, vor seiner hoheitsvollen Herrscherwürde, erhebt er sich, der Erde Schrecken einzuflößen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'An jenem Tage schleudert jeder fort die silbernen und goldnen Götzen, die er zur Anbetung gefertigt, in die Löcher der Ratten und der Fledermäuse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'In Bergesklüfte, Felsenrisse verkriechen sie sich vor des Herrn Schrecken, vor seiner hoheitsvollen Herrscherwürde, erhebt er sich, der Erde Schrecken einzuflößen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Sagt euch deswegen von den Menschen los, in deren Nase nur ein Hauch! Wofür sind sie zu achten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Ja sieh! Der Herr, der Heeresscharen Herr, nimmt aus Jerusalem und Juda den Stab und Stock hinweg, jedwedes Stärkungsbrot, jedwedes Labewasser:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'die Ritter, Krieger, Richter und Propheten, Wahrsager, Älteste,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Anführer, Angesehene, Ratsherren, Baukundige und Redefertige. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, '\"Ich aber gebe Knaben ihnen zu Beamten, und Kinder sollen ihrer walten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'In harten Druck gerät das, Volk, der eine durch den anderen, der Nachbar durch den Nachbarn. Frech fährt den Greis der Knabe an, der Niedere den Angesehenen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Wenn einer seinen Blutsverwandten anhält mit den Worten: \"Du hast noch ein Stück Tuch. Werd unser Oberhaupt, und untertan sein diese Trümmer dir!\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'so ruft er laut an jenem Tage - \"Ich kann nicht Helfer sein. In meinem Hause gibt es weder Brot noch Tuch. Bestellt mich nicht zum Oberhaupt des Volkes!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Jerusalem zerfällt in Trümmer, und Juda stürzt; denn ihre Reden, ihre Taten sind dem Herrn zuwider und reizen seine Hoheit. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Parteilichkeit zeugt wider sie. Von ihren Sünden sprechen sie wie Sodom unverhohlen. Ein Wehe über sie! Sie tun sich selber Böses an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Bedenket, daß die Frommen Gutes, daß ihrer Taten Früchte sie genießen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Doch wehe über einen Frevler! Ihm wird Schlimmes, ihm wird jetzt seiner Taten Lohn zuteil. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Mein Volk! Sein Herrscher ist ein Kind, und Weiber walten seiner. Mein Volk! Verführer sind die Führer dein, verwirrend deiner Wege Lauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Der Herr tritt auf, um Recht zu schaffen; er steht, das Volk zu richten, da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'So geht der Herr denn ins Gericht mit seines Volkes Ältesten und Amtspersonen: - \"Ihr habt den Weinberg abgeweidet. In euren Häusern ist geraubtes Armengut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Was fällt euch ein, mein Volk zu treten, der Armen Antlitz zu zermalmen?\" - Ein Spruch des Herrn, des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'So spricht der Herr: - \"Weil Sions Töchter hochgetragen tun, gereckten Halses gehn und freche Blicke werfen und tänzelnd trippeln, mit den Füßen klirren, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'so macht der Herr der Sionstöchter Scheitel kahl; der Herr macht sie ganz bloß.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'An jenem Tage nimmt der Herr hinweg die wunderbaren die Schleier, Fußspangen, Stirnbänder, Halbmonde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Ohrtropfen, Armketten, die Schleier,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Kopfbinden, die Schrittkettchen und Schleifen, Riechfläschchen, Amulette,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Fingerringe, Stirnreifen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'die Feierkleider, Mäntel, Überwürfe, Taschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'die Spiegel und die Linnentücher, Turbane samt den Schleiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Anstatt des Balsams gibt es Moderduft und statt des Gürtels einen Strick und statt des Lockenwerkes kahle Köpfe, anstatt des Prunkgewandes Sackumgürtung, Brandmale statt der Schönheitsmittel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'So fallen deine Schwächlinge durchs Schwert und deine gute Mannschaft in dem Kampf. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Und seine Tore seufzen trauernd; am Boden sitzt es, ausgeplündert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Und sieben Weiber hängen sich an einen Mann an jenem Tag und sagen ihm: \"Wir wollen unser eignes Brot verzehren, in unser eigenes Gewand uns kleiden. Nur laß uns deinen Namen führen! Hinweg nimm unsere Schmach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'An jenem Tage dient der Sproß des Herrn zu Schmuck und Preis, des Landes Frucht zum Stolz und Ruhm dem Reste Israels, der noch gerettet wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Und wer in Sion übrigbleibt und in Jerusalem noch übrig ist, der heißt ein Heiliger, der in Jerusalem gebucht zum Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Hat erst der Herr der Sionstöchter Unflat abgewaschen, die Blutschuld aus Jerusalem hinweggeschafft durch des Gerichtes Sturmflut und durch Feuerguß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'dann schafft der Herr ob jedem Platz des Sionsberges und über allen den Zusammenkünften daselbst Gewölk und Rauch bei Tag und lichten Feuerglanz bei Nacht. Denn über aller Herrlichkeit ist da die Decke eines Baldachins');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'bei Tag zum Schatten vor der Hitze, und zum Versteck und Schutz vor Guß und Regen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Ich komme meinem Lieblinge mit meinem alten Lied von seinem Weinberg. Mein Liebling hatte einen Weinberg auf dem fetten Bergesrücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Man hatte ihn behackt und ihn entsteint und ihn mit Edelreben angepflanzt und einen Turm in ihm erbaut. Man hieb auch eine Kelter darin aus. Man hoffte, daß er Trauben brächte; er brachte aber böse Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nun, ihr Bewohner von Jerusalem, ihr Männer Judas! Jetzt richtet zwischen mir und meinem Weinberg!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Was gab\'s an meinem Weinberg noch zu tun, das ich ihm nicht getan? Warum nur hoffte ich auf Trauben; Er aber brachte böse Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'So mache ich euch kund, was ich mit meinem Weinberg tue: Weg da mit seinem Zaun! Er werde abgefressen! Hinweg mit seiner Mauer! Zertreten werde er!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Ich lasse ihn zur Wüste werden. Er werde nicht beschnitten, nicht behackt! In Dorn und Distel soll er schießen! Den Wolken untersage ich, mit Regen ihn zu netzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Das Haus von Israel, der Weinberg ist\'s des Herrn der Heeresscharen und Judas Männer seine Lieblingspflanzung. Er wartete auf Rechtsspruch, und sieh da: Rechtsbruch! Auf Guttat hoffte er. Doch sieh da: Bluttat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ein Wehe denen, die sich Haus an Haus anrücken und Feld an Felder reihen, bis daß kein Platz mehr ist und ihr des Landes einzige Bewohner seid!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Beim Herrn, dem Herrn der Heeresscharen! Zur Öde sollen viele Häuser werden, die großen, schönen menschenleer! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Zehn Morgen Weinberg geben einen Eimer nur, ein Malter Aussaat einen einzigen Scheffel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ein Wehe denen, die am frühen Morgen sich dem Bier ergeben, die sich bis in die späte Nacht hinein mit Wein erhitzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'die Zithern, Harfen, Pauken, Flöten und Wein vereinen zum Gelage, doch um des Herren Wirken sich mitnichten kümmern und nicht auf seiner Hände Werke blicken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Fortwandert so mein Volk infolge der Unwissenheit; sein Adel wird dem Hunger preisgegeben, dem Durste seine Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Weit reißt die Unterwelt den Schlund auf, sperrt den Rachen unermeßlich auf. Hinabstürzen Vornehm und Masse. Ihr Schrei ist schrecklich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Dann beugen sich die Menschen; die Männer werden sich demütigen. Der Stolzen Blicke senken sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Der Heeresscharen Herr, erhaben zeigt er sich durch das Gericht und heilig durch Gerechtigkeit der heilige Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Dann weiden Lämmer wiederum auf ihrer Trift; die fetten Jungen käuen wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ein Wehe denen, die die Schuld mit Ochsenstricken herziehn und die Sündenstrafen wie mit Wagenseilen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'die sagen: \"Er beschleunige sein Werk, vollziehe es in Eile, daß wir\'s noch erleben! Herbei mit der Erfüllung, mit dem, was über uns der Heilige Israels beschloß, daß wir es kennenlernen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ein Wehe denen, die das Böse gut und bös das Gute nennen, die Finsternis zu Lichte machen und Licht zu Finsternis, und Bitteres zu Süßem, süß zu bitter! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ein Wehe denen, die in ihren eigenen Augen klug und vor sich selber weise sind! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ein Wehe denen, die im Weintrunk Helden sind und in des Bieres Zubereitung wackere Männer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Die für Bezahlung Schuldige freisprechen, der Unschuld ihre Unschuld streitig machen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Drum, wie des Feuers Zunge Stoppeln frißt und dürres Gras im Feuer flammt, so wird auch ihre Wurzel wie zu Moder. Wie Staub fliegt ihre Blüte auf. Denn sie verwarfen das Gesetz des Herrn der Heeresscharen und lästerten das Wort des Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Deshalb ist gegen seine Nation der Zorn des Herrn entbrannt; er streckte seine Hand aus wider sie und schlug sie nieder. Die Berge zitterten, und ihre Leichen lagen wie der Unrat auf den Gassen. Bei all dem legte sich sein Zorn noch nicht, und seine Hand blieb ausgestreckt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Und für ein Volk aus fernem Land erstellte er ein Banner, und pfiff es von der Erde Rand herbei. Behende kommt es und in Eile. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Kein Müder und kein Matter ist darunter, und keiner schläft, und keiner schlummert, und keiner öffnet seiner Lenden Gürtel, und keiner löst die Riemen seiner Schuhe. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Geschärft sind seine Pfeile; alle seine Bogen sind gespannt. Den Kieseln gleichen seiner Rosse Hufe, dem Wirbelsturme seine Räder. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Gleich einem Löwen brüllt es; gleich einem jungen Leuen brüllt\'s und knurrt und packt und sichert seinen Rauh, und niemand wehrt ihm. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Das knurrt an jenem Tage über ihm wie Meerestoben, und wer hineinschaut in dies Land, der sieht nur bange Finsternis. Kein Lichtstrahl dringt mehr in sein Dunkel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Im Todesjahr des Königs Ozias, da habe ich den Herrn geschaut, auf hohem und erhabnem Throne thronend; sein Schleppgewand erfüllte ganz das Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphe standen um ihn her; sechs Schwingen hatte jeder. Mit zweien deckte er sein Angesicht, mit zweien seine Füße; mit zweien schwebte er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Und einer rief dem andern zu und sprach: \"Der Heilige, der Heilige, der Heilige, der Herr der Heeresscharen! Sein Ruhm der ganzen Erde Fülle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Da zitterten sogar die Schwellenlager von diesem lauten Rufen; das Haus ward voller Rauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Da sprach ich: \"Wehe mir! Ich bin verloren. Ich bin ein Mann unreiner Lippen und lebe auch inmitten eines Volks unreiner Lippen. Und dennoch schaue ich den König selbst mit meinen Augen, den Herrn der Heeresscharen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Da schwebte einer von den Seraphim zu mir mit einem Glühstein in der Hand, den er mit einer Zange vom Altar genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Damit berührt\' er meinen Mund und sprach: \"So dies an deine Lippen rührt, hinweg ist deine Missetat, und deine Sünde ist gesühnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Da hörte ich des Herren Stimme sprechen: - \"Wen soll ich senden? Wer von uns mag gehen?\" - Ich sprach: \"Ich bin bereit; mich sende!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Er sprach: \"So geh und sprich zu diesem Volk: \'Zuhören sollt ihr stets und dennoch nichts verstehn! Zusehen stets und dennoch nichts erkennen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Verstocke dieses Volkes Herz! Verhärte seine Ohren! Verklebe seine Augen! Dann sieht es nichts mit seinen Augen und hört nichts mehr mit seinen Ohren und faßt nichts mehr mit seinen Sinnen, und so bekehrt sich\'s nicht und findet keine Heilung.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Ich fragte: \"Herr! Bis wann?\" Er sprach: \"Bis daß verheert die Städte sind und unbewohnt und menschenleer die Häuser, und bis das Ackerland zur Wüstenei verheert.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Die Menschen schickt der Herr in weite Ferne, und eine große Leere wird im Lande sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Wenn auch ein Zehntel noch darin verblieben, von neuem würde dieses abgeweidet. Doch so, wie bei gefällten Eichen oder Terebinthen ein Stumpf vorhanden bleibt, wird auch sein Stumpf ein heiliger Sprößling werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Zur Zeit des Achaz; der ein Sohn des Jotam war, wie der ein Sohn Ozias\', des Judakönigs, zogen Resin, Syriens König, und Israels König Pekach, des Remalja Sohn, hin vor Jerusalem, es zu erstürmen. Doch er vermochte nicht, sie zu bekämpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Gemeldet ward dem Davidshause: \"Verbündet hat sich Syrien mit Ephraim\", da bebte sein und seines Volkes Herz, so, wie des Waldes Bäume vor dem Sturme beben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Der Herr sprach zu Isaias: \"Geh jetzt zu Achaz, du und Searjasub, dein Sohn, dort an das Ende der Rinne aus dem obern Teiche, dort an die Straße nach dem Walkerfelde zu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Und sprich zu ihm: Sei völlig ruhig, ohne Furcht! Laß deinen Mut nicht sinken vor diesen beiden Fackelstummeln, die durch den fürchterlichen Zorn Resins und Syriens und des Remaljasohnes also qualmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Zwar sinnen Syrien und Ephraim und der Remaljasohn gar Schlimmes wider dich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '\"Wir wollen gegen Juda ziehn, es hart bedrängen und für uns erobern und dann zum Könige darin den Tabelsohn einsetzen!\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Dagegen spricht der Herr, der Herr: \"Daraus wird nichts. Das gibt es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Damaskus, Syriens Haupt, und Resin von Damaskus wird ebenso wie Ephraim vernichtet, - und dies nach fünfundsechzig Jahren, daß es kein Volk mehr ist, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Samaria auch, das Haupt von Ephraim, und von Samaria Remaljas Sohn. Wenn ihr nicht glaubt, dann bleibt ihr nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Dann ließ der Herr zu Achaz weiter sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '\"Nun fordere ein Zeichen von dem Herrn, deinem Gott, sei\'s unten in der Gruft, sei\'s oben in der Luft!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Achaz entgegnete: \"Ich stelle keine Bitte; ich will den Herrn doch nicht versuchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Da sagte er: \"So hört, die ihr zum Davidshaus gehört! Ist\'s euch zuwenig, Menschen zu ermüden, daß ihr auch meinen Gott ermüdet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Trotzdem gibt euch der Herr von selbst ein Zeichen: Die Jungfrau wird empfangen und einen Sohn gebären und ihn Immanuel benennen - Gott mit uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Er wird genießen Milch und Honig, wenn er das Böse zu verschmähen, das Gute zu erwählen lernt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Bevor der Knabe nämlich Böses zu verschmähen und Gutes zu erwählen lernt, wird schon das Land verlassen sein, wovor du bangst der beiden Könige wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Doch läßt auch über dich, dein Volk und deines Vaters Haus der Herr noch Zeiten kommen, wie sie noch nie gewesen, seitdem sich Ephraim von Juda trennte, mit Hilfe des Assyrerkönigs.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'An jenem Tage pfeift der Herr den Bremsen, die an dem Ende der ägyptischen Ströme sitzen, sowie den Wespen im Assyrerlande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Sie kommen allesamt und lagern sich in Tälerschluchten, in Felsenspalten, in allen Dorngestrüppen, an allen Wasserplätzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'An jenem Tage läßt der Herr mit einem Messer, das jenseits des Stroms gedungen war, dem König von Assyrien, euch Haupt und Beine scheren und selbst den Bart nimmt\'s weg. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Wer dann an jenem Tag sich eine junge Kuh noch halten kann und ein paar Schafe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'der kann von lauter Sahne leben beim Überfluß der Milch; von Sahne lebt und Honig dann ein jedes, das im Lande ist. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Geschehen wird\'s an jenem Tag, daß jeder Platz, wo tausend Reben stehn im Wert von tausend Silberlingen, zu Dorn und Distel wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Mit Pfeil und Bogen muß man ihn betreten: denn alles Land wird Dorn und Distel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Und all die Berge, ehedem behackt, die suchst du nicht mehr auf, aus Furcht vor Dorn und Distel. Die Rinder treibt man hin; von Schafen läßt man sie zertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Dann sprach der Herr zu mir: \"Nimm her dir eine große Tafel und schreib in Volksschrift also drauf: \'Her stürzt die Plünderung.\' \'Her rast der Raub!\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Glaubwürdige Männer stellte ich als Zeugen auf, Urias, einen Priester, und Zacharias, Jeberechjas Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Dann nahte ich mich der Prophetin; sie wurde guter Hoffnung und schenkte einem Sohn das Leben. Dann sprach der Herr zu mir: \"Benenne ihn mit Namen: \'Her stürzt die Plünderung.\' \'Her stürzt der Raub!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Denn ehe noch der Knabe rufen kann: \'Mein Vater! Meine Mutter!\', wird schon der Reichtum von Damaskus vor dem König der Assyrer hergetragen sein sowie die Beute von Samaria.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Dann sprach der Herr zu mir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '\"Verächtlich denkt dies Volk vom sanften Bach Siloa und von dem Wassergraben gegen den Remaljasohn und Resin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'So läßt der Herr deswegen aber sie herfluten das mächtige, gewaltige Gewässer aus dem Strom - den König von Assyrien und seine ganze Wucht -, und über seine Dämme steigt es allenthalben, und über alle seine Ufer tritt es aus. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'In Juda dringt es ein und überschwemmt und überströmt es; es reicht ihm bis zum Halse. - Und seiner Flügel Spanne bedeckt dein Land, so breit es ist, Immanuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Weint, Völker, bebt! Horcht auf, ihr fernen Gegenden der Erde all! Zum Kampfe rüstet euch! Erbebt! Zum Kampf rüstet euch! Erbebt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Auf Schmiedet Pläne! Sie werden doch vereitelt. Faßt nur Beschlüsse! Sie werden doch nicht durchgesetzt. Mit uns ist Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Ja, also sprach der Herr zu mir, und seine Hand lag schwer auf mir, um mich zu warnen, die Wege dieses Volkes zu betreten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '\"Ihr sollt nicht Hochverrat es nennen, was dieses Volk als Hochverrat bezeichnet! Habt keine Furcht vor seiner Furcht-, erschauert nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Für hehr und heilig sehet an den Herrn der Heeresscharen! Nur der sei eure Furcht! Nur der sei euer Schrecken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Er wird wie ein Gewicht, ein Stein des Anstoßes, ein Block des Strauchelns für beide Häuser Israels, wie eine Schlinge, eine Falle für die Einwohner Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Dort stoßen viele sich, zerschmettern sich im Fall; hier werden viele in das Garn verwickelt und gefangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Verschnüre die Vermahnung! Versiegle die Verkündigung mit Siegelwachs!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Doch ich vertraue auf den Herrn. Er hat zwar seinen Blick dem Jakobshaus entzogen; und doch, ich hoffe fest auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Fürwahr, ich selber samt den Söhnen, die mir der Herr geschenkt, sind Zeichen jetzt und Vorbilder in Israel, geschenkt vom Herrn der Heeresscharen, der auf dem Sionsberge wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Und wenn man zu euch sagt: \"Befragt die Totengeister und die Wahrsaggeister, die piependen, die murmelnden!\" Dann sage ich: \"Soll nicht ein Volk nur seinen Gott befragen? Soll man die Toten fragen für die Lebenden?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Doch stimmen sie in Mahnung und Verwarnung nicht überein mit jenem Spruch, in dem kein Dunkel ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'dann zieht man darob hin, gebeugt und hungernd, und weil man Hunger leidet, gerät man in Verzweiflung und flucht dann seinem Könige und seinen Göttern. Wenn man nach oben schaut');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'und blickt man auf die Erde, nur ängstigendes Dunkel und jämmerliche Finsternis! - Doch nimmer kennt Ermüdung, der sich ergießt darüber. Zuerst eilt er ins Land von Zabulon und Naphtali. Zuletzt bedrückt er auch den Meeresweg, am Jordan das Gelände samt dem Heidengau.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Das Volk, das da im Dunkel wallt, es sieht ein mächtig Licht, und über den Bewohnern finstern Landes wird es hell. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Viel schaffst Du frohen Jubels, und groß machst Du die Freude; man freut sich unter Deinen Augen wie bei Erntefreuden, wie bei der Beuteteilung jauchzen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Die Last des Jochs, das Holz auf seinem Nacken, des Treibers Stock zerbrichst Du wie am Midianstage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Denn jeder Schuh, der dröhnend stampft, der Mantel, blutbefleckt, verfällt dem Brand, dem Fraß des Feuers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Ein Kind wird uns geboren; ein Sohn wird uns geschenkt, das Herrscherzeichen auf der Schulter; sein Name lautet: \"Wunderbarer Rater, Gott und Held, ein ewiger Vater, Friedensfürst\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Das Reich wird groß, endlos der Friede. Er nimmt Besitz von Davids Thron und Reich, errichtet dies aufs neue, festigt es durch Recht und durch Gerechtigkeit von nun an bis auf ewig. Dies wirkt des Herrn der Heeresscharen Eifer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Der Herr entsandte aber gegen Jakob einst ein Wort; es ging auf Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Sein ganzes Volk erfuhr\'s, ganz Ephraim und die Bewohner von Samaria, weil sie in Übermut und stolzem Sinne sprachen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, '\"Stürzten Ziegelsteine ein, mit Quadern bauen wir es auf. Und hieb man Sykomoren ab, ersetzen wir\'s mit Zedern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Da ließ der Herr des Resin Haß dawider lodern: Er stachelt seine Feinde an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'die Syrer hier im Osten, im Westen die Philister. Sie fressen Israel an jeder Seite an. Und dennoch konnte sich sein Zorn nicht legen; noch immer blieb sein Arm gereckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Es kehrte sich das Volk nicht um zu ihm, der es geschlagen, und frug nichts nach dem Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Drum hieb der Herr von Israel den Kopf und Schweif, Palmzweig und Binse ab, an einem Tage. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Der Alte und der Angesehne sind der Kopf, der lügenlehrende Prophet der Schweif.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Irrleiter sind die Leiter dieses Volkes, verleitet die Geleiteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Drum freut der Herr sich seiner jungen Männer nicht und ist den Waisen und den Witwen nimmer gnädig. Sie alle waren ruchlos, Bösewichte, und jeder Mund sprach frevelhaft. Und also konnte sich sein Zorn nicht legen; noch immer blieb sein Arm gereckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Wie Feuer brannte Schlechtigkeit, verzehrte Dorn und Distel und loderte im dicht verwachsenen Wald empor, im Rauche wirbelnd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Verfinstert ward das Land beim Zorn des Herrn der Heeresscharen; das Volk ward wie des Feuers Fraß; der eine schonte nicht des andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Sie fraßen, was zur rechten Seite, verschlangen hungernd, was zur Linken, und wurden doch nicht satt. Ein jeglicher fraß seines Armes Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manasse Ephraim und Ephraim Manasse, sie miteinander Juda. Und dennoch konnte sich sein Zorn nicht legen; noch immer blieb sein Arm gereckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ein Wehe denen, die verderbliche Gesetze machen! Ein Wehe jenen Schreibern, die Plackereien schreiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'die von dem Rechtsweg die Geringen drängen und meines Volkes Arme ihres Rechts berauben! Die Witwen werden ihre Beute, und Waisen plündern sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Was wollt denn ihr am Tag der Strafe machen, wenn die Verheerung aus der Ferne kommt? Zu wem flieht ihr um Hilfe rufend? Wo laßt ihr eure Schätze?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Wer sich dem Kerkermeister nicht ergibt, verfällt dem Henker. - Und dennoch konnte sich sein Zorn nicht legen; noch immer blieb sein Arm gereckt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Doch wehe dem Assyrer. Meines Zornes Stock! In seiner Hand ist meines Grimmes Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Ich send ihn gegen ein unheilig Volk; ich biete gegen eine Nation ihn auf, mit der ich zürne, sie zu berauben, sie zu plündern, sie zu zertreten gleich dem Straßenkot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Er aber meint\'s nicht so; dies hat er nicht im Sinn. Gesonnen ist er zu vertilgen, nicht wenige Völker auszurotten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'So sagt er ja: \"Sind meine Obersten nicht alle Könige?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Erging\'s nicht Kalno so wie Karkemis? Nicht Hamat so wie Arpad? Samaria wie Damaskus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Wie meine Hand der Götter Königreiche traf, und ihrer Götzenbilder waren\'s mehr als die Jerusalems und die Samarias, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'da sollte ich, was ich Samaria und seinen Götzen angetan, nicht auch Jerusalem und seinen Götzen tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Hat nur der Herr sein ganzes Werk erst an dem Sionsberg und an Jerusalem vollzogen, - \"so strafe ich kopfüber auch des Assurkönigs stolzen Sinn und unverhofft sein übermütiges Geschau\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Er sagt: \"Durch meinen starken Arm und meine Weisheit hab ich\'s ausgeführt; denn ich bin klug. Der Völker Grenzen habe ich verrückt und ihre Schätze ausgeplündert und die Bewohner fürchterlich geschwächt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Und meine Hand griff in der Völker Reichtum wie in Nester. Wie man verlassene Eier sammelt, so habe ich die ganze Erde eingesteckt. Da gab\'s kein Flügelschlagen, kein Schnabelsperren und kein Zwitschern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Rühmt sich die Axt denn vor dem Fäller, und protzt die Säge vor dem Säger? - Als ob ein Stab den schwänge, der ihn schwingt! Als höb ein Stock den auf, der nicht von Holz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Der Herr, der Heeresscharen Herr, schickt Abzehrung deswegen seinen Starken, und seiner Pracht entbrannt ein Brand wie Feuerbrand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'In Feuer wandelt sich das Licht von Israel, sein Heiliger in eine Flamme. Sie sengt und frißt an einem Tag sein Dorngebüsch und seine Disteln');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'und seines Waldes Pracht samt seinem Fruchtgefilde; die Seele samt dem Leib vernichtet er, wie wenn dahin ein Krankes siecht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Der Bäume Rest in seinem Wald wird zählbar sein; ein Kind vermag sie aufzuschreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Was übrigbleibt von Israel und was von Jakobs Haus entrinnt, verläßt sich nimmermehr an jenem Tag auf einen Büttel. Aufrichtig baut es auf den Herrn, den Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ein Rest kehrt um, der Jakobsrest zum starken Gott. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Wenn Israel, Dein Volk, wie Sand am Meere wäre, allein ein Rest davon bekehret sich. Ein Garaus, festbeschlossen, bricht mit gerechter Strenge ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Verheerung, wenn auch abgekürzt, verhängt der Herr, der Heeresscharen Herr, für alle Teile dieses Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, '\"Trotzdem\", so spricht der Heeresscharen Herr, \"hab keine Furcht, mein Volk, das hier in Sion wohnt, vor dem Assyrer, der dich mit dem Stocke schlägt und seine Rute gegen dich erhebt nach Art Ägyptens!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Denn nur noch eine kleine Weile, dann ist der Zorn vorüber und geht mein Grimm zu Ende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Dann schwingt der Heeresscharen Herr die Peitsche über ihn zu Streichen, wie Midian sie am Rabenfelsen spürte; er streckt dann seine Rute aus, wie einstens übers Meer auf dem Ägypterwege. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'An jenem Tage schwindet seine Last von deinem Nacken, sein Joch von deinem Halse. Zunichte wird der Fremden Joch. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Er geht auf Ajat los und zieht durch Migron. Zu Michmas läßt er sein Gepäck. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Sie ziehen durch den Paß; zu Geba sind die Nachtquartiere. Da zittert Rama; Sauls Gibea flieht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Schrei laut auf, Gallims Tochter! Horch auf, Laisa! Gib weiter, Anatot, den Schrei!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena schwankt von dannen; Gebims Bewohner fliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'In Nob steht er noch heute und macht dem Berg der Sionstochter eine Faust, dem Hügel von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Doch seht! Der Herr, der Heeresscharen Herr, entästet schrecklich das Gezweige. Die hohen Wipfel werden abgeschlagen, und Ragendes fällt ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Er fällt des Waldes Dickicht mit der Axt; der Libanon stürzt hin mit Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Dann sprießt ein Reis aus Jesses Stumpf; ein Schößling bricht hervor aus seinen Wurzeln. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Auf ihn läßt sich der Geist des Herrn hernieder, der Geist der Weisheit, des Verstandes, der Geist des Rates und der Stärke, der Geist der Kenntnis und der Furcht des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Sein Scharfsinn ruht nur auf der Furcht des Herrn; er richtet nicht nach seiner Augen Sicht und urteilt nicht nach dem Verhör.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Er richtet in Gerechtigkeit die Armen und spricht in Redlichkeit Bescheidenen im Land das Urteil. Er schlägt den Bösewicht mit seines Mundes Stock; den Frevler tötet er mit seiner Lippen Hauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Sein Hüftgurt ist Gerechtigkeit, und Treue seiner Lenden Gürtel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Der Wolf ist bei dem Lamm zu Gast, der Panther lagert bei dem Böcklein, und Kalb und Löwe fressen miteinander; ein kleiner Knabe treibt sie aus. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Und Kuh und Bär befreunden sich und werfen beieinander ihre Jungen, und Stroh frißt gleich dem Rind der Löwe. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'An Otternhöhlen spielt der Säugling; ans Natternauge strecken die Entwöhnten ihre Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nicht wirken Böses sie und nicht Verderb auf meinem heiligen Berg, soweit er reicht. - Denn wie den Meeresboden Wasser decken, so wird das Land voll von des Herrn Erkenntnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Da steht an jenem Tage Jesses Wurzelsproß als aufgestecktes Banner für die Völker da und wird von Heidenvölkern aufgesucht, und wo er weilt, der Ort ist herrlich. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'An jenem Tag erhebt der Herr zum zweitenmal die Hand, um seines Volkes Rest sich zu erwerben, der übrig ist aus Assur und Ägypten, aus Patros und aus Äthiopien, aus Elam, Sinear und Hamat und aus den Küstenländern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Er steckt ein Banner für die Heidenvölker auf und sammelt die Verstoßnen Israels und die Versprengten Judas. Er sammelt sie aus den vier Gegenden der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Dann schwindet Ephraims Neid, und ausgerottet wird die Feindschaft Judas, und Ephraim beneidet Juda nimmermehr, und Juda ist auf Ephraim nicht weiter eifersüchtig. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Sie stürzen stürmisch sich am Meer auf die Philister; verbündet plündern sie des Ostens Söhne. Die Hände legen sie an Edom und an Moab und machen Ammons Söhne hörig. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Der Herr ließ einst die Zunge des ägyptischen Meeres schwinden. So zeigt er nunmehr seine Faust dem Strom in seinem Damm; in sieben Bäche schlägt er ihn und macht ihn gangbar selbst für Schuhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'So gibt es nunmehr eine Straße für seines Volkes Überrest, für die, die aus Assyrien noch übrig, wie einst für Israel bei seinem Auszug aus Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'An jenem Tage wirst du sprechen: \"Ich danke Dir, o Herr, Du hast auf mich gezürnt; Dein Zorn hat sich gelegt, und nun bist Du mein Tröster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Fürwahr, Du bist mein hilfereicher Gott, auf den ich furchtlos mich verlasse. Dem Herren gelten meine Ruhmeslieder, ward er doch mir zum Heile.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Schöpft jubelnd aus des Heilborns Wasser');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'und ruft dabei an jenem Tage: \"Dem Herrn sei Dank!\" Mit Stolz nennt seinen Namen! Tut Völkern seine Taten kund! Verkündet, daß sein Name hoch erhaben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Lobsingt dem Herrn! Denn große Dinge hat er ausgeführt!. Dies werde aller Welt bekannt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Frohlocke, juble, du Bewohnerschaft von Sion! Denn groß in deiner Mitte ist der Heilige Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Ein Ausspruch über Babel, worüber ein Gesicht Isaias, Amos\' Sohn, empfangen hat: -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Auf freiem Berge hißt ein Banner! Ruft ihnen zu mit lauter Stimme! Winkt mit der Hand, auf daß der Fürsten Heerbann komme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, '\"Ich selber biete meine Scharen auf; für meinen Zorn berufe ich die Helden mein, ja, meine siegesfrohen Leute.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Horch! Getümmel auf den Bergen wie von großem Volke! Horch! Gelärm von Königreichen, von Heidenvölkern dort vereint. Jetzt mustert der Heerscharen Herr ein Kriegsheer aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Von fernem Lande kommen sie, vom Himmelsrande her. Sie sind des Herren Rachediener zum Untergang der ganzen Erde. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Heult auf! Der Tag des Herrn ist nah; Lawinen aus dem Hochgebirge gleich kommt er heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Die Hände aller werden schlaff darob; ein jeglich Menschenherz zergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Betäubt werden sie sein, und Krämpfe, Wehen packen sie; sie winden sich gleich den Gebärenden. Sie sehen starr einander an; wie Flammen glüht ihr Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Jetzt kommt der Tag des Herrn, so fürchterlich, mit Grimm und Zornesglut. In Öde wandelt er die Erde, und ihre Sünder tilgt er draus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Des Himmels Sterne leuchten nimmer, noch seine Sternbilder in ihrem Glanz. Verdunkelt geht die Sonne auf; nicht glänzt der Mond in seinem Lichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, '\"Ich suche an der Welt die Bosheit heim und an den Frevlern ihre Missetaten. Dem Stolz der Übermütigen bereite ich ein Ende; der Wüteriche Hochmut beuge ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Die Menschen mach ich seltener als Gold, die Sterblichen noch teurer als das Ophirgold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Deshalb erschüttre ich den Himmel. Die Erde bebt von ihrer Stätte bei dem Grimm des Herrn der Heerscharen am Tage seiner Zornesglut. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Und wie verscheuchte Rehe, wie Schafe ohne Hirten kehrt ein jeder zu seinem Volk zurück, in seine Heimat flieht ein jeder. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Und wer sich finden läßt, der wird durchbohrt; wer aufgegriffen wird, der fällt durch\'s Schwert. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Vor ihren Augen werden Säuglinge zerschmettert, geplündert ihre Häuser, geschändet ihre Weiber. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Ich biete gegen sie die Meder auf, die nicht des Silbers achten und nach Gold nicht gieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Die Bogenschützen strecken junge Männer nieder; sie schonen keine Leibesfrucht und schauen nicht auf Kinder mitleidsvoll. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Und Babylon, der Königreiche Krone, der stolzen Zierde der Chaldäer, ergeht\'s wie Sodom und Gomorrha, die Gott vernichtet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Auf ewig bleibt es unbewohnt, durch alle Zeiten unbesiedelt. Kein Araber schlägt sein Gezelt dort auf, und keine Hirten lagern sich darin. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Nur wilde Katzen haben dort ihr Lager und Uhus füllen ihre Häuser, und Strauße hausen da; Bocksgeister tanzen dort. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'In ihren Burgen werden die Schakale und in Luftschlössern Hyänen das Geschrei erwidern. Der Anbruch seiner Zeit ist nah, und seine Tage zögern nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Erbarmt der Herr sich Jakobs abermals, erwählt von neuem Israel und bringt sie heim, dann schließen Fremdlinge sich ihnen an, gesellen sich zu Jakobs Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Sie nehmen mit sich von den Völkern Leute und führen sie in ihre Siedlung. Israels Haus macht auf dem Boden seines Herrn sie sich zu Knechten und zu Mägden. So werden sie nun ihrer Fänger Fänger und schalten über ihre Treiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Verschafft der Herr dir Ruh von deinem Kummer, deiner Angst und von dem schweren Dienst, worunter du gelitten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'dann stimme auf den Babelkönig dieses Spottlied an und rufe: \"Wie muß der Treiber feiern und feiern das Gelärme?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Zerbrochen hat der Herr der Frevler Stock und der Tyrannen Zepter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'das Völker grimmig schlug mit Schlägen ohne Ende, im Zorne Heidenvölker niedertrat mit Tritten mitleidslos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nun ruht und rastet alle Welt; sie jubelt auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Selbst die Zypressen freun sich über dich, die Zedern auf dem Libanon: \'Seitdem du dich gelegt, kein Fäller kommt mehr, uns zu fällen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Die Schattenwelt dort unten zittert dann bei deinem Kommen; die Schatten jagt sie auf, der Erde Führer insgesamt. Sie heißt von ihren Thronen sich erheben die Könige der Heidenvölker allesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Sie alle heben an und sagen dir: \'Auch du bist hingesiecht wie wir; du bist uns gleich geworden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Hinab ins Totenreich ist deine Pracht gestürzt, mit dem Getöne deiner Harfen. Das Lager unter dir sind Maden, und Gewürm ist deine Decke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Wie bist vom Himmel du gefallen, du Glanzstern, Sohn der Morgenröte! Wie auf die Erde hingeworfen, du Völkersieger!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Du freilich hast bei dir gedacht: \'Ich steige auf zum Himmel und stelle über Gottes Sterne meinen Thron und setze mich auf den Versammlungsberg im hohen Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Zu Wolkenhöhen steige ich empor und mache mich dem Höchsten gleich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Nun stürzest du ins Schattenreich, zur allertiefsten Grube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Die einstens dich gesehen, blicken dich voll Spannung an, betrachten dich und sagen: \'Ist das der Mann, der einst die Erde zittern ließ, in Schrecken Königreiche setzte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Und der die Welt zur Wüste machte und ihre Städte niederriß, nicht losgab seine Häftlinge nach Hause?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Die Könige der Heidenvölker insgesamt, in Ehren ruhen sie: ein jeder ruht in seiner Gruft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Doch du wirst weggeworfen ohne Grab wie ein verächtlich Ding, umgeben von Erwürgten, Schwertdurchbohrten, die zur Vergessenheit der Grube fahren. Wie ein zertreten Aas');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'wirst du im Grab jenen nicht beigesellt. Du hast dein Land verwüstet, dein eigen Volk erwürgt. Nicht werde mehr der Missetäter Brut gedacht! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'So richtet eine Schlachtbank her für seine Söhne, ob ihrer Ahnen Missetat! Sie sollen nicht mehr auferstehen, die Erde zu erobern!\' - Dann wird die Welt von Städten wieder Voll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, '\"Aufstehen will ich wider sie\", ein Spruch des Herrn der Heeresscharen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '\"Ich rotte Namen, Nachkommen und Schoß und Sproß aus Babel aus und mache es zum Sumpf, mit Rohr bewachsen, in tiefen Schlamm versunken.\" - Ein Spruch des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Geschworen hat der Heeresscharen Herr: \"Wie ich\'s beschlossen, soll\'s geschehen. Wie ich mir\'s vorgenommen, soll\'s auch werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'In meinem Land zerschmettere ich den Assyrer, zertrete ihn auf meinen Bergen, auf daß sein Joch von ihnen schwinde und seine Last von ihrem Nacken weiche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Das ist der Plan, geplant für alle Welt, und das der Arm, der über alle Heidenvölker ausgestreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Der Heeresscharen Herr beschließt es. Wer will es hindern? Ist ausgestreckt sein Arm, wer biegt ihn rückwärts?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Im Todesjahr des Königs Achaz erfolgte dieser Ausspruch:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '\"Freu dich, Philisterland, nicht allzu sehr, daß jetzt die Rute, die dich schlug, zerbrochen ist! Dem Schlangenstamm entspringt ja eine Natter; ein Flügeldrache ist ihr Junges.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Die Ärmsten aber können auf die Weide gehen, und Elende in Sicherheit sich lagern; dagegen töte ich durch Hunger deinen Stamm; er mordet deinen Rest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Ihr Tore, wimmert! Klaget, Städte! Erbebe, ganz Philisterland! Denn qualmgleich kommt es aus dem Norden; nicht einer bleibt zurück bei seinen Scharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Was wird man dann den Heidenboten sagen? \'Der Herr hat Sion fest gegründet, und dort besitzen die Armen seines Volkes eine Zufluchtsstatt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Ein Ausspruch aber Moab: \"Gewiß! Schon in der Angriffsnacht ist\'s aus mit Kir Moab. Gewiß! Schon in der Angriffsnacht ist\'s aus mit Ar Moab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Zum Tempel schreitet Dibon weinend auf die Höhen; zu Nebo und zu Medeba heult Moab. Auf allen Häuptern sieht man Glatzen, und jedes Kinn ist ausgerauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Auf seinen Straßen schreitet man im Trauerkleide; auf seinen Dächern, seinen Plätzen in Tränenfluten alles klagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Sie schreien, Hesbon und Elale; bis Jahaz hört man ihr Geschrei. Dort schlottern Moabs Hüften; bis in die Seele zittert es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Ich muß von Herzen über Moab jammern; bis Soar ziehen seine Flüchtlinge und bis zur dritten Furt. Hinan steigt man die Steige von Luchit mit Weinen; den Weg herab nach Horonaim füllen sie mit Jammerklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Die Wasser Nimrims sind verschüttet. Das Gras verdorrt; das Kraut verwelkt, nichts Grünes mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Drum tragen sie, was sie erspart, und das, was sie gerettet, hin zum Weidenbach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Doch rings um Moabs Grenzen schallt Geschrei; bis Eglaim tönt sein Geheul und bis zum Elimbrunnen sein Geschrei: -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Denn Dimons Wasser sind voll Blut. Bei Dimon schwelle ich sie wieder an; ich fülle sie mit Flüchtlingen der Moabiter an und auch den letzten Rest vernichte ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Von Sela schickt zum Sionsberg den Sohn des Landesfürsten durch die Wüste!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, '\"Die Moabstöchter an den Arnonfurten gleichen\", so soll er sprechen, \"aus dem Nest verscheuchten Vögeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Helft mit gutem Rat! Erfüllt die Bitte: Mach am hohen Mittag deine Schatten gleich der Nacht! Verstecke die Vertriebenen! Die Flüchtigen verrate nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Ach! Dürften die Versprengten Moabs bei dir weilen! Sei ihnen Schutz vor dem Verwüster, bis vorüber die Bedrückung und die Verwüstung überstanden und die Zerstörer aus dem Land verschwunden sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Durch solche Güte wird der Thron befestigt; dann thront in Davids Zelt gewiß ein Richter, der des Rechtes sich befleißt und willig ist zum Edelmut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '\"Wir haben es vernommen\", wird man sagen. -\"Die Frechheit Moabs war stets groß, sein Stolz, sein Übermut, sein herrisches Gehaben, sein ungeziemendes Geschwätz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Drum mag auch Moab über Moab jammern; das ganze Land mag jammern über Kir Charesets Traubenkuchen! Mögt ihr nur mutlos werden, ganz zerschlagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Ja! Die Gefilde Hesbons sind gewesen; gewesen Sibmas Weinstock, dessen Edelreben bis zum Heidenbaala reichten und bis nach Jazer langten, sich durch die Wüste schlangen, und dessen Ranken sich noch weiter dehnten und übers Meer selbst gingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Ich weine deshalb um den Weinstock Sibmas, daß man\'s in Jazer hört. Ich weine, Hesbon und Elale, heftig über dich. In deinen Sommer und in deinen Herbst ist ein gar rauher Klang gedrungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Weg aus dem Gartenland ist Freud und Jubel, und in den Weinbergen wird nicht gesungen, nicht gejauchzt. Nicht keltert Wein, wer sonst gekeltert. Verstummen lasse ich das Kelterlied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Mein Inneres seufzt deshalb einer Zither gleich; mein Herz seufzt über Kir Chareset.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Mag Moab offenkundig sich zur Höhe müde laufen, in seinen Tempel zum Gebete gehn, es richtet doch nichts aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Das ist das Wort, das über Moab einst der Herr geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Jetzt aber redet so der Herr: - \"In noch drei Jahren, gerechnet nach Taglöhners Jahren, wird Moabs Adel zugleich verringert mit der ganzen großen Masse. Was übrigbleibt, wird unbedeutend wenig, wird ohnmächtig sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Ein Ausspruch über Damaskus: \"Die Stadt Damaskus wird verschwinden; es wird aus einer Stadt ein Trümmerhaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Verlassen werden sein der Steppe Städte, den Herden überlassen. Sie lagern sich daselbst, und niemand scheucht sie auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Ein Bollwerk Ephraims hört auf zu sein, das Reich der damaszenischen und andern Aramäer, die Israel wie eine Glorie umstrahlen.\" Ein Spruch des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Doch wird an jenem Tag auch Jakobs Herrlichkeit gemindert; sein wohlgenährter Körper schwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Und so wird\'s sein, wie wenn ein Schnitter Halme rafft und mit der Hand die Ähren schneidet, wie bei der Ährenlese im Tal Rephaim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, '\"Nachlese bleibt von ihm nur soviel übrig, gleichwie wenn man Olivenbäume klopft; so zwei, drei Beeren bleiben an des Astes Spitze, so vier und fünf in seinem Fruchtgezweig.\" - Ein Spruch des Herrn, des Gottes Israels:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, '\"An jenem Tage schaun die Leute wieder auf zu ihrem Schöpfer, und ihre Augen blicken zu dem Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Und niemand schaut sich weiter um nach den Altären, seiner Hände Werk, und niemand blickt mehr hin zu dem, was seine Finger einst gemacht, zu Pfählen, Rauchaltären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'An jenem Tag sind seine festen Städte so verlassen wie einst der Amoriter und Hiwiter Städte, die vor den Söhnen Israels im Stich sie ließen, und die zur Wüste wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Denn deines Heiles Gott hast du vergessen; du dachtest an den Felsen nicht, nicht an dein Bollwerk. Magst du auch Liebesgärtchen anlegen und fremde Reiser einpflanzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'und bringst du sie, kaum eingepflanzt, zum Sprossen, am andern Morgen dein Gewächs zum Blühen, die Ernte schwindet doch dahin am Tag der Trauer und des bittern Schmerzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ha! Welch ein Tosen vieler Völker! Wie Meerestosen tosen sie. Ein Brausen von Nationen! Wie starker Wasser Brausen brausen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Wie großer Wasser Brausen brausen die Nationen. Er schilt auf sie; sie fliehen in die Ferne, gejagt wie Spreu auf Bergen vor dem Sturm, wie vor der Windsbraut Wirbelstaub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Zur Abendzeit Bestürzung! Vor Morgenanbruch sind sie nicht mehr da. Das ist das Schicksal unsrer Plünderer und unserer Berauber Los.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Hör, Land der Segelschiffe, Zugang zu Äthiopiens Strömen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'das Boten auf dem Meere sendet in den Papyruskähnen übers Meer! Ihr schnellen Boten, eilt, zum Volke, hochgereckt und blank, zum Volke, fürchterlich, seitdem es ist, zum Heidenvolke wundersamen Wohlstands und Behagens, des Land von Flüssen wird durchquert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'All ihr Bewohner rings des Erdenrundes, die ihr auf Erden wohnt! Schaut auf, wenn ein Panier auf Bergen aufgerichtet wird! Horcht auf, wenn die Posaune tönt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Denn also spricht der Herr zu mir: \"Ich schaue hin auf meine Stätte wie Strahlenglut bei Sonnenschein, wie Taugewölk zur Erntezeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Noch vor der Ernte, wenn die Blütezeit vorüber und wenn die Blume sich zur reifen Traube bildet, wenn man die Reben mit den Winzermessern schneidet, die Ranken wegnimmt und zerknickt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'da werden allesamt den Vögeln auf den Bergen, dem Wild des Feldes preisgegeben. Im Sommer sind die Raubvögel bei ihnen; im Winter haust alles Getier des Feldes bei ihnen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Zu jener Zeit bringt man dem Herrn der Heeresscharen Gaben von einem Volke, hochgereckt und blank, von einem Volke, fürchterlich, seitdem es ist, von einem Heidenvolke wundersamen Wohlstands und Behagens, dessen Land durch Flüsse wird durchquert, zum Ort hin für des Herrn der Heeresscharen Namen, bis zum Sionsberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Ein Ausspruch über Ägypten: \"Auf schneller Wolke fährt der Herr daherund kommt nach dem Ägypterland. Vor ihm erbeben die ägyptischen Götter, und der Ägypter Herz verzagt in ihrer Brust. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Ich stachle den Ägypter gegen den Ägypter auf, daß Bruder kämpfe gegen Bruder und Nachbar gegen Nachbar, Stadt gegen Stadt, Reich gegen Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Gespalten wird Ägyptens Ratschluß schon in seiner Brust; denn ich verwirre seinen Plan. Dann mögen sie die Götzen, die Gespenster fragen, die Totengeister, die Wahrsagegeister!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Ich geb Ägypten einem harten Herrn preis, ein strenger König soll\'s beherrschen.\" - Ein Spruch des Herrn, des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Das Wasser schwindet aus dem Meere; der Strom versandet und versiegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Die Flüsse faulen; seicht und sandig werden die Kanäle in Ägypten, und Rohr und Schilf verwelken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Die grünen Triften an dem Nil und an des Niles Mündung und alle Saaten an dem Nil verdorren und zerstieben und verschwinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Die Fischer seufzen; alle trauern, die im Nile angeln, und mutlos werden, die ins Wasser Netze senken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Es schämen sich die Flachsarbeiter des Gehechelten, die Weber des Gewobenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Und seine Wasserträger stehn geschlagen, bekümmert alle seine Bierbrauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Nur Toren sind die Oberen von Tanis; den Pharao beraten seine Weisen dumm. Wie könnt zum Pharao ihr sagen: \"Ich bin ein Glied der Zunft der Weisen, du Sohn uralter Könige\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Wo sind sie? Wo sind deine Weisen? Sie mögen, falls sie\'s wissen, dir\'s kundtun, was zum Untergang Ägyptens beschlossen hat der Heeresscharen Herr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Als Toren stehn die Oberen von Tanis da; einfältig sind die Oberen von Memphis. Ägypten führen ins Verderben, die seiner Gaue Oberste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Der Herr bereitet einen Schwindelgeist darin. So bringen sie Ägypten in allem seinem Tun zum Taumeln, wie der Betrunkene unsichern Schritts in sein Erbrochenes taumelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Zum Heil Ägyptens dient kein Unternehmen. Was sich\'s zum Kopfe macht, das wird zum Schweife, und was zum Palmenzweig, zur Binse. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'An jenem Tage gleichen die Ägypter Weibern. Sie zittern und erbeben vor dem erhobenen Arm des Herrn der Heeresscharen, den wider sie er reckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Und Judas Land wird dem Ägypterland zum Schrecken. Sooft es jemand dran erinnert, erschrickt es über den Beschluß des Herrn der Heeresscharen, den er dawider faßt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Fünf Städte reden im Ägypterland an jenem Tag die Sprache Kanaans, und sie bekennen sich zum Herrn der Heeresscharen. Die \"Gästestadt\" heißt eine unter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'An jenem Tag steht ein Altar des Herrn inmitten von Ägypten, an seiner Grenze für den Herrn ein Denkstein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Das wird zum Zeichen und zum Zeugnis für der Heeresscharen Herrn in dem Ägypterland: Wenn sie zum Herrn vor den Bedrängern schreien, dann schickt er ihnen einen Retter, der für sie streitet und sie rettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Und den Ägyptern wird der Herr sich offenbaren, und die Ägypter lernen an jenem Tag den Herrn erkennen und bringen Schlacht- und Speiseopfer dar; sie lösen ein, was sie dem Herrn gelobt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'So schlägt der Herr Ägypten. Er schlägt und heilt es, sie bekehren sich zum Herrn. Er läßt sich auch erbitten, sie zu heilen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'An jenem Tag ist eine Straße von Ägypten bis Assyrien. Assyrien kommt zu Ägypten, Ägypten zu Assyrien. Und mit Assyrien hält Ägypten Gottesdienste ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'An jenem Tag gesellt sich Israel als drittes Ägypten und Assyrien bei, ein Segensquell auf Erden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Den Segen spricht der Heeresscharen Herr mit diesen Worten: \"Gesegnet sei mein Volk Ägypten, du Schöpfung meiner Hand, Assyrien, und Israel, mein Eigentum!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Im Jahre, da Tartan nach Asdod kam - der König der Assyrer, Sargon, hatte ihn gesandt, und er belagerte Asdod und nahm es ein -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'zu dieser Zeit, sprach so der Herr durch Amos\' Sohn, Isaias: \"Auf! Bind das grobe Tuch von deinen Hüften los. Zieh deine Schuhe von den Füßen!\" - Und er tat so und ging entblößt und barfuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Da sprach der Herr: \"So, wie mein Knecht Isaias bloß und barfuß geht, drei Jahre als ein Zeichen und als Vorbereitung für Ägypter und Äthiopier,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'so führt Assyriens König die gefangenen Ägypter und die verschleppten Äthiopier hinweg, die jungen und die Alten, bloß und barfuß, und das Gesäß entblößt, zur Schmach Ägyptens.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Bestürzt sind sie, von Äthiopien enttäuscht, nach dem sie ausgeblickt, und am Ägypterland, mit dem sie sich gebrüstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Und die Bewohner dieser Küste sagen jenes Tages: \"Wenn\'s denen so erging, nach denen wir Ausschau gehalten, wohin wir uns der Hilfe wegen flüchteten, um vor dem Könige Assyriens uns zu retten, wie können wir uns retten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Ein Ausspruch über die Verheerung der Gebieterin: \"Wie Stürme aus dem Süden brausen, so kommt es aus der Wüste, aus fürchterlichem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ein hart Gesicht wird mir vermeldet: \'Der Räuber raubt, der Tilger tilgt!\'- Herauf, Elam! Dräng nach, du Medien! All dem Gestöhne mache ich ein Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Darüber zittern meine Hüften; mich packen Schmerzen gleich den Wehen einer Kreißenden. Mir wendet\'s das Gehör, und das Gesicht verstört es mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Das Herz pocht mir; ein Beben bebt durch mich. Die Dämmerung, mir sonst so lieb, zum Grauen hat man sie für mich gemacht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Auf! Deckt die Tische! Breitet Teppiche! Nun schmaust und zecht! - Ihr Fürsten, auf! Greift nach den Schilden! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Denn also spricht der Herr zu mir: \'Auf denn! Bestell mir einen Wächter! Er melde, was er sieht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Und sieht er Wagen, die bespannt mit Rossen, auf Eseln Reiter, Reiter auf Kamelen, dann horche er, was er nur horchen kann!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Da rief er aus: \'Ich stehe auf der Wache meines Herrn, tagsüber immerzu; auf Posten bin ich all die Nächte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Da kommt ein Mann auf einem Wagen, bespannt mit Rossen. Da hebt er an und spricht: \"Gestürzt, gestürzt ist Babel. All seine Götterbilder hat man auf die Erde hingeschmettert.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O mein zermalmtes und zerdroschenes Volk! Was ich erhorcht vom Herrn der Heeresscharen, dem Gotte Israels, das kündige ich euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Ein Ausspruch über Duma: \"Von Seïr ruft\'s mir zu: \'Du Wächter, ach! Wie spät ist\'s in der Nacht? Du Wächter, ach! Wie spät ist\'s in der Nacht?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Der Wächter spricht: \'Gekommen ist der Morgen, und doch ist es noch Nacht. Wollt ihr noch mehr erfragen, könnt ihr\'s tun. Dann kommt nur wieder.\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ein Ausspruch über Arabien: \"Im Steppenbusche nächtigt, Karawanen Dedans!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Den Durstigen bringt Wasser zu, Einwohner aus dem Lande Taima, und bietet Brot den Flüchtigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Vor Schwertern sind sie auf der Flucht, vor wohlgeschärften Schwertern, vor wohlgespannten Bogen, vor Kampfeswut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Denn also spricht der Herr zu mir: \'Schon binnen Jahresfrist, gerechnet nach Taglöhnersjahren, ist\'s mit der ganzen Herrlichkeit von Kedar aus.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Der Rest der Bogenzahl der Krieger bei Kedars Söhnen wird gering. Der Herr, Gott Israels, er sagt es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Ein Ausspruch über die Scherbenschlucht: \"Was ist dir doch, daß insgesamt du auf die Dächer steigst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Du lärmerfüllter Ort! Du Stadt, so voll Getöse, du ausgelassene Feste! Die Deinen, die durchbohrt, nicht Schwertdurchbohrte sind\'s, nicht Kampfgefallene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'All deine Führer fliehen miteinander. Sie werden alle ohne Bogenschuß gefangen, die von dir angeworben waren. Gefangen werden allesamt, die aus der Ferne sich hierher geflüchtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Drum sage ich: Laßt mich! Ich muß gar bitter weinen. Dringt nicht in mich mit Tröstungen ob der Gewalt an meines Volkes Tochter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Denn jetzo ist der Tag des Herrn, des Herrn der Heeresscharen, Tag der Bestürzung, der Verheerung und Verwirrung. Da in der Scherbenschlucht durchsticht man Quell und Damm am Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Das sandige Ufer trägt man ab und schleift die Stufenhöhe. Der Mauer mangeln Wehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Mit Kriegerwagen werden deine schönsten Täler voll, und Reiter stellen sich dem Tore gegenüber auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Da wird die Decke Judas weggezogen. - An jenem Tag schaust du im Waldhaus nach dem Rüstzeug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Und ihr bemerket große Risse in der Davidsstadt; da sammelt ihr des untern Teiches Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Ihr zählt die Häuser von Jerusalem und schleift die Häuser zur Befestigung der Mauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Ihr macht ein Sammelbecken in dem Zwischenraum der beiden Mauern für die Wasser aus dem alten Teiche. Doch schaut ihr nicht nach dem, der es geplant, ihr seht nicht den an, der es schon seit langer Zeit beschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Wohl ruft an jenem Tag der Herr, der Heeresscharen Herr, zum Weinen und zum Klagen, zum Haarausraufen und zu Trauerkleidung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Doch da ist eitel Lust und Lachen und Rinderwürgen, Schafeschlachten und Fleischverzehren, Weinvertilgen. \'Gegessen und getrunken! Denn morgen sind wir tot!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Der Herr der Heeresscharen hat es mir ins Ohr geoffenbart: \'Solch eine Missetat wird nimmer euch verziehen, bis daß ihr sterbet\', spricht der Herr, der Heeresscharen Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So spricht der Herr, der Heeresscharen Herr: \"Auf! Hin zu diesem Pfleger, des Hauses Vorstand, Sebna!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Was hast du hier? Und wen? Daß du ein Grab hier auszuhaun bestimmst? Du, der auf einer Höhe sich ein Grab aushaut, in Felsen eine Grabkammer sich meißelt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Hinschleudert, Mannsbild, dich der Herr der Länge nach. Zusammen rollt er dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Er wickelt dich zu einem Wickel und wirft wie einen Ball dich in die weite Welt. Dort sollst du sterben, und dorthin sollen kommen deine wunderschönen Wagen, du Schandfleck in dem Hause deines Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Ich stürze dich von deinem, Amte und jage dich von deinem Posten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Ich ruf an jenem Tage meinen Diener - den Eljakim, Hilkias\' Sohn -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'ihm lege ich dein Amtskleid an, umbinde ihn mit deiner Schärpe und übergeb ihm deine Vollmacht. Er sei Jerusalems Bewohnern Vater und dem Judahause!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Ihm übergebe ich des Davidshauses Schlüssel. Er öffnet, niemand schließt. Er schließt, und niemand öffnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Als Nagel schlage ich an einen festen Ort ihn ein, zum Ehrensitze wird er seinem Vaterhause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Was alles seines Vaters Haus zur Zierde dient, das wird man an ihn hängen, die Helme und die Schilde, auch alles kleine Hausgerät von Bechern bis zu Krügen aller Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'An jenem Tag\", ein Spruch des Herrn der Heeresscharen, \"wird der bisher am festen Orte eingeschlagene Nagel weichen. Er wird herabgeschlagen und fällt nieder; was er getragen, ist dahin.\" - Der Herr hat\'s ja gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Ein Ausspruch über Tyrus: \"Die Tarsisschiffe jammern: \'Vernichtet ist der Landungsplatz der Siedlungen.\' Aus dem Kittiterlande wird es ihnen kundgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Verstummt sind die Bewohner ihrer Küste, die Kaufleute aus Sidon. Dich füllten an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'die auf den mächtigen Gewässern fuhren, dich, die des Sichors Saat einführte, des Niles Ernte, und die der Stapelplatz der Heidenvölker war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Erröte, Sidon! Das Meer sagt ja: \'Du liegst nicht mehr in Wehen, Meeresfeste, gebierst nicht mehr; du ziehst nicht Jünglinge mehr groß; bringst keine Jungfrauen mehr auf.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Wie bei der Kunde von Ägypten, so bebt man bei der Kunde über Tyrus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Nach Tarsis ziehet hin! Küstenbewohner, heult!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ist dies denn eure sonst so frohe Stadt mit ihrem Ursprung in der Vorzeit Tagen? Die Füße trugen weithin sie zu Siedlungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Wer nur verhängte dieses Schicksal über Tyrus, das gekrönte, wo Handelsleute Fürsten, Kaufleute die Geehrtesten im Lande waren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Der Heeresscharen Herr hat es beschlossen, den ganzen hohen Glanz zu dunkeln und die Geehrtesten im Land herabzuwürdigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Setz unter Wasser gleich dem Nil dein Land! Du Tarsistochter; keine Mutterstadt gibt\'s mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Er streckt den Arm aus übers Meer, erschüttert Königreiche. Der Herr gibt wider Kanaan Befehl, zu tilgen seine Festen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Er spricht: \'Du sollst nicht mehr frohlocken, geschändete Jungfrau, du Sidonstochter! Auf! Auf, hinüber nach Kittim! Auch dort wird dir nicht Ruhe!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Sieh! Des Chaldäerlandes Volk, das nicht assyrisch ist, gibt jenes wilden Katzen preis, errichtet Türme, stürmt seine Schlösser und wandelt sie in Trümmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Ihr Tarsisschiffe! Heult! Denn eure Feste ist zerstört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'An jenem Tag kommt Tyrus in Vergessenheit wohl an die siebzig Jahre, gerechnet wie bei einem König. Nach siebzig Jahren geht es Tyrus wieder, wie\'s in dem Liede von der Dirne heißt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '\'Die Zither nimm! Die Stadt durchstreife, du vergeß\'ne Dirne! Spiel rührend! Singe Lied auf Lied, damit man wieder dein gedenke!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Nach siebzig Jahren wird der Herr ja Tyrus abermals heimsuchen, damit zu seinem Buhlerlohn es kehre; mit allen Königreichen auf der Erde buhlt es wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Doch sein Gewinn, sein Dirnenlohn, wird eine heilige Gabe für den Herrn, nicht aufgespart und nicht gehortet. Denn jenen, die da siedeln vor dem Herrn, wird sein Gewinn zur Ehrengabe, zur Sättigung und zur Gewandung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Der Herr reißt auf die Erde, bricht sie um und macht das Oberste auf ihr zum Untersten, zerstreut, die sie bewohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Dem Priester geht es wie dem Volk, dem Herrn wie seinem Knechte, der Frau wie ihrer Magd, und dem Verkäufer wie dem Käufer, dem Borger wie dem Ausleiher, dem Schuldner wie dem Gläubiger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Geleert, geplündert wird die Erde. Der Herr hat dies ihr angedroht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Hintrauernd stirbt die Erde ab; hinwelkend stirbt die Welt. Hinwelken wird in hohem Maß der Erde Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Entartet ist die Erde deretwegen, die sie bewohnen: Sie übertreten die Gesetze und überschreiten die Verordnungen. Sie brechen einen ewigen Bund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Drum frißt ein Fluch die Erde, wer sie bewohnt, der muß es büßen. Drum nehmen ab die Erdensiedler; von Sterblichen bleibt nur ein winziger Rest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Hintrauert auch der Wein, der neue; die Rebe welkt. Wer frohen Muts gewesen, seufzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Der der Pauken froher Schall verhallt; der Lärm der Jubelnden hört auf, der Zitherklang verhallt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Man trinkt nicht Wein mehr bei Gesang; den Zechern schmeckt das Bier gar bitter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'In Trümmern liegt die Neue Stadt, ein jedes Haus wird für den Zugang abgesperrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Und um den Wein Gejammer auf den Straßen! Versiegt ist jeder Freudenquell und aller Frohsinn aus dem Land gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Nur öde Plätze sind der Stadt verblieben; in Stücke wird das Tor geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'So geht es nämlich auf der Erde bei den Völkern wie beim Olivenschlagen, wie nach der Ernte bei der Nachlese.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Die einen jubeln laut, und ob des Herren Größe jauchzen sie im Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Sie singen in den Binnenländern darob dem Herrn, das Lob des Herrn, des Gottes Israels, auf Meeresinseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Vom Saum der Erde her vernehmen wir Gesang: \"Der Frommen Teil ist Herrlichkeit.\" Die andere aber sprechen: \"Unsagbar ist\'s für mich, unsagbar. Wehe mir! Die Räuber rauben; die Räuber rauben Raub.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Du Erdensiedler! Dich überkommen Grauen, Grube, Garn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Wer flieht vor greulichem Geschrei, der fällt in eine Grube, und wer nicht in die Grube fällt, verfängt sich in dem Garn. Der Höhe Gitter öffnen sich; der Erde Gründe schüttern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Die Welt zerbricht, zerkracht; die Welt zerspringt, zerreißt; die Erde wankt und schwankt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Die Erde wankt wie ein Betrunkener; sie schwankt wie eine Hängematte. Ihr Frevel wuchtet schwer auf ihr; sie stürzt und steht nicht wieder auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'An jenem Tage straft der Herr das Heer der Feste in der Feste wie schon die Könige des Binnenlandes in dem Binnenland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'In Haufen wirft man sie gebunden ins Verließ und schließt sie in den Kerker ein und zieht sie für die lange Frist zur Rechenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Der Mond verbleicht; die Sonne staunt, weil wiederum der Heeresscharen Herr die Königsherrschaft antritt auf dem Sionsberg und zu Jerusalem mit einem Himmelsglanz vor seinen Ältesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Dich muß ich loben, Herr, mein Gott, lobpreisen Deinen Namen, wenn Unvergleichliches Du wirkst und ferne Pläne wahr werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Die Stadt mögst Du in Schutt verwandeln, die Burg in Trümmer! Der Fremden Feste keine Stadt mehr, sie soll nicht mehr aufgerichtet werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Ein starkes Volk wird Dich deswegen ehren, das Reich der mächtigen Heiden wird Dich fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Für den Geringen sei Du eine Burg und für den Armen eine Burg zur Zeit der Not, ein Zufluchtsort im Ungewitter, ein Schatten bei der Hitze! Der Wüteriche Toben sei wie schneller Wirbelsturm');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'und Hitze bei der Dürre! Der Fremden Wüten dämpfe Du! Wie Hitze durch die Wolkenschatten, so dämpfe man der Wüteriche Jubel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Der Heeresscharen Herr bereite für die Völker all auf diesem Berg ein fettes Mahl, ein Mahl bei starkem Wein, ein fettes Mahl von Mark, ein Mahl bei altem, abgeklärtem Wein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Und er zerreißt auf diesem Berg den Schleier vorne, der die Völker all verhüllt, die Hülle, ausgebreitet über alle Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Den Tod vernichtet er für immer. Der Herr wischt Tränen ab von jedem Angesicht und macht der schimpflichen Behandlung seines Volks ein Ende überall auf Erden. Der Herr hat\'s ja versprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'An jenem Tage wird man sprechen: \"Seht! Da ist unser Gott. Von ihm erhofften wir, daß er uns rette. Das ist der Herr, auf den wir hoffen. So laßt uns jubeln und frohlocken über seine Hilfe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Die Hand des Herrn ruht ja auf diesem Berge. - Doch Moab wird an seinem Ort hinabgepreßt gleich einem Strohbund, eingestampft in Jauche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Und breitet es darinnen seine Hände aus gleich einem Schwimmer wie beim Schwimmen, dann drückt man seinen Körper nieder trotz der Bewegung seiner Arme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Ja, deine festen, hohen Mauern reißt man ein und wirft sie nieder und stürzt sie in den Staub der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'An jenem Tage singt man dieses Lied im Judalande. \"Wir haben eine feste Stadt, und Hilfe schaffen Mauern und das Bollwerk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Macht auf die Tore! Ein frommes, treuergebenes Volk zieht ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Die festgebaute Stadt machst Du zum Frieden, zum Frieden, weil sie sich auf Dich verläßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Verlaßt euch immer auf den Herrn, ja, auf den Herrn! Der Herr ein Fels der Ewigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Zu Boden hat er die Hochthronenden geworfen, hinabgestürzt die hochgelegene Stadt, darnieder bis zur Erde und sie in den Staub gestoßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Dann sollen Füße drüber wandeln, die Füße Armer und geringer Leute Tritt! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Den Frommen wird ein ebener Pfad zuteil; den Weg des Frommen ebnest Du, Gerechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Wir hoffen, Herr; auf Dich vertraun wir, Herr, daß Du vollziehest Deine Strafen; nach Deinem Ruhme, Deinem Preis verlangt die Seele. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Nach Dir verlangt es mich des Nachts. Nach Dir sehnt sich mein Geist in mir; wenn Deine Strafen träfen, dann lernten auch die Weltbewohner das, was recht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Wird so ein Bösewicht begnadigt, dann lernt er nie das Rechte. Im Land, wo Recht und Tugend herrschen, verübt er nur Verkehrtes, und nicht beachtet er des Herren Herrscherhoheit. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herr! Hocherhoben ist Dein Arm; sie schauen nicht darauf. So sollen sie voll Scham nur schauen den Eifer für das Volk, wenn Feuer Deine Feinde fressen wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Du wirst uns Heil verschaffen, Herr. Denn alles, was uns traf, hast Du an uns getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herr, unser Gott! Uns meistern andere Herrn als Du; doch rühmen möchten wir nur Dich allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Sie sollen sterben, ohne wieder aufzuleben; sie seien Gespenster, ohne wieder aufzustehen! Drum strafe sie, vertilge sie, und ihr Gedächtnis lösche aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Herr! Nimm ein Heidenvolk, ein Heidenvolk ums andre vor, erwirb Dir Ruhm bis weithin zu der Erde Grenzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Da sollen sie Dich suchen, Herr, in ihrer Not, ergießen sich in der Beschwörung Deiner Züchtigung, die ihnen werden soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Wie eine Mutter, der Entbindung nahe, sich windet und in ihren Wehen schreit, so sind wir, Herr, vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Wir gehen schwanger, haben Wehen; wenn wir gebären, ist\'s nur Wind. Der Erde können wir kein Glück verschaffen, und Weltbewohner kommen nicht ans Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Doch Deine Toten mögen leben und meine Leichen auferstehen! Erwachet! Jubelt! Staubbewohner! Dein Tau ist ein heilsamer Tau, wenn Du ihn auf das Land der Schatten fallen lässest.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Wohlan, mein Volk, geh nun in deine Kammern! Verschließe hinter dir die Tür! Verbirg dich eine kleine Weile, bis daß der Zorn vorübergeht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Denn seht! Der Herr bricht schon von seinem Orte auf, die Missetat der Erdbewohner zu bestrafen. Die Erde deckt Blutströme auf, bedeckt nicht länger die auf ihr Erwürgten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'An jenem Tage straft der Herr mit seinem scharfen, großen, starken Schwert den Leviatan, diese flüchtige Schlange, den Leviatan, eine krumme Schlange, und tötet in dem Meer den Drachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'An jenem Tage singt von ihm: \"Du Weinberg, gar so lieblich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '\'Ich selbst, der Herr, behüte ihn und tränke ihn das eine um das andere Mal. Daß niemand ihn zertrete, behüte ich ihn nachts und tags.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Um mich ist keine Mauer. Ach, hätte ich in diesem Kriege Pfahl und Wall, wo es doch heißt: \'Ich will es brennen, wegbrennen will ich alles\'!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Oder wäre er mein starker Schutz; er sorgte für mein Wohl; mein Wohl besorgte er!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'In Bälde schlüge Jakob Wurzel und triebe Knospen und sproßte Israel, die Weit mit Früchten füllend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Wird er es also schlagen, wie er die schlägt, die es geschlagen, und würgen, wie er dessen Würger würgt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Wenn Du\'s vertreibst und fortschickst, im Streit mit ihm, dann wird es seufzen über seinen unbeugsamen Geist, wie man\'s am Tag des Ostwinds tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Nur dadurch könnte Jakobs Sünde Sühne finden, und daraus könnte seiner Sündenschulden Tilgung folgen, wenn es die Steine aller der Altäre zerschlagnem Kalkgesteine gleich machte und wenn die Pfähle und die Rauchaltäre nicht mehr stünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Jedoch die feste Stadt wird ganz verödet sein, ein Platz, verödet und verlassen wie die Wüste. Dort weiden Rinder; dort lagern sie und fressen ihre Zweige ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Die dürrgewordenen Zweige werden abgebrochen; dann kommen Weiber und verfeuern sie. Ein Volk ganz ohne Einsicht ist\'s; sein Stifter konnte kein Erbarmen mit ihm haben, sein Bildner ihm nicht gnädig sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'An jenem Tage drischt der Herr bis zu Ägyptens Bache von des Stromes Wellen. Ihr werdet alsdann einzeln aufgelesen, Söhne Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Gestoßen wird an jenem Tage in ein mächtig Horn. Da kommen alle die herbei, die im Assyrerland sich einst verloren und die verstoßen waren nach Ägypterland, und beten auf dem heiligen Berge in Jerusalem zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ein Wehe jener stolzen Krone der Trunkenbolde Ephraims, dem wohlbesprengten Blumenkranz und seinem wunderschönen Schmuck, der auf dem Haupt des früchtereichen Tales liegt, der auf dem Haupte der vom Weine Trunkenen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Einen Mächtigen und Starken hält der Herr gleich Hagel und Verderbens Sturm bereit. Gleichwie ein Schwall gewaltiger Wassergüsse, so wirft er rücklings sie zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Mit Füßen wird getreten die stolze Krone dieser Trunkenbolde Ephraims.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Dem wohlbesprengten Blumenkranz und seinem wunderschönen Schmuck, der auf dem Haupt des früchtereichen Tales ist, ergeht es wie der frühen Feige vor dem Sommer. Wer sie erblickt, der pflückt sie ab und hat sie schon verschlungen. Kaum hat er sie in seiner Hand, verschlingt er sie. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'An jenem Tage ist der Heeresscharen Herr selbst eine schmucke Krone, ein wundervolles Diadem dem Reste seines Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Und mit dem Geiste der Gerechtigkeit beseelt er den, der auf dem Richterstuhle sitzt, mit Tapferkeit die Männer, die den Kampf zum Tor zurückdrängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Doch diese wanken auch vom Wein und taumeln von dem Biere. Vom Biere wanken Priester und Propheten; vom Weine werden sie verwirrt. Sie taumeln von dem Biere; beim Schauen wanken sie; schwanken beim Schlichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Die Tische alle voller Unrat, voll Unflat bis zum letzten Platze!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Wen kann man da Erkenntnis lehren und wem die Offenbarung deuten? Allein noch den der Milch Entwöhnten, nur den der Brust Entwachsenen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, '\"Saw lasaw, saw lasaw, kaw lakaw, kaw lakaw\", das heißt: \"Nichts als Befehlen und nichts als Warten!\" - Kurzformen hier und dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Jawohl! In solch unschöner Rede, in einer fremden Sprache wird er zu diesem Volke reden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'er, der zu ihm gesprochen hat: \"Kriegsruhe ist nur dies: Den Müden gönnet Ruhe! Nur dann gibt\'s Friedenszeit.\" Sie aber wollen nimmer hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'An sie ergeht deshalb des Herren Wort: \"Saw lasaw; saw lasaw, kaw lakaw, kaw lakaw\", \"Schon angeordnet! Nur warten, warten!\" - Kurzformen hier und dort, - daß sie auf ihrem Wege strauchelnd rücklings fallen und sich zerschmettern und, verstrickt, gefangen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Des Spottes Männer, hört daher das Wort des Herrn, Gebieter dieses Volks, die zu Jerusalem ihr weilt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Zwar saget ihr: \"Wir schließen mit dem Tode einen Bund und machen mit der Unterwelt Verträge. Wenn des Verderbens Flut hier einbricht, uns erreicht sie nicht. Denn Lügen machen wir zu unsrer Burg, verstecken uns in Trug.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Dagegen spricht der Herr: \"Schon gründe ich in Sion einen Stein, solch einen Stein, gar wohl erprobt, solch einen Eckstein, köstlich für die Gründung, ein fester Grund, der sich nicht ändert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Und ich bestimme Recht zur Meßschnur, Gerechtigkeit zur Waage. Die Lügenburg schlägt Hagel nieder, und Wasser überschwemmt den Unterschlupf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Und euer Bündnis mit dem Tod wird aufgehoben, und eure Übereinkunft mit der Unterwelt, sie gilt nicht mehr. Wenn des Verderbens Flut herflutet, werdet ihr davon vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Wenn sie herströmt, schwemmt sie euch fort, sei\'s morgens, dann am Morgen. Wenn sie bei Tag, bei Nacht herflutet, nur mit Schauder hört man diese Kunde. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Zu kurz ist dann das Bett, euch darin auszustrecken, zu schmal die Decke, euch dareinzuwickeln. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Wie einst am Berge Perasim, wird sich der Herr erheben. Wie in der Ebene von Gibeon, so wird er donnern, um seine Tat zu tun, sein so befremdlich Werk, um so sein Werk zu wirken, sein seltsam Unterfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Deswegen spöttelt nicht darüber. Sonst werden eure Fesseln sich verstärken. Verheerung, wenn auch kurze, vernahm ich von dem Herrn, der Heeresscharen Herrn, für dieses ganze Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Horcht auf! Auf meine Stimme hört! Merkt auf! Hört meine Rede!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Pflügt einer denn beim Saatgeschäft den ganzen Tag? Umbricht er nur und eggt sein Ackerland?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Nicht wahr? Hat er die Fläche eingeebnet, dann streut er Dill, sät Kümmel aus, bestimmt dem Weizen und dem Dinkel, der Gerste und der Hirse sowie dem Emmer jedem seine Felder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'So unterweist Er ihn im Rechten, sein Gott belehrt ihn so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Denn Dill wird nicht mit Schlitten ausgerieben; auf Kümmel dreht sich nicht das Wagenrad. Der Dill wird mit dem Stecken ausgeklopft, der Kümmel mit dem Stocke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Brotkorn wird ausgetreten; doch immerfort drischt man nicht bloß drauf los. Nicht immer drehen sich darauf die Wagenräder; nicht immer treten\'s seine Rosse aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Auch dieses geht vom Herrn der Heeresscharen aus. In Plänen ist er wunderbar und groß in ihrer Ausführung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ach Ariel! O Ariel! Du Stadt, die David einst belagert! Ein Jahr nur laßt vorüber, den Festeskreis zu Ende sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Dann will ich Ariel bedrängen, daß Klage, Weheklage werde: \"Mir geht\'s wie Ariel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Ich lagere wider dich wie David und schließe dich mit einem Walle ein und baue Schanzen gegen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Dann sprichst du demütig vom Boden her und lässest aus dem Staub die Rede tief gedämpft ertönen. Wie eines Erdgeists Stimme wird die deine, und aus dem Staube flüsterst du die Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Doch wird dem dünnen Staube gleich die Menge deiner Feinde, wie Spreu, die hinfährt, wird der Wüteriche Schar. Und plötzlich wird\'s, urplötzlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Gezüchtigt wird sie von dem Herrn der Heeresscharen bei Donnern, Dröhnen, lautem Schall, bei Sturmgebraus und Wirbelwind und bei gefräßiger Feuerlohe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'So wird zum Traum, zum nächtlichen Gesicht die Menge aller Heidenvölker, die Ariel bekämpfen, und alle ihre Posten, ihre Schanzen, ihre Stürmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'So wird\'s, wie wenn dem Hungrigen es träumt, er esse, und wacht er auf, ist seine Gier noch ungestillt. Wie wenn der Durstige träumt, er trinke, und wacht er auf, dann ist er matt, und seine Gier noch lechzend. So geht\'s dem Schwarme aller Heidenvölker, die gegen Sions Berg sich scharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Nur still und starr! Erblindet und verblendet euch! Seid trunken, aber nicht vom Wein, und taumelt, aber nicht vom Biere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Es gieße über euch der Herr den Geist der Schlafsucht aus und drücke eure Augen, die Propheten, zu und hülle eure Häupter ein, die Seher!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Doch das Gesicht von alledem sei euch gleich einem Buch mit sieben Siegeln. Gib\'s einem Mann, der lesen kann, und sag dabei: \"Da, lies dies doch!\", dann sagt er drauf: \"Das kann ich nicht; es ist versiegelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Doch gibst du einem, der nicht lesen kann, das Buch, und sagst dabei: \"Lies dies!\", dann sagt er drauf: \"Ich kann ja überhaupt nicht lesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'So spricht der Herr: \"Im Munde nur führt mich dies Volk; nur mit den Lippen ehrt es mich; doch fern hält es von mir sein Herz, und die Verehrung, die sie mir erweisen, besteht in angelernten Menschenformeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Drum handle ich an diesem Volke noch einmal rätselvoll und wundersam. Die Weisheit seiner Weisen soll dran scheitern, die Klugheit seiner Klugen sich verbergen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ein Wehe denen, die so tief die Pläne vor dem Herrn verbergen wollen und die ihr Werk im Finstern treiben, sprechend: \"Wer beachtet uns? Wer merkt auf uns?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Verderben komme über euch. Ist denn dem Lehm der Töpfer gleich zu achten? Darf eine Arbeit sagen über den, der sie getan: \"Der hat mich nicht getan?\" Und ein Gebilde von dem Bildner: \"Der hat mich nicht ersonnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Ist\'s nicht noch eine kurze, kleine Weile? Dann wird der Libanon zu einem Garten, und für Gestrüpp gehalten wird der Garten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'An jenem Tag verstehen selbst die Tauben die vorgelesenen Worte. Der Blinden Augen können sehen, von Dunkelheit und Finsternis befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Die Dulder aber freuen sich des Herrn aufs neue; der Menschen Ärmste jubeln ob des Heiligen Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'wenn fort die Wüteriche sind und wenn es aus ist mit den Spöttern und wenn getilgt wird, wer auf Bosheit lauert, und ausgerottet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'wer mit Worten schlecht die Leute macht, dem Richter im Gerichtstor Schlingen legt, Unschuldige durch falsche Gründe ins Unrecht setzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Drum spricht der Herr zu Jakobs Haus, er, der den Abraham befreit: \"Fortan wird Jakob nimmermehr sich schämen, sein Antlitz nimmermehr erblassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Wenn es in seiner Mitte die Kinder, meiner Hände Werk, erblickt, so heiligen sie meinen Namen. - Sie heiligen Jakobs Heiligen, erschauern vor dem Gotte Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Zur Einsicht kommen Geistesirre, und Murrende erlernen Einsicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '\"Ein Wehe über diese widerspenstigen Söhne\", ein Spruch des Herrn, \"die Pläne machen ohne mich, die Bünde schließen ohne meinen Willen, um Missetat auf Missetat zu häufen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Die nach Ägypten reisen, doch meinen Mund darüber nicht befragen. Sie fliehen in den Schutz des Pharao und suchen Zuflucht in Ägyptens Schatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Der Schutz des Pharao wird euch Enttäuschung, die Zuflucht in Ägyptens Schatten Schmach bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Sind seine Fürsten auch in Tanis, und kommen schon bis Chanes seine Boten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'enttäuscht wird alles durch ein Volk, das ihnen nicht zu Nutzen ist. - Sie dienen ihnen nicht zu Nutz und Frommen, nein, zur Schmach nur und zur Schande.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Ein Ausspruch über des Südens Tiere: \"Im Land voller Angst und Not, wo Löwen und wo Löwinnen auf Raub ausgehn, wo Ottern und wo Drachen fliegen, da laden sie auf Eselsrücken ihre Güter und ihre Schätze auf den Höcker der Kamele und bringen sie zu einem Volke, das nichts nützt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Ägypten ist ein Nichts und nichtig seine Hilfe. Drum künde ich von ihm: \'Die Leute sind nur Stillesitzer.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Nun geh und schreib\'s auf eine Tafel dort bei ihnen, und zeichne in ein Buch es ein! So diene es fortan für künftige Zeit als Zeuge!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Ein widerspenstig Volk ist\'s ja, verlogene Söhne, Söhne, die des Herrn Gesetz nicht halten wollen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'die zu den Sehern sprechen: \"Nein! Ihr sollt nicht sehen!\", und zu den Zukunftsschauern: \"Tut uns die nackte Wahrheit ja nicht kund! Uns sagt nur Dinge, die gefallen! Verkündet uns Gesichte, die uns schmeicheln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Weicht ab vom Weg! Biegt ab vom Pfade! Und laßt uns mit dem Heiligen Israels in Ruhe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Deshalb spricht so der Heilige Israels: \"Ihr habt dies Wort verworfen, auf Falsches und auf Sündiges vertraut und euch darauf verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'So werde dieser Frevel euch ein Riß, zum Einsturz führend, ein Bruch an hoher Mauer, die plötzlich unversehens niederstürzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'die man zerbricht, wie man ein irdenes Gefäß zerbricht, zertrümmert ohne jegliches Bedauern, und unter dessen Stücken keine Scherbe bleibt, um Feuer aus dem Herd zu holen und Wasser aus dem Born zu schöpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Denn also spricht der Herr, der Herr, der Heilige Israels: \'In Umkehr und Gelassenheit liegt euer Heil. In Stillesein und in Vertraun ruht eure Stärke.\' Das aber wollt ihr nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Ihr sagt vielmehr: \'Ach nein! Auf Rossen wollen wir fliegen!\' Darum sollt ihr fliehen! \'Auf Rennern wollen wir reiten!\' Darum werden eure Hetzer rennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Vor eines einzigen Drohung beben Tausend, und vor der Drohung von nur fünfen sollt ihr rennen, bis daß von euch nur übrigbleibt, was einer Stange auf dem Bergesgipfel gleicht und einem Banner auf dem Hügel.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Und doch verlangt\'s den Herrn nach euerer Begnadigung; er wünscht, sich euer zu erbarmen. Ein rechter Gott ist ja der Herr. Heil dem, der ihn ersehnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Du, Sionsvolk, das in Jerusalem verweilt! Du sollst nicht länger weinen. Um deines Schreiens willen wird er dich begnadigen; wenn er\'s, vernimmt, erhört er dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Wenn euch der Herr auch kärglich Brot und Wasser gibt, so wird dir doch der Lehrer nicht entzogen: denn abermals mit eignen Augen schaust du deinen Lehrer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Und deine Ohren hören hinter dir den Ruf: \"Hier! Diesen Weg da geht!\", wenn ihr nach rechts wollt oder links.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Dann nennt ihr unrein eure Götzen, die mit Silber sind beschlagen, und eure goldbezogenen, gegossenen Bilder. Du wirfst sie fort wie Ekelhaftes. \"Nur fort damit!\", sprichst du davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Dafür benetzt er deine Saat mit Regen, wenn du sie auf die Felder säst, und das Getreide, das der Acker trägt, wird voller Saft und Kraft. An jenem Tage wird dein Vieh auf weitem Anger weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Des Feldbaus Helfer, Ochs und Esel, fressen dann gesalz\'nes Futter, mit Schaufeln und mit Gabeln gut geworfelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Von allen hohen Bergen, von allen hocherhabenen Hügeln strömen Bäche; Wasserläufe rinnen. - Am großen Würgetag, wenn Türme stürzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'dann gleicht dem Sonnenlichte das des Mondes; das Sonnenlicht wird aber siebenfach und gleicht dem Licht von sieben Tagen, wenn der Herr die Wunde seines Volkes dann verbindet und die von ihm geschlagenen Striemen heilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Seht! Fernher kommt des Herren Name. Aufloht sein Zorn, gewaltig seine Rauchwolke; vom Grolle schäumen seine Lippen, ein fressend Feuer seine Lippen, ein fressend Feuer seine Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Sein Hauch ein ausgetretner Strom, der bis zum Halse reicht, wenn er die Heiden sichtet mit der Schwinge des Verderbens, und wie ein Zaum an Kinnladen die Völker mit Gewalt fortreißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Dann singet ihr, wie in der Nachtzeit, wenn das Fest beginnt, vor Fröhlichkeit im Herzen wie bei dem, der unter Flötenklang hinwallt, um auf den Berg des Herrn zu ziehn zum Felsen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Der Herr läßt seiner Stimme lauten Schall ertönen und seines Armes Wucht mit fürchterlichem Zorne schauen, und mit gefräßiger Feuerlohe, bei Sturm, Gewitter, Hagelschlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Denn Assur soll erschrecken vor des Herren Donner, wenn er es mit dem Stocke schlägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Das Feldgepäck wird dann zur Ruhebank, darauf der Herr sich niederläßt mit Pauken und mit Zithern und mit den Siegespreisen, die er sich erstritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Schon längst ist eine Feuerstätte hergerichtet; so tief und breit gemacht, gilt sie dem König. Des Feuers mächtigen Scheiterhaufen setzt in Brand des Herren Odem gleich einem Schwefelstrome.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ein Wehe denen, die der Hilfe halber nach Ägypten ziehen, die sich auf Rosse stürzen und auf mächtig viele Reiter, doch auf den Heiligen Israels nicht blicken, den Herrn nicht fragen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Und doch ist er ein Weiser, und bringt er Unglück, nimmt er seine Drohung nicht zurück. Und sie erfüllt sich an der Frevler Haus und an der Übeltäter Spießgesellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Ägypter sind ja auch nur Menschen, nicht Gott, und ihre Rosse Fleisch, nicht Geist. Wenn seine Hand der Herr ausstreckt, dann fällt der Helfer, und der Unterstützte stürzt. Sie alle kommen miteinander um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Dagegen spricht zu mir der Herr: \"So ist\'s, wie wenn ein Löwe knurrt, ein Jungleu über seiner Beute. Man bietet gegen ihn der Hirten Vollzahl auf. Doch er erschrickt vor ihrem Schreien nicht; ihr Lärmen läßt ihn unberührt. So kommt der Herr der Heeresscharen herab zum Kampfe um den Sionsberg und seine Höhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Wie Schwingen die Gefiederten, so hüllt der Herr der Heeresscharen Jerusalem, beschirmt und rettet, schont, befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'So kehrt zu dem zurück, von dem ihr gänzlich abgefallen, ihr Söhne Israels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'An jenem Tag wirft jeder seine silbernen und goldenen Götzen von sich, die eure Hände euch zur Sünde angefertigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'wenn Assur fällt durch eines Nichtmanns Schwert, gefressen wird durchs Schwert von einem Nichtmenschen. Dann flieht es vor dem Schwerte, und seine besten Krieger werden Sklaven.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Vorüber eilt\'s an seiner Felsenburg aus Furcht und seine Führer an dem Banner, voller Angst.\" Ein Spruch des Herrn, der auf dem Sion seinen Feuerherd besitzt und seinen Feuerofen zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Regiert gerecht ein König, dann walten die Beamten auch dem Recht entsprechend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Ein jeder ist ein Schutz vor Sturm und ein Versteck vor Regen, wie Wasserbäche in dem heißen Lande, wie eines wuchtigen Felsens Schatten in ausgedorrtem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Wer sehen soll, drückt nimmer seine Augen zu. Wer hören soll, horcht nunmehr auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Bedächtig wird das Herz der Vorlauten. Der Stotterer Zunge redet hurtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Der Schurke heißt nicht mehr ein edler Mann, der Schleicher nimmermehr ein Ehrlicher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Der Schurke redet Schurkereien, sein Herz sinnt nur auf Böses, er tut Vermessenes und redet irrig von dem Herrn, daß \"er den Hungrigen nur darben lasse, dem Durstigen den Trunk entziehe\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Des Schleichers Waffen sind gar böse, er schmiedet schlimme Pläne, um Elende durch trügerische Reden zu verderben, selbst wenn der Arme auch sein Recht beweist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Der Edle aber sinnt auf Edles, beharrt bei edlen Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Steht auf, ihr sorgenfreien Weiber! Auf meine Stimme hört! Sorglose Töchter, hört auf meine Rede!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Leichtsinnige! Ihr werdet über Jahr und Tag erbeben; denn dann ist\'s mit der Weinlese zu Ende und kommt kein Ernten mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Leichtsinnige, erbebt! Erzittert, Sorglose! Streift das Gewand ab! Entkleidet euch! Um eure Hüften Trauergürte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Die Brust zerschlage der schönen Felder halber, der früchtereichen Reben wegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'der Scholle meines Volkes wegen, wo Dorn und Distel wachsen, ob all der lustigen Häuser in der frohgemuten Stadt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Das Schloß verlassen! Der Stadtlärm weg! Der Hügel und die Warte kahle Höhn für immer, der Wildesel Ergötzen, der Herden Weideplatz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Bis aus der Höhe über uns ein Geist wird ausgegossen. Dann wird zum Fruchtgefilde die Wüste, und Fruchtgefilde gilt als Wald.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Und in der Wüste wohnt das Recht, und in dem Fruchtgefilde siedelt die Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Die Wirkung der Gerechtigkeit ist Friede, und der Gerechtigkeit Ertrag ist ewige Sicherheit und Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'In einer Friedensaue wohnt alsdann mein Volk, in sichern Wohnungen, an stillen Ruheplätzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Und stürzen Wälder nieder, werden Städte Ebenen gleich gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Heil euch, die ihr an allen Wassern säen dürft, freilaufen lassen könnet Rind und Esel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Dir, Räuber, wehe! Noch nie beraubt! Dir, Plünderer, weh! Noch nie geplündert! Hast du genug geraubt, wirst du beraubt. Hast du genug geplündert, dann wirst du geplündert. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herr! Sei uns gnädig! Auf Dich, Herr, harren wir. Sei unser Arm allmorgendlich, ja, unsere Hilfe in der Zeit der Not!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Die Völker mögen fliehen vor der Donnerstimme, vor Deiner Hoheit selbst die Heiden auseinanderstieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Dann sei das Beutemachen wie das Tun der Heuschrecken, so falle man darüber her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Erhaben ist der Herr; er wohnt ja in der Höhe; er füllt mit Recht und mit Gerechtigkeit in reichem Maße Sion. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'In deinen Unglückszeiten Sicherheit, und deines Glückes reichster Quell sei Weisheit und Erkenntnis! - Die Furcht des Herrn ein reicher Schatz!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Jetzt aber schreien Führer draußen, und Friedensboten weinen bitterlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Die Straßen sind verödet, die Wanderer verschwunden; man bricht den Bund und gibt auf die Gemeinde nichts und achtet nicht der Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'In Trauer steht das hingewelkte Land, der Libanon steht fahl und welk, und Saron gleicht der Wüste; Basan und Karmel sind entlaubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, '\"Jetzt will ich aufstehn\", spricht der Herr, \"jetzt mich erheben, mich ermannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Ihr geht mit dürrem Grase schwanger; gebären sollt ihr dürre Halme. Ein Hauch, ein Feuerhauch soll euch verzehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Dann werden Völker wie zu Kalk verbrannt, wie abgehackte Dornen in des Feuers Brand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Ihr fernen Völker, höret, was ich tue! Erkennt, ihr nahen, meine Heldenkraft!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'In Sion werden sich die Sünder ängstigen, und Beben wird die Frevler packen. \"Wer kann von uns verweilen hier bei diesem Feuer, das so frißt? Wer weilt von uns bei ewigem Brande?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Wer redlich wandelt und Gerades spricht und wer Gewinn von Ausbeutung verschmäht und wer die Hände schüttelt, um Bestechung abzulehnen, und wer sein Ohr verstopft, damit er nicht von einem Mordplan höre, wer seine Augen schließt, damit er seine Lust nicht an dem Bösen habe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'der wohnt auf sicheren Höhen, und seine Burg sind Felsenschlösser. Dem wird sein Brot zuteil, dem bleibt sein Wasser sicher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Dann laben deine Augen sich an der Pracht des Königs; ein Land der Ferne sehen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Dein Herz besinnt sich auf die Schreckenszeit: \"Wo ist jetzt der, der ehedem gezählt? Wo der, der abgewogen? Wo der, der schon die Türme abgezählt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Ja, jenes wilde Volk siehst du nicht mehr, das Volk mit dunkler Rede, unverständlich, mit stammelnder, sinnloser Sprache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Auf Sion, unsrer Festgezeiten Stadt, schau hin! Hinblicken mögen deine Augen auf Jerusalem, die sichre Heimat! Ein unverrückbar Zelt! Kein Pflock wird fernerhin mehr ausgezogen; kein Strick reißt mehr darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Denn weil für uns ein Mächtiger dort weilt, der Herr, so ist es nun ein Ort, von Flüssen, breiten Strömen rings umflossen, darauf kein Ruderschiff sich wagt; kein stolzes Schiff durchschneidet sie. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Der Herr wird unser Richter sein, der Herr nur unser Fürst, der Herr nur unser König, der uns helfen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Wohl hingen deine Taue schlaff hernieder; sie konnten nicht den Mast in dem Gestelle halten und nicht das Segel spannen. Nunmehr wird reiche Beute ausgeteilt; selbst Lahme können Beute machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Und kein Bewohner sagt: \"Ich fühle mich erkrankt.\" Dem Volke, das darinnen wohnt, ist seine Missetat vergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Herbei, ihr Heidenvölker! Horchet auf! Merkt auf, ihr Nationen! Die Erde horche auf und was sie füllt, der Erdkreis und was ihm entsproßt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Der Herr ist über alle Heiden schwer ergrimmt und zornig über all ihr Heer. Er hat sie mit dem Bann belegt und sie der Schlachtbank preisgegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Da liegen ihre Abgeschlachteten. Der Dunst von ihren Leichen steigt hoch auf; von ihrem Blute triefen Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Die ganze Himmelsschar verschwindet. Der Himmel rollt sich wie ein Buch zusammen. Sein ganzes Heer verschwindet wie Laub vom Weinstock welkt, wie von dem Feigenbaum unreife Früchte fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, '\"Hat sich berauscht mein Schwert im Himmel, dann saust es auf die Erde nieder, auf das von mir gebannte Volk, zur Strafe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Das Schwert des Herrn wird dann voll Blut und trieft von Fett, vom Blut der Lämmer und der Böcke, vom Nierenfett der Widder. Zu Bosra gibt der Herr ein Opferfest, ein großes Schlachtfest in dem Edomlande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Wildstiere stürzen dort mit Büffeln, mit jungen Rindern Stiere. Vom Blute wird ihr Land berauscht; ihr Boden starrt von Fett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'So feiert einen Rachetag der Herr und der Vergeltung Jahresfrist bei Sions Feinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Da wandeln seine Bäche sich in Pech, sein Staub in Schwefel; sein Land wird brennend Pech.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Bei Nacht sowie bei Tag verlischt es nicht. Auf ewig steigt sein Qualm empor. Durch alle Zeiten bleibt es öde; nie zieht ein Wandersmann hindurch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Dort hausen Pelikan und Rohrdommeln; Nachteulen wohnen dort und Raben, und drüber wird der Öde Schnur, der Leere Senkblei ausgespannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Und keiner seiner Edlen ist mehr da, den man zur Herrschaft rufen könnte. All seine Fürsten sind dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Von Dornen werden seine Schlösser überwuchert, von Nesseln, Disteln seine Burgen. Zum Lager dient es den Schakalen, zum Tummelplatz den Straußen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Mit Wölfen streiten wilde Katzen sich um Plätze; Bocksgeister treffen dort einander. Dort herrscht der Nachtgeist, und er findet eine Ruhestatt für sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Dort heckt die Pfeilschlange; sie legt und brütet aus und hegt es im Versteck. Und Geier sammeln sich daselbst, zu seinesgleichen jegliches Getier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Befragt das Buch des Herrn und lest! Keins wird von diesen fehlen, kein Spruch vermißt den andern. Der Mund des Herrn hat so befohlen. Sein Geist hat sie versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Dies gibt er ihnen nun als Los, und seine Hand mißt\'s ihnen mit der Meßschnur zu. Auf ewig werden sie dies Land behalten, durch alle Zeiten darin wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Auf, Wüste, Öde, jauchze auf! Die Steppe juble auf! Wie Veilchen blühe sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Aufblühe sie! Sie juble, jauchze, jubiliere! Die Pracht des Libanon wird ihr geschenkt, der Schmuck vom Karmel und von Saron, und diese schauen jetzt des Herren Herrscherhoheit und unseres Gottes Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'So stärkt die schlaffen Hände, und stützt die schwanken Knie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Den angsterfüllten Herzen rufet zu: \"Getrost jetzt! Laßt die Furcht! Seht! Euer Gott ist da. Die Rache kommt und die Vergeltung Gottes; er selber kommt und rettet euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Dann öffnen sich der Blinden Augen, erschließen sich der Tauben Ohren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Dann springt der Lahme wie ein Hirsch; des Stummen Zunge jubelt. Es quellen Wasser in der Wüste auf und Bäche in der Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Der Glutsand wird zum Wasserteich und dürstend Land zu Wasserquellen, und wo Schakale Junge warfen, dort gedeiht das Gras wie Rohr und Schilf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Dort wird ein Straßendamm entstehen; den heiligen Weg benennt man ihn. Wer unrein ist, betritt ihn nicht. Wegweiser ist er selber, und so verirren sich Unkundige nie darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Kein Löwe wird dort sein, und nicht betritt ihn je ein reißend Tier; keins wird dort mehr gefunden. Ihn gehen nur Erlöste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Und die der Herr befreit hat, kehren heim. Mit Jauchzen kommen sie nach Sion, und um ihr Haupt schwebte ewige Freude. Freude und Wonne geben ihnen das Geleit, und weit entfliehen Schmerz und Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Im vierzehnten Jahre des Königs Ezechias zog Sanherib, Assyriens König, gegen Judas feste Städte, sie einzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Der König von Assyrien sandte den Rabsake von Lachis nach Jerusalem zum König Ezechias mit einer starken Heeresmacht; er stellte sich an des obern Teiches Wasserleitung auf, an der Straße nach dem Walkerfelde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Darauf ging Eljakim, Hilkias Sohn, des Hauses Vorstand, zu ihm hinaus, ebenso der Kanzler Sebna und der Ratsherr Joach, Asaphs Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Da sprach Rabsake zu ihnen: \"Berichtet Ezechias: So spricht der Großkönig, der König von Assyrien: \'Was ist es mit der Zuversicht, die du noch hegst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Du meinst vielleicht, ein bloßes Wort genüge schon für Kriegsplan und für Kriegerstärke? Auf wen verläßt du dich denn jetzt, daß du dich gegen mich empörst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Sieh, du verlässest auf Ägypten dich, auf diesen abgebrochenen Rohrstab, der jedem in die Hand fährt, der sich darauf stützt, und sie durchbohrt. So geht\'s mit Pharao, Ägyptens König, allen, die auf ihn vertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Sagt ihr mir aber. \"Nur auf den Herrn, auf unsern Gott, vertrauen wir,\", ja ist nicht eben er es, dessen Höhen und Altäre Ezechias abgeschafft, als er Jerusalem und Juda anempfohlen: \"Ihr sollt allein vor diesem Altar beten!\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Auf! Wette doch mit meinem Herrn, dem König von Assyrien! Ich wollte dir zweitausend Rosse geben, bist du imstande, für sie zu diesem Dienste Reiter zu beschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Wie willst du auch nur einen der geringsten Knechte meines Herrn zum Abzug bringen, und du verlässest dich auf dies Ägypten, um seiner Rosse, seiner Wagen willen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Sodann! Bin ich ohne den Herrn verderbenbringend gegen dieses Land herangezogen? Der Herr hat selbst zu mir gesagt: \"Zieh gegen dieses Land, verheere es!\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Da sprachen Eljakim, Sebna und Joach zu Rabsake: \"Sprich doch mit deinen Knechten aramäisch! Denn dies verstehen wir. Doch rede nicht judäisch mehr mit uns vor diesen Leuten auf der Mauer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Da sprach Rabsake: \"Hat mich mein Herr zu deinem Herrn allein und nur zu dir gesandt, dies zu verkünden? Gilt\'s nicht für diese Männer auf der Mauer? Sie haben ihren Kot zu essen und ihren Harn mit euch zu trinken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Und Rabsake gab nicht nach. Vielmehr rief er mit lauter Stimme auf judäisch und sprach: \"Vernehmt die Worte des Großkönigs, des Assyrerkönigs!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So spricht der König: \'Ezechias soll euch nicht betören! Er kann euch ja nicht retten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Und laßt euch doch von Ezechias nicht vertrösten auf den Herrn, indem er sagte: \'Der Herr wird uns gewißlich retten; die Stadt fällt nicht in des Assyrerkönigs Hand.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Hört nicht auf Ezechias! Denn also spricht der König von Assyrien: \'Schließt mit mir doch Frieden und kommt zu mir heraus! Dann dürfet ihr, ein jeglicher, von seinem Weinstock und von seinem Feigenbaume essen und jeder seines Brunnens Wasser trinken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'bis daß ich komme, euch in ein Land zu holen, das dem euren gleicht, zu einem Land voll Korn und Wein, zu einem Land voll Korn und Weinbergen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Will aber Ezechias euch verführen, indem er spricht: \'Der Herr kann uns erretten\' - ja, haben denn die Heidengötter, ein jeglicher sein Land, aus des Assyrerkönigs Hand errettet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Wo sind die Götter von Hamat und Arpad? Wo sind die Götter von Sepharvaim? Und wo die Götter von Samaria? Ja, haben sie vielleicht Samaria aus meiner Hand befreit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Wer ist doch unter all den Göttern dieser Länder, der sein Land aus meiner Hand errettet hätte? Jetzt sollte gar der Herr Jerusalem aus meiner Hand befreien?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Da schwiegen sie und sie erwiderten ihm nichts; denn des Königs Befehl lautete. \"Ihr sollt ihm nichts erwidern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Hierauf kamen Eljakim, Hilkias Sohn, des Hauses Vorstand, und Sebna, der Kanzler, und der Ratsherr Joach, Asaphs Sohn, zu Ezechias mit zerrissenen Kleidern und berichteten ihm des Rabsake Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Als König Ezechias dies vernahm, zerriß er seine Kleider, legte an ein Bußgewand und ging in\'s Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Dann sandte er Eljakim, des Hauses Vorstand, und Sebna, den Kanzler, und die Ältesten der Priester, in Bußgewänder gehüllt, zu Isaias, dem Amossohne, dem Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Und sie sollten zu ihm sprechen: \"So spricht Ezechias: \'Ein Tag der Not, der Drangsal und der Schmach ist dieser Tag; denn Kinder wollen durchbrechen; doch fehlt die Kraft, sie zu gebären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Vielleicht hört doch der Herr, dein Gott, auf des Rabsake Reden, den sein Herr, der König von Assyrien, hergesandt, zu lästern den lebendigen Gott und ihn mit Worten zu beschimpfen; dies hat der Herr, dein Gott, vernommen. So leg Fürsprache ein für diesen Rest, der noch vorhanden!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Als des Königs Ezechias Diener zu Isaias kamen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'sprach Isaias zu ihnen: \"Sprecht zu so eurem Herrn: So spricht der Herr: \'Hab keine Angst der Reden wegen, die du hörtest, mit denen mich die Knechte des Assyrerkönigs gelästert haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Ich setze einen Geist ihm jetzt entgegen. Er wird dann eine Kunde hören und heim nach seinem Lande ziehen. Ich fälle ihn in seinem Lande durch das Schwert.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Darauf kehrte Rabsake zurück und traf den König der Assyrer bei der Belagerung von Libna an. Er hatte nämlich schon gehört, er sei von Lachis aufgebrochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Da hörte er vom Äthiopierkönig Tirhaka: \"Er zieht heran, mit dir zu kämpfen.\" Da sandte er auf diese Nachricht hin an Ezechias Boten und ließ sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '\"Sagt so zu Ezechias, Judas König! Laß dich von deinem Gotte nicht betören, auf den du baust wegen des Spruches: \'Jerusalem fällt nicht in des Assyrerkönigs Hand!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Du hast ja selbst vernommen, wie die Assyrerkönige mit allen Ländern sind verfahren, an denen sie den Bann vollstreckt. Da wolltest du gerettet werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ja, haben wohl die Götter all der Heidenvölker, die meine Ahnen einst vernichtet, sie retten können? Gozan und Charan und Reseph sowie Edens Söhne in Telassar?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Wo ist der König von Hamat und wo der König von Arpad? Wo ist der König der Stadt Sepharvaim, von Hena und von Avva?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Als Ezechias diesen Brief der Boten Hand entnommen und ihn gelesen hatte, ging er in das Haus des Herrn. Und Ezechias breitete ihn vor dem Herrn dort aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Dann betete Ezechias also zu dem Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '\"Du Herr der Heeresscharen, Israels Gott, der über Cherubinen thront! Nur Du allein bist Gott für alle Erdenreiche; Du schufst den Himmel und die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Neig, Herr, Dein Ohr und höre! Herr! Öffne Deine Augen! Sieh her und höre alle Worte Sanheribs, die er verlauten ließ zum Hohn auf den lebendigen Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Wahr ist\'s ja, Herr.- Die Könige Assyriens verheerten alle Länder und das ihrige dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Sie warfen deren Götter selbst ins Feuer. Denn diese waren keine Götter, nur Menschenmachwerk, Holz und Stein; so konnte man sie gut vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Nun aber, Herr, Du unser Gott! Errette uns aus seiner Hand! Der Erde Reiche sollen insgesamt erkennen: Du bist allein der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Da sandte Isaias, des Amos Sohn, zu Ezechias und ließ sagen: \"So spricht der Herr, Gott Israels, zu dem du betest, jetzt über Sanherib, den König von Assyrien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Dies ist das Wort, das über ihn der Herr gesprochen: \'Die Jungfrau, Sions Tochter, spottet deiner und verachtet dich. Die Tochter von Jerusalem, sie schüttelt hinter dir das Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Wen lästerst du? Wen schmähst du, gegen wen erhebst du deine Stimme? - Du tatest deine stolzen Augen auf, dem Heiligen Israels zum Trotz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Durch deine Knechte sprachest du vom Herrn vermessen: \"Mit der Menge meiner Wagenzüge dringe ich hinauf bis zu der Berge höchsten Höhen, selbst auf den höchsten Libanon, und fälle seine höchsten Zedern und seine schönsten Fichten. Ich dringe bis zu seinem höchsten Gipfel in seine reichsten Waldungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Zur Kühlung trinke ich die Firngewässer und trete mit den Füßen all die Gletscherströme aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hast du denn nicht gehört, daß ich seit langem dies geplant, von alten Zeiten her bestimmt? Jetzt ließ ich Ähnliches geschehen. So wurden beste Städte ja durch Schleifung bis zum Grund verheert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Und die in ihnen wohnten, für die Verteidigung zu schwach, erzitterten und bebten. Sie wurden wie des Feldes Kraut, wie grünend Gras, wie Hälmchen auf den Dächern, wie unreifes, vermengtes Korn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Bekannt ist mir dein Aufstehn und dein Niedersitzen; dein Gehen und dein Kommen kenne ich sehr gut und auch dein Toben gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Zu Ohren kam dein Toben mir, dein Ungestüm. So lege ich in deine Nase meinen Ring und meinen Zaum in deine Lippen und führ\' dich auf dem selben Wege heim, auf dem du hergekommen bist.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Dies sei zum Zeichen: In diesem Jahre iß den Altwuchs! Im zweiten Jahr den Brachwuchs! Im dritten Jahre aber sät und erntet wieder! Pflanzt Weinberge! Genießet ihre Früchte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Und was dem Untergang entronnen und was im Hause Juda übrig ist, bewurzelt in der Tiefe sich, und oben trägt es Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Denn aus Jerusalem wird das, was übrig ist und was dem Untergang entging, vom Sionsberge sich verbreiten. Die Eifersucht des Herrn der Heerscharen tut dies.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'So spricht der Herr zum König von Assyrien: \"Er dringt in diese Stadt nicht ein, schießt keinen Pfeil hinein; mit keinem Schild berennt er sie, und keinen Wall erstellt er gegen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Denselben Weg, auf dem er kam, muß er zurück; die Stadt jedoch betritt er nicht.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '\"Ich schirme diese Stadt und helfe ihr um meiner selbst und meines Dieners David willen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Darauf ging der Engel des Herrn aus und schlug im Assyrerlager 185.000 Mann, und als man sich frühmorgens aufmachen wollte, waren sie allesamt leblose Leichname.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Da brach Sanherib, Assyriens König, auf und zog ab. Und er blieb in Ninive.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Während er einmal im Hause Nisrochs, seines Gottes, betete, ermordeten ihn seine Söhne Adramelech und Sareser mit dem Schwert. Sie flohen ins Land Ararat. Da wurde sein Sohn Asarhaddon an seiner Statt König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Zu jener Zeit ward Ezechias todkrank. Da besuchte ihn der Prophet Isaias, des Amos Sohn, und sprach zu ihm: \"So spricht der Herr: Bestell dein Haus! Denn sterben mußt du, ohne zu genesen.\"-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Da wandte sich Ezechias mit seinem Angesicht zur Wand und betete zum Herrn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'und sprach: \"Ach Herr, denk doch daran, daß ich vor Dir gewandelt, treulich und mit ungeteiltem Herzen, und daß ich tat, was Dir gefiel!\" Darauf brach Ezechias in lautes Weinen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Da erging das Wort des Herrn an Isaias, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '\"Auf! Sprich zu Ezechias: Also spricht der Herr, des Davids, deines Vaters, Gott: \'Ich hörte dein Gebet und schaute deine Tränen. So lege ich denn deinen Tagen noch fünfzehn Jahre zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Ich rette dich aus des Assyrerkönigs Hand samt dieser Stadt; ich schirme diese Stadt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Dies diene dir vom Herrn als Zeichen, daß wirklich auch der Herr das tut, was er verspricht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Die Schatten von den Stufen laß ich soviel rückwärtsgehen, wie schon die Sonne an des Achaz Sonnenzeiger sank, zehn Stufen.\'\" Da stieg die Sonne um zehn Stufen wieder, So viele Stufen sie gesunken war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Ein Gedicht von Ezechias, dem Judakönig, als er krank war und von seiner Krankheit dann genas:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '\"Ich spreche: In meines Lebens voller Kraft soll ich das Tor der Unterwelt betreten und mich beraubt des Restes meiner Jahre sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Schon habe ich gesprochen: Ich soll den Herrn nicht wiedersehn im Lande der Lebendigen und Menschen nicht mehr schauen dort bei des Totenreichs Bewohnern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Mein Zelt soll abgebrochen werden und eingerollt. Aufrollen willst Du, einem Weber gleich, mein Leben, abschneiden mich vom Faden. Bevor die Nacht dem Tage folgt, bist Du schon mit mir fertig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Du handelst richtig wie ein Löwe; so wird all mein Gebein zermalmt. Bevor die Nacht dem Tage folgt, bist du mit mir schon fertig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Wie eine Schwalbe ächze ich und seufze wie die Drosseln. Zur Höhe tränen meine Augen: Ich bin so hart bedrückt, Herr! Tritt Du doch für mich ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Wo soll ich Worte finden? Was er mir angekündigt, tut er auch. All meine Jahre ende ich in Bitternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herr, deshalb mögen sie noch weiter dauern, und möge doch mein Geist in ihnen allen lebend sein! Mach mich gesund und laß mich weiter leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Zum Heile dient mir dann die bittre Bitternis, bewahrst Du meine Seele vor dem sichern Untergange, weil hinter Deinen Rücken Du all meine Sünden wirfst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Die Unterwelt lobpreist Dich nicht; Dich lobt auch nicht der Tod. Die rühmen Deine Treue nicht, die in die Grüfte sinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Nur wer noch lebt, nur wer noch lebt, der kann Dich loben so wie ich\'s heute möchte tun. Der Vater kündete alsdann den Söhnen Deine Treue an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Zu Hilfe, Herr! Wir wollen alle unsere Lebenstage im Haus des Herrn die Saitenspiele rühren.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Isaias befahl hierauf, ein Feigenpflaster herbeizubringen und dies auf das Geschwür zu streichen, auf daß er genese.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Da sprach Ezechias: \"Was ist das Zeichen, daß ich wieder in das Haus des Herrn eingehen kann?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Zu jener Zeit sandte Merodoch Baladan, Baladans Sohn, der Babelkönig, Schreiber mit Geschenken zu Ezechias, auf die Nachricht hin, daß er krank gewesen und wieder zu Kräften gelangt sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Ezechias freute sich darüber und zeigte ihnen sein Schatzhaus, das Silber und das Gold, die Spezereien und das Feinöl und sein ganzes Zeughaus und alles andere in seinen Schatzkammern. Nichts gab es in seinem Hause und in seinem ganzen Herrschaftsgebiete, was ihnen Ezechias nicht gezeigt hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Da kam der Prophet Isaias zum König Ezechias und sprach zu ihm: \"Was haben diese Männer denn gesprochen? Woher kommen sie zu dir?\" Da sprach Ezechias: \"Aus fernem Lande kommen sie zu mir, aus Babel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Da sprach er: \"Was haben sie in deinem Hause sich besehen?\" Ezechias sprach: \"Alles haben sie in meinem Hause sich besehen. Nichts gibt es, was ich ihnen in meinen Schatzkammern nicht vorgewiesen hätte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Da sprach Isaias zu Ezechias: \"Vernimm das Wort des Herrn der Heerscharen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, '\'Einst kommen Tage, da alles, was in deinem Hause ist, was deine Väter bis auf diesen Tag sich aufgespeichert, nach Babel fortgebracht wird. Nichts läßt man übrig\', spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Und auch von deinen Leibessöhnen, die du noch zeugst, wird man dann einige nehmen, damit sie Kämmerlinge im Palast des Babelkönigs werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Da sprach Ezechias zu Isaias. \"Das Herrnwort, das du angekündigt hast, ist recht.\" Dann sprach er. \"Ein dauerhafter Friede herrsche noch in meinen Tagen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '\"Nun tröstet, tröstet mir mein Volk!\" so läßt sich euer Gott vernehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Zu Herzen sprecht Jerusalem und ruft ihm zu, sein Sklavendienst sei aus und seine Schuld gebüßt! - Denn aus der Hand des Herrn hat es für seine Sünden insgesamt das Doppelte empfangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Horch! Einer ruft: \"Bahnt in der Wüste einen Weg des Herrn! Für unsern Gott bereitet in der Steppe grade Straßen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Erheben soll sich jedes Tal, und jeder Berg und Hügel soll sich senken! Das Krumme werd gerade und eben alles Höckerige!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Denn sichtbar werden will des Herren Lichter Glanz, und sehen soll ihn alle Welt zusammen! Der Mund des Herrn hat es gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Horch! Einer spricht: \"Verkünde!\" \"Was denn\", fragt ein andrer, \"soll ich künden?\" \"Die ganze Welt ist Gras, all ihre Pracht ist wie die Blume, des Feldes Blume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Das Gras verdorrt, die Blume welkt, wenn sie der Hauch des Herren trifft. Wahrhaftig, Gras nur sind die Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Das Gras verdorrt: die Blume welkt. Doch unseres Gottes Wort besteht in Ewigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Ersteige einen hohen Berg als Freudenbotin! Erhebe mächtig deine Stimme als Freudenbotin, du Jerusalem! Furchtlos erhebe sie und rufe Judas Städten zu: \"Seht! Da ist euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Der Herr, der Herr kommt als der Sieger; sein Arm allein hat ihm den Sieg erkämpft. Sein Sold ist auch bei ihm; sein Kampfpreis geht vor ihm einher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Er weidet seine Herde wie ein Hirt; in seinen Arm nimmt er die Lämmer. An seinem Busen trägt er sie und leitet sanft die Mutterschafe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Wer mißt mit seiner Faust die Wasser und wer den Himmel mit der Spanne? Wer faßt denn in ein Drittelmaß der Erde Staub und wägt die Berge mit der Waage, in ihren Schalen ihre Hügel?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Wer mißt den Geist des Herrn? Und wer ist sein Berater, der ihn unterwiesen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Wen zieht er je zu Rat, daß er ihn weise machte und ihn den Pfad der Ordnung lehrte und ihn in Einsicht weiterbrächte und ihm die Weisheitsbahn entdeckte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Die Heidenvölker sind ein Tropfen an dem Eimer und gelten, was ein Flöckchen an der Waage gilt. Die Inseln fallen ins Gewicht nur wie ein Stäubchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Kein Libanon reicht hin zum Feuer, zum Opfer nicht sein Wild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Die Heidenvölker alle sind wie nichts vor ihm, sind weniger als nichts in seinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Wem wollt ihr also Gott vergleichen und unter welchem Bild ihn darstellen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Ein Götzenbild, das gießt der Künstler; der Goldschmied überzieht\'s mit Gold und schließt\'s mit Silberkettchen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Und wer zu arm für solche Stiftung, wählt ein Holz aus, das nicht fault. Dann sucht er einen guten Künstler, ein Götzenbild ihm anzufertigen, das nicht aus den Fugen geht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Wißt ihr es nicht Wollt ihr\'s nicht hören? Ward\'s nicht schon längst euch kundgetan? Kennt ihr denn nicht der Erde Gründungsart?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Er, der da thronet überm Erdenrund; seine Bewohner sind wie Heuschrecken. Er, der wie einen Flor den Himmel ausgebreitet und wie ein Wohngezelt ihn ausgespannt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'er, der die Fürsten in ein Nichts verwandelt, der Erde Mächtige in leere Luft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Kaum sind sie eingepflanzt, kaum ausgesät, kaum wurzelt ein ihr Stamm im Boden, da bläst er sie schon an, und sie verdorren, und fort trägt sie der Sturm wie Spreu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '\"Wem also wollt ihr mich vergleichen?\" So fragt der Heilige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Zur Höhe hebet eure Augen! Und haltet Umschau! Wer ist ihr Schöpfer? Wer führt ihr Heer gezählt hervor und ruft sie all mit Namen auf? Und vor dem Starken und dem Mächtigen bleibt nicht eines aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Weswegen sagst du, Jakob, und sprichst du, Israel: \"Mein Schicksal ist dem Herrn verborgen, und meinem Gott entgeht mein Recht\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Weißt du denn nicht? Hast du\'s nicht gehört? Ein ewiger Gott, das ist der Herr, und wandert er bis an der Erde Säume, wird er nicht müde und nicht matt, und sein Verstand ist unbegrenzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Den Müden gibt er Stärke und den Erschöpften neue Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Mag müd und matt die Jugend werden und mögen Rüstige zusammenbrechen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'doch die des Herren harren, gewinnen neue Kraft; sie zeigen Schwingen gleich den Adlern. Sie laufen und ermüden nicht und gehn und werden nimmer matt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, '\"Hört still mir zu, ihr Inseln! Und stärken sollen sich Nationen und dann zur Unterredung kommen! Zum Entscheid wollen wir zusammentreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Wer ruft von Osten her den Falken, der auf dem Fuß ihm folgt? Wer gibt ihm Heidenvölker preis und treibt die Könige in Flucht, und wessen Schwert jagt sie wie Staub davon, und wessen Bogen wie verwehte Spreu?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Und er verfolgt sie, sicher wandelnd, auch auf Pfaden, die noch nie sein Fuß betreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Wer wirkt und waltet es? Ich, der von Anfang an ruft die Geschlechter. Ich, der Herr, der Erste und bei den Letzten noch derselbe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Voll Furcht vernehmen es die Inseln; die Erdenenden beben. Sie kommen näher her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Und einer sucht dem anderen zu helfen und ruft ihm zu: \"Nur Mut!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Der Schnitzer muntert einen Goldschmied auf; der mit dem Hammer schafft, den Blasbalgtreter, der von der Lötung sagt: \"Die ist jetzt gut\", und es mit Nägeln dann befestigt, damit\'s nicht wackle. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, '\"Du aber, Israel, mein Knecht, du Jakob, den ich auserkoren, du Sproß von meinem Freunde Abraham!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Du, den ich vor den Vornehmsten der Welt erwählt, vor ihren Edelsten berufen habe! Ich sage dir: \'Mein Knecht bist du; dich habe ich erkoren und nicht abgelehnt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Sei ohne Furcht! Ich bin mit dir. Sei ohne Angst! Ich bin dein Gott. Ich stärke dich; ich helfe dir und stütze dich mit meiner sieggewohnten Rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Mit Schimpf und Schande wird bedeckt, wer dich beschimpft. Vernichtet wird und untergeht, wer mit dir streitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Du suchst alsdann und findest sie nicht mehr, die mit dir streiten. Vernichtet werden und vergehn, die dich bekriegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Denn ich, der Herr, ich bin dein Gott, der deine rechte Hand ergreift, der zu dir spricht: \'Sei ohne Furcht! Ich bin es, der dir hilft.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Sei ohne Furcht, mein Würmlein Jakob! Ihr armen Männer Israels! Ich bin es, der ihm hilft.\" Ein Spruch des Herrn. \"Ja, dein Erlöser ist der Heilige Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Ich mache dich zu einem Dreschschlitten, so scharf und neu, mit vielen Schneiden. Du wirst die Berge dreschen und zermalmen und Hügel wie in Spreu verwandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Du worfelst sie; der Wind trägt sie hinweg, der Sturm reibt sie zu Staub. Du jubelst dann über den Herrn und rühmest dich des Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Die Elenden und Armen suchen Wasser; doch keins ist da. Vor Durst ist ihre Zunge ausgetrocknet. Doch ich, der Herr, bekümmere mich um sie; ja ich, der Schutzgott Israels, verlasse nimmer sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Ich lasse Ströme fließen auf den kahlen Höhen und Quellen mitten in den Gründen. Zu Wasserteichen mache ich die Wüsten und dürres Land zu Wassersprudeln;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'ich lasse in der Wüste Zedern und Akazien und Myrten und Oliven wachsen und pflanze in die Steppe ein Zypressen, Ulmen, Fichten allzumal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Sie sollen sehen und erkennen, drauf achten und sich merken, daß dies die Hand des Herrn getan, daß dies der Heilige des Herrn getan, daß dies der Heilige Israels geschaffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, '\"Bringt eure Sache vor!\" So spricht der Herr. \"Legt vor eure Beweise!\" So spricht der König Jakobs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, '\"Sie mögen nähertreten und uns künden, was sich ereignen wird! Was war es mit dem Früheren? So sagt es, daß wir es vermerken und uns erkundigen nach dem Eintritt! Oder macht uns doch die Zukunft kund!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Ja, kündet uns die Zeichen schon im voraus an! Dann werden wir es anerkennen, daß in der Tat ihr Götter seid, und daß ihr nützen könnt und schaden. Dann wollen wir uns alle voller Staunen fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Ihr seid ja weniger als nichts, und euer Tun ist weniger als null. Abscheulich ist, wer euch erwählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Von Norden ruf ich, und er kommt; vom Sonnenaufgang den, der meinen Namen ruft, und in Satrapen tritt er wie in Lehm, so wie ein Töpfer stampft den Ton.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Wer zeigte solches schon zum voraus an, daß wir\'s erfahren hätten, im voraus, daß wir hätten sagen können: \'Richtig!\'? Doch keiner hat je so etwas verkündet, und keiner solches kundgetan. Kein Mensch bekommt von euch ein Wort zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Nur ich bestelle Boten für Sion als Erster - sie sind, fürwahr, schon da - und Freudenboten für Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Ich schaue rings umher, und keiner tritt hervor. Von ihnen zeigt sich keiner als Berater, daß ich sie bitten könnte, mir Auskunft zu erteilen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Seht! Nichtig sind sie alle und nichtig ist ihr Tun, und ihre Bilder, die gegossenen, sind Tand und leerer Schein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, '\"Hier ist mein Knecht, dem ich als Stütze diene, der von mir Auserkorene, der meinem Herzen wohlgefällt! Ich lege meinen Geist auf ihn; den Heidenvölkern wird er Wahrheit künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Er macht nicht Geschrei und ruft nicht laut; nicht läßt er sich in Gassen hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Geknicktes Rohr zerbricht er nicht; zerdrückt den Docht nicht, den verlöschenden! Hinaus trägt er in Treue Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Er wird nicht müde und nicht matt, bis er auf Erden Wahrheit durchgeführt; die Inseln warten ja auf seine Weisung.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'So spricht der Gott, der Herr, des Himmels Schöpfer, der ihn ausgebreitet und der die Erde festigt und ihr Gewächs, der Lebenshauch dem Volk darauf verleiht und Atem denen, die drauf wandeln:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '\"Ich rufe dich in Gnaden, ich, der Herr; ich fasse dich bei deiner Hand, beschütze dich und mache dich zum Ruhme für das Volk, zum Licht für Heidenvölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Sollst blinde Augen öffnen, Gefang\'ne aus dem Kerker führen, und aus dem Kerker, die im Finstern sitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Mein Name ist, \'der Herr\', und meine Ehre trete ich nicht einem andere ab und meinen Ruhm nicht Götzenbildern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Das Frühere, seht, es ist erschienen. Und nun verkünde ich euch Neues; bevor es keimt, laß ich\'s euch hören.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Dem Herren singt ein neues Lied, sein Lob bis an der Erde Rand, ihr Fahrer auf dem Meer und seiner Fülle, ihr Inseln und die sie besiedeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Die Wüste juble auf mit ihren Triften, den Dörfern, darin Kedar wohnt! Die auf den Felsen siedeln, sollen jauchzen und von der Berge Gipfel her laut jubilieren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Dem Herren sollen sie die Ehre geben und auf den Inseln seinen Ruhm verkünden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Der Herr zieht aus als Held; als Kriegsmann weckt er seinen Eifer; er schreit, er brüllt, und mannhaft geht er gegen seine Feinde vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, '\"Urlang geschwiegen habe ich, und mich gehüllt in Schweigen. Jetzt schreie ich wie eine Kreißende und stöhne, schnaube allzumal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Ich dörre Berg und Hügel aus und lasse all ihr Grün verwelken und wandle Ströme um in dürres Land und lege Sümpfe trocken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Auf unbekanntem Wege führe ich die Blinden; ich leite sie auf unbekannten Steigen. Vor ihnen mache ich die Finsternis zum Licht, zur ebenen Fläche Schluchten! Das sind nun Dinge, die ich früher schon getan und die ich noch nicht aufgegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Es sollen rückwärts prallen und beschämt sich fühlen, die auf geschnitzte Bilder sich verlassen, die zu gegossenen Bildern sprechen: \'Ihr seid unsere Götter.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Ihr Tauben, horchet auf! Ihr Blinden, schauet auf und seht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Wer war je blind, wenn nicht mein Knecht? Wer taub, wenn nicht mein Bote, den ich senden will? - Wer je so blind wie der Knecht des Herrn?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Viel sahst Du, doch behieltest nichts. Du hattest offene Ohren, hörtest aber nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Dem Herrn gefiel\'s, um seines Heiles willen, die Lehre groß und wundervoll zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Da wurden sie ein Volk, beraubt, geplündert. In Löchern lagen sie gefesselt alle; in Kerkerhäuser waren sie gesteckt; zum Raub geworden, ohne Retter, zur Beute, und niemand sprach: \'Gib\'s wieder her!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Wer unter euch wohl, der dies hört, wird aufmerksam das Folgende vernehmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Wer gab zur Beute Jakob preis und Israel den Räubern? War\'s nicht der Herr, an dem wir uns versündigt, auf dessen Wegen sie nicht wandeln und dessen Lehre sie nicht hören wollten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'So goß er seinen Grimm darüber aus, des Krieges Härte. Rings um sie flammte es. Man achtete des aber nicht, und so verbrannt\' es sie. Doch nicht zu Herzen nahm man es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Nun aber spricht der Herr, dein Schöpfer, Jakob, dein Bildner, Israel: \"Sei ohne Furcht! Denn ich erlöse dich. Ich rufe dich beim Namen; du bist mein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Wenn du durchs Wasser gehen mußt, bin ich bei dir, durch Ströme, doch sie schwemmen dich nicht fort. Wenn du durchs Feuer gehen mußt, verbrennst du nicht; die Flamme sengt dich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Denn ich, der Herr, ich bin dein Gott, der Heilige Israels dein Retter. Zum Lösegeld für dich geb ich Ägypten hin, für dich auch Äthiopien und Saba.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Weil teuer du in meinen Augen bist und wertgeachtet, mir so lieb, drum gebe ich auch andre Leute für dich hin und andre Völker für dein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Sei ohne Furcht! Ich bin mit dir. Von Osten bring ich dein Geschlecht herbei, von Westen dich zuhauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Ich sage zu dem Norden: \'Gib heraus!\' Zum Süden: \'Halt sie nicht zurück! Bringt aus der Ferne meine Söhne her und meine Töchter von der Erde Rand!\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'sie alle, die genannt nach meinem Namen: ich schaffe es um meiner Ehre willen und mache es und führe es auch aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, '\"Das Volk! Heraus mit ihm, das blind und dennoch Augen hat, die taub und dennoch Ohren haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Zusammenstehen sollen all die Heidenvölker und die Nationen sich zusammenscharen! Wer kann bei jenen solches melden? Sie sollen Früheres uns hören lassen! Sie sollen ihre Zeugen bringen, daß sie Recht bekommen, auf daß man\'s höre und dann sage: \'Richtig\'!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ihr seid nun meine Zeugen\", ein Spruch des Herrn, \"mein Knecht, den ich erwählt, daß ihr gewißlich an mich glaubt und merkt, daß ich es bin, daß nicht ein Gott vor mir gebildet ward, und daß es nach mir keinen anderen gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ich, ich nur bin der Herr, und außer mir gibt\'s keinen Helfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ich habe es verkündet und alsdann geholfen. Als ich\'s verkünden ließ, war unter euch kein Fremder. Das müßt ihr mir bezeugen.\" Ein Spruch des Herrn. \"So bin ich also Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Von jeher war ich stets derselbe. Aus meiner Hand ist niemand zu erretten. Was ich beginne, wer will\'s hindern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So spricht der Herr, der euch erlöst, der Heilige Israels: \"Um euretwillen habe ich nach Babel hingesandt. Die Segelschiffe ließ ich alle sie besteigen und die Chaldäer ihre schnellen Schiffe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ich bin der Herr und euer Heiliger, der Schöpfer Israels und euer König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So spricht der Herr, der einen Weg gab durch das Meer, durch starke Wasser eine Straße');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'und Roß und Wagen sie betreten ließ und Heerestroß und Krieger abzumal. - Da liegen sie und stehen nicht mehr auf, erloschen, wie ein Docht verglommen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, '\"Denkt nicht der früheren Taten! Achtet des Vergangenen nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Ich schaffe etwas Neues. Es keimt schon auf. Merkt ihr es nicht? Ich bahne durch die Wüste einen Weg; ich lasse Ströme fließen durch die Öden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Des Feldes Wild preist mich, Schakale, Strauße, daß in der Wüste Wasser ich jetzt spende und Ströme in den Öden, um mein erkornes Volk zu tränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Das Volk, das ich mir selbst erschaffen, muß meinen Ruhm verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mich hast du, Jakob, nicht gerufen, nicht dich um mich bemüht, du Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Du brachtest mir kein Lamm zum Opfer; nicht ehrtest du mich je mit deinen Schlachtopfern. Mit Speiseopfern war ich dir nicht lästig, mit Weihrauch nicht beschwerlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Du kauftest nicht für mich um Geld Gewürzrohr und labtest nimmer mich durch deine fetten Schlachtopfer. Wohl aber wurdest du durch deine Sünde mir beschwerlich; durch deine Missetaten fielst du mir zur Last.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ich selber tilge nur um meinetwillen deine Missetaten, und deiner Sünden denke ich nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Verbessere mich nur! Wir wollen miteinander rechten. So bringe irgend etwas vor, damit du recht behaltest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Dein erster Vater hat gesündigt, und deine Mittler brachen mir die Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Die heiligen Fürsten mußte ich entweihen, dem Banne Jakob überliefern und Israel dem Hohne überlassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, '\"Nun, Jakob, höre, du mein Knecht, und Israel den ich erkoren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So spricht der Herr, der dich gemacht und dich im Mutterschoß gebildet hat, dein Helfer. \"Jakob, mein Knecht, sei ohne Furcht, und Jeschurun, den ich erkoren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Ich gieße Wasser auf ein durstig Land und auf ein ausgedorrtes Wasserbäche. Ich gieße meinen Geist auf deinen Stamm und meinen Segen über deine Sprößlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Sie sprießen wie im Sumpf das Gras, wie Weiden an den Wasserbächen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Der sagt: \'Dem Herrn gehöre ich\', und der nennt stolz den Namen Jakobs, und der schreibt sich auf seine Hand \'dem Herrn gehörig\' und gibt den Namen Israel den Kindern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So spricht der Herr, der König Israels und sein Erlöser, Herr der Heerscharen: \"Ich bin der Erste, ich der Letzte, und außer mir gibt\'s keinen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Wer ist wie ich, der sage es, vermelde es und lege mir nur irgend etwas vor, seit ich ein ewig Volk erschaffen! Das Künftige, das kommen wird, das zeige er zu seinem Ruhme an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Seid ohne Furcht und ohne Sorgen! Ja, habe ich nicht längst zuvor die Dinge kundgemacht und angezeigt? Ihr müßt es mir bezeugen, ob\'s einen Gott gibt außer mir. Von einem andern Felsen weiß ich nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die Götzenbilder allesamt sind nichts, und ihre schönsten Werke helfen nichts. Bezeugen müssen sie dies selbst; sie sehen nichts und merken nichts. So muß sich schämen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'wer einen Götzen bildet und ein unnütz Bild sich gießt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Sich schämen müssen alle die Gesellen. Die Meister selber werden rot, und stehen sie versammelt beieinander, geraten sie in Angst und Scham zumal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Der Schmied schlägt Eisen ab und tut\'s in Kohlenglut und formt es mit den Hämmern und schlägt mit seinem starken Arm darauf. Doch hungert\'s ihn, dann wird er matt, und trinkt er Wasser nicht, dann wird er kraftlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Der Tischler spannt die Meßschnur aus und zeichnet\'s mit dem Stifte auf und gibt durch Hobeln ihm Gestalt und formt es nach dem Zirkel. Er macht\'s zu einer Mannsfigur, zum schönen Menschenbild; in einem Hause soll es wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Ein andrer wählt beim Zedernfällen Fichten oder Eichen aus. Ein dritter zieht sich Waldesbäume groß, sich Fichten pflanzend, die durch Regen wachsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Dem Menschen dient es dann zum Heizen; er nimmt davon und wärmt sich auf; auch heizt er ein und backt sich Brot. Auch einen Gott macht er davon und betet an ein Götzenbild, vor dem er niederfällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Im Feuer hat er einen Teil davon verbrannt, und über seinen Kohlen buk er Brot, und über einem andern Teile briet er Fleisch und aß den Braten, wurde satt und wärmte sich, rief endlich aus: \'Eija, ich bin durchwärmt, ich habe an dem Feuer mich erquickt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Den Rest davon hat er zu einem Gott, zu seinem Götzenbild gemacht, davor sich bückend, fällt er nieder, fleht zu ihm und spricht: \'Errette mich! Mein Gott bist du!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'So unverständig sind sie, so gedankenlos. Verklebt sind ihre Augen; sie sehen nichts, und ihre Herzen merken nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Nichts kommt ihm in den Sinn. Nicht soviel Einsicht hat er und Verstand, so daß er spräche: \'Im Feuer habe ich doch einen Teil verbrannt und Brot in seiner Glut gebacken und Fleisch gebraten und verzehrt. Den Rest davon soll ich zum Greuelbilde machen und einen Holzklotz anbeten?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Der Asche freut er sich, betört sein leicht betörbar Herz. Er rettet seine Seele nicht, so daß er spräche: \'Ist dies in meiner Rechten hier nicht Tand?\' -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Denk daran, Jakob, und Israel, daß du mein Diener bist, daß ich dich mir zum Knecht erzogen! Du bleibst mir unvergessen, Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Ich wische wie ein Wölkchen deine Missetaten aus, wie eine Wolke deine Sündenstrafen. Zurück zu mir! Denn ich erlöse dich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Ihr Himmel, jauchzet! Denn der Herr vollbringt\'s. Frohlocket laut, ihr Erdenklüfte! Ihr Berge, brecht in Jubel aus, du Wald und alle Bäume drin! Jakob erlöst der Herr und prangt mit Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So spricht der Herr, der dich erlöst, der dich im Mutterschoß gebildet. \"Ich bin der Herr, der alles macht und der allein den Himmel ausgespannt und selbst die Erde hingebreitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'der eitel macht der Schwätzer Zeichen, Wahrsager zu Toren, zum Rückzug Weise bringt, der ihre Künste narrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'doch seiner Knechte Wort bestätigt, seiner Boten Plan vollbringt und von Jerusalem so spricht: \'Besiedelt werde es!\' und von den Städten Judas: \'Sie werden wieder aufgebaut. Herstellen will ich ihre Trümmer\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'der spricht auch zu der Tiefe: \'Versiege! Austrocknen will ich deine Fluten\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'der spricht von Cyrus: \'Erfüllen soll er meinen Plan und meinen Wunsch vollauf.\'\" Er spreche von Jerusalem: \"Es werde wieder aufgebaut; der Tempel werde neu gegründet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So spricht der Herr zu dem, den er gesalbt, zu Cyrus: \"Du, den ich an der rechten Hand gefaßt, um Heidenvölker vor ihn hinzuwerfen! Der Könige Hüften werde ich entgürten und Türen vor ihm öffnen, daß Pforten nicht verschlossen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ich ziehe vor dir her und werfe Wälle nieder, zertrümmre eherne Tore, ich zersprenge Eisenriegel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Ich gebe dir auch Schätze aus dem Dunkel, verborgene Kleinodien. Du sollst erkennen, daß ich, der Herr, es bin, der dich beim Namen rief, der Schutzgott Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'zugunsten meines Dieners Jakob und meines Auserkorenen, Israel, der dich beim Namen rief und einen Ehrennamen dir verlieh, obschon du mich nicht kanntest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ich bin der Herr und keiner sonst; und außer mir ist keiner Gott. Ich habe dich gegürtet, obschon du mich nicht kanntest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Vom Sonnenaufgang bis zum Abend wisse man, daß keiner neben mir vorhanden ist! Ich bin der Herr und keiner sonst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'der Licht macht, Finsternis erschafft, der Heil bewirkt und Unheil schafft. Ja, ich, der Herr, ich mach dies alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Von oben taut, ihr Himmel! Ihr Wolken gießet Segen aus! Die Erde öffne sich! Sie sollen Heil zum Reifen bringen! Aufkeime Segen allzumal! Ich, ich, der Herr, ich schaffe dies. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Wie? Hadert denn ein Topf mit seinem Töpfer und eine Scherbe mit dem Künstler, der in Ton arbeitet? Der Lehm, spricht er zu seinem Bildner: \'Was du da machst, hat keine Handhabe?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ein Wehe über den, der zu dem Vater sagt: \'Was zeugest du?\', zum Weibe: \'Was gebärest du?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So spricht der Herr, der Heilige Israels, sein Bildner: \"Ihr stellet wegen meiner Söhne mich zur Rede und gebet mir Gesetze über meiner Hände Werk?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Die Erde habe ich gemacht, die Menschen drauf erschaffen. Nur meine Hände breiteten den Himmel aus, und seinem ganzen Heer erteile ich Befehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ich habe ihn erweckt zum Heile und ebne alle seine Wege. Er soll aufs neue bauen meine Stadt und die Gefangenen mir loslassen, umsonst und unentgeltlich.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So spricht der Herr: \"Ägyptens Arbeit, Äthiopiens Handel und die Sabäer, diese hochgewachsenen Männer, sie sollen auf dich übergehn, die deinen werden! Sie folgen dir und ziehen unentwegt dahin, und vor dir niederfallend, beten sie vor dir: \'Bei dir allein ist Gott, und weiter gibt es keinen andern Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Fürwahr, Du bist ein Gott, der Schutz gewährt, ein Helfer, Du Gott Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Sie alle schämen sich und sind mit Schmach bedeckt; sie gehen schmachvoll weg, die Bildermacher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Doch Israel wird durch den Herrn befreit auf ewige Zeiten. Nicht Schmach mehr, nicht mehr Schande über euch durch alle Ewigkeiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Ja, also spricht der Herr: \"Wer da den Himmel schafft, der ist der wahre Gott. Und wer die Erde formt und macht, erhält sie auch. Nicht schuf er sie zum Ödland; zur Siedlung bildete er sie. Ich bin\'s, der Herr, und keiner sonst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nicht im geheimen habe ich geredet, im finstern Erdenwinkel, und zum Geschlechte Jakob sprach ich nicht: \'Mich sucht in\'s Leere!\' Ich bin der Herr, der Wahrheit spricht, der Richtiges verkündet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Auf! Allesamt herbei Nur näher her, der Heidenvölker Rest! Sie schleppen unverständig sich mit ihres Götzenbildes Holz und flehn zu einem Gotte, der nicht hilft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Fragt an! Herbei mit ihnen! Sie mögen alle miteinander sich beraten! Wer tat dergleichen jemals kund? Wer zeigte je dergleichen an? War ich, der Herr, es nicht? Ja, außer mir gibt\'s keinen Gott. Kein wahrer Gott und Helfer außer mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Zu mir nur wendet euch und laßt euch helfen, all ihr Erden-Enden! Denn ich bin Gott und keiner sonst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Bei mir geschworen habe ich. Nur Wahrheit kommt aus meinem Munde, nur Worte ohne Widerruf; ein jeglich Knie beugt sich vor mir, und jede Zunge schwört:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, '\'Wahrhaftig! Nur beim Herrn\', so wird man sprechen, \'ist Wahrheit und ist Kraft für mich\'. Sie kommen voller Scham zu ihm, sie alle, die einst gegen ihn geeifert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Im Herrn dagegen siegt und triumphiert die ganze Nachwelt Israels.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Gebeugt ist Bel; geduckt ist Nebo. Und ihre Götzenbilder sind den Tieren und dem Lastvieh aufgeladen, sie, die euch tragen sollten, als Last dem Vieh, dem abgematteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Geduckt, gebeugt sind sie zumal; sie können ihre Würde nimmer schützen; sie wandern selbst in die Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, '\"Hör mir zu, Jakobshaus, du ganzer Rest des Hauses Israel, ihr, die ihr seid vom Mutterleib an aufgeladen, vom Mutterschoß an aufgenommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Selbst bis in euer Alter bleibe ich derselbe, und bis zum grauen Alter trage ich. Ich hab\'s getan und hebe weiter; ich trage und behüte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Mit wem vergleicht ihr mich, wem wollt ihr mich gleichsetzen? Nach wem mich bilden, daß wir uns glichen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Die zählen aus dem Beutel Goldstücke und wägen Silber auf der Waage. Sie dingen einen Goldschmied, und dieser macht\'s zum Gott; sie bücken sich und beten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie heben ihn auf ihre Schultern und schleppen ihn, und wenn sie ihn an seinen Platz zurückstellen, dann bleibt er stehen, wo er ist, kann sich nicht von der Stelle rühren. Und ruft jemand zu ihm, erteilt er keine Antwort, befreit aus seiner Not ihn nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Bedenket dies! Errötet! Abtrünnige! Nehmt\'s zu Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Ersehet aus dem Früheren von alten Zeiten her, daß ich allein Gott bin und keiner sonst. Schutzgott, und nichts ist je mir gleich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'der ich von Anfang auch das Ende angekündigt, das Ungeschehene in der Vorzeit, der spricht: \'Mein Wille soll geschehen!\' Was mir gefällt, das schaffe ich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'der ich von Osten einen Adler rufe, aus fernem Land den Mann für meinen Plan. Kaum habe ich\'s gesagt, vollführ ich\'s auch. Wie ich\'s geplant, mach ich\'s zur Tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Verstockte! Hört auf mich, die ihr euch fern vom Heile glaubet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Ich bring mein Heil herbei, das nicht mehr ferne, und meine Hilfe wird sich nicht verzögern. Ich spende Sion Hilfe und meine Herrlichkeit an Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Herunter! In den Staub! Du Jungfrau, Babels Tochter! Setz dich zur Erde! Entthronte! Du Chaldäertochter! Man nennt dich nimmermehr \"die Feine und die Zarte\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Die Mühle nimm und mahle Mehl! Deck deinen Schleier auf! Die Schleppe hoch! Das Bein entblößt! So wate durch die Flüsse!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Dein Schoß wird aufgedeckt, und angegafft wird deine Blöße. \"Ich nehme Rache und bitte niemand um Erlaubnis.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Der uns erlöst, der \"Herr der Heerescharen\" heißt, der Heilige Israels, spricht also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, '\"Sitz ruhig hin! Ins Dunkel schleiche, du Chaldäertochter! Denn fortan nennt dich niemand mehr \'der Königreiche Herrin\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Ich hatte auf mein Volk gezürnt; die ewig Meinen hatte ich entweiht und sie in deine Hand gegeben. Kein Mitleid hattest du für sie; den Alten machtest du dein Joch gar schwer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Du sprachst: \'Ich bleibe Herrin immerdar\' und überlegtest nicht und dachtest nicht an seine Folgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Nun höre dies, Verzärtelte, die da im Sichern thront, die bei sich spricht: \'Ich bin\'s und keine sonst; ich sitze nicht als Witwe da und kenne keine Kinderlosigkeit\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Und dennoch trifft dich beides plötzlich: an e i n e m Tage Kinderlosigkeit und Witwenschaft. Sie treffen dich in ihrer ganzen Schwere, dies trotz der Menge deiner Zauberkniffe und trotz der Masse der Beschwörungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Auf deine Schlechtigkeit vertrautest du und sprachst: \'Nicht einer mich durchschaut.\' Doch deine Weisheit, deine Klugheit haben dich berückt. \'Ich bin\'s ja\', dachtest du, \'sonst keine.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Doch über dich kommt Unheil, und du weißt nicht, wie du es beschwören sollst. Dich überfällt Verderben; du kannst es nimmer bannen. Urplötzlich überkommt dich Schwindel, daß dir vergehn die Sinne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Bleib nur bei deines Bannes Sprüchen, bei deinen vielen Zauberkniffen! Du mühtest dich mit ihnen schon von Jugend an. Vielleicht kannst du dir helfen; vielleicht verscheuchst du es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Wenn du das Spiel verlorengibst trotz deiner vielen Pläne, dann mögen diese Himmelskundigen zu deiner Hilfe kommen, die nach den Sternen sehn und an den Neumonden verkünden, was dir begegnen wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Sie sind nur Stoppeln, die das Feuer frißt. Sie können sich nicht aus der Flamme retten, und das ist keine Kohlenglut zum Wärmen, kein Feuer, um davor zu sitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Das aber sind sie dir, die Zauberer. Mit ihnen hast du es von Jugend auf gehalten. Ein jeder taumelt seinem Untergange zu, und keiner steht dir bei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Dies höre, Jakobshaus! Sie, die nach Israel sich nennen, aus Judas Born entsprungen, die bei des Herren Namen schwören, die Gottheit Israels im Munde führen, doch unaufrichtig, ohne jedes Recht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'An sie kam aus der heiligen Stadt der Ruf; doch sie erfanden einen Vorwand gegenüber dem Gott Israels, der \"Herr der Heerscharen\" genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '\"Längst habe ich das Frühere verkündigt; aus meinem Munde ist\'s gekommen. Ich tat es kund; ich ließ es plötzlich kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Denn weil ich wußte, daß du harten Sinnes bist, dein Nacken eine Eisensehne und deine Stirne Erz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'so tat ich alles dir von alten Zeiten kund. Bevor es eintraf, ließ ich dich drum wissen, daß du nicht sagen könntest: \'Mein Götze hat\'s getan, mein Schnitzbild und mein Gußbild es gefügt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Du hast dies alles doch gehört. Müßt ihr\'s nicht selbst bekennen? Von jetzt an aber offenbare ich dir Neues, Verborgenes, das du nicht weißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Jetzt ist es erst im Werden, und früher war es nicht. Vor dieser Zeit vernahmst du nichts davon, daß du nicht sagst: \'Mir war\'s bekannt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Nein! Nichts hast du gehört und nichts gewußt; dein Ohr hat\'s früher nicht vernommen. Ich wußte, wie du treulos warst, und treulos hieß man dich vom Mutterleibe an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Um meines Namens willen hemme ich den Zorn, um meiner Ehre willen, und zügle ihn zu deinem Besten, um dich nicht zu vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Ich habe dich geläutert; du warst kein reines Silber; ich habe in des Leidens Ofen dich geprüft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Um meinetwillen, meinetwillen will ich\'s tun. Wie würde sonst gelästert werden! Ich gebe meine Ehre keinem andere preis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Hör zu, Jakob, und Israel, du mein Berufener! Ich bleibe stets derselbe. Der Erste bin ich und der Letzte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'hat meine Hand die Erde doch gegründet und meine Rechte ausgespannt den Himmel; ich rufe ihnen, und sie stehen still.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Zuhauf, ihr alle hört! Wer unter ihnen tat dergleichen kund? \'Der, den der Herr hat lieb, vollstreckt an Babel seinen Willen. Sein Arm tut dies an den Chaldäern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ich, ich allein nur habe es gesagt. Ich rufe ihn und führe ihn, daß ihm sein Weg gelinge. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Heran zu mir! Vernehmet dies! Von Anfang an sprach ich nicht insgeheim. Wenn etwas ward, war ich dabei.\" So hat mich denn der Herr, der Herr, gesandt, mit seinem Geiste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So spricht der Herr, dein Retter und der Heilige Israels: \"Ich bin dein Gott, der Herr, der dich belehrt zu deinem Nutzen, dich leitet auf dem Wege, den du gehen sollst:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Wenn du nur achtetest auf mein Gebot, dann würde wie ein Strom dein Glück, dein Wohlstand gleich den Meereswellen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'und dein Geschlecht dem Sande gleich, wie seine Körner deine Leibesfrucht. Sein Name würde nimmer ausgerottet, nie vertilgt vor meinem Angesicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Heraus aus Babel! Fort aus Chaldäa! Mit Jubelschall verkündet\'s! Laßt es hören! Bis zu dem Erdenrand laßt es erschallen! Sprecht: \"Der Herr hat Jakob, seinen Knecht, erlöst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Sie dürsten in den Wüsten nicht, durch die er sie geleitet. Er läßt aus Felsen Wasser ihnen rieseln. Er spaltet Felsen, und es rauschen Wasser. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, '\"Kein Friede\", spricht der Herr, \"für Frevler!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Ihr Inseln, hört auf mich! Von fern her lauscht, ihr Nationen! Der Herr hat mich vom Mutterleib berufen, im Mutterschoße meinen Namen schon genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Er machte meinen Mund zu einem scharfen Schwert; im Schatten seiner Hand verbarg er mich. Er machte mich zu einem blanken Pfeile, versteckte mich in seinem Köcher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, '\"Du sollst\", sprach er, \"mein Diener sein, und Israel soll\'s sein, an dem ich mich durch dich verherrliche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Ich aber mußte sprechen: \"Umsonst hab ich mich abgemüht und meine Kraft an Nichtigkeiten und an Dunst vertan. Und doch steht bei dem Herrn mein Recht, bei meinem Gott mein Lohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Darauf erwiderte der Herr, der mich vom Mutterschoß für sich zum Knecht erzog, um Jakob wiederum zu sich zu bringen und Israel zu sich zu sammeln. Ich bin ja in des Herren Augen vieles wert, und meine Stärke ist mein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Er sprach: \"Zuwenig wäre es dafür, daß du mein Knecht geworden, wärst du nur so mein Diener, daß du die Stämme Jakobs wiederherstellen und Israels Geschlecht heimführen würdest. Ich mache dich vielmehr zum Licht der Heidenvölker, auf daß mein Heil bis an der Erde Ende reiche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So spricht der Herr, der Retter Israels, sein Heiliger, von dem, den alle Welt verachtet, vom Spott der Heidenvölker, vom Knecht der Wüteriche: \"Könige stehen auf, wenn sie es schauen, und Fürsten fallen nieder, des Herren, des getreuen, wegen, des Heiligen Israels, der dich erwählt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'So spricht der Herr: \"Ist mir\'s gefällig, so bewillige ich dir Gehör und helfe dir, ist\'s Zeit zur Hilfe. Ich schütze dich und mache dich zum Ruhm des Volkes. So helfe ich dem Lande auf, besiedle wieder öde Plätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Ich sage zu den Häftlingen: \'Heraus!\' - zu denen, die im finstern Kerker: \'Kommt ans Licht!\' An Straßen sollen sie die Weiden finden, auf allen Hügeln ihre Trift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nicht hungern werden sie, nicht dürsten. Nicht sticht sie Glutwind, nicht die Sonne. Denn ihr Erbarmer leitet sie; zu Wassersprudeln führt er sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Ich mache gangbar alle meine Berge, und meine Straßen heben sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Aus weiter Ferne kommen sie. Die da vom Norden, die vom Westen und diese aus Siniterland.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Ihr Himmel jauchzt! Frohlocke, Erde! Ihr Berge brecht in lauten Jubel aus! Der Herr nimmt an sich seines Volkes, erbarmt sich seiner Armen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Doch Sion spricht: \"Der Herr hat mich verlassen; der Herr hat mich vergessen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Vergißt denn eine Mutter ihres Kindes, des eigenen Leibessprossen die Gebärerin? Und könnten Mütter sie vergessen, so vergesse ich dich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'In meinen Händen trage ich dich eingezeichnet, und deine Mauern stehen allezeit vor mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Es eilen deine Kinder schneller her als die, die dich verlassen, als die, die dich verwüstet und vernichtet haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Erhebe ringsum deine Augen! Schau! Sie alle kommen dir zuhauf. So wahr ich lebe\" - ein Spruch des Herrn -, \"sie alle legst du dir wie ein Geschmeide an, gleich einem Brautschmuck um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Denn deine Trümmer, deine Öden, dein zerschunden Land, zu enge wird\'s für die, die Wohnung suchen, wenn deine Todfeinde erst fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Vor deinen eignen Ohren sagen dann die Kinder, dir in deiner Einsamkeit geboren: \'Der Platz ist mir zu eng. Rück weg, daß ich hier auch noch sitzen kann!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Du fragst dich dann: \'Wer hat sie mir geboren? Ich war doch kinderlos und unfruchtbar, gefangen und verbannt! Wer hat mir diese aufgezogen? Ich war allein noch übrig. Was ist\'s mit ihnen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Dann spricht der Herr, der Herr, also: \"Bis zu den Heidenvölkern hin erhebe ich die Hand und richte unter den Nationen meine Flagge auf, damit sie im Gewandbausch deine Söhne bringen, herbei auf ihren Schultern deine Töchter tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Und deine Wärter sollen Könige und ihre Fürstinnen für dich die Ammen sein. Sie fallen auf ihr Angesicht zur Erde vor dir nieder, den Staub von deinen Füßen küssend. Dann wirst du sehn, daß ich der Herr bin, und daß nicht zuschanden werden, die auf mich vertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kann denn der Raub dem Starken abgejagt, dem Wüterich der Fang entrissen werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'O ja. So spricht der Herr. \"Dem Starken kann der Fang entrissen, dem Wüterich die Beute abgenommen werden. Wer mit dir kämpft, mit diesem kämpfe ich; ich selber rette deine Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Ich gebe deinen Peinigern ihr eigen Fleisch zu essen. Sie müssen sich an ihrem eignen Blut berauschen wie am Wein, und alle Welt soll wissen, daß ich, der Herr, dein Retter bin, der Starke Jakobs, dein Erlöser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So spricht der Herr: \"Wo ist nur eurer Mutter Scheidebrief, mit dem ich sie verstoßen hätte? Wer ist mein Gläubiger, an den ich euch verkauft? Für eure Missetaten wurdet ihr verkauft; um eurer Sünden willen wurde eure Mutter fortgeschickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Warum war niemand da, als ich erschien? Warum gab niemand Antwort, als ich rief 2 Ist meine Hand zu kurz zum Helfen? Bin ich zu schwach zum Retten? Mit meinem Machtwort trockne ich das Meer aus, in Steppen wandle ich die Ströme, und ihre Fische faulen, weil das Wasser mangelt, und sterben hier vor Durst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Den Himmel kleide ich in Düsternis und hüll\' ihn in ein Bußgewand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Der Herr, der Herr verlieh mir eine Jüngerzunge, damit den Müden ich durch Zuspruch anzuregen wüßte. An jedem Morgen weckt er mich durch\'s Ohr, daß ich aufhorche wie ein Schüler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Der Herr, der Herr macht offen mir das Ohr; ich widerstrebe nicht und weiche nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Den Schlagenden biet ich den Rücken dar und meine Wangen meinen Quälern, mein Angesicht verhüll ich nicht vor Schmähung und Bespeiung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Der Herr, der Herr steht selbst mir bei; ich werde deshalb nicht zuschanden. Drum mache ich mein Antlitz kieselgleich; ich weiß, ich werde nicht zuschanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Der mir zu meinem Recht verhilft, ist nahe. Wer ist\'s, der mit mir streiten will? So treten wir zusammen vor. Wer ist\'s, der mich verklagen will? Er trete her zu mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Der Herr, der Herr verteidigt mich. Wer könnte mich bezichtigen? Fürwahr! Sie allesamt zerfallen, den Kleidern gleich, die Motten fressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Ist einer unter euch, der vor dem Herrn sich fürchtet und noch auf seines Dieners Stimme hört? Nur einer, der des Herren Namen traut und sich auf seinen Gott verläßt, wenn er im Finstern wandelt und keinen Lichtstrahl sieht? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Ihr alle wollt euch selber Feuer schlagen, um Fackeln anzuzünden. So wandelt denn bei eures Feuers Licht und bei den Fackeln, die ihr angezündet! Von meiner Hand wird euch dies zubereitet: Ihr müßt an einem Ort der Qualen wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, '\"Horcht ihr doch wenigstens auf mich, die ihr dem Heil nachjagt, die ihr den Herren sucht! Schaut auf den Felsen hin, aus dem ihr seid gehauen, und auf den Born, aus dem ihr seid geflossen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Schaut hin auf euren Vater Abraham, auf Sara, eure Mutter! Denn ihn nur habe ich berufen und ihn gesegnet und gemehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'So sei der Herr auch Sion wieder gnädig, erbarme sich all seiner Trümmer, und seine Öde mache er zu einem Paradies und seine Wüste zu des Herren Garten, in dem sich Lust und Wonne finden und Dank und Liederklänge! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, '\"Ihr Völker, horcht auf mich, und ihr Nationen, hört mich an! Von mir geht Weisung aus, und meine Wahrheit mache ich zum Licht für Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Mein Heil kommt näher; meine Hilfe zieht schon aus. Denn meine Arme bringen Völker zu dem Recht; die Inseln harren schon auf mich, und sie vertraun auf meinen Arm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Zum Himmel hebet eure Augen auf! Und schauet auf die Erde unten! Zerflattert auch der Himmel gleich dem Rauch, zerfällt die Erde wie ein Kleid, auf gleiche Weise auch ihre Bewohner, so bleibt doch meine Hilfe ewiglich bestehen. Mein Heil wird nicht zunichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'So hört mir zu, die ihr das Rechte kennt! Du Volk, das meine Lehre in dem Herzen trägt! Habt keine Angst vor Menschenschimpf! Zagt nicht vor ihrem Hohn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Wie ein Gewand frißt sie die Motte; wie Wolle wird die Schabe sie verzehren. Mein Heil dagegen bleibt in Ewigkeit bestehn und meine Hilfe bis zum äußersten Geschlecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Hervor! Hervor! Leg Kraft an, Arm des Herrn! Hervor, wie einstens in der Urzeit Tagen! Bist Du\'s nicht, der das Ungetüm zerhauen, den Drachen einst durchbohrt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Bist Du\'s nicht, der das Meer einst ausgetrocknet, das Wasser jener großen See? Der durch des Meeres Tiefe eine Straße bahnte, Erlöste durchzuführen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'So mögen auch des Herrn Erkaufte wiederkehren nach Sion unter Jubelrufen, auf ihrem Haupte ewige Freude. Freude und Wonne mögen ihnen das Geleite geben, und weithin fliehen Schmerz und Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, '\"Ich selber bin es, der euch tröstet. Wer bist du doch, daß du vor Menschen, sterblichen, dich fürchtest? Vor Menschenkindern, die zu Grase werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Du dachtest nimmer an den Herrn, den Schöpfer, der einst den Himmel ausgespannt, der Erde Grund gelegt. Du bebtest vielmehr allezeit den ganzen Tag vor des Bedrückers Grimm, als hätte er schon zum Vertilgen Macht gehabt. Wo ist nun des Bedrückers Grimm?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Der Kluge ist bereit für die Befreiung; dann stirbt er nicht im Kerker, und nimmer mangelt ihm das Brot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Ich bin der Herr, dein Gott, der selbst das Meer zur Ruhe zwingt, wenn seine Wellen brausen, der \'Herr der Heeresscharen\' heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Ich lege mein Versprechen dir in deinen Mund, mit meiner Hand dich deckend, ich werde einen andern Himmel schaffen und eine andere Erde gründen und dann zu Sion sprechen: \'Mein Volk bist du.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Empor! Empor! Auf! Du Jerusalem, das aus des Herren Hand den Becher seines Zorns getrunken, den schaumgefüllten Taumelbecher bis zum letzten Tropfen ausgeschlürft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Kein Führer ist ihm mehr geblieben von all den Söhnen, die\'s geboren, keiner, der\'s an seiner Hand genommen, von all den Söhnen, die es großgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Getroffen hat dich Zwiefaches: Wer nur hat Leid um dich getragen? Verheerung und Vernichtung, Hungersnot und Schwert. Wer spricht zu dir ein Wort des Trostes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Berauscht an allen Straßenecken liegen deine Söhne, wie Antilopen in dem Netz, gefüllt vom Grimm des Herrn, von deines Gottes Zorne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'So höre dies, du Ärmste, du Trunkene, doch nicht von Wein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So spricht der Herr, Herr und Gott, der für sein Volk jetzt kämpft: \"Ich nehme dir den Taumelbecher aus der Hand; denn meines Grimmes schäumenden Pokal sollst du nicht weiter trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ich gebe diesen deinen Quälern in die Hand, die dir befehlen: \'Beuge dich, daß wir darüber gehen\', so daß du deinen Rücken mußt zum Bogen machen, zur Straße für die Wandersleute.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Auf! Sion! Auf! Dein Festkleid angelegt! In deine Prachtgewänder hülle dich, Jerusalem, du heilige Stadt! Kein Unbeschnittener, kein Unreiner betritt dich fernerhin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Schüttle den Staub ab! Auf! Gefangenes Jerusalem! Lös dir die Fesseln deines Halses, gefangene Sionstochter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Ja, also spricht der Herr: \"Umsonst seid ihr verkauft; so werdet ihr auch unentgeltlich freigegeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Denn also spricht der Herr, der Herr: \"Mein Volk zog damals nach Ägypten und wollte dort nur gasten, Assur bedrückte es um nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Nun aber, wie geschieht mir hier?\" Ein Spruch des Herrn: \"Mein Volk ist ohne Grund gefangen, und seine Fürsten klagen wehe.\" Ein Spruch des Herrn: \"Mein Name wird noch immerfort gelästert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Drum soll mein Volk es noch erfahren, wie ich heiße, jawohl an diesem Tag, daß ich es bin, der da gesagt: \'Seht! Ich bin da.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Wie hochwillkommen eilen über das Gebirge des Freudenboten Füße, der Frieden ausruft, Glück verkündet und Heil verlauten läßt, der Sion meldet: \"Dein Gott ist wieder König!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Horch! Deine Wächter rufen laut; sie jubeln alle. Sie sehen ganz genau den Herrn zurück nach Sion kehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Jauchzt auf! Im Chore jubelt, Trümmer von Jerusalem! Der Herr erbarmt sich seines Volkes, befreit Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Der Herr entblößt den heiligen Arm vor aller Heidenvölker Augen. Alle Enden der Erde schaun die Hilfe unseres Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Hinweg! Hinweg! Heraus von da! Berührt nichts Unreines! Zieht fort aus seiner Mitte! Doch reinigt euch, die ihr des Herrn Gefäße tragt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Doch euer Auszug sei nicht eilig und eure Reise nicht fluchtartig! Der Herr geht euch voran, und eure Nachhut bildet wieder Israels Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Fürwahr! Mein Knecht hat Glück; groß wird er, hochgeachtet, hochgeehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Wie viele seinetwegen sich entsetzten, - so sehr entstellt war er, so wenig sah er andern Menschen ähnlich, so wenig andern Menschenkindern gleich -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'so setzt er viele Heidenvölker über sich in Staunen, und Könige verschließen ihren Mund. Denn nie Erzähltes schauen sie, und nie Gehörtes hören sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Wer glaubte unserer Botschaft? Wem wird der Arm des Herrn enthüllt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Er wächst für sich so, wie ein Reis, so, wie aus dürrem Erdreich eine Wurzel, ist ohne Schönheit und Gestalt; er zieht auf sich nicht unsere Blicke; ist ohne Ansehn, aller Reize für uns bar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Er ist verachtet und von aller Welt verlassen, ein Schmerzensmann, dem Krankheit wohlbekannt, verachtet so wie einer, der sein Angesicht vor uns verhüllen muß. Wir rechnen nimmermehr mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Und dennoch trägt er unsere Leiden, erduldet unsere Schmerzen, wiewohl er uns, als ein von Gott Getroffener, nur Schläge zu verdienen scheint und Qualen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'So ist er denn durch unsre Schuld zerfleischt, durch unsere Verschuldung so zerschlagen. Zu unsrer Wohlfahrt nur fällt er der Züchtigung anheim, durch seine Striemen wird uns Heilung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wir sind wie Schafe allesamt verlaufen; ein jeder folgt nur seinem Wege. So läßt der Herr all unsere Schuld ihn treffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Er wird mißhandelt, beugt sich nieder, tut den Mund nicht auf gleich einem Lamm, das man zur Schlachtbank führt. Gleich einem Mutterschaf, verstummt vor seinen Scherern, tut er den Mund nicht auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Man schleppt ihn aus Gefängnis und Gericht zum Tode. Wer überlegt sein Schicksal? Aus der Lebendigen Land soll er gerissen werden. Aus meines Volkes Schuld fließt ihm das Unheil zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Schon gibt man ihm sein Grab bei Missetätern und seine Grabstätte bei Armen, obwohl er nicht Gewalttat ausgeübt und kein Betrug in seinem Mund gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Der Herr verwundet ihn; in Leiden wissen will er ihn, daß, hat er erst gebüßt, er Nachwuchs sehe, lange lebend, und daß durch ihn des Herren Wunsch gelinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Nach seiner Seele Leid wird er, erfüllt mit seiner Kenntnis, sie genießen. Selbst glücklich, macht mein Diener viele glücklich, nachdem er ihre Schuld getragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Drum mache ich ihn auch zum Herren über Große und gebe ihm zur Beute Mächtige, weil er dem Tod sich stellen, sich unter Missetäter zählen läßt. Er, der die Sünde vieler trägt, tritt noch für Übeltäter ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Du Unfruchtbare, jauchze, die du nicht geboren! Brich aus in Jubel, jauchze du, die nicht in Wehen hat gelegen! \"Denn der Verstoßnen Kinderzahl ist größer als jene der Vermählten.\" - So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Mach weit den Raum in deinem Zelte! Man spanne weiter deiner Wohnungen Behänge und spare nicht! Verlängere deine Stricke, schlage fester deine Pflöcke ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Nach rechts und links dehnst du dich aus, und Heidenvölker unterjocht sich dein Geschlecht, besiedelt wieder Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Sei ohne Furcht! Du brauchst dich nicht zu schämen. Sei frohen Muts! Du brauchst nicht zu erröten. Die Schande deiner Kinderlosigkeit vergissest du; der Schande deiner Witwenschaft gedenkst du nimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Dein Gatte ist ja der, der dich erschaffen; \"der Heeresscharen Herr\" heißt er. Der Heilige Israels ist dein Befreier; \"Gott aller Welt\" heißt er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Wie ein verlassnes, tiefbetrübtes Weib ruft dich der Herr zurück. \"Ein Weib der Jugendliebe, kann es denn verworfen werden?\" So spricht dein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '\"Nur einen kleinen Augenblick verließ ich dich; mit starker Liebe hole ich dich wieder ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'In großem Zorn verbarg ich einen Augenblick mein Angesicht vor dir. Ich hege nunmehr dich mit ewiger Zärtlichkeit\", so spricht, der dich erlöst, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '\"Wie in des Noë Tagen tu ich; so, wie ich damals schwur: \'Nie sollen Noës Fluten die Erde wieder überschwemmen\', so schwöre ich, nie wieder dir zu grollen, nie wieder dich zu schelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Selbst Berge mögen weichen, Hügel wanken, doch meine Liebe weicht nicht mehr von dir, nie wieder wankt mein Friedensbund\", so spricht der Herr, der dich so zärtlich liebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '\"Du Arme, Sturmgepeitschte, Trostberaubte! Ich will in Malachit einbetten deine Steine und in Saphire deine Grundfesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Ich mache aus Rubinen deine Zinnen und deine Tore aus Karfunkel und deinen ganzen Wall aus Edelstein. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Und alle, die dich bauen, werden von dem Herrn selbst unterrichtet, und groß ist die Geschicklichkeit bei denen, die dich bauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Kunstfertig, fest erbaut, so wisse dich von jedem Überfalle fern! Du brauchst ihn ja nicht mehr zu fürchten, auch nicht den Untergang. Er darf dir nicht zu nahe kommen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Wer angreift, wird von mir vernichtet. Wer mit dir kämpft, fällt deinetwegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Ich schuf den Schmied, der in das Kohlenfeuer bläst und der nach seiner Weise Waffen schmiedet. Ich selber schaffe auch das Werkzeug zur Vernichtung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Kein Kriegsgerät, gen dich geschmiedet, hat Glück, und jede Zunge, die im Streit ums Recht dich anficht, kannst du widerlegen. Das ist das Erbteil für des Herren Knechte und das, worauf sie bei mir Anspruch haben.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, '\"Auf! All ihr Dürstenden, geht hin zum Wasser! Auch ihr, die ihr kein Silber habt! Auf! Kaufet, esset! Auf! Kauft ohne Geld umsonst jetzt Wein und Milch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Was zahlt ihr Geld für das, was keine Nahrung ist, und was ihr euch gespart, für das, was nimmer sättigt? Auf mich nur hört, dann habt ihr feine Kost und labt euch an dem Fett.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'So gönnt mir euer Ohr und kommt zu mir! Hört zu und euer Geist, er lebe wieder auf! - Ein ewig Bündnis schließe ich mit euch, gleich Davids Gnaden, die für immer währen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Fürwahr! Zu einem Völkerrichter setze ich ihn ein, zum Völkerherrscher und Gebieter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Fürwahr! Auch du rufst Heidenvölker her, die du nicht kennst, und Heidenvölker, die von dir nichts wissen. Sie eilen zu dir her, des Herren, deines Gottes, wegen, dem Heiligen Israels zu Ehren, weil er dich verherrlicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Suchet den Herrn, da er sich finden läßt! Ihn ruft, da er so nahe ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Der Frevler lasse sein Beginnen, der Mann des Unrechts seine Pläne! Zurück zum Herrn, daß er sich seiner wiederum erbarme, zu unserm Gott; denn im Vergeben ist er reich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, '\"Meine Gedanken sind nicht eurige Gedanken. Nicht eure Wege meine Wege.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '\"Soviel der Himmel höher als die Erde, sind meine Wege höher als die eurigen, meine Gedanken höher als eure Gedanken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Wie Schnee und Regen vom Himmel fallen und nicht mehr dorthin kehren, vielmehr die Erde tränken, befruchten und mit Grün bedecken, dem Sämann Samen geben und Brot dem Essenden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'so ist\'s mit meinem Wort, das meinen Mund verläßt. Nicht leer kehrt es zu mir zurück, es habe denn getan, was ich gewünscht, mit Glück vollführt, wozu ich\'s ausgesandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Zieht aus mit frohem Mut! Ihr werdet ja in Sicherheit geleitet. Die Berge und die Hügel jubeln vor euch her, des Feldes Bäume alle klatschen in die Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Zypressen wachsen statt des Dorngestrüpps und statt der Nesseln Myrten. - Ein Denkmal ist es für den Herrn und eine ewige Inschrift, die nicht schwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So spricht der Herr:\"Befolgt, was recht ist! Und tut,was vorgeschrieben! Denn meine Hilfe ist dem Anbruch nah, mein Heil will sich jetzt offenbaren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Heil sei dem Menschen, der so handelt, dem Menschenkind, das dabei bleibt, das seinen Sabbat hält, ihn nicht entweiht, und seine Hand bewahrt vor Übeltat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Der Fremdling sage nicht, der sich dem Herrn anschließen will: \"Der Herr schließt mich aus seinem Volke sicher aus\"! Auch sage der Entmannte nicht: \"Ich bin ein dürrer Baum\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Denn also spricht der Herr:\"Entmannten, die meine Sabbattage feiern und wählen, was mir wohlgefällt, und fest an meinem Bunde halten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'auch diesen geb ich einen Platz in meinem Haus, in meinen Mauern und einen Namen trefflicher als Söhne und als Töchter. Ich gebe ihnen einen ewigen Namen, der nimmermehr erlischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Die Fremden, die sich an den Herrn anschließen, um ihm zu dienen und um des Herren Namen Liebe zu erweisen und Knechte ihm zu sein, falls sie den Sabbat halten, ihn nicht entweihen und fest an meinem Bunde hängen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'laß ich betreten meinen heiligen Berg und heiße sie in meinem Bethaus hochwillkommen. Ich nehme ihre Brand- und Schlachtopfer auf meinem Altar wohlgefällig an. Mein Haus soll \'aller Nationen Bethaus\' heißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Ein Spruch des Herrn, des Herrn, der Israel aus der Zerstreuung sammelt: \"Zu ihnen, die ich schon gesammelt, will ich noch andere hinzuversammeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Ihr wilden Tiere insgesamt! Jetzt kommt zum Fraß herbei! Ihr Tiere alle aus dem Wald!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'All seine Wächter sind ja blind; sie passen nimmer auf, sind alle stumme Hunde, die nicht bellen mögen. Sie träumen, liegen ausgestreckt und schlafen gern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Als heißhungrige Hunde sind sie nicht zu sättigen; als Hirten wissen sie von keiner Achtsamkeit. Sie alle sehen nur auf ihren Nutzen, auf seinen Vorteil jeder bis zum letzten Mann:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '\"Herbei! Ich hole Wein. Wir wollen Bier zusammen zechen! Und morgen soll\'s wie heute gehn, großartig über alle Maßen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Der Fromme stirbt, und niemand nimmt\'s zu Herzen. Die guten Männer sterben aus, und keiner merkt darauf, daß vor der Bösen Zeit der Fromme stirbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Er geht zum Frieden ein und ruht in seiner Lagerstätte als Redlicher von tadellosem Wandel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Doch ihr, ihr tretet vor, ihr Hexensöhne, du Brut der Ehebrecher und der Dirnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Wen höhnt ihr? Gegen wen reißt euren Mund ihr auf und streckt die Zunge aus? Seid ihr nicht eine Sündenbrut, ein treuloses Geschlecht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Die ihr in Brunst kommt unter Eichen, unter jedem grünen Baume; die ihr an Bächen Kinder schlachtet und unter Felsenhängen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Die glatten Kiesel aus den Bächen bilden dein Geschick; sie dienen dir zum Losen. Du gießest Opferwein zu ihren Ehren aus, bringst ihnen Speiseopfer dar. Damit soll ich mich wohl zufriedengeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Auf hohen, steilen Bergen schlägst du dein Ruhelager auf. Du steigst hinauf, um dort Schlachtopfer darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Und hinter Tür und Pfosten stellst du dein Zeichen auf. Mir untreu, deckest du dich auf, besteigst dein ausgebreitet Bett, bedingst für dich von ihnen ihres Lagers Liebe, und erfreust dich ihrer Liebesgunst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Du schaust nach Öl dich für den Moloch um, häufst deine Wohlgerüche an, schickst deine Boten in die Ferne und sendest sie bis in das Totenreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Obgleich ermüdet durch dein langes Treiben, bekennst du nicht. \"Vergeblich!\" Du findest neue Stillung deiner Gier; deshalb wirst du nicht matt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Wovor ist dir denn bange? Worum bist du besorgt, daß du so untreu wirst und meiner nicht gedenkst und keine Acht mir schenkst? Nicht wahr, ich schweige, zeige mich nicht offen; so fürchtest du dich nicht vor mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ich aber künde dir, daß dieses Handeln, das dir recht erscheint, und deine Werke dir nicht helfen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Dich mögen die erretten, die du zusammenbringst, wenn du zu heulen hast! Sie alle aber führt ein Lüftchen in die Weite und ein Windhauch trägt sie fort. Nur wer auf mich vertraut, ererbt das Land und darf auf meinem heiligen Berge wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Ich rufe: \"Auf! Nun bahnet, bahnet, ebnet jetzt den Weg! Und räumet allen Anstoß meinem Volke aus dem Wege!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'So spricht der, dessen Name ist \"der Hohe, der Erhabene, der Ewiglebende, der Heilige\": \"Ich wohne hoch und heilig; doch bin ich auch bei den Bedrückten und Demütigen, um so den Geist der Demutsvollen zu beleben und zu beleben der Gedrückten Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Nicht immer will ich streiten, nicht auf die Dauer grollen, weil sonst der Geist vor mir verschmachtete, und ich erschaffe doch die Lebensgeister.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Ich zürne ihm ob seiner frevelhaften Gier und strafe es mit abgewandtem Angesicht und grolle, weil es störrisch seinen Lüsten folgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Ich sehe diese seine Wege, und dennoch wünsche ich, ihm wohlzutun, ihm Ruh zu gönnen, Trost zu spenden, ihm selbst und seinen Trauemden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Der Lippen Ruf laß ich ins Dasein treten für Ferne und für Nahe: Friede, Friede.\" So spricht der Herr: \"Ich heile ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Die Bösen aber gleichen einem aufgewühlten Meer, das nicht zur Ruhe kommt und dessen Wasser Kot und Schlamm aufwühlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, '\"Kein Friede\", spricht mein Gott, \"für Gottlose!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '\"Ruf ungehemmt aus vollem Halse! Posaunen gleich erhebe deine Stimme! Vermelde meinem Volke seinen Frevel, dem Hause Jakobs seine Sünden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Zwar fragen sie mich Tag für Tag und möchten meine Wege gerne kennen. Als wären sie ein Volk, das täte, was da recht, und die Gesetze seines Gottes nie verließe, so fordern sie von mir Behandlung, die gerecht sein soll verlangen eine göttliche Kundgebung:\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '\'Wozu nur fasten wir? Du achtest nicht darauf. Kasteien uns? Du merkst es nicht.\' Seht! Fastet ihr, dann tut ihr nur, was euch gefällt. Ihr hetzet alle eure Arbeitsleute ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Bei Streit und Zanken fastet ihr, beim Dreinhaun mit der frevlen Faust. Ihr solltet vorerst nicht so fasten. Sonst hört man euren Lärm sogar im Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Soll etwa das ein Fasttag sein, wie ich ihn liebe, wenn jemand leibliche Genüsse sich versagt und seinen Kopf wie Schilf läßt hängen und sich auf rauhes Tuch und Asche bettet? Ja, willst du das ein Fasten heißen und einen Tag, dem Herrn gefällig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ist nicht erst das ein Fasten, wie ich es liebe: des Unrechts Bande öffnen, des Joches Knoten lösen, Geknechtete befreien und daß du jeglich Joch zertrümmerst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Nicht das: den Hungrigen dein Brot mitbrechen und obdachlose Arme in dein Haus einführen, und siehst du einen nackt, daß du ihn kleidest und dich nicht deinem Fleisch entziehst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Dann bricht dein Licht hervor wie Morgenrot, und schnell vernarben deine Wunden. Dein Heil zieht vor dir her, und deine Nachhut ist die Herrlichkeit des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Du rufst; der Herr gibt Antwort. Du schreist um Hilfe, und er spricht: \'Ich bin schon da.\' Entferne nur von dir Bedrückung, den abgefeimten Trug, das Unheilreden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Und teilst du mit dem Hungrigen dein Brot, und sättigst du den Schmachtenden, dann strahlt in Dunkelheit dein Licht, und deine Finsternis wird gleich dem Mittag hell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Beständig leitet dich der Herr und stillt in dürren Landen deinen Hunger, und dein Gebein füllt er mit Mark. Du gleichst dann einem Garten, wohlgetränkt, und einem Wasserborne, unversieglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Der Vorzeit Trümmer bauen deine Leute auf: Grundsteine legst du für die spätesten Geschlechter. Du heißt \'Rissevermaurer\', heißt \'der Pfade Neubeleber\'. - \'Für den Sabbat\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Wenn du zurückhältst deinen Fuß des Sabbats wegen und nicht an meinem heiligen Tag Geschäfte treibst, und wenn du eine Lust den Sabbat nennst und ehrenwert den, der dem Herrn geheiligt, und ehrst ihn dadurch, daß du keine Gänge machst, nicht dein Geschäft betreibst und nicht Verträge schließest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'dann hast du deine Freude an dem Herrn. Auf Landes Höhen lasse ich dich wandeln, ich gebe dir das Erbe deines Vaters Jakob.\" - Gesprochen hat\'s der Mund des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Der Arm des Herrn ist nicht zu kurz zum Helfen; sein Ohr ist nicht zu taub zum Hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Nur eure Missetaten trennen euch und euren Gott. Nur eure Sünden zwingen ihn, vor euch das Antlitz zu verhüllen, um euch nicht anzuhören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Denn eure Hände sind mit Blut befleckt, mit Übeltaten eure Finger, und eure Lippen reden Trug, und eure Zunge flüstert Unerlaubtes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Gerechterweise klagt kein Mensch, und niemand ist, der ehrlich sich verteidigt. Man baut auf Trug und redet falsch, und mit Gewalttat geht man schwanger und zeugt dann Unheil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Sie brüten Basiliskeneier aus und weben Spinngewebe. Wer von den Eiern ißt, muß sterben; als Otter quillt das Ausgebrütete hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Zum Kleid taugt ihr Gewebe nicht; mit ihrer Arbeit kann man sich nicht decken. Denn Unheilswerk sind ihre Werke; Gewalttat ist in ihren Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Zum Bösen rennen ihre Füße und eilen, Blut der Unschuld zu vergießen. Und ihre Pläne sind nur Unheilspläne, nur Stoß und Sturz auf ihren Bahnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Ein Friedensweg ist ihnen unbekannt; auf ihren Pfaden ist kein Recht. Sie bahnen krumme Steige sich; wer sie betritt, weiß nichts von Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Drum bleibt das Richtige uns fern; kein Glück wird uns zuteil. Jetzt hoffen wir auf Licht; doch bleibt es finster; auf Lichtstrahlen, jedoch im Dunkeln wandeln wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Wir tappen wie die Blinden nach der Wand; wie ohne Augen tasten wir. Am hellen Mittag straucheln wir, als ob es Dämmerung wäre, und in der Dunkelheit sind wir wie Tote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Wir murren alle wie die Bären und gurren seufzend wie die Tauben. Wir harren auf das Richtige, doch fort bleibt es; auf Glück, fern bleibt es uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Denn unsre Missetaten stehn in großer Zahl vor Dir, und unsre Sünden zeugen gegen uns. Ja, unsre Missetaten stehen neben uns, und unsere Sünden kennen wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Abfall, Untreue an dem Herrn, Aufgabe der Nachfolge unseres Gottes! Wir raten zu Gewalt und Abfall; mit Bosheit gehn wir schwanger und sinnen recht mit Fleiß auf trügerische Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Das Recht zieht sich zurück, und die Gerechtigkeit steht ferne. Die Wahrheit kommt auf freiem Platz zu Fall, und Biedersinn darf sich nicht zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Vermißt wird Redlichkeit, und vorenthalten bleibt das Bösesmeiden. Dies sieht der Herr, und ihm mißfällt, daß nirgends Recht zu finden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Er sieht, kein rechter Mensch ist da, und staunt darüber, daß kein Mensch vermittelt. Da hilft ihm denn sein eigner Arm; sein Beistand ist die eigene Gerechtigkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Gerechtigkeit sein Panzer! Der sieggewohnte Helm auf seinem Haupt! Der Rache Kleid sein Alltagskleid! Sein Mantel Eiferzorn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Drum nach Verdienst vergilt er nunmehr. Glutzorn seinen Widersachern! Vergeltung seinen Feinden! Vergeltung übt er also an den Inseln:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Den Ruhm des Herrn erschauen die im Westen und die im Osten seine Herrlichkeit, wenn er erscheint, dem Strome gleich, der aufschäumt, hergejagt vom Sturm des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, '\"Für Sion aber kommt ein Retter, für die in Jakob, die von Sünden lassen.\" - Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '\"Nur dies ist die Bedingung, die ich ihnen mache\", so spricht der Herr: \"Mein Geist, der auf dir ruht, und meine Worte, dir in den Mund gelegt, sie dürfen nicht aus deinem Munde weichen und nicht von deiner Kinder Munde und nicht von deiner Enkelkinder Munde\", so spricht der Herr, \"von nun an bis in Ewigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Auf! Werde Licht! Dein Licht will kommen; die Herrlichkeit des Herrn strahlt über dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn Finsternis bedeckt die Erde und Wolkendunkel die Nationen. Doch über dir erstrahlt der Herr, und über dir strahlt seine Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Bei deinem Lichte wandeln Heidenvölker und Könige im Glanze deines Strahlens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Auf, erhebe deine Augen! Schau ringsumher! Sie alle sammeln sich und kommen zu dir her. Aus weiter Ferne kommen deine Söhne, und deine Töchter werden auf der Hüfte hergetragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Du siehst es und erstrahlst; dein Herz erbebt und regt sich freudig; denn plötzlich strömt zu dir des Meeres Reichtum und kommen zu dir her der Heidenvölker Schätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Dann deckt dich der Kamele Schwall, von Midian und Epha junge Tiere. Von Saba kommen sie zuhauf und tragen Gold und Weihrauch her und künden froh des Herren Ruhmestaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Dir werden alle Schafe Kedars zugetrieben, und Nabatäas Widder stehen dir zu Diensten. Auf meinen Altar kommen sie zum Wohlgefallen, und also schmücke ich mein herrlich Haus. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Wer sind doch jene, die herbei wie Wolken fliegen, wie Tauben schnell zu ihren Schlägen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Die Küstenländer mühen sich für mich, voran die Tarsisschiffe, und bringen aus der Ferne deine Söhne heim, - mit ihnen auch ihr Silber und ihr Gold, zu Ehren deines Herrn und Gottes, des Heiligen Israels, der dich verherrlicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Und deine Mauern bauen Ausländer, und ihre Könige bedienen dich. Ich habe dich in meinem Groll geschlagen; nun tue ich dir wieder wohl in meiner Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Beständig stehen deine Tore offen, unverschlossen Tag und Nacht, daß man der Heiden Reichtum bei dir einführe mit ihren Königen, umgeben von Geleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Denn Volk und Reich, das dir nicht dienen will, wird untergehn, und Heidenvölker werden völlig ausgerottet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Die Pracht des Libanon kommt zu dir her, Zypressen, Fichten, Ulmen allzumal, um meine heilige Stätte auszuschmücken und meiner Füße Schemel zu verherrlichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Dir nahen sich, gebückt, die Söhne deiner Unterdrücker und werfen sich zu deinen Füßen nieder, sie alle, die dich einst verhöhnt. Sie heißen dich \"Die heilige Stadt des Herrn\", \"Sion des Heiligen Israels\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Wie du verlassen warst, gehaßt und unbesucht, so mache ich dich jetzt zum ewigen Stolz, zur Wonne kommender Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Du trinkst der Heidenvölker Milch und nährst dich gar an königlicher Brust. Du sollst erfahren, daß ich, der Herr, dein Helfer bin und dein Befreier Jakobs Held.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'An Erzes Statt will ich dir Gold bescheren und statt des Eisens Silber, Erz statt der Hölzer, statt der Steine Eisen. Ich setze als Regierung dir den Frieden ein, als deinen Obern die Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nicht weiter hört man von Gewalt in deinem Land, in deinen Grenzen nichts von Druck und Drangsal; du heißest deine Mauern \"Sieg\" und deine Tore \"Ruhm\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Zum Tageslichte dient dir nicht die Sonne; noch braucht des Mondes Schimmer dir zu leuchten. Ein ewig Licht ist dir der Herr, dein Gott dein Strahlenkranz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nie mehr geht deine Sonne unter; dein Mond verschwindet nicht. Ein ewig Licht ist dir der Herr; denn deine Trauertage sind vorbei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Dein Volk - nur Fromme! Auf ewig werden sie das Land besitzen, als Sprößlinge von mir gepflanzt, als meiner Hände ehrenvolles Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Der Kleinste wird zu einer Tausendschaft, zum starken Volke der Geringste. Ich bin der Herr, und ich beschleunige es plötzlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Der Geist des Herrn, des Herrn, ruht über mir, weil mich der Herr gesalbt, den Elenden gar Freudiges zu künden, und mich gesandt, um zu verbinden, deren Herz gebrochen, um den Gefangenen die Freiheit anzukünden, Gefesselten die Fessellösung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'ein Gnadenjahr vom Herrn zu künden und einen Tag der Ahndung unseres Gottes, um alle Trauernden zu trösten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'und um den Trauernden in Sion statt des Schmutzes Schmuck zu geben und Freudenöl statt Trauerflor, an Stelle des verzagten Geistes Festgewänder. Sie sollen dann \"Des Heiles Eichen\" heißen, \"Des Herren ehrenvolle Pflanzung\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Sie bauen auf der Vorzeit Trümmer, sie stellen wieder her der alten Zeiten öde Orte, erneuern abermals zerstörte Städte und langer Zeiten Wüsteneien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Dann kommen Fremdlinge und weiden eure Herden; Ausländer dienen euch als Ackerer und Winzer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ihr aber heißt \"Des Herren Priester\"; euch nennen sie \"Die Diener unseres Gottes\". Und ihr verzehrt der Heiden Reichtum, verfüget völlig über ihre Schätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Für eure doppelt schmähliche Beschimpfung erhalten sie ein freudig Los. Drum erben sie in ihrem Land ein Doppelmaß; zuteil wird ihnen ewige Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Denn ich, der Herr, ich liebe Recht und hasse frevlen Raub; ich gebe ihnen vollen Lohn und schließe einen ewigen Bund mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Ihr Stamm sei bei den Heiden hochberühmt und ihr Geschlecht inmitten der Nationen! Wer sie erblickt, der merkt an ihnen, daß sie ein Stamm sind, den der Herr gesegnet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, '\"Ich freue innig mich des Herrn. Und meine Seele jauchze über meinen Gott! Denn er bekleidet mich mit Heilsgewändern und hüllt mich in des Glückes Mantel, so wie ein Bräutigam sich würdig schmückt, wie eine Braut sich anlegt ihr Geschmeide.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Denn wie die Erde ihre Pflanzen wachsen und wie ein Garten seine Sämereien sprossen läßt, so läßt der Herr, der Herr, aus allen Heidenvölkern Glück und Heil ersprießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Ich schweige nicht um Sions willen. Aus Liebe zu Jerusalem bin ich nicht still, bis daß sein Glück hervorbricht wie das Morgenlicht, sein Heil wie Fackelschein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Die Heiden schaun dein Heil und alle Könige deine Herrlichkeit; sie geben dir nun einen neuen Namen, den selbst bestimmt der Mund des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Du bist ein Prachtkranz in der Hand des Herrn, ein königliches Diadem in deines Gottes Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, '\"Verlassen\" nennt dich niemand mehr, dein Land nicht mehr \"Verstoßen\". Man nennt dich \"Meine Lust\", dein Land \"Vermählt\". Denn seine Lust hat wiederum an dir der Herr; dein Land wird abermals gefreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Dem Jüngling gleich, der eine Jungfrau freit, so freit um dich, der dich aufbaut; und wie ein Bräutigam sich seiner Braut erfreut, also erfreut sich deiner auch dein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Jerusalem! Ich stelle Wächter hin auf deine Mauern, die Tag und Nacht nie schweigen dürfen: \"Die ihr den Herrn erinnern sollt, ihr dürft nicht ruhen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Und laßt ihm keine Ruhe, bis er hergestellt Jerusalem und für die Welt zum Jubelklang gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Geschworen hat der Herr bei seiner Rechten, seinem starken Arm: \"Ich gebe niemals deinen Weizen mehr zur Speise deinen Feinden, und Fremde dürfen deinen Wein nicht trinken, den du dir gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Nein! Die ihn ernten, sollen ihn verzehren, den Herrn lobpreisend. - Die ihn gekeltert, sollen selbst ihn trinken in meinen heiligen Höfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Zieht ein! Durchzieht die Tore! Dem Volke bahnet einen Weg! Die Straße ebnet, ebnet! Entsteinet sie! Errichtet eine Flagge für die Stämme! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Der Herr tut\'s kund bis an der Erde Enden. Vermeldet es der Sionstochter: \"Sieh! Deine Rettung kommt!\" Mit ihm kommt auch sein Lohn; sein Sold liegt ihm bereit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Sie heißen \"Heiliges Volk\", \"Des Herrn Erlöste\". Du jedoch wirst heißen: \"Vielbegehrte\", \"Die Stadt, die nie verlassen wird\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, '\"Wer ist\'s, der da gerötet kommt? Und seine Kleider sind besprengt, mehr als die Winzerkleider. Der dort, behindert durch sein Kleid, mit vieler Mühe schreiten kann?\" - \"Ich bin\'s, der gütig im Verheißen ist und stark genug zum Helfen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, '\"Warum an deinem Kleid die roten Flecken? Warum dein Kleid wie das des Keltertreters?\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '\"Die Kelter habe ich allein getreten; bei mir war niemand von den Völkern. In meinem Zorn zertrat ich sie, zermalmte sie in meinem Grimme. Ihr Saft bespritzte meine Kleider, und ich besudelte all mein Gewand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Der Ahndung Tag lag mir im Sinne, und der Erlösung Jahr war mir gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Ich blickte um; da war kein Helfer. Ich staunte, daß mich niemand stützte. So half mir denn mein eigener Arm, und meine Grimmglut stützte mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Und so zermalmte ich in meinem Zorne Völker; in meinem Grimm zertrat ich sie, und ihren Saft ließ ich zur Erde rinnen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Ich denke an des Herren Gnadentaten, des Herren Ruhmeswerke, nach allem, was der Herr an uns getan, nach seiner Güte Fülle für das Haus von Israel, die er in seiner Huld und seiner großen Gnade ihnen hat erzeigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Er sprach: \"Sie sind ja doch mein Volk, sind Kinder, die nicht pflichtvergessen handeln\", und so ist er ihr Helfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Bei allem Drang gibt es kein Bangen; des Angesichtes Engel unterstützt sie ja. Er rettet selber sie in seiner Liebe, seiner Milde. Durch alle früheren Zeiten hob und trug er sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Doch sie verbitterten im Trotze seinen heiligen Geist. Da ward er ihnen selbst zum Feinde: er selbst bekämpfte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Sein Volk gedachte drauf der alten Zeiten unter Moses: \"Wo ist doch der, der aus dem Meer sie steigen ließ, den Hirten und die Herde? Wo der, der in sein Inn\'res seinen heiligen Geist gelegt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Er, der den Moses an der rechten Hand geführt mit seinem wundervollen Arme? Er, der vor ihnen die Gewässer spaltete und sich auf solche Weise einen ewigen Namen schuf?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Er, der sie durch die Fluten führte wie Rosse durch die Wüste?\" Sie mögen nimmer straucheln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'So, wie ein Tier ins Tal herniedersteigt, vom Geist des Herrn geleitet, so führtest Du Dein Volk, Dir einen hehren Namen schaffend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Vom Himmel sieh herab! Aus Deiner heilig hehren Wohnung blick hernieder! Wo ist Dein Eifer, Deine Wunderkraft? Hat sich Dein mitleidig Erbarmen mir entzogen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Du bist doch unser Vater. Denn Abraham weiß nichts von uns, und Israel erkennt uns nimmer an. Du, Herr, bist unser Vater; von jeher war Dein Name \"Unser Retter\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Warum machst Du uns irre, Herr, an Deinen Wegen, verhärtest unser Herz vor Deiner Furcht? Werd andern Sinns um Deiner Knechte willen, der Stämme, die Dein eigen sind!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Seit kurzem haben sie Dein heilig Volk in ihrer Macht, und unsere Feinde treten jetzt Dein Heiligtum mit Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Und schon ist\'s uns, als hättest Du nie über sie geherrscht, als wär Dein Name über ihnen nie genannt gewesen. Zerrissest Du doch jetzt den Himmel und stiegest nieder, daß die Berge abermals vor Dir erbebten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'So, wie beim Feuerbrand das Feuer Wasser wallen macht, so laß, um Deinen Namen Deinen Feinden kundzutun, die Heidenvölker vor Dir beben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Furchtbares tu, was wir gar nicht erwarten, und komm herab, daß Berge vor Dir beben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Nie höre man von einem Gott, und nie vernehme man dergleichen, und nie erblicke außer Dir ein Auge einen, der also wirkt für die, die seiner harren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Komm dem entgegen, der des Rechten sich erfreuend, es tut und Deiner eingedenk, auf Deinen Wegen bleibt! Doch jetzt bist Du\'s, der grollt, und wir versündigten uns stets dagegen und waren ungehorsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Wir wurden alle wie befleckt, und wie ein unrein Tuch, so waren alle unsere Werke der Gerechtigkeit. Wir alle welkten hin wie Laub; doch sturmesgleich wird unsere Missetat uns fortreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Doch Deinen Namen ruft nicht einer an, und keiner ist, der sich aufrüttelte, um sich an Dich zu klammern; denn Du verbirgst vor uns Dein Angesicht und gibst uns unsern Missetaten preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Und doch bist Du, Herr, unser Vater. Wir sind der Lehm, Du unser Bildner, wir alle Deiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Zürne nicht maßlos, Herr! Ach, denk nicht immer an die Sünde! Schau her! Wir sind doch alle Deines Volkes Glieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Verheert sind Deine heiligen Städte, und Sion ist zur Wüste, Jerusalem zur Wüstenei geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Ach, unser heilig, prachtvoll Haus, wo unsere Väter Dich gepriesen, ist ein Raub der Flammen! All unsere Augenweide ward ein Trümmerhaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Kannst Du darob noch an Dich halten, Herr? Kannst Du so lange schweigen? Kannst Du so lange uns hinhalten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '\"Ich werde also aufgesucht von denen, die mich sonst nicht fragen. Ich soll mich also finden lassen von denen, die mich sonst nicht suchten. \'Da, da bin ich\', soll ich zu einem Volke sprechen, das meinen Namen sonst nicht angerufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Ich breite meine Hände ja den ganzen Tag nach einem widerspenstigen Volke aus, das unheilvolle Wege geht, das seinem eigenen Dünkel folgt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'nach einem Volk, das stets mich reizt, ganz ohne Scheu vor mir, das in den Gärten opfert und auf Ziegelsteinen räuchert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'das in den Gräbern hockt und in Verließen ganze Nächte weilt, das Schweinefleisch genießt und in Gefäßen Greuelbrühe trägt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'das ruft: \'Bleib, wo Du bist! Rühr mich nicht an! Sonst mache ich Dich noch gebannt.\' Sie müssen Rauch in meinem Grimme werden, ein immer lodernd Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Vor mir liegt\'s aufgeschrieben, und ich ruhe nicht, bis ich es heimgezahlt. Vergelten muß ich ihnen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'jetzt ihre Sünden und die ihrer Väter allzumal\", so spricht der Herr, \"die auf den hohen Bergen räucherten und auf den Hügeln meiner spotteten. Erst muß ich denen ihren Lohn in ihren Busen messen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Doch sagt der Herr auch dies: \"Wenn in der Traube Saft sich zeigt, so heißt\'s: \'Zertritt sie nicht! Ein Segen ist ja drin.\' So mache ich es auch um meiner Diener willen, daß ich das Ganze nicht verderbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Aus Jakob bringe ich ein anderes Geschlecht hervor, aus Juda andre Erben meiner Berge, und meine Auserwählten sollen sie besitzen. Dort sollen meine Diener wohnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Und Saron soll zur Schaftrift werden und Achors Tal zum Rinderlager diesem meinem Volk, das nach mir fragt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Für euch jedoch, die ihr den Herrn verlassen, für euch, die meinen heiligen Berg vergessen und die dem Glück den Tisch gedeckt, dem Schicksalsgott den Mischtrank eingeschenkt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'für euch bestimme ich das Schwert. Zur Schlachtung müsset ihr euch ducken, weil ich rief und ihr nicht Antwort gabet, weil ich redete und ihr nicht hörtet, und weil ihr tatet, was mir nicht gefiel, und das gewählt, was ich nicht wollte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Deshalb spricht so der Herr, der Herr: \"Seht! Meine Diener essen; doch ihr hungert. Und meine Diener trinken; ihr aber dürstet. Und meine Diener sind von Herzen fröhlich, ihr aber seid mit Schmach bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Laut jubeln meine Diener auf vor Herzensfreude; ihr aber schreit vor Herzeleid und heult beim Niederbruch des Lebensmutes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Und euren Namen hinterlaßt ihr meinen Auserwählten zum Fluchen: \'Also töte dich der Herr, der Herr!\' - Bei seinen Dienern aber braucht man neue Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Wer sich im Lande Segen wünscht, der wünscht ihn sich vom Gott der Treue, und wer im Lande schwört, der schwört alsdann beim Gott der Treue. - Die früheren Leiden werden all vergessen, verschwunden sein aus meinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Seht! Ich erschaffe einen neuen Himmel und eine neue Erde, und an das Frühere wird nicht gedacht, und keinem kommt es weiter in den Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Nein! Jauchzet immerdar, frohlocket über das, was ich erschaffe. Denn seht! Jerusalem, das schaffe ich zum Jubel um, sein Volk zur Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Über Jerusalem frohlock\' ich selbst und freue mich an meinem Volk. Kein Schluchzen hört man mehr darin und kein Geschrei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nicht mehr gibt\'s dort frühzeitig alte Männer, die ihre Lebenstage nicht erreichen. Der Jüngste stirbt vielmehr als Hundertjähriger; wer hundert Jahre dann verfehlt, gilt als verflucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Sie bauen Häuser und bewohnen sie, und pflanzen Reben und genießen deren Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Sie bauen nicht, auf daß ein andrer es bewohne, sie pflanzen nicht, auf daß ein andrer es verzehre. Der Bäume Alter wird mein Volk erreichen, und ihrer Hände Werk verbrauchen meine Auserwählten selbst. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ihr Schaffen soll nicht mehr vergeblich sein; sie sollen nicht umsonst sich Mühe geben. Ein Stamm, gesegnet von dem Herrn, sind sie samt ihren Kindern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Bevor sie rufen, werde ich willfahren; sie reden noch, und ich erhöre schon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Einträchtig weiden Wolf und Lamm zusammen, und Stroh verzehrt der Löwe gleich dem Rinde. Von Staub nährt sich die Schlange. Sie schaden und verletzen nicht auf meinem heiligen Berg, soweit er reicht.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'So spricht der Herr: \"Der Himmel ist mein Thron, die Erde meiner Füße Schemel. Was für ein Haus ist das, das ihr mir bauen könntet? Was für ein Ort, der mir zur Ruhestätte paßt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Die ganze Welt hat meine Hand gemacht; mein ist das alles.\" - Ein Spruch des Herrn: \"Ich sehe gnädig nur auf den, der demutsvoll ist und zerknirscht, der gegen meine Vorschrift Ehrfurcht hegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Wer Stiere schlachtet, der erschlägt auch Männer; wer Schafe opfert, bricht auch Hunden das Genick. Wer Speiseopfer darbringt, tut es auch mit Schweineblut. Verbrennt er Weihrauch, tut er\'s auch zu Ehren eines Abgotts. Ja, diese haben ihre eignen Wege sich erwählt, ergötzen sich an ihren Scheusalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Und so gefällt es mir, auch ihnen übel mitzuspielen. Ich laß sie treffen, was sie fürchten. Ich rief, und niemand gab mehr Antwort; ich sprach, und niemand hörte, und sie verübten, was mir nicht gefiel. Was ich nicht wollte, wählten sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Nun hört auch ihr des Herren Wort, ihr, die ihr Ehrfurcht hegt vor seinem Worte! \"So sprechen eure Brüder, die euch hassen und euch um meines Namens willen ächten: \'Mög sich der Herr verherrlichen, daß wir auch eure Freude miterleben!\' Die werden recht beschämt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Horch! Aus der Stadt Getöse! Vom Tempel her Getöse! Horch nur! Der Herr zahlt seinen Feinden heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Bevor noch Wehen kommen, ist schon die Geburt erfolgt; bevor noch Schmerzen kommen, ist der Knabe da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Wer hörte je, wer sah dergleichen? Dauern Wehen für ein Land nur einen Tag? Wird sonst ein Volk in einem Augenblick geboren? Doch kaum ist Sion wehe, sind seine Kinder da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, '\"Ja, sollte ich nicht zur Geburt verhelfen und gebären lassen?\" So spricht der Herr. \"Ja, sollte ich, der ich gebären lasse, selbst das Gebären hemmen?\" So spricht dein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Erfreut euch mit Jerusalem! Frohlocket mit ihm allesamt, die ihr es liebt! In großer Freude freuet euch mit ihm, die ihr darüber trauert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Denn satt dürft ihr an seines Trostes Mutterherz euch trinken. Ihr dürfet trinken, euch erlabend, an seiner schweren Brust.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Denn also spricht der Herr: \"Ich lenke stromgleich Wohlfahrt zu ihm hin und einem Wildbach gleich der Heiden Schätze. Ja, trinken sollet ihr, getragen werden auf den Hüften und auf den Knien spielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Wie einen Knaben, den die Mutter tröstet, so werde ich euch trösten, und in Jerusalem sollt ihr getröstet sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Erfahrt ihr dies, alsdann erfreut sich euer Herz. Mark strömt in die Gebeine ein wie Saft in grünes Gras. Des Herren Macht wird offenbar an seinen Dienern, sein Zorn an seinen Feinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Denn seht! Im Feuer kommt der Herr und seine Wagen wie im Sturme, in Hitze auszuhauchen seinen Zorn und seinen Grimm in Feuerflammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Denn richten wird der Herr mit Feuer, mit seinem Schwerte alles Fleisch, und zahlreich sind des Herrn Erschlagene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, '\"Die sich in Gärten, hinter einem in der Mitte, reinigen und heiligen, die Schweinefleisch verzehren und Ungeziefer, Mäuse, sollen miteinander enden.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '\"Ich kenne ihre Taten, ihre Pläne. Die Zeit erscheint, wo alle Heiden, alle Zungen sich versammeln. Sie kommen her und schauen meine Herrscherwürde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Ich stelle dann ein Beispiel auf an jenen und schicke einige von ihnen, die noch übrig, zu den Heidenvölkern nach Tarsis, Phul und Lud, und zu den Bogenspannern, Tubal und zu Javan nach fernen Küstenländern, die nie etwas von mir gehört, die meine Herrlichkeit noch nie geschaut. Sie sollen meine Herrlichkeit auch bei den Heiden künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Dann bringt man alle eure Brüder aus allen Heidenvölkern her als Opfergabe für den Herrn auf Rossen, Wagen und in Sänften, auf Maultieren und Dromedaren zu meinem heiligen Berge nach Jerusalem\", so spricht der Herr, \"so wie die Söhne Israels das Speiseopfer in reinem Topf nur in das Haus des Herrn eintragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Ich nehme einige von ihnen selbst zu Priestern und Leviten\", so spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Solang der neue Himmel und die neue Erde stehn, die ich erschaffe, solange ich bestehe\", ein Spruch des Herrn, \"soll euer Stamm und euer Name dauern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'An jedem Neumond und an jedem Sabbat erscheint zur Anbetung vor mir die ganze Welt\", so spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, '\"Und gehen sie hinaus, dann schauen sie die Leichen derer, die mir untreu wurden, sie, deren Wurm nicht stirbt und deren Feuer nicht erlischt. Für alle Welt sind sie ein Schauder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Aussprüche des Chelkiassohnes Jeremias, eines Mitgliedes der Priesterschaft, die zu Anatot im Lande Benjamin saß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'an den das Wort des Herrn erging in den Tagen des Amonsohnes Josias, des Judakönigs, in seinem dreizehnten Regierungsjahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Dies geschah auch in den Tagen des Josiassohnes Jojakim, des Judakönigs, bis zum Schluß des elften Jahres des Josiassohnes Sedekias, des Judakönigs, bis zur Wegführung aus Jerusalem im fünften Monat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '\"Bevor ich dich im Mutterleib gebildet, habe ich dich schon gekannt; bevor du deinen Mutterschoß verlassen, habe ich dich schon geweiht und zum Propheten über Heiden dich bestellt.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Ich sprach darauf: \"Ach Herr, Du Herr! Ich kann nicht reden; ich bin zu jung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Da sprach der Herr zu mir: \"Sprich nicht: \'Ich bin zu jung!\' Wohin ich dich auch sende, wirst du gehen. Was ich dir anbefehle, wirst du künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Hab keine Furcht davor! Ich bin mit dir, um dich zu schützen.\" - Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Dann reckte seine Hand der Herr, berührte meinen Mund. Dann sprach der Herr zu mir: \"Ich lege meine Worte in deinen Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Ich geb dir heute Vollmacht über Heidenvölker und Königshäuser zum Ausreißen, zum Einreißen und zum Verheeren, zum Verderben, zum Bauen und zum Pflanzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Darauf erging das Wort des Herrn an mich: \"Was siehst du, Jeremias?\" Ich sprach: \"Ich sehe eines Wachbaums Zweig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Da sprach der Herr zu mir: \"Ganz recht! Ich wache über meinem Wort, es zu erfüllen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Zum zweitenmal erging das Wort des Herrn an mich: \"Was siehst du da?\" Ich sprach: \"Ich sehe einen Kessel überkochen, und seine Öffnung schaut von Norden her.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Da sprach der Herr zu mir: \"Im Norden wird gebraut das Unheil über alle, die im Lande wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Ja, sieh! Ich bin\'s, der alle Horden jener Reiche dort im Norden aufruft\", ein Spruch des Herrn, \"auf daß sie kommen, und jeder seinen Sitz hinstelle vor die Tore von Jerusalem und alle seine Mauern rings umher und wider alle Städte Judas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Ich ziehe sie zur Rechenschaft für alle ihre Bosheit, daß sie mich verließen und andern Göttern opferten, anbetend ihrer Hände Machwerk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Du aber gürte deine Lenden! Tritt hin und sprich zu ihnen, was immer ich dich heiße! Erschrick vor ihnen nicht, damit ich dich nicht öffentlich erschrecke!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Ich selbst mach heute dich zur festen Burg, zum Eisenturm, zur ehernen Mauer gegen alle hierzulande, die Könige von Juda, seine Fürsten und seine Priester und des Landes Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Und wenn sie dich bekämpfen, übermannen sie dich nicht. Ich bin mit dir, um dich zu schützen.\" - Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '\"Auf! Künde laut Jerusalem: So spricht der Herr: \'Ich denke, dir zulieb, an deiner Jugend Minne, an deiner Brautzeit Liebe, wie du mir in die Wüste folgtest, in saatenloses Land.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Ein heilig Gut ist Israel dem Herrn, sein Erstlingsteil. Die davon essen, müssen\'s büßen.\" Ein Spruch des Herrn: \"Das Unheil trifft sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Vernehmt das Wort des Herrn, ihr von dem Jakobshaus, all ihr Geschlechter des Hauses Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So spricht der Herr: \"Was fanden eure Väter an mir Übles, daß sie von mir sich trennten, dem Nichts nachliefen und selber nichtig wurden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'und nimmer fragten: \'Wo ist der Herr, der aus Ägypterland uns weggeführt, der uns den Weg gewiesen durch die Wüste, durch Steppen und durch Schluchten, durch dürres, düsteres Land, ein Land, nicht zu betreten, in dem kein menschlich Wesen wohnt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Ich brachte euch in Fruchtgefilde, daß seine Frucht und seine Güter ihr genösset. Ihr zoget auch hinein. Da machtet unrein ihr mein Land, mein Eigentum zum Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Die Priester fragten nicht: \'Wo ist der Herr?\' Und des Gesetzes Wächter kümmerten sich nicht um mich. Die Hirten wurden von mir abtrünnig, und die Propheten waren vom Baal begeistert und liefen denen nach, die doch nichts halfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Drum muß ich mit euch selber hadern\", ein Spruch des Herrn, \"und selbst mit euren Kindern noch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Geht hin zu der Kittiter Küsten! Seht nach! Zieht hin nach Kedar! Gebt acht! Seht zu, ob so etwas schon vorgekommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Hat je ein Heidenvolk Gottheiten umgetauscht? Und dabei sind das keine Götter. Mein Volk jedoch hat seine Herrlichkeit vertauscht mit etwas, was nichts nützen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Entsetzt euch drob, ihr Himmel! Erstarrt vor Schauder!\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '\"Denn zwiefach Böses hat mein Volk getan: Mich haben sie verlassen, mich, den Quell lebendigen Wassers, und Brunnen sich gegraben, geborstene Brunnen, die kein Wasser halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ist Israel ein Sklave, ein Sklavensohn? Warum verfällt\'s dem Raube?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Ihm brüllen Löwen zu; sie lassen ihre Stimme schallen und machen sein Gebiet zur Wüste. Vernichtet seine Städte, ganz entvölkert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Auch die von Memphis und Tachpanches, sie grollen dir gar heftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Der Grund dafür, daß dir dies zugefügt, ist\'s nicht, daß du Gott, deinen Herrn, verlassen? Er wollte auf dem Wege dich zur rechten Zeit geleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Was hast du von dem Wege nach Ägypten, du des Niles Wasser trinkst? Was hast du von Assyriens Weg, wenn du des Stromes Wasser trinkst? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Dein Unglück möge dich belehren und deinen Abfall dir zu Herzen führen! So wisse und erfahre, wie arg es ist, wie bitter, deinen Gott, den Herrn, im Stich zu lassen! - Wenn keine Furcht vor mir mehr bei dir ist!\" Ein Spruch des Herrn, des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, '\"Seit langem hast du ja dein Joch zerbrochen, zerrissen deine Fesseln und gesagt: \'Ich diene Dir nicht mehr.\' Auf jedem hohen Hügel und unter jedem grünen Baum liegst buhlerisch du hingestreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Ich pflanzte dich als Edelrebe ein, ein völlig echt Gewächs. Wie hast du dich mir umgewandelt in eines Wildlings Nebentriebe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Ja, wenn du dich mit Laugensalz auch wüschest, viel Seife dran verschwendetest, so bliebe deine Sünde doch für mich ein Blutfleck.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, '\"Wie kannst du sagen: \'Besudelt habe ich mich nicht, ich bin den Baalen nicht nachgelaufen?\' Besieh dir deinen Weg ins Tal hinab! Bedenke, was du dort getan, du ganz erregte Stute, überbrünstig! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Die wilde Eselin, gewöhnt an Wüsten, erschnappt sie Witterung in ihrer Brunst, wer kann ihre Begierde dämpfen? Wer sie sucht, der braucht nicht müde sich zu laufen; er find sie in ihrem Monat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Lauf dir doch nicht die Sohlen ab! Erspare deiner Kehle das Verdursten! Du aber sagst: \'Vergebens! Nein! Die Fremden liebe ich einmal und laufe ihnen nach.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Wie ein ertappter Dieb in Schmach gerät, so kommen sie vom Hause Israel in Schmach, sie selbst mit ihren Königen und Fürsten und ihren Priestern und Propheten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'sie, die zum Holze sagen: \'Du bist mein Vater\', und zu dem Steine: \'Unsere Mutter.\' Den Rücken kehren sie mir zu, nicht das Gesicht, und sagen doch zur Zeit der Not: \'Auf! Rette uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Wo bleiben deine Götter, die du dir selbst gemacht? Sie sollen aufstehn! Ob sie dir wohl in deiner Notzeit helfen? So viele Städte, so viele Götter hast du, Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Warum nur hadert ihr mit mir? Ihr allesamt seid von mir abgefallen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, '\"Vergeblich schlug ich eure Söhne. Ihr nahmet keine Zucht mehr an, hat euer Schwert doch meine Seher aufgefressen, dem wilden Löwen gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Die Brut, die ihr schon seid! Erwägt das Wort des Herrn: Bin ich denn eine Wüstenei für Israel, ein durstig Land? Warum nur spricht mein Volk: \'Wir laufen fort; wir kommen nicht mehr zu Dir\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vergißt die Jungfrau ihres Schmuckes und ihrer Bänder eine Braut? Und doch hat mich mein Volk vergessen schon seit zahllosen Tagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Wie fein verstehst du\'s anzustellen, dir eine Liebschaft zu erwerben! Fürwahr, du kannst die schlimmsten Weiber deine Künste lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'An deinen Kleidersäumen finden sich Blutspuren armer, unschuldiger Leute. Nicht bei der Reinigung bekamst du sie, vielmehr durch alle diese.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Du aber sprichst: \'Ich bin jetzt schuldlos, hat sich sein Zorn doch von mir weggewandt.\' Ich aber gehe ins Gericht mit dir, weil du gesagt: \'Ich habe nicht gesündigt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Wie gehst du doch daran, den Weg zu wechseln! Doch von Ägypten wirst du so enttäuscht, wie du von Assur warst enttäuscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Von dort auch kommst du weg, die Hände überm Kopf. Der Herr verwirft die, denen du vertraust. Du hast kein Glück mit ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '\"Gesetzt den Fall: Ein Mann entläßt sein Weib, und diese geht von ihm, wird eines andern Mannes - wird jener wohl sich wieder zu ihr kehren? Ist nicht dies Weib entweiht? Du aber hast mit vielen Buhlen schon gebuhlt und willst dich wieder zu mir wenden?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '\"Erhebe zu den Hügeln deine Augen; sieh! Wo hast du dich nicht schänden lassen? Du saßest an den Wegen für sie da, gleich einem Araber der Wüste. Und du entheiligtest das Land durch deine Buhlerei und deine Bosheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Und wurden Regengüsse vorenthalten, und fiel kein später Regen mehr - du hattest dennoch eine unverschämte Stirn; du wolltest dich nicht schämen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Nicht wahr, jetzt rufst du mir: \'Ach, Du mein Vater, meiner Jugend Freund bist Du!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Wird der denn immerwährend grollen und ewig nachtragen?\' So sprachst du und du tatest dabei Schlechtes; du brachtest beides fertig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Einst sprach der Herr zu mir zur Zeit des Königs Josias. \"Hast du gesehen, was die Abgekehrte, Israel, getan? Sie ging auf jeden hohen Berg, zu jedem grünen Baum und buhlte dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Ich dachte: Wenn sie alles das verübt, dann kehrt sie um zu mir. Sie aber tat es nicht. Das sah die ungetreue Schwester Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Sie hatte zwar gesehn, wie ich die Abgekehrte, Israel, verstieß und ihr den Scheidebrief gegeben, weil sie die Ehe brach. Doch ihre ungetreue Schwester Juda hat sich nicht gescheut; sie ging und buhlte ebenso.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Und ihre Unzucht war ganz unaussprechlich, und sie entheiligte das Land und buhlte mit dem Stein und mit dem Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Trotz alldem kehrte ihre ungetreue Schwester Juda in Heuchelei zu mir zurück und nicht von ganzem Herzen.\" - Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Nun spricht der Herr zu mir: \"Unschuldig ist ja Israel, die Abgekehrte, verglichen mit der Ungetreuen, Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Auf! Ruf nach Norden diese Worte hin und sprich: \'Kehr um, du Abgefallene, Israel!\' Ein Spruch des Herrn. \'Ich will auf euch nicht finster blicken, bin ich doch gütig.\' Ein Spruch des Herrn. \'Ich grolle nicht auf ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Erkenne doch nur deine Schuld, daß du vom Herren, deinem Gott, bist abgefallen, daß du mit deiner Liebe gegen Fremde freigebig gewesen unter jedem grünen Baum! Auf meine Stimme aber habt ihr nicht gehört.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, '\"So kehrt zurück, ihr abgefall\'nen Söhne!\" Ein Spruch des Herrn. \"Denn ich, ja ich bin euer Herr. Ich nehme euch, aus einer Stadt je einen, je zwei aus einem Hause, und bringe euch nach Sion hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Nach meinem Herzen gebe ich euch Hirten, die euch mit Einsicht und mit Klugheit weiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Und habt ihr euch durch Fruchtbarkeit vermehrt im Land zu jenen Zeiten\", ein Spruch des Herrn, \"dann spricht man nicht mehr von des Herren Bundeslade. An sie denkt niemand mehr; kein Mensch erinnert sich an sie, vermißt sie nicht und fertigt niemals wieder eine an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'In jener Zeit nennt man Jerusalem den Thron des Herrn, und dorthin kommen alle Heidenvölker in Scharen zu des Herren Namen nach Jerusalem. Sie folgen nimmermehr dem Trotze ihres argen Herzens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'In jenen Tagen einen die vom Judahause sich mit dem Hause Israel und kommen miteinander aus dem Land des Nordens in das Land, das ich zum Eigentum an eure Väter gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Ich dachte, wie ich dich als ein Kind behandelte und dir ein lieblich Land verlieh, den herrlichsten Besitz der Heiden. Ich dachte: \'Mein Vater\' wirst du zu mir sagen und wirst mich nicht verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Doch wie ein Weib dem Mann die Treue brechen kann, so habt auch ihr, vom Hause Israel, die Treue mir gebrochen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Horch! Von den Hügeln hernieder kann man bei den Söhnen Israels sie weinen hören, klagen, daß krumme Pfade sie gewandelt, und daß des Herren, ihres Gottes, sie vergessen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '\"Kehrt um, ihr abgefallenen Söhne! Ich will die Strafe eures Abfalls euch erlassen.\" - \"Da sind wir, sind zu Dir gekommen; denn Du, der Herr, bist unser Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Vergebens ist von Hügeln, von Bergen Segen zu erwarten. Nur bei dem Herren, unserm Gott, ist Heil für Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Gefressen hat die Schande das Vermögen unsrer Väter von unsrer Jugend an; wie ihre Schafe, ihre Rinder, so ihre Söhne, ihre Töchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Wir wollen uns in unsere Schande legen. Zudecken soll uns unsere Schmach! Wir haben ja am Herrn, an unserm Gott, gesündigt, wir selbst, wie unsre Väter auch, von unserer Jugend bis auf diesen Tag, und haben nicht gehorcht dem Wort des Herrn, unseres Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '\"Ja, wenn du umkehrst, Israel\", ein Spruch des Herrn, \"zu mir umkehrst, entfernst du meinetwegen deine Scheusale, ganz ohne Zaudern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'und wenn du schwörst den Schwur \'Beim Herrn!\' aufrichtig, schlicht und rückhaltlos, dann segnen sich mit ihm die Heiden, sich seiner rühmend.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Nun also spricht der Herr zu Judas Männern und zu denen aus Jerusalem: \"Brecht euch ein Neuland um und sät nicht unter Dornen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Beschneidet euch dem Herrn zulieb! Weg mit der Vorhaut eures Herzens, ihr Männer Judas, ihr Bewohner von Jerusalem! - Sonst fährt mein Grimm wie Feuer aus und brennt, und niemand löscht, ob eurer Taten Schlechtigkeit!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Verkündet es in Juda, und in Jerusalem ruft aus und redet, und bei Trompetenschall verkündigt es im Land und ruft aus vollem Hals und sprecht: \"Zuhauf! Wir müssen in die festen Städte ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, '\"Die Flagge schwinget gegen Sion hin! Fort! Bleibt nicht stehen! Denn Unheil bringe ich von Norden her, gewaltigen Niederbruch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Aus seinem Dickicht steigt der Löwe, der Völkerwürger. Nun bricht er auf, läßt seine Stätte hinter sich. Dein Land macht er zur Wüstenei und deine Städte wüst und menschenleer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Legt deshalb Trauerkleider an! So klaget! Heult: \'Daß sich des Herren Zornesglut von uns nicht wendet!\' -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'An jenem Tage aber\", ein Spruch des Herrn, \"entsinkt das Herz dem König und den Fürsten. Die Priester sind verstört, entsetzt die Seher!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Ein Klagelied: \"Ach Herr, o Herr! Gar gründlich hast Du dieses Volk getäuscht, mitsamt Jerusalem. Du sprachst: \'Der Friede wird euch sein!\' Nun geht das Schwert an ihre Kehle.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, '\"Zu jener Zeit wird für dies Volk und für Jerusalem, zur Tochter meines Volkes hin bestellt ein Sturmwind, der die Wüstenhöhen sengt, zum Worfeln nicht geeignet noch zum Säubern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Ein Wind, zu scharf dafür, erscheint auf mein Geheiß. Ich spreche jetzt das Urteil aber sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Wie Meergewölk zieht es heran. Gleichwie ein Sturmgebrause sind seine Wagen, und seine Rosse schneller als der Aar: \'Ach wehe uns! Wir sind verloren.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'So wasche rein dein Herz von Missetat, Jerusalem, daß Heil dir werde! Wie lange haust in deiner Brust dein heillos Gieren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Aus Dan, horch, eine Meldung! Ein Unheilsbote vom Gebirge Ephraim!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, '\"Heidnische Völker bietet auf und ruft sie gen Jerusalem zusammen! Aus fernem Lande kommen Krieger; ihr Kriegsgeschrei gilt Judas Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Wie Feldhüter umlagern sie es ganz. Es war ja widerspenstig gegen mich.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Dein Wandel, deine Taten, die tragen dir dies ein. Das kommt von deiner Schlechtigkeit, daß es so bitter hart ans Herz dir greift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Mein Inneres, mein Inneres! Ich muß mich krümmen. Ach, meines Herzens Kammern! Mein Herz! Es pocht; ich kann\'s nicht stillen. - Ich höre schon des Lärmhorns Schall - des Krieges Lärmgetümmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Verheerung auf Verheerung wird gemeldet. Verloren ist das ganze Land, im Nu vernichtet mein Gezelt, im Augenblicke meine Hütte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Wie lange muß ich Kriegspaniere schauen, das Lärmhorn hören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, '\"Ach, töricht ist mein Volk; sie wollen mich nicht kennen. Einfältige Kinder sind\'s, so unvernünftig, nur klug, um Schlechtes zu verüben. Dagegen schlicht zu handeln, das verstehn sie nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Ich schaue auf die Erde hin; nur Irr- und Wirrsal. Empor zum Himmel blicke ich: Fort Ist sein Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Ich seh die Berge an: Sie zittern, und alle Hügel beben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Ich schaue hin: Da gibt es keine Menschen mehr, und alle Himmelsvögel sind davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Ich schaue hin: das Fruchtgefilde eine Wüste; verheert all seine Städte vor dem Herrn, vor seiner Zornesglut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Denn also spricht der Herr: \"Das ganze Land soll eine Wüste werden; nur ganz vernichten will ich\'s nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Darüber trauere das Land! Der Himmel droben schwärze sich! Drum rede ich von meinem Plan und lasse ihn mich nicht gereuen; ich gehe nimmer davon ab.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Doch vor dem Rufe \"Reiter! Schützen!\" sind alle Städte auf der Flucht. Die schlüpfen in Gebüsche, und die erklettern Felsen; die Städte alle sind verlassen, und niemand siedelt mehr darin. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Du Elende, was willst du tun? Ob du dich auch in Scharlach kleidest, ob du dich schmückst mit goldnem Schmuck, ob du mit Bleiglanz deine Augen schminkst, du machst umsonst dich schön. Die Buhlen haben dich jetzt satt; nach deinem Leben trachten sie. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Ich höre Schreie wie von einer Kreißenden, Angstrufe wie von einer Erstgebärenden. Horch, wie die Sionstochter stöhnt und ihre Hände breitet: \"O wehe mir! Dem Henkerstod bin ich verfallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Durchstreift die Gassen von Jerusalem und seht euch um! Erkundet! Sucht auf ihren Plätzen, ob ihr nur einen findet, einen, der gerecht verfährt und sich der Redlichkeit befleißt! Dann will ich ihm verzeihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Und sagen sie auch \"Bei dem Herrn!\", ein Meineid ist es. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herr, sind nicht Deine Augen auf Ehrlichkeit gerichtet? Du schlugest sie; sie aber bebten nicht. Du warst versöhnlich gegen sie; sie mochten keine Zucht annehmen. Sie machten härter als Gestein ihr Angesicht; sie weigerten sich umzukehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Ich dachte zwar: So ist wohl nur der Pöbel, der töricht sich gebärdet. Er kennt ja nicht des Herren Weg, die Satzung seines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Ich will mich an die Großen wenden und mit ihnen sprechen; die kennen doch des Herren Weg, die Satzung ihres Gottes. - Erst recht zerbrachen die das Joch und rissen Fesseln durch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Dafür schlägt sie der Löwe aus dem Wald und würgen sie die Steppenwölfe. An ihren Städten lauern Pardel. Wer sie verläßt, der wird zerrissen. Denn ohne Zahl sind ihre Missetaten und zahlreich ihre Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, '\"Weswegen soll ich dir verzeihen? Mich haben deine Söhne aufgegeben; bei Aftergöttern schwören sie. Ich habe feierlich mit ihnen mich verbunden, und dennoch brechen sie die Ehe und sind im Hurenhaus zu Gast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Sie gleichen hitzigen, genährten Hengsten; ein jeder wiehert nach des andern Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Dafür soll ich sie nicht bestrafen?\" Ein Spruch des Herrn. \"An einem Volk wie diesem soll ich keine Rache nehmen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Auf! Zerstöret ihre Rebenhänge! Tilgt sie! Doch ganz sollt ihr sie nicht vernichten! Haut ihre Ranken ab! Denn sie gehören nicht dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Verraten haben sie mich ja, das Haus von Israel und Judas Haus.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Den Herrn verleugnen sie und sagen: \"Es ist nichts mit ihm. Uns trifft kein Unglück. Wir spüren weder Schwert, noch Hunger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Die Seher sind nur Luft. Durch sie spricht niemand. So muß man sie behandeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Deswegen spricht der Herr, der Gott der Heerscharen: \"Dieweil ihr solche Reden führt, bin ich\'s, der meine Worte nun zu Feuer macht in deinem Munde und dieses Volk zu Holz, daß jenes sie verzehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Ich bringe über euch ein Volk aus fernem Land, Haus Israel!\" Ein Spruch des Herrn. \"Ein unverwüstlich Volk, ein uralt Volk, ein Volk, von dessen Sprache du nichts weißt, von dem du nicht verstehst, was es dir sagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Dem offenen Grabe gleicht sein Rachen; Helden sind sie alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Und wie dein Brot verzehrt es deine Ernte, verzehrt dir Söhne samt den Töchtern,verzehrt dir Schafe samt den Rindern, verzehrt dir Weinstock samt dem Feigenbaum, zerstört dir feste Städte mit dem Schwerte, und doch verläßt du dich auf diese.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Doch auch in jenen Tagen\", ein Spruch des Herrn, \"Will ich nicht gänzlich euch vernichten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Und fraget ihr: \'Wofür tut uns der Herr und unser Gott dies alles?\', so sprich zu ihnen: \'So wie ihr mich verlaßt und fremden Göttern dient in eurem Lande, so sollt ihr auch der Fremden Sklaven sein in einem Land, das nicht das eure ist!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Nun kündet dies dem Jakobshause! Ruft aus in Juda:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '\"Vernimm dies, Volk, so töricht, unverständig, das Augen hat und doch nicht sieht, und Ohren und nicht hört!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Mich wollt ihr nimmer fürchten?\" Ein Spruch des Herrn. \"Ihr wollt vor mir nicht zittern? Der ich dem Meer den Sand als Grenze setze, die es nach ewigem Gesetz nicht überschreitet. Sie branden zwar, doch sie vermögen nichts, und brausen seine Wogen noch so sehr, sie überschreiten\'s nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Doch dieses Volk besitzt ein widerspenstig, arges Herz; sie fallen ab und gehen fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Sie sprechen nicht in ihrem Herzen: \'Laßt vor dem Herren, unserm Gott, uns fürchten, der Regen gibt zu seiner Zeit, Herbstregen, Lenzesschauer; der uns der Erntefrüchte Fülle sichert!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Doch Störung brachten eure Sünden, und eure Frevel beraubten dieser Wohltat euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Ja, Frevler finden sich in meinem Volk, die, Fallen stellend, Menschen fangen, so wie man Vogelstellerstangen stellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Gleich einem Korbe voller Vögel, sind ihre Häuser voll von ungerechtem Gut. Sie werden davon groß und reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Sie werden fett und feist und übertreffen selbst darin die wüsten Dinger. Sie mögen keine Sache richten und nicht der Waisen Handel schlichten, den Armen nicht zu ihrem Recht verhelfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Und solches sollt ich nicht bestrafen?\" Ein Spruch des Herrn. \"Soll ich an solcher Art von Volk nicht Rache nehmen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Entsetzliches und Gräßliches geschieht im Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Die Seher weissagen durch Trug; die Priester aber klatschen in die Hände, und dies erringt den Beifall meines Volks. Was aber tut ihr dann zuletzt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Ihr Söhne Benjamins! Flieht aus Jerusalem! Stoßt in das Lärmholz zu Tekoa! Und schwingt die Flagge auf Betkerem! Denn Unheil lugt von Norden her, ein schwerer Schlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Mit einer wohlgepflegten Au vergleiche ich die Sionstochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Mitsamt den Herden kommen Hirten über sie; sie schlagen ihre Zelte ringsum auf; sie weiden, jeder seine Schar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Zum Kampfe gegen sie! \"Vorwärts! Wir stürmen noch zur Mittagszeit. Weh uns! Schon neigt sich dieser Tag. Die abendlichen Schatten strecken sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Vorwärts! Wir stürmen dann bei Nacht und brechen ihre Burgen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Denn also spricht der Herr der Heerscharen: \"Haut Bäume um und schüttet einen Wall auf gen Jerusalem! Das ist die Stadt, in der erpreßtes Gut wird allenthalben aufbewahrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Wie seine Wasser frisch der Brunnen hält, genauso hält sich ihre Bosheit frisch. \'Gewalt und Raub!\' hört man in ihr; vor meinem Antlitz sind stets Qual und Schlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Ach, bessere dich, Jerusalem! Sonst reißt sich meine Seele von dir los; ich mache dich zur Wüste, zum unbewohnten Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So spricht der Herr der Heerscharen: \"Man halte gründlich Nachlese wie an dem Weinstock, so am Reste Israels! Streck deine Hand aus wie ein Winzer nach den Reben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Zu wem soll ich noch reden und wen beschwörend mahnen, daß sie hören? Fürwahr, ihr Ohr ist unbeschnitten; sie können nichts vernehmen. Das Wort des Herrn wird ihnen zum Gespött; sie haben kein Gefallen dran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Nun bin ich voll vom Grimm des Herrn, des Anmichhaltens müde; ich gieß ihn auf den Straßen über Kinder aus und auf den frohen Kreis der Jugend. Sie werden kriegsgefangen, Mann und Weib, der Greis samt dem im besten Alter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'An andre kommen ihre Häuser, Felder, Weiber insgesamt, wenn gegen die Bewohner dieses Landes ich meine Hand ausstrecke.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, '\"Denn Groß und Klein bei ihnen, alle wollen Geld. Und die Propheten und die Priester schaffen Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Sie möchten meines Volkes Schaden schnellstens heilen. Nur Heil auf Heil verheißen sie, und doch ist nirgends Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Scham über sie, daß sie so Greuliches verübt! Für sie jedoch gibt\'s kein Erröten mehr; das Schämen haben sie verlernt. Drum werden sie bei den Erschlagnen liegen. Wenn ich sie strafe, kommen sie zu Fall.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So spricht der Herr: \"Verweilet bei den Wegen, seht doch nach! Fragt früheren Pfaden nach: \'Wo ist der Weg zum Guten?\' Und geht ihr den, dann findet ihr für eure Seele Ruhe. Sie aber sagen: \'Nein! Den gehn wir nicht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Ich stelle für euch Wächter auf. \'Auf der Trompete Schall gebt acht!\' Doch sie erwidern: \'Nein! Wir geben nimmer acht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'So hört, ihr Heidenvölker! Vernehmt es, Nationen, was aus ihnen wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Horch auf, du Land! Ich bringe Unheil über dieses Volk, die Früchte ihres Planens. Auf meine Worte mögen sie nicht hören, und mein Gesetz verwerfen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Wozu mir da der Weihrauchduft aus Saba und Würzrohr aus dem fernen Land? Nicht wohlgefällig sind mir eure Brandopfer; und eure Schlachtopfer sind mir nicht angenehm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Darum spricht so der Herr: \"Ich gebe diesem Volk zum Sturz den Anstoß. Die Väter und die Söhne stoßen sich daran, ein Nachbar nach dem andern geht zugrunde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So spricht der Herr: \"Schon kommt ein Volk vom Nordland her; ein großes Heidenvolk erhebt sich von der Erde Enden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Den Bogen und den Wurfspieß führen sie, und hart sind sie, erbarmungslos; ihr Lärmen gleicht den Meer, dem tosenden, wenn sie auf Rossen jagen. Gerüstet Mann für Mann zum Kampf, so geht es wider dich, du Tochter Sions.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, '\"Wir hören, wie sie kommen; erschlafft sind unsere Hände. Uns packen Angst und Zittern wie bei einer Kreißenden.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Geh nicht ins Freie! Nicht auf die Straße! Des Feindes Schwert ist da. Entsetzen ringsumher!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Du, meines Volkes Tochter! Umgürte dich mit einem Bußgewand! In Asche wälze dich! Und traure wie um einen Liebling, und klage bitterlich. \"Im Nu kommt der Verwüster über uns!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, '\"Zum unerschrocknen Scheidemeister bestelle ich dich für mein Volk, auf daß du seinen Wandel untersuchend prüfest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Sie alle sind Empörer und verleumdungssüchtig, sind Kupfer bloß und Eisen, grundverdorben allesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Der Blasbalg ist versengt vom Feuer; das Blei ist unversehrt. Vergeblich schmolz man es; die Schlacken gehn nicht ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, '\"Verworfnes Silber\" nennt man sie; der Herr hat sie verworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Das Wort, das an Jeremias von seiten des Herrn erging:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '\"Betritt das Tor am Haus des Herrn! Und künde dort dies Wort und sprich: Vernehmt das Wort des Herrn, Judäer all, die ihr durch diese Tore kommt zur Anbetung des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So spricht der Heeresscharen Herr, der Schutzgott Israels: \'Verbessert euer Wesen, euren Wandel, dann lasse ich euch hier an dieser Stätte wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Dem Lügenworte trauet nicht! \'Des Herren Heiligtum! Des Herren Heiligtum! Des Herren Heiligtum ist das!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Ja, bessert ihr Wandel und Handel, und bringet ernstlich ihr das Recht zur Geltung beim Streit des einen mit dem andern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'bedrückt ihr keine Fremden, Waisen, Witwen, vergießt ihr kein unschuldig Blut an dieser Stätte, und laufet ihr nicht andern Göttern nach zu eurem Schaden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'dann bleibe ich bei euch an dieser Stätte allezeit, im Land, das euren Vätern ich von alters her verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Doch seht! Ihr trauet diesen Lügenworten ohne Nutzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Wie? Stehlen, morden, ehebrechen, falsch schwören und dem Baal räuchern und anderen Göttern folgen, die ihr gar nicht kennt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Dann kommt ihr, tretet vor mich hin in diesem Haus, das meinen Namen trägt, und sprecht: \"Wir sind geborgen.\" Und bald tut ihr all diese Greuel wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ist denn dies Haus, das meinen Namen trägt, in euren Augen eine Räuberhöhle? Doch ich, fürwahr, ich habe es bemerkt.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, '\"Geht nur nach Silo hin, zu meiner Stätte, wo ich im Anfang meinen Namen wohnen ließ! Und seht dort, was ich wegen der Verruchtheit meines Volkes Israel ihr angetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Weil ihr nun ganz das gleiche tut\", ein Spruch des Herrn, \"weil früh und spät ich zu euch rede, ihr aber mich nicht hört, weil ich euch anrufe, ihr aber keine Antwort gebt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'so tue ich an diesem Haus, das meinen Namen trägt, auf das ihr euch verlaßt, und diesem Ort, den ich euch gab und euren Vätern, so, wie ich einst an Silo hab getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Fortstoßen will ich sie von meinem Angesicht, so, wie ich alle eure Brüder auch verstoßen, den ganzen Stamm von Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Verrichte kein Gebet für dieses Volk! Kein klagend Wort und kein Gebet sprich aus für sie und dringe nicht in mich! Ich höre dich doch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ja, siehst du nicht ihr Treiben in den Städten Judas und in den Straßen von Jerusalem?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Die Kinder sammeln Holz; die Väter zünden Feuer an. Die Weiber kneten Teig, um Kuchen für die Himmelskönigin zu backen und andern Göttern Opferschalen auszugießen. Sie wollen mir Verdruß bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Bin ich\'s, dem sie Verdruß bereiten?\" Ein Spruch des Herrn. \"Und nicht vielmehr sich selbst zu ihrer eigenen Schande?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Darum spricht so der Herr, der Herr: \"Fürwahr, mein Zorn, mein Grimm ergießt sich wegen dieser Stätte über Menschen, über Vieh, des Feldes Bäume und des Landes Frucht. Er brennt und ist nicht auszulöschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So spricht der Herr der Heerscharen, der Schutzgott Israels: \"Bringt eure Brand- und Schlachtopfer in Menge dar! Das Fleisch eßt selber!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Denn euren Vätern hab ich nichts gesagt und ihnen nichts geboten, als ich sie aus Ägypterland hinweggeführt, von Brand- und Schlachtopfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Nur das befahl ich ihnen: \'Auf meine Stimme hört! Dann bin ich für euch Gott, und ihr mein Volk. Den Weg, den ich euch weise, geht! Dann geht\'s euch gut.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Sie aber hörten nicht, noch neigten sie ihr Ohr. Sie wandelten im Trotze ihres bösen Herzens mit Absicht; statt vorwärts, gingen sie zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Wohl sandte ich vom Tag, da eure Väter aus Ägypterland gezogen, bis heute alle meine Knechte, die Propheten, zu euch vom frühen Morgen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Sie aber hörten nicht auf mich, noch neigten sie ihr Ohr. Sie steiften ihren Nacken und trieben\'s ärger noch als ihre Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Wenn du das alles ihnen sagst, und hören sie dich nicht, und rufst du ihnen zu, und geben sie nicht Antwort,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'dann sprich zu ihnen: \'Das ist das Volk, das auf die Stimme seines Herrn und Gottes nicht mag hören und keine Zucht annimmt. Verschwunden ist die Treue, aus ihrem Mund entwichen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Scher deine Locken ab! Wirf sie hinweg! Stimm auf den Höhn ein Klaglied an: \"Verworfen hat der Herr, verstoßen das Geschlecht, auf das er zürnt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, '\"Denn Judas Söhne haben das getan, was mir mißfällt.\" Ein Spruch des Herrn. \"Sie stellten ihre Greuelgötzen in dem Hause auf, das meinen Namen trägt, und sie entweihten es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Und sie errichteten des Tophet Höhen im Tal Ben Hinnom, um ihre Söhne, ihre Töchter zu verbrennen. Nie hab ich solches je geboten; nie ist mir solches in den Sinn gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Fürwahr, deswegen sollen Zeiten kommen\", ein Spruch des Herrn, \"da spricht man nicht mehr von dem Tophet und vom Hinnomstal, nur noch vom Würgetal. Im Tophet wird man euch begraben: sonst ist kein Platz mehr da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Doch dienen auch die Leichen dieses Volks den Vögeln unterm Himmel und den wilden Tieren zum Fraß; kein Mensch verscheucht sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Aus den Städten Judas und aus den Straßen von Jerusalem laß ich verstummen Wonneruf und Freudenjubel, Gesang von Braut und Bräutigam. Zur Wüste wird das Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '\"Zu jener Zeit\", ein Spruch des Herrn, \"holt man aus ihren Grüften die Gebeine der Könige von Juda und die seiner Fürsten und die der Priester und Propheten und der Bewohner von Jerusalem');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'und breitet sie der Sonne und dem Monde hin mitsamt dem ganzen Himmelsheer, gerade jenen, die sie so geliebt und denen sie gedient und nachgelaufen, die sie befragt und angebetet. Nie liest man sie mehr auf, begräbt sie nicht; als Dünger dienen sie dem Acker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Und lieber ist das Sterben als das Leben dem ganzen Rest, der übrigbleibt von dieser bösen Sippe, an all den Orten übrigbleibt, wohin ich sie verstoße.\" Ein Spruch des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Sprich das zu ihnen: \"So spricht der Herr: Wer fällt denn hin und will nicht wieder sich erheben? Wer geht denn fort und kehrt nicht wieder?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Warum fiel dieses Volk, warum Jerusalem auf immer? Weswegen hält es fest am Trug und sträubt sich, umzukehren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich horche hin und lausche; sie aber reden nicht, was recht. Kein Mensch hat heute Reue über seine Schlechtigkeit, so daß er spricht: \'Was habe ich getan?\' Denn sie verharren insgesamt bei ihrem Lauf, dem Rosse gleich, das in den Kampf sich stürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Sogar die Störche unterm Himmel kennen ihre Zeit, und Turteltaube, Schwalbe, Drossel kehren pünktlich wieder. Mein Volk jedoch kennt nicht des Herren Ordnung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Wie mögt ihr sagen: \"Wir sind so weise. Wir haben ja des Herren Lehre inne\"? Fürwahr, in Lügen arbeitet der Lügengriffel eurer Schriftgelehrten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Schande über diese Weisen! Bestürzt, betroffen werden sie. Verworfen haben sie das Wort des Herrn. Was nützt nun ihnen ihre Weisheit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, '\"Ich gebe deshalb ihre Weiber andern und ihre Felder den Eroberern. Denn groß und klein, sie alle wollen Geld, und die Propheten und die Priester schaffen Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Sie möchten gern den Schaden der Tochter meines Volkes auf das schnellste heilen. Nur Heil auf Heil verheißen sie, und doch ist nirgends Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Drum Schande über sie, daß sie so Greuliches verübt! Indes für sie gibt\'s kein Erröten mehr; - das Schämen haben sie verlernt. Drum werden sie bei den Erschlagnen liegen. Wenn ihrer Strafe Zeit erscheint, stürzen sie hin.\" - So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, '\"Ich will bei ihnen Ernte halten.\" Ein Spruchdes Herrn. \"Am Weinstock keine Trauben! Am Feigenbaume keine Feigen, und selbst das Laub verwelkt! Ich bringe ihnen ihren Tod.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Weswegen sitzen wir herum? Zuhauf! Wir wollen in die festen Städte ziehen, daß wir dort schweigend harren. Denn unser Gott, der Herr, hüllt uns in Schweigen; mit bittrem Wasser tränkt er uns, weil wir uns an dem Herrn vergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Auf Frieden hoffen wir, jedoch nichts Gutes kommt, auf Ruhezeit kommt das Entsetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Von Dan her hört man schon das Schnauben seiner Rosse vom lauten Wiehern seiner Hengste bebt das ganze Land. Sie fallen ein; das Land und seine Fülle fressen sie, die Stadt samt den Bewohnern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, '\"Giftschlangen schick ich euch, dawider jeder Zauber fehlt. Sie beißen euch\", ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, '\"Dafür gibt\'s keine Heilung.\" Der Jammer faßt mich an; mein Herz in mir ist krank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Horch auf! Die Tochter meines Volkes schreit aus wüstem Land. \"Ist denn der Herr nicht mehr in Sion? Ist denn sein König nicht mehr dort?\" - \"Weswegen reizten sie durch ihre Bilder mich zum Zorn, durch fremde Nichtse?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '\"Vorbei der Sommer, und der Herbst vorüber, uns wird keine Hilfe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Dieweil gebrochen meines Volkes Tochter, bin ich gebrochen, übertraurig; mich packt Entsetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Gibt\'s keinen Balsam mehr in Gilead? Ist denn kein Arzt mehr da? Warum vernarbt sich nicht die Wunde der Tochter meines Volkes? Wenn doch mein Haupt voll Wasser wäre, ein Tränenquell mein Auge! Ich wollte Tag und Nacht beweinen die Erschlagenen der Tochter meines Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Wenn ich nur in der Wüste eine Ruhestatt besäße, verlassen wollte ich nein Volk, fortgehn von ihnen. Sie sind ja alle Ehebrecher und eine Rotte treuloser Gesellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, '\"Sie spannen ihre Zunge, ihren Lügenbogen; \'s ist ihnen nicht zu trauen, sind sie stark im Land. Von einer Bosheit geht\'s zur andern. Von mir nur wollen sie nichts wissen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Ein jeder hüte sich vor seinem Nachbarn! Und keiner traue seinem Bruder! Denn Hinterlist übt jeder Bruder, und jeder Nachbar gibt sich mit Verleumdung ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Und einer hintergeht den andern, betrügt, gewöhnt ans Lügen seine Zunge und frevelt ohne Rast und Ruhe. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '\"Du wohnest mitten unter Lug und Trug; Sie wollen mich vor lauter Trug nicht kennen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Darum spricht so der Herr der Heerscharen: \"Fürwahr, ich will sie schmelzend prüfen. Wie kann ich anders handeln an der Tochter meines Volkes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Ein spitzer Pfeil ist ihre Zunge, das Reden trügerisch. Man redet freundlich zum Genossen mit dem Munde; im Innern legt man einen Hinterhalt für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Dafür soll ich sie nicht bestrafen?\" Ein Spruch des Herrn. \"An einem Volk, wie dieses, keine Rache nehmen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ich heb ein Weinen an, ein Klagen um die Berge, und um der Steppe Fluren stimm ich an ein Trauerlied. Denn so verheert sind sie, daß sie kein Wandersmann durchzieht. Sie hören nimmermehr der Herde Blöken. Vom Vogel unterm Himmel bis zum Wild ist alles weggezogen, fortgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, '\"Jerusalem, das mache ich zu einem Steinhaufen und zur Behausung für Schakale. Zu einer Wüste mache ich die Städte Judas, worin kein Mensch mehr wohnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Wer ist so weise, daß er dies verstünde? Und daß er künden könnte, was der Mund des Herrn zu ihm geredet? Weswegen geht das Land zugrunde, der Wüste gleich versengt, durch die kein Wandrer zieht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'So spricht der Herr: \"Weil mein Gesetz sie schnöd verlassen, das einst ich ihnen vorgelegt, und weil sie nicht auf meine Stimme hören und ihr nicht folgen mögen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'vielmehr starrsinnig ihrem eigenen Sinn und den Baalen folgen, die ihre Väter sie gelehrt\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'deshalb spricht so der Herr der Heerscharen, Gott Israels: \"Ich gebe Wermut diesem Volk zu essen und tränke es mit bitterem Wasser,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'und unter Völker streue ich sie hin, die weder sie noch ihre Väterje gekannt, und sende hinter ihnen drein das Schwert, bis daß ich sie vernichtet habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'So spricht der Heeresscharen Herr: \"Besinnt euch! Ruft die Klageweiber, daß sie kommen! Zu weisen Frauen schickt, auf daß sie eilends kommen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Sie sollen über uns ein Trauerlied anstimmen, auf daß von Tränen unsere Augen fließen und von Wasser unsere Wimpern triefen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Ja, horch! Ein Klagelied ertönt aus Sion: \"Wie sind wir zugerichtet! Voll Schmach! Verlassen müssen wir das Land, und unsere Wohnungen zerfallen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Ja, Weiber, hört das Wort des Herrn, und euer Ohr erfasse seines Mundes Worte! Dann lehret eure Töchter Wehgesänge, ein Weib das andere den Grabgesang:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, '\"Durch unsre Fenster stieg der Tod; in unsre Burgen drang die Pest und würgte Kinder auf der Straße und auf dem Markte junge Männer.\" Sprich so!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Ein Spruch des Herrn: \"Der Leute Leichen liegen da gleich Dünger auf dem Ackerfeld, wie hinterm Schnitter Ähren, die niemand sammelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'So spricht der Herr: \"Der Weise rühme sich nicht seiner Weisheit! Der Starke rühme sich nicht seiner Stärke! Der Reiche rühme sich nicht seines Reichtums!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Vielmehr, wer sich da rühmen will, der rühme sich, daß er so klug ist, mich zu kennen, daß ich, der Herr, es bin, der Gnade, Recht, Gerechtigkeit auf Erden schafft; an solchen habe ich Gefallen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, '\"Es kommen Tage\", ein Spruch des Herrn, \"wo ich die Unbeschnittenen heimsuche,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Ägypten so wie Midian, Edom, die Ammonssöhne, Moab und alle mit gestutztem Haar, die in der Wüste wohnen. Die Heiden all sind unbeschnitten; doch Israels gesamtes Haus ist unbeschnittnen Herzens.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Vernehmt den Ausspruch, den der Herr an euch vom Hause Israel gerichtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So spricht der Herr: \"Gewöhnet euch nicht an der Heiden Wege und erschreckt nicht vor den Himmelszeichen, wenn schon die Heiden sich vor solchen fürchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Der Völker Satzungen sind eitler Wahn, nur Holz das man im Walde fällt, durch Künstlerhand gefertigt mit dem Meißel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'mit Silber und mit Gold verziert, mit Nägeln und mit Hämmern festgemacht, daß es nicht wackle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Sie gleichen einer Vogelscheuche im Gurkenfeld. Sie reden nicht. Man muß sie tragen. Sie schrecken nicht. Habt keine Angst vor ihnen! Sie können niemals schaden. Doch Gutestun ist auch nicht ihre Sache.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Nicht Deinesgleichen gibt es, Herr; Du bist gar groß, durch Deine Stärke ist Dein Name groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Wer sieht Dich nicht als Völkerkönig an? Für Dich geziemt sich dies. Denn unter allen Weisen bei den Heiden ist Deinesgleichen nicht in ihrem ganzen Göttersaal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Sie spalten, schaben allzumal am Kern der Nichtse, der aus Holz');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'und Silberblech, aus Tarsis eingeführt, und Gold aus Ophir, des Tischlers und des Goldschmieds Machwerk, mit blauem oder rotem Purpurkleid, ein Werk gelernter Meister insgesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'In Wirklichkeit ist nur der Herr ein Gott, lebendiger Gott und ewiger König. Die Erde bebt vor seinem Zorn, und Völker halten seinen Grimm nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Von jenen sollt ihr also sprechen: \"Die Götter, die den Himmel und die Erde nicht erschaffen, verschwinden von der Erde unterm Himmel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Er ist es, der durch seine Kraft die Erde schuf, durch seine Weisheit einst den Erdkreis gründete, durch seine Einsicht auch dem Himmel seine Weite gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Läßt er am Himmel Wasserbrausen hörbar werden, und führt er Wolken von der Erde Rand herauf, und schafft er Blitze, daß es regnet, führt den Wind aus seinen Kammern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'dann muß ein jeder Unverständige sich für töricht halten, weil er merkt, und jeder Künstler muß verblüfft dastehen, weil er sieht: Sein Gußbild ohne Geist ist Trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Nur Wahn sind sie, nur Possenspiel. Wenn sie ein Unglück trifft, ist\'s aus mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Doch solchen gleicht nicht Jakobs Teil. Er ist des Weltalls Schöpfer, und sein besonderer Stamm ist Israel, und \"Herr der Heeresscharen\", ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Vom Boden nimm die Matte auf, die du im Elend sitzest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Denn also spricht der Herr: \"ich schieße dieses Mal auf die Bewohner hier des Landes, ich treib sie in die Enge; sie sollen gut getroffen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Weh mir, meiner Wunde wegen! Unheilbar ist der Schlag, der mich getroffen. Ich aber dachte, eine Krankheit sei es, die ich überstünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mein Zelt ist umgeworfen, und alle meine Seile sind zerrissen. Entführt sind mir die Kinder, und meine Schäflein sind nicht mehr. Mein Zelt spannt niemand auf und niemand richtet meine Decken her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Weil Hirten unverständig sind und nach dem Herrn nichts fragen, schon deshalb haben sie kein Glück, und ihre Herde stiebt nach allen Seiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Horch! Eine Kunde! Her kommt\'s, gewaltiges Getöse aus dem Nordland, das Judas Städte öde macht, zum Wohnsitz für Schakale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Ich weiß jetzt, Herr: Der Mensch ist niemals seines Weges Herr. Dem Manne ist es nicht gegeben, im Gange seine Schritte zu bestimmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'So züchtige mich, Herr, doch nur mit Maß! Und nicht in Deinem Zorn, daß Du mich nicht zermalmst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Gieß über jene Heiden, die Dich nicht anerkennen, Deinen Grimm und über jene Sippen, die Deinen Namen nicht anrufen! Denn sie verschlingen Jakob, verschlingen\'s ganz und gar, und seine Au verheeren sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Das Wort, das an Jeremias von seiten des Herrn erging:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '\"Die Worte dieses Bundes hört! Verkündet sie den Leuten Judas und den Bewohnern von Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Und sprich zu ihnen: Also spricht der Herr, Gott Israels: \'Verflucht der Mann, der nicht auf dieses Bundes Worte hört,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'den euren Vätern ich befohlen, als ich sie aus Ägypterland, dem Eisenschmelzofen, geführt. Ich sprach: Hört meine Stimme! Zur Tat macht alles, was ich euch gebiete! Dann sollt ihr mir zum Volke sein und ich für euch zum Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Ich will den Eidschwur halten, den ich euren Vätern zugeschworen, ich würde ihnen gern ein Land verleihen, wie es heute ist, von Milch und Honig fließend.\'\" Ich gab darauf zur Antwort: \"So sei es, Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Da sprach der Herr zu mir: \"Ruf alle diese Worte in den Judastädten aus und in den Straßen von Jerusalem verkünde: \'Hört die Worte dieses Bundes an und richtet euch danach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Ich schärfte euren Vätern bis auf diese Stunde ein, seit ich sie aus Ägypterland geführt, ich schärfte schon am frühen Morgen ein: Hört meine Stimme!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Sie aber hörten nicht, noch neigten sie ihr Ohr. Ein jeder folgte nur dem Trotze seines argen Herzens. So ließ ich über sie nun all die Worte dieses Bundes kommen, den ich zu halten ihnen anbefohlen, und den sie nicht gehalten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'So sprach der Herr zu mir: \"Treubruch ward aufgedeckt bei Judas Leuten und bei Jerusalems Bewohnern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Zu Missetaten ihrer Ahnen sind sie umgekehrt, die sich geweigert, meine Worte anzuhören. Sie gehen andere Göttern nach, sie zu verehren. Gebrochen hat Israels Haus und Judas Haus den Bund, den ich mit ihren Vätern schloß\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Deshalb spricht so der Herr: \"Von mir kommt Unheil über sie, aus dem sie keinen Ausweg finden. Sie schrein zu mir; ich aber will sie nicht erhören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Und schreien auch die Städte Judas und die Bewohner von Jerusalem ein übers andremal zu Göttern, zu ihnen, denen sie jetzt räuchern, sie helfen ihnen nicht in ihrer Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'So viele Städte, soviel Götter hast du, Juda, und nach der Zahl der Gassen von Jerusalem habt ihr Altäre für den Schandgott aufgestellt, Altäre, um dem Baal zu räuchern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Verrichte kein Gebet für dieses Volk! Kein klagend Wort und kein Gebet sprich über sie! Denn ich hör nicht darauf, wenn sie ob ihrem Unglück zu mir rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Was fällt denn meinem Liebling ein, in meinem Hause eine Menge Frevel zu verüben? Mag heilig Fleisch von dir die Bosheit nehmen, daß du so jubelst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Der Herr nennt einen frischen Ölbaum dich, durch prächtige Früchte ausgezeichnet; doch legt er wegen seines mächtigen Rauschens Feuer an, daß seine Äste krachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Der Herr der Heerscharen hat Schlimmes dir angedroht, als er dich eingepflanzt, der Schlechtigkeit des Hauses Israel wegen, und wegen der des Judahauses, das Dinge bei sich treibt, die mich zum Zorne reizen müssen, weil es dem Baal Räucheropfer bringt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Der Herr hat mich\'s erfahren lassen; ich habe es verkostet. Du hast mir damals aufgedeckt, wozu sie fähig waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ich selber aber, einem zarten Lamme gleich, das man zur Schlachtbank schleppt, ich ahnte nicht, daß wider mich sie Pläne hegten: \"Im Safte wollen wir den Baum verderben und aus dem Lande der Lebendigen ihn tilgen, und seines Namens werde nimmermehr gedacht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Du Herr der Heerscharen, gerechter Richter! Du Herz- und Nierenprüfer! Ich schaue Deine Rache noch an ihnen; denn ich befehle meine Sache Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'So spricht der Herr betreffs der Männer Anatots, die deinem Leben nachgestellt und dir befohlen haben: \"Du darfst nicht in des Herren Namen prophezeien; sonst leidest du den Tod durch unsre Hand!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'So spricht der Herr der Heerscharen: jawohl, ich will sie strafen. Die jungen Männer sterben durch das Schwert, durch Hunger ihre Söhne samt den Töchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Kein Rest verbleibe ihnen! Das Unheil bringe ich den Männern Anatots im Jahre der Heimsuchung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Herr, Du bist\'s, der immer Recht behält, sooft ich mit Dir hadre; ich möchte dennoch Dich zur Rede stellen: Weswegen glückt der Weg der Frevler und leben ruhig alle treulos Handelnden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du pflanzest sie; schon wurzeln sie. Sie schlagen aus; schon tragen sie auch Frucht. Geläufig bist Du ihrem Mund, doch ihrem Herzen fremd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Du aber kennst mich, Herr, durchschaust mich, hast erprobt, wie sich mein Herz zu Dir verhält. So schlepp sie fort wie Schafe, fort zum Schlachten! Dem Würgetage weihe sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Wie lange soll das Land noch trauern, des Feldes ganzes Gras verdorren? Das Vieh mitsamt den Vögeln schwindet, der Bosheit derer wegen, die drin siedeln. Sie sagen ja: \"Von unsrer Zukunft weiß er nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '\"Wirst du im Wettlauf mit den Fußgängern schon müde, wie wolltest du mit Rennpferden Wettrennen? Bist du im sichern Land schon ängstlich, was tust du erst im Jordandickicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Denn deine Brüder, deines Vaters Haus, auch sie sind treulos gegen dich gesinnt. Auch diese rufen hinter deinem Rücken: \'Voll das Maß!\' Trau ihnen nicht, auch wenn sie freundlich mit dir reden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Ich will von meinem Hause nichts mehr wissen; mein Eigen geb ich preis und überliefere mein Liebstes in die Hand der Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Was mein, benahm sich gegen mich wie in dem Wald ein Löwe; es brüllte wider mich. Daher mag ich es nimmer leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Sieht denn mein Eigentum wie ein entstellter Vogel aus, um den die andern Vögel fliegen? Herzu! Zuhauf des Feldes Tiere! Herbei zum Fraße!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Zahlreiche Hirten machen meinen Weinberg wüst, zertreten meinen Grund und Boden; in wüste Öde wandeln sie mein Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Zur Wüste machen sie\'s, verwüstet trauert es vor mir. Verwüstet ist das ganze Land, weil niemand sich\'s zu Herzen nimmt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Auf allen Höhen in der Wüste treten die Verwüster auf. Der Herr hat ja ein Schwert, das von des Landes einem Ende bis zum andern würgt. Kein Mensch bleibt heil. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Sie säen Weizen, ernten aber Dornen; und ohne Nutzen quälen sie sich ab. - Seid über eure Ernte recht enttäuscht! Aufdampft der Zorn des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So spricht der Herr: \"All meine schlimmen Nachbarn, die an das Eigentum angrenzen, das ich zu eigen meinem Volke Israel gegeben, entwurzle ich aus ihrem Land. Nicht länger lasse ich das Judahaus in ihrer Mitte weilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Danach, wenn ich sie weggerissen, erbarme ich mich ihrer wiederum und leite jeden abermals in sein Besitztum und jeden in sein Land zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Gewöhnen sie sich an die Weise meines Volks, daß sie bei meinem Namen schwören \'Bei dem Herrn\', so wie sie einst mein Volk daran gewöhnt, beim Baal zu schwören, dann werden Sie inmitten meines Volkes ein Stätte haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Doch wollen sie nicht hören, dann will ich solch ein Heidenvolk ausreißen und vertilgen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So sprach der Herr zu mir: \"Auf! Kauf dir einen Leinengürtel! Leg ihn um deine Hüften! Doch bring ihn nicht ins Wasser!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Da kaufte ich den Gürtel nach des Herrn Geheiß und legte ihn um meine Hüften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Hierauf erging das Wort des Herrn an mich zum zweitenmal:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '\"Den Gürtel, den du dir gekauft und an den Hüften hast, nimm mit! Auf! Zieh zum Euphrat hin! Verbirg ihn dort in einer Felsenspalte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Ich ging und barg ihn dort am Euphrat, wie mir der Herr geboten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Und es geschah nach vielen Tagen; da sprach der Herr zu mir: \"Auf! Zieh zum Euphrat hin und hol daselbst den Gürtel, den ich dich dort verbergen hieß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Ich zog zum Euphrat hin und suchte nach und nahm den Gürtel von der Stelle, wo ich ihn versteckt, und siehe da, der Gürtel war verdorben; zu nichts mehr tauglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Darauf erging das Wort des Herrn an mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Der Herr sprach also: \"Auf gleiche Art vernichte ich auch Judas Glanz und den Jerusalems, so groß er ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Dem bösen Volk, das sich jetzt weigert, meine Worte anzuhören, und das im Trotze seines Herzens wandelt und hinter anderen Göttern läuft, sie zu verehren und sie anzubeten, ihm soll\'s genau so gehn wie diesem Gürtel, der zu nichts mehr taugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Wie sich der Gürtel schmiegt an eines Mannes Hüften, ließ ich an mich das ganze Haus von Israel sich schmiegen und das von Juda\", ein Spruch des Herrn, \"damit es mir zum Volk, zum Lob und Ruhm und Schmucke diene. Sie aber hörten nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'So sage ihnen dieses Wort: So spricht der Herr, Gott Israels: \'Mit Wein wird jedes Weingefäß gefüllt\'; und sagen sie zu dir: \'Ja, dürfen wir nicht wissen, weshalb man jeden Krug mit Wein soll füllen?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'dann sage ihnen - Also spricht der Herr: \'Erfüllen will ich wirklich alle, die dieses Land bewohnen, die Könige, die auf dem Davidsthrone sitzen, die Priester und Propheten und alle Einwohner Jerusalems mit Trunkenheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'und ich zerschlage sie, den einen an dem andern, die Väter und die Söhne allzumal\'; ein Spruch des Herrn: \'Ich schone nicht, bedaure nicht, und kein Erbarmen hält mich ab, sie zu vernichten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'So hört! Merkt auf! Seid doch nicht stolz! Der Herr hat ja geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Die Ehre gebet eurem Gott, dem Herrn, bevor es dunkel wird, bevor sich eure Füße an den finstern Bergen stoßen. Ihr sehnet euch nach Licht; er macht\'s zu tiefem Dunkel und hüllt\'s in dichte Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Doch hört ihr nicht darauf, dann muß ich herzlich still beweinen euren stolzen Sinn. Und unaufhörlich weint mein Auge; es zerfließt in Tränen, weil des Herren Herde gefangen wird hinweggeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'So sprich zum König und zur Herrin: \"Zu unterst setzt euch hin! Herab von eurem Haupt ist eure Krone voller Pracht gesunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Des Südlands Städte sind umschlossen, und niemand ist, der sie befreit. Ganz Juda wird jetzt weggeführt, hinweggeführt bis auf den letzten Mann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Heb deine Augen auf und sieh, wie sie von Norden kommen! Wo bleibt die Herde, die dir anvertraut, wo deine schmucken Schafe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Was sagst du, stellt er dich jetzt unter Aufsicht? Du selber hast sie an die Herrschaft über dich gewöhnt, als erste Lieblinge. Ja, packen dich dann nicht die Wehen, gleich einem Weibe, das gebiert?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Und fragst du dich: \"Warum geschieht mir dies?\" Bei deiner großen Schlechtigkeit war deine Schleppe immer aufgedeckt, und deine Fersen waren wund gerieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann wohl ein Neger seine Haut, ein Pardel seine Flecken ändern? Nur dann könnt ihr auch besser werden, die ihr gewohnt seid, schlecht zu handeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, '\"Und ich zerstreue euch wie Stoppeln, die vor dem Wüstenwind verfliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Das sei dein Los, dies sei dein Teil, von mir dir zugemessen!\" Ein Spruch des Herrn. \"Weil du vergessen mich, auf Lüge dich verlassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'will ich dir dein Gewand bis ins Gesicht aufdecken, daß deine Schande sichtbar werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Dein Ehebrechen, dein Gewieher und deine unverschämte Buhlerei, auf Hügeln und im freien Feld hab ich gesehen deine Greuel. Weh dir, Jerusalem! Du bist nicht rein. Wie lange noch?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Was einst als Wort des Herrn an Jeremias der Dürre wegen erfolgte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '\"In Juda Trauer! Und öde seine Pforten! Am Boden trauernd liegen sie. Jerusalems Geschrei schallt in die Lüfte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Die Großen senden ihre Knechte nach dem Wasser; sie kommen an die Brunnen, finden keins. Sie kehren leer zurück, bestürzt, enttäuscht, das Haupt verhüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Dieweil zu Staub das Ackerland geworden - im Lande fällt kein Regen mehr -, drum lassen ihren Mut die Ackersleute mit verhülltem Haupte sinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Sogar das Reh gebiert auf freiem Feld und geht davon; denn nirgends gibt\'s mehr Gras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Wildesel stehen auf den Höhen, nach Atem schnappend gleich den Drachen. Sie sehen sich die Augen aus; denn nirgends grünes Futter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, '\"Klagen uns an auch unsere Missetaten, so handle doch entsprechend Deiner Ehre, Herr! Zahlreich sind freilich unsere Übertretungen, durch die wir uns an Dir versündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du Hoffnung Israels, sein Heiland in der Zeit der Not! Warum tust Du so fremd im Land, gleich einem Wandersmann, der nur zur Nachtzeit bleibt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Warum gleichst Du jetzt einem Manne, der erschrocken, dem Schwächling, der nicht helfen kann? Und doch bist Du in unsrer Mitte, Herr. Wir sind Dein Eigentum. Laß uns nicht untergehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Von diesem Volke sprach der Herr: \"So hin und her, das lieben sie und schonen ihre Füße nicht. An ihnen kann der Herr sich aber nicht erfreuen, und so gedenkt er ihrer Schuld und ahndet ihre Sünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Dann sprach der Herr zu mir: \"Verrichte kein Gebet für dieses Volk um Heil! Selbst wenn sie fasten, hör ich nimmer auf ihr Flehn, und wenn sie Brand- und Speiseopfer bringen, nehme ich sie nicht zu Gnaden an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Durch Schwert und Hunger und durch Pest, so räume ich gewaltig unter ihnen auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Da sprach ich: \"Herr, ach Herr! Propheten sagen ja zu ihnen: \'Von Schwertern werdet ihr nichts sehen, und Hungersnot kommt nicht zu euch. Nein, ich verleihe sichern Frieden euch an dieser Stätte hier.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Da sprach der Herr zu mir: \"Nur Lügen prophezein in meinem Namen die Propheten. Ich habe sie ja nicht gesandt und nicht geheißen und nie zu ihnen je gesprochen. Erlogene Gesichte, eitle Wahrsagung und selbsterdachten Trug, das prophezein sie euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Deshalb spricht so der Herr: \"Die Seher, die in meinem Namen prophezeien und die künden: \'Kein Schwert kommt in dies Land, kein Hunger\', - obwohl ich sie doch nicht gesandt, - durch Schwert und Hunger enden diese Seher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Die Leute aber, denen sie weissagen, liegen in den Gassen von Jerusalem am Boden, vom Hunger und vom Schwerte hingestreckt, und niemand ist, der sie bestatten könnte, sie selbst mit ihren Weibern, Söhnen, Töchtern. Ich gieße ihre Bosheit über sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Das sag zu ihnen: \'Von Tränen rinnen meine Augen Tag und Nacht und werden nimmer trocken. Mit tiefen Wunden wird die Jungfrau, meines Volkes Tochter, ganz unheilbar geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Wenn ich hinaus ins Freie gehe, da liegen Schwertdurchbohrte. Betrete ich die Stadt, da toben Hungersqualen. Propheten samt den Priestern wälzen sich besinnungslos am Boden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hast Du denn Juda ganz verworfen? Hast Du an Sion Ekel? Warum schlägst Du uns so, da uns die Mittel, uns zu heilen, fehlen? Genesung hoffen, ohne daß es besser wird! Statt Heilung Rückfall!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Wir kennen unsern Frevel, Herr, und unserer Väter Schuld, daß wir an Dir gesündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Verschmäh doch nicht die Wohnstatt Deines Namens, entehre nicht den Thronsitz Deiner Herrlichkeit! An Deinen Bund mit uns erinnere Dich und kündige ihn nimmer auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Gibt\'s bei den Heidennichtsen Regenspender, und spendet denn der Himmel selber Regenschauer? Bist Du es nicht, Herr, unser Gott? So wollen wir auf Dich vertrauen; denn Du hast alles das gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'So sprach der Herr zu mir: \"Wenn Moses auch und Samuel vor mich hinträten, so wäre meine Seele doch nicht mehr bei diesem Volke. Schaff es fort aus meinen Augen! Laß sie gehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Und sprechen sie zu dir: \'Wohin denn sollen wir uns wenden?\', so spricht zu ihnen: Also spricht der Herr: \'Zur Seuche, wer der Seuche ist! Zum Schwerte, wer des Schwertes! Zum Hunger, wer des Hungers! Zum Kerker, wer des Kerkers ist!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Vier Sippen will ich gegen sie bestellen.\" Ein Spruch des Herrn. \"Das Schwert zum Morden, die Hunde zum Verschleppen, des Himmels Vögel und der Erde Wild zum Fressen und Vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Ich mache sie zum Schreckensbild für alle Königreiche auf der Erde, um Manasses, des Ezechiassohns und Judakönigs willen für alles, was er in Jerusalem verübt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Wer hat, Jerusalem, mit dir Erbarmen? Wer klagt mit dir? Wer biegt vom Wege ab, nach deinem Wohl zu fragen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, '\"Du selbst hast mich verstoßen\", Spruch des Herrn, \"und mir den Rücken zugekehrt. Nun strecke ich die Hand aus gegen dich, vernichte dich; was ich beschlossen, ändere ich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Ich worfle diese an des Landes Pforten mit der Gabel und mache bis zum Untergange kinderlos mein Volk. Von seinen Wegen läßt es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Zahlreicher werden seine Witwen als der Sand am Meer. Ich bringe über sie im Übermaße junge Männer, die am hellichten Tage rauben. Aufregung, Schrecken lasse ich sie jäh befallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Die siebenmal geboren, welkt dahin, verhaucht ihr Leben. Am lichten Tag geht ihre Sonne unter. Sie wird zuschanden und mit Scham bedeckt. Was dann von ihnen übrig, gebe ich dem Schwert vor ihren Feinden preis.\" Ein Spruch des Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Weh mir, ach Mutter, daß du mich geboren, mich, einen Mann des Haders und des Streits für alle Welt. Ich habe nicht verborgt und nicht geborget und dennoch flucht mir alle Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Da sprach der Herr. \"Zum Glücke löse ich dich aus und trete für dich ein beim Feind zur Zeit des Unglücks und der Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Läßt Eisen sich zerschlagen, das Eisen aus dem Norden und das Erz?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Dein Hab und Gut und deine Schätze gebe ich der Plünderung ganz ohne Entgelt preis für alle deine Sünden, deine Missetaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Ich will dich dienen lassen deinen Feinden in einem Land, das du nicht kennst. Durch meinen Zorn entzündet sich ein Feuer, das über euch zusammenschlägt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Du weißt es, Herr. Gedenke meiner! Schau her auf mich! Und räche mich an meinen Widersachern! Laß mich durch Deine Langmut nicht zugrunde gehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Wenn\'s von Dir Worte gab, verschlang ich sie. Dein Wort war Freude für mein Herz und Wonne. Ich trage Deinen Namen. Herr, Du Gott der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Ich sitze nie in heiterm Kreis voll Fröhlichkeit; ich sitze ganz abseits, von Deiner Hand berührt, sooft Du mich mit Grimm erfüllst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Warum ist meine Kümmernis so dauernd und meine Wunde unheilbar und tödlich? Du gleichst mir einem trügerischen Bach, Gewässern, auf die kein Verlaß. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, '\"Nicht so!\" Es sprach der Herr. \"Wofern du andern Sinnes wirst, bediene ich mich deiner Dienste wieder, und trägst du Edles lieber vor als Häßliches, dann darfst du mir zum Munde wieder dienen. Sie wenden sich zu dir; du aber sollst dich nicht zu ihnen kehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Ich mache dich für dieses Volk zu einer steilen, ehernen Mauer. Und greifen sie dich an, so werden sie dich nicht bezwingen. Ich bin bei dir, um schirmend dich zu schützen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '\"Ich will dich retten aus der Hand der Bösen und aus der Wüteriche Faust.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '\"Du sollst nicht heiraten und weder Sohn noch Tochter an diesem Orte haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Denn also spricht der Herr von jenen Söhnen und den Töchtern, die hier geboren werden, und von den Müttern, die das Leben ihnen geben, und von den Vätern, die in diesem Land sie zeugen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '\"Sie sterben jammerwürdig, unbetrauert, unbegraben. Zum Dünger werden sie dem Acker. Durch Schwert und Hunger schwinden sie; zum Fraße dienen ihre Leichen den wilden Tieren und des Himmels Vögeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'So spricht der Herr: \"Betritt kein Haus zum Totenmahl! Geh nicht zum Trauern! Dein Beileid drücke niemand aus! Denn meine Freundschaft hab ich diesem Volk entzogen\", ein Spruch des Herrn, \"die Huld und die Barmherzigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Und nun stirbt Groß und Klein in diesem Lande, unbegraben, unbetrauert. Man ritzt sich nicht, man schert sich nicht um ihretwillen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Man bricht kein Trauerbrot mit ihnen und tröstet keinen um des Toten willen. Man läßt ihn nicht des Trostes. Becher trinken um seines Vaters oder seiner Mutter willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Besuche nicht ein Festgelagehaus, bei Schmaus und Trunk mit ihnen dort zu liegen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Denn also spricht der Herr der Heerscharen, Gott Israels: \"Aus diesem Ort verbanne ich vor euren Augen und in euren Tagen das Gejohl des Lachens und der Lust, den Sang des Bräutigams, das Lied der Braut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Und tust du diesem Volke all dies kund, und sagen sie zu dir: \'Warum hat uns der Herr all dieses große Unheil angedroht? Was ist denn unsere Schuld, was unsere Sünde, wodurch wir uns verfehlt an unserm Gott und Herrn?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Dann sprich zu ihnen: \'Weil eure Väter mich verlassen\', ein Spruch des Herrn, \'und weil sie andern Göttern nachgelaufen und sie verehrt und angebetet und mich im Stich gelassen und mein Gesetz nicht mehr gehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Und ihr habt noch viel Schlimmeres getan als eure Väter; ihr folgtet, jeder, dem Trotze seines argen Herzens und hörtet nicht auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'So schleudre ich euch fort aus diesem Land in jenes Land, das ihr so wenig kennt wie eure Väter. Dort mögt ihr andern Göttern dienen Tag und Nacht, dieweil ich kein Erbarmen mehr euch schenke.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, '\"Doch kommen Tage\", ein Spruch des Herrn, \"da sagt man nicht mehr: \'Bei dem Herrn, der aus Ägypterland die Söhne Israels heraufgeführt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Nein! Bei dem Herrn, der aus dem Nordland hergeführt die Söhne Israels und ebenso aus all den Ländern, in die er sie verstoßen: Ich bringe sie in ihre Heimat wieder, die ich verliehen ihren Vätern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Ich lasse viele Fischer holen\", ein Spruch des Herrn, \"die fischen sie heraus; danach entbiet ich viele Jäger; die jagen sie von jedem Berg und Hügel und aus den Felsenklüften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Denn meine Augen schauen alle ihre Wege; sie können nicht vor mir verheimlicht werden, und ihre Missetat bleibt nicht verborgen meinen Blicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Ich ahnde einmal, zweimal ihre Missetat und Sünde. Durch ihrer Greuel Schändlichkeit entweihten sie mein Land, und ihre Greueltaten füllten ganz mein Eigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herr, meine Kraft und Feste! Und meine Zuflucht in der Zeit der Not! Bis von der Erde Enden kommen Völker zu Dir her und sprechen: \"Nur Trug besaßen unsre Väter zum Besitz, nur Nichtse, die nichts nützen können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kann wohl ein Mensch sich Götter machen? Drum sind sie keine Götter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '\"Ich zeige ihnen daher diesmal meine');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Mit Eisengriffel ist die Sünde Judas auf ihres Herzens Tafel eingetragen, mit diamantener Spitze euren Altarhörnern eingegraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Wie voll von ihren Kindern sind bei ihnen die Altäre! Und unter grünen Bäumen stehen ihre Götzensäulen auf den hohen Hügeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, '\"Ach, du mein Berg im Felde! Ich geb dem Raub all deine Schätze preis für deine Höhen, für die Missetat in deinem ganzen Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Verzichten mußt du auf dein Erbe, das ich dir eingeräumt. Ich mache dich zum Knechte deiner Feinde, in jenem Land, das du nicht kennst. Ein Feuer habt ihr ja durch meinen Zorn entzündet, das lange, lange brennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So spricht der Herr: \"Dem Manne, der auf Menschen baut, sei Fluch, der Fleisch zu seinem Arme macht und dessen Herz vom Herrn nichts wissen will!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Er gleicht dem Strauche in der Steppe, erlebt nie bessere Zeiten. Er siedelt auf der Wüste Flammengründen, in unwirtlichem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Gesegnet ist der Mann, der auf den Herrn vertraut, und dessen Zuversicht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Er gleicht dem Baum, gepflanzt am Wasser. Ist er am Bache eingewurzelt, so spürt er nicht, wenn Hitze kommt; sein Laub bleibt frisch und grün. In einem trocknen Jahre hat er keine Not, und unaufhörlich trägt er Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Das Herz ist hinterhältiger als alles, ist heillos. Wer kann\'s ergründen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Nur ich, der Herr, erforsch\' das Herz, prüfe die Nieren und lohne jedermann nach seinem Wandel, ganz nach seiner Taten Frucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Ein Rebhuhn, das bebrütet, was es nicht gelegt, ist, wer sich Reichtum sammelt, aber nicht auf rechte Weise. In seiner Tage Hälfte wird der ihn verlassen; er steht an seinem Ende da als Narr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Ein Thron der Herrlichkeit, von alten Zeiten hoch erhaben, ist die Stätte unsres Heiligtums.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Herr, Hoffnung Israels! Wer Dich verläßt, der wird zuschanden. Die von mir weichen, werden in den Staub geschrieben. Sie haben ja den Quell des Lebenswassers, den Herrn, verlassen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Herr, heile mich! Dann bin ich heil. Befreie mich! Dann bin ich frei. Mein Ruhm bist einzig Du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Sie sagen jetzt zu mir: \"Wo bleibt das Wort des Herrn? Es treffe ein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ich habe niemals mich an Dich herangedrängt zum Bösen. Nie wünschte ich den unheilvollen Tag herbei. Das weißt Du selbst. Was über meine Lippen kam, lag offen da vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'So werde mir zum Sturze nicht, Du meine Zuflucht an dem Unheilstag!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Die mich verfolgen, möge Schande treffen, nicht mich! Erschrecken mögen sie, nicht ich! Den Unheilstag bring über sie! Mit zwiefacher Zerschmetterung zerschmettere sie!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'So spricht der Herr zu mir: \"Stell dich ins Benjaminstor, durch das die Könige von Juda einziehn, durch das sie ausziehen, hierauf an alle andern Tore in Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Und sprich zu ihnen: \'Vernehmt das Wort des Herrn, ihr Könige von Juda, du, Juda insgesamt, all ihr Bewohner von Jerusalem, die ihr in diese Tore kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So spricht der Herr:\"Um eures Lebens willen hütet euch! Am Sabbat traget keine Last, daß ihr sie in die Tore von Jerusalem verbrächtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Am Sabbat tragt aus euren Häusern keine Last! Kein Tagwerk dürft ihr da verrichten! Den Sabbat heiligt so, wie ich es euren Vätern vorgeschrieben!\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Sie aber hörten nicht, noch neigten sie ihr Ohr. Halsstarrig wollten sie nicht hören und nicht Zucht annehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Wenn ihr nun auf mich hören wollt\", ein Spruch des Herrn, \"daß ihr am Sabbat keine Last hier in die Tore dieser Stadt verbringt, vielmehr den Sabbat heiligt, keinerlei Geschäfte an ihm tut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'dann ziehen durch die Tore dieser Stadt die Könige und Fürsten ein, die auf dem Davidsthrone sitzen, auf Wagen und auf Rossen, samt ihren Fürsten, die Männer Judas und Jerusalems Bewohner, und diese Stadt bleibt immerdar besiedelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Aus Judas Städten, aus Jerusalems Umgebung, aus dem Lande Benjamin und aus der Ebene und vom Gebirge, vom Südland her bringt Brand- und Schlacht- und Speiseopfer und Weihrauch samt den Dankesopfern zu dem Haus des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Gehorchet ihr mir aber nicht und heiligt nicht den Sabbat und tragt ihr Lasten und bringt sie in die Tore von Jerusalem am Sabbattage, dann leg ich Feuer an die Tore, und dieses frißt die Burgen von Jerusalem, und niemand löscht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Das Wort, das einst an Jeremias vom Herrn ergangen ist, des Inhalts:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '\"Auf! Geh zum Töpferhaus hinab! Dort lasse ich dich meine Worte hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Da ging ich zu des Töpfers Haus; er machte eben eine Arbeit auf der Töpferscheibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Doch das Gefäß mißlang, das er mit Töpferhand aus Lehm sich fertigte. Da machte er daraus ein anderes Gefäß, so, wie zu fertigen dem Töpfer es beliebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '\"Vermag ich nicht, wie dieser Töpfer, auch mit euch zu tun? Ihr aus dem Hause Israel!\" Ein Spruch des Herrn. \"Fürwahr, was in des Töpfers Hand der Lehm, das seid ihr aus dem Hause Israel in meiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Ich drohe einem Volke, einem Reich, es auszurotten, zu vernichten, zu verheeren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Wenn aber dieses Volk von seiner Bosheit läßt, um deretwillen ich\'s ihm angedroht, dann lasse ich des Unheils mich gereuen, das ich ihm zuzufügen plante.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Und einem Volk und einem Reich verheiße ich, es aufzubauen, einzupflanzen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'tut es jedoch, was mir mißfällt, mißachtet meine Stimme, dann lasse ich des Guten mich gereuen, das ihm zu tun ich einst verheißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Nun aber sprich zu Judas Männern und zu Jerusalems Bewohnern: So spricht der Herr: \'Ich schaffe Unheil wider euch, und einen Plan entwerf ich gegen euch. Ein jeder lasse seinen schlimmen Weg! Und bessert euren Wandel, eure Werke!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Nun aber sagen sie: \'Das ist vergebens. Wir folgen lieber unseren Gedanken und folgen jeder nur dem Trotze seines argen Herzens.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Deshalb spricht so der Herr: \"Fragt bei den Heiden nach! Wer hörte schon dergleichen? Gar Schauerliches tat die Jungfrau Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Verläßt der Gletscher wohl den Berg, der Schnee den Libanon? Versickern wohl der Firne kühlfließende Gewässer?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Mich aber hat mein Volk vergessen; dem Nichtse räuchern sie. Denn man verführte sie auf ihren Wegen, auf altgewohnten Pfaden, daß sie auf andern Steigen gingen, auf ungebahnten Wegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'und so ihr Land zum Schrecken machten, zum immerwährenden Gespött. Wer dies durchwandert, hebt sein Haupt und schüttelt es verwundert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Ich jage sie, dem Ostwind gleich, vorm Feinde her. Den Rücken zeig ich ihnen, aber nicht das Angesicht am Tage ihrer Not.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Sie sprachen: \"Auf! So laßt uns gegen Jeremias Pläne schmieden! Die Lehre läßt den Priester nicht im Stich und nicht der Rat den Weisen und nicht das Wort den Seher. Auf! Laßt uns ihn für sein Gerede niederschlagen, auf keines seiner Worte achten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Auf mich, Herr, achte! Erhöre meine laute Klage!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Vergilt man denn mit Bösem Gutes, daß sie mir eine Grube graben? Denk doch daran, wie ich vor Dich getreten, Fürbitte für sie einzulegen, um Deinen Grimm von ihnen abzuwenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'So gib dafür dem Hunger ihre Kinder preis! Laß sie dem Schwert verfallen! Mach ihre Weiber kinderlos, zu Witwen! Laß ihre Männer von der Seuche hingewürgt und ihre Jünglinge im Kampf vom Schwert erschlagen werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Aus ihren Häusern töne Wehgeschrei, wenn Kriegerscharen plötzlich über sie Du bringst! Sie graben eine Gruft, um mich zu fangen, und legen meinen Füßen heimlich Schlingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Du aber, Herr, kennst alle ihre Todespläne gegen mich. Laß ihre Schuld nicht ohne Sühne, und ihre Sünde wische nimmer vor Dir aus! Sie seien Dir zum Anstoß! Bist Du im Zorn, gib Dich mit ihnen ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So sprach der Herr: \"Auf! Kauf dir einen Tonkrug von dem Töpfer! Und von den Ältesten des Volkes und der Priester nimm dir ein paar mit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Und zieh ins Hinnomstal, dort vor dem Scherbentor; dort ruf die Worte aus, die ich dir sage!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'So sprich zu ihnen: \'Vernehmt das Wort des Herrn, ihr Könige von Juda, und ihr Bewohner von Jerusalem! So spricht der Herr der Heerscharen, Gott Israels:\"Ich bringe Unheil über diesen Ort, daß jedem, der davon vernimmt, die Ohren gellen.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Sie lassen mich im Stich, verfremden diesen Ort und räuchern andern Göttern hier, die weder sie, noch ihre Väter, noch Judas Könige zuvor gekannt, und füllen diese Stätte mit dem Blut Unschuldiger');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'und bauen Höhen für den Baal, verbrennen ihre Söhne als Opfer für den Baal dort im Feuer. Das hab ich nie geboten, nie befohlen. Dies kam mir niemals in den Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Deshalb, fürwahr, erscheinen Tage\", ein Spruch des Herrn, \"wo dieser Ort nicht mehr Tophet, nicht Tal Ben Hinnoms heißt, nein: \'Würgetal\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Da will ich Judas Rat und den Jerusalems an diesem Ort zerschmettern und sie durchs Schwert vor ihren Feinden fällen, durch ihre Todfeinde, und ihre Leichen gebe ich zum Fraße hin den Vögeln unterm Himmel,den Tieren auf dem Felde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Ich mache diese Stadt zur Öde, zum Gespött. Wer sie durchzieht, erstaunt und spottet aller ihrer Schläge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Ich gebe ihnen ihrer Söhne Fleisch zu essen und ihrer Töchter Fleisch. Ein jeder ißt des andere Fleisch in Drang und Not, bedrängt von ihren Gegnern, ihren Todfeinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Darauf zerbrich den Krug im Beisein jener Männer, die mit dir gegangen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Und sprich zu ihnen: Also spricht der Heeresscharen Herr: \'Zerschmettern will ich dieses Volk und diese Stadt, wie man das irdene Gefäß zerschlägt; man kann\'s nicht mehr zusammensetzen. Im Tophet selbst wird man begraben aus Mangel an Begräbnisplatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Also verfahre ich mit diesem Ort\', ein Spruch des Herrn, \'mit denen, die darinnen wohnen. Ich mache diese Stadt zum Tophet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Unrein sind dann die Häuser von Jerusalem und die der Könige von Juda wie des Tophets Stätte unrein, ja, all die Häuser, auf deren Dächern sie geräuchert dem ganzen Himmelsheer und andern Göttern Trankopfer gespendet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Als Jeremias von dem Tophet kam, zu dem der Herr zum Weissagen ihn ausgesandt, betrat er in dem Haus des Herrn den Vorhof und sprach zum ganzen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '\"So spricht der Herr der Heerscharen, Gott Israels: \'Ich bringe über diese Stadt und über alle ihre Nebenstädte all jenes Unheil, das ich ihr angedroht. Denn sie versteifen ihren Nacken, auf meine Worte nicht zu achten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Da hörte Paschur, Immers Sohn, der Priester, der Oberaufseher im Haus des Herrn, den Jeremias diese Worte künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Da ließ Paschur den Propheten Jeremias stäupen und ihn legen in den Block, der bei dem oberen Tore Benjamins im Haus des Herrn gestanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Am andern Morgen aber, als Paschur Jeremias aus dem Block entließ, sprach Jeremias so zu ihm: \"Nicht \'Freudenreich\' heißt dich der Herr mehr, sondern \'Grauenvoll\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Denn also spricht der Herr: \'Ich mache dich zum Grauen für dich und alle deine Freunde. Sie fallen durch die Schwerter ihrer Feinde, und du mußt zusehen. Ganz Juda gebe ich dem Babelkönig preis, daß er nach Babel sie verschleppe und mit dem Schwerte schlage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Und allen Reichtum dieser Stadt hier geb ich preis und all ihr Gut und ihre Kostbarkeiten. Den ganzen Schatz der Könige von Juda geb ich in ihrer Feinde Hand, daß sie ihn plündern, rauben und hin nach Babel bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Du, Paschur, mußt mit allen deinen Hausgenossen in Gefangenschaft wegziehen. Du kommst nach Babel. Dort endest du, und dort wirst du begraben, samt allen deinen Freunden; denn Lügen hast du ihnen prophezeien lassen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Du locktest mich, o Herr: Ich ließ mich locken. Du packtest mich und bliebest Sieger. Nun bin ich täglich zum Gespött, und alles spottet über mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Sooft ich rede, muß ich schreien: \"Unbill!\", \"Gewalt!\" ausrufen. Das Wort des Herrn bringt Schimpf und Spott mir ein den ganzen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Und nehme ich mir vor: \"Ich denke nicht daran und rede nimmermehr in seinem Namen\", dann ist\'s in meinem Innern wie ein lodernd Feuer, ein körperlicher Zwang. Ich quäle mich, es auszuhalten und kann es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Ich höre viele zischeln: \"Grauenvoll!\" \"Sagt\'s nur, dann zeigen wir ihn an!\" - All meine Freunde lauern nur, ob ich nicht falle: \"Vielleicht läßt er sich locken; wir übermannen ihn und können Rache an ihm nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Doch ist der Herr mit mir, ein kühner Held. Die mich verfolgen, straucheln drum, und sie vermögen nichts. Mit großer Schande werden sie bedeckt, mit ewiger Schande unvergeßlich, weil es ihnen nicht gelingt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Du, Herr der Heeresscharen, Du gerechter Prüfer, der Du auf Herz und Nieren schaust! An ihnen schaue ich noch Deine Rache; ich habe meine Sache nur auf Dich gestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Lobsingt dem Herrn! Lobpreist den Herrn! Er rettet aus der Übeltäter Hand der Armen Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Verflucht der Tag, da ich geboren! Der Tag, da meine Mutter mich gebar, sei nicht gesegnet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Verflucht der Mann, der Kunde meinem Vater brachte: \"Geboren wurde dir ein kräftig Knäblein\", und ihn dazu beglückwünschte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Wär\'s diesem doch ergangen wie den Städten, die schonungslos der Herr vernichtet hat! Er hätte schon am Morgen ein Geschrei vernehmen sollen und Kriegslärm um die Mittagszeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Er ließ mich nicht im Mutterleibe sterben, daß meine Mutter mir mein Grab geworden, und immer hätte mich ihr Leib getragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Warum ging aus dem Mutterschoße ich hervor? Doch nur, um Gram und Kummer zu erleben und um in Schmach mein Leben zu beenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Das Wort, das einst vom Herrn an Jeremias erging, als König Sedekias den Paschur, Malkias Sohn, und den Priester Sephania, Maasejas Sohn, mit diesem Auftrag zu ihm sandte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '\"Befrage doch den Herrn für uns! Nebukadrezar Babels König, belagert uns. Ob wohl der Herr an uns nach seinen sonstigen, so wunderbaren Taten handeln wird, daß jener wiederum von uns abzöge?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Da sprach zu ihnen Jeremias: \"Meldet Sedekias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'So spricht der Herr, Gott Israels: \'Ich wende um das Kriegsgerät in eurer Hand, mit dem ihr gegen Babels König und gegen die euch drängenden Chaldäer kämpfet, weg von der Mauer und schaffe jenen Einlaß in das Innere dieser Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Ich selber kämpfe gegen euch mit ausgereckter Hand und starkem Arm in Zorn, im Grimm und in gewaltiger Wut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Ich schlage dieser Stadt Bewohner nieder, die Menschen wie das Vieh durch fürchterliche Pest, daß sie dem Tod verfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Dann geb ich Sedekias, Judas König, preis\', ein Spruch des Herrn, \'und seine Diener und das Volk, die in der Stadt verschont geblieben sind von Pest und Schwert und Hunger, dem Babelkönige Nebukadrezar und ihren Gegnern, ihren Todfeinden. Er soll sie mit dem Schwerte niedermetzeln, des Mitleids, des Erbarmens und der Schonung bar.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Zu diesem Volke aber sprich: So spricht der Herr: \'Ich stelle euch zur Wahl den Weg zum Leben und den Weg zum Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Wer hier in dieser Stadt verbleibt, stirbt durch das Schwert, den Hunger und die Pest. Wer aber geht und übertritt zu den Chaldäern, die euch bedrängen, der wird leben; zur Beute wird ihm so sein Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Ich richte gegen diese Stadt mein Angesicht zum Unheil, nicht zum Heil.\' Ein Spruch des Herrn. \'Sie fällt dem Babelkönig in die Hände, daß er sie niederbrenne.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Zum Königshaus von Juda aber sprich: Vernimm das Wort des Herrn, du Davidshaus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'So spricht der Herr: \'An jedem Morgen richtet in Gerechtigkeit! Und rettet den Beraubten vor dem Dränger! Sonst bricht mein Grimm wie Feuer los und brennt, und niemand löscht, der Bosheit eurer Taten wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Fürwahr, ich will an dich, Bewohnerin des hohen, steilen Felsens!\' Ein Spruch des Herrn. \'Ihr, die ihr sprecht: \"Wer kann uns überfallen? Wer kann in unsre Wohnungen eindringen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Ich zahle euch den Lohn für eure Taten\', ein Spruch des Herrn, \'und ihren Wald verbrenne ich mit Feuer, und dies frißt alles ringsumher.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So spricht der Herr: \"Ins Haus des Judakönigs steig hinab! Dort rede dieses Wort');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'und sprich: Vernimm das Wort des Herrn, du Judakönig, der du auf Davids Throne sitzest, samt deinen Dienern, deinem Volke, die ihr durch diese Tore geht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So spricht der Herr: \'Tut Recht und handelt nach Gerechtigkeit und rettet den Beraubten vor dem Dränger! Bedrängt nicht Fremde, Waisen, Witwen! Tut keine Grausamkeit! Unschuldig Blut vergießet nicht an diesem Ort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Nur wenn ihr solches tut, betreten dieses Hauses Tore Könige, die auf dem Davidsthrone sitzen, zu Wagen und zu Roß, er selbst wie seine Diener und sein Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Doch, hört ihr nicht auf diese Worte, dann schwör ich bei mir selbst\', ein Spruch des Herrn: \'Ein Trümmerort wird dieses Haus.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Ja, also spricht der Herr vom königlichen Hause Juda: \'Bist du mir auch ein Gilead und wie ein Fürst des Libanon, so mach ich dennoch dich zur Wüste mit unbewohnten Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Verderber werde ich herrufen gegen dich, jeden mit seinem Beile, auf daß sie deine allerschönsten Zedern fällen und sie ins Feuer werfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Und ziehn an dieser Stadt vorüber viele Völker und fragen sie einander: \"Warum tat so der Herr mit dieser großen Stadt?\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'so wird man sagen: \"Sie hat den Bund des Herren, ihres Gottes, aufgegeben und andere Götter angebetet und verehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Beweinet nicht den Toten! Klagt nicht um ihn! Beweinet den, der fortgezogen! Denn er sieht nimmermehr das Land, wo er geboren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Denn also spricht der Herr von Sallum, einem Sohn des Judaköniges Josias, der an Stelle des Josias, seines Vaters, König ward: \'Der fort von diesem Ort gezogen, kommt nicht wieder her;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'er stirbt vielmehr an jenem Ort, wohin sie ihn verschleppt, und dieses Land sieht er nicht mehr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Weh dem, der sich sein Haus mit Ungerechtigkeit erbaut, mit Unrecht seine Söller; der seinen Nächsten ohne Entgelt fronen läßt und seinen Lohn ihm vorenthält,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'der spricht: \"Ich baue mir ein massig Haus und luftige Gemächer\", der Fenster darin ausbricht, es mit Zedernholz verbälkt und rot bemalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Hast dazu du das Königtum, daß du in Zedern wetteiferst? Hat nicht dein Vater, wie er aß und trank, geradeso Gerechtigkeit und Recht geübt? Da ging\'s ihm gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Er schaffte Armen und Bedrückten Recht: Da ging\'s ihm wohl. \"Gilt dies bei mir nicht für vernünftig?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Doch deine Augen und dein Sinn sind einzig auf Gewinn gerichtet und aufs Vergießen von unschuldigem Blut, aufs Drücken und aufs Knicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Darum spricht so der Herr von Jojakim, dem Sohn des Judakönigs Josias: \"Ihn wird man nicht bejammern: \'Ach mein Bruder! Der Brüderlichkeit wehe!\' Ihn wird man nicht bejammern: \'Ach Gebieter! Wehe seiner Herrschergröße!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Wie einen Esel man begräbt, wird er begraben; man schleppt ihn fort und wirft ihn hin weit draußen vor den Toren von Jerusalem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Besteig den Libanon! Klag laut! In Basan laß die Stimme schallen! Schrei von den Uferbergen her! Dahin sind deine Lieblinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Ich warnte dich in deiner Blütezeit. Du sprachst: \"Ich mag nichts hören\". Dies war dein Weg von Jugend an; du hörtest nie auf meine Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'All deine Freunde tilgt ein Sturm, und wer dich liebt, der wird verschleppt. Beschämt wirst du, beschimpft wegen der Schlechtigkeit all deiner Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Du wohnst auf einem Libanon, in Zedern eingenistet. Wie sinkst du hin, wenn Wehen dich befallen, ein Zittern, wie bei Kreißenden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, '\"So wahr ich lebe\", ein Spruch des Herrn, \"wenn auch Konjahu, Sohn des Jojakim, der Judakönig, ein Siegelring an meiner Rechten wäre, ich risse dich doch weg von da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Ich liefre dich an deinen Todfeind aus, vor dem dir graut, an Nebukadrezar, den Babelkönig, und an die Chaldäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Ich schleudre dich samt deiner Mutter fort, die dich geboren, in ein fremdes Land, in dem ihr nicht geboren seid. Dort sollt ihr sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Sie aber kehren niemals wieder in das Land zurück, in das sie gerne möchten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ist ein so armselig, gewöhnlich Ding der Mann Konjahu da? Ein Ding, das niemandem gefällt? Weswegen wurden er und sein Geschlecht weit fortgeschleudert in ein Land, das sie nicht kannten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Land! Land! Land! Vernimm das Wort des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So spricht der Herr: \"Schreibt diesen Mann als Kinderlosen auf, als einen Menschen, der kein Glück im Leben hat! Denn niemals wird es einem seines Stammes glücken, auf Davids Thron zu sitzen und über Juda wiederum zu herrschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '\"Ein Wehe jenen Hirten, die meine anvertraute Herde verwahrlosen und sich verlaufen lassen!\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Darum spricht so der Herr, Gott Israels, von diesen Hirten, die mein Volk so weiden: \"Ihr habt die Schafe mein zerstreut, versprengt. Ihr habt euch nicht darum gekümmert. Ich aber kümmere mich um euch und eurer Werke Schlechtigkeit.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, '\"Ich sammle selber meiner Herde Rest aus all den Ländern, in die ich sie zerstreut, und führe sie auf ihre Auen wieder, auf daß sie wachsen und gedeihen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'und stelle Hirten über sie, um sie zu weiden. Nicht Furcht, nicht Schrecken fällt auf sie; man braucht sie nicht mehr aufzusuchen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, '\"Fürwahr, es kommen Tage\", ein Spruch des Herrn, \"wo ich für David einen echten Sproß erwecke. Als König herrscht er weise und hält im Lande auf Gerechtigkeit und Recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'In seinen Tagen fühlt sich Juda glücklich, und Israel wohnt sicher. So ist sein Name: \'Der Herr ist unser Heil\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Jawohl, es kommen Tage\", ein Spruch des Herrn, \"da sagt man nicht mehr \'Bei dem Herrn, der aus Ägypterland die Söhne Israels herausgeführt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Vielmehr \'Beim Herrn, der die Zerstreuten des Hauses Israels herausgeführt und hergebracht hat aus dem Land des Nordens und aus den andern Ländern all, in die ich sie verstoßen habe.\' Sie siedeln abermals auf ihrer Scholle.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Der Seher wegen bricht das Herz in mir; alle Gebeine schlottern. Ich gleiche einem trunkenen Mann, solch einem, den der Wein bezwang, vorm Herrn, vor seinen heiligen Worten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Das Land ist voll von Ehebrechern; denn ihretwegen schmachtet hin das Land und sind der Steppe Auen ausgedörrt. Ihr Streben war nur Schlechtigkeit und ihre Stärke Unwahrhaftigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, '\"Die Seher wie die Priester sind gleicherweise ruchlos; sogar in meinem Hause finde ich ihr wüstes Treiben.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, '\"So sei denn auch ihr Weg gleich schlüpferigen Pfaden in der Dunkelheit! Sie sollen stolpern drauf und fallen; denn Unheil bring ich über sie im Jahre ihrer Heimsuchung.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, '\"Recht Albernes sah ich schon bei Samarias Propheten. Sie weissagten beim Baal und führten irre Israel, mein Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Doch bei den Sehern von Jerusalem sah ich Abscheuliches. Die Ehe brechen und mit Lüge handeln den frevlen Mut bestärken, daß keiner sich von seiner Schlechtigkeit bekehre! Sie alle gelten mir wie Sodoma und wie Gomorrha und wie die dortigen Bewohner.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Drum spricht der Herr der Heeresscharen wider die Propheten: \"Zur Speise geb ich ihnen Wermut und Bitterwasser zum Getränk. Denn von Jerusalems Propheten ging die Gemeinheit aus durchs ganze Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'So spricht der Heeresscharen Herr: \"Nicht auf die Worte der Propheten hört, die euch weissagen! - Sie schmeicheln eurer Eitelkeit und künden selbstersonnene Gesichte, durchaus nicht aus dem Mund des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Sie sprechen immerfort zu denen, die von mir nichts wissen wollen: \'Der Herr hat es gesagt: Ihr werdet Frieden haben\', und jedem, der in seines Herzens Trotze wandelt, dem sagen sie: \'Euch trifft nichts Schlimmes.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Wer steht im Rat des Herrn, daß er Gesichte hätte, seine Worte hörte? Wer achtet auf mein Wort und wer vernimmt es?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Der Sturm des Herrn, ein heißer Wind, bricht los, ein Sturm, ums Haupt der Frevler wirbelnd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Der Zorn des Herrn gibt keine Ruhe, bis er vollführt hat und vollbracht, was er geplant. Am Schluß der Tage werdet ihr das klar erkennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Ich habe die Propheten nicht gesandt, und dennoch haben sie es eilig. Zu ihnen hab ich nie gesprochen, und dennoch prophezeien sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Wenn sie in meinem Rat gestanden, dann brächten sie auch meine Worte meinem Volke zu Gehör und führten es von seinem schlimmen Wege heim, von seinen schlechten Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Bin ich denn Gott nur für die Nähe?\" Ein Spruch des Herrn. \"Und nicht ein Gott auch für die Ferne?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Verbärge sich ein Mann im tiefsten Winkel, ich sollt ihn nicht bemerken?\" Ein Spruch des Herrn. \"Erfülle ich denn nicht den Himmel und die Erde?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, '\"Was die Propheten sagen, höre ich, die unter meinem Namen Lüge prophezeien: \'Mir hat geträumt. Mir hat geträumt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Wie lange noch? Ist\'s in der Absicht der Propheten, Lug zu künden und selbstersonnenen Betrug zu prophezeien?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Ob sie wohl planen, aus dem Gedächtnis meines Volkes meinen Namen auszumerzen durch ihre Träume, die sie sich erzählen, wie ihre Väter meinen Namen über dem Baal vergaßen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Der Seher, dem ein Traum bekannt, erzähle seinen Traum, und wem mein Wort zuteil geworden, berichte es getreu als Wort von mir! Was soll das Stroh beim Korn?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, '\"Ist denn mein Wort nicht feuergleich?\" Ein Spruch des Herrn. \"Zerschlägt es nicht gleich einem Hammer Felsgestein?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Darum will ich an die Propheten,\" ein Spruch des Herrn, \"die meine Worte voneinander stehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Ich will an die Propheten\", ein Spruch des Herrn, \"die ihre Zunge nehmen und Gottessprüche murmeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Ich will an die Propheten trügerischer Träume,\" ein Spruch des Herrn, \"die sie erzählen und in die Irre führen durch ihre Lügen mein Volk, durch ihr Geflunker. Ich aber hab sie nie gesandt und ihnen nichts befohlen. Sie können diesem Volk nichts nützen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, '\"Und fragt dich dieses Volk, sei\'s Priester, sei\'s Prophet: \'Was ist das lästige Zeug des Herrn?\' - so sprich zu ihnen: \'Ihr seid das lästige Zeug. Wegwerfen will ich euch,\'\" ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, '\"Propheten, Priester und das Volk, wer immer redet von dem lästigen Zeug des Herrn, den strafe ich samt seinem ganzen Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'So sollt ihr zueinander sagen, der eine zu dem andern so: \'Was gab der Herr zur Antwort? Was hat der Herr gesprochen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Vom lästigen Zeug des Herrn sollt ihr nicht weiter sprechen! Sonst wird sein Wort zu lästigem Zeug für jeden, verdreht ihr doch die Worte des lebendigen Gottes, des Herrn der Heeresscharen, unseres Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'So sollst du zum Propheten sagen: \'Was hat zur Antwort dir der Herr gegeben?\' Und \'Was der Herr gesprochen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Doch sprechet ihr vom lästigen Zeug des Herren, dann spricht also der Herr: \'Weil ihr den Ausdruck \"Lästiges Zeug des Herrn\" gebraucht, obschon ich euch entbieten ließ: \"Ihr sollt vom lästigen Zeug des Herrn nicht reden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Deswegen hebe ich euch in die Höhe und schleudere euch hinweg mitsamt der Stadt, die euch und euren Vätern ich gegeben habe, hinweg von meinem Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Mit ewiger Schmach beleg ich euch, mit ewigem Schimpf, der nie vergessen wird.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Da ließ der Herr mich schauen: Zwei Feigenkörbe standen da, bezeichnet, vor des Herren Tempel, nachdem Nebukadrezar, der Babelkönig, den Jechonias, Sohn des Jojakim, den Judakönig, und Judas Fürsten samt den Schmieden und den Schreinern fort von Jerusalem geführt und sie nach Babel hingebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Der eine Korb enthielt sehr gute Feigen, den frühen Feigen gleich; der andre Korb sehr schlechte Feigen, ganz ungenießbar, weil verdorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Da sprach der Herr zu mir: \"Was siehst du, Jeremias?\" Ich sagte: \"Feigen! Die guten Feigen sind sehr gut, die schlechten äußerst schlecht, ganz ungenießbar, weil verdorben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '\"So spricht der Herr, Gott Israels: Wie diese guten Feigen hier, so will ich die Verschleppten Judas gutheißen, die ich von diesem Orte ins Chaldäerland geschickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Auf diese richte ich mein Auge freundlich und bringe sie zurück in dieses Land. Denn bauen will ich, nicht vernichten, einpflanzen und nicht ausreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Ich schenke ihnen Einsicht, daß sie merken, daß ich der Herr bin. Sie dienen mir alsdann zum Volk und ich zum Schutzgott ihnen, wenn sie aus ganzem Herzen sich zu mir bekehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Doch gleich den schlechten Feigen, die verdorben, ungenießbar sind\", so spricht der Herr, \"will ich den König Judas, Sedekias, seine Fürsten, sowie den Rest Jerusalems behandeln, die noch in diesem Lande übrig sind, samt denen im Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Ich mache sie zu bösem Schreckensbild für alle Reiche auf der Erde. Dem Schimpf und Spott, dem Hohn und der Verwünschung geb ich preis sie überall, wohin ich sie verstoße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Ich sende unter sie das Schwert, den Hunger und die Seuche, bis sie vertilgt vom Boden, den ich ihnen wie ihren Vätern einst verliehen habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Das Wort, das an Jeremias über das ganze Volk Juda erging im vierten Jahre des Judakönigs Jojakim, des Josiassohns, das ist im ersten Jahre des Babelkönigs Nebukadrezar,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'das Jeremias, der Prophet, dem ganzen Volke Juda und an alle Einwohner Jerusalems verkündet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, '\"Vom dreizehnten Jahr des Ammonssohns und Judakönigs Josias bis auf diesen Tag, nun dreiundzwanzig Jahre lang, erging das Wort des Herrn an mich. Und ich sprach unermüdlich zu euch; ihr aber hörtet nicht darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'All seine Diener, die Propheten, hat unablässig euch der Herr gesandt. Ihr aber hörtet nicht darauf, noch neigtet ihr das Ohr zum Hören:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, '\'Kehrt um, ein jeglicher von seinem schlimmen Weg, von eurem bösen Treiben! Dann dürft ihr in dem Land für alle Zeit verbleiben, das euch und euren Vätern einst der Herr verliehen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Lauft nicht den andern Göttern nach, sie zu verehren, sie anzubeten! Verdrießt mich nicht mit eurer Hände Werk! Dann will ich euch nicht wehe tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ihr aber höret nicht auf mich,\' ein Spruch des Herrn, \'verdrießet mich durch eurer Hände Werk euch zum Verderben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Deshalb spricht so der Herr der Heeresscharen: \'Weil ihr auf meine Worte nicht gehört,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'hol ich des Nordens Sippen alle her\', ein Spruch des Herrn, \'zum Babelkönig, meinem Knecht Nebukadrezar. Ich laß sie gegen dieses Land, seine Bewohner und gegen alle Völker ringsum ziehen und banne sie und mache sie zum Spott und Schrecken und zu ewiger Verödung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Aus ihnen banne ich des Lachens und der Lust Gejohle, den Sang des Bräutigams, den Brautgesang, der Mühle Lärm, der Lampe Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'So wird dies ganze Land zur Wüste und zur Öde, und diese Völker müssen Babels König dienstbar sein an siebzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Doch sind erfüllt die siebzig Jahre, dann such ich heim den Babelkönig und auch jenes Volk\', ein Spruch des Herrn, \'und strafe ihre Missetat an der Chaldäer Land und mache es zur ewigen Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Ich lasse kommen über dieses Land all meine Drohungen, die ich dawider ausgesprochen, alles, was in diesem Buch geschrieben steht, was über alle Völker Jeremias prophezeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Auch diese werden großen Völkern untertan und großen Königen, und so vergelte ich auch ihnen je nach ihrem Tun und ihrer Hände Werk.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Denn also sprach der Herr, Gott Israels, zu mir: \"Aus meiner Hand nimm diesen Zornweinbecher und reiche ihn zum Trinken allen Völkern, zu denen ich dich sende!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Sie sollen trinken, taumeln, tollen im Angesicht des Schwertes, das ich mitten unter sie entsende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Ich nehme aus der Hand des Herrn den Becher und reiche ihn zum Trinken all den Völkern, zu denen mich der Herr gesandt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalem und Judas andern Städten und ihren Königen und Fürsten, um diese der Verwüstung und Verheerung, dem Hohn und der Verwünschung preiszugeben, wie es heute ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Hernach dem Pharao, Ägyptens König, seinen Dienern und seinen Fürsten, seinem ganzen Volke');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'und ganz Arabien und allen Königen des Landes Us und allen Königen des Landes der Philister Und Askalon und Gaza, Akkaron, dem Reste Asdods');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'und Edom, Moab und den Ammonitern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'und allen Königen von Tyrus und allen Königen von Sidon und allen Königen der Küstenländer, die überm Meere lagern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedan, Tema, Bus und allen mit gestutztem Haar');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'und allen Königen Arabiens und all den Königen Arabiens, die in der Wüste wohnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'und allen Königen von Gamir und allen Königen von Elam und allen Königen von Medien');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'und allen Königen des Nordens, den nahen wie den fernen, kurz allen Königreichen auf der Welt, die auf der Erde sind. Nach ihnen aber muß der König Sesaks trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '\"Zu ihnen sprich dabei: So spricht der Heeresscharen Herr, Gott Israels: \'Trinkt doch! Berauscht euch! Speit! Stürzt hin! Steht nimmer auf vorm Schwert, das ich in eure Reihen sende!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Und sollten sie sich weigern, aus deiner Hand den Kelch zum Trinken anzunehmen, dann sprich zu ihnen: Also spricht der Heeresscharen Herr: \'Ihr müsset trinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Ich mache bei der Stadt, die meinen Namen trägt, den Anfang mit den Strafen. Ihr aber wolltet frei ausgehen? Nein! Ich rufe gegen alle Erdbewohner ein Schwert auf.\'\" Ein Spruch des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, '\"Künd ihnen alles dies! So sprich zu ihnen: \'Von oben brüllt der Herr; von seinem heiligen Sitze donnert er. Gar furchtbar brüllt er über sein Gefilde, er jauchzt wie Keltertreter, singt wider alle Erdbewohner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Bis an den Erdrand dringt das Tosen; der Herr hat mit den Heidenvölkern Streit. Mit allem Fleische geht er ins Gericht; dem Schwert gibt er die Frevler preis.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So spricht der Heeresscharen Herr: \"Von Volk zu Volk schreitet das Unheil, erwacht ein großer Sturm vom Rand der Erde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'An jenem Tage liegen die vom Herrn Erschlagenen von einem Erdrand bis zum andern da; sie werden nicht beklagt, nicht aufgehoben, nicht begraben; dem Acker dienen sie als Dünger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, '\"Ihr Hirten, weinet! Schreit! Im Staube wälzt euch, ihr, der Herde Führer! Denn eure Tage sind erfüllt zur Schlachtung; zerstückelt werdet ihr. Ihr liegt in Scherben wie ein zerbrechliches Gefäß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Und für die Hirten gibt es keine Zuflucht mehr und kein Entrinnen für die Führer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Horch, wie die Hirten schreien, die Herdenführer heulen! Der Herr verwüstet ihren Weideplatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Vernichtet sind die friedlichen Gefilde vor diesem Flammenzorn des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Wie hat der Löwe seinen Schlupf verlassen? Denn eine Wüste ward ihr Land vom Zorn des Fürchterlichen, vor seinem Flammenzorn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Am Anfang der Regierung Jojakims, des Sohnes des Josias, des Judakönigs, ist dieses Wort vom Herrn ergangen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So spricht der Herr: \"Betritt den Vorhof in dem Haus des Herrn und sprich zu all den Leuten aus den Städten Judas, die in das Haus des Herrn zur Anbetung gekommen sind, all diese Worte, die ihnen zu verkünden ich dir anbefehle! Kürze nicht ein Wort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Sie hören doch vielleicht und kehren um, ein jeglicher von seinem schlimmen Weg; dann laß ich mich des Unheils auch gereuen, das ich beschlossen, ihnen anzutun, um ihrer bösen Taten Willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Nun sprich zu ihnen: Also spricht der Herr: \'Ihr höret nicht auf mich und lebet nicht nach meiner Lehre, die ich euch vorgelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Ihr hört nicht auf die Worte der Propheten, meiner Diener, die ich euch sende und unermüdlich sandte, und doch wollt ihr nicht hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Drum mache ich dies Haus hier dem zu Silo gleich, und gebe allen Völkern auf der Erde diese Stadt hin zur Verwünschung.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Die Priester und Propheten und die ganze Menge waren Zeuge, wie Jeremias diese Worte in dem Haus des Herrn verkündete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Und Jeremias trug all das, was ihn der Herr geheißen, dem ganzen Volke vor. Da packten ihn die Priester und Propheten und das Volk und schrien: \"Jetzt mußt du sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Warum weissagst du also in des Herren Namen: \'Wie dem zu Silo soll es diesem Haus ergehen\' und \'Diese Stadt soll wüst und ganz entvölkert werden\'?\" So rottete sich alles Volk zusammen wider Jeremias in dem Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Als aber Judas Fürsten davon hörten, gingen sie vom Haus des Königs in das Haus des Herrn und ließen sich am Eingange des neuen Herrentores nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Da sprachen die Propheten und die Priester zu den Fürsten und zum gesamten Volke so: \"Des Todes schuldig ist der Mann, hat er doch gegen diese Stadt geweissagt, wie ihr es selbst gehört.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Doch Jeremias sprach zu all den Fürsten wie zum ganzen Volke so: \"Mich hat der Herr gesandt, um gegen dieses Haus und diese Stadt all jene Worte, die ihr vernommen habt, zu weissagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'So bessert euren Wandel, eure Werke! Hört auf des Herren, eures Gottes, Stimme, daß sich der Herr das Unheil mög gereuen lassen, das er euch angedroht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Was mich betrifft, so bin ich hier in eurer Hand. Verfahrt mit mir, wie\'s gut und billig euch erscheint!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Nur wißt, falls ihr mich tötet, daß ihr unschuldig Blut bringt über euch und diese Stadt und ihre Einwohner! In Wahrheit sandte mich der Herr zu euch, in eurer Gegenwart all diese Worte zu verkünden.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Da sprachen nun die Fürsten und das ganze Volk zu den Propheten und den Priestern: \"Der Mann ist keineswegs des Todes schuldig, sprach er zu uns doch in des Herren, unseres Gottes, Namen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Da traten von den Ältesten des Landes Männer auf und sprachen zu der ganzen Volksgemeinde:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '\"Michaeas, der aus Maresa stammte, trat als Prophet zur Zeit des Judakönigs Ezechias auf und sprach zum ganzen Volk von Juda so: \'So spricht der Heeresscharen Herr: Zum Feld wird Sion umgepflügt, Jerusalem ein Trümmerhaufen, Gestrüpp der Berg des Hauses.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Hat Judas König Ezechias und das gesamte Juda ihn zum Tod geführt? Hat man sich nicht vielmehr vorm Herrn gefürchtet und sich bemüht, ihn zu versöhnen, so daß der Herr des Unheils, das er ihnen angedroht, sich wiederum gereuen ließ? Und wir sind im Begriff, ein großes Unrecht zu verüben, uns selbst zum Leid?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Auch noch ein andrer prophezeite in des Herrn Namen, Urias, des Semaja Sohn, aus Kirjatjearim, und zwar weissagte dieser gegen diese Stadt und dieses Land im Einklang mit des Jeremias Reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Der König Jojakim und alle seine Krieger und all die Fürsten hörten seine Reden. Da wollte ihn der König töten lassen. Als nun Urias dies erfuhr, ward er von Furcht erfüllt, ergriff die Flucht und kam so nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Da sandte König Jojakim von seinen Leuten nach Ägypten, Elnatan, Akbors Sohn, und andre mit ihm nach Ägypten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Sie holten den Urias aus Ägypten und brachten ihn zum König Jojakim, und dieser ließ ihn mit dem Schwerte richten und seinen Leichnam in das Grab der Findlinge wegbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Doch Saphans Sohn, Achikam, schützte Jeremias; so gab man ihn dem Volke nicht zur Tötung preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Im vierten Jahre der Regierung des Judakönigs Sedekias, des Josiassohnes, erging das Wort des Herrn an Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'So sprach der Herr zu mir: \"Verschaff dir Stricke und Jochhölzer und leg sie auf den Hals!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Dann schicke etliche davon an Edoms und an Moabs König und an den Ammoniterkönig, an Sidons König und an den von Tyrus, durch Gesandte, die den Juda König Sedekias in Jerusalem besuchen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Trag ihnen auf, daß ihren Herrn sie folgendes berichten: \'So spricht der Herr der Heerscharen, Gott Israels: So sollt ihr euren Herren sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, '\"Ich schuf die Erde und die Menschen und das Vieh auf Erden durch meine große Kraft und schenkte sie an den, der mir gefiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'So schenk ich jetzt all diese Länder dem Babelkönig, Nebukadrezar, meinem Diener, und selbst das Wild des Feldes schenk ich ihm zu seinen Diensten. Die Völker sollen alle dienstbar sein');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'ihm, seinem Sohn und Enkel, bis auch die Zeit für sein Land kommt und starke Völker, große Könige ihn dienstbar machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Das Volk und Reich, das nicht dem Babelkönig Nebukadrezar dienen will und seinen Hals nicht in das Joch des Babelkönigs steckt, dies Volk bestrafe ich mit Schwert, mit Hunger und mit Pest\", ein Spruch des Herrn, \"bis ich\'s durch ihn vernichtet habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Ihr aber, hört doch nicht auf eure Propheten, Wahrsager, Traumausleger, Zeichendeuter, Zauberer, die euch verkünden: \'Dient nicht dem Babelkönig!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Denn Lüge prophezeien sie; so kommt\'s dahin, daß sie um euer Land euch bringen, daß ich euch wegschleppe zu eurem Untergang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Das Volk indes, das seinen Hals ins Joch des Babelkönigs steckt zu seinem Dienst, das lasse ich in seinem Lande.\' Ein Spruch des Herrn. \'Es soll das Land bebauen und bewohnen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Das gleiche sagte ich zu Judas König Sedekias: \"Ins Joch des Babelkönigs stecket eure Hälse! Ihm dient und seinem Volke! Darin bleibet ihr am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Warum wollt ihr denn sterben, du und dein Volk, durch Schwert, durch Hunger und durch Pest? Hat solches doch der Herr dem Volke angedroht, das nicht dem Babelkönig dienen will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Hört nicht auf der Propheten Reden, die also zu euch sprechen: \'Ihr müßt dem Babelkönige nicht dienen\'! Denn Lügen prophezein sie euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, '\'Denn ich habe sie nicht gesandt\', ein Spruch des Herrn, \'und Lügen prophezeien sie in meinem Namen, damit ich euch versprenge und die Seher, die euch prophezeien.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Den Priestern aber sagte ich sowie dem ganzen Volke: \"So spricht der Herr: Auf eurer Seher Reden höret nicht, die so euch prophezeien: \'In aller Bälde werden die Geräte für das Haus des Herrn zurückgebracht aus Babel\'. Nur Lüge prophezein sie euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Hört nicht auf sie! Dem Babelkönig dienet! Dann bleibet ihr am Leben. Warum soll diese Stadt zur Wüste werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Sind sie jedoch Propheten, steht ihnen zu Gebot das Wort des Herrn, dann mögen sie zum Herrn der Heeresscharen flehen, daß die Geräte, die im Haus des Herrn und in dem Haus des Judakönigs und in Jerusalem vorhanden, nicht nach Babel kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Denn solches spricht der Herr der Heerscharen von Säulen, Meer und Stühlen, vom Reste der Geräte, die in dieser Stadt verbleiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'und die der Babelkönig Nebukadrezar noch nicht weggeführt. Den Jojachin, den Sohn des Jojakim, den Herrscher über Juda, verschleppte er nach Babel aus Jerusalem, samt allen Edlen Judas und Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'So spricht der Herr der Heerscharen, Gott Israels, jetzt über die im Haus des Herrn verbliebenen Geräte und über die im Haus des Königs über Juda und Jerusalem:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '\'Nach Babel werden sie gebracht. Dort bleiben sie bis zu dem Tag, da ich sie aufsuche\', ein Spruch des Herrn, \'und wieder herfahre und sie an diesen Ort verbringe.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Im selben Jahr geschah es, im Anfang der Regierung des Judakönigs Sedekias, im vierten Jahr, im fünften Monat, daß Ananias, Azzurs Sohn, der Seher, der aus Gibeon stammt, im Haus des Herrn so zu mir sprach, in Gegenwart der Priester und des ganzen Volkes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '\"So spricht der Herr der Heerscharen, Gott Israels: \'Zerbrechen werde ich das Joch des Babelkönigs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Nur noch ein Jahrespaar, dann bringe ich an diesen Ort zurück all die Geräte für das Haus des Herrn, die einst Nebukadrezar, Babels König, von diesem Orte fort nach Babel bringen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Auch Judas König Jojachin, den Sohn des Jojakim, und die nach Babel abgeführte Mannschaft Judas bring ich heim an diesen Ort\', ein Spruch des Herrn; \'des Babelkönigs Joch zerbreche ich.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Darauf sprach Jeremias, der Prophet, zu Ananias, dem Propheten, in Gegenwart der Priester und des ganzen Volks, das in dem Haus des Herren stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Sprach Jeremias, der Prophet: \"So sei\'s! So tue nur der Herr! Der Herr erfülle deine Worte, die du geweissagt hast! Ach, brächte er aus Babel die Geräte für das Haus des Herrn und alle die Gefangenen an diesen Ort zurück!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Doch hör dies Wort! Ich sag es laut vor dir und allem Volke aus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Die Seher, die vor mir und dir, von alters her gelebt, weissagten vielen Ländern, großen Reichen von Krieg und Not und Pest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Doch der Prophet, der Heil weissagt, kann erst als Seher sich ausweisen, als ein vom Herrn in Wahrheit Ausgesandter, wenn sich das Seherwort erfüllt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Darauf nahm Ananias, der Prophet, das Jochholz von dem Hals des Jeremias, des Propheten, und zerbrach es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Darauf sprach Ananias in Gegenwart des ganzen Volkes: \"So spricht der Herr: \'Also zerbreche ich das Joch Nebukadrezars, des Babelkönigs, noch vor dem Ablauf eines Jahrespaares und nehme es vom Nacken aller Völker weg.\'\" Doch Jeremias, der Prophet, ging seines Wegs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Darauf erging das Wort des Herrn an Jeremias, dem der Seher Ananias das Jochholz von dem Hals zerbrochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '\"Auf! Sprich zu Ananias! So spricht der Herr: \'Ein hölzern Joch hast du zerbrochen, an seine Stelle setzest du ein eisernes.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Denn also spricht der Herr der Heerscharen, Gott Israels: \'Ich leg ein eisern Joch dem Halse aller dieser Völker auf. Sie müssen dienstbar sein und bleiben dem Nebukadrezar, Babels König; ich gebe ihm auch noch des Feldes Tiere.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Darauf sprach Jeremias, der Prophet, zu dem Propheten Ananias: \"Hör, Ananias! Hör! Der Herr hat niemals dich gesandt, und doch hast du dies Volk verleitet, auf Lüge zu vertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'So spricht deshalb der Herr: \'Ich schaffe dich von dieser Erde weg. Du stirbst noch dieses Jahr, weil du empfohlen, sich dem Herrn zu widersetzen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Und noch im selben Jahr, im siebten Monat, starb Ananias, der Prophet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Das ist der Inhalt des Schreibens, das Jeremias, der Prophet, von Jerusalem aus an den Rest der Ältesten in der Verbannung, an Priester und Propheten und an das ganze Volk absandte, das Nebukadrezar aus Jerusalem nach Babel weggeführt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'nachdem der König Jojachin, sowie die Herrin und die Kämmerer, die Fürsten Judas und Jerusalems, die Schmiede und die Schreiner Jerusalem verlassen hatten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'durch Vermittlung Elasas, des Sohnes Saphans, und Gemarjas, Chelkias\' Sohn, die Judas König Sedekias zu Nebukadrezar, Babels König, nach Babel sandte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '\"So spricht der Herr der Heerscharen, Gott Israels, zu allen den Gefangenen, die ich nach Babel aus Jerusalem verpflanzt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '\'Baut Häuser! Wohnt darin! Legt Gärten an! Eßt ihre Früchte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Heiratet! Zeugt Söhne, Töchter! Auch für eure Söhne nehmet Weiber! Gebt Männern eure Töchter, daß sie von Söhnen und von Töchtern Mütter werden und ihr daselbst euch mehret und nicht mindert!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Ein Wohlergehen wünscht der Stadt, in die ich euch verpflanzt, betet zum Herrn für sie! Ihr Wohl ist euer Wohl.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'So spricht der Herr der Heerscharen, Gott Israels: \'Laßt nimmer euch verführen von euren Sehern unter euch, von euren Wahrsagern! Auf eure Traumerzähler höret nicht, die ihr zum Träumen aufgestellt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Denn Lüge prophezein sie euch in meinem Namen. Ich habe sie ja nicht gesandt.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Vielmehr spricht so der Herr: \'Verfließen volle siebzig Jahre erst für Babel, dann suche ich euch heim, und ich erfülle dann mein freundlich Wort an euch und bring euch noch einmal an diesen Ort zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Ich kenne selbst die Pläne, die ich plane über euch.\' Ein Spruch des Herrn. \'Heilspläne sind es, nicht zum Leide, euch hoffnungsvolle Zukunft zu gewähren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Wenn ihr mich anruft, oftmals zu mir betet, so will ich euch erhören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Ihr findet mich, falls ihr mich suchet. Ja, wenn ihr mich von ganzem Herzen suchet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'dann lasse ich mich von euch finden.\' Ein Spruch des Herrn. \'Ich wende euer Schicksal und sammle euch aus allen Völkern, allen Orten, wohin ich euch verstoßen\', ein Spruch des Herrn, \'und laß euch wieder an den Ort heimkehren, von dem ich euch verschleppt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Ihr saget wohl: \'Propheten hat der Herr zu Babel uns erweckt\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Dagegen spricht der Herr vom König, der auf Davids Throne sitzt, vom ganzen Volk, das diese Stadt bewohnt, von euren Brüdern, die nicht mit euch in die Verbannung zogen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'So spricht der Herr der Heerscharen: \'Fürwahr, zu ihrem Schaden lasse ich das Schwert, den Hunger und die Seuche los, behandle sie wie haarige Feigen, die, weil verdorben, ungenießbar sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Mit Schwert, mit Hunger und mit Pest verfolge ich und mache sie zu einem Schreckensbild für alle Reiche auf der Erde, zum Fluch und zum Entsetzen, zum Spott und Hohn bei allen Völkern, unter die ich sie versprenge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Dafür, daß sie auf meine Worte nicht gehört\', ein Spruch des Herrn, \'mit denen meine Diener, die Propheten, ich vom frühen Morgen zu ihnen ausgesandt. Ihr aber hörtet nicht auf sie.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, '\'Nun aber hört das Wort des Herrn, all ihr Gefangenen, die ich nach Babel von Jerusalem gesandt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'So spricht der Herr der Heerscharen, Gott Israels, von Achab, des Kolaja Sohn, und von dem Sohn des Maaseja, dem Sedekias, die euch in meinem Namen Lügen prophezeien: Ich gebe sie Nebukadrezar preis, dem König Babels. Vor euren Augen läßt er sie hinrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Von ihnen nimmt man das Verwünschungswort bei allen den Gefangenen Judas, die zu Babel leben: \'Der Herr, der mache dich wie Sedekias und wie Achab, die Babels König rösten ließ im Feuer!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'In Israel verübten sie Ruchlosigkeit und buhlten mit den Weibern ihrer Nachbarn und redeten in meinem Namen Lügenworte. Doch dazu gab ich ihnen keinen Auftrag. Ich selbst bin Mitwisser und Zeuge.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Und zu Semaja, dem Nechelamiten, rede:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '\'So spricht der Herr der Heerscharen, Gott Israels: Weil du in deinem Namen einen Brief gesandt an all das Volk, das zu Jerusalem sich findet, und an den Priester Sophonias, Maasejas Sohn, und alle Priester mit dem Inhalt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '\"Der Herr hat dich zum Priester eingesetzt an Stelle Jojadas, des Priesters, daß du im Haus des Herrn die Aufsicht führest über jeden, der in Begeisterung spricht und prophezeit, und daß du einen solchen in den Block kannst legen und ins Halseisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Nun also! Warum straftest du nicht Jeremias, den Anatotiter? Prophetenwahn hat ihn bei euch ergriffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Sonst hätte er nicht eine Botschaft uns nach Babel hergesandt, die also lautet: Noch lange währt\'s. Erbauet Häuser! Wohnt darin! Legt Gärten an! Eßt ihre Früchte!\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Der Priester Sophonias las dieses Schreiben dem Propheten Jeremias laut und deutlich vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Darauf erging das Wort des Herrn an Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '\"Allen Gefangenen laß diese Botschaft zukommen: \'So spricht der Herr über Semaja, über den Nechelamiten: Weil auch Semaja prophezeite, obwohl ich niemals ihn gesandt, und zum Vertraun auf Lüge euch verleitete\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'drum spricht der Herr: \'Ich will das an Semaja, dem Nechelamiten, ahnden wie an seinen Nachkommen. Er soll niemanden haben, der unter diesem Volke wohnen bliebe, noch Anteil an dem Glücke haben, das meinem Volk ich schaffen will. Hat er doch Abfall von dem Herrn gepredigt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Das Wort, das einst vom Herrn erging an Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So spricht der Herr, Gott Israels: \"Schreib alle diese Worte auf, die ich zu dir geredet, in ein Buch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Denn siehe, Tage kommen\", ein Spruch des Herrn, \"da wende ich das Schicksal meines Volkes Israel und Juda\", so spricht der Herr, \"und führe sie ins Land, das ihren Vätern ich zu eigen gab, zurück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Dies aber sind die Worte, die der Herr von Israel und Juda geredet hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'So spricht der Herr: \"Horch auf! Schon hören wir von Schrecken, von Grausen, unheilvoll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Befragt euch! Seht, ob Männer auch gebären können? Weswegen sehe ich die Männer all mit Händen an den Hüften, wie Kreißende, und jedes Antlitz wandelt sich in Todesblässe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Weh! Groß ist jener Tag. Nicht gibt es seinesgleichen. Drangsalszeit für Jakob! Doch wird es darauf wiederum befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'An jenem Tag geschieht\'s\", ein Spruch des Herrn der Heerscharen, \"daß ich sein Joch auf deinem Nacken zerbreche und deine Fesseln aufreiße, und Fremde sollen sie nicht länger knechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Dann dienen sie Gott, ihrem Herrn, und David, ihrem König, den ich für sie erwecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Du aber fürcht dich nicht, mein Diener Jakob!\" Ein Spruch des Herrn. \"Erschrick nicht, Israel! Denn sieh, ich rette dich aus fernem Lande, aus dem Lande der Verbannung deinen Stamm, daß Jakob wieder ruhig wohne und niemand mehr ihn schrecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Ich bin mit dir\", ein Spruch des Herrn, \"dich zu befreien. Denn ich vernichte gänzlich alle Völker, unter die ich dich zerstreut. Dir mache ich den Garaus nicht; ich strafe dich mit Maß. Doch straflos kann ich dich nicht lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Ja, also spricht der Herr: \"Dein Schaden ist unheilbar und deine Wunde bösartig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nach aller Urteil ist die Schwäre unheilbar; Vernarbung gibt es nicht für dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'All deine Buhlen haben dich vergessen; sie kümmern sich nicht mehr um dich. Mit argen Schmerzen schlug ich dich, mit scharfer Züchtigung ob deiner vielen Sünden, der Menge deiner Missetaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Was schreist du denn, ob deines Schadens, und ob der Menge deiner Missetaten sei so schlimm dein Schmerz? Ob deiner vielen Sünden und ob der Menge deiner Missetaten tat ich dir dies an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Jedoch sie alle, die dich aufgefressen, sie werden gleichfalls aufgefressen, und deine Dränger sollen insgesamt in die Gefangenschaft abziehen, und die dich ausgeplündert, selbst geplündert werden, und alle, die dich ausgeraubt, die gebe ich dem Raube hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Vernarben laß ich deine Wunde und heile dich von deinen Plagen\", ein Spruch des Herrn, \"weil sie dich die \'Verstoßene\' nennen, und Sion \'die, um die kein Mensch sich kümmert\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So spricht der Herr: \"Ich wende das Geschick der Zelte Jakobs, und gnädig bin ich seinen Wohnungen. Die Stadt wird wiederum auf ihrem Hügel aufgebaut; am rechten Platze steht die Burg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Aus ihr klingt Lobgesang und froher Leute Jubel. Ich mehre sie, daß sie nicht kleiner werden, und ehre sie, daß sie nicht minder werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Wie vordem sind mir seine Söhne lieb und wert, und seine Volksgemeinde steht vor mir geschlossen da. Doch Heimsuchung bereite ich all seinen Bedrückern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Sein Herrscher wird ihm selbst entstammen, und sein Gebieter kommt aus seiner eigenen Mitte. Zutritt gewähre ich auch ihm, daß er mir nahe. Wen gäb\' es sonst, der dran sein Leben wagen wollte, zu mir herzutreten?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, '\"Dann seid ihr mir zum Volk, und ich, zu eurem Gotte werde ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Der Sturm des Herrn, ein Grimm, ganz außerordentlich, ein Wirbelsturm, ganz ungewöhnlich, der auf das Haupt der Frevler wirbelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Der Flammenzorn des Herrn kehrt nicht zurück, bevor er ihn austoben ließ, und bis er seine Pläne ausgeführt. Am Schluß der Tage sehet ihr das ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '\"Zu jener Zeit\", ein Spruch des Herrn, \"da werde ich zum Gott für alle die Geschlechter Israels, und diese werden mir zum Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So spricht der Herr: \"Das Volk der Schwertentronnenen erlangte in der Wüste Gnade, und Israel zog seiner Ruhestatt entgegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Von fernher gab der Herr sich mir zu schauen. \"Ich liebe dich mit ewiger Liebe, deswegen ziehe ich in Liebe dich an mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ich bau dich wieder auf; dann bleibst du aufgebaut, du Jungfrau Israel. Richt nochmals deine Pauken her! Zieh aus im Reigen Frohgesinnter!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Und pflanze nochmals auf Samarias Bergen Weingärten! Die Winzer sollen sie bepflanzen und in Nießbrauch setzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Dann kommt die Zeit, da Wächter rufen im Gebirge Ephraim: \'Auf, lasset uns nach Sion ziehn, zum Herrn, zu unserm Gott!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Ja, also spricht der Herr: \"Erfreuet euch an Jakob! Jubelt ob des trefflichsten der Völker auf! Ruft laut und sprecht: \'Befrei Dein Volk, o Herr, den Rest von Israel!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Ich bringe sie vom Nordland her und sammle sie vom Erdenrand, die Stummen, Blinden, Lahmen, Schwangeren und Wöchnerinnen allzumal; sie gehn zurück in großer Schar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Mit Weinen kommen sie; mit Tröstung führe ich sie her. Ich leite sie an Wasserbäche auf ebener Bahn, daß sie nicht straucheln. Denn Vater bin ich jetzt für Israel; mein Erstgeborener ist Ephraim.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Vernehmt das Wort des Herrn, ihr Heidenvölker! Verkündet auf den Inseln in der Ferne! Sprecht so: \"Der Israel zerstreut hat, sammelt\'s wieder und hütet\'s wie ein Hirte seine Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Denn Jakob hat der Herr befreit, aus der Gewalt des Stärkern ihn erlöst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Sie kommen jubelnd auf die Höhe Sions; vor Freude strahlen sie ob ihres Herren Güte, des Kornes, Mostes, Öles halber, und der Lämmer und der Rinder wegen. Und ihre Seele wird ein Garten, wohl erquickt; hinschmachten sie fortan nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Am Reigen freuen sich die Jungfraun mit den Jünglingen und Greisen allzumal. \"Ich kehre ihre Trauer um in Wonne und schenke ihnen Trost und Freude nach dem Leid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Den Gaumen ihrer Priester labe ich mit Fett; an meiner Güte sättigt sich mein Volk.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So spricht der Herr: \"In Rama hört man Klage. Horch! Bitterliches Weinen. Um ihre Söhne weinet Rachel! Sie läßt sich nimmer trösten; denn ihre Söhne sind nicht mehr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'So spricht der Herr: \"Das Weinen wehre deiner Stimme, die Tränen deinen Augen! Für deine Mühsal gibt es einen Ausgleich.\" Ein Spruch des Herrn. \"Sie kehren heim aus Feindesland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Für deine Zukunft gibt\'s noch Hoffnung.\" Ein Spruch des Herrn. \"Denn deine Söhne kehren in ihr Heim zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Ich höre Ephraim wehklagen: \'Gezüchtigt hast Du mich. Und ich empfing die Zucht, wie jungen Rindern es geschieht, die noch nicht eingeübt. Führ heim mich! Heim will ich, bist Du doch, o Herr, mein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Nach meiner Heimkehr reut es mich. Zur Einsicht jetzt gelangt, schlag ich an meine Hüfte. Ich schäme mich, bin ganz zerknirscht; denn meiner Jugend Schande muß ich büßen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ist Ephraim mir ein so teurer Sohn, ein Lieblingskind? Wie oft ich gegen ihn auch spreche, muß ich doch immer wieder an ihn denken. Drum schlägt mein Herz ihm zu: Ich muß mich sein erbarmen.\" Ein Spruch des Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, '\"Wegzeiger stell dir auf und Wegmarken errichte dir! Hab auf die Straße acht und auf den Weg, den du gegangen! Kehr heim, du Jungfrau Israel! Kehr heim zu diesen deinen Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Wie lange, ungetreue Tochter, zauderst du? Ein Neues schafft der Herr im Lande: Den Mann umwirbt ein Weib.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So spricht der Herr der Heerscharen, Gott Israels: \"Aufs neu gebraucht man dieses Wort im Lande Juda und in seinen Städten, wenn ich wende ihr Geschick: \'Es segne dich der Herr, du Aue der Gerechtigkeit, du Berg der Heiligkeit!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Drin weilt in Eintracht Juda mit allen seinen Städten, die Ackersleute und die Herdenführer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Erquicken will ich jeden Gaumen, der lechzt, und jeden Mund, der darbt, den sättige ich');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ich wach darüber, schaue drein; mein Schlaf ist mir vergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Die Zeit trifft ein\", ein Spruch des Herrn, \"und gut besäe ich das Haus Israels und Judas Haus mit Menschen- und mit Tiersamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Ich wachte über ihnen zum Ausreuten, Einreißen, Vernichten, Tilgen und Verderben. So wache ich jetzt über ihnen zum Bauen und zum Pflanzen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'In jenen Tagen heißt\'s nicht mehr: \"Die Väter aßen Herlinge, und erst der Söhne Zähne werden stumpf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Nein! Jeder stirbt um seiner eigenen Sünde willen. Wer Herlinge genießt, dem werden stumpf die Zähne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, '\"Die Zeit trifft ein\", ein Spruch des Herrn, \"da schließe ich mit Israels und Judas Haus ein neues Bündnis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'nicht wie den Bund, den ich mit ihren Vätern abgeschlossen, als ich sie bei der Hand ergriff und aus dem Lande der Ägypter führte. Mein Bündnis aber brachen sie, obwohl ich sie mir angetraute Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, '\"Das ist der Bund, den ich nun mit dem Hause Israels nach diesen Tagen schließe.\" Ein Spruch des Herrn. \"Ich lege in ihr Innres mein Gesetz und schreib es ihnen in ihr Herz. Alsdann bin ich ihr Gott, sie sind mein Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Nicht mehr belehren sie sich so: \'Erkennt den Herrn!\' Denn alle werden sie mich kennen vom Kleinsten bis zum Größten.\" Ein Spruch des Herrn. \"Denn ihre Sündenschuld vergebe ich, und ich gedenke nimmer ihrer Missetat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So spricht der Herr, der leuchten heißt die Sonne am Tag, dem Mondlicht und den Sternen weist, bei Nacht zu scheinen, das Meer aufwühlt, daß seine Wogen brausen; sein Name ist \"Der Heeresscharen Herr\":');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '\"Wie diese Ordnungen nie vor mir schwinden\", ein Spruch des Herrn, \"so hört Israels Stamm nicht auf, ein ewig Volk vor mir zu sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So spricht der Herr: \"Erst wenn der Himmel droben ausgemessen, erforscht der Erde Felsen drunten wären, dann erst verwerf ich Israels ganzen Stamm um dessentwillen, was sie einst getan.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, '\"Die Zeit trifft ein\", ein Spruch des Herrn, \"da wird die Stadt dem Herrn aufs neue aufgebaut vom Turme Ananels bis zu dem Tor der Ecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Und weiter zieht die Meßschnur geradeaus sich hin bis zu dem Grabeshügel und wendet sich nach Goah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Das ganze Tal der Äser und der Asche, das ganze Gartenland bis zu dem Kidronsbach und bis zur Ecke östlich von dem Roßtor ist ganz dem Herrn geweiht. Nie wird es mehr geschleift, nie mehr verwüstet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Das Wort, das einst vom Herrn an Jeremias ging im zehnten Jahr des Judakönigs Sedekias, das ist im achtzehnten des Nebukadrezar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Damals lag vor Jerusalem das Heer des Babelkönigs, und Jeremias, der Prophet, war eingekerkert im Wachthof in dem Haus des Judakönigs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Ihn hatte Judas König, Sedekias, eingekerkert, indem er sagte: \"Was prophezeiest du: So spricht der Herr: \'Fürwahr, ich gebe diese Stadt dem Babelkönig zum Erobern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Und Judas König, Sedekias, entschlüpft mitnichten den Chaldäern. Er wird dem Babelkönig ausgeliefert. Der spricht von Mund zu Mund mit ihm, sieht ihm ins Auge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Nach Babel bringt er Sedekias, wo er bleibt, bis ich ihn heimsuche.\' Ein Spruch des Herrn. \'Wenn ihr mit den Chaldäern kämpft, wird euch das Glück nicht lächeln.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Darauf erzählte Jeremias: \"Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, '\'Chanamel, deines Oheims Sallum Sohn, erscheint vor dir in kurzer Zeit und sagt zu dir: \"Kauf meinen Acker, den zu Anatot! Du hast das Vorkaufsrecht.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Da kam zu mir Chanamel, meines Oheims Sohn, ganz nach des Herren Worten, in den Wachthof. Er sprach zu mir: \'Kauf meinen Acker, der zu Anatot, in Benjamins Gebiet! Dir steht das Erbrecht samt dem Vorkaufsrechte zu! So kauf ihn doch!\' Und ich sah ein, es war des Herren Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Da kaufte ich den Acker von Chanamel, dem Sohne meines Oheims zu Anatot,und zahlte ihm den Preis von siebzehn Silberlingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Dann brachte ich es zu Papier und siegelte, zog Zeugen bei und wog das Silber auf der Waage dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Ich nahm darauf den Kaufbrief, den nach Vorschrift und Gesetz gesiegelten, sowie den offenen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'und übergab den Kaufbrief Baruch, dem Sohn des Neria, Maasejas Enkel, in Gegenwart Chanamels, meines Vetters, sowie in Gegenwart der Zeugen, die diesen Kaufbrief unterzeichnet hatten, in Gegenwart all der Judäer, die im Wachthof weilten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Ich trug in ihrer Gegenwart dem Baruch auf:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '\'So spricht der Herr der Heerscharen, Gott Israels: Hier diese Briefe nimm, sowohl den Kaufbrief, den gesiegelten, als diesen offenen Brief, und gib sie in ein irdenes Gefäß, damit sie viele Jahre sich erhalten!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Ja, also sprach der Herr der Heerscharen, Gott Israels: \'Es sollen wieder Häuser-, Äcker-, Weinbergskäufe im Lande abgeschlossen werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Da betete ich zu dem Herrn, nachdem ich dem Neriasohne Baruch den Kaufpreis zugestellt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Herr! Herr! Du schufst den Himmel und die Erde durch Deine große Macht und Deinen ausgestreckten Arm. Kein Ding ist Dir unmöglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Du schenkest Gnade Tausenden, doch zahlst Du später erst der Väter Sünden heim den Söhnen, Du großer, Du gewaltiger Gott; Dein Name \'Herr der Heerscharen\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'So groß an Rat, an Tat so mächtig, Du, dessen Augen auf aller Menschenkinder Wege blicken, um jeglichen nach seinen Wegen zu entlohnen, gemäß den Früchten seiner Taten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Du, der Du wunderbare Zeichen im Ägypterland gewirkt, bis heute noch in Israel und bei den andern. So schufest Du Dir Deinen jetzigen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Du hast doch Israel, Dein Volk, aus dem Ägypterland geführt mit Zeichen und mit Wundern, mit starker Hand und ausgestrecktem Arm und unter großem Schrecken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'gabst ihnen dieses Land, das ihren Vätern zu verleihen Du geschworen, ein Land, von Milch und Honig fließend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Sie zogen ein und nahmen\'s in Besitz; sie aber hörten nicht auf Deine Stimme und lebten nicht nach Deiner Lehre und taten nichts von alldem, was Du sie geheißen. Da ließest Du sie treffen all dies Unheil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Nun reichen schon die Wälle an die Stadt, sie zu bezwingen, und preisgegeben wird die Stadt in der belagernden Chaldäer Hand, durch Schwert, durch Hunger und durch Pest. Was Du gedroht, geschieht, und ruhig schaust Du zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Und doch hast Du zu mir gesprochen, Herr: \'Den Acker kaufe dir um Geld! Dazu nimm Zeugen!\', obschon die Stadt in der Chaldäer Hand gerät.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Darauf erging das Wort des Herrn an Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '\"Fürwahr! Ich bin der Herr, der Gott der Fleischeswesen insgesamt. Ist irgend etwas mir unmöglich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Deshalb sprach so der Herr: \"Ich gebe diese Stadt in der Chaldäer Hand und in die Hand Nebukadrezars, des Babelkönigs; er nimmt sie ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Und die Chaldäer, die die Stadt belagern, werden eindringen und diese Stadt anzünden und verbrennen, und zwar die Häuser, auf deren Dächern sie dem Baal einst geräuchert und andern Göttern Trankspenden gegossen, mich zu verdrießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Die Söhne Israels und Judas taten ja von ihren Jugendzeiten an nur das, was mir mißfiel. Die Söhne Israels verdrossen immer mich durch ihrer Hände Werk.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, '\"Zum Zorn und Grimm ward diese Stadt mir schon vom Tage an, da man sie aufgebaut, bis auf den heutigen Tag. Aus meinem Antlitz muß ich sie hinwegräumen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'ob all der Bosheit bei den Söhnen Israels und Judas, die sie verübt mich zu verdrießen, sie, ihre Könige und Fürsten und ihre Priester und Propheten, die Männer Judas wie Jerusalems Bewohner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Sie kehrten mir den Rücken zu, nicht das Gesicht. Ich lehrte sie und lehrte sie vom frühen Morgen an; sie aber hörten nicht, daß Zucht sie angenommen hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Sie stellten vielmehr ihre Greuelgötzen in dem Hause auf, das meinen Namen trägt, und machten\'s dadurch unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Sie bauten Baalshöhlen im Ben Hinnomstale und brachten Sohn und Tochter selbst dem Moloch dar. Nie hab ich dies geboten; nie ist\'s mir in den Sinn gekommen, sie sollten solche Greuel tun und Juda so mit Schuld beladen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Nun aber spricht aus diesem Grund der Herr, Gott Israels, von dieser Stadt, von der ihr sagt, sie sei dem Babelkönig preisgegeben durch Schwert, durch Hunger und durch Pest:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, '\"Ich bin\'s, der aus den Ländern sie versammelt, in die ich sie in meinem Zorn und Grimm verstoßen in großem Ärger. Ich führte sie zu diesem Orte heim und lasse sie allhier in Ruhe wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Sie werden mir zum Volk und ich zum Schutzgott ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'E i n Herz und e i n e n Weg verleih ich ihnen, daß sie mich fürchten alle Zeit zum Heil für sie und ihre Söhne später.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Ich schließe einen ewigen Bund mit ihnen; dann kann ich ihnen allzeit Gutes tun und lege ihnen meine Furcht ins Herz, und nimmer weichen sie von mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Voll Freude über sie erweis ich ihnen Gutes nur und pflanze sie in diesem Lande auf die Dauer ein, mit meinem ganzen Herzen und mit meiner ganzen Seele ihnen zugetan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'So spricht der Herr: \"So wie ich über dieses Volk all dieses schwere Ungemach gebracht, so bring ich ihnen auch das Gute all, wie ich es ihnen hab versprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'In diesem Lande kauft man wieder Äcker, und doch sagt ihr von ihm: \'Jetzt ist es eine Wüste ohne Mensch und Vieh und den Chaldäern preisgegeben\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Für Silber wird man Äcker kaufen, Kaufbriefe schreiben und versiegeln mit Beiziehung von Zeugen im Lande Benjamin, rings um Jerusalem, in Judas Städten und in denen des Gebirges und in den Städten in der Niederung und in des Südlands Städten; ich wende ihr Geschick\". Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Das Wort des Herrn erging zum zweitenmal an Jeremias, als er noch im Wachthof eingeschlossen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'So spricht der Herr, der es ersonnen, der Herr, der es entworfen, um es auszuführen, - \"Der Herr\" - sein Name:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, '\"Frag mich, ich will dir Antwort geben und Großes dir verkünden, das ihr nicht kennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'So spricht der Herr, Gott Israels, im Hinblick auf die Häuser dieser Stadt und die der Könige von Juda, die für die Wälle eingerissen wurden und für die Kriegsmaschinen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, '\"Sie zogen in den Kampf mit den Chaldäern und füllten sie mit Menschenleichen, die ich in meinem Zorn und Grimm erschlug. Mein Angesicht verhüllte ich vor dieser Stadt all ihrer Schlechtigkeiten wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Jetzt laß ich völlig sie genesen und gesunden, eröffne ihnen eine Fülle von Frieden und Beständigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Ich wende das Geschick von Juda und Israels Geschick und stelle sie wie vormals wieder her');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'und reinige sie von aller ihrer Schuld, durch die sie gegen mich gefehlt, vergebe alle ihre Sünden, durch die sie gegen mich gesündigt und sich an mir vergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Sie sollen mir zu Ruhm und Wonne, zu Preis und Ehre dienen bei allen Erdenvölkern. Vernehmen sie von all dem Guten, das ich ihnen tue, alsdann erbeben sie und zittern ob all dem Guten, all dem Frieden, den ich für sie bewirke.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So spricht der Herr: \"An diesem Ort, von dem ihr sagt: \'Verödet ist er, ohne Mensch und Vieh\', und in den Städten Judas und in den Straßen von Jerusalem, jetzt Öde, menschenleer, ganz der Bewohner bar und ohne Vieh, vernimmt man noch einmal');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'des Jubels und der Freude Stimme, den Sang des Bräutigams, den Brautgesang, den Jubel derer, die da sprechen: \'Lobpreist den Herrn der Heerscharen! Gut ist der Herr, und ewig währet seine Huld.\' Dankopfer bringt man wieder in das Haus des Herrn. Ich wende das Geschick des Landes so, wie es zuvor gewesen.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So spricht der Herr der Heerscharen: \"An diesem Orte, öde, ohne Mensch und Vieh, und auch in allen seinen Städten gibt es wieder eine Au für Hirten, die Schafe lagern lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Auch in den Städten des Gebirges und der Niederung, im Südland und im Lande Benjamin, rings um Jerusalem und in den Städten Judas entschlüpfen wieder dem die Schafe, der sie zählt.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, '\"Fürwahr! Die Zeit erscheint\", ein Spruch des Herrn, \"wo ich mein freundlich Wort erfülle, das ich dem Hause Israel und Juda gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'In jenen Tagen und zu jener Zeit laß ich für David einen rechten Sprossen sprießen, der Recht im Lande und Gerechtigkeit verwaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'In jenen Tagen fühlt sich Juda glücklich; in sicherer Ruhe ist Jerusalem. Dies ist sein Name: \'Der Herr ist unser Heil\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'So spricht der Herr: \"Nie soll es David an den Männern fehlen, die sitzen auf dem Thron des Hauses Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Den Priestern aber, den Leviten, wird nie ein Mann vor meinem Angesichte fehlen, der Brandopfer darbringt und Speiseopfer läßt in Rauch aufgehen und allzeit Schlachtopfer bereitet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Darauf erging das Wort des Herrn an Jeremias also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'So spricht der Herr: \"Falls ihr mein Bündnis mit dem Tag und mit der Nacht aufheben könnt, daß Tag und Nacht zu ihrer Zeit ausblieben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'dann könnte auch mein Bund mit David, meinem Knechte, aufgehoben werden, so daß er keinen Sohn auf seinem Thron mehr hätte, und auch der Bund mit den Leviten, mit den Priestern, daß sie mich nimmermehr bedienten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Gleichwie das Heer des Himmels nicht zu zählen und der Sand des Meeres nicht zu messen ist, so will ich Davids, meines Knechtes, Geschlecht vermehren und die Leviten, die in meinen Diensten stehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Und es erging das Wort des Herrn an Jeremias, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '\"Bemerkst du nicht, was diese Leute sprechen? \'Die beiden Häuser, die der Herr einst auserwählt, die hat er jetzt verworfen.\' So denken sie von meinem Volk verächtlich, daß sie es nicht als Volk mehr gelten lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So spricht der Herr: \'Wenn ich mein Bündnis mit dem Tag und mit der Nacht, des Himmels und der Erde Ordnungen, nicht festhielte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'nur dann verwürfe ich auch Jakobs Stamm und David, meinen Knecht, und nähme keine Herrscher mehr aus seinem Stamm für das Geschlecht des Abraham, des Isaak und des Jakob. Ich wende ihr Geschick und neige ihnen mich erbarmend zu.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Das Wort, das einst an Jeremias von dem Herrn ergangen, als Nebukadrezar, Babels König, und sein ganzes Heer samt allen seiner Herrschaft unterworfenen Reichen und allen andern Völkern Jerusalem belagerten, mit allen seinen Städten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '\"So spricht der Herr, Gott Israels: Geh hin! Sprich zu dem Könige von Juda, Sedekias: Verkünde ihm: So spricht der Herr: \'Ich gebe diese Stadt dem Babelkönig preis, daß er mit Feuer sie verbrenne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Auch du entrinnst ihm nicht; du wirst ergriffen und ihm ausgeliefert. Den Babelkönig schauen deine Augen; von Mund zu Munde redet er mit dir. Nach Babel wirst du kommen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Doch hör das Wort des Herrn, du Sedekias, Judas König! So spricht der Herr von dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, '\'Du stirbst im Frieden, und wie die Leichenbrände deiner Väter waren, der früheren Könige vor dir, so zündet man auch dir ihn an und klagt um dich \"Ach, du Gebieter!\" Das hab ich zu sagen.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'So meldete der Seher Jeremias dem Judakönig Sedekias all diese Worte zu Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Das Heer des Babelkönigs aber kämpfte gen Jerusalem und alle Städte Judas, die noch übrig waren, Lachis und Aseka; sie waren doch die einzigen von Judas festen Städten, die noch standhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Das Wort, das einst an Jeremias von dem Herrn erging, nachdem der König Sedekias einen Bund mit allem Volke zu Jerusalem geschlossen hatte, bei ihnen die Freilassung zu verkünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'daß jeder seinen Sklaven und jeder seine Sklavin, Hebräer und Hebräerin, freilasse, daß kein Volksgenosse mehr bei ihnen noch einem andern Juden Sklavendienste leiste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Da gehorchten alle Fürsten und das ganze Volk. Sie schlossen diesem Abkommen sich an, daß jeder seinen Sklaven und seine Sklavin freilasse, um sie nicht länger mehr im Dienst zu halten. Sie schenkten ihnen demgemäß die Freiheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Inzwischen aber, andern Sinns geworden, holten sie die freigelassenen Sklaven samt den Sklavinnen zurück und zwangen mit Gewalt sie abermals zum Sklavendienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Darauf erging das Wort des Herrn an Jeremias, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '\"So spricht der Herr, Gott Israels: Ich selber schloß mit euren Vätern einen Bund, als ich sie aus Ägypterlande führte, aus ihrem Sklavenstand, und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '\'Nach sieben Jahren lasse jeder frei den Bruder, der Hebräer ist und der sich dir verkauft! Sechs Jahre soll er dir ein Sklave sein! Dann laß ihn wieder frei!\' Doch eure Väter hörten nicht auf mich, noch neigten sie ihr Ohr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Doch neuerdings seid andern Sinnes Ihr geworden und tatet, was in meinen Augen richtig war, und habt einander Freiheit ausgerufen. Ihr schlosset einen Bund vor mir im Haus, das meinen Namen trägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Doch ihr entweiht aufs neue meinen Namen. Ein jeder holt den Sklaven und die Sklavin wieder, die ihr aus eignem Willen freigelassen. Ihr unterwerft sie mit Gewalt zu Sklaven und zu Sklavinnen für euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Darum spricht so der Herr: \"Bewilligt ihr aus Ungehorsam gegen mich einander keine Freiheit, dann künde ich euch Freiheit an\", ein Spruch des Herrn, \"für Schwert, für Pest und Hunger. Ich mache euch zu einem Schreckensbild für alle Reiche auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'All die Männer, die meinen Bund gebrochen und die Worte des vor mir geschlossenen Bundes nicht gehalten haben, die mache ich zum Kalb, das sie entzweigeschnitten und zwischen dessen Stücken sie hindurchgeschritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Die Fürsten Judas und Jerusalems, die Kämmerer, die Priester, des Landes ganzes Volk, das mitten durch');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'des Kalbes Stücke hindurchgeschritten, gebe ich in ihrer Gegner Hände und in die Hände ihrer Todfeinde. Zum Fraße sollen ihre Leichen des Himmels Vögeln dienen, dem Getier des Feldes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Ich gebe Judas König, Sedekias, wie seine Fürsten auch jetzt ihren Gegnern preis und ihren Todfeinden, in die Gewalt des Heers des Babelkönigs, das von euch abgezogen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'So ordne ich es an\", ein Spruch des Herrn, \"und bringe wieder sie zu dieser Stadt zurück. Sie streiten gegen sie, erobern und verbrennen sie. Auch Judas Städte mache ich zur unbewohnten Wüste.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Das Wort, das von dem Herrn erging an Jeremias, zur Zeit des Judakönigs Jojakim, des Sohnes des Josias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '\"Ins Haus der Rekabiter geh und sprich mit ihnen! Führ sie ins Haus des Herrn hinein, in eine seiner Zellen, und setze ihnen Wein zum Trinken vor!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Ich holte Jajanja, Jeremias Sohn und Habasankjas Enkel, samt seinen Brüdern, seinen Söhnen allen, sowie das ganze Rekabiter-Haus');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'und führte sie ins Haus des Herrn in das Gemach der Söhne Hanans, eines Sohns des Gottesmanns Igdalja. Neben dem Gemach des Fürsten lag es über der Zelle des Sallumsohns und Schwellenhüters Maaseja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Hier setzte ich den Söhnen aus dem Rekabiterhause mit Wein gefüllte Krüge und Becher vor und sprach zu ihnen. \"Trinket Wein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Da sprachen sie: \"Wir trinken keinen Wein. Denn Jonadab, des Rekab Sohn und unser Ahnherr, schrieb folgendes uns vor: \'Wein sollet weder ihr noch eure Söhne trinken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'noch Häuser bauen, noch Samen säen, noch Weinberge bepflanzen, noch besitzen! Vielmehr sollt ihr die ganze Lebenszeit in Zelten wohnen! So bleibt ihr viele Tage in dem Land, in dem ihr nur als Wandrer lebt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Wir folgten dem Befehl des Rekabsohnes und unseres Ahnen Jonadab in allem, was er uns geheißen. Wir tranken keinen Wein in unserm Leben, wir nicht noch unsere Weiber, noch unsere Söhne, noch unsere Töchter;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'auch bauten wir keine Wohnhäuser. Wir hatten weder Weinberge noch Äcker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Wir wohnten unter Zelten und taten aus Gehorsam alles, was unser Ahnherr Jonadab uns vorgeschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Als aber Babels König, Nebukadrezar, in das Land einfiel, da sprachen wir: \'Kommt! Laßt uns nach Jerusalem verziehen vor dem Heere der Chaldäer und vor dem Heer der Aramäer!\' So nahmen wir Jerusalem zum Wohnsitz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Darauf erging das Wort des Herrn an Jeremias, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '\"So spricht der Herr der Heerscharen, Gott Israels: Geh hin und sprich zu Judas Männern und zu Jerusalems Bewohnern! Wollt ihr\'s euch nicht zum Beispiel nehmen, daß ihr auf meine Worte hört?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, '\"Des Jonadab, des Rekabsohns, Befehle werden ausgeführt. Verboten hat er seinen Söhnen, Wein zu trinken. Sie trinken keinen bis auf diesen Tag. Denn sie gehorchen dem Befehle ihres Ahnherrn. Nun sprech auch ich zu euch, und zwar vom frühen Morgen an: Ihr aber höret nicht auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'All meine Diener, die Propheten, sandte ich zu euch. Ich sandte sie am frühen Morgen schon, zu künden: \'Kehrt doch, ein jeglicher, von seinem schlimmen Wege um! Befleißt euch guter Taten! Den andern Götzen geht nicht nach, sie zu verehren! Dann bleibet ihr in diesem Land, das ich euch gab und euren Vätern.\' Ihr aber neiget euer Ohr nicht her und höret nicht auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Die Söhne Jonadabs, des Rekabsohns, befolgen treulich ihres Ahnherrn Vorschrift, die er ihnen gab. Doch kein Gehör schenkt mir dies Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'So spricht deshalb der Herr der Heerscharen, Gott Israels: \"Fürwahr, ich bringe über Juda und alle Einwohner Jerusalems das ganze Unheil, das ich ihnen angedroht. Ich sprach zu ihnen; sie aber hörten nicht; ich rief sie an, sie aber gaben keine Antwort.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Dagegen sprach zum Haus der Rekabiter Jeremias: \"So spricht der Herr der Heerscharen, Gott Israels: \'Ihr seid dem Worte eures Ahnherrn Jonadab gehorsam, beachtet alle seine Forderungen und tut, was er euch vorgeschrieben!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Deshalb spricht so der Herr der Heerscharen, Gott Israels: \'Nie soll es Jonadab, dem Rekabsohne, an einem mangeln, der mir Dienste tut.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Im vierten Jahr des Judakönigs Jojakim, des Sohnes des Josias, erging vom Herrn das Wort an Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '\"Nimm eine Buchrolle! Drauf schreibe all die Worte, die ich zu dir geredet gegen Israel und Juda und gegen alle andern Völker, seitdem ich zu dir sprach von des Josias Zeiten bis auf diesen Tag!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Vielleicht vernimmt das Judahaus das ganze Ungemach, das ich ihm anzutun gedenke. Wenn dann ein jeglicher von seinem schlimmen Wege läßt, dann schenke ich auch ihnen Schuld und Missetat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Darauf rief Jeremias Baruch, des Neria Sohn, herbei, und Baruch schrieb in eine Buchrolle aus Jeremias\' Munde all die Herrenworte auf, die er zu ihm gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Darauf trug Jeremias dem Baruch auf: \"Ich selber bin verhindert am Besuch im Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Geh du jetzt hin! Lies aus der Rolle, die du meinem Munde abgeschrieben, die Herrenworte laut dem Volk am Festtag vor im Haus des Herrn! Lies sie auch vor den Ohren von ganz Juda, das aus seinen Städten kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Vielleicht wird ihr Gebet dem Herren unterbreitet, wenn jeglicher von seinem schlimmen Wege läßt. Gewaltig ist der Zorn und Grimm, mit dem der Herr dies Volk bedroht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Und Baruch, des Neria Sohn, tat alles, was Jeremias, der Prophet, ihm anbefohlen. Er las im Haus des Herrn die Herrenworte aus dem Buche vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Im fünften Jahr des Judakönigs und Josiassohnes, Jojakim, am neunten Neumond, da geschah, daß man zu einem Fasten vor dem Herrn das ganze Volk Jerusalems berief, desgleichen alles Volk, das aus den Städten Judas nach Jerusalem gekommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Dabei las Baruch aus dem Buche des Jeremias Worte laut vor allem Volke vor, im Haus des Herrn, im Raum des Schreibers und Saphansohns, Gemarja, im oberen Hof, am neuen Tor am Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Michaja, des Gemarja Sohn und Saphans Enkel, auch er vernahm die Herrenworte aus dem Buche alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Da ging er zu dem Haus des Königs in den Raum des Schreibers; dort saßen eben alle Fürsten beieinander, der Schreiber Elisama und Delaja, des Semaja Sohn, und Elnatan, der Sohn des Akbor, und Gemarja, Saphans Sohn, und Sedekias, des Ananja Sohn, und alle andern Fürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Da meldete Michaja ihnen alle Worte, die er vernommen, als Baruch aus dem Buch dem Volk laut vorgelesen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Da schickten alle diese Fürsten zu Baruch Jehudi, Netanjas Sohn und Enkel des Selemja, des Kusisohnes, und ließen sagen: \"Bring die Rolle, aus der dem Volke du laut vorgelesen, mit und mach dich auf den Weg!\" Da nahm Nerias Sohn, nahm Baruch, die Rolle mit und kam zu ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Da sprachen sie zu ihm: \"Lies sie noch einmal auch uns vor mit lauter Stimme!\" Darauf las Baruch ihnen sie laut vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Doch wie sie alle diese Worte hörten, da sahen sie erschrocken einander an und sprachen dann zu Baruch: \"Das alles müssen wir dem König melden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Den Baruch aber baten sie: \"Teil uns doch mit: Wie schriebst du alle diese Worte für uns aus seinem Munde nieder?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Da sprach zu ihnen Baruch. \"Er trug mir auswendig all diese Worte vor; dann schrieb ich sie mit Tinte in das Buch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Die Fürsten sprachen nun zu Baruch: \"Geh hin! Verbirg dich samt dem Jeremias! Und niemand wisse, wo ihr seid!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Dann gingen eilends sie zum König, nachdem sie in des Schreibers Elisama Kammer die Rolle hinterlegt, und meldeten dem König selbst all diese Dinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Der König sandte den Jehudi hin, die Rolle beizubringen; der holt\' sie aus des Schreibers Elisama Kammer; Jehudi las sie laut dem König vor und allen Fürsten um den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Der König aber saß im Winterhaus im neunten Monat, vor ihm ein brennend Kohlenbecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Sooft Jehudi drei, vier Spalten vorgelesen, schnitt er sie mit dem Federmesser ab und warf sie in das Feuer im Kohlenbecken, bis die ganze Rolle ins Feuer in dem Kohlenbecken kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Sie aber zeigten keinen Schrecken und zerrissen ihre Kleider nicht, weder der König noch ein einziger seiner Diener, die alle diese Worte angehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Doch gleichwohl hatten Elnatan und Delaja und Gemarja den König flehentlich gebeten, er möge doch die Rolle nicht verbrennen; er aber hörte nicht auf sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Vielmehr befahl der König Jerachmeel, dem Königssohne, dem Sohne Azriels, Seraja und Adeels Sohne, Selemja, den Schreiber Baruch zu verhaften samt Jeremias, dem Propheten; der Herr jedoch hielt sie verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Darauf erging das Wort des Herrn an Jeremias, nachdem der König jene Rolle mit den Worten verbrannt, die Baruch aus des Jeremias Munde aufgeschrieben hatte. Dies war sein Inhalt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '\"Jetzt nimm dir eine andre Rolle und schreib darauf die früheren Worte alle, die auf der ersten Rolle standen und die der König Judas, Jojakim, verbrannt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Auch gegen Jojakim, den Judakönig, sollst du sprechen: So spricht der Herr: \'Du hast die Rolle verbrannt mit diesen Worten: \"Was schriebst du da hinein: Ganz sicher kommt der Babelkönig, verheert das Land und tilgt daraus so Mensch wie Vieh?\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Dafür spricht gegen Jojakim, den Judakönig, so der Herr: \'Nicht soll er einen Erben auf dem Throne Davids haben! Sein Leichnam soll bei Tag der Hitze, bei Nacht der Kälte preisgegeben sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Ich such an ihm und seinem Stamm und seinen Dienern ihre Sünde heim. Ich bringe über sie und die Bewohner von Jerusalem und alle Männer Judas all dies Unheil, das ich ihnen angedroht. Sie aber hören nicht darauf.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Da nahm sich Jeremias eine andre Rolle und gab sie dem Neriasohn und Schreiber Baruch. Er schrieb darauf aus Jeremias\' Munde den ganzen Inhalt jenes Buches, das ihm der Judakönig Jojakim verbrannt. Sie ward vermehrt mit vielen Reden gleicher Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Und Sedekias, des Josias Sohn, ward König, anstelle Jojachins, des Sohnes Jojakims, den Nebukadrezar, Babels König, einst zum König über das Land Juda eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Doch weder er noch seine Diener noch die Bevölkerung des Landes hörten auf das Wort des Herrn, das er durch den Propheten Jeremias, redete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Nun sandte König Sedekias den Jehukal, Sohn des Selemia, dazu den Priester Sophonjas, Maasejas Sohn, zu Jeremias, dem Propheten, mit der Weisung: \"Fleh doch für uns zum Herrn, zu unsrem Gott!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Und Jeremias ging noch immer unterm Volk umher, weil man ihn noch nicht eingekerkert hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Inzwischen brach das Heer des Pharao aus Ägypten auf. Als die Chaldäer, die Jerusalem belagerten, die Kunde davon hörten, zogen sie sich von Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Darauf erging das Wort des Herrn an den Propheten Jeremias also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '\"So spricht der Herr, Gott Israels: Zum Judakönig sprecht, der euch zu mir gesandt, mich zu befragen, also: \'Fürwahr, das Heer des Pharao, das euch zu Hilfe ausgezogen, kehrt wieder in sein Land zurück, in das Ägypterland!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Dann kommen die Chaldäer wieder, belagern abermals die Stadt, erobern und verbrennen sie.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'So spricht der Herr: \'Ah! Täuscht euch nicht und wähnet nicht, es ziehen die Chaldäer wirklich von uns ab. Sie sind nicht weggezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Und schlüget ihr die ganze Heeresmacht der euch belagernden Chaldäer, und blieben nur noch einige Verwundete davon in ihren Zelten einzeln übrig, sie ständen auf, und sie verbrannten diese Stadt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Als nun die Heermacht der Chaldäer von Jerusalem abzog, wegen der Heermacht Pharaos,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'ging von Jerusalem auch Jeremias, um ins Gebiet von Benjamin sich zu begeben und dort im Stamme eine Erbschaft anzutreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Als er ins Benjaminstor trat, war auf der Wache dort ein Mann mit Namen Jeria, Selemjas Sohn und Enkel des Ananja. Da hielt er den Propheten Jeremias mit den Worten an: \"Du läufst zu den Chaldäern über.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Doch Jeremias sprach: \"Es ist nicht wahr. Nie laufe ich zu den Chaldäern über\", und achtete nicht mehr auf ihn. Jeria aber nahm den Jeremias fest und führte ihn den Fürsten vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Die Fürsten aber wurden über Jeremias zornig; sie stäupten ihn und brachten ihn in das Gefängnis, in das Haus des Schreibers Jonatan; denn dieses hatten sie zum Kerker ausgestattet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'So kam denn Jeremias in das Brunnenhaus, und zwar in das Gewölbe. Dort mußte Jeremias viele Tage bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Einmal ließ ihn der König Sedekias holen. In seinem Haus befragte ihn der König heimlich: \"Gibt\'s von dem Herrn ein Wort zu künden?\" Da sagte Jeremias: \"Ja!\" Er sprach sodann: \"Dem Babelkönig wirst du ausgeliefert werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Dann sagte Jeremias zum König Sedekias: \"Womit habe ich\'s an dir und deinen Dienern, an diesem Volk verschuldet, daß ihr mich ins Gefängnis werft?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Wo sind nun die Propheten, die euch prophezeien: \'Der Babelkönig kommt nicht über euch und dieses Land?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Nun hör, mein Herr und König! Laß meine Bitte vor dich kommen! Schick mich nicht abermals ins Haus des Schreibers Jonatan, damit ich dort nicht sterben muß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Der König Sedekias gab darauf Befehl. So brachte man Jeremias im Wachthof in Gewahrsam und gab ihm einen Brotlaib täglich aus der Bäckergasse, bis alles Brot der Stadt zu Ende war. Seitdem saß Jeremias nun im Wachthof.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Da hörten Mattans Sohn Sephatja, Gedalja, Paschurs Sohn, und Jukar, des Selemja Sohn, und Paschur, des Malkia Sohn, die Worte, die Jeremias sprach zum ganzen Volke:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '\"So spricht der Herr: \'Wer hier in dieser Stadt verbleibt, der stirbt durchs Schwert, den Hunger und die Pest; wer den Chaldäern sich ergibt, erbeutet seine Seele und bleibt am Leben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'So spricht der Herr: \'Gewiß wird diese Stadt dem Heer des Babelkönigs überliefert, der sie erobert.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Da sprachen die Fürsten zum König: \"Der Mann müßte getötet werden, weil er die Krieger, die in der Stadt noch übrig sind, wie auch das ganze Volk entmutigt, weil er vor ihnen solche Reden führt; denn dieser Mann ist nicht aufs Heil für unser Volk bedacht, nein, nur auf Unheil.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Da sprach der König Sedekias: \"Wohlan, er sei in eurer Hand! Denn gegen euch vermag der König nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Da nahmen sie den Jeremias und warfen ihn in die Zisterne des Prinzen Malkias im Wachthof. Sie ließen ihn hinab an Stricken. In der Zisterne war kein Wasser, sondern Schlamm, und Jeremias sank in diesen Schlamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Da hörte der Äthiope Ebedmelech, ein Eunuche, der eben in des Königs Hause war, man habe den Jeremias in den Brunnen geschafft; der König aber weilte unterdes im Tore Benjamins.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Darauf ging Ebedmelech aus dem Haus des Königs und sprach zum König:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '\"Mein Herr und König! Gar übel taten jene Männer an dem Propheten Jeremias, da sie ihn in den Brunnen warfen, daß er dort Hungers stürbe, weil\'s in der Stadt kein Brot mehr gibt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Da wies der König den Äthiopen Ebedmelech an: \"Nimm dir von hier drei Männer mit und holet den Propheten Jeremias aus dem Brunnen, bevor er stirbt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Da nahm Ebedmelech die Männer mit, ging in das Haus des Königs oben in die Kleiderkammer, nahm dorten Lumpen von zerrissenem und zerschlissenem Zeug und ließ an Stricken sie zu Jeremias in den Brunnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Dann sprach der Äthiope Ebedmelech zu Jeremias: \"Leg diese Lumpen von zerrissenem und zerschlissenem Zeug dir unter deine Achseln und um diese Stricke!\" Und Jeremias tat so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Sie zogen nunmehr Jeremias an den Stricken hoch und holten ihn so aus dem Brunnen. Und Jeremias blieb fortan im Wachthof.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Der König Sedekias ließ jedoch sich den Propheten Jeremias holen zum dritten Eingange im Haus des Herrn. Der König sprach zu Jeremias: \"Ich will dich etwas fragen. Verhehl mir nichts!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Da sprach zu Sedekias Jeremias: \"Verkünde ich es dir, läßt du mich töten. Geb ich dir aber einen Rat, so hörst du nicht auf mich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Da schwur der König Sedekias Jeremias insgeheim: \"So wahr der Herr lebt, der es macht, daß uns jetzt so zu Mute ist: Ich lasse dich nicht töten und gebe dich nicht preis den Leuten, die dir nach dem Leben trachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Und Jeremias sprach zu Sedekias: \"So spricht der Herr, der Heeresscharen Gott, Gott Israels: \'Ergibst du dich den Obersten des Babelkönigs, dann bleibt dein Leben ungefährdet, und diese Stadt wird nicht verbrannt. Du bleibst samt deinem Haus am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Ergibst du aber dich den Obersten des Babelkönigs nicht, dann fällt die Stadt in der Chaldäer Hand; sie werden sie verbrennen. Auch du entrinnst nicht ihren Händen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Der König Sedekias sprach zu Jeremias: \"Ich sorge mich der Juden wegen, die schon zu den Chaldäern überliefen, daß sie mich diesen überlassen, um ihren Spott mit mir zu treiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Darauf sprach Jeremias: \"Sie liefern dich nicht aus. Folg doch dem Wort des Herren nach dem, was ich dir künde! Dann geht\'s dir gut, und du bleibst so am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Doch sträubst du dich, dich zu ergeben, so ist es dies, was mir der Herr gezeigt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, '\'Fürwahr, die Weiber all, die in des Judakönigs Haus noch übrig sind, sie werden vorgeführt den Obersten des Babelkönigs und sprechen: Betrogen haben dich und überredet deine guten Freunde. Sie lockten deine Füße in den Sumpf und ließen dich im Stich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Denn alle deine Weiber, deine Söhne wird man hinaus zu den Chaldäern führen; auch du entrinnst nicht ihren Händen; du wirst vielmehr dem Babelkönig überliefert, und diese Stadt wird man verbrennen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Da sprach zu Jeremias Sedekias: \"Kein Mensch darf von der Unterredung wissen; sonst mußt du sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Doch sollten je die Fürsten es erfahren, daß ich mit dir geredet, und kämen sie zu dir und sagten: \'Teil uns doch mit, was du zum Könige gesprochen! - Verhehle uns aber nichts davon, sonst bringen wir dich um! - und was der König dann zu dir gesagt\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'so sage ihnen: \'Ich bat den König flehentlich, mich nicht mehr in das Haus des Jonatan zurückzuschicken, daß ich dort stürbe.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Und wirklich kamen alle Fürsten zu Jeremias und fragten ihn. Doch gab er ihnen so Bescheid, wie ihm der König anbefohlen. Da ließen sie ihn gehen, weil von dem Vorgang weiter nichts bekannt geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Und Jeremias blieb im Wachthof bis zum Tage, da Jerusalem erobert ward. Er blieb am Leben bei Jerusalems Eroberung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Im neunten Jahr des Judakönigs Sedekias, im zehnten Monat, zog Babels König Nebukadrezar mit seinem ganzen Heere vor Jerusalem, um dieses einzuschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Im elften Jahre des Sedekias, am neunten Tage des vierten Monats, ward Bresche in die Stadt gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Da kamen alle Obersten des Babelkönigs und ließen sich am Mitteltore nieder, Nergalsareser, Samgar Nebo, Sarsekim, der Oberkämmerer, der Obermagier Nergalsareser und alle anderen Obersten des Babelkönigs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Als aber Sedekias, Judas König, sowie das ganze Kriegsvolk sie erblickten, ergriffen sie die Flucht und gingen aus der Stadt zur Nachtzeit auf dem Weg zum Königsgarten, durch das Tor, das zwischen den zwei Mauern liegt, und zwar ging er hinaus der Jordansteppe zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Darauf verfolgten die Truppen der Chaldäer sie und holten in den Steppen Jerichos den Sedekias ein, ergriffen ihn und führten ihn zum Babelkönig Nebukadrezar, nach Ribla in dem Land von Hamat, und er sprach ihm das Urteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Des Sedekias Söhne ließ der Babelkönig zu Ribla selbst vor seinen Augen schlachten. Auch alle Edlen Judas ließ der Babelkönig abschlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Den Sedekias aber ließ er blenden und in Ketten legen und mit nach Babel nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Das Königshaus sowie den Tempel verbrannten die Chaldäer, und sie zerstörten auch die Mauern von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Des Volkes Rest, der in der Stadt verblieb, sowie die Überläufer, die ihm zugelaufen waren, des Volkes Rest, der übrig blieb, die führte Nebuzaradan, der Oberste der Leibwächter, nach Babel weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Von den geringen Leuten aber, die nichts hatten, ließ Nebuzaradan, der Oberste der Leibwächter, noch etliche im Judaland zurück und schenkte ihnen an jenem Tage Weingärten und Äcker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Für Jeremias gab der Babelkönig Nebukadrezar dem Nebuzaradan, dem Obersten der Leibwächter, Befehl:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '\"Hol ihn; trag für ihn Sorge! Laß ihm kein Leid geschehen! Wie er dir sagt, so tu mit ihm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Darauf ließen Nebuzaradan, der Oberste der Leibwächter, der Oberste der Kämmerer, Nebusazban, der Obermagier Nergalsareser und alle Obersten des Babelkönigs');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'den Jeremias aus dem Wachthof holen und übergaben ihn Gedalja, dem Sohne Achikams, des Saphansohnes, auf daß er ihn in Freiheit setze und nach Haus entließe. So blieb er mitten unterm Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'An Jeremias aber war ein Herrenwort ergangen, als er in Haft im Wachthof war:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '\"Geh! Sprich zu Ebedmelech, dem Äthiopen: \'So spricht der Heeresscharen Herr, Gott Israels: Fürwahr, Ich lasse meine Worte über diese Stadt zum Unheil, nicht zum Heile, in Erfüllung gehen, und zwar an diesem Tage. Vor deinen Augen wird\'s geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Dich aber errette ich an jenem Tage.\' Ein Spruch des Herrn. \'Du fällst nicht in der Männer Hand, vor denen es dir graut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Nein! Ich errette dich gewiß. Du fällst nicht durch das Schwert. Du wirst dein Leben dir erbeuten, weil du auf mich vertraust.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Das Wort, das von dem Herrn an Jeremias ging, nachdem ihn Nebuzaradan, der Oberste der Leibwächter, von Rama hatte gehen lassen. Als er ihn holen ließ, da war mit Ketten er gefesselt, inmitten aller der Gefangenen Jerusalems und Judas, die abgeführt nach Babel werden sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Der Oberste der Leibwächter ließ Jeremias holen und sprach zu ihm: \"Der Herr, dein Gott, hat diesem Ort dies Unheil angedroht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Der Herr hat es erfüllt. Er tat so, wie er angedroht; denn ihr versündigtet euch an dem Herrn und hörtet nicht auf seine Stimme; drum hat euch dies Geschick getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Doch heute löse ich dich aus den Ketten, die an deinen Händen sind. Beliebt es dir, mit mir nach Babel mitzugehn, dann komm! Ich sorg für dich. Beliebt\'s dir aber nicht, mit mir nach Babel mitzugehn, dann laß es sein! Das ganze Land steht dir dann offen. Wohin zu gehen es dir gut und recht erscheint, geh hin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Als er noch immer nichts erwiderte, sprach er: \"Geh zu Gedalja, dem Sohn des Achikam und Enkel Saphans! Ihn hat der Babelkönig über Judas Städte eingesetzt. Bleib unterm Volk bei diesem, oder geh, wohin zu gehn es dir beliebt!\" Alsdann beschenkte ihn der Oberste der Leibwächter mit Zehrung und mit einer Ehrengabe; hierauf entließ er ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Und Jeremias kam so zu Gedalja, dem Sohn des Achikam, nach Mispa und blieb bei ihm dort unterm Volk, das noch im Lande war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Da hörten alle Obersten der Scharen auf dem freien Feld, samt ihren Leuten, daß Babels König den Gedalja, Achikams Sohn, zum Statthalter im Lande eingesetzt und daß er ihm die Männer, Weiber, Kinder unterstellt, und von den armen Leuten im Lande jenen Teil, der nicht nach Babel abgeführt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Da kam nach Mispa zu Gedalja Ismael, der Sohn Netanjas, mit ihm Jochanan und von Karechs Söhnen Jonatan, Seraja, des Tanchumet Sohn, die Söhne Ephai\'s, des Netophatiters, sowie Jezanja, des Maakatiters Sohn, und ihre Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Da schwur der Sohn des Achikam, Gedalja, ihnen samt ihren Leuten zu: \"Habt keine Angst, euch den Chaldäern zu ergeben! Bleibt hier im Land und seid dem Babelkönig untertan! Dann geht\'s euch gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Ich selber bleibe hier in Mispa, um euch vor den Chaldäern zu vertreten, die zu uns kommen. Ihr aber erntet ruhig Wein und Obst und Öl und legt es ein und bleibt in euren Städten, die ihr euch erwählt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Und auch die andern Juden alle, die in Moab bei den Ammonitern und in Edom und in all den andern Ländern waren, hörten, Babels König habe Juda einen Rest gelassen und über sie des Achikam Sohn, Gedalja, den Enkel Saphans, eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Da kehrten alle Juden aus den Orten insgesamt zurück, in die sie überall versprengt gewesen, und kamen in das Judaland nach Mispa zu Gedalja. Da ernteten sie Wein und Obst in großer Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Da kam Jochanan, Karechs Sohn, samt allen Heeresobersten im freien Felde nach Mispa zu Gedalja');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'und sie sagten ihm: \"Weißt du, daß Baalis, der Ammoniterkönig, den Ismael, Netanjas Sohn gesandt, dich zu ermorden?\" Gedalja aber, Sohn Achikams, schenkte ihnen keinen Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Jochanan, Karechs Sohn, sprach aber zu Gedalja insgeheim in Mispa: \"Ich gehe hin und morde Ismael, Netanjas Sohn. Kein Mensch soll es erfahren. Was soll er dich ums Leben bringen, daß alle, die von Juda sich um dich gesammelt, sich abermals zerstreuen und Judas Rest verlorengehe?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Achikams Sohn jedoch, Gedalja, sprach zu Karechs Sohn, Jochanan: \"Tu dies nicht! Du redest über Ismael nur, was nicht wahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Am siebten Neumonde geschah\'s, daß Ismael, Netanjas Sohn und Elisamas Enkel, von königlicher Abstammung, sowie die königlichen Großen in Begleitung von zehn Männern nach Mispa zu Gedalja, Sohn Achikams, sich begaben. Als sie jedoch in Mispa miteinander speisten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'erhob sich Ismael, Netanjas Sohn, und die zehn Männer bei ihm, und sie erschlugen Gedalja, des Achikams Sohn und Saphans Enkel mit dem Schwerte. So mordete er ihn, den Babels König hatte über das Land gesetzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'auch alle die Judäer, die in Mispa bei Gedalja waren, samt den Chaldäern, die dort waren. Sogar die Kriegermannschaft mordete Ismael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Und da geschah\'s am zweiten Tag nach der Ermordung des Gedalja, als noch kein Mensch es wußte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'daß Leute aus Sichem, Silo und Samaria kamen, an achtzig Mann, mit abgeschorenen Bärten, zerrissnen Kleidern und zerfetzter Haut. Sie hatten Speiseopfer und Weihrauch bei sich, um sie in das Haus des Herrn zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Diesen ging Netanjas Sohn, Ismael, von Mispa aus entgegen, indem er unter Weinen seines Weges zog. Als er sie traf, sprach er zu ihnen: \"Kommt zu Achikams Sohn Gedalja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Sobald sie aber in die Stadt gekommen waren, erschlug Netanjas Sohn, Ismael, sie mitten an dem Brunnen, er und die Leute, die er bei sich hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Zehn Männer aber fanden sich darunter, die sprachen zu Ismael: \"Töt uns nicht! Wir haben auf dem Feld noch Vorräte an Weizen, Gerste, Öl und Honig.\" Da ließ er ab und tötete sie nicht mit ihren Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Doch die Zisterne, in die Ismael die Leichen aller dieser Männer werfen ließ, die er um des Gedalja willen hat erschlagen, war die Zisterne, die der König Asa gen Baësa, Israels König, einst gegraben hatte. Sie füllte Ismael, Netanjas Sohn, mit den Erschlagenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Dann führte Ismael den ganzen Rest des Volks in Mispa weg, die Königstöchter und das ganze Volk, das noch in Mispa übrig, das Nebuzaradan, der Oberste der Leibwächter, dem Sohn des Achikam Gedalja übergeben hatte. Sie führte Ismael, Netanjas Sohn, gefangen fort. So zog er hin und wollte zu den Ammonitern übergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Als Jochanan, des Karech Sohn, und alle Heeresobersten bei ihm, von all dem Unheil hörten, das Ismael, der Sohn Netanjas, angestiftet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'nahmen alle Leute sie und zogen hin, mit Ismael, Netanjas Sohn, zu kämpfen. Sie trafen ihn am großen Wasser zu Gibeon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Wie dann das ganze Volk bei Ismael den Karechsohn Jochanan und alle Heeresobersten bei ihm erblickte, ward es froh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Das ganze Volk, das Ismael gefangen aus Mispa weggeführt, machte nun kehrt und ging zum Karechsohn Jochanan über.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Doch Ismael, Netanjas Sohn, entkam mit noch acht Männern dem Jochanan, und er gelangte zu den Ammonitern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Da nahm des Karech Sohn, Jochanan, und alle Heeresobersten bei ihm den ganzen Rest des Volkes, den er dem Ismael, Netanjas Sohn, aus Mispa abgenommen, als er Achikams Sohn, Gedalja, schnöd ermordet hatte, die Männer, Krieger, Weiber, Kinder und Eunuchen, die er von Gibeon zurückgebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Sie zogen ab und hielten Rast in Kimhams Herberge seitwärts von Bethlehem; sie wollten nach Ägypten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'aus Furcht vor den Chaldäern. Sie fürchteten sich nämlich vor diesen, weil Ismael, Netanjas Sohn, Gedalja, Achikams Sohn, ermordet hatte; ihn aber hatte Babels König eingesetzt über das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Da kamen alle Heeresobersten mitsamt Jochanan, Karechs Sohn, sowie Asarja, Maasejas Sohn, und allem Volk vom Kleinsten bis zum Größten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'und sprachen zum Propheten Jeremias: \"Möge unsre Bitte Erhörung bei dir finden; bete du für uns zum Herrn, deinem Gott, für diesen ganzen Rest! Von vielen sind wir bloß ein kleines Häuflein übriggeblieben, wie du uns vor dir siehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Möge uns der Herr, dein Gott, den Weg kundtun, den wir betreten, und den Beschluß, den wir jetzt fassen sollen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Da sprach zu ihnen Jeremias, der Prophet: \"Nun gut! Ich will zum Herren, eurem Gotte, nach eurem Wunsche beten und sag euch den Bescheid, den euch der Herr zukommen läßt. Nicht ein Wort werde ich vor euch verschweigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Da sprachen sie zu Jeremias: \"Der Herr sei gegen uns ein ganz wahrhaftiger und ganz genauer Ankläger, falls wir nicht ganz genau, den Weisungen gemäß, so tun, wie es der Herr durch dich uns anweist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'sei\'s Gutes oder Schlimmes! Nur auf die Stimme unseres Herrn und Gottes, zu dem wir dich entsenden, wollen wir hören. Daß es uns gut ergehe, weil wir auf des Herren, unseres Gottes, Stimme hören wollen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Und nach zehn Tagen erging das Herrenwort an Jeremias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Da rief er Karechs Sohn, Jochanaan, und alle Heeresobersten bei ihm, sowie das ganze Volk, vom Kleinsten bis zum Größten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Er sprach zu ihnen. \"So spricht der Herr, Gott Israels, zu dem ihr mich gesandt, damit ich euer Flehen vor ihn brächte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, '\'Wenn ihr in diesem Lande bleibet, dann baue ich euch auf und reiße es nicht wieder ein und pflanze euch darein und reiße es nicht wieder aus. Denn mich gereut des Unheils, das ich euch angetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Habt keine Angst vor Babels König, vor dem ihr jetzt in Schrecken seid! Habt keine Angst vor ihm!\' Ein Spruch des Herrn. \'Ich bin mit euch, um euch zu helfen und euch aus seiner Hand zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Ich lasse euch Erbarmen finden, daß er sich euer erbarmt und euch in eurem Lande wohnen läßt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Doch wenn ihr denkt: \'Wir bleiben nicht in diesem Land,\' und achtet ihr nicht auf des Herren, eures Gottes, Stimme');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'und sprechet: \"Nein! Nach Ägypten ziehen wir. Dort hören wir vom Krieg nichts mehr und müssen nicht Trompetenschall vernehmen und haben nicht nach Brot zu hungern. Dort lassen wir uns nieder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Nun denn, so hört für solchen Fall das Wort des Herrn, die ihr von Juda übrig seid! So spricht der Heeresscharen Herr, Gott Israels: Beharrt ihr auf der Reise nach Ägypten, und zieht ihr hin, als Gäste dort zu weilen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'dann trifft euch im Ägypterland das Schwert, vor dem ihr bangt; die Hungersnot, vor der ihr zagt, verfolgt euch bis in das Ägypterland. Dort sterbet ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Und alle Männer, die darauf beharren, in das Ägypterland zu kommen, um dort als Gäste zu verweilen, erliegen durch das Schwert, den Hunger und die Seuche. Dem Unheil, das ich über sie verhänge, entkommt, entrinnt nicht einer unter ihnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'So spricht der Heeresscharen Herr, Gott Israels: \'Wie sich mein Zorn und meine Wut einst über die Bewohner von Jerusalem ergossen, so wird mein Grimm sich über euch ergießen, wenn ihr nach Ägypten zieht. Ihr werdet zur Verwünschung, zum Entsetzen, zum Fluch und zum Gespött. Ihr sehet diesen Ort nicht wieder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Gesagt hat\'s euch der Herr, ihr Rest von Juda: \'Zieht mitnichten nach Ägypten! Ihr werdet es erfahren. Ich warne euch im voraus.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Ihr haltet mit Gefahr für euer Leben einen nur zum besten; ihr sandtet mich zum Herren, eurem Gott, und sprachet: \'Bete für uns zum Herren, unserm Gott! Was unser Herr und Gott verkündet, dieses melde uns! Wir tun es dann.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Ich hab es heute euch vermeldet. Ihr aber hörtet auf die Stimme des Herrn, eures Gottes, in nichts, womit er mich für euch beauftragt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Nun werdet ihr\'s erfahren: Durch Schwert, durch Hunger und durch Pest erlieget ihr am Orte, wohin es euch zu ziehn gelüstet, um dort als Gäste zu verweilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Jeremias teilte dem gesamten Volk all diese Worte von dem Herrn, ihrem Gotte, mit; denn der Herr, ihr Gott, hatte ihn damit an sie gesandt. Er teilte all diese Worte bis zu Ende mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Da sprach Azarja, Maasejas Sohn, und Karechs Sohn, Jochanan, und all die Männer sprachen, arg sich überschreiend, zu Jeremias: \"Nicht wahr ist, was du sprichst! Dich schickt der Herr, unser Gott, nicht mit der Weisung her: \'Ihr sollt nicht nach Ägypten zieh\'n, um dort als Gäste zu verweilen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Nein, Baruch, des Neria Sohn, reizt gegen uns dich auf. Er will uns den Chaldäern überliefern, daß man uns töte oder uns nach Babel bringe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'So hörten denn Jochanan, Karechs Sohn, und alle Heeresobersten, sowie das ganze Volk nicht des Herren Stimme, daß sie im Judaland geblieben wären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Vielmehr nahm Karechs Sohn, Jochanan, und alle Heeresobersten den ganzen Rest von Juda; er war zurückgekehrt aus all den Völkern, wohin sie sich zerstreut, um in dem Judaland zu bleiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'die Männer, Weiber, Kinder, die Königstöchter und alle anderen Personen. Sie hatte Nebuzaradan, der Leibwache Oberster, bei Achikams Sohn und Saphans Enkel, Gedalja, zurückgelassen, auch den Propheten Jeremias, und Nerias Sohn, Baruch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'So zogen sie ins Land Ägypten, im Ungehorsam gegen des Herren Stimme. Sie kamen bis Tachpanches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Darauf erging das Wort des Herrn an Jeremias zu Tachpanches, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '\"In deine Hand nimm große Steine! Vergrabe sie im Boden, wohl bedeckt, am Eingang zu des Pharaos Haus dort zu Tachpanches in Gegenwart jüdischer Männer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Und sprich zu ihnen: \'So spricht der Heeresscharen Herr, Gott Israels: Ich hole her den Babelkönig, Nebukadrezar, meinen Knecht, und stelle seinen Thron auf diese Steine, die ich allhier versenken ließ. Er spannt sein Teppichzelt darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Er kommt und schlägt Ägypterland. Wer für die Pest bestimmt, verfällt der Pest, dem Kerker, wer dem Kerker, dem Schwerte, wer dem Schwerte zugewiesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Ich lasse Feuer an die Häuser der ägyptischen Götter legen, und dies verbrennt sie samt den Tempeln. So säubert er das Land Ägypten, wie sein Gewand der Hirte säubert, und unversehrt zieht er von dannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Und dann zertrümmert er des Sonnenhauses Obelisken in Ägypten; die Häuser der ägyptischen Götter brennt er nieder.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Das Wort erging an Jeremias über die Judäer alle, die sich im Land Ägypten, in Migdol, Tachpaneches, in Memphis und in dem Lande Patros niederließen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '\"So spricht der Heeresscharen Herr, Gott Israels: \'Ihr selber habt das ganze Unheil miterlebt, das ich Jerusalem und allen andern Städten Judas zugefügt. Sie sind jetzt eine menschenleere Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Der bösen Taten wegen, die sie trieben, mir zum Verdrusse. Sie räucherten im Dienste unaufhörlich den andern vordem unbekannten Göttern, die euch und euren Vätern unbekannt gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Wohl sandte ich zu euch all meine Diener, die Propheten; ich sandte sie vom frühen Morgen an und ließ sie sprechen: \'Treibt doch nicht solchen Greuel, den ich hasse!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Sie aber hörten nicht und neigten nicht ihr Ohr, daß sie von ihrem bösen Tun gelassen und den andern Göttern nicht geräuchert hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Und so ergoß sich meine Wut, mein Zorn und loderte in Judas Städten auf und in den Straßen von Jerusalem. Sie wurden eine wüste Öde, wie sie\'s noch heute sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Und nun spricht so der Herr der Heerscharen, Gott Israels: \"Was tut ihr selbst euch solch ein großes Unheil an und rottet so aus Juda Mann und Weib und Kind und Säugling aus, laßt keinen Rest für euch mehr übrig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Durch eurer Hände Werk verdrießt ihr mich, wenn andern Göttern im Ägypterland ihr räuchert. Ihr seid dahin zu Gast gezogen, um euch Vernichtung zuzuziehen. So werdet ihr zum Fluch und zum Gespött bei allen Erdenvölkern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Habt ihr vergessen schon die Übeltaten eurer Väter und die der Könige von Juda, die seiner Fürsten und eure eignen Übeltaten, die eurer Weiber auch, die sie im Judaland und in den Straßen von Jerusalem verübt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Sie sind bis heute nicht zerknirscht und haben keine Angst und wandeln nicht nach meiner Lehre, meinen Satzungen, die ich dereinstens euch und euren Vätern vorgeschrieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Darum spricht so der Herr der Heerscharen, Gott Israels: \"Ich bin zum Unheil gegen euch entschlossen, ganz Juda auszurotten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Und Judas Rest, der drauf besteht, sich zum Agypterlande zu begeben, um dort als Gast zu weilen, soll im Ägypterlande gänzlich aufgerieben werden. Vom Kleinsten bis zum Größten sterben sie durch Schwert und Hunger und werden so zum Fluch und zum Entsetzen, zum Spott und Hohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Bestrafen will ich, die im Land Ägypten sich niederlassen, so wie ich Jerusalem bestraft, durch Schwert, durch Hunger und durch Pest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'So gut wie keiner soll entrinnen und entkommen von Judas Rest, von denen, die gewillt sind, als Gäste im Ägypterland zu weilen, um später in das Judaland zurückzukehren, obwohl sie voller Sehnsucht sind, daselbst sich wieder anzusiedeln. Sie kehren nicht zurück; sie schwinden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Darauf erwiderten dem Jeremias die Männer all, die wußten, daß ihre Weiber andern Göttern räucherten, und alle Weiber, die in großen Haufen daneben standen, und alles andre Volk, das im Ägypterland in Patros wohnte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '\"Was du uns in des Herren Namen angekündigt, dem stimmen wir nicht bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Wir tun vielmehr, was wir gelobt, der Himmelskönigin zu räuchern und Trankopfer ihr zu spenden, wie wir und unsere Väter, unsere Könige und Fürsten in Judas Städten einst getan und in den Straßen von Jerusalem. Denn damals hatten wir noch Brot genug und lebten froh, von keinem Ungemach beschwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Seitdem wir aber unterließen, der Himmelskönigin zu räuchern und Trankopfer ihr auszugießen, mangelt\'s uns an allem, und wir wurden durch das Schwert und durch den Hunger aufgerieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Wenn wir der Himmelskönigin jetzt räuchern und ihr Trankopfer spenden, bereiten wir ihr Kuchen als ihr Bild und gießen ihr Trankopfer aus wohl ohne Wissen unsrer Männer?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Da sprach zum ganzen Volke Jeremias, zu Männern, Weibern und dem ganzen andern Volk, das eine solche Antwort ihm gegeben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '\"Das Räucherwerk, das ihr verbrannt in Judas Städten und in den Straßen von Jerusalem, ihr selber, eure Väter, eure Könige und eure Fürsten und die Landbevölkerung, ist dies dem Herrn nicht in Erinnerung geblieben? Zu Herzen ging es ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Der Herr hielt\'s länger nicht mehr aus ob eurer Taten Schlechtigkeit, der Greuel wegen, die ihr triebet. Und euer Land ward wüste, öde und verflucht und menschenleer, wie\'s heut noch ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Gerade, weil ihr räuchertet und euch damit am Herrn verfehltet, nicht auf des Herren Stimme hörtet und nicht nach seiner Lehre, seinen Satzungen und Überlieferungen lebtet, darum traf euch dies Ungemach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Alsdann sprach Jeremias zum gesamten Volk und allen Weibern:\"Vernehmt das Wort des Herrn, ganz Juda, das im Land Ägypten weilt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So spricht der Herr der Heerscharen, Gott Israels: \'Was ihr und eure Weiber offen ausgesprochen, vollbringt ihr auch mit euren Händen, also sprechend: \"Wir wollen unsere Gelöbnisse erfüllen, die wir gemacht, der Himmelskönigin zu räuchern und ihr Trankopfer darzubringen.\" Und sie erfüllen euere Gelöbnisse, vollziehn getreulich euere Gelübde.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Drum hör\' das Wort des Herrn, ganz Juda, das du im Land Ägypten weilst! Fürwahr, bei meinem großen Namen schwöre ich\', so spricht der Herr, \'mein Name soll nicht fernerhin im Munde irgendeines Judamannes sein, so daß er spräche: \"Bei dem Herrn, dem Herrn!\" in irgendeinem Teil Ägyptens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Ich wache über sie zum Unheil, nicht zum Heile, und aufgerieben werden sollen alle Männer Judas, die sich im Land Ägypten finden, durchs Schwert und durch den Hunger bis zur Vernichtung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Nur die dem Schwert Entronnenen, sie dürfen aus Ägypterland zum Lande Juda kehren, nur wenige an Zahl, damit der ganze Rest von Juda, der nach Ägypterland zum Aufenthalt gezogen, erkenne, wessen Worte sich erfüllen, die meinen oder ihre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Und dies soll euch zum Zeichen sein\', ein Spruch des Herren, \'daß ich euretwegen diese Stätte strafe, damit ihr daraus seht, daß meine Worte auch an euch zum Unheil sich erfüllen können.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'So spricht der Herr: \'Ich liefere Ägyptens König, Pharao Hophra, aus an seine Feinde, seine Widersacher, so wie ich Judas König Sedekias ausgeliefert dem Babelkönige Nebukadrezar, seinem Feind und Widersacher.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Das Wort, das Jeremias, der Prophet, zu Baruch, Sohn des Neria, sprach. Er hatte diese Reden in ein Buch geschrieben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'im vierten Jahr des Judakönigs und Josiassohnes Jojakim, nach Angabe des Jeremias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, '\"So spricht er Herr, Gott Israels, von dir, Baruch: \'Du sprachest: Wehe mir! Denn meinen Schmerz vermehrt der Herr durch Kummer; von meinem Seufzen bin ich müde; ich finde keine Ruhe.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'So sprich zu ihm: \'So spricht der Herr: Was ich gebaut, das reiß ich ein; was ich gepflanzt, das reiß ich aus, das ganze Land, das mir gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Und du verlangst für dich so Großes? Verlang es nicht! Ich bringe Unheil über alles Fleisch.\' Ein Spruch des Herrn. Dein Leben gebe ich zur Beute dir an jenem Ort, wohin du gehen willst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Was als ein Herrnwort an Jeremias, den Propheten, über die Heidenvölker erging:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Über Ägypten und des Pharao Necho Heer, das an dem Euphratstrom bei Karkemis gestanden und das Nebukadrezar, Babels König, im vierten Jahr des Judakönigs Jojakim, des Sohnes des Josias, geschlagen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '\"Zurecht macht Schild und Wehr! Zum Kampfe tretet an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Schirrt Rosse an! Sitzt auf, ihr Reiter! Stellt euch auf im Helmschmuck! Ergreift die Lanzen! Legt die Panzer an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Was sehe ich sie so bestürzt? Sie weichen rückwärts. Die Krieger sind geschlagen; sie fliehen, ohne umzuschauen. Von allen Seiten Grauen!\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '\"Entkommen kann der Schnelle nicht, der Krieger sich nicht retten. Im Norden an dem Euphratstrom stürzen sie hin und fallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Wer stieg nur wie der Nil empor, und wessen Wasser brausten so wie die des Stromes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Ägypten stieg dem Nile gleich herauf; die Wasser brausten so wie die des Stromes. Es sprach: \"Ich will hinauf, das Land bedecken und Städte samt den Insassen vernichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Stürmt her, ihr Rosse! Ihr Wagen, rennt! Rückt aus, ihr Krieger! Kuschiten, ihr von Put, ihr Schildgewappneten! Luditer, ihr erfahrenen Bogenschützen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Dem Herrn, dem Herrn der Heeresscharen, ist dieser Tag ein Rachetag; da rächt er sich an seinen Widersachern. Da frißt ein Schwert und sättigt sich, stillt sich an ihrem Blut. Ein Schlachtfest hält der Herr, der Heeresscharen Herr, im Nordland an dem Euphratstrom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Nach Gilead steig hinauf! Und hole Balsam dir, jungfräuliches Ägypten! Vergebens häufst du Heilungsmittel; Genesung gibt\'s für dich nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Von deiner Schmach erfahren Heidenvölker; denn dein Geschrei erfüllt die Erde. Da straucheln Krieger über Krieger; sie stürzen allesamt zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Das Wort, das der Herr zu Jeremias sprach über den Zug des Babelkönigs Nebukadrezar zur Niederwerfung des Ägypterlandes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '\"Verkündet\'s in Ägypten! Laßt es in Migdol hören! In Memphis und Tachpanches ruft es aus! Und sprechet: Stell dich auf! Leg deine Rüstung an! Schon frißt ein Schwert um dich herum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Weswegen stürzen deine Helden fort, und warum halten sie nicht stand? Der Herr treibt sie dahin und schlägt sie in die Flucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Da stürzt der eine zu dem andern wankend mit dem Rufe: \'Auf! Laßt uns heim zu unserm Volke kehren, in unsere Heimat vor dem mörderischen Schwert!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Jetzt nennt den Pharao, Ägyptens König: \'Getümmel bringt die Zeit herbei!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, '\'So wahr ich lebe\', ein Spruch des Königs, der Herr der Heeresscharen heißt: \'So wie ein Tabor unter Bergen und wie ein Karmel an dem Meere, so zieht\'s heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Mach dir zurecht die Reisebündel, Ägyptens Tochter, die so ruhig wohnt! Denn Memphis wird zur Wüstenei, zerstört und menschenleer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Ägypten ist wie eine Kuh mit schönem Maul; von Norden kommen Bremsen gegen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Auch seine Söldner, die bei ihm wie Kälber im Stalle stehn, sie kehren um und fliehen allzumal und machen nicht mehr Halt; denn ihres Unterganges Tag ist für sie angebrochen, die Stunde ihrer Heimsuchung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Ein Lärm wie der von Kriegern auf dem Marsche; mit Heeresmacht erscheinen sie und gehen ihm zu Leib mit Äxten, wie die, die Bäume fällen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Legt seinen Wald um!\' Ein Spruch des Herrn. \'Er ist ja undurchdringlich; mehr sind\'s ja ihrer als Heuschrecken ohne Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Zu Schanden wird Ägyptens Tochter und ausgeliefert einem Volk des Nordens.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'So spricht der Heeresscharen Herr, Gott Israels: \'Ich suche heim in Norden Ammon, den Pharao mitsamt Ägypten und seine Götter, seine Könige, den Pharao samt denen, die ihm trauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Und ihren Widersachern liefere ich sie aus und der Gewalt des Babelkönigs Nebukadrezar und seiner Diener. Hernach ist\'s wieder so besiedelt wie in alten Tagen.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, '\'Sei ohne Furcht, mein Diener Jakob! Erschrick nicht, Israel! Ich rette dich aus fernem Land und aus des Kerkers Lande deinen Stamm, daß Jakob wieder ruhig wohne und niemand mehr ihn schrecke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Sei also unbesorgt, mein Diener Jakob!\' Ein Spruch des Herrn. \'Ich selber bin bei dir. Den Untergang verhäng ich über all die Völker, wohin ich dich vertrieben habe. Nur über dich verhänge ich ihn nimmermehr. Mit Mäßigung will ich dich züchtigen; doch laß ich dich nicht völlig ungestraft.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Das Wort des Herrn an den Propheten Jeremias über die Philister, bevor der Pharao Gaza überwand:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So spricht der Herr: \"Von Norden schwellen Wasser an; zum Wildbach werden sie und überschwemmen dieses Land und was es füllt, die Stadt und ihre Einwohner. Die Menschen schreien, und alle, die im Lande wohnen, heulen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'beim Schall des Hufschlags seiner Rosse, beim Rasseln seiner Wagen, beim Rollen seiner Räder. Die Väter blicken nicht nach ihren Kindern; erschlafft sind die Hände');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'an jenem Tag, dazu bestimmt, ganz Philistäa zu verwüsten und jeden, der für Tyrus und für Sidon zur Hilfe übrig wäre, auszurotten. Der Herr will die Philister tilgen, den Rest der Insel Kaphtor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kahlheit bricht über Gaza ein, und Askalon wird kahl gerauft! Du Rest aus ihrem Lande! Wie lang zerfleischest du dich noch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Du Schwert des Herrn! Wie lang noch bist du voller Unrast? Zurück in deine Scheide! Halt ein! Bleib ruhig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Wie aber kannst du rasten? Befehle gab ihm schon der Herr für Askalon und für das Meeresufer. Dorthin hat er\'s entboten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Über Moab: So spricht der Heeresscharen Herr, Gott Israels: \"Weh über Nebo! Verwüstet ist\'s. Zu Schanden wird jetzt Kirjataim und erobert. Zu Schanden wird gebrochen diese Hochburg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Und Moabs Ruhm erlischt; Unheil wird gegen es zu Hesbon ausgeheckt. \'Herbei! Wir streichen Moab aus der Völker Zahl.\' Und du, Madmen, wirst auch vernichtet; ein Schwert wird dich verfolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Aus Choronaim tönt ein lautes Schreien: \'Verwüstung! Gräßliche Verheerung!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, '\'Verheert ist Moab\', so rufen schreiend seine Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Zur Steige von Luchit steigt tränenreiches Weinen. Den Weg herab von Choronaim vernimmt man Schreien über Feindesnot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fort! Rettet euer Leben, dem Dornbusch in der Wüste gleich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Du setzest dein Vertrauen auf deine Festungen und Vorratsmittel. Drum wirst du auch erobert, und Kamos geht in die Verbannung und seine Priester, seine Fürsten miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Zerstörer überfallen jede Stadt; nicht eine Stadt entrinnt. Zugrunde geht das Tal; vernichtet wird die Ebene.\" Das ist es, was der Herr gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, '\"Verfluchet Moab! Bestimmt zieht\'s fort, und seine Städte werden öde, und niemand wohnt mehr drin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Den träfe ja der Fluch, der in des Herren Auftrag lässig wäre. Der Fluch träf den, der seinem Schwert im Blutvergießen Grenzen setzte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Von Jugend an lag Moab in der tiefsten Ruhe; auf seinen Hefen lag es ungestört, ward niemals umgegossen und zog niemals in Verbannung. Deswegen blieb ihm sein Geschmack, und sein Geruch ward nicht verändert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Jetzt aber kommen Tage\", ein Spruch des Herrn, \"da sende ich zu ihm die Küfer, es umzugießen. Sie leeren die Gefäße, und dann zerschmettern sie die Krüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Da schämt sich Moab über Kamos, gleichwie das Haus von Israel sich über Betel, seine Hoffnung, schämte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Wie könnt ihr sagen: \'Wir sind Helden und tapfere Krieger\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Zerstört wird Moab, und seine Städte kommen auf die Schlachtbank, und seine besten jungen Krieger fallen drauf.\" Ein Spruch des Königs, der Herr der Heerscharen heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, '\"Dem Anfang nah ist Moabs Untergang; sein Unheil bricht gar schnell herein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Beklagt\'s, ihr seine Nachbarn all! Ihr alle, die von seinem Ruhme wissen, und sprecht: \'Wie ward zerbrochen dieser starke Stock, der wunderschöne Stab?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Leg deinen Ruhmesschimmer ab: Zum Staube steig hinab, du Bürgerschaft von Dibon! Denn gegen dich zieht der Verwüster Moabs her, bricht deine Burgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Heran zum Weg! Späh aus! Herzu, du Bürgerschaft von Aroër! Den Flüchtling frage, den Entronnenen! \'Was ist geschehen?\' Frage!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Zuschanden wurde Moab; besiegt ist es. So heulet! Jammert! Am Arnon macht bekannt: \'Verwüstet ist Moab!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Ein Strafgericht traf dieses Flächenland, Cholon, Jachaz und Mephaat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Dibon, Nebo und Bet Diblataim,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kirjataim, Bet Gamul und Bet Meon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Kerijot und Bosra und alle andern Städte in dem Lande Moab, die fernen wie die nahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Zerbrochen wurde Moabs Horn, sein Arm zerschmettert.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, '\"Betrunken macht\'s! Dem Herren gegenüber hat es sich gebrüstet. In sein Gespei soll Moab klatschen und also zum Gespötte werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Hast du nicht auch mit Israel ein ähnliches Gespött getrieben? Hat man\'s unter Dieben angetroffen, daß du dich schütteltest, sooft du von ihm sprachst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Fort aus den Städten! In Klüften haust! Bewohner Moabs! Macht\'s wie Tauben, die an des Abgrunds Rande kundig nisten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Wir hörten von dem übergroßen Hochmut Moabs, von seinem Übermute, seinem Stolz und seiner Anmaßung und Hoffart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Auch mir ist wohlbekannt\", ein Spruch des Herrn, \"sein windiges Gebaren, und seine Schwätzer handeln windig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Deswegen klag ich über Moab und jammere um Moab insgesamt. Die Leute von Kircheres sind wohl zu bedauern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Mehr als man über Jaser weinte, bewein ich jetzt den Weinstock Sibmas, dich, dessen Ranken bis zum Meere gehen und bis nach Jaser reichen. In deinen Herbst und deine Lesezeit fällt der Verwüster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Aus Moabs Gartenland und Ackerfeld wird Lust und Jubel weggenommen. Den Wein, den laß ich aus den Kufen schwinden. Man tritt nicht nach dem Kelterliede mehr. Das Kelterlied ist jetzt kein Kelterlied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Von Hesbons Schreien zieht sich ihr Geschrei bis nach Elale und bis Jahas fort, von Soar bis nach Choronaim und bis zum dritten Eglat hin; denn auch die Wasser Nimrims sind verschüttet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Aus Moab will ich die vertilgen\", ein Spruch des Herrn, \"die Opfer auf den Altar legen und seinem Gotte Weihrauch streuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Drum seufzt mein Herz um Moab Trauerflöten gleich, und um die Männer von Kircheres seufzt mein Herz wie Trauerflöten, wenn das Ersparte doch verlorengeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Ein jedes Haupt ist deshalb eine Glatze und jeder Bart gestutzt, an allen Armen Ritzwunden, an allen Hüften Bußgewänder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Auf allen Dächern Moabs, auf seinen Plätzen nichts als Weheklagen, weil ich Moab so zerschmettere, als wärs ein mißliebig Gefäß.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, '\"Wie ist\'s doch zugerichtet! Vergießet Tränen! Wie schimpflich zeigte Moab seinen Rücken! Für seine ganze Nachbarschaft dient Moab zum Entsetzen und Gespött.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'So spricht der Herr: \"Dem Adler gleich fliegt es heran und breitet seine Flügel über Moab hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Die Städte werden eingenommen, die Festungen erobert. Das Herz der Helden Moabs gleicht an diesem Tag dem Herzen eines Weibs in Wehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Getilgt wird Moab aus der Völker Reihe; es brüstet sich dem Herren gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'So kommen Grauen, Grube, Garn, du Bürgerschaft von Moab, über dich.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, '\"Wer vor dem Grauen flieht, der fällt in eine Grube, und wer nicht in die Grube fällt, verfängt sich in dem Garn. Ich bringe solches über Moab im Jahre seiner Heimsuchung.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, '\"Sonst blieben die erschöpften Flüchtlinge im Schatten Hesbons stehen. Nun aber geht aus Hesbon Feuer aus und Flammenglut aus Sichon, und sie verzehrt die Schläfen Moabs mitsamt dem Hinterhaupt der Söhne des Gelärms.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Weh, Moab, dir! Aus ist es mit dem Volk des Kamos. Gefangen werden deine Söhne fortgeschleppt und deine Töchter in Verbannung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Doch wende ich das Schicksal Moabs am Schluß der Tage.\" Ein Spruch des Herrn. - Soweit die Strafgerichte über Moab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Über die Ammoniter: So spricht der Herr: \"Hat Israel denn keine Söhne? Hat es denn keinen Erben? Warum nimmt Milkom Gad für sich und läßt sich dort sein Volk in dessen Städten nieder?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Drum kommen, wahrlich, Tage\", ein Spruch des Herrn, \"da laß ich gegen Rabbat in der Ammoniter Land ein Kriegsgeschrei ertönen. Zu Trümmerhaufen wird\'s, und seine Tochterstädte brennen nieder, und Israel beerbt, die selbst es einst beerbt.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, '\"Du, Hesbon, weine! Vertilgt ist Haj. Wehklagt, ihr Töchter Rabbas! Umgürtet euch mit Bußgewändern! Schlagt an eure Brust! Und lauft von Ort zu Ort! In die Gefangenschaft muß Milkom ziehen und seine Priester, seine Fürsten miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Was prahlst du von den Tälern, dein Talgrund fließe immer, verkehrte Tochter du, die sich auf ihre Schätze ganz verläßt: \'Wer kommt mir darin gleich?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Führwahr, ich bringe Grauen über dich\", ein Spruch des Herrn, des Herrn der Heerscharen, \"von allen Seiten um dich her, daß einer vor sich her den andern treibe und niemand mehr die Flüchtigen sammle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Doch später wende ich der Ammoniter Schicksal.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Über Edom: So spricht der Heeresscharen Herr: \"Ist keine Weisheit mehr in Teman? Kam bei den Klugen Rat abhanden? Ist ihre Weisheit jetzt verschüttet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fort! Geht davon! Versteckt euch tief, Bewohner Dedans! Denn Not verhäng ich über Esau, die Zeit, da ich ihn strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Wenn Winzer über dich gekommen wären, sie hätten keine Nachlese zurückgelassen? Wenn Diebe in der Nacht, dann hätten sie nur soviel Schaden angerichtet, bis sie genügend hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Ich selber decke Esau auf und ziehe sein Verstecktestes hervor. Verstecken kann man sich nicht mehr; zugrund geht sein Geschlecht. Um seine Brüder ist\'s geschehen, seine Nachbarn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Laß deine Waisen, auf daß ich das Leben ihnen wahre! Vertrauen mögen deine Witwen nur auf mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'So spricht der Herr: \"Die\'s nicht verdient, den Kelch zu trinken, die mußten ihn, wahrhaftig, leeren. Und du willst frei ausgehen? Nein! Du mußt ihn trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Ich schwöre bei mir\", ein Spruch des Herrn, \"zum Spott und zum Entsetzen, zur Wüste und zum Fluch wird Bosra und alle seine Städte ewig Ödland.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Ich hörte von dem Herrn das Aufgebot. Ein Bote wurde an die Heidenvölker abgesandt: \"Versammelt euch! Rückt jetzt dawider! Brecht auf zum Kampfe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '\"Ich mache dich zum kleinsten Volke, zu dem verachtetsten der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Die Angst vor dir, dein Übermut hat dich betört, daß du in Felsenhängen wohnst, dich an den steilen Hang anklammerst. Und hättest du dein Nest so hoch wie Adler, ich stürzte dich von dort herab.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, '\"Und Edom wird zur Öde werden. Ein jeder Wandersmann wird staunend über alle seine Wunden spotten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Wie\'s war, als Sodoma und Gomorrha mit ihren Nachbarstädten einst vernichtet wurden,\" so spricht der Herr, \"so wohnt auch dort kein menschlich Wesen mehr, und niemand weilt darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Wie Löwen aus des Jordans Dickichte in wasserreiche Auen dringen, so laß\' ich es im Nu auch daraus stürzen, und wer auch immer ein Erlesener, dem gebe ich Befehl dawider. Wer ist denn so wie ich? Wer stellte mich zur Rede? Wer ist der Hirte, der vor mir bestünde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Drum hört des Herren Plan, den über Edom er gefaßt, und die Gedanken, die über Temans Einwohner er hegt! Die Schäferhunde schleppen sie hinweg. Man wird des Schreckens über sie und ihre Stätte voll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Von ihres Sturzes Dröhnen bebt die Erde; wie das Geschrei am Schilfmeere hört sich ihr Schreien an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Gleich einem Adler steigt es auf, fliegt her und breitet seine Flügel gegen Bosra aus. Das Herz der Krieger Edoms gleicht an jenem Tag dem Herzen eines Weibs in Nöten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Über Damaskus: \"Hamat und Arpad sind bestürzt, verzagen, weil sie unheilvolle Kunde hören, ein Wogen wie im Meer, das niemand stillt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus ist erschlafft und wendet sich zur Flucht; denn Schrecken hat\'s gepackt und Angst und Weh erfaßt gleich einer Kreißenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Warum nur wird sie jetzt verlassen, die hochgepriesene Stadt, die Stadt der Wonnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Auf ihren Straßen fallen ihre jungen Männer, und an jenem Tage werden alle Krieger hingeopfert.\" Ein Spruch des Herrn der Heeresscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, '\"Ich lege Feuer an Damaskus\' Mauern, daß es die Schlösser Benhadads verzehre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Von Kedar und dem Reich von Hasor, die Nebukadrezar, der Babelkönig, schlug, spricht so der Herr: \"Brecht auf! Zieht gegen Kedar, und greift des Ostens Söhne an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Weg nimmt man ihre Zelte, ihre Herden und ihre Decken, all ihre Sachen. Auch die Kamele führt man ihnen weg. Drob rufen sie: \'Ringsum ist Schrecken.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Flieht! Flüchtet eilends! Verbergt euch tief, ihr Bürger Chasors!\" Ein Spruch des Herrn. \"Denn einen Plan hat Nebukadrezar, der Babelkönig, und einen Anschlag gegen euch ersonnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Brecht auf! Zieht gegen ein harmloses Volk, das sicher haust\", ein Spruch des Herrn, \"das weder Tor noch Riegel hat und einsam wohnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Zum Raube werden die Kamele, zur Beute ihrer Herden Menge. Die mit gestutztem Haar zerstreue ich in alle Winde, bereite ihnen Untergang von allen Seiten.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, '\"Schakalen bietet Chasor Unterschlupf, ein ewig Ödland; niemand wohnt mehr darin; kein Menschenkind verweilt daselbst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Was einst als Wort erging an Jeremias, den Propheten, über Elam im Anbeginne der Regierung des Judakönigs Sedekias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So spricht der Heeresscharen Herr: \"Fürwahr! Ich breche Elams Bogen, das erste Werkzeug seiner Kraft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'und lasse gegen Elam die vier Winde los; von den vier Gegenden des Himmels, nach allen diesen Winden zerstreue ich sie. Kein Volk soll\'s geben, zu dem nicht die Versprengten Elams kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Verzagen laß ich Elam vor den Feinden, vor denen, die nach seinem Untergange trachten. Und Unheil bringe ich darüber und meines Zornes Glut.\" Ein Spruch des Herrn. \"Ich laß dem Schwerte hinter ihnen freien Lauf, bis ich sie aufgerieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'In Elam setze ich dann nieder meinen Thron, vernichte dort den König samt den Fürsten.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, '\"Doch wende ich am Ende jener Tage auch Elams Schicksal.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Das Wort, das über Babel und das Chaldäerland der Herr durch Jeremias, den Propheten, einst geredet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '\"Verkündet\'s bei den Heidenvölkern! Macht es bekannt! Tut\'s kund! Laßt\'s kein Geheimnis bleiben, sprecht: \'Erobert wurde Babel, zu Schanden Bel und Merodach gestürzt. Zertrümmert wurden seine Götzenbilder, zerschmettert seine Götzentempel.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Von Norden zieht gen Babel her ein Heidenvolk, das macht sein Land zum Grauen, das künftig niemand mehr bewohnen wird. Denn Mensch und Tiere wandern aus und ziehen fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'In jenen Tagen und zu jener Stunde\", ein Spruch des Herrn, \"erscheinen Israels Söhne freiwillig und Judas Söhne miteinander. Sie kommen unter Tränen, nach ihrem Gott und Herrn verlangend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Sie sehnen sich nach Sion, das Antlitz auf den Weg dahin gerichtet. Sie kommen, an den Herrn sich anzuschließen durch einen ewigen Bund, der unvergessen bleibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Verlorenen Schafen gleicht mein Volk, und ihre Hirten führen diese irre, verleiten sie zum Abfall auf den Bergen. So ziehen sie von Berg zu Hügel, vergessen ihres Ruheortes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Wer auf sie stößt, verzehret sie, und ihre Widersacher sprechen: \'Wir laden keine Schuld auf uns\', dafür, daß sie am Herren sich vergangen, dem rechten Ruheort; war doch der Herr auch ihrer Väter Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Aus Babel flieht! Aus dem Chaldäerland eilt fort! Seid wie die Böcke vor der Herde!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Ich reize gegen Babel große Völkerhaufen und laß sie aus dem Nordland kommen. Sie stellen sich gen Babel auf; von dort bedräuen ihre Pfeile, gleich denen eines kriegserfahrenen Helden, der nicht erfolglos heimwärts zieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'So wird Chaldäa eine Beute, und alle, die drin Beute machen\", ein Spruch des Herrn, \"die machen sie in Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Wie freutest du dich einst und wie frohlocktest du, als du mein Eigentum geplündert! Wie sprangst du, einem Rinde auf der Weide gleich, und wiehertest wie ein Hengst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Doch nun wird eure Mutter elendig zuschanden; die euch geboren, wird voll Scham. Sieh da, der Heidenvölker Ende: \'Die Steppe, Öde, Wüste!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Nicht mehr besiedelt wird es durch den Grimm des Herrn; in seinem ganzen Umfang bleibt es eine Wüste. Ein jeder Wandersmann staunt über Babel und pfeift gar höhnisch über alle seine Wunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Um Babel stellt euch auf, ihr Bogenschützen alle! Und schießt die Pfeile schonungslos darauf! Denn an dem Herren hat sich\'s versündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Erhebet gegen es von allen Seiten ein Geschrei: \'Sein Heer hat sich ergeben; die Zinnen sind gefallen, die Mauern eingerissen!\' Des Herren Rache ist\'s. Vollzieht an ihm die Rache! Tut ihm genau so, wie es selbst getan!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Vertilgt aus Babel jeden, der das Feld bestellt, jedweden, der zur Erntezeit die Sichel führt! Ein jeder wendet sich vorm Würgeschwert zu seinem Volk, ein jeder flieht in seine Heimat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Wie eine Herde, die versprengt und von den Löwen ward verjagt, also war Israel. Den einen Teil hat Assurs König aufgefressen; dem andern Teile hat die Knochen Nebukadrezar, Babels König, abgenagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Deshalb spricht so der Herr der Heerscharen, Gott Israels: \"Den Babelkönig und sein Land bestrafe ich, wie ich auch Assurs König strafte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'und bringe Israel auf seine Weide wieder, und weiden soll es auf dem Karmel und in Basan. Auf Ephraims Gebirge und in Gilead soll\'s seinen Hunger stillen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Forscht man in jenen Tagen und zu jener Zeit\", ein Spruch des Herrn, \"nach Israels Vergehn, so zeigt sich keines mehr, und nach den Sünden Judas, man findet keine. Denn denen, die ich übrig ließ, verzeihe ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, '\"Rück wider Marataimland heran! Zieh doch dagegen, zieh gegen Pekods Leute! Mach sie nieder! Vollstreck den Bann!\" Ein Spruch des Herrn. \"All das, was ich dir anbefohlen, tu!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Horch auf! Im Land ist Krieg, gewaltiger Zusammenbruch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Wie ist verstümmelt und zerbrochen der Hammer aller Welt! Wie wurde Babel zum Schrecken bei den Völkern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, '\"Ich legte, Babel, dir ein Netz; du hast dich drin verfangen. Und du bemerktest nicht, daß du gepackt und dann verschlungen wurdest, weil mit dem Herren du gekämpft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Der Herr tat seine Kammer auf und holt\' daraus die Waffen seines Grimmes. Denn Arbeit gab\'s in dem Chaldäerlande für den Herrn, den Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Zu Leibe geht ihm gründlich! Erbrecht ihm seine Scheunen! Wie Garben schüttet\'s auf! Vollstreckt an ihm den Bann, auf daß von ihm nichts übrigbleibe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'All seine Farren metzelt nieder! Zur Schlachtbank laßt sie wandern! Weh ihnen! Ihr Tag ist angebrochen, die Stunde ihrer Strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Horch! Flüchtlinge, die sich aus Babels Land gerettet, um auf dem Sion zu verkünden: \"Des Herren, unseres Gottes Rache ist\'s, die Rache für sein Heiligtum.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Gen Babel bietet Schützen auf, die Bogenschützen all! Und lagert euch herum, damit kein Mensch entkomme! Vergeltet ihm nach seinem Tun! Tut ihm genau so, wie es selbst getan! Denn übermütig war es gen den Herrn, den Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, '\"Drum fallen seine Jünglinge auf seinen Straßen, und alle seine Krieger werden an jenem Tage ausgerottet.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '\"Ich will an dich, du Frechheit\", ein Spruch des Herrn, des Herrn der Heerscharen, \"dein Tag ist ja gekommen, die Stunde deiner Strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Die Frechheit strauchelt jetzt und fällt, und niemand hilft ihr auf. An ihre Städte lege ich ein Feuer, das alles rings um sie verzehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So spricht der Herr der Heerscharen: \"Gleich grausam wurden Israels und Judas Söhne unterdrückt. Die sie gefangen weggeführt, die halten sie noch immer fest und weigern sich, sie loszulassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Ihr Rächer aber ist ein Starker; er heißt \'Der Herr der Heerscharen\'. Er führt mit Eifer ihre Sache. Er will der Welt zur Ruhe helfen; drum nimmt er Babels Einwohnern die Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, '\"Ein Schwert komm über die Chaldäer\", ein Spruch des Herrn, \"und über Babels Einwohner und seine Fürsten, seine Weisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Ein Schwert komm über diese Großsprecher, sie sollen Narren werden! Ein Schwert komm über seine Krieger, auf daß sie zittern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Fluch über seine Rosse, seine Wagen und übers ganze Volk in seiner Mitte, auf daß sie Weiber werden! Fluch über seine Schätze, daß sie geplündert werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Fluch über seine Wasser, daß sie vertrocknen! Ein Land der Götzenbilder ist es ja; sie rühmen sich noch ihrer Götter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Drum sollen wilde Katzen neben den Schakalen hausen und Strauße drinnen wohnen. Nie soll es mehr besiedelt werden, noch je bewohnt in Ewigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Wie\'s war, als Gott einst Sodom und Gomorrha mitsamt den Nachbarstädten ausgetilgt\", ein Spruch des Herrn, \"so wohnt auch dort kein menschlich Wesen mehr, und niemand weilt darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Von Norden kommt ein Volk und eine ganz gewaltige Nation, und viele Könige erheben sich vom Rand der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Sie führen Bogen, Wurfspieße, sind grausam und erbarmungslos. Ihr Lärmen tost dem Meere gleich; auf Rossen reiten sie, gerüstet wie ein Mann zum Kampfe, her gegen dich, du Tochter Babels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Der Babelkönig hört von ihnen, und seine Hände sinken schlaff. Ihn packt die Angst, ein Zittern wie das der Kreißenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Wie Löwen aus des Jordans Dickicht in wasserreiche Auen dringen, so lasse ich im Nu ihn daraus stürzen, und wer nur immer ein Erlesener ist, dem geb dagegen ich Befehl. Wer ist denn so wie ich? Wer stellte mich zur Rede? Wer ist der Hirte, der vor mir bestünde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Drum hört des Herren Plan, den gegen Babel er gefaßt, und die Gedanken, die gegen das Chaldäerland er hegt! Fürwahr, die Schäferhunde schleppen sie hinweg. Man wird voll Schrecken über sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Vom Rufe \"Babel ist erobert\" bebt die Welt; die Erde zittert; sein Wehgeschrei tönt bei den Völkern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So spricht der Herr: \"Sieh! Gegen Babel und die im \'Herzen meiner Widersacher\' wohnen, erhebe ich den Sturmwind voll Verderbnis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'und sende gegen Babel Worfler. Sie sollen\'s worfeln, dann sein Land ausfegen. Von allen Seiten kommen sie darüber am schreckensvollen Tage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Der Schütze spanne seinen Bogen und lege seinen Panzer an! Schont seiner jungen Männer nicht! Dem Banne übergebt sein Heer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Erschlagne liegen im Chaldäerland und Schwerverwundete in seinen Gassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Von ihrem Gott sind Israel und Juda nicht verlassen, vom Herrn der Heerscharen, obwohl ihr Land voll Schuld beim Heiligen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Aus dem Bereich von Babel flieht; sein Leben rette jeder, damit ihr nicht um seiner Sünde willen untergeht! Der Rache Zeit ist\'s für den Herrn; er gibt ihm seinen Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Ein Becher goldenen Weins war Babel in der Hand des Herrn, ein Becher, der die ganze Welt berauschte. Von seinem Weine mußten Heidenvölker trinken; wie toll benahmen sich die Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Gestürzt ist plötzlich Babel und zerschmettert. Darüber heult! Für seinen Schmerz holt Balsam her! Vielleicht ist es noch heilbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '\"Doch wollten wir auch Babel heilen, es ist unheilbar.\" Nun, laßt es! Ziehn wir, jeder hin in seine Heimat. Bis zum Himmel streckt sich sein Verbrechen; bis zu den Wolken steigt\'s hinan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Der Herr zog unsere gerechte Sache ans Tageslicht. Auf! Laßt in Sion uns erzählen des Herren, unseres Gottes, Wirken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Die Pfeile schärft! Rüstet die Schilde! Der Herr reizt Mederkönige zum Grimm. Denn wider Babel geht sein Sinnen, es zu vernichten. Des Herren Rache ist\'s, die Rache für sein Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Steckt Flaggen aus auf Babels Mauern! Verstärket die Bewachung! Stellt Posten auf! Legt Hinterhalte! Doch was der Herr beschlossen, führt er aus, was einst er Babels Einwohnern gedroht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Die du an vielen Wassern wohnst, so reich an Schätzen! Da ist dein Ende, dein einzig bleibender Gewinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Der Herr der Heerscharen schwört bei sich selbst: \"Wenn ich dich auch mit Menschen wie mit Ungeziefer angefüllt, so jauchzt man dennoch über dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Er ist es, der durch seine Kraft die Erde machte, durch seine Weisheit einst den Erdkreis gründete, durch seine Einsicht auch dem Himmel seine Weite gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Läßt er am Himmel Wasserbrausen hörbar werden, und führt er Wolken von der Erde Rand herauf, und schafft er Blitze, daß es regnet, und führet er den Wind aus seinen Kammern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'dann muß ein jeder Laie sich für töricht halten, weil er merkt, und jeder Künstler muß verblüfft dastehen, weil er sieht: Sein Gußbild ist nur Trug, ganz ohne Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Nur eitel Wahn sind sie, ein Possenspiel, und wenn ein Unglücksfall sie trifft, ist\'s aus mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Doch solchen gleicht nicht Jakobs Teil. Er ist vielmehr des Weltalls Schöpfer, und sein besonderer Stamm ist Israel, und \"Herr der Heeresscharen\" ist sein Name.-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, '\"Ein Hammer warst du mir, ein Kriegsgerät; mit dir zerhämmerte ich Heidenvölker; mit dir zertrümmerte ich Reiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Mit dir zerhämmerte ich Roß und Reiter; mit dir zerhämmerte ich Wagen samt den Fahrern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Mit dir zerhämmerte ich Mann und Weib; mit dir zerhämmerte ich Greis und Knabe; mit dir zerhämmerte ich Jünglinge und Jungfrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Mit dir zerhämmerte ich Hirt und Herde; mit dir zerhämmerte ich Bauer und Gespann; mit dir zerhämmerte ich Statthalter und Vögte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Nun will ich Babel und allen Bewohnern von Chaldäa vor euren Augen all das Böse lohnen, das sie an Sion ausgeübt.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, '\"Ich will an dich, du Unheilsberg,\" ein Spruch des Herrn, \"der alle Welt verheerte. Ich laß dich meine Stärke fühlen und stürze dich hinab von jenen Felsen und mache dich zum ausgebrannten Berge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Kein Mensch holt einen Eckstein mehr von dir, noch einen Stein zum Grunde. Du wirst zur ewigen Wüste.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Steckt Flaggen auf der Erde aus! Ihr Hörner, stoßet bei den Heidenvölkern, und sammelt Völker gegen dies! Dagegen ruft des Ararats und Minnis Reiche und das von Askenaz herbei! Bestelle Späher gegen es! Dem borstigen Ungeziefer gleich laßt Rosse kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Ruft Völker auf dagegen, die Könige Mediens und seine Statthalter und Vögte alle und alle Länder seiner Herrschaft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Die Erde zittert und erbebt. An Babel geht der Plan des Herren in Erfüllung, das babylonische Land zur unbewohnten Wüstenei zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Die Krieger Babels hören auf zu kämpfen und hocken in den Burgen. Versiegt ist ihre Kraft; sie sind jetzt Weiber. Verbrannt sind seine Wohnungen, zerbrochen seine Riegel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Ein Läufer läuft dem Läufer zu, ein Bote jetzt dem Boten, dem Babelkönig zu vermelden, daß seine Stadt an allen Ecken eingenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Die Furten sind besetzt, die Schlupfwinkel verbrannt, die Krieger ganz bestürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'So spricht der Heeresscharen Herr, Gott Israels: \"Der Tochter Babels geht\'s wie einer Tenne. Man stampft sie fest; noch kurze Zeit, dann kommt dafür die Zeit der Ernte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, '\"Nebukadrezar, Babels König, fraß mich auf, verschluckte mich. Er machte sich ein Nichts aus mir, und er verschlang mich wie ein Drache und füllte seinen Bauch mit meinen Kostbarkeiten und leerte mich dann aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Es komme über Babel mein mißhandelt Fleisch!\", so spreche Sions Bürgerschaft! \"Auch komme über die Bewohner von Chaldäa mein Blut!\", spreche Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Deshalb spricht so der Herr: \"Fürwahr, ich führe deinen Streit und nehme Rache jetzt für dich. Sein Meer laß ich vertrocknen und versiegen seinen Quell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Und Babel wird ein Trümmerhaufen, die Lagerstätte der Schakale, zum Spott und zum Entsetzen, menschenleer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Noch brüllen sie zusammen, den jungen Löwen gleich, und knurren wie die Löwenkatzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Doch mache ich für sie recht hitzig ihr Gelage, daß sie berauscht aufspringen und dann in ewigen Schlaf verfallen und nimmermehr erwachen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, '\"Wie Lämmer laß ich sie zur Schlachtbank wandern, wie Widder samt den Böcken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Wie ist doch Sesak eingenommen, der ganzen Erde Ruhm, erobert! Wie wird zum Grauen Babel bei den Heiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Das Meer stürzt über Babel her; von seiner Wellen Schwall wird es bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Zur Wüste werden seine Städte, zum dürren Land, zur Steppe, zum Land, darinnen niemand wohnt, durch das kein menschlich Wesen zieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, '\"Heimsuchen werde ich auch Bel in Babel und reiße ihm aus seinem Maule das Verschluckte. Nie sollen Völker wieder zu ihm strömen! Auch Babels Mauer stürzt zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Zieh fort, mein Volk, aus seiner Mitte! Sein Leben rette jeder vor der Zornesglut des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Daß euer Herz doch nicht verzage, daß ihr bei dem Gerücht, das man im Land vernimmt, in keine Furcht geratet, wenn in dem einen Jahre dies Gerücht auftritt, im andern das, und wenn Gewalttat in dem Land geschieht und Herrscher gegen Herrscher sich erheben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'So seht, es kommen Tage, da ich die Götzenbilder Babels heimsuche. Sein ganzes Land wird übel riechen, weil überall umher Erschlagene liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Und über Babel jubelt mit der Erde selbst der Himmel samt allem, was darin, wenn drüber Räuber aus dem Norden kommen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Auch Babel fällt, Erschlagene Israels! Sie fallen auch in Babel, Erschlagene der ganzen Welt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Die ihr dem Schwert entronnen, fort! Bleibt nicht stehn! Erinnert euch in weiter Ferne an den Herrn, und euer Sinnen richte auf Jerusalem sich hin:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '\"Wir schämten uns, als wir die Schmähung hörten, und Schande deckte unser Angesicht, daß Fremde in des Herren heilig Haus gedrungen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, '\"Dafür erscheinen Tage\", Spruch des Herrn, \"wo ich selbst seine Götzenbilder heimsuche. In seinem ganzen Lande stöhnen dann Verwundete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Denn steigt auch Babel bis zum Himmel, befestigt\'s in der Höhe seine Macht, so dringen doch von mir Verwüster ein\". Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Horch! Schreien tönt aus Babel. Im Lande der Chaldäer großer Niederbruch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Der Herr verwüstet Babel völlig und tilgt daraus das laute Lärmen. Gleich großen Wassern tosen seine Wogen; gewaltig tobt ihr Lärm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Denn Babel überfällt ein Räuber; gefangen werden seine Krieger. Der Herr zersplittert ihre Bogen. Der Herr ist ein Vergeltungsgott, der ganz genau vergilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, '\"Berauschen will ich seine Fürsten, seine Weisen und seine Statthalter und Vögte, seine Krieger. Zum ewigen Schlaf entschlummern sie und wachen nimmer auf.\" Ein Spruch des Königs, der \"Herr der Heeresscharen\" heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So spricht der Heeresscharen Herr: \"Die breite Mauer Babels wird geschleift, und seine hohen Tore werden angezündet. Es haben Völker für ein Nichts geschafft, fürs Feuer sich Nationen abgemüht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Das Wort, das Jeremias, der Prophet, dem Seraja, Nerias Sohn, Machsejas Enkel, auftrug, als er nach Babel mit dem Judakönige Sedekias zog, im vierten Jahre seines Königtums. Seraja aber war ein Fürst, der für den Frieden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Nun hatte aber Jeremias all das Unheil, das über Babel kommen sollte, in ein besonderes Buch geschrieben, all diese Reden, die über Babel aufgeschrieben sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Jeremias sprach zu Seraja: \"Kommst du nach Babel, lies dann mit Bedacht all diese Worte vor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Und sprich: \'Du selbst bist\'s, Herr, der diesem Ort Vernichtung angedroht, daß niemand mehr drin weile, nicht Mensch, nicht Tier, denn: Eine ewige Wüste sollst du werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Und hast zu Ende du dieses Buch gelesen, dann binde einen Stein daran und wirf es mitten in den Euphratfluß');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'und sprich: \'Gerade so soll Babel untersinken und nimmer sich erheben ob des Unheils, das ich darüber bringe.\' Sie mühen sich ab.\" - Bis dahin reichen des Jeremias Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Als Sedekias König wurde, war er einundzwanzig Jahre alt, und zu Jerusalem regierte er elf Jahre. Seine Mutter hieß Hamutal und war des Jeremias Tochter aus Libna.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Er tat, was dem Herrn mißfiel, ganz so wie Jojakim getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Des Herrenzornes wegen kam er über Juda und Jerusalem, bis daß er sie verstoßen mußte. Und Sedekias fiel vom Babelkönig ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Im neunten Jahre seines Königtums, am zehnten Tag des zehnten Monats, zog Nebukadrezar, Babels König, mit seinem ganzen Heere gen Jerusalem. Und sie belagerten es und bauten ringsum einen Wall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'So ward die Stadt belagert bis zu dem elften Jahr des Königs Sedekias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Am neunten Tag des vierten Monats nahm in der Stadt der Hunger überhand, und auch das Landvolk hatte gar nichts mehr zu essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Da wurde eine Bresche in die Stadt gelegt, und alle Krieger flohen und gingen aus der Stadt bei Nacht durchs Tor, das zwischen jenen beiden Mauern am Königsgarten liegt, solange die Chaldäer noch die Stadt umzingelten. Und jene zogen nach der Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Die Truppen der Chaldäer aber jagten dem König nach und holten in den Steppen Jerichos den Sedekias ein, nachdem all seine Truppen weit zersprengt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Sie nahmen nun den König fest und führten ihn zum Babelkönige nach Ribla im Land Hamat, und der sprach ihm das Urteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Der Babelkönig nämlich ließ des Sedekias Söhne vor seinen eigenen Augen niedermachen; dann ließ er auch zu Ribla alle Fürsten Judas töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Den Sedekias aber ließ er blenden und in Ketten legen. So ließ der Babelkönig ihn nach Babel führen, und er behielt ihn bis zu seinem Todestage im Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Am zwölften Tag des fünften Monats - es war das neunzehnte Jahr des Königs Nebukadrezar, des Babelkönigs - kam Nebuzaradan, der Oberste der Leibwächter, des Babelkönigs Diener, nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Und er verbrannte das Haus des Herrn sowie das Haus des Königs und alle andere Häuser zu Jerusalem; die großen Häuser alle brannte er nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Sämtliche Mauern um Jerusalem rissen die Truppen der Chaldäer nieder, die beim Obersten der Leibwächter waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Und abgesehen von den ganz geringen Leuten aus dem Volk, führte Nebuzaradan, der Oberste der Leibwächter, den Rest des Volkes, der in der Stadt noch übrig war, gefangen ab mitsamt den Überläufern, die zum Babelkönig übergingen, sowie den Rest der Handwerker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Nur von des Landes ganz geringen Leuten ließ Nebuzaradan, der Oberste der Leibwächter, ein paar als Winzer und als Bauern hier zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Die ehernen Säulen im Haus des Herrn, die Gestelle und das eherne Meer im Hause des Herrn zerbrachen die Chaldäer und brachten alles Erz davon nach Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Die Töpfe, Schaufeln, Messer, Sprengschalen und Schalen sowie die ehernen Geräte, mit denen man den Dienst versah, nahmen sie alle mit fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Die Becken, Pfannen, Sprengschalen, Töpfe und Leuchter sowie die Schalen und Becher, von Gold die einen und die anderen von Silber, nahm der Oberste der Leibwächter auch mit;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'und die zwei Säulen, das eine Meer, die zwölf ehernen Rinder darunter, die Gestelle, die König Salomo einst für das Haus des Herrn gemacht. Gar nicht zu wägen war das Erz all der Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Was die Säulen anbelangt, so war die eine Säule achtzehn Ellen hoch, und eine Schnur, zwölf Ellen lang, umspannte sie; sie war vier Finger dick und hohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Ein Knauf auf ihr war ehern; des einen Knaufes Höhe war fünf Ellen. Ein Flechtwerk von Granatäpfeln war rings um diesen Knauf, ganz ehern. Genau so war es bei der zweiten Säule und so bei den Granatäpfeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Dieser Granatäpfel waren es nach außen hin sechsundneunzig. Rings ums Flechtwerk waren es hundert Granatäpfel im ganzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Der Oberste der Leibwächter verhaftete den Oberpriester Seraja sowie den zweiten Priester Sephanja und die drei Schwellenhüter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Und aus der Stadt nahm er noch einen Kämmerer mit, der Kriegsleute befehligte, und sieben Männer aus des Königs Günstlingen, die in der Stadt geblieben, sowie des Feldhauptmannes Schreiber, der zu dem Heeresdienst das Landvolk aufbot, und aus dem Landvolk sechzig Mann, die in der Stadt sich aufhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Die nahm der Oberste der Leibwächter, Nebuzaradan, und brachte sie zum Babelkönig nach Ribla.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Der Babelkönig aber ließ sie stäupen und zu Ribla im Lande Hamat hinrichten. Also ward Juda weggeführt von seinem Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dies war das Volk, das Nebukadrezar fortführte: im siebten Jahre 3.023 Judäer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'im achtzehnten Jahre Nebukadrezars 832 Seelen aus Jerusalem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'im dreiundzwanzigsten Jahre Nebukadrezars führte Nebuzaradan, der Oberste der Leibwächter, von den Judäern 745 Seelen fort: zusammen 4.600 Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Im siebenunddreißigsten Jahre der Wegführung des Judakönigs Jojachin, am fünfundzwanzigsten des zwölften Monats geschah es, daß der Babelkönig Evilmerodach im Jahre, da er König ward, Bescheid über den Judakönig Jojachin erhielt und ihn aus dem Gefängnisse entließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Er redete freundlich mit ihm und stellte seinen Sitz über den der andern Könige, die noch bei ihm zu Babel waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Er legte seine Kerkerkleider ab und speiste beständig vor ihm alle Tage seines Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Sein ständiger Unterhalt ward ihm vom Babelkönige gewährt, soviel er täglich brauchte, bis zu seinem Todestag, solang er lebte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Wie sitzt so einsam da die Stadt, vordem so reich an Volk! Wie ward zu einer Witwe, die einst so groß war unter den Nationen! Die Königin der Länder muß Sklavendienste tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Sie weint und weint noch in der Nacht; die Tränen netzen ihre Wangen. Nicht einer ihrer Buhlen tröstet sie; all ihre Freunde brechen ihr die Treue und werden ihre Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Vor Elend schwindet Juda hin vor hartem Sklavendienst. Jetzt weilt es bei den Heiden und findet keine Ruhestatt. Alle, die es verfolgen, sie finden es in Nöten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Die Sionswege trauern; Festpilger fehlen. All ihre Tore sind verödet, und ihre Priester seufzen, und ihre Jungfrauen sind voll Gram, ihr selbst ist\'s wehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Und ihre Feinde kommen obenauf, und wohlgemut sind ihre Gegner. Der Herr hat sie mit Gram erfüllt ob ihrer vielen Sünden; fortziehen ihre Kinder in Gefangenschaft, vorm Feinde her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Fortzieht von Sions Tochter all ihre Herrlichkeit. Und ihre Fürsten gleichen Widdern, die keine Weide finden und so vorm Treiber kraftlos laufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem gedenkt in seines Elends Tagen und seiner Heimatlosigkeit all seiner Herrlichkeiten, die seit der Urzeit ihm beschert gewesen, wie nun sein Volk durch Feindes Hände fiel und niemand ihm zu Hilfe eilte und ihm die Dränger zuschauten und seines Feierabends wegen lachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Schwer hat Jerusalem gesündigt; zum Abscheu ist es drum geworden. Die einstens es verehrt, verachten\'s alle. Sie schauten seine Blöße, und selberseufzt es tief, sich abwendend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Sein Unflat klebt an seinen Säumen; sein Ende hat es nicht bedacht. In unerhörter Weise kam\'s herab; ihm fehlte jeder Tröster. \"Ach Herr, sieh doch mein Elend an! Der Feind frohlockt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Der Feind streckt seine Hände aus nach allen seinen Schätzen. Es mußte sehn, wie in sein Heiligtum die Heiden drangen, von denen du geboten: \"Sie dürfen nicht in die Gemeinde dein gelangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'All seine Leute seufzen, suchen Brot. Sie geben ihre Schätze hin für Speise, um so das Leben sich zu fristen. \"Herr, schau und blicke her, wie ich mißachtet bin!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Nicht stimmt\'s zu euerer Erfahrung. \"Ihr all, die ihr des Weges zieht! Schaut her und seht, ob ist ein Schmerz wie meiner, der mir ward angetan, mir, die der Herr mit Gram erfüllte am Tage seiner Zornesglut!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Er sandte aus der Höhe Feuer hin in mein Gebein und ließ es tief eindringen, und meinen Füßen stellte er ein Netz; zurück getrieben hat er mich und mich gar jammervoll gemacht, für alle Zeiten siech.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Gefertigt ward mein Sündenjoch. Durch seine Hand ward es geknüpft und kam auf meinen Nacken. Er brach mir meine Kraft. Der Herr hat mich in Hände überliefert, aus denen ich mich nicht befreien kann');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Verworfen hat der Herr all meine Helden in meiner Mitte, und er beraumte wider mich den Tag, um meine jungen Männer zu zermalmen. Der Herr trat selbst die Kelter der Jungfrau, Judas Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Darüber weine ich. Mein Auge, ja mein Auge fließt in Wasser. Denn fern ist mir der Tröster, der mir die Seele labt. Verstört sind meine Kinder; der Feind so stark.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Es streckte Sion seine beiden Hände aus; doch fand es keinen Tröster. Der Herr entbot gen Jakob von allen Seiten seine Feinde. So ward Jerusalem bei ihnen zu einem Schimpfwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, '\"Der Herr ist so gerecht; denn seinem Worte trotzte ich. Ihr Völker alle! Hört es! Seht meinen Schmerz mit an! Gefangen zogen meine Jungfrauen fort und meine Jünglinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Ich rufe meinen Buhlen zu; sie lassen mich im Stich, und meine Priester, meine Ältesten, verschmachten in der Stadt. Sie suchen für sich Speise, um so das Leben sich zu fristen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Sie, Herr, wie mir so bange! Mein Inneres glüht; im Busen dreht sich mir das Herz; denn ich bin voll von Bitternissen. Das Schwert würgt draußen meine Kinder; drin herrscht die Pest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Sie hören, wie ich seufze; ich aber habe keinen Tröster. Von meinem Unglück hören alle meine Feinde; sie jubeln, daß Du mir es angetan, daß Du herbeigeführt den Tag, den Du verkündet, und waren doch wie ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Laß ihre Bosheit vor Dich kommen! An ihnen tu, wie Du an mir getan um aller meiner Sünden willen! Denn ohne Zahl sind meine Seufzer; mein Herz ist siech.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Wie hat umwölkt in seinem Zorn der Herr die Sionstochter! So tief gestürzt vom Himmel auf die Erde die Herrlichkeit von Israel! Er dachte nicht an seiner Füße Schemel an seinem Zornestage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Der Herr vertilgte schonungslos die Auen Jakobs insgesamt. In seinem Grimme riß er nieder die Festungen der Tochter Judas und warf zu Boden den König und die Fürsten - todeswund;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'in Zornglut hieb er ab ein jeglich Horn in Israel und schlug ihm seine Rechte vor dem Feind zurück, und dieser wütete in Jakob gleich einer Flammenlohe, die alles ringsumher verzehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Er spannte seinen Bogen wie ein Gegner, und reckte wie ein Feind die Rechte; er tötete all ihre Augenlust im Zelt der Sionstochter und goß den Grimm wie Feuer aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Der Herr hat sich als Feind gezeigt und Israel gestürzt, all seine Burgen eingerissen und seine Festungen zerstört und Jammer über Jammer bei Judas Tochter angehäuft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Und seine Hütte riß er nieder gleich einer bloßen Gartenhütte, zerstreute seine Offenbarungsstätte. Vergessen ließ der Herr in Sion die Festtage und Sabbate. Und er verwarf in seinem grimmen Zorn den König und den Priester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Und seinen Altar hat der Herr verschmäht, sein Heiligtum verworfen, in Feindeshand gegeben all die Mauern seiner Burgen. Sie schrieen in dem Haus des Herrn, als wär\'s ein Feiertag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Der Herr bot alle seine Künste auf, der Sionstochter Mauern zu zerstören. Er zog die Meßschnur drüber her und hemmte seine Hand nicht im Zerstören. Da trauerten zusammen Wall und Mauer und härmten sich zusammen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Versunken in die Erde ihre Tore und ihre Riegel unbrauchbar, zerbrochen. Ihr König, ihre Fürsten weilen bei den Heiden; und ein Gesetz gibt\'s nimmermehr, und ihre Seher erhalten keine Offenbarung mehr vom Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Am Boden sitzen schweigend die Ältesten der Sionstochter. Sie streuen Staub auf ihren Kopf, mit härenem Gewand gegürtet. Zu Boden senken ihre Häupter die Jungfrauen Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'In Tränen schwinden meine Augen; mein Inneres glüht, und meine Leber fließt zu Boden; denn meines Volkes Tochter ist vernichtet. Auf öffentlichen Plätzen verschmachten Säuglinge und Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Sie rufen ihren Müttern zu: \"Wo gibt es Brot?\" und keins ist da. Wie todwund schmachten sie dahin auf öffentlichen Plätzen. In ihrer Mütter Schoß verhauchen sie ihr Leben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Was soll ich dir nur gleichstellen, womit dich nur vergleichen, du Tochter von Jerusalem? Wem setze ich dich gleich, um dich zu trösten, du Jungfrau, Sions Tochter? Groß wie das Meer ist deine Wunde; wer kann dich heilen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Dir schauten deine Seher Lug und Trug. Sie sagten über deine Sünde nichts, um dadurch dein Geschick zu wenden. Sie haben dir erschaut nur Sprüche zum Betrug und zur Verführung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Die Hände schlugen über dich zusammen sie alle, die des Weges zogen. Sie zischten, schüttelten das Haupt über die Tochter von Jerusalem: \"Ist das die Stadt, von der man sagte, sie sei der Schönheit Krone, der ganzen Erde Lust?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'All deine Feinde rissen wider dich den Mund weit auf. Sie zischten, knirschten mit den Zähnen und sprachen: \"Wir vertilgen es. Das ist der Tag, den wir erhofft; wir haben es erreicht, erlebt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Der Herr hat ausgeführt, was er geplant, sein Wort erfüllt, das er seit alten Zeiten angedroht. Er riß zu Boden schonungslos und ließ den Feind frohlocken über dich und deiner Gegner Horn emporwachsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Zum Herrn schreit aus Herzensgrund die Sionstochter in Bekümmernis. Laß deine Tränen stromweis rinnen bei Tag und Nacht! Gönn keine Ruhe dir! Nicht rasten soll dein Augenstern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Auf! Jammere laut noch durch die Nacht bis zum Beginn der Nachtwachen! Dem Wasser gleich schütte dein Herz aus vorm Angesicht des Herrn! Zu ihm erhebe deine Hände um deiner Kindlein Leben, die Hungers voll an allen Straßenecken schmachten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, '\"Herr, sieh darein und schau! Wem hast du solches angetan, wenn Weiber ihre Leibesfrucht, die Kinder ihrer Wartung, essen, wenn selbst im Heiligtum des Herrn gemordet werden Priester und Prophet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Es liegen auf dem Boden in den Straßen die Knaben samt den Greisen; hinfallen meine Jungfrauen und meine Jungmänner durchs Schwert. An deinem Zornestage mordest du und schlachtest schonungslos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Du hast von überall her wie zu einem Fest in meine Fremdenzimmer eingeladen; am Tag des Herrenzorns war niemand, der entronnen und entkommen wär von denen, die ich einst gepflegt und aufgezogen. Mein Feind hat sie vernichtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ich bin der Mann, der Elend hat erfahren durch seines Grimmes Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Mich drängte er und führte mich in Finsternis und tiefes Dunkel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'An mir erprobt er immer wieder seine Macht den ganzen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Er rieb mir auf mein Fleisch und meine Haut, zerbrach mir mein Gebein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Und eingeschritten ist er gegen mich mit Gift und Aufhängen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'versetzte mich in Finsternis wie ewig Tote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Er mauerte mich ein, ließ keinen Ausweg offen, beschwerte mich mit Ketten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Ob ich auch schreie, rufe, er weist mein Beten ab,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'versperrt mit Pfählen meine Wege, verstört mir meine Pfade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Er ist mir wie ein Bär, der lauert, ein Löwe in dem Hinterhalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Er kreist um meine Wege, umschließt mich, macht mich einsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'dann spannt er seinen Bogen und stellt als Ziel mich auf für seine Pfeile.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Er schießt mir in die Nieren des Köchers Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Ich wurde meinem ganzen Volke zum Gespött, ihr Spottlied für den ganzen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Mit Bitternissen machte er mich satt, berauschte mich mit Wermut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'zermalmen ließ er meine Zähne Kiesel und wälzte mich im Staube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Des Glücks beraubt ward meine Seele, daß ich des Heiles ganz vergaß');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'und sprach: \"Dahin ist meine Lebenskraft und meine Hoffnung auf den Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Ja, der Gedanke an mein Elend, meine Irrsale, ist Wermut mir und Gift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Und doch denkt meine Seele dran und sinnt in mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Und ich bedachte dies und schöpfte daraus meine Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Des Herren Huld ist nicht zu Ende und sein Erbarmen nicht erschöpft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Neu ist\'s an jedem Morgen; ja: \"Groß ist Deine Treue;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'mein Anteil ist der Herr\", spricht meine Seele; \"drum hoffe ich auf ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Der Herr ist denen gütig, die seiner harren, und einer Seele, die ihn sucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Drum ist es gut, schweigend des Herren Hilfe zu erwarten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Gar heilsam ist es für den Mann, das Joch in seiner Jugend schon zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Er sitze einsam da und schweige, weil er\'s ihm auferlegt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Mit seinem Mund berühre er den Staub! Vielleicht gibt\'s dann noch Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Er biete seine Wange jenem dar, der nach ihm schlägt, und lasse sich mit Schmach ersättigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Denn nicht auf ewig will der Herr verstoßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Und fügt er auch Betrübnis zu, erbarmt er sich auch wieder seiner Gnadenfülle nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Denn nicht aus Lust erniedrigt er und beugt die Menschenkinder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'damit man mit den Füßen all die Gefangenen des Landes trete,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'daß man das Recht der Leute beuge, das sie beim Allerhöchsten haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Daß jemandem sein Recht genommen wird, das kann der Herr nicht billigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Wer ist\'s, der sprach, und es geschah, und nicht befohlen hätte es der Herr?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Ja, kommt nicht aus des Höchsten Mund das Schlimme wie das Gute?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Was klagt ein Mensch im Leben, ein Mann ob seiner Sündenstrafe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Laßt uns doch unsern Wandel prüfen und erforschen und uns zum Herrn bekehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Laßt uns die Herzen lieber als die Hände zu Gott im Himmel heben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, '\"Gesündigt haben wir in Widerspenstigkeit; Du hast uns nicht vergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Du hast mit Zorn uns ganz bedeckt, verfolgt, gemordet mitleidlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Du hast Dich in Gewölk gehüllt, daß kein Gebet hindurch mehr dringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Zu Kehricht und zum Auswurf hast Du uns gemacht inmitten jener Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Weit rissen über uns den Mund all unsre Feinde auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Zu Angst und Furcht ward uns Verwüstung und Verderben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Mein Auge weinte Wasserströme ob der Vernichtung, die getroffen meines Volkes Tochter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Und ohne Ruhe fließt mein Auge und ohne Rasten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'bis daß herniederschaue und es sehe der Herr vom Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mein Auge klagt ohn Ende ob all den Töchtern meiner Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Mich jagten hin und her wie einen Vogel, die mir so grundlos Feinde waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Mein Leben wollten sie vernichten in der Grube; mit Steinen warfen sie auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Dann strömte übers Haupt mir Wasser; ich sprach: \"Ich bin verloren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Da rief ich Deinen Namen, Herr, aus tiefster Grube an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Du hörtest meine Stimme: \"Ach, verschließe meinem Rufen und meinem Seufzen nicht Dein Ohr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Du nahtest, als ich Dich gerufen; Du sprachst: \"Sei nur getrost!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Du führtest meine Sache, Herr; Du wahrtest mir das Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Nun siehst Du, Herr: Bedrückt bin ich. Verhilf zu meinem Rechte mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'All ihre Rachgier schauest Du, all ihre Pläne gegen mich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Du hörst ihr Schmähen, Herr, und all ihr Planen gegen mich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'die Reden meiner Widersacher, ihr stetes Trachten gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Ihr Sitzen und ihr Aufstehn schau Dir an! Zum Spottlied bin ich ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Du lohnest ihnen, Herr, nach ihrer Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Verblendung gibst Du ihrem Herzen, gibst ihnen Deinen Fluch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Im Zorn verfolgst Du sie und tilgst sie unterm Himmel, Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Wie unbeachtet ist das Gold und feines Gold mißachtet! Wie werden Steine aus dem Heiligtum an alle Straßenecken hingeworfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Wie werden, ach, die teuren Sionskinder, bisher mit Feingold aufgewogen, jetzt irdnen Töpfen gleich geachtet, dem Werk von Töpferhänden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Schakale selbst entblößen ihre Brust und säugen ihre Jungen. Grausam ward meines Volkes Tochter, tut wie die Straußenhenne in der Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Des Säuglings Zunge klebt vor Durst an seinem Gaumen. Die Kinder flehn um Brot; doch niemand bricht es ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Die einstens Leckerbissen aßen, verschmachten auf den Gassen, die man auf Purpur trug, umklammern Düngerhaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'So ist die Schuld der Tochter meines Volkes größer als Sodoms Missetat, das wie im Nu verwüstet ward, an das sich keine Hände legten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Und reiner waren ihre Nasiräer als der Schnee, und weißer als die Milch; ihr Mund war rötlicher als die Korallen und ihr Geäder wie Saphir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Da ward ihr Aussehn schwärzer als der Ruß; unkenntlich sind sie auf den Straßen; an ihren Knochen klebt die Haut; wie Holz so trocken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Weit besser waren die vom Schwert getroffenen daran, als die vom Hungertod gemarterten. Denn diese schwanden hin, im Stich gelassen von des Feldes Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Weichherzige Frauen kochten mit eigenen Händen ihre Kinder; sie wurden ihre Speise beim Untergang der Tochter meines Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Der Herr hat seinen Grimm erschöpft und ausgegossen seine Zornesglut. In Sion hat ein Feuer er entzündet, das seine Grundfesten verzehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Die Könige auf Erden hätten\'s nicht geglaubt, kein Weltbewohner, daß je Belagerer und Feinde die Tore von Jerusalem beträten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Doch wegen der Vergehen ihrer Seher, der Missetaten ihrer Priester, die darin gerechtes Blut vergossen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'ziehn diese auf den Gassen blind umher, mit Blut besudelt. Sie können sich in ihren Kleidern nicht mehr regen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '\"Weicht aus, ein Unreiner!\" so rufen sie von sich. \"Weicht aus! Weicht aus! Kommt nicht zu nahe!\" Und fliehen sie und wanken sie, dann sagt man bei den Heidenvölkern: \"Sie dürfen nirgendwo sich aufhalten\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Das Antlitz derer, deren Teil der Herr, er sieht es nicht mehr an. Auf Priester nimmt man keine Rücksicht mehr, erbarmt sich nicht der alten Leute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Stets schauen unsere Augen voller Sehnsucht aus nach unserer Hilfe. Vergeblich unser Ausblicken! Wir hofften auf ein Volk, das nimmer hilft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Sie lauerten auf unsere Schritte; wir konnten unsere Plätze nicht betreten. Der Untergang naht sich für uns, undunsere Tage laufen ab,das Ende kommt für uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Viel schneller waren unsere Verfolger, als es des Himmels Adler sind. Sie setzten uns noch in die Berge nach und lauerten uns in der Wüste auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Da wurde unser Lebensodem, des Herrn Gesalbter, in ihren Gruben eingefangen. Von diesem dachten wir: \"In seinem Schatten leben wir unter den Völkern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Freu dich, sei fröhlich, Edomstochter, die du das Land von Us bewohnst! An dich kommt auch der Kelch, und trunken wirst du dich entblößen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Getilgt wird deine Schuld, du Sionstochter. Er wird dich nimmermehr verbannen. Doch deine Schuld, du Edomstochter, sucht er heim; und deine Sünden deckt er auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Gedenke, Herr, was uns geschehen! Blick her! Sieh unsere Schmach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Fremden ist unser Erbteil zugefallen und unsere Häuser Ausländern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Wir wurden wie die Waisen vaterlos und unsere Mütter wie die Witwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Wir trinken unser eigen Wasser nur um Geld, bekommen unser eigen Holz nur um Bezahlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Auf unsern Nacken lastet ein gewaltig Joch, und sind wir matt, gönnt man uns keine Ruhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Ägypten reichten wir die Hand, um satt zu werden, Assur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Gesündigt haben unsere Väter; doch sie sind nicht mehr. Wir tragen ihr Verschulden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Jetzt herrschen Sklaven über uns, und ihrer Hand entreißt uns keiner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Wir holen in der Wüste unser Brot mit Einsatz unsres Lebens vor dem Schwerte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Uns sind gedünstet wie im Ofen die Glieder von den Hungersgluten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'In Sion haben sie die Ehefraun geschändet und Jungfrauen in Judas Städten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Gehenkt durch ihre Hand die Fürsten, der Greise Ansehen für nichts geachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Die jungen Männer schleppten Lasten, und Knaben wankten unter Holzbündeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Verschwunden sind die Greise aus dem Tore und Jünglinge aus ihrer Schule.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Geschwunden ist die Freude unsres Herzens, in Klage unser Reigen umgewandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Die Krone ist vom Haupte uns gefallen. Weh uns, daß wir gesündigt haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Deshalb ward unser Herz so krank, deshalb so trübe unser Auge');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'des wüsten Sionsberges wegen, auf dem sich Füchse tummeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Du bist, o Herr, in Ewigkeit; Dein Thron steht von Geschlechte zu Geschlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Warum willst Du uns immerdar vergessen, uns lebenslang verlassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Bekehr uns, Herr, zu Dir! Wir kehren um. Erneure unsere Tage wie vor alters!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Denn wolltest Du uns ganz verwerfen, dann gingest Du in Deinem Zorne gegen uns zu weit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Am fünften Tag des vierten Monds im Jahre dreißig, als ich am Kebarfluß bei den Gefangenen war, hat sich der Himmel aufgetan: Ich schaute göttliche Gesichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Am fünften Tag des Monats - es war das fünfte Jahr seit König Jojachins Verbannung -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'erging das Wort des Herrn tatsächlich an Ezechiel, des Buzi Sohn, den Priester, im Lande der Chaldäer, an dem Kebarfluß. Dort kam die Hand des Herrn auf mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Ich schaute: Ein Sturmwind kam von Norden her und eine große Wolke und ein Feuerwirbel, um diesen ringsherum ein Glanz und mitten drin wie Silbergold, ja, mitten in dem Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Und mitten drinnen sah man so etwas wie vier lebendige Gestalten; ihr Aussehn hatte Ähnlichkeit mit Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Ein jedes hatte vier Gesichter, vier Flügel jedes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Und ihre Füße standen senkrecht da; gerundet waren ihre Fußsohlen und funkelten wie glänzend Erz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Sie hatten Menschenhände unter ihren Flügeln an den vier Seiten; vier Flügel hatten sie wie vier Gesichter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Die Flügel stießen aneinander; sie selber aber drehten sich nicht um bei ihrem Fortbewegen; ein jedes ging gerade vor sich hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Ihr Antlitz sah dem Menschenantlitz ähnlich, zur Rechten dieser viere dem des Löwen, zur Linken dieser viere dem des Stiers und dem des Adlers. Das war das Antlitz dieser vier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Darüber waren ihre Flügel ausgebreitet; zwei Paare hatte jedes; das eine Paar stieß an das andere, und dies bedeckte ihre Körper.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Ein jedes ging gerade vor sich hin. Wohin zu gehn der Geist sie trieb, da gingen sie auch hin. Sie drehten sich nicht um im Gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Und diese Lebewesen sahen aus wie Feuerkohlen, die wie Fackeln flammten. Das Feuer flammte zwischen diesen Wesen hin und her; es hatte aber einen hellen Glanz, und aus dem Feuer fuhren Blitze aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Und diese Wesen liefen hin und her wie Wetterleuchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Da sah ich mir die Wesen näher an, und je ein Rad ging auf der Erde neben diesen Wesen, entsprechend ihren vier Gesichtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Die Räder und was sonst daran, glich einem Chrysolith. Sie waren alle vier einander ähnlich und so geformt, als ob ein Rad im andern wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Auf jeder der vier Seiten gingen sie, wenn sie sich fortbewegten; beim Gehen drehten sie sich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Doch ihre Felgen konnten sich erheben, und Rührigkeit war ihnen eigen. Auch Sehkraft hatten sie; voll Augen waren nämlich ihre Pflöcke ringsumher bei diesen vieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Und wenn die Wesen sich bewegten, so gingen auch die Räder neben ihnen mit, und wenn die Wesen von der Erde sich erhoben, erhoben sich zugleich die Räder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Wohin zu gehn der Geist sie trieb, da gingen sie auch hin. Die Räder hoben sich mit ihnen in die Höhe; auch in den Rädern war der Geist der Wesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Wenn jene gingen, gingen diese auch, und standen jene still, so standen sie auch still. Erhoben jene sich vom Boden, erhoben sich mit ihnen auch die Räder; auch in den Rädern war der Geist des Lebens,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'und oberhalb der Häupter dieser Wesen war etwas gleich einem Himmel, an Aussehn wie von wunderbarem Eiskristall; ganz weit war\'s über ihren Häuptern oben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Und unter diesem Himmel waren ihre Flügel grade ausgebreitet, der eine an den andern rührend, und jeder hatte noch zwei Flügel, mit denen sie von beiden Seiten ihren Leib bedeckten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Und ihrer Flügel Rauschen, das ich hörte,war gleich dem Rauschen vieler Wasser und gleich des Hochgebirges Dröhnen, wenn sie sich fortbewegten, und gleich dem Tosen eines Wolkenbruchs, wie Kriegsgetümmel. Doch wenn sie stillestanden, senkten sie die Flügel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Wenn sich dann eine Stimme hören ließ von oberhalb des Himmels über ihren Häuptern, verhielten sie, die Flügel senkend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Denn oberhalb des Himmels über ihren Häuptern war etwas wie ein Saphirthron, und auf dem Throngebilde saß ein menschenähnlich Wesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Wie Silbergold erschien es mir, als ob es innen ringsum Feuer wäre, beim Anblick seines Oberkörpers. Beim Anblick seines Unterleibes aber sah ich ein Feuer ringsum Glanz verbreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'So wie der Wolke Bogen, wenn es regnet, so war der Glanz beschaffen ringsherum, ein Anblick gleich der Herrlichkeit des Herrn. Ich sah\'s; dann fiel ich auf mein Antlitz nieder und hörte eine Stimme sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Sie sprach zu mir: \"Du Menschensohn! Stell dich auf deine Füße, damit ich mit dir reden kann!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Da kam ein Geist in mich, als er zu mir so redete, und er verhalf mir auf die Füße. Nun hörte ich ihn an, der mit mir sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Er sprach zu mir: \"Du Menschensohn! Ich send dich zu den Söhnen Israels, zu einem Volke von Rebellen, die von mir abgefallen sind. Sie, wie schon ihre Väter, haben bis auf diesen Tag den Abfall von mir fortgesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Die Söhne aber sind noch frecher und verstockter. Zu diesen sende ich dich hin; du sollst zu ihnen sagen: \'So spricht der Herr, der Herr\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'sie mögen\'s hören oder auch es lassen - sie sind ja doch ein Haus der Widerspenstigkeit -, sie sollen aber wissen, daß unter ihnen ein Prophet verweilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Du aber, Menschensohn, sei ohne Furcht vor ihnen und ohne Furcht vor ihren Drohungen, obwohl sie Nesseln für dich sind und Dornen und du bei Skorpionen wohnen mußt! Vor ihren Drohungen sei ohne Furcht; vor ihren Blicken zittre nicht, auch wenn sie schon ein Haus der Widerspenstigkeit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Trag ihnen meine Worte vor, sie mögen hören oder nicht! Sie sind der Ungehorsam selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Du also, Menschensohn, befolge das, was ich dir sage! Sei doch nicht widerspenstig wie das Haus der Widerspenstigkeit! Tu deinen Mund auf und verzehre, was ich dir jetzt gebe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Danach sah ich mich um, und eine Hand war zu mir hingestreckt, und sieh, darin lag eine Buchrolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Er breitete sie vor mir aus, und sie war in- und auswendig beschrieben, mit der Aufschrift: \"Klagrufe, Seufzer, Weheklagen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Er sprach zu mir: \"Du Menschensohn! Iß, was du findest! Verzehre diese Rolle! Geh hin und sprich zu Israel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Ich öffnete den Mund; dann gab er diese Rolle mir zu essen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'und sprach zu mir: \"Du Menschensohn! Gib deinem Magen diese Rolle zum Verzehren, die ich dir hiermit gebe, und fülle deinen Leib damit!\" Da aß ich sie. Sie ward in meinem Munde honigsüß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Er sprach zu mir: \"Du Menschensohn! Zum Hause Israel geh hin und sprich zu ihm mit meinen Worten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Du wirst ja nicht gesandt zu einem Volk von unbekannter Sprache, von schwerer Zunge, nein, zum Hause Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Doch wenn ich dich zu vielen Völkern unbekannter Sprachen und schwerer Zungen schickte, zu solchen, deren Worte für dich unverständlich, ja, wenn ich dich zu solchen schickte, sie würden auf dich hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Das Haus von Israel jedoch hört nicht auf dich. Es hört ja nicht einmal auf mich, ist doch das ganze Israel von harter Stirn und starrem Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Doch sieh, ich mache hart dein Angesicht, gleich ihrem Angesicht, gleich ihrer Stirne deine Stirn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Wie Diamant, noch härter als ein Felsen, mach ich deine Stirn. Du sollst dich nicht vor ihnen fürchten und nicht vor ihnen zittern, obgleich ein Haus der Widerspenstigkeit sie sind!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Er sprach zu mir: \"Du Menschensohn! Präg meine Worte, die ich zu dir rede, dir ein, ja, präg sie deinem Herzen ein, horch auf mit deinen Ohren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Nun geh zu den Gefangenen, zu deines Volkes Söhnen! Sag ihnen! Sprich zu ihnen: \'Also spricht der Herr: Sie mögen hören und erbeben!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Ein Geist hob mich empor, und hinter mir vernahm ich eine mächtig starke Stimme: \"Gepriesen sei die Majestät des Herrn!\", von seinem Orte her,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'und dann ein Rauschen, das von der Wesen Flügel kam, die aneinander rührten, und dann ein Rasseln von den Rädern nebenan, ein mächtiges Getöse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'So hob mich denn ein Geist empor und riß mich fort. Da schritt ich, bitterer Gefühle voll, dahin, in meinem Innern ganz erregt; schwer lastete die Hand des Herrn auf mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Nach Tell Abib kam ich zu den Gefangenen, die an dem Kebarflusse saßen, und wo sie wohnten, verblieb ich unter ihnen sieben Tage, starr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Nach dem Verlauf von sieben Tagen erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '\"Dich, Menschensohn, bestell ich für das Haus von Israel zum Wächter. Aus meinem Mund vernimm das Wort, mit dem du sie von mir verwarnen sollst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Wenn ich vom Frevler sage: \'Du mußt sterben!\', und du verwarnst ihn nicht und sagst auch nichts, um einen Frevler vor dem schlimmen Weg zu warnen, daß er am Leben bleibe, dann stirbt der Frevler zwar für seine Missetat; von deiner Hand jedoch verlange ich sein Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Verwarnst du aber einen Frevler und läßt er nicht von seinem Frevel und nicht von seinem schlimmen Wege, so muß er selbst für seine Sünde sterben. Du aber hast dich selbst gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Und wendet sich der Fromme weg von seiner Frömmigkeit, und tut er Unrechtes, dann laß ich\'s ihm zum Fall gereichen, daß er stirbt. Hast du ihn nicht verwarnt, so muß er zwar ob seiner Sünde selber sterben, und der Verdienste, die er sich erworben, wird nicht mehr gedacht. Von deiner Hand jedoch verlange ich sein Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Verwarnst du aber einen Frommen in rechter Weise, ohne selbst dich zu verfehlen, und sündigt dieser wirklich nicht mehr, so wird er leben bleiben. Er hat sich warnen lassen, und du hast dich gerettet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Dort kam die Hand des Herrn auf mich; er sprach zu mir: \"Steh auf, geh in das Tal hinaus! Dort will ich mit dir sprechen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Da stand ich auf und ging ins Tal hinaus. Da stand die Herrlichkeit des Herrn, gleich der, die ich am Kebarfluß geschaut. Da fiel ich auf mein Antlitz nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Dann aber kam ein Geist in mich; der stellte mich auf meine Füße; er redete mich an und sprach zu mir: \"Sperr dich in deine Wohnung ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Nun, Menschensohn! Schau hin! Sie werden Stricke um dich legen und dich mit ihnen fesseln, daß du nicht unter sie hinausgehn kannst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Dann laß ich deine Zunge dir am Gaumen kleben, daß du verstummst und ihnen nicht zu einem Manne werdest, der Strafe predigt; sie sind ein Haus der Widerspenstigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Sobald ich aber zu dir rede, will ich den Mund dir öffnen, daß du zu ihnen sagst: \'So spricht der Herr, der Herr.\' Wer hören will, der höre; wer nicht, der laß es sein; sie sind ein Haus der Widerspenstigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '\"Du Menschensohn! Nimm dir jetzt einen Ziegelstein, leg diesen vor dich hin und zeichne drauf die Stadt Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Mach einen Wall um sie! Bau einen Turm dawider! Schütt einen Damm dagegen, stell Heere auf dawider! Laß ringsum Sturmböcke angreifen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Dann hol dir eine Eisenpfanne und stell als Eisenwand sie zwischen dich und diese Stadt und richte unverwandt dein Antlitz gegen sie, als wäre sie jetzt in Belagerung und du wärst ihr Belagerer! Ein Zeichen sei dies für das Haus von Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Dann aber leg dich auf die linke Seite! Trag so die Sündenschuld des Hauses Israel! So viele Tage, wie du darauf liegst, hast du an ihrer Missetat zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ich will dir nämlich auferlegen ihrer Sünden Jahre, in Tage umgewandelt, dreihundertneunzig Tage. So lang trag du die Sündenschuld des Hauses Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Bist du damit zu Ende, dann leg zum zweitenmal dich auf die rechte Seite, und trag die Schuld des Hauses Juda vierzig Tage! Ich setze einen Tag für jedes Jahr dir an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Dein Antlitz richte unverwandt auf die Belagerung Jerusalems! Es sei dein Arm entblößt! Weissage so dawider!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Ich binde dich mit Stricken, damit du dich nicht umwendest, bis du die Tage überstanden, da du belagert bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Alsdann nimm Weizen, Gerste, Bohnen, Linsen, Hirse, Spelt, tu sie in ein Gefäß zusammen und mach dir Brot daraus! Die ganze Zeit, die du auf deiner Seite liegst, dreihundertneunzig Tage, sollst du\'s essen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Die Speise, die du essen sollst, beträgt nach dem Gewicht nur zwanzig Ringe für den Tag. Du sollst von einer Stunde bis zur gleichen des andern Tags sie essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Auch Wasser sollst du abgemessen trinken, ein Sechstel Maß. Du sollst von einer Stunde bis zur gleichen des andern Tags es trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Als Gerstenkuchen sollst du es verzehren. Den aber backe du vor ihren Augen auf Ballen Menschenkotes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Es sprach der Herr: \"Genauso essen ekelhaftes Brot die Söhne Israels bei Heidenvölkern, unter die ich sie zerstreue.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Ich aber sprach: \"Ach Herr, o Herr! Ich habe niemals mich verunreinigt und nie Gefallenes gegessen, und nie Zerrissenes, niemals von meiner Jugend an bis jetzt. Nie kam in meinen Mund verdorbenes Fleisch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Er sprach zu mir: \"Statt Menschenkots bewillige ich dir Rindermist; mit solchem magst du dir dein Brot bereiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Er sprach zu mir:\"Du Menschensohn! Sieh! Ich lasse in Jerusalem an Brot es nicht ermangeln, daß man\'s nur nach Gewicht verzehrt und unter Angst und Wasser trinkt nach zugemessenem Maß mit Schrecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'An Brot und Wasser Mangel leidend, werden sie, einander starr anblickend, zur Strafe ihrer Missetat verschmachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '\"Du Menschensohn! Nimm dir ein scharfes Schwert! Gebrauch\'s als Schermesser! Und führ es über Kopf und Bart! Dann nimm dir eine Waage zum Verteilen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ein Drittel sollst du mitten in der Stadt verbrennen, wenn verflossen der Belagerung Tage. Das andere Drittel schneide mit dem Schwert in deiner Nachbarschaft ganz klein. Das letzte Drittel streue in den Wind! Doch halte ich auch hinter diesem noch das Schwert gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Doch nimm zuvor davon ein wenig und bind\'s in deinen Bausch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Von diesem nimm noch etwas und wirf\'s ins Feuer! Verbrenn es drin! Daraus entzündet sich ein anderes Feuer fürs ganze Haus von Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'So spricht der Herr, der Herr: \"So ist es mit Jerusalem: Ich hab\' es in der Heidenvölker Mitte hingestellt und in die Nachbarschaft von Ländern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Weit ungehorsamer als je ein Heidenvolk betrug sich\'s gegen meine Vorschriften, und schlimmer gegen meine Satzungen als je die Länder seiner Nachbarschaft. So hat es meine Vorschriften verachtet und dem nicht nachgelebt, was ich geboten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Deshalb spricht so der Herr, der Herr: \"Ihr habt ob eures Überflusses, der den der Heidenvölker um euch übertraf, dem nimmer nachgelebt, was ich geboten, und nimmer meine Vorschriften befolgt. Nein! Nach der Art der Heidenvölker rings um euch habt ihr getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Darum spricht so der Herr, der Herr: \"Fürwahr, so will ich auch an dich. In deiner Mitte halte ich Gericht vor dieser Heidenvölker Augen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'und ich verhänge über dich, was ich noch nie verhängt, desgleichen ich auch künftig nicht verhängen werde, um aller deiner Greueltaten willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Drum sollen Väter ihre Kinder und Kinder ihre Väter bei dir fressen. Ich tu genau nach Recht an dir und streue deinen ganzen Rest in alle Winde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Deshalb, so wahr ich lebe\", ein Spruch des Herrn, \"weil du mein Heiligtum entweiht durch alle deine Greuelgötzen und alle deine Schandgottheiten, hau ich erbarmungslos darein und ohne Schonung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Dein dritter Teil stirbt an der Pest und wird durch Hunger in dir aufgerieben. Das andere Drittel fällt durchs Schwert in deiner Nähe; das letzte Drittel streue ich in alle Winde und halte hinter ihm das Schwert gezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Mein ganzer Grimm entlädt sich so; ich kühle meinen Zorn an ihnen und nehme Rache. Dann werden sie erkennen, daß ich, der Herr, es bin, der da im Eifer seines Zornes droht, wenn ich an ihnen meinen Grimm abkühle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Ich mache dich zur Wüstenei, zum Spott der Heidenvölker rings um dich und in den Augen eines jeden, der dich betrachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Der Schande fällst du und dem Schimpf anheim, zur Warnung und zum Staunen bei den Heidenvölkern rings um dich, wenn ich in Zorn und Grimm, in Züchtigungen unter Zürnen an dir das Strafgericht vollziehe. Ich, ich, der Herr, ich habe dies gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Wenn ich des Hungers Pfeile, die verderblichen, auf die abschieße, die zum Verderben sind bestimmt, dann mehre ich zum Schaden noch den Hunger, zerbreche jede Brotesstütze euch, wenn ich zu eurem Untergang sie abgeschossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ich sende Hungersnot und wilde Tiere gegen euch, dich kinderlos zu machen. Und Pest und Blutvergießen überfallen dich. Ich bringe über dich das Schwert. Ich, ich, der Herr, ich habe es gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '\"Du Menschensohn! Dein Antlitz wende zu den Bergen Israels und prophezeie aber sie');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'und sprich: \'Ihr Berge Israels, vernehmt das Wort des Herrn, des Herrn! So spricht der Herr, der Herr, zu diesen Bergen, diesen Hügeln, zu diesen Gründen, diesen Tälern. Ich bringe über euch das Schwert, zerstöre eure Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Zertrümmert werden euere Altäre, zerbrochen eure Rauchaltäre; und euere Erschlagenen werf ich vor eure Götzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Die Leichname der Söhne Israels leg ich vor ihre Götzen hin, zerstreue euere Gebeine rings um euere Altäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Soweit sich alle eure Wohnsitze erstrecken, soll\'n menschenleer die Städte werden, zerstört die Höhen. Sind dann zertrümmert und verwüstet eure Altäre und eure Götzen ganz zerschlagen und verschwunden und eure Rauchaltäre umgehauen und eure Machwerke vertilgt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'und wenn bei euch Erschlagne liegen bleiben, dann seht ihr ein: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Doch lasse ich von euch noch einige, dem Schwert Entronnene, bei jenen Heidenvölkern übrig, wenn ihr zerstreut seid in die Länder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Und diese euere Entkommenen gedenken meiner bei den Heiden, zu denen sie gefangen abgeführt, wenn ich zu Boden beuge ihren buhlerischen Sinn, der von mir abgefallen, und ihre buhlerischen, ihren Götzenbildern zugeworf\'nen Blicke. Sie werden vor sich selber Abscheu haben ob der vertüten Frevel, ob aller ihrer Greueltaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Dann sehn sie ein: Ich bin der Herr. Nicht leere Worte waren es, wenn ich gedroht, dies Unheil ihnen anzutun.\'\" So spricht der Herr, der Herr:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, '\"Schlag in die Hand! Stampf mit dem Fuße auf und sprich: \'Weh über all die argen Greueltaten in dem Hause Israels! Sie sollen dafür fallen durch das Schwert, durch Hunger und durch Pest!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Wer fern, stirbt an der Pest; wer nahe, fällt durchs Schwert. Wer noch verschont, der stirbt des Hungers. Ich laß an ihnen meinen Ingrimm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Dann seht ihr ein. Ich bin der Herr, wenn die Erschlagenen bei ihren Götzen rings um die Altäre liegen auf jedem hohen Hügel, jedem Bergesgipfel und unter jedem grünen Baum und unter jeder dichtbelaubten Terebinthe, an jedem Ort, wo süßen Opferduft sie allen ihren Göttern spenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Ich strecke meine Hand aus gegen sie und mache noch verödeter das Land und wüster als Diblas Steppenland, soweit sie wohnen, damit sie wissen: Ich, ich bin der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Das Wort des Herrn erging an mich, also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '\"Du Menschensohn! So spricht der Herr, der Herr vom Lande Israel: Ein Ende kommt, das Ende für alle die vier Himmelsgegenden des Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nun kommt das Ende über dich. Ich lasse wider dich dem Zorne freien Lauf und richte dich nach deinem Wandel und bringe über dich all deine Greueltaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mein Auge blickt nicht mitleidsvoll auf dich. Ich übe keine Schonung mehr; ich lohne deinen Wandel dir, solange deine Greueltaten noch in dir geschehen, daß ihr erkennt: Ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So spricht der Herr, der Herr: \"Ein Ungemach kommt nach dem andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Ein Ende kommt. Das Ende kommt. Schon ist es auf dem Weg zu dir. Fürwahr, es kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Verhängnis über dich, Einwohnerschaft des Landes! Die Zeit erscheint; der Tag ist nah. Verwirrung, nur kein Jubelruf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nun gieße ich in Bälde meinen Ingrimm über dich, erschöpfe meinen Zorn an dir und richte dich nach deinem Wandel und bringe über dich all deine Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mein Auge blickt nicht mitleidsvoll. Ich übe keine Schonung mehr; ich lohne deinen Wandel dir, solange deine Greuel noch in dir geschehn, daß ihr erkennt: Ich selbst, der Herr, ich bin\'s, der Schläge führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Fürwahr, der Tag! Seht her! Er kommt. Verhängnis geht nun aus. Und das Geschwür blüht auf, und die Geschwulst nimmt zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Gar Schweres droht dem schlimmen Stamm. Nicht um sich selbst und ihre Volksmenge und ihre Kinder trauern sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Die Zeit ist da. Der Tag ist nah, da selbst der Käufer sich nicht freut und trauert der Verkäufer. Ein Zorn trifft ihre ganze Masse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Denn kein Verkäufer kommt je wieder in Besitz seines verkauften Gutes, falls er noch am Leben bliebe. Denn das Gesicht wird nicht zurückgenommen; es geht auf ihre ganze Masse, und niemand, der in Missetat gelebt, kann sich für sicher halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Und stieße man in die Posaune, und hätte alles sich gerüstet, es zöge dennoch niemand in den Kampf; es trifft mein Zorn ja ihre ganze Masse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Im freien Feld das Schwert und drinnen Pest und Hunger! Wer auf dem Feld, der stirbt durchs Schwert, wer in der Stadt, den tilgen Hungersnot und Pest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Entrinnen auch ein paar von ihnen, und kommen sie noch in die Berge, so seufzen sie wie Turteltauben, ein jeder über seine Missetat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Schlaff sinken alle Hände nieder; die Knie aller werden naß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Sie legen Trauerkleider an und hüllen sich in Angst. Auf jedem Angesicht Enttäuschung, auf allen Köpfen Glatzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ihr Silber werfen sie hin auf die Gassen; ihr Gold erachten sie als Kot. Ihr Silber und ihr Gold kann sie am Tag der Wut des Herrn nicht retten. Sie können sich davon nicht sättigen und ihren Bauch nicht füllen, war\'s doch ein Reiz zu ihrer Missetat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Aus ihrem Schmuck, dem herrlichen, den sie zu ihrem Ruhm sich hätten machen sollen, verfertigten sie Greuelbilder, ihre Scheusale. Deswegen mache ich\'s für sie zum Unflat');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'und geb als Beute es den Fremden in die Hände, zum Raub den Wildesten der Erde, daß sie\'s entweihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Ich wende ab mein Angesicht von ihnen; denn sie entweihten ja mein tief Geheimnis; nun dringen Räuber ein, entweihen es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Nun schmiede Ketten! Das Land ist voll von Bluturteilen, die Stadt von Grausamkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Der Heidenvölker schlimmste laß ich kommen; sie sollen ihre Häuser einnehmen. Dem Übermut der Trotzigen bereite ich ein Ende, und ihre Heiligtümer sollen ihre Heiligkeit verlieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Wenn dann die Schreckenszeit eintrifft, so suchen sie wohl Rettung; doch sie finden keine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Unfall kommt über Unfall, und eine Unglücksbotschaft folgt der anderen. Gesichte wünschen sie sich von Propheten; doch, wie Belehrung Priestern fehlt, so guter Rat den Ältesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Der König ist in Trauer; der Fürst hüllt sich in Schrecken. Des Landvolks Hände sind vor Schrecken lahm. Nach ihrem Wandel lohn ich ihnen und richte sie nach dem, was sie verdient, daß sie erkennen: Ich, ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Am fünften Tag des sechsten Monds im sechsten Jahr saß ich in meinem Haus und Judas Älteste vor mir. Da senkte sich auf mich die Hand des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Ich sah. Da war\'s, wie eine männliche Gestalt. Von dem, was seinen Hüften glich, war\'s abwärts wie ein Feuer. Von seinen Hüften aufwärts war\'s wie Strahlenglanz, wie Glanz von Silbergold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Er streckte etwas aus, wie eine Hand, und faßte mich an meines Hauptes Stirnlocke. Dann trug ein Wind mich zwischen Erd\' und Himmel fort und brachte nach Jerusalem mich hin, in einem göttlichen Gesichte, zum Eingang in des inneren Hofes Tor, das gegen Norden schaut, wo sich das fürchterliche Bild befand, die Viehgestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Da war zu sehn die Herrlichkeit des Gottes Israels gleich dem Gesicht, das ich im Tal geschaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Er sprach zu mir: \"Du Menschensohn! Gen Norden richte deine Augen!\" Da richtete ich meine Augen gegen Norden, und siehe, nördlich von dem Tore zum Altar stand jenes fürchterliche Bild am Eingang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Er sprach zu mir: \"Du Menschensohn! Siehst du, was jene treiben? Gar große Greuel sind\'s, die hier das Haus von Israel verübt, um mich aus meinem Heiligtum zu treiben. Du schaust jedoch noch größere Greuel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Er brachte mich zum Vorhofstore. Da sah ich in der Wand ein Loch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Er sprach zu mir: \"Jetzt, Menschensohn! Zwäng dich durch diese Wand!\" Da zwängte ich mich durch die Wand und schaute eine Tür.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Er sprach zu mir: \"Tritt ein und schau die argen Greuel, die sie an diesem Orte treiben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Ich ging hinein und schaute; da gab es allerlei Gebilde von Gewürm und greuelhaften Tieren, und alle Götzen, die das Haus Israel besaß; sie waren ringsum in die Wand gegraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Vor ihnen standen siebzig Männer aus den Ältesten des Hauses Israel, darunter auch Jazanja, Saphans Sohn. Sein Rauchfaß hatte jeder in der Hand, und Wohlgeruch in Weihrauchwolken stieg empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Er sprach zu mir: \"Du Menschensohn, siehst du, was da die Ältesten des Hauses Israel im Finstern treiben, ein jeder in der Kammer seines Bildes? Sie sagen ja: \'Es sieht der Herr uns nicht.\' \'Es hat der Herr das Land verlassen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Er sprach zu mir: \"Noch ärgere Greuel, die sie treiben, sollst du schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Er brachte mich zum Eingang in das Tor zum Tempel, der gegen Norden liegt. Da saßen Weiber, die um Tammuz weinten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Er sprach zu mir: \"Siehst du dies, Menschensohn? Du sollst noch ärgere Greuel sehn als diese.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Er brachte mich zum Eingang in das Tor zum Tempel. Da waren an dem Eingang zu dem Tempel des Herrn, dort zwischen Halle und Altar, wohl gegen fünfundzwanzig Männer. Ihr Rücken war dem Heiligtum des Herren zugekehrt, ihr Antlitz gegen Osten. So beteten sie dort, nach Osten hin, die Sonne an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Er sprach zu mir: \"Siehst du es, Menschensohn? Ist\'s nicht, als wär\'s dem Judahaus zu wenig, die hier verübten Greuel selbst getan zu haben, daß sie das Land mit Grausamkeit erfüllen? Sie reizten mich schon wiederholt zum Unmut. Jetzt schau, wie sie die Ranke an die Nase halten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Nun will auch ich im Grimm verfahren; mein Auge soll kein Mitleid haben. Ich kenne keine Schonung mehr. Und schrein sie überlaut mir in die Ohren, ich hör sie nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Er rief mir dann mit lauter Stimme in die Ohren: \"Herbei jetzt mit den Henkern für die Stadt! Die Mordwaffe in eines jeden Hand!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Da sah ich von dem obern Tor sechs Männer kommen, von dem, das gegen Norden sieht, und jeder hatte in der Hand die Mordwaffe. Bei ihnen war ein Mann, gehüllt in Linnen, mit Schreibgeräte an den Hüften. So kamen sie herein und stellten sich dem ehernen Altare gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Die Herrlichkeit des Gottes Israels erhob sich von dem Cherub, über dem sie war, begab sich zu des Hauses Schwelle und rief dem Mann im Linnenkleid, der Schreibgeräte an den Hüften trug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Dann sprach der Herr zu ihm: \"Zieh mitten durch die Stadt, ja, mitten durch Jerusalem, mach auf der Männer Stirn ein Zeichen, die seufzend jammern all der Greuel wegen, die darin geschehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Und zu den übrigen sprach er vor meinen Ohren: \"Folgt diesem durch die Stadt! Und schlaget drein! Kein Mitleid habe euer Auge! Gewähret keine Schonung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Die Greise, Jünglinge, Jungfrauen, Kinder, Weiber bringt um und tilgt sie aus! Doch rührt an keinen, der das Zeichen an sich trägt! Mit meinem Heiligtum beginnt!\" Da machten sie den Anfang mit den Ältesten, die vor dem Hause waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Er sprach zu ihnen: \"Dieses Haus macht unrein! Füllt mit Erschlagenen die Höfe an! Dann ziehet weiter!\" Sie zogen fort von da und schlugen in der Stadt darein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Nach ihrem Niedermetzeln blieb ich ganz allein zurück; da fiel ich auf mein Antlitz, schrie und sprach: \"Ach Herr, o Herr! Vernichtest Du den ganzen Rest von Israel? Ergießest Deinen Grimm Du auf Jerusalem?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Er sprach zu mir: \"Die Missetat des Hauses Israel und Juda ist zu groß; das Land ist voll von Blutvergehn, die Stadt voll von Bedrückungen. Sie sagen: \'Es hat der Herr das Land verlassen. Der Herr sieht nichts.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'So soll denn auch mein Auge ohne Mitleid sein; ich übe keine Schonung mehr, und ich vergelte ihnen ihren Wandel auf den Kopf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Und siehe da, der Mann, gehüllt in Linnen, mit dem Schreibgerät an seinen Hüften, erstattete hierauf Bericht und sprach: \"Ich tat, wie Du mir anbefohlen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Ich sah mich um, und auf dem Himmel, der überm Haupt der Cherube, war etwas wie ein Saphirstein zu sehn. Als wär\'s ein Throngebilde, sah es aus, was über ihnen sichtbar ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Und zu dem Mann im Linnenkleide sagte er: \"Tritt zwischen diese Räder unterhalb des Cherubs hin! Und mit den Händen nimm dir glühende Kohlen zwischen diesen Cheruben heraus, und streu sie über diese Stadt!\" Vor meinen Augen ging er hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Als er hineinging, standen rechts vom Haus die Cherube, und von der Wolke war der innere Hof erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Des Herren Herrlichkeit erhob sich aber von dem Cherub, und sie begab sich zu des Hauses Schwelle. Da füllte sich das Haus mit dieser Wolke, und voll vom Glanz der Herrlichkeit des Herrn ward auch der Hof.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Das Rauschen jener Cherubsflügel wurde bis zum äußern Hof vernommen, gleich der Stimme des Allmächtigen, wenn er redet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Da er dem Mann im Linnenkleide so geboten:\"Nimm Feuer zwischen diesen Rädern und zwischen diesen Cheruben heraus\", ging dieser hin und stellte sich dem Rade gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Da streckte zwischen diesen Cheruben ein Cherub die Hand nach jenem Feuer aus, das zwischen jenen Cheruben; er nahm davon und gab es dem ins Linnenkleid Gehüllten in die Hände; der nahm\'s und ging hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Man konnte an den Cheruben so etwas unter ihren Flügeln sehn, was Ähnlichkeit mit einer Menschenhand besaß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Ich sah\'s genauer an und sah vier Räder neben diesen Cheruben; denn neben jedem Cherub war ein Rad; die Räder sahen aus wie Chrysolith.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Und jedes dieser vier sah ganz genau so wie das andere aus, als ob ein Rad im andern wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Bei ihrem Gehen gingen sie nach allen den vier Seiten; beim Gehen drehten sie sich nicht. Denn zu dem Orte gingen sie, wohin sich eines jeden Haupt hinwandte; sie drehten sich beim Gehen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Ihr ganzer Leib, ihr Rücken, ihre Hände, ihre Flügel mitsamt den Rädern waren ringsum voller Augen, bei allen den vier Rädern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Die Räder hießen, wie ich\'s selbst gehört, die \"Drehbaren\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Und vier Gesichter hatte jedes: Das eine Angesicht, das Angesicht des Cherubs, war ein Stiergesicht; das zweite Antlitz war ein Menschenangesicht; ein Löwenantlitz war das dritte; ein Adlerantlitz war das vierte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Erheben konnten sich die Cherube; das war das Wesen, das ich am Kebarfluß geschaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Und wenn die Cherube fortgingen, bewegten sich die Räder neben ihnen auch. Wenn aber diese Cherube die Flügel schwangen, um sich vom Boden zu erheben, dann drehten sich die Räder nicht an ihrer Seite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Wenn jene standen, verhielten diese auch; erhoben jene sich, erhoben diese sich mit jenen; denn auch in ihnen war der Geist der Wesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Da ging des Herren Herrlichkeit fort von des Hauses Schwelle und ließ sich auf die Cherube herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Da schwangen diese Cherube die Flügel und stiegen von dem Boden auf vor meinen Augen. Wie die sich fortbegaben, machten es in gleicher Weise auch die Räder. Am Eingang blieben sie zum Osttor stehen, das zum Haus des Herren führt, und oben über ihnen war die Herrlichkeit des Gottes Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Das war das Wesen, das ich am Kebarfluß geschaut unter dem Gott von Israel; so wußte ich, es seien Cherube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Ein jeder hatte vier Gesichter, vier Flügel jeder, und so etwas wie Menschenhände war unter ihren Flügeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Und ihre Angesichter sahen aus wie jene, die ich am Kebarfluß geschaut. Sie sahen ihnen gleich und waren es; ein jedes ging gerade vor sich hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Da führte mich ein Geist hinweg und brachte mich am Haus des Herrn zum vordern Tor, das gegen Morgen schaut, und an des Tores Eingang standen fünfundzwanzig Männer, und unter ihnen sah ich den Jazanja, Uzars Sohn, und den Pelatja, des Benaja Sohn, die Obersten des Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Er sprach zu mir. \"Sieh, Menschensohn! Das sind die Männer, die solch Unheil sinnen und schlimmen Rat in dieser Stadt abhalten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'die sprechen: \'Heißt es jetzt nicht, Häuser zu erstellen?\' \'Sie ist der Topf\'. \'Wir sind das Fleisch\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Weissage darum gegen sie! Ja weissage, du Menschensohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Da senkte sich auf mich der Geist des Herrn; er sprach zu mir: \"Verkünde! Es spricht der Herr: \'Ihr habt doch so gesprochen, du Haus Israel. Was euch in eurem Geiste aufsteigt, weiß ich wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'In dieser Stadt sind\'s eurer Opfer viel; mit solchen Opfern füllt ihr ihre Straßen an.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Deshalb spricht so der Herr, der Herr: \'Ja eure Todesopfer, die ihr in ihrer Mitte habt vollbracht, die sind das Fleisch. Sie ist der Topf. Euch aber schleppe ich hinweg von ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vorm Schwerte habt ihr Angst; ich bringe über euch das Schwert.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, '\'Ich führe euch aus ihr hinweg und geb euch in die Hand von Fremden, und ich vollstrecke so an euch die Strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Ihr fallet durch das Schwert; so richte ich euch an der Grenze Israels, daß ihr erkennt: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Sie soll euch nicht zum Topfe dienen, ihr werdet darin nicht das Fleisch mehr sein. Ich richt euch an der Grenze Israels,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'daß ihr erkennt, daß ich der Herr bin, nach dessen Satzungen ihr nicht gewandelt und dessen Vorschriften ihr nicht erfüllt. Nein, nach der Heiden Sitten rings um euch, danach habt ihr gehandelt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Als ich so weissagte, geschah\'s, daß den Pelaja, des Benaja Sohn, der Tod ereilte. Da fiel ich auf mein Angesicht und rief mit lauter Stimme: \"Ach Herr, ach Herr! Willst Du denn jetzt den Rest von Israel vertilgen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '\"Hör, Menschensohn! Zu deinen Brüdern, zu deinen Brüdern, deinen Blutsverwandten, zum ganzen Haus von Israel, zu denen die Bewohner von Jerusalem nun sagen: \'Laßt doch den Herrn! Uns ist das Land zum Eigentum gegeben\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'sprich deshalb: \'Also spricht der Herr, der Herr: Zwar habe ich sie zu den Heiden abgeführt; zwar habe ich sie in die Länder hin zerstreut. Doch dien ich ihnen auch für diese kurze Zeit zur Schutzwehr in den Ländern, die sie jetzt betreten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Sprich deshalb: \'Also spricht der Herr, der Herr: Ich will euch aus den Völkern sammeln und aus den Ländern euch zusammenbringen, worin ihr seid zerstreut. Ich gebe euch das Land Israel wieder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Und kommen sie dahin, so werden sie daraus all seine Scheusale und seine Greuel all entfernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Ich gebe ihnen ja ein anderes Herz und gebe in ihr Inneres einen neuen Geist. Ich nehme weg ein steinern Herz aus ihrem Leibe und schenke ihnen dann ein Herz von Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Dann wandeln sie in meinen Satzungen, befolgen meine Vorschriften genau und werden mir zum Volke, ich ihr Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Elender Götzen Greuel haben nun ihr Herz verführt; und denen lohne ich den Wandel auf den Kopf.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Die Cherube erhoben ihre Flügel; desgleichen hoben sich die Räder, und oben über ihnen war die Herrlichkeit des Gottes Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Die Herrlichkeit des Herrn verließ die Stadt und ließ sich auf dem Berge nieder, der östlich von der Stadt gelegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Mich aber hob ein Geist empor und brachte nach Chaldäa mich zu den Gefangenen in einem göttlichen Gesicht. Doch das Gesicht, das ich geschaut, verschwand vor mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Und ich erzählte den Gefangenen dies alles, was der Herr mich hatte schauen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '\"Hör, Menschensohn! Du wohnst im Haus der Widerspenstigkeit bei solchen, die zum Sehen Augen haben und doch nicht sehen, zum Hören Ohren, die jedoch nicht hören. Sie sind ein Haus der Widerspenstigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Du aber, Menschensohn, mach dir ein Reisebündel und zieh bei Tag vor ihren Augen weg! Vor ihren Augen sollst du dann von einem Ort zum andern ziehen! Vielleicht, daß sie dabei zur Einsicht kommen, was für ein Haus der Widerspenstigkeit sie sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Trag deine Habe als ein Reisebündel fort bei Tag vor ihren Augen, wie man\'s beim Auszug macht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Vor ihren Augen grab dir durch die Wand ein Loch, und trag es so hindurch');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Vor ihren Augen nimm\'s dann auf die Schulter und bring\'s im Dunkeln fort! Verhüll dein Angesicht dabei, daß du das Land nicht siehst! Zu einem Wahrzeichen des Hauses Israel mache ich dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Ich tat, wie mir befohlen ward. Ich trug als Reisebündel meine Habe fort bei Tag, und ich ich durchgrub am Abend mit der Hand die Wand. Im Dunkeln trug ich\'s fort und nahm\'s vor ihren Augen auf die Schulter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Darauf erging das Wort des Herrn an mich am andern Morgen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '\"Du Menschensohn! Hat dich nicht das Haus Israel, das Haus der Widerspenstigkeit, gefragt: \'Was machst du da?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sag ihnen: Also spricht der Herr, der Herr: \'Dies Schleppen gilt dem Fürsten in Jerusalem sowie dem ganzen Hause Israel, das drinnen wohnt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dann sprich: \'Ich muß zum Wahrzeichen euch dienen. Wie ich getan, so geht\'s auch ihnen. Sie müssen in Verbannung ziehen und Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Der Fürst in ihrer Mitte aber zieht im Dunkeln mit dem Bündel auf der Schulter fort. Zu seinem Abzug läßt man ihm die Wand durchbrechen. Dabei verhüllt er sein Gesicht. Er schaut das Land mit seinen Augen nimmer wieder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Denn ich umstricke ihn mit meinem Netz; in meinem Garn soll er sich fangen. Ich bringe ihn nach Babel ins Chaldäerland. Das soll er zwar nicht sehen, aber dennoch in ihm sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Was um ihn ist, all seine Dienerschaft und alle seine Scharen zerstreue ich in alle Winde und halte noch das Schwert gezogen hinter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Dann wissen sie, daß ich der Herr bin, wenn ich sie unter diese Heiden hab\' zerstreut und in die Länder sie versprengt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Nur wenige laß ich von ihnen übrig, verschont vom Schwert, vom Hunger, von der Pest. Sie sollen alle ihre Greuel den Heiden eingestehn, wohin sie kommen, und dann erkennen, daß ich der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '\"Ach, Menschensohn! Nun iß dein Brot mit Zittern! Dein Wasser trink in Angst und Sorgen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'und sprich zum Volk des Landes: \'So spricht der Herr, der Herr, von denen, die Jerusalem im Lande Israel bewohnen: In Sorgen werden sie ihr Brot verzehren, mit Angst ihr Wasser trinken. Von Grund aus wird ihr Land verwüstet um des Frevels willen, den die verübt, die es bewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Und die bewohnten Städte werden öde; das Land wird eine Wüste, daß ihr es erkennt: Ich bin der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '\"Sag, Menschensohn! Was habt ihr da für einen Spruch im Lande Israel: \'Die Zeit verzieht sich; doch kein Gesicht trifft ein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Drum sag zu ihnen: \'Also spricht der Herr, der Herr: Ich mache diesem Spruch ein Ende, daß sie in Israel ihn länger nicht gebrauchen.\' So sag zu ihnen: \'Die Tage kommen schon heran mit der Erfüllung jeglichen Gesichtes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Denn fürderhin heißt kein Gesicht mehr falsch und keine Prophezeiung trügerisch im Hause Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Denn ich, der Herr, ich werde sprechen, und was ich spreche, wird geschehn. Nicht lange wird\'s verschoben. In euren Tagen, Haus der Widerspenstigkeit, vollziehe ich, was ich einst angedroht. Ein Spruch des Herrn, des Herrn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '\"Hör, Menschensohn! Fürwahr, es sagt das Haus von Israel: \'Es geht auf späte Tage das Gesicht, das er geschaut; von fernen Zeiten hat er prophezeit.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Drum sprich zu ihnen: \'Also spricht der Herr, der Herr: Auf lange Zeit wird keines meiner Worte mehr verschoben; jetzt trifft ein, was ich verkünde.\'\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '\"So, Menschensohn, so prophezeie gegen Israels Propheten, die Prophezeiungen aussprechen, und sag zu denen, die nur aus sich selbst weissagen: \'Vernehmt das Wort des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Der Herr, der Herr, so spricht er über diese törichten Propheten, die ihrem eignen Geiste folgen, und die doch kein Gesicht gehabt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Den Füchsen in zerstörten Plätzen sind Israels Propheten gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Ihr tretet nicht in Breschen ein, und ziehet um das Haus von Israel kein Mauerwerk, daß fest am Herrentage es im Kampfe stünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Sie tragen Truggesichte vor und Lügenprophezeiungen; sie sagen zwar: \"Ein Spruch des Herrn\", und doch hat niemals sie der Herr gesandt, und trotzdem hoffen sie, daß sich das Wort erfülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Sind das nicht Truggesichte die ihr schaut? Nicht Lügenprophezeiungen, die ihr aussprecht? Und dennoch saget ihr: \"Ein Spruch des Herrn\", obschon ich nicht geredet habe.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Deshalb spricht so der Herr, der Herr: \"Weil ihr nur Trug verkündet und nur Lügen schaut, deshalb, fürwahr, will ich an euch.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, '\"Ja, meine Hand ist gegen die Propheten, die Truggesichte schauen und Lügen prophezeien; sie dürfen nicht zum Kreise meines Volkes mehr gehören, nicht eingetragen bleiben in der Urkunde des Hauses Israel und nicht im Lande Israel geduldet werden, daß ihr erkennet, daß der Herr, der Herr, ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Dafür, und zwar dafür, daß sie mein Volk so täuschen, sie sagen: \'Gut steht es\', da es übel steht, - so daß er eine lockre Wand sich baut, die sie in kümmerlicher Weise übertünchen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'so sprich zu denen, die in solch kümmerlicher Weise übertünchen, daß es zusammenstürzt. \'Gesetzt, es käme eine Regenflut, und Hagelsteine ließ ich niederfallen, ein Sturmwind bräche los,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'gesetzt, die Mauer fiele ein, ja, würde man zu euch nicht sagen: \"Wo ist die Tünche, die ihr aufgetragen?\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Deshalb spricht so der Herr, der Herr: \'Ich laß in meinem Grimme einen Sturm losbrechen, in meinem Zorne eine Regenflut erfolgen, und Hagelsteine werden sie vernichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Die Mauer, kümmerlich getüncht von euch, die reiß ich nieder, werfe sie zu Boden, daß sichtbar wird ihr Grund. Bei ihrem Fall kommt ihr darunter um, und so erkennt ihr, daß der Herr ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Wenn ich dann meinen Ingrimm an der Mauer ausgelassen, sowie an denen, die sie kümmerlich getüncht, dann sag ich euch: Die Mauer ist nicht mehr und keiner mehr von denen, die sie überstrichen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'von den Propheten Israels, die von Jerusalem weissagten und ihm in Gesichten Glück verhießen, da doch kein Glück vorhanden war.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Du Menschensohn! Dein Antlitz wende hin zu deines Volkes Töchtern, die aus sich selber als Prophetinnen auftreten, und prophezeie wider sie');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'und sprich: \'So spricht der Herr, der Herr: Weh denen, die für jede Schulter Kissen richten und Polster für das Haupt zum Schlafen, um Seelen einzufangen! Ihr fangt aus meinem Volke Seelen, um eure eignen Seelen durchzufristen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Bei meinem Volk entweiht ihr mich für eine Handvoll Gerste, für ein paar Bissen Brot, um Seelen so zu morden, die nicht sterben sollten, und Seelen lebend zu erhalten, die nicht leben sollten. Ihr lüget meinem Volk vor, das auf Lügen hört.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Deshalb spricht so der Herr, der Herr: \'Fürwahr, ich will an eure Kissen, womit ihr Seelen, lebenskräftige, zu fangen sucht. Ich reiße sie aus euren Armen und mache frei die Seelen, die ihr so umgarnt, die Seelen, die so lebenskräftig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Ich reiße eure Kissen weg und rette so mein Volk aus euren Händen. Sie sollen keine Beute mehr in euren Händen sein, daß ihr erkennet, daß der Herr ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Weil ihr des Frommen Herz betrügerisch in Angst versetzt, das ich doch nicht geängstigt wissen wollte, weil ihr der Frevler Hände kühner macht, daß sie von ihrem bösen Wege sich nicht kehren, um selber glücklich sich zu machen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'deshalb dürft ihr nicht länger Truggesichte schauen, nicht länger mehr Orakel geben. Nein! Mein Volk befreie ich aus eurer Hand, daß ihr erkennt: Ich bin der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Da kamen einige der Ältesten aus Israel zu mir und setzten sich mir gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '\"Sieh, Menschensohn! Die Männer denken nur an ihre Götzenbilder und stellen vor sich hin das Ding, mit dem sie sich versündigen. Und ich soll ihnen da zur Rede stehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Drum sprich sie an und sag zu ihnen: So spricht der Herr, der Herr: \'Ein jeder, der im Hause Israel an seine Götzen denkt und vor sich hin den Anlaß seiner Sünde stellt, und dennoch zum Propheten kommt, bei einem solchen antworte ich, Jahve, ich selbst auf seine vielen Götzenbilder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Ich will\'s dem Hause Israel in seinem Herzen fühlbar machen, daß es durch seine Götzen all sich mir entfremdet hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Deshalb sag zu dem Hause Israel: So spricht der Herr, der Herr: \'Kehrt um und wendet euch von euren Götzenbildern, von allen euren Greueln wendet euer Antlitz ab!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Denn jeder in dem Hause Israel und von den Fremdlingen, die in Jerusalem verweilen, und wer an seine Götzen denkt und wer den Anlaß seiner Sünde vor sich hinstellt und dennoch zum Propheten kommt, um mich durch diesen zu befragen, dem werde ich, Jahve, die Antwort selber geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Ich wende gegen einen solchen Mann mein Angesicht; ein warnend Beispiel mache ich aus ihm und rotte ihn aus meinem Volke aus, daß ihr erkennet, daß der Herr ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Und läßt sich der Prophet verleiten, ihm eine Antwort zu erteilen, dann habe ich, der Herr, den Seher vorher selbst dazu verleitet. Doch streck ich gegen diesen meine Hand und tilge ihn aus meinem Volke Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'So müssen beide ihr Vergehen tragen, der Fragende wie der Prophet; sie werden gleicherweise schuldig sein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'damit das Haus von Israel von mir nicht Abfall übe und sich durch irgendwelche Freveltat nicht mehr entweihe, daß sie vielmehr zum Volk mir werden und ich für sie zum Gott.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '\"Du Menschensohn! Wenn sich an mir ein Land hat schwer versündigt und ich dawider meine Hand ausstreckte und ihm des Brotes Stab zerbräche und Hungersnot ihm schickte und Mensch und Vieh aus ihm vertilgte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'und drinnen wären die drei Männer, Noë, Daniel und Job, so retteten sie nur sich selbst durch ihre Tugend.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '\"Und brächte ich die wilden Tiere in das Land, und machte ich es menschenleer, zu einer Wüste, die niemand mehr durchwandern möchte, der wilden Tiere wegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'und drinnen wären die drei Männer, so wahr ich lebe\", ein Spruch des Herrn, des Herrn, \"sie würden weder Sohn noch Tochter retten. Sie retteten nur sich allein; das Land jedoch würde zur Wüste werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Und ließe ich das Schwert hingehen über jenes Land und spräche dann: \'Ein Schwert soll durch das Land hinfahren!\' und ich vertilgte Mensch und Vieh daraus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'und drinnen wären die drei Männer, so wahr ich lebe\", ein Spruch des Herrn, des Herrn, \"sie würden weder Sohn noch Tochter retten. Sie retteten nur sich allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Und sendete ich Pest in jenes Land, und gösse blutig meinen Grimm darüber, um Mensch und Vieh daraus zu tilgen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'und wären Noë, Daniel und Job darin, so wahr ich lebe\", ein Spruch des Herrn, des Herrn, \"sie würden weder Sohn noch Tochter retten; sie retteten durch ihre Tugend nur sich selbst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Ja, also spricht der Herr, der Herr: \"Um wieviel mehr nun sende ich jetzt meine vier Strafübel, Schwert und Hunger, wilde Tiere samt der Pest gegen Jerusalem, um Mensch und Vieh daraus zu tilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Und doch bleibt drinnen übrig eine Schar Verschonter. Sie kann selbst Sohn und Tochter noch daraus wegführen. Fürwahr! Sie ziehen dann zu euch; da könnt ihr ihren Wandel, ihre Handlungsweise sehen. Ihr denkt dann anders über dieses Unglück, das für Jerusalem von mir gekommen, all das, was ich darüber brachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Da lehren sie euch anders denken, beschaut ihr ihren Wandel und ihr Tun. Und ihr seht ein, daß ich nicht ohne Ursache geschehen ließ, was ich an ihm getan.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '\"Sag, Menschensohn! Welch einen Vorzug hat das Rebenholz vor all den andern Rankenpflanzen, die zu den Waldbäumen gehören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Kann man aus seinem Holze eine Arbeit machen? Kann man davon etwas zu Pflöckchen brauchen, um allerhand Geräte auf zuhängen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'O nein! Man gibt\'s dem Feuer zum Verzehren. Hat dann das Feuer seine beiden Enden aufgezehrt, und ist die Mitte durchgebrannt, wird\'s noch zu irgendeiner Arbeit taugen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Man konnte es zu irgendeiner Arbeit nicht gebrauchen, als es noch ganz gewesen. Da sollte es, verzehrt und durchgebrannt vom Feuer, zu irgendwelcher Arbeit brauchbar sein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Nun also spricht der Herr, der Herr: \"Wie\'s bei den Waldbäumen mit Rebholz ist, das ich zur Feuerung bestimmt, so mache ich es auch mit den Bewohnern von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Ich richte wider sie mein Angesicht, und kommen sie aus einem Feuer, so wird ein andres sie verzehren, daß ihr erkennt, daß ich der Herr, wenn gegen diese ich mein Antlitz richte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Zur Wüste mache ich das Land, weil Treubruch sie verübt.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Das Wort des Herrn erging an mich -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '\"Geh, Menschensohn, und halt Jerusalem jetzt seine Greuel vor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Und sag: So spricht der Herr, der Herr, jetzt zu Jerusalem: \'Dein Ursprung, deine Abkunft weisen auf die Lande der Kanaaniter. Dein Vater war von amoritischem Geschlecht und deine Mutter von chittitischem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Und das ist die Geschichte deines Lebens: Am Tag, da du geboren wurdest, ward deine Schnur nicht abgeschnitten; nicht wurdest du mit Wasser rein gewaschen. Mit Salz wardst du nicht abgerieben, in Windeln nicht gewickelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Kein Auge sah mit Mitleid auf dich hin, um eines dieser Dinge dir zu tun, aus Mitgefühl mit dir. Du wurdest auf dem freien Feld dir selber überlassen, aus Überdruß an dir, am selben Tage noch, an dem du warst geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Ich habe dich gesehn und dich geschaut, wie du in deinem Blut gezappelt hast. Ich sprach zu dir: Trotz deinem Blute bleib am Leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Aufwachsen ließ ich dich wie das Gewächs des Feldes. So wuchsest du heran und wurdest groß und kamst zur schönsten Blüte deines Leibes; du aber warst noch unvermählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Da habe ich dich wiederum gemustert und beschaut, und siehe da, die Zeit der Liebe war für dich gekommen. Da breitete ich meines Kleides Zipfel über dich, bedeckte deine Blöße, verband mich dir mit einem Eide und trat mit dir in einen Bund.\' Ein Spruch des Herrn, des Herrn. \'So wurdest du denn mein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Dann badete ich dich in Wasser; ich wusch das Blut von dir hinweg und salbte dich mit Öl');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'und hüllte dich in buntgewirkte Kleider und schenkte dir von Seekuhfell Sandalen. Ich band dir einen Linnengürtel um und hüllte dich in einen Seidenschleier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Ich schmückte dich mit Schmuck und legte Spangen um die Arme, um deinen Hals ein Kettchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Ich legte einen Ring auf deine Nase, in deine Ohren Ringe und setzte dir aufs Haupt ein prächtig Diadem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'In Gold und Silber prangtest du, und dein Gewand war Byssus, Seide, Stickerei. Feinmehl genossest du und Honig und Öl und wurdest unbeschreiblich schön, und so kamst du zu königlicher Würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Du warst berühmt bei Heidenvölkern deiner Schönheit wegen; denn sie war ganz vollkommen durch den von mir dir angelegten Schmuck.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, '\'Da bautest du auf deine Schönheit. Trotz deinem Rufe buhltest du und warst mit deiner Buhlerliebe so verschwenderisch zu jedem, der vorüberzog, dem\'s gelten sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Du nahmst von deinen Kleidungsstücken und machtest dir davon ein buntes Lager und buhltest dann mit jenen, wie\'s nimmermehr geschieht und nie geschehen war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'nahmst deine Schmucksachen von meinem Gold und Silber, das ich dir geschenkt, und fertigtest dir Männerbilder und triebst mit ihnen Buhlerei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Du nahmst von deinen buntgestickten Kleidern, sie ihnen umzuhängen. Mein Öl und Rauchwerk legtest du vor ihnen nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Mein Brot, das ich dir gab, aus Feinmehl, Öl und Honig angefertigt und dir zum Essen überlassen, das legtest du zum süßen Opfer ihnen vor.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, '\'Dann nahmst du deine Söhne und deine Töchter, die du mir geboren, und schlachtetest zum Fraß sie ihnen. War\'s nicht genug an deinem buhlerischen Treiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'daß du auch meine Kinder schlachtetest und jenen gabst, und sie für jene durch das Feuer gehen ließest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Bei allen deinen Greueln, deinen Buhlereien, warst du der Tage deiner Kindheit nimmer eingedenk, da du, ganz nackt und bloß, in deinem Blut gezappelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Nach aller deiner Bosheit aber, - wehe, wehe über dich!\' - ein Spruch des Herrn, des Herrn -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, '\'erbautest du dir einen Kegel noch und machtest dir auf jedem Platze Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'An jedem Straßeneingang bautest du dir eine Höhe und schändetest hier deine Schönheit und zeigtest jedem, der vorüberzog, dich willfährig und triebst, um mich zu reizen, unaufhörlich Buhlerei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Du hurtest mit Ägyptens Söhnen, deinen leibesstarken Nachbarn, und triebst, um mich zu reizen, unaufhörlich Buhlerei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Doch sieh! Ich streckte meine Hand aus wider dich und minderte dir deinen Unterhalt. Ich gab dich denen, die dich haßten, preis, den Töchtern der Philister, die sich ob deines Lasterlebens schämten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Dann buhltest du mit Assurs Söhnen, nimmer satt. Und durch die Buhlerei mit ihnen nicht gesättigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'erstrecktest du dein Buhlen bis ins Krämerland, bis nach Chaldäa. Auch davon bist du noch nicht satt geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Wie liebeskrank muß doch das Herz dir sein\', ein Spruch des Herrn, des Herrn, \'da du dies alles tust, was sonst nur Art der ausgeschämten Buhlerin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'An jedem Straßeneingang bautest du dir einen Kegel, und deine Höhe machtest du auf jedem freien Platz. Doch du benahmst dich nicht wie eine Buhlerin. Du hast den Lohn verschmäht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'du ehebrecherisches Weib, das an der Stelle seines Mannes Fremde zu sich nimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Sonst gibt man einer jeden Hure Lohn; du aber gabst Geschenke allen deinen Liebhabern, und du bestachest sie, daß sie von allen Seiten her zum Buhlen mit dir kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Bei deinen Buhlereien findet sich an dir ein Widerspiel mit andere Weibern. Nach deinem Beispiel wird nicht Buhlerei getrieben; denn du gibst selber Lohn; dir aber wird kein Lohn gereicht. So bist du denn ein Widerspiel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Drum, Buhlerin, hör nun des Herren Wort!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So spricht der Herr, der Herr: \'Du hast die Schande aufgedeckt und deine Scham entblößt bei deiner Buhlerei vor deinen Buhlen, vor allen deinen Greuelgötzen. Darum und wegen deiner Söhne Blut, das du für sie geopfert,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'will ich zusammenholen alle deine Buhlen, sie, gegen die du so gefällig warst, sie alle, die du, ach, so gern gehabt, samt allen denen, die du nicht gemocht. Zusammenhole ich sie wider dich von allen Seiten und decke deine Blöße auf vor ihnen, damit sie deine ganze Schande sehn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'belege dich mit Strafen der Ehebrecherinnen und der Mörderinnen und geb dich preis der blutigen Rache der ergrimmten Eifersucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Ich überliefre dich in ihre Hand. Sie reißen deine Kegel nieder, zertrümmern deine Höhen und reißen dir vom Leib die Kleider und nehmen dir die Zierat weg und stellen nackt und bloß dich hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Sie rufen wider dich ein Volksgericht zusammen und steinigen mit Steinen dich, zerstückeln dich mit ihren Schwertern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Sie brennen deine Häuser nieder, vollziehn vor vieler Weiber Augen das Gericht an dir. So mache ich ein Ende deiner Buhlerei; dann gibst du keinen Buhlerlohn mehr her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Ich stille meinen Grimm an dir; dann erst läßt meine Eifersucht von dir. Ich werde ruhig werden und mich nicht fernerhin erzürnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Uneingedenk der Tage deiner Jugend, hast du durch all das mich gereizt; denn jetzt vergelte ich dir deinen Wandel auf den Kopf\', ein Spruch des Herrn, des Herrn. \'Du machtest dir ja nicht Gedanken über alle deine Greueltaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Wer einen Spottvers auf dich machen wollte, der könnte also sagen: \"Wie die Mutter, so die Tochter!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du bist die wahre Tochter deiner Mutter, die ihres Mannes und ihrer Kinder überdrüssig ward. Du bist die wahre Schwester deiner Schwestern, die überdrüssig ihrer Männer und der Kinder wurden. Chittiterin war eure Mutter und euer Vater Amoriter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Samaria mit ihren Töchtern ist deine ältre Schwester, die nördlich von dir wohnt; und deine jüngre Schwester, die südlich von dir wohnt, ist Sodoma mit ihren Töchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Du gingst nicht bloß auf ihren Wegen; du ahmtest nicht bloß ihre Greuel nach; dies war dir bald zuwenig. Noch schlimmer hast du es getrieben als die beiden, in deiner ganzen Lebensart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'So wahr ich lebe!\', ein Spruch des Herrn, des Herrn. \'Nein, Sodom, deine Schwester, hat samt ihren Töchtern nicht getan, was du getan samt deinen Töchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Das war die Sünde Sodoms, deiner Schwester: Übermut. Sie hatte Überfluß an Brot und ungestörte Ruh, sie selbst samt ihren Töchtern; drum blieb der Elende und Arme ohne Unterstützung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Im Übermut verübten sie vor meinem Antlitz Greuel. Da tat ich sie hinweg, nachdem ich es bemerkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samaria hat nicht die Hälfte deiner Sünden je getan. Du hast mehr Greuel ausgeübt als jene beiden, hast deine Schwestern rein erscheinen lassen durch alle deine Greuel, die du verübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Trag selber jetzt die Schmach, die du als recht erkannt für deine Schwestern! Durch deine Sünden, die abscheulicher als ihre, erscheinen sie weit reiner doch als du. Nun schäme du dich selbst, trag deine Schmach! Du hast ja deine Schwestern rein erscheinen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Ich aber bringe ihr verbanntes Volk zurück, ja das verbannte Volk von Sodoma und ihren Töchtern, das von Samaria und ihren Töchtern und zwischen beiden dein verbanntes Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Denn du hast deine Schmach getragen und alles dessen dich geschämt, was du verübt, nachdem du jenen einen Trost gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Und deine Schwestern, Sodoma und ihre Töchter, sie werden wieder, was sie waren. Samaria und ihre Töchter wieder, was sie waren. Auch du und deine Töchter wieder, was ihr wart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Und doch kam Sodom, deine Schwester, nicht in deinen Mund zu jener Zeit, da du so stolz gewesen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'als deine Schlechtigkeit noch unbekannt geblieben, zu jener Zeit, da Schmach die Töchter Syriens und ihre Nachbarinnen, Philistäas Töchter, drückte. Sie überfallen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Abbüßen mußt du deine Unzucht, deine Greuel\', ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Denn also spricht der Herr, der Herr: \'Dir sollte ich nun tun, wie du getan, die du den Eidschwur nicht geachtet, dadurch, daß du den Bund gebrochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Doch ich bin meines Bundes mit dir in den Tagen deiner Jugend eingedenk, und ich errichte einen ewigen Bund mit dir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'wenn du mit Scham an deinen Wandel denkst und deine ältere Schwester und deine jüngere zu dir nimmst. Ich will sie dir zu Töchtern geben, doch nicht zufolge deines Bundes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Ich will mit dir mein Bündnis schließen, daß du erkennest, daß der Herr ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Erinnre dich mit Scham daran! Entschuldige dich nimmer ob der Schmach, wenn ich vergebe dir, was alles du getan!\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '\"Geh, Menschensohn! Verkünde einen Rätselspruch, ein Gleichnis von dem Hause Israel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'und sprich: \'So spricht der Herr, der Herr: Der große Adler mit den großen Flügeln und mit der langen Schwungfeder, mit starken Schwingen, die Schnelligkeit besaßen, kam auf den Libanon, ein dünnes Zedernreis zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Von seinen jungen Zweigen brach er eine Spitze ab und brachte sie zu einem Krämerland und pflanzte sie in eine Kaufmannsstadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Dann nahm er eines von des Landes Setzgewächsen und pflanzt\' es in ein Ackerfeld. Er setzte es an reichlich Wasser, pflanzte es an einen Ort, wo Weiden wachsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Es wuchs heran und ward ein Rebstock von rankendem und niedrem Wuchs, daß seine Ranken, einwärts eingebogen, grad über seinen Wurzeln lagen. Doch wurde er zu einem Weinstock, der Zweige trieb und Laubwerk schob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Noch war ein andrer großer Adler da mit großen Flügeln, starker Schwinge. Zu diesem bog der Weinstock seine Wurzeln und streckte seine Ranken nach ihm aus, daß er ihn tränken möchte mehr, als es seine Pflanzungsstätte tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Und doch war er in gutes Feld verpflanzt an viele Wasser, damit er Zweige triebe, Früchte brächte und so zu einem schmucken Weinstock würde.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sprich: \'Also spricht der Herr, der Herr: Wird\'s einen guten Ausgang nehmen? Wird nicht der erste seiner Wurzeln ihn berauben und seine Frucht abreißen, daß alle Zweige seines Triebes dürre werden? Nicht braucht es eine große Kraft, nicht vieles Volk, um diesen seiner Wurzeln zu berauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Da steht er zwar jetzt umgepflanzt. Wird\'s einen guten Ausgang nehmen? Wird er, falls ihn ein Ostwind trifft nicht ganz verdorren? Wird er auf seinem Pflanzort nicht verdorren?\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '\"So sprich zum Haus der Widerspenstigkeit: \'Versteht ihr nicht, was dies bedeutet?\' So sprich: \'Es kam der König Babels nach Jerusalem, ließ seinen König, seine Fürsten greifen und sie zu sich nach Babel bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Dann nahm er einen von dem königlichen Stamm und machte einen Bund mit ihm und nahm ihm einen Eidschwur ab. Die Mächtigsten des Landes nahm er mit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'um so das Reich zu schwächen, daß sich\'s nicht abermals erhöbe, vielmehr den Bund in Dienstbarkeit einhielte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Doch fiel er von ihm ab und sandte seine Boten nach Ägypten, daß es ihm Rosse und viel Kriegsvolk überlasse. Kann solches einen guten Ausgang nehmen? Kann der sich retten, der dies tut? Kann der entkommen, der ein Bündnis bricht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'So wahr ich lebe\', ein Spruch des Herrn, des Herrn, \'am Ort des Königs, der ihn zum König eingesetzt, dem er den Eid der Treue nicht gehalten, dem er den Bund gebrochen, bei dem soll er zu Babel sterben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Trotz großem Heer und starker Schar tut Pharao für ihn im Kriege nichts, wenn er auch Wälle schüttet, Türme baut, um viele Leben auszurotten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Er hatte nicht des Eidschwurs acht; er wurde bundesbrüchig, obwohl er ihm die Hand gegeben. Er, der dies alles tat, wird nicht entkommen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Darum spricht so der Herr, der Herr: \'So wahr ich lebe, den mir zugeschworenen Eid, den er mißachtet, und den bei mir geschlossenen Bund, den er gebrochen, den gebe ich ihm auf den Kopf zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Ich stelle gegen ihn mein Netz, daß er in meinem Garn sich fange. Dann bringe ich ihn hin nach Babel und halte dort an ihm Gericht, weil er an mir treulos gehandelt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Und seine besten Truppen, all seine Kriegerscharen fallen durch das Schwert. Wer sonst noch übrigbleibt, der wird in alle Winde hin zerstreut, daß ihr erkennt: Ich selbst, der Herr, hab es gesagt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So spricht der Herr, der Herr: \'Dann nehme ich etwas vom Wipfel jener hohen Zeder und setz es ein und pflücke von den jungen Trieben eine zarte Spitze ab und pflanze sie auf einen hohen und erhabenen Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Auf Israels erhabnen Berg will ich sie pflanzen, auf daß sie Zweige treibe, Früchte trage und so zu einer schmucken Zeder werde, auf daß darunter Vögel aller Art und allerlei Geflügel im Schatten seiner Zweige wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Dann werden alle Bäume auf dem Feld erkennen, daß ich, der Herr, zu niedrigen Gesträuchen hohe Bäume und niedriges Gesträuch zu hohen Bäumen machen kann, daß ich den grünen Baum verdorren, den dürren Baum zum Grünen bringen kann. Ja, ich, der Herr, ich sage es und tue es.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '\"Wie kommt gerade ihr dazu, daß ihr vom Lande Israel das Sprichwort braucht: \'Die Väter aßen saure Trauben; doch erst den Kindern wurden ihre Zähne stumpf davon\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'So wahr ich lebe!\" Ein Spruch des Herrn, des Herrn. \"Ihr sollt in Israel nicht ferner diesen Spruch gebrauchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Mir gelten alle Seelen gleich. Der Vater gilt das gleiche wie der Sohn. Und nur wer sündigt, der muß sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Ist jemand ein Gerechter und handhabt er Gerechtigkeit und Recht');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'und nimmt er nicht am Mahl auf Bergen teil, erhebt er seine Augen nicht zu Götzenbildern in dem Hause Israel, entehrt er nicht des Nachbarn Weib und naht er nicht dem Weibe sich im Unreinsein');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'und unterdrückt er niemanden, nimmt keine Pfändung vor, begeht nicht Raub und teilt er mit den Hungrigen sein Brot, bedeckt die Nackten mit Gewändern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'leiht er kein Geld auf Wucher aus und nimmt nicht Zinsen, hält er vom Unrecht seine Hand zurück und handelt er nach wahrem Rechte gegen seine Nebenmenschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'und lebt er auch nach meinen Vorschriften und hält genau, was ich befohlen: Solch ein Gerechter, der soll leben.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, '\"Und hat er einen Bösewicht zum Sohn, der Blut vergießt und etwas derart tut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'was jener niemals sich erlaubte, daß er auf Bergen schmaust und seines Nachbarn Weib entehrt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'daß er den Dürftigen und Armen unterdrückt und Raub begeht und nicht zurückgibt das Verpfändete, daß er zu Götzen seine Hände hebt und Greueltaten tut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'daß er auf Wucher leiht und Zinsen nimmt: Ein solcher sollte leben dürfen? Nein, leben soll er nicht, der solche Greuel tut. Doch er allein verdient den Tod; auf ihm soll seine Blutschuld lasten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Hat dieser wieder einen Sohn, der seinen Vater sieht die vielen Sünden tun, er aber fürchtet sich und tut nicht so;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'er schmaust nicht auf den Bergen und hebt nicht seine Augen zu den Götzen im Haus Israel, entehrt nicht seines Nachbarn Weib');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'und unterdrückt niemanden, noch nimmt er Pfändung vor, begeht auch keinen Raub und teilt sein Brot mit Hungrigen, bedeckt mit Kleidern Nackte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'und hält vom Unrecht seine Hand zurück und nimmt nicht Wuchervorteil an, nicht Zins, und tut, was ich befohlen, und lebt nach meinen Satzungen: Ein solcher stirbt nicht wegen seines Vaters Missetat; er soll am Leben bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Sein Vater aber, der Gewalt verübt und Raub getan an seinen Brüdern, der unter seinem Volke Schlechtigkeiten trieb, der muß um seiner Sünden willen sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Und saget ihr: Warum büßt nicht der Sohn des Vaters Missetat? Es hat der Sohn Gerechtigkeit und Recht geübt, all meine Vorschriften gehalten und befolgt; er darf am Leben bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Wer sündigt, der allein soll sterben; kein Sohn soll büßen für des Vaters Schuld. Den Frommen soll die Frömmigkeit, den Bösen schlimmes Tun in Rechnung kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Doch kehrt der Bösewicht sich ab von allen Sünden, die er tat, und hält, was ich geboten, und übt Gerechtigkeit und Recht, so soll er leben und nicht sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Von seinen Sünden all, die er begangen, soll keine einzige ihm angerechnet werden. Er lebe wegen der Gerechtigkeit, die er geübt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Soll ich Gefallen finden an des Sünders Tod?\" Ein Spruch des Herrn, des Herrn. \"Und nicht daran, daß er, von seinem Wandel sich bekehrend, lebe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Wenn sich der Fromme seiner Frömmigkeit entäußert und Schlechtes tut, und treibt er alle Greuel, die der Schlechte treibt, soll er am Leben bleiben? Gedacht wird nicht mehr aller seiner frommen Taten. Er stirbt des Frevels wegen, den er tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Doch wenn ihr sagt: \'Des Herrn Verfahren ist nicht in der Ordnung\', so hört doch, ihr vom Hause Israel! Ja, sollte mein Verfahren nicht in Ordnung sein? Ist nicht vielmehr euer Verhalten nicht in Ordnung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Wenn seiner Frömmigkeit der Fromme sich entäußert und übt er Frevel aus und stirbt darüber, so stirbt er wegen seines Frevels, den er tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Doch kehrt der Schlechte um von seinem schlimmen Wesen, das er trieb, und übt Gerechtigkeit und Recht, sein Leben wird er dann behalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Weil er zur Einsicht kam und sich von allen den begangnen Sünden wandte, soll er leben und nicht sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Und spricht das Haus von Israel: \'Des Herrn Verfahren ist nicht in der Ordnung\', ja, mein Verfahren wäre nicht in Ordnung, Haus Israel? Ist eures vielmehr nicht in Ordnung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'So richte ich denn jeglichen von euch nach seinem Richten, Haus Israel.\" Ein Spruch des Herrn, des Herrn. \"Kehrt um! Laßt ab von allen euren Sünden, daß nicht die Sünde euch zum Sturz gereiche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Werft weg von euch all eure Sünden, durch die ihr euch vergangen! Ein neues Herz schafft euch und einen neuen Geist! Warum denn wollt ihr sterben, du Haus Israel?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Ich habe kein Gefallen an dem Tode dessen, der ihn verdient\", ein Spruch des Herrn, des Herrn. \"Damit ihr lebet, kehret um!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '\"Stimm an ein Klagelied, die Klage auf die Fürsten Israels');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'und sprich: \'Was war doch deine Mutter? Nicht eine Löwin zwischen Löwen, die unter Jungleu\'n ihre Jungen großgezogen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Sie brachte eins von ihren Jungen in die Höhe; dies ward ein Jungleu. Er lernte Beute machen und fraß Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Da rief man Heidenvölker gegen ihn zusammen; in ihrer Grube wurde er gefangen. Man brachte ihn mit Nasenringen ins Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Sie sah, daß ihre Hoffnung rettungslos gescheitert. Sie nahm ein andres ihrer Jungen, um es zum Löwen zu erziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Und zwischen Löwen ward er selbst ein Löwe; er lernte Beute machen und fraß Menschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'mißhandelte die Witfrauen, verheerte ihre Städte. Das Land und was darin entsetzte sich ob seines lauten Brüllens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Da legten gegen ihn die Heiden aus den Ländern ringsumher die Netze aus und breiteten sie über ihn. Gefangen wurde er in ihrer Grube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Sie zogen ihn mit Ringen in den Käfig und führten ihn zu Babels König. Sie setzten ihn in einen Turm, so daß man nimmer seine Stimme hörte auf den Gebirgen Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Wie du war deine Mutter wie ein Weinstock, verpflanzt an Wasserläufe, fruchtbar, zweigereich vom vielen Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Er hatte starke Rebstöcke, die sich zu Herrscherstäben eigneten. Er ragte in dem Laubwerk hoch empor; durch seine Größe, seiner Ranken Menge fiel er auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Da ward durch einen heißen Wind er ausgerissen und auf den Boden hingeworfen. Der Ostwind machte seine Früchte dürr, und seine starken Stöcke wurden abgerissen und verdorrten; dann fraß sie Feuer vollends auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Und nun ist er verpflanzt in eine Wüste, in dürres, durstiges Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Ein Feuer ging von einem rankenreichen Rebstock aus, und seine Frucht verzehrte es. Kein starker Rebstock war an ihm zum Herrscherstabe tauglich. Kläglich ward er so und bot zu einem Klagelied den Stoff.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Am zehnten Tag des fünften Monds im siebten Jahr, da kamen einige der Ältesten aus Israel, den Herren zu befragen, und setzten sich mir gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Alsdann erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '\"Sprich, Menschensohn! Sprich zu den Ältesten von Israel und sage ihnen: So spricht der Herr, der Herr: \'Mich zu befragen kommet ihr? So wahr ich lebe, ich laß von euch mich nicht befragen.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Willst du mit ihnen denn nicht rechten, willst du nicht rechten, Menschensohn? Halt ihnen ihrer Väter Greuel vor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Und sprich zu ihnen: Also spricht der Herr, der Herr: \'Am Tage, da ich Israel erwählt und da ich dem Geschlecht des Hauses Israel mich vorgestellt und da ich ihnen im Ägypterland mich kundgetan, und da ich ihnen so mich vorgestellt: Ich bin der Herr, bin euer Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'an jenem Tage, da ich ihnen schwur mit aufgehobener Hand, sie aus Ägypterland zu führen in das Land, das ich für sie erwählt, das ich von Milch und Honig übervoll gemacht, in dieses Kleinod unter allen Ländern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'da sagte ich zu ihnen: Ein jeder werfe fort die Greuelgötter seiner Augen, und es verunreinige keiner sich mit Götzenbildern der Ägypter! Denn ich, der Herr, bin euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Sie aber waren ungehorsam gegen mich und wollten nimmer auf mich hören, und keiner warf die Greuelgötter seiner Augen weg. Ägyptens Götzenbilder wollte keiner fahren lassen. Ich drohte, meinen Ingrimm über sie zu gießen und im Ägypterlande meinen Zorn an ihnen zu erschöpfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Ich tat jedoch um meines Namens willen anders, damit er vor den Heiden nicht entheiligt wurde, bei denen sie verweilten. Ich machte mich vor deren Augen ihnen dadurch kenntlich, daß ich sie aus Ägypterlande führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Ich führte sie ans dem Ägypterland hinaus und leitete sie in die Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Da gab ich ihnen meine Satzungen und offenbarte ihnen meine Vorschriften, daß jeder, der nach ihnen lebe, glücklich werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Auch gab ich ihnen meine Sabbate zum Zeichen der Verbindung zwischen mir und ihnen und zum Beweis, daß ich, der Herr, sie heiligte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Doch war das Haus von Israel auch in der Wüste ungehorsam gegen mich. Es lebte nicht nach meinen Satzungen und sah verachtungsvoll auf meine Vorschriften, durch die der glücklich werden sollte, der danach lebte, und meine Sabbate entweihten sie gar sehr. Ich dachte meinen Ingrimm über sie zu gießen, sie in der Wüste aufzureiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Ich tat jedoch um meines Namens willen anders, damit er von den Heiden nicht entheiligt werde, vor deren Augen ich sie einst herausgefordert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Doch schwur ich in der Wüste selbst mit aufgehobner Hand, sie nicht mehr in das Land zu bringen, das ich von Milch und Honig triefen machte, in dieses Kleinod unter allen Ländern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'weil sie Verachtung gegen meine Vorschriften bewiesen, nach meinen Satzungen nicht lebten und meine Sabbate entweihten. Ihr Herz ging ihren Götzen nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mein Auge aber blickte mitleidsvoll auf sie, daß ich sie nicht verderben konnte und in der Wüste nicht Vernichtung über sie verhängte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Ich sprach zu ihren Söhnen in der Wüste: Lebt nicht nach eurer Väter Sitten! Befolgt nie ihre Bräuche! Befleckt euch nicht mit ihren Götzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ich selbst, der Herr, bin euer Gott. So lebt nach meinen Satzungen! Befolget meine Vorschriften; erfüllt Sie,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'feiert meine Sabbate zum Zeichen der Verbindung zwischen mir und euch und zum Beweise, daß ich selbst der Herr bin, euer Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mir aber waren auch die Söhne ungehorsam. Sie lebten nicht nach meinen Satzungen, befolgten nimmer meine Vorschriften und taten nicht danach, wodurch der glücklich werden sollte, der danach lebte. Und sie entweihten meine Sabbate. Ich drohte, meinen Ingrimm über sie zu gießen und meinen Zorn an ihnen in der Wüste auszulassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Doch stand ich wieder davon ab und tat um meines Namens willen anders, damit er vor den Heiden nicht entheiligt werde, vor deren Augen ich sie einst herausgefordert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Doch schwur ich in der Wüste selbst mit aufgehobner Hand, sie unter Heidenvölker zu zerstreuen und in die Länder zu versprengen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Weil meine Vorschriften sie nicht befolgten und meine Satzungen verachteten und meine Sabbate entweihten und ihre Augen nach den Götzen ihrer Väter richteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Nun ließ ich zu, daß sie den schlechtesten Gesetzen und den Bräuchen folgten, wonach sie niemals leben konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Ich ließ auch zu, daß sie sich schändeten durch ihre Gaben und daß sie alle Erstgeburt dem Feuer weihten. Dafür vernichte ich sie jetzt, daß sie erkennen lernen, daß ich der Herr.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Deswegen, Menschensohn, sprich zu dein Hause Israel und künde ihm: So spricht der Herr, der Herr: \'Auch dieses noch! Mich höhnten eure Väter und brachen mir die Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Kaum führte ich sie in das Land, das ihnen einzuräumen einst ich ihnen zugeschworen, da blickten sie nach jedem hohen Hügel und dichtbelaubten Baum und opferten dort ihre Opfer. Dort legten sie auch Gaben nieder mir zum Ärgernis; dort ließen sie die süßen Wohlgerüche wallen; dort gossen sie Trankopfer aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Obwohl ich ihnen sagte. \"Was ist\'s denn mit der Höhe, zu der ihr euch begeht?\", so wird der Name \"Höhe\" doch bis auf diesen Tag genannt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Deshalb sprich zu dem Hause Israel: \'So spricht der Herr, der Herr: Befleckt ihr euch nicht selbst nach eurer Väter Weise, und buhlt ihr selbst nicht ihren Götzen nach?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ja, bringt ihr eure Gaben dar und lasset eure Söhne durch das Feuer gehn, so macht ihr euch bis heut befleckt durch alle eure Götzen. Soll ich von euch, Haus Israel, mich noch befragen lassen? So wahr ich lebe\', ein Spruch des Herrn, des Herrn, \'ich laß mich nicht von euch befragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Nach eurem Wunsche soll\'s nicht gehn! Ihr sagt: \'Wir wollen wie die Heidenvölker, wie die Geschlechter in den andern Ländern Holz und Stein verehren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'So wahr ich lebe\', ein Spruch des Herrn, des Herrn, \'mit starker Hand und ausgestrecktem Arm, so herrsche ich mit ungehemmtem Grimme über euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'ich will euch aus den Völkern herausführen und aus den Ländern sammeln, wohin zerstreut ihr seid. Mit starker Hand und ausgestrecktem Arm und ungehemmtem Grimme bringe ich');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'euch in der Völker Wüste und gehe mit euch dorten ins Gericht von Angesicht zu Augesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Wie über eure Väter in Ägyptens Wüste, so halte ich auch über euch Gericht\', ein Spruch des Herrn, des Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, '\'und laß euch unterm Stab durchgehen; ich zwing euch in des Halfters Fessel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Absondern werde ich von euch die Widerspenstigen und die mir untreu wurden. Ich will sie aus dem Lande führen, wo sie geweilt. Doch in die Heimat Israels kommt keiner, auf daß ihr es erkennt: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Ihr aber, du Haus Israel!\' - so spricht der Herr, der Herr - \'geht bin und dient ein jeder seinem Götzen! - Nachdem ihr mir nicht mehr gehorchen wollt, entweiht dann nicht noch länger meinen heiligen Namen durch eure Opfergaben, eure Götzen! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Auf meinem beiligen Berg, auf dem erhabenen Berge Israels\', ein Spruch des Herrn, des Herrn, \'wird dienen mir das ganze Haus von Israel, ein jeglicher im Lande. Dort heiße ich sie hoch willkommen. Dort frage ich nach euren Hebeopfern und nach den ersten Abhüben. Da heiße ich euch hoch willkommen mit allen euren heiligen Gaben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'und mit dem süßen Wohlgeruch, wenn ich euch aus den Völkern erst herausgeführt und euch gesammelt habe aus den Ländern, in die ihr seid zerstreut, und mich an euch erwiesen als heilig vor der Heiden Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Dann wisset ihr, daß ich der Herr, wenn ich euch in die Heimat Israels zurückversetze, ins Land, das ich mit Eidschwur euren Vätern zuerkannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Da denket ihr an euren Wandel, an alle eure Taten, mit denen ihr euch habt befleckt. Euch ekelt\'s vor euch selbst ob all der Schlechtigkeiten, die ihr ausgeübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Dann seht ihr ein, daß ich der Herr, wenn ich mit euch nach meinem Namen tue und nicht nach eurem schlimmen Wandel und nicht nach euren schlechten Taten, o Haus Israel.\' - Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '\"Nun, Menschensohn! Wende dein Angesicht nach Süden hin und sprich gen Mittag hin und weissage dem Wald im Süden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Und sprich zum Wald des Südens: Vernimm das Wort des Herrn: \'So spricht der Herr, der Herr: Ich zünde an in dir ein Feuer, das alles graue Holz und alles dürre Holz in dir verzehrt. Gelöscht wird nicht die lichterlohe Flamme! Nein! Es werden dadurch alle Seiten angezündet von Süden bis zum Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Und alles Fleisch soll sehn, daß ich, der Herr, es angezündet, das nimmermehr erlischt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Ich sprach: \"Ach Herr, o Herr! Sie sagen dann von mir: \'Spricht er nicht immerzu in Bilderreden?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Darauf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, '\"Jetzt, Menschensohn! Wende dein Antlitz gen Jerusalem und sprich von Heiligtümern und weissage dem Lande Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Sprich zu dem Lande Israel: So spricht der Herr: \'Ich will an dich; ich zieh mein Schwert aus seiner Scheide; ich rotte bei dir aus Unschuldige und Schuldige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Weil ich bei dir Unschuldige und Schuldige vernichte, kommt mein Schwert aus seiner Scheide auch wider alles Fleisch vom Süden bis zum Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Und alles Fleisch verspürt, daß ich der Herr, mein Schwert aus seiner Scheide zog, unwiderruflich.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Du aber, Menschensohn! In bittrem Schmerze stöhne, daß die Lenden brechen! Vor ihren Augen stöhne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Und sagen sie zu dir: \'Worüber stöhnst du denn?\', so sprich: \'Der Nachricht wegen, die gekommen. Darob schmilzt jedes Herz, und lahm sind alle Hände, und jeder Sinn ist stumpf, und über jedes Knie fließt Wasser. So muß es kommen; ja, so muß es werden.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Alsdann erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '\"Sag, Menschensohn! Weissage, sprich: So spricht der Herr: \'So sprich: ein Schwert, ein Schwert! Geschärft und blank gemacht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Zum Schlachten wurde es geschärft, zum Blitzen blank gemacht, noch mehr als eines Bildhauers und Zimmermannes Beil, das jeden Baum umlegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Man ließ es schleifen, auf daß man\'s mit der Hand ergreife. Geschärft und blank gemacht ward dieses Schwert, um es dem Henker in die Hand zu drücken.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Nun schrei, nun heule, Menschensohn! Denn an mein Volk will es, an alle Fürsten Israels. Sie sind samt meinem Volk dem Schwert verfallen. Schlag dich daher auf deine Hüften!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Bestimmt ist es, wenn auch das Beil, das fällende, noch fehlen sollte.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '\"Du, Menschensohn! Weissag und schlag zusammen deine Hände! Das Schwert verdoppelt, ja verdreifacht sich, das Schwert für die zu Mordenden, ist\'s doch ein Schwert gar groß und mörderisch, so tief einschneidend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Daß man den Mut verliere, daß es zum Sturze vielen Anlaß gebe, stelle ich für das Schwert an alle ihre Tore eine Schlachtbank. Ha! Blank zum Blitzen ist\'s gemacht; geschliffen ist\'s zum Schlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Wend dich nach Westen, Süden, Ost und Norden, wohin nur deine Schneide ist gerichtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Die Hände schlage ich dann auch zusammen; ich habe meinen Zorn gekühlt. Ja, ich, der Herr, ich hab es ausgesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Alsdann erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, '\"Du Menschensohn, beachte die zwei Wege, darauf das Schwert des Babelkönigs kommen kann! Vom Lande eines Mannes gehn sie aus. Des Zaubrers Hand am Anbeginn der Wege weist auf Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Zugänglich macht sie für des Schwertes Kommen Rabbat bei Ammons Söhnen und Juda mit Jerusalem, der festen Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Am Scheidewege stand ja Babels König, am Anbeginn der beiden Wege, um ein Orakel einzuholen, dann schüttelt er die Pfeile, befragt die Teraphim, beschaut die Leber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Dann fällt zum Ende das Orakel nach rechts hin, auf Jerusalem, auf daß die Mauerbrecher angesetzt und Mordbefehle ausgegeben werden, daß lauter Kriegsgeschrei erschalle und daß man Mauerbrecher an die Tore setze und einen Wall aufschütte, Türme baue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Zwar kommt dies ihnen wie ein Trugorakel vor, sie schwören\'s selbst einander zu. Doch er erinnert sich der Schuld, daß sie bezwungen werden müssen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Darum spricht so der Herr, der Herr: \"Ihr habet mich an eure Schuld erinnert, so offenbar sind eure Sünden, so sichtbar eure Frevel. Ihr steht in solchem Ruf bei allem eurem Tun. Drum werdet ihr bezwungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Und du, dem Tod verfallener, nichtswürdiger Fürst von Israel, du, dessen Tag erschienen und dessen Sünde jetzt das Ende bringt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'So spricht der Herr, der Herr: \"Weg mit dem Diadem! Weg mit der Krone! So soll\'s nicht weiter bleiben! Empor jetzt mit dem Niedrigen! Herunter mit dem Hohen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Dreifache Umwälzung verhänge ich. Noch nie ist so etwas geschehen, bis daß der kommt, dem Herrschermacht gebührt. Ich geb sie ihm. Du aber, Menschensohn, weissage, sprich: So spricht der Herr, der Herr, von Ammons Söhnen, ihrem schändlichen Betragen. So sprich: \'Ein Schwert ist schon gezückt zum Schlachten, schon blank gemacht zum Kommen unter Blitzen. Solang man dir noch Trug erschaut und Lügen prophezeit, wirst du dich selbst zu Missetätern stellen, die jetzt enthauptet werden sollen, für die ihr Tag erschienen ist, die Zeit des Endes ihres Frevels. Steck nur das deine in die Scheide! Am Ort, wo du erschaffen wardst, in deinem Ursprungsland will ich dich strafen. Ich gieße meinen Ingrimm über dich und schnaube dich in meinem Zorne an und gebe dich in wilder Menschen Hände, die im Vernichten wohl erfahren sind. Du wirst des Feuers Nahrung werden; dein Blut ist mitten in der Erde und fällt so der Vergessenheit anheim. Denn ich, der Herr, ich hab\'s gesprochen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '\"Du, Menschensohn, willst du der blutbefleckter Stadt nicht das Gewissen schärfen und ihre vielen Greuel ihr jetzt vorhalten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'So sprich: So spricht der Herr, der Herr: \'Du Stadt, die Blut vergießt in ihrer Mitte, daß ihre Zeit erscheinen muß, die Götzenbilder macht für die Entheiligung des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Ja, durch dein Blut, das du vergossen, bist du schuldbeladen, durch deine Götzen, die du machst, befleckt. Du hast dadurch beschleunigt deine Tage und bist zu deinen Jahren schon gelangt. Drum mach ich dich zum Spott bei Heidenvölkern, zum Schimpf für alle Länder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Die Nahen wie die Fernen rufen, deiner spottend: \"Ha! die Berüchtigte, jetzt an Bestürzung reich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Fürwahr, die Fürsten Israels, ein jeder brauchte seine Macht bei dir zum Blutvergießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Den Vater und die Mutter achtet man bei dir gering, und mit Gewalt mißhandelt man die Fremdlinge bei dir, bedrückt bei dir die Waisen und die Witwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Und du verachtest meine heiligen Gebräuche, und meine Sabbate entweihest du.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Verleumder stehn in dir bereit zum Blutvergießen, und auf den Bergen hält man Mahlzeiten bei dir. In deiner Mitte treibt man Unzucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Bei dir deckt man des Vaters Blöße auf; bei dir gesellt man sich zu Weibern, wenn sie unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Man treibt mit seines Nachbarn Weibe Greuliches; blutschänderisch entehrt man Schwiegertöchter, und seine Schwester, seines Vaters Tochter, schändet man bei dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Man nimmt bei dir Geschenke an zum Zweck des Blutvergießens; ja, Wucherzinsen nimmst du an. Gewinn erpressest du vom Nachbarn mit Gewalt, und mich hast du vergessen.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, '\"Doch über den Gewinn, den du gemacht, schlag ich zusammen meine Hände und über deine Blutschuld, die bei dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Wird wohl dein Mut jetzt standhalten, und bleiben deine Hände fest an jenem Tage, da ich mich mit dir befasse? Ich drohe, ich, der Herr, und ich vollführe es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Ich streu dich unter Heidenvölker hin, zersprenge in die Länder dich und nehme das, was an dir unrein, von dir weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Du bist dann in der Heiden Augen selber unrein. Da erkennst du an, daß ich der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '\"Hör Menschensohn! Das Haus von Israel gilt mir wie Schlacken. Sie alle zeigen sich als Erz und Zinn, als Eisen und als Blei im Tiegel. Das Silber wurde ja zu Schlacken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Deshalb spricht so der Herr, der Herr: \"Weil alle ihr zu Schlacken seid geworden, drum bringe ich euch nach Jerusalem zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'So wie man Silber, Erz und Eisen, Blei und Zinn zusammen in den Tiegel tut und Feuer anbläst, es zu schmelzen, sammle auch ich in meinem Zornesgrimme euch und werfe euch zusammen, euch zu schmelzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Ich sammle euch und fache an mein Zornesfeuer gegen euch, daß ihr darin geschmolzen werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Wie man im Tiegel Silber schmelzt, sollt ihr darin geschmolzen werden, daß ihr erkennt, ich bin der Herr. Ich gieße meinen Grimm auf euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '\"Sprich, Menschensohn! Sprich so zu ihm: \'Du bist ein Land, nicht ausgejätet, des Zornestages wegen nicht beregnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Die unter sich verschworenen Propheten gleichen darin dem Leu, der brüllt, geht er auf Raub. Denn sie verschlingen Menschenleben und nehmen Schätze an und Kostbarkeiten; die Witwenzahl vermehren sie im Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Und mein Gesetz verletzen gröblich seine Priester, entweihen meine Heiligtümer und machen zwischen heilig und gemein nicht den geringsten Unterschied und lehren nicht, was rein und unrein. Vor meinen Sabbaten verschließen sie die Augen, und mitten unter ihnen sehe ich mich selbst entweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Drum gleichen seine Fürsten drin den räuberischen Wölfen; denn sie vergießen Blut und stürzen Menschenleben ins Verderben des niedrigsten Gewinnes wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Und seine Seher streichen ihnen Tünche drüber. Sie schauen Trug und prophezeien ihnen Lügen und sprechen: \"Also spricht der Herr, der Herr\", obschon der Herr gar nicht gesprochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Man vergewaltigt das gemeine Volk und raubt es aus. Die Dürftigen und Armen unterdrücken sie und tun dem Fremdling wider Recht Gewalt an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Ich suchte unter ihnen einen Mann, der sich die Mühe gab, die Mauern auszubessern, der in den Riß sich stellte zu des Landes Bestem. Ich konnte niemand finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Nun will ich meinen Ingrimm über sie ergießen, in meinem Zornesfeuer sie vertilgen. So gebe ich den Wandel ihnen auf den Kopf zurück.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '\"Hör, Menschensohn! Zwei Weiber lebten einst, die Töchter einer Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Sie buhlten in Ägypten. Sie buhlten dort in ihrer Jugendzeit, und dort berührte man den jugendlichen Busen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Sie hießen Ohola, die ältere, Oholiba, die Schwester. Sie wurden mir verbunden, gebaren dann auch Söhne, Töchter. Samaria wird Ohola, Jerusalem Oholiba genannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Da buhlte Ohola, obgleich mir angehörend, und wurde gegen ihre Buhlen liebetrunken, die Söhne Assurs, die sie sich aussuchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Da waren Fürsten und Satrapen, purpurblau gekleidet, und Jünglinge von reizender Gestalt, und Reiter, die zu Pferde saßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Sie gab sich ihnen preis zur Buhlerei, den auserlesenen Söhnen Assurs insgesamt, und sie befleckte sich mit ihnen allen, mit denen sie der Liebe pflog, mit allen ihren Unreinheiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Daneben ließ sie nicht von ihren Buhlereien mit Ägypten. Sie lagen bei ihr schon in ihrer Jugendzeit, berührten ihren jugendlichen Busen und lebten so mit ihr in ausschweifendem Genuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Ich gab sie deshalb ihren Buhlen preis, den Söhnen Assurs, gegen die sie liebetrunken war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Und sie enthüllten ihre Blöße und nahmen ihre Söhne, ihre Töchter fort und töteten sie selber mit dem Schwert. So wurde sie ein Denkmal für die Weiber, nachdem das Strafgericht an ihr vollzogen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Obschon dies ihre Schwester, die Oholiba, gesehen, trieb sie noch ärger ihre Liebelei als jene und stärker ihre Buhlerei als ihre Schwester.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Und sie entbrannte gegen Assurs Söhne, die Fürsten und Satrapen, einen nach dem andern, die auf das prächtigste gekleidet waren, die Reiter, auf den Rossen reitend, und lauter Jünglinge von reizender Gestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Ich sah es, wie sie sich befleckte; sie gingen beide einen Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Doch trieb sie ihre Buhlerei noch weiter; sie sah da Männer, auf die Wand gemalt, die Bilder von Chaldäern, mit Mennige gemalt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'mit einem Gürtel um die Hüften, das Haupt mit einem Turban wohlbedeckt, sie allesamt wie Kriegsgewaltige anzusehen, den Söhnen Babels gleich, nach ihrem Vaterland genannt Chaldäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Beim ersten Blicke ihrer Augen ward sie schon liebetrunken gegen sie und sandte Boten hin zu ihnen nach Chaldäa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Da kamen Babels Söhne her zu ihr, zum Liebeslager, und sie bedeckten sie mit ihrer Buhlerei. Sie ließ sich gern durch sie beflecken und stillte ihre Lust an ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Da sie so offen Unzucht trieb und ihre Blöße enthüllte, riß ich meine Seele von ihr los, wie meine Seele sich von ihrer Schwester losgerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Doch trieb sie ihre Buhlerei noch weiter, und sie gedachte ihrer Jugendtage, da sie gebuhlt im Land Ägypten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'und da nach solchen Buhlen sie verlangte, die stark wie Esel waren, vollsaftig wie Hengste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Du sahst dich nach der Unzucht deiner Jugend um, wo die Ägypter deine Brust berührten und deinen jugendlichen Busen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Deshalb, Oholiba, spricht so der Herr: \'Fürwahr, jetzt reize ich die gegen dich, die mit dir Liebe pflogen, an denen du die Lüste stilltest, und führe sie von überall her gegen dich heran,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'die Söhne Babels, die Chaldäer all, Pekod und So und Ko, die Söhne Assurs insgesamt dabei, die Jünglinge von reizender Gestalt, die Fürsten und Satrapen insgesamt, Kriegsoberste und Aufgebotene, auf Rossen alle reitend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Dann kommen gegen dich Gewappnete mit Wagen und mit Fahrzeugen, mit einer Schar von Völkern, mit Tartschen, Schilden, Helmen, und lagern rings um dich. Dann überlaß ich ihnen selbst das Urteil, damit sie dich nach ihren eigenen Gesetzen richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Ich drücke jetzt den Stempel meiner Eifersucht dir auf, so daß sie grimmig dich behandeln dürfen. Sie schneiden dir die Nase und die Ohren ab. Dein Rest stürzt durch das Schwert. Sie schleppen deine Söhne, deine Töchter fort; was übrigbleibt von dir, wird durch das Feuer aufgefressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Sie ziehen dein Gewand dir aus und nehmen dir die Schmuckgeräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Ein Ende mache ich so deinem Lasterleben und deiner Buhlerei, die aus Ägypterlande stammt. Du schaust nicht mehr nach ihnen und denkst nicht weiter an Ägypten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'So spricht der Herr, der Herr: \"Ich geb dich in die Hände derer, die du heute nicht mehr magst, an denen du die Lüste stilltest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Sie werden dich mit Haß behandeln und dir alles nehmen, was du dir erworben. Sie lassen dich dann nackt und bloß daliegen, mit aufgedeckter Blöße, womit du Unzucht, Buhlerei und Hurerei getrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Dies widerfährt dir wegen deiner Buhlerei mit Heiden; mit ihren Abgöttern hast du dich schwer befleckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Auf deiner Schwester Weg bist du gewandelt; drum gebe ich dir ihren Becher in die Hand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So spricht der Herr, der Herr: \"Den Becher deiner Schwester mußt du leeren, so groß an Umfang und Gehalt, daß du zum Hohn und zum Gelächter wirst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Berauscht wirst du voll schmerzlicher Gefühle. Ein Becher zum Entsetzen und Erstarren ist der Becher deiner Schwester Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Den mußt du trinken, ihn ausschlürfen und seine Scherbe noch belecken, dabei die Brust zerfleischen. Ich droh\' dir\'s an.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, '\"Nun also\", spricht der Herr, der Herr, \"dieweil du mich vergessen, mich hintangesetzt, so büße du für deine Unzucht, deine Buhlerei!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Da sprach der Herr zu mir: \"O Menschensohn! Willst du mit Ohola und mit Oholiba nicht rechten? Halt ihnen ihre Greuel vor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'daß Ehebruch sie treiben, daß Blut an ihren Händen klebt, daß sie mit ihren Götzen Ehebruch getrieben, ja, daß sie ihre Söhne, die sie mir geboren, sogar zur Speise ihnen dargebracht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Auch das noch taten sie mir an, daß sie am selben Tag mein Heiligtum entweihten und meine Sabbate entheiligten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Denn schlachteten sie ihre Söhne ihren Götzen, betraten sie am selben Tage noch mein Heiligtum, und so entweihten sie\'s auf diese Art. So trieben sie\'s inmitten meines Hauses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Auch schickten sie nach Leuten, die aus der Ferne kommen sollten. Zu ihnen wurden Boten abgesandt; sie kamen, ihretwegen hast du dich gebadet und geschminkt die Augen und Schmuck dir angelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Dann setztest du dich auf ein Prachtbett nieder; davor stand ein gedeckter Tisch; auf diesen stelltest du mein Räucherwerk und Öl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Alsdann erscholl daran die Stimme einer frohen Menge; den Männern setzten Weibermassen Trockenweine vor, und diese legten jenen Spangen an die Arme und setzten schmucke Diademe auf ihr Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Da sagte ich von der im Ehebruch Verblühten: Jetzt treiben sie mit ihr noch Buhlerei, wie sie auch selber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Wie man zu einem buhlerischen Weibe geht, so gehen sie zu Ohola und Oholiba, zu den verbuhlten Weibern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Gerechte Männer aber werden über sie erkennen nach dem Gesetz für Ehebrecherinnen und für Mörderinnen. Denn Ehebrecherinnen sind sie ja; an ihren Händen klebt auch Blut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Denn also spricht der Herr, der Herr: \"Man rufe eine Volksversammlung wider sie zusammen und geb\' sie der Mißhandlung und Beraubung preis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Die Volksversammlung soll sie steinigen und mit den Schwertern niederhauen und ihre Söhne, ihre Töchter niedermetzeln und ihre Häuser niederbrennen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Der Unzucht mache ich im Land ein Ende, daß alle Weiber sich daraus zur Warnung nehmen, nicht so wie ihr zu buhlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Und haben sie euch mit der Strafe eurer Buhlerei belegt, und büßet ihr für euren Götzendienst, dann seht ihr ein, daß ich der Herr bin, ich, der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Das Wort des Herrn erging an mich am zehnten Tag des zehnten Monds im Jahre neun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '\"Merk, Menschensohn! Schreib diesen Tag genau dir auf, den heutigen Tag! Heut warf sich Babels König auf Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Trag nun dem Haus der Widerspenstigkeit ein Gleichnis vor und sprich zu ihnen: So spricht der Herr, der Herr: \'Setz einen Kessel auf! So setz ihn zu: Gieß Wasser ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Wirf Stücke Fleisch hinein, die besten Stücke von dem Fettschwanz, von den Lenden und den Schultern, und fülle ihn mit auserles\'nen Knochenstücken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Vom schönsten Vieh der Herde nimm! Im Kessel seien auch die Knochen! Laß seine Stücke sieden, daß selbst die Knochen darin kochen!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Denn also spricht der Herr, der Herr: \"Weh dieser Stadt der Blutschulden! Weh diesem Kessel, überdeckt mit Schmutz, aus dem der Schmutz nicht weichen will, der immer mehr an seinen Stücken Schmutz ansetzt! Man braucht ihn nicht mehr zu verlosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Ihr Blut ist mitten noch in ihr. Sie ließ es ja auf nackte Felsen fließen und goß es auf die Erde nicht, um es mit Staub zu decken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Um Zorn herbeizuführen, Rache zu erwecken, ließ ich ihr Blut auf nackte Felsen fließen, unbedeckt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Deshalb spricht so der Herr, der Herr: \"Weh dieser Stadt der Blutschulden! Nun leg ich selber einen großen Holzstoß aufeinander');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'und schüre durch ein zugelegtes Holz das Feuer, daß sich das Fleisch zerkoche, die Brühe überkoche und selbst die Knochen noch verkohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Den leeren Kessel laß ich auf den Kohlen stehen, damit sein Boden von der Hitze glühe, was unrein ist an ihm, zerschmelze, und so sein Schmutz verschwinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Die Glut erschöpft sich zwar; jedoch sein starker Schmutz weicht nicht aus ihm; sein Schmutz bleibt selbst im Feuer haften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Mit deinem Schmutz ist Störrigkeit gepaart. Ich will dich reinigen; du aber willst gar nicht gereinigt werden. Drum wirst du auch nicht rein von deinem Schmutz, bis Meinen Grimm ich abgekühlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ich selbst, der Herr, ich sag\'s, und es geschieht; ich führe aus und laß nicht nach. Ich bleibe schonungslos, erbarmungslos. Sie richten dich nach deinem Wandel, deinen Taten.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '\"Sieh, Menschensohn! Ich nehme deiner Augen Lust durch einen Schlag dir weg; du aber sollst nicht weheklagen und nicht weinen, und Tränen dürfen dir nicht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Im stillen seufze! Doch stell keine Totenklage an! Bind dir die Kopfbedeckung um! Zieh deinen Füßen Schuhe an! Verhüll den Bart dir nicht und iß kein Brot von andern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Ich sprach alsdann zum Volk am Morgen; am Abend vorher aber war mein Weib gestorben; am selben Morgen aber tat ich schon, wie mir befohlen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Da sprach das Volk zu mir: \"Willst du uns nicht erklären, was das bedeuten soll, daß du dich so benimmst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Ich sprach zu ihnen: \"Das Wort des Herrn ist so an mich ergangen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Sprich so zum Hause Israel: \'So spricht der Herr, der Herr: \"Mein Heiligtum entweihe ich, das Höchste eures Stolzes, und eure Augenlust und euer Kleinod. Und eure Söhne, eure Töchter stürzen hin, die ihr zurücklaßt, durch das Schwert zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Da tut ihr dann, wie ich getan. Ihr werdet nicht den Bart verhüllen und Brot von anderen nicht essen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'auf eurem Kopfe eure Kopfbedeckung, an euren Füßen eure Schuhe anbehalten. Ihr klaget nicht und weinet nicht. Verschmachtend ob der Strafe eurer Missetaten, seufzt ihr nur leise einer zu dem andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Zum Wahrzeichen dient euch Ezechiel. Ihr werdet alles tun, was er getan, wenn\'s kommt, und dann erkennen, daß der Herr, der Herr, ich bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Du aber, Menschensohn! Sieh, an dem Tag, da ich ihr Bollwerk ihnen raube, ihr herrlichstes Entzücken, ihr Kleinod, ihre Augenweide, die Söhne und die Töchter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'an jenem Tage, wenn ein Flüchtling dich besucht, der Schreie hören läßt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'an jenem Tage soll dein Mund sich gegen diesen Flüchtling öffnen; du sollst dann sprechen, nicht verschweigen, daß du zum Wahrzeichen für sie gedient, damit sie so erkennen, daß der Herr ich bin.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '\"Auf, Menschensohn! Dein Antlitz richte gegen Ammons Söhne und prophezeie gegen sie');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'und sprich: \'Über die Söhne Ammons vernehmt ein Wort des Herrn, des Herrn! So spricht der Herr, der Herr: \"Weil du im Hohne sprichst von meinem Heiligtum: \'Es ist entweiht\', vom Lande Israel: \'Es ist verwüstet\', vom Hause Juda: \'In die Verbannung ist\'s gewandert\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'drum geb ich dich des Ostens Söhnen zum Besitz, auf daß sie ihre Ringlager in dir errichten und ihre Wohnung in dir nehmen. Sie sollen deine Früchte essen und deine Milch austrinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Und zur Kameltrift mache ich Rabbat, das Land der Ammonssöhne zum Schaflagerplatz, daß ihr erkennt: Ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Denn also spricht der Herr, der Herr: \"Du klatschtest in die Hände und stampftest mit dem Fuße. Du freutest dich aus tiefstem Herzen über das Land Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Drum strecke ich die Hand aus gegen dich und gebe Heidenvölkern dich zur Beute und rotte aus dem Kreis der Nationen dich aus und laß dich aus den Völkern schwinden. Ich tilge dich, auf daß du innewerdest: Ich bin der Herr.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So spricht der Herr, der Herr: \"Weil Moab so wie Seïr spricht: \'Jetzt geht\'s dem Judahaus wie allen andern Heidenvölkern\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'deswegen übergebe ich nun Moabs Hang mit seinen Städten und seinem besten Teile. Das schönste Land, die Landschaft von Bet Jesimot, Baal Meon und Kirjataim');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'verleihe ich des Ostens Söhnen zum Besitz, zum Land der Söhne Ammons noch hinzu, damit der Name der Söhne Ammons bei der Heidenwelt erlösche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'So will ich auch an Moab ein Gericht vollziehn, damit sie innewerden, daß der Herr ich bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So spricht der Herr, der Herr: \"Am Judahaus hat Edom rachgierig gehandelt und sich dadurch verschuldet, weil es Rache an ihm nahm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, '\"Deshalb\", so spricht der Herr, der Herr, \"streck ich jetzt gegen Edom meine Hand aus und tilge Mensch und Vieh daraus und mache es zu einer Wüstenei von Teman bis nach Dedan. Sie stürzen durch das Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Ich gebe meine Rache an Edom in die Hände meines Volkes Israel. Nach meinem Zorn und Grimm tun sie mit Edom, daß es meine Rache fühlt.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So spricht der Herr, der Herr: \"Weil die Philister rachegierig handelten und tief verachtend Rache nahmen aus alter Feindschaft bis zur Ausrottung\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'darum spricht so der Herr, der Herr, \"ich strecke meine Hand aus wider die Philister, um die aus Kreta zu vernichten, den Rest am Meeresstrande zu vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Ich strafe hart und züchtige im Grimm, damit sie innewerden, daß ich der Herr, wenn ich an ihnen meine Rache nehme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Im elften Jahr, am ersten Tag des Mondes, erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '\"Hör, Menschensohn! Weil Tyrus ausrief: \'Ha, Jerusalem, Zerschmettert sind der Völker Pforten. Nun wendet sich mir alles zu. Ich blühe auf, weil sie in Trümmern liegt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Deshalb spricht so der Herr, der Herr: \'Fürwahr, ich will an dich, du Tyrus, und führe viele Heidenvölker gegen dich heran, wie sich das Meer erhebt in seinen Wellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Und Tyrus\' Mauern werden sie zerstören und seine Türme niederreißen. Dann fege ich den Schutt von seiner Fläche und mache es zu einem nackten Felsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Ein Trockenplatz für Fischernetze soll\'s am Meere werden. Ich sage es\', ein Spruch des Herrn, des Herrn. \'Der Heidenvölker Beute soll es werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Und seine Töchter auf dem festen Land, ermordet werden sie durchs Schwert, damit sie innewerden, daß ich der Herr.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Denn also spricht der Herr, der Herr: \'Fürwahr, ich bringe gegen Tyrus Babels König Nebukadrezar, von Norden her den König aller Könige mit Rossen, Wagen, Reitern und vielen Völkerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Er tötet mit dem Schwerte deine Töchter auf dem Lande, erbaut Belagerungstürme gegen dich und schüttet einen Wall auf rings um dich; Schilddächer stellt er gegen dich dann auf');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'und richtet seines Sturmbocks Stöße gegen deine Mauern und wirft mit seinen Kriegsgeräten deine Türme nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Der Staub von seiner Rosse Menge deckt dich zu; vom Rasseln seiner Reiter, seiner Wagenräder beben deine Mauern, wenn er in deine Tore dringt, so wie man einzieht in erstürmte Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Die Hufe seiner Rosse zerstampfen alle deine Gassen, und mit dem Schwerte tötet er dein Volk, und deine schönen Säulen stürzen auf den Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Sie plündern deine Schätze, rauben deine Handelsgüter, legen deine Mauern nieder, reißen deine Prachtgebäude ein und werfen deine Steine, Balken, deinen Schutt ins Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Und deinem Liederklange mache ich ein Ende, und deiner Zithern Ton wird nimmermehr gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Ich mache dich zum kahlen Felsen. Du wirst ein Trockenplatz für Fischernetze. Du wirst nie wieder auferbaut. Denn ich, der Herr, ich sage es.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So spricht der Herr, der Herr, von Tyrus: \'Erbeben nicht die Inseln von dem Dröhnen deines Niedersturzes, beim Stöhnen der Durchbohrten, bei dem Gemetzel, das in dir geschieht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Herab von ihren Thronen steigen des Meeres Fürsten alle; sie legen ihre Mäntel ab und ziehen ihre buntgestickten Kleider aus und hüllen sich in Bußgewänder und setzen sich zu Boden und zittern unaufhörlich, entsetzen sich gewaltig über dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Sie stimmen über dich ein Klaglied an und werden von dir sagen: \"Wie bist du doch zugrundgerichtet, Stadt des grauen Altertums, du hochgepriesene Stadt, so mächtig auf dem Meer, samt deinen Bürgern, die alle seine Anwohner erzittern machte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Am Tage deines Sturzes bebt die Küste; des Meeres Inseln sind ob deines Untergangs bestürzt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Denn also spricht der Herr, der Herr: \'Ich mache dich jetzt zur zerstörten Stadt, den Städten gleich, die unbewohnbar sind. Ich laß die See dich überströmen, daß dich die Wassermassen ganz bedecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Ich stürze dich hinab zu denen, die zur Grube fuhren, hinab zu Völkern früherer Zeiten. Ich weise in den Tiefen dir der Erde eine Wohnung an bei Trümmern aus der alten Zeit, bei denen, die zur Grube fuhren, daß du nicht weiter lebst. Im Lande der Lebendigen erwecke ich Gejauchze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Ich mache dich zum Schrecken; du bist nicht mehr. Du wirst gesucht, jedoch in Ewigkeit nicht mehr gefunden.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '\"Stimm, Menschensohn, ein Klagelied jetzt über Tyrus an');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'und sprich: \'Von Tyrus, das an Meereshäfen liegt, nach vielen Küstenländern mit den Völkern Handel treibend\', so spricht der Herr, der Herr: \'Du, Tyrus, sprichst: \"Ich bin ein wunderschönes Schiff.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Wohl liegt dein Reich im Herzen da des Meeres; schön, vollendet schön erschufen dich, die dich gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Sie machten aus Zypressen vom Senir dir alle Planken. Sie holten Zedern von dem Libanon und machten dir daraus Mastbäume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Und deine Ruder machten sie aus Basanseichen und dein Verdeck aus Elfenbein und Fichtenholz von den Kittiterinseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Gestickter Byssus aus Ägypten war dein Segel; dir diente blauer Purpur für die Wimpel, und roter von Elisas Inseln war dein Dach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Sidons und Arvads Leute bedienten dich als Ruderer, und deine Steuermänner, Tyrus, waren deine Allertüchtigsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Die Ältesten und Kunstverständigen aus Gebal, sie besserten dir deine Lecke aus. Die Meeresschiffe all und ihre Führer begaben sich zu dir zum Tausche deiner Waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'In deinem Heere dienten Paras, Lydier und Put als Krieger; sie hängten Schild und Helme bei dir auf, verhalfen dir zum Ruhm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Die Söhne Arvads bildeten dein Heer auf deinen Mauer ringsumher, Kimmerier auf deinen Türmen mit ihren Schilden rings um deine Mauern; sie machten deine Pracht vollkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Und Tarsis handelte mit dir all deines großen Reichtums wegen; sie brachten Silber, Eisen, Zinn und Blei auf deinen Markt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Die Griechen, Tibarener, Moscher handelten mit dir; sie lieferten als Ware Menschen dir und eherne Geräte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Die von Togarmas Hause lieferten auf deinen Markt nebst Rossen Reitpferde und Maultiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Die Söhne Dedans handelten mit dir, und viele Küstenländer waren deinem Handel günstig; sie brachten Elfenbein und Ebenholz zum Umtausch deiner Waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Auch Edom handelte mit dir, herbeigelockt durch deine zahlreichen Erzeugnisse. Rubinen, Purpur, bunte Stickereien und Byssus und Korallen sowie Jaspis brachten sie auf deinen Markt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Das Land von Israel und Juda trieb mit dir Handel. Den besten Weizen und Gebäck und Honig, Öl und Mastix brachten sie auf deinen Markt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus handelte mit dir, herbeigelockt durch deine zahlreichen Erzeugnisse und durch die Menge der verschiedenen Güter, in Wein von Helbon und in blendend weißer Wolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Wedan und Javan brachten aus Uzal für deinen Markt geschmiedet Eisen, Kassia und Zimt für dich als Tauschwaren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Und Dedan handelte mit dir in Pferdesatteldecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien und alle Kedarfürsten, sie waren deine liebsten Händler, verhandelten dir Lämmer, Widder, Böcke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Die Kaufleute von Seba und von Rema handelten mit dir. Die besten Sorten Balsam, Gold und Edelsteine brachten sie auf deinen Markt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran, Kanne und Eden trieben mit dir Handel und Sebas Händler und Assur und Kulmadara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Sie handelten mit dir in Prachtgewändern, in purpurblauen und gestickten Mänteln, mit einem Schatz von Kleidern, die sie, mit Stricken fest gebunden, auf deine Handelsplätze brachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Die Tarsisschiffe nahmen ersten Rang in deinem Handel ein. So wurdest du mit Schätzen angefüllt, im Meere überreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Dich brachten auf die hohe See, die deine Ruder führten. Da hat ein Sturmwind auf dem Meere dich zerschmettert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Dein Reichtum, deine Kaufmannsgüter, deine Waren, dein Schiffsvolk, deine Steuermänner, die deine Lecke besserten und deine Waren tauschten, und was zum Volk in dir gehörte, das fiel ins Meer am Tage, da du untergingest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Vom lauten Schreien deiner Steuermänner erdröhnten selbst die Schiffsrippen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Aus ihren Schiffen stiegen alle, die Ruder führten. Das Schiffsvolk, alle Steuermänner, gingen an das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Sie ließen laute Klage über dich erschallen, erhoben bitteres Wehgeschrei und warfen Staub auf ihre Häupter und wälzten sich in Asche');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'und schoren sich um deinetwillen Glatzen und legten Trauerkleider an und weinten über dich betrübten Herzens, in bitterer Trauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Sie stimmten schluchzend über dich ein Klaglied an, wehklagten über dich: \"Was gleicht nur Tyrus, mittendrin im Meere liegend?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Als deine Handelswaren aus den Meeren kamen, verschafftest du den vielen Völkern Speise. Durch deine vielen Güter, deine Waren hast du der Erde Könige bereichert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nun bist du auf dem Meer gescheitert, auf des Wassers Tiefen. Dahin dein Handel und dein ganzes Volk in dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Und alle, die auf jenen Inseln wohnen, staunen über dich, und ihre Könige befällt ein Schauder, und sie zerschlagen sich das Angesicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Die bei den Völkern mit dir handelten, sie zischen über dich. Zum Schreckensbild bist du geworden, für alle Zeit dahin.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '\"Sprich, Menschensohn! Sprich so: \'Vom Tyrusfürsten spricht der Herr, der Herr, also: Du sagst im Übermut. \"Ein Gott bin ich. Auf einem Göttersitz im Herzen des Meeres wohne ich\", obgleich du nur ein Mensch bist und kein Gott. Du meinst, der Weisheit eines Gottes sei die deine gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Sieh, du bist weiser noch als Daniel, und kein Geheimnis ist vor dir verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Durch deine Weisheit, deine Klugheit erwarbst du Reichtum dir und schafftest Gold und Silber her in deinen Schatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Dank deiner Klugheit Fülle mehrtest du durch deinen Handel deinen Reichtum, und übermütig ward dein Sinn durch deine Schätze.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Deshalb spricht so der Herr, der Herr: \'Du meintest, eines Gottes Weisheit sei die deine gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Drum führ ich über dich jetzt Fremdlinge herbei, der Heidenvölker Wildeste. Die zücken ihre Schwerter gegen deiner Klugheit Wohnstätte, vernichten deinen Glanz');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'und stürzen dich zur Grube, daß du den Tod Erschlagener sterbest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Wirst du vor deinen Henkern dann noch sagen: \"Ich bin ein Gott\"? Du bist dann nur ein Mensch, kein Gott, wenn du dich in der Mörder Hand erblickst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Den Tod der Nackten sollst du leiden durch fremde Hand. Ich sage es.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '\"Ach Menschensohn! Ein Klagelied heb über Tyrus\' König an und sprich: So spricht der Herr, der Herr, von ihm: \'Ein Muster bist du und ein Ausbund voller Weisheit, an Schönheit ganz vollkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'In einem Eden, einem Gottesgarten, wohntest du und warst bedeckt mit mannigfachen Edelsteinen, mit Karneol, Topas, Beryll, mit Goldstein, Onyx und mit Jaspis, mit Saphir und Rubin, Smaragd und Gold, mit Werken deiner Künstler und Metallbearbeiter, die an dem Tage deines Werdens in Bereitschaft standen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ich machte dich dem Cherub ähnlich, der das Verschlossene behütet. Du warst auf einem Gottesberge und wandeltest inmitten dort von Feuersteinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Du schienst in deinem Wandel tadellos zu sein vom Tage deines Werdens an, bis daß man schließlich Schlechtigkeit an dir entdeckte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Durch deinen großen Handel sind deine Schatzkammern mit ungerechtem Gut gefüllt. Und du begingst Verfehlungen. Da warf ich dich vom Gottesberg herab, gab dich, den Schutz-Cherub bei Feuersteinen, dem Untergange preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Hochfahrend war dein Sinn durch deine Schönheit. So hast du deine Weisheit dir verdorben um deines Glanzes willen. Da warf ich dich zu Boden und gab dich Königen zur Augenweide preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Durch deiner Frevel Menge, durch die VerschuIdungen bei deinem Handel hast du dein Heiligtum entweiht. Ich ließ hervor aus deiner Mitte Feuer brechen; dich fraß es auf. Ich machte auf der Erde dich zu Staub im Angesichte aller, die dich sahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Und alle, die dich kannten bei den Völkern, staunten über dich. Zum Schreckgespenst bist du geworden und bist für alle Zeit dahin.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '\"Nun, Menschensohn! Dein Antlitz richte gegen Sidon! Und weissage dagegen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Und sprich: So spricht der Herr, der Herr: \'Ich will an dich, du Sidon; gekränkte Ehre räche ich an dir, damit man innewerde: Ich bin der Herr; an ihm vollziehe ich die Strafgerichte und zeige mich an ihm als Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Ich sende Pest dawider und Blut in seine Gassen. Erschlagne stürzen darin nieder durch das Schwert, von überall dagegen wütend, auf daß man innewerde, daß ich der Herr bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Für das Haus Israel gibt\'s keinen Stachel mehr, der es verwundet, und keine Dornen, die es schmerzen, bei allen seinen Nachbarn, die es anfielen, damit sie innewerden, daß ich der Herr, der Herr.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So spricht der Herr, der Herr: \'Wenn ich das Haus von Israel einst aus den Völkern sammle, worunter es zerstreut, dann zeige ich an ihnen vor den Augen der Heiden mich als Heiligen; dann sollen sie ihr Land bewohnen, das ich verliehen habe meinem Knechte Jakob.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Sie sollen sicher in ihm wohnen und Häuser bauen, Weinberge anpflanzen. Sie sollen sicher wohnen, wenn ich an allen ihren Nachbarn, die sie angefallen, die Strafgerichte dann vollstrecke, damit sie innewerden: Der Herr, ihr Gott, bin ich.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Am zwölften Tag des zehnten Monds im Jahre zehn erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '\"Du, Melischensohn! Dein Antlitz richte gegen Pharao, Ägyptens König, und prophezeie gegen ihn und gegen ganz Ägypten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Und sprich: So spricht der Herr, der Herr: \'Ich will an dich, du Pharao, Ägyptens König, großes Krokodil, das mitten drin in seinen Strömen lagert und das gesagt: \"Mein ist mein Strom; ich schuf ihn mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Ich lege Haken jetzt in deine Kinnbacken und lasse deines Stromes Fische sich an deine Schuppen hängen; dann zieh ich dich aus deinem Strome mit all den Fischen deines Stromes, die fest an deinen Schuppen hängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Ich werfe dich und alle Fische deines Stromes alsdann in die Wüste. Da bleibst du auf dem Felde liegen, nicht weggebracht, nicht aufgehoben. Dem Wild des Feldes und des Himmels Vögeln bestimme ich dich dann zum Fraß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'damit, die in Ägypten wohnen, innewerden: Ich bin der Herr. Sie waren für das Haus von Israel ein Rohrstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Wenn sie an deiner Hand dich faßten, so knicktest du zusammen, zerrissest ihnen ihre Schultern. Wenn sie auf dich sich stützten, gingst du in Stücke und machtest ihnen Schmerzen in der ganzen Hüfte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Deshalb spricht so der Herr, der Herr: \'Ich bringe nun ein Schwert für dich und rotte Vieh und Menschen bei dir aus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'daß das Ägypterland zur öden Wüste werde, damit sie innewerden: Ich bin der Herr. Gesagt hat es: \"Mein ist der Strom und mein die Flotte, die ich aufgestellt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Deshalb will ich an dich und deinen Strom und mache das Ägypterland zur öden Wüste, von Migdol bis Syene hin, bis an Äthiopiens Grenzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Kein Mensch soll\'s mehr durchwandern, nicht eines Tieres Fuß. Es bleibe vierzig Jahre unbewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Ich mache das Ägypterland zur Wüste im Vergleich mit andern öden Ländern, und seine Städte liegen wie die andern öden Städte vierzig Jahre wüst. Zerstreuen will ich die Ägypter unter Heiden, und in die Länder hin versprenge ich sie jetzt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Doch also spricht der Herr, der Herr: \'Nach vierzig Jahren sammle ich aus jenen Völkern die Ägypter wieder, wo sie in Zerstreuung lebten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Ich führe die gefangenen Ägypter wiederum zurück und bring sie nach dem Patrosland, nach ihrem Ursprungsland. Sie bilden dort jedoch ein schwaches Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Den andern Reichen gegenüber ist es schwach, damit sich\'s nimmer gegen Heidenvölker brüste. Ich mache sie ganz unbedeutend, damit sie nimmer über andere Heidenvölker herrschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Das Haus von Israel vertraut fortan nicht mehr auf sie, der Schuld gedenkend, daß sie einst sich ihnen angeschlossen. So werden sie erkennen: Ich bin der Herr, der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Am ersten Tag des ersten Monds im Jahre siebenundzwanzig erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '\"Du Menschensohn! Nebukadrezar, Babels König, verlangte gegen Tyrus schweren Dienst von seinem Heer. Ein jeder Kopf ist kahl geworden und jede Schulter abgeschunden. Von Tyrus selbst ward ihm und seinem Heer kein Lohn für den daselbst vollzognen Dienst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Deshalb spricht so der Herr, der Herr: \"Ich übergebe das Ägypterland dem Babelkönig, dem Nebukadrezar, auf daß er seinen Reichtum an sich nehme, raube, plündere, dies zur Belohnung für sein Heer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Als seinen Sold, um den es Dienst getan, will ich ihm das Ägypterland einräumen, weil sie für mich beschäftigt waren.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, '\"An jenem Tage führe ich das Haus von Israel zu neuer Macht und öffne dir bei ihnen wieder deinen Mund, damit sie innewerden: Ich, ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '\"Sprich, Menschensohn! Weissage, sprich: \'So spricht der Herr, der Herr: \"Wehklaget: ach der Tag!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Ein Tag ist nah; ein Tag vom Herrn ist nah, ein trüber Tag und eine Zeit, voll von Verhängnis für die Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Ein Schrecken dringt bis nach Ägypten; und Äthiopien befällt ein Zittern, wenn in Ägypten die Erschlagnen liegen, und wenn man seine Schätze plündert und einreißt seine Grundfesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Ja, Äthiopien und Put und Lud und alle Araber und Kub, sowie die Söhne von Berytus fallen durch das Schwert mit ihnen.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So spricht der Herr: \"Ägyptens Stützen sinken hin, und seine stolze Pracht stürzt nieder; von Migdol bis Syene fallen sie durchs Schwert.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, '\"Sie sollen im Vergleich mit andern öden Ländern erst recht verwüstet werden, und seine Städte im Vergleich zu andern öden Städten erst recht öde werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'damit sie innewerden: Ich bin der Herr, wenn ich das Feuer an Ägypten lege und seine Helfer all zerschmettert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'An jenem Tage reisen Boten nach meiner Anordnung auf Schiffen, um Äthiopien in seiner Ruhe aufzuschrecken. Und Zittern wird daselbst entstehn am Tag Ägyptens. Denn sieh, es kommt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So spricht der Herr, der Herr: \"Die große Volkszahl in Ägypten mindre ich durch Babels König Nebukadrezar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Er und sein Volk mit ihm, die wildesten der Heidenvölker werden hergeführt, um diese Lande zu vernichten. Sie ziehen ihre Schwerter gen Ägypten und füllen mit Erschlagenen das Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Ich lege Ströme trocken und überliefere das Land in die Gewalt von Schlimmen: Das Land zerstöre ich durch Fremder Hand und was es füllt: Ich sag\'s dir, ich, der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So spricht der Herr, der Herr: \"Zertrümmern will ich ihre Götterbilder, die Abgötter aus Memphis tilgen. Und einen Fürsten aus Ägypten gibt\'s nicht mehr. Ich werde Schrecken im Ägypterland verbreiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Verwüsten will ich Patros, an Tanis Feuer legen und Strafen über No verhängen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'und gießen will ich meinen Ingrimm über Sin, Ägyptens feste Stadt; das völkerreiche No vertilge ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Ich lege an Ägypten Feuer. Erzittre, Sin, und bebe! Erstürmt werd\' No! Am hellen Tage komme Schrecken über Memphis!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Die Jünglinge von On und von Bubastis fallen durch das Schwert, und ihre Jungfraun wandern in Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Zu Tachpanches verfinstert sich der Tag, wenn ich Ägyptens Zepter dort zerbreche, wenn dort ein Ende seiner stolzen Pracht bereitet wird. Gewölk bedeckt es, und seine Töchter ziehen in Verbannung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'So werde ich Gericht ausüben an Ägypten, damit sie innewerden: Ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Am siebten Tag des ersten Monds im Jahre elf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '\"Du Menschensohn! Des Pharao, des Königs von Ägypten, Arm zerbreche ich. Er wird zum Heilen nicht gebunden und kein Verband ihm angelegt, um wieder fest zu werden, daß er das Schwert aufs neue führen könnte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Deshalb spricht so der Herr, der Herr: \"Ich will an Pharao, Ägyptens König; ich breche seine Arme, den gesunden und den gebrochenen, und lasse seiner Hand das Schwert entfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Und ich zerstreue unter andre Heiden die Ägypter, und ich zersprenge sie in andre Länder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Dagegen stärke ich des Babelkönigs Arme und drücke diesem in die Hand mein Schwert. Die Arme Pharaos zerbreche ich dagegen, auf daß er vor ihm ächzen möge wie ein Verwundeter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Des Babelkönigs Arme aber stärke ich; die Arme Pharaos dagegen sinken nieder, damit sie innewerden: Ich bin der Herr, wenn ich mein Schwert der Hand des Babelkönigs überlasse, daß er es schwinge gegen das Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Und ich zerstreue unter Heiden hin Ägypten, und ich versprenge sie in andre Länder, damit sie innewerden: Ich, ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Am ersten Tag des dritten Monds im Jahre elf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '\"Sprich, Menschensohn, so sprich nun zu Ägyptens König, Pharao, sowie zu seinem großen Volke: \'Wem dünkst du dich in deiner Größe gleich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Assyrien, der Zeder auf dem Libanon, der schöngeästeten, der schattenspendenden, der ragenden, mit hochgerecktem Wipfel zwischen Baumkronen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Das Wasser hatte diese großgezogen, das Meer sie hochgebracht, das seine Ströme rings um ihre Pflanzstatt fließen ließ, das sonst Kanäle bloß zu andern Bäumen auf dem Felde sandte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'So überragte denn ihr Wuchs den aller andern Bäume auf dem Feld. So wurden ihre Zweige stark und ihre Äste lang vom reichen Wasser in den Rinnsalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'In ihren Zweigen nisteten des Himmels Vögel alle, und unter ihrer Krone warf auch allerlei Getier des Feldes. In ihrem Schatten wohnten manche starken Heidenvölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Und schön war sie in ihrer Größe durch ihrer Zweige Länge; denn ihre Wurzel stand an vielem Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Im Gottesgarten kamen andre Zedern ihr nicht gleich; in ihren Zweigen glichen ihr Zypressen nicht. Platanen waren gegen ihre Äste nichts; kein Baum war ihr an Schönheit gleich im Gottesgarten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Gar herrlich hab ich sie gemacht in ihrer Zweige Fülle. Im Gottesgarten neideten sie alle Bäume Edens.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Doch sprach der Herr, der Herr: \'Weil sie an Wuchs so hoch geworden, und weil sie ihren Wipfel in die Wolken streckte, und weil sie so auf ihre Größe stolz geworden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'drum gab ich sie dem mächtigsten der Heidenvölker preis, daß sie an ihr entsprechend ihrer Schlechtigkeit verfuhren, sie, die ich doch wachsen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Da haben Fremde sie gefällt und hingeworfen, die Wildesten der Heidenvölker. Auf Berge und in Täler fielen ihre Zweige überall. Zerbrochen lagen ihre Äste in allen Bachtälern des Landes, und alle Erdenvölker zogen fort aus ihrem Schatten und ließen sie so liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Des Himmels Vögel alle saßen auf ihrem umgeworfnen Stamm; an ihre Äste kamen alle Tiere des Feldes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'daß kein Baum am Wasser ferner stolz auf seine Höhe sei und nicht emporstrecke den Wipfel zwischen Baumkronen, daß keiner, der dort Wasser trinkt, um ihre Höhe sie anfeinde. Sie alle sind zum Tode für die Unterwelt bestimmt, gerade so wie andre Menschen, die zur Grube wandern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So spricht der Herr, der Herr: \'Am Tag, da ich sie ließ ins Schattenreich fortziehen, da brachte ich den Ozean in Trauer ihrethalb und ließ ihn sich verhüllen. Und seine Ströme hielt ich an; die vielen Wasser hörten auf zu fließen. Ich hüllte ihretwegen auch den Libanon in Schwarz; des Feldes Bäume all verhüllten sich um sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Durch ihres Falles Lärm erschreckte ich die Heidenvölker, als ich sie in die Unterwelt versetzte zu denen, die zur Grube fuhren. Und alle Bäume Edens trösteten sich in der Erde Tiefen, die auserlesensten des Libanon, die Wasser tranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Sie waren jetzt mit ihr zusammen in der Unterwelt bei denen, die durchs Schwert erschlagen wie ihre Helfer aus der Heidenwelt, die einst in ihrem Schatten weilten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Wem glichest du an Pracht und Größe unter Edens Bäumen? Nun fahre selbst hinab zu Edens Bäumen in der Erde Tiefen! Inmitten Nackter sollst du liegen, bei den Schwertdurchbohrten. Das ist des Pharao Geschick und seines großen Volkes.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Am ersten Tag des zwölften Monds im Jahre zwölf erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '\"Klag, Menschensohn! Ein Klagelied stimm an auf Pharao, Ägyptens König, und sprich zu ihm: \'Du hieltest dich für einen Jungleu bei den Heiden und bist doch wie die Drachen in den Meeren. Du stürztest dich in deine Ströme und trübtest das Gewässer mit den Füßen und wühltest seine Strömung auf.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So spricht der Herr, der Herr: \'Ich breite über dich mein Netz in einer Schar von vielen Völkern, daß sie dich in meinem Garne in die Höhe ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Dann werfe ich dich auf das Land und strecke dich aufs freie Feld, so lang du bist, und lasse alle Vögel des Himmels auf dir weilen und sich an dir das Wild der ganzen Erde sättigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Dein Fleisch verstreu ich auf den Bergen überall und fülle Täler an mit deinen Würmern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Das Land, in dem du schwimmst, das tränke ich mit deinem Blut bis zu den Bergen; Rinnsale werden von dir ausgefüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Wenn ich dich so erlöschen mache, alsdann verhülle ich den Himmel, und seine Sterne kleide ich in Schwarz. Die Sonne überziehe ich mit Wolken, und nicht mehr gibt der Mond sein Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Die Lichter all am Himmel kleide ich in Schwarz um deinetwillen und lasse Finsternis in deinem Land entstehen.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, '\'Ich mache vieler Völker Herz bekümmert, wenn ich die Kunde deines Untergangs hin zu den Heiden kommen lasse, in Länder, die du niemals kanntest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Ich setze viele Völker in Erstaunen über dich, und über dich erschauern ihre Könige, wenn ich mein Schwert vor ihrem Antlitz schwinge. Sie zittern immerfort am Tage deines Sturzes.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Denn also spricht der Herr, der Herr: \'Das Schwert des Babelkönigs soll dich treffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Durch Kriegerschwerter werf ich deine große Menge nieder. Die Wildesten der Heiden sind es insgesamt; Ägyptens Glanz vernichten sie. Sein großes Volk geht unter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Vernichten will ich all sein Vieh an großen Wassern; kein Menschenfuß soll sie mehr trüben, nicht trüben eines Rindes Klaue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Dann laß ich ihr Gewässer sinken, und ihre Ströme laß ich fließen wie das Öl.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, '\'Wenn ich das Land Ägypten dann verheert, das Land samt seiner Fülle ganz vernichtet, auch alle, die dort wohnen, umgebracht, dann werden sie erkennen: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Dies ist ein Klagelied, das man singt; der Heiden Töchter stimmen\'s an. Sie singen\'s auf Ägypten und sein großes Volk. Ein Spruch des Herrn, des Herrn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Im Jahre zwölf am fünfzehnten des Monds erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '\"Klag, Menschensohn! Ein Klagelied stimm auf das große Volk Ägyptens an! Begleite es mitsamt den Töchtern großer Völker zu der Unterwelt, zu denen, die zur Grube fuhren:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, '\'Warst du nicht herrlicher als irgendwer, herunter jetzt! Leg dich zu Nackten hin!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Bei den vom Schwert Erschlagenen sollen sie jetzt liegen - ein Schwert ist schon bestimmt -; man schleppt es hin mit seinem ganzen großen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Anreden werden es die ersten Helden aus der Unterwelt samt seinen Helfern, die herabgestiegen und ihr Lager eingenommen, die Nackten, die vom Schwert Erschlagenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Hier liegt Assyrien; sein zahlreich Volk liegt um sein Grab. Sie alle sind Erschlagene, durchs Schwert Gefallene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Ihm ist sein Grab bereitet in dem innern Teil der Gruft; sein zahlreich Volk liegt um sein Grab herum. Sie alle sind Erschlagene, durchs Schwert Gefallene, die einst Schrecken verbreiteten im Lande der Lebendigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Hier liegt auch Elam und sein ganzes großes Volk rings um sein Grab. Sie alle sind Erschlagene, durchs Schwert Gefallene. Sie sind zur Unterwelt hinabgefahren nackt, die einstens Schreck verbreiteten im Lande der Lebendigen. Sie tragen nun die Schmach dafür bei denen, die zur Grube fuhren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Inmitten von Erschlagenen ward ihm sein Lager angewiesen mit seinem ganzen, großen Volke; um ihn herum ihr Grab. Sie alle sind nur Nackte, Schwertdurchbohrte. Weil sie im Lande der Lebendigen ein Schrecken waren, so tragen sie die Schmach dafür bei denen, die zur Grube fuhren. Jetzt wird\'s zu den Erschlagenen gezählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Hier ist Mesech, Tubal, sein ganzes großes Volk und rings um ihn sind seine Gräber; sie alle sind nur Nackte, Schwertdurchbohrte. Weil sie einst Schrecken um sich her verbreiteten im Lande der Lebendigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'drum liegen sie nicht bei der Vorzeit Helden, die hinter jenen Nackten ruhen, die mit den Waffen in den Händen zur Unterwelt hinabgestiegen, die ihre Schwerter unter ihre Häupter legten, und deren Leib ein Schild bedeckt. Sie waren ja ein Schrecken für die andern Helden im Lande der Lebendigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Auch du bist unter Nackte hingeworfen und liegst bei Schwertdurchbohrten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Hier ist auch Edom, seine Könige, all seine Fürsten, die zu den Schwerterschlagenen trotz ihrer Tapferkeit geraten sind. Sie liegen bei den Nackten, bei den ins Totenreich Gewanderten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Dort liegen alle Fürsten aus dem Norden und alle die Sidonier, zu den Erschlagenen herabgestiegen, trotz ihrer fürchterlichen Tapferkeit mit Schmach bedeckt. Sie liegen nackt bei jenen Schwertdurchbohrten und tragen ihre Schmach samt andern Schatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Wenn diese Pharao erblickt, dann tröstet er sich wegen seines ganzen großen Volkes. Denn Schwertdurchbohrte sind der Pharao sowie sein ganzes Heer.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, '\"Ja, Schrecken ließ ich über ihn verbreiten im Lande der Lebendigen. Nun liegt er zwischen Nackten hingestreckt und zwischen Schwertdurchbohrten, der Pharao und alle seine Scharen.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '\"Sprich, Menschensohn! Sprich so zu deines Volkes Söhnen! Und sage ihnen: \'Wenn ich Krieg verhänge über eine Gegend und wenn des Landes Volk sich einen Mann aus seinen Tüchtigsten erwählt, den es zum Wächter sich bestellt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'und dieser sieht das Schwert dem Lande nahen und stößt ins Lärmhorn, warnt das Volk');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'und dieses hört des Lärmhorns Schall, doch horcht es auf die Warnung nicht; wenn dann das Schwert erscheint und reibt es auf, dann ist\'s allein an seinem Tode schuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Des Lärmhorns Schall hat es gehört. Wenn es sich hätte warnen lassen, dann hätte es sich retten können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Wenn zwar der Wächter kommen sieht ein Schwert, doch nicht in die Trompete stößt, wird nicht das Volk gewarnt und kommt alsdann ein Schwert und rafft von ihnen einen weg, so wird zwar dieser wegen seiner Schuld hinweggerafft; doch von dem Wächter fordere ich sein Blut.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Dich aber, Menschensohn, dich habe ich zum Wächter für das Haus von Israel bestellt. Aus meinem Mund hörst du ein Wort. Verwarne sie damit von meiner Seite aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Wenn ich vom Frevler sage: \'Du Frevler, du mußt sterben\', und sagst du nichts, um so von seinem Tun den Bösen abzumahnen, so stirbt der Böse selber zwar für seine Sünde; sein Blut jedoch verlange ich von deiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Hast du den Bösen aber wohl vermahnt, von seinem Wege umzukehren, er kehrt sich aber nicht von seinem Wandel, so stirbt er zwar für seine Sünde; du aber hast dich selbst gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Du, Menschensohn, sprich so zum Hause Israel: \'Ihr sagt ganz richtig: \"Die Sündenschulden und die Strafen drücken uns; wir schwinden durch sie hin. Wie können wir noch weiter leben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'So sprich zu ihnen! So wahr ich lebe\', ein Spruch des Herrn, des Herrn. \'ich habe kein Gefallen an des Bösen Tod, nein, daran aber, daß der Böse sich von seinem Wege kehre und dadurch lebe. Kehrt um von euren schlimmen Wegen! Was wollt ihr sterben, Haus von Israel?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Du aber, Menschensohn, so sprich zu deines Volkes Söhnen: \'Die Frömmigkeit kann nicht den Frommen retten, sobald er sich vergeht. Das schlimme Leben aber läßt den Bösen nicht am Boden liegen bleiben, sobald er sich von seinem schlimmen Leben wendet. Der Fromme aber kann nicht weiterleben, sobald er sich versündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Wenn ich dem Frommen sage, er darf leben bleiben, er aber tut, auf seine Frömmigkeit vertrauend, Böses, dann wird nicht einer seiner frommen Taten mehr gedacht, und er muß sterben für das Böse, das er tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Wenn ich zum Bösen sage: \"Du mußt sterben\", und er bekehrt sich von der Sünde und tut, was Recht ist und Gerechtigkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'und gibt er ungerechte Pfänder wieder her, erstattet das Geraubte und wandelt nach den lebenspendenden Geboten, und übt er keinen Frevel mehr, darf er am Leben bleiben und braucht nicht zu sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Und keine seiner Sünden, die er tat, wird ihm noch angerechnet. Er hat getan, was recht war und gerecht. So darf er weiter leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Zwar sprechen deines Volkes Söhne: \"Des Herrn Verfahren ist nicht in der Ordnung\", und doch ist nur das ihre nicht in Ordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Wenn je ein Frommer läßt von seinem frommen Wandel, und er erlaubt sich Frevel, muß er dafür sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Und läßt ein Böser ab von seinem schlimmen Wandel und tut, was recht ist und gerecht, so bleibt er gegen jene Ansicht doch am Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Da mögt ihr sagen: \"Des Herrn Verfahren ist nicht in der Ordnung\"; ich richte einfach jeden unter euch nach seinem Wandel, o Haus Israel.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Am fünften Tag des zehnten Monds im zwölften Jahre unserer Verbannung, da kam ein Flüchtling zu mir her mit Kunde aus Jerusalem: \"Die Stadt ist eingenommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Des Herren Hand kam über mich an jenem Abend, ehe der Entflohene erschien. Er hatte mir den Mund schon aufgeschlossen, als dieser erst am andern Morgen zu mir kam. So ward der Mund mir aufgetan; ich blieb nicht länger stumm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Das Wort des Herrn erging alsdann an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '\"Sieh, Menschensohn! Wer in dem Lande Israel auf diesen öden Trümmern wohnt, der sagt: \'Ein einzelner war Abraham, als er das Land zum Eigentum bekam; nun sind es aber unser viele. Drum muß uns um so mehr das Land zum Eigentum gegeben sein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Deshalb sprich so zu ihnen: Also spricht der Herr, der Herr: \'Ihr esset Blutiges und schlagt zu euren Götzenbildern eure Augen auf, vergießet Blut. So wollt ihr im Besitz des Landes bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ihr stützet euch auf euer Schwert, verübet Greueltaten, beflecket gegenseitig eure Weiber! Da wollt ihr im Besitz des Landes bleiben?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Sprich dann zu ihnen: So spricht der Herr, der Herr: \'So wahr ich lebe! Die in den Trümmern wohnen, fallen durch das Schwert. Die auf dem platten Lande wohnen, gebe ich dem Wild zum Fraß, und die auf Felsenklippen und in Höhlen, sterben an der Pest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Zur öden Wüste mache ich das Land. Mit seiner stolzen Hoffart hat\'s ein Ende, und Israels Gebirge soll kein Wanderer durchziehen, so öde wird es sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Dann werden sie erkennen, daß ich der Herr, wenn ich das Land zur öden Wüste mache, um aller ihrer Greuel willen, die sie taten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Du, Menschensohn! In ihren Häusern reden über dich die Söhne deines Volkes, und an den Türen der Häuser redet einer zu dem andern, ein Nachbar zu dem anderen: \'Herbei! Und hört, was für ein Ausspruch von dem Herrn ergeht!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'So kommen sie zu dir gleich einem Haufen Leute und setzen sich vor dich, als wären sie mein Volk, und hören deine Worte an. Doch tun sie nicht danach; denn sie bewundern sie nur mit dem Mund; ihr Herz läuft aber ihren Lüsten nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Was so ein Liebessänger ist, der eine schöne Stimme hat und gut die Saiten spielt, das bist du ihnen. Sie hören deine Worte an; doch handeln sie nach ihnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Wenn\'s aber kommt, und es kommt sicher, dann werden sie erkennen, daß bei ihnen ein Prophet geweilt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '\"Hör, Menschensohn! Weissage gegen diese Hirten Israels! Weissage, sprich: So spricht der Herr, der Herr, von diesen Hirten: \'Weh diesen Hirten Israels, die sich allein geweidet haben! Sollen die Hirten nicht ihre Herde weiden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Ihr aßet Milch und hülltet euch in Wolle. Ihr schlachtetet das Mastvieh; die Schafe aber mochtet ihr nicht hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Das Schwache mochtet ihr nicht warten und nicht das Kranke heilen und das Gebrochne nicht verbinden und das Verlorene nicht wiederbringen, nicht suchen das Verirrte, und über die Gesunden habt mit Härte ihr geherrscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Sie hatten keinen Hirten, deshalb wurden sie zerstreut und, alsobald zerstreut, von allem Wilde auf dem Feld gefressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Auf allen Bergen irrten meine Schafe, auf jedem hohen Hügel, und meine Schafe wurden auf dem platten Land zerstreut. Doch niemand kümmerte sich drum, und niemand suchte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Deshalb, ihr Hirten, hört das Wort des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'So wahr ich lebe\', ein Spruch des Herrn, des Herrn. \'Weil meine Schafe ohne Hirten zur Beute wurden, weil meine Schafe allem Wild des Feldes zum Fraße dienten, weil meine Hirten nicht nach meinen Schafen suchten, weil diese Hirten nur sich selber weideten, nicht aber meine Herde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'deshalb, ihr Hirten, hört das Wort des Herrn\':');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So spricht der Herr, der Herr: \'Fürwahr, ich will jetzt an die Hirten; ich fordere aus ihren Händen meine Schafe und mache ihrem Hirtenamt ein Ende. Die Hirten sollen nimmermehr sie weiden. Aus ihrem Munde will ich meine Schafe reißen. Sie sollen ihnen nicht zur Speise dienen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Denn also spricht der Herr, der Herr:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, '\'Gleichwie ein Hirte sich um seine Herde sorgt, am Tage, da er mitten unter der zersprengten Herde ist, so nehme ich mich meiner Schafe an, entreiße sie aus all den Orten, wohin sie sich zerstreut am Tage des Gewölks und Wolkendunkels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Und aus den Völkern führe ich sie weg und sammle aus den Ländern sie und bringe sie zu ihrem Vaterland und weide sie dann auf den Bergen Israels, in Tälern und in allen Wohnstätten des Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Ich weide sie auf guter Weide, und auf den hohen Bergen Israels ist ihre Hürde. Dort sollen sie auf guter Weidetrift sich lagern und fette Weide auf den Bergen Israels bekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ich selber weide meine Schafe; ich lasse selbst sie lagern.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, '\'Ich suche das Verirrte auf, und das Verlorene führe ich zurück, verbinde das Verwundete. Das Kranke stärke ich und hüte das Gesunde und das Fette. Ich weide sie, wies richtig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Ihr, meine Schafe\', also spricht der Herr, der Herr. \'Ich richte zwischen Schaf und Schaf.\' Von jenen Widdern, jenen Böcken spricht der Herr:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, '\'War\'s euch noch nicht genug, die beste Weide abzuweiden? Was ihr von eurer Weide übrigließet, zerstampftet ihr mit euren Füßen. Das klare Wasser trankt ihr selber; was übrig, machtet ihr mit euren Füßen trübe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'So mußten meine Schafe weiden, was ihr zertreten habt mit euren Füßen, und trinken, was ihr trüb gemacht mit euren Füßen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Deshalb spricht so der Herr, der Herr, zu ihnen: \'Seht, ich bin da und richte zwischen diesen fetten Schafen und den mageren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Weil ihr mit Hinter- und mit Vorderfüßen schlagt und mit den Hörnern alle kranken Tiere stoßt, bis daß ihr sie hinausgetrieben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'so helf ich meinen Schafen denn, daß sie nicht mehr zu eurer Beute werden. Ich richte zwischen Schaf und Schaf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Und ich bestelle über sie zum Weiden einen einzigen Hirten, den David, meinen Knecht. Er soll sie weiden, soll ihr Hirte sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Und ich, der Herr, will dann ihr Schutzgott sein, mein Diener David Fürst bei ihnen. Ich sag\' es, ich, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Und ich errichte einen Friedensbund für sie, verbanne aus dem Land die wilden Tiere. Selbst in der Wüste sollen sie dann sicher wohnen, in Wäldern schlafen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Ich mache sie und was um meinen Hügel liegt, zum Segen. Zur rechten Zeit send ich den Regen; es sollen segensreiche Regengüsse sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Des Feldes Bäume tragen ihre Früchte, und sein Erträgnis gibt das Land. Auf ihrem Boden wohnen sie so sicher, und sie erfahren, daß ich der Herr, wenn ich ihr lastend Joch zerbrochen und sie entrissen der Gewalt von Leuten, die sie knechteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Sie sollen nicht mehr eine Beute für die Heiden sein; des Landes Tiere sollen nimmermehr sie fressen; sie sollen sicher wohnen, nicht mehr aufgeschreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Vollkommene Pflanzung laß ich ihnen sprießen. In diesem Land soll niemand mehr durch Hunger aufgerieben werden und niemand mehr der Heiden Hohn zu tragen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Sie sollen es erfahren, daß ich der Herr, ihr Gott, mit ihnen bin, daß sie, das Haus von Israel, mein Volk.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, '\'Ihr, meine Schafe, Schafe meiner Weide! Ihr seid zwar Menschen; aber ich bin euer Gott.\' Ein Spruch des Herrn, des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '\"Auf, Menschensohn! Richt dein Gesicht nach dem Gebirge Seïrs hin und prophezeie ihm');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'und sprich zu ihm: So spricht der Herr, der Herr: \'Ich will an dich, Gebirge Seïr, und strecke meine Hand aus wider dich und mache dich zur öden Wüstenei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'In Schutt verwandle ich dir deine Städte; du selbst sollst eine Wüste werden, daß du erfährst: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Weil ewige Feindschaft du gehegt, die Söhne Israels dem Schwert entgegentriebst zu ihrer Unglückszeit, zur Zeit, da Missetat zum Ende führte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'darum, so wahr ich lebe\', ein Spruch des Herrn, des Herrn, \'ich mache dich zu Blut. Blutschuld verfolge dich! Da du nicht feind dem Blutvergießen warst, verfolg\' dich selber blutige Schuld!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Ich mache das Gebirge Seïr zur öden Wüste, und was da kommt und geht, vertilge ich daraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Ich fülle deine Berge mit Erschlagnen an. Auf deinen Hügeln und in deinen Tälern, an allen deinen Bächen liegen Schwertdurchbohrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Ich wandle dich in ewige Wüstenei, und deine Städte bleiben unbewohnt, daß ihr erfahrt, daß ich der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Weil du gesagt: \"Zwei Völker und zwei Länder sind jetzt mein. Wir wollen in Besitz sie nehmen\", und doch ist dort der Herr;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'darum, so wahr ich lebe\', ein Spruch des Herrn, des Herrn, \'verfahre ich, wie es dein Zorn verdient und deine Eifersucht, mit der du gegen sie in deinem Haß verfahren. Ich mach mich dadurch kenntlich, daß ich dich strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Und du erfährst, daß ich, der Herr, all deine Lästerungen angehört, die gegen Israels Gebirg\' du ausgestoßen: \"Es ist zur Wüstenei geworden und uns zum Fraße überlassen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Ihr führtet Prahlereien gegen mich in eurem Mund, und führtet freche Reden wider mich. Ich selber hörte es.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So spricht der Herr, der Herr: \"Ich mache dich zur Wüste, aller Welt zur Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Wie deine Freude über Israels verwüstetes Gebiet verdient, also verfahre ich mit dir. Zur Wüste soll Seïrs Gebirge werden, in seinem ganzen Umfang Edom, daß man erfährt, daß ich der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '\"Du aber, Menschensohn, weissage über das Gebirge Israels und sprich: \'Ihr Berge Israels, vernehmt das Wort des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So spricht der Herr, der Herr: \"Weil über euch die Feinde sprechen: Ha! Die ewigen Höhen sind in unseren Besitz gelangt\"\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'deshalb weissage du und sprich: \'So spricht der Herr, der Herr: \"Weil zum Verderben man nach euch ringsum begierig schnappte, daß ihr das Eigentum des Rests der Heiden würdet, weil ihr geworden ein Gerede und Gespräch der Völker,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'darum, ihr Berge Israels, vernehmt das Wort des Herrn, des Herrn!\"\' So spricht der Herr, der Herr, zu diesen Bergen, diesen Hügeln, zu den Bächen und den Tälern und den öden Wüsten und verlaßnen Städten, die zum Schimpf und Spott dem Rest der Heiden ringsumher geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Darum spricht so der Herr, der Herr: \'In meinem Feuereifer tu ich jetzo diesen Ausspruch dem Rest der Völker und ganz Edom gegenüber, die sich in wilder Herzensfreude und mit schadenfroher Seele mein Land genommen, es zu verheeren und zu plündern\';');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'weissag deshalb dem Lande Israel und sprich: \'Von diesen Bergen, Hügeln, Bächen, Tälern spricht der Herr, der Herr: \"In meinem Eifer und im Grimme tu ich nun den Ausspruch, weil ihr den Hohn der Heiden tragen müßt\";');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'darum spricht so der Herr, der Herr: \"Ich schwöre mit erhobner Hand: Fürwahr, die Heidenvölker um euch her, sie sollen ihre Schande tragen müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Ihr aber, Berge Israels, sollt euer Laub jetzt sprossen lassen und eure Früchte tragen für mein Volk, für Israel. Sie kommen heim in Bälde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Ich will mich abermals zu euch begeben, mich zu euch wenden; ihr sollt bebaut, besäet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Die Menschen werde ich auf euch vermehren, das ganze Haus von Israel; die Städte sollen dann bewohnt und aufgebaut die öden Plätze werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Und Vieh und Menschen mehre ich auf euch; sie sollen zahlreich, fruchtbar werden. Ich lasse euch bewohnt sein wie in eurer letzten Zeit und Gutes euch erweisen mehr als je in eurer allerersten Zeit, daß ihr erfahrt: Ich bin der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Ich lasse wieder Menschen euch betreten, du Israel, mein Volk, und diese werden in Besitz dich nehmen. Du dienst ihnen zum Eigentum, beraubst sie fortan nimmermehr der Kinder.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So spricht der Herr, der Herr: \'Weil man zu euch gesagt: \"Du bist ja eine Menschenfresserin und machst selbst kinderlos dein Volk\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'deshalb frißt du nicht Menschen mehr und machst dein Volk nicht kinderlos.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, '\'Ich lasse dich den Hohn der Heiden nicht mehr hören. Den Spott der Völker sollst du nicht mehr weiter tragen, dein Volk nicht kinderlos mehr machen.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '\'Hör, Menschensohn! Einst wohnte das Haus Israel in seinem Land; doch es befleckte dies durch seinen Wandel, seine Taten. Gleichwie ein unrein Weib, so unrein war vor mir sein Wandel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Da goß ich meinen Ingrimm über sie, des Blutes wegen, das im Lande sie vergossen, und ihrer Götzen wegen, durch die sie sich bedeckten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Und ich versprengte sie unter die Heidenvölker; sie wurden in die Länder hin versprengt. Entsprechend ihrem Wandel, ihren Taten, sprach ich über sie das Urteil aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Sie kamen zu den Heidenvölkern. Wohin sie aber kamen, entweihten sie dort meinen heiligen Namen, da man von ihnen sagte: \"Das Volk des Herrn sind sie, und dennoch mußten sie aus seinem Lande fort.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Da tat\'s mir leid um meinen heiligen Namen, den bei der Heidenwelt Israels Haus entweihte, wohin sie immer kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Deshalb sprich so zum Hause Israel: So spricht der Herr, der Herr: \'Haus Israel, um euretwillen tu ich\'s nicht, nein, nur um meines heiligen Namens willen, den ihr entweiht habt bei der Heidenwelt, zu der ihr kamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Nun will ich meinen großen Namen heiligen, der bei den Heiden ward entweiht, den ihr bei ihnen habt entweiht, auf daß die Heidenwelt erkenne: Ich bin der Herr,\' ein Spruch des Herrn, wenn ich vor ihren Augen mich als Heiligen erzeige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Ich hole aus den Heidenvölkern euch und sammle euch aus allen Ländern und bringe euch wieder in die Heimat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Und ich besprenge euch mit reinem Wasser, daß rein ihr werdet. Von allen euren Unreinheiten und allen euren Götzen mache ich euch rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Ich gebe euch ein neues Herz und senke einen neuen Geist in euer Inneres. Das Herz von Stein entnehm ich eurem Leib und gebe euch ein Herz von Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ich senke ein in euer Innres meinen Geist und mache euch zu Leuten, die nach meinen Satzungen sich richten und meine Vorschriften beachten und befolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Dann dürft ihr in dem Lande wohnen bleiben, das euren Vätern ich verliehen. Ihr sollt mein Schutzvolk werden, und ich will euer Schutzgott sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Und ich befreie euch von allen euren Unreinheiten; ich rufe das Getreide her und mehre es. Ich bringe keine Hungersnot mehr über euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Ich laß der Bäume Früchte wachsen und in Menge den Ertrag des Feldes, damit ihr bei den Heiden nicht die Schmach des Hungers mehr ertragen müßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Alsdann erinnert ihr euch eures bösen Wandels und eurer Taten, die nicht gut gewesen. Ihr werdet Ekel vor euch selbst bekommen um eurer Sünden, eurer Greuel willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nicht euretwegen tu ich das\'; ein Spruch des Herrn, des Herrn. \'Dies sei euch unverhohlen! Schämt euch und werdet rot vor eurem Wandel, Haus Israel!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So spricht der Herr, der Herr: \'Wenn ich von allen euren Sünden euch gereinigt, die Städte wieder hab\' erbauen lassen, und wenn zerstörte Orte werden neu gebaut');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'und angebaut das Ödland sein wird, statt wie zuvor wüst dazuliegen vor jedes Wandrers Blicken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'dann wird man sagen: \"Dieses vormals wüste Land ist jetzt dem Garten Edens gleich geworden. Die wüsten, öden und zerstörten Städte werden jetzt bewohnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Da sehen rings um euch die Heidenvölker, die übrig sind geblieben, ein, daß ich, der Herr, es bin, der das Zerstörte wieder aufgebaut und das Verheerte wieder angepflanzt, daß ich, der Herr, es bin, der dies versprochen und getan.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So spricht der Herr, der Herr: \'Auch darum laß ich mich vom Hause Israel erbitten, und ich erfülle ihnen, daß ich an Menschen sie vermehre, zahlreich wie die Herden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'So wie von heiligen Schafen, so wie Jerusalem in Zeiten seiner Feste voll von Schafen ist, so sollen auch die öden Städte voll von Menschenherden werden, daß sie erfahren, daß ich bin der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Da senkte sich die Hand des Herrn auf mich. Im Geiste führte mich der Herr hinaus und brachte mich in eine Ebene voller Gebeine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Er ließ mich ringsum sie betrachten; sehr viele lagen auf der Ebene. Sie waren völlig ausgetrocknet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Er sprach zu mir: \"Sag, Menschensohn! Sollten wohl die Gebeine abermals lebendig werden können?\" Ich sprach: \"Herr, Herr, das weißt nur du.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Er sprach zu mir: \"So prophezeie über die Gebeine und sprich zu ihnen: \'Ihr ausgetrockneten Gebeine, vernehmt das Wort des Herrn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So spricht der Herr, der Herr, zu den Gebeinen: \"Ich bringe zur Belebung Geist in euch,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'und Sehnen lege ich auf euch und lasse Fleisch darüber wachsen und überziehe euch mit Haut und bringe zur Belebung Geist in euch, daß ihr erfahrt, daß ich der Herr.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Da prophezeite ich, wie mir befohlen wird. Und als ich prophezeite, gab es ein Getöse, und die Gebeine rückten eins ans andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Ich sah\'s. Da kamen Sehnen dran, und Fleisch wuchs drüber her. Dann spannte Haut sich oben drüber. Noch aber war kein Geist in ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Er sprach zu mir: \"Weissage von dem Geiste! Weissage, Menschensohn, und sprich zum Geiste: So spricht der Herr, der Herr: \'Herbei von den vier Winden komm, Geist! Hauch diese Toten an, daß sie lebendig werden!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Ich prophezeite so, wie er mir anbefohlen. Da kam der Geist in sie. Sie wurden abermals lebendig und stellten sich auf ihre Füße, eine große, große Schar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Er sprach zu mir: \"Sieh, Menschensohn! Diese Gebeine sollen das gesamte Haus von Israel bedeuten; sie sind es, die gesprochen: \'Fleischlos sind unsere Gebeine, und unsere Hoffnung ist dahin, und unser Lebensfaden ist zerschnitten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Deswegen weissage und sprich zu ihnen: So spricht der Herr, der Herr: \'Ich öffne eure Gräber und lasse euch, mein Volk, aus euren Gräbern steigen und führe euch in das Land Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Dann werdet ihr erkennen, daß ich der Herr bin, wenn ich eure Gräber öffne und euch aus diesen Gräbern steigen lasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Ich senke meinen Geist in euch, daß ihr lebendig werdet und erfahrt: Ich selbst, der Herr, tu das, was ich versprochen.\'\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '\"Du Menschensohn! Ein Holz nimm dir und schreib darauf: \'Für Juda und die Söhne Israels, die es mit jenem hielten\'. Dann nimm dir einen andern Stab und schreib darauf: \'Für Joseph ist dies Holz, für Ephraim und für das ganze Haus, das es mit jenem hielt\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Und füge eins zum anderen, daß sie zu einem Holze werden, daß sie in deiner Hand zu einem Stücke werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Und fragen dich die Söhne deines Volks: \'Willst du uns nicht erklären, was dies wohl bedeutet?\',');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'dann sag zu ihnen: Also spricht der Herr, der Herr: \'Ich nehme Josephs Holz, das sich bei Ephraim befindet, und die Stämme Israels, die es mit jenem hielten, und füge es ans Juda-Holz und mache sie zu einem Holze. Sie werden eins durch meine Hand.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Dann nimm die Hölzer, auf die du geschrieben hast, in deine Hand vor ihren Augen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'und sprich zu ihnen: Also spricht der Herr, der Herr: \'Fürwahr, ich hol die Söhne Israels her aus den Heidenvölkern, bei denen sie sich aufgehalten, und sammle sie von allen Seiten und bringe sie ins Vaterland');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'und mache sie zu einem Volk im Lande auf den Bergen Israels. Zum König sollen sie dann alle einen König haben; sie sollen nimmermehr zwei Völker sein, nicht mehr geteilt sein in zwei Königreiche!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Sie machen sich nicht weiterhin unrein an ihren Götzen, ihren Scheusalen. Von allen ihren Sünden will ich sie befreien. Von allen ihren Ausgelassenheiten, durch die sie sich versündigt, will ich sie reinigen. Sie sollen dann mein Schutzvolk werden; ich will ihr Schutzgott sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Mein Diener David soll ihr König werden. Ein Hirte soll er für sie alle sein. Nach meinen Rechten werden sie sich richten und meine Satzungen beachten und sie tun');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'und in dem Lande wohnen, das meinem Diener Jakob einst ich eingeräumt, in dem einst eure Väter wohnten. Auf ewig wohnen sie darin und ihre Kinder, ihre Kindeskinder, und ewig ist mein Diener David Fürst bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Mit ihnen schließe ich des Friedens Bund; ein Bund von ewiger Dauer soll er ihnen sein. Ich will sie segnen und sie mehren und nehme meinen heiligen Sitz auf ewig unter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Mein Wohnsitz wird bei ihnen sein; ich will ihr Schutzgott werden, und sie werden dann mein Schutzvolk sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Die Heiden werden anerkennen, daß ich, der Herr, mein Israel ganz heilig mache, wenn ewiglich mein heiliger Sitz bei ihnen ist.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '\"Du, Menschensohn! Dein Antlitz richte gegen Gog im Lande Magog, den Großfürsten von Mesech und von Tubal! Weissage gegen ihn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'und sprich: So spricht der Herr, der Herr: \'Fürwahr, ich will an dich, du Gog, Großfürst von Mesech und von Tubal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Ich leite dich mit Haken, die ich in deine Backen lege, und lasse dich mit deinem ganzen Heer ausziehen, mit Rossen und mit Reitern, die alle auf das herrlichste gewandet sind, wohl eine große Schar mit Schild und Wehr, und alle haben Schwerter in den Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Mit ihnen Paras, Kusch und Put, sie allesamt mit Schild und Helm,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Kimmerier und alle ihre Scharen, Togarmas Haus im hohen Norden und alle seine Scharen; gar viele Völker sind bei dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Nun rüste dich und mach dich selber fertig und alle deine Scharen, die sich bei dir versammelt, und übernimm du über sie den Kriegsbefehl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Zwar wirst du erst nach vielen Tagen aufgeboten. Am Ende erst der Jahre wirst du in das Land der Schwertentronnenen und derer kommen, die aus vielen Völkern sich gesammelt auf den Bergen Israels, die wiederholt Verödung traf und die bis jetzt in tiefer Sicherheit gewohnt, nachdem sie aus den Völkern weggeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Und rückst du an, kommst du dem Sturmwind gleich, bedeckst das Land wie ein Gewölke, du und alle deine Scharen, die vielen Völker, die bei dir.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So spricht der Herr, der Herr: \'An jenem Tag geschieht\'s; da kommen Pläne dir in deinen Sinn, und eine schlimme Absicht wirst du hegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Du sprichst: \"Einfallen will ich in das offne Land, die Friedlichen angreifen, die in Ruhe wohnen, die allesamt in Plätzen ohne Mauern wohnen, die keine Riegel, keine Pforten haben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'da will ich Beute machen, plündern.\" Du legst die Hand an wiederaufgebaute Trümmer und an ein Volk, das aus den Heiden ist gesammelt, das Vieh und Herden zu erwerben sich befleißt und auf dem Nabel der Erde wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Die Handelsleute von Seba, Dedan und Tarsis und alle seine Händler sprechen dann zu dir: \"Kommst du zum Beutemachen, Rauben? Hast du dein Heer versammelt, um Gold und Silber fortzuschleppen, um Vieh und Herden fortzunehmen und große Beute zu erbeuten?\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Drum prophezeie, Menschensohn, und sprich zu Gog: So spricht der Herr, der Herr: \'Nicht wahr, du wirst\'s zu jener Zeit erfahren, wenn Israel, mein Volk, ganz sicher wohnt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Dann wanderst du von deiner Heimat aus, dem hohen Norden, du und die vielen Völker, die bei dir. Sie reiten allesamt auf Rossen, ein großes Volk, ein starkes Heer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Du ziehst gen Israel, mein Volk, heran und deckst das Land wie ein Gewölke. Geschehen wird\'s am Ende jener Tage, daß ich dich meinem Land zuführe, damit die Heiden kennenlernen, wer ich bin, wenn ich an dir vor ihren Augen, Gog, mich selbst als Heiligen erweise.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So spricht der Herr, der Herr: \'Du bist\'s, von dem ich redete in alten Tagen durch meine Diener, die Propheten Israels, die damals schon die Jahre prophezeiten, die ich jetzt gegen sie heranführe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'An jenem Tag, zur Zeit, wann Gog kommt über das Land Israel\', ein Spruch des Herrn, des Herrn, \'entbrennt mein Grimm in meinem Zorne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'In meinem Eifer, meinem Feuergrimm verordne ich: An jenem Tage sei ein großes Beben im Lande Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Vor mir erzittern dann des Meeres Fische und des Himmels Vögel, das Getier des Feldes und alles auf der Erde kriechende Gewürm und alle Menschen in dem Lande. Die Berge werden umgerissen; hinstürzen Felsensteige; zu Boden fällt jedwede Mauer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Ich werde gegen ihn ein Schwert aufbieten auf allen meinen Bergen.\' Ein Spruch des Herrn, des Herrn. \'Das Schwert des einen würgt den andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Durch Pest und Blutvergießen streite ich mit ihm, durch Wolkenbrüche und durch Hagelsteine, und lasse Schwefelfeuer auf ihn regnen, auf ihn und seine Scharen und auf die vielen Völker, die bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'So zeige ich mich groß und heilig. So tu ich kund mich vor den Augen der Heiden, daß sie es erfahren. Ich bin der Herr.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '\"Du, Menschensohn! Weissage gegen Gog und sprich. So spricht der Herr, der Herr: \'Fürwahr, ich will an dich, du Gog, Großfürst von Mesech und von Tubal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Dich leite ich und bring dich aus dem hohen Norden und führe dich auf das Gebirge Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Da schlag ich deinen Bogen dir aus der Linken und lasse deine Pfeile deiner rechten Hand entsinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Auf Israels Gebirge sollst du fallen, du und all deine Scharen, die Völker um dich her. Raubvögeln, allen möglichen, den wilden Tieren gebe ich zum Fraß dich hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Auf freiem Felde bleibst du liegen; ich sage es.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, '\'Ein Feuer sende ich auf Magog nieder und auch auf die, die auf den Inseln friedlich wohnen, daß sie erfahren, daß ich der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Ich mache meinen heiligen Namen kund inmitten meines Volkes Israel. Ich laß nicht länger meinen heiligen Namen mehr entweihen. Die Heidenwelt soll innewerden, daß ich, der Herr, ein Heiliger in Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Fürwahr, es kommt; so gut ist\'s, wie geschehen.\' Ein Spruch des Herrn, des Herrn. \'Das ist der Tag, von dem ich sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Dann kommen aus den Städten Israels Bewohner und zünden Feuer an. Mit Rüstungen und Schilden zünden sie es an, mit Tartschen, Bogen, Pfeilen, Keulen, Spießen und unterhalten sieben Jahre lang ein Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Vom Felde holen sie kein Holz und fällen keines in den Wäldern. Sie unterhalten nur mit diesen Rüstungen das Feuer, berauben die, die sie beraubt, und plündern die, die sie geplündert.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '\'Ich gebe Gog dort einen Ort an jenem Tag zum Grab in Israel, das Tal der Wanderer ostwärts vom Meere, und jenes sperrt den Wanderern den Weg. Daselbst begräbt man Gog und seine ganze Schar und heißt es \"Tal der Scharen Gogs\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'An ihnen hat Israels Haus wohl an die sieben Monde zu begraben, um so das Land zu reinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Das ganze Volk des Landes muß begraben helfen. Zum Ruhm dient ihm der Tag, an dem ich mich verherrliche.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '\'Und eigne Männer wählt man aus, die in dem Lande Nachschau halten, zu diesen, die nachsehen, ob noch im Lande jemand übrig sei, die andern zu begraben, um es so zu reinigen. Nach sieben Monden sollen sie mit Nachforschen beginnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Wenn diese Nachschauhaltenden das Land durchmustern, und sie sehn ein menschliches Gebein, alsdann errichten sie ein Zeichen neben ihm, bis es die Totengräber in dem Tal der Scharen Gogs begraben können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Auch heißt davon Hamona eine Stadt; so reinigt man das Land.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Du aber, Menschensohn\", so spricht der Herr, der Herr: \"Ruf jetzt den Vögeln und allen den Beflügelten und allem Wild des Feldes: \'Versammelt euch und kommt herbei! Versammelt euch von allen Seiten zu meinem Opfermahl, das ich für euch geschlachtet, ein großes Schlachtfest auf den Bergen Israels!\' Da sollt ihr Fleisch zum Fressen und Blut zum Trinken haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Ja, Fleisch von Kriegern sollt ihr fressen und Blut von Erdenfürsten trinken, von Widdern, Lämmern, Böcken, Farren, Mastvieh von Basan insgesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Fett sollt ihr essen bis zur Sättigung und Blut bis zur Berauschung trinken von meinem Opfer, das ich euch geschlachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Ihr sollt an meinem Tisch euch sättigen an Rossen und an Zugtieren, an Streitern und allerlei Kriegsleuten.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '\"Da mache ich den Heiden sichtbar meine Herrlichkeit, und alle Heiden schauen die Gerechtigkeit, von mir geübt, und fühlen meine Hand, die ich auf sie gelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Das Haus von Israel wird alsdann inne, daß ich, der Herr, ihr Schutzgott bin von diesem Tage an und fernerhin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Auch überzeugen sich die Heiden, daß nur um seiner Sünde willen das Haus Israel in die Verbannung zog, daß ich vor ihnen barg mein Angesicht, sie preisgab ihren Feinden, daß sie durchs Schwert hinstürzten allzumal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'So, wie ihr unrein Wesen, ihre Missetaten es verdienten, tat ich ihnen und barg mein Angesicht vor ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'So spricht deshalb der Herr, der Herr: \"Ich bringe Jakobs weggeführtes Volk zurück, erbarme mich des ganzen Hauses Israel und eifre so für meinen heiligen Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Alsdann verlernen sie ihr schändliches Benehmen und alle ihre Untreue, die sie an mir verübt, wenn sie in ihrem Lande sorglos wohnen, von niemand aufgeschreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Wenn ich sie erst zurückgebracht aus jenen Völkern und sie gesammelt aus den Ländern ihrer Feinde, dann will ich mich an ihnen auch erweisen als Heiliger vor vieler Heiden Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Und sie erkennen dann, daß ich der Herr, ihr Gott, daß ich sie zu den Heiden in die Verbannung führte und sie in ihre Heimat wieder sammelte, wobei ich keinen dort zurückgelassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Mein Antlitz berge ich nicht mehr vor ihnen; ich gieße meinen Geist auf das Haus Israel.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Im Jahre fünfundzwanzig unserer Verbannung, am Anfang dieses Jahres, am zehnten Tag des Monats im Jahre vierzehn nach Eroberung der Stadt, an eben diesem Tage senkte sich die Hand des Herrn auf mich und brachte mich dorthin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'In göttlichen Gesichten bringt er mich zum Lande Israel und setzt mich hier auf einem hohen Berge nieder. Dem gegenüber war etwas wie einer Stadt Gebäulichkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Sobald er mich dorthin gebracht, da zeigte sich ein Mann, der aussah wie aus Erz. Er hatte eine Linnenschnur und einen Maßstab in der Hand und stand am Tor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Es sprach der Mann zu mir: \"Sieh, Menschensohn, mit deinen Augen! Und hör mit deinen Ohren, gib auf alles acht, was ich dir zeige! Denn hierher wurdest du gebracht, daß ich dir alles zeigen sollte. Verkünde alles, was du siehst, dem Hause Israel!\" 1');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Nun lief da außerhalb des Hauses eine Mauer ringsherum, und in der Hand des Mannes war ein Maßstab von sechs Ellen, zu einer Elle und noch einer Handbreite gerechnet. Er maß des Baues Breite: eine Rute; die Höhe: eine Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Dann trat er in das Tor, das gegen Osten sah, und stieg hinan auf seinen Stufen und maß des Tores Schwelle, in der Breite: eine Rute, die andere Schwelle gleichfalls eine Rute in der Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Und jegliches Gemach war eine Rute lang und eine Rute breit, und zwischen den Gemächern betrug der Zwischenraum fünf Ellen. Kam noch des Tores Schwelle an der innern Torhalle mit einer Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Er maß des Tores innere Lichtweite mit einer Rute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Die Torweite dagegen maß er mit acht Ellen. Es waren nämlich seine Wandpfeiler zwei Ellen dick, desgleichen an der innere Torweite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Und die Gemächer an dem Tore gegen Osten waren drei auf der einen und drei auf der andern Seite. Die drei besaßen gleiches Maß, desgleichen beiderseits die Wandpfeiler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Er maß die Breite von der Torweite: zehn Ellen; die Torlänge: dreizehn Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Ein freier Raum von einer Elle war vor den Kammern, auf dieser und auf jener Seite. Sechs Ellen hatte jede Kammer auf dieser und auf jener Seite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Er maß das Tor vom Dach der einen Kammer bis zu dem der andern, an fünfundzwanzig Ellen breit; Durchgang stand Durchgang gegenüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Die Säulen machten sechzig Ellen, den Vorsprung an den Säulen eingerechnet. So war ein jedes Tor ringsum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Vom Torgiebel bis zu der innern Torweite betrug es fünfzig Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Schräg gingen Gitterfenster in die Kammern und auch zu ihren Säulen im Inneren des Tores an allen Seiten. So hatten auch die Vorhallen ringsum nach innen Fenster, und an den Pfeilern waren Palmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Er brachte mich zum innern Vorhof hin; da waren Zellen. Der Vorhof war ringsum gepflastert und dreißig Zellen an dem Pflaster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Das Pflaster lief zwar nach der Seite der Tore hin; doch war das Pflaster längs der Tore etwas niedriger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Er maß die Breite von dem untern Tor bis an die äußre Wand des innern Hofes; hundert Ellen gegen Osten und gegen Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Vom Tor, das gegen Mitternacht des äußern Vorhofs lag, maß er die Länge und die Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Drei Kammern hatte es, drei hüben und drei drüben, und seine Pfeiler, seine Bogen besaßen ganz genau das Maß des erstgenannten Tores. An fünfzig Ellen war es lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Und seine Fenster, seine Bogen und seine Palmen waren wie beim Tor, das gegen Osten lag. Auf sieben Stufen stieg man zu ihm auf; vor diesen war ein Bogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Es gingen Tore in den innern Hof, die gleich den Toren gegen Mitternacht und Morgen waren. Er maß von Tor zu Tor: einhundert Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Er brachte gegen Süden mich; da fand ich südlich auch ein Tor. Er maß die Pfeiler und die Bogen; sie hatten ganz das gleiche Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Und Fenster hatte es ringsum, gerade wie die Bogen, gleich jenen Fenstern. Es war auch fünfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Auf sieben Stufen stieg man zu ihm auf; vor diesen war ein Bogen. Als Pfeiler dienten Palmen auf dieser und auf jener Seite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Ein Tor zum innern Hof lag gegen Süden; er maß von Tor zu Tor nach Süden hundert Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Durch dieses Südtor brachte er mich zu dem innern Hof. Er maß das Tor; es waren wiederum die gleichen Maße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Auch seine Kammern, Pfeiler, Bogen besaßen gleiches Maß. Es hatte Fenster ringsherum, war fünfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Und Bogen waren ringsherum, an fünfundzwanzig Ellen lang, fünf Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Sein Bogen ging dem äußern Vorhof zu, und Palmen waren seine Pfeiler. Acht Stufen stieg man zu ihm auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Er brachte mich zum innern Vorhof gegen Osten und maß das Tor: die gleichen Maße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Und seine Kammern, Pfeiler, Bogen besaßen gleiches Maß. Es hatte Fenster ringsherum, gerade wie sein Bogen, war fünfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Sein Bogen zog sich nach dem äußeren Vorhof hin, und seine Pfeiler waren palmenförmig auf beiden Seiten. Auf acht Stufen stieg man empor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Er führte mich zum Tore gegen Mitternacht und maß das gleiche Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Es hatte Kammern, Pfeiler, Bogen; es hatte Fenster ringsherum, war fünfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Sein Säulengang zog sich zum äußern Vorhof hin, und seine Pfeiler waren palmenförmig auf beiden Seiten. Auf acht Stufen stieg man.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Dann gab es eine Zelle, und ihre Tür war in den Torsäulen. Man wusch darin das Brandopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Und in des Tores Lichtweite auf beiden Seiten waren jedesmal zwei Tische aufgestellt, um Brand- und Sünd- und Schuldopfer darauf zu schlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Und außerhalb, wo man hinaufgeht zu der Tür des Tores gegen Mitternacht, da standen ebenfalls zwei Tische und andere zwei Tische auf der andern Seite der Lichtweite des Tores.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Auf dieser Seite vier Tische, vier auf jener Seite bei dem Tor, acht Tische. Auf ihnen sollte man die Opfer schlachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Die vier Brandopfertische waren aus behauenen Steinen, an ein und eine halbe Elle lang und breit und eine Elle hoch, auf die man die Geräte niederlegte, mit denen man das Brand- und Schlachtopfer schlachtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Handbreite Doppelhaken waren innen ringsum angebracht zum Aufhängen des Opferfleischs und der Geräte, mit denen man das Brand- und Schlachtopfer schlachtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Und außerhalb des innern Tores waren Zellen für die Sänger in dem innern Hof, die eine an der Seite des Nordtores, die gegen Süden sah, die andre an der Seite des Osttores, die gegen Norden sah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Er sprach zu mir: \"Die Zelle, die nach Süden schaut, gehört den Priestern, die den Tempeldienst verrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Die Zelle, die nach Norden schaut, gehört den Priestern, die Altardienste versehen. Dies sind die Sadoksöhne, die von den Levisöhnen bei dem Herrn das Vorrecht haben, ihn zu bedienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Er maß den Vorhof: hundert Ellen lang und hundert Ellen breit, ein Viereck; doch vor dem Haus war der Altar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Er brachte mich zur Toröffnung des Hauses und maß die Pfeiler der Öffnung, fünf Ellen hüben und fünf Ellen drüben, drei Ellen hier, drei Ellen dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Der Öffnung Breite waren zwanzig Ellen, elf Ellen seine Tiefe. Man stieg hinan auf Stufen. Auch waren Säulen an den Pfeilern, die eine hüben und die andre drüben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Er brachte mich zum Tempel hin und maß die Säulen, sechs Ellen breit auf dieser Seite, sechs Ellen breit auf jener, des Zeltes Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Es war das Tor zehn Ellen breit, des Tores Wände fünf auf jeder Seite; dann maß er seine Länge: vierzig Ellen, und seine Breite: zwanzig Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Er ging ins Innere und maß der Türe Pfeiler: zwei Ellen; sechs Ellen hatte zwar die Tür; doch war sie sieben Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Dann maß er seine Länge: zwanzig Ellen, und seine Breite: zwanzig Ellen von dem, was vor dem Tempel lag; er sprach zu mir: \"Das ist das Allerheiligste.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Er maß des Hauses Wand: sechs Ellen, und ein vier Ellen breiter Seitengang lief um das Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Es reihte Zimmer sich an Zimmer, dreiunddreißigmal; sie stießen an die Mauer, die für die Zimmer dieses Haus besaß; sie hingen rings mit ihr zusammen, doch ohne in des Hauses eigene Mauer einzugreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Die Breite dieser Zimmer nahm nach oben immer zu; man sollte oberhalb des Hauses ringsum gehen können; drum war das Haus nach oben breiter, und aus dem untere Stockwerk ging man durch das mittlere zum obern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Auch sah ich eine Einfassung rings um das Haus, dem Meßgehalt der Zimmer ganz entsprechend eine volle Rute, sechs Ellen oben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Die Außenmauer jener Zimmer war fünf Ellen dick und soviel auch der freie Raum des Zimmerbaus beim Tempelhaus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'und zwischen den Gemächern war ein zwanzig Ellen breiter Raum rings um das Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Zwei Türen waren in dem freigebliebnen Raum der Zimmer, je eine gegen Nord und eine gegen Süden; des freigebliebnen Raumes Breite war fünf Ellen ringsherum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Und das Gebäude, das gegen Abend an dem Tempelplatze lag, war siebzig Ellen breit und des Gebäudes Wand fünf Ellen ringsum breit und seine Länge neunzig Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Er maß das Haus: gerade hundert Ellen lang, den Tempelplatz samt dem Gebäude und dem Zwischenstück: gerade hundert Ellen lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Des Hauses Front sowie der Platz nach Osten zu war hundert Ellen breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Er maß nun des Gebäudes Länge bis zum Platze, der dahinter lag, und die Terrassen auf den beiden Seiten: hundert Ellen, den innern Tempel und des Vorhofs Bogen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'die Schwellen und die schrägen Fenster und die Altanen rings an den drei Seiten - und bei den Schwellen, da war alles ringsherum getäfelt -, sodann den Boden bis an jene Fenster; die Fenster aber waren gut verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Und oberhalb der Türen, innerhalb und außerhalb des Hauses, und an der ganzen Wand herum, im Innern wie auch außerhalb nach festbestimmten Maßen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'da waren Cherube und Palmen angebracht. Je eine Palme trennte einen Cherub von dem andern, und jeder Cherub hatte zwei Gesichter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Ein Menschenangesicht sah auf die Palme dort, am ganzen Hause ringsum angebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Vom Boden bis hinauf zur Türe waren Cherube und Palmen angebracht, auch an der Tempelwand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Des Tempels Türeinfassung indessen war viereckig. Das Heiligtum bot ganz den gleichen Anblick.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Aus Holz war der Altar, drei Ellen hoch, zwei Ellen lang; in Hörnern liefen seine Ecken aus; sein Fußgestell und seine Wände waren hölzern. Er sprach zu mir: \"Das ist der Tisch, der vor dem Herren steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Zwei Türen waren an dem Tempel und dem Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Es waren Doppeltüren mit zwei Blättern, die ganz zusammenlegbar waren; die eine Türe hatte ein Paar Türblätter, desgleichen auch die andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'An ihnen, an den Tempeltüren waren Cherube und Palmen angebracht wie an den Wänden, und vor der Halle war ein hölzern Vordach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Und schräge Fenster und Palmen waren an den beiden Seiten und an den Seitenwänden der Halle, an des Hauses Kammern und den Vordächern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Dann führte er mich gegen Norden zum äußern Vorhofe und brachte mich zu den Gemächern, die dem Platz und dem Gebäude gegen Norden vorgelagert waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'derart, daß ihre hundert Ellen lange Seite an dem Nordtor war, und fünfzig Ellen war die Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Denn zwanzig Ellen fielen auf den innern Vorhof ab und soviel auf das Pflaster, das im äußern Vorhof war, dazu Altanen auf drei Seiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Denn vor den Zellen her lief ein zehn Ellen breiter Gang ins Innere. Der eigentliche Weg war eine Elle breit, und ihre Türen gingen gegen Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Die oberen Gemächer waren niedriger - denn die Altanen nahmen Raum von ihnen - als die unteren und mittleren des Baus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Sie lagen nämlich dreifach aufeinander und hatten keine Pfeiler wie die Vorhöfe. Drum war die Grundfläche mehr eingezogen als bei den unteren und mittleren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Die Mauer außen, an die Gemächer stießen, die nach dem äußern Hofe vor den Zellen lief, betrug in ihrer Länge fünfzig Ellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Denn die Gemächer an dem äußern Hofe waren fünfzig Ellen lang, wie die dem Tempel zugekehrte Seite hundert Ellen maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Von untenher ging man zu diesen Zellen ein, von Osten her für den, der aus dem äußern Vorhof sie betritt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Und an der breiten Vorhofmauer gegen Osten zu, gerade vor dem Platze und dem Bauwerk waren Zellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Es war ein Gang vor ihnen wie vor den Zellen an der Nordseite, und wie bei jenen waren Länge, Breite, Ausgänge nach Schwellen und nach Türen gleich beschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'So waren auch die Türen der nach Süden zu gelegenen Gemächer. Am Anbeginn des Gangs lag eine Tür, des Gangs an der geraden Mauer, die gegen Osten schaut, beim Aufgang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Er sprach zu mir: \"Die Zellen gegen Norden und die gegen Süden, die vor dem Platze liegen, sind heilige Gemächer, worin die Priester, die dem Herrn sich nähern dürfen, Hochheiliges verzehren, und wo sie das Hochheilige verwahren sollen, das Speise-, Sünd- und Schuldopfer. Der Ort ist nämlich heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Und sind die Priester eingetreten, dann sollen sie nicht aus dem Heiligtum zum äußern Vorhof gehen. Sie sollen vielmehr hier die Kleider niederlegen, in denen sie den Dienst verrichten; denn sie sind heilig. Sie sollen sich in andere Gewänder kleiden, wenn sie zu dem fürs Volk bestimmten Platze gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Er hörte nunmehr auf, das innere Gebäude auszumessen. Dann führte er mich durch das Tor hinaus, das gegen Osten lag, und maß es ringsherum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Er maß die Morgenseite mit dem Maßstabe: fünfhundert Ellen nach dem Maßstab. Dann ging er hin');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'und maß die Nordseite: fünfhundert Ellen nach dem Maßstab. Dann ging er hin');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'und maß die Südseite: fünfhundert Ellen nach dem Maßstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Dann ging er zu der Westseite und maß: fünfhundert Ellen nach dem Maßstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Nach den vier Winden maß er\'s aus. Es hatte aber eine Mauer ringsherum: fünfhundert in der Länge, fünfhundert in der Breite, um so das Heilige von dem Gemeinen abzusondern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Er führte mich zum Tore hin, zum Tor, das gegen Osten sah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Und sieh! Da zog die Herrlichkeit des Gottes Israels von Osten her. Ihr Brausen glich dem Brausen vieler Wasser; die Erde leuchtete von seiner Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Der Anblick des Gesichtes, das ich sah, war dem Gesichte gleich, das ich gesehn, als er erschien, die Hauptstadt zu zerstören. Und beide glichen dem Gesicht, das ich am Kebarflusse sah. Da fiel ich auf das Antlitz nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Die Herrlichkeit des Herrn zog in das Haus, durchs Tor, das gegen Osten sah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Ein Geist hob mich empor und brachte mich so in den innern Hof. Und sieh! Die Majestät des Herrn erfüllte ganz das Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Nun hörte ich jemand vom Haus her zu mir reden; dabei stand neben mir der Mann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Er sprach zu mir: \"Du Menschensohn! Dies ist der Ort für meinen Thron und dies der Schemel meiner Füße, wo ich für immer bei den Söhnen Israels verweile. Das Haus von Israel entweiht nicht fürderhin mehr meinen heiligen Namen mit seinen Königen durch seine Buhlerei und durch die Leichen seiner Könige in ihrem Grabgewölbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Sie setzten ihre Schwelle ja an meine Schwelle und ihren Pfosten neben meinen Pfosten, daß zwischen mir und ihnen einzig sich die Wand befand und sie so meinen heiligen Namen unrein machten durch ihre Greuel, die sie übten. Ich mußte sie in meinem Zorn vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Jetzt aber halten sie ihr Buhlen fern von mir sowie die Leichen ihrer Könige. So kann ich allzeit unter ihnen wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Du aber, Menschensohn, beschreibe jetzt dem Hause Israel das Haus, daß sie sich ihrer Missetaten schämen, wenn sie das Bauwerk messen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Und schämen sie sich alles dessen, was sie taten, dann zeige ihnen die Gestalt des Hauses und seine Einrichtung und seine Aus- und Eingänge, wie alles in ihm eingerichtet ist und alles in ihm festgestellt und alles in ihm angeordnet und alles vorgeschrieben! Und zeichne es vor ihnen auf, damit sie es befolgen, genau so wie es eingerichtet und befohlen ist, und sie sich danach richten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Des Hauses Grundgesetz ist dies: Auf höchster Bergeshöhe sei ganz heilig rings sein voller Umkreis! Sieh! Dies ist des Hauses Grundgesetz,\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Dies aber sind die Maße des Altars in Ellen, die Elle eine Handbreit länger als die Elle sonst; der Fuß ist eine Elle tief und eine breit; sein Rand ringsum nur eine Spanne breit, und dies ist des Altars Gestell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Und von dem Fuß am Boden bis zum untern Absatz, zwei Ellen hoch und eine breit, von diesem kleinem Absatz bis zum größeren vier Ellen hoch und eine breit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Der Opferherd darauf vier Ellen, und schräg aufwärts vom Opferherd erhoben sich vier Hörner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Der Opferherd war selbst zwölf Ellen lang sowie zwölf Ellen breit, so daß ein Viereck seine Seiten bildeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Der Absatz vierzehn Ellen lang und vierzehn Ellen breit nach allen den vier Seiten, der eine halbe Elle breite Rand ging ringsherum. Der Fuß war eine Elle hoch, und seine Treppenstufen gingen gegen Osten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Er sprach zu mir: \"Hör, Menschensohn! So spricht der Herr, der Herr: \'Dies wird für den Altar bestimmt, sobald er fertig ist, daß man Brandopfer auf ihn lege und ihn mit Blut besprenge.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Du sollst den Priestern, den Leviten, die vom Geschlechte Sadoks sind und die allein zum Dienste sich mir nähern dürfen\", ein Spruch des Herrn, des Herrn, \"ein Jungrind zum Sündopfer übergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Dann nimm etwas von seinem Blut, bestreich damit die vier Altarhörner sowie die Ecken an dem Absatz und die Leisten ringsherum, und so entsühne und entsündige ihn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Dann nimm das Rind, das Sündopfer, damit man es an dem bestimmten Platz des Hauses, ganz außerhalb des Heiligtums, verbrenne!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Am zweiten Tage sollst du einen fehlerlosen Ziegenbock als Sündopfer darbringen, daß man den Altar so entsündige, wie man durch Farren ihn entsündigt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Und bist du mit Entsühnen fertig, dann hast du einen fehlerlosen jungen Stier zu opfern und einen fehlerlosen Widder aus dem Kleinvieh.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Die sollst du vor den Herrn hinbringen! Die Priester sollen sie mit Salz bestreuen und sie dem Herrn als Brandopfer darbringen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Du sollst dann sieben Tage täglich einen Bock zum Sündopfer herrichten, auch einen jungen Stier und einen Widder aus dem Kleinvieh, völlig fehlerlos. Die sollen sie herrichten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Und sieben Tage nacheinander sollen sie entsündigen den Altar und ihn reinigen und einweihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Und haben sie die Tage so beendigt, so sollen dann am achten Tag und weiterhin die Priester auf dem Altar eure Brand- und Heilsopfer darbringen! Dann nehme ich euch gnädig an.\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Er führte mich hierauf zurück zum äußern Tor des Heiligtums, das sich gen Osten wendet; es war verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Dann sprach zu mir der Herr: \"Verschlossen bleibt dies Tor; es wird nicht aufgemacht, und niemand darf\'s betreten, ist doch der Herr, Gott Israels, durch dieses eingezogen. Darum soll es verschlossen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Der Fürst allein, nur er, der Fürst, darf drin verweilen, um vor dem Herrn die Mahlzeit einzunehmen. Dann geh er durch die Vorhalle hinein! Doch muß er wieder auf dem selben Weg hinaus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Er führte mich hierauf zum Nordtor vor dem Hause hin. Und als ich hinsah, füllte schon die Herrlichkeit des Herrn das Haus des Herrn. Da fiel ich auf mein Antlitz nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Er sprach: \"Hör, Menschensohn! Gib acht und sieh mit deinen Augen und hör mit deinen Ohren, was immer ich jetzt mit dir rede von allen Anordnungen fürs Haus des Herrn und allen seinen Dienstverordnungen! Und merk dir, was das Kommen in das Haus betrifft, und das Herausgehn aus dem Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'So sprich zu den Unfolgsamen, zum Hause Israel: So spricht der Herr, der Herr: \'Haus Israel, genug mit euren Greueln,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'daß ihr den Fremden, Unbeschnittenen an Herz und Leib den Einlaß in mein Heiligtum gewährtet und mein Haus entweihtet! Ihr ließet meine Speise, Fett und Blut, darbringen. So brach man meinen Bund zu allen euren Greueln hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Ihr tatet selber nicht den Dienst in meinem Heiligtum. Nein, ihr bestelltet andere, die dann für euch den Dienst in meinem Heiligtum getan.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Deshalb spricht so der Herr, der Herr: \'Kein Fremder und kein Unbeschnittener an Herz und Leib darf je mein Heiligtum betreten, kein einziger der Fremdlinge, die bei den Söhnen Israels verweilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Ja wahrlich, die Leviten, die sich von mir entfernten, als Israel, zum Götzendienste sich verirrend, mich verließ, sie haben auch für ihre Missetat zu büßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Sie sollen zwar in meinem Heiligtum Dienst tun als Wachen an des Hauses Türen, und andre Dienste in dem Hause. Sie sollen Brand- und Schlachtopfer dem Volke schlachten und ihm bereit zu andern Diensten stehn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Weil sie vor ihren Götzen ihnen Dienst getan und so dem Hause Israel zur Sünde Anlaß wurden, deswegen schwöre ich auch ihnen mit erhobener Hand\', ein Spruch des Herrn, des Herrn, \'sie sollen ihre Missetat jetzt büßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Sie dürfen sich nicht mir zu Priesterdiensten nahen, noch irgendeinem meiner Heiligtümer und nicht dem Allerheiligsten. Sie müssen vielmehr ihre Schande büßen und ihre Greuel, die sie ausgeübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Und ich bestimme sie zur Wache in dem Haus, zu aller Arbeit und zu allem, was darin zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Die Priester, die Leviten, Sadoksöhne, die Dienst an meinem Heiligtum getan, als sich die Söhne Israels von mir verirrten, sie sollen Zutritt zu mir haben und bei mir Dienst tun. Sie dürfen vor mich treten, Fett und Blut mir darzubringen.\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, '\'Sie dürfen in mein Heiligtum eintreten und meinem Tische sich, mir dienend, nahen und meines Dienstes warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Und kommen sie dann in des innern Hofes Tore, haben sie sich linnene Gewänder anzulegen. Sie dürfen nichts von Wolle bei der Dienstverrichtung tragen im Haus und in des innern Hofes Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Von Leinwand soll die Kopfbedeckung sein, von Leinwand auch die Beinkleider um ihre Lenden, aber nicht zu fest gebunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Und gehn sie in den äußern Hof zum Volk hinaus, so haben sie die Kleider abzulegen, worin sie Dienst getan, und in die heiligen Gemächer zu verbringen und andre anzulegen, damit sie nicht dem Volk begegnen in ihren Dienstkleidern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ihr Haupthaar sollen sie nicht kahl abscheren, auch nicht in langen Locken fliegen lassen, nein, nur gestutzt ihr Haupthaar tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Ein Priester soll nicht vorher Wein genießen, wenn er den inneren Hof betritt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Sie dürfen keine Witwe noch Verstoßene heiraten, nur Jungfraun aus dem Stamm des Hauses Israel und nachgelassene Priesterwitwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Sie sollen auch mein Volk belehren, was für ein Unterschied ist zwischen Heilig und Gemein und zwischen Rein und Unrein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Bei einem Streitfall sollen sie die Richter sein, nach meinem Rechte ihn entscheiden, und meine Weisungen sowie Gesetze sollen sie befolgen insgesamt für meine Feste und auch meine Sabbattage heiligen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Zu keinem toten Menschen darf er gehn, damit er nicht unrein werde. Nur bei dem Vater und der Mutter und dem Sohne und der Tochter, dem Bruder und der Schwester, die nicht eines Mannes ist, da dürfen sie sich unrein machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Und ist er wieder rein geworden, dann zählt man ihm noch sieben Tage ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Und kommt er dann ins Heiligtum und in den innern Hof, um seinen Dienst im Heiligtum zu tun, so bringe er sein Sündopfer jetzt dar!\' Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, '\'Auch müssen sie ein Eigentum besitzen; dieses will ich ihnen sein. Ihr braucht daher kein Eigentum in Israel noch ihnen einzuräumen; ich selber will es ihnen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Von Speise-, Sünd- und Sühneopfern sollen sie sich nähren, und alles, was in Israel dem Bann verfällt, soll ihnen eigen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Der erste Abhub aller Erstlinge von jeder Art und jegliches Geschenk von allen euren Hebeopfern gehören nur den Priestern. Den ersten Abhub eures Teiges sollet ihr den Priestern geben, um so den Segen über euer Haus zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Doch nichts Gefallenes und nichts Zerrissenes, sei\'s von den Vögeln, sei\'s vom Wild, ist Priestern zum Genuß gestattet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '\"Verloset ihr das Land zum Erbbesitz, dann sondert von dem Land dem Herren eine heilige Gabe ab, an fünfundzwanzigtausend Ellen lang und zwanzigtausend Ellen breit! In seinem ganzen Umfang sei es ringsum heilig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Fünfhundert im Gevierte sollen davon zu dem Heiligtum gehören; ein freier Platz von fünfzig Ellen ziehe sich ringsum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Von diesem Maß miß fünfundzwanzigtausend in die Länge, zehntausend in die Breite! Drauf komme dann das Heiligtum, das Allerheiligste, zu stehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Dies von dem Land sei heilig! Den Priestern, die das Heiligtum bedienen, soll\'s gehören, die Zutritt haben, um dem Herrn zu dienen. Als Platz für Häuser soll es dienen, ein Heiligtum beim Heiligtum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Und fünfundzwanzigtausend in die Länge, zehntausend in die Breite, sie sollen den Leviten, die den Dienst am Hause tun, als Grundbesitz anheimfallen nebst zwanzig Vorratskammern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Der Stadt gebt ihr zum Eigentum fünftausend in die Breite und fünfundzwanzigtausend in die Länge, entsprechend jener heiligen Gabe! Dem ganzen Hause Israel soll es gehören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Dem Fürsten aber sollt ihr geben zu beiden Seiten des dem Heiligtum geweihten Bodens sowie des Eigentums der Stadt, und zwar vor dem dem Heiligtum geweihten Boden und vor dem Eigentum der Stadt im Westen gegen Westen, im Osten gegen Osten, wie eines Stammes Erbteil lang, von seiner Abendgrenze bis zur Morgengrenze!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Das Land gehöre ihm als Grundbesitz in Israel, daß meine Fürsten nicht mein Volk mehr weiter drücken! Sie sollen nur das Land dem Hause Israel nach seinen Stämmen lassen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'So spricht der Herr, der Herr: \"Laßt\'s nun genug sein, Fürsten Israels! Laßt von Gewalt und Unterdrückung ab und übt Gerechtigkeit und Recht! Mit dem Verjagen meines Volkes höret auf!\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, '\"Nur rechte Waage führt; ein richtiger Scheffel und ein richtiger Eimer soll es sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Gleich sollen Eimer sein und Scheffel! Den zehnten Teil des Malters soll der Eimer sein, den zehnten Teil des Malters auch der Scheffel! Nach Malter hat sich beider Maß zu richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Der Ring soll zwanzig Korn betragen! Nur fünfundzwanzig, zwanzig, fünfzehn Ringe sollt ihr haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Die Gabe, die ihr spenden sollt, ist die: Vom Malter Weizen ist\'s ein Sechstel eines Scheffels. Vom Malter Gerste nehmt ihr auch ein Sechstel eines Scheffels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Der pflichtgemäße Teil des Öls beträgt vom Maß das Zehntel eines Eimers. Zehn Eimer geben einen Malter; es sind zehn Eimer auch ein Malter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Ein Schaf aus einer Herde von zweihundert von der Tränke Israels, das diene für die Speise-, Brand- und Mahlopfer, um Sühne euch zu schaffen!\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, '\"Verpflichtet sei das ganze Volk des Landes zu dieser Gabe für den Fürsten Israels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Dem Fürsten aber liegen ob die Brand- und Speise- und Trankopfer an Festen, Neumonden und Sabbaten, bei allen Festen fürs Haus Israel. Er stelle auch das Sünd- und Speiseopfer und das Brand- sowie die Mahlopfer, zur Sühnung für das Haus von Israel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So spricht der Herr, der Herr: \"Am ersten Tag des ersten Monats hol einen fehlerlosen jungen Stier zu der Entsündigung des Heiligtums!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Der Priester nehme von dem Blut des Sündopfers und tu dies an des Hauses Pfosten, an die vier Ecken an dem Absatz des Altars und an des Tores Pfosten in dem innern Hof!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tu so am siebten Tag des Monats! Entsündigt so das Haus, der Leute wegen, die aus Irrtum oder Einfalt sündigten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Im ersten Mond, am Tage vierzehn, sollet ihr das Passah feiern, ein Fest von sieben Tagen, da ungesäuert Brot gegessen wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'An jenem Tage soll der Fürst für sich und für das ganze Volk des Landes den Farren stellen für das Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Und diese sieben Feiertage stelle er dem Herren Brandopfer, je sieben Farren, sieben fehlerlose Widder, an jedem Tag der sieben Tage, und täglich einen Ziegenbock als Sündopfer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Zum Speiseopfer aber bringe er auf jeden Farren einen Scheffel dar, auf jeden Widder einen Scheffel und auf den Scheffel einen Krug voll Öl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'im siebten Mond, am Tage fünfzehn, soll er an dem Fest, wie an den sieben Tagen, die Sünd- und Brand- und Speiseopfer samt dem Öl darbringen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So spricht der Herr, der Herr: \"Das Tor des innern Hofes, das nach Osten geht, soll fest verschlossen bleiben durch sechs Werktage! Geöffnet wird\'s am Sabbat; am Neumondstage wird es auch geöffnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Der Fürst nimmt seinen Eingang durch die äußre Torhalle und bleibt hier an des Tores Pfosten stehen. Die Priester bringen dar sein Brand- und seine Friedensopfer. Er betet an des Tores Schwelle und geht hinaus. Das Tor sei bis zum Abend unverschlossen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Das Volk des Landes aber betet vor dem Herrn am Eingang dieses Tores an Sabbaten und Neumonden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Das Brandopfer, das an dem Sabbat der Fürst dem Herrn darbringt, bestehe aus sechs fehlerlosen Lämmern, einem fehlerlosen Widder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'nebst einem Speiseopfer! Auf jeden Widder einen Scheffel und auf die Lämmer so viel, wie er geben will, und einen Krug voll Öl auf jeden Scheffel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Am Neumond sei\'s ein fehlerloser junger Stier sowie sechs fehlerlose Lämmer, dazu ein fehlerloser Widder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Zum Speiseopfer stelle er dann einen Scheffel für den Stier und einen Scheffel für den Widder und für die Lämmer so viel, wie er geben will, und einen Krug voll Öl auf jeden Scheffel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Und geht der Fürst hinein, so nimmt er seinen Eingang durch die äußre Torhalle, und auf demselben Weg geht er hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Erscheint das Volk des Landes an Festen vor dem Herrn, alsdann geht, wer durchs Nordtor anzubeten kam, durchs Südtor wieder fort, und wer durchs Südtor kam, durchs Nordtor; man kehrt nicht durch das Tor zurück, durch das man kam; durchs gegenüberliegende geht man hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Der Fürst sei in des Volkes Mitte beim Ein- und Ausgehn!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'An Festen und an Feiertagen kommt zum Speiseopfer auf den Stier ein Scheffel sowie ein Scheffel auf den Widder und auf die Lämmer so viel, wie man geben will, und auf den Scheffel ein Krug Öl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Und bringt der Fürst dem Herrn freiwillig, sei es ein Brand-, sei es ein Mahlopfer als freie Gabe für den Herrn, dann schließe man das Tor ihm auf, das gegen Osten schaut! Er bringe dar sein Brand- und seine Mahlopfer, wie er\'s am Sabbat für gewöhnlich tut! Geht er hinaus, so wird das Tor nach seinem Weggang zugeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Ein noch nicht jährig, fehlerloses Lamm wirst du dem Herrn an jedem Tag als Brandopfer darbringen. Bring es an jedem Tag dem Herrn als Brandopfer, an jedem Morgen dar!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Als Speiseopfer bring jeden Morgen ihm den sechsten Teil des Scheffels, an Öl den dritten Teil des Kruges und träufle dieses auf das Mehl als Speiseopfer für den Herrn nach einer ewig dauernden Verordnung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Das Lamm, das Speiseopfer und das Öl, die bringe man als regelmäßiges Brandopfer alle Morgen dar!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So spricht der Herr, der Herr: \"Wenn von dem zugeteilten Land ein Stück der Fürst an einen seiner Söhne schenkt, so hat dies seinen Söhnen zu verbleiben; es wird ihr Erbbesitz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Wenn er von seinem Lande etwas einem seiner Diener schenkt, alsdann gehört es diesem bis zum Freiheitsjahr; hierauf fällt\'s wieder an den Fürsten. Sein Eigentum geht nur an seine Söhne über.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Vom Eigentum des Volkes nehme nie der Fürst etwas hinweg, verdränge niemand aus dem Erbbesitz! Er gebe einzig seinen Söhnen aus seinem Grundbesitz ein Erbe! Denn keiner meines Volkes soll aus dem Erbbesitz vertrieben werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Er brachte mich zum Eingang an der Seitenwand des Tors zu den Gemächern in dem Heiligtum, die für die Priester waren und nach Norden lagen. Da war ein Raum an beiden Ecken gegen Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Er sprach zu mir: \"Dies ist der Raum, in dem die Priester Fleisch der Schuld- und Sündopfer garkochen, wo sie das Speiseopfer backen, so daß man\'s durch den äußern Hof nicht tragen muß. Sonst wird das Volk dadurch geheiligt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Er führte mich zum äußern Hof und ließ mich die vier Ecken in dem Hof betrachten, und sieh, in jeder Ecke in dem Hof war ein besondres Höfchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'In den vier Ecken dieses Hofes waren ganz verrauchte Vorhöfe, an vierzig Ellen lang und dreißig breit; von gleichem Maße waren die vier Ecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Es hatten diese vier ein Mauerwerk ringsum, und Küchen waren unter diesen Mauern angelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Er sprach zu mir: \"Dies sind die Küchen, wo für das Volk des Hauses Diener das Schlachtopfer garkochen sollen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Er brachte mich zurück zur Tür des Hauses; siehe, Wasser sprudelte hervor gen Osten unter jenes Hauses Schwelle. Des Hauses Vorderseite sah ja gegen Osten; das Wasser aber floß zur rechten Seite dieses Hauses, auf der Südseite des Altars.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Er führte mich zum Nordtore hinaus und auf dem Außenweg herum zum äußern Tor, das gegen Morgen liegt. Da quoll das Wasser an der rechten Seitenwand hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Der Mann ging gegen Osten mit einer Schnur in seiner Hand; dann maß er tausend Ellen ab und hieß mich durch das Wasser gehn, das bis zum Knöchel reichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Er maß aufs neue tausend Ellen ab und hieß mich durch das Wasser gehn. Es ging bis an die Knie. Er maß aufs neue tausend Ellen ab und hieß mich durch das Wasser gehn. Es reichte an die Hüften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Er maß noch tausend Ellen ab, da war\'s ein Strom, durch den ich nicht mehr schreiten konnte. Das Wasser war zu tief, ein Wasser nur zum Schwimmen, ein Strom, nicht zu durchwaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Er sprach zu mir: \"Hast du\'s gesehen, Menschensohn?\", und führte zu des Stromes Ufer mich zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Bei meiner Rückkehr sah ich an des Flusses Ufer auf beiden Seiten viele Bäume stehn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Er sprach zu mir: \"Dies Wasser fließt zur Markung des Ostens hin und läuft hinab zur Ebene und fällt ins Meer. Kommt dieses Wasser in das Meer, dann wird das Wasser dort gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Und jedes lebende Geschöpf, das sich bewegt, zu dem die beiden Arme des Stromes kommen, wird mit Lebenskraft erfüllt. Sehr viele werden\'s sein, denn jenes Wasser kommt dahin. Dann wird ein jegliches gesund, voll Lebenskraft, zu dem sich so der Strom ergießt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'An seiner Seite stehen Fischer von Engaddi bis nach Eglaim. Zum Netzetrocknen gibt es einen Platz. Ihr Fischreichtum wird ganz gewaltig groß wie der des Weltmeers sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Nur seine Tümpel, seine Lachen, werden nimmer süß gemacht, weil sie bestimmt zur Salzgewinnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Und an des Stromes Ufern auf den beiden Seiten sprießen allerlei Fruchtbäume, und ihre Blätter welken nicht, und ihre Fruchtbarkeit erschöpft sich nicht. In dem bestimmten Monat tragen sie frühzeitig Frucht. Denn aus dem Heiligtum fließt ihr Gewässer her. Zur Nahrung dienen ihre Früchte und ihre Blätter zur Arznei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So spricht der Herr, der Herr: \"Das ist die Grenzbestimmung nun, nach der das Land ihr unter die zwölf Stämme Israels verteilen sollt. Zwei gleiche Teile werden Joseph zugeteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Und dann verteilt ihr es, dem einen gleich so viel wie seinem Bruder! Ich schwur mit aufgehobener Hand, es euren Vätern einzuräumen. Nun wird euch dieses Land als Erbbesitz zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Dies sind die Landesgrenzen: Die nördliche geht von dem großen Meer auf Chetlon bis nach Sedad zu,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'nach Chamat, Berot und Sibraim, das zwischen dem Gebiete von Damaskus und dem von Chamat liegt, und nach dem mittleren Chaser, das an der Grenze Haurans liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Die Grenze geht vom Meer bis Chasar Enon. Das Damaszenerland im Norden, gegen Norden das Gebiet von Chamat, das ist die Nordseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Es zieht die Ostseite sich zwischen Hauran und Damaskus und Gilead, hierauf zum Lande Israel dem Jordan zu. Und von dem Ufer bis zum Ostmeer sollt ihr messen! Dies ist die Ostseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Die Südseite zieht gegen Mittag zu, von Tamar bis zum Haderwasser bei Kades und nach dem Tal zum großen Meer; das ist die Südseite gen Mittag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Die Westseite wird von dem großen Meer gebildet, von da an bis nach Chamat hin; das ist die Westseite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Dies Land verteilet unter euch, den Stämmen Israels entsprechend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Verlost es unter euch als Erbbesitz und unter jene Fremden, die bei euch geweilt und die auch Kinder unter euch gezeugt! Denn diese seien euch wie Eingeborene Söhne Israels! Sie sollen mit euch losen auch um das Besitztum mitten bei den Stämmen Israels!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Und in dem Stamm, in dem ein jeglicher als Fremdling weilt, dort sollt ihr seinen Erbbesitz ihm geben!\" Ein Spruch des Herrn, des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '\"Dies sind der Stämme Namen: Am Nordende am Weg nach Chetlon hin bis da, wo man nach Chamat geht, und von Chasar Enan bis zu der Grenze vor Damaskus gegen Norden und bis Chamat, von Osten bis nach Westen: ein Erbteil: Dan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Und neben dem Gebiet von Dan von Osten bis nach Westen eines: Aser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Und neben dem Gebiet von Aser von Osten bis nach Westen eines: Naphtali.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Und neben dem Gebiet von Naphtali von Osten bis nach Westen eins: Manasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Und neben dem Gebiete von Manasse von Osten bis nach Westen eines: Ephraim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Und neben dem Gebiet von Ephraim von Osten bis nach Westen eines: Ruben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Und neben dem Gebiet von Ruben von Osten bis nach Westen eines: Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Und neben dem Gebiet von Juda von Osten bis nach Westen ist der geweihte Landstrich, den ihr abzusondern habt, an fünfundzwanzigtausend Ellen breit und lang, wie alle andern Teile vom Osten bis zum Westen, das Heiligtum in seiner Mitte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Und der geweihte Landstrich, den ihr für den Herrn absondern müßt, hat in der Länge fünfundzwanzigtausend Ellen, zehntausend in der Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Und der geweihte Landstrich sei den Priestern eigen, nach Norden fünfundzwanzigtausend Ellen lang, nach Westen hin zehntausend Ellen breit, nach Osten auch zehntausend breit, nach Süden fünfundzwanzigtausend lang! Und in der Mitte liegt das Heiligtum des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Geweiht ist es den Priestern, jenen Sadoksöhnen, die meinen Dienst getreu besorgt und die sich nicht verirrt wie einst die Söhne Israels und nicht wie die Leviten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Das Beste von dem Land soll ihnen als Hochheiliges eigen sein, an der Leviten Grenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Was die Leviten anbetrifft, so ist, entsprechend dem Gebiet der Priester, das ihre fünfundzwanzigtausend lang, zehntausend breit, die ganze Länge fünfundzwanzigtausend und zehntausend seine Breite.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Sie dürfen nichts davon verkaufen, nichts davon vertauschen. Das beste Stück des Landes darf nicht veräußert werden, weil es heilig ist dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Fünftausend Ellen aber, die noch in der Breite übrig, nebst den fünfundzwanzigtausend in der Länge, sind für die Stadt gemeines Land zum Wohnen sowie Weideplätze. Die Stadt sei in der Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Und dies sind ihre Maßverhältnisse: Die Nordseite hat an viertausend und fünfhundert Ellen, die Südseite viertausend und fünfhundert, die Ostseite viertausend und fünfhundert, die Westseite viertausend und fünfhundert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Besitzen soll die Stadt ein Weideland nach Norden an zweihundertfünfzig Ellen, nach Süden zu zweihundertfünfzig, nach Osten auch zweihundertfünfzig, nach Westen ebenfalls zweihundertfünfzig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Und was noch in der Länge übrig ist, von dem geweihten Stück des Heiligtumes abgesehen, zehntausend Ellen gegen Osten, zehntausend gegen Westen, ganz abgesehen vom geweihten Stück des Heiligtums, davon soll der Ertrag zur Nahrung denen dienen, die ihren Dienst der Hauptstadt widmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Und wer der Hauptstadt Dienste tut, für den soll man aus allen Stämmen Israels gut sorgen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'All das geweihte Land an fünfundzwanzigtausend Ellen, zu fünfundzwanzigtausend im Geviert, sollt ihr als heilig Stück zu dem Besitz der Stadt hin aussondern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Was dann noch übrigbleibt, gehört dem Fürsten, zu beiden Seiten des geweihten Stückes und des Eigentums der Stadt, vor jenen fünfundzwanzigtausend Ellen des geweihten Landes bis zu der Grenze gegen Osten und westwärts vor den fünfundzwanzigtausend bis zu der Grenze gegen Westen, entsprechend jenen Teilen. Das sei des Fürsten! Doch das geweihte Land des Heiligtums sowie des Hauses Heiligtum sei mitten drin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Was, abgesehn vom Eigentume der Leviten und der Stadt, inmitten dessen, was des Fürsten ist, in dem Gebiet von Benjamin und Juda liegt, das soll dem Fürsten eigen sein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Was nun die andern Stämme anbetrifft, so liegt für Benjamin ein Teil vom Osten bis zum Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Und an der Grenze Benjamins für Simeon ein Teil vom Osten bis zum Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Und an der Grenze Simeons für Issakar ein Teil vom Osten bis zum Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Und an der Grenze Issakars für Zabulon ein Teil vom Osten bis zum Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Und an der Grenze Zabulons für Gad ein Teil vom Osten bis zum Westen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Und an der Grenze Gads nach Süden auf der Mittagsseite soll sich die Grenze hinziehn von Tamar bis zum Haderwasser bei Kades und zu dem Tale bis ans große Meer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Dies ist das Land, das ihr als Erbbesitz den Stämmen Israels verlosen sollt, und das sind ihre Erbteile.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Ein Spruch des Herrn, des Herrn. 30 \"Dies sind die Ausgänge der Stadt: viertausend und fünfhundert nach Maßen auf der Seite gegen Norden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Der Hauptstadt Tore heißen nach den Stämmen Israels. Drei Tore liegen gegen Norden: das Tor des Ruben eines, das Tor des Juda eines, das Tor des Levi eines.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Und gegen Osten viertausend und fünfhundert; da liegen auch drei Tore: das Tor des Joseph eines, das Benjaminstor eines, das Tor des Dan auch eines.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Und gegen Mittag viertausend und fünfhundert nach dem Maß, da liegen auch drei Tore: das Tor des Simeon eines, das Tor des Issakar eines, das Tor des Zabulon auch eines.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Und gegen Westen viertausend und fünfhundert; da liegen auch drei Tore: das Tor des Gad eines, das Tor des Aser eines, das Tor des Naphtali auch eines.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Im Umkreis sind es achtzehntausend Ellen. Die Stadt heißt von dem Tage an: \'Der Herr ist dort.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Im dritten Jahr der Herrschaft Jojakims, des Judakönigs, kam Nebukadrezar, der Babelkönig, nach Jerusalem und schloß es ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Da gab der Herr den Judakönig Jojakim mitsamt den besten Stücken aus dem Gotteshaus in seine Hand. Er brachte diese in das Sinearland in seines Gottes Haus. Doch die Geräte brachte er ins Schatzhaus seines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Und da befahl der König dem Obersten der Kämmerlinge, Aspenaz, er solle von den Söhnen Israels aus königlichem wie aus adligem Geblüt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'ihm Knaben bringen, an denen gar nichts auszusetzen sei, von schönem Angesicht, in allem Wissen wohl bewandert, kenntnisreich und gut erzogen, die die Fähigkeit besäßen, im Palast des Königs aufzuwarten, damit er sie in der Chaldäer Schrift und Sprache unterrichten lassen könne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Auch wies der König ihnen ihren Unterhalt für jeden Tag vom königlichen Tische an und von dem Weine, den er selber trank, daß sie, drei Jahre lang gut ausgebildet, in die königlichen Dienste treten könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Darunter waren Daniel und Ananias, Misael und Azarias aus dem Stamme Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Der Oberkämmerer gab ihnen andre Namen. Den Daniel hieß er Baltasar, den Ananias Sidrach, Misach den Misael, Abdenago den Azarias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Doch Daniel nahm sich im Herzen vor, sich weder durch des Königs Speise noch durch den Wein, den jener trank, unrein zu machen. Und so erbat er sich vom Oberkämmerer, daß er sich nicht unrein machen müsse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Und Gott ließ Daniel beim Oberkämmerer Nachsicht und Gnade finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Doch sprach der Oberkämmerer zu Daniel: \"Ich fürchte meinen Herrn, den König, der euch Speis und Trank bestimmte. Fänd er, daß euere Gesichter schmächtiger als die der andern Knaben eures Alters wären, so brächtet ihr beim König mich um meinen Kopf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Darauf sprach Daniel zum Wächter, den der Oberkämmerer über Daniel und Ananias, Misael und Azarias gesetzt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '\"Versuch es bitte doch zehn Tage lang mit deinen Knechten. Man gebe nur Gemüse uns zu essen und nur Wasser uns zu trinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Besieh dann unsere Gesichter und die der andern Knaben, die von der königlichen Kost genießen! Und je nachdem, wie dein Befund ausfällt, magst du mit deinen Knechten dann verfahren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Auf diese Rede hin versuchte er\'s zehn Tage lang mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Nach Ablauf der zehn Tage aber waren ihre Angesichter sichtlich schöner wie auch voller als die aller andern Knaben, die von der königlichen Speise zu genießen pflegten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'So ließ fortan der Wächter ihre Speise wegnehmen samt dem Wein, den sie genießen sollten; er brachte ihnen dafür nur Gemüse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Doch den vier Knaben gab die Gottheit Wissen und Verständnis für jede Schrift und Wissenschaft; dem Daniel Verständnis auch für jederart Gesichte und für Träume.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Und nach Verlauf der Zeit, nach der der König ihre Vorstellung befohlen, stellte sie der Oberkämmerer Nebukadrezar vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Da unterredete der König sich mit ihnen, und unter allen andern fand sich keiner so wie Daniel und Ananias, Misael und Azarias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Sooft der König sie befragte in den Fällen, bei denen es auf Weisheit ankam und auf Einsicht, da fand er sie in zehnfach größerem Maß bei ihnen als bei den Zauberern und Wahrsagern in seinem ganzen Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Und Daniel erlebte noch das erste Jahr des Königs Cyrus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Es war im zweiten Jahr der Herrschaft Nebukadrezars. Da träumte dem Nebukadrezar. Darüber wurde er in Angst versetzt; sein Schlaf ward ihm versagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Alsdann befahl der König, Zauberer, Beschwörer, Wahrsager, Chaldäer herzurufen, damit sie ihrem König deuteten, was er geträumt. Als sie nun kamen, stellten sie sich vor dem König auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Der König sprach zu ihnen: \"Ich habe einen Traum gehabt; ich weiß jedoch vor lauter Angst nicht mehr, was ich geträumt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Da sprachen die Chaldäer syrisch zu dem König:\"O König, mögst du ewig leben! Erzähle deinen Traum jetzt deinen Knechten! Dann sagen wir, was er bedeutet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Da hob der König an und sprach zu den Chaldäern: \"Das Wort steht meinerseits ganz fest: Wenn ihr den Traum samt seiner Deutung mir nicht sagt, dann werdet ihr zerstückelt, und eure Häuser werden Trümmerhaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Doch kündet ihr den Traum und seine Deutung, empfangt ihr von mir Auszeichnungen, Geschenke, große Ehre. So tut mir nun den Traum samt seiner Deutung kund!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Da hoben sie zum zweiten Male an und sprachen: \"Der König möge seinen Knechten doch den Traum erzählen! Dann sagen wir, was er bedeutet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Da hob der König an und sprach: \"Jetzt weiß ich ganz bestimmt, daß ihr nur Zeit gewinnen wollet, weil ihr wißt, daß mir der Traum entfallen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Könnt ihr mir demnach nicht den Traum angeben, dann gibt es nur ein Urteil über euch, daß eine falsche, trügerische Deutung ihr ersinnen wollt, um sie mir vorzutragen, bis die Zeit sich ändere. Deshalb sagt mir den Traum, damit ich überzeugt bin, daß ihr mir dessen rechte Deutung geben könnt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Da hoben die Chaldäer an und sprachen zu dem König: \"Auf Erden gibt es keinen Menschen, der leisten könnte, was du, König, forderst. Doch gibt\'s auch keinen König, noch so groß und mächtig, der solches zu erfahren wünscht von irgendeinem Wahrsager, von Zauberern und von Chaldäern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Was der König will, ist schwer, und niemand wird sich finden lassen, der ihm darüber Aufschluß geben könnte als die Götter. Doch diese haben ihre Wohnung nicht bei Sterblichen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Auf dies hin ward der König zornig und erbittert und befahl, die Weisen Babels alle hinzurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Als der Befehl erlassen war, ging man daran, die Weisen umzubringen. So sollten Daniel und die Gefährten ebenfalls getötet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Da wandte Daniel mit Klugheit und Geschick sich an den Obersten der Leibwachen, an Arioch, der ausgegangen war, die Weisen Babels hinzurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'So hob er an und sprach zu Arioch, dem königlichen Obersten: \"Aus welchem Anlaß ist vom König solch ein schrecklicher Befehl ergangen?\" Auf dies hin sagte Arioch dem Daniel den Sachverhalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Da schickte Daniel sich an zu bitten, daß ihm vom König eine Frist gegeben werde, um dem Könige die Deutung kundzugeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Darauf ging Daniel heim und teilte Ananias, Misael und Azarias diese Sache mit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'damit sie bei dem Gott des Himmels wegen des Geheimnisses um Gnade flehten, damit nicht Daniel und die Gefährten mit den andern Weisen Babels hingerichtet würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Da ward in einem Nachtgesicht dem Daniel das Geheimnis kund. Darauf pries Daniel den Gott des Himmels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Da hob er an und sprach:\"Gepriesen sei des Herren Name von Ewigkeit zu Ewigkeit! Sein ist die Weisheit und die Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Er ist\'s, der Zeiten und Geschlechter anders macht, der Könige einsetzt und sie wieder stürzt, der Weisen Weisheit gibt und Klugheit Klugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Er ist\'s, der Tiefes und Verborgenes offenbart, der weiß, was in der Finsternis geschieht, bei dem das Licht verweilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ich danke Dir, Gott unserer Väter. Ich preise Dich, weil Du mir Weisheit gabst und Kraft und Du mich wissen lässest, was wir von Dir erfleht. Du offenbartest uns des Königs Traum.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Hierauf ging Daniel zu Arioch, an den der König den Befehl gegeben, Babels Weise hinzurichten. Er ging und sprach zu ihm also: \"Laß Babels Weise nicht hinrichten! Führ mich zum König! Ich kann dem König jetzt die Deutung geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Da führte Arioch in aller Eile Daniel dem König vor und sprach zu ihm: \"Ich fand hier bei den jüdischen Verbannten einen Mann; der will dem König die Traumdeutung geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Da hob der König an und sprach zu Daniel, der auch Baltasar geheißen wurde: \"Glaubst du imstand zu sein, den Traum, den ich gehabt, und seine Deutung mir zu künden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Darauf hob Daniel an und sprach zum König: \"Die Weisen, Zauberer, Wahrsager sowie Zeichendeuter können dem König das Geheimnis, nach dem der König fragt, nicht kundtun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Dagegen gibt\'s im Himmel einen Gott, der die Geheimnisse enthüllen kann, und dieser offenbarte dem Könige Nebukadrezar, was am Ende der Tage einst geschehen wird. Mit deinem Traum und den Gesichten deines Hauptes auf deiner Lagerstätte ist es so:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Dir, König, stieg auf deinem Lager der Gedanke auf, was wohl hernach geschehen würde. Und der Geheimnisse eröffnet, tat dir kund, was noch geschehen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Doch dies Geheimnis ward mir nicht enthüllt durch Weisheit, die ich vor allen andern Menschen hätte. Nein, nur dazu, daß dem Könige die Deutung kund würde und du erführest die Gedanken deines Herzens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, König, sahst umher. Da schautest du ein großes Bild. Dies Bild war hoch, und prachtvoll war sein Glanz. Es stand vor dir, und schrecklich war es anzusehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Des Bildes Haupt war feines Gold, die Brust und Arme Silber, sein Bauch und seine Lenden Erz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'und seine Schenkel waren eisern, seine Füße teils von Eisen, teils von Ton.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Da sahst du, wie ein Stein sich losriß, ganz ohne menschlich Zutun. Er traf das Bild an seine Füße, die von Eisen teils und teils von Ton gebildet waren. Und er zermalmte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Zermalmt ward dann das Eisen insgesamt, das Erz, das Silber und das Gold; sie wurden wie die Spreu auf Sommertennen. Und diese trug der Wind davon, und dann war keine Spur von ihnen mehr zu finden. Der Stein hingegen, der das Bild zertrümmerte, der ward zu einem großen Berg und nahm die ganze Erde ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Dies ist der Traum. Doch auch die Deutung wollen wir jetzt vor dem König geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, König, bist König der Könige. Dir gab des Himmels Gott Gewalt und Ehre, Reich und Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Und alle Welt, wo Menschen wohnen, und des Feldes Tiere und des Himmels Vögel gab er dir in deine Hand, und alles unterwarf er deiner Herrschaft. Du bist das Haupt von Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Nach dir ersteht ein andres Reich, geringer als das deinige; darauf ein anderes, ein drittes Reich, von Erz, das alle Welt beherrscht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Ein viertes Reich wird stark wie Eisen sein. Geradeso wie Eisen alles ganz zertrümmert und zerschlägt, ja, so wie Eisen, das zerschmettert, so zertrümmert und zerschmettert\'s alle jene Reiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Daß du die Füße und die Zehen zum Teil aus Töpferton, zum Teil aus Eisen sahst, das deutet hin auf ein verschiedenartig Reich. Doch hat es Festigkeit von Eisen, weil du mit dem Töpferton gemischt das Eisen sahst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Die Zehen teils von Eisen, teils von Ton, bedeuten, daß das Reich zum Teil gar stark, zum Teil zerbrechlich ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Und daß du Eisen sahst gemischt mit Töpferton, bedeutet, daß sie mit dem Menschenstamm sich mischen, doch ohne daß sie fest dadurch zusammenhingen; auch Eisen mischt sich nicht mit Ton.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Und in den Tagen dieser Könige errichtet Gott ein Reich, das bis in Ewigkeit nicht mehr in Trümmer geht und dessen Herrschaft keinem andern Volke überlassen wird. Zertrümmern wird es und vernichten alle jene Reiche; selbst aber ewig dauern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Daß du jedoch gesehn, wie sich vom Fels ein Stein losriß, ganz ohne menschliches Zutun, und wie er Eisen, Erz, Ton, Silber, Gold zermalmte, dadurch hat ein großer Gott dem König kundgetan, was danach sich ereignet. Der Traum ist wahr, und zuverlässig seine Deutung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Da warf der König Nebukadrezar sich aufs Antlitz nieder, verehrte Daniel, und dann befahl er, Opfer ihm und Rauchwerk darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Dann hob der König an und sprach zu Daniel: \"Wahrhaftig! Euer Gott, er ist der Götter Gott, der Herr der Könige, der Offenbarer von Geheimnissen, kannst du doch dies Geheimnis offenbaren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Hierauf erwies der König dem Daniel große Ehre und gab ihm prächtige Geschenke; er übertrug ihm gänzlich die Verwaltung der Provinz von Babel und ernannte ihn zum Oberhaupt der Weisen Babels insgesamt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Doch Daniel erbat sich von dem König, er möge die Verwaltung der Provinz von Babel Sidrach, Misach und Abdenago verleihen. Und so blieb Daniel am Hof des Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Da ließ König Nebukadrezar ein golden Bild von sechzig Ellen Höhe und sechs Ellen Breite machen und stellte dieses in der Ebene von Dura auf, in der Provinz von Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Dann ließ König Nebukadrezar die Satrapen, Statthalter, Vorgesetzte und Befehlshaber, Schatzmeister, Richter und Beamte sowie die andern Würdenträger der Provinz alle zusammenkommen, damit sie zu der Einweihung des Bildes sich einfänden, das er, König Nebukadrezar, errichten ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Und so versammelten sich die Satrapen, Statthalter, Vorgesetzten und Befehlshaber, Schatzmeister, Richter und Beamte, auch all die andern Würdenträger der Provinz zur Einweihung des Bildes, das er, König Nebukadrezar hatte dort erstellen lassen. Sie stellten vor dem Bild sich auf, das dort Nebukadrezar hatte aufzurichten angeordnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Darauf rief laut der Herold aus: \"Euch, Völker, Nationen, Zungen wird hiermit verkündet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Sobald ihr die Trompeten, Pfeifen, Zithern, Harfen, Psalter und Sackpfeifen, auch all die anderen Arten von Musik ertönen hört, dann werft euch nieder zu der Anbetung des goldenen Bildes, das er, König Nebukadrezar, hier errichten ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Wer sich jedoch zur Anbetung nicht niederwirft, wird in derselben Stunde noch den Flammen eines Feuerofens übergeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Sobald nun all die Völkerscharen Trompeten, Pfeifen, Zithern, Harfen, Psalter, auch all die anderen Arten von Musik ertönen hörten, warfen sich auf dies hin alle Völker, Nationen, Zungen nieder zur Anbetung des goldenen Bildes, das er, König Nebukadrezar, hatte dort erstellen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Da traten alsogleich Chaldäer vor, die Juden anzuklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Sie huben an und sprachen zu dem König Nebukadrezar: \"König, mögst du ewig leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du gabst, o König, den Befehl: \'Wer die Trompeten, Pfeifen, Zithern, Harfen, Psalter, Sackpfeifen, auch all die anderen Arten von Musik ertönen hört, der soll sich niederwerfen und dies goldene Bild anbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Wer aber sich zur Anbetung nicht niederwirft, der soll den Flammen eines Feuerofens übergeben werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nun sind da diese Juden, die du über die Verwaltung der Provinz von Babel eingesetzt, Sidrach, Misach, Abdenago. Die Männer kümmerten sich nicht um dein Gebot, o König. Denn sie verehren deine Götter nicht und beten auch das goldene Bild nicht an, das du errichten ließest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Darauf befahl Nebukadrezar in Zorn und Grimm, Sidrach, Misach und Abdenago herzuführen. Da brachte man sie vor den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Da hob Nebukadrezar an und sprach zu ihnen:\"Habt ihr absichtlich meine Götter nicht verehrt, Sidrach, Misach und Abdenago, und dieses goldene Bild, das ich errichten ließ, nicht angebetet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nun wohl, seid ihr bereit dazu, dann werft euch nieder in dem Augenblick, da ihr Trompeten, Pfeifen, Zithern, Harfen, Psalter, Sackpfeifen und all die anderen Arten von Musik ertönen hört, zur Anbetung des Bildes, das ich errichten ließ! Doch betet ihr\'s nicht an, dann werdet ihr zur selben Stunde den Flammen eines Feuerofens übergeben werden. Und welchen Gott gäb\'s dann, der euch aus meiner Hand befreien könnte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Da hoben Sidrach, Misach sowie Abdenago also an und sprachen zu dem König:\"Nebukadrezar! Wir brauchen keine Antwort dir zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Denn siehe, unser Gott, den wir verehren, hat die Macht, uns aus des Feuerofens Glut zu retten und aus deiner Hand, o König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Wenn aber nicht, dann werden wir - du König, merk es dir! - doch deine Götter nicht verehren und nicht das goldene Bild, das du gemacht, anbeten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Da ward Nebukadrezar von Wut erfüllt, und sein Gesicht ward ganz entstellt ob Sidrach, Misach und Abdenago. Er gab Befehl, den Ofen siebenmal so stark, wie es sonst angemessen war, zu heizen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Alsdann gab er Befehl den stärksten Männern seines Heeres, Sidrach und Misach samt dem Abdenago an ihren Füßen fest zu fesseln und in des Feuerofens Glut zu werfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Da wurden diese Männer festgebunden, samt den Hosen, Hüten, Mänteln und den anderen Gewändern, und in des Feuerofens Glut geworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Weil der Befehl des Königs äußerst dringend war, so ward der Ofen übermäßig angeheizt. Da tötete die Feuerflamme jene Männer, die Sidrach, Misach und Abdenago hineingeworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Und jene drei, Sidrach, Misach und Abdenago, sie fielen in des Feuerofens Glut in ihren Fesseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Da ward König Nebukadrezar von Staunen tief ergriffen, stand eilends auf und sprach zu seinen Edlen: \"Drei Männer ließen wir gefesselt in das Feuer werfen?\" Sie sprachen zu dem König: \"Ja, o König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Da hob er an und sprach: \"Vier Männer seh ich frei im Feuer wandeln, und keinerlei Verletzung ist an ihnen zu bemerken; der vierte aber gleicht im Aussehn einem Sohne Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Darauf trat Nebukadrezar zu der Tür des Feuerofens, und er sprach: \"Ihr, Sidrach, Misach und Abdenago, des höchsten Gottes Diener, kommt heraus und tretet her!\" Da traten sogleich Sidrach, Misach und Abdenago heraus aus jenem Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Da eilten die Satrapen, Statthalter, die Vorgesetzten und des Königs andere Beamte her und überzeugten sich mit ihren Augen, daß das Feuer den Männern nichts an ihrem Leibe hatte schaden können, daß nicht einmal ein Haar auf ihrem Haupte war versengt, so wenig auch, wie einen Schaden ihre Beinkleider erlitten hatten. Nicht der geringste Feuerschaden hatte sich an sie geheftet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Da hob Nebukadrezar an und sprach: \"Gepriesen sei ihr Gott, der Gott des Sidrach, Misach und Abdenago, der seinen Engel hergesandt und seine Diener, die auf ihn vertraut, gerettet hat! Sie übertraten eher den Befehl des Königs und gaben selbst sich preis, damit sie keinen andern Gott verehren und anbeten mußten als nur den ihrigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Und so ergeht von mir jetzt der Befehl, daß jeder, welchen Volkes, welcher Nation und Zunge er auch sei, wenn gegen den Gott Sidrachs und den des Misach und des Abdenago er eine Lästerung ausstößt, in Stücke soll zerhauen werden, und daß sein Haus in Trümmer soll gelegt werden! Es gibt ja keinen andern Gott, der solche Rettung wirken könnte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Hierauf beförderte der König Sidrach, Misach und Abdenago in der Provinz von Babel. König Nebukadrezar an alle Völker, Stämme, Zungen, die auf der ganzen Erde wohnen: \"Mit euch sei vielmals Frieden! Es hat mir nun gefallen, euch die Zeichen und die Wunder, die der höchste Gott an mir getan, zu künden. Wie groß sind seine Zeichen, wie gewaltig seine Wunderwerke! Es ist sein Reich ein ewig Reich, und seine Macht reicht von Geschlechte zu Geschlecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, '\"Ich, der König Nebukadrezar, ich lebte friedlich einst in meinem Hause, in meinem Schlosse glücklich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Da hatte ich ein Traumgesicht, das mich erschreckte. Auf meinem Lager wirrten sich mir die Gedanken, die Gesichte meines Hauptes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Da wurde der Befehl von mir gegeben, alle Weisen Babels vor mich herzubringen, damit sie mir des Traumes Deutung gäben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Da traten die Wahrsager, Zauberer, Chaldäer, Zeichendeuter ein, und ich erzählte ihnen von dem Traum; doch seine Deutung konnte mir nicht einer geben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'bis endlich Daniel vor mir erschien, der Baltasar nach meines Gottes Namen heißt und der den Geist des heiligen Gottes in sich hat. Auch ihm erzählte ich den Traum:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '\'O Baltasar, du Größter aller Wahrsager, der du, wie ich wohl weiß, den Geist des heiligen Gottes in dir trägst, dem kein Geheimnis unenthüllbar ist, sag mir den Traum, den ich geschaut, und seine Deutung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Dies war auf meinem Lager meines Hauptes Gesicht: Ich schaute hin, da sah ich mitten auf der Erde einen Baum von außerordentlicher Höhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Groß war der Baum und stark; sein Gipfel reichte bis zum Himmel, und sichtbar war er bis ans Ende der ganzen Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Sein Laubwerk war sehr schön und seine Früchte überreich, und Nahrung gab\'s an ihm für alle. Es ruhten unter ihm die wilden Tiere; des Himmels Vögel nisteten in seinen Zweigen; und alles Fleisch ernährte sich von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Da schaute ich in dem Gesichte meines Hauptes auf dem Lager; sieh, da kam ein heiliger Wächter aus dem Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Er rief mit lauter Stimme: \"Fällt den Baum! Schlagt seine Äste ab und streift das Laub ihm weg! Streut seine Frucht umher! Fort flieh das Wild, das unter ihm geruht, aus seinen Zweigen fort die Vögel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Nur seinen Wurzelstock laßt in der Erde! Man binde ihn jedoch mit eisernen und ehernen Fesseln an im Grase draußen! Laßt ihn benetzt vom Tau des Himmels werden; mit dem Wilde hab er Anteil an des Erdreichs Gras!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Sein Menschenherz soll umgewandelt und ein Tierherz ihm gegeben werden; sieben Zeiten sollen über ihn hinziehen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Nach dem Beschluß der Wächter ist es angeordnet. Es ist der Heiligen Wunsch und Wille, daß die Lebenden erkennen, daß der Höchste Macht hat über das Königtum der Menschen und daß er es verleihen kann, wem er es will, und daß er selbst den Niedrigsten darüber setzen kann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Ich schaute diesen Traum, ich, König Nebukadrezar. Du aber, Baltasar, sag mir, was er bedeutet! Denn keiner von den Weisen meines Reiches vermag mir eine Deutung vorzutragen. Doch du vermagst es; denn du hast den Geist des heiligen Gottes ja in dir.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Darauf ward Daniel, auch Baltasar genannt, für kurze Zeit ganz still, und was er dachte, machte ihn bestürzt; da hob der König an und sprach: \"O Baltasar, laß durch den Traum und seine Deutung dich doch nicht verwirren!\" Darauf sprach Baltasar: \"Mein Herr! Ach, möchte doch der Traum nur denen gelten, die dich hassen, seine Deutung deinen Feinden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Der Baum, den du gesehen hast, der groß und mächtig ist und dessen Gipfel an den Himmel reicht und den man auf der ganzen Erde sehen kann');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'und dessen Laub so wunderschön und dessen Frucht so reichlich ist, an dem es Nahrung gibt für alle und unter dem des Feldes Tiere ruhen, in dessen Zweigen auch des Himmels Vögel nisten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'der Baum bist du, o König, der du groß und mächtig bist geworden. Es hat ja deine Größe zugenommen; sie reicht jetzt bis zum Himmel; deine Macht erstreckt sich bis ans Erdenende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Und daß der König sah, wie aus dem Himmel niederstieg ein heiliger Wächter, also sprechend: \'So fällt den Baum! Zerstückelt ihn! Doch seinen Wurzelstock laßt in der Erde! Man binde ihn jedoch mit Eisen und mit Erz im Grase draußen an und lasse ihn benetzt vom Tau des Himmels werden; seine Nahrung hab er mit dem Wild gemein, bis sieben Zeiten über ihn dahingegangen sind!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Dies ist die Deutung, König, und ein Beschluß des Höchsten ist\'s, ergangen gegen meinen Herrn, den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Man stößt dich aus der Menschenwelt, und bei den wilden Tieren mußt du wohnen. Man gibt dir Gras wie Rindern zu verzehren und läßt dich von dem Tau des Himmels netzen. Und sieben Zeiten gehen über dich dahin, bis du zur Einsicht kommst, daß nur der Höchste Macht hat über das Königtum der Menschen und es verleihen kann, wem er es will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Daß man gebot, den Wurzelstock des Baumes zu belassen, dies bedeutet: Dein Königtum wird weiter für dich fortbestehn, wenn du des Himmels Macht erkannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Laß deshalb meinen Rat, o König, dir gefallen! Mach deine Sünden wieder gut durch Almosen und deine Missetaten durch Güte gegen Arme! Vielleicht ist deinem Wohlergehen lange Dauer dann beschieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'All dies kam über König Nebukadrezar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Nach Ablauf von zwölf Monaten erging er sich auf dem Palast zu Babel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Da hob der König an und sprach: \"Ist dieses nicht das große Babel, das ich zur königlichen Residenz erbaut kraft meiner Macht und zur Vermehrung meines Ruhmes?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Noch war das Wort im Mund des Königs, als schon vom Himmel eine Stimme kam: \"Man kündigt dir, König Nebukadrezar, jetzt an: Das Königtum wird dir entzogen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'und aus der Menschheit stößt man dich hinaus. Du mußt bei wilden Tieren hausen. Man gibt dir Gras wie Rindern zu verzehren. Und sieben Zeiten gehen über dich, bis du zur Einsicht kommst, daß nur der Höchste Macht hat über das Königtum der Menschen und es geben kann, wem er es will.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Im selben Augenblick erfüllte sich an Nebukadrezar das Wort: Er wurde aus der Menschheit ausgestoßen, verzehrte Gras gleich einem Rind, und von dem Tau des Himmels ward sein Leib benetzt, bis adlergleich das Haar ihm wuchs und vogelkrallengleich die Nägel wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Doch nach Verlauf von vielen Tagen hob ich, Nebukadrezar, meine Augen gegen Himmel. Da ward mir wieder mein Verstand verliehen. Den Höchsten lobte ich und pries und rühmte hoch den ewig Lebenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Nicht einer, der auf Erden wohnt, kommt in Betracht. Er tut nach seinem Willen mit des Himmels Mächten, geradeso wie mit den Erdbewohnern, und niemand kann, ihm in die Arme fallend, zu ihm sprechen: \'Warum hast Du das getan?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Es kehrte mein Verstand zur selben Zeit zu mir zurück, und meine Herrschermacht zur Ehre meines Königtums; auch meine frühere Gestalt erhielt ich wieder. Da suchten meine Edlen und Beamten wiederum mich auf. So ward ich wieder in die Königsherrschaft eingesetzt. Und größere Macht als je zuvor ward mir verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Drum lob und rühme ich und preise ich, Nebukadrezar, des Himmels König. Denn recht sind alle seine Werke, richtig seine Wege, und zu erniedrigen weiß er, die übermütig wandeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Der König Belsazar gab seinen Edlen, tausend an der Zahl, ein großes Mahl. Soviel wie diese Tausend trank er Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Als Belsazar betrunken war, befahl er, jene goldenen und silbernen Gefäße, die aus dem Tempel zu Jerusalem sein Vater, der König Nebukadrezar, weggeschleppt, herbeizubringen, damit daraus der König und die Edlen, die Gemahlinnen und seine Nebenweiber tränken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Da wurden hergebracht die goldenen Gefäße, die aus dem Tempel Gottes zu Jerusalem genommen waren. Daraus nun trank der König, seine Edlen, die Gemahlinnen und Nebenweiber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Sie tranken Wein und lobten ihre Götter, die von Gold und Silber, Erz und Eisen, Stein und Holz gefertigt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Im selben Augenblick erschienen Finger einer Menschenhand dem Leuchter gegenüber auf dem Kalk des Königsschlosses. Der König aber sah die Hand, die schrieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Da ward des Königs Angesicht entstellt, und seine Ahnungen verwirrten ihn, und seine Hüftgelenke schlotterten, und seine Kniee schlugen aneinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Dann rief der König laut, man solle doch die Zauberer, Chaldäer, Zeichendeuter holen. Dann hob der König an und sagte zu den Weisen Babels: \"Wer immer diese Schrift da lesen kann und mir zu sagen weiß, was sie bedeutet, der wird mit Purpur angetan, darf an dem Halse eine goldene Kette tragen und soll in meinem Königreich der dritte sein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Auf dies hin kamen alle königlichen Weisen her. Doch konnten sie die Schrift nicht lesen, noch weniger dem König eine Deutung geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Da ward der König Belsazar aufs heftigste bestürzt; sein Angesicht entfärbte sich; auch seine Edlen waren ganz verstört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Da trat die Königin, durch das bewogen, was dem König und den Edlen widerfahren, in das Gebäude, wo das Gastmahl war. Die Königin hob an und sprach: \"O König, mögst du ewig leben! Es mögen deine Ahnungen dich nicht verstören! Nicht verfärbe sich dein Angesicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'In deinem Reiche gibt es einen Mann, der in sich trägt den Geist der heiligen Götter, bei dem in deines Vaters Tagen Einsicht und Verstand und Weisheit gefunden ward, der Götterweisheit nahezu entsprechend; hat doch König Nebukadrezar, dein Vater, diesen eingesetzt zum Obersten der Zauberer, Beschwörer, Chaldäer und der Zeichendeuter, dein eigner Vater, König,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'weil ein hoher Geist und Klugheit und Verständnis, Traumdeutung und Enthüllung von Geheimnissen, Aufklärung dunkler Sachen bei Daniel zu finden war, den Baltasar der König zubenannt. Man rufe also Daniel! Er wird die Deutung geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Da wurde Daniel dem König zugeführt. Da hob der König an und sprach zu Daniel: \"Bist du der Daniel, der zu den jüdischen Gefangenen gehört, die einst mein königlicher Vater aus Judäa hergebracht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Von dir hab ich gehört, daß du den Geist der Götter in dir trägst, daß Einsicht und Verständnis, Weisheit bei dir in hohem Maße gefunden ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Soeben sind vor mir die weisen Zauberer erschienen, um diese Schrift zu lesen, ihre Deutung mir zu geben. Doch konnten sie mir keinen Aufschluß über diese Sache geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Da hörte ich von dir, du könntest Dunkles aufklären und Schweres aufhellen. Bist du nun wirklich in der Lage, diese Schrift zu lesen, ihre Deutung mir zu geben, so erhältst du auch ein Purpurkleid, darfst du am Halse eine goldene Kette tragen und sollst der dritte Fürst in meinem Reiche sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Darauf sprach vor dem König Daniel: \"Behalte dein Geschenk für dich und deine Gaben schenke einem andern! Die Schrift jedoch will ich dem König lesen und auch ihre Deutung geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Du, König! Der höchste Gott gab Königtum und Königswürde und Ruhm und Ehre deinem Vater, dem Nebukadrezar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Und ob der Herrschergröße, die er ihm gab, erzitterten vor ihm und bebten alle Völker, Stämme, Zungen. Er konnte töten, wen er wollte, am Leben den erhalten, den er wollte, erhöhen, wen er wollte, und erniedrigen, wen er nur wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Als aber stolz sein Herz geworden war und bis zum Übermute sich sein Geist verhärtet, ward er von seinem königlichen Thron gestürzt und ihm sein Ruhm genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Und aus der Menschheit ward er ausgestoßen und sein Herz Tierherzen gleich gemacht. Er mußte bei den wilden Eseln hausen und wie die Rinder Gras verzehren. Vom Tau des Himmels ward sein Leib benetzt, bis daß er zur Erkenntnis kam, daß nur der Höchste Macht hat über das Königtum der Menschen und, wen er will, darüber setzen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Du, Belsazar, sein Sohn, hast gleichfalls nicht dein Herz gedemütigt, obschon du alles dies gewußt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Vielmehr erhobst du dich gegen den Herrn des Himmels. Man hat aus seinem Hause die Gefäße vor dich hergebracht, und du und deine Edlen, die Gemahlinnen und deine Nebenweiber, ihr habt aus ihnen Wein getrunken. Du priesest auch die Götter, die aus Gold und Silber, aus Erz und Eisen, Holz und Stein gefertigt sind, obschon sie doch nicht sehen, hören, fühlen können. Dagegen diesen Gott, der deinen Odem hat in seiner Hand samt allen deinen Wegen, den hast du nicht geehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'So ward denn eine Hand von ihm gesandt, und so ward diese Schrift hier aufgezeichnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'So heißt die Schrift denn, die hier steht geschrieben: \'Mene, mene, Tekel, Pharsin.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Und es bedeuten diese Worte: Mene: Gezählt hat Gott dein Königtum und ihm ein Ende zubestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel: Gewogen wardst du auf der Waage und zu leicht befunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Pharsin: Es wird dein Reich geteilt und wird den Medern und den Persern übergeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Da wurde Daniel auf den Befehl des Belsazar mit Purpur angetan und seinem Halse eine goldene Kette umgelegt; dann riefen über ihn sie aus, daß er als Dritter in dem Reiche herrschen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Noch in derselben Nacht ward Belsazar, der König der Chaldäer, umgebracht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Der medische Darius folgte in der Herrschaft nach, schon zweiundsechzig Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Und da gefiel\'s Darius, einhunderteinundzwanzig Statthalter in seinem Reiche einzusetzen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'und über diese drei Vorsteher, und unter ihnen war auch Daniel. Und ihnen sollten jene Statthalter selbst Rechenschaft ablegen, auf daß der König keinen Schaden leide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Da übertraf nun dieser Daniel weit alle Vorsteher und die Satrapen, weil er Geist in hohem Maße hatte. So ging der König mit dem Plane um, ihn übers ganze Reich zu setzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Da suchten nun die Vorsteher und die Satrapen einen Anlaß, um gegen Daniel von seiten der Regierung etwas aufzubringen. Doch sie vermochten nichts zu finden, weil er zuverlässig war und weil an ihm sich kein Vergehen und kein verdächtig Zeichen fand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Da sagten jene Männer: \"Wir finden keinen Vorwand gegen diesen Daniel, wenn wir ihn nicht in dem Gesetze seines Gottes finden können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Da liefen diese Vorsteher und die Satrapen bei dem Könige zusammen und sprachen so zu ihm: \"Darius, König, mögst du ewig leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Es haben alle Vorsteher des Reichs, Statthalter und Satrapen und die Richter und die Vorgesetzten den Beschluß gefaßt, es soll der König ein Gebot erlassen und ein Verbot dazu aufstellen, wonach ein jeder in die Löwengrube soll geworfen werden, der dreißig Tage lang an irgendeinen Gott oder an einen Menschen außer dir, o König, eine Bitte richtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Bestätige nun, o König, den Beschluß! Gib schriftlich den Befehl, damit es nach dem medischen und persischen Gesetz, das niemals abgeändert werden kann, unwiderruflich sei!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'So ließ der König, der Darius hieß, das schriftliche Verbot abfassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Als Daniel erfuhr, daß diese Schrift geschrieben sei, begab er sich in seine Wohnung, die im obern Stockwerk Fenster nach Jerusalem hin hatte. Er kniete dreimal dort am Tage nieder, pries betend seinen Gott, indem er ihn verehrte wie zuvor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Da eilten jene Männer aufgeregt herbei und fanden Daniel vor seinem Gott in Flehen und Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Da gingen sie zum König, über das Verbot ihn zu befragen: \"Hast du nicht ein Verbot aufzeichnen lassen, König, daß jeder Mensch in eine Löwengrube soll geworfen werden, der dreißig Tage lang an irgendeinen Gott oder an einen andern Menschen eine Bitte richtet als an dich, o König?\" Da hob der König an und sprach: \"Es steht die Sache nach dem medischen und persischen Gesetze fest, das niemals aufgehoben werden kann.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Da gaben sie zur Antwort vor dem König: \"Daniel, der zu den jüdischen Gefangenen gehört, hat sich um dein Gesetz, o König, nicht gekümmert, auch nicht um das Verbot, das schriftlich du gegeben. Er betet dreimal täglich sein Gebet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Als dies der König hörte, ward er tief betrübt und mühte sich um Daniels Errettung, und bis zum Sonnenuntergang war er bedacht auf seine Rettung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Doch da bestürmten jene Männer eifervoll den König; sie sprachen zu dem König: \"Wisse, König! Es ist ein medisches und persisches Gesetz, daß kein Verbot und kein Gebot, das je der König hat erlassen, darf verändert werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Da gab der König den Befehl, den Daniel herbeizubringen. Dann warf man ihn in eine Löwengrube. Der König sprach zu Daniel: \"Dein Gott, dem du beharrlich dienst, er möge dich erretten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Dann ward ein Stein herbeigeholt und oben auf der Grubenöffnung angebracht. Der König aber drückte dann sein Siegel und das der Edlen drauf, damit nichts gegen Daniel unternommen werden konnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Darauf zog der König sich ins Schloß zurück und legte nüchtern sich zum Schlafe nieder; und er ließ keine Speisen vor sich bringen. Auch so floh ihn der Schlaf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Da stand der König schon in früher Morgenstunde auf und eilte zu der Löwengrube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Und als er sich der Grube näherte, rief er dem Daniel mit lauter Stimme zu. Der König sprach zu Daniel: \"O Daniel, du des lebendigen Gottes Diener! Hat dich dein Gott, dem du beharrlich dienst, auch vor den Löwen retten können?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Sprach Daniel zum König:\"O König, ewig mögst du leben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Mein Gott hat seinen Engel hergesandt. Er hat der Löwen Rachen zugeschlossen, daß sie mir kein Leid zufügten. Unschuldig ward ich ja vor Dir erfunden. Doch tat ich, König, auch vor dir nichts Unrechtes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Da ward der König seinethalben froh erregt und hieß den Daniel aus dieser Grube ziehen. Da wurde aus der Grube Daniel gezogen; es fand an ihm sich keinerlei Verletzung, weil er auf seinen Gott vertraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Da gab der König den Befehl, nun jene Männer herzubringen, die Daniel verklagt. Sie warf man nun in jene Löwengrube mit den Kindern und den Weibern. Noch hatten sie der Grube Boden nicht erreicht, da waren schon die Löwen über sie gefallen und zermalmten ihnen alle Knochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Darauf erließ Darius, jener König, an alle Völker, Stämme, Zungen, die auf der ganzen Erde wohnten, ein Schreiben:\"Friede sei vielmals mit euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Von mir ergeht jetzt der Befehl, daß man im ganzen Umkreis meines Königtums vor Daniels Gott erzittern und sich fürchten soll. Er ist ja der lebendige Gott, der bleibt in Ewigkeit. Sein Reich wird nicht zerstört, und seine Herrschaft dauert ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Er ist ein Retter und Erlöser, der Zeichen wirkt und Wunder im Himmel und auf Erden, er, der den Daniel aus der Löwengrube errettet hat.\" Und dieser Daniel war glücklich unter der Regierung des Darius, wie auch unter der des Persers Cyrus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Im ersten Jahre Belsazars, des Babelkönigs, schaute Daniel ein Traumgesicht. Es fanden aber die Gesichte seines Hauptes auf seinem Lager statt. Er schrieb den Traum nach seinem wesentlichen Inhalt nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'So hob nun Daniel an und sprach: \"Ich sah des Nachts in meinem Traumgesicht, wie auf das große Meer vier Himmelswinde stürmten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Vier große Tiere stiegen aus dem Meer, ein jegliches verschieden von dem andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Es glich das erste einer Löwin und hatte Adlerflügel. Doch sah ich, wie ihm seine Flügel ausgerissen wurden und wie\'s vom Boden sich erhob, gleich einem Menschen auf den Füßen stand, wie ihm ein menschlich Herz gegeben ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Und sieh! Ein andres zweites Ungeheuer war dem Bären gleich. Es legte sich auf eine Seite; in seinem Maule hatte es drei Rippen zwischen seinen Zähnen. Man rief ihm zu: \'Steh auf und friß viel Fleisch!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Ein anderes, dem Panther gleich, sah ich nach diesem. Vier Flügel hatte es auf seinem Rücken. Vier Köpfe saßen auf dem Ungeheuer, und ihm ward Herrschermacht erteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Nach diesem sah ich in dem nächtlichen Gesicht ein viertes Ungeheuer, furchtbar, schrecklich und ausnehmend stark. Es hatte große Zähne, die von Eisen waren. Es fraß, zermalmte und zertrat, was übrigblieb, mit seinen Füßen. Es war von allen Ungeheuern vor ihm ganz verschieden und hatte noch zehn Hörner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Als ich die Hörner aufmerksam betrachtete, sah ich, wie da ein andres kleines Horn hervorwuchs zwischen ihnen. Drei von den ersten Hörnern wurden vor ihm ausgerissen, und an diesem Horne saßen Augen, Menschenaugen gleich. Es hatte ein Maul, das freche Reden führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Ich sah, wie Throne aufgeschlagen wurden. Ein Hochbetagter setzte sich. Und sein Gewand war weiß wie Schnee, sein Haupthaar rein wie Wolle. Sein Thron bestand aus Feuerflammen; seine Räder waren brennend Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ein Feuerstrom ergoß sich von ihm aus, und tausendfache Tausende bedienten ihn. Zehntausendfache Hunderttausend warteten ihm auf. Es ließ sich das Gericht nun nieder. Bücher wurden aufgeschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Ich schaute hin und sah, daß für die frechen Worte, die das Horn geredet, das Ungeheuer totgeschlagen, sein Leib verstümmelt und dem Feuerbrande übergeben wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Und auch den anderen Tieren wurde ihre Macht genommen und ihnen ihre Lebenszeit auf Zeit und Stunde festgelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'In meinem nächtlichen Gesichte sah ich noch, daß auf des Himmels Wolken einer wie ein Menschensohn erschien. Er nahte sich dem Hochbetagten und ward ihm zugeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Ihm wurde Herrschaft, Ruhm und Reich verliehen; ihm sollten alle Nationen, Völker, Zungen dienen; seine Herrschaft sollte ewige Herrschaft sein, die nicht beendigt werden kann. Sein Reich soll unzerstörbar sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Mir, Daniel, ward drob mein Herz entsetzt; es ängstigen mich die Gesichte meines Hauptes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Ich trat daher zu einem der Aufwartenden heran und fragte ihn um Auskunft über alles das. Er gab sie mir und tat mir diese Deutung kund:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '\'Die großen Ungeheuer, vier an Zahl, bedeuten: Vier Könige erheben sich auf Erden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Zur Herrschaft kommen dann die Heiligen des Höchsten; diese haben so in alle Ewigkeit die Herrschaft inne.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Darauf erbat ich Auskunft über jenes vierte Tier, das ganz verschieden von den andern war und ganz ausnehmend schrecklich, das Zähne hatte, die von Eisen, dazu eherne Klauen; das fraß, zermalmte und, was übrigblieb, mit Füßen trat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'und ferner über die zehn Hörner seines Haupts und dann das andere kleine, das hervorgewachsen und vor dem drei andre ausgerissen wurden, das Augen hatte, ein Maul, das Freches redete, und dessen Aussehen größer war als das der andern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Ich sah, wie dieses Horn des Höchsten Heilige bekriegte und wie es über sie die Oberhand gewann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'bis daß der Hochbetagte kam und Recht verliehen ward den Heiligen des Höchsten und bis die Zeit erschien, da Heilige das Reich besitzen sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Er gab nun diese Auskunft: \'Das vierte Ungeheuer ist das vierte Reich der Erde, das sich von allen Reichen unterscheidet. Es frißt die ganze Erde und zertritt sie und zerstampft sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Zehn Hörner deuten an: In diesem Reiche folgen sich zehn Könige. Nach ihnen steht ein anderer auf, der von den ersten ganz verschieden ist und drei der Könige zum Falle bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Dem Höchsten gegenüber wird er freche Reden führen und die Heiligen des Höchsten hart behandeln. Er wird sich unterfangen, Gesetz und Zeiten abzuändern. Sie werden ihm auch unterliegen bis auf eine Zeit und eine Doppelzeit und eine halbe Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Dann wird Gericht gehalten, um die Herrschaft ihm zu nehmen, zu vernichten und zu tilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Und Reich und Macht und Herrschaft über alle Reiche unterm Himmel wird verliehen dem Volk der Heiligen des Höchsten. Sein Reich wird sein ein ewig Reich, und alle andern Mächte werden ihm dann dienen und gehorchen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Bis hierher dies. Es ist zugleich das Ende des Gesichtes. Mich, Daniel, beängstigen unruhige Gedanken. Mein Aussehn ward ein anderes. Die Sache aber hielt ich fest in meinem Sinn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, '\"Im dritten Jahre der Regierung Belsazars, des Königs, wurde ein Gesicht mir, Daniel, zuteil, das nach dem ersten mir geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Ich schaute ein Gesicht. Als es mir ward, befand ich mich zu Susa, in der Burg, die in der Landschaft Elam liegt. Ich schaute aber im Gesicht, daß ich am Tore, das zum Ulai führte, war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Ich schlug nun meine Augen auf und sah: Da stand ein Widder mit zwei Hörnern vor dem Fluß. Die Hörner waren hoch. Doch war das eine höher als das andere. Das höhere aber ragte hinten auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Ich sah den Widder stoßen gegen Westen, Norden und nach Süden. Kein einzig Tier getraute sich, ihm standzuhalten; keines konnte sich vor seiner Übermacht erretten. Was ihm beliebte, tat er und er wurde übergroß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Noch hing ich der Betrachtung nach; da kam ein Ziegenbock von Westen her, durchlief die ganze Erde; doch berührte er den Boden nicht. Ein ganz beträchtlich Horn stand zwischen seinen Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Er kam bis zu dem Widder mit zwei Hörnern, den ich am Flusse hatte stehen sehen; er rannte auf ihn zu mit seinem Ungestüm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Wie er dem Widder nahe war, sah ich ihn wütend nach ihm stoßen. Er brach ihm beide Hörner ab. Der Widder hatte nicht die Kraft zum Widerstand. Der Bock warf ihn zu Boden und trat ihn mit den Füßen, und keinen gab es, der den Widder seiner Wut entriß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Der Ziegenbock ward übermäßig groß. Wie er am höchsten war, zerbrach das große Horn. An seiner Stelle kamen andre vier hervor nach den vier Himmelswinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'An einem jener Hörner brach ein kleines Horn hervor. Doch es erstreckte sich gewaltig hin nach Süd und Ost und nach dem Wunderlande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Es reckte sich empor bis zu dem Himmelsheer und stürzte manche von dem Heer, ja manche Sterne auf die Erde und trat sie da mit Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Es streckte sich empor bis zu des Heeres Fürsten. Sein täglich Opfer ward ihm weggenommen und sein heiliger Sitz entweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Der Sünde wegen ward das Heer mitsamt dem Opfer preisgegeben. Was hehr und heilig war, das warf das Horn zu Boden. Es unternahm\'s und hatte Glück damit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Nun hört\' ich einen Heiligen sprechen. Zu einem andern nämlich sprach ein Heiliger: \'Bis wann erfüllt sich die in dem Gesicht geschaute Sünde, die in Vernichtung jenes Opfers und des Heiligtums, in der Zertretung jener Schar besteht?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Er sagte zu mir hin: \'Bis auf zweitausend und dreihundert Abendmorgen. Dann wird das Heiligtum gereinigt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Nachdem ich, Daniel, gesehen das Gesicht, wünschte ich mir eine Deutung, und siehe, einer, wie ein Mann gestaltet, stand vor mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Nun hört\' ich eine Menschenstimme zwischen des Ulai Ufern; sie rief: \'O Gabriel, erkläre dem da drüben das Gesicht!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Da ging er auf mich zu, und als er näher kam, fiel ich erschrocken auf mein Angesicht. Er sprach zu mir: \'Merk auf, du Menschensohn! Denn auf die letzte Zeit geht das Gesicht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Als er so zu mir sprach, fiel ich betäubt zur Erde auf mein Angesicht. Da rührte er mich an und richtete mich wieder auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Er sprach: \'Ich tu dir kund, was in des Zornes letzter Zeit geschehen wird. Es geht ja auf die Zeit des Endes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Der Widder mit zwei Hörnern, den du sahst, bezeichnet Könige von Medien und Persien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Der Ziegenbock den Griechenkönig, und das große Horn, das zwischen seinen Augen ist, den ersten König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Und daß vier andere, nachdem das Horn zerbrochen war, an seiner Statt erschienen, dies bedeutet, daß vier Reiche aus dem selben Volk hervorgehn, doch nicht von gleicher Stärke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Und gegen ihrer Herrschaft Schluß, wenn die Verschuldungen ihr höchstes Maß erreicht, dann tritt ein unverschämter, ränkevoller König auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'und er verstärkt sich seine Macht, doch nicht durch seine Kraft. Er wird erstaunliche Verwüstungen bewirken und doch glücklich sein bei seinem Unterfangen; Mächtige wird er verderben, auch das Volk der Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Ist ihm durch seine Schlauheit dann geglückt sein täuschendes Beginnen, so tötet er im Übermute seines Herzens viele unversehens; gegen den Fürsten aller Fürsten steht er auf. Er aber wird zerschmettert durch den Eingriff einer Macht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Und wahr ist das Gesicht von Abendmorgen, wovon die Rede war. Halt aber selber das Gesicht geheim! Es geht auf späte Zeiten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Ich, Daniel, war dadurch angegriffen und eine Zeitlang krank und, wiederhergestellt, tat ich zwar königlichen Dienst; doch blieb ich voll Erstaunen über das Gesicht, das jedem unverständlich blieb.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, '\"Im ersten Jahre des Darius, des Sohnes Ahasvers, aus dem Geschlecht der Meder, der Herrscher über der Chaldäer Reich war,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'im ersten Jahr, da er regierte, dacht ich, Daniel, der Zahl der Jahre in den Büchern nach, wovon der Herr zu Jeremias, dem Propheten, einst geredet, daß erst nach siebzig Jahren die Verwüstung von Jerusalem beendet sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Ich wandte mich darauf an Gott, den Herrn, und suchte unter Fasten und in Sack und Asche richtiges Gebet zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Ich flehte zu dem Herren, meinem Gott, und legte dies Bekenntnis ab und sprach: \'Ach, Herr, Du großer, hehrer Gott, der denen, die ihn lieben und seine Vorschriften befolgen, den Bund und die Barmherzigkeit bewahrt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Gesündigt haben wir und uns empört. Von Deinen Vorschriften und Rechten sind wir abgewichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Wir hörten nicht auf Deine Diener, die Propheten, die zu unsern Königen und Fürsten, unsern Vätern und zum ganzen Volk im Land in Deinem Namen sprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Du bist im Rechte, Herr. Wir aber haben uns zu schämen, wie es jetzt geschieht, die Männer Judas, die Bewohner von Jerusalem, ganz Israel, die Nahen und die Fernen, in allen Ländern dort, wohin Du sie verstoßen hast, der Untreue wegen, die sie an Dir begangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'O Herr, wir haben uns zu schämen, wir selbst und unsere Könige, die Fürsten und die Väter, die wir an Dir uns schwer vergangen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Doch bei dem Herrn, bei unserm Gott, ist ja Verzeihung und Vergebung, obschon wir ihm untreu geworden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'und nicht auf unseres Herrn und Gottes Stimme hörten, daß wir nach den Geboten wandelten, die er uns vorgelegt durch seine Diener, die Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Ganz Israel hat Dein Gesetz verletzt und, widerspenstig, nicht gehört auf Deine Stimme. Da wurden ausgeschüttet über uns der Fluch und die Verwünschungen, die im Gesetze Mosis stehn, des Gottesknechtes. Weil wir an ihm gesündigt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'ließ er in Erfüllung gehen seine Drohungen, die er gen uns und unsere Oberhäupter ausgesprochen, daß er ein großes Ungemach uns treffen lasse, wie solches niemals unterm Himmel eingetroffen, so, wie\'s Jerusalem getroffen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Wie es geschrieben steht in dem Gesetze Mosis, so kam all dieses Unglück über uns. Wir suchten nicht den Herren, unsren Gott, so zu begütigen, daß wir von unsern Missetaten abgelassen und auf Dein Wort geachtet hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'So wurde auf das Ungemach der Herr bedacht und brachte es auch über uns. Denn unser Gott, der Herr, ist ganz gerecht in allem, was er tut, weil wir trotz alledem auf seine Stimme nicht gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Und nun, Herr, unser Gott, der Du Dein Volk aus dem Ägypterland mit starker Hand herausgeführt und einen großen Namen Dir gemacht, so wie er jetzt noch dauert! Gesündigt haben wir und uns vergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Herr, laß nach Deiner Güte doch von Deinem Grimme ab und Deinem Zorn auf Deine Stadt Jerusalem und Deinen heiligen Berg! Denn wegen unserer Sünden, unserer Väter Missetaten dient Jerusalem und Deine Nation zum Hohne allen unsern Nachbarvölkern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Nun hör, Du unser Gott, das Flehen Deines Dieners, sein Gebet! Laß über deinem öden Heiligtum Dein Antlitz um des Herren willen leuchten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Neig Du, mein Gott, Dein Ohr zu uns und höre! Öffne Deine Augen, blick hin auf unsere Zerstörungen und auf die Stadt, die Deinen Namen trägt! Nicht im Vertraun auf unsere Tugenden mehr legen wir die Bitten vor Dir nieder, nein, nur im Vertraun auf Deine große Huld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Herr, höre! Herr, vergib! Merk auf, Herr, tu es! Zögere nicht um Deinetwillen, Du mein Gott! Nach Deinem Namen ist ja Deine Stadt und Deine Nation benannt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Noch redete ich so und betete, bekannte meine Sünde und die meines Volkes Israel und legte meine Bitte nieder vor dem Herren, meinem Gott, für meines Gottes heiligen Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Noch sprach ich im Gebet, als Gabriel, der Mann, den ich im früheren Gesichte sah, schnell fliegend zu mir kam und um die Zeit des Abendopfers mich berührte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Vernehmlich redete er mich also an. Er sagte: \'Daniel! Soeben bin ich ausgegangen, dein Verständnis aufzuschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Beim Anfang deines Betens ist Befehl dazu ergangen, und dir Bescheid zu bringen, bin ich da, weil du ein Liebling bist. Merk also auf den Ausspruch wohl und laß dich über das Gesetz belehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Es sind der Wochen siebzig für dein Volk und deine heilige Stadt bestimmt, um die Verschuldung abzutun, die Sünden abzubüßen, die Missetaten wiedergutzumachen, die alte Gnade wiederherzustellen und um Gesicht und Prophezeiung zu erfüllen und um das Allerheiligste zu weihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Doch sollst du wissen und beachten: Von dem Erhalten des Befehls bis zu der Wiederherstellung, dem Aufbau von Jerusalem, bis zu des Fürsten Salbung sind es sieben Wochen. Nach zweiundsechzig Wochen aber werden wieder aufgebaut die Plätze und die Gräben, jedoch in arger Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Nach zweiundsechzig Wochen wird dann der Gesalbte umgebracht, und es wird ihm kein Recht. Und Stadt und Heiligtum zerstört das Volk des Fürsten, der heranzieht und der in einer Wasserflut sein Ende findet. Beschlossen bis zum Kriegsende ist die Verwüstung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Und während einer Woche vergewaltigt er den Bund für viele. Durch eine halbe Woche untersagt er Brand- und Speiseopfer, kommt er doch als Verwüster an der Spitze greulicher Abteilungen, bis Unheil über Unheil sich schließlich über den Abscheulichen ergießt.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Im dritten Jahr des Perserkönigs Cyrus wurde dem Daniel, der auch Baltasar geheißen wurde, etwas geoffenbart. Das Wort ist wahr und geht auf eine lange Zeit. Er hat das Wort ganz richtig aufgefaßt und das Gesicht verstanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, '\"Ich, Daniel, habe damals drei Wochen lang getrauert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Ich aß nicht ausgesuchte Speisen, und Fleisch und Wein kam nicht in meinen Mund. Auch salbte ich mich nicht, bis die drei Wochen ganz zu Ende waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Am vierundzwanzigsten des ersten Monats war ich am Ufer jenes großen Flusses Tigris.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Ich schlug da meine Augen auf und schaute. Da war ein Mann im Leinenkleide, gegürtet waren seine Hüften mit feinstem Gold.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Dem Goldstein glich sein Leib; sein Antlitz strahlte wie der Blitz, und seine Augen glichen Feuerfackeln; seine Arme, seine Füße funkelten wie glänzend Erz, und seiner Worte Klang war wie das Rauschen eines Heeres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ich, Daniel, allein sah das Gesicht. Die Leute bei mir sahen\'s nicht; doch kam ein großer Schrecken über sie. Sie flohen, sich zu bergen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Ich blieb allein zurück und sah dies wichtige Gesicht. In mir blieb keine Kraft, so daß sich meine Auszeichnung mir zum Verderben schien zu wenden, und alle Kraft schwand mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Ich hörte seiner Worte Schall, und als ich ihn vernahm, fiel ich betäubt auf mein Gesicht, und mein Gesicht lag auf dem Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Da rührte eine Hand mich an und half mir auf die Knie und die Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Er sprach zu mir: \'O Daniel, geliebter Mann! Merk auf die Worte, die ich zu dir spreche! Steh auf! Ich bin ja eigens zu dir hergesandt.\' Nachdem er dies zu mir gesagt, stand ich mit Zittern auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Dann sagte er zu mir: \'O Daniel, sei ohne Furcht! Am ersten Tag, da du dir vorgenommen hast vor deinem Gott um der Belehrung willen dich zu erniedrigen, ward schon dein Wunsch erhört, und daraufhin ward ich gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Mir aber widersetzte sich der Fürst des Perserreichs wohl einundzwanzig Tage lang. Doch Michael, der ersten Fürsten einer, kam mir zu Hilfe. So ward ich bei dem Perserkönig überflüssig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Nun bin ich da, dir anzuzeigen, was deinem Volke in der letzten Zeit begegnet. Denn das Gesicht geht bis in ferne Tage.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Als er mit mir auf solche Weise redete, schlug ich die Augen nieder und ward sprachlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Und siehe: Einer, wie ein Mensch gestaltet, berührte meine Lippen. Da öffnete ich meinen Mund und konnte reden, und ich sprach zu dem, der vor mir stand: \'Mein Herr, durch die Erscheinung bin ich ganz gelähmt und habe alle Kraft verloren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Wie könnte da der Diener meines Herrn mit meinem Herrn noch reden? Da bleibt mir keine Kraft, und kaum der Atem ist in mir noch übrig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Und einer, wie ein Mensch gestaltet, rührte mich von neuem an und stärkte mich und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, '\'Sei ohne Furcht, geliebter Mann! Der Friede sei mit dir! Sei mutig, mutig!\' Und da er mit mir redete, bekam ich neue Kräfte. Ich sprach: \'Es rede nun mein Herr! Ich fühle mich gestärkt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Er sprach: \'Weißt du, warum ich zu dir kam? Gleich muß ich zwar zurück zum Kampfe mit dem Perserfürsten. Hab ich dann ausgekämpft, erscheint der Fürst von Griechenland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Doch tu ich dir zuvor zu wissen, was da schriftlich aufgezeichnet ist, und zwar im wesentlichen. Es unterstützt mich niemand gegen jene als nur Michael, der euer Fürst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Im ersten Jahr des medischen Darius besaß ich schon das Amt, zu helfen und ihm beizustehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Nun will ich dir\'s im wesentlichen künden: Noch stehen drei Könige in Persien auf. Der vierte bringt noch größeren Reichtum als die andern all zusammen, und, im Vertraun auf seinen Reichtum, setzt er dem ganzen Griechenreiche zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Dann steht ein großer König auf, beherrscht ein großes Reich und tut, was ihm gefällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Steht er auf seiner Höhe, wird sein Reich zertrümmert und nach vier Himmelswinden aufgeteilt, nicht aber unter seine Nachkommen und nicht mehr von der Macht, die er besessen. Wird doch sein Reich zerrissen und verteilt an andere als jene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Und mächtig wird des Südens König. Von seinen Fürsten aber wird noch einer mächtiger als dieser. Er wird ein großes Reich beherrschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Dann nach Verlauf von Jahren treten sie in engere Verbindung. Des Königs Tochter aus dem Süden kommt zum Könige des Nordens, um die Freundschaft zu festigen. Den starken Beistand wird sie nicht behalten; denn weder er noch seine Macht sind mehr von Dauer. So wird sie hingeopfert, sie und die sie hinbegleitet hatten, ihr Sohn und die ihr in Gefahren Hilfe leisten wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Aus ihrem Wurzelschoße steht an seiner Stelle einer auf. Er stellt sich an des Heeres Spitze, zieht gegen des Nordkönigs Festungen und greift sie an und überwältigt sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Auch ihre Götter samt den Gußbildern, mitsamt den kostbaren Geräten, Gold und Silber bringt er dann als Beute nach Ägypten. Er ist dem Könige des Nordens während ein paar Jahren überlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Der kommt ins Reich des Königs in den Süden, kehrt dann aber heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Doch seine Söhne werden kriegerischer sein und große Heere sammeln. Losbrechen wird der eine, überflutend kommen und bis zu seiner Festung wiederholt den Krieg vortragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Erbittert zieht darauf des Südens König auch zu Feld, um mit des Nordens König nun zu kämpfen. Er wird ein großes Heer aufstellen, und dies wird seinem eigenen Befehle untergeben sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Das Heer, begeistert und voll hohen Muts, streckt Tausende zu Boden, und doch behält er nicht die Oberhand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Des Nordens König stellt ein größer Heer auf, als das erste je gewesen, und kommt nach Jahren dann mit einem großen Heer und vielem Kriegsgerät.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'In jenen Zeiten stehn Irrlehrer wider den König aus dem Süden auf. Aufrührer deines Volkes befördern voll Vermessenheit dann des Gesichts Erfüllung und ihr Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Des Nordens König zieht heran und kommt, er wirft dann Dämme auf und nimmt so eine feste Stadt. Des Südens Kräfte werden nichts vermögen, und auch das auserlesene Volk hat nicht die Kraft, sich zu behaupten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'So tut, der gegen ihn gezogen, was er will, und niemand kann sich vor ihm halten. Dann rückt er in das Wunderland, und dies fällt ganz in seine Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Dann faßt er den Entschluß, mit seines Reiches ganzer Macht zu kommen. Doch muß er mit ihm Frieden machen. Er gibt ihm eine Tochter, damit sie dort verderblich wirke. Doch kommt es nicht zustande, es gelingt ihm nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Nun wendet er sich nach den Küstenländern und erobert ihrer viele. Ein Fürst jedoch macht seinem Hohn ein Ende, ja, er gibt ihm seinen Hohn zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Er wendet sich zu seines Landes festen Plätzen; dann aber strauchelt er und fällt und ist nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'An seine Stelle tritt ein anderer, der Gelderpresser durch das herrlichste der Reiche schickt. Nach wenigen Tagen wird er dann vernichtet, doch nicht im Zorn und nicht im Kampf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'An seine Stelle setzt sich ein Verworfener, zur Königswürde nicht bestimmt. Er kommt voll List, und so bemächtigt er sich durch Betrug des Reiches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Streitkräfte werden weggeschwemmt vor seinem Angesicht; mitsamt dem Bundesfürsten werden sie vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Und hat er sich mit ihm verbündet, dann wird betrügerisch er handeln, mit wenig Kriegsvolk einen Angriff wagen und der Sieger sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'In ein friedliches, reiches Land kommt er und tut dort, was die Väter seiner Väter nicht getan. Und Beute, Raub und Güter nimmt er ihnen und richtet auf die festen Plätze seine Pläne, jedoch nur für gewisse Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Dann stärkt er seine Kraft und seinen Mut zum Angriff auf des Südens König durch ein großes Heer. Den Kampf beginnt des Südens König mit großem und sehr starkem Heer. Doch hält er nimmer stand. Geschmiedet werden Ränke gegen ihn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'und seine Tischgenossen richten ihn zugrunde. Sein Heer wird alles überschwemmen, und fallen werden viele, die erschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Es sinnen beide Könige auf Böses; an einer Tafel speisend, belügen sie sich gegenseitig. Doch nimmt\'s kein günstig Ende. Denn erst zu der bestimmten Zeit erfolgt das Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Er kehrt nun in sein Land zurück mit großer Habe und richtet auf den heiligen Bund den Sinn. Er führt den Plan auch aus und kehrt dann in sein Land zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Zur festgesetzten Zeit zieht er aufs neue in den Süden. Doch ist\'s das zweitemal nicht so, wie bei dem erstenmal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Aus Cypern kommen mit ihm Schiffe. Doch eingeschüchtert, läßt er seinen Grimm am heiligen Bunde wieder aus und schenkt Beachtung denen, die am heiligen Bund gefrevelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Streitkräfte seines Heeres treten auf, und sie entweihn das Heiligtum, die Burg und schaffen ab das täglich Opfer und stellen dann das Götzenscheusal auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Die an dem Bunde freveln, sucht er nun durch Schmeichelei\'n zum Abfall zu verleiten. Das Volk jedoch, das seinen Gott noch anerkennt, wird sich zur Tat ermannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Des Volkes Weise werden viele recht belehren. Doch sind sie eine Zeit durch Schwert und Feuer und durch Gefangenschaft und Plünderungen unterlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Wenn diese fallen, werden jene Rettung finden durch eine unscheinbare Hilfe. Dann aber schlagen sich zu ihnen viele auf heuchlerische Weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Und von den Weisen fallen manche, um die anderen zu läutern und zu reinigen und fleckenlos zu machen bis auf die Zeit des Endes; denn eine Weile dauert\'s noch bis zu der festbestimmten Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Was ihm beliebt, das tut der König und überhebt sich übermütig gegen jeden Gott; auch gegen Gott, der Götter Gott, führt er vermessene Reden. Er hat Gelingen nur, solange nicht der Zorn wird ausgelassen; denn, was beschlossen, muß geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Er achtet weder seiner Väter Götter, noch achtet er der schönen Weiber, noch irgendeines Gottes achtet er. Denn er erhebt sich gegen jeden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Den Gott der Stärke, den wird er an seiner Statt verehren. Den Gott, den seine Väter nicht gekannt, ehrt er mit Gold und Silber, Edelstein und andern Kostbarkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'In feste Stellungen bringt er das Volk des fremden Gottes. Und wer ihn anerkennt, den würdigt er gar großer Ehre. Er wird ihm Herrschaft über viele anvertrauen, und Land wird er zum Lohn verteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Zur Zeit des Endes kämpft mit ihm des Südens König. Auf ihn stürmt ein des Nordens König mit Wagen, Rossen, vielen Schiffen, und überströmend, überschwemmend dringt er in die Länder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Er kommt auch in das Wunderland, und viele kommen da zu Fall. Nur diese werden seiner Hand entgehen: Edom, Moab, der Söhne Ammons bester Teil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'An Länder legt er seine Hand; auch das Ägypterland entgeht ihm nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Er wird der Gold- und Silberschätze sich bemächtigen und aller Kostbarkeiten von Ägypten, und die von Lub und Kusch führt er mit sich hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Dann schrecken ihn Gerüchte aus dem Osten und dem Norden. Er bricht mit großem Grimme auf, um viele zu vernichten und sie zu vertilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Er spannt sein Lagerzelt dann aus dort zwischen Meeren an dem heiligen, berühmten Berg. Hier findet er sein Ende, niemand wird ihm helfen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, '\'In jener Zeit erhebt sich Michael, der große Fürst, er, der den Söhnen deines Volkes Beistand leistet. Es gibt ja eine Zeit der Not, dergleichen keine war, seitdem es Völker gab, bis jetzt. Doch wird in jener Zeit dein Volk gerettet, ein jeder, der im Buch verzeichnet wird gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Und viele derer, die im Staub der Erde schlafen, wachen auf, die einen für ein ewig Leben, die andern, um bedeckt zu sein mit ewiger Schmach und Schande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Die Weisen aber leuchten wie des Himmels Glanz und jene, die viele zur Gerechtigkeit geleitet, wie die Sterne ewiglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Du aber, Daniel, halt das Gesagte ganz geheim! Versiegle du das Buch bis auf die Zeit des Endes! Dann lesen\'s viele durch, und groß ist dann das Wissen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Ich, Daniel, ich schaute hin und sah, wie da zwei andere Männer standen, diesseits des Flusses einer und der andere jenseits.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Da fragte jener bei dem Mann in Linnenkleidern, der überm Stromgewässer war: \'Wann ist das Ende dieser wunderbaren Dinge?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Ich hörte, wie der Mann in Linnenkleidern, der überm Stromgewässer war, die rechte und die linke Hand zum Himmel hebend schwur bei dem, der ewig lebt. In einer Zeit, in einer doppelten und einer halben Zeit, wenn aufhört die Vernichtung an der Macht des heiligen Volkes, geht alles das zu Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Dies hört\' ich zwar, verstand es aber nicht und sprach daher: \'Mein Herr, was ist das für ein Ende?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Er sprach: \'Geh, Daniel! Es muß der Worte Sinn verschlossen bleiben und geheim bis zu der Zeit des Endes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Es werden viele bei der Läuterung sich rein und fleckenlos erweisen und als verrucht sich die Verruchten zeigen, und keiner der Verruchten wird den Sinn verstehn; die Weisen aber werden ihn verstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Von jener Zeit, da man das täglich Opfer abgeschafft und man den Greuelgötzen aufstellt, sinds zwölfhundertneunzig Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Wohl dem, der dreizehnhundertfünfunddreißig Tage dann erreicht, geduldig harrend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Du aber geh dem Ende zu! Ruh aus! Hernach erhebe dich zu deinem Los am Ende jener Tage!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Des Herren Wort, das an Hosea, Beeris Sohn, erging zur Zeit der Judakönige Ozias, Jotam, Achaz und Ezechias, sowie zur Zeit des Israelkönigs Jeroboam, des Joassohns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Beginn der Reden, die vom Herrn gerichtet an Hosea: Der Herr sprach zu Hosea: \"Auf! Nimm dir ein unfrei Weib! Von ihr bekomme Kinder, gleichfalls unfreie!\" Der Herr erklärte ja das Land für unfrei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Da ging er hin und nahm die Gomer, eines Söldners Tochter. Und sie empfing, und sie gebar ihm einen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Da sprach der Herr zu ihm: \"Gib ihm den Namen \'Jezrael\'! Denn nur noch eine kleine Weile, dann suche ich die Blutschuld Jezraels an Jehus Hause heim und mache seiner Herrschaft über das Haus Israel ein Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'An jenem Tage nämlich wird\'s geschehen, daß ich den Bogen Israels im Tale Jezraels zerschmettere.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Und sie empfing ein zweitesmal, und da gebar sie eine Tochter. Er sprach zu ihm: \"Gib ihr den Namen \'Ungeliebte\'! Denn Liebe schenke ich dem Hause Israel nicht mehr. Ich bringe über sie Vernichtung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Ich schenke Liebe nur dem Judahaus und rette sie durch ihren Gott, den Herrn. Doch rette ich sie nicht durch Bogen, nicht durchs Schwert, nicht durch die Schlacht, durch Rosse nicht und nicht durch Reiterscharen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Und sie entwöhnte dann die \"Ungeliebte\". Und sie empfing und schenkte einem Sohn das Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Er sprach: \"Gib ihm den Namen \'Nicht mein Volk\'! Denn ihr seid nimmermehr mein Volk, und ich gehöre euch nicht an.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, '\"Einst aber gleicht die Zahl der Söhne Israels dem Sand am Meer, der nicht zu messen noch zu zählen ist. Anstatt daß es von ihnen heißt: \'Ihr seid nicht mehr mein Volk\', heißt\'s dann von ihnen: \'die,Söhne des lebendigen Gottes\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Und Judas Söhne und die Söhne Israels, sie werden sich vereinigen und über sich ein Oberhaupt bestellen und so auf Erden hochansehnlich werden. Bedeutungsvoll wird ja der Tag von Jezrael.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Zu euren Brüdern sprecht: \'Mein Volk\', zu euren Schwestern: \'Du Geliebte\'! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Zankt nur mit eurer Mutter, zankt! Sie ist mir nicht mehr Eheweib, und ich bin nimmer ihr Gemahl. - Sie tue weg von ihrem Antlitz die unechte Schönheit, weg von ihrem Busen ihren falschen Schmuck!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Sonst laß ich sie entkleiden und stelle sie so hin, wie sie an jenem Tage ward, und mache sie gleich einem Menschen in der Wüste und stelle sie so hin, gleich einem, der in dürrem Lande, und lasse sie durch Durst hinsterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Mit ihren Kindern hab ich kein Erbarmen; unechte Söhne sind sie ja.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Denn ihre Mutter brach die Treue; die sie gebar, gab sich der Schande hin. Sie sprach: \'Ich folge eben denen, die mich gerne haben und die mir Brot und Wasser geben, Wolle, Flachs und Öl und was mir sonst zur Stärkung dient.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Deswegen sperre ich mit Dornen deinen Weg und schließe sie durch Buschwerk ein, so daß sie ihre Wege nicht mehr findet. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Und sollte sie doch ihren Buhlen folgen können, so wird sie diese nirgends finden. Dann spricht sie endlich: \'Auf! Ich gehe heim zu meinem ersten Mann; denn damals ging\'s mir besser als zu dieser Zeit.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Doch jetzt sieht sie\'s nicht ein, daß ich es bin, der ihr Getreide, Most und Öl gespendet. Viel Silber gab ich ihr und Gold; doch hat sie dies dem Baal geweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Deswegen mache ich es nunmehr anders: Ich gebe mein Getreide nicht zu seiner Zeit, nicht meinen Wein zu seiner Frist. Ich halte meine Wolle, meinen Flachs zurück, womit sie ihre Blöße decken wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Und dann entblöße ich vor ihren Buhlen ihre Scham, und niemand soll sie meiner Hand entreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Aufheben will ich alles, was sie fröhlich macht, ihr Fest und ihren Neumondstag und ihren Sabbat, all ihre andern Feiertage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Denn ich verheere ihren Weinstock, ihren Feigenbaum, von dem sie sprach: \'Das ist mein Lohn, den meine Buhlen mir gegeben.\' Ich mach sie zum Gestrüpp; abfressen sollen sie des Feldes Tiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'So will ich sie bestrafen für die Baalsfeste, wo sie räucherte, wo sie, geschmückt mit Ringen und Geschmeide, ihren Buhlen nachlief, aber mich dabei vergaß.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, '\"Ist\'s dann soweit, dann locke ich sie wieder an und leite wieder sie im öden Land und rede ihr zu Herzen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'und gebe dort ihr wieder ihre Rebenhügel und Achors Tal zur Hoffnungspforte. Dann singt sie fröhlich wie in ihrer Jugendzeit, wie damals, als sie aus Ägypterlande zog.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, '\"Und dann geschieht\'s an jenem Tag\", ein Spruch des Herrn, \"da rufst du wiederum: \'Mein Ehgemahl\' und sprichst nicht mehr zu mir: \'Mein Baal\' (Herr).');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Aus ihrem Mund entferne ich die Baalsnamen, daß mit ihren Namen sie nicht länger mehr gepriesen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Ich schließe einen Bund an jenem Tag zu ihrem Besten mit des Feldes Tieren, mit des Himmels Vögeln und dem Gewürm der Erde. Und ich vernichte Bogen, Schwert und andere Waffen in dem Land und lasse sie in sicherer Ruhe lagern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Und ich verlobe mich mit dir für ewig, verlobe mich mit dir rechtskräftig und gesetzlich, in Zärtlichkeit und Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Und ich verlobe mich mit dir für Treue, für das Erkennen ihres Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'An jenem Tage wird\'s geschehn, da werde ich\", ein Spruch des Herrn, \"des Himmels Wunsch erfüllen, und dieser den der Erde, die Erde den des Korns, des Weines und des Öls, und diese dann die Wünsche Jezraels. Ich säe sie für mich im Lande aus und zeige Liebe wiederum der \'Ungeliebten\' und sage dann zu \'Nicht mein Volk\': \'Mein Volk bist du\', und dieses spricht: \'Mein Gott\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Und wieder sprach der Herr zu mir: \"Auf! Geh, mit einem Weibe einen Liebeshandel abzuschließen, das sich von Freunden lieben läßt und sich mit anderen vergeht! So, wie der Herr den Söhnen Israels auch seine Liebe schenkt, obschon sie sich zu andern Göttern wenden und andre Lager lieben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'So ward ich denn mit einer solchen einig für fünfzehn Silberlinge und für anderthalb Maß Gerste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Ich sprach zu ihr: \"Du sollst mir viele Tage dasitzen und keine Unzucht treiben, mit keinem andere Manne dich abgeben. Jedoch auch ich will für mich leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Denn viele Tage müssen die Söhne Israels dasitzen. Kein König und kein Fürst ist da, kein Opfer und kein Bild, kein Ephod, keine Teraphim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Alsdann bekehren sich die Söhne Israels und suchen nach dem Herren, ihrem Gott, und David, ihrem König. Sie eilen in der Tage letzten Zeit voll Furcht zum Herrn und seinem Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Vernehmt das Wort des Herrn, ihr Söhne Israels: Zu rechten hat der Herr mit den Bewohnern dieses Landes; denn keine Treue, keine Frömmigkeit, keine Erkenntnis Gottes gibt es mehr im Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Das Schwören und Betrügen, Morden, Stehlen, Ehebrechen nimmt überhand; Bluttat reihet sich an Bluttat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Darüber steht das Land in Trauer, und was darinnen wohnt, verschwindet. Des Feldes Tiere und des Himmels Vögel, selbst des Meeres Fische schwinden hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, '\"\'Man rechte nicht! Man tadle nicht!\' Dein Volk, du Priester, dein Volk ist solchen gleich, die mich angreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Du gabst am Tage Anstoß deinem Volk und der Prophet zur Nachtzeit. Und ich vertilgte deine Ernte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Hinschwand mein Volk, weil ihm Erkenntnis mangelte. Du hast ja die Erkenntnis weggeworfen, und so verwerfe ich auch dich, daß du mir nimmer Priester seist. Du wolltest nichts von deines Gottes Lehre wissen, so weiß auch ich nichts mehr von deinen Söhnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Je angesehener sie wurden, um so mehr verfehlten sie sich gegen mich; drum wandle ich in Schmach ihr Ansehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Sie nähren sich von meines Volkes Sünde; nach seinen Missetaten hungern sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Drum wie dem Volke so dem Priester! Ich strafe seinen Wandel und vergelte ihm nach seinen Werken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Sie essen, werden aber nimmer satt; sie buhlen, aber mehren sich nicht mehr, weil sie den Herrn verlassen, um sich der Unzucht zu ergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, '\"Der Wein und Most nimmt den Verstand gefangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mein Volk befragt nur sein Stück Holz; sein Stab gibt ihm Bescheid.\" Ein buhlerischer Geist betört es ja, und sie entfernen buhlend sich von ihrem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, '\"Auf Bergesgipfeln opfern sie; auf Hügeln bringen sie Brandopfer dar und unter Eichen, Pappeln, Terebinthen, weil so lieblich deren Schatten. Drum huren eure Töchter, und eure Bräute brechen hier die Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Soll ich an euren Töchtern nicht die Buhlerei bestrafen, an euren Bräuten nicht den Treuebruch? Sie selber haben sich den Buhlerinnen beigesellt und opfern mit geweihten Dirnen, und das gedankenlose Volk wird so geschändet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Magst du auch buhlen, Israel, so möge Juda sich doch nicht versündigen! \"Kommt nicht nach Gilgal! Wallfahrt nicht zum Götzenhaus! nicht \'Beim Herrn\'!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Beträgt sich Israel wie eine widerspenstige Kuh, kann dann der Herr es weiden lassen auf weiter Flur gleich einem Lamm?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Man bringt jetzt Ephraim ins Joch, zur Arbeit angebunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ihr Weingelage schwindet hin, bei dem sie so gebuhlt und ihrer Berge Schmach geliebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Der Atem macht ihm eng in seinen Flanken. Dann schämen sie sich ihrer Opfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '\"Hört dies, ihr Priester! Achte drauf, Haus Israel! Horch auf, du Königshaus! Denn euch obliegt das Recht. Ihr gleicht auf Mispa einer Schlinge und einem ausgespannten Netz auf Tabor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'In Grüften haben sie Unschuldige geschlachtet; ich aber ward von ihnen allen abgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'O Ephraim, ich weiß es gut; o Israel, mir ist es nicht verborgen, daß du noch immer buhlst, daß Ephraim und Israel sich unrein machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Nicht lassen ihre Werke zu, daß sie zu ihrem Gott sich kehren, ist doch der Buhlergeist in ihrer Mitte. Sie wollen von dem Herrn nichts wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Sein Prunk jedoch zeugt wider Israel, und Israel und Ephraim, sie beide stürzen hin durch ihre Schuld. Auch Juda stürzt mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Dann ziehen sie mit ihren Schafen und den Rindern aus, den Herrn zu suchen. Sie aber finden ihn nicht mehr; denn er entzieht sich ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Die Treue brachen sie dem Herrn; unechte Söhne zeugten sie. Ein Zorn verzehrt sie jetzt samt ihren Ländereien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, '\"Auf! Stoßt zu Gibea in die Posaune, zu Rama in Trompeten und schreit beim Götzenhaus: \'Nimm dich in acht, du Benjamin!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Zum Schreckensbild wird Ephraim am Tag der Züchtigung. Den Stämmen Israels verkünd ich ganz Gewisses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Die Fürsten Judas gleichen Grenzverrückern; drum gieße ich auch über sie wie Wasser meinen Grimm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Bedrückt, geknickt wird Ephraim mit Recht, weil es mit Willen Ekelhaftem folgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, '\"Wie Fieber werde ich für Ephraim, für Judas Haus wie Wurmfraß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Wenn Ephraim dann seine Krankheit merkt und Juda seinen Eiter, dann wendet Ephraim sich an Assyrien und schickt zum mächtigen König. Doch dieser kann euch auch nicht heilen und euch vom Eiter nicht befreien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Ein Löwe werde ich für Ephraim, für Judas Haus ein junger Leu. Ich selber raube, gehe fort und nehm es mit, und niemand kann es mir entreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ich gehe fort und kehre heim zu meinem Lager, bis sie sich schuldig geben und mein Antlitz suchen in der Not, sich ängstlich an mich wendend, sprechen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '\'Auf, auf! Zurück zum Herrn! Zerrissen hat er uns; er wird uns heilen. Geschlagen hat er uns; er wird uns auch verbinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Schon nach zwei Tagen wird er uns beleben. Am dritten Tag läßt er uns auferstehen, auf daß wir vor ihm leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'So laßt uns klüger werden, laßt uns trachten, den Herren zu erkennen! Gewiß gleicht dann der Morgenröte sein Erscheinen; er kommt zu uns wie milder Regen, wie später Regen, der das Land befruchtet.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, '\"Was soll ich, Ephraim, mit dir jetzt tun? Was soll ich, Juda, nun mit dir beginnen? Ist eure Frömmigkeit doch wie Gewölk am Morgen, nur wie der Tau der Morgenfrühe, der hinschwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Ich schlage deshalb drein auf die Propheten und spreche über sie das Todesurteil aus durch meines Mundes Worte; so hell wie Licht geht meine Forderung nun aus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'daß ich die Güte lieber habe als die Opfer, Erkenntnis Gottes lieber als den Opferbrand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Zu Adam überschreiten sie den Bund; dort handeln treulos sie an mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Auch Gilead ist eine Übeltäterstadt, voll blutiger Spuren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Den Menschenfängern, Räuberbanden gleich ist ihre Priesterschaft; zu Sichem morden sie die Pilger; denn Schändliches verüben sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Zu Betel sah ich Gräßliches. Daselbst hat Ephraim gebuhlt und Israel sich tief befleckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Dir, Juda, dir steht eine Dürre noch bevor. Sooft ich meines Volkes Schicksal wenden wollte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'sooft ich heilen wollte Israel, zeigt\' sich die Sünde Ephraims, Samarias Verbrechen, daß sie unredlich handeln, wie Diebe einbrechen und plündern wie die Räuber draußen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Sie überlegen nicht bei sich, daß ich gedenke aller ihrer Bosheit. Doch sie verraten ihre Taten; sie stehen mir vor Augen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Voll schlechter Absicht grüßen sie den König im Verein mit ihren Lügenfürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, '\"Sie allesamt sind nimmer zuverlässig, sind wie ein Ofen, ungeheizt vom Bäcker, der hört mit seiner Wachsamkeit nur auf vom Anrühren des Teiges bis zu dessen Gärung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Der Königstag, das ist der Tag, da Fürsten an des Weines Glut erkrankten, und dennoch lockte seine Kraft die Ausgelassenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Sie kamen ja herbei, mit einem Herzen voller Tücke gleich dem Ofen. \"Und diesmal schlief die ganze Nacht der Bäcker; da glühte er am Morgen wie ein Feuerbrand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Sie glühten insgesamt wie dieser Ofen, verzehrten sie doch ihre Vorgesetzten. \"Von allen ihren Königen jedoch, die fielen, hat nicht ein einziger mich angerufen.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'So wurde Ephraim zur Speise bei den Völkern ausgeboten; es wurde Ephraim ein Kuchen, zwiefach ausgebacken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, '\"Sein kräftig Brot verzehrten Fremde; es selber merkte nichts davon. Bei ihm ward auch die Sahne weggetrunken; es selber merkte nichts davon.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'So wird der Hochmut Israels durch ihn gebeugt; sie aber kehren nicht zum Herrn, zu ihrem Gott, zurück und suchen ihn trotz alledem nicht auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, '\"Einfältig, dumm wie eine Taube, so ist Ephraim. Sie rufen nach Ägypten und wenden sich an Assur.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Wo sie auch hinziehn, werfe ich mein Netz darüber und hole sie herab, des Himmels Vögeln gleich. Ich strafe sie, sobald nur ihre Reise ruchbar wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Weh ihnen, daß sie treulos an mir werden! Verderben über sie, daß sie an mir gefrevelt! Selbst wenn ich sie erlöste, würden sie vor mir nur heucheln');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'und nicht aus ganzem Herzen zu mir flehen. Sie wurden nur auf ihrem Lager heulen, nur um Korn und Wein bekümmert, dann aber wieder abfallen von mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Mag ich sie strafen, mag ich sie stärken, sie sinnen doch nur Schlimmes wider mich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Sie kehren nimmermehr zurück. Sie gleichen einem Bogen, der versagt. Und ihre Fürsten fallen durch das Schwert ob ihres vielen Schwätzens und ihres gotteslästerlichen Redens im Ägypterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Schrei laut, wie mit Trompetenton, dem Adler gleich, über dem Haus des Herrn! \"Weil meinen Bund sie übertreten und über meine Lehre sich hinweggesetzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'so sollen sie zu mir noch schreien: \'Wir kennen Dich, Gott Israels.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Vom Guten sagte Israel sich los; der Feind wird es verfolgen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, '\"Sie haben Könige berufen, aber ohne mich; sich Fürsten eingesetzt; ich wußte nichts davon. Sie bildeten aus ihrem Silber, ihrem Gold sich Götzenbilder, daß sie vernichtet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Verwerflich ist dein Kalb, Samaria. \"Mein Zorn ist gegen sie entbrannt. Wie lange können sie nicht Lauterkeit ertragen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Denn welcher Stier wär Gott? Ein Künstler hat das Bild gemacht; ein Gott ist\'s nicht. Es kann in Stücke gehn, das Kalb Samarias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, '\"Sie säen Wind; deswegen ernten sie auch Sturm.\" Nicht sproßt ihm eine Saat. Was wächst, das gibt kein Mehl und würde es gedeihen, verzehrten es die Fremden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, '\"Verschlungen wird so Israel. Sie gelten bei den Heiden jetzt als unnütz Ding.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Ja, hin nach Assur laufen sie, zum Wildesel, der nur bedacht auf seinen Nutzen; dort spendet Ephraim der Liebe Gaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, '\"Doch teilen sie auch solche bei den Heidenvölkern aus, ich lasse dennoch sie zusammenschrumpfen. Und schon beginnen sie, sich zu vermindern, beim Druck des Fürstenkönigs.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Zwar schafft sich Ephraim viele Altäre an zum Sündigen; doch werden die Altäre ihm zur Sünde werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, '\"Und habe ich ihm vielmals meine Lehre vorgeschrieben, sie achten sie wie fremde Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Die Opfer für mich ausgewählter Böcke mögen für sich selbst sie schlachten und auch das Fleisch verzehren!\" Der Herr hat keine Freude dran; vielmehr gedenkt er ihrer Schuld, und ihre Sünden sucht er heim. Sie müssen wieder nach Ägypten ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Nichts wissen will von seinem Schöpfer Israel; Paläste baut es sich. - Auch Juda legte viele feste Städte an. \"Ich aber sandte Feuer wider seine Städte, und dies verzehrte seine Burgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Der Freude überlaß dich nimmer, Israel, und juble nicht wie andere Völker! Du hast ja buhlend deinen Gott verlassen und dich am Buhlerlohn erfreut auf allen korngefüllten Tennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, '\"Die Tenne und die Kelter nähren sie nicht mehr. Der neue Wein läßt sie im Stich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Sie bleiben nimmermehr im Land des Herrn. Denn Ephraim muß nach Ägypterland zurück; Unreines müssen sie in Assur essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Sie spenden nicht mehr Wein dem Herrn und bringen ihre Opfer ihm nicht mehr. \"Sie haben dann nur, was den Trauerspeisen ähnlich. Wer es genießt, wird dadurch unrein.\" Ihr Brot dient nur zur Stillung ihres Hungers; nicht kommt es mehr ins Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Was wollt ihr am Versammlungstage tun? Und was am Tag des Herrenfestes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Die der Verheerung schon entkommen sind, die hält Ägypten fest, und Memphis wird ihr Grab. Ihr glänzend Schatzhaus wird der Nesseln Erbbesitz, und Disteln sind in ihren Zelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, '\"Der Strafe Tage sind gekommen, die Tage der Vergeltung angebrochen; sie klagen Israel ob seines Spruches an: \'Ein Tor ist der Prophet; der Geistesmann ist aberwitzig\', ob der Größe dieser deiner Sünde, ja, groß war deine Anfeindung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Der Seher ist der Wächter Ephraims, des Volkes meines Gottes. Auf allen seinen Wegen liegt jetzt eine Vogelstellerschlinge; Anfeindung gibt\'s sogar im Hause seines Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'So tief sind sie gesunken wie in den Tagen Gibeas. Drum muß er ihrer Schuld gedenken und ihre Sünde ahnden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, '\"Wie wilde Trauben in der Wüste fand ich Israel. Wie frühe Feigen an dem Feigenbaum, so sah ich eure Väter an ihrem ersten Anfange. Sie aber gingen zu dem Peorsbaal und weihten sich der Schande; das waren Götzen, wie sie sie liebten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Die Menge Ephraims verfliegt nach der Geburt wie Vögel, ja in der Schwangerschaft und schon bei der Empfängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Und zögen sie auch ihre Söhne auf, so mache ich sie kinderlos; denn: \'Jammer über sie, wenn ich von ihnen weiche!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'O Ephraim! Wie sah ich im Gefilde jenen rohen Felsen, wo sich Ephraim bereit gehalten hat, dem Henker seine Kinder zuzuführen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, '\"Gib ihnen, Herr! Was sollst Du geben? Gib ihnen unfruchtbaren Mutterschoß und welke Brust!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, '\"All ihre Schlechtigkeit geschah zu Gilgal; deshalb verstoß ich sie aus meinem Hause ob der Verruchtheit ihrer Werke. Ich kann sie nicht mehr lieben. Abtrünnige sind alle ihre Fürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Geschlagen wird jetzt Ephraim. Verdorrt ist seine Wurzel. Sie sollen keine Frucht mehr bringen! Und sollten dennoch sie gebären, so geb ich doch die Leibesfrucht, die sie ersehnen, dem Tode preis.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mein Gott verwirft sie ganz und gar, weil sie ihm nicht gehorchen. Drum sind sie flüchtig bei den Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Den Weinstock leerte Israel und nahm sich seine Frucht. Doch mit der Menge seiner Frucht vermehrte es die Anzahl der Altäre. Je reicher seines Landes Ernte, um so schöner machte es die Denksäulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, '\"Ihr Herz ist unbeständig; jetzt müssen sie es büßen.\" Er selbst zerschlägt ihre Altäre, zerschmettert ihre Denksäulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Sie sagen ferner: \"Wir wollen nichts von einem König wissen; wir fürchten uns nicht vor dem Herrn. Was kann uns da der König tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, '\"Ja, nichts als Worte machen sie und schwören falsch und schließen Bünde. Das Recht vertilgen sie, als wär es Giftkraut in den Ackerfurchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Besorgt sind um des Götzenhauses Kälber die Bewohner von Samaria. Schon trauert drob sein Volk, und seine Priester klagen laut darum, weil fortgewandert ist sein Schmuck.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Es selber bringt man auch nach Assur, als eine Gabe für den mächtigen König. Dann hüllt sich Ephraim in Schande, und seines Kunstwerks schämt sich Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Samaria mit seinem Moloch schwindet hin wie Späne auf dem Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Verwüstet werden auch die Götzenhöhen, die Sündenstätten Israels. Nur Dorngesträuch und Disteln sprossen dort auf den Altären. Sie sprechen zu den Bergen: \'Decket uns!\', und zu den Hügeln: \'Fallet über uns!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Noch schwerer als dereinst zu Gibea hast du gesündigt, Israel. \"Sie meinten freilich, daß ein Krieg, wie er zu Gibea die Söhne der Verruchtheit einst getroffen, sie nicht treffe');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Doch ich bestrafe sie in meinem Ungestüm. Es sollen Völker gegen sie sich sammeln, um sie zu strafen wegen ihrer beiden Greueltaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ein wohlgezähmtes Rind war Ephraim, das Dreschen gerne hatte. Ich prüfte seines Nackens Festigkeit. So spannt\' ich Ephraim ins Joch, und Juda pflügte, und Jakob zog die Furchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Sät euch Gerechtigkeit und erntet, wie die Liebe es verlangt! Brecht euch ein neues Feld um! Es ist Zeit, den Herrn zu suchen, bis er kommt und Segen auf euch träufle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, '\"Ihr aber habt die Bosheit eingepflügt und Freveltat geerntet, Lügenfrucht verzehrt. - Weil du auf deine schnellen Rosse, deine vielen Krieger dich verlassen hast,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'kommt nun Verderben über deine Stämme, und alle deine Festen werden so zerstört, wie Salman einstens Bet-Arbel im Krieg zerstörte, wo mit den Kindern auch zerschmettert ward die Mutter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Also verfährt er auch mit euch, Haus Israel, infolge eurer Schlechtigkeit. Bald sinkt er hin, hinsinkt der König Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, '\"Als Israel noch jung gewesen, hab ich\'s liebgewonnen, und von Ägypten her schon nenne ich es meinen Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Je mehr man aber ihnen rief, nur um so weiter wandten sie sich ab. Sie opferten den Baalen und räucherten den Götzenbildern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, '\"Ich lehrte Ephraim das Gehen und nahm\'s auf meinen Arm. Doch sie erkannten nicht, daß ich sie heil bewahrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Und wollten je die Leute ihnen wehe tun, umgab ich sie mit dem Gehege meiner Liebe: Ich war auf ihrer Seite, einem gleich, der denen wehrte, die sie auf die Wange schlagen wollten. Ich neigte mich ihm zu und gab ihm Nahrung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nun muß es wieder nach Ägypterland zurück, und ein Assyrer wird sein König werden. Die Umkehr hat es ja verweigert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Eintrocknung kommt jetzt über seine Haut, vernichtet seine Gliedmaßen und zehrt an ihren Kräften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, '\"Mein Volk, verwirrt, weil untreu gegen mich, es läßt sich nicht bewegen, will man es zur Rückkehr rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Was soll ich, Ephraim, dir tun, was über dich verhängen, Israel? Wie? Sollte ich dir so wie Adma tun, das Schicksal Seboims dich teilen lassen? Mein Herz dreht sich in mir; mein ganzes Mitleid ist erregt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Ich kann nicht meinen heißen Ingrimm in die Tat umsetzen. Ich kann nicht Ephraim wieder vertilgen. Ich bin ja Gott und nicht ein Mensch. In deiner Mitte weile ich als Heiliger: Ich komme nicht im Grimm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Dann ziehen sie dem Herren nach, wenn er mit LÖwenstimme brüllt, und brüllt er, alsdann eilen zitternd Söhne aus dem Westen her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, '\"Sie eilen zitternd wie die Vögel aus Ägypten, wie Tauben aus dem Land Assyrien. Ich bringe sie in ihre Heimat wieder.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, '\"Doch jetzt umgibt mich Ephraim mit Lug, mit Trug das Haus von Israel.\" Doch Juda geht noch immerhin mit Gott und hält dem Heiligen die Treue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, '\"Nach Sturm geht Ephraims Verlangen; dem Ostwind jagt es nach. Den ganzen Tag lang häuft es Lüge und Verderben. Bald schließt es einen Bund mit Assur; bald bringt es nachägypten Öl.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Jedoch mit Juda muß der Herr auch rechten. - Nach seinem Wandel aber straft er Jakob, um ihm nach seinen Werken zu vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, '\"Im Mutterschoße schon betrog er seinen Bruder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Er kämpfte gegen einen Engel und obsiegte, nachdem er unter Tränen ihn um Gnade angefleht. Zu Betel hat er wieder ihn gefunden und dort mit ihm geredet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '\"Der Herr, Gott der Heerscharen Herr\", das ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Doch kehre um zu deinem Gott! Befleiße dich der Tugend und Gerechtigkeit! Und hoffe stets auf deinen Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, '\"Falschwaage hält der Kanaaniter in der Hand; er liebt Betrügerei.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Da sagt nun Ephraim: \"Auch ich bin reich geworden; ich habe Schätze mir erworben. An allem, was ich mühevoll errang, ist kein Vergehn zu finden, das da Sünde wäre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '\"Ich, der Herr, ich bin dein Gott vom Land Ägypten her. In Zelten laß ich wiederum dich wohnen wie in den Tagen der Versammlung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ich rede abermals zu den Propheten, laß ein Gesicht aufs andere folgen und lehre auch in Gleichnissen durch die Propheten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Gileads Schandbilder sind eitel Eitelkeit; in Gilgal schlachten sie zum Opfer Knaben; Altäre haben sie so viel wie Haufen Steine auf den Furchen ihrer Äcker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, '\"In Syriens Gefilde floh einst Jakob, und um ein Weib ward Israel ein Knecht, und um ein Weib hat er gehütet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Durch einen Seher aber hat der Herr einst Israel aus dem Ägypterland herausgeführt; durch einen Seher ward\'s gehütet. Doch hat ihm bittern Kummer Ephraim bereitet; drum wird er seine Blutschuld auf ihm lassen, und ahnden wird der Herr an ihm die zugefügte Schmach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Als Ephraim den Schrecken feierte, da war es angesehn in Israel. Doch als es mit dem Baal sich versündigt, starb es hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Und jetzt noch sündigen sie weiterhin und machen sich aus ihrem Silber Bilder, durch ihre Kunst sich Götzenbilder, die nichts als Schöpfungen von Handwerkern. An jene richten sie das Wort und, Menschen opfernd, küssen sie die Kälber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Drum werden jene wie ein Morgenwölkchen, wie Tau, der früh verschwindet, wie Spreu, die von der Tenne stäubt, wie Rauch, der durch das Fenster zieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, '\"Ich aber bin der Herr, dein Gott, vom Land Ägypten her. Doch außer mir sollst keinen andern Gott du kennen, noch einen Heiland außer mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ich weidete dich in der Wüste, im Land der Trockenheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Je mehr sie weideten, nur um so satter wurden sie. Sie waren satt; da hob sich stolz ihr Sinn; sie wollten nichts mehr von mir wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'So will ich gegen sie ein Löwe werden und wie ein Panther auf dem Wege lauem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Ich gehe auf sie los wie ein der Brut beraubten Bär, zerreiße ihren Brustknochen und fresse dort sie wie ein Löwe auf.\" Die wilden Tiere werden dich zerfleischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Verderben bringen sie dir, Israel. \"Bei mir allein steht deine Rettung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Wo bleibt dein König? Er sollte dir in allen deinen Städten helfen! Wo deine Richter? Daß du gesagt: \'Gib König mir und Fürsten!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'In meinem Zorne gebe ich dir einen König: in meinem Grimme nehme ich ihn wieder weg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Die Sündenliste Ephraims ist nunmehr zugebunden, zugerollt sein Sündenbuch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Ergreifen werden es Geburtswehen. \"Doch ist es keine kluge Mutter; denn nicht die rechte Zeit stellt sich zum Kindesdurchbruch ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Ich könnte sie vom Totenreich befreien, sie vom Tod erretten. Ach, deine Seuchen, Tod; ach, deine Pest, du Totenreich! Vor mir verbirgt sich Trost.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Inzwischen läßt es Gras aufsprossen; da wird ein Ostwind kommen, ein Sturm des Herrn, der aus der Wüste braust, der seinen Quell vertrocknet, seinen Born versiegen macht. Er nimmt ihm aller Kostbarkeiten Schätze mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samaria wird es bereuen, daß es widerspenstig gegen seinen Gott gewesen. Sie sinken hin durchs Schwert. Zerschmettert werden ihre Kinder, ihre Wöchnerinnen aufgeschlitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Bekehr dich, Israel, zum Herrn, zu deinem Gott! \"Durch eigene Schuld kommst du zu Fall.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Nehmt mit euch Worte, kehrt zum Herrn zurück und sprecht zu ihm: \"Vergib die Sünde ganz und gar! Nimm gnädig an, wenn wir einlösen unserer Lippen Rufe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Uns darf nie wieder Assur helfen. Wir wollen nimmermehr auf Rossen reiten und nicht mehr sagen \'Unser Gott\' vom Machwerk unserer Hände. Wer Gnade bei Dir findet, der ist glücklich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, '\"Ich will die Folgen ihres Abfalls heilen; ich liebe sie in unverdienter Weise. Von ihm kehrt sich mein Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Ich bin wie Tau für Israel; wie eine Lilie wird es blühen und Wurzeln schlagen gleich der Pappel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Es breiten seine Sprossen weit sich hin, und eine Krone hat es wie der Ölbaum, und einen Duft gleich wie der Libanon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Und wieder ruhen sie in seinem Schatten. Getreide bauen sie und pflanzen wunderwieviel Reben, und deren Ruhm wird sein wie der des Weins vom Libanon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, '\"Was gehn euch an die Götzen Ephraims? Ich habe es geschwächt und lasse es erstarken. Ich bin wie eine grüne Zeder. Von mir wird dir die Frucht verliehn.\" Wer klug, gibt darauf acht, und wer verständig, merkt darauf: \"Gerade sind des Herren Wege, und die Gerechten wandeln drauf. Die Schlechten aber kommen drauf zu Fall.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Das Herrnwort, das an Joel, Petuels Sohn, erging:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, '\"Vernehmet dies, ihr Ältesten! Horcht alle auf, die ihr im Lande wohnt! Geschah dergleichen wohl in euren Tagen? Geschah\'s in eurer Väter Tagen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Davon erzählet euren Kindern, und eure Kinder ihren Kindern, und deren Kinder einem künftigen Geschlecht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Was übrigließ der Nager, fraß die Heuschrecke; was übrigließ die Heuschrecke, das fraß der Fresser, und was der Fresser übrigließ, das fraß der Abschäler.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Ihr Zecher, wachet auf und weinet! Und heult, ihr Weinvertilger alle, um den Wein, daß eurem Munde er entzogen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, '\"Ein Volk drang in mein Land, gewaltig, ohne Zahl, und seine Zähne waren Löwenzähne, sein Gebiß das einer Löwin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Es machte meinen Weinstock wüst und meinen Feigenbaum zu Reisig; es hat ihn gänzlich abgeschält und ihn vernichtet, und seine Ranken wurden blaß');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'wie eine Jungfrau, die ihr Trauerkleid sich anlegt wegen des Verlobten ihrer Jugend.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Speise- und Trankopfer im Haus des Herrn gibt\'s nimmermehr. Die Priester schmachten hin, des Herren Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, '\"Verwüstet ist die Flur, in Trauer das Gefilde; denn abgestorben ist das Korn, der Wein versiegt, das Öl vertrocknet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Die Ackersleute sind enttäuscht; die Bauern klagen um den Weizen und die Gerste. Des Feldes Ernte ist dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, '\"Der Weinstock ist verdorrt, der Feigenbaum verwelkt. Granaten, Palmen, Apfelbäume, des Feldes Bäume insgesamt sind dürr. - Beschämt entfloh die Freude von den Menschkindern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'So hüllet euch in Bußgewänder! Klagt, Priester! Wehklagt, Diener des Altars! Geht heim! Verbringt die Nacht in Bußgewändern, ihr, meines Gottes Diener! Versagt sind die Speise- und Trankopfer dem Hause eures Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Ein Fasten ordnet an! Berufet eine Volksversammlung, Älteste! Versammelt alle Einwohner des Landes hin zum Haus des Herren, eures Gottes, und ruft zum Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '\"Weh, welch ein Tag!\" Ja, nahe ist der Tag des Herrn; Lawinen aus dem Hochgebirge gleich kommt er heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, '\"Ward nicht vor unsern Augen Nahrung weggenommen, aus unseres Gottes Haus die Freude und der Jubel?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, '\"Die Körner sind vertrocknet unter ihren Schollen. Verödet sind die Speicher, entleert die Scheunen; denn das Getreide ist dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Wie klagt das Vieh? Die Rinderherden sind verstört; denn nirgends Weide mehr für sie! Zugrunde gehn der Schafe Herden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Sie schreien, Herr, zu Dir. Denn Feuer zehrt der Steppe Auen auf und Flammenglut des Feldes Bäume all.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Des Feldes wilde Tiere schreien selbst zu Dir. Denn ausgetrocknet sind die Wasserbäche; Feuer hat verzehrt der Steppe Auen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '\"Auf, Sion, stoß in die Posaune! Auf meinem heiligen Berge rufet laut, daß alle Einwohner des Landes zittern: \'Gekommen ist der Tag des Herrn!\'\" Schon ist er nahe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'ein Tag der Finsternis und Dunkelheit, ein Tag der finstern Wolkennacht. \"Wie tiefes Dunkel, ausgebreitet auf den Bergen, so ist ein Volk, so groß und stark wie keines je gewesen und nach ihm keines kommt bis in der Zukunft fernste Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Ein Feuer frißt vor ihm, und hinter ihm her lodern Flammen. War auch vor ihm das Land wie Edens Garten, zur öden Wildnis wird\'s dahinter. Verschont bleibt nicht ein Teil von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Wie Pferde ist es anzuschauen; sie laufen wie die Rosse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Gerade wie mit Wagenrasseln hüpfen sie auf Berges Höhen hin und wie mit dem Geprassel einer Feuerflamme, die Stoppeln frißt, so wie ein ganz gewaltig Volk, das sich zum Kampfe rüstet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Vor ihm erzittern rings die Völker, und jedes Antlitz ist verzerrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Gleich Kriegern stürmen sie daher, ersteigen Mauern gleich den Kämpfern, von denen jeder seines Weges zieht, die nimmer ihre Bahnen kreuzen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'und keiner an den andern stößt, von denen jeder rüstig seine Bahn beschreitet, und die nicht brechen, wenn Geschosse auch einschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Sie schwärmen in der Stadt umher. Die Mauer laufen sie hinauf und steigen in die Häuser und dringen wie die Diebe durch die Fenster.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, '\"Die Erde bebt vor ihm; die Himmel zittern. Die Sonne und der Mond verfinstern sich, die Sterne ziehen ihren Glanz zurück.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Der Herr läßt seine Stimme vor seinem Heer erschallen; gar groß ist seine Schar. Gewaltig tut es seinen Willen; ist doch der Tag des Herrn so groß und furchtbar. Wer kann ihn bestehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '\"Nun denn\", ein Spruch des Herrn, \"so kehrt zu mir zurück, mit eurem ganzen Herzen, mit Fasten, Weinen, Klagen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Zerreißet lieber euer Herz als eure Kleider, und kehrt zurück zum Herrn, zu eurem Gott! Er ist ja sonst so gnädig und barmherzig, zum Zorne langsam, reich an Huld und läßt das Unheil sich gereuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Wer weiß, ob er sich\'s nicht gereuen läßt und hinter sich zurückläßt Segen, Speise- und Trankopfer für euren Gott und Herrn?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, '\"Auf Sion stoßt in die Posaune! Ein Fasten ordnet an! Berufet eine Volksversammlung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Das Volk versammelt! Versammelt die Gemeinde! Die Greise holt zusammen! Die Kinder bringt herbei, ja selbst die Säuglinge! Der Neuvermählte lasse seine Kammer, die Braut ihr Brautgemach!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Die Priester sollen zwischen Vorhof und Altare knien, des Herren Diener sollen sprechen: \"Schone, Herr, Dein Volk! Und gib Dein Erbteil nicht der Schande preis, der Knechtschaft bei den Heiden! Weswegen darf man bei den Völkern sprechen: \'Wo bleibt ihr Gott?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Der Herr nehme sich seines Landes an und schone seines Volkes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Der Herr hob an und sprach zu seinem Volk: \"Ich send euch wieder Korn und Wein und Öl, daß ihr daran Genüge habt, und geb euch bei den Heiden nimmermehr der Schande preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Den Nordfeind aber treibe ich von euch und werf ihn in ein dürres, ödes Land, ins Ostmeer seinen Vortrab und seinen Nachtrab in das Westmeer. Da steigt von ihm Gestank auf; ein übler Duft steigt von ihm auf.\" Ja, Großes wird er tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Du Land, fürcht dich nicht mehr! Nein, jauchze, juble! Denn Großes unternimmt der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, '\"So fürchtet euch nicht mehr, ihr Tiere auf dem Feld! Der Steppe Auen grünen wiederum; die Bäume tragen wieder Früchte; der Feigenbaum und Weinstock zeigen ihre Kraft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Und ihr, ihr Sionssöhne, jauchzt! Freut euch im Herrn, in eurem Gott! Er gab euch ja ein Warnungszeichen hin zur Frömmigkeit. Jetzt aber läßt er niederrieseln euch den frühen und den späten Regen wie ehedem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'damit die Tennen voll Getreide werden, und von Wein und Öl die Keltern überströmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, '\"Ersetzen will ich euch die Jahre, da die Heuschrecken gefressen haben, die Fresser, Nager und die Abschäler, mein großes Heer, das gegen euch ich ausgesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Ihr eßt, bis ihr gesättigt seid, und preist des Herren, eures Gottes, Namen, der wunderbar mit euch verfahren. - Mein Volk wird nicht in Ewigkeit zuschanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Ihr wisset dann, daß ich inmitten Israels verweile, daß ich der Herr bin, euer Gott, und keiner sonst, und daß mein Volk in Ewigkeit nicht mehr zuschanden wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '\"Hernach geschieht es, daß ich meinen Geist ausgieße über alles Fleisch, daß eure Söhne, eure Töchter prophezeien und eure Greise Träume haben und eure Jünglinge Gesichte schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Selbst über Sklaven und Sklavinnen werde ich in jenen Tagen meinen Geist ausgießen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Dann sende ich am Himmel und auf Erden Zeichen, Blut, Feuer, Rauch in hohen Säulen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Die Sonne wandelt sich in Finsternis, der Mond in Blut, bevor der Tag des Herrn erscheint, der große, fürchterliche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Dann ist in Sicherheit, wer sich zum Herrn bekennt. Denn eine sichere Statt ist auf dem Sionsberge zu Jerusalem zu finden. Der Herr hat\'s ja verheißen, und zwar für die Entronnenen, die sich der Herr bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, '\"Denn seht, in jenen Tagen und zu jener Zeit, da wende ich das Schicksal Judas und Jerusalems. Ich sammle alle Heiden und führe sie ins Tal von Josaphat und gehe dort mit ihnen ins Gericht, weil sie mein Volk und Erbteil Israel zerstreuten unter Heidenvölker und mein Land zerteilten. Ja, sie verlosten selbst mein Volk und gaben manchen Knaben hin für eine Dirne und handelten um Wein ein Mädchen ein und soffen. - Wie steht ihr doch zu mir, du Tyrus und du Sidon, und ihr Bezirke Philistäas insgesamt? Ihr wolltet gar Vergeltung an mir üben? In schnellster Eile bring ich euer Tun auf euer Haupt zurück, ihr Räuber meines Silbers, meines Goldes. Und meine herrlichsten Kleinodien brachtet ihr in eure Tempel. Die Söhne Judas und Jerusalems verkauftet ihr den Griechensöhnen, um sie recht weit von ihrer Heimat zu entfernen. Fürwahr, ich lasse sie den Ort verlassen, wohin ihr sie verkauft, und bringe so auf euer Haupt all euer Tun zurück. Und ich verkaufe eure Söhne, eure Töchter durch die Söhne Judas. Und die verkaufen sie an die Sabäer, an ein fernes Volk.\" Dies sagt der Herr. - Verkündet bei den Heiden dies: \"Bereitet euch zum Krieg! Werbt Streiter an! Heran mit allen Kriegern, die ausziehen wollen! Zu Schwertern schmiedet eure Pflüge um, zu Lanzen eure Winzermesser! Der Schwächling sprech sogar: \'Ich bin ein Held.\'\" Ihr Heiden alle, eilt herbei! Kommt her von allen Seiten! Und sind sie dann beisammen, führe Deine Streiter, Herr, dorthin! \"Aufbrechen sollen sie! Die Heiden mögen ziehn ins Tal von Josaphat! Dort lasse ich mich nieder, um die ganze Heidenwelt ringsum zu richten. Legt an die Sichel! Reif ist die Ernte. Herbei! Nun tretet! Voll ist die Kelter. Die Kufen laßt auslaufen! Gewaltig ist ihr Schäumen.\" Die Scharen! Scharen im Entscheidungstal! In dem Entscheidungstal naht sich der Tag des Herrn. Die Sonne und der Mond verfinstern sich; die Sterne ziehen ihre Strahlen ein. Aus Sion brüllt der Herr, und seine Stimme läßt er aus Jerusalem ertönen. Der Himmel und die Erde zittern. Nur seinem Volke ist der Herr ein Schutz, ein Hort den Söhnen Israels. \"So werdet ihr erfahren, daß ich der Herr, ich euer Gott, der ich auf meinem heiligen Berg zu Sion wohne. Jerusalem wird dann ein Heiligtum; kein Fremdling zieht mehr durch.\" An jenem Tage dann geschieht es, daß von Wein die Berge triefen, von Milch die Hügel fließen und Judas Bäche all von Wasser strömen. Und eine Quelle quillt vom Haus des Herrn; der Frommen Tal bewässert sie. Ägypten wird zur Wüstenei und Edom öde Steppe wegen der Mißhandlungen der Söhne Judas, daß sie in ihrem Land unschuldig Blut vergossen. Doch Juda bleibt in Ewigkeit bestehen, Jerusalem durch alle kommenden Geschlechter. \"Ich räche ihre Blutschuld, und ich lasse sie nicht ungestraft.\" Der Herr wohnt wiederum auf Sion.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Die Worte des Amos, der zu Tekoas Viehzüchter gehörte und Gesichte sah zur Zeit des Judakönigs Ozias, sowie zur Zeit des Israelkönigs Jeroboam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'des Joassohns, zwei Jahre vor dem Erdbeben, und der zu sagen pflegte. \"Aus Sion brüllt der Herr, und seine Stimme läßt er aus Jerusalem erschallen. Dann stehn der Hirten Anger traurig, und Karmels Gipfel ist beschämt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So spricht der Herr: \"Des Frevels von Damaskus wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück. Sie zogen über Gilead Eisenwalzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Nun sende ich ein Feuer in das Haus des Asael, und fressen soll\'s die Schlösser Benhadads.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Die Riegel von Damaskus will ich jetzt zerbrechen. Vertilgen will ich die Bewohner aus dem Sündental, den Zepterträger aus dem Haus der Lust, und wandern soll nach Kir der Aramäer Volk.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So spricht der Herr: \"Des Frevels Gazas wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück. Sie haben weggeschleppt in voller Zahl Gefangene und sie an Edom ausgeliefert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Ich schleudre Feuer in die Mauern Gazas, und fressen soll es seine Burgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Aus Asdod tilg ich die Bewohner, aus Askalon, wer dort das Zepter führt, und gegen Akkaron erheb ich wieder meine Hand, und untergehen soll, was von Philistern übrig ist.\" So spricht der Herr, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So spricht der Herr: \"Um seines Frevels willen, des drei- und vierfach schändlichen, daß Tyrus das Grenzland Salomos an Syrien ausgeliefert, nehm\' ich es nicht zurück, des Bruderbundes nimmer eingedenk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Ich sende Feuer gen die Mauern von Tyrus, fressen soll es seine Burgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So spricht der Herr, \"Des Frevels Edoms wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück, daß dies den Bruder mit dem Schwert verfolgt, sein Mitgefühl erstickt und seinen Zorn für immer festgehalten und ewig hat genährt des Hasses Glut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Ich sende Feuer wider Teman, es fresse Bosras Burgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So spricht der Herr: \"Des Frevels Ammons wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück, daß sie das Bergland Gileads eroberten, um ihre Grenzen zu erweitern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'ich sende Feuer gegen Rabatts Mauern, und fressen soll es seine Burgen am Kampftag unter Kriegsgeschrei, im Wettersturm am Tag des Ungewitters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Fort muß ihr König in Gefangenschaft mit seinen Fürsten insgesamt.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So spricht der Herr: \"Des Frevels Moabs wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück, daß die Gebeine eines Edomiterkönigs es zu Tüncherkalk verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Ich sende Feuer wider Moab, und fressen soll\'s die Burgen Kerijots. Und Moab stirbt im Schlachtgetümmel, bei Kriegsgeschrei und bei Trompetenschall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Ich tilge ihm den Herrscher aus der Mitte und würge mit ihm alle seine Fürsten.\" So spricht der Herr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So spricht der Herr. \"Des Frevels Judas wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück, daß es des Herrn Gesetz verwirft und seine Satzungen nicht hält. Nur ihre Lügen haben sie verführt, die gleichen, denen ihre Väter schon gefolgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'So sende ich ein Feuer wider Juda, und fressen soll\'s die Burgen von Jerusalem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So spricht der Herr: \"Israels Frevels wegen, des drei- und vierfach schändlichen, nehm\' ich es nicht zurück, daß sie Unschuldige um Geld verkaufen und Arme um ein Paar Sandalen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Sie, die um Staubes willen nach der Armen Kopfgeld gieren und Dürftiger Steuern höher schrauben, und dabei geht der Mann mit seinem Vater zu üppigem Mahl, um meinen heiligen Namen zu entweihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Auf Decken buntgewirkt, so liegen sie zur Seite eines jeglichen Altars und zechen Bier in ihres Gottes Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Und doch vertilgte ich vor ihnen einst den Amoriter, hochgewachsen wie die Zedern, stark wie Eichen. Ich tilgte oben seine Frucht und unten seine Wurzeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Ich war es, der euch aus Ägypterland geführt und euch versorgte vierzig Jahre in der Wüste, daß ihr das Amoriterland erobern konntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Propheten habe ich für mich erweckt aus euren Söhnen und Nasiräer mir aus euren Jünglingen. Ist dem nicht so, ihr Söhne Israels?\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '\"Ihr aber gebt den Nasiräern Wein zu trinken, gebietet den Propheten: \'Nimmer dürft ihr prophezeien!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Fürwahr so will ich euch zermalmen auf dem Boden, wie volle Garben ein Dreschwagen zermalmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Die Flucht vergeht alsdann dem Schnellen. Nicht fühlt der Starke Kraft in sich; der Krieger weiß sich nicht zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Und selbst der Bogenschütze tritt nicht an; nicht rettet sich der schnelle Läufer, und auch der Reitersmann vermag sein Leben nicht zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'An jenem Tag flieht nackt der Mutigste der Krieger.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Vernehmet diesen Ausspruch, den wider euch der Herr getan, ihr Söhne Israels, und wider alle die Geschlechter, die ich aus dem Ägypterland geführt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Er lautet so: \"Ich lernte euch von allen den Geschlechtern der Erde kennen. Drum strafe ich an euch all eure Missetaten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Begeben zwei sich zueinander, wenn sie sich nicht zum voraus schon bestellt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brüllt denn im Wald der Löwe, eh er seine Beute hat? Läßt denn ein junger Leu aus seinem Lager seine Stimme tönen, bevor er einen Fang gemacht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Fällt auf den festen Boden wohl ein Vogel, wenn nicht ein Wurfholz für ihn dagewesen? Springt denn vom Boden eine Falle auf, bevor sie wirklich einen Fang gemacht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Wird die Trompete in der Stadt geblasen, ohne daß die Leute recht erschrecken? Trifft eine Stadt ein Ungemach, das nicht der Herr veranlaßt hat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Nichts tut der Herr, der Herr, er habe denn zuvor schon sein Geheimnis seinen Dienern, den Propheten, offenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Ein Löwe brüllt. Wer hätte keine Angst? Der Herr, der Herr spricht. Wer prophezeite nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Vermeldet in den Schlössern von Assyrien, in des Ägypterlandes Schlössern und verkündet: Versammelt euch jetzt auf Samarias Bergen und seht das tolle Treiben an in einer Mitte und die Bedrückungen in seinem Innern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Ja, recht zu tun, verstehn sie nicht\", ein Spruch des Herrn, \"sie, die in ihren Schlössern Freveltaten häufen und Gewalttat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Darum\", so spricht der Herr, der Herr, \"bedrängt ein Feind dies Land. Mit deinem Glanze geht\'s zu Ende jetzt, und deine Schlösser werden ausgeplündert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So spricht der Herr: \"Wie aus des Löwen Rachen ein Paar Beine ein Hirte rettet oder bloß ein Ohrläppchen, so werden auch die Söhne Israels sich retten, die in Samaria wohnen, mit einem Bettgestell und einem Damaszener Deckchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Hört! Zeuget wider Jakobs Haus!\" Ein Spruch des Herrn, des Herrn, des Gottes der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, '\"Wenn ich die Frevel Israels an ihm bestrafe, dann nehme ich an den Altären Betels Rache, daß des Altares Hörner, abgehauen, zu Boden fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Das Winterhaus zerschlage ich mitsamt dem Sommerhaus, und die mit Elfenbein geschmückten Häuser werden ihrem Untergang verfallen. Große Häuser schwinden gänzlich hin.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Ihr Basanskühe, hört dies Wort, die ihr verweilt auf Samarias Berg, die ihr die Niedrigen bedrücken und die Armen schinden helft, die ihr zu euren Herren sprecht: \"Nur immer her, damit wir trinken können!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Geschworen hat der Herr, der Herr, bei seiner Heiligkeit: \"Fürwahr, es kommen Tage über euch, da treibt man euch mit Haken fort, was von euch übrigbleibt mit Stacheln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Da schleppt man euch hinaus mit Ungestüm, die eine nach der anderen, und wirft euch in den Fluß.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '\"Nach Betel zieht und sündigt! Nach Gilgal, sündigt dort noch mehr! Bringt morgens eure Opfer dar, am dritten Tage eure Zehnten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Dankopfer bringt von dem Gesäuerten! Ruft auf zu freiwilligen Opfern! Ihr tut es ja so gern, ihr Söhne Israels.\" Ein Spruch des Herrn, des Herrn. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '\"Schon machte ich an allen euren Städten eure Zähne blank und ließ an allen euren Plätzen an Brot es mangeln, und dennoch kamt ihr nicht zu mir zurück.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '\"Und ich versagte euch den Regen drei Monde vor der Ernte. Ich ließ auf eine Stadt zwar regnen, doch auf die andre nicht. So ward die eine Gegend zwar beregnet; jedoch die andere, auf die kein Regen fiel, verdorrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'So taumelten die Städte zwei und drei zu einer Stadt, um Wasser dort zu trinken, und wurden nicht gesättigt, und ihr kamet dennoch nicht zu mir zurück.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '\"Ich schlug mit Kornbrand euch und Meltau, auf schwere Weise eure Gärten, eure Weinberge. Die Heuschrecke fraß Feigen- und Olivenbäume ab, und dennoch kamt ihr nicht zu mir zurtick.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '\"Ich sandte eine Pest zu euch nach Art und Weise der ägyptischen, schlug mit dem Schwerte eure Jünglinge samt euren besten Pferden. Gestank ließ ich von eurem Lager aus euch in die Nase dringen, und dennoch kamt ihr nicht zu mir zurück.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '\"Und einen Umsturz bracht\' ich über euch, wie Gott einst Sodom und Gomorrha umgestürzt; ihr gleichet einem Scheit, der Glut entrissen, und dennoch kamt ihr nicht zu nur zurück.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, '\"Drum Israel, will ich mit dir nun so verfahren, und weil ich so mit dir verfahren will, so halte, Israel, dich auch bereit für die Begegnung deines Gottes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Ja, sieh! Er ist der Berge Bildner und des Windes Schöpfer. Er kann dem Menschen kundtun, was er selber im geheimen denkt. Er macht zum Morgenrot die Finsternis und wandelt auf der Erde Höhen. \"Herr, Gott der Heerscharen\", das ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Hört dieses Wort, das ich anhebe über euch, ein Trauerlied um das Haus Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Es fällt die Jungfrau Israel, steht nicht mehr auf. Sie liegt auf ihrem eignen Boden hingestreckt, und keiner hilft ihr auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn also spricht der Herr, der Herr: \"Die Stadt, die einst mit tausend ist ins Feld gezogen, behält nur hundert übrig, die hundert einst gestellt, wird zehn nur übrighaben im Hause Israel.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'So spricht der Herr vom Hause Israel: \"Kommt, sucht mich auf, daß ihr am Leben bleibet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Besucht nicht Betel! Wallfahrt nicht nach Gilgal! Denn Gilgal schwindet; in nichts sinkt Betel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Den Herrn sucht auf, daß ihr am Leben bleibt! Sonst kommt in Josephs Haus das Feuer und zehrt es auf, und niemand könnte Betels Flammen löschen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Weh denen, die das Recht in Wermut wandeln und die Gerechtigkeit zu Boden werfen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Er ist\'s, der die Plejaden schuf und den Orion, und wie er Finsternis in Morgenlicht verwandelt, dunkelt er den Tag in Nacht. Er ruft des Meeres Wasser her und gießt sie auf die Erde. Sein Name ist \"Der Herr\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Vernichtung bringt er starken Plätzen; als Verwüstung kommt er für die Festungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sie hassen den, der vor Gericht Beweise bringt, verabscheun Fürsprecher der Schuldlosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, '\"Darum, weil ihr auf den Geringen mit Verachtung schaut, doch Kornabgaben von ihm nehmt, drum sollt ihr, mögt ihr auch aus Quadern Häuser bauen, sie dennoch nie bewohnen und, mögt ihr auch die herrlichsten Weingärten pflanzen, dennoch ihren Wein nicht trinken. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Ja, eure vielen Frevel sind mit wohlbekannt und eurer Missetaten Menge; Schuldlose drücket ihr und nehmt Bestechung an und raubt den Armen vor Gericht ihr Recht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Deswegen schweigt die Weissagung in jener Zeit; denn eine schlimme Zeit ist es. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Dem Guten strebet nach und nicht dem Bösen, daß ihr am Leben bleibt, damit alsdann der Herr, der Heeresscharen Gott, mit euch so sei, wie ihr\'s euch wünschet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Das Böse hasset, liebt das Gute! Verschafft dem Rechte bei Gerichte Geltung! Vielleicht ist dann der Herr der Gott der Heerscharen, dem Reste Josephs gnädig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Darum spricht so der Herr der Gott der Heerscharen, der Herr: \"Auf allen Plätzen Weheklage! In allen Gassen schreit man Wehe, Wehe!\' Zur Trauer ruft man Sänger auf, zur Weheklage, die der Totenlieder kundig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Auf allen Lagern Traurigkeit, wenn ich durch deine Mitte ziehe\", spricht der Herr. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Weh denen, die den Tag des Herrn sich wünschen! Wozu soll auch der Tag des Herrn nur dienen? Er ist ja Finsternis, nicht Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Wie einer sich vor einem Löwen retten will und stößt auf einen Bären, tritt er ins Haus und stützt sich an die Wand mit seiner Hand, da sticht ihn eine Schlange,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'ist nicht geradeso der Tag des Herrn von Unheil schwarz, von keinem Strahl erhellt, nur Dunkel, ohne Morgenstrahl? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, '\"Ich hasse und verwerfe eure Feste und achte nicht auf eure Feiertage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Wenn ihr mir Brand- und Speiseopfer bringt, so hab\' ich kein Gefallen daran. Nach euren fetten Bundesopfern mag ich gar nicht blicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Hinweg von mir mit dem Gelärme deiner Lieder! Dein Harfenspiel mag ich nicht hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Zur Spende werde Recht wie Wasser ausgegossen, Gerechtigkeit wie Ströme Weins!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr mir Schlacht- und Speiseopfer dargebracht, Haus Israel, einst in der Wüste vierzig Jahre,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'und habt ihr eures Königs Zelt umhergetragen und eures Gottes Sternbildsäule, die ihr euch angefertigt habt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Darum verschleppe ich euch weiter weg als nach Damaskus.\" So spricht der Herr; sein Name ist: \"Der Gott der Heerscharen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Weh denen, die sich dort auf Sion sicher fühlen und die sich auf Samarias Berg verlassen, die da der Heidenvölker Bestes zur Aus- und Einfuhr nehmen für das Haus von Israel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, '\"Nach Kalne geht und schaut euch um! Und zieht von dort her nach dem großen Hamat! Nach Gat in dem Philisterlande geht, ob ihr wohl tapfrer seid als diese Königreiche, ob ihr Gebiet nicht größer als das eure ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Die ihr den Unglückstag fern wissen möchtet und doch den Sabbat der Gewalt herbeiführt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Gelagert auf den elfenbeingeschmückten Ruhebetten und hingestreckt auf ihre Ruhelager, verzehren sie der Herde Lämmer, die jungen Rinder aus dem Stall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Sie gröhlen zu der Zither Klang und musizieren wie verrückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Sie trinken von dem feinsten Wein und salben sich mit bestem Öl. Jedoch um Josephs Schaden kümmern sie sich nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Sie ziehen deshalb an der Spitze der Gefangnen fort; zu Ende ist der Schwelger Freudenmahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Geschworen hat der Herr, der Herr, bei sich - ein Spruch des Herrn, des Gottes der Heerscharen -: \"Ein Abscheu ist mir Jakobs Prunk; zuwider sind mir seine Schlösser. Ich geb die Stadt samt allem, was darinnen, preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Und blieben noch in einem einzigen Haus zehn Männer übrig, auch diese sollen sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Wenn dann der Lieblingssohn und Erbe einen forttragen läßt, um die Gebeine aus dem Haus zu schaffen, und fragt er die, die sich im Hintergrund des Hauses hält: \"Ist jemand noch bei dir?\" dann sagt sie: \"Nein!\" und sagt dann noch: \"Kein Wort mehr weiter!\", weil man des Herren Namen nicht mehr nennen darf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Denn so, fürwahr, bestimmt\'s der Herr: Das große Haus schlägt er in Trümmer; das kleine ganz in Stücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, '\"Ja, laufen Rosse über Felsen? Kann man mit Stieren Felsen pflügen, daß ihr das Recht in Gift verwandelt, die Früchte der Gerechtigkeit in Wermut?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Ihr, die ihr über Lodabar euch freut, ihr, die ihr sagt: \'Ja, haben wir dem nicht durch unsre Kraft Karnajim uns erobert?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Fürwahr, ich lasse wider euch, du Haus von Israel\", ein Spruch des Herrn, des Gottes der Heerscharen, \"ein Volk erstehn, das euch bedrängt vom Weg nach Hamat bis zum Weidenbach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'So ließ der Herr, der Herr, mich\'s schauen: Er führte junge Heuschrecken herbei zu Anbeginn, da Spätgras wuchs, das Gras, das späte, nach des Königs Mahd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Und als sie alles Kraut im Lande fressen wollten, sprach ich: \"Herr, o Herr, vergib! Wer hilft nur Jakob auf? Gar schwach ist es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Der Herr erbarmte sich. \"Es soll nicht sein!\" so sprach der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Da ließ der Herr, der Herr, mich schauen: Der Herr, der Herr, rief einen Feuerwind herbei; er fraß das große Meer und wollte auch die Flur verzehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Da sprach ich: \"Herr, ach Herr, hör auf! Wer hilft nur Jakob auf? Gar schwach ist es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Der Herr erbarmte sich. \"Auch dies soll nimmer sein\", so sprach der Herr, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Dann ließ er dies mich schauen: Da stand der Herr auf einem Haufen Hartgestein und hatte einen harten Stein in seiner Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Da sprach der Herr zu mir: \"Was siehst du, Amos?\" Ich sagte: \"Einen harten Stein.\" Da sprach der Herr: \"Ich lege einen harten Stein ins Innere meines Volkes Israel und will ihm weiter nicht verzeihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Verwüstet sollen nunmehr werden Isaaks Höhen, die Heiligtümer Israels zerfallen, und wider des Jeroboam Haus erheb ich mich mit meinem Schwert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Da ließ Amasias, der Priester Betels, Jeroboam, dem Könige von Israel, vermelden: \"Verschwörung stiftet Amos gegen dich im Hause Israels; das Land kann seine Reden nicht mehr fassen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'denn so spricht Amos: \'Jeroboam stirbt durch das Schwert, und Israel wird weggeführt aus seiner Heimat.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Zu Amos aber sprach Amasias: \"Auf, Seher, fort! Nach Juda flieh! Dein Brot verdiene dort! Weissage dort!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Zu Betel darfst du doch nicht länger weissagen; denn es ist königliches Heiligtum und Reichstempel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Darauf gab Amos Antwort und sprach zu Amasias: \"Ich bin doch kein Prophet und kein Prophetensohn. Ein Hirte bin ich nur und Maulbeerfeigenzüchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Mich hat der Herr gerade von der Herde weggeholt, und also sprach der Herr zu mir: \'Auf! Prophezeie gegen mein Volk Israel!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Und nun vernimm das Wort des Herrn! Du hast gesagt: \'Du darfst nicht gegen Israel weissagen, nicht gegen Isaaks Haus so predigen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Deshalb spricht so der Herr: \'Dein Weib wird öffentlich entehrt, und deine Söhne mit den Töchtern fallen durch das Schwert. Dein Boden wird durchs Los verteilt. Du selber stirbst auf ungeweihtem Boden, und Israel wird fortgeführt aus seiner Heimat.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Dies ließ der Herr, der Herr, mich schauen: Es war ein Korb mit Erntefrüchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Er sprach: \"Was siehst du, Amos?\" Ich sagte: \"Einen Korb mit Erntefrüchten.\" Da sprach der Herr zu mir: \"Das Abernten kommt über mein Volk Israel; ich will ihm nicht verzeihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Die Glieder werden fürchterlich anschwellen\", ein Spruch des Herrn, des Herrn, \"an allen Orten wirft man schweigend Leichenhaufen hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Vernehmet dies, die ihr den Armen niedertretet, die Niedrigen im Lande unterdrückt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'und sprecht: \"Wann ist der Neumond um, damit wir Korn verkaufen, der Sabbat, daß wir Korn verhandeln können? Den Scheffel muß man kleiner machen, größer seinen Preis und das Gewicht verfälschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'um Arme für das Geld zu kaufen und Dürftige um ein Paar Schuhe. - Taubes Korn verhandeln wir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Der Herr schwört wider Jakobs Adel: \"In Ewigkeit vergesse ich nicht ihre Taten.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Soll nicht darob das Land erbeben? Nicht alle trauern, die darinnen wohnen? Wär\'s gleich dem Euphrat angewachsen, hochgestiegen, so sinkt es dennoch wie Ägyptens Nil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '\"An jenem Tage wird\'s gescheh\'n\", ein Spruch des Herrn, des Herrn, \"da lasse ich die Sonne untergehn am Mittag und wandle für die Erde schon am Tag das Licht in Dunkel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'In Trauer ändere ich eure Feste, in Totenklage alle eure Lieder und gürte allen Hüften Bußgewänder um und mache kahlgeschoren jedes Haupt und mach es so wie bei der Trauer um den Einzigen. Und alles endet wie ein bitterer Tag.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, '\"Es kommen Tage\", Spruch des Herrn, des Herrn, \"da sende ich ins Land den Hunger, doch Hunger nicht nach Brot, nicht Durst nach Wasser, vielmehr danach, das Wort des Herrn zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Sie wanken dann von Meer zu Meer, von Mitternacht bis Sonnenaufgang hin. So irren sie umher, ein Herrenwort zu suchen, doch sie finden keines. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'An jenem Tage sinken hin die jungen Mädchen, die Jünglinge, vor Durst verschmachtend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'die schwören bei Samarias Sünde, und die sprechen: \'So wahr dein Gott lebt, Dan! So wahr dein Stammgott lebt, Beetseba!\' Sie sinken hin und stehen nicht mehr auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ich sah den Herrn an dem Altare stehn; Er sprach: \"Wenn an den Säulenknauf du schlägst, dann beben auch die Schwellen. Das Haupt vernicht ich ihnen allen, dann schlag ich ihr Gefolge mit dem Schwerte nieder. Nicht einer soll entrinnen, von ihnen nicht ein einziger sich retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Selbst wenn sie in die Unterwelt eindrängen, holte meine Hand sie dort, und stiegen sie zum Himmel auf, dann holte ich sie auch von dort herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Versteckten sie sich auf des Karmels Gipfel, dort spähte ich sie aus und holte sie hinweg, und wollten sie vor meinen Augen auf dem Meeresgrunde sich verbergen, so böte ich die Schlangen, sie zu beißen, auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Und wanderten gefangen sie vor ihren Feinden her, auch dort geböt\' ich einem Schwerte, sie zu töten. Ich richte meinen Blick auf sie zum Unheil, nicht zum Guten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Der Herr, der Herr der Heerscharen, der an die Erde rührt, daß sie erbebt, daß alle, die drauf wohnen, trauern und wäre sie dem Euphrat gleich gewachsen, sie wird dem Nil Ägyptens gleich sich wieder senken;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'der da im Himmel seinen Söller baut und sein Gewölbe auf der Erde gründet, der dem Meerwasser zuruft und auf die Erde es hingießt; sein Name ist: \"Der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, '\"Seid ihr mir nicht geradeso wie die Kuschiten, Söhne Israels?\" Ein Spruch des Herrn. \"Hab ich nicht aus Ägypterlande Israel geführt? Aus Kreta aber die Philister und aus Kir die Aramäer!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Fürwahr, des Herrn, des Herren Augen schauen auf das frevelhafte Reich. \"Doch tilge ich durchaus nicht also Jakobs Haus, daß ich es von der Erde tilgte.\" - Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '\"Fürwahr! Ich gebe Weisung, dann laß ich das Haus Israel bei all den Heiden schütteln, wie man in einer Schütteltrommel schüttelt, daß auf die Erde nicht ein einzig Klümpchen fällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Dann sterben alle Sünder meines Volkes durch das Schwert, die sprechen: \'So bald kommt nicht das Unglück über uns.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Dann aber richte ich an jenem Tag die Hütte Davids, die verfallene, auf, vermaure ihre Risse, stelle ihre Trümmer wieder her und baue neu sie auf wie in der Vorzeit fernen Tagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Dann nehmen sie den Rest von Edom, wie den von allen andern Völkern die einstens unter seiner Herrschaft standen.\" Ein Spruch des Herrn, der dies vollführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, '\"Fürwahr, dann kommen Tage\", Spruch des Herrn, \"da wird der Pflüger gar den Schnitter und der Traubenkelterer den Sämann treiben, von Wein die Berge triefen und alle Hügel von ihm fließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Da wende ich das Schicksal meines Volkes Israel. Sie bauen die zerstörten Städte auf und wohnen drin. Weinberge pflanzen sie und trinken deren Wein. Sie legen Gärten an und essen deren Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Ich pflanze sie in ihre Heimat ein, daß sie nicht abermals aus ihrem Boden, den ich gab, herausgerissen werden können.\" So spricht der Herr, dein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Das Gesicht des Abdias: Sprach über Edom so der Herr, der Herr. - Vom Herrn ward eine Offenbarung uns zuteil, und zu den Heidenvölkern ward ein Bote hingesandt: \"Wohlauf, wir ziehen jetzt gen Edom!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, '\"Ich mache bei den Heiden dich so klein; du wirst gar sehr verächtlich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Betört hat dich jetzt deines Herzens Stolz, dich, das in Felsenhängen wohnt und Höhen hat zum Sitz, und das im Herzen spricht: \'Wer könnte mich zu Boden stürzen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Doch throntest du so hoch wie Adler und hättest zwischen Sternen eingebaut dein Nest, ich stürzte dennoch dich von dort hinab.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Ja, wären Diebe über dich gekommen oder Räuber bei der Nacht, wie wärest du verwüstet worden? Nicht wahr, sie hätten nur soviel gestohlen, wie sie grade hätten tragen können? Und wären Winzer über dich gekommen, hätten sie nicht eine Nachlese zurückgelassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Doch wie durchwühlt steht nunmehr Esau da, und wie durchsucht sind seine gutversteckten Schätze?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Zurück bis zu der Grenze treiben dich all deine Bundesfreunde, und dich betrugen deine guten Freunde; sie überlisten dich, und die dein Brot verzehren, legen Fallen deinen Füßen. - Doch Edom selber merkt dies nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, '\"Wird\'s nicht an jenem Tage sein\", ein Spruch des Herrn, \"als hätte ich aus Edom weise Männer, aus dem Gebirge Esaus Einsicht weggenommen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Dann zittern deine Krieger, Teman, weil vom Gebirge Esaus jeder Mann vernichtet wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Für grausames Erwürgen deines Bruders Jakob deckt dich Schande und trifft dich immerwährende Vernichtung. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Am Tag, da du dabeigestanden, am Tag, da Fremdlinge sein Heer wegführten, in seine Tore Fremde drangen und um Jerusalem die Lose warfen, da warst auch du wie irgendwer von ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, '\"Du hättest dich nicht freuen sollen an deines Bruders Unglück, an seinem Unglückstage. Du hättest nicht frohlocken sollen über Judas Söhne am Tage ihres Untergangs, nicht harte Worte sprechen sollen am Tage der Bedrängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Du hättest nicht in meines Volkes Tore dringen sollen an seinem Unglückstage. Du hättest nicht die Hand an seine Habe legen sollen an seinem Unglückstage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Du hättest dich an seinen Breschen nicht aufstellen sollen, um seine Flüchtlinge zu würgen, und hättest nimmer die Entronnenen am Tag der Not abfangen sollen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Der Tag des Herrn kommt ja für alle Heidenvölker. - \"Wie du getan, wird dir geschehn; dein Tun fällt auf dein Haupt zurück.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, '\"Ja, so wie ihr den Kelch auf meinem heiligen Berge trinken müßt, so müssen alle Heiden auch der Reihe nach ihn trinken. Sie trinken und beschmutzen sich und sind, als ob sie nie gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Auf Sions Berg jedoch wird Rettung sein, ein heiliger Sitz, und Jakobs Haus nimmt ihre Güter in Besitz. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Denn Jakobs Haus ist dann ein Feuer, eine Flamme Josephs Haus und Esaus Haus ein Strohbündel, das jene anzünden und aufzehren. Von Esaus Haus entrinnt nicht einer. Der Herr hat\'s ja gesagt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, '\"Sie nehmen in Besitz den Süden samt dem Esauberg, die Ebene mit Philistäa und das Gefilde Ephraims und das Gefilde von Samaria und Benjamin samt Gilead.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Und jene so verlassene Gefangenschaft der Söhne Israels besetzt der Kanaaniter Land bis nach Sarepta hin, und die Gefangnen aus Jerusalem, die in Sepharad sind, sie nehmen in Besitz des Südens Städte.\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Als Sieger ziehen sie den Sionsberg hinan, um über die vom Esauberg Gericht zu halten. Dann tritt der Herr die Königsherrschaft wieder an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Das Wort des Herrn erging an Jonas, den Sohn des Amittaj:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '\"Auf! Zieh nach Ninive, der großen Stadt, und predige, daß ihre Bosheit bis vor mich gedrungen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Doch Jonas machte sich daran, zu fliehen vor dem Herrn nach Tarsis. Er stieg deshalb hinab nach Joppe und traf ein Schiff, das fuhr nach Tarsis. Als er den Preis dafür entrichtet, stieg er ein, um vor dem Herrn mit ihnen nach Tarsis zu gelangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Der Herr jedoch warf einen starken Wind aufs Meer, ein großer Sturm ward auf dem Meer, so daß das Schiff zu scheitern drohte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Die Schiffer wurden voller Angst; ein jeder schrie zu seinem Gott. Sie warfen das Gepäck ins Meer aus ihrem Schiff, es dadurch zu erleichtern. Doch Jonas war ins Unterteil des Schiffs hinabgestiegen und hatte dort sich hingelegt und war fest eingeschlafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Da trat der Schiffshauptmann zu ihm und sprach zu ihm: \"Was fällt dir ein, zu schlafen? Erheb dich! Fleh zu deinem Gott! Vielleicht nimmt dieser Gott sich unser an, daß wir nicht untergehn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Sie sprachen alsdann zueinander: \"Auf! Laßt uns auch die Lose werfen, damit wir es erfahren, durch wessen Schuld uns dieses Unheil trifft!\" Da warfen sie die Lose. Das Los traf Jonas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Da sprachen sie zu ihm: \"Sag uns, weshalb uns dieses Unheil trifft! Was hast du für Geschäfte? Wo kommst du her? Was ist dein Vaterland? Von welchem Volke stammst du denn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Er sprach zu ihnen: \"Ich bin Hebräer und verehre Gott, den Herrn des Himmels, der das Meer geschaffen und das feste Land.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Da überfiel die Leute große Angst; sie fragten ihn: \"Was hast du denn getan?\" Die Leute wußten nämlich schon, daß er in Furcht war vor dem Herrn, wie er es ihnen angedeutet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Da sprachen sie zu ihm: \"Was sollen wir jetzt mit dir tun, damit von uns das Meer ablasse?\" Denn immer ärger tobte jetzt die See.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Er sprach zu ihnen: \"Nehmt und werft mich in das Meer! Dann läßt das Meer von euch. Ich weiß ja, daß nur meinetwegen dieser große Sturm euch überfiel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Da mühten sich die Leute ab, ans feste Land zurückzukommen. Doch sie vermochten\'s nicht; denn immer stärker tobte gegen sie die See.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Da riefen sie zum Herrn und sprachen: \"Herr, laß uns nicht zugrunde gehen um des Lebens dieses Mannes willen! Bring über uns nicht schuldlos Blut! Herr, tu, was Dir gefällt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Da nahmen sie den Jonas und warfen ihn ins Meer. Nun legte sich des Meeres Ungestüm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'So fürchteten sich diese Leute mächtig vor dem Herrn und brachten ihm Schlachtopfer dar und machten ihm Gelübde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Der Herr ersah sich einen großen Fisch, den Jonas zu verschlingen. Und Jonas blieb drei Tage und drei Nächte im Leib des Fisches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Und Jonas betete zu seinem Gott und Herrn, nachdem er wieder außerhalb des Fischleibs war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Er sprach: \"Ich hab zum Herrn in meiner Not gerufen; da hat er mich erhört. Ich schrie um Hilfe aus dem Schoß der Unterwelt, und Du vernahmst mein Rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Du warfst mich in die Tiefe, in des Meeres Mitte. Und mich umgab die Strömung. All Deine Wogen, Deine Wellen gingen über mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Da hatte ich gesprochen: Verstoßen bin ich jetzt aus Deinen Augen. Ach, könnte ich doch wieder Deinen heiligen Tempel schauen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Die Wasser gingen mir bis an die Kehle. Der Abgrund hielt mich fest umfangen, und Meergras schlang sich um mein Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Bis zu der Berge Gründen war ich schon hinabgefahren; der Erde Riegel wollten ewig mich verschließen. Da hast Du, Herr, mein Gott, mein Leben vor dem Untergang gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Als meine Lebenskraft in mir zu Ende ging, da habe ich des Herrn gedacht. Mein Flehen kam zu Dir in Deinen heiligen Tempel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Die nichtigen Götzen dienen, verlassen ihre treue Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ich aber muß mit lautem Dank Dir opfern. Was ich gelobt, muß ich erfüllen; erschienen ist des Herren Hilfe.\" Dem Fische hatte ja der Herr geboten, aufs trockne Land den Jonas auszuspeien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Und nun erging das Wort des Herrn zum zweitenmal an Jonas:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '\"Auf! Geh nach Ninive, der großen Stadt, und halte ihr die Predigt, die ich dir aufgetragen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'So brach denn Jonas auf und ging nach Ninive gemäß dem Wort des Herrn, und Ninive war eine große Stadt, drei Tagereisen zum Beschauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Da fing nun Jonas an, in diese Stadt hineinzugehen, eine Tagesreise weit, und predigend zu rufen: \"Noch vierzig Tage, dann wird Ninive zerstört\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Da glaubten die Bewohner Ninives an Gott und riefen Fasten aus und zogen Bußgewänder an, vom Größten bis zum Kleinsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Die Kunde kam auch zu dem Könige von Ninive; der stieg von seinem Thron herab und legte seinen Mantel fort, bedeckte sich mit einem Bußgewand und setzte sich in Asche');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'und ließ in seinem und im Namen seiner Großen den Herold ausrufen zu Ninive: \"Die Menschen wie das Vieh, die Rinder und die Schafe sollen keinen Bissen kosten, nicht auf die Weide gehen und kein Wasser trinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'In Trauer gehen sollen Mensch und Vieh, und jene sollen Gott mit Macht anrufen! Ein jeder lasse jetzt von seinem schlimmen Wandel ab und von dem Frevel, der an seinen Händen klebt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Vielleicht läßt sich\'s die Gottheit wiederum gereuen und wendet sich von ihrer Zornesglut, daß wir nicht untergehn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Da sah die Gottheit, was sie taten, daß sie ihren schlimmen Wandel aufgegeben. So ließ die Gottheit sich des Unheils wiederum gereuen, das ihnen zuzufügen sie gedroht, und führte es nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Doch dies verdroß den Jonas schwer; er war entrüstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Er betete zum Herrn und sprach: \"Ach, Herr, war das nicht mein Gedanke, als ich noch in meiner Heimat war? Deshalb floh ich zuvor nach Tarsis. Ich wußte wohl, daß Du ein Gott bist, gnädig und barmherzig, zum Zorne langsam, reich an Huld, der sich gereuen läßt des Unheils.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Nun, Herr, nimm mir das Leben! Besser ist\'s für mich, zu sterben als zu leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Da sprach der Herr: \"Bist du mit Recht erzürnt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Darauf ging Jonas aus der Stadt und ließ sich nieder, östlich von der Stadt. Er baute sich dort eine Hütte und wollte sich darunter in den Schatten setzen, bis daß er sähe, was mit der Stadt geschehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Da ließ der Herr Gott einen Wunderbaum erstehen und ihn hoch über Jonas aufwachsen, um durch den Schatten, den er seinem Haupte spendete, ihn seiner üblen Laune zu entreißen. Und Jonas hatte große Freude an dem Wunderbaum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Die Gottheit aber ließ den Tag darauf zur Zeit der Morgendämmrung einen Wurm entstehen. Er stach den Wunderbaum, daß er verdorrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Und als die Sonne aufgegangen war, bestellte Gott auch einen schwülen Ostwind. Da stach die Sonne Jonas auf das Haupt. So ward er ganz erschöpft und wünschte sich den Tod und sprach: \"Zu sterben ist mir besser als zu leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Da sprach zu Jonas Gott: \"Zürnst du des Wunderbaumes wegen?\" Er sprach: \"Mit Recht bin ich bis in den Tod erzürnt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Da sprach der Herr: \"Dir ist es schade um den Wunderbaum, um den du dich nicht abgemüht, den du nicht großgezogen hast, der da in einer Nacht entstand und in der anderen Nacht verging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Mir aber sollte es um Ninive nicht leid sein, diese große Stadt, in der mehr als einhundertzwanzigtausend Menschen sind, die nicht die Linke von der Rechten unterscheiden, und eine Menge Vieh?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Das Wort des Herrn, das in der Zeit der Judakönige Jotam, Achaz und Ezechias, an Michäas aus Maresa erging, der über Samaria und Jerusalem Gesichte hatte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, '\"Ihr Mitbürger des Volkes alle, hört! Du Land, horch auf, und was darin! Der Herr, der Herr, tritt gegen euch als Kläger auf, der Herr aus seinem heiligen Palast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Denn seht! Von seinem Sitze kommt der Herr. Er steigt herab und schreitet auf des Landes Höhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Die Berge schmelzen unter ihm; die Täler spalten sich wie Wachs am Feuer, wie Wasser, das vom Abhang stürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Dies alles wegen Jakobs Missetat und der Versündigung des Hauses Israel. Was ist doch Jakobs Missetat? Ist\'s nicht Samaria? Was ist denn Judas schlechte Wahl? Ist\'s nicht Jerusalem?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, '\"Deswegen mache ich Samaria zu einem Feldsteinhaufen an den Weinbergspflanzungen und rolle seine Steine in das Tal, entblöße seinen Grund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Zerschlagen werden alle seine Götzenbilder, verbrannt im Feuer alle seine Weihegaben. Zerstören will ich alle seine Götterbilder; denn was es sammelte an Buhlerlohn, das soll zum Buhlerlohn ihm wieder werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, '\"Darüber weine ich und klage ich und gehe nackt und bloß einher; ich stimme an ein Schakalheulen; ich stimme an ein Straußenklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Ja, tödlich sind die ihm geschlagnen Wunden; denn bis nach Juda wirken sie noch fort. Sie wirken fort bis an die Pforte meines Volks, bis nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Vermeldet\'s nicht in Gat; vergießet keine Tränen! Einwohnerschaft von Ophra, wälze dich im Staube!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Zieht fort, Bewohner von Saphir, geht nackt und bloß! Die Schwelle überschreitet, Bewohner von Saanan! Betrübnis um das schwanke Haus erfüllt die ihm Entrissenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Denn krank vor Kummer sind die Einwohner, der Habe wegen, denn von dem Herrn dringt Unheil an das Tor Jerusalems.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Spannt an den Wagen nun das Roß, Bewohner von Lachis! Zur Missetat der Sionstochter gaben sie den ersten Anlaß. Die Sünden Israels sind bei dir eingeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Deswegen gibst du Gats Besitztum frei. Doch die Geschenke zeige ich nun auf als Täuschungen der Könige von Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Ich führ euch bis zum Bach, Bewohner Maresas. Bis nach Adullam kommt der Reichtum Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Scher dir das Haar! Rauf\'s aus, um deiner Lieblingskinder willen! Und mach dir eine Glatze so breit wie die des Geiers! Sie schwinden vor dir weg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Weh denen, die auf Unheil sinnen, auf ihren Lagern Böses planen! Beim ersten Morgenlicht vollbringen sie\'s; sie haben ja die Macht dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Nach Feldern tragen sie Gelüste und rauben sie, oder nach Häusern, und nehmen sie hinweg. Sie vergewaltigen den Herrn samt seinem Haus, den Mann mit seinem Eigentum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'So spricht deshalb der Herr: \"Ich plane Unheil gegen dies Geschlecht. Dem könnt ihr euren Nacken nicht entziehn; darin könnt ihr nicht aufrecht gehn. Denn eine schlimme Zeit wird\'s sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'An jenem Tag stimmt man auf euch ein Spottlied an; man singt ein Klagelied, das heißt: \"Wir sind vollständig ausgeraubt. Vertauscht hat er den Anteil meines Volkes. Wie nimmt er\'s mir hinweg? Dem Feinde teilt er unsere Felder zu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Gewiß! Euch spannt die Meßschnur niemand mehr noch weiter in des Herrn Gemeinde aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '\"Weissaget nicht!\" So geifern sie: \"Sie sollen nicht zum Unheil prophezeien! Sonst bleibt nicht die Beschämung aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Was wird da ausgesagt in Jakobs Haus? \"Ist denn der Geist des Herrn ohnmächtig? Sind seine Werke solcher Art? Gefallen meine Worte nicht mehr: \'Ich wandle mit den Redlichen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Doch schon seit langer Zeit hat sich mein Volk feindselig aufgelehnt. Ihr zieht das Unterkleid mitsamt dem Mantel unbesorgten Wandrern aus, den Krieg erneuernd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Ihr treibt die Weiber meines Volkes aus ihrem Haus, darinnen sie sich wohlgefühlt, und ihren Kindern nehmt ihr weg die Mütter, die sie in ihren Wiegen eingeschläfert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Auf! Fort! Dies ist jetzt keine Ruhstatt mehr. Sie ist entweiht, verschuldet durch ein schreckliches Verschulden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Wenn einer löge, der mit Lug und Trug umgeht: \'Ich fordre für dich Wein und Met\', dann würde dieses Voll, beistimmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Dann bringe ich dich, Jakob, insgesamt zusammen, wenn ich den Rest von Israel herhole, und wie die Schafe in die Hürde bringe ich sie ein. Wie eine Herde in dem Stall, so machen sie der Menschenmenge wegen Lärm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Vor ihnen zieht der Führer her. Sie ziehen aus und schreiten durch das Tor und ziehn hindurch. Ihr König zieht vor ihnen her, der Herr an ihrer Spitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Ich sprach: \"Ihr Jakobshäupter, hört, ihr Richter hier im Hause Israel! Ist das nicht eure Pflicht, das Recht zu kennen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Ihr seid diejenigen, die das Gute hassen und das Böse lieben und anderen die Haut abziehen, das Fleisch von ihren Knochen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Ihr seid es, die ihr meines Volkes Fleisch verzehrt und ihm die Haut vom Leibe zieht und seine Knochen so zerhackt und sie zerlegt, wie für den Topf, wie Fleisch im Kessel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Dann schreien sie zum Herrn; er wird sie nicht erhören. Er birgt zu jener Zeit sein Angesicht vor ihnen, weil sie schlimme Taten ausgeübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'So spricht der Herr jetzt über die Propheten, die mein Volk verführen, von seligen Zeiten sprechend, solange sie mit ihren Zähnen noch zu kauen haben, doch dem, der ihnen in den Mund nichts gibt, den Krieg erklären:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, '\"Wahrhaftig, für das Schauen wird euch Nacht und Finsternis, daß ihr nicht prophezeien könnt.\" Da geht die Sonne den Propheten unter; der Tag wird finster für sie werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Voll Scham die Seher und voll Schande die Wahrsager; sie verhüllen allesamt den Bart; denn keine Gottesantwort gibt es mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ich aber bin erfüllt mit Ausdauer wohl durch den Geist des Herrn, mit Rechtsgefühl und Mut und halte Jakob seinen Frevel vor und seine Sünde Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, '\"Ihr Häupter in dem Jakobshause, höret dies, ihr Richter im Hause Israel, ihr, denen Recht ein Greuel ist, die alles Richtige verkehren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Ihr baut mit Blutschuld Sion auf, Jerusalem mit Frevel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ach, seine Häupter, die Recht sprechen um Geschenke! Ach, seine Priester, die gar für Bezahlung lehren! Ach, seine Seher, die um Geld weissagen, sich auf den Herrn verlassen mit den Worten: \"Ist nicht der Herr in unserer Mitte? Uns kann kein Unheil treffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Deswegen sei um euretwillen gleich einem Felde Sion umgepflügt, ein Trümmerhaufen werd Jerusalem, der Tempelberg zur waldbewachsenen Höhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'In ferner Zukunft Zeit steht aber an der Berge Spitze der Berg des Hauses, das dem Herrn gehört, und übertrifft die anderen Hügel. Die Völker strömen freudig zu ihm hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Und große Heidenvölker kommen, also sprechend: \"Auf! Laßt uns wallen zu dem Berg des Herrn, zum Haus des Gottes Jakobs! Er möge über seine Wege uns belehren! Wir wollen jetzt auf seinen Pfaden wandeln! Von Sion geht die Lehre aus und von Jerusalem das Wort des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Er schlichtet großer Völker Fehden, läßt starke Heidenvölker in der Ferne sich vergleichen. Zu Pflügen schmieden sie die Schwerter um, zu Winzermessern ihre Lanzen. Kein Heidenvolk mehr zückt gegen das andere das Schwert; das Kriegshandwerk hat keine Schüler mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Dann sitzt ein jeder unter seinem Rebstock und Feigenbaum, von niemandem mehr aufgeschreckt. So sagt\'s der Mund des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Mag von den anderen Völkern jedes seinen Gott verehren, wir aber, wir verehren ewig unsern Gott, den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '\"An jenem Tage sammle ich Ermattetes\", ein Spruch des Herrn, \"und bringe das Versprengte wiederum zusammen, das von mir Gestrafte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Zum Überschuß mach ich das Kränkliche, das Schwache zu zahlreicher Nation.\" Der Herr ist auf dem Sionsberge König über sie von nun an bis in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Du, Herdenturm, Hügel der Sionstochter! Zu dir kommt wiederum, zu dir kehrt abermals die alte Herrschaft, der Sitz des Reichs zur Tochter von Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Doch jetzt, worüber führst du laute Klage? Ist nicht ein König noch bei dir? Ist dein Berater umgekommen, daß Wehen dich wie eine Kreißende befallen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Ja, zittre, stöhne, Sionstochter, wie eine Kreißende! Du mußt jetzt aus der Stadt hinaus, auf freiem Felde lagern, bis du nach Babel hingelangst. Dort aber findest du Errettung; dort rettet dich der Herr aus deiner Feinde Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Jetzt aber stehen große Heidenvölker gegen dich zusammen, also sprechend: \"Besudelt soll es werden, auf daß an Sion unser Auge sich erlabe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Sie aber kennen nicht des Herrn Gedanken; mit seinem Plane sind sie unbekannt, daß er sie selbst wie Garben auf die Tenne bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Dann auf und drisch, du Sionstochter! Ich gebe Hörner dir von Eisen und schaffe Klauen dir von Erz. Zermalmen sollst du große Völker und dem Herren ihre Schätze weihen, ihr Gut dem Herrn der ganzen Erde! Jetzt aber wirst du, Tochter der Absonderung, ganz abgesondert werden. Man schließt uns ein mit einem Wall; man schlägt mit einem Stocke die Richter Israels auf ihre Wange.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, '\"Du aber, Bethlehem, einst Ephrata genannt! Du bist ja zu gering, um unter Judas Gauen mitzuzählen. Aus dir entsprießt mir aber Einer, um Herrscher über Israel zu werden. Sein Ursprung stammt aus grauer Zeit, aus alten Tagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Nur deshalb gibt man sie so lange hin, bis eine, die gebären soll, gebiert. Und seiner Brüder Rest kehrt zu den Söhnen Israels zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Dann tritt er auf und weidet in der Kraft des Herrn, im hoheitsvollen Namen seines Herrn und Gottes. Sie wohnen sicher; groß steht er bis an der Erde Enden da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Er selbst ist Friede. Wenn aber der Assyrer unser Land betritt, wenn er in unsere Berge dringen will, dann stellt er ihm entgegen sieben Hirten, acht Völkerführer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Sie weiden Assurs Landschaft mit dem Schwert und Nimrodland mit offener Klinge. Und so befreit er vom Assyrer uns, wenn dieser unser Land betritt und seinen Fuß in unsere Grenzen setzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Und Jakobs Rest gleicht mitten unter großen Völkern dann dem Tau, der von dem Herren kommt, den Regentropfen auf dem Gras, die nicht auf Menschen warten müssen und nicht auf Menschenkinder harren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Und Jakobs Rest gleicht bei den Heiden inmitten großer Völker einem Löwen bei des Waldes Tieren, dem jungen Leu bei einer Herde Schafe, der, wenn er sie durchläuft, sie niederwirft und rettungslos zerreißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Mög Deine Hand obsiegen über alle Deine Widersacher; zugrundegehen sollen alle Deine Feinde! -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '\"An jenem Tag geschieht\'s\", ein Spruch des Herrn, \"da tilge ich aus deiner Mitte deine Rosse, zerbreche deine Wagen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'zerstöre deines Landes Städte, schleife alle deine Festen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Aus deiner Hand vertilge ich die Zauberdinge, auf daß nicht Zeichendeuter bei dir seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Aus deiner Mitte schaff\' ich deine Götzenbilder, deine Säulen weg. Dann fällst du nicht mehr hin vor deiner Hände Werk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Aus deiner Mitte reiße ich die Pfähle aus und tilge deine Haine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Ich nehme Rache an den Heiden voller Zorn und Grimm, weil sie nicht hören wollen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Vernehmt, was jetzt der Herr euch sagt: \"Auf! Führe Klage vor den Bergen! Die Hügel sollen deine Stimme hören!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'So hört des Herren Klage, ihr Berge, und merket auf, ihr festen Gründe dieser Erde! Denn eine Klage hat der Herr wider sein Volk; mit Israel hat er zu rechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '\"Mein Volk! Was hab ich dir getan? Und womit hab ich dich gekränkt? Antworte mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Hab ich dich nicht aus dem Ägypterland geführt und dich befreit aus einem Sklavenhaus und dir vorauf den Moses, Aaron und die Mirjam gesandt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mein Volk! Bedenk, was Balak, Moabs König, plante, und was ihm Bileam, der Beorsohn zur Antwort gab! - von Sittim bis nach Gilgal hin, damit des Herren Gnadentaten offenkundig werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '\"Womit soll vor den Herrn ich treten, mich beugen vor dem Gott der Höhe? Soll ich vor ihn mit Brandopfern hintreten, mit Kälbern, die noch nicht einjährig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Hat wohl der Herr an Tausenden von Widdern Freude, an ungezählten Bächen Öls? Soll meinen Erstgebornen ich für eine Missetat hingeben und meine Leibesfrucht für meiner Seele Schuld?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Dir hat man, Mensch, was gut ist, kundgetan. Was fordert denn der Herr von dir in Wirklichkeit, als recht zu tun und dich der Güte zu befleißen und deinen Gott demütig zu verehren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Laut spricht der Herr zur Stadt, und eine Offenbarung wird daselbst erlebt! Horcht auf! Wer droht die Rute an?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, '\"Noch immer sind des Frevlerhauses Unheil ungerechte Schätze und ein verkleinertes, verwünschtes Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Wie aber kann ich weiter heilig dastehn und dabei frevlerische Waage dulden, einen Beutel voll mit falschen Waagesteinen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Weil ihre reichen Leute von Gewalttat voll und ihre Einwohner nur Lügen reden, weil trügerisch in ihrem Mund die Zunge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'drum schlag ich dir unheilbar tiefe Wunden und vernichte dich um deiner Sünden willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du wirst zwar essen, aber dich nicht sättigen. Und was in dir erzeugt, das bringst du zwar zur Welt; doch hältst du\'s nicht am Leben. Du willst beiseite schaffen, aber du wirst nichts beiseite bringen; was du am Leben hältst, das gebe ich dem Schwerte preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du wirst zwar säen, doch nicht ernten; du wirst Oliven pressen, doch mit dem Öle dich nicht salben, und keltern neuen Wein, doch wirst du ihn nicht trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Denn Omris Wesen hat man nachgeahmt, des Achabhauses ganzes Treiben. Ihr folgtet ihren Grundsätzen. Dafür geh ich dich preis dem Untergang und mache zum Gespötte die Bewohner. Der Völker Schmähung müßt ihr tragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Weh mir! Es geht mir wie beim Obsternten, wie bei der Nachlese der Traubenernte! Nicht eine Traube ist zum Essen da, nicht eine frühgereifte Feige, nach der einen gelüstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Ausgestorben sind die Frommen aus dem Land, und Redliche gibt\'s nicht mehr bei den Leuten. Sie lauern allesamt aufs Blutvergießen; der eine legt dem andern Netze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Fürs Böse sind die Hände tüchtig. Der Fürst stellt ein Verlangen; der Richter zeigt sich einverstanden. Der Große spricht nur seine Wünsche aus, und jener sucht sie zu erfüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Der Beste unter ihnen ist dem Dornbusch gleich, der Redliche noch schlimmer als die Dornenhecke. Am Tag, nach dem du Sehnsucht trägst, wird dich die Strafe treffen. Dann hebt ihr Weinen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Dem Freunde trauet nicht! Verlaßt euch nicht auf die Vertraute! Vor deinem liebsten Weib verwahre deines Mundes Tor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Der Sohn schmäht seinen Vater; die Tochter lehnt sich gegen ihre Mutter auf; die Schwiegertochter gegen ihre Schwiegermutter. Des Mannes Feinde sind die Leute seines Hauses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Ich aber will zum Herrn aufschauen, auf meines Heiles Gott die Hoffnung setzen. Mein Gott wird mich erhören. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Du meine Feindin! Jauchze du nicht über mich! Gefallen bin ich zwar; doch steh ich wieder auf. Und wenn ich auch im Finstern sitze, wird der Herr mir doch zum Lichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Den Zorn des Herrn will ich ertragen, weil ich mich an ihm versündigt, bis daß er meinen Rechtsstreit schlichtet, mir Recht verschafft und mich hinausführt an das Licht, daß ich seine Gerechtigkeit erlebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Wenn meine Feindin dies erblickt, dann wird Enttäuschung sie einhüllen, die zu mir gesprochen hat: \"Wo ist der Herr, dein Gott?\" Da laben meine Augen sich an ihr; dann wird sie wie der Gassenkot zertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Am Tage, da man deine Mauern wieder baut, an jenem Tage, da die Grenzen schwinden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'an jenem Tage kommen sie zu dir von Assur und Ägyptens Städten, von Tyrus bis zum Strom, von Meer zu Meer, von Berg zu Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Verwüstet wird die Erde der Bewohner wegen, um ihrer Werke willen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Mit Deinem Stabe weide Du Dein Volk, die Herde, die Dein Eigen ist, die ganz verlassen im Gestrüpp, jetzt wieder auf dem Fruchtgefilde weilt! In Gilead und Basan soll sie wieder wie vor alters weiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '\"Wie einst bei deinem Auszug aus Ägypterland, so lasse ich sie wieder Wunder schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Beschämt erblicken dies die Heiden; zuschanden werden sie an aller ihrer Macht und legen auf den Mund die Hand, und ihre Ohren werden taub.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Sie sollen Staub wie Schlangen lecken, jenem gleich, was auf dem Boden kriecht. Aus ihren Winkeln kommen sie und beben. Unserem Gott, dem Herrn, nahn sie sich zitternd und fürchten sich vor Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Wer ist ein Gott wie Du, der Missetat vergibt und Sündenschuld verzeiht dem Reste seines Eigentums, der seinen Zorn nicht ewig dauern läßt, vielmehr am Wohltun seine Freude hat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Aufs neue wird er unser sich erbarmen und unsere Schuld abwaschen. Du schleuderst in des Meeres Tiefen alle ihre Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Und Du erfüllst die Treue gegen Jakob und die Huld für Abraham, wie Du geschworen hast zur Urzeit unsern Vätern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Ein Ausspruch über Ninive. Das Buch der Weissagung Nahums, des Elkoschiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Ein eifersüchtiger Gott, ein Rächer ist der Herr, der Herr ein Rächer voller Grimm. Rache an seinen Feinden nimmt der Herr; er trägt es seinen Gegnern nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Langmütig ist der Herr und voll Geduld; doch läßt er niemals etwas ungestraft. Im Sturm und Wetter ist sein Weg, und Wolken türmen sich wie Staub um seine Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Er schilt das Meer und legt es trocken und macht versiegen alle Ströme. Der Basan und der Karmel schmachten hin; die Blüte auf dem Libanon verwelkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Vor ihm erbeben Berge, zittern Hügel. Es springt die Erde vor ihm auf, der Erdkreis und wer ihn bewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Wer kann vor seinem Zorn bestehn und standhalten vor seiner Zornesglut? Wie Feuer brennt sein Zorn; vor ihm zerschmelzen Felsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Der Herr ist gütig und ein Schutz am Tag der Not. Er weiß, wer bei ihm Zuflucht sucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Durch eine Flut, allüberströmend, zerstört er jenen Ort. Ins Finstre stößt er seine Feinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Was denkt ihr von dem Herrn? Den vollen Untergang kann er verhängen, daß keine zweite Not zu kommen braucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Zu Dornen werden sie geballt, wie dürre Stoppeln werden sie verbrannt, wenn sie bei Schmauserei\'n betrunken sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Ist nicht aus dir hervorgegangen, der Schlimmes für den Herrn geplant, ein ganz verruchter Pläneschmied?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So spricht der Herr: \"So stark und zahlreich sie auch sind, sie werden dennoch völlig untergehn. Wenn ich dich auch gestraft, so tu ich\'s nimmermehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Und nun zerbreche ich sein Joch auf dir, und ich zerreiße dir die Fesseln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Und wider dich hat den Beschluß der Herr gefaßt: \"Dein Name soll sich weiter nicht verbreiten. Aus deinem Gotteshaus vertilge ich die Schnitz- und Gußbilder und richte her die Stätte deines Grabes. Du bist ein Scheusal.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Seht! Über Berge eilt ein froher Bote hin, ein Glücksverkünder. Nun feiere, Juda, deine Feste! Was du gelobt, erfülle! Denn kein Verruchter wird dich mehr durchstreifen. Sie alle sind vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Doch jetzt kommt der Zertrümmerer über dich! Betritt die Warte! Den Weg bespähe! Umgürte deine Lenden! Zusammen nimm die ganze Kraft!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Mit Jakobs Prachtschmuck kehrt der Herr zurück, so, wie mit dem von Israel. Denn Räuber hatten es geplündert, vernichtet seine Habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Gerötet sind die Schilde seiner Krieger; die Kämpfer sind in Kot getaucht. Beim hellen Fackelscheine schirren sie die Wagen an und schwingen Feuerspäne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Nun rasen Wagen auf den Straßen hin und rasseln auf den Plätzen, wie Wetterstrahlen anzuschauen, wie Blitze, die daniederfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Jetzt ruft man ihre Tapfersten herbei. Sie schlüpfen durch die Laufgräben. Sie hasten zu der Mauer hin; dann wird ein Sturmdach aufgestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Die Schleusentore werden aufgebrochen; die Flöße schwanken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Die Sockel werden bloßgelegt, gehoben, und ihre Pfosten ächzen gleich den Tauben, ins Mark getroffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Und Ninive wird wie ein Sumpfland namenlos. Nun wird die Flucht ergriffen: \"Haltet! Haltet!\" Doch niemand dreht sich um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, '\"Nun plündert Silber, plündert Gold!\" Unzählig sind die kostbaren Geräte, weit wertvoller als alle andern Kostbarkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Jetzt Öde, Leere, Wüstenei, verzagte Herzen, Kniee schlotternd und Krampf in allen Hüften, aller Angesicht verzogen und verzerrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Wo ist das Löwenlager? Wo jenes Jungleufutter, das herbeizuschaffen der Löwe fortging? Und ungestört verblieben dort die Löwenjungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Der Löwe holte Raub für seine Jungen, würgte ab für seine Löwinnen und füllte seine Höhlen mit dem Raub, mit Beute seine Lagerstatt. \"Jetzt bin ich über dich gekommen\", ein Spruch des Herrn der Heerscharen. \"Ich laß in Feuer deine Lagerstatt aufgehen. Das Schwert frißt deine jungen Leuen, und ich vertilge von der Erde deine Jungen, und deines Knurrens Laut soll nimmermehr vernommen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Weh dieser blutbefleckten Stadt, ganz Lug und Trug, der Grausamkeiten voll, im Rauben unersättlich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Horch, Peitschenknall! Horch! Räderrasseln! Rennende Rosse und rollende Wagen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Stürmende Reiter und funkelnde Schwerter und blitzende Lanzen, Erschlagene in Menge und Tote haufenweise! Kein Ende mehr der Leichen; man stolpert über ihre Leiber,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'der vielen Buhlereien wegen dieser Buhlerin, der so berückenden und zauberkundigen, die Heidenvölker heimgesucht mit ihren Buhlereien, mit ihren Zaubereien Völkerstämme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '\"Fürwahr, ich will an dich\"; ein Spruch des Herrn der Heerscharen, \"bis über das Gesicht deck ich dir deine Schleppen auf, und deine Schande zeige ich den Völkern, den Königreichen deine Schmach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Zu deinem Schimpf beschmutze ich dich jetzt mit Kot und werfe dich in Schmutz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Wer dich erblickt, der wendet sich mit Ekel von dir ab und spricht: \'Mit Ninive ist\'s aus. Wer mag\'s bedauern?\'\" Wo nehme ich nur Leute her, die dich bejammern? -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Hast du dich besser als No Ammon eingerichtet, das an den Flüssen lag, von Wasser rings umgeben, zu dessen Wall ein See, zu dessen Mauern Wasser diente?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Zahlreiche Äthiopier, Ägypter ohne Zahl und Put und Libyer dienten ihm als Hilfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Und dennoch mußte es in die Verbannung ziehen, in Gefangenschaft. An allen Straßenecken wurden seine Kinder zerschmettert, über seine Edlen ward das Los geworfen, und allen seinen Großen wurden Ketten angelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'So wirst auch du berauscht und wirst umnachtet; auch du mußt Zuflucht vor dem Feinde suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'All deine Festungswerke sind wie Feigenbäume mit frühreifen Feigen. Beim Schütteln fallen sie dem in den Mund, der sie verzehren will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Ja, Weibern gleicht bei dir dein Volk, und deinen Feinden öffnen sich die Pforten deines Landes, und deine Riegel frißt das Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Schöpf Wasser dir für die Belagerung! Verstärke deine Festungswerke! Herbei mit Lehm! Stampf Ton! Und bessere das Ziegelbauwerk aus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Dich frißt das Feuer, und dich fällt das Schwert und frißt dich, wie Heuschrecken tun. - Vermehre dich wie Heuschrecken! Vermehre dich wie Ungeziefer!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Mach deine Händler zahlreich wie des Himmels Sterne! Die Heuschrecken entpuppen sich und fliegen fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Und seien\'s deiner Streiter auch so viele wie Ungeziefer und deiner Späher so viele wie Heuschrecken, die an den Mauern sich an kalten Tagen aufhalten; wenn dann die Sonne aufgeht, fliegen sie davon, und niemand kennt die Stätte, wo sie waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Zum Schlafe sinken deine Fürsten hin, Assyrerkönig, und deine Helden ruhen; auf Bergen ist dein Volk zerstreut, und niemand sammelt es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Kein Mittel gibt\'s für deine Wunde, unheilbar dein Schaden. Ein jeder, der von deinem Schicksal hört, klatscht deinetwegen in die Hände. Denn über wen entlud sich nicht andauernd deine Bosheit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Das Gesicht, das Habakuk, der Prophet, geschaut:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Wie lange rufe ich um Hilfe, Herr? Doch Du hörst nicht auf mich. Und schreie ich zu Dir: \"Bedrückung!\" Du aber rettest nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Warum läßt Du mich Unheil sehn und siehst dem Jammer zu? Warum steht Druck und Vergewaltigung mir vor den Augen? Warum erhebt sich Kampf und Krieg?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Dadurch hört die Belehrung auf, und nimmer kommt das Glück zum Vorschein. Und weil ein Frevler den Gerechten umgarnt, drum kommt verkehrtes Recht heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Schaut auf die Heidenvölker! Blicket hin! Verwundert euch und staunt! In euren Tagen wirkt er eine Tat, die ihr nicht glaubtet, würde sie euch bloß berichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, '\"Ich bin\'s, der die Chaldäer sich erheben läßt, das hitzige, das ungestüme Heidenvolk, das über Erdenweiten zieht, um fremde Wohnsitze sich zu erobern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'So schrecklich ist\'s, so fürchterlich; sein Urteil und sein Unheil stammt von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Und schneller als die Panther seine Pferde, kühner als die Steppenwölfe, und stolzen Ganges seine Rosse, seine Reiter; aus weiter Ferne kommen sie; sie fliegen wie die Adler, die zum Fraße eilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Sie alle gehen auf Gewalttat aus, und Gier belebt die Blicke ihnen; wie Sand, so sammelt es Gefangene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Und es verhöhnt die Könige, treibt Spott mit Fürsten. Es lacht auch aller Festungen; es schüttet einfach Erde auf und nimmt sie ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Dann greift es stürmisch an und zieht hinein und handelt ruchlos. So ist denn seine Macht sein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Bist Du nicht, Herr, von alten Zeiten her mein heiliger Gott, der niemals stirbt? Du hast ihn zum Gerichte, Herr, bestimmt, Du Fels, zum Strafen ihn gebildet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Zu rein sind deine Augen, Böses anzuschauen. Nichts Arges kannst Du sehen. Wie siehst Du nunmehr Räubern schweigend zu, wenn Frevler die Unschuldigen verschlingen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Wie machst Du Menschen Meeresfischen gleich und dem Gewürm, das keinen Herrn besitzt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Sie alle holt es mit den Angeln ein und lockt sie in sein Garn und rafft sie in sein Netz. Darüber freut es sich und jubelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Deswegen opfert es auch seinem Garn und räuchert seinem Netz. Denn fette Beute schaffen diese ihm und eine wohlbestellte Tafel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Doch sollte es deshalb sein Garn entleeren, beständig Heidenvölker schonungslos abschlachten dürfen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Ich will auf meine Warte treten, mich auf meinen Wachtturm stellen, um also spähend zu vernehmen, was er mir sagt, was er auf meine Klage mir zur Antwort gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Da gibt der Herr mir dies zur Antwort, und er spricht: \"Schreib das Gesicht dir auf und zeichne es in Tafeln ein, daß jeder es geläufig lesen kann!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Denn noch geht das Gesicht auf die bestimmte Zeit und spricht vom Ende sonder Trug. Und wenn es zögern sollte, harre sein! Es kommt ja sicherlich und bleibt nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Wenn schon der Aufgeblasne seine Seele nicht glücklich macht, indessen der Gerechte leben bleibt durch seine Redlichkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'dann um so minder der Gewaltmensch, dieser Räuber, der Mann voll Übermut, der Ungesittete, der gleich der Hölle seinen Mund aufreißt und wie der Tod so unersättlich ist, der diesem alle Heidenvölker überliefert und alle Nationen zu ihm bringt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Stimmt da nicht alles über ihn ein Spottlied an und einen rätselhaften Spottgesang auf ihn? Man singt: \"Ein Wehe dem, der aufgespeichert, was nicht sein, - wie lange noch? - und der das Pfand so schwer gemacht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Ja, stehen deine Gläubiger nicht plötzlich auf, erwachen deine Peiniger? Zur Beute fällst du ihnen zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Weil viele Heidenvölker du ausgeplündert hast, so plündert dich der Völker ganzer Überrest für das vergossene Menschenblut und für die Grausamkeit an Stadt und Land und was darin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Weh dem, der schändlichen Gewinn in seinem Hause häuft, um seinen Sitz sich in der Höhe anzulegen und sich vor Unheilshand zu retten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Du hast gar schmählich für dein Haus gesorgt, so vielen Völkern Untergang bereitet, und so versündigst du dich an dir selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Denn jeder Stein schreit aus der Wand, und jeder Balken aus dem Holzwerk stimmt ihm bei:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, '\"Weh dem, der eine Stadt mit Blutschuld baut und eine Burg mit Frevel!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Ist solches nicht verhängt vom Herrn der Heerscharen, daß sich fürs Feuer Völker mühen und für ein Nichts Nationen sich ermüden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Die Erde sollte von Einsicht in die Herrschergröße des Herrn erfüllt sein, wie den Meeresboden Wasser decken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Weh dem, der seinen Nachbar trinken läßt! Weh dir, der du dem Trunk dein Gift beimischest, um ihre Blöße anzuschaun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Du sättigst dich an Schmach mehr als an Ruhm. Trink selber nun und taumle hin! Zu dir kommt jetzt der Becher in der rechten Hand des Herrn, und deine Ehre wird bespieen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Des Libanon Verwüstung lastet ja auf dir, und die Gewalttat an den Tieren wird für dich zum Schrecken wegen des vergossenen Menschenblutes und der Grausamkeit an Stadt und Land und allen, die dort wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Was nützt ein Schnitzbild, daß es sein Bildner schnitzte? Ein Gußbild, das nur Lüge lehrt, wenn sich des Künstlers Herz darauf verläßt, derweil er stumme Götzen macht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Weh dem, der zu dem Holze spricht: \"Erwache!\", \"Wach auf!\" zum stummen Stein, daß er Bescheid ihm gäbe! Gefaßt ist er in Gold und Silber nur; in seinem Innern aber ist kein Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Dagegen vor dem Herrn in seinem heiligen Tempel, vor ihm sei still die ganze Welt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Ein Gebet Habakuks, des Propheten, ein Klagelied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Die Kunde über Dich vernahm ich zitternd, Herr, Dein Werk verwirkliche, o Herr, in ein paar Jahren! In ein paar Jahren zeig es! Doch gib im Zorne dem Erbarmen Raum!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Von Teman her kommt Gott, der Heilige vom Berge Pharan. (Sela.) Den Himmel deckt sein Glanz; die Erde ist erfüllt von seinem Schimmer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Sein Schein ist wie das Sonnenlicht, und seiner Hand entsprühen Strahlen. Alsdann verhüllt sich seine Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Die Pest zieht vor ihm her, und Fieber folgt ihm auf dem Fuß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Und tritt er auf, zertrümmert er die Erde; mit seinem Blick zersprengt er Heidenvölker. Uralte Berge bersten, alte Hügel sinken hin und alte Wege vor ihm nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Ich sehe, wie sich Kuschans Zelte ducken; im Lande Midian erzittern Zeltdecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Ist gegen Fluten, Herr, Dein Zorn entbrannt, ja, gegen Fluten? Befällt das Meer Dein Grimm? Besteigst Du deine Rosse, Deine Kriegswagen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Und wird Dein Bogen ganz enthüllt? Und füllst Du denn mit Pfeilen Deinen Köcher? (Sela.) Und spaltest Du die Erde über alles Maß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Erbebend schauen Berge Dich, und Wasser läßt der Regen strömen. Erdröhnen läßt die Tiefe ihre Stimme; die Höhe reckt die Hände aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'In ihrer Wohnung bleiben Mond und Sonne. Leuchtend fliegen Deine Pfeile hin; Dein Speer blitzt glänzend auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'So schreitest Du voll Grimm durchs Land; im Zorn zertrittst Du Heidenvölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du ziehst zu Hilfe Deinem Volk, zu helfen dem, den Du gesalbt. Du schlägst die Spitze ab im Haus des Frevlers; den Grund entblößest Du bis auf das äußerste. (Sela.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Du schlägst dann seines Fürsten Haupt samt seinen Scharen nieder, die da herbeigestürmt, mich zu zerschmettern, die einen Siegesjubel angestimmt, als ob sie unbeachtet Wehrlose verzehren könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Du stampfest seine Rosse in das Meer, in viele Wasser den Tyrannen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Ich höre es; mein Herz erbebt, und bei der Rede zittern meine Lippen. In mein Gebein kommt Schwäche, meine Beine sind gelähmt, weil ich den Drangsalstag erwarte, an dem ein Volk uns überfällt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'wenn dann die Feigenbäume keine Frucht mehr tragen und keine Frucht mehr an den Reben ist, des Ölbaums Früchte mangeln und die Gefilde keine Nahrung liefern, die Schafe aus den Hürden schwinden und in den Ställen keine Rinder sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Und dennoch juble ich im Herrn und jauchze über meinen Rettergott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Der Herr, der Herr, ist meine Kraft. Schnellfüßig macht er mich gleich Rehen. Auf meine Höhen führt er mich, daß ich mein Zitherspiel ertönen lasse. (Auf den Siegesspender mit Zithern.)');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Das Wort des Herrn erging an Sophonias, Kusis Sohn und Enkel des Gedalja, Urenkel Amarjas, des Ezechiassohnes, zur Zeit des Judakönigs Josias, des Amossohnes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '\"Fortraffen will ich alles aus dem Land\", ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, '\"Fortraffen will ich Vieh und Menschen, fortraffen auch des Himmels Vögel samt den Meeresfischen, die Ärgernisse samt den Himmelsgottheiten, ausrotten aus dem Land die Menschen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, '\"Nun will ich gegen Juda meine Hand ausstrecken und gegen die Bewohner von Jerusalem. Aus diesem Orte tilge ich den Baal bis auf seinen Rest, der Götzenpriester Namen samt den Priestern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Auch jene, die das Himmelsheer anbeten auf den Dächern, und jene, die sich zum Herrn bekennen und zugleich zu Milkom. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Die abgefallen sind vom Herrn, die nicht den Herrn gesucht, nicht um den Herrn sich mehr gekümmert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Jetzt stille vor dem Herrn, dem Herrn! Der Tag des Herrn ist nah, hat doch der Herr ein Schlachtfest hergerichtet und seine Gäste schon bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Am Tag des Schlachtfestes des Herrn wird es geschehen: \"Ich suche heim die Fürsten und die Königssöhne und alle, die ausländische Gewänder tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Ich suche heim an jenem Tag auch alle, die über Schwellen hüpfen, die ihres Herren Haus mit Unrecht und mit Trug erfüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'An jenem Tag\", ein Spruch des Herrn, \"erschallt ein lautes Wehgeschrei vom Fischtor her und aus der Neustadt Wehgeheul und von dem Hügel großes Angstgeschrei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Es heulen, die im Mörser wohnen; vernichtet wird das ganze Krämervolk, und ausgerottet werden alle Geldabwäger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Wenn dies zu jener Zeit geschieht, alsdann durchsuche ich Jerusalem mit Leuchten. Dann suche ich die Männer heim, die zäh auf ihren Hefen wurden und bei sich sprachen: \'Der Herr tut weder wohl noch weh\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Nun werden ihre Schätze ausgeplündert und zertrümmert ihre Häuser. Sie haben Häuser sich gebaut und wohnen nicht mehr drin, Weinberge sich gepflanzt und dürfen ihren Wein nicht trinken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Der große Tag des Herrn ist nahe, voller Eifer. Laut ruft die Stimme: \"Der Tag des Herrn ist bitter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ein Tag des Zorns ist jener Tag, ein Tag der Angst und Not, ein Tag des Wetterns und des Stürmens, ein Tag der Dunkelheit und Finsternis, ein Tag der Wolken und der Nacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'ein Tag des Blasens und des Kriegsgeschreis vor festen Städten, hohen Zinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, '\"Da ängstige ich die Leute, daß sie Blinden gleichen, wenn sie schreiten, weil sie sich am Herrn versündigt; ihr Blut soll in den Staub verschüttet werden, ihr Eingeweide in den Kot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ihr Silber nicht, ihr Gold kann sie nicht retten am Zornestag des Herrn. Vom Feuer seines Zorneseifers wird das ganze Land verschlungen, weil er schnellstens Untergang verhängt jetzt über alle, die dies Land bewohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Geh in dich, Volk! Geh in dich, das du dich nicht schämst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Eh ein Befehl erscheint, der Tag soll kommen, rückhaltlos, bevor noch über euch des Herren Zorngrimm sich ergießt, bevor noch über euch der Zornestag des Herrn erscheint!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Alle ihr Niedrigen auf Erden, sucht den Herrn! Ihr, die ihr sein Gesetz erfüllt, befleißt euch der Gerechtigkeit! Befleißigt euch der Demut! Vielleicht, daß ihr am Zornestag des Herrn geborgen werden könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Verlassen wird ja Gaza, Askalon verödet. Zur Mittagszeit verheert man Asdod, und Akkaron wird ausgetilgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Weh euch, die ihr am Meeresufer wohnt, du Kretervolk! Das Wort des Herrn an euch ist das an Kanaan vormals ergangene, Philisterland. \"Ich mache dich ganz menschenleer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Der Strich am Meere wird zu Triften, zu Weideplätzen für die Hirten, zu Hürden für die Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Das Ufer fällt dem Rest des Hauses Juda zu; sie treiben dorthin ihre Herden und lagern in den Häusern Askalons am Abend. Es sucht sie wieder heim der Herr, ihr Gott, und wendet ihre Haft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '\"Ich habe Moabs Schmähung angehört, der Söhne Ammons Lästerworte; sie schmähten auf mein Volk und brüsteten sich stolz mit ihrer Grenze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Darum, so wahr ich lebe\", ein Spruch des Herrn der Heerscharen, des Gottes Israels, \"wie Sodom werde Moab und die Ammonssöhne wie Gomorrha, ein Raum voll Disteln, ein Ort, mit Salz bestreut und eine ewige Wüste! Sie plündert meines Volkes Überrest, und meines Volkes Rest verteilt sie unter sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Dies ist ihr Teil für ihren Übermut, den sie am Volk des Herrn der Heerscharen ausgeübt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Furchtbar zeigt ihnen sich der Herr, wenn alle Götter auf der Erde er vernichtet. Dann beten alle Inseln der Heiden, Ort für Ort, ihn an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, '\"Mit ihnen werden die Kuschiten Opfer meines Schwertes sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Dann streckt er gegen Norden seine Hand, vertilgt Assyrien, verwandelt Ninive in eine Wüste, in einen öden Platz gleich einer Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Drin lagern sich in Rudeln die Scharen wilder Tiere. Auf ihren Säulenknäufen mächtigen die Igel und Nachteulen. Geheul tönt aus den Fenstern und Gebrüll von ihren Schwellen; denn ausgeplündert ist die Burg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Ist das die stolze Stadt, die gar so sicher wohnte, die bei sich sprach: \"Ich bin\'s und keine andere sonst\"? Des Wildes Lagerstätte ist sie jetzt. Wie ist sie doch verwüstet worden! Wer immer sie betrachtet, zischt und schlägt in seine Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Weh der abscheulichen, bedeckten Stadt, der quälerischen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'die nie auf eine Warnung hört und keine Zucht annimmt, die nimmer auf den Herrn vertraut, die ihrem Gott sich nicht mehr naht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'In ihr sind ihre Fürsten brüllende Löwen und ihre Richter ausgezehrte Wölfe, die nicht auf den Morgen warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Leichtfertig ihre Seher und des Truges Männer; und Heiliges entweihen ihre Priester, freveln an der Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Als ein Gerechter wohnt der Herr in ihr; er tut nichts Unrechtes. Allmorgendlich setzt er sein Rechtsverfahren an; beim Tagesgrauen läßt er sich nicht missen, und dabei weiß er gar nichts von schmachvollem Unrechttun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '\"Ich habe Heidenvölker ausgerottet; eingerissen wurden ihre Winkel. Verödet hab ich ihre Gassen, daß niemand sie durchzog, und ihre Städte wurden so zerstört, daß niemand mehr drin wohnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Da dachte ich, du fürchtetest mich jetzt, du nähmest Zucht an, daß nicht Zerstörung ihren Wohnsitz treffe, nicht alles das, womit ich ihr gedroht. Doch um so eifriger verdarben sie all ihre schlimmen Werke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Doch wartet nur auf mich,\" ein Spruch des Herrn, \"nur auf den Tag, da ich als Kläger mich erhebe! Mein Recht ist es, die Heidenvölker zu versammeln und Königreiche aufzubieten, um über jene meinen Grimm zu gießen, all meine Zornesgluten. Vom Feuer meines Zorneseifers soll das ganze Land gefressen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Alsdann verleih ich wieder meinem Volke reine Lippen, daß sie alle den Namen ihres Herrn anrufen und ihn einmütig verehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Von jenseits her der Flüsse Äthiopiens, von Indien und Medien und Persien wird man mir Wohlgerüche als Geschenk darbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Du wirst an jenem Tag dich aller deiner Taten schämen, durch die du dich an mir vergangen; denn dann entferne ich die frechen Sünder aus deiner Mitte. Du bist dann nicht mehr voller Übermut auf meinem heiligen Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'In deiner Mitte laß ich dann ein Volk noch übrig, demütig und gering. Sie nehmen zu des Herren Namen ihre Zuflucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Wer übrigbleibt von Israel, der tut kein Unrecht mehr und spricht nicht Lügen. Kein trügerisches Wort ist mehr in ihrem Mund; sie können weiden und sich lagern und niemand schreckt sie auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Frohlocke, Sionstochter! Israel, nun jauchze auf! Sei froh! Aus ganzem Herzen juble,Tochter du Jerusalem!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Der Herr entfernte deine Richter; verschwinden ließ er deinen Feind. Der Herr ist wieder König über Israel in dir; dir widerfährt nichts Schlimmes mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'An jenem Tage spricht man zu Jerusalem: \"Fürchte dich nicht! Laß deine Hände, Sion, nimmer sinken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'In deiner Mitte ist der Herr, dein Gott, der Held, der hilft. Er freut sich deiner wonnevoll, umfaßt mit Liebe dich, frohlockend, und jauchzt und jubelt über dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Die Possen an dem Feste lasse ich bei dir verschwinden; sie waren eine schimpfliche Zugabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Zu jener Zeit vernichte ich deine Bedränger alle. Dagegen rette ich das Lahme, sammle das Versprengte und bringe sie zu Ruhm und Ehre in allen Landen ihrer Schmach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'In jener Zeit, da bringe ich euch heim. Die Zeit erscheint, da ich euch sammle. Ich bringe euch zu Ruhm und Ehre bei allen Erdenvölkern, wenn ich vor euren eigenen Augen wende eure Haft.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im zweiten Jahr des Königs Darius, im sechsten Monat am ersten Monatstag, erging das Wort des Herrn durch den Propheten Aggäus an den Statthalter von Juda, Zorobabel, Salatiels Sohn, sowie an den Hohenpriester Josue, Josadaks Sohn, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So spricht der Herr der Heerscharen: \"Die Leute sagen, die Zeit sei noch nicht da, das Haus des Herrn zu bauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Darauf erging das Wort des Herrn durch den Propheten Aggäus, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '\"Ist es denn Zeit für euch, in euren Häusern, den getäfelten, zu ruhn, obgleich dies Haus in Trümmern liegt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nun überlegt einmal\", so spricht der Herr der Heerscharen, \"wie\'s euch bisher ergangen ist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr sät viel aus; doch wenig erntet ihr. Ihr esset, werdet aber nimmer satt; ihr trinket, werdet nimmer froh. Ihr ziehet Kleider an und werdet nimmer warm, und wer um Lohn arbeitet, tut ihn in einen löcherigen Beutel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht der Herr der Heerscharen: \"Überlegt doch, wie es euch bisher erging!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Dann steiget auf die Berge! Herbei mit Holz und baut das Haus! Dies wird mich freuen und mich ehren.\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, '\"Ihr machtet Platz für viel und seht: Es ward nur weniger. Und was ihr eingeheimst, das blies ich weg. Weshalb?\" Ein Spruch des Herrn der Heerscharen. \"Um meines Hauses willen, das in Trümmern liegt, und jeder unter euch ist nur geschäftig für sein Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Deshalb hält über euch der Himmel seinen Tau zurück, und den Ertrag versagt die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Und ich rief Dürre über Land und Berge und über Korn und Most und Öl herbei und über alles, was der Boden trägt, und über Mensch und Vieh und aller Hände Arbeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Da hörten Zorobabel, Salatiels Sohn, und Josue, der Sohn des Josadak, der Hohepriester, sowie der ganze Rest des Volkes auf die Stimme ihres Herrn und Gottes, das heißt auf des Aggäus, des Propheten, Worte, sobald der Herr, ihr Gott, ihn abgesandt. Furcht vor dem Herrn befiel das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Da sprach Aggäus, des Herren Bote, gemäß des Herren Botschaft zu dem Volk: \"Ich werde mit euch sein.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Und da erweckte Gott den Geist Zorobabels, des Sohns Salatiels, des Statthalters von Juda, sowie den Geist des Hohenpriesters Josue, des Sohnes Josadaks, und den des ganzen Volksrestes. Und so begannen sie die Arbeit an dem Haus des Herrn der Heerscharen und ihres Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'am vierundzwanzigsten des sechsten Monats, im zweiten Jahr des Königs Darius.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Am einundzwanzigsten Tag des siebenten Monats erging das Wort des Herrn durch den Propheten Aggäus, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '\"Zum Sohn Salatiels, Zorobabel, dem Statthalter von Juda, sowie zum Hohenpriester Josue, dem Sohne Josadaks, und zu des Volkes Rest sprich also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, '\'Wer ist von euch noch übrig, der dies Haus geschaut in seiner ersten Herrlichkeit? Wie aber seht ihr\'s jetzt? Ist\'s nicht wie nichts in euren Augen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Und doch, faß Mut, Zorobabel!\' Ein Spruch des Herrn. \'Faß Mut, du Josue, Sohn des Josadak und Hoherpriester! Faß Mut, gesamtes Volk des Landes!\' Ein Spruch des Herrn. \'Und haltet doch - ich will ja mit euch sein\', ein Spruch des Herrn der Heerscharen -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, '\'den Bund, den ich bei eurem Auszug aus Ägypten mit euch geschlossen habe! Dann bleibt mein Geist in eurer Mitte, und ihr braucht keine Furcht zu haben!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, '\"Denn also spricht der Herr der Heerscharen: \'Noch einmal eine kleine Weile noch, erschüttre ich den Himmel und die Erde, das Meer sowie das trockene Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Und ich erschüttre alle Heidenvölker, und aller Heiden Schätze kommen her, und so erfülle ich dies Haus mit Herrlichkeit.\' So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '\'Mein ist das Silber, mein das Gold.\' Ein Spruch des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, '\'Und dieses Hauses künftige Pracht wird größer als die des früheren.\' So spricht der Herr der Heerscharen. \'An diesem Orte will ich Heil verleihen.\' Ein Spruch des Herrn der Heerscharen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Am vierundzwanzigsten des neunten Monats, im zweiten Jahre des Darius, erging das Wort des Herrn durch den Propheten Aggäus also:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '\"So spricht der Herr der Heerscharen: \'Die Priester bitte um Belehrung über dies:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Trägt jemand heilig Fleisch in seines Kleides Bausch, und er berührt mit seinem Bausche Brot, Gekochtes oder Wein und Öl und sonst etwas Genieß bares, wird dies dadurch geweiht?\'\" Die Priester gaben drauf zur Antwort: \"Nein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Da sprach Aggäus: \"Berührte aber jene Dinge jemand, der unrein ist durch eine Leiche, so würden sie wohl unrein werden?\" Die Priester gaben drauf zur Antwort: \"Ja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Da fuhr Aggäus fort und sprach: \"So ist in meinen Augen dieses Volk, so diese Nation beschaffen\", ein Spruch des Herrn, \"und so auch alle Arbeit ihrer Hände, wohin sie treten, wird es unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Nun denkt vom heutigen Tag in die Vergangenheit zurück, bevor man Stein auf Stein am Heiligtum des Herrn gelegt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Eh dies geschehen war, wenn einer kam zu einem Haufen Gerste, gut zu zwanzig Maß geschätzt, so waren\'s nur noch zehn. Wenn einer hin zur Kelter kam, um fünfzig Maß zu schöpfen, so waren\'s nur noch zwanzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Mit Kornbrand schlug ich euch und mit Vergilbung, mit Hagel alles, was ihr angebaut. Doch wolltet ihr von mir nichts wissen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, '\"Nun aber richtet euer Augenmerk von diesem Tag an vorwärts hin, vom vierundzwanzigsten des neunten Monats! Vom Tag an, da man an dem Heiligtum des Herrn den Grundstein legte, gebt acht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'ob noch die Saatfrucht in den Speichern schwindet und ob der Weinstock und der Feigenbaum, Granat- und Ölbaum noch nicht tragen! Von diesem Tag an spendete ich Segen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Zum zweitenmal erging das Wort des Herrn am vierundzwanzigsten desselben Monats an Aggäus, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '\"Zum Statthalter von Juda, zu Zorobabel sprich also: Ich werde jetzt den Himmel und die Erde tief erschüttern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Die Königsthrone stürz ich um. Die Rosse samt den Reitern sinken hin, ein jeder durch des andern Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'An jenem Tag\", ein Spruch des Herrn der Heerscharen, \"da nehm ich dich, Zorobabel, Salatiels Sohn, zu meinem Diener\", ein Spruch des Herrn, \"und hüte dich wie einen Siegelring. Dich habe ich erkoren.\" Ein Spruch des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Am achten Neumonde, im zweiten Jahre des Darius, erging das Wort des Herrn an den Propheten Zacharias, des Barachias Sohn und Iddos Enkel, also lautend:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '\"Gar schwer hat über eure Väter sich der Herr erzürnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Zu ihnen sprich: So spricht der Herr der Heerscharen: \'Zu mir kehrt euch\', ein Spruch des Herrn der Heerscharen, \'dann kehr\' auch ich mich zu euch.\' So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, '\'Seid nicht wie eure Väter, denen einst die früheren Propheten zugerufen: \"So spricht der Herr der Heerscharen: Bekehret euch von euren schlimmen Wegen, euren bösen Taten!\" Sie aber hörten nicht und hatten keine Acht auf mich.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '\'Wo sind nun eure Väter? Wo die Propheten? Leben diese ewig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Doch meine Worte und Beschlüsse, die ich einst meinen Dienern, den Propheten, aufgetragen, haben sie nicht eure Väter in der Tat getroffen? Ja, kämen sie zurück, sie sprächen: \"So, wie der Herr der Heerscharen nach unserm Wandel, unsere Taten uns zu tun beschlossen hatte, so hat er wirklich auch an uns getan.\"\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Am vierundzwanzigsten des elften Monats, das ist im Monat Schebat, im zweiten Jahre des Darius, erging das Wort des Herrn an Zacharias, Barachias\' Sohn und Iddos Enkel, den Propheten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Mir wurde ein Gesicht in letzter Nacht zuteil: Auf einem roten Rosse saß ein Mann. Er hielt mit einem Heer von Tausenden Berittener, und hinter ihm gab\'s dunkle, rote, weiße Reiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, '\"Mein Herr\", sprach ich, \"was sollen diese?\" Und mir erwiderte der Engel, der mit mir zu reden pflegte: \"Ich will dir zeigen, was sie sollen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Und dann begann der Mann, der mit dem Heer der Tausende dastand, zu sprechen: \"Dies sind die Leute, die der Herr gesandt, die Erde zu durchstreifen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Da meldeten sie sich bei dem Herrenengel, der mit dem Heer der Tausende dastand, und sprachen: \"Durchzogen haben wir die Erde; die ganze Erde liegt in Ruh und Frieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Da hob des Herren Engel an und sprach: \"Du Herr der Heerscharen! Wie lang willst Du denn Dich nicht Jerusalems erbarmen, nicht der Städte Judas, denen du schon siebzig Jahre zürnst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Da gab der Herr dem Engel, der Mir liebe Worte zugesprochen, Worte voller Trost zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Dann sprach zu mir der Engel, der mit mir redete: \"So predige und sprich! So spricht der Herr der Heerscharen: \'Für Jerusalem und Sion glühe ich vor übergroßem Liebeseifer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Dagegen zürne ich den satten Heidenvölkern sehr, denn während ich ein wenig nur gezürnt, da halfen sie das Übel noch vergrößern.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Deshalb spricht so der Herr: \'Ich wende mich Jerusalem in Gnade wieder zu; errichtet wird darin mein Haus\', ein Spruch des Herrn der Heerscharen, \'und angelegt die Meßschnur an Jerusalem.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Noch einmal predige: So spricht der Herr der Heerscharen: \'Von Segen sollen meine Städte überfließen!\' Der Herr wird Sion wieder trösten, Jerusalem sich wiederum erwählen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Ich schlug aufs neue meine Augen auf und schaute; da zeigten sich der Hörner vier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Da fragte ich den Engel, der mit mir redete: \"Was sollen diese?\" Er sprach zu mir: \"Dies sind die Hörner, die Israel und Juda und Jerusalem zu Boden stießen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Alsdann ließ mich der Herr vier Schmiede sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Ich sprach: \"Was wollen diese tun?\" Er sprach zu mir: \"Dies sind die Hörner, die zu Boden Juda stießen, daß keiner mehr sein Haupt erheben mochte; da kommen jene, diese zu entfernen, der Heidenvölker Hörner hinzuwerfen, die gegen Judaland das Horn erhoben, es auf den Boden hinzustoßen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Aufs neue schlug ich meine Augen auf und schaute, da war ein Mann mit einer Meßschnur in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, '\"Wohin\", frug ich, \"willst du?\" Er sprach zu mir: \"Jerusalem zu messen und zu sehn, wie breit und lang es wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Nun ging der Engel vorwärts, der mit mir redete; da kam ein andrer Engel ihm entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Er sprach zu ihm: \"Lauf! Sag dem jungen Mann: \'Jerusalem bleibt ohne Mauern jetzt, der Menge all der Menschen und des Viehes wegen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, '\'Ich selber diene ihm\', ein Spruch des Herrn, \'ringsum als Feuermauer, selber ihm zum Glanz.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, '\'Auf! Auf! Flieht aus des Nordens Land!\' Ein Spruch des Herrn. \'Ich streute euch nach allen den vier Himmelswinden.\' Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, '\'Auf! Rette dich nach Sion du, die du bei Babels Tochter weilst!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Denn also spricht der Herr der Heerscharen, der mich gesandt, nachdem er seinen Sinn geändert, von jenen Völkern, die euch ausgeplündert: \'Wer euch anrührt, der rührt an seines Auges Apfel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Ich schwinge gegen jene meine Hand; sie sollen eine Beute ihrer Sklaven werden.\' Da seht ihr ein, daß mich der Herr gesandt. \'Du, Tochter Sions, juble und frohlocke! Ich komme, und ich wohne ja in deiner Mitte.\' Ein Spruch des Herrn.\" Dann schließen sich an jenem Tage viele Völker an den Herrn. \"Sie werden mir zum Volke sein. Ich wohne dann in deiner Mitte.\" Dann siehst du ein: Der Herr der Heerscharen hat mich zu dir gesandt. So nimmt der Herr sich Juda wiederum zu eigen im heiligen Land, und er erwählt sich wiederum Jerusalem. Vorm Herrn sei alle Welt jetzt still! Er ist in seiner heiligen Wohnung aufgewacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Er ließ mich Josue, den Hohenpriester, sehen, wie dieser vor des Herren Engel stand und wie der Satan sich an seine Rechte stellte, ihn anzuklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Da sprach des Herren Engel so zu Satan: \"Der Herr bedrohe dich, du Satan! Der Herr bedrohe dich, er, der Jerusalem sich wieder auserwählt Ist dieser nicht ein Scheit, dem Brand entrissen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Und Josue war angetan mit Kleidern voller Schmutz; so stand er vor dem Engel da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Da hob er an und sprach zu denen, die vor ihm standen: \"Zieht ihm die schmutzbedeckten Kleideraus!\" Dann sagte er zu ihm: \"Ich nehme dir die Schuld hinweg und hülle dich in Festgewänder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Dann sprach er noch: \"Man setze seinem Haupte einen reinen Bund auf!\" Da setzten sie ihm einen reinen Kopfbund auf und hüllten ihn in andre Kleider; dann setzte ihn des Herren Engel wieder ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Des Herren Engel gab dabei dem Josue ein feierlich Versprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'So spricht der Herr der Heerscharen: \"Wenn du auf meinen Wegen gehst und meine Ordnungen befolgst, dann darfst du der Verwalter meines Hauses sein und über meine Vorhöfe die Aufsicht führen; dann laß ich dich zu denen gehen, die hier stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Vernimm es, Hoherpriester Josue: Du und auch deine Freunde, die ihre Sitze vor dir haben, ihr selber seid ein Vorzeichen, daß ich herführe meinen Knecht, den Sproß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Und auf dem Steine, den ich Josue aufgelegt, auf diesem e i n e m Stein sind sieben Felder; ich lasse eine Inschrift drauf eingraben:\" Ein Spruch des Herrn der Heerscharen. \"An einem Tag vergebe ich dem Lande seine Schuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'An jenem Tag\", ein Spruch des Herrn der Heerscharen, \"da ladet ihr einander unter Feigenbaum und Weinstock ein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Da weckte mich der Engel wieder, der mit mir redete, wie einen, den man aus dem Schlafe weckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Er sprach zu mir: \"Was schaust du?\" \"Ich sehe\", sprach ich, \"einen Leuchter, ganz von Gold, mit seinem Ölbehälter drauf, und seiner Lampen sind es sieben. Die sieben Lampen haben sieben Röhrchen. die zur Spitze laufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Zwei Ölbäume sind neben ihm, der eine rechts, der andre links vom Ölbehälter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Da hob ich an und sprach zum Engel, der mit mir redete: \"Mein Herr, was sollen diese?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Da hob der Engel an, der mit mir redete, und sprach zu mir: \"Weißt du das nicht, was sie bedeuten?\" - \"Nein, Herr!\" sprach ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Da hob er an und sprach zu mir: \"Dies ist das Wort des Herren an Zorobabel: \'Nicht durch Gewalt und nicht durch Tüchtigkeit! Nein! Nur durch meinen Geist allein!\' So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Was bist du, großer Berg? Sink nieder vor Zorobabel zur Ebene! Wenn er den Schlußstein herholt, erschallt der Freudenruf: \'Heil ihm, Heil ihm!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Und noch erging das Wort des Herrn an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '\"Den Grund zu diesem Hause legten die Hände des Zorobabel; sie werden\'s auch vollenden. - Dann siehst du ein: Der Herr der Heerscharen hat mich zu euch gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Wer vormals auf den kleinen Anfang mit Verachtung sah, der ist voll Freude, wenn er in der Hand Zorobabels den Sonderstein erblickt. - Die sieben sind des Herren Augen, die auf die ganze Erde schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Da hob ich an und fragte ihn, was jene beiden Ölbäume bedeuten, rechts und links vom Leuchter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Zum zweiten Male hob ich an und sprach zu ihm: \"Was sollen diese beiden jungen Ölbäume, die neben jenen goldnen Röhren sind, die goldnes Öl durchfließen lassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Er sprach zu mir: \"Weißt du denn nicht, was sie bedeuten?\" - \"Nein, Herr!\" sprach ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Er sprach: \"Sie deuten zwei Gesalbte an, die vor dem Herrn der ganzen Erde stehn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Ich schlug aufs neue meine Augen auf und schaute; da sah ich eine Rolle fliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Er fragte mich: \"Was siehst du da?\" Ich sprach:\"Ich sehe eine Rolle fliegen, zwanzig Ellen lang, zehn Ellen breit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Er sprach zu mir: \"Das ist der Fluch, der übers ganze Land ergeht. Wer stiehlt, der wird dafür bestraft. Wer einen Meineid schwört, wird ebenfalls dafür bestraft.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, '\"Sprech\' ich ihn aus\", ein Spruch des Herrn der Heerscharen, \"so dringt er in des Diebes Haus und in das Haus des Mannes, der falsch bei meinem Namen schwört, und setzt sich mitten in dem Hause fest, bis er sein Holz und sein Gestein zermalmt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Der Engel ging voraus, der mit mir redete, und sprach zu mir: \"Heb deine Augen auf und schau! Was ist\'s, was da zum Vorschein kommt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Ich sprach: \"Was ist es wohl?\" Er sagte: \"Eine Tonne ist\'s, was da zum Vorschein kommt,\" und sagte weiter: \"Das ist im ganzen Lande ihre Missetat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Da ward ein Deckel, bleiern, abgehoben, und mitten in der Tonne saß ein Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Er sprach: \"Das ist die Schlechtigkeit\" und stieß sie wieder in die Tonne und warf den bleiernen Deckel auf die Öffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Da schlug ich meine Augen wieder auf und schaute. Zwei Weiber wurden sichtbar, mit Wind in ihren Flügeln. Sie hatten nämlich gleich den Störchen Flügel; sie trugen zwischen Erd und Himmel die Tonne fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Ich sprach zum Engel, der mit mir redete: \"Wohin verbringen sie die Tonne?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Er sprach zu mir: \"Ihr baut man in dem Lande Sinear ein Haus. Ist\'s fertig, wird sie dort auf ihr Gestell gesetzt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Ich schlug aufs neue meine Augen auf und schaute; da zeigten sich vier Wagen zwischen den zwei Bergen; die Berge aber waren ehern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Am ersten Wagen waren rote Rosse, am zweiten schwarze,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'am dritten weiße, am vierten stark gescheckte Rosse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Da hob ich an und sprach zum Engel, der mit mir redete: \"Mein Herr, was sollen diese da?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Da hob der Engel an und sprach zu mir: \"Die ziehn hinaus nach den vier Himmelsrichtungen; sie holten sich zuvor beim Herrn der ganzen Welt Befehle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Der mit den schwarzen Rossen fährt zum Nordland hin; die weißen fahren nach dem Westen, die gescheckten in des Südens Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Und auch die roten wollten fahren, und sie versuchten auszufahren, um auf der Erde hin- und herzustreifen. Da sprach er: \'Auf! Durchzieht die Erde!\' Und nun durchzogen sie die Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Er aber rief mir zu und sprach zu mir: \'Die nach dem Nordland fahren, bringen in des Nordens Land den Geist des Herrn.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Das Wort des Herrn erging an mich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '\"Laß doch von den Verbannten dir, von Heldaj, von Tobia und Jedaja Gaben geben! Du selber geh! Am selben Tag noch geh in des Josias, des Sephanjasohnes, Wohnung, der eben angekommen ist aus Babel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Hol Gold und Silber! Laß eine Krone daraus fertigen! Und setze Josue, dem Sohn des Josadak, dem Hohenpriester, sie aufs Haupt und sprich zu ihm:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'So spricht der Herr der Heerscharen: \'Jetzt kommt ein Mann, der Sprosse heißt; aus seiner Tiefe nämlich sproßt er auf. Er baut das Heiligtum des Herren wieder auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Des Herren Heiligtum baut dieser und verlangt so selber königliche Würde. Er läßt sich auf dem Throne nieder und regiert. An seinem Throne steht ein Priester, und zwischen beiden herrscht ein friedlich Einvernehmen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Die Krone aber ist ein Zeichen der Erinnerung an Heldaj und Tobia und Jedaja und an die Freundlichkeit des Sohnes des Sephanja; sie bleibt im Heiligtum des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Dann kommen weit Entfernte und helfen an dem Heiligtum des Herren bauen. Da werdet ihr erkennen: Mich hat der Herr der Heerscharen zu euch gesandt. Und jenes wird geschehn, wenn ihr getreulich hört auf eures Herrn und Gottes Stimme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Im vierten Jahre des Königs Darius erging das Wort des Herrn an Zacharias, am vierten Tag des neunten Monds, im Kislev.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Man hatte nämlich in das Gotteshaus Sarezer abgesandt, den königlichen Aufseher, und seine Leute, den Herren zu begütigen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'und dann die Priester im Haus des Herrn der Heerscharen und die Propheten zu befragen: \"Soll ich im fünften Monat weiter weinen, Enthaltsamkeit noch weiter üben, wie ich getan schon viele Jahre?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Damit erging an mich das Wort des Herrn der Heerscharen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '\"Zum ganzen Landvolk sprich und zu den Priestern: \'Wenn ihr gefastet und geklagt im fünften und im siebten Mond, und zwar schon siebzig Jahre lang, habt ihr gefastet mir zu Nutzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Ja, wenn ihr esset, trinket, seid nicht dann ihr die Essenden und ihr die Trinkenden?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Hat nicht das gleiche schon der Herr verkünden lassen durch die früheren Propheten, einst, als Jerusalem noch stand und es ihm wohl erging mit seinen Städten ringsumher und noch bewohnt der Süden und die Niederung gewesen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Das Wort des Herrn erging an Zacharias weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'So sprach der Herr der Heerscharen: \"Gerechte Richtersprüche fällt! Ein jeder zeige seinem Bruder Liebe und Erbarmen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Bedränget Witwen nicht und nicht Verwaiste, nicht Fremdlinge, nicht Arme! Und keiner sinne Böses gegen seinen Bruder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Sie aber weigerten sich, aufzumerken, und machten ihre Nacken widerspenstig, verhärteten dazu die Ohren, daß sie nimmer hörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Zu einem Diamanten machten sie ihr Herz. Sie hörten nicht auf das Gesetz und auf die Worte, die der Herr der Heerscharen durch seinen Geist einst durch die früheren Propheten ausgesprochen. Darob erhob sich großer Zorn vom Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Und es geschah: Wie er gerufen, sie jedoch nicht hören wollten, da sprach der Herr der Heerscharen: \"So mögen sie nur rufen: Doch ich höre nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Zerstreun will ich sie unter alle Heidenvölker, die sie nicht kennen. Nach ihrem Abzug soll das Land so öde werden, daß niemand es zum Hin- und Herweg mehr benützt.\" So machten sie ein herrlich Land zur Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Und es erging das Wort des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'So sprach der Herr der Heerscharen: \"Ich habe Sion lieb mit großer, eifersüchtiger Liebe; ich liebe es mit großer Wärme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So sprach der Herr der Heerscharen: \"Nach Sion kehr ich wieder heim und wohne mitten in Jerusalem. Jerusalem heißt \'Treue Stadt\', der Berg des Herrn der Heerscharen heißt \'Heiliger Berg\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So sprach der Herr der Heerscharen: \"Im Greisenalter sitzen künftighin auf allen Plätzen von Jerusalem die Männer und die Weiber, ein jedes um der Last der Jahre willen mit dem Stabe in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Die Plätze in der Stadt sind angefüllt mit Knaben und mit Mädchen, die auf den Plätzen spielen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So sprach der Herr der Heerscharen: \"Dies dünkt dem Reste dieses Volks in diesen Tagen ganz unmöglich. Sollt es auch mir unmöglich dünken?\" Ein Spruch des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So sprach der Herr der Heerscharen: \"Ich helfe meinem Volk heraus aus Ost- und Westlanden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'und bringe sie auch heim, daß sie, Jerusalem bewohnend, mir zum Volke seien. Und ich bin ihnen Gott in Treue und Gerechtigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So sprach, der Herr der Heerscharen: \"Regt rüstig eure Hände, die ihr in diesen Tagen jene Worte hört aus der Propheten Mund, die von dem Tage reden, da das Haus des Herrn der Heerscharen, der Tempel, zum Wiederaufbau hergestellt sein wird!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Vor jenen Tagen gab es keinen Lohn für irgend jemanden und keinen Lohn fürs Vieh. Wer aus- und einzog, war vorm Feind nicht sicher; ich hetzte alle Leute durcheinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Jetzt aber stehe ich ganz anders als in frühern Zeiten zu des Volkes Rest.\" Ein Spruch des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '\"Des Friedens Frucht wird sein: Es trägt der Weinstock seine Frucht; die Erde liefert ihre Ernte, der Himmel seinen Tau. Dies alles gebe ich dem Reste dieses Volks zu eigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Und so wie ihr, du Haus von Juda und von Israel, den Heiden einst zum Fluch gedient, so helfe ich auch euch, daß ihr zum Segensbeispiel werdet. Habt keine Furcht! Regt rüstig eure Hände!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Denn also spricht der Herr der Heerscharen: \"Wie ich beschließen mußte, Übles euch zu tun, weil eure Väter mich erzürnten\", so spricht der Herr der Heerscharen, \"und ich mich\'s nicht gereuen ließ,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'so faßte ich in diesen Tagen wieder den Beschluß, dem Haus Jerusalem und Juda Gutes zu erweisen. Habt also keine Furcht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Nur müßt ihr dieses tun! Aufrichtig rede jeder mit dem andern! Und richtet ehrlich nach Gerechtigkeit! Und gleicht euch gütlich aus in euren Toren!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Nichts Böses sinne einer wider seinen Bruder! Nicht liebet lügenhaftes Schwören! Denn all dies ist mir grundverhaßt.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Und dann erging das Wort des Herrn an mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'So spricht der Herr der Heerscharen: \"Die Fasttage im vierten, fünften, siebten, zehnten Mond, die sollen jetzt dem Judahaus zur Freude und zum Jubel werden, zu frohen Festgezeiten! Doch liebt die Wahrheit und den Frieden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So spricht der Herr der Heerscharen: \"Noch kommen Völker und die Bewohner großer Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Der einen Stadt Bewohner ziehen hin zur anderen und rufen: \'Laßt uns zusammen gehen, vor dem Herrn die Andacht zu verrichten und dann den Herrn der Heerscharen zu fragen. Auch ich wallfahre hin.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'So kommen große Nationen, viele Heidenvölker, und fragen zu Jerusalem den Herrn der Heerscharen und sie verrichten ihre Andacht vor dem Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So Spricht der Herr der Heerscharen: \"In jenen Tagen hängen sich zehn Männer aus allen Heidensprachen an eines Juden Kleiderzipfel mit den Worten: \'Wir wollen mit euch ziehn; wir hören: Gott ist jetzt mit euch.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Weissagung, des Herren Wort über Hadrachland und seine Residenz Damaskus. Das Eigentum des Herrn wird Arams Auge, wie alle Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Auch Hamat, das angrenzt, mitsamt dem einen Sidon, weil es mit ihm verbündet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Und baute Tyrus sich auch eine Feste und häufte Silber auf wie Staub und Gold wie Gassenkot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'so nimmt der Herr es dennoch ein und wirft sein Bollwerk in das Meer. Es selber wird vom Feuer aufgezehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Dann sieht dies Askalon und fürchtet sich, und Gaza bebt im Innersten, auch Akkaron; denn seine Hoffnung ward zuschanden. Fort muß der Rat aus Gaza, und Askalon bleibt unbewohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'In Asdod siedeln Mischlinge. \"Ich rotte aus den Adel aus Philisterland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Ich reiße ihm aus seinem Maul sein blutig Fleisch, aus seinen Zähnen seinen Greuelfraß.\" Wer dann noch übrigbleibt, wird unserm Gott gehören. Er wird geachtet wie ein Fürst aus Juda; der Mann aus Akkaron ist wie ein Jebusiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, '\"Ich laß bei meinem Hause einen Posten lagern, daß niemand kommt und geht; kein Zwingherr darf es weiter überfallen. Ich habe jetzt sein Elend angesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Du Sionstochter, juble laut! Frohlocke, Tochter du Jerusalem! Dein König kommt zu dir, gerecht und sieghaft, sanftmütig und auf einem Esel reitend, dem Füllen einer Eselin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, '\"Kriegswagen lasse ich aus Ephraim verschwinden, Streitrosse aus Jerusalem; Kriegsbogen werden fortgeschafft.\" Denn Frieden wird den Heiden er gebieten; von einem Meer zum andern wird er herrschen, vom Strom bis zu der Erde Enden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, '\"Ja, wegen deines Bundesbluts befreie ich auch die Gefangnen aus der wasserleeren Grube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Zurück zur festen Burg, die ihr in Fesseln Hoffnung hegtet! Ich kündige es heute an: Ich will dir Doppeltes ersetzen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'denn als gespannten Bogen brauche ich jetzt Juda, als gefüllten Köcher Ephraim. Aufbieten will ich, Sion, deine Söhne zu dem Kampfe mit den Griechensöhnen, und will mich deiner jetzt bedienen als eines Kriegerschwertes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Der Herr kommt über sie, und gleich dem Blitze fährt sein Pfeil dahin. Der Herr, der Herr, stößt in das Lärmhorn jetzt und schreitet in des Südlands Stürmen her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Der Herr der Heerscharen wird sie mit Schmach bedecken, Schleudersteine werden sie aufreiben und damiederwerfen. Daliegen sie gleichwie vom Wein betrunken und seufzen auf das schrecklichste. Sie stöhnen auf vor Wut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'An jenem Tag leistet ihnen Hilfe nur der Herr, ihr Gott, wie einer Herde seinem Volk. In seinem Lande wachsen fromme Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Wie groß ist seine Huld und Güte! Getreide läßt er scheffelweise wachsen, eimerweise Wein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Fleht an den Herrn um Regen in der Frühlingszeit, den Herrn, der Blitzesstrahlen schaffen kann! Ein reicher Regen bringt für Mensch und alles andere im Felde Kräuter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Die Teraphim vertrösten nur mit leeren Worten. Wahrsager haben trügende Gesichte, erzählen falsche Träume und spenden windigen Trost. Deswegen schweifen sie den Schafen gleich umher und gehen ohne Hirten in die Irre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, '\"Den Hirten lodert meine Zornesglut entgegen; Ich such die Böcke heim.\" - Jetzt aber sucht der Herr der Heerscharen selbst seine Herde heim, das Judahaus, und er bedient sich seiner im Kampf als seines edlen Rosses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Ihm entstammen die Obersten der Anführer, ihm auch die Unterführer, ihm die Bogenschützen für den Kampf. Aus ihm gehn lauter Angriffslustige hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Sie werden Helden dann im Krieg bis in den Kot der Gasse niederstampfen, und sie bestehen Kämpfe, weil der Herr mit ihnen ist; zuschanden machen sie die Rossereiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, '\"Ich mache stark das Judahaus und helfe auf dem Josephshaus und nehme wiederum sie auf. Ich liebe sie. Sie werden sein, als hätte ich sie nie verstoßen. Ich selbst, der Herr, bin ja ihr Gott, und ich erfülle ihre Wünsche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Wie Helden sind dann die von Ephraim; ihr Herz wird frohen Mutes, wie von Wein. Und ihre Söhne schauen dies mit Herzensfreude und im Herrn frohlockend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, '\"Ich pfeife sie herbei und sammle sie; ich habe sie erlöst. Sie sollen zahlreich werden, wie sie einst waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Ich habe unter Völker sie zerstreut; in fernen Landen aber denken sie an mich. Sie kehren mit den Kindern lebend heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Ich bringe sie aus dem Ägypterland zurück und sammle aus Assyrien sie. Ich fahre sie ins Land von Gilead und an den Libanon. Das aber reicht für sie nicht hin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Dann schreitet er durch ein gefährlich Meer und schlägt im Meer die Wellen nieder. Vertrocknen werden alle Nilestiefen; das stolze Assur wird gestürzt; Ägyptens Zepter schwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, '\"Ich lasse sie an Zahl anwachsen. Sie triumphieren in dem Herrn und seinem Namen.\" Ein Spruch des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Schließ deine Pforten auf, o Libanon, daß Feuer deine Zedern fresse!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Zypresse heule! Die Zeder ist gefallen; die starken Fichten sind vernichtet. Ihr Basanseichen weint! Gefallen ist der Wald, der undurchdringliche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Horch! Hirten jammern; ihre Herde ist vernichtet. Horch! Junge Löwen brüllen; des Jordans Pracht dahin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'So sprach der Herr, mein Gott: \"Schlachtschafe weide,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'deren Käufer sie bedenkenlos abschlachten, von denen ihr Verkäufer spricht: \'Gepriesen sei der Herr! Ich bin jetzt überreich\', und deren Züchter sie nicht schonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Ich habe selber keine Nachsicht mehr mit den Bewohnern dieses Landes\", ein Spruch des Herrn, \"ich gebe jeden preis, den einen in des anderen Gewalt, dazu in seines Königs Hand. So richten sie dies Land zugrunde: Aus ihrer Hand befrei ich keinen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'So weidete ich diese Schlachtschafe für Schafhändler. Zwei Stäbe nahm ich mir dazu. Den einen hieß ich \"Huld\", den anderen \"Verbindung\" und weidete die Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Doch da bemerkte ich, daß sie noch mager blieben. Da ward ich ihrer überdrüssig; auch sie bekamen Widerwillen gegen mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Da sagte ich: \"Ich mag euch nicht mehr weiden. Was sterben will, das sterbe, und was zugrunde gehen will, das geh zugrunde. Was dann noch übrig, möge gegenseitig sich auffressen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Dann nahm ich meinen Stab \"die Huld\" und brach ihn ganz und gar in Stücke, um aufzuheben den Vertrag, den ich mit all den Leuten abgeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Er ward an jenem Tage aufgehoben. Da konnten diese Schafhändler erkennen, wenn sie nur auf mich achteten, daß es ein Herrenwort gewesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Ich sprach zu ihnen: \"Beliebt es euch, so gebt mir meinen Lohn! Wenn nicht, dann lasset es!\" Sie wogen dreißig Silberlinge mir zum Lohne dar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Da sprach der Herr zu mir: \"Zu Füßen wirf ihn hin dem Schatzmeister, den wundervollen Preis, den ich bei ihnen gelte!\" Ich nahm die dreißig Silberlinge und warf sie hin dem Schatzmeister im Haus des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Dann brach ich meinen zweiten Stab entzwei, den \"der Verbindung\", um aufzuheben die Verbrüderung, die zwischen Juda und Jerusalem bestand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Da sprach nochmals der Herr zu mir: \"Schaff die Ausrüstung eines ungeschickten Hirten an!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Ich stelle ja in diesem Lande einen Hirten an, der sich um das Zugrundegehende nicht kümmert und das Verlaufene nicht sucht und das Verwundete nicht heilt, das Heile auch nicht pflegt, vielmehr der Fetten Fleisch verzehrt und selbst noch an den Klauen nagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Weh diesem ungeschickten Hirten, der seine Herde läßt im Stich! Sein Arm samt seinem guten Auge welk ihm hin! Sein Arm verdorre! Sein gutes Auge soll erblinden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Der Ausspruch eines Herrenwortes Israel betreffend, ein Spruch des Herren, der den Himmel ausgebreitet und die Erde gründet, des Menschen Geist in seinem Innern bildet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '\"Zu einem Taumelkelche mache ich Jerusalem für alle Völker ringsumher. Auch über Juda kommt es bei Jerusalems Belagerung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'An jenem Tage mach ich einen Stein zum Heben aus Jerusalem für alle Völker. Verwunden wird sich jeder, der ihn heben will, und dennoch sammeln sich dagegen alle Heidenvölker auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'An jenem Tag\", ein Spruch des Herrn, \"da schlage ich mit Scheu ein jedes Roß, mit Wahnsinn seinen Reiter. Des Judahauses Augen öffne ich; mit Blindheit aber schlage ich ein jeglich Roß der Völker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Dann sprechen die Geschlechter Judas so bei sich: \'Jerusalems Bewohner sind siegreich durch den Herrn der Heerscharen, durch ihren Gott.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'An jenem Tage mach ich die Geschlechter Judas zu einem Feuerherd in einem Holzstoß, zu einer Feuerfackel unter Garben. Sie fressen alle Völker ringsumher zur Rechten und zur Linken. Doch sicher bleibt Jerusalem an seiner Stelle zu Jerusalem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Erst hilft der Herr den Zelten Judas auf, daß nicht zu groß der Ruhm des Davidshauses werde, und nicht der Ruhm der Einwohner Jerusalems den Judas übertreffe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'An jenem Tage schirmt der Herr die Einwohner Jerusalems. An jenem Tage ist der Schwächste unter ihnen David gleich und Davids Haus ein göttlich Wesen, wie des Herren Engel im Vergleich zu ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, '\"Anjenem Tage tracht ich, alle Heiden zu vernichten, die Jerusalem bekriegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Zuvor jedoch gieß ich aufs Davidshaus und alle. Einwohner Jerusalems den Geist des Mitleids und Erbarmens aus. Sie blicken dann auf den, den man durchbohrt, und sie betrauern ihn, wie man den einzigen Sohn betrauert, und weinen bitterlich um ihn, wie man den Erstgeborenen beweint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Ein großes Klagen tönt an jenem Tage aus Jerusalem, so groß wie über Hadadrimmon in Megiddos Tal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Geschlechterweise trauert ja das Land für sich, so das Geschlecht des Davidshauses für sich, auch seine Frau\'n für sich, so das Geschlecht des Natanshauses für sich und seine Frau\'n für sich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'so das Geschlecht des Levihauses für sich und seine Frau\'n für sich, so das Geschlecht der Simeïten für sich und seine Frau\'n für sich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'und alle übrigen Geschlechter, jegliches Geschlecht für sich und seine Frau\'n für sich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, '\"An jenem Tag wird eine Quelle für das Davidshaus und die Bewohner von Jerusalem entspringen als Mittel wider Sündenschuld und Unreinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'An jenem Tag wird es geschehn\", ein Spruch des Herrn der Heerscharen, \"da rotte ich der Götzen Namen aus dem Land, daß ihrer nimmer wird gedacht. Und aus dem Lande jage ich auch die Propheten samt dem Geist der Unreinheit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Und tritt dann einer noch als Seher auf, dann sagt zu ihm der Vater und die Mutter, die eignen Eltern: \"Du darfst nicht leben bleiben; du redest in des Herren Namen Lügen.\" Sogar der Vater und die Mutter, seine eignen Eltern, nageln ihn dann an, wenn er den Seher machen will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'An jenem Tage schämen sich die Seher, ein jeder des Gesichts, durch das er den Propheten machen will, und keiner legt mehr einen här\'nen Mantel an, um zu betrügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Ein jeder sagt: \"Ich bin kein Seher; ein Ackersmann bin ich; von Jugend auf stammt aus dem Ackerboden mein Erwerb.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Und fragt man ihn: \"Woher dann diese Wunden zwischen deinen Armen?\", erwidert er: \"Die holte ich mir doch in meiner Freunde Haus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, '\"Du Schwert! Auf gegen meinen Hirten und gegen den, mit dem ich übereingekommen!\" Ein Spruch des Herrn der Heerscharen. \"Den Hirten schlag! Alsdann zerstieben auch die Schafe. Ich strecke aus die Hand auch gegen diese Minderwertigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Im ganzen Lande werden\", ein Spruch des Herrn, \"zwei Drittel weggerafft zum Tode, ein Drittel bleibt darin noch übrig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Ins Feuer bringe ich auch dieses Drittel und läutere es so, wie man das Silber läutert, erprobe es, wie man das Gold erprobt, und ruft\'s nur meinen Namen an, alsdann erhör ich es. \'Dies\', sage ich, \'dies ist mein Volk\', und dieses sagt: \'Du Herr, Du bist mein Gott\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Ein Tag kommt für den Herrn; da wird in deiner Mitte Beute ausgeteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, '\"Ich hole alle Heiden her zum Kampfe gen Jerusalem, und eingenommen wird die Stadt und ausgeplündert ihre Häuser, entehrt die Weiber. Muß auch die halbe Stadt ins Elend wandern, wird doch ein Rest des Volkes nicht aus dieser Stadt vertrieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Der Herr wird ausziehen zum Kampf mit jenen Heidenvölkern, wie er einst am Tag der Schlacht gestritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Und stehen seine Füße jenes Tages auf dem Ölberg, der vor Jerusalem gen Osten liegt, so trennt der Ölberg sich in seiner Mitte, nach Ost und West, zu einem großen Tal. Des Berges eine Hälfte fällt nach Norden, die andere nach Süden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Dann flieht ihr in der Berge Tal. Das Bergetal reicht bis zum Meer; ihr fliehet so, wie zu der Zeit der Erderschütterung ihr euch geflüchtet habt, zur Zeit des Judakönigs, des Ozias. So pflegt der Herr, mein Gott, zu kommen. Und alle Heiligen sind bei Dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'An jenem Tage gibt es keine Hitze, keinen Frost und keine Kälte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Das ist ein Tag ganz eigenartig; er gibt sich zu erkennen als das Eigentum des Herrn. Und nicht wird\'s Tag noch Nacht; am Abend ist\'s noch hell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'An jenem Tag strömt von Jerusalem lebendiges Wasser; zur einen Hälfte fließt es ostwärts hin zum Meer, zur andern nach dem Meer im Westen. Im Sommer und im Winter fließt es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Der Herr ist König auf der ganzen Erde; an jenem Tage ist der Herr der einzige, und \"Einziger\" sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Das ganze Land verwandelt sich zur Niederung von Geba bis nach Rimmon hin im Süden von Jerusalem. Und dies wohnt hoch auf seiner Stätte, wohl besiedelt. Vom Tore Benjamins bis zu dem früheren Tor, bis zu dem Ecktor hin, vom Turme Chananels bis zu den Königskeltern wohnt man drin,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'nicht mehr vom Untergang bedroht; im Sichern wohnt Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Dies wird die Strafe sein, mit der der Herr die Völker alle schlägt, die gen Jerusalem zu Felde ziehn: Ihr Leib wird faulen, während sie noch auf den Füßen stehen, und in den Augenhöhlen faulen ihre Augen, im Munde ihre Zunge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'An jenem Tag kommt über sie ein ganz gewaltiger Herrenschrecken, daß dieser Hand an jenen und an diesen jener legt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Da kämpft mit Juda selbst Jerusalem. Da wird der Reichtum aller Heiden ringsumher gesammelt, Gold, Silber und Gewänder überreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Die gleiche Plage trifft die Rosse, Maultiere und Kamele, die Esel und das andere Vieh, das sich in jenen Landen dort befindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Doch wer von all den Heiden übrigbleibt, die gen Jerusalem gezogen, der wird von Jahr zu Jahr wallfahren, um dort den Herrn der Heerscharen, den König, anzubeten, das Laubhüttenfest zu feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Doch wer von den Familien der Erde nicht wallfahrt nach Jerusalem, um dort den Herrn der Heerscharen, den König, anzubeten, dem fällt kein Regen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Und pilgerte Ägyptens Volksstamm nicht und stellte er sich dort nicht ein, so träfe ihn die gleiche Plage, mit der der Herr die Heiden alle schlägt, weil er zur Feier des Laubhüttenfestes nicht wallfahrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Dies wird Ägyptens Strafe sein, die Strafe aller Heidenvölker, weil es zur Feier des Laubhüttenfestes nicht wallfahrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'An jenem Tag steht auf den Rosseglöckchen: \"Dem Herrn geweiht\". Die Wagen gelten in dem Haus des Herrn soviel wie vorm Altar die Opferschale.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Ein jeder Topf ist in Jerusalem und Juda jetzt dem Herrn der Heerscharen geweiht. Und wer da opfern will, der kommt und nimmt sich einen solchen weg und kocht darin. An jenem Tage gibt es keinen Händler mehr im Haus des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Der Ausspruch eines Herrenworts an Israel durch Malachias:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '\"Ich liebe euch.\" So spricht der Herr. \"Ihr aber fragt: \'Wodurch zeigst du uns Liebe?\' Ja, war nicht Esau Jakobs Bruder?\" Ein Spruch des Herrn. \"Ich aber zeigte gegen Jakob Liebe, gegen Esau keine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ich habe seine Berge öd gemacht, sein Eigentum zu Wüsteneien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Und spräche Edom: \'Wir sind vernichtet; doch bauen wir Zerstörtes wieder auf\'\", so spricht der Herr der Heerscharen: \"Und wenn sie bauen, reiße ich es wieder ein; \'Verruchtes Land\' wird man es nennen. \'Das Volk, dem ewig grollt der Herr\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Und sehn dies eure Augen, so sprechet ihr: \'Der Herr ist groß, weit über Israels Gebiet hinaus.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ein Sohn ehrt seinen Vater und ein Diener seinen Herrn. Nun, bin ich wirklich Vater, wo bleibt denn meine Ehrung? Und bin ich Herr, wo bleibt vor mir die Ehrfurcht?\" So spricht der Herr der Heerscharen zu euch, ihr Priester: \"Ihr Verächter meines Namens, ihr fragt dabei: \'Wodurch denn haben wir verachtet Deinen Namen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Auf meinen Altar bringet ihr unreine Speise und fragt dabei: \'Wodurch denn haben wir Dich eigentlich gering behandelt?\' Durch eure Reden: \'Der Tisch des Herrn ist nicht so vornehm.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Wenn ihr ein blindes Vieh zum Opfern bringt, ist das nichts Schlimmes? Bringt ihr ein lahmes oder krankes dar, ist das nichts Schlimmes? Bring solches deinem Statthalter, ob er dich freundlich aufnähme, ob er dich gnädiglich empfinge?\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '\"Nun sprechet ihr: \'Fleht doch zu Gott, daß er uns gnädig sei!\' Von eurer Hand geschah ja solches, und da soll er euch freundlich sein?\" So spricht der Herr der Heerscharen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '\"Ach, schlösse jemand unter euch die Türen, damit ihr nicht umsonst mein Altarfeuer zündet! Es liegt mir nichts an euch\", so spricht der Herr der Heerscharen. \"Geschenke will ich nicht aus eurer Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Vom Sonnenaufgang bis zum Niedergang ist groß mein Name bei den Heiden. So wird an jedem Orte meinem Namen dargebracht ein Räucherwerk, ein reines Speiseopfer. Groß ist mein Name bei den Heiden.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, '\"Doch ihr entweihet ihn; denn ihr sagt: \'Der Tisch des Herrn ist minderwertig. Was von ihm kommt, ist schlechte Speise.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Ihr sagt: \'Wozu solch lästige Pflicht?\' Ihr schätzet ihn gering\", so spricht der Herr der Heerscharen, \"und opfert, was zerrissen, lahm und krank, und opfert gleiches Speiseopfer. Ja, sollte mir denn solcherlei aus eurer Hand gefallen?\" So spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, '\"Verflucht sei der Betrüger, der ein gesundes Tier in seiner Herde hat und es gelobt und dann dem Herrn ein minderwertiges opfert. Ein großer König bin ich doch\", so spricht der Herr der Heerscharen, \"und bei den Heiden ist mein Name hochverehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Und nun ergeht an euch, ihr Priester, folgender Beschluß:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, '\"Gehorcht ihr nicht und nehmet ihr es nicht zu Herzen, meinem Namen Ehre zu erweisen\", so spricht der Herr der Heerscharen, \"dann sende ich den Fluch auf euch, verfluche euere Geschenke. Ja, ich verfluche sie, weil ihr es nicht zu Herzen nehmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Fürwahr, ich werde euch die Saat beschreien und Unrat ins Gesicht euch schleudern, den Unrat eurer Festesopfer. Man schafft euch selbst mit ihm hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Dann werdet ihr erkennen, daß ich selbst die Weisung euch gesandt, mein Bund mit Levi soll bestehen bleiben.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, '\"Mein Bund hat Heil und Leben ihm bedeutet. Dies gab ich ihm; mir zollte er dagegen Ehrfurcht und beugte sich vor meinem Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Der Wahrheit Lehre war in seinem Mund, kein Falsch auf seinen Lippen. Er wandelte mit mir unsträflich und gerade und brachte viele von der Sünde ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Man hängt ja an des Priesters Lippen; aus seinem Mund sucht man Belehrung, Unterweisung. Bote ist er des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ihr aber seid vom Wege abgewichen, habt viele im Gesetz zu Fall gebracht und habt den Bund mit den Leviten aufgelöst.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '\"Drum habe ich euch selbst verachtet und geringschätzig gemacht beim ganzen Volk, weil ihr an meine Wege euch nicht haltet und nicht um das Gesetz euch kümmert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, '\'Ach, haben wir nicht alle einen Vater? Hat denn nicht ein Gott uns erschaffen? Warum ist einer zu dem andern ohne Treu gewesen, daß er den Bund verletzte eurer Väter?\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda begehet Treubruch, Greuel werden zu Jerusalem verübt wie einst in Israel. Des Herren Heiligtum, das er so liebt, entheiligt Juda, weil es mit Töchtern fremder Götter sich vermählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Der Herr vertilge jeden, der dies tut, den Lehrer wie den Schüler aus den Zelten Jakobs, und brächte selbst er Opfer dar dem Herrn der Heerscharen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Und zweitens tut ihr dies: Ihr laßt des Herrn Altar mit Tränen überschwemmen, mit Weinen und mit Schluchzen, wenn er sich nicht mehr zu den Opfern wendet und nichts aus eurer Hand mit Wohlgefallen nimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Ihr fragt: \"Warum?\" Der Herr ist Zeuge zwischen dir und deiner Jugend Weib, das treulos du verlassen hast, obwohl sie dir Gefährtin war, dein angetrautes Eheweib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, '\"Hat\'s nicht der Eine auch getan beim letzten Rest von Leidenschaft?\" Was soll\'s mit diesem Einen? Er trachtete nach Gottes Stamm; ihr aber hegt nur eure Leidenschaft. So handle doch nicht treulos an dem Weibe deiner Jugend!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, '\"Wer haßt, entlasse!\" So sprach der Herr, Gott Israels: \"So decke man an seinem Kleide Flecken zu!\" So spricht der Herr der Heerscharen: \"Ihr hegt nur eure Leidenschaft; doch dürft ihr nimmer treulos handeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Den Herrn belästigt ihr mit euren Reden. Ihr fragt: \"Wieso belästigen wir ihn?\" Dadurch, daß ihr gesprochen habt: \"Wer Böses tut, gefällt dem Herrn. An solchen hat er seine Freude.\" - \"Wo bleibt nur der gerechte Gott?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '\"Ich sende meinen Boten schon, um meinen Weg vor mir zu ebnen. Ganz unvermutet kommt der Herr in seinen Tempel. Er, den ihr vermißt. Dazu des Bundes Bote, dem ihr entgegenharrt. Er kommt\", so spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Wer hält ihn aus, den Tag, an dem er kommt? Wer kann bestehn, wenn er erscheint? Er gleicht dem Feuer eines Schmelzofens und gleicht der Wäscherlauge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Und die sonst Silber läutert und es reinigt, wird jetzt die Levisöhne reinigen und läutern wie Gold und Silber. So hat der Herr nur solche, die Speiseopfer bringen in Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Dem Herrn gefallen abermals die Speiseopfer Judas und Jerusalems wie einst in alten Tagen, in längst vergangenen Jahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, '\"Ich trete zum Gericht an euch heran; ein schneller Kläger werde ich für Mädchenjäger und für Ehebrecher und für die, die falsche Eide schwören und die entziehn dem Tagelöhner seinen Lohn, die Witwen, Waisen, Fremdlinge bedrücken und keine Ehrfurcht vor mir haben.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, '\"Ja, ich, der Herr, ich habe niemals mich geändert, und ihr habt auch nicht aufgehört, des Jakobs Söhne immer noch zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Seit eurer Väter Tagen seid ihr von meinen Satzungen gewichen und habt sie nicht befolgt. Zu mir kehrt euch! Dann kehre ich mich auch zu euch.\" So spricht der Herr der Heerscharen. \"Ihr fragt: \'Weswegen müssen wir umkehren?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Darf denn ein Mensch wohl Gott berauben, daß ihr mich selbst beraubt? Ihr fragt: \'Wie haben wir Dich nur beraubt?\' In Zehnten und in Abgaben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Bei der Verkürzung ziehet ihr nur selbst den kürzeren, und doch beraubt ihr mich, das ganze Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Herbei mit allen Zehnten in das Vorratshaus, daß Zehrung sich in meinem Hause finde! Versucht\'s mit mir einmal auf diese Weise\", so spricht der Herr der Heerscharen, \"ob ich euch nicht des Himmels Fenster öffne und Segen über euch ergieße ohne Maß!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Der Freßheuschrecke wehre ich dann euretwegen, daß sie euch nicht des Bodens Frucht verderbe und daß der Weinstock auf dem Felde nicht zu eurem Schaden ohne Trauben bleibe.\" So spricht der Herr der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '\"Dann preisen euch die Heiden alle glücklich; ihr seid ja dann ein Land der Lust.\" So spricht der Herr der Heerscharen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '\"Ihr nehmt euch viel in euren Reden wider mich heraus\" So spricht der Herr: \"Ihr fragt: \'Was reden wir denn gegen Dich?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Ihr sagt: \'Umsonst ist\'s, Gott zu dienen. Was haben wir davon, daß seine Satzung wir befolgen, daß wir in Trauer wandeln vor dem Herrn der Heerscharen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nun preisen wir Vermeßne glücklich. Nur Lasterhaften geht es gut; sie stellen auf die Probe Gott und kommen ungestraft davon.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Dagegen sprechen so des Herrn Verehrer unter sich: \"Der Herr vernimmt es und behält es.\" In ein Gedächtnisbuch, das vor ihm liegt, wird eingeschrieben, was alle die betrifft, die vor dem Herrn sich fürchten und die vor seinem Namen Ehrfurcht haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '\"Sie werden mir\", so spricht der Herr der Heerscharen, \"am Tage, da ich einschreite, zum ganz besonderen Eigentum. Mit ihnen habe ich so Mitleid, wie jemand Mitleid hat mit seinem Sohne, der ihm dient.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Aufs neue werdet ihr den Unterschied erkennen, der zwischen fromm und gottvergessen ist, und zwischen dem, der Gott verehrt, und dem, der ihn nicht ehrt. \"Der Tag wird kommen, gleich einem Ofen flammt er auf. Die Frevler und die Missetäter all sind Stoppeln, und sie verzehrt der Tag, der kommt\", so spricht der Herr der Heerscharen. \"Von ihnen bleibt nicht Zweig noch Wurzel übrig. Euch aber, die ihr meinen Namen fürchtet, strahlt die Sonne der Gerechtigkeit, und Heilung liegt in ihren Strahlen. Ihr kommt hervor und hüpft wie Kälber aus dem Stalle, die Frevler zu zertreten. Sie werden unter euren Füßen Staub an jenem Tag, da ich erscheine.\" So spricht der Herr der Heerscharen. \"Gedenket also des Gesetzes Mosis, meines Dieners! Am Horeb gab ich für ganz Israel Gebote ihm und Satzungen. Ich sende euch Elias, den Propheten, zu. Bevor der Tag des Herrn erscheint, der große, schreckliche, bemüht er sich, das Herz der Väter für die Kinder, das Herz der Kinder für die Väter wiederzugewinnen. Sonst muß ich, wenn ich komme, das Land zum Untergang verdammen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Stammbaum Jesu Christi, des Sohnes Davids, des Sohnes Abrahams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Von Abraham stammt Isaak ab, von Isaak Jakob, von Jakob Juda und dessen Brüder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'von Juda und der Thamar Phares und Zara, von Phares Esron, von Esron Aram,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'von Aram Aminadab, von Aminadab Naasson, von Naasson Salmon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'von Salmon und der Rachab Booz, von Booz und der Ruth Obed, von Obed Jesse,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'von Jesse David, der König. Von David und des Urias Weib stammt Salomon,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'von Salomon Roboam, von Roboam Abias, von Abias Asa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'von Asa Josaphat, von Josaphat Joram, von Joram Ozias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'von Ozias Joatham, von Joatham Achas, von Achas Ezechias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'von Ezechias Manasses, von Manasses Amon, von Amon Josias,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'von Josias Jechonias und dessen Brüder zur Zeit der babylonischen Gefangenschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Nach der babylonischen Gefangenschaft ward Jechonias der Vater des Salathiel; von Salathiel stammt Zorobabel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'von Zorobabel Abiud, von Abiud Eliakim, von Eliakim Azor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'von Azor Sadok, von Sadok Achim, von Achim Eliud,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'von Eliud Eleazar, von Eleazar Matthan, von Matthan Jakob,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'von Jakob Joseph, der Mann Marias. Aus dieser ward Jesus geboren, der Christus genannt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Es sind demnach im ganzen von Abraham bis David 14 Geschlechter, von David bis zur babylonischen Gefangenschaft vierzehn Geschlechter, von der babylonischen Gefangenschaft bis auf Christus vierzehn Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Mit der Geburt Jesu Christi verhielt es sich also: Maria, seine Mutter, war mit Joseph verlobt. Da fand es sich, noch ehe sie zusammenwohnten, daß sie durch den Heiligen Geist empfangen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Indes Joseph, ihr Mann, war rechtlich denkend und wollte sie nicht bloßstellen, und so gedachte er, sie im stillen zu entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Noch trug er sich mit diesen Gedanken, siehe, da erschien ihm im Traum ein Engel des Herrn. Er sprach: \"Joseph, Sohn Davids, trage kein Bedenken, Maria, dein Weib, zu dir ins Haus zu nehmen; denn, was in ihr erzeugt ist, stammt vom Heiligen Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Sie wird einen Sohn gebären, dem du den Namen Jesus geben sollst; denn dieser wird sein Volk von seinen Sünden retten\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Dies alles aber ist geschehen, damit erfüllt werde, was von dem Herrn durch den Propheten gesprochen ward, wenn er sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '\"Siehe, die Jungfrau wird empfangen und einen Sohn gebären, und man wird ihn Emmanuel - d.h. \'Gott mit uns\' - heißen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Joseph stand auf vom Schlaf und tat, wie ihm der Engel des Herrn geboten hatte; er nahm sein Weib zu sich ins Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Jedoch erkannte er sie nicht, bis sie ein Kind (das Erstgeborene) geboren hatte; und er gab ihm den Namen Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Als Jesus in Bethlehem in Judäa geboren war in den Tagen des Königs Herodes, siehe, da erschienen Weise aus dem Morgenland in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Sie fragten: \"Wo ist der neugeborene König der Juden? Wir haben seinen Stern aufleuchten sehen und sind gekommen, um ihm zu huldigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Als der König Herodes dies hörte, geriet er in Erregung und ganz Jerusalem mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Er ließ alle Oberpriester und Schriftgelehrten des Volkes zusammenkommen und fragte sie aus, wo der Christus geboren werden solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Sie gaben ihm zur Antwort: \"Zu Bethlehem in Judäa. Denn also steht beim Propheten geschrieben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '\'Und du, Bethlehem im Lande Juda, bist keineswegs die geringste unter den Fürstenstädten Judas; denn aus dir wird der Fürst hervorgehen, der mein Volk Israel regieren soll\'\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Hiernach beschied Herodes die Weisen heimlich zu sich und suchte von ihnen genau die Zeit der Sternenerscheinung zu erfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Darauf wies er sie nach Bethlehem und sprach: \"Geht, suchet eifrig nach dem Kinde. Und sobald ihr es gefunden habt, sagt es mir, damit auch ich ihm dort huldige.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Als sie dies vom König vernommen hatten, machten sie sich auf den Weg. Und siehe, der Stern, den sie bei seinem Aufleuchten gesehen hatten, ging vor ihnen her, bis er über dem Orte stillstand, wo das Kind war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Als sie den Stern erblickten, ward ihre Freude übergroß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Sie traten in das Haus, sahen das Kind mit Maria, seiner Mutter, fielen nieder und huldigten ihm. Dann öffneten sie ihre Truhen und brachten ihm Geschenke dar: Gold, Weihrauch und Myrrhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'In einem Traumgesicht angewiesen, nicht mehr zu Herodes zu gehen, kehrten sie auf einem anderen Weg in ihre Heimat zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Als sie weggegangen waren, da erschien ein Engel des Herrn im Traum dem Joseph. Er sprach: \"Auf! Nimm das Kind und seine Mutter und fliehe nach Ägypten. Bleibe dort, bis ich es dir sage. Herodes fahndet nämlich nach dem Kind, um es zu töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Er stand auf; nahm das Kind und seine Mutter noch bei Nacht und zog nach Ägypten fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Dort blieb er bis nach dem Tode des Herodes. So sollte sich erfüllen, was von dem Herrn durch den Propheten gesprochen ward, wenn er sagt: \"Aus Ägypten habe ich meinen Sohn berufen.\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Herodes hatte indessen erkannt, daß er von den Weisen hintergangen worden sei. Er geriet in großen Zorn und ließ in Bethlehem und dessen ganzem Umkreis alle Knäblein töten, die zwei Jahre und jünger waren, genau der Zeit entsprechend, die er von den Weisen erforscht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'So wurde damals erfüllt, was durch Jeremias, den Propheten, gesprochen ward, wenn er sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '\"Zu Rama ward eine Stimme vernommen, ein Weinen und ein lautes Klagen: Rachel weint um ihre Kinder, sie will sich nicht trösten lassen, weil sie nicht mehr sind\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Als Herodes tot war, siehe, da erschien ein Engel des Herrn im Traum dem Joseph in Ägypten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'und sprach: \"Auf! Nimm das Kind und seine Mutter und zieh in das Land Israel. Denn die dem Kinde nach dem Leben strebten, sind gestorben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Er stand auf, nahm das Kind und seine Mutter und zog in das Land Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Doch als er hörte, daß Archelaus König in Judäa sei an Stelle seines Vaters Herodes, da fürchtete er sich, dorthin zu gehen. In einem Traumgesicht angewiesen, zog er in die Landschaft Galiläa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'wo er sich in einer Stadt mit Namen Nazareth niederließ. So sollte sich das Prophetenwort erfüllen: \"Er wird Nazaräer heißen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'In jenen Tagen trat Johannes der Täufer auf. Er predigte in der Steppe von Judäa');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'und sprach: \"Bekehret euch: das Himmelreich ist nahe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Ihn meint der Prophet Isaias da, wo er sagt: \"Eine Stimme ruft in der Steppe: Richtet her den Weg des Herrn, macht eben seine Pfade\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Dieser Johannes trug ein Kamelhaarkleid und um die Lenden einen Ledergürtel; seine Nahrung waren Heuschrecken und wilder Honig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Jerusalem zog zu ihm hinaus und ganz Judäa, sowie die ganze Jordansau.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Man ließ sich von ihm im Jordanfluß taufen und bekannte dabei seine Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Als er nun viele von den Pharisäern und den Sadduzäern sah, wie sie zu seinem Taufplatz kamen, sprach er zu ihnen: \"Ihr Schlangenbrut! Wer hat euch eingeredet, ihr würdet dem drohenden Strafgericht entrinnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Bringt also Frucht würdig der Bekehrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Glaubt ja nicht, daß ihr denken dürft: Wir haben Abraham zum Vater. Ich sage euch: Gott kann aus diesen Steinen da Kinder für Abraham erstehen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Schon liegt die Axt an der Wurzel der Bäume. Jeder Baum, der keine gute Frucht trägt, wird umgehauen und ins Feuer geworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ich taufe euch mit Wasser zur Bekehrung; er aber, der nach mir kommt, ist mächtiger als ich; ich bin nicht wert, ihm auch nur die Schuhe zu tragen. Er wird euch mit dem Heiligen Geist und mit Feuer taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Schon hat er seine Schaufel in der Hand; und er wird seine Tenne reinigen: Den Weizen wird er in seinen Speicher bringen, die Spreu jedoch verbrennen in einem unauslöschlichen Feuer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Damals kam Jesus von Galiläa her an den Jordan, um von ihm getauft zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Johannes aber wollte es ihm wehren; er sprach: \"Ich sollte doch von dir getauft werden, und du kommst zu mir?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Allein Jesus sprach zu ihm: \"Gib dich für jetzt zufrieden! Denn so gehört es sich für uns, all das zu erfüllen, was Rechtens ist.\" Da ließ er ihm den Willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Nach der Taufe stieg Jesus sogleich aus dem Wasser, und siehe, es öffneten sich ihm die Himmel: Er sah den Geist Gottes herniederschweben so wie eine Taube und auf ihn zukommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Und siehe, eine Stimme rief vom Himmel her: \"Dies ist mein geliebter Sohn; an ihm habe ich mein Wohlgefallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Darauf ward Jesus in die Einsamkeit geführt, um vom Teufel versucht zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Er hatte vierzig Tage und vierzig Nächte lang gefastet, und nun hungerte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Da trat der Versucher an ihn heran und sprach: \"Wenn du der Sohn Gottes bist, so sprich, daß diese Steine hier Brot werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Doch er gab ihm zur Antwort: \"Es steht geschrieben: \'Der Mensch lebt nicht vom Brot allein, sondern von jedem Worte, das aus dem Munde Gottes kommt\'\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Darauf entführte ihn der Teufel in die heilige Stadt und stellte ihn auf die Zinne des Tempels');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'und sprach zu ihm: \"Wenn du der Sohn Gottes bist, so stürze dich hinab. Denn also steht geschrieben: \'Seinen Engeln hat er deinethalben befohlen, und sie werden dich auf den Händen tragen, damit du nicht etwa deinen Fuß an einen Stein anstoßest.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Doch Jesus sprach zu ihm: \"Es steht nochmals geschrieben: \'Du sollst den Herrn, deinen Gott, nicht versuchen\'\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Nun entführte ihn der Teufel auf einen sehr hohen Berg, zeigte ihm alle Reiche der Welt und deren Herrlichkeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'und sprach zu ihm: \"All dies will ich dir geben, wenn du niederfällst und mich anbetest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Jetzt aber rief ihm Jesus zu: \"Hinweg, Satan! Es steht geschrieben: \'Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen\'\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Nun verließ ihn der Teufel, und siehe, Engel traten herzu und dienten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Als Jesus hörte, Johannes sei gefangengenommen, begab er sich nach Galiläa zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Er verließ jedoch Nazareth und ließ sich in Kapharnaum, das am Meer liegt, nieder, im Grenzgebiet von Zabulon und Nephtalim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'So sollte sich erfüllen, was der Prophet Isaias gesprochen, wenn er sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '\"Land Zabulon und Land Nephtalim, du Weg am Meer, jenseits des Jordans, Galiläa, Land der Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Das Volk, das im Finstern sitzt, sah ein großes Licht, und denen, die im Schattenland des Todes weilen, erschien ein Licht\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Und jetzt fing Jesus an zu predigen. \"Bekehret euch\", rief er, \"das Himmelreich ist nahe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Einst wanderte er am Meere von Galiläa entlang, als er zwei Brüder sah: den Simon, der auch Petrus heißt, und Andreas, dessen Bruder. Sie warfen eben ein Netz ins Meer: sie waren nämlich Fischer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Er sprach zu ihnen: \"Kommt! Folget mir! ich werde euch zu Menschenfischern machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Sofort ließen sie ihre Netze liegen und folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Als er von da weiterging, sah er zwei andere Brüder, den Jakobus, den Sohn des Zebedäus, und Johannes, dessen Bruder. Sie legten in ihrem Boote gerade ihre Netze zurecht mit ihrem Vater Zebedäus. Und er berief sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Auf der Stelle verließen sie das Boot und ihren Vater und folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Jesus zog durch ganz Galiläa hin. Er predigte in ihren Synagogen, verkündete die frohe Botschaft vom Reich und heilte alle Krankheiten und Plagen im Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Sein Ruf drang durch ganz Syrien hin; man brachte zu ihm alle, die an mancherlei Gebrechen litten und mit Krankheiten schwer belastet waren, besonders auch Besessene, Mondsüchtige, Gelähmte, und er heilte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Große Scharen folgten ihm aus Galiläa, der Dekapolis, Jerusalem, Judäa und aus der Gegend jenseits des Jordans.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Als er die Scharen sah, ging er auf einen Berg. Dort setzte er sich nieder, und seine Jünger traten zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Dann tat er seinen Mund auf, lehrte sie und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '\"Selig die Armen im Geiste; denn ihrer ist das Himmelreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Selig die Trauernden; denn sie werden getröstet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Selig die Sanftmütigen; denn sie werden das Land erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Selig, die hungern und dürsten nach der Gerechtigkeit; denn sie werden gesättigt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Selig die Barmherzigen; denn sie werden Barmherzigkeit erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Selig, die reinen Herzens sind; denn sie werden Gott schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Selig die Friedensstifter; denn sie werden Söhne Gottes heißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Selig, die Verfolgung leiden der Gerechtigkeit zulieb; denn ihrer ist das Himmelreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Selig seid ihr, wenn man euch schmäht und verfolgt und alles Schlechte in lügenhafter Weise wider euch aussagt um meinetwillen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Dann freuet euch und jubelt; denn groß ist euer Lohn in den Himmeln! So hat man schon vor euch die Propheten verfolgt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ihr seid das Salz der Erde. Wenn aber das Salz fade wird, womit soll man es salzen? Es ist zu nichts mehr zu gebrauchen; man wirft es eben weg, und es wird von den Leuten zertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ihr seid das Licht der Welt: Eine Stadt, die oben auf dem Berge liegt, kann nicht verborgen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Auch zündet man kein Licht an und stellt es unter den Scheffel, sondern auf den Leuchter. Dann leuchtet es allen im Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'So leuchte euer Licht vor den Menschen, damit sie eure guten Werke sehen und euern Vater preisen, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Denkt nicht, ich sei gekommen, das Gesetz oder die Propheten abzuschaffen. Ich komme nicht abzuschaffen, vielmehr zu vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Wahrlich, ich sage euch: Eher werden Himmel und Erde untergehen, als daß auch nur ein Jota oder Strichlein vom Gesetz vergeht, bevor nicht alles geschehen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Jedoch, wenn einer eines dieser kleineren Gebote nicht beachtet und so die Menschen lehrt, der wird als der Geringste im Himmelreich gelten. Nur wer sie hält und halten lehrt, der wird als Großer im Himmelreich gelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Nein, ich sage euch: Wenn eure Gerechtigkeit nicht weitaus besser ist als die der Schriftgelehrten und Pharisäer, so kommt ihr überhaupt nicht in das Himmelreich hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ihr habt gehört, daß zu den Alten gesprochen ward: \'Du sollst nicht töten\'; wer aber tötet, wird dem Gerichte verfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ich aber sage euch: Wer seinem Bruder zürnt, wird dem Gerichte verfallen. Wer seinen Bruder \'Raka\' schimpft, der wird dem Hohen Rate verfallen. Und wer ihn \'gottlos\' heißt, verfällt der Feuerhölle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Wenn du zum Beispiel deine Gabe zum Altare bringst, und dort fällt es dir ein, daß dein Bruder etwas gegen dich habe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'dann laß deine Gabe dort vor dem Altare liegen, geh hin, versöhne dich zuvor mit deinem Bruder, und dann erst magst du deine Gabe opfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Sei bereit, dich schnell mit deinem Gegner zu versöhnen, solange du mit ihm noch auf dem Wege bist. Es könnte sonst dein Gegner dich dem Richter übergeben, der Richter dem Kerkermeister, und du könntest in den Kerker geworfen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Wahrlich, ich sage dir: Du kämest sicher nicht von da heraus, bevor du nicht den letzten Pfennig bezahlt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ihr habt gehört, es ward gesagt: \'Du sollst nicht ehebrechen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ich aber sage euch: Jeder, der ein Weib auch nur begehrlich ansieht, hat in seinem Herzen schon Ehebruch mit ihr begangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Gibt dir dein rechtes Auge zur Sünde Anlaß, so reiß es aus und wirf es weg. Denn besser ist\'s für dich, eines deiner Glieder gehe zugrunde, als daß dein ganzer Leib in die Hölle geworfen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Gibt dir deine rechte Hand zur Sünde Anlaß, so haue sie ab und wirf sie weg. Denn besser ist\'s für dich, eines deiner Glieder gehe zugrunde, als daß dein ganzer Leib zur Hölle fahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Und weiter ward gesagt: \'Wer sein Weib entlassen will, der gebe ihr einen Scheidebrief!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ich aber sage euch: Jeder, der sein Weib entläßt -auch nicht im Falle des Ehebruchs- ist schuld, daß sie die Ehe bricht, und wer eine Entlassene heiratet, bricht die Ehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Und wieder habt ihr gehört, daß zu den Alten gesprochen ward: \'Du sollst keinen Meineid schwören\'; \'Du sollst dem Herrn halten, was du geschworen hast.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ich aber sage euch: Ihr sollt überhaupt nicht schwören, nicht bei dem Himmel; denn er ist der Thron Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Nicht bei der Erde; denn sie ist der Schemel seiner Füße, nicht bei Jerusalem; denn es ist die Stadt des großen Königs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Auch bei deinem Haupte sollst du nicht schwören; du kannst ja kein einziges Härchen weiß oder schwarz machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Ein einfaches Ja, ein einfaches Nein sei eure Rede. Was darüber ist, stammt vom Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ihr habt gehört, es ward gesagt: \'Aug` um Aug` und Zahn um Zahn.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ich aber sage euch: Leistet dem Bösen keinen Widerstand; vielmehr schlägt dich einer auf die rechte Wange, so halte ihm auch die andere hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Und wer dir vor Gericht den Rock abstreiten will, dem laß auch noch den Mantel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Wer dich zu einer Meile zwingt, mit dem geh zwei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Dem, der dich bittet, gib; wenn einer von dir borgen will, weise ihn nicht ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ihr habt gehört, es ward gesagt: \'Du sollst deinen Nächsten lieben\'; doch hassen magst du deinen Feind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ich aber sage euch: Liebet eure Feinde tut Gutes denen, die euch hassen und betet für die, die euch verfolgen und verleumden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'auf daß ihr Kinder eures Vaters werdet, der in den Himmeln ist. Er läßt ja seine Sonne aufgehen über Böse und Gute und läßt regnen über Gerechte und Ungerechte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Denn wolltet ihr nur jene lieben, die euch lieben, auf welchen Lohn könnt ihr dann Anspruch machen? Handeln denn nicht auch die Zöllner ebenso?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Und wolltet ihr nur eure Brüder grüßen, was tut ihr da besonderes? Handeln denn nicht auch die Heiden ebenso?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Ihr aber sollt vollkommen sein, wie euer himmlischer Vater vollkommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '\"Hütet euch, daß ihr eure Gerechtigkeit vor den Menschen übt, um euch vor ihnen zur Schau zu stellen. Ihr würdet sonst keinen Lohn erhalten von eurem Vater, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Gibst du also Almosen, posaune es nicht aus, wie es die Heuchler in den Synagogen und auf den Straßen machen, um von den Menschen Ruhm zu ernten. Wahrlich, ich sage euch: Sie haben ihren Lohn empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Sooft du also Almosen geben willst, soll deine Linke nicht wissen, was deine Rechte tut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'damit dein Almosen im Verborgenen bleibe. Und dein Vater, der ins Verborgene sieht, wird es dir vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Auch wenn ihr betet, sollt ihr es nicht machen wie die Heuchler. Sie beten am liebsten in den Synagogen und an den Straßenecken, um sich den Menschen zu zeigen. Wahrlich, ich sage euch: Sie haben ihren Lohn empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Sooft du also betest, geh in deine innerste Kammer, schließe noch die Türe zu und bete zu deinem Vater, der im Verborgenen ist. Und dein Vater, der ins Verborgene sieht, wird es dir vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Beim Beten sollt ihr auch nicht plappern wie die Heiden. Diese meinen nämlich, sie würden dann Erhörung finden, wenn sie recht viele Worte machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Macht es nicht so wie diese. Euer Vater weiß ja, was ihr braucht, noch bevor ihr ihn gebeten habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Ihr aber sollt also beten: \'Vater unser, der du bist im Himmel, geheiligt werde Dein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Zu uns komme Dein Reich. Dein Wille geschehe, wie im Himmel also auch auf Erden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Unser tägliches Brot gib uns heute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Vergib uns unsere Schuld, wie auch wir vergeben unsern Schuldigern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Und führe uns nicht in Versuchung, sondern erlöse uns von dem Übel.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Wenn ihr den Menschen ihre Fehler vergebt, so wird euer himmlischer Vater auch euch vergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Vergebet aber ihr den Menschen ihre Fehler nicht, so wird euch euer Vater eure Fehler nicht vergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Und wenn ihr Fasten haltet, so dürft ihr nicht trübselig erscheinen wie die Heuchler. Sie entstellen nämlich ihr Angesicht, damit die Menschen sehen, daß sie fasten. Wahrlich, ich sage euch: Sie haben ihren Lohn empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Du aber, wenn du fastest, salbe dein Haupt und wasche dein Gesicht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'damit die Menschen nicht merken, daß du fastest, vielmehr nur dein Vater, der im Verborgenen ist. Und dein Vater, der ins Verborgene sieht, wird es dir vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Häufet euch nicht Schätze an auf Erden, wo Motten und Nager sie vernichten, wo Diebe einbrechen und stehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Häuft euch Schätze an im Himmel, wo keine Motte und kein Nager sie vernichtet und wo keine Diebe einbrechen und sie stehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Denn wo dein Schatz ist, da ist auch dein Herz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Die Leuchte deines Leibes ist das Auge. Ist also dein Auge lauter, so wird dein ganzer Leib erleuchtet sein;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Ist dein Auge jedoch krank, dann wird dein ganzer Leib verfinstert sein. Ist aber das Licht in dir zur Finsternis geworden, wie groß muß diese Finsternis dann sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Niemand kann zwei Herren dienen; entweder haßt er den einen und liebt den anderen, oder er hält es mit dem einen und verachtet den anderen; ihr könnet nicht Gott dienen und dem Mammon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'So sage ich denn euch: Sorget nicht ängstlich für euer Leben, was ihr essen oder trinken sollet; auch nicht für euern Leib, womit ihr ihn bekleiden sollet. Ist denn das Leben nicht weit mehr wert als die Nahrung und der Leib mehr als die Kleidung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Schaut hin auf die Vögel des Himmels: Sie säen nicht, sie ernten nicht, sie sammeln nicht in Speicher, und doch ernährt sie euer himmlischer Vater. Seid ihr nicht viel mehr wert als sie?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Wer aus euch kann denn mit seinem Sorgen seine Lebenszeit auch nur um eine Elle verlängern?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Und was seid ihr um die Kleidung so besorgt? Betrachtet die Lilien des Feldes, wie sie wachsen; sie schaffen nicht, sie spinnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ich sage euch aber: Nicht einmal Salomon in seiner ganzen Herrlichkeit war so gekleidet wie eine einzige aus ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Wenn Gott das Gras des Feldes, das heute steht und schon morgen in den Ofen geworfen wird, also kleidet, um wieviel mehr dann euch, ihr Kleingläubigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'So sprechet also nicht in Sorgen: \'Was werden wir essen?\' Oder: \'Was werden wir trinken?\' Oder: \'Womit werden wir uns kleiden?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Um alles dies bekümmern sich die Heiden. Denn euer himmlischer Vater weiß wohl, daß ihr all das braucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Suchet vor allem das Reich Gottes und seine Gerechtigkeit, dann wird euch dies alles dazugegeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Sorgt also nicht ängstlich für morgen. Der morgige Tag wird für sich selber sorgen; genug, daß jeder Tag seine eigene Plage hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '\"Richtet nicht, damit ihr nicht gerichtet werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Denn wie ihr richtet, so werdet ihr gerichtet werden. Und mit dem Maße, womit ihr messet, wird euch zugemessen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Was siehst du zwar den Splitter im Auge deines Bruders; den Balken aber in deinem eigenen Auge siehst du nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Oder, wie kannst du zu deinem Bruder sagen: \'Laß mich den Splitter dir aus dem Auge ziehen\', und sieh, in deinem Auge steckt ein Balken!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Du Heuchler! Entferne zuerst den Balken aus deinem Auge, und dann erst magst du sehen, wie du den Splitter aus dem Auge deines Bruders ziehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Gebt das Heilige nicht den Hunden, und werfet eure Perlen nicht den Schweinen vor. Sie würden sie ja nur mit den Füßen zertreten, sich umwenden und euch zerreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bittet und es wird euch gegeben werden; sucht und ihr werdet finden; klopft an und es wird euch aufgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Denn jeder, der bittet, empfängt; wer sucht, der findet; wer anklopft, dem wird aufgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Oder ist etwa einer unter euch, der seinem Kinde, wenn es ihn um Brot bittet, einen Stein darreichen würde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Oder, wenn es um einen Fisch bittet, ihm eine Schlange geben würde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Wenn nun ihr, die ihr böse seid, euern Kindern doch gute Gaben zu geben wisset, um wieviel mehr wird euer Vater, der in den Himmeln ist, denen Gutes geben, die ihn bitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alles nun, was ihr wollt, daß euch die Menschen tun, das sollt auch ihr ihnen tun. Denn das ist das Gesetz und die Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Tretet ein durch die enge Pforte. Weit ist ja die Pforte und breit der Weg, der ins Verderben führt, und viele sind\'s, die auf ihm hineingehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Wie eng ist die Pforte, wie schmal der Weg, der zum Leben führt, und wenige sind es, die ihn finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Hütet euch vor den falschen Propheten. Sie kommen zu euch in Schafskleidern; inwendig aber sind sie reißende Wölfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'An ihren Früchten könnt ihr sie erkennen: Erntet man denn Trauben von den Dornen oder Feigen von den Disteln?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'So trägt jeder gute Baum gute Früchte, der schlechte Baum aber trägt schlechte Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ein guter Baum kann keine schlechten Früchte tragen, ein schlechter Baum wird keine guten Früchte bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Jeder Baum, der keine gute Frucht trägt, wird umgehauen und ins Feuer geworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Also, an ihren Früchten werdet ihr sie erkennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nicht jeder, der zu mir sagt: \'Herr, Herr!\' wird in das Reich der Himmel kommen, vielmehr wer den Willen meines Vaters tut, der in den Himmeln ist, wird ins Himmelreich eingehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Viele werden an jenem Tage zu mir sprechen: \'Herr, Herr, haben wir denn nicht in deinem Namen prophezeit, in deinem Namen Dämonen ausgetrieben, in deinem Namen viele Wunderzeichen gewirkt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Ich werde ihnen aber dann versichern: \'Ich habe euch niemals gekannt: hinweg von mir, ihr Übeltäter.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Jeder also, der diese meine Worte hört und nach ihnen handelt, ist einem klugen Manne gleich: Er hat sein Haus auf einen Felsen aufgebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Platzregen strömte nieder, die Fluten kamen, die Stürme brausten und tobten gegen jenes Haus, doch es fiel nicht ein; denn festgegründet stand es auf dem Felsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Jeder aber, der diese meine Worte hört und nicht nach ihnen handelt, ist einem törichten Manne gleich: Er hat sein Haus auf Sand gebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Platzregen strömte nieder, die Fluten kamen, die Stürme brausten und tobten gegen jenes Haus; es fiel ein und stürzte ganz zusammen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Als Jesus mit diesen Reden fertig war, da war die ganze Menge von seiner Rede hingerissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Er lehrte sie wie einer, der Vollmacht hat, und nicht wie ihre Schriftgelehrten und Pharisäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Jesus stieg vom Berge herab, und große Scharen folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Und siehe, ein Aussätziger kam heran und warf sich vor ihm nieder mit den Worten: \"Herr! Wenn du willst, kannst du mich rein machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Da streckte er die Hand aus, berührte ihn und sprach: \"Ich will, sei rein!\" Sofort war er von seinem Aussatze rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Und Jesus sprach zu ihm: \"Sag es ja niemand! Geh vielmehr hin, zeig dich dem Priester und opfere die Gabe, die Moses vorgeschrieben hat; sie mögen dies zum Zeugnis nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Dann ging er nach Kapharnaum hinein. Da trat ein Hauptmann zu ihm');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'mit der Bitte: \"Herr, mein Knecht liegt gelähmt zu Hause, er leidet fürchterliche Schmerzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Und Jesu sprach zu ihm: \"Ich gehe hin und heile ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Darauf erwiderte der Hauptmann: \"Herr, ich bin nicht würdig, daß du eingehst unter mein Dach. Doch sprich nur ein Wort, so wird mein Knecht gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Denn auch ich bin ein Untergebener, habe Soldaten unter mir. Wenn ich zu dem da sage: \'Geh!\' dann geht er; zu einem anderen: \'Komm!\' dann kommt er; und zu meinem Knechte: \'Tu dies!\' dann tut er es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Als Jesus dies hörte, mußte er sich wundern und sprach zu denen, die ihm folgten: \"Wahrlich, ich sage euch, solch einen Glauben habe ich bei niemand in Israel gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Doch sage ich euch: Viele werden von Osten und von Westen kommen und mit Abraham, Isaak und Jakob im Himmelreich zu Tische sitzen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Die Kinder des Reiches aber werden hinausgeworfen in die Finsternis draußen. Dort wird Heulen und Zähneknirschen sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Und zu dem Hauptmann sprach Jesus: \"Geh hin! Wie du geglaubt hast, soll dir geschehen.\" Und in derselben Stunde war der Knecht gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Dann kehrte Jesus im Hause des Petrus ein. Dort sah er dessen Schwiegermutter fieberkrank darniederliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Er nahm sie bei der Hand, und das Fieber wich von ihr. Sie stand auf und diente ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Als es Abend geworden war, brachte man viele Besessene zu ihm. Mit einem Worte trieb er die Geister aus und heilte alle Kranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'So sollte sich erfüllen, was der Prophet Isaias gesprochen hat, wenn er sagt: \"Er selbst nimmt unsere Schwachheiten auf sich, und er trägt die Krankheiten\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Da Jesus eine Menge Volkes um sich sah, befahl er, an das andere Ufer wegzufahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Da trat ein Schriftgelehrter vor und sprach zu ihm: \"Meister, ich will dir folgen, wohin du auch gehst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Doch Jesus sprach zu ihm: \"Die Füchse haben Höhlen, die Vögel des Himmels Nester; der Menschensohn jedoch hat keine Stätte, wohin er sein Haupt legen könnte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ein andrer seiner Jünger sprach zu ihm: \"Laß, Herr, mich zuvor nochmals gehen, um meinen Vater zu begraben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Doch Jesus sprach zu ihm: \"Folge mir; und laß die Toten ihre Toten begraben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Er stieg in ein Boot, und seine Jünger folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Und siehe, ein gewaltiger Sturm erhob sich auf dem Meere, so daß das Boot von den Wellen überflutet ward. Er aber schlief.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Da traten sie heran, weckten ihn und riefen: \"Herr! Hilf! Wir sind verloren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Er aber sprach zu ihnen: \"Was seid ihr denn so furchtsam, ihr Kleingläubigen?\" Alsdann erhob er sich, gebot den Winden und dem Meere, und es ward ganz still.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Da sprachen die Menschen voll Verwunderung: \"Wer ist doch dieser, daß ihm sogar die Winde und das Meer gehorchen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Er kam ans andere Ufer in das Land der Gadarener. Da liefen zwei Besessene ihm in den Weg; sie kamen aus den Gräbern und waren sehr bösartig, so daß es niemand wagen durfte, jenen Weg zu gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Sie schrien laut und sprachen: \"Was willst du von uns, Sohn Gottes? Bist du hierhergekommen, uns vor der Zeit zu quälen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Etwas entfernt von ihnen war eine große Schweineherde auf der Weide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Da baten ihn die Dämonen und sprachen: \"Wenn du uns austreibst, so schicke uns in die Schweineherde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Er sprach zu ihnen: \"Fahret hin!\" Sie fuhren aus und in die Schweine hinein, und siehe, die ganze Herde raste am Abhang hin ins Meer hinein; dort kamen sie im Wasser um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Die Hirten flohen und erzählten alles in der Stadt, auch den Vorfall mit den Besessenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Siehe, da zog die ganze Stadt hinaus, Jesus entgegen. Und als sie ihn erblickten, baten sie ihn dringend, er möchte sich aus ihrem Gebiet entfernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Dann stieg er in ein Boot, fuhr über den See und kam in seine Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Und siehe, da brachte man ihm einen Gelähmten, der auf seinem Bette lag. Als Jesus ihren Glauben sah, sprach er zu dem Gelähmten: \"Mut, mein Sohn! Deine Sünden sind dir vergeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Und siehe, einige der Schriftgelehrten dachten: \"Der lästert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Doch Jesus, der ihre Gedanken durchschaute, sprach: \"Warum denkt ihr Arges in euren Herzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Was ist leichter, zu sagen: Deine Sünden sind dir vergeben, oder zu sagen: Steh auf und geh umher?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ihr sollet aber sehen, daß der Menschensohn Vollmacht hat, auf Erden Sünden zu vergeben.\" Dann sprach er zum Gelähmten: \"Steh auf, nimm dein Bett und geh nach Hause.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Da stand er auf und ging nach Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Als die Scharen dies sahen, wurden sie von Furcht ergriffen; sie lobten Gott, der solche Macht den Menschen gegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Von dort ging Jesus weiter. Da sah er einen Mann, der an der Zollstätte saß; er hieß Matthäus. Er sprach zu ihm: \"Folge mir!\" Und er stand auf und folgte ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Als er dann im Hause zu Tische saß, waren auch viele Zöllner und Sünder zu Tische mit Jesus und seinen Jüngern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Die Pharisäer sahen dies und fragten seine Jünger: \"Warum speist euer Meister mit Zöllnern und mit Sündern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jesus hörte es und sprach: \"Nicht die Gesunden brauchen einen Arzt, wohl aber die Kranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Lernet doch, was es bedeutet \'Erbarmen will ich, keine Opfer\'. Nicht dazu bin ich da, Gerechte zu berufen, sondern Sünder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Da kamen die Jünger des Johannes zu ihm her und fragten: \"Warum fasten wir und die Pharisäer so streng, und deine Jünger fasten gar nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jesus sprach zu ihnen: \"Können die Hochzeitsgäste etwa trauern, solange der Bräutigam bei ihnen weilt? Es werden aber Tage kommen, da ihnen der Bräutigam entrissen ist; dann werden sie fasten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Niemand näht einen Fleck aus ungewalktem Zeug auf einen alten Mantel; sonst reißt der Fleck auch noch vom Mantel etwas ab, und der Riß wird nur noch größer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Auch füllt man neuen Wein nicht in alte Schläuche; sonst platzen die Schläuche, der Wein läuft aus, und die Schläuche sind verdorben. Nein, neuen Wein füllt man in neue Schläuche, dann halten beide miteinander.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Noch sprach er so zu ihnen, siehe, da trat vor ihn ein Vorsteher und warf sich vor ihm nieder mit den Worten: \"Meine Tochter ist soeben gestorben; komm, lege ihr deine Hand auf, dann wird sie leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jesus stand auf und folgte ihm mit seinen Jüngern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Und siehe, da trat ein Weib, das schon zwölf Jahre am Blufluß litt, von hinten her und rührte den Saum seines Kleides an,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'denn sie sagte sich: \"Wenn ich auch nur sein Kleid berühre, so wird mir geholfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Doch Jesus wandte sich um, sah sie an und sprach: \"Mut, meine Tochter! Dein Glaube hat dir geholfen.\" Und von jener Stunde an war dem Weib geholfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Als Jesus in das Haus des Vorstehers gekommen war und die Flötenbläser und die aufgeregte Menge sah, sagte er:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, '\"Gehet hinaus; das Mädchen ist nicht tot, es schläft.\" Doch sie verlachten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Als die Menge hinausgetrieben war, ging er hinein, faßte das Mädchen bei der Hand, und dieses richtete sich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Die Kunde hiervon verbreitete sich in jener ganzen Gegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Von dort ging Jesus weiter; da folgten ihm zwei Blinde. Sie riefen laut: \"Erbarme dich unser, du Sohn Davids!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Kaum war er in das Haus getreten, da kamen auch die Blinden gleich zu ihm. Und Jesus fragte sie: \"Glaubt ihr, daß ich das tun kann?\" \"Ja, Herr\", erwiderten sie ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Und er berührte ihre Augen, wobei er sprach: \"Wie ihr geglaubt habt, soll euch geschehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Da öffneten sich ihre Augen. Doch Jesus sprach zu ihnen voll Ernst: \"Sorgt dafür, daß niemand es erfährt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Sie aber gingen weg und breiteten die Kunde über ihn in jener ganzen Gegend aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Diese waren eben weggegangen, da brachte man ihm einen Stummen, der besessen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Sobald der Dämon ausgetrieben war, konnte der Stumme wieder reden. Die Scharen riefen ganz verwundert: \"Noch nie ist so etwas in Israel geschehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Allein die Pharisäer sagten: \"Durch den Obersten der Dämonen treibt er die Dämonen aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Und Jesus zog umher in allen Städten und in den Dörfern; er lehrte in ihren Synagogen, verkündete die frohe Botschaft des Reiches und heilte jede Krankheit und jegliches Gebrechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Als er die Scharen sah, empfand er mit ihnen ein herzliches Erbarmen; sie waren ja so elend und verwahrlost wie Schafe, die keinen Hirten haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Damals sagte er zu seinen Jüngern: \"Die Ernte ist groß, doch der Arbeiter sind wenige;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'bittet den Herrn der Ernte, daß er Arbeiter für seine Ernte sende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Dann rief er seine zwölf Jünger zu sich her, gab ihnen Macht, unreine Geister auszutreiben und alle Krankheiten und jegliches Gebrechen zu heilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Dies sind die Namen der zwölf Apostel: An erster Stelle Simon, der auch Petrus heißt, und Andreas, dessen Bruder; Jakobus, des Zebedäus\' Sohn, und Johannes, dessen Bruder;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippus und Bartholomäus; Thomas und Matthäus, der Zöllner; Jakobus, des Alphäus\' Sohn, und Thaddäus;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon, der Eiferer, und Judas Iskariot, der ihn dann verriet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Diese Zwölf sandte Jesus mit der Warnung aus: \"Gehet nicht den Weg, der zu den Heiden führt, betretet keine Samariterstadt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'geht vielmehr nur zu den verlorenen Schafen aus dem Hause Israel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'So geht denn hin und verkündet: \'Das Himmelreich ist nahe.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Heilet Kranke, wecket Tote auf, Aussätzige machet rein, treibt Dämonen aus. Umsonst habt ihr es empfangen, gebt es umsonst auch wieder her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Verschafft euch weder Gold noch Silber, noch Geld für eure Gürtel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'nehmt keinen Bettelsack mit auf den Weg, auch nicht zwei Röcke, keine Schuhe, keinen Stab. Denn der Arbeiter ist seines Unterhalts wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Betretet ihr dann eine Stadt oder ein Dorf, so fraget nach, wer dort würdig sei. Bleibt dort, bis ihr wieder weiterziehet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Betretet ihr das Haus, alsdann entbietet ihm den Gruß und saget: \'Der Friede sei mit diesem Hause\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Ist das Haus es würdig, so komme euer Friede über dieses Haus. Ist es dessen aber unwert, alsdann wird euer Friede zu euch zurückkehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Doch wo man euch nicht aufnimmt und eure Worte nicht hören mag, da verlasset jenes Haus oder jene Stadt und schüttelt den Staub von euren Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Wahrlich, ich sage euch: Dem Lande Sodoma und Gomorrha wird es am Tage des Gerichts erträglicher ergehen als jener Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Seht, ich sende euch wie Schafe mitten unter Wölfe. So seid denn klug wie die Schlangen und arglos wie die Tauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Doch vor den Menschen hütet euch. Sie werden euch den Gerichten übergeben und in ihren Synagogen geißeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Auch vor Statthalter und Könige werdet ihr geschleppt um meinetwillen, ihnen und den Heiden zum Zeugnis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Wenn ihr dann ausgeliefert seid, so macht euch keine Sorge, wie und was ihr reden sollt. es wird euch in jener Stunde eingegeben werden, was ihr zu reden habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Denn alsdann seid nicht ihr es, die da reden, vielmehr ist es der Geist eures Vaters, der aus euch redet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Der Bruder wird den eigenen Bruder zum Tode überliefern, der Vater das Kind; Kinder werden gegen ihre Eltern auftreten und sie in den Tod bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Von allen werdet ihr um meines Namens willen gehaßt werden. Doch wer ausharrt bis ans Ende, wird gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Wenn man euch in der einen Stadt verfolgt, so flieht in die andere. Wahrlich ich sage euch: Ihr werdet mit den Städten Israels noch nicht zu Ende sein, bis der Menschensohn erscheint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Der Schüler steht nicht über seinem Meister, der Knecht nicht über seinem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Der Schüler muß zufrieden sein, wenn es ihm ergeht wie seinem Meister, der Knecht, wenn es ihm ergeht wie seinem Herrn. Hat man den Hausherrn \'Beezebul\' gescholten, um wieviel mehr dann seine Hausgenossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Fürchtet sie also nicht. Denn es ist nichts geheim, was nicht offenkundig wird und nichts verborgen, was nicht bekannt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Was ich euch im dunkeln sage, das kündigt im Tageslicht; was ihr nur leis ins Ohr vernommen, das verkündet von den Dächern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Fürchtet euch nicht vor denen, die den Leib zwar töten, aber die Seele nicht töten können. Fürchtet vielmehr den, der Seele und Leib dem Verderben in der Hölle überliefern kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Kauft man nicht zwei Sperlinge um ein paar Pfennige? Und doch fällt nicht ein einziger von ihnen auf die Erde, ohne daß euer Vater es so wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Bei euch aber sind selbst die Haare eures Hauptes gezählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Fürchtet euch also nicht. Denn ihr seid weit mehr wert als viele Sperlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Wer immer vor den Menschen sich zu mir bekennt, zu dem will ich auch mich bekennen vor meinem Vater, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Wer aber mich vor den Menschen verleugnet, den will auch ich vor meinem Vater verleugnen, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Glaubt nicht, ich sei gekommen, Frieden in die Welt zu bringen. Nicht den Frieden wollte ich bringen, vielmehr das Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Ich bin gekommen, den Sohn mit seinem Vater zu entzweien, die Tochter mit ihrer Mutter, die Schwiegertochter mit ihrer Schwiegermutter;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Feinde eines Menschen sind also seine eigenen Hausgenossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Wer Vater oder Mutter mehr liebt als mich, der ist meiner nicht wert; wer den Sohn oder die Tochter mehr liebt als mich, der ist meiner nicht wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Und wer sein Kreuz nicht nimmt und mir nicht nachfolgt, der ist meiner nicht wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Wer sein Leben findet, der wird es verlieren; doch wer sein Leben mir zulieb verliert, der wird es finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Wer euch aufnimmt, nimmt mich auf, und wer mich aufnimmt, nimmt den auf, der mich gesandt hat');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Wer einen Propheten aufnimmt, weil er ein Prophet ist, wird den Lohn eines Propheten erhalten. Wer einen Frommen aufnimmt, weil er ein Frommer ist, wird den Lohn eines Frommen erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Wer einem dieser Kleinen hier nur einen Becher frischen Wassers reicht, weil er mein Jünger ist, wahrlich, ich sage euch: er wird seines Lohnes nicht verlustig gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Als Jesus mit seinen Anordnungen an seine zwölf Jünger zu Ende war, zog er von dort weiter, um in ihren Städten zu lehren und zu predigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Johannes hatte im Gefängnis von den Taten Christi gehört. Da ließ er ihn durch seine Jünger fragen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '\"Bist du es, der da kommen soll, oder sollen wir auf einen andern warten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Und Jesus sprach zu ihnen: \"Gehet hin und berichtet dem Johannes, was ihr hört und seht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Blinde sehen, Lahme gehen, Aussätzige werden rein, Taube hören, Tote stehen auf, und Armen wird die Heilsbotschaft verkündet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Und selig ist, wer sich an mir nicht ärgert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Diese gingen weg. Und Jesus sprach zu den Scharen von Johannes: \"Was wolltet ihr denn sehen, als ihr in die Steppe ginget? Etwa ein Schilfrohr, das vom Winde hin- und herbewegt wird?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Was wolltet ihr sehen, als ihr hinausginget: Wohl einen Menschen, angetan mit weichlichen Gewändern? - Seht, die sich weichlich kleiden, wohnen in Königsburgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ja, wozu seid ihr dann hinausgegangen? Einen Propheten zu sehen? Jawohl. Ich sage euch, mehr sogar als einen Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Denn dieser ist es, von dem geschrieben steht: \'Siehe, ich sende meinen Engel vor dir her, daß er den Weg vor dir bereite\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Wahrlich, ich sage euch: Unter denen, die vom Weibe geboren sind, ist nie ein Größerer aufgetreten als Johannes der Täufer. Doch der Kleinste im Himmelreich ist größer als er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Von den Tagen Johannes des Täufers an bis zu dieser Stunde wird das Himmelreich gestürmt, und nur wer stürmisch drängt, wird es an sich reißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Alle Propheten und das Gesetz bis auf Johannes haben so geweissagt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'und wenn ihr es glauben wollt: Er ist Elias, der da kommen soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Wer Ohren hat, der höre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mit wem kann ich wohl dieses Geschlecht vergleichen? Kindern ist es zu vergleichen, die auf dem Marktplatz sitzen und ihren Spielgenossen zurufen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, '\'Wir haben euch auf der Flöte vorgespielt, und ihr habt nicht getanzt; Klagelieder haben wir gesungen, und ihr habt nicht geweint.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Johannes kam: er aß nicht und trank nicht; da hieß es: \'Er ist besessen\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Es kam der Menschensohn: Er ißt und trinkt; da heißt es: \'Seht den Schlemmer und den Säufer, den Freund der Zöllner und der Sünder.\' Indes die Weisheit ward aus ihren Werken doch als gerecht anerkannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Er machte alsdann jenen Städten bittern Vorbehalt, in denen die meisten seiner Wunder geschehen waren, weil sie trotzdem nicht Buße taten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '\"Wehe dir, Chorazain! Wehe dir, Bethsaida!. Denn wenn in Tyrus und in Sidon die Wunder geschehen wären, die bei euch geschehen sind, sie hätten längst in Sack und Asche Buße getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Jedoch ich sage euch: Tyrus und Sidon wird es am Tage des Gerichts erträglicher ergehen als euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Und du, Kapharnaum, bist du nicht bis in den Himmel erhoben worden? Bis in die Hölle hinab wirst du fahren. Denn wenn in Sodoma die Wunder geschehen wären, die in dir geschehen sind, stünde es heute noch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Jedoch ich sage euch: Dem Lande Sodoma wird es am Tage des Gerichts erträglicher ergehen als dir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Damals hob Jesus an und sprach: \"Ich preise dich, Vater, Herr des Himmels und der Erde, daß du dies den Weisen und Klugen verborgen, Einfältigen es jedoch geoffenbart hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Vater, so hat deine Güte es gefügt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Mir ist von meinem Vater alles übergeben, und niemand kennt den Sohn als nur der Vater, und niemand kennt den Vater als allein der Sohn, und wem der Sohn es offenbaren will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommt her zu mir alle, die ihr elend und beladen seid, ich werde euch erquicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Nehmt mein Joch auf euch und lernt an mir, wie ich von Herzen sanft und voll Demut bin. So werdet ihr Ruhe finden für eure Seelen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'denn mein Joch ist süß und meine Bürde leicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'In jener Zeit ging Jesus an einem Sabbat durch die Ährenfelder. Seine Jünger waren hungrig; sie rupften Ähren ab und aßen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Als die Pharisäer dies sahen, sagte sie zu ihm: \"Sieh doch, deine Jünger tun, was am Sabbat verboten ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Doch er sprach zu ihnen: \"Habt ihr denn nicht gelesen, was David tat, als er und seine Begleiter Hunger hatten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Wie er das Haus Gottes betrat und die Schaubrote aß, die weder er noch seine Begleiter essen durften, sondern nur die Priester?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Oder habt ihr nicht im Gesetze gelesen, daß an den Sabbaten die Priester im Tempel auch den Sabbat brechen, und dennoch schuldlos bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ich sage euch: Hier ist noch etwas Größeres als der Tempel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Wenn ihr es doch verstündet, was es heißt: \'Erbarmen will ich, keine Opfer\', dann hättet ihr die Unschuldigen nicht verurteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Denn Herr des Sabbats ist der Menschensohn!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Von dort ging er weiter und kam in ihre Synagoge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Und siehe, da war ein Mann mit einer verwelkten Hand. Sie fragten ihn: \"Darf man am Sabbat heilen?\" Sie wollten ihn nämlich verklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Er fragte sie: \"Wenn einer unter euch ein einziges Schaf besitzt und dieses am Sabbat in eine Grube fällt, wird er nicht sogleich danach langen und es wieder auf seine Füße stellen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Wie viel mehr wert ist aber im Vergleich zu einem Schaf der Mensch. Also darf man auch am Sabbat Gutes tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Dann sprach er zu dem Manne: \"Strecke deine Hand aus!\" Da streckte er sie aus, und sie ward wiederhergestellt, gesund wie die andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Die Pharisäer aber gingen weg und faßten gegen ihn den Beschluß, ihn umzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Jesus wußte dies und zog sich von dort zurück. Viele folgten ihm, und er machte sie alle gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Streng verbot er ihnen, ihn bekannt zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'So sollte sich erfüllen, was der Prophet Isaias sprach, der sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '\"Das ist mein Knecht, den ich erwählt, mein Liebling, meines Herzens Wonne. Ich lege meinen Geist auf ihn, er wird den Heiden das Recht verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Er wird nicht zanken und nicht schreien; noch wird man auf den Gassen seine Stimme hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Geknicktes Rohr zerbricht er nicht, den Docht, der nur noch glimmt, löscht er nicht aus, bis das Recht mit seinem Sieg beendet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Auf seinen Namen hoffen auch die Heiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Da brachte man ihm einen, der besessen war und blind und stumm zugleich. Er heilte ihn, so daß der Stumme wieder reden und sehen konnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Die Leute alle kamen außer sich und sprachen: \"Sollte der nicht der Sohn Davids sein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Als dies die Pharisäer hörten, sprachen sie: \"Nur durch Beelzebul, den obersten der Dämonen, treibt er die Dämonen aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Da er wußte, was sie dachten, sprach er zu ihnen: \"Jedes Reich, das in sich uneins ist, zerfällt, und jede Stadt und jedes Haus, das in sich uneins ist, wird nicht bestehen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Und wenn der Satan den Satan austreiben würde, so wäre er ja in sich selber uneins. Wie könnte da sein Reich bestehen bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Wenn ich durch Beelzebul die Dämonen austreibe, durch wen treiben dann eure Söhne sie aus? Deshalb werden diese eure Richter sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Wenn ich jedoch im Geiste Gottes die Dämonen austreibe, dann ist ja das Reich Gottes schon zu euch gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Oder wie könnte einer in das Haus des Starken eindringen und ihm seine Habseligkeiten rauben, wenn er den Starken nicht zuvor gebunden hat? Dann erst kann er sein Haus ausplündern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Wer nicht mit mir ist, ist gegen mich, und wer nicht mit mir sammelt, der zerstreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'So sage ich euch denn: Den Menschen wird jede Sünde und Lästerung vergeben werden; die Lästerung des Geistes jedoch wird nicht vergeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Wer ein Wort sagt gegen den Menschensohn, dem wird vergeben werden; doch wer ein Wort sagt gegen den Heiligen Geist, dem wird nicht vergeben werden, in dieser Welt nicht und nicht in der kommenden..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Entweder erklärt ihr den Baum für gut, dann ist auch seine Frucht gut, oder ihr erklärt den Baum für schlecht, dann ist auch seine Frucht schlecht; denn an der Frucht erkennt man den Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Ihr Schlangenbrut! Wie könnt ihr Gutes reden, da ihr doch böse seid? Der Mund redet das, wovon das Herz voll ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Der gute Mensch bringt aus seinem guten Schatze Gutes hervor, der böse Mensch aus seinem bösen Schatze Böses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Indessen sage ich euch: Von jedem unnützen Worte, das die Menschen reden, werden sie am Tage des Gerichtes Rechenschaft ablegen müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Aus deinen Worten nämlich wirst du für gerecht erklärt, aus deinen Worten aber auch verurteilt werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Da sagten zu ihm einige der Schriftgelehrten und der Pharisäer: \"Meister, wir möchten ein Zeichen von dir sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Er gab ihnen zur Antwort: \"Ein böses und ehebrecherisches Geschlecht verlangt ein Zeichen. Jedoch es wird ihm kein andres Zeichen gegeben als das Zeichen des Propheten Jonas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Wie nämlich Jonas drei Tage und drei Nächte im Bauche des Seetiers war, so wird auch der Menschensohn drei Tage und drei Nächte im Schoße der Erde sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Die Niniviten werden sich beim Gerichte zugleich mit diesem Geschlecht erheben und es verdammen. Denn diese haben sich bekehrt, als Jonas ihnen predigte, und siehe, hier ist mehr als Jonas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Die Königin des Südens wird sich beim Gerichte zugleich mit diesem Geschlecht erheben und es verdammen. Sie kam von den Enden der Erde, die Weisheit Salomons zu hören, und siehe, hier ist mehr als Salomon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Wenn der unreine Geist aus dem Menschen ausgefahren ist, dann wandert er durch öde Gegenden, sucht eine Ruhestätte, findet aber keine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Alsdann sagt er: \'Ich will in mein Haus zurück, aus dem ich ausgezogen bin.\' Er kommt und findet es geleert, rein gefegt und geschmückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Dann geht er hin, nimmt noch sieben andre Geister mit sich, die schlimmer sind als er; sie ziehen ein und wohnen dort. Mit einem solchen Menschen wird es nachher schlimmer stehen, als vorher. So wird es diesem schändlichen Geschlecht ergehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Noch redete er zu den Scharen, da standen seine Mutter und seine Brüder draußen; sie wollten ihn sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Da sagte zu ihm irgendeiner: \"Deine Mutter und deine Brüder stehen draußen; sie möchten dich gern sprechen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Er antwortete dem, der es ihm gesagt hatte: \"Wer ist denn meine Mutter, wer sind denn meine Brüder?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Dann zeigte er mit seiner Hand auf seine Jünger hin und sprach: \"Seht, hier sind meine Mutter und meine Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Denn wer den Willen meines Vaters tut, der in den Himmeln ist, der ist mir Bruder, Schwester, Mutter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'An jenem Tag ging Jesus aus dem Hause fort und setzte sich am Meere nieder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Da sammelten sich bei ihm große Scharen, so daß er ein Boot besteigen mußte; dort setzte er sich nieder; die ganze Menge aber stand am Ufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Er sprach nun viel in Gleichnissen zu ihnen: \"Siehe, es ging der Sämann aus zu säen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Und als er säte, fiel ein Teil hin auf den Weg, es kamen die Vögel des Himmels und fraßen es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Ein andres fiel auf steinigen Grund, wo nicht viel Erdreich war. Rasch schoß es in den Halm; es hatte nämlich keinen tiefen Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Doch als die Sonne aufgegangen war, wurde es versengt, weil es keine Wurzeln hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Ein andres fiel unter Dornen. Die Dornen wuchsen auf und erstickten es..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Ein andres fiel auf guten Boden und trug Frucht: hundertfältig, sechzigfältig, dreißigfältig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Wer Ohren hat, der höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Da traten seine Jünger näher und fragten ihn: \"Warum sprichst du in Gleichnissen zu ihnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Er sprach zu ihnen: \"Euch ist es vergönnt, die Geheimnisse des Himmelreiches zu verstehen, doch jenen ist es nicht vergönnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Wer nämlich hat, dem wird gegeben werden, und er wird im Überflusse haben, doch wer nicht hat, dem wird auch das genommen werden, was er besitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Deshalb rede ich in Gleichnissen zu ihnen, weil sie sehen und doch nicht sehen, hören und doch nicht hören, noch zur Einsicht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'An ihnen wird die Weissagung des Isaias erfüllt, die lautet: \'Ihr werdet mit eigenen Ohren hören, aber nicht zur Einsicht kommen, und mit eigenen Augen sehen, aber nicht einsehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Verstockt ist das Herz dieses Volkes; schwerhörig sind seine Ohren, und seine Augen hält es geschlossen, damit sie mit den Augen nicht sehen und mit den Ohren nicht hören und verständig würden mit den Herzen, damit sie sich bekehrten und ich sie heilen könnte\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Doch selig eure Augen, weil sie sehen, und eure Ohren, weil sie hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Wahrlich, ich sage euch: Viele Propheten und Gerechte verlangten sehnlichst zu sehen, was ihr sehet, sie sahen es aber nicht, zu hören, was ihr höret, sie hörten es aber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Ihr also sollt das Gleichnis vom Sämann vernehmen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Wer immer das Wort vom Reiche hört, doch nicht zur Einsicht kommt, da kommt der Böse und raubt, was in seinem Herzen gesät ist. Das ist der, bei dem es auf den Weg gesät war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Auf steinigen Grund ist es bei dem gesät, der zwar das Wort anhört und es sofort mit Freuden aufnimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Doch hat er in sich keine Wurzel, denn er ist unbeständig; kommt nämlich Trübsal oder Verfolgung um des Wortes willen, dann wird er sogleich irre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Und unter Dornen ist es bei dem gesät,, der zwar das Wort anhört, jedoch die Sorgen dieser Welt sowie der trügerische Reichtum ersticken dann das Wort, und so bleibt es ohne Frucht..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Auf guten Boden aber ist es bei dem gesät, der das Wort hört, zur Einsicht kommt und dann auch Frucht bringt: hundertfältig, sechzigfältig, dreißigfältig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Ein anderes Gleichnis trug er ihnen vor; er sprach: \"Das Himmelreich ist einem Manne gleich, der guten Samen auf seinen Acker säte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Während die Leute schliefen, kam sein Feind, säte Unkraut mitten in den Weizen und ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Als nun die Saat heranwuchs und Frucht ansetzte, zeigte sich auch das Unkraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Da traten die Knechte des Hausvaters zu ihm hin und fragten ihn: \'Herr! Hast du nicht guten Samen auf deinen Acker gesät? Woher hat er denn das Unkraut?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Er sprach zu ihnen: \'Das hat ein Feind getan.\' Die Knechte fragten ihn: \'Sollen wir hingehen und es einsammeln?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, '\'Nein!\' sprach er. \'Ihr könntet sonst, wenn ihr das Unkraut einsammelt, zugleich den Weizen mit herausreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Laßt beides zusammen wachsen bis zur Ernte. Zur Zeit der Ernte will ich dann den Schnittern sagen: Sammelt zuerst das Unkraut und bindet es in Büschel zum Verbrennen; den Weizen aber sammelt ein in meinen Speicher.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Ein anderes Gleichnis trug er ihnen vor; er sprach: \"Das Himmelreich ist einem Senfkorn gleich, das jemand auf seinen Acker säte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Dieses ist zwar das kleinste unter allen Samenkörnern; ist es aber herangewachsen, so ist es das größte unter allen Gartenkräutern und wird zum Baume, so daß die Vögel des Himmels kommen und in seinen Zweigen nisten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Und er erzählte ihnen noch ein Gleichnis: \"Das Himmelreich ist einem Sauerteig gleich. Ihn nahm ein Weib und vermengte ihn mit drei Maß Mehl, bis alles ganz durchsäuert war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'All dies sprach Jesus zu den Scharen gleichnisweise; ja, ohne Gleichnis redete er nicht zu ihnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'damit erfüllt würde, was durch den Propheten gesprochen ward, wenn er sagt: \"In Gleichnissen will ich meinen Mund öffnen und will enthüllen, was verborgen war seit Grundlegung der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Alsdann entließ er die Scharen und ging ins Haus zurück. Da traten seine Jünger zu ihm mit der Bitte: \"Erkläre uns das Gleichnis vom Unkraut auf dem Acker!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Er sprach: \"Der den guten Samen sät, ist der Menschensohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Der Acker ist die Welt. Der gute Same sind die Kinder des Reiches; das Unkraut sind die Kinder des Bösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Der Feind, der es gesät hat, ist der Teufel. Die Ernte ist die Vollendung der Welt; die Schnitter sind die Engel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Wie man das Unkraut sammelt und im Feuer verbrennt, so wird es auch bei der Vollendung der Welt sein:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Der Menschensohn wird seine Engel aussenden; sie werden aus seinem Reiche alle zusammenlesen, die Ärgernis gegeben und die Unrecht getan haben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'und werden sie in den Feuerofen werfen; dort wird Heulen und Zähneknirschen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Dann werden die Gerechten leuchten wie die Sonne im Reiche ihres Vaters. Wer Ohren hat, höre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Das Himmelreich ist einem Schatze gleich, der im Acker verborgen lag. Ihn fand ein Mann, verhehlte ihn jedoch, ging in seiner Freude hin, verkaufte alles, was er hatte, und kaufte jenen Acker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Das Himmelreich ist ferner einem Kaufmann gleich, der schöne Perlen suchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Da fand er eine Perle von gar großem Wert. Er ging hin, verkaufte alles, was er hatte, und kaufte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Das Himmelreich ist ferner einem Netze gleich; man warf es ins Meer und fing Fische aller Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Und als es voll geworden war, zog man es ans Ufer; man setzte sich und sammelte die guten in Behälter, die schlechten aber warf man weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'So wird es auch bei der Vollendung der Welt sein: Die Engel werden ausgehen, die Bösen von den Guten scheiden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'und jene in den Feuerofen werfen; dort wird Heulen und Zähneknirschen sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Und Jesus fragte sie: \"Habt ihr dies alles verstanden?\" \"Ja, Herr\", erwiderten sie ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Er sprach zu ihnen: \"Darum gleicht jeder Lehrer, der in der Schule des Himmelreiches herangebildet ist, einem Hausvater, der aus seiner Vorratskammer Neues und Altes hervorholt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Als Jesus diese Gleichnisreden beendet hatte, begab er sich von dort hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Er kam in seine Vaterstadt und lehrte sie in ihrer Synagoge. Voll Staunen fragte man: \"Woher hat dieser solche Weisheit und die Wunderkraft;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'ist er denn nicht der Sohn des Zimmermanns? Heißt nicht seine Mutter Maria und seine Brüder Jakobus, Joseph, Simon und Judas?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Und wohnen denn nicht alle seine Schwestern hier bei uns? Woher mag er denn all dies haben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'So nahm man also an ihm Anstoß. Doch Jesus sprach zu ihnen: \"Ein Prophet gilt nirgends weniger als in seiner Vaterstadt und in seinem Vaterhaus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Er wirkte dort nicht viele Wunder wegen ihres Unglaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'In jener Zeit vernahm Herodes, der Vierfürst, von Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Er sprach zu seinen Höflingen: \"Das ist Johannes der Täufer. Er ist von den Toten auferstanden, deshalb wirken in ihm Gottes Kräfte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Herodes hatte nämlich Johannes gefangennehmen, fesseln und ins Gefängnis werfen lassen der Herodias, dem Weibe Philippus\', seines Bruders, zu Gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Denn Johannes hatte ihm vorgehalten: \"Es ist dir nicht erlaubt, sie zu besitzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Er hätte ihn gern getötet, jedoch er fürchtete das Volk; denn dieses sah ihn als einen Propheten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Am Geburtsfest des Herodes tanzte die Tochter der Herodias im Kreise der Gäste. Dies gefiel Herodes so,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'daß er ihr unter einem Eid versprach, ihr zu geben, was immer sie verlangen würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Von ihrer Mutter angestiftet, sprach sie: \"Gib mir hier auf einer Schüssel den Kopf Johannes des Täufers!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Da ward der König tief betrübt; jedoch des Eides und der Gäste wegen befahl er, ihn zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Also ließ er den Johannes im Gefängnis enthaupten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Man brachte seinen Kopf auf einer Schüssel und gab ihn dem Mädchen, und diese brachte ihn ihrer Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Seine Jünger holten dann den Leichnam und begruben ihn. Hierauf erzählten sie es Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Auf diese Nachricht hin zog sich Jesus von da zurück; auf einem Boote ging er allein an einen abgelegenen Ort. Die Scharen merkten dies und folgten ihm zu Fuß von den Städten her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Er stieg aus und sah die große Menge, empfand ein herzliches Erbarmen über sie und heilte ihre Kranken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Als es schon spät geworden war, traten seine Jünger zu ihm hin und sprachen: \"Der Ort ist einsam und die Zeit schon vorgerückt. Entlaß daher die Scharen. Sie mögen in die Dörfer gehen und sich Nahrung kaufen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Doch Jesus sprach zu ihnen: \"Sie brauchen gar nicht wegzugehen; gebt ihr ihnen zu essen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Da sagten sie zu ihm: \"Wir haben nur fünf Brote und zwei Fische hier.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, '\"So bringet sie mir her\", sprach er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Dann hieß er die Scharen sich auf dem Grase zu lagern, nahm die fünf Brote und die zwei Fische, schaute auf zum Himmel und segnete. Er brach sodann die Brote und gab sie seinen Jüngern; die Jünger gaben sie den Scharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Und alle aßen und wurden satt; ja, noch zwölf Körbe trugen sie hinweg, voll mit Stücken, die übriggeblieben waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Es waren derer, die gegessen hatten, an fünftausend Männer; die Frauen und Kinder nicht gerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Und sogleich drängte er die Jünger, in das Boot zu steigen und an das andere Ufer ihm vorauszufahren; er wollte die Scharen inzwischen entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Und er entließ die Scharen und stieg allein auf einen Berg, um dort zu beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Es war schon spät, und er war dort ganz allein. Das Boot war schon viele Stadien vom Land entfernt mitten auf dem Meere von Wellen hart bedrängt; sie hatten nämlich Gegenwind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Da, um die vierte Nachtwache, kam er zu ihnen, auf dem Meere daherwandelnd.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Die Jünger sahen ihn, wie er auf dem Meere wandelte; sie erschraken und riefen: \"Ein Gespenst!\" Sie schrien laut vor Angst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Doch alsbald redete sie Jesus an und sprach: \"Nur Mut! Ich bin es. Habt keine Angst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Und Petrus sprach zu ihm: \"Herr, wenn du willst, so heiße mich auf dem Wasser zu dir kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Er sprach: \"Komm!\" Da stieg Petrus aus dem Boot und schritt über das Wasser hin und ging auf Jesus zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Als er jedoch den starken Wind verspürte, bekam er Angst; er fing an zu sinken und schrie: \"Herr, rette mich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Sogleich streckte Jesus seine Hand aus, faßte ihn und sprach: \"Kleingläubiger, warum hast du gezweifelt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Darauf stiegen sie ins Boot, und sogleich legte sich der Wind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Die im Boote waren, fielen vor ihm nieder mit den Worten: \"Wahrhaftig, du bist der Sohn Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Sie fuhren vollends über und kamen bei Genesareth ans Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Sobald die Leute ihn dort erkannten, schickten sie in jener Gegend überall herum, und man brachte alle Kranken zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Und diese baten ihn, sie möchten nur den Saum seines Kleides berühren. Und alle, die ihn berührten, wurden ganz gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Da kamen aus Jerusalem Pharisäer und Schriftgelehrte zu Jesus mit der Frage:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '\"Warum übertreten deine Jünger die Überlieferung der Alten? Sie waschen ja ihre Hände nicht, bevor sie essen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Allein er fragte sie: \"Warum übertretet ihr das Gebot Gottes eurer Überlieferung zulieb? Gott hat geboten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, '\'Du sollst Vater und Mutter ehren\' und \'Wer Vater oder Mutter schmäht, soll sterben\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ihr aber sagt: \'Wer zu Vater oder Mutter spricht: Was ich dir zu leisten hätte, ist Opfergabe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'der braucht Vater und Mutter nicht zu ehren.\' Damit entkräftigt ihr das Gesetz Gottes eurer Überlieferung zulieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Ihr Heuchler! Richtig hat Isaias über euch geweissagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '\'Dieses Volk ehrt mich mit den Lippen; ihr Herz jedoch ist weit von mir;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'nichtig ist ihr Gottesdienst: Menschensatzungen machen sie zu ihrer Lehre.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Er rief sodann die Scharen zu sich her und sprach zu ihnen: \"Höret und verstehet es wohl:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nicht was zum Munde eingeht, macht den Menschen unrein, sondern was vom Munde ausgeht, das macht den Menschen unrein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Da traten seine Jünger zu ihm hin und sprachen: \"Weißt du, daß die Pharisäer, als sie diese Worte hörten, Anstoß nahmen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Er erwiderte: \"Jede Pflanzung, die mein himmlischer Vater nicht gepflanzt hat, wird ausgerottet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laßt sie! Sie sind ja blinde Blindenführer. Wenn ein Blinder einen Blinden führt, fallen beide in die Grube.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Petrus sprach zu ihm: \"Erkläre uns das Gleichnis\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Er sagte: \"Seid auch ihr noch so unverständig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Versteht ihr wirklich nicht, daß alles, was durch den Mund eingeht, in den Magen kommt und dann ausgeschieden wird?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Was aber aus dem Mund ausgeht, kommt aus dem Herzen, und dies macht den Menschen unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Denn aus dem Herzen gehen schändliche Gedanken, Mord, Ehebruch, Unzucht, Diebstahl, falsches Zeugnis und Lästerungen hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Das sind Dinge, die den Menschen unrein machen. Jedoch mit ungewaschenen Händen essen, macht den Menschen nicht unrein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Und Jesus ging von dort hinweg und begab sich in das Land von Tyrus und Sidon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Da kam eine Kanaanäerin aus jener Gegend; diese rief: \"Erbarme dich meiner, Herr, du Sohn Davids! Meine Tochter wird von einem Dämon arg geplagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Er aber würdigte sie keines Wortes. Da traten seine Jünger vor ihn hin und baten ihn: \"Schick sie doch weg; sie schreit hinter uns her.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Doch Jesus sprach zu ihnen: \"Ich bin nur zu den verirrten Schafen des Hauses Israel gesandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Da kam sie her und fiel vor ihm nieder mit den Worten: \"Herr, hilf mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Er aber gab zur Antwort: \"Es ist nicht recht, den Kindern das Brot wegzunehmen und es den Hunden vorzuwerfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Doch sie entgegnete: \"Gewiß, Herr. Doch auch die Hunde fressen von den Brocken, die von dem Tische ihrer Herren fallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Da sprach Jesus zu ihr: \"O Weib! Dein Glaube ist groß. Es sei dir gewährt, worum du bittest.\" Und ihre Tochter war von jener Stunde an geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Von dort begab sich Jesus weiter; er kam an das Meer von Galiläa, stieg auf einen Berg und setzte sich dort nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Große Scharen traten zu ihm hin; sie hatten Lahme, Krüppel, Blinde, Stumme und noch andere Kranke bei sich. Sie legten diese vor ihm nieder, und er heilte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Die Scharen staunten, da sie sahen, wie Lahme gingen und wie Blinde sehend wurden. Und sie priesen den Gott Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Da rief Jesus seine Jünger zu sich her und sprach: \"Mich erbarmt des Volkes. Sie harren schon drei Tage bei mir aus und haben nichts zu essen. Ich kann sie nicht hungrig entlassen; sonst möchten sie auf dem Wege verschmachten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Die Jünger gaben ihm zur Antwort: \"Woher sollen wir in der Steppe so viel Brot bekommen, um eine solche Schar zu sättigen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Und Jesus fragte sie: \"Wie viele Brote habt ihr?\" Sie sprachen: \"Sieben, dazu noch ein paar kleine Fische.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Nun hieß er die Scharen sich auf den Boden lagern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Dann nahm er die sieben Brote und die Fische, dankte, brach sie und gab sie den Jüngern; die Jünger gaben sie der Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Und alle aßen und wurden satt. Ja, sie trugen noch sieben Körbe weg, voll mit Stücken, die übriggeblieben waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Derer, die gegessen hatten, waren es viertausend Männer, die Frauen und Kinder nicht gerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Und er entließ die Scharen, bestieg das Boot und gelangte in die Gegend von Magadan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Die Pharisäer und die Sadduzäer traten zu ihm hin. Sie wollten ihn versuchen und verlangten von ihm, er solle sie ein Zeichen vom Himmel sehen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Er aber gab ihnen zur Antwort: \"Am Abend sagt ihr: \'Es wird schön Wetter, denn der Himmel ist feuerrot.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Am Morgen: \'Heute gibt es Sturm, denn der Himmel ist trübrot.\' Wie der Himmel aussieht, wisset ihr zu deuten, nicht aber könnt ihr es bei den Zeichen der Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Ein böses und ein ehebrecherisches Geschlecht verlangt ein Zeichen. Jedoch wird ihm kein anderes Zeichen gegeben werden, als das Zeichen des Jonas.\" Damit ließ er sie stehen und ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Seine Jünger langten am andern Ufer an; sie hatten aber vergessen, Brote mitzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Und Jesus sprach zu ihnen: \"Hütet euch vor dem Sauerteig der Pharisäer und Sadduzäer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Sie dachten hin und her und sprachen schließlich: \"Wir haben ja kein Brot bei uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jesus merkte dies und sprach: \"Was denkt ihr da bei euch, Kleingläubige, daß ihr kein Brot mitgenommen habt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Begreift ihr denn immer noch nicht? Erinnert ihr euch nicht mehr an die fünf Brote für die Fünftausend und wieviel Körbe ihr noch bekommen habt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Auch nicht mehr an die sieben Brote für die Viertausend und wieviel Körbe ihr noch bekommen habt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Warum begreift ihr denn nicht, daß ich nicht von Broten zu euch gesprochen habe? Doch hütet euch vor dem Sauerteig der Pharisäer und Sadduzäer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Nunmehr begriffen sie, daß er es nicht so gemeint hätte, als sollten sie sich vor dem Sauerteig des Brotes hüten, sondern vor der Lehre der Pharisäer und Sadduzäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Und Jesus kam in das Gebiet von Cäsarea Philippi. Er fragte seine Jünger: \"Für wen halten die Leute den Menschensohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Sie sagte: \"Die einen für Johannes den Täufer, andre für Elias, wieder andre für Jeremias oder für den Einen der Propheten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Er fragte weiter: \"Und ihr, für wen haltet ihr mich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Da antwortete Simon Petrus: \"Du bist der Christus, der Sohn des lebendigen Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Darauf sprach Jesus zu ihm: \"Selig bist du, Simon, Sohn des Jonas. Nicht Fleisch und Blut hat dir das geoffenbart, sondern mein Vater, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Ich sage dir: Du bist Petrus; auf diesen Felsen will ich meine Kirche bauen, und die Pforten der Hölle werden sie nicht überwältigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Ich werde dir die Schlüssel des Himmelreiches geben; was immer du auf Erden binden wirst, das wird auch in den Himmeln gebunden sein, was immer du auf Erden lösen wirst, das wird auch in den Himmeln gelöst sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Sodann gebot er seinen Jüngern, es niemandem zu sagen, daß er der Christus sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Von jetzt an begann Jesus, seinen Jüngern klarzumachen, daß er nach Jerusalem gehen müsse und vieles leiden werde von den Ältesten, den Oberpriestern und den Schriftgelehrten, daß er getötet werde müsse, am dritten Tage aber wieder auferstehen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Da nahm Petrus ihn beiseite und wollte ihm ernstlich zureden: \"Gott bewahre, Herr! Das sei ferne von dir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Da wandte er sich um und sprach zu Petrus: \"Hinweg von mir, du Satan! Du bist für mich ein Ärgernis; du hast nicht Sinn für das Göttliche, sondern für das Menschliche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Dann sprach Jesus zu seinen Jüngern: \"Wer mir nachfolgen will, der verleugne sich selbst, nehme sein Kreuz auf sich und folge mir nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Denn wer sein Leben sich erhalten will, der wird es verlieren, wer aber sein Leben meinetwegen verliert, der wird es erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Was nützt es dem Menschen, wenn er die ganze Welt gewänne, dabei aber doch sein Leben verlieren würde. Oder was möchte auch einer geben als Kaufpreis für sein Leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Der Menschensohn wird in der Herrlichkeit seines Vaters erscheinen samt seinen Engeln; er wird dann jedem vergelten nach seinen Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Wahrlich, ich sage euch: Es stehen solche hier, die den Tod nicht kosten werden, bis sie den Menschensohn in seinem Reiche kommen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Sechs Tage später nahm Jesus den Petrus, Jakobus und Johannes, dessen Bruder, mit sich und führte sie abseits auf einen hohen Berg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Und er ward vor ihnen verwandelt: Sein Antlitz glänzte wie die Sonne, und seine Kleider wurden leuchtend wie das Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Und siehe, es erschienen ihnen Moses und Elias, die sich mit ihm unterredeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Und Petrus nahm das Wort und sprach zu Jesus: \"Herr, wie schön ist es doch, daß wir hier sind. Willst du, so will ich hier drei Hütten bauen: Dir eine, dem Moses eine und dem Elias eine.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Noch sprach er so und schon kam der Schatten einer lichten Wolke über sie, und eine Stimme aus der Wolke sprach: \"Das ist mein vielgeliebter Sohn, an dem ich Wohlgefallen habe. Auf diesen sollt ihr hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Als die Jünger dies hörten, fielen sie auf ihr Antlitz nieder und gerieten in gewaltige Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Doch Jesus trat herzu, berührte sie und sprach: \"Steht auf, seid ohne Furcht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Und sie erhoben ihre Augen und sahen niemand mehr als Jesus allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Während sie vom Berge niederstiegen, befahl ihnen Jesus: \"Sagt niemand etwas von dem Gesichte, bis der Menschensohn von den Toten auferstanden ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Da fragten ihn die Jünger: \"Wie ist es denn, wenn die Schriftgelehrten sagen, vorher müsse noch Elias kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Er sprach zu ihnen: \"Elias kommt allerdings, und er wird alles wiederherstellen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'ja, ich sage euch: Elias ist schon gekommen. Doch man hat ihn nicht erkannt und mit ihm angefangen, was man wollte. Geradeso wird auch der Menschensohn durch sie zu leiden haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Die Jünger begriffen jetzt, daß er zu ihnen von Johannes dem Täufer gesprochen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Als sie zum Volke gekommen waren, da trat ein Mann vor ihn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'und bat ihn auf den Knien: \"Herr, erbarme dich meines Sohnes! Er ist mondsüchtig und hat arg zu leiden. Oft fällt er in das Feuer, oft ins Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Ich brachte ihn deinen Jüngern; doch diese konnten ihn nicht heilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Und Jesus sprach: \"Du ungläubiges und ganz verkehrtes Geschlecht. Wie lang noch muß ich bei euch bleiben? Wie lang noch muß ich euch ertragen? Bringt ihn her zu mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Alsdann gebot ihm Jesus, und der Dämon fuhr aus von ihm. So war der Knabe von jener Stunde an geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Da traten die Jünger insgeheim zu Jesus hin und fragten ihn: \"Warum konnten wir ihn nicht austreiben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Und Jesus sprach zu ihnen: \"Weil ihr so wenig Glauben habt. Wahrlich, ich sage euch: Wenn ihr Glauben habt so groß nur wie ein Senfkorn, so könnt ihr zu diesem Berge sagen: \'Rück weg von hier, dorthin!\' Und er wird weggehen. Gar nichts wird euch unmöglich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Doch diese Art wird nur durch Beten und Fasten ausgetrieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Solange sie in Galiläa wanderten, sprach Jesus zu ihnen: \"Der Menschensohn wird in die Hände der Menschen überliefert werden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'man wird ihn töten, doch am dritten Tage wird er auferstehen.\" Da wurden sie sehr traurig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Als sie dann nach Kapharnaum gekommen waren, traten die Einnehmer der Doppeldrachme zu Petrus hin und fragten ihn: \"Bezahlt euer Meister denn die Doppeldrachme nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Er sagte: \"Doch.\" Kaum war er in das Haus gekommen, als Jesus ihm zuvorkam mit der Frage: \"Was meinst du, Simon, von wem nehmen die Könige der Erde Zoll und Steuer, von ihren Söhnen oder von den Fremden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, '\"Von den Fremden!\" gab er zur Antwort. Da sagte Jesus zu ihm: \"So sind die Söhne demnach frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Wir aber wollen ihnen keinen Anstoß geben. Geh an das Meer und wirf die Angel aus und nimm den ersten Fisch, der in die Höhe kommt. Öffne ihm das Maul, darin wirst du einen Stater finden; mit dem bezahle dann für mich und dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'In jener Stunde traten die Jünger vor Jesus mit der Frage: \"Wer ist der Größte im Himmelreich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Da rief Jesus sich ein Kind herbei, stellte es mitten unter sie');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'mit den Worten: \"Wahrlich, ich sage euch: Wenn ihr euch nicht bekehrt und werdet wie die Kinder, so werdet ihr sicher nicht ins Himmelreich eingehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Doch wer sich demütig macht wie dieses Kind, der ist der Größte im Himmelreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Und wer ein solches Kind in meinem Namen aufnimmt, nimmt mich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Wer aber einem dieser Kleinen, die an mich glauben, Anlaß zur Sünde gibt, für den wäre es besser, wenn ihm ein großer Mühlstein an den Hals gehängt und er ins tiefste Meer versenkt würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Wehe der Welt der Ärgernisse wegen. Ärgernisse müssen zwar kommen, doch weh dem Menschen, durch den das Ärgernis kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Gibt dir also deine Hand oder dein Fuß zur Sünde Anlaß, so haue sie ab und wirf sie weg. Besser ist es für dich, verstümmelt oder hinkend in das Leben einzugehen, als daß du zwei Hände und zwei Füße habest und in das ewige Feuer geworfen wirst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Gibt dein Auge dir zur Sünde Anlaß, so reiß es aus und wirf es weg.. Besser ist es für dich, mit einem Auge in das Leben einzugehen, als daß du zwei Augen habest und in das Höllenfeuer geworfen wirst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Hütet euch, daß ihr keines dieser Kleinen verachtet. Ich sage euch: Ihre Engel in den Himmeln schauen immerfort das Antlitz meines Vaters, der in den Himmeln ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Denn der Menschensohn ist gekommen, zu retten, was verloren war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Was dünkt euch? Wenn einer hundert Schafe hat und eines sich davon verläuft, läßt er nicht die neunundneunzig auf den Bergen und macht sich auf, um das verlaufene zu suchen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Und hat er dann das Glück, es aufzufinden, wahrlich, sage ich euch: Er freut sich mehr über dieses, als über jene neunundneunzig, die sich nicht verlaufen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'So ist es nicht der Wille eures Vaters, der in den Himmeln ist, daß eines dieser Kleinen verlorengehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Und hat dein Bruder gegen dich gefehlt, geh hin, stelle ihn zur Rede, doch nur unter vier Augen. Hört er alsdann auf dich, so hast du deinen Bruder gewonnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Doch hört er nicht, dann nimm noch einen oder zwei mit dir, damit durch zweier oder dreier Zeugen Mund die ganze Sache festgestellt werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Hört er dann auch auf diese nicht, so sage es der Kirche. Hört er jedoch auf die Kirche nicht, dann gelte er dir wie ein Heide und ein Zöllner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Wahrlich, ich sage euch: Was immer ihr auf Erden binden werdet, das wird auch im Himmel gebunden sein; was immer ihr auf Erden lösen werdet, das wird auch im Himmel gelöst sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Wahrlich sage ich euch ferner: Um was immer zwei aus euch einmütig auf Erden bitten werden, das wird ihnen von meinem Vater, der in den Himmeln ist, gegeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Denn wo zwei oder drei in meinem Namen beieinander sind, da bin ich mitten unter ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Darauf trat Petrus zu ihm hin und fragte: \"Herr, wie oft muß ich meinem Bruder verzeihen, wenn er wider mich gesündigt hat? Etwa bis zu siebenmal?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Und Jesus sprach zu ihm: \"Nein, ich sage dir, nicht bis zu siebenmal, vielmehr siebenundsiebzigmal.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'So ist das Himmelreich einem Könige zu vergleichen, der mit seinen Knechten abrechnen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Und als er anfing abzurechnen, da brachte man ihm einen mit einer Schuld von zehntausend Talenten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Er hatte nichts, womit er hätte zahlen können, und so befahl sein Herr, ihn, sein Weib und seine Kinder mit der ganzen Habe zu verkaufen, um damit zu zahlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Da warf sich der Knecht ihm zu Füßen; er bat: \'Herr, habe Geduld mit mir; ich will dir alles bezahlen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Voll Mitleid mit diesem Knechte ließ der Herr ihn frei und schenkte ihm die Schuld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Der Knecht ging hinaus und traf einen seiner Mitknechte, der ihm hundert Zehner schuldig war. Er packte und würgte ihn und schrie: \'Bezahle, was du schuldig bist!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Da fiel der Mitknecht vor ihm nieder und bat ihn mit den Worten: \'Habe Geduld mit mir; ich werde dich bezahlen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Allein der wollte nicht, ging vielmehr hin und ließ ihn ins Gefängnis werfen, bis er die Schuld bezahlt hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Dies hatten seine Mitknechte mit angesehen und waren tief betrübt darüber. Sie gingen hin und erzählten ihrem Herrn alles, was sich ereignet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Da ließ ihn sein Herr vor sich kommen und sprach zu ihm: \'Du böser Knecht! Jene ganze Schuld habe ich dir nachgelassen, weil du mich so angefleht hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Hättest nicht auch du dich deines Mitknechtes erbarmen müssen, wie ich mich deiner erbarmt habe?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Und sein Herr übergab ihn voll Zorn den Folterknechten, bis er ihm die ganze Schuld abgetragen hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'So wird auch mein himmlischer Vater mit euch verfahren, wenn nicht ein jeder seinem Bruder von ganzem Herzen verzeiht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Als Jesus diese Reden beendet hatte, zog er aus Galiläa weg und gelangte in die Gegend von Judäa überm Jordan drüben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Und große Scharen folgten ihm, und er heilte sie dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Da traten Pharisäer zu ihm, versuchten ihn und fragten: \"Ist es dem Mann erlaubt, sein Weib aus jedem beliebigen Grund zu entlassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Er sprach zu ihnen: \"Habt ihr denn nicht gelesen, daß der Schöpfer im Anfang die Menschen als Mann und Weib geschaffen hat');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'und sprach: \'So wird der Mann den Vater und die Mutter verlassen und sich seinem Weib verbinden, und diese zwei werden zu einem Fleische werden?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'So sind sie also nicht mehr zwei, vielmehr ein einziges Fleisch. Was aber Gott vereinigt hat, das soll der Mensch nicht trennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Da sagten sie zu ihm: \"Warum hat aber dann Moses geboten, den Scheidebrief zu geben und sie zu entlassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Er sprach zu ihnen: \"Weil Moses wegen eurer Herzenshärte es euch gestattet hat, eure Weiber zu entlassen, ursprünglich aber war es nicht so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Ich aber sage euch: Jeder, der sein Weib entläßt - auch nicht im Falle des Ehebruchs - und eine andere heiratet, der bricht die Ehe. Und wer eine Entlassene heiratet, bricht die Ehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Da sprachen seine Jünger zu ihm: \"Wenn so zwischen Mann und Weib das Rechtsverhältnis ist, dann ist nicht gut zu heiraten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Er aber sprach zu ihnen: \"Nicht alle fassen dieses Wort, vielmehr nur jene, denen es gegeben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'So gibt es Menschen, die vom Mutterschoße her unfähig sind zur Ehe; dann gibt es solche, die durch Menschen so geworden sind, und auch solche gibt es, die sich von sich aus des Himmelreiches wegen der Ehe enthalten. Wer es fassen kann, der fasse es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Damals brachte man ihm Kinder, damit er seine Hände auf sie lege und bete. Allein die Jünger fuhren sie hart an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Doch Jesus sprach: \"Lasset die Kinder und wehret es ihnen nicht, zu mir zu kommen; denn ihrer ist das Himmelreich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Dann legte er ihnen die Hände auf und ging weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Siehe, da trat einer auf ihn zu und fragte: \" Guter Meister, was muß ich Gutes tun, um zum ewigen Leben zu gelangen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Er sprach zu ihm: \"Was fragst du mich über das Gute? Einer ist der Gute Gott. Doch willst du zum Leben eingehen, so halte die Gebote.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '\"Welche?\" fragte dieser weiter. Und Jesus sprach: \"Zum Beispiel: \'Du sollst nicht töten!\' \'Du sollst nicht ehebrechen!\' \'Du sollst nicht stehlen!\' \'Du sollst kein falsches Zeugnis geben!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, '\'Du sollst Vater und Mutter ehren!\' \'Du sollst deinen Nächsten lieben wie dich selbst!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Da sprach der Jüngling zu ihm: \"All dies habe ich von Jugend an gehalten. Was fehlt mir noch?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Und Jesus sprach zu ihm: \"Willst du vollendet sein, geh hin, verkaufe deine Habe und schenke sie den Armen; du wirst dann einen Schatz im Himmel haben; dann komm und folge mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Als der Jüngling dies hörte, ging er betrübt von dannen; denn er besaß viele Güter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Und Jesus sprach zu seinen Jüngern: \"Wahrlich, sage ich euch: Ein Reicher wird nur schwer ins Himmelreich gelangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Ich wiederhole es: Es geht viel leichter ein Kamel durchs Nadelöhr, als ein Reicher in das Gottesreich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Als die Jünger dies hörten, wurden sie sehr bestürzt und fragten: \"Wer kann da noch gerettet werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Da sah sie Jesus an und sprach zu ihnen: \"Bei den Menschen ist es freilich unmöglich; jedoch bei Gott ist alles möglich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Und Petrus nahm das Wort und sprach zu ihm: \"Siehe, wir haben alles verlassen und sind dir nachgefolgt; was werden wir dafür erhalten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Und Jesus sprach zu ihnen: \"Wahrlich, sage ich euch: Auch ihr, die ihr mir gefolgt seid, werdet in der neuen Welt, wenn der Menschensohn auf dem Throne seiner Herrlichkeit sitzt, auf zwölf Thronen sitzen und die zwölf Stämme Israels regieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Wer immer Häuser, Brüder, Schwestern, Vater, Mutter oder Kinder und Äcker um meines Namens willen verläßt, der wird Hundertfältiges erhalten und ewiges Leben erben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Viele aber werden aus Ersten Letzte und aus Letzten Erste werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '\"Das Himmelreich ist nämlich einem Hausherrn gleich, der früh am Morgen ausging, Arbeiter für seinen Weinberg zu dingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Er einigte sich mit den Arbeitern auf einen Denar für den Tag und schickte sie in seinen Weinberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Als er zur dritten Stunde ausging, da sah er andere müßig auf dem Markte stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Und er sprach zu ihnen: \'Geht auch ihr in meinen Weinberg! Ich will euch geben, was sich gehört\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'So gingen diese hin. Und um die sechste und die neunte Stunde ging er wieder aus und machte es ebenso.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Als er nun um die elfte Stunde ausging, da fand er andere dastehen; er fragte sie: \'Was steht ihr müßig hier den ganzen Tag?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Sie gaben ihm zur Antwort: \'Weil niemand uns gedungen hat.\' Er sprach zu ihnen: \'So geht auch ihr in meinen Weinberg!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Des Abends sprach der Herr des Weinbergs zu seinem Verwalter: \'Ruf die Arbeiter und zahle ihnen ihren Lohn, von den Letzten bis zu den Ersten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Da kamen jene von der elften Stunde, und sie bekamen je einen Denar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Es kamen auch die Ersten; sie meinten, sie würden mehr empfangen. Jedoch auch sie bekamen je nur einen Denar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Sie nahmen ihn, doch murrten sie wider den Hausherrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Sie sagten: \'Nur eine einzige Stunde haben diese Letzten da gearbeitet, und du hast sie uns gleichgestellt, die wir die Last und Hitze des Tages ertragen haben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Da sprach er zu dem einen unter ihnen: \'Freund! Ich tue dir kein Unrecht. Hast du dich nicht mit mir auf einen Denar geeinigt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Nimm, was dein ist und geh! Jedoch auch diesem Letzten will ich geben wie dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Oder kann ich mit meinem Eigentum nicht machen, was ich will? Oder ist dein Auge neidisch, weil ich gut bin?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'So werden die Letzten Erste und die Ersten Letzte. Denn viele sind berufen, wenige aber erwählt. \"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Und Jesus zog nach Jerusalem hinauf. Da nahm er die zwölf Jünger auf die Seite, und unterwegs sprach er zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '\"Seht, wir ziehen nach Jerusalem hinauf. Der Menschensohn wird den Oberpriestern und den Schriftgelehrten überliefert werden; sie werden ihn zum Tode verdammen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'und den Heiden überliefern zum Verspotten, zum Geißeln und zum Kreuzigen. Doch am dritten Tage wird er auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Da trat die Mutter der Zebedäussöhne mit ihren Söhnen vor ihn hin, fiel vor ihm nieder und trug ihm eine Bitte vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Er fragte sie: \"Was willst du?\" Da gab sie ihm zur Antwort: \"Sprich, daß diese meine beiden Söhne in deinem Reiche der eine dir zur Rechten, der andre dir zur Linken sitze.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Doch Jesus gab zur Antwort: \"Ihr wisset nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken muß?\" Sie sagten zu ihm: \"Wir können es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Er sprach zu ihnen: \"Meinen Kelch zwar werdet ihr trinken, die Sitze zu meiner Rechten und zu meiner Linken aber, die kann nicht ich vergeben; denn sie gehören denen, für die sie von meinem Vater schon bestimmt sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Als dies die anderen Zehn hörten, wurden sie der beiden Brüder wegen unwillig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Doch Jesus rief sie zu sich her und sprach: \"Ihr wißt: Die Fürsten der Heidenvölker wollen den Herrn spielen und lassen ihre Untertanen ihre Macht fühlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Bei euch aber wird es nicht so sein: Wer unter euch ein Großer werden will, sei euer Diener,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'und wer unter euch will Erster sein, sei euer Knecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Wie auch der Menschensohn nicht gekommen ist, bedient zu werden, vielmehr zu dienen und sein Leben als Sühne für viele hinzuopfern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Sie zogen aus Jericho hinaus, und eine große Menge folgte ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Und siehe, am Wege saßen zwei Blinde. Als sie vernahmen: \"Jesus kommt vorüber\", da riefen sie mit lauter Stimme: \"Herr, erbarme dich unser, du Sohn Davids!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Die Menge aber fuhr sie an, sie sollten schweigen. Sie aber riefen noch lauter: \"Herr, erbarme dich unser, du Sohn Davids!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Darauf blieb Jesus stehen, rief sie her und sprach: \"Was wollt ihr, daß ich euch tue?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Sie baten ihn: \"Herr, daß sich unsere Augen öffnen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Voll Mitleid rührte Jesus ihre Augen an; und alsbald konnten sie sehen und folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Sie näherten sich Jerusalem und kamen nach Bethphage am Ölberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Dort sandte Jesus zwei von seinen Jüngern mit dem Auftrag fort: \"Geht in das Dorf, das vor euch liegt. Sogleich werdet ihr eine Eselin angebunden finden und bei ihr ein Füllen. Bindet diese los und bringt sie mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Und sollte es jemand euch verwehren, so sagt: \'Der Herr braucht sie; er wird sie sogleich wieder zurücksenden\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Dies ist geschehen, damit erfüllt würde, was durch den Propheten gesprochen ward:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '\"Sagt der Tochter Sion: \'Siehe, dein König kommt zu dir, sanftmütig und auf einem Esel reitend, auf einem Füllen, auf dem Jungen eines Lasttiers.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Die Jünger gingen weg und taten so, wie ihnen Jesus aufgetragen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Sie brachten die Eselin mit ihrem Füllen, legten ihre Kleider auf sie, und er setzte sich darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Sehr viele aus dem Volke breiteten ihre Kleider auf den Weg, andere hieben Zweige von den Bäumen und streuten sie auf den Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Die Scharen, die vor und hinter ihm herzogen, riefen laut: \"Hosanna dem Sohne Davids! Gepriesen sei, der im Namen des Herrn kommt! Hosanna in der Höhe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Bei seinem Einzug in Jerusalem geriet die ganze Stadt in Aufregung. Man fragte: \"Wer ist dieser?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Die Scharen aber sagten: \"Das ist der Prophet Jesus aus Nazareth in Galiläa.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Alsdann begab sich Jesus in den Tempel Gottes und jagte alle fort, die im Tempel kauften und verkauften. Auch stieß er die Tische der Wechsler und die Bänke der Taubenhändler um');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'und sprach zu ihnen: \"Es steht geschrieben: \'Mein Haus soll ein Bethaus heißen; ihr aber macht es zu einer Räuberhöhle.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Dann traten Blinde und Lahme im Tempel vor ihn hin, und er heilte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Als die Oberpriester und die Schriftgelehrten die Wunder sahen, die er wirkte, und die Kinder, die im Tempel riefen: \"Hosanna dem Sohne Davids!\", wurden sie unwillig');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'und sprachen zu ihm: \"Hörst du, was diese rufen?\" Und Jesus entgegnete ihnen: \"Gewiß habt ihr noch nie gelesen: \'Du läßt dir aus dem Munde von Kindern und Säuglingen lobsingen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Damit ließ er sie stehen und verließ die Stadt, ging nach Bethanien hinaus und blieb dort über Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Am frühen Morgen ging er wieder in die Stadt; da empfand er Hunger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Er sah am Weg einen Feigenbaum, ging auf ihn zu, fand aber nichts daran als Blätter. Er sprach zu ihm: \"In Ewigkeit sollst du nicht mehr Frucht tragen!\" Im Nu war der Feigenbaum verdorrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Die Jünger sahen dies und sprachen voll Verwunderung: \"Wie doch der Feigenbaum augenblicklich verdorrt ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus sprach zu ihnen: \"Wahrlich, ich sage euch: Wenn ihr Glauben habt und nicht zweifelt, werdet ihr nicht allein das zustande bringen, was an dem Feigenbaum geschehen ist; vielmehr, wenn ihr zu diesem Berge saget: \'Heb¥ dich hinweg und stürze dich ins Meer\', so wird es geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Ja, alles, was ihr im gläubigen Gebet erflehet, werdet ihr empfangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Dann ging er in den Tempel. Und während er dort lehrte, traten die Oberpriester und die Ältesten des Volkes vor ihn hin und fragten: \"In wessen Vollmacht tust du dies? Wer hat dir denn das Recht dazu gegeben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus sprach zu ihnen: \"Auch ich will euch etwas fragen. Gebt ihr mir Antwort, dann will auch ich euch sagen, in wessen Vollmacht ich dies tue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Woher kam die Johannestaufe? Kam sie vom Himmel oder von den Menschen?\" Da überlegten sie bei sich:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, '\"Sagen wir \'vom Himmel\', so wird er uns fragen: \'Warum habt ihr ihm dann nicht geglaubt?\' Und sagen wir \'von Menschen\', so haben wir das Volk zu fürchten; denn alle halten Johannes für einen Propheten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Und so erwiderten sie Jesus: \"Wir wissen es nicht.\" Da sprach er zu ihnen: \"Dann sage auch ich euch nicht, in wessen Vollmacht ich dies tue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Jedoch was dünkt euch? Ein Mann hatte zwei Söhne. Da sprach er zu dem einen: \'Mein Sohn, geh, arbeite heute im Weinberg!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Der sagte: \'Jawohl, Herr.\' Doch er ging nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Dann sprach er ebenso zum andern. Und dieser gab zur Antwort: \'Ich mag nicht.\' Doch nachher reute es ihn, und er ging hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Welcher von beiden hat den Willen des Vaters erfüllt?\" \"Der Letztere\" sagten sie. Und Jesus sprach zu ihnen: \"Wahrlich, ich sage euch: Zöllner und Dirnen kommen noch vor euch ins Gottesreich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Johannes kam zu euch auf dem Wege der Gerechtigkeit, und trotzdem habt ihr ihm nicht geglaubt. Die Zöllner und Dirnen aber haben ihm geglaubt. Ihr habt dies gesehen, und dennoch wurdet ihr nicht andern Sinnes, daß ihr ihm wenigstens nachher geglaubt hättet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Vernehmet ein anderes Gleichnis! Es war ein Hausherr; dieser pflanzte einen Weinberg, umgab ihn mit einem Zaune, grub in ihm eine Kelter und erbaute einen Turm. Darauf verpachtete er ihn an Winzer und ging nach auswärts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Es kam die Zeit der Lese. Da schickte er seine Knechte zu den Winzern, um den Ertrag des Weinbergs zu empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Jedoch die Winzer packten seine Knechte, mißhandelten den einen, töteten den andern und steinigten den dritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Er schickte nochmals andre Knechte, mehr als zuvor. Jedoch sie machten es ihnen ebenso.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Zuletzt aber schickte er seinen Sohn zu ihnen, weil er dachte: Vor meinem Sohne werden sie wohl Achtung haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Als aber die Winzer den Sohn erblickten, sprachen sie unter sich: \'Das ist der Erbe. Kommt, lasset uns ihn töten; dann wird sein Erbteil unser sein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Und sie ergriffen ihn, warfen ihn zum Weinberg hinaus und brachten ihn ums Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Wenn nun der Herr des Weinbergs kommt, was wird er wohl mit jenen Winzern tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Sie sagten ihm: \"Er wird die Elenden elendig verderben, den Weinberg aber andren Winzern überlassen, die ihm den Ertrag zur rechten Zeit abliefern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Und Jesus sprach zu ihnen: \"Habt ihr noch niemals in der Schrift gelesen: \'Der Stein, den die Bauleute verworfen haben, der ist zum Schlußstein geworden; dies ist durch den Herrn geschehen, und es ist wunderbar in unsern Augen\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'So sage ich euch denn: Das Gottesreich wird euch genommen und einem Volke gegeben werden, das rechte Früchte bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Wer auf diesen Stein fällt, der wird zerschmettert werden, auf wen er aber fällt, den wird er zermalmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Die Oberpriester und die Pharisäer, die seine Gleichnisse mitanhörten, erkannten, daß er sie selber meine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Sie hätten sich seiner gern bemächtigt; allein sie fürchteten das Volk, weil es ihn für einen Propheten hielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Und Jesus redete nochmals in Gleichnissen zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '\"Das Himmelreich ist einem Könige gleich, der seinem Sohne Hochzeit hielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Er sandte seine Knechte aus, um die Eingeladenen zum Feste herbeizurufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Doch diese wollten nicht kommen. Er schickte nochmals andere Knechte mit dem Auftrag aus: \'Sagt den Geladenen: Seht, mein Gastmahl ist bereitet, meine Ochsen und das Mastvieh sind geschlachtet; alles steht bereit; kommt zur Hochzeit! \'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Doch diese gingen unbekümmert weiter: Der eine auf seinen Acker, ein anderer in sein Geschäft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Der Rest fiel über seine Knechte her, mißhandelte und erschlug sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Da ward der König zornig. Er schickte seine Heere hin, ließ jene Mörder töten und ihre Stadt in Brand stecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Darauf sprach er zu seinen Knechten: \'Das Hochzeitsmahl ist bereitet; doch die Geladenen waren dessen nicht wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'So geht denn an die Straßenausgänge und ruft zur Hochzeit, wen immer ihr findet.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Die Knechte gingen auf die Straßen und brachten alle, die sie gerade fanden, Böse und Gute; und der Hochzeitssaal füllte sich mit Gästen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Der König trat herein, um sich die Gäste anzusehen. Dort sah er einen Menschen, der kein hochzeitliches Gewand anhatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Er sprach zu ihm: \'Freund, wie bist du ohne hochzeitliches Gewand hereingekommen?\' Doch dieser schwieg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Darauf gebot der König seinen Knechten: \'Bindet ihn an Füßen und an Händen und werft ihn in die äußerste Finsternis hinaus; dort wird Heulen und Zähneknirschen sein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Denn viele sind berufen, wenige aber auserwählt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Die Pharisäer gingen darauf hin und überlegten, wie sie ihm mit einer Frage eine Falle stellen könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Sie schickten ihre Schüler mit den Herodianern zu ihm mit der Frage: \"Meister, wir wissen, daß du wahrhaftig bist und den Weg Gottes in Wahrheit lehrst; du fragst nach niemand, denn du siehst nicht auf die Person der Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'So sage uns denn, was meinst du wohl: Darf man dem Kaiser Steuer zahlen oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Doch Jesus erkannte ihre Bosheit und sprach: \"Warum versuchet ihr mich, ihr Heuchler?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Zeigt mir die Steuermünze!\" Da reichten sie ihm einen Denar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Er fragte sie: \"Wessen Bild und Aufschrift ist dies?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Sie gaben ihm zur Antwort: \"Des Kaisers.\" Da sagte er zu ihnen: \"So gebet also dem Kaiser, was des Kaisers, und Gott, was Gottes ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Als sie dies hörten, staunten sie, verließen ihn und gingen weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Am selben Tage kamen zu ihm Sadduzäer - diese leugnen, daß es eine Auferstehung gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Sie sagten: \"Meister, Moses hat geboten: \'Wenn einer stirbt, ohne daß er Kinder hinterläßt, dann soll sein Bruder dessen Weib heiraten und dem Bruder Nachkommen erwecken.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Nun waren bei uns sieben Brüder. Der erste heiratete und starb. Und weil er keine Kinder hatte, hinterließ er sein Weib seinem Bruder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Und ebenso erging es dem zweiten, dem dritten bis zum siebten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Zuletzt von allen starb das Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Wem von den sieben wird sie als Weib bei der Auferstehung angehören; denn alle haben sie gehabt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus antwortete ihnen: \"Ihr seid im Irrtum. Denn ihr versteht weder die Schrift noch die Allmacht Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Die Auferstandenen heiraten nicht und werden auch nicht mehr verheiratet; sie sind vielmehr wie Engel Gottes im Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Und weiter, über die Auferstehung von den Toten habt ihr da den Ausspruch Gottes nicht gelesen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '\'Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs\'? Gott ist doch nicht ein Gott der Toten, sondern der Lebendigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Die Scharen hörten dies und staunten über seine Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Als die Pharisäer hörten, daß er so die Sadduzäer zum Schweigen gebracht hatte, kamen sie zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Da wollte ihn einer aus ihnen, ein Gesetzeslehrer, versuchen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'er fragte ihn: \"Meister, welches Gebot im Gesetz ist ein großes?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Er sprach zu ihm: \"\'Du sollst den Herrn, deinen Gott, lieben, aus deinem ganzen Herzen, aus deiner ganzen Seele, aus deinem ganzen Gemüte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Dies ist das größte und das erste Gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Ein anderes aber ist diesem gleich: \'Du sollst deinen Nächsten lieben wie dich selbst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'An diesen beiden Geboten hängt das ganze Gesetz und die Propheten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Wie nun die Pharisäer beieinander waren, da legte ihnen Jesus die Frage vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '\"Was haltet ihr von Christus? Wessen Sohn ist er?\" Sie gaben ihm zur Antwort: \"Davids Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Er fragte sie weiter: \"Wie kann aber David im Geist ihn \'Herr\' nennen, da, wo er sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '\'Es sprach der Herr zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde dir zu Füßen lege \'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Wenn David ihn also \'Herr\' nennt, wie ist er dann sein Sohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Und niemand konnte ihm darauf ein Wort erwidern; auch wagte es von jenem Tag an keiner mehr, ihn überhaupt zu fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Darauf sprach Jesus zu den Scharen und zu seinen Jüngern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '\"Auf dem Stuhle des Moses sitzen die Schriftgelehrten und die Pharisäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Tut und haltet alles, was sie euch verkünden; jedoch nach ihren Werken dürft ihr euch nicht richten. Sie reden nämlich nur und handeln nicht danach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Sie binden unerträglich schwere Lasten und legen sie den Menschen auf die Schultern; sie selber aber wollen nicht einmal mit ihrem Finger daran rühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Sie tun auch alle ihre Werke, um von den Menschen angestaunt zu werden. So machen sie ihre Gebetsriemen breit und ihre Kleiderquasten lang;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'bei den Mählern lieben sie die Ehrenplätze und die Ehrensitze in den Synagogen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'den Gruß auf den öffentlichen Plätzen und lassen von den Leuten gern sich \'Rabbi\' heißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ihr sollt euch nicht \'Rabbi\' nennen lassen. Nur einer ist ja euer Lehrer, ihr aber seid alle Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Auch sollt ihr auf Erden keinen aus euch \'Vater\' nennen. Nur einer ist euer Vater, der im Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Auch lasset euch nicht Lehrmeister nennen. Nur einer ist euer Lehrmeister: Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Der größte unter euch sei euer Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Denn wer sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr verschließt das Himmelreich den Menschen; ihr selber geht nicht hinein, noch laßt ihr die hineingehen, die gerne möchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '\"Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr verzehret die Häuser der Witwen und sagt dafür lange Gebete her. Ihr werdet dafür eine härtere Strafe erhalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr zieht über Land und Meer, um einen einzigen Proselyten zu gewinnen; und ist er es geworden, dann macht ihr ihn zum Sohn der Hölle, noch einmal so schlimm als ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Wehe euch, ihr blinden Führer! Ihr sagt, wenn einer beim Tempel schwöre, das gelte nichts; wer aber bei dem Gold des Tempels schwört, der sei dadurch verpflichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Ihr Toren und Blinde! Was ist denn wichtiger: das Gold oder der Tempel, der das Gold erst heiligt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Dann sagt ihr, wenn einer beim Altare schwöre, das gelte nichts, wer aber bei der Opfergabe, die darauf liegt, schwört, der sei dadurch verpflichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Ihr Blinden! Was ist wichtiger: die Opfergabe oder der Altar, der erst die Gabe heiligt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Wer demnach beim Altare schwört, der schwört bei diesem und bei allem, was auf ihm liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Und wer beim Tempel schwört, der schwört bei diesem und bei dem, der darin wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Und wer beim Himmel schwört, der schwört beim Throne Gottes und bei dem, der darauf sitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr verzehntet Minze, Anis, Kümmel; die wichtigeren Gebote aber übersehet ihr: Gerechtigkeit, Güte, Treue. Das eine soll man tun, das andere jedoch nicht lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Ihr blinden Führer! Ihr seiht Mücken und verschlingt Kamele.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr reinigt das Äußere des Bechers und der Schüssel, das Innere aber laßt ihr strotzen von Raub und Unersättlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Du blinder Pharisäer! Mach doch zuerst den Becher und die Schüssel innen rein, dann wird ihre Außenseite gleichfalls rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr gleicht übertünchten Gräbern, die nach außen hin zwar schön erscheinen, inwendig aber voll sind von Totenknochen und jedem anderen Unrat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'So erscheint auch ihr nach außen hin den Menschen als gerecht; inwendig aber seid ihr voll von Heuchelei und Schlechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Wehe euch, ihr Schriftgelehrten und ihr Pharisäer! Heuchler! Ihr bauet den Propheten Grabdenkmäler und schmücket die Denkstätten der Gerechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Ihr saget: \'Hätten wir zu Zeiten unserer Väter gelebt, wir hätten uns am Blute der Propheten nicht mitschuldig gemacht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Nun, so bezeuget ihr euch selbst, daß ihr Söhne der Prophetenmörder seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Ihr macht das Maß eurer Väter voll');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Schlangen! Natternbrut! Wie werdet ihr der Verdammung zur Hölle entfliehen können?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Seht, gerade deshalb sende ich zu euch Propheten, Weisheitslehrer und Schriftgelehrte. Die einen werdet ihr ermorden und kreuzigen, die anderen in euren Synagogen geißeln und sie von Stadt zu Stadt hetzen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'damit über euch all das unschuldige Blut komme, das je auf Erden vergossen ward, vom Blute des gerechten Abel an bis auf das Blut des Zacharias, des Sohnes des Barachias, den ihr zwischen Tempel und Altar ermordet habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Wahrlich, ich sage euch: Alles dies kommt über dieses Geschlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, das du die Propheten mordest und jene steinigst, die zu dir gesandt wurden! Wie oft wollte ich deine Kinder sammeln, wie eine Henne ihre Küchlein unter ihre Flügel sammelt, allein, ihr habt nicht gewollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Seht, euer Haus wird euch verwüstet überlassen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Jedoch ich sage euch: Ihr werdet mich von jetzt an nicht mehr sehen, bis daß ihr sprechet: \'Gepriesen sei, der da kommt im Namen des Herrn!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Jesus verließ darauf den Tempel und wollte weitergehen. Da traten seine Jünger zu ihm und wiesen auf die Tempelbauten hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Er aber sprach zu ihnen: \"Ihr seht wohl all dies? Wahrlich, ich sage euch: Hier wird kein Stein auf dem andern bleiben, der nicht wird abgebrochen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Dann setzte er sich auf dem Ölberg nieder. Seine Jünger traten allein vor ihn und baten: \"Sage uns, wann wird denn dies geschehen? Welches wird das Zeichen deiner Ankunft sein und das der Weltvollendung?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Und Jesus sprach zu ihnen: \"Sehet zu, daß euch niemand verführe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Viele werden unter meinem Namen kommen und behaupten: \'Ich bin der Christus.\' Und sie werden viele täuschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Ihr werdet von Kriegen und von Kriegsgerüchten hören. Gebt acht und laßt euch nicht erschrecken. All dies muß geschehen, doch es ist noch nicht das Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Denn Volk wird sich gegen Volk erheben und Reich gegen Reich, Pest, Hunger und Erdbeben werden an vielen Orten sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Dies alles ist aber erst der Anfang der Wehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Dann wird man euch der Drangsal überliefern und euch töten; bei allen Völkern werdet ihr um meines Namens willen gehaßt sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Es werden viele daran Anstoß nehmen und sich gegenseitig verraten und sich hassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Auch viele falsche Propheten werden sich erheben und viele verführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Und weil die Gesetzlosigkeit übergroß geworden ist, wird in vielen die Liebe erkalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Doch wer ausharrt bis ans Ende, der wird gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Auch wird dieses Evangelium vom Reiche in der ganzen Welt verkündet werden zum Zeugnisse für alle Völker. Und dann erst kommt das Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Wenn ihr dann den Greuel der Verwüstung, von dem der Prophet Daniel gesprochen, am heiligen Ort herrschen seht, - der Leser möge dies wohl beachten -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'dann fliehe ins Gebirge, wer in Judäa ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Wer auf dem Dache ist, der steige nicht herab, sein Eigentum aus seinem Haus zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Wer auf dem Felde ist, der wende sich nicht um, sein Oberkleid zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Doch wehe den Frauen, die in jenen Tagen ein Kindlein unterm Herzen oder an der Brust tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Betet, daß eure Flucht nicht in den Winter oder auf den Sabbat falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Es wird dann eine solche Trübsal sein, wie sie seit Anbeginn der Welt bis jetzt noch nie gewesen ist, noch jemals sein wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Ja, wenn jene Tage nicht abgekürzt würden, würde nichts Sterbliches gerettet werden. Doch um der Auserwählten willen werden jene Tage abgekürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Wenn euch dann jemand sagt: \'Siehe, hier ist Christus oder dort\', glaubet es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Denn falsche Christusse und falsche Propheten werden sich erheben; sie werden große Zeichen und Wunder tun, so daß, wenn es möglich wäre, sogar die Auserwählten irregeführt würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Seht, ich sage es euch vorher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Wenn man zu euch dann sagt: \'Seht, er ist in der Steppe\', geht nicht hinaus! \'Seht, er ist in den Gemächern\', glaubt es nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Denn, wie der Blitz im Osten aufflammt und bis zum Westen leuchtet, so wird es auch mit der Ankunft des Menschensohnes sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Da, wo ein Aas ist, sammeln sich die Geier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Sogleich nach der Drangsal jener Tage wird sich die Sonne verfinstern, der Mond wird seinen Schein nicht mehr geben; die Sterne werden vom Himmel fallen, die Kräfte des Himmels erschüttert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Dann wird das Zeichen des Menschensohnes am Himmel sichtbar werden; dann werden alle Völker auf derErde wehklagen und den Menschensohn auf den Wolken des Himmels kommen sehen mit großer Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Er wir seine Engel aussenden mit gewaltigem Posaunenschall; sie werden seine Auserwählten sammeln von den vier Richtungen des Windes, von einem Ende des Himmels bis zum anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Vom Feigenbaum aber lernt das Gleichnis: Wenn seine Zweige saftig werden und er Blätter treibt, dann wisset ihr: der Sommer ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'So sollt auch ihr, wenn ihr all dies seht, erkennen, daß es dicht vor der Türe steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis all dies geschehen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Himmel und Erde werden vergehen, doch meine Worte werden nicht vergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Von jenem Tag aber und der Stunde weiß niemand etwas, nicht einmal die Engel des Himmels, als allein der Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Wie die Zeit des Noe, so wird die Ankunft des Menschensohnes sein:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Gleichwie man in den Tagen vor der Sintflut aß und trank, zur Ehe gab und nahm bis zu dem Tage, da Noe in die Arche ging,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'und man nicht zur Besinnung kam, bis die Flut hereinbrach und sie alle mit sich fortriß, so wird auch die Ankunft des Menschensohnes sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Da werden zwei auf dem Felde sein: der eine wird mitgenommen, der andre bleibt zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Es werden zwei an der Mühle mahlen: es wird die eine mitgenommen, die andre bleibt zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'So seid denn wachsam; denn ihr wisset nicht, an welchem Tag euer Herr erscheint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Das aber bedenket: Wenn der Hausherr wüßte, zu welcher Stunde in der Nacht der Dieb kommt, dann würde er wohl wachen und ihn nicht in sein Haus einbrechen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'So seid auch ihr bereit! Denn der Menschensohn kommt zu einer Stunde, da ihr es nicht vermutet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Wer ist der treue und verständige Knecht, den der Herr über sein Gesinde setzt, damit er ihm zur rechten Zeit die Nahrung reiche?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Wohl dem Knecht, den der Herr bei seiner Heimkehr also handelnd antrifft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Wahrlich, ich sage euch: Er wird ihn zum Verwalter aller seiner Güter machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Doch würde jener böse Knecht bei sich denken: \'Mein Herr bleibt noch länger aus\';');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'und würde er seine Mitknechte verprügeln, wollte er mit Trunkenbolden essen und zechen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'alsdann wird der Herr eines solchen Knechtes erscheinen an einem Tage, da er es nicht erwartet, zu einer Stunde, die er nicht kennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Er wird ihn dann in Stücke hauen und ihm bei den Heuchlern seinen Platz anweisen; dort wird Heulen und Zähneknirschen sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '\"Dann wird das Himmelreich zehn Jungfrauen gleichen, die mit ihren Lampen dem Bräutigam und der Braut entgegengingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Fünf aus ihnen waren töricht und fünf klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Die törichten hatten zwar ihre Lampen bei sich, aber ohne Öl;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'und die klugen trugen in Krügen noch Öl für die Lampen bei sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Der Bräutigam blieb länger aus, und alle wurden schläfrig und nickten schließlich ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Da, um Mitternacht, erscholl der Ruf: \'Der Bräutigam! Auf! Geht ihm entgegen!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alle jene Jungfrauen erhoben sich und machten ihre Lampen zurecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Da baten die törichten die klugen: \'Gebt uns von euerm Öl! Unsere Lampen gehen aus.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Die klugen aber sagten: \'Das geht nicht an; es möchte sonst für uns und für euch nicht reichen. Geht lieber zu den Krämern und kaufet euch.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Sie gingen hin, um zu kaufen. Da kam der Bräutigam. Die bereit waren, gingen mit ihm zur Hochzeit ein, und die Türe ward geschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Später kamen auch die andern Jungfrauen; sie riefen: \'Herr, Herr, mach uns auf!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Doch er erwiderte: \'Wahrlich, ich sage euch: Ich kenne euch nicht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'So seid denn wachsam, weil ihr weder den Tag noch die Stunde wisset.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Ferner: Ein Mann wollte in die Fremde ziehen. Da ließ er seine Knechte kommen und übergab ihnen sein Vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Dem einen gab er fünf Talente, dem andern zwei und einem dritten eines, nach seinen Fähigkeiten einem jeden. Dann reiste er ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Der fünf Talente erhalten hatte, ging sogleich hin, trieb damit Handel und gewann noch fünf weitere dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Auch der mit seinen zwei gewann noch zwei andre dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Der aber, der nur das eine empfangen hatte, ging hin und vergrub das Geld seines Herrn im Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Nach langer Zeit kam der Herr jener Knechte zurück und hielt mit ihnen Abrechnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Der mit den fünf Talenten kam herein und brachte noch fünf weitere Talente mit. Er sprach: \'Herr, fünf Talente hast du mir übergeben, sieh, weitere fünf habe ich dazugewonnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Da sprach sein Herr zu ihm: \'Recht so, du guter und getreuer Knecht! In wenigem bist du getreu gewesen, ich will dich über vieles setzen; gehe ein in die Freude deines Herrn!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Da trat der mit den zwei Talenten ein. Er sprach: \'Herr, zwei Talente hast du mir übergeben, sieh, weitere zwei habe ich dazugewonnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Da sprach sein Herr zu ihm: \'Recht so, du guter und getreuer Knecht! In wenigem bist du getreu gewesen, ich will dich über vieles setzen; gehe ein in die Freude deines Herrn!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Endlich kam auch der, der ein Talent erhalten hatte. Er sprach: \'Herr, ich kenne dich: Du bist ein harter Mann; du erntest, wo du nicht gesät hast, wo du nichts eingesetzt hast, willst du gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Ich hatte Angst, ging hin und vergrub dein Talent im Boden; sieh, hier hast du wiederum, was dir gehört.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Da sprach sein Herr zu ihm: \'Du böser und fauler Knecht! Du wußtest, daß ich ernte, wo ich nicht gesät, gewinnen will, wo ich nichts eingesetzt habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Da hättest du mein Geld zu den Wechslern bringen sollen, dann hätte ich nach meiner Rückkehr das Meinige mit Zinsen wiederum bekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'So nehmt ihm das Talent und gebt es dem, der zehn hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Denn jedem, der hat, wird gegeben werden, und er wird im Überfluß haben. Doch wer nichts hat, dem wird auch das, was er besitzt, genommen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Den nichtsnutzigen Knecht aber werft in die Finsternis hinaus; dort wird Heulen und Zähneknirschen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Wenn der Menschensohn in seiner Herrlichkeit erscheint und mit ihm alle seine Engel, dann wird er sich auf dem Throne seiner Herrlichkeit niederlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Alle Völker werden vor ihm versammelt werden. Er wird sie voneinander scheiden, wie der Hirte die Schafe von den Böcken scheidet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Die Schafe wird er auf seine rechte Seite stellen, die Böcke aber auf die linke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Dann wird der König die zu seiner Rechten anreden: \'Kommt her, ihr Gesegneten meines Vaters! Nehmt in Besitz das Reich, das euch seit Grundlegung der Welt bereitet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Denn ich war hungrig, und ihr habt mich gespeist; ich war durstig, und ihr habt mich getränkt; ich war Fremdling, und ihr habt mich beherbergt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'ich war nackt, und ihr habt mich bekleidet; ich war krank, und ihr habt mich besucht; ich war im Gefängnis, und ihr seid zu mir gekommen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Da werden ihn die Gerechten fragen: \'Herr, wann sahen wir dich hungrig und haben dich gespeist, oder durstig und gaben dir zu trinken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Wann sahen wir dich fremd und haben dich beherbergt, oder nackt und haben dich bekleidet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Wann sahen wir dich krank oder im Gefängnis und sind zu dir gekommen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Da wird ihnen der König antworten: \'Wahrlich, ich sage euch: Was ihr einem der geringsten meiner Brüder getan habt, das habt ihr mir getan.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Dann wird er auch zu denen auf der Linken sagen: \'Hinweg von mir, Verfluchte, in das ewige Feuer, das dem Teufel samt seinen Engeln bereitet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Denn ich war hungrig, und ihr habt mich nicht gespeist; ich war durstig, und ihr habt mich nicht getränkt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'ich war fremd, und ihr habt mich nicht beherbergt; ich war nackt, und ihr habt mich nicht bekleidet; ich war krank und im Gefängnis, und ihr habt mich nicht besucht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Auch diese werden nunmehr fragen: \'Herr, wann sahen wir dich hungrig oder durstig, wann fremd und nackt und krank und im Gefängnis und hätten dir nicht gedient?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Da wird er ihnen antworten: \'Wahrlich, ich sage euch: Was ihr einem dieser meiner Geringsten nicht getan habt, das habt ihr auch mir nicht getan.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Und diese werden in die ewige Pein eingehen, die Gerechten aber in das ewige Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Als Jesus alle diese Reden beendet hatte, sprach er zu seinen Jüngern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '\"Ihr wißt, daß in zwei Tagen Ostern ist; da wird der Menschensohn zur Kreuzigung überliefert werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'In der gleichen Zeit kamen die Oberpriester und die Ältesten des Volkes zusammen im Palast des Hohenpriesters, der Kaiphas hieß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Sie faßten den Beschluß, Jesus ganz unauffällig zu ergreifen und zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Doch sagten sie: \"Nicht am Festtag, es könnte sonst das Volk in Aufruhr kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Als Jesus in Bethanien weilte im Hause Simons des Aussätzigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'da trat ein Weib zu ihm; sie trug ein Gefäß aus Alabaster voll kostbaren Salböls. Dieses goß sie, als er zu Tische lag, über seinem Haupte aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Als die Jünger dies sahen, wurden sie unwillig und sprachen: \"Wozu diese Verschwendung?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Man hätte es um teures Geld verkaufen und den Erlös den Armen geben können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Doch Jesus, der es wohl bemerkte, sprach zu ihnen: \"Was kränkt ihr dieses Weib? Sie hat ein gutes Werk an mir getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Die Armen habt ihr allezeit bei euch, mich aber habt ihr nicht allezeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Wenn sie dieses Salböl über meinen Leib ausgoß, so tat sie es für mein Begräbnis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Wahrlich, ich sage euch: Wo immer in der ganzen Welt dieses Evangelium verkündet wird, da wird man auch erzählen, was sie getan, ihr zum Gedächtnis\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Dann ging einer von den Zwölfen, Judas Iskariot mit Namen, zu den Oberpriestern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'und sprach: \"Was wollt ihr mir geben, wenn ich ihn euch verrate?\" Sie boten ihm dreißig Silberstücke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Von da an suchte er eine günstige Gelegenheit, ihn zu verraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Am ersten Tag der Ungesäuerten Brote begaben sich die Jünger zu Jesus mit der Frage: \"Wo willst du, daß wir dir das Ostermahl bereiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Er sprach: \"Geht in die Stadt zu dem bekannten Manne! Zu diesem sagt: \'Der Meister spricht: Es naht sich meine Zeit; bei dir halte ich mit meinen Jüngern das Ostermahl. \'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Die Jünger taten so, wie Jesus ihnen aufgetragen hatte; und sie bereiteten das Ostermahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'So ward es Abend; er setzte sich zu Tische mit den Zwölfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Beim Mahle sprach er: \"Wahrlich, ich sage euch: Einer aus euch wird mich verraten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Da fragte ihn einer nach dem andern tiefbetrübt: \"Bin ich es etwa, Herr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Er sprach zu ihnen: \"Der seine Hand mit mir in die Schüssel tunkt, wird mich verraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Der Menschensohn geht zwar dahin, so wie es von ihm geschrieben steht; doch wehe dem Menschen, durch den der Menschensohn verraten wird. Besser wäre es für diesen Menschen, wenn er nicht geboren wäre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Auch Judas, sein Verräter, fragte ihn: \"Bin ich es etwa, Rabbi?\" Er sprach zu ihm: \"Du bist es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Während sie beim Mahl waren, nahm Jesus Brot, dankte, brach es und gab es seinen Jüngern mit den Worten: \"Nehmt hin und esset, das ist mein Leib.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Darauf nahm er den Kelch, dankte und gab ihn diesen mit den Worten: \"Trinket alle daraus;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'denn das ist mein Bundesblut, das für viele vergossen wird zur Nachlassung der Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ich sage euch aber: Ich werde von jetzt an nicht mehr von dem Gewächs des Weinstocks trinken, bis zu jenem Tage, da ich es mit euch in neuer Weise trinken werde im Reiche meines Vaters.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Sie beteten den Lobgesang und gingen hernach zum Ölberg hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Da sprach Jesus zu ihnen: \"Ihr alle werdet heute nacht noch an mir irre werden; steht doch geschrieben: \'Ich will den Hirten schlagen; dann werden die Schafe der Herde zerstreut werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Nach meiner Auferstehung aber will ich euch nach Galiläa vorausgehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Da gab Petrus ihm zur Antwort: \"Und mögen alle an dir irre werden, ich werde niemals irre werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus sprach zu ihm: \"Wahrlich, ich sage dir: Noch heute nacht vor dem Hahnenschrei wirst du mich dreimal verleugnet haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Petrus sprach zu ihm: \"Und wenn ich mit dir sterben müßte, ich würde dich doch nicht verleugnen.\" In gleicher Weise sprachen alle Jünger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Und Jesus ging mit ihnen zu einem Landgut, Gethsemani geheißen. Er sprach zu seinen Jüngern.: \"Wartet hier, indes ich dorthin gehe und bete\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Nur Petrus und die beiden Zebedäussöhne nahm er mit sich. Dann fing er an, traurig und betrübt zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Er sprach zu ihnen: \"Meine Seele ist tief betrübt bis zum Tode; bleibt hier und wacht mit mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Er ging ein wenig vorwärts, fiel auf sein Antlitz nieder und betete: \"Mein Vater, wenn es möglich ist, so gehe dieser Kelch an mir vorüber. Doch nicht wie ich will, sondern wie du willst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Dann ging er zu den Jüngern und fand sie schlafend. Er sprach zu Petrus: \"So konntet ihr nicht eine einzige Stunde mit mir wachen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Wachet und betet, damit ihr nicht in Versuchung fallet. Der Geist ist willig, doch das Fleisch ist schwach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Er ging zum zweiten Male hin und betete: \"Mein Vater, wenn dieser Kelch nicht vorübergehen kann, ohne daß ich ihn trinke, dann geschehe dein Wille.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Er kam zurück und fand sie wieder schlafend; denn ihre Augen waren schwer geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Da ließ er sie, ging hin und betete zum dritten Male mit den gleichen Worten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alsdann begab er sich zu seinen Jüngern und sprach zu ihnen: \"Noch schlafet ihr und ruhet; sehet, die Stunde ist gekommen, da der Menschensohn in die Hände der Sünder überliefert wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Steht auf und laßt uns gehen. Seht, mein Verräter naht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Noch sprach er so, da kam schon Judas, einer aus den Zwölfen, mit ihm ein großer Haufen mit Schwertern und Prügeln im Auftrag der Oberpriester und der Ältesten des Volkes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Sein Verräter hatte mit ihnen ein Zeichen ausgemacht: \"Den ich küssen werde, der ist es, den ergreifet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'So schritt er denn sofort auf Jesus zu und sagte: \"Sei gegrüßt, Rabbi!\" und küßte ihn gar innig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Und Jesus sprach zu ihm: \"Freund, wozu bist du gekommen? \"Jetzt traten sie hinzu und legten Hand an Jesus und ergriffen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Und siehe, einer von denen, die um Jesus waren, streckte seine Hand aus, zog sein Schwert, traf einen Knecht des Hohenpriesters und schlug ihm ein Ohr ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Da sprach Jesus zu ihm: \"Stecke dein Schwert an seinen Ort; denn alle, die das Schwert ergreifen, werden durch das Schwert zugrunde gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Oder meinst du, ich könnte nicht meinen Vater bitten, und dieser würde nicht sofort mir mehr als zwölf Legionen Engel senden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Wie würden aber dann die Schriften erfüllt, wonach es also kommen muß?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Und zu dem Haufen sagte Jesus in derselben Stunde: \"Wie gegen einen Räuber seid ihr ausgezogen mit Schwertern und Prügeln, um mich zu ergreifen. Tag für Tag saß ich im Tempel, wo ich lehrte, und ihr habt mich nicht ergriffen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Dies alles aber ist geschehen, damit die Schriften der Propheten in Erfüllung gehen sollten. Jetzt ließen ihn alle Jünger im Stich und flohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Die Häscher aber führten Jesus dem Hohenpriester Kaiphas vor. Dort hatten sich die Schriftgelehrten und die Ältesten versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Und Petrus folgte ihm von fern bis zum Palaste des Hohenpriesters. Er ging hinein und setzte sich zu den Dienern, um zu sehen, wie es ausginge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Die Oberpriester und der ganze Hohe Rat suchten nach einem falschen Zeugnis gegen Jesus, um ihn in den Tod zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Sie fanden aber keines, obwohl viele falsche Zeugen kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Zuletzt traten noch zwei vor und sagten: \"Er hat behauptet: \'Ich kann den Tempel Gottes niederreißen und ihn in drei Tagen wieder aufbauen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Da stand der Hohepriester auf und fragte ihn. \"Weißt du nichts zu sagen auf das, was diese gegen dich aussagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Doch Jesus schwieg. Da sprach der Hohepriester zu ihm: \"Ich beschwöre dich bei dem lebendigen Gott: Sag uns: Bist du der Christus, der Sohn Gottes?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesus sprach zu ihm: \"Ich bin es. Zudem aber sage ich euch: Von jetzt an werdet ihr den Menschensohn zur Rechten des Allmächtigen Gottes sitzen und auf den Wolken des Himmels kommen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Da zerriß der Hohepriester seine Kleider und rief: \"Er hat Gott gelästert. Was brauchen wir noch Zeugen? Ihr habt ja seine Gotteslästerung gehört!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Was dünkt euch?\" Da riefen sie: \"Er ist des Todes schuldig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Nun spien sie ihm ins Gesicht und schlugen ihn mit Fäusten; andere gaben ihm Stockschläge;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'sie höhnten: \"Weissage uns, Christus: Wer ist es, der dich geschlagen hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Petrus saß indes im Hofe draußen. Da trat eine Magd zu ihm und sprach. \"Auch du warst bei Jesus, dem Galiläer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Er aber leugnete es vor allen ab und sprach. \"Ich verstehe nicht, was du sagst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Er ging zum Tore hinaus; da sah ihn eine andere Magd. Sie sprach zu denen, die dort standen: \"Der war auch bei Jesus, dem Nazarener.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Und nochmals leugnete er es mit einem Schwur: \"Ich kenne den Menschen nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Nach einer kleinen Weile traten die Umstehenden hinzu; sie sagten zu Petrus: \"Wahrlich, auch du gehörst zu ihnen, dich verrät ja deine Sprache!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Petrus fing an zu fluchen und zu schwören: \"Ich kenne den Menschen nicht.\" Da krähte gleich darauf ein Hahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Und jetzt erinnerte sich Petrus des Wortes Jesu, als er sprach: \"Noch vor dem Hahnenschrei wirst du mich dreimal verleugnet haben.\" Er ging hinaus und weinte bitterlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Alle Oberpriester und die Ältesten des Volkes faßten in der Morgenfrühe gegen Jesus den Beschluß, ihn hinzurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Sie führten ihn gebunden ab und übergaben ihn dem Statthalter Pontius Pilatus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Als Judas, sein Verräter, sah, daß er verurteilt sei, überkam ihn Reue. Er brachte die dreißig Silberstücke den Oberpriestern und den Ältesten zurück');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'und sprach: \"Ich habe gesündigt; ich habe unschuldiges Blut verraten.\" Doch sie erwiderten: \"Was geht das uns an? Das ist deine Sache.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Da warf er die Silberstücke in den Tempel; ging weg und henkte sich mit einem Strick.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Die Oberpriester nahmen das Geld und sagten: \"Wir dürfen es nicht dem Tempelschatz überweisen; es ist ja Blutgeld.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Nachdem sie Beschluß gefaßt hatten, erwarben sie damit den Töpferacker zu einer Grabstätte für Fremde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Deshalb heißt dieser Acker bis auf den heutigen Tag Blutacker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Also erfüllte sich, was durch den Propheten Jeremias ausgesprochen ward, der sagt: \"Sie nahmen die dreißig Silberstücke, den Preis des Abgeschätzten, so wie er von den Söhnen Israels geschätzt ward,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'und gaben sie für einen Töpferacker hin. So hat der Herr mir aufgetragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jesus also stand vor dem Statthalter. Der Statthalter fragte ihn: \"Bist du der König der Juden?\" Und Jesus sprach: \"Das sagst nur du.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Als ihn die Oberpriester und die Ältesten anklagten, erwiderte er nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Pilatus sprach zu ihm: \"Hörst du denn nicht, was diese alles gegen dich bezeugen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Er gab jedoch auf keine einzige seiner Fragen Antwort, so daß der Statthalter sich sehr verwunderte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Nun pflegte der Statthalter auf den Festtag dem Volk einen der Gefangenen loszugeben, wen sie wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Man hatte damals einen berüchtigten Gefangenen namens Barabbas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Als sie versammelt waren, fragte sie Pilatus: \"Wen soll ich euch freilassen: Barabbas oder Jesus, den sogenannten Christus?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Er wußte nämlich, daß sie ihn nur aus Neid überliefert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Noch während der Gerichtssitzung schickte seine Frau zu ihm und ließ ihm sagen: \"Laß deine Hand von dem Gerechten da. Denn seinetwegen habe ich heute nacht im Traume vieles ausgestanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Die Oberpriester aber und die Ältesten beredeten das Volk, sich den Barabbas auszubitten und Jesus zu verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Der Statthalter sprach nun zu ihnen: \"Wen von den beiden soll ich euch jetzt freilassen?\" \"Barabbas!\" schrien sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Da fragte sie Pilatus: \"Was soll ich aber dann mit Jesus, dem sogenannten Christus, machen?\" \"Gekreuzigt soll er werden!\" riefen alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Darauf erwiderte der Statthalter: \"Was hat er denn Böses getan?\" Da schrien sie noch lauter: \"Gekreuzigt soll er werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Pilatus sah wohl ein, es sei nichts mehr zu machen, daß der Lärm vielmehr nur größer würde. Da nahm er Wasser, wusch sich die Hände angesichts des Volkes und sprach dabei: \"Ich bin unschuldig am Blute dieses Gerechten, verantwortet ihr es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Und die ganze Menge schrie: \"Sein Blut komme über uns und unsre Kinder!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Da gab er ihnen den Barabbas frei, Jesus aber ließ er geißeln und übergab ihn dann zur Kreuzigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Hierauf nahmen die Soldaten des Statthalters Jesus mit sich ins Gerichtsgebäude und versammelten um ihn die ganze Abteilung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Sie zogen ihn aus, hängten ihm einen scharlachroten Mantel um,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'flochten eine Krone aus Dornen, setzten sie ihm auf das Haupt und gaben ihm ein Rohr in seine rechte Hand. Sie beugten auch zum Spott vor ihm das Knie und sprachen: \"Heil dir, du Judenkönig!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Auch spien sie ihn an, nahmen ihm das Rohr und schlugen ihn damit aufs Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Nachdem sie ihren Spott mit ihm getrieben hatten, nahmen sie ihm den Mantel ab, zogen ihm seine Kleider wieder an und führten ihn zur Kreuzigung hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'So zogen sie hinaus; sie trafen einen Cyrenäer namens Simon. Den nötigten sie, ihm das Kreuz nachzutragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Und so gelangten sie an einen Ort, der Golgotha - d.h. Schädelstätte - heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Sie gaben ihm Wein, vermischt mit Galle, zu trinken. Er aber kostete nur davon und wollte ihn nicht trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Dann kreuzigten sie ihn, verteilten seine Kleider durch das Los, damit erfüllt würde, was vom Propheten gesagt worden war: \"Sie haben meine Kleider unter sich verteilt und über mein Gewand das Los geworfen\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'setzten sich dort nieder und bewachten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Und über seinem Haupte hefteten sie eine Inschrift an mit Angabe seiner Schuld: \"Dieser ist Jesus, der Judenkönig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Zugleich mit ihm wurden auch zwei Räuber an das Kreuz geschlagen, der eine ihm zur Rechten und der andere zur Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Die Vorübergehenden überhäuften ihn mit Lästerworten; sie schüttelten den Kopf');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'und sprachen: \"Du hast den Tempel Gottes zerstören und in drei Tagen wieder aufbauen wollen, rette doch dich selbst. Bist du der Sohn Gottes, dann steig vom Kreuz herab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'So ähnlich höhnten auch die Oberpriester mitsamt den Schriftgelehrten und den Ältesten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '\"Andere hat er gerettet, sich selbst kann er nicht retten. Er ist König von Israel. So steige er jetzt vom Kreuze herab, dann wollen wir an ihn glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Er hat auf Gott vertraut. Der soll ihn erlösen, wenn er ihn wirklich liebt. Er sagte ja: \'Ich bin der Sohn Gottes\'\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'In gleicher Weise schmähten ihn auch die Räuber, die mit ihm gekreuzigt worden waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Von der sechsten bis zur neunten Stunde lag auf dem ganzen Land eine Finsternis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Und um die neunte Stunde rief Jesus mit lauter Stimme: \"Eli, eli, lama sabakthani?\" d.h. \"Mein Gott, mein Gott, warum hast du mich verlassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Einige von denen, die dort standen, vernahmen dies und sagten: \"Er ruft den Elias.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Da lief sogleich einer aus ihnen hin, füllte einen Schwamm mit Essig, steckte ihn auf ein Rohr und gab ihm zu trinken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Die andern aber sagten: \"Wart\', wir wollen sehen, ob Elias kommt, ihn zu retten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Darauf rief Jesus noch einmal mit lauter Stimme und gab den Geist auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Und siehe, der Vorhang im Tempel riß entzwei von oben bis unten, die Erde bebte, die Felsen spalteten sich;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'die Gräber öffneten sich, und viele Leiber von entschlafenen Heiligen wurden auferweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Sie kamen aus den Grabstätten nach seiner Auferstehung hervor und gingen in die heilige Stadt und erschienen vielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Als der Hauptmann und die mit ihm bei Jesus Wache hielten das Erdbeben und was sonst geschah gewahrten, gerieten sie in große Furcht und sprachen: \"Wahrhaftig, dieser war Gottes Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Auch viele Frauen waren dort; die schauten von ferne zu. Sie waren Jesus von Galiläa her gefolgt und hatten ihm gedient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Und unter ihnen war Maria Magdalena, Maria, die Mutter des Jakobus und des Joses, sowie die Mutter der Zebedäussöhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Am Abend kam ein reicher Mann aus Arimathäa namens Joseph; er war auch ein Jünger Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Dieser begab sich zu Pilatus und bat um den Leichnam Jesu. Pilatus befahl, ihm den Leichnam zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Joseph nahm den Leichnam, wickelte ihn in reine Leinwand');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'und legte ihn in sein neues Grab, das er in einen Felsen hatte hauen lassen. Er wälzte einen großen Stein vor den Eingang des Grabes und ging weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Maria Magdalena und die andere Maria blieben noch dem Grabe gegenüber sitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Des andern Tages, also nach dem Rüsttag, begaben sich die Oberpriester und Pharisäer zusammen zu Pilatus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Sie sprachen: \"Herr, wir haben uns erinnert, daß jener Betrüger noch bei Lebzeiten gesagt hat: \'Ich werde nach drei Tagen auferstehen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Laß also das Grab bis auf den dritten Tag bewachen, sonst möchten seine Jünger kommen, ihn stehlen und dem Volke sagen: \'Er ist von den Toten auferstanden.\' Und dieser letzte Betrug würde schlimmer sein als der erste.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatus sprach zu ihnen: \"Ihr sollt eine Wache haben! Geht hin und sichert das Grab, wie ihr es versteht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Sie gingen hin und sicherten das Grab; sie versiegelten den Stein und stellten eine Wache auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Als der Sabbat vorüber war, am ersten Wochentag beim Morgengrauen, kamen Maria Magdalena und die andere Maria, um nach dem Grabe zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Und siehe, da entstand ein starkes Erdbeben; ein Engel des Herrn stieg vom Himmel nieder, trat hinzu, wälzte den Stein hinweg und setzte sich darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Sein Anblick war wie ein Blitz und sein Gewand so weiß wie Schnee.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Die Wächter erzitterten aus Furcht vor ihm und wurden leichenblaß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Der Engel aber redete die Frauen also an: \"Habt keine Furcht. Ich weiß, ihr suchet Jesus, den Gekreuzigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Er ist nicht hier; er ist auferstanden, so wie er es gesagt hat. Kommt her und schaut den Ort, wo der Herr gelegen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Geht schnell weg und sagt seinen Jüngern, daß er von den Toten auferstanden ist. Seht, ich habe es euch gesagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Schnell gingen sie vom Grabe weg mit Furcht und doch zugleich mit großer Freude und eilten, diese Botschaft seinen Jüngern zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Und siehe, Jesus trat ihnen in den Weg und sprach: \"Seid gegrüßt.\" Sie traten zu ihm hin, umfaßten seine Füße und beteten ihn an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Darauf sprach Jesus zu ihnen: \"Habt keine Furcht. Geht hin und kündet meinen Brüdern, sie sollen nach Galiläa gehen, dort werden sie mich sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Sie gingen weiter. Da kamen einige von der Wache in die Stadt und meldeten den Oberpriestern alles, was geschehen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Diese kamen mit den Ältesten zusammen und faßten den Beschluß, den Soldaten reichlich Geld zu geben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'und den Auftrag: \"Sagt aus: \'Seine Jünger sind nachts gekommen und haben ihn gestohlen, als wir schliefen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Wenn dies dem Statthalter zu Ohren kommen sollte, so werden wir ihn schon beschwichtigen und euch jede Sorge abnehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Diese nahmen das Geld und taten, wie sie angeleitet worden waren. Und dieses Gerede hat sich bei den Juden bis auf den heutigen Tag erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Die elf Jünger aber begaben sich nach Galiläa auf den Berg, wohin sie Jesus befohlen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Als sie ihn sahen, beteten sie ihn an; andere aber waren noch im Zweifel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Darauf trat Jesus her und sprach zu ihnen: \"Mir ist alle Gewalt gegeben im Himmel und auf Erden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Darum gehet hin und lehret alle Völker: Tauft sie im Namen des Vaters und des Sohnes und des heiligen Geistes');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'und lehrt sie alles halten, was ich euch geboten habe. Seht, ich bin bei euch alle Tage bis zur Vollendung der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Anfang der frohen Botschaft von Jesus Christus, dem Sohne Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'So, wie geschrieben steht bei dem Propheten Isaias: \"Siehe, ich sende meinen Engel vor dir her, der dir den Weg bereiten soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Eine Stimme ruft in der Steppe: \'Richtet her den Weg des Herrn, macht seine Pfade eben.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Johannes trat in der Steppe auf, taufte und verkündete die Taufe der Bekehrung zur Nachlassung der Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Das ganze Land Judäa zog zu ihm hinaus, sowie alle Bewohner Jerusalems. Man ließ sich von ihm im Jordanfluß taufen, wobei man seine Sünden bekannte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Johannes trug ein Kleid aus Kamelhaaren und einen Ledergürtel um die Lenden; er nährte sich von Heuschrecken und wildem Honig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Er predigte und sprach: \"Nach mir kommt einer, der mächtiger ist als ich; ich bin nicht wert, mich vor ihm hinzubeugen und ihm die Riemen seiner Schuhe loszulösen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ich habe euch nur mit Wasser getauft. Er aber wird euch mit dem Heiligen Geiste taufen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'In jenen Tagen kam Jesus von Nazareth in Galiläa und ließ sich im Jordan von Johannes taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Und sogleich, als er aus dem Wasser stieg, sah er, wie sich die Himmel öffneten und wie der Geist einer Taube gleich auf ihn niederschwebte und über ihm blieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Und eine Stimme kam vom Himmel her: \"Du bist mein geliebter Sohn; an dir habe ich mein Wohlgefallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Und gleich hernach trieb ihn der Geist in die Einsamkeit');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Vierzig Tage und vierzig Nächte war er in der Einsamkeit und ward vom Satan versucht; er lebte bei den wilden Tieren; doch Engel dienten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Nach der Gefangennahme des Johannes begab sich Jesus nach Galiläa und verkündete die frohe Botschaft vom Reiche Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Er sprach: \"Erfüllt ist die Zeit; das Reich Gottes ist nahe! Bekehret euch und glaubt an die frohe Botschaft!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Einst wanderte er an Galiläas Meer entlang, als er den Simon und Andreas, Simons Bruder, sah. Sie warfen eben ein Netz ins Wasser aus; sie waren nämlich Fischer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Und Jesus sprach zu ihnen: \"Kommt, folget mir! Ich werde euch zu Menschenfischern machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Augenblicklich ließen sie ihre Netze liegen und folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Er ging ein wenig weiter; da sah er Jakobus, den Sohn des Zebedäus, und Johannes, seinen Bruder. In ihrem Boote legten sie gerade die Netze sich zurecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Sogleich berief er sie. Sie ließen ihren Vater Zebedäus im Boot bei den Tagelöhnern und gingen mit ihm fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Sie gingen nach Kapharnaum hinein. Gleich am Sabbat begab er sich in die Synagoge, wo er lehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Man war von seiner Lehre hingerissen; denn er lehrte sie wie einer, der Vollmacht hat, und nicht wie die Schriftgelehrten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'In ihrer Synagoge war ein Mensch im Banne eines unreinen Geistes. Er schrie laut');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'und rief: \"Oho! Was willst du von uns, Jesus von Nazareth? Bist du gekommen, uns zu verderben? Ich weiß, wer du bist: der Heilige Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Doch Jesus drohte ihm und sprach: \"Schweig! Fahr von ihm aus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Da zerrte ihn der unreine Geist hin und her und fuhr mit gellendem Geschrei von ihm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Alle entsetzten sich und stritten miteinander. Sie fragten: \"Was ist doch das, die neue Lehre in der Vollmacht Gottes? Gebietet er doch selbst unreinen Geistern, und sie gehorchen ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Sein Ruf ging überall hinaus ins ganze Gebiet von Galiläa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Dann ging er aus der Synagoge fort und kam ins Haus des Simon und Andreas, in der Begleitung von Jakobus und Johannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Die Schwiegermutter des Simon lag fieberkrank darnieder, und sie erzählten ihm sofort von ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Da trat er zu ihr hin, ergriff sie bei der Hand und richtete sie auf. Da wich von ihr das Fieber, und sie diente ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Als es Abend wurde und die Sonne untergegangen war, brachte man zu ihm alle Kranken und Besessenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Die ganze Stadt drängte sich vor der Tür zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Er heilte viele Kranke von mannigfachen Leiden und trieb auch viele Dämonen aus; doch ließ er es nicht zu, daß die Dämonen redeten; sie erkannten ihn nämlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Frühmorgens, als es noch ganz dunkel war, stand er auf, ging fort und kam an einen abgelegenen Ort, wo er betete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon und die Seinen gingen ihm rasch nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Sie fanden ihn und sagten zu ihm: \"Alle suchen dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Er sprach zu ihnen: \"Laßt uns auch anderswohin gehen, in die Flecken da umher, damit ich auch dort predige; dazu bin ich gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'So zog er denn umher und predigte überall in Galiläa in ihren Synagogen und trieb die Dämonen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Da kam zu ihm ein Aussätziger; auf den Knien flehte er ihn an und sprach: \"Wenn du willst, kannst du mich rein machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Voll Erbarmen streckte er seine Hand aus, berührte ihn und sprach: \"Ich will, sei rein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Und sofort wich der Aussatz von ihm, und er war rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Mit strengen Worten schickte er ihn alsbald fort');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'und sprach zu ihm: \"Hüte dich, irgend jemand etwas zu sagen; geh vielmehr hin, zeige dich dem Priester und opfere für deine Reinigung, was Moses vorgeschrieben hat; sie mögen dies zum Zeugnis nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Jener ging hinweg; er wußte vieles zu erzählen und machte die Tat überall bekannt. So kam es, daß Jesus sich nicht mehr offen in einer Stadt zeigen konnte, vielmehr sich außerhalb an abgelegenen Orten aufhielt; jedoch kam man zu ihm von allen Seiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Ein paar Tage später kam er wieder nach Kapharnaum. Man erfuhr, daß er im Hause sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'So viele strömten zusammen, daß selbst vor der Tür kein Platz mehr war. Und er legte ihnen das Wort aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Da kamen einige daher und brachten zu ihm einen Lahmen; vier Männer trugen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Doch des Gedränges wegen konnten sie nicht zu ihm kommen; da deckten sie gerade, wo er stand, das Dach auf und schufen dadurch eine Öffnung und ließen die Bahre, auf welcher der Lahme lag, hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Als Jesus ihren Glauben sah, sprach er zu dem Lahmen: \"Mein Sohn, vergeben sind dir deine Sünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Es saßen aber einige der Schriftgelehrten dort, die in ihrem Herzen dachten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '\"Wie kann er nur so reden? Er lästert. Wer kann denn Sünden vergeben als nur der Eine, Gott?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Doch Jesus erkannte sofort in seinem Geiste, daß sie solches bei sich dachten. Er sprach zu ihnen: \"Was denkt ihr da in eurem Herzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Was ist leichter, zu dem Lahmen zu sagen: \'Vergeben sind dir deine Sünden\' oder zu sagen: \'Steh auf, nimm deine Bahre und geh umher?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Ihr aber sollt wissen, daß der Menschensohn die Macht besitzt, auf Erden Sünden zu vergeben.\" Dann sprach er zum Gelähmten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '\"Ich sage dir: Steh auf, nimm deine Bahre und geh nach Hause!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Und er stand auf, nahm seine Bahre und ging sogleich vor aller Augen weg. Alle waren außer sich, lobten Gott und sprachen: \"So etwas haben wir noch nie gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Dann ging er wieder an das Meer hinaus. Die ganze Menge strömte zu ihm hin, und er lehrte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Im Vorübergehen sah er Levi, des Alphäus Sohn, an der Zollstätte sitzen. Er sprach zu ihm: \"Folge mir!\" Da stand er auf und folgte ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Als er in seinem Haus zu Tische saß, waren auch viele Zöllner und Sünder zu Tische mit Jesus und Seinen Jüngern. - Es gab schon viele, die sich ihm angeschlossen hatten. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Die Schriftgelehrten bei den Pharisäern sahen, wie er mit Sündern und Zöllnern aß; sie fragten deshalb seine Jünger: \"Warum ißt und trinkt er denn mit Zöllnern und Sündern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Jesus hörte dies und sprach: \"Nicht die Gesunden brauchen einen Arzt, sondern die Kranken. Nicht dazu bin ich da, Gerechte zu berufen, sondern Sünder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Die Jünger des Johannes und die Pharisäer hatten einmal einen Fasttag. Da kamen sie und fragten ihn: \"Warum fasten die Jünger des Johannes und die Pharisäer; deine Jünger aber fasten nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jesus sprach zu ihnen: \"Können denn die Hochzeitsgäste fasten, solange der Bräutigam bei ihnen weilt? Solange sie den Bräutigam bei sich haben, können sie nicht fasten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Es werden aber Tage kommen, da ihnen der Bräutigam entrissen ist; an jenen Tagen werden sie dann fasten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Niemand näht einen Fleck aus ungewalktem Zeug auf einen alten Mantel; sonst reißt der neue Fleck auch noch vom alten Mantel etwas weg, und der Riß wird nur noch größer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Auch füllt niemand neuen Wein in alte Schläuche; sonst sprengt der Wein die Schläuche, und Wein und Schläuche sind verdorben. Nein, neuen Wein muß man in neue Schläuche füllen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'An einem Sabbat ging er durch die Ährenfelder hin. Seine Jünger rupften im Vorübergehen Ähren ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Da sprachen die Pharisäer zu ihm: \"Sieh, wie sie am Sabbat tun, was verboten ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Doch er sprach zu ihnen: \"Habt ihr noch nie gelesen, was David tat, als er in Not war und er und seine Begleiter Hunger hatten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Wie er das Haus Gottes betrat zur Zeit des Hohenpriesters Abjathar und dort die Schaubrote aß, die nur die Priester essen dürfen, und wie er auch noch seinen Gefährten gab?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Und weiter sagte er zu ihnen: \"Der Sabbat ist des Menschen wegen da und nicht der Mensch des Sabbats wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Übrigens ist der Menschensohn auch Herr des Sabbats.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Dann ging er wieder in die Synagoge. Dort war ein Mann mit einer verwelkten Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Da gaben sie nun acht, ob er ihn am Sabbat heile; denn sie wollten ihn verklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Da sprach er zu dem Manne mit der verwelkten Hand: \"Tritt hierher, in die Mitte!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Dann fragte er sie: \"Darf man am Sabbat Gutes oder Böses tun, ein Leben retten oder es zugrunde gehen lassen?\" Jedoch sie schwiegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Voll Zorn sah er einen nach dem anderen an, in Trauer über die Verstocktheit ihres Herzens, und sprach dann zu dem Manne: \"Strecke deine Hand aus!\" Er streckte sie aus, und seine Hand war wiederhergestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Die Pharisäer aber gingen weg und hielten gegen ihn mit den Herodianern Rat, wie sie ihn verderben könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Darauf zog sich Jesus mit seinen Jüngern an das Meer zurück. Und große Scharen folgten ihm aus Galiläa und auch aus Judäa,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'aus Jerusalem, Idumäa und aus der Gegend jenseits des Jordans; von Tyrus und von Sidon strömte man ihm in Scharen zu, weil man hörte, welch große Taten er vollbrachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Er sprach zu seinen Jüngern, sie sollten wegen dieser Menge ihm ein Boot bereithalten, damit er nicht ins Gedränge komme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Denn er hatte viele geheilt, und so drängten alle Leidenden sich an ihn her, um ihn anzurühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Und wenn unreine Geister ihn erblickten, so fielen diese vor ihm nieder und schrien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, '\"Du bist der Sohn Gottes.\" Er aber fuhr sie heftig an, daß sie ihn nicht offenbaren sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Dann stieg er auf den Berg und rief die, die er wollte, zu sich, und sie gingen zu ihm hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Und er bestimmte zwölf, daß sie stets um ihn seien, die er dann aussenden könnte, um zu predigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'und die auch Macht besäßen, Krankheiten zu heilen und die Dämonen auszutreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Und er bestimmte die Zwölf. Er gab dem Simon den Namen Petrus;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jakobus, den Sohn des Zebedäus, und Johannes, den Bruder des Jakobus, die hieß er Boanerges - d.h. Donnerer -;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'sodann Andreas und Philippus, Bartholomäus, Matthäus, Thomas und Jakobus, des Alphäus Sohn, Thaddäus und Simon, den Eiferer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'sowie Judas, den Iskariot, der ihn dann verraten hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Er ging nach Hause. Da strömte wiederum viel Volk zusammen, so daß sie nicht einmal mehr essen konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Als dies die Seinen hörten, kamen sie heraus, um ihn mit Gewalt hereinzuholen; denn sie sagten: \"Er ist von Sinnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Und auch die Schriftgelehrten, die von Jerusalem hergekommen waren, sagten: \"Dieser hat den Beelzebul\" und \"Durch den obersten der Dämonen treibt er die Dämonen aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Da rief er sie heran und sprach zu ihnen gleichnisweise: \"Wie kann denn Satan den Satan austreiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Wenn ein Reich in sich uneins ist, kann dieses Reich nicht bestehen bleiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'und wenn ein Haus in sich uneins ist, kann dieses Haus nicht bestehen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Wenn Satan wider sich selbst auftreten würde und wenn er uneinig wäre, er könnte nicht bestehen; es wäre dann aus mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Vielmehr kann keiner in das Haus des Starken eindringen und ihm seine Habe rauben, wenn er den Starken nicht zuvor gebunden hat. Dann erst kann er sein Haus ausplündern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Wahrlich, ich sage euch: Alle Lästerungen und Sünden werden den Menschenkindern nachgelassen werden, mögen sie auch noch so schwere Lästerungen ausgestoßen haben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'nur wer gegen den Heiligen Geist Lästerungen ausspricht, wird in Ewigkeit nicht Nachlaß finden. Der ewigen Sünde wird er schuldig bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Sie sagten nämlich: \"Dieser hat einen unreinen Geist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Da kamen seine Mutter und seine Brüder; sie blieben draußen stehen und ließen ihn rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Eine große Menge saß um ihn herum; da sagte man zu ihm: \"Siehe, deine Mutter, deine Brüder und deine Schwestern suchen dich draußen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Doch er sprach zu ihnen: \"Wer ist meine Mutter, wer sind meine Brüder?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Dann sah er alle, die im Kreis um ihn saßen, einen nach dem anderen an und sprach: \"Seht, hier sind meine Mutter und meine Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Denn wer den Willen Gottes tut, der ist mir Bruder, Schwester, Mutter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Dann fing er wieder an, am Meer zu lehren. Da sammelten bei ihm sich große Scharen, so daß er ein Boot besteigen mußte und sich draußen auf dem Meer niedersetzte; die ganze Menge aber stand am Meer entlang am Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Er lehrte sie viel in Gleichnissen. So sprach er in seinem Lehrvortrag zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '\"Höret! Seht: Der Sämann ging aus zu säen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Und als er säte, fiel ein Teil davon auf den Weg; die Vögel des Himmels kamen und fraßen es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Anderes fiel auf steinigen Grund, wo es nicht viel Erdreich gab. Rasch schoß es in den Halm, es hatte nämlich keinen tiefen Boden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'doch als die Sonne aufgegangen war, wurde es versengt, und es verdorrte, weil es keine Wurzel hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Ein anderes fiel unter Dornen; die Dornen wuchsen auf und erstickten es, und so gab es keine Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Ein anderes fiel auf guten Boden; es keimte, wuchs und brachte Frucht; es trug Frucht bis zu dreißig-, sechzig-, hundertfältig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Er fügte dann noch bei: \"Wer Ohren hat zu hören, höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Als er allein war, fragten ihn die Leute, die bei ihm waren, sowie die Zwölf über die Gleichnisse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Er sprach zu ihnen: \"Euch ist das Geheimnis des Gottesreiches anvertraut; doch jenen, die draußen sind, wird das alles nur in Gleichnissen mitgeteilt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'damit sie mit offenen Augen sehen und doch nicht sehen, mit eigenen Ohren hören und doch nicht zur Einsicht kommen, damit sie sich nicht bekehren und Vergebung finden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Und weiter sagte er zu ihnen: \"Ihr versteht dieses Gleichnis nicht? Wie wollt ihr alle anderen verstehen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Der Sämann sät das Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, '\'Auf dem Wege\' liegt es bei denen, wo das Wort gesät wird; doch kaum, daß sie es gehört, kommt der Satan und nimmt das Wort, das in ihnen gesät ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Und ähnlich ist es \'auf steinigen Grund gesät\' bei denen, die, wenn sie das Wort gehört haben, es sofort mit Freuden aufnehmen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'allein, sie haben in sich keine Wurzeln; denn sie sind unbeständig; kommt nämlich Trübsal oder Verfolgung um des Wortes willen, dann werden sie gleich irre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Andere sind die, wo es \'unter Dornen\' gesät ward. Das sind die, die das Wort zwar hören;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'jedoch die Sorgen dieser Welt, der Trug des Reichtums und ähnliche Gelüste drängen sich herein, ersticken das Wort, und so bleibt es ohne Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, '\'Auf guten Boden\' ward gesät bei jenen, die das Wort gehört und in sich auf genommen haben und Frucht bringen: dreißig-, sechzig-, hundertfältig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Des weiteren sprach er zu ihnen: \"Läßt man sich wohl ein Licht bringen, um es unter einen Scheffel oder ein Bett zu stellen? Doch wohl, um es auf den Leuchter zu stellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Nichts ist verborgen, was nicht offenkundig werden, und nichts geheim, was nicht an den Tag kommen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Wer Ohren hat zu hören, höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Er sprach zu ihnen: \"Gebt acht auf das, was ihr jetzt hört: Mit dem Maß, mit dem ihr messet, wird euch zugemessen werden; ja, wenn ihr hört, wird euch noch dreingegeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Wer nämlich hat, dem wird gegeben werden; aber wer nicht hat, dem wird auch das, was er besitzt, genommen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Dann sprach er: \"So ist es mit dem Gottesreich, wie wenn ein Mann den Samen übers Land wirft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Er schläft und wacht wieder auf, so Nacht für Nacht und Tag für Tag. Und die Saat sproßt und wächst; wie, weiß er selber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Von selbst trägt die Erde Frucht; Saatgrün zuerst, dann Ähre und dann in der Ähre volles Korn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Läßt es die Frucht zu, legt er sogleich die Sichel an: Die Erntezeit ist da.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Und weiter sprach er: \"Womit sollen wir das Gottesreich vergleichen, oder in welches Gleichnis sollen wir es kleiden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Es ist wie ein Senfkörnlein. Wenn man es in die Erde sät, ist es das kleinste unter allen Samenkörnern auf der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Ist es aber gesät, so geht es auf und wird das größte unter allen Gartenkräutern; es treibt so große Zweige, daß unter seinem Schatten die Vögel des Himmels nisten können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'In vielen solchen Gleichnissen verkündete er ihnen das Wort so, wie sie es eben fassen konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Ohne Gleichnis redete er nicht zu ihnen; war er dann allein, erklärte er alles seinen Jüngern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Am selben Tage, gegen Abend, sagte er zu ihnen: \"Laßt uns hinüberfahren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Und sie schickten die Menge fort und nahmen ihn, so wie er war, mit in ihr Boot. Auch andere Boote fuhren mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Doch da erhob sich ein gewaltiger Wirbelsturm; die Wogen schlugen in das Boot, und das Boot begann schon, sich zu füllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Er befand sich hinten im Boot und schlief auf einem Kissen. Sie weckten ihn und riefen: \"Meister, kümmert es dich nicht, daß wir zugrunde gehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Und er stand auf, gebot dem Wind und sprach zum Meere: \"Schweig! Sei still!\" Da legte sich der Wind, und es entstand lautlose Stille.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Darauf sprach er zu ihnen: \"Was seid ihr denn so furchtsam? Wie? Habt ihr noch immer keinen Glauben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Und es befiel sie große Furcht; sie sprachen untereinander: \"Wer ist wohl dieser, daß ihm Wind und Meer gehorchen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'So kamen sie übers Meer hinüber in das Land der Gerasener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Kaum war er aus dem Boot gestiegen, da lief ihm sogleich aus den Gräbern ein Mensch entgegen, der von einem unreinen Geist besessen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Er hauste in den Gräbern, und niemand konnte ihn fesseln, auch nicht mit einer Kette.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Man hatte ihn zwar oft an Händen und Füßen schon gefesselt, jedoch die Ketten hatte er gesprengt, die Fesseln durchgerieben, und niemand war imstande, ihn zu bändigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'So war er denn beständig, Tag und Nacht, in Gräbern und auf Bergeshöhen, schrie und schlug sich selbst mit Steinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Da sah er Jesus aus der Ferne; er lief herzu, fiel vor ihm auf den Boden nieder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'und schrie laut und gellend auf: \"Was willst du von mir, Jesus, du Sohn des allerhöchsten Gottes? Ich beschwöre dich bei Gott: Quäle mich nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Denn schon sprach er zu ihm: \"Unreiner Geist, fahr aus von diesem Menschen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Er fragte ihn: \"Wie ist dein Name?\" \"Mein Name ist Legion\", antwortete er ihm, \"denn unser sind gar viele.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Er bat ihn flehentlich, sie doch nicht aus dem Lande zu vertreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Nun war am Berge dort eine große Schweineherde auf der Weide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Sie baten ihn und sprachen: \"Schick uns zu den Schweinen, auf daß wir in sie fahren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Er gewährte es ihnen. Da fuhren die unreinen Geister aus und in die Schweine; die Herde raste am Abhang hin und ins Meer hinein, ungefähr zweitausend Stück, und sie ertranken im Meere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ihre Hirten flohen und erzählten es in der Stadt und auf dem Lande. Und sie kamen, um zu sehen, was vorgefallen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Sie gingen auch zu Jesus und sahen den Besessenen, der die Legion gehabt, bekleidet und vernünftig dasitzen. Da gerieten sie in Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Die zugesehen hatten, erzählten ihnen, was mit dem Besessenen und den Schweinen vorgefallen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Da baten sie ihn dringend, er möge sich aus ihren Grenzen entfernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Als er das Boot besteigen wollte, da bat ihn der Besessene, ob er nicht mit ihm gehen dürfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Doch er gestattete es nicht; er sprach zu ihm: \"Geh heim zu den Deinen; erzähle ihnen, was der Herr an dir Großes getan und wie er sich deiner erbarmt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Da ging er hin und verkündete in der Dekapolis, was Jesus ihm getan hatte; und alle mußten staunen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Und Jesus fuhr im Boot wieder zum anderen Ufer hin, und es versammelte sich bei ihm viel Volk. Er hielt sich immer noch am Meere auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Da kam einer der Synagogenvorsteher; er hieß Jairus. Er sah ihn und fiel ihm zu Füßen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'und bat ihn flehentlich: \"Mein Töchterchen liegt im Sterben; daß du doch kommen und ihm die Hände auflegen wolltest, damit es gerettet sei und lebe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Er ging mit ihm. Viel Volk ging hintendrein, und sie umdrängten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Da war ein Weib, das schon zwölf Jahre am Blutfluß litt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'und von vielen Ärzten schon vieles hatte leiden müssen und seine ganze Habe ohne jeden Nutzen aufgewendet hatte; im Gegenteil, nur immer schlimmer war es gegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Sie hatte von Jesus gehört und kam jetzt in der Menge hinterher und berührte sein Gewand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Denn also dachte sie: \"Wenn ich auch nur seine Kleider berühre, so ist mir schon geholfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Und ihr Blutfluß hörte sogleich auf; sie spürte es an ihrem Leibe, daß sie von ihren Leiden geheilt sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Doch Jesus merkte alsbald an sich, daß eine Kraft von ihm ausgegangen sei. Deshalb wandte er sich zu der Menge um und fragte: \"Wer hat meine Kleider angerührt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Da sprachen seine Jünger zu ihm: \"Du siehst doch, wie die Menge dich umdrängt; da fragst du noch: \'Wer hat mich angerührt?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Jedoch, er schaute nach der um, die es getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Das Weib, das wußte, was mit ihr geschehen war, kam mit Zittern und Zagen heran, fiel vor ihm nieder und sagte ihm die volle Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Er aber sprach zu ihr: \"Meine Tochter! Dein Glaube hat dir geholfen. Geh hin im Frieden und sei von deinem Leiden geheilt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Noch sprach er so, da kamen Boten vom Hause des Synagogenvorstehers und sagten: \"Deine Tochter ist gestorben. Wozu bemühst du noch den Meister?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jesus, der mitangehört hatte, was da geredet wurde, sprach zum Synagogenvorsteher: \"Hab keine Furcht! Glaube nur!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Und niemand durfte ihn begleiten als Petrus, Jakobus und Johannes, der Bruder des Jakobus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Sie kamen in das Haus des Synagogenvorstehers; hier hörte er den Lärm, das Weinen und das laute Klagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Er ging hinein und sprach zu ihnen: \"Was lärmt und weint ihr? Das Mädchen ist nicht tot; es schläft nur.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Da verlachten sie ihn. Er aber schickte alle weg, nahm nur den Vater und die Mutter des Kindes mit sich und die bei ihm waren und ging hinein, wo das Mädchen lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Dann faßte er das Mädchen bei der Hand und sprach zu ihm: \"Talitha kumi!\" - d.h. \"Mädchen, steh auf!\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Und sogleich stand das Mädchen auf und ging umher; es war zwölf Jahre alt. Sie gerieten vor Staunen ganz außer sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Er schärfte ihnen streng ein, daß niemand es erfahren dürfe; dann ließ er ihm zu essen geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Er ging von dort hinweg und kam in seine Vaterstadt, und seine Jünger begleiteten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Als es wieder Sabbat war, lehrte er in der Synagoge, und viele, die ihn hörten, fragten voll Erstaunen: \"Woher mag er all dies haben? Welche Weisheit ward ihm verliehen! Welch große Wunder geschehen durch seine Hände!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ist das nicht der Zimmermann, der Sohn der Maria und der Bruder des Jakobus, Joses, Judas und des Simon? Und wohnen denn nicht seine Schwestern hier bei uns?\" So nahm man an ihm Anstoß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Doch Jesus sprach zu ihnen: \"Ein Prophet gilt nirgends weniger als in seiner Vaterstadt, bei seinen eigenen Verwandten und in seinem Vaterhause.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Er konnte dort kein einziges Wunder wirken; nur daß er einigen Kranken die Hand auflegte und sie heilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Und er wunderte sich wegen ihres Unglaubens. Und lehrend zog er durch die Dörfer ringsumher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Alsdann rief er die Zwölf zu sich und begann, sie auszusenden, zu je zweien; auch gab er ihnen Macht über unreine Geister.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Weiter gebot er ihnen, nichts mitzunehmen auf den Weg als einen Stab, kein Brot und keinen Bettelsack und keine Münze im Gürtel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Doch dürften sie Sandalen tragen, aber nicht zwei Röcke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Ferner sprach er zu ihnen: \"Betretet ihr irgendwo ein Haus, dann bleibt dort, bis ihr weiterzieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Doch wo man euch nicht aufnimmt und auf euch nicht hört, da geht weg von dort und schüttelt den Staub von euren Füßen ihnen zum Zeugnis.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'So zogen sie nun hin und predigten, man solle Buße tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Sie trieben viele Geister aus, salbten viele Kranke mit Öl und heilten sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Die Kunde drang auch zum König Herodes; war doch sein Name in aller Mund. Er sprach: \"Johannes der Täufer ist von den Toten auferstanden. Darum wirken in ihm Gottes Kräfte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Doch andere behaupteten, er sei Elias; und wieder andere, er sei ein Prophet, wie einer aus den früheren Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Herodes aber meinte, als er davon hörte: \"Johannes, den ich habe enthaupten lassen, ist wieder von den Toten auferstanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Eben der Herodes hatte nämlich den Johannes gefangennehmen lassen und im Gefängnis ihn verwahrt wegen der Herodias, dem Weibe des Philippus, seines Bruders, die er geheiratet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Denn Johannes hatte dem Herodes vorgehalten: \"Es ist dir nicht erlaubt, das Weib deines Bruders zu haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Darum war die Herodias auf ihn erbost und hätte ihn gern töten lassen; sie brachte es aber nicht zuwege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Herodes hatte nämlich vor Johannes Ehrfurcht; er wußte, daß er ein gerechter und heiliger Mann war. So nahm er ihn in Schutz. Wenn er ihn anhörte, geriet er oft in Zwiespalt mit sich selbst, und trotzdem hörte er ihn gern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Da kam ein sehr gelegener Tag. An seinem Geburtsfest gab Herodes seinen Würdenträgern, den Obersten und Vornehmsten in Galiläa ein Mahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Da trat die Tochter eben der Herodias herein und tanzte. Und dies gefiel Herodes und den Gästen so, daß der König zu dem Mädchen sprach: \"Erbitte von mir, was du willst; ich werde es dir geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Ja, er schwur ihr: \"Was du von mir verlangst, will ich dir geben, und sollte es auch die Hälfte meines Reiches sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Sie ging hinaus und fragte ihre Mutter: \"Was soll ich verlangen?\" Und diese sagte: \"Den Kopf Johannes des Täufers.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Alsdann trat sie voll Eifer vor den König hin und bat: \"Ich will, laß mir sogleich auf einer Schüssel den Kopf Johannes des Täufers geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Da ward der König tief bestürzt; jedoch seiner Schwüre und der Gäste wegen wollte er sie nicht abweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Der König schickte sogleich einen Henker weg mit dem Befehl, seinen Kopf zu bringen. Der ging hinweg und enthauptete ihn im Gefängnis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'und brachte seinen Kopf auf einer Schüssel, gab ihn dem Mädchen, und das Mädchen gab ihn seiner Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Als seine Jünger davon hörten, kamen sie und holten seinen Leichnam und bargen ihn in einem Grabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Nun kehrten die Apostel wiederum zu Jesus zurück und erzählten ihm alles, was sie gewirkt und gepredigt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Er sprach zu ihnen: \"Kommt mit, ihr ganz allein, an einen abgelegenen Ort und ruht euch ein wenig aus.\" Denn viele gingen ab und zu, so daß sie nicht einmal Zeit zum Essen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Sie fuhren also für sich allein in einem Boot an einen abgelegenen Ort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Doch viele sahen, wie sie von dannen gingen, und erkannten ihre Absicht. Aus allen Städten strömten sie dorthin zu Fuß zusammen und kamen noch vor ihnen an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Er stieg aus und sah die große Menge, und er empfand ein herzliches Erbarmen über sie; sie waren wie Schafe ohne Hirten. Und er begann, sie mancherlei zu lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Als es schon spät geworden war, traten seine Jünger zu ihm hin und sprachen: \"Einsam ist der Ort und auch die Zeit schon vorgerückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Entlaß sie! Sie mögen in die Dörfer und die Flecken hier im Umkreis gehen und Nahrung für sich kaufen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Er aber sprach zu ihnen: \"Gebt ihr ihnen zu essen!\" Da sagten sie zu ihm: \"Sollen wir denn gehen und Brot für zweihundert Zehner kaufen und ihnen dann zu essen geben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Er fragte sie: \"Wieviel Brote habt ihr? Geht und seht nach!\" Sie sahen nach und sagten: \"Fünf, und zwei Fische.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Dann ließ er alle in Gruppen auf dem grünen Rasen sich lagern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Sie ließen sich nun Reih\' an Reihe nieder, zu je hundert und je fünfzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Dann nahm er die fünf Brote und die zwei Fische; er sah zum Himmel auf, segnete und brach die Brote und gab sie den Jüngern, um sie ihnen vorzulegen. Auch die zwei Fische ließ er unter alle verteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Und alle aßen und wurden satt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'ja, noch zwölf Körbe trugen sie hinweg, voll mit Stücken, auch von den Fischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Derer, die gegessen hatten, waren es fünftausend Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Sogleich drängte er die Jünger, in das Boot zu steigen und an das andere Ufer nach Bethsaida weiterzufahren, ihm voraus, während er selbst die Scharen entlassen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Und er entließ sie und stieg auf einen Berg, um zu beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Es war schon spät; das Boot war mitten auf dem Meer und er allein noch an Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Er sah, wie sie im Dahinfahren hart bedrängt waren; sie hatten nämlich Gegenwind. Da, um die vierte Nachtwache, kam er zu ihnen auf dem Meer daher. Er wollte an ihnen vorübergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Sie sahen ihn, wie er auf dem Meer wandelte, und meinten, es sei ein Gespenst, und schrien laut auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Denn alle sahen ihn und erschraken. Doch alsbald redete er sie an und sprach zu ihnen: \"Nur Mut! Ich bin es. Habt keine Angst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Dann stieg er zu ihnen ins Boot, und sogleich legte sich der Wind. Jetzt gerieten sie erst recht ganz außer sich;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'das mit den Broten nämlich hatten sie noch nicht verstanden; ihr Sinn war immer noch verschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Sie fuhren vollends hinüber und kamen bei Genesareth ans Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Und wie sie aus dem Boote stiegen, ward er sofort erkannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Man lief die ganze Gegend aus und trug voll Eifer Kranke auf Betten dahin, wo sie hörten, daß er sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Wo immer er Dörfer, Städte oder Gehöfte betrat, da legte man die Kranken auf die Plätze und bat ihn, sie möchten nur den Saum seines Kleides berühren dürfen. Und alle, die ihn berührten, wurden gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Da kamen zu ihm Pharisäer und einige Schriftgelehrte aus Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Und da sie sahen, daß etliche seiner Jünger mit \"gemeinen\", das heißt mit ungewaschenen, Händen ihre Mahlzeit hielten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(-die Pharisäer und die Juden überhaupt essen nämlich nicht, ehe sie sich die Hände nicht mit einer Handvoll Wasser gewaschen haben, getreu der Überlieferung der Alten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Auch wenn sie von dem Markt kommen, so essen sie nicht, ohne sich gewaschen zu haben. Auch sonst gibt es noch vieles andere, was sie streng nach der Überlieferung beobachten: Abspülung von Bechern, Krügen, Kesseln Bettgestellen.-),');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'fragten die Pharisäer und die Schriftgelehrten ihn also: \"Warum leben deine Jünger nicht nach der Überlieferung der Alten, sondern essen mit \'gemeinen\' Händen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Da sagte er zu ihnen: \"Richtig hat Isaias über euch, ihr Heuchler, schon geweissagt; denn also steht geschrieben: \'Dieses Volk ehrt mich mit den Lippen; ihr Herz jedoch ist weit von mir;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'nichtig ist ihr Gottesdienst; Menschensatzungen machen sie zu ihrer Lehre.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ihr gebt das Gebot Gottes preis und haltet euch an die Überlieferung der Menschen; Abspülung von Krügen, Bechern und vieles andere dergleichen tut ihr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Er fuhr dann fort: \"Gar trefflich schiebt ihr das Gebot Gottes beiseite, um eure Überlieferung zu wahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Moses hat einst geboten: \'Du sollst Vater und Mutter ehren!\' und \'Wer Vater oder Mutter schmäht, soll sterben!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ihr aber sagt: \'Wer zu Vater oder Mutter spricht: Was ich dir zu leisten hätte, ist \'korban\' - d.h. Opfergabe -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'dann laßt ihr ihn für Vater oder Mutter nichts mehr tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Also entkräftet ihr, was Gott gesprochen hat, durch eure Überlieferung, die ihr überliefert habt. Und dergleichen treibt ihr noch viel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Er rief sodann die Scharen wieder zu sich her und sprach zu ihnen: \"Hört alle und versteht es wohl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nichts gibt es, was von außen in den Menschen kommt und ihn unrein machen könnte; nein, was vom Menschen ausgeht, das macht den Menschen unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Wer Ohren hat zu hören, der höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Als er von der Menge weg ins Haus getreten war, da fragten ihn die Jünger nach dem Gleichnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Er sprach zu ihnen: \"Seid denn auch ihr immer noch unverständig? Versteht ihr wirklich nicht, daß, was immer von außen in den Menschen kommt, ihn nicht unrein machen kann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'weil es nicht in sein Herz eingeht, sondern in den Magen und den naturgemäßen Ausgang nimmt.\" - Alle Speisen erklärte er damit für rein. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, '\"Was aber aus dem Menschen kommt\", so fuhr er fort, \"das macht den Menschen unrein. 21 Von innen, aus den Herzen der Menschen, gehen schändliche Gedanken, Unzucht, Diebstahl, Mord,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Ehebruch, Habgier, Bosheit, Arglist, Ausschweifung, Neid, Lästerung, Hochmut, Unverstand hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Alle diese bösen Dinge kommen aus dem Innern, und sie machen den Menschen unrein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Dann brach er auf und ging von dort hinweg ins Land von Tyrus und Sidon. Er begab sich in ein Haus, doch wollte er es niemand wissen lassen; allein er konnte nicht verborgen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ein Weib, dessen Töchterchen von einem unreinen Geist besessen war, hatte schon von ihm erfahren. Sie kam herzu und fiel ihm zu Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Das Weib war eine Heidin und stammte aus dem syrischen Phönizien. Sie bat ihn, daß er den Dämon aus ihrer Tochter austreibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Er aber sprach zu ihr: \"Laß doch die Kinder erst einmal gesättigt werden! Es ist nicht recht, den Kindern das Brot wegzunehmen und es den Hunden vorzuwerfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Doch sie entgegnete und sprach zu ihm: \"Gewiß, o Herr! Doch auch die Hunde unterm Tisch fressen, was die Kinder übriglassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Da sagte er zu ihr: \"Um dieses Wortes willen geh heim! Der Dämon ist aus deiner Tochter ausgefahren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Sie ging nach Hause, fand das Kind auf seinem Bett liegen; der Dämon war wirklich ausgefahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Und er verließ das Land von Tyrus wieder und begab sich über Sidon mitten in das Gebiet der Dekapolis hinein an das Meer von Galiläa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Da brachte man ihm einen Tauben, der zugleich stumm war, und bat ihn, daß er ihm die Hand auflege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Er nahm ihn aus der Menge weg, abseits, und legte ihm seine Finger in die Ohren, berührte seine Zunge mit Speichel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'schaute zum Himmel auf, seufzte und sprach zu ihm: \"Effetha!\" das heißt: Tu dich auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Und sogleich waren ihm die Ohren aufgetan; gelöst war das Band seiner Zunge, und er konnte richtig sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jedoch er verbot ihnen, dies weiter auszusagen; allein je strenger er es ihnen verwehrte, desto weiter machten sie es bekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Und man staunte über alle Maßen und sagte: \"Er macht alles wohl; die Tauben macht er hören und die Stummen reden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'In jenen Tagen war wieder einmal eine große Volksmenge beisammen und hatte nichts zu essen. Da rief er seine Jünger zu sich her und sprach zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '\"Mich erbarmt des Volkes. Schon drei Tage harren sie bei mir aus und haben nichts zu essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Wenn ich sie hungrig nach Hause gehen lasse, könnten sie auf dem Weg verschmachten, und manche unter ihnen sind weit hergekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Seine Jünger aber gaben ihm zur Antwort: \"Wie sollte man sie hier in der Steppe mit Broten sättigen können?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Da fragte er sie: \"Wieviel Brote habt ihr denn?\" Sie sprachen: \"Sieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Nun hieß er die Leute, sich auf den Boden lagern. Dann nahm er die sieben Brote, dankte, brach sie und gab sie seinen Jüngern, daß diese sie austeilen möchten. Sie teilten sie der Menge aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Auch ein paar Fischlein hatten sie. Er segnete auch diese und ließ auch sie verteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Sie aßen und wurden satt; sie trugen auch noch sieben Körbe weg mit Stücken, die übriggeblieben waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Es waren wohl an viertausend gewesen die gegessen hatten; alsdann entließ er sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Sogleich stieg er mit seinen Jüngern in das Boot, und er gelangte in die Gegend von Dalmanutha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Da kamen auch die Pharisäer, und sie versuchten, sich mit ihm einzulassen. Sie wollten ihn auf die Probe stellen und verlangten von ihm ein Zeichen aus dem Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Da seufzte er aus tiefstem Herzensgrund und sprach: \"Wozu verlangt dieses Geschlecht ein Zeichen? Wahrlich, ich sage euch: Diesem Geschlecht wird kein Zeichen gegeben werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Damit ließ er sie stehen, stieg wieder ein und fuhr ans andere Ufer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Sie hatten vergessen, Brote mitzunehmen; nur ein einziges Brot hatten sie bei sich im Boote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Er warnte sie und sprach zu ihnen: \"Habt acht und hütet euch vor dem Sauerteig der Pharisäer und vor dem Sauerteig des Herodes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Sie besprachen sich und sagten schließlich: \"Wir haben ja kein Brot bei uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Doch Jesus merkte dies und sprach zu ihnen: \"Was besprecht ihr miteinander, weil ihr keine Brote habt; begreift und versteht ihr denn immer noch nicht? Ist euer Herz noch ganz verschlossen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Ihr habt Augen, seht aber nicht, und Ohren habt ihr, hört aber nicht. Erinnert ihr euch denn nicht mehr,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'daß ich fünf Brote für die Fünftausend brach? Wie viele Körbe, voll mit Stücken, habt ihr noch fortgetragen?\" Sie sagten zu ihm: \"Zwölf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '\"Und bei den sieben für die Viertausend: Wie viele Körbe, voll mit Stücken, habt ihr da noch fortgetragen?\" Sie gaben ihm zur Antwort: \"Sieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Er sprach zu ihnen: \"Versteht ihr es denn immer noch nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Sie kamen nach Bethsaida. Dort brachte man ihm einen Blinden; sie baten ihn, er möge ihn nur berühren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Er nahm den Blinden bei der Hand und führte ihn vors Dorf hinaus. Alsdann tat er Speichel in seine Augen, legte ihm die Hände auf und fragte ihn: \"Siehst du etwas?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Er sah auf und sagte: \"Ich sehe die Menschen; ich sehe etwas wie Bäume, daß sie sich bewegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Dann legte er ihm die Hände nochmals auf die Augen. Sein Blick drang jetzt ganz durch, er wurde wiederhergestellt und konnte alles deutlich sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Dann sandte er ihn heim und sprach: \"Geh nicht ins Dorf hinein!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Darauf ging Jesus mit seinen Jüngern in die Ortschaften von Cäsarea Philippi. Auf dem Wege fragte er seine Jünger: \"Für wen halten mich die Leute?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Sie gaben ihm zur Antwort: \"Für Johannes den Täufer, andere für Elias, wieder andere für irgendeinen Propheten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Da fragte er sie weiter: \"Für wen haltet ihr mich?\" Darauf gab ihm Petrus zur Antwort: \"Du bist der Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Er aber schärfte ihnen streng ein, sie sollten über ihn zu niemand reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Nun fing er an, sie zu belehren, daß der Menschensohn vieles leiden müsse; er müsse von den Ältesten, den Oberpriestern und den Schriftgelehrten verworfen werden, er müsse getötet werden, doch nach drei Tagen werde er wieder auferstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Er sagte das ganz offen. Da nahm ihn Petrus beiseite und wollte ihm ernstlich zureden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Er aber wandte sich um, und angesichts der Jünger schalt er Petrus mit den Worten: \"Hinweg von mir, du Satan! Du hast nicht Sinn fürs Göttliche, sondern nur fürs Menschliche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Alsdann rief er die Menge samt seinen Jüngern her und sprach zu ihnen: \"Wer mir nachfolgen will, der verleugne sich selbst, nehme sein Kreuz auf sich und folge mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Denn wer sein Leben sich erhalten will, der wird es verlieren, und wer sein Leben mir und dem Evangelium zulieb verliert, der wird es erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Was nützte es dem Menschen, wenn er die ganze Welt gewänne, doch sein Leben dabei verlöre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Was könnte auch einer geben als Kaufpreis für sein Leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Denn wer sich bei diesem Geschlecht voll Ehebruch und Sünde meiner und meiner Worte schämt, dessen wird auch der Menschensohn sich schämen, wenn er mitsamt den heiligen Engeln in der Herrlichkeit seines Vaters kommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Und weiter sprach er zu ihnen: \"Wahrlich, ich sage euch: Es stehen solche hier, die den Tod nicht kosten werden, bis sie das Gottesreich in Macht erscheinen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Sechs Tage später nahm Jesus den Petrus, Jakobus und Johannes mit sich und führte sie allein auf einen hohen Berg abseits. Und er ward verwandelt vor ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Seine Kleider wurden schimmernd weiß, wie sie kein Walker auf der Erde bleichen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Und es erschienen ihnen Elias mit Moses, die sich mit Jesus unterhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Petrus nahm das Wort und sprach zu Jesus: \"Rabbi, wie schön ist es doch, daß wir hier sind. Laß uns drei Hütten bauen: dir eine, dem Moses eine und dem Elias eine.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Er wußte nicht, was er sprach: sie waren vor Schrecken außer sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Doch da kam eine Wolke, die ihren Schatten auf sie warf, und eine Stimme aus der Wolke sprach: \"Das ist mein vielgeliebter Sohn; auf diesen sollt ihr hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Rasch schauten sie umher, sie sahen aber niemand mehr bei sich als Jesus allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Während sie vom Berge niederstiegen, befahl er ihnen streng, niemand zu erzählen von dem, was sie gesehen hatten, bis der Menschensohn von den Toten auferstanden sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'An diesem Worte blieben sie nun hängen und stritten miteinander, was das zu bedeuten habe: das Auferstehen von den Toten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Sie fragten ihn und sprachen: \"Es sagen aber doch die Pharisäer und Schriftgelehrten, Elias müsse vorher noch kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Er sprach zu ihnen: \"Elias kommt allerdings vorher, und er wird alles wieder herstellen. Wie kann dann aber vom Menschensohn geschrieben sein, daß er viel leiden müsse und verkannt werde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Gewiß, ich sage euch: Elias ist schon da. Doch hat man mit ihm angefangen, was man wollte, wie über ihn geschrieben steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Sie kamen zu den Jüngern und sahen eine große Menge um sie her, auch Schriftgelehrte, die mit ihnen stritten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Sobald ihn die Menge erblickte, geriet sie in Erregung und eilte ihm entgegen, ihn zu grüßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Er fragte sie: \"Worüber streitet ihr mit ihnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Da erwiderte ihm einer aus der Menge: \"Meister, ich brachte meinen Sohn zu dir, er ist von einem stummen Geiste besessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Wenn der ihn packt, zerrt er ihn hin und her; dann schäumt er und knirscht mit den Zähnen und liegt starr da. Ich bat deine Jünger, sie möchten ihn austreiben; sie hatten aber nicht die Kraft dazu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Darauf erwiderte er ihnen: \"O du ungläubiges Geschlecht. Wie lang noch muß ich bei euch bleiben? Wie lang noch muß ich euch ertragen? Bringt ihn her zu mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Da brachten sie ihn zu ihm. Doch wie der Geist ihn erblickte, riß er den Knaben hin und her; dieser fiel zu Boden und wälzte sich schäumend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Und Jesus fragte seinen Vater: \"Wie lang schon hat er das?\" Er sprach: \"Von Kindheit an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Oft wirft er ihn sogar ins Feuer oder auch ins Wasser, um ihn umzubringen. Wenn du das kannst, so hilf uns; hab Erbarmen mit uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Und Jesus sprach zu ihm: \"Wenn du das kannst? Wer glaubt, kann alles.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Sofort rief der Vater des Knaben unter Tränen: \"Ich glaube Herr. Hilf meinem Unglauben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Als Jesus sah, wie das Volk immer dichter zusammenströmte, bedrohte er den unreinen Geist und rief ihm zu: \"Du stummer und tauber Geist, ich befehle dir, fahre aus von ihm und kehre niemals mehr in ihn zurück!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Da schrie er auf, zerrte ihn heftig hin und her und fuhr dann von ihm aus. Der Knabe lag da wie tot, so daß die meisten sagten: \"Er ist tot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Doch Jesus nahm ihn bei der Hand und half ihm auf, und er stand aufrecht da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Er ging darauf ins Haus. Insgeheim fragten ihn seine Jünger: \"Warum konnten wir ihn nicht austreiben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Er aber sprach zu ihnen: \"Diese Art kann man nur durch Beten und Fasten austreiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Sie gingen weg von dort und wanderten durch Galiläa hin; doch wollte er nicht, daß es jemand erfahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Denn er belehrte seine Jünger und sagte ihnen: \"Der Menschensohn wird in die Hände der Menschen überliefert werden; man wird ihn töten; jedoch drei Tage nach seinem Tode wird er auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Doch sie begriffen diese Rede nicht; sie scheuten sich indes, ihn zu fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Sie kamen nach Kapharnaum. Zu Hause fragte er sie: \"Worüber habt ihr unterwegs gestritten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Sie aber schwiegen. Sie hatten nämlich unterwegs miteinander gestritten, wer der Größte sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Er setzte sich und rief die Zwölf zu sich her und sprach zu ihnen: \"Wer der Erste sein möchte, der sei der Letzte und der Diener aller.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Darauf nahm er ein Kind, stellte es mitten unter sie, schloß es in die Arme und sprach zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '\"Wer ein solches Kind wie dieses hier in meinem Namen aufnimmt, nimmt mich auf; und wer mich aufnimmt, nimmt nicht mich auf, sondern den, der mich gesandt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes sprach zu ihm: \"Meister, wir sahen einen, der in deinem Namen Dämonen austrieb, aber nicht mit uns geht. Wir suchten ihn zu hindern, weil er nicht mit uns geht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Doch Jesus sprach: \"Hindert ihn nicht! Keiner kann in meinem Namen Wunder wirken und gleich nachher wieder Böses von mir reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Wer nicht gegen uns ist, der ist für uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Wer euch in meinem Namen nur einen Becher Wassers zu trinken reicht, weil ihr Christus angehört, ich sage euch: Er wird seinen Lohn nicht verlieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Wer aber einem dieser Kleinen, die an mich glauben, Anlaß zur Sünde gibt, dem ist es besser, daß ihm ein Mühlstein an den Hals gehängt und er ins Meer geworfen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Gibt dir deine Hand zur Sünde Anlaß, so hau sie ab! Besser ist es für dich, verstümmelt zum Leben einzugehen, als daß du zwei Hände habest und in die Hölle gehen mußt, ins unauslöschliche Feuer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Gibt dir dein Fuß zur Sünde Anlaß, so hau ihn ab! Besser ist es für dich, hinkend zum Leben einzugehen, als daß du zwei Füße habest und in die Hölle geworfen wirst, ins unauslöschliche Feuer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Gibt dir dein Auge zur Sünde Anlaß, so reiß es aus! Besser ist es für dich, mit einem Auge in das Reich Gottes einzugehen, als daß du zwei Augen habest und in die Hölle geworfen wirst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Jeder soll mit Feuer gesalzen werden wie jedes Opfer mit Salz gesalzen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Das Salz ist etwas Gutes. Doch wenn das Salz einmal schal geworden ist, womit wollt ihr es dann würzen? Habt Salz in euch und haltet Frieden mit einander!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Er machte sich auf und zog in die Gegend von Judäa und über den Jordan. Und wieder sammelten sich bei ihm große Scharen, und wie gewöhnlich lehrte er sie wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Da traten zu ihm Pharisäer, versuchten ihn und fragten, ob es dem Mann erlaubt sei, daß er sein Weib entlasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Er sprach zu ihnen: \"Was hat euch Moses geboten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Sie sprachen: \"Moses hat erlaubt, einen Scheidebrief zu schreiben und alsdann zu entlassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Doch Jesus sprach zu ihnen: \"Nur eurer Herzenshärte wegen hat er dieses Gebot für euch geschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Doch im Anfang der Schöpfung schuf sie Gott als Mann und Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'So wird der Mann Vater und Mutter verlassen und sich seinem Weibe verbinden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'und diese zwei werden zu einem Fleische werden. So sind sie also nicht mehr zwei, vielmehr sind sie ein einziges Fleisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Was aber Gott vereinigt hat, das soll der Mensch nicht trennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Zu Hause fragten ihn dann seine Jünger noch einmal darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Er sprach zu ihnen: \"Wer sein Weib entläßt und eine andere heiratet, bricht ihr die Ehe;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'und wenn sie ihren Mann entläßt und einen anderen heiratet, bricht sie die Ehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Man brachte zu ihm Kinder, damit er sie berühre. Allein die Jünger fuhren jene, die sie brachten, an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Als Jesus dies bemerkte, ward er unwillig und sprach zu ihnen: \"Laßt die Kinder zu mir kommen, wehrt es ihnen nicht; für solche ist das Reich Gottes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Wahrlich, ich sage euch: Wer das Reich Gottes nicht aufnimmt wie ein Kind, kommt sicherlich nicht hinein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Dann schloß er sie in seine Arme, legte ihnen seine Hände auf und gab ihnen den Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Er machte sich wieder auf den Weg, da lief einer auf ihn zu, fiel vor ihm auf die Knie und fragte ihn: \"Guter Meister, was muß ich tun, um das ewige Leben zu erwerben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Und Jesus sprach zu ihm: \"Was nennst du mich \'gut\'? Niemand ist gut als Gott allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Du kennst die Gebote: \'Du sollst nicht töten!\' \'Du sollst nicht ehebrechen!\' \'Du sollst nicht stehlen!\' \'Du sollst kein falsches Zeugnis geben!\' \'Du sollst nicht betrügen!\' \'Du sollst Vater und Mutter ehren!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Doch dieser sprach zu ihm: \"All dies, Meister, habe ich von Jugend auf gehalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Und Jesus schaute ihn liebevoll an und sprach zu ihm: \"Eines fehlt dir noch. Geh hin, verkaufe, was du hast, und schenke es den Armen; du wirst dann einen Schatz im Himmel haben. Dann komm und folge mir und trage dein Kreuz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Bei diesen Worten ward er kleinmütig und ging betrübt von dannen, denn er besaß viele Güter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Da schaute Jesus sich um und sprach zu seinen Jüngern: \"Wie schwer geht es doch, daß die Reichen in das Reich Gottes gelangen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Die Jünger waren über seine Worte sehr betroffen. Doch Jesus sprach noch einmal zu ihnen: \"Kinder! Wie schwer ist es doch für die, die auf ihr Geld vertrauen, in das Reich Gottes zu kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Viel leichter geht ein Kamel durch ein Nadelöhr, als ein Reicher in das Reich Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Darauf erschraken sie noch mehr und sagten zueinander: \"Wer kann da noch gerettet werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Da sah sie Jesus an und sprach zu ihnen: \"Bei den Menschen ist dies freilich unmöglich, doch nicht bei Gott; bei Gott ist alles möglich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Da nahm Petrus das Wort und sprach: \"Siehe, wir haben alles verlassen und sind dir nachgefolgt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Und Jesus sprach: \"Wahrlich, ich sage euch: Wer immer Haus, Brüder oder Schwestern, Mutter, Vater oder Kinder oder Äcker verläßt um meinetwillen und des Evangeliums wegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'wird es hundertfach zurückerhalten: in dieser Welt an Häusern, an Brüdern, Schwestern, Müttern, Kindern und an Äckern, allerdings unter Verfolgung, und in der anderen Welt das ewige Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Viele Erste werden Letzte und viele Letzte werden Erste sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Sie befanden sich auf dem Weg nach Jerusalem hinauf, und Jesus war ihnen stets weit voran, so daß sie sich entsetzten; sie folgten ihm, jedoch mit bangem Herzen. Er nahm die Zwölf wieder zu sich und begann mit ihnen über das zu sprechen, was ihm begegnen werde:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '\"Seht, wir ziehen nach Jerusalem hinauf. Der Menschensohn wird den Oberpriestern und den Schriftgelehrten und Ältesten ausgeliefert werden, sie werden ihn zum Tod verdammen und ihn den Heiden übergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Sie werden ihn verspotten und anspeien, geißeln und töten; doch nach drei Tagen wird er auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Da traten Jakobus und Johannes, die Zebedäussöhne, zu ihm hin und sprachen: \"Meister, wir möchten, daß du uns gewährst, um was wir dich bitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Er sprach zu ihnen: \"Was soll ich euch tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Sie antworteten ihm: \"Verleihe uns, daß wir in deiner Herrlichkeit der eine dir zur Rechten, der andere dir zur Linken sitzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Doch Jesus sprach zu ihnen: \"Ihr wißt nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den ich trinken muß, die Taufe, die ich empfange, auch empfangen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Sie sagten ihm: \"Wir können es.\" Doch Jesus sprach zu ihnen: \"Den Kelch, den ich trinke, werdet ihr zwar trinken, und auch die Taufe empfangen, die ich empfange,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'die Sitze zu meiner Rechten und zu meiner Linken aber, die kann ich nicht vergeben; denn sie gehören denen, für die sie schon bestimmt sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Als die anderen zehn das hörten, wurden sie unwillig über Jakobus und Johannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Doch Jesus rief sie zu sich her und sprach zu ihnen: \"Ihr wißt: Die als Fürsten der Heidenvölker gelten, wollen über ihre Völker den Herrn spielen, und ihre Großen lassen sie ihre Macht fühlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Bei euch ist es aber nicht so; sondern wer unter euch ein Großer werden will, sei euer Diener,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'und wer unter euch Erster sein will, sei der Knecht aller,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'wie auch der Menschensohn nicht gekommen ist, bedient zu werden, vielmehr zu dienen, ja, sein Leben hinzuopfern als Lösegeld für viele.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'So kamen sie nach Jericho. Als er mit seinen Jüngern und mit vielem Volke Jericho verließ, saß der Sohn des Timäus, der Bartimäus, ein blinder Bettler, am Wege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Als er vernahm: Jesus von Nazareth ist es, begann er laut zu schreien und zu rufen: \"Sohn Davids, Jesus, erbarme dich meiner!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Da fuhren ihn viele an, er solle schweigen. Er aber rief nur um so lauter: \"Sohn Davids, erbarme dich meiner!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Darauf blieb Jesus stehen und sprach: \"Ruft ihn her!\" Da riefen sie den Blinden her und sagten ihm: \"Sei guten Muts! Steh auf! Er ruft dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Da warf er seinen Mantel ab, sprang auf und kam zu Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Und Jesus sprach zu ihm: \"Was soll ich dir tun?\" Der Blinde sprach zu ihm: \"Rabbuni, ich möchte wieder sehen können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Und Jesus sprach zu ihm: \"Geh hin, dein Glaube hat dir geholfen.\" Und sogleich konnte er sehen und folgte ihm auf dem Wege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Sie kamen in die Nähe von Jerusalem, nach Bethphage und nach Bethanien am Ölberg. Er sandte zwei von seinen Jüngern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'mit dem Auftrag fort: \"Geht in das Dorf, das vor euch liegt. Gleich am Eingang findet ihr ein Füllen angebunden, auf dem noch niemals jemand saß. Löst es los und bringt es her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Und sollte jemand zu euch sagen: \'Was macht ihr da?\' dann sagt: \'Der Herr braucht es. Er schickt es gleich wieder zurück.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Sie gingen weg und fanden am Hoftor ein Füllen angebunden, außen nach der Straße zu. Sie lösten es los.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Und einige von denen, die dort standen, fragten sie: \"Was macht ihr da; ihr bindet ja das Füllen los?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Doch sie erwiderten, wie Jesus ihnen aufgetragen hatte. Da ließ man sie gewähren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Sie brachten das Füllen zu Jesus, legten ihre Kleider darauf, und er setzte sich darauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Und viele breiteten ihre Kleider auf den Weg, andere als Büschel das, was sie auf den Feldern abgeschnitten hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Die vor und hinter ihm einhergingen, riefen: \"Hosanna! Gepriesen sei, der im Namen des Herrn kommt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Gepriesen sei das Reich unseres Vaters David, das jetzt erscheint. Hosanna in der Höhe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'So zog er nach Jerusalem hinein in den Tempel. Er schaute alles ringsum an und ging nach Bethanien mit den Zwölfen, weil es schon spät war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Als sie des anderen Tages wieder von Bethanien weggingen, empfand er Hunger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Von weitem sah er einen Feigenbaum, voll mit Blättern, ging auf ihn zu, ob er nicht etwas an ihm fände. Doch wie er hinkam, fand er nichts als Blätter; es war nämlich noch nicht Feigenzeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Er aber sprach zu ihm: \"Nie mehr, in Ewigkeit nicht, soll jemand von dir Frucht essen.\" Und seine Jünger hörten das.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Sie kamen nach Jerusalem. Da ging er in den Tempel und machte sich daran, die Käufer und Verkäufer aus dem Tempel auszutreiben. Die Tische der Wechsler und die Bänke der Taubenhändler stieß er um');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'und ließ es nicht geschehen, daß jemand ein Gefäß durch den Tempel trage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Und er belehrte sie und sprach: \"Steht denn nicht geschrieben: \'Mein Haus soll ein Bethaus heißen für alle Völker, doch ihr habt eine Räuberhöhle daraus gemacht.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Als dies die Oberpriester und die Schriftgelehrten hörten, suchten sie, wie sie ihn verderben könnten. Sie fürchteten ihn nämlich; es war ja alles Volk von seiner Lehre überwältigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Als es dann Abend wurde, entfernten sie sich aus der Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Als sie des anderen Morgens an dem Feigenbaum vorübergingen, da sahen sie, daß er von der Wurzel an ganz verdorrt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Da erinnerte sich Petrus und sprach zu ihm: \"Rabbi, sieh, der Feigenbaum, den du verflucht hast, ist ganz verdorrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Und Jesus sprach zu ihnen: \"Habt Glauben an Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Wahrlich, ich sage euch: Wenn einer zu dem Berg da spräche: \'Hebe dich hinweg und stürze dich ins Meer!\' und er in seinem Innern nicht zweifelt, vielmehr glaubt, daß, was er sagt, geschehen wird, er wird es zustande bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'So sage ich euch denn: Um was ihr immer im Gebete bittet, glaubt nur, daß ihr es schon habt; dann wird es euch zuteil werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Und steht ihr zum Beten da, verzeiht, wenn ihr gegen jemand etwas habt, damit auch euer Vater in den Himmeln euch eure Sünden vergeben möge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Wenn aber ihr nicht verzeiht, wird auch mein Vater, der in den Himmeln ist, euch eure Sünden nicht verzeihen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Sie kamen wieder nach Jerusalem. Und während er im Tempel hin und her ging, näherten sich ihm die Oberpriester und die Schriftgelehrten sowie die Ältesten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'und fragten ihn: \"Mit welcher Vollmacht tust du das? Wer hat dir das Recht gegeben, dies zu tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Doch Jesus sprach zu ihnen: \"Auch ich will euch nach etwas fragen; gebt ihr mir Antwort, dann will auch ich euch sagen, mit welcher Vollmacht ich dies tue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Kam die Johannestaufe vom Himmel oder von den Menschen? Gebt mir Antwort!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Da überlegten sie miteinander und sprachen: \"Sagen wir \'vom Himmel\', so wird er fragen: \'Warum habt ihr ihm dann nicht geglaubt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Oder sollen wir sagen: \'Von Menschen?\'\" Doch dazu fürchteten sie das Volk; denn alle hielten den Johannes für einen wirklichen Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Und so erwiderten sie Jesu: \"Wir wissen es nicht.\" Darauf erwiderte ihnen Jesus: \"Dann sage auch ich nicht, mit welcher Vollmacht ich dies tue.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Und dann begann er, in Gleichnissen zu ihnen zu reden. \"Es pflanzte jemand einen Weinberg, umgab ihn mit einem Zaun, grub eine Kelter und baute einen Turm. Darauf verpachtete er ihn an Winzer und ging außer Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Als nun die Zeit gekommen war, da schickte er einen Knecht zu den Winzern, um von den Winzern vom Ertrag des Weinbergs zu empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Doch diese packten ihn, schlugen ihn und schickten ihn mit leeren Händen heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Da schickte er ein zweitesmal einen anderen Knecht zu ihnen, doch sie mißhandelten auch diesen und beschimpften ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Noch einen dritten schickte er; diesen brachten sie sogar ums Leben; und so noch viele andere, die sie teils mißhandelten, teils ermordeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Nun hatte er noch einen, seinen vielgeliebten Sohn. Den schickte er zuletzt zu ihnen; er sagte sich: \'Vor meinem Sohne werden sie doch Achtung haben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Doch jene Winzer sprachen zueinander: \'Das ist der Erbe; kommt, den töten wir; dann gehört sein Erbteil uns.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Und sie ergriffen ihn und brachten ihn ums Leben und warfen ihn zum Weinberg hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Was wird wohl der Herr des Weinbergs tun? Er wird kommen und die Winzer töten und seinen Weinberg anderen anvertrauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Habt ihr nie die Stelle in der Schrift gelesen: \'Der Stein, den die Bauleute verworfen haben, der ist zum Schlußstein geworden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'durch den Herrn ist dies geschehen, und es ist wunderbar in unseren Augen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Sie hätten sich seiner gern bemächtigt; allein sie fürchteten sich vor dem Volke. Sie hatten nämlich wohl erkannt, daß dieses Gleichnis ihnen gelte. So ließen sie ihn stehen und gingen weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Sie schickten alsdann einige von den Pharisäern und den Herodianern zu ihm, damit sie ihn mit einer Rede fangen sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Sie kamen und sagten zu ihm: \"Meister, wir wissen, daß du wahrhaftig bist; du fragst nach niemand; du siehst nicht auf die Stellung der Menschen, sondern lehrst den Weg Gottes in Wahrheit: Darf man dem Kaiser Steuer zahlen oder nicht? Sollen wir bezahlen oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Doch er erkannte ihre Heuchelei und sprach zu ihnen: \"Warum versucht ihr mich? Zeigt mir einen Denar, damit ich sehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Sie reichten einen hin. Er fragte sie: \"Wessen Bild und Aufschrift ist das?\" \"Des Kaisers\", gaben sie ihm zur Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Darauf entgegnete ihnen Jesus: \"So gebt dem Kaiser, was des Kaisers, und Gott, was Gottes ist.\" Und sie staunten über ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Jetzt kamen die Sadduzäer zu ihm; - diese leugnen, daß es eine Auferstehung gebe - sie fragten ihn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '\"Meister, bei Moses steht geschrieben: \'Wenn irgend jemands Bruder stirbt und er ein Weib, doch kein Kind hinterläßt, dann soll der Bruder dessen Weib heiraten und seinem Bruder Nachkommen erwecken.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Da waren sieben Brüder. Der erste nahm ein Weib; doch er starb kinderlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Darauf nahm sie der zweite; allein auch er starb kinderlos und ebenso der dritte;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'alle sieben blieben kinderlos. Zuletzt von allen starb dann auch das Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Wessen Weib wird sie nun bei der Auferstehung sein; - gesetzt den Fall, daß sie wirklich auferstehen - denn alle sieben haben sie zum Weibe gehabt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Und Jesus sprach zu ihnen: \"Liegt nicht schon darin euer Irrtum, daß ihr weder die Schriften noch die Allmacht Gottes kennt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Denn wenn man von den Toten aufersteht, dann heiratet man nicht mehr und wird auch nicht verheiratet; man ist vielmehr so wie die Engel in den Himmeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Was aber die Auferstehung der Toten betrifft, habt ihr nicht im Buche Mosis gelesen, wie bei der Stelle von dem Dornbusch Gott zu ihm sprach: \'Ich bin der Gott Abrahams, der Gott Isaaks und der Gott Jakobs\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Gott ist doch nicht ein Gott der Toten, sondern der Lebendigen. Ihr irrt euch also gewaltig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Ein Schriftgelehrter, der ihrem Wortstreit zugehört hatte und einsah, daß er ihnen gut erwidert hatte, trat herzu und fragte ihn: \"Was ist das erste unter allen Geboten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Und Jesus sprach: \"Das erste ist: \'Höre, Israel, der Herr unser Gott ist allein der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen, aus deiner ganzen Seele, aus deinem ganzen Gemüte und deiner ganzen Kraft.\' Dies ist das erste Gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Das zweite lautet: \'Du sollst deinen Nächsten lieben wie dich selbst.\' Ein größeres Gebot als diese gibt es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Da sprach zu ihm der Schriftgelehrte: \"Vortrefflich, Meister! Ganz richtig hast du ausgeführt, daß er nur einer ist und daß kein anderer ist außer ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Auch das \'Ihn lieben aus ganzem Herzen und aus ganzem Gemüte und aus aller Kraft\', und das \'Du sollst den Nächsten lieben wie dich selbst\', ist wertvoller als alle Brand- und anderen Opfer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Als Jesus vernahm, wie er so verständig Antwort gab, sprach er zu ihm: \"Du bist nicht mehr weit vom Reiche Gottes entfernt.\" Und keiner wagte mehr, ihn etwas zu fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Als Jesus dann im Tempel lehrte, fragte er: \"Wie können die Schriftgelehrten sagen, der Christus sei der Sohn Davids?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Sagt doch David selbst im Heiligen Geist: \'Es sprach der Herr zu meinem Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde dir als Schemel zu Füßen lege.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'So nennt ihn David also selber \'Herr\': Wie kann er dann sein Sohn sein?\" Die große Menge hörte ihm gerne zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Und weiter sagte er in seiner Lehre: \"Hütet euch vor den Schriftgelehrten! Sie lieben es, in langen Kleidern einherzugehen, auf den öffentlichen Plätzen gegrüßt zu werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'in der Synagoge die Ehrensitze einzunehmen und bei den Gastmählern die Ehrenplätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Sie verprassen die Häuser der Witwen und sagen nur zum Schein lange Gebete dafür her. Eine härtere Strafe erwartet diese.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Er saß dem Opferkasten gegenüber und schaute zu, wie das Volk in den Opferkasten sein Geld einwarf, und viele Reiche warfen viel hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Auch eine bettelarme Witwe kam herbei und warf zwei Heller ein, das heißt soviel wie einen Pfennig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Da rief er seine Jünger zu sich her und sprach zu ihnen: \"Wahrlich, ich sage euch: Diese arme Witwe gab mehr in den Opferkasten als alle anderen, die etwas hineingeworfen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Denn alle warfen von ihrem Überfluß hinein; sie aber gab in ihrer Armut alles, was sie hatte, ihren ganzen Lebensunterhalt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Als er den Tempel verließ, da redete ihn einer seiner Jünger an: \"Schau, Meister, was für Steine, was für Bauten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Doch Jesus sprach zu ihm: \"Siehst du die so gewaltigen Bauten? Hier wird kein Stein auf dem anderen bleiben, der nicht niedergerissen werden wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Dann ließ er sich dem Tempel gegenüber auf dem Ölberg nieder; da fragten ihn Petrus, Jakobus, Johannes und Andreas im geheimen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '\"Sag uns: Wann wird das geschehen, und welches wird das Zeichen sein, wann all das sich zu vollenden beginnt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Da fing Jesus an, ihnen zu erklären: \"Seht zu, daß euch niemand irreführe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Viele werden unter meinem Namen kommen und behaupten: \'Ich bin es.\' Und sie werden viele irreführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Wenn ihr von Kriegen und von Kriegsgerüchten hört, so laßt euch nicht erschrecken. Denn das muß geschehen, doch es ist noch nicht das Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Denn Volk wird sich gegen Volk erheben und Reich gegen Reich; an vielen Orten wird es Erdbeben geben, und Hungersnöte werden sein; doch dies ist erst der Anfang der Wehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Doch. seht euch für euch selber vor. Man wird euch den Gerichten übergeben und euch in Synagogen geißeln; vor Statthalter und Könige wird man euch um meinetwillen stellen, ihnen zum Zeugnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Doch zuvor muß bei allen Völkern das Evangelium verkündet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Wenn ihr dann den Gerichten ausgeliefert werdet, so macht euch vorher keine Sorge, was ihr reden sollt, vielmehr was euch in jener Stunde eingegeben wird, das saget. Denn alsdann seid nicht ihr es, die da reden; es ist vielmehr der Heilige Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Der Bruder wird den eigenen Bruder zum Tode überliefern, der Vater das eigene Kind; Kinder werden gegen ihre Eltern auftreten und sie in den Tod bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Von allen werdet ihr um meines Namens willen gehaßt werden, doch wer ausharrt bis ans Ende, wird gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Wenn ihr jedoch den Greuel der Verwüstung dort herrschen seht, wo es nicht sein soll - der Leser möge dies wohl beachten -, dann fliehe ins Gebirge, wer in Judäa ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Wer auf dem Dache ist, der steige nicht in sein Haus hinab; auch gehe er nicht hinein, um irgend etwas aus seinem Hause zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Wer auf dem Felde ist, der wende sich nicht um, sein Oberkleid zu holen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Doch wehe den Frauen, die in jenen Tagen ein Kindlein unterm Herzen oder an der Brust tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Betet, daß dies nicht zur Winterszeit geschehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Jene Tage werden nämlich eine Trübsal bedeuten, wie sie noch nie gewesen, seitdem Gott im Anfang die Schöpfung schuf bis jetzt, noch auch jemals sein wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Und hätte der Herr die Tage nicht abgekürzt, so würde niemand gerettet werden. Doch um der Auserwählten willen, die er sich auserwählte, hat er die Tage abgekürzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Wenn dann jemand zu euch sagt: \'Siehe, hier ist Christus.\' \'Siehe, dort.\' Glaubt es nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Denn falsche Christusse und falsche Propheten werden sich erheben: Sie werden Zeichen und Wunder tun, so daß, wenn es möglich wäre, sogar die Auserwählten verführt würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'So seht euch vor! Seht, ich sage euch alles vorher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Sogleich nach der Trübsal jener Tage wird sich die Sonne verfinstern; der Mond wird seinen Schein nicht geben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'die Sterne werden vom Himmel fallen, die Kräfte des Himmels erschüttert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Dann wird man den Menschensohn auf Wolken kommen sehen mit großer Macht und Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Dann wird er seine Engel aussenden und seine Auserwählten sammeln von den vier Richtungen des Windes, von der Erde tiefstem Ende bis zum höchsten Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Vom Feigenbaum aber lernt es im Gleichnis: Wenn seine Zweige einmal saftig werden und er schon Blätter treibt, dann wisset ihr: Der Sommer ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'So sollt auch ihr, wenn ihr dies geschehen seht, erkennen, daß es schon vor der Türe steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis all dies geschehen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Himmel und Erde werden vergehen, doch meine Worte werden nicht vergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Von jenem Tag aber und der Stunde weiß niemand etwas, nicht die Engel des Himmels, auch nicht der Sohn, sondern nur der Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'So seid denn auf der Hut; seid wachsam betet! Ihr wißt ja nicht, wann der Zeitpunkt da ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Es wird euch ergehen wie einem Manne, der in die Fremde ziehen wollte: Er verließ sein Haus, gab seinen Knechten alle Vollmacht, wies einem jeden seine Arbeit zu; dem Torhüter trug er auf, wachsam zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'So seid denn wachsam; ihr wißt nicht, wann der Herr des Hauses kommt, ob spät am Abend oder erst um Mitternacht, ob beim Hahnenschrei oder am frühen Morgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Er könnte unerwartet kommen und euch schlafend finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Was ich euch sage, gilt allen: Wachet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Ostern, das Fest der ungesäuerten Brote, war in zwei Tagen. Die Oberpriester und die Schriftgelehrten suchten nach einer passenden Gelegenheit, wie sie ihn mit List ergreifen und dann töten könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Doch sagten sie: \"Nur nicht am Fest, es könnte sonst das Volk in Aufruhr kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Als Jesus in Bethanien weilte, im Hause Simons des Aussätzigen, da trat, solange er zu Tische lag, ein Weib herein; sie trug ein Gefäß aus Alabaster voll echten, feinsten Nardenöls. Sie zerbrach das Alabastergefäß und goß das Öl über seinem Haupte aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Darüber waren einige untereinander sehr erbost: \"Wozu die Verschwendung mit dem Salböl?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Man hätte die Salbe um mehr als dreihundert Denare verkaufen und den Erlös den Armen geben können.\" So ließen sie das Weib hart an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Doch Jesus sprach: \"Laßt sie! Was kränkt ihr sie? Sie hat ein gutes Werk an mir getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Die Armen habt ihr allzeit bei euch und könnt ihnen Gutes tun, wann ihr wollt, mich aber habt ihr nicht allzeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Sie hat getan, was sie konnte; sie salbte meinen Leib zum voraus für das Begräbnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Wahrlich, ich sage euch: Wo immer in der ganzen Welt dieses Evangelium verkündet wird, da wird man auch erzählen, was sie getan hat, ihr zum Gedächtnis.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Alsdann ging einer von den Zwölfen, Judas Iskariot, zu den Oberpriestern, um ihn diesen zu verraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Wie sie dies hörten, freuten sie sich sehr, und sie versprachen, ihm Geld zu geben. Er ging nun darauf aus, ihn zu gelegener Zeit auszuliefern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Am ersten Tag der Ungesäuerten Brote, an dem man das Osterlamm zu schlachten pflegte, fragten ihn seine Jünger: \"Wo willst du, daß wir dir das Ostermahl bereiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Da sandte er zwei aus seinen Jüngern ab und sprach zu ihnen: \"Geht in die Stadt! Dort wird euch ein Mann mit einem Wasserkrug begegnen; dem folgt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Wo der hingeht, da sagt zu dem Herrn des Hauses: \'Der Meister spricht: Wo ist mein Gemach, in dem ich mit meinen Jüngern das Ostermahl halten kann?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Er wird euch ein oberes Gemach anweisen, geräumig, mit Teppichen belegt und hergerichtet; dort bereitet es für uns!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Die Jünger gingen weg und kamen in die Stadt; sie fanden es so, wie er es ihnen gesagt hatte, und sie bereiteten das Ostermahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'So ward es Abend. Da kam er mit den Zwölfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Während sie bei Tische waren und aßen, sprach Jesus: \"Wahrlich, ich sage euch: Einer aus euch wird mich verraten, einer, der mit mir ißt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Da fragte ihn einer nach dem anderen tief betrübt: \"Doch nicht ich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Er sprach zu ihnen: \"Einer aus den Zwölfen, der mit mir aus einer Schüssel ißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Zwar geht der Menschensohn dahin, wie es von ihm geschrieben steht; doch wehe jenem Menschen, durch den der Menschensohn verraten wird. Besser wäre es für ihn, wenn dieser Mensch nicht geboren wäre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Während sie beim Mahle waren, nahm Jesus Brot, segnete, brach es und gab es ihnen mit den Worten: \"Nehmt hin, das ist mein Leib.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Darauf nahm er den Kelch, dankte und gab ihnen diesen, und sie tranken daraus alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Er sprach zu ihnen: \"Das ist mein Bundesblut, das für viele vergossen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Wahrlich, ich sage euch: Ich werde nicht mehr vom Gewächs des Weinstocks trinken bis zu jenem Tage, da ich es im Gottesreiche erneuert trinken werde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Sie beteten den Lobgesang und gingen hierauf zum Ölberg hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Und Jesus sprach zu ihnen: \"Ihr alle werdet heute nacht an mir irre werden; denn also steht geschrieben: \'Ich will den Hirten schlagen; dann werden die Schafe zerstreut werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Nach meiner Auferstehung aber will ich euch nach Galiläa vorausgehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Darauf gab ihm Petrus zur Antwort: \"Und mögen alle an dir irre werden, ich nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Doch Jesus sprach zu ihm: \"Wahrlich, ich sage dir: Heute noch, in dieser Nacht, noch vor dem zweiten Hahnenschrei, wirst du mich dreimal verleugnet haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Allein nur um so eifriger sprach er: \"Und wenn ich mit dir sterben müßte, ich werde dich nicht verleugnen.\" In gleicher Weise sprachen alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Sie kamen zu einem Landgut, Gethsemani geheißen. Er sprach zu seinen Jüngern: \"Wartet hier, indes ich bete.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Nur Petrus, Jakobus und Johannes nahm er mit sich. Da fing er an, zu zittern und zu zagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Er sprach zu ihnen: \"Meine Seele ist bis zum Tod betrübt; bleibet hier und wachet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Er ging ein wenig vorwärts, fiel auf die Erde nieder und betete, daß, wenn es möglich sei, die Stunde an ihm vorübergehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Er sprach: \"Abba, Vater, dir ist alles möglich; laß diesen Kelch an mir vorübergehen. Doch nicht, wie ich will, sondern wie du willst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Dann ging er wieder hin und fand sie schlafend. Er sprach zu Petrus: \"Simon, du schläfst? Nicht eine einzige Stunde hast du wachen können?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Wachet und betet, damit ihr nicht in Versuchung fallet. Der Geist ist willig; doch das Fleisch ist schwach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Dann ging er wieder hin und betete mit denselben Worten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Er kam zurück und fand sie wieder schlafend; denn ihre Augen waren schwer geworden; sie wußten nicht, was sie zu ihm sagen sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Als er zum drittenmal kam, sprach er zu ihnen: \"Noch schlafet ihr und ruhet. Nun ist es soweit. Die Stunde ist gekommen, da der Menschensohn in die Hände der Sünder überliefert wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Steht auf und laßt uns gehen. Seht, mein Verräter naht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Noch sprach er so, da kam schon Judas, einer aus den Zwölfen, mit ihm ein Haufen mit Schwertern und mit Prügeln im Auftrag der Oberpriester, der Schriftgelehrten und der Ältesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Sein Verräter hatte mit ihnen ein Zeichen verabredet: \"Der, den ich küssen werde, ist es. Den packt und führt ihn vorsichtig weg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Er ging sofort auf Jesus zu und sagte zu ihm: \"Sei gegrüßt, Rabbi!\" und küßte ihn gar innig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Sie aber legten Hand an Jesus und ergriffen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Doch einer von denen, die in der Nähe standen, zog sein Schwert und schlug den Knecht des Hohenpriesters und hieb ihm ein Ohr ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Und Jesus sprach zu ihnen: \"Wie gegen einen Räuber seid ihr ausgezogen, mit Schwertern und Prügeln, um mich zu ergreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Tag für Tag war ich bei euch im Tempel, wo ich lehrte, und ihr habt mich nicht ergriffen. Jedoch es sollen sich die Schriften erfüllen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Jetzt ließen ihn alle seine Jünger im Stich und flohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Ein Jüngling, der ein Linnentuch auf bloßem Leibe trug, folgte ihm. Da packte man ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Er aber ließ das Linnentuch fahren und floh vor ihnen nackt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Sie führten Jesus zum Hohenpriester, bei dem sich alle versammelten, die Oberpriester und die Ältesten und Schriftgelehrten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Petrus folgte ihm von ferne bis in den Hof des Hohenpriesters hinein. Dort setzte er sich bei den Dienern nieder und wärmte sich am Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Die Oberpriester, das heißt der ganze Hohe Rat, suchten nach einem Zeugnis gegen Jesus, um ihn in den Tod zu bringen. Sie fanden aber keines,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'obwohl gar viele falsches Zeugnis über ihn abgaben; ihr Zeugnis stimmte nicht zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Dann traten einige noch auf und sagten als falsche Zeugen gegen ihn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '\"Wir haben diesen sagen hören: \'Ich reiße diesen Tempel hier, der mit Händen erbaut wurde, nieder und baue innerhalb drei Tagen einen anderen auf, der nicht mit Händen erbaut wird.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Doch auch so stimmte, was sie sagten, nicht zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Da trat der Hohepriester mitten hin und fragte Jesus: \"Weißt du denn gar nichts zu erwidern? Was bezeugen doch diese gegen dich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Er aber schwieg und gab ihm keine Antwort. Und wieder fragte ihn der Hohepriester: \"Bist du der Christus, der Sohn Gottes des Hochgelobten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Und da sprach Jesus: \"Ich bin es. Ihr werdet den Menschensohn zur Rechten des Allmächtigen Gottes sitzen und auf den Wolken des Himmels kommen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Da zerriß der Hohepriester seine Kleider und rief: \"Was brauchen wir noch Zeugen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Ihr habt die Lästerung gehört. Was dünkt euch?\" Und alle sprachen ihn des Todes schuldig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Alsdann begannen einige, ihn anzuspeien, sein Antlitz zu verhüllen, ihm Stockschläge zu geben und ihm zuzurufen: \"Weissage!\" Und auch die Diener fielen über ihn her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Indes befand sich Petrus im Hofe draußen. Da kam eine von den Mägden des Hohenpriesters;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'sie sah den Petrus, der sich wärmte, schaute ihm ins Gesicht und sprach: \"Auch du warst bei Jesus, dem Nazarener.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Er aber leugnete und sagte: \"Ich weiß nicht und verstehe nicht, was du redest.\" Er ging alsdann zur Vorhalle hinaus, und schon krähte der Hahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Wie ihn die Magd da sah, fing sie noch einmal an und sprach zu denen, die dort standen. \"Auch der gehört zu ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Er leugnete es abermals. Nach einer kleinen Weile sagten die Umstehenden nochmals zu Petrus: \"Sicherlich gehörst du auch zu ihnen; du bist ja auch ein Galiläer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Da fing er an zu fluchen und zu schwören: \"Ich kenne diesen Menschen nicht, von dem ihr redet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Da krähte gleich darauf der Hahn ein zweitesmal. Und nun erinnerte sich Petrus des Wortes Jesu, als er zu ihm sprach: \"Noch vor dem zweiten Hahnenschrei wirst du mich dreimal verleugnet haben.\" Und er brach in Tränen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Die Hohenpriester, Ältesten und Schriftgelehrten, das heißt der ganze Hohe Rat, hielten sofort am Morgen eine Sitzung. Sie führten Jesus gefesselt ab und übergaben ihn dem Pilatus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilatus fragte ihn: \"Bist du der Judenkönig?\" Und Jesus sprach zu ihm: \"Das sagst nur du!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Die Oberpriester wußten ihn in vielem anzuklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Da fragte ihn Pilatus abermals: \"Weißt du denn gar nichts zu erwidern? Sieh, was diese alles gegen dich vorbringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Doch Jesus gab überhaupt keine Antwort mehr, so daß Pilatus sich verwunderte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Nun pflegte er ihnen auf den Festtag einen Gefangenen loszugeben, den sie sich selbst ausbitten durften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Da lag nun einer im Gefängnis, er hieß Barabbas, und mit ihm andere Aufrührer, die beim Aufruhr einen Mord begangen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Das Volk zog hinauf und fing an unter lautem Schreien zu fordern, das ihnen zu gewähren, was er immer noch getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilatus fragte sie: \"Wollt ihr, daß ich euch den Judenkönig freilasse?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Er wußte nämlich wohl, daß ihn die Oberpriester aus Neid überliefert hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Die Oberpriester hetzten die Menge auf, er möge ihnen eher den Barabbas freilassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Da fragte sie Pilatus noch einmal: \"Was soll ich aber dann mit diesem anfangen, den ihr den Judenkönig heißt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Sie schrien wiederum: \"Ans Kreuz mit ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Jedoch Pilatus sprach zu ihnen: \"Was hat er denn Böses getan?\" Da schrien sie noch lauter: \"Ans Kreuz mit ihm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilatus aber wollte sich dem Volk gefällig zeigen, so gab er ihnen den Barabbas frei, Jesus aber überließ er ihnen, daß er gegeißelt und gekreuzigt würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Die Soldaten führten ihn in den Hof hinein, das heißt in das Gerichtsgebäude, und versammelten um ihn die ganze Abteilung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Sie behängten ihn mit einem scharlachroten Mantel, flochten eine Dornenkrone und setzten sie ihm auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Alsdann begannen sie, ihn zu begrüßen: \"Heil dir, du Judenkönig!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Sie schlugen ihn mit dem Rohr auf das Haupt, spieen ihn an und beugten huldigend vor ihm die Knie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Nachdem sie ihren Spott mit ihm getrieben hatten, nahmen sie ihm den Mantel ab und zogen ihm die eigenen Kleider wieder an. Dann führten sie ihn ab zur Kreuzigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Sie zwangen einen, der vorüberging, den Simon von Cyrene, der von seinem Landgut kam, den Vater des Alexander und Rufus, ihm das Kreuz nachzutragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Sie führten ihn nach dem Orte Golgotha, das heißt Schädelstätte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'und gaben ihm Wein, vermischt mit Myrrhe. Er nahm ihn aber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Dann kreuzigten sie ihn und verteilten seine Kleider unter sich, indem sie das Los darüber warfen, was ein jeder haben sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Es war die dritte Stunde, als sie ihn kreuzigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Auch eine Inschrift, die seine Schuld angab, war angeschrieben: \"Der Judenkönig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Zugleich mit ihm kreuzigte man auch zwei Räuber, den einen zu seiner Rechten, den anderen zur Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'So ward die Schrift erfüllt: \"Er wird den Missetätern beigezählt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Die Vorübergehenden überhäuften ihn mit Lästerworten; sie schüttelten den Kopf und sprachen: \"He du, der du den Tempel hast zerstören und ihn in drei Tagen wieder aufbauen wollen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'rette dich selbst und steige herab vom Kreuz.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Ähnlich höhnten auch die Oberpriester; sie und die Schriftgelehrten sagten zueinander: \"Andere hat er gerettet; sich selbst kann er nicht retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Christus, der König Israels, steige jetzt herab vom Kreuz, auf daß wir es sehen und glauben.\" Selbst die mit ihm gekreuzigt waren, schmähten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Von der sechsten Stunde an lag auf dem ganzen Land eine Finsternis und dauerte bis zur neunten Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Und um die neunte Stunde rief Jesus mit lauter Stimme aus: \"Eloi, eloi, lama sabachthani!\", das heißt: \"Mein Gott, mein Gott, warum hast du mich verlassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Und einige von denen, die dort standen, vernahmen dies und sagten: \"Seht, er ruft Elias.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Da lief sogleich einer aus ihnen hin und füllte einen Schwamm mit Essig, steckte ihn auf ein Rohr und gab ihm zu trinken mit den Worten: \"Laßt mich, wir wollen sehen, ob Elias wirklich kommt und ihn herabnimmt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Doch Jesus stieß noch einen lauten Schrei aus und verschied.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Und der Vorhang im Tempel riß entzwei, von oben bis unten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Als der Hauptmann, der ihm gegenüberstand, gewahrte, daß er so verschieden sei, rief er aus: \"Wahrlich, dieser Mensch war Gottes Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Auch Frauen waren dort; die schauten aus der Ferne zu. Unter ihnen waren Maria Magdalena, Maria, die Mutter des jüngeren Jakobus und des Joses, und Salome.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Sie waren ihm schon in Galiläa gefolgt und hatten ihm gedient. Noch viele andere waren da, die mit ihm nach Jerusalem hinaufgegangen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Als es Abend war - es war ja Rüsttag, das ist der Tag vor dem Sabbat-,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'kam Joseph von Arimathäa, ein angesehener Ratsherr, der selber auch das Reich Gottes erwartete. Mutig ging er zu Pilatus und bat ihn um den Leichnam Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus war erstaunt, daß er schon tot sein sollte, er ließ den Hauptmann kommen und fragte ihn, ob er schon tot sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Als er es vom Hauptmann erfahren hatte, schenkte er den Leichnam dem Joseph.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Und dieser kaufte Leinwand, nahm ihn ab und wickelte ihn in die Leinwand. Darauf legte er ihn in ein Grab, das aus einem Felsen ausgehauen war, und wälzte vor den Eingang des Grabes einen Stein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Maria Magdalena und Maria, die Mutter des Joses, sahen zu, wohin er gelegt wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Als der Sabbat vorüber war, kauften Maria Magdalena, Maria, die Mutter des Jakobus, und Salome Spezereien, um hinauszugehen und ihn zu salben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Ganz früh am Morgen des ersten Wochentages, wie die Sonne eben aufgegangen war, kamen sie zum Grabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Sie sagten zueinander: \"Wer mag uns wohl den Stein vom Eingange des Grabes wegwälzen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Als sie hinblickten, sahen sie, daß der Stein weggewälzt war; er war wirklich sehr groß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Sie gingen in das Grab hinein und sahen zur Rechten einen Jüngling sitzen, angetan mit einem weißen Gewande. Und sie entsetzten sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Er aber sprach zu ihnen: \"Entsetzt euch nicht! Ihr sucht Jesus von Nazareth, den Gekreuzigten, er ist auferstanden, er ist nicht mehr hier. Seht den Platz, wohin man ihn gelegt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Doch geht schnell hinweg und sagt seinen Jüngern und dem Petrus, daß er euch nach Galiläa vorangeht. Dort werdet ihr ihn sehen, so wie er es euch gesagt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Sie gingen rasch hinaus und eilten schnell vom Grab hinweg; denn Zittern und Entsetzen hatte sie erfaßt. Sie sagten niemand etwas; denn sie hatten Angst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'So war er in der Frühe des ersten Wochentages auferstanden und erschien zuerst der Maria Magdalena, aus der er sieben Dämonen ausgetrieben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Und diese ging hin und verkündete es denen, die bei ihm gewesen waren und jetzt trauerten und weinten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Als sie hörten, daß er lebe und ihr erschienen sei, da wollten sie es nicht glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Später erschien er noch zwei anderen aus ihnen unterwegs in einer andersartigen Gestalt, als sie über Land gingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Auch jene gingen hin und erzählten es den übrigen; jedoch auch ihnen wollten sie nicht glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Zuletzt erschien er den Elfen selbst, als sie zu Tische saßen. Er rügte ihren Unglauben und ihre Herzenshärte, weil sie denen nicht geglaubt hatten, die ihn als einen von den Toten Auferstandenen gesehen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Hierauf sprach er zu ihnen: \"Gehet hin in alle Welt und verkündet die frohe Botschaft der ganzen Schöpfung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Wer glaubt und sich taufen läßt, wird gerettet werden, wer aber nicht glaubt, wird verdammt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Und diese Zeichen werden die Glaubenden begleiten: In meinem Namen werden sie Dämonen austreiben; sie werden in neuen Sprachen reden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'sie werden Schlangen aufheben, und sollten sie Tödliches trinken, werden sie nicht Schaden leiden; Kranken werden sie die Hände auflegen, und sie werden gesund werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'So sprach der Herr Jesus zu ihnen. Darauf ward er in den Himmel aufgenommen und setzte sich zur Rechten Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Sie aber zogen aus und predigten überall. Der Herr wirkte mit ihnen, und er gab ihrer Rede Kraft durch die nachfolgenden Wunderzeichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Viele haben es schon unternommen, zusammenhängend zu erzählen, was für Begebenheiten sich unter uns zugetragen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Sie haben sich dabei an die Überlieferungen derer gehalten, die von Anfang an Augenzeugen und Diener des Wortes waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'So habe auch ich mich entschlossen, allen Ereignissen von ihren ersten Anfängen an sorgfältig nachzugehen und sie für dich, edler Theophilus, der Reihe nach aufzuschreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Auf diese Weise kannst du dich von der Zuverlässigkeit der Lehren überzeugen, in denen du unterrichtet worden bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'In den Tagen des Herodes, des Königs von Judäa, lebte ein Priester namens Zacharias, aus der Priesterklasse des Abia. Er hatte eine Frau aus dem Geschlechte Aarons; ihr Name war Elisabeth.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Beide waren fromm vor Gott und lebten tadellos in allen Geboten und Satzungen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Doch hatten sie kein Kind; Elisabeth war nämlich unfruchtbar, und beide waren auch schon hochbetagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Einst versah er seinen Dienst vor Gott, weil seine Priesterklasse an der Reihe war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Weil es in der Priesterschaft Gewohnheit war, ward gelost, und er hatte das Rauchopfer darzubringen. So trat er in den Tempel des Herrn ein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'die ganze Volksmenge betete jedoch zur Zeit des Rauchopfers draußen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Da erschien ihm rechts vom Rauchopferaltar ein Engel des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Zacharias erschrak, als er ihn sah, und es befiel ihn Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Der Engel aber sprach zu ihm: \"Fürchte dich nicht, Zacharias! Dein Gebet ist erhört; Elisabeth, dein Weib, wird dir einen Sohn schenken, und du sollst ihn Johannes nennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Du wirst darüber freudig jubeln, und viele werden über seine Geburt sich freuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Denn er wird groß sein durch die Gnade Gottes. Wein und berauschendes Getränk wird er nicht trinken und schon im Mutterschoß voll des Heiligen Geistes sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Und viele der Kinder Israels wird er zum Herrn, ihrem Gott, bekehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Er wird vor ihm einhergehen im Geist und in der Kraft des Elias, um den Sinn der Väter den Kindern wieder einzuflößen, Unfolgsame zur Gesinnung Frommer hinzuführen und dem Herrn ein williges Volk zu bereiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Doch Zacharias sprach zu dem Engel: \"Woran soll ich das erkennen? Ich bin schon alt, und auch mein Weib ist hochbetagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Darauf gab ihm der Engel zur Antwort: \"Ich bin Gabriel, der vor Gott steht, und bin gesandt, mit dir zu reden und dir diese frohe Botschaft zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Siehe, du sollst stumm sein und nicht reden können, bis auf den Tag, da dies eintrifft, weil du meinen Worten nicht geglaubt hast, die zu ihrer Zeit in Erfüllung gehen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Das Volk, das auf Zacharias wartete, wunderte sich sehr, daß er so lange im Tempel weilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Er trat heraus; doch konnte er nicht zu ihnen reden, und sie erkannten, daß er im Tempel ein Gesicht geschaut hatte. Er konnte ihnen nur noch winken und blieb stumm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Als die Zeit seines Dienstes vorüber war, begab er sich nach Hause zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Hernach empfing Elisabeth, sein Weib, und zog sich auf fünf Monate zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Sie sprach: \"So hat der Herr an mir getan; er hat auf mich in diesen Tagen herabgeschaut und vor den Menschen meine Schmach hinweggenommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Im sechsten Monat ward der Engel Gabriel von Gott in eine Stadt in Galiläa namens Nazareth gesandt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'zu einer Jungfrau, die verlobt war mit einem Manne namens Joseph. Er stammte aus dem Hause David; der Name der Jungfrau war Maria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Er der Engel trat zu ihr hinein und sprach: \"Gegrüßet seist du, Gnadenvolle; der Herr ist mit dir.\" Du bist gebenedeit unter den Weibern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Sie ward verwirrt ob dieser Rede und dachte nach, was dieser Gruß bedeute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Der Engel aber sprach zu ihr: \"Fürchte dich nicht, Maria; denn du hast bei Gott Gnade gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Siehe, du wirst empfangen und einen Sohn gebären, und du sollst ihm den Namen Jesus geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Er wird groß sein und Sohn des Allerhöchsten heißen; Gott, der Herr, wird ihm den Thron seines Vaters David geben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'und er wird herrschen über das Haus Jakob in Ewigkeit, und seines Reiches wird kein Ende sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria sprach zum Engel: \"Wie soll das geschehen, da ich keinen Mann erkenne?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Der Engel aber sprach zu ihr: \"Der Heilige Geist wird auf dich herabkommen, und die Kraft des Allerhöchsten wird dich überschatten. Darum wird auch das Heilige, das geboren wird, Sohn Gottes heißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Siehe, auch deine Base Elisabeth hat in ihrem Alter einen Sohn empfangen, und dies ist schon der sechste Monat bei ihr, die für unfruchtbar gehalten wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Bei Gott ist nichts unmöglich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Da sprach Maria: \"Siehe, ich bin die Magd des Herrn; mir geschehe nach deinem Wort.\" Und der Engel schied von ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'In jenen Tagen machte sich Maria auf und eilte ins Gebirge nach einer Stadt in Juda.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Und sie betrat das Haus des Zacharias und grüßte Elisabeth.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Sobald Elisabeth den Gruß Marias vernahm, frohlockte das Kind in ihrem Schoße. Da ward Elisabeth vom Heiligen Geiste erfüllt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'und rief mit lauter Stimme: \"Du bist gebenedeit unter den Weibern, und gebenedeit ist die Frucht deines Leibes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Womit habe ich verdient, daß die Mutter meines Herrn zu mir kommt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Denn siehe, sobald der Klang deines Grußes mein Ohr berührte, frohlockte jubelnd das Kind in meinem Schoße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Selig, die geglaubt hat, daß das in Erfüllung gehen werde, was ihr vom Herrn gesagt ward.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Da sprach Maria: \"Hoch preist meine Seele den Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'mein Geist frohlockt in Gott, meinem Heiland,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'weil er die Demut seiner Magd geschaut; denn siehe, fortan preisen mich selig alle Geschlechter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Denn Großes hat an mir getan der Mächtige; und heilig ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Und sein Erbarmen waltet von Geschlecht zu Geschlecht für jene, die ihn fürchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Er wirket Mächtiges mit seinem Arm; zerstreut, die stolz in ihrem Herzen denken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Herab stürzt er Gewalthaber von Thronen und erhöht Niedrige;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'mit Gütern sättigt er die Darbenden; doch Reiche läßt er leer ausgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Er hat sich angenommen Israels, seines Knechtes, in der Erinnerung an sein Erbarmen -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'denn so verhieß er\'s unsern Vätern schon - mit Abraham und seinem Stamm auf ewig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Maria blieb etwa drei Monate bei ihr. Dann kehrte sie in ihr Haus zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Es kam nun für Elisabeth die Zeit der Niederkunft, und sie gebar einen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Als ihre Nachbarn und Verwandten hörten, daß ihr der Herr so großes Erbarmen gezeigt hatte, da freuten sie sich mit ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Am achten Tage kamen sie, um das Kind zu beschneiden, und wollten ihm den Namen seines Vaters Zacharias geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Doch seine Mutter sprach: \"Nein, Johannes soll es heißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Man sprach zu ihr: \"In deiner Verwandtschaft ist doch niemand, der diesen Namen trägt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Nun winkten sie dem Vater, wie er es genannt wissen wolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Er verlangte eine Schreibtafel und schrieb die Worte darauf: \"Johannes ist sein Name.\" Da staunten alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Im selben Augenblick ward sein Mund geöffnet, und seine Zunge ward gelöst; er konnte wieder reden und pries Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Da kam Furcht über alle Nachbarn, und im Gebirge von Judäa sprach man überall von allen diesen Dingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Und alle, die sie hörten, erwogen sie in ihrem Herzen; sie sagten: \"Was mag aus diesem Kinde werden?\" Und wirklich war die Hand des Herrn mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Sein Vater Zacharias aber ward vom Heiligen Geist erfüllt und sprach wie ein Prophet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '\"Gepriesen sei der Herr, der Gott Israels; heimgesucht hat er sein Volk und ihm Erlösung bereitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'ein Horn des Heils uns aufgerichtet im Hause Davids, seines Knechtes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'wie er verheißen hat von alters her durch seiner heiligen Propheten Mund;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'von unsern Feinden uns zu retten, aus der Hand all derer, die uns hassen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Barmherzigkeit unsern Vätern zu erweisen und seines heiligen Bundes zu gedenken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'des Eides, den er unserm Vater Abraham geschworen: Er wolle uns verleihen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'daß wir aus unserer Feinde Hand errettet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'ihm furchtlos dienen in Heiligkeit und Gerechtigkeit dank seiner Gnade alle Tage unsres Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Und du, Kind, wirst ein Prophet des Höchsten heißen; denn du wirst vor dem Herrn einhergehen, ihm seine Wege zu bereiten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'um sein Volk zur Erkenntnis zu führen, daß das Heil in der Vergebung seiner Sünden liege');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'dank des herzlichen Erbarmens unsres Gottes, womit uns heimgesucht das Licht aus der Höhe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'um denen aufzuleuchten, die in Finsternis und Todesschatten sitzen, und unsre Schritte auf des Friedens Pfad zu lenken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Der Knabe wuchs und ward stark im Geiste. Er lebte in der Einsamkeit bis zu dem Tage, da er Israel sich zeigen sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'In jenen Tagen erging ein Erlaß des Kaisers Augustus, das ganze Land sei aufzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Dies war die erste Aufzeichnung, die unter dem Statthalter von Syrien, Cyrinus, stattfand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Da gingen alle hin, sich eintragen zu lassen, ein jeglicher in seinen Heimatort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Auch Joseph reiste von Galiläa aus der Stadt Nazareth nach Judäa zur Davidstadt mit Namen Bethlehem, um sich eintragen zu lassen, weil er aus dem Hause und Geschlechte Davids war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Mit ihm ging Maria, sein anverlobtes Weib, das guter Hoffnung war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Während sie dort verweilten, kam für sie die Zeit der Niederkunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Und sie gebar ihren erstgeborenen Sohn; sie wickelte ihn in Windeln und legte ihn in eine Krippe, weil sich in der Herberge sonst kein Platz für sie fand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'In derselben Gegend waren Hirten auf dem freien Felde; sie hielten nachts Wache bei ihrer Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Da stand der Engel des Herrn vor ihnen, und die Herrlichkeit des Herrn umleuchtete sie. Und sie gerieten in übergroße Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Der Engel aber sprach zu ihnen: \"Fürchtet euch nicht: Seht, ich verkünde euch eine große Freude, die allem Volke zuteil werden soll:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Heute ist euch in der Stadt Davids der Heiland geboren; es ist Christus, der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Und dies soll euch zum Zeichen dienen: Ihr werdet ein Kind finden, das in Windeln eingewickelt ist und in einer Krippe liegt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Und sogleich war bei dem Engel eine ganze Schar des himmlischen Heeres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Sie lobten Gott und sprachen: \"Ehre ist Gott in der Höhe und Friede auf der Erde den Menschen seiner Huld.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Die Engel gingen dann von ihnen weg in den Himmel; die Hirten aber sprachen zueinander: \"Laßt uns nach Bethlehem gehen und sehen, was dort geschehen ist, was uns der Herr kundgetan hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Sie gingen eilends hin und fanden Maria und Joseph und das Kind, das in der Krippe lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Als sie es gesehen hatten, erzählten sie, was sie über dieses Kind erfahren hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Und alle, die davon hörten, verwunderten sich über das, was ihnen von den Hirten gesagt worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Maria aber bewahrte alle diese Begebenheiten und überdachte sie in ihrem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Die Hirten kehrten heim und lobten und priesen Gott für alles, was sie vernommen und gesehen hatten, so wie es ihnen gesagt worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Als acht Tage vorüber waren und das Kind beschnitten werden mußte, erhielt es den Namen Jesus, den es vom Engel erhalten hatte, noch ehe es im Mutterschoß empfangen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Als die Tage ihrer Reinigung, entsprechend dem Gesetze des Moses, vorüber waren, brachten sie das Kind nach Jerusalem, um es dem Herrn darzustellen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'wie im Gesetze des Herrn geschrieben steht: \"Jeder erstgeborene Sohn soll dem Herrn geheiligt sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Auch wollten sie das Opfer darbringen, wie es im Gesetze des Herrn geboten ist, ein Paar Turteltauben oder zwei junge Tauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'In Jerusalem lebte ein Mann mit Namen Simeon. Er war ein frommer und gottesfürchtiger Mann, der den Trost Israels erwartete; auch war der Heilige Geist in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Ihm war vom Heiligen Geist geoffenbart worden, daß er den Tod nicht schauen werde, bevor er nicht den Gesalbten des Herrn gesehen habe. So kam er auf den Antrieb des Geistes in den Tempel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Als eben die Eltern das Kind Jesus hereintrugen, um die Gesetzesvorschrift an ihm zu erfüllen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'nahm er es auf seine Arme, pries Gott und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '\"Nunmehr entlässest du Deinen Knecht, o Herr, nach Deinem Wort in Frieden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'mit eigenen Augen habe ich Dein Heil geschaut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'das du bereitet hast vor allen Völkern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Ein Licht zur Offenbarung für die Heiden und eine Ehre für Dein Volk Israel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Sein Vater und seine Mutter staunten über das, was über ihn gesprochen wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Und Simeon segnete sie und sagte zu Maria, seiner Mutter: \"Siehe, dieser ist bestimmt zum Falle und zur Auferstehung vieler in Israel und zu einem Zeichen, dem man widersprechen wird -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'auch deine Seele wird das Schwert durchdringen -, damit die Gedanken vieler Herzen offenkundig werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Da war auch Anna, eine Prophetin, eine Tochter Phanuels, aus dem Stamme Aser. Sie war schon hochbetagt; sie hatte nach ihrer Mädchenzeit sieben Jahre mit ihrem Manne gelebt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'und war nun eine Witwe von vierundachtzig Jahren. Sie lebte dauernd im Tempel und diente Gott mit Fasten und Beten Tag und Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Auch diese fand sich zur selben Stunde ein, pries Gott und redete von ihm zu allen, die auf die Erlösung Jerusalems warteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Nachdem sie alles nach dem Gesetze des Herrn erfüllt hatten, begaben sie sich nach Galiläa in ihre Stadt Nazareth zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Das Kind wuchs heran, es erstarkte, ward voll Weisheit; die Liebe Gottes ruhte auf ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Seine Eltern pilgerten jährlich nach Jerusalem zum Osterfest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Auch als er zwölf Jahre alt war, reisten sie der Festsitte gemäß hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Am Schluß der Festtage machten sie sich wieder auf den Weg; der Jesusknabe aber blieb in Jerusalem zurück, und seine Eltern wußten nichts davon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Sie glaubten, er sei bei der Karawane, und gingen eine Tagereise weit; dann suchten sie ihn bei den Verwandten und Bekannten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Als sie ihn aber dort nicht fanden, kehrten sie nach Jerusalem zurück und suchten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Erst nach drei Tagen fanden sie ihn im Tempel; er saß mitten unter den Lehrern und hörte ihnen zu und stellte ihnen Fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Und alle, die ihn hörten, waren außer sich über sein Verständnis und über seine Antworten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Als sie ihn nun sahen, wunderten sie sich. Und seine Mutter sprach zu ihm: \"Kind, warum hast du uns das getan? Siehe, dein Vater und ich haben dich mit Schmerzen gesucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Er sprach zu ihnen: \"Warum habt ihr mich gesucht? Wußtet ihr nicht, daß ich im Hause meines Vaters sein muß?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Doch sie verstanden nicht, was er mit diesem Worte ihnen sagen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Alsdann zog er mit ihnen nach Nazareth hinab und war ihnen untertan. Seine Mutter aber bewahrte alle diese Begebenheiten in ihrem Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Und Jesus nahm zu an Weisheit, Alter und Wohlgefallen bei Gott und den Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Im fünfzehnten Jahre der Regierung des Kaisers Tiberius, als Pontius Pilatus Statthalter Judäas war, Herodes Vierfürst von Galiläa, sein Bruder Philippus Vierfürst von Ituräa und der Landschaft Trachonitis, Lysanias Vierfürst von Abilene;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'als Annas und Kaiphas Hohepriester waren, erging das Wort des Herrn an Johannes, den Sohn des Zacharias, in der Steppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Er durchzog die ganze Jordansau und predigte die Taufe der Bekehrung zur Nachlassung der Sünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'wie geschrieben steht im Buche der Reden des Propheten Isaias: \"Eine Stimme ruft in der Steppe: Richtet her den Weg des Herrn; machet seine Pfade eben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Jedes Tal soll ausgefüllt, jeder Berg und Hügel abgetragen werden; was krumm ist, soll gerade, was nicht eben, soll zu ebenem Wege werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'und alles Fleisch wird das Heil Gottes schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Zu den Scharen, die hinausgezogen waren, um von ihm die Taufe zu empfangen, sagte er: \"Ihr Schlangenbrut, wer hat euch eingeredet, ihr würdet dem drohenden Unheil entrinnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Bringt Früchte würdig der Bekehrung. Denkt nicht: \'Wir haben Abraham zum Vater.\' Ich sage euch: Gott kann aus diesen Steinen da Kinder für Abraham erstehen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Schon liegt die Axt an der Wurzel der Bäume. Ein jeder Baum, der keine gute Frucht trägt, wird umgehauen und ins Feuer geworfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Die Scharen fragten ihn: \"Was sollen wir tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Er sprach zu ihnen: \"Wer zwei Röcke hat, gebe dem einen, der keinen hat, und wer Speise hat, mache es geradeso.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Auch Zöllner kamen, um die Taufe zu empfangen; sie fragten ihn: \"Meister, was sollen wir tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Er sprach zu ihnen: \"Treibt nicht mehr ein, als was euch vorgeschrieben ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Auch Soldaten fragten ihn: \"Was sollen wir tun?\" Er antwortete ihnen: \"Verübet gegen niemand Gewalt und Unbill und seid mit eurem Solde zufrieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Das Volk war voll Erwartung, und alle dachten bei sich hin und her, ob Johannes nicht der Messias sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Indes Johannes sprach zu allen: \"Ich taufe euch bloß mit Wasser; doch es kommt einer, der mächtiger ist als ich. Ich bin nicht wert, ihm seine Schuhriemen aufzubinden. Er wird euch mit dem Heiligen Geist und mit Feuer taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Er hat schon seine Schaufel in der Hand und wird seine Tenne reinigen; den Weizen wird er in seinen Speicher verbringen, die Spreu wird er in einem unauslöschlichen Feuer verbrennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Noch viele andere Mahnungen trug er dem Volke als frohe Botschaft vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Allein Herodes, der Vierfürst, den er zurechtgewiesen hatte wegen der Herodias, des Weibes seines Bruders, und wegen all der Schandtaten, die er verübt hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'ließ noch zu all dem Johannes ins Gefängnis werfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Als alles Volk sich taufen ließ und Jesus nach der Taufe betete, da tat sich der Himmel auf;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'der Heilige Geist stieg auf ihn in leiblicher Gestalt wie eine Taube nieder. Und eine Stimme kam vom Himmel her: \"Du bist mein geliebter Sohn; an dir habe ich mein Wohlgefallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Als Jesus auftrat, war er etwa dreißig Jahre alt; er war, so glaubte man, ein Sohn des Joseph. Und seine Ahnen waren:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Heli, Matthat, Levi, Melchi, Janes, Joseph,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Matthathias, Amos, Nahum, Hesli, Nagge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Mahath, Mattathias, Semei, Josech, Joda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Joanna, Resa, Zorobabel, Salathiel, Neri,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Melchi, Addi, Kosan, Elmadam, Her,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Jesus, Eliezer, Jorim, Matthat, Levi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Melea, Menna, Mattatha, Nathan, David,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Jesse, Obed, Booz, Sala, Naasson,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Aminadab, Admin, Arni, Esron, Phares, Juda,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Jakob, Isaak, Abraham, Thare, Nachor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Sarug, Ragau, Phaleg, Heber, Sale,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Kainan, Arphaxad, Sem, Noe, Lamech,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Mathusala, Henoch, Jared, Malaleel, Kainan,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Henos, Seth, Adam, und dieser stammt von Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Voll des Heiligen Geistes, begab sich Jesus vom Jordan hinweg und ward vom Geiste auf vierzig Tage in die Einsamkeit geführt und vom Teufel versucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Er aß nichts in jenen Tagen. Als sie vorüber waren, empfand er Hunger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Da sprach der Teufel zu ihm: \"Bist du der Sohn Gottes, so sprich zu diesem Stein, er solle sich in Brot verwandeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Doch Jesus sprach zu ihm: \"Es steht geschrieben: \'Der Mensch lebt nicht allein vom Brote\'\" sondern von jedem Worte Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Dann führte er ihn in die Höhe und zeigte ihm in einem Augenblick alle Reiche der Welt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'und der Teufel sprach zu ihm: \"Diese ganze Macht und ihre Herrlichkeit will ich dir geben, mir gehört sie ja, ich kann sie geben, wem ich will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Willst du mich anbeten, dann soll sie ganz dir gehören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jesus sprach zu ihm: \"Es steht geschrieben: \'Du sollst den Herrn, deinen Gott, anbeten und ihm allein dienen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Jetzt führte er ihn nach Jerusalem und stellte ihn auf die Zinne des Tempels und sprach zu ihm: \"Bist du der Sohn Gottes, so stürze dich von hier hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Denn also steht geschrieben: \'Seinen Engeln hat er deinethalben befohlen, dich zu hüten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'sie sollen dich auf Händen tragen, damit du nicht den Fuß an einen Stein anstoßest.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Doch Jesus sprach zu ihm: \"Es heißt aber auch: \'Du sollst den Herrn, deinen Gott, nicht versuchen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Als der Teufel mit all seiner Versuchungskunst zu Ende war, ließ er eine Zeitlang von ihm ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Dann kehrte Jesus in der Kraft des Geistes wiederum nach Galiläa heim. Sein Ruf verbreitete sich in der ganzen Gegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Er lehrte in den dortigen Synagogen und ward von allen hochgeehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'So kam er auch nach Nazareth, wo er aufgewachsen war. Und wie gewöhnlich ging er am Sabbat in die Synagoge und meldete sich zum Lesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Man reichte ihm das Buch des Propheten Isaias. Er machte die Rolle auf und traf auf die Stelle, wo es heißt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '\"Der Geist des Herrn ist über mir; er salbte mich dazu, den Armen frohe Botschaft kundzutun; er sandte mich, zu heilen, die zerknirschten Herzens sind Gefangenen Erlösung, Blinden das Augenlicht zu verkünden, Niedergebrochene in die Freiheit zu entlassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'das Gnadenjahr des Herrn zu künden\" und den Tag der Vergeltung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Dann rollte er das Buch zusammen, gab es dem Diener und setzte sich. Aller Augen in der Synagoge waren gespannt auf ihn gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Und er begann, zu ihnen also zu sprechen: \"Heute ist die Stelle, die ihr soeben gehört habt, erfüllt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Alle gaben ihm lauten Beifall und wunderten sich über die gnadenvollen Worte, die aus seinem Munde flossen. Sie sagten: \"Ist das nicht der Sohn des Joseph?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Er sprach zu ihnen: \"Ihr werdet mir wohl das Sprichwort entgegenhalten: \'Arzt, heile dich selbst!\' Verrichte auch hier in deiner Vaterstadt die großen Taten, die, wie wir hören, in Kapharnaum geschehen sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Und er fuhr fort: \"Wahrlich, ich sage euch: Kein Prophet gilt etwas in seiner Heimat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Und zum Beweise sage ich euch: In Israel gab es viele Witwen in den Tagen des Elias, da einst der Himmel drei Jahre und sechs Monate verschlossen war und im ganzen Lande eine große Hungersnot entstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Jedoch zu keiner unter ihnen ward Elias gesandt, sondern zu einer Witwe nach Sarepta im Gebiet von Sidon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Und viele Aussätzige gab es in Israel zur Zeit des Propheten Elisäus; jedoch keiner aus ihnen wurde rein, als Naaman, der Syrer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Als sie dies hörten, gerieten alle in der Synagoge in große Wut;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'sie sprangen auf und stießen ihn zur Stadt hinaus und drängten ihn bis an den Rand des Berges, auf dem ihre Stadt erbaut war, um ihn hinabzustürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Doch er schritt mitten hin durch ihre Reihen und zog weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Dann ging er nach Kapharnaum hinab, einer Stadt in Galiläa. Dort lehrte er die Leute an den Sabbaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Man war von seiner Lehre hingerissen; denn mit Vollmacht erging sein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Da war in der Synagoge ein Mensch, der von dem Geist eines unreinen Dämons besessen war. Laut schrie er auf:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '\"Oho, was willst du von uns, Jesus von Nazareth? Bist du gekommen, um uns zu verderben? Ich kenne dich, wer du bist, du Heiliger Gottes!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Doch Jesus drohte ihm und sprach: \"Schweig; fahre aus von ihm.\" Alsdann warf ihn der Dämon mitten hin, und ohne ihm zu schaden, fuhr er von ihm aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Über alle kam ein Staunen, und sie sprachen zueinander: \"Was ist doch das für eine Sache? Mit Vollmacht und Kraft gebietet er den unreinen Geistern, und sie fahren aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Und so verbreitete sich sein Ruf in jener ganzen Gegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Von der Synagoge ging er in das Haus des Simon. Die Schwiegermutter des Simon war von hohem Fieber heimgesucht. Sie baten ihn für sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Und über sie gebeugt, gebot er dem Fieber, und es wich von ihr. Sofort erhob sie sich und wartete ihnen auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Gleich nach Sonnenuntergang brachten alle zu ihm ihre Kranken, die an mancherlei Gebrechen litten. Er legte jedem aus ihnen seine Hände auf und heilte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Von vielen fuhren auch Dämonen aus. Und diese schrien laut: \"Du bist der Sohn Gottes.\" Doch er bedrohte sie und ließ sie nicht weiterreden; sie wußten nämlich, daß er der Messias sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Bei Tagesanbruch begab er sich an einen abgelegenen Ort. Jedoch die Scharen suchten und fanden ihn. Sie wollten ihn hindern weiterzuziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Er aber sprach zu ihnen: \"Ich muß auch den anderen Städten die frohe Botschaft vom Reiche Gottes künden; dazu bin ich gesandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'So predigte er in den Synagogen Judäas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Und es geschah einmal, - er stand am See Genesareth -, daß sich das Volk an ihn herandrängte, um das Wort Gottes zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Er sah zwei Boote am Ufer liegen; die Fischer waren ausgestiegen und wuschen ihre Netze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Er stieg in eines der Boote, das dem Simon gehörte, und bat ihn, vom Land ein wenig abzustoßen. Dann setzte er sich nieder und lehrte die Scharen vom Boote aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Als er zu reden aufgehört hatte, sagte er zu Simon: \"Fahr auf die hohe See und werft eure Netze aus zum Fange!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Doch Simon sprach zu ihm: \"Meister, die ganze Nacht haben wir uns abgeplagt und trotzdem nichts gefangen. Allein auf dein Wort hin will ich die Netze auswerfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Sie taten es und fingen eine große Menge Fische; die Netze drohten zu zerreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Sie winkten den Gefährten im anderen Boote, sie sollten kommen und mit anfassen. Und diese kamen, und man füllte beide Boote, so daß sie beinahe versanken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Als Simon Petrus das sah, fiel er Jesus zu Füßen mit den Worten: \"Herr, geh weg von mir; ich bin ein sündiger Mensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Denn Schrecken hatte ihn ergriffen und alle, die bei ihm waren, des Fischfangs wegen, den sie gemacht hatten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'desgleichen auch Jakobus und Johannes, die Söhne des Zebedäus, die Simons Gefährten waren. Jesus aber sprach zu Simon: \"Hab keine Furcht! Von nun an sollst du Menschenfischer sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Sie zogen ihre Boote ans Land, verließen alles und gingen mit ihm fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'In einer jener Städte, wo er weilte, war ein Mann ganz vom Aussatz bedeckt. Als er Jesus sah, warf er sich vor ihm auf sein Antlitz nieder und bat: \"Herr, wenn du willst, kannst du mich rein machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Da streckte er die Hand aus, berührte ihn und sprach: \"Ich will: sei rein!\" Und sogleich wich von ihm der Aussatz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Er sprach zu ihm: \"Sage es niemand! Geh vielmehr hin, zeige dich dem Priester und opfere für deine Reinigung die Gabe, wie sie Moses vorgeschrieben hat; sie mögen dies zum Zeugnis nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Jedoch die Kunde über ihn breitete sich immer weiter aus. In Scharen strömten sie zusammen, um ihn zu hören und von ihren Krankheiten geheilt zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Er aber zog sich zum Gebet in die Einsamkeit zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Er lehrte eines Tages, und Pharisäer und Gesetzeslehrer, die aus allen Flecken Galiläas und Judäas und aus Jerusalem gekommen waren, saßen auch dabei. Die Kraft des Herrn trieb ihn zu Heilungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Und siehe, Männer brachten auf einer Bahre einen Lahmen her. Und sie versuchten, ihn hineinzubringen und ihn vor ihn hinzulegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Doch wegen des Gedränges konnten sie ihn nirgends hineinbringen, und so stiegen sie auf das Dach und ließen ihn durch die Ziegel mitsamt dem Bett hinab, mitten hin vor Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Wie er ihren Glauben sah, da sagte er: \"Mann, vergeben sind dir deine Sünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Die Schriftgelehrten und die Pharisäer aber machten sich Gedanken. Sie sprachen: \"Wer ist dieser, der Gotteslästerungen spricht? Wer kann denn Sünden vergeben als Gott allein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Doch Jesus wußte, was sie dachten, und sprach zu ihnen: \"Was denkt ihr in euren Herzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Was ist leichter, zu sagen: Vergeben sind dir deine Sünden, oder zu sagen: Steh auf und geh umher?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Ihr sollt aber sehen, daß der Menschensohn die Macht besitzt, auf Erden Sünden zu vergeben.\" Dann sprach er zu dem Lahmen: \"Ich sage dir: Steh auf, nimm dein Bett und geh nach Hause!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Sofort erhob er sich vor ihren Augen, nahm das Bett, auf dem er gelegen hatte, ging nach Hause und pries Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Da kamen alle außer sich; sie lobten Gott und sagten voll Furcht: \"Heute haben wir Unglaubliches gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Dann ging er fort; da sah er einen Zöllner namens Levi an der Zollstätte sitzen. Er sprach zu ihm: \"Folge mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Und er verließ alles, stand auf und folgte ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Danach hielt Levi ihm in seinem Haus ein großes Mahl. Eine große Menge Zöllner und andere saßen mit zu Tische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Da murrten die Pharisäer und die Schriftgelehrten und fragten seine Jünger: \"Warum eßt und trinkt ihr denn mit Zöllnern und mit Sündern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'ich bin nicht dazu da, Gerechte zu berufen, sondern Sünder zur Buße.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Da sagten sie zu ihm: \"Die Jünger des Johannes und die der Pharisäer fasten viel und beten eifrig, die deinen aber essen und trinken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Doch Jesus sprach zu ihnen: \"Könnt ihr die Hochzeitsgäste fasten lassen, solange der Bräutigam noch unter ihnen weilt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Es werden aber Tage kommen, da ihnen der Bräutigam entrissen ist; in jenen Tagen werden sie dann gleichfalls fasten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Alsdann erzählte er ihnen auch ein Gleichnis: \"Niemand reißt ein Stückchen Tuch von einem neuen Kleide ab und näht es auf ein altes Kleid; sonst ist ja das neue Kleid zerrissen, und auch zum alten paßt das Stück vom neuen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Und niemand füllt jungen Wein in alte Schläuche, sonst sprengt der junge Wein die Schläuche, er selbst läuft aus, und auch die Schläuche sind verdorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Nein, jungen Wein muß man in neue Schläuche füllen dann hält beides.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Und niemand, der alten Wein getrunken hat, mag gleich daraufhin neuen. Er sagt: \'Der alte schmeckt doch besser.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Da sagten einige der Pharisäer: \"Warum tut ihr, was am Sabbat verboten ist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Doch Jesus sprach zu ihnen: \"Habt ihr denn nicht gelesen, was David tat, als er und seine Begleiter Hunger hatten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'wie er das Haus Gottes betrat, die Schaubrote nahm und aß, die nur die Priester essen dürfen, und auch noch seinen Begleitern gab?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Und weiter sprach er zu ihnen: \"Der Menschensohn ist Herr des Sabbats.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'An einem anderen Sabbat ging er in die Synagoge, wo er lehrte. Dort war ein Mensch, dessen rechte Hand verwelkt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Die Schriftgelehrten und die Pharisäer gaben acht, ob er am Sabbat heile, um einen Grund zur Klage gegen ihn zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Jedoch er wußte, was sie dachten, und sagte zu dem Manne mit der verwelkten Hand: \"Steh auf und stell dich in die Mitte!\" Da stand er auf und stellte sich dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Dann sprach Jesus zu ihnen: \"Ich frage euch: Darf man am Sabbat Gutes oder Böses tun, ein Leben retten oder es vernichten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Er schaute alle, einen nach dem andern, an und sprach darauf zu ihm: \"Strecke deine Hand aus.\" Er tat es, und seine Hand ward wiederhergestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Sie wurden ganz rasend und berieten miteinander, was sie Jesus antun könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'In jenen Tagen ging er fort auf einen Berg, um dort zu beten. Die ganze Nacht verbrachte er im Gebet mit Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Nachdem es Tag geworden war, rief er seine Jünger zu sich her und wählte zwölf aus ihnen aus, die er Apostel nannte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, dem er den Namen Petrus gab, und Andreas, dessen Bruder, Jakobus, Johannes, Philippus, Bartholomäus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthäus, Thomas und Jakobus, des Alphäus Sohn, Simon, der auch der Eiferer heißt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'und Judas, des Jakobs Bruder, und den Judas Iskariot; dieser wurde sein Verräter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Er stieg mit ihnen hinab und blieb auf einem ebenen Platze stehen samt einer großen Schar von seinen Jüngern. Und eine gewaltige Menge Volkes war herbeigeeilt aus ganz Judäa und Jerusalem, auch aus dem Küstenland von Tyrus und von Sidon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Sie kamen, um ihn zu hören und um von ihren Krankheiten geheilt zu werden; auch die von unreinen Geistern Heimgesuchten wurden geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Und alles Volk versuchte, ihn zu berühren; denn eine Kraft ging von ihm aus und heilte alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Dann blickte er seine Jünger an und sprach: \"Selig, ihr Armen, denn euer ist das Reich Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Selig, die ihr jetzt hungert; denn ihr werdet gesättigt werden. Selig, die ihr jetzt weinet; ihr werdet lachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Selig seid ihr, wenn euch die Menschen hassen und verstoßen und schmähen und den guten Namen rauben um des Menschensohnes willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Freut euch an jenem Tag und frohlockt; denn seht, euer Lohn ist groß im Himmel. Ihre Väter haben es ja den Propheten ebenso gemacht. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Doch wehe euch, ihr Reichen; ihr habt schon euren Trost.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Weh euch, die ihr jetzt satt seid; ihr werdet hungern. Weh euch, die ihr jetzt lachet; ihr werdet trauern und weinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Wehe, wenn euch alle Menschen loben. Ihre Väter haben es den falschen Propheten ebenso gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Doch euch, die ihr zuhört, sage ich: Liebet eure Feinde, tut Gutes denen, die euch hassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'segnet die, die euch verfluchen, betet für die, die euch mißhandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Schlägt dich jemand auf die eine Wange, so halte ihm auch die andere hin. Nimmt einer dir den Mantel weg, alsdann versage ihm auch den Rock nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Dem, der dich bittet, gib; wer dir das Deine nimmt, von diesem fordere es nicht zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Was ihr von anderen erwartet, das sollt auch ihr ihnen ebenso tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Wolltet ihr nur jene lieben, die euch lieben, welchen Verdienst habt ihr davon? Auch die Sünder lieben die, von denen sie geliebt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Wenn ihr nur denen Gutes tut, die euch Gutes erweisen, welchen Verdienst habt ihr davon? Dasselbe tun ja auch die Sünder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Wenn ihr nur denen leiht, von denen ihr es wieder zu bekommen hofft, welchen Verdienst habt ihr davon? Auch Sünder leihen ja einander, um den gleichen Betrag dafür zu erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Liebt vielmehr eure Feinde, tut Gutes, leihet, ohne etwas zurückzuerwarten. Alsdann wird euer Lohn groß sein, ihr werdet Söhne des Allerhöchsten sein, der selber gütig ist gegen Undankbare und gegen Böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'So seid also barmherzig, wie euer Vater auch barmherzig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Richtet nicht, dann werdet ihr nicht gerichtet werden; verdammt nicht, dann werdet ihr nicht verdammt werden; vergebt, und es wird euch vergeben werden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'gebt, und es wird euch gegeben werden. Ein gutes, ein gedrücktes und gerütteltes, ein überfließendes Maß wird man euch in den Schoß schütten. Denn mit dem Maß, mit dem ihr messet, wird euch zugemessen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Dann trug er ihnen ein Gleichnis vor: \"Kann ein Blinder einen Blinden führen? Werden nicht beide in eine Grube fallen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Der Schüler steht nicht über seinem Lehrer; jeder, der ausgelernt hat, ist wie sein Lehrer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Was siehst du zwar den Splitter im Auge deines Bruders, doch den Balken in deinem eignen Auge siehst du nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Oder wie magst du zu deinem Bruder sprechen: \'Bruder, laß mich den Splitter dir aus dem Auge ziehen\', du, der du den Balken in deinem eigenen Auge nicht siehst? Du Heuchler! Zieh zuerst den Balken aus deinem Auge, und dann magst du sehen, wie du den Splitter aus dem Auge deines Bruders ziehst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Kein guter Baum trägt schlechte Frucht, und ebenso: Kein schlechter Baum trägt gute Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Jeden Baum erkennt man an seiner Frucht; denn von den Disteln pflückt man keine Feigen, und von dem Dornbusch liest man keine Trauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Der gute Mensch bringt aus dem guten Schatze seines Herzens Gutes hervor; der Böse aber bringt aus bösem Schatze Böses hervor; denn aus des Herzens Überfülle redet der Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Warum nennt ihr mich: \'Herr, Herr\' und tut doch nicht, was ich sage?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Ich will euch zeigen, wem der gleicht, der zu mir kommt und meine Worte hört und nach ihnen handelt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Er gleicht einem Manne, der ein Haus gebaut hat; er grub tief und setzte das Grundgemäuer auf den Felsen. Als nun Hochwasser kam, da prallte die Flut an das Haus, vermochte es aber nicht zu erschüttern, weil es gut gebaut war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Wer aber meine Worte nur hört und nicht nach ihnen handelt, ist einem Manne gleich, der sein Haus ohne Grundgemäuer nur auf den Boden hingebaut hat. Die Flut prallte daran, und es fiel sogleich ein, und dieses Haus stürzte ganz zusammen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Nachdem er alle seine Reden vor dem aufmerksamen Volk beendet hatte, ging er nach Kapharnaum hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Der Knecht eines Hauptmanns lag auf den Tod krank darnieder, er war ihm lieb und teuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Als der Hauptmann von Jesus hörte, ließ er ihn durch angesehene Juden bitten, er möge kommen, um seinen Knecht zu heilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Sie kamen zu Jesus und baten ihn inständig. Sie sagten: \"Er verdient es, daß du ihm dies gewährst;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'er liebt unser Volk und hat uns die Synagoge gebaut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus ging mit ihnen. Als er nicht mehr weit vom Haus entfernt war, ließ ihm der Haupt-mann durch Freunde sagen: \"Herr, bemühe dich nicht; ich bin nicht würdig, daß du unter meinem Dach Einkehr hältst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Deshalb hielt ich mich selbst auch nicht für wert, zu dir zu kommen. Sprich ein Wort, so wird mein Knecht gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Ich bin zwar nur Untergebener, habe aber doch Soldaten unter mir. Wenn ich zu dem da sage: \'Geh!\', dann geht er, und zu einem anderen: \'Komm!\', dann kommt er, und zu meinem Knechte: \'Tu dies!\', dann tut er es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Als Jesus dies hörte, mußte er sich über ihn verwundern. Er wandte sich zum Volk, das ihn begleitete, und sprach: \"Ich sage euch: Solch einen Glauben habe ich nicht einmal in Israel gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Die Boten kehrten in das Haus zurück und fanden den Knecht gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Er ging weiter und kam in eine Stadt mit Namen Naim. In großer Zahl begleiteten ihn seine Jünger und viel Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Als er in die Nähe des Stadttors kam, trug man eben einen Toten heraus, den einzigen Sohn seiner Mutter, diese war Witwe. Mit ihr ging eine große Menge aus der Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Als der Herr sie sah, empfand er Mitleid über sie und sprach zu ihr: \"Weine nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Dann trat er hin und rührte die Bahre an. Die Träger standen still. Er sprach: \"Jüngling, ich sage dir, steh auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Da setzte sich der Tote auf und begann zu sprechen. Und Jesus gab ihn seiner Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Furcht ergriff alle; sie priesen Gott und sprachen:., Ein mächtiger Prophet ist bei uns aufgestanden\" und: \"Gott hat sein Volk heimgesucht\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Die Kunde von dieser seiner Tat verbreitete sich im ganzen Judenland und in den Grenzgebieten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'All dies berichteten seine Jünger dem Johannes. Da rief Johannes zwei seiner Jünger zu sich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'sandte sie zum Herrn und ließ ihn fragen: \"Bist du es, der da kommen soll, oder sollen wir auf einen anderen warten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Die Männer trafen bei ihm ein und sagten: \"Johannes der Täufer schickt uns zu dir und läßt dich fragen: \'Bist du es, der da kommen soll, oder sollen wir auf einen anderen warten?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'In jener Stunde heilte er gerade viele von Krankheiten, Gebrechen und von bösen Geistern und schenkte vielen Blinden das Augenlicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'So gab er ihnen zur Antwort: \"Geht hin und meldet dem Johannes, was ihr gesehen und gehört habt: Blinde sehen, Lahme gehen, Aussätzige werden rein, Taube hören, Tote stehen auf, Armen wird die Heilsbotschaft verkündet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'und selig ist, wer sich an mir nicht ärgert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Als die Boten des Johannes wieder fortgegangen waren, sprach er zu den Scharen von Johannes: \"Was wolltet ihr denn sehen, als ihr in die Steppe ginget? Etwa ein Schilfrohr, vom Winde hin und her bewegt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Was wolltet ihr doch sehen? Wohl einen Menschen, angetan mit weichlichen Gewändern? O, die weichlich gekleidet sind und üppig leben, wohnen in den Königsburgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Was wolltet ihr also sehen? Etwa einen Propheten? Wahrlich, ich sage euch, mehr sogar als einen Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Dieser ist es, von dem geschrieben steht: \'Siehe, ich sende meinen Engel vor dir her, daß er den Weg vor dir bereite.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Ich sage euch: Von denen, die vom Weib geboren sind, gibt es keinen Größeren als Johannes. Der Kleinste im Gottesreich ist aber größer als er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Und alles Volk, das ihn hörte, ja, selbst die Zöllner gaben Gott recht und empfingen die Taufe des Johannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Die Pharisäer und Gesetzeslehrer aber achteten den für sie bestimmten Ratschluß Gottes nicht und ließen sich von ihm nicht taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Wem soll ich die Menschen dieses Geschlechtes vergleichen? Wem sind sie gleich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Sie gleichen Kindern, die auf dem Marktplatz sitzen und einander zurufen: \'Wir haben euch auf der Flöte vorgespielt, ihr aber habt nicht getanzt; wir haben Klagelieder gesungen, und ihr habt nicht geweint.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Johannes der Täufer kam, aß kein Brot und trank keinen Wein, da sagtet ihr: \'Er ist besessen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Es kam der Menschensohn, er ißt und trinkt; ihr aber sagt: \'Seht den Schlemmer und den Säufer, den Freund der Zöllner und der Sünder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Indes die Weisheit ward von allen ihren Kindern doch als gerecht anerkannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Ein Pharisäer bat ihn einst zu Tisch. Er ging ins Haus des Pharisäers und setzte sich zu Tisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'In jener Stadt lebte nun ein sündiges Weib. Als sie erfuhr, daß er zu Tisch im Hause des Pharisäers sei, brachte sie ein Gefäß aus Alabaster voll Salböl mit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'ließ sich hinter ihm zu seinen Füßen nieder und weinte. Dann fing sie an, mit ihren Tränen seine Füße zu benetzen, trocknete sie mit den Haaren ihres Hauptes ab, küßte seine Füße und salbte sie mit dem Salböl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Als dies der Pharisäer, der ihn geladen hatte, sah, sprach er bei sich: \"Wenn dieser ein Prophet wäre, so wüßte er, wer und was für ein Weib dies ist, die ihn berührt, daß sie eine Sünderin ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Da wandte Jesus sich zu ihm und sprach: \"Simon, ich muß dir etwas sagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Er entgegnete: \"Sag es, Meister.\" Er sprach: \"Ein Gläubiger hatte zwei Schuldner, der eine war ihm fünfhundert Denare schuldig, der andere fünfzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Da sie nicht bezahlen konnten, schenkte er den beiden ihre Schuld. Sag: Welcher von ihnen wird ihn nun am meisten lieben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon gab zur Antwort: \"Ich denke, der, dem er das meiste geschenkt hat.\" \"Du hast recht geurteilt\", sprach er zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Und zu dem Weib gewendet, sprach er weiterhin zu Simon: \"Siehst du dieses Weib? Ich kam in dein Haus, und du gabst mir kein Wasser für die Füße; sie aber hat mit ihren Tränen meine Füße benetzt und sie mit ihren Haaren abgetrocknet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Du gabst mir keinen Kuß; sie aber hat seit meinem Eintritt nicht aufgehört, mir die Füße zu küssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Du salbtest mein Haupt nicht mit Öl; sie aber hat mir die Füße mit Salböl gesalbt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Deshalb, sage ich dir, sind ihr viele Sünden nachgelassen, weil sie große Liebe hat. Wem aber wenig nachgelassen wird, der liebt auch wenig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Hierauf sprach er zu ihr: \"Deine Sünden sind dir nachgelassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Da dachten die Tischgenossen bei sich: \"Wer ist doch der, daß er sogar Sünden nachläßt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Er aber sprach zum Weibe: \"Dein Glaube hat dich gerettet; geh hin in Frieden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Alsdann durchwanderte er auch selbst nacheinander Städte und Dörfer. Er predigte und verkündete das Evangelium vom Reiche Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Ihn begleiteten die Zwölf und ein paar Frauen, die Heilung von bösen Geistern und von Krankheiten gefunden hatten: Maria, mit dem Beinamen Magdalena, aus der sieben böse Geister ausgefahren waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'sodann Johanna, Eheweib des Chusa, eines der Verwalter des Herodes, Susanna und noch viele andere, die sie mit ihrer Habe unterstützten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Als eine große Volksmenge zusammenkam und man aus den Städten zu ihm herbeieilte, trug er dieses Gleichnis vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '\"Der Sämann ging aus, seinen Samen auszusäen. Und als er säte, fiel einiges auf den Weg; es ward zertreten, und die Vögel des Himmels fraßen es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Anderes fiel auf steinigen Grund; es ging zwar auf, doch es verdorrte sogleich; denn es fand keine Feuchtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Wieder anderes fiel unter Dornen; die Dornen wuchsen mit ihm auf und erstickten es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Anderes endlich fiel auf guten Boden; da ging es auf und trug hundertfältige Frucht.\" Dann sprach er mit erhobener Stimme: \"Wer Ohren hat zu hören, höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Seine Jünger fragten ihn, was dieses Gleichnis bedeute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Er sprach: \"Euch ist es vergönnt, die Geheimnisse des Reiches Gottes zu verstehen; den anderen aber werden sie nur in Gleichnissen vorgetragen, damit sie sehen und doch nicht sehen, und hören, aber nicht zur Einsicht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Das Gleichnis will dies besagen: Der Same ist das Wort Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, '\'Auf dem Wege\' liegt es bei denen, die das Wort hören; dann kommt der Teufel und nimmt das Wort aus ihren Herzen, damit sie nicht glauben und gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, '\'Auf steinigem Grunde\' liegt es bei denen, die das Wort zwar hören und mit Freuden aufnehmen; sie haben aber keine Wurzeln; sie glauben nur eine Zeitlang, aber in Zeiten der Versuchung fallen sie ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Was \'unter Dornen\' fällt, sind die, die zwar hören, aber in Sorgen, Reichtümern und Lebensfreuden aufgehen und also es ersticken, ohne Frucht zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Doch was \'auf guten Boden\' fiel, sind die, die das Wort mit gutem und mit frommem Herzen anhören und es bewahren und so Früchte bringen in Beharrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Niemand, der ein Licht anzündet, deckt es mit einem Topfe zu oder stellt es unters Bett; vielmehr stellt er es auf den Leuchter, damit man beim Eintritt das Licht erblicke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Nichts ist verborgen, was nicht offenkundig wird, und nichts geheim, was nicht bekannt wird und so an den Tag kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Gebt also darauf acht, wie ihr höret. Wer hat, dem wird gegeben werden; doch wer nicht hat, dem wird auch das genommen werden, was er zu besitzen meint.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Da kamen seine Mutter und seine Brüder zu ihm. Doch konnten sie des großen Andranges wegen nicht zu ihm gelangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Da sagte man zu ihm: \"Deine Mutter und deine Brüder stehen draußen und möchten dich sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Eines Tages stieg er in ein Boot mit seinen Jüngern und sprach zu ihnen: \"Laßt uns ans andere Seeufer hinüberfahren.\" Sie stießen vom Lande ab');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'und fuhren so dahin; er aber schlief. Da stürzte ein Sturmwind auf den See hernieder, das Boot füllte sich mit Wasser, und sie gerieten in Gefahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Sie gingen hin, weckten ihn und riefen: \"Meister, Meister, wir sind verloren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Er fragte sie: \"Wo ist euer Glaube?\" Voll Furcht und voll Verwunderung sprachen sie zueinander: \"Wer ist wohl dieser, daß er den Winden und dem Wasser befiehlt, so daß sie ihm gehorchen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Sie steuerten dem Land der Gergesener zu, das Galiläa gegenüber liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Kaum war er ans Land gestiegen, als ihm ein Mann aus dieser Stadt entgegenkam, der von Dämonen besessen war. Er trug schon lange keine Kleidung mehr; auch hielt er sich nicht in einem Hause auf, sondern in den Grabhöhlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Als er Jesus sah, stieß er einen lauten Schrei aus, fiel vor ihm nieder und rief mit lauter Stimme: \"Was willst du von mir, Jesus, du Sohn des höchsten Gottes? Ich bitte dich: quäle mich nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Er hatte nämlich dem unreinen Geist befohlen, aus dem Manne auszufahren. Schon lange hielt er ihn in seiner Macht. Man hatte ihn mit Fesseln und mit Ketten gebunden und ihn gefangengehalten, doch er hatte die Bande immer wieder zerrissen und ward vom Dämon in die Einöde hinausgetrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jesus fragte ihn: \"Wie ist dein Name?\" \"Legion\", sprach er. Es waren nämlich viele Dämonen in ihn gefahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Sie baten ihn, sie doch nicht in die Hölle zu verweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Nun war am Berge dort eine große Schweineherde auf der Weide. Sie baten ihn, er möge ihnen gestatten, in diese einzufahren. Und er gewährte es ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'So fuhren die Dämonen denn von dem Menschen aus in die Schweine. Die Herde raste dann am Abhang hin in den See hinein und ertrank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Als die Hirten sahen, was geschehen war, liefen sie davon und erzählten es in der Stadt und auf dem Lande.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Man kam zu sehen, was vorgefallen war. Sie kamen auch zu Jesus und sahen den Menschen, von dem die Dämonen gewichen waren, bekleidet und vernünftig zu den Füßen Jesu sitzen; da gerieten sie in Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Die zugesehen hatten, erzählten ihnen, wie der Besessene gesund geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Da bat ihn die Bevölkerung des Bezirks Gergesa insgesamt, er möge sich von ihnen entfernen; denn große Furcht hielt sie gefangen. So stieg er in ein Boot und kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Der Mann, von dem die Dämonen gewichen waren, bat ihn, ob er nicht bei ihm bleiben dürfe. Doch er entließ ihn mit den Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '\"Kehre in dein Haus zurück; erzähle, was Gott an dir getan hat.\" Da ging er hin und erzählte in der ganzen Stadt, was ihm Jesus getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Bei seiner Rückkehr nahm die Menge Jesus freudig auf; denn alle warteten auf ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Da kam ein Mann mit Namen Jairus; er war Vorsteher der Synagoge. Er fiel zu den Füßen Jesu nieder und bat ihn, in sein Haus zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Er hatte eine einzige Tochter von zwölf Jahren; diese lag im Sterben. Als er hinging, war er vom Volk umdrängt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Da war ein Weib, das schon zwölf Jahre lang an Blutfluß litt; sie hatte ihr ganzes Vermögen an die Ärzte ausgegeben und konnte doch bei ihnen keine Heilung finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Sie trat von hinten her und berührte den Saum seines Kleides, und sogleich hörte der Blutfluß auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Da fragte Jesus: \"Wer hat mich angerührt?\" Alle leugneten es; Petrus und die bei ihm waren, sprachen: \"Meister, die Scharen schieben und drängen dich und da fragst du noch: \'Wer hat mich angerührt?\' \"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Doch Jesus gab zur Antwort: \"Es hat mich jemand angerührt; ich habe es gefühlt, wie eine Kraft von mir ausgegangen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Da sah das Weib, daß sie nicht unbemerkt geblieben war. Und zitternd kam sie her, fiel vor ihm nieder und erzählte dann vor allem Volk, weshalb sie ihn berührt und wie sie auch sofort geheilt worden sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Er aber sprach zu ihr. \"Meine Tochter, dein Glaube hat dir geholfen. Geh hin im Frieden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Noch sprach er so, da kam jemand vom Hause des Synagogenvorstehers und sprach zu ihm: \"Deine Tochter ist schon tot; bemühe den Meister nicht mehr weiter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Als Jesus dies vernahm, sprach er zu ihm: \"Hab keine Furcht! Glaube nur! Sie wird gerettet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Am Hause angekommen, ließ er niemand mit sich hinein, nur Petrus, Johannes und Jakobus sowie den Vater und die Mutter des Mädchens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Alle weinten und klagten über sie. Er aber sprach: \"Weinet nicht! Sie ist nicht tot; sie schläft nur.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Doch sie verlachten ihn; sie wußten ja, daß sie gestorben war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Da faßte er sie bei der Hand und rief: \"Mädchen, steh auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Da kehrte ihr Geist zurück, und sogleich stand sie auf. Dann ließ er ihr zu essen geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Ihre Eltern waren außer sich vor Staunen; er aber schärfte ihnen ein, von dem, was geschehen war, mit niemand zu reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Er rief die Zwölf zusammen und verlieh ihnen Kraft und Vollmacht über alle Dämonen und die Gewalt, Krankheiten zu heilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Dann sandte er sie aus, das Reich Gottes zu verkünden und Kranke zu heilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Er sprach zu ihnen: \"Nehmt nichts mit auf den Weg, nicht Stab, noch Bettelsack, noch Brot, noch Geld; auch sollt ihr nicht zwei Röcke haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Wo immer ihr ein Haus betretet, da bleibt und zieht von hier dann wieder weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Wo man euch aber nicht aufnimmt, da verlaßt die Stadt und schüttelt selbst den Staub von euren Füßen zum Zeugnis wider sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'So machten sie sich auf den Weg und zogen von Ort zu Ort; sie verkündigten das Evangelium und heilten überall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Von all den Dingen drang die Kunde auch zum Vierfürsten Herodes, und er geriet in Unruhe; denn einige sagten: \"Johannes ist von den Toten auferstanden\";');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'andere: \"Elias ist erschienen\"; wieder andere: \"Einer von den alten Propheten ist auferstanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Herodes aber sagte: \"Johannes habe ich doch enthaupten lassen; wer mag nur der sein, von dem ich solche Dinge höre?\" Und er wünschte, ihn zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Nun kehrten die Apostel wiederum zurück, und sie erzählten ihm, was sie alles vollbracht hatten. Da zog er sich mit ihnen allein in eine Stadt zurück, die Bethsaida heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Die Scharen merkten es und kamen hinterher. Und er nahm sie freundlich auf; er redete zu ihnen vom Reiche Gottes und heilte alle, die Heilung nötig hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Der Tag ging schon zur Neige. Die Zwölf traten zu ihm hin und sagten: \"Entlaß die Scharen, sie mögen in die Dörfer und die Flecken hier im Umkreis gehen, Obdach und Nahrung suchen; denn hier sind wir in der Steppe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Er aber sprach zu ihnen: \"Gebt ihr ihnen doch zu essen!\" Sie erwiderten jedoch: \"Wir haben nur fünf Brote und zwei Fische; wir müßten denn hingehen und für diese ganze Menge Speise kaufen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Es waren nämlich an fünftausend Männer. Da sagte er zu seinen Jüngern: \"Laßt sie in Gruppen zu je fünfzig lagern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Sie taten es und ließen alle sich lagern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Dann nahm er die fünf Brote und die zwei Fische, sah zum Himmel auf, segnete sie, brach sie und gab sie seinen Jüngern, sie sollten sie dem Volke vorlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Und alle aßen und wurden satt; ja, man hob noch zwölf Körbe von den Brocken auf, die übriggeblieben waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Als er einmal einsam betete und nur die Jünger um ihn waren, da fragte er sie: \"Für wen halten mich die Leute?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Sie gaben ihm zur Antwort: \"Für Johannes den Täufer, andere für Elias; noch andere sagen, einer der alten Propheten sei wieder auferstanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Da fragte er sie weiter: \"Ihr aber, für wen haltet ihr mich?\" Und Petrus gab zur Antwort: \"Für den Gesalbten Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Darauf verbot er ihnen streng, dies irgend jemand zu sagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, '\"Der Menschensohn\", sprach er, \"muß vieles leiden, er muß von den Ältesten, den Oberpriestern und den Schriftgelehrten verworfen und getötet werden und am dritten Tage auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Zu allen aber sagte er: \"Wer mir nachfolgen will, der verleugne sich selbst, jeden Tag nehme er sein Kreuz auf sich und folge mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Denn wer sein Leben sich erhalten will, der wird es verlieren; und wer sein Leben mir zulieb verliert, der wird es erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Was nützte es dem Menschen, wenn er die ganze Welt gewänne, sich selbst jedoch verlöre oder zugrunde ginge?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Denn wer sich meiner und meiner Worte schämt, dessen wird auch der Menschensohn sich schämen, wenn er in seiner Herrlichkeit und der des Vaters und der heiligen Engel kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Ich sage euch in Wahrheit: Es stehen solche hier, die den Tod nicht kosten werden, bis sie das Reich Gottes gesehen haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Acht Tage ungefähr nach diesen Reden nahm er Petrus, Jakobus und Johannes mit sich und stieg auf den Berg, um zu beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Während er betete, veränderte sich der Ausdruck seines Angesichtes, und sein Gewand ward glänzend weiß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Und siehe, zwei Männer redeten mit ihm, Moses und Elias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Sie erschienen in Herrlichkeit und sprachen über seinen Tod, wie er sich in Jerusalem erfüllen sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petrus ward mit den Gefährten vom Schlafe übermannt. Beim Erwachen sahen sie ihn in seiner Herrlichkeit und die zwei Männer, die bei ihm waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Als diese sich entfernen wollten, sprach Petrus zu Jesus: \"Wie schön ist es, Meister, daß wir hier sind! Wir möchten gern drei Hütten bauen: Dir eine, dem Moses eine und dem Elias eine.\" Er wußte jedoch nicht, was er sagte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Noch sprach er so, als eine Wolke kam und sie in Dunkel hüllte. Sie fürchteten sich sehr, als jene in die Wolke gingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Und aus der Wolke erscholl eine Stimme: \"Das ist mein erwählter Sohn, auf diesen sollt ihr hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Während die Stimme erscholl, war Jesus ganz allein. Sie schwiegen und erzählten in jenen Tagen niemandem, was sie gesehen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Des anderen Tags stiegen sie vom Berg hinab, und eine große Menge Volkes kam ihnen entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Und siehe, aus der Menge rief ein Mann: \"Meister, ich bitte dich, nimm dich meines Sohnes an, es ist mein einziger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Siehe, ein Geist packt ihn, und alsdann schreit er sogleich auf; er zerrt ihn hin und her, wobei er schäumt. Nur schwer läßt er von ihm ab; er reibt ihn noch ganz auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Ich hatte deine Jünger gebeten, sie möchten ihn austreiben, doch sie haben es nicht vermocht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Und Jesus sprach: \"O du ungläubiges, verkehrtes Geschlecht! Wie lang noch muß ich bei euch sein und euch ertragen? Bring deinen Sohn hierher!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Noch während er herbeikam, riß und zerrte ihn der Dämon hin und her, und Jesus drohte dem unreinen Geist und heilte so den Knaben und gab ihn seinem Vater wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Da staunte alles über die große Macht Gottes. Während alle über alle seine Taten voll Erstaunen waren, sprach er zu seinen Jüngern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '\"Behaltet diese Worte tief im Gedächtnis: Der Menschensohn wird in die Hände der Menschen überliefert werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Sie konnten aber dieses Wort nicht verstehen; es blieb ihnen verborgen, und sie sollten es nicht erfassen. Sie scheuten sich jedoch, ihn danach zu fragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Einst kam es bei ihnen zur Erörterung, wer unter ihnen wohl der Größte sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Da nahm Jesus, der die Gedanken ihres Herzens wohl erkannte, ein Kind und stellte dieses neben sich');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'und sprach zu ihnen: \"Wer dieses Kind in meinem Namen aufnimmt, nimmt mich auf. Und wer mich aufnimmt, nimmt den auf, der mich gesandt hat. Wer so der Kleinste von euch allen ist, nur der ist groß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Da sagte Johannes: \"Meister, wir sahen einen, der in deinem Namen Dämonen austrieb; wir suchten ihn zu hindern, weil er dir nicht mit uns nachfolgt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Doch Jesus sprach zu ihm: \"Hindert ihn nicht; denn wer nicht gegen euch ist, der ist für euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'So kamen die Tage seines Hingangs heran. Da schlug er unverwandten Blicks die Richtung nach Jerusalem ein');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'und sandte Boten vor sich her. Diese machten sich auf den Weg und kamen in ein Dorf der Samariter, um eine Unterkunft für ihn zu suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Allein, man nahm ihn nicht auf, weil sein Reiseziel Jerusalem war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Als dies Jakobus und Johannes, seine Jünger, hörten, sagten sie: \"Herr, sollen wir nicht Feuer vom Himmel rufen, daß es sie verzehre?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Da wandte er sich um und verwies es ihnen und sprach: \"Ihr wisset nicht, wes Geistes Kinder ihr seid. Der Menschensohn ist nicht gekommen, Menschen zu verderben, sondern zu retten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Sie gingen dann in eine andere Ortschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Und unterwegs sprach zu ihm irgendeiner: \"Herr, ich will dir folgen, wohin du gehst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Doch Jesus sprach zu ihm: \"Die Füchse haben Höhlen, die Vögel des Himmels Nester, der Menschensohn jedoch hat keine Stätte, wohin er sein Haupt legen könnte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Zu einem anderen sprach er: \"Folge mir!\" Doch der erwiderte: \"Herr, laß zuvor mich nochmals gehen, damit ich meinen Vater begrabe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Er aber sprach zu ihm: \"Laß die Toten ihre Toten begraben. Du aber gehe hin, verkündige das Reich Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Ein anderer sprach: \"Ich will dir folgen, Herr; doch laß zuerst mich zu Hause Abschied nehmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Doch Jesus sprach zu ihm: \"Für das Reich Gottes ist niemand brauchbar, der die Hand an den Pflug anlegt und wieder rückwärts schaut.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Er sprach zu ihnen: \"Die Ernte ist groß, jedoch der Arbeiter sind es wenige. Bittet den Herrn der Ernte, daß er Arbeiter in seine Ernte sende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Geht hin! Seht, ich sende euch wie Lämmer mitten unter Wölfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Nehmt weder Beutel, Bettelsack noch Schuhe mit; grüßt niemand unterwegs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Wo immer ihr ein Haus betretet, da sagt zuerst: \'Der Friede sei mit diesem Hause.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Wohnt darin ein Kind des Friedens, so wird euer Friede auf ihm ruhen, wo nicht, wird er zu euch zurückkehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Bleibt in dem gleichen Hause und eßt und trinkt, was sich dort findet, der Arbeiter ist seines Lohnes wert. Zieht nicht von einem Haus zum anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Und wo ihr eine Stadt betretet und man euch aufnimmt, da eßt, was man euch vorsetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Heilt die Kranken, die dort sind und verkündet ihnen: \'Das Reich Gottes hat sich euch genaht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Wo immer aber ihr in eine Stadt eintretet und man euch nicht aufnimmt, da geht auf ihre Straßen hinaus und sagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '\'Sogar den Staub, der sich in eurer Stadt an unsere Füße angehängt hat, schütteln wir auf euch. Doch das sollt ihr wissen: Das Reich Gottes hat sich genaht.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Ich sage euch: \'An jenem Tage\' wird es Sodoma erträglicher gehen als jener Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Wehe dir, Chorozain! Wehe dir, Bethsaida! Denn wenn in Tyrus und in Sidon die Wunder geschehen wären, die bei euch geschehen sind, dann hätten sie schon längst in Sack und Asche sitzend Buße getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Doch Tyrus und Sidon wird es erträglicher ergehen im Gericht als euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Und du, Kapharnaum! Warst du nicht bis in den Himmel erhoben worden? Bis in die Hölle hinab sollst du fahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Wer auf euch hört, hört auf mich; wer euch abweist, weist mich ab, wer aber mich abweist, weist den ab, der mich gesandt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Voll Freuden kamen die zweiund- siebzig wiederum zurück. Sie sagten: \"Herr, sogar die Dämonen sind uns in deinem Namen untertan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Er sprach zu ihnen: \"Ich sah den Satan wie einen Blitz vom Himmel stürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Seht, ich habe euch Macht gegeben, über Schlangen und Skorpionen wegzuschreiten und über alle feindlichen Gewalten; nichts soll euch schaden können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Doch nicht darüber freuet euch, daß euch die Geister unterworfen sind, freut euch vielmehr, daß eure Namen in den Himmeln aufgeschrieben sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'In jener Stunde frohlockte er im Heiligen Geist und sprach: \"Ich preise dich, Vater, Herr des Himmels und der Erde, daß du all dies den Weisen und Klugen verhüllt hast, Einfältigen jedoch geoffenbart. Ja, Vater, also fügt es deine Güte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Mir ist von meinem Vater alles übergeben, und niemand versteht es, wer der Sohn ist, als nur der Vater, und niemand, wer der Vater ist, als allein der Sohn und wem der Sohn es offenbaren will.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Dann wandte er sich seinen Jüngern noch besonders zu und sprach: \"Selig sind die Augen, die sehen, was ihr seht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Ich sage euch: Viele Propheten und Könige wollten sehen, was ihr seht, sie sahen es aber nicht, und hören, was ihr hört, sie hörten es aber nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Siehe, da erhob sich ein Gesetzeslehrer, um ihn zu versuchen. Er fragte:\"Meister, was habe ich zu tun, um das ewige Leben zu erlangen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Er sprach zu ihm: \"Was steht im Gesetz geschrieben? Was liesest du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Und jener gab zur Antwort: \"Du sollst den Herrn, deinen Gott, lieben aus deinem ganzen Herzen, aus deiner ganzen Seele, mit deiner ganzen Kraft und allen deinen Gedanken, und deinen Nächsten wie dich selbst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Er sprach zu ihm: \"Du hast recht geantwortet; tu das, so wirst du leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Doch jener wollte sich rechtfertigen und fragte Jesus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, '\"Wer ist mein Nächster?\" Und Jesus nahm das Wort und sprach: \"Ein Mensch ging von Jerusalem nach Jericho hinab und fiel Räubern in die Hände. Diese plünderten ihn aus, sie gaben ihm dazu noch Schläge, ließen ihn dann halbtot liegen und verschwanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Zufällig zog ein Priester jenen Weg hinab; er sah ihn und ging vorüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Desgleichen kam auch ein Levit an die Stelle; er sah ihn und ging vorüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Da kam ein Samariter des Wegs gerade zu ihm hin, er sah ihn und ward von Mitleid tief gerührt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Er trat hinzu, goß Öl und Wein auf seine Wunden und verband sie. Dann setzte er ihn auf sein Reittier und brachte ihn in eine Herberge und sorgte noch für ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Des anderen Tags zog er zwei Denare aus dem Beutel, gab sie dem Wirt und sprach: \'Sorge für ihn! Was du darüber noch aufwendest, will ich dir nach meiner Rückkehr bezahlen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Wer von diesen dreien hat sich wohl als Nächster dessen gezeigt, der unter die Räuber gefallen war?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Er sprach: \"Der ihm Barmherzigkeit erwiesen hat.\" Und Jesus sprach zu ihm: \"Geh hin und tu desgleichen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Einmal kehrte er auf ihrer Wanderung in einem Flecken ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Und eine Frau mit Namen Martha nahm ihn in ihr Haus auf. Sie hatte eine Schwester, die Maria hieß. Und diese setzte sich zu den Füßen des Herrn nieder und lauschte auf sein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Indessen machte sich Martha mit der Bewirtung viel zu schaffen. Sie trat hinzu und sprach: \"Herr, kümmert es dich nicht, daß meine Schwester mich allein bedienen läßt? Sage ihr, daß sie mir helfen soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Doch der Herr sprach zu ihr: \"Martha, Martha, du machst dir Unruhe und Sorge um vielerlei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Wenig ist notwendig, oder nur eins. Maria hat den besseren Teil erwählt, der ihr nicht wird genommen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Einstmals verweilte er an einem Ort beim Beten. Als er geendet hatte, bat ihn einer seiner Jünger: \"Herr, lehre uns beten, gleichwie Johannes seine Jünger es gelehrt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Er sprach zu ihnen: \"Wenn ihr betet, sprecht also: \'Vater, geheiligt werde dein Name. Es komme dein Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Gib uns täglich unser nötig Brot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Und vergib uns unsere Sünden; denn auch wir vergeben jedem, der unser Schuldner ist, und führe uns nicht in Versuchung\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Dann fuhr er fort: \"Einer aus euch hat einen Freund, und dieser kommt mitten in der Nacht zu ihm und bittet ihn: \'Freund, leihe mir drei Brote;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Ein Freund von mir ist auf der Reise bei mir eingekehrt, und ich habe nichts, was ich ihm vorsetzen könnte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Doch jener gibt von drinnen zur Antwort: \'Laß mich in Ruh! Die Tür ist schon geschlossen, und meine Kinder sind mit mir im Bett; ich kann nicht aufstehen und dir etwas geben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Und wenn er fortmacht mit Klopfen Ich sage euch: Wenn er nicht aufsteht und ihm etwas gibt, weil es sein Freund ist, so wird er sich seines Drängens wegen erheben und ihm geben, was er braucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'So sage auch ich euch: Bittet, und es wird euch gegeben werden, suchet, und ihr werdet finden, klopfet an, und es wird euch aufgetan werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Denn wer bittet, empfängt, wer sucht, findet, wer anklopft, dem wird aufgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Wo unter euch gibt es einen Vater, der seinem Kinde, das ihn um Brot anfleht, einen Stein geben würde? Oder wenn es ihn um einen Fisch bittet, ihm dann statt des Fisches eine Schlange reichen würde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Oder wenn es ihn um ein Ei bittet, ihm einen Skorpion gäbe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Wenn ihr nun, die ihr böse seid, doch euren Kindern gute Gaben zu geben wisset, um wieviel mehr wird der Vater im Himmel den Heiligen Geist denen geben, die ihn darum bitten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Einst trieb er einen Dämon aus, der stumm war. Und als der Dämon ausgefahren war, da redete der Stumme, die Scharen aber staunten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Doch einige aus ihnen sagten: \"Durch Beelzebul, den obersten der Dämonen, treibt er die Dämonen aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Andere versuchten ihn und forderten von ihm ein Zeichen vom Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Er aber wußte, was sie dachten, und sprach zu ihnen: \"Jedes Reich, das in sich uneins ist, zerfällt; ein Haus stürzt über das andere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Ist nun auch der Satan uneins mit sich selbst, wie sollte dann sein Reich bestehen? Ihr sagt, ich treibe durch Beelzebul die Dämonen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Wenn ich durch Beelzebul die Dämonen austreibe, durch wen treiben dann eure Söhne sie aus? So werden diese eure Richter sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Wenn ich jedoch die Dämonen durch den Finger Gottes austreibe, dann ist das Reich Gottes ja schon zu euch gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Und wenn ein Starker wohlbewaffnet seinen Hof bewacht, dann ist sein Eigentum in Sicherheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Doch kommt ein Stärkerer als er darüber und überwältigt ihn, so nimmt er ihm die Waffenrüstung ab, auf die er sich verlassen hatte, und verteilt, was er bei ihm erbeutet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Wer nicht mit mir ist, ist gegen mich, und wer nicht mit mir sammelt, zerstreut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Wenn der unreine Geist aus dem Menschen ausgefahren ist, wandert er durch öde Gegenden und sucht eine Ruhestätte. Doch weil er keine findet, sagt er: \'Ich will in mein Haus zurück, aus dem ich ausgezogen bin.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Er kommt und findet es rein gefegt und ausgeschmückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Dann geht er hin, nimmt noch sieben andere Geister mit, die schlimmer sind als er; sie ziehen ein und wohnen dort. Mit einem solchen Menschen wird es nachher schlimmer stehen als vorher.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Während er noch so redete, erhob ein Weib im Volke seine Stimme; es sprach zu ihm: \"Selig der Leib, der dich getragen hat, und die Brüste, die dich genährt haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Doch er erwiderte: \"Jawohl, selig, die Gottes Wort hören und es befolgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Als sich die Scharen an ihn drängten, sprach er: \"Dieses Geschlecht ist ein böses Geschlecht. Es fordert ein Zeichen; jedoch, es wird ihm kein anderes Zeichen gegeben werden als das Zeichen des Jonas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Wie Jonas den Niniviten zum Zeichen ward, so wird es der Menschensohn für dieses Geschlecht sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Die Königin des Südens wird beim Gericht zugleich mit den Männern dieses Geschlechtes sich erheben und wird sie verdammen. Sie kam ja von den Enden der Erde, um die Weisheit Salomons zu hören, und siehe, hier ist mehr als Salomon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Die Niniviten werden sich beim Gericht mit diesem Geschlecht erheben und es verdammen. Denn diese haben sich bekehrt, als Jonas ihnen predigte, und siehe, hier ist mehr als Jonas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Niemand, der ein Licht anzündet, stellt es in einen Winkel oder unter einen Scheffel, vielmehr auf einen Leuchter, daß man den hellen Schein beim Eintreten gleich sehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Die Leuchte des Leibes ist dein Auge. Ist dein Auge gesund, so ist dein ganzer Leib erleuchtet; ist es aber krank, so ist auch dein Leib verfinstert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Sieh also zu, ob nicht das Licht in dir verfinstert sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Doch wenn dein ganzer Leib erleuchtet ist und gar nichts Finsteres an sich hat, so ist er durch und durch erleuchtet, wie das Licht mit seinem Strahle dich erleuchtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Während er noch redete, lud einer von den Pharisäern ihn zum Essen ein. Er ging hin und setzte sich zu Tisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Wie nun der Pharisäer sah, daß er sich vor der Mahlzeit nicht gewaschen hatte, verwunderte er sich sehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Da sprach der Herr zu ihm: \"Ihr Pharisäer reinigt das Äußere von Bechern und Schüsseln, doch euer Inneres strotzt von Raubgier und Schlechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Ihr Toren! Hat er, der das Äußere gemacht hat, nicht auch das Innere gemacht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Gebt lieber das, was drinnen ist, als Almosen, und siehe, alles ist euch rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Doch wehe euch, ihr Pharisäer! Ihr verzehntet zwar Minze, Raute und ein jedes Gartenkraut, doch um Gerechtigkeit und Gottesliebe kümmert ihr euch nicht. Das eine soll man tun, das andere jedoch nicht unterlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Wehe euch, ihr Pharisäer! Ihr liebt den Ehrenplatz in den Synagogen sowie den Gruß auf den öffentlichen Plätzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Wehe euch! Ihr gleicht unkenntlich gewordenen Gräbern; man geht darüber hin und weiß es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Da sagte zu ihm ein Gesetzeslehrer: \"Mit diesen Worten, Meister, schmähst du auch uns.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Doch er erwiderte: \"Wehe auch euch, ihr Gesetzeslehrer! Ihr bürdet den Menschen unerträglich schwere Lasten auf, doch selber rührt ihr mit keinem Finger diese Lasten an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Wehe euch, ihr baut den Propheten Grabdenkmäler, doch eure Väter haben sie gemordet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Also bezeugt und billigt ihr die Taten eurer Väter; jene haben sie gemordet, ihr aber baut die Grabdenkmäler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Deshalb hat die Weisheit Gottes auch gesprochen: Ich will ihnen Propheten und Apostel senden, und einige aus ihnen werden sie ermorden und verfolgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'So soll von diesem Geschlecht all das Prophetenblut gefordert werden, das seit Erschaffung der Welt vergossen ward,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'vom Blute Abels an bis auf das Blut des Zacharias, der zwischen dem Altar und dem Tempelhaus seinen Tod gefunden hat. Ja, ich sage euch: Es wird von diesem Geschlechte gefordert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Wehe euch, ihr Gesetzeslehrer: Ihr habt den Schlüssel zur Erkenntnis weggenommen; ihr selber seid nicht eingetreten und habt noch jene ferngehalten, die eintreten wollten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Und er ging weg von da. Die Pharisäer und die Schriftgelehrten setzten ihm sehr auffällig zu und überhäuften ihn mit Fragen über vielerlei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Sie lauerten ihm dabei auf, um eine Äußerung aus seinem Munde aufzufangen und ihn anklagen zu können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Inzwischen hatten sich so viele Scharen eingefunden, daß man sich gegenseitig auf die Füße trat. Er sprach zunächst zu seinen Jüngern: \"Hütet euch vor dem Sauerteig der Pharisäer, das heißt vor Heuchelei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Denn es ist nichts geheim, was nicht offenkundig wird, und nichts verborgen, was nicht bekannt werden wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Was ihr im Dunkeln gesagt habt, das wird man im Tageslicht hören; was ihr in den innersten Kammern leise geflüstert habt, das wird man laut von den Dächern rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Euch, meinen Freunden, sage ich: Fürchtet euch nicht vor denen, die den Leib zwar töten können, doch weiter nichts vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ich will euch zeigen, wen ihr fürchten sollt: Fürchtet den, der über den Tod hinaus noch in die Hölle stürzen kann. Ja, ich sage euch: Den fürchtet!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Verkauft man nicht fünf Sperlinge schon für ein paar Pfennige? Und doch ist keiner aus ihnen bei Gott vergessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Sogar alle Haare eures Hauptes sind gezählt. So fürchtet euch denn nicht; ihr seid mehr wert als viele Sperlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Ich sage euch: Wer sich vor den Menschen zu mir bekennt, zu dem wird sich der Menschensohn auch vor den Engeln Gottes bekennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Wer aber mich vor den Menschen verleugnet, der wird vor den Engeln Gottes verleugnet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Und wer ein Wort sagt gegen den Menschensohn, dem wird vergeben werden; doch wer den Heiligen Geist lästert, dem wird nicht vergeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Wenn man euch vor die Synagogen, Obrigkeiten und Behörden schleppt, so macht euch keine Sorge, wie oder womit ihr euch verteidigen oder was ihr sagen sollt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'der Heilige Geist wird euch in jener Stunde lehren, was ihr sagen sollt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Da sagte zu ihm einer aus dem Volke: \"Meister, sage meinem Bruder, er solle das Erbe mit mir teilen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Er sprach zu ihm: \"Mensch, wer hat denn mich zum Richter oder Erbteiler für euch bestellt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Dann sprach er zu ihnen: \"Habt acht und hütet euch vor jeder Habsucht. Wenn einer auch im Überfluß hat, so hängt sein Leben doch nicht von seinem Vermögen ab.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Dann trug er ihnen ein Gleichnis vor: \"Ein Reicher hatte einen Acker voll Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Da dachte er bei sich: \'Was soll ich tun? Ich habe keinen Raum, wo ich meine Ernte unterbringen kann.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Er sprach: \'Das will ich tun: Ich breche meine Scheunen ab und baue größere; dort will ich meine ganze Ernte und meinen Besitz unterbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Ich will dann zu meiner Seele sagen: Meine Seele, jetzt hast du große Vorräte an Gütern für viele Jahre; nun setze dich zur Ruhe, iß und trink und laß dir\'s wohl sein. \'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Gott aber sprach zu ihm: \'Du Tor! Noch in dieser Nacht wird man dein Leben von dir zurückfordern. Wem wird dann das gehören, was du aufgespeichert hast?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'So geht es dem, der für sich selber Schätze häuft, jedoch nicht bei Gott reich ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Alsdann sprach er zu seinen Jüngern: \"Darum sage ich euch, sorgt nicht um das Leben, was ihr essen werdet, noch um den Leib, womit ihr ihn bekleiden sollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Das Leben ist doch mehr wert als die Nahrung, der Leib mehr als die Kleidung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Betrachtet die Raben: Sie säen nicht, sie ernten nicht; sie haben keine Scheune und keinen Speicher: Gott ernährt sie. Wieviel mehr wert seid ihr als Vögel!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Wer aus euch kann seine Lebenszeit mit seinen Sorgen nur um eine Elle verlängern?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Wenn also ihr nicht einmal Kleinigkeiten fertigbringt, was seid ihr dann ums Weitere so sehr besorgt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Betrachtet die Lilien wie sie wachsen, sie spinnen nicht, und sie weben nicht. Doch sage ich euch: Nicht einmal Salomon in seiner ganzen Herrlichkeit war so gekleidet wie eine einzige aus ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Wenn nun Gott das Gras, das heute auf dem Felde steht und morgen schon im Ofen liegt, also kleidet, wieviel mehr dann euch, ihr Kleingläubigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'So fragt denn nicht, was ihr essen oder trinken sollt; laßt euch nicht in Unruhe versetzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Um all dies bekümmern sich die Heiden in der Welt draußen. Doch euer Vater weiß, daß ihr dies braucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Nur müßt ihr sein Reich suchen und seine Gerechtigkeit, dann wird euch jenes dazugegeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Fürchte dich nicht, du kleine Herde; es hat eurem Vater gefallen, euch das Reich zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Verkauft eure Habe und gebt Almosen davon. Verschafft euch Beutel, die sich nicht abnützen, einen unvergänglichen Schatz in den Himmeln, an den kein Dieb kommt und den die Motten nicht zerfressen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Denn wo euer Schatz ist, da ist auch euer Herz..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Eure Lenden seien umgürtet und eure Lampen brennend;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'ihr sollt Menschen gleichen, die auf ihren Herrn warten, bis er vom Hochzeitsfest heimkommt, um ihm sofort zu öffnen, wenn er kommt und klopft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Wohl den Knechten, die der Herr bei seiner Ankunft wachend findet. Wahrlich, ich sage euch: Er wird sich selbst umgürten, sie aber sitzen heißen, herumgehen und sie bedienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Mag er zu der zweiten oder dritten Nachtwache kommen, trifft er sie also an, wohl ihnen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Doch dies bedenkt: Wenn der Hausherr wüßte, zu welcher Stunde der Dieb kommt, dann würde er wachen und nicht in sein Haus einbrechen lassen. So seid auch ihr bereit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Der Menschensohn kommt zu einer Stunde, da ihr es nicht vermutet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Da fragte Petrus: \"Beziehst du dieses Gleichnis, Herr, auf uns oder auf alle?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Der Herr sprach: \"Wer ist der treue und verständige Verwalter, den der Herr über sein Gesinde setzen wird, auf daß er ihm zur rechten Zeit den Unterhalt darreiche?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Wohl dem Knechte, den der Herr bei seiner Heimkehr also handelnd antrifft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Wahrlich, ich sage euch: Er wird ihn zum Verwalter aller seiner Güter machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Doch würde jener Knecht bei sich denken: \'Mein Herr bleibt noch länger aus\', und wenn er die Knechte und die Mägde verprügelt, wenn er essen, zechen und sich berauschen würde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'alsdann wird der Herr eines solchen Knechtes an einem Tag erscheinen, da er es nicht erwartet, zu einer Stunde, die ihm nicht bekannt ist. Er wird ihn in Stücke hauen und ihm bei den Ungläubigen seinen Platz geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Und jener Knecht, der den Willen seines Herrn zwar kennt, doch keine Vorbereitung trifft, noch nach dem Willen seines Herrn handelt, wird viele Schläge erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Wer ihn aber nicht kennt und Dinge tat, die Schläge verdienen, wird weniger Schläge erhalten. Wem viel gegeben ist, von dem wird viel gefordert werden, und wem viel anvertraut ist, von dem wird man auch um so mehr verlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Ich bin gekommen, Feuer auf die Erde zu werfen, und wie sehr wünschte ich, es loderte empor!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Doch muß ich eine Taufe empfangen, und wie drängt es mich, bis sie vollendet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Glaubt ihr, ich sei gekommen, Frieden in die Welt zu bringen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Nein, ich sage euch, vielmehr Entzweiung. Es werden fortan fünf in ein und demselben Hause uneins sein: Drei gegen zwei und zwei gegen drei;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'der Vater gegen seinen Sohn, der Sohn gegen seinen Vater; die Mutter gegen ihre Tochter, die Tochter gegen ihre Mutter; die Schwiegermutter gegen ihre Schwiegertochter, die Schwiegertochter gegen ihre Schwiegermutter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Dann sprach er zu den Scharen: \"Wenn ihr im Westen eine Wolke aufsteigen seht, dann sagt ihr sogleich: \'Nun gibt es Regen.\' Und es trifft ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Und weht der Südwind, dann sagt ihr: \'Nun wird es heiß.\' Und es trifft zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Ihr Heuchler! Die Zeichen an Himmel und Erde wißt ihr zu deuten; warum deutet ihr dann nicht die heutige Zeit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Warum entscheidet ihr nicht von euch selbst, was recht ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Während du mit deinem Gegner noch zur Obrigkeit hingehst, gib dir unterwegs noch Mühe, von ihm loszukommen. Sonst könnte er dich vor den Richter schleppen, der Richter dich dem Gerichtsdiener übergeben und der Gerichtsdiener dich ins Gefängnis werfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Ich sage dir, du wirst von da nicht herauskommen, bevor du nicht den allerletzten Pfennig bezahlt hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Zu eben dieser Zeit kamen einige und erzählten ihm von Galiläern, deren Blut Pilatus vergossen habe, wie sie gerade opferten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Er sprach zu ihnen: \"Ihr meint wohl, diese Galiläer seien größere Sünder gewesen als alle anderen Galiläer, weil sie solches erlitten haben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Gewiß nicht, sage ich euch. Vielmehr: Wenn ihr euch nicht bekehrt, so werdet ihr alle ebenso zugrunde gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Oder meint ihr, es seien jene achtzehn, die durch den Einsturz des Turmes am Siloe den Tod gefunden, schuldiger gewesen als die anderen Bewohner Jerusalems?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Durchaus nicht, sage ich euch. Wenn ihr euch nicht bekehrt, so werdet ihr alle ebenso zugrunde gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Dann trug er ihnen dieses Gleichnis vor: \"Jemand hatte einen Feigenbaum in seinem Weinberg stehen. Er kam und suchte daran Frucht, fand aber keine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Da sprach er zum Winzer: \'Sieh, schon drei Jahre komme ich hierher und suche auf diesem Feigenbaum Frucht, finde aber keine. Hau ihn heraus! Wozu saugt er den Boden aus?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, '\'Herr\', erwiderte ihm jener, \'laß ihn dieses Jahr noch stehen, ich will um ihn herum aufgraben und Dung einlegen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'vielleicht bringt er in Zukunft doch noch Frucht; wo nicht, magst du ihn heraushauen lassen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Er lehrte irgendwo an einem Sabbat in einer Synagoge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Siehe, da war eine Frau, die schon achtzehn Jahre lang einen Krankheitsgeist hatte. Sie war gekrümmt und konnte sich nicht ganz aufrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Als Jesus sie erblickte, rief er sie zu sich her und sprach zu ihr: \"Frau, du bist von deiner Krankheit befreit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Er legte ihr die Hände auf, und sogleich richtete sie sich auf und lobte Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Doch voll Entrüstung, daß Jesus auch am Sabbat heile, sprach der Synagogenvorsteher zum Volk: \"Sechs Tage sind zur Arbeit da; an diesen kommt und laßt euch heilen, doch nicht am Sabbattag!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Der Herr jedoch entgegnete ihm: \"Ihr Heuchler, bindet denn nicht jeder von euch am Sabbat seinen Ochsen oder Esel von der Krippe los und führt ihn zur Tränke?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Doch diese, eine Tochter Abrahams, die der Satan schon achtzehn Jahre gebunden hält, sollte nicht am Sabbattag von dieser Fessel befreit werden dürfen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Bei diesen Worten mußten sich alle seine Gegner schämen. Das ganze Volk jedoch ward voll Freude wegen all der großen Taten, die er vollbrachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Dann sprach er: \"Wem ist das Reich Gottes gleich? Womit soll ich es vergleichen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Es gleicht einem Senfkörnlein, das jemand in seinen Garten säte; es wuchs und ward zu einem großen Baume, so daß selbst die Vögel des Himmels in seinen Zweigen nisteten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Und weiter sprach er: \"Womit soll ich das Reich Gottes vergleichen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Es gleicht einem Sauerteig. Den nahm ein Weib und mengte ihn mit drei Maß Mehl, bis alles ganz durchsäuert war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'So ging er lehrend durch die Städte und die Dörfer und zog weiter auf dem Wege nach Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Da fragte ihn jemand: \"Herr, sind es wenige, die gerettet werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Er sprach zu ihnen: \"Bemüht euch, durch die enge Tür einzugehen. Ich sage euch: Es werden viele einzugehen suchen, jedoch es nicht vermögen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Wenn sich der Hausherr einmal erhoben und die Tür abgeschlossen hat, so werdet ihr draußen stehen, an die Tür klopfen und rufen: \'Herr! Mach uns auf!\' Doch er wird euch entgegnen: \'Ich weiß nicht, woher ihr seid.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Dann werdet ihr erwidern: \'Wir haben doch vor deinen Augen einst gegessen und getrunken; du hast auf unseren Straßen gelehrt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Er aber wird euch erklären: \'Ich sage euch, ich weiß nicht, woher ihr seid. Hinweg von mir, all ihr Übeltäter!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Alsdann wird Heulen und Zähneknirschen sein, wenn ihr Abraham und Isaak und Jakob und alle Propheten im Reiche Gottes, euch selber aber daraus ausgeschlossen seht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Von Osten und von Westen, von Norden und von Süden kommen sie und werden im Reiche Gottes zu Tische sitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Seht, es gibt Letzte, die Erste sind, und Erste, die Letzte sein werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Am selben Tage noch kamen Pharisäer, die zu ihm sagten: \"Geh weg und zieh fort von hier, Herodes will dich töten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Er aber sprach zu ihnen: \"Geht und sagt diesem Fuchs: \'Siehe, ich treibe Dämonen aus und vollbringe Heilungen noch heute und morgen; am dritten Tag erst bin ich fertig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Doch heute, morgen und am nächsten Tag muß ich wandern; es geht ja doch nicht an, daß ein Prophet außerhalb Jerusalems umkomme.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, das du die Propheten mordest und jene steinigst, die zu dir gesandt sind! Wie oft habe ich deine Kinder sammeln wollen wie eine Henne ihre Küchlein unter ihre Flügel; allein, ihr habt es nicht gewollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Seht, euer Haus wird euch verbleiben. Jedoch ich sage euch: Ihr werdet mich nicht mehr sehen, bis die Zeit kommt, da ihr sprecht: \'Gepriesen sei, der da kommt im Namen des Herrn!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'An einem Sabbat ging er einmal in das Haus eines angesehenen Pharisäers zum Essen; sie gaben auf ihn acht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Und siehe, da war vor ihm ein Mann, der wassersüchtig war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Und Jesus fragte die Gesetzeslehrer und die Pharisäer: \"Ist es erlaubt, am Sabbat zu heilen oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Sie schwiegen. Da faßte er ihn an, heilte ihn und hieß ihn fortgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Sodann sprach er zu ihnen: \"Wenn einem unter euch sein Sohn oder sein Ochs in einen Brunnen fällt, wird er ihn nicht sofort herausziehen, auch am Sabbattag?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Sie konnten ihm darauf nichts erwidern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Als er nun wahrnahm, wie sich die Geladenen die ersten Plätze suchten, trug er ihnen dieses Gleichnis vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '\"Wenn du von jemand zur Hochzeit eingeladen bist, so suche dir nicht den ersten Platz heraus; es könnte ja ein Vornehmerer als du von jenem eingeladen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Käme alsdann der, der dich und ihn geladen hat, und sagte zu dir: \'Mach diesem Platz!\', so müßtest du mit Schande zum letzten Platz gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Bist du eingeladen, so gehe hin und setze dich auf den letzten Platz. Kommt dann dein Gastgeber und sagt zu dir: \'Freund, rücke höher hinauf!\', dann bist du vor allen deinen Tischgenossen geehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Denn jeder, der sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Er sagte aber auch zu seinem Gastgeber: \"Wenn du ein Mittags- oder Abendmahl bereitest, so lade nicht deine Freunde und deine Brüder ein, auch nicht die Verwandten noch reiche Nachbarsleute; sonst laden sie dich wieder ein und halten so dich schadlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Wenn du ein Gastmahl gibst, so lade vielmehr Bettler, Krüppel, Lahme, Blinde dazu ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Alsdann wohl dir; denn diese können dich nicht schadlos halten, und es wird dir vergolten werden bei der Auferstehung der Gerechten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Als einer von den Tischgenossen dies hörte, sprach er zu ihm: \"Ja, selig, wer im Reiche Gottes speisen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Darauf sprach er zu ihm: \"Ein Mann bereitete ein großes Gastmahl und lud viele dazu ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Als die Stunde des Mahles gekommen war, schickte er seinen Knecht aus und ließ den Eingeladenen sagen: \'Kommt, es ist schon bereit!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Da fingen sie insgesamt an, sich zu entschuldigen. Der erste sprach zu ihm: \'Ich habe mir ein Gut gekauft und muß nun hin, mir es anzusehen; ich bitte dich, halte mich für entschuldigt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Ein anderer sprach: \'Ich habe fünf Paar Ochsen gekauft und gehe hin, diese zu erproben; ich bitte dich, halte mich für entschuldigt!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Ein dritter sprach: \'Ich habe mir ein Weib genommen und kann deshalb nicht kommen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Der Knecht kam zurück und sagte dies seinem Herrn. Da ward der Hausherr zornig und befahl dem Knecht: \'Gehe eilends auf die Straßen und Gassen der Stadt und hole die Bettler, Krüppel, Blinden, Lahmen hier herein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, '\'Herr\', meldete der Knecht, \'dein Befehl ist erfüllt; doch ist immer noch Platz übrig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Da sprach der Herr zum Knechte: \'Dann gehe an die Wege und die Zäune und nötige sie hereinzukommen, damit mein Haus ganz voll werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Doch dies sage ich euch: Nicht einer jener Männer, die geladen waren, soll mein Mahl verkosten.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Und große Scharen folgten ihm. Er wandte sich an sie und sprach zu ihnen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '\"Wenn einer zu mir kommt und Vater, Mutter, Weib und Kind, Brüder und Schwestern, ja, selbst sein eigenes Leben ihm nicht gleichgültig erscheinen, der kann nicht mein Jünger sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Und wer sein Kreuz nicht trägt und mir nicht folgt, der kann nicht mein Jünger sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Wenn einer von euch einen Turm erbauen will, setzt er sich dann nicht vorher hin, die Kosten zu berechnen, ob er auch die Mittel zur Ausführung habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Wenn er den Grund legen würde und könnte den Bau nicht vollenden, so würden alle, die es sehen, ihn verspotten und sagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '\'Der Mensch hat einen Bau begonnen, ihn aber nicht zu Ende führen können.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Oder, wenn ein König gegen einen anderen König zu Felde ziehen will, setzt er sich dann nicht vorher hin und überlegt, ob er mit Zehntausend dem entgegentreten kann, der mit Zwanzigtausend gegen ihn heranrückt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Vermag er es nicht, so schickt er, solange jener noch fern ist, eine Botschaft ab und bittet um Friedensbedingungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'So kann denn keiner unter euch mein Jünger sein, der nicht all seiner Habe entsagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Das Salz ist etwas Gutes. Wenn aber sogar das Salz die Kraft verlieren würde, womit soll man es würzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Es ist weder für den Boden noch für den Düngerhaufen brauchbar; man wirft es eben weg. Wer Ohren hat zu hören, höre!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Es kamen Zöllner und Sünder aller Art zu ihm, um ihn zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Darüber murrten die Pharisäer und die Schriftgelehrten; sie sprachen: \"Er nimmt sich der Sünder an und ißt mit ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Da trug er ihnen folgendes Gleichnis vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '\"Wer von euch, der hundert Schafe hat und eins davon verliert, läßt nicht die neunundneunzig in der Steppe und geht dem verirrten nach, bis er es findet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Und hat er es gefunden, so nimmt er es voll Freude auf seine Schultern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Und wenn er dann nach Hause kommt, so ruft er seine Freunde und alle Nachbarn zusammen und sagt zu ihnen: \'Freut euch mit mir; ich habe mein verirrtes Schaf wiedergefunden!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Ich sage euch: Geradeso wird im Himmel mehr Freude sein über einen einzigen Sünder, der sich bekehrt, als über neunundneunzig Gerechte, die sich nicht zu bekehren brauchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Oder welches Weib, das zehn Drachmen besitzt und eine davon verloren hat, zündet nicht ein Licht an, kehrt das Haus und sucht mit Sorgfalt, bis sie das Geld gefunden hat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Und hat sie es gefunden, so ruft sie ihre Freundinnen und Nachbarinnen zusammen und sagt: \'Freut euch mit mir; ich habe die Drachme gefunden, die ich verloren hatte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Ebenso, sage ich euch, herrscht auch bei den Engeln Gottes Freude über einen einzigen Sünder, der sich bekehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Dann fuhr er fort: \"Ein Mann hatte zwei Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Der jüngere sprach zum Vater: \'Vater, gib mir den Anteil des Vermögens, der mir zukommt.\' Dieser teilte das Vermögen unter sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Einige Tage später packte der jüngere Sohn all sein Gut zusammen und zog in ein fremdes Land. Dort verschwendete er sein Vermögen durch ein liederliches Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Als er alles durchgebracht hatte, entstand überall in jenem Lande schwere Hungersnot, und allmählich litt er bittere Not.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Da ging er hin und drängte sich einem Bürger dieses Landes auf. Und dieser schickte ihn auf seine Felder, um dort die Schweine zu hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Zu gern hätte er nun seinen Magen mit den Schoten angefüllt, die die Schweine fraßen; doch niemand gab sie ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Da kam er wieder zur Besinnung, und er sprach: \'Wie viele Taglöhner bei meinem Vater haben Brot im Überfluß, und ich komme hier vor Hunger um!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Ich will mich aufmachen, zu meinem Vater gehen und ihm sagen: Vater, ich habe gesündigt wider den Himmel und vor dir;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'ich bin nicht wert, dein Sohn zu heißen, halte mich nur wie einen deiner Taglöhner. \'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Da machte er sich auf und ging zu seinem Vater. Als er noch weit weg war, sah ihn schon sein Vater und ward von Mitleid gerührt. Er eilte ihm entgegen, fiel ihm um den Hals und küßte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Da sprach zu ihm der Sohn: \'Vater, ich habe gesündigt wider den Himmel und vor dir. Ich bin nicht mehr wert, dein Sohn zu heißen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Jedoch der Vater sagte seinen Knechten: \'Holt schnell das beste Kleid und zieht es ihm an; gebt ihm einen Ring an die Hand und Schuhe an die Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Holt auch das Mastkalb her und schlachtet es; wir wollen essen und fröhlich sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Denn dieser mein Sohn war tot und lebt nun wieder; er war verirrt und ist jetzt wiedergefunden.\' Und sie fingen an, ein Freudenmahl zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Sein älterer Sohn war eben auf dem Felde. Als er auf dem Heimweg in die Nähe des Hauses kam, hörte er Musik und Tanz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Da rief er einen Knecht herbei und fragte, was dies zu bedeuten habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Er sagte ihm: \'Dein Bruder ist gekommen; dein Vater hat das Mastkalb schlachten lassen, weil er ihn gesund zurückerhalten hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Da ward er zornig und wollte nicht hineingehen. Sein Vater aber ging hinaus und redete ihm gütlich zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Er aber sprach zum Vater: \'Sieh, schon so viele Jahre diene ich dir und habe noch niemals einen deiner Befehle übertreten. Doch mir hast du noch nie auch nur ein Böcklein überlassen, damit ich mit meinen Freunden hätte ein Festmahl halten können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Jetzt aber, da dein Sohn, der dein Vermögen mit Huren verpraßt hat, heimkommt, da hast du ihm das Mastkalb schlachten lassen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Doch er entgegnete ihm: \'Mein Sohn, du bist mit bei mir, und all das meinige ist dein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Jedoch wir mußten fröhlich sein und jubeln; denn dieser dein Bruder war tot und lebt jetzt wieder; er war verirrt und ist wieder aufgefunden worden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Und er erzählte weiterhin den Jüngern: \"Ein reicher Mann hatte einen Verwalter. Dieser ward bei ihm beschuldigt, er verschleudere seine Güter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Er ließ ihn rufen und hielt ihm vor: \'Was muß ich von dir hören? Gib Rechenschaft von deiner Verwaltung; du kannst nicht länger Verwalter sein.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Da dachte der Verwalter bei sich: \'Was soll ich nun tun, weil mein Herr mir die Verwaltung nimmt? Graben kann ich nicht; zu betteln schäme ich mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ich weiß, was ich tue, damit die Leute mich in ihre Häuser aufnehmen, wenn ich aus der Verwaltung entfernt bin.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Er ließ die Schuldner seines Herrn, einen nach dem anderen, zu sich kommen. Den ersten fragte er: \'Wieviel bist du meinem Herrn schuldig?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Er gab zur Antwort:, Hundert Krüge Öl.\' \'Da hast du deinen Schuldschein\', sagte er zu ihm, \'setz dich jetzt hin und flugs schreibe fünfzig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Einen anderen fragte er: \'Wieviel bist du schuldig?\' Er gab zur Antwort: \'Hundert Malter Weizen.\' Zu diesem sagte er: \'Da hast du deinen Schuldschein, schreibe achtzig.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Der Herr lobte den ungetreuen Verwalter, weil er klug gehandelt habe. Sind doch die Kinder dieser Welt klüger als die Kinder des Lichtes, soweit es sich um ihresgleichen handelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Auch ich sage euch: Macht euch Freunde mit dem ungerechten Mammon, damit man euch, wenn er zu Ende geht, in die ewigen Wohnungen aufnehme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Wer im Kleinsten getreu ist, ist auch im Großen getreu. Wer aber im Kleinsten ungetreu ist, der ist es auch im Großen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Wenn ihr mit dem ungerechten Mammon nicht getreu gewesen seid, wer wird euch das wahre Gut anvertrauen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Und wenn ihr mit dem fremden Gute nicht getreu gewesen seid, wer wird euch dann den eigenen Besitz anvertrauen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kein Knecht kann zwei Herren dienen: Entweder haßt er den einen und liebt den anderen, oder er hält sich zu dem einen und verachtet den anderen; ihr könnt nicht Gott und zugleich dem Mammon dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'All dies hörten auch die geldgierigen Pharisäer und verhöhnten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Er sprach zu ihnen: \"Ihr gebt euch vor den Menschen als Gerechte aus; Gott aber kennt eure Herzen. Was den Menschen groß erscheint, ist vor Gott ein Greuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Das Gesetz und die Propheten reichen bis auf Johannes; von da an wird das Gottesreich verkündigt; und jeder dringt mit Gewalt hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Eher werden aber der Himmel und die Erde untergehen, als daß auch nur ein Strichlein vom Gesetze fällt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Jeder, der sein Weib entläßt und eine andere heiratet, bricht die Ehe, und wer eine von dem Mann Entlassene heiratet, bricht ebenfalls die Ehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Es war ein reicher Mann, der kleidete sich in Purpur und feine Leinwand und hielt alle Tage glänzende Gelage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Vor seiner Tür lag ein Armer namens Lazarus, mit Geschwüren ganz bedeckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Wie gern hätte er mit dem, was vom Tische des Reichen abfiel, sich gesättigt aber niemand gab es ihm. Sogar die Hunde kamen und leckten an seinen Geschwüren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Da starb der Arme und wurde von den Engeln in den Schoß Abrahams getragen. Doch auch der Reiche starb und ward in die Hölle begraben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Als er in der Hölle mitten in den Qualen seine Augen erhob, sah er in der Ferne Abraham und in dessen Schoß den Lazarus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Da rief er: \'Vater Abraham! Erbarme dich meiner, sende den Lazarus, damit er seine Fingerspitze ins Wasser tauche und meine Zunge kühle; ich leide große Qual in dieser Glut.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham jedoch erwiderte: \'Kind, bedenke, dir ist es in deinem Leben gut ergangen, dem Lazarus hingegen schlecht. Jetzt wird er hier getröstet, du aber wirst gepeinigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Zu alledem gähnt zwischen uns und euch eine weite Kluft, damit keiner von hier zu euch hinüber kann und keiner von dort zu uns, selbst wenn er wollte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Darauf sprach jener: \'Dann bitte ich dich, Vater, sende ihn in mein väterliches Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Ich habe nämlich noch fünf Brüder. Die soll er warnen, damit nicht auch sie an diesen Ort der Qual kommen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham indes entgegnete: \'Sie haben Moses und die Propheten; auf diese sollen sie hören.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Doch er entgegnete: \'Nein, Vater Abraham; wenn einer von den Toten zu ihnen käme, dann würden sie sich bekehren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Er aber sprach zu ihm: \'Wenn sie auf Moses und die Propheten nicht hören, so werden sie sich auch nicht überzeugen lassen, wenn einer von den Toten auferstünde.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Er aber sprach zu seinen Jüngern: \"Unmöglich ist es, daß Ärgernisse ausbleiben; wehe aber dem, durch den sie kommen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Besser ist es für ihn, wenn ihm ein Mühlstein an den Hals gehängt und er ins Meer geworfen würde, als daß er einem dieser Kleinen Anlaß zur Sünde gäbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Habt aufeinander acht! Verfehlt sich dein Bruder, so stelle ihn zur Rede. Bereut er, vergib ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Auch wenn er siebenmal des Tages sich gegen dich verfehlte und siebenmal vor dir erscheinen und vor dir sagen sollte: \'Es tut mir leid.\' Vergib ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Dann sagten die Apostel zum Herrn: \"Vermehre unseren Glauben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Der Herr jedoch erwiderte: \"Wenn ihr nur Glauben hättet so groß wie ein Senfkörnlein, ihr könntet diesem Maulbeerbaum befehlen: \'Entwurzle dich und pflanze dich ins Meer\'; er würde euch gehorchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Einer aus euch hat einen Knecht fürs Pflügen oder Hüten. Nun kommt er vom Felde heim; wird er da zu ihm sagen: \'Komm doch gleich her und setze dich zu Tisch\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Wird er nicht vielmehr zu ihm sagen: \'Richte mir die Mahlzeit her, umgürte dich, bediene mich, bis ich gegessen und getrunken habe; und danach kannst auch du essen und trinken?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Weiß er dem Knecht etwa Dank dafür, daß er getan hat, was ihm befohlen war?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'So sollt auch ihr, wenn ihr alles getan habt, was man euch befohlen hat, sagen: \'Wir sind nichtsnutzige Knechte, wir haben nur getan, was wir schuldig waren.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Auf seinem Wege nach Jerusalem zog er mitten durch Samaria und Galiläa hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Da kamen ihm beim Eingang in ein Dorf zehn aussätzige Männer entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Sie blieben in der Ferne stehen und riefen laut: \"Jesus, Meister, erbarme dich unser!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Als er sie sah, sprach er zu ihnen: \"Geht hin und zeigt euch den Priestern!\" Und auf dem Wege dahin wurden sie gereinigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Ein einziger aus ihnen kehrte um, als er sah, daß er geheilt sei, und lobte Gott mit lauter Stimme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Er fiel ihm zu Füßen auf sein Antlitz und dankte ihm. Und dieser war ein Samariter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Da fragte Jesus: \"Sind nicht alle zehn rein geworden? Wo sind die neun?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'So fand sich keiner, der umgekehrt wäre, um Gott die Ehre zu geben, als dieser Fremde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Alsdann sprach er zu ihm: \"Steh auf und geh; dein Glaube hat dich gerettet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Da fragten ihn die Pharisäer: \"Wann kommt das Reich Gottes?\" Er sprach zu ihnen. \"Das Reich Gottes kommt nicht so, daß man es berechnen kann;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'man kann nicht sagen: Hier ist es oder dort. Nein, seht, das Reich Gottes ist mitten unter euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Dann sagte er zu seinen Jüngern: \"Es werden Tage kommen, da ihr euch danach sehnen werdet, einen einzigen Tag des Menschensohnes zu erleben; doch ihr werdet ihn nicht erleben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Man wird euch sagen: \'Siehe, dort ist er! Siehe, hier ist er!\' Geht nicht dahin und lauft ihnen nicht nach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Denn wie der Blitzstrahl von einem Ende des Himmels bis zum anderen leuchtet, so wird es auch mit dem Menschensohn an seinem Tage sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Zuvor jedoch muß er vieles leiden und von diesem Geschlechte verworfen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Wie es in den Tagen Noes war, so wird es auch in den Tagen des Menschensohnes sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Man aß und trank, man nahm und gab zur Ehe bis zu dem Tage, da Noe in die Arche ging. Da kam die Sintflut und vertilgte alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Es wird gehen wie zu Zeiten Lots: Man aß und trank, man kaufte und verkaufte, man pflanzte und baute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Am Tage aber, da Lot fortging aus Sodoma, regnete es Feuer und Schwefel vom Himmel und vertilgte alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Geradeso wird es an dem Tage sein, an dem der Menschensohn sich offenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Wer an jenem Tage auf dem Dach ist und seine Sachen noch im Hause hat, der steige nicht herab, um sie zu holen. Wer auf dem Feld ist, der wende sich nicht rückwärts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Denkt an Lots Weib!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Wer sein Leben für sich zu gewinnen sucht, wird es verlieren, und wer es verliert, wird es erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ich sage euch: In jener Nacht werden zwei auf einem Lager sein: Der eine wird mitgenommen, der andere zurückgelassen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Zwei werden miteinander mahlen: Die eine wird mitgenommen, die andere zurückgelassen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Zwei werden auf dem Felde sein: Der eine wird mitgenommen, der andere zurückgelassen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Sie fragten ihn: \"Wo, Herr?\" Er sprach zu ihnen: \"Wo das Aas ist, da sammeln sich die Geier.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Er zeigte ihnen dann in einem Gleichnis, daß man andauernd beten müsse und nicht nachlassen dürfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Er sprach: \"In einer Stadt lebte einst ein Richter, der Gott nicht fürchtete und nach Menschen nichts fragte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'In derselben Stadt lebte auch eine Witwe. Sie ging zu ihm und bat: \'Schaffe mir Recht gegen meinen Dränger!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Er wollte eine Zeitlang nicht. Dann sagte er sich: \'Ich fürchte zwar Gott nicht und frage auch nichts nach den Menschen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'doch dieser Witwe will ich zu ihrem Recht verhelfen, weil sie mir lästig fällt. Am Ende kommt sie noch und fährt mir ins Gesicht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Der Herr sprach weiter: \"Hört, was der ungerechte Richter sagt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Da sollte Gott seinen Auserwählten, die Tag und Nacht zu ihm rufen, nicht zu ihrem Recht verhelfen und sollte sie so lange warten lassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Ja, ich versichere euch: Plötzlich wird er ihnen Recht verschaffen. Doch wird der Menschensohn, wenn er kommt, den Glauben auf Erden finden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Einigen, die sich für gerecht ansahen und die anderen verachteten, trug er dieses Gleichnis vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '\"Zwei Menschen gingen in den Tempel, um zu beten. Der eine war ein Pharisäer und der andere ein Zöllner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Der Pharisäer stellte sich gerade hin und betete also bei sich: \'O Gott, ich danke dir, daß ich nicht bin wie die anderen Menschen, wie die Räuber, Betrüger, Ehebrecher oder auch wie dieser Zöllner da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Ich faste zweimal in der Woche und gebe den Zehnten von allem, was ich einnehme.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Der Zöllner aber blieb weit hinten stehen und wagte nicht einmal, die Augen zum Himmel zu erheben; er schlug an seine Brust und betete: \'Gott, sei mir Sünder gnädig!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ich sage euch: Dieser ging gerechtfertigt nach Hause, jener nicht. Denn jeder, der sich selbst erhöht, wird erniedrigt werden, und wer sich selbst erniedrigt, wird erhöht werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Man brachte zu ihm Kinder, daß er sie berühre. Als dies die Jünger sahen, fuhren sie sie hart an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Doch Jesus rief sie zu sich her und sprach: \"Lasset die Kinder zu mir kommen und wehrt es ihnen nicht; für solche ist das Reich Gottes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Wahrlich, ich sage euch: Wer das Reich Gottes nicht aufnimmt wie ein Kind, kommt nicht hinein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Ein Vorsteher richtete an ihn die Frage: \"Guter Meister, was muß ich tun, um das ewige Leben zu erwerben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Und Jesus sprach zu ihm: \"Was nennest du mich \'gut\'? Gut ist Gott allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Du kennst die Gebote: \'Du sollst nicht ehebrechen\', \'du sollst nicht töten\', \'du sollst nicht stehlen\', \'du sollst kein falsches Zeugnis geben\', \'du sollst Vater und Mutter ehren.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Doch dieser sprach: \"All das habe ich von Jugend auf so gehalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Als Jesus dies hörte, sagte er zu ihm: \"Eines fehlt dir noch: Verkaufe alles, was du hast, und verteile es den Armen, du wirst dann einen Schatz im Himmel haben. Dann komm und folge mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Als er das vernahm, ward er ganz traurig; war er doch reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Als Jesus ihn so sah, sprach er: \"Wie schwer kommen doch die Reichen in das Reich Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Viel leichter geht ein Kamel durch ein Nadelöhr als ein Reicher in das Reich Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Da fragten seine Hörer: \"Wer kann da noch gerettet werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Er sprach: \"Was bei den Menschen unmöglich ist, das ist möglich bei Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Da sagte Petrus: \"Siehe, wir haben unser Eigentum verlassen und sind dir nachgefolgt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Er sprach zu ihnen: \"Wahrlich, ich sage euch: Es gibt keinen, der um des Reiches Gottes willen Haus und Weib, Brüder, Eltern oder Kinder verläßt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'und nicht viel mehr erhält in dieser Welt und in der anderen Welt das ewige Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Dann rief er die Zwölf zu sich her und sprach zu ihnen: \"Seht, wir ziehen nach Jerusalem hinauf, und alles wird in Erfüllung gehen, was die Propheten vom Menschensohn geschrieben haben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Er wird den Heiden ausgeliefert, verspottet, mißhandelt und angespieen werden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'sie werden ihn geißeln und ihn töten, doch am dritten Tage wird er auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Sie verstanden aber nichts davon; die Rede war für sie dunkel, und sie begriffen nicht, was er damit sagen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Er näherte sich Jericho; am Weg saß ein Blinder und bettelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Dieser hörte, wie das Volk vorbeizog, und fragte, was dies zu bedeuten habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Man sagte ihm: \"Jesus von Nazareth geht vorüber.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Da rief er: \"Jesus, Sohn Davids, erbarme dich meiner!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Die vorausgingen, fuhren ihn an, er solle schweigen. Er aber schrie nur um so lauter: \"Sohn Davids, erbarme dich meiner!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Da blieb Jesus stehen und ließ ihn zu sich führen. Er kam her, und Jesus fragte ihn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '\"Was soll ich dir tun?\" Er bat: \"Herr, ich möchte sehen können.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Und Jesus sprach zu ihm: \"Sei sehend! Dein Glaube hat dir geholfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Und er konnte sogleich sehen, pries Gott und folgte ihm. Auch alles Volk, das zugesehen hatte, lobte Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Er kam nach Jericho und zog hindurch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Da war ein Mann, der Zachäus hieß, er war ein Oberzöllner und reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Er hätte gern gesehen, wer Jesus sei; allein der Menge wegen war es ihm nicht möglich, denn er war klein von Gestalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Deshalb lief er voraus, stieg auf einen Maulbeerfeigenbaum, um ihn zu sehen; Jesus mußte nämlich dort vorüberkommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Als Jesus an die Stelle kam, blickte er empor und sprach zu ihm: \"Zachäus, steige schnell herab, denn heute muß ich in deinem Hause bleiben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Da stieg er schnell herab und nahm ihn voll Freude auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Doch alle, die es sahen, murrten; sie sprachen: \"Bei einem Sünder ist er eingekehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zachäus aber trat vor ihn und sprach zum Herrn: \"Siehe, Herr, die Hälfte meines Vermögens gebe ich den Armen, und habe ich jemand übervorteilt, gebe ich es vierfach wieder zurück.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Und Jesus sprach zu ihm: \"Heute ist diesem Hause Heil widerfahren, weil auch er ein Sohn Abrahams ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Denn der Menschensohn ist gekommen, zu suchen und zu retten, was verloren war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Und vor denselben Zuhörern fügte er ein Gleichnis an, war er doch nahe bei Jerusalem, und jene meinten, daß jetzt gleich das Reich Gottes erscheinen müsse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Er sagte also: \"Ein Mann von edler Abkunft zog in ein fernes Land. Er wollte sich dort die Königswürde erlangen und danach wieder heimwärts ziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Er rief seine zehn Knechte zu sich her und gab ihnen zehn Minen und sprach zu ihnen: \'Treibt damit Handel, bis ich wiederkomme.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Seine Mitbürger aber waren ihm feind; sie schickten ihm Gesandte nach und ließen sagen: \'Den wollen wir nicht zu unserem Könige haben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Doch als er nach erlangter Königswürde zurückkehrte, ließ er die Knechte, denen er das Geld gegeben hatte, rufen, um zu erfahren, was ein jeder für Geschäfte gemacht habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Der erste kam und sprach: \'Herr, deine Mine hat noch zehn Minen hinzugewonnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Er sprach zu ihm: \'Recht so, guter Knecht, weil du im Geringen getreu gewesen bist, sollst du Herr sein über zehn Städte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Der zweite kam und sprach: \'Herr, deine Mine hat noch fünf Minen hinzugewonnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Zu diesem sprach er gleichfalls: \'Auch du sollst über fünf Städte gebieten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Ein dritter kam und sagte: Herr, siehe, da ist deine Mine; ich habe sie im Schweißtuch aufbewahrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Ich hatte Angst vor dir; du bist ein strenger Mann, du erhebst, wo du nicht angelegt, und erntest, wo du nicht gesät hast.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Er sprach zu ihm: \'Mit deinen eigenen Worten will ich dich verdammen, nichtswürdiger Knecht! Du hast gewußt, daß ich ein strenger Mann bin, daß ich erhebe, wo ich nicht angelegt, und ernte, wo ich nicht gesät habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Warum hast du mein Geld nicht auf die Bank gebracht? Dann hätte ich es bei meiner Rückkehr mit Zinsen abheben können.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, '\'Nehmt ihm die Mine\', sagte er zu den Umstehenden, \'und gebt sie dem, der die zehn Minen hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Doch diese sagten zu ihm: \'Herr, er hat ja schon zehn Minen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '\'Ich sage euch: Jedem, der hat, dem wird gegeben werden; wer aber nicht hat, dem wird auch das genommen werden, was er besitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Doch jene, meine Feinde, die nicht wollten, daß ich König sei, bringt her und haut sie vor meinen Augen nieder!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Nach diesen Worten ging er wiederum voran und zog nach Jerusalem hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'So kam er in die Nähe von Bethphage und Bethanien am sogenannten Ölberg. Er sandte zwei von seinen Jüngern mit dem Auftrag fort:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, '\"Geht in das Dorf, das vor euch liegt. Am Eingang findet ihr ein Füllen angebunden, worauf noch niemals jemand saß. Bindet dieses los und bringt es her!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Und sollte jemand zu euch sagen: \'Warum bindet ihr es los?\', dann saget: \'Weil der Herr es braucht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Die Abgesandten gingen hin und fanden es so, wie er es ihnen gesagt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Als sie das Füllen losbanden, da fragte sie dessen Eigentümer: \"Warum bindet ihr das Füllen los?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Sie sprachen: \"Weil der Herr es braucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Sie führten es zu Jesus und legten ihre Kleider auf das Füllen und hoben Jesus hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Und wie er so dahinzog, breiteten sie ihre Kleider auf den Weg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Schon war er nahe der Stelle, wo es am Ölberg abwärts geht, da begann die ganze Jüngerschar voll Freude mit lauter Stimme Gott zu preisen wegen all der Wundertaten, die sie gesehen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Sie riefen: \"Gepriesen sei der König, der im Namen des Herrn kommt. Friede ist im Himmel, Ehre in der Höhe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Doch einige der Pharisäer, die in der Menge waren, sagten ihm: \"Meister, wehre deinen Jüngern!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Er aber sprach: \"Ich sage euch: Wenn diese schweigen, werden die Steine schreien.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Als er sich der Stadt näherte und diese vor sich liegen sah, weinte er über sie');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'und sprach: \"Wenn doch auch du erkanntest, und zwar an diesem deinem Tage, was dir zum Frieden dient! So aber ist es vor deinen Augen verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Es werden Tage über dich kommen, da deine Feinde rings um dich her einen Wall aufwerfen, dich ringsum einschließen und dich von allen Seiten bedrängen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Sie werden dich und deine Kinder in deinen Mauern auf den Boden schmettern und keinen Stein in dir auf dem anderen lassen, weil du die Zeit deiner Heimsuchung nicht erkannt hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Dann ging er in den Tempel und trieb die Händler hinaus, wobei er ihnen zurief:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, '\"Es steht geschrieben: \'Mein Haus soll ein Bethaus sein\'; \'doch ihr habt eine Räuberhöhle daraus gemacht.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Er lehrte täglich im Tempel. Die Oberpriester und die Schriftgelehrten und auch die Führer des Volkes trachteten ihm nach dem Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Doch konnten sie ihm nichts anhaben; das ganze Volk hing ja an ihm, wenn es ihn hörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Und eines Tages, als er das Volk im Tempel lehrte und die frohe Botschaft verkündete, näherten sich ihm die Oberpriester und die Schriftgelehrten sowie die Ältesten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'und fragten ihn: \"Sag uns: Mit welcher Vollmacht tust du dies? Oder wer hat dir das Recht dazu gegeben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Er aber sprach zu ihnen: \"Auch ich will euch etwas fragen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Sagt mir: Ist die Taufe des Johannes vom Himmel gekommen oder von den Menschen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Da überlegten sie bei sich: \"Sagen wir: \'vom Himmel\', so wird er fragen: \'Warum habt ihr ihm dann nicht geglaubt?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Und sagen wir: \'von Menschen\', dann wird das ganze Volk uns steinigen; es ist ja überzeugt, daß Johannes ein Prophet war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Da gaben sie ihm zur Antwort, sie wüßten nicht, woher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Und Jesus sprach zu ihnen: \"Dann sage auch ich euch nicht, mit welcher Vollmacht ich dies tue.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Er trug darauf dem Volke dieses Gleichnis vor: \"Jemand pflanzte einen Weinberg und gab ihn an Winzer in Pacht. Dann ging er geraume Zeit außer Landes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Als die Zeit gekommen, schickte er einen Knecht zu den Winzern, sie sollten ihm den Anteil vom Ertrag des Weinbergs abliefern. Jedoch die Winzer schlugen ihn und schickten ihn mit leeren Händen heim');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Da schickte er noch einen zweiten Knecht, jedoch auch diesen schlugen sie, beschimpften ihn und jagten ihn mit leeren Händen fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Er schickte dann noch einen dritten; diesen schlugen sie sogar blutig und warfen ihn hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Da sprach der Herr des Weinbergs: \'Was fange ich nun an? Ich will meinen lieben Sohn hinschicken; vor diesem werden sie wohl Achtung haben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Doch als die Winzer ihn erblickten, besprachen sie sich und sagten: \'Das ist der Erbe. Laßt uns ihn töten; dann gehört das Erbe uns.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Sie warfen ihn zum Weinberg hinaus und brachten ihn ums Leben. Was wird nun wohl der Herr des Weinbergs mit ihnen tun?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Er wird kommen und die Winzer töten und seinen Weinberg anderen verpachten.\" Als sie dies hörten, sagten sie: \"Möge solches nimmermehr geschehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Er aber blickte sie fest an und sprach: \"Was bedeutet denn das Schriftwort: \'Der Stein, den die Bauleute verworfen haben, ist zum Schlußstein geworden\'?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Jeder, der auf diesen Stein auffällt, wird zerschmettert werden; auf wen er aber fällt, den wird er zermalmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Die Schriftgelehrten und die Oberpriester suchten noch in derselben Stunde Hand an ihn zu legen, allein sie fürchteten das Volk. Sie hatten nämlich erkannt, daß dieses Gleichnis ihnen gelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Sie ließen ihn nun scharf beobachten und schickten Späher aus, die sich den Schein rechtschaffener Leute geben sollten, damit sie ihn an einem Worte fassen könnten. Dann wollten sie ihn der Obrigkeit und der Gewalt des Statthalters ausliefern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Sie fragten ihn: \"Meister, wir wissen, du redest und lehrst recht; du siehst nicht auf die Stellung der Menschen und lehrst Gottes Weg in Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Ist es uns erlaubt, daß wir dem Kaiser Steuer zahlen oder nicht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Doch er durchschaute die Arglist und sprach zu ihnen: Warum versucht ihr mich?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '\"Zeigt mir einen Denar! Wessen Bild und Zeichen trägt er?\" Sie gaben ihm zur Antwort: \"Das des Kaisers.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Da sagte er zu ihnen: \"So gebt dem Kaiser, was des Kaisers, und Gott, was Gottes ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Und so gelang es ihnen nicht, ihn in einem Ausspruch vor dem Volke zu fassen. Und sie schwiegen voll Verwunderung über seine Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Dann kamen einige aus den Sadduzäern - diese leugnen, daß es eine Auferstehung gebe -.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Sie fragten ihn: \"Meister, bei Moses steht geschrieben: \'Wenn der Bruder irgendjemands stirbt, der zwar ein Weib, doch keine Kinder hatte, dann soll der Bruder dessen Weib heiraten und seinem Bruder Nachkommen erwecken.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Da waren sieben Brüder. Der erste nahm ein Weib, doch er starb kinderlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Darauf nahm sie der zweite');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'und ebenso der dritte, schließlich alle sieben; sie starben alle, ohne daß sie Kinder hinterlassen hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Zuletzt starb auch das Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Wessen Weib wird sie nun bei der Auferstehung sein? Denn alle sieben haben sie zum Weib gehabt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Und Jesus sprach zu ihnen: \"Die Kinder dieser Welt heiraten und werden verheiratet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Die aber, die jener Welt und der Auferstehung von den Toten gewürdigt werden, heiraten nicht und werden nicht verheiratet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Auch können sie dann nicht mehr sterben, sie sind engelgleich und Kinder Gottes, weil sie Kinder der Auferstehung sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Daß aber die Toten wirklich auferstehen, das hat auch Moses angedeutet an der Stelle vom Dornbusch, wo er den Herrn den Gott Abrahams, den Gott Isaaks und den Gott Jakobs nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Gott ist kein Gott der Toten, sondern der Lebendigen; denn alle leben für ihn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Da sagten einige der Schriftgelehrten: \"Meister, du hast gut gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Sie wagten es von nun an nicht mehr, ihm eine Frage vorzulegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Und er fragte sie: \"Wie kann man sagen, Christus sei der Sohn Davids?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Sagt David selber doch im Buche der Psalmen: \'Es sprach der Herr zu meinem Herrn:  ́Setze dich zu meiner Rechten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'bis ich deine Feinde als Schemel dir zu Füßen lege.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'So nennt ihn David also \'Herr\'; wie kann er alsdann sein Sohn sein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Und während noch das ganze Volk zuhörte, sagte er zu seinen Jüngern:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '\"Hütet euch vor den Schriftgelehrten. Sie lieben es, in langen Kleidern einherzugehen, auf den öffentlichen Plätzen gegrüßt zu werden, die Ehrensitze in den Synagogen einzunehmen und bei Mählern die Ehrenplätze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Sie verprassen die Häuser der Witwen und sagen nur zum Schein dafür lange Gebete her. Eine furchtbare Strafe erwartet diese.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Und als er aufblickte, sah er, wie Reiche ihre Gaben in den Opferkasten warfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Er sah auch, wie eine arme Witwe nur zwei Heller einwarf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Er sprach: \"Wahrhaftig sage ich euch: Diese bettelarme Witwe hat mehr als alle anderen hineingeworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Denn alle anderen warfen nur von ihrem Überfluß zu den Gaben Gottes ein, sie aber gab von ihrer Armut alles, was sie zum Leben hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Als einige vom Tempel sagten, er sei mit kostbaren Steinen und mit Weihgeschenken geschmückt, da sprach er:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '\"Es werden Tage kommen, da von dem, was ihr hier seht, kein Stein mehr auf dem anderen bleibt, der nicht abgebrochen werden wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Da fragten sie ihn: \"Meister, wann wird dies geschehen, und welches wird das Zeichen sein, wann dies zu geschehen anfängt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Da sagte er: \"Seht zu, daß euch niemand verführe. Viele werden unter meinem Namen kommen und behaupten: \'Ich bin es; gekommen ist die Zeit.\' Lauft ihnen ja nicht nach!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Wenn ihr von Krieg und Umsturz hört, dann laßt euch nicht erschrecken. Denn dies muß zuerst geschehen, jedoch ist das Ende noch nicht gleich da.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Und er fuhr fort: \"Volk wird sich gegen Volk erheben und Reich gegen Reich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Gewaltige Erdbeben, Pest und Hunger wird es an vielen Orten geben. Schreckbilder und fürchterliche Zeichen werden am Himmel erscheinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Vor all dem aber wird man an euch Hand anlegen; man wird euch verfolgen, euch an die Synagogen und Gefängnisse überliefern, vor Könige und Statthalter euch schleppen um meines Namens willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Doch dies wird euch zum Zeugnis werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Dann nehmt euch vor, nicht schon im voraus euch zu sorgen, wie ihr euch verteidigen werdet;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'ich werde euch Beredsamkeit und Weisheit geben, der von allen euren Gegnern keiner widerstehen noch widersprechen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Ihr werdet sogar von Eltern und Brüdern ausgeliefert werden und von Verwandten und Freunden, und manche aus euch wird man töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Von allen werdet ihr um meines Namens willen gehaßt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Und doch soll euch nicht ein Haar von eurem Haupte verlorengehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Wenn ihr standhaft bleibt, werdet ihr euer Leben gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Wenn ihr Jerusalem von Heeren umlagert seht, dann erkennt, daß seine Verödung sich genaht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Dann fliehe, wer in Judäa ist, ins Gebirge, wer in der Stadt ist, gehe fort, und wer auf dem Lande ist, gehe nicht in die Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Denn das sind die Tage der Rache, da alles in Erfüllung gehen soll, was geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Doch wehe den Frauen, die in jenen Tagen ein Kindlein unterm Herzen oder an der Brust tragen. Denn große Drangsal wird im Lande herrschen, und ein Gericht des Zornes wird dieses Volk treffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Sie werden durch die Schärfe des Schwertes fallen und in Gefangenschaft zu allen Heidenvölkern geführt werden. Jerusalem wird von den Heiden zertreten werden, bis die Zeiten der Heiden abgelaufen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'An Sonne, Mond und Sternen werden Zeichen sein; auf Erden Angst, Bestürzung bei den Völkern ob des Tosens und Brausens der Meereswogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Die Menschen werden vergehen vor Bangen in Erwartung dessen, was über den Erdkreis kommen soll. Die Kräfte des Himmels werden erschüttert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Man wird den Menschensohn auf einer Wolke mit Macht und großer Herrlichkeit kommen sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Wenn dieses anfängt zu geschehen, dann richtet euch auf, erhebt eure Häupter: Eure Erlösung naht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Und er erzählte ihnen noch ein Gleichnis: \"Betrachtet den Feigenbaum und alle anderen Bäume!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Wenn ihr wahrnehmt, daß sie ausschlagen, so wisset ihr von selbst, daß der Sommer nahe ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'So sollt ihr, wenn ihr all dies geschehen seht, auch erkennen, daß das Reich Gottes nahe ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Wahrlich, ich sage euch: Dieses Geschlecht wird nicht vergehen, bis all dies geschehen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Himmel und Erde werden vergehen, doch meine Worte werden nicht vergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'So hütet euch, mit Schwelgen, mit Trunkenheit und mit irdischen Sorgen euer Herz zu belasten, so daß jener Tag unvermutet euch überfalle');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'gleichwie eine Schlinge. Er wird über alle kommen, die irgendwo auf der ganzen Erde wohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'So seid denn allezeit wachsam und betet, daß ihr imstande seid, all dem, was kommen wird, zu entgehen und vor dem Menschensohn zu erscheinen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Tagsüber lehrte er im Tempel; des Abends ging er dann hinaus und übernachtete auf dem sogenannten Ölberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'In der Morgenfrühe strömte alles Volk zu ihm in den Tempel, um ihn zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Der Festtag der Ungesäuerten Brote, den man Paschah heißt, war nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Die Oberpriester und die Schriftgelehrten suchten nach einer passenden Gelegenheit, wie sie Jesus töten könnten; allein sie fürchteten das Volk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Da fuhr Satan in Judas, der Iskariot heißt; er gehörte zu der Zahl der Zwölf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Er ging hin und verhandelte mit den Oberpriestern und den Hauptleuten, wie er ihn an sie überliefern könnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Und diese freuten sich und wurden einig, ihm Geld zu bieten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Er sagte zu und suchte eine günstige Gelegenheit, ihn unauffällig an sie auszuliefern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Es kam der Tag der Ungesäuerten Brote, an dem man das Osterlamm zu schlachten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Er sandte Petrus und Johannes mit dem Auftrag fort: \"Geht und bereitet uns das Ostermahl, daß wir es essen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Sie fragten ihn: \"Wo willst du, daß wir es bereiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Er sprach zu ihnen: \"Seht, wenn ihr in die Stadt kommt, wird euch ein Mann mit einem Wasserkrug begegnen. Folgt ihm in das Haus, in das er geht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'und sagt zu dem Herrn des Hauses: \'Der Meister läßt dich fragen: Wo ist das Gemach, in dem ich mit meinen Jüngern das Ostermahl halten kann?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Er wird euch ein großes Obergemach zeigen, das mit Polstern ausgestattet ist, daselbst bereitet es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Sie gingen weg und fanden es so, wie er ihnen gesagt hatte, und sie bereiteten das Ostermahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Als dann die Stunde gekommen war, setzte er sich mit den zwölf Aposteln zu Tisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Er sprach zu ihnen: \"Sehnlichst hat es mich danach verlangt, dieses Ostermahl mit euch zu halten, bevor ich leide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Ich sage euch: Ich werde es nicht mehr essen, bis es erfüllt ist im Reiche Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Dann nahm er einen Kelch, dankte und sprach: \"Nehmt hin und teilt ihn unter euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Ich sage euch: Von jetzt an werde ich nicht mehr von dem Gewächs des Weinstocks trinken, bis das Reich Gottes kommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Dann nahm er Brot, dankte, brach es und gab es ihnen mit den Worten: \"Das ist mein Leib, der für euch hingegeben wird. Tut dies zu meinem Andenken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Desgleichen nahm er nach dem Mahle auch den Kelch und sprach: \"Dies ist der Kelch, der Neue Bund in meinem Blute, das für euch vergossen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Doch seht: Die Hand des Verräters ist mit mir auf dem Tische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Der Menschensohn geht zwar hin, wie es bestimmt ist, doch wehe jenem Menschen, durch den er verraten wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Da fragten sie einander, wer aus ihnen der sein könnte, der das tun wolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Auch gab es bei ihnen Streit darüber, wer unter ihnen der Größte sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Er sprach zu ihnen: \"Die Könige der Heidenvölker wollen über sie den Herrn spielen; ihre Mächtigen lassen sich \'Wohltäter\' nennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Bei euch soll es aber nicht so sein; vielmehr der Größte unter euch soll wie der Jüngste, der Vorsteher wie der Diener werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Wer ist denn größer? Der zu Tische sitzt oder der aufwartet? Doch wohl der, der zu Tische sitzt. Ich aber bin bei euch als Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Ihr habt in meinen Prüfungen mit mir ausgeharrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Und so bestimme ich euch das Reich, so wie mein Vater es mir bestimmt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Ihr sollt in meinem Reich an meinem Tisch essen und trinken; ihr sollt auf Thronen sitzen und die zwölf Stämme Israels regieren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Der Herr fuhr fort: \"Simon, Simon, siehe, der Satan hat verlangt, daß er euch sieben dürfe wie Weizen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Ich aber habe für dich gebetet, daß dein Glaube nicht versage. Du hinwieder stärke, wenn du dich wiedergefunden hast, deine Brüder.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Dieser sprach zu ihm: \"Herr, ich bin bereit, mit dir in den Kerker und in den Tod zu gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Doch er entgegnete: \"Ich sage dir, Petrus, heute nacht noch, vor dem Hahnenschrei, wirst du es dreimal geleugnet haben, mich zu kennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Alsdann sprach er zu ihnen: \"Als ich euch aussandte ohne Beutel, ohne Sack und Schuhe, habt ihr an irgend etwas Mangel leiden müssen?\" Sie erwiderten: \"Nein, an nichts.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, '\"Nun aber\", fuhr er fort, \"soll der, der einen Beutel hat, ihn an sich nehmen, desgleichen auch, wer einen Sack besitzt; wer aber das nicht hat, verkaufe seinen. Mantel und kaufe sich dafür ein Schwert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Ich sage euch: An mir muß das Schriftwort erfüllt werden: \'Er wird den Übeltätern zugerechnet.\' Mit mir geht es zu Ende\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Da sagten sie: \"Sieh, Herr, hier sind zwei Schwerter.\" \"Genug hiervon\", antwortete er ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Danach ging er hinaus und begab sich wie gewöhnlich an den Ölberg. Und seine Jünger folgten ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Als er dort ankam, sagte er zu ihnen: \"Betet, damit ihr nicht in Versuchung fallet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Alsdann ging er von ihnen etwa einen Steinwurf weit hinweg und kniete nieder und betete:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '\"Vater, wenn du diesen Kelch an mir vorübergehen lassen wolltest. - Jedoch nicht mein Wille geschehe, sondern der deine.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Da erschien ihm ein Engel vom Himmel und stärkte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Als er sodann innerlich mit sich rang, betete er noch inniger. Sein Schweiß glich Blutstropfen, die auf die Erde rieselten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Dann stand er vom Gebet auf und ging zu seinen Jüngern und fand sie vor Traurigkeit schlafend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Er sprach zu ihnen: \"Wie, ihr schlaft? Steht auf und betet, damit ihr nicht in Versuchung fallt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Noch sprach er so, als schon ein Haufe kam, und einer von den Zwölfen, Judas, ging vor ihnen her. Er schritt auf Jesus zu, um ihn zu küssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Und Jesus sprach zu ihm: \"Judas, mit einem Kusse verrätst du den Menschensohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Als die, die bei ihm waren, sahen, was da kommen werde, riefen sie: \"Herr, sollen wir mit dem Schwerte dreinschlagen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Und einer aus ihnen schlug nach einem Knecht des Hohenpriesters und hieb ihm das rechte Ohr ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Doch Jesus sprach: \"Laßt ab! Nicht weiter!\" Alsdann berührte er das Ohr und heilte es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Und Jesus sprach zu den Oberpriestern und zu den Hauptleuten der Tempelwache und zu den Ältesten, die an ihn herangetreten waren: \"Wie gegen einen Räuber seid ihr ausgezogen mit Schwertern und mit Prügeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Tag für Tag war ich bei euch im Tempel, und dennoch habt ihr nicht Hand an mich gelegt. Doch dies ist eure Stunde und die Macht der Finsternis.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Sie nahmen ihn gefangen und führten ihn hinweg und brachten ihn in das Haus des Hohenpriesters. Und Petrus folgte ihm von fern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Man hatte mitten in dem Hof ein Feuer angezündet und sich ringsum gesetzt. Auch Petrus setzte sich hinzu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Da sah ihn, wie er im Lichtschein dasaß, eine Magd; sie blickte ihn scharf an und sprach: \"Der da war auch bei ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Er leugnete und sprach: \"Weib, ich kenne ihn nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Doch kurz darauf erblickte ihn jemand anders und sagte: \"Auch du gehörst zu ihnen.\" Und Petrus sprach: \"Nein, Mensch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Nach einer Stunde ungefähr versicherte ein anderer: \"Wahrhaftig, der war auch bei ihm; er ist ein Galiläer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, '\"Mensch, ich begreife nicht, was du sagst\", sprach Petrus. Da, wie er noch am Reden war, krähte schon ein Hahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Jetzt wandte sich der Herr um und blickte Petrus an. Und nun erinnerte sich Petrus an das Wort des Herrn, wie er zu ihm gesagt hatte: \"Noch vor dem Hahnenschrei wirst du mich heute dreimal verleugnet haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Und er ging hinaus und weinte bitterlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Die Männer, die ihn gefangenhielten, verspotteten und schlugen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Sie verhüllten ihn und fragten: \"Sag an, wer ist es, der dich geschlagen hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Sie stießen wider ihn noch viele andere Lästerungen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Als es Tag geworden war, versammelten sich die Ältesten des Volkes, die Oberpriester und die Schriftgelehrten; sie ließen ihn in ihren Sitzungssaal bringen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'und sprachen: \"Wenn du der Christus bist, alsdann sage es uns.\" Er sprach zu ihnen: \"Wenn ich es euch sagen würde, würdet ihr dennoch nicht glauben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'wenn ich euch fragen würde, so würdet ihr mir keine Antwort geben und mich nicht freilassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Von nun an aber wird der Menschensohn zur Rechten des allmächtigen Gottes sitzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Da fragten alle: \"Also bist du der Sohn Gottes?\" Er sprach zu ihnen: \"Ihr sagt, daß ich es bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Und sie erwiderten. \"Wozu brauchen wir ein Zeugnis? Wir selbst haben es aus seinem eigenen Munde vernommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Da erhob sich die ganze Schar und führte ihn zu Pilatus und begann, ihn anzuklagen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, '\"Wir fanden, daß er unser Volk aufwiegelt, denn er verbietet, dem Kaiser Steuern zu bezahlen, und gibt sich für den Christus, für den König aus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Da fragte ihn Pilatus: \"Bist du der König der Juden?\" Er sprach zu ihm: \"Das sagst nur du.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus sprach zu den Oberpriestern und der Menge: \"Ich finde keine Schuld an diesem Menschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Da riefen sie noch ungestümer: \"Er bringt das Volk in Aufruhr dadurch, daß er im ganzen Judenlande lehrt, von Galiläa an bis hierher.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Als dies Pilatus hörte, fragte er, ob dieser Mensch ein Galiläer sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Als er vernahm, er sei aus dem Gebiete des Herodes, schickte er ihn zu Herodes, der sich in jenen Tagen gleichfalls in Jerusalem aufhielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Herodes freute sich sehr, als er Jesus sah. Denn längst hätte er ihn gern gesehen, weil er von ihm gehört hatte und hoffte, eine Wundertat von ihm zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Er richtete an ihn viele Fragen. Doch Jesus gab ihm keine Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Die Oberpriester aber und die Schriftgelehrten standen nahe dabei und klagten ihn leidenschaftlich an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Herodes aber verhöhnte ihn samt seinem Gefolge. Zum Spott ließ er ihm ein weißes Kleid anziehen und schickte ihn so dem Pilatus zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'An demselben Tage wurden Herodes und Pilatus Freunde; denn vorher waren sie einander feind gewesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilatus ließ darauf die Oberpriester, die Mitglieder des Hohen Rates und das Volk zusammenrufen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'und sprach zu ihnen: \"Ihr habt mir diesen Mann gebracht, weil er das Volk aufwiegeln soll. Doch seht, ich habe ihn in eurer Gegenwart verhört, allein keine einzige eurer Anklagen gegen diesen Mann begründet gefunden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Herodes gleichfalls nicht; denn er hat ihn wieder zu uns zurückgesandt. Seht, nichts, was den Tod verdienen würde, ward ihm nachgewiesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'So will ich ihn denn züchtigen lassen und dann freigeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Er mußte nämlich auf den Festtag ihnen einen Gefangenen freigeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Doch alsbald schrie der ganze Haufen: \"Hinweg mit dem! Gib uns den Barabbas frei!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Dieser lag gefangen wegen eines Aufruhrs in der Stadt und wegen eines Totschlags.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilatus redete ihnen nochmals zu; denn er wollte Jesus freigeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Doch diese schrien: \"Ans Kreuz! Ans Kreuz mit ihm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Und er fragte sie zum drittenmal: \"Was hat er denn Böses getan? Ich finde nichts an ihm, was den Tod verdienen würde. Ich will ihn also züchtigen lassen und dann freigeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Sie aber forderten nur noch ungestümer mit lautem Schreien seine Kreuzigung, und ihr Geschrei drang durch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Darauf entschied Pilatus, ihr Verlangen solle erfüllt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Dann gab er ihnen den frei, der des Aufruhrs und des Totschlages wegen im Gefängnis lag, und den sie sich gefordert hatten; Jesus aber gab er ihrem Willen preis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Als sie ihn abführten, hielten sie einen gewissen Simon von Cyrene, der vom Felde kam, an und beluden ihn mit dem Kreuze, daß er es Jesu nachtrage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Eine große Menge Volkes lief hintendrein, auch Frauen, die ihn beweinten und beklagten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Und Jesus wandte sich zu ihnen um und sprach: \"Ihr Töchter Jerusalems, weint nicht über mich, weint über euch und eure Kinder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Seht, es kommen Tage, da man sagen wird: \'Selig sind die Unfruchtbaren, deren Schoß nicht geboren und deren Brust nicht genährt hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Da wird man zu den Bergen sagen: \'Fallet über uns!\' und zu den Hügeln: \'Bedecket uns!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Wenn dies am grünen Holze geschieht, was wird dann am dürren geschehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Auch zwei Verbrecher führte man mit ihm zur Hinrichtung hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Als sie an den Ort, der Schädelstätte heißt, gekommen waren, schlugen sie ihn ans Kreuz, desgleichen die Verbrecher, den einen zu seiner Rechten und den anderen zu seiner Linken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Und Jesus betete: \"Vater, vergib ihnen, sie wissen nicht, was sie tun.\" Alsdann verteilten sie seine Kleider unter sich, indem sie das Los darüber warfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Das Volk stand da und schaute zu. Da spotteten auch die Mitglieder des Hohen Rates: \"Andere hat er gerettet; er rette sich nun selber, wenn er der Christus Gottes, der Auserwählte, ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Auch die Soldaten höhnten ihn. Sie traten her, reichten ihm Essig und sagten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, '\"Wenn du der König der Juden bist, so rette dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Und über ihm war eine Inschrift in griechischen, lateinischen und hebräischen Buchstaben: \"Der Judenkönig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Auch einer der Verbrecher, die am Kreuze hingen, lästerte ihn: \"Bist du nicht der Messias? Rette dich und uns!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Der andere indes verwies es ihm und sprach: \"Fürchtest auch du Gott nicht, obwohl du selbst die gleiche Strafe leidest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Wir allerdings mit Recht; denn wir empfangen die gerechte Strafe für unsere Taten, doch dieser hat nichts Böses getan.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Er bat: \"Jesus, gedenke meiner, wenn du in deiner Königsherrlichkeit erscheinst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Er sprach zu ihm: \"Wahrlich, ich sage dir: Heute noch wirst du mit mir im Paradiese sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Es war ungefähr um die sechste Stunde, da legte sich auf das ganze Land eine Finsternis, die bis zur neunten Stunde dauerte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'weil die Sonne sich verfinsterte. Der Vorhang im Tempel riß entzwei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Und Jesus rief mit lauter Stimme: \"Vater, in deine Hände empfehle ich meinen Geist.\" Nach diesen Worten verschied er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Als der Hauptmann sah, was geschehen war, gab er Gott die Ehre und sprach: \"Wahrhaftig, dieser Mensch war gerecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Und alles Volk, das bei dem Schauspiel zugegen war und diese Vorgänge mitangesehen hatte, schlug an seine Brust und kehrte heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'In einiger Entfernung standen alle seine Bekannten sowie die Frauen, die ihm aus Galiläa gefolgt waren, und sahen dies mit an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Siehe, ein Ratsherr, namens Joseph, ein edler und rechtschaffener Mann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '-er hatte ihrem Plan und Vorgehen nicht zugestimmt; er stammte aus Arimathäa, einer Stadt in Judäa, und erwartete das Reich Gottes-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'ging zu Pilatus und bat um den Leichnam Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Dann nahm er ihn herab und hüllte ihn in Leinwand und legte ihn in ein Felsengrab, in dem noch niemand gelegen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Es war der Rüsttag, und eben brach der Sabbat an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Die Frauen, die mit Jesus aus Galiläa gekommen waren, gingen mit und sahen sich das Grab, und wie sein Leichnam bestattet wurde, mit an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Dann kehrten sie zurück und richteten sich Spezereien und Salben her. Den Sabbat brachten sie nach dem Gesetz in Stille zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Am ersten Tage der Woche gingen sie sodann in aller Frühe zum Grabe hinaus und nahmen die Spezereien mit, die sie sich zubereitet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Da fanden sie den Stein vom Grabe weggewälzt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'sie gingen hinein, doch fanden sie den Leichnam des Herrn Jesus nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Sie waren darüber tief bestürzt. Und plötzlich standen vor ihnen zwei Männer in glänzend weißen Kleidern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Und sie erschraken und senkten ihre Blicke zu Boden. Diese aber fragten sie: \"Was sucht ihr den Lebendigen bei den Toten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Er ist nicht hier; er ist auferstanden. Erinnert euch doch, wie er zu euch gesagt hat, als er in Galiläa war:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, '\'Der Menschensohn\', sagte er, \'muß in die Hände sündiger Menschen ausgeliefert und gekreuzigt werden, am dritten Tage aber auferstehen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Da erinnerten sie sich an seine Worte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'kehrten vom Grabe zurück und sagten all das den Elfen und allen anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Es waren Maria Magdalena und Johanna, Maria, des Jakobus Mutter, und noch andere, die bei ihnen waren; diese brachten den Aposteln diese Nachricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Doch wie ein leeres Gerede kam ihnen diese Kunde vor; sie glaubten ihnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Darauf erhob sich Petrus, um zum Grabe zu eilen. Als er sich vorneigte, sah er nur die Linnentücher. Voll Staunen über das, was vorgefallen war, ging er nach Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Und siehe, am selben Tage wanderten zwei von ihnen in einen Flecken namens Emmaus. Er liegt etwa sechzig Stadien von Jerusalem entfernt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Sie unterhielten sich miteinander über alles, was sich zugetragen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Während sie sich so miteinander unterhielten und besprachen, da nahte sich Jesus und ging mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Doch ihre Augen waren gebannt, daß sie ihn nicht erkannten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Er fragte sie: \"Was sind das für Reden, die ihr auf dem Weg miteinander führet?\" Da hielten sie traurig inne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Der eine namens Kleophas gab ihm zur Antwort: \"Bist du allein in Jerusalem so fremd, daß du nicht weißt, was dort in diesen Tagen geschehen ist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Er fragte sie: \"Was denn?\" Sie sagten zu ihm: \"Das mit Jesus von Nazareth. Er war ein Prophet, mächtig in Tat und Wort vor Gott und vor dem ganzen Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Unsere Oberpriester und der Hohe Rat haben ihn der Todesstrafe überliefert und gekreuzigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Wir aber hatten gehofft, daß er es sei, der Israel erlösen werde. Und heute ist schon der dritte Tag, seitdem dies geschehen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Zwar haben einige von unseren Frauen uns verwirrt. Sie waren schon sehr früh zum Grabe hinausgegangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'doch fanden sie den Leichnam nicht; sie kamen vielmehr und erzählten, es seien ihnen Engel erschienen, die versichert hätten, daß er lebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Da gingen einige der Unsrigen ans Grab und fanden es so, wie die Frauen gesagt hatten. Ihn selber aber sahen sie nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Darauf sprach er zu ihnen: \"Ihr Unverständigen, wie seid ihr doch so schwerfällig, um an das zu glauben, was die Propheten gesagt haben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Mußte denn nicht der Christus solches erleiden und so in seine Herrlichkeit eingehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Dann fing er mit Moses an und mit all den Propheten und erklärte ihnen, was in allen Schriften von ihm geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'So kamen sie nahe an das Dorf, wohin sie gehen wollten. Er tat, als ob er weitergehen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Jedoch sie nötigten ihn mit den Worten: \"Bleibe bei uns; es wird Abend; der Tag hat sich schon geneigt.\" Er kehrte ein und blieb bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Und wie er mit ihnen am Tische saß, nahm er Brot, segnete, brach es und gab es ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Da wurden ihre Augen aufgetan, und sie erkannten ihn. Doch da entschwand er ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Sie sagten zueinander: \"Brannte nicht das Herz in uns, wie er unterwegs mit uns redete und uns die Schrift erschloß?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Noch in derselben Stunde machten sie sich auf den Weg und kehrten nach Jerusalem zurück; sie trafen die Elf und die anderen Gefährten beieinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Diese sagten: \"Der Herr ist wahrhaft auferstanden und dem Simon erschienen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Nun erzählten auch sie, was sich auf dem Wege zugetragen und wie sie ihn am Brotbrechen erkannt hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Während sie noch davon erzählten, stand Jesus mitten unter ihnen. Er sprach zu ihnen: \"Friede sei mit euch!\" Ich bin es, fürchtet euch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Vor Angst und Schrecken glaubten sie, ein Gespenst zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Er aber sprach zu ihnen: \"Weshalb seid ihr erschrocken und steigen Zweifel euch im Herzen auf?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Seht meine Hände und meine Füße, daß ich es bin. Betastet mich und überzeugt euch: Ein Gespenst hat doch nicht Fleisch und Bein, wie ihr an mir es sehet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Nach diesen Worten zeigte er ihnen seine Hände und seine Füße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Allein, vor Freude und Staunen konnten sie es immer noch nicht glauben. So fragte er sie dann: \"Habt ihr etwas zum Essen da?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Sie reichten ihm ein Stück gebratenen Fisches und eine Honigwabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Er nahm es und aß vor ihren Augen. Als er vor ihnen gegessen hatte, verteilte er die Überreste unter sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Alsdann sprach er zu ihnen: \"Das waren meine Worte, die ich zu euch geredet habe, als ich noch bei euch war: Alles muß sich erfüllen, was im Gesetz des Moses, bei den Propheten und in den Psalmen über mich geschrieben steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Darauf erschloß er ihren Sinn, damit sie die Schriften verstanden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'und fuhr fort: \"So steht geschrieben, und so mußte Christus leiden und am dritten Tage von den Toten auferstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'In seinem Namen soll nun allen Völkern Buße und Vergebung der Sünden verkündet werden. Beginnet mit Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Ihr seid von alledem ja Zeugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Seht, ich sende den auf euch herab, den mein Vater verheißen hat. Bleibt in der Stadt, bis ihr mit Kraft von oben umkleidet seid.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Er führte sie sodann bis nach Bethanien hinaus und erhob segnend seine Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Und segnend schied er von ihnen und fuhr zum Himmel auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Sie fielen vor ihm nieder und kehrten dann mit großer Freude nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Beständig weilten sie im Tempel, lobten Gott und priesen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Im Anfang war das Wort, und das Wort war bei Gott, und Gott war das Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Dieses war im Anfang bei Gott;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'alles ist durch es geworden, und nichts von dem, was geworden ist, ward ohne dieses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'In ihm war Leben, und das Leben war das Licht der Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Das Licht leuchtet in der Finsternis, und die Finsternis hat es nicht begriffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Da war ein Mensch, ein Gottesbote; Johannes ist sein Name.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Der kam als Zeuge, zu künden von dem Lichte, damit alle durch ihn glauben sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Er selbst war nicht das Licht; nur künden sollte er vom Lichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Da kam das wahre Licht, das jeden Menschen erleuchtet, in diese Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Er war in der Welt; die Welt ist ja durch ihn gemacht; und doch hat die Welt ihn nicht erkannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Er kam in sein Eigentum, die Seinen aber nahmen ihn nicht auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Doch allen, die ihn aufnahmen, verlieh er Kraft, Kinder Gottes zu werden, denen, die an seinen Namen glauben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'die nicht aus dem Blute - aus Fleischeslust nicht, noch aus Manneswollen -, vielmehr aus Gott geboren sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Und das Wort ist Fleisch geworden und hat unter uns gewohnt. Wir haben seine Herrlichkeit gesehen, eine Herrlichkeit wie die eines Eingeborenen vom Vater, voll Gnade und Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes kündet ihn und ruft: \"Der war es, von dem ich sprach: Nach mir kommt einer, der vor mir ist; denn er war eher als ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Aus seiner Fülle haben wir alle empfangen: Gnade um Gnade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Durch Moses ward uns das Gesetz gegeben; doch Gnade und Wahrheit kamen durch Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Noch nie hat jemand Gott geschaut; ein eingeborener Gott, der am Herzen des Vaters ruht, hat ihn geoffenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Dies ist das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten zu ihm sandten, damit sie ihn fragen sollten: \"Wer bist du denn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Und er bekannte ohne Leugnen und beteuerte: \"Ich bin nicht Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Da fragten sie ihn weiter: \"Was nun, bist du Elias?\" Er gab zur Antwort: \"Nein.\" \"Bist du der Prophet?\" \"Nein\", sagte er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Da sprachen sie zu ihm: \"Wer bist du denn? Wir müssen denen, die uns sandten, Antwort bringen. Für wen gibst du dich aus?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Er sprach: \"Ich bin die Stimme, die in der Steppe ruft: \'Macht eben den Weg des Herrn!\', wie der Prophet Isaias gesagt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Es waren auch Abgesandte dabei aus den Pharisäern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Sie fragten ihn: \"Warum taufst du dann, wenn du nicht der Christus bist, noch Elias, noch der Prophet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johannes sagte ihnen: \"Ich taufe nur mit Wasser; doch mitten unter euch steht der, den ihr nicht kennt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'der nach mir kommt der vor mir war: Ich bin es nicht wert, ihm die Riemen seiner Schuhe aufzubinden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dies geschah zu Bethanien, jenseits des Jordans, wo Johannes taufte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Am Tag darauf sah er, wie Jesus auf ihn zukam; er sprach: \"Seht das Lamm Gottes, das hinwegnimmt die Sünden der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Er ist es, von dem ich gesagt habe: Nach mir kommt ein Mann, der vor mir ist; denn er war eher als ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Ich kannte ihn auch nicht, damit er jedoch in Israel offenbar würde, trat ich mit meiner Wassertaufe auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Und weiter bezeugte Johannes: \"Ich sah den Geist wie eine Taube aus dem Himmel niedersteigen und über ihm schweben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Auch ich kannte ihn nicht; doch der, der mich zur Wassertaufe gesandt hat, sagte mir: \'Auf den du den Geist niedersteigen und über ihm schweben siehst, der ist es, der mit Heiligem Geiste tauft.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Und das habe ich gesehen und bezeugt: Dieser ist der Sohn Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Des anderen Tages stand Johannes wieder da, samt zweien seiner Jünger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Und Jesus kam des Weges daher; er richtete seine Augen auf ihn und sprach: \"Seht das Lamm Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Die zwei Jünger hörten, was er sagte, und folgten Jesu nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Und Jesus wandte sich um und sah, daß sie ihm folgten. Da fragte er sie: \"Was suchet ihr?\" Sie sagten zu ihm: \"Rabbi - d.h. Meister -, wo wohnst du?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Er sagte ihnen: \"Kommt und seht!\" Sie gingen also mit und sahen, wo er wohnte, und blieben jenen Tag bei ihm. Es war um die zehnte Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andreas, der Bruder des Simon Petrus, war einer von den beiden, die dies von Johannes gehört hatten und ihm gefolgt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Gleich hernach traf er seinen Bruder Simon und sprach zu ihm: \"Wir haben den Messias - d.h. den Christus - gefunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Er führte ihn zu Jesus. Und Jesus schaute ihn an und sprach: \"Du bist Simon, der Sohn des Johannes; du wirst Kephas - d.h. Petrus - heißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Des anderen Tages wollte er nach Galiläa gehen; da traf er den Philippus. Und Jesus sprach zu ihm: \"Komm mit!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Philippus stammte aus Bethsaida, der Heimat des Andreas und des Petrus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus traf den Nathanael und sprach zu ihm: \"Den Mann, von dem Moses im Gesetze geschrieben hat und die Propheten, haben wir gefunden: Jesus aus Nazareth, den Sohn des Joseph!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Nathanael gab ihm zur Antwort: \"Kann denn aus Nazareth das Heil kommen?\" Philippus sagte ihm: \"Komm und sieh!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus sah den Nathanael, wie er zu ihm kam, und sprach von ihm: \"Seht da, ein echter Israelit, an dem nichts Falsches ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanael fragte ihn: \"Woher kennst du mich?\" Darauf gab ihm Jesus zur Antwort: \"Noch ehe dich Philippus rief, habe ich dich unter dem Feigenbaum gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Da sprach Nathanael zu ihm: \"Rabbi, du bist der Sohn Gottes, du bist der König Israels.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Und Jesus sprach zu ihm: \"Weil ich dir gesagt habe, ich habe dich unter dem Feigenbaum gesehen, glaubst du; noch Größeres als dies wirst du sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Dann sagte er zu ihm: \"Wahrlich, wahrlich sage ich euch: Ihr werdet den Himmel offen und die Engel Gottes über dem Menschensohn auf- und niedersteigen sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Am dritten Tage fand zu Kana in Galiläa eine Hochzeit statt. Die Mutter Jesu war dabei;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'auch Jesus war mit seinen Jüngern zur Hochzeit geladen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Als der Wein ausging, da sagte ihm die Mutter Jesu: \"Sie haben keinen Wein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Und Jesus sprach zu ihr: \"Was habe ich mit dir zu schaffen, Weib? Meine Stunde ist noch nicht gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Da sagte seine Mutter zu den Dienern: \"Tut alles, was er euch sagen mag.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Nun waren dort sechs steinerne Wasserkrüge aufgestellt für Reinigungen, wie sie bei den Juden üblich waren; ein jeder faßte zwei oder drei Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Und Jesus sprach zu ihnen: \"Füllt die Krüge mit Wasser!\" Sie füllten sie bis zum Rande an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Er sprach zu ihnen: \"Schöpft jetzt und bringt es dem Speisemeister!\" Sie brachten es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Der Speisemeister kostete das Wasser, das zu Wein geworden war. Er wußte nicht, woher er war; die Diener wußten es, sie hatten ja das Wasser eingeschöpft. Der Speisemeister rief den Bräutigam und sprach zu ihm:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, '\"Ein jeder setzt den Gästen zuerst den guten Wein vor, und erst wenn sie trunken sind, den geringeren; du aber hast den guten Wein bis jetzt zurückgehalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'So machte Jesus zu Kana in Galiläa den Anfang seiner Zeichen. Er offenbarte seine Herrlichkeit, und seine Jünger glaubten an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Darauf zog er nach Karpharnaum hinab mit seiner Mutter, seinen Brüdern und seinen Jüngern; sie blieben aber nur ein paar Tage dort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Das Osterfest der Juden war nahe, und Jesus zog nach Jerusalem hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Im Tempel traf er solche, die Rinder, Schafe und Tauben zu verkaufen hatten, und Geldwechsler, die sich dort aufhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Er flocht eine Geißel aus Stricken und trieb sie alle, samt den Schafen und den Rindern, aus dem Tempel, verschüttete das Geld der Wechsler und stieß deren Tische um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Und zu den Taubenhändlern sprach er: \"Schafft das hinweg und macht das Haus meines Vaters nicht zu einer Markthalle!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Da erinnerten sich seine Jünger an das Schriftwort: \"Der Eifer für dein Haus wird mich verzehren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Die Juden aber traten ihm entgegen mit den Worten: \"Mit welchem Zeichen beweist du uns, daß du dies tun darfst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus sprach zu ihnen: \"Reißt diesen Tempel nieder, und in drei Tagen will ich ihn wieder aufrichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Da sagten zu ihm die Juden: \"Sechsundvierzig Jahre hat man an diesem Tempel gebaut, und du willst ihn in drei Tagen wieder aufrichten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Er aber sprach vom Tempel seines Leibes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Als er dann von den Toten auferstanden war, erinnerten sich seine Jünger, daß er davon gesprochen hatte. So glaubten sie der Schrift und auch dem Worte, das Jesus gesprochen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Während er beim Osterfest in Jerusalem weilte, glaubten viele an seinen Namen, weil sie die Zeichen sahen, die er wirkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Doch Jesus selbst vertraute sich ihnen nicht an; denn er durchschaute sie alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Er hatte ja nicht nötig, daß ihn jemand über Menschen belehre; er selber wußte, wie es mit Menschen sich verhält.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Unter den Pharisäern war ein Mann mit Namen Nikodemus, ein Ratsherr bei den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Der kam eines Nachts zu ihm und sprach: \"Wir wissen, Rabbi, daß du von Gott als Lehrer gekommen bist; denn niemand kann solche Zeichen tun, wie du sie wirkst, wenn Gott nicht mit ihm ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Und Jesus sprach zu ihm: \"Wahrlich, wahrlich sage ich dir: Wenn jemand nicht von oben geboren ist, kann er das Reich Gottes nicht schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Da sagte Nikodemus zu ihm: \"Wie kann ein Mensch geboren werden, der schon alt ist? Er kann doch nicht noch einmal in den Mutterschoß zurück und wiederum geboren werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Und Jesus sprach: \"Wahrlich, wahrlich sage ich dir: Wer nicht aus Wasser und Heiligem Geiste geboren ist, kann nicht in das Reich Gottes eingehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Was aus dem Fleische geboren ist, ist Fleisch, was aber aus dem Geiste geboren ist, ist Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Wundere dich nicht, daß ich dir sagte: Ihr müßt von oben geboren werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Der Wind weht, wo er will; du hörst sein Brausen, weißt aber nicht, woher er kommt, noch wohin er geht. Geradeso verhält es sich mit dem, der aus dem Geiste geboren ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Darauf fragte Nikodemus: \"Wie ist das möglich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Und Jesus sprach zu ihm: \"Du bist der Lehrer Israels und begreifst das nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Wahrlich, wahrlich sage ich dir: Wir reden, was wir wissen, und wir bezeugen, was wir gesehen haben; ihr aber nehmt unser Zeugnis nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Wenn ich von irdischen Dingen zu euch rede und ihr nicht glaubt, wie werdet ihr dann glauben, wenn ich von himmlischen zu euch rede?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Niemand ist zum Himmel aufgestiegen als der, der vom Himmel kam, der Menschensohn der im Himmel ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Wie Moses in der Wüste die Schlange erhöht, hat, so muß auch der Menschensohn erhöht werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'damit jeder, der glaubt, nicht verlorengehe, sondern in ihm ewiges Leben habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'So sehr hat Gott die Welt geliebt, daß er seinen eingebornen Sohn hingab, damit, wer immer an ihn glaubt, nicht verlorengehe, vielmehr ewiges Leben habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Denn Gott hat seinen Sohn nicht dazu in die Welt gesandt, damit er die Welt richte, sondern damit die Welt durch ihn gerettet werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Wer an ihn glaubt, wird nicht gerichtet werden, wer aber nicht glaubt, der ist schon gerichtet, weil er an den Namen des eingebornen Sohnes Gottes nicht geglaubt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Darin besteht ja das Gericht: Das Licht ist in die Welt gekommen, die Menschen aber wollten lieber die Finsternis als das Licht; denn ihre Werke waren böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Denn jeder, der Böses tut, haßt das Licht und kommt nicht an das Licht, damit seine Werke nicht ans Licht kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Doch wer recht handelt, geht zum Lichte, damit so offenkundig werde, daß seine Werke mit Gott vollbracht sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Hierauf kam Jesus mit den Jüngern in die Landschaft Judäa, blieb dort mit ihnen und taufte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Auch Johannes taufte noch zu Änon, nahe bei Salim; denn dort gab es reichlich Wasser. Die Leute kamen hin und ließen sich taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Noch lag Johannes nicht im Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Da entstand ein Streit über Reinigungen zwischen den Jüngern des Johannes und einem Judäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Sie gingen zu Johannes und sagten ihm: \"Rabbi! Jener Mann, der drüben überm Jordan bei dir war und für den du Zeugnis abgelegt hast, sieh, er tauft nun auch, und alles läuft ihm zu.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes sprach: \"Ein Mensch kann sich nichts nehmen, was ihm nicht vom Himmel gegeben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ihr selbst müßt mir bezeugen, daß ich gesagt habe: \'Ich bin nicht der Christus, ich bin nur vor ihm hergesandt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Wer die Braut hat, ist Bräutigam; der Freund des Bräutigams indes steht da und hört ihn und freut sich herzlich ob der Stimme des Bräutigams. Diese Freude ist mir in vollem Maße zuteil geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Er muß wachsen und ich abnehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Wer von oben kommt, steht über allen; wer von der Erde ist, ist irdisch und redet irdisch. Wer vom Himmel kommt, steht über allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Und er bezeugt, was er gesehen und gehört hat; jedoch sein Zeugnis nimmt ja niemand an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Wer aber sein Zeugnis annimmt, der bestätigt, daß Gott wahrhaftig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Denn der von Gott Gesandte redet Gottes Worte; er spendet den Geist nicht kärglich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Der Vater liebt den Sohn und hat alles in seine Hand gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Wer an den Sohn glaubt, hat ewiges Leben, wer aber auf den Sohn nicht hört, wird das Leben nicht schauen; es lastet vielmehr Gottes Zorn auf ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Als der Herr erfahren hatte, den Pharisäern sei berichtet worden, daß Jesus mehr Jünger gewinne und mehr taufe als Johannes');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '-doch taufte Jesus nicht selber, sondern seine Jünger-');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'verließ er Judäa und ging nach Galiläa zurück. Er mußte seinen Weg durch Samaria nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'So kam er zu einer Stadt Samarias mit Namen Sichar, nahe bei dem Grundstück, das Jakob seinem Sohne Joseph geschenkt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Dort war der Jakobsbrunnen. Ermüdet von der Wanderung, setzte sich Jesus ohne weiteres am Brunnen nieder; es war um die sechste Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Eine Samariterin kam zum Wasserschöpfen. Und Jesus bat sie: \"Gib mir zu trinken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Seine Jünger waren nämlich in die Stadt gegangen, um Nahrungsmittel einzukaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Die Samariterin erwiderte ihm: \"Wie kannst denn du, ein Jude, von mir, einer Samariterin, einen Trunk erbitten?\" - Die Juden haben nämlich keinerlei Verkehr mit Samaritern. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Doch Jesus sprach zu ihr: \"Wenn du die Gabe Gottes kenntest und den, der dich gebeten: \'Gib mir zu trinken\', so hättest du ihn wohl gebeten, und er würde dir fließendes Wasser geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '\"Herr!\" sagte das Weib zu ihm, \"du hast ja kein Schöpfgefäß, und der Brunnen ist tief. Woher hast du denn fließendes Wasser?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Bist du vielleicht größer als unser Vater Jakob, der uns den Brunnen gegeben und selbst aus ihm getrunken hat, samt seinen Söhnen und Herden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus sprach zu ihr: \"Wer von diesem Wasser trinkt, den wird es wieder dürsten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'wer aber von dem Wasser trinkt, das ich ihm gebe, den wird es in Ewigkeit nicht dürsten. Das Wasser, das ich ihm geben werde, wird vielmehr in ihm ein Brunnen werden, dessen Wasser in das ewige Leben weiterfließt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Darauf bat ihn das Weib: \"Herr, gib mir dieses Wasser, damit ich nimmer dürste und nicht mehr zum Wasserschöpfen herzukommen brauche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Und Jesus sprach zu ihr: \"Geh, rufe deinen Mann und komm hierher!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Das Weib gab ihm zur Antwort: \"Ich habe keinen Mann.\" Und Jesus sprach zu ihr: \"Du hast recht, wenn du sagst: \'Ich habe keinen Mann.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Fünf Männer hast du schon gehabt, und der, den du jetzt hast, ist nicht dein Mann. Da hast du die Wahrheit gesagt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, '\"Herr\", sagte darauf das Weib zu ihm, \"ich sehe, du bist ein Prophet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Unsere Väter haben Gott auf diesem Berge angebetet; ihr sagt, in Jerusalem sei die Stätte, wo man anbeten müsse.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Und Jesus sprach zu ihr: \"Weib, glaube mir: Die Stunde kommt, da ihr weder auf dem Berge dort noch in Jerusalem den Vater anbeten werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ihr betet an, was ihr nicht kennet; wir beten an, was wir kennen; denn das Heil kommt von den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Jedoch die Stunde kommt, und sie ist jetzt da, in der die wahren Anbeter den Vater im Geist und in der Wahrheit anbeten werden. Der Vater sucht solche Anbeter;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'denn Gott ist Geist, und die ihn anbeten, müssen ihm im Geist und in der Wahrheit anbeten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Das Weib entgegnete ihm: \"Ich weiß, daß der Messias - das ist der sogenannte Christus - kommt. Ist er einmal da, dann wird er alles uns verkünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Da sagte Jesus zu ihr: \"Ich bin es, der mit dir redet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Darüber kamen seine Jünger. Sie wunderten sich sehr, daß er mit einem Weibe rede. Doch fragte keiner: \"Was willst du von ihr?\" oder \"Was redest du mit ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Das Weib ließ ihren Wasserkrug indessen stehen, eilte in die Stadt und sagte zu den Leuten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '\"Kommt, seht einen Mann, der mir alles gesagt hat, was ich getan habe. Vielleicht ist dieser der Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Da gingen sie zur Stadt hinaus und kamen zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Inzwischen baten ihn seine Jünger: \"Rabbi, iß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Er aber sprach zu ihnen: \"Ich habe eine Speise zum Essen, die ihr nicht kennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Die Jünger sprachen zueinander: \"Hat ihm denn jemand zu essen gebracht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Und Jesus sprach zu ihnen: \"Meine Speise ist es, den Willen dessen zu tun, der mich gesandt hat, und sein Werk zur Vollendung zu bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Sagt ihr denn nicht: Noch vier Monate, und dann kommt die Ernte? Seht, ich sage euch: Erhebt eure Augen und betrachtet die Felder; sie sind weiß zur Ernte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Schon empfängt der Schnitter seinen Lohn und sammelt Frucht zum ewigen Leben, daß Sämann und Schnitter sich zugleich erfreuen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Hier wird das Sprichwort wahr: \'Ein anderer sät, ein anderer erntet.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ich habe euch ausgesandt zu ernten, wo ihr nicht gearbeitet habt; andere taten die Arbeit, und ihr seid in ihre Arbeit eingetreten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Viele Samariter aus jener Stadt glaubten an ihn, weil das Weib ihnen fest versicherte: \"Er hat mir alles gesagt, was ich getan habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Die Samariter kamen zu ihm und baten ihn, bei ihnen zu bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Er blieb dort zwei Tage. Noch viel mehr glaubten an ihn um seiner Lehre willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Dem Weibe aber sagten sie: \"Nicht mehr um deines Redens willen glauben wir, nun haben wir ihn selbst gehört, wir wissen: Dieser ist wahrhaft der Heiland der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Nach den zwei Tagen zog er von dort weiter und ging nach Galiläa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Auch Jesus selbst ist ein Beweis dafür, daß ein Prophet in seiner Heimat keine Anerkennung findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Doch als er nach Galiläa kam, da nahmen ihn die Galiläer auf; sie hatten alles gesehen, was er in Jerusalem am Feste gewirkt hatte; auch sie waren nämlich zum Feste gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'So kam er wieder nach Kana in Galiläa, wo er das Wasser in Wein verwandelt hatte. Da war ein königlicher Beamter in Kapharnaum, dessen Sohn krank darniederlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Als er vernahm, daß Jesus von Judäa her nach Galiläa komme, suchte er ihn auf und bat ihn, er möge kommen und seinen Sohn, der schon im Sterben liege, heilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Und Jesus sprach zu ihm: \"Wenn ihr nicht Zeichen und Wunder seht, glaubt ihr nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Da bat ihn der königliche Beamte: \"Herr, komm, bevor mein Kind stirbt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Und Jesus sprach zu ihm: \"Geh heim, dein Sohn lebt.\" Der Mann glaubte dem Wort, das Jesus ihm gesagt hatte, und ging heim.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Er war noch auf dem Wege, da kamen ihm seine Knechte entgegen mit der Kunde: \"Dein Sohn lebt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Er fragte sie nach der Stunde, in der die Besserung eingetreten sei. Sie sagten ihm: \"Gestern um die siebte Stunde hat ihn das Fieber verlassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Da erkannte der Vater, daß es genau die Stunde gewesen war, da Jesus ihm gesagt hatte: \"Dein Sohn lebt.\" Nun wurde er mit seinem Hause gläubig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Das war schon das zweite Zeichen, das Jesus nach der Rückkehr aus Judäa nach Galiläa gewirkt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Hernach war ein Fest der Juden, und Jesus ging nach Jerusalem hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Am Schaftor zu Jerusalem befindet sich ein Teich, der auf hebräisch Bethesda heißt; er hat fünf Hallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'In diesen lag eine Menge Kranker: Blinde, Lahme und Schwindsüchtige, die warteten, bis das Wasser in Wallung kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Stieg doch von Zeit zu Zeit ein Engel /des Herrn/ in den Teich herab und ließ das Wasser aufwallen. Wer zuerst in dieses wallende Wasser stieg, ward gesund, an welchem Übel er auch leiden mochte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Dort war ein Mann, der schon achtunddreißig Jahre lang an einer Krankheit litt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Jesus sah ihn daliegen, und er erfuhr, daß er schon lange leide. Er fragte ihn: \"Willst du gesund werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Der Kranke sprach zu ihm: \"O Herr, ich habe ja keinen Menschen, der mich in den Teich brächte, wenn das Wasser in Wallung kommt. Bis ich dann komme, steigt ein anderer schon vor mir hinein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Und Jesus sprach zu ihm: \"Steh auf, nimm dein Bett und geh umher!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Und sogleich ward der Mann gesund; er nahm sein Bett und ging umher. Jener Tag war aber ein Sabbat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Die Juden sagten deshalb zum Geheilten: \"Es ist Sabbat; du darfst dein Bett nicht tragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Er aber sprach zu ihnen: \"Der mich gesund gemacht hat, sprach zu mir: \'Nimm dein Bett und geh!\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Sie fragten ihn: \"Wer ist der Mensch, der dir gesagt hat: \'Nimm dein Bett und geh umher?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Doch der Geheilte wußte nicht, wer es war; denn Jesus hatte sich entfernt, weil auf dem Platz ein Gedränge herrschte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Später traf ihn Jesus im Tempel und sprach zu ihm: \"Siehe, du bist gesund geworden; sündige nun nicht mehr, damit dir nicht noch Schlimmeres widerfahre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Da ging der Mann weg und sagte es den Juden, daß Jesus es sei, der ihn gesund gemacht habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Die Juden verfolgten nun Jesus, weil er solches am Sabbat tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Doch Jesus sprach zu ihnen: \"Mein Vater wirkt bis zur Stunde, und ich wirke auch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Deshalb trachteten ihm die Juden noch mehr nach dem Leben, nicht nur weil er den Sabbat brach, sondern auch weil er Gott seinen Vater nannte und sich so Gott gleichstellte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Doch Jesus sprach zu ihnen: \"Wahrlich, wahrlich, ich sage euch: Der Sohn kann nichts von sich aus tun, vielmehr nur das, was er den Vater wirken sieht. Was dieser tut, das tut auf gleiche Weise auch der Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Der Vater liebt den Sohn und zeigt ihm alles, was er tut, ja, noch größere Werke als diese wird er ihm zeigen, so daß ihr staunen werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Denn wie der Vater Tote auferweckt und lebendig macht, so macht auch der Sohn lebendig, wen er will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Auch richtet der Vater niemand, vielmehr hat er das Gericht ganz dem Sohn überlassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'damit alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, ehrt auch den Vater nicht, der ihn gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Wahrlich, wahrlich, ich sage euch: Wer auf mein Wort hört und dem glaubt, der mich gesandt hat, hat ewiges Leben; er kommt nicht ins Gericht; vielmehr ist er bereits vom Tode zum Leben übergegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Wahrlich, wahrlich, ich sage euch: Die Stunde kommt, und sie ist jetzt da, in der die Toten die Stimme des Sohnes Gottes hören werden; und die sie hören, werden leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Denn wie der Vater in sich selber das Leben hat, so hat er auch dem Sohn verliehen, das Leben in sich selbst zu haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Auch gab er ihm die Macht, Gericht zu halten; weil er Menschensohn ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Wundert euch nicht darüber! Die Stunde kommt, da alle, die in den Gräbern ruhen, seine Stimme hören werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'Die Gutes getan haben, werden auferstehen zur Auferstehung für das Leben, die Böses getan haben, zur Auferstehung der Verdammnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Aus mir selber kann ich nichts tun; ich richte, wie ich es höre; mein Urteil ist gerecht: ich suche ja nicht meinen Willen, sondern den Willen dessen, der mich gesandt, hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Wenn ich für mich selber Zeugnis geben würde, so wäre mein Zeugnis nicht wahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ein anderer legt für mich Zeugnis ab; ich weiß aber, daß das Zeugnis, das er über mich ablegt, wahr ist');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ihr habt zu Johannes gesandt, und er hat für die Wahrheit Zeugnis abgelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ich aber brauche das Zeugnis eines Menschen nicht, sondern ich sage das nur, damit ihr Rettung findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Er war die Lampe, die hell brannte; ihr aber wolltet euch in ihrem Scheine nur eine Zeitlang ergötzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Nein, ich habe ein Zeugnis, wertvoller als das des Johannes: die Werke, die mir der Vater übertragen hat, damit ich sie vollende; gerade sie, die Werke, die ich vollbringe, bezeugen es von mir, daß mich der Vater gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Der Vater, der mich gesandt hat, ist es auch, der selber Zeugnis über mich gegeben hat. Ihr freilich habt seine Stimme nie gehört, seine Gestalt nie gesehen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'sein Wort habt ihr nicht in euch bewahrt, weil ihr nicht an den glaubt, den er gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Ihr forscht in den Schriften, weil ihr glaubt, darin das ewige Leben zu besitzen; doch gerade diese legen Zeugnis von mir ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Indes zu mir wollt ihr nicht kommen, um so das Leben zu haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Mir ist es nicht darum zu tun, von Menschen Ehre zu empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Ich aber habe erkannt, daß ihr die Liebe Gottes nicht in euch habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ich bin im Namen meines Vaters gekommen, und doch, ihr nehmt mich nicht auf. Kommt dann ein anderer in seinem eigenen Namen, den nehmt ihr auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Wie könnt ihr zum Glauben kommen, da ihr auf Ehre voneinander bedacht seid und die Ehre vor dem einen Gott nicht sucht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Glaubt nicht, daß ich euch beim Vater anklagen werde. Wer euch anklagt, ist Moses, auf den ihr eure Hoffnung gesetzt habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Denn würdet ihr an Moses glauben, dann würdet ihr auch mir glauben; von mir hat er nämlich geschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Wenn ihr nicht an seine Schriften glaubt, wie solltet ihr dann meinen Worten glauben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Hierauf fuhr Jesus an das andere Ufer des Galiläischen Meeres, das auch See von Tiberias genannt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Eine große Menge folgte ihm, weil sie die Zeichen sahen, die er an den Kranken wirkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Und Jesus stieg auf den Berg, wo er sich mit seinen Jüngern niedersetzte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Das Hauptfest der Juden, Ostern, war nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Als Jesus die Augen erhob und sah, wie eine große Menge auf ihn zukam, da sprach er zu Philippus: \"Wo werden wir wohl Brote kaufen, daß diese essen können?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Er sagte dies aber nur, um ihn auf die Probe zu stellen; er wußte ja ganz gut, was er tun wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippus antwortete ihm: \"Brot für zweihundert Denare reicht für diese nicht aus, wenn jeder auch nur ein wenig erhalten soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Andreas, einer seiner Jünger, der Bruder des Simon Petrus, sprach zu ihm:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '\"Es ist ein Knabe hier, der fünf Gerstenbrote und zwei Fische hat; allein, was ist das für so viele?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Darauf sprach Jesus: \"Lasset die Leute sich setzen..\" Viel Gras war nämlich an dem Ort. Es lagerten sich die Männer, etwa fünftausend an der Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Und Jesus nahm die Brote, sprach ein Dankgebet und ließ sie an die Leute, die sich gesetzt hatten, verteilen; ebenso die Fische, soviel sie eben wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Als sie nun satt geworden waren, sprach er zu seinen Jüngern: \"Sammelt die Brocken, die übriggeblieben sind, damit nichts zugrunde gehe\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sie lasen auf und füllten zwölf Körbe voll mit Brocken der fünf Gerstenbrote; soviel war vom Essen übriggeblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Als die Leute sahen, welches Zeichen Jesus gewirkt hatte, riefen sie: \"Da ist wahrhaftig der Prophet, der in die Welt kommen soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Doch Jesus merkte, daß sie kommen würden und ihn mit Gewalt fortführen wollten, um ihn zum König zu machen. Er zog sich deshalb ganz allein wieder auf den Berg zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Als es Abend ward, begaben sich seine Jünger ans Meer hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Dort bestiegen sie ein Boot und fuhren übers Meer auf Kapharnaum zu. Es war schon dunkel, und Jesus war noch nicht zu ihnen gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Das Meer war durch einen heftigen Sturm aufgewühlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Sie waren etwa fünfundzwanzig oder dreißig Stadien Welt gerudert; da sahen sie Jesus auf dem Meere wandeln und immer näher auf das Boot zukommen. Und sie erschraken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Er aber redete sie an: \"Ich bin es, habt keine Furcht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Sie wollten ihn nun ins Boot nehmen, doch sogleich war das Boot am Land, auf das sie zuhielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Des anderen \'Tages bemerkte die Menge, die am anderen Meeresufer zurückgeblieben war, daß nur ein einziges Fahrzeug dagewesen, daß Jesus mit seinen Jüngern nicht ins Boot gestiegen sei, daß vielmehr seine Jünger allein abgefahren seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Indessen kamen andere Schiffe von Tiberias nahe an den Platz, wo sie nach dem Dankgebet des Herrn das Brot gegessen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Als die Menge sah, daß weder Jesus noch seine Jünger dort geblieben seien, bestiegen auch sie die Boote und fuhren nach Kapharnaum und suchten Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Sie fanden ihn am anderen Ufer und fragten ihn: \"Rabbi, wann bist du hierher gekommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus sprach zu ihnen: \"Wahrlich, wahrlich ich sage euch: Ihr sucht mich nicht, weil ihr Zeichen gesehen habt, sondern weil ihr von den Broten gegessen habt und satt geworden seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Bemüht euch nicht um die vergängliche Speise, vielmehr um die Speise, die zum ewigen Leben vorhält, die der Menschensohn euch geben wird; ihn hat Gott, der Vater ja besiegelt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Da sagten sie zu ihm: \"Was müssen wir denn tun, um die Werke Gottes zu verrichten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Und Jesus sprach zu ihnen: \"Das ist das Werk Gottes, daß ihr an den glaubt, den er gesandt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Sie fragten ihn: \"Welches Zeichen wirkst du denn, daß wir es sehen und an dich glauben? Welches Werk vollbringst du?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Unsere Väter haben das Manna in der Wüste gegessen, so wie geschrieben steht: \'Brot vom Himmel gab er ihnen zur Speise.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Und Jesus sprach zu ihnen: \"Wahrlich, wahrlich, ich sage euch: Nicht Moses gab euch das Himmelsbrot, sondern mein Vater gibt euch das wahre Himmelsbrot;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'der ist das Gottesbrot, der aus dem Himmel kommt und der Welt das Leben schenkt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Da riefen sie ihm zu: \"Herr, gib uns immerdar dieses Brot!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Und Jesus sprach zu ihnen: \"Ich bin das Brot des Lebens. Wer zu mir kommt, den wird es nicht mehr hungern; wer an mich glaubt, den wird es nie mehr dürsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Indes, ich habe es euch ja schon gesagt: Ihr habt mich zwar gesehen, doch ihr glaubt nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alles, was mir der Vater gibt, das kommt zu mir, und wer zu mir kommt, den stoße ich nicht zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Ich bin vom Himmel herabgestiegen, nicht um meinen eigenen Willen zu vollbringen, sondern den Willen dessen, der mich gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Das aber ist der Wille dessen, der mich gesandt hat: Ich soll nichts von dem, was er mir gegeben hat, verlorengehen lassen, vielmehr es auferwecken am Jüngsten Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'So ist es der Wille meines Vaters, daß jeder, der den Sohn sieht und an ihn glaubt, das ewige Leben habe; ich aber werde ihn auferwecken am Jüngsten Tage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Da murrten die Juden über ihn, weil er gesagt hatte: \"Ich bin das lebendige Brot, das aus dem Himmel gekommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Sie sprachen: \"Ist das nicht Jesus, der Sohn Josephs? Und kennen wir nicht seinen Vater und seine Mutter? Wie kann er sagen: \'Ich bin vom Himmel herabgekommen?\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Doch Jesus sprach zu ihnen: \"Murret nicht untereinander!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Niemand kann zu mir kommen, wenn ihn nicht der Vater, der mich gesandt hat, zieht; und ich werde ihn auferwecken am Jüngsten Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Bei den Propheten steht geschrieben: \'Sie alle werden Schüler Gottes sein.\' Wer immer auf den Vater hört und sich belehren läßt, der kommt zu mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nicht, als ob je einer den Vater gesehen hätte. Nur der, der bei Gott ist, hat den Vater gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Wahrlich, wahrlich, ich sage euch: Wer glaubt, hat ewiges Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Eure Väter haben das Manna in der Wüste gegessen und sind gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Das Brot, das aus dem Himmel kommt, ist solcher Art, daß keiner stirbt, der davon ißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ich bin das lebendige Brot, das aus dem Himmel gekommen ist. Wer von diesem Brot ißt, wird ewig leben. Das Brot, das ich geben werde, ist mein Fleisch für das Leben der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Da stritten die Juden untereinander und sagten: \"Wie kann uns dieser das Fleisch zu essen geben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesus aber sprach zu ihnen: \"Wahrlich, wahrlich, ich sage euch: Wenn ihr das Fleisch des Menschensohnes nicht essen und sein Blut nicht trinken werdet, so werdet ihr das Leben nicht in euch haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Wer mein Fleisch ißt und mein Blut trinkt, hat ewiges Leben, und ich werde ihn auferwecken am Jüngsten Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Denn mein Fleisch ist wirklich eine Speise und mein Blut wirklich ein Trank.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Wer mein Fleisch ißt und mein Blut trinkt, der bleibt in mir und ich in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Wie mich der lebendige Vater gesandt hat und ich kraft des Vaters lebe, so wird auch, wer mich ißt, durch mich leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'So ist das Brot, das aus dem Himmel herabgekommen ist, nicht wie jenes, das die Väter gegessen haben, die gestorben sind. Wer dieses Brot ißt, wird ewig leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Dies sprach er, als er zu Kapharnaum in der Synagoge lehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Viele seiner Jünger, die zugehört hatten, erklärten: \"Diese Rede ist schwer zu ertragen; wer mag ihn weiter anhören?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Doch Jesus wußte von sich aus, daß seine Jünger darüber murrten, und er sprach zu ihnen: \"Ihr nehmt daran Anstoß?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Wenn ihr den Menschensohn nun dahin auffahren seht, wo er zuvor war?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Der Geist ist es, der lebendig macht; das Fleisch nützt nichts. Die Worte, die ich zu euch gesprochen habe, sind Geist und Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Doch es sind einige unter euch, die nicht glauben.\" Denn Jesus wußte von Anfang an, wer die wären, die nicht glauben, und wer der ist, der ihn verraten würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'So fuhr er fort: \"Deshalb habe ich zu euch gesagt: Zu mir kann niemand kommen, wenn es ihm nicht vom Vater gegeben ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Von da an zogen sich viele seiner Jünger ganz zurück und gingen nicht mehr mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Da fragte Jesus die Zwölf: \"Wollt vielleicht auch ihr weggehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Darauf gab ihm Simon Petrus zur Antwort: \"Herr, zu wem sollen wir gehen? Du hast Worte ewigen Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Wir glauben und wir wissen, daß du der Heilige Gottes bist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Und Jesus sprach zu ihnen: \"Habe ich nicht euch Zwölf mir auserwählt? Und doch - einer aus euch ist ein Teufel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Damit meinte er den Judas Iskariot, den Sohn des Simon; denn dieser war daran, ihn zu verraten; einer aus den Zwölfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Hernach wanderte Jesus in Galiläa umher; denn in Judäa wollte er nicht mehr umherwandern, weil die Juden ihn zu töten suchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Unterdessen kam das jüdische Laubhüttenfest heran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Da sagten seine Brüder zu ihm: \"Geh fort von hier, begib dich nach Judäa, damit auch deine Anhänger die Werke sehen, die du vollbringst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Denn niemand wirkt im verborgenen, der öffentlich bekannt werden will. Kannst du solche Dinge tun, so zeige dich offen vor der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Selbst seine Brüder glaubten also nicht an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Deshalb sagte Jesus zu ihnen: \"Die Zeit ist für mich noch nicht gekommen; für euch ist freilich die Zeit stets geschickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Euch kann die Welt nicht hassen; mich aber haßt sie, weil ich ihr bezeuge, daß ihre Werke böse sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Ihr mögt zum Feste hinaufgehen; ich gehe zu diesem Feste noch nicht hinauf; denn meine Zeit ist noch nicht da.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'So sprach er zu ihnen und blieb in Galiläa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Nachdem seine Brüder zum Fest abgereist waren, ging er selbst auch hinauf, aber nicht öffentlich, nur im geheimen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Die Juden suchten ihn beim Fest und fragten: \"Wo ist er denn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Man redete viel von ihm heimlich im Volke. Die einen sagten: \"Er meint es gut.\" Andere aber sagten: \"Nein, im Gegenteil, er verführt das Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Doch offen sprach von ihm keiner aus Furcht vor den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Als nun das Fest schon halb vorüber war, ging Jesus in den Tempel und lehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Die Juden wunderten sich und fragten: \"Wie kennt er sich in der Schrift aus, da er doch keinen Unterricht gehabt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesus sprach zu ihnen: \"Ich habe meine Lehre nicht aus mir, vielmehr von dem, der mich gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Wer sich Mühe gibt, seinen Willen zu erfüllen, der wird erkennen, ob meine Lehre von Gott ist, oder ob ich aus mir selber rede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Wer aus sich selber redet, sucht seine eigene Ehre; doch wer die Ehre dessen sucht, der ihn gesandt hat, ist ehrlich, und kein Unrecht ist in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hat euch nicht Moses das Gesetz gegeben? Und dennoch hält keiner aus euch das Gesetz. Warum sucht ihr mich zu töten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Die Menge rief: \"Du bist verrückt. Wer trachtet dir denn nach dem Leben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus entgegnete: \"Ein einziges Werk habe ich getan, und ihr seid alle befremdet darüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moses gab euch die Beschneidung - nicht als ob sie von Moses käme, sie stammt schon von den Vätern - und ihr nehmt die Beschneidung auch am Sabbat vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Wenn jemand auch am Sabbat beschnitten werden darf, damit das Gesetz des Moses nicht übertreten wird, wie könnt ihr mir dann zürnen, wenn ich am Sabbat einen ganzen Menschen gesund gemacht habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Urteilt doch nicht nach dem Augenschein, nein, richtet nach dem wahren Sachverhalt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Da sagten einige aus Jerusalem: \"Ist das nicht der, den man zu töten sucht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Seht, er redet ja ganz offen, und man sagt nichts dagegen. Ja, sollten wirklich die Vorsteher einsehen, daß er der Christus ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Wir aber wissen, woher er stammt. Wenn aber einmal der Christus kommt, weiß niemand, woher er stammt\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Da rief Jesus, der im Tempel lehrte: \"Ihr kennt mich, und ihr wißt, woher ich stamme. Ich bin nicht von mir selbst gekommen, vielmehr, der mich gesandt hat, ist der Wahrhaftige. Ihr freilich kennt ihn nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ich aber kenne ihn: Ich stamme ja von ihm, und er hat mich gesandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Da suchten sie ihn zu ergreifen; doch niemand legte Hand an ihn, denn seine Stunde war noch nicht gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Aus dem Volk glaubten viele an ihn und sprachen: \"Wird der Christus, wenn er einmal kommt, wohl mehr Zeichen wirken als dieser?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Die Pharisäer wurden inne, daß man über ihn so im Volk sprach. Da sandten die Pharisäer und die Oberpriester Diener aus, ihn zu ergreifen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Und Jesus sprach: \"Nur noch kurze Zeit bin ich bei euch; dann gehe ich zu dem, der mich gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ihr werdet mich zwar suchen, aber nicht finden, und wo ich bin, dahin könnt ihr nicht kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Da fragten sich die Juden: \"Wohin will er denn gehen, daß wir ihn nicht finden sollen? Will er vielleicht in die Diaspora zu den Heiden gehen und die Heiden lehren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Was soll denn das bedeuten, wenn er sagt: \'Ihr werdet mich zwar suchen, aber nicht finden\', und \'wo ich bin, dahin könnt ihr nicht kommen\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Am letzten Tag, dem \"großen Festtag\" stand Jesus da und rief: \"Wer dürstet, komme zu mir und trinke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Wer an mich glaubt, aus dessen Innern werden, wie die Schrift sagt, Ströme lebendigen Wassers fließen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Er meinte damit den Geist, den die empfangen sollten, die an ihn glauben, denn es gab noch keinen Geist, weil Jesus noch nicht in seine Herrlichkeit eingegangen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Einige in der Menge, die diese Worte hörten, sagten: \"Er ist wahrhaftig der Prophet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Andere sagten: \"Er ist der Christus.\" Doch einige meinten: \"Kommt der Christus denn aus Galiläa?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Sagt nicht die Schrift: Er kommt aus dem Geschlechte Davids; aus Bethlehem, dem Flecken, wo David war, kommt der Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Und so entstand um seinetwillen ein Zwiespalt in der Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Einige aus ihnen wollten ihn ergreifen, doch niemand mochte an ihn Hand anlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Die Diener kehrten also zu den Oberpriestern und den Pharisäern zurück. Sie fragten: \"Warum habt ihr ihn nicht mitgebracht?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Die Diener sagten: \"Noch nie hat jemand so wie dieser Mensch gesprochen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Die Pharisäer hielten ihnen entgegen: \"Habt auch ihr euch schon verführen lassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Glaubt etwa einer von den Ratsherren an ihn oder einer von den Pharisäern?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Nein, nur dieser Pöbel - er sei verflucht -, der vom Gesetze nichts versteht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Da sprach zu ihnen Nikodemus, derselbe, der früher schon einmal des Nachts zu ihm gekommen und der einer aus ihrer Mitte war:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '\"Verurteilt bei uns das Gesetz einen Menschen, bevor man ihn gehört und untersucht hat, was er getan hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Da sagten sie zu ihm: \"Bist vielleicht auch du aus Galiläa? Sieh nach in der Schrift und wisse, daß kein Prophet aus Galiläa kommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Damit gingen sie auseinander, ein jeder in seine Wohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Darauf ging Jesus auf den Ölberg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Am frühen Morgen kam er wieder in den Tempel; alles Volk strömte ihm zu. Er setzte sich und lehrte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Da brachten die Schriftgelehrten und die Pharisäer ein Weib daher, das beim Ehebruch ertappt worden war. Sie stellten sie vor ihn hin');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'und sprachen zu ihm: \"Meister, dieses Weib ward beim Ehebruch auf frischer Tat ertappt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Nun hat Moses im Gesetz geboten, solche zu steinigen. Was sagst du dazu?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Sie fragten dies aber nur, um ihn auf die Probe zu stellen, damit sie Grund zur Anklage bekämen. Doch Jesus bückte sich und schrieb mit seinem Finger auf den Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Und als sie weiterhin mit Fragen in ihn drangen, da richtete er sich auf und sprach zu ihnen: \"Wer von euch keine Sünde hat, der werfe den ersten Stein auf sie!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Dann bückte er sich wieder und schrieb weiter auf den Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Als sie dies hörten, schlichen sie sich, die Ältesten voran, einer nach dem anderen weg. Jesus blieb allein zurück mit dem Weib, das vor ihm stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Da richtete sich Jesus auf und fragte sie: \"Weib, wo sind sie die dich angeklagt haben? Hat keiner dich verurteilt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, '\"Keiner, Herr,\" gab sie zur Antwort. Darauf sprach Jesus zu ihr: \"So will auch ich dich nicht verurteilen. Geh hin und sündige fortan nicht mehr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Und Jesus sprach weiterhin zu ihnen: \"Ich bin das Licht der Welt. Wer mir nachfolgt, wird nicht im Finstern wandeln, sondern das Licht des Lebens haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Da sagten die Pharisäer zu ihm: \"Du zeugst für dich selbst; dein Zeugnis hat keinen Wert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus erwiderte ihnen: \"Auch wenn ich für mich selbst zeuge, so hat mein Zeugnis dennoch Wert; ich weiß, woher ich komme und wohin ich gehe. Ihr freilich wißt nicht, woher ich komme noch wohin ich gehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ihr urteilt nach dem Äußeren, ich urteile über niemand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Wenn ich aber ein Urteil fälle, so ist mein Urteil wahr; ich stehe ja nicht allein, der Vater, der mich gesandt hat, ist mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'In eurem Gesetze steht geschrieben, daß zweier Menschen Zeugnis beweiskräftig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Nun zeuge ich für mich, und es zeugt für mich der Vater, der mich gesandt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Da fragten sie ihn: \"Wo ist dein Vater?\" Und Jesus sprach: \"Ihr kennt weder mich noch meinen Vater. Ja, würdet ihr mich kennen, dann würdet ihr auch meinen Vater kennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Er sprach diese Worte an der Schatzkammer, als er im Tempel lehrte. Doch es ergriff ihn niemand, denn seine Stunde war noch nicht gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Dann sprach er weiter zu ihnen: \"Ich gehe fort; ihr werdet mich zwar suchen, aber doch in eurer Sünde sterben. Wohin ich gehe, dahin könnt ihr nicht kommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Die Juden sagten: \"Will er sich etwa selber töten, daß er sagt: \'Wohin ich gehe, dahin könnt ihr nicht kommen\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Er sprach zu ihnen: \"Ihr stammt von unten, ich stamme von oben; ihr seid von dieser Welt, ich bin nicht von dieser Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Ich habe euch gesagt: Ihr werdet in euren Sünden sterben; wenn ihr nicht glaubt, daß ich es bin, so werdet ihr in euren Sünden sterben\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Sie fragten ihn: \"Wer bist du denn?\" Doch Jesus sprach zu ihnen: \"Daß ich überhaupt noch mit euch rede!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Ich hätte über euch noch vieles zu sagen und zu richten. Doch der, der mich gesandt hat, ist wahrhaftig, und ich verkünde der Welt das, was ich von ihm gehört habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Sie merkten nicht, daß er vom Vater zu ihnen sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jesus fuhr dann fort: \"Wenn ihr den Menschensohn erhöht habt, dann werdet Ihr erkennen, daß ich es bin und nichts aus mir selber tue, daß ich vielmehr nur das verkünde, was der Vater mich gelehrt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Der mich gesandt hat, ist immer mit mir; er hat mich nicht allein gelassen, weil ich allzeit tue, was ihm wohlgefällig ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Auf diese Rede hin glaubten viele an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Darauf sprach Jesus zu den Juden, die an ihn glaubten: \"Wenn ihr euch an mein Wort haltet, dann seid ihr meine echten Jünger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Ihr werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Sie antworteten ihm: \"Wir sind doch Kinder Abrahams und waren niemals bei irgend jemand Knecht. Wie magst du sagen: \'Ihr werdet frei werden\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Und Jesus sprach zu ihnen: \"Wahrlich, wahrlich, ich sage euch: Wer immer die Sünde begeht, ist ein Knecht der Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Der Knecht bleibt nicht für immer im Hause; der Sohn dagegen bleibt für immer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Wenn der Sohn euch frei macht, so seid ihr in Tat und Wahrheit frei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Wohl weiß ich, ihr seid Kinder Abrahams; doch ihr sucht mich zu töten, weil mein Wort in euch nicht Boden findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Was ich beim Vater geschaut habe, rede ich; ihr aber tut, was ihr bei eurem Vater gehört habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Da sagten sie zu ihm: \"Unser Vater ist Abraham.\" Jesus sprach zu ihnen: \"Wenn ihr Abrahams Kinder seid, so vollbringt auch die Werke Abrahams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'So aber sucht ihr mich zu töten, der ich euch die Wahrheit gesagt, die ich bei Gott vernommen habe. Abraham hat solches nicht getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ihr tut die Werke eures Vaters.\" Sie sagten ihm: \"Wir stammen nicht aus einem Ehebruch; wir haben nur einen Vater, Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus erwiderte ihnen: \"Wenn Gott euer Vater wäre, so würdet ihr mich lieben; ich bin von Gott ausgegangen und gekommen. Ich bin nicht aus eigener Sendung da; nein, jener hat mich gesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Warum versteht ihr meine Sprache nicht? Weil ihr mein Wort nicht hören könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ihr habt den Teufel zum Vater und wollt nach den Gelüsten eures Vaters handeln. Dieser war ein Menschenmörder von Anbeginn her und stand nicht in der Wahrheit, weil in ihm keine Wahrheit ist. Wenn er eine Lüge spricht, alsdann spricht er so recht aus seinem Eigenen; er ist ein Lügner und der Vater der Lüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Weil ich jedoch die Wahrheit rede, so glaubt ihr mir nicht');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Wer aus euch kann mich einer Sünde überführen? Wenn ich euch also die Wahrheit sage, warum glaubt ihr mir nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Wer aus Gott ist, hört die Worte Gottes; ihr hört nicht, weil ihr nicht aus Gott seid.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Die Juden gaben ihm zur Antwort: \"Haben wir nicht recht, wenn wir sagen, daß du ein Samariter und von Sinnen bist?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Und Jesus sprach: \"Ich bin nicht von Sinnen; ich ehre meinen Vater, doch ihr entehrt mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ich suche nicht meine eigne Ehre; doch es gibt einen, der auf sie bedacht ist und richtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Wahrlich, wahrlich, ich sage euch: Wer mein Wort bewahrt, der wird in Ewigkeit den Tod nicht schauen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Da sagten zu ihm die Juden: \"Nun wissen wir, daß du von Sinnen bist. Abraham und die Propheten sind gestorben, und du behauptest: \'Wer mein Wort bewahrt, der wird in Ewigkeit den Tod nicht kosten.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Stehst du etwa höher als unser Vater Abraham, der doch gestorben ist, und als die Propheten, die auch gestorben sind? Was machst du aus dir selbst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Und Jesus sprach: \"Wenn ich mich selbst ehren würde, so wäre meine Ehre nichts; nun ist es jedoch mein Vater, der mich ehrt, von dem ihr sagt, er sei euer Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Ihr kennt ihn nicht; ich aber kenne ihn. Würde ich sagen: Ich kenne ihn nicht, so wäre ich, was ihr seid, ein Lügner. Ich aber kenne ihn und bewahre sein Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, euer Vater, hat gejubelt, daß er meinen Tag schauen sollte; er sah ihn und frohlockte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Da sagten ihm die Juden: \"Du bist noch keine fünfzig Jahre alt und willst Abraham gesehen haben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Da sagte Jesus zu ihnen: \"Wahrlich, wahrlich, ich sage euch: Ehe Abraham war, bin ich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Da griffen sie nach Steinen, um auf ihn zu werfen. Doch Jesus verbarg sich und ging aus dem Tempel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Im Vorübergehen sah er einen Mann, der von Geburt an blind war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Seine Jünger fragten ihn: \"Rabbi, wer hat gesündigt, er oder seine Eltern, daß er blind geboren ward?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus antwortete: \"Weder er noch seine Eltern haben gesündigt, es sollten vielmehr die Werke Gottes sich an ihm offenbaren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Wir müssen die Werke dessen wirken, der mich gesandt hat, solange es Tag ist. Es kommt die Nacht, da niemand wirken kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Solange ich in der Welt bin, bin ich das Licht der Welt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'So sprach er, spuckte auf den Boden, machte mit Speichel einen Teig, strich den Teig auf die Augen des Blinden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'und sprach zu ihm: \"Geh, wasche dich im Teiche Siloe!\" - d.h. \"Gesandter\". Und er ging und wusch sich und kam sehend wieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Die Nachbarn und die ihn vorher als Bettler gesehen hatten, sagten: \"Ist das nicht der, der da gesessen und gebettelt hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Die einen sagten: \"Ja, er ist es.\" Die anderen: \"Nein, er sieht ihm nur ähnlich.\" Er selber sagte: \"Doch, ich bin es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Sie fragten ihn: \"Wie wurden dir die Augen geöffnet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Er gab zur Antwort: \"Der Mann, der Jesus heißt, hat einen Teig gemacht, mir die Augen bestrichen und zu mir gesagt: \'Geh hin zum Siloe und wasche dich.\' So bin ich hingegangen, habe mich gewaschen, und jetzt kann ich sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Sie fragten ihn: \"Wo ist jener?\" Er sprach: \"Ich weiß es nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Da brachten sie den Blindgewesenen zu den Pharisäern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'weil es Sabbat war am Tage, da Jesus den Teig bereitet und ihm die Augen geöffnet hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Nun fragten ihn die Pharisäer noch einmal, wie er denn sehend geworden sei. Und er erzählte ihnen: \"Er hat auf meine Augen einen Teig gestrichen, ich habe mich gewaschen und kann sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Da sagten einige aus den Pharisäern: \"Dieser Mensch ist nicht aus Gott; er hält den Sabbat nicht.\" Doch andere sagten: \"Wie kann ein Sünder solche Zeichen tun?\" Und so entstand ein Zwiespalt unter ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Sie fragten deshalb noch einmal den Blinden: \"Was sagst denn du von ihm; er hat dir ja die Augen aufgetan?\" Er sprach: \"Er ist ein Prophet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Nun wollten die Juden von ihm nicht glauben, daß er blind gewesen und jetzt sehend geworden sei, bevor sie nicht die Eltern des Geheilten vorgeladen hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Sie fragten diese: \"Ist dies euer Sohn, der, wie er sagt, blind geboren ist? Wie kommt es denn, daß er jetzt sehen kann?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Seine Eltern sprachen: \"Wir wissen: Das ist unser Sohn; er wurde blind geboren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Wie es kommt, daß er jetzt sehend ist, wissen wir nicht, noch wissen wir, wer ihm die Augen aufgetan hat. Fragt ihn nur selbst, er ist ja großjährig und kann über sich selber Auskunft geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'So sprachen seine Eltern. Sie hatten nämlich Angst vor den Juden; denn die Juden hatten schon beschlossen, jeden, der ihn als Christus bekennen würde, aus der Synagoge auszuschließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Deshalb sagten seine Eltern: \"Er ist großjährig, fragt ihn nur selbst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Sie ließen den Mann, der blind gewesen, nochmals rufen und sagten zu ihm: \"Gib Gott die Ehre. Wir wissen, daß jener Mensch ein Sünder ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Er aber sprach: \"Ob er ein Sünder ist, weiß ich nicht; eins aber weiß ich, daß ich blind gewesen bin und jetzt sehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Da fragten sie ihn noch einmal: \"Was hat er denn mit dir gemacht? Wie hat er dir die Augen aufgetan?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Da antwortete er ihnen: \"Ich habe es euch doch schon gesagt, habt ihr es nicht gehört; warum wollt ihr es nochmals hören? Wollt ihr vielleicht auch seine Jünger werden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Da schmähten sie ihn sehr und sagten: \"Du magst sein Jünger sein; wir sind Jünger des Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Wir wissen, daß Gott zu Moses geredet hat; wir wissen aber nicht, woher der kommt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Da sprach der Mann zu ihnen: \"Das ist aber doch merkwürdig, daß ihr nicht wißt, woher er ist, und doch hat er mir meine Augen aufgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Man weiß doch, daß Gott Sünder nicht erhört; wenn aber einer gottesfürchtig ist und Gottes Willen tut, den erhört er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Solange die Welt steht, hat man noch nie gehört, daß jemand einem Blindgeborenen die Augen aufgetan hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Wäre dieser nicht aus Gott, so könnte er nichts ausrichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Da sagten sie zu ihm und riefen: \"Ganz und gar in Sünden bist du geboren, und du willst uns belehren?\" Und sie schlossen ihn aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus hörte, daß sie ihn ausgeschlossen hätten. Als er ihm begegnete, da fragte er ihn: \"Glaubst du an den Menschensohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Er sprach: \"Herr, wer ist es, daß ich an ihn glaube?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Und Jesus sprach zu ihm: \"Du siehst ihn; der mit dir redet, ist es.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Da rief er aus: \"Herr, ich glaube!\" und fiel vor ihm nieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Und Jesus sprach: \"Zum Gericht bin ich in diese Welt gekommen: Die Blinden sollen sehend werden und die Sehenden erblinden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Das hörten einige der Pharisäer, die in seiner Nähe standen, und sie fragten: \"Sind vielleicht auch wir blind?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Und Jesus sprach: \"Wäret ihr blind, so hättest ihr am Ende keine Sünde; nun aber sagt ihr: \'Wir sehen.\' Sonach bleibt eure Sünde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '\"Wahrlich, wahrlich, ich sage euch: Wer nicht durch die Tür in den Schafstall geht, vielmehr woanders einsteigt, ist ein Dieb und Räuber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Wer aber durch die Tür eingeht, ist der Hirt der Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Ihm öffnet der Torhüter, und auch die Schafe kennen seine Stimme. Er ruft seine Schafe bei Namen und führt sie heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Hat er dann alle, die ihm gehören, hinausgelassen, so geht er vor ihnen her; die Schafe folgen ihm, weil sie seine Stimme kennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Einem Fremden aber werden sie nie folgen, vielmehr vor ihm fliehen, weil sie die Stimme des Fremden nicht kennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Dieses Gleichnis trug Jesus ihnen vor. Doch sie verstanden nicht, wen er damit meinte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Darauf sprach Jesus zu ihnen: \"Wahrlich, wahrlich ich sage euch: Ich bin die Tür zu den Schafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle, die vor mir kamen, sind Diebe und Räuber. Deshalb haben auch die Schafe nicht auf sie gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ich bin die Tür. Wer durch mich eingeht, der wird gerettet werden; er wird ein- und ausgehen und Weide finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Der Dieb kommt nur, um zu stehlen, zu schlachten und zu verderben. Ich komme, damit sie Leben haben, ja, damit sie es überreichlich haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ich bin der gute Hirt. Der gute Hirt setzt sein Leben für seine Schafe ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Der Mietling aber, der kein Hirt ist und dem die Schafe nicht gehören, sieht, wie der Wolf kommt; er läßt die Schafe im Stich und entflieht, und der Wolf fällt die Schafe an und versprengt sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Der Mietling flieht, weil er Mietling ist und ihm nichts an den Schafen liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ich bin der gute Hirt; ich kenne die Meinen, und die Meiner, kennen mich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'wie mich der Vater kennt und ich den Vater kenne. Ich setze mein Leben ein für die Schafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Ich habe noch andere Schafe, die nicht aus diesem Schafstall sind. Auch diese muß ich führen; sie werden meine Stimme hören, dann wird es eine Herde und ein Hirt sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Deshalb liebt mich auch der Vater, weil ich mein Leben einsetze, um es wiederzugewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Niemand entreißt es mir; freiwillig setze ich es ein. Ich habe Macht, es hinzugeben, und habe Macht, es wiederzugewinnen. Das ist der Auftrag, den ich von meinem Vater erhalten habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Wiederum entstand ein Zwiespalt bei den Juden wegen dieser Rede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Viele von ihnen sagten: \"Er ist besessen und von Sinnen. Was hört ihr ihm noch zu?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Andere sagten: \"Das sind nicht Reden eines Besessenen; kann denn ein Dämon Blinden die Augen öffnen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Man feierte das Fest der Tempelweihe in Jerusalem. Es war Winter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Und Jesus ging im Tempel, in der Halle Salomos, hin und her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Da umringten ihn die Juden und fragten ihn: \"Wie lange läßt du uns im Ungewissen? Wenn du der Christus bist, so sag es uns offen heraus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Und Jesus sprach zu ihnen: \"Ich habe es euch ja schon gesagt, doch ihr glaubt nicht. Die Werke, die ich im Namen meines Vaters vollbringe, zeugen für mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Allein ihr glaubt nicht, weil ihr nicht aus meinen Schafen seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Denn meine Schafe hören meine Stimme; ich kenne sie, und sie folgen mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Ich gebe ihnen ewiges Leben, und in Ewigkeit gehen sie nicht verloren, und niemand wird sie meiner Hand entreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mein Vater, der sie mir gegeben hat, ist größer als alle, und niemand kann sie der Hand meines Vaters entreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ich und der Vater sind eins.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Da hoben die Juden wiederum Steine auf, um ihn zu steinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Da sprach Jesus zu ihnen: \"Viele gute Werke ließ ich euch in der Macht meines Vaters sehen. Um welches dieser Werke willen wollt ihr mich steinigen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Die Juden sagten zu ihm: \"Nicht eines guten Werkes wegen wollen wir dich steinigen, sondern der Gotteslästerung wegen, da du, der du nur ein Mensch bist, dich zu Gott machst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Und Jesus sprach zu ihnen: \"Steht nicht in eurem Gesetz geschrieben: \'Ich sagte: Ihr seid Götter?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Wenn schon jene Götter heißen, an die das Wort Gottes erging, und da die Schrift nicht aufgehoben werden kann,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'wie könnt ihr von dem, den der Vater geweiht und in die Welt gesandt hat, sagen: \'Du lästerst Gott, \'weil ich gesagt habe: Ich bin der Sohn Gottes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Wenn ich die Werke meines Vaters nicht vollbringe, dann braucht ihr mir auch nicht zu glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Vollbringe ich sie aber und wollt ihr trotzdem mir nicht glauben, so glaubt doch wenigstens meinen Werken, auf daß ihr klar erkennt, daß der Vater in mir ist und ich im Vater bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Da suchten sie ihn wieder zu ergreifen; doch er entzog sich ihren Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Dann überschritt er wiederum den Jordan und ging an den Ort, wo Johannes vormals getauft hatte. Dort blieb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Und viele kamen zu ihm und sagten: \"Johannes hat kein Zeichen gewirkt; doch alles, was Johannes von diesem gesagt hat, hat sich als wahr erwiesen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Und viele glaubten dort an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Da war jemand krank, Lazarus aus Bethanien, dem Flecken der Maria und ihrer Schwester Martha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Maria war es gewesen, die den Herrn mit Öl gesalbt und die mit ihren Haaren seine Füße abgetrocknet hatte. Ihr Bruder Lazarus lag krank darnieder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Da ließen ihm die Schwestern sagen: \"Herr, sieh, der, den du liebst, ist krank.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Auf diese Botschaft hin sprach Jesus: \"Diese Krankheit führt nicht zum Tode, sie dient zur Ehre Gottes; der Sohn Gottes soll durch sie verherrlicht werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus liebte Martha, deren Schwester Maria und den Lazarus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Nachdem er nun erfahren hatte, Lazarus sei krank, blieb er trotzdem noch zwei Tage an dem Orte, wo er sich gerade befand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Alsdann erst sagte er zu den Jüngern: \"Laßt uns wieder nach Judäa gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Die Jünger sagten zu ihm: \"Rabbi, eben wollten dich die Juden steinigen; nun gehst du wiederum dorthin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Und Jesus sprach: \"Hat nicht der Tag zwölf Stunden? Wer am Tage seines Weges geht, der strauchelt nicht, er sieht ja das Licht dieser Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Doch wer bei Nacht dahingeht, strauchelt, weil ihm das Licht fehlt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'So sprach er; alsdann fügte er hinzu: \"Lazarus, unser Freund, liegt im Schlafe; ich gehe aber hin, ihn aufzuwecken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Da sagten die Jünger zu ihm: \"Herr, wenn er schläft, wird er gesund werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Doch Jesus sprach von seinem Tode; sie aber meinten, er rede von der Ruhe des Schlafes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Da sagte ihnen Jesus offen heraus: \"Lazarus ist gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Ich freue mich aber euretwegen, daß ich nicht dort war, damit ihr glaubt. Doch laßt uns jetzt zu ihm gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Da sagte Thomas, der auch der Zwilling heißt, zu den anderen Jüngern: \"Laßt uns mitgehen, damit wir mit ihm sterben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Als Jesus ankam, fand er ihn bereits vier Tage im Grabe liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Bethanien lag nahe bei Jerusalem, ungefähr fünfzehn Stadien davon entfernt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'So waren viele Juden zu Martha und Maria gekommen, um sie ihres Bruders wegen zu trösten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Sobald Martha hörte, Jesus komme, ging sie ihm entgegen; Maria aber blieb zu Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Und Martha sprach zu Jesus: \"Herr, wärest du dagewesen, wäre mein Bruder nicht gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Doch auch so weiß ich, daß Gott dir alles gibt, was du von Gott erbittest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Und Jesus sprach zu ihr: \"Dein Bruder wird auferstehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Martha sprach zu ihm: \"Ich weiß, daß er auferstehen wird bei der Auferstehung am Jüngsten Tage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Und Jesus sprach zu ihr: \"Ich bin die Auferstehung und das Leben. Wer an mich glaubt, wird leben, auch wenn er gestorben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Wer aber lebt und an mich glaubt, wird in Ewigkeit nicht sterben. Glaubst du das?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, '\"Ja, Herr\", sprach sie, \"ich glaube, daß du der Christus bist, der Sohn des lebendigen Gottes, der in die Welt kommen soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'So sprach sie, ging weg und rief Maria, ihre Schwester, und sagte zu ihr leise: \"Der Meister ist da und ruft dich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Kaum hatte sie dies gehört, stand sie schnell auf und eilte zu ihm hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jesus hatte den Flecken noch nicht betreten; er war noch an der Stelle, wo Martha ihn getroffen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Als die Juden, die bei ihr im Hause waren und sie trösteten, gesehen hatten, daß Maria sich eilends erhoben hatte und weggegangen war, folgten sie ihr in der Meinung, sie gehe zum Grabe, um dort zu weinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Als Maria an die Stelle kam, wo Jesus war, und sie ihn sah, fiel sie ihm zu Füßen mit den Worten: \"Herr, wärst du dagewesen, so wäre mein Bruder nicht gestorben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Als Jesus sah, wie sie so weinte und wie die Juden, die mit ihr gekommen waren, gleichfalls weinten, ward er innerlich tief ergriffen und erschüttert;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'er fragte: \"Wohin habt ihr ihn gelegt?\" Sie sagten ihm: \"Herr, komm und sieh!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Und Jesus weinte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Die Juden sagten: \"Seht, wie lieb er ihn hatte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Doch einige aus diesen meinten: \"Hätte dieser, der dem Blinden die Augen aufgetan hat, nicht machen können, daß er nicht starb?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Und Jesus, wiederum innerlich tief erschüttert, ging zum Grabe. Es war eine Höhle, die mit einem Stein verschlossen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Und Jesus sprach: \"Nehmt den Stein hinweg!\" Da sagte Martha, die Schwester des Verstorbenen, zu ihm: \"Herr, er riecht schon; es ist bereits vier Tage her.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Doch Jesus sprach zu ihr: \"Habe ich dir nicht gesagt, daß, wenn du glaubst, du die Herrlichkeit Gottes sehen würdest?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Nun hoben sie den Stein hinweg. Und Jesus hob die Augen himmelwärts und betete: \"Ich danke dir, Vater, daß du mich erhört hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Ich wußte zwar, daß du mich jederzeit erhörst. Jedoch ich sagte es des Volkes wegen, das hier steht, damit sie glauben, daß du mich gesandt hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Nach diesen Worten rief er mit lauter Stimme: \"Lazarus, komm heraus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Und der Tote kam heraus, an Händen und Füßen mit Binden eingewickelt und das Angesicht mit einem Schweißtuch bedeckt. Und Jesus sprach zu ihnen: \"Macht ihn frei und laßt ihn gehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Viele Juden, die zu Maria gekommen waren und gesehen hatten, was er getan hatte, glaubten an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Doch einige aus ihnen gingen zu den Pharisäern und erzählten ihnen, was Jesus getan hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Die Oberpriester und die Pharisäer riefen nun den Hohen Rat zusammen und sagten: \"Was sollen wir tun, da dieser Mensch so viele Zeichen wirkt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Denn lassen wir ihn weiter gewähren, so werden alle an ihn glauben; dann aber kommen die Römer und nehmen uns Land und Leute weg.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Einer aber unter ihnen, Kaiphas, der Hohepriester jenes Jahres, sprach zu ihnen: \"Ihr versteht nichts,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'bedenkt auch nicht, daß es für euch besser ist, wenn ein einziger Mensch für das Volk stirbt, als daß das ganze Volk zugrunde gehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Das sagte er indes nicht aus sich selbst; vielmehr, weil er in jenem Jahre Hoherpriester war, weissagte er, daß Jesus für das Volk sterben werde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'ja, nicht für das Volk allein, sondern auch, um die zerstreuten Kinder Gottes zu einem Volk zu vereinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Von diesem Tage an waren sie entschlossen, ihn zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Darum wandelte Jesus nicht mehr öffentlich bei den Juden, sondern zog sich von dort zurück in eine Gegend nahe der Steppe, in eine Stadt mit Namen Ephrem. Dort verweilte er mit seinen Jüngern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Nun war das Osterfest der Juden nahe. Da zogen viele vom Lande vor dem Osterfest nach Jerusalem hinauf, um sich zu reinigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Sie suchten Jesus und fragten einander im Tempel: \"Was meint ihr? Wird er wohl zum Feste kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Die Oberpriester und die Pharisäer hatten nämlich den Befehl erlassen, jeder, der von seinem Aufenthalt wisse, müsse es anzeigen, damit man ihn festnehmen könne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Sechs Tage vor dem Osterfest kam Jesus nach Bethanien, wo Lazarus wohnte, den Jesus von den Toten auferweckt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Dort bereitete man ihm ein Gastmahl. Martha wartete auf; Lazarus war einer seiner Tischgenossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Maria aber nahm ein Pfund von echtem, kostbarem Nardenöl und salbte die Füße Jesu und trocknete die Füße Jesu mit ihren Haaren ab. Das Haus ward vom Duft der Salbe ganz erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Da sagte einer von den Jüngern, Judas Iskariot, der ihn verraten sollte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '\"Warum hat man dieses Salböl nicht um dreihundert Denare verkauft und es den Armen gegeben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Das sagte er indessen nicht, weil ihm an den Armen etwas gelegen wäre, vielmehr weil er ein Dieb war und die Kasse hatte und das, was einging, auf die Seite brachte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Doch Jesus sprach: \"Laßt sie in Ruhe, damit sie es für den Tag meines Begräbnisses aufbewahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Die Armen habt ihr allezeit bei euch; mich aber habt ihr nicht allezeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Da hörte eine große Anzahl Juden, daß er dort sei. Sie kamen nicht bloß Jesu wegen, vielmehr auch, um den Lazarus zu sehen, den er von den Toten auferweckt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Die Oberpriester beschlossen nun, auch Lazarus zu töten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'weil seinetwegen viele Juden hingingen und an Jesus glaubten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Am Tag darauf erfuhr die Volksmenge, die zum Fest gekommen war, daß sich Jesus auf dem Wege nach Jerusalem befinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Sie nahmen Palmzweige und zogen ihm entgegen und riefen: \"Hosanna! Gepriesen sei, der kommt im Namen des Herrn! Du König Israels!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Und Jesus traf auf einen jungen Esel und setzte sich darauf, so wie geschrieben steht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '\"Fürchte dich nicht, du Tochter Sion, siehe, dein König kommt; er sitzt auf dem Füllen eines Esels.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Zuerst verstanden seine Jünger es nicht; hernach aber, als Jesus verherrlicht war, erinnerten sie sich, daß dies über ihn geschrieben stand und daß sie dabei mitgewirkt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Die Volksmenge, die bei ihm gewesen war, als er den Lazarus aus dem Grabe gerufen und von den Toten auferweckt hatte, legte Zeugnis ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Darum zog ihm auch das Volk entgegen, weil es vernommen hatte, daß er dieses Wunder gewirkt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Die Pharisäer aber sagten zueinander: \"Da seht ihr nun, daß ihr nichts ausrichtet. Seht: alle Welt läuft ihm nach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Unter denen, die hinaufgepilgert waren, um am Fest anzubeten, befanden sich auch einige Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Diese wandten sich an Philippus, der aus Bethsaida in Galiläa war, und baten ihn: \"Herr, wir möchten Jesus sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippus ging und besprach sich mit Andreas, dann trugen es Andreas und Philippus Jesus vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Und Jesus sprach zu ihnen: \"Die Stunde ist gekommen, da der Menschensohn verherrlicht wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Wahrlich, wahrlich sage ich euch: Wenn das Weizenkorn nicht in die Erde fällt und stirbt, so bleibt es für sich allein; wenn es aber stirbt, bringt es viele Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Wer sein Leben liebt, wird es verlieren; doch wer sein Leben in dieser Welt haßt, der wird es für das ewige Leben bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Wer mir dienen will, folge mir; denn wo ich bin, soll auch mein Diener sein. Und wer mir dient, den wird mein Vater ehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Jetzt ist meine Seele tief erschüttert. Jedoch, was soll ich sagen? Vater, rette mich aus dieser Stunde. Ist doch deshalb gerade diese Stunde über mich gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Vater, verherrliche Deinen Namen!\" Da erscholl eine Stimme vom Himmel: \"Ich habe verherrlicht, und ich will weiterhin verherrlichen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Das Volk, das dastand und es hörte, sprach: \"Es hat gedonnert.\" Andere indes behaupteten: \"Ein Engel hat mit ihm geredet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus sprach: \"Nicht meinethalben ertönte diese Stimme, sondern euretwegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Denn jetzt vollzieht sich das Gericht in dieser Welt; jetzt wird der Fürst dieser Welt hinausgestoßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Wenn ich von der Erde erhöht bin, werde ich alle an mich ziehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Mit diesen Worten wollte er andeuten, welch einen Tod er sterben werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Da sprach das Volk zu ihm: \"Wir haben aus dem Gesetz erfahren, daß der Christus ewig bleibt. Wie kannst du sagen: \'Der Menschensohn muß erhöht werden\'? Wer ist denn dieser Menschensohn?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Und Jesus sprach zu ihnen: \"Nur noch kurze Zeit ist das Licht bei euch. Wandelt darin, solange ihr das Licht habt. Sonst möchte euch die Finsternis ergreifen. Wer im Finstern wandelt, weiß nicht, wohin er geht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Solange ihr das Licht habt, glaubt an das Licht, damit ihr Kinder des Lichtes werdet.\" So sprach Jesus, ging weg und hielt sich vor ihnen verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Obwohl er vor ihnen so viele Zeichen gewirkt hatte, glaubten sie doch nicht an ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Es sollte sich das Wort des Propheten Isaias erfüllen: \"Herr, wer hat unserer Botschaft geglaubt? Wem ward der Arm des Herrn offenbar?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Darum konnten sie nicht glauben, wie es Isaias wiederum vorhergesagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '\"Er machte ihre Augen blind und hart ihr Herz, auf daß sie mit den Augen nicht sehen, mit ihrem Herzen nicht verstehen und sie sich bekehren und ich sie heilen könnte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'So sagte Isaias, als er seine Herrlichkeit schaute und von ihm sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Trotz alldem glaubten an ihn auch viele von den Ratsherren; nur wagten sie es der Pharisäer wegen nicht, sich offen zu bekennen, damit sie nicht aus der Synagoge ausgeschlossen würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Die Ehre vor den Menschen galt ihnen eben mehr als die Ehre vor Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Und Jesus rief mit lauter Stimme: \"Wer an mich glaubt, glaubt nicht an mich, vielmehr an den, der mich gesandt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'und wer mich sieht, sieht den, der mich gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ich hin als Licht in die Welt gekommen, damit keiner, der an mich glaubt, im Finstern bleibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Wenn jemand meine Worte hört, aber nicht befolgt, den richte nicht ich. Ich bin nicht gekommen, die Welt zu richten, sondern die Welt zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Wer mich verachtet und meine Worte nicht annimmt, hat seinen Richter: Das Wort, das ich geredet habe, wird ihn am Jüngsten Tage richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Nicht von mir aus habe ich geredet; der Vater, der mich gesandt hat, hat mir geboten, was ich sagen und verkünden soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Ich weiß, sein Gebot bedeutet ewiges Leben. Was ich also sage, sage ich so, wie mir es der Vater geboten hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Es war vor dem Osterfest. Jesus wußte, daß die Stunde für ihn gekommen sei, aus dieser Welt zum Vater hinüberzugehen. Da er die Seinen, die in der Welt waren, liebte, bewies er ihnen seine Liebe bis zum äußersten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Es war während eines Mahles. Der Teufel hatte schon dem Judas, dem Sohn des Simon, dem Iskariot, ins Herz gegeben, ihn zu verraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Obwohl er wußte, daß der Vater ihm alles in die Hände gelegt, daß er von Gott ausgegangen sei und wiederum zu Gott zurückkehre,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'erhob er sich vom Mahle, legte seine Oberkleider ab, nahm ein Linnentuch und legte es sich um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Dann goß er Wasser in das Becken und begann, den Jüngern die Füße zu waschen und sie mit dem Linnentuch, das er sich umgebunden hatte, abzutrocknen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'So kam er auch zu Simon Petrus. Und dieser sprach zu ihm: \"Herr, du willst mir die Füße waschen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus sprach zu ihm: \"Was ich tue, verstehst du jetzt noch nicht; nachher wirst du es begreifen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Da sagte Petrus zu ihm: \"In Ewigkeit sollst du mir die Füße nicht waschen.\" Jesus aber sprach zu ihm: \"Wenn ich dich nicht wasche, dann hast du keinen Teil an mir.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Da gab ihm Simon Petrus zur Antwort: \"Dann, Herr, nicht nur die Füße, auch die Hände und das Haupt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Doch Jesus sprach zu ihm. \"Wer gebadet hat, der braucht nur noch die Füße zu waschen; sonst ist er ganz rein. Auch ihr seid rein, aber nicht alle.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Er kannte nämlich den, der ihn verraten wollte; deshalb sprach er: \"Ihr seid nicht alle rein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Nachdem er ihnen die Füße gewaschen, seine Oberkleider angelegt und sich wieder zu Tisch gesetzt hatte, sprach er zu ihnen: \"Versteht ihr, was ich euch getan habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ihr nennt mich \'Meister\' und \'Herr\', und ihr habt recht; ich bin es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Wenn ich euch nun die Füße gewaschen habe, ich, euer Herr und Meister, dann müßt auch ihr einander die Füße waschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Ich habe euch ein Beispiel gegeben, damit ihr so tut, wie ich an euch getan habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Wahrlich, wahrlich, ich sage euch: Der Knecht steht nicht höher als sein Herr, und der Gesandte nicht höher als der, der ihn gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Wenn ihr dies versteht und danach handelt, dann seid ihr selig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Doch von euch allen gilt dies nicht. Ich weiß, wen ich erwählt habe. Allein, es muß die Schrift erfüllt werden: \'Der mit mir das Brot ißt, hat die Ferse gegen mich erhoben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Schon jetzt sage ich es euch, bevor es eintrifft, damit ihr, wenn es eintrifft, glaubt, daß von mir die Rede ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Wahrlich, wahrlich, ich sage euch: Wer den aufnimmt, den ich sende, der nimmt mich auf, wer aber mich aufnimmt, nimmt den auf, der mich gesandt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Nach diesen Worten wurde Jesus im Geiste erschüttert, und unverhüllt sprach er es aus und sagte: \"Wahrlich, wahrlich, ich sage euch: Einer aus euch wird mich verraten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Da sahen sich die Jünger gegenseitig an; sie wußten nicht, wen er meinte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Einer seiner Jünger, der, den Jesus liebte, lag an der Brust Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Petrus winkte diesem zu und sprach zu ihm: \"Frage, wen er damit meint.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Da lehnte sich dieser so an die Brust Jesu und fragte: \"Herr, wer ist es?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Und Jesus gab zur Antwort: \"Der ist es, dem ich den Bissen eintunken und reichen werde.\" Er tunkte den Bissen ein und reichte ihn dem Judas, dem Sohn des Simon, dem Iskariot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Und nach dem Bissen fuhr der Satan in ihn. Jesus sprach dann noch zu ihm: \"Was du tun willst, tu bald!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Doch verstand keiner der Tischgenossen, weshalb er das zu ihm sagte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Weil Judas die Kasse hatte, so meinten einige, Jesus wollte ihm sagen: \"Kaufe, was wir auf das Fest brauchen\", oder er solle den Armen etwas geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Als jener den Bissen zu sich genommen hatte, ging er sofort hinaus. Und es war Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Als er hinausgegangen war, sprach Jesus: \"Jetzt ist der Menschensohn verherrlicht, und Gott ist in ihm verherrlicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Wenn Gott in ihm verherrlicht ist, wird Gott ihn auch bei sich verherrlichen; und er wird ihn bald verherrlichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Kinder! Nur noch eine kleine Weile bin ich bei euch. Ihr werdet mich suchen; doch was ich den Juden gesagt habe: Wohin ich gehe, dahin könnt ihr nicht gehen, das sage ich jetzt auch euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Ich gebe euch ein neues Gebot: Liebet einander! So, wie ich euch geliebt habe, so sollt auch ihr einander lieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Daran sollen alle erkennen, daß ihr meine Jünger seid, wenn ihr Liebe zueinander habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Petrus fragte ihn: \"Herr, wohin gehst du?\" Jesus sprach zu ihm: \"Wohin ich gehe, dorthin kannst du mir jetzt nicht folgen; du wirst mir aber später folgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Petrus erwiderte ihm: \"Herr, warum kann ich dir denn jetzt nicht folgen? Mein Leben will ich für dich hingeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus antwortete: \"Dein Leben willst du für mich hingeben? Wahrlich, wahrlich, ich sage dir: Noch vor dem Hahnenschrei wirst du mich dreimal verleugnet haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '\"Euer Herz sei nicht bange! Ihr glaubt an Gott, glaubt auch an mich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Im Hause meines Vaters gibt es viele Wohnungen. Und wäre es nicht so, dann hätte ich es euch gesagt; ich gehe hin, euch eine Stätte zu bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Wenn ich dann hingegangen bin und euch eine Stätte bereitet habe, dann komme ich wieder und hole euch zu mir, damit auch ihr da seid, wo ich bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Den Weg kennt ihr, wohin ich gehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Da sagte Thomas zu ihm:., Herr, wir wissen nicht, wohin du gehst. Wie sollten wir da den Weg kennen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus sprach zu ihm: \"Ich bin der Weg, die Wahrheit und das Leben. Niemand kommt zum Vater als durch mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Wenn ihr mich kenntet, so würdet ihr auch meinen Vater kennen. Jedoch von nun an kennt ihr ihn, ihr habt ihn ja gesehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Da sprach Philippus zu ihm: \"Herr, zeige uns den Vater, und das ist uns genug.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Und Jesus sprach zu ihm: \"So lange schon bin ich bei euch, und du kennst mich immer noch nicht, Philippus? Wer mich gesehen hat, der hat auch den Vater gesehen. Wie kannst du sagen: \'Zeige uns den Vater?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Glaubst du denn nicht, daß ich im Vater bin und daß der Vater in mir ist? Die Worte, die ich zu euch rede, sage ich nicht aus mir selber; der Vater, der in mir bleibt, vollbringt die Werke selber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Glaubt mir, daß ich im Vater bin und daß der Vater in mir ist. Wenn nicht, so glaubt wenigstens der Werke wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubt, der wird die Werke, die ich vollbringe, ebenso vollbringen; ja, noch größere wird er vollbringen; ich gehe ja zum Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Um was immer ihr in meinem Namen den Vater bitten werdet, das will ich tun, damit der Vater im Sohn verherrlicht werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Um was ihr mich in meinem Namen bitten werdet, das will ich tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Wenn ihr mich liebt, werdet ihr meine Gebote halten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Ich will den Vater bitten, und er wird euch einen anderen Beistand verleihen, damit er in Ewigkeit bei euch bleibe:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'den Geist der Wahrheit. Die Welt kann ihn nicht empfangen, weil sie ihn weder sieht noch kennt. Ihr aber kennt ihn; er bleibt bei euch und wird in euch sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ich lasse euch nicht als Waisen zurück; ich komme zu euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Nur noch eine kleine Weile, dann sieht die Welt mich nicht mehr; ihr aber seht mich, weil ich lebe und ihr leben werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'An jenem Tage werdet ihr verstehen, daß ich in meinem Vater bin und daß ihr in mir seid und ich in euch bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Wer meine Gebote hat und sie bewahrt, der ist es, der mich liebt. Wer mich liebt, der wird von meinem Vater geliebt werden, und auch ich will ihn lieben und mich ihm offenbaren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Da fragte ihn Judas, nicht der Iskariot: \"Herr, wie kommt es denn, daß du dich uns und nicht der Welt offenbaren willst?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Und Jesus sprach zu ihm: \"Wer mich liebt, der wird mein Wort bewahren; ihn wird mein Vater lieben; zu diesem kommen wir und nehmen bei ihm Wohnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Wer aber mich nicht liebt, bewahrt auch meine Worte nicht. Jedoch das Wort, das ihr vernehmt, ist nicht das meinige, vielmehr ist es das Wort dessen, der mich gesandt hat, des Vaters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Dies habe ich zu euch gesagt, da ich noch bei euch weile.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Jedoch der Heilige Geist, der Beistand, den der Vater in meinem Namen senden wird, wird euch alles lehren und euch an alles erinnern, was ich euch gesagt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Frieden hinterlasse ich euch, meinen Frieden gebe ich euch. Nicht wie die Welt gibt, gebe ich euch. Euer Herz sei nicht bange und verzage nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ihr habt gehört, daß ich zu euch gesagt habe: Ich gehe, doch ich komme wiederum zu euch. Wenn ihr mich liebtet, so würdet ihr euch freuen, daß ich zum Vater gehe; denn der Vater ist größer als ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Ich habe es euch jetzt gesagt, ehe es geschieht, damit ihr glaubt, sobald es einmal eingetroffen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Ich werde nicht mehr vieles zu euch reden; denn es kommt der Fürst der Welt. Er hat zwar kein Anrecht an mich;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'die Welt jedoch soll erkennen, daß ich den Vater liebe und so handle, wie mir der Vater aufgetragen hat. Wohlan, laßt uns von hier weggehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '\"Ich bin der wahre Weinstock; mein Vater ist der Weingärtner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Er schneidet jeden Rebzweig an mir ab, der keine Frucht bringt; jeden aber, der Frucht trägt, reinigt er, damit er noch mehr Frucht trage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ihr seid schon rein des Wortes wegen, das ich zu euch gesprochen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Bleibt in mir, dann bleibe ich in euch. Wie der Rebzweig aus sich selbst keine Frucht bringen kann, wenn er nicht am Weinstock bleibt, also auch ihr nicht, wenn ihr nicht in mir bleibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ich bin der Weinstock; ihr seid die Rebzweige. Wer in mir bleibt, und der, in dem ich bleibe, bringt viel Frucht; getrennt von mir, könnt ihr nichts tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Wer nicht in mir bleibt, wird wie ein Rebzweig weggeworfen und verdorrt; man sucht sie dann zusammen, wirft sie ins Feuer und verbrennt sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Wenn ihr in mir bleibt und meine Worte in euch bleiben, so mögt ihr bitten, um was ihr wollt, es wird euch zuteil werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Dadurch wird mein Vater verherrlicht, daß ihr reiche Frucht bringt und meine Jünger werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Wie mich der Vater geliebt hat, so habe auch ich euch geliebt. Bleibt in meiner Liebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Wenn ihr meine Gebote haltet, dann bleibt ihr in meiner Liebe, so wie auch ich die Gebote meines Vaters gehalten habe und in seiner Liebe bleibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Das habe ich zu euch gesagt, damit meine Freude in euch sei und eure Freude vollendet werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Das ist mein Gebot: Liebet einander, so wie ich euch geliebt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Niemand hat eine größere Liebe, als wer sein Leben einsetzt für seine Freunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ihr seid meine Freunde, wenn ihr tut, was ich euch auftrage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ich nenne euch nicht mehr Knechte; der Knecht weiß nicht, was sein Herr tut. Freunde habe ich euch genannt; denn ich habe euch alles geoffenbart, was ich von meinem Vater gehört habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Nicht ihr habt mich erwählt, sondern ich habe euch erwählt und euch bestellt, damit ihr hingeht und Frucht bringt und eure Frucht von Dauer sei, damit euch der Vater alles gebe, um was ihr ihn in meinem Namen bittet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Nur dies ist mein Gebot: Liebet einander!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Wenn die Welt euch haßt, bedenket, daß sie mich vor euch gehaßt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Ja, wäret ihr aus der Welt, so würde die Welt ihr Eigenes lieben. Da ihr aber nicht aus der Welt seid, vielmehr ich euch aus der Welt auserwählt habe, so haßt euch die Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Denkt an das Wort, das ich zu euch gesprochen habe: Ein Knecht ist nicht höher als sein Herr. Wenn sie mich verfolgt haben, so werden sie auch euch verfolgen; und haben sie mein Wort bewahrt, so werden sie auch das eurige bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Doch all dies werden sie um meines Namens willen euch antun, weil sie den nicht kennen, der mich gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Wäre ich nicht gekommen und hätte nicht zu ihnen gesprochen, so hätten sie keine Sünde; nun aber haben sie für ihre Sünde keine Entschuldigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Wer mich haßt, haßt auch meinen Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Hätte ich nicht Taten unter ihnen vollbracht, wie sie kein anderer vollbracht hat, dann hätten sie keine Sünde. Nun aber haben sie gesehen, und dennoch hassen sie mich und meinen Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Aber das Wort, das in ihrem Gesetze steht, mußte in Erfüllung gehen: \'Sie haßten mich ganz ohne Grund.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Wenn dann der Beistand kommt, den ich euch vom Vater senden werde, der Geist der Wahrheit, der vom Vater ausgeht, so wird er Zeugnis über mich ablegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Auch ihr sollt Zeugnis ablegen, weil ihr von Anfang an bei mir seid,\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '\"Das habe ich euch gesagt, damit ihr nicht Anstoß nehmet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Man wird euch aus der Synagoge ausschließen; es kommt sogar die Stunde, da jeder, der euch tötet, meint, Gott einen Dienst zu erweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Sie werden so handeln, weil sie weder den Vater noch mich verstanden haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Dies habe ich euch gesagt, damit, wenn einmal die Stunde kommt, ihr euch an das erinnert, was ich euch gesagt habe. Ich habe bis jetzt nichts davon gesagt; ich war ja noch bei euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Nun gehe ich zu dem, der mich gesandt hat, und keiner aus euch fragt mich: \'Wohin gehst du?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Weil ich euch dies gesagt habe, hat Trauer euer Herz erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Jedoch ich sage euch die Wahrheit: Es ist gut für euch, wenn ich jetzt hingehe; denn wenn ich nicht hingehe, wird auch der Beistand nicht zu euch kommen. Doch gehe ich hin, so werde ich ihn euch senden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Wenn alsdann jener kommt, wird er der Welt es zum Bewußtsein bringen, was Sünde, was Gerechtigkeit, was Gericht ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Sünde, weil sie nicht an mich geglaubt hat;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Gerechtigkeit, weil ich zum Vater gehe und ihr mich nicht mehr sehen werdet;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Gericht, weil der Fürst dieser Welt gerichtet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Noch vieles hätte ich euch zu sagen, doch ihr könnt es jetzt noch nicht ertragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Wenn aber jener kommt, der Geist der Wahrheit, der wird euch in alle Wahrheit einführen. Er wird nicht von sich aus reden; er wird reden, was er hört, und euch die Zukunft künden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Er wird mich dann verherrlichen; er wird ja von dem Meinen empfangen und es euch verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alles, was der Vater hat, ist mein. Deshalb habe ich gesagt: Er wird von dem Meinigen empfangen und es euch verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Noch eine kleine Weile, dann sehet ihr mich nicht mehr, und nochmals eine kleine Weile, dann sehet ihr mich wieder denn ich gehe zum Vater.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Da sprachen einige seiner Jünger zueinander: \"Was soll das heißen, daß er sagt: \'Noch eine kleine Weile, dann sehet ihr mich nicht mehr, und wieder eine kleine Weile, dann sehet ihr mich wieder\'; sowie: \'Ich gehe zum Vater\'?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Sie fragten also: \"Was meint er mit der kleinen Weile; denn wir verstehen nicht, was er sagt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesus merkte, daß sie ihn fragen wollten; er sprach zu ihnen: \"Ihr fragt einander, weil ich sagte: Noch eine kleine Weile, dann sehet ihr mich nicht mehr, und nochmals eine kleine Weile, dann sehet ihr mich wieder?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Wahrlich, wahrlich, ich sage euch: Ihr werdet weinen und wehklagen, allein, die Welt wird sich freuen. Ihr werdet trauern, doch eure Trauer wird sich in Freude verwandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'So hat das Weib, wenn es gebiert, sein Leid, weil seine Stunde da ist; hat es jedoch das Kind geboren, so denkt es nicht mehr an die Angst aus Freude, daß ein Mensch zur Welt geboren ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'So habt auch ihr jetzt Leid. Doch ich werde euch wiedersehen, und euer Herz wird sich freuen, und eure Freude wird niemand von euch nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'An jenem Tage werdet ihr mich nichts mehr fragen. Wahrlich, wahrlich sage ich euch: Wenn ihr den Vater um etwas bitten werdet, so wird er es meines Namens wegen euch geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Bisher habt ihr um nichts in meinem Namen gebeten. Bittet, und ihr werdet empfangen, und eure Freude wird vollendet sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Dies habe ich in Gleichnissen zu euch geredet. Es kommt die Stunde, da will ich nicht mehr in Gleichnissen zu euch sprechen, vielmehr euch offen vom Vater Kunde geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'An jenem Tage werdet ihr in meinem Namen bitten; ich sage euch nicht: Ich will den Vater für euch bitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Der Vater selber liebt euch, weil ihr mich geliebt und weil ihr geglaubt habt, daß ich von Gott ausgegangen bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ich bin vom Vater ausgegangen und in die Welt gekommen, ich verlasse wiederum die Welt und gehe zum Vater.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Da sagten seine Jünger: \"Siehe, jetzt sprichst du offen und gebrauchst kein Gleichnis mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Jetzt wissen wir, daß du alles weißt und niemand dich zu fragen braucht. Deshalb glauben wir, daß du von Gott ausgegangen bist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Und Jesus sprach zu ihnen: \"Jetzt glaubt ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Seht, es kommt eine Stunde, ja, sie ist schon da, da ihr euch zerstreuen werdet, ein jeder in sein Haus, und mich allein lasset. Doch ich bin nicht allein; der Vater ist mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Das habe ich zu euch gesagt, auf daß ihr Frieden in mir habet. In der Welt leidet ihr Drangsal; doch seid getrost: Ich habe die Welt überwunden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'So sprach Jesus. Alsdann erhob er seine Augen gegen Himmel und betete: \"Vater, die Stunde ist gekommen; verherrliche Deinen Sohn, damit der Sohn dich verherrliche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Du hast ihm Macht verliehen über alles Fleisch, damit er allen, die du ihm anvertraut hast, ewiges Leben schenke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Das aber ist das ewige Leben: dich zu erkennen, den einzig wahren Gott, und den, den du gesandt hast, Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ich habe dich auf Erden verherrlicht; ich habe das Werk vollbracht, das du mir aufgetragen hast, daß ich es vollenden soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Und nun, Vater, verherrliche du mich bei dir mit der Herrlichkeit, die ich bei dir hatte, bevor die Welt entstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ich habe deinen Namen den Menschen kundgetan, die du mir aus der Welt gegeben hast. Dein waren sie, und du hast sie mir anvertraut, und sie haben dein Wort bewahrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nun wissen sie, daß alles, was du mir gegeben hast, von dir kommt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'daß ich die Worte, die du mir anvertraut hast, ihnen gegeben habe. Sie haben diese angenommen und haben wirklich erkannt, daß ich von dir ausgegangen bin, und haben geglaubt, daß du mich gesandt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Für sie bitte ich. Nicht für die Welt bitte ich; für die vielmehr, die du mir gegeben hast; sie sind ja dein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Denn alles Meinige ist dein, und all das Deinige ist mein. In ihnen bin ich verherrlicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Ich bin zwar nicht mehr in der Welt - sie sind noch in der Welt -, ich gehe zu dir. Heiliger Vater, erhalte sie in deinem Namen, den du mir gegeben hast, damit sie eins seien so wie wir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Solange ich bei ihnen war, habe ich sie in deinem Namen bewahrt, den du mir gegeben hast. Ich wachte, und kein einziger aus ihnen ist verlorengegangen, als nur der Sohn des Verderbens, damit die Schrift erfüllt würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Nun komme ich zu dir und rede dies in der Welt, damit sie meine Freude vollkommen in sich haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ich habe ihnen dein Wort gegeben; die Welt jedoch hat sie mit Haß verfolgt; denn sie sind nicht von dieser Welt, so wie auch ich nicht von der Welt bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ich bitte nicht: Nimm sie aus der Welt hinweg! sondern: Bewahre sie vor dem Bösen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Sie sind nicht von der Welt, so wie auch ich nicht von der Welt bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Weihe sie in Wahrheit! Dein Wort ist Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Wie du mich in die Welt gesandt hast, so sende auch ich sie in die Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Für sie weihe ich mich selbst, auf daß auch sie in Wahrheit geweiht seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Doch nicht für sie allein bitte ich, sondern auch für die, die durch ihr Wort den Glauben an mich finden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'damit alle eins seien: so wie du, Vater, in mir bist und ich in dir bin, daß sie in uns eins seien, damit die Welt glaube, daß du mich gesandt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Die Herrlichkeit, die du mir gegeben hast, habe ich ihnen gegeben, damit sie eins seien, wie wir eins sind:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ich in ihnen und du in mir, auf daß sie völlig eins seien, damit die Welt erkenne, daß du mich gesandt und sie geliebt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Vater, ich will, laß, die du mir gegeben hast, bei mir sein, wo ich bin, damit sie meine Herrlichkeit schauen, die du mir verliehen hast. Du hast mich ja vor der Grundlegung der Welt geliebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Gerechter Vater! Die Welt hat dich nicht verstanden. Ich aber habe dich verstanden, auch diese haben verstanden, daß du mich gesandt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Ich habe ihnen deinen Namen kundgetan und werde ihn ferner kund tun, damit die Liebe, mit der du mich geliebt hast, in ihnen sei und ich in ihnen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'So betete Jesus. Dann überschritt er mit seinen Jüngern den Bach Cedron. Hier war ein Garten, wohin er sich mit seinen Jüngern begab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Auch Judas, sein Verräter, wußte den Ort, weil Jesus oft mit seinen Jüngern dort zusammen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Und Judas nahm eine Abteilung Soldaten und Knechte von den Oberpriestern und den Pharisäern und ging dorthin mit Fackeln, Laternen und Waffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jesus aber, der alles wußte, was ihn treffen sollte, trat her und fragte sie: \"Wen suchet ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Sie sagten zu ihm: \"Jesus von Nazareth.\" Jesus erwiderte ihnen: \"Ich bin es.\" Auch Judas, sein Verräter stand dabei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Als er zu ihnen sagte: \"Ich bin es\", wichen sie zurück und stürzten zu Boden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Noch einmal fragte er sie: \"Wen suchet ihr?\" Und sie antworteten: \"Jesus von Nazareth.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus sprach: \"Ich habe es euch schon gesagt, daß ich es bin; wenn ihr also mich sucht, so lasset diese gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'So sollte das Wort erfüllt werden, das er gesprochen hatte: \"Ich habe von denen, die du mir anvertraut hast, nicht einen einzigen verloren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Und Simon Petrus, der ein Schwert hatte, zog es heraus und schlug damit auf den Knecht des Hohenpriesters ein und hieb ihm das rechte Ohr ab. Der Knecht hieß Malchus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Da sprach Jesus zu Petrus: \"Stecke dein Schwert in die Scheide! Soll ich den Kelch nicht trinken, den mir der Vater dargereicht hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Die Abteilung mit ihrem Hauptmann und den Knechten der Juden ergriffen Jesus, fesselten ihn');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'und führten ihn zunächst zu Annas. Er war der Schwiegervater des Kaiphas, der in jenem Jahre Hoherpriester war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kaiphas war es auch gewesen, der den Juden einst geraten hatte, es sei am besten, wenn ein Mensch für das Volk sterbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Petrus und ein anderer Jünger folgten Jesus. Dieser Jünger war dem Hohenpriester wohl bekannt und konnte so mit Jesus in den Hof des Hohenpriesters gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Doch Petrus blieb vor dem Tore draußen stehen. Da ging der andere Jünger, der mit dem Hohenpriester bekannt war, hinaus, sprach mit der Türhüterin und holte Petrus herein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Die Türhüterin, eine Magd, fragte den Petrus: \"Gehörst etwa auch du zu den Jüngern dieses Menschen?\" Er sagte: \"Nein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Die Knechte und Gerichtsdiener hatten ein Kohlenfeuer angezündet und standen daran herum und wärmten sich; denn es war kalt. Auch Petrus stand bei ihnen und wärmte sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Der Hohepriester fragte Jesus nach seinen Jüngern und nach seiner Lehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus sprach zu ihm: \"Ich habe offen zur Welt geredet; ich habe allerorten gelehrt, in Synagogen und im Heiligtum, wohin alle Juden kommen; nichts habe ich im Verborgenen geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Was fragst du mich? Frage jene, die gehört haben, was ich ihnen gesagt habe. Die wissen es ja, was ich geredet habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Auf diese Worte hin schlug einer der Knechte, der daneben stand, ihn mit einem Stock ins Gesicht und rief: \"So antwortest du dem Hohenpriester?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Darauf entgegnete ihm Jesus: \"Habe ich unrecht geredet, so beweise das Unrechte; doch habe ich recht geredet, warum schlägst du mich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Dann schickte ihn Annas gefesselt zum Hohenpriester Kaiphas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petrus stand noch da und wärmte sich. Da sagte man zu ihm: \"Bist nicht auch du einer aus seinen Jüngern?\" Er leugnete und sagte: \"Nein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Da sagte einer von den Knechten des Hohenpriesters, ein Verwandter dessen, dem Petrus das Ohr abgehauen hatte: \"Habe ich dich nicht bei ihm im Garten gesehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Und Petrus leugnete es wieder. Da krähte gleich darauf ein Hahn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Von Kaiphas führten sie Jesus ins Gerichtsgebäude. Es war noch früh am Morgen. Sie selbst betraten das Gerichtsgebäude nicht, damit sie nicht unrein würden und noch das Paschamahl essen könnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Deswegen ging Pilatus zu ihnen hinaus und fragte: \"Welche Anklage erhebt ihr gegen diesen Menschen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Sie gaben ihm zur Antwort: \"Wenn dieser kein Verbrecher wäre, so hätten wir ihn dir nicht ausgeliefert\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilatus sprach zu ihnen: \"Dann nehmt ihn und richtet ihn nach eurem Gesetz.\" Darauf erwiderten ihm die Juden: \"Wir dürfen niemand hinrichten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'So sollte sich das Wort Jesu erfüllen, mit dem er seine Todesart angekündigt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilatus trat wieder ins Gerichtsgebäude, ließ Jesus kommen und fragte ihn: \"Bist du der König der Juden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus gab zur Antwort: \"Fragst du das aus dir selbst, oder haben es dir andere von mir behauptet?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus sprach: \"Bin ich denn ein Jude? Dein Volk und die Oberpriester haben dich mir übergeben; was hast du verbrochen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Und Jesus sprach: \"Mein Reich ist nicht von dieser Welt. Wenn mein Reich von dieser Welt wäre, so hätten meine Anhänger gekämpft, auf daß ich nicht den Juden ausgeliefert würde. So aber ist mein Reich nicht von hier.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Da sagte Pilatus zu ihm: \"So bist du also doch ein König?\" Jesus erwiderte: \"Du sagst, ich sei ein König. Ich bin dazu geboren und dazu in die Welt gekommen, um für die Wahrheit Zeugnis abzulegen. Wer immer aus der Wahrheit stammt, der hört auf meine Stimme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Da sprach Pilatus zu ihm: \"Was ist Wahrheit?\" Nach diesen Worten ging er wieder zu den Juden hinaus und sprach zu ihnen: \"Ich finde keine Schuld an ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Jedoch bei euch besteht der Brauch, daß ich euch am Osterfest einen freigebe. Soll ich euch den König der Juden freigeben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Da schrien sie wiederum laut: \"Nein, den nicht, sondern den Barabbas.\" Barabbas war aber ein Räuber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Pilatus behielt Jesus und ließ ihn geißeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Und die Soldaten flochten eine Krone aus Dornen und setzten sie ihm auf das Haupt und legten ihm einen Purpurmantel um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Dann traten sie vor ihn hin und riefen: \"Heil dir, du König der Juden!\" und gaben ihm Stockschläge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilatus ging jetzt wiederum hinaus und sprach zu ihnen: \"Seht her, ich führe ihn euch vor, daß ihr es erkennt, daß ich keine Schuld an ihm finde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Und Jesus kam heraus; er trug die Dornenkrone und den Purpurmantel. Pilatus sprach zu ihnen: \"Seht da den Menschen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Doch als die Oberpriester und die Knechte ihn so sahen, schrien sie: \"Ans Kreuz, ans Kreuz!\" Pilatus sprach zu ihnen: \"Dann nehmt ihn und kreuzigt ihn! Ich finde keine Schuld an ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Darauf entgegneten ihm die Juden: \"Wir haben ein Gesetz; nach dem Gesetz muß er sterben; er hat sich selbst zum Sohne Gottes erklärt!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Als Pilatus diese Worte hörte, befiel ihn noch größere Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Er ging wieder ins Gerichtshaus und fragte Jesus: \"Woher bist du?\" Doch Jesus gab ihm keine Antwort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilatus sprach zu ihm: \"Mir gibst du keine Antwort? Weißt du nicht, daß ich Macht habe, dich freizulassen, und auch Macht, dich kreuzigen zu lassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus sprach zu ihm: \"Du würdest über mich keine Macht besitzen, wenn sie dir nicht von oben gegeben wäre. Deshalb hat der die größere Sünde, der mich dir preisgegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Auf dies hin suchte Pilatus ihn freizugeben. Die Juden aber schrien: \"Wenn du diesen freigibst, dann bist du kein Freund des Kaisers; jeder, der sich für einen König ausgibt, der lehnt sich gegen den Kaiser auf.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Als Pilatus diese Worte hörte, ließ er Jesus herbeiführen und setzte sich auf dem Platz, der Lithostrotos, hebräisch Gabbatha, genannt wird, auf den Richterstuhl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Es war der Rüsttag des Osterfestes, um die sechste Stunde. Da sprach er zu den Juden: \"Seht euren König.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Doch diese schrien: \"Hinweg, hinweg; ans Kreuz mit ihm!\" Da fragte sie Pilatus: \"Euren König soll ich kreuzigen?\" Die Oberpriester aber schrien: \"Wir haben keinen König, nur den Kaiser.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Da übergab er ihnen Jesus zur Kreuzigung. Sie übernahmen Jesus und führten ihn hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Er trug sein Kreuz und ging hinaus zum Ort, der Schädelstätte heißt; hebräisch heißt er Golgotha.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Dort kreuzigten sie ihn und mit ihm noch zwei andere rechts und links, Jesus aber in der Mitte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus hatte eine Inschrift schreiben und ans Kreuz anheften lassen. Sie lautete: \"Jesus von Nazareth, der König der Juden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Diese Inschrift lasen viele von den Juden - der Ort, wo Jesus gekreuzigt worden war, lag nämlich nahe bei der Stadt -; sie war hebräisch, römisch und griechisch abgefaßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Die Oberpriester der Juden sprachen zu Pilatus.- \"Schreibe nicht: \'Der König der Juden\', vielmehr: \'Er hat gesagt, ich bin der König der Juden\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus sprach: \"Was ich geschrieben habe, bleibt geschrieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Als die Soldaten Jesus gekreuzigt hatten, nahmen sie seine Kleider und machten vier Teile daraus, für jeden Soldaten einen Teil; dazu den Leibrock. Der Leibrock war aber ohne Naht, von oben her in einem Stück gewebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Sie sprachen zueinander: \"Wir wollen ihn nicht zerteilen, vielmehr um ihn losen, wem er gehören soll.\" So sollte in Erfüllung gehen, was in der Schrift geschrieben steht: \"Sie teilen meine Kleider unter sich und werfen über mein Gewand das Los.\" Dies taten denn auch die Soldaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Beim Kreuze Jesu standen seine Mutter, sowie die Schwester seiner Mutter, Maria, die Frau des Kleophas, und Maria Magdalena.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Als Jesus seine Mutter und den Jünger, den er liebte, dastehen sah, sprach er zu seiner Mutter: \"Weib, siehe dein Sohn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Dann sprach er zu dem Jünger: \"Siehe, deine Mutter.\" Und von jener Stunde an nahm sie der Jünger bei sich auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Weil Jesus wußte, daß jetzt alles vollbracht war, sprach er, damit die Schrift erfüllt würde, weiter: \"Mich dürstet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Nun stand ein Gefäß voll Essig da. Man steckte einen Schwamm voll Essig auf einen Hysopstengel und hielt ihm diesen an den Mund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Und Jesus kostete den Essig; alsdann sprach er: \"Es ist vollbracht.\" Dann neigte er das Haupt und gab den Geist auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Es war Rüsttag. Da sollten die Leichen nicht über den Sabbat am Kreuze bleiben; denn jener Sabbat war ein ganz besonders hoher Tag. Deswegen baten die Juden den Pilatus, man möchte jenen ihre Gliedmaßen zerschlagen und sie herabnehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'So kamen die Soldaten und zerschlugen dem einen seine Glieder und auch dem anderen, der mit ihm gekreuzigt worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Als sie zu Jesus kamen, sahen sie, daß er schon tot war, und so zerschlugen sie ihm die Glieder nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Doch stieß ihm einer der Soldaten seine Lanze in die Seite, und sogleich floß Blut und Wasser heraus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Dies erzählt ein Augenzeuge, dessen Zeugnis durchaus wahr ist, und er weiß, daß er die Wahrheit sagt, damit auch ihr glaubet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Dies ist geschehen, damit die Schrift erfüllt würde: \"Ihm soll kein Bein zerbrochen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'sowie die andere Schriftstelle: \"Sie blicken auf zu dem, den sie durchbohrt haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Joseph von Arimathäa, ein Jünger Jesu - nur im geheimen freilich; er hatte vor den Juden Angst -, bat Pilatus, den Leichnam Jesu abnehmen zu dürfen. Pilatus gab ihm die Erlaubnis. Er ging hin und nahm den Leichnam ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Auch Nikodemus, der einst zur Nachtzeit bei ihm war, kam und brachte eine Mischung Myrrhe und Aloe mit, an hundert Pfund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Sie nahmen den Leichnam Jesu und wickelten ihn samt den Spezereien in Linnentücher ein, so wie es bei den Juden beim Bestatten Brauch ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'An dem Ort, wo er gekreuzigt worden war, war ein Garten, und in dem Garten ein neues Grab, in das noch niemand gelegt worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Dorthin legten sie Jesus des Rüsttags der Juden wegen und weil das Grab so nahe war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Am ersten Tag der Woche ging Maria Magdalena zum Grabe früh am Morgen, als es noch dunkel war; sie sah, daß der Stein vom Grab weggewälzt war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Sie lief zu Simon Petrus und zu dem anderen Jünger, zu dem, den Jesus liebte, und sprach zu ihnen: \"Man hat den Herrn aus dem Grabe weggenommen, wir wissen nicht, wohin man ihn gelegt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Da gingen Petrus und der andere Jünger hin und kamen zum Grabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Sie beide liefen miteinander hin; aber der andere Jünger lief schneller als Petrus und kam zuerst am Grab an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Er beugte sich vor und sah die Linnentücher daliegen, ging aber nicht hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Darauf kam Simon Petrus nach ihm an und ging ins Grab hinein. Er sah die Linnentücher daliegen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'und auch das Schweißtuch, das auf seinem Haupte gelegen hatte. Dieses lag nicht bei den Linnentüchern; vielmehr lag es gefaltet für sich besonders.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Jetzt ging der andere Jünger, der zuerst am Grabe angekommen war, auch hinein, er sah und glaubte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Denn noch hatten sie die Schrift nicht verstanden, daß er von den Toten auferstehen müsse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Die Jünger gingen dann nach Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Maria aber stand am Grabe draußen und weinte. Wie sie so weinte, neigte sie sich in das Grab hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Und da erblickte sie zwei Engel dasitzen in weißen Kleidern, den einen zu Häupten und den anderen zu Füßen, wo der Leib Jesu gelegen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Sie fragten sie: \"Weib, was weinst du?\" Sie sprach zu ihnen. \"Man hat meinen Herrn weggenommen, und ich weiß nicht, wohin man ihn gelegt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Dann wandte sie sich um und sah, wie Jesus vor ihr stand; sie wußte aber nicht, daß es Jesus war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Und Jesus sprach zu ihr: \"Weib, was weinst du? Wen suchst du?\" Im Glauben, es sei der Gärtner, gab sie ihm zur Antwort: \"Herr, wenn du ihn fortgetragen hast, sag mir, wohin du ihn gelegt hast; alsdann will ich ihn holen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesus sprach zu ihr: \"Maria.\" Da wandte sie sich um und sprach zu ihm hebräisch: \"Rabboni\" - d.h. Meister.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Doch Jesus sprach zu ihr: \"Halte mich nicht fest: noch bin ich nicht zum Vater aufgefahren. Geh aber hin zu meinen Brüdern und sage ihnen: \'Ich fahre auf zu meinem Vater und zu eurem Vater, zu meinem Gott und zu eurem Gott.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Da ging Maria Magdalena hin und verkündete den Jüngern, sie habe den Herrn gesehen, und das habe er zu ihr gesagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Es war schon spät an diesem ersten Wochentag. Die Jünger hatten an dem Ort, wo sie versammelt waren, aus Furcht vor den Juden die Türen fest verschlossen. Da kam Jesus, er trat mitten unter sie und sprach: \"Friede sei mit euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Nach diesen Worten zeigte er ihnen seine Hände und seine Seite. Die Jünger freuten sich, als sie den Herrn sahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Und abermals sprach Jesus zu ihnen: \"Friede sei mit euch! Wie mich der Vater gesandt hat, so sende ich euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Nach diesen Worten hauchte er sie an und sprach: \"Empfanget den Heiligen Geist!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Welchen ihr die Sünden nachlasset, denen sind sie nachgelassen, und welchen ihr sie behaltet, denen sind sie behalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Thomas, der \"Zwilling\", einer aus den Zwölfen, befand sich nicht bei ihnen, als Jesus kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Die anderen Jünger sagten zu ihm: \"Wir haben den Herrn gesehen.\" Er aber sprach zu ihnen: \"Wenn ich an seinen Händen nicht das Mal der Nägel sehe und meine Finger nicht in die Wundmale legen kann und meine Hand in seine Seite, kann ich nicht glauben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Acht Tage später waren die Jünger wieder in dem Haus versammelt; auch Thomas war bei ihnen. Jesus kam bei verschlossenen Türen, trat mitten unter sie und sprach: \"Friede sei mit euch!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Dann sagte er zu Thomas: \"Lege deinen Finger her und sieh meine Hände; reiche deine Hand und lege sie in meine Seite und sei nicht ungläubig, sondern gläubig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Und Thomas rief: \"Mein Herr und mein Gott!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Und Jesus sprach zu ihm: \"Weil du mich gesehen hast Thomas, deshalb glaubst du. Selig, die nicht sahen und dennoch glaubten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jesus hat vor den Augen seiner Jünger noch viele andere Zeichen getan, die nicht in diesem Buche aufgezeichnet sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Diese hier sind aber aufgezeichnet, damit ihr glaubt, daß Jesus der Christus, der Sohn Gottes ist und damit ihr durch den Glauben Leben habt in seinem Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Später offenbarte sich Jesus noch einmal seinen Jüngern am Meere von Tiberias, und zwar offenbarte er sich auf diese Weise:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Petrus, der \"Zwilling\" Thomas, Nathanael aus Kana in Galiläa, die Söhne des Zebedäus und zwei andere seiner Jünger waren beieinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Und Simon Petrus sprach zu ihnen: \"Ich gehe fischen.\" Sie sagten zu ihm: \"Wir gehen auch mit.\" Da gingen sie hinaus und stiegen in das Boot, sie fingen aber nichts in jener Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Schon dämmerte der Morgen, da stand Jesus am Ufer. Die Jünger wußten aber nicht, daß es Jesus war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Und Jesus sprach zu ihnen: \"Kinder, habt ihr keinen Fisch?\" \"Nein\", sagten sie zu ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Hierauf sprach er zu ihnen: \"So werft das Netz aus, rechts vom Boote, dann werdet ihr etwas bekommen.\" Sie warfen es aus und vermochten es vor der Menge der Fische nicht heraufzuziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Da sprach der Jünger, den Jesus liebte, zu Petrus: \"Es ist der Herr.\" Als Simon Petrus hörte: \"Es ist der Herr\", legte er sich das Oberkleid über - er war nämlich unbekleidet - und sprang ins Meer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Die anderen Jünger kamen im Boote nach; sie waren nicht weit vom Land entfernt, etwa zweihundert Ellen. Sie zogen das mit Fischen angefüllte Netz hinter sich her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Sie stiegen ans Land und sahen ein Kohlenfeuer angelegt, darüber einen Fisch und Brot dabei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Und Jesus sprach zu ihnen: \"Bringt von den Fischen, die ihr jetzt gefangen habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Und Simon Petrus stieg ins Boot und zog das Netz ans Land, mit hundertdreiundfünfzig großen Fischen angefüllt. Obwohl es so viele waren, zerriß das Netz doch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Und Jesus sprach zu ihnen: \"Kommt her und frühstückt!\" Und keiner von den Jüngern wagte zu fragen: \"Wer bist du?\" Sie wußten ja, daß es der Herr sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Und Jesus nahm sogleich das Brot und gab es ihnen, ebenso den Fisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Das war bereits das dritte Mal, daß Jesus nach seiner Auferstehung von den Toten sich seinen Jüngern geoffenbart hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Nach jenem Frühstück fragte Jesus den Simon Petrus: \"Simon, Sohn des Johannes, liebst du mich mehr als diese?\" Er sprach zu ihm: \"Ja, Herr, du weißt, daß ich dich liebe.\" Da sagte er zu ihm: \"Weide meine Lämmer!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Und er fragte ihn ein zweites Mal: \"Simon, Sohn des Johannes, liebst du mich?\" Er sprach zu ihm: \"Ja, Herr, du weißt, daß ich dich liebe.\" Er sprach zu ihm: \"Weide meine Schafe!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Er fragte ihn noch ein drittes Mal: \"Simon, Sohn des Johannes, liebst du mich?\" Da wurde Petrus traurig, daß er ihn zum drittenmal fragte: \"Liebst du mich?\" Er sprach zu ihm: \"Herr, du weißt alles, du weißt auch, daß ich dich liebe.\" Und Jesus sprach zu ihm: \"Weide meine Schafe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wahrlich, wahrlich, ich sage dir: Als du noch jung warst, hast du dich selbst gegürtet und bist gegangen, wohin du wolltest. Wenn du aber alt geworden bist, dann wirst du deine Hände ausstrecken; ein anderer wird dich gürten und dich dahin führen, wohin du nicht willst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Mit diesen Worten deutete er an, durch welche Todesart er Gott verherrlichen werde. Dann sagte er zu ihm: \"Folge mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Und Petrus wandte sich um und sah, wie der Jünger, den Jesus liebte, ihm folgte. Es war derselbe, der beim Abendmahl, an seine Brust gelehnt, gefragt hatte: \"Herr, wer ist es, der dich verrät?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Als Petrus ihn sah, sprach er zu Jesus: \"Herr, was ist mit diesem?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Und Jesus sprach zu ihm: \"Wenn ich will, daß er bleibe, bis ich komme, was geht das dich an? Du sollst mir folgen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Daher kam das Gerede bei den Brüdern auf, jener Jünger sterbe nicht. Doch Jesus hatte nicht zu ihm gesagt: \"Er stirbt nicht\", sondern: \"Wenn ich will, daß er bleibe, bis ich komme, was geht das dich an?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Das ist der Jünger, der dies bezeugt und geschrieben hat. Wir wissen, daß sein Zeugnis wahr ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Noch gibt es vieles andere, was Jesus getan hat. Wollte man das alles einzeln niederschreiben, so könnte, meine ich, die Welt die Bücher nicht fassen, die dann zu schreiben wären.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Lieber Theophilus! In meiner ersten Schrift habe ich von allem erzählt, was Jesus tat und lehrte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'bis zu jenem Tage, da er in den Himmel aufgenommen ward, nachdem er den Aposteln, die er sich durch den Heiligen Geist auserwählt hatte, seinen Willen kundgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Diesen hatte er sich auch nach seinem Leiden als lebendig dargestellt durch vielerlei Beweise: Vierzig Tage hindurch erschien er ihnen, wobei er ihnen über alles Aufschluß gab, was das Reich Gottes betrifft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Als er mit ihnen noch zusammen war, befahl er ihnen, von Jerusalem nicht wegzugehen, sondern abzuwarten, was der Vater verheißen hat: \"Was ihr von mir gehört habt so sprach er:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, '\"Johannes hat zwar mit Wasser getauft, ihr aber sollt in eben diesen Tagen mit dem Heiligen Geiste getauft werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Die zusammengekommen waren, fragten ihn: \"Herr, wirst du in dieser Zeit die Königsherrschaft in Israel wiederherstellen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Doch er sprach zu ihnen: \"Nicht eure Sache ist es, Zeit und Stunde zu erfahren die der Vater in seiner Machtvollkommenheit festgesetzt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Ihr werdet jedoch Kraft empfangen, wenn der Heilige Geist über euch herabkommt, und ihr werdet für mich zu Zeugen werden in Jerusalem, in ganz Judäa und in Samaria, ja, bis an die Grenzen der Erde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Nach diesen Worten ward er vor ihren Augen emporgehoben, und eine Wolke entrückte ihn ihren Blicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Unverwandten Auges schauten sie gen Himmel, während er emporfuhr. Doch siehe, da standen zwei Männer in weißen Gewändern bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Sie sprachen: \"Ihr Galiläer! Was steht ihr da und schaut zum Himmel hinauf? Dieser Jesus, der aus eurer Mitte in den Himmel aufgenommen ward, wird in derselben Weise wiederkommen, wie ihr ihn in den Himmel habt auffahren sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Darauf kehrten sie von dem Berge, der Ölberg heißt und nahe bei Jerusalem liegt, einen Sabbatweg entfernt, nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Dort angekommen, begaben sie sich in das Obergemach, wo sie blieben: nämlich Petrus und Johannes, Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, der Sohn des Alphäus, und Simon, der Eiferer, und Judas, der Bruder des Jakobus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Sie alle verharrten einmütig im Gebet mit den Frauen, mit Maria, der Mutter Jesu, und mit seinen Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'In jenen Tagen erhob sich Petrus inmitten der Brüder - es war eine Menge von ungefähr einhundertzwanzig Personen beisammen - und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '\"Liebe Brüder! Das Schriftwort mußte in Erfüllung gehen, das der Heilige Geist durch den Mund Davids über Judas vorhergesagt, der den Häschern Jesu den Weg gezeigt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Er gehörte einst zu uns und hatte teil an diesem Amt erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Um seinen Sündenlohn erwarb er sich einen Acker, fiel dann kopfüber ab und barst entzwei, und alle seine Eingeweide quollen hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Und dies erfuhren alle Einwohner Jerusalems; darum nannten sie in ihrer Sprache jenen Acker: Hakeldama, d.h. Blutacker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Heißt es doch im Buch der Psalmen: \'Seine Wohnstatt werde öde, und niemand sei, der darin wohne!\' Und dann: \'Sein Amt soll ein anderer erhalten!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'So muß denn einer von den Männern, die bei uns waren in der ganzen Zeit, da der Herr Jesus bei uns ein- und ausging,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'angefangen von der Taufe des Johannes bis zu dem Tage, da er von uns hinweg aufgenommen ward, es muß von diesen einer mit uns Zeuge seiner Auferstehung werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Sie stellten zwei vor: Joseph, genannt Barsabas, mit dem Beinamen Justus, und Matthias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Und sie beteten: \"O Herr, Du kennst die Herzen aller, zeige an, wen von diesen beiden Du erwählt hast,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'die Stelle dieses Dienstes und Apostelamtes zu erhalten, von dem Judas abgefallen war, um an seinen Ort zu gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Dann warfen sie das Los für sie, und das Los fiel auf Matthias. Er wurde den elf Aposteln beigezählt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'So war das Pfingstfest herangekommen. Alle waren an demselben Ort beisammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Plötzlich erhob sich vom Himmel her ein Brausen, als ob ein gewaltiger Wind daherkäme, und erfüllte das ganze Haus, in dem sie saßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Es erschienen ihnen Zungen, wie von Feuer, die sich verteilten und sich auf jeden einzelnen unter ihnen niederließen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Alle wurden voll des Heiligen Geistes und begannen, in fremden Sprachen zu reden, wie es der Heilige Geist ihnen verlieh zu sprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'In Jerusalem wohnten aber Juden, gottesfürchtige Männer, aus allen Völkern unter dem Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Als sich nun dieses Brausen erhob, lief die Menge zusammen und wurde bestürzt, weil ein jeder sie in seiner Muttersprache reden hörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Außer sich vor Verwunderung riefen sie: \"Sind denn nicht alle, die da reden, Galiläer?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Wie mag es denn geschehen, daß jeder aus uns sie in seiner Muttersprache reden hört?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Wir Parther, Meder und Elamiter, und wir, die wir Mesopotamien bewohnen. Judäa und Kappadozien, Pontus und Asien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Phrygien und Pamphilien, Ägypten und den Landstrich Lybiens bis nach Cyrene hin, wir Pilger aus Rom,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Juden und Proselyten, wir Kreter und Araber, wir hören sie in unseren Sprachen die großen Taten Gottes verkünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Alle waren außer sich vor Staunen und sprachen zueinander: \"Was mag das wohl sein?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Andere dagegen spotteten und sagten: \"Sie sind voll süßen Weines.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Da trat Petrus samt den Elfen vor, erhob seine Stimme und redete sie begeistert an: \"Ihr Männer von Judäa und ihr alle, die ihr in Jerusalem zu Hause seid! Dies sei euch kundgetan! Vernehmet meine Worte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Die da sind nicht betrunken, wie ihr meint; es ist ja erst die dritte Stunde des Tages.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Vielmehr erfüllt sich hier, was der Prophet Joel vorhergesagt hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '\'Ich werde in den letzten Tagen,\' so spricht Gott, \'von meinem Geist über alles Fleisch ausgießen. Da werden eure Söhne und eure Töchter prophezeien; eure Jünglinge werden Gesichte schauen und eure Greise Traumgesichte haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Sogar über meine Sklaven und meine Sklavinnen will ich in jenen Tagen von meinem Geist ausgießen, und sie werden prophezeien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Ich werde Wunder tun am Himmel droben, und auf der Erde unten Zeichen: Blut, Feuer, Qualm und Rauch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Die Sonne wird sich in Finsternis wandeln, der Mond in Blut, bevor der große und erhabene Tag des Herrn kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Doch wer den Namen des Herrn anruft, wird gerettet werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Ihr Männer Israels! Vernehmet diese Worte: Jesus von Nazareth, ein Mann, der von Gott für euch durch Taten voll Allmacht, durch Wunder und durch Zeichen beglaubigt ward, die Gott - das wißt ihr ja selbst - durch ihn mitten unter euch vollbracht hat, ihn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'der durch Gottes festgesetzten Ratschluß und Vorherwissen ausgeliefert ward, ihn habt ihr durch die Hände der Gesetzeslosen ans Kreuz geschlagen und getötet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Gott aber hat die Wehen des Todes gelöst und ihn auferweckt; wie es ja auch nicht möglich war, daß der Tod über ihn die Macht behielt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Sagt doch schon David mit Bezug auf ihn: \'Allzeit schaue ich den Herrn vor mir; er steht zu meiner Rechten, auf daß ich nicht wanke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Darum frohlockte laut mein Herz, und meine Zunge jubelte, und auch mein Fleisch wird voller Hoffnung ruhen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'denn du wirst meine Seele nicht dem Totenreich preisgeben und deinem Heiligen nicht die Verwesung zu schauen geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du lehrst mich des Lebens Wege, erfüllst mich vor deinem Angesicht mit Wonne.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '\"Meine Brüder! Ganz offen darf ich über unseren Patriarchen David vor euch reden; er starb und ward begraben; sein Grabmal ist hier bei uns bis auf den heutigen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Er war ja ein Prophet und hat gewußt, daß Gott mit einem Eid ihm verheißen hatte, er werde einstens einen seiner Nachkommen auf seinen Thron erheben das heißt, daß Christus leiblich auferstehen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'So schaut und kündet er zum voraus Christi Auferstehung; dieser wird nicht im Totenreich verbleiben noch wird sein Fleisch Verwesung erfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Diesen Jesus hat Gott auferweckt; dessen sind wir alle Zeugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Er ward erhöht durch Gottes Rechte, empfing vom Vater den verheißenen Heiligen Geist, den er ausgegossen hat, wie ihr jetzt seht und hört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Denn nicht David stieg zum Himmel auf, und doch sagt er: \'Es sprach der Herr zu meinem Herrn; setze dich zu meiner Rechten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'bis ich deine Feinde zum Schemel deiner Füße mache.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'So soll denn das ganze Haus Israel mit aller Sicherheit erkennen, daß Gott gerade diesen Jesus, den ihr gekreuzigt habt, zum Herrn und Christus gemacht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Als sie dies hörten, ging ein Stich ihnen durchs Herz, und sie sprachen zu Petrus und den anderen Aposteln: \"Liebe Brüder, was sollen wir tun?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Petrus sprach zu ihnen: \"Bekehret euch! Jeder von euch lasse sich taufen auf den Namen Jesu Christi für die Vergebung eurer Sünden, damit ihr die Gabe des Heiligen Geistes empfanget.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Die Verheißung gilt euch und euren Kindern und all denen, die noch ferne sind, so viele auch der Herr unser Gott berufen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Noch mit vielen weiteren Worten beschwor und ermahnte er sie: \"Laßt euch erretten von diesem ganz verdorbenen Geschlecht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Die nun sein Wort bereitwillig annahmen, wurden getauft, und an jenem Tage kamen gegen dreitausend Seelen hinzu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Sie hielten fest an der Lehre der Apostel und an der Gemeinschaft, am Brotbrechen und am Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Furcht ergriff alle Herzen; denn viele Wunder und Zeichen geschahen durch die Apostel in Jerusalem, so daß große Furcht auf allen lag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Alle Gläubigen hielten zusammen und betrachteten all ihre Habe als gemeinsames Eigentum;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'auch verkauften sie dann und wann ihr Hab und Gut und verteilten den Erlös an alle, je nach Bedürfnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Täglich verharrten sie einmütig im Tempel, brachen in den einzelnen Häusern das Brot und genossen ihre Speisen in stolzer Freudigkeit und Einfalt des Herzens;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Sie priesen Gott und waren beim ganzen Volk beliebt. Täglich führte der Herr ihnen neue zu, die gerettet werden sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Petrus und Johannes gingen zum Tempel hinauf; es war um die neunte Gebetsstunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Da trug man eben einen Mann daher, der von Geburt an lahm war. Tag für Tag setzte man ihn an das sogenannte \"Schöne Tor\" des Tempels, damit er sich von den Tempelbesuchern ein Almosen erbetteln solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Als er Petrus und Johannes sah, wie sie eben in den Tempel hineingehen wollten, bat er sie um ein Almosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Petrus und zugleich Johannes sah ihn scharf an und sprach: \"Schau auf uns her!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Er sah gespannt auf sie in der Meinung, etwas von ihnen zu bekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Petrus aber sprach: \"Silber und Gold habe ich nicht, doch was ich habe, gebe ich dir: Im Namen Jesu Christi von Nazareth steh auf und geh umher!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Damit faßte er ihn an seiner rechten Hand und richtete ihn auf. Sogleich kam Kraft in seine Füße und Knöchel;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'er sprang auf und konnte stehen; er wandelte umher und begab sich mit ihnen in den Tempel, lief, sprang umher und lobte Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Alles Volk sah, wie er umherging und Gott lobte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Sie erkannten ihn als denselben, der des Almosens halber am \"Schönen Tor\" des Tempels gesessen hatte, und wurden voll von Staunen und Verwunderung über den Vorfall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Er hielt sich zu Petrus und Johannes, und alles Volk lief außer sich vor Staunen zu ihnen in die sogenannte Halle Salomons.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Als Petrus dies sah, sprach er zum Volke: \"Ihr Männer Israels! Was wundert ihr euch über diesen hier, oder was seht ihr uns so staunend an, als hätten wir es aus eigener Kraft und Frömmigkeit soweit gebracht, daß dieser gehen kann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Der Gott Abrahams, Isaaks und Jakobs, der Gott unserer Väter, hat Jesus, seinen Knecht, verherrlicht. Ihr freilich habt ihn ausgeliefert und vor Pilatus verworfen, als dieser ihn freilassen wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Den Heiligen und Gerechten habt ihr verworfen und verlangt, man solle euch den Mörder schenken;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'den Fürsten des Lebens aber habt ihr gemordet. Doch Gott hat ihn von den Toten erweckt; dessen sind wir Zeugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Sein Name hat jetzt diesem da, den ihr seht und kennt, auf Grund des Glaubens an diesen seinen Namen Kraft verliehen. Und dieser Glaube, der durch ihn zustande kommt, gab ihm auch die volle Gesundheit zurück, wie ihr jetzt alle seht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Wohlan denn, meine Brüder, ich weiß, ihr habt es nur aus Unwissenheit getan, so wie auch eure Obern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Gott aber hat auf diese Art erfüllt, was er durch den Mund aller Propheten vorherverkündet hat, daß sein Christus werde leiden müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'So tut denn Buße und bekehret euch, damit eure Sünden nachgelassen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Dann werden Zeiten der Erquickung durch die Gnade des Herrn kommen, er wird Christus Jesus senden, der für euch vorherbestimmt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Ihn mußte zwar der Himmel erst aufnehmen, bis daß die Zeit gekommen wäre, da alles soll wiederhergestellt werden, wovon Gott durch den Mund seiner uralten heiligen Propheten geredet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Moses ist es, der da sagte: \'Einen Propheten wird für euch der Herr und unser Gott erwecken aus der Mitte eurer Brüder wie mich. Hört auf ihn in allem, was immer er euch sagen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Wer aber nicht auf den Propheten hört, der soll aus dem Volke ausgerottet werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Auch alle anderen Propheten von Samuel an und später, so viele ihrer auch geredet haben, haben eben diese Tage verkündet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ihr seid die Söhne der Propheten, und ihr gehört dem Bund an, den Gott mit euren Vätern einst geschlossen hat, als er zu Abraham sprach: \'Alle Geschlechter der Erde sollen sich in deinem Stamme segnen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Für euch vor allem hat Gott seinen Knecht auferweckt und gesandt, daß er euch segne unter der Bedingung, daß sich ein jeder von seiner Schlechtigkeit bekehre.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Während sie noch so zum Volke redeten, traten die Priester, der Hauptmann der Tempelwache und die Sadduzäer auf sie zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Sie waren unwillig, weil sie das Volk lehrten und unter Hinweis auf Jesus die Auferstehung der Toten verkündeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Sie legten Hand an sie und gaben sie in Gewahrsam bis zum anderen Tage; denn es war bereits Abend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Viele aber von denen, die die Rede gehört hatten, wurden gläubig, und so stieg die Zahl der Männer auf ungefähr fünftausend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Am folgenden Morgen versammelten sich die Obersten, die Ältesten und die Schriftgelehrten in Jerusalem,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'auch der Hohepriester Annas, Kaiphas, Johannes und Alexander und wer sonst noch zum Priesteradel gehörte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Man ließ Petrus und Johannes vorführen und fragte sie: \"Mit welcher Vollmacht und in wessen Namen habt ihr dies getan?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Da sprach Petrus, erfüllt vom Heiligen Geiste, zu ihnen: \"Oberste des Volkes und Älteste höret');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Wenn wir heute wegen einer Wohltat, die wir einem kranken Mann erwiesen haben, jetzt darüber vernommen werden, durch wen er gesund geworden sei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'so sei euch allen und dem ganzen Volke Israel kund: Im Namen Jesu Christi, des Nazareners, den ihr gekreuzigt habt, den aber Gott von den Toten erweckt hat, in ihm steht dieser hier gesund vor euren Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Er ist der Stein, der von euch, den Bauleuten, verworfen ward, jedoch zum Schlußstein geworden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'In keinem anderen gibt es Rettung; denn es gibt keinen anderen Namen unter dem Himmel, der uns Menschen gegeben wäre, in dem wir selig werden müssen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Als sie den Freimut des Petrus und Johannes gewahrten und merkten, daß es ungelehrte und ungebildete Leute waren, verwundenen sie sich. Auch stellten sie fest, daß sie ehemalige Jünger Jesu seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Da sie zugleich den Mann, der geheilt war, bei ihnen stehen sahen, wußten sie nichts zu entgegnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Man ließ sie aus dem Sitzungssaal abführen, und sie beratschlagten miteinander');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'und sagten: \"Was sollen wir mit diesen Menschen machen? Denn daß ein offenkundiges Wunder durch sie geschehen ist, ist allen in Jerusalem bekannt; wir können es nicht leugnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Doch damit die Sache sich nicht weiter mehr im Volke verbreite, wollen wir ihnen unter Drohungen einschärfen, zu keinem Menschen mehr in diesem Namen zu reden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Man rief sie wieder herein und verbot ihnen, je wieder im Namen Jesu zu reden oder zu predigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Petrus und Johannes aber erwiderten ihnen: \"Ob es vor Gott berechtigt ist, mehr auf euch als auf Gott zu hören, darüber urteilt selber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Unmöglich ist es uns, von dem nicht zu reden, was wir gesehen und gehört haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Jene aber drohten ihnen noch einmal und entließen sie. Denn sie fanden keinen Grund, sie zu bestrafen, schon des Volkes wegen nicht; denn alle priesen Gott ob des Geschehenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'War doch der Mann, an dem dieses Wunder geschehen war, schon über vierzig Jahre alt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Nach ihrer Freilassung kamen sie zu den Ihrigen und berichteten alles, was die Hohenpriester und die Ältesten zu ihnen gesagt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Sie vernahmen es und erhoben alle zumal ihre Stimme zu Gott und beteten. \"Herr! Du hast den Himmel und die Erde, das Meer und alles, was darinnen ist, gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Du hast durch den Heiligen Geist aus dem Munde unseres Vaters David, Deines Knechtes, gesprochen: \'Warum toben die Heiden und planen die Völker Nichtiges?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Die Könige der Erde stehen auf, und Herrscher scharen sich zusammen, dem Herrn und seinem Gesalbten zum Trotz.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Wahrhaftig, es haben sich in dieser Stadt vereinigt Herodes und Pontius Pilatus mit den Heiden und den Stämmen Israels gegen Jesus, Deinen heiligen Knecht, den Du gesalbt hast,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'um auszuführen, was Deine Hand und was Dein Ratschluß festgesetzt hat, daß es geschehen solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Und jetzt o Herr, sieh hin auf ihre Drohungen. Verleihe Deinen Knechten, Dein Wort mit allem Freimut zu verkünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'wenn Du Deine Hand ausstreckst, um zu heilen und Zeichen und Wunder zu vollbringen im Namen Deines heiligen Knechtes Jesus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Während sie so beteten, erbebte der Ort, an dem sie versammelt waren, und alle wurden mit dem Heiligen Geist erfüllt und verkündeten freimütig das Wort Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Die Menge der Gläubigen war ein Herz und eine Seele. Niemand betrachtete etwas von seiner Habe als sein Eigentum; sie hatten alles miteinander gemeinsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Mit großer Kraft gaben die Apostel Zeugnis von der Auferstehung des Herrn Jesus Christus. Große Liebe herrschte unter ihnen allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'So gab es keinen Darbenden unter ihnen; denn wer immer Grundstücke oder Häuser besaß, verkaufte sie und brachte den Erlös des Verkauften');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'und stellte ihn den Aposteln zur freien Verfügung. Einem jeden wurde davon nach Bedarf zugeteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'So besaß Joseph, der von den Aposteln den Beinamen Barnabas, das heißt \"Tröster\", erhalten hatte, ein Levit, aus Cypern stammend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'einen Acker; er verkaufte ihn, brachte das Geld und stellte es den Aposteln zur Verfügung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Auch ein Mann namens Ananias verkaufte mit seinem Weibe Saphira ein Grundstück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Mit Wissen seines Weibes behielt er von dem Verkaufspreis einen Teil zurück und brachte nur den anderen und stellte ihn den Aposteln zur Verfügung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Da sprach Petrus: \"Ananias, warum hat der Satan dir das Herz erfüllt, daß du den Heiligen Geist belogest und einen Teil des Erlöses aus deinem Acker für dich zurückbehieltest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Blieb er denn nicht dein eigen, wenn du ihn nicht verkaufen wolltest, und auch, nachdem du ihn verkauft hast, hast du nicht frei verfügen können? Wie konntest du nur solcherlei Gedanken in deinem Herzen fassen? Nicht Menschen hast du angelogen, sondern Gott.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Als Ananias diese Worte hörte, fiel er zu Boden und war tot. Große Furcht ergriff alle, die es hörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Junge Männer standen auf, deckten ihn zu, trugen ihn hinaus und begruben ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Es vergingen ungefähr drei Stunden, da kam auch sein Weib herein, ohne von dem Vorgefallenen etwas zu wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Petrus sprach zu ihr: \"Sage mir: Habt ihr den Acker nur um soviel verkauft?\" \"Ja\", sagte sie, \"nur um soviel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Da sprach Petrus zu ihr: \"Was seid ihr übereingekommen, den Geist des Herrn zu versuchen? Siehe, die Füße derer, die deinen Mann begraben haben, stehen vor der Tür, um auch dich hinauszutragen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Im selben Augenblick fiel sie vor seinen Füßen nieder und war tot. Die Jünglinge kamen herein, fanden sie tot, trugen sie hinaus und begruben sie an der Seite ihres Mannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Gewaltige Furcht kam über alle, die davon hörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Durch die Hände der Apostel geschahen viele Zeichen und Wunder unter dem Volke. Einmütig versammelten sie sich alle in der Halle Salomos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Von den anderen aber wagte niemand, sich zu ihnen zu gesellen; das Volk jedoch schätzte sie hoch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Immer mehr wuchs die Zahl der Männer und Frauen, die den Glauben an den Herrn annahmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Man trug die Kranken sogar auf die Straße und legte sie auf Betten und Bahren, damit, wenn Petrus vorübergehe, wenigstens sein Schatten auf den einen oder anderen aus ihnen falle und sie von ihren Krankheiten befreit wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Auch aus den umliegenden Städten strömte das Volk nach Jerusalem zusammen und brachte Kranke und von unreinen Geistern geplagte mit, und alle wurden geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Da erhoben sich der Hohepriester und alle seine Anhänger, nämlich die Sekte der Sadduzäer, voll Eifersucht;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'sie ließen die Apostel festnehmen und ins Stadtgefängnis werfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Ein Engel des Herrn aber öffnete in der Nacht die Tore des Gefängnisses, führte sie heraus und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '\"Gehet hin und tretet im Tempel auf und redet zu dem Volk alle Worte dieses Lebens.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Daraufhin gingen sie mit Tagesanbruch in den Tempel und lehrten. Nun erschienen der Hohepriester und seine Anhänger; sie beriefen den Hohen Rat, das heißt alle Ältesten der Söhne Israels. Sie schickten zum Gefängnis, um die Apostel vorführen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Die Diener gingen hin öffneten das Gefängnis, fanden sie aber nicht im Gefängnis. Sie kehrten zurück mit der Meldung:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '\"Wir fanden das Gefängnis in aller Ordnung fest verschlossen, die Wachen standen an den Toren, doch als wir öffneten, fanden wir niemand mehr darin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Als der Tempelhauptmann und die Oberpriester diese Kunde vernahmen, fragten sie sich ratlos, was denn daraus noch werden solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Da kam jemand mit der Meldung: \"Die Männer, die ihr gefangengenommen habt, sind im Tempel und lehren dort das Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Da begab sich der Hauptmann mit den Dienern hin und holte sie herbei; doch nicht mit Gewalt; denn sie fürchteten, sie möchten vom Volk gesteinigt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Sie führten sie also herbei und stellten sie vor den Hohen Rat. Der Hohepriester hielt ihnen vor:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '\"Wir haben euch doch streng verboten, in diesem Namen da zu lehren. Und doch habt ihr Jerusalem mit eurer Lehre angefüllt und wollt das Blut dieses Menschen auf uns bringen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Petrus aber und die übrigen Apostel antworteten: \"Man muß Gott mehr gehorchen als den Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Denn der Gott unserer Väter hat Jesus, den ihr ans Holz gehängt und gemordet habt, auferweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Ihn hat nun Gott durch seine Rechte zum Fürsten und zum Heiland erhöht, um Israel Bekehrung und Sündennachlaß zu gewähren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Und wir sind Zeugen dieser Dinge, wie auch der Heilige Geist, den Gott denen verliehen hat, die ihm gehorsam sind.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Bei diesen Worten gerieten sie in Wut und wollten sie töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Da erhob sich im Hohen Rat ein Pharisäer namens Gamaliel, ein beim ganzen Volke angesehener Gesetzeslehrer. Er hieß die Männer auf kurze Zeit hinausführen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'dann sprach er zu ihnen: \"Ihr Männer Israels, seht euch wohl vor, wie ihr mit diesen Leuten verfahren wollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Vor einiger Zeit trat Theudas auf und gab vor, etwas Besonderes zu sein. Es schlossen sich ihm gegen vierhundert Leute an. Doch er wurde getötet, und alle, die sich ihm angeschlossen hatten, zersprengt und schließlich ganz vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Nach ihm erhob sich in den Tagen der Schätzung der Galiläer Judas und verführte viel Volk zum Abfall. Auch dieser ging zugrunde, und alle, die ihm angehangen hatten, wurden weit zersprengt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Was aber diesen Fall betrifft, so sage ich euch: Laßt ab von diesen Leuten, gebt sie frei! Denn geht dieses Vorhaben oder dieses Werk von Menschen aus, dann wird es ein Ende nehmen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'doch kommt es von Gott, so werdet ihr ihnen kein Ende bereiten können; ja, ihr könntet gar als Widersacher gegen Gott erfunden werden.\" Sie stimmten ihm bei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Dann ließen sie die Apostel rufen, ließen sie geißeln und verboten ihnen, im Namen Jesu zu reden. Darauf entließen sie dieselben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Sie aber gingen voll Freude vom Hohen Rat hinweg, weil sie gewürdigt worden waren, um des Namens Jesu willen Schmach zu leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Und sie hörten nicht auf, Tag für Tag im Tempel und in den Häusern zu lehren und die frohe Botschaft von Christus Jesus zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'In jenen Tagen, da die Jünger sich mehrten, entstand ein Murren der Hellenisten gegen die Hebräer, daß ihre Witwen bei der täglichen Almosenverteilung zurückgesetzt würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Da beriefen die Zwölf eine Versammlung der Jünger und erklärten: \"Es geht nicht an, daß wir das Wort Gottes hintansetzen, um die Tische zu besorgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'So sucht euch denn, ihr lieben Brüder, bei euch sieben Männer aus, die ein gutes Zeugnis haben und voll des Heiligen Geistes und voll Weisheit sind; die wollen wir für diese Sache bestellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Wir aber werden weiter dem Gebete sowie dem Dienste des Wortes uns widmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Der Vorschlag fand den Beifall der ganzen Versammlung. Sie wählten Stephanus, einen Mann voll Glauben und Heiligen Geistes, den Philippus, Prochorus, Nikanor, Timon, Parmenas und Nikolaus, einen Proselyten aus Antiochien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Diese stellte man den Aposteln vor. Sie legten ihnen unter Gebet die Hände auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Und das Wort Gottes verbreitete sich, und die Zahl der Jünger ward in Jerusalem groß, sogar eine große Anzahl von Priestern unterwarf sich dem Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stephanus, voll Liebe und Kraft, tat große Zeichen und Wunder unter dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Da erhoben sich einige aus der sogenannten Synagoge der Libertiner, Cyrenäer und Alexandriner und derer aus Cilizien und Asien und stritten mit Stephanus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Sie vermochten aber der Weisheit und dem Geiste, mit dem er sprach, nicht zu widerstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Sie stifteten Männer an, die aussagen mußten: \"Wir haben gehört, wie er Lästerworte gegen Moses und Gott ausstieß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Sie hetzten das Volk, die Ältesten und die Schriftgelehrten auf, überfielen ihn, schleppten ihn fort und führten ihn vor den Hohen Rat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Auch stellten sie falsche Zeugen auf, die aussagen mußten: \"Dieser Mensch hört nicht auf, gegen die heilige Stätte und gegen das Gesetz Reden auszustoßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Haben wir ihn doch sagen hören: \'Der bekannte Jesus von Nazareth wird diesen Ort zerstören und die Bräuche ändern, die Moses uns überliefert hat.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Alle, die im Hohen Rat saßen, richteten ihre Blicke auf ihn, und sein Antlitz erschien ihnen wie das Antlitz eines Engels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Der Hohepriester aber fragte: \"Verhält sich das so?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Stephanus antwortete: \"Meine Brüder! Väter! Höret! Der hocherhabene Gott erschien einst unserem Vater Abraham, als er noch in Mesopotamien lebte, bevor er sich in Charran niederließ,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'und sprach zu ihm: \'Zieh weg aus deinem Land und aus deiner Verwandtschaft und zieh in das Land, das ich dir zeigen werde.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Da machte er sich aus dem Lande der Chaldäer auf und zog nach Charran. Nach dem Tode seines Vaters versetzte ihn Gott von dort in dieses Land, wo ihr jetzt wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Doch gab er ihm darin kein Erbe, nicht eines Fußes Breite, sondern er versprach ihm nur, er werde später ihm und seinem Stamm es als Besitztum geben, obwohl er damals noch kein Kind besaß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Also sprach nämlich Gott: \'Seine Nachkommen werden als Fremdlinge in fremdem Lande wohnen; man wird sie knechten und sie vierhundert Jahre lang hart bedrücken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Das Volk jedoch, dem sie als Knechte dienen, werde ich richten\', so sprach Gott. \'Doch später werden sie von dannen ziehen und mir an diesem Orte dienen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Dann gab er ihnen das Bundeszeichen der Beschneidung. Kraft desselben zeugte er den Isaak und beschnitt ihn am achten Tage. Isaak zeugte weiterhin den Jakob, und dieser die zwölf Patriarchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Die Patriarchen waren eifersüchtig gegen Joseph und verkauften ihn nach Ägypten. Indes war Gott mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Er rettete ihn aus allen seinen Drangsalen, und er verlieh ihm Gunst und Weisheit vor Pharao, dem König von Ägypten. Dieser machte ihn zum Herrn Ägyptens und seines ganzen Hauses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Doch eine Hungersnot kam über ganz Ägypten und Kanaan; groß war das Elend, und unsere Väter konnten keine Lebensmittel finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Da hörte Jakob, daß es in Ägypten noch Getreide gebe; er sandte unsere Väter ein erstesmal dorthin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Beim zweitenmal gab sich dann Joseph seinen Brüdern zu erkennen, und so ward dem Pharao die Abstammung des Joseph bekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Hierauf ließ Joseph seinen Vater Jakob und alle Verwandten kommen; es waren fünfundsiebzig Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'So zog Jakob nach Ägypten, wo er starb, er und unsere Väter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Man brachte sie nach Sichem; sie wurden in dem Grabe beigesetzt, das Abraham einst um eine Summe Geldes von den Söhnen Hemors in Sichem gekauft hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Wie nun die Zeit für die Verheißung nahte, die Gott dem Abraham zugesagt hatte, da mehrte sich das Volk in Ägypten und wurde zahlreich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'bis in Ägypten ein anderer König zur Herrschaft kam, der nichts von Joseph wußte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Und er verfuhr mit unserem Geschlechte hinterlistig: er bedrückte unsere Väter, die ihre Kinder aussetzen mußten, damit sie nicht am Leben blieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'In dieser Zeit kam Moses auf die Weit: er war Gott wohlgefällig. Drei Monate hindurch ward er im Vaterhause auferzogen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'dann setzte man ihn aus. Die Tochter Pharaos nahm ihn indessen an sich und zog ihn für sich auf als den eigenen Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Und Moses ward in aller Weisheit der Ägypter unterrichtet; mächtig in Wort und Tat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Als er vierzig Jahre alt war, kam ihm das Verlangen, sich nach den Israeliten, seinen Brüdern, umzusehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Da sah er, wie irgendeinem Unrecht getan ward. Er setzte sich zur Wehr und schaffte dem Mißhandelten sein Recht und schlug den Ägypter tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Er meinte, seine Brüder würden wohl verstehen, daß Gott ihnen Rettung durch seine Hand verschaffen wolle; doch sie verstanden es nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Des anderen Tags kam er zu ihnen, als sie gerade miteinander stritten. Er wollte zwischen ihnen Frieden stiften mit den Worten: \'Ihr seid doch Brüder, Männer! Warum tut ihr einander Unrecht an?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Doch der, der seinem Nächsten unrecht tat, stieß ihn zurück und sagte: \'Wer hat denn dich zum Herrn und Richter über uns gemacht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Willst du etwa mich töten, so wie du gestern den Ägypter totgeschlagen hast?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Auf diese Worte hin brachte Moses sich in Sicherheit und lebte im Lande Madian als Fremdling, wo er Vater von zwei Söhnen wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Vierzig Jahre waren schon vorüber, da erschien ihm in der Wüste bei dem Berge Sinai ein Engel in der Flamme eines brennenden Dornbusches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Voll Verwunderung sah Moses die Erscheinung. Als er hinzutrat, um sie zu betrachten, erging die Stimme des Herrn:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '\'Ich bin der Gott deiner Väter, der Gott Abrahams, Isaaks und Jakobs.\' Moses zitterte und wagte nicht, dorthin zu schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Und also sprach der Herr zu ihm: \'Ziehe deine Schuhe aus! Der Ort, auf dem du stehst, ist heiliges Land.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Ich habe die Bedrückung meines Volkes in Ägypten gesehen und ihr Seufzen gehört; ich bin herabgekommen, damit ich es befreie. So komm denn, ich will dich nach Ägypten senden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Denselben Moses, den sie verworfen hatten, indem sie sprachen: \'Wer hat denn dich zum Herrn und Richter eingesetzt?\', den hat Gott als Herrn und Befreier gesandt unter dem Schutz eines Engels, der ihm im Dornbusch erschienen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Und dieser führte sie heraus, vollbrachte Wunder und Zeichen im Lande Ägypten, im Roten Meer und in der Wüste, vierzig Jahre lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Es ist derselbe Moses, der den Söhnen Israels gesagt hatte: \'Einen Propheten wie mich wird Gott euch erwecken aus der Mitte eurer Brüder.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Er ist es auch, der bei der Gemeinde in der Wüste mit dem Engel verkehrte, der auf dem Berge Sinai mit ihm und mit unseren Vätern redete, und er empfing die Worte des Lebens, um sie euch mitzuteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Doch unsere Väter wollten ihm nicht gehorsam sein; sie lehnten ihn vielmehr ab und wandten sich in ihren Herzen wieder Ägypten zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'So sprachen sie zu Aaron: \'Verschaffe uns Götter, die vor uns herziehen; wir wissen nicht, was aus dem Moses da geworden ist, der uns aus Ägypten herausgeführt hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Sie machten sich in jenen Tagen ein Kalb, brachten diesem Götzenbild Opfer dar und ergötzten sich an dem Gebilde ihrer Hände.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Da wandte Gott sich von ihnen ab und ließ sie dem Himmelsheer dienen, wie es geschrieben steht im Buche der Propheten. \'Habt ihr mir etwa Schlachttiere und Opfer dargebracht die vierzig Jahre in der Wüste, Haus Israel?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'O nein, das Zelt des Moloch und das Sternbild eures Gottes Rempham habt ihr herumgeführt, die Bilder, die ihr selbst verfertigt habt, um sie anzubeten. Ich werde euch noch über Babylon hinaus verbannen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Unsere Väter hatten in der Wüste das Bundeszelt, wie der es angeordnet hatte, der zu Moses sprach: \'Er soll es machen nach dem Vorbilde, das er gesehen hat.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Und dieses übernahmen unsere Väter und brachten es mit sich, als sie dann unter Josue das Land der Heiden zum Besitz erhielten, die Gott vor unseren Vätern hernach vertrieb. So blieb es bis auf Davids Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Dieser war Gott wohlgefällig und bat, ob er für den Gott Jakobs nicht eine Wohnung machen dürfe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Jedoch erst Salomo erbaute ihm ein Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Allein der Allerhöchste wohnt nicht in Stätten, die von Menschenhand gemacht sind. Sagt doch schon der Prophet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '\'Der Himmel ist mein Thron, die Erde der Schemel meiner Füße. Was für ein Haus wollt ihr mir bauen\', spricht der Herr, \'oder wo ist der Ort, an dem ich ständig wohnen kann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hat denn nicht meine Hand all dies geschaffen?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'O ihr Halsstarrigen und Unbeschnittenen an Herz und Ohren! Ihr widerstrebt allzeit dem Heiligen Geiste, wie eure Väter, so auch ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Gibt es einen Propheten, den eure Väter nicht verfolgt haben? Sie haben die ermordet, die das Kommen des Gerechten vorherverkündigt haben; ihr selbst seid nun seine Verräter und Mörder geworden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'ihr, die ihr das Gesetz auf Anordnung von Engeln zwar erhalten, aber nicht gehalten habt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Bei diesen Worten ergrimmten sie in ihrem Innersten und knirschten mit den Zähnen gegen ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Stephanus aber, voll des Heiligen Geistes, blickte zum Himmel empor und sah die Herrlichkeit Gottes und Jesus stehend zur Rechten Gottes');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'und rief aus: \"O schaut! Ich sehe die Himmel offen und den Menschensohn zur Rechten Gottes stehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Da erhoben sie ein wüstes Geschrei und hielten sich die Ohren zu. Alle miteinander stürzten sie auf ihn los,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'stießen ihn zur Stadt hinaus und steinigten ihn. Die Zeugen gaben ihre Kleider einem jungen Manne namens Saul in Verwahrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'So steinigten sie den Stephanus. Er betete: \"Herr Jesus, nimm meinen Geist auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Dann sank er in die Knie und rief mit lauter Stimme: \"Herr, rechne ihnen diese Sünde nicht an!\" Damit entschlief er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul aber war mit seiner Ermordung einverstanden. Noch am selben Tage brach über die Kirche in Jerusalem eine erbitterte Verfolgung herein. Alle, mit Ausnahme der Apostel, zerstreuten sich in die Gegenden von Judäa und Samaria.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Den Stephanus aber bestatteten gottesfürchtige Männer und hielten eine große Totenklage um ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saul hingegen wütete furchtbar gegen die Kirche; er drang in die Häuser ein, schleppte Männer und Frauen fort und warf sie ins Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Die Versprengten zogen umher und verkündeten das Wort Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Philippus kam in die Stadt Samaria und verkündete dort Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Einmütig horchte die Volksmenge aufmerksam auf das, was Philippus predigte, und sah die Zeichen, die er wirkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Denn von vielen, die unreine Geister hatten, fuhren diese mit lautem Geschrei aus;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'auch viele Lahme und Krüppel wurden geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Es herrschte deshalb eine große Freude in jener Stadt. Ein Mann namens Simon lebte schon seit geraumer Zeit in jener Stadt. Er trieb Zauberei und betörte die Bewohner von Samaria, indem er sich für etwas Höheres ausgab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Alle, klein und groß, hielten zu ihm; sie sagten: \"Er ist die Kraft Gottes, die \'die Große\' heißt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Sie hielten aber nur deswegen zu ihm, weil er sie längere Zeit mit seiner Zauberei betört hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Als sie aber dem Philippus, der ihnen die frohe Botschaft vom Reiche Gottes und vom Namen Jesu Christi verkündet hatte, glaubten, ließen sich Männer und Frauen taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Simon selber glaubte ebenfalls, ließ sich taufen und schloß sich dem Philippus an. Als er sah, welch große Zeichen und Wunder geschahen, kam er ganz außer sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Als aber die Apostel in Jerusalem hörten, daß Samaria das Wort Gottes angenommen habe, sandten sie den Petrus und Johannes dorthin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Diese zogen hinab, beteten für sie, daß sie den Heiligen Geist empfangen möchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Denn er war noch auf keinen aus ihnen herabgekommen, sondern sie waren nur auf den Namen des Herrn Jesus getauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Nun legten sie ihnen die Hände auf, und sie empfingen den Heiligen Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Als Simon sah, daß durch die Handauflegung der Apostel der Heilige Geist verliehen wurde, brachte er ihnen Geld');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'und sagte: \"Gebt auch mir so große Macht, daß jeder, dem ich die Hand auflege, den Heiligen Geist empfange.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Petrus aber sprach zu ihm: \"Dein Geld fahre samt dir ins Verderben, weil du geglaubt hast, du könntest dir die Gabe Gottes um Geld kaufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du hast nicht teil noch Recht daran; dein Herz ist ja vor Gott nicht ehrlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Bekehre dich von dieser deiner Bosheit und bitte den Herrn, ob dir vielleicht das Sinnen deines Herzens vergeben werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Denn wie ich sehe, bist du voll bitterer Galle und liegst in den Fesseln der Bosheit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Simon aber erwiderte: \"Betet ihr für mich zum Herrn, damit nichts von dem, was ihr gesagt habt, mich treffe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Als sie nun Zeugnis gegeben und das Wort des Herrn verkündet hatten, kehrten sie nach Jerusalem zurück und verkündeten dabei noch in vielen Ortschaften der Samariter die frohe Botschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Ein Engel des Herrn aber gab Philippus den Auftrag: \"Mache dich auf und geh um die Mittagszeit auf die Straße, die von Jerusalem nach Gaza führt; sie ist ganz unbelebt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Er machte sich auf und ging hin. Ein Äthiopier, ein Eunuch und Würdenträger der Königin Kandake von Äthiopien, ihr oberster Schatzmeister, war nach Jerusalem gekommen, um anzubeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Er befand sich auf der Heimreise und las auf seinem Wagen den Propheten Isaias.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Es sprach aber der Geist zu Philippus: \"Tritt hin und halte dich bei diesem Wagen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Philippus lief hin und hörte ihn den Propheten Isaias lesen. Er sprach zu ihm: \"Verstehst du, was du liesest?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Er erwiderte: \"Wie sollte ich auch, wenn mich niemand anleitet?\" Und er bat den Philippus, einzusteigen und sich neben ihn zu setzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Die Schriftstelle, die er gerade las, war folgende: \"Wie ein Schaf ward er zur Schlachtbank geführt; wie ein Lamm, das vor dem, der es schert, verstummt, so tut auch er den Mund nicht auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Um seiner Demut willen ward das Gericht über ihn aufgehoben. Wer wird sein Geschlecht beschreiben? Denn weggenommen von der Erde wird sein Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Der Eunuch wandte sich an Philippus und fragte: \"Bitte, von wem sagt dies der Prophet? Von sich oder von irgendeinem anderen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Da öffnete Philippus seinen Mund, und, ausgehend von dieser Schriftstelle, verkündigte er ihm die frohe Botschaft von Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Während sie nun des Weges dahinzogen, kamen sie an ein Wasser. Der Eunuch sprach: \"Siehe, hier ist Wasser, was hindert, daß ich getauft werde?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Philippus sprach: \"Wenn du aus ganzem Herzen glaubst, so kann es geschehen.\" Er antwortete und sprach: \"Ich glaube, daß Jesus Christus der Sohn Gottes ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Er ließ den Wagen halten, und beide stiegen zum Wasser hinab, Philippus und der Eunuch. Dort taufte er ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Als sie aus dem Wasser herausgestiegen waren, da entrückte der Geist des Herrn den Philippus, und der Eunuch sah ihn nicht mehr. Voll Freude zog er seines Weges weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippus aber fand sich in Azot wieder. Er zog umher und verkündete in allen Städten bis nach Cäsarea hin die frohe Botschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Noch immer brannte Saul von Wut und Mordgier gegen die Jünger des Herrn. Er ging zum Hohenpriester');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'und erbat sich von ihm Schreiben an die Synagogen in Damaskus. Er wollte etwaige Anhänger dieser Lehre, Männer und Weiber, gefesselt nach Jerusalem bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'So machte er sich auf den Weg und kam in die Nähe von Damaskus. Da umstrahlte ihn plötzlich ein Licht vom Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Er stürzte zu Boden und vernahm eine Stimme, die ihm zurief: \"Saul, Saul, warum verfolgst du mich?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, '\"Wer bist du, Herr?\" so fragte er. \"Ich bin Jesus, den du verfolgst\", sprach er \"es wird dir schwer sein, gegen den Stachel auszuschlagen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Zitternd und bebend fragte er: \"Herr, was willst du, daß ich tun soll?\" \"Steh auf; geh in die Stadt! Dort wird man dir sagen, was du tun sollst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Die Männer, die mit ihm gekommen waren, standen sprachlos da; denn obwohl sie die Stimme hörten, konnten sie doch niemand sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saul erhob sich vom Boden. Als er die Augen aufschlug, konnte er nicht sehen. Da nahmen sie ihn bei der Hand und führten ihn nach Damaskus hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Drei Tage lang war er blind und aß und trank nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'In Damaskus lebte ein Jünger namens Ananias. Zu diesem sprach der Herr in einem Gesichte: \"Ananias!\" Er antwortete: \"Hier bin ich, Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Und der Herr gebot ihm: \"Mache dich auf, geh in die Straße, die die \'Gerade\' heißt, und frage im Hause des Judas nach einem Manne namens Saul aus Tarsus. Siehe, er betet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'In einem Gesichte sah Saul einen Mann namens Ananias eintreten und ihm die Hände auflegen, damit er wieder sehend würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias antwortete: \"O Herr, von diesem Manne habe ich von vielen Seiten schon gehört, wieviel Böses er deinen Heiligen zu Jerusalem angetan hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Und auch hier hat er die Vollmacht von den Oberpriestern, alle zu fesseln, die deinen Namen anrufen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Doch der Herr erwiderte ihm: \"Geh nur hin! Denn dieser ist für mich ein auserwähltes Werkzeug, um meinen Namen vor Heiden, Könige und die Kinder Israels zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Ich will ihm zugleich zeigen, wieviel er um meines Namens willen leiden muß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias machte sich auf und ging in das Haus. Er legte ihm die Hände auf und sprach: \"Bruder Saul, der Herr hat mich gesandt, Jesus, der dir auf dem Wege, den du kamst, erschienen ist, damit du wieder sehend und voll des Heiligen Geistes werdest.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Sofort fiel es ihm wie Schuppen von den Augen, und er konnte wieder sehen. Er stand auf und wurde getauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Dann nahm er Nahrung zu sich und erholte sich wieder. Er blieb noch einige Tage bei den Jüngern in Damaskus');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'und predigte sofort in den Synagogen, daß Jesus der Sohn Gottes ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Alle, die es hörten, wunderten sich und sprachen: \"Ist das nicht derselbe, der in Jerusalem die zugrunde richtete, die diesen Namen anriefen? Kam er nicht eben deshalb auch hierher, um sie gefesselt vor die Oberpriester zu schleppen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saul aber trat immer wirksamer auf und brachte die Juden in Damaskus in Verwirrung durch den Nachweis: \"Er ist der Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Nach einiger Zeit faßten die Juden den Plan, ihn umzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Ihr Anschlag wurde jedoch dem Saul bekannt. Sie bewachten aber Tag und Nacht die Tore, um ihn ermorden zu können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Seine Jünger aber ließen ihn bei Nacht in einem Korb über die Mauer hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Er kam nach Jerusalem. Dort suchte er sich den Jüngern anzuschließen; alle aber hatten Furcht vor ihm und konnten nicht glauben, daß er ein Jünger sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabas aber nahm sich seiner an und führte ihn zu den Aposteln. Er erzählte ihnen, wie er auf dem Wege den Herrn gesehen, wie er mit ihm geredet und wie er in Damaskus freimütig im Namen Jesu gepredigt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'So ging er denn bei ihnen in Jerusalem ein und aus und predigte freimütig im Namen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Er redete und stritt auch mit den Hellenisten. Diese aber trachteten danach, ihn zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Das erfuhren die Brüder, und sie geleiteten ihn hinab nach Cäsarea und entließen ihn nach Tarsus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Die Kirche hatte jetzt Frieden in ganz Judäa, Galiläa und Samaria. Sie baute sich auf und wandelte in der Furcht des Herrn, sie mehrte sich durch den Trost des Heiligen Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Nun geschah es, daß Petrus auf einer Rundreise bei allen auch zu den Heiligen kam, die in Lydda wohnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Dort traf er einen Mann namens Äneas. Schon seit acht Jahren lag er zu Bette; denn er war gelähmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Petrus sprach zu ihm: \"Äneas, Jesus Christus heilt dich! Steh auf und mach dir selbst dein Bett!\" Und sofort stand er auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Alle Bewohner von Lydda und der Saronebene sahen ihn und bekehrten sich zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'In Joppe lebte eine Jüngerin namens Tabitha, das heißt Dorkas. Sie war reich an guten Werken und gab viel Almosen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Eben damals geschah es nun, daß sie krank wurde und starb. Man wusch sie und bahrte sie im Obergemach auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Da Lydda nahe bei Joppe liegt und die Jünger erfahren hatten, daß sich Petrus dort aufhalte, sandten sie zwei Männer zu ihm mit der Bitte: \"Säume nicht und komm zu uns herüber!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Petrus machte sich auf und ging mit ihnen. Als er angekommen war, führte man ihn in das Obergemach. Alle Witwen standen um ihn herum und zeigten ihm unter Tränen die Unter- und Oberkleider, die Dorkas gemacht hatte, da sie noch unter ihnen weilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Petrus aber wies sie alle hinaus, kniete nieder und betete. Dann wandte er sich zu der Leiche und sprach: \"Tabitha, steh auf!\" Sie öffnete ihre Augen, und, als sie den Petrus erblickte, setzte sie sich aufrecht hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Er reichte ihr die Hand und half ihr auf. Dann rief er die Heiligen und die Witwen herein und stellte sie ihnen lebend vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Dies ward in ganz Joppe bekannt, und viele glaubten an den Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Er blieb dann noch geraume Zeit in Joppe bei einem Gerber namens Simon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'In Cäsarea lebte ein Mann namens Kornelius, Hauptmann in der so genannten Italischen Kohorte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Er war samt seinem ganzen Hause fromm und gottesfürchtig, gab dem Volke reichlich Almosen und betete unablässig zu Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Es war um die neunte Tagesstunde, da sah er ganz deutlich in einem Gesichte, wie ein Engel Gottes zu ihm hereinkam und zu ihm sprach: \"Kornelius!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Er aber schaute ihn starr an und fragte voll Furcht: \"Was, o Herr?\" Er antwortete ihm: \"Deine Gebete und deine Almosen sind emporgestiegen zu Gott als Gedächtnisopfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Doch jetzt sende Männer nach Joppe und laß den Simon holen, der auch Petrus heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Er ist zu Gast bei einem Gerber namens Simon, der am Meer ein Haus besitzt\" Der wird dir sagen, was du tun sollst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Der Engel, der mit ihm geredet hatte, verschwand. Er rief zwei seiner Sklaven und einen gottesfürchtigen Soldaten aus seiner ständigen Umgebung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'setzte ihnen alles auseinander und schickte sie nach Joppe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Am anderen Tag, während jene noch unterwegs waren und sich der Stadt näherten, stieg Petrus auf das Dach, um zu beten. Es war um die sechste Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Er war hungrig und wünschte zu essen. Während man zurichtete, kam über ihn eine Verzückung:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Er schaute den Himmel offen und ein Behältnis wie ein großes Linnentuch herabkommen, das an den vier Enden auf die Erde herabgelassen wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'In ihm befanden sich alle vierfüßigen und kriechenden Tiere der Erde und Vögel des Himmels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Eine Stimme rief ihm zu: \"Steh auf, Petrus, schlachte und iß!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Petrus erwiderte: \"Nein, Herr! Noch nie habe ich etwas Gemeines und Unreines gegessen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Zum zweitenmal rief es ihm zu: \"Was Gott gereinigt hat, sollst du nicht gemein heißen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Das geschah dreimal. Gleich darauf wurde das Behältnis wieder in den Himmel emporgehoben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Während Petrus noch überlegte, was das Gesicht, das er gesehen hatte, zu bedeuten habe, standen die Leute, die Kornelius abgesandt und die sich zum Hause des Simon bereits durchgefragt hatten, am Tore.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Sie riefen und fragten, ob hier ein Simon mit dem Beinamen Petrus wohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Petrus dachte immer noch über das Gesicht nach. Da sprach der Geist zu ihm: \"Drei Männer suchen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Steh auf und geh hinab und zieh mit ihnen ohne irgendein Bedenken; denn ich habe sie gesandt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Da ging Petrus zu den Leuten hinunter und sprach zu ihnen: \"Ich bin es, den ihr suchet. Was führt euch hierher?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Sie antworteten ihm: \"Kornelius, der Hauptmann, ein rechtlicher und gottesfürchtiger Mann, der bei der ganzen jüdischen Bevölkerung in gutem Rufe steht, ward von einem heiligen Engel angewiesen, dich in sein Haus zu holen und von dir Belehrung zu empfangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Da lud er sie ein und beherbergte sie. Am folgenden Tage machte er sich auf und zog mit ihnen fort; einige der Brüder aus Joppe begleiteten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Am anderen Tag langte er in Cäsarea an. Kornelius erwartete sie und hatte seine Verwandten und vertrauten Freunde eingeladen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Als Petrus eintrat, ging ihm Kornelius entgegen, fiel ihm zu Füßen und begrüßte ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Petrus aber hob ihn auf und sprach: \"Steh auf! Auch ich bin nur ein Mensch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Im Gespräch mit ihm trat er ein und fand viele Leute versammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Da sprach er zu ihnen: \"Ihr wisset wohl, daß es einem Juden nicht erlaubt ist, mit einem Nichtjuden näher zu verkehren oder zu ihm zu gehen. Doch mir hat Gott gezeigt, daß man keinen Menschen gemein und unrein nennen darf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Ich bin deshalb ohne irgendein Bedenken mitgegangen, als ihr mich rufen ließet. Ich möchte aber doch nun wissen, warum ihr mich habt rufen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Kornelius erwiderte: \"Gerade vor vier Tagen, auf die Stunde hin, da betete ich in meinem Hause um die neunte Stunde. Und siehe, da stand ein Mann vor mir in glänzend weißem Kleide');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'und sprach: \'Kornelius! Dein Gebet ist erhört und deiner Almosen ward vor Gott gedacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Schick hin nach Joppe und laß Simon rufen, der auch Petrus heißt; er weilt als Gast im Hause des Gerbers Simon dicht am Meer.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Und sogleich sandte ich zu dir, und du hast recht getan, daß du gekommen bist. Jetzt sind wir alle hier vor Gott versammelt, um zu hören, was dir vom Herrn aufgetragen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Da tat Petrus seinen Mund auf und sprach: \"Nunmehr begreife ich in Wahrheit, daß Gott nicht auf die Person sieht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'daß ihm vielmehr in jedem Volke der angenehm ist, der ihn fürchtet und Gerechtigkeit übt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Das Wort hat er den Kindern Israels gesandt, indem er Frieden verkündigte durch Jesus Christus; dieser ist der Herr aller.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Ihr kennt die Begebenheiten, die sich im ganzen Judenland zugetragen haben: In Galiläa fing er an nach der Taufe, die Johannes verkündete;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'ich meine Jesus von Nazareth, den Gott mit dem Heiligen Geist und mit Wunderkraft gesalbt hat, der dann umhergezogen ist, Wohltaten spendete und alle vom Teufel Besessenen geheilt hat; Gott war ja mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Wir sind von all dem Zeugen, was er im Judenland und in Jerusalem gewirkt hat. Man hat ihn zwar getötet, indem man ihn ans Holz gehängt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Gott aber hat ihn am dritten Tag auferweckt und sichtbar werden lassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'zwar nicht dem ganzen Volke, doch den von Gott vorbestimmten Zeugen, uns, die wir nach seiner Auferstehung von den Toten mit ihm zusammen gesessen und getrunken haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Er hat uns aufgetragen, dem Volke zu verkünden und zu bezeugen, daß er der von Gott bestellte Richter über Lebendige und Tote ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Von ihm bezeugen alle Propheten, daß jeder, der an ihn glaubt, durch seinen Namen Nachlaß der Sünden empfangen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Während Petrus noch so redete, kam der Heilige Geist auf alle herab, die die Predigt hörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Die Gläubigen aus der Beschneidung, die mit Petrus gekommen waren, wunderten sich, daß auch über die Heiden die Gabe des Heiligen Geistes ausgegossen wurde;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'denn sie hörten, wie sie in Sprachen redeten und Gott lobpriesen. Da sprach Petrus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '\"Kann man das Wasser der Taufe denen versagen, die gleich uns den Heiligen Geist empfangen haben?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'So ließ er sie denn im Namen Jesu Christi taufen. Hierauf baten sie ihn, noch einige Tage dazubleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Die Apostel und die Brüder in Judäa erfuhren, daß auch die Heiden das Wort Gottes angenommen hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Als nun Petrus nach Jerusalem hinaufkam, stritten die aus dem Judentum mit ihm');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'und sagten: \"Du bist bei Unbeschnittenen eingekehrt und hast mit ihnen Mahl gehalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Petrus aber hob an und setzte ihnen den ganzen Hergang der Reihe nach auseinander. Er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '\"Ich war in der Stadt Joppe und wollte eben mein Gebet verrichten. Da hatte ich in der Verzückung ein Gesicht: Ein Behältnis wie ein großes Linnentuch kam herab und hing an den vier Enden aus dem Himmel her und kam gerade auf mich zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'ich sah genau hin und sah die vierfüßigen Tiere der Erde und die wilden Tiere und die Kriechtiere und auch die Vögel des Himmels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Auch hörte ich eine Stimme, die mir zurief: \'Petrus, steh auf, schlachte und iß!\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Doch ich erwiderte: \'Nein, Herr! Noch nie kam etwas Gemeines oder Unreines in meinen Mund.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Jedoch zum zweitenmal sprach die Stimme vom Himmel her: \'Was Gott gereinigt hat, darfst du nicht gemein nennen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Und das geschah ein drittes Mal. Dann wurde alles wieder in den Himmel hinaufgezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Im selben Augenblick standen drei Männer vor dem Hause, in dem wir uns befanden; sie waren zu mir aus Cäsarea hergesandt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Der Geist hieß mich mit ihnen gehen ohne irgendein Bedenken. Und mit mir reisten die sechs Brüder da; so kamen wir in das Haus des Mannes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Und er erzählte uns, wie er in seinem Hause den Engel habe stehen sehen, der zu ihm sprach: \'Sende hin nach Joppe und laß den Simon holen, der auch Petrus heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Und er wird Worte zu dir sprechen, kraft deren du samt deinem ganzen Hause gerettet werden wirst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Kaum hatte ich zu reden angefangen, da kam der Heilige Geist auf sie herab, wie damals auf uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Und da gedachte ich des Herrenwortes, das er einstens sprach: \'Johannes hat nur mit Wasser getauft; ihr aber werdet mit dem Heiligen Geiste getauft werden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Wenn Gott nun ihnen die gleiche Gnade gab wie uns, die wir schon an den Herrn Jesus Christus glaubten, woher hätte ich mir die Macht nehmen sollen, Gott zu hindern?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Als sie dies gehört hatten, gaben sie sich zufrieden; sie lobten Gott und sprachen: \"Also hat Gott auch den Heiden die Sinnesänderung verliehen, die zum Leben führt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Durch die Verfolgung, die des Stephanus\' wegen ausgebrochen war, wurden viele versprengt und kamen bis nach Phönizien, Cypern und Antiochien. Sie verkündigten aber niemand das Wort als allein den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Jedoch einige aus ihnen, Männer aus Cypern und der Cyrenaika, verkündeten, als sie in Antiochien angekommen waren, auch den Heiden die frohe Botschaft vom Herrn Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Die Hand des Herrn war mit ihnen, und eine beträchtliche Anzahl wurde gläubig und bekehrte sich zum Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Die Kunde davon kam zu den Ohren der Gemeinde in Jerusalem. Man entsandte den Barnabas nach Antiochien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Als er ankam und die Gnade Gottes sah, freute er sich; er ermahnte alle, so wie sie es sich in ihrem Herzen vorgenommen hätten, beim Herrn zu bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'War er doch ein trefflicher Mann, voll Heiligen Geistes und Glaubens. Es wurde auch eine große Anzahl für den Herrn hinzugewonnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Er reiste dann nach Tarsus, um den Saulus aufzusuchen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'er traf ihn und nahm ihn nach Antiochien mit. Dort wirkten sie noch ein ganzes Jahr in der Gemeinde zusammen und unterrichteten eine ansehnliche Menge. In Antiochien nannte man die Jünger zum erstenmal \"Christen\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'In dieser Zeit kamen von Jerusalem her Propheten nach Antiochien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Einer aus ihnen, namens Agabus, stand auf und kündigte durch den Geist an, daß eine große Hungersnot über den ganzen Erdkreis kommen werde. Sie trat dann unter Claudius wirklich ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Die Jünger aber faßten den Beschluß, daß ein jeder von ihnen je nach Vermögen den Brüdern in Judäa eine Unterstützung zukommen lassen solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Dieses taten sie auch und sandten das Geld an die Presbyter durch Barnabas und Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Um dieselbe Zeit legte der König Herodes Hand an einige Angehörige der Gemeinde, um sie zu mißhandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Er ließ Jakobus, den Bruder des Johannes, mit dem Schwerte hinrichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Da er sah, daß dies den Juden gefiel, ließ er auch den Petrus ergreifen. Es war in den Tagen der Ungesäuerten Brote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Er ließ ihn also festnehmen und ins Gefängnis werfen und durch eine vierfache Wache von je vier Soldaten bewachen. Nach Ostern wollte er ihn dann dem Volke vorführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Petrus wurde im Gefängnis bewacht, von der Gemeinde aber wurde ohne Unterlaß für ihn zu Gott gebetet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'In der Nacht, bevor Herodes ihn vorführen lassen wollte, schlief Petrus mit zwei Ketten gefesselt zwischen zwei Soldaten. Wachtposten vor der Türe bewachten das Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Siehe, da erschien ein Engel des Herrn, Licht erstrahlte in dem Gelaß; er stieß den Petrus in die Seite, weckte ihn und sprach: \"Schnell, auf!\" Da fielen ihm die Ketten von den Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Der Engel gebot ihm weiter: \"Gürte dich und ziehe deine Schuhe an!\" Er tat es. Weiter sprach er: \"Wirf deinen Mantel um und folge mir!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Er ging hinaus und folgte ihm, wußte aber nicht, daß es Wirklichkeit war, was durch den Engel geschah; er meinte vielmehr, ein Gesicht zu schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Sie schritten an der ersten und zweiten Wache rasch vorüber und kamen an das eiserne Tor, das in die Stadt hineinführt; dieses tat sich ihnen von selbst auf. Sie traten ein und gingen in eine gewisse Straße, und plötzlich schied der Engel von ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Da kam Petrus, zu sich und sprach: \"Jetzt weiß ich in Wahrheit, der Herr hat seinen Engel gesandt und mich aus der Hand des Herodes gerissen, und aus dem, was das Judenvolk erwartete.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Und als er sich das klargemacht hatte, ging er zum Hause der Maria, der Mutter des Johannes mit dem Beinamen Markus. Hier waren viele versammelt und beteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Er klopfte an die Tür des Hoftors. Eine Magd mit Namen Rhode kam herbei, um zu horchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Als sie die Stimme des Petrus erkannte, öffnete sie vor lauter Freude das Tor nicht, sondern lief hinein und meldete, Petrus Stehe vor dem Tore.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Die aber sagten zu ihr: \"Du bist von Sinnen.\" Doch sie bestand fest darauf, daß es so sei. Da meinten sie: \"Es ist sein Engel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Petrus aber fuhr fort zu klopfen; man öffnete, sah ihn und staunte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Er aber winkte ihnen mit der Hand, daß sie schweigen möchten, und erzählte ihnen dann, wie ihn der Herr aus dem Gefängnis herausgeführt habe. Er sagte noch: \"Meldet dies dem Jakobus und den anderen Brüdern!\" Dann ging er weg und begab sich an einen anderen Ort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Als es Tag geworden war, entstand unter den Soldaten eine nicht geringe Aufregung, was aus Petrus geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herodes, der ihn holen lassen wollte, aber nicht vorfand, verhörte die Wächter und ließ sie dann zur Hinrichtung abführen. Hierauf begab er sich von Judäa nach Cäsarea hinab und hielt sich dort auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Gegen die Bewohner von Tyrus und von Sidon war er sehr erzürnt. Diese erschienen nun einmütig vor ihm, und nachdem sie den königlichen Kammerherrn Blastus für sich gewonnen hatten, baten sie um Frieden; denn ihr Land bezog von dem des Königs die Lebensmittel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'An dem bestimmten Tage setzte sich Herodes in königlichem Gewand auf seinen Thron und hielt eine Ansprache an sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Das Volk brach in den Ruf aus: \"Eines Gottes, nicht eines Menschen Stimme.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Auf der Stelle schlug ihn ein Engel des Herrn dafür, daß er nicht Gott die Ehre gegeben hatte. Und von Würmern zerfressen starb er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Das Wort des Herrn aber breitete sich immer weiter aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas und Saul kehrten aus Jerusalem zurück, nachdem sie ihre Aufgabe erfüllt hatten; sie nahmen Johannes mit dem Beinamen Markus mit sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'In der Gemeinde zu Antiochien gab es Propheten und Lehrer: Barnabas, Symeon, genannt Niger, Lucius von Cyrene, Manahen, ein Milchbruder des Vierfürsten Herodes, und Saul.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Während sie dem Herrn den heiligen Dienst verrichteten und fasteten, sprach der Heilige Geist: \"Sondert mir den Barnabas und Saul für die Aufgabe aus, zu der ich sie berufen habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Hierauf fasteten und beteten sie, legten ihnen die Hände auf und entließen sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Ausgesandt vom Heiligen Geiste, wanderten sie nach Seleuzia hinab, segelten von da nach Cypern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'und kamen dann nach Salamis. Dort verkündeten sie das Wort Gottes in den jüdischen Synagogen. Als Gehilfen hatten sie Johannes bei sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Sie durchwanderten die ganze Insel bis nach Paphus, wo sie einen jüdischen Zauberer und Lügenpropheten mit dem Namen Barjesus trafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Er war in der Umgebung des Prokonsuls Sergius Paulus, eines ganz verständigen Mannes. Dieser ließ Barnabas und Saul zu sich kommen und verlangte danach, das Wort Gottes zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Doch Elymas, der Zauberer - so wird sein Name übersetzt -, trat ihnen entgegen und suchte den Prokonsul vom Glauben abzuhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saul aber, der auch Paulus heißt, ward erfüllt vom Heiligen Geiste, blickte ihn scharf an');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'und sprach: \"O du, voll Bosheit und Arglist jeder Art, du Sohn des Teufels, Feind jeglicher Gerechtigkeit. Willst du nicht aufhören, die geraden Wege des Herrn zu verwirren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Siehe, die Hand des Herrn kommt jetzt über dich; du sollst blind sein und die Sonne eine Zeitlang nicht mehr sehen können.\" Sogleich umfing ihn Dunkel und Finsternis, er tastete umher und suchte nach jemand, der ihn führen würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Als der Prokonsul den Vorfall sah, wurde er gläubig, ganz ergriffen von der Lehre des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Von Paphus fuhren Paulus und seine Gefährten nach Perge in Pamphylien. Johannes aber trennte sich von ihnen und kehrte nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Sie zogen von Perge aus weiter und kamen nach Antiochien in Pisidien. Am Sabbat gingen sie in die Synagoge und nahmen Platz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Nachdem aus dem Gesetz und den Propheten vorgelesen war, ließen ihnen die Synagogenvorsteher sagen: \"Liebe Brüder! Wenn ihr einige erbauliche Worte an das Volk zu richten habt, so redet!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Da erhob sich Paulus, winkte mit der Hand und sprach: \"Ihr Männer Israels und ihr, die ihr Gott fürchtet, höret!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Der Schutzgott unseres Volkes Israel hat unsere Väter auserwählt und hat das Volk in der Fremde, im Ägypterland, vermehrt; mit hocherhobenem Arme hat er sie von dort herausgeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'An vierzig Jahre ertrug er sie in der Wüste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Sieben Völker vernichtete er im Lande Kanaan und gab ihnen deren Land zum Besitze');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'nach ungefähr vierhundertfünfzig Jahren. Dann gab er ihnen Richter bis auf den Propheten Samuel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Alsdann begehrten sie sich einen König, und Gott gab ihnen Saul, den Sohn des Kis, den Mann vom Stamme Benjamin, auf vierzig Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Nachdem er ihn verworfen hatte, erweckte er ihnen David als König. Von ihm bezeugte er: \'Gefunden habe ich David, Jesses Sohn, einen Mann nach meinem Herzen; er wird in allem meinen Willen treu erfüllen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Aus dessen Nachkommen ließ Gott, so wie es verheißen war, einen Retter für Israel auferstehen, Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Johannes hatte schon vor seinem Auftreten dem ganzen Volke Israel die Bußtaufe verkündigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Bevor jedoch Johannes seinen Lauf vollendete, sprach er: \'Ich bin nicht der, für den ihr mich haltet. Erst nach mir kommt er; ich bin\'s nicht wert, ihm die Schuhe von den Füßen aufzubinden.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Liebe Brüder, Söhne aus dem Geschlechte Abrahams, sowie ihr anderen, die ihr Gott fürchtet! An uns ist diese Heilsbotschaft ergangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Denn die Bewohner von Jerusalem und ihre Vorsteher erkannten ihn Jesus nicht: sie brachten vielmehr die Stimmen der Propheten, die jeden Sabbat verlesen werden, durch ihren Richterspruch zur Erfüllung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Obgleich sie keine Todesschuld an ihm gefunden hatten, verlangten sie doch von Pilatus, daß er getötet werden solle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Als sie dann all das, was über ihn geschrieben stand, erfüllt hatten, nahm man ihn vom Holze ab und legte ihn ins Grab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Doch Gott erweckte ihn am dritten Tage von den Toten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Und er erschien durch eine Reihe Tage denen, die mit ihm von Galiläa nach Jerusalem hinaufgezogen waren; sie sind jetzt seine Zeugen vor dem Volke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Und wir verkünden euch die frohe Botschaft, daß Gott jetzt die Verheißung, die er einst den Vätern gegeben hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'an uns, den Kindern, erfüllt hat, dadurch, daß er Jesus auferweckte. So steht es auch im zweiten Psalm geschrieben: \'Mein Sohn bist Du, heute habe ich Dich gezeugt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Und daß er ihn von den Toten auferweckte, damit er nicht der Verwesung überliefert würde, das sprach er also aus: \'Die unverbrüchlichen Heilsgüter Davids will ich euch verleihen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'So sagte er auch an einer anderen Stelle: \'Du wirst Deinen Heiligen nicht erfahren lassen die Verwesung.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Doch David starb, nachdem er dem Willen Gottes in seiner Zeit gedient hatte. Er ward zu seinen Vätern versammelt und erfuhr an sich die Verwesung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Der aber, den Gott von den Toten auferweckte, hat die Verwesung nicht erfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'So wisset denn, ihr Brüder, daß euch durch diesen Nachlaß der Sünden verkündet wird. Von allem, wovon ihr durch das Gesetz des Moses nicht habt gerechtfertigt werden können,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'wird in diesem jeder, der da glaubt, gerechtfertigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Darum seht wohl zu, daß über euch nicht das komme, was bei den Propheten gesagt ist:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '\'Seht, ihr Verächter, staunt und vergeht; ein Werk vollbringe ich in euren Tagen, ein Werk, das ihr nicht glauben würdet, wenn einer es euch nur erzählte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Als sie hinausgingen, bat man sie, sie möchten am nächsten Sabbat wieder über diesen Gegenstand reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Dann löste sich die Versammlung auf. Viele Juden und gottesfürchtige Proselyten folgten dem Paulus und dem Barnabas. Diese redeten ihnen eindringlich zu, in der Gnade Gottes zu verharren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Am folgenden Sabbat fand sich fast die ganze Stadt ein, um das Wort Gottes zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Da nun die Juden die Scharen sahen, wurden sie voll Eifersucht; sie widersprachen dem, was Paulus sagte, und stießen Schmähungen aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paulus und Barnabas aber erklärten voll Freimut: \"Euch mußte das Wort Gottes zuerst gepredigt werden. Doch weil ihr es zurückweist und euch des ewigen Lebens selbst nicht würdig achtet, so wenden wir uns an die Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Denn also hat der Herr uns anbefohlen: \'Ich habe dich zum Lichte für die Heiden bestimmt, daß du zum Heile seist bis an die Grenzen der Erde.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Als dies die Heiden hörten, freuten sie sich und priesen das Wort des Herrn. Alle, die für das ewige Leben bestimmt waren, wurden gläubig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Das Wort des Herrn aber verbreitete sich in jener ganzen Gegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Die Juden indessen hetzten die vornehmen gottesfürchtigen Frauen und die angesehensten Männer der Stadt auf, erregten eine Verfolgung gegen Paulus und Barnabas und vertrieben sie aus ihrem Gebiet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Diese aber schüttelten den Staub von ihren Füßen gegen sie und begaben sich nach Ikonium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Die Jünger aber waren voll Freude und voll Heiligen Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'In Ikonium gingen sie ebenfalls in die jüdische Synagoge und predigten, So daß eine große Menge von Juden und Heiden gläubig wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Die Juden aber, die ungläubig blieben, reizten und erbitterten die Heiden gegen die Brüder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Trotzdem konnten Sie dort noch eine Zeitlang bleiben und predigten freimütig im Vertrauen auf den Herrn, der für das Wort seiner Gnade Zeugnis gab durch Zeichen und Wunder, die er durch ihre Hände geschehen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Da spaltete sich die Bevölkerung der Stadt; die einen hielten es mit den Juden, die anderen mit den Aposteln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Als aber bei Heiden und Juden unter Anführung ihrer Vorsteher eine Bewegung entstand, sie zu mißhandeln und zu steinigen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'brachten sie sich, sobald sie das merkten, in den Städten Lykaoniens in Sicherheit: in Lystra, Derbe und in deren Umgegend.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Dort verkündigten sie nun das Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'In Lystra saß ein Mann da, kraftlos an seinen Füßen von Geburt an; er hatte niemals gehen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Dieser hörte der Predigt des Paulus aufmerksam zu. Der aber blickte ihn an, sah, daß er Glauben hatte, um geheilt werden zu können,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'und sprach zu ihm mit lauter Stimme: \"Stell dich aufrecht auf deine Füße!\" Und er sprang auf und ging umher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Als die Volksscharen sahen, was Paulus getan hatte, erhoben sie ihre Stimmen und riefen auf lykaonisch: \"Götter in Menschengestalt sind zu uns herabgestiegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Den Barnabas nannten sie Zeus, den Paulus Hermes, weil er das Wort führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Der Priester des Zeus vor der Stadt ließ Stiere und Kränze an das Tor bringen und wollte samt den Volksscharen opfern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Als die Apostel Barnabas und Paulus dies erfuhren, zerrissen sie ihre Kleider, sprangen unter das Volk');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'und riefen laut: \"Ihr Männer! Was macht ihr da? Auch wir sind schwache Menschen wie ihr. Wir bringen euch die frohe Botschaft, damit ihr von diesen nichtigen Götzen euch bekehren sollt zu dem lebendigen Gott, der Himmel, Erde, Meer und alles, was darinnen ist, erschaffen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'In den vergangenen Zeiten ließ er alle Völker ihre eigenen Wege gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Gleichwohl hat er sich nicht unbezeugt gelassen: Er spendete Wohltaten: Vom Himmel her gibt er euch Regen und fruchtbare Zeiten, er schenkt euch Nahrung und erfüllt eure Herzen mit Frohsinn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Nur mit Mühe konnten sie durch diese Worte die Volkscharen abhalten, ihnen Opfer darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Dann kamen aber Juden von Antiochien und Ikonium her und brachten das Volk auf ihre Seite. Sie steinigten den Paulus und schleiften ihn zur Stadt hinaus, weil sie ihn für tot hielten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Wie nun die Jünger um ihn herum standen, erhob er sich und kehrte in die Stadt zurück. Am folgenden Tage ging er mit Barnabas weiter nach Derbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Sie verkündeten in dieser Stadt das Evangelium und gewannen viele Jünger. Dann kehrten sie über Lystra und Ikonium wieder nach Antiochien zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Sie stärkten dabei die Herzen der Jünger, ermahnten sie, im Glauben zu beharren, und wiesen sie darauf hin, daß wir durch viele Drangsale in das Reich Gottes eingehen müßten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Sie stellten in jeder Gemeinde unter Handauflegung mit Gebet und Fasten Presbyter für sie auf und empfahlen sie dem Herrn, dem sie sich gläubig zugewandt hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Sie kamen dann über Pisidien nach Pamphylien');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'und verkündeten das Wort des Herrn in Perge. Von da reisten sie nach Attalia hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Hier gingen sie nach Antiochien in See. Dort hatte man sie ja der Gnade Gottes übergeben zu dem Werke, das sie nun vollendet hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Nach ihrer Ankunft versammelten sie die Gemeinde und erzählten, welch große Dinge Gott durch sie gewirkt und daß er den Heiden die Tür des Glaubens geöffnet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Sie verweilten geraume Zeit bei den Jüngern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Da kamen einige aus Judäa herab und wollten die Brüder belehren: \"Wenn ihr euch nicht nach dem Brauche des Moses beschneiden lasset, so könnt ihr das Heil nicht erlangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Es entstand eine Aufregung, und Paulus und Barnabas hatten nicht wenig gegen sie zu streiten. Da beschloß man, Paulus und Barnabas, sowie einige andere aus ihrer Mitte, sollten wegen dieser Streitfrage zu den Aposteln und Presbytern nach Jerusalem hinaufgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Von der Gemeinde eine Strecke Weges begleitet, zogen sie durch Phönizien und Samarien hindurch, erzählten, wie die Heiden sich bekehrt hätten, und sie bereiteten allen Brüdern große Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'In Jerusalem angekommen, wurden sie von der Gemeinde, den Aposteln und den Presbytern empfangen. Sie berichteten, welch große Dinge Gott durch sie gewirkt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Einige aus der Sekte der Pharisäer, die gläubig geworden waren, standen aber auf und erklärten: \"Sie müssen sich beschneiden lassen und das Gesetz des Moses halten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Da versammelten sich die Apostel und die Presbyter, um über die Forderung zu beraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Nach langem Hin- und Herreden erhob sich Petrus und sprach zu ihnen: \"Liebe Brüder! Ihr wißt, daß schon vor Zeiten Gott unter euch den Ratschluß kundgetan hat, daß die Heiden durch meinen Mund das Wort des Evangeliums hören und gläubig werden sollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Gott, der Herzenskenner, hat für sie Zeugnis abgelegt, indem er ihnen, wie auch uns, den Heiligen Geist verliehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Er machte keinen Unterschied mehr zwischen uns und ihnen, da er durch den Glauben ihre Herzen reinigte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Weshalb wollt ihr jetzt Gott versuchen und den Jüngern ein Joch auf den Nacken legen, das weder unsere Väter noch wir ertragen konnten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Wir glauben vielmehr, zum Heile zu kommen durch die Gnade des Herrn Jesus Christus in gleicher Weise wie auch sie.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Die ganze Versammlung schwieg. Sie lauschten dem Barnabas und Paulus, die erzählten, welch große Zeichen und Wunder Gott durch sie unter den Heiden gewirkt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Als sie zu Ende waren, ergriff Jakobus das Wort und sprach: \"Liebe Brüder! Schenkt mir Gehör!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Symeon hat erzählt, wie Gott erstmals darauf gesehen hat, aus den Heiden ein Volk für seinen Namen zu gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Es stimmen damit auch die Worte der Propheten überein wie geschrieben steht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '\'Ich komme danach wieder, um das zerfallene Zelt Davids wieder aufzurichten und, was zerstört war, wiederherzustellen und dieses wieder hinzustellen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'damit auch die anderen Menschen den Herrn suchen, ja, alle Völker, über die mein Name genannt wird; so spricht der Herr, der solches tut.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Dies ist seit Ewigkeit kund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'So meine ich nun, man solle denen, die vom Heidentum sich zu Gott bekehren, keine weiteren Lasten aufbürden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'vielmehr ihnen jetzt nur ein Schreiben senden, sie sollen von Befleckung durch die Götzen, von Unzucht, von dem Genusse des Erstickten und des Blutes sich enthalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Denn Moses hat von alters her in jeder Stadt schon seine Prediger, da in den Synagogen an allen Sabbaten aus ihm vorgelesen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Hierauf beschlossen die Apostel und Presbyter samt der ganzen Gemeinde, aus ihrer Mitte Männer auszuwählen und sie mit Paulus und Barnabas nach Antiochien zu senden. Es waren: Judas mit dem Beinamen Barsabbas und Silas, Männer, die unter den Brüdern eine führende Stellung einnahmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Man gab ihnen folgendes Schreiben mit: \"Die Apostel und die Presbyter entbieten als Brüder ihren Brüdern aus dem Heidentum in Antiochien, Syrien und Cilizien ihren Gruß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Wir haben erfahren, daß einige aus unserer Mitte euch mit ihren Reden in Verwirrung und Unruhe gebracht haben. Wir hatten ihnen keinen Auftrag dazu gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'So haben wir uns denn versammelt und beschlossen, Männer auszuwählen und sie zugleich mit unserem geliebten Barnabas und Paulus zu euch zu senden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Männern, die ihr Leben eingesetzt haben für den Namen unseres Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Wir haben demnach den Judas und den Silas abgesandt, die euch mündlich dasselbe zu verkünden haben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Es hat dem Heiligen Geist und uns gefallen, euch keine weiteren Lasten aufzubürden außer folgenden notwendigen Stücken:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Ihr sollt euch vom Götzenopfer enthalten, von Blut, von Ersticktem und von Unzucht. Wenn ihr euch davor bewahrt, werdet ihr recht handeln. Lebt wohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Also wurden sie entlassen und zogen nach Antiochien hinab. Sie versammelten die Gemeinde und übergaben das Schreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Man las es und freute sich aber die beruhigenden Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas und Silas, die zugleich Propheten waren, stärkten und ermunterten die Brüder durch viele Ansprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Erst nachdem sie längere Zeit verweilt hatten, wurden sie von den Brüdern mit Friedensgrüßen zu ihren Auftraggebern entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Silas entschloß sich, dort zu bleiben; Judas indessen kehrte allein nach Jerusalem zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paulus und Barnabas aber blieben in Antiochien, lehrten und verkündeten mit noch vielen anderen das Wort des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Nach einiger Zeit sprach Paulus zu Barnabas: \"Wir wollen nachsehen, wie es den Brüdern in all den Städten geht, in denen wir das Wort des Herrn verkündet haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas wollte noch den Johannes, der Markus genannt wird, mitnehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Paulus aber wollte den, der sie in Pamphylien verlassen und an ihrem Wirken nicht teilgenommen hatte, nicht um sich wissen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Es kam zu einer heftigen Auseinandersetzung, so daß sie sich voneinander trennten. Barnabas fuhr mit Markus nach Cypern;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paulus aber wählte sich den Silas und reiste ab, von den Brüdern der Gnade des Herrn empfohlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Er durchzog Syrien und Cilizien und stärkte die Gemeinden indem er befahl, die Vorschriften der Apostel und der Ältesten zu beobachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Er kam auch nach Derbe und Lystra. Hier war ein Jünger namens Timotheus, der Sohn einer gläubig gewordenen Jüdin und eines heidnischen Vaters.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Die Brüder in Lystra und Ikonium stellten ihm ein gutes Zeugnis aus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'und Paulus wünschte, ihn als Begleiter mitzunehmen. Mit Rücksicht auf die Juden, die in jenen Gegenden lebten, beschnitt er ihn; denn alle wußten, daß sein Vater ein Heide war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Als sie nun durch die Städte wanderten, übergaben sie ihnen die von den Aposteln und Presbytern in Jerusalem gefaßten Beschlüsse zur Beachtung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Die Gemeinden wurden im Glauben gestärkt und nahmen täglich an Zahl zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Sie zogen dann durch Phrygien und die Landschaft von Galatien, weil ihnen vom Heiligen Geiste verwehrt wurde, das Wort Gottes in Asien zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Sie kamen gegen Mysien hin und wollten nach Bithynien weitergehen, doch der Geist Jesu gestattete es ihnen nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'So zogen sie denn an Mysien vorbei und kamen nach Troas hinab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Hier hatte Paulus in der Nacht ein Gesicht: Ein Mazedonier stand vor ihm und bat: \"Komm herüber nach Mazedonien und hilf uns!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Nach dieser Erscheinung suchten wir alsbald nach Mazedonien hinüberzufahren, weil wir daraus schlossen, daß Gott uns gerufen habe, um dort das Evangelium zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Wir fuhren von Troas ab, geradewegs nach Samothrake, am folgenden Tag nach Neapolis');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'und dann von da nach Philippi. Dies ist die erste Stadt in diesem Bezirk von Mazedonien, eine Kolonie. Wir hielten uns in dieser Stadt einige Tage auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Am Sabbat gingen wir vors Tor hinaus an einen Fluß, wo wir eine Gebetsstätte vermuteten. Wir setzten uns und sprachen zu den Frauen, die da zusammengekommen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Auch eine Purpurhändlerin aus der Stadt Thyatira, namens Lydia, eine gottesfürchtige Frau, hörte zu. Ihr schloß der Herr das Herz auf, daß sie der Predigt des Paulus Aufmerksamkeit schenkte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Sie ließ sich samt ihrer Familie taufen und bat: \"Wenn ihr die Überzeugung habt, daß ich eine Jüngerin des Herrn bin, so kommt in mein Haus und wohnt dort.\" Und sie nötigte uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Auf dem Wege zur Gebetsstätte begegnete uns eines Tages eine Magd, die einen Wahrsagegeist hatte. Sie brachte durch ihre Wahrsagekunst ihrer Herrschaft großen Gewinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Sie lief hinter Paulus her und schrie: \"Diese Männer sind Diener des höchsten Gottes; sie verkünden euch den Weg zum Heile.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'So machte sie es viele Tage lang. Paulus ward sehr unwillig darüber, wandte sich um und sprach zu dem Geiste: \"Ich befehle dir im Namen Jesu Christi, von ihr auszufahren.\" Und er fuhr aus von ihr in derselben Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Als nun ihre Herrschaft sah, daß die Aussicht auf Gewinn dahin sei, ergriffen sie Paulus und den Silas und schleppten sie auf den Marktplatz vor die Obrigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Man führte sie vor die Stadtrichter und sprach:\"Diese Menschen bringen unsere Stadt in die größte Verwirrung. Sie sind Juden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'und verkünden Gebräuche, die wir als Römer nicht annehmen noch ausüben dürfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Auch die Volksmenge erhob sich gegen mit sie. Die Stadtrichter ließen ihnen die Kleider herunterreißen und sie mit Ruten schlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Nachdem sie ihnen viele Streiche hatten geben lassen, warfen sie beide ins Gefängnis und gaben dem Kerkermeister den Befehl, sie in sicherem Gewahrsam zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Auf diese Weisung hin brachte er sie in das innere Gefängnis und spannte zur Sicherheit ihre Füße in den Block.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Um Mitternacht sangen nun Paulus und Silas betend Gott ein Loblied. Die Gefangenen hörten ihnen zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Da entstand plötzlich ein gewaltiges Erdbeben, so daß die Grundmauern des Gefängnisses erschüttert wurden. Im Nu waren alle Tore offen, und die Fesseln fielen von allen ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Als der Kerkermeister erwachte und die Tore des Gefängnisses offenstehen sah, zog er sein Schwert und wollte sich das Leben nehmen in der Annahme, die Gefangenen seien entflohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Paulus aber rief mit lauter Stimme: \"Tu dir kein Leid an; wir sind alle noch hier.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Er ließ sich Licht bringen, trat ein und fiel Paulus und Silas zitternd zu Füßen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Er führte sie heraus und fragte: \"Ihr Herren, was muß ich tun, damit ich das Heil erlange?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Sie antworteten: \"Glaube an den Herrn Jesus, alsdann wirst du samt deinem Hause das Heil erlangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Dann verkündeten sie ihm und seiner ganzen Familie das Wort des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Noch in derselben Nachtstunde nahm er sie zu sich und wusch ihnen die Striemen ab. Auch ließ er sich sogleich samt den Seinigen taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Dann führte er sie in sein Haus und ließ ihnen ein Mahl bereiten voll Freude, daß er mit seiner Familie zum Glauben an Gott gekommen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Als es Tag geworden war schickten die Stadtrichter Amtsdiener mit dem Befehle: \"Laß diese Leute frei!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Der Kerkermeister berichtete diesen Befehl dem Paulus: \"Die Stadtrichter haben hergeschickt, man solle euch freilassen; so geht denn hinaus und zieht im Frieden weiter.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Paulus jedoch sagte zu ihnen: \"Ohne Untersuchung haben sie uns, die wir doch römische Bürger sind, öffentlich schlagen und ins Gefängnis bringen lassen; und nun wollen sie uns heimlich ausweisen. Nein, sie sollen selber kommen und uns herausführen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Die Amtsdiener berichteten dies den Stadtrichtern. Als diese hörten, daß sie römische Bürger seien, gerieten sie in Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Sie gingen hin, entschuldigten sich und führten sie heraus mit der Bitte, sie möchten die Stadt verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Sie verließen das Gefängnis und begaben sich zu der Lydia. Dort trafen sie Brüder, ermunterten sie und zogen danach weiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Über Amphipolis und Appolonia gelangten sie nach Thessalonich, wo die Juden eine Synagoge hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Nach seiner Gewohnheit ging Paulus zu ihnen hinein und sprach an drei Sabbaten zu ihnen, wobei er von der Heiligen Schrift ausging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Er gab ihnen Aufschluß und legte dar, daß Christus leiden und von den Toten auferstehen mußte und: \"dieser ist der Christus, Jesus, den ich euch verkünde\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Einige aus ihnen ließen sich überzeugen und schlossen sich Paulus und Silas an, ebenso eine Anzahl gottesfürchtiger Heiden und nicht wenige vornehme Frauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Hierüber wurden die Juden aufgebracht. Sie holten Marktgesindel herbei, erregten einen Auflauf und brachten die Stadt in Aufruhr. Sie zogen vor das Haus des Jason und suchten sie, um sie dem Volke vorzuführen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'fanden sie aber nicht. So schleppten sie den Jason und einige Brüder vor die städtische Behörde und schrien: \"Die Menschen, die die ganze Welt in Aufruhr bringen, sind auch hier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Jason hat sie aufgenommen. Sie alle handeln den Verordnungen des Kaisers zuwider; sie sagen nämlich, ein anderer sei König, Jesus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'So reizten sie das Volk und die Behörden auf, die das mitanhörten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Diese ließen sich von Jason und den übrigen Bürgschaft geben und entließen sie dann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Noch in derselben Nacht schickten die Brüder den Paulus und den Silas nach Beröa weiter. Nach ihrer Ankunft begaben sie sich in die Synagoge der Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Diese waren edler gesinnt als die in Thessalonich; sie nahmen das Wort mit aller Bereitwilligkeit an und forschten täglich in den Schriften, ob es sich auch so verhalte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Viele von ihnen wurden gläubig und auch viele von den vornehmen heidnischen Frauen und Männern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Als aber die Juden in Thessalonich erfuhren, daß das Wort Gottes von Paulus auch in Beröa verkündet werde, kamen sie auch dahin und brachten das Volk in Erregung und in Aufruhr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Deshalb geleiteten die Brüder den Paulus sogleich scheinbar bis ans Meer, während Silas und Timotheus dort zurückblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Die Begleiter des Paulus brachten ihn bis nach Athen. Von dort nahmen sie den Auftrag mit, Silas und Timotheus möchten so schnell wie möglich nachkommen; dann reisten sie ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Während Paulus in Athen noch auf sie wartete, ward er innerlich tief erregt, da er sah, wie die Stadt voll von Götterbildern war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Er redete in der Synagoge mit den Juden und den Gottesfürchtigen und auf dem Markt tagtäglich zu denen, die gerade dorthin kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Dabei gerieten einige epikuräische und stoische Weltweise mit ihm zusammen, und manche sagten: \"Was mag wohl dieser Schwätzer sagen wollen?\" Andere: \"Er scheint ein Herold fremder Gottheiten zu sein.\" Er verkündete nämlich die frohe Botschaft von Jesus und die Auferstehung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Da nahmen sie ihn mit sich und führten ihn auf den Areopag und fragten, \"Dürfen wir wohl wissen, was das für eine neue Lehre ist, die du verkündest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Du gibst uns ja seltsame Dinge zu hören; wir möchten nun gern wissen, welche Bewandtnis es damit habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Alle Athener und auch die Fremden, die dort wohnten, haben für nichts anderes Zeit, als das Allerneueste zu erzählen oder zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Da trat Paulus mitten im Areopag auf und sprach: \"Ihr Männer von Athen! Ich finde, daß ihr durchaus gottesfürchtig seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Denn als ich umherging und eure Götterbilder genau ansah, da fand ich einen Altar mit der Inschrift: \'Dem unbekannten Gott\'. Was ihr verehrt, ohne es zu kennen, gerade das verkündige ich euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Gott, der die Welt und alles, was in ihr ist, erschaffen hat, der Herr des Himmels und der Erde, wohnt nicht in Tempeln, die von Menschenhänden gemacht sind;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'auch läßt er sich nicht von Menschenhänden bedienen, als ob er irgend etwas brauche; er selber spendet allem Leben, Odem und gar alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Er hat aus einem Menschen das ganze menschliche Geschlecht entstehen lassen, damit es auf der ganzen Oberfläche der Erde wohne; er setzte auch die Zeiten fest und die Grenzen ihrer Wohnsitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Sie sollen Gott suchen, ob sie ihn herausfühlten und fänden, ihn, der ja keinem aus uns ferne ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'In ihm leben wir, bewegen wir uns und sind wir, wie es ja auch einige eurer Dichter sagen: \'Sind wir doch seines Geschlechtes\'.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Sind wir nun so göttlichen Geschlechtes, dann dürfen wir nicht meinen, die Gottheit sei dem Golde, dem Silber und dem Steine, Erzeugnissen der bildenden Kunst und menschlicher Erfindung gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Über die Zeiten der Unwissenheit hat Gott hinweggesehen; doch jetzt tut er den Menschen kund, daß alle allenthalben anderen Sinnes werden sollen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'wie er denn einen Tag festgesetzt hat, an dem er die Welt in Gerechtigkeit richten wird. Und dazu hat er einen Mann bestimmt, den er vor allem dadurch beglaubigte, daß er ihn von den Toten auferweckt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Als sie von einer Auferstehung von den Toten hörten, spotteten einige, andere aber sagten: \"Hierüber wollen wir dich ein andermal hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'So ging Paulus aus ihrer Mitte hinweg.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Doch einige Männer schlossen sich ihm an und wurden gläubig, unter ihnen Dionysius, ein Mitglied des Areopags, und eine Frau namens Damaris und noch einige andere mit ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Hierauf schied Paulus von Athen und begab sich nach Korinth.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Dort traf er einen Juden mit Namen Aquila, der aus Pontus gebürtig und kurz zuvor aus Italien angekommen war, und dessen Frau Priszilla. Claudius hatte nämlich angeordnet, daß alle Juden Rom verlassen müßten. Zu ihnen begab er sich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'und weil sie das gleiche Handwerk hatten, blieb er bei ihnen und nahm dort Arbeit; sie waren nämlich von Beruf Zeltweber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Jeden Sabbat sprach er in der Synagoge wobei er den Namen des Herrn Jesus einflocht und suchte Juden und Heiden zu überzeugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Als jedoch Silas und Timotheus von Mazedonien her eingetroffen waren, widmete sich Paulus ganz der Predigt und wies den Juden nach, daß Jesus der Messias ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Da sie sich aber dagegen auflehnten und Lästerungen ausstießen, schüttelte er seine Kleider aus und sprach zu ihnen: \"Euer Blut komme über euer Haupt. Mich trifft keine Schuld; von nun an will ich zu den Heiden gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Er ging von da weg und begab sich in das Haus eines gottesfürchtigen Mannes, Titius Justus mit Namen; sein Haus stieß an die Synagoge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Der Synagogenvorsteher Krispus nahm mit seiner ganzen Familie den Glauben an den Herrn an. Auch viele andere Zuhörer in Korinth wurden gläubig und ließen sich taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Es sprach aber bei Nacht der Herr in einem Gesicht zu Paulus: \"Fürchte dich nicht! Rede weiterhin und schweige nicht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Ich bin mit dir, und niemand soll dir weiterhin ein Leid zufügen; denn viel Volk in dieser Stadt ist mein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Paulus blieb dort ein Jahr und sechs Monate und predigte unter ihnen das Wort Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Als Gallio Prokonsul von Achaia war, traten die Juden einmütig gegen Paulus auf, führten ihn vor den Richterstuhl');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'und erhoben die Anklage: \"Der verführt die Leute, Gott in einer Weise zu verehren, die gegen das Gesetz verstößt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Schon war Paulus im Begriffe zu erwidern, da sagte Gallio zu den Juden: \"Würde es sich um eine Freveltat oder um ein Bubenstück handeln, ihr Juden, so würde ich eure Klage annehmen, so wie es sich gehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Handelt es sich aber um Streitigkeiten über Lehre, Namen oder über euer Gesetz, da möget ihr selbst zusehen. In solchen Dingen will ich nicht Richter sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Und er ließ sie von seinem Richterstuhl fortjagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Nun fielen alle Heiden über den Synagogenvorsteher Sosthenes her und schlugen ihn vor dem Richterstuhle. Gallio aber kümmerte sich nicht darum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Paulus verblieb noch geraume Zeit. Hierauf nahm er Abschied von den Brüdern und fuhr nach Syrien. Bei ihm waren Priszilla und Aquila. In Kenchreä ließ er sich das Haupt scheren, denn er hatte ein Gelübde gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Sie kamen nach Ephesus, wo er sie zurückließ. Er selbst ging in die Synagoge und predigte den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Obwohl sie ihn baten, längere Zeit zu bleiben, ging er doch nicht darauf ein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'sondern nahm Abschied mit den Worten: \"So Gott will, werde ich wieder zu euch kommen.\" - Dann reiste er von Ephesus weg');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'und kam nach Cäsarea. Von dort ging er nach Jerusalem hinauf, begrüßte die Gemeinde und begab sich dann nach Antiochien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Nach einiger Zeit brach er wieder auf. Er durchwanderte nacheinander die Landschaft von Galatien und Phrygien und bestärkte alle Jünger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Es war nun ein Jude namens Apollos, aus Alexandrien stammend, ein gelehrter und schriftkundiger Mann, nach Ephesus gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Er war in der Lehre des Herrn unterrichtet, redete mit glühender Begeisterung und lehrte genau über Jesus, obwohl er nur die Johannestaufe kannte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Mit großem Freimut redete er in der Synagoge. Als Priszilla und Aquila ihn gehört hatten, nahmen sie ihn zu sich und setzten ihm die Lehre Gottes genauer auseinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Da er nach Achaia zu reisen wünschte, ermunterten ihn die Brüder und schrieben an die dortigen Jünger, sie möchten ihn gut aufnehmen. Nach seiner Ankunft leistete er den Gläubigen vortreffliche Dienste durch seine Begabung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Denn schlagend widerlegte er öffentlich die Juden und wies aus der Schrift nach, daß Jesus der Christus sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Während Apollos in Korinth weilte, kam Paulus, nachdem er das Hochland durchwandert hatte, nach Ephesus. Dort traf er einige Jünger');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'und fragte sie: \"Habt ihr den Heiligen Geist empfangen, als ihr gläubig wurdet?\" Sie antworteten ihm: \"Nein, wir haben nicht einmal gehört, daß es einen Heiligen Geist gebe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Er fragte weiter: \"Welche Taufe habt ihr denn empfangen?\" Sie antworteten: \"Die Taufe des Johannes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paulus erwiderte: \"Johannes taufte zur Buße und mahnte das Volk, an den zu glauben, der nach ihm komme, nämlich Jesus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Da sie dies gehört hatten, ließen sie sich auf den Namen des Herrn Jesus taufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Als Paulus ihnen dann die Hände auflegte, kam der Heilige Geist auf sie herab, sie redeten in Sprachen und weissagten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Es waren im ganzen ungefähr zwölf Männer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Er ging sodann in die Synagoge, predigte mit großem Freimut drei Monate hindurch und redete überzeugungsvoll vom Reiche Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Da aber einige in ihrem Unglauben hartnäckig verharrten, ja vor dem Volke die Lehre des Herrn lästerten, trennte er sich von ihnen und sonderte die Jünger ab. Er hielt nun täglich seine Lehrvorträge in dem Hörsaal eines gewissen Tyrannus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Das währte zwei Jahre lang, so daß alle Bewohner von Asien, Juden und Heiden, Gelegenheit hatten, das Wort des Herrn zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Auch wirkte Gott durch die Hand des Paulus ungewöhnliche Wunder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Sogar Schweißtücher und Schürzen legte man von seinem Leib weg auf die Kranken, und die Krankheiten wichen von ihnen, und die bösen Geister fuhren aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Einige der herumziehenden jüdischen Teufelsbeschwörer versuchten, über die von bösen Geistern Besessenen den Namen des Herrn Jesus anzurufen indem sie sagten: \"Ich beschwöre euch bei Jesus, den Paulus verkündet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Es waren die sieben Söhne des jüdischen Oberpriesters Skeuas, die es taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Aber der böse Geist erwiderte ihnen: \"Jesus kenne ich, auch Paulus ist mir wohlbekannt; wer aber seid denn ihr?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Damit stürzte sich der Mensch, in dem der böse Geist war, auf sie, überwältigte alle miteinander und ließ seine Macht an ihnen derart aus, daß sie nackt und wund aus jenem Hause flohen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Dies wurde allen Juden und Heiden, die in Ephesus wohnten, bekannt, und Furcht kam über sie alle; der Name des Herrn Jesus aber kam hoch zu Ehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Viele Gläubige kamen, bekannten und offenbarten, was sie getan hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Viele aber, die Zauberkünste getrieben hatten, trugen ihre Bücher zusammen und verbrannten sie vor aller Augen. Man schätzte ihren Wert insgesamt auf fünfzigtausend Silberdrachmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'So breitete sich das Wort des Herrn kräftig aus und erwies sich sehr wirksam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Hierauf faßte Paulus den Plan, über Mazedonien und Achaia nach Jerusalem zu reisen. \"Wenn ich dort gewesen bin\", sprach er, \"muß ich auch Rom sehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Er sandte zwei seiner Gehilfen, Timotheus und Erastus, nach Mazedonien. Er selbst blieb noch einige Zeit in Asien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Es entstand aber um jene Zeit ein ganz gewaltiger Aufruhr wegen der Lehre des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Ein Silberschmied namens Demetrius verschaffte nämlich durch Anfertigung von silbernen Artemistempelchen den Handwerkern großen Verdienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Nun rief er diese und auch die anderen Arbeiter, die dasselbe Geschäft hatten, zusammen und sprach: \"Ihr Männer, wie ihr wißt, fließt unser Wohlstand aus diesem Gewerbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Nun aber seht und hört ihr, wie nicht allein in Ephesus, sondern fast im ganzen Asien dieser Paulus durch seine Überredungskunst viel Volk abwendig gemacht hat. Er behauptet nämlich, das seien gar keine Götter, die mit Händen gemacht sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Es droht aber nicht nur die Gefahr, daß unser Erwerbszweig zu Schaden komme, auch das Heiligtum der großen Göttin Artemis selbst wird in Verachtung kommen; ja, sie selbst verliert an ihrer Majestät, sie, die doch ganz Asien, ja, alle Welt verehrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Da sie dies hörten, gerieten sie in Wut und schrien: \"Groß ist die Artemis von Ephesus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Die Aufregung teilte sich der ganzen Stadt mit: Alles stürmte ins Theater, und man schleppte die Mazedonier Gaius und Aristarchus, Reisegefährten des Paulus, mit dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Paulus wollte in die Volksversammlung gehen, aber die Jünger ließen ihn nicht fort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Auch einige mit ihm befreundete höhere Beamte ließen ihn dringend bitten, sich nicht ins Theater zu begeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Hier schrien nun die einen dies, die anderen das; denn es herrschte in der Versammlung eine heillose Verwirrung, und die meisten wußten gar nicht, weshalb sie zusammengekommen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Da beredete man aus der Menge einen Alexander, den die Juden vorschoben. Alexander winkte mit der Hand und wollte sich vor dem Volke verteidigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Als man aber erkannte, daß er ein Jude war, schrien sie alle wie aus einem Munde fast zwei Stunden lang: \"Groß ist die Artemis von Ephesus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Endlich beschwichtigte der Stadtschreiber die Menge und hielt folgende Ansprache: \"Epheser! Wer in aller Welt wüßte nicht, daß die Stadt Ephesus die Hüterin ist des Tempels der großen Artemis und ihres Bildes, das vom Himmel gefallen ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Dies ist unbestritten. Also müßt ihr Ruhe bewahren und dürft nichts Übereiltes tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Ihr habt diese Männer vorgeführt, die weder Tempelräuber noch Lästerer unserer Göttin sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Wenn Demetrius und seine Zunftgenossen Klage wider jemanden zu führen haben, so werden dafür Gerichtstage abgehalten und sind Gerichtsherren da; dort mögen sie einander verklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Habt ihr aber noch eine weitere Beschwerde, so mag sie in einer regelrechten Volksversammlung erledigt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Wir laufen nämlich noch Gefahr, wegen der heutigen Vorkommnisse des Aufruhrs angeklagt zu werden, da gar kein Anlaß vorhanden ist, mit dem wir diesen Auflauf rechtfertigen können.\" Nach diesen Worten löste er die Versammlung auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Als der Aufruhr sich gelegt hatte, beschied Paulus, die Jünger zu sich und gab ihnen Ermahnungen. Dann verabschiedete er sich und zog fort nach Mazedonien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Er durchzog jene Gegend, ermahnte eindringlich die Jünger und begab sich nach Griechenland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Dort war er drei Monate lang. Als er nach Syrien fahren wollte, planten die Juden einen Anschlag gegen ihn. Deshalb entschloß er sich, den Rückweg über Mazedonien zu nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Es begleiteten ihn bis nach Asien: Sopater, der Sohn des Pyrrhus, aus Beröa, Aristarch und Sekundus aus Thessalonich, Gaius aus Derbe, ferner Timotheus sowie Tychikus und Trophimus aus Asien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Diese reisten voraus und erwarteten uns in Troas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Wir aber fuhren nach den Tagen der Ungesäuerten Brote von Philippi ab und trafen sie fünf Tage später in Troas. Dort hielten wir uns sieben Tage auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Als wir nun am ersten Tage der Woche zum Brotbrechen versammelt waren, redete Paulus zu den Versammelten. Da er schon tags darauf weiterreisen wollte, dehnte er seine Rede bis Mitternacht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Zahlreiche Lampen brannten in dem Obergemach, wo wir versammelt waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Ein Jüngling namens Eutychus saß auf der Fensterbank. Da die Predigt des Paulus sich länger hinzog, war er in tiefen Schlaf gesunken, stürzte, vom Schlaf überwältigt, vom dritten Stockwerk hinab und wurde tot aufgehoben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Paulus ging hinab, beugte sich über ihn, umfaßte ihn und sagte: \"Beunruhigt euch nicht, es ist noch Leben in ihm.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Dann ging er wieder hinauf, brach das Brot und aß. Er redete noch lange, bis zum Tagesanbruch; darauf reiste er ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Den Jüngling aber führten sie lebend herbei, und sie fühlten sich nicht wenig getröstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Wir gingen voraus auf das Schiff und segelten nach Assus weiter in der Absicht, dort den Paulus an Bord zu nehmen. So hatte er es nämlich selbst bestimmt; er selbst wollte zu Fuß dahin kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Er traf mit uns in Assus zusammen, wir nahmen ihn an Bord und kamen nach Mytilene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Von dort fuhren wir weiter und gelangten anderen Tags auf die Höhe von Chios; am nächsten Tag liefen wir Samos an übernachteten in Trogyllion und gelangten tags darauf nach Milet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Paulus hatte sich nämlich entschlossen an Ephesus vorbeizufahren, um in Asien keine Zeit zu verlieren. Denn er hatte Eile, um womöglich zu Pfingsten in Jerusalem zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Von Milet sandte er nach Ephesus und beschied die Presbyter der Gemeinde zu sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Als sie bei ihm eingetroffen waren, sprach er zu ihnen: \"Ihr wißt, wie ich vom ersten Tag an, da ich Asien betrat, die ganze Zeit bei euch verweilte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Ich habe dem Herrn gedient in aller Demut unter Tränen in Prüfungen, die mir widerfahren sind durch die Nachstellungen der Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Ich habe nichts versäumt und habe euch alles verkündigt und gelehrt, was euch zuträglich sein könnte, öffentlich, wie auch von Haus zu Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Und ich beschwor die Juden wie die Heiden, sie möchten sich zu Gott bekehren und an unseren Herrn Jesus glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Und jetzt fühle ich mich in meinem Innern genötigt, nach Jerusalem zu reisen. Was mir daselbst begegnet, weiß ich nicht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'nur das versichert mir der Heilige Geist von Stadt zu Stadt, daß Bande und Trübsal in Jerusalem meiner warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Allein, ich halte mein Leben nicht der Rede wert, wenn ich nur meinen Lauf vollende und meine Aufgabe erfülle, die ich vom Herrn Jesus erhalten habe: das Evangelium von der Gnade Gottes zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Seht, ich weiß, was mich anbetrifft, daß ihr mich nicht mehr von Angesicht zu Angesicht sehen werdet, ihr alle, bei denen ich als Prediger des Reiches wandelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Darum versichere ich es euch am heutigen Tage: Ich bin vom Blute aller rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Ich habe es gewiß nicht unterlassen, euch den ganzen Ratschluß Gottes zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Habt acht auf euch und auf die ganze Herde, in der euch der Heilige Geist zu Bischöfen bestellt hat, die Kirche Gottes zu weiden, die er für sich erworben hat mit dem Blute eines, der sein eigen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Ich weiß: Nach meinem Weggang dringen wilde Wölfe bei euch ein und schonen nicht die Herde;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Ja, selbst aus eurer Mitte werden Männer auftreten, die mit verkehrten Reden die Jünger auf ihre Seite ziehen wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'So seid denn wachsam und denkt stets daran, wie ich drei Jahre lang bei Tag und Nacht nicht aufgehört habe, mit Tränen einen jeden einzeln zu mahnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Und nun empfehle ich euch Gott und dem Worte seiner Gnade. Er nur vermag es, euch aufzubauen und euch inmitten aller Heiligen das Erbe zu verleihen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Silber, Gold oder Kleider habe ich von keinem einzigen begehrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Ihr wißt, daß diese meine Hände selber sorgten für das, was ich und meine Begleiter brauchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'In allem habe ich euch gezeigt, daß man durch Arbeit sich der Schwachen annehmen soll, der Worte des Herrn Jesus eingedenk, wie er selbst gesagt hat: \'Geben ist seliger als Nehmen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Nach diesen Worten kniete er mit allen nieder und betete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Alle brachen in lautes Weinen aus; sie fielen Paulus um den Hals und küßten ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Am meisten betrübten sie sich über das Wort, als er gesagt hatte, daß sie ihn nicht mehr von Angesicht sehen würden. Sodann gaben sie ihm das Geleit bis ans Schiff.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Als wir uns von ihnen losgerissen hatten, fuhren wir ab. In gerader Richtung kamen wir nach Kos; tags darauf nach Rhodos und von da nach Patara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Wir fanden ein Schiff, das nach Phönizien fuhr, bestiegen es und fuhren ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Wir bekamen Cypern in Sicht, ließen es links liegen, steuerten auf Syrien zu und gelangten nach Tyrus. Dort sollte das Schiff seine Fracht löschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Wir suchten die Jünger auf und blieben daselbst sieben Tage. Auf Eingebung des Geistes rieten sie dem Paulus, er solle nicht nach Jerusalem hinaufgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Dennoch machten wir uns nach Ablauf dieser Tage auf den Weg, wobei uns alle mit Weib und Kind das Geleit gaben bis vor die Stadt hinaus. Am Strande knieten wir nieder und beteten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'So nahmen wir Abschied voneinander. Wir bestiegen das Schiff, jene aber kehrten nach Hause zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Wir legten den letzten Teil unserer Seefahrt zurück und kamen von Tyrus nach Ptolemais. Dort begrüßten wir die Brüder und blieben einen Tag bei ihnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Am folgenden Tage reisten wir nach Cäsarea weiter. Wir gingen in das Haus des Evangelisten Philippus, eines der Sieben, und blieben bei ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Dieser hatte vier Töchter, Jungfrauen, die weissagten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Als wir einige Tage dort waren, kam ein Prophet namens Agabus von Judäa herab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Dieser fand sich bei uns ein, nahm den Gürtel des Paulus, band sich damit Füße und Hände und sagte. \"Also spricht der Heilige Geist: \'Den Mann, dem dieser Gürtel gehört, werden die Juden in Jerusalem auf solche Weise binden und den Heiden überliefern.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Als wir das vernahmen, baten wir und die Einheimischen ihn inständig, er möge doch nicht nach Jerusalem hinaufgehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Paulus erwiderte: \"Warum weint ihr und macht mir das Herz schwer? Ich bin bereit, mich nicht allein fesseln zu lassen, vielmehr auch in Jerusalem zu sterben für den Namen des Herrn Jesus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Da er sich nicht überreden ließ, gaben wir nach und sprachen: \"Der Wille des Herrn geschehe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Nach Ablauf dieser Tage machten wir uns reisefertig und zogen nach Jerusalem hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Auch einige Jünger aus Cäsarea gingen mit uns und brachten uns zu einem gewissen Mnason aus Cypern, einem Jünger aus der ersten Zeit, bei dem wir gastliche Aufnahme finden sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Als wir in Jerusalem angelangt waren, nahmen uns die Brüder mit Freuden auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Am folgenden Tage ging Paulus mit uns zu Jakobus; alle Presbyter fanden sich ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Er begrüßte sie und erzählte im einzelnen, was Gott durch seinen Dienst unter den Heiden gewirkt hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Als sie das vernommen hatten, priesen sie Gott. Dann aber sprachen sie zu ihm: \"Du siehst, lieber Bruder, wie viele Tausende bei den Juden gläubig geworden sind, und doch sind alle noch eifrige Anhänger des Gesetzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Nun haben sie von dir gehört, du lehrest alle Juden in der Heidenwelt, von Moses abzufallen, und weisest sie an, ihre Kinder nicht zu beschneiden und überhaupt nicht nach den Gesetzesbräuchen zu leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Was ist da nun zu machen? Sie werden jedenfalls in großer Zahl zusammenströmen. Sie werden ja erfahren, daß du angekommen bist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'So tu denn, was wir dir anraten. Bei uns sind jetzt vier Männer, die ein Gelübde auf sich haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Nimm sie zu dir, laß dich mit ihnen weihen und zahle für sie, damit sie sich das Haupt scheren lassen können. Dann werden alle einsehen, daß nichts an den Gerüchten ist, die über dich verbreitet worden sind, daß du vielmehr getreulich das Gesetz beachtest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Was aber die Gläubigen aus der Heidenwelt betrifft, so haben wir den schriftlichen Bescheid gegeben, sie sollen sich enthalten von Götzenopferfleisch, von Blut, Ersticktem und von Unzucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Paulus nahm darauf die Männer zu sich, ließ sich am folgenden Tage mit ihnen weihen und ging in den Tempel. Dort meldete er den Ablauf der Weihezeit an, damit für jeden aus ihnen das Opfer dargebracht werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Als die sieben Tage zu Ende gingen, erblickten ihn Juden aus Asien im Tempel. Sie brachten das ganze Volk in Aufruhr, legten Hand an ihn und schrien:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, '\"Ihr Männer von Israel! Zu Hilfe! Das ist der Mensch, der überall und bei allen gegen das Gesetz und gegen diesen Ort lehrt, der sogar Heiden in den Tempel eingeführt und dadurch diese heilige Stätte entweiht hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Sie hatten nämlich vorher den Trophimus aus Ephesus mit ihm zusammen in der Stadt gesehen und meinten nun, Paulus habe ihn auch mit in den Tempel genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Die ganze Stadt geriet in Aufruhr, und es entstand ein Volksauflauf. Sie ergriffen den Paulus und schleppten ihn aus dem Tempel, und sogleich wurden die Tore geschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Schon wollten sie ihn töten, da wurde dem Befehlshaber der Besatzung gemeldet, ganz Jerusalem sei in Aufruhr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Dieser zog eiligst Soldaten und Hauptleute heran und eilte zu ihnen hinab. Als sie aber den Befehlshaber und die Soldaten sahen, hörten sie auf, den Paulus zu mißhandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Der Befehlshaber trat hinzu, ließ ihn ergreifen und mit zwei Ketten fesseln. Er fragte, wer er sei und was er verbrochen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Es rief aber in der Volksmenge alles durcheinander. Weil er vor lauter Lärm nichts Sicheres erfahren konnte, ließ er ihn auf die Burg bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Als er an die Treppe kam, mußte er von den Soldaten getragen werden wegen des Ungestüms der Menge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Denn die Volksmenge drängte nach und schrie: \"Nieder mit ihm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Als Paulus eben in die Burg hinaufgeführt werden sollte, fragte Paulus den Befehlshaber: \"Darf ich etwas zu dir sagen?\" Jener entgegnete: \"Du verstehst Griechisch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'So bist du also nicht der Ägypter, der neulich die viertausend Meuchelmörder aufgewiegelt und in die Wüste hinausgeführt hat?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paulus erwiderte: \"Ich bin ein Jude aus Tarsus, ein Bürger dieser nicht unberühmten Stadt Ciliziens. Ich bitte dich also, gestatte mir, zum Volke zu reden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Er erlaubte es. Paulus trat auf die Stufen und winkte dem Volke mit der Hand. Da trat tiefe Stille ein, und er hielt auf hebräisch folgende Ansprache:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '\"Ihr Brüder und Väter! Vernehmt, wie ich mich vor euch verteidige.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Als sie hörten, daß er hebräisch zu ihnen sprach, wurden sie noch ruhiger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Er fuhr fort: \"Ich bin ein Jude, zu Tarsus in Cilizien geboren, hier in dieser Stadt erzogen zu den Füßen Gamaliels, streng nach dem väterlichen Gesetz unterrichtet. Ich war ein Eiferer für Gott, so wie ihr es alle heute seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Als solcher verfolgte ich diese Lehre bis auf den Tod und legte Männer und Frauen in Fesseln und brachte sie ins Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Das kann der Hohepriester und der ganze Rat der Ältesten mir bezeugen. Von ihnen erhielt ich Briefe an die Brüder in Damaskus und zog dorthin, um auch jene, die sich dort befanden, gefesselt nach Jerusalem zu führen, damit sie gestraft würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Als ich dahinzog und mich Damaskus näherte, umstrahlte mich plötzlich zur Mittagszeit vom Himmel her ein grelles Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Ich stürzte zu Boden und hörte eine Stimme, die mir zurief: \'Saul, Saul, warum verfolgst du mich?\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Ich erwiderte: \'Wer bist du, Herr?\' Er sprach zu mir: \'Ich bin Jesus von Nazareth, den du verfolgst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Meine Begleiter sahen zwar das Licht, doch hörten sie die Stimme nicht, die mit mir sprach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Ich fragte weiter: \'Was soll ich tun, o Herr?\' Da sprach der Herr zu mir: \'Steh auf und geh nach Damaskus, und dort wird man dir alles sagen, was du tun sollst.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Da ich nicht mehr sehen konnte wegen jenes Lichtglanzes, führten mich die Begleiter an der Hand, und also kam ich nach Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Und ein gesetzestreuer Mann mit Namen Ananias, der bei allen Juden, die dort wohnen, in gutem Rufe stand, kam zu mir,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'trat herzu und sprach zu mir: \'Bruder Saul, blicke auf!\' Im selben Augenblick sah ich ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Dann fuhr er fort: \'Der Gott unserer Väter hat dich dazu bestimmt, daß du seinen Willen erkennst und den Gerechten schauest und die Stimme seines Mundes vernehmest;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'du sollst ihm Zeuge sein vor allen Menschen von dem, was du gesehen und vernommen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Und nun, was zögerst du noch? Steh auf, laß dich taufen und dich von deinen Sünden waschen, nachdem du seinen Namen angerufen hast.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Als ich mich nach Jerusalem zurückbegeben hatte und im Tempel betete, geriet ich in Verzückung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Ich sah ihn, und er sprach zu mir: \'Verlasse eilends Jerusalem; sie werden dein Zeugnis über mich nicht annehmen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Ich sprach: \'O Herr, sie wissen doch, daß ich es war, der deine Gläubigen ins Gefängnis werfen und in den Synagogen geißeln ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Als das Blut deines Zeugen Stephanus vergossen ward, da war es wieder ich, der mit Wohlbehagen dabeistand und die Kleider seiner Mörder verwahrte.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Er aber sprach zu mir: \'Zieh fort; ich will dich zu den Heiden in die Ferne senden.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Bis hierher hatten sie ihm zugehört. Nun aber schrien sie laut: \"Weg von der Erde mit einem solchen Menschen. Er darf nicht mehr länger leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Als sie so schrien, ihre Kleider von sich warfen und Staub in die Höhe schleuderten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'befahl der Befehlshaber, den Paulus in die Burg hinaufzuführen. Zugleich gab er Befehl, ihn unter Anwendung der Folter zu verhören, um herauszubringen, warum sie so gegen ihn tobten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Schon wollte man ihn in die Riemen spannen, da fragte er den Hauptmann, der dabeistand: \"Ist es euch erlaubt, einen römischen Bürger, dazu noch ohne Richterspruch, zu geißeln?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Als der Hauptmann das hörte, ging er zum Befehlshaber und meldete ihm: \"Was hast du vor? Der Mensch dort ist römischer Bürger.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Der Befehlshaber trat heran und fragte ihn: \"Sage mir: Bist du römischer Bärger?\" Er antwortete: \"Ja.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Der Befehlshaber entgegnete: \"Ich mußte mir dieses Bürgerrecht um vieles Geld erwerben.\" Paulus entgegnete: \"Ich besitze es schon durch Geburt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Alsdann stand man davon ab, ihn zu foltern. Der Befehlshaber war sogar in Furcht, da er jetzt wußte, daß er römischer Bürger war und er ihn trotzdem hatte fesseln lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Er wollte aber doch sicher wissen, weswegen er von den Juden angeklagt sei. Darum ließ er ihm am folgenden Tage die Fesseln abnehmen und berief die Oberpriester und den ganzen Hohen Rat. Dann ließ er Paulus hineinführen und vor sie hinstellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Festen Blickes sah Paulus auf den Hohen Rat und sprach: \"Brüder! Mit dem besten Gewissen bin ich vor Gott gewandelt bis zum heutigen Tage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Da befahl der Hohepriester Ananias den neben ihm Stehenden, ihn auf den Mund zu schlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Paulus aber sprach zu ihm: \"Gott wird dich schlagen, du übertünchte Wand. Du sitzest da, um mich nach dem Gesetz zu richten, und du befiehlst, mich gegen das Gesetz zu schlagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Die Umstehenden warnten: \"Du beschimpfst den Hohenpriester Gottes?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paulus entgegnete: \"Brüder, ich wußte nicht, daß er der Hohepriester ist; es steht ja allerdings geschrieben: \'Du sollst einen Vorsteher deines Volkes nicht schmähen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Nun wußte aber Paulus, daß der eine Teil Sadduzäer, der andere Pharisäer waren. Und so rief er laut in die Versammlung hinein: \"Ich bin ein Pharisäer, Brüder, und stamme aus einer pharisäischen Familie. Der Hoffnung auf die Auferstehung von den Toten wegen stehe ich vor Gericht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Als er dies sagte, brach ein Streit aus zwischen den Pharisäern und Sadduzäern; die Versammlung spaltete sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Die Sadduzäer leugnen nämlich, daß es eine Auferstehung, Engel und Geister gebe, die Pharisäer dagegen nehmen all dies an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Es erhob sich ein großer Lärm; einige Schriftgelehrte von der Partei der Pharisäer erhoben sich, stritten heftig und erklärten: \"Wir finden nichts Böses an diesem Manne. Wie, wenn ein Geist oder ein Engel zu ihm gesprochen hätte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Bei der gewaltigen Aufregung, die entstand, befürchtete der Befehlshaber, Paulus möchte von ihnen zerrissen werden. Deshalb ließ er seine Soldaten herabkommen, den Paulus aus ihrer Mitte reißen und auf die Burg führen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'In der folgenden Nacht erschien ihm der Herr und sprach: \"Sei guten Muts! Wie du in Jerusalem Zeugnis für mich abgelegt hast, so mußt du auch in Rom Zeugnis ablegen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Als es Tag geworden war, rotteten sich die Juden zusammen und verschworen sich, weder zu essen noch zu trinken, bis sie den Paulus getötet hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Es waren mehr als vierzig, die diesen Schwur getan hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Sie gingen zu den Oberpriestern und Ältesten und sagten: \"Wir haben uns heilig verschworen, nichts zu genießen, bis wir Paulus umgebracht haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'So werdet jetzt zusammen mit dem Hohen Rat beim Befehlshaber vorstellig, er möge ihn zu euch herunterführen lassen, als wolltet ihr seine Sache noch genauer untersuchen. Wir aber halten uns bereit, ihn zu töten, bevor er noch bei euch angekommen ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Allein der Schwestersohn des Paulus erfuhr von diesem Anschlag. Er verschaffte sich Eintritt in die Burg und meldete es Paulus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Da ließ Paulus einen der Hauptleute kommen und bat ihn: \"Führe diesen jungen Mann zum Befehlshaber; er hat ihm etwas zu melden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Dieser brachte ihn zum Befehlshaber und sagte: \"Der Gefangene Paulus ließ mich rufen und bat mich, diesen jungen Mann zu dir zu führen, da er dir etwas zu melden habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Der Befehlshaber nahm ihn bei der Hand, ging mit ihm auf die Seite und fragte: \"Was hast du mir zu melden?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Er berichtete: \"Die Juden haben sich verabredet, dich zu bitten, du möchtest morgen den Paulus vor den Hohen Rat führen lassen, angeblich, um seine Angelegenheit genauer zu untersuchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Willfahre ihrer Bitte nicht. Denn über vierzig Männer aus ihnen lauern ihm auf; sie haben sich verschworen, weder zu essen noch zu trinken, bis sie ihn getötet hätten. Schon stehen sie bereit und erwarten nur noch deine Zusage.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Der Befehlshaber entließ den jungen Mann und schärfte ihm ein: \"Sage niemand etwas davon, daß du mir dies angezeigt hast.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Er rief zwei von seinen Hauptleuten zu sich und befahl ihnen: \"Haltet von der dritten Nachtwache an zweihundert Mann, die nach Cäsarea abmarschieren sollen, bereit, dazu noch siebzig Reiter und zweihundert Schützen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Auch Reittiere sollen sie bereitstellen, um den Paulus daraufzusetzen und ihn so wohlbehalten zum Statthalter Felix zu bringen. Er befürchtete nämlich, die Juden möchten ihn ergreifen und töten, und er selbst hätte nachher die üble Nachrede zu fürchten, als hätte er sich bestechen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Dann schrieb er einen Brief folgenden Inhaltes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '\"Claudius Lysias entbietet dem edlen Statthalter Felix seinen Gruß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Dieser Mann wurde von den Juden ergriffen und war nahe daran, von ihnen umgebracht zu werden. Da schritt ich mit meiner Mannschaft ein und befreite ihn, nachdem ich erfahren hatte, daß er ein römischen Bürger sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Da ich nun wissen wollte, weswegen sie gegen ihn Anklage erhoben hatten, ließ ich ihn vor ihren Hohen Rat bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Da fand ich, daß er wegen Streitfragen über ihr Gesetz angeklagt war, daß aber keine Anklage gegen ihn vorliege, die Tod oder Gefängnis verdiente.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Es wurde mir nun angezeigt, es solle von ihnen ein Anschlag gegen den Mann ausgeführt werden. Darum sende ich ihn zu dir. Zugleich habe ich die Ankläger angewiesen, bei dir ihre Anklage gegen ihn vorzubringen. Lebe wohl!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Die Soldaten brachten den Paulus ihrem Befehl gemäß in der Nacht nach Antipatris.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Tags darauf ließen sie die Reiter mit ihm weiterziehen und kehrten in die Burg zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Nach ihrer Ankunft in Cäsarea überreichten sie dem Statthalter den Brief und führten ihm auch den Paulus vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Jener las den Brief und fragte den Paulus, aus welcher Provinz er stamme. Nachdem er erfahren hatte, daß er aus Cilizien sei,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'sprach er: \"Ich will dich verhören, wenn auch deine Ankläger eingetroffen sind.\" Dann ließ er ihn im Schlosse des Herodes in Gewahrsam halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Fünf Tage später kam der Hohepriester Ananias mit etlichen Ältesten und einem Anwalt, namens Tertyllus, um beim Statthalter die Klage gegen Paulus vorzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Dieser wurde vorgeladen, und Tertyllus begann mit seiner Anklagerede: \"Durch dich erfreuen wir uns tiefen Friedens, deiner Fürsorge verdankt dieses Volk mannigfaltige Verbesserung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Das erkennen wir allzeit und überall mit großer Dankbarkeit an, edler FeIix.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Um aber dich nicht länger hinzuhalten, so bitte ich dich: Schenk uns gütigst für kurze Zeit Gehör.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Wir haben diesen Mann als eine Pest und einen Unruhestifter unter allen Juden auf der Welt erfunden sowie als einen der Hauptführer der Nazarenersekte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Ja, er hat versucht, selbst den Tempel zu entweihen. Deshalb haben wir ihn festgenommen und wollten ihn nach unserem Gesetz richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Da kam der Tribun Lysias dazwischen, entriß ihn mit großer Gewalt unseren Händen und erklärte, die Ankläger möchten zu dir kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Du selber wirst von ihm genauere Auskunft erhalten, wenn du ihn über alles verhörst, weswegen wir ihn anklagen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Diesen Angaben schlossen sich die Juden an und versicherten, daß es sich so verhalte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Auf einen Wink des Statthalters ergriff Paulus das Wort zur Entgegnung: \"Weil ich weiß, daß du seit langen Jahren schon Richter über dieses Volk bist, deshalb verteidige ich guten Mutes meine Sache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Wie du feststellen lassen kannst, sind es nicht mehr als zwölf Tage her, seitdem ich meine Wallfahrt nach Jerusalem gemacht habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Doch weder im Tempel noch in den Synagogen, noch in der Stadt hat man mich angetroffen, daß ich mit jemandem gestritten oder einen Volksaufruhr angestiftet hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Sie können dir auch keinerlei Beweise für das vorbringen, wessen sie mich jetzt anklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Doch das bekenne ich dir: Ich diene nach der Lehre, die sie eine Sekte nennen, dem Gott meiner Väter. Ich glaube alles, was im Gesetz und bei den Propheten geschrieben steht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'und hege zu Gott die Hoffnung, die diese hier auch teilen, daß es einstens eine Auferstehung der Gerechten und der Ungerechten geben wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Deshalb befleißige ich mich auch selbst, vor Gott und den Menschen durchweg mir ein reines Gewissen zu bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Nach Verlauf mehrerer Jahre bin ich hinaufgezogen, um meinem Volk Almosen auszuteilen und Opfer und Gelübde darzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Als ich im Tempel mich dabei einer Weihe unterzog, doch ohne Lärm und Auflauf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'da trafen mich einige Juden aus Asien an. Die hätten vor dir erscheinen und klagen müssen, wenn sie etwas gegen mich wüßten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Oder die hier mögen doch angeben, welches Vergehen sie an mir fanden, als ich vor dem Hohen Rate stand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Es müßte denn dies eine Wort nur sein, das ich, als ich vor ihnen stand, laut ausrief: \'Der Auferstehung von den Toten wegen stehe ich heute vor euch als Angeklagter.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Obwohl Felix eine genaue Kenntnis der in Frage stehenden Lehre hatte, vertagte er doch die Sache und sagte: \"Wenn der Befehlshaber Lysias herabkommt, werde ich euren Fall genauer untersuchen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Er gab dem Hauptmann die Weisung, ihn in milder Haft zu halten und keinen von den Seinigen zu hindern, ihm Dienste zu leisten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Einige Tage später kam Felix mit seiner Gemahlin Drusilla, einer Jüdin; er ließ den Paulus rufen und hörte ihn an über den Glauben an Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Da er aber von Gerechtigkeit, Enthaltsamkeit und dem künftigen Gerichte sprach, ward Felix betroffen und sagte: \"Für jetzt kannst du gehen; wenn ich einmal Zeit habe, werde ich dich wieder rufen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Zugleich hoffte er auch, von Paulus Geld zu erhalten. Deshalb ließ er ihn auch öfters kommen und unterhielt sich mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Volle zwei Jahre später erhielt Felix in Porzius Festus einen Nachfolger. Felix wollte sich die Juden zum Dank verpflichten und ließ darum Paulus in der Gefangenschaft zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festus übernahm die Verwaltung der Provinz und begab sich drei Tage später von Cäsarea nach Jerusalem hinauf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Die Oberpriester und die Angesehensten der Juden brachten ihm ihre Klagen gegen Paulus vor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Sie erbaten sich die gegen ihn gerichtete Vergünstigung, er möge ihn nach Jerusalem kommen lassen. Sie stellten ihm nämlich nach, um ihn unterwegs zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus entgegnete, Paulus werde in Cäsarea verwahrt bleiben; doch gedenke er selbst, bald wieder dorthin abzureisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '\"Dann können\", so fügte er hinzu, \"Bevollmächtigte aus eurer Mitte mit hinabziehen und eine Klage gegen ihn vorbringen, wenn der Mann ein Verbrechen begangen haben sollte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Er hielt sich bei ihnen nicht länger als acht bis zehn Tage auf und ging dann wieder nach Cäsarea hinab. Gleich am folgenden Tage hielt er eine Gerichtssitzung, ab und ließ den Paulus vorführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Kaum war dieser erschienen, da umringten ihn die Juden aus Jerusalem und brachten eine Menge schwerer Beschuldigungen gegen ihn vor, die sie aber nicht zu beweisen vermochten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paulus dagegen sagte zu seiner Verteidigung: \"Weder gegen das Gesetz der Juden noch gegen den Tempel, noch gegen den Kaiser habe ich mich irgendwie verfehlt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus aber, der sich den Juden gefällig erweisen wollte, fragte den Paulus: \"Willst du nach Jerusalem hinaufgehen und dich dort in dieser Sache von mir richten lassen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Paulus erwiderte: \"Ich stehe vor dem Richterstuhl des Kaisers; da habe ich mein Urteil zu empfangen. Den Juden habe ich nichts zuleid getan; das weißt auch du ganz gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Bin ich im Unrecht und habe ich ein Verbrechen begangen, das den Tod verdient, so weigere ich mich nicht zu sterben. Ist aber nichts an den Anklagen, die diese gegen mich erheben, so darf kein Mensch mich ihnen preisgeben. Ich lege Berufung an den Kaiser ein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Hierauf besprach sich Festus mit seinem Beirat und erklärte dann: \"Du hast Berufung an den Kaiser eingelegt; du sollst zum Kaiser gehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Einige Tage später fanden sich der König Agrippa und Berenike zur Begrüßung des Festus in Cäsarea ein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Da sie dort mehrere Tage verweilten, berichtete Festus dem König über Paulus. Er erzählte ihm: \"Hier ist noch ein Gefangener aus der Zeit des Felix.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Bei meinem Besuch in Jerusalem wurden die Oberpriester und Ältesten der Juden seinetwegen bei mir vorstellig und forderten, daß er verurteilt würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Ich erwiderte ihnen, es sei nicht Sitte bei den Römern, jemand preiszugeben, ehe der Angeklagte nicht seinen Anklägern Aug\' in Aug\' gegenüber gestanden und Gelegenheit gehabt habe, sich gegen die Anklage zu verteidigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Als sie dann hier eintrafen, da habe ich gleich am anderen Tag ohne Aufschub Gerichtssitzung gehalten und den Mann vorführen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Die Ankläger traten auf, sie brachten aber keine solchen Anschuldigungen über Verbrechen vor, wie ich sie vermutete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Nur einige Streitfragen über ihre Religion hatten sie gegen ihn sowie über einen gewissen verstorbenen Jesus, der aber, wie Paulus sagt, noch leben soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Da ich dieser Streitfrage gegenüber ratlos dastand, fragte ich ihn, ob er nicht nach Jerusalem gehen und dort in dieser Sache gerichtet werden Wolle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Doch da legte Paulus Berufung ein und verlangte, für die Entscheidung des Kaisers aufbewahrt zu werden. So befahl ich, ihn in Haft zu halten, bis ich ihn zum Kaiser schicken würde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Da sagte Agrippa zu Festus: \"Ich möchte den Mann gern einmal hören.\" \"Morgen schon\", erwiderte er, \"kannst du ihn hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Am anderen Tag erschienen Agrippa und Berenike mit großem Prunk. Sie betraten mit den Obersten und Vornehmen der Stadt den Gerichtssaal. Auf Befehl des Festus wurde Paulus vorgeführt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Und Festus sprach: \"König Agrippa und ihr alle, die ihr hier mit anwesend seid! Hier seht ihr den Mann, um dessentwillen mich die ganze Judenschaft in Jerusalem und hier mit der lauten Forderung bestürmt, ihn nicht länger mehr am Leben zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Ich habe aber festgestellt, daß er kein Verbrechen begangen hat, das den Tod verdient. Weil er aber Berufung an den Kaiser eingelegt hat, habe ich beschlossen, ihn dahin zu schicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Nun weiß ich aber meinem Herrn nichts Bestimmtes über ihn zu berichten. So habe ich ihn euch und vor allem dir, König Agrippa, vorführen lassen, damit ich nach dem Verhör weiß, was ich schreiben soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Denn es erscheint mir unvernünftig, einen Gefangenen wegzuschicken, ohne die Anklagepunkte gegen ihn anzugeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa sprach zu Paulus: \"Du darfst dich jetzt verteidigen.\" Da streckte Paulus seine Hand aus und begann seine Verteidigungsrede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '\"König Agrippa, ich schätze mich glücklich, daß ich mich wegen all der Anklagen, die die Juden gegen mich erheben, heute vor dir verteidigen darf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Du bist ja ein vorzüglicher Kenner aller jüdischen Gebräuche und Streitfragen. Ich bitte deshalb, mich in Geduld zu hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Alle Juden kennen meinen Lebenswandel unter meinem Volke von meiner Jugend an und in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Sie kennen mich von früher her und können, wenn sie wollen, es bezeugen, daß ich gemäß der strengsten Richtung unserer Religion gelebt habe, nämlich als Pharisäer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Und nun stehe ich vor Gericht wegen der Hoffnung auf die Verheißung, die von Gott an unsere Väter ergangen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Ihrer teilhaftig zu werden, hofft unser Zwölfstämmevolk mit Sehnsucht und dient unablässig Gott bei Tag und Nacht. Um dieser Hoffnung willen, König, bin ich von den Juden angeklagt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Warum wird es bei euch für unglaubhaft gehalten, daß Gott Tote auferweckt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Freilich, einstens glaubte auch ich, gegen den Namen Jesus von Nazareth viel Feindseliges verüben zu müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Das tat ich in Jerusalem; auch verschaffte ich mir Vollmacht von den Oberpriestern und ließ viele Heilige ins Gefängnis bringen und, wo es sich darum handelte, sie hinzurichten, gab ich meine Zustimmung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'In allen Synagogen suchte ich sie durch Strafen oftmals zur Lästerung zu zwingen; ja, in meiner maßlosen Wut gegen sie verfolgte ich sie auch bis in die auswärtigen Städte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'So zog ich mit Vollmacht und im Auftrag der Oberpriester auch nach Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Da sah ich, König, wie am Mittag auf dem Wege vom Himmel her ein Licht, noch glänzender als die Sonne, mich selbst umstrahlte und auch die, die bei mir waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Wir alle stürzten zu Boden. Und da vernahm ich eine Stimme, die in hebräischer Sprache mir zurief: \'Saul, Saul, warum verfolgst du mich? Es wird dir schwer sein, gegen den Stachel auszuschlagen.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Ich aber fragte: \'Herr, wer bist du?\' Er gab zur Antwort: \'Ich bin Jesus, den du verfolgst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Doch nun steh auf und stelle dich auf deine Füße! Denn dazu bin ich dir erschienen, um dich zum Diener und zum Zeugen dessen zu bestellen, was du gesehen hast und was ich dir noch offenbaren werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Ich will dich aus dem Volke retten und auch aus den Heiden, zu denen ich dich sende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Du sollst ihnen die Augen öffnen, damit sie sich aus der Finsternis zum Licht und aus der Macht des Satans zu Gott bekehren, damit sie Verzeihung ihrer Sünden und Anteil mit den Heiligen erhalten dadurch, daß sie an mich glauben.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Sonach konnte ich, König Agrippa, der himmlischen Erscheinung nicht ungehorsam sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Ich predigte zuerst denen in Damaskus und in Jerusalem, dann in der ganzen Landschaft Judäa und endlich bei den Heiden, sie sollten sich bekehren und sich Gott zuwenden und Werke tun entsprechend der Bekehrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Deshalb ergriffen mich die Juden im Tempel und suchten mich zu töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Doch da mir bis auf diesen Tag Gott seine Hilfe lieh, so lege ich aufrecht vor klein und groß mein Zeugnis ab, daß ich nichts anderes sage als was schon die Propheten und Moses geweissagt haben:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Der Messias werde leiden, als Erster von den Toten auferstehen und dem Volke wie den Heiden das Licht verkünden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Da Paulus dies zu seiner Verteidigung sagte, rief Festus laut aus: \"Du bist von Sinnen, Paulus! Das viele Studieren bringt dich ganz um den Verstand.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Paulus erwiderte: \"Edler Festus, ich bin nicht von Sinnen; nein, wahr und wohlbedacht sind meine Worte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Der König kennt sich in diesen Dingen sehr wohl aus, weshalb ich mit allem Freimut vor ihm rede; denn ich kann nicht glauben, es sei ihm etwas davon unbekannt geblieben, die Sache trug sich ja nicht in einem abgelegenen Winkel zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'König Agrippa, glaubst du den Propheten? Ich weiß, du glaubst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa erwiderte dem Paulus: \"Fast überredest du mich, Christ zu werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paulus entgegnete: \"Wollte Gott, daß über kurz oder lang nicht nur du allein, nein alle, die mich heute hören, so würden, wie ich bin, nur abgesehen von diesen Ketten da.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Da erhoben sich der König, der Statthalter, Berenike und die übrigen Anwesenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Im Weggehen sprachen sie zueinander: \"Dieser Mensch hat nichts getan, was Tod oder Gefängnis verdiente.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Und Agrippa sagte zu Festus: \"Man könnte den Mann freilassen, hätte er nicht Berufung an den Kaiser eingelegt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Als unsere Abfahrt nach Italien festgesetzt war, wurde Paulus mit noch einigen anderen Gefangenen einem Hauptmann der kaiserlichen Kohorte, namens Julius, übergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Wir bestiegen ein adramyttenisches Schiff, das die asiatischen Küstenplätze anlaufen sollte, und fuhren ab. Mit uns fuhr noch Aristarch aus Thessalonich in Mazedonien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Am folgenden Tage landeten wir in Sidon. Julius behandelte den Paulus rücksichtsvoll und gestattete ihm, die Freunde aufzusuchen und sich mit dem Nötigen versehen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Von da segelten wir ab und fuhren an Cypern hin, weil wir widrigen Wind hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'So durchfuhren wir das Meer bei Cilizien und Pamphylien und kamen nach Myra in Lykien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Dort fand der Hauptmann ein alexandrinisches Schiff, das sich auf der Fahrt nach Italien befand, und brachte uns hinüber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Nach vielen Tagen langsamer Fahrt kamen wir mit Mühe gegen Knidos hin, und da der Wind uns dort nicht anlegen ließ, fuhren wir an Kreta hin, auf der Höhe von Salmone.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Nach mühevoller Fahrt längs der Küste kamen wir an einen Ort Kaloi Limenes in der Nähe der Stadt Lasäa.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Unterdessen war geraume Zeit verstrichen, und die Schiffahrt wurde bereits gefährlich; der Fasttag war ja schon vorüber. Darum warnte sie Paulus:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '\"Ihr Männer, ich sehe, daß die Schiffahrt mit großem Ungemach und großem Schaden nicht bloß für die Ladung und das Schiff, sondern auch für unser Leben vor sich gehen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Der Hauptmann gab aber auf die Worte des Steuermanns und des Schiffsherrn mehr als auf die des Paulus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Da der Hafen zum Überwintern nicht günstig war, beschloß die Mehrzahl, von da ins offene Meer zu fahren, um womöglich Phönix zu erreichen und dort zu überwintern. Dieser Hafen Kretas ist gegen Südwest und Nordwest geschützt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Da ein schwacher Südwind aufkam, glaubten sie, mit ihrem Vorhaben sicher zum Ziel zu kommen; sie lichteten die Anker und fuhren dicht an der Küste Kretas hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Doch nach kurzer Zeit brach von der Insel her ein Sturmwind los, ein sogenannter Ostnordost.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Das Schiff wurde von ihm erfaßt und konnte dem Sturm nicht standhalten; so gaben wir es preis und ließen uns treiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Wir kamen an einer kleinen Insel, Klauda, vorbei. Dort gelang es uns mit vieler Mühe, des Rettungsbootes habhaft zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Man zog es herauf und wandte Schutzmittel an, indem man das Schiff untergürtete. Aus Furcht, in die Syrte zu geraten, zog man die Segel ein und ließ sich so dahintreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Der Sturm setzte uns furchtbar zu. Deshalb warf man am folgenden Tag einen Teil der Ladung über Bord;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'am dritten Tage schleuderten die Leute eigenhändig das Schiffsgerät hinaus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Mehrere Tage sah man weder Sonne noch Sterne; der Sturm tobte ungeschwächt weiter; alle Hoffnung auf Rettung war geschwunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Schon lange hatten die Leute nichts mehr zu sich genommen, da trat Paulus mitten unter sie und sagte: \"Ihr Männer, man hätte mir folgen und nicht von Kreta in das offene Meer hinausfahren sollen, dann wären uns dieses Ungemach und dieser Schaden erspart geblieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Für jetzt jedoch ermahne ich euch, guten Mutes zu sein. Kein Menschenleben aus uns wird verlorengehen, sondern nur das Schiff.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Denn heute nacht erschien mir ein Engel des Gottes, dem ich zu eigen bin und dem ich diene,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'und sprach: \'Fürchte dich nicht, Paulus! Du mußt vor den Kaiser treten. Siehe, Gott hat dir alle geschenkt, die mit dir fahren.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Darum seid guten Mutes, ihr Männer! Denn ich vertraue auf Gott, daß es so kommen wird, wie es mir verheißen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Wir müssen auf irgendeine Insel verschlagen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Als wir schon die vierzehnte Nacht im Adriatischen Meer umhertrieben, vermuteten um Mitternacht die Schiffsleute Land in der Nähe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Sie warfen das Senkblei und warfen eine Tiefe von zwanzig Faden. Als sie nach kurzer Zeit wiederum das Senkblei warfen, fanden sie nur noch fünfzehn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Aus Furcht, wir möchten auf Klippen auflaufen, warfen sie vom Hinterteil des Schiffes vier Anker aus und erwarteten sehnlichst den Anbruch des Tages.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Da machte die Besatzung den Versuch, vom Schiffe zu fliehen. Sie ließen das Rettungsboot ins Meer nieder unter dem Vorwand, sie wollten auch vom Vorderteil aus Anker auswerfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paulus aber sagte dem Hauptmann und den Soldaten: \"Wenn diese nicht auf dem Schiffe bleiben, könnt ihr nicht gerettet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Da hieben die Soldaten die Taue des Rettungsbootes ab und ließen es ins Meer fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Sobald der Morgen dämmerte, ermahnte Paulus alle, Nahrung zu sich zu nehmen. Er sprach: \"Heute werden es vierzehn Tage, daß ihr ohne Nahrung in einem fort nur wartet, ohne etwas zu genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Darum rate ich euch, jetzt Nahrung zu euch zu nehmen; das dient zu eurer Rettung. Keinem von euch wird auch nur ein Haar von seinem Haupte verlorengehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Nach diesen Worten nahm er Brot, dankte Gott vor aller Augen, brach es und fing an zu essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Da bekamen alle Mut und nahmen ebenfalls Nahrung zu sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Im ganzen waren wir zweihundertsechsundsiebzig Personen an Bord.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Als sie sich gesättigt hatten, erleichterten sie das Schiff, indem sie die Getreideladung ins Meer warfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Endlich ward es heller Tag, doch sie erkannten das Land nicht. Sie bemerkten aber eine Bucht mit einem flachen Strande. Dorthin gedachten sie, wenn möglich, das Schiff auflaufen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Sie machten also die Anker los und ließen sie ins Meer fallen; zugleich lösten sie die Riemen von den Rudern, stellten das Vordersegel nach dem Wind und hielten auf den Strand zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Sie gerieten auf eine Landzunge, wo sie das Schiff auflaufen ließen. Das Vorderteil bohrte sich tief ein und saß fest; das Hinterteil jedoch wurde durch den Anprall der Wogen zerschellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Die Soldaten waren nun willens, die Gefangenen zu töten, damit keiner durch Schwimmen entkomme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Allein der Hauptmann, der Paulus retten wollte, hinderte sie an ihrem Vorhaben. Er befahl, wer Schwimmen könne, solle zuerst hinausspringen und ans Land gehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'die übrigen teils auf Brettern, teils auf sonstigen Schiffstrümmern. So gelang es, alle unversehrt ans Land zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Als wir gerettet waren, erfuhren wir, daß die Insel Malta hieß..');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Die Eingeborenen erwiesen uns eine ungewöhnliche Menschenfreundlichkeit. Sie zündeten ein Feuer an und holten uns alle heran, denn Regen setzte ein, und es war kalt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Paulus raufte einen Haufen Reisig zusammen und warf ihn ins Feuer. Da schnellte infolge der Hitze eine Natter heraus und heftete sich an seine Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Als die Eingeborenen das Tier an seiner Hand hängen sahen, sprachen sie zueinander: \"Gewiß ist dieser Mensch ein Mörder. Wenn er auch dem Meer entronnen ist, die Rache läßt ihn dennoch nicht am Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Er aber schüttelte das Tier ins Feuer, ohne daß er Schaden erlitten hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Die Leute warteten nun darauf, daß er anschwellen oder plötzlich tot zusammensinken werde. Lange warteten sie. Als sie sahen, daß ihm nichts Schlimmes widerfuhr, änderten sie ihre Ansicht und sagten, er sei ein Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'In jener Gegend besaß der oberste Beamte der Insel, namens Publius, ein Landgut. Dieser nahm uns auf und gewährte uns drei Tage lang liebevolle Gastfreundschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Der Vater des Publius lag gerade an fiebriger Ruhr krank danieder. Paulus ging zu ihm hin, betete, legte ihm die Hand auf und machte ihn gesund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Daraufhin kamen auch die anderen Kranken der Insel herbei und wurden geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Dafür überhäufte man uns mit Ehrenbezeigungen und versah uns bei unserer Abfahrt mit allem, was wir nötig hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Nach drei Monaten fuhren wir auf einem alexandrinischen Schiff ab. Dieses hatte auf der Insel überwintert und führte das Zeichen der Dioskuren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Wir liefen Syrakus an, wo wir drei Tage blieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Von dort fuhren wir der Küste entlang und kamen nach Rhegium. Da tags darauf ein Südwind einsetzte, kamen wir in zwei Tagen nach Puteoli.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Dort trafen wir Brüder, die uns baten, sieben Tage bei ihnen zu bleiben. Und dann kamen wir nach Rom.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Die Brüder hatten von uns gehört und kamen uns von dort entgegen bis Forum Appii und Tres Tabernae. Bei ihrem Anblick dankte Paulus Gott und schöpfte neuen Mut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Nachdem wir in Rom angekommen waren übergab der Hauptmann die Gefangenen dem Befehlshaber des Lagers, wurde es dem Paulus gestattet, unter Aufsicht eines Soldaten eine eigene Wohnung zu beziehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Nach drei Tagen rief er die Angesehensten der Juden zu sich. Als sie versammelt waren, sprach er zu ihnen: \"Brüder, ohne mich gegen das Volk oder die Vätersitte je verfehlt zu haben, bin ich von Jerusalem aus als Gefangener den Römern überliefert worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Sie wollten mich nach einer Untersuchung in Freiheit setzen, weil kein todeswürdiges Verbrechen bei mir vorlag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Jedoch die Juden legten Einspruch ein, und so war ich genötigt, Berufung an den Kaiser einzulegen, jedoch nicht, als wollte ich mein Volk selbst verklagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Aus diesem Grunde also habe ich euch zu mir gebeten, um euch zu sehen und zu sprechen; denn um der Hoffnung Israels willen bin ich mit dieser Kette umschlossen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Sie erwiderten ihm-. \"Wir haben weder schriftliche Nachricht aus Judäa über dich erhalten, noch kam einer von den Brüdern und berichtete oder erzählte uns etwas Nachteiliges über dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Doch möchten wir deine Ansicht näher kennenlernen. Denn von dieser Sekte ist uns nur bekannt, daß sie überall Widerspruch findet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Sie bestimmten ihm einen Tag und fanden sich an ihm in größerer Anzahl in seiner Wohnung ein. Er erklärte und bezeugte ihnen das Reich Gottes und suchte sie im Anschluß an das Gesetz des Moses und an die Propheten vom frühen Morgen bis zum Abend für die Sache Jesu zu gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Ein Teil glaubte seinen Worten, der andere blieb ungläubig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'In Uneinigkeit miteinander gingen sie weg. Paulus sagte nur noch das eine Wort: \"Treffend hat der Heilige Geist zu euren Vätern durch Isaias, den Propheten, gesagt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '\'Tritt hin vor dieses Volk und sprich \"Ihr werdet hören und nicht verstehen, ihr werdet sehen und nicht einsehen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'verstockt ist das Herz dieses Volkes; seine Ohren sind schwerhörig, und seine Augen sind verschlossen, damit es mit den Augen ja nicht sehe und mit den Ohren nicht höre, in seinem Herzen nicht verständig werde und sich bekehre und Heilung bei mir finde.\"\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'So sei es denn euch kund, daß das Heil Gottes den Heiden gebracht wird, und diese werden darauf hören.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Nachdem er dies gesagt hatte, verließen ihn die Juden, wobei sie viele Streitfragen unter sich hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Er blieb zwei volle Jahre in seiner Mietwohnung und nahm alle auf, die zu ihm kamen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Er verkündete das Reich Gottes und lehrte vom Herrn Jesus Christus ganz offen und ungehindert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, Knecht Christi Jesu, berufen zum Apostel und auserkoren für das Evangelium Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'das er durch seine Propheten in den heiligen Schriften verheißen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'für das Evangelium von seinem Sohne Jesus Christus, unserem Herrn. Dieser kommt dem Fleische nach aus dem Stamme David,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'war aber als Sohn Gottes kundgetan mit Macht seinem heiligen Geiste nach seit der Auferstehung von den Toten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Von ihm empfingen wir die Gnade des Apostelamtes, um für die Ehre seines Namens bei allen Heidenvölkern für den Gehorsam im Glauben zu wirken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Zu ihnen gehört auch ihr, die ihr von Jesus Christus berufen seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Euch allen in Rom, Lieblingen Gottes, berufenen Heiligen, werde Gnade und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Vor allem danke ich meinem Gott durch Jesus Christus euer aller wegen dafür, daß euer Glaube in der ganzen Welt gerühmt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Gott, dem ich mit ganzer Seele diene, da ich das Evangelium von seinem Sohne verkünde, ist mir Zeuge,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'daß ich, sooft ich bete und flehe, unablässig euer dabei gedenke, ob ich nicht endlich einmal doch das Glück hätte, so Gott will, zu euch zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Ich sehne mich so sehr danach, euch zu sehen, damit ich euch irgendeine Geistesgabe gebe, um euch dadurch zu stärken;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'das heißt, um gegenseitig uns aufzumuntern, wenn ich bei euch bin, durch unser beider Glauben, den euren und den meinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Ich will euch, meine Brüder, nicht verhehlen, daß ich mir oft schon vorgenommen hatte, zu euch zu kommen; doch bisher bin ich immer wieder abgehalten worden. Ich möchte eben auch bei euch manche Früchte ernten wie bei den anderen Völkern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Griechen und Barbaren, Menschen mit und ohne Bildung, fühle ich mich verpflichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Soweit es auf mich ankommt, bin ich gern bereit, auch euch in Rom die frohe Botschaft zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'In keiner Weise nämlich schäme ich mich des Evangeliums; denn es ist eine Gotteskraft zum Heile für jeden, der glaubt, vor allem für die Juden, jedoch auch für die Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Gottes Gerechtigkeit, die aus dem Glauben stammt, wird ihm enthüllt zum Glauben hin; wie geschrieben steht: \"Der aus dem Glauben Gerechte wird leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Wird doch enthüllt, wie Gott vom Himmel her zürnte über alle frevelhaften und ungerechten Menschen, die die Wahrheit niederhalten mit ihrer Ungerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Denn was an Gott erkennbar ist, ist ihnen wohlbekannt. Gott selber hat es ihnen ja geoffenbart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Denn was an ihm unsichtbar ist, wird in den Geschöpfen durch Nachdenken seit Erschaffung der Welt erkannt: seine ewige Allmacht und Göttlichkeit. Darum sind sie unentschuldbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Denn sie erkannten zwar Gott, verherrlichten ihn aber nicht als Gott und dankten ihm auch nicht. Vielmehr gerieten sie mit ihrem Denken auf Torheiten, und ihr unverständiges Herz ward verfinstert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Sie gaben sich als Weise aus und waren doch Toren geworden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'sie vertauschten die Herrlichkeit des unvergänglichen Gottes mit einem Abbild der Gestalt eines vergänglichen Menschen, von Vögeln, von vierfüßigen und kriechenden Tieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Darum gab Gott sie der Lasterhaftigkeit preis, entsprechend den bösen Lüsten ihres Herzens, so daß sie ihre Leiber gegenseitig schändeten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Sie, die den wahren Gott mit der Lüge tauschten und den Geschöpfen Ehre und Anbetung erwiesen anstatt dem Schöpfer, der hochgelobt ist in Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Gott gab sie deshalb auch schmachvollen Leidenschaften preis: Ihre Weiber tauschten den natürlichen Verkehr mit dem widernatürlichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Und ähnlich gaben auch die Männer den natürlichen Verkehr mit dem Weibe auf und entbrannten gegeneinander in ihrer wilden Gier, und Männer taten so die größten Schändlichkeiten aneinander. Dafür empfingen sie an ihrem eigenen Leib auch die Strafe, wie es sich für ihre Verirrungen geziemte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Wie sie es ablehnten, den Gedanken an Gott mit sich zu tragen, so überließ Gott sie auch ihrer schändlichen Gesinnung, so daß sie taten, was sich nicht ziemte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'erfüllt von aller Ungerechtigkeit, Bösartigkeit Unzucht, Habsucht und Verkommenheit, voll Neid und Mordlust, Streitsucht, Bosheit, Tücke; sie wurden Ohrenbläser,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Verleumder, Gotteshasser, Spötter, eingebildet und prahlerisch, erfinderisch im Bösen, gegen Eltern unfolgsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'unverständig, treulos, ohne Mitleid und Erbarmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Sie, die doch die Rechtsordnung Gottes kennen, daß, wer solches treibt, des Todes schuldig ist, tun dies nicht nur selber, sie spenden auch noch denen Beifall, die solches treiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Darum bist du unentschuldbar, Mensch, und magst du sein, wer du willst, im Falle du richten wolltest. Dadurch, daß du den Nächsten richtest, verurteilst du dich ja selbst; denn du, der du den Richter spielst, treibst ja genau dasselbe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Wir wissen aber, daß das göttliche Gericht ohne Ansehen der Person ergeht über die, die solches treiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Meinst du denn wirklich, Mensch, der du die richtest, die solches treiben, und trotzdem dasselbe tust, gerade du würdest dem göttlichen Gericht entrinnen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Oder denkst du vermessen von seiner überreichen Güte, seiner Geduld und Nachsicht? Weißt du wirklich nicht, daß dich die Güte Gottes nur zur Bekehrung führen will?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mit deinem Starrsinn aber und deinem unbußfertigen Herzen häufst du dir Zorn auf für den Tag des Zornes und der Offenbarung des Gerichtes von seiten des gerechten Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, '\"der einem jeden vergelten wird nach seinen Werken\":');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Ein ewiges Leben denen, die durch Beharrlichkeit im Guten Verherrlichung, Ehre und Unvergänglichkeit erstreben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'dagegen Zorn und Grimm für die, die widerspenstig sind, die sich der Wahrheit nicht beugen, der Ungerechtigkeit dagegen folgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Trübsal und Angst über die Seele eines jeden Menschen, die böse Werke tut; vor allem über den Juden, jedoch auch über den Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Verherrlichung, Ehre und Friede aber einem jeden, der gute Werke tut, vor allem dem Juden, jedoch auch dem Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Denn es gibt kein Ansehen der Person bei Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Alle, die ohne Gesetz gesündigt haben, werden verlorengehen ohne Gesetz; die aber gesündigt haben unter dem Gesetze, werden durch das Gesetz gerichtet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Denn nicht die Hörer des Gesetzes sind gerecht vor Gott; nur wer das Gesetz auch gehalten hat, wird für gerecht erklärt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Wenn so zum Beispiel Heiden, die das Gesetz nicht haben, aus Antrieb der Natur die Forderungen des Gesetzes erfüllen, so sind sie, ohne das Gesetz zu haben, sich selbst Gesetz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Denn sie beweisen, daß der Kern des Gesetzes in ihr Herz eingezeichnet ist. Zeuge dafür ist ihnen ihr Gewissen: die Gedanken, mit denen sie sich gegenseitig anklagen oder auch verteidigen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'am Tage, da Gott das heimliche Tun der Menschen richten wird meinem Evangelium entsprechend durch Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Wenn du dich einen Juden heißen lässest, der sich auf das Gesetz versteift, und dich rühmst in Gott -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'du kennst ja seinen Willen, und als treuer Schüler des Gesetzes weißt du ganz genau, worauf es ankommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Du traust dir zu, Führer zu sein für Blinde, Licht für die, die im Finstern sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'ein Erzieher der Unverständigen, Lehrer der Unmündigen, der im Gesetz die Verkörperung des Wissens und der Wahrheit hat. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Du zwar belehrst andere, dich selber aber lehrst du nicht? Du predigst, man dürfe nicht stehlen, und stiehlst doch selber?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Du sagst, man dürfe nicht die Ehe brechen, und brichst doch selbst die Ehe? Du verabscheust wohl die Götzenbilder, verübst selber aber Tempelraub?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Du rühmst dich des Gesetzes, entehrst aber Gott durch deine Übertretung des Gesetzes?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Denn \"durch eure Schuld wird der Name Gottes gelästert von den Heiden\", heißt es in der Schrift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Nur dann ist die Beschneidung nämlich etwas wert, wenn du das Gesetz beachtest. Doch übertrittst du immer wieder das Gesetz, dann ist deine Beschneidung zur Vorhaut geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Wenn dagegen die Vorhaut die Rechtsforderungen des Gesetzes hält, wird ihr dann die Vorhaut nicht als Beschneidung angerechnet werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Ja, die von Natur aus unbeschnitten sind, die aber das Gesetz erfüllen, werden dich verdammen, der du trotz Gesetzesvorschriften und Beschneidung dich gegen das Gesetz verfehlst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Denn ein wahrer Jude ist nicht der, der es nur nach außenhin ist, und nicht das ist die wahre Beschneidung, die äußerlich am Fleische vorhanden ist;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'nein, der nur ist ein Jude, der es im Innern ist, und eine richtige Beschneidung ist nur die des Herzens, dem Geiste nach, und nicht nur nach den Gesetzesvorschriften. Ein solcher freilich findet bei Menschen keine Anerkennung, sondern nur bei Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Doch welchen Vorzug hat dann der Jude? Oder was nützt die Beschneidung? In jeder Hinsicht viel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Vor allem wurden ihnen die Worte Gottes anvertraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Doch wie? Wenn einige nicht mehr glauben, hebt ihr Unglaube dann nicht die Treue Gottes auf?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'In keiner Weise. Gott soll stets wahrhaftig erwiesen werden, jeder Mensch aber als Lügner, wie geschrieben steht: \"Du sollst in deinen Worten gerecht erfunden werden und recht behalten, wenn man dich richtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Wenn aber unsere Ungerechtigkeit die Gerechtigkeit Gottes ins Licht stellt, was folgt daraus? Gott ist doch nicht - rein menschlich angesehen - ungerecht, wenn er in seinem Zorne straft?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'In keiner Weise. Wie könnte dann sonst Gott die Welt noch richten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Doch wenn Gott im Hinblick darauf, daß ich so unwahrhaftig bin, nur um so herrlicher als der Wahrhaftige erscheint und dadurch verherrlicht wird, warum soll ich dennoch als Sünder gerichtet werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Und sollen wir - einige behaupten verleumderisch, daß wir dies lehren - etwa Böses tun, damit Gutes daraus entspringe? Die Verdammung solcher ist berechtigt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Was folgt also aus alledem? Sind etwa wir besser daran? Nicht ganz. Wir haben eben dargetan, daß alle, Juden und Heiden, der Sünde verfallen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'So steht es ja geschrieben: \"Kein einziger ist gerecht, auch nicht einer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'verständig keiner, und keiner fragt etwas nach Gott;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'sie alle sind auf falscher Bahn, verdorben alle miteinander, und keiner ist, der Gutes täte, auch nicht einer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Ein offenes Grab ist ihre Kehle. Trug üben sie mit ihren Zungen, und Natterngift findet sich auf ihren Lippen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'und ihr Mund ist voll von Fluch und Bitterkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'schnell sind sie da, wo Blut vergossen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Verderben und Unglück ist auf ihren Wegen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'sie kennen nicht den Weg des Friedens,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'und Gottesfurcht ist nicht vor ihren Augen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Wir wissen aber, daß alles, was das Gesetz befiehlt, für jene gilt, die unter dem Gesetze stehen, damit jeder Mund verstumme und die ganze Welt vor Gott schuldig werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Denn durch Gesetzeswerke wird kein Mensch vor ihm gerecht; man lernt ja durch das Gesetz erst die Sünde kennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Jetzt aber ist unabhängig vom Gesetze Gottes Gerechtigkeit geoffenbart; - Gesetz sowie Propheten haben auf sie hingewiesen -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Gottes Gerechtigkeit durch den Glauben an Jesus Christus für alle sowie über alle, die glauben. Da gibt es keinen Unterschied;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'alle haben ja gesündigt und sind der Herrlichkeit Gottes verlustig gegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Gerechtfertigt doch werden sie ohne eigenes Zutun durch seine Gnade dank des Loskaufs in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Ihn hat Gott als Versöhnungsopfer in seinem eigenen Blute durch den Glauben dargestellt, um seine Gerechtigkeit zu zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'In seiner Langmut hatte Gott die Sünden, die früher geschehen waren, ungestraft gelassen; er wollte nämlich seine Gerechtigkeit jetzt erst erweisen, auf daß er selber gerecht sei, und auch den gerecht machen, der an Jesus Christus glaubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Wo bleibt nun das Rühmen? Es ist ganz ausgeschlossen. Durch welches Gesetz? Durch das Gesetz der Werke? Nein, sondern durch das Gesetz des Glaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Denn wir nehmen an, daß der Mensch durch den Glauben gerechtfertigt wird, ohne die Werke des Gesetzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Oder ist Gott etwa nur ein Gott der Juden und nicht auch der der Heiden? Doch wohl auch der der Heiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Es ist ja doch derselbe Gott, der rechtfertigt: auf Grund ihres Glaubens die Beschnittenen, die Vorhaut vermittels ihres Glaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'So heben wir also das Gesetz des Glaubens wegen auf? Im Gegenteil! Wir bringen das Gesetz erst recht zur Geltung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Wie steht es nun nach unserer Behauptung bei unserem Stammvater dem Leibe nach, bei Abraham?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Ward Abraham aus Werken gerechtfertigt, so mag er sich rühmen; doch nicht vor Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Was steht denn in der Schrift? \"Abraham glaubte Gott, und es ward ihm angerechnet als Gerechtigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Dem, der Werke tut, wird der Lohn nicht aus Gnade, vielmehr nach Verdienst berechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Wer aber keine Werke tut und doch an den glaubt, der den Gottlosen zum Gerechten macht, dem wird sein Glaube zur Gerechtigkeit angerechnet nach dem Ratschluß der Gnade Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'So spricht David auch sein \"Selig\" über den Menschen, dem Gott Gerechtigkeit anrechnet ohne Werke:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '\"Selig, deren Missetaten verziehen und deren Sünden bedeckt sind;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'selig der Mann, dem der Herr die Sünden nicht anrechnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Gilt nun dieses \"Selig\" nur von den Beschnittenen oder auch von der Vorhaut? Wir sagen: \"Der Glaube ward dem Abraham als Gerechtigkeit angerechnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Wann wurde er ihm angerechnet? Nach der Beschneidung oder vor der Beschneidung? Nicht nach der Beschneidung, vielmehr in der Vorhaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Das Zeichen der Beschneidung erhielt er ja als Besiegelung der Gerechtigkeit, die er durch den Glauben in der Vorhaut hatte. Er sollte der Vater aller sein, die in der Vorhaut glauben, damit auch ihnen die Gerechtigkeit angerechnet würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Er sollte aber auch der Vater der Beschnittenen sein, soweit sie nicht allein Beschnittene sind, vielmehr getreulich unserem Vater Abraham in seinem Glauben folgen, den er schon in der Vorhaut hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Dem Abraham oder seinen Nachkommen ward die Verheißung, er würde einst die Welt zum Erbe erhalten, nicht durch das Gesetz, sondern durch die Gerechtigkeit des Glaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Denn wenn nur die, die das Gesetz besitzen, Erben wären, dann wäre der Glaube eitel und die Verheißung nichtig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Denn das Gesetz bewirkt Zorn; wo es aber kein Gesetz gibt, da gibt es auch keine Übertretung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Und deshalb geschieht es durch den Glauben, damit die Gerechtigkeit aus Gnade komme und die Verheißung allen Nachkommen gesichert sei; nicht nur denen, die aus dem Gesetze kommen, sondern auch denen, die dem Glauben Abrahams entstammen, der unser aller Vater ist');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'gemäß dem Schriftwort: \"Zum Vater vieler Völker habe ich dich gemacht.\" Er ist dies vor Gott, an den er glaubte, der die Toten auferweckt und das, was nicht ist, ins Dasein ruft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Er hat gegen alle Hoffnung vertrauensvoll geglaubt, daß er Vater vieler Völker werde, wie zu ihm gesprochen ward: \"So wird dein Stamm sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Auch ward er nicht im Glauben wankend, als er seinen schon erstorbenen Leib betrachtete - er war ja beinahe hundert Jahre alt - und den gleichfalls erstorbenen Schoß der Sara.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Er hegte keinen ungläubigen Zweifel an der Verheißung Gottes, sondern wurde stark im Glauben und gab Gott die Ehre,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'durchaus überzeugt, daß er, der die Verheißung gab, sie auch erfüllen könne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Darum \"ward es ihm zur Gerechtigkeit angerechnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Es steht nun aber nicht nur seinetwegen da: \"Es ward ihm angerechnet\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'sondern auch unseretwegen, denen es erst angerechnet werden soll, uns, die wir an den glauben, der unseren Herrn Jesus von den Toten auferweckt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'der um unserer Sünden willen hingeopfert ward und auferweckt wurde zu unserer Rechtfertigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Gerechtfertigt aus dem Glauben leben wir also mit Gott im Frieden durch unseren Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Durch ihn haben wir kraft des Glaubens den Zutritt zu der großen Gnade erlangt, in der wir uns befinden, und rühmen uns der Hoffnung, die göttliche Verklärung zu erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Doch nicht darob allein wollen wir uns rühmen, nein, auch der Trübsal. Wir wissen: Die Trübsal macht starkmütig;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'der Starkmut schafft Bewährung, Bewährung führt zur Hoffnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Die Hoffnung aber beschämt nicht; denn die Liebe Gottes ist in unsere Herzen ausgegossen durch den Heiligen Geist, der uns verliehen wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ist doch Christus, weil wir kraftlos waren, für uns, die Gottlosen, zur rechten Zeit gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Kaum stirbt jemand für einen Gerechten; für einen Freund bringt man es vielleicht noch über sich zu sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Gott aber zeigt uns seine Liebe dadurch, daß Christus für uns gestorben ist, da wir noch Sünder waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Wir werden demnach um so mehr, da wir in seinem Blute jetzt gerechtfertigt sind, durch ihn vor dem Zorne gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Denn wurden wir mit Gott durch den Tod seines Sohnes versöhnt, als wir noch Feinde waren, so werden wir noch viel mehr Rettung finden als Versöhnte in seinem Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Und nicht nur dies: Wir wollen uns auch in Gott rühmen durch unseren Herrn Jesus Christus, durch den wir jetzt die Versöhnung empfangen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Wie also durch einen Menschen die Sünde in die Welt kam und durch die Sünde der Tod und so der Tod auf alle Menschen überging, weil alle ja gesündigt hatten, -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'auch vor dem Gesetze gab es schon Sünde in der Welt; nur war die Sünde nicht angerechnet, als das Gesetz noch nicht gegeben war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Gleichwohl beherrschte von Adam bis auf Moses der Tod auch die, die nicht gesündigt hatten, wie Adam es getan, der ein Vorbild des \"Kommenden\" ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Jedoch verhält es sich mit der Begnadigung nicht so wie mit dem Sündenfall. - Wenn also durch den Fall des einen Menschen die vielen dem Tode verfallen waren, so ist viel mehr noch Gottes Gnade sowie die Gnadengabe des einen Menschen Jesus Christus vielen überreichlich zugeströmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Auch mit der Gnadengabe verhält es sich nicht so wie mit der Sünde, die von einem Menschen kommt. Denn das Gericht kam wegen einer Übertretung und führte zur Verdammung, die Begnadigung aber führte aus vielen Sünden zur Rechtfertigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Denn wenn durch die Sünde des einen der Tod eben wegen dieses einen herrschte, dann werden um so mehr die, die den Überfluß der Gnade und des Geschenkes der Gerechtigkeit empfangen, im Leben herrschen durch den einen Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Wie also durch den Fall des einen über die gesamte Menschheit die Verdammung kam, so kommt auch durch die rechtfertigende Tat des \"Einen\" über die gesamte Menschheit die lebenspendende Rechtfertigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Wie durch des einen Menschen Ungehorsam die Vielen Sünder wurden, so werden durch den Gehorsam des \"Einen\" die Vielen Gerechte werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Das Gesetz kam nur deswegen dazu, damit sich die Sünde häufe. Doch als die Sünde sich gehäuft hatte, ward die Gnade noch viel mächtiger,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'damit, wie die Sünde ihre Herrschaft im Tode gezeigt hatte, nun auch die Gnade ihre Herrschaft zeige durch die Rechtfertigung zum ewigen Leben durch Jesus Christus, unseren Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Was folgt daraus? Sollen wir in der Sünde etwa verharren, damit die Gnade um so reichlicher werde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Keineswegs! Wie sollten wir, nachdem wir der Sünde abgestorben sind, noch in ihr leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Solltet ihr das wirklich nicht wissen, daß wir alle, die wir auf Christus Jesus getauft sind, auf seinen Tod getauft sind?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Wir sind also durch die Taufe auf den Tod mit ihm begraben, damit auch wir in einem durchaus neuen Leben wandeln, wie Christus durch die Herrlichkeit des Vaters von den Toten auferweckt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Denn wenn wir durch ein Sterben, das dem seinigen ähnlich ist, schon in lebendige Verbindung mit ihm gekommen sind, so werden wir durch die ähnliche Auferstehung darin verbleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Wir wissen: Unser alter Mensch ward mitgekreuzigt, damit der Leib, der der Sünde preisgegeben ward, zugrunde gehe und wir fernerhin der Sünde nicht dienen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Wer gestorben ist, ist gerechtgesprochen von der Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Wenn wir mit Christus gestorben sind, so glauben wir, daß wir mit ihm auch leben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Wir wissen ja, daß Christus nicht mehr stirbt, nachdem er einmal von den Toten auferweckt ist; der Tod hat keine Macht mehr über ihn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Durch seinen Tod ist er der Sünde ein für allemal gestorben. Er aber, der lebt, lebt nur für Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'So müßt auch ihr euch als solche betrachten, die der Sünde abgestorben sind, jedoch für Gott durch Christus Jesus leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'So soll also nicht die Sünde in eurem sterblichen Leibe herrschen, so daß ihr seinen Lüsten folget;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'noch sollt ihr eure Glieder der Sünde zur Verfügung stellen als Werkzeuge der Ungerechtigkeit, sondern tretet ganz entschieden auf die Seite Gottes als solche, die von den Toten zum Leben auferweckt sind; betrachtet eure Glieder als Werkzeuge der Gerechtigkeit für Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Die Sünde darf euch in keiner Weise beherrschen. Ihr steht ja nicht mehr unter dem Gesetz, sondern unter der Gnade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Doch wie? Dürfen wir nun sündigen, weil wir nicht unter dem Gesetz, sondern unter der Gnade stehen? Nein, niemals.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Wisset ihr denn nicht, daß ihr als Sklaven jenem folgen müßt, dem ihr euch selbst als Sklaven zur Verfügung stellt mit der Verpflichtung zum Gehorsam: sei es der Sünde für den Tod oder der Unterwürfigkeit für die Gerechtigkeit?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Gott sei Dank! Wohl waret ihr Sklaven der Sünde, doch ihr habt euch von ganzem Herzen der Lehre unterworfen, der man euch anvertraut hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Der Sünde ledig, wurdet ihr der Gerechtigkeit dienstbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Ich rede ganz verständlich, weil ihr noch schwache Menschen seid. Wie ihr einstens eure Glieder wie Sklaven der Unlauterkeit und der Zuchtlosigkeit überlassen und ganz gesetzlos gelebt habt, so überlasset jetzt eure Glieder, ebenfalls als Sklaven, der Gerechtigkeit zur Heiligung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Solange ihr Sklaven der Sünde waret, hattet ihr an der Gerechtigkeit nicht teil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Was habt ihr damals von jenen Dingen denn geerntet, deren ihr euch nunmehr schämt? Sie brachten eben schließlich euch den Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Jetzt aber, da ihr, der Sünde ledig, Gott dient, erhaltet ihr als eure Frucht die Heiligung, die zum ewigen Leben führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Der Sünde Sold ist der Tod, die Gnade Gottes aber ewiges Leben in Christus Jesus, unserem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Oder wißt ihr, meine lieben Brüder, wirklich nicht - zu solchen rede ich, die das Gesetz verstehen -, daß das Gesetz über den Menschen herrscht, solange er lebt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'So ist eine Ehefrau an das Gesetz gebunden, solange ihr Mann noch lebt; ist der Mann tot, so ist sie frei vom Gesetz, das sie an den Mann gebunden hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Wollte sie also, solange ihr Mann noch lebt, einem anderen Mann gehören, so würde sie als Ehebrecherin gelten. Ist aber ihr Mann gestorben, so ist sie vom Gesetze frei und keine Ehebrecherin, wenn sie einem anderen Manne angehört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Auch ihr, meine lieben Brüder, seid durch den Leib Christi für das Gesetz gestorben, so daß ihr einem anderen angehören dürft, dem, der von den Toten erweckt ward, damit wir fortan für Gott fruchtbar seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Solange wir nämlich noch im Fleische lebten, wirkten die durch das Gesetz geweckten sündhaften Leidenschaften in unseren Gliedern, so daß wir für den Tod fruchtbar waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Nun aber sind wir des Gesetzes ledig, weil wir dem, was uns in Banden hielt, gestorben sind. Wir dienen also in einem neuen Geist und nicht in veralteten Gesetzesvorschriften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Was weiter? Ist das Gesetz etwa Sünde? Durchaus nicht. Aber wenn das Gesetz nicht wäre, dann wäre ich mit der Sünde nicht bekannt geworden. Ich wüßte auch nichts von der Begierde, wenn das Gesetz nicht sagte: \"Du sollst nicht begehren!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Die Sünde nahm das Gebot zum Anlaß und weckte jede Gier in mir; denn ohne das Gesetz ist die Sünde tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Einst lebte ich selber ohne das Gesetz; es kam das Gebot, und da lebte auch die Sünde auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Ich starb. Es zeigte sich zu meinem Schaden, daß eben das Gesetz, das zum Leben führen sollte, den Tod gebracht hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Die Sünde hatte im Gebot ja einen Anlaß; sie hatte mich getäuscht und mich dadurch gemordet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Nun ist aber doch das Gesetz heilig; auch das Gebot ist heilig und gerecht und gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'So wäre das Gute für mich zum Tode geworden? Durchaus nicht. Es war die Sünde. Sie sollte als Sünde offenkundig werden dadurch, daß sie mir den Tod schuf durch das, was an sich gut war; die Sünde sollte über alle Maßen sündhaft erwiesen werden durch das Gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Wir wissen: Das Gesetz ist geistig, ich aber bin fleischlich und an die Sünde verkauft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Das, was ich tue, ist mir nicht verständlich; denn ich tue nicht, was ich will, sondern was ich hasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Doch, wenn ich tue, was ich nicht will, so gebe ich damit zu, daß das Gesetz gut ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Dann aber handle ja nicht ich, vielmehr handelt die Sünde, die in mir wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Ich weiß: In mir, das heißt in meiner Sinnlichkeit, wohnt nichts Gutes. Es fällt mir zwar leicht, das Gute zu wollen, doch nicht in gleicher Weise, es zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Tue ich doch nicht das Gute, das ich will; ich tue, was ich nicht will, das Böse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Doch wenn ich das, was ich nicht will, tue, dann bin nicht ich es, der handelt, vielmehr ist es die Sünde, die in mir wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Ich finde somit das Gesetz: Wenn ich das Gute tun möchte, liegt mir das Böse näher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Dem inneren Menschen nach habe ich ja Freude am Gesetz Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Ich sehe aber auch ein ganz davon verschiedenes Gesetz in meinen Gliedern, das dem Gesetz meiner Vernunft widerstreitet und mich im Gesetz der Sünde gefangenhält, das in meinen Gliedern wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ich unglückseliger Mensch! Wer wird mich aus einem Leib erlösen, der solches Sterben in sich trägt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Dank sei Gott - durch Jesus Christus, unseren Herrn. Also bin auch ich selbst in meinem Verstande zwar dem Gesetz Gottes unterworfen, mit meinem Leib aber dem Gesetz der Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'So gibt es also in jenen, die in Christus Jesus sind und nicht nach dem Fleische wandeln, jetzt nichts mehr, was zur Verdammung führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Das Gesetz des Geistes, das Leben spendet, hat mich befreit in Christus Jesus von der Macht der Sünde und des Todes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Was das Gesetz nicht fertigbrachte, wozu es wegen der Sinnlichkeit der Menschen viel zu schwach gewesen war, hat Gott vermocht. Er sandte seinen eigenen Sohn, dem sündigen Fleische ähnlich und um der Sünde willen, und er verurteilte an seiner menschlichen Natur die Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Es sollte demnach die Rechtsforderung des Gesetzes an uns vollendet werden, die nicht mehr sinnlich, vielmehr geistig wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Denn wer sinnlich lebt, denkt an die Forderungen des Fleisches, wer aber geistig lebt, an die des Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Des Sinnenmenschen Sinnen führt zum Tode, doch das des geistigen zum Leben und zum Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Darum bedeutet auch des Sinnenmenschen Sinnen Feindschaft gegen Gott; es ordnet sich ja keinesfalls dem Gesetze Gottes unter, und es vermag es auch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Die aber sinnlich leben, können Gott nicht gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Ihr aber lebt nicht mehr im Machtbereich der Sinnlichkeit, vielmehr in dem des Geistes, wenn wirklich Gottes Geist in euch wohnt. Wer aber den Geist Christi nicht hat, gehört ihm auch nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Ist aber Christus in euch, so ist der Leib zwar dem Tode verfallen durch die Sünde, der Geist jedoch bestimmt für das Leben infolge der Rechtfertigung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Wenn weiter der Geist dessen in euch wohnt, der Jesus von den Toten auferweckt hat, so wird er, der Christus von den Toten auferweckt hat, auch eure sterblichen Leiber erwecken durch seinen Geist, der in euch wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'So sind wir es also, Brüder, keineswegs der Sinnlichkeit schuldig, in Sinnlichkeit zu leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Denn wenn ihr sinnlich lebt, dann müßt ihr sterben. Doch wenn ihr durch den Geist die Werke des Leibes tötet, werdet ihr leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Alle, die sich vom Geiste Gottes leiten lassen, sind Kinder Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Ihr habt doch nicht den Geist der Knechtschaft empfangen, so daß ihr euch von neuem fürchten müßtet. Nein! Ihr habt den Geist der Annahme als Kind empfangen, in dem wir rufen: Abba, Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Der Geist bezeugt es selbst mit unserem Geist zusammen, daß wir Kinder Gottes sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Und sind wir Kinder, alsdann sind wir auch Erben: Erben Gottes und zugleich mit Christus Erben; nur müssen wir mit ihm auch leiden, um mit ihm verherrlicht zu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Ich bin jedoch der festen Überzeugung, daß die Leiden dieser Zeit nicht zu vergleichen sind mit der Herrlichkeit, die an uns offenbar wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Und so erwartet auch die ganze Schöpfung in heißer Sehnsucht die Offenbarung der Kinder Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Ist doch die Schöpfung der Vergänglichkeit unterworfen, nicht freiwillig, sondern um des willen, der sie unterwarf, mit der Hoffnung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'daß einst auch sie, die Schöpfung, von der Knechtschaft der Vergänglichkeit erlöst wird zur Freiheit der Herrlichkeit der Kinder Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Wir wissen ja, daß die ganze Schöpfung voll Seufzen und Wehen ist bis auf diesen Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Und nicht nur sie allein; auch wir, die wir als Erstlingsgabe den Geist besitzen, seufzen in unserem Innern in der Erwartung dieser Annahme an Kindes Statt, nämlich der Erlösung unseres Leibes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Denn auf Hoffnung hin wurden wir gerettet. Nun ist eine Hoffnung, die man sieht, keine Hoffnung mehr. Wie könnte man noch hoffen, was man schon sieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Doch hoffen wir auf das, was wir nicht sehen, dann müssen wir eben in Geduld warten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Ebenso nimmt sich der Geist auch unserer Schwachheit an; wir wissen ja nicht, um was wir richtig beten sollen. Da tritt der Geist selbst für uns ein mit wortlosen Seufzern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Und er, der die Herzen erforscht, weiß, was der Geist begehrt, daß er so, wie es Gottes Wille ist, für die Heiligen betet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Wir wissen, daß jenen, die Gott lieben, alles zum Heile zusammenwirkt, weil sie nach seinem Ratschluß zu Heiligen berufen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Denn die, die er vorhererkannte, hat er auch vorherbestimmt, dem Bilde seines Sohnes gleich zu werden, der dadurch der Erstgeborene unter vielen Brüdern wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Die er vorherbestimmt hat, hat er auch berufen; die er berufen hat, hat er gerecht gemacht, und die er gerecht gemacht hat, hat er verklärt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Was sollen wir zu alldem sagen? Wenn Gott für uns ist, wer ist dann gegen uns?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Er, der seines eigenen Sohnes nicht geschont, vielmehr ihn für uns alle hingegeben hat, wie sollte dieser uns nicht alles auch mit ihm in Gnaden schenken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Wer sollte gegen Gottes Auserwählte klagen? Etwa Gott, der sie gerecht gemacht hat?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Wer verurteilt? Etwa Christus Jesus, der starb, oder besser, der auferweckt wurde, der nun zur Rechten Gottes ist und auch für uns bittet?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Wer wird uns scheiden von der Liebe Christi? Trübsal, Bedrängnis und Verfolgung, Hunger oder Blöße oder Todesgefahr oder das Schwert?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'So steht es ja in der Schrift: \"Stets sind wir deinetwegen in der Todesgefahr; Opferschafen sind wir gleichgeachtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Doch über all dies kommen wir siegreich hinweg durch ihn, der uns geliebt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Ich lebe der Überzeugung: Weder Tod noch Leben, nicht Engel und nicht Herrschaften, nicht Gegenwärtiges noch Kommendes, nicht Mächte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'nicht Höhe oder Tiefe noch sonst ein anderes Geschöpf wird uns scheiden können von der Liebe Gottes, die da ist in Christus Jesus, unserem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Ich sage die Wahrheit in Christus; ich lüge nicht; zudem bezeugt es mir auch mein Gewissen im Heiligen Geiste,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'daß ich in großer Trauer bin und daß der Kummer meines Herzens nicht vergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Ich wollte ja, ich selbst, von Christus fern und verflucht sein an Stelle meiner Brüder, die dem Leibe nach meine Stammesgenossen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Israeliten sind sie; die Gotteskindschaft gehört ihnen, die Gottesherrlichkeit sowie die Bundesschlüsse, das Gesetz, der Tempeldienst und die Verheißungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Auch die Väter gehören ihnen, aus denen dem Leibe nach Christus stammt, der Gott ist über allem, hochgelobt in Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Dabei ist es aber nicht so, als ob das Wort Gottes vereitelt worden wäre. Denn nicht alle, die von Israel abstammen, sind auch echte Israeliten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Auch sind nicht alle, weil sie von Abraham stammen, seine Kinder, sondern: \"Nur in Isaak sollen dir Nachkommen angerechnet werden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Das will besagen: Nicht ohne weiteres sind schon die leiblichen Kinder Kinder Gottes; es werden vielmehr nur die Kinder der Verheißung als Nachkommen gerechnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Denn also lautet das Verheißungswort: \"Ich werde wieder zur gegebenen Zeit kommen, und Sara wird dann einen Sohn besitzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'So aber war es nicht nur in diesem Falle, vielmehr auch bei Rebekka, die nur von einem Manne, unserem Vater Isaak, Kinder hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Sie waren noch nicht geboren und hatten weder gut noch bös gehandelt, da ward ihr schon gesagt, damit der Ratschluß Gottes nach freier Wahl bleibe: -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'doch nicht auf Grund von Werken, sondern durch Berufung - \"Der Ältere wird dem Jüngeren dienstbar sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'So steht es auch geschrieben: \"Ich liebte den Jakob, doch Esau war mir gleichgültig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Was werden wir nun sagen? Ist nicht Ungerechtigkeit bei Gott? In keiner Weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Sagt er doch zu Moses: \"Erbarmen will ich mich, wessen ich mich erbarmen will, und ich schenke mein Mitleid dem, mit dem ich Mitleid haben will.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'So kommt es also nicht aufs Wollen an, auch nicht aufs Rennen, viel mehr allein auf das Erbarmen Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'So sagt die Schrift zu Pharao: \"Gerade dazu habe ich dich aufgerufen, damit ich meine Allmacht an dir zeigen kann und mein Name in der ganzen Welt gepriesen werde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Und so erbarmt er sich dessen, den er will, und er verstockt auch, wen er will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Du wirst mir nun entgegenhalten: \"Was hat er dann noch zu tadeln? Wer kann denn seinem Willen widerstehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'O Mensch! Wer bist du denn, daß du mit Gott hadern willst? Darf das Geschöpf zum Schöpfer sagen: Warum hast du mich so gemacht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Oder verfügt nicht der Töpfer über seinen Ton, so daß er aus derselben Masse Prunkgefäße, aber auch Gefäße zu niedrigem Gebrauche machen könnte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Wenn Gott, obwohl er seinen Zorn erzeigen und seine Stärke kundtun wollte, mit großer Langmut doch die Gefäße des Zornes, die schon zum Verderben bestimmt waren, ertragen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'nur um an den Gefäßen der Erbarmung den Reichtum seiner Herrlichkeit zu zeigen... Sie hat er zur Verklärung vorbereitet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'zu der er auch uns berufen hat nicht nur aus den Juden, sondern auch aus den Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Bei Osee sagt er ja: \"Das \'Nicht-Mein-Volk\' will ich \'Mein Volk\' nennen, die \'Nicht-Geliebte\' die \'Geliebte\' und die \'Nichtbegnadigte\' \'Begnadigte\'.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Wo man zu ihnen sprach: \"Ihr seid nicht mehr mein Volk, gerade dort wird man sie \'Söhne des lebendigen Gottes\' nennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Isaias ruft über Israel: \"Wäre auch die Zahl der Kinder Israels wie der Sand am Meere, der Rest nur wird gerettet werden;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'der Herr wird sein Wort schnell und gründlich in Gerechtigkeit, weil ein schnelles Wort in der Welt vollenden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Isaias hat auch vorhergesagt: \"Wenn nicht der Herr der Heerscharen uns einen Rest gelassen hätte, wir wären wie Sodoma geworden, ähnlich wie Gomorrha.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Was werden wir nun weiter sagen? Daß Heiden, die die Rechtfertigung nicht anstrebten, Rechtfertigung erlangt haben, und zwar Rechtfertigung aus dem Glauben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'daß aber Israel, das nach einer Lebensregel lebte, die Rechtfertigung bewirken sollte, sie nicht erreicht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Warum? Weil es nicht aus Glauben danach strebte, sondern sozusagen nur aus Werken. Sie stießen sich am Stein des Anstoßes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'wie auch geschrieben steht: \"Siehe, ich setze in Sion einen Stein des Anstoßes und einen Fels des Ärgernisses; wer an ihn glaubt, wird nicht zuschanden werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Liebe Brüder! Meines Herzens Wunsch und mein Gebet zu Gott gilt ihnen, daß sie gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Denn ich bezeuge ihnen, daß sie zwar Eifer für Gott haben, doch nicht in rechter Einsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Sie verkannten die Gerechtigkeit aus Gott und suchten ihre eigene aufzustellen und unterwarfen sich so nicht der Gerechtigkeit aus Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Mit Christus hat das Gesetz ein Ende, so daß ein jeder gerecht wird nur durch Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Schreibt Moses doch von der Gerechtigkeit aus dem Gesetze: \"Wer dies tut, wird dadurch leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Doch die Gerechtigkeit des Glaubens sagt: \"Sprich nicht in deinem Herzen: \'Wer wird zum Himmel steigen?\'\" - nämlich um Christus von dort herabzuholen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Oder - \"Wer wird in den Abgrund steigen?\" - nämlich um Christus von den Toten zurückzurufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Nein! Wie spricht sie vielmehr? \"Nahe bei dir ist das Wort, in deinem Mund und in deinem Herzen\", das Wort des Glaubens nämlich, das wir verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Wenn du also mit deinem Mund bekennst: Jesus ist der Herr, und in deinem Herzen glaubst, daß Gott ihn von den Toten auferweckt hat, wirst du gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Denn mit dem Herzen glaubt man, um gerecht zu werden; doch mit dem Munde bekennt man, um Rettung zu erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'So sagt ja auch die Schrift: \"Wer an ihn glaubt, wird nicht zuschanden werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Da gibt es keinen Unterschied mehr zwischen Juden und Heiden; derselbe Herr ist der Herr aller, der reichlich allen gibt, die zu ihm rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '\"Wird doch jeder, der den Namen des Herrn anruft, gerettet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Wie sollen sie aber den anrufen, an den sie noch nicht glauben? Wie sollen sie an den glauben, von dem sie nichts gehört haben? Wie können sie hören, wenn ihnen nicht gepredigt wird?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Wie können sie denn predigen, wenn sie nicht gesandt sind? So steht es ja auch geschrieben: \"Wie lieblich sind die Füße derer, die den Frieden verkünden eine frohe Botschaft verkünden!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Jedoch nicht alle wollen jener frohen Botschaft Folge leisten, sagt doch Isaias: \"Herr, wer glaubt unserer Predigt?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'So kommt der Glaube aus dem Hören; was aber gehört wird, kommt durch das Wort Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Vielleicht vernahmen sie aber nichts davon? O doch! \"Ihr Schall drang in die ganze Welt, ihr Wort bis an die Enden der Erde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Vielleicht, frage ich, verstand es Israel nicht? Zunächst sagt Moses: \"Ich will euch eifersüchtig machen auf ein \'Nicht-Volk\', zum Zorn euch reizen auf ein unverständiges Volk.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Isaias getraut sich sogar zu sagen: \"Auffinden ließ ich mich von solchen, die mich nicht suchten, und offenkundig ward ich denen, die nicht nach mir fragten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Jedoch von Israel spricht er: \"Ich streckte allzeit meine Hände aus nach einem ungläubigen und widerspenstigen Volke.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Ich frage weiter: Hat Gott sein Volk etwa verstoßen? Gewiß nicht. Denn auch ich bin Israelit, aus Abrahams Geschlecht, vom Stamme Benjamin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gott hat sein Volk, das er sich auserwählte, nicht verstoßen. Oder wißt ihr denn nicht, was die Schrift in der Geschichte des Elias sagt, als er sich bei Gott über Israel beklagte:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '\"O Herr, sie haben deine Propheten gemordet, Deine Altäre verwüstet; nur ich allein bin übrig, und auch mir trachten sie nach dem Leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Was sagt ihm dann der Gottesspruch? \"Ich habe mir siebentausend Männer aufbewahrt, die ihre Knie vor Baal nicht gebeugt haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'So ist auch in unserer Zeit ein Rest geblieben, den die Gnade sich auserwählt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Hat ihn die Gnade sich auserwählt, dann geschah es nicht auf Grund von Werken; sonst wäre ja die Gnade keine Gnade mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Was nun? Was Israel erstrebte, hat es nicht erreicht. Nur der auserwählte Teil hat es erreicht, die anderen wurden verstockt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'wie geschrieben steht: \"Gott gab ihnen den Geist der Betäubung, Augen, damit sie nicht sehen, und Ohren, damit sie nicht hören bis auf diesen Tag.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Und David sagt: \"Ihr Tisch soll ihnen zur Schlinge werden, zur Falle, zum Anstoß und zur Vergeltung;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'ihre Augen sollen finster werden, so daß sie nicht mehr sehen. Für immer beuge ihren Rücken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Ich frage nun: Sind sie gestrauchelt, so daß sie nun verloren sind? Gewiß nicht. Vielmehr kam zu den Heiden das Heil erst durch ihr Verderben, um dadurch ihre Eifersucht zu wecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Ist aber ihr Verderben für die Welt zum Reichtum und ihr Versagen zum Reichtum für die Heidenwelt geworden, um wieviel mehr dann erst, wenn sie vollzählig werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Jedoch, ich rede ja zu euch, den Heiden. Soweit ich Apostel für die Heiden bin, will ich meinem Amt Ehre machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Vielleicht kann ich meine Stammesbrüder zur Eifersucht verleiten und dadurch einige aus ihnen retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Denn wenn schon ihre Verwerfung Versöhnung für die Welt bedeutet, was mag dann erst die Aufnahme bedeuten? Nichts anderes als ein Leben aus den Toten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Denn ist die Erstlingsgabe heilig, dann ist es auch die ganze Masse, und ist die Wurzel heilig, so sind es auch die Zweige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Wenn einige der Zweige ausgebrochen wurden, und du, der du ein Wildling bist, zwischen ihnen eingesetzt warst und also Anteil an der Wurzel und dem Saft des Ölbaums bekamst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'alsdann erhebe dich doch nicht über die Zweige. Wenn du dich rühmen wolltest, so bedenke: Nicht du bist es, der die Wurzel trägt, vielmehr trägt die Wurzel dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Du magst nun sagen: \"Es mußten aber Zweige ausgebrochen werden, damit ich eingepflanzt würde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Gut! Sie wurden wegen ihres Unglaubens ausgebrochen, und du bist deines Glaubens wegen eingepflanzt. So werde also nicht stolz; bleibe vielmehr in der Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Wenn Gott schon die gewachsenen Zweige nicht verschont hat, so wird er deiner auch nicht schonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Also beachte Gottes Güte wie auch seine Strenge: die Strenge gegen die Verworfenen, die Güte Gottes gegen dich, Solange du seiner Güte treu bleibst. Sonst wirst auch du noch ausgehauen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Jedoch auch jene werden wieder eingepflanzt, wenn sie nicht im Unglauben verharren; denn Gott hat Macht genug, sie wieder einzupflanzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Wenn du aus dem gewachsenen Wildling, abgeschnitten und gegen den sonstigen Brauch einem edlen Ölbaum eingepflanzt wurdest, um wie viel leichter können diese, die gewachsenen Zweige, dann ihrem eigenen Baume wieder eingepflanzt werden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Liebe Brüder! Ich will euch folgendes Geheimnis nicht verbergen, auf daß ihr euch selbst vor euch ja nicht weise dünket: Die Verstocktheit eines Teils von Israel wird nur solange dauern, bis die Vollzahl der Heiden eingetreten ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Alsdann wird das gesamte Israel das Heil erlangen, wie geschrieben steht: \"Von Sion wird ein Retter kommen; wegschaffen wird er die Gottlosigkeit aus Jakob;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'und dies ist mein Bund mit ihnen, wenn ich ihre Sünden tilge.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Im Hinblick auf das Evangelium sind diese euretwegen Feinde, im Hinblick aber auf die Auserwählung um der Väter willen seine Lieblinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Unwiderruflich sind die Gnadengaben und die Erwählung Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Wie ihr einst Ungehorsam gegen Gott bewiesen, doch jetzt durch ihren Ungehorsam Erbarmen gefunden habt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'so sind auch diese jetzt ungehorsam geworden, um durch eben das Erbarmen, das ihr gefunden habt, jetzt auch Erbarmen zu erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'So hat Gott alle zusammen ungehorsam werden lassen, damit er sich aller erbarme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O Abgründe des Reichtums und der Weisheit und der Einsicht Gottes! Wie unbegreiflich sind seine Gerichte, wie unerforschlich seine Wege!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, '\"Wer erkennt den Ratschluß des Herrn? Oder wer will ihn beraten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Oder wer gibt ihm zuerst etwas, so daß er ihm vergelten müßte?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Denn alles ist aus ihm, durch ihn und zu ihm hin; ihm sei die Ehre für die Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Liebe Brüder, ich beschwöre euch bei den göttlichen Erbarmungen, bringt eure Leiber als ein lebendiges, heiliges und Gott gefälliges Opfer dar. Dies sei euer geisterfüllter Gottesdienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Werdet dieser Welt nicht ähnlich; sondern wandelt euch um durch einen neuen Geist, so daß ihr prüfen könnt, was Gottes Wille ist, was gut, wohlgefällig und vollendet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Kraft der mir geschenkten Gnade sage ich einem jeden aus euch: Denkt nicht höher von euch, als recht ist, denkt vielmehr bescheiden, wie Gott einem jeden das Maß des Glaubens zugemessen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Denn wie wir an einem Leibe viele Glieder haben, nicht alle Glieder aber demselben Zwecke dienen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'so sind wir viele ein Leib in Christus, einzeln betrachtet aber Glieder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'mit Gaben ausgestattet, die sich unterscheiden je nach der Gnade, die uns verliehen ward. Ist es die gotterfüllte Redegabe, so laßt sie uns gebrauchen entsprechend unserem Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Ist es ein Amt in der Gemeinde, so bleibe er bei dem Amte. Ist es die Unterweisungsgabe, so unterweise er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Und wer die Gabe des Trostes hat, der tröste. Wer Almosen ausspendet, tu es schlichten Sinnes. Der Vorsteher sei es mit allem Eifer. Und der Barmherzige sei es in Freudigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Die Liebe sei ohne Falsch. Haßt das Böse. Haltet fest am Guten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'In brüderlicher Liebe seid einander innig zugetan. Zeichnet euch in Achtung voreinander aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Erlahmt nicht im Eifer. Seid feurigen Geistes. Dient dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Seid fröhlich in der Hoffnung, geduldig in der Trübsal, beharrlich im Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Nehmt teil an den Bedürfnissen der Heiligen. Pflegt eifrig die Gastfreundschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Segnet die, die euch verfolgen; segnet sie, verflucht sie nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Freut euch mit den Fröhlichen, weinet mit den Weinenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Seid eines Sinnes miteinander. Seid nicht stolzen Sinnes, vielmehr befaßt euch auch mit niedrigeren Diensten. Haltet euch nicht selbst für klug.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Vergeltet niemand Böses Mit Bösem. Seid \"vor allen Menschen nicht nur vor Gott auf das Gute bedacht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Soweit es möglich ist und es auf euch ankommt, haltet mit allen Menschen Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Rächt euch nicht selber, Geliebteste, laßt vielmehr Raum für Gottes Zorn. Denn so steht geschrieben: \"Mein ist die Rache; ich will vergelten, spricht der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Im Gegenteil - \"Wenn deinen Feind hungert, gib ihm zu essen, und wenn ihn dürstet, gib ihm zu trinken. Denn wenn du solches tust, wirst du glühende Kohlen ihm auf das Haupt sammeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Laß dich vom Bösen nicht überwinden, sondern überwinde das Böse durch das Gute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Ein jeder sei untertan der obrigkeitlichen Gewalt; gibt es doch keine Obrigkeit, sie wäre denn von Gott. Wo immer eine ist, da ist sie von Gott eingesetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Wer sich also der Obrigkeit widersetzt, der widersetzt sich der Anordnung Gottes, und alle, die sich widersetzen, ziehen ihr Strafgericht sich selber zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Die Beamten sind kein Grund zur Furcht für die, die das Gute tun, sondern für die, die Böses tun. Du möchtest keinen Anlaß haben, die Obrigkeit zu fürchten? Tu, was recht ist, dann wirst du von ihr Lob erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Sie ist für dich eine Gehilfin Gottes für das Gute. Doch wenn du Böses tust, dann fürchte dich. Sie trägt das Schwert nicht zwecklos; ist sie doch die Gehilfin Gottes, um rächend an denen seine Strafe zu vollziehen, die Böses tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'So muß man also sich ihr unterwerfen nicht allein der Strafe wegen, vielmehr auch des Gewissens halber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Deshalb bezahlt ihr auch Steuern; sind sie doch Diener Gottes, die gerade dazu angestellt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'So gebt denn jedem, was ihr schuldig seid: Steuer, wem Steuer, Zoll, wem Zoll; Ehrfurcht, wem Ehrfurcht, Ehre, wem Ehre gebührt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Bleibt niemand etwas schuldig; außer, daß ihr einander liebet. Denn wer den Nächsten liebt, hat das Gesetz erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Denn die Gebote: \"Du sollst nicht ehebrechen\", \"Du sollst nicht töten\", \"Du sollst nicht stehlen\", Du sollst kein falsches Zeugnis geben, \"Du sollst nicht begehren\" und all die anderen Gebote sind in dem einen Gotteswort zusammengefaßt: \"Du sollst deinen Nächsten lieben wie dich selbst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Die Liebe fügt dem Nächsten in keiner Weise Böses zu; die Liebe ist also die Vollendung des Gesetzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'So handelt denn danach in richtiger Erkenntnis der Zeit, daß jetzt die Stunde für euch da ist, vom Schlafe aufzustehen. Unser Heil ist jetzt viel näher als damals, da wir gläubig wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Die Nacht ist vorangeschritten, der Tag hat sich genaht. So laßt uns ablegen die Werke der Finsternis, die Waffen des Lichtes aber anlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Wir wollen ehrbar wandeln wie am hellen Tage, nicht in Schwelgereien und Gelagen, nicht in Wollust und Ausschweifung, nicht in Streit und Eifersucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Zieht vielmehr den Herrn Jesus Christus an und pflegt nicht das Fleisch, so daß es lüstern wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Nehmt euch um den an, der im Glauben schwach ist, doch nicht, um mit ihm wegen Meinungsverschiedenheiten zu streiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Der eine hat genügend Glauben, so daß er alles essen kann; ein anderer, der noch schwach ist, ißt eben nur Gemüse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Wer alles essen kann, soll den nicht verachten, der nicht ißt, und wer nicht ißt, soll den, der ißt, nicht verdammen; Gott hat ihn ja aufgenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Wer bist denn du, daß du einen fremden Knecht richtest? Er steht und fällt nur seinem eigenen Herrn. Doch wird er stehen; denn der Herr hat Macht genug, ihn aufzurichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Und wieder einer macht einen Unterschied zwischen Tag und Tag; ein anderer nimmt alle Tage gleich. Jeder soll in seinem eigenen Innern voll überzeugt sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Wer den Tag beobachtet, beobachtet ihn für den Herrn; wer ißt, ißt für den Herrn; denn er dankt Gott. Und wer nicht ißt, der ißt nicht für den Herrn; denn er dankt Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Und überhaupt lebt keiner aus uns für sich selbst, und keiner stirbt für sich selbst;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'sondern wenn wir leben, so leben wir für den Herrn, und wenn wir sterben, so sterben wir für den Herrn; wir mögen also leben oder sterben, wir sind des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'ist Christus doch gerade deshalb gestorben und wieder lebendig geworden, damit er über Lebende und Tote herrsche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Warum richtest du deinen Bruder? Oder warum verachtest du deinen Bruder? Werden doch wir alle vor dem Richterstuhl Gottes stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Es steht ja geschrieben: \"\'So wahr ich lebe\', spricht der Herr, \'vor mir wird jedes Knie sich beugen, und jede Zunge wird Gott preisen.\'\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'So muß denn jeder aus uns für Sich selbst vor Gott Rechenschaft ablegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Darum wollen wir einander nicht mehr richten, sondern richtet eher darauf euer Augenmerk, daß ihr eurem Bruder nicht Anstoß gebt noch Ärgernis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Ich weiß und bin davon im Herrn Jesus überzeugt, daß an sich nichts unrein ist. Wenn aber einer meint, es sei etwas nicht rein, für den ist es dann unrein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Fühlt sich daher dein Bruder durch dein Essen verletzt, so wandelst du nicht mehr der Liebe entsprechend. Bring durch dein Essen nicht den ins Verderben, für den Christus gestorben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Laßt euren Vorzug doch nicht zum Ärgernis werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Im Reiche Gottes handelt es sich nicht um Essen oder um Trinken, sondern um Gerechtigkeit, Friede und Freude im Heiligen Geiste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Wer auf solche Weise Christus dient, der ist vor Gott wohlgefällig und anerkannt bei den Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'So laßt uns auf das sinnen, was dem Frieden und der gegenseitigem Erbauung dient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Vernichte doch nicht einer Speise wegen Gottes Werk. Es ist zwar alles rein, doch Sünde ist es dem, der durch sein Essen Anstoß gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Es ist auch recht, kein Fleisch zu essen und keinen Wein zu trinken noch sonst etwas zu tun, woran dein Bruder Anstoß nimmt oder Ärgernis nimmt oder schwach wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Doch du behalte die Überzeugung, die du hast, für dich vor deinem Gott. Wohl dem, der sich bei seiner Entscheidung nicht selbst zu verdammen braucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Wer aber zweifelt und dann trotzdem ißt, ist schon gerichtet, weil er es nicht aus Glauben tut. Alles, was nicht aus Glauben kommt, ist Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Wir nun, die Starken, müssen die Gebrechen der Schwachen tragen, doch ohne Selbstgefälligkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Ein jeder aus uns sei gefällig gegen seinen Nächsten, so daß das Gute zur Erbauung werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Auch Christus lebte nicht sich zu Gefallen, sondern wie geschrieben steht: \"Die Lästerungen derer, die dich lästern, sind auf mich gefallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Was immer vormals geschrieben ward, ist geschrieben, um uns zu belehren, damit wir durch Geduld und durch den Trost der Schriften uns die Hoffnung bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Der Gott der Geduld und des Trostes aber möge euch verleihen, nach der Lehre Christi Jesu eines Sinns zu sein,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'damit ihr einmütig mit einem Mund Gott und den Vater unseres Herrn Jesus Christus verherrlichet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'So nehme sich denn der eine des anderen an, wie sich Christus eurer zur Ehre Gottes angenommen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Ich sage: Christus wurde der Diener der Beschneidung, um zu erweisen, daß Gott treu ist, und um die Verheißungen zu erfüllen, die einst den Vätern gegeben wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Die Heiden aber preisen Gott um des Erbarmens willen. Es heißt ja in der Schrift: \"Deshalb will ich Dich preisen bei den Heiden und Deinem Namen jubeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Und wieder heißt es: \"Freuet euch samt seinem Volke, ihr Heiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Und noch einmal: \"Ihr Heiden alle, lobt den Herrn! Alle Völker sollen ihn preisen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Und weiter sagt Isaias: \"Es kommt die Wurzel Jesse und ihr Schößling, die Heiden zu beherrschen; auf diesen hoffen auch die Heiden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Der Gott der Hoffnung aber erfülle euch mit aller Freude und mit allem Frieden im Glauben, damit ihr überströmt an Hoffnung in Kraft des Heiligen Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Liebe Brüder! Ich selbst bin überzeugt, daß ihr voll guten Willens seid, erfüllt mit aller Erkenntnis und wohl imstande, einander zu ermahnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Vielleicht zu freimütig habe ich zum Teil euch geschrieben, um durch die Gnade, die mir von Gott zuteil geworden ist, euer Gedächtnis aufzufrischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Ich soll ja für die Heiden der Diener Christi Jesu sein, der am Evangelium Gottes heiligen Dienst verrichtet, damit die Heiden ein Gott wohlgefälliges Opfer werden, geheiligt im Heiligen Geiste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'So darf ich mich in Christus Jesus auch der Sache Gottes rühmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Ich möchte mich ja nicht erkühnen, von etwas anderem zu reden als von dem, was Christus, um die Heiden zum Gehorsam zu bewegen, in Wort und Tat durch mich vollbracht hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'in Kraft der Zeichen und der Wunder, in Kraft des Geistes Gottes. So konnte ich, angefangen von Jerusalem, im großen Bogen bis nach Illyrien das Evangelium Christi überall verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Ich setzte meine Ehre dabei darein, das Evangelium nicht da zu verkündigen, wo der Name Christi schon bekannt war. Ich wollte nicht auf fremdem Grundstein weiterbauen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'sondern wie geschrieben steht: \"Die werden es sehen, denen von ihm noch nichts verkündet ward, und die verstehen, die noch nichts vernommen haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Deshalb ward ich auch immer wieder abgehalten, zu euch zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Jetzt aber, da ich kein Arbeitsfeld in diesen Gegenden mehr habe, dagegen schon seit vielen Jahren das Verlangen in mir trage, zu euch zu kommen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'wenn ich nach Spanien reise, hoffe ich, euch auf der Durchreise zu sehen und euer Geleit dorthin zu erhalten, nachdem ich vorher mich bei euch erfreut habe, sei es auch nur für kurze Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Zunächst jedoch gehe ich nach Jerusalem, um den Heiligen zu Dienste zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Mazedonien und Achaia faßten nämlich den Beschluß, eine Sammlung zu veranstalten für die Armen bei den Heiligen in Jerusalem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Sie taten es gerne, sind sie doch in deren Schuld. Denn wenn sie den Heiden Anteil an ihren geistigen Gaben gegeben haben, so müssen diese dafür ihnen mit leiblichen Gütern dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Wenn ich dann damit fertig bin und ihnen den Ertrag der Sammlung treulich übergeben habe, will ich auf meiner Fahrt nach Spanien zu euch kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'ich weiß, daß, wenn ich zu euch komme, ich in der Segensfülle Christi komme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Liebe Brüder, bei unserem Herrn Jesus Christus und bei der Liebe des Geistes bitte ich euch: Steht mir im Kampfe bei durch eure Fürbitte für mich bei Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'damit ich vor den Ungläubigen in Judäa gerettet werde und daß dann meine für Jerusalem bestimmte Dienstleistung von den Heiligen gut aufgenommen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Dann kann ich auch zu euch in Freude kommen und mich, so Gott will, am Verkehr mit euch erquicken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Der Gott des Friedens sei mit euch allen! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Und nun empfehle ich euch unsere Schwester Phöbe; sie ist in Kenchreae im Dienste der Gemeinde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Nehmt sie im Herrn auf, so wie es sich für Heilige geziemt. Steht ihr in all den Anliegen bei, in denen sie euch etwa braucht. Sie ist ja vielen beigestanden, auch mir selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Grüßt Priska und den Aquila, meine Mitarbeiter in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Sie haben ihren Nacken für mein Leben dargeboten. Nicht bloß ich bin ihnen dafür dankbar, auch alle Heidengemeinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Grüßt besonders ihre Hausgemeinde. Grüßt meinen vielgeliebten Epänetus, ist er doch die Erstlingsgabe Asiens für Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Grüßt Maria, die so vieles unter euch gewirkt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Grüßt Andronikus, sowie Junias, meine Landsleute und Mitgefangenen, bei den Aposteln hochberühmt und länger schon als ich Christen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Grüßt meinen Ampliatus, vielgeliebt im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Grüßt unseren Mitarbeiter in Christus, Urbanus, und meinen geliebten Stachys!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Grüßt Apelles, den in Christus wohlbewährten! Grüßt die Hausgenossen des Aristobul!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Grüßt den Herodion, meinen Landsmann! Grüßt die Hausgenossen des Narzissus, die im Herrn leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Grüßt Tryphäna und Tryphosa, die sich im Herrn abgemüht haben. Grüßt die geliebte Persis, die sich so sehr im Herrn gemüht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Grüßt Rufus, den im Herrn Auserwählten, und seine Mutter, die auch mir zur Mutter ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Grüßt Asynkritus, Phlegon, Hermes, Patrobas, Hermas und die Brüder, die dort sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Grüßt Philologus und Julia, Nereus und seine Schwester, Olympias und seine Heiligen, die bei ihnen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Grüßt mit heiligem Kuß euch gegenseitig. Alle Gemeinden Christi grüßen euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Ich bitte euch aber, liebe Brüder, daß ihr die im Auge behaltet, die Spaltungen und Ärgernisse erregen im Widerspruch zur Lehre, die ihr vernommen habt. Haltet euch von ihnen fern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Denn solche dienen nicht unserem Herrn Christus, sondern ihrem eigenen Bauche. Mit ihren frommen, schönen Reden verführen sie die Herzen Argloser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Überall ist euer Gehorsam wohlbekannt, und darum freue ich mich über euch. Ich wünsche nur, daß ihr im Guten weise seid, dem Bösen aber gegenüber unverdorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Der Gott des Friedens wird schnell den Satan unter euren Füßen zermalmen. Die Gnade unseres Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timotheus, mein Mitarbeiter, grüßt euch, ebenso meine Landsleute Luzius, Jason und Sosipater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Auch ich, Tertius, der diesen Brief im Herrn geschrieben hat, grüße euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Es grüßt euch Gajus, mein sowie der ganzen Gemeinde Gastgeber. Es grüßt euch Erastus, der Stadtpfleger, sowie der Bruder Quartus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Ihm aber, der es vermag, euch zu bekräftigen in meinem Evangelium sowie in der Predigt Jesu Christi - dadurch ward das Geheimnis ja enthüllt, das von ewigen Zeiten her geheimgehalten war;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'jetzt aber wird es durch Prophetenschriften im Auftrag des ewigen Gottes bei allen Völkern verkündet für den Glaubensgehorsam -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'ihm, dem allein weisen Gott, sei durch Jesus Christus Preis und Ehre von Ewigkeit zu Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, berufen zum Apostel Jesu Christi durch den Willen Gottes, und Sosthenes, der Bruder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'an die Gemeinde Gottes in Korinth. An die, die in Christus Jesus geheiligt und als Heilige berufen sind, samt allen, die den Namen unseres Herrn Jesus Christus anrufen an jedem Orte, bei ihnen und bei uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Ich danke immerwährend meinem Gott um euretwillen wegen der Gnade Gottes, die euch verliehen ward in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Durch ihn seid ihr in allem reich geworden; in jedem Wort und in jeglicher Erkenntnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'So machtvoll ist das Zeugnis Christi unter euch geworden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'daß ihr an keiner Gnadengabe Mangel habt, die ihr auf die Offenbarung unseres Herrn Jesus Christus wartet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Er wird euch bis ans Ende stärken, daß ihr am Tage der Wiederkunft unseres Herrn Jesus Christus ohne Tadel seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Treu ist ja Gott, durch den ihr berufen worden seid zur Gemeinschaft mit seinem Sohne, unserem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Ich ermahne euch, liebe Brüder, im Namen unseres Herrn Jesus Christus: Führt alle dieselbe Sprache und duldet keine Spaltungen bei euch; seid vielmehr einig im gleichen Sinnen und im gleichen Denken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Von den Angehörigen der Chloe ward mir nämlich über euch, meine Brüder, mitgeteilt, daß bei euch Streitigkeiten herrschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ich meine damit dies, daß der eine von euch sagt: \"Ich halte mich an Paulus.\" Ein anderer: \"Ich gehöre zu Apollos!\" Und wieder einer: \"Ich zu Kephas\", oder: \"Ich zu Christus.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ist Christus denn geteilt? Ist etwa Paulus für euch gekreuzigt worden; oder seid ihr auf des Paulus Namen hin getauft?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Gott sei Dank, daß ich niemand aus euch getauft habe als den Krispus und den Gajus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'So kann niemand sagen, daß ihr auf meinen Namen getauft seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Doch, auch das Haus des Stephanas habe ich getauft; sonst wüßte ich aber niemand mehr, den ich getauft hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Christus hat mich nämlich nicht gesandt zu taufen, vielmehr das Evangelium zu predigen, und dies nicht in geschwätziger Weisheit, sonst würde das Kreuz Christi ja seine Kraft verlieren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Das Wort vom Kreuz ist nämlich denen Torheit, die verlorengehen, doch Gotteskraft für uns, die wir gerettet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Steht doch geschrieben: \"Vernichten will ich der Weisen Weisheit und den Verstand Verständiger verwerfen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Wo bleibt der Weise, wo der Schriftgelehrte und wo der Wortfechter dieser Welt? Hat Gott denn nicht die Weisheit der Welt zur Torheit werden lassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Nachdem die Welt Gott in der Weisheit Gottes mit ihrer Weisheit nicht erkannte, hat es Gott gefallen, gerade durch die Torheit der Predigt die, die da glauben wollen, zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Die Juden fordern Wunder, die Griechen suchen Weltweisheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'wir aber verkünden einen Christus, den man gekreuzigt hat: den Juden zwar ein Ärgernis, den Griechen eine Torheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'doch allen, die berufen sind, ob Jude oder Grieche, Christus als Gottes Kraft und Gottes Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Ist doch die Torheit Gottes weiser als die Menschen, die Schwachheit Gottes stärker als die Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Meine lieben Brüder, schaut doch hin, was für Leute unter uns berufen sind. Da gibt es nicht viele, die weise sind im Sinne der Welt, nicht viele Mächtige und Vornehme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Sondern was der Welt als töricht gilt, hat Gott erwählt, um die Weisen zu beschämen; und was die Welt als schwach bezeichnet, hat Gott erwählt, um die Starken zu beschämen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'und was der Welt als niedrig und verächtlich gilt, ja, was ihr gar nichts gilt, hat Gott erwählt, um das, was etwas gilt, zu nichts zu machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'So sollte kein Sterblicher vor Gott sich rühmen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Aus ihm aber habt ihr das Sein in Christus Jesus, der uns von Gott zur Weisheit wurde, zur Rechtfertigung, Heiligung und Erlösung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Es sollte, wie es auch geschrieben steht, \"wer sich rühmen will, im Herrn sich rühmen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Auch ich, meine Brüder, bin, als ich zu euch kam, nicht mit hoher Rede oder mit Weisheit aufgetreten, als ich euch Zeugnis gab von Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Denn ich glaubte, ich dürfte unter euch kein anderes Wissen zeigen als Jesus Christus, und zwar als Gekreuzigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'So kam ich denn zu euch in Schwachheit und in Furcht sowie in großem Zagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Mein Reden und der Inhalt meiner Predigt waren nicht Worte der Überredung voll Menschenweisheit, sondern es waren Beweise von Geist und Kraft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'damit euer Glaube nicht auf Menschenweisheit ruhe, sondern auf Gottes Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Wir künden zwar bei den Vollendeten auch Weisheit, doch nicht die Weisheit dieser Welt, noch die der Mächtigen dieser Welt, die zugrunde gehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Im Gegenteil, wir verkünden als Geheimnis Gottes Weisheit, die zwar verborgen war, die aber Gott vor aller Zeit zu unserer Verherrlichung bestimmt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Keiner der Mächtigen dieser Welt hat sie verstanden, denn wenn sie sie verstanden hätten, hätten sie den Herrn der Herrlichkeit nicht gekreuzigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Gilt doch hier das Schriftwort: \"Was kein Auge gesehen und was kein Ohr gehört und was in keines Menschen Herz gedrungen ist, das hat Gott für die bereitet, die ihn lieben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Gott hat es durch den Geist uns geoffenbart; der Geist ergründet nämlich alles, selbst die Tiefen der Gottheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Wer von den Menschen kennt das Wesen des Menschen, außer der Geist des Menschen, der in seinem Innern ist? Und so erkennt auch niemand das Wesen Gottes, außer der Geist Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Wir aber haben nicht den Geist der Welt empfangen, vielmehr den Geist aus Gott, damit wir erkennen, was uns von Gott in Liebe geschenkt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Und davon reden wir, und zwar nicht in Worten, wie sie Menschenweisheit lehrt, sondern wie der Geist sie eingibt: Geistiges erklären wir den Geisterfüllten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Der naturhafte Mensch nimmt nicht an, was vom Geiste Gottes kommt; als Torheit kommt es ihm vor; er kann es auch nicht begreifen, denn geistig will es verstanden sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Der geisterfüllte Mensch versteht dagegen alles, während er selbst von niemand verstanden wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, '\"Wer hätte auch den Ratschluß des Herrn begriffen, daß er ihn belehren könnte?\" Wir aber haben den Geist Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Meine lieben Brüder! Auch ich konnte zu euch nicht reden wie zu Geisterfüllten, sondern nur wie zu Fleischesmenschen, zu solchen, die noch nicht mündig sind in Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Mit Milch ernährte ich euch und nicht mit fester Speise; denn diese konntet ihr noch nicht ertragen. Allein auch jetzt könnt ihr es noch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Denn ihr seid noch fleischlich. Solange nämlich Eifersucht und Streit sich bei euch finden, seid ihr da nicht noch fleischlich und lebt nach der Art der anderen Menschen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Denn wenn der eine sagt: \"Ich halte mich an Paulus\", ein anderer: \"Ich gehöre zu Apollos\", seid ihr da nicht so recht noch Menschen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Was ist denn Apollos? Was ist denn Paulus? Diener sind sie, die euch zum Glauben verholfen haben, und dies ein jeder so, wie es ihm der Herr verliehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ich habe gepflanzt, Apollos hat es begossen; Gott aber hat das Wachstum gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'So kommt es denn nicht auf den an, der pflanzt, und nicht auf den, der begießt, sondern auf den, der das Gedeihen gibt, auf Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Wer pflanzt und wer begießt, gehört zusammen; ein jeder wird je nach seiner Arbeit seinen Lohn erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Sind wir doch Gottes Mitarbeiter, ihr aber Gottes Ackerland und Gottes Bauwerk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Entsprechend der Gnade Gottes, die mir verliehen ward, legte ich den Grund als kluger Baumeister; ein anderer baut darauf weiter; jeder aber sehe zu, wie er weiterbaue.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Doch einen anderen Grund, als den bereits gelegten, kann niemand legen: Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Ob einer nun auf diesem Grunde mit Gold und Silber oder Edelstein weiterbaut oder mit Holz und Heu und Stroh,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'das wird sich bei dem Bauwerk eines jeden zeigen. Der \"Tag\" wird es offenbaren, weil er sich im Feuer kundgibt. Wie das Bauwerk eines jeden ist, das wird das Feuer erweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Ist das Bauwerk, das einer auferbaute, von Bestand, alsdann empfängt er Lohn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'doch brennt sein Bauwerk nieder, wird er zu Schaden kommen. Er selbst wird zwar gerettet werden, jedoch so wie durch Feuer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Wißt ihr denn nicht, daß ihr Tempel Gottes seid, daß der Geist Gottes in euerm Innern wohnt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Wer den Tempel Gottes zugrunde richtet, den wird Gott auch zugrunde richten; denn heilig ist der Tempel Gottes, und der seid ihr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Daß sich doch keiner täusche! Wer unter euch für diese Welt sich weise dünkt, der werde doch zuerst ein Tor und so erst weise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Die Weisheit dieser Welt gilt ja vor Gott als Torheit; so steht geschrieben: \"Er fängt die Weisen mit ihrer eigenen Schlauheit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Und wieder heißt es: \"Der Herr weiß, daß der Weisen Denken eitel ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'So soll sich also niemand über Menschen rühmen; alles ist ja euer:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Sei es Paulus, sei es Apollos oder Kephas; sei es Welt, sei es Leben oder Tod; sei es Gegenwart oder Zukunft; all das ist euer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Ihr aber gehört Christus an und Christus Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Man halte uns sonach für Diener Christi und für Verwalter der Geheimnisse Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Das Mindeste, was man von den Verwaltern fordert, ist, daß sie treu erfunden werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Ich mache mir sehr wenig daraus, von euch oder von einem menschlichen Gericht mein Urteil zu erhalten; ich richte aber auch mich selber nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Ich bin mir nichts bewußt, jedoch darum noch nicht gerechtfertigt. Der mich richtet, ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'So richtet denn in keiner Weise vor der Zeit, bevor der Herr kommt. Er bringt ans Licht, was im Finstern verborgen ist, und macht die Absichten des Herzens offenbar. Und dann wird jedem sein Lob von Gott zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Dies, liebe Brüder, habe ich auf mich und auf Apollos angewandt um euretwillen. Lernt so an uns den Grundsatz: \"Nicht mehr, als was geschrieben steht.\" So möge keiner sich zugunsten eines anderen und zum Schaden eines dritten überheben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Wer zeichnet dich denn aus? Was hast du, das du nicht empfangen hättest? Wenn du es aber empfangen hast, was rühmst du dich, wie wenn du es nicht empfangen hättest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Ihr seid schon gesättigt. Ihr seid reich geworden. Ihr seid Könige geworden ohne uns. O daß ihr doch schon Könige wäret, dann wären wir es mit euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Ich glaube fast, Gott hat uns, den Aposteln, das letzte Plätzchen angewiesen, als wären wir zum Tode verurteilt. Zum Schauspiel sind wir geworden der Welt, den Engeln und den Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Wir sind um Christi willen Toren, doch ihr gar klug in Christus; wir sind schwach, doch ihr stark; ihr seid geehrt und wir dagegen ehrlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Und bis zu dieser Stunde hungern wir und dürsten, sind entblößt, müssen uns mißhandeln lassen, sind heimatlos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Wir quälen uns mit unserer Hände Arbeit ab; man flucht uns, wir segnen; man verfolgt uns, wir erdulden es;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'man verleumdet uns, wir spenden Trost; gleich wie der Auskehricht der Welt sind wir geworden, wie der Auswurf aller bis zur Stunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ich schreibe euch dies, nicht um euch zu beschämen, sondern um euch zu mahnen als meine vielgeliebten Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Denn hättet ihr auch viele Tausende Erzieher in Christus, so habt ihr doch nicht viele Väter. Ich ward euer Vater in Christus Jesus durch das Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Deshalb ermahne ich euch: Werdet meine Nachahmer wie ich Nachahmer Christi bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Gerade deshalb sende ich euch den Timotheus, mein vielgeliebtes und getreues Kind im Herrn, damit er euch an meine Lehre in Christus erinnere, wie ich sie überall in jeder Gemeinde verkünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Doch einige erheben sich bei euch, als ob ich gar nicht zu euch käme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ich werde aber in aller Bälde zu euch kommen, wenn der Herr es will. Dann möchte ich aber nicht die Worte der Aufgeblasenen kennenlernen, sondern ihre Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Denn das Reich Gottes besteht nicht in Worten, sondern in Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Was wollt ihr? Soll ich mit dem Stock zu euch kommen oder in Liebe und im Geist der Sanftmut?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Überhaupt hört man unter euch von Unzucht, und zwar von solcher, wie sie nicht einmal bei Heiden vorkommt: daß einer mit dem Weibe seines Vaters lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Und dabei überhebt ihr euch noch, anstatt daß ihr vielmehr getrauert hättet, daß der, der diese Tat vollbracht hat, aus eurer Mitte entfernt würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Obwohl ich leiblich von euch fern bin, bin ich dem Geiste nach doch unter euch und bin mit meinem Urteil genau so, wie wenn ich bei euch wäre, schon fertig über den, der solches tat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Ihr und mein Geist sollen sich im Namen unseres Herrn Jesus mit der Kraft unseres Herrn Jesus');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'versammeln, und dann übergebt diesen Menschen dem Satan zum Verderben seines Fleisches, damit sein Geist gerettet werde am Tage des Herrn Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Nicht schön ist es, wie ihr euch selbst rühmt! Wißt ihr denn nicht, daß schon ein wenig Sauerteig den ganzen Teig durchsäuert?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'So schafft den alten Sauerteig fort, dann seid ihr neuer Teig. Ihr seid ja ungesäuert. Ist doch Christus, unser Osterlamm, geschlachtet worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Wir dürfen also nicht mit dem alten Sauerteig feiern, auch nicht mit dem Sauerteig der Bosheit und der Schlechtigkeit, sondern mit dem Ungesäuerten der Lauterkeit und Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'In meinem Briefe habe ich euch geschrieben: Verkehret nicht mit Unzüchtigen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Damit meinte ich nun nicht die Unzüchtigen dieser Welt an sich, die Habsüchtigen, die Räuber oder Götzendiener; sonst müßtet ihr ja diese Welt verlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Jetzt aber schreibe ich euch: Verkehret nicht mit einem, der sich Bruder nennt, doch unzüchtig wäre, oder ein Habsüchtiger, ein Götzendiener, ein Lästerer, ein Trunkenbold, ein Räuber; mit einem solchen pflegt keine Tischgemeinschaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Was hätte ich auch die Außenstehenden zu richten? Sollt ihr denn nicht die richten, die zu uns gehören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Die draußen sind, wird Gott schon richten. Entfernt darum den Bösen aus eurer Mitte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Wagt es wirklich einer unter euch, der einen Rechtsstreit mit einem andern hat, sein Recht bei den Ungerechten zu suchen, und nicht vielmehr bei den Heiligen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Wißt ihr denn nicht, daß die Heiligen die Welt richten werden? Wenn also schon die Welt von euch gerichtet wird, solltet ihr da nicht würdig sein, auch Gerichte über Kleinigkeiten abzuhalten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Wißt ihr denn nicht, daß wir Engel richten werden? Um wieviel mehr denn Vermögensangelegenheiten!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Wenn ihr nun über Vermögensangelegenheiten zu Gericht sitzt, dann bestellt ihr die zu Richtern, die in der Gemeinde am wenigsten Ansehen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Euch zur Beschämung sage ich dies. Gibt es keinen einzigen Weisen unter euch, der zwischen seinen Brüdern als Richter walten könnte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Nein, Bruder geht gegen Bruder vor Gericht, und dies auch noch zu Ungläubigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Überhaupt ist dies schon ein Fehler an euch, daß ihr Streitigkeiten miteinander habt. Warum leidet ihr nicht lieber Unrecht? Warum laßt ihr euch nicht lieber übervorteilen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Doch ihr selber übt ja Unrecht und Übervorteilung, und dies sogar an Brüdern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Wißt ihr denn nicht, daß Ungerechte das Reich Gottes nicht erben werden? Gebt euch keiner Täuschung hin! Unzüchtige, Götzendiener, Ehebrecher, Lüstlinge, Knabenschänder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Diebe, Habsüchtige, Trunkenbolde, Lästerer, Räuber werden keinen Teil am Reiche Gottes haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Und so etwas seid ihr zum Teil gewesen. Doch ihr seid abgewaschen, ihr seid geheiligt, ihr seid gerechtfertigt im Namen unseres Herrn Jesus Christus und im Geist unseres Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Alles ist mir erlaubt, jedoch ist nicht alles von Nutzen; alles ist mir erlaubt, doch ich soll mich von nichts beherrschen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Die Speisen sind für den Magen da, der Magen für die Speisen; doch Gott wird beide einst vernichten. Der Leib dagegen ist nicht für die Unzucht da, sondern für den Herrn, und der Herr für den Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Gott aber, der den Herrn auferweckt hat, wird auch uns durch seine Macht auferwecken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Wißt ihr denn nicht, daß eure Leiber Glieder Christi sind? Soll ich die Glieder Christi also nehmen und sie zu Gliedern einer Hure machen? Nein, nimmermehr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Oder wißt ihr nicht, daß, wer mit einer Hure Umgang hat, ein Leib ist? Es heißt ja: \"Die zwei werden zu einem Fleische werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Wer aber mit dem Herrn Umgang hat, ist ein Geist mit ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Flieht die Unzucht! Denn jede Sünde, die ein Mensch begeht, bleibt außerhalb des Leibes; der Unzüchtige dagegen sündigt an seinem eigenen Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Oder wißt ihr nicht, daß euer Leib ein Tempel des Heiligen Geistes ist, der in euch wohnt, den ihr von Gott empfangen habt, und daß ihr euch nicht mehr selbst angehört?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Um einen Preis seid ihr erkauft. Verherrlicht und traget also Gott in eurem Leibe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Ich komme auf das, weswegen ihr geschrieben habt: Es ist besser für den Mann, sich mit dem Weibe nicht einzulassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Doch wegen der Gefahr der Unzucht soll jeder sein Weib und jedes Weib ihren Mann haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Der Mann soll dem Weibe die eheliche Pflicht leisten und ebenso das Weib dem Manne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Das Weib hat kein Verfügungsrecht mehr über seinen Leib, sondern der Mann; desgleichen hat der Mann auch kein Verfügungsrecht mehr über seinen Leib, sondern das Weib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Verweigert euch einander nicht, außer auf Grund von gegenseitiger Übereinkunft eine Zeitlang, um für das Gebet Zeit zu haben und dann wieder zusammenzuleben, damit euch der Satan nicht versuche wegen eures Mangels an Selbstbeherrschung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Ich sage dies nur ab Zugeständnis, nicht als Gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Ich wollte aber, alle Menschen wären so wie ich; indes hat jeder von Gott seine eigene Gabe, der eine so, der andere anders.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Den Ledigen und Witwen sage ich: Viel besser ist es für sie, wenn sie so bleiben wie ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Doch können sie sich nicht enthalten, so sollen sie heiraten. Denn besser ist heiraten als brennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Den Verehelichten aber befehle ich, das heißt nicht ich, es ist der Herr: Das Weib darf sich vom Manne nicht trennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Sollte es sich aber dennoch trennen, so muß es unverehelicht bleiben oder sich wiederum mit seinem Manne versöhnen. Und auch der Mann darf sein Weib nicht entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Den übrigen sage ich, nicht der Herr: Hat ein Bruder ein ungläubiges Weib und dieses will mit ihm noch weiterleben, so soll er es nicht entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Und hat ein gläubiges Weib einen ungläubigen Mann und dieser will mit ihm noch weiterleben, so soll sie den Mann nicht entlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Geheiligt wird der ungläubige Mann im Weib und das ungläubige Weib wird im Bruder heilig; sonst wären ja auch eure Kinder unrein, so aber sind sie heilig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Will aber der ungläubige Teil sich scheiden lassen, so mag er es tun; ein Bruder oder eine Schwester ist in solchen Fällen nicht gebunden; vielmehr hat Gott euch zum Frieden berufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Denn weißt du wirklich, Weib, ob du deinen Mann retten wirst? Mann, weißt du denn, ob du dein Weib retten wirst?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Jeder lebe so, wie der Herr es ihm verliehen, wie Gott ihn berufen hat. Diese Weisung gebe ich überall in den Gemeinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Ward einer als Beschnittener berufen, so suche er dies nicht zu verbergen; ward er als Unbeschnittener berufen, dann lasse er sich nicht beschneiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Es kommt nicht darauf an, ob man beschnitten sei, und nicht darauf, ob man unbeschnitten sei, vielmehr ob man die Gebote Gottes halte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ein jeder bleibe in dem Stande, in dem er berufen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Du wurdest vielleicht als Sklave berufen? Das soll dir keine Sorge machen. Selbst wenn du frei werden kannst, bleibe erst recht dabei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Ein Sklave, der im Herrn berufen ist, ist ja ein Freigelassener des Herrn, so wie auch, wer als Freier berufen ward, ein Sklave Christi ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Um einen Preis seid ihr erkauft. Werdet nicht zu Menschensklaven!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Meine Brüder! Jeder soll vor Gott in dem Stande verbleiben, in dem er berufen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Was dann die Jungfrauen betrifft, so habe ich kein Gebot vom Herrn; doch einen Rat will ich erteilen als einer, der durch die Gnade des Herrn als zuverlässig erwiesen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Ich meine nun, der gegenwärtigen Bedrängnis wegen sei es gut, daß sie so bleiben; wie es auch für jeden anderen gut ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Du bist an eine Frau gebunden? Suche keine Lösung! Du bist ledig? Suche keine Frau!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Doch wenn du dennoch heiratest, sündigst du nicht. Auch wenn die Jungfrau heiratet, sündigt sie nicht. Doch werden solche irdische Bedrängnis haben, und davor möchte ich euch bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Doch das, Brüder, muß ich sagen: Die Zeit ist kurz bemessen. Daß doch künftighin Verheiratete so leben, als wären sie nicht verheiratet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'die Weinenden, als weinten sie nicht, die Fröhlichen, als wären sie nicht fröhlich, die Kaufenden, als behielten sie nichts,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'und die mit der Welt verkehren, als hätten sie nichts davon; denn die Gestalt dieser Welt vergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Ich möchte aber, daß ihr ohne Sorgen seid. Wer ledig ist, sorgt für die Sache des Herrn: er möchte gern dem Herrn gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Doch der Verehelichte sorgt sich um Weltliches: er möchte gern dem Weib gefallen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'er ist geteilt. Die unverheiratete Frau und die Jungfrau sorgt sich um die Sache des Herrn: daß sie an Leib und Seele heilig sei; doch die Verheiratete sorgt sich ab um Weltliches: sie möchte gern dem Mann gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Das sage ich aber nur zu eurem eigenen Nutzen, nicht, um euch eine Schlinge überzuwerfen, sondern damit ihr wohlanständig und beharrlich, ohne Ablenkung beim Herrn aushaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Wenn aber einer an seiner Jungfrau ungeziemend zu handeln glaubt, wenn diese über ihrer Reife ist, und es kommt so zu einem Muß, dann tue er, was er mag; er sündigt nicht; sie mögen heiraten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Doch wer in seinem Innern gefestigt ist und keinerlei Notwendigkeit zu folgen braucht und Gewalt über seine Begierlichkeit hat, wenn nun ein solcher sich in seinem Inneren dafür entschieden hat, seine Jungfrau zu behalten, der tut wohl daran.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Wer also seine Jungfrau verheiratet, der handelt gut; doch wer sie nicht verheiratet, der handelt besser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Das Weib ist gebunden, solange sein Mann noch lebt; ist nun sein Mann entschlafen, dann ist es frei und kann heiraten, wen es will; es soll jedoch im Herrn geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Sie ist indessen seliger, wenn sie so bleibt. Dies ist zwar nur meine eigene Meinung; ich glaube jedoch, auch den Geist Gottes zu haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Was weiter das Götzenopferfleisch betrifft, so nehme ich an, wir alle wissen, um was es sich handelt. - Die Erkenntnis bläht auf; die Liebe aber erbaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Wenn einer meint, etwas erkannt zu haben, so weiß er doch noch lange nicht, wie man erkennen muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Wenn aber einer Gott liebt, so ist er von ihm erkannt. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Was also den Genuß von Götzenopferfleisch betrifft, so wissen wir, es gibt keine Götzen in der Welt, und es ist kein Gott, als allein der Eine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Mag es auch im Himmel oder auf Erden sogenannte Götter geben - es gibt ja so viele Götter und so viele Herren -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'für uns gibt es doch nur einen Gott, den Vater, aus dem alles ist, für den wir sind, und einen Herrn, Jesus Christus, durch den alles ist und durch den auch wir sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Allein nicht alle haben die Erkenntnis; manche essen noch mit ihrer alten Göttervorstellung das Fleisch als Götzenopferfleisch, und ihr Gewissen, schwach wie es ist, wird befleckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'An sich stellt uns die Speise nicht vor den Richterstuhl Gottes: Wir gelten um nichts weniger, wenn wir nicht essen, und um nichts mehr, wenn wir essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Doch seht zu, daß diese eure Freiheit den Schwachen nicht zum Anstoß werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Denn sieht dich, der du Erkenntnis hast, einer an einem Tempelmahl teilnehmen, wird sein Gewissen, weil es schwach ist, nicht dadurch \"auferbaut werden\", nun Götzenopferfleisch als solches zu genießen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'So kommt der Schwache durch dein Wissen ins Verderben, der Bruder, für den Christus gestorben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Wenn ihr in dieser Weise an den Brüdern euch versündigt und so ihr schwaches Gewissen verletzt, dann sündigt ihr gegen Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Gibt darum eine Speise meinem Bruder Ärgernis, so wollte ich lieber in Ewigkeit kein Fleisch mehr essen, nur, um nicht meinem Bruder Ärgernis zu geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Bin ich nicht frei? Bin ich denn nicht Apostel? Habe ich nicht unseren Herrn Jesus gesehen? Seid denn nicht ihr mein Werk im Herrn?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Wenn ich für andere nicht Apostel bin, so bin ich es doch mindestens für euch. Ihr seid das Siegel meines Amtes als Apostel im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Meine Antwort meinen Tadlern gegenüber lautet so:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Haben wir denn nicht das Recht, zu essen und zu trinken?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Haben wir nicht das Recht, eine Schwester als Frau mitzunehmen wie die anderen Apostel, die Brüder des Herrn und selbst Kephas?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Oder haben ich und Barnabas allein kein Recht, die Handarbeit ganz aufzugeben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Wer leistet denn Kriegsdienst auf eigene Kosten? Wer pflanzte einen Weinberg und wollte nicht von seinem Ertrag essen? Oder wer weidet eine Herde und genießt nicht von der Milch der Herde?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Ist es nur Menschenmeinung, was ich da behaupte, oder lehrt denn das Gesetz nichts hierüber?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Im Gesetze Moses heißt es: \"Du sollst dem Ochsen beim Dreschen das Maul nicht verbinden\". Kümmert denn Gott sich um Ochsen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Oder sagt er das nicht gerade unsererwegen? Ja, unseretwegen ward es aufgeschrieben: Der Pflügende muß auf Hoffnung pflügen und in der Hoffnung auf den Anteil auch der Drescher seine Arbeit tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Wenn wir bei euch nun Geistiges gesät haben, ist es dann etwas Besonderes, wenn wir bei euch Irdisches ernten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Wenn anderen schon ein Recht auf euch zusteht, so doch ganz sicher uns noch mehr. Doch machen wir von diesem Rechte nicht einmal Gebrauch; wir nehmen vielmehr alles ganz auf uns, um dem Evangelium Christi ja kein Hindernis zu bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Wißt ihr denn nicht, daß, wer den heiligen Dienst verrichtet, auch vom Heiligtum essen darf? Daß, wer an dem Altare dient, auch am Altar Anteil haben darf?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'So hat es auch der Herr geboten, daß, wer das Evangelium verkündet, vom Evangelium auch leben soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Von keinem dieser Rechte habe ich indes Gebrauch gemacht. Ich schreibe dies nun nicht, damit es in Zukunft so mit mir gehalten werde; nein, lieber sterben, als... Meinen Ruhm soll mir keiner schmälern!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Wenn ich das Evangelium nur verkünde, ist dies kein Ruhm für mich; es liegt dies ja als Muß auf mir. Weh mir, wenn ich das Evangelium nicht verkünden wollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Tu ich es aber aus freiem Willen, dann habe ich ein Verdienst; wenn unfreiwillig, dann bin ich eben nur mit der Verwaltung eines Amtes betraut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Wovon hängt mein Verdienst ab? Davon, daß ich das Evangelium ohne Unterhaltsanspruch verkünde, so daß ich von meinem Anspruch an das Evangelium keinen Gebrauch mache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Obwohl in jeder Hinsicht frei, machte ich mich doch zum Sklaven aller, um so recht viele zu gewinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Den Juden ward ich wie ein Jude, um so die Juden zu gewinnen; für die, die unter dem Gesetze stehen, ward ich wie einer, der selber unter dem Gesetze steht, obwohl ich selbst nicht unter dem Gesetze stehe, um so die zu gewinnen, die unter dem Gesetze stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Für die, die vom Gesetze frei sind, ward ich wie einer, der vom Gesetze frei ist - natürlich nicht frei vom Gesetze Gottes, vielmehr an das Gesetz Christi gebunden -, um so die zu gewinnen, die nicht unter dem Gesetze stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Den Schwachen ward ich schwach, um die Schwachen zu gewinnen: So ward ich allen alles, um überhaupt nur einige zu retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Das alles aber tue ich des Evangeliums wegen, um teil daran zu haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Wißt ihr denn wirklich nicht, daß zwar alle Wettläufer in der Rennbahn laufen, jedoch nur ein einziger den Siegespreis erhält? Lauft so, daß ihr ihn erhaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Jeder Kämpfer ist in allem enthaltsam, jene, um einen vergänglichen Kranz zu erhalten, wir aber einen unvergänglichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ich laufe also, aber nicht ins Ungewisse; ich führe Fausthiebe, jedoch nicht in die Luft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'sondern ich züchtige meinen Leib und unterwerfe ihn, damit ich nicht selbst einst unbewährt erfunden werde, nachdem ich anderen gepredigt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ich möchte nämlich, meine Brüder, daß ihr wohl beachtet, daß alle unsere Väter unter der Wolke waren, alle durch das Meer hindurchgingen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'alle die Taufe auf Moses hin empfingen in der Wolke und im Meer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'alle auch die gleiche geistige Speise aßen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'alle auch denselben geistigen Trank genossen - sie tranken nämlich aus dem geistigen Felsen, der ihnen folgte; der Fels aber war Christus -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'doch an den meisten unter ihnen hatte Gott kein Wohlgefallen; und so wurden sie in der Wüste hingestreckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Das sind nun Vorbilder für uns, damit es uns nicht nach Bösem gelüste, wie es jene einst gelüstete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Werdet auch nicht Götzendiener, wie manche aus ihnen, wie geschrieben steht: \"Das Volk ließ sich nieder, um zu essen und zu trinken, und es erhob sich wieder, um zu tanzen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Wir wollen auch keine Unzucht treiben, wie es manche aus ihnen trieben, so daß an einem Tage dreiundzwanzigtausend fielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Auch wollen wir den Herrn nicht versuchen, wie manche aus ihnen ihn versuchten und dann durch Schlangen starben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Murrt auch nicht, wie so manche unter ihnen murrten, die von dem Würgengel weggerafft wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Dies alles ist jenen widerfahren als ein Vorbild; doch aufgeschrieben ward es uns zur Warnung, die wir das Ende der Zeiten erleben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Deshalb, wer zu stehen meint, der sehe zu, daß er nicht falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nur eine menschliche Versuchung hat euch jetzt gepackt; Gott aber ist getreu: Er wird nicht zulassen, daß ihr über eure Kräfte versucht werdet, vielmehr mit der Versuchung auch den guten Ausgang geben, so daß ihr es ertragen könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'So fliehet denn, Geliebteste, den Götzendienst!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Ich rede, wie man mit verständigen Menschen redet; beurteilt selber, was ich sage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Ist denn der Kelch der Segnung, den wir segnen, nicht Gemeinschaft mit dem Blute Christi? Und ist das Brot, das wir brechen, nicht Gemeinschaft mit dem Leibe Christi?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Weil nur ein Brot ist, so sind wir viele ein Leib; denn wir alle nehmen an dem einen Brote teil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Seht hin auf Israel dem Fleische nach! Haben die, die vom Opfer essen, nicht mit dem Altare Gemeinschaft?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Was will ich denn nun damit sagen? Vielleicht, daß ein Götzenopfer etwas sei? Oder daß solch ein Götze etwas sei?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Gewiß nicht! Wohl aber, daß das, was die Heiden opfern, den Dämonen und nicht Gott geopfert wird. Ich will nun aber nicht, daß ihr mit den Dämonen in Gemeinschaft tretet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ihr könnt nicht den Kelch des Herrn trinken und zugleich den Kelch der Dämonen. Ihr könnt nicht am Tische des Herrn teilhaben und zugleich am Tische der Dämonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Oder wollen wir den Herrn herausfordern? Sind wir denn mächtiger als er?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Alles ist erlaubt; doch es nützt nicht alles; alles ist erlaubt; doch nicht alles ist erbaulich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Niemand suche sein eigenes Wohl, vielmehr das Wohl des Nächsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Alles, was auf dem Markte verkauft wird, esset es, ohne des Gewissens wegen nachzufragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, '\"Dem Herrn gehört ja die Erde und das, was sie erfüllt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Wenn nun ein Ungläubiger euch zu Tische bittet, und ihr möchtet gern dorthin gehen, so eßt alles, was euch vorgesetzt wird, ohne des Gewissens wegen nachzufragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Sagt aber einer zu euch: \"Es ist Götzenopferfleisch.\" Dann eßt es nicht, und zwar um dessentwillen, der euch gewarnt hat und um des Gewissens willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Ich meine aber nicht das eigene Gewissen, sondern das des anderen. Warum soll ich aber meine Freiheit von dem Gewissen eines anderen richten lassen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Wenn ich mit Dank teilnehme, warum soll ich mich schmähen lassen wegen etwas, wofür ich Dank sage?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ihr möget essen oder trinken oder irgend etwas anderes tun - tut alles zur Ehre Gottes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Erregt keinen Anstoß weder bei Juden noch bei Heiden noch in der Kirche Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'wie auch ich in allen Stücken euch allen zu Gefallen bin und in keiner Weise meinen eigenen Vorteil suche, sondern den Vorteil der vielen, damit sie Rettung finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Folgt meinem Beispiel, wie ich dem Beispiel Christi folge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Ich finde es lobenswert an euch, daß ihr in allem an mich denkt und an den Vorschriften festhaltet, wie ich sie euch gegeben habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Ihr sollt indes wissen, daß Christus das Haupt jeden Mannes ist, des Weibes Haupt der Mann, Gott aber das Haupt Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Jeder Mann, der betet oder prophezeit und dabei etwas auf dem Haupte trägt, entehrt sein Haupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Jedes Weib, das betet oder prophezeit und dabei unverhüllten Hauptes ist, entehrt sein Haupt; es ist ja dann geradeso wie eine kahl Geschorene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Wenn ein Weib sich nicht verhüllen will, so lasse sie sich doch die Haare ganz scheren. Ist es aber für das Weib schimpflich, sich die Haare abschneiden oder ganz abscheren zu lassen, dann möge sie sich verhüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Der Mann braucht sein Haupt nicht zu verhüllen, weil er Abbild und Abglanz Gottes ist. Das Weib jedoch ist ein Abglanz des Mannes;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'denn der Mann stammt nicht vom Weibe ab, sondern das Weib vom Manne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Auch wurde nicht der Mann dem Weibe zulieb geschaffen, sondern das Weib dem Manne zulieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Darum muß das Weib einen Schleier auf dem Haupte tragen, um der Engel willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Sonst aber ist das Weib im Herrn nichts ohne seinen Mann, noch der Mann etwas ohne Weib;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'denn wie das Weib vom Manne stammt, so stammt ja auch der Mann vom Weibe; und schließlich kommt alles von Gott her.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Urteilt doch selber: Ist es wirklich passend für ein Weib, unverhüllt zu Gott zu beten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Lehrt euch denn nicht schon die Natur, daß es für den Mann eine Unehre ist, wenn er sein Haar lang trägt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'dagegen für das Weib ein langes Haar als Zierde gilt? Das Haar ward ihr als Schleier verliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Will aber einer durchaus recht behalten, so wißt: Wir kennen eine solche Sitte nicht, und die Gemeinden Gottes auch nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Bei folgender Ermahnung kann ich euch nicht loben; ihr kommt ja nicht zur Besserung, sondern zur Verschlechterung zusammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Fürs erste muß ich hören, daß, wenn ihr euch als Gemeinde versammelt, Spaltungen bei euch zutage treten. Und zum Teil möchte ich es glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Es muß ja bei euch auch Spaltungen geben, damit die Erprobten unter euch sich offenbaren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Wenn ihr also zusammenkommt, so heißt das nimmermehr das Herrenmahl feiern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Jeder nimmt beim Essen sein eigenes Mahl vorweg; der eine ist dann hungrig, der andere betrunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Habt ihr denn keine Häuser zum Essen und Trinken? Oder verachtet ihr die Kirche Gottes, macht ihr die Mittellosen schamrot? Was soll ich euch sagen? Soll ich euch gar noch loben? In diesem Punkte kann ich euch nicht loben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Vom Herrn nämlich habe ich empfangen, was ich euch auch überliefert habe: In jener Nacht, da er verraten ward, nahm der Herr Jesus Brot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'dankte, brach es und sprach: \"Das ist mein Leib, der für euch hingegeben wird; dies tut zu meinem Andenken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Desgleichen nahm er nach dem Mahl auch den Kelch und sprach: \"Dieser Kelch ist der Neue Bund in meinem Blute; tut dies, sooft ihr trinket, zu meinem Andenken!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Sooft ihr dieses Brot esset und aus dem Kelche trinket, verkündet ihr den Tod des Herrn, bis er wiederkommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Wer deshalb unwürdig das Brot ißt oder den Kelch des Herrn trinkt, vergeht sich am Leib und Blut des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'So prüfe man sich also selbst und esse dann von dem Brot und trinke aus dem Kelch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Denn wer nur ißt und trinkt, der ißt und trinkt ein Strafgericht in sich hinein, weil er den Leib nicht richtig einschätzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Darum sind bei euch so viele schwach und krank, und viele sind auch schon entschlafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Wenn wir uns selber richtig beurteilten, dann würden wir nicht gerichtet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Wenn wir jedoch vom Herrn gerichtet werden, dann werden wir gezüchtigt, damit wir nicht mit der Welt verdammt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Wenn ihr also zum Essen zusammenkommt, meine Brüder, so wartet aufeinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Hat einer Hunger, dann esse er zu Hause, damit eure Zusammenkunft euch kein Strafgericht einbringe. Das andere will ich anordnen, wenn ich komme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Was sodann die Geistesgaben betrifft, meine lieben Brüder, so will ich euch nicht im unklaren lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Ihr wißt: Solange ihr noch Heiden waret, da ließt ihr euch zu den stummen Götzen führen, sooft man euch eben führte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'So tue ich euch kund, daß keiner, der im Geiste Gottes redet, sagt: \"Verflucht sei Jesus!\" Es kann auch keiner sagen: \"Der Herr ist Jesus\", außer im Heiligen Geiste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Es gibt verschiedene Zuteilungen von Geistesgaben, doch nur einen Geist;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'es gibt verschiedene Dienste, doch nur einen Herrn;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'es gibt verschiedene Wirkungen, jedoch nur einen Gott, der alles in allen wirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Die Offenbarung des Geistes wird einem jeden zum Nutzen verliehen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Dem einen nämlich wird das Wort der Weisheit durch den Geist verliehen, dem anderen das Wort der Erkenntnis in eben diesem Geiste,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'und wieder einem anderen der Glaube in demselben Geiste, noch einem anderen die Heilungsgabe in dem einen Geiste,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'und einem weiteren die Wirkungen der Kräfte; die Prophezeiungsgabe diesem und dem die Geisterunterscheidungsgabe, und dem die Sprachengabe, und dem die Auslegung der Sprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Das alles aber wirkt der eine und derselbe Geist, der einem jeden seine Gaben zuteilt, wie er will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Wie der Leib zwar nur einer ist und dennoch viele Glieder hat und alle Glieder des Leibes, soviel es deren sind, nur einen Leib ausmachen, so ist es auch mit Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'In einem Geiste sind wir alle zu einem Leibe getauft, ob wir nun Juden oder Heiden sind, ob Sklaven oder Freie. Wir alle sind mit einem Geiste getränkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Besteht doch auch der Leib nicht nur aus einem Gliede, vielmehr aus vielen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Und spräche auch der Fuß: \"Weil ich nicht Hand bin, so gehöre ich nicht zum Leibe\", würde er deshalb nicht zum Leibe gehören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Und spräche auch das Ohr: \"Weil ich nicht Auge bin, gehöre ich nicht zum Leibe\", würde es deshalb nicht zum Leibe gehören?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Und wenn der ganze Leib nur Auge wäre, wo bliebe das Gehör? Und wäre der ganze Leib nur Ohr, wo bliebe der Geruch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Nun aber hat Gott einem jeden Glied am Leibe seinen Platz gegeben, so, wie er wollte;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'wäre aber alles nur ein einziges Glied, wo bliebe dann der Leib?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'So gibt es also viele Glieder, doch nur einen Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Das Auge darf nicht zur Hand sagen: \"Ich brauche dich nicht.\" Und der Kopf nicht zu den Füßen: \"Ich brauche euch nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Im Gegenteil, die scheinbar schwächeren Glieder des Leibes sind notwendig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'und das, was wir am Leib für weniger ehrbar halten, umgeben wir mit größerer Ehre; die unanständigen Teile werden ja mit größerem Anstande behütet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'was die anständigen nicht brauchen. Gott aber hat den Leib so eingerichtet, daß er den Gliedern, die für geringer gelten, nur um so größere Ehre zuerteilte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'damit sich keine Spaltung im Leib ergebe, vielmehr die Glieder füreinander in Eintracht Sorge tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Leidet ein Glied, so leiden alle Glieder mit, und wird ein Glied geehrt, so freuen sich alle Glieder mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Ihr seid nun Christi Leib und Glieder, wenn als Teile angesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Die einen in der Kirche bestimmte Gott fürs erste zu Aposteln, und andere zu Propheten, zu Lehrern dritte und weitere zu Wundertaten und andere zu Heilungsgaben, zu Hilfeleistungen, Verwaltungen und für verschiedene Sprachenarten und Auslegung der Sprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Sind etwa alle Apostel? Sind alle Propheten? Sind alle Lehrer? Sind alle Wundertäter?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Haben alle die Heilungsgabe? Reden alle in Zungen? Legen alle etwa aus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Erstrebt aber immerhin die höchsten Geistesgaben! Indes, ich will euch einen weit besseren Weg zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Wenn ich mit Menschen-, ja mit Engelszungen redete, doch hätte ich die Liebe nicht, dann wäre ich nur ein tönendes Erz, nur leeres Klingeln einer Schelle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Hätte ich Prophetengabe, ja, wüßte ich alle Geheimnisse, besäße ich alle Erkenntnis, hätte ich allen Glauben, um Berge zu versetzen, doch hätte ich die Liebe nicht, dann wäre ich ein Nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Gäbe ich mein ganzes Gut dahin und meinen Leib zum Verbrennen, doch hätte ich die Liebe nicht, es würde mir nichts nutzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Die Liebe ist langmütig, die Liebe ist gütig; sie ist nicht eifersüchtig, die Liebe ist nicht prahlerisch; sie ist nicht aufgeblasen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'nicht unanständig; sie sucht nicht den eigenen Vorteil; sie läßt sich nicht erbittern, sie rechnet nicht mit dem Bösen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'sie frohlockt nicht über das Unrecht; sie freut sich aber über die Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Sie erträgt alles, glaubt alles, hofft alles, übersteht alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Die Liebe hört nimmer auf. Prophetengaben nehmen ein Ende, Sprachen werden aufhören, Erkenntnis wird vergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Unsere Erkenntnis ist ja Stückwerk, und Stückwerk unser Prophezeien;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'kommt aber das Vollendete, dann hört das Stückwerk auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Als ich noch ein Kind war, da redete ich wie ein Kind, dachte wie ein Kind, urteilte wie ein Kind. Doch als ich Mann geworden war, da habe ich, was kindisch, abgelegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Wir schauen jetzt im Spiegel rätselhaft; dann aber von Angesicht zu Angesicht. Jetzt erkenne ich bruchstückweise, dann aber werde ich klar erkennen, wie auch ich bin erkannt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Jetzt bleiben Glaube, Hoffnung, Liebe: diese drei; das Größte aber unter ihnen ist die Liebe. Trachtet nach der Liebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Habt eifriges Verlangen nach den Geistesgaben, vor allem, daß ihr prophezeien könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Denn wer in einer Sprache redet, spricht nicht für Menschen, sondern für Gott; ihn versteht ja niemand, weil er geheimnisvoll im Geiste redet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Wer aber prophezeit, spricht für Menschen Worte der Ermahnung, der Erbauung und des Trostes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Wer in einer Sprache redet, erbaut sich selbst; wer aber prophezeit, erbaut die Gemeinde Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Ich wollte, daß ihr insgesamt in Sprachen reden könntet, mehr aber, daß ihr prophezeit. Wer prophezeit, steht nämlich höher, als wer in Sprachen redet, es sei denn, daß er auch die Auslegung noch gebe, damit die Gemeinde erbaut werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Meine Brüder, was würde es euch nützen, wenn ich zu euch käme und in Sprachen reden wollte, wenn ich nicht zugleich zu euch auch redete in Offenbarung oder in Erkenntnis, in Prophezeiung oder Lehre?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Wenn unbeseelte Instrumente, wie Flöte oder Laute, nur klingen, aber keine Töne unterscheiden ließen, wie soll man da erkennen, was auf der Flöte oder auf der Laute gespielt wird?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Wenn die Trompete nur undeutlich klingt, wer wird zum Kampf antreten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'So ist es auch mit der Sprachengabe: Ist eure Rede, die ihr vorbringt, nicht verständlich, wie soll man dann verstehen, was gesprochen wird? Ihr würdet ja in den Wind reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Es gibt wer weiß wie viele Sprachen in der Welt; nichts ist ja ohne Sprache');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'doch kenne ich den Sinn der Sprache nicht, so bleibe ich für den, der spricht, ein Fremdling, und mir erscheint der Sprechende gleichfalls als Fremdling.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'So sollt auch ihr, die ihr so sehr euch Gnadengaben wünscht, doch danach trachten, in reicher Fülle solche zu besitzen, die zur Erbauung der Gemeinde dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'So möge denn, wer in einer Sprache redet, auch um das Auslegen der Sprache bitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Wenn ich in einer Sprache bete, so betet zwar mein Geist; doch bleibt mein Verstand ohne Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Was folgt daraus? Ich will zwar im Geiste beten; doch will ich auch mit dem Verstande beten, und mit dem Geiste will ich lobsingen, doch will ich auch mit dem Verstande lobsingen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Und wenn du bloß im Geiste dankst, wie soll denn der, der die Stellung eines Nichtchristen einnimmt, zu deiner Danksagung das \"Amen\" sprechen? Er versteht ja gar nicht, was du sagst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Dein Dankgebet mag ganz vortrefflich sein, doch der andere wird nicht erbaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Gott sei Dank! Die Sprachengabe habe ich besser als ihr alle;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'doch will ich lieber in der Gemeinde mit meinem Verstand fünf Worte reden, um andere zu belehren, als zehntausend Worte in einer Sprache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Brüder! Seid doch keine Kinder an Verständnis, wohl aber Kinder an Bosheit, Erwachsene jedoch an Verständnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Im Gesetze steht geschrieben: \"In fremden Sprachen und in fremden Lippen will ich zu diesem Volke reden; doch werden sie auch so nicht auf mich hören, spricht der Herr.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'So ist die Sprachengabe auch kein Zeichen für die Gläubigen, sondern für die Ungläubigen. Die Prophezeiung aber ist nicht für die Ungläubigen, sondern für die Gläubigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Wenn die Gemeinde sich versammelt und alle in Sprachen reden und es kommen dann Nichtchristen oder Ungläubige herein, werden diese dann nicht sagen: \"Ihr seid verrückt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Wenn aber alle prophezeien und tritt dann ein Ungläubiger oder Nichtchrist herein, so wird ihm von allen ins Gewissen geredet; von allen wird er auch überführt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Das Verborgene seines Herzens wird geoffenbart; er fällt dann auf sein Antlitz nieder und betet Gott an und bekennt: \"Wahrlich, Gott ist in euch.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Was folgt daraus, meine lieben Brüder? Wenn ihr zusammenkommt, mag jeder von euch einen Lobgesang besitzen, eine Lehre, eine Offenbarung, eine Sprache sowie eine Auslegung; doch alles soll zur Erbauung dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Wenn man in Sprachen redet, so sollen es nur zwei tun oder höchstens drei, und diese nacheinander, und einer soll die Auslegung geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ist aber keiner da, der auslegt, so schweige er in der Versammlung. Er mag dann zu Hause und mit Gott reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Propheten sollen nur zwei oder drei reden; die anderen sollen prüfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Wird aber einem anderen, der noch dasitzt, eine Offenbarung zuteil, so soll der erstere schweigen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'ihr könnt ja alle miteinander prophezeien, damit alle lernen und alle belehrt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Prophetengeister haben sich den Propheten zu fügen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'denn Gott ist nicht für Unordnung, sondern für den Frieden. Wie in allen Gemeinden der Heiligen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'sollen die Frauen in der Versammlung schweigen. Es steht ihnen nicht zu, zu reden, vielmehr sich unterzuordnen; so steht es ja auch im Gesetze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Doch wenn sie etwas lernen wollen, sollen sie zu Hause ihre Männer fragen; es paßt sich nicht für eine Frau, in den Versammlungen zu reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Oder ging wohl von euch das Gotteswort hinaus, oder kam es zu euch allein?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Wenn einer meint, er sei ein Prophet oder sonst ein Geistbegabter, so soll er anerkennen, daß das, was ich euch schreibe, ein Gebot des Herrn ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Erkennt er dies nicht an, so soll auch er nicht anerkannt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'So trachtet denn, meine Brüder, nach der Prophetengabe; doch hindert nicht das Sprachenreden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Alles aber möge mit Anstand und Ordnung geschehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Meine Brüder! Ich mache euch das Evangelium kund, das ich euch verkündet habe. Ihr habt es angenommen; ihr steht fest in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'In ihm liegt euer Heil, wenn ihr es festhaltet, wie ich es euch verkündet habe; ihr hättet sonst den Glauben ja vergeblich angenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Vor allem habe ich euch überliefert, was auch ich empfangen habe, daß nämlich Christus, der Schrift entsprechend, für unsere Sünden gestorben ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'daß er begraben wurde und daß er, der Schrift entsprechend, am dritten Tage auferweckt ward,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'daß er dann dem Kephas erschien und darauf den Zwölfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Sodann erschien er mehr als fünfhundert Brüdern zugleich, von denen noch die meisten leben bis auf den heutigen Tag; nur einige sind schon entschlafen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Alsdann erschien er dem Jakobus, darauf allen Aposteln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Zu allerletzt erschien er dann auch mir, gewissermaßen wie einer Fehlgeburt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'ich bin ja der geringste der Apostel nicht wert, Apostel zu heißen, weil ich die Kirche Gottes verfolgt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Doch durch die Gnade Gottes bin ich, was ich bin, und seine mir verliehene Gnade ist nicht unwirksam geworden. Im Gegenteil, ich habe mehr gearbeitet als alle diese, das heißt nicht ich, vielmehr die Gnade Gottes in mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Sei es also ich oder seien es jene, so predigen wir, und so habt ihr es auch geglaubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Wenn aber nun gepredigt wird, daß Christus von den Toten auferweckt ward, wie können dann einige unter euch sagen: \"Es gibt gar keine Auferstehung der Toten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Gibt es keine Auferstehung der Toten, so ward auch Christus nicht erweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Ward aber Christus nicht erweckt, dann ist unsere Predigt ohne Inhalt, ohne Inhalt ist dann auch euer Glaube.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Dann stehen wir sogar als falsche Zeugen über Gott da, weil wir es wider Gott bezeugt haben, er habe Christus auferweckt, den er nicht auferweckt haben kann, wenn die Toten wirklich nicht auferweckt würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Wenn nämlich Tote nicht erweckt werden, dann ward auch Christus nicht erweckt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'ward aber Christus nicht erweckt, dann ist euer Glaube nichtig, und ihr seid noch in euren Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Dann sind auch die verloren, die in Christus schon entschlafen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Wenn wir nur für dieses Leben auf Christus hoffen dürften, dann wären wir die beklagenswertesten unter allen Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Nun wurde aber Christus von den Toten auferweckt, und zwar als Erstling der Entschlafenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Weil ja der Tod durch einen Menschen kam, so kam durch einen Menschen auch die Auferstehung der Toten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Denn wie in Adam alle sterben, so werden in Christus alle auch das Leben haben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'ein jeder, wenn die Reihe an ihm ist: Christus ist der Erstling; dann die, die Christus bei seiner Ankunft angehören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Dann kommt der Rest, wenn er das Reich Gott und dem Vater übergibt, nachdem er alle Herrschaft, Gewalt und Macht vernichtet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Denn er muß herrschen, \"bis er alle Feinde unter seine Füße gelegt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Als letzter Feind wird dann der Tod vernichtet:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, '\"denn alles hat er unter seine Füße gelegt.\". Und wenn er sagt: \"Alles ist unterworfen\", so ist doch offenbar der ausgenommen, der ihm alles unterworfen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Ist ihm alles unter unterworfen, dann wird auch der Sohn sich selbst dem unterwerfen, der ihm alles unterworfen hat, auf daß Gott alles in allem sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Was wollen die denn tun, die sich für die Toten taufen lassen? Wenn Tote überhaupt nicht auferweckt werden, wozu dann lassen sie für sie sich taufen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Wozu setzen wir uns zu jeder Stunde Gefahren aus?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Ich schwebe Tag für Tag in Todesgefahr, so wahr ihr, meine Brüder, mein Ruhmestitel seid, den ich in Christus Jesus, unserem Herrn, besitze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Wenn ich in Ephesus nur als ein Mensch mit wilden Tieren einen Kampf bestanden hätte, was würde es mir nützen? Ja, wenn die Toten nicht erweckt werden, dann \"laßt uns essen und trinken; denn morgen sind wir tot.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Täuscht euch nicht! Schlechter Umgang ist verderblich für gute Sitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Kehrt aufrichtig zur Besinnung wieder und sündigt nicht; denn einige haben keine Erkenntnis Gottes; zur Beschämung sage ich es euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Jedoch es könnte jemand fragen: \"Wie werden die Toten auferweckt?\" \"Mit was für einem Leibe werden sie kommen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Du Tor! Was du säst, wird nicht lebendig, wenn es nicht gestorben ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Und was du säst, ist nicht der Körper, der entstehen soll, vielmehr ein einfaches Korn, etwa vom Weizen oder einer anderen Pflanzenart.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Gott aber gibt ihm eine Form, so wie er will, jedem Samenkorn seine eigene Form.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nicht jedes Fleisch ist von derselben Art: Ein anderes ist das der Menschen, ein anderes das der Haustiere, ein anderes das der Vögel und wieder anders das der Fische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Auch gibt es himmlische und irdische Körper. Ganz anders ist der Glanz der himmlischen Körper und anders der der irdischen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'anders ist der Glanz der Sonne und anders der des Mondes und wieder anders der der Sterne; und bei den Sternen selber unterscheidet sich der eine von dem anderen an Glanz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'So verhält es sich auch mit der Auferstehung von den Toten: Gesät wird in Verweslichkeit und auferweckt in Unverweslichkeit;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'gesät wird in Unehre und auferweckt in Herrlichkeit; gesät wird in Schwäche und auferweckt in Kraft;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'gesät wird ein Sinnenleib, auferweckt ein vergeistigter Leib. Gibt es einen Sinnenleib, dann gibt es auch einen vergeistigten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'So steht ja auch geschrieben: \"Der erste Mensch, Adam, ward ein lebendiges Wesen.\" Der letzte Adam ward ein geistiges, lebenspendendes Wesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Zuerst kommt aber nicht das Vergeistigte, sondern das Sinnliche; alsdann erst kommt das Vergeistigte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Der erste Mensch stammt von der Erde, ist aus Lehm; der zweite Mensch stammt aus dem Himmel ist himmlisch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Wie der aus Lehm Gebildete, also auch die aus Lehm Gebildeten, und wie der Himmlische, so auch die Himmlischen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Wie wir das Abbild des aus Lehm Gebildeten an uns getragen haben, so werden wir an uns auch das Bild des Himmlischen tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Das aber sage ich, meine Brüder: Fleisch und Blut können das Reich Gottes nicht erhalten, und das Verwesliche wird nicht die Unverweslichkeit erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Seht, ich sage euch ein Geheimnis. Wir werden zwar nicht alle entschlafen, doch werden wir alle verwandelt werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'und dies plötzlich, in einem Augenblick, beim Schall der letzten Posaune. Denn es wird die Posaune ertönen; die Toten werden alsdann unverweslich auferweckt, und wir werden verwandelt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Denn dieses Verwesliche muß Unverweslichkeit anziehen und dieses Sterbliche Unsterblichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Wenn aber dieses Verwesliche die Unverweslichkeit angezogen hat und dieses Sterbliche die Unsterblichkeit, dann geht das Schriftwort in Erfüllung: \"Verschlungen ist der Tod im Siege.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Wo ist, o Tod, dein Sieg? Wo ist, o Tod, dein Stachel?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Der Stachel des Todes aber ist die Sünde, die Kraft der Sünde aber das Gesetz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Dank sei Gott, der uns den Sieg verleiht durch unseren Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Also, meine lieben Brüder! Steht fest und unerschütterlich allzeit voll Eifer im Werke des Herrn und überzeugt, daß eure Mühe nicht vergeblich ist im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Mit den Sammlungen für die Heiligen haltet es ebenso, wie ich es für die galatischen Gemeinden angeordnet habe:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Am ersten Tage jeder Woche lege jeder aus euch zu Hause zurück, soviel er vermag, damit die Sammlung nicht erst dann gehalten werde, wenn ich anwesend bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Bin ich dann da, so will ich die, die ihr erprobt habt, mit Empfehlungsschreiben nach Jerusalem senden, um eure Liebesgabe hinzubringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Wenn es aber sich verlohnte, daß ich auch hinreise, so werden sie mich begleiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Ich komme zu euch, sobald ich Mazedonien durchwandert habe; denn Mazedonien will ich nur durchwandern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'bei euch jedoch womöglich noch länger verweilen, vielleicht sogar den ganzen Winter; ihr solltet mir dann das Geleit geben, wohin ich eben reise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Gerade jetzt möchte ich euch nicht nur so vorübergehend sehen, ich hoffe vielmehr, bei euch geraume Zeit zu bleiben, wenn der Herr es gestattet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'In Ephesus bleibe ich bis Pfingsten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'denn eine weite, einflußreiche Tür steht mir offen, doch sind es auch viele Gegner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Kommt dann Timotheus, so sorgt dafür, daß er sich ohne Furcht bei euch aufhalten kann. Er arbeitet ja am Werke des Herrn wie ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'So soll ihn niemand geringschätzen. Gebt ihm vielmehr im Frieden das Geleit, auf daß er zu mir komme. Denn ich erwarte ihn mitsamt den Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Was aber den Bruder Apollos betrifft, so habe ich ihn dringend gebeten, er möge mit den Brüdern zu euch kommen; er hatte aber keineswegs die Absicht, jetzt schon zu gehen. Doch wird er kommen, sobald sich eine günstige Gelegenheit findet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Seid wachsam, steht fest im Glauben, seid mannhaft und seid stark!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Was immer ihr tut, sei in Liebe getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Brüder, ich flehe euch an: Ihr wißt: Das Haus des Stephanas und das des Fortunatus und Achaikus ist die Erstlingsfrucht Achaias und hat dem Dienste der Heiligen sich gewidmet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Auch ihr sollt solchen ganz ergeben sein, wie auch jedem anderen, der mitarbeitet und sich müht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Ich freue mich, daß Stephanus gekommen ist und Fortunatus und Achaikus: denn sie ersetzen eure Abwesenheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'und sie erquicken meinen und auch euren Geist. Erweist solchen Männern eure Hochachtung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Die Gemeinden Asiens senden euch Grüße; es grüßen euch vielmals im Herrn Aquila und Priska samt der Gemeinde in ihrem Hause bei denen ich als Gastfreund wohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Es grüßen euch alle Brüder! Grüßt auch ihr einander mit heiligem Kusse!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Hier mein eigenhändiger Gruß: Paulus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Wenn einer den Herrn Jesus Christus nicht liebt, der soll verflucht sein! Marana tha!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Die Gnade des Herrn Jesus sei mit euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mit euch allen ist meine Liebe in Christus Jesus Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, Apostel Christi Jesu durch den Willen Gottes, und der Bruder Timotheus an die Gemeinde Gottes in Korinth und an alle Heiligen, die in ganz Achaia sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus, der Vater der Erbarmungen und der Gott alles Trostes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Er tröstet uns in all unserer Bedrängnis, damit auch wir andere in jeglicher Bedrängnis trösten können durch den Trost, mit dem wir selbst von Gott getröstet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Denn wie die Leiden Christi uns in überreichem Maß getroffen haben, so wird durch Christus uns auch überreicher Trost zuteil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Und mögen wir auch in Bedrängnis kommen, alsdann geschieht es zu eurem Trost und Heil, und mögen wir getröstet werden, alsdann geschieht es zu eurem Troste und mögen wir ermuntert werden, dann geschieht es zu eurer Ermunterung und zu eurem Heil, so daß ihr gleiche Leiden, wie wir sie dulden, geduldig ertragen könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'So steht denn unsere Hoffnung für euch fest begründet, weil wir wissen, daß ihr am Leiden ebenso teilhabt wie am Troste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Wir möchten nämlich euch, ihr Brüder, nicht in Unkenntnis lassen über die Bedrängnis, die wir in Asien zu erdulden hatten. Sie traf uns ungewöhnlich schwer, ja, über unsere Kraft, so daß wir am Leben selbst verzweifelten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'wir trugen unser Todesurteil schon in uns. Wir sollten eben das Vertrauen nicht auf uns selbst setzen, vielmehr auf Gott, der die Toten auferweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Er hat uns auch aus dieser großen Todesnot gerettet und rettet uns noch immer und wird, so hoffen wir, auch fernerhin uns retten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'wenn nur ihr durch euer Beten für uns mithelft, damit aus vieler Mund von vielen für uns gedankt werde für die an uns erzeigte Gnade.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Unser Ruhm ist das Zeugnis unseres Gewissens, daß wir in Gottes Heiligkeit und Lauterkeit in der Welt gewandelt sind und nicht in irdischer Weisheit, vielmehr in der Liebe Gottes, zumal wenn es dabei sich um euch handelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Denn unsere Schreiben wollen nichts anderes bedeuten, als was ihr lest und versteht. Ich hoffe, daß ihr es bis ans Ende verstehen werdet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'wie ihr zum Teil uns schon verstanden habt, daß nämlich wir euer Ruhm sind, wie auch ihr der unsrige am Tag unseres Herrn Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Erfüllt von solcher Zuversicht hatte ich im Sinne, zunächst zu euch zu kommen, damit ihr eine zweite Gnade hättet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Von euch wollte ich sodann nach Mazedonien weiterreisen und wiederum von Mazedonien zu euch zurück, um mir von euch dann das Geleit nach Judäa zu erbitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'War es nun Leichtsinn, der mich bei diesem Plane geleitet hat? Oder fasse ich Entschlüsse nur nach Laune, daß es bei mir zugleich \"ja, ja\" und \"nein, nein\" heißt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'So wahr Gott getreu ist: Nicht Ja und Nein zugleich ist unser Wort an euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Denn Jesus Christus, der Sohn Gottes, der euch durch uns verkündigt ward, durch mich, Silvanus und Timotheus, war auch nicht Ja und Nein; sondern in ihm ist \"Ja\" zur Wirklichkeit geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'In ihm ist alles das bejaht worden, was Gott verheißen hat. Darum dient auch in ihm das \"Amen\" Gott zum Lobe durch uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Der uns mit euch in Christus gegründet und gesalbt hat, ist Gott;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'er hat uns auch das Siegel aufgedrückt sowie den Geist als Unterpfand in unser Herz gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Ich rufe Gott zum Zeugen auf, bei meinem Leben, daß ich nur deshalb noch nicht nach Korinth gekommen bin, um euch zu schonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nicht so, als wollten wir euren Glauben meistern, sondern wir möchten euch zur Freude verhelfen; im Glauben steht ihr ja fest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Ich nahm mir aber vor, nicht mehr zu euch zu kommen, wenn ich betrüben müßte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Denn wenn ich euch betrübe, wer sollte mir dann Freude machen, wenn nicht gerade der von mir Betrübte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Darum habe ich die Angelegenheit durch einen Brief erledigt, damit, wenn ich komme, ich nicht an denen Trauer erleben mußte, von denen ich doch Freude haben sollte. Ich habe das Vertrauen zu euch allen, daß meine Freude auch die von euch allen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Aus großer Drangsal nämlich und aus Herzensangst habe ich mit vielen Tränen euch geschrieben, doch nicht etwa, damit ihr betrübt würdet, vielmehr, damit ihr die übergroße Liebe erkennt, die ich zu euch habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Hat einer aber Betrübnis verursacht, so hat er mich zwar nicht betrübt, jedoch zum Teil - ich will nicht übertreiben - euch alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Die Strafe, die die Mehrzahl über ihn verhängt hat, mag ihm genügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'So wollt ihm jetzt eher wiederum verzeihen und ihn trösten, damit er nicht in seiner übergroßen Traurigkeit untergehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'So mahne ich euch denn, ihm Liebe zu erweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Habe ich doch gerade deshalb geschrieben, um euch zu prüfen, ob ihr in allem durchaus gehorsam seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Wem aber ihr irgend etwas verzeihst, dem verzeihe auch ich; denn habe ich verziehen - sofern ich überhaupt etwas zu verzeihen hatte -, so tat ich es um euretwillen vor dem Antlitz Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Wir wollen uns doch nicht vom Satan überlisten lassen; wir kennen seine Schliche nur zu gut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Als ich nach Troas kam, um das Evangelium Christi zu verkünden, da tat sich mir im Herrn eine Türe auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Doch hatte ich in meinem Innern keine Ruhe, weil ich meinen Bruder Titus nicht antraf. Ich nahm deshalb dort Abschied und ging nach Mazedonien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Gott sei Dank, der uns allzeit in Christus triumphieren und den Duft seiner Erkenntnis überall durch uns verbreiten läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Denn Christi Wohlgeruch sind wir für Gott bei denen, die Rettung finden, und bei denen, die verlorengehen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'den einen ein Geruch des Todes, der den Tod bewirkt, und für die andere ein Wohlgeruch des Lebens, der Leben schafft. Und wer ist dazu fähig?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Wir freilich machen es nicht so, wie es so viele tun, daß wir das Gotteswort verschachern würden; wir reden vielmehr nur aus Lauterkeit, wie aus Gott so vor Gott in Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Fangen wir schon wieder an, uns selber zu empfehlen? Oder brauchen wir, wie andere, etwa Empfehlungsschreiben wie an euch, so auch von euch?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Unser Empfehlungsbrief seid ihr, in unser Herz hineingeschrieben, verständlich und für jedermann zu lesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Ganz offensichtlich seid ihr selber Christi Brief, von uns besorgt, geschrieben nicht mit Tinte, sondern mit dem Geiste des lebendigen Gottes, und nicht auf steinerne Tafeln, vielmehr auf fleischerne Herzenstafeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ein solches Vertrauen haben wir auf Gott durch Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nicht als ob wir aus uns selbst, aus eigener Kraft schon fähig wären, auch nur einen Gedanken zu fassen; nein, unsere Fähigkeit dazu stammt aus Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'der uns zu Dienern des Neuen Bundes befähigt hat. Es ist kein Bund des Buchstabens, vielmehr des Geistes; denn der Buchstabe tötet, der Geist aber macht lebendige');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Wenn nun schon der Dienst des Todes, der mit Buchstaben auf Stein gegraben war, mit solcher Herrlichkeit erfolgte, daß die Kinder Israels dem Moses nicht ins Antlitz schauen konnten wegen des Glanzes seines Angesichtes, der doch verging,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'um wieviel mehr wird dann der Dienst des Geistes in Herrlichkeit bestehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Wenn der Dienst der Verdammung schon so herrlich war, dann ist der Dienst der Rechtfertigung noch viel reicher an Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Ja, die Verherrlichung in diesem Falle schwindet hin vor dieser übergroßen Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Denn wenn schon das Vergängliche durch Herrlichkeit geoffenbart ward, um wieviel mehr wird dann das Bleibende noch viel herrlicher sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Im Besitz einer solchen Hoffnung treten wir mit großem Freimut auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Wir machen es nicht wie Moses, der sein Angesicht verhüllte, damit die Kinder Israels das Ende des Vergänglichen nicht sehen sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Jedoch ihr Sinn ward verhärtet; denn bis zum heutigen Tage bleibt die gleiche Hülle unaufgedeckt bei der Lesung des Alten Testamentes, da nicht enthüllt wird, daß es in Christus seine Wirksamkeit verliert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Im Gegenteil, bis zum heutigen Tage, wenn Moses vorgelesen wird, liegt auf ihrem Herzen eine Hülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Doch wenn es sich zum Herrn bekehrt, dann wird die Hülle weggenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Der Herr ist der Geist; wo der Geist des Herrn ist, da ist Freiheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Wir alle aber schauen die Herrlichkeit des Herrn mit unverhülltem Angesicht wie im Spiegel und werden in dasselbe Bild umgestaltet werden, zu immer größerer Herrlichkeit gerade durch den Geist des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Weil wir durch Erbarmung diesen Dienst besitzen, werden wir nicht müde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Wir haben schandvolle Heimlichkeit abgewiesen, wir gehen nicht mit Ränken um, noch fälschen wir das Wort Gottes, vielmehr empfehlen wir vor Gott uns jedem menschlichen Gewissen durch offene Verkündigung der Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Sollte aber unser Evangelium auch verhüllt sein, so ist es nur für die verhüllt, die verlorengehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'bei Ungläubigen, denen der Gott dieser Welt den Verstand geblendet hat, damit der Lichtglanz des Evangeliums von der Herrlichkeit Christi, der Gottes Abbild ist, nicht aufleuchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Denn nicht uns selbst künden wir, sondern Christus Jesus als den Herrn, uns aber Jesu wegen als eure Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Denn Gott, der sprach: \"Aus Finsternis soll Licht aufleuchten\", ist es, der in unseren Herzen aufgeleuchtet ist, damit die Einsicht in die Herrlichkeit Gottes auf Jesu Christi Antlitz aufleuchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Wir tragen diesen Schatz in irdenen Gefäßen, auf daß das Übermaß an Kraft von Gott und nicht von uns herkomme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Von allen Seiten werden wir bedrängt, doch nicht erdrückt; wir sind ratlos, aber nicht mutlos,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'verfolgt, doch nicht verlassen, unterdrückt, doch nicht vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Wir tragen allezeit an unserm Leibe das Todesleiden Jesu, damit auch das Leben Jesu an unserem Leibe sichtbar werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Beständig sind wir, obschon noch lebend, um Jesu willen dem Tod ausgeliefert, damit auch das Leben Jesu an unserem sterblichen Leibe sichtbar werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'So wirkt in uns der Tod, in euch jedoch das Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Da wir den gleichen Geist des Glaubens haben wie in der Schriftstelle: \"Ich glaube, darum rede ich\", so glauben wir und reden deshalb auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Wir wissen ja, daß der, der den Herrn Jesus auferweckt hat, auch uns mit Jesus auferwecken und mit euch darstellen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'All dies geschieht um euretwillen, damit die Gnade, vermehrt durch so viele, den Dank überreich mache zur Ehre Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Darum verzagen wir auch nicht; denn mag auch unser äußerer Mensch aufgegeben werden, der innere verjüngt sich von Tag zu Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Denn unsere jetzige erträgliche Drangsal verschafft uns eine über alle Maßen große und ewige Fülle an Herrlichkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'wenn wir nur unsere Blicke nicht aufs Sichtbare, sondern aufs Unsichtbare richten. Das Sichtbare ist zeitgebunden, das Unsichtbare aber bleibt ewig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Wir wissen, wenn unsere irdische Zeltwohnung abgebrochen wird, haben wir ein Haus von Gott, eine nicht von Händen hergestellte ewige Wohnung in den Himmeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Wir seufzen in der Tat voll Verlangen, unsere himmlische Behausung darüber anzuziehen. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Nur wenn wir diese angezogen haben, dann werden wir nicht nackt erfunden werden. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Solange wir also in diesem Zelt sind, seufzen wir beklommen, weil wir nicht entkleidet, sondern überkleidet werden möchten, damit das Sterbliche vom Leben verschlungen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Gott, der uns gerade dazu instand setzt, ist es auch, der uns als Unterpfand den Geist gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Wir sind darum stets guten Mutes, obschon wir wissen, daß, solange wir im Leibe weilen, wir fern vom Herrn sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Denn noch wandeln wir im Glauben, nicht im Schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Wir sind aber guten Mutes und wünschen, lieber aus unserem Leib auszuziehen und beim Herrn daheim zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Darum setzen wir auch unsere Ehre darein, ihm zu gefallen, sei es im Leib oder außerhalb des Leibes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Wir alle müssenja vor dem Richterstuhl Christi erscheinen, damit jeder empfange, was er, sei es Gutes oder Böses, in seinem Leibesleben getan hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Durchdrungen also von der Furcht des Herrn, versuchen wir, die Menschen zu gewinnen. Von Gott sind wir ganz klar durchschaut, und so hoffe ich, daß wir auch in eurem Gewissen klar durchschaut sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Wir wollen damit nicht uns wieder selbst empfehlen, vielmehr euch nur Gelegenheit verschaffen, unseretwegen euch zu rühmen, damit ihr jenen entgegnen könnt, die sich ins Antlitz nur und nicht im Herzen rühmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Wenn wir von Sinnen sind, dann ist es für Gott; sind wir bei Verstand, so ist es für euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Die Liebe Christi hält uns fest in der Erwägung: daß, wenn einer für alle gestorben ist, alle gestorben sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Und er ist für alle gestorben, damit die Lebenden nicht mehr für sich selber leben, vielmehr für den, der für sie gestorben ist und auferweckt wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'So kennen wir von jetzt an niemand mehr dem Fleische nach. Und wenn wir früher Christus dem Fleische nach gekannt haben, so kennen wir ihn jetzt nicht mehr so.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Wer in Christus ist, ist eine neue Schöpfung; das Alte ist dahin; seht, es wurde Neues.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Das alles aber kommt von Gott, der uns durch Christus mit sich versöhnt und den Dienst der Versöhnung uns verliehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Gott war es, der durch Christus die Welt mit sich versöhnt und ihre Sünden ihr nicht angerechnet und das Wort der Versöhnung in uns gelegt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Wir sind also Gesandte Christi; denn Gott mahnt durch uns; an Christi Stelle bitten wir: Versöhnet euch mit Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Er machte den, der von der Sünde nichts gewußt hat, für uns zur Sünde, auf daß wir durch ihn vor Gott Gerechte würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Als Mitarbeiter mahnen wir: Empfangt die Gnade Gottes nicht vergeblich!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'So heißt es ja: \"Zur Gnadenzeit erhörte ich dich; am Tage des Heiles half ich dir\". Seht, jetzt ist die reichste Gnadenzeit, jetzt ist der Tag des Heiles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Wir wollen niemand irgendwelchen Anstoß geben, damit unseren Dienst kein Vorwurf treffe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'In allem möchten wir vielmehr als Diener Gottes uns erweisen, in viel Geduld, in Drangsalen, Nöten und Ängsten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'bei Schlägen, in Gefängnissen und Unruhen, in Mühen, Nachtwachen und Fasten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'in Reinheit und Erkenntnis, in Langmut und Güte, im Heiligen Geist und in ungeheuchelter Liebe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'im Wort der Wahrheit und in Gottes Kraft und durch die Waffen der Gerechtigkeit zum Schutz und Trutz,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'bei Ehre und bei Schmach, bei Schmähung und bei Lob. Wir gelten als betrügerisch und sind doch ehrlich,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'als unbekannt und sind doch wohlbekannt, als dem Tod Geweihte, und siehe da, wir leben, als Gezüchtigte, und wir sind doch nicht tot,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'als Betrübte und sind immer fröhlich, als Bettler, und wir machen viele reich, als Besitzlose, und wir besitzen alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Korinther! Unser Mund hat sich vor euch geöffnet, weit unser Herz sich aufgetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Ihr nehmt keinen kleinen Platz darin ein; klein aber ist der Platz, den ihr in eurem Herzen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Vergeltet Gleiches doch mit Gleichem: - ich rede wie zu Kindern - macht euer Herz auch weit!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Zieht nicht am gleichen Strange mit den Ungläubigen! Was hat Gerechtigkeit mit Unglauben zu schaffen? Was haben Licht und Finsternis gemein?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Worin stimmt Christus mit Beliar zusammen? Und welchen Teil hat der Gläubige mit dem Ungläubigen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Und wie verträgt der Tempel Gottes sich mit Götzen? Wir sind ja der Tempel des lebendigen Gottes, wie Gott gesprochen hat: \"Ich will in ihnen wohnen und wandeln; Ich will ihr Gott sein, und sie sollen mir mein Volk sein.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Deshalb \"zieht fort aus ihrer Mitte und sondert euch ab, spricht der Herr, und Unreines berührt nicht! Alsdann will ich euch aufnehmen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'will euch Vater sein, und ihr sollt mir Söhne sein und Töchter, so spricht der Herr, der Allbeherrscher.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Geliebteste, da wir derartige Verheißungen besitzen, so wollen wir uns von jeder fleischlichen und geistigen Befleckung rein halten und unsere Heiligkeit in Gottesfurcht vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Gebt uns Platz! Wir haben niemand Unrecht getan, niemand geschädigt noch übervorteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nicht um euch zu verdammen, sage ich dies; sagte ich eben doch schon, daß ihr in unserem Herzen auf Tod und Leben mit uns verbunden seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Ich bin euch gegenüber voll Freimut, voll Stolz bin ich über euch. Ich bin auch voll des Trostes; ich fließe über vor lauter Freude bei all unserer Bedrängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Als wir nämlich nach Mazedonien gekommen waren, da hatte unser Leib keine Ruhe, nur allerlei Bedrängnis: von außen Kämpfe und im Innern Furcht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Doch Gott, der die Gebeugten tröstet, hat uns getröstet durch die Ankunft des Titus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Und nicht allein durch seine Ankunft, viel mehr noch durch den Trost, den er bei euch erfahren hat. Berichtete er uns doch von eurer Sehnsucht, von eurer Trauer, eurem Eifer meinetwegen, was meine Freude noch vermehrte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Habe ich in meinem Brief euch also auch betrübt, so reut es mich doch nicht, selbst wenn es mich auch retten wollte. Ich sehe ja, daß jener Brief euch betrübt hat, wenn auch nur für kurze Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Jetzt aber freut es mich, nicht, daß ihr betrübt wurdet, vielmehr weil die Betrübnis euch zur Bekehrung geführt hat. Ihr wurdet ja betrübt, wie es Gott wohlgefällig ist, so daß ihr unseretwegen in keiner Weise Schaden leidet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Bewirkt doch die gottgefällige Betrübnis Bekehrung, die heilsam ist und darum nicht bereut wird. Die Betrübnis der Welt aber wirkt den Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Seht doch, welchen Eifer diese gottgefällige Betrübnis in euch gewirkt hat: Entschuldigung, Bedauern, Furcht, Sehnsucht, Eifer, Sühne. In jeder Hinsicht habt ihr so bewiesen, daß ihr in dieser Sache ganz schuldlos seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Wenn ich euch also geschrieben habe, geschah es nicht dem zuleid, der jenes Unrecht tat, noch dem zulieb, der dieses Unrecht erlitten hat, vielmehr damit euer Eifer unseretwegen unter euch vor Gott sich offenbare.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Und darum sind wir auch getröstet worden. Bei unserem Trost aber freuten wir uns noch viel mehr darüber, wie sich Titus freut, daß seine Seele von euch allen erquickt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Wenn ich mich eurer irgendwie vor ihm je rühmte, so bin ich nicht zuschanden worden. Wie alles, was wir zu euch sagten, Wahrheit war, so ist dem Titus gegenüber unser Rühmen gleichfalls wahr geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Sein Herz ist euch nur noch mehr gewogen in der Erinnerung an den Gehorsam von euch allen, wie ihr ihn mit Furcht und Zittern aufgenommen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Ich freue mich, daß ich in allem mich auf euch verlassen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Wir geben euch, liebe Brüder, Kunde von der Gottesgabe, die in den mazedonischen Gemeinden abgeliefert worden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'In Trübsal reichlich erprobt, hat sich aus der Fülle ihrer Freude und aus der Tiefe ihrer Armut ein reicher Strom zum Reichtum ihrer opferfrohen Gäste ergossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Nach Vermögen, ja, ich kann es bezeugen, über ihr Vermögen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'so baten sie uns flehentlich von sich aus, sich an den Liebesgaben beteiligen zu dürfen und am Dienste für die Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Nicht bloß so, wie wir gehofft hatten, sie gaben vielmehr sich selber zuerst dem Herrn und dann auch uns nach Gottes Willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Infolgedessen baten wir den Titus, er möge so, wie er begonnen hat, bei euch auch dieses Liebeswerk vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Wie ihr in jeder Art euch auszeichnet: im Glauben und im Wort, in der Erkenntnis und in jedem Eifer und auch in der von uns in euch geweckten Liebe, so zeichnet euch auch in diesem Liebeswerk aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nicht als ob ich euch befehlen wollte, sage ich dies; ich möchte am Eifer anderer nur die Echtheit eurer Liebe prüfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Ihr kennt ja die Liebe unseres Herrn Jesus Christus; obgleich er reich war, ward er euretwegen arm, damit ihr durch seine Armut reich würdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Nur einen Rat möchte ich in dieser Sache geben. Das ist für euch von Nutzen, die ihr nicht allein mit der Ausführung, vielmehr auch mit dem rechten Wollen letztes Jahr begonnen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Führt es jetzt vollends durch, damit wie eure Bereitschaft für das Wollen so auch die Ausführung dem Vermögen entspreche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Denn ist der gute Wille da, so ist er Gott gefällig schon nach dem, was er besitzt, und nicht nach dem, was er nicht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Es soll nicht anderen Erleichterung geschaffen werden, euch aber nur Bedrängnis; vielmehr um einen Ausgleich herzustellen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Soll jetzt euer Überfluß dem Mangel jener zukommen, damit auch der Überfluß von jenen eurem Mangel abhelfe. So soll ein Ausgleich stattfinden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'so wie geschrieben steht: \"Wer viel sammelte, der hatte keinen Überfluß, und wer nur wenig sammelte, hatte keine Not.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Doch Dank sei Gott, der dem Titus den gleichen Eifer für euch ins Herz gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Er nahm meine Bitte an und reiste voll Eifer aus eigenem Antrieb zu euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Mit diesem senden wir den Bruder, dessen Lob im Evangelium durch alle Gemeinden geht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Doch nicht nur dies; er ward von den Gemeinden auch zu unserem Begleiter für dieses Liebeswerk bestellt, das wir unternehmen zur Ehre des Herrn und zum Beweise unseres guten Willens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Wir möchten nämlich verhüten, daß bei der Fülle dieser Gaben, die wir besorgen, uns jemand übel nachrede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Denn wir sind auf das bedacht, was recht ist nicht bloß vor dem Herrn, sondern auch vor den Menschen. Mit ihm senden wir auch unseren Bruder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'den wir in vielen Angelegenheiten oftmals eifrig fanden, der aber jetzt, da er soviel auf euch vertraut, noch größeren Eifer zeigen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Mag es sich um Titus handeln - er ist mein Gefährte, bei euch mein Mitarbeiter - oder um unsere Brüder - sie sind Abgesandte der Gemeinden, Christi Ruhm -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'gebt ihnen die Beweise eurer Liebe und auch von der Wahrheit dessen, was wir von euch so Rühmliches vor den Gemeinden sagten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Doch euch noch mehr betreffs der Hilfeleistung für die Heiligen zu schreiben, erachte ich für überflüssig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Ich kenne ja euren guten Willen und rühmte ihn den Mazedoniern gegenüber: \"Achaja ist nun schon seit Jahresfrist bereit.\" Euer Eifer spornte viele andere an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Trotzdem sende ich die Brüder, damit das, was wir zu eurem Ruhm gesagt, nicht gerade hier inhaltslos würde und damit ihr, wie ich immer wieder sage, wirklich vorbereitet seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Sonst könnten, kämen Mazedonier mit mir und träfen sie euch unvorbereitet an, wir, um nicht zu sagen ihr, in dieser Zuversicht beschämt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Ich hielt es darum für notwendig, die Brüder zu bitten, sie möchten doch schon vorher zu euch reisen und eure früher schon angekündigte Segensgabe in Ordnung bringen, so daß sie schon bereit liege, und zwar als eine Segensgabe und nicht als ein Geschenk des Geizes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Noch eins! Wer spärlich sät, wird spärlich ernten; doch wer auf Segensfülle sät, wird Segensfülle ernten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Jeder gebe, wie er es sich im Herzen vorgenommen hat, doch nicht in Unlust noch mit Zwang; denn den freudigen Geber hat Gott lieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Gott kann jede Gabe für euch zur Fülle werden lassen, damit ihr in allem allezeit euer volles Auskommen habt und noch zu jedem guten Werk überreich erübrigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'So steht es ja auch geschrieben: \"Er streut aus und gibt den Armen; sein Almosen währt ewiglich.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Doch er, der dem Sämann Samen reicht und Brot zur Speise, der wird auch euch das Saatgut geben und es vermehren und die Früchte eures Almosens gedeihen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'So werdet ihr in allem reich zu jeder Art von Güte, die Gott durch uns zum Lobe gereicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Denn diese Dienstleistung hilft nicht allein der Not der Heiligen ab; sie bringt auch reiche Früchte durch so viele Dankgebete Gott zu Ehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Sie preisen Gott, daß ihr in diesem Liebesdienst euch bewährt, daß ihr dem Bekenntnis des Evangeliums Christi so ergeben seid, und ebenso für die opferfrohe Güte, in der ihr die Gemeinschaft pflegt mit ihnen und mit allen anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Wenn sie für euch Gebete darbringen, so werden sie nach euch sich sehnen um jener übergroßen Liebe willen, die Gott euch erwiesen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Dank sei Gott für seine unbeschreiblich große Gabe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Ich selbst aber, Paulus, mahne euch bei der Sanftmut Christi und bei seiner Milde, ich, der ich zwar bei euch ins Angesicht hinein bescheiden bin, doch aus der Ferne mutig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'ich bitte, daß ich bei meiner Ankunft nicht aufzutreten brauche mit jenem Mut und jenem Selbstbewußtsein, wie ich gegen ganz Bestimmte vorzugehen gedenke, die meinen, daß wir nach dem Fleische wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Wir wandeln wohl im Fleische, doch kämpfen wir nicht nach dem Fleische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Die Waffen, mit denen wir kämpfen, sind nicht fleischlich, sondern stark für Gott, um selbst Bollwerke einzureisen. Trugschlüsse reißen wir damit nieder');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'und jeden Hochmut, der wider die Erkenntnis Gottes sich erhebt; auch nehmen wir jeglichen Gedanken gefangen und machen ihn Christus gehorsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Wir sind bereit, jeden Ungehorsam zu bestrafen, sobald nur eure Folgsamkeit vollendet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Beachtet das, was klar vor Augen liegt. Wenn einer sich darauf etwas einbildet, daß er Christus angehört, so möge er doch andererseits bei sich bedenken, daß, wie er, auch wir Christus angehören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Und habe ich mich noch darüber hinaus gerühmt ob unserer Gewalt, die uns der Herr verliehen hat zu eurer Auferbauung, nicht zu eurer Zerstörung, so werde ich deshalb nicht zuschanden werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Doch ich mag nicht den Anschein erwecken, als wollte ich durch die Briefe sozusagen euch nur einschüchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, '\"Die Briefe\", sagt man ja, \"sind wuchtig und kräftig, doch sein persönliches Auftreten ist schwächlich, und gar nichts ist sein Vortrag.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Wer so spricht, möge doch bedenken, daß wir genau so, wie wir abwesend durch das geschriebene Wort uns zeigen, uns durch die Tat auch anwesend erweisen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Wir wagen es nun freilich nicht, uns auf eine Linie zu stellen, oder uns mit solchen zu vergleichen, die sich selbst zu empfehlen wissen. Sie messen sich nur an sich selbst und stellen sich selber nur sich selbst gleich und zeigen damit ihren Unverstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Wir aber rühmen uns nicht ins Ungemessene, vielmehr nur nach Maßgabe des Arbeitsfeldes, das Gott uns als Maß zugeteilt hat und das bis zu euch hinreicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Wir dehnen uns nicht übermäßig aus, als wären wir nicht bis zu euch gelangt. Sind wir doch wirklich mit der Predigt des Evangeliums Christi bis zu euch gekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Wir rühmen uns nicht ins Ungemessene fremder Arbeit, wohl aber hegen wir die Hoffnung, daß wir, wenn euer Glaube wächst, dann bei euch groß dastehen werden, wie es ja auch unserem Arbeitsfeld entspricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Dann können wir auch in Gebieten, die über euch hinaus liegen, das Evangelium verkünden und brauchen uns dabei nicht der Arbeiten auf fremdem Felde zu rühmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '\"Wer sich rühmen will, der rühme sich im Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Denn nicht der ist bewährt, der sich selber empfiehlt, sondern wen der Herr empfiehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'O möchtet ihr ein wenig Torheit von mir hinnehmen! Nehmt es von mir hin!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Mit einer göttlichen Eifersucht bin ich für euch ja eifersüchtig; ich habe euch einem Manne verlobt, um euch als keusche Jungfrau Christus zuzuführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ich fürchte nur, wie einst die Schlange mit ihrer Arglist die Eva verführt hat, so könnte auch euer Denken verdorben werden weg von der schlichten Hingabe an Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Wenn einer kommt und euch einen anderen Jesus verkündigt als den, den wir verkündet haben, oder wenn ihr einen anderen Geist bekämet, den ihr bis jetzt nicht empfangen habt, oder ein anderes Evangelium, wie ihr es nicht erhalten habt, so laßt ihr euch dies gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Ich denke, daß ich in nichts den \"Überaposteln\" nachstehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Mag ich auch ein Stümper im Ausdruck sein, so doch nicht an Erkenntnis, die wir bei euch in allem durchaus kundgetan haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Habe ich denn eine Sünde damit getan, daß ich mich selbst erniedrigte, nur um euch zu erhöhen, weil ich euch das Evangelium Gottes unentgeltlich verkündigt habe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Andere Gemeinden habe ich beraubt und Unterstützung angenommen, damit ich euch dienen könnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Als ich bei euch war und in Not geriet, fiel ich niemand zur Last. Denn was mir mangelte, ergänzten die Brüder, die aus Mazedonien kamen. So habe ich mich peinlich gehütet, euch zur Last zu fallen, und werde mich auch ferner hüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'So gewiß die Wahrheit Christi in mir ist: der Ruhm soll in den Gegenden Achaias mir nicht geschmälert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Weshalb? Vielleicht, weil ich euch nicht liebe? Weiß Gott!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Was ich jetzt tue, werde ich auch ferner tun, um denen, die einen Vorwand suchen, diesen wegzunehmen, damit sie bei ihrem Rühmen so wie wir erfunden würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Solche Menschen sind Lügenapostel, heimtückische Arbeiter, die sich als Apostel Christi ausgeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Doch das ist nicht verwunderlich, verwandelt sich doch Satan selbst in einen Lichtengel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Da ist es nichts Besonderes, wenn auch seine Diener sich als Diener der Gerechtigkeit ausgeben. Ihr Ende wird sein wie ihre Werke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Ich wiederhole: Niemand halte mich für töricht. Und wenn schon, nun, so nehmt mich eben hin als einen Toren, damit auch ich mich ein wenig rühmen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Was ich in diesem Punkte des Rühmens rede, das rede ich nicht im Sinne des Herrn, sondern sozusagen nur im Unverstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Nachdem so viele sich dem Fleische nach rühmen, so muß auch ich mich selbst doch rühmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'So kluge Leute wie ihr seid, ertragen ja gerne Toren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Denn ihr ertragt es auch, wenn man euch knechtet, aussaugt, übervorteilt, sich überhebt, euch in das Antlitz schlägt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Zu meiner Schande muß ich es gestehen: In diesem Stücke sind wir schwach gewesen. Worauf nun einer pocht - ich rede im Unverstand -, darauf poche ich auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Sie sind Hebräer? Ich auch. Israeliten sind sie? Ich auch. Abrahams Nachkommen sind sie? Ich auch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Und Diener Christi sind sie? - Ich rede wie ein Tor: ich noch mehr. Und dies in Mühsal ohne Zahl, in überreicher Kerkerhaft, in Mißhandlungen mehr als schwer, oft in der Gefahr des Todes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Fünfmal erhielt ich von den Juden vierzig Schläge weniger einen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'dreimal ward ich mit Ruten geschlagen, einmal gesteinigt, dreimal erlitt ich Schiffbruch. Eine Nacht und einen Tag trieb ich auf hoher See umher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Dazu eine große Zahl von Wanderungen, Gefahren durch Flüsse, Gefahren von den Räubern, Gefahren von meinem eigenen Volke, Gefahren von den Heiden, Gefahren in der Stadt, Gefahren in den Einöden, Gefahren auf dem Meere, Gefahren von falschen Brüdern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Mühsale und Beschwerden, viele Nachtwachen. Hunger und Durst, vieles Fasten, in Kälte und in Blöße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Ganz abgesehen von weniger Wichtigem: der tägliche Besuchsandrang bei mir, die Sorge um alle Gemeinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Wo ist einer schwach und ich nicht auch? Wo wird einer zur Sünde verleitet, und mir geht es nicht brennend nahe?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Wenn doch gerühmt sein muß, so will ich mich auch meiner schwachen Seiten rühmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Der Gott und Vater des Herrn Jesus - in Ewigkeit sei er gepriesen! - weiß, daß ich nicht lüge:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Der Statthalter des Königs Aretas zu Damaskus ließ die Stadt der Damaszener scharf bewachen, er wollte mich gefangennehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Da wurde ich in einem Korbe durch ein Fenster an der Mauer hinabgelassen, und so entkam ich seinen Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Wenn schon gerühmt sein muß - es nützt zwar nichts -, so will ich zu den Gesichten und den Offenbarungen des Herrn übergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Ich weiß einen Menschen in Christus, es ist jetzt vierzehn Jahre her, der ward - ob im Leibe, ich weiß es nicht, oder außerhalb des Leibes, ich weiß es nicht, Gott weiß es - bis in den dritten Himmel entrückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Ich weiß von diesem Menschen - ob im Leibe oder außerhalb, ich weiß es nicht, Gott weiß es -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'er ward ins Paradies entrückt, und da vernahm er unaussprechliche Worte, die auszusprechen keinem Menschen je verstattet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Und darob will ich mich rühmen. Doch meiner selbst rühme ich mich nicht; es sei denn meiner Schwächen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Ich wäre zwar kein Tor, wenn ich mich rühmen wollte; ich spräche ja die Wahrheit. Doch ich unterlasse es, damit niemand von mir mehr halte, als was er an mir sieht oder von mir hört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Damit ich mich bei dem Übermaß von Offenbarungen nicht überhebe, ward mir ein Stachel ins Fleisch gegeben, ein Satansengel, der mir Fausthiebe versetzen soll, damit ich mich nicht überhebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Um seinetwillen flehte ich dreimal zum Herrn, daß er von mir ablasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Er aber sprach zu mir: \"Genügen muß dir meine Gnade; die Kraft kommt in der Schwachheit zur Vollendung.\" So will ich denn mit Freuden mich lieber meiner Schwächen rühmen, damit sich die Kraft Christi auf mir niederlasse.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Darum habe ich Schwächen gern, Mißhandlungen, Nöte, Verfolgungen, Bedrängnisse um Christi willen; denn wenn ich schwach bin, dann bin ich stark.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ich bin ein Tor geworden, ihr selbst habt mich dazu gezwungen. Ich hätte eigentlich von euch empfohlen werden sollen; ich stehe ja in nichts den \"Überaposteln\" nach, wenngleich ich selbst nichts bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Die Kennzeichen für mein Apostolat sind unter euch in jeglicher Geduld gegeben worden durch Zeichen, Wunder und kraftvolle Taten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Worin wurdet ihr den anderen Gemeinden gegenüber benachteiligt? Es sei denn, daß ich allein euch nicht zur Last fiel. Verzeiht mir dieses Unrecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Seht, zum drittenmal bin ich bereit, zu euch zu kommen, und auch diesmal werde ich euch nicht zur Last fallen. Ich suche ja nicht das Eurige, sondern euch selbst. Die Kinder müssen doch nicht für die Eltern sparen, vielmehr die Eltern für die Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Doch will ich gern Opfer bringen, ja, selbst mich aufopfern für eure Seelen. Wenn ich euch im Übermaß liebe, soll ich dann weniger geliebt werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Nun gut! Ich bin euch nicht zur Last gefallen. Doch \"da ich ein schlauer Mann sei, so hätte ich euch überlistet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Habe ich vielleicht euch ausgebeutet durch irgendeinen, den ich dann und wann zu euch sandte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Ich bat den Titus, und ich sandte noch den Bruder mit. Hat euch nun Titus übervorteilt? Sind wir nicht in demselben Geiste gewandelt, in den gleichen Spuren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Schon lange denkt ihr wohl, daß wir uns vor euch verteidigen wollen. O nein! Wir reden nur vor Gott in Christus. Doch alles, Geliebte, nur zu eurer Erbauung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Ich fürchte nur, ich möchte bei meiner Ankunft euch nicht so finden, wie ich es wünsche, und ihr könntet mich so finden, wie ihr es nicht wünscht; es könnten Zwistigkeiten herrschen und Eifersüchteleien, Zorn, Zwietracht, Verleumdungen, Ohrenbläserei, Anmaßung und Unordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Ich fürchte, Gott könnte bei meiner Wiederkehr mich bei euch verdemütigen; ich müsse nämlich über viele trauern, die früher gesündigt und nicht Buße getan haben der Unzucht, Unreinheit und Ausschweifungen wegen, die sie verübt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Zum drittenmal komme ich jetzt zu euch: \"Jede Streitsache soll durch Aussage zweier oder dreier Zeugen entschieden werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Ich habe es früher schon gesagt und sage es jetzt wieder vorher, wie als ich zum zweitenmal anwesend war und jetzt abwesend bin, denen, die früher gesündigt haben, und auch zu allen anderen: Wenn ich komme, gibt es zum zweitenmal keine Schonung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Ihr verlangt den Beweis, daß Christus in mir redet, er, der in euch nicht schwach, vielmehr mächtig ist bei euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Infolge seiner Schwachheit konnte er zwar gekreuzigt werden, durch die Allmacht Gottes aber lebt er wieder. Also sind auch wir zwar schwach in ihm; wir werden aber auch mit ihm aus Gottes Allmacht für euch leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Prüft euch selbst, ob ihr im Glauben seid. Erprobt euch selbst! Oder erkennt ihr an euch nicht, daß Jesus Christus in euch ist? Wenn nicht, dann seid ihr unbewährt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Doch ich hoffe, ihr werdet finden, daß wir nicht unbewährt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Wir beten aber zu Gott, ihr möchtet nichts Böses tun, und nicht, daß wir bewährt erscheinen, sondern daß ihr das Gute tut, wenn auch wir selber nicht bewährt sein sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Denn wir vermögen nichts gegen die Wahrheit, vielmehr nur für die Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'So freuen wir uns denn, wenn wir schwach sind, ihr aber stark seid; so beten wir auch um eure Vollendung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Ich schreibe euch dieses aus der Ferne, um nicht, wenn ich dort bin, streng sein zu müssen in Kraft der Vollmacht, die mir der Herr zum Aufbauen und nicht zum Niederreißen verliehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Im übrigen, meine Brüder, freut euch, laßt euch wieder zurechtbringen, ermuntert euch und lebt in Einigkeit und haltet Frieden; der Gott der Liebe und des Friedens wird dann mit euch sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Grüßt einander mit heiligem Kusse. Es grüßen euch alle Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Die Gnade des Herrn Jesus Christus, die Liebe Gottes und die Gemeinschaft des Heiligen Geistes seien mit euch allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus, Apostel nicht von Menschen noch durch Menschen, vielmehr durch Jesus Christus und durch Gott den Vater, der ihn von den Toten auferweckt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'und alle Brüder, die bei mir sind, an die Gemeinden in Galatien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'der sich selbst für unsere Sünden hingegeben hat, um uns aus dieser bösen Welt -zeit zu retten. So ist auch der Wille unseres Gottes und Vaters,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'dem Ehre ist von Ewigkeit zu Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Ich wundere mich, daß ihr so schnell euch abwendig machen laßt von dem, der euch in der Gnade Christi berufen hat, zu einem anderen Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Es gibt doch kein anderes. Allein, manche wollen euch verwirren und das Evangelium Christi verfälschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Doch wenn wir selbst oder sogar ein Engel vom Himmel das Evangelium euch anders verkündeten, als wir es euch verkündet haben, der sei verflucht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Ich wiederhole, was ich eben sagte: Wer euch das Evangelium anders predigt, als ihr es empfangen habt, der sei verflucht!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Rede ich jetzt Menschen oder Gott zulieb? Suche ich etwa Menschen zu gefallen? Wenn ich noch Menschen zu gefallen suchte, dann wäre ich nicht Christi Knecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Liebe Brüder, ich versichere euch: Das Evangelium, das ich verkünde, ist nicht Menschenwerk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Denn nicht von einem Menschen habe ich es übernommen, auch nicht durch Unterricht gelernt, sondern durch Offenbarung Jesu Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Ihr habt von meinem früheren Wandel im Judentum gehört, wie ich die Gemeinde Gottes über die Maßen verfolgte und sie zugrunde zu richten suchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Ich zeichnete mich an jüdischer Gesinnungstüchtigkeit vor vielen meiner Altersgenossen in meinem Volke aus und eiferte ganz übertrieben für die väterlichen Überlieferungen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Doch da gefiel es dem, der mich vom Mutterschoß an ausersehen und mich kraft seiner Gnade berufen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'in mir seinen Sohn zu offenbaren, damit ich ihn der Heidenwelt verkünde. Von Anfang an zog ich nicht Fleisch und Blut zu Rate,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'noch ging ich nach Jerusalem hinauf zu denen, die vor mir Apostel waren; nein, ich ging fort nach Arabien und kam dann wieder nach Damaskus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Erst dann, drei Jahre später, ging ich nach Jerusalem, um dort Kephas persönlich kennenzulernen. Ich hielt mich vierzehn Tage bei ihm auf.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Sonst sah ich keinen der anderen Apostel, den Jakobus, den Bruder des Herrn, ausgenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Was ich da schreibe - ich bezeuge es vor Gott -, ist keine Lüge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Darauf kam ich in die Gegenden von Syrien und Cilizien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Den Christengemeinden in Judäa blieb ich also persönlich unbekannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Sie hatten nur gehört: Der einstens uns verfolgt hat, verkündet jetzt den Glauben, den er vorher zu vernichten suchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Und sie priesen Gott um meinetwillen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Vierzehn Jahre später ging ich wieder nach Jerusalem hinauf mit Barnabas; auch Titus nahm ich mit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Ich unternahm die Reise auf eine Offenbarung hin. Ich legte ihnen das Evangelium vor, das ich bei den Heiden verkündige. Ganz besonders tat ich es vor den Maßgebenden; ich wollte nämlich nicht vergeblich laufen oder gelaufen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Doch nicht einmal mein Begleiter Titus, ein Grieche, ward zum Empfang der Beschneidung angehalten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'obwohl sich falsche Brüder eingeschlichen und eingedrängt hatten. Die lagen auf der Lauer gegen unsere Freiheit, die wir in Christus Jesus besitzen; sie wollten uns zu Sklaven machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Doch gaben wir ihnen nicht einen Augenblick nach, daß wir uns etwa unterworfen hätten, damit bei euch das echte Evangelium bleibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Von den Maßgebenden - wie immer sie waren, ist mir gleichgültig; vor Gott gibt es kein Ansehen der Person -, die Maßgebenden also haben mir nichts weiter mitgeteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Im Gegenteil, sie haben eingesehen, daß ich mit dem Evangelium für die Unbeschnittenen betraut bin, wie Petrus mit dem für die Beschnittenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Denn der dem Petrus seinen Beistand lieh zu dem Apostelwirken unter den Beschnittenen, stand auch mir zur Seite bei den Heiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Als sie erkannten, daß mir eine ganz besondere Gnade verliehen ward, da gaben Jakobus, Kephas und Johannes, die doch als \"Säulen\" gelten, mir und dem Barnabas die rechte Hand zum Zeichen der Gemeinschaft. Wir sollten zu den Heiden, sie wollten darin zu den Beschnittenen gehen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'nur sollten wir der Armen gedenken. Das habe ich auch gewissenhaft getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Als Kephas nach Antiochien kam, trat ich ihm Aug\' in Aug\' entgegen; denn er war schon gerichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Bevor nämlich einige aus der Umgebung des Jakobus gekommen waren, pflog er Tischgemeinschaft mit den Heiden. Nach ihrer Ankunft aber zog er sich zurück und sonderte sich von ihnen ab, weil er sich vor den Beschneidungsmännern fürchtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Mit ihm verstellten sich dann auch die anderen Juden, ja, Barnabas sogar ließ sich durch ihre Verstellung mitreißen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Als ich nun sah, daß ihre Handlungsweise dem echten Evangelium nicht entspräche, da sagte ich vor allen anderen zu Kephas: \"Wenn du als Jude nach heidnischer und nicht nach jüdischer Gewohnheit lebst, wie magst dann du die Heiden zwingen, die jüdische Gewohnheit anzunehmen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Wir sind Juden von Geburt und nicht Sünder aus der Heidenwelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Wir wissen aber, daß der Mensch gerecht wird nicht auf Grund von Werken des Gesetzes, sondern durch den Glauben an Jesus Christus. Wir haben ja den Glauben an Christus Jesus angenommen, damit wir gerecht wurden durch den Glauben an Christus und nicht durch Werke des Gesetzes; denn durch Gesetzeswerke wird kein Mensch gerecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Doch würden wir bei unserem Streben, in Christus gerecht zu werden, doch also Sünder erfunden, wäre dann nicht Christus Diener der Sünde? Nein, nimmermehr!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Denn wenn ich das, was ich eingerissen habe, von neuem wieder aufbaue, dann erweise ich mich selbst als Übertreter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Denn durch Gesetz bin ich dem Gesetz abgestorben, um nur für Gott zu leben; mit Christus bin ich an das Kreuz geheftet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Ich lebe, aber nicht mehr ich, Christus lebt in mir. Soweit ich aber jetzt noch im Fleische lebe, lebe ich im Glauben an den Gottessohn, der mich geliebt und sich selbst für mich geopfert hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Ich tue der Gnade Gottes keinen Eintrag; denn wenn Rechtfertigung durch das Gesetz käme, dann wäre Christus umsonst gestorben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ihr unverständigen Galater! Wer hat euch denn behext der Wahrheit nicht zu gehorchen, euch, denen Jesus Christus vor Augen gezeichnet ward als der Gekreuzigte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Nur dieses eine möchte ich von euch wissen: Habt ihr den Geist empfangen durch Werke des Gesetzes oder durch die Botschaft des Glaubens?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Seid ihr denn so unverständig? Ihr habt im Geiste begonnen und wolltet nun im Fleisch enden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'So Schweres wolltet ihr umsonst erduldet haben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Wahrlich, umsonst! Der euch den Geist verleiht und Wunder bei euch wirkt, tut er das der Gesetzeswerke wegen oder aus dem Hören des Glaubens?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Es ist so wie bei Abraham: \"Er glaubte Gott, und dies ward ihm als Gerechtigkeit angerechnet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'So wisset denn: die aus dem Glauben stammen, sind Kinder Abrahams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Da nun die Schrift vorausgesehen hat, daß Gott die Heiden rechtfertige aus dem Glauben, so verkündet sie von vornherein dem Abraham die frohe Kunde: \"Alle Völker sollen in dir gesegnet werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'So werden also die, die aus dem Glauben kommen, mit Abraham, dem Glaubenden, gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Denn alle, die sich an Gesetzeswerke halten, stehen unter dem Fluche. Denn also steht geschrieben: \"Verflucht sei jeder, der nicht alles treulich hält, was im Buche des Gesetzes vorgeschrieben ist, damit es gehalten werde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Daß aber niemand durch das Gesetz vor Gott gerecht wird, ist klar, denn: \"Der aus dem Glauben Gerechte wird leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Das Gesetz jedoch stammt nicht aus dem Glauben, denn also heißt es: \"Wer das tut, wird dadurch leben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Von dem Fluche des Gesetzes hat uns Christus erlöst dadurch, daß er unseretwegen selbst zum Fluche ward, wie denn geschrieben steht: \"Verflucht sei jeder, der am Holze hängt.\'');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'So sollte denn der Segen Abrahams auf die Heiden übergehen in Christus Jesus: wir sollten durch den Glauben den verheißenen Geist empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Liebe Brüder, ich will ein Gleichnis aus dem Leben bringen: Ein Testament, das rechtsgültig ist, stößt niemand um, noch fügt man ihm einen Zusatz an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Die Verheißungen wurden aber dem Abraham und seinem Nachkommen zugesagt. Nun heißt es nicht: \"den Nachkommen\" in der Mehrzahl, vielmehr in der Einzahl: \"deinem Nachkommen\"; damit ist Christus gemeint.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ich denke nun, ein Testament, das früher schon durch Gott rechtskräftig ward, kann nicht durch das Gesetz, das erst vierhundertdreißig Jahre später kam, noch umgestoßen werden, so daß die Verheißung dadurch nichtig würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Denn würde das Erbe durch Gesetz erlangt, dann käme es nicht mehr durch die Verheißung; dem Abraham jedoch hat Gott es durch Verheißung in Gnaden geschenkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Welchen Zweck hat aber dann das Gesetz? Es kam der Sünden wegen dazu, bis der Nachkomme auftreten würde, dem die Verheißung gilt. Durch Engel angeordnet, kam es aus der Hand eines Mittlers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ein Mittler ist aber nicht für einen allein da; Gott jedoch ist nur Einer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'So stünde also das Gesetz im Widerspruch zu dem, was Gott verheißen hat? Gewiß nicht. Wenn ein Gesetz gegeben worden wäre, das Leben hätte schaffen können, dann käme in der Tat die Rechtfertigung aus dem Gesetze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Allein die Schrift hat alles unter Sünde eingeschlossen, damit die Verheißung den Gläubigen gegeben werde auf Grund des Glaubens an Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Denn bevor der Glaube kam, wurden wir unter dem Gesetz eingeschlossen, im Gewahrsam für den Glauben, der erst geoffenbart werden sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'So ward uns das Gesetz ein Erzieher zu Christus, damit wir gerecht würden durch den Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Da aber jetzt der Glaube gekommen ist, stehen wir nicht mehr unter dem Erzieher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Denn ihr alle seid Kinder Gottes durch den Glauben an Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Ihr alle, die ihr auf Christus getauft seid, habt Christus angezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Jetzt gibt es nicht mehr Juden oder Heiden, nicht mehr Sklaven oder Freie, nicht mehr Mann noch Weib; denn ihr alle seid Einer in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Wenn ihr aber Christus angehört, dann seid ihr Nachkommen Abrahams und Erben, wie es verheißen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Ich sage nun: Solange der Erbe noch nicht mündig ist, unterscheidet er sich in nichts von einem Sklaven, obgleich er Herr von allem ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Er steht vielmehr unter Vormündern und Verwaltern bis auf die vom Vater festgesetzte Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'So war es auch bei uns: Solange wir noch nicht mündig waren, lebten wir geknechtet unter den Weltgeistern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Da kam die Fülle der Zeit, und Gott sandte seinen Sohn, der, vom Weib geboren, dem Gesetz unterworfen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Er sollte die, die unter dem Gesetze standen, loskaufen, und wir sollten die Annahme an Sohnes Statt erhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Weil ihr nun Söhne seid, so sandte Gott in unsere Herzen den Geist seines Sohnes, und dieser ruft:\"Abba!\" \"Vater!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'So bist du also nicht mehr Sklave, sondern Sohn; wenn aber Sohn, dann Erbe durch Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Damals freilich, als ihr Gott nicht kanntet, da dientet ihr den Göttern, die es in Wirklichkeit doch gar nicht gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Jetzt aber erkennt ihr Gott, vielmehr, ihr seid von Gott erkannt. Wie könnt ihr euch wiederum den schwachen und armseligen Geistern zuwenden und ihnen noch einmal von neuem dienstbar werden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Ihr beobachtet ja Tage, Monate, Festzeiten und Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Ich fürchte für euch, ob ich mich nicht vergeblich unter euch abgemüht habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Liebe Brüder, ich bitte euch, werdet wie ich! Auch ich bin euch gleich geworden, ihr habt mir nichts zuleid getan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Ihr wißt, wie ich in körperlicher Schwachheit euch damals das Evangelium verkündet habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Jedoch trotz der Prüfung, die für euch in meinem schwachen Zustande lag, habt ihr mich nicht verachtet noch vor mir ausgespuckt, vielmehr mich aufgenommen wie einen Engel Gottes, ja wie Christus Jesus selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Wo ist jetzt eure freudige Begeisterung? Ich kann es euch bezeugen: Ihr hättet, wenn es möglich wäre, euch die Augen ausgerissen und sie mir gegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Bin ich denn nunmehr euer Feind geworden, weil ich euch die Wahrheit Sage?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Jene werben um euch nicht in guter Absicht. Sie möchten euch abwendig machen, damit ihr sie alsdann umwerbet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Es ist ja schön, wenn man umworben wird, allerdings nur in einer guten Sache und allezeit und nicht bloß, solange ich bei euch bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Liebe Kinder! Von neuem liege ich mit euch in Wehen, bis Christus in euch Gestalt gewonnen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Ich möchte jetzt bei euch sein und einen anderen Ton anschlagen können; in großer Sorge bin ich euretwegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Sagt mir, ihr, die ihr so gern unter dem Gesetz stehen möchtet: Hört ihr das Gesetz nicht?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Es steht geschrieben: \"Abraham hatte zwei Söhne, den einen von der Magd, den anderen von der Freien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Der Sohn der Magd war natürlich geboren worden; der Sohn der Freien aber durch Verheißung.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Das ist bildlich zu verstehen: Diese (Frauen) sind die beiden Testamente; das eine das Testament vom Berge Sinai, das nur Knechte gebiert, das ist die Agar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Agar bedeutet nämlich den Berg Sinai in Arabien. Es entspricht dem jetzigen Jerusalem, das samt den Kindern in der Knechtschaft ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Doch frei ist das Jerusalem dort oben, und das ist unsere Mutter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Es steht ja auch geschrieben: \"Freu dich, du unfruchtbare, die du nicht geboren hast, o juble laut du, die du keine Wehen kennst! Zahlreicher sind die Kinder der Vereinsamten als die der Vermählten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Ihr aber, liebe Brüder, seid, wie Isaak, Kinder der Verheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Wie aber damals der natürlich Geborene den nach dem Geiste Geborenen verfolgte, so ist es auch heute noch. Was sagt jedoch die Schrift?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, '\"Verstoße die Magd und ihren Sohn; der Sohn der Magd darf nicht mit dem Sohn der Freien erben!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'So sind wir also, meine lieben Brüder, nicht Kinder der Magd, sondern der Freien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Für die Freiheit hat Christus uns befreit. So steht denn fest und laßt euch nicht wieder das Joch der Sklaverei aufbürden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Seht! Ich, Paulus, sage euch:Wenn ihr euch beschneiden laßt, dann nützt euch Christus nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Und noch einmal versichere ich jedem, der sich beschneiden läßt: Er ist dann verpflichtet, das ganze Gesetz zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Ihr seid von Christus losgetrennt, wenn ihr euch durch das Gesetz Rechtfertigung zu verschaffen sucht; ihr geht dann der Gnade verlustig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Denn wir erwarten die Rechtfertigung, auf die wir hoffen, durch den Geist in Kraft des Glaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'In Christus Jesus nützt die Beschneidung nichts noch das Unbeschnittensein, sondern Glaube, der durch die Liebe wirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Ihr waret in so gutem Lauf. Wer hat euch aufgehalten, daß ihr der Wahrheit nicht mehr folgen wollt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Die Umstimmung kommt nicht von dem, der euch berufen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Ein wenig Sauerteig durchsäuert den ganzen Teig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ich habe zu euch das Vertrauen im Herrn, daß ihr nicht anderen Sinnes werdet. Doch wird sein Urteil ertragen müssen, mag sein, wer es will, wer bei euch Verwirrung stiftet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Wenn ich aber, liebe Brüder, noch die Beschneidung predigte, warum werde ich dann noch verfolgt? Dann ist ja das Ärgernis des Kreuzes aus der Welt geschafft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Möchten doch die, die euch verwirren, sich gleich entmannen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Zur Freiheit seid ihr berufen worden, liebe Brüder. Mißbraucht aber die Freiheit nicht als einen Vorwand für ein Leben nach dem Fleische; nein, dient einander in Liebe!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Denn das ganze Gesetz ist mit dem einen Wort erfüllt: \"Du sollst deinen Nächsten lieben wie dich selbst!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Wenn ihr jedoch einander beißt und auffreßt, seht dann nur zu, daß ihr nicht voneinander aufgefressen werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Ich sage: Wandelt im Geiste, dann werdet ihr die Lüste des Fleisches nicht mehr vollbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Das Fleisch gelüstet es ja gegen den Geist, des Geistes Begehren widerspricht dem Fleische; sie liegen in Streit miteinander, so daß ihr das nicht tut, was ihr möchtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Laßt ihr euch aber vom Geiste leiten, dann steht ihr nicht unter dem Gesetze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Offenkundig sind die Werke des Fleisches, zum Beispiel Unzucht, Unkeuschheit Schamlosigkeit, Wollust,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Abgötterei, Zauberei, Feindschaft, Streit, Eifersucht, Zorn, Zwietracht, Spaltungen, Parteien,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Neid Mord, Trunkenheit, Schlemmerei und anderes dergleichen. Was ich euch früher schon gesagt habe, das wiederhole ich: Die solches treiben, werden das Reich Gottes nicht erben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Des Geistes Frucht dagegen ist: Liebe, Freude, Friede, Langmut, Wohlwollen, Güte, Vertrauen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Sanftmut Keuschheit und Enthaltsamkeit. Dem steht das Gesetz auf keinen Fall entgegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Die aber Christus Jesus angehören, haben ihr Fleisch mitsamt den Leidenschaften und den Lüsten ans Kreuz geschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Wenn wir nun durch den Geist das Leben haben, dann laßt uns auch im Geiste wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Laßt uns nicht nach eitlem Ruhme trachten und nicht einander reizen und gegenseitig uns beneiden!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Liebe Brüder! Wenn einer in der Übereilung einen Fehltritt tut, dann weist ihn, die ihr Geistesmänner seid, im Geiste der Sanftmut zurecht. Doch achte dabei auf dich selbst, damit nicht auch du in Versuchung kommst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Der eine trage die Last des anderen. Also erfüllt ihr das Gesetz Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Denn wer sich schmeichelt, er habe etwas zu bedeuten, während er doch nichts ist, betrügt sich selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Jeder prüfe nur sein eigenes Handeln, dann wird er seinen Ruhm für sich behalten und andere damit verschonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Hat doch ein jeder an seiner eigenen Last zu tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Wer in der Lehre Unterricht erhält, der soll dem Lehrer Teil an all seiner Habe geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Täuscht euch nicht: Gott läßt seiner nicht spotten. Was der Mensch sät, wird er ernten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Wer auf sein Fleisch sät, wird vom Fleische Verderben ernten; wer aber auf den Geist sät, wird vom Geiste das ewige Leben ernten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Laßt uns im Gutestun nicht müde werden! Denn schließlich werden wir doch einmal ernten, wenn wir nicht nachlassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'So lasset uns denn allen Gutes tun, solange wir noch Gelegenheit dazu haben, besonders aber unseren Glaubensgenossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Seht, mit was für großen Buchstaben ich euch eigenhändig schreibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Alle, die bei den Menschen eine Rolle spielen möchten, wollen euch die Beschneidung aufnötigen, nur damit sie um des Kreuzes Christi willen nicht verfolgt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Und dabei halten sie, obwohl beschnitten, nicht einmal selber das Gesetz. Nur deshalb wollen sie euch ja beschneiden, damit sie sich mit eurem Fleische rühmen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Mir aber sei es ferne, mich zu rühmen, es sei denn im Kreuz unseres Herrn Jesus Christus. Durch ihn ist mir die Welt gekreuzigt und ich der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Denn in Christus Jesus weder die Beschneidung noch das Unbeschnittensein hat Wert, vielmehr nur eine Neuschöpfung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Über alle, die nach diesem Grundsatz wandeln, komme Friede und Erbarmen und über das Israel Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'In Zukunft mache mir keiner Unannehmlichkeiten; ich trage ja die Male des Herrn Jesu an meinem Leibe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste, liebe Brüder. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, Apostel Jesu Christi durch den Willen Gottes, den Heiligen und Gläubigen in Christus Jesus in Ephesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus! Er, der uns im Himmel gesegnet hat in Christus mit aller Art von Geistessegen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'So wie er uns in ihm vor Grundlegung der Welt erwählt hat, auf daß wir heilig seien vor ihm und tadellos.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Er, der uns in Liebe zu seinen Kindern vorherbestimmte durch Jesus Christus, weil so sein Wohlgefallen es gewollt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'damit wir jubeln ob der Herrlichkeit seiner Gnade, die er in seinem Liebling gnädig uns verliehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'In ihm besitzen wir Erlösung durch sein Blut, Vergebung unserer Sünden dank seiner überreichen Gnade,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'die er reichlich auf uns überströmen ließ samt aller Weisheit und Erkenntnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Er tat uns kund, was er geheimnisvoll gewollt, wie er es sich in seiner Liebe in ihm vorgenommen hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Er wollte es in der Zeiten Fülle erreichen, daß alles wieder unter einem Haupte, unter Christus, stünde, was im Himmel und auf Erden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'In ihm sind wir als Erben gleichfalls reich bedacht, die wir vorausbestimmt gewesen nach dem Plane dessen, der alles nach dem Ratschluß seines Willens wirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'So sollten wir zum Lobe seiner Herrlichkeit gereichen, nachdem wir längst zuvor auf Christus unsere Hoffnung aufgebaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Als ihr das Wort der Wahrheit, die frohe Botschaft eures Heils, vernommen und als ihr dann geglaubt habt, seid auch ihr in ihm mit dem verheißenen Heiligen Geiste besiegelt worden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Ist er doch unseres Erbes Unterpfand, das uns den Loskauf seines Eigentums verbürgt zum Lobe seiner Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Seitdem ich von eurem Glauben an den Herrn Jesus hörte sowie von eurer Liebe zu allen Heiligen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'sage ich um euretwillen unablässig Dank, bei meinem Beten euer eingedenk.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Möge der Gott unseres Herrn Jesus Christus, der Vater der Verherrlichung, den Geist der Weisheit und der Offenbarung euch verleihen, damit ihr ihn erkennet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Möge er die Augen eures Herzens hell erleuchten, damit ihr so begreift, zu welcher Hoffnung ihr berufen seid, wie herrlich reich sein Erbe bei den Heiligen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'wie überwältigend groß seine Macht an uns ist, die wir gläubig wurden auf Grund der großen Wirkung seiner Kraft,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'die er erwiesen hat an Christus, als er ihn von den Toten auferweckte und ihn in Himmelshöhen zu seiner Rechten sitzen hieß,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'hoch über alle Macht und Kraft und über Herrschaft und Gewalt, ja, über jedes Wesen, das es in dieser Welt und in der Welt der Zukunft gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Er legte ihm das ganze All zu Füßen, ihn aber machte er zum Haupte der Kirche, das alles überragen sollte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'der Kirche, die sein Leib ist, die ganze Fülle dessen, der das All allüberall erfüllt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Ihr waret tot infolge eurer Übertretungen und Sünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'in denen ihr einst nach dem Zeitgeist dieser Welt gewandelt seid, nach dem Fürsten der Gewalt der Luft, des Geistes, der noch immer in den Kindern des Ungehorsams wirksam ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Darunter wandelten auch wir einst alle mit unseren fleischlichen Gelüsten. Wir taten, was das Fleisch und Herz begehrte, und waren von Natur Kinder des Zornes, genau so wie die anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Gott aber, der reich ist an Erbarmen, hat auch uns in seiner großen Liebe, in der er uns so sehr geliebt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'obwohl wir unserer Sünden wegen tot waren, dennoch mit Christus zusammen wieder auferweckt zum Leben. Aus Gnade seid ihr gerettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Er hat in Christus Jesus uns auch miterweckt und mit ins Himmelreich versetzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Um in den Zeiten, die da kommen werden, den übergroßen Reichtum der Gnade aufzuzeigen, aus lauter Güte gegen uns in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Durch Gnade seid ihr kraft des Glaubens gerettet, und zwar nicht als euer eigenes Verdienst; Gottes Gabe ist es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Nicht aus Werken, damit sich keiner rühmen könne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Wir sind ja sein Geschöpf, in Christus Jesus für gute Werke geschaffen, die Gott bereitet hat im voraus, damit wir eifrig in ihnen wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Darum bedenkt, daß ehemals ihr, die Heiden von Geburt - die \"Beschnittenen\", die am Leibe von Menschenhänden beschnitten sind, heißen euch \"Unbeschnittene\" -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'in jener Zeit ohne Christus gelebt habt, ausgeschlossen aus Israels Gemeinde, ohne Anteil am Bunde der Verheißung, ohne Hoffnung, ohne Gott in dieser Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Doch jetzt seid ihr, die ihr einst ferne wart, in Christus Jesus nahe geworden durch Christi Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Denn er selbst ist unser Friede, der die beiden zu Einem gemacht hat und dadurch, daß er die Scheidewand, das heißt den Zaun, die Feindschaft in seinem Fleische abgebrochen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'das Gesetz der Gebote in seinen Anordnungen außer Kraft gesetzt hat, damit er die beiden in sich zu einem einzigen, neuen Menschen schuf und so Frieden stiftete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Die beiden wollte er in einem Leibe durch das Kreuz mit Gott versöhnen, indem er die Feindschaft dort vernichtete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'So trat er auf und verkündete Frieden euch, den Fernen, und Frieden den Nahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Wir beide haben also durch ihn in einem Geiste den Zutritt zum Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'So seid ihr denn nicht mehr Fremde und Beisassen, sondern Mitbürger der Heiligen und Hausgenossen Gottes,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'aufgebaut auf dem Fundament der Apostel und Propheten, indessen Christus Jesus selbst der Schlußstein ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'In ihm fügt sich der ganze Bau zusammen und wächst zu einem Tempel aus, heilig im Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'auf dem auch ihr zu einer geistigen Gotteswohnung miterbaut seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Um dessentwillen bin ich, Paulus, der Gefangene Christi Jesu, für euch, ihr Heidenchristen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Ihr habt doch sicherlich gehört, wie die Gnade Gottes waltete, die mir für euch gegeben ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Durch eine Offenbarung wurde mir aber das Geheimnis kundgetan, wie ich es kurz beschrieben habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Beim Lesen könnt ihr daraus erkennen, welchen Einblick ich in das Geheimnis Christi habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Dieses ward zu anderen Zeiten den Menschenkindern nicht so geoffenbart, wie es durch den Geist jetzt seinen heiligen Aposteln und Propheten enthüllt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Die Heiden sind in Christus Jesus Miterben, Mitglieder und Mitgenossen der Verheißung durch das Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Sein Diener wurde ich nach Gottes Gnadengabe, die mir durch seine Machtwirkung verliehen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mir, dem geringsten unter den Heiligen, ist diese große Gnade zugefallen, der Heidenwelt den unergründlich tiefen Reichtum Christi zu verkünden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'und es bei allen in das Licht zu stellen, wie das Geheimnis verwirklicht ward, das seit den ewigen Zeiten in Gott verborgen war, der das Weltall schuf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'damit den Mächten und den Kräften in den Himmelshöhen jetzt durch die Kirche die mannigfache Weisheit Gottes kundgetan werde');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'nach jenem ewigen Beschluß, den er in Christus Jesus, unserem Herrn, verwirklicht hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Durch ihn sind wir voll Zuversicht und können, da wir an ihn glauben, jetzt voll Vertrauen nahetreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'So bitte ich euch denn: Verzaget nicht bei meiner Drangsal, die ich für euch leide; denn sie gereicht euch zur Ehre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Deshalb beuge ich meine Knie vor dem Vater unseres Herrn Jesus Christus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'nach dem sich jede Gemeinschaft im Himmel und auf Erden nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Möge er euch nach dem Reichtum seiner Herrlichkeit verleihen, daß ihr durch seinen Geist am innern Menschen mit Kraft gefestigt werdet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'damit Christus durch den Glauben in euren Herzen wohne und ihr in Liebe festgewurzelt und gegründet seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Dann werdet ihr mit allen Heiligen erfassen können die Breite und die Länge und die Höhe und die Tiefe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Dann werdet ihr die Liebe Christi erkennen, die jede Erkenntnis weit überragt, und werdet übervoll von Gottes Fülle werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Ihm aber, der durch die Kraft, die in uns wirksam ist, mehr, über alle Maßen mehr, zu tun vermag, als was wir bitten und ersinnen können,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'ihm sei die Verherrlichung in der Kirche und in Christus Jesus für alle Zeit von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Als der Gefangene im Herrn ermahne ich euch: Wandelt würdig des Berufs, der euch zuteil geworden ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'in aller Demut, Sanftmut, Geduld. Ertragt einander in Liebe;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'seid eifrig darauf bedacht, die Einheit des Geistes zu erhalten durch das Band des Friedens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Es ist nur ein Leib und ein Geist, wie ihr ja auch, als ihr berufen wurdet, zu einer Hoffnung berufen worden seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Es ist auch nur ein Herr, ein Glaube, eine Taufe,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'ein Gott und Vater aller, der über allen und durch alle und in allen wirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Jedem aus uns wurde die Gnade verliehen je nach dem von Christus ausgeteilten Maß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Darum heißt es auch: \"Er stieg zur Höhe auf und führte die Gefangenen mit sich und gab den Menschen seine Gaben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Was setzt das Hinaufsteigen anderes voraus, als daß er vorher unter die Erde hinabgestiegen ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Der herabkam, ist derselbe, der über alle Himmel aufstieg, um so das Weltall zu erfüllen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Und er bestimmte die einen zu Aposteln, die anderen zu Propheten, noch andere zu Evangelisten, zu Hirten und zu Lehrern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Sie sollen so die Heiligen zur Ausübung des Amtes bilden, zum Aufbau des Leibes Christi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'bis wir alle zur Einheit im Glauben kommen und zur vollen Erkenntnis des Sohnes Gottes und zum vollendeten Manne, zum Maß der Reife der Christusfülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Dann sind wir nicht mehr unmündige Kinder, die sich schaukeln und tragen lassen durch jeden Windhauch irgendeiner Lehre, durch der Menschen Trugspiel und durch die Arglist in der Kunst der Irreführung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Nein, an die Wahrheit wollen wir uns halten, in Liebe ganz und gar in den hineinwachsen, der das Haupt ist, Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Von ihm aus fügt und schließt sich der ganze Leib zusammen - und jedes der Gelenke leistet seinen Dienst dabei -, und jedem Teil ist sein ganz bestimmtes Maß der Arbeit zugemessen, und so vollzieht sich das Wachstum des Leibes, bis er sich auferbaut in Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'So sage ich denn und beschwöre euch im Herrn: Wandelt nicht mehr gleich den Heiden, die nach ihrem verkehrten Sinne wandeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Sie sind in ihrem Denken verfinstert, entfremdet einem Leben in Gott; Unwissenheit hält sie umfangen, weil ihr Herz verhärtet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Und unempfindlich wurden sie und gaben sich selbst der Ausschweifung hin, um unersättlich jeder Unreinheit zu frönen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ihr aber habt Christus nicht in solcher Weise kennengelernt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Soweit ihr von ihm gehört habt und über ihn unterrichtet worden seid, so wie es in Jesus Wahrheit ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Legt ab den alten Menschen nach eurem früheren Wandel, der seiner trügerischen Lüste wegen untergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Ihr sollt euch vielmehr durch den Geist in eurem Sinn erneuern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'und anziehen den neuen Menschen, der nach Gott geschaffen ist in wahrer Gerechtigkeit und Heiligkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'So leget denn die Lüge ab; ein jeder rede mit seinem Nächsten die Wahrheit. Wir sind ja Glieder untereinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '\"Wenn ihr zürnt, dann sündigt nicht\". Die Sonne gehe nicht unter über eurem Groll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Gebt dem Teufel nicht Raum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Der Dieb soll nicht mehr stehlen; vielmehr verschaffe er sich durch seiner Hände Arbeit ehrlichen Verdienst, damit er davon dem Bedürftigen noch geben könne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Aus eurem Munde komme keine schlechte Rede, sondern nur gute, die, wo nur immer möglich, zur Erbauung dient und so den Hörern Segen bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Betrübt nicht den Heiligen Geist Gottes, mit dem ihr für den Tag der Erlösung besiegelt seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Und jede Bitterkeit und jeder Zorn und Groll und alles Lärmen, alles Lästern samt aller Bosheit soll euch ferne bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Seid vielmehr gütig und barmherzig gegeneinander, vergebt einander, so wie Gott in Christus euch vergeben hat!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Ihr sollt Nachahmer Gottes sein, als vielgeliebte Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Wandelt in der Liebe, wie auch Christus euch geliebt und sich für uns an Gott als ein köstlich duftendes Opfer hingegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Unzucht und jede Art von Unreinheit und Habsucht werde unter euch nicht einmal erwähnt. So ziemt es sich für Heilige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Auch nicht Zoten, Possenreißerei, leichtfertiges Geschwätz; all das geziemt sich nicht. Dagegen um so mehr Lobpreisung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Denn dies müßt ihr wissen und verstehen: Kein Unkeuscher oder Unreiner oder Habgieriger - ein solcher wäre ein Götzendiener - hat Erbteil am Reiche Christi und Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Niemand täusche euch durch eitles Schwätzen. Um solcher Dinge willen kommt ja der Zorn Gottes auf die, die ungehorsam bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Habt nichts mit solchen gemein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Einst wart ihr Finsternis, jetzt aber seid ihr Licht im Herrn. So wandelt als Kinder des Lichtes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Die Frucht des Lichtes zeigt sich in lauter Güte und Gerechtigkeit und Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Prüft, was dem Herrn gefällig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Laßt euch nicht mit den unfruchtbaren Werken der Finsternis ein; stellt sie vielmehr ans Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Was jene im Verborgenen treiben, das ist zu schändlich, um es auch nur auszusprechen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Doch alles, was man ans Licht stellt, wird vom Licht erhellt; was aber hell erleuchtet wird, das ist ja selbst Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Darum heißt es auch: \"Wach auf, du Schläfer; steh auf von den Toten, und Christus wird dir aufleuchten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'So gebt denn peinlich acht, wie ihr wandelt. Nicht als Unverständige. Nein, wie Verständige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Kauft die Zeit aus! Bös sind die Tage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Deswegen werdet nicht unvernünftig, sucht vielmehr zu verstehen, was der Wille des Herrn ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Berauscht euch nicht im Weine; das führt nur zur Ausschweifung. Werdet vielmehr voll des Heiligen Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'In Psalmen, Hymnen und in frommen Liedern redet zueinander, singt und jubelt dem Herrn in eurem Herzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Dankt allezeit für alles Gott, dem Vater, im Namen unseres Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Ordnet in der Ehrfurcht Christi euch einander unter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Die Frauen seien ihren Männern untergeben wie dem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Der Mann ist ja das Haupt der Frau, wie Christus das Haupt der Kirche ist, er als Erlöser des Leibes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Wie die Kirche Christus untergeben ist, so seien auch die Frauen ihren Männern untertan in allem.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Ihr Männer, liebt eure Frauen, wie auch Christus die Kirche geliebt und sich für sie dahingegeben hat, um sie zu heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Er machte sie rein in der Wassertaufe durch das Wort des Lebens,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'um sich die Kirche herrlich zu gestalten ohne Flecken, ohne Runzel und dergleichen; denn heilig sollte sie sein und ohne Makel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'So müssen auch die Männer ihre Frauen lieben wie ihren eigenen Leib. Wer seine Frau liebt, liebt sich ja nur selbst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Es hat noch niemand sein eigenes Fleisch gehaßt; er hegt und pflegt es vielmehr. So machte es auch Christus mit der Kirche,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'weil wir Glieder seines Leibes sind von seinem Fleisch und von seinem Bein:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '\"Darum verläßt der Mann Vater und Mutter, verbindet sich mit seinem Weibe, und diese beiden werden dann zu einem Fleische.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Dieses Geheimnis ist groß; ich meine es aber in seiner Beziehung zu Christus und zur Kirche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'So geht es denn nicht anders, als daß ein jeder einzelne auch bei euch seine Frau liebe wie sich selbst. Die Frau indessen soll vor dem Mann Ehrfurcht haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Ihr Kinder, seid euren Eltern untertan im Herrn, denn so gehört es sich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '\"Du sollst deinen Vater und deine Mutter ehren\". Dies ist das erste der Gebote, dem eine Verheißung beigegeben ist:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '\"damit es dir wohlergehe und du lange lebest auf Erden\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Ihr Väter aber reizt eure Kinder nicht zum Zorne; erzieht sie in der Zucht und Ermahnung des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Ihr Sklaven, gehorcht euren Herrn auf Erden mit Furcht und Zittern und in der Lauterkeit eures Herzens, wie Christo.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Seid nicht Augendiener, die nur den Menschen zu gefallen suchen. Seid vielmehr Sklaven Christi, die den Willen Gottes aus ganzem Herzen tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Dient willig, als gälte es dem Herrn und nicht dem Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Ihr wißt ja, daß jeder für das Gute, das er tut, vom Herrn seinen Lohn empfängt, sei er nun Sklave oder Freier.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Doch auch ihr, Herren, handelt ihnen gegenüber ebenso. Lasset das Schelten! Ihr wißt ja: Geradeso wie sie habt ihr im Himmel einen Herrn; bei diesem gibt es kein Ansehen der Person.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Im übrigen: Erstarkt im Herrn und in seiner mächtigen Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Zieht Gottes volle Waffenrüstung an, damit ihr den Ränken des Teufels widerstehen könnt!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Denn unser Kampf geht nicht gegen Fleisch und Blut, vielmehr gegen die Mächte und die Kräfte, die Weltbeherrscher dieser Finsternis, die bösen Geister in den Himmelshöhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'So legt denn die volle Waffenrüstung Gottes an, damit ihr am bösen Tage widerstehen könnt und nach erkämpftem vollem Siege das Feld behauptet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'So steht da, umgürtet an den Lenden mit der Wahrheit, bekleidet mit dem Panzer der Gerechtigkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'beschuht an euren Füßen mit der Bereitschaft für das Evangelium des Friedens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Zu all dem nehmt noch den Schild des Glaubens, mit dem ihr alle feurigen Geschosse des Bösen löschen könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Ergreift sodann den Helm zum Schutz und auch das Schwert des Geistes, das heißt das Wort Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Mit lauter Bitten und mit Flehen betet allezeit im Geiste; wacht noch dazu in anhaltendem Gebete für alle Heiligen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'und auch für mich, damit mir das rechte Wort verliehen werde, wenn ich meinen Mund auftun soll, um freimütig das Geheimnis des Evangeliums zu verkünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'dessen Botschafter ich trotz der Fesseln bin, damit ich freimütig darüber rede, wie die Pflicht mir es gebietet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Doch sollt auch ihr erfahren, wie meine Lage ist, wie es mir geht. Dies alles wird euch Tychikus erzählen, der liebe Bruder und treue Diener im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Gerade deshalb sende ich ihn zu euch, damit ihr erfahret, wie es um uns steht, und damit er eure Herzen tröste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Den Brüdern werde Friede zuteil und Liebe samt dem Glauben von Gott, dem Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Die Gnade sei mit allen, die unseren Herrn Jesus Christus in seiner Unvergänglichkeit lieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus und Timotheus, Knechte Christi Jesu, an alle Heiligen in Christus Jesus zu Philippi mitsamt den Bischöfen und Diakonen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ich danke meinem Gott, sooft ich an euch denke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'und flehe allezeit bei all meinem Beten mit Freude für euch alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Ich danke ihm wegen eurer regen Anteilnahme, die ihr für das Evangelium vom ersten Tage bis jetzt bewiesen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Darum habe ich auch die Überzeugung, daß er, der in euch das gute Werk begonnen hat, es auch vollenden werde bis zum Tage Christi Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Nur billig ist es, daß ich so von euch allen denke; trage ich euch doch in meinem Herzen eingeschlossen. Ihr nahmt ja alle teil an meiner Gnade, sowohl als ich gefangen lag als auch da, wo ich das Evangelium verteidigt und bekräftigt habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Gott ist mein Zeuge, wie ich mich nach euch allen sehne in der Liebe Christi Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Und dies erbitte ich, daß eure Liebe immer reicher und reicher werde an Erkenntnis und an jeglicher Erfahrung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'damit ihr das Richtige zu wählen wisset, damit ihr lauter seid und tadellos für den Tag Christi');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'und reich an Frucht der Gerechtigkeit, die aus Jesus Christus stammt, zu Gottes Herrlichkeit und Ruhm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Liebe Brüder! Ich möchte euch wissen lassen, daß meine Lage eher zur Förderung des Evangeliums dient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Es ist ja bei der ganzen Leibwache und sonst noch überall bekannt geworden, daß ich meine Fesseln um Christi willen trage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Auch ward die Mehrzahl der Brüder im Herrn durch meine Fesseln ermutigt und wagt es um so mehr, ganz furchtlos Gottes Wort zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Es verkündigen zwar einige Christus nur aus Neid und Eifersucht, doch andere auch wieder guten Sinnes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Die einen künden Christus aus Liebe, wohl wissend, daß ich zur Rechtfertigung des Evangeliums bestimmt bin;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'die anderen aus Streitsucht, nicht in reiner Absicht und sie gedenken, mir in meinen Banden Trübsal zu bereiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Doch was liegt daran? Wenn nur auf jede Art und Weise, aufrichtig oder hinterhältig, Christus verkündet wird. Dies dient mir zur Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Es wird mich auch weiter freuen. Ich weiß ja, daß es mir zum Heile dienen wird durch euer Beten und durch den Beistand des Geistes Jesu Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Und dem entsprechen auch mein Hoffen und mein Harren, daß ich in nichts zuschanden werde, daß vielmehr, wie schon immer, so auch jetzt an meinem Leibe frei und offen Christus verherrlicht werde, sei es durch mein Leben, sei es durch mein Sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Denn für mich ist das Leben Christus, das Sterben Gewinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Ist es nämlich mir bestimmt, noch im Fleische zu leben, so heißt das für mich Arbeit und Erfolg, und also weiß ich wirklich nicht, was ich vorziehen soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Nach beiden Seiten zieht es mich hin: Ich habe das Verlangen, aufgelöst zu werden und mit Christus zu sein; und das wäre bei weitem schon das Beste -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'im Fleische zu bleiben aber ist viel nötiger um euretwillen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'In dieser Überzeugung weiß ich, daß ich am Leben bleiben und bei euch allen ausharren werde zu eurem Fortschritt wie zu eurer Glaubensfreudigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Dann könnt ihr euch um meinetwillen Christi Jesu noch mehr rühmen, wenn ich wiederum zu euch komme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Wollet doch des Evangeliums Christi würdig wandeln, damit, sollte ich kommen und euch sehen dürfen oder fernbleiben müssen, ich von euch höre, daß ihr feststeht in einem Geiste, in Eintracht für den Glauben an das Evangelium kämpft');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'und euch in keiner Weise von Widersachern zaghaft machen laßt. Dies ist für sie ein Zeichen, daß sie verlorengehen, ihr aber Rettung finden werdet, und dieses Zeichen kommt von Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Ward doch euch die Gnade verliehen, an Christus nicht allein zu glauben, sondern auch für ihn zu leiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Ihr habt ja denselben Kampf, den ihr an mir gesehen habt, von dem ihr jetzt von mir hört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Wenn ihr also auf christliche Ermahnung etwas haltet, auf liebevolles Zureden, auf die Gemeinschaft im Geist, auf herzliches Erbarmen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'so macht meine Freude voll und seid ein Herz in gleicher Liebe, im Sinnen und im Sorgen einig');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'und fern von Streit und eitler Ruhmsucht. In Demut achte jeder den anderen höher als sich selbst,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'keiner sei auf den eigenen Vorteil aus, vielmehr ein jeder auch auf den des Nächsten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Hegt in euch dasselbe Sinnen, wie es Christus Jesus hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Obwohl er sich in der Gestalt Gottes befand, wollte er dennoch nicht gewaltsam an seiner Gottesgleichheit festhalten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'vielmehr entäußerte er sich, nahm Knechtsgestalt an und ward den Menschen ähnlich. Im Äußeren als Mensch erfunden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'erniedrigte er sich selbst und ward gehorsam bis zum Tode, ja bis zum Tod am Kreuze.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Darum hat ihn Gott auch so hoch erhoben und ihm den Namen gnädiglich verliehen, der über alle Namen ist:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Im Namen Jesus sollen sich alle Knie beugen im Himmel, auf der Erde und in der Unterwelt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'und jede Zunge soll laut bekennen zu Gottes, des Vaters, Herrlichkeit: Jesus Christus ist der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Wohlan denn, meine Vielgeliebten! So wie ihr allezeit gehorsam waret, so wirkt nicht bloß, wenn ich zugegen bin, sondern noch viel mehr, solange ich fern bin, euer Heil mit Furcht und Zittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Gott ist es ja, der in euch das Wollen und auch das Vollbringen zustande bringt nach seinem Wohlgefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Tut alles ohne Murren und Bedenken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'damit ihr untadelig und unverdorben seid und Gotteskinder inmitten eines ganz verkehrten und verdorbenen Geschlechts, in dem ihr leuchtet wie die Sterne im Weltall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Haltet fest am Worte des Lebens, mir zum Ruhm am Tage Christi, damit ich nicht vergeblich gelaufen sei und mich nicht vergeblich abgemüht habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Doch wenn ich auch mein Blut vergießen muß zum Opfer und zur Weihe eures Glaubens, so bin ich dennoch froh und freue mich mit euch allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Seid auch ihr darüber froh und freut euch mit mir!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Im Herrn Jesus hoffe ich, daß ich euch den Timotheus bald senden kann. Dann werde ich wieder guten Mutes werden, sobald ich weiß, wie es um euch steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Ich habe sonst keinen, der diesem gleichgesinnt und so aufrichtig für euch besorgt gewesen wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Alle anderen denken nur an sich und nicht an die Sache Christi Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ihr wisset, wie er sich bewährt hat; gleich wie ein Sohn dem Vater, so hat er mit mir dem Evangelium gedient.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Ihn also hoffe ich zu senden, sobald ich meine eigene Lage überschauen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ich habe indessen die Zuversicht im Herrn, daß ich auch selbst bald kommen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Doch hielt ich es für nötig, den Epaphroditus zu euch zu senden. Er ist mein Bruder, Mitarbeiter und mein Mitkämpfer; für euch ist er Apostel und Diener für alles, was ich brauche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Er war in Sehnsucht nach euch allen und in banger Sorge, weil ihr von seiner Krankheit gehört hattet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Er war tatsächlich todkrank; doch Gott erbarmte sich seiner, und nicht nur seiner, sondern auch meiner, damit ich nicht Trauer über Trauer hätte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Um so mehr beeile ich mich, ihn abzusenden, auf daß ihr die Freude des Wiedersehens habt und ich so einer Sorge ledig bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'So nehmt ihn denn im Herrn in aller Freude auf und haltet solche Männer wohl in Ehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Denn um des Werkes Christi willen kam er dem Tode nahe, und mutig wagte er sein Leben, um im Dienste für mich das zu ersetzen, was ihr nicht leisten konntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Im übrigen, o meine lieben Brüder, freuet euch im Herrn! Das Gleiche euch zu schreiben, ist keine Last für mich, für euch bedeutet es aber Sicherheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Nehmt euch vor den Hunden in acht, nehmt euch in acht vor schlechten Arbeitern, nehmt euch in acht vor der Zerschneidung!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Die richtige Beschneidung sind doch wir, die geistigen Gottesdiener, die wir uns in Christus Jesus rühmen und nicht dem Fleische vertrauen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'obwohl ich auch dem Fleische vertrauen könnte. Wenn irgendeiner meint, er könne auf das Fleisch vertrauen, so könnte ich erst recht dies tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Ich bin am achten Tage beschnitten, bin aus dem Volke Israel und aus dem Stamme Benjamin und ein Hebräer von hebräischen Ahnen; ich war gesetzestreuer Pharisäer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'voll Eifer verfolgte ich die Kirche Gottes, von tadellosem Wandel, was die Gerechtigkeit betrifft, die aus dem Gesetze stammt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Doch was mir einstens als Gewinn erschien, das habe ich um Christi willen für wertlos erachtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Ich erachte übrigens gar alles für wertlos; denn weit wertvoller ist die Erkenntnis meines Herrn Christus Jesus, für den ich alles preisgegeben habe. Geradezu für Kehricht halte ich es, um Christus dadurch zu gewinnen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'damit ich in ihm gefunden werde, und dies nicht mit meiner Gerechtigkeit aus dem Gesetze, vielmehr mit der Gerechtigkeit aus dem Glauben an Christus, die aus Gott stammt, ruhend auf dem Glaubensgrund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'So werde ich ihn erkennen und die Macht seiner Auferstehung sowie die Gemeinschaft mit seinen Leiden dadurch, daß ich ihm im Tod ähnlich werde,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'in dem Gedanken, zur Auferstehung von den Toten zu gelangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nicht, als hätte ich es bereits erreicht oder als ob ich schon vollendet wäre, jedoch ich jage ihm nach und möchte es ergreifen, wie auch ich von Christus Jesus ergriffen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Brüder! Ich bilde mir nicht ein, es schon erreicht zu haben; eins aber tue ich: Ich vergesse, was hinter mir ist, und strecke mich nach dem, was vor mir liegt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'das Ziel im Auge jage ich dem Kampfpreis nach: der Berufung von droben, von Gott durch Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Wir alle, die wir schon vollendet sind, wollen doch so denken. Doch solltet ihr in einem Punkte anders denken, so wird euch Gott auch dies offenbaren;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'nur müssen wir auf dem betretenen Wege weitergehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Ahmt mich nach, liebe Brüder, und achtet sehr auf die, die nach unserem Vorbild wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Denn viele wandeln, wie ich euch schon oft gesagt habe, jetzt aber unter Tränen wiederhole, als Feinde des Kreuzes Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Ihr Ende ist Verderben, ihr Gott der Bauch, sie setzen ihren Ruhm in ihre Scham; ihr Sinnen geht nur aufs Irdische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Doch unser Staat ist im Himmel, woher wir unseren Erlöser, den Herrn Jesus Christus, erwarten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Er wird dann unseren armseligen Leib verwandeln und seinem verklärten Leibe gleichgestalten mit der Macht, mit der er auch das All sich unterwerfen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Daher, meine lieben, teuren Brüder, meine Freude und mein Kranz, steht fest im Herrn, Geliebte!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Ich mahne die Evodia und mahne die Syntyche, in Eintracht im Herrn zu sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ich bitte, trauter Freund, auch dich: Nimm dich ihrer an! Sie haben sich mit mir fürs Evangelium gemüht, zusammen mit Klemens und den andern Mitarbeitern; ihre Namen stehen im Buche des Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Freuet euch allezeit im Herrn! Ich wiederhole es:, Freuet euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Eure Güte werde allen Menschen kund! Der Herr ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Habt keine Sorge, bringt vielmehr alle eure Anliegen in innigem Gebete mit Dank vor Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Der Friede Gottes, der jedes Begreifen übersteigt, wird eure Herzen und eure Gedanken in Christus Jesus behüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Endlich, Brüder, trachtet nach dem, was wahr, was würdig, was recht, was heilig, was liebenswürdig, was rühmlich, was tugendhaft ist oder sonstwie löblich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Was ihr gelernt und überkommen, gehört und auch an mir gesehen habt, das tut! Der Gott des Friedens wird mit euch sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Eine große Freude war es mir im Herrn, weil ihr endlich einmal wiederum in der Lage wart, für mich zu sorgen. Ihr seid zwar immer so besorgt gewesen, doch hattet ihr nicht die Gelegenheit dazu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nicht so, als wollte ich jetzt von Entbehrungen sprechen; ich habe es ja gelernt, mit den Verhältnissen mich abzufinden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Ich kann in Armut und ich kann im Überflusse leben. Mit allem und mit jedem bin ich wohl vertraut, mit Sattsein und mit Hungerleiden; mit Reichsein und mit Darben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Ja, ich vermag alles, in dem, der mir die Kraft dazu gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Ihr habt gleichwohl gut daran getan, daß ihr euch meiner Not angenommen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Auch ihr wißt es, meine lieben Leute von Philippi: Als ich Mazedonien zu Anfang der Verkündigung des Glaubens verließ, stand keine der Gemeinden mit mir im Verhältnis des Gebens und Empfangens als ihr allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Schon nach Thessalonich habt ihr mehr als einmal mir etwas für meine Not geschickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nicht als ob ich die Gabe suchen würde; ich suche die Frucht in reichster Fülle, die euch gutgeschrieben werden wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Ich habe alles empfangen, und dies im Überfluß; ich bin so reich, seitdem ich eure Gabe durch Epaphroditus empfangen habe. Es war ein lieblicher Duft, ein angenehmes, Gott wohlgefälliges Opfer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mein Gott wird alle eure Wünsche auf das herrlichste erfüllen in Christus Jesus nach seinem Reichtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Gott, unserm Vater, sei Preis in Ewigkeit der Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Grüßt jeden Heiligen in Christus Jesus! Es grüßen euch die Brüder, die bei mir sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Es grüßen euch die Heiligen alle, besonders die vom Hause des Kaisers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Die Gnade des Herrn Jesus Christus sei mit eurem Geiste! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, Apostel Christi Jesu durch den Willen Gottes, und Timotheus, der Bruder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'an die heiligen und christusgläubigen Brüder zu Kolossae. Gnade werde euch zuteil und Friede von Gott, unserem Vater und dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Wir danken Gott und dem Vater unseres Herrn Jesus Christus allezeit, wenn wir für euch beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Wir hörten ja von eurem Glauben in Christus Jesus sowie von eurer Liebe gegen alle Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Ihr übet diese um der Hoffnung willen, die für euch in den Himmeln hinterlegt ist, von der ihr schon durch das wahre Wort des Evangeliums vernommen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Dieses ist ja auch zu euch gelangt, wie es in der ganzen Welt zu finden ist und Früchte trägt und wächst, wie bei euch von dem Tage an, da ihr es gehört und Gottes Gnade in Wahrheit erkannt habt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Sowie ihr von unserem lieben Mitknecht Epaphras unterrichtet worden seid. Er ist für euch ein treuer Diener Christi;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'er ist es auch, der uns von eurer Liebe im Geiste berichtet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'So hören wir auch seit dem Tage, da wir dies vernommen haben, nicht auf, für euch zu beten und zu flehen, ihr möchtet voll Erkenntnis seines Willens werden in aller Weisheit und in geistigem Verständnis;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'ihr möchtet dann in allen guten Werken Früchte bringen und so durch die Erkenntnis Gottes wachsen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'mit aller Kraft begabt, entsprechend seiner so erhabenen Macht. Dann werdet ihr alles mit Geduld und Langmut ertragen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'und auch dem Vater freudig dafür danken, daß er uns fähig machte, am Erbe seiner Heiligen im Lichte teilzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Er hat uns der Gewalt der Finsternis entrissen und in das Reich seines vielgeliebten Sohnes versetzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'In ihm haben wir Erlösung durch sein Blut, die Nachlassung der Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Er ist das Abbild des unsichtbaren Gottes, der Erstgeborene vor aller Schöpfung;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'denn in ihm ist alles erschaffen, was in den Himmeln und auf Erden ist, das Sichtbare und das Unsichtbare, seien es nun Throne oder Herrschaften oder Mächte oder Kräfte. Das alles ist durch ihn und für ihn erschaffen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'er selber ist jedoch vor allem, und alles hat in ihm Bestand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Er ist das Haupt des Leibes, der Kirche; er ist der Anfang und der Erstgeborene von den Toten, um so den Vorrang in allem zu besitzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Und Gott gefiel es, daß die ganze Fülle in ihm wohne,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'und er durch ihn das All auf ihn hin versöhne, was auf Erden und im Himmel ist, indem er durch sein Blut am Kreuze Frieden stiftete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Auch euch, die ihr einst Gott entfremdet, ihm feindlich gesinnt wart durch eure bösen Werke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'hat er in seinem Fleischesleib jetzt durch den Tod versöhnt, um euch heilig, fehlerlos, untadelig vor ihm darzustellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Doch müsset ihr im Glauben unverrückbar fest gegründet sein und dürfet von der Hoffnung des Evangeliums nicht lassen. Ihr habt es vernommen; es ist ja in der ganzen Schöpfung unterm Himmel schon verkündet worden, und ich, Paulus, ward sein Diener.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'So freue ich mich der Leiden für euch, und ich ergänze an meinem Leibe für seinen Leib, die Kirche, was den Leiden Christi mangelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Ich ward ihr Diener kraft des Amtes, das mir Gott zu eurem Nutzen übertragen hat. Ich sollte Gottes Wort durchweg verkünden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'das Geheimnis, das seit Zeit und Ewigkeit verborgen war, jetzt aber seinen Heiligen geoffenbart worden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Gott wollte ihnen zu wissen tun, wie wunderreich dieses Geheimnis bei den Heiden ist: Christus in euch als Hoffnung der Verklärung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Ihn künden wir, indem wir jeden Menschen mahnen, in aller Weisheit jeden Menschen lehren, um so jeden in Christus vollendet darzustellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Dafür nun leide ich und streite ich in seiner Kraft, die mächtig in mir wirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Ich möchte euch zu wissen tun, welch große Sorge ich um euch habe, um die in Laodizea, wie überhaupt um alle, die mich persönlich noch nicht kennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Ich möchte, daß ihre Herzen gefestigt werden, daß sie, vereint in Liebe, zur ganzen reichen Fülle der Einsicht kämen, zur Erkenntnis des Geheimnisses Gottes, das heißt Christus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'in dem alle Schätze der Weisheit und des Wissens verborgen liegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Das sage ich, damit niemand euch durch blendende Gespräche in Verwirrung bringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Denn mag ich körperlich auch ferne sein, geistig bin ich doch bei euch und sehe mit Freuden, wie es gut um euch bestellt, wie euer Christusglaube so gefestigt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Wie ihr den Herrn Christus Jesus kennengelernt habt, so wandelt auch in ihm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'In ihm faßt Wurzel, baut auf ihm euch auf und festigt euch im Glauben, wie man es euch gelehrt hat; von Dankbarkeit strömt über.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Nehmt euch in acht, damit keiner euch einfange durch Weltweisheit und leere Täuschung, die auf Menschenüberlieferung beruht, auf Weltgeistern, aber nicht auf Christus;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'wohnt doch in ihm die ganze Fülle der Gottheit wesenhaft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Ihr habt teil an dieser Fülle in ihm, dem Haupte jeder Macht und Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'In ihm seid ihr auch beschnitten worden, nicht mit einer Beschneidung, die mit der Hand gemacht ward, sondern durch die Ablegung des Fleischesleibes, die Beschneidung in Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Mit ihm seid ihr begraben worden in der Taufe, mit ihm auch auferweckt durch den Glauben an die Macht Gottes, der ihn von den Toten auferweckt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Euch, die ihr durch eure Missetaten und durch euer unbeschnittenes Fleisch tot waret, hat er mit ihm zusammen auferweckt zum Leben. Er hat uns alle Missetaten gnädig vergeben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'und hat den gegnerischen Schuldschein, der mit seinem Inhalt gegen uns lautete, vernichtet und gelöscht, indem er ihn ans Kreuz geheftet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Er hat die Mächte und Gewalten entwaffnet und öffentlich zum Spott gemacht und durch ihn über sie triumphiert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'So soll euch niemand wegen Speise oder Trank oder wegen eines Festes, Neumondes oder Sabbats verurteilen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Dies ist ja nur der Schatten dessen, was erst kommen soll; die Wirklichkeit ist Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Und keiner soll euch um den Siegespreis betrügen, der sich in Kasteiung und in Engeldienst gefällt, der sein Leben nach Erscheinungen einrichtet, ganz ohne jeden Grund in seinem Fleischessinn aufgeblasen ist');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'und nicht am Haupte festhält. Von ihm aus fügt sich der ganze Leib zusammen, mit Sehnen und mit Bändern ausgestattet, und wächst so immer mehr in Gott hinein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Wenn ihr mit Christus den Weltgeistern abgestorben seid, warum laßt ihr euch dann Satzungen aufdrängen, als lebtet ihr noch in der Welt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '\"Faß das nicht an!\" \"Koste auch nicht davon!\" \"Berühre es nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Alle diese Dinge werden durch den Verbrauch vernichtet; Menschensatzungen und Menschenlehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Sie haben zwar den Ruf von Weisheit in ihrer selbstgemachten Frömmelei, Demütigung und Kasteiungen des Leibes; jedoch sie haben keinen Wert und dienen nur der Befriedigung des Fleisches.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Wenn also ihr mit Christus auferweckt seid, dann suchet, was droben ist, wo Christus sitzt zur Rechten Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Denkt an das, was droben ist, und nicht an das, was irdisch ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Ihr seid ja gestorben, und euer Leben ist mit Christus in Gott verborgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Erscheint dann einmal Christus, unser Leben, dann werdet ihr gleichfalls mit ihm in Herrlichkeit erscheinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'So ertötet denn die irdischen Glieder: Unzucht, Unkeuschheit, Leidenschaftlichkeit, böse Lust und Habsucht, die Götzendienst sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Um solcher Dinge willen kommt der Zorn Gottes auf die Kinder des Ungehorsams.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Auch ihr waret diesen Dingen einstens untertan, als ihr noch unter ihnen lebtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Jetzt aber sollt auch ihr das alles ablegen: Zorn, Erbitterung, Bosheit, Lästerung und Zoten aus eurem Munde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Belügt einander nicht! Ihr habt ja den alten Menschen samt seinen Werken völlig ausgezogen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'und den neuen angezogen, der nach dem Bilde seines Schöpfers ständig erneuert wird zur vollen Erkenntnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Da heißt es dann nicht mehr Heide und Jude, Beschnittener und Unbeschnittener; Barbar und Skythe; Sklave und Freier; nein, nur mehr Christus in jeder Beziehung und bei allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Kleidet euch als Gottes Auserwählte, als Heilige und Geliebte mit herzlichem Erbarmen, mit Güte, Demut, Sanftmut und Geduld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Ertragt einander und verzeiht euch gegenseitig gern, wenn einer ob des anderen zu klagen hat. Wie der Herr gnädig euch vergeben hat, so sollt ihr auch tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Doch über all dies legt die Liebe an; das ist das Band der Vollendung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Der Friede Christi herrsche in euren Herzen; zu ihm seid ihr berufen als ein einziger Leib. Und seid dankbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Christi Wort wohne bei euch in seiner ganzen Fülle. Belehrt und ermuntert euch in aller Weisheit! Lobsingt in Dankbarkeit des Herzens Gott mit Psalmen, Hymnen und geistlichen Gesängen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Was immer ihr tut in Wort und Werk, das alles tut im Namen des Herrn Jesus und dankt durch ihn Gott, dem Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ihr Frauen, seid euren Männern untertan. So ziemt es sich im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Ihr Männer, liebet eure Frauen und laßt euch nicht gegen sie erbittern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Ihr Kinder, gehorchet in allem euren Eltern; denn daran hat der Herr sein Wohlgefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ihr Väter, erbittert eure Kinder nicht, damit sie nicht mutlos werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Ihr Sklaven, seid euren irdischen Herrn in allem untertan, nicht als Augendiener, die den Menschen gefallen wollen, sondern mit aufrichtigem Herzen in der Furcht des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Was immer ihr tut, das tut von Herzen gern, wie wenn es für den Herrn geschähe und nicht für Menschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Ihr wisset ja, daß ihr das Erbe vom Herrn als Lohn erhalten werdet. Dient dem Herrn Christus!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Wer Unrecht tut, wird für sein Unrecht bestraft; da gilt kein Ansehen der Person.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Ihr Herren, gewähret euren Sklaven, was recht und billig ist. Bedenkt, daß auch ihr einen Herrn im Himmel habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Seid beharrlich im Gebete; verbindet damit Wachsamkeit und Dankbarkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Betet auch für uns, Gott möge unserer Predigt eine Tür auftun, damit ich das Geheimnis Christi künden könne, um dessentwillen ich gefangen liege,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'daß ich es so kundtue, wie es mir die Pflicht gebietet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Wandelt weise bei den Außenstehenden und kauft die Zeit gut aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Allzeit sei eure Rede liebenswürdig, mit Salz gewürzt, so daß ihr wißt, was ihr einem jeden zur Antwort geben sollt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Wie es mir geht, wird euch Tychikus berichten, der vielgeliebte Bruder, treue Diener und Mitknecht im Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Gerade deshalb schicke ich ihn ja zu euch, damit ihr erfahret, wie es mit uns steht, und er eure Herzen aufmuntere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Onesimus, der treue und geliebte Bruder, euer Landsmann, begleitet ihn. Sie werden euch alles von hier berichten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Es grüßt euch Aristarch, mein Mitgefangener, und Markus, der Vetter des Barnabas. Ihr habt ja über ihn schon Anweisung erhalten. Nehmt ihn auf, wenn er zu euch kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Es grüßt euch ferner Jesus, mit dem Beinamen Justus. Das sind die einzigen aus der Beschneidung, die mir als Mitarbeiter am Reiche Gottes zum Troste geworden sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Es grüßt euch euer Landsmann Epaphras, Knecht Christi Jesu. In seinem Beten ringt er allezeit für euch, daß ihr vollendet dastehen möget und durchaus das erfüllet, was Gottes Wille ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Ich kann es ihm bezeugen, daß er um euch und um die Brüder in Laodizea und um die in Hierapolis sich viele Mühe gibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Es grüßt euch Lukas, der geliebte Arzt, und Demas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Grüßt die Brüder in Laodizea, besonders Nymphas und die Gemeinde in seinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Sobald dieser Brief bei euch vorgelesen ist, dann sorgt dafür, daß er in der Gemeinde von Laodizea gleichfalls vorgelesen werde und daß ihr den aus Laodizea auch zum Lesen bekommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Sagt dem Archippus: Hab acht, daß du das Amt, das du vom Herrn erhalten hast, gut verwaltest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Mein eigenhändiger Gruß: Paulus. Seid meiner Bande eingedenk! Die Gnade sei mit euch!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus, Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott, dem Vater, und im Herrn Jesus Christus. Gnade werde euch zuteil und Friede.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Wir danken Gott allezeit für euch alle, sooft wir bei unseren Gebeten euer gedenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Vor Gott und unserem Vater denken wir unablässig an euren Glauben, der sich in Werken kundgibt, an eure Liebe, die solche Opfer bringt, an eure feste Hoffnung auf unseren Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Wir sind auch überzeugt, von Gott geliebte Brüder, daß ihr erwählt seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Denn unser Evangelium ist nicht bloß in Worten zu euch gekommen, sondern auch in Macht und im Heiligen Geiste und mit großer Überzeugungskraft. Ihr wisset ja, wie wir um euretwillen bei euch aufgetreten sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Und ihr seid unsere sowie des Herrn Nachahmer geworden, da ihr das Wort, trotz vieler Not, doch mit der Freude des Heiligen Geistes angenommen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Ihr wurdet so ein Vorbild für alle Gläubigen in Mazedonien und in Achaia.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Von euch aus ist das Wort des Herrn erklungen nicht bloß in Mazedonien und Achaia, überall ist euer Glaube an Gott kund geworden. Darüber brauchen wir nichts weiter mehr zu sagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Die Leute selbst erzählen es, welch eine Aufnahme wir bei euch gefunden haben und wie ihr euch von den Götzen zu Gott bekehrt habt, um dem lebendigen und wahren Gott zu dienen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'und seinen Sohn, den er von den Toten auferweckt hat, vom Himmel zu erwarten, Jesus, der vor dem kommenden Zorngericht uns errettet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Ihr selber wißt ja, meine Brüder, daß unser Auftreten bei euch nicht vergeblich war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Obgleich wir, wie ihr wisset, schon vorher in Philippi Leiden und Mißhandlungen zu dulden hatten, so haben wir doch im Vertrauen auf unseren Gott den Mut gefunden, euch in heißem Bemühen das Evangelium Gottes zu verkünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Unsere Predigt hat ja nichts zu tun mit trügerischer oder mit unlauterer Absicht oder gar mit Arglist;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'wir reden vielmehr so, wie wir von Gott gewürdigt wurden, mit dem Evangelium betraut zu werden. Wir reden nicht, um Menschen zu gefallen, vielmehr Gott, der unser Herz durchschaut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Gar nie, ihr wißt es, sind wir mit Schmeichelreden noch mit versteckter Habsucht aufgetreten - Gott ist unser Zeuge -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'noch suchten wir Ruhm bei den Menschen, bei euch nicht, noch bei anderen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Wir hätten als Apostel Christi zwar gewichtig auftreten können, doch traten wir in eurer Mitte milde auf wie eine Mutter, die ihre Kinder pflegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Ja, so sehr fühlten wir uns zu euch hingezogen und waren gern bereit, nicht bloß das Evangelium Gottes euch zu bringen, sondern auch unsere Lebenskraft für euch zu opfern; so sehr wart ihr uns lieb geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Brüder, ihr erinnert euch an unsere Mühe und Beschwerde. Wir haben Tag und Nacht gearbeitet, um keinem aus euch zur Last zu fallen; so haben wir euch das Evangelium Gottes verkündet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Ihr und Gott seid dafür Zeugen, wie lauter und gerecht und tadellos wir uns gegen euch, ihr Gläubigen, benommen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Ihr wißt auch, wie wir jeden einzelnen aus euch, gleichwie ein Vater seine Kinder,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'ermahnt und aufgemuntert und beschworen haben, ihr möchtet Gottes würdig wandeln, der euch zu seinem Reich und zu seiner Herrlichkeit berufen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Darum danken wir unablässig Gott dafür, daß ihr unsere Predigt vom Worte Gottes aufgenommen habt, nicht als ein Menschenwort etwa habt ihr sie aufgenommen, vielmehr als das, was sie in Wahrheit ist, als Wort Gottes. Dieses ist auch in euch, den Gläubigen, wirksam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ihr, meine Brüder, seid ja Nachahmer geworden der Gemeinden Gottes in Judäa, die in Christus Jesus sind. Von euren Volksgenossen hattet ihr die gleichen Leiden zu erdulden, wie jene von den Juden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Sie haben sogar den Herrn Jesus und die Propheten getötet und uns verfolgt. Sie sind Gott mißfällig Und allen Menschen feind;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'sie wollen uns hindern, zu den Heiden zu sprechen, damit auch sie gerettet werden. So machen sie das Maß ihrer Sünden ganz und gar voll. Doch der Zorn hat sich schon völlig an ihnen ausgewirkt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Brüder! Wir waren fern von euch, äußerlich, nicht aber dem Herzen nach. Da hatten wir lebhaft und voll Sehnsucht das Verlangen, euch wiederum zu sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Deswegen hatten wir uns vorgenommen, zu euch zu kommen, ich, Paulus, sogar wiederholt; doch Satan hat uns daran gehindert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Denn wer ist unsere Hoffnung, unsere Freude und unser Ruhmeskranz vor unserem Herrn Jesus bei seiner Ankunft, wenn nicht gerade ihr?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Ja, ihr seid unser Ruhm und unsere Freude.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Als wir nicht länger uns gedulden konnten, entschlossen wir uns, in Athen allein zurückzubleiben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'und entsandten den Timotheus, unseren Bruder und Diener Gottes für das Evangelium Christi. Er sollte euch im Glauben stärken und ermuntern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'damit niemand im Glauben sich irremachen lasse in den gegenwärtigen Bedrängnissen. Ihr wißt: Dazu sind wir da.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Schon damals, als wir bei euch waren, sagten wir euch zum voraus, daß wir Drangsale erdulden mußten. Ihr wißt jetzt, daß es auch so kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Deshalb also, weil ich es länger nicht ertragen konnte, habe ich hingesandt, um zu erfahren, wie es um euren Glauben stehe, ob doch nicht etwa der Versucher euch in Versuchung geführt habe und unsere Arbeit vergeblich gewesen sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Jetzt aber ist Timotheus von euch zu uns zurückgekehrt und hat von eurem Glauben und von eurer Liebe uns frohe Kunde gebracht und uns berichtet, daß ihr uns stets in gutem Andenken behaltet voll Sehnsucht, uns noch einmal zu sehen, gleichwie auch wir euch sehen möchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Deswegen, Brüder, sind wir voll des Trostes euretwegen durch euren Glauben, all unserer Not und Drangsal zum Trotz.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Wir leben aber jetzt auf, wenn ihr im Herrn feststeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Wie könnten wir Gott euretwegen genug für all die Freude danken, die wir von unserem Gott um euch empfinden?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Wir beten Tag und Nacht mit übervollem Herzen um die Gnade, euch zu sehen und das zur Vollendung zu bringen, was noch an eurem Glauben fehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Er selbst aber, unser Gott und Vater, und Jesus, unser Herr, lenke unsern Weg zu euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Euch aber lasse der Herr zunehmen und überreich an Liebe werden zueinander und zu allen Menschen, so wie wir euch lieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Er möge eure Herzen stärken, daß sie untadelig und heilig vor Gott und unserem Vater seien bei der Ankunft Jesu, unseres Herrn mit allen seinen Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Im übrigen, meine Brüder, bitten und ermahnen wir euch im Herrn Jesus: Wie ihr es von uns überliefert bekommen habt, wie ihr leben und Gott wohlgefallen sollt, lebt auch wirklich so. Dann werdet ihr immer vollkommener werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Ihr wißt ja, welche Vorschriften wir euch in der Kraft des Herrn Jesus gegeben haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Denn das ist der Wille Gottes: eure Heiligung. Ihr sollt der Unzucht euch enthalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Ein jeglicher aus euch soll es verstehen, in heiliger Zucht und Ehrbarkeit sein Weib sich zu gewinnen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'und nicht in leidenschaftlicher Begierde wie die Heiden, die Gott nicht kennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Es soll sich keiner einen Übergriff erlauben und seinen Bruder geschäftlich hintergehen; denn alle diese straft der Herr, wie wir ja früher schon es euch gesagt und versichert haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Gott hat uns nicht zur Unlauterkeit berufen, vielmehr zur Heiligung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Wer demnach dies mißachtet, mißachtet nicht Menschen, sondern Gott, der euch seinen Heiligen Geist gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Von brüderlicher Liebe braucht man euch nicht zu schreiben: Ihr habt von Gott selbst es gelernt, einander zu lieben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'ihr tut dies ja in ganz Mazedonien an allen Brüdern. Wir ermahnen euch aber, liebe Brüder, darin immer noch mehr zuzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Setzt eure Ehre darein, ein stilles Leben zu führen, eure Angelegenheiten zu besorgen und eurer Hände Arbeit zu verrichten, wie wir euch angewiesen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'So wandelt ihr in Ehren vor den Außenstehenden und braucht niemand in Anspruch zu nehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Meine Brüder, wir wollen euch über die Entschlafenen nicht im Ungewissen lassen, damit ihr nicht trauert wie die anderen, die keine Hoffnung haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Wenn wir glauben, daß Jesus gestorben und auferstanden ist, so wird Gott ebenso auch die Entschlafenen durch Jesus zugleich mit ihm herbeiführen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Das sagen wir euch nach einem Worte des Herrn: Wir, die wir noch am Leben sind, die wir noch für die Ankunft des Herrn übrig sind, wir werden vor den Entschlafenen nichts voraus haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Der Herr wird ja, wenn der Befehl ergeht, beim Schalle der Stimme des Erzengels und der Posaune Gottes vom Himmel niedersteigen. Zuerst erstehen die in Christus Verstorbenen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Dann werden wir, die wir noch am Leben und noch übrig sind, vereint mit jenen auf den Wolken in die Luft entrückt werden, dem Herrn entgegen, und werden so immerdar in Gemeinschaft mit dem Herrn sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Mit diesen Worten also tröstet einander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Von den Zeiten und von den Fristen, meine Brüder, braucht man euch nicht zu schreiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Ihr wißt selbst recht wohl: Der Tag des Herrn kommt wie ein Dieb in der Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Wenn man noch von Frieden und von Sichersein spricht, bricht plötzlich das Verderben über einen her, gleichwie die Wehen über eine Schwangere; sie werden sicher nicht entrinnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Ihr aber, liebe Brüder, bleibt nicht in Finsternis, damit jener Tag euch nicht einem Diebe gleich überrasche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Ihr alle seid Söhne des Lichtes und Söhne des Tages; wir gehören nicht der Nacht an und nicht der Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'So laßt uns also nicht schlafen, wie die übrigen; wir wollen vielmehr wachsam sein und nüchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Wer schläft, der schläft bei Nacht, wer trunken ist, der ist bei Nacht betrunken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Wir aber, die wir dem Tage angehören, wir wollen nüchtern sein, wir wollen mit dem Panzer des Glaubens und der Liebe uns bewaffnen und mit dem Helm der Hoffnung auf das Heil.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Denn Gott hat uns nicht zum Zorne bestimmt, sondern daß wir das Heil erlangen durch unseren Herrn Jesus Christus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'der für uns gestorben ist, damit wir, mögen wir wachen oder entschlafen sein, mit ihm vereinigt leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Darum ermahnt und erbaut einander, so wie ihr es ja auch bisher schon tut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Wir bitten euch, Brüder, zollt denen Anerkennung, die sich bei euch abmühen und eure Vorsteher und Seelsorger im Herrn sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Schätzt sie in liebevollem Sinne ganz besonders hoch um ihres Wirkens willen. Lebt im Frieden miteinander.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Liebe Brüder, wir ermahnen euch, weist Unbotmäßige zurecht und tröstet die Kleinmütigen, nehmt euch der Schwachen an und habt Geduld mit allen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Seht zu, daß keiner Böses mit Bösem vergelte; strebt vielmehr allezeit danach, euch gegenseitig und allen anderen Gutes zu erweisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Freut euch allezeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Betet ohne Unterlaß. Seid in jeder Lage dankbar.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Denn das will Gott von euch in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Löscht den Geist nicht aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Weist prophetische Rede nicht verächtlich zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Prüft alles; das, was gut ist, behaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Haltet euch fern jeder schlechten Art.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Er selbst aber, der Gott des Friedens, heilige euch in vollem Maße. Euer Geist und eure Seele und euer Leib bleibe makellos bis zur Ankunft unseres Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Getreu ist, der euch berufen hat; er wird es auch vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Liebe Brüder, betet auch für uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Grüßt mit heiligem Kusse alle Brüder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Ich beschwöre euch beim Herrn: Laßt allen heiligen Brüdern diesen Brief vorlesen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Die Gnade unseres Herrn Jesus Christus sei mit euch. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus, Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott und unserem Vater und im Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Gnade werde euch zuteil und Friede von Gott, dem Vater, und dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Meine Brüder! Wir fühlen uns Gott zu stetem Dank euretwegen verpflichtet. Also gehört es sich auch; denn euer Glaube nimmt stets überreichlich zu, und auch die gegenseitige Liebe ist bei euch allen übergroß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Darum rühmen wir uns euer vor den Gemeinden Gottes ob eurer Geduld und eures Glaubens, trotz all der Verfolgungen und Drangsale, die ihr auszustehen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Darin zeigt sich eben das gerechte göttliche Gericht: Ihr sollt würdig befunden werden des Reiches Gottes, für das ihr jetzt zu leiden habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Es ist ja nur gerecht von Gott, wenn er mit Bedrängnis euren Bedrängern heimzahlt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'euch Bedrängten aber mit Erquickung lohnt samt uns, wenn sich der Herr Jesus vom Himmel her mit seinen Engelscharen offenbart');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'in Feuerflammen und Vergeltung übt an denen, die Gott nicht kennen, und an denen, die dem Evangelium unseres Herrn Jesus nicht gehorchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Mit ewigem Verderben werden sie es büßen, fern vom Angesicht des Herrn und seiner großen Herrlichkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'wenn er an jenem Tage kommt, um sich in seinen Heiligen zu verherrlichen und wunderbar in allen seinen Gläubigen zu erscheinen; denn bei euch hat unser Zeugnis Glauben gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Darum beten wir auch allzeit für euch, daß unser Gott euch der Berufung würdig mache und jede Freude am Guten in Kraft vollende wie auch das Werk des Glaubens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Der Name unseres Herrn Jesus wird dann in euch verherrlicht werden und ihr in ihm in Kraft der Gnade unseres Gottes und des Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Meine Brüder! Was die Ankunft unseres Herrn Jesus Christus und unsere Vereinigung mit ihm betrifft, so bitten wir euch:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Laßt euch nicht gleich aus der Fassung bringen und in Furcht jagen, weder durch einen Geist, noch durch einen Ausspruch, auch nicht durch einen Brief, der von uns stammen soll, als ob der Tag des Herrn schon da wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Laßt euch von niemand auf keine Weise irremachen. Zuerst muß ja der Mensch der Sünde offenbar werden, der Mensch des Verderbens,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'der Widersacher, der über alles sich erhebt, was Gott heißt oder Heiligtum, so daß er sich selbst in den Tempel Gottes setzt und sich damit zum Gott erklärt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Erinnert ihr euch denn nicht mehr, daß ich euch dieses gesagt habe, als ich noch bei euch war?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Ihr wißt, was ihn jetzt aufhält, bis er zu gegebener Zeit offenbar werden Soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Wohl ist ja das Geheimnis der Gottlosigkeit schon am Werke; nur muß noch der, der es noch aufhält, erst aus dem Wege sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Dann wird der Gottlose offenbar werden. Doch der Herr Jesus wird ihn mit dem Hauche seines Mundes vernichten und ihn verderben durch den Lichtglanz seiner Ankunft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Des anderen Ankunft ist vom Satan bewirkt mit allen trügerischen Machterweisen und mit Wunderzeichen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'und allerlei Verführung zur Schlechtigkeit für die, die verlorengehen, weil sie die Liebe zur Wahrheit, die sie retten sollte, nicht angenommen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Gott sendet ihnen deshalb die Macht der Verführung, damit sie der Lüge glauben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'und so alle dem Gerichte verfallen, die der Wahrheit nicht glaubten, vielmehr an der Ungerechtigkeit ihr Wohlgefallen hatten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Wir aber, vom Herrn geliebte Brüder, müssen allzeit danken um euretwillen. Denn Gott hat euch vom Anfang an zum Heil erwählt durch die Heiligung des Geistes und durch den Glauben an die Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Dazu hat er euch durch unser Evangelium berufen, um an der Herrlichkeit unseres Herrn Jesus Christus teilzunehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'So steht denn fest, meine Brüder! Haltet euch an die Überlieferungen, die ihr mündlich oder schriftlich von uns empfangen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Er aber, Jesus Christus, unser Herr und Gott, unser Vater, der uns geliebt und uns steten Trost und gute Hoffnung gnädiglich verliehen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'ermuntere eure Herzen und stärke sie zu jedem Werk und gutem Wort.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Und endlich, meine Brüder, betet für uns, damit das Wort des Herrn dahineile und verherrlicht werde, wie dies bei euch der Fall gewesen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Betet, damit wir der schlimmen, bösen Menschen ledig werden; nicht alle sind empfänglich für den Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Der Herr jedoch ist treu; er wird euch stärken und vor dem Bösen behüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Wir hegen das Vertrauen zu euch im Herrn, daß ihr, was wir anbefehlen, jetzt und auch in Zukunft tun werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Der Herr aber lenke eure Herzen hin auf die Liebe Gottes und auf die Geduld Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Liebe Brüder, wir gebieten euch im Namen unseres Herrn Jesus Christus: Haltet euch von jedem Bruder fern, der einen ungeordneten Lebenswandel führt und sich nicht an die Lehre hält, die ihr von uns empfangen habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Ihr wißt ja gut, wie ihr uns nachahmen sollt: Wir haben kein unordentliches Leben unter euch geführt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'wir ließen uns von niemand unser Brot schenken; wir haben vielmehr bei Tag und Nacht schwer gearbeitet, um keinem einzigen aus euch zur Last zu fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nicht, als ob wir nicht dazu ein Recht besäßen, sondern um euch ein Beispiel zu geben, das ihr euch zur Nachahmung nehmen solltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Noch als wir bei euch waren, gaben wir euch den Grundsatz: Wer nicht arbeiten will, soll auch nicht essen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Nun hören wir doch, daß einige bei euch ein ungeordnetes Leben führen und nichts schaffen, sondern nur geschäftig tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Solchen sagen und gebieten wir im Herrn Jesus Christus: Sie sollen sich in stiller Arbeit ihr eigenes Brot verdienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Ihr aber, meine Brüder, ermüdet nicht beim Gutestun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Doch wollte einer dem nicht folgen, was wir brieflich anordnen, so merkt ihn euch und meidet jeglichen Verkehr mit ihm, damit er beschämt werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Behandelt ihn aber keineswegs als Feind, sondern weiset ihn zurecht wie einen Bruder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Er aber, der Herr des Friedens, schenke euch Frieden immerdar und auf alle Weise. Der Herr sei mit euch allen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Ich, Paulus, schreibe eigenhändig diesen Gruß. Das ist in jedem Briefe das Erkennungszeichen: So schreibe ich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Apostel Christi Jesu, gemäß dem Auftrag Gottes, unseres Heilandes und Christi Jesu, unserer Hoffnung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'an Timotheus, sein echtes Kind im Glauben. Gnade, Barmherzigkeit und Friede werde dir zuteil von Gott, dem Vater, und von Christus Jesus, unserem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Als ich nach Mazedonien reiste, bat ich dich, in Ephesus zu bleiben. Du solltest da gewissen Leuten einschärfen, sie möchten nicht anders lehren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'auch nicht mit Fabeln und endlosen Geschlechtsregistern sich abgeben. Derlei Dinge fördern mehr Grübeleien als Gottes Heilsordnung, die auf dem Glauben ruht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Das Ziel der Predigt ist aber Liebe aus reinem Herzen, aus trefflichem Gewissen, aus ungeheucheltem Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Doch eben davon sind gewisse Leute abgekommen und auf eitle Schwätzereien verfallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'So wollen sie Gesetzeslehrer sein; doch sie verstehen nicht, was sie sagen, noch was sie so kühn behaupten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Wir wissen: Gut ist das Gesetz, nur muß man es richtig anwenden');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'und sich dabei bewußt bleiben, daß es nicht dem Gerechten gilt, sondern für Frevler, Unbotmäßige, Gottlose, Sünder, Unheilige, Gemeine, für Vatermörder und Muttermörder, Totschläger,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'für Huren, Knabenschänder, Menschenhändler, Lügner und Meineidige und was sonst noch der gesunden Lehre widerstrebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'So lehrt das Evangelium der Herrlichkeit des seligen Gottes, mit dem ich beauftragt bin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Dank weiß ich Christus Jesus, unserem Herrn, der mir Kraft gegeben hat, daß er mich für vertrauenswürdig hielt und mich zum Dienst bestellte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'mich, der ich früher selbst Lästerer, Verfolger und Bedrücker war. Allein, ich fand Erbarmen, weil ich unwissend gehandelt hatte, als ich noch nicht gläubig war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Doch überreichlich ward die Gnade unseres Herrn mit Glaube und mit Liebe in Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Dieses Wort ist wahr und wohl wert, daß es überall angenommen werde: Christus Jesus kam in die Welt, die Sünder zu erretten. Von ihnen bin ich der erste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Gerade darum fand ich auch Erbarmen, damit an mir, als an dem ersten, Jesus Christus seine ganze Langmut zeige, ein Vorbild derer, die an ihn glauben und dadurch zum ewigen Leben gelangen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Dem Könige der Ewigkeiten, dem unsterblichen, unsichtbaren, einzigen Gott sei Ruhm und Herrlichkeit in Ewigkeit der Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ich lege dir nun diese Predigt ans Herz, mein Kind Timotheus, entsprechend den Weissagungen, die auf dich hinzielten, daß du in ihrer Kraft den guten Kampf durchkämpfest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Halte dabei fest den Glauben und ein gutes Gewissen, das einige schon weggeworfen haben und so am Glauben Schiffbruch litten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Darunter sind Hymenäus und Alexander. Ich habe sie dem Satan überantwortet, damit sie das Lästern verlernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Vor allen Dingen dringe ich darauf, daß Gebete, Bitten, Fürbitten sowie Danksagungen verrichtet werden für alle Menschen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'für Könige und jede Obrigkeit, damit wir ein stilles und ruhiges Leben führen in jeglicher Gottseligkeit und Ehrbarkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'So ist es gut und wohlgefällig vor unserem Heiland-Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'der will, daß alle Menschen Rettung finden und zur Einsicht in die Wahrheit kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Es gibt nur einen Gott und einen Mittler zwischen Gott und Menschen, den Menschen Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Er gab sich selbst als Lösegeld für alle hin; zur rechten Zeit ein Zeugnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Dafür bin ich zum Herold und Apostel aufgestellt - ich sage die Wahrheit und lüge nicht -, in ewiger Treue zum Völkerlehrer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Ferner will ich, daß, wo immer die Männer beten, sie heilige Hände erheben ohne Zorn und zweifelnde Bedenken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Desgleichen, daß die Frauen in sittsamer Haltung mit Zucht sich schmücken und mit edlem Anstand und nicht mit Haargeflecht, Gold, Perlen oder mit kostbaren Gewändern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'sondern, wie es sich für Frauen ziemt, die fromm sein wollen, mit guten Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Das Weib soll in aller Unterwürfigkeit und Ruhe lernen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Zu lehren gestatte ich dem Weibe nicht; auch nicht, dem Manne zu befehlen; sie soll sich zurückhaltend zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Denn Adam ward zuerst erschaffen und dann erst Eva.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Auch ließ nicht Adam sich betören; wohl aber ließ sich das Weib völlig betören und kam zu Fall.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Das Heil erlangt sie aber durch Kindergebären, wenn sie ausharrt im Glauben, in der Liebe und in der Heiligung ihrer selbst in einem sittsamen Betragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Es ist ein wahres Wort - Wer nach dem Bischofsamt strebt, begehrt ein herrliches Ding.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Doch muß der Bischof untadelig sein, nur einmal verheiratet, nüchtern, besonnen, sittsam, gastfreundlich und lehrtüchtig,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'nicht dem Trunk ergeben, nicht gewalttätig, im Gegenteil gefällig, nicht streitsüchtig, nicht geldgierig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Er muß imstande sein, dem eigenen Hause wohl vorzustehen und seine Kinder im Gehorsam und in aller Sittsamkeit zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Denn wer sein eigenes Haus nicht zu verwalten weiß, wie sollte der für die Kirche Gottes Sorge tragen können?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Er darf kein Neugetaufter sein, damit er nicht hochmütig werde und ins Gericht des Teufels falle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Endlich muß er ein gutes Zeugnis haben von den Außenstehenden, damit er nicht in üble Nachrede komme und in die Schlinge des Teufels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Auch die Diakone müssen ehrbar sein, nicht doppelzüngig, sie dürfen nicht reichlichem Weingenuß und schändlichem Verdienst ergeben sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Sie müssen das Geheimnis des Glaubens in reinem Gewissen bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Auch diese sollen vorher der Prüfung unterzogen werden und erst dann das Amt ausüben, wenn sie unbescholten sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Ebenso sollen die Frauen ehrbar sein und nicht verleumderisch, sondern nüchtern und in allem zuverlässig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Die Diakone dürfen nur einmal verheiratet sein; sie sollen ihren Kindern und dem Hauswesen gut vorstehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Denn solche, die das Amt des Diakons gut verwaltet haben, erwerben sich eine schöne Stellung und viel Zuversicht im Glauben an Christus Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Das schreibe ich dir, voll Hoffnung, recht bald zu dir zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Doch sollte meine Ankunft sich verzögern, so sollst du wissen, wie man sich im Hause Gottes zu benehmen hat; denn die Kirche des lebendigen Gottes ist eine Säule und Grundfeste der Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Groß ist, wie jeder zugesteht, das Geheimnis der Frömmigkeit: Er, der im Fleische geoffenbart wurde, ward im Geiste gerechtfertigt; er wurde kundgetan den Engeln, verkündet bei den Völkern, in der Welt geglaubt, hinaufgenommen in Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Der Geist sagt bestimmt, daß in den künftigen Zeiten manche vom Glauben abfallen und Irrgeistern und Lehren von den Dämonen sich hingeben werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Menschen, die mit heuchlerischem Sinne Lügen reden und die an ihrem eigenen Gewissen gebrandmarkt sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Menschen, die das Heiraten verbieten und den Genuß gewisser Speisen, die Gott geschaffen hat, damit sie von den Gläubigen, die die Wahrheit erkannt haben, mit Danksagung genossen würden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Denn alles, was Gott geschaffen hat, ist gut und nichts verwerflich, wenn es nur mit Danksagung genossen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Geheiligt wird es ja durch das Wort Gottes und durch Gebet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Wenn du dies den Brüdern ans Herz legst, dann wirst du ein guter Diener Christi Jesu sein, der sich an den Worten des Glaubens und an der rechten Lehre nährt; sie hast du dir ja zur Richtschnur genommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Altweiberfabeln aber und Albernheiten weise ab; übe dich vielmehr für die Frömmigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Die Leibesübung bringt wenig Nutzen, die Frömmigkeit dagegen ist zu allem nützlich, weil sie die Verheißung hat für dieses Leben und für das künftige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Dies Wort ist wahr und wohl wert, daß es allgemein angenommen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Denn dafür mühen wir uns ab und kämpfen wir, weil wir unsere Hoffnung auf den lebendigen Gott gesetzt haben, den Retter aller Menschen, vor allem der Gläubigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Dies sollst du einschärfen und lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Niemand schätze dich deiner Jugend wegen gering. Sei vielmehr ein Vorbild für die Gläubigen im Wort, im Wandel, in Liebe, im Glauben, in der Reinheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Bis ich komme, widme dich der Vorlesung, dem Ermahnen und dem Lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Achte die Gnadengabe in dir nicht gering, die dir verliehen ward zufolge Weissagung und unter der Handauflegung des Presbyteriums.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Nimm dies zu Herzen, gehe ganz darin auf, damit dein Fortschritt allen offenkundig sei.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Achte auf dich selbst und auf die Lehre, halte daran fest. Denn wenn du dies tust, wirst du dich selbst und deine Hörer retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Einen alten Mann sollst du nicht schroff anfahren, sondern rede ihm wie einem Vater zu; den jüngeren Männern rede zu wie Brüdern;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'den älteren Frauen wie Müttern; den jüngeren in aller Ehrbarkeit wie Schwestern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Witwen, die echte Witwen sind, ehre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Wenn aber eine Witwe Kinder oder Enkel hat, so sollen diese es zunächst lernen, die eigene Familie liebevoll zu behandeln und so sich den Vorfahren dankbar zu erweisen; denn das ist vor Gott wohlgefällig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Die wahre Witwe, die vereinsamt ist, hat ihre Hoffnung in Gott und verharrt in Gebet und Flehen Tag und Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Lebt aber eine ausschweifend, so ist sie lebend tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Dies schärfe ein, damit sie untadelig seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Wer aber für die Seinen, zumal für seine Angehörigen, nicht Sorge trägt, der hat den Glauben verleugnet und ist schlimmer als ein Ungläubiger.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Als Witwe soll nur jene ins Verzeichnis eingetragen werden, die wenigstens schon sechzig Jahre alt und nur einmal verheiratet gewesen ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'im Rufe guter Werke steht, wenn sie ihre Kinder gut erzogen, Gastfreundschaft ausgeübt, den Heiligen die Füße gewaschen, Bedrängten Hilfe geleistet und aller guten Werke sich befleißigt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Jüngere Witwen weise ab. Wenn sie Christus zuwider sinnlich werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'so wollen sie heiraten und ziehen sich ein Gericht zu, weil sie die erste Treue brachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Zugleich lernen sie, müßig in den Häusern herumzulaufen, ja, nicht nur müßig, sondern auch geschwätzig und recht vorwitzig, wobei sie ungeziemend reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Deswegen will ich auch, daß Jüngere wieder heiraten, Kinder gebären und den Haushalt führen und so dem Gegner keinen Anlaß zu übler Nachrede geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Denn schon sind etliche dem Satan nach vom rechten Weg abgewichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Wenn eine Christin Witwen bei sich hat, so soll sie auch für diese sorgen; nicht aber die Gemeinde noch damit belasten, auf daß diese die eigentlichen Witwen versorgen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Die Presbyter, die ihr Amt gut verwalten, erachte man zweifacher Ehre wert; vorzüglich jene, die in Wort und Lehre sich mühen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Sagt doch die Schrift: \"Dem dreschenden Ochsen sollst du das Maul nicht verbinden\", und: \"Der Arbeiter ist seines Lohnes wert.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Nimm gegen einen Presbyter keine Klage an, außer auf Grund von zwei oder drei Zeugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Die Fehlenden weise in der Gegenwart aller zurecht, damit auch die anderen Furcht bekommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ich beschwöre dich vor Gott, vor Christus Jesus und den auserwählten Engeln: Befolge dies ohne Vorurteil und handle nicht nach Gunst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Lege niemand vorschnell die Hände auf und mache dich fremder Sünde nicht mitschuldig. Dich selber halte rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Trinke nicht mehr ausschließlich Wasser; genieße auch ein wenig Wein, deines Magens und deiner vielen Schwächen wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Bei manchen Menschen sind die Sünden offenkundig und eilen dem Gerichte voraus; bei anderen folgen sie erst nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Genauso sind die guten Werke offenbar; und auch, wo es sich anders verhält, können sie nicht verborgen bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Alle, die das Joch des Sklaven tragen, sollen ihre Herren aller Ehre würdig halten, auf daß der Name Gottes und die Lehre nicht gelästert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Die aber Gläubige zu Herren haben, sollen sie deshalb nicht für gering erachten, weil sie Brüder sind, vielmehr nur um so williger ihnen dienen, weil sie Gläubige und Geliebte sind, die sich des Wohltuns befleißigen. Dies lehre und schärfe ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Wer anders lehrt und sich nicht an die gesunden Worte unseres Herrn Jesus Christus hält und nicht an die Lehre, die der Frömmigkeit entsprechend ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'der ist verblendet und versteht nichts, sondern krankt an Grübelei und Zanksucht. Daraus entstehen Neid, Streit, Lästerungen, böser Argwohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Reibereien unter Menschen, die verdorben sind in ihrem Denken und die den Sinn für die Wahrheit verloren haben, Menschen, die meinen, die Frömmigkeit sei eine Quelle des Erwerbs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Ja, Frömmigkeit ist eine gute Quelle des Erwerbs, dann, wenn sie mit Genügsamkeit verbunden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Wir haben nichts in diese Welt hereingebracht und können auch nichts mit hinausnehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Wenn wir Nahrung und Kleidung haben, lasset uns damit zufrieden sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Die aber danach trachten, reich zu werden, fallen in Versuchung und in Schlingen des Teufels, in viele sinnlose und schädliche Begierden, die die Menschen in Verderben und Untergang stürzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Die Liebe zum Geld ist eine Wurzel aller Übel. Manche sind schon in dem Trachten danach vom Glauben abgeirrt und haben sich selber viele Schmerzen zugezogen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Du aber, Mann Gottes, fliehe dies! Strebe vielmehr nach Gerechtigkeit, Frömmigkeit, Glauben, Liebe, Geduld und Sanftmut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kämpfe den guten Kampf des Glaubens; ergreife das ewige Leben, zu dem du berufen bist, für das du vor vielen Zeugen das herrliche Bekenntnis abgelegt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Vor Gott, der allen Dingen Leben gibt, sowie vor Christus Jesus, der unter Pontius Pilatus das herrliche Bekenntnis abgelegt hat, gebiete ich dir:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Bewahre unbefleckt und ohne Tadel dein Amt bis zum Erscheinen unseres Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Zur rechten Zeit wird es der selige, alleinige Gebieter kundtun, der König der Könige, der Herr der Herrscher,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'der allein Unsterblichkeit besitzt und in einem unzugänglichen Lichte wohnt, den nie ein Mensch gesehen hat, noch sehen kann. Ihm sei Preis und Macht in Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Den Reichen dieser Welt gebiete, sich nicht zu überheben und nicht auf ungewissen Reichtum zu vertrauen, vielmehr auf Gott, der alles reichlich zum Genuß uns darreicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Sie sollen Gutes tun, an guten Werken reich werden, freigebig und mitteilsam sein');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'und also eine feste Grundlage für die Zukunft sich zusammentragen, damit sie für sich das wahre Leben erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timotheus! Bewahre das anvertraute Gut! Vermeide leeres, unheiliges Geschwätz sowie die Streitfragen der fälschlich sogenannten \"Erkenntnis\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Einige, die sich dazu bekannt haben, sind am Glauben irre geworden. Die Gnade sei mit euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, Apostel Christi Jesu durch den Willen Gottes nach der auf Christus Jesus ruhenden Verheißung des Lebens,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'an sein geliebtes Kind Timotheus. Gnade, Barmherzigkeit und Friede werde dir zuteil von Gott, dem Vater, und von Christus Jesus, unserem Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Ich danke Gott, dem ich von den Ahnen her mit reinem Gewissen diene, wenn ich bei meinem Beten deiner ohne Unterlaß bei Tag und Nacht gedenke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Ich habe das innige Verlangen, dich zu sehen in der Erinnerung an deine Tränen, damit ich voll Freude würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Vor meiner Seele steht ja dein aufrichtiger Glaube, der schon in Lois, deiner Großmutter, und in Eunike, deiner Mutter, wohnte, und - davon bin ich überzeugt - auch in dir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Aus diesem Grunde ermahne ich dich, die Gnadengabe Gottes wieder anzufachen, die in dir ist durch die Auflegung meiner Hände;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Gott gab uns ja nicht den Geist der Furchtsamkeit, vielmehr den der Kraft, der Liebe und der Besonnenheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'So schäme dich nicht des Zeugnisses für unseren Herrn, noch meiner, der seinetwegen Gefangener ist; leide vielmehr mit für das Evangelium in der Kraft Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Er hat uns ja errettet und den heiligen Ruf an uns ergehen lassen nicht unserer Werke wegen, vielmehr nach seinem Ratschluß und der Gnade, die uns von Christus Jesus vor ewigen Zeiten schon verliehen ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Sie ist durch die Ankunft unseres Heilandes Christi Jesu offenbar geworden. Er überwand den Tod und ließ durch das Evangelium ein unvergängliches Leben aufleuchten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'für dieses ward ich zum Herold und Apostel, zum Völker- Lehrer aufgestellt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Aus diesem Grunde muß ich auch so leiden; dennoch schäme ich mich nicht. Ich weiß ja, wem ich geglaubt habe, und bin überzeugt, daß er die Macht besitzt, mein hinterlegtes Gut bis zu jenem Tage zu behüten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Als Beispiel von gesunden Lehren halte fest an dem, was du von mir gehört hast im Glauben und in Liebe, die aus Christus Jesus stammt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Bewahre das herrliche, anvertraute Gut durch den Heiligen Geist, der in uns wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du weißt, die in Asien haben sich insgesamt von mir zurückgezogen, darunter Phygelus und Hermogenes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Dem Hause des Onesiphorus erweise der Herr Barmherzigkeit; denn oftmals hat er mich erquickt und sich meiner Ketten nicht geschämt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Vielmehr, als er nach Rom kam, suchte er mich eifrig, bis er mich fand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Der Herr verleihe ihm die Gnade, an jenem Tag Erbarmen beim Herrn zu finden. Welch große Dienste er in Ephesus geleistet hat, weißt du am allerbesten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'So sei denn stark, mein Kind, in der Gnade Christi Jesu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Was du von mir mit vielen Zeugen vernommen hast, vertraue zuverlässigen Männern an, die fähig sind, es wieder andere zu lehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Ertrage mit mir Leiden als wackerer Streiter Christi Jesu!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Kein Soldat Gottes läßt sich in zivile Geschäfte ein, sonst wird er dem Kriegsherrn nicht gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Auch wer im Ringkampf auftritt, erhält nur dann den Siegeskranz, wenn er ordnungsgemäß gekämpft hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Der Landmann, der sich abmüht, besitzt den ersten Anspruch auf die Früchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Verstehe wohl, was ich damit sagen will. Der Herr wird dir Verständnis für alles geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Denke an Jesus Christus, der von den Toten auferweckt wurde und ein Nachkomme Davids ist. So lautet ja mein Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Für dieses erdulde ich Leiden, selbst Fesseln wie ein Verbrecher; doch Gottes Wort läßt sich nicht fesseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Darum ertrage ich alles um der Auserwählten willen, damit auch sie das Heil erlangen, das in Christus Jesus ruht, samt der ewigen Herrlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Das Wort ist wahr: Wenn wir mit ihm gestorben sind, dann werden wir mit ihm auch leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Wenn wir geduldig harren, dann werden wir mit ihm auch herrschen. Wenn wir verleugnen, wird er auch uns verleugnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Und wenn wir untreu sind, er bleibt dennoch treu; er kann sich selbst ja nicht untreu werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Dies bringe in Erinnerung und so beschwöre vor Gott: Man soll nicht um leere Worte streiten; es führt ja doch zu nichts und bringt den Hörern nur Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Strebe eifrig danach, dich vor Gott bewährt zu zeigen als einen Arbeiter, der sich nicht zu schämen braucht, der das Wort der Wahrheit richtig handhabt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Geh dem leeren und unheiligen Geschwätz aus dem Weg; es führt ja mehr und mehr zur Gottlosigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Ein solches Geschwätz wird gleich einem Krebsgeschwür um sich greifen. Zu ihnen gehören auch Hymenäus und Philetus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'die von der Wahrheit abgeirrt sind. Sie sagen nämlich, die Auferstehung sei bereits erfolgt, und sie bringen so manche um den Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Jedoch der feste Grundstein Gottes steht da und trägt die Inschrift: \"Der Herr kennt die Seinen\", und: \"Jeder lasse von dem Unrecht, der den Namen des Herrn nennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'In einem großen Hause gibt es nicht nur goldene und silberne Gefäße, vielmehr auch hölzerne und irdene; die einen dienen einem edlen Zwecke, die anderen einem niedrigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Wer sich von diesen gründlich frei macht, der wird ein vornehmes Gefäß, geheiligt und brauchbar für den Herrn, zu jedem guten Werke geeignet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fliehe die Lüste der Jugend. Strebe eifrig nach Gerechtigkeit, Glaube, Liebe, Friede mit denen, die mit reinem Herzen zum Herrn rufen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Die albernen und törichten Grübeleien weise ab; du weißt ja, daß sie nur zu Streitigkeiten führen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Ein Knecht des Herrn soll aber nicht streiten, sondern gegen alle freundlich sein, geschickt im Lehren, geduldig auch das Böse tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Sanftmütig weise er die Widersacher zurecht. Vielleicht schenkt ihnen Gott doch Sinnesänderung, so daß sie die Wahrheit erkennen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'und ernüchtert der Schlinge des Teufels sich entwinden, der sie gefangenhält, damit sie ihm zu Willen seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Das aber wisse, daß in den letzten Tagen schwere Zeiten hereinbrechen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Die Menschen werden voll Selbstsucht sein, geldgierig, prahlerisch, hochmütig, schmähsüchtig, den Eltern ungehorsam, undankbar, gottlos,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'lieblos, unversöhnlich, verleumderisch, ausschweifend, grausam, zuchtlos,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'verräterisch, frech, aufgeblasen, sie haben mehr Freude am Vergnügen als an Gott;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'sie geben sich den Schein der Frömmigkeit, doch lassen sie deren Kraft vermissen. Von solchen Menschen wende dich ab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Aus ihrer Mitte kommen jene, die in die Häuser einschleichen und schwache Frauen an sich fesseln, Frauen, die mit Sünden beladen sind und sich von allerlei Gelüsten leiten lassen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'die immerfort nur lernen wollen und doch nie zur Kenntnis der Wahrheit kommen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'So wie Jannes und Jambres einst dem Moses widerstanden, so leisten auch diese der Wahrheit Widerstand, Menschen mit verdorbenem Sinn und unbewährt im Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Sie werden aber keinen weiteren Erfolg haben; ihr Unverstand wird allen offenkundig werden, wie es auch bei jenen einst der Fall gewesen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Du aber hast meine Lehre dir zur Richtschnur genommen, meinen Wandel, meine Gesinnung, meinen Glauben, meine Langmut, Liebe, Geduld,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'meine Verfolgungen und meine Leiden, wie sie mir in Antiochien, Ikonium und Lystra widerfahren sind. Was für Verfolgungen habe ich ertragen! Und doch hat mich der Herr aus allen befreit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Alle, die fromm in Christus Jesus leben wollen, müssen Verfolgungen erdulden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Doch schlechte Menschen und Betrüger werden es immer schlimmer treiben, Verführer und Verführte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Du aber bleibe bei dem, was du gelernt und wovon du dich überzeugt hast. Du weißt, von wem du es gelernt hast;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'du kennst ja von Kindheit an die heiligen Schriften, die die Kraft haben, dir Weisheit zu verleihen, damit du das Heil erlangst durch den Glauben, der auf Christus Jesus ruht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Jede Schrift, vom Geiste Gottes eingegeben, ist nützlich zur Belehrung, zur Zurechtweisung, zur Besserung und zur Erziehung in Gerechtigkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'damit der Mensch Gottes untadelig sei, bereit zu jedem guten Werke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Jetzt beschwöre ich dich vor Gott und Christus Jesus, der einst die Lebenden und Toten richten wird, bei seiner Erscheinung und bei seinem Reiche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Verkünde das Wort, tritt auf, ob es gelegen oder ungelegen sei, weise zurecht und tadle, ermahne in jeglicher Geduld und in Belehrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Es kommt ja eine Zeit, da man gesunde Lehre nicht ertragen mag, vielmehr nach eigenen Begierden Lehrer über Lehrer für sich sucht, weil man nur nach Ohrenkitzel verlangt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Von der Wahrheit wird man dann sein Ohr abwenden, hingegen Fabeleien gerne sich zuneigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Du aber sei bei allem besonnen und ertrage Leiden, erfülle den Beruf als ein Verkündiger des Evangeliums, verwalte voll und ganz dein Amt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Schon werde ich ja hingeopfert; die Zeit für meine Auflösung ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Ich habe den guten Kampf gekämpft, den Lauf vollendet, den Glauben bewahrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Im übrigen liegt mir der Kranz der Gerechtigkeit bereit, den mir der Herr als ein gerechter Richter an \"jenem Tage\" verleihen wird, und nicht bloß mir, auch allen anderen, die sich in Liebe nach seiner Erscheinung sehnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Beeile dich, bald zu mir zu kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Demas hat mich verlassen, weil er diese Welt lieb gewann. Er ging nach Thessalonich. Kreszenz nach Galatien, Titus nach Dalmatien;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukas allein ist noch bei mir. Bringe Markus mit; denn seine Dienste kann ich gut gebrauchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Den Tychikus habe ich nach Ephesus geschickt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Den Mantel, den ich in Troas bei Karpus ließ, bringe mit, wenn du kommst. Ebenso die Bücher, vor allem auch die Pergamentrollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Viel Böses tat mir Alexander an, der Schmied; der Herr wird ihm nach seinen Werken vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Auch du magst dich vor ihm hüten. Er widersprach heftig unseren Worten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Bei meiner erstmaligen Verteidigung war mir niemand zur Seite; alle ließen mich im Stich. Möge es ihnen nicht angerechnet werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Doch stand der Herr mir bei und stärkte mich, damit durch mich die Predigt durchaus zur Vollendung käme und alle Heidenvölker sie vernähmen; also entrann ich aus dem Rachen des Löwen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Der Herr wird mich auch weiter allen bösen Anschlägen entreißen und in sein himmlisches Reich retten. Ihm sei Ehre von Ewigkeit zu Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Grüße Priska und Aquila und die Familie des Onesiphorus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blieb in Korinth, den Trophimus ließ ich krank in Milet zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Beeile dich, daß du noch vor dem Winter kommst. Es grüßen dich Eubulus und Pudens, Linus und Claudia sowie die Brüder alle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Der Herr Jesus Christus sei mit deinem Geiste. Die Gnade sei mit euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Knecht Gottes, Apostel Jesu Christi, bestimmt, den Auserwählten Gottes Glauben zu vermitteln und die Erkenntnis solcher Wahrheit, die Frömmigkeit erzeugt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Beide ruhen auf der Hoffnung auf das ewige Leben, das Gott, der niemals lügt, vor ewigen Zeiten verheißen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Er offenbarte zu bestimmten Zeiten sein Wort durch die Predigt, mit der ich betraut bin im Auftrage Gottes, unseres Heilands.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'An Titus, an sein echtes Kind im selben Glauben. Gnade und Friede von Gott, dem Vater, und von Christus Jesus, unserem Heiland.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Ich habe dich auf Kreta zurückgelassen, damit du, was noch fehlt, vollends ordnest und Presbyter in jeder Stadt einsetzest, wie ich es dir aufgetragen habe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Ein solcher muß unbescholten sein und einmal nur verheiratet, muß gläubige Kinder haben, die nicht im Rufe eines liederlichen Lebens stehen und die nicht unbotmäßig sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Denn unbescholten muß ein Bischof sein als Gottes Haushalter, nicht selbstsüchtig, nicht jähzornig, nicht trunksüchtig, nicht roh und nicht auf schändlichen Gewinn bedacht,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'sondern gastfreundlich, dem Guten zugetan, besonnen, gerecht, fromm und enthaltsam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Er muß am zuverlässigen Wort der Lehre entsprechend festhalten, damit er imstande sei, nach der gesunden Lehre zu ermahnen sowie die Gegner zu widerlegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Es gibt ja viele unfolgsame Menschen und eitle Schwätzer und Verführer, zumal bei denen aus der Beschneidung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Diesen muß man den Mund stopfen; sie bringen ganze Häuser in Verwirrung, indem sie Ungehöriges lehren nur schändlichen Gewinnes wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Einer ihrer eigenen Propheten sagte ja: \"Die Kreter sind von jeher Lügner, wilde Tiere, faule Bäuche.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Dies Zeugnis ist wahr. Weise sie aus diesem Grunde scharf zurecht, damit sie im Glauben gesund bleiben');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'und sich nicht auf jüdische Fabeleien einlassen und auf Menschensatzungen, die von der Wahrheit abweichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Den Reinen ist alles rein; den Unreinen jedoch und Ungläubigen ist nichts rein, ist ihr Verstand und ihr Gewissen doch befleckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Sie geben vor, Gott zu kennen, verleugnen ihn jedoch durch Werke. Und so sind sie ein Greuel und ungehorsam, untauglich zu jedem guten Werke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Du aber predige, was der gesunden Lehre entspricht:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Die alten Männer sollen nüchtern sein, ehrbar, besonnen, gesund im Glauben, an Liebe und Geduld.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Desgleichen sollen alte Frauen sich ehrfürchtig benehmen, nicht verleumderisch und nicht dem Trunk ergeben sein, ein Muster alles Guten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'damit sie die jungen Frauen anleiten, die Männer und die Kinder zu lieben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'sittsam zu sein und züchtig, häuslich und gütig, ihren Gatten untertan, damit nicht das Wort Gottes gelästert werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Geradeso ermahne die jungen Männer, Selbstbeherrschung zu zeigen in jeder Hinsicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Sei ihnen selber ein Vorbild guter Sitten. Beim Lehren zeige Lauterkeit und Würde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Deine Worte seien gesund und unangreifbar, damit der Gegner beschämt werde, wenn er nichts Böses nachsagen kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Die Sklaven sollen ihren Herren in allem untertänig sein, gefällig, ohne Widerspruch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Sie sollen nichts veruntreuen, vielmehr volle und gediegene Treue zeigen, damit sie der Lehre Gottes, unseres Heilandes, in allem Ehre machen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Erschienen ist ja die Gnade Gottes, die allen Menschen Heil verleiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Sie erzieht uns dazu, daß wir der Gottlosigkeit und den weltlichen Gelüsten entsagen, besonnen, gerecht und fromm in der jetzigen Welt leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Dabei erwarten wir die beseligende Hoffnung und die Erscheinung der Herrlichkeit unseres großen Gottes und Heilandes Christus Jesus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'der sich selber für uns dahingegeben hat, um uns von aller Ungerechtigkeit zu erlösen und sich ein reines Volk als Eigentum zu schaffen, das voll Eifer ist zu guten Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'So predige und mahne und weise zurecht mit aller Entschiedenheit. Niemand soll dich verachten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Erinnere sie daran, daß sie sich der Gewalt der Obrigkeiten unterordnen, daß sie gehorsam seien, zu jedem guten Werke bereit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Sie sollen niemand beschimpfen, nicht streitsüchtig sein, sondern nachgiebig und gegen alle Menschen in vollem Maße Sanftmut zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Einst waren ja wir selber unverständig, unbotmäßig und gingen in die Irre und waren allerlei Begierden und Lüsten dienstbar und lebten so in Bosheit und in Neid dahin, des Abscheus wert und gegenseitig voll von Haß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Als jedoch die Güte und Menschenfreundlichkeit unseres Heilandes und Gottes erschienen ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'hat er uns errettet, nicht auf Grund von Werken, die wir in Gerechtigkeit vielleicht selbst vollbracht hätten, vielmehr nach seinem eigenen Erbarmen durch das Bad der Wiedergeburt sowie durch die Erneuerung durch den Heiligen Geist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'den er in reichem Maße durch Jesus Christus, unseren Heiland, über uns ausgegossen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'damit wir, gerechtfertigt durch seine Gnade, Erben würden des erhofften ewigen Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Das Wort ist wahr, und so will ich, daß du darüber entschieden Zeugnis ablegst, damit jene, die zum Gottesglauben kamen, eifrig darauf sinnen, sich guter Werke zu befleißigen. Es ist das gut und für die Menschen nützlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Dagegen meide dumme Grübeleien, Fragen über Stammbäume und Zänkereien sowie Streitigkeiten über das Gesetz; denn sie sind nutzlos und eitel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Hast du einen Ketzer einmal oder zweimal gewarnt, dann stoße ihn aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Du weißt ja, daß ein solcher ganz verdorben ist und durch sein Sündigen sich selbst das Urteil spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Wenn ich den Artemas oder den Tychikus zu dir gesandt habe, dann eile, nach Nikopolis zu mir zu kommen; denn dort gedenke ich den Winter zu verbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenas, den Gesetzeskundigen, und Apollos versorge gut für die Reise, damit ihnen nichts fehle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Auch unsere Leute sollen lernen, durch gute Werke sich bei dringenden Bedürfnissen hervorzutun, damit sie nicht ohne Frucht dastehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Dich grüßen alle, die bei mir sind; grüße auch du, die uns im Glauben lieben. Die Gnade sei mit euch allen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pau Gefangener Christi Jesu, und Timotheus, der Bruder, an Philemon, unseren geliebten Mitarbeiter,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'und an die Schwester Appia, an unseren Mitkämpfer Archippus und an die Gemeinde in deinem Hause.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gnade werde euch zuteil und Friede von Gott, unserem Vater, und von dem Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Ich danke meinem Gott allezeit, sooft ich bei meinem Beten deiner gedenke,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'da ich höre, wie du Liebe und Glauben an den Herrn Jesus und für alle Heiligen hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Möchte doch dein Glaube, der uns gemeinsam ist, sich in der Tat bewähren auf Christus hin in richtiger Erkenntnis all des Guten, das unter uns vorhanden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Viel Freude und viel Trost habe ich aus deiner Liebe geschöpft; an dir, o Bruder, erquicken sich ja die Herzen der Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Nun hätte ich allerdings das volle Recht in Christus, dir zu befehlen, was du tun sollst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Doch um der Liebe willen ziehe ich es vor zu bitten, so wie ich, der alte Paulus, nun einmal bin, dazu noch jetzt Gefesselter um Christi Jesu willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Ich bitte dich für mein Kind, dem ich im Gefängnis das Leben gab, für den Onesimus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Einst war er dir unnütz, doch jetzt ist er für dich und auch für mich von großem Nutzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Ich schicke ihn dir zurück; nimm ihn, oder besser mein Herz, wohl auf!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Gern hätte ich ihn bei mir zurückbehalten, damit er an deiner Statt mir Dienste leiste in meinen Banden für das Evangelium.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Doch ohne deine Zustimmung wollte ich nichts tun, damit das Gute, das du tust, nicht erzwungen scheine, vielmehr freiwillig geschehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Vielleicht hat er sich deshalb auf kurze Zeit von dir getrennt, damit du ihn auf ewig zurückerhieltest,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'nicht mehr als Sklaven, sondern weit mehr als einen Sklaven, als einen vielgeliebten Bruder. Dies ist er mir vor allem; wieviel mehr wird er dir es sein als Mensch und auch als Christ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Wenn du dich mit mir einig fühlst, so nimm ihn auf wie mich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Doch brachte er dich in Schaden oder schuldet er dir noch etwas, so setze dies mir auf die Rechnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ich, Paulus, gebe es dir mit eigener Hand schriftlich: Ich werde es bezahlen. Davon allerdings will ich nicht reden, daß du sogar dich selbst mir schuldest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Lieber Bruder: Ich möchte im Herrn ein Nutzungsrecht an deiner Person ausüben; bereite in Christus meinem Herzen eine Freude!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Auf dein Entgegenkommen fest vertrauend, schreibe ich dir; ich weiß, du tust noch mehr als ich verlange.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Bereite mir zugleich ein Gastzimmer; habe ich doch die Hoffnung, daß ich dank eurer Gebete euch geschenkt werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Es grüßen dich Epaphras, mein Mitgefangener in Christus Jesus,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'und Markus, Aristarch, Demas und Lukas, meine Mitarbeiter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Die Gnade des Herrn Jesus Christus sei mit eurem Geiste! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Gar oft und verschiedenartig hat Gott vor alters durch die Propheten zu den Vätern geredet;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'jetzt, am Ende der Tage, sprach er zu uns durch seinen Sohn. Ihn setzte er zum Erben des Weltalls ein, durch den er die Welten geschaffen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Er ist der Abglanz seiner Herrlichkeit, das Abbild seines Wesens, und er trägt das All durch sein gewaltiges Wort. Er brachte Erlösung von den Sünden und setzte sich zur Rechten der Majestät im Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Er ward um ebensoviel über alle Engel hoch erhoben, als der Name, den er ererbt hat, den ihren überragt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Zu welchem Engel hat denn jemals Gott gesprochen: \"Mein Sohn bist du, heute habe ich dich gezeugt\"? Oder zu welchem sagte er: \"Ich werde ihm Vater und er wird mir Sohn sein\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Und wenn er den Erstgeborenen wiederum in die Welt einführt, sagt er: \"Ihm sollen huldigen alle Engel Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Doch von den Engeln heißt es nur: \"Er macht seine Engel zu Winden, zu Feuerflammen seine Diener.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Vom Sohn aber: \"Dein Thron, o Gott, steht für die Ewigkeit der Ewigkeiten!\" und \"Das Zepter der Gerechtigkeit, das ist dein Herrscherstab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du liebst das Recht; den Frevel hassest du; darum hat dich, o Gott, dein Gott gesalbt mit Freudenöl, wie keinen deiner Genossen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Und weiter heißt es: \"Du, o Herr, hast im Anfang die Erde gegründet; die Himmel sind das Werk deiner Hände;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'doch sie vergehen, Du aber bleibst, veralten werden alle, wie ein Kleid,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'wie einen Mantel wirst Du sie zusammenrollen - wie ein Kleid werden sie vertauscht; Du aber bleibst derselbe, und Deine Jahre gehen nicht zu Ende.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Zu welchem von den Engeln hat er je gesprochen: \"Setze dich zu meiner Rechten, bis ich deine Feinde als Schemel dir zu Füßen lege\"?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Sind nicht vielmehr alle dienende Geister, ausgesandt zum Dienste derer, die das Heil erben sollen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'So müssen wir nun um so eifriger beachten, was wir vernommen haben; sonst könnten schließlich wir noch darum kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Wenn schon das Wort, das durch die Engel verkündet wurde, so streng verpflichtend war und jede Übertretung, jeder Ungehorsam die gerechte Strafe nach sich zog,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'wie sollten dann wir der Strafe entrinnen, wenn wir ein solches Heil unbeachtet ließen, das zuerst vom Herrn verkündet und von den Ohrenzeugen uns getreu überliefert ward?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dazu ward es von Gott bekräftigt nach seinem heiligen Willen durch Zeichen und Wunder, durch manche Machterweise und Mitteilungen des Heiligen Geistes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Nicht Engel sind die Herren der künftigen Welt, von der wir reden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'vielmehr heißt es zum Beweise irgendwo: \"Was ist der Mensch, daß Du seiner gedenkst? Und was ein Menschenkind, daß Du es beachtest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Nur wenig ließest Du ihn den Engeln nachstehen, Du kröntest ihn mit Ehre und mit Herrlichkeit und hast ihn über die Werke Deiner Hände gesetzt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'und legtest ihm alles zu Füßen.\" Wenn er ihm alles unterworfen hat, so ließ er nichts mehr übrig, was ihm nicht unterworfen wäre. Jetzt freilich sehen wir noch nicht, daß ihm alles unterworfen wäre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'In dem, der nur wenig den Engeln nachstand, erblicken wir Jesus, der seines Todesleidens wegen mit Ehre und Herrlichkeit gekrönt ward, damit er nach Gottes gnädigem Willen den Tod für alle koste.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Es ziemte sich für das Ziel und den Urgrund aller Dinge, der viele Söhne zur Herrlichkeit führte, durch Leiden den Begründer ihres Heiles zu vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Denn der, der heilig macht, und die, die geheiligt werden, sind ja alle eines Ursprungs; so schämt er sich auch nicht, sie Brüder zu nennen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Wenn er sagt: \"Deinen Namen will ich meinen Brüdern künden, inmitten der Gemeinde will ich Dich lobpreisen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Und weiter: \"Ich werde mein Vertrauen auf ihn setzen\"; und ferner: \"Sieh, hier bin ich samt den Kindern, die mir Gott gegeben hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Weil nun Kinder Fleisch und Blut gemeinsam haben, so nahm auch er in gleicher Weise solches an, um durch den Tod den zu vernichten, der über den Tod die Macht, besaß, den Teufel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'und alle zu erlösen, die im Bann der Todesfurcht ihr ganzes Leben lang ein Sklavenjoch getragen haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Nicht etwa Engeln gilt ja seine Sorge; sondern um die Kinder Abrahams nimmt er sich an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Deswegen mußte er in allem seinen Brüdern gleich werden, damit er ein barmherziger und treuer Hoherpriester würde für ihre Anliegen bei Gott, um die Sünden des Volkes zu sühnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Denn weil er selber unter den Versuchungen gelitten hat, kann er denen helfen, die versucht werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Nun denn, heilige Brüder, Gefährten himmlischer Berufung, betrachtet unverwandt den Gesandten und Hohenpriester Jesus, zu dem wir uns bekennen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'der dem treu war, der ihn bestellte, ähnlich, wie in seinem ganzen Hause Moses.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Ist er doch größerer Herrlichkeit gewürdigt worden als Moses, wie der Baumeister größeren Ruhm hat als das Haus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Jedes Haus hat seinen Baumeister; der Weltenbaumeister jedoch ist Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Auch Moses, der in seinem ganzen Leben treu gedient hat, tat dies als Diener, zum Zeugnis für die Offenbarung, die erst noch kommen sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Doch Christus steht als Sohn über seinem Hause. Dieses Haus sind wir, wenn wir die gläubige Zuversicht und das ruhmvolle Hoffen bis ans Ende treu bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Darum gilt, was der Heilige Geist gesprochen hat: \"Heute, wenn ihr seine Stimme höret,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'verhärtet eure Herzen nicht wie bei der Erbitterung am Tage der Versuchung in der Wüste,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'wo eure Väter mich mit Zweifel auf die Probe stellten, obwohl sie meine Taten vierzig Jahre lang sahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'So überkam mich ein heiliger Zorn über dieses Geschlecht; ich sprach: \'Beständig mögen sie in ihrem Herzen irren.\' Doch sie verstanden meine Wege nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'So schwur ich denn in meinem Zorne: \'Sie sollen nicht in meine Ruhe eingehen.\'\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Seht zu, o meine Brüder, daß nicht in irgendeinem unter euch ein böses und ungläubiges Herz sich finde, daß es zum Abfall käme vom lebendigen Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Sprecht vielmehr Tag für Tag einander zu, solange das \"Heute\" noch gilt, daß keiner unter euch verhärtet werde durch den Trug der Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Wir sind Gefährten Christi, wenn wir nur den ersten Glauben bis zum Ende treu bewahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Wenn es heißt: \"Heute, wenn ihr seine Stimme höret, verhärtet eure Herzen nicht wie bei der Erbitterung\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'wer waren denn die Hörer, die so erbittert waren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Wem zürnte er denn vierzig Jahre lang? Waren es nicht jene, die gesündigt hatten und deren Leichen in der Wüste liegen blieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Wem hat er denn geschworen, daß sie nicht in seine Ruhe eingehen sollten? Wenn nicht denen, die ungehorsam waren?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Und in der Tat, wir sehen, daß sie wegen dieses Unglaubens nicht eingehen konnten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'So lasset uns denn ernstlich sorgen, daß keiner unter euch für säumig befunden werde; denn die Verheißung, in seine Ruhe einzugehen, steht noch aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Denn auch an uns, wie an jene, erging die frohe Botschaft. Doch jenen hat das Wort der Predigt nichts genützt, weil es nicht durch den Glauben mit den Hörern zusammenwuchs.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Wir werden aber eingehen in seine Ruhe, weil wir gläubig wurden, wie er denn auch gesagt hat: \"Wie ich schwur in meinem Zorne: \'Sie sollen nicht in meine Ruhe eingehen.\'\" Und doch sind die Werke seit der Welterschaffung abgeschlossen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Es heißt ja irgendwo vom siebten Tag also: \"Gott ruhte am siebten Tage von allen seinen Werken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Und hier heißt es: \"Sie sollen nicht in meine Ruhe eingehen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Es bleibt also dabei, daß manche in sie eingehen, doch auch, daß die, die zuerst die frohe Botschaft empfangen haben, wegen ihres Ungehorsams nicht hineingekommen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'So bestimmt er wieder einen Tag, ein \"Heute\", wenn er nach so langer Zeit durch David sagen läßt, wie eben angeführt: \"Heute, wenn ihr seine Stimme höret, verhärtet eure Herzen nicht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Denn hätte sie Josue zur Ruhe geführt, dann hätte er nicht nachher noch von einem anderen Tage geredet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'So bleibt dem Volke Gottes eine Sabbatruhe noch in Aussicht;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'denn wer in seine Ruhe eingegangen ist, ruht von seinen Werken wie Gott von den seinen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'So soll denn unser eifrigstes Bestreben sein, in diese Ruhe einzugehen, daß keiner durch Ungehorsam zu Falle komme, wie es eben an diesem Beispiel dargetan ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Lebendig ist ja das Wort Gottes und wirksam und noch schärfer als jedes zweischneidige Messer. Es dringt hindurch, bis es Geist und Seele, Gelenk und Mark geschieden hat; es ist ein Richter über die Gedanken und Gesinnungen des Herzens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Und kein Geschöpf bleibt vor ihm verborgen; es liegt alles bloß und offen da vor den Augen dessen, dem wir Rechenschaft geben müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Da wir nun einen so großen Hohenpriester haben, der die Himmel durchschnitten hat, Jesus, den Gottessohn, so laßt uns am Bekenntnisse festhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Wir haben ja nicht einen solchen Hohenpriester, der nicht mit unseren Schwächen mitfühlen könnte, sondern einen, der in allem versucht ward ebenso wie wir, nur daß es nicht zur Sünde kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'So laßt uns denn mit Zuversicht dem Throne der Gnade nahen, damit wir Barmherzigkeit erlangen und Gnade finden für die Hilfe zur richtigen Zeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Denn jeder Hohepriester, aus den Menschen genommen, wird für die Menschen aufgestellt, in ihren Anliegen bei Gott, damit er für ihre Sünden Gaben und Opfer darbringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'So muß er Verständnis haben können mit den Unwissenden und Irrenden, weil er auch selbst mit Schwachheit behaftet ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Um ihretwillen muß er, wie für das Volk, so auch für sich selbst der Sünden wegen Opfer bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Auch darf sich keiner diese Würde anmaßen, vielmehr muß er von Gott berufen sein wie Aaron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'So hat auch Christus nicht sich selbst mit der hohenpriesterlichen Würde bekleidet, vielmehr der, der zu ihm sprach: \"Mein Sohn bist du, heute habe ich dich gezeugt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Wie er denn auch an einer anderen Stelle spricht: \"Du bist Priester ewiglich nach der Ordnung des Melchisedech.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'In den Tagen seines Erdenlebens betete und flehte er mit lautem Rufen unter Tränen innig zu dem, der ihn vom Tode retten konnte, und wurde wegen seiner Gottesfurcht erhört.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Obschon er Sohn Gottes war, lernte er an dem, was er litt, den Gehorsam,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'und wurde so, als er zur Vollendung gelangt war, für alle, die ihm gehorchen, Urheber des ewigen Heiles,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'nachdem er von Gott als Hoherpriester nach der Ordnung des Melchisedech anerkannt worden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Darüber hätten wir nun viel zu sagen; doch ist es schwer, es darzulegen, weil ihr harthörig geworden seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Der Zeit nach solltet ihr schon Lehrer sein; statt dessen ist es nötig, daß man euch in den Anfangsgründen der Worte Gottes wieder unterrichte; ihr könnt ja nur Milch brauchen anstatt fester Speise.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Wer noch Milch braucht, ist unfähig, richtiges Reden zu verstehen; er ist ja noch nicht mündig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Für die Vollendeten ist feste Nahrung da, für die, die von Natur aus ihre Sinne geübt haben, um zwischen Gut und Bös zu unterscheiden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Wir wollen deshalb die Anfangsgründe der Lehre Christi übergehen und uns den höheren Dingen zuwenden und nicht den Grund noch einmal legen: Abkehr von toten Werken, Glauben an Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'die Lehre von den Taufen, der Handauflegung, von der Auferstehung von den Toten und der ewigen Vergeltung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Wenn Gott es gewährt, so wollen wir dies so halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Es ist ja unmöglich, daß solche, die einmal erleuchtet waren, die von der Himmelsgabe gekostet hatten, die des Heiligen Geistes teilhaftig geworden waren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'die das herrliche Gotteswort verkostet und die Kräfte jener künftigen Welt in sich erfahren hatten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'und dann abgefallen sind, zur Bekehrung wiederum erneuert wurden; sie haben ja, soweit es auf sie ankommt, den Sohn Gottes aufs neue gekreuzigt und ihn zum Gespött gemacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Wenn ein Grundstück Regen, der reichlich darauf niederströmte, aufgesogen hat und denen, durch die es bestellt wird, erwünschte Früchte bringt, so nimmt es teil am Segen Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Bringt es aber nur Dornen und Disteln, so ist es wertlos und dem Fluche nahe, der schließlich ins Feuer führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Wir sind bei euch, Geliebte, des günstigeren Falles und des zum Heil Gehörenden gewiß, wenn schon wir so reden mußten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Gott ist nicht ungerecht, daß er eure guten Werke und eure Liebe vergessen würde, die ihr um seines Namens willen gezeigt habt, indem ihr den Heiligen gedient habt und noch immer dienet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Wir wünschen nur, daß jeder aus euch den gleichen Eifer zeige, damit ihr auch die Hoffnung voll entfaltet, ja, selber zur Vollendung bringt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'auf daß ihr nicht ermattet, sondern die nachahmt, die durch Glauben und Geduld die Verheißungen erben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Denn als Gott dem Abraham die Verheißung gab, da schwur er, weil er bei keinem Höheren schwören konnte, bei sich selbst und sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, '\"Fürwahr, ich will dich reichlich segnen und reichlich auch dich mehren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Und so harrte er geduldig aus und erlangte die Verheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Menschen schwören stets bei einem Höheren; der Eid läßt jede Widerrede verstummen und gibt Sicherheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Weil Gott den Erben der Verheißung noch deutlicher zeigen wollte, wie unabänderlich sein Ratschluß sei, deshalb verbürgte er sich durch einen Eid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'So sollten wir an zwei unabänderlichen Tatsachen, bei denen Gott unmöglich täuschen konnte, einen sicheren Trost besitzen, wir, die wir an die dargebotene Hoffnung uns geklammert haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'An ihr besitzen wir für unsere Seele einen Anker, fest und zuverlässig, der in das Innere des Vorhangs hineinreicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Ist Jesus doch als Vorläufer für uns dort eingetreten, nachdem er Hoherpriester nach der Ordnung des Melchisedech auf ewig geworden war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Eben der Melchisedech war König von Salem und Priester des allerhöchsten Gottes. Er ging dem Abraham entgegen, als dieser von der Niederwerfung der Könige zurückkam, und gab ihm den Segen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Dafür gab Abraham ihm den Zehnten von allem. Sein Name wird zunächst erklärt als \"König der Gerechtigkeit\", dann aber auch als \"Salems König\", das heißt \"Friedenskönig\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Er steht da ohne Vater, ohne Mutter, ohne Stammbaum, ohne Anfang seiner Tage, ohne Lebensende; ein treues Urbild des Gottessohnes, bleibt er Priester bis in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Bedenket nun, wie hoch der stehen muß, dem sogar Abraham, der Patriarch, den Zehnten von den besten Beutestücken gab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Die, die aus dem Stamme Levi das Priesteramt erhalten haben, besitzen zwar nach dem Gesetze das Recht, vom Volke, also von ihren Brüdern, einen Zehnten zu erheben, obwohl auch sie von Abraham abstammen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Doch dieser, der nicht aus ihnen stammt, hat doch dem Abraham den Zehnten abgenommen und dann den Träger der Verheißungen gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Es unterliegt gar keinem Zweifel: Das Niedrige wird vom Höheren gesegnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Ferner nehmen hier sterbliche Menschen den Zehnten entgegen, dort aber einer, von dem bezeugt ist, daß er lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Und weiter ward in Abraham auch sozusagen Levi, der selber doch den Zehnten fordert, mit dem Zehnten belegt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'er war ja noch in der Lende seines Vaters, als ihm Melchisedech begegnete.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Wenn nun das levitische Priestertum, auf das das Volk gesetzlich festgelegt war, schon die Vollendung gebracht hätte, wäre es dann notwendig gewesen, noch einen andern nach der Ordnung des Melchisedech als Priester aufzustellen und davon zu reden, daß er es nicht nach der Ordnung Aarons sei?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Und weiter: wenn das Priestertum wechselt, dann wechselt notwendig auch die Priesterordnung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Denn der, auf den sich diese Aussage bezieht, gehört ja einem anderen Stamme an, aus dem noch keiner dem Altare gedient hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Denn es ist allgemein bekannt, daß unser Herr aus Juda hervorgegangen ist, aus einem Stamme, von dem Moses nichts gesagt hatte, was sich auf Priester beziehen könnte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Und vollends klar wird noch die Sache, wenn nach dem Ebenbild des Melchisedech ein anderer Priester eingesetzt wird,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'der es nicht nach dem Gesetz eines fleischlichen Gebotes ward, vielmehr in der Kraft eines unvergänglichen Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'So heißt es ja: \"Du bist Priester ewiglich nach der Ordnung des Melchisedech.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ein bisher geltendes Gesetz wird aufgehoben dann, wenn es kraft- und nutzlos wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Das Gesetz hatte die Vollendung nicht gebracht; es war nur die Einleitung zu einer besseren Hoffnung, durch die wir uns Gott nahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Und in demselben Maße, wie er nicht ohne Eidschwur Priester ward - indessen jene ohne Eidschwur Priester wurden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'ward er es durch einen Eidschwur dessen, der zu ihm sprach: \"Geschworen hat der Herr; es wird ihn nicht gereuen, du bist Priester ewiglich\" -,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'in eben diesem Maße wurde Jesus Bürge eines höheren Bundes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Diese wurden in größerer Anzahl Priester, weil sie durch den Tod verhindert wurden, im Amte zu bleiben;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'er aber hat ein unvergängliches Priestertum, weil er ja ewig am Leben bleibt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'So kann er auch für alle Zeiten jene retten, die sich durch ihn Gott nahen, weil er immer lebt, um für sie einzutreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'So mußte unser Hoherpriester ja auch sein: heilig, rein, unbefleckt, von den Sündern losgelöst und über alle Himmel hoch erhoben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'der nicht wie die Hohenpriester täglich nötig hat, zuerst für seine eigenen Sünden Opfer darzubringen und alsdann für die des Volkes; denn dies hat er ein für allemal getan, indem er sich selber zum Opfer dargebracht hat. 21 Also bestellt das Gesetz zu Hohenpriestern Menschen mit Schwachheit angetan, das Wort des Eidschwurs dagegen in der Zeit nach dem Gesetze den Sohn, der für alle Zeit vollendet ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Die Hauptsache bei diesen Ausführungen ist aber dies: Wir haben einen Hohenpriester, der sich zur Rechten des Thrones der Majestät im Himmel gesetzt hat');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'als Priester im Heiligtum und an der wahren Stiftshütte, die der Herr und nicht ein Mensch errichtet hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Jeder Hohepriester ist nämlich dazu aufgestellt, daß er Gaben und Opfer darbringe; er muß deshalb auch etwas haben, was er opfern kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Würde er auf Erden leben, So wäre er ja gar nicht Priester; denn hier sind schon solche, die nach dem Gesetze Gaben darbringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Sie dienen nur einem Vorbild und einem Schattenriß des Himmlischen; wie denn auch Moses, als er einst das Zelt errichten wollte, so angewiesen ward: \"Sieh zu\", hieß es, \"daß du alles nach dem Vorbild machen lässest, das dir auf dem Berge gezeigt ward!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Der Dienst jedoch, den Jesus erhielt, ist um so ausgezeichneter, als auch der Bund, den er vermittelt, besser ist; beruht doch dieser auf einer höheren Verheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Denn wäre jener erste tadellos gewesen, so hätte man nicht Platz für einen zweiten gesucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Er sagt ja, jene tadelnd: \"Siehe, es kommen Tage\", spricht der Herr, \"wo ich einen neuen Bund schließen will mit dem Hause Israel und mit dem Hause Juda;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'nicht so wie jenen Bund, den ich mit ihren Vätern an dem Tage schloß, da ich sie bei der Hand nahm, um sie aus dem Lande Ägypten zu führen. Weil sie meinem Bund nicht treu geblieben waren, habe auch ich mich nicht um sie gekümmert\", spricht der Herr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '\"Doch dieses soll der Bund nun sein, den ich nach diesen Tagen\", spricht der Herr, \"mit dem Hause Israel abschließen werde: Mein Gesetz will ich in ihr Inneres legen und ihnen in das Herz es schreiben; ich will ihr Gott sein, und sie sollen mir zum Volke werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Keiner braucht dann seinen Nächsten und keiner seinen Bruder mehr zu lehren und zu sagen: \'Erkenne doch den Herrn!\' Sie alle, klein und groß, werden mich alsdann erkennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Ich werde ihre Schuld vergeben und ihrer Sünden nimmermehr gedenken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Mit dem Worte \"neu\" erklärte er den frühern für veraltet. Was aber alt ist und veraltet, das ist reif, daß es vergehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Der frühere Bund hatte zwar auch Vorschriften für den Gottesdienst und für das irdische Heiligtum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Es wurde ja ein Zelt errichtet, in dessen vorderem Teile der Leuchter sich befand sowie der Tisch mit den Schaubroten; der Teil heißt \"Heiligtum\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Und hinter dem zweiten Vorhang war das Zelt, das man das \"Allerheiligste\" nennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Darin standen der goldene Rauchopferaltar und die mit Gold überzogene Bundeslade. In dieser befanden sich ein goldenes Gefäß mit Manna und Aarons Stab, der grün geworden war, und die Gesetzestafeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Und über ihr beschatteten die Cherubim der Glorie den Sühnedeckel. Jedoch hierüber ist jetzt nicht im einzelnen zu reden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Entsprechend dieser Einrichtung betreten die Priester stets nur den vorderen Raum des Zeltes, um ihrem heiligen Dienst obzuliegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Doch in den hinteren Raum tritt nur der Hohepriester ein, und zwar nur ein einzigesmal im Jahr und dann nicht ohne Blut, das er für sich und die unwissentlichen Verfehlungen des Volkes darbringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Es offenbart dadurch der Heilige Geist, der Zugang zu dem Heiligtum sei noch nicht offen, solange das erste Zelt noch Bestand hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Das ist aber nur ein Gleichnis für die gegenwärtige Zeit, wonach Gaben und Opfer dargebracht werden, die nicht die Kraft besitzen, den Opfernden im Gewissen zu vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Sie stehen vielmehr in gleicher Linie mit den Vorschriften für Speise und Trank und für verschiedene Waschungen: nur äußerliche Heiligungsmittel bis zur Zeit der Neugestaltung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Christus dagegen kam als Hoherpriester für die zukünftigen Heilsgüter; er trat durchs größere und durchs vollkommenere Zelt, das nicht mir Händen gemacht ist, das heißt, das nicht dieser Erde angehört,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'auch nicht durch Blut von Böcken und Rindern, vielmehr durch sein eigenes Blut ein für allemal hinein ins Heiligtum, wodurch er ewige Erlösung bewirkt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Wenn schon das Blut von Böcken und Stieren sowie die Asche einer Kuh durch Besprengung Unreine heiligen kann, so daß sie äußerlich gereinigt werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'um wieviel mehr wird das Blut Christi, der durch den ewigen Geist sich selbst untadelig Gott dargebracht hat, eure Gewissen von toten Werken reinigen, damit ihr dem lebendigen Gott dient!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Deshalb ist er auch Bürge eines Neuen Bundes, damit die Berufenen das verheißene ewige Erbe zum Besitz erhalten. Er ging zuvor ja in den Tod, um so die Sünden wegzunehmen, die unter dem früheren Bunde begangen worden waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Denn wo ein Testament in Kraft treten soll, da muß der Tod des Erblassers nachgewiesen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Ein Testament erlangt ja mit dem Tod erst Rechtskraft, weil es nichts gilt, solange der Erblasser noch lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Deshalb ward auch der erste Bund nicht ohne Blutvergießen eingeweiht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Als nämlich Moses dem gesamten Volk alle Vorschriften genau nach dem Gesetze vorgetragen hatte, nahm er das Blut der Rinder und Böcke samt Wasser, roter Wolle und Hysop. Er besprengte dann das Buch und das gesamte Volk, wobei er sprach:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, '\"Dies ist das Blut des Bundes, den Gott mit euch geschlossen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Auch das Zelt und alle gottesdienstlichen Geräte besprengte er in gleicher Weise mit dem Blute.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Auch sonst wird dem Gesetz entsprechend fast alles mit Blut gereinigt, und ohne Blutvergießung gibt es keine Vergebung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Die Abbilder des himmlischen Heiligtums müssen also mit solchen Mitteln gereinigt werden; das himmlische Heiligtum selber erfordert aber noch höhere Opfer als jene.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Nicht in ein Heiligtum, das Menschenwerk und nur ein Vorbild vom wahren wäre, ist Christus eingegangen, sondern in den eigentlichen Himmel, um von jetzt an für uns vor Gottes Angesicht einzutreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Auch braucht er sich nicht immer wieder selbst zum Opfer darzubringen, wie der Hohepriester Jahr für Jahr ins Allerheiligste mit fremdem Blute tritt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'sonst hätte er ja seit der Erschaffung der Welt oftmals leiden müssen. So aber ward er nur ein einzigesmal, zur Zeit der Weltvollendung, offenbar, um durch das Opfer seiner selbst die Sünde auszutilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Und wie es dem Menschen bestimmt ist, ein einzigesmal zu sterben, worauf dann das Gericht kommt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'so wurde auch Christus nur einmal geopfert, um die Sünden vieler wegzunehmen. Das zweitemal wird er ohne jegliche Beziehung zur Sünde erscheinen, zum Heile derer, die auf ihn harren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Das Gesetz ist nur ein Schattenbild der künftigen Heilsgüter, nicht aber das wahre Bild der Wirklichkeit. Trotz der gleichen Opfer, die man Jahr für Jahr unaufhörlich darbringt, ist es nicht imstande, die Opfernden zu vollenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Oder hätte man nicht aufgehört, sie darzubringen, wenn die Opfernden sich frei von Sünden wüßten und wenn sie ein für allemal gereinigt wären?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Im Gegenteil, durch die Opfer werden wir Jahr für Jahr nur an die Sünden recht erinnert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Unmöglich kann das Blut von Stieren und Böcken Sünden tilgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Deshalb sagt er auch bei seinem Eintritt in die Welt: \"Du willst keine Opfer und keine Gaben; einen Leib aber hast Du mir geschaffen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'An Brand- und Sündopfern hast Du keinen Gefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Da sprach ich: Siehe, ich bin da; es steht in der Buchrolle von mir geschrieben, daß ich, o Gott, Deinen Willen vollbringen soll.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Zuerst sagt er: Du willst keine Opfer und Gaben, nicht Brand- noch Sündopfer, und hast daran kein Wohlgefallen. Es sind dies Opfer, wie man sie nach dem Gesetze darbringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Dann aber fährt er fort: \"Siehe, ich bin da, um Deinen Willen zu erfüllen.\" Damit hebt er das erste auf, um das zweite als maßgebend zu kennzeichnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Kraft dieses Willens sind wir ein für allemal geheiligt durch die Hingabe des Leibes Jesu Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Jeder Priester steht im heiligen Dienste Tag für Tag und bringt immer wieder nur die gleichen Opfer dar, die doch nie die Sünden tilgen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Dieser aber hat das eine Opfer für die Sünden dargebracht und sich alsdann für immer zur Rechten Gottes gesetzt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'um abzuwarten, bis ihm seine Feinde als Schemel zu Füßen gelegt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Ja, durch ein einziges Opfer hat er für alle Zeit die vollendet, die heilig werden wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Das bezeugt uns auch der Heilige Geist; denn nach den Worten:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '\"Dieses ist mein Bund, den ich nach jenen Tagen mit ihnen schließen will\", spricht der Herr: \"Ich lege meine Gesetze in ihre Herzen und schreibe sie in ihr Inneres,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'und ich will ihrer Sünden und Vergehen nicht mehr gedenken.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Wo aber diese vergeben sind, bedarf es keines Opfers mehr der Sünde wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Liebe Brüder, wir besitzen also voll Zuversicht die Hoffnung, das Heiligtum im Blute Jesu zu betreten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'wohin er uns einen neuen und lebendigen Weg aufgetan hat, durch den Vorhang hindurch, das heißt durch seinen Leib.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Und da wir auch einen hocherhabenen Priester haben, der über dem Hause Gottes waltet,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'laßt uns aufrichtigen Herzens hintreten, in vollem Glauben, die Herzen rein vom sündigen Gewissen, den Leib mit reinem Wasser abgewaschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Wir wollen unerschütterlich am Bekenntnis unserer Hoffnung festhalten. Getreu ist der, der die Verheißungen gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Sorgfältig wollen wir einander im Auge behalten, um uns zur Liebe und zu guten Werken anzuspornen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Bleiben wir doch unserer Versammlung nicht fern, wie einige die Gewohnheit haben; vielmehr ermuntern wir uns gegenseitig, und dies um so mehr, je näher ihr den \"Tag\" erscheinen seht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Denn wenn wir freiwillig sündigen, nachdem wir schon die Wahrheit voll erfaßt haben, dann gibt es kein Opfer für die Sünden mehr;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'wohl aber wartet unser dann ein furchtbares Gericht sowie die Glut des Feuers, das künftig die Widersacher verzehren wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Wenn jemand das Gesetz des Moses übertritt, so muß er ohne Erbarmen sterben auf Aussage von zwei oder drei Zeugen hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Welch größere Strafe wird dann der erleiden müssen, der den Sohn Gottes mit Füßen tritt und das Blut des Bundes, durch das er geheiligt ward, für gemein erachtet und so den Geist der Liebe höhnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Wir kennen doch den, der da sprach: \"Mein ist die Rache; ich will vergelten\"; und weiter noch: \"Der Herr wird sein Volk richten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Furchtbar ist es, in die Hände des lebendigen Gottes zu fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Gedenket der vergangenen Tage, da ihr nach eurer Erleuchtung so viele Leidenskämpfe bestanden habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Bald wurdet ihr an den Pranger gestellt mit Schmähungen und Bedrängnissen, bald nahmt ihr teil am Schicksal solcher, denen es so erging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Ihr habt mit den Gefangenen gelitten und den Raub eurer Habe mit Freuden hingenommen, wohl wissend, daß ihr Besseres und Bleibendes besitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Werft euren Bekennermut doch nicht weg! Er hat einen großen Lohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Standhaftigkeit braucht ihr, daß ihr den Willen Gottes tut und das erlangt, was er verheißen hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, '\"Nur noch eine ganz kleine Weile, und dann kommt der, der kommen soll; er zögert nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Und mein Gerechter, der es aus dem Glauben ist, wird leben. Zieht er sich aber feig zurück, alsdann hat meine Seele an ihm kein Wohlgefallen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Doch wir gehören nicht zu denen, die sich zu ihrem Untergang zurückziehen, vielmehr zu denen, die im Glauben ihre Seele retten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Der Glaube ist eine Zuversicht auf das, was man erhofft, ein Beweis von Dingen, die man nicht sieht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'In ihm erhielten auch die Ahnen schon ihr Ruhmeszeugnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Im Glauben erkennen wir, daß durch das göttliche Wort das Weltall geordnet ward, also das Sichtbare nicht aus der Erscheinungswelt geworden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Im Glauben brachte Abel Gott ein Opfer dar, wertvoller als das des Kain; dafür erhielt er auch das Zeugnis, daß er gerecht sei: ein Zeugnis, das Gott ihm seiner Gaben wegen ausstellte; in ihm redet er noch nach seinem Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Im Glauben wurde Henoch entrückt, daß er den Tod nicht sah; er war nicht mehr zu finden, weil ihn Gott entrückt hatte. Denn vor der Entrückung hat er schon das Zeugnis erhalten, daß er Gott wohlgefalle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Doch ohne Glauben ist es unmöglich, Gott zu gefallen; denn wer Gott naht, muß glauben, daß er ist, und daß er denen, die ihn suchen, ein Vergelter ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Im Glauben erhielt Noe Kunde von dem, was er noch nicht sah, nahm sich in acht und baute eine Arche zur Rettung seines Hauses; in ihm hat er die Welt verurteilt und ward ein Erbe der Rechtfertigung aus dem Glauben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Im Glauben gehorchte Abraham dem Ruf, in ein Land zu ziehen, das er als Erbe erhalten sollte, und so zog er aus und wußte nicht, wohin er käme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Im Glauben siedelte er sich im Lande der Verheißung an wie in einem fremden und wohnte in Zelten mit Isaak und Jakob, den Miterben derselben Verheißung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Er wartete ja auf die Stadt mit festen Grundmauern, deren Baumeister und Gründer Gott ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Im Glauben erhielt Sara noch die Kraft zum Mutterwerden trotz ihres holten Alters, weil sie den für treu hielt, der die Verheißung gegeben hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Darum wurden sie auch von dem einen und dazu Erstorbenen erzeugt so zahlreich wie die Sterne des Himmels, unzählbar wie der Sand am Meeresstrand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Im Glauben starben diese alle, ohne daß sie die verheißenen Güter schon erlangt hätten. Sie hatten sie aus weiter Ferne nur gesehen und begrüßt und so bekannt, daß sie nur Pilgrime und Fremdlinge auf Erden seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Denn die so sprechen, zeigen, daß sie eine Heimat suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Hätten sie dabei an das Land gedacht, aus dem sie ausgezogen waren, so hätten sie die Möglichkeit gehabt, dorthin zurückzukehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'So aber trachten sie nach einem besseren, das heißt nach dem himmlischen. Darum scheut sich Gott auch nicht, sich ihren Gott nennen zu lassen; er hat ja ihnen eine Stadt bereitet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Im Glauben brachte Abraham, als er erprobt werden sollte, den Isaak als Opfer dar; er wollte seinen einzigen Sohn darbringen; er, der doch die Verheißung empfangen hatte,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'als zu ihm gesprochen ward: \"Du sollst in Isaak Nachkommen erhalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Er dachte eben: \"Gott kann sogar Tote wieder auferwecken\", und so erhielt er ihn zugleich als Sinnbild wiederum zurück.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Im Glauben segnete Isaak den Jakob und den Esau auch für die künftigen Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Im Glauben segnete der sterbende Jakob die beiden Söhne Josephs und betete, gestützt auf die Spitze seines Stabes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Im Glauben dachte Joseph noch beim Sterben an den Auszug der Kinder Israels und gab Anweisung über seine Gebeine.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Im Glauben ward nach der Geburt Moses von seinen Eltern noch drei Monate lang verborgen gehalten; sie sahen nämlich, daß das Kind lieblich war, und fürchteten den Befehl des Königs nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Im Glauben lehnte Moses, als er schon erwachsen war, es ab, sich Sohn der Tochter Pharaos nennen zu lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Er wollte lieber mit dem Volke Gottes Leid ertragen, als nur vorübergehenden Genuß von Sünde haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'So hielt er die Schmach Christi für einen größeren Reichtum als Ägyptens Schätze. Er blickte ja auf die Vergeltung hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Im Glauben verließ er das Ägypterland und fürchtete den Zorn des Königs nicht. Und standhaft hielt er aus, als hätte er den Unsichtbaren sichtbar vor Augen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Im Glauben hielt er das Pascha und ordnete das Blutbestreichen an, damit der Würgengel nicht ihre Erstgeburt vernichte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Im Glauben durchschritten sie das Rote Meer wie trockenes Land, während die Ägypter beim gleichen Versuche verschlungen wurden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Im Glauben stürzten auch die Mauern Jerichos zusammen, nachdem man an sieben Tagen um sie herumgezogen war.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Im Glauben kam die Dirne Rahab nicht mit jenen Unfolgsamen um, weil sie die Kundschafter friedlich aufgenommen hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Doch wozu soll ich noch weiter reden? Es fehlt mir die Zeit, um alles durchzugehen von Gedeon und Barak, Samson und Jephte, von David, Samuel und den Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Im Glauben rangen diese Königreiche nieder, schufen Recht, erlangten Verheißungen; sie schlossen Löwenrachen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'löschten Feuersgluten aus, entgingen der Schärfe des Schwertes. Aus Schwachheit kamen sie zu Kraft und wurden Helden im Kampf und brachten fremde Heere zum Weichen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Frauen erhielten ihre Toten durch die Wiederaufweckung zurück. Andere wurden gemartert und wollten nichts von der Freilassung wissen, um eine wundervollere Auferstehung zu erlangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Und wieder andere mußten Spott und Geißelung verkosten, andere Ketten und Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Sie wurden gesteinigt und gefoltert und zersägt, durchs Schwert getötet; in Schaf- und Ziegenfellen zogen sie umher, in Not, bedrängt, mißhandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Die Welt war ihrer nicht wert. In Einöden und im Gebirge irrten sie umher, in Höhlen und in Erdklüften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Und doch, sie alle, obwohl so große Glaubenszeugen, erlangten die verheißenen Güter nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Gott hatte noch etwas Herrlicheres für uns vorgesehen: jene sollten nicht ohne uns zur Vollendung kommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'So wollen denn auch wir, da wir von einer solchen Wolke von Glaubenszeugen uns umgeben sehen, jede Last ablegen, zumal die Sünde, die uns so leicht bestrickt. Dann wollen wir mit Ausdauer im Wettkampf laufen, der uns obliegt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'dabei auf Jesus blickend, den Begründer und Vollender unseres Glaubens. Freude lag für ihn bereit; aber er erduldete anstatt ihrer das Kreuz, der Schmach nicht achtend. Jetzt sitzt er zur Rechten des Thrones Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'O, lebt euch in den hinein, der solchen Widerspruch der Sünder gegen sich erduldet hat, damit ihr nicht ermattet und an eurer Seele schlaff werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Noch widerstandet ihr im Kampfe mit der Sünde nicht bis aufs Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Dagegen habt ihr die Mahnung vergessen, die euch wie Söhnen zuredet: \"Mein Sohn, achte die Züchtigung des Herrn nicht gering, verzage nicht, wenn du von ihm zurechtgewiesen wirst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Denn wen der Herr liebhat, den züchtigt er; er schlägt jeden Sohn, zu dem er als Vater sich bekennt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Ihr duldet der Erziehung wegen; wie mit Söhnen verkehrt Gott mit euch. Wo wäre je ein Sohn, den der Vater nicht züchtigte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Und wenn ihr ohne Züchtigung, unter der alle stehen, bliebet, so wäret ihr Bastarde und nicht echte Söhne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Wenn wir unter der strengen Zucht unserer leiblichen Väter gestanden haben und Ehrfurcht vor ihnen hatten, sollten wir uns nicht noch mehr dem Vater der Geister unterwerfen, um zu leben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Jene hielten uns nur kurze Zeit nach ihrem Gutdünken in Zucht; er aber tut\'s zu unserem Besten, auf daß wir an seiner Heiligkeit teilnehmen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Jede Züchtigung scheint für den Augenblick nicht Freude, vielmehr Betrübnis einzutragen, doch nachher trägt sie denen, die in ihr geschult sind, als heilsame Frucht Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'So richtet denn die schlaffen Hände und die müden Knie wieder auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'und wandelt zielsichere Wege, damit, was lahm ist, sich nicht ganz ausrenke, vielmehr geheilt werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Trachtet nach Frieden mit allen und nach Heiligung; denn ohne sie wird niemand je den Herrn schauen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Sorgt, daß keiner der Gnade Gottes sich entziehe, daß nicht ein giftiges Gewächs emporwachse und um sich greife und viele dadurch befleckt werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'daß keiner ein Ehebrecher sei oder ein so gemeiner Mensch wie Esau, der sein Erstgeburtsrecht wegen einer einzigen Speise preisgab.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Ihr wisset ja, daß er den Segen nachher noch empfangen wollte und daß er abgewiesen wurde; er fand keine Möglichkeit für eine Sinnesänderung, obwohl er unter Tränen sie herbeizuführen suchte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ihr seid nicht zu einem Berge, den man berühren kann, hinzugetreten, zu einer Feuerflamme, zu Dunkel, Finsternis, Gewittersturm');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'und zu Posaunenschall und laut erdröhnenden Worten; bei ihnen baten ja die Zuhörer, es möchte nicht mehr weiterhin so zu ihnen gesprochen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Denn sie vermochten nicht, die Verordnung zu ertragen: \"Wenn nur ein Tier den Berg berührt, so soll es gesteinigt werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Und die Erscheinung war so furchtbar, daß Moses selber sprach: \"Ich bin voll Furcht und Zittern.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Nein, ihr seid zum Berge Sion, zu der Stadt des lebendigen Gottes hinzugetreten, zum himmlischen Jerusalem und zu den Myriaden Engeln, zu der festlichen Gemeinde');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'der Erstgeborenen, die in den Himmeln aufgeschrieben sind, zu Gott, dem Richter aller, und zu den Seelen der vollendeten Gerechten');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'und zu dem Bürgen des Neuen Bundes, Jesus, und zum Besprengtwerden mit seinem Blute, das eindringlicher redet als das Blut Abels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'So seht denn zu, daß ihr den, der redet, nicht ablehnt. Denn wenn jene schon der Strafe nicht entgingen, die ihn, als er sich auf Erden offenbarte, abgewiesen haben, um wieviel weniger dann wir, wenn wir den abweisen, der aus dem Himmel zu uns redet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Damals erschütterte seine Stimme die Erde, jetzt aber gab er die Verheißung: \"Noch einmal will ich nicht bloß die Erde erschüttern, sondern auch den Himmel.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Das \"Noch einmal\" weist darauf hin, daß das, was erschüttert wird, als ein Geschaffenes eine Umwandlung erfahren wird, damit das bleibe, was sich nicht erschüttern läßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'So laßt uns denn, weil wir ein unerschütterliches Reich in Aussicht haben, jetzt unsere Dankbarkeit dadurch bezeugen, daß wir in Scheu und Ehrfurcht Gott wohlgefällig dienen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'denn \"unser Gott ist ein verzehrendes Feuer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Die Bruderliebe soll bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Vergesset nicht die Gastfreundschaft. Ohne es zu wissen, haben einige dadurch Engel beherbergt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Gedenket der Gefangenen, als wäret ihr mitgefangen, und der Mißhandelten als solche, die noch im Leibe leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Die Ehe sei bei allen ehrbar und unbefleckt das Ehebett. Unzüchtige und Ehebrecher wird Gott richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Euer Lebenswandel sei frei von Geldgier. Seid mit dem zufrieden, was ihr habt. Er selbst hat ja gesagt: \"Ich werde niemals dich verlassen und nie dich preisgeben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'So können wir getrost erklären: \"Mein Helfer ist der Herr; ich brauche mich nicht zu fürchten; was könnte auch ein Mensch mir antun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Erinnert euch an eure Vorsteher, die euch das Wort Gottes verkündet haben. Betrachtet genau das Ende ihres Wandels und ahmt ihren Glauben nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus ist immer derselbe, gestern, heute und in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Laßt euch durch allerlei fremdartige Lehren nicht irremachen. Es ist doch besser, das Herz durch Gnaden stark zu machen als durch Opferspeisen, von denen jene keinen Nutzen hatten, die davon lebten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Wir haben einen Altar, von dem die nicht essen dürfen, die dem Zelte dienen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Denn die Leiber jener Tiere, von deren Blut vom Hohenpriester zur Sühne für die Sünden etwas in das Allerheiligste getragen wird, werden außerhalb des Lagers verbrannt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Darum hat auch Jesus, um durch sein Blut sein Volk zu heiligen, außerhalb des Stadttores gelitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'So laßt uns denn zu ihm vors Tor hinausgehen und seine Schmach tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Wir haben hienieden keine bleibende Stätte: wir trachten vielmehr nach der kommenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Wir wollen Gott durch ihn beständig Lobopfer bringen; die Frucht von Lippen meine ich, die seinen Namen preisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Vergeßt nicht, wohltätig zu sein und mitzuteilen; an solchen Opfern hat Gott Wohlgefallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Gehorchet euern Vorstehern und folget ihnen. Sie wachen nämlich über eure Seelen, weil sie darüber Rechenschaft ablegen müssen. O, möchten sie doch dies mit Freude tun und nicht mit Seufzen. Das brächte euch ja keinen Nutzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Betet für uns! Wir sind überzeugt, daß wir ein gutes Gewissen haben, weil wir in allem rechtschaffen zu wandeln suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Um so inniger ermahne ich euch, dies zu tun, damit ich um so rascher euch wiedergegeben werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Der Gott des Friedens, der den erhabenen Hirten der Schafe, unseren Herrn Jesus, durch das Blut des ewigen Bundes von den Toten auferweckt hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'befähige euch zu allem Guten, damit ihr seinen Willen tut. Durch Jesus Christus wirkte er in uns, was vor ihm wohlgefällig ist. Ihm sei Ehre von Ewigkeit zu Ewigkeiten! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ich bitte euch, meine Brüder, nehmt dieses Mahnwort willig auf; ich habe euch ja nur kurz geschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wißt, daß Timotheus, unser Bruder, wieder frei ist; ich werde euch mit ihm besuchen, sobald er kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Grüßt alle eure Vorsteher und alle Heiligen! Es grüßen euch die Brüder in Italien!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Die Gnade sei mit euch allen! Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobus, Knecht Gottes und des Herrn Jesu Christi, entbietet seinen Gruß den zwölf Stämmen in der Diaspora.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Haltet es für lauter Freude, meine Brüder, wenn ihr in mannigfache Versuchungen geratet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Ihr wisset ja: Wenn euer Glaube echt ist, dann wirkt er Geduld,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'und die Geduld soll zur Vollendung führen, damit ihr vollendet seid, ohne Tadel, ohne Fehl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Fehlt es aber einem unter euch an Weisheit, so bitte er Gott, der allen ohne weiteres und ohne harte Worte gibt, und sie wird ihm gegeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Nur bete er mit gläubigem Vertrauen und zweifle nicht im mindesten. Wer zweifelt, gleicht einer Meereswoge, die vom Sturme gepeitscht und hin- und hergeworfen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Ein solcher Mensch soll ja nicht meinen, vom Herrn etwas zu empfangen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'der Mann mit den zwei Seelen, unbeständig auf allen seinen Wegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Der arme Bruder rühme sich seiner Hoheit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'der reiche aber der Armseligkeit; wird er doch vergehen wie die Blüte des Grases:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Wenn die Sonne und der Glutwind sich zumal erheben, alsdann verdorrt das Gras, und seine Blüte welkt; sein schöner Anblick ist dahin. So wird auch der Reiche bei seinen Unternehmungen dahinwelken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Glückselig der Mann, der die Prüfung besteht! Bewährt er sich, so wird er den Kranz des Lebens empfangen, den der Herr denen verheißen hat, die ihn lieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Keiner, der versucht wird, sage: \"Gott versucht mich!\" Gott kann zum Bösen nicht versucht werden, und er selbst versucht niemanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ein jeder wird vielmehr von der eigenen Begierlichkeit versucht, die ihn lockt und ködert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Hat die Begierlichkeit empfangen, so gebiert sie die Sünde, die Sünde aber, ausgereift, gebiert den Tod.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Laßt euch nicht irreführen, meine vielgeliebten Brüder!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'jede gute Gabe und jedes vollkommene Geschenk kommt von oben her, vom Vater der Lichter, bei dem es keine Veränderung gibt und keinen Schatten von Veränderlichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Mit freiem Willen hat er durch das Wort der Wahrheit uns gezeugt, damit wir so gewissermaßen Erstlinge seiner Schöpfung seien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Wißt, meine lieben Brüder: jeder Mensch sei schnell bereit zum Hören, zum Reden aber langsam, langsam zum Zorn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Des Menschen Zorn bewirkt nicht, was recht macht vor Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Legt jeden Schmutz und jeden Rest von Schlechtigkeiten ab und nehmt in Sanftmut das Wort an, das euch eingepflanzt ward, das eure Seelen retten kann.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Werdet Täter des Wortes und nicht nur Hörer, die sich selber täuschen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Wer nur Hörer des Wortes ist und nicht auch Täter, gleicht einem Manne, der sein natürliches Aussehen in einem Spiegel beschaut,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'dann aber, hat er sich betrachtet, weggeht und sogleich vergißt, wie er ausgesehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Wer aber in das vollkommene Gesetz der Freiheit hineingeschaut hat und auch dabei verbleibt, wer nicht ein vergeßlicher Hörer ist, vielmehr ein tätiger Vollbringer, wird durch sein Wirken selig werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Wenn einer meint, er sei fromm, doch seine Zunge nicht im Zaume hält, vielmehr sein Herz betrügt, dessen Frömmigkeit ist nichts.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Vor Gott, dem Vater, ist nur dies eine reine, makellose Frömmigkeit: die Waisen und Witwen in ihrer Trübsal aufzusuchen und sich selber unbefleckt zu bewahren vor der Welt');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meine Brüder, haltet den Glauben an unseren verherrlichten Herrn Jesus Christus frei von Parteilichkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Betritt zum Beispiel eure Versammlung, ein Mann mit goldenem Fingerring und prächtigem Kleid, zugleich erscheint ein Armer in unansehnlichem Kleid,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'und ihr richtet eure Blicke auf den mit prächtigem Kleid hin und sagt zu ihm: \"Setze du dich hier auf den bequemen Platz!\", zu dem Armen aber: \"Stelle dich dorthin!\" oder: \"Setze dich hier unten neben meinen Schemel!\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'habt ihr denn da bei euch nicht einen Unterschied gemacht, und wurdet ihr nicht Richter nach ganz schlechten Grundsätzen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Hört, meine lieben Brüder! Hat Gott nicht die, die vor der Welt arm sind, auserwählt, im Glauben reich zu sein und Erben jenes Reiches, das er denen verheißen hat, die ihn lieben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Und ihr verunehrt den Armen. Sind es nicht die Reichen, die euch vergewaltigen, sind nicht sie es, die euch vor die Gerichte zerren,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'und lästern nicht gerade sie den edlen Namen, der über euch angerufen worden ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Wenn ihr jedoch das königliche Gesetz erfüllt, das nach der Schrift lautet: \"Du sollst deinen Nächsten lieben wie dich selbst\", dann tut ihr recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Doch nehmt ihr auf die Menschen Rücksicht, alsdann begeht ihr eine Sünde, und es überführt euch das Gesetz als Übertreter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Mag einer das Gesetz auch ganz erfüllen, in einem einzigen Punkt es aber übertreten, so hat er sich gegen alle verfehlt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Denn er, der sprach: \"Du sollst nicht ehebrechen\", hat auch gesagt: \"Du sollst nicht töten.\" Brichst du zwar nicht die Ehe, aber tötest du, so hast du das Gesetz doch übertreten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Redet und handelt wie solche, die durch das Gesetz der Freiheit abgeurteilt werden sollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Erbarmungslos kommt das Gericht über den, der selber kein Erbarmen übt. Barmherzigkeit dagegen triumphiert über das Gericht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Was nützt es, meine Brüder, wenn einer sagt, er habe Glauben, aber keine Werke aufzuweisen hat? Kann denn der Glaube ihn retten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Fehlt es einem Bruder oder einer Schwester an der Kleidung oder ermangeln sie der täglichen Nahrung,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'und einer aus euch sagt zu ihnen: \"Geht hin im Frieden, zieht euch warm an und sättigt euch!\", ihr gebt ihnen aber nicht, was für den Leib nötig ist, was nützt es dann?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Also verhält es sich auch mit dem Glauben; wenn er keine Werke aufzuweisen hat, ist er für sich allein tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Doch da könnte jemand sagen: \"Du hast den Glauben, und ich habe Werke.\" - Zeige mir deinen Glauben ohne Werke, dann will auch ich aus meinen Werken dir den Glauben zeigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du glaubst: es gibt nur einen Gott. Ganz recht! Auch die Dämonen glauben und erschaudern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Willst du nun einsehen, du Tor, daß der Glaube ohne Werke wertlos ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ward unser Vater Abraham nicht aus Werken gerechtfertigt, als er seinen Sohn Isaak auf dem Altare dargebracht hatte?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Du siehst, wie der Glaube bei seinen Werken mitwirkte und daß der Glaube aus den Werken erst zur Vollendung kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'So ward die Schrift erfüllt, die sagt: \"Abraham glaubte Gott, und dies ward ihm als Gerechtigkeit angerechnet\" und \"er ward Freund Gottes genannt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Ihr seht also, daß der Mensch aus Werken gerecht wird und nicht aus dem Glauben allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Und wurde nicht in gleicher Weise auch die Dirne Rahab aus Werken gerechtfertigt, weil sie die Kundschafter bei sich aufnahm und sie auf einem anderen Wege wiederum entließ?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Denn wie der Leib ohne Seele tot ist, so ist auch der Glaube ohne Werke tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Meine Brüder, drängt euch nicht als Lehrer auf! Ihr wisset, daß wir dadurch ein strengeres Gericht erwarten müssen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Wir alle fehlen ja in vielem; wer sich aber im Reden nicht verfehlt, der ist vollendet und fähig, auch den ganzen Leib im Zaume zu halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Wenn wir den Pferden den Zaum ins Maul einlegen, damit sie uns gehorchen, so lenken wir damit auch ihren ganzen Körper.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Seht auch die Schiffe; sie mögen noch so groß sein, von noch so starken Winden hin und her getrieben werden, sie lassen sich durch ein ganz kleines Steuerruder lenken, wohin der Steuermann es haben will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'So ist auch die Zunge zwar ein kleines Glied und rühmt sich dennoch großer Dinge. Seht, welch kleines Feuer einen noch so großen Wald in Brand setzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Auch die Zunge ist ein Feuer, eine ganze Welt der Ungerechtigkeit. Die Zunge ist unter unseren Gliedern die Macht, die den ganzen Leib befleckt und das Rad des Lebens in Brand setzt, sie, die ihr Feuer von der Hölle erhält.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Jedwede Art von Landtieren und Vögeln, von kriechenden Tieren und von Wassertieren, wird gezähmt und ward noch immer von der menschlichen Natur gezähmt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'die Zunge aber kann kein Mensch zähmen; dieses nimmermüde Übel voll von Todesgift.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Mit ihr preisen wir den Herrn und Vater, mit ihr verfluchen wir die Menschen, die doch nach dem Ebenbild Gottes geschaffen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Demselben Mund entquillt so Segen und Fluch. Meine Brüder, so darf es nicht sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Sprudelt denn die Quelle aus derselben Mündung süßes und bitteres Wasser?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Kann denn, meine Brüder, der Feigenbaum Oliven tragen oder der Weinstock Feigen? Eine Salzquelle kann doch kein Süßwasser spenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Wer aus euch ist weise und verständig? Er zeige durch guten Lebenswandel seine Werke in sanftmütiger Weisheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Hegt ihr dagegen bittere Leidenschaftlichkeit sowie Rechthaberei in eurem Herzen, dann höret auf, euch zu rühmen und der Wahrheit ins Gesicht zu lügen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Das ist nicht die Weisheit, die von oben kommt; nein, eine irdische, sinnliche, teuflische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Denn wo Leidenschaftlichkeit vorherrscht und Rechthaberei, da ist Unordnung und jegliche Verkehrtheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Die Weisheit aber, die von oben stammt, ist vor allen Dingen lauter, dann friedliebend, bescheiden, folgsam, dem Guten zugetan, voll Erbarmen, voll guter Früchte, unparteiisch, ehrlich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Die Frucht der Gerechtigkeit wird ausgesät im Frieden für die, die selber Frieden halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Woher kommt Zank und woher Streit bei euch? Woher denn anders als von euren Lüsten, die in euren Gliedern streiten?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ihr begehrt, doch erhaltet es nicht; ihr mordet und eifert und könnt es doch nicht erlangen; ihr kämpft und streitet und erlangt es nicht, weil ihr nicht betet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Ihr betet und erhaltet es dennoch nicht, weil ihr schlecht betet; ihr wollt es in eurer Gier vergeuden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ihr Ehebrecher! Wisset ihr denn nicht, daß Freundschaft mit der Welt Feindschaft gegen Gott bedeutet? Wer also Freund der Welt sein will, erweist sich als Feind Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Oder meint ihr, die Schrift sage umsonst: \"In Eifersucht verlangt es ihn nach dem Geiste, den er in uns hat Wohnung nehmen lassen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Doch um so größer ist dann auch die Gnade, die er schenkt. Deshalb heißt es: \"Gott widersteht den Hochmütigen, den Demütigen aber gibt er Gnade.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'So unterwerfet euch denn Gott und widersteht dem Teufel, dann wird er von euch fliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nähert euch Gott, und dieser wird sich auch euch nähern. Reinigt eure Hände, ihr Sünder, und heiligt eure Herzen, ihr Doppelseelen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Empfindet euer Elend; klagt und weint. Euer Lachen wandle sich in Trauer und eure Freude in Niedergeschlagenheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Demütigt euch vor dem Herrn, und dieser wird euch erhöhen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Verleumdet einander nicht, meine Brüder! Wer seinen Bruder verleumdet oder richtet, der richtet und verleumdet das Gesetz. Wenn du aber das Gesetz richtest, dann bist du nicht Täter, sondern Richter des Gesetzes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Nun gibt es aber nur einen einzigen Gesetzgeber und Richter, den, der die Macht hat, zu retten oder zu verderben. Wer bist du denn, daß du den Nächsten richtest?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Wohlan denn, ihr, die ihr da sagt: \"Heute oder morgen wollen wir in diese oder jene Stadt reisen, daselbst ein Jahr verbringen, Geschäfte machen und verdienen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Ihr wisset ja nicht, was der morgige Tag bringt! Was ist denn euer Leben? Ihr seid ein Rauch, der nur auf kurze Zeit zu sehen ist und dann verschwindet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Sagt doch lieber: \"Wenn der Herr es will und wir noch leben, dann werden wir dieses oder jenes tun.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'So aber rühmt ihr euch mit euren Prahlereien. Ein jedes Rühmen solcher Art ist schlecht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Wer aber Gutes zu tun weiß und es nicht tut, dem ist es Sünde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Wohlan, ihr Reichen! Weint und klagt über alles Elend, das über euch kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vermodert ist euer Reichtum, und eure Kleider sind zerfressen von den Motten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'euer Gold und Silber ist verrostet; es wird ihr Rost noch gegen euch zeugen und euren Leib wie Feuer fressen. Noch in den \"Letzten Tagen\" habt ihr Reichtümer gesammelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Seht, es schreit der von euch vorenthaltene Lohn der Arbeiter, die eure Felder abgeerntet haben, und dieser Klageschrei der Schnitter drang zu den Ohren des Herrn der Heerscharen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ihr habt geschwelgt auf Erden und gepraßt, habt euch gemästet noch am \"Schlachttag\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Den Gerechten aber habt ihr verurteilt und gemordet; er leistet euch ja keinen Widerstand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'So harret, meine Brüder, denn geduldig aus bis zu der Ankunft des Herrn. Seht, der Landmann wartet auf die kostbare Frucht der Erde; er wartet in Geduld, bis er den Früh- und Spätregen erhalten hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'So haltet auch ihr geduldig aus und richtet eure Herzen auf; die Ankunft des Herrn ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Murrt, meine Brüder, nicht gegeneinander, damit ihr nicht gerichtet werdet. Seht, der Richter steht schon vor der Tür.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Brüder, nehmt im Leiden und im Dulden die Propheten, die im Namen des Herrn geredet haben, zum Vorbild.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Seht, wir preisen die selig, die ausgeharrt haben. Ihr habt von der Geduld des Job gehört und habt gesehen, welchen Ausgang der Herr gegeben hat; denn der Herr ist voll Erbarmen und Mitleid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Vor allem, meine Brüder, sollt ihr nicht schwören. Nicht bei dem Himmel und nicht bei der Erde, noch einen anderen Eid. Es sei bei euch das Ja ein Ja und euer Nein ein Nein, damit ihr nicht dem Gerichte verfallet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Leidet jemand unter euch, so soll er beten. Geht es einem gut, alsdann lobsinge er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ist einer bei euch krank, er rufe die Presbyter der Kirche zu sich; sie sollen über ihn beten und ihn dabei mit Öl salben im Namen des Herrn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Das gläubige Gebet wird dem Kranken zum Heile sein; der Herr wird ihn aufrichten, und wenn er Sünden begangen hat, so werden sie ihm vergeben werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekennet also einander eure Sünden und betet füreinander, damit ihr geheilt werdet. Viel vermag ja das anhaltende Gebet eines Gerechten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias war ein Mensch gleicher Art wie wir; er betete inständig, daß es nicht regnen möge; und es regnete im Lande drei Jahre und sechs Monate nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Er betete dann abermals, und alsbald gab der Himmel Regen, und die Erde brachte ihre Frucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Meine Brüder! Irrt einer unter euch von der Wahrheit ab und führt ihn jemand dann zurück, der wisse, wer einen Sünder von seinem Irrweg zurückführt, der rettet seine Seele vom Tod und deckt eine Menge Sünden zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, '');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, Apostel Jesu Christi, an die auserwählten Fremdlinge in der Diaspora von Pontus, Galatien, Kappadozien, Asien und Bithynien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Erwählt seid ihr, weil Gott, der Vater, es vorhergewußt, geheiligt durch den Geist, damit ihr gehorsam seid und mit dem Blute Jesu Christi besprengt werdet. In reicher Fülle werde Gnade euch zuteil und Friede!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gepriesen sei der Gott und Vater unseres Herrn Jesus Christus. In seiner großen Huld hat er uns wiedergeboren zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'zu einem unvergänglichen, unbefleckten und unverwelklichen Erbe, das in den Himmeln für euch aufbewahrt ist,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'für euch, die ihr in Gottes Allmacht behütet werdet des Glaubens wegen für das Heil, das in der Endzeit offenkundig werden soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Dann werdet ihr darob frohlocken, indes ihr jetzt, falls es nötig ist, in mannigfachen Prüfungen auf kurze Zeit Betrübnis habt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Dadurch soll ja euer Glaube nur erprobt und wertvoller erfunden werden als das vergängliche Gold, das im Feuer geläutert wird. Ihr sollt so zum Lob und Preis und Ruhme dienen bei der Offenbarung Jesu Christi.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Ihn liebt ihr, obwohl ihr ihn nicht gesehen habt, ihr glaubt an ihn, ohne ihn jetzt zu schauen. Deswegen werdet ihr in unaussprechlicher, verklärter Freude auch frohlocken,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'wenn ihr das Ziel eures Glaubens erlangt habt, das Heil der Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Nach diesem Heile suchten forschend die Propheten, die von der Gnade weissagten, die euch zuteil geworden ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Sie forschten nach dem Wann und Wie, auf die sie der Geist Christi, den sie besaßen, hinwies, da er die Leiden Christi vorhergesagt hat und die darauf folgende Verklärung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Es wurde ihnen ja geoffenbart, daß sie nicht sich, sondern euch zu Dienste seien mit dem, was von den Predigern des Evangeliums euch jetzt verkündet wird in Kraft des vom Himmel ausgesandten Heiligen Geistes, worin Engel einen Einblick haben möchten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Umgürtet also die Lenden eures Geistes und seid besonnen, setzet gänzlich eure Hoffnung auf die Gnade, die bei der Offenbarung Jesu Christi euch zuteil werden wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Folgsamen Kindern gleich, gestaltet euer Leben nicht nach den früheren Lüsten, wie in den Zeiten der Unwissenheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Vielmehr wie der, der euch berufen hat, heilig ist, so sollt auch ihr in eurem ganzen Lebenswandel heilig werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Darum steht ja auch geschrieben: \"Seid heilig, wie ich heilig bin.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Und wenn ihr den als Vater anrufet, der ohne Ansehen der Person jeden nach seinem Werke richtet, so führt einen Lebenswandel voll von Gottesfurcht, solange ihr hier als Fremdlinge verweilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Ihr wißt ja, daß ihr nicht um Vergängliches, um Silber oder Gold, losgekauft seid von eurem törichten, von den Vätern her ererbten Lebenswandel,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'sondern um das kostbare Blut Christi als eines fehlerlosen und makellosen Lammes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Erwählt war er ja schon vor Grundlegung der Welt; erschienen aber ist er euretwegen erst am Ende der Zeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Durch diesen glaubt ihr an Gott, der ihn von den Toten erweckt und ihm auch Herrlichkeit verliehen hat. So ist nun euer Glaube auch Hoffnung auf Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Durch Folgsamkeit der Wahrheit gegenüber weihet eure Seelen zu beharrlicher Bruderliebe ein und habt von Herzen einander innig lieb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Ihr seid ja nicht aus einem vergänglichen Samen wiedergeboren, sondern aus einem unvergänglichen, durch das Wort Gottes, das lebendig und beständig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, '\"Denn alles Fleisch ist wie Gras, und alle seine Herrlichkeit wie des Grases Blüte; das Gras verdorrt, und seine Blüte welkt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'das Wort des Herrn bleibt aber in Ewigkeit.\" Das ist das Wort, das euch verkündet ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'So legt denn alle Bosheit und alle Arglist ab, die Heuchelei, den Neid und jegliche Verleumdungssucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Wie neugeborene Kinder verlangt nach der geistigen und unverfälschten Milch, um dadurch zum Heile heranzuwachsen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Ihr habt ja schon verkostet, wie der Herr so gütig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Schließt euch ihm an, dem lebendigen Steine, der von den Menschen zwar verworfen, bei Gott jedoch kostbar und auserlesen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Dann werdet auch ihr als lebendige Steine auferbaut zu einem geistigen Hause, zu einem heiligen Priestertum, um geistige Opfer darzubringen, die Gott durch Jesus Christus wohlgefällig sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Es heißt ja in der Schrift: \"Siehe, ich lege in Sion einen Schlußstein, ganz auserlesen und in Ehren; wer an ihn glaubt, wird nicht zuschanden werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Euch nun, die ihr glaubt, winkt die Ehre, dem Ungläubigen aber \"ist der Stein, den die Bauleute verworfen haben, zum Schlußstein geworden\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'und zum Steine des Anstoßes und zum Felsen des Ärgernisses. Sie stoßen sich an ihm, weil sie dem Worte nicht gehorchen; dazu sind sie nun allerdings ja auch bestimmt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ihr seid aber das auserlesene Geschlecht, die königliche Priesterschaft, ein heiliger Stamm, ein Volk, bestimmt zum Eigentum, damit ihr die großen Taten dessen kündet, der euch aus der Finsternis in sein wunderbares Licht berufen hat,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'euch, die ihr einst ein \"Nichtvolk\" waret, nun aber \"Gottesvolk\" geworden seid, einst \"Nichtbegnadigte\", doch jetzt \"Begnadigte\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Geliebte, ich ermahne euch: Enthaltet euch als Fremdlinge und Pilger der sinnlichen Begierden, die wider eure Seele streiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Tadellos sei euer Lebenswandel vor den Heiden. Dann werden sie, wie sie euch als Übeltäter verleumden, wegen eurer guten Werke, die sie sehen, Gott verherrlichen am Tage, da er sie heimsucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Seid um des Herrn willen jeder Art von Menschen untertan, sei es dem König, als dem höchsten Herrn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'sei es den Statthaltern, als von ihm gesandt, die Übeltäter zu bestrafen und Rechtschaffene zu belohnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Denn dies ist der Wille Gottes, daß ihr durch einen guten Lebenswandel den Unverstand einfältiger Menschen zum Schweigen bringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Seid untertan als Freie, nicht als solche, die ihre Freiheit nur als Deckmantel der Schlechtigkeit mißbrauchen, vielmehr als Knechte Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Erweiset jedem Achtung, liebt die Brüder, fürchtet Gott und ehrt den König.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Ihr Sklaven, seid euren Herrn untertan in aller Furcht, nicht bloß den gütigen und milden, sondern auch den launenhaften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Denn das ist wohlgefällig, wenn man an Gott denkt und dabei das Leid erträgt, das man ungerecht leiden muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Was für ein Verdienst wäre auch dabei, wenn ihr für Verfehlungen Schläge leiden würdet? Doch wenn ihr rechtschaffen handelt und trotzdem Leid erduldet, so ist dies bei Gott wohlgefällig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Dazu seid ihr ja auch berufen; auch Christus hat für euch gelitten und euch ein Beispiel hinterlassen, damit ihr in seine Fußtapfen tretet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, '\"Er beging keine Sünde; in seinem Mund fand sich kein Trug.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Er ward geschmäht und schmähte nicht, er litt und drohte nicht; er stellte vielmehr seine Sache dem anheim, der richtet in Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Er trug an seinem Leib unsere Sünden selber auf das Holz, damit wir, den Sünden abgestorben, der Gerechtigkeit leben. Durch seine Wunden wurdet ihr geheilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Wie Schafe hattet ihr euch verlaufen; jetzt aber seid ihr heimgekehrt zum Hirten und Hüter eurer Seelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Desgleichen seid ihr Frauen euren Männern untertan. Dann werden solche, die etwa dem Worte nicht gehorchen, durch den Lebenswandel der Frauen ohne Worte gewonnen werden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'wenn sie euren gottesfürchtigen und heiligen Wandel sehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Ihr Sinnen sei auch nicht der äußerliche Schmuck: Haargeflechte, goldene Anhänger und Kleiderpracht;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'sondern der verborgene Mensch des Herzens, mit einer sanften, ruhigen Gemütsart unvergänglich schön geschmückt; vor Gott ist dies ja alles wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'So schmückten sich einst auch die heiligen Frauen, die, ihren Männern untertan, auf Gott hofften;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'so wie Sara dem Abraham gehorchte und ihn \"Herr\" nannte. Ihr seid dann ihre Töchter, wenn ihr rechtschaffen handelt und keine Einschüchterungen fürchtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Auch ihr, ihr Männer, lebt vernünftig mit dem Weibe. Es ist der schwächere Teil, und erweist ihnen Ehre. Sie erben ja mit euch die Gnade des Lebens. Durch nichts wird euer Beten dann behindert sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Seid endlich alle einträchtig, mitleidend, brüderlich, barmherzig, (bescheiden,) demütig;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'vergeltet Böses nicht mit Bösem, nicht Schmähungen mit Schmähungen; im Gegenteil, segnet. Denn dazu seid ihr berufen, Segen zu erben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '\"Wer seines Lebens froh sein will und glückliche Tage sehen möchte, der halte seine Zunge vom Bösen fern, von trügerischer Rede seine Lippen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'der lasse das Böse und vollbringe das Gute, der suche den Frieden und jage ihm nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Denn die Augen des Herrn ruhen auf den Gerechten, und seine Ohren hören auf ihr Flehen; die Übeltäter aber trifft der Zornesblick des Herrn.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Wer sollte euch auch Böses tun, wenn ihr für das Gute Eifer zeigt?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Doch selig, wenn ihr der Gerechtigkeit zuliebe leiden müßt. Fürchtet ihre Drohungen nicht und laßt euch nicht einschüchtern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Haltet vielmehr in euren Herzen den Herrn Christus heilig. Seid stets bereit, euch jedem gegenüber zu verantworten, der über diese eure Hoffnung Rechenschaft von euch verlangt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Bewahret euch jedoch dabei ein ruhiges Gewissen mit Sanftmut und Ehrfurcht. So sollen die, die euer gutes christliches Leben schlimm verdächtigen, zuschanden werden, eben dadurch, womit sie euch verleumden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Es ist doch besser, für rechtschaffenes Verhalten Leid zu tragen, wenn es Gottes Wille also fügen sollte, als für schlechtes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Auch Christus mußte der Sünde wegen einmal sterben, der Gerechte für die Ungerechten, um euch zu Gott hinzuführen. Den Tod erlitt er zwar dem Leibe nach; zum Leben aber wurde er dem Geiste nach erweckt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'In ihm ging er auch hin und predigte den Seelen im Gefängnis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Diese waren einstens ungläubig gewesen, als Gottes Langmut in den Tagen Noes wartete, indes die Arche angefertigt ward, in der nur wenige, acht Seelen, durch das Wasser Rettung finden sollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Das Gegenbild davon, die Taufe, rettet jetzt auch euch. Doch sie besteht nicht darin, daß man den Schmutz des Leibes ablegt, vielmehr erfleht sie von Gott ein gutes Gewissen durch die Auferstehung Jesu Christi,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'der, nachdem er in den Himmel aufgefahren war, zur Rechten Gottes ist nachdem er den Tod verschlungen hatte, damit wir Erben des ewigen Lebens würden, wo Engel und Gewalten und die Mächte ihm unterworfen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Da Christus also im Fleische gelitten hat, so wappnet auch ihr euch mit ähnlicher Gesinnung. Wer im Fleische gelitten hat, der ist von der Sünde frei');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'und bringt die Zeit, die ihm im Fleische noch verbleibt, nicht mehr im Dienste menschlicher Gelüste, vielmehr nach dem Willen Gottes zu.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Es genügt ja, daß wir in der vergangenen Lebenszeit der Sinnesrichtung der Heiden folgten und so dahinlebten in Ausschweifungen und Lüsten, in Trunkenheit und Schmausereien, in Gelagen und in frevelhaftem Götzendienst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Nun fällt es den Heiden auf, daß ihr nicht mehr mitmacht bei diesem wüsten, zügellosen Treiben; deswegen lästern sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Sie aber werden Rechenschaft dem geben müssen, der sich bereit hält, Lebende und Tote zu richten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Deswegen wurde auch den Toten das Evangelium verkündet, daß, wenn sie auch nach Menschenschicksal dem Leibe nach gerichtet sind, sie doch der Seele nach leben, wie Gott es will.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Das Ende aller Dinge ist nahe. So seid besonnen und seid nüchtern, damit ihr beten könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Vor allem aber heget eine starke Liebe zueinander; die Liebe bedeckt ja eine Menge Sünden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Seid gegenseitig gastfreundlich ohne Murren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Dient einander mit der Gnadengabe, wie sie ein jeder empfangen hat, als treue Sachwalter der mannigfachen Gnade Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Wer die Redegabe hat, der trage seine Worte als Worte Gottes vor; und wer ein Amt besitzt, verwalte es aus der Kraft, die Gott verleiht; damit in allem Gott verherrlicht werde durch Jesus Christus, dem Herrlichkeit und Macht gebührt von Ewigkeit zu Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Geliebte! Laßt euch nicht befremden durch die Feuerprobe, die ihr erduldet, als ob euch damit etwas Ungewöhnliches geschähe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Freut euch vielmehr im gleichen Maße, in dem ihr an den Leiden Christi Teil bekommt, damit, wenn seine Herrlichkeit sich offenbart, ihr dann auch mit Frohlocken jubeln könnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Wenn ihr um des Namens Christi willen Schmähungen erleidet, dann seid ihr selig. Dann ruht der Geist der Herrlichkeit, ja, Gottes Geist auf euch.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Doch keiner unter euch darf leiden, weil er ein Mörder, ein Dieb oder ein Verbrecher wäre, oder einer, dem es nach fremdem Gute gelüstet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Wer aber leiden muß als Christ, der braucht sich dessen nicht zu schämen; er preise vielmehr Gott ob dieses Namens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Jetzt ist die Zeit, da das Gericht beim Hause Gottes schon beginnt. Wenn nun zuerst bei uns, wie mag dann das Ende derer sein, die dem Evangelium Gottes nicht gehorchen?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Und wird schon der Gerechte kaum gerettet, wo werden der Frevler und der Sünder alsdann bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'So sollen die, die nach dem Willen Gottes leiden, ihre Seelen dem getreuen Schöpfer durch ein tugendhaftes Leben anbefehlen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Die Presbyter bei euch ermahne ich als Mitbruder und Zeuge der Leiden Christi wie auch als Erbe der Verherrlichung, die sich künftig offenbaren wird:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Weidet die Herde Gottes, die euch anvertraut ist, und traget für sie Sorge, nicht aus Zwang, sondern gerne, so wie Gott es will; und keinesfalls aus schändlicher Gewinnsucht, vielmehr mit Lust und Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Spielt nicht den Herrn in den Gemeinden, sondern seid ein Vorbild für die Herde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Erscheint alsdann der Oberhirte, so werdet ihr den unverwelklichen Kranz der Herrlichkeit empfangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'In gleicher Weise sollt auch ihr Jüngeren den Älteren euch unterordnen. Seid alle miteinander in Demut eng verbunden: \"Gott widersteht den Hochmütigen, den Demütigen aber gibt er Gnade.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'So beugt euch denn in Demut unter Gottes mächtige Hand, damit er euch zur rechten Zeit erhöhe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Werfet auf ihn alle eure Sorge: Ihr liegt ihm ja am Herzen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Seid nüchtern und wachsam. Der Teufel, euer Widersacher, geht umher wie ein brüllender Löwe und sucht, wen er verschlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Widersteht ihm fest im Glauben. Wißt, daß euren Brüdern in der Welt die gleichen Leiden widerfahren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Der Gott aller Gnade aber, der euch nach kurzem Leiden zu seiner ewigen Herrlichkeit in Christus Jesus berufen hat, wird euch vervollkommnen und stärken, bekräftigen und festigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Ihm gebührt Herrlichkeit und Macht von Ewigkeit zu Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Ich schreibe euch, wie ich glaube, in Kürze, durch Silvanus, den treuen Bruder. Ich wollte euch erinnern und zugleich bezeugen, daß dies die wahre Gnade Gottes ist, in der ihr lebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Es grüßt euch die mit euch erwählte Gemeinde in Babylon und Markus, mein Sohn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Grüßt einander mit dem Kusse der Liebe. - Euch allen, die ihr in Christus lebet, Frieden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Symeon Petrus, Knecht und Apostel Jesu Christi, an die, die einen mit dem unsrigen gleichartigen Glauben erlangt haben durch das gerechte Walten unseres Gottes und Heilandes Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Gnade werde euch zuteil und Friede in überreicher Fülle durch immer tiefere Erkenntnis Gottes und unseres Herrn Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Seine göttliche Macht hat uns all das geschenkt, was zu einem frommen Leben dient durch die Erkenntnis dessen, der uns vermöge seiner Herrlichkeit und Macht berufen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Die kostbarsten und größten der Verheißungen gab er deshalb, damit ihr durch sie göttlicher Natur teilhaftig würdet, wofern ihr der Verderbnis entrinnet, die aus der bösen Lust der Welt entspringt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Nur müßt ihr allen Eifer darauf verwenden und in eurem Glauben die Tugend schaffen, in der Tugend die Erkenntnis,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'in der Erkenntnis die Mäßigung, in der Mäßigung die Geduld, in der Geduld die Frömmigkeit,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'in der Frömmigkeit die Bruderliebe, in der Bruderliebe die Liebe überhaupt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Wenn diese Tugenden bei euch vorhanden sind und wenn sie sich noch mehren, so werden sie euch nicht ohne Früchte und Erfolge lassen in der Erkenntnis unseres Herrn Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Wem aber diese Tugenden fehlen, der ist blind und kurzsichtig und vergißt, daß er von seinen früheren Sünden gereinigt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'So seid denn, Brüder, nur um so mehr darauf bedacht, Beruf und Auserwählung euch zu sichern; denn wenn ihr so lebt, dann werdet ihr nie straucheln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Dann wird euch als überreiche Zugabe der Eingang in das ewige Reich unseres Herrn und Heilandes Jesu Christi beschieden sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Deshalb wird es allzeit mein Bestreben sein, euch an diese Dinge zu erinnern, obwohl ihr sie schon wißt und von dieser Wahrheit fest überzeugt seid.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ich halte es für meine Pflicht, solange ich noch in diesem Zelte lebe, durch solche Mahnungen euch wachzuhalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Ich weiß ja, daß mein Zelt rasch abgebrochen wird, wie es mir auch Jesus Christus, unser Herr, geoffenbart hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Darum liegt mir auch viel daran, daß ihr diese Lehren nach meinem Hingang euch ins Gedächtnis ruft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Denn nicht an gut erfundene Fabeln haben wir uns gehalten, als wir euch die Kunde brachten von der Kraft und Ankunft unseres Herrn Jesus Christus, sondern weil wir Augenzeugen seiner Majestät geworden waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Als er von Gott, dem Vater, Ehre und Herrlichkeit empfing und von der erhabenen Herrlichkeit an ihn die Stimme erging: \"Das ist mein vielgeliebter Sohn, an dem ich mein Wohlgefallen habe\",');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'da hörten auch wir diese Stimme vom Himmel her, die wir uns mit ihm auf dem heiligen Berge befanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Wir halten so die Worte der Propheten für um so zuverlässiger. Auch ihr tut gut, wenn ihr euch daran haltet, als einer Leuchte, die am dunklen Orte scheint, bis der Tag anbricht und der Morgenstern in euren Herzen aufleuchtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Doch das erkennt vor allem, daß keine Weissagung der Schrift nach Gutdünken ausgelegt werden darf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'denn nie erging eine Weissagung durch eines Menschen Willen, vielmehr vom Heiligen Geiste geleitet, redeten heilige Gottesmänner.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Es traten aber im Volk auch falsche Propheten auf, und so werden auch unter euch falsche Lehrer kommen, die verderbliche Irrlehren mit sich bringen. Sie verleugnen den Herrn, der sie erkauft hat, und bereiten sich ein jähes Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Viele werden ihrer Ausschweifung nachfolgen; um ihretwillen wird der Weg der Wahrheit gelästert werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'In ihrer Habsucht werden sie mit ihren trügerischen Reden euch ausbeuten. Doch das Gericht, das über sie schon ausgesprochen ist, und ihr Verderben schlummern nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Gott schonte nicht einmal die sündigen Engel. Er stürzte sie vielmehr hinab ins finstere Verlies der Hölle, wo sie für das Gericht aufgehoben sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Er schonte nicht der alten Welt; er rettete nur Noe, den Verkünder der Gerechtigkeit, dazu noch sieben andere, als er die Sintflut auf die Welt der Frevler sich ergießen ließ.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'So hat er auch die Städte Sodoma und Gomorrha zum Untergang durchs Feuer verdammt, als warnendes Beispiel für die künftigen Frevler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Er rettete nur den gerechten Lot, der unter dem unzüchtigen Lebenswandel jener Frevler arg zu leiden hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Durch alles, was er sah und hörte, ward der Gerechte, solange er unter ihnen wohnte, an seiner gerechten Seele durch ihre frevelhaften Werke Tag für Tag gequält.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'So weiß der Herr, die Frommen aus der Prüfung zu erretten, die Frevler aber für den Gerichtstag unter Züchtigungen aufzubewahren;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'besonders solche, die dem Fleische mit schmutzigem Gelüste folgen und die Majestät des Herrn verachten. In ihrer Frechheit und Verwegenheit scheuen sie sich nicht, die Herrlichkeiten selbst zu lästern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'wo Engel, an Kraft und Stärke ihnen überlegen, doch vor dem Herrn ein Fluchurteil nicht gegen diese fällen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Sie aber, unvernünftigen Tieren gleich, die von Natur aus zum Fang und Tod geboren sind, lästern, was sie nicht verstehen, und werden im Verderben jener zugrunde gehen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'betrogen durch den Lohn ihrer Ungerechtigkeit. Alltägliche Genüsse halten sie für Wonne, sie schlemmen ganz betört als Schmutz- und Schandflecken, wenn sie mit euch zusammen speisen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Ihre Augen sind voll Ehebrechereien und unersättlich im Sündigen. Sie locken haltlose Seelen an sich; bewandert sind sie in der Habsucht, sie, des Fluches Kinder.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Sie haben den geraden Weg verlassen und sich verlaufen, indem sie den Spuren Balaams, des Bosor Sohnes, folgen. Dieser liebte ungerechten Lohn,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'doch er empfing für seine Widersetzlichkeit Zurechtweisung: Ein stummes Lasttier redete mit Menschenstimme und wehrte so dem Unverstande des Propheten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Sie sind Quellen ohne Wasser, vom Sturme gejagte Nebelwolken; das Grauen der Finsternis ist ihnen aufbewahrt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Sie locken mit überschwenglichen, doch inhaltsleeren Worten, durch fleischliche Genüsse und durch Ausschweifung jene an sich, die denen kaum entronnen sind, die im Irrtum dahinleben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Sie verheißen ihnen Freiheit und sind doch selber Sklaven des Verderbens. Denn von wem einer überwältigt wird, dessen Sklave ist er.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Wenn solche, die der Befleckung durch die Welt entronnen sind in der Erkenntnis unseres Herrn und Heilandes Jesus Christus, sich wiederum von ihr verführen und bezwingen lassen, dann werden bei ihnen die letzten Dinge ärger sein als die ersten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Denn es wäre besser für sie, sie hätten nie den Weg zur Gerechtigkeit kennengelernt, als daß sie ihn erkannten und dann wiederum sich abwandten vom heiligen, ihnen übergebenen Gebote.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Auf solche trifft das wahre Sprichwort zu: \"Ein Hund, der zum eigenen Gespei sich wendet\", und:\"Ein Schwein, das sich nach der Schwemme wieder im Schmutze wälzt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Das ist nun schon der zweite Brief, Geliebte, den ich an euch schreibe. Ich will in ihnen eure lautere Gesinnung wachhalten durch Ermahnungen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'auf daß ihr der Worte eingedenk seid, die einst die heiligen Propheten schon vorhergesagt, und des Gebotes unseres Herrn und Heilands, das die Apostel euch verkündigt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Vor allen Dingen müßt ihr wissen, daß am Ende der Tage Spötter voll Hohn auftreten, Menschen, die ihren eigenen Lüsten folgen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'und sagen: \"Wo bleibt denn seine Ankunft, die er verheißen hat? Schon seit die Väter entschlafen sind, bleibt alles so, wie es vom Anfang der Welt an war.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Sie übersehen ja absichtlich, daß zwar von Urzeit an der Himmel war und daß die Erde aus dem Wasser und durch das Wasser kraft des Gotteswortes zustande kam');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'und daß, durch beide vom Wasser überflutet, die alte Welt zugrunde ging.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Der jetzige Himmel und die jetzige Erde sind durch das gleiche Wort nun aber aufgespart und aufbewahrt fürs Feuer an dem Tag, an dem die frevlerischen Menschen gerichtet und verdammt werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Dies eine aber, Geliebte, dürft ihr ja nicht übersehen: Ein Tag ist bei dem Herrn wie tausend Jahre, und tausend Jahre sind wie ein Tag.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Der Herr säumt nicht mit der Erfüllung der Verheißung, wie das manche für ein Säumen halten. Er übt an euch nur Langmut; er will ja nicht, daß auch nur einige verlorengehen, vielmehr, daß alle sich zur Buße wenden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Jedoch, es kommt der Tag des Herrn wie ein Dieb. Die Himmel werden in gewaltigem Sausen vergehen, die Elemente werden sich in Gluthitze auflösen, die Erde aber und was sich darauf befindet, wird verbrennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Da sich nun alles so auflöst, wie sehr müßt dann ihr einen heiligen und frommen Wandel führen');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'und so den Tag der Ankunft unseres Gottes erwarten und beschleunigen. Der Himmel löst sich dann in Feuer auf; die Elemente schmelzen in der Gluthitze dahin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Wir aber erwarten, wie er es verheißen hat, einen neuen Himmel und eine neue Erde, wo die Gerechtigkeit wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Deshalb, Geliebte, während ihr solches erwartet, zeigt allen Eifer, daß ihr im Frieden, unbefleckt und tadellos vor ihm befunden werdet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Benützt die Langmut unseres Herrn zu eurem Heil. So hat auch unser lieber Bruder Paulus in der ihm verliehenen Weisheit euch geschrieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Er tut es in allen seinen Briefen, wo er darauf zu sprechen kommt. Gar manches ist darin nun freilich schwierig zu verstehen, was Ungebildete und solche, die noch nicht gefestigt sind - wie übrigens auch die anderen Schriften - zu ihrem eigenen Verderben verdrehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ihr aber, Geliebte, die ihr jetzt dies wißt, nehmt euch in acht, daß ihr, vom Irrtum der Frevler fortgerissen, nicht euren festen Halt verlieret.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Wachset in der Gnade und Erkenntnis unseres Herrn und Heilandes Jesus Christus. Ihm sei die Herrlichkeit jetzt und am Tage der Ewigkeit. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Was von Anfang an gewesen, was wir gehört, was wir mit eigenen Augen gesehen, was wir geschaut und unsere Hände berührt haben, das künden wir vom Wort des Lebens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Erschienen ist das Leben- wir haben gesehen und bezeugen und verkünden euch das ewige Leben, das beim Vater war und uns erschienen ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Also was wir gesehen und gehört haben, verkünden wir auch euch, damit auch ihr mit uns Gemeinschaft habt. Unsere Gemeinschaft haben wir mit dem Vater und mit seinem Sohne Jesus Christus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Wir schreiben dies, auf daß ihr euch freut und wir volle Freude hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Das ist die Botschaft, die wir von ihm vernommen haben und die wir euch verkünden: Gott ist Licht. In ihm gibt es keine Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Doch wollten wir behaupten, daß wir mit ihm Gemeinschaft hätten, und wollten doch dabei im Finstern wandeln, dann lügen wir und tun nicht die Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Doch wandeln wir im Lichte, wie auch er im Lichte ist, dann leben wir in Gemeinschaft miteinander, und das Blut Jesu, seines Sohnes, macht uns von aller Sünde rein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Wenn wir aber sagten, wir hätten keine Sünde, dann betrügen wir uns selbst, und die Wahrheit wohnt nicht in uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Bekennen wir jedoch unsere Sünden, dann ist er treu und rechtlich, so daß er uns unsere Sünden nachläßt und uns von allem Unrecht reinigt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Würden wir aber sagen, wir hätten nicht gesündigt, dann würden wir ihn dadurch zum Lügner stempeln, und sein Wort wäre nicht in uns.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meine Kinder, dies schreibe ich euch, damit ihr nicht sündigt. Und wenn einer trotzdem gesündigt hätte, dann ist uns Jesus Christus, der Gerechte, Fürsprecher beim Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Er ist die Sühne für unsere Sünden, und nicht nur für die unsrigen allein, nein, auch für die ganze Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Das ist ja der Beweis, daß wir ihn erkannt haben, wenn wir seine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Wer sagt: \"Ich kenne ihn\", doch seine Gebote nicht hält, der ist ein Lügner; in einem solchen ist die Wahrheit nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Doch wer sein Wort hält, in dem ist wahrhaft Gottes Liebe vollendet; dies ist auch das Zeichen, daß wir in ihm sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Wer sagt: \"Ich bleibe in ihm\", dem ist es heilige Pflicht, gerade so zu wandeln, wie auch er gewandelt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Geliebteste! Kein neues Gebot ist es, was ich euch schreibe, sondern ein altes, und ihr hattet es von Anfang an: Das Wort, das ihr vernommen habt, ist dieses alte Gebot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Und doch ist es auch ein neues Gebot, was ich euch schreibe, wahr in ihm und in euch: Die Finsternis geht vorüber; es leuchtet schon das wahre Licht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Wer sagt, er sei im Lichte, doch seinen Bruder haßt, der ist noch immer in der Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Wer aber seinen Bruder liebt, der bleibt im Licht ohne Anstoß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Jedoch, wer seinen Bruder haßt, der ist noch immer in der Finsternis; er wandelt in der Finsternis und weiß nicht, wohin er geht; denn die Finsternis hat ihm die Augen verdunkelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ich schreibe euch, ihr Kinder: Euch sind die Sünden nachgelassen um seines Namens willen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ich schreibe euch, ihr Väter: Ihr habt ja den erkannt, der von Anfang ist. Ich schreibe euch, ihr Jünglinge: Ihr habt den Bösen überwunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ich habe euch geschrieben, ihr Kinder; denn ihr versteht den Vater. Ich habe euch geschrieben, ihr Väter; denn ihr habt den erkannt, der von Anfang ist. Ich habe euch geschrieben, ihr Jünglinge; denn ihr seid stark, und Gottes Wort wohnt in euch; ihr habt den Bösen überwunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Liebt nicht die Welt, noch was sich in der Welt befindet. Wenn jemand die Welt liebt, ist die Liebe des Vaters nicht in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Denn alles, was in der Welt sich findet: Lust des Fleisches, Lust der Augen, Hoffart des Lebens, kommt nicht vom Vater her, vielmehr kommt es von der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Allein, die Welt vergeht samt ihrer Lust; wer aber den Willen Gottes tut, bleibt in Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Kinder, es ist die letzte Stunde: Ihr habt gehört: Es kommt der Antichrist. Jetzt sind schon viele Antichristi aufgestanden. Daran mögen wir erkennen, daß es letzte Stunde ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Aus unseren Reihen sind sie ausgegangen; doch sie gehörten nicht zu uns. Denn hätten sie zu uns gehört, so wären sie bei uns geblieben. Allein, es sollte an ihnen sich klar zeigen, daß nicht alle zu uns gehören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ihr aber habt die Salbung von dem Heiligen, und ihr alle wisset es.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Ich schreibe euch nicht deshalb, weil ihr die Wahrheit nicht erkennet, sondern weil ihr sie kennet und wisset, daß aus der Wahrheit niemals Lüge kommt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Wer anders aber ist der Lügner, wenn nicht der, der leugnet, daß Jesus der Christus ist? Das ist der Antichrist, der den Vater samt dem Sohne leugnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Denn wer den Sohn leugnet, der hat auch nicht den Vater. Nur wer den Sohn bekennt, hat auch den Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Was ihr von Anfang an vernommen habt, das soll in euch bleiben. Wenn in euch bleibt, was ihr von Anfang an vernommen habt, dann bleibt auch ihr im Sohn und im Vater.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'So heißt ja die Verheißung, die er selber uns gegeben hat: das ewige Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Soviel wollte ich euch über jene schreiben, die euch zu verführen suchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'In euch hingegen bleibt die Stellung, die ihr von ihm empfangen habt; ihr habt nicht nötig, daß euch jemand belehre. Also, wie seine Salbung euch über alles aufgeklärt hat, so ist es wahr, und keine Lüge gibt es. Bleibt so in ihm, wie er es euch gelehrt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Und jetzt, o Kinder, bleibt in ihm! Damit wir, wenn er erscheint, von froher Zuversicht erfüllt sind und bei seiner Ankunft nicht mit Beschämung von ihm zu weichen brauchen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ihr wißt, daß er gerecht ist, so wisset ihr auch, daß jeder, der Gerechtigkeit tut, aus ihm geboren ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Seht, welch große Liebe uns der Vater erwiesen hat: Wir heißen Kinder Gottes und sind es in der Tat. Darum versteht die Welt uns nicht, weil sie ihn nicht verstanden hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Geliebteste, jetzt sind wir Kinder Gottes, doch ist es noch nicht offenbar, was wir einst sein werden. Wir wissen aber, wenn er erscheint, werden wir ihm gleich sein, weil wir ihn schauen, wie er ist. -');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Jeder, der solche Hoffnung auf ihn hegt, der heiligt sich, so wie auch jener heilig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Jeder, der die Sünde tut, begeht damit auch die Gesetzlosigkeit; die Sünde selber ist die Gesetzlosigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Nun wisset ihr, daß jener erschienen ist, die Sünden wegzunehmen, und daß keine Sünde in ihm ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Jeder, der in ihm bleibt, ist sündenfrei. Doch wer sündigt, hat ihn nicht gesehen noch verstanden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kinder! Niemand möge euch verführen. Wer die Gerechtigkeit tut, ist gerecht, wie er gerecht ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Doch wer die Sünde tut, stammt aus dem Teufel; denn der Teufel sündigt von Anfang an. Dazu ist der Sohn Gottes erschienen, die Werke des Teufels zu zerstören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Jeder, der aus Gott geboren ist, sündigt nicht; sein Lebenskeim bleibt ja in ihm. Er kann auch gar nicht sündigen, weil er aus Gott geboren ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Die Kinder Gottes und des Teufels sind daran zu erkennen: Wer nicht Gerechtigkeit übt, ist nicht aus Gott, noch auch, wer seinen Bruder nicht liebt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Denn diese Botschaft habt ihr von Anfang an vernommen: daß wir einander lieben sollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nicht so, wie Kain gehandelt hat, der vom Bösen kam und seinen Bruder mordete. Warum hat er ihn gemordet? Seine Werke waren eben böse, die seines Bruders recht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ihr braucht euch nicht zu wundern, Brüder, wenn die Welt euch haßt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Wir wissen, daß wir aus dem Tode zum Leben gekommen sind, weil wir die Brüder lieben. Wer nicht liebt, bleibt im Tode.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Jeder, der seinen Bruder haßt, ist ein Menschenmörder. Ihr wisset auch: In keines Mörders Innern bleibt das ewige Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Daran erkennen wir die Liebe, daß jener sein Leben für uns hingegeben hat. So sind auch wir verpflichtet, das Leben für die Brüder hinzugeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Wenn einer Güter dieser Welt besitzt und seinen Bruder in bitterer Not sieht und doch sein Herz vor ihm verschließt, wie kann in einem solchen noch die Liebe Gottes bleiben?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'O Kinder, nicht in Worten laßt uns lieben, nicht mit der Zunge nur, sondern in Tat und Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Daraus werden wir ersehen, daß wir aus der Wahrheit sind, und werden unser Herz vor ihm beruhigen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Denn mag auch unser Herz uns verdammen, noch größer als unser Herz ist Gott; er weiß ja alles.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Geliebteste, wenn unser Herz uns nicht verdammt, alsdann beseelt uns frohe Zuversicht auf Gott,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'und alles, was wir von ihm erbitten, werden wir empfangen, weil wir seine Gebote bewahren und tun, was vor ihm wohlgefällig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Und dies ist sein Gebot: Wir müssen an den Namen seines Sohnes Jesus Christus glauben und einander lieben, wie er es uns geboten hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Wer seine Gebote hält, der bleibt in ihm und er in diesem. Daß er in uns verbleibt, das erkennen wir aus dem Geiste, den er uns gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Geliebte! Trauet nicht jedem Geiste! Prüft die Geister, ob sie aus Gott sind. Denn viele falsche Propheten sind in die Welt hinausgegangen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Daran erkennt man den Geist aus Gott: jeder Geist, der bekennt: Jesus Christus ist im Fleische gekommen, ist aus Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Doch jeder Geist, der Jesus nicht bekennt, ist auch nicht aus Gott. Es ist vielmehr der Geist des Antichristen, von dem ihr vernommen habt, daß er kommt; ja, er ist schon in der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Doch ihr, o Kinder, seid aus Gott, ihr habt jene überwunden; denn er, der in euch ist, ist stärker als jener in der Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Sie sind von der Welt; deshalb reden sie nach Art der Welt; es hört auch die Welt auf sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Wir aber sind aus Gott. Wer Gott erkennt, der hört auf uns; nur wer nicht aus Gott ist, der hört auch nicht auf uns. Daran erkennen wir den Geist der Wahrheit und den Geist der Verwirrung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Geliebte! Lasset uns einander lieben! Die Liebe stammt aus Gott, und jeder, der liebt, ist aus Gott geboren und versteht Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Doch wer nicht liebt, hat Gott nicht verstanden: Gott ist Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Dadurch hat sich die Liebe Gottes unter uns geoffenbart, daß Gott seinen Eingeborenen Sohn in diese Welt gesandt hat, damit wir durch ihn leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Und darin eben liegt die Liebe, nicht, daß wir Gott geliebt haben, sondern daß er uns geliebt und daß er seinen Sohn als Sühne für unsere Sünden gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Geliebte! Wenn uns Gott so sehr geliebt hat, dann sind auch wir verpflichtet, einander zu lieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Noch nie hat jemand Gott geschaut, doch wenn wir einander lieben, dann bleibt Gott in uns, und seine Liebe ist in uns vollendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Daran mögen wir erkennen, daß wir in ihm bleiben und er in uns verbleibt, daß er von seinem Geist uns gegeben hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Wir haben es gesehen und bezeugen es, daß der Vater seinen Sohn als Weltheiland gesandt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Wer nun bekennt: Jesus ist der Sohn Gottes, in dem bleibt Gott und er in Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Und wir haben erkannt und der Liebe geglaubt, die Gott zu uns hat. Gott ist Liebe. Wer in der Liebe bleibt, der bleibt in Gott, und Gott bleibt in ihm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Darin vollendet sich bei uns die Liebe, daß wir voll Zuversicht für den Tag des Gerichtes verblieben; denn so wie jener sind auch wir in dieser Welt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Furcht gibt es bei der Liebe nicht; denn ist die Liebe ganz vollendet, dann wird die Furcht verdrängt. Die Furcht hat Strafe in sich, und darum, ist, wer fürchtet, in der Liebe noch nicht vollendet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Wir lieben, weil er uns zuvor geliebt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Wenn einer sagt: \"Ich liebe Gott\", doch seinen Bruder haßt, der ist ein Lügner. Wenn einer nämlich seinen Bruder, den er sieht, nicht liebt, der kann auch Gott nicht lieben, den er nicht gesehen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Dieses Gebot haben wir von ihm: Wer Gott liebt, muß auch seinen Bruder lieben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Jeder, der glaubt, daß Jesus der Christus ist, ist aus Gott geboren. Jeder der den Vater liebt, liebt auch dessen Kind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Daran erkennen wir, daß wir die Kinder Gottes lieben, wenn wir Gott selber lieben und seine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Denn das ist Liebe zu Gott, daß wir seine Gebote halten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Seine Gebote sind nicht schwer. Denn alles, was aus Gott geboren ist, hat die Welt überwunden, und unser Glaube ist der Sieg, der die Welt bezwungen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Wer ist es denn, der die Welt besiegt, wenn nicht der, der glaubt, daß Jesus der Sohn Gottes ist?');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Er ist es, der gekommen ist durch Wasser, Blut und Geist: Jesus Christus. Nicht allein durch Wasser, sondern durch Wasser und durch Blut. Der Geist ist es, der es bezeugt; der Geist ist Wahrheit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'So sind es denn drei, die Zeugnis geben: im Himmel: der Vater, das Wort und der Heilige Geist, und diese drei sind Eins. Und drei sind es, die Zeugnis geben auf Erden:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Der Geist, das Wasser und das Blut, und diese drei stimmen überein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Wenn wir dem Zeugnis der Menschen glauben, so steht doch das Zeugnis Gottes höher; denn dies ist das Zeugnis Gottes das höher steht, daß er von seinem Sohne Zeugnis abgelegt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Wer immer an den Sohn Gottes glaubt, der hat das Zeugnis in sich. Wer aber Gott nicht glaubt, macht ihn zum Lügner; er glaubt ja nicht all das Zeugnis, das Gott von seinem Sohn abgelegt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Und dieses Zeugnis lautet: Gott hat uns ewiges Leben gegeben, und dieses Leben ist in seinem Sohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wer den Sohn hat, hat das Leben, wer aber den Sohn Gottes nicht hat, hat auch das Leben nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Dies schreibe ich euch, damit ihr wisset, daß ihr das ewige Leben habt, die ihr an den Namen des Sohnes Gottes glaubt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Und das ist unsere Zuversicht, die wir zu ihm besitzen, daß er uns hört, wenn wir nach seinem Willen um irgend etwas bitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Und wenn wir wissen, daß er uns hört, um was wir immer bitten, so wissen wir auch, daß wir das schon besitzen, was wir mit unseren Bitten erst von ihm erflehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Wenn einer sieht, wie sein Bruder eine Sünde tut, die nicht zum Tode führt, der möge beten und dadurch ihm zum Leben verhelfen, wofern er nicht zum Tode gesündigt hat. Es gibt auch eine Sünde, die zum Tode führt; doch nicht für diese, sage ich, soll man beten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Jede Ungerechtigkeit ist Sünde. Es gibt indes auch eine Sünde, die nicht zum Tode führt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wir wissen: Wer aus Gott geboren ist, der sündigt nicht; sondern wer aus Gott geboren ist, der hütet sich, und auch der Böse tastet ihn nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wir wissen, daß wir aus Gott stammen und daß die ganze Welt in der Gewalt des Bösen liegt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Wir wissen aber auch, daß der Sohn Gottes gekommen ist und daß er uns die Einsicht gegeben hat, daß wir den Wahrhaftigen erkennen. Wir sind in dem Wahrhaftigen, in seinem Sohne Jesus Christus. Dies ist der wahre Gott und ewiges Leben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kinder, hütet euch vor den Götzen!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Der Presbyter an die erwählte Herrin und an ihre Kinder, die ich in der Wahrheit liebe, und nicht nur ich allein, sondern alle, die die Wahrheit erkannt haben,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'gerade um der Wahrheit willen, die in uns bleibt und ewig bei uns bleiben wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Gnade, Erbarmen und Friede möge uns verbleiben von Gott, dem Vater, und von dem Sohne des Vaters, Jesus Christus, in Wahrheit und Liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Ich habe mich gar sehr gefreut, daß ich unter deinen Kindern solche gefunden habe, die in der Wahrheit wandeln, wie es der Vater uns geboten hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Nun bitte ich dich, Herrin - nicht als wollte ich dir ein neues Gebot schreiben; es ist dasselbe, das wir von Anfang gehabt haben: Laßt uns einander lieben!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Das aber ist die Liebe, daß wir nach seinen Geboten wandeln. Dies ist das Gebot, das ihr von Anfang an gehört habt, damit ihr darin wandelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Denn viele Verführer sind in die Welt gezogen, die leugnen, Jesus Christus sei im Fleisch erschienen. Nur ein Verführer redet so, der Antichrist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Sehet euch doch vor, auf daß ihr nicht verliert, was ihr erarbeitet habt, sondern damit ihr vollen Lohn erhaltet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Denn jeder, der weitergeht und nicht bei der Lehre Christi bleibt, hat Gott nicht. Nur wer bei der Lehre bleibt, hat den Vater samt dem Sohne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Wenn einer zu euch kommt, ohne diese Lehre mitzubringen, den nehmt nicht in euer Haus auf und bietet ihm auch nicht den Gruß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Denn wer ihn auch nur grüßt, nimmt teil an seinen schlechten Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Noch vieles hätte ich euch zu schreiben, doch ich wollte es nicht mit Papier und Tinte tun. Ich hoffe ja, zu euch zu kommen und dann von Mund zu Mund zu reden, damit wir volle Freude hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Die Kinder deiner auserwählten Schwester grüßen dich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Der Presbyter an den geliebten Gajus, den ich in Wahrheit liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Geliebtester! Ich wünsche, daß es dir in allem wohlergehe und daß du dich gesund befinden mögest, so wie es deiner Seele wirklich wohl ergeht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Ich habe mich gar sehr gefreut, als Brüder kamen und deine Treue rühmten, mit der du in der Wahrheit wandelst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Ich kenne keine größere Freude, als zu hören, daß meine Kinder in der Wahrheit wandeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Geliebtester! Getreu in allem handelst du, was immer du an den Brüdern tust, und dies an fremden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Sie rühmen dich ob solcher Liebe laut vor der Gemeinde, und trefflich handelst du, wenn du sie weiter förderst, so wie es Gottes würdig ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Sie sind ja um des Namens willen ausgezogen und haben nichts von den Heiden angenommen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'So ist es denn nur unsere Pflicht, uns solcher Männer anzunehmen; wir werden dadurch ihre Mitarbeiter für die Wahrheit sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ich habe auch etwas an die Gemeinde selbst geschrieben; allein Diotrephes, der gern den Ersten unter ihnen spielt, erkennt uns nicht an.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Darum will ich, wenn ich komme, sein Treiben zur Sprache bringen, wie er mit bösen Worten uns verdächtigt und, damit nicht zufrieden, die Brüder selbst nicht aufnimmt und denen, die sie gastfrei halten, wehrt, ja, sie sogar aus der Gemeinde ausschließt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Geliebtester! Ahme nicht das Böse nach, vielmehr das Gute! Wer Gutes tut, ist aus Gott; wer aber Böses tut, hat Gott nicht gesehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Von allen erhält Demetrius ein gutes Zeugnis, auch von der Wahrheit selber. Auch wir bezeugen so, und unser Zeugnis ist, du weißt es, wahr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Noch vieles hätte ich dir zu schreiben; doch wollte ich es nicht mit Tinte und Feder tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Ich hoffe nämlich, dich bald zu sehen; dann werden wir uns mündlich sprechen. Friede sei mit dir! Die Freunde grüßen dich. Grüße auch du die Freunde, einen jeden einzeln!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, Knecht Jesu Christi und Bruder des Jakobus, an die Berufenen, die in Gott, dem Vater, geliebt und für Jesus Christus bewahrt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Erbarmen werde euch zuteil und Friede und Liebe in allerreichster Fülle.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Geliebteste! Es war mir eine Herzenssache, an euch einmal zu schreiben über unser gemeinsames Heil. Nun aber sehe ich mich geradezu genötigt, mit einem Brief euch zu mahnen, ihr möchtet für den Glauben kämpfen, der ein für allemal den Heiligen anvertraut ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Denn es haben sich gewisse Menschen eingeschlichen, die längst für dieses Strafgericht vorherbestimmt sind: Frevler, die die Gnade unseres Gottes in Schwelgerei verkehren und unseren einzigen Gebieter und Herrn, Jesus Christus, leugnen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ich möchte euch, obwohl ihr alles durchaus wißt, trotzdem an folgendes erinnern: Der Herr hat zwar das Volk aus dem Land Ägypten errettet und doch hernach die Ungläubigen vernichtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Auch die Engel, die ihre Herrschaft nicht bewahrten, ja, ihre Wohnungen verließen, hat er bis zum Gerichte des großen Tages aufgehoben mit ewigen Fesseln in der Finsternis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'So stehen auch Sodoma und Gomorrha und die Städte um sie her, die wie jene Unzucht trieben und der unnatürlichen Wollust nachgingen, als warnendes Beispiel da in ihrer ewigen Feuerstrafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'In gleicher Weise beflecken auch diese das Fleisch mit ihren Träumen, verachten die Majestät des Herrn und lästern Herrlichkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Selbst Michael, der Erzengel, hat es nicht gewagt, ein Fluchurteil zu sprechen, als er mit dein Teufel aber Mosis Leichnam stritt und rechtete. Er sagte nur: \"Es strafe dich der Herr!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Doch jene lästern alles, was sie nicht verstehen. Doch was sie von Natur aus, unvernünftigen Tieren gleich, schon wissen, wird ihnen zum Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Wehe ihnen; sie wandeln auf dem Wege des Kain; sie geben sich Balaams Verführung aus Gewinnsucht hin, sie kommen, einem Kore gleich, in der Empörung um.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Sie sind die Schandflecken bei euren Liebesmahlen, die sie, allen Schamgefühls bar, mit euch halten. Sie weiden sich selbst: Wolken ohne Regen, vom Wind vorbeigejagt; Bäume im Spätherbst, unfruchtbar, zweimal tot, entwurzelt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'wilde Meereswogen, die ihren eigenen Unrat ausschäumen; Irrsterne, denen auf ewig das Grauen der Finsternis aufbewahrt ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Schon Henoch, der siebte nach Adam, hat über sie vorhergesagt: \"Siehe, es kommt der Herr mit seinen heiligen Zehntausenden,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'um über alle Gericht zu halten und all die Frevler heimzusuchen all ihrer frevelhaften Werke wegen, die sie verübt, und all ihrer bösen Reden wegen, die gottlose Sünder wider ihn geführt haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Sie sind unzufriedene Nörgler, die nach ihren Lüsten wandeln und deren Mund freche Rede führt; jedoch, wo es ihr Vorteil ist, ins Angesicht hinein auch freundlich tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ihr aber, o Geliebteste, gedenkt der Worte, die die Apostel unseres Herrn Jesus Christus euch vorhergesagt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Sie haben euch gesagt: \"In den letzten Zeiten werden Spötter kommen, die nach ihren eigenen, frevelhaften Lüsten wandeln.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Gemeint sind jene, die Spaltungen bilden, Menschen, durchaus sinnlich, ohne Geist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Doch ihr, Geliebteste, baut euch auf auf eurem hochheiligen Glauben! Im Heiligen Geiste sollt ihr beten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'daß ihr euch bewahrt in der Liebe Gottes. Und so erwartet das Erbarmen unseres Herrn Jesus Christus zum Leben in der Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Weist die zurecht, die zweifeln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Die anderen rettet; reißt sie aus dem Feuer. Erbarmt euch der dritten in Furcht, voll Ekel vor ihrem vom Fleische bedeckten Kleide.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Ihm aber, der Macht hat, euch vor dem Straucheln zu bewahren, euch bei der Ankunft unseres Jesus Christus unbefleckt, voll Jubel vor seine Herrlichkeit zu stellen,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'dem alleinigen Gott, unserem Heiland, gebührt durch Jesus Christus, unseren Herrn, Herrlichkeit und Majestät, Macht und Herrschaft, wie es war vor aller Zeit, so jetzt und bis in alle Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Offenbarung Jesu Christi, die Gott ihm gegeben hat, um seinen Knechten kundzutun, was bald geschehen muß. Er tat es durch seinen Engel, den er gesandt hat, Johannes, seinem Knechte, kund.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Dieser hat Zeugnis abgelegt vom Worte Gottes, und das Bekenntnis über Jesus Christus, über alles, was er geschaut hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Selig, wer die Worte der Prophezeiung liest und die sie hören, und was darin geschrieben steht, bewahren; die Zeit ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes an die sieben asiatischen Gemeinden. Gnade werde euch zuteil und Friede von dem, der ist und war und kommen wird, und von den sieben Geistern, die vor seinem Throne sind,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'und von Jesus Christus, dem getreuen Zeugen, dem Erstgeborenen der Toten, dem Herrscher über die Könige der Erde. Von ihm, der uns liebt, der uns erlöst hat von unseren Sünden in seinem Blute,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'der uns zu einem Königtum gemacht hat, zu Priestern für Gott und seinen Vater: Ihm gebührt die Herrlichkeit und Macht bis in die Ewigkeit der Ewigkeiten. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Sieh, er kommt auf den Wolken. Jedes Auge wird ihn schauen, auch die, die ihn durchbohrt haben. Dann werden alle Stämme auf der Erde wehklagen über ihn. Ja. Amen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '\"Ich bin das Alpha und das Omega\" der Anfang und das Ende, spricht Gott, der Herr, der ist und war und kommen wird, der Allbeherrscher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ich, Johannes, euer Bruder und Gefährte in der Trübsal, im Reiche Gottes und in der geduldigen Erwartung in Jesus, ich war auf der Insel Patmos wegen des Wortes Gottes und des Zeugnisses für Jesus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Ich ward am Tage des Herrn verzückt: Ich hörte hinter mir eine laute Stimme, es war wie ein Posaunenstoß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Sie rief: \"Was du da siehst, das schreibe dir auf eine Rolle und sende es an die sieben Gemeinden; nach Ephesus, Smyrna, Pergamum, Thyatira, Sardes, Philadelphia und Laodizea.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Da wandte ich mich um, um nach der Stimme zu schauen, die mit mir redete. Und als ich mich umwandte, sah ich sieben goldene Leuchter;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'inmitten dieser Leuchter einen, der einem Menschensohne glich. Er trug ein wallendes Gewand, und über seiner Brust war er gegürtet mit einem goldenen Gürtel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sein Haupt und seine Haare waren weiß wie weiße Wolle, weiß wie Schnee, und seine Augen wie ein loderndes Feuer,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'und seine Füße wie Golderz, wie geglüht in Feuersglut, und seine Stimme glich dem Rauschen vieler Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'In seiner Rechten hält er sieben Sterne; aus seinem Munde gebt ein Schwert hervor, zweischneidig und geschärft. Sein Antlitz ist, wie wenn die Sonne scheint in ihrer vollen Kraft.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Als ich ihn sah, fiel ich wie tot zu seinen Füßen nieder. Doch er legte seine Rechte auf mich: \"Hab keine Furcht\", sprach er, \"ich bin der Erste und der Letzte');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'und der Lebendige. Ich war tot, und sieh, ich lebe bis in die Ewigkeit der Ewigkeiten; ich habe die Schlüssel des Todes und der Unterwelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Schreibe nun, was du gesehen hast, was ist und was hernach geschehen wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Das Geheimnis der sieben Sterne, die du in meiner Rechten sahst, und die sieben goldenen Leuchter: Die sieben Sterne sind die Engel der sieben Gemeinden; die sieben Leuchter sind die sieben Gemeinden selbst.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Dem Engel der Gemeinde in Ephesus schreibe: \"So spricht, der die sieben Sterne in seiner Rechten hält, der inmitten der sieben goldenen Leuchter wandelt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Ich kenne deine Werke, deine Arbeit, dein Geduldigsein und weiß, daß du die Schlechten nicht ertragen kannst und daß du jene, die sich, ohne es zu sein, Apostel nennen, erprobt und als Lügner erfunden hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Du hast auch Geduld und hast um meines Namens willen gelitten und bist nicht müde geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Doch dies habe ich an dir auszusetzen: Du hast deinen ersten Liebeseifer aufgegeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Bedenke also, von welcher Höhe du herabgesunken bist. Bekehre dich und tue deine ersten Werke wieder! Sonst komme ich über dich und rücke deinen Leuchter von seiner Stelle, wenn du dich nicht bekehrst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Doch das hast du; du hassest das Treiben der Nikolaiten so, wie auch ich es hasse.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht: \"Dem Sieger gebe ich zu essen von dem Baume des Lebens, der im Paradiese Gottes steht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Dem Engel der Gemeinde in Smyrna schreibe: \"So spricht der Erste und der Letzte, der tot war und lebendig wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Ich kenne deine Trübsal und deine Armut; doch du bist reich. Ich weiß gar wohl, wie du von denen gelästert wirst, die sich Juden nennen und es nicht sind, sondern die Synagoge des Satans.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Hab keine Furcht vor dem, was du noch leiden mußt. Siehe, der Teufel wird manche unter euch ins Gefängnis bringen, damit ihr geprüft werdet; ihr werdet Trübsal haben zehn Tage lang. Sei getreu bis in den Tod; ich will dir dann den Kranz des Lebens geben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht: \"Der Sieger wird vom zweiten Tode nicht geschädigt werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Dem Engel der Gemeinde in Pergamum schreibe: \"So spricht der, der das zweischneidige und geschärfte Schwert trägt:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Ich weiß, wo du wohnst: dort wo der Thron des Satans steht. Du aber hältst an meinem Namen fest und hast den Glauben an mich nicht verleugnet, auch nicht in den Tagen, da mein treuer Zeuge Antipas bei euch getötet ward, dort, wo der Satan wohnt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Doch ich habe einiges an dir auszusetzen: du hast dort einige, die der Lehre Balaams nachfolgen, der Balak lehrte, den Kindern Israels eine Falle zu stellen, nämlich Götzenopferfleisch zu essen und Unzucht zu treiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Desgleichen hast du solche, die in ähnlicher Weise der Lehre der Nikolaiten folgen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Bekehre dich also! Wenn nicht, dann komme ich gar schnell über dich und werde sie bekämpfen mit dem Schwerte meines Mundes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht: \"Dem Sieger will ich vom verborgenen Manna geben; auch einen weißen Stein will ich ihm geben und, auf dem Stein geschrieben, einen neuen Namen, den niemand kennt als der, der ihn empfängt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Dem Engel der Gemeinde in Thyatira schreibe: \"So spricht der Sohn Gottes, der Augen hat wie loderndes Feuer und dessen Füße glühendem Erz ähnlich sind:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ich kenne deine Werke und deine Liebe und deinen Glauben, deinen Dienst und dein Geduldigsein; deine letzten Werke sind auch besser als die früheren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Doch ich habe an dir auszusetzen, daß du das Weib Jezabel so gewähren lässest, sie, die sich Prophetin nennt und die mit ihren Lehren meine Knechte irreführt, so daß sie Unzucht treiben und Götzenopferfleisch genießen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Ich gab ihr Zeit, sich zu bekehren; doch sie will sich von ihrer Unzucht nicht bekehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Sieh, ich werfe sie aufs Krankenlager und bringe die in große Drangsal, die mit ihr Unzucht treiben, wenn sie sich nicht von ihren Werken bekehren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Und ihre Kinder will ich (durch die Pest) sterben lassen, und alle Gemeinden sollen erkennen, daß ich es bin, der Nieren und Herzen prüft, und daß ich einem jeden aus euch vergelten will nach seinen Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Euch anderen aber in Thyatira, die ihr diese Lehre nicht befolgt, die ihr die \'Tiefen des Satans\', wie sie es heißen, nicht kennengelernt habt, erkläre ich: Ich lege euch keine weitere Last auf;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'nur haltet fest an dem, was ihr schon habt, bis ich komme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Wer sieht und bis ans Ende an meinen Werken festhält, dem will ich Macht verleihen über die Heidenvölker.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Er wird sie mit Eisenzepter leiten, wie Tongeschirre sie zertrümmern,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'wie auch ich es von meinem Vater empfangen habe. Auch will ich ihm den Morgenstern verleihen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Dem Engel der Gemeinde in Sardes schreibe: \"Also spricht, der die sieben Geister Gottes und die sieben Sterne hat: Ich kenne deine Werke; du hast den Namen, daß du lebest, doch du bist tot.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Wach auf und stärke den Rest, der schon im Sterben liegt. Denn ich habe deine Werke vor meinem Gott nicht voll erfunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Erinnere dich, wie du es empfangen und gehört hast. Halte daran fest und ändere deinen Sinn! Doch solltest du nicht aufwachen, so werde ich kommen wie ein Dieb; du sollst nicht wissen, zu welcher Stunde ich über dich kommen werde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Indes hast du einige in Sardes, die ihre Kleider nicht besudelt haben; sie sollen in weißen Kleidern mit mir wandeln, denn sie sind es wert.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Der Sieger wird auf diese Weise mit weißen Kleidern angetan; ich werde seinen Namen niemals aus dem Buche des Lebens löschen; ich werde seinen Namen vielmehr vor meinem Vater und vor seinen Engeln bekennen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Dem Engel der Gemeinde in Philadelphia schreibe: \"So spricht der Heilige, der Wahrhaftige, der den Schlüssel Davids hat, der öffnet, und niemand schließt, der schließt, und niemand öffnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Ich kenne deine Werke; ich habe vor dir eine Tür geöffnet, die niemand schließen kann. Denn du hast nur eine geringe Kraft und hast doch mein Wort bewahrt und meinen Namen nicht verleugnet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Siehe, ich schenke dir solche aus der Synagoge Satans, die sich Juden heißen, ohne es zu sein; sie lügen. Siehe, ich will sie dazu bringen, daß sie kommen und dir zu deinen Füßen huldigen und dann erkennen, daß ich dich liebe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Du hast das Wort vom Harren auf mich bewahrt; darum will auch ich dich bewahren vor der Prüfungsstunde, die über die ganze Welt kommen wird, die Erdbewohner zu prüfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Ich komme bald. Halte fest, was du hast, damit niemand deinen Kranz dir nehme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Den Sieger werde ich zu einer Säule im Tempel meines Gottes machen. Er soll nicht mehr entfernt werden, und ich will den Namen meines Gottes darauf schreiben sowie den Namen meiner Gottesstadt, des neuen Jerusalem, das aus den Himmeln von meinem Gott herniedersteigt, und meinen neuen Namen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Dem Engel der Gemeinde in Laodizea schreibe: \"So spricht der \'Amen\', der treue und wahrhaftige Zeuge, der Anfang der Schöpfung Gottes:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Ich kenne deine Werke und weiß, du bist nicht kalt noch warm. O wärest du doch kalt oder warm!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Weil du aber lau bist und weder kalt noch warm, so will ich dich aus meinem Munde speien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Du magst wohl sagen: Ich bin reich und habe Überfluß; ich brauche nichts. Und du weißt gar nicht, daß du elend bist, erbarmungswürdig, arm und blind und bloß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Ich rate dir, kaufe von mir Gold, in Feuersglut geglüht, damit du reich werdest, und weiße Kleider, auf daß du dich bekleidest und die Schande, das heißt deine Blöße, nicht mehr sichtbar sei, und Salbe, so daß du deine Augen damit salbest, damit du sehend werdest.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ich strafe und züchtige alle, die ich liebe. So sei denn eifrig und ändere deinen Sinn.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Siehe, ich stehe vor der Tür und klopfe an. Wenn jemand meine Stimme hört und mir die Tür öffnet, zu dem gehe ich hinein und halte mit ihm Mahl und er mit mir.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Dem Sieger werde ich verleihen, mit mir auf meinem Thron zu sitzen, wie auch ich nach meinem Siege mich zu meinem Vater auf seinen Thron gesetzt habe.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Wer ein Ohr hat, höre, was der Geist zu den Gemeinden spricht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Dann hatte ich ein Gesicht: Siehe, im Himmel stand eine Tür offen und die Stimme, die ich wie eine Posaune vorhin mit mir hatte reden hören sprach:\"Komm hier herauf; ich will dir zeigen, was hernach geschehen muß.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Sofort ward ich verzückt: Siehe, da stand ein Thron im Himmel, und auf dem Throne saß Einer.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Der dasaß, sah wie Jaspis und wie Sardis aus; ein Regenbogen erstrahlte rings um den Thron herum, der wie ein Smaragd aussah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Und vierundzwanzig andere Throne waren rund um den Thron, und auf den Thronen saßen vierundzwanzig Älteste mit weißen Kleidern angetan und goldenen Kränzen auf ihren Häuptern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Vom Throne gehen Blitze, Tosen, Donnerschläge aus. Sieben Fackeln brannten vor dem Throne; das sind die sieben Geister Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Dann war vor dem Throne noch etwas wie ein gläsernes Meer, ähnlich wie Kristall. Und mitten vor dem Thron und rund um den Thron herum waren vier lebendige Wesen voller Augen vorn und hinten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Das erste Wesen glich einem Löwen, das zweite Wesen glich einem Rind, das dritte Wesen hatte ein Antlitz wie ein Mensch, das vierte Wesen glich einem fliegenden Adler.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Jedes der vier Lebewesen hatte sechs Flügel, außen wie innen voller Augen; sie haben keine Ruhe Tag und Nacht; sie rufen: \"Heilig, heilig, heilig ist Gott, der Herr, der Allbeherrscher, der war, der ist, der kommen wird.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Und sooft die Lebewesen Ruhm und Ehre und Dank dem dargebracht hatten, der auf dem Throne saß, der von Ewigkeit zu Ewigkeiten lebt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'werfen sich die vierundzwanzig Ältesten vor dem, der auf dem Throne saß, zu Boden und beten den an, der lebt von Ewigkeit zu Ewigkeiten; sie legen ihre Kränze vor dem Throne nieder und rufen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '\"Würdig bist Du, unser Herr und Gott, Ruhm, Macht und Ehre zu empfangen; denn Du hast das All erschaffen, durch Deinen Willen wurde es und ist es entstanden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Dann sah ich in der Rechten dessen, der auf dem Throne saß, eine Rolle, beschrieben innen und außen, mit sieben Siegeln versiegelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Auch sah ich einen gewaltigen Engel, der kündete mit lauter Stimme: \"Wer ist würdig, die Rolle zu öffnen und ihre Siegel zu lösen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Doch niemand war im Himmel noch auf Erden noch unterhalb der Erde, der es vermochte, die Rolle zu öffnen oder hineinzusehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Da weinte ich sehr, weil niemand würdig erfunden ward, die Rolle zu öffnen und hineinzusehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Und einer aus den Ältesten sprach zu mir: \"Weine nicht! Siehe, gesiegt hat der Löwe aus dem Stamme Juda, der Davidsprosse: Er wird die Rolle öffnen und ihre Siegel lösen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Da sah ich mitten vor dem Thron und den vier Lebewesen, inmitten jener Ältesten, ein Lamm dastehen wie geschlachtet. Es hatte sieben Hörner und sieben Augen; das sind die sieben Geister Gottes, die in alle Welt ausgesandt sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Es kam heran und empfing aus der Rechten dessen, der auf dem Throne saß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Als es die Rolle empfangen hatte, fielen die vier Lebewesen und die vierundzwanzig Ältesten vor dem Lamme nieder. Ein jeder hatte eine Harfe und goldene Schalen voll Weihrauch: das sind die Gebete der Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Sie sangen ein neues Lied und sprachen: \"Würdig bist Du, die Rolle zu empfangen und ihre Siegel zu lösen Du bist geschlachtet worden. Du hast uns losgekauft in Deinem Blute für Gott aus allen Stämmen, Sprachen, Völkern und Nationen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Du hast sie zu einem Königtum und zu Priestern gemacht für unseren Gott, die auf der Erde herrschen sollen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Ich hatte ein Gesicht: Ich hörte Stimmen vieler Engel rund um den Thron und um die Lebewesen und die Ältesten. Es war zehntausendmal zehntausend und tausendmal tausend ihre Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Mit lauter Stimme riefen sie: \"Würdig ist das Lamm, das geschlachtet ward, Macht, Reichtum, Weisheit, Kraft, Ehre, Herrlichkeit und Lobpreis zu empfangen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Und jedes Geschöpf, das im Himmel und auf der Erde, unterhalb der Erde und auf dem Meere ist, ja alles, was in ihnen ist, hörte ich also sprechen: \"Dem, der auf dem Throne sitzt, und dem Lamme sei Lob und Ehre und Herrlichkeit und Macht von Ewigkeit zu Ewigkeiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Und die vier Lebewesen riefen. \"Amen.\" Dann warfen sich die Ältesten anbetend nieder vor dem, der da lebt von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Ich hatte ein Gesicht: Das Lamm öffnete das erste der sieben Siegel. Da hörte ich das erste der vier Lebewesen donnernd rufen: \"Komm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Ich schaute hin, und siehe, da war ein weißes Roß. Der auf ihm saß, trug einen Bogen; es ward ihm auch ein Kranz gegeben. So zog er als ein Sieger aus, um zu siegen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Als es das zweite Siegel öffnete, hörte ich das zweite Lebewesen rufen: \"Komm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Alsdann erschien ein anderes Roß, rot wie Feuer, und seinem Reiter ward die Macht verliehen, den Frieden von der Erde zu nehmen, damit die Menschen gegenseitig sich abschlachten; auch wurde ihm ein großes Schwert gereicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Und als es dann das dritte Siegel öffnete, hörte ich das dritte Lebewesen rufen: \"Komm!\" Da schaute ich, und siehe, da war ein schwarzes Roß, sein Reiter hatte eine Waage in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Da hörte ich, wie eine Stimme inmitten der vier Lebewesen rief: \"Ein Maß Weizen für einen Denar, und drei Maß Gerste für einen Denar, und Öl und Wein vergeude nicht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Als es das vierte Siegel öffnete, hörte ich die Stimme des vierten Lebewesens rufen: \"Komm!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Da schaute ich, und siehe, da war ein fahles Roß; sein Reiter hieß der Tod, und mit ihm zog die Unterwelt. Es wurde ihnen Gewalt gegeben über den vierten Teil der Erde, zu morden durch Schwert und Hunger, durch Pest und durch die Tiere der Erde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Als es das fünfte Siegel öffnete, sah ich unter dem Altare die Seelen derer, die hingeschlachtet waren des Wortes Gottes und des Zeugnisses wegen, an denen sie festgehalten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Mit lauter Stimme riefen sie und sprachen: \"Wann endlich, o heiliger, wahrhaftiger Herr, wirst Du richten und rächen an den Erdbewohnern unser Blut?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Da wurde jedem aus ihnen ein weißes Gewand gereicht und ihnen zugerufen, sie möchten sich noch kurze Zeit gedulden, bis ihre Mitknechte und ihre Brüder vollzählig geworden seien, die getötet werden sollten, wie sie selber.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Als es das sechste Siegel öffnete, schaute ich, und es entstand ein gewaltiges Beben; die Sonne wurde schwarz gleich einem härenen Trauerkleid, der ganze Mond war wie Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Die Sterne des Himmels fielen auf die Erde, wie der Feigenbaum die Früchte abwirft, wenn ihn ein starker Sturm durchschüttelt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Der Himmel wich zurück wie eine Rolle, die sich zusammenrollt; jeder Berg und jede Insel wurden von ihrer Stelle weggerückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Die Könige der Erde, die Großen und die Obersten, die Reichen und die Mächtigen, jeder Sklave und Freie verbargen sich in Höhlen und in Felsen der Gebirge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Sie riefen den Bergen und den Felsen zu: \"Fallet über uns, verbergt uns vor dem Angesichte dessen, der auf dem Throne sitzt, und vor dem Zorn des Lammes!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Gekommen ist der große Tag ihres Zornes. Wer könnte da bestehen?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Alsdann sah ich vier Engel, die an den vier Ecken der Erde standen; sie hielten die vier Winde der Erde fest, damit nicht ein Wind hinwehe, weder auf die Erde noch auf das Meer noch über einen Baum.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Dann sah ich einen anderen Engel; von Sonnenaufgang stieg er auf, er hielt das Siegel des lebendigen Gottes und rief mit lauter Stimme den vier Engeln zu, die die Gewalt besaßen, die Erde und das Meer zu schädigen:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, '\"Schädigt nicht die Erde noch das Meer und nicht die Bäume, bis wir die Knechte unseres Gottes auf ihrer Stirne versiegelt haben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Ich hörte auch die Zahl der so Versiegelten: Einhundertvierundvierzigtausend Versiegelte aus allen Stämmen Israels:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Aus dem Stamme Juda: zwölftausend Versiegelte, aus dem Stamme Ruben: zwölftausend, aus dem Stamme Gad: zwölftausend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'aus dem Stamme Aser: zwölftausend, aus dem Stamme Nephtali: zwölftausend, aus dem Stamme Manasse: zwölftausend');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'und aus dem Stamme Simeon: zwölftausend, aus dem Stamme Levi: zwölftausend, aus dem Stamme Issachar: zwölftausend,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'aus dem Stamme Zabulon: zwölftausend, aus dem Stamme Joseph: zwölftausend, aus dem Stamme Benjamin: zwölftausend Versiegelte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Dann hatte ich ein Gesicht: Siehe, eine große Schar, die niemand zählen konnte, aus jedem Volk und allen Geschlechtern, aus allen Stämmen und Sprachen. Sie standen vor dem Thron und vor dem Lamme, mit weißen Kleidern angetan und Palmen in den Händen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Mit lauter Stimme riefen sie: \"Heil unserem Gott, der auf dem Throne sitzt, und dem Lamme!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Die Engel alle standen rund um den Thron und um die Ältesten und die vier Lebewesen. Sie fielen vor dem Thron auf ihr Antlitz nieder; sie beteten Gott an');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'und sprachen: \"Amen. Lob, Preis, Weisheit, Dank, Ehre, Macht und Stärke gebühren unserem Gott von Ewigkeit zu Ewigkeiten. Amen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Darauf nahm einer von den Ältesten das Wort und sprach zu mir: \"Die da bekleidet sind mit weißen Kleidern, wer sind sie, und woher kommen Sie?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Ich erwiderte ihm: \"Herr, das weißt nur du!\" Er sprach zu mir: \"Das sind die, die aus der großen Trübsal kommen und ihre Kleider im Blute des Lammes weißgewaschen und gereinigt haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Darum stehen sie vor dem Throne Gottes und dienen ihm in seinem Tempel Tag und Nacht. Der auf dem Throne sitzt, wird unter ihnen sein Zelt aufschlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Und sie werden nicht mehr hungern noch dürsten, noch wird die Sonne auf sie fallen, noch irgendwelche Glut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Das Lamm, das mitten auf dem Throne steht, weidet sie und führt sie zu den Wasserquellen des Lebens, und Gott wird jede Träne von ihren Augen wischen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Als es das siebte Siegel öffnete, ward es still im Himmel, wohl eine halbe Stunde lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Ich sah die sieben Engel, die vor dem Antlitz Gottes stehen; es wurden ihnen sieben Posaunen dargereicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Dann kam ein anderer Engel und trat vor den Altar mit einem goldenen Rauchfaß. Dann gab man ihm viel Räucherwerk, damit er es mit den Gebeten aller Heiligen auf dem goldenen Altar vor dem Throne darbringe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Da stieg der Duft des Räucherwerks auf mit den Gebeten der Heiligen aus der Hand des Engels empor zum Angesichte Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Der Engel nahm sodann das Rauchfaß und füllte es von dem Feuer des Altars und warf es auf die Erde. Da gab es Donnerschläge, Tosen, Blitze, Erdbeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Die sieben Engel mit den sieben Posaunen bereiteten sich dann zum Blasen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Der erste stieß in die Posaune. Da gab es Hagel und Feuer, untermischt mit Blut, und dieses fiel auf die Erde. Der dritte Teil des Landes verbrannte, und es verbrannte auch der dritte Teil der Bäume, und es verbrannte alles grüne Gras.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Der zweite Engel stieß in die Posaune. Da stürzte etwas wie ein großer Berg von Feuer glühend in das Meer hinein. Da ward der dritte Teil des Meeres Blut;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'der dritte Teil der in dem Meere lebenden Geschöpfe starb; der dritte Teil der Schiffe ging zugrunde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Der dritte Engel stieß in die Posaune. Da fiel ein großer Stern vom Himmel, der wie eine Fackel brannte. Er fiel auf den dritten Teil der Flüsse und auf die Wasserquellen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Der Stern heißt \"Wermut\". Der dritte Teil der Wasser ward zu Wermut, und viele Menschen starben an den Wassern; denn bitter waren sie geworden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Der vierte Engel stieß in die Posaune. Da ward der dritte Teil der Sonne geschlagen, der dritte Teil des Mondes und der dritte Teil der Sterne, so daß der dritte Teil von ihnen finster ward und auch der Tag zu einem Drittel nicht mehr hell war, und ebenso die Nacht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Ich schaute, und ich hörte, wie ein Adler hoch oben durch den Himmelsraum dahinflog; er rief mit lauter Stimme: \"Wehe, wehe, wehe den Erdbewohnern ob der übrigen Posaunenstöße der drei Engel, die jetzt noch blasen werden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Der fünfte Engel stieß in die Posaune. Da sah ich einen Stern; der war vom Himmel auf die Erde gefallen. Ihm ward der Schlüssel zum Brunnen des Abgrunds übergeben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Er öffnete den Brunnen des Abgrunds; da stieg Rauch auf aus dem Brunnen, wie der Rauch aus einem großen Ofen, so daß die Sonne und die Luft verfinstert wurden durch den Rauch, der aus dem Brunnen kam.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Und aus dem Rauche kamen Heuschrecken über die Erde hin, und ihnen wurde die Gewalt gegeben, wie sie die Skorpione der Erde haben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Es wurde ihnen aufgegeben, das Gras der Erde nicht zu schädigen, auch nicht das Grün und nicht die Bäume, sondern nur die Menschen, die das Siegel Gottes nicht auf ihrer Stirne tragen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Doch wurde ihnen nicht die Macht verliehen, sie zu töten, vielmehr sie nur zu quälen fünf Monate lang. Und ihre Qual war wie die eines Skorpions, wenn er einen Menschen sticht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'In jenen Tagen suchen die Menschen den Tod, doch sie werden ihn nicht finden; sie werden zu sterben verlangen, und der Tod wird sie fliehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Die Heuschrecken waren Rossen ähnlich, die für den Krieg gerüstet sind; auf ihren Köpfen trugen sie etwas wie goldene Kränze, und ihre Angesichter waren wie Menschenangesichter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Sie hatten Haare wie Frauenhaare, und ihre Zähne waren wie die von Löwen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'sie hatten Panzer von Eisen, und das Geräusch ihrer Flügel war wie das Gerassel vieler Streitwagen, die in den Kampf hineinrasseln.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Sie hatten Schwänze und Stacheln wie Skorpione; in ihren Schwänzen hatten sie die Kraft, den Menschen fünf Monate lang zu schaden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Als König haben sie den Engel des Abgrunds über sich; hebräisch heißt er Abaddon und griechisch Apollyon.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'So ging das erste Weh vorüber; doch siehe, es kommen noch zwei Wehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Der sechste Engel stieß in die Posaune. Da hörte ich eine Stimme von den vier Hörnern am goldenen Altare vor dem Angesichte Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Sie sprach zum sechsten Engel, der die Posaune hielt: \"Laß die vier Engel los, die an dem großen Euphratstrom gebunden sind!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Da wurden die vier Engel losgelassen, die sich bereitgehalten hatten auf Stunde, Tag, Monat und Jahr, den dritten Teil der Menschen hinzumorden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Die Zahl der Reiterscharen war zwanzigtausendmal zehntausend; so hörte ich ihre Zahl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Also sah ich im Gesichte die Rosse und die Reiter. Sie trugen feuerrote, dunkelblaue, schwefelgelbe Panzer; die Köpfe der Rosse waren wie Löwenköpfe, aus ihren Mäulern gingen Feuer, Rauch und Schwefeldampf hervor.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Durch die drei Plagen, durch Feuer, Rauch und Schwefel, die aus ihren Mäulern kamen, ward der dritte Teil der Menschen umgebracht;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'die Kraft der Rosse liegt in ihrem Maul und Schwanze. Die Schwänze glichen nämlich Schlangen mit Köpfen, mit denen sie Schaden stiften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Gleichwohl bekehrte sich der Rest der Menschen, die nicht durch diese Plagen getötet wurden, nicht von den Werken ihrer Hände, so daß sie die Dämonen nicht mehr verehrt hätten, und auch nicht die Götzenbilder aus Gold, Silber, Erz, Stein und Holz, die weder sehen noch hören noch gehen können.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Und sie bekehrten sich nicht von ihrem Morden, von ihren Zaubereien, ihrer Unzucht und ihren Diebereien.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Ich sah einen anderen starken Engel, angetan mit einer Wolke, aus dem Himmel niedersteigen. Hoch über seinem Haupte war ein Regenbogen, sein Angesicht war wie die Sonne, und seine Füße glichen Feuersäulen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'in seiner Hand hielt er ein offenes Büchlein. Er setzte seinen rechten Fuß auf das Meer, den linken auf das Land;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'er schrie mit lauter Stimme, wie wenn ein Löwe brüllt. Und als er schrie, ließen die sieben Donner ihre Stimme hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Und als die sieben Donner verklungen waren, wollte ich schreiben. Doch ich hörte eine Stimme aus dem Himmel, die rief: \"Versiegle, was die sieben Donner gekündet haben, und schreibe es nicht auf!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Und der Engel, den ich auf dem Meere und auf dem Lande stehen sah, erhob seine rechte Hand zum Himmel');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'und schwur bei dem, der lebt von Ewigkeit zu Ewigkeiten, der den Himmel und was in ihm ist, gegründet hat, die Erde und was auf ihr ist, und das Meer und was in ihm ist: \"Es soll keine Frist mehr sein;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'vielmehr in diesen Tagen, da der siebte Engel seine Stimme erschallen läßt und sich anschickt, in die Posaune zu stoßen, ist das Geheimnis Gottes erfüllt, wie er es seinen Knechten, den Propheten, verkündigt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Da sprach die Stimme, die ich aus dem Himmel hatte reden hören, nochmals mit mir und sagte: \"Geh! Nimm das offene Büchlein, das der Engel in der Hand hält, der auf dem Meer und dem Lande steht!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Da ging ich zu dem Engel hin und bat, er möchte mir das Büchlein geben. Er sprach zu mir: \"Nimm und verschlinge es! Es wird dir zwar den Magen bitter machen, doch in deinem Munde wird es süß sein wie Honig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Ich nahm das Büchlein aus der Hand des Engels und verschlang es. Da war es in dem Munde süß wie Honig. Und als ich es verschlungen hatte, ward es in meinem Magen bitter.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Man sagte mir: \"Du mußt noch einmal prophezeien über Völker, Geschlechter, Sprachen und viele Könige.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Da gab man mir ein Rohr, einem Stabe ähnlich, mit den Worten: \"Steh auf und miß den Tempel Gottes und den Altar und die darin anbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Doch den Hof außerhalb des Tempels laß aus und miß ihn nicht! Er ist den Heiden preisgegeben; auf zweiundvierzig Monate zertreten sie die heilige Stadt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Ich aber werde meinen beiden Zeugen es verleihen, daß sie eintausendzweihundertsechzig Tage lang in Bußgewändern prophezeien.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Es sind dies die zwei Ölbäume und die zwei Leuchter, die vor dem Herrn der Erde stehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Wenn irgend jemand ihnen Leid antun wollte, so ginge Feuer aus von ihrem Munde und verzehrte ihre Feinde. Wer ihnen also Leid antun wollte, der müßte auf solche Weise sterben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Sie haben Macht, den Himmel zu verschließen, so daß kein Regen fällt in den Tagen ihrer Predigt; auch haben sie Macht über die Gewässer, sie in Blut zu verwandeln und auch die Erde mit jeder Plage hart zu treffen, sooft sie es nur wollen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Wenn sie ihr Zeugnis vollendet haben, dann wird das Tier, das aus dem Abgrund aufsteigt, mit ihnen Krieg beginnen, sie besiegen und sie töten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Ihre Leichen werden in der großen Stadt auf den Straßen liegen bleiben, die bildlich Sodoma und Ägypten heißt, wo auch ihr Herr gekreuzigt ward.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Menschen aus den Völkern, Stämmen, Sprachen und Geschlechtern werden ihre Leichen drei und einen halben Tag lang sehen; man wird ja ihre Leichen nicht in einem Grabe bergen lassen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Die Erdbewohner werden über sie sich freuen und frohlocken und sich Geschenke senden; denn diese zwei Propheten machten einst den Erdbewohnern Qualen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Doch nach jenen dreieinhalb Tagen fuhr der Geist des Lebens von Gott in sie; sie standen wiederum auf ihren Füßen, und große Furcht befiel jene, die sie sahen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Sie hörten eine mächtige Stimme aus dem Himmel, die ihnen zurief: \"Kommt hier herauf!\" Auf einer Wolke stiegen sie zum Himmel empor, und ihre Feinde schauten ihnen nach.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Zur selben Stunde entstand ein großes Erdbeben; der zehnte Teil der Stadt fiel ein, und siebentausend Menschen wurden bei dem Beben getötet. Da fürchteten sich die anderen und gaben die Ehre dem Gott des Himmels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Das zweite Weh ist vorüber, nun siehe, das dritte Weh kommt schnell.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Der siebte Engel stieß in die Posaune. Da tönten laute Stimmen im Himmel, die sprachen: \"Die Weltherrschaft ist unserem Herrn zuteil geworden und seinem Gesalbten, und er wird jetzt herrschen von Ewigkeit zu Ewigkeiten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Da fielen jene vierundzwanzig Ältesten, die vor Gott auf ihren Thronen sitzen, auf ihr Antlitz nieder; sie beteten Gott an');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'und sprachen: \"Wir danken Dir, Herr, Gott, Du Allbeherrscher, der Du bist und warst, daß Du Deine große Macht an Dich genommen und Dich wieder als König gezeigt hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Die Völker zürnten; da kam Dein Zorn, und so die Zeit, die Abgeschiedenen zu richten und Deinen Knechten ihren Lohn zu geben: den Propheten, den Heiligen, und denen, die Deinen Namen fürchten, den Kleinen und den Großen, und zu verderben, die die Erde so verderben.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Und im Himmel tat sich der Tempel Gottes auf, und es erschien die Lade seines Bundes in seinem Tempel. Es folgten Blitze, Tosen, Donnerschräge, Erdbeben und starker Hagel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Ein großes Zeichen ward am Himmel sichtbar: Ein Weib, bekleidet mit der Sonne, den Mond zu ihren Füßen, auf ihrem Haupt ein Kranz von zwölf Sternen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Sie war gesegneten Leibes und schrie in ihren Wehen und Schmerzen des Gebärens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Und noch ein anderes Zeichen ward am Himmel sichtbar: siehe, ein großer, feuerroter Drache. Er hatte sieben Köpfe und zehn Hörner und auf seinen Köpfen sieben Kronen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Mit seinem Schweife fegte er den dritten Teil der Sterne vom Himmel weg und warf sie auf die Erde. Der Drache stand vor dem Weibe, das gebären sollte, auf daß er ihr das kaum geborene Kind verschlinge.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Und sie gebar ein Kind männlichen Geschlechts, das alle Völker mit Eisenzepter weiden soll. Jedoch ihr Kindlein ward zu Gott und seinem Thron entrückt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Das Weib floh in die Wüste, wo Gott ihr schon eine Stätte bereitet hatte, wo man sie tausendzweihundertsechzig Tage lang ernähren soll.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Und es entstand ein Kampf im Himmel: Michael und seine Engel fingen an, den Drachen zu bekämpfen. Doch auch der Drache und seine Engel kämpften.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Jedoch vermochten sie nicht standzuhalten, und ihres Bleibens war nicht länger mehr im Himmel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Der große Drache ward geworfen, die alte Schlange, die Teufel und Satan heißt und die ganze Welt verführt; er ward auf die Erde geworfen, und mit ihm wurden seine Engel hinabgeworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Dann hörte ich eine mächtige Stimme im Himmel, die sprach: \"Jetzt ist gekommen das Heil, die Macht und Herrschaft unseres Gottes und die Gewalt seines Gesalbten. Denn gestürzt ist der Ankläger unserer Brüder, der sie Tag und Nacht vor unserem Gott anklagte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Sie haben ihn durch das Blut des Lammes überwunden und durch ihr Zeugniswort; sie liebten ja ihr Leben so wenig, daß sie den Tod erlitten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'So freut euch denn, ihr Himmel, und ihr, die ihr darinnen wohnet. Wehe der Erde und dem Meere! Der Teufel ist mit großer Wut zu euch hinabgestiegen, weil er weiß, daß ihm nur kurze Zeit vergönnt ist.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Als sich der Drache auf die Erde geworfen sah, verfolgte er das Weib, die Mutter jenes Knaben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Dem Weibe gab man jedoch die beiden Flügel des großen Adlers, damit sie in die Wüste an ihre Stätte hinflöge, wo sie, vor jener Schlange sicher, nun eine Zeit und zwei Zeiten und eine halbe Zeit ernährt wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Da spie die Schlange aus dem Rachen Wasser nach dem Weibe, einem Strome gleich, damit der Strom sie mit sich reiße.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Jedoch die Erde kam dem Weibe zu Hilfe; die Erde öffnete den Mund und verschlang den Strom, den der Drache aus dem Rachen ausgespien hatte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Da geriet der Drache über das Weib in Zorn, und er ging hin, Krieg zu führen mit ihren anderen Kindern, die die Gebote Gottes halten und das Zeugnis Jesu haben. Und er trat an den Strand des Meeres.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Da sah ich, wie ein Tier emporstieg aus dem Meere. Es hatte zehn Hörner und sieben Köpfe; auf seinen Hörnern waren zehn Kronen, auf seinen Köpfen gotteslästerliche Namen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Das Tier, das ich sah, glich einem Panther; seine Füße waren wie die eines Bären, sein Maul wie ein Löwenmaul. Ihm übertrug der Drache seine Macht und seinen Thron und große Stärke.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Eines seiner Häupter war wie zum Tode getroffen, doch seine Todeswunde heilte wieder. Die ganze Erde lief bewundernd diesem Tiere nach,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'und man betete den Drachen an, weil er die Gewalt dem Tiere überlassen hatte. Und auch das Tier betete man an mit den Worten: \"Wer ist dem Tiere gleich, und wer kann mit ihm streiten?\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Es wurde ihm ein Maul gegeben, das hochtrabende Worte und Lästerungen ausstieß; auch wurde ihm Gewalt verliehen, es zweiundvierzig Monate lang zu tun.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Es öffnete sein Maul zu Lästerungen gegen Gott, um seinen Namen, seine Wohnung und die, die im Himmel wohnen, zu lästern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Auch ward es ihm gestattet, mit den Heiligen Krieg zu führen und sie zu besiegen. Ihm ward Gewalt verliehen über die Stämme, Völker, Sprachen und Nationen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Alle Erdbewohner werden es anbeten, deren Namen seit Grundlegung der Welt nicht ins Lebensbuch des Lammes, das geschlachtet ward, eingetragen sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Wer ein Ohr hat, höre!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Wer in Gefangenschaft geführt hat, geht in Gefangenschaft; wer mit dem Schwerte getötet hat, muß durchs Schwert getötet werden. Hier gilt Geduld sowie der Glaube der Heiligen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Ich sah, wie ein anderes Tier aus dem Lande emporstieg; es hatte zwei Hörner wie ein Widder, doch redete es wie ein Drache.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Es übt die gleiche Macht aus wie das erste Tier unter dessen Augen. Und es bringt die Erde und die Erdbewohner dazu, das erste Tier, dessen Todeswunde geheilt ward, anzubeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Es wirkt große Zeichen; vom Himmel läßt es vor den Augen der Menschen sogar Feuer auf die Erde fallen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Und so verführt es die Erdbewohner durch die Zeichen, die es in der Kraft des Tieres machen durfte. Es forderte die Erdbewohner auf, ein Bild des Tieres anzufertigen, das eine Schwertwunde besaß und doch wieder lebendig wurde.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Auch wurde ihm die Macht gegeben, dem Bilde des Tieres Leben einzuhauchen, so daß sogar das Bild des Tieres redete und alle töten ließ, die das Tierbild nicht anbeten wollten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Auch machte es, daß alle, klein und groß, reich und arm, Freie und Sklaven, ein Zeichen auf der rechten Hand oder auf ihrer Stirne tragen sollten,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'so daß niemand weder kaufen noch verkaufen kann, wenn er nicht das Zeichen trägt: des Tieres Namen oder den Zahlenwert seines Namens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Hier braucht es Weisheit; wer Verstand besitzt, möge die Zahl des Tieres berechnen, es ist eines Menschen Zahl; sie heißt: Sechshundertsechsundsechzig.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Ich hatte ein Gesicht, und siehe, das Lamm stand auf dem Berge Sion und bei ihm hundertundvierundvierzigtausend, die seinen Namen und den Namen seines Vaters auf ihrer Stirne geschrieben trugen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Ich hörte eine Stimme aus dem Himmel, gleichwie das Tosen vieler Wasser und wie das Rollen gewaltiger Donner; die Stimme, die ich hörte, klang wie die von Harfenspielern, die ihre Harfen schlagen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Sie singen vor dem Thron und den vier Lebewesen und vor den Ältesten ein neues Lied. Ihr Lied vermochte niemand zu lernen, ausgenommen die hundertvierundvierzigtausend, die von der Erde erkauft sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Es sind die, die sich mit Weibern nicht befleckt haben; sie sind jungfräulich. Dem Lamme folgen sie, wohin es geht. Sie sind aus der Menschenwelt erkauft als Erstlinge für Gott und für das Lamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'In ihrem Munde ward keine Lüge gefunden; sie sind untadelig vor Gottes Thron.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Da sah ich einen anderen Engel hoch oben durch den Himmelsraum hinfliegen. Er hatte ein ewiges Evangelium, um es den Erdbewohnern zu verkünden, allen Völkern, Stämmen, Sprachen und Nationen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Er rief mit lauter Stimme: \"Fürchtet Gott und gebet ihm die Ehre! Gekommen ist die Stunde, da er richten wird. Betet den an, der Himmel, Erde, Meer und Wasserquellen erschaffen hat!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Ein anderer, zweiter Engel folgte mit dem Rufe: \"Gefallen, gefallen ist Babylon, das große, das alle Völker mit dem Zornwein seiner Unzucht getränkt hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Ein weiterer, dritter Engel folgte ihnen. Er rief mit lauter Stimme: \"Wer das Tier und dessen Bild anbetet und wer sein Zeichen an der Stirne oder an der Hand annimmt,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'der muß auch vom Zornwein Gottes trinken, der ungemischt im Becher seines Zornes bereitet ist; er wird gequält mit Feuer und mit Schwefel vor den heiligen Engeln und dem Lamme.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Der Rauch von ihren Qualen wird aufsteigen von Ewigkeit zu Ewigkeiten. Bei Tag und Nacht werden die keine Ruhe haben, die das Tier und dessen Bild angebetet haben und wer das Zeichen seines Namens angenommen hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Hier zeigt sich die Geduld der Heiligen, die an den Geboten Gottes und am Glauben an Jesus festhalten.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Da hörte ich eine Stimme aus dem Himmel, die sprach: \"Schreibe: Selig die Toten, die schon jetzt im Herrn sterben. Fürwahr, so spricht der Geist, sie sollen ruhen von ihren Mühen; denn ihre Werke folgen ihnen nach.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Ich hatte ein Gesicht, und siehe, es zeigte sich eine lichte Wolke, und auf der Wolke saß einer wie ein Menschensohn. Auf seinem Haupte trug er einen goldenen Kranz und eine scharfe Sichel in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Da kam ein anderer Engel aus dem Tempel her und rief mit lauter Stimme dem zu, der auf der Wolke saß: \"Strecke deine Sichel aus und ernte! Gekommen ist die Stunde der Ernte; das Getreide auf der Erde ist überreif.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Da warf der, der auf der Wolke saß, die Sichel auf die Erde, und also ward die Erde abgeerntet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Da ging ein anderer Engel vom Tempel im Himmel aus, gleichfalls mit einer scharfen Sichel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Ein weiterer Engel ging vom Altare aus: Er hatte Gewalt über das Feuer. Mit lauter Stimme rief er dem mit der scharfen Sichel zu: \"Strecke deine scharfe Sichel aus und schneide die Trauben vom Weinstock der Erde ab; denn seine Beeren sind reif!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Da warf der Engel seine Sichel auf die Erde und erntete den Weinstock der Erde ab und warf die Trauben in die Kelter des großen Zornes Gottes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Die Kelter wurde außerhalb der Stadt getreten, und Blut floß aus der Kelter bis an die Zügel der Pferde, etwa eintausendsechshundert Stadien weit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Ich sah ein anderes Zeichen am Himmel, groß und wunderbar. Sieben Engel mit den sieben letzten Plagen, durch die der Zorn Gottes zur Vollendung kommen sollte.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Ich sah da etwas wie ein gläsernes Meer, gemischt mit Feuer, und wie die Sieger über jenes Tier und dessen Bild und seines Namens Zahl auf dem gläsernen Meere mit Gottesharfen standen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Sie singen das Lied des Gottesknechtes Moses und das Lied des Lammes: \"Groß und wunderbar sind Deine Werke, Herr, Gott, Du Allbeherrscher. Gerecht sind Deine Wege und wahrhaftig, Du Völkerkönig!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Wer sollte, Herr, nicht Deinen Namen fürchten und ihn preisen? Denn Du allein bist heilig. Alle Völker werden kommen und sich vor Dir anbetend niederwerfen; es sind ja Deine so gerechten Taten offenbar geworden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Dann hatte ich noch ein Gesicht: Im Himmel tat der Tempel mit dem Bundeszelt sich auf,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'und aus dem Tempel traten jene sieben Engel mit den sieben Plagen, mit glänzend reinem Linnen angetan, mit goldenen Gürteln über ihrer Brust gegürtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Und eines der vier Lebewesen gab den sieben Engeln sieben goldene Schalen, voll mit dem Zorne Gottes, der lebt von Ewigkeit zu Ewigkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Da ward der Tempel voll Rauch von Gottes Macht und Herrlichkeit, und niemand konnte in den Tempel hineingehen, bis die sieben Plagen der sieben Engel vollzogen waren.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Ich hörte eine laute Stimme, die aus dem Tempel zu den sieben Engeln sprach: \"Geht hin und gießt die sieben Schalen voll des Zornes Gottes auf die Erde aus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Der erste ging hin und goß seine Schale auf das Land. Da kam ein schlimmes und bösartiges Geschwür an die Menschen, die das Zeichen des Tieres tragen und sein Bild anbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Der zweite goß seine Schale auf das Meer; und dieses ward zu Blut wie von einem Toten, und jedes Lebewesen im Meere starb.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Der dritte goß seine Schale auf die Flüsse und in die Wasserquellen aus. Da wurden sie zu Blut.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Da hörte ich den Engel der Gewässer sagen: \"Gerecht bist Du, der Du bist und warst, Heiliger, daß Du also gerichtet hast.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Das Blut von Heiligen und von Propheten haben sie vergossen; dafür gabst Du nun ihnen Blut zu trinken; sie haben es verdient.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Und ich hörte vom Altar her rufen: \"Ja, Herr, Gott, Du Allbeherrscher, wahrhaftig und gerecht sind Deine Gerichte.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Der vierte goß seine Schale auf die Sonne aus; da wurde ihr die Kraft verliehen, die Menschen mit Feuer zu versengen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Und es wurden die Menschen von großer Glut versengt; jedoch sie lästerten den Namen Gottes, der Macht über solche Plagen hat. Somit bekehrten sie sich nicht, daß sie ihm Ehre erwiesen hätten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Der fünfte goß seine Schale auf den Thron des Tieres. Und verfinstert ward sein Reich. Sie zerrissen sich ihre Zungen vor Schmerz;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'jedoch sie lästerten den Gott des Himmels ob ihrer Schmerzen und Geschwüre, und sie bekehrten sich nicht von ihren Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Der sechste goß seine Schale auf den großen Euphratstrom. Da vertrocknete sein Wasser, damit der Weg bereitet würde für die Könige des Ostens.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Ich sah, wie aus dem Maule des falschen Propheten drei unreine Geister ausgingen, wie Frösche.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Das sind Dämonengeister, die Zeichen tun, die zu den Königen der ganzen Erde gehen, um diese für den Kampf zu sammeln am großen Tage Gottes, des Allbeherrschers.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '\"Siehe, ich komme wie ein Dieb.\" Selig, der wacht und seine Kleider bereithält, damit er nicht nackt zu gehen braucht und man seine Blöße sehe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Sie sammeln sich an einem Orte, der auf hebräisch Harmagedon heißt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Der siebte Engel goß seine Schale in die Luft. Und aus dem Tempel vom Throne her kam eine laute Stimme, die rief: \"Es ist geschehen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Nun folgten Blitze, Tosen, Donnerschläge, ein Beben, wie noch keines war, seitdem auf Erden Menschen leben; so furchtbar war dieses große Beben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Die große Stadt fiel in drei Teile auseinander; die Städte der Heiden stürzten ein. So ward vor Gott des großen Babylons gedacht und ihm der Becher seines grimmen Zornweins dargereicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Jede Insel schwand, und Berge waren nicht zu sehen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'gewaltiger Hagel, zentnerschwer, fiel vom Himmel auf die Menschen nieder. Die Menschen aber lästerten Gott ob dieser Hagelplage; denn übergroß ist diese Plage.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Darauf kam einer jener sieben Engel mit den sieben Schalen und sprach zu mir: \"Komm her, ich will dir das Gericht über die große Hure zeigen, die an den großen Wassern sitzt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Die Könige der Erde trieben mit ihr Hurerei; die Erdbewohner wurden trunken vom Wein ihrer Unzucht.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Dann brachte er mich in der Verzückung in eine Wüste. Ich sah ein Weib auf einem scharlachroten Tiere sitzen, voll von gotteslästerlichen Namen, mit sieben Köpfen und mit zehn Hörnern.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Gekleidet war das Weib in Purpur und in Scharlachrot, mit Gold und Edelsteinen und mit Perlen reich geschmückt. In seiner Hand hielt es einen goldenen Becher, strotzend von Greuel und vom Schmutze seiner Unzucht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Auf seiner Stirne war ein geheimnisvoller Name eingeschrieben: \"Das große Babylon, die Mutter der Unzüchtigen und der Greueltaten auf der Erde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Ich sah das Weib, trunken vom Blute der Heiligen und von dem Blute der Zeugen Jesu. Ich wunderte mich sehr, als ich sie sah.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Da sprach der Engel zu mir: \"Was wunderst du dich? Ich will dir das Geheimnis des Weibes künden und des Tieres, das sie trägt, das sieben Köpfe und zehn Hörner hat:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Das Tier, das du gesehen hast, war und ist nicht. Es wird gleich aus dem Abgrund steigen und ins Verderben fahren. Staunen werden die Erdbewohner, deren Namen nicht im Buche des Lebens stehen seit Grundlegung der Welt, wenn sie das Tier sehen, das war und nicht ist und wieder da sein wird.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Hier gilt Verstand und Weisheit. Die sieben Köpfe sind sieben Berge, auf denen das Weib sich niederließ; auch sind es sieben Könige.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Fünf von ihnen sind gefallen; der eine ist noch da; noch nicht gekommen ist der andere, und wenn er kommt, darf er nur eine kurze Spanne bleiben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Das Tier, das war und nicht mehr ist, das ist der achte. Er gehört zu den sieben, geht aber ins Verderben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Die zehn Hörner, die du sahst, sind zehn Könige; die Herrschaft haben sie noch nicht erlangt, jedoch erhalten sie zusammen mit dem Tiere die Gewalt wie Könige eine Stunde lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Sie sind eines Sinnes und geben ihre Macht und ihre Kraft dem Tiere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Sie werden das Lamm bekämpfen, jedoch das Lamm wird sie besiegen - es ist ja der Herr der Herren und König aller Könige - und mit ihm die Berufenen, Auserwählten und Getreuen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Er sprach zu mir weiter: \"Die Wasser, die du sahest, wo die Hure wohnt, bedeuten Völker, Stämme, Nationen, Sprachen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Die zehn Hörner, die du sahst, und das Tier werden die Hure hassen und sie verwüsten und nackend machen; sie werden ihr Fleisch verzehren und sie im Feuer verbrennen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Denn Gott gab ihnen ins Herz, zu vollziehen, was er beschlossen, einmütig zu handeln und ihre Macht dem Tiere zu übertragen, bis die Worte Gottes vollendet sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Und das Weib, das du gesehen hast, ist die große Stadt, die die Herrschaft hat über die Könige der Erde.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Dann sah ich einen anderen Engel aus dem Himmel niedersteigen. Er hatte große Macht; die Erde ward von seiner Herrlichkeit erleuchtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Er rief mit starker Stimme: \"Gefallen, gefallen ist das große Babylon; es ist zur Behausung von Dämonen geworden, zum Schlupfwinkel unreiner Geister aller Art, zum Unterschlupf aller unreinen und wüsten Vögel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Denn vom Zornwein ihrer Unzucht tranken alle Völker, die Könige der Erde trieben mit ihr Hurerei, die Kaufleute der Erde wurden reich an ihrer übergroßen Üppigkeit.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Da hörte ich eine andere Stimme aus dem Himmel rufen: \"Geht aus ihr heraus, mein Volk, damit ihr nicht an ihrer Sünde teilhabt und nicht Teil bekommt an ihrer Strafe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Denn ihre Sünden reichten bis zum Himmel, und Gott gedachte ihrer Freveltaten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Vergeltet ihr so, wie auch sie vergalt, und zahlt es ihr nach ihren Werken doppelt heim! Den Becher, den sie eingeschenkt, schenkt ihr nun zweimal ein!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Wie sie geprunkt hat und geschwelgt, so fügt ihr Qual und Trauer zu! Spricht sie doch in ihrem Herzen: \"Ich sitze hier als Königin, ich bin keine Witwe, kenne keine Trauer.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Deshalb werden an einem Tag ihre Plagen kommen: Tod, Trauer, Hunger; im Feuer wird sie verbrannt werden; denn mächtig ist der Herr, Gott, der sie richtet.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Die Könige der Erde, die mit ihr buhlend schwelgten, weinen und wehklagen über sie, wenn sie den Rauch von ihrem Brande schauen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Von ferne stehen sie aus Furcht vor ihrer Qual und rufen: \"Wehe, wehe, du große Stadt, Babylon, du starke Stadt! Denn in einer einzigen Stunde ist das Gericht über dich gekommen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Die Kaufleute der Erde werden um sie weinend trauern; denn ihre Waren kauft jetzt niemand mehr:');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'die Gold- und Silberwaren, Edelsteine, Perlen, Linnen, Purpur, Seide, Scharlach, allerlei wohlriechendes Holz und all die elfenbeinernen Geräte, die Geräte aus kostbarem Holz, aus Erz, Eisen und Marmor,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'ferner Zimt, Balsam, Räucherwerk, Myrrhe, Weihrauch, Wein, Öl, Feinmehl, Weizen, Hornvieh, Schafe, Pferde, Wagen, Menschenleiber, Menschenseelen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Das Obst, die Freude deines Herzens, ist dir entschwunden, und aller Glanz und Flitter ist für dich verloren und nimmermehr zu finden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Die mit diesen Dingen Handel trieben und sich an ihr bereicherten, sie werden ferne stehen, aus Furcht vor ihrer Qual. Sie werden weinend, wehklagend');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'rufen: \"Wehe, wehe, du große Stadt! In Linnen, Purpur und in Scharlachrot gelkleidet, reich geschmückt mit Gold und Edelsteinen und Perlen;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'in einer einzigen Stunde ist vernichtet dieser ganze Reichtum. Ein jeder Steuermann und Küstenfahrer, ein jeder Schiffer und wer sonst noch auf dem Meere arbeitet, sie stehen fern');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'und rufen, wenn sie den Rauch von ihrem Brande sehen: \"Wer ist dieser großen Stadt doch ähnlich!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Sie streuten Staub auf ihre Häupter und schrien weinend, weheklagend: \"Wehe, wehe, du große Stadt! Alle, die Schiffe auf dem Meer besaßen, sind an deinem Wohlstand in dir reich geworden. In einer einzigen Stunde wurde sie vernichtet.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, '\"Frohlocke über sie, du Himmel, ihr Heiligen, ihr Apostel und Propheten! Denn Gott hat eure Verurteilung an ihr gerächt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Da hob ein starker Engel einen Stein empor, groß wie ein Mühlstein, und warf ihn in das Meer und sprach. \"Mit gleicher Wucht wird Babylon, die große Stadt, gestürzt und dann nicht mehr zu finden sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Von Harfenspielern, Musikern, Flöten- und Posaunenbläsern soll nimmermehr ein Ton in dir vernommen werden, kein Handwerker irgendeines Handwerks soll jemals wiederum in dir zu finden sein, und kein Geräusch der Mühle wird man jemals wieder in dir hören.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Kein Lampenlicht soll jemals wieder in dir scheinen, und keine Stimme von Bräutigam und Braut jemals in dir vernommen werden. Deine Händler waren ja die Großen dieser Erde, durch deine Zauberkünste wurden alle Völker irregeführt;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'in ihr fand sich auch das Blut der Propheten und der Heiligen, ja aller, die auf Erden hingemordet wurden.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Darauf vernahm ich ein lautes Rufen einer großen Schar, die im Himmel rief: \"Alleluja! Das Heil, die Herrlichkeit und Macht gehören unserem Gott.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Wahrhaftig und gerecht sind seine Gerichte. Er hat die große Hure gerichtet, die die Erde mit ihrer Hurerei verdorben hat; gerächt hat er das Blut seiner Knechte, das sie vergossen hat.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Nochmals rufen sie: \"Alleluja! Ihr Rauch steigt auf von Ewigkeit zu Ewigkeiten!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Da fielen jene vierundzwanzig Ältesten und die vier Lebewesen nieder; sie beteten Gott an, der auf dem Throne saß, und sprachen: \"Amen! Alleluja!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Und vom Throne ging eine Stimme aus, die sprach: \"Lobt unseren Gott, ihr alle seine Knechte, die ihr ihn fürchtet, ihr Kleinen und die Großen!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Da hörte ich etwas wie das Rufen einer großen Menge und wie das Tosen vieler Wasser und wie das Rollen fürchterlicher Donner; sie riefen: \"Alleluja! König ward unser Herr und Gott, der Allbeherrscher.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Laßt uns frohlocken und uns freuen und ihm die Ehre geben. Gekommen ist die Hochzeit des Lammes, und seine Braut hat sich bereit gemacht;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'sie durfte sich in glänzend reines Linnen kleiden.\" Das Linnen deutet auf die gerechten Werke der Heiligen hin.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Alsdann sprach er zu mir: \"Schreibe: Selig, die zu dem Hochzeitsmahl des Lammes geladen sind.\" Er fügt noch hinzu. \"Das sind die wahren Worte Gottes.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Da fiel ich ihm zu Füßen nieder, ihn anzubeten. Er aber sprach zu mir: \"Tu es nicht; ich bin ja nur dein Mitknecht und der deiner Brüder, die das Zeugnis Jesu haben. Gott bete an!\" Das Zeugnis Jesu ist der Geist der Weissagung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Ich sah den Himmel offen, und siehe, da war ein weißes Roß. Sein Reiter heißt \"der Treue und Wahrhaftige\"; er richtet und streitet in Gerechtigkeit.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Seine Augen sind loderndes Feuer; auf seinem Haupte waren viele Kronen; er hatte einen Namen darauf geschrieben, den niemand kennt als er allein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Er war mit einem blutgetränkten Mantel angetan. Sein Name ist \"Das Wort Gottes\".');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Auf weißen Rossen folgten ihm die Scharen des Himmels, mit glänzend weißen Linnen angetan.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Aus seinem Munde geht ein scharfes Schwert hervor, damit er mit ihm die Völker schlage. Er selbst wird sie mit Eisenzepter weiden, und er selbst wird die Kelter des Zornweins Gottes, des Allbeherrschers, treten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Auf seinem Mantel, und zwar an der Hüfte, trug er den Namen angeschrieben: \"König der Könige und Herr der Herren.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Dann sah ich einen Engel in der Sonne stehen; er rief mit lauter Stimme allen Vögeln zu, die durch den Himmelsraum hoch oben hinfliegen: \"Kommt, sammelt euch zum großen Gottesmahl!');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Ihr sollt Fleisch von Königen fressen, Fleisch von Heerführern und Mächtigen, Fleisch von Rossen und von ihren Reitern, Fleisch von allen Freien und von Sklaven, der Kleinen und der Großen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Ich sah das Tier, die Könige der Erde und ihre Heere versammelt, um Krieg zu führen mit dem Reiter und mit seinem Heere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Da ward das Tier und der Prophet der Lüge, der bei ihm war, gefangen - es ist derselbe, der in seiner Kraft die Wunderzeichen tat, durch die er die verführte, die das Zeichen des Tieres an sich trugen und dessen Bild anbeteten -; lebendig wurden beide in den Feuerpfuhl geworfen, der von Schwefel brennt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Die anderen wurden getötet durch das Schwert des Reiters auf dem Rosse, das aus seinem Munde hervorgeht. Und all die Vögel sättigten sich an ihrem Fleische.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Da sah ich einen Engel aus dem Himmel niedersteigen. Er trug den Schlüssel des Abgrunds und eine große Kette in der Hand.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Er überwältigte den Drachen, die alte Schlange, die der Teufel und der Satan ist, und legte ihn in Fesseln tausend Jahre lang.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Er warf ihn in den Abgrund, schloß diesen zu und siegelte darüber, damit er nicht die Völker fernerhin verführe, bis die tausend Jahre vorüber wären. Alsdann muß er für kurze Zeit losgelassen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Dann sah ich Throne; man setzte sich darauf, und das Gericht ward ihnen übergeben. Dann sah ich auch die Seelen derer, die hingerichtet worden waren, weil sie für Jesus Zeugnis abgelegt hatten und um des Wortes Gottes willen; sie, die das Tier und dessen Bild nicht angebetet und sein Siegel weder auf der Stirne noch an der Hand getragen hatten. Sie wurden lebendig und herrschen nun mit Christus tausend Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Die anderen Toten aber werden nicht lebendig, bevor die tausend Jahre nicht vorüber sind.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Das ist die erste Auferstehung. Selig und heilig, wer an der ersten Auferstehung teilhat. Der zweite Tod hat über sie nicht mehr Gewalt, sie werden Priester Gottes und des Christus sein und mit ihm herrschen tausend Jahre.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Wenn aber die tausend Jahre vorüber sind, wird Satan aus seinem Kerker losgelassen werden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Er wird dann ausziehen, die Völker an den vier Enden der Erde, Gog und Magog, zu verführen und sie zum Kampfe zu sammeln. Ihre Zahl ist wie der Sand am Meere.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Sie stiegen zu der Oberfläche der Erde, umzingelten das Lager der Heiligen und die vielgeliebte Stadt. Doch Feuer fiel von Gott vom Himmel nieder und verzehrte sie.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Der Teufel, der sie verführte, ward in den Pfuhl von Feuer und Schwefel geworfen, wo auch das Tier und der Prophet der Lüge sind. Dort werden sie nun Tag und Nacht gequält von Ewigkeit zu Ewigkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Dann sah ich einen großen, lichten Thron und den, der auf ihm saß. Vor seinem Angesichte flohen Erde und Himmel, und ihre Stätte ward nicht mehr gefunden.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Ich sah sodann die Toten, groß und klein, wie sie vor dem Throne standen; es wurden Bücher aufgeschlagen. Und noch ein Buch ward aufgeschlagen; es ist das Buch des Lebens. Die Toten wurden gerichtet, wie es in den Büchern aufgeschrieben ist, entsprechend ihren Werken.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Das Meer gab die Toten wieder, die darin waren, und auch der Tod sowie die Unterwelt gaben ihre Toten wieder her, die darin waren. Ein jeder ward nach seinen Werken abgeurteilt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Tod und Unterwelt wurden in den Feuerpfuhl geworfen; dies ist der zweite Tod: der Feuerpfuhl.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Auch wen man nicht im Buche des Lebens aufgezeichnet fand, der wurde in den Feuerpfuhl geworfen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Dann sah ich einen neuen Himmel und eine neue Erde. Der erste Himmel und die erste Erde waren vergangen, und auch das Meer ist nicht mehr.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Dann schaute ich die heilige Stadt, das neue Jerusalem, wie es von Gott, vom Himmel niederstieg, ausgestattet wie eine Braut, die sich für ihren Bräutigam geschmückt hat.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Vom Throne her hörte ich eine laute Stimme rufen: \"Siehe, das Gezelt Gottes bei den Menschen; er wird unter ihnen wohnen, sie werden seine Völker sein, und er, Gott selber, wird bei ihnen sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Er wird jede Träne aus ihren Augen wischen; der Tod wird nicht mehr sein, noch Trauer noch Klage noch Mühsal wird sein; das Frühere ist ja vorüber.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Der auf dem Throne saß, sprach: \"Siehe, ich mache alles neu!\" Er fügte noch hinzu: \"Schreibe! Diese Worte sind wahr und zuverlässig.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Dann sagte er: \"Es ist geschehen. Ich bin das Alpha und das Omega, der Anfang und das Ende. Ich will aus dem Borne des Lebenswassers dem Dürstenden umsonst zu trinken geben.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Wer siegt, soll dieses erben: Ich will ihm Gott sein, er soll mir Sohn sein.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Die Feigen aber und die Ungläubigen, die Frevler, Mörder, Unkeuschen, die Zauberer, die Götzendiener und alle Lügner erhalten ihren Anteil in dem Pfuhle, der von Feuer und Schwefel brennt. Das ist der zweite Tod.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Da kam einer von den sieben Engeln mit den sieben Schalen, angefüllt mit den sieben letzten Plagen, und sprach zu mir: \"Komm, ich will dir die Braut und Gattin des Lammes zeigen.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Da trug er mich in der Verzückung auf einen großen, hohen Berg und zeigte mir die heilige Stadt Jerusalem, wie sie aus dem Himmel von Gott herniederkam');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'in Gottes Herrlichkeit. Ihr Glanz war wie der kostbarste Edelstein, wie ein kristallheller Jaspis.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Sie hatte eine große, hohe Mauer, zwölf Tore und auf den Toren zwölf Engel und Namen darauf geschrieben: die Namen der zwölf Stämme Israels.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Im Osten waren drei Tore, im Norden drei Tore, im Süden drei Tore, im Westen drei Tore.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Die Stadtmauer hatte zwölf Grundsteine, auf denen die zwölf Namen der zwölf Apostel des Lammes geschrieben standen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Der mit mir redete, hatte ein goldenes Meßrohr, um die Stadt, ihre Tore und ihre Mauer auszumessen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Die Stadt ist in einem Viereck angelegt, so lang wie breit. Und er maß mit dem Rohre die Stadt: zwölftausend Stadien; die Länge, Breite, Höhe sind bei ihr ganz gleich.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Er maß auch ihre Mauer: einhundertvierundvierzig Ellen nach dem Maß der Menschen, das auch das der Engel ist.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Die Mauer ist aus Jaspis aufgebaut; die Stadt jedoch ist reines Gold, so rein wie Glas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Die Grundsteine der Stadtmauer trugen Schmuck aus verschiedenen Edelsteinen: Der erste Grundstein war ein Jaspis, der zweite ein Saphir, der dritte ein Chalzedon, der vierte ein Smaragd,');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'der fünfte ein Sardonyx, der sechste ein Sardis, der siebente ein Chrysolith, der achte ein Beryll, der neunte ein Topas, der zehnte ein Chrysopras, der elfte ein Hyazinth, der zwölfte ein Amethyst.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Und die zwölf Tore waren aus zwölf Perlen; ein jedes Tor bestand aus einer einzigen Perle. Die Straßen in der Stadt waren aus reinem Golde, wie durchsichtiges Glas.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Doch einen Tempel sah ich nicht darin; denn Gott, der Herr, der Allbeherrscher, sowie das Lamm ist ihr Tempel.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Die Stadt braucht auch nicht die Sonne noch den Mond, damit sie in ihr scheinen; denn die Herrlichkeit Gottes erhellt sie, und ihre Leuchte ist das Lamm.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'In ihrem Lichte werden die Völker wandeln; die Könige der Erde werden ihre Herrlichkeit ihr bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Auch werden ihre Tore tagsüber nie geschlossen werden; denn Nacht gibt es dort nicht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Man wird die Herrlichkeit und den Reichtum der Völker in sie bringen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Etwas Gemeines aber wird nicht in sie eingehen, auch nicht, wer Greuel und Lüge tut; nur wer eingetragen ist im Lebensbuch des Lammes.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Dann zeigte er mir einen Strom lebendigen Wassers, klar wie Kristall; er floß vom Throne Gottes und des Lammes aus.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Und mitten auf der Straße, zu beiden Seiten des Stromes, stand der Baum des Lebens, der zwölfmal Früchte trägt; in jedem Monat bringt er seine Frucht. Die Blätter des Baumes aber dienen den Völkern zur Heilung.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Verfluchtes wird es nicht mehr geben. Der Thron Gottes und der des Lammes wird in ihr sein, und seine Knechte werden ihn anbeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Sie schauen sein Angesicht und sein Name steht auf ihrer Stirne.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Nacht gibt es keine mehr; sie brauchen weder Fackellicht noch Sonnenschein; denn Gott, der Herr, ist selbst ihr Licht, und herrschen werden sie von Ewigkeit zu Ewigkeiten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Er sprach zu mir: \"Diese Worte sind wahr und zuverlässig. Der Herr, der Gott der Prophetengeister, sandte seinen Engel, um seinen Knechten anzuzeigen, was bald geschehen muß.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Siehe, ich komme bald. Selig, wer die Prophezeiungsworte dieses Buches bewahrt.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Ich, Johannes, bin es, der dies gehört und geschaut hat. Sobald ich es gehört und geschaut hatte, fiel ich dem Engel, der mir dies gezeigt hatte, zu Füßen, ihn anzubeten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Er aber sprach zu mir: \"Tu es nicht! Ich bin ja nur dein und deiner Brüder, der Propheten, Mitknecht, und auch derer, die auf die Worte dieses Buches achten. Gott bete an!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Und weiter sagte er zu mir: \"Versiegle nicht die Prophezeiungsworte dieses Buches! Denn die Zeit ist nahe.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Der Ungerechte soll weiter Unrecht tun, der Unreine sich noch weiter beschmutzen; der Gerechte soll weiterhin recht handeln, der Heilige werde noch weiter geheiligt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Siehe, ich komme bald, und mit mir kommt mein Lohn, um einem jeden nach seinen Werken zu vergelten.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ich bin das Alpha und das Omega, der Erste und der Letzte, der Anfang und das Ende.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Selig, die ihre Kleider waschen im Blute des Lammes, damit ihr Anrecht auf den Baum des Lebens bleibe und sie durch die Tore in die Stadt eingehen.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Hinaus jedoch die Hunde, Zauberer, Unkeuschen, die Mörder, Götzendiener und jeder, der Lüge liebt und übt.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ich, Jesus, sandte meinen Engel, euch dies über die Gemeinden zu bezeugen. Ich bin die Wurzel und der Stamm Davids, der glänzende Morgenstem.\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Der Geist und die Braut sprechen: \'Komm!\' Wer hört, der spreche: \'Komm!\' Wer dürstet, möge kommen. Wer will, empfange umsonst lebendiges Wasser.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Ich bezeuge jedem, der die Prophezeiungsworte dieses Buches hört: Wer etwas noch hinzufügt, dem wird Gott die Plagen hinzufügen, die in diesem Buch aufgezeichnet sind;');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'wer etwas von den Weissagungen dieses Buches wegnimmt, dem wird Gott seinen Anteil hinwegnehmen am Baume des Lebens, wie auch an der heiligen Stadt, von der in diesem Buche geschrieben steht.');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Der dies bezeugt, spricht: \"Ja, ich komme bald.\" \"Amen. Komm, Herr Jesus!\"');
INSERT INTO `GerGruenewald_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Die Gnade des Herrn Jesus sei mit allen Heiligen. Amen.');
